-- Canonical translations, consolidated with the existing winning values.
local _, addonTable = ...

local quest_alliance = {
    [1001] = { [1] = "Дзижчатор 411", [2] = "Тоненький голос потріскує з глибин машини.\n\n\"Бацбах на зв'язку! Наступний Дзижчатор знаходиться на північ від Аубердіна, на пляжі\n\nОтож, ця машина під номером 411, і їй потрібні 3 ока молотників для ремонту. Вони прямо біля берега! Молотники Темнобережжя... *Гик*... Вибач за це...\n\nЯк і минулого разу, коли ти помістиш в нього все необхідне, він видасть твою винагороду. *Ги-ик*... Га? Ні, я в порядку!\"", [3] = "Зберіть 3 ока молотників Темнобережжя, що водяться у водах поблизу Дзижчатору 411.", [4] = "Люк машини відчинений і, здається, очікує, коли в нього помістять 3 ока молотника.", [5] = "Дзижчатор починає гудіти, щойно ви поміщаєте всередину очі молотників. Після коротких перешкод, ви чуєте знайомий тоненький голосок.\n\n\"Вино з повзунів — просто щось...\" *Гик!*\n\n\"Що? О, ти вже {стать:полагодив:полагодила} його? Ого, ти {стать:шустрий:шустра}. То ш-шо, хоч полагодити ще?\"\n\nЗдається, ви чуєте, як рідина ллється в кружку, а після цього — гучні ковтки.", ["en"] = "Buzzbox 411", ["tasks"] = { ["Thresher Eye"] = "око молотника", ["Thresher Eye (Provided)"] = "око молотника (видано)" } },
    [1002] = { [1] = "Дзижчатор 323", [2] = "Дзижчатор видає сплеск статичних перешкод, і ви чуєте голос Бацбаха.\n\n\"Наступний Дзижчатор — номер 323. Це на північ від Аубердіну, але... де ель? Шо? А, він стоїть на дорозі, тож ти без проблем знайдеш його, десь біля мосту\".\n\nБацбах бурмоче щось незв'язне, перш ніж ви чуєте гучний ковток.\n\n\"Цьому знадобляться ікла місяцескрада... ш-ш-шість штук.\"", [3] = "Зберіть 6 ікл місяцескрадів та помістіть їх в Дзижчатор 323.", [4] = "Хоча ви ще не помістили ікла місяцескрадів всередину, вам здається, що зсередини лунають звуки перешкод і незв'язного гном'ячого бурмотіння. Можливо, хтось вже полагодив цю машину?", [5] = "Несподівано Дзижчатор починає працювати, і ви чуєте, як ікла перемелюються усередині машини на борошно.\n\n\"Шо, ти {стать:зробив:зробила} ц-це! Ч-ч-чудово... Ш-шо ж... Ч-чом б тобі...*Гик!* ...не піти далі? А? Хочеш ш-ще попрацювати?\"", ["en"] = "Buzzbox 323", ["tasks"] = { ["Moonstalker Fang"] = "ікло місяцескрада", ["Moonstalker Fang (Provided)"] = "ікло місяцескрада (видано)" } },
    [101] = { [1] = "Тотем шкоди", [2] = "По лісі розповзається псування, {ім'я}, і всі ми змушені подбати про самозахист. Вітри шепочуть мені, і вони говорять про велику небезпеку, яка чекає на тебе у найближчому майбутньому.\n\nЯкщо ти бажаєш захистити себе, {стать:благородний:благородна} {клас:н}, принеси мені 10 ікл гуля, 10 пальців скелета і 5 флаконів павучої отрути. Тоді я створю тотем шкоди, який буде завдавати шкоди тим, хто спробує напасти на тебе.", [3] = "Принесіть 10 ікл гуля, 10 пальців скелета і 5 флаконів павучої отрути мадам Єві в Темноділ.", [4] = "Принеси мені 10 ікл гуля, 10 пальців скелета і 5 флаконів павучої. Тоді я створю тотем шкоди, який буде завдавати шкоди тим, хто спробує напасти на тебе.", [5] = "Дуже мудро з твого боку, {ім'я}. Цей тотем шкоди допоможе захистити тебе від зла, яке чатує по всьому Азероту та за його межами. Коли відчуєш загрозу, тримай цей тотем і його магічна аура захистить тебе. Будь {стать:мужнім:мужньою}, {стать:справедливим:справедливою} {клас:о}. Тобі знадобиться вся відвага, оскільки я бачу багато кровопролиття у твоєму майбутньому.", ["en"] = "The Totem of Infliction", ["tasks"] = { ["Ghoul Fang"] = "ікло гуля", ["Ghoul Fang (Provided)"] = "ікло гуля (видано)", ["Skeleton Finger"] = "палець скелета", ["Skeleton Finger (Provided)"] = "палець скелета (видано)", ["Vial of Spider Venom"] = "флакон павучої отрути", ["Vial of Spider Venom (Provided)"] = "флакон павучої отрути (видано)" } },
    [1015] = { [1] = "Нові рубежі", [2] = "Увага, герої!\n\nКенарійське Коло шукає здібних осіб, які допоможуть в дослідженні нових безкраїх рубежів Калімдору! Далеко на заході від Танарісу та Пристробляху лежить загадкова пустеля, сповнена неймовірних небезпек, і Колу потрібні охочі та благородні герої, що діятимуть від його імені.\n\nУсі зацікавлені мають звернутися до Кенарійського Кола. Поговоріть з верховним друїдом Фендралом Оленерогом в Дарнасі для отримання подальшої інформації!", [3] = "Поговоріть з верховним друїдом Фендралом Оленерогом в Кенарійському Анклаві Дарнасу з приводу заклику Кенарійського Кола на експедицію до нових рубежів Калімдору.", [5] = "З чого ти {стать:взяв:взяла}, що буду витрачати час на таких, як ти, {клас:к}? Звісно, почекай, зараз я кину всі свої важливі щоденні справи та допоможу тобі знайти щось-там. Ну звісно, добробут Дарнасу, та що там, всього Тельдрассілю — ніщо в порівнянні з твоїм бажанням отримати якусь нову кольорову річ.\n\nЦі дурні з Місячної галявини знову витрачають мій час на ці заклики про допомогу. Я мені все це витримати?", ["en"] = "The New Frontier" },
    [1019] = { [1] = "Нові рубежі", [2] = "Увага, герої!\n\nКенарійське Коло шукає здібних осіб, які допоможуть в дослідженні нових безкраїх рубежів Калімдору! Далеко на заході від Танарісу та Пристробляху лежить загадкова пустеля, сповнена неймовірних небезпек, і Колу потрібні охочі та благородні герої, що діятимуть від його імені.\n\nУсі зацікавлені мають звернутися до Кенарійського Кола. Поговоріть з верховним друїдом Фендралом Оленерогом в Дарнасі для отримання подальшої інформації!", [3] = "Поговоріть з верховним друїдом Фендралом Оленерогом в Кенарійському Анклаві Дарнасу з приводу заклику Кенарійського Кола на експедицію до нових рубежів Калімдору.", [5] = "З чого ти {стать:взяв:взяла}, що буду витрачати час на таких, як ти, {клас:к}? Звісно, почекай, зараз я кину всі свої важливі щоденні справи та допоможу тобі знайти щось-там. Ну звісно, добробут Дарнасу, та що там, всього Тельдрассілю — ніщо в порівнянні з твоїм бажанням отримати якусь нову кольорову річ.\n\nЦі дурні з Місячної галявини знову витрачають мій час на ці заклики про допомогу. Я мені все це витримати?", ["en"] = "The New Frontier" },
    [102] = { [1] = "Патрулювання Західного краю", [2] = "Штормовій відвернувся від нас. По рівнинах Західного краю шумить бридкий вітер мерзенності. А це була моя батьківщина, і я не відвернуся від місцевих, які вирішили тут залишитися. Ми, колишні фермери, постоїмо за себе.\n\nТвоє завдання, якщо ти за нього візьмешся, буде полягати в тому, щоб патрулювати луки Західного краю. Вистежи й убий огидних гнолів, які, схоже, діють спільно зі злодіями з Мертвих копалень. Принеси мені 8 лап гнолів, і я віддячу тобі за проявлену мужність.", [3] = "Принесіть 8 лап гнолів капітанові Данувіну на Сторожовий пагорб.", [4] = "Ти вже {стать:зібрав:зібрала} 8 лап тих підступних гнолів?", [5] = "Хороша робота, {ім'я}. З такими сміливими шукачами пригод, як ти, на боці Народного ополчення, Західний край зможе знову стати квітучою житницею, якою був колись. Будь ласка, прийми цю нагороду як знак вдячності за твої невтомні зусилля.", ["en"] = "Patrolling Westfall", ["tasks"] = { ["Gnoll Paw"] = "лапа гнола", ["Gnoll Paw (Provided)"] = "лапа гнола (видано)" } },
    [1024] = { [1] = "Очищення Рене", [2] = "Дослідження тобі доведеться провести самостійно, але з нотаток Тероніса зрозуміло, що твій наступний крок — знайти решту частин жезла, створеного Дартолом. Раджу почати з місячного колодязя на схід від Райдужного озера. Коли будеш {стать:готовий:готова}, вирушай дорогою, а коли дістанешся до невеликого майданчика для відпочинку зліва, повертай на північ.\n\nТобі зможе допомогти дріада на ім'я Шел'дрін. Знайди її.\n\nВізьми самоцвіт з собою — він знадобиться Шел'дрін, аби відновити жезл.", [3] = "Знайдіть Шел'дрін біля місячного колодязя на північному сході.", [4] = "Вітаю. Як справи?", [5] = "Тебе прислала Рене? Мабуть, справа важлива. Чим можу допомогти?", ["en"] = "Raene's Cleansing", ["tasks"] = { ["Glowing Gem"] = "сяючий самоцвіт", ["Glowing Gem (Provided)"] = "сяючий самоцвіт (видано)" } },
    [1026] = { [1] = "Очищення Рене", [2] = "Невеселі вісті.\n\nРене права, я знаю про творіння Дартола і про дереванів в цих землях. Принаймні, знала раніше. Їх було спотворено, їхня сутність понівечена.\n\nЯкщо ти бажаєш знайти ще одну частину жезла, маєш знайти ключ від скрині, в якій вона зберігається.\n\nДерев'яний ключ знайдеш в одного з дереванів на північному сході, біля Сквернолісся. Коли отримаєш його, шукай маленьку галявину на захід від дороги біля кордону зі Скверноліссям... там сховано скриню.", [3] = "Знайдіть дерев'яний ключ та частину жезла Дартола та поверніться до Шел'дрін біля місячного колодязя.", [4] = "Спотворення дереванів дуже мене засмучує. Шкода, що я не можу надати їм кращої допомоги.", [5] = "Рада бачити тебе знову, {ім'я}.", ["en"] = "Raene's Cleansing", ["tasks"] = { ["Iron Shaft"] = "залізне руків'я", ["Iron Shaft (Provided)"] = "залізне руків'я (видано)" } },
    [1029] = { [1] = "Очищення Рене", [2] = "Тобі варто знайти Рене та сказати їй, що жезл відновлено. Впевнена, що вона знає, що робити далі.\n\nЩасти тобі, {ім'я}.", [3] = "Поверніться до Рене Вовкогін в Астранаар.", [5] = "То ти {стать:відновив:відновила} жезл, який шукав Тероніс? Це чудові новини.\n\nТероніс був би радий дізнатися, що його справа живе навіть після його смерті.", ["en"] = "Raene's Cleansing", ["tasks"] = { ["Dartol's Rod of Transformation"] = "жезл трансформації Дартола" } },
    [1038] = { [1] = "Майно Велінди", [2] = "І це показав тобі фоліант Мел'Тандріс? Гадаю, нічого поганого не станеться, якщо я дозволю тобі подивитися на її речі. Цей ключ відімкне скриню з її речами в бараці стражів. Вона робила нотатки в щоденнику про свої обов'язки. Якщо є можливість чогось дізнатися, то тільки з нього.\n\nВарто зауважити, що стражі вважають, що у неї були причини для зникнення. Вони чекають на її повернення в будь-який час. Жриця багато зробила, аби заслужити нашу довіру.", [3] = "Обшукайте скриню Велінди, аби знайти її щоденник, та віддайте його, разом з ключем, Тін'тель Лезоткалі в Дарнасі.", [4] = "Щось {стать:знайшов:знайшла}?", [5] = "Схоже, що зникнення Велінди — це більша проблема, ніж здавалося спочатку. І все ж таки мені важко повірити, що вона зійшла у темряву. Можливо, було б корисно зв'язатися з нею.\n\n{ім'я}, оскільки ти {стать:проявив:проявила} неабияку цікавість до цієї справи, я хотіла б заручитися твоєю допомогою.", ["en"] = "Velinde's Effects", ["tasks"] = { ["Velinde's Journal"] = "щоденник Велінди", ["Velinde's Journal (Provided)"] = "щоденник Велінди (видано)", ["Velinde's Key"] = "ключ Велінди", ["Velinde's Key (Provided)"] = "ключ Велінди (видано)" } },
    [1039] = { [1] = "Порт в Степах", [2] = "Брашпиль — єдиний порт в Степах. Скоріше за все, Велінда знайшла торгове судно в Брашпилі, аби вирушити до Бухти Чорноводдя в Азероті. Ми мало спілкувалися з гоблінами, які керують портом, але завідувач причалу повинен знати, куди й звідки подорожують пасажири.\n\nВирушай дорогою на південний схід з Ясенедолу, поки не опинишся в Степах. Будь {стать:обережний:обережна}, {ім'я}, цю місцину охороняють воїни Орди. Але в порту ти будеш в безпеці.", [3] = "Поговоріть з завідувачем причалу Запамороком в Брашпилі.", [5] = "{Раса}, ге? Якщо чесно, ми не часто бачимо тут таких, як ти. Шукаєш когось? Хвильку, я точно робив нотатки в журналі.\n\nЧерез цей порт подорожує багацько народу, тож доведеться зачекати.", ["en"] = "The Barrens Port" },
    [1042] = { [1] = "Карвіни", [2] = "Ні, у мене немає жодних записів про перебування Велінди Зорепісні в Темнодолі... Хоча важко уявити жрицю з нічних ельфів, яка знімає кімнату в корчмі, розумієш?\n\nАле ці вовколюди, про яких ти {стать:згадав:згадала} — про них я чув. На днях Калор прийшов до міста з цілою вервечкою їхніх голів. Він працює з Карвінами — мисливцями на демонів, невмерлих та інших чудовиськ. Поговори з Джонатаном, він голова сім'ї.", [3] = "Поговоріть з Джонатаном Карвіном в Темнодолі.", [5] = "Темні часи. Недобрі чутки розносяться з кожним подихом вітру, а зло ховається під кожною каменюкою.\n\nІ в такі часи {стать:незнайомець:незнайомка} приходить в мій дім та питає про воргенів. Я не перепрошуватиму за свою підозрілість, але вимагатиму відповідей.\n\nІ я їх отримаю.", ["en"] = "The Carevin Family" },
    [1043] = { [1] = "Коса Елуни", [2] = "Ти кажеш правду... Я не зовсім розумію твої мотиви, але якщо твої справи в Смерколіссі передбачають знищення будь-якої кількості воргенів, я радий обміняти розуміння на результат.\n\nНа півдні є шахта, яку захопили воргени. Вони з'явилися хтозна-звідки, але наскільки нам відомо, їх було вперше помічено саме там.\n\nЙди по своїх справах, але прошу: якщо знайдеш щось важливе, дай мені знати. Ми будемо раді будь-якій допомозі в боротьбі зі злом.", [3] = "Знайдіть сліди коси Елуни, а потім поверніться до Джонатана Карвіна в Темноділ.", [4] = "Ці ліси небезпечні для непідготовлених. Тримай зброю та розум при собі, або твоя наступна подорож до лісу може стати останньою.", [5] = "Цікава історія, {ім'я}. Можливо, сім'я Карвін недостатньо впливова для того, аби знайти причини цієї проблеми та вирішити її раз і назавжди. Але ми робимо все можливе, аби тримати кількість воргенів в Смерколіссі під контролем.\n\nЯ вже доручив Калору зробити це завдання першочерговим.", ["en"] = "The Scythe of Elune", ["tasks"] = { ["Find evidence of the Scythe of Elune"] = "Знайдіть докази існування Коси Елуни" } },
    [1044] = { [1] = "Питання та відповіді", [2] = "Ми приборкаємо воргенів, не хвилюйся. Зло, яке твоя знайома принесла в наші ліси, буде стримано, і я не тримаю гніву за її дії. Дивні події відбуваються останнім часом, {ім'я}, а темрява не знає перепочинку.\n\nЯ тебе більше не затримуватиму. Гадаю, що є й інші, хто має почути про те, що ти {стать:знайшов:знайшла} в шахтах Смерколісся.", [3] = "Поверніться до Тін'тель Лезоткалі в Дарнас.", [5] = "То ось яка доля Велінди? Верховна жриця буде засмучена, почувши про це, вони були добрими подругами до її зникнення. Втім, коса Елуни, безсумнівно, була дарована їй нашою богинею як благословення, і мене бентежить, що служителі Елуни втратили її.\n\nВтім, про це поговоримо іншим разом. Я дуже вдячна тобі за те, що ти {стать:зробив:зробила}.", ["en"] = "Answered Questions" },
    [1045] = { [1] = "Очищення Рене", [2] = "Нічні ельфи старі як світ, але своєю зарозумілістю вони руйнують все навколо себе. А тепер вони руйнують ще й наші життя. Проте цьому вже не завадиш...\n\nЯ багато в чому звинувачую ельфів, але ми все одно відповідальні за свої вчинки. Спотворені чи ні, ми здатні на велике зло.\n\nРан Кривавозубий — одне з таких зол. Жадібний до влади, хтивий... Спотворення лише надало йому сили. Моя ненависть до ельфів палає, але я не бажаю зла їхнім дітям, тож ми мусимо приводити до ладу власні справи.", [3] = "Вбийте Рана Кривавозубого та 4 кривавозубих вартових і поверніться до Кролґа біля озера Містраль.", [4] = "Ти вже {стать:вбив:вбила} Рана?\n\nНавіть нічні ельфи не заслуговують на його гнів. Його ненависть палає гарячіше моєї, але його власний розум більше йому не належить. Він — загроза для всіх створінь природи в цьому лісі.", [5] = "Молодець.\n\nЦей ліс і досі забруднено, але принаймні ми знаємо, що зробили свій невеличкий внесок в повернення його колишньої величі. Якщо забажаєш повернутися до мене, я буду радий товариству родича.\n\nБувай {стать:здоровий:здорова}. Можливо, наші племена знову зустрінуться в менш жорстокі часи.", ["en"] = "Raene's Cleansing", ["tasks"] = { ["Bloodtooth Guard"] = "кривавозубий вартовий", ["Bloodtooth Guard slain"] = "кривавозубий вартовий: убито", ["Ran Bloodtooth"] = "Ран Кривавозубий", ["Ran Bloodtooth slain"] = "Ран Кривавозубий: убито" } },
    [1047] = { [1] = "Нові рубежі", [2] = "Увага, герої!\n\nКенарійське Коло шукає здібних осіб, які допоможуть в дослідженні нових безкраїх рубежів Калімдору! Далеко на заході від Танарісу та Пристробляху лежить загадкова пустеля, сповнена неймовірних небезпек, і Колу потрібні охочі та благородні герої, що діятимуть від його імені.\n\nУсі зацікавлені мають звернутися до Кенарійського Кола. Поговоріть з верховним друїдом Фендралом Оленерогом в Дарнасі для отримання подальшої інформації!", [3] = "Поговоріть з верховним друїдом Фендралом Оленерогом в Кенарійському Анклаві Дарнасу з приводу заклику Кенарійського Кола на експедицію до нових рубежів Калімдору.", [5] = "З чого ти {стать:взяв:взяла}, що буду витрачати час на таких, як ти, {клас:к}? Звісно, почекай, зараз я кину всі свої важливі щоденні справи та допоможу тобі знайти щось-там. Ну звісно, добробут Дарнасу, та що там, всього Тельдрассілю — ніщо в порівнянні з твоїм бажанням отримати якусь нову кольорову річ.\n\nЦі дурні з Місячної галявини знову витрачають мій час на ці заклики про допомогу. Я мені все це витримати?", ["en"] = "The New Frontier" },
    [1050] = { [1] = "Мітологія титанів", [2] = "Майбутнє невідворотне! Ми прямуємо до нього, як краплі дощу до Великого моря.\n\nТа, можливо, вивчаючи минуле, ми зможемо краще підготуватись до прийдешнього.\n\nДо того, як в Лордерон прийшло лихо, в Тірісфальському переліссі знаходився бастіон знань. Ходять чутки, що в бібліотеці старого монастиря знаходиться примірник \"Мітології титанів\".\n\nПринеси її мені й разом ми розкриємо таємниці минулого!", [3] = "Добудьте \"Мітологію титанів\" в Багряному монастирі та принесіть її бібліотекарці Мей Блідопилій в Залізогарт.", [4] = "Колись в монастирі навчали палпадинів. Та нині цю твердиню Світла захопили божевільні фанатики Багряного Походу.\n\nВони вірять в благородність своєї мети — очищення земель від напасті невмерлих. Та безумство затьмарило їх діяння і тепер вони стали ворогами для всіх.\n\nПринеси мені \"Мітологію титанів\" і я зможу вивчити її та вберегти в Залізогарті.\n\nТакій перлині історії не місце в зіпсованих стінах монастиря.", [5] = "Ти {стать:врятував:врятувала} священне писання!\n\nПевно твоя подорож була довгою, добути таку книгу — не легка задача. Та дворфи Залізогарту зможуть витягнути багато користі з твоїх діянь.\n\nДякую тобі, {ім'я}, від імені Ліги дослідників.", ["en"] = "Mythology of the Titans", ["tasks"] = { ["Mythology of the Titans"] = "Мітологія титанів", ["Mythology of the Titans (Provided)"] = "Мітологія титанів (видано)" } },
    [1053] = { [1] = "В ім'я Світла", [2] = "Колись я служив Багряному Походу усією честю та відданістю. Я вірив в його благородну мету: позбавлення Азерот від невмерлих.\n\nТа коли я провів час у монастирі в Тірісфальському переліссі, я зрозумів, що вони живуть в зовсім іншій реальності. Для них ворогом є кожен, хто не належить до Походу. Безліч невинних постраждало від тортур, бо їх вважали нечистими.\n\nБагряний Похід має бути знищенний в ім'я Світла. І ти, {ім'я}, маєш це зробити.", [3] = "Вбийте верховну інквізиторку Білогриву, командира Багряного Походу Моґрейна, чемпіона Багряного Походу Герода та псаря Локсі та відзвітуйте Релі Благочестивому в Південнобережжі.", [4] = "Ці жахливі діяння в монастирі не закінчаться, поки ми не покінчимо з лідерами Багряного Походу.\n\nВ ім'я світла, вбий верховну інквізиторку Білогриву, командира Багряного Походу Моґрейна, чемпіона Багряного Походу Герода та псаря Локсі. Можливо без них, Багряний Похід зможе повернутись до його первісної чистої мети. Та до тих пір в небезпеці буде кожен, хто перейде дорогу Багряному Походу.\n\nПрямуй в монастир і покінчи з ними!", [5] = "Хоч шлях Світла і не спонукає до кровопролить, та ми маємо визнати, що смерті цих негідників — чесна жертва на благо Королівства і всього нашого світу.\n\nТвої діяння в монастирі врятували багато невинних життів, {ім'я}. Я високо ціную твою наполегливість.", ["en"] = "In the Name of the Light", ["tasks"] = { ["Herod"] = "Ірод", ["Herod (Provided)"] = "Ірод (видано)", ["Herod slain"] = "Ірод: убито", ["High Inquisitor Whitemane"] = "Верховний інквізитор Вайтмейн", ["High Inquisitor Whitemane (Provided)"] = "Верховний інквізитор Вайтмейн (видано)", ["High Inquisitor Whitemane slain"] = "Верховний інквізитор Вайтмейн: убито", ["Houndmaster Loksey"] = "псар Локсі", ["Houndmaster Loksey slain"] = "псар Локсі: убито", ["Scarlet Commander Mograine"] = "командир Багряного Походу Моґрейн", ["Scarlet Commander Mograine slain"] = "командир Багряного Походу Моґрейн: убито" } },
    [1054] = { [1] = "Усунути загрозу", [2] = "Прямо на північ від Астранаару живе плем'я Колючохутрих хутропузів. Мої розвідники повідомляють, що за останні кілька місяців їхня чисельність значно зросла. Якщо їх стане занадто багато, вони можуть набратися сміливості й напасти на Астранаар.\n\nВбий якомога більше хутропузів та принеси мені череп їхнього вождя як доказ того, що їхні зусилля марні... поки що.\n\nЯ залишуся тут, в Астранаарі, і чекатиму на звістку. Хай буде з тобою Елуна.", [3] = "Принесіть череп Дала Кровопазура до Рене Вовкогін в Астранаар.", [4] = "Спотворення хутропузів призвело до того, що Ясенеділ став тінню колишньої величі.", [5] = "Молодець, {ім'я}.\n\nМи під постійною загрозою хутропузів. Сподіваймося, що це триматиме їх на відстані ще деякий час.", ["en"] = "Culling the Threat", ["tasks"] = { ["Dal Bloodclaw's Skull"] = "череп Дала Кровопазура", ["Dal Bloodclaw's Skull (Provided)"] = "череп Дала Кровопазура (видано)" } },
    [1057] = { [1] = "Відновлення Обвугленої долини", [2] = "Ти, як {стать:захисник:захисниця} лісових духів, безсумнівно, можеш здогадатися, чому я стривожений.\n\nЩоб попасти на цю вершину, ти {стать:пройшов:пройшла} через гори та, скорше за все, {стать:бачив:бачила}, що сталося з цією землею. Жадібність призвела до знищення священних пагорбів.\n\nОбвуглена долина на півдні була спалена механізованою армією жадібних промисловців. Гірше того, клан Криваволютих гарпій, що зазіхнув на цю землю, не дає нам пройти та розпочати її відродження.\n\nВижени цих нікчемних гарпій, {ім'я}!", [3] = "Хранитель Альбаґорм з Каміннопазуристого піку просить вас вбити 7 криваволютих гарпій, 7 криваволютих душительок, 7 криваволютих вбивць і 7 криваволютих оперених пройдисвіток.", [4] = "Попереду ще багато роботи, перш ніж Обвуглена долина знову стане пишним лісом, яким вона була раніше.\n\nОчисть територію Обвугленої долини від цієї мерзенної загрози, {ім'я}! Тільки тоді ми зможемо розпочати відновлювати те, що належить природі.", [5] = "Тепер, коли клан Криваволютих зазнав великих втрат, можливо, розпочнеться справжня робота по відновленню землі...", ["en"] = "Reclaiming the Charred Vale", ["tasks"] = { ["Bloodfury Ambusher"] = "криваволюта душителька", ["Bloodfury Ambusher slain"] = "криваволюта душителька: убито", ["Bloodfury Harpy"] = "криваволюта гарпія", ["Bloodfury Harpy slain"] = "криваволюта гарпія: убито", ["Bloodfury Roguefeather"] = "криваволюта оперена пройдисвітка", ["Bloodfury Roguefeather slain"] = "криваволюта оперена пройдисвітка: убито", ["Bloodfury Slayer"] = "криваволюта вбивця", ["Bloodfury Slayer slain"] = "криваволюта вбивця: убито" } },
    [1059] = { [1] = "Відновлення Обвугленої долини", [2] = "Клан Криваволютих приборкано. Але вони досить швидко перегрупуються та повернуться, якщо не вжити заходів.\n\nНа південь від Степів є земля, відома як Тисяча Шипів. Якщо підеш на захід Тисячі Шипів, доки не доберешся густого лісу Фераласу, ти зустрінеш друїда, на ім'я Фалфіндел Шляхостраж.\n\nЦей великий і мудрий друїд здатний викликати сильних лісових духів, які допоможуть у відновленні Обвугленої долини.\n\nРозкажи йому про нашу біду! Відшукай його негайно!", [3] = "Відправляйтесь до Фалфіндела Шляхостража, що живе на кордоні Тисячі Шипів і Фераласа.", [5] = "Хранитель Альбаґорм вчинив мудро, відправивши тебе з терміновим посланням.\n\nСподіваюся, ми зможемо викликати допомогу з великого лісу і вони встигнуть дістатися до Обвугленої долини.", ["en"] = "Reclaiming the Charred Vale" },
    [106] = { [1] = "Юні закохані", [2] = "Ох, я проклята! Моє серце належить Томмі-Джо Кам'янопільському, але наші сім'ї — закляті вороги. Тож ми не можемо бути разом, але мої очі плачуть без погляду на його вродливе обличчя!\n\nБудь ласка, візьми цей лист і передай його Томмі-Джо. Він дуже часто буває біля річки на захід від ферми Кам'янопільських, яка також на захід звідси.", [3] = "Передайте любовний лист Мейбелл Томмі-Джо Кам'янопільському.", [4] = "Що це в тебе?? Мейбелл - це світло мого похмурого життя. Не барися, дозволь мені побачити її лист!", [5] = "Ой лишенько! Я не витримаю нашої розлуки. Я мушу її побачити!!", ["en"] = "Young Lovers", ["tasks"] = { ["Maybell's Love Letter"] = "любовний лист Мейбелл", ["Maybell's Love Letter (Provided)"] = "любовний лист Мейбелл (видано)" } },
    [107] = { [1] = "Записка для Вільяма", [2] = "Готова закластися, що Вільям Товкач має зілля, що об'єднає серця двох наших молодих закоханих!\n\nОсь, віддай цю записочку Вільямові. Він зупинився в таверні «Гордість лева» в Злотохресті.", [3] = "Візьміть записку бабці Кам'янопільської та передайте її Вільяму Товкачеві.", [4] = "Ти {стать:приніс:принесла} записку від \"бабці\" Кам'янопільської, ге? Я не бачив Мілдред сто років! Цікаво, що вона пише...", [5] = "Моя душа болить за цих двох нещасних, Мейбелл і Томмі-Джо. Пам'ятаю, колись і я був юним і закоханим.\n\nЯ мушу якось їм допомогти! Дай-но подумати...", ["en"] = "Note to William", ["tasks"] = { ["Gramma Stonefield's Note"] = "записка бабці Кам'янопільської", ["Gramma Stonefield's Note (Provided)"] = "записка бабці Кам'янопільської (видано)" } },
    [1071] = { [1] = "Перепочинок гнома", [2] = "Бачиш, {ім'я}, я член Просвітленої Асамблеї Арканології, Алхімії та Інженерних Наук, і моя ціль... ні, мій ОБОВ'ЯЗОК! показати нічним ельфам, що комбінування магії, сумішей і механізмів може допомогти врятувати їхні ліси.\n\nАле це важка війна, і, здається, гобліни розмножуються, як кролики. Я навіть не встигаю завершити конструювання своїх найновіших винаходів!\n\nМені потрібен час на планування та організацію. Але для цього знадобиться твоя допомога, щоб тримати гоблінів в бухті Вітрокосої скелі, що на схід звідси...", [3] = "Вбийте 10 лісорубів та 10 лісозаготівельників ТзНБ \"Авантюра\" і поверніться до Ґаксима Іржошипа в Каміннопазуристі гори.", [4] = "То як ідуть справи з твого боку, {ім'я}?", [5] = "Дуже дякую тобі за допомогу, {ім'я}. Ти {стать:повернувся:повернулася} якраз вчасно.\n\nЗдається, я придумав ідеальний план... вибухівка. Ні, це не весь план, це частина плану.\n\nРозумієш, я використовував потужну вибухівку — не хвилюйся, вона не така небезпечна, як всі думають — щоб трохи налякати гоблінів. Розмістивши вибухівку в ключових місцях по краях гір, я зможу їх непогано налякати, але вже через кілька днів у мене можуть закінчитися матеріали...", ["en"] = "A Gnome's Respite", ["tasks"] = { ["Venture Co. Deforester"] = "лісозаготівельник ТзНБ \"Авантюра\"", ["Venture Co. Deforester slain"] = "лісозаготівельник ТзНБ \"Авантюра\": убито", ["Venture Co. Logger"] = "лісоруб ТзНБ \"Авантюра\"", ["Venture Co. Logger slain"] = "лісоруб ТзНБ \"Авантюра\": убито" } },
    [1072] = { [1] = "Давній колега", [2] = "Пристрій, про який я думаю, — це мій найдосконаліший винахід на сьогодні. Але щоб він запрацював, нам знадобиться спеціальне зілля. Гадаю, нам варто дістати найкращі інгредієнти, або ця місія може стати останньою для тебе.\n\nА для цього нам знадобиться потужна вибухівка: нітроміргліцероній.\n\nЄдиний, хто може зробити НГ-5 - це мій давній друг: Ломак Зубчастик. Знайди його у Штукарівці.\n\nТи маєш вмовити його зробити нам кілька НГ-5, а я поки займуся розміщенням моїх пристроїв.", [3] = "Поговоріть з Ломаком Зубчастиком в Залізогарті.", [5] = "Оой.... Тебе Ґаксим прислав, так? Звідки мені знати, що ти мені не брешеш?! Ммм? Ммм...?", ["en"] = "An Old Colleague" },
    [1075] = { [1] = "Сувій від Морена", [2] = "Гаразд, тепер до другої частини мого плану — дистанційні вибухи... ой, я ще не розповідав про це?\n\nДобре, якщо коротко, то ось що: трохи магії і я зроблю так, щоб вибухівка спрацювала без твоєї присутності. Я зберу такий пристрій, для активації якого потрібно натиснути лише одну кнопку та, коли ти будеш {стать:готовий:готова}, НГ-5 вибухне.\n\nАле мені потрібне закляття від мого друга Колліна Морена, що проживає у Штормовії. Ти можеш знайти його у кварталі магів. Він людина, тому його важко буде не помітити.", [3] = "Знайдіть Колліна Морена у Штормовії.", [5] = "Отже, тобі потрібне закляття, що дозволить підірвати здетонувати на відстані... хмм...", ["en"] = "A Scroll from Mauren" },
    [1076] = { [1] = "Дідьки Західного краю", [2] = "Здається, я зрозумів. Закляття повідомлення... Гадаю, це саме той ефект, який він шукає.\n\nЯ маю створити сувій з накладеним на нього закляттям. Для цього мені знадобляться уламки пилового дідька.\n\nПоки я збиратиму решту компонентів, чому б тобі не відправитися у Західний край і не знайти одну з цих мерзенних тварюк? Вони небезпечні, але я впевнений, що там немає нічого такого, з чим ти б не {стать:зміг би:змогла б} впоратися, якщо хочеш взяти участь в одному з експериментів Ґаксима.\n\nЯ чекатиму на тебе тут.", [3] = "Принесіть уламки пилового дідька Колліну Морену у Штормовій.", [4] = "Привіт, {ім'я}. Ти {стать:знайшов:знайшла} компонент, який мені потрібен?", [5] = "Дай мені кілька хвилин і твій сувій буде готовий.", ["en"] = "Devils in Westfall", ["tasks"] = { ["Dust Devil Debris"] = "уламки пилового дідька", ["Dust Devil Debris (Provided)"] = "уламки пилового дідька (видано)" } },
    [1077] = { [1] = "Особливий пакунок для Ґаксима", [2] = "Ось, {ім'я}, це має підійти.\n\nБудь ласка, передай Ґаксиму вітання, коли побачиш його наступного разу. Я з нетерпінням чекаю розповідь про твою подорож.\n\nЩасливої дороги.", [3] = "Віднесіть сувій повідомлення Ґаксиму Іржошипу в Каміннопазуристі гори.", [4] = "Ха-ха! Ти {стать:повернувся:повернулася}! Воно у тебе? Ти {стать:приніс:принесла} закляття?", [5] = "Чудово, {ім'я}! Ти молодець.\n\nПоєднавши це закляття з НГ-5, ми отримаємо ідеальну дистанційну вибухівку.\n\nНам вдасться провести ідеальний маневр, щоб відвернути їхню увагу та дозволити тобі пробратися всередину і викрасти листи та інженерні плани ТзНБ \"Авантюра\".\n\nЦе, безумовно, сповільнить вирубку лісів.", ["en"] = "Special Delivery for Gaxim", ["tasks"] = { ["Scroll of Messaging"] = "сувій повідомлення", ["Scroll of Messaging (Provided)"] = "сувій повідомлення (видано)" } },
    [1079] = { [1] = "Таємна операція — Альфа", [2] = "Отож, {ім'я}. Слухай уважно. Пристрої готові до використання.\n\nВізьми ці папери — з них ти дізнаєшся більше про детонатори та вибухівку, а також про те, де ти маєш їх розмістити.\n\nПам'ятай: успіх твоєї місії не залежить від того, скільки руйнувань ти спричиниш. Успіх плану \"Альфа\" залежить від того, чи добудеш ти інженерні креслення ТзНБ \"Авантюра\", що знаходяться південніше від Скельнодонного озера на лісопильні.", [3] = "Добудьте інженерні креслення ТзНБ \"Авантюра\" з лісопильні на Вітрокосих скелях.", [4] = "Ти {стать:дістав:дістала} креслення, {ім'я}?", [5] = "Справді дивовижно! Це величезний удар для ТзНБ \"Авантюра\".\n\nМи зможемо знайти слабкі місця в їхніх машинах, а також використати їхні розробки для наших потреб. Це дійсно чудовий день.", ["en"] = "Covert Ops - Alpha", ["tasks"] = { ["Venture Co. Engineering Plans"] = "інженерні креслення ТзНБ \"Авантюра\"", ["Venture Co. Engineering Plans (Provided)"] = "інженерні креслення ТзНБ \"Авантюра\" (видано)" } },
    [1080] = { [1] = "Таємна операція — Бета", [2] = "План Бета схожий з планом Альфа, {ім'я}.\n\nМи відвернемо їхню увагу, а потім викрадемо дорогоцінні документи.\n\nГоловне — отримати їхні документи... пам'ятай про це.\n\nНа паперах, які я тобі дав, вказано, де закласти вибухівку. Просто повернися сюди {стать:живим:живою} та з документами....", [3] = "Добудьте документи ТзНБ \"Авантюра\" з Вітрокосої печери, що на східній стороні Вітрокосої скелі.", [4] = "То як справи, {ім'я}?", [5] = "Неймовірно, {ім'я}! Кейла і стражі будуть в захваті. З твоєю майстерністю і моїми творіннями нас не зупинити.", ["en"] = "Covert Ops - Beta", ["tasks"] = { ["Venture Co. Letters"] = "документи ТзНБ \"Авантюра\"", ["Venture Co. Letters (Provided)"] = "документи ТзНБ \"Авантюра\" (видано)" } },
    [1082] = { [1] = "Новини для стражниці Тенисіл", [2] = "{ім'я}, ти {стать:зробив:зробила} гідний вчинок, простягнувши нам руку допомоги.\n\nСтражі Ясенедолу добре віддячать тобі, якщо ти розкажеш їм, що ми з Ґаксимом живі. Скажи їм, що ми працюємо над тим, щоб зупинити ТзНБ \"Авантюра\" і зцілити землі.\n\nЗнайди в Астранаарі Тару Тенисіл. Вона зрадіє твоєму поверненню та хорошим новинам.", [3] = "Поверніться до стражниці Тенисіл в Ясенеділ.", [5] = "Дякую тобі, {ім'я}. Ти {стать:допоміг:допомогла} стражам.\n\nЯ рада бачити, що у Кейли... і навіть у Ґаксима все добре.\n\nТи заслуговуєш нашої подяки.", ["en"] = "Update for Sentinel Thenysil" },
    [1083] = { [1] = "Розлючені духи", [2] = "Я не знаю, що ТзНБ \"Авантюра\" зробили з долиною, але очевидно, що тамтешні істоти були сильнішими за них.\n\nТзНБ \"Авантюра\" підпалили ліс і використовували свої вбивчі винаходи, щоб знищити якомога більшу частину долини.\n\nАле через свою неосвіченість вони випустили на волю дещо інше: палаючих духів, елементалів вогню, каменю та люті.\n\nЗемля ніколи не побачить усмішки Елуни, доки ці створіння блукатимуть на волі.\n\nПринеси мені тліючі вуглинки як доказ того, що тобі вдалося зменшити кількість розлючених духів.", [3] = "Добудьте 8 тліючих вуглинок у будь-якого вогняного елементаля в Обвугленій долині та віддайте Кейлі Тінеспис в Каміннопазуристих горах.", [4] = "Коли я вперше побачила Обвуглену долину, я мало не розплакалася, {ім'я}.", [5] = "Рештки наших ворогів... твоя сила добре послужила нам, {ім'я}. Дякую тобі.", ["en"] = "Enraged Spirits", ["tasks"] = { ["Smoldering Embers"] = "тліюча вуглинка", ["Smoldering Embers (Provided)"] = "тліюча вуглинка (видано)" } },
    [1084] = { [1] = "Поранені древні", [2] = "Мені здається очевидним, що захисники долини — деревані — протистояли ТзНБ \"Авантюра\" і врешті-решт вигнали їх звідти. На жаль, навіть ці колись великі охоронці зазнали спотворення.\n\nҐаксим вважає, що їхнє спотворення якось пов'язане зі зброєю, яку гобліни використовували під час відступу.\n\nЯ сказала йому, що візьму зразок із тіла пораненого дереваня і віддам його на дослідження, щоб з'ясувати, чи це правда.\n\nПринеси мені трохи шрапнелі, щоб гном міг розповісти більше...", [3] = "Принесіть шматок іржавої шрапнелі Кейлі Тінеспис в Каміннопазуристі гори.", [4] = "В мене таке відчуття, що Ґаксим знайде застосування шрапнелі, не дивлячись на те, як ТзНБ \"Авантюра\" використовувала її раніше.", [5] = "Дякую тобі, {ім'я}.\n\nЦього має бути більш ніж достатньо, щоб Ґаксим міг зрозуміти, які причини лежать в основі спотворення дереванів. Я негайно передам йому цей зразок.", ["en"] = "Wounded Ancients", ["tasks"] = { ["Corroded Shrapnel"] = "іржава шрапнель", ["Corroded Shrapnel (Provided)"] = "іржава шрапнель (видано)" } },
    [1085] = { [1] = "На варті в Каміннопазуристих горах", [2] = "Якщо гном і нічний ельф працюють разом, очевидно, що в Каміннопазуристі гори прийшла біда.\n\nТзНБ \"Авантюра\" спустошила ці землі. Я витратила багато часу, намагаючись покласти кінець їх нищівному впливу.\n\nНе суди Ґаксима завчасно. Він розуміє, що наша спільна робота необхідна.\n\nЯкщо бажаєш допомогти, спочатку поговори з Ґаксимом.\n\nВибач, що не можу поки що відіслати тебе назад до Тари з добрими новинами. Можливо, це скоро станеться.", [3] = "Поговоріть з Ґаксимом.", [5] = "Ця земля підступна... підступна та небезпечна.\n\nАле я тут для того, аби показати нічним ельфам, що стара добра інженерія та дрібка магії можуть зробити її безпечнішою.\n\nРозумієш, повна відмова від магії не спрацює — вона потрібна нічним ельфам. Вона потрібна світові. А якщо додати трохи інженерії та алхімії, точно не прогадаєш. Можливості неосяжні.", ["en"] = "On Guard in Stonetalon" },
    [109] = { [1] = "Звіт Ґріану Міцнокриву", [2] = "Здається мені, що ти {стать:побував:побувала} не в одному бою, {клас:к}. Тобі слід відзвітувати Ґріанові Міцнокриву, якщо досі не було такої нагоди. Він очолює Народне ополчення, спрямоване на захист сільськогосподарських угідь Західного краю. Б'юсь об заклад, йому може знадобитись твоя допомога. Зазвичай його можна знайти в кам'яній вежі на Сторожовому пагорбі, неподалік дороги посеред Західного краю.", [3] = "Поговоріть з Ґріаном Міцнокривом. Зазвичай його можна знайти в кам'яній вежі на Сторожовому пагорбі, неподалік дороги посеред Західного краю.", [5] = "О, то тебе прислав сюди мій друг? Як люб'язно.\n\nНу, монархія Штормовія полишила нашу справу. Залишається покладатися лише на Народне ополчення. Якщо тебе зацікавила наша боротьба, то я зможу знайти застосування твоїм бойовим навичкам, в ім'я свободи.", ["en"] = "Report to Gryan Stoutmantle" },
    [1091] = { [1] = "Новини для Кейли", [2] = "{ім'я}, віднеси ці документи Кейлі. Впевнений, вона захоче дізнатися про це. Принаймні, стражі точно захочуть.\n\nНе забудь розповісти їй про наші успіхи й про те, що у нас нічого б не вийшло без дрібки магії.", [3] = "Віднесіть документи ТзНБ \"Авантюра\" Кейлі Тінеспис.", [4] = "Так, {ім'я}? Чи я можу тобі допомогти?", [5] = "Це дійсно цікаво.\n\nВи з Ґаксимом дуже добре попрацювали, {ім'я}. Дякую.", ["en"] = "Kaela's Update", ["tasks"] = { ["Venture Co. Letters"] = "документи ТзНБ \"Авантюра\"", ["Venture Co. Letters (Provided)"] = "документи ТзНБ \"Авантюра\" (видано)" } },
    [1097] = { [1] = "Завдання Елмора", [2] = "В Штормовії є дворф-зброяр, Ґріманд Елмор, якому потрібна допомога з доставкою. Я думаю, він шукає когось, хто зможе доставити його посилку на його батьківщину на північ.\n\nСхоже, що ти {стать:досвідчений мандрівник:досвідчена мандрівниця}. Отож, якщо ти шукаєш роботу — поговори з Ґрімандом. Ми могли б скористатися твоєю допомогою тут, та нам також потрібно підтримувати міцні зв'язки з дворфами.\n\nТи знайдеш Ґріманда Елмора в крамниці зброї у дворфійському районі в Штормовії, у північно-східній частині міста.", [3] = "Поговоріть з Ґрімандом Елмором.", [5] = "Ти тут, щоб допомогти мені з доставкою? Дуже добре!", ["en"] = "Elmore's Task" },
    [11] = { [1] = "Винагорода за річколапих гнолів", [2] = "На кордонах Елвиннського лісу з'явилися гноли — звіроподібні тварюки, яким просто нема чого робити в цих краях. На південь від сторожової вежі була помічена велика група цих істот: їх занадто багато, щоб ми зуміли дати їм відсіч самі. Гірше того: на сході, біля озера Кам'яних Обелісків, теж виявили гнолів.\n\nАрмія Штормовію буде вдячна кожному, хто допоможе впоратися з цією загрозою. Як доказ своєї перемоги принеси мені розфарбовані браслети гнолів.", [3] = "Принесіть 8 розфарбованих браслетів гнолів заступнику Райнеру в казарми.", [4] = "Егей, {ім'я:к}. Ти {стать:повбивав:повбивала} гнолів...?", [5] = "О, бачу, ти слів на вітер не кидаєш! Прийми нашу подяку, {ім'я:к}!", ["en"] = "Riverpaw Gnoll Bounty", ["tasks"] = { ["Painted Gnoll Armband"] = "розфарбований браслет гнола", ["Painted Gnoll Armband (Provided)"] = "розфарбований браслет гнола (видано)" } },
    [1101] = { [1] = "Відьма краалю", [2] = "Бідний Гералат! І цей дворф... Однобровий. Яка хоробра душа...\n\nЇх зусилля не будуть марними. Ця відьма... Чарлґа Бритвобока... ми маємо її зупинити.\n\nЩо ж, штурм краалю буде непростим, та у нас немає часу чекати на підмогу з Дарнас. {ім'я}, тобі доведеться знайти компаньйонів і вбити відьму.\n\nПринеси мені медальйон Бритвобокої як доказ.", [3] = "Принесіть медальйон Бритвобокої Фалфінделу Шляхостражу в Таланаар.", [4] = "Поки Чарлґа Бритвобока збирає сили в краалі Бритвоболотих, ці землі в небезпеці.", [5] = "Нарешті ця відьма згинула. Це чудова новина, {ім'я}.\n\nВ ці важки часи дуже приємно зустріти таку хоробру душу, як ти.\n\nТепер, коли слуги Бритвобокої не несуть загрозу, ми можемо продовжити наші досліди в цих землях. Можливо тепер ми дізнаємось, що спричинило порчу на місці поховання Аґамаґґана.\n\nОднак, я боюсь, що причина у зраді...", ["en"] = "The Crone of the Kraul", ["tasks"] = { ["Razorflank's Medallion"] = "медальйон Бритвобокої", ["Razorflank's Medallion (Provided)"] = "медальйон Бритвобокої (видано)" } },
    [111] = { [1] = "Розмова з бабцею", [2] = "Будь ласка, {ім'я}, переговори з моєю бабусею. Якщо хто й може зробити так, щоб ми з Мейбелл були разом, так це вона.\n\nВона живе в нашому будинку на схід звідси.", [3] = "Поговоріть з бабцею Кам'янопільською.", [5] = "Допоки наші сім'ї ворогують, у Томмі-Джо та Мейбелл не найкраще майбутнє, але... можливо, ми зможемо допомогти їм хоча б ненадовго зустрітися.\n\nГм, дай-но подумаю...", ["en"] = "Speak with Gramma" },
    [112] = { [1] = "Збір водоростей", [2] = "Я можу зварити зілля, що зробить Мейбелл невидимою, тоді вона зможе прослизнути з виноградників Маклура та піти до Томмі-Джо. Але для виготовлення відвару мені потрібні кришталеві водорості.\n\nХоча водорості, зазвичай, ростуть в океані... іноді їх збирають мурлоки. Перевір, чи є запаси у мурлоків, тих, що біля Кришталевого озера. Водойма знаходиться одразу на схід від Злотохрестя.", [3] = "Принесіть 4 стебла кришталевої водорості Вільяму Товкачеві до Злотохрестя.", [4] = "Ти {стать:приніс:принесла} кришталеві водорості? Безсумнівно, Мейбелл не терпиться побачити свого залицяльника...", [5] = "Тобі вдалося! Чудово! Тепер зачекай хвильку, поки я приготую відвар...", ["en"] = "Collecting Kelp", ["tasks"] = { ["Crystal Kelp Frond"] = "стебло кришталевої водорості", ["Crystal Kelp Frond (Provided)"] = "стебло кришталевої водорості (видано)" } },
    [1133] = { [1] = "Подорож до Астранаару", [2] = "Якщо ти щойно {стать:прибув:прибула} з Менетілу, то в першу чергу тобі варто... відправитись до Астранаару. Впевнена, там знайдеться щось для таких відданих членів Альянсу, як ти. Поговори з Шиндрел Спалах і запропонуй їй свої послуги.\n\nАле не згадуй хто тебе прислав. Шиндрел мене не знає...", [3] = "Поговоріть з Шиндрел Спалах в Астранаарі.", [5] = "Ти тут, щоб запропонувати свою допомогу Альянсу, {ім'я}? Ми з радістю приймемо її. Хоча Ясенеділ так само мальовничий, як і раніше, війна все ж не оминула його.", ["en"] = "Journey to Astranaar" },
    [1134] = { [1] = "Гордокрили з Каміннопазуристих гір", [2] = "Ми не в стані відкритої війни з Ордою, проте це перемир'я крихке. Ми часто помічаємо ворожі дії ординських агентів, але вони приховані.\n\nМи дізналися про один з таких випадків з таємного джерела в Тераморі. Схоже, що орки збирають отруту гордокрилів біля Хмуромутного озера, що в Каміннопазуристих горах на півдні. Орківські душогуби використовують цю отруту під час таємних нападів на Альянс!\n\nЯкщо це правда, ми повинні їх зупинити, {ім'я}. Перекрий їм доступ до джерела отрути.", [3] = "Принесіть 12 отруйних залоз гордокрилів Шиндрел Спалах в Астранаар.", [4] = "Ти {стать:здобув:здобула} отруйні залози, {ім'я}? Ми не можемо дозволити оркам використати отруту проти нас!", [5] = "Дякую, {ім'я}. Мені шкода, що доводиться вбивати істот, які ненавмисно допомагають ворогові, але це мій обов'язок.\n\nЯкщо твоє серце стискається від думки про вбивство гордокрилів, друже, нехай думка про всіх наших побратимів, врятованих від отрути, буде тобі розрадою.", ["en"] = "Pridewings of Stonetalon", ["tasks"] = { ["Pridewing Venom Sac"] = "отруйна залоза гордокрила", ["Pridewing Venom Sac (Provided)"] = "отруйна залоза гордокрила (видано)" } },
    [1138] = { [1] = "Дари моря", [2] = "Я обожнюю крабів. Краби — це справжні дари моря! Їх можна варити, тушкувати, запікати, смажити на сковорідці, у фритюрі, на грилі, на вогні. Є крабовий салат, крабове рагу, крабовий суп, крабовий куліш, тушкований краб, краб з ананасом, в лимоні, з перцем, краб з кнутокоренем і краб-сюрприз по-Залізогартськи. Ну... здається, все.\n\nЯ зараз рибалю, тому не можу дістати гарного крабового м'яса. Ти зможеш добути його з повзунів: потертих хвилевих чи рифових. З них можна багато чого приготувати. Можна варити, тушкувати, запікати...", [3] = "Зберіть 6 шматків чудового крабового м'яса Ґаббі Блампу в Аубердін.", [4] = "...з перцем, краб з кнутокоренем і краб-сюрприз по-Залізогартськи. Ну... здається, все.\n\nО, привіт, {ім'я}. Ти {стать:приніс:принесла} крабове м'ясо, про яке я казав?", [5] = "Ого, це чудове крабове м'ясо — те, що мені потрібно. Дякую, {ім'я}! Я знайшов це під час риболовлі, і воно мені ні до чого. Може, ти зможеш щось з ним зробити. До крабових страв таке точно не підійде.\n\nЯ ж вже розповідав тобі про крабів, так?", ["en"] = "Fruit of the Sea", ["tasks"] = { ["Fine Crab Chunks"] = "чудове крабове м'ясо", ["Fine Crab Chunks (Provided)"] = "чудове крабове м'ясо (видано)" } },
    [114] = { [1] = "Втеча", [2] = "Передайте цей відвар невидимості юній Мейбелл. Його дія повинна тривати достатньо довго, щоб вона змогла відвідати Томмі-Джо.", [3] = "Передайте відвар невидимості Мейбелл Маклур.", [4] = "Ти {стать:доставив:доставила} мій лист Томмі-Джо? Що він сказав??", [5] = "О лишенько! Мені так соромно, що обманюю свою родину, але мої почуття до Томмі-Джо занадто сильні, щоб їх ігнорувати.\n\nДякую, {ім'я}. Я вип'ю цей відвар, як тільки матиму нагоду, та вислизну до свого коханого.\n\nА ось це для тебе... будь ласка, візьми.", ["en"] = "The Escape", ["tasks"] = { ["Invisibility Liquor"] = "відвар невидимості", ["Invisibility Liquor (Provided)"] = "відвар невидимості (видано)" } },
    [1141] = { [1] = "Родина і вудка", [2] = "Я люблю рибалити. Сім'я Блампів славиться своїми рибалками. Мене звати Ґабба Бламп, я рибалка.\n\nУ цих краях я люблю ловити рибу, яка називається окунем Темнобережжя. Раніше я виходив на човні в море, але відтоді, як тут оселилися ці злі мурлоки, жоден човен у море не виходить. Боюся, вони й окунів усіх з'їдять.\n\nХочеш допомогти мені наловити окунів? Я дам тобі справжню сімейну вудку Блампів, якщо погодишся! Це дуже хороша вудка!", [3] = "Спіймайте 6 окунів Темнобережжя для Ґабби Блампа в Аубердіні.", [4] = "З окунів Темнобережжя можна приготувати багато смачних страв. Вони гарні на смак, але я думаю, що ловити їх набагато цікавіше.\n\nТи вже {стать:наловив:наловила} окунів?", [5] = "Це дуже гарні окуні, {ім'я}! Дякую за допомогу!\n\nТи щонайменше {стать:такий же хороший:така ж хороша} рибалка, як моя родичка, Ґраун Бламп. У неї, щоправда, є борода і вона трохи дивно пахне, але це не заважає їй ловити рибу. Гадаю, ти теж тепер можеш користуватися сімейною вудкою Блампів.", ["en"] = "The Family and the Fishing Pole", ["tasks"] = { ["Darkshore Grouper"] = "окунь Темнобережжя", ["Darkshore Grouper (Provided)"] = "окунь Темнобережжя (видано)" } },
    [1142] = { [1] = "Прийняття смертності", [2] = "Мені залишилось недовго... Сили... покидають мене...\n\n...х-х-хоробрий дворф... Однобровий... він відправився, щоб по... попепередити Фалфіндела...\n\nТа перш ніж я... помру...\n\n...моя дружина, Трешала... Її кулон забрав один з... нападників...\n\nПрошу, знайди його... і поверни Трешалі в Дарнас...\n\nІ розкажи про мою... смерть.", [3] = "Знайдіть кулон Трешали та поверніть його Трешалі Цілиноплин в Дарнас.", [4] = "Що привело тебе у мій дім, {раса:к}?", [5] = "Ні!\n\nНе може бути... Я не вірю... Який жорстокий світ!\n\nЯ нестиму тягар цього горя і не дозволю справі Гералата померти з ним.\n\nДякую за те, що {стать:подолав:подолала} цей шлях, {ім'я}. Але залиш мене.\n\nЯ оплакуватиму чоловіка на самоті...", ["en"] = "Mortality Wanes", ["tasks"] = { ["Treshala's Pendant"] = "кулон Трешали", ["Treshala's Pendant (Provided)"] = "кулон Трешали (видано)" } },
    [115] = { [1] = "Темна магія", [2] = "Чорноскельні орки залучили тінемовів до своїх атак на Багрянокряжжя, а ті принесли із собою джерела темної сили — опівнічні сфери. З їх допомогою тінемови завдали тяжких ударів по захисниках Багрянокряжжя, і ми маємо якнайшвидше позбавити їх цієї демонічної зброї.\n\nДобудь для мене опівнічні сфери з убитих тінемовів Чорнокаменю. Я знищу сфери, і наш світ стане чистіше!", [3] = "Принесіть 3 опівнічні сфери маршалу Маррісу в Приозер'я.", [4] = "Як твої успіхи з тінемовами? Вже {стать:дістав:дістала} опівнічні сфери?", [5] = "Дякую, {ім'я}. Я негайно займусь їх знищенням.", ["en"] = "Shadow Magic", ["tasks"] = { ["Midnight Orb"] = "опівнічна сфера", ["Midnight Orb (Provided)"] = "опівнічна сфера (видано)" } },
    [116] = { [1] = "Сухі часи", [2] = "У мене тут кепська ситуація, {ім'я}. Бутилі вже ледь не сухі, а доставка питва сильно спізнюється. Вторгнення орків - це чисте пекло.\n\nМоже ти зможеш мені прислужитись?\n\nМені треба, щоб ти {стать:забрав:забрала} бочечку громузвару у Лютобуха Громовара у пагорбах Західного краю, барильце Мерло у Штормовії, пляшку сивухи у Темноділі й бурдюк солодкого рому в Злотохресті. Принеси їх мені, і я прослідкую, щоб ти не {стать:лишився обділений:лишилась обділена}.", [3] = "Бармен Деніелс з Приозер'я потребує бочечку громузвару, барильце Мерло, пляшку сивухи та бурдюк солодкого рому.", [4] = "Мені треба, щоб ти {стать:підібрав:підібрала} бочечку громузвару у Лютобуха Громовара у пагорбах Західного краю, барильце Мерло у Штормовії, пляшку сивухи у Темноділі й бурдюк солодкого рому в Злотохресті. Принеси їх мені й будеш {стать:нагороджений:нагороджена}.", [5] = "Блискуче виконана робота, {ім'я}! Я добре знаю дороги, якими ти {стать:пройшов:пройшла}, аби дістати таку кількість алкоголю. Та мої відвідувачі знову будуть щасливі!\n\nМоя жінка - вміла швачка. Прошу взяти цей плащ, що вона зшила, як нагороду за твої труди.", ["en"] = "Dry Times", ["tasks"] = { ["Bottle of Moonshine"] = "пляшка сивухи", ["Bottle of Moonshine (Provided)"] = "пляшка сивухи (видано)", ["Cask of Merlot"] = "барильце Мерло", ["Cask of Merlot (Provided)"] = "барильце Мерло (видано)", ["Keg of Thunderbrew"] = "бочечка громузвару", ["Keg of Thunderbrew Lager"] = "Кег лагеру Thunderbrew", ["Keg of Thunderbrew Lager (Provided)"] = "Кег лагеру Thunderbrew (видано)", ["Keg of Thunderbrew Lager slain"] = "Кег лагеру Thunderbrew: убито", ["Skin of Sweet Rum"] = "бурдюк солодкого рому", ["Skin of Sweet Rum (Provided)"] = "бурдюк солодкого рому (видано)" } },
    [117] = { [1] = "Громузвар", [2] = "Скоріше, мій друже, чому ти закляк?\nДля того, щоб лагер був схожий на смак\nСкоріше на пиво, а не на кисіль,\nЗварити щоб пійло, потрібен нам хміль.", [3] = "Принесіть Лютобухові Громовару 5 шишок хмелю, щоб завершити його особливий напій.", [4] = "Скоріше, мій друже, чому ти закляк?\nДля того, щоб лагер був схожий на смак\nСкоріше на пиво, а не на кисіль,\nЗварити щоб пійло, потрібен нам хміль.", [5] = "З хмелю й ячменю, дріжджів і солоду\nЦей вибух у роті несе насолоду.\nНе треба благати, не треба просити,\nЩоб кухоль собі Громузвару налити!", ["en"] = "Thunderbrew", ["tasks"] = { ["Hops"] = "хміль", ["Hops (Provided)"] = "хміль (видано)" } },
    [118] = { [1] = "Ціна підків", [2] = "Я витратив стільки заліза на екіпіровку стражів Штормовію, що мені не вистачає навіть на підкови для коней!\n\nВіднеси цю записку ковалеві Арґусу в Злотохрестя, я хочу замовити у нього партію підків.", [3] = "Віднесіть записку Вернера ковалю Арґусу в Злотохрестя.", [4] = "Що це? Кажеш, тебе Вернер прислав? Давай мені цю записку. І ГОВОРИ ГУЧНІШЕ!", [5] = "Хех, то старому Вернеру потрібні підкови, ге?!", ["en"] = "The Price of Shoes", ["tasks"] = { ["Verner's Note"] = "записка Вернера", ["Verner's Note (Provided)"] = "записка Вернера (видано)" } },
    [119] = { [1] = "Повернення до Вернера", [2] = "Гаразд, я відправлю йому 50 підків...\n\nОсь вони, упаковані та готові до відправлення! Передай Вернеру, що з ним приємно мати справу. І нехай прочитає записку, прикріплену до ящика!", [3] = "Поверніться до Вернера Осґуда в Багрянокряжжя та віддайте йому ящик з підковами.", [4] = "Чудово, ти {стать:повернувся:повернулась}! Підкови в тебе?", [5] = "Дякую, ти мене дуже {стать:виручив:виручила}.\n\nЩо це? Арґус надіслав записку з ящиком... Що?! Арґус хоче, щоб я йому ЗАПЛАТИВ? Пф!\n\nЩо ж, {ім'я}, дякую за допомогу.", ["en"] = "Return to Verner", ["tasks"] = { ["Crate of Horseshoes"] = "ящик з підковами", ["Crate of Horseshoes (Provided)"] = "ящик з підковами (видано)" } },
    [1199] = { [1] = "Настання сутінків", [2] = "Черпаючи силу зі стародавніх обрядів Старих Богів, члени Сутінкового Молота намагаються повернути своїх темних повелителів в наш світ, щоб ті знову сіяли смерть і хаос.\n\nМи думаємо, що Сутінковий Молот об'єднався з нагами й тепер вони накопичують сили в Чорноводних глибинах на узбережжі Ясенедолу.\n\nЩо б вони там не задумали, ми маємо їх зупинити.\n\nЙди на війну з Молотом і повертайся з доказами своїх діянь. За свої зусилля ти отримаєш щедру винагороду.", [3] = "Принесіть 10 сутінкових підвісок вартовому Сріблястого Світанку Манадосу в Дарнас.", [4] = "Чорноводні глибини були стародавнім храмом нічних ельфів. Колись там знаходився наймогутніший місячний колодязь. Хто зна, яке зло там тепер готує Сутінковий Молот.\n\nЄ успіхи в боротьбі з ними?", [5] = "Ти, безперечно, {стать:повний:повна} хоробрості та доброчинності, {ім'я}. Сріблястий Світанок високо цінить твої зусилля в боротьбі проти зла.", ["en"] = "Twilight Falls", ["tasks"] = { ["Twilight Pendant"] = "сутінкова підвіска", ["Twilight Pendant (Provided)"] = "сутінкова підвіска (видано)" } },
    [12] = { [1] = "Народне ополчення", [2] = "У Народного ополчення є лише одна мета: захистити землі Західного краю та повернути в них мир. На жаль, за мир часто доводиться платити кров'ю.\n\nОдин з моїх розвідників повідомив про групу капканників Непокірних, що сіють неспокій. В мене є звіти, що звіроловів Непокірних помічали біля копальні Джанґолода на північний захід звідси, а також неподалік від ферми Мольсена та гарбузової ферми Хмуроброва. Якщо ти прагнеш приєднатися до наших лав, убий 15 капканників і 15 контрабандистів з Братства Непокірних, а потім повертайся до мене.", [3] = "Ґріан Міцнокрив хоче, щоб ви вбили 15 капканників і 15 контрабандистів Непокірних та повернулися до нього на Сторожовий пагорб.", [4] = "Можливо, я не пояснив достатньо зрозуміло, новачку. Для того, щоб довести свою цінність як {стать:служителя:служительки} Народного ополчення та Світла, тобі потрібно вбити 15 капканників та 15 контрабандистів з Братства Непокірних, а потім повернутися до мене, коли все буде зроблено.", [5] = "Молодець, {ім'я:к}. Мій розвідник був свідком твоїх доблесних вчинків. Ти досить добре себе {стать:зарекомендував:зарекомендувала}.", ["en"] = "The People's Militia", ["tasks"] = { ["Defias Smuggler slain"] = "контрабандист Непокірних: убито", ["Defias Trapper slain"] = "капканник Непокірних: убито" } },
    [120] = { [1] = "Посланець до Штормовію", [2] = "Ми переживаємо важкі часи, {клас:к}. Містечко знаходиться в постійній облозі. Без підкріпленнь нам не вистояти. Я довіряю тобі надзвичайно важливий лист. Передай цей звіт генералу Марку Джонатану в Штормовій. І якнайшвидше повертайся зі звісткою — неважливо, доброю чи злою.\n\nПоквапся!", [3] = "Війт Соломон просить вас віднести звіт генералу Марку Джонатану в Штормовій.", [4] = "Що там у тебе?", [5] = "Вільно, {клас:к}.\n\nМагістрат Соломон — благородний лідер. Його слова багато для мене значать. Я поговорю з королем і поясню йому ситуацію. Передай доброму судді, що він отримає підтримку армії Штормовію. Я надішлю підкріплення, щойно отримаю наказ Його Величності.", ["en"] = "Messenger to Stormwind", ["tasks"] = { ["The State of Lakeshire"] = "звіт Приозер'я", ["The State of Lakeshire (Provided)"] = "звіт Приозер'я (видано)" } },
    [1204] = { [1] = "Суп з болотяних черепах з жуками", [2] = "Я працюю над новою стравою, яку я назвав \"Суп з болотяних черепах з жуками\". Мені все ще не вистачає основних інгредієнтів, і... Я не думаю, що зможу вижити, продираючись через Бруднолипку трясовину!\n\nТак от, {ім'я}, чи можеш ти піти на полювання замість мене? Для початку мені потрібні язики болотяних черепах. Ти знайдеш їх вздовж узбережжя, переважно навколо бухти.\n\nАле мені не потрібні звичайні язики! Я чув, що язики деяких болотяних черепах роздвоєні...\n\nКажуть, що роздвоєні язики мають особливий смак, і я хочу, щоб цей смак був у моїй страві...", [3] = "Принесіть 8 роздвоєних язиків болотяних черепах Моргану Штерну в Терамор.", [4] = "Ти {стать:знайшов:знайшла} роздвоєні язики черепах?", [5] = "Ці підійдуть! Дякую, {ім'я}!\n\nТепер я спробую різні техніки приготування цих язиків, щоб знайти найкращий спосіб розкрити їхній смак.\n\nВрешті-решт у мене вийде страва, гідна подачі в \"Синьому Відлюднику\"!", ["en"] = "Mudrock Soup and Bugs", ["tasks"] = { ["Forked Mudrock Tongue"] = "роздвоєний язик болотяної черепахи", ["Forked Mudrock Tongue (Provided)"] = "роздвоєний язик болотяної черепахи (видано)" } },
    [121] = { [1] = "Посланець до Штормовію", [2] = "Поки я чекаю відповіді від короля, я хочу, щоб ти {стать:передав:передала} цього листа війту Соломону.\n\nВільно, {клас:к}!", [3] = "Передайте лист з відповіддю генерала Марка Джонатана війту Соломону в Приозер'я.", [4] = "Є новини від генерала? Підкріплення вже в дорозі?", [5] = "Дякую за твій час, {клас:к}. За твою службу Приозер'ю та Штормовію прийми цю оплату.\n\nТепер, вибач, але мені здається, що зміст цього листа дещо загадковий. Щось не так у нашому королівстві. Я боюся, що це лише початок війни, а не кінець.", ["en"] = "Messenger to Stormwind", ["tasks"] = { ["The General's Response"] = "відповідь генерала", ["The General's Response (Provided)"] = "відповідь генерала (видано)" } },
    [122] = { [1] = "Черевна луска", [2] = "Мені потрібна черевна луска з дитинчат чорних драконів, щоб заплатити Арґусу за підкови. Якщо ти зможеш дістати для мене 6 таких лусок, то я зможу заплатити Арґусу... І для тебе щось зроблю.\n\nДитинчата чорних драконів часто літають на півдні від Приозер'я, але вони не сидять на одному місці. Найпростіше просто бути напоготові й полювати на них, коли буде нагода.", [3] = "Зберіть 6 черевних лусок з дитинчат чорних драконів та принесіть їх Вернеру Осґуду в Багрянокряжжя.", [4] = "Якщо я не віддам луску Арґусу, він пришле за нею когось іншого. Ти вже {стать:зібрав:зібрала} луску?", [5] = "Дякую! Тепер я зможу розплатитись з Арґусом...", ["en"] = "Underbelly Scales", ["tasks"] = { ["Underbelly Whelp Scale"] = "підчеревна луска дракончика", ["Underbelly Whelp Scale (Provided)"] = "підчеревна луска дракончика (видано)" } },
    [1222] = { [1] = "Втеча Смердючки", [2] = "Чудово, нарешті знайшовся хтось, хто не хоче з'їсти мене!\n\nМені потрібна допомога, щоб розібратися з тутешніми звірами, а ти якраз підходиш, {стать:приятелю:приятелько}.\n\nКухар Морган Штерн досліджує новий рецепт і послав мене зібрати листя болотних бобів. Гадаю, він вважає їх смачними.\n\nВ будь-якому разі, під час пошуку болотних бобів... Мене оточили! Зможеш допомогти мені вибратися звідси та прикрити мене, поки я шукатиму ці боби?", [3] = "Проведіть \"Смердючку\" Іґнаца, після чого поговоріть з Морганом Штерном у Тераморі.", [4] = "Ти {стать:бачив:бачила} містера Іґнаца? Я відправив його в болото, а він досі не повернувся!", [5] = "Містер Іґнац нещодавно був тут з листям болотних бобів, і він розповів мені, що ти {стать:допоміг:допомогла} йому в скрутній ситуації.\n\nДякую, {ім'я}. Я попрошу свого дядька пригостити тебе ситною вечерею, коли ти наступного разу завітаєш до \"Синього Відлюдника\" в Штормовії.", ["en"] = "Stinky's Escape", ["tasks"] = { ["Help Stinky find Bogbean Leaves"] = "Допоможіть Смердючому знайти Листя Богобана" } },
    [123] = { [1] = "Збирач", [2] = "Ця записка — графік із переліком днів та часу, коли людина, названа «Збирачем», отримує вантаж золота з шахт у Ельвиннському лісі.\n\nСудячи з розкладу, Збирач проживає біля гарбузового наділу Бреквелів в східному Ельвинні.\n\nЦе звучить важливо. Вам варто повідомити про це маршалові Дугану в Злотохресті.", [3] = "Йдіть до маршала Дугана в Злотохрестя та передайте йому розклад Збирача.", [4] = "Що?!? Вже декілька місяців у шахтах Ельвинну не працювали наші люди!\n\nДай-но гляну на твою записку...", [5] = "Гм... Я чув про цього \"Збирача\", але не знаю, на кого він працює. Дякую за розклад. Він допоможе нам розгадати цю таємницю.", ["en"] = "The Collector", ["tasks"] = { ["The Collector's Schedule"] = "розклад Збирача", ["The Collector's Schedule (Provided)"] = "розклад Збирача (видано)" } },
    [124] = { [1] = "Гавкіт гнолів", [2] = "Ніби нападів орків було не досить! Тепер ще й гнолячі моцаки й містики снують по кряжу на північ від моїх стаєнь і забирають моїх бродячих коней...\n\nМи з конями будемо дуже вдячні, якщо тобі вдасться позбутися цих гнолів.", [3] = "Вбийте 10 багрянокряжових моцаків та 8 багрянокряжових містиків, після чого поверніться до Вернера Осґуда.", [4] = "Схоже мої коні все ще налякані, а я досі чую те кляте вовче виття уночі. Прошу, {ім'я}, зроби щось із тими гнолами!", [5] = "Дякую тобі за поміч, {ім'я}.", ["en"] = "A Baying of Gnolls", ["tasks"] = { ["Redridge Brute"] = "багрянокряжовий моцак", ["Redridge Brute slain"] = "багрянокряжовий моцак: убито", ["Redridge Mystic"] = "багрянокряжовий містик", ["Redridge Mystic slain"] = "багрянокряжовий містик: убито" } },
    [1241] = { [1] = "Зниклий дипломат", [2] = "Нещодавно одного з наших дипломатів відправили до Джайни Праудмур. Але він так і не дістався до Терамора.\n\nЯ думав, це справа рук Непокірних, та зараз я не впевнений. Ми поки що успішно приховуємо це від розголосу, але так не може тривати довго.\n\nАгенти Короля вже нишпорять містом у пошуках підказок, але я хотів би залучити свої зв'язки.\n\nУ Долині Героїв ти знайдеш мого старого друга, на ім'я Йорген. Передай йому цю записку та виконуй його вказівки.", [3] = "Знайдіть Йоргена в Штормовії.", [4] = "Хм... Сподіваюсь у тебе є вагома причина, щоб відривати мене він риболовлі. Я не купую всіляку дурню і не подаю жебракам.", [5] = "Хмм... <Йорген дивиться на вас, примруживши очі.>\n\nДобре. Я допоможу тобі, та тільки тому, що я маю борг перед Делавеєм.\n\nВідразу проясню одну річ: ти вже забагато знаєш. Тримай рота на замку і не ляпни зайвого у всіляких тавернах.", ["en"] = "The Missing Diplomat", ["tasks"] = { ["Letter to Jorgen"] = "лист до Йорґена", ["Letter to Jorgen (Provided)"] = "лист до Йорґена (видано)" } },
    [1242] = { [1] = "Зниклий дипломат", [2] = "Віднеси цю записку Еллінгу Тріасу. Нічого йому не розказуй, просто будь {стать:ввічливим:ввічливою} та дочекайся його відповіді.\n\nПро всяк випадок нагадаю тобі, {ім'я}: справа серйозна, тож тримай рота на замку.\n\nТи знайдеш Тріаса в його сирній крамниці, \"Сири Тріаса\", що в торговому районі. Нехай щастить.", [3] = "Доставте запечатану записку Йоргена Еллінгу Тріасу в Штормовій.", [4] = "Вітаю, {ім'я}. Чим я можу тобі допомогти? Можливо, тебе зацікавить наш особливий чедер? Чи, може, дарнаський блю?", [5] = "Що? Лист для мене? Що ж... нечасто мені сюди доставляють щось, крім ящиків чи бочок. Що ж, поглянемо...\n\n<Еллінг дивиться на вас, поки відкриває листа.>\n\nТи {стать:якийсь напружений:якась напружена}. Ти в порядку, {ім'я}?", ["en"] = "The Missing Diplomat", ["tasks"] = { ["Sealed Note to Elling"] = "запечатана записка для Еллінга", ["Sealed Note to Elling (Provided)"] = "запечатана записка для Еллінга (видано)" } },
    [1243] = { [1] = "Зниклий дипломат", [2] = "Йорген, трясця його... Ну і що з цим робити?\n\nНу добре, розберемось. Щоб він проваливсь!\n\nОт, що буде далі, {ім'я:к}. Я залучу всі мої тутешні зв'язки, а тобі доведеться трохи побігати.\n\nПрямуй до Темнодолу, що в Смерколіссі, та знайди вартового Бакуса. Він зазвичай патрулює дорогу на північ від міста. Просто скажи йому, що ти шукаєш інформацію про Непокірних для мене і він з радістю допоможе.", [3] = "Віддайте запечатану записку вартовому Бакусу в Смерколісся.", [4] = "Цей ліс небезпечний, {клас:к}. Будь {стать:обережний:обережна} і якщо побачиш щось підозріле чи небезпечне — повідом вартових. Не намагайся розібратись самотужки. Якщо з тобою щось станеться — ми відповідальності не несемо.\n\nТа ми обоє знаємо, що це тебе не зупинить і ти битимешся з будь-чим, що вилізе з темряви. Хе-хе, так, всі ви, шукачі пригод, однакові.", [5] = "То тебе Тріас прислав? Це вже інша справа.\n\nМожеш битись з чудовиськами скільки душа забажає. Ти легко з ними впораєшся, якщо працюєш з такими, як він.\n\nТо що моєму другу потрібно від мене в цей похмурий день?", ["en"] = "The Missing Diplomat", ["tasks"] = { ["Sealed Note to Watcher Backus"] = "запечатана записка для наглядача Бакуса", ["Sealed Note to Watcher Backus (Provided)"] = "запечатана записка для наглядача Бакуса (видано)" } },
    [1244] = { [1] = "Зниклий дипломат", [2] = "Знову Непокірні? Що ж, вони завжди щось затівають. Навіть коли про них нічого не чути, ми не розслабляємось.\n\nДо речі, це мені нагадало про одну дивну річ. Кілька тижнів тому кілька з них нишпорили біля ферми Еддла. Певно, вони щось затівали.\n\nЧому б тобі не оглянути ферму і не дізнатись більше?\n\nВона знаходиться на південь від дороги на Західний край. Прямо перед виходом зі Смерколісся.", [3] = "Знайдіть плани Непокірних та поверніть їх вартовому Бакусу в Смерколісся.", [4] = "Будь {стать:обережний:обережна}, {ім'я:к}. Хоч тебе й прислав Тріас, та це не означає, що ліс не становить для тебе небезпеки... Особливо, якщо ти розслідуєш справи Непокірних.", [5] = "Ти {стать:повернувся цілим і неушкодженим:повернулась цілою і неушкодженою}. Вже непогано, правда?\n\nНу, що тут в тебе? Це схоже на справжні документи Непокірних. Та це може бути й підробка, якою вони намагаються збити тебе зі сліду.", ["en"] = "The Missing Diplomat", ["tasks"] = { ["Defias Docket"] = "плани Непокірних", ["Defias Docket (Provided)"] = "плани Непокірних (видано)" } },
    [1245] = { [1] = "Зниклий дипломат", [2] = "Ого, виглядає надто складно, як для приманки. Та я навіть не маю цього бачити. Віднеси ці папери Тріасу — він зможе щось зрозуміти. І нікому про це не кажи. Це не моя справа. А може й не його, побачимо.\n\nІ прошу, {ім'я}, не кажи нікому, що я допоміг тобі. Якщо моє начальство дізнається, що я знав про це і не доповів їм — мене можуть стратити.", [3] = "Принесіть плани Непокірних Еллінгу Тріасу в Штормовій.", [4] = "Бачу, ти {стать:повернувся:повернулась}, ще й {стать:живим:живою}. Ми обоє знаємо, що ти тут не за сиром, тож давай без формальностей. Бакус допоміг тобі, чи ти ще не {стать:ходив:ходила} до Смерколісся?", [5] = "Так... це цікаво. Йорген та Делавей не дарма мене вплутали.\n\nСхоже, що Непокірні затіяли щось серйозне. Хм... що це? \"Кулак\"? Знайоме ім'я...", ["en"] = "The Missing Diplomat", ["tasks"] = { ["Defias Docket"] = "плани Непокірних", ["Defias Docket (Provided)"] = "плани Непокірних (видано)" } },
    [1246] = { [1] = "Зниклий дипломат", [2] = "Так, тепер мені спало на думку... Дешель... Дешель якось-там... Як його прізвище? КУЛАК! Дешель Кам'яний Кулак. Його називають Кулаком в деяких колах. Певно тому, що він полюбляє бійки.\n\nЙого зазвичай можна знайти в Старому Місті, прямо в центрі. Йди й поговори з ним. Якщо доведеться — використай меч чи ще щось важке, щоб змусити його говорити. І не вагайся. Якщо це той самий Кулак, про якого йдеться в цих паперах — він так просто не здасться.", [3] = "Поговоріть з Дешелем Кам'яним Кулаком в Штормовії.", [5] = "Що?!\n\nТи приходиш до мене і сунеш носа в мої справи? Це тебе не стосується!", ["en"] = "The Missing Diplomat" },
    [1247] = { [1] = "Зниклий дипломат", [2] = "Ну... ммм... так, я знаю дещо про зустріч на фермі Еддла. Це було тижні зо два тому. Але мене там не було. Моя участь закінчилась з провалом плану А... кляті шукачі пригод.\n\nХлопчина, який мав займатись планом Б прибув з Менетілу. Його звали Пронирою. Це все, що мені відомо про запасний план.", [3] = "Поговоріть з Еллінгом Тріасом в Штормовії.", [5] = "Радий бачити, що ти досі {стать:живий:жива}. Тож з Дешелєм все пройшло добре?\n\nЯ тут проглядав папери і, хоч тут і не згадується ім'я дипломата, але йдеться про план Б, до якого вони мають перейти, якщо не зможуть схопити його з першої спроби.\n\nПро цього Прониру, котрого згадував Дешель, тут нічого не написано. Та якщо ти кажеш, що він з Менетілу, то туди нам і треба.", ["en"] = "The Missing Diplomat" },
    [1248] = { [1] = "Зниклий дипломат", [2] = "Один мій старий знайомий насолоджується відставкою у гавані Менетілів. Він з радістю допоможе тобі, якщо ти скажеш, що працюєш на мене. Його звать Михайль. Здається, перед тим, як покинути Штормовій кілька років тому, він казав, що стане барменом.\n\nПоговори з ним, знайди Прониру і довідайся все, що зможеш про цього викраденого дипломата. Ми маємо дізнатись, що вони з ним зробили чи, хоча б, хто він такий. В документах нічого не сказано про їх плани після викрадення.", [3] = "Поговоріть з Михайлем у Заболотті.", [5] = "Вітаю в нашій таверні, {ім'я}. Раді вас бачити! Чи не бажаєте елю? Чи, може, баранини?\n\nСкажіть, чого бажаєте і ми неодмінно виконаємо всі ваші побажання. Мене звати Михайль, і я з радістю обслужу вас.\n\nМм? Що це? Тріас? Тихше, прошу вас. Моїм відвідувачам не обов'язково знати про це.", ["en"] = "The Missing Diplomat" },
    [1249] = { [1] = "Зниклий дипломат", [2] = "То вас прислав Еллінг? Що ж, тоді можете просити про все, чого бажаєте, я зроблю все можливе.\n\nХмм, Пронира, кажете? Не певен, чи чув це ім'я, але спробую дізнатись більше.\n\nНе обертайтесь, {ім'я}. Той джентльмен, що біля виходу, поглядає на нас. Якось він занадто уважно підслуховує. На вашому місці, я б скоріше впіймав його, поки він не втік.", [3] = "Зупиніть Яна Тапокі, поки він не втік та поверніться до Михайля в гавань Менетілів.", [4] = "Вдалось впіймати? Якось надто похмуро він дививсь на нас.", [5] = "Впіймали його? Чудово. А це був той самий Пронира!\n\nЧесно кажучи, я й не думав, що буду радий знову взяти участь у всій цій таємній діяльності. Старі звички дають про себе знати. Не кажіть про це Еллінгу, а то він знову затягне мене в Штормовій.\n\nЯ радий допомогти вам з цією пригодою в Менетілі. Якщо вам ще щось знадобиться — просто скажіть.", ["en"] = "The Missing Diplomat", ["tasks"] = { ["Defeat Tapoke Jahn"] = "Перемога над Тапоке Джаном" } },
    [125] = { [1] = "Втрачені інструменти", [2] = "Мені б не завадила твоя допомога, {ім'я}. Коли місто було в облозі, нам було важко отримати припаси. Мої інструменти везли з Злотохрестя возом, але міст підірвали. Ми перевантажили їх у човен, але орки влучили в нього з катапульти. Отака моя вдача, мої інструменти лежить на дні озера.\n\nДістань їх, {ім'я}, і я щедро віддячу тобі.", [3] = "Десятник Ослоу з Приозер'я просить вас дістати його набір інструментів з дна Безхвильного озера.", [4] = "Тобі вдалось знайти мої інструменти?", [5] = "Чудова робота, {ім'я}! Я вже й не сподівався побачити їх знову.", ["en"] = "The Lost Tools", ["tasks"] = { ["Oslow's Toolbox"] = "інструменти Ослоу", ["Oslow's Toolbox (Provided)"] = "інструменти Ослоу (видано)" } },
    [1250] = { [1] = "Зниклий дипломат", [2] = "Непокірні не платять мені стільки, щоб я за них вмер. Вони схопили короля. Так, короля Штормовію, а не якогось там звичайного дипломата. Він прямував до Терамору на зустріч з Джайною Праудмур. Це було щось дуже важливе і таємне. Та до цього причетні не лише Непокірні. Вони працюють ще з кимось, могутнішим за них.\n\nЯ мав лише допомогти їх людині потрапити на корабель короля, поки той стояв у гавані. Його звали Гіндель. Це все, що я знаю. Присягаюсь!", [3] = "Поговоріть з Михайлем у Заболотті.", [5] = "КОРОЛЬ? Кхм, тобто... король? Справжній король Штормовію? Жартуєте? Ви не казали, що шукаєте викрадачів короля. Я навіть не знав, що він пропав. Тепер зрозуміло, чому його сина коронували.\n\nЯ відправлю Еллінгу звістку. Він має знати про все, що ви тут дізнались.\n\nЯ б і не подумав, що Ян може так просто зрадити Штормовій. Навіть у пройдисвітів більше честі в таких справах.\n\nТепер потрібно знайти цього Гінделя. І я можу з цим допомогти.", ["en"] = "The Missing Diplomat" },
    [1252] = { [1] = "Лейтенант Павал Ріт", [2] = "Блиск на землі привертає вашу увагу, і ви помічаєте під завалами блискучий предмет. Обтерши його від сміття й попелу, ви розумієте, що це знак Терамора — золотий якір на білому фоні.\n\nПід якорем викарбувано ім'я \"Лейтенант Павал Ріт\".", [3] = "Принесіть жетон Ріта капітану Ґаррану Ваймсу в Терамор.", [4] = "Вдалось знайти щось цікаве на руїнах таверни «Відпочинок у затінку»?", [5] = "Це завжди погана новина, коли мені приносять жетон вартового.\n\nІноді вони гинуть в битві, і мені доводиться повідомляти про їх долю сім'ї та близьким... Іноді ми так і не дізнаємося, що з ними стало. А іноді знаємо, і це ще гірше...", ["en"] = "Lieutenant Paval Reethe", ["tasks"] = { ["Reethe's Badge"] = "жетон Ріта", ["Reethe's Badge (Provided)"] = "жетон Ріта (видано)" } },
    [1253] = { [1] = "Чорний щит", [2] = "Залізний щит, почорнілий від пожежі, що вирувала в таверні, прикріплений до зруйнованого каміна, однієї з небагатьох вцілілих частин споруди, яка колись була таверною «Відпочинок у затінку».\n\nЩит можна зняти.", [3] = "Принесіть почорнілий залізний щит капітану Ґаррану Ваймсу в Терамор.", [4] = "Ти {стать:знайшов:знайшла} зачіпки на руїнах таверни «Відпочинок у затінку»?", [5] = "Хм, я не експерт у куванні зброї та обладунків. У їх використанні — так, але не у виготовленні.\n\nЦей щит виглядає таким же звичайним, як і будь-який інший, за винятком пошкоджень від пожежі, що охопила таверну.", ["en"] = "The Black Shield", ["tasks"] = { ["Blackened Iron Shield"] = "почорнілий залізний щит", ["Blackened Iron Shield (Provided)"] = "почорнілий залізний щит (видано)" } },
    [1258] = { [1] = "... і жуки", [2] = "Ще один інгредієнт моєї нової страви — це лапа гігантського краба. І краби з Бруднолипкої трясовини — бруднорпанцирники, як їх називають — мені не підходять! Я боюсь, що підійдуть лише краби, що живуть далеко, на болоті Скорбот.\n\nПанцир крабової лапи — ключовий елемент презентації страви, тому мені потрібні непошкоджені, бездоганні лапи. Дорослий краб може мати лише одну-дві такі лапи, а для моїх кулінарних експериментів їх потрібно набагато більше.\n\nТак от, {ім'я}... чи {стать:готовий:готова} ти до подорожі?", [3] = "Принесіть 12 бездоганних лап повзунів Моргану Штерну в Терамор.", [4] = "Мої експерименти з черепашачими язиками приносять плоди. Сподіваюсь, твоє полювання на крабів проходить вдало?", [5] = "Це чудові екземпляри, {ім'я}! Панцир в ідеальному стані, а м'ясо рожеве і ніжне. У твоїх жилах тече кров шеф-кухаря, я в цьому впевнений!", ["en"] = "... and Bugs", ["tasks"] = { ["Pristine Crawler Leg"] = "бездоганна лапа повзуна", ["Pristine Crawler Leg (Provided)"] = "бездоганна лапа повзуна (видано)" } },
    [1259] = { [1] = "Лейтенант Павал Ріт", [2] = "Мені не знайомий лейтенант на ім'я Павал Ріт. Тобі краще звернутися до ад'ютанта Тесорана. У нього є записи про варту Терамору: від самих вартових до їхнього спорядження.\n\nВін зможе швидко знайти інформацію про цього Ріті, перевіривши свої книги.", [3] = "Дізнайтеся більше про Ріта в ад'ютанта Тесорана в Тераморі.", [5] = "Привіт, {ім'я}. То тобі потрібна інформація про вартового Терамора? Ріт, так?\n\nДай мені хвилинку, я знайду потрібні записи.", ["en"] = "Lieutenant Paval Reethe" },
    [1264] = { [1] = "Зниклий дипломат", [2] = "На початку кожного місяця моряки Кул-Тірасу отримують зарплату і зазвичай покидають Терамор. Багато з них прибувають сюди, щоб випити, розважитись і просто добре провести час. Одна така компанія часто сидить в цій таверні й, здається, серед них є той самий Гіндель.\n\nКомандир Самол з Терамору зможе допомогти вам знайти Гінделя, якщо той все ще там. Самол цілком відданий Праудмурам, але якщо скажете, що ви від Еллінга, з ним можна буде домовитись.", [3] = "Знайдіть командира Самола в Бруднолипкій трясовині.", [5] = "Приємно познайомитись, {ім'я}. Я командир Самол, і я керую військами міс Праудмур, що знаходяться в Тераморі.\n\nХоч я й трохи зайнятий, але якщо потрібна моя допомога — кажи. Багато не обіцяю, але допоможу, чим зможу.\n\nЯкщо збираєшся відправитись за місто — будь {стать:обережний:обережна}. Окрім огрів, орків та мурлоків, в південній частині болота поселились чорні дракони.", ["en"] = "The Missing Diplomat" },
    [1265] = { [1] = "Зниклий дипломат", [2] = "Гіндель? Так, я його знаю. Але нащо тобі один з наших солдатів?\n\nТебе прислав Еллінг? Хмм, не подобається це мені. Він не відправив би тебе до мене, якби все було гаразд. Ти звісно можеш мені нічого не розказувати, та знай, що мій обов'язок — захищати ці землі. Якщо збираєшся порушити спокій Терамору — краще розкажи мені про це зараз.\n\nЗдається, Гіндель має бути в першій від Терамору вежі", [3] = "Огляньте караульну вежу в пошуках слідів рядового Гінделя.", [4] = "Так, {ім'я}?", [5] = "Чоловіка, якого ти шукаєш, тут немає. Я так розумію, ти вже знаєш все те ж саме, про що доповіли леді Праудмур її джерела. Вона попросила мене знайти тебе і запропонувати допомогу. Якщо {стать:згоден:згодна}, я розкажу тобі, де ти зможеш знайти Гінделя, щоб притягнути його до відповідальності.", ["en"] = "The Missing Diplomat", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Sentry Point explored"] = "Досліджено Сентрі-Пойнт" } },
    [1266] = { [1] = "Зниклий дипломат", [2] = "Рядовий Гіндель знаходиться на захід звідси. Його загін займається охороною розвідників Терамора, поки ті відпочивають. Вони намагаються визначити розташування бази Орди — селища Папорохащі, а заодно й наглядають за кордонами.\n\nТи легко знайдеш їх — просто шукай табір біля дороги.\n\nУ мене є ще одна справа, тож я тебе наздожену пізніше. Але якщо я знадоблюсь — ти завжди можеш знайти мене у вежі леді Праудмур.", [3] = "Знайдіть рядового Гінделя в Бруднолипкій трясовині.", [5] = "Вітаю, {стать:пане:пані}. Це не найкраще місце для прогулянок. На вашому місті, я б тут не затримувався.\n\nЯкщо потрібна допомога — я до ваших послуг. Тільки не забувайте озиратись, чи не ховаються де ці мерзенні огри. Ходять чутки, що десь тут неподалік знаходиться база Орди. Розвідники намагаються знайти її, та справа йде повільно.", ["en"] = "The Missing Diplomat" },
    [1267] = { [1] = "Зниклий дипломат", [3] = "Поговоріть з Джайною Праудмур в Бруднолипкій трясовині.", [5] = "Дозволь мені подякувати тобі за все, що ти {стать:зробив:зробила}, {ім'я}.Ти неймовірно {стать:допоміг:допомогла} моїм людям та людям Штормовію. Шкода, що ми не зустрілись за кращих обставин.\n\nСподіваюсь, ти розумієш, що я не зможу публічно віддячити тобі.\n\nТа як будеш в Тераморі — зайди до мене і я вручу тобі винагороду.\n\nЩе раз дякую тобі, {ім'я}.", ["en"] = "The Missing Diplomat" },
    [127] = { [1] = "Продаж риби", [2] = "Безхвильне озеро славиться своєю плямистою сонцерибою. На неї завжди є попит... а у мене закінчуються її запаси!\n\nПринеси мені 10 рибин, і я добре за них заплачу. Якщо не вмієш рибалити, то... можеш відібрати її у мурлоків!", [3] = "Принесіть 10 плямистих сонцериб начальнику доку Барену в Приозер'я.", [4] = "Ну як, {стать:дістав:дістала} для мене сонцерибу?", [5] = "Приємно мати справи з тобою, {стать:друже:подруго}!", ["en"] = "Selling Fish", ["tasks"] = { ["Spotted Sunfish"] = "плямиста сонцериба", ["Spotted Sunfish (Provided)"] = "плямиста сонцериба (видано)" } },
    [1271] = { [1] = "Бенкет в Синьому Відлюднику", [5] = "Мій племінник сказав, що ти {стать:допоміг:допомогла} йому з дослідженням в Бруднолипкій трясовині та {стать:витяг:витягла} його знайомого з біди. Ми, Штерни, підтримуємо один одного та піклуємося про наших друзів!\n\nТож мий руки, {ім'я}, бо ми збираємося влаштувати вечірку на твою честь!", ["en"] = "Feast at the Blue Recluse" },
    [1274] = { [1] = "Зниклий дипломат", [2] = "Перепрошую, {стать:пане:пані}. Єпископ Делавей попросив мене знайти шукачів пригод, що можуть допомогти йому з... досить делікатною справою.\n\nЯкщо ви зможете якомога скоріше пройти у фортецю Штормовію та поговорити з ним, впевнений, він буде вдячний. Але, будь ласка, тримайте це в таємниці. Це надзвичайно важлива справа.", [3] = "Знайдіть єпископа Делавея у фортеці Штормовію.", [5] = "Вітаю, {ім'я}. Я єпископ Делавей.\n\nПевно ти тут тому, що Томасу вдалось передати тобі моє прохання. Він завжди відповідально ставився до моїх прохань.\n\nНа жаль, в мене немає часу на зайві балачки, тож я розкажу коротко... і прошу, не розказуй про це нікому.", ["en"] = "The Missing Diplomat" },
    [128] = { [1] = "Нагорода за Чорнокамінь", [2] = "Клан Чорнокаменю треба знищити. Ворог вдерся в наші землі. Ці гори підпадають під суверенне право короля Штормовію. Наші джерела повідомляють, що лідери кожного загону в клані відомі як чемпіони. Ти знайдеш їхній табір на півночі, на захід від шляху до Палаючого степу.\n\nВійт Соломон хоче цих головорізів мертвими. Виріж 15 чемпіонів Чорнокаменю і повертайся до мене.", [3] = "Убийте 15 чемпіонів Чорнокаменю і вартовий Гау в Приозер'ї нагородить вас.", [4] = "Повертайся, коли вб'єш 15 чемпіонів Чорнокаменю.", [5] = "Я бачу, ти звитяжно {стать:бився:билась} з кланом Чорнокаменю, {клас:к}. Воістину ти сильно {стать:прислужився:прислужилась} нашому містечку.", ["en"] = "Blackrock Bounty", ["tasks"] = { ["Blackrock Champion"] = "чемпіон Чорнокаменю", ["Blackrock Champion slain"] = "чемпіон Чорнокаменю: убито" } },
    [1282] = { [1] = "Його звуть Усміхнений Джим", [2] = "Мені так шкода Джима. Він не завжди був таким. Колись він тримав таверну на болотах, чудове місце було.\n\nСлухай, я не дуже хочу про це говорити. Якщо тобі це вже так потрібно — поговори з капітаном Ваймсом.", [3] = "Поговоріть з капітаном Ґарраном Ваймсом в Тераморі.", [5] = "Джеймс Хіал — його справжнє ім'я. Він відкрив таверну на кордоні Степів, хотів зробити затишне місце для відпочинку мандрівників...\n\nМожливо, він хотів надто багато, але деякий час справи в таверні йшли добре. А потім ми втратили контроль над дорогами в болоті, і там почали вештатись огри.\n\nДжеймс був занадто упертим, щоб відмовитися від своєї мрії заради безпеки, і таверну «Відпочинок у затінку» спалили дотла. Ми проводимо розслідування, але досі марно. Якщо хочеш допомогти — спробуй знайти щось серед руїн.", ["en"] = "They Call Him Smiling Jim" },
    [1284] = { [1] = "Підозрілі сліди копит", [2] = "Сліди копит ведуть від все ще тліючих руїн таверни «Відпочинок у затінку». Є принаймні кілька чітких відбитків і багато інших слідів, ледве помітних на м'якому болотистому ґрунті.", [3] = "Повідомте про підозрілі сліди в таверні «Відпочинок у затінку» капітана Ґаррана Ваймса в Тераморі.", [5] = "Сліди копит, ге? Дійсно, останнім часом у землях біля Бруднолипкої трясовини заворушилися кентаври. Під час коротких вилазок до Степів ми помітили кілька їхніх таборів та поселень.\n\nЯ пошлю Фальґрана Гастіла, одного з наших пантрувачів, подивитися, куди ведуть ці сліди.", ["en"] = "Suspicious Hoofprints" },
    [1285] = { [1] = "Солдати Дейліна", [2] = "Реддон... Редпат... Ага, ось він! Лейтенант Павал Ріт.\n\nПриєднався до гарнізону Терамору разом з іншими рекрутами, що перетнули море з леді Праудмур. Зачислений до морської піхоти Кул-Тірасу у віці шістнадцяти років. Відзначився у службі, отримав підвищення...\n\nЗаписаний зниклим безвісти.", [3] = "Поверніться з інформацію про Ріта до капітана Ґаррана Ваймса в Терамор.", [5] = "Зник? У перекладі з Тесоранської, це означає — зрадник.\n\nНе сумніваюся, що це один з тих дурнів, сліпо відданих адміралу Дейліну. Кумедно, правда? Дезертири звинувачують нас у зраді Альянсу.", ["en"] = "Daelin's Men" },
    [1286] = { [1] = "Дезертири", [2] = "Нам доводиться вести постійну боротьбу за існування на болоті, але завдяки нашій силі волі, нам вдалося зберегти кілька оборонних веж.\n\nОстанні доповіді розвідників свідчать про те, що група дезертирів засіла в нашій покинутій вежі на Зруйнованій заставі, на південний схід від таверни.\n\nЛідер дезертирів — чоловік, на ім'я Джекен. Спробуй дізнатися у нього якусь інформацію.\n\nПопереджаю, {ім'я}. Він може бути досить впертим.", [3] = "Отримайте інформацію про Ріта у Балоса Джекена та дезертирів в Бруднолипкій трясовині.", [5] = "Тебе Ваймс прислав? Не хоче сам братися за брудну роботу, ге?", ["en"] = "The Deserters" },
    [129] = { [1] = "Безкоштовний обід", [2] = "Можеш мені допомогти? Я приготувала обід для вартового Паркера, проте він зараз на патрулюванні... Це великий сильний вартовий Штормовія. Він у змозі захистити себе, але для такої городянки, як я, там ззовні надто небезпечно.\n\nТож якщо ти доставиш йому полуденок, повертайся до мене, і я безкоштовно почастую тебе обідом! Паркер патрулює біля дороги, що веде до Смерколісся.", [3] = "Принесіть вартовому Паркеру його обід. Він патрулює дорогу що веде в Темноділ.", [4] = "Дарсі надіслала мені полуденок, справді? В неї таке добре серце. Що ж... нумо обідати!", [5] = "Дякую, їжа дійсно знадобилася. Вартувати Приозер'я від орків і гнолів це тяжка праця!", ["en"] = "A Free Lunch", ["tasks"] = { ["Parker's Lunch"] = "обід Паркера", ["Parker's Lunch (Provided)"] = "обід Паркера (видано)" } },
    [13] = { [1] = "Народне ополчення", [2] = "Банда злісних грабіжників з Братства Непокірних помічена у розоренні кар'єру Золотого берега, Місяцеграю та садиби Алекстона. Народне ополчення не терпітиме такого. Вирушай негайно, {ім'я}, і покажи присутність Світла всьому Західному краю.\n\nКар'єр Золотого берега розташований неподалік від узбережжя, на захід від вежі. Як наступний крок твого навчання, я хочу, щоб ти {стать:вбив:вбила} 15 грабіжників і 15 здобичників з Братства Непокірних.", [3] = "Ґріан Міцнокрив хоче, щоб ви вбили 15 грабіжників і 15 здобичників Непокірних та повернулися до нього на Сторожовий пагорб.", [4] = "У нас немає часу на балачки, {ім'я:к}. Грабіжники з Братства Непокірних позбавляють жителів Західного краю миру та процвітання, на які вони заслуговують. Переконайся в тому, що ти {стать:вбив:вбила} принаймні 15 грабіжників і 15 мародерів з Братства Непокірних. Це буде чітким натяком на те, що безчинство тут не вітають.", [5] = "Твою цінність для Народного ополчення підтверджено твоїми сміливими вчинками.", ["en"] = "The People's Militia", ["tasks"] = { ["Defias Looter slain"] = "здобичник Непокірних: убито", ["Defias Pillager slain"] = "грабіжник Непокірних: убито" } },
    [130] = { [1] = "Візит до травниці", [2] = "Поки ти не {стать:повернувся:повернулася} до Дарсі, не {стать:міг би:могла б} ти принести їй від мене трохи квітів? Дістати їх можеш у Приозер'ї, в крамниці травниці, що на західному краю міста.\n\nТа коли отримуватимеш квіти... Не кажи травниці, Марті, від кого вони чи для кого...", [3] = "Поговоріть з травницею Багрянокряжжя, Марті Джайнроуз.", [5] = "Тобі потрібен букет квітів? Ти не надто довго {стать:був:була} у місті... Вже {стать:знайшов:знайшла} собі тут {стать:кохану:коханого}?\n\nЗнаю, що не варто було допитуватися, але це чудово -- бачити, як кохання витає в повітрі... Особливо, в такі небезпечні часи.", ["en"] = "Visit the Herbalist" },
    [131] = { [1] = "Доставка нарцисів", [2] = "Ось твій букет. Для тебе я обрала нарциси. Вони мої улюблені!", [3] = "Віддайте Дарсі букет нарцисів.", [4] = "Знову привіт, {ім'я}. Паркеру сподобався мій обід?", [5] = "Ох, які вони чудові! Не дочекаюсь, коли покладу їх у воду!\n\nАле...це улюблені квіти Марті. Паркер часом не змусив тебе йти до цієї заздрісної лисиці? Ти ж не {стать:сказав:сказала} їй для кого ці квіти? Якщо {стать:сказав:сказала}, то не здивуюсь, якщо вони отруєні.\n\nОх, та це не твоя вина. Дякую, ось твій перекус.", ["en"] = "Delivering Daffodils", ["tasks"] = { ["Daffodil Bouquet"] = "букет нарцисів", ["Daffodil Bouquet (Provided)"] = "букет нарцисів (видано)" } },
    [1319] = { [1] = "Чорний щит", [2] = "Вибач, я не можу допомогти, {ім'я}, але я можу послати тебе до того, хто може. Каз Двокрут — один з наших кращих ковалів, який працює в місцевій кузні.\n\nВіднеси щит до нього і вислухай що він скаже.", [3] = "Покажіть почорнілий залізний щит Казу Двокруту в Тераморі.", [4] = "Ти щось мені {стать:приніс:принесла}?", [5] = "Хм... цікавий шматок залізяки. Очевидно, що його не зробив жоден із ковалів, яких я знаю по цей бік моря і це, безумовно, не моя робота.", ["en"] = "The Black Shield", ["tasks"] = { ["Blackened Iron Shield"] = "почорнілий залізний щит", ["Blackened Iron Shield (Provided)"] = "почорнілий залізний щит (видано)" } },
    [132] = { [1] = "Братство Непокірних", [2] = "Те, про що я хочу тобі розповісти, може коштувати мені життя. Банда Непокірних готує щось серйозне. Останнє, що я чув — вони діють спільно з усілякими гнолами, кобольдами та навіть гоблінами.\n\nВіднеси цю записку Міцнокривові. В ній роз'яснено все, що я знаю на цю тему.", [3] = "Віднесіть записку Вайлі Ґріанові Міцнокриву в Західний край.", [4] = "Приємно бачити тебе знову, {ім'я}. Так чим Вайлі збирався виправдовуватися?", [5] = "Ба! Я мав би залишити цього шахрая згнивати, коли у мене була така можливість. Але ця інформація надзвичайно важлива. Хороша робота.", ["en"] = "The Defias Brotherhood", ["tasks"] = { ["Wiley's Note"] = "записка Вайлі", ["Wiley's Note (Provided)"] = "записка Вайлі (видано)" } },
    [1320] = { [1] = "Чорний щит", [2] = "Ах, я ледь не пропустив це... Шкіряний ремінець на зворотному боці, згорів, але здається, що він був зроблений на велике тіло. Гадаю, це був щит таурена.\n\nЦе все, що я можу сказати. Скажи капітану Ваймсу, що мені шкода, але я не можу більше нічим допомогти.", [3] = "Поговоріть з капітаном Ґарраном Ваймсом в Тераморі.", [5] = "Дізнатися вдалося небагато, але ми повинні мати це на увазі. Будемо сподіватися, що інші частини цієї загадки незабаром проясняться і ми зможемо побачити повну картину того, що сталося.", ["en"] = "The Black Shield" },
    [1324] = { [1] = "Зниклий дипломат", [2] = "Що?! Ти звинувачуєш мене у співпраці з Непокірними? Я цього так просто не залишу! Втім, мене попереджали про тебе...", [3] = "Переможіть рядового Гінделя в Бруднолипкій трясовині.", [4] = "І знову привіт, {ім'я}. Сподіваюсь, ти не проти невеликої допомоги. Ми не могли дати Гінделю втекти чи, ще гірше, померти.", [5] = "Запевняю тебе, ми всі стривожені цими подіями. Але дозволь нам повернути його до Терамору, він має відповісти на кілька питань. Ми маємо дізнатись більше про короля.\n\nВпевнений, леді Праудмур захоже подякувати тобі за допомогу. Поговори з нею, якщо маєш хвилинку.", ["en"] = "The Missing Diplomat", ["tasks"] = { ["Subdue Private Hendel"] = "Приборкати рядового Генделя" } },
    [133] = { [1] = "Огидне опудало", [2] = "Я живу так далеко від міста, що дивно, як гулі та ходячі мерці мене ще не з'їли без захисту! Насправді ще вчора кілька кістожувів ломилися до мене в дім!\n\nЯ хочу зробити своєрідне опудало, щоб відлякувати їх. І для цього мені потрібні ребра гулів. Ти можеш зібрати їх у пожирачів плоті, кісткожувів, мізкоїдів, гниляків та розповсюдників чуми.\n\nПринеси мені ребра, а я віддячу тобі монетою.", [3] = "Зберіть 7 ребер гулів і принесіть їх Аберкромбі в його хатину.", [4] = "Здається, я чую гулів за будинком — мені треба скоріше встановити опудало! Ти {стать:знайшов:знайшла} ребра гулів для мене?", [5] = "О, дякую. Вони чудесно підійдуть для мого задуму!", ["en"] = "Ghoulish Effigy", ["tasks"] = { ["Ghoul Rib"] = "ребро гуля", ["Ghoul Rib (Provided)"] = "ребро гуля (видано)" } },
    [1338] = { [1] = "Замовлення Бурешпиля", [2] = "Є один дворфійський майстер обладунків, від чиєї роботи я в захваті. Його звати Фьюрен Довгоборід, і його навички неперевершені. Мені потрібен новий щит і я маю зробити замовлення!\n\nПроблема в тому, що він живе далеко на півдні, в Дворфійському районі Штормовію. В землях людей! Поняття не маю, нащо він забрався так далеко від Залізогарту. Певне, люди платять йому чимало, аби втримати його там!\n\nТож, якщо ти не проти невеликої подорожі та не проти трішки підзаробити, може доставиш Фьюрену моє замовлення?", [3] = "Віднесіть замовлення Бурешпиля Фьюрену Довгобороду в Штормовій.", [4] = "Лист з дворфійських земель? Цікаво, хто може писати мені з такої далечіні...\n\nДозволь мені поглянути на замовлення.", [5] = "А, замовлення від дворфа Бурешпиля. Це гордий клан славетних дворфів. А ще заможних.\n\nДякую тобі, {ім'я}. Я сьогодні ж почну працювати над щитом для горянина Бурешпиля.", ["en"] = "Stormpike's Order", ["tasks"] = { ["Bring Stormpike's Request to Furen Longbeard in Stormwind."] = "Віднесіть замовлення Бурешпиля Фьюрену Довгобороду в Штормовій.", ["Stormpike's Request"] = "замовлення Бурешпиля", ["Stormpike's Request (Provided)"] = "замовлення Бурешпиля (видано)" } },
    [1339] = { [1] = "Завдання горянина Бурешпиля", [2] = "Я чув, що горянин Бурешпиль шукає гінця, який виконав би його доручення. Як щодо тебе? Чи ти {стать:той самий:та сама} {клас:н}, {стать:який:яка} годиться для такої роботи?\n\nЯкщо це так, ти знайдеш Бурешпиля на вершині північної вартової вежі.", [3] = "Поговоріть з горянином Бурешпилем.", [5] = "Саме так. У мене є справа, яку я не зможу виконати, поки стою на посту. Насправді тобі доведеться відправитись далеченько від Лох-Модану.\n\nЗате це чудова нагода для пригод!", ["en"] = "Mountaineer Stormpike's Task" },
    [134] = { [1] = "Огри-злодії", [2] = "Декілька тижнів тому я збирав трави далеко від свого будинку і на мене напала група огрів! Я втік і був змушений залишити ящик з дорогоцінними інструментами та травами.\n\nВідігнавши мене, вони повернулися до своїх курганів на південному заході Смерколісся. Я впевнений, що мій ящик десь там.\n\nБудь ласка, {ім'я}, поверни мені ящик, я без нього як без рук.", [3] = "Поверніть Абекромбі його ящик.", [4] = "Мій ящик у тебе? Якщо так, то будь ласка... віддай мені його скоріше!", [5] = "Хвала Нек... Тобто тобі, {ім'я}! Ти більш ніж заслуговуєш на нагороду.\n\nАга! Який я щасливий! Попереду багато радісних ночей!!", ["en"] = "Ogre Thieves", ["tasks"] = { ["Abercrombie's Crate"] = "ящик Абекромбі", ["Abercrombie's Crate (Provided)"] = "ящик Абекромбі (видано)" } },
    [135] = { [1] = "Братство Непокірних", [2] = "Цікаво, що мав на увазі Вайлі, коли згадував про Каменярів. Можливо, обмовився або проговорився? Чи можуть розбійники з банди Непокірних бути пов'язані з Каменярами? Тільки одна людина знає напевне: Матіас Гич, голова ШУР. Покажи йому записку Вайлі та дізнайся, чи зможе він щось додати до цієї загадки. Якщо тобі не одразу вдасться знайти Гича — пошукай у казармі Старого Міста.", [3] = "Віднесіть записку Вайлі до Матіаса Гича у Штормовій.", [4] = "Яке в тебе діло до мене? Я дуже зайнята людина...", [5] = "Ця справа може виявитися складнішою, ніж уявляє Міцнокрив.", ["en"] = "The Defias Brotherhood", ["tasks"] = { ["Wiley's Note"] = "записка Вайлі", ["Wiley's Note (Provided)"] = "записка Вайлі (видано)" } },
    [1360] = { [1] = "Повернення скарбів", [2] = "У мене була чудова робота гірника на розкопках Ульдаману в Безплідних краях... доки не з'явилися ці кляті троги. Я ледь зумів врятуватись, але в хаосі я залишив найдорожче, що в мене було. Звісно, в скрині його троги не дістануть, але воно прямісінько в їх натовпі.\n\nЯ буду перед тобою в боргу, і честю, і грошима, якщо ти зможеш принести мій скарб! Скриня з моїм ім'ям стоїть у кінці північної зали. Туди тобі й треба потрапити.", [3] = "Дістаньте скарб Крома Міцнорука з його скрині північній загальній залі Ульдамана і принесіть його йому в Залізогарт.", [4] = "Ну що, тобі вдалось прорватись через трогів до скрині та забрати мій скарб?", [5] = "Ах, нарешті я знову можу бути собою — спасибі тобі величезне.\n\nДеякі дворфи цінують блиск металу, а деякі — блиск дорогоцінних каменів... але Міцнорук без своєї дорогоцінної пивної кружки — не Міцнорук!", ["en"] = "Reclaimed Treasures", ["tasks"] = { ["Krom Stoutarm's Treasure"] = "скарб Крома Міцнорука", ["Krom Stoutarm's Treasure (Provided)"] = "скарб Крома Міцнорука (видано)" } },
    [1395] = { [1] = "Постачання для Підсвітньої Варти", [2] = "Цей ящик з камінням сили потрібно доставити до фортеці Підсвітньої Варти в Спустошені землі. Вони не зможуть довго зберігати свою силу, тому ми не можемо відправити їх з наступним караваном.\n\nТобі потрібно віднести їх, і зробити це швидко.\n\nДостав їх квартирмейстеру Лунгерцу в фортецю Підсвітньої Варти. Щоб дістатися до фортеці, тобі потрібно буде тримати шлях на схід через перевал Мертвого Вітру, потім на схід через болото Скорбот, а потім на південь через Спустошені землі.\n\nБудь {стать:обережним:обережною}, {ім'я}. Твій шлях лежить через небезпечні землі, але завдання повинно бути виконано.", [3] = "Віднесіть ящик з камінням сили квартирмейстеру Лунгерцу, поки каміння не втратили силу.", [4] = "Привіт! Не звертай уваги на весь цей галас, це звичайнісінький день у фортеці Підсвітньої Варти.\n\nУ тебе є щось для мене?", [5] = "А, камені сили! Маги будуть раді побачити їх!\n\nКрасно дякую, {ім'я}. Я знаю, що твоя подорож з Темнодолу була нелегкою.", ["en"] = "Supplies for Nethergarde", ["tasks"] = { ["Crate of Power Stones"] = "ящик з камінням сили", ["Crate of Power Stones (Provided)"] = "ящик з камінням сили (видано)" } },
    [1396] = { [1] = "Вторгнення фауни", [2] = "Мій караван прямував до східного узбережжя, але до пункту призначення так і не дістався. Загублені атакували нас, перебивши варту і знищивши припаси.\n\nЛише мені вдалося пережити їхній напад. Я присягнувся зберегти решту припасів, але навколо повно чудовиськ. Прошу тебе, допоможи мені захистити табір від звірів!", [3] = "Вбийте 8 молодих пилкозубих кроколісків, 10 ткачів скорботи та 10 болотних ягуарів і потім поверніться до вартового Біґґса на болото Скорбот.", [4] = "Болотні істоти насідають, {ім'я}! Благаю, ти маєш захистити табір!", [5] = "Судячи зі звуків, звірі віддаляються. Дякую тобі, {ім'я}. Тепер, будемо сподіватись, вони не повернуться!", ["en"] = "Encroaching Wildlife", ["tasks"] = { ["Sorrow Spinner"] = "ткач скорботи", ["Sorrow Spinner slain"] = "ткач скорботи: убито", ["Swamp Jaguar"] = "болотний ягуар", ["Swamp Jaguar slain"] = "болотний ягуар: убито", ["Young Sawtooth Crocolisk"] = "молодий пилкозубий кроколіск", ["Young Sawtooth Crocolisk slain"] = "молодий пилкозубий кроколіск: убито" } },
    [1398] = { [1] = "Плавник", [2] = "Я у величезному боргу перед тобою, {ім'я}. У тебе благородне серце. У мене є ще одне завдання, щодо якого я покірно прошу допомоги.\n\nЩоб дістатися до фортеці Підсвітньої Варти, я повинен полагодити цей віз. І для цього... мені необхідне дерево. Міцна, суха деревина, а не дірчаста і сплетена як у болотяних дерев.\n\n{ім'я}, вирушай на східне узбережжя, пошукай там просушений сонцем плавник та принеси його мені.", [3] = "Принесіть 8 шматків сухого плавника вартовому Біґґсу на болото Скорбот.", [4] = "Ти {стать:знайшов:знайшла} хоч трохи плавника, {ім'я}?", [5] = "Деревина легка, але міцна. Дякую тобі, {ім'я}. Вона чудово підходить.", ["en"] = "Driftwood", ["tasks"] = { ["Sundried Driftwood"] = "сухий плавник", ["Sundried Driftwood (Provided)"] = "сухий плавник (видано)" } },
    [14] = { [1] = "Народне ополчення", [2] = "Деякі Непокірні вислизнули від нас. Мій найнадійніший розвідник повідомляє, що ці члени Братства Непокірних грабують і розоряють села аж до південного Західного краю. Ми вважаємо, що вони переховуються в Кинджальних пагорбах, плануючи наступний наліт. Убий цих негідників від імені Народного ополчення.", [3] = "Ґріан Міцнокрив хоче, щоб ви вбили 15 нальотників, 5 вистежувачів і 5 кастетників Непокірних, а потім повернулися до нього на Сторожовий пагорб.", [4] = "{Ім'я:к}, зараз не час для порожньої балаканини. Якщо ти все ще хочеш проявити себе перед Народним ополченням, тобі потрібно вбити Непокірних, про яких я повідомляв раніше. Повертайся до мене, коли виконаєш свій обов'язок.", [5] = "Коли я полишив спаплюжені землі Лордерону та повернувся, то застав свою батьківщину в жахливому стані. Але для Західного краю все ще є надія. Проявлена тобою доблесть довела, що ти з честю служиш нашій справі. З величезною гордістю я приймаю тебе до лав Народного ополчення. Нехай Світло сяє над тобою.", ["en"] = "The People's Militia", ["tasks"] = { ["Defias Highwayman"] = "нальотник Непокірних", ["Defias Highwayman slain"] = "нальотник Непокірних: убито", ["Defias Knuckleduster"] = "кастетник Непокірних", ["Defias Knuckleduster slain"] = "кастетник Непокірних: убито", ["Defias Pathstalker"] = "вистежувач Непокірних", ["Defias Pathstalker slain"] = "вистежувач Непокірних: убито" } },
    [141] = { [1] = "Братство Непокірних", [2] = "Гільдію Каменярів очолювала людина на ім'я Едвін Ван-Кліф. Саме він займався відновленням Штормовія після того, як орки зрівняли його з землею в часи Першої війни. Очевидно, Ван-Кліф і його люди залишилися незадоволеними тим, як король повівся з ними після завершення реконструкції міста. Це могло б прояснити декілька речей.\n\nЯ розписав усе більш детально для твого керівника в Західному краї. Передай йому цей документ негайно!", [3] = "Доставте доповідь Гича Ґріану Міцнокривові у Західний край.", [4] = "Чи пролив майстер Гич світло на те, що відбувається?", [5] = "Едвін Ван-Кліф... Мені добре відоме це ім'я. Тривожно від думки, що така підприємлива та талановита людина могла перетворитися на такого негідника. Мені потрібні додаткові докази, перш ніж я повірю в це.", ["en"] = "The Defias Brotherhood", ["tasks"] = { ["Shaw's Report"] = "звіт Гича", ["Shaw's Report (Provided)"] = "звіт Гича (видано)" } },
    [142] = { [1] = "Братство Непокірних", [2] = "Нам потрібно з'ясувати розташування схованки Непокірних. {Ім'я:к}, мій розвідник повідомляє, що їхнього гінця бачили на дорогах між Місяцеграєм, кар'єром Золотого берега та копальнею Джанґолода. Я хочу, щоб ти його {стать:спіймав:спіймала}. Якщо він чинитиме опір, убий його та принеси мені все, що знайдеш на ньому.", [3] = "Вистежить гінця Непокірних у Західному краї та принесіть його звіт Ґріанові Міцнокриву.", [4] = "{Ім'я}, тобі вдалося знайти якусь інформацію? Чи {стать:знайшов:знайшла} ти гінця?", [5] = "Це явний доказ того, що Ван-Кліф — їхній ватажок. Тепер усе, що нам потрібно дізнатися — де переховується банда Непокірних.\n\nНам тут трохи пощастило, поки тебе не було. Ми зловили злодія, який намагався викрасти візок Салдена. Він пообіцяв привести нас до їхнього укриття в обмін на своє життя. Я хочу, щоб ти {стать:захистив:захистила} перебіжчика, аби він міг вказати, де схованка. Повертайся до мене, коли з'ясуєш її місце розташування.", ["en"] = "The Defias Brotherhood", ["tasks"] = { ["A Mysterious Message"] = "таємниче повідомлення", ["A Mysterious Message (Provided)"] = "таємниче повідомлення (видано)" } },
    [1421] = { [1] = "Загублений караван", [2] = "Я був приголомшений під час атаки Загублених, але, перш ніж знепритомніти, я бачив, як один з наших возів тягнули до Тьмяного пристановища, поселення Загублених на півночі.\n\nУ цьому возі була скриня з цінними реактивами, життєво важливими для досліджень чарівників фортеці Підсвітньої Варти. {Ім'я}, знайди скриню, дістань ці реактиви та поверни їх мені.", [3] = "Знайдіть скриню з каравану в Тьмяному пристановищі, здобудьте реактиви чарівників і принесіть їх вартовому Біґґсу.", [4] = "Ти {стать:дістав:дістала} реактиви чарівників, {ім'я}?", [5] = "Ах, ти {стать:знайшов:знайшла} їх! З цими реактивами чарівники фортеці Підсвітньої Варти зможуть продовжити роботу. Я не знаю чим вони займаються, але це пов'язано з Темним Порталом в Спустошених землях і життєво важливо для безпеки всього Альянсу.", ["en"] = "The Lost Caravan", ["tasks"] = { ["Wizards' Reagents"] = "реактиви чарівників", ["Wizards' Reagents (Provided)"] = "реактиви чарівників (видано)" } },
    [1423] = { [1] = "Втрачені припаси", [2] = "Ця діжка невелика, але міцна. Її шви ущільнені жовтим пахучим воском. На дні діжки викарбувані слова:\n\nКВАРТИРМЕЙСТЕР ЛУНГЕРЦ\n\nФОРТЕЦЯ ПІДСВІТНЬОЇ ВАРТИ", [3] = "Принесіть втрачені припаси квартирмейстерові Лунгерцу.", [4] = "У тебе щось є для мене?", [5] = "Дякую тобі, {ім'я}! Так багато припасів втрачається на шляху з Темнодолу. Добре, що дещо вдається повернути.", ["en"] = "The Lost Supplies", ["tasks"] = { ["Lost Supplies"] = "втрачені припаси", ["Lost Supplies (Provided)"] = "втрачені припаси (видано)" } },
    [1425] = { [1] = "Доставка вантажу", [2] = "Поки я чиню цей візок, {ім'я}, у мене є останнє завдання для тебе.\n\nЯ зібрав найважливіші припаси, вцілілі після набігів огрів. Віднеси їх у фортецю Підсвітньої Варти. Вона розташована на північних пагорбах Спустошених земель, для спостереження за Темним Порталом.\n\nЩоб дістатися туди — прямуй дорогою на схід. Коли вона розгалузиться, верни на південь до Спустошених земель, а потім наліво на наступній розвилці. Тримайся дороги, {ім'я}, і не втрачай пильності.", [3] = "Доставте вантаж квартирмейстерові Лунгерцу в фортецю Підсвітньої Варти.", [4] = "Маєш справу до мене?", [5] = "Що? Вантаж з каравану Біґґса? Ми думали, він пропав разом з караваном.\n\nДякую, {ім'я}. Якщо пощастить, в цьому вантажу вкрай необхідний реагент — кристали Азорану. Наші запаси добігають кінця...", ["en"] = "Deliver the Shipment", ["tasks"] = { ["Shipment to Nethergarde"] = "вантаж для Підсвітньої Варти", ["Shipment to Nethergarde (Provided)"] = "вантаж для Підсвітньої Варти (видано)" } },
    [143] = { [1] = "Посланець до Західного краю", [2] = "Щось дивне коїться з армією Штормовію. Вони вже мали б бути тут у повному складі. Однак час — це розкіш, якої ми не маємо. Я не стоятиму осторонь і не спостерігатиму, як люди Приозер'я віддають свої життя, не намагаючись заручитися додатковою допомогою. Я чув, що у Західному краї формується народне ополчення.\n\nПередай це прохання їхньому лідеру, Ґріану Міцнокриву. Можливо, люди Міцнокрива зможуть надати нам підтримку, поки король не надішле підкріплення.", [3] = "Війт Соломон просить вас віднести лист з проханням Ґріану Міцнокриву в Західний край.", [4] = "Вітаю, {клас:к}. Що привело тебе до Народного ополчення?", [5] = "Добрий посланець, ти добре {стать:послужив:послужила} своєму панові.", ["en"] = "Messenger to Westfall", ["tasks"] = { ["Solomon's Plea to Westfall"] = "прохання Соломона до Західного краю", ["Solomon's Plea to Westfall (Provided)"] = "прохання Соломона до Західного краю (видано)" } },
    [144] = { [1] = "Посланець до Західного краю", [2] = "Мені боляче читати лист війта Соломона. Але він, очевидно, не знає про війну, яка ведеться в Західному краї, інакше б не чекав на допомогу від нас. Якби Штормовій не покинув нас, нам не знадобилося б ополчення.\n\nВіднеси цю відповідь своєму пану в Багрянокряжжя, {клас:к}. Передай йому мої співчуття, щодо втрати хороших людей.", [3] = "Поверніться до війта Соломона з відповіддю Ґріана Міцнокрива.", [4] = "Ми можемо очікувати на допомогу від Народного ополчення? Є хороші новини від лорда Міцнокрива?", [5] = "Що сказати, справи недобрі. Я й не підозрював, що у Міцнокрива такі ж проблеми, що й у Приозер'ї. Що ж могло статись настільки важливого, що армія Штормовію не може захистити власні землі? Втім, дарма я про це говорю вголос.\n\nОсь, {стать:посланцю:посланнице}. Прийми ці монети за твою службу містечку. Можливо, ти мені знову знадобишся.", ["en"] = "Messenger to Westfall", ["tasks"] = { ["Stoutmantle's Response to Solomon"] = "відповідь Міцнокрива Соломону", ["Stoutmantle's Response to Solomon (Provided)"] = "відповідь Міцнокрива Соломону (видано)" } },
    [1447] = { [1] = "Зниклий дипломат", [2] = "Що ж, ти, очевидно, не {стать:найрозумніший:найрозумніша} {клас} в Штормовії.\n\n{стать:Знайомий:Знайома} з моїми друзями?", [3] = "Переможіть Дешеля Кам'яного Кулака в Штормовії.", [4] = "Я не хотів тебе образити, {клас:к}. Ми ж друзі, так? Ніяких проблем?", [5] = "Отож, ти чомусь {стать:прийшов:пришла} до мене. Що тобі потрібно?", ["en"] = "The Missing Diplomat", ["tasks"] = { ["Defeat Dashel Stonefist"] = "Перемогти Дашеля Кам'яного Кулака" } },
    [1452] = { [1] = "Калімдорський коктейль Рапсодія", [2] = "Гик!\n\nТо тебе прислав цей божевільний дурень Броган? У нас була ще та пригода... Гик!\n\nЯкщо ти хочеш, щоб я розповів тобі, що сталося над цим болотом, мені потрібно випити щось міцне. Там було не дуже приємно, розумієш? Гик!\n\nТак от, послухай... принеси мені все, що потрібно для калімдорського коктейлю і я все тобі розкажу.\n\nМені знадобляться шлунки рухів з Танарісу... і, так... печінки гроддокських мавп та залізохутрих ведмедів з Фераласу...\n\nМіцний калімдорський коктейль... розв'яже мені язик!", [3] = "Принесіть Рапсодію Жартогону з Внутрішніх земель 3 шлунки руха, 3 печінки гроддокської мавпи та 3 печінки залізохутрого ведмедя.", [4] = "Ти коли-небудь {стать:куштував:куштувала} солод Рапсодія? Це один з моїх кращих сортів, так. Гик!\n\nАле якщо я збираюся згадати жахливий політ над... гик!... болотом, то мені знадобиться щось трохи міцніше. Гик!\n\nПрипускаю, що ти не {стать:знайшов:знайшла} ті шлунки та печінки, які мені потрібні, щоб додати вишуканого смаку до мого калімдорського коктейлю?\n\nГик!", [5] = "Бачу, що тобі не складно було дістати все, що мені потрібно! Мабуть, {стать:втомився:втомилася} від подорожі до далекого Калімдору.\n\nМені знадобиться лише мить, щоб дістати зі шлунків та печінок те, що мені потрібно. Гик!\n\nПотім я зможу зробити собі міцний напій і нарешті розповісти тобі те, що ти хочеш знати.\n\nГик!\n\nУ мене мурашки по шкірі, коли я думаю про це старе болото.\n\nГик!\n\nДай я швиденько змішаю напій.", ["en"] = "Rhapsody's Kalimdor Kocktail", ["tasks"] = { ["Groddoc Liver"] = "печінка гроддокської мавпи", ["Groddoc Liver (Provided)"] = "печінка гроддокської мавпи (видано)", ["Ironfur Liver"] = "печінка залізохутрого ведмедя", ["Ironfur Liver (Provided)"] = "печінка залізохутрого ведмедя (видано)", ["Roc Gizzard"] = "шлунок руха", ["Roc Gizzard (Provided)"] = "шлунок руха (видано)" } },
    [1453] = { [1] = "Справи корпорації \"Віднова\" в Спустошищі", [2] = "У Спустошищі є робота для тебе, {ім'я}. Це моторошне місце, осквернене кентаврами та іншою гидотою. Та якщо шукаєш, де гарно попрацювати — вирушай туди, зустрінься з Крелдіґом Унґором і скажи, що я тебе прислав.\n\nТи знайдеш його в оплоті Найджела — це маленький затишний табір, схований у горах на півночі Спустошища. Просто прямуй на схід від входу з Каміннопазуристих гір. Вхід до табору легко проминути, тож будь {стать:уважним:уважною}.", [3] = "Поговоріть з Крелдіґом Унґором в Спустошищі.", [5] = "Радий бачити, що корпорації \"Віднова\" не бракує ні роботи, ні шукачів пригод, готових прийти на допомогу.\n\nЯ Крелдіґ, {ім'я}. Ти чиниш розумно, допомагаючи корпорації \"Віднова\". Кожен чогось потребує: втрачену сімейну реліквію, чарівний предмет, кохану людину. Та мало що. Але коли за справу береться наша корпорація — за гарну ціну кожен може знайти те, що втратив.", ["en"] = "Reclaimers' Business in Desolace" },
    [1454] = { [1] = "Пожитки Карнітола", [2] = "Моє перше завдання стосується мага Карнітола — це якийсь дворянин зі Штормовію. На його корабель напали морські велетні, коли він пропливав біля північно-західного узбережжя Спустошища. Він зі слугами намагався витягти на берег одну з найцінніших скринь, але коли морські велетні накинулися на них, йому довелося кинути її та телепортувати себе і своїх слуг в безпечне місце.\n\nТак ось, він хоче, щоб ми знайшли його скриню та повернули її разом з усім вмістом у Штормовій.", [3] = "Знайдіть скриню Карнітола в Спустошищі.", [5] = "Схоже, що скриня не постраждала від води.\n\nОднак видно, що кришка була відкрита силою. І які б магічні пастки для її захисту тут не були встановлені, вони встигли спрацювати: краї скрині обпечені.", ["en"] = "The Karnitol Shipwreck" },
    [1455] = { [1] = "Пожитки Карнітола", [2] = "Ви витрачаєте кілька хвилин, щоб дізнатися, хто або що, відкрило скриню. Судячи з довгих глибоких подряпин на боках і кришці, це була не людина і не велетень.... Ці подряпини не схожі й на сліди від кинджала чи меча.\n\nВідкривши скриню, ви бачите, що вона порожня.\n\nРобити нічого: залишається тільки закрити скриню і піти. Крелдіґ буде розчарований.", [3] = "Поверніться до Крелдіґа Унґора в Спустошище.", [5] = "З поверненням до оплоту Найджела, {ім'я}. Розказуй, що ти {стать:знайшов:знайшла}.\n\nЯк?! Нічого? Боюся, за порожню скриню нам не заплатять.\n\nРозкажи мені більше про ці сліди, які ти {стать:бачив:бачила}... ці подряпини.", ["en"] = "The Karnitol Shipwreck" },
    [1456] = { [1] = "Пожитки Карнітола", [2] = "Цікаво...\n\nЩо ж, можливо, ще не все втрачено.\n\nВздовж цього ж узбережжя, трохи на північ від острова Раназжар, на дні океану є руїни нічних ельфів. Слизькорізи, плем'я наг, зробили їх своїм домом. Гадаю, вони мають відношення до історії зі скринею.\n\nЯкщо розвідники наг зайшли так далеко на південь, значить, вони були досить сильними. Якщо ти хочеш знайти речі Карнітола, я б спочатку перевірив наймогутніших наг: хвилеловів або морських відьом.", [3] = "Знайдіть торбу Карнітола і поверніть її Крелдіґу Унґору в Спустошище.", [4] = "Не знаю вже, ким там був цей Найджел, але його табір — не найприємніше місце для ночівлі, можеш мені повірити, {ім'я}.", [5] = "Це ж чудово, {ім'я}! Ти {стать:знайшов:знайшла} пожитки Карнітола!\n\nЧерез цих клятих наг завжди самі лиш проблеми. Краще все життя воювати з Ордою, ніж мати справу з цими створіннями. Ти {стать:зробив:зробила} велику послугу для корпорації \"Віднова\".", ["en"] = "The Karnitol Shipwreck", ["tasks"] = { ["Karnitol's Satchel"] = "торба Карнітола", ["Karnitol's Satchel (Provided)"] = "торба Карнітола (видано)" } },
    [146] = { [1] = "Посланець до Темнодолу", [2] = "Якби я не знав війта Соломона особисто, я б сказав, що він збожеволів. Відправити Нічну варту до Приозер'я, тому що Штормовій відмовив у допомозі? Нічна варта була створена тому, що Штормовій кинув нас напризволяще, коли наші землі наповнила ця нечиста магія. Якщо я відправлю Нічну варту, це місто заполонить зло ще до того, як вони дійдуть до краю лісу.\n\nВіднеси цей лист з моєю відповіддю Соломону в Приозер'я.", [3] = "Поверніться до війта Соломона з відповіддю лорда Чорнобривого.", [4] = "Ах, радий тебе знову бачити, {стать:посланцю:посланнице}. Я вже можу повідомити маршалу, що Нічна варта їде з Темнодолу?", [5] = "Сили небесні! Армія Штормовія відступила з Західного краю, а варта більше не захищає Темноділ? Щось тут нечисто. Як це могло статися?\n\nО, я забув винагородити твою службу, {клас:к}. Ось кілька монет. А тепер прошу мене вибачити. У Штормовії щось відбувається, і я мушу розібратися в цьому.", ["en"] = "Messenger to Darkshire", ["tasks"] = { ["Ebonlocke's Response to Solomon"] = "відповідь Чорнобривого Соломону", ["Ebonlocke's Response to Solomon (Provided)"] = "відповідь Чорнобривого Соломону (видано)" } },
    [1468] = { [1] = "Дитячий тиждень", [2] = "Ти бажаєш допомогти нам у притулку для сиріт? Нехай благословлять тебе боги, твоя допомога під час Дитячого тижня буде дуже важливою.\n\nВізьми цей свисток. Ти зможеш використовувати його лише короткий період часу — зазвичай до кінця Дитячого тижня. Свиснувши в нього, ти зможеш спілкуватися з дитиною, про яку {стать:погодився:погодилася} піклуватися. Щоб дитина пішла, використай свисток ще раз.\n\nПрошу, {ім'я} — скористайся свистком і зустрінься з твоїм підопічним! Я впевнена, що дитина буде надзвичайно рада познайомитися з тобою.", [3] = "Використовуйте свисток сироти, щоб поговорити з дитиною, за якою ви будете доглядати протягом Дитячого тижня.", [5] = "Ем... привіт. Мене звати Рандіс. А ти тепер піклуватимешся про мене? Ти {стать:шукач:шукачка} пригод, зовсім як були мої мама з татом... Я так радий познайомитися з тобою!\n\nА ми тепер будемо шукати пригоди робити разом? Мені стільки всього хочеться зробити, а опікунка сказала, що ти весь тиждень будеш для мене, як {стать:старший брат:старша сестра}. Гайда до пригод!", ["en"] = "Children's Week", ["tasks"] = { ["Human Orphan Whistle"] = "свисток сироти" } },
    [1469] = { [1] = "Історія Рапсодія", [2] = "Перед польотом я випив цілу кеглю стауту. Гик!\n\nІ що за політ вийшов! Я швидко кружляв, а за мною летів Броган. Ніякого храму я там не бачив. Гик!\n\nІ не знайшли б ми його ніколи, якби я не напився так, що впав із сідла. Я впав у воду і мене почало тягнути на дно. Там мене оточили огидні тролі. Я швидко втік з того місця! І ще забрав із собою цей трольський сувенір. Ось, віднеси його Брогану та повідом йому, що цей храм там дійсно є. Гик!", [3] = "Віднесіть уламок таблички Атал'ай Брогану Бочкопузу в Штормовій.", [4] = "Нарешті ти {стать:повернувся:повернулася}, {ім'я}. Пройшло вже досить багато часу з нашої останньої розмови. Я подумав, що, можливо, ти {стать:забув:забула} про моє завдання.\n\nТи {стать:знайшов:знайшла} того приборкувача грифонів? Він щось сказав?", [5] = "Рапсодій Жартогін! Точно... як я міг забути це ім'я?\n\nТо він увесь цей час знав про те, що храм затонув? Що ж, це точно заощадить тобі час.\n\nАле цей артефакт Атал'ай! Це справді чудова знахідка!", ["en"] = "Rhapsody's Tale", ["tasks"] = { ["Atal'ai Tablet Fragment"] = "уламок таблички Атал'ай", ["Atal'ai Tablet Fragment (Provided)"] = "уламок таблички Атал'ай (видано)" } },
    [147] = { [1] = "Полювання на здирника", [2] = "\"Збирач\" відбирає золото з наших шахт, тим самим обкрадаючи королівство! Притягни його до відповідальності, а мені принеси перстень, згаданий у розкладі, що ти {стать:дав:дала} мені. Можливо, перстень допоможе нам зрозуміти, на кого той негідник працює...\n\nУ розкладі сказано, що \"Збирач\" переховується у гарбузовому наділі Бреквеллів. Доведеться тобі там все обшукати.", [3] = "Знайдіть і вбийте \"Збирача\", а потім принесіть маршалові Дугану його перстень.", [4] = "Ти {стать:знайшов:знайшла} \"Збирача\"? {стать:Довідався:Довідалась}, на кого він працює?", [5] = "Тобі вдалося? Молодець, {ім'я:к}. Він більше не буде нічого \"збирати\" з Ельвиннських копалень!\n\nЦей перстень, що ти {стать:приніс:принесла}, цікавенький... Це членський перстень давньої гільдії Каменярів Штормовію. Чому в жалюгідного злодюги є перстень ремісничої гільдії, і чому Непокірні злодії збирають гроші в наших шахтах?\n\nСкладні запитання. Сподіваюся, колись у нас будуть відповіді.", ["en"] = "Manhunt", ["tasks"] = { ["The Collector's Ring"] = "перстень Збирача", ["The Collector's Ring (Provided)"] = "перстень Збирача (видано)" } },
    [148] = { [1] = "Припаси з Темнодолу", [2] = "Ой, що ж робити бідному старцю? Мені потрібні деякі речі з Темнодолу, але він так далеко, а я такий старий та слабкий... Я ніколи не дійду до нього.\n\nЧи можеш ти піти до Темнодолу та принести мені нитку з волосся привида? Ти можеш отримати її у мадам Єви в її будинку на площі в Темнодолі.", [3] = "Поговоріть з мадам Євою.", [5] = "А, тобі потрібна нитка з волосся привида, чи не так? На жаль, я не маю її в наявності, але я можу створити її для тебе... якщо ти знайдеш волосся привида.", ["en"] = "Supplies from Darkshire" },
    [149] = { [1] = "Нитка з волосся привида", [2] = "Є один бідний, сумний дух, на ім'я сліпа Мері, що блукає навколо старого фермерського будинку між пагорбами, що на південь від Темнодолу.\n\nОсь, візьми цей примарний гребінець та попроси сліпу Мері розчесати своє волосся. Потім принеси гребінець мені, і я зберу з нього примарне волосся для нитки.\n\nБудь {стать:обережним:обережною}, оскільки поруч з тим будинком тепер чатує щось темне...", [3] = "Принесіть примарний гребінець сліпій Мері.", [4] = "<Плаче> Прошу, не дивись на мене! Я вирвала собі ці очі сама, але все ще відчуваю твій погляд!\n\nЯ потворна! Потворна! Будь ласка, відвернись!!", [5] = "Що це таке? Гребінець? Він чудовий! І він ковзає по моєму волоссю так, ніби воно не збилося в жахливий ковтун.\n\nЯкби ж я тільки мала дзеркало...", ["en"] = "Ghost Hair Thread", ["tasks"] = { ["Spectral Comb"] = "примарний гребінець", ["Spectral Comb (Provided)"] = "примарний гребінець (видано)" } },
    [15] = { [1] = "Розвідка в Ехокряжі", [2] = "{Ім'я:к}, мої розвідники доповіли, що нашестя кобольдів є більшим, ніж ми вважали. Група кобольдів-робітників розгорнула табір поблизу копальні Ехокряжу, на північ звідси.\n\nЙди до копальні та позбудься їх. Нам відомо про наявність щонайменше десятьох. Убий їх, тоді перевір, чи то всі. Потім відзвітуєш мені.", [3] = "Убийте 10 кобольдів-робітників, а потім поверніться зі звітом до маршала Макбрайда.", [4] = "Ти вже {стать:був у:була в} копальні? {стать:Готовий:Готова} звітувати?", [5] = "Не подобається мені вся ця історія з кобольдами в наших копальнях. Нічого доброго з того не вийде. Ось, твоя платня, і, коли наважишся на нове завдання — поговори зі мною знову. Я б хотів, щоб ти ще раз {стать:навідався:навідалася} до копальні...", ["en"] = "Investigate Echo Ridge", ["tasks"] = { ["Kobold Worker"] = "кобольд-робітник", ["Kobold Worker slain"] = "кобольд-робітник: убито" } },
    [150] = { [1] = "Мурлоки-браконьєри", [2] = "Мурлоки починають нас турбувати. Вони селяться великими групами на берегах Безхвильного озера і виловлюють всю рибу! Ми маємо вигнати їх, доки вони не спустошили все озеро!\n\nВбий якомога більше мурлоків! Принеси мені вісім їхніх плавців, і я знайду чим тобі відплатити...", [3] = "Принесіть 8 плавців мурлока начальнику доку Барену в Приозер'я.", [4] = "Плавці у тебе? Поквапся, ми маємо вигнати їх з озера!", [5] = "Молодець, {ім'я}. Сподіваюсь, це не викликало в тебе великих складнощів.\n\nДивно бачити їх так далеко від моря. Цікаво, чому вони тут. Невже втекли від чогось...", ["en"] = "Murloc Poachers", ["tasks"] = { ["Murloc Fin"] = "плавець мурлока", ["Murloc Fin (Provided)"] = "плавець мурлока (видано)" } },
    [151] = { [1] = "Бідна старенька Білявка", [2] = "Бідна старенька Білявка! Така стомлена конячка від всієї праці, яку ми на неї покладаємо. Я погодувала її перед тим, як виїхати з ферми, але ми не очікували, що візок зламається по дорозі. Якби ти {стать:приніс:принесла} їй кілька жмень вівса з полів, я була б дуже вдячна.\n\nЗакладаюся, що ти знайдеш овес на будь-якій фермі у Західному краї, якщо тільки зможеш триматися якомога далі від тих жахливих машин, що захопили поля. На північний захід звідси є кілька таких ферм.", [3] = "Принесіть 8 жмень вівса Верні Хмуробров з Західного краю.", [4] = "Старенька Білявка вже валиться з ніг. Чи не {стать:роздобув:роздобула} ти трохи вівса для неї?", [5] = "Дякую тобі дуже, {ім'я}! Бідна старенька Білявка буде така щаслива!", ["en"] = "Poor Old Blanchy", ["tasks"] = { ["Handful of Oats"] = "жменя вівса", ["Handful of Oats (Provided)"] = "жменя вівса (видано)" } },
    [153] = { [1] = "Червоні шкіряні бандани", [2] = "Непокірні не стоять на місці. Я вже досить давно стежу за ними. Між іншим, я помітив, що багатьох членів їхньої банди можна розпізнати за червоними шкіряними банданами.\n\nПринеси мені 15 таких бандан, і я подбаю про те, щоб тебе винагородили.", [3] = "Принесіть розвіднику Галіаанові на Сторожовий пагорб 15 червоних шкіряних бандан.", [4] = "Принеси мені 15 червоних шкіряних бандан, і я добре заплачу.", [5] = "Гарна робота, {раса:к}. Будь ласка, прийми один з цих предметів як оплату за твій тяжкий труд.", ["en"] = "Red Leather Bandanas", ["tasks"] = { ["Red Leather Bandana"] = "червона шкіряна бандана", ["Red Leather Bandana (Provided)"] = "червона шкіряна бандана (видано)" } },
    [154] = { [1] = "Повернення гребінця", [2] = "НІ!!!!!\n\nЗабери цей гребінець від мене!\n\nЯ потвора, і ніхто ніколи більше не вважатиме мене привабливою!", [3] = "Поверніть примарний гребінець мадам Єві в Темноділ.", [4] = "Я відчуваю, що ти {стать:бачив:бачила} сліпу Мері. Мій гребінець у тебе?", [5] = "Я можу зробити цілий клубок ниток з цього волосся і залишити кілька про запас. Візьми ці монети як плату за зайве волосся.", ["en"] = "Return the Comb", ["tasks"] = { ["Ghost Hair Comb"] = "гребінець з волоссям привида", ["Ghost Hair Comb (Provided)"] = "гребінець з волоссям привида (видано)" } },
    [155] = { [1] = "Братство Непокірних", [2] = "Отже, Міцнокрив послав {стать:такого кволого:таку кволу} {раса:з} захищати мене? Що ж, доведеться йти так. Проте краще візьми з собою кількох друзів.\n\nТи ж знаєш, що робити, так? Ти прикриваєш мою спину, а я веду тебе до схованки Непокірних. Про всяк тримайся до мене ближче. Банда Непокірних тепер полює на мене. Якщо вони побачать мене з тобою, то спробують мене вбити.\n\nДай знати, коли ти та друзі, яких ти зможеш зібрати, будуть готові йти.", [3] = "Супроводжуйте зрадника Непокірних до таємної схованки Братства Непокірних. Коли зрадник покаже вам, де ховаються Ван-Кліф і його люди, поверніться до Ґріана Міцнокрива з цією інформацією.", [4] = "Яке в тебе діло до мене? Я дуже зайнята людина...", [5] = "Чудово, {ім'я}! Тепер, коли ми знаємо, де ховається Ван-Кліф, він майже наш.", ["en"] = "The Defias Brotherhood", ["tasks"] = { ["Escort The Defias Traitor to discover where VanCleef is hiding"] = "Супроводіть зрадника Непокірних, щоб знайти схованку Ван-Кліфа" } },
    [156] = { [1] = "Збір гнилоцвіту", [2] = "Якщо ти принесеш мені кілька гнилоцвітів, то я зможу зварити для тебе сік зомбі.\n\nГнилоцвіт зростає в дивних місцях. Зокрема, я чув, що його можна знайти всередині черепів скелетних страховищ та скелетних марників... хоча я не був достатньо близько, щоб побачити це на власні очі.\n\nНа кладовищі Воронячого пагорба і цвинтарі при Затишних садах повно цих скелетів. Коли будеш шукати гнилоцвіт, заодно можеш позбавитись від них. Темноділ буде тобі вдячний.", [3] = "Зберіть 8 гнилоцвітів та принесіть їх до господаря таверни Сміттса в Темноділ.", [4] = "Привіт, {ім'я}. Ти {стать:приніс:принесла} мені гнилоцвіт?", [5] = "Чудово, ти {стать:знайшов:знайшла} його. І я повідомлю Альтею Чорнобриву з Нічної варти, що ти {стать:допоміг:допомогла} вбити скелетів.\n\nБезпека жителів Темнодолу — це тягар, що лежить на плечах Нічної варти, і новини про те, що інші допомагають стримувати наплив чудовиськ у Смерколіссі, завжди тішать.", ["en"] = "Gather Rot Blossoms", ["tasks"] = { ["Rot Blossom"] = "гнилоцвіт", ["Rot Blossom (Provided)"] = "гнилоцвіт (видано)" } },
    [157] = { [1] = "Доставка ниток", [2] = "Ось твоя нитка, {ім'я}. Вона має тисячу застосувань, від зв'язування злих духів до вшивання життя в неживі предмети.", [3] = "Віднесіть нитку з волосся привида до Аберкромбі, в його халупу на північ від кладовища Воронячого пагорба.", [4] = "Мені потрібно натягнути нитку з волосся привида на двері та вікна, щоб утримати небажаних духів. Ти {стать:приніс:принесла} її для мене?", [5] = "Чудово! Вона чудово підійде...\n\nОсь, {стать:добрий:добра} {ім'я}, візьми це як оплату за свою благородну справу.", ["en"] = "Deliver the Thread", ["tasks"] = { ["Ghost Hair Thread"] = "нитка з волосся привида", ["Ghost Hair Thread (Provided)"] = "нитка з волосся привида (видано)" } },
    [1578] = { [1] = "Постачання на фронт", [2] = "Горяни Лох-Модану без перепочинку ведуть боротьбу з трогами! Їм постійно потрібна нова зброя та броня, щоб вони могли протриматись.\n\nТому мій колега Торвальд поїхав туди, щоб забезпечити горян спорядженням. Тож якщо ти зробиш декілька мідних сокир і плетених поясів та принесеш їх Торвальду, він буде дуже вдячний. Можливо, він навіть поділиться з тобою своїми знаннями.\n\nТорвальд знаходиться в південній сторожовій вежі Лох-Модану.", [3] = "Принесіть 6 мідних сокир і 6 мідних плетених поясів Торвальду в південну сторожову вежу Лох-Модану.", [4] = "Я не маю часу на балачки. В тебе якась справа?", [5] = "А, вибач! Я не знав, що ти тут, щоб допомогти поповнити запаси наших військ. Те, що ти {стать:зробив:зробила} дуже допоможе нам!\n\nОсь креслення деяких обладунків. Сподіваюся, вони тобі знадобляться.", ["en"] = "Supplying the Front", ["tasks"] = { ["Copper Axe"] = "мідна сокира", ["Copper Axe (Provided)"] = "мідна сокира (видано)", ["Copper Chain Belt"] = "мідний плетений пояс", ["Copper Chain Belt (Provided)"] = "мідний плетений пояс (видано)" } },
    [158] = { [1] = "Сік зомбі", [2] = "Мені потрібна пляшка особливого напою — сік зомбі. У господаря таверни Сміттса з таверни Багряний Ворон в Темнодолі має бути зайва пляшечка.\n\nІ, будь ласка, поквапся, {ім'я}. Ці ночі стають холодними, і мені потрібен той напій, щоб знову розпалити вогонь у своїх жилах!", [3] = "Поговоріть з господарем таверни Сміттсом.", [5] = "Тобі потрібен сік зомбі? Хмм... це дуже міцний напій — зазвичай в мене його не замовляють.", ["en"] = "Zombie Juice" },
    [1581] = { [1] = "Еліксири для Клинколистів", [2] = "Наша крамничка трав і алхімічних припасів процвітає, але мій чоловік витрачає стільки часу на виготовлення еліксирів, що у нас не залишається часу один на одного.\n\nЧи можеш ти нам допомогти?\n\nЯкщо ти принесеш мені запас готових еліксирів, то я з радістю обміняюся з тобою. У мене є деякі рідкісні трави, які можуть стати тобі в пригоді.", [3] = "Принесіть 6 еліксирів сили лева та 2 еліксири слабкого захисту Сірел Клинколист в Доланаар.", [4] = "Привіт, {ім'я}. Ти {стать:приніс:принесла} еліксири на обмін?", [5] = "Вони добре поєднуються. Ти дуже ретельно ставишся до своєї справи, {ім'я}, а це важливо для алхіміка.\n\nОсь твої трави, свіжозібрані. Нехай вони принесуть тобі користь.", ["en"] = "Elixirs for the Bladeleafs", ["tasks"] = { ["Elixir of Lion's Strength"] = "еліксир сили лева", ["Elixir of Lion's Strength (Provided)"] = "еліксир сили лева (видано)", ["Elixir of Minor Defense"] = "еліксир слабкого захисту", ["Elixir of Minor Defense (Provided)"] = "еліксир слабкого захисту (видано)" } },
    [1582] = { [1] = "Жилет місячного сяйва", [2] = "В Дарнасі всі, а особливо майстри, дуже зайняті. Юні шукачі пригод прагнуть випробувати себе та постійно потребують припасів.\n\nЯкщо ти допоможеш мені виконати замовлення на шкіряні вироби, то, можливо, я зможу навчити тебе більш досконалій техніці роботи зі шкірою.", [3] = "Принесіть пару тиснених шкіряних рукавичок, 5 пар тиснених шкіряних чобіт та 5 тиснених шкіряних плащів до Лотеріас в Дарнас.", [4] = "Вітаю, {ім'я}.", [5] = "Так, це гарні вироби. У тебе вправна рука та уважне око. Твоє майбутнє як {стать:шкірника:шкірниці} перспективне.\n\nОсь, {ім'я}. Дозволь показати тобі викрійку для виготовлення жилета місячного сяйва.", ["en"] = "Moonglow Vest", ["tasks"] = { ["Embossed Leather Boots"] = "тиснені шкіряні чоботи", ["Embossed Leather Boots (Provided)"] = "тиснені шкіряні чоботи (видано)", ["Embossed Leather Cloak"] = "тиснений шкіряний плащ", ["Embossed Leather Cloak (Provided)"] = "тиснений шкіряний плащ (видано)", ["Embossed Leather Gloves"] = "тиснені шкіряні рукавички", ["Embossed Leather Gloves (Provided)"] = "тиснені шкіряні рукавички (видано)" } },
    [159] = { [1] = "Доставка соку", [2] = "А ось і сік зомбі...\n\n...і будь {стать:обережний:обережна} з ним. Він настільки сильний, що може підняти мерців!", [3] = "Принесіть сік зомбі Аберкромбі в його хатину.", [4] = "Мені потрібен цей сік зомбі, щоб зігрітися в ці холодні темні ночі. Ти {стать:дістав:дістала} його для мене?", [5] = "Щиро дякую тобі, {ім'я}. Ти зігріваєш серце старого чоловіка своєю дурнуватістю... тобто... своєю добротою!\n\nОсь, тримай. Візьми це на знак моєї вдячності.", ["en"] = "Juice Delivery", ["tasks"] = { ["Bottle of Zombie Juice"] = "пляшка соку зомбі", ["Bottle of Zombie Juice (Provided)"] = "пляшка соку зомбі (видано)" } },
    [16] = { [1] = "Спрага Джерарда", [4] = "Сільське господарство виснажує, тому я завжди в пошуку освіжаючої джерельної води.\n\nЯкщо в тебе вона є, то я з радістю обміняюсь.", [5] = "Дякую, {ім'я}! І повертайся, як захочеш знову обмінятись.", ["en"] = "Give Gerard a Drink", ["tasks"] = { ["Refreshing Spring Water"] = "освіжаюча джерельна вода", ["Refreshing Spring Water (Provided)"] = "освіжаюча джерельна вода (видано)" } },
    [160] = { [1] = "Записка меру", [2] = "Візьми цю записку і віднеси меру Темнодолу, Елло Чорнобривому.\n\nМи з ним старі друзі... Я впевнений, що коли він прочитає її та дізнається, що ти {стать:зробив:зробила} для мене, він буде так само щасливий, як і я! Хахахаха!", [3] = "Передайте лист Аберкромбі Елло Чорнобривому, меру Темнодолу.", [4] = "Аберкромбі...? Я не знаю нікого з таким ім'ям. Кажеш, у тебе є для мене лист від цього Аберкромбі?\n\nДобре, подивімось...", [5] = "<Елло дивиться на лист...>\n\nЩо це за мова? Виглядає древньою... Я не можу прочитати це.", ["en"] = "Note to the Mayor", ["tasks"] = { ["Letter to Ello"] = "лист до Елло", ["Letter to Ello (Provided)"] = "лист до Елло (видано)" } },
    [161] = { [1] = "Темна загроза", [2] = "Я підозрюю, що це якась вибухівка. Хай це проаналізує експерт з вибухових речовин, щоб ми точно знали, з чим маємо справу. Ашлана Камнесміха направили на охорону Дун-Модра та віадуку Тандола. Це буде важка й небезпечна подорож, {ім'я}.\n\nЙди через тунель Альґаз, по дорозі через Заболоття і знайди Ашлана Камнесміха в Дун-Модрі. Раджу не сходити з дороги і не зупинятися.", [3] = "Старший інженер Греблер просить вас віднести знайдений порошок експерту з вибухівки Ашлану Камнесміху в Дун-Модр.", [4] = "А. ти щось {стать:сказав:сказала}? Ні біса не чую, у вухах дзвенить. Що це ти {стать:приніс:принесла}?", [5] = "Ох, старий Греблер не дарма хвилюється.", ["en"] = "A Dark Threat Looms", ["tasks"] = { ["Strange Smelling Powder"] = "порошок з дивним запахом", ["Strange Smelling Powder (Provided)"] = "порошок з дивним запахом (видано)" } },
    [1618] = { [1] = "Екіпірування Багрянокряжжя", [2] = "Ми, дворфи, не єдині, хто воює. Наші союзники — люди — не сидять склавши руки!\n\nНа Багрянокряжжя час від часу нападають орки Чорнокаменю, і їм завжди не вистачає спорядження. Якщо ти зможеш допомогти їм, я впевнений, що місцевий коваль, Вернер Осґуд, навчить тебе чомусь.", [3] = "Торм Ковоглиб хоче, щоб ви принесли 4 рунічні мідні пояси та 4 важкі мідні молоти Вернеру Осґуду в Багрянокряжжя.", [4] = "Сподіваюся, ти тут з хорошими новинами з Залізогарту. Бо я на межі!", [5] = "Дякую, {ім'я}. Це надзвичайно мені допоможе. Через напади орків Чорнокаменю з фортеці Кам'яної Варти та Багрянокрязьких гнолів з півночі, мені завжди доводиться лагодити обладунки та виготовляти нову зброю для наших військ.\n\nТепер я зможу трохи перепочити завдяки тобі. І в мене буде достатньо часу, щоб дечого тебе навчити...", ["en"] = "Gearing Redridge", ["tasks"] = { ["Heavy Copper Maul"] = "важкий мідний молот", ["Heavy Copper Maul (Provided)"] = "важкий мідний молот (видано)", ["Runed Copper Belt"] = "рунічний мідний пояс", ["Runed Copper Belt (Provided)"] = "рунічний мідний пояс (видано)" } },
    [163] = { [1] = "Воронячий пагорб", [2] = "Щось не так на Воронячому пагорбі, {ім'я}. Калор клянеться, що хтось, або щось, нишпорить в будівлях там. Протягом двох ночей він помічав, як тіні рухаються, а на третю він каже, що бачив світло в одному з вікон.\n\nЯкщо, як ти кажеш, тобі дійсно не байдужа безпека Смерколісся, з'ясуй, який монстр переслідує Воронячий пагорб.", [3] = "Дізнайтеся, що коїться на Воронячому пагорбі.", [5] = "Ні! Будь ласка, не вбивай мене! Це ж я... Тремтіній!! Вони всюди... Я не можу від них втекти! Монстри на Воронячому пагорбі? Н-н-ні... не може бути. Всього лише Тремтіній.", ["en"] = "Raven Hill" },
    [1639] = { [1] = "Пияка Бартлбі", [2] = "Так, я можу тебе вчити. Та перше я хочу подивитись, на що ти {стать:здатен:здатна}.\n\nБачиш того пияку в кінці бару? Бартлбі? Візьми його кружку.\n\nХех, якщо ти його знаєш, то можеш здогадатись, що просто так він тобі її не віддасть.", [3] = "Поговріть з Бартлбі.", [5] = "Здоров, {стать:красунчику:красуне}! Що таке ніжне створіння, як ти, забуло тут? Дивись, ніготь не зламай...", ["en"] = "Bartleby the Drunk" },
    [164] = { [1] = "Припаси для Свена", [2] = "Ти знаєш Свена? Ось хто справжній служитель Світла! Він та його послідовники отаборилися на північно-західному краю Смерколісся.\n\nОскільки їх так мало, на жаль, вони нікого не можуть виділити, щоб привезти припаси з міста. Чи можеш ти доставити йому ці припаси?", [3] = "Доставте припаси Свену.", [4] = "Виглядаєш досить {стать:міцним:міцною}, {клас:к}. Ти {стать:прийшов:прийшла}, щоб поповнити наші ряди?", [5] = "Ці припаси нам дуже знадобляться. Карвіни щедро допомагають нам. Ось тобі невеличка винагорода за твої клопоти.", ["en"] = "Deliveries to Sven", ["tasks"] = { ["Supplies for Sven"] = "припаси для Свена", ["Supplies for Sven (Provided)"] = "припаси для Свена (видано)" } },
    [1640] = { [1] = "Побити Бартлбі", [2] = "Тобі треба що?? Ти з глузду {стать:з'їхав:з'їхала}!\n\nЦю кружку ти забереш лише через мій труп!", [3] = "Побийте Бартлбі, після чого поговоріть з ним.", [4] = "Цю кружку ти забереш лише через мій труп!", [5] = "А ти міцніше, ніж здаєшся...", ["en"] = "Beat Bartleby", ["tasks"] = { ["Beat Bartleby"] = "Біт Бартлбі" } },
    [1641] = { [1] = "Фоліант божественності", [5] = "Тут, у Штормовії, я наставляю паладинів на шлях кращих чеснот, щоб вони присвятили себе священному Світлу та захищали Азерот від Скари та інших загроз.\n\nНастав твій час зробити перші кроки до справжньої доброчесності. Якщо приймеш цей шлях, я дам тобі фоліант божественності. Вивчаючи його, ти дізнаєшся дещо про Світло та про те, що від тебе очікується. Осягнувши його мудрість, ти зможеш досягти великих звершень.", ["en"] = "The Tome of Divinity" },
    [1642] = { [1] = "Фоліант божественності", [2] = "Всі діяння паладина мають бути достойними віри у Світло, яке сповнює нас силою. Наше прагнення божественності не означає бажання стати подібними богам — ми творимо добро своїми діяннями.\n\nХоч ми й маємо нищити зло, та не це вирізняє нас серед інших жителів Азероту. Милосердя, терпіння, хоробрість і допомога ближнім — ці речі значать для паладина стільки ж, скільки сила в битві.\n\nЗапам'ятай це і ніколи не забувай.", [3] = "Поговоріть з Даторіаном Раллом в Штормовії.", [5] = "І знову вітаю тебе, {ім'я:к}. Як проходить твоє вивчення фоліанта божественності?\n\nТи маєш приготуватись до випробувань. Тебе чекають великі справи: як в місті, так і за його стінами. Ти проявиш милосердя до тих, хто потребує допомоги та знищиш ворогів, що несуть загрозу нашому королівству.\n\nСвоїми добрими діяннями ти доведеш щирість своєї віри та світлість своїх намірів.", ["en"] = "The Tome of Divinity" },
    [1643] = { [1] = "Фоліант божественності", [2] = "Отож, {ім'я:к}, твоє завдання — знайти в Штормовії того, хто потребує допомоги. Когось зі світлим серцем і помислами. Того, хто допомагає іншим чи хто сам потребує допомоги. Як би то не було, наміри того, кого ти знайдеш, будуть благородними та на тебе будуть у всьому покладатись.\n\nПовертайся до мене, як закінчиш і ми обговоримо твій подальший шлях служителя Світла.", [3] = "Знайдіть Стефані Тернер в торговому районі Штормовію.", [5] = "О, вітаю, {стать:дорогенький:дорогенька}. Як твої пригоди? Ох, я рада знати, що в тебе все добре.\n\nЯ? А що я? Що ж, враховуючи обставини, справи йдуть непогано.\n\nУ нас тут побільшало торговців, що купують все підряд, тож і охочих віддавати речі на пожертви притулку поменшало. Та нічого, ми справимось. Під \"ми\" я маю на увазі мене й мого чоловіка. Він зараз в Залізогарті в пошуках допомоги від тамтешніх жителів.", ["en"] = "The Tome of Divinity" },
    [1644] = { [1] = "Фоліант божественності", [2] = "Нещасні душі, вони втратили свої сім'ї під час нападів Скари.\n\nМій чоловік Джон збирає матеріали, з яких я можу пошити одяг для сиріток. Та, на жаль, я не встигаю з цим — їх ще треба нагодувати та дати їм дах.\n\nЩо? Ти хочеш допомогти? Ох, слава Світлу! І дякую тобі, {ім'я:к}.\n\nЯкщо принесеш мені трохи лляної тканини — я зможу пошити одяг для діточок.", [3] = "Принесіть 10 відрізків лляної тканини до Стефані Тернер в Штормовій.", [4] = "Сподіваюсь, Джону пощастить в Залізогарті. Він дуже не любить далекі подорожі, бо залишає мене тут одну з дітьми. Та він знає, що це необхідно. Він такий добрий...\n\nІноді справи йдуть краще, та цей рік, здається, найважчий. Я відчуваю, що на нас чекають великі потрясіння. Та хто зна?", [5] = "Дякую, {ім'я:к}, дуже-дуже дякую.\n\nДіти будуть дуже раді. Та й в мене буде більше часу на інші обов'язки. Тепер я зможу зайнятись іншими потребами діточок, та й Джон має зовсім скоро повернутись.\n\nЩе раз дякую тобі, {ім'я:к}. Я знала, що в наших серцях ще є милосердя. Хай береже тебе Світло.", ["en"] = "The Tome of Divinity", ["tasks"] = { ["Linen Cloth"] = "лляна тканина", ["Linen Cloth (Provided)"] = "лляна тканина (видано)" } },
    [1645] = { [1] = "Фоліант божественності", [5] = "Рада тебе бачити, {ім'я:к}. Я займаюсь наставлянням паладинів на шлях кращих чеснот, щоб вони присвятили себе священному Світлу та захищали Азерот від Скари та інших загроз.\n\nНастав твій час зробити перші кроки до справжньої доброчесності. Якщо приймеш цей шлях, я дам тобі фоліант божественності. Вивчаючи його, ти дізнаєшся дещо про Світло та про те, що від тебе очікується. Осягнувши його мудрість, ти зможеш досягти великих звершень.", ["en"] = "The Tome of Divinity" },
    [1646] = { [1] = "Фоліант божественності", [2] = "Всі діяння паладина мають бути достойними віри у Світло, яке сповнює нас силою. Наше прагнення божественності не означає бажання стати подібними богам — ми творимо добро своїми діяннями.\n\nХоч ми й маємо нищити зло, та не це вирізняє нас серед інших жителів Азероту. Милосердя, терпіння, хоробрість і допомога ближнім — ці речі значать для паладина стільки ж, скільки сила в битві.\n\nЗапам'ятай це і ніколи не забувай.", [3] = "Поговоріть з Тізою Боєкузнею в Залізогарті.", [5] = "І знову вітаю тебе, {ім'я:к}. Сподіваюсь, ти {стать:займався:займалась} вивченням фоліанта?\n\nТи маєш приготуватись до випробувань. Тебе чекають великі справи: як в місті, так і за його стінами. Ти проявиш милосердя до тих, хто потребує допомоги та знищиш ворогів, що несуть загрозу нашому королівству.\n\nСвоїми добрими діяннями ти доведеш щирість своєї віри та світлість своїх намірів.", ["en"] = "The Tome of Divinity" },
    [1647] = { [1] = "Фоліант божественності", [2] = "Отож, {ім'я:к}, твоє завдання — знайти в Залізогарті того, хто потребує допомоги. Когось зі світлим серцем і помислами. Того, хто допомагає іншим чи хто сам потребує допомоги. Як би то не було, наміри того, кого ти знайдеш, будуть благородними та на тебе будуть у всьому покладатись.\n\nПовертайся до мене, як закінчиш і ми обговоримо твій подальший шлях служителя Світла. Я залишатимусь тут, в храмі, і чекатиму на твоє повернення. Іншим паладинам теж можуть знадобитись мої настанови.", [3] = "Знайдіть Джона Тернера на зовнішньому колі Залізогарту.", [5] = "СИРОТИНЕЦЬ ШТОРМОВ... Ох, вибачте, не хотів на вас кричати.\n\nЯ Джон Тернер. Як ваші справи?\n\nДобре, добре, радий чути, що у вас все добре. А в мене був важкий день і я дуже скучив за моєю дружиною, та це невелика ціна за те, щоб нагодувати та одягнути бідолашних сиріт.", ["en"] = "The Tome of Divinity" },
    [1648] = { [1] = "Фоліант божественності", [2] = "Ми з дружиною займаємось сиротинцем в Штормовії. Більшість тамтешніх дітей втратили батьків від нападів Скари. Я приїжджаю до Залізогарту щомісяця, щоб зібрати пожертви у місцевих жителів і знайти допомогу у місцевих організацій.\n\nЦя поїздка була дуже довгою і не дуже плідною.\n\nЯкщо знайдете трохи лляної тканини, я відправлю її додому і моя дружина зможе пошити одяг для дітей.", [3] = "Принесіть 10 відрізків лляної тканини Джону Тернеру в Залізогарт.", [4] = "Через наплив торговців нам приносять все менше речей для сиротинця. Твоє бажання допомогти надзвичайно благородне, {ім'я:к}. Дякую тобі.\n\nСподіваюсь, я зовсім скоро повернусь додому до моєї дружини.", [5] = "Це так великодушно, {ім'я:к}. Дуже тобі дякую.\n\nЦе дуже благородний вчинок. Видно, що ти не просто так {стать:обрав:обрала} шлях Світла. Я хочу тобі віддячити... Що кажеш? Не варто? Ось про що я кажу, {ім'я:к} — надзвичайна благородність.\n\nБережи себе і нехай Світло допомагає тобі.", ["en"] = "The Tome of Divinity", ["tasks"] = { ["Linen Cloth"] = "лляна тканина", ["Linen Cloth (Provided)"] = "лляна тканина (видано)" } },
    [1649] = { [1] = "Фоліант доблесті", [2] = "Доблесть і супутні їй чесноти подібні дорогоцінним металам: ти маєш берегти їх, адже вони надзвичайно цінні, але також потрібно витратити час на те, щоб їх зібрати та довести до ідеалу. Разом же вони утворюють надміцний сплав, що може витримати найпотужніші удари.\n\nТвоя сила, віра і сміливість мають пройти випробування. Ти маєш навчитись ніколи не втрачати віри та усвідомити, що з силою Світла ти можеш витримати те, чого інші не зможуть.", [3] = "Поговоріть з Даторіаном Раллом в Штормовії.", [5] = "То ти хочеш випробувати свою доблесть? Прекрасно.\n\nВ місті та навколишніх землях вдосталь задач, для яких можуть знадобитись твої навички.\n\nЦе випробування не з простих, {ім'я:к}. Як і всі інші речі на нашому шляху, тебе це може вбити. Наша церква прагне зміцнити свої ряди, але ми також розуміємо, що без жертв неможливо визначити найдостойніших паладинів.\n\nТи {стать:готовий:готова}?", ["en"] = "The Tome of Valor" },
    [165] = { [1] = "Відлюдник", [2] = "Колись давно до міста досить часто приходив один старець, щоб купити припаси, але я давно його не бачила. Якщо я правильно пам'ятаю, він живе в халупі поруч з кладовищем Воронячого пагорба. Можливо, тобі варто піти подивитися, чи все з ним гаразд.", [3] = "Відвідайте старця в халупі біля кладовища Воронячого пагорба.", [5] = "Елейн Карвін? Хехе, так... звичайно, Карвіни.\n\nНі, нічого не трапилось, але мені зараз важко виходити в місто. Дороги небезпечні, а я не молодшаю. Може, ти зробиш старому послугу?", ["en"] = "The Hermit" },
    [1654] = { [1] = "Випробування праведності", [2] = "Я хотів би віддячити тобі, якщо ти не проти. Але не зрозумій мене неправильно — твоя винагорода буде залежати від твоїх зусиль, але наша співпраця буде корисна нам обом.\n\nЯ викую для тебе зброю, гідну твоїх діянь — символ паладина та Світла. Та тобі доведеться зібрати всі необхідні для неї компоненти. Я вже почав складати список, потрібно тільки знайти когось сміливого і вправного, хто принесе мені їх. Ну, що скажеш, {клас:н}?", [3] = "Використовуючи вказівки Джордана, знайдіть деревину білокам'яного дуба, партію очищеної руди Джордана, ковальський молоток Джордана та очищений самоцвіт Кора і принесіть їх Джордану Стілвеллу в Залізогарт.", [4] = "Компоненти ці знайти буде непросто, та запевняю тебе, зброя, яку ти отримаєш, буде гідна твоїх зусиль.\n\nЦе буде моя найкраща робота і скромна винагорода за твою допомогу.", [5] = "Це дивовижно! Ти {стать:приніс:принесла} все необхідне.\n\nЗ цим я з легкістю створю неймовірну зброю. Насправді я давно збирався це зробити, та ніяк не міг зібрати компоненти. Дякую, {ім'я:к}.\n\nПриємно знову тримати в руках молоток мого батька... і самоцівіт Кора — я й не думав, що колись побачу його на власні очі.", ["en"] = "The Test of Righteousness", ["tasks"] = { ["Jordan's Refined Ore Shipment"] = "партія очищеної руди Джордана", ["Jordan's Refined Ore Shipment (Provided)"] = "партія очищеної руди Джордана (видано)", ["Jordan's Smithing Hammer"] = "ковальський молоток Джордана", ["Jordan's Smithing Hammer (Provided)"] = "ковальський молоток Джордана (видано)", ["Purified Kor Gem"] = "очищений самоцвіт Кора", ["Purified Kor Gem (Provided)"] = "очищений самоцвіт Кора (видано)", ["Whitestone Oak Lumber"] = "деревина білокам'яного дуба", ["Whitestone Oak Lumber (Provided)"] = "деревина білокам'яного дуба (видано)" } },
    [1655] = { [1] = "Партія руди Бейлора", [2] = "Ох, ну ти й {стать:налякав:налякала} мене. Хіба не бачиш, що я думаю?\n\nЩо? Поставка для Джордана... в Залізогарт. Ах, так, знаю про що ти. Огри Мо'ґрош... ось хто забрав партію руди для мого старого друга. Караван з рудою йшов сюди з Заболоття і потрапив в засаду. Охоронець з каравану помер кілька днів тому, не дочекавшись лікаря.\n\nЯкщо хочеш знайти цю партію руди — відправляйся на північний схід за озеро Лох. Воно десь там.", [3] = "Принесіть партію руди Джордана Бейлору Камнеруку в Лох-Модан.", [4] = "Ну, є щось? Хехе, ці огри отримають від тебе по повній, еге ж?", [5] = "Так-так, це вона. Ха! Якби я знав, що ти дійсно туди підеш і надаєш тим ограм, я б дав тобі цілий список всього, що треба звідти принести. Та ти ж тут не для того, щоб мої доручення виконувати, еге ж?\n\nУгода є угода: Джордану потрібна була партія руди і він її отримає.\n\nПередавай йому від мене привіт, {клас:к}. І бережи себе.", ["en"] = "Bailor's Ore Shipment", ["tasks"] = { ["Jordan's Ore Shipment"] = "партія руди Джордана", ["Jordan's Ore Shipment (Provided)"] = "партія руди Джордана (видано)" } },
    [1658] = { [1] = "Зірвати фестиваль Плетеного чоловічка", [2] = "Мені потрібні сміливці, які відправляться до Тірісфальського перелісся і знайдуть фестиваль Плетеного чоловічка. Не буду приховувати — ця подорож буде небезпечною. Стражі на фестивалі будуть особливо жорстокими. Але нам потрібно знати, наскільки великим буде фестиваль цього року і які проблеми відречені спричинять нам під час Повечір'я святих.\n\nЯкщо ти {стать:готовий:готова} до цього, вирушай до Тірісфалю та розвідай фестиваль. Повертайся до мене з інформацією, і я виплачу тобі щедру компенсацію.", [3] = "Знайдіть місце проведення фестивалю Плетеного чоловічка в Тірісфальському переліссі. Після цього поверніться до сержанта Гартмана в Південнобережжя.", [4] = "Ти вже {стать:був:була} у Тірісфальському переліссі та {стать:дивився:дивилася}, що там відбувається? Зазвичай вони проводять фестиваль неподалік від Підмістя...", [5] = "Гарна робота, {ім'я}. Фестиваль Плетеного чоловічка продовжить приносити проблеми, поки кляті відречені населяють залишки Лордерона. Це НЕ гідний спосіб вшанування колись гордого королівства, от що я скажу...\n\nОсь кілька монет за твою роботу, а також, в дусі свята, кілька ласощів, які тобі можуть сподобатись. Щасливого Повечір'я святих — зробімо все можливе, щоб зберегти безпеку Південнобережжя.", ["en"] = "Crashing the Wickerman Festival", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Scout out the Forsaken's Wickerman Festival."] = "Розвідайте фестиваль плетених людей Від'їханих." } },
    [166] = { [1] = "Братство Непокірних", [2] = "Залишилась ще одна справа для тебе. Ти маєш вбити Едвіна Ван-Кліфа. Як би я не хотів не виносити смертний вирок, та це на благо жителів Західного краю. Принеси мені його голову, як покінчиш з ним.", [3] = "Вбийте Едвіна Ван-Кліфа та принесіть його голову Ґріану Міцнокриву.", [4] = "Як успіхи з полюванням на Едвіна Ван-Кліфа?", [5] = "{Ім'я:к}, твоя хоробрість надзвичайна. Народне ополчення дякує тобі за службу народу Західного Краю. Смерть Ван-Кліфа покладе кінець Братству Непокірних. Сподіваюсь, зовсім скоро на ці землі повернеться мир та спокій.", ["en"] = "The Defias Brotherhood", ["tasks"] = { ["Head of VanCleef"] = "голова Ван-Кліфа", ["Head of VanCleef (Provided)"] = "голова Ван-Кліфа (видано)" } },
    [1665] = { [1] = "Кружка Бартлбі", [2] = "Добре, ось тобі кружка. Чекай! Дай доп'ю... На, тримай", [3] = "Принесіть Яроварту кружку Бартлбі", [4] = "Я бачив твою бійку з Бартлбі. Непогано! Ти {стать:приніс:принесла} кружку?", [5] = "А ось і кружка! Він так не хотів її віддавати, та ти вмієш наполягати на своєму. Молодець.\n\nА тепер до навчання...", ["en"] = "Bartleby's Mug", ["tasks"] = { ["Bartleby's Mug"] = "кружка Бартлбі", ["Bartleby's Mug (Provided)"] = "кружка Бартлбі (видано)" } },
    [1666] = { [1] = "Маршал Знесилій", [2] = "Ти {стать:вивчив:вивчила} кілька нових рухів, та тобі варто знайти кращу зброю. Думаю, маршал Знесилій може тобі з цим допомогти.\n\nМаршал Знесилій живе в своїй садибі в Ельвиннському лісі, в лісозаготівельному таборі Східнодолу. Він вже на пенсії, але за час служби зібрав непогану колекцію озброєння.\n\nСкажи йому, що тебе прислав я і, як пощастить, він поділиться зайвою зброєю.", [3] = "Поговоріть з маршалем Знесилієм.", [5] = "Хто це? Бурлґард, це ти? Підійди ближче, мій зір вже не той. Ти так підкрався, що я прийняв тебе за гнола!", ["en"] = "Marshal Haggard" },
    [1667] = { [1] = "Джек Мертвозуб", [2] = "Тебе прислав Яроварт, еге ж? Так, я можу запропонувати тобі деяку зброю, та спершу я попрошу тебе дещо зробити...\n\nНещодавно мене обдурив мерзотник з Братства Непокірних, Джек Мертвозуб. Було темно і він був в накидці Штормовію, а тому я прийняв його за маршала Дугана. Він попросив у мене мій старий Штормовійський значок маршала і я віддав йому його... А потім він розсміявся і втік, перш ніж я міг схопити його!\n\nПоверни мій значок! Джек Мертвозуб має бути у своєму таборі на півдні.", [3] = "Добудьте значок Знесилія в таборі Джека Мертвозуба і поверніть його маршалу Знесилію.", [4] = "Ти {стать:приніс:принесла} мій значок? Страшно подумати, що Джек Мертвозуб міг натворити з ним.", [5] = "Чудово, ти {стать:знайшов:знайшла} мій значок! Я думав, що втратив його назавжди, а ці негідники Братства Непокірних будуть прикидатись представниками Штормовійської влади. Що ж, тобі вдалося цьому запобігти, дякую.\n\nОсь деяка зброя, яку я використовував, коли був маршалом. Я її добре зберігав і вона в чудовому стані. Обирай собі до смаку!", ["en"] = "Dead-tooth Jack", ["tasks"] = { ["Marshal Haggard's Badge"] = "значок маршала Знесилія", ["Marshal Haggard's Badge (Provided)"] = "значок маршала Знесилія (видано)" } },
    [167] = { [1] = "О, брате мій...", [2] = "Ми були глибоко в шахті Західного краю під Місяцеграєм. Поняття не маю, звідки взялись ті гидкі злодюги. Хай там як, тунель шахти обвалився на нас. Мені вдалось вибратись, та інші... про них нічого невідомо з тих часів.\n\nМоже, тобі пощастить більше? Я шукаю свого брата. Він завжди носив свій значок Ліги дослідників. Якщо ти не зможеш знайти його, постарайся знайти хоча б значок...", [3] = "Принесіть значок Ліги дослідників, що належав десятнику Лютополоху, Вайлдеру Лютополоху в Штормовій.", ["en"] = "Oh Brother...", ["tasks"] = { ["Thistlenettle's Badge"] = "значок Лютополоха", ["Thistlenettle's Badge (Provided)"] = "значок Лютополоха (видано)" } },
    [168] = { [1] = "Збір спогадів", [2] = "Багато моїх друзів загинуло того жахливого дня, коли шахта обвалилася. Якщо пригоди заведуть тебе у те крило шахти в Місяцеграї, будь ласка, спробуй знайти щось, що допомогло б їх ідентифікувати. Якщо натрапиш на будь-яку з їхніх карток спілки шахтарів, принеси їх мені, я відправлю їх сім'ям загиблих.", [3] = "Добудьте 4 картки спілки шахтарів та поверніть їх Вайлдеру Лютополоху в Штормовій.", [4] = "Тобі вдалось знайти картки спілки шахтарів, що належали моїм друзям?", [5] = "Я дуже вдячний тобі, {ім'я}. Твої зусилля допоможуть принести спокій постраждалим від цієї трагедії. Я прослідкую, щоб сім'ї загиблих отримали їх.", ["en"] = "Collecting Memories", ["tasks"] = { ["Miners' Union Card"] = "картка спілки шахтарів", ["Miners' Union Card (Provided)"] = "картка спілки шахтарів (видано)" } },
    [1681] = { [1] = "Майстерня Залізоплета", [2] = "У мого вчителя, Стурґі Залізоплета, була майстерня на південь від озера Постеля Гельма, в якій він навчав ковальству. Він був в цьому найкращим.\n\nТа одного дня, його студент приніс партію дивної руди. Вчитель Залізоплет назвав її смерковою рудою і радо з нею працював. Але зовсім скоро на майстерню напала банда дворфів Темного Заліза. Вони всіх вбили!\n\nЙди до майстерні Залізоплета, {ім'я}, і помстись за мого вчителя. І принеси мені смеркову руду.", [3] = "Принесіть смерекову руду Торму Ковоглибу в Залізогарт.", [4] = "Ти вже {стать:був:була} в майстерні Залізоплета? Там була смеркова руда?", [5] = "Ти {стать:знайшов:знайшла} її! Чудово!\n\nСподіваюсь, ти {стать:вбив:вбила} багато дворфів Темного Заліза, поки {стать:шукав:шукала} її. Боюсь, ми ще зіткнемось з ними...\n\nТа дякую тобі за руду, {ім'я}. Я вже спішу зайнятись її обробкою.", ["en"] = "Ironband's Compound", ["tasks"] = { ["Umbral Ore"] = "смеркова руда", ["Umbral Ore (Provided)"] = "смеркова руда (видано)" } },
    [1682] = { [1] = "Зброя із сірого заліза", [5] = "А ось і зброя зі смеркової руди. Щойно з ковадла!\n\nПрошу, {ім'я}, вибирай!", ["en"] = "Grey Iron Weapons" },
    [169] = { [1] = "Розшукується: Ґат'Ільзоґґ", [2] = "Розшукується! Ґат'Ільзоґґ, ватажок нападів Чорнокаменю на фортецю Кам'яної Варти та набігів на околиці Приозер'я.\n\nҐат'Ільзоґґ надзвичайно небезпечний. За останніми даними, він переховується у нещодавно захопленій фортеці та планує нові злочини проти людства. Навала орків має бути знищена за будь-яку ціну. Сміливець, який принесе голову Ґат'Ільзоґґа війту Соломону, буде щедро винагороджений.", [3] = "Вбийте Ґат'Ільзоґґа та принесіть його голову війту Соломону в Приозер'я, щоб отримати винагороду.", ["en"] = "WANTED: Gath'Ilzogg", ["tasks"] = { ["Head of Gath'Ilzogg"] = "голова Ґат'Ільзоґґа", ["Head of Gath'Ilzogg (Provided)"] = "голова Ґат'Ільзоґґа (видано)", ["Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward."] = "Вбийте Ґат'Ільзоґґа та принесіть його голову війту Соломону в Приозер'я, щоб отримати винагороду." } },
    [170] = { [1] = "Нова загроза", [2] = "Сподіваюся, ти тут для того, щоб допомогти нам, {клас:к}. Після недавнього нападу трогів, нам знадобиться будь-яка допомога.\n\nЯ чув, що ці мерзотники тепер з'являються всюди й Морозна долина — не виключення. Їх повно в горах на південному сході й біля замерзлого озера.\n\nАле і це ще не все! Лише кілька ночей тому вони напали на наш табір на заході та розгромили його!\n\nНас малувато тут, {стать:хлоп'яга:дівча}, і нам не завадить допомога, щоб відігнати трогів.", [3] = "Балір Кригомолот хоче, щоб ви вбили 6 кам'янощелепих трогів та 6 кремезних кам'янощелепих трогів.", [4] = "Наполегливі гади, еге ж?", [5] = "Якщо проблеми, які ми мали тут, відбуваються всюди, то, клянусь бородою Маґні, — нас чекають неприємності! Я можу лише сподіватись, що король та сенат вживають заходів для подолання загрози, яку становлять троги.", ["en"] = "A New Threat", ["tasks"] = { ["Burly Rockjaw Trogg"] = "кремезний кам'янощелепий трог", ["Burly Rockjaw Trogg slain"] = "кремезний кам'янощелепий трог: убито", ["Rockjaw Trogg"] = "кам'янощелепий трог", ["Rockjaw Trogg slain"] = "кам'янощелепий трог: убито" } },
    [1700] = { [1] = "Ґріманд Елмор", [2] = "Я зробив копію своїх записів про виготовлення броні і мені потрібен хтось, хто віднесе їх Ґріманду Елмору. Він тут, в дворфійському районі, в крамниці зброї.\n\nВін не зрадіє тобі, бо занадто пишається своїми навичками і навіть не подумає навчатись чомусь у мене...", [3] = "Принесіть Ґріманду Елмору записи Фьюрена.", [4] = "Вітаю і ласкаво прошу. Чим можу допомогти?", [5] = "Це Фьюрен написав? Як він сміє! Та я навчив його всьому, що він знає! Кого це він надумав вчити?!\n\nХм... але в його нотатках є дещо, що я міг би спробувати...", ["en"] = "Grimand Elmore", ["tasks"] = { ["Furen's Notes"] = "записи Фьюрена", ["Furen's Notes (Provided)"] = "записи Фьюрена (видано)" } },
    [1703] = { [1] = "Матіель", [2] = "Я зробив копію своїх записів про виготовлення броні і мені потрібен хтось, хто віднесе їх ковалю Матіелю. Він живе в Дарнасі. Дорога далека, та я певен, що він буде дуже вдячний, коли дізнається про моє відкриття.", [3] = "Принесіть Матіелю записи Фьюрена.", [4] = "Вітаю тебе, {клас:к}.", [5] = "Це цікаво, справді, дуже цікаво. Мій колега-дворф Фьюрен зробив грандіозне відкриття!\n\nДякую, {ім'я}. Для мене буде честю застосувати його нову техніку у своїх роботах.", ["en"] = "Mathiel", ["tasks"] = { ["Furen's Notes"] = "записи Фьюрена", ["Furen's Notes (Provided)"] = "записи Фьюрена (видано)" } },
    [1704] = { [1] = "Клокморт Гайковерт", [2] = "Я зробив копію своїх записів про виготовлення броні і мені потрібен хтось, хто віднесе їх Клокморту Гайковерту. Він гномський коваль в Залізогарті. І коли він дізнається про моє відкриття... Він собі бороду повисмикує від захвату!", [3] = "Принесіть Клокморту Гайковерту записи Фьюрена.", [4] = "Добридень... Чи ранок... Чи вечір... Тут внизу цього не видно. Отож, чого ти хочеш від мене?", [5] = "О Боже! Ці записи дивовижні! Ба більше... Вони неймовірні та приголомшливі, я ледве на ногах стою від захвату!\n\nФьюрен здійснив прорив у ковальській справі! Так-так, справжнісінький прорив! Мені не терпиться випробувати нову технологію!", ["en"] = "Klockmort Spannerspan", ["tasks"] = { ["Furen's Notes"] = "записи Фьюрена", ["Furen's Notes (Provided)"] = "записи Фьюрена (видано)" } },
    [171] = { [1] = "Опікун Альянсу", [2] = "Ти {стать:був:була} дуже {стать:добрим:доброю} до мене, {ім'я}. Я й уявити не міг, що дитячий тиждень буде таким веселим. Дякую. Я не хочу засмучуватися через власну долю — мені завжди казали, що я маю переборювати всі нещастя. Знаєш, коли я виросту, я хочу стати героєм... як ти.\n\nЯк це не сумно, та мені пора додому. Давай повернемося, і я розповім нашій опікунці, наскільки ти {стать:класний:класна}!", [3] = "Поверніть свого підопічного до притулку Штормовію, передавши свисток сироти опікунці сиротинця Ночевітру на Соборній площі.", [4] = "Приємно знову бачити тебе, {ім'я}. Ти {стать:виконав:виконала} всі обов'язки, на які ти добровільно {стать:погодився:погодилася} під час дитячого тижня?", [5] = "Нехай небеса благословлять тебе, {ім'я}. Ти {стать:зробив:зробила} більше для Рандіса, ніж багато хто зумів би зробити для нього. Дякую тобі, ти — сяйниста зірка на небосхилі Альянсу.\n\nБудь ласка, якщо у тебе буде час — заходь до нас у гості. Рандіс хотів би цього не менше за мене.\n\nЙому було так весело з тобою, {ім'я}. Рандіс хотів подарувати тобі одного зі своїх улюбленців, щоб ти завжди {стать:згадував:згадувала} його.", ["en"] = "A Warden of the Alliance", ["tasks"] = { ["Human Orphan Whistle"] = "свисток сироти", ["Human Orphan Whistle (Provided)"] = "свисток сироти (видано)" } },
    [173] = { [1] = "Воргени в лісі", [2] = "Темрява неминуче підступає до Смерколісся. Задача майстра Карвіна — вигнання зла та єресі. Завдяки нашим зусиллям жителі Темнодолу залишаються в безпеці.\n\nТи вважаєш себе {стать:гідним:гідною} долучитися до нашої справи?\n\nЯ колись думав так само, я був розчарований бездіяльністю варти та приєднався до майстра Карвіна. Якщо ти хочеш довести свою гідність, то не словами.\n\nПеревір свої навички у боротьбі з воргенами, тіньовими ткачами Ночегибелі в Сяючому гаю та Гниючому саду.", [3] = "Убийте 6 тіньових ткачів Ночегибелі для Калора з Темнодолу.", [4] = "{ім'я}, як проходить полювання?", [5] = "Вражаюче, {ім'я}. Очевидно, ти можеш дати собі раду. Мабуть, твоїм здібностям слід знайти більш гідне застосування.\n\nЦікаво... Здається, ці воргени з'явилися просто нізвідки. Але враховуючи всіх інших дивних істот, які перетинають наш кордон, я вважаю, що це лише одна з багатьох проблем, що викликає занепокоєння.", ["en"] = "Worgen in the Woods", ["tasks"] = { ["Nightbane Shadow Weaver"] = "тіньовий ткач Ночегибелі", ["Nightbane Shadow Weaver slain"] = "тіньовий ткач Ночегибелі: убито" } },
    [1738] = { [1] = "Серцедерево", [2] = "Готуючись до твого приходу я використовував свій дар передбачення та подивився на світи крізь імлу часу. Я знайшов те, що ти шукаєш.\n\nПід час війни Древніх двоє закоханих загинули разом в битві. Там, де вони зробили останній подих, виросло дерево, відоме як Серцедерево — символ їхньої безсмертної любові.\n\nЦього має бути достатньо, щоб спокусити сукуба. Ти знайдеш його в руїнах Орділ'Арану на північному заході Ясенедолу.", [3] = "Знайдіть серцедерево в Ясенедолі та принесіть його Ґакіну Темнопряду у квартал Магів Штормовію.", [4] = "Є успіхи в пошуках, {ім'я}?", [5] = "Так, я відчуваю, що це підійде, дай мені трохи попрацювати з ним, хвилину...\n\nТакар — дуже винахідливий хлопчина, чи не так? Шкода, що я не можу переконати його повернутися до цивілізації.", ["en"] = "Heartswood", ["tasks"] = { ["Heartswood"] = "серцедерево", ["Heartswood (Provided)"] = "серцедерево (видано)" } },
    [174] = { [1] = "Поглянь на зірки", [2] = "Мій друг-гном, Шестірня, пообіцяв допомогти мені створити пристрій, який дозволить мені досліджувати зірки. Існує істина, що не стосується магії, що може пояснити те, що коїться в лісі.\n\nПринеси мені бронзову трубку, зроблену досвідченим інженером. Це перший крок, згідно з кресленнями Шестірні.", [3] = "Вікторі Прізм'Антрас з Темнодолу просить вас принести йому бронзову трубку.", ["en"] = "Look to the Stars", ["tasks"] = { ["Bronze Tube"] = "бронзова трубка", ["Bronze Tube (Provided)"] = "бронзова трубка (видано)" } },
    [175] = { [1] = "Поглянь на зірки", [2] = "Згідно з кресленнями Шестірні, мені зараз потрібно щось, що відбиватиме світло. Я пам'ятаю жінку, на ім'я Мері, яка завжди носила з собою дзеркальце. Можливо, ти зможеш відшукати Мері та запитати її, чи не позичить вона нам цю сітловідбивальну поверхню для цього проєкту? Я пригадую, що вона колись жила на півдні Смерколісся...", [3] = "Знайдіть Мері та переконайте її віддати сітловідбивальну поверхню для проєкту Вікторі.", [5] = "Так, у мене колись було дзеркальце.", ["en"] = "Look To The Stars" },
    [176] = { [1] = "Розшукується: \"Кнурило\"", [2] = "Розшукується: Кнурило\n\nВеличезний гнол, Кнурило, вештається лісами південно-західного Ельвинну. Попри усі спроби, схопити його так і не вдалося.\n\nАрмія Штормовію назначила щедру винагороду за цього гнола. Щоб отримати її, потрібно пред'явити маршалові Дугану в Злотохресті доказ смерті Кнурила.", [3] = "Покінчіть із гнолом Кнурилом і принесіть його величезну лапу маршалові Дугану.", [4] = "Так, Кнурило став справжньою мукою для мене та моїх людей. Ти маєш що повідомити про цього звіра?", [5] = "Та невже?! Молодець! Я почав уже думати, що цього монстра ніхто не здолає!\n\nОсь твоя винагорода, {ім'я}. І щиро дякую — той гнол завдавав мені клопоту розміром з Чорноскельну гору!", ["en"] = "Wanted: \"Hogger\"", ["tasks"] = { ["Huge Gnoll Claw"] = "величезна лапа гнола", ["Huge Gnoll Claw (Provided)"] = "величезна лапа гнола (видано)" } },
    [177] = { [1] = "Поглянь на зірки", [2] = "Дзеркальце було одним з моїх найдорожчих скарбів, поки... не сталося дещо. Після цього я викинула його за амбаром. Там колись бродив божевільний гуль. Можливо, він його підібрав. Ходять чутки, що цей диявольський звір мешкає на цвинтарі при Затишних садах", [3] = "Заберіть дзеркальце сліпої Мері у божевільного гуля та віддайте його Вікторі в Темнодолі.", [4] = "Я показав Шестірні проєкт нашого апарату для спостереження за зірками. Він був вражений. Ти випадково не {стать:знайшов:знайшла} сітловідбивальний пристрій?", [5] = "Шедеврально! Це неодмінно спрацює. Я глибоко вдячний!", ["en"] = "Look To The Stars", ["tasks"] = { ["Mary's Looking Glass"] = "дзеркальце Мері", ["Mary's Looking Glass (Provided)"] = "дзеркальце Мері (видано)" } },
    [1778] = { [1] = "Фоліант божественності", [2] = "Я збираюсь скоро повертатись додому. Сподіваюсь, у Стефані в Штормовії справи йдуть добре. Не можу дочекатися, коли побачусь з нею. До наступної зустрічі, {клас:к}.", [3] = "Поговоріть з Тізою Боєкузнею в Залізогарті.", [5] = "Так скоро {стать:повернувся:повернулась}? І що тобі вдалося зробити за цей час?\n\nБлагородна допомога нужденним? Схоже, ти {стать:засвоїв:засвоїла} цінність доброчинності та важливість твоїх обов'язків перед жителями Азероту. Що ж, розказуй, кому і чим {стать:допоміг:допомогла}... Неймовірно, {ім'я:к}, це вчинок {стать:істинного послідовника:істинної послідовниці} Світла.\n\nТакі жертви щедро винагороджуються.", ["en"] = "The Tome of Divinity" },
    [1779] = { [1] = "Фоліант божественності", [2] = "Візьми це, {ім'я:к}. Це — знак життя.\n\nТи {стать:довів:довела} своє милосердя та терпіння, а тепер я хочу, щоб ти {стать:проявив:проявила} свої здібності в бою та силу.\n\nМій чоловік, Муйредон, нещодавно повернувся після бою з дворфами Темного Заліза. Він ледь залишився живим і зараз один з наших жерців заліковує його рани.\n\nВізьми цей знак і поговори з ним. Як зможеш йому допомогти — ми знову зустрінемось. Нехай тобі сяє Світло.", [3] = "Візьміть знак життя та поговоріть з Муйредоном Боєкузнею в Залізогарті.", [5] = "*кхе-кхе*\n\nЗдрастуй, {клас:к}. Не гляди на рани, добрий жрець хороше дбає про старого Муйредона. Сила знаку життя поки тут не потрібна.\n\nТо тебе послала моя дружина, ге? Хе, справедливо. Що ж, я розкажу тобі що сталосі з Муйредоном та його ліпшим другом Нармом, таким же паладином, як ти.", ["en"] = "The Tome of Divinity", ["tasks"] = { ["Symbol of Life"] = "знак життя" } },
    [1780] = { [1] = "Фоліант божественності", [2] = "Я сьогодні ж віднесу це до притулку. Бережи себе, {стать:добрий:добра} {клас:к}. Не часто тут можна зустріти {стать:такого:таку} {раса:з}, як ти. Та ти {стать:довів:довела}, що паладини Штормовію не залишать нужденних в біді.", [3] = "Поговоріть з Даторіаном Раллом в Штормовії.", [5] = "Ти так скоро {стать:повернувся:повернулась}, {ім'я:к}. І що тобі вдалося зробити за час, проведений поза храмом?\n\nБлагородна допомога нужденним? Схоже, ти {стать:засвоїв:засвоїла} цінність доброчинності та важливість твоїх обов'язків перед жителями Азероту. Що ж, розказуй, кому і чим {стать:допоміг:допомогла}... Неймовірно, {ім'я:к}, це вчинок {стать:істинного послідовника:істинної послідовниці} Світла.\n\nТакі жертви щедро винагороджуються.", ["en"] = "The Tome of Divinity" },
    [1781] = { [1] = "Фоліант божественності", [2] = "Візьми це, {ім'я:к}. Це — знак життя.\n\nТи {стать:довів:довела} своє милосердя та терпіння, а тепер прийшов час перевірити, чи вистачить тобі сил для одного з найвеличніших дарів Світла.\n\nМій друг, Ґазін, нещодавно повернувся після бою з Непокірними в Ельвинні біля Варти Героїв. Він ледь залишився живим і зараз один з наших жерців заліковує його рани біля вівтаря.\n\nВізьми цей знак і поговори з ним. Як зможеш йому допомогти — ми знову зустрінемось. Нехай тобі сяє Світло.", [3] = "Віднесіть знак життя Ґазіну Тенорму в Штормовій.", [5] = "*кхе-кхе*\n\nВітаю тебе, {клас:к}. Не зважай на мої рани, добрий жрець гарно дбає про старого Ґазіна. Сила знаку життя мені не знадобиться... принаймні поки що.\n\nОтже, тебе відправив Даторіан, еге ж? Хех, справедливо. Що ж, я розкажу тобі що сталося зі мною та моїм другом Гензе. Якщо нам пощастить і тобі вистачить сил, можливо, ти ще зможеш нам допомогти.", ["en"] = "The Tome of Divinity", ["tasks"] = { ["Symbol of Life"] = "знак життя" } },
    [1783] = { [1] = "Фоліант божественності", [2] = "Ми шпигували за кількома дворфами Темного Заліза, що засіли на південь від озера Постеля Гельма. Ми знали що вони щось затівають, тож ми з Нармом рішили підійти ближче, щоб підслухати розмови командувача.\n\nМи отримали шанс вбити кількох, та вони виявились сильніше й оточили нас. Нарм сказав мені бігти по допомогу й ось я тут.\n\nНарму треба допомогти, і я не вспокоюсь поки він її не отримає.\n\nПоможеш, {ім'я:к}?", [3] = "Візьміть знак життя та воскресіть Нарма Фока в Дун-Морозі.", [5] = "Не знаю як тобі віддячити, {стать:брате:сестро}.\n\nСхоже, Тіза та Муйредон відправили тебе на допомогу, раз ти несеш знак життя.\n\nТак, це правда, мене звалили дворфи Темного Заліза коли я намагався добути їх записи. Я протримався достатньо, щоб Муйредон міг врятуватись та майже відійшов до Світла, коли {стать:прийшов:прийшла} ти. Те, що тобі вистачило сил, багато означає для тебе. Та про це пізніше.", ["en"] = "The Tome of Divinity", ["tasks"] = { ["Narm Faulk"] = "Нарм Фок", ["Narm Faulk slain"] = "Нарм Фок: убито" } },
    [1784] = { [1] = "Фоліант божественності", [2] = "Перед тим, як мене вбили, ми з Муйредоном майже прикінчили одного зі шпигунів Темного Заліза біля того маленького будинку. Ми побачили, як їх капітан роздає папери з наказами, тому вирішили вбити одного з них і добути ці папери.\n\nДехто в раді Залізогарту все ще не вірить в присутність дворфів Темного Заліза в Дун-Морозі. Отримавши ці накази, ми мали б не тільки докази, а й плани Темного Заліза.\n\nДобудь один з цих наказів і віднеси Муйредону, {ім'я:к}.", [3] = "Добудьте накази Темного Заліза у дворфів Темного Заліза біля озера Постеля Гельма і поверніться до Муйредона Боєкузні в Залізогарт.", [4] = "Ти {стать:вернувся:вернулась}! Радий бачити тебе, {ім'я:к}. Мої рани загоїлися і я збираюся повернутись до озера Постеля Гельма, щойно переконаю дружину, що зі мною все буде добре.", [5] = "Хе-хе! Ти це {стать:зробив:зробила}! {стать:Врятував:Врятувала} Нарма і {стать:добув:добула} докази, які моя дружина зможе віднести до ради.\n\nЩе раз дякую тобі та хай благословить тебе Світло, {ім'я:к}.", ["en"] = "The Tome of Divinity", ["tasks"] = { ["Dark Iron Script"] = "накази Темного Заліза", ["Dark Iron Script (Provided)"] = "накази Темного Заліза (видано)" } },
    [1785] = { [1] = "Фоліант божественності", [2] = "Бачу, моя дружина прямо пашить гордістю. Ти б скоріше {стать:йшов:йшла} до неї — бач, вона хоче з тобою про щось поговорити.\n\nХай береже тебе Світло, {стать:славний:славна} {клас:к}. Побачимось на битві проти Скари та клану Темного Заліза, коли прийде пора.", [3] = "Поговоріть з Тізою Боєкузнею в Залізогарті.", [5] = "Ти сьогодні добре {стать:допоміг:допомогла} Залізогарту, {ім'я:к}. Я пишаюсь тим, що ти {стать:один:одна} з нас і якщо ти {стать:готовий:готова} - я хотіла б благословити тебе цим сувоєм. Знак життя має силу лиш в руках {клас:р}, що {стать:готовий:готова} прийняти один з найвеличніших дарів Світла — дар повертати мертвих до життя.\n\nЯ навчу тебе, як користуватись цим умінням, щоб воскрешати своїх супутників. Користуйся ним відповідально, {ім'я:к}, і прийми подяку від мене, мого чоловіка та всього Залізогарту.", ["en"] = "The Tome of Divinity" },
    [1786] = { [1] = "Фоліант божественності", [2] = "Ми з Гензе дістались до Варти Героїв — острову посеред озера Кам'яних Обелісків на північному сході Ельвинна. Ходять чутки, що Непокірні проникли в наші землі й ми мали дістати докази для радників короля.\n\nМи побачили кількох покидьків, що переглядали якісь документи, і напали на них. Та, на жаль, нас хутко оточили їхні маги.\n\nГензе затримав їх, щоб я міг врятуватись... клятий дурень, вирішив погеройствувати...\n\nВін там і залишився. Ти допоможеш, {ім'я:к}?", [3] = "Візьміть знак життя та воскресіть Гензе Фока в Ельвинні.", [5] = "Дякую тобі, {стать:брате:сестро}.\n\nБачу, ти маєш знак життя. Тебе ж прислав Даторіан чи Ґазін, чи не так?\n\nМи з Ґазіном намагались викрасти плани Непокірних, та на нас напали їхні чаклуни. Мені вдалось протриматись достатньо, щоб Ґазін зміг врятуватись, та врешті решт їхня магія добила мене.\n\nТа тобі вдалось повернути мене до життя. Не всі мають здатність використовувати знак життя, {ім'я:к}. Це означає, що твоя віра надзвичайно глибока.", ["en"] = "The Tome of Divinity", ["tasks"] = { ["Henze Faulk"] = "Гензе Фок", ["Henze Faulk slain"] = "Гензе Фок: убито" } },
    [1787] = { [1] = "Фоліант божественності", [2] = "У нас ще буде час поговорити про знак. Зараз важливіше дістати ті папери, що переглядали Непокірні. Якщо ми добудемо їх, у нас будуть докази присутності Непокірних в Ельвинні та, сподіваюсь, розуміння їх планів.\n\nЯ поки не здатен битись, {ім'я:к}. Як думаєш, зможеш піти на острів самотужки та відібрати ті документи?\n\nЯк добудеш їх — віднеси їх Ґазіну і передай, що зі мною все добре.", [3] = "Добудьте накази Непокірних у чарівників-пройдисвітів Непокірних в Ельвинні та поверніться то Ґазіна в Штормовій.", [4] = "Гензе в безпеці, {ім'я:к}? Тобі вдалося?\n\nЗ твоїми бойовими вміннями та силою Світла нам на Варті Героїв можна не боятись Непокірних. Та останнє слово за королем та його радниками.", [5] = "Неймовірно! Тобі вдалося врятувати Гензе! Світло воістину сяє в тобі, {ім'я:к}!", ["en"] = "The Tome of Divinity", ["tasks"] = { ["Defias Script"] = "накази Непокірних", ["Defias Script (Provided)"] = "накази Непокірних (видано)" } },
    [1788] = { [1] = "Фоліант божественності", [2] = "Я передам ці накази радникам короля після того, як Даторіан погляне на них, та поки що ти маєш йти до нього. Певен, він теж захоче віддячити тобі.\n\nЩе раз дякую тобі, {ім'я:к}. Сподіваюсь, ще побачимось. Радий мати {стать:такого друга:таку подругу}, як ти.", [3] = "Поговоріть з Даторіаном Раллом в Штормовії.", [5] = "Ти добре {стать:постарався:постаралась} сьогодні, {ім'я:к}. Ти можеш пишатись своїми діяннями.\n\nБа більше, ти маєш пишатись своїми силами. Не кожен має змогу використовувати знак життя. Вміння використовувати силу Світла для повернення до життя означає, що ти {стать:готовий:готова} прийняти найвеличніший дар для {клас:р} — дар воскресіння.\n\nТи зможеш використовувати свої сили, щоб повертати до життя своїх союзників так само як Генза.\n\nНехай щастить, {ім'я:к}. Світло осяює тебе, прийми його в собі.", ["en"] = "The Tome of Divinity" },
    [1789] = { [1] = "Знак життя", [5] = "{ім'я:к}, якщо тобі не вдасться використати знак життя, щоб допомогти Нарму — повертайся до мене і я дам тобі ще один.\n\nНам з чоловіком дуже важливо, щоб тобі все вдалося. Поспіши, прошу тебе.", ["en"] = "The Symbol of Life" },
    [179] = { [1] = "Дворфійські екіпірувальники", [2] = "Що тут у нас? Виглядаєш так, ніби тобі може знадобитися щось, щоб зігріти руки, га?\n\nЯ скажу, що тобі потрібно: пара хороших теплих рукавичок. І така добра душа, як я, буде більш ніж рада забезпечити тобі відповідну пару. Однак у мене одна умова.\n\nТреба, щоб ти {стать:здобув:здобула} мені вовчого м'яса. Файна угода, так? Ти принесеш мені трохи вовчого м'яса, а я подбаю, щоб ти не {стать:втратив:втратила} жодного пальця від обмороження. Ну, що скажеш?", [3] = "Стен Міцнорук хотів би отримати 8 шматків жорсткого вовчого м'яса.", [4] = "Вовки завдали тобі трохи клопоту? Краще уникати ікл, кігтів, та інших гострих штук, еге ж?", [5] = "А! Чудово. Вовче м'ясо — це те, що треба. О, не хвилюйся, {ім'я}, я не забув про свою частину угоди. Ось, щось з цього тобі підійде.", ["en"] = "Dwarven Outfitters", ["tasks"] = { ["Tough Wolf Meat"] = "жорстке вовче м'ясо", ["Tough Wolf Meat (Provided)"] = "жорстке вовче м'ясо (видано)" } },
    [1790] = { [1] = "Знак життя", [5] = "Поспіши, {ім'я:к}. Багато життів залежить від тебе.\n\nЯкщо тобі не вдасться допомогти Ґазіну та Гензе — повертайся до мене і я дам тобі ще один знак життя.\n\nНе думай, що я допомагаю тобі просто так. Ти маєш довести свою гідність, як і всі інші паладини. Постійні невдачі — не найкращий шлях.", ["en"] = "The Symbol of Life" },
    [18] = { [1] = "Братство злодіїв", [2] = "Нещодавно навколо Північнокраю почала тинятися нова група злодіїв. Вони називають себе Братством Непокірних і їх бачили за річкою на сході.\n\nЯ не знаю, що вони замислили, але я впевнений, що нічого доброго! Принеси мені бандани, які вони носять, а я, своєю чергою, нагороджу тебе зброєю.", [3] = "Принесіть 12 червоних бандан з мішковини заступникові Віллему неподалік Північнокрайового абатства.", [4] = "Ти вже {стать:зібрав:зібрала} їхні бандани?", [5] = "О, бачу, ти {стать:повернувся:повернулася} з кількома банданами. Армія Штормовію вдячна за твою допомогу.", ["en"] = "Brotherhood of Thieves", ["tasks"] = { ["Red Burlap Bandana"] = "червона бандана з мішковини", ["Red Burlap Bandana (Provided)"] = "червона бандана з мішковини (видано)" } },
    [180] = { [1] = "Розшукується: лейтенант Тельбухожбур", [2] = "Розшукується: лейтенант Тельбухожбур\n\nВідомий ватажок клану тінешкурих гнолів, що працює на Морґанта, ворога міста та Королівства. За наказом війта Соломона, цього підлого зрадника Штормовію засуджено до смерті. Принесіть його лапу війту як доказ здійснення правосуддя.", [3] = "Вбийте лейтенанта Тельбухожбура та поверніться до війта Соломона з його лапою.", ["en"] = "WANTED: Lieutenant Fangore", ["tasks"] = { ["Fangore's Paw"] = "лапа Тельбухожбура", ["Fangore's Paw (Provided)"] = "лапа Тельбухожбура (видано)" } },
    [181] = { [1] = "Поглянь на зірки", [2] = "Тепер лишився лише один предмет, щоб завершити цей пристрій. За кресленнями Шестірні потрібна якась лінза. Єдину відому мені лінзу, яка була б достатньо великою, буде дуже важко дістати.\n\nЄ огр, на ім'я Ззарк'Вул, який мешкає в кургані на півдні Смерколісся. Якщо зможеш, принеси мені його монокль, і я використаю його як лінзу!", [3] = "Знайдіть Ззарк'Вула на південному кургані огрів у Смерколіссі та принесіть його монокль Вікторі в Темноділ.", [4] = "Ти {стать:зміг:змогла} переконати Ззарк'Вула позичити свій монокль для нашого експерименту?", [5] = "Нарешті! Пристрій для спостереження за зірками готовий! Дякую тобі, {ім'я}. Тепер я можу продовжити свої дослідження...", ["en"] = "Look To The Stars", ["tasks"] = { ["Ogre's Monocle"] = "монокль огра", ["Ogre's Monocle (Provided)"] = "монокль огра (видано)" } },
    [182] = { [1] = "Печера тролів", [2] = "Мене з моїм братом Сеніром відправили в Дун-Морог для дослідження загрози, яку становлять тролі. Сенату вистачає клопотів з трогами, тож зайві проблеми їм ні до чого.\n\nНаскільки я бачу, тролі ще не закріпились в Морозній долині - в основному вони живуть в південній печері. Як на мене, допомога армії тут не знадобиться - кількох вправних рук буде достатньо.\n\nМоже, й ти не проти долучитись? У мене буде чим віддячити за допомогу.", [3] = "Ґрелін Білобород просить вас вбити 14 морозогривих молодих тролів.", [4] = "Наскільки я знаю, ці тролі походять з племені Морозогривих. На жаль, більше корисної інформації для тебе я не маю, {ім'я}.", [5] = "Ух, кляті тролі! Да покарає їх Світло!\n\n<Ґрелін робить кілька вдохів і, здається, трохи заспокоюється.>\n\nЇх загін прийшов вночі і вкрав мій журнал! Я знав, що не варто довіряти цьому бездарному стаж...", ["en"] = "The Troll Cave", ["tasks"] = { ["Frostmane Troll Whelp"] = "морозогривий молодий троль", ["Frostmane Troll Whelp slain"] = "морозогривий молодий троль: убито" } },
    [183] = { [1] = "Мисливець на кнурів", [2] = "Немає нічого краще, ніж полювання на кнурів, еге ж?\n\nЩоправда, тут, в Морозній долині, їх наплодилось стільки, що весь інтерес зникає. Їх навіть заганяти не треба - вони злющі й самі кидаються на мисливця. Насправді нещодавно тут водилося стільки кнурів, що й полювати було небезпечно.\n\nКоротше кажучи, якщо ти допоможеш мені завалити кількох кнурів, я буду дуже вдячний.", [3] = "Талін Гострозір просить вас вбити 12 малих скельних кнурів.", [4] = "Як проходить полювання?", [5] = "Чудово! Тепер я можу повернутись до... неквапливого... полювання. Дякую, {ім'я}.", ["en"] = "The Boar Hunter", ["tasks"] = { ["Small Crag Boar"] = "малий скельний кнур", ["Small Crag Boar slain"] = "малий скельний кнур: убито" } },
    [184] = { [1] = "Документ Хмуроброва", [2] = "Це — договір, що дає право на розширення фермерських володінь у Західному краю. На ньому стоять підписи Теодора Хмуроброва та його дружини, Верни. На звороті документа квапливо видряпані слова:\n\n\"Ми натиснули на Хмуроброва й отримали від нього документ. Подумали, він придасться, якщо тобі захочеться підробити такий для власної ділянки.\n\nЗ Хмуробровами проблем не передбачається. Востаннє, коли я їх бачив, вони застрягли зі зламаним візком, залишаючи Західний край.\"\n\nВи думаєте, що Хмуроброви були б раді повернути їхній договір...", [3] = "Принесіть документ фермеру Хмуроброву.", [4] = "У тебе документ на мою ферму? Оце так хороша новина! Кілька днів тому його вкрали якісь мерзотники... Я думав, що втратив його назавжди!\n\nБудь ласка, віддай мені цей папір. Звичайно, ми зараз їдемо із Західного краю та повернемося не скоро, але настануть часи, коли він нам дуже знадобиться...", [5] = "Ми надзвичайно вдячні тобі, {ім'я}! Як я казав, зараз у цих краях пристойним людям не місце, але, може, часи зміняться, і тоді цей папір допоможе нам повернути свою землю.\n\nЯ не можу багато запропонувати, але візьми хоча б ось це...", ["en"] = "Furlbrow's Deed", ["tasks"] = { ["Furlbrow's Deed"] = "документ Хмуроброва", ["Furlbrow's Deed (Provided)"] = "документ Хмуроброва (видано)" } },
    [19] = { [1] = "Таріл'зун", [2] = "Відступники та вістові Чорнокаменю влаштовують засідки на дорозі між містом та фортецею Кам'яної Варти. Керує ними орк, на ім'я Таріл'зун — нам то він і потрібен. Принеси мені голову Таріл'зуна!", [3] = "Принесіть голову Таріл'зуна маршалу Маррісу в Багрянокряжжя.", [4] = "Орки Чорнокаменю все ще не дають нам спокою. Ти вже {стать:позбавив:позбавила} нас від Таріл'зуна?", [5] = "Таріл'зун був жорстоким і підступним орком. Молодець — я впевнений, що з ним було нелегко. Ось твоя винагорода, {ім'я:к}.", ["en"] = "Tharil'zun", ["tasks"] = { ["Tharil'zun's Head"] = "голова Таріл'зуна", ["Tharil'zun's Head (Provided)"] = "голова Таріл'зуна (видано)" } },
    [1941] = { [1] = "Мантія з манополотна", [5] = "Ось твоя мантія. Це одна з моїх найкращих робіт! Носи її з гордістю, а коли хтось запитає де ти її {стать:взяв:взяла}... порадь їм завітати в \"сукна Ларсона\"!", ["en"] = "Manaweave Robe" },
    [198] = { [1] = "Припаси для рядового Торсена", [2] = "Хмм. Так, у мене є одне завдання для тебе. Лейтенант Дорен та його побратими, на півночі, потребують регулярного постачання від нас.\n\nПрипаси ще не доставили, а оскільки атаки тролів продовжуються, мені потрібен хтось, хто це зробить. Табір Дорена знаходиться на північний захід від дороги, біля входу в Тернисту долину з боку Смерколісся. Віддай припаси рядовому Торсену. Якщо не знайдеш його в таборі, значить він патрулює на південь від нього. Торсен подбає про припаси.\n\nВрахуй, якщо не впораєшся, тобі доведеться відшкодувати мої витрати.", [3] = "Доставте різні гоблінські припаси рядовому Торсену.", [4] = "Так? Чого тобі треба? А, припаси від гоблінів. Дивно бачити, що їх доставляє {раса:н}, зазвичай вони відправляють одного зі своїх. Неважливо... ти ж не {стать:чіпав:чіпала} їх, правильно? Добре, добре... ми б не хотіли, щоб з нашими мінами щось сталося, о ні.", [5] = "Ці міни допоможуть нам захиститися від цього звіра — Курцена, та його людей. Дякую, що {стать:приніс:принесла} їх. Якщо тобі потрібна робота, думаю, я зможу знайти для тебе ще щось. До того ж тобі не доведеться мати справу з тими гоблінами. Як тобі?", ["en"] = "Supplies to Private Thorsen", ["tasks"] = { ["Miscellaneous Goblin Supplies"] = "різні гоблінські припаси", ["Miscellaneous Goblin Supplies (Provided)"] = "різні гоблінські припаси (видано)" } },
    [199] = { [1] = "Темна загроза", [2] = "Ви берете зразок порошку з дивним запахом.", [3] = "Поверніться до старшого інженера Греблера та покажіть йому знахідку.", [4] = "Ну що, {стать:знайшов:знайшла} щось, {ім'я}?", [5] = "Це тривожна знахідка, м'яко кажучи!", ["en"] = "A Dark Threat Looms", ["tasks"] = { ["Strange Smelling Powder"] = "порошок з дивним запахом", ["Strange Smelling Powder (Provided)"] = "порошок з дивним запахом (видано)" } },
    [20] = { [1] = "Загроза Чорнокаменю", [2] = "Орки з клану Чорнокаменю прикочували з Палаючого степу і захопили фортецю Кам'яної Варти на півночі. Звідти вони учиняють набіги по всій півночі та змушують жителів Приозер'я сидіти в місті, загнаних як худобу.\n\nПоможи Приозер'ю позбутися цієї загрози. Вбий цих орків й принеси мені десять їхніх зношених у бою сокир як доказ.\n\nІ хоча Чорнокамінь грозить нам з півночі, ми отримали звіти про ще більшу кількість у південно-східному Багрянокряжжі. Знайдеш когось там — знищ їх заразом.", [3] = "Принесіть 10 зношених у бою сокир маршалу Маррісу в Приозер'я.", [4] = "Ти {стать:повбивав:повбивала} орків, {ім'я:к}? Якщо так, то покажи мені...", [5] = "Тепер нам не треба так хвилюватися про орків, дякую.", ["en"] = "Blackrock Menace", ["tasks"] = { ["Battleworn Axe"] = "зношена сокира", ["Battleworn Axe (Provided)"] = "зношена сокира (видано)" } },
    [200] = { [1] = "Букмекер Герод", [2] = "Якщо Курцен знає таємницю Торсена, то серед нас є шпигун. Треба з'ясувати, звідки витікає інформація!\n\nЗв'язковим Торсена в таборі Курцена був букмекер Герод. Герод — офіцер з логістики Курцена і знає все про його табір. Якщо ти дістанеш нотатки або записи Герода, можливо, ми зможемо дізнатися, як викрили Торсена.\n\nКоли ми служили у військах Курцена, офіс букмекера був на верхньому поверсі єдиного двоповерхового будинку в таборі. Його записи, ймовірно, все ще там.", [3] = "Знайдіть записи букмекера Герода.", [5] = "Це нотатки та записи букмекера Герода.\n\nСеред них: перелік постачань табору, запити від полковника Курцена, а також різні листи.", ["en"] = "Bookie Herod" },
    [202] = { [1] = "Полковник Курцен", [2] = "Ти неодноразово {стать:доводив:доводила}, що ти {стать:кращий:краща} за самого Курцена, а твоя винахідливість не гірша ні на краплю. Ти можеш стати порятунком для нашого загону повстанців... якщо зможеш вистояти проти Курцена і перемогти!\n\nВін командує своїми людьми з Погребиці. Тобі потрібно піти в ту печеру, хоробро пробитися повз його підопічних і зустрітися з Курценом та його захисниками.\n\nПрощавай, {ім'я}. Моя надія і доля моїх людей з тобою.", [3] = "Вбийте 6 елітних бійців та 4 заступників Курцена і принесіть голову Курцена лейтенанту Дорену в табір Повстання.", [4] = "Чи можу я сподіватися, що Курцен і його захисники мертві, {ім'я}?", [5] = "Я не наважувався вірити повідомленням, але ти {стать:приніс:принесла} нам докази того, що... Курцен і його послідовники зазнали поразки. Ти {стать:врятував:врятувала} нас!\n\nЦі джунглі сповнені різних загроз, але розум жодної з них навіть не стояв поруч Курценом. Тепер, коли його більше немає, ми всі можемо видихнути з полегшенням.", ["en"] = "Colonel Kurzen", ["tasks"] = { ["Kurzen Elite"] = "елітний боєць Курцена", ["Kurzen Elite slain"] = "елітний боєць Курцена: убито", ["Kurzen Subchief"] = "заступник Курцена", ["Kurzen Subchief slain"] = "заступник Курцена: убито", ["Kurzen's Head"] = "голова Курцена", ["Kurzen's Head (Provided)"] = "голова Курцена (видано)" } },
    [203] = { [1] = "Друге повстання", [2] = "Ми програємо в битві з полковником Курценом. Він не тільки блискучий тактик, у нього також щонайменше в 10 разів більше військ! Щоб вижити, ми повинні використати проти нього його ж тактику.\n\nПроникни в його табір на сході та вбий його людей. Якнайбільше. А потім сховайся допоки не прийде підкріплення.", [3] = "Вбийте 15 лісових бійців Курцена.\n\nПоверніться до сержантки Йогви в табір Повстання.", [4] = "Сподіваюсь, що полювання пройшло успішно, {ім'я}. Ми довго не протримаємось без твоєї допомоги.", [5] = "Гарна робота. Втрата цих бійців дещо послабить тиск на наш табір.\n\nТепер, коли ти {стать:відчув:відчула}, з якими силами ми боремось, ти все ще хочеш приєднатись до нас?", ["en"] = "The Second Rebellion", ["tasks"] = { ["Kurzen Jungle Fighter"] = "лісовий боєць Курцена", ["Kurzen Jungle Fighter slain"] = "лісовий боєць Курцена: убито" } },
    [2038] = { [1] = "Зникле спорядження Бінґлса", [2] = "Мало того, що я розбився в Лох-Модані, на мене ще й напали троги з найближчого острову і вкрали мої інструменти разом з особливою вибухівкою - болтозривом Підривайченка! Без гірокоптера та вибухівки нашому руху не обійтись!\n\nПоверни мої інструменти та болтозрив, {ім'я}. За Гномреґан!", [3] = "Знайдіть і поверніть Бінґлсу його спорядження:\n\nГайковий ключ Бінґлса, викрутку Бінґлса, молоток Бінґлса та болтозрив Бінґлса.", [4] = "{ім'я}! Де мої речі?!", [5] = "Ти гарно {стать:послужив:послужила} цілям руху, {ім'я}. Троги та лепрогноми, що заполонили Гномреґан, скоро відчують на собі міць повітряної атаки гномів!", ["en"] = "Bingles' Missing Supplies", ["tasks"] = { ["Bingles' Blastencapper"] = "болтозрив Бінґлса", ["Bingles' Blastencapper (Provided)"] = "болтозрив Бінґлса (видано)", ["Bingles' Hammer"] = "молоток Бінґлса", ["Bingles' Hammer (Provided)"] = "молоток Бінґлса (видано)", ["Bingles' Screwdriver"] = "викрутка Бінґлса", ["Bingles' Screwdriver (Provided)"] = "викрутка Бінґлса (видано)", ["Bingles' Wrench"] = "гайковий ключ Бінґлса", ["Bingles' Wrench (Provided)"] = "гайковий ключ Бінґлса (видано)" } },
    [2039] = { [1] = "Знайти Бінґлса", [2] = "Ми втратили зв'язок з Бінґлсом! Його було відправлено в розвідувальний політ над Гномреґаном і він не виходить на зв'язок вже більше ніж тиждень. Я знаю лише що він пішов в розвідку і підірвавсь.\n\nВостаннє його бачили, коли він пролітав над озером Лох. Можливо ти зможеш з'ясувати, що з ним сталось, {ім'я}.", [3] = "Знайдіть Бінґлса Підривайченка в Лох-Модані.", [5] = "Отже, Ґноарн сумнівається в моїх здібностях розвідника? Цікаво, чому це...\n\nНе бери в голову, мені потрібна твоя допомога! Ні! Нашому руху потрібна твоя допомога!", ["en"] = "Find Bingles" },
    [204] = { [1] = "Ліки з джунглів", [2] = "Щоб мати хоч якийсь шанс проти Курцена, нам необхідно нейтралізувати його цілителів. Він зібрав навколо себе велику кількість медиків, які зцілюють його війська за допомогою зілля джунглів і труять наших бійців екстрактами отруйної папороті.\n\nНам потрібні ці зілля, щоб вилікувати наших людей, а також потрібен зразок цього екстракту, щоб ми змогли виготовити наші власні зілля. Відшукай і те, і інше в таборі Курцена — зілля можна знайти у медиків, а екстракти, ймовірно, зберігаються в ящиках з припасами.", [3] = "Принесіть 7 порцій зілля з джунглів та 1 екстракт отруйної папороті сержантці Йогві в табір Повстання.", [4] = "Я чекаю на зілля та екстракт, {ім'я}.", [5] = "Молодець, {ім'я}. Ці зілля допоможуть більшості з нас вижити та зберегти бойову форму. А екстракти дадуть можливість створити власні ліки.", ["en"] = "Bad Medicine", ["tasks"] = { ["Jungle Remedy"] = "зілля з джунглів", ["Jungle Remedy (Provided)"] = "зілля з джунглів (видано)", ["Venom Fern Extract"] = "екстракт отруйної папороті", ["Venom Fern Extract (Provided)"] = "екстракт отруйної папороті (видано)" } },
    [2040] = { [1] = "Підземний штурм", [2] = "Гномреґан захопили ці кляті троги! Ситуація дуже важка, але ти можеш допомогти нам, {ім'я}.\n\nГлибоко в Мертвих копальнях є гоблінський подрібнювач. Знайди його і принеси мені його джерело живлення. З його допомогою ми матимемо достатньо потужності для наших гіробурорийок, щоб пробитись через скелясті підземелля до Гномреґану і почати штурм!", [3] = "Добудьте гномський шпрековерт в Мертвих копальнях і принесіть його Шоні Мовшунці в Штормовій.", [4] = "Ти {стать:знайшов:знайшла} гномський шпрековерт, {ім'я}?", [5] = "Чудово, {ім'я}. Завдяки тобі ми ще на крок ближче до звільнення Гномреґану!", ["en"] = "Underground Assault", ["tasks"] = { ["Gnoam Sprecklesprocket"] = "гномський шпрековерт", ["Gnoam Sprecklesprocket (Provided)"] = "гномський шпрековерт (видано)" } },
    [205] = { [1] = "Чаклунство тролів", [2] = "Поки я вивчатиму легенди, що ти {стать:приніс:принесла}, збери для мене знаряддя злої магії тролів. Проникни на територію тролів племені Черепотрощителів, другого племені на далекому півдні та добудь фетиші у їхніх знахарів та містиків.", [3] = "Принесіть 4 фетиші Черепотрощителів брату Німіцу в табір Повстання.", [4] = "Ти {стать:дістав:дістала} фетиші, {ім'я}? Можливо, саме в них міститься секрет того, що сталось з Курценом... Я мушу це дізнатись!", [5] = "Дякую. Я вивчу ці фетиші та дізнаюсь, чи містять вони таємницю зла Курцена.", ["en"] = "Troll Witchery", ["tasks"] = { ["Skullsplitter Fetish"] = "фетиш Черепотрощителів", ["Skullsplitter Fetish (Provided)"] = "фетиш Черепотрощителів (видано)" } },
    [207] = { [1] = "Таємниця Курцена", [2] = "Полковник Курцен колись був великою, благородною людиною — я повинен з'ясувати, що змусило його звернути з праведного шляху! Можливо, він перебуває під впливом магії тролів. Щоб підтвердити цю теорію, мені потрібно вивчити кілька їхніх легенд.\n\nУ руїнах Тернистої долини заховано 4 скрижалі. Я маю побачити, що написано на них! Перепиши їхні легенди й принеси їх мені.\n\nПерша скрижаль знаходиться в руїнах Бал'лал, друга — на Підступному рифі, а третя і четверта — в руїнах Зул'Кунда.", [3] = "Знайдіть 4 скрижалі та принесіть легенди брату Німіцу.", [4] = "{ім'я}! Ти {стать:приніс:принесла} легенди тролів? Я маю знати їхні таємниці!", [5] = "Дякую, {ім'я}. Я вивчу ці легенди та дізнаюся, чи є якийсь зв'язок між тролями й злом, яке вселилося в полковника Курцена.", ["en"] = "Kurzen's Mystery", ["tasks"] = { ["The First Troll Legend"] = "перша легенда тролів", ["The First Troll Legend (Provided)"] = "перша легенда тролів (видано)", ["The Fourth Troll Legend"] = "четверта легенда тролів", ["The Fourth Troll Legend (Provided)"] = "четверта легенда тролів (видано)", ["The Second Troll Legend"] = "друга легенда тролів", ["The Second Troll Legend (Provided)"] = "друга легенда тролів (видано)", ["The Third Troll Legend"] = "третя легенда тролів", ["The Third Troll Legend (Provided)"] = "третя легенда тролів (видано)" } },
    [21] = { [1] = "Сутичка в Ехокряжі", [2] = "Твої попередні розслідування стали доказом того, що копальня Ехокряжу потребує вичищення. Повертайся до шахти та допоможи зачистити її від кобольдів.\n\nНе витрачай даремно часу, {ім'я:к}. Чим довше ми ігноруватимемо кобольдів в копальні, тим міцніше вони закріпляться в Північнокраї.", [3] = "Убийте 12 кобольдів-різноробів, після чого поверніться до маршала Макбрайда в Північнокрайове абатство.", [4] = "Я знаю, це кривава робота, {ім'я:к}, але також життєво необхідна для безпеки Північнокраю. Ти {стать:готовий:готова} звітувати?", [5] = "І знову ти {стать:заслужив:заслужила} мою повагу та вдячність армії Штормовію. Можливо, в шахті ще залишаються кобольди, але я направлятиму й інших проти них. А для тебе у нас є інші завдання.", ["en"] = "Skirmish at Echo Ridge", ["tasks"] = { ["Kobold Laborer"] = "кобольд-різнороб", ["Kobold Laborer slain"] = "кобольд-різнороб: убито" } },
    [210] = { [1] = "Горщик Кронжека", [2] = "Здебільшого я беру відповідальність за приготування їжі в таборі. І раніше це займало багато часу, поки я не купив механічний горщик у гобліна-торговця в Грабіжній Бухті. Цей горщик — просто диво! Він зберіг мені купу часу, поки не зламався!\n\nМожеш віднести горщик до гобліна, щоб він його полагодив? Його звуть Кронжек.", [3] = "Принесіть зламаний горщик Кронжека до гобліна Кронжека.", [4] = "Привіт! Ти мені щось {стать:приніс:принесла}?", [5] = "О, це ж горщик Кронжека! Геніальна річ, але час від часу може ламатися пружина або вилітати шестерня. Дай подивлюся, що з ним не так...\n\nАга! Паровий зарядник проржавів, прокладка тріснула, а на фобуляторі стерлись зубці. Дивно, як в такому стані вдавалося варити хоча б ріпу!\n\nЧи можу я його полагодити? Звісно, що я можу його полагодити!\n\nАле за це треба заплатити. Звісно, будь-яка робота має свою ціну...", ["en"] = "Krazek's Cookery", ["tasks"] = { ["Krazek's Crock Pot"] = "зламаний горщик Кронжека", ["Krazek's Crock Pot (Provided)"] = "зламаний горщик Кронжека (видано)" } },
    [211] = { [1] = "Шкода, Андорал", [2] = "Шкода, але настав час атакувати Андорал та вигнати звідти ліча, який контролює місто.\n\nВ самому серці руїн міста влаштувався ліч — Араж-Закликач. Його охороняють найкращі бійці Скари, що оточують решту центру міста. Тобі знадобиться велика кількість союзників, щоб мати хоч якийсь шанс протистояти йому.\n\nЗнищ Аража, {ім'я}, та принеси мені уламок його філактерії як доказ!", [3] = "Принесіть уламок філактерії Аража командиру Ашламу Мужньобою в табір Студовій, що в Західних Зачумлених землях.", [4] = "Тобі дали завдання, {ім'я}. Ти {стать:приніс:принесла} уламок філактерії ліча як доказ того, що ти {стать:виконав:виконала} його?", [5] = "Ти {стать:зробив:зробила} це! Араж... ліч нарешті переможений!\n\nСьогодні ти {стать:зробив:зробила} величезну послугу Альянсу, {ім'я}. Твої сміливість та наполегливість є свідченням твого справжнього героїзму. Прошу, прийми цей знак, щоб всі знали, що завдяки тобі Альянс здобув велику перемогу!", ["en"] = "Alas, Andorhal", ["tasks"] = { ["Araj's Phylactery Shard"] = "уламок філактерії Аража", ["Araj's Phylactery Shard (Provided)"] = "уламок філактерії Аража (видано)" } },
    [214] = { [1] = "Червоні шовкові бандани", [2] = "Всі знають, що червоні бандани є символом Банди Непокірних. Та ми дізнались, що матеріал, з якого зроблена бандана, означає ранг члена банди.\n\nОтож, я хочу, щоб ти {стать:знищив:знищила} якомога більше бандитів високого рангу. Їх точно можна знайти в сховищі Едвіна Ван-Кліфа. Коли справишся — принеси мені 10 червоних шовкових бандан як доказ і я винагороджу тебе. Нехай тобі щастить, {ім'я}.", [3] = "Розвідниця Ріелла зі сторожового пагорба просить вас принести їй 10 червоних шовкових бандан.", [4] = "Ну що, {стать:позбавив:позбавила} наші землі від Банди Непокірних? Якщо так — покажи 10 червоних шовкових бандан.", [5] = "Чудово, {ім'я}! Від імені народного ополчення дякую тобі за твої зусилля. З допомогою таких сміливців, як ти, ми зовсім скоро повернемо ці землі їх жителям.", ["en"] = "Red Silk Bandanas", ["tasks"] = { ["Red Silk Bandana"] = "червона шовкова бандана", ["Red Silk Bandana (Provided)"] = "червона шовкова бандана (видано)" } },
    [215] = { [1] = "Таємниці джунглів", [2] = "Дякую, що {стать:врятував:врятувала} мене, {ім'я}. Я знаю, як це виглядає, але дозволь мені пояснити.\n\nЛейтенант Дорен доручив мені завербуватися до людей Курцена, щоб я міг шпигувати за ними та передавати повстанцям вкрай необхідні розвідувальні дані. Ти {стать:бачив:бачила}, як виглядала моя спроба проникнути в табір Курцена. Я допустив помилку, і ще раз дякую тобі, що {стать:врятував:врятувала} мене.\n\nЦе була надсекретна місія, тому тобі не можна нікому розповідати. Але якщо ти поговориш з Дореном, він тобі все пояснить.", [3] = "Поговоріть з лейтенантом Дореном в таборі Повстання.", [5] = "Так, те, що тобі сказав Торсен — правда. Тільки будь {стать:обережним:обережною} з цією інформацією. Колись ми, повстанці, були палко віддані полковнику Курцену. Але, коли Курцен перейшов на сторону зла, наша пристрасть перетворилася на лють. Якби дійшли чутки, що рядовий Торсен нещодавно мав справу з людьми Курцена, то однієї ночі його б знайшли з перерізаним горлом.\n\nНаскільки я знаю, лише сержантці Йогві, Торсену і мені були відомі деталі його місії. Але є ще хтось. Зрадник.", ["en"] = "Jungle Secrets" },
    [2158] = { [1] = "Відпочинок і спокій", [2] = "Кожен мандрівник має відпочивати, коли виснажиться. І немає кращого місця для відпочинку та спокою, ніж таверна «Гордість лева»!\n\nМій найкращий друг, корчмар Фарлі, там за головного. Якщо скажеш йому, що ти від мене, то отримаєш особливу знижку на їжу та напої.\n\n«Гордість лева» знайти не важко, рухайся на південь по дорозі — не проґавиш!", [3] = "Поспілкуйтеся з корчмарем Фарлі в таверні «Гордість лева».", [5] = "Відпочинок і спокій для втомлених і зморених — ось наш девіз! Будь ласка, влаштовуйся біля вогню зручніше і гарненько відпочинь тілом і душею.\n\nЧи бажаєш скуштувати щось із наших вишуканих напоїв та їжі?", ["en"] = "Rest and Relaxation" },
    [2159] = { [1] = "Доставка в Доланаар", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Допоможеш мені? В мене є пакет трав, який я повинен доставити до Доланаару. Але я все ще потрібен друїдам Тінистої долини і не можу їх залишити.\n\nЧи можеш доставити цей пакет замість мене? Його потрібно передати в руки Келдаміру в корчму в Доланаарі. Ти знайдеш місто вздовж дороги, на півдні.", [3] = "Передайте посилку в Доланаар корчмарю Келдаміру.", [4] = "Чим я можу допомогти вам, {стать:юначе:юначко}? Ви прийшли відпочити? Чи вам потрібен Камінь Вогнища?", [5] = "А, так. Доставка трав з Тінистої долини. Шкода, що Портенній не зміг принести їх сам, нам потрібно багато чого обговорити віч-на-віч. Але я дуже радий нарешті отримати цю посилку, тож дякую, що ви прийшли.\n\nПоки ви тут, прошу, відпочиньте. Герої повинні час від часу відновлювати свої сили та бойовий дух, тож вам не завадять відпочинок і втіха за можливості. Нехтування спокоєм тіла та розуму — вірний шлях до невдач.\n\nТож... відпочивайте.", ["en"] = "Dolanaar Delivery", ["tasks"] = { ["Dolanaar Delivery"] = "посилка в Доланаар", ["Dolanaar Delivery (Provided)"] = "посилка в Доланаар (видано)" } },
    [2160] = { [1] = "Припаси для Таннока", [2] = "Егей! Ти виглядаєш як {стать:впевнений шукач:впевнена шукачка} пригод. Якщо ти плануєш прорватись через тунель, чи не {стать:міг би:могла б} ти віднести цей пакунок до таверни в Хараносі?\n\nТи ж {стать:збирався:збиралась} зазирнути туди? Після всього, що тебе чекає в дорозі, ти точно захочеш відпочити і набратися сил.\n\nХай там як, віднеси це Танноку Кригомолоту, помічнику корчмаря. Сам я не пройду, а на патруль горянинів чекати ще довго.", [3] = "Доставте ящик припасів для корчми Танноку Кригомолоту в Харанос.", [4] = "Вітаю! Заходь, сідай біля вогнища, зігрійся кухлем відмінного елю.", [5] = "О, нарешті, припаси від Ручика! Я вже почав хвилюватись - з тих пір, як тунель захопили троги, ми не мали жодної звістки з Ковмару.\n\nЯ дуже вдячний тобі, {ім'я}. Ти заходь, будь як вдома. Ти певно {стать:виснажений:виснажена} після такої подорожі.", ["en"] = "Supplies to Tannok", ["tasks"] = { ["Crate of Inn Supplies"] = "ящик припасів для корчми", ["Crate of Inn Supplies (Provided)"] = "ящик припасів для корчми (видано)", ["Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos."] = "Доставте ящик припасів для корчми Танноку Кригомолоту в Харанос." } },
    [217] = { [1] = "На захист королівських земель", [2] = "{ім'я}, наші розвідники виявили ватажка вторгнення трогів. Схоже, що ці мерзотники підпорядковуються вождю на ім'я Ґромаґ. Однак, його пильно охороняють. Двоє його найкращих вартових, Скрегатель та Булдига, не відходять від нього ні на мить.\n\nЯкщо {стать:впевнений:впевнена} у своїх силах, {ім'я}, можеш очолити операцію з ліквідації Ґромаґа та двох його посіпак. Якщо тобі вдасться вбити їх вождя, можливо, ми зможемо загнати трогів назад в землю.", [3] = "Вбийте лідера трогів, Ґромаґа, та двох його охоронців, Скрегателя та Булдигу, після чого поверніться до капітана Руґельфуза в південну вартову вежу.", [4] = "Ґромаґ та його охоронці, Скрегатель та Булдига, все ще живі. Твоє завдання не буде виконане, поки всі троє ну будуть вбиті. Всі дворфи розраховують на тебе, {ім'я}.", [5] = "Просто неймовірно, {ім'я}! Ти {стать:повернув:повернула} надію до Лох-Модану. Коли Ґромаґ мертвий, у нас з'явилось більше шансів вигнати трогів з наших земель.", ["en"] = "In Defense of the King's Lands", ["tasks"] = { ["Brawler"] = "Булдига", ["Brawler slain"] = "Булдига: убито", ["Gnasher"] = "Скрегатель", ["Gnasher slain"] = "Скрегатель: убито", ["Grawmug"] = "Ґромаґ", ["Grawmug slain"] = "Ґромаґ: убито" } },
    [218] = { [1] = "Викрадений щоденник", [2] = "Мій щоденник! Вони забрали його у свою печеру. Здоровенний бугай, розмальований з голови до ніг, тримав його. Це все, що я зміг розгледіти.\n\nТи ж вже {стать:мав:мала} справу з тролями, тож може ти зможеш повернути мій щоденник?", [3] = "Вбийте Ґрік'ніра Холодного та поверніть Ґреліну Білобороду його щоденник.", [4] = "О, {ім'я}! Як успіхи?", [5] = "Чудово, {ім'я}! Дуже дякую що повернув мої записи. Що ж, схоже що ситуація з тролями в Морозній долині під контролем, тож у нас більше немає причин для хвилювань.\n\nЩойно я завершу свій звіт, мені знадобиться кур'єр, який доставить їх моєму брату Сеніру.", ["en"] = "The Stolen Journal", ["tasks"] = { ["Grelin Whitebeard's Journal"] = "щоденник Ґреліна Білоборода", ["Grelin Whitebeard's Journal (Provided)"] = "щоденник Ґреліна Білоборода (видано)" } },
    [219] = { [1] = "Зниклий безвісти", [2] = "Нарешті, союзники Альянсу!\n\nДопоможи... будь ласка...\n\nОстаннє, що я пам'ятаю — як ці мерзенні орки розгромили наш полк. Більшість людей загинули. Мене вдарили по голові, і в очах потемніло. А тепер я ув'язнений у цій печері. Допоможи мені, я тяжко поранений.\n\nМені знадобиться допомога, щоб дістатися міста... будь ласка... ти моя остання надія...", [3] = "Допоможіть капралу Кішану повернутись до Багрянокряжжя.", [4] = "Так?", [5] = "Ти добре {стать:послужив:послужила} Королівству, {клас:к}. Дякую, що {стать:допоміг:допомогла} капралу Кішану втекти від орків Чорнокаменю. Твоя хоробрість заслуговує на гідну винагороду.", ["en"] = "Missing In Action", ["tasks"] = { ["Escort Corporal Keeshan back to Redridge"] = "Супроводіть капрала Кішана до Багрянокряжжя" } },
    [2198] = { [1] = "Пошкоджене намисто", [2] = "Ви знайшли потьмяніле намисто. Хоча потьмяніння не змогло спотворити майстерну, навіть трохи магічну роботу майстра. Намисто пошкоджене — схоже, що в ньому не вистачає трьох самоцвітів. На його нижньому боці ледь видніється печатка Залізогарта. Під печаткою викарбувано три маленькі ініціали: \"ТдК\".\n\nЯкщо від намиста й можна отримати користь, певно, варто дізнатися більше про його походження. Можливо, печатка та ініціали — непоганий початок...", [3] = "Знайдіть творця розбитого намиста, щоб дізнатися чого воно варте.", [4] = "Ти {стать:натрапив:натрапила} не того гнома, {стать:приятелю:приятелько}! Мене там і близько не було! Ти нічого не доведеш!\n\nСекундочку... Ти хто? Що за... де ти {стать:знайшов:знайшла} це намисто?", [5] = "Так. Я — той самий ювелір, який зробив це намисто. Я ще я не роздаю інформацію за просто так. Інформація ніколи не буває безплатною, {стать:друже:подруго}. Якщо ти хочеш моєї допомоги — спочатку доведеться допомогти мені.", ["en"] = "The Shattered Necklace", ["tasks"] = { ["Shattered Necklace"] = "пошкоджене намисто", ["Shattered Necklace (Provided)"] = "пошкоджене намисто (видано)" } },
    [2199] = { [1] = "Плата за знання", [2] = "Я прославлений в Залізогарті ювелір! Ну, принаймні, був прославленим... Я потрапив у скрутне становище через те, що мене підставив мій конкурент! Погана репутація в нашому ремеслі означає фінансову катастрофу. І тепер з моїм добрим, але заплямованим ім'ям моя робота не варта й мідного п'ятака.\n\nЯ хочу, щоб ти {стать:приніс:принесла} мені п'ять срібних злитків, щоб я зміг завершити замовлення — перше за цілу вічність.\n\nДістань мені ці п'ять срібних злитків, і я все розповім тобі про намисто.", [3] = "Принесіть п'ять злитків срібла Талвашу дель Кісселю в Залізогарт.", [4] = "Ти {стать:дістав:дістала} п'ять срібних злитків, про які я просив? Я поділюся з тобою своєю сумною історією про це намисто... але тільки після того, як отримаю ці злитки! Будь ласка, поможи гному.", [5] = "Ти {стать:гарний:гарна} {клас}, і байдуже, що там казали інші... Жартую, жартую! Серйозно, дякую тобі величезне.\n\nНамисто, яке ти {стать:приніс:принесла} — одне з моїх найкращих творінь, але в ньому не вистачає трьох камінців, які допомагають зв'язати з ним магічну силу. Колись я зробив його для одного паладина. Він за особистим спонуканням вирушив у похід, щоб очистити \"злу нечисть\" на розкопках у Безплідних краях, у місці під назвою Ульдаман.\n\nЩо ж... той паладин загинув в Ульдамані, і це стало початком моїх нещасть.", ["en"] = "Lore for a Price", ["tasks"] = { ["Silver Bar"] = "злиток срібла", ["Silver Bar (Provided)"] = "злиток срібла (видано)" } },
    [22] = { [1] = "Пиріг з печінки іклоштрика", [2] = "Цибуля очищена. Часник роздавлений. Розмарин подрібнений. Основа випечена. Кріп нарізаний. Підливка закипає. Тепер усе, що мені ще потрібно для мого відомого м'ясного пирога — це 8 печінок іклоштрика!", [3] = "Принесіть Сальмі Салден 8 печінок іклоштрика, щоб вона могла спекти пиріг.", [4] = "Усе, що мені потрібно для мого знаменитого м'ясного пирога — це 8 печінок іклоштрика!", [5] = "Ці шматки — просто ідеальні, {ім'я:к}! Дякую тобі дуже! Ми з фермером Салденом влаштуємо сьогодні справжній бенкет. А ця дрібничка для тебе — за важку працю. Ти ж не {стать:думав:думала}, що {стать:такий:така} {клас:н}, як ти, залишиться без частування, га?", ["en"] = "Goretusk Liver Pie", ["tasks"] = { ["Goretusk Liver"] = "печінка іклоштрика", ["Goretusk Liver (Provided)"] = "печінка іклоштрика (видано)" } },
    [2201] = { [1] = "Пошуки самоцвітів", [2] = "Щоденник паладина надав лиш зачіпки щодо знаходження самоцвітів з намиста. Якщо вірити записам паладина, вам доведеться мати справу з дворфами Тінегарту та трогами, які змагаються за контроль над розкопками.\n\nОзброївшись цими знаннями, починаються серйозні пошуки самоцвітів. Коли всі самоцвіти будуть знайдені, слід повідомити про це Талваша в Залізогарті за допомогою фіалу провидіння.", [3] = "Знайдіть рубін, сапфір і топаз, які розкидані по всьому Ульдаману. Отримавши їх, зв'яжіться з Талвашем дель Кісселєм, використовуючи фіал провидіння, який він дав вам раніше.\n\nЗі щоденника ви знаєте, що...\n* Рубін схований на забарикадованій території Тінегарту.\n* Топаз захований в урні в одному з районів, зайнятих трогами, біля дворфів Альянсу.\n* Сапфір привласнив Грімлок, ватажок трогів.", [4] = "Образ Талваша з'являється на поверхні води в чаші провидіння.\n\n\"Ого, ти ще {стать:живий:жива}! Тобі вдалося знайти самоцвіти? Ти єдина надія на порятунок моєї репутації. Будь ласка, скажи мені, що ти не {стать:витратив:витратила} заряд фіала лише для того, щоб потеревенити; ці речі недешеві, а я і так вельми обмежений у коштах.\"", [5] = "Так, це ті самі три самоцвіти. Чудова робота! Але, на жаль, це ще не все.\n\nНі, я не намагаюся тебе надурити, {стать:дурненький:дурненька} {клас:к}. Справа в особливостях виготовлення чарівних прикрас — прикрас рівня Талваша дель Кісселя! Для створення таких речей потрібне потужне джерело енергії. А в цьому намисті ніякої сили вже не залишилося.", ["en"] = "Find the Gems", ["tasks"] = { ["Shattered Necklace Ruby"] = "рубін пошкодженого намиста", ["Shattered Necklace Ruby (Provided)"] = "рубін пошкодженого намиста (видано)", ["Shattered Necklace Sapphire"] = "сапфір пошкодженого намиста", ["Shattered Necklace Sapphire (Provided)"] = "сапфір пошкодженого намиста (видано)", ["Shattered Necklace Topaz"] = "топаз пошкодженого намиста", ["Shattered Necklace Topaz (Provided)"] = "топаз пошкодженого намиста (видано)" } },
    [2204] = { [1] = "Відновлення намиста", [2] = "Тобі знадобиться трохи магічної сили для намиста, і Ульдаман, мабуть, найкраще місце, щоб її роздобути. Гадаю, там бігає безліч магічних творінь, так? Що ж, знайди найбільше, найстрашніше творіння і захопи його джерело живлення! Я впевнений, що зможу помістити його в намисто.\n\nБез цього джерела сили полагодити намисто буде неможливо. Повертайся до мене в Залізогарт, коли знайдеш щось підхоже, і ми швидко все полагодимо!", [3] = "Добудьте джерело енергії з найпотужнішого творіння Ульдамана і доставте його Талвашу дель Кісселю в Залізогарт.", [4] = "Ти навіть не {стать:зупинявся:зупинялась}, щоб привести себе до ладу після Ульдамана, чи не так? Ти просто {стать:прийшов:прийшла} сюди, попри всі ці запахи підземелля. Будемо сподіватися, що це все не даремно.\n\nУ тебе є джерело сили для намиста?", [5] = "Чудово! Я радий бачити і тебе, і це джерело сили цілими й неушкодженими. Тепер, коли самоцвіти знову в намисті, мені знадобиться деякий час, щоб помістити в нього джерело сили. Щойно я це зроблю, намисто стане твоїм!\n\nХвилюєшся, чи не так? Вже тремтиш від нетерпіння? Куди ж я подів зосереджувач магії...", ["en"] = "Restoring the Necklace", ["tasks"] = { ["Shattered Necklace Power Source"] = "джерело сили пошкодженого намиста", ["Shattered Necklace Power Source (Provided)"] = "джерело сили пошкодженого намиста (видано)" } },
    [2206] = { [1] = "Урвати та схопити", [2] = "Наша розвідка звітує про активність Непокірних на південь від Злотохрестя. Звіти вказують на те, що вони захопили заставу Джерода і використовують її для переправлення великих партій контрабанди з Багрянокряжжя до Західного краю.\n\nМені потрібно, щоб ти {стать:проник:проникла} в доки та {стать:дістав:дістала} розклад постачань, {ім'я:к}. Скоріш за все, ти знайдеш його в кишенях начальника доку.\n\n...і, {ім'я:к}, якщо тебе викриють — ШУР заперечуватиме будь-який зв'язок з тобою.", [3] = "Знайдіть начальника доку Непокірних та принесіть розклад постачань майстру Матіасу Гичу.", [4] = "З кожною хвилиною, що ти вештаєшся в казармах, твоє життя стає коротшим на 60 секунд, {клас:к}.", [5] = "Я здивований...Здивований що Керін нарешті знайшла рекрута, що дійсно може мати задатки {стать:належного:належної} {клас:р}. Візьми цей клинок, {ім'я}. Настане день, коли ШУР знову покличе тебе на допомогу. Відточуй свої навички, тримай очі відкритими, а лезо — гострим.\n\nТи не помітиш нас, але відчуєш, коли ми будемо поруч...", ["en"] = "Snatch and Grab", ["tasks"] = { ["Defias Shipping Schedule"] = "розклад постачань Непокірних", ["Defias Shipping Schedule (Provided)"] = "розклад постачань Непокірних (видано)" } },
    [221] = { [1] = "Воргени в лісі", [2] = "Можливо, ти {стать:помітив:помітила}, що в лісі разом з тіньовими ткачами бродять дещо більші воргени? Наскільки ми можемо судити, ці темні вісники складають більшу частину зграї воргенів.\n\nПід час розвідки я також помітив, що вони зайняли Гниючий сад на південний захід від міста. Ці воргени трохи сильніші за тих, з якими ти вже {стать:бився:билася}.\n\nБудь насторожі.", [3] = "Убийте 12 темних вісників Ночегибелі для Калора з Темнодолу.", [4] = "Так швидко {стать:повернувся:повернулася}, {ім'я}? Сподіваюся, ти не збираєшся здаватись.", [5] = "Ти добре {стать:впорався:впоралася} з темними вісниками, {ім'я}. Але здається, що їх чисельність безмежна. Кожного разу, коли ми здобуваємо перемогу, з'являються нові, щоб поповнити їхні ряди.\n\nЯка зла сила приваблює їх сюди? Чому вони прийшли мучити наш нещасний світ...\n\nЯ покладаю надію на майстра Карвіна. Не сумніваюся, він розбереться з цією проблемою.", ["en"] = "Worgen in the Woods", ["tasks"] = { ["Nightbane Dark Runner"] = "темний вісник Ночегибелі", ["Nightbane Dark Runner slain"] = "темний вісник Ночегибелі: убито" } },
    [2218] = { [1] = "Шлях до порятунку", [2] = "Ще одна загублена душа, яка шукає настанови, ге? Гадаю, ти хочеш знайти мету — своє призначення. бачив це тисячу разів, ще {стать:один герой:одна героїня}, що шукає роботу.\n\nДобре, сьогодні твій щасливий день, {стать:друже:подруго}. Гоґрал знайшов ліки від твоєї недуги.\n\nОсь що тобі потрібно зробити: йди до Залізогарту та доберися до Закинутої Печери. Як прибудеш — знайди гільдію злодіїв та поговори з Гульфданом Чорнобородим. Він покаже твій шлях до порятунку.", [3] = "Поговоріть з Гульфданом Чорнобородим в Залізогарті.", [5] = "Ти думаєш, що ти {стать:справжній мерзотник:справжня мерзотниця}? {стать:Який:Яка} буде {стать:обраним:обраною} Чорнобородим, щоб стати офіцером Прихованого Кола?\n\nТільки справжній пройдисвіт так високо себе цінуватиме!\n\nСаме таких як ти ми й шукаємо! Ласкаво просимо, {ім'я}!", ["en"] = "Road to Salvation" },
    [222] = { [1] = "Воргени в лісі", [2] = "Твої попередні досягнення переконали мене, що ти {стать:готовий:готова} взятися за найнебезпечніших воргенів, що заселили ліси.\n\nЗ усіх воргенів, що знайшли собі тут новий дім, злобні ікла та плюгавці — найнебезпечніші. Вони живуть поряд із печерами та в шахті на півдні.\n\nТи побачиш здалеку сяйво їх вогнищ...", [3] = "Убийте 8 злобних ікл Ночегибелі та 8 плюгавців Ночегибелі для Калора з Темнодолу.", [4] = "Страшні звірі, чи не так? Але не бійся, {ім'я}, ті, хто стоїть за Світло, ніколи не будуть переможеними!", [5] = "{ім'я}, щиро кажучи, я не вірив, що ти зможеш зайти так далеко, але ти, безумовно, {клас}, з {стать:яким:якою} треба рахуватися. Насправді якщо ти бажаєш офіційно приєднатися до боротьби майстра Карвіна, я з радістю напишу для тебе рекомендаційний лист.", ["en"] = "Worgen in the Woods", ["tasks"] = { ["Nightbane Tainted One"] = "плюгавець Ночегибелі", ["Nightbane Tainted One slain"] = "плюгавець Ночегибелі: убито", ["Nightbane Vile Fang"] = "злобне ікло Ночегибелі", ["Nightbane Vile Fang slain"] = "злобне ікло Ночегибелі: убито" } },
    [223] = { [1] = "Воргени в лісі", [2] = "Тримай, {ім'я}. Віднеси це повідомлення майстру Карвіну.\n\n<Він швидко дістає шматок бляклого пергаменту і передає його вам.>\n\nЩе кілька таких, як ти, і ми перевершимо Нічну Варту! Можливо, тоді ми завершимо те завдання, яке зараз виконуємо з великим зусиллям.", [3] = "Передайте записку Калора Джонатану Карвіну.", [4] = "Так, що тобі потрібно? Швидше, у мене багато невідкладних справ.", [5] = "Вибач за мою холодну зустріч, {ім'я}, але, як ти розумієш, я надзвичайно зайнята людина. Я бачу, що ти {стать:вразив:вразила} Калора — а це, запевняю тебе, не маленьке досягнення — і що він дав свою рекомендацію.\n\nНавколо повно ненадійних осіб, {ім'я}, а нам потрібна допомога тих, на кого можна покластися. Ми боремося проти демонів, невмерлих та тих, хто надає їм підтримку. Не втрачай пильності, обережності та не довіряй нікому, хто не хоче допомагати нашій справі.\n\nСлава Світлу.", ["en"] = "Worgen in the Woods", ["tasks"] = { ["Calor's Note"] = "записка Калора", ["Calor's Note (Provided)"] = "записка Калора (видано)" } },
    [224] = { [1] = "На захист королівських земель", [2] = "Ми маємо захистити озеро Лох, {ім'я}! Поки королівські солдати проливають кров на далеких полях бою, наші рідні землі в небезпеці. Троги лізуть з кожної щілини! Нашестя трогів несе велику загрозу Залізогарту. Ми повинні знищити цих огидних мутантів.\n\nНам потрібно, щоб ти, {стать:відважний шукачу:відважна шукачко} пригод, {стать:наважився:наважилась} піти й усунути загрозу трогів. Вбий 10 трогів Каменедробів та 10 розвідників Каменедробів та повертайся.", [3] = "Горянин Кремінник з південної вартової вежі просить вас вбити 10 трогів Каменедробів та 10 розвідників Каменедробів.", [4] = "Лох-Модан в небезпеці, {ім'я}! Нам потрібен кожен член Альянсу, хто може тримати зброю, щоб допомогти нашій справі. Ти вже {стать:вбив:вбила} 10 трогів Каменедробів та 10 розвідників Каменедробів?", [5] = "Чудова робота, {ім'я}! Ти {стать:показав:показала} неабияку хоробрість на полі бою. Ми переможемо у війні проти трогів завдяки зусиллям таких, як ти. Ти добре {стать:послужив:послужила} королю Маґні.\n\nЯкщо тобі до вподоби такі пригоди - поговори з горянином Ринєлютом. Капітан дав йому нелегке завдання, тож йому може знадобитись твоя допомога. Ти знайдеш Ринєлюта всередині вежі.", ["en"] = "In Defense of the King's Lands", ["tasks"] = { ["Stonesplinter Scout"] = "розвідник Каменедробів", ["Stonesplinter Scout slain"] = "розвідник Каменедробів: убито", ["Stonesplinter Trogg"] = "трог Каменедробів", ["Stonesplinter Trogg slain"] = "трог Каменедробів: убито" } },
    [2240] = { [1] = "Прихована кімната", [2] = "Тепер повернемося до нагальних завдань.\n\nІснує таємна кімната, кімната Хаз'мула, яку потрібно дослідити. Проблема в тому, що вона знаходиться за величезними замкненими дверима! На щастя, я знаю, як їх відчинити.\n\nЯ все описав у своєму щоденнику, ось тут, на столі. Ми з групою поки що застрягли тут... тож ти, {ім'я}, маєш знайти для нас кімнату Хаз'мула!\n\nПрочитай мій щоденник, досліди кімнату, а потім звітуй розвідувачу Бурешпилю в Залізогарті.", [3] = "Прочитайте щоденник Бейлоґа, дослідіть приховану кімнату та звітуйте розвідувачу Бурешпилю.", [4] = "У тебе є про що розказати?", [5] = "Ти {стать:бачив:бачила} кімнату Хаз'мула? Дивовижно! Бейлоґ був упевнений, що вона існує, але я, чесно кажучи, сумнівався.\n\nДякую, {ім'я}. Якщо пощастить, твоя знахідка спонукає наших лідерів відновити зусилля для відвоювання Ульдамана. А коли це місце знову повернеться під контроль Залізогарта, всі таємниці кімнати Хаз'мула будуть нашими!", ["en"] = "The Hidden Chamber", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Explore the Hidden Chamber"] = "Дослідіть Приховану кімнату" } },
    [2242] = { [1] = "Поклик долі", [2] = "Нам здається, що одна істота могла б допомогти нам зрозуміти, що відбувається з лісами Тельдрассіля. На жаль, змусити його співпрацювати виявилося неймовірно складно.\n\nВін ховається на гілці в околицях поляни Оракула. Поки що всіх, хто підходив до цього сатира — з погрозами чи добрим словом — зустріли свою загибель. Може, треба підкрастися до нього непомітно, {ім'я}.\n\nДізнайся, що у Сетіра Древнього в сумках, і повертайся до мене.", [3] = "Знайдіть Сетіра Древнього та принесіть Сіарні будь-які докази.", [4] = "Чи є тобі що доповісти мені про Сетіра Древнього, {ім'я}?", [5] = "Це похмурі новини, {ім'я}. Схоже, що хвороба, яка вразила ліси та річки Темнобережжя, почала плямувати наш дім.\n\nТи добре нам {стать:послужив:послужила}, але ти більше нічим не зможеш допомогти. Візьми це лезо як винагороду за твої послуги Тельдрассілю.", ["en"] = "Destiny Calls", ["tasks"] = { ["Sethir's Journal"] = "щоденник Сетіра", ["Sethir's Journal (Provided)"] = "щоденник Сетіра (видано)" } },
    [225] = { [1] = "Занедбана могила", [2] = "Надпис на занедбаному могильному камені говорить:\n\nМОРГАН ЛАДІМОР\n\n<При подальшому огляді ви помічаєте, що могилу нещодавно розкопували, і більшість ґрунту насипана заново...>", [3] = "Поговоріть з Сіррою Фон'Інді в Темнодолі.", [5] = "Морган Ладімор?\n\nАх, так, звичайно. Це була довга та сумна історія. Я знав його добре, до того часу, як він пішов на війну, але це було останнє, що я про нього чув. Він був благородним та добрим, але доля приготувала йому нещасний кінець.\n\nТут у мене має бути щось, що розповість історію краще за мої власні спогади...", ["en"] = "The Weathered Grave" },
    [226] = { [1] = "Вовки наступають на п'яти", [2] = "На нас зі Свеном чекають важкі дні через некроманта на сході. Ми тут зовсім одні, тому нам доводиться самостійно добувати собі їжу. Здається, кожного разу, коли я повертаюся до табору з м'ясом, з лісу виходять голодні або скажені вовки, які хочуть перекусити. Що й казати, жити тут небезпечно!\n\nАле якщо ти позбавиш нас хоча б від частини вовків, нам стане легше. Вони живуть на півночі та сході звідси, біля річки.", [3] = "Вбийте 12 голодних зловісних вовків і 8 скажених зловісних вовків, а потім поверніться до Ларса в табір Свена на західному кордоні Смерколісся.", [4] = "Ти ще не {стать:вполював:вполювала} вовків...?", [5] = "О, чудово. Ти здорово {стать:зменшив:зменшила} вовчу зграю, і тепер, коли вовки не наступають нам на п'яти, ми зможемо зосередитись на боротьбі проти Морбента Скверна.\n\nОсь, візьми декілька вибухових пакетів. Їх виготовляють у місті, і багато з них були передані Свену, щоб допомогти його справі.", ["en"] = "Wolves at Our Heels", ["tasks"] = { ["Rabid Dire Wolf"] = "скажений зловісний вовк", ["Rabid Dire Wolf slain"] = "скажений зловісний вовк: убито", ["Starving Dire Wolf"] = "голодний зловісний вовк", ["Starving Dire Wolf slain"] = "голодний зловісний вовк: убито" } },
    [2260] = { [1] = "Наказ Еріона", [2] = "Чутки про твої діяння розійшлися, {ім'я}. Настільки далеко, що навіть розвідка Штормовію хоче з тобою поговорити.\n\nПодорож далека та небезпечна, але можливість тренуватися в ШУР того варта.\n\nНовий світ чекає на тебе, {ім'я}. Вирушай у Старе Місто Штормовію та поговори з Рензіком \"Пером\" у штаб-квартирі ШУР.", [3] = "Відправляйтеся до Штормовію та знайдіть Рензіка \"Перо\".", [5] = "Ти {стать:відповів:відповіла} на заклик ШУР, {ім'я}, ти {стать:пройшов:пройшла} довгий шлях з далеких берегів, щоб приєднатися до наших лав. Однак тобі іще багато чому варто навчитися.", ["en"] = "Erion's Behest" },
    [227] = { [1] = "Морган Ладімор", [2] = "<Він шукає на полицях і знаходить книгу в шкіряній палітурці.>\n\nЯкщо хочеш дізнатися більше, запитай Альтею, саме вона останнім часом займалася... проблемами... з ним.", [3] = "Поговоріть з командиром Альтеєю Чорнобривою в Темнодолі.", [5] = "Морган Ладімор? Ніколи не чула...\n\nОх, ти маєш на увазі Мор'Ладіма! Здається, ти не {стать:чув:чула} цю історію?\n\nДобре, я розповім тобі коротко. Блудний невмерлий під іменем Мор'Ладім блукає по лісах Смерколісся. З того, нам відомо, схоже, що цим невмерлим є Морган Ладімор, про якого ти вже знаєш. Він завдає нам багато клопоту, нападаючи на вартових під час патрулювання та вбиває людей.\n\n<Вона оцінює вас.>\n\nЗдається, ти {стать:зміг би:змогла б} допомогти упокоїти його дух.", ["en"] = "Morgan Ladimore" },
    [2279] = { [1] = "Платинові диски", [2] = "Дотик до дисків Норґаннона знову викликає поколювання у ваших пальцях. Однак, цього разу зсередини дисків доноситься гучний скрегіт.\n\nВаш рюкзак раптово стає тяжче. Всередині ви знаходите мініатюрну версію дисків!\n\nБез сумніву, такий предмет — безцінна знахідка для того, хто зацікавлений в древній історії Азероту. Ліга дослідників в Залізогарті — одна з таких груп в Альянсі. Можливо, вони знайдуть їм належне застосування.", [3] = "Віднесіть мініатюрну копію дисків Норґаннона до Ліги дослідників в Залізогарт.", [4] = "Так, чи можу я тобі чимось допомогти? Чесно кажучи, я зараз дуже зайнятий. Та якщо в тебе є щось значуще для Ліги дослідників — я тебе уважно слухаю!", [5] = "Що це в тебе... ой, лишенько. Де ти це {стать:знайшов:знайшла}, кажеш?\n\nЩо, правда?\n\nА ще хтось про це знає?\n\nЩО, ПРАВДА?\n\n{стать:Любий:Люба} {клас:к}, ти, можливо, {стать:здійснив:здійснила} археологічне відкриття року! Та кого я обдурюю, це відкриття століття! Якщо це ті самі диски, то ми знайшли ключ, який дуже довго шукали! Тепер ми раз і назавжди доведемо магічне походження дворфів!", ["en"] = "The Platinum Discs", ["tasks"] = { ["Miniature Platinum Discs"] = "мініатюрні платинові диски", ["Miniature Platinum Discs (Provided)"] = "мініатюрні платинові диски (видано)" } },
    [228] = { [1] = "Мор'Ладім", [2] = "З того, що повідомляють мої розвідники, Мор'Ладім блукає по всьому Смерколіссі, йдучи дивною звивистою стежкою через цвинтар. Ми поховали його за будинком на пагорбі, знаєш, де це?\n\nБільше нічим не можу допомогти тобі, але бажаю удачі.", [3] = "Убийте Мор'Ладіма, а потім принесіть його череп командиру Альтеї Чорнобривій у Темноділ.", [4] = "Я не звинувачуватиму тебе, якщо тобі не вдасться впоратися з ним, {ім'я}. Деякі з наших найсильніших вартових були вбиті Мор'Ладімом.", [5] = "Ти його {стать:вбив:вбила}? Це не мале досягнення, {ім'я}! Від імені жителів Темнодолу та Нічної варти я дякую тобі.\n\nАле... є одна справа, яку потрібно обговорити...", ["en"] = "Mor'Ladim", ["tasks"] = { ["Mor'Ladim's Skull"] = "череп Мор'Ладіма", ["Mor'Ladim's Skull (Provided)"] = "череп Мор'Ладіма (видано)" } },
    [2281] = { [1] = "Зустріч в Багрянокряжжі", [2] = "Відправляти тебе в поле зараз було б самогубством. Рензіку не {стать:потрібен іще один мертвий пройдисвіт:потрібна іще одна мертва пройдисвітка} на його руках. Не переймайся, {ім'я} — для тебе знайдеться не така небезпечна справа.\n\nВідправляйся до Багрянокряжових гір та поговори з Лукієм, цей тип пов'язаний із ШУР. Ти знайдеш його біля пристані Приозер'я, він постійно отирається там з іншими неробами.", [3] = "Відправтеся до Приозер'я в Багрянокряжових горах та поговоріть з Лукієм.", [5] = "Ага, тож твої пальці трошки затовсті, ге? Та не переймайся, {ім'я}, я й не з таких нікчемних злодюжок робив чудових пройдисвітів.", ["en"] = "Redridge Rendezvous" },
    [229] = { [1] = "Дочка, що вижила", [2] = "Я повинна була розповісти тобі це раніше...\n\nЯк краще сказати...\n\nМожливо, Морган вважав, що його родина померла, але насправді його дочка Сара Ладімор тепер вартова. Вона завжди страждала через... обставини... що оточують смерть її батька. Можливо, ти {стать:міг би:могла б} повідомити її про це.", [3] = "Поговоріть з вартовою Сарою Ладімор у Темнодолі.", [5] = "Так? Мій батько...\n\n<Її очі опускаються.>\n\nХотіла б я... щоб було щось, що я могла б для нього зробити... Якби я тільки поговорила з ним до того, як він...", ["en"] = "The Daughter Who Lived" },
    [230] = { [1] = "Табір Свена", [2] = "Копаючи землю, ви знаходите маленьку, заляпану брудом книжку.\n\nКнига не має назви, але... в ній міститься інформація, яку Свену варто знати.", [3] = "Принесіть Свену книгу з його ферми.", [4] = "Ти {стать:знайшов:знайшла} щось? Прошу, дай мені поглянути...", [5] = "<Свен читає сторінки книги, а потім закриває її.>\n\nЦей таємничий незнайомець, якого я бачив, був свідком смерті моєї сім'ї! Є питання, які я хотів би поставити йому... якби ж я тільки знав, хто це!", ["en"] = "Sven's Camp", ["tasks"] = { ["Book from Sven's Farm"] = "книга з ферми Свена", ["Book from Sven's Farm (Provided)"] = "книга з ферми Свена (видано)" } },
    [231] = { [1] = "Любов доньки", [2] = "Ось, візьми це і поклади на його могилу. Можливо... якимось чином він дізнається, що зі мною все гаразд, і зрозуміє, що ніхто з нас не вважає його винним за те, що сталося.\n\n<На її очах видніються сльози, поки вона знімає каблучку зі своєї правої руки та кладе її вам у руку.>\n\nІ... дякую тобі, {ім'я}.", [3] = "Віднесіть каблучку Сари Ладімор до могили Моргана Ладімора.", [4] = "Облиш мене...", [5] = "<Примарний голос лунає по вітру...>\n\nЩо це...? Сара? Невже вона жива? Гора з плечей впала...\n\n{ім'я}. Візьми мій меч, Архей. Моя душа упокоєна, мені він більше не потрібен. Він був викуваний нести добро, і я довів, що негідний тримати його. Можливо, ти зможеш нести ним світло замість мене.\n\nЛіз, моя любов...", ["en"] = "A Daughter's Love", ["tasks"] = { ["Sarah's Ring"] = "каблучка Сари", ["Sarah's Ring (Provided)"] = "каблучка Сари (видано)" } },
    [233] = { [1] = "Пошта Морозної долини", [2] = "Гм, не думаю, що ти надто гориш бажанням мені допомогти, еге ж {стать:малий:мала}? Сьогодні прийшов стіс листів, але в мене нема часу доставити їх.\n\nВсі вони адресовані Таліну Гострозору. Ти можеш знайти його прямуючи дорогою на захід. Його табір поруч з замерзлим озером.\n\nТо що скажеш?", [3] = "Доставте стіс листів Таліну Гострозору.", [4] = "Так? Маєш щось для мене?", [5] = "Дякую тобі, я вже давно чекав ці листи...\n\nНа жаль, не всі листи для мене. Цей адресований Ґреліну Білобороду. Він мешкає не надто далеко, якщо схочеш доставити лист.", ["en"] = "Coldridge Valley Mail Delivery", ["tasks"] = { ["A Stack of Letters"] = "стіс листів", ["A Stack of Letters (Provided)"] = "стіс листів (видано)", ["Deliver the stack of letters to Talin Keeneye."] = "Доставте стіс листів Таліну Гострозору." } },
    [234] = { [1] = "Пошта Морозної долини", [2] = "Якщо я вірно пам'ятаю, табір Ґреліна знаходиться далі по дорозі, на південний схід звідси. Без сумніву, він з нетерплячкою очікує на свою пошту.", [3] = "Доставте лист Ґреліну Білобороду.", [4] = "Чи можу я тобі чимось допомогти?", [5] = "Ах, чудово. Давно ж я не отримував звістку з Залізогарта.", ["en"] = "Coldridge Valley Mail Delivery", ["tasks"] = { ["A Letter to Grelin Whitebeard"] = "лист до Ґреліна Білоборода", ["A Letter to Grelin Whitebeard (Provided)"] = "лист до Ґреліна Білоборода (видано)", ["Deliver the letter to Grelin Whitebeard."] = "Доставте лист Ґреліну Білобороду." } },
    [237] = { [1] = "На захист королівських земель", [2] = "Горянин Кремінник дуже нахвалює тебе, {раса:н}. Тому я хочу довірити тобі надзвичайно важливе завдання. Ми маємо продовжувати тиснути на трогів, поки наші браття дворфи не повернуться з фронту.\n\nВідправляйся на південні пагорби та вбий 10 череполомів Каменедробів та 10 провидців Каменедробів. Цим ти виграєш нам трішки часу. Повертайся до мене, як виконаєш завдання.", [3] = "Горянин Ринєлют з південної вартової вежі просить вас вбити 10 череполомів Каменедробів та 10 провидців Каменедробів.", [4] = "Нам потрібно більше часу, {раса:к}. Твоє завдання - вбити 10 череполомів Каменедробів та 10 провидців Каменедробів. Ми маємо підтримувати натиск, доки не прийде підкріплення. Зараз ми не маємо часу на відпочинок.", [5] = "Ти добре {стать:впорався:впоралась} із завданням, {раса:к}. Сам король може пишатись тобою.\n\nНа жаль, обіцяне підкріплення так і не з'явилось. Схоже, що на полях бою полягло багато наших братів. Гіркі звістки про втрати сповнюють болем моє серце. Але їх загибель не має бути марною. Ми маємо об'єднатись в ці важкі часи й принести славу Альянсу.\n\nПоговори з горянином Стіноламом, він дасть тобі нове завдання. Зараз ти нам {стать:потрібен:потрібна}, як ніколи.", ["en"] = "In Defense of the King's Lands", ["tasks"] = { ["Stonesplinter Seer"] = "провидець Каменедробів", ["Stonesplinter Seer slain"] = "провидець Каменедробів: убито", ["Stonesplinter Skullthumper"] = "череполом Каменедробів", ["Stonesplinter Skullthumper slain"] = "череполом Каменедробів: убито" } },
    [239] = { [1] = "Гарнізон Західноводдя потребує допомоги!", [2] = "Гарнізон на нашому західному кордоні повідомляє про посилення активності гнолів і злодіїв. Вони просять вислати допомогу... але у нас просто немає жодного вільного солдата!\n\nЯкщо у тебе є нагода допомогти, ми охоче її приймемо. Поговори із заступником Райнером в гарнізоні Західноводдя, поглянь, що йому там потрібно зробити.\n\nГарнізон — далі по дорозі на захід. Праворуч, як перейдеш міст через невеликий струмок.", [3] = "Прямуйте до гарнізону Західноводдя та поговоріть там із заступником Райнером.", [5] = "Значить, маршал Дуган прислав тебе? Ну, ти явно не солдат, але мені достатньо того, що саме Дуган обрав тебе!\n\nНаша ситуація досить напружена, м'яко кажучи. Сподіваюся, ти зможеш нам допомогти.", ["en"] = "Westbrook Garrison Needs Help!" },
    [2398] = { [1] = "Загублені дворфи", [2] = "Розкопки в Ульдамані не завжди були захоплені трогами. Ми, дворфи Залізогарту, контролювали цю територію, але... це було до того, як прийшли троги. Вони прийшли так швидко і в такій кількості, що навіть дворфи не змогли їх зупинити!\n\nНасправді їхній напад був настільки раптовим, що я боюся, що деякі з наших могли опинитися в пастці в тилу ворога.\n\nМій друг Бейлоґ керував невеликим загоном дворфів углибині розкопок якраз перед тим, як з'явилися троги. Якщо він і його хлопці живі, я хочу, щоб ти {стать:знайшов:знайшла} їх.", [3] = "Знайдіть Бейлоґа в Ульдамані.", [5] = "Ти саме вчасно! Я вже думав, що програю Олафу!\n\nВін побився об заклад, що його борода виросте до колін, перш ніж він побачить інше живе створіння. І ось ти тут, і, як бачиш, бороді Олафа залишилося ще кілька сантиметрів до колін.\n\nДякую, {ім'я}. Я поділю з тобою виграш.", ["en"] = "The Lost Dwarves" },
    [2399] = { [1] = "Пророслі паростки", [5] = "Паростки, які Деналан посадив у своєму саду, зійшли та виросли. Вони тремтять, неначе хочуть, щоб їх хтось зібрав...", ["en"] = "The Sprouted Fronds" },
    [240] = { [1] = "Повернення до Тремтінія", [2] = "А ось і крабові пиріжки а-ля Ґруал!", [3] = "Поверніться до Тремтінія з темними крабовими пиріжками.", [4] = "{ім'я}, нарешті ти тут! Ти {стать:приніс:принесла} мені їжу?!?", [5] = "Ага! Дякую, {ім'я}. Те, що треба!\n\nІ ось, будь ласка, дозволь мені заплатити за це!", ["en"] = "Return to Jitters", ["tasks"] = { ["Dusky Crab Cakes"] = "темні крабові пиріжки", ["Dusky Crab Cakes (Provided)"] = "темні крабові пиріжки (видано)" } },
    [2438] = { [1] = "Смарагдовий ловець снів", [2] = "Колись Ґеролас Талветрен, вартовий сплячих Друїдів Кігтя в обителі кургану Бен'етіль, дав мені смарагдовий ловець снів. Цей потужний амулет здатен витягувати енергію зі Смарагдового Сну, даруючи удачу тому, хто ним володіє.\n\nНа жаль, мені не вдалося забрати його зі своєї шафи в селищі Зоряний Бриз... Хоча колись це селище і було спокійним місцем, тепер там живуть охоплені порчею хутропузи.\n\nМожливо, ти {стать:зміг би:змогла б} повернути мій ловець снів, {клас:к}?", [3] = "Принесіть смарагдовий ловець снів Таллонкаю Спритнокореню в Доланаар.", [4] = "Прошу, рушай хутчіш! Мені залишається сподіватися, що жоден хутропуз не пошкодив мій ловець снів.\n\nТобі вже вдалося його повернути, {Ім'я}?", [5] = "Цей смарагдовий ловець снів для мене дуже важливий. Такий подарунок роблять небагатьом. Дякую, що {стать:повернув:повернула} його мені, {Ім'я}.", ["en"] = "The Emerald Dreamcatcher", ["tasks"] = { ["Emerald Dreamcatcher"] = "смарагдовий ловець снів", ["Emerald Dreamcatcher (Provided)"] = "смарагдовий ловець снів (видано)" } },
    [2439] = { [1] = "Платинові диски", [2] = "Цей об'єкт — неймовірна знахідка. Згідно з цими дисками, древні титани, або ж \"Творці\", як їх називають в дисках, пов'язані з нашим магічним походженням! Ми маємо якомога детальніше вивчити їх.\n\nА щодо тебе, {стать:героїчний:героїчна} {клас:к}, віднеси цей талон Дініті Камнекривій в сховище. По ньому ти отримаєш гідну винагороду за свої зусилля!\n\nПовертайся до мене, як будеш {стать:готовий:готова}. У Ліги дослідників ще багато роботи для тебе!", [3] = "Віднесіть ваш талон на винагороду Дініті Камнекривій в сховище Залізогарту.", [4] = "Ласкаво прошу до сховища Залізогарту, {ім'я}. Чи я можу тобі допомогти?", [5] = "А, так, це талон від Ліги дослідників... доволі цінний, до речі.\n\nЛіга дослідників доручила мені запропонувати тобі на вибір винагороду зі сховища. Ти можеш отримати цю річ і обрати з п'яти відмінних зіллів лікування та п'яти сильних зіллів мани.", ["en"] = "The Platinum Discs", ["tasks"] = { ["Reward Voucher"] = "талон на винагороду", ["Reward Voucher (Provided)"] = "талон на винагороду (видано)" } },
    [244] = { [1] = "Вторгнення гнолів", [2] = "Вітаю, {клас:к}. Мені доручено патрулювати цей відрізок дороги. І хоча дорога поки що безпечна, я помітив табори гнолів, на півночі та на сході.\n\nПриозер'я має знати про об'єднання сил гнолів! Відрапортуй заступнику Фелдону в Приозер'ї та розкажи йому про них. Зроби це, і Фелдон, певно, запропонує тобі гонорар розвідника.\n\nВін зазвичай наглядає за територією на південь від мосту до Приозер'я.", [3] = "Відрапортуйте заступнику Фелдону.", [5] = "Багрянокряжові гноли так близько від Ельвинну?? Мабуть, вони мають намір вторгнутися в нашу батьківщину. Скоро не лише люди Приозер'я будуть в облозі!\n\nОсь твоя платня, хоч ти і {стать:приніс:принесла} страшні вісті. І прийшли вони невчасно, бо ж ми недостатньо споряджені для такого нападу.", ["en"] = "Encroaching Gnolls" },
    [245] = { [1] = "Восьмилапа загроза", [2] = "Привіт, {клас:н}. Можливо, ти {стать:бачив:бачила} тих павуків, що на західному кордоні? Ця небезпечна восьмилапа загроза завдає нам надто багато проблем, а командир не має достатньо солдат, щоб відправити їх так далеко від Темнодолу.\n\nМені ніяково просити тебе про допомогу, але, здається, тобі вдалося б з ними впоратися. Не можу обіцяти тобі щось дуже цінне, але винагороджу, якщо ти допоможеш винищити цих бридких потвор.\n\nМоя тобі порада — остерігайся їхньої отрути.", [3] = "Убийте 15 карликових отруйних колопрядів, а потім поверніться до вартового Доддса в Смерколісся.", [4] = "Тобі краще бути {стать:обережним:обережною}, коли ти будеш мати справу з павуками. Я втратив кількох своїх людей через них, і повір мені, це неприємний вид — побачити солдата, який висить догори ногами у їхній павутині після того, як отрута почала їх розкладати.\n\nЯ не хотів би бачити, як одна з цих потвор з'їдає тебе на обід.", [5] = "А! Ти {стать:повернувся:повернулася}. І, здається, не надто {стать:постраждав:постраждала}. Звичайно ж, {ім'я}, Нічна варта вдячна за твою роботу, тож ось обіцяна винагорода.", ["en"] = "Eight-Legged Menaces", ["tasks"] = { ["Pygmy Venom Web Spider"] = "карликовий отруйний колопряд", ["Pygmy Venom Web Spider slain"] = "карликовий отруйний колопряд: убито" } },
    [2459] = { [1] = "Феросітас Пожирач Снів", [2] = "Смарагд... Він зник! Мій ловець снів пошкоджено!\n\nНа півночі від Зоряного Бризу засіла зграя містиків з племені Кривої Сосни. Я чув, що їхній ватажок, Феросітас Пожирач Снів, носить намисто, яке світиться зеленим уночі. Тепер, бачачи мій ловець снів, я впевнений, що це він вкрав мій смарагд... Він не розуміє, що сила самоцвіту йому не потрібна.\n\nЗнайди зниклий камінь, {Ім'я}. І якщо ти вже {стать:взявся:взялась} за це..., вбий кілька представників цієї погані.", [3] = "Убийте 7 містиків з племені Кривої Сосни для Таллонкая Спритнокорня та знайдіть зниклий самоцвіт.", [4] = "Нехай Феросітас та містики Кривої Сосни повернуть те, що належить мені! Прошу тебе, забери в них смарагд, щоб я міг полагодити свій ловець снів.", [5] = "Нарешті я можу полагодити свій ловець снів! Спасибі тобі, {Ім'я}.", ["en"] = "Ferocitas the Dream Eater", ["tasks"] = { ["Gnarlpine Mystic"] = "містик Кривої Сосни", ["Gnarlpine Mystic slain"] = "містик Кривої Сосни: убито", ["Tallonkai's Jewel"] = "самоцвіт Таллонкая", ["Tallonkai's Jewel (Provided)"] = "самоцвіт Таллонкая (видано)" } },
    [246] = { [1] = "Оцінка загрози", [2] = "У нас немає зайвих людей, але з цими гнолами, про яких {стать:доповів:доповіла}, треба щось робити.\n\nРозвідай південне Багрянокряжжя і пошукай там гнолів. Зроби засідку, вбий, скільки зможеш, і доповіси мені, скільки їх та яку загрозу вони становлять. Ти можеш знайти табори цих гнолів вздовж південної дороги Багрянокряжжя.\n\nЗроби це заради армії Штормовію, {ім'я}, і отримаєш винагороду.", [3] = "Убийте 10 багрянокряжових дворняг і 6 багрянокряжових браконьєрів, а потім відрапортуйте заступнику Фелдону в Приозер'ї.", [4] = "Перепрошую, {ім'я}, але ми тут сильно зайняті. Якщо тобі нічого доповісти, я краще займусь іншими справами.", [5] = "<Заступник Фелдон слухає вашу доповідь...>\n\nТам отаборилися чималі сили гнолів, і з того, що ти мені {стать:розповів:розповіла}, вони міцні горішки. Це мало бути непросто - зібрати ці відомості.\n\nОсь, будь ласка, {ім'я}. Ми вдячні за твою допомогу.\n\nІ якщо ти ще досі цього не {стать:зробив:зробила}, поговори з маршалом Маррісом і війтом Соломоном у Приозер'ї. Наша ситуація стає все безнадійнішою, і у цих двох точно знайдеться справа для тебе.", ["en"] = "Assessing the Threat", ["tasks"] = { ["Redridge Mongrel"] = "багрянокряжова дворняга", ["Redridge Mongrel slain"] = "багрянокряжова дворняга: убито", ["Redridge Poacher"] = "багрянокряжовий браконьєр", ["Redridge Poacher slain"] = "багрянокряжовий браконьєр: убито" } },
    [248] = { [1] = "Глибший погляд", [2] = "Я спостерігав за вежею Ілґалара і помітив, що Морґант ворогує з орками у фортеці Кам'яної Варти. Я не знаю в чому причина, але ти можеш допомогти мені розгадати цю таємницю.\n\nВізьми ще один гліф Азори та віднеси його на вершину вцілілої вежі поряд з фортецею Кам'яної Варти.\n\nЗнайди підхоже місце, де ти зможеш сховати його. В якійсь скрині чи глечику — головне, щоб його не помітили.", [3] = "Підніміться на вцілілу сторожову вежу поруч з фортецею Кам'яної Варти.\n\nЗнайдіть придатне місце для розміщення гліфа Азори.", [4] = "Колись у цьому глечику був смердючий напій, але тепер він лежить порожній і забутий на парі бочок.", [5] = "Це підхожа посудина для гліфа Азори. Тепер Теокріт зможе дізнатись більше про задуми мешканців фортеці Кам'яної Варти.", ["en"] = "Looking Further", ["tasks"] = { ["Glyph of Azora"] = "гліф Азори", ["Glyph of Azora (Provided)"] = "гліф Азори (видано)" } },
    [249] = { [1] = "Морґант", [2] = "Після довгих спостережень я нарешті розкрив плани Морґанта.\n\nВін шукає косу Елуни... і, можливо, вже знайшов її! Якщо так, то незабаром Багрянокряжжя, а потім і все королівство Штормовію відчує його темну силу.\n\nЯ не готовий протистояти Морґанту, але боюсь, що ми не можемо гаяти час. Ти маєш піти до вежі Ілґалара і зустрітися з Морґантом.\n\nПереможи його і принеси мені його кулон тіні. Зроби це, і королівство цього не забуде.", [3] = "Переможіть Морґанта.\n\nПринесіть його кулон тіні Теокріту до вежі Азори, що в Ельвиннському лісі.", [4] = "Поспіши, {ім'я}, поки мої побоювання щодо Морґанта не справдилися!", [5] = "Ти {стать:зробив:зробила} велику справу, {ім'я}. Перемігши чорнокнижника Морґанта, ти {стать:врятував:врятувала} Штормовій від великої небезпеки.\n\nСмиренно прошу прийняти цю нагороду. І я б побажав тобі миру, якби це були мирні часи.\n\nАле натомість я побажаю тобі удачі в подальших випробуваннях і перемоги в майбутніх боях.", ["en"] = "Morganth", ["tasks"] = { ["Pendant of Shadow"] = "кулон тіні", ["Pendant of Shadow (Provided)"] = "кулон тіні (видано)" } },
    [2498] = { [1] = "Повернення до Деналана", [2] = "Я щойно отримав звістку про те, що Деналан біля озера Аль'Амет виявив причину пухлин у деревників. Будь ласка, поговори з ним і скажи, що я тебе направив до нього.\n\nПоспішай, {Ім'я}. Йому потрібна наша допомога.", [3] = "Релліан Зеленоватрий хоче, щоб ви поговорили з Деналаном біля озера Аль'Амет.", [5] = "Отже, Релліан послав тебе допомогти мені. Я радий, що ти {стать:прийшов:прийшла} до мене так швидко.\n\nЯ виявив тривожні речі!", ["en"] = "Return to Denalan" },
    [2499] = { [1] = "Дубохмур", [2] = "У печері вздовж південного берега озера великий деревник на ім'я Дубохмур поширює порчу на всіх істот, що мешкають на Аль'Амет.\n\nЯ не наважувався підійти занадто близько, але навіть на відстані мені зрозуміло, що Дубохмур уражений найбільшою пухлиною, яку я коли-небудь бачив... Я б навіть сказав велетенською.\n\n{Ім'я}, ти вже багато чого {стать:зробив:зробила} для мене, але я прошу тебе виконати ще одне завдання. Вистеж Дубохмура та виріж в нього цю пухлину. Вилучи джерело порчі з мого дому.", [3] = "Деналан з озера Аль'Амет хоче, щоб ви забрали велетенську пухлину в Дубохмура.", [4] = "Тобі вже вдалося вистежити Дубохмура, {раса:к}?", [5] = "Я знав, що ти зможеш врятувати озеро від цього жахливого монстра.\n\nЯк невтішно... Колись Дубохмур був великим вождем свого народу... але порча вражає всіх підряд — і підлих, і благородних.\n\nВід величини цієї пухлини бере дрижа, але я мушу дослідити її, щоб зрозуміти, який недуг мучить деревників.\n\nЯ безмежно вдячний тобі, {Ім'я}.", ["en"] = "Oakenscowl", ["tasks"] = { ["Gargantuan Tumor"] = "велетенська пухлина", ["Gargantuan Tumor (Provided)"] = "велетенська пухлина (видано)" } },
    [250] = { [1] = "Темна загроза", [2] = "Хвала небесам, хоч хтось тривожиться станом нашої Дамби. Спочатку знищення віадука Тандола, потім розграбування Дун-Модру! Я впевнений, що дамба буде наступною ціллю Темного Заліза. Більшість охоронців відправили на фронт Альянсу, включаючи мого старшого інспектора.\n\nТому ти мені й {стать:потрібен:потрібна}, {ім'я}. Я помітив саперів Темного Заліза, що вештались біля східного краю дамби. Поглянь що вони там затіяли і повертайся з доказами.", [3] = "Огляньте область біля східного краю дамби та принесіть старшому інженеру Греблеру докази того, що дворфи Темного Заліза щось затівають.", [5] = "В бочці міститься порошок з дивним запахом.", ["en"] = "A Dark Threat Looms" },
    [2500] = { [1] = "Забіг по реагенти Безплідними краями", [2] = "{Клас:к}, я хотів би скористатись твоїми послугами. Я — досить визначний алхімік, і мені потрібна твоя допомога у здобутті деяких реагентів, які можна відшукати в Безплідних краях.\n\nОсь що мені потрібно, щоб поповнити свої запаси: п'ять шлунків канюка, десять ікл скельного койота і п'ять уламків кам'яних елементалів. Очевидно, що їх можна добути з цих самих створінь. Та якщо ти не любиш битись — попроси допомоги у друзів.\n\nРоздобудь для мене ці реагенти, і я непогано заплачу.\n\nНу, шо скажеш?", [3] = "Добудьте в Безплідних краях реагенти для Ґхака Цілителя і віднесіть їх йому в Телсамар.", [4] = "Ти {стать:добув:добула} все необхідне? Поки не принесеш - не заплачу.", [5] = "А, чудова робота, {ім'я}. Цього мені має вистачити на деякий час. Ось твоя плата, як я й обіцяв.\n\nЯкщо ти не проти ще допомогти, мені потрібно ще кілька реагентів. Деякі з них, однак, можна знайти лише на Ульдаманських розкопках. Це буде нелегко, але й винагорода буде відповідна, якщо візьмешся.\n\nМожливо, щось більше, ніж декілька блискучих монет, ммм?", ["en"] = "Badlands Reagent Run", ["tasks"] = { ["Buzzard Gizzard"] = "шлунок канюка", ["Buzzard Gizzard (Provided)"] = "шлунок канюка (видано)", ["Crag Coyote Fang"] = "ікло скельного койота", ["Crag Coyote Fang (Provided)"] = "ікло скельного койота (видано)", ["Rock Elemental Shard"] = "уламок кам'яного елементаля", ["Rock Elemental Shard (Provided)"] = "уламок кам'яного елементаля (видано)" } },
    [251] = { [1] = "Переклад записки Аберкромбі", [2] = "Передай цю записку Сіррі Фон'Інді. Він дуже обізнаний у стародавніх мовах та мистецтвах — якщо хтось тут може перекласти цей лист, то це він.", [3] = "Принесіть лист Елло до Сірри Фон'Інді.", [4] = "Записка від Аберкромбі, відлюдника, так? Я його не знаю, хоча якщо він живе на кладовищі, то я точно знаю, що в нього мізки згнили!", [5] = "<Сірра починає перекладати записку...>", ["en"] = "Translate Abercrombie's Note", ["tasks"] = { ["Letter to Ello"] = "лист до Елло", ["Letter to Ello (Provided)"] = "лист до Елло (видано)" } },
    [2518] = { [1] = "Сльози місяця", [2] = "Леді Сатра колись була улюбленицею Елуни. Ця благородна і чиста павучиха пряла свої срібні нитки під місячним сяйвом, ловлячи вечірній туман. Його срібляста роса мала велику цілющу силу і зберігалася у цьому храмі.\n\nАле нещодавно Сатру спіткало безумство. Її нащадки теж під загрозою.\n\nЗнайди леді Сатру, {ім'я}, і поклади край її стражданням. Вона мешкає біля північних кордонів Тельдрассіля, біля Джерельного озера. Збери її сріблопавутинні залози та принеси мені.", [3] = "Жриця А'мура з храму Місяця просить вас принести їй сріблопавутинні залози леді Сатри.", [4] = "Я дала тобі це доручення з великим жалем, але леді Сатру вже не врятувати.\n\nМи сподіваємося, що якщо принести сріблопавутинні залози в жертву Елуні, то вона благословить Сатру і та переродитися з миром.", [5] = "Ліс оплакує леді Сатру, але ми мали це зробити.\n\nДякую тобі, {ім'я}.", ["en"] = "Tears of the Moon", ["tasks"] = { ["Silvery Spinnerets"] = "сріблопавутинні залози", ["Silvery Spinnerets (Provided)"] = "сріблопавутинні залози (видано)" } },
    [2519] = { [1] = "Храм Місяця", [2] = "Колись величне створіння лісу потребує нашої допомоги, {раса:к}.\n\nЄ нелегка справа, яку потрібно виконати.\n\nБудь ласка, знайди жрицю А'муру — вона все тобі пояснить. Ти знайдеш її на південний схід звідси, у храмі Місяця.", [3] = "Сестра Аквінна просить вас поговорити зі жрицею А'мурою в храмі Місяця.", [5] = "То тебе прислала сестра Аквінна?", ["en"] = "The Temple of the Moon" },
    [252] = { [1] = "Переклад для Елло", [2] = "Сили небесні! Якщо те, що написано на цій записці, правда, то Аберкромбі вчинив щось... невимовне.\n\nТобі краще віднести перекладену записку Елло.\n\nІ поспіши, бо я боюся, що загроза вже наближається до нашого міста...", [3] = "Передайте перекладеного листа лорду Елло Чорнобривому.", [4] = "А, записка перекладена? Будь ласка, дай мені поглянути...", [5] = "<Елло читає листа... і його обличчя біліє. Він дивиться на вас...>\n\nХоча допомога, яку ти {стать:надав:надала} Аберкромбі, можливо, і була мотивована добротою, твої дії прирекли наше місто на загибель.\n\n<Елло поринає у роздуми...>", ["en"] = "Translation to Ello", ["tasks"] = { ["Translated Letter"] = "перекладений лист", ["Translated Letter (Provided)"] = "перекладений лист (видано)" } },
    [2520] = { [1] = "Жертва Сатри", [2] = "Тепер ти маєш закінчити цю справу. Візьми залози та принеси Елуні жертву леді Сатри. Нехай вона спочиває з миром.\n\nУсередині цього храму знайди центральний фонтан. Там ти зможеш залишити жертву. Священні води змиють порчу, яка звела Сатру з розуму.\n\nЯк закінчиш — повертайся до мене.", [3] = "Жриця А'мура просить вас помістити сріблопавутинні залози леді Сатри біля фонтану храму Місяця та повернутись до неї.", [4] = "Ти {стать:залишив:залишила} залози біля фонтану, {ім'я}?", [5] = "Втрата леді Сатри неймовірно засмучує нас, але тільки так вона зможе переродитися з чистим духом.\n\nНехай Елуна прийме цю жертву.", ["en"] = "Sathrah's Sacrifice", ["tasks"] = { ["Offer the sacrifice at the fountain"] = "Принесіть жертву біля джерела" } },
    [253] = { [1] = "Наречена Бальзамувальника", [2] = "Бальзамувальник — це ім'я, яке згадується в одній з наших дитячих історій. Він був добрим алхіміком, який збожеволів після смерті своєї дружини Елізи. Щоб відродити її, він використав темну магію, щоб помістити своє серце в груди своєї мертвої дружини.\n\nЦе оживило Елізу... але прокляло її жагою до людського м'яса, змусивши Бальзамувальника тримати її похованою.\n\nЙого сила — в серці. Знайди могилу його дружини, забери його серце і принеси мені, поки воно ще б'ється. Зроби це, і його сила буде зламана.", [3] = "Знайдіть могилу Елізи. Заберіть у неї серце Бальзамувальника, а потім поверніться до Елло Чорнобривого.", [4] = "Ти вже {стать:був:була} на могилі Елізи? Серце Бальзамувальника у тебе?", [5] = "Ти {стать:зробив:зробила} це! Магія його серця захистить нас від зла Бальзамувальника та послужить потужним захистом для Темнодолу.\n\nТи {стать:зробив:зробила} велику справу для нашого народу, {ім'я}. Твоє ім'я назавжди залишиться в наших літописах.", ["en"] = "Bride of the Embalmer", ["tasks"] = { ["The Embalmer's Heart"] = "серце Бальзамувальника", ["The Embalmer's Heart (Provided)"] = "серце Бальзамувальника (видано)" } },
    [2541] = { [1] = "Сплячий друїд", [2] = "Шаман Кривої Сосни, який мешкає в цьому місці, знайшов спосіб відокремити дух сплячого друїда від його фізичного тіла. Хутропуз оживив мою фізичну форму та використовує її для нападу на тих, хто намагається розвідати обитель кургану Бен'етіль. Я тепер полонений у Смарагдовому Сні, тож безсилий зупинити це.\n\nТи мусиш мені допомогти. Шамани Кривої Сосни носять із собою дивний оберіг, який використовується для виконання цього ритуалу, і я хотів би його вивчити. Будь ласка, {Ім'я}, принеси мені такий.", [3] = "Принесіть шаманський оберіг вуду Обенові Лютопазуру в обитель кургану Бен'етіль.", [4] = "Дослідивши оберіг, я, можливо, зрозумію, як зруйнувати ці чари. Ти {стать:знайшов:знайшла} його?", [5] = "Дякую, {Ім'я}.\n\nЯка ж це дивна річ... Я відчуваю її мерзенну ауру, це дуже потужне чаклунство.", ["en"] = "The Sleeping Druid", ["tasks"] = { ["Shaman Voodoo Charm"] = "шаманський оберіг вуду", ["Shaman Voodoo Charm (Provided)"] = "шаманський оберіг вуду (видано)" } },
    [255] = { [1] = "Найманці", [2] = "Два місяці, поки в Залізогарті вирішать відправити нам на допомогу купку солдатів і ще два місяці, поки вони прибудуть! Мало того, що наше місто нема кому захищати, так ще й розкопки й дамба... дамба! - теж в небезпеці.\n\nЗдається, в мене немає вибору. Доведеться шукати найманців.\n\nЯк щодо тебе? Схоже, що ти згодишся, {клас:н}. Купка огрів стала табором на північний захід від озера. Може ти б {стать:знайшов:знайшла} ще кількох на кшталт тебе і {стать:допоміг:допомогла} усунути загрозу нашому місту?", [3] = "Війт Кирпоніс з Телсамару просить вас вбити 4 огрів Мо'ґрош, 4 моцаків Мо'ґрош та 4 громил Мо'ґрош.", [4] = "Ну як, щось виходить?", [5] = "О, це чудові новни! Жителі Телсамару та особисто я щиро цінуємо твої зусилля. Ба більше, якщо розберемось з ограми, ми зможемо зайнятись нашестям цих клятих трогів.", ["en"] = "Mercenaries", ["tasks"] = { ["Mo'grosh Brute"] = "моцак Мо'ґрош", ["Mo'grosh Brute slain"] = "моцак Мо'ґрош: убито", ["Mo'grosh Enforcer"] = "громило Мо'ґрош", ["Mo'grosh Enforcer slain"] = "громило Мо'ґрош: убито", ["Mo'grosh Ogre"] = "огр Мо'ґрош", ["Mo'grosh Ogre slain"] = "огр Мо'ґрош: убито" } },
    [256] = { [1] = "РОЗШУКУЄТЬСЯ: Чок'сул", [2] = "За рішенням війта Телсамару\n\nОгр Чок'сул, лідер і організатор нападів на Телсамар, Каменярську дамбу та розкопки Залізоплета засуджується до смерті в будь-який спосіб.\n\nГрошова винагорода буде видана тому, хто принесе війту доказ того, що Чок'сул мертвий.\n\nВостаннє Чок'сула бачили в таборі огрів на північному заході Лох-Модану.", [3] = "Вбийте Чок'сула та принесіть його голову війту Кирпоносу в Телсамар.", [4] = "Так? Чим я можу тобі допомогти?", [5] = "Фу, що це? І нащо ти це {стать:притяг:притягла}...\n\nСвяті... Це ж він? Ух, побий мене грім, це голова того клятого огра? Оце так здобич! Ось, прийми винагороду і подяку від мене та всіх жителів Телсамару.", ["en"] = "WANTED: Chok'sul", ["tasks"] = { ["Chok'sul's Head"] = "голова Чок'сула", ["Chok'sul's Head (Provided)"] = "голова Чок'сула (видано)" } },
    [2561] = { [1] = "Друїд Пазура", [2] = "Після дослідження цього оберегу, {Ім'я}, я розумію, що потрібно зробити. Будь ласка, візьми це та зроби те, що я прошу.\n\nТи {стать:повинен:повинна} спуститися у найглибші недри обителі кургану Бен'етіль. Там ти знайдеш моє бездушне тіло... Хоча я й шкодую про те, що мені потрібно тобі повідати, я не бачу іншого способу звільнитися від впливу племені Кривої Сосни.\n\nЩоб зробити це, тобі потрібно знищити мою фізичну форму. Як тільки закінчиш з цим завданням, скористайся оберегом вуду над моїм загиблим тілом. Коли завершиш, будь ласка, повертайся до мене.", [3] = "Обен Лютопазур хоче, щоб ви вбили його бездушне тіло, а потім застосували оберіг вуду.", [4] = "{Ім'я}, будь насторожі, наближаючися до моєї фізичної форми. Чари, якими вона окутана, досить потужні.", [5] = "Нарешті я вільний від впливу племені Кривої Сосни. Дякую, {Ім'я}.\n\nТепер мій дух може спокійно спочивати у Смарагдовому Сні.\n\nМожливо, одного дня ми зможемо зустрітися знову, {стать:юний:юна} {клас:к}. А поки що, будь ласка, візьми цю нагороду, як символ моєї подяки.", ["en"] = "Druid of the Claw", ["tasks"] = { ["Rageclaw"] = "Лютопазур", ["Rageclaw slain"] = "Лютопазур: убито" } },
    [26] = { [1] = "Необхідний урок", [2] = "{ім'я:к}, я з задоволенням спостерігав за твоїми успіхами. Ти безперечно станеш {стать:відомим захисником:відомою захисницею} природи.\n\nНастав час тобі дізнатись більше про один з аспектів тварин, здатність перетворюватись в яких дарував нам Кенарій. Про аспект, який дає тобі владу над водою. Для цього тобі потрібно відправитись в селище Нічна Гавань на Місячній галявині й поговорити з Дендритом Зіркосяйвом з Кенарійського Кола. Він буде твоїм наставником.", [3] = "Поговоріть з Дендритом Зіркосяйвом у селищі Нічна Гавань на Місячній галявині.", [5] = "Мої вітання, {стать:юний:юна} {клас:к}. Настав час тобі пізнати водну форму. В ній ти зможеш вільно і необмежено пересуватися у воді. Цей аспект буде для тебе корисним інструментом і благословінням... Але перш ніж опанувати це уміння, його потрібно заслужити.\n\nТебе чекає два випробування. Перше перевірить твою здатність працювати під тиском води. Друге — перевірить твою рішучість пізнати аспект самої форми.\n\nГотуйся — час випробування настав.", ["en"] = "A Lesson to Learn" },
    [262] = { [1] = "Таємничий незнайомець", [2] = "Мені потрібно дізнатись, ким був той таємничий незнайомець, якого я побачив у той день, коли мою родину вбили!\n\nБудь ласка, {ім'я}, ти вже {стать:продемонстрував:продемонструвала} свою винахідливість. Знайди того незнайомця. Мені потрібно дізнатись, які таємниці він приховує!\n\nЯ не знаю нічого, що не знаєш ти, але ось, візьми книгу, яку ти {стать:знайшов:знайшла} на моїй фермі. Можливо, хтось із мешканців міста зможе зв'язати цю книгу з її власником.", [3] = "Візьміть книгу, яку ви знайшли на фермі Свена, і покажіть її жителям Темнодолу.", [4] = "Якщо у тебе є щось, що належить таємничому незнайомцю, якого ти шукаєш, то покажи мені. Можливо, я зможу згадати щось про власника.", [5] = "Хмм... Хтось нещодавно тримав цю книгу в руках. Той, хто сповнений жадобою помсти. Але, на жаль, сліди на ній, принаймні сліди першого власника, ледь помітні.\n\nАле я можу сказати одне — справжній власник цієї книги не є жителем Темнодолу.", ["en"] = "The Shadowy Figure", ["tasks"] = { ["Book from Sven's Farm"] = "книга з ферми Свена", ["Book from Sven's Farm (Provided)"] = "книга з ферми Свена (видано)" } },
    [263] = { [1] = "На захист королівських земель", [2] = "Горянини розказують мені що ти {стать:сміливий:смілива} та {стать:здібний:здібна}, {ім'я}. Нам {стать:потрібен такий:потрібна така} {раса:н}, як ти. Ми ніяк не можемо справитись з трогами. Всі резерви відправлені на фронт, тож ми тут залишились без підтримки. Але тепер, коли у нас є {стать:загартований:загартована} в боях {клас:н}, ми можемо вистояти.\n\nЙди і вбий 10 шаманів Каменедробів та 10 кісткохрустів Каменедробів. Подивимось, чи правду про тебе кажуть, вбивця трогів.", [3] = "Горянин Стінолам з південної вартової вежі просить вас вбити 10 шаманів Каменедробів та 10 кісткохрустів Каменедробів.", [4] = "Так швидко? Якщо я не ясно виразивсь - ти маєш вбити 10 шаманів Каменедробів та 10 кісткохрустів Каменедробів, {ім'я}. Покажи їм, вбивця трогів!", [5] = "З першого погляду на тебе, {ім'я}, я зрозумів, що Залізогарт буде тобою пишатись. Ти гарно {стать:послужив:послужила} королю Маґні. Тепер, коли ти {стать:довів:довела} свою відданість королівству, тобі варто поговорити з капітаном. Можливо, він довірить тобі щось важливіше.\n\nХвала тобі, {ім'я}.", ["en"] = "In Defense of the King's Lands", ["tasks"] = { ["Stonesplinter Bonesnapper"] = "кісткохруст Каменедробів", ["Stonesplinter Bonesnapper slain"] = "кісткохруст Каменедробів: убито", ["Stonesplinter Shaman"] = "шаман Каменедробів", ["Stonesplinter Shaman slain"] = "шаман Каменедробів: убито" } },
    [265] = { [1] = "Продовження пошуку таємничого незнайомця", [2] = "Ось твоя книга, {ім'я}, і бажаю тобі успіху у пошуках. Якщо ти запитаєш інших мешканців міста, можливо, вони зможуть щось тобі сказати.\n\nІ ще одне — хоч автор цієї книги й не з нашого міста, та сама книга була придбана тут.", [3] = "Дізнайтеся, чи знають інші мешканці міста ще щось про таємничого незнайомця.", [4] = "Іноді я продаю чисті книги вченим і магам, або тим, хто хоче вести щоденник.\n\nЯ добре пам'ятаю кожного, кому продавав книги за останні кілька місяців...", [5] = "А, так. Я продав цю книгу одному сумнівному незнайомцю. Він не представився, але явно нервував, смикався, постійно оглядався через плече.\n\nСподіваюся, я зміг тобі допомогти...", ["en"] = "The Shadowy Search Continues", ["tasks"] = { ["Book from Sven's Farm"] = "книга з ферми Свена", ["Book from Sven's Farm (Provided)"] = "книга з ферми Свена (видано)" } },
    [266] = { [1] = "Розпитування в таверні", [2] = "Ось твоя книга, бажаю успіху у пошуках.\n\nРаджу зазирнути в таверну. Якщо той, кого ти шукаєш, перебував в місті, то є шанс, що хтось бачив його там.", [3] = "Обшукайте таверну, щоб знайти щось про таємничого незнайомця.", [4] = "Багряний Ворон вже не має такого попиту, як раніше, але до нас все ще заїжджають мандрівники.\n\nЯкщо ти зможеш описати того, кого шукаєш, то, можливо, я щось пригадаю.", [5] = "О, так, я пам'ятаю цю книгу. Її власник винаймав кімнату на кілька днів і проводив свої ночі в барі, пишучи.\n\nВін виїхав з міста поспішно, бурчачи про те, що його переслідує... щось. Востаннє я бачив його, коли він прямував на захід з міста, шукаючи нове місце, щоб сховатись.\n\nПерше місце на заході, де він міг би знайти притулок — Воронячий пагорб...", ["en"] = "Inquire at the Inn", ["tasks"] = { ["Book from Sven's Farm"] = "книга з ферми Свена", ["Book from Sven's Farm (Provided)"] = "книга з ферми Свена (видано)" } },
    [267] = { [1] = "Загроза трогів", [2] = "{Клас:к}, не знаю, чи {стать:чув:чула} ти про загрозу, що нависла над землями дворфів. Резерви Залізогарта відправились на фронт, а ми залишились лиш з невеликою частиною сил необхідних для захисту наших земель. Моєму полку наказали охороняти Ворота і ми не можемо покинути наші позиції, остерігаючись вторгнення.\n\nАле ми маємо посилити натиск на цих клятих трогів, що бродять по долині. Якщо тобі під силу ця задача - влаштуй трогам облогу. Принеси мені 8 кам'яних зубів трогів як доказ.", [3] = "Принесіть 8 кам'яних зубів трогів капітану Руґельфузу в південну вартову вежу.", [4] = "Ти {стать:приніс:принесла} мені 8 кам'яних зубів трогів? Якщо ні - тобі є чим зайнятись, {ім'я}.", [5] = "Ти {стать:вразив:вразила} мене, {ім'я}. Ти {стать:зробив:зробила} велику послугу дворфам, захищаючи наші землі. Сам король Маґні Бронзобородий пишався б!", ["en"] = "The Trogg Threat", ["tasks"] = { ["Trogg Stone Tooth"] = "кам'яний зуб трога", ["Trogg Stone Tooth (Provided)"] = "кам'яний зуб трога (видано)" } },
    [268] = { [1] = "Повернення до Свена", [2] = "Книгу, яку ти {стать:знайшов:знайшла}, було закінчено тільки наполовину. Я мусив лишити її на фермі Свена, коли втікав...\n\nОсь, візьми мій завершений щоденник і віднеси Свену. Він детальніше описує події на фермі.\n\nХоча цей щоденник був єдиним моїм співрозмовником протягом останніх тижнів, я охоче розлучуся з ними, аби не вставати на шляху Свена і його гніву!", [3] = "Поверніться до Свена із заповненим щоденником Тремтінія.", [4] = "Ти {стать:з'ясував:з'ясувала}, хто цей таємничий незнайомець?", [5] = "Цей щоденник багато чого пояснює. Тепер мені ясно, що слід шукати темних вершників! Я бачив їх вершників у Смерколіссі та бачив, як вони розмовляли з чаклуном Морбентом Скверном у Закинутій садибі.", ["en"] = "Return to Sven", ["tasks"] = { ["Jitters' Completed Journal"] = "заповнений щоденник Тремтінія", ["Jitters' Completed Journal (Provided)"] = "заповнений щоденник Тремтінія (видано)" } },
    [269] = { [1] = "У пошуках мудрості", [2] = "Відправляйся в Штормовій і поговори з єпископом Фартингом в соборі Світла. Дай йому щоденник Тремтінія і скажи, що збираєшся кинути виклик Морбенту Скверну.\n\nХоча Штормовій відрікся від Темноділу, Фартинг — добродушний та дуже мудрий. Він може допомогти тобі врятувати нас.\n\nТвоє завдання небезпечне, але поспіши, {ім'я}. З кожною годиною, тіні Смерколісся стають ще темнішими.", [3] = "Передайте заповнений щоденник Тремтінія єпископу Фартингу в Штормовій.", [4] = "Відпочинь, {стать:брате:сестро}. Я бачу, що ти {стать:пройшов:пройшла} довгий шлях і на тобі важкий тягар. Скажи, що за тінь упала на тебе?", [5] = "<Після прочитання щоденника та почутого про ваш намір...>\n\nЗло проникло в і без того оточене з усіх боків Смерколісся. Хвала Світлу, що {стать:знайшовся герой:знайшлася героїня} на кшталт тебе, що зможе протистояти йому.\n\nАле ти {стать:повинен:повинна} підготуватися до майбутнього випробування... Оскільки некромант Морбент Скверн надзвичайно сильний, та наклав чорну магію на себе, щоб захиститися від фізичних атак. Якщо ти хочеш перемогти його, тобі потрібна зброя, здатна пробити цей захист.", ["en"] = "Seeking Wisdom", ["tasks"] = { ["Jitters' Completed Journal"] = "заповнений щоденник Тремтінія", ["Jitters' Completed Journal (Provided)"] = "заповнений щоденник Тремтінія (видано)" } },
    [270] = { [1] = "Приречена флотилія", [2] = "Багато років тому на узбережжі Заболоття, величезного болота на північ від дворфського королівства Залізогарт, потонула Третя флотилія Кул-Тіраса. На одному з кораблів був вантаж зі злитками світлосталі.\n\nЦей метал є дорогоцінним для нас, оскільки речі, створені з нього, уражають ворогів силою святої істини. Якщо ти збираєшся кинути виклик Морбенту Скверну, тобі потрібна саме така зброя.\n\nЙди до гавані Менітілів та звернись до мого колеги, дворфа Ґлоріна Сталеброва. Якщо цей загублений метал можна знайти, він точно має знати, де почати шукати.", [3] = "Ідіть до гавані Менетілів в Заболоття і поговоріть з Ґлоріном Сталебровом.", [5] = "Світлосталь — дорогоцінний метал, але, здається, твоє завдання не з простих. Ти {стать:зайшов:зайшла} далеко, {стать:брате:сестро}. Якщо тобі дуже пощастить, ти зможеш знайти те, що шукаєш!\n\nА коли роздобудеш метал — я знаю, хто зможе викувати зброю проти того некроманта в Смерколіссі, про якого ти говориш.", ["en"] = "The Doomed Fleet" },
    [272] = { [1] = "Випробування морського лева", [2] = "Для другого випробування тобі потрібно зібрати дві половини підвіски морського лева. Одна з половинок уособлює спритність аспекту морського лева, що стрімко плаває в товщі води. Інша ж — уособлює його неймовірну витривалість. Друїди покладаються на обидві ці якості, щоб опанувати водну форму.\n\nПоговори з жителями Місячної галявини, щоб дізнатись, де знаходяться ці половинки та принеси їх сюди. Коли об'єднаєш їх — віддай підвіску Дендриту Зіркосяйву.", [3] = "Знайдіть половинку підвіски водної спритності та половинку підвіски водної витривалості. Поговоріть з жителями Місячної галявини, щоб дізнатись про їх місцеперебування.\n\nОб'єднайте половинки в підвіску морського лева, перебуваючи біля вівтаря Ремула.\n\nОб'єднану підвіску принесіть Дендриту Зіркосяйву в Нічну Гавань, що на Місячній галявині.", [4] = "Ти вже {стать:об'єднав:об'єднала} половинки підвіски, {ім'я:к}? Якщо тобі потрібна допомога — звернись до місцевих жителів. Так ти не тільки дізнаєшся, де їх шукати, а й краще познайомишся з цією прекрасною священною галявиною.", [5] = "Тобі вдалось пройти випробування морського лева, {ім'я:к}, вітаю тебе!\n\nУ своїх зусиллях з їх пошуків тобі довелось проявити спритність та витривалість, які так необхідні тобі для гармонії з водними глибинами. Одне не може існувати без іншого і без обох цих якостей ти не зможеш прийняти аспект морського лева.\n\nДобре запам'ятай цей урок і згадуй про нього, коли наважишся прийняти водну форму.", ["en"] = "Trial of the Sea Lion", ["tasks"] = { ["Pendant of the Sea Lion"] = "підвіска Морського Лева", ["Pendant of the Sea Lion (Provided)"] = "підвіска Морського Лева (видано)" } },
    [273] = { [1] = "Постачання експедиції", [2] = "Ще не пізно, ти можеш наздогнати Гулдара. Вони не могли далеко відійти. Хай якими дужими не були Міран та Саян, вони не надто жваво рухатимуться з вантажем діжок.\n\nВони пішли звичною дорогою до розкопок - на південь від міста, вздовж берега.\n\nЗнайти їх буде не складно, якщо вони ще не дійшли.", [3] = "Поговоріть з Гулдаром.", [5] = "Хм, якомусь нікчемному Темному Залізу не вдасться зірвати наші поставки!\n\nАле Саян... Ніколи б не подумав, що він може бути їх спільником. Я з ним майже рік працював... Мабуть, я був надто довірливим.\n\nЩо ж, розберусь з цим пізніше.", ["en"] = "Resupplying the Excavation", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Find Huldar, Miran, and Saean"] = "Знайдіть Гулдара, Мірана та Саяна" } },
    [274] = { [1] = "Темна загроза", [2] = "Це не звичайна вибухівка. Подивись на ці срібні кристалики. І характерний запах! Ясно ж як день - це ж сифорій. Сам по собі він загрози не становить. Але якщо намокне - здатен висадити в повітря Залізогарт!\n\nХімічну реакцію можна нейтралізувати, змішавши чотири компоненти: отруту павука, розтовчений кристал Мо'ґрош, сльоза кроколіска та оцей нейтралізуючий колоїд. Біжи розкажи це Греблеру, доки не пізно!", [3] = "Поверніться до старшого інженера Греблера з інформацією від Ашлана Камнесміха.", [4] = "Що сказав Ашлан?", [5] = "Нейтралізуючий колоїд? Для сифорія? О, небеса!", ["en"] = "A Dark Threat Looms", ["tasks"] = { ["Disarming Colloid"] = "нейтралізуючий колоїд", ["Disarming Colloid (Provided)"] = "нейтралізуючий колоїд (видано)" } },
    [2745] = { [1] = "Проникнення в замок", [2] = "Хм, цікава історія, і її не можна сприймати легковажно. Так, я можу тобі допомогти, але доведеться здійснити правосуддя... не зовсім законним шляхом, якщо ти хочеш довести це до кінця.\n\nЗ Лесковаром і Марзоном потрібно розібратися, і швидко. Як думаєш, ти зможеш це зробити?\n\nТобі вирішувати. Якщо так, то поспішай до замку і знайди мого старого друга, гнома, на ім'я Тіріон. Він вже кілька тижнів спостерігає за Лесковаром і має допомогти тобі покінчити з цим.", [3] = "Поговоріть з Тіріоном у замку Штормовія.", [5] = "Що за...?! Не підкрадайся так до мене! І тихше! Чому, в ім'я Тіні, ти підкрадаєшся до мене? Хіба ти не бачиш, що я зайнятий, дурило?\n\nВ сенсі, що я роблю? Чекаю, поки знову відкриється Темний портал звісно, як ти думаєш, що я роблю? Говори скоріш і йди собі... поки ті сторожі не помітили, що ми тут вдвох ховаємось в кущах. Я не можу дозволити, щоб мене викрили.", ["en"] = "Infiltrating the Castle" },
    [2746] = { [1] = "Речі з наслідками", [2] = "Тріас хоче трохи поквапити події, га? Гаразд, ми можемо це зробити, але я ще не готовий. І знай, я роблю всю важку роботу, але тобі доведеться забруднити руки, {стать:зрозумів:зрозуміла}? Добре.\n\nГаразд, мені потрібно, щоб ти {стать:приніс:принесла} мені кілька речей, перш ніж я зможу втілити свій план. У мене є ідеальне маскування, яке дозволить роботу-шпигуну пройти повз цих охоронців.\n\nПринеси мені шовк і пару яблук. Шовк шукай {стать:сам:сама}, а от яблука підхожого розміру ти знайдеш на маленькій фермі Клари прямо за містом.", [3] = "Принесіть Тіріону в Штормовій 3 шовкових полотна та 2 свіжих яблука Клари.", [4] = "Я спостерігаю за Лесковаром вже кілька тижнів. Тріас ніколи йому не довіряв, але ми й не підозрювали, що він пов'язаний з Братством Непокірних. Ми шукали докази його зв'язків з Сутінковим Молотом. У будь-якому випадку він став занадто небезпечним для цього міста, тому ми й втрутились.\n\nПринеси мені ці речі, і ми зможемо втілити мій план.", [5] = "Ці підходять, {ім'я}. Чудова робота.\n\nУ мене в рюкзаку є решта необхідного спорядження... дякувати Світлу, я попросив свого друга кравця пошити мені шовкову сумку. Мені не вистачало місця для всього мого спорядження.\n\nПерш ніж ми запустимо робота-шпигуна, обговорімо деталі, щоб ти не {стать:розгубився:розгубилась}.", ["en"] = "Items of Some Consequence", ["tasks"] = { ["Clara's Fresh Apple"] = "свіже яблуко Клари", ["Clara's Fresh Apple (Provided)"] = "свіже яблуко Клари (видано)", ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [2758] = { [1] = "Походження ковальства", [2] = "Коли я був приблизно десь твого віку, дворф, на ім'я Ґальван прийняв мене під своє крило і навчив кувати обладунки. Перед тим, як він вирушив до Грабіжної Бухти, він взяв з мене обіцянку навчати всіх, хто має бажання і наполегливість розвиватися в ковальському ремеслі. Отже, ось я — стримую цю обіцянку.\n\nТепер час навчити тебе. Виготов мені шість пар золотих лускатих браслетів і ти дізнаєшся, звідки походить ковальське мистецтво, {ім'я}.", [3] = "Принесіть шість пар золотих лускатих браслетів Хенку Молоту в Штормовій.", [4] = "Ти {стать:міг би:могла б} стати {стать:наступником:наступницею} Ґальвана!", [5] = "Дуже добре, {ім'я}! Слухай і вчися.\n\nКовальство ніколи не походить звідси! <Хенк вказує на молот.>\n\nКовальство ніколи не походить звідси! <Хенк вказує на ковадло.>\n\nКовальство походить тільки звідси! <Хенк вказує собі на серце.>\n\nТепер ти знаєш походження ковальства.", ["en"] = "The Origins of Smithing", ["tasks"] = { ["Golden Scale Bracers"] = "золоті лускаті браслети", ["Golden Scale Bracers (Provided)"] = "золоті лускаті браслети (видано)" } },
    [2759] = { [1] = "В пошуках Ґальвана", [2] = "Хоча Ґальван і покинув Грабіжну Бухту багато років тому, члени ордену все ще знаходяться в місті, сподіваючись знайти когось, гідного уваги Ґальвана.\n\nВізьми цю печатку і передай її Макґавану в Грабіжній Бухті.\n\nЯкщо ти дійсно дійдеш туди, він зрозуміє, що ти {стать:гідний:гідна}. Я вірю в тебе, {ім'я}!", [3] = "Поговоріть з Макґаваном в Грабіжній Бухті.", [4] = "Оце тебе занесло, {стать:приятелю:приятелько}. Дай-но мені поглянути на цю печатку.", [5] = "Клянуся гривою Чорного Копита — нарешті, хтось {стать:гідний:гідна} ордену мітрилу!", ["en"] = "In Search of Galvan", ["tasks"] = { ["Mithril Insignia"] = "мітрилова печатка", ["Mithril Insignia (Provided)"] = "мітрилова печатка (видано)" } },
    [276] = { [1] = "Бродячі лапи", [2] = "Мохошкурі гноли багато років жили мирно в Заболотті, але тепер вони розплодились. Вони витолочують своїми лапами луги, а мерзенними сокирами - вирубують надто багато дерев, щоб палити вогнища.\n\nВони більше не в гармонії з природою. Гнолів має бути менше, щоб Заболоття вижило.\n\nВбий 15 мохошкурих гнолів та 10 мохошкурих дворняг. Вони водяться на півдні, біля дворфійських воріт Альґазу. Як зробиш це - повертайся до мене.", [3] = "Вбийте 15 мохошкурих гнолів та 10 мохошкурих дворняг, після чого поверніться до Ретіля Вартового Природи в Заболоття.", [4] = "Ти ще не {стать:виконав:виконала} своє завдання, {клас:к}.", [5] = "Зменшивши поголів'я гнолів, ти {стать:подарував:подарувала} Заболоттю надію на зцілення. Хай я зневірився в тобі подібних раніше, {раса:к}, але ще не все втрачено.", ["en"] = "Tramping Paws", ["tasks"] = { ["Mosshide Gnoll"] = "мохошкурий гнол", ["Mosshide Gnoll slain"] = "мохошкурий гнол: убито", ["Mosshide Mongrel"] = "мохошкура дворняга", ["Mosshide Mongrel slain"] = "мохошкура дворняга: убито" } },
    [2769] = { [1] = "Брати Латуноболти", [2] = "Ти вже {стать:знайомий:знайома} з братами Латуноболтами? Вони на Мерехтливих рівнинах, що в Калімдорі, ганяють на своїх машинах-ракетах проти гоблінів. Зазвичай вони перемагають, що не дивно — машини гоблінів вибухають так часто, що рідко перетинають фінішну лінію!\n\nАле брати Латуноболти все одно шукають нові способи зробити свою машину швидшою, і Віззл сказав мені, що йому потрібні рідкісні компоненти для його чергових експериментів.\n\nЙому явно потрібна допомога. Поговори з ним про це.", [3] = "Поговоріть з Фіззлом Латуноболтом на Мерехтливій рівнині.", [5] = "А, то ти хочеш допомогти мені? Чудово!\n\nМені для експерименту потрібна одна штука, і {стать:такий сміливий:така смілива} {клас:н}, як ти, добуде її без зусиль!", ["en"] = "The Brassbolts Brothers" },
    [279] = { [1] = "Загроза з глибин", [2] = "Мурлоки лізуть з морських глибин і будують свої поселення на узбережжі. Вони нападають на наших рибалок і торговців, ми маємо це зупинити.\n\nОдин з них, Жерун, прокрадається з іншими синьожабрими мурлоками до дороги і влаштовує засідки на наших торговців. І кожного разу вони втікають до своїх хиж, де ми їм нічого не можемо зробити. Наші торговці в небезпеці і ми готові заплатити за їх захист.\n\nЖерун бродить в затоці річки на північ звідси. Знайти його, знищи його плем'я і принеси мені його голову.", [3] = "Вбийте 12 синьожабрих мурлоків.\n\nУбийте Жеруна та заберіть його голову.\n\nПринесіть голову Жеруна Карлу Борану в гавань Менетілів.", [4] = "Наші торговці будуть в небезпеці, поки ми не позбавимось Жеруна і цих мурлоків.", [5] = "Ах, чудово {ім'я}.\n\nПрийми цю оплату за виконання угоди з торговим флотом.", ["en"] = "Claws from the Deep", ["tasks"] = { ["Bluegill Murloc"] = "синьожабрий мурлок", ["Bluegill Murloc slain"] = "синьожабрий мурлок: убито", ["Gobbler's Head"] = "голова Жеруна", ["Gobbler's Head (Provided)"] = "голова Жеруна (видано)" } },
    [281] = { [1] = "Повернення товарів", [2] = "Нещодавно мурлоки напали на торгове судно \"Сліпа принцеса\". Хоч корабель і не постраждав, ці потвори стягнули велику частину вантажу, зокрема дуже цінну статуетку Теренаса Менетіла. Ми маємо повернути її.\n\nОбшукай прибережні поселення мурлоків. Ящики, бочки - все, що схоже на вкрадений вантаж. Знайди статуетку Менетіла і поверни її мені.", [3] = "Обшукайте ящики та бочки в прибережних таборах мурлоків.", [5] = "Цей ящик звогчів, він весь вкритий слідами від кігтів. Відкривши його, всередині ви бачите розмоклу гнилу солому, що може означати, що всередині лежить щось цінне. Ви розгрібаєте солому...\n\n...і знаходите кілька червоних пляшечок.", ["en"] = "Reclaiming Goods" },
    [282] = { [1] = "Спостереження Сеніра", [2] = "Я збирався відправити свого учня до мого брата Сеніра зі звітом, але мені буде спокійніше, якщо довірю його в надійні руки. Якщо ти, звісно, не проти.\n\nХмм... Щоб дістатись Хараноса, тобі доведеться пройти по тунелю.\n\nПеред тим, як відправишся, поговори з горянином Талосом. Тунель кишить трогами.\n\nПовертайся до Ковмару, після чого йди на схід. Талос стоїть поруч із тунелем.", [3] = "Поговоріть з горянином Талосом.", [4] = "Вітаю! Будь {стать:обережний:обережна}, {Ім'я}, тунель до Дун-Морога кишить трогами, тож йти по ньому небезпечно.\n\nЯкщо в тебе немає невідкладних справ у Дун-Морозі, я попрошу тебе залишитись в Ковмарі, поки не стане безпечніше.", [5] = "Хм, отож, якщо Білобород посилає тебе до Дун-Морога з важливим дорученням, то не мені тебе зупиняти, правда ж?\n\nПринаймні, дозволь мені дати тобі кілька порад.", ["en"] = "Senir's Observations", ["tasks"] = { ["Grelin's Report"] = "звіт Ґреліна", ["Grelin's Report (Provided)"] = "звіт Ґреліна (видано)", ["Speak with Mountaineer Thalos."] = "Поговоріть із горянином Талосом." } },
    [2821] = { [1] = "Знак якості", [2] = "Моя філософія роботи зі шкірою полягає в тому, що робота повинна бути максимально якісною — жодних компромісів. Той, хто каже, що якість не має значення, намагатиметься продати тобі нерухомість в Дун-Морозі з видом на море!\n\nУ своєму нещодавньому пошуку високоякісних матеріалів, я натрапив на товсті шкури єті. Єті Фераласа можна знайти на заході звідси, в долині Лихий Шрам. Я дам тобі на вибір один з моїх шкіряних виробів за десять шкур. Якщо це звучить для тебе прийнятно, тоді до справи.", [3] = "Принесіть 10 товстих шкур єті Пратту Макґруббену в фортецю Перомісяць.", [4] = "Десять товстих шкур єті дасть тобі змогу отримати один з моїх виробів. Оскільки я дбаю про якість, я можу гарантувати, що ти отримаєш гарну річ!\n\nЯкщо ти не можеш знайти єті, я тобі підкажу де їх знайти. Спробуй пошукати на заході звідси, біля Забутого узбережжя, поруч з долиною Лихий Шрам", [5] = "Ти {стать:бачив:бачила} текстуру цих шкур? Якщо їх правильно обробити, вони цілком можуть бути міцнішими за залізо. Мало хто знає про ці шкури, і в поєднанні з широким спектром моїх рішень для їх обробки це дозволить мені потенційно виготовляти речі незрівнянної якості... завдяки тобі, звичайно ж!\n\nА тепер, будь ласка, {ім'я}, обирай будь-який з моїх виробів!", ["en"] = "The Mark of Quality", ["tasks"] = { ["Thick Yeti Hide"] = "товста шкура єті", ["Thick Yeti Hide (Provided)"] = "товста шкура єті (видано)" } },
    [284] = { [1] = "Пошуки продовжуються", [2] = "Ви ретельно обшукуєте поселення мурлоків, і не знаходите жодного сліду статуетки Менетіла.\n\nМожливо, варто пошукати в поселеннях на півночі та північному заході.", [3] = "Пошукайте статуетку Менетіла.", [5] = "Схоже, цю бочку не чіпали. Ви її відкриваєте...\n\n...і відчуваєте різкий запах сиру. Трохи промоклий, але все ще смачний!", ["en"] = "The Search Continues" },
    [285] = { [1] = "Обшукати більше хатин", [2] = "Ви обшукали це поселення мурлоків, але нічого не знайшли.\n\n...але ви впевнені, що ціль вже близько.\n\nСтатуетка Менетіла має бути в одному з поселень на півночі!", [3] = "Продовжуйте шукати статуетку Менетіла в поселеннях мурлоків.", [5] = "Ця бочка наполовину зарита в багнюку й траву...", ["en"] = "Search More Hovels" },
    [286] = { [1] = "Повернення статуетки", [2] = "Витягнувши бочку з багнюки та відкривши її, ви знаходите серез соломи срібну статуетку. Вона зображує молодого, довговолосого паладина, з піднятим над головою молотом.\n\nПевно, це статуетка Менетіла! Тепер її варто повернути Карлу Борану в гавань Менетілів.", [3] = "Принесіть Карлу Борану статуетку Менетіла.", [4] = "Ти {стать:приніс:принесла} статуетку?", [5] = "Капітан \"Сліпої принцеси\" неабияк зрадіє, коли дізнається про повернення такого цінного вантажу. Ти заслуговуєш на гідну винагороду за свою допомогу.\n\nПриємно знати, що є такі надійні люди, на яких можна покластись. Особливо, в такі важкі часи.", ["en"] = "Return the Statuette", ["tasks"] = { ["Menethil Statuette"] = "статуетка Менетіла", ["Menethil Statuette (Provided)"] = "статуетка Менетіла (видано)" } },
    [2866] = { [1] = "Руїни Солесонця", [2] = "На південь від нас знаходяться руїни Солесонця. Це руїни дуже древнього міста. Ми вже обстежили їх, але не знайшли нічого важливого, тому залишили їх.\n\nОднак нещодавно в цих руїнах оселилися наги Гребеня Ненависті, причому в загрозливій кількості. Спершу ми вирішили, що вони готують напад. Можливо, вони його справді готують, але нам здається, що там відбувається щось ще.\n\nЙди туди, досліди руїни та зверни увагу на все, що здасться підозрілим. Удачі, {ім'я}.", [3] = "Дослідіть руїни Солесонця і перевірте, чи є там наги.", [5] = "Оглядаючи альтанку, ви виявляєте кілька незвичайних речей, що контрастують з навколишніми руїнами.\n\nПо-перше, альтанка виглядає новішою за інші об'єкти в руїнах. По-друге, на стінах альтанки видно невелику послідовність гліфів, вони повторюються, але що це за письмена і що вони означають, вам незрозуміло. Ну і, по-третє, камінь альтанки — теплий на дотик.\n\nТак, все це, безперечно, підозріло!", ["en"] = "The Ruins of Solarsal" },
    [2867] = { [1] = "Повернення у фортецю Перомісяць", [2] = "Тепер, коли ви виявили дивну альтанку в самому серці руїн Солесонця, настав час повернутися до фортеці Перомісяць і повідомити генерала Шандрісу Перомісяць про вашу знахідку.", [3] = "Поверніться до Шандріси Перомісяць у фортецю Перомісяць і повідомте про свої знахідки.", [5] = "З поверненням, {ім'я}. Виявлена тобою альтанка справді вельми... підозріла. Очевидно, що навіть якщо наги й не замишляють напад, їхня присутність не означає для нас нічого доброго. Ну, хай там як, ось твоя заслужена нагорода за розслідування.\n\nЗдається, фортеця Перомісяць гостро потребує допомоги для боротьби з нагами Гребеня Ненависті. Я хотіла б запропонувати тобі це завдання, якщо ти не проти. Роботи багато.", ["en"] = "Return to Feathermoon Stronghold" },
    [2869] = { [1] = "Боротьба з кланом Гребеня Ненависті", [2] = "Наразі найрозумніше — розраховувати на те, що наги у будь-якому разі спробують захопити острів. І нам потрібно запобігти цій загрозі, поки не стало занадто пізно.\n\nПринеси мені десять лусок наг з клану Гребеня Ненависті. Як їх добути — думаю, зрозуміло? У тебе буде нагода пополювати на наг, а кількість їх воїнів на острові Сардор зменшиться — і те, й інше нам на користь!", [3] = "Принесіть 10 лусок наг Гребеня Ненависті Латроніку Місяцеспису у фортецю Перомісяць.", [4] = "{ім'я}, якщо ти {стать:прийшов:прийшла}, щоб уточнити завдання, яке тобі дали, то мені потрібно десять лусок наг з клану Гребеня Ненависті. А якщо ти тут, щоб потеревенити, то мені зараз не до цього.\n\nЗнай, що ми, нічні ельфи — народ мирний. Ми прагнемо лише до збереження миру та гармонії. Однак це не означає, що ми не будемо захищати свої власні інтереси. Це мій обов'язок перед генералом Перомісяць і перед усією фортецею.", [5] = "Так, ця луска згодиться. Думаю, ми відправимо її Пратту. Можливо, він зуміє виготовити з неї що-небудь корисне.\n\nА для тебе в мене є ще одне завдання. Але спочатку ось твоя винагорода за луски. Твоя постійна служба генералу та всій фортеці Перомісяць дуже цінна перед лицем небезпеки, що загрожує нам.", ["en"] = "Against the Hatecrest", ["tasks"] = { ["Hatecrest Naga Scale"] = "луска наги Гребеня Ненависті", ["Hatecrest Naga Scale (Provided)"] = "луска наги Гребеня Ненависті (видано)" } },
    [287] = { [1] = "Поселення Морозогривих", [2] = "Я не встигаю зі звітом і мені б не завадила твоя допомога, {ім'я}. Мені вдалося дізнатись, де засіли тролі, але там їх було стільки, що я побоявся туди лізти.\n\nОсь що мені потрібно... Іди в печеру, понишпор там, прибий кілька тролів і повертайся до мене.\n\nВирушай з Хараноса по дорозі на північ, коли дістанешся до мосту, йди на захід по замерзлій річці, поки не дістанешся озера Кригохвиля. На західному березі стоїть селище Всезвар. Поселення тролів знаходиться на південний захід від нього.", [3] = "Обстежте поселення Морозогривих і вбийте 5 мисливців за головами Морозогривих на прохання Сеніра Білоборода з Хараноса.", [4] = "{стать:Заблукав:Заблукала}? Мої вказівки були вельми зрозумілі! У нас мало часу, тобі треба поспішати! Не повертайся, поки не знайдеш печеру.", [5] = "А, {ім'я}! Я так і думав, що тобі буде нескладно знайти це місце, адже мої вказівки були бездоганні...\n\nДай-но мені закінчити свій звіт.\n\n\nОсь! Ха-ха, тепер це зовсім кумедно... Гадаю, {ім'я}, ти не відмовишся зробити для мене останню послугу?", ["en"] = "Frostmane Hold", ["tasks"] = { ["Frostmane Headhunter"] = "морозогривий мисливець за головами", ["Frostmane Headhunter slain"] = "морозогривий мисливець за головами: убито", ["Fully explore Frostmane Hold"] = "Повністю дослідіть поселення Морозогривих", ["slain"] = "убито" } },
    [2870] = { [1] = "Вбити лорда Шалзару", [2] = "{ім'я}, ми отримали нові повідомлення від розвідників, і тепер непогано уявляємо собі, як влаштовано військо наг. Найвище командування складається з осіб королівської крові, які приймають всі рішення.\n\nЗокрема, ми впізнали одного з жорстокіших наг — лорда Шалзару. Розвідка повідомляє, що саме він знайшов таємничу реліквію під час останніх розкопок наг в печері на південь від головних руїн на острові Страховищ.\n\nЗупини лорда Шалзару та принеси мені його реліквію, щоб ми могли її дослідити.", [3] = "Убийте лорда Шалзару, а потім принесіть знайдену ним таємничу реліквію Латроніку Місяцеспису в фортецю Перомісяць.", [4] = "Вбивство лорда Шалзару точно відсунуло б їх плани назад на кілька тижнів, якщо не місяців. Крім того, реліквія, яку він знайшов, безумовно, цікава для нас.\n\nТи {стать:виконав:виконала} завдання, {ім'я}?", [5] = "Чудова робота, {ім'я}! Загибель лорда Шалзару наги запам'ятають надовго. Тепер вони становлять значно меншу загрозу, ніж раніше, і все це — завдяки тобі!\n\nОсь тобі ще нагорода зі скарбниці фортеці — ти {стать:заробив:заробила} кожен мідяк. Тобі та твоїм друзям завжди будуть раді у фортеці Перомісяць, {стать:друже:подруго}.\n\nІ перш ніж ти підеш, {ім'я}... ще одне прохання...", ["en"] = "Against Lord Shalzaru", ["tasks"] = { ["Mysterious Relic"] = "таємнича реліквія", ["Mysterious Relic (Provided)"] = "таємнича реліквія (видано)" } },
    [2871] = { [1] = "Доставка реліквії", [2] = "Якби ти {стать:допоміг:допомогла} віддати реліквію моїй дружині Вестії, я був би дуже вдячний. Вона не тільки поважна жриця нашої громади, але й одна з найкращих учених, яких я знаю. Я особисто не зрозумів би, що це за штука... Але якщо моя дружина в ній не розбереться, значить, не розбереться ніхто...\n\nВона тут, неподалік. Напевне, вивчає щось. Дякую, {ім'я}.", [3] = "Доставте таємничу реліквію Вестії Місяцеспису у фортецю Перомісяць.", [4] = "Так, чим я можу допомогти тобі?\n\nЗачекай, ти ж {стать:той:та} {клас}, {стать:який:яка} допомагає генералу Перомісяць та Латро з боротьбою проти наг, чи не так? Я — Вестія, дружина Латро — точніше, Латроніка. Дуже приємно з тобою познайомитися!\n\nВибач, у тебе, мабуть, важлива справа. Ти {стать:приніс:принесла} щось від нього?", [5] = "Дивно... Ти кажеш, що ця знахідка була у руїнах Солесонця? Ну, Латро правий, що мені потрібно на це подивитись. Таке враження, що ця річ — не звідти. З іншого боку, на роботу наг це теж не схоже... Точно не щось настільки чуже.\n\nМені знадобиться деякий час, щоб дослідити цей предмет. Коли я закінчу дослідження, можливо, я скористаюся твоїми послугами, якщо ти будеш поблизу.\n\nОсь, візьми один з цих предметів. Сподіваюся, ти знайдеш йому використання!", ["en"] = "Delivering the Relic", ["tasks"] = { ["Mysterious Relic"] = "таємнича реліквія", ["Mysterious Relic (Provided)"] = "таємнича реліквія (видано)" } },
    [2877] = { [1] = "Зачистка Замаскованої печери", [2] = "Ми, Дикі Молоти, пам'ятаємо минуле більше, ніж наші брати з Залізогарту. Якщо хочеш мати тут друзів, то ти {стать:повинен:повинна} забруднити свої руки заради нас!\n\nОрда залишила свої позиції в Внутрішніх землях біля Замаскованої печери, і тепер там повно гидких шламів та слизнів. У нас є плани на цю територію, але спочатку нам потрібно очистити територію.\n\nОсь це, власне, й твоє завдання, сонечко! Йди туди та знищ десять зелених шламів та десять нефритових слизнів, а потім повертайся до мене. Рухайся!", [3] = "Убийте 10 зелених шламів і 10 нефритових слизнів, а потім поверніться до Фраґґара Громовержця на Орлиний пік.", [4] = "Не намагайся ухилитися від виконання цього звдання, {раса:к}! Якби боги хотіли вбити цих виплодків, вони б уже зробили це, чи не так?!", [5] = "Поглянь на себе, допомагаєш Диким Молотам! Ти дійсно {стать:дієвий:дієва} {клас}, а дія — це те, що ми поважаємо.\n\nТвоє завдання з прибирання території набагато важливіше, ніж може здаватись. З людьми, які позбавляють нас від шламів та слизнів, ми зможемо розширити наш вплив. Ось, візьми щось на додачу до того, що ти {стать:здобув:здобула} нових друзів на Орлиному піку!", ["en"] = "Skulk Rock Clean-up", ["tasks"] = { ["Green Sludge"] = "зелений шлам", ["Green Sludge slain"] = "зелений шлам: убито", ["Jade Ooze"] = "нефритовий слизень", ["Jade Ooze slain"] = "нефритовий слизень: убито" } },
    [288] = { [1] = "Третя флотилія", [2] = "Колись я був першим помічником на «Володарці хвилі», лінійному кораблі Третьої флотилії Кул-Тірасу. Приреченій флотилії. Приреченій, бо під час свого останнього плавання на кораблі напали червоні дракони. Якими керували орки!\n\nУ нас не було жодного шансу проти полум'я драконів... і наш флот був спалений і потоплений біля цього узбережжя. Я єдиний, хто вижив в цьому жаху...\n\n...Ох, як же гуде голова! Мені треба щось випити, якщо я хочу впоратися з цим похміллям і продовжити розповідь.", [3] = "Купіть першому помічнику Фіцсіммонсу кружку медовухи.", [4] = "Ох, як же хочеться пити! Не пригостиш випивкою бідного, дурного нікчему?", [5] = "Ух, те, що треба! І голова не гуде, і язику легше. Дякую, {стать:приятелю:приятелько}!", ["en"] = "The Third Fleet", ["tasks"] = { ["Flagon of Mead"] = "Глегін з медом", ["Flagon of Mead (Provided)"] = "Глегін з медом (видано)", ["Flagon of Mead slain"] = "Глегін з медом: убито" } },
    [2880] = { [1] = "Нагорода за намисто тролів", [2] = "Прояснімо, {раса:к} — ми НЕ є частиною Альянсу! Клан Диких Молотів незалежний, ми вважаємо, що заслуги та дії визначають нашу цінність, а не порожні балачки!\n\nЯкщо ти шукаєш тут друзів, то спочатку доведи чого вартуєш! Ті брудні тролі, що заполонили пагорби Внутрішніх земель носять племінні намиста. Принеси мені п'ять таких намист, і ми підемо тобі назустріч.", [3] = "Принесіть 5 племінних намист тролів Фраґґару Громовержцю на Орлиний пік.", [4] = "Мені потрібно п'ять племінних намист, які носять ці тролі. Якщо незрозуміло, то поясню: найпростіше зняти намисто з мертвого троля!\n\nДоведи, що ти {стать:вартий:варта} Диких Молотів!", [5] = "Ось про що я говорю! Бачиш — ці намиста доводять, що ти {стать:готовий:готова} забруднити руки. Ми, Дикі Молоти, цінуємо це в тих, з ким співпрацюємо.\n\nПродовжуй в тому ж дусі й заслужиш нашу повагу.", ["en"] = "Troll Necklace Bounty", ["tasks"] = { ["Troll Tribal Necklace"] = "племінне намисто тролів", ["Troll Tribal Necklace (Provided)"] = "племінне намисто тролів (видано)" } },
    [289] = { [1] = "Проклята команда", [2] = "<Освіжившись, Фіцсіммонс продовжує свою розповідь...>\n\nЯ єдиний уцілілий з усіх матросів злощасної Третьої флотилії Кул-Тірасу, що розбилася біля узбережжя на півночі. І хоча я останній з команди, чиє серце ще б'ється, я не єдиний, хто ще ходить по землі! Бо на одному з наших кораблів був захований великий і жахливий скарб, і його моторошна сила тримає душі моїх братів у пастці в гнилих корпусах кораблів.\n\nАле якщо ти зможеш їх звільнити, тоді, можливо, ти зможеш зняти їхнє прокляття.", [3] = "Убийте 13 проклятих моряків, 5 проклятих морських піхотинців і першого помічника Снелліґа. Принесіть табакерку Снелліґа першому помічнику Фіцсіммонсу в гавань Менетілів.", [4] = "Крики моїх приречених побратимів переслідують мене в кошмарах! Прошу, {стать:добродію:добродійко}, звільни їх. Нехай їх крики змовкнуть назавжди.", [5] = "Я вдячний тобі, {ім'я}. Як і вдячні тобі мої прокляті побратими.", ["en"] = "The Cursed Crew", ["tasks"] = { ["Cursed Marine"] = "проклятий морський піхотинець", ["Cursed Marine slain"] = "проклятий морський піхотинець: убито", ["Cursed Sailor"] = "проклятий моряк", ["Cursed Sailor slain"] = "проклятий моряк: убито", ["Snellig's Snuffbox"] = "табакерка Снелліґа", ["Snellig's Snuffbox (Provided)"] = "табакерка Снелліґа (видано)" } },
    [29] = { [1] = "Випробування озера", [2] = "Твоїм першим випробуванням буде пошук прикраси з вівтаря в озері Елуна'ара. Вона швидко руйнується, тож тобі доведеться швидко віднести її до вівтаря Ремула. Поклади прикрасу на вівтар і поговори там з Таджаррі. Вона — одна з найдовіреніших вартових Місячної галявини.\n\nУ тебе обмаль часу і тобі, певно, доведеться змагатись з іншими друїдами в пошуках прикраси. Твоя фізична й духовна міць допоможуть тобі досягти успіху.\n\nНехай щастить, {ім'я:к}.", [3] = "Знайдіть прикрасу вівтаря в озері Елуна'ара, принесіть її до вівтаря Ремула на північному заході Місячної галявини та використайте її там.\n\nПісля цього поговоріть з Таджаррі біля вівтаря, щоб завершити випробування.", [4] = "Щоб завершити випробування озера — використай прикрасу біля вівтаря. Поки цього не зробиш — твоє випробування не може вважатись завершеним і ти можеш зазнати невдачі.", [5] = "Що ж, здається, ще {стать:один:одна} {клас:н} успішно {стать:завершив:завершила} випробування озера! Вітаю, {ім'я:к}, ти чудово {стать:впорався:впоралась}.\n\nЯк я вже казала, мене звати Таджаррі. Мій обов'язок і честь — стояти на варті Місячної галявини, а конкретно — цього вівтаря. Хранитель Ремул направляє Кенарійське Коло у збереженні природи та рівноваги, а цей вівтар — вшанування його пам'яті. Поклавши цю прикрасу тут, ти {стать:вшанував:вшанувала} його важливість.", ["en"] = "Trial of the Lake", ["tasks"] = { ["Complete the Trial of the Lake."] = "Пройдіть випробування озера.", ["Shrine Bauble"] = "прикраса вівтаря" } },
    [291] = { [1] = "Звіт", [2] = "Чудово! Достав мій звіт сенатору Беріну Червонокаменю. Він похмурий тип, тож дивись не заразись цим від нього. Він в Залізогарті, в палаті, де король Маґні вершить правосуддя.\n\nНе знаєш як потрапити в Залізогарт? Йди дорогою на північ від Хараноса, перейди міст, після чого йди східною дорогою - там будуть великі штандарти - вгору по схилу.\n\nДо речі, не {стать:міг би:могла б} ти уникнути деталей про твою допомогу? Не хочу, щоб подумали, ніби я тут не працюю в поті чола.", [3] = "Доставте звіт Сеніра сенатору Беріну Червонокаменю в Залізогарт.", [4] = "Хм... Схоже що мої охоронці почали впускати до мене абикого. Гаразд, кажи чого хочеш, тільки хутчіш.", [5] = "<Сенатор мигцем проглядає звіт>\n\nЗа схвалення КОРОЛЯ? Маґні зовсім з глузду з'їхав! І цей клятий Білобород... Отже, взяв справи в свої руки? Сенату це не сподобається, ой як не сподобається.\n\nЩо, ти ще тут? Йди звідси, поки я не покликав охорону!", ["en"] = "The Reports", ["tasks"] = { ["Deliver Senir's report to Senator Barin Redstone in Ironforge."] = "Доставте звіт Сеніра сенатору Беріну Червонокаменю в Залізогарт.", ["Senir's Report"] = "звіт Сеніра", ["Senir's Report (Provided)"] = "звіт Сеніра (видано)" } },
    [2922] = { [1] = "Порятунок мозку Техбота", [2] = "Коли наше любе місто Гномреґан впало, випадкова іскра, певно, вдарила моє бідолашне творіння — Техбота. Колись він допомагав мені та моїм колегам своїми незліченними пристроями й безмежним запасом інформації, але його позитронний мозок поляризувався. Тепер він негатронний... і поведінка Техбота стала протилежною. Він блукає Гномреґаном у нестямі!\n\nТа, можливо, його ще можна врятувати. Якщо ти зможеш дістати ядро пам'яті Техбота й принести його мені, я зможу з'ясувати причину поляризації та полагодити мого бідолашного Техбота.\n\n", [3] = "Принесіть ядро пам'яті Техбота мехмайстру Надспалаху в Залізогарт.", [4] = "Тобі вдалось знайти Техбота і витягти його ядро пам'яті?", [5] = "О, чудово! Дякую тобі, {ім'я}! Я негайно візьмуся до роботи!!\n\nБідний, бідний Техбот... Не засмучуйся. Ми тебе полагодимо.\n\nКуди я поклав свій гідропневмогайковерт...", ["en"] = "Save Techbot's Brain!", ["tasks"] = { ["Techbot's Memory Core"] = "ядро пам'яті Техбота", ["Techbot's Memory Core (Provided)"] = "ядро пам'яті Техбота (видано)" } },
    [2928] = { [1] = "Гіробурорийки", [2] = "Це жахливо, {ім'я}. У нас не вистачить запчастин, щоб підготувати наш флот гіробурорийок до відправлення в Дун-Морог.\n\nНам потрібні запчастини, {ім'я}. А де ще можна дістати запчастини для наших машин, як не в Гномреґані? Я чула, що роботи та механізми, що залишилися там, блукають містом, як худоба по леваді.\n\nЯ хочу, щоб ти {стать:вирушив:вирушила} до Гномреґану і {стать:розірвав:розірвала} тих роботів на шматки. Принеси мені їхні нутрощі. Двох дюжин має вистачити.", [3] = "Принесіть 24 пригорщі робо-механічних нутрощів Шоні в Штормовій.", [4] = "Якби це були перегони, ти б уже {стать:програв:програла}.", [5] = "Так, вони підійдуть, {ім'я}. Одна гіробурорийка відремонтована. Залишилось ще 398.", ["en"] = "Gyrodrillmatic Excavationators", ["tasks"] = { ["Robo-mechanical Guts"] = "робо-механічні нутрощі", ["Robo-mechanical Guts (Provided)"] = "робо-механічні нутрощі (видано)" } },
    [2929] = { [1] = "Велика зрада", [2] = "Я довіряв Термоштепселю, {раса:к}. Ніколи не думав, що він зрадить мене і весь народ гномів. І заради чого? Заради влади? Багатства? Все те, що він і так згодом отримав би. Тепер нас вигнали з нашого рідного дому, а цей божевільний залишився там правити. Король порожнього місця....\n\nМи повернемо собі Гномреґан, {ім'я}. Ми не зупинимося, доки місто знову не стане нашим. Якщо ти хочеш приєднатися до нашої боротьби, я прошу тебе виконати одне просте завдання — вбити зрадника. Знищ мекженера Термоштепселя.", [3] = "Вирушайте до Гномреґану та вбийте мекженера Термоштепселя, після чого повертайтесь до верховного штукаря Меккакрутя.", [4] = "Ти {стать:виконав:виконала} завдання? Він благав про милосердя?", [5] = "Мені подобається думати, що останнє, що він побачив, коли впав на землю, була твоя нога, {раса:к}. Зі смертю Термоштепселя ми стали на крок ближче до повернення Гномреґану.", ["en"] = "The Grand Betrayal", ["tasks"] = { ["Mekgineer Thermaplugg"] = "Термоштекер Mekgineer", ["Mekgineer Thermaplugg (Provided)"] = "Термоштекер Mekgineer (видано)", ["Mekgineer Thermaplugg slain"] = "Термоштекер Mekgineer: убито" } },
    [2930] = { [1] = "Порятунок даних", [2] = "Коли ми втікали з Гномреґану, ми залишили стільки даних! Життєво важливих даних!\n\nМені потрібні дані з призматичної перфокарти термінала високого рівня безпеки — матричного перфографа 3005-D, що знаходиться в глибинах Гномреґану. Ти маєш дістатися терміналу, але для цього тобі спочатку потрібно отримати допуск... а щоб отримати його, ти маєш отримати доступ до терміналів з нижчим рівнем захисту: моделей -A, -B та -C. А для ЦЬОГО тобі потрібні перфокарти, починаючи з білої... а всі перфокарти залишились у місті.\n\nЦе катастрофа! Можеш допомогти?", [3] = "Принесіть призматичну перфокарту майстру-механіку Трубоплаву в Залізогарт.", [4] = "Призматична перфокарта у тебе?!", [5] = "Тобі вдалося! Ти {стать:знайшов:знайшла} призматичну перфокарту і {стать:відновив:відновила} втрачені дані! Життєво, критично, безмірно важливі дані, без яких ми просто не зможемо жити!\n\nТвою допомогу гноми надовго запам'ятають, {ім'я}.", ["en"] = "Data Rescue", ["tasks"] = { ["Prismatic Punch Card"] = "призматична перфокарта", ["Prismatic Punch Card (Provided)"] = "призматична перфокарта (видано)" } },
    [2939] = { [1] = "В пошуках знань", [2] = "У руїнах Фераласа може бути доволі небезпечно, але вони можуть розповісти багато історії.\n\nДекілька днів тому, подорожуючи півднем, я виявив те, що здається звичайною дерев'яною палицею. Однак мені не дає спокою думка, що в ній є щось більше. Ми з Ангелою прочитали багато книг, але нічого не знайшли.\n\nУ мене є колега в Дарнасі, яка, можливо, зуміє допомогти, {ім'я:к}. Чому б тобі не поговорити з нею?", [3] = "Поговоріть з Дарін Легковій у селищі Рут'Теран.", [5] = "То тебе прислав Трояс Місяцебриз?\n\n<бурчить>... завжди турбує мене своїми \"надзвичайними\" знахідками...\n\nПослухай, {ім'я}, буду говорити відверто. Трояс завжди думає, що він знайшов щось важливе в тих руїнах. Насправді все, що там було цінного, давно вже розтягли огри або гарпії.\n\nТи, звісно, можеш поритися в бібліотеці, але я не знаю, чи зумієш ти знайти щось, що допоможе тобі.", ["en"] = "In Search of Knowledge" },
    [294] = { [1] = "Помста Ормера", [2] = "Ситуація важка, це точно. Коли ми під час розкопок виявили кістки, вони привабили рапторів. Ці мерзенні звірі вбили мою братію та заманили мене, Меррін та бідолашного розвідувача у пастку.\n\nДопоможи очистити Заболоття від цих рапторів, {ім'я}. Строкаті раптори та строкаті верескуни знаходяться на захід від обриву. Вбий по 10 кожного виду, якщо зможеш.\n\nЦе буде непоганим початком помсти яку я запланував для них.", [3] = "Ормер Залізов'яз із розкопок Вельґара хоче, щоб ви вбили 10 строкатих верескунів та 10 строкатих рапторів.", [4] = "Вбий 10 строкатих рапторів та 10 строкатих верескунів, {ім'я}. Мої товариші не заслуговували тієї долі, яка їх спіткала. Прийшов час вирівняти рахунок.", [5] = "Вбивство - це брудна справа, але ти добре {стать:виконав:виконала} свою роботу, {ім'я}. Якби я не мусив залишатись тут із розвідувачем та Меррін, я б був там знизу і проливав кров разом із тобою.", ["en"] = "Ormer's Revenge", ["tasks"] = { ["Mottled Raptor"] = "строкатий раптор", ["Mottled Raptor slain"] = "строкатий раптор: убито", ["Mottled Screecher"] = "строкатий верескун", ["Mottled Screecher slain"] = "строкатий верескун: убито" } },
    [2947] = { [1] = "Повернення персня", [2] = "Відкривши коробку, виготовлену Блискочистом 5200, ви бачите те, що й очікували — блискучий перстень! Ви відчуваєте, як він випромінює чарівну силу.\n\nНа його внутрішній стороні є невеликий, але помітний відбиток печатки Залізогарта. Поруч викарбувано маленькі ініціали: «ТдК». Це можуть бути ініціали власника, а може — ювеліра, що виготовив перстень. Залишити його собі... чи повернути власнику. Непросте рішення...", [3] = "Ви можете залишити перстень собі, або знайти того, чиї ініціали викарбувані на його внутрішній стороні.", [4] = "Гей, спокійно, {стать:друже:подруго} — я дуже важливий бізнесмен! Я впевнений, що кур'єр із грошима просто затримався в дорозі... хм, пожди... ти не мій орендодавець.\n\nНу звісно ж ні! Ти {стать:прийшов:прийшла} до найкращого ювеліра в усьому Залізогарті, того, хто НЕ створює ПРОКЛЯТИХ речей! Так!\n\nГм... то що тобі потрібно?", [5] = "Перстень, кажеш? Дай-но погляну... так, звісно, це моя робота.\n\nДо трагедії в Гномреґані я мав там невеличку крамницю. Можливо, це той самий перстень, який я залишив, коли тікав. Вони досить прості, я зробив таких декілька. Тож, можливо, цей перстень належав комусь, хто не зміг врятуватись.\n\nТи {стать:знайшов:знайшла} його у дворфа Темного Заліза? Що ж, це все стає ще більш заплутаним... Можливо, про це варто б дізнатись комусь з представників влади. Ця інформація точно не для таких, як я.\n\nА тепер, що стосується персня...", ["en"] = "Return of the Ring", ["tasks"] = { ["Brilliant Gold Ring"] = "блискучий золотий перстень", ["Brilliant Gold Ring (Provided)"] = "блискучий золотий перстень (видано)" } },
    [2948] = { [1] = "Гномське вдосконалення", [2] = "Слухай, {ім'я}, цей перстень твій, звісно... але я можу зробити кращий! Цей перстень, як я вже казав, дуже простий. Тепер я набагато вправніший, і всього лише за тридцять срібних монет я зроблю з нього витвір мистецтва! Ну, трохи більше тридцяти, якщо чесно...\n\nЯ зараз у скрутному становищі, всі мої запаси матеріалів вичерпались. Якщо принесеш мені злиток срібла та моховий агат, я додам до персня плетення зі срібла та агат, що додасть йому ще більше шику!\n\nПовір мені!", [3] = "Принесіть блискучий золотий перстень, злиток срібла, моховий агат та 30 срібних монет Талвашу дель Кісселю в Залізогарт.", [4] = "Ти {стать:приніс:принесла} всі необхідні матеріали? Я б не став тебе просити про них, якби не моє становище...", [5] = "Ах, це саме те, що треба! Одного дня, коли я виберуся з цієї нори, я зроблю для тебе, для ВСІХ І КОЖНОГО найкращі прикраси у всьому Азероті! А поки дякую тобі за допомогу з матеріалами. Я зазвичай беру вдесятеро більше за перстень такої якості...\n\nДо речі, про персні — ось твоя обнова!", ["en"] = "Gnome Improvement", ["tasks"] = { ["Brilliant Gold Ring"] = "блискучий золотий перстень", ["Brilliant Gold Ring (Provided)"] = "блискучий золотий перстень (видано)", ["Moss Agate"] = "моховий агат", ["Moss Agate (Provided)"] = "моховий агат (видано)", ["Silver Bar"] = "злиток срібла", ["Silver Bar (Provided)"] = "злиток срібла (видано)" } },
    [295] = { [1] = "Помста Ормера", [2] = "Тепер настав час справді змусити цих жахливих рапторів пошкодувати про свою жагу крові. Прямо під нами знаходяться десятки строкатих серпопазурів та строкатих бритвозубів. Змусь цих гнилих істот заплатити, вбивши по 10 кожного виду!", [3] = "Ормер Залізов'яз хоче, щоб ви вбили 10 строкатих серпопазурових рапторів і 10 строкатих бритвозубих рапторів і повернутись до нього в місце розкопок Вельґара.", [4] = "Я хочу, щоб ті строкаті серпопазурі та строкаті бритвозуби поплатились за те, що скоїли. Ти вже {стать:вбив:вбила} по 10 кожного виду?", [5] = "Ти {стать:виконав:виконала} відмінну роботу вичищаючи тих рапторів, {ім'я}!", ["en"] = "Ormer's Revenge", ["tasks"] = { ["Mottled Razormaw"] = "строкатий бритвозуб", ["Mottled Razormaw slain"] = "строкатий бритвозуб: убито", ["Mottled Scytheclaw"] = "строкатий серпопазур", ["Mottled Scytheclaw slain"] = "строкатий серпопазур: убито" } },
    [2963] = { [1] = "Провісники Ульдуму", [2] = "І знову привіт, {ім'я}! Твоя ульдаманська знахідка викликала захоплення у Ліги дослідників. Вони працювали не покладаючи рук, щоб розкрити таємниці цих платинових дисків. І ти дуже вчасно, мені є чим поділитись з тобою.\n\nІсторик Карник знайшов кілька важливих підказок щодо походження долини Наглядачів, що в пустелі Танаріс. І він хоче поскоріше поговорити з тобою!", [3] = "Поговоріть з істориком Карником в залі Дослідників, що в Залізогарті.", [5] = "Я радий, що твоя цікавість не згасає, {ім'я}! Твій талант та кмітливість допоможуть тобі розкрити таємниці, які ми навіть уявити не могли!\n\nДиски Норґаннона з Ульдаману містять безліч інформації. Все, що ми дізнались на цей час — лише верхівка айсберга. Ходять чутки, що у Творців було ще кілька таких сховищ по всьому Азероту. І тут ми згадуємо Ульдум...", ["en"] = "Portents of Uldum" },
    [2969] = { [1] = "Свободу звірятам", [2] = "Мерзенні таурени Зловісного Тотема ловлять чарівних дракончиків, {ім'я}. Ми з Джер'кай не маємо жодної здогадки, що вони збираються з ними робити, але вочевидь нічого доброго.\n\nМи не маємо достатньо сили, щоб прорватися в табір і звільнити захоплених дракончиків, але, можливо, з твоєю допомогою...\n\nЯкщо ти {стать:готовий:готова} і маєш надійних союзників, звільни цих бідолашних звірят з кліток за допомогою цього ключа і переконайся, що вони зможуть втекти. Я звісно буду поруч увесь час. А Джер'кай залишиться тут.", [3] = "За допомогою ключа від бамбукової клітки випустіть райдужних хамелеонів із загону в таборі Зловісного Тотема. Щонайменше 6 райдужних хамелеонів і Кіндал Місяцеткач повинні вижити.\n\nУ вас є 6 хвилин, перш ніж Кіндал вирішить, що настав час відступати, і ви провалите завдання.", [4] = "Ми не можемо дозволити Зловісному Тотему знищити цих прекрасних створінь. Їх потрібно звільнити!", [5] = "Хвала Елуні, {ім'я}! Ти велике благословення для нас і для врятованих тобою дракончиків. Ми ніколи не змогли б допомогти їх самі.\n\nПоговори з Джер'кай... Я маю підготуватися до помсти. Те, що райдужні хамелеони вільні, ще не означає, що для них все скінчено. Ми з Джер'кай підготуємо наступний крок.", ["en"] = "Freedom for All Creatures", ["tasks"] = { ["Save at least 6 Sprite Darters from capture"] = "Врятуйте щонайменше 6 Спрайт Дартерів від захоплення" } },
    [297] = { [1] = "Збір ідолів", [2] = "Недавно, прямо перед тим, як троги вилізли з розкопок, ми знайшли велику кількість дивних різьблених ідолів. Але ми не мали можливості їх дослідити, бо якраз після цього троги прогнали нас з руїн! І ці ідоли дивно впливають на трогів! Вони перетворюються в берсерків!\n\nПринеси мені 8 ідолів - я хочу вивчити їх детальніше. Ти знайдеш ідоли у трогів, їх там вдосталь.", [3] = "Принесіть Маґмару Люторубу 8 різьблених кам'яних ідолів.", [4] = "Ти {стать:дістав:дістала} ідоли? Ми маємо їх вивчити та відзвітувати до Залізогарту!", [5] = "Вони в тебе! Чудова робота, {ім'я}!\n\nІ ти наче не занадто {стать:побитий:побита}, не дивлячись на всіх тих трогів-берсерків. Я буду слідкувати за твоєю долею... ти подаєш надію.", ["en"] = "Gathering Idols", ["tasks"] = { ["Carved Stone Idol"] = "різьблений кам'яний ідол", ["Carved Stone Idol (Provided)"] = "різьблений кам'яний ідол (видано)" } },
    [2970] = { [1] = "Крихта правосуддя", [2] = "Як тобі вже сказала Кіндал, ми збираємося дати бій Зловісному Тотему. Вдвох ми зможемо знищити кількох тауренів без особливих складнощів, але ми були б дуже раді, якби й ти до нас {стать:приєднався:приєдналася}.\n\nТи {стать:бачив:бачила} табір під нами, але існують інші на сході. Постарайся завдати тауренам якомога більше шкоди. Зустрінемося тут після того, як вони скуштують стріл Кайдел і твоєї зброї.", [3] = "Вбийте 12 натуралістів Зловісного Тотема, 10 рейдерів Зловісного Тотема і 6 шаманів Зловісного Тотема, перш ніж повернутися до Джер'кай Місяцеткач у Фералас.", [4] = "Кіндал потрібен час, щоб підготуватися, але ми вже вбили немало. Зловісний Тотем знає про нашу присутність, ми розворушили їхнє зміїне кубло.\n\nВони зроблять все, що в їхніх силах, щоб отримати наші голови. Тож будь насторожі... Тепер, коли ти з нами, вони полюватимуть і на тебе.", [5] = "Кіндал мала рацію, {ім'я} — у тебе талант. Ти більш {стать:досвідчений шукач пригод:досвідчена шукачка пригод}, ніж ми. Дякую, що ти з нами!\n\nЗловісний Тотем значно небезпечніший за інших тауренів... Я думаю, що навіть їхній власний рід не схвалює їхніх дій. Я б не здивувалася. Як ти, мабуть, знаєш, у багатьох рас на Азероті є менш доброзичливі побратими.\n\nВтім, це вже тема для іншої розмови.", ["en"] = "Doling Justice", ["tasks"] = { ["Grimtotem Naturalist"] = "натураліст Зловісного Тотема", ["Grimtotem Naturalist slain"] = "натураліст Зловісного Тотема: убито", ["Grimtotem Raider"] = "рейдер Зловісного Тотема", ["Grimtotem Raider slain"] = "рейдер Зловісного Тотема: убито", ["Grimtotem Shaman"] = "шаман Зловісного Тотема", ["Grimtotem Shaman slain"] = "шаман Зловісного Тотема: убито" } },
    [2972] = { [1] = "Крихта правосуддя", [2] = "Тут, у дикій природі, у нас з Кіндал немає можливостей винагородити тебе, але без нагороди ми тебе не відпустимо. Візьми мій перстень-печатку. Якщо колись опинишся в хащах Тельдрассіля, зайди в храм Місяця у серці Дарнаса. Там ти знайдеш верховну жрицю Тіранду Шелест Вітру. Перстень дасть їй знати, що з нами все гаразд, і що тобі можна довіряти.\n\nМи обидві вдячні тобі, {ім'я}.", [3] = "Віднесіть перстень-печатку Джер'кай верховній жриці Тіранді Шелесту Вітру в Дарнас.", [4] = "Привіт, дитя. Ми раді бачити в нашому храмі таких загартованих шукачів пригод. Якщо в тебе є час, можливо, ти розкажеш кілька історій менш досвідченим мандрівникам? Багатьом із них, напевно, піде на користь твоя мудрість.\n\nДаруй за мою нечемність. Ти {стать:прийшов:прийшла} до храму по нашу допомогу, а я нав'язую тобі своє прохання. Будь ласка, пробач мені це. Скажи, чим служителі Світла можуть допомогти тобі?", [5] = "Дуже цікава історія, {ім'я}. Нам приємно, що ти {стать:допоміг:допомогла} не тільки дракончикам, але й нашим жрицям. Джер'кай вчинила правильно, відправивши тебе до мене. Я подбаю про те, щоб повернути їй її перстень — до Фераласу найближчим часом вирушать наші розвідники. Це буде ще одна річ, яку вони досліджуватимуть під час своєї місії.\n\nЩе раз дякую, і, будь ласка, поки ти тут, почувай себе як вдома.", ["en"] = "Doling Justice", ["tasks"] = { ["Jer'kai's Signet Ring"] = "перстень-печатка Джер'кай", ["Jer'kai's Signet Ring (Provided)"] = "перстень-печатка Джер'кай (видано)" } },
    [298] = { [1] = "Звіт про хід розкопок", [2] = "Мені потрібно відправити звіт про хід робіт до Телсамару. Звіт та запит на нову партію пороху. Ось вони. Віднеси їх Джерну Рогошолому. Він наш представник в Телсамарі.\n\nЗавдання це не складне, але все ж важливе.", [3] = "Віднесіть звіт про хід робіт Залізоплета до Джерна Рогошолома в Телсамар.", [4] = "О, звіт з розкопок? Чудесно!", [5] = "Ха! У Залізоплета проблеми з трогами. Цікаво, цей порох йому потрібен для розкопок чи для трогів...\n\nЩо ж, так чи інакше порох буде витрачено з користю!\n\nАле що дивно, кілька тижнів тому я надіслав йому купу пороху. Цікаво, куди він подівся...", ["en"] = "Excavation Progress Report", ["tasks"] = { ["Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar."] = "Віднесіть звіт про хід робіт Залізоплета Джерну Рогошолому в Телсамар.", ["Ironband's Progress Report"] = "звіт Залізоплета", ["Ironband's Progress Report (Provided)"] = "звіт Залізоплета (видано)" } },
    [2982] = { [1] = "Безкрайня глушина", [2] = "Хоч це й небезпечно, та ми з Троясом досліджуємо руїни в лісах Фераласа.\n\nАле останнім часом Трояс ходив у Безкрайню глушину сам, і я дуже переймаюся за нього. Огри клану Ґордунні захопили ту місцевість і вони не дуже люблять, коли хтось заходить на їхню територію.\n\nМожливо, ти погодишся піти до руїн на південному сході та вбити кількох огрів? Тоді ці місця стануть трішки безпечнішими для мого Трояса, і я буду надзвичайно вдячна тобі.", [3] = "Ангела Місяцебриз просить вас вбити 8 чорнокнижників Ґордунні, 8 шаманів Ґордунні та 8 моцаків Ґордунні.", [4] = "Обережніше в землях Ґордунні, {ім'я}. Їхні чари, здається, сіють хаос по землі, на якій вони стоять.", [5] = "Я дуже вдячна, що ти {стать:зміг:змогла} зробити це для мене.\n\nА тепер, будь ласка, ні слова про це Троясу...", ["en"] = "The High Wilderness", ["tasks"] = { ["Gordunni Brute"] = "моцак Ґордунні", ["Gordunni Brute slain"] = "моцак Ґордунні: убито", ["Gordunni Shaman"] = "шаман Ґордунні", ["Gordunni Shaman slain"] = "шаман Ґордунні: убито", ["Gordunni Warlock"] = "чорнокнижник Ґордунні", ["Gordunni Warlock slain"] = "чорнокнижник Ґордунні: убито" } },
    [2988] = { [1] = "Клітки Зів'ялої Кори", [2] = "Син нашого наймогутнішого грифона зник! Спадкоємець Стрімкокрила, Гостродзьоб, загубився на полюванні разом з батьками кілька днів тому, і ми думаємо, що його забрали тролі.\n\nТи {стать:повинен:повинна} нам допомогти! Обшукай клітки у двох селищах тролів Зів'ялої Кори, щоб дізнатися, чи немає там Гостродзьоба.", [3] = "Перевірте клітки у двох селищах тролів Зів'ялої Кори, а потім поверніться до приборкувача грифонів Кігтеруба.", [4] = "Ти {стать:обшукав:обшукала} клітки, {ім'я}? Ми мусимо знайти Гостродзьоба!", [5] = "Гостродзьоба не було в селищах? Хм... це погані новини. Цьому грифону судилося очолити наступне покоління грифонів. Якщо він загине, сила і дух нашого флоту дуже сильно постраждають.", ["en"] = "Witherbark Cages", ["tasks"] = { ["Check First Cage"] = "Перевірте першу клітку", ["Check Second Cage"] = "Перевірте другу клітку", ["Check Third Cage"] = "Перевірте третю клітку" } },
    [2989] = { [1] = "Олтар Зула", [2] = "Гостродзьоба не було у тролів Зів'ялої Кори. Можливо, його забрали тролі Миршавого Гілля. Йди до Олтаря Зула на західному краю території Миршавого Гілля та знайди пташеня грифона.", [3] = "Перевірте верхню частину Олтаря Зула, а потім поверніться до приборкувача грифонів Кігтеруба.", [4] = "Поквапся, {ім'я}! Якщо Гостродзьоб у тролів Миршавого Гілля, хто знає, що вони можуть з ним зробити!", [5] = "Гостродзьоба там не було? Це погана новина, але й хороша теж...\n\nДобре, що його не було біля Олтаря Зула, бо тролі Миршавого Гілля відомі своїми жертвоприношеннями.\n\nЯ дякую тобі за допомогу, але боюся, що у мене для тебе є ще більш важливе завдання.", ["en"] = "The Altar of Zul", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Search the Altar of Zul"] = "Обшукайте вівтар Зула" } },
    [299] = { [1] = "Таємниці минулого", [2] = "Прямо перед вторгненням я знайшов велику табличку, що називається скрижаллю Ґоаз. Кілька шматків відсутні, тому текст обривається в чотирьох місцях, прямо перед чимось про \"задум богів\" та \"пророцтво про кінець світу\".\n\nБоюсь що у нас обмаль часу. Я застарий, щоб спуститись і битись з усіма цими звірами. Але ти виглядаєш {стать:сильним:сильною}.\n\nОбшукай розкопки й знайди 4 фрагменти скрижалі: Адос, Модр, Ґолм та Неру. Шукай їх серед древніх реліквій та в пухкому ґрунті. Принеси їх мені і я розгадаю цю таємницю.", [3] = "Розвідувач Вельґар просить вас знайти на розкопках 4 фрагменти скрижалі: Адос, Модр, Ґолм та Неру.", [4] = "Ти {стать:знайшов:знайшла} чотири фрагменти, {ім'я}? Адос, Модр, Ґолм та Неру...", [5] = "Отож, скрижаль Ґоаз відновлено! Чудова робота, {ім'я}. Дійсно чудова. Тепер я можу продовжити переклад послання титанів. Я вже бачу нові слова! Хм... \"старі боги... закуті під землею...\". Що ж, схоже, нас чекає щось грандіозне.", ["en"] = "Uncovering the Past", ["tasks"] = { ["Ados Fragment"] = "фрагмент Адос", ["Ados Fragment (Provided)"] = "фрагмент Адос (видано)", ["Golm Fragment"] = "фрагмент Ґолм", ["Golm Fragment (Provided)"] = "фрагмент Ґолм (видано)", ["Modr Fragment"] = "фрагмент Модр", ["Modr Fragment (Provided)"] = "фрагмент Модр (видано)", ["Neru Fragment"] = "фрагмент Неру", ["Neru Fragment (Provided)"] = "фрагмент Неру (видано)" } },
    [2991] = { [1] = "Медальйон Некрума", [2] = "Я дізнаюся, де твій грифон, але спершу ти маєш дещо для мене зробити. В Зул'Фарраці є один троль — Некрум Кишкожер. У нього є медальйон, який я дуже хотів би вивчити. Принеси мені цей медальйон і я знайду Гостродзьоба.\n\nЗул'Фаррак розташований за океаном, на заході, в пустелі Танаріс.", [3] = "Принесіть медальйон Некрума Тадію Хмуротіні в Спустошені землі.", [4] = "Ти {стать:приніс:принесла} медальйон Некрума, {ім'я}? Я хочу дослідити приховані у ньому сили.", [5] = "Ого, медальйон Некрума. Подейкують, що він і є секретом довголіття троля, але за певну ціну. Сподіваюся, я зможу скористатися силою цього медальйона й уникнути його... побічних ефектів.\n\nТи {стать:зробив:зробила} мені велику послугу, {ім'я}. Тепер я виконаю свою частину угоди.", ["en"] = "Nekrum's Medallion", ["tasks"] = { ["Nekrum's Medallion"] = "медальйон Некрума", ["Nekrum's Medallion (Provided)"] = "медальйон Некрума (видано)" } },
    [2993] = { [1] = "Повернення у Внутрішні землі", [2] = "Гостродзьоба тримають у клітці, на вершині скелі Джинта'Алора у Внутрішніх землях. Ключ від клітки у верховної жриці племені Миршавого Гілля — підступної жриці Гекс.\n\nОтож, я виконав свою частину угоди. Нехай тобі щастить з пошуками, {ім'я}.", [3] = "Поговоріть з приборкувачем грифонів Кігтерубом.", [5] = "Ти {стать:говорив:говорила} з Хмуротінню? Що він сказав?\n\n...Що? Гостродзьоб у тролів Миршавого Гілля? Це немислимо! Ми повинні зібратись з силами, щоб повернути його!", ["en"] = "Return to the Hinterlands" },
    [2994] = { [1] = "Порятунок Гостродзьоба", [2] = "Ми маємо врятувати Гостродзьоба!\n\nПроберись на вершину Джинта'Алора, що в самому серці території Миршавого Гілля, забери ключ від клітки Гостродзьоба у підступної жриці Гекс, а потім знайди та врятуй Гостродзьоба!", [3] = "Бийтеся на вершині Джинта'Алора, вбийте підступну жрицю Гекс, щоб отримати ключ від клітки Гостродзьоба, і врятуйте Гостродзьоба.", [4] = "Врятуй Гостродзьоба!", [5] = "Стрімковій і Кігтевик повернулися зі своїм пташеням кілька хвилин тому і тепер від нього не відходять. Одного лише погляду на них достатньо, щоб навіть у такого старого дворфа як я покотилася сльоза...\n\nЯ навіть не знаю, чим ми можемо віддячити тобі, {ім'я}. Грифони Орлиного піку та їхні вершники назавжди запам'ятають твоє ім'я.", ["en"] = "Saving Sharpbeak", ["tasks"] = { ["Open Sharpbeak's Cage"] = "Відкрийте клітку Гостроклюва", ["Open Sharpbeak's Cage (Provided)"] = "Відкрийте клітку Гостроклюва (видано)", ["Open Sharpbeak's Cage slain"] = "Відкрийте клітку Гостроклюва: убито" } },
    [2997] = { [1] = "Фоліант божественності", [2] = "Вітаю, {ім'я:к}. Я знаю, що ти {стать:зайнятий:зайнята} допомогою жителям Дун-Морогу, та як матимеш час — відправляйся до Залізогарту та поговори з нашою найшанованішою сестрою — Тізою Боєкузнею. До неї приходять юні паладини коли приходить час дізнатись більше про Світло та подальший шлях паладина.\n\nТи знайдеш її на верхньому поверсі залу Таємниць, що в Таємній палаті. Нехай щастить, {ім'я:к}.", [3] = "Поговоріть з Тізою Боєкузнею в Залізогарті.", [5] = "Вітаю тебе, {ім'я:к}. Сподіваюсь, Світло вказує тобі праведний шлях та береже від зла.", ["en"] = "Tome of Divinity" },
    [2998] = { [1] = "Фоліант божественності", [2] = "Вітаю, {стать:брате:сестро}. Даторіан Ралл, один з найвпливовіших паладинів, нещодавно говорив про тебе. Я чув, як він казав щось про випробування для тебе... Та й взагалі він казав добрі речі про тебе.\n\nНа твоєму місці я б прямував до Штормовію і поговорив з ним. Впевнений, ти знайдеш його в соборі Світла — там він проводить більшу частину часу.", [3] = "Поговоріть з Даторіаном Раллом в Штормовії.", [5] = "В Штормовії красиво, чи не так?\n\nТи {стать:прибув:прибула} неймовірно вчасно, {ім'я:к}.", ["en"] = "Tome of Divinity" },
    [2999] = { [1] = "Фоліант божественності", [2] = "Привіт, {ім'я:к}. Я знаю, що ти {стать:зайнятий:зайнята} допомогою жителям Дун-Морогу, та як матимеш час — відправляйся нагору та поговори з нашою найшанованішою сестрою — Тізою Боєкузнею. До неї приходять юні паладини коли приходить час дізнатись більше про Світло та подальший шлях паладина.", [3] = "Поговоріть з Тізою Боєкузнею в Залізогарті", [5] = "Вітаю тебе, {ім'я:к}. Сподіваюсь, Світло вказує тобі праведний шлях та береже від зла.", ["en"] = "Tome of Divinity" },
    [3000] = { [1] = "Фоліант божественності", [2] = "Вітаю, {ім'я:к}. Я знаю, що ти {стать:зайнятий:зайнята} допомогою жителям Азероту, та як матимеш час — повертайся до Залізогарту та поговори з однією з найшанованіших паладинок наших земель — Тізою Боєкузнею. До неї приходять юні дворфи-паладини коли приходить час дізнатись більше про Світло та подальший шлях паладина.\n\nТи знайдеш її на верхньому поверсі залу Таємниць, що в Таємній палаті. Нехай щастить, {ім'я:к}.", [3] = "Поговоріть з Тізою Боєкузнею в Залізогарті.", [5] = "Вітаю та ласкаво прошу, {ім'я:к}.", ["en"] = "Tome of Divinity" },
    [301] = { [1] = "Звіт до Залізогарту", [2] = "Ми не можемо задовольнити запит на партію пороху для Залізоплета без схвалення вище. Тобі доведеться віднести цей звіт до штаб-квартири Ліги дослідників в Залізогарті.\n\nОсь, тримай. Віднеси його розвідувачеві Бурешпилю і не забудь відійти трохи далі, як віддаси його. Бурешпиль - гаряча голова, і він не буде радий почути про затримки в розкопках Залізоплета.\n\nТи знайдеш Бурешпиля в асамблеї Дослідників.", [3] = "Віднесіть звіт Залізоплета до розвідувача Бурешпиля.", [4] = "Ми, Бурешпилі, не любимо коли нас турбують через дрібниці, {клас:к}. Сподіваюсь, твоя звістка варта моєї уваги.", [5] = "Клятий Залізоплет! Я відправив йому цілий віз пороху кілька тижнів тому, але він не згадав про це у звіті.\n\nОтож... Куди подівся порох?!?", ["en"] = "Report to Ironforge", ["tasks"] = { ["Ironband's Progress Report"] = "звіт Залізоплета", ["Ironband's Progress Report (Provided)"] = "звіт Залізоплета (видано)", ["Take Ironband's Progress Report to Prospector Stormpike."] = "Віднесіть звіт про хід робіт Залізоплета розвідувачу Бурешпилю." } },
    [302] = { [1] = "Порох для Залізоплета", [2] = "Якщо Залізоплету все ще потрібен порох, то, іменем короля Магні, він його отримає! Я відправив посланця зі схваленням до Джерна Рогошолома в Телсамар. Він підготує партію пороху та інші припаси для Залізоплета.\n\nІ ще одне: я хочу, щоб ти особисто {стать:простежив:простежила} за вантажем. Останній вантаж не дістався розкопок, тому очі в руки і пильнуй.", [3] = "Поговоріть з Джерном Рогошоломом в Телсамарі.", [5] = "Що? Бурешпиль хоче, щоб ти особисто {стать:супроводжував:супроводжувала} вантаж до Залізоплета?\n\nЯ... думаю, це непогана ідея, але... Я вже відправив Гулдара з вантажниками, Міраном та Саяном. Ти щойно {стать:розминувся:розминулась} з ними.", ["en"] = "Powder to Ironband" },
    [3022] = { [1] = "Нести з обережністю", [2] = "{ім'я}, я бачу, що ти прагнеш присвятити себе моїй корисній справі. Так, звичайно, ти можеш дещо зробити для мене!\n\nВіднеси цей ящик яєць Ереласу Бурштинонебесному. Він друїд, який дбає про ці яйця, допомагає їм вилупитися, а потім тренує молодих гіпогрифів. Ти знайдеш його на Тельдрассілі, у невеликому селищі під назвою Рут'Теран, що на півдні.", [3] = "Принесіть дбайливо запакований ящик Ереласу Бурштинонебесному в селище Рут'Теран.", [4] = "Ще одна партія від Бульки, я так розумію?", [5] = "Дякую за твою допомогу, {ім'я}. Якби не ми, гіпогрифи вже б вимерли. Але я впевнений, що ти це дуже добре розумієш, адже тобі траплялося бувати у Фераласі, і ти знаєш не з чуток, як спустошили землю Ґордунні.\n\nНу, як бачиш, я тут заклопотаний роботою, тому тобі краще піти.\n\nЩе раз дякую, {ім'я}.", ["en"] = "Handle With Care", ["tasks"] = { ["A Carefully-packed Crate"] = "дбайливо запакований ящик", ["A Carefully-packed Crate (Provided)"] = "дбайливо запакований ящик (видано)" } },
    [305] = { [1] = "У пошуках групи розкопок", [2] = "О боже, ти, мабуть, {стать:той розвідник, якого:та розвідниця, яку} Довгокос обіцяв надіслати! Ти не уявляєш як сильно я хвилювався.\n\nМоя дружина Меррін протягом останнього місяця щотижня надсилала мені листи. Вона взяла участь в групі розкопок Вельґара. Але з моменту останнього надісланого її листа пройшло майже два тижні. Напевно, щось не так!\n\nДовгокос казав, що надішле {стать:розвідника:розвідницю} перевірити, що там коїться, якщо найближчим часом група з нами не зв'яжеться. Я припускаю, що цей розвідник — це ти, {ім'я}. Знайди Меррін на місці розкопок на сході!", [3] = "Таррел Кам'яноткач хоче, щоб ви дістались місця розкопок та знайшли Меррін Кам'яноткач.", ["en"] = "In Search of the Excavation Team" },
    [306] = { [1] = "У пошуках групи розкопок", [2] = "Це було жахливо! Ми викопували кілька рідкісних артефактів і натрапили на ці великі кістки.\n\nПерш ніж ми зрозуміли, що відбувається, ці строкаті раптори захопили місце розкопок. Багато життів було втрачено.\n\nМене та розвідувача врятував Ормер — він такий хоробрий. Він захищав нас поки ми шукали укриття. Але тепер ми у пастці. І наша важка праця лежить у руїнах.\n\nОсь, віднеси цю записку до мого любого Таррела. Це пояснить йому ситуацію.", [3] = "Поверніться до Таррела Кам'яноткача з запискою Меррін.", [4] = "Ти {стать:зміг:змогла} знайти Меррін? Вона передала щось?", [5] = "Які жахливі новини! Принаймні 3 з них вижили. Але коли ці смерті припиняться? Я прагну дня, коли піддані короля Маґні зможуть жити без страху.", ["en"] = "In Search of The Excavation Team", ["tasks"] = { ["Merrin's Letter"] = "записка Меррін", ["Merrin's Letter (Provided)"] = "записка Меррін (видано)" } },
    [307] = { [1] = "Бридкі лапи", [2] = "Копальня Срібних потоків, що на схід звідси, вже давно вироблена. Ліга Шахтарів використовувала її як склад, але тепер туди вдерлись кобольди та наклали свої мерзенні лапи на чудові дворфійські інструменти!\n\nМи скоро видворимо звідти цих шкідників, але Ліга хоче, щоб хтось врятував їх спорядження, поки мої воїни не увірвались туди й не розтрощили там все. Завдання це не з простих, помічники тобі не завадять.\n\nСпорядження знаходиться в ящиках Ліги шахтарів, що розкидані по всій шахті. Щасти тобі.", [3] = "Йдіть до копальні Срібних потоків та зберіть для горянина Бурешпиля 4 ящики шахтарського спорядження.", [4] = "Ти {стать:добув:добула} шахтарське спорядження, {ім'я}?", [5] = "Ну що, багато там кобольдів? Не можу дочекатися, як прибуде наказ зачистити копальню. Як подумаю, що вони роблять з шахтою своїми бридкими лапами, мене аж сіпає!", ["en"] = "Filthy Paws", ["tasks"] = { ["Miners' Gear"] = "шахтарське спорядження", ["Miners' Gear (Provided)"] = "шахтарське спорядження (видано)" } },
    [308] = { [1] = "Відволікання Ярвена", [4] = "Хмм! Скільки ж тут випивки, а в мене суворий наказ не чіпати нічого. Мені б хоч трохи покуштувати нашого громузвару... це б зробило мій розум гострішим, чесне слово!", [5] = "Це мені? Ти {стать:справжній герой:справжня героїня}, {ім'я}!", ["en"] = "Distracting Jarven", ["tasks"] = { ["Thunder Ale"] = "громузвар", ["Thunder Ale (Provided)"] = "громузвар (видано)" } },
    [309] = { [1] = "Захист вантажу", [2] = "{стать:Готовий:Готова} йти, {ім'я}?\n\nВ першу чергу, нам треба доставити цей порох Залізоплету. Вантаж немалий, а тут може бути небезпечно — хтозна-що ще задумало Темне Залізо.\n\nМені буде значно спокійніше з тобою.", [3] = "Переконайтесь, що Міран з вантажем дістануться до розкопок, після чого поговоріть з розвідувачем Залізоплетом.", [4] = "Де мій порох, {ім'я}? Мої потреби ростуть з кожним днем.", [5] = "О, хвала Світлу, порох прибув. Але звістка звісно тривожна. Подумати тільки, у Темного Заліза є поплічники, які можуть забезпечити їх першосортними матеріалами для втілення мерзенних задумів.\n\nХай цим займається хтось інший, та й не сьогодні. А я знайду цьому пороху файне застосування.", ["en"] = "Protecting the Shipment", ["tasks"] = { ["Escort Miran to the excavation site"] = "Супроводіть Мірана до місця розкопок" } },
    [310] = { [1] = "Міцне суперництво", [2] = "Мушу визнати, ці Громовари роблять файні напої. Але вони повинні зрозуміти, що не тільки в них гідне варево! Може, ти допоможеш їх провчити...\n\nОсь, візьми це барильце Ячміноварового Пекучого. Прослизни у підвал винокурні Громовара, що в Хараносі, та заміни на одне барильце їх громузвару. Тоді й подивимося, як відвідувачам сподобається моє пиво більш за їхнє!\n\nЯкщо бочки охороняються, можливо, тобі доведеться відволікти охорону...", [3] = "Замініть одне барильце громузвару барильцем Ячміноварового Пекучого у підвалі винокурні Громовара в Хараносі.", [4] = "Дата на цій діжці свідчить, що незабаром її відкриють.", [5] = "Ви швидко ставите барильце Ячміноварового Пекучого, що дала вам Марлет, серед барилець громузвару.", ["en"] = "Bitter Rivals", ["tasks"] = { ["Barrel of Barleybrew Scalder"] = "барильце Ячміноварового Пекучого", ["Barrel of Barleybrew Scalder (Provided)"] = "барильце Ячміноварового Пекучого (видано)" } },
    [3100] = { [1] = "Простий лист", [2] = "Мене попросили передати тобі цього листа, щойно ти повернешся з табору кобольдів, {ім'я}. Здається, на цьому листі стоїть печатка Ллейна, нашого тренера воїнів. На твоєму місці, я б не зволікав і прочитав би листа до того, як відправитись далі у справах абатства.", [3] = "Прочитайте простий лист і поговоріть з Ллейном Бішіром в Північнокрайовому абатстві.", [4] = "А, ти {стать:отримав:отримала} листа, {ім'я:к}. Добре.\n\nОстаннім часом в Ельвинні з'являється все більше воїнів. Що дуже добре для Штормовію... і дуже погано для кобольдів та Непокірних.", [5] = "Спробуй розібратись з місцевими негараздами, оглянь місцевість і повертайся до мене, як знадобляться тренування. Я буду тут в будь-який час доби.\n\nЛицарі Сріблястої Десниці добре постарались над безпекою цих країв. Але поспілкуйся з місцевими і, я певен, ти знайдеш кілька проблем, які не вирішити без допомоги {стать:такого:такої} {клас:р}, як ти. Нехай тобі щастить.", ["en"] = "Simple Letter", ["tasks"] = { ["Simple Letter"] = "простий лист", ["Simple Letter (Provided)"] = "простий лист (видано)" } },
    [3101] = { [1] = "Освячений лист", [2] = "Мене попросили передати тобі цього листа, щойно ти повернешся з табору кобольдів, {ім'я:к}. Здається, на цьому листі стоїть печатка брата Семмюела, нашого тренера паладинів. На твоєму місці, я б не зволікав і прочитав би листа до того, як відправитись далі у справах абатства.", [3] = "Прочитайте освячений лист і поговоріть з братом Семмюелом в Північнокрайовому абатстві.", [4] = "Нарешті! Ось ми й зустрілись, {стать:брате:сестро}. Вітаю тебе в Північнокраї. Це місце деякий час буде твоїм притулком, поки ти не освоїш тонкощі нашої справи. Та знай, що Штормовій неподалік і рано чи пізно дорога приведе тебе туди. Та поки наберись терпіння... {стать:лицарю:лицарко} Сріблястої Десниці.", [5] = "Між тим, тобі варто засвоїти кілька речей. Ти будеш прикладом для багатьох, тож поводься відповідно. Священне Світло сяє в тобі — це бачать і друзі, і вороги.\n\nТакож, коли наберешся мудрості і сили, тобі варто буде навчитись нових навичок. Тут я тобі й допоможу. Як здобудеш достатньо досвіду в Північнокраї — приходь до мене і я навчу тебе всього необхідного. Щасти тобі... {клас:к}.", ["en"] = "Consecrated Letter", ["tasks"] = { ["Consecrated Letter"] = "освячений лист", ["Consecrated Letter (Provided)"] = "освячений лист (видано)" } },
    [3102] = { [1] = "Зашифрований лист", [2] = "Мене попросили передати тобі цього листа, щойно ти повернешся з табору кобольдів, {ім'я}. Здається, на цьому листі стоїть печатка Йоріка, одного з наших місцевих тренерів. На твоєму місці, я б не зволікав і прочитав би листа до того, як відправитись далі у справах абатства.", [3] = "Прочитайте зашифрований лист та поговоріть з Йоріком Керріданом в стайні за Північнокрайовим абатством.", [4] = "Ти {стать:дістався цілим і неушкодженим:дісталася цілою і неушкодженою}, і не схоже, що тебе бачило багато людей. Для мене цього достатньо. Не люблю, коли до мене привертають багато уваги... тут тихо і спокійно. Впевнений, що ти мене розумієш.\n\nУ тебе немає ніяких проблем? Радий це чути. Це скоро зміниться.", [5] = "Ти скоро дізнаєшся, що багато кому потрібні наші навички, {ім'я}. Мандрівники, ШУР... трясця, навіть Братство Непокірних не проти послати кількох шпигунів у Штормовій. Але запам'ятай: ти {стать:сам собі господар:сама собі господиня}. Не давай нікому змушувати тебе робите те, чого ти не хочеш робити! Крім того, усі козирі у нас на руках... принаймні, поки гра не закінчилася. Розумієш про що я?\n\nТак чи інакше, я просто хотів представитися та дати тобі знати, що я буду тут, якщо тобі знадобиться тренування. Приходь у будь-який час.", ["en"] = "Encrypted Letter", ["tasks"] = { ["Encrypted Letter"] = "зашифрований лист", ["Encrypted Letter (Provided)"] = "зашифрований лист (видано)" } },
    [3103] = { [1] = "Священний лист", [2] = "Мене попросили передати тобі цього листа, щойно ти повернешся з табору кобольдів, {ім'я}. Здається, на цьому листі стоїть печатка жриці Анетти, нашої тренерки жерців. На твоєму місці, я б не зволікав і прочитав би листа до того, як відправитись далі у справах абатства.", [3] = "Прочитайте священний лист та поговоріть зі жрицею Анеттою в Північнокрайовому абатстві.", [4] = "Ах, нарешті ти {стать:прийшов:прийшла}. Я знала, що ти знайдеш шлях до мене. Святе Світло осяває тебе та шлях, який ти {стать:обрав:обрала}. Зараз часи дуже неспокійні — Палаючий Легіон все ще присутній в Азероті, а весь Калімдор шукає нові шляхи захисту від власного нещастя, тож саме від тебе залежить, чи зможеш ти допомогти всім.", [5] = "Коли наберешся досвіду — повертайся до мене, і я зроблю все можливе, щоб передати свої знання тобі. А поки що йди зі співчуттям у своєму серці, і нехай мудрість буде твоїм поводирем. Пам'ятай, світ стає кращим тільки тоді, коли ти робиш його таким.", ["en"] = "Hallowed Letter", ["tasks"] = { ["Hallowed Letter"] = "священний лист", ["Hallowed Letter (Provided)"] = "священний лист (видано)" } },
    [3104] = { [1] = "Гліфічний лист", [2] = "Мене попросили передати тобі цього листа, щойно ти повернешся з табору кобольдів, {ім'я:к}. Здається, на цьому листі стоїть печатка Хелдена, нашого тренера магів. На твоєму місці, я б не зволікав і прочитав би листа до того, як відправитись далі у справах абатства.", [3] = "Прочитайте гліфічний лист та поговоріть з Хелденом Бременом у Північнокрайовому абатстві.", [4] = "Привіт, {ім'я:к}. Я Хелден. Чи можу я чимось допомогти?", [5] = "Ха-ха, я знав що моя записка не зіб'є тебе з власного шляху. Тож, ти {стать:готовий:готова}, чи не так? {стать:Готовий:Готова} прийняти свою долю? {стать:Готовий:Готова} кинути виклик богам або будь-якій іншій силі яка стане перед тобою у пошуках знань та сили?\n\nНе буду брехати, {ім'я:к}, тебе будуть боятися так само сильно, як і поважати. Але також знай, що я буду тут, коли ти потребуватимеш навчання. Просто знайди мене, коли станеш {стать:сильнішим:сильнішою}.", ["en"] = "Glyphic Letter", ["tasks"] = { ["Glyphic Letter"] = "гліфічний лист", ["Glyphic Letter (Provided)"] = "гліфічний лист (видано)" } },
    [3105] = { [1] = "Заплямований лист", [2] = "Мене попросили передати тобі цього листа, щойно ти повернешся з табору кобольдів, {ім'я}. Здається, на цьому листі стоїть печатка Друсілли, однієї з наших місцевих тренерів. На твоєму місці, я б не зволікав і прочитав би листа до того, як відправитись далі у справах абатства.", [3] = "Прочитайте заплямований лист та поговоріть з Друсіллою ла Салле в Північнокрайовому абатстві.", [4] = "А, от ти й {стать:прийшов:прийшла}, і не {стать:забарився:забарилася}, {ім'я}. Щойно тут проходили вартові й підозріло поглядали на мене... жалюгідні простаки.", [5] = "Коли твоя сила буде зростати, твоя спокуса буде сильнішою... Ти {стать:повинен:повинна} завжди контролювати себе. Не буду брехати — псування може заволодіти будь-ким, хто практикує магію, особливо тим, хто має справу з істотами з Підсвітньої Круговерті. Будь {стать:терплячим:терплячою} та {стать:обачним:обачною}... але не дозволяй цьому пригнічувати свої амбіції.\n\nКоли ти станеш {стать:сильнішим:сильнішою} — повертайся до мене, і я розповім тобі більше про наші шляхи.", ["en"] = "Tainted Letter", ["tasks"] = { ["Tainted Letter"] = "заплямований лист", ["Tainted Letter (Provided)"] = "заплямований лист (видано)" } },
    [3106] = { [1] = "Проста руна", [2] = "Мені принесли цю руну, поки ти {стать:займався:займалась} вовками і попросили передати тобі. Прочитай її, як матимеш нагоду. Здається, вона від Трана, тренера воїнів. Ти знайдеш його в Ковмарі.", [3] = "Прочитайте просту руну і поговоріть з Траном Хорманом в Морозній долині.", [4] = "Ох і морозно ж сьогодні, еге ж? Схоже, цей сніг ніколи не розтане, {ім'я}.\n\nДумаю, ти вже {стать:помітив:помітила}, що тут з нами оселились гноми. Вони підірвали свій власний дім. тому й прибилися до нас. Але знаєш, що? Я їх не засуджую. Я б і сам підірвав Залізогарт якби його заполонило Темне Залізо чи ще яка нечисть...", [5] = "Що ти, певне, теж {стать:міг:могла} помітити, так це дворфів, що використовують магію замість зброї. Хтось поклоняється священним силам світла, як і деякі люди і навіть троги. Та про них ти дізнаєшся більше згодом, а зараз я тут щоб допомогти тобі в навчанні.\n\nЯ зроблю з тебе {стать:справжнього:справжню} {клас:з}. Як знадобляться мої уроки - приходь в будь-який час.", ["en"] = "Simple Rune", ["tasks"] = { ["Read the Simple Rune and speak to Thran Khorman in Coldridge Valley."] = "Прочитайте просту руну й поговоріть із Траном Хорманом у Морозній долині.", ["Simple Rune"] = "проста руна", ["Simple Rune (Provided)"] = "проста руна (видано)" } },
    [3107] = { [1] = "Освячена руна", [2] = "Мені принесли цю руну, поки ти {стать:займався:займалась} вовками та попросили передати тобі. Прочитай її, як матимеш нагоду. Здається, вона від Бромоса, тренера паладинів. Ти знайдеш його в Ковмарі.", [3] = "Прочитайте освячену руну та поговоріть з Бромосом Ґруммнером в Морозній долині.", [4] = "Отож, ти тут! І дуже вчасно. На тебе чекає багацько діянь в Морозній долині та за її межами. Мені може знадобитись твоя допомога, як і тобі, безперечно, знадобиться моя!\n\nТепер ти {стать:один:одна} з лицарів Сріблястої Десниці, не забувай про це.", [5] = "Люди багато чого розповіли нам про Священне Світло і про те, як орден паладинів необхідний їм... і всьому Азероту. Ми глибоко поважаємо традиції ордену. Воістину вражає, як одна людина, одна жертва може навернути смерть на спасіння.\n\nДумаю, нам обом доведеться трохи попрацювати разом. Коли ти вирішиш, що час настав, повертайся до мене. Тобі треба буде навчитися чомусь новому, перш ніж братися за справу. Негідно рушати у світ непідготовленим, правда ж?", ["en"] = "Consecrated Rune", ["tasks"] = { ["Consecrated Rune"] = "освячена руна", ["Consecrated Rune (Provided)"] = "освячена руна (видано)" } },
    [3108] = { [1] = "Гравійована руна", [2] = "Мені принесли цю руну, поки ти {стать:займався:займалась} вовками та попросили передати тобі. Прочитай її, як матимеш нагоду. Здається, вона від Торґаса, тренера мисливців. Ти знайдеш його в Ковмарі.", [3] = "Прочитайте гравійовану руну та поговоріть з Торґасом Ґрімсоном в Морозній долині.", [4] = "О, нарешті ти {стать:прийшов:прийшла}! Радий тебе бачити! Сподіваюсь, мене не надто важко було знайти. Хе-хе!\n\nОснови нашого ремесла йдуть з наших звичаїв, {ім'я:к}. Вивчення шляхів, вистеження ведмедів в горах. Саме виживання вимагає неабиякої сміливості та здібностей. Ну, що думаєш, впораєшся?", [5] = "Ти маєш завжди пам'ятати про повагу до навколишнього світу. Вибір звіра, з яким ти будеш битись пліч-о-пліч, блиск твоєї зброї, вага обладунків, пронизливий холод вітру — все це те, без чого не обійдеться твоє життя.\n\nЯ зроблю все, що в моїх силах, щоб допомогти тобі, та все у твоїх руках. Як будеш {стать:готовий:готова} - приходь до мене. Я навчу тебе всього, що знаю.", ["en"] = "Etched Rune", ["tasks"] = { ["Etched Rune"] = "гравійована руна", ["Etched Rune (Provided)"] = "гравійована руна (видано)" } },
    [3109] = { [1] = "Зашифрована руна", [2] = "Мені принесли цю руну, поки ти {стать:займався:займалась} вовками та попросили передати тобі. Прочитай її, як матимеш нагоду. Здається, вона від Солма, тренера пройдисвітів. Ти знайдеш його в Ковмарі.", [3] = "Прочитайте зашифровану руну та поговоріть з Солмом Гарґріном в Морозній долині.", [4] = "Ти {стать:прийшов:прийшла}! Чудово!\n\nОстаннім часом у нас спостерігається приплив активності, тому я радий покластися на іще одного представника Залізогарту в наших рядах. Завдяки холодному лезу та тіні, ти завжди на крок попереду, і якщо ти тут, ти точно знаєш, що я маю на увазі!", [5] = "Хай там як, коли ти почнеш тинятися Морозною долиною, тобі явно знадобиться тренування. Просто повертайся до мене, коли відчуєш, що тобі це потрібно, і я навчу тебе усього що я знаю: трюк тут, випад там. Ну, ти знаєш, штукенції, які допоможуть тобі вижити та заробити копієчку.\n\nПриглядай за нашими друзями-гномами... вони трошки пригнічені через... руйнування Гномреґану. Їм знадобиться наша допомога, щоб відчути себе як вдома.", ["en"] = "Encrypted Rune", ["tasks"] = { ["Encrypted Rune"] = "зашифрована руна", ["Encrypted Rune (Provided)"] = "зашифрована руна (видано)" } },
    [311] = { [1] = "Повернення до Марлет", [2] = "Підсунувши барильце пекучої бражки Марлет у підвал винокурні в Хараносі ви хапаєте барильце громузвару як доказ...", [3] = "Принесіть барильце громузвару Марлет Ячміновар в селище Всезвар.", [4] = "Ти {стать:зробив:зробила} підміну?", [5] = "Непогано, {ім'я}! Тобі, мабуть, нелегко було прослизнути повз їх охорону?\n\nБайдуже — красно дякую, і якщо тобі колись знадобиться міцне пекуче пиво, згадай Ячміноварів!", ["en"] = "Return to Marleth", ["tasks"] = { ["Barrel of Thunder Ale"] = "барильце громузвару", ["Barrel of Thunder Ale (Provided)"] = "барильце громузвару (видано)" } },
    [3110] = { [1] = "Священна руна", [2] = "Мені принесли цю руну, поки ти {стать:займався:займалась} вовками та попросили передати тобі. Прочитай її, як матимеш нагоду. Здається, вона від Бранстока, тренера жерців. Ти знайдеш його в Ковмарі.", [3] = "Прочитайте священну руну та поговоріть з Бранстоком Халдером в Ковмарі.", [4] = "Йой! Ти {стать:прийшов:прийшла}, {ім'я}. Чудово!\n\nЧесно кажучи, я вже втратив віру в те, що ти взагалі прийдеш... дійшло, втратив віру? Це жарт, {стать:хлопче:дівчино}... ай, забудь. Ти ж не {стать:прийшов:прийшла} сюди, щоб слухати мої дурні жарти.", [5] = "Я — той, хто буде тренувати тебе, щоб ти {стать:зміг:змогла} освоїтись в Морозній долині. Коли відчуєш, що ти {стать:готовий:готова}, повертайся до мене, і можливо я навчу тебе кількох фокусів, щоб позбутися цих бісових трогів у долині.\n\nСвітло з тобою, {ім'я}, як і весь Залізогарт... ніхто не вимагає, щоб ти {стать:досяг:досягла} чогось особливого.", ["en"] = "Hallowed Rune", ["tasks"] = { ["Hallowed Rune"] = "священна руна", ["Hallowed Rune (Provided)"] = "священна руна (видано)" } },
    [3112] = { [1] = "Проста директива", [2] = "Мені принесли цю директиву, поки ти {стать:займався:займалась} вовками та попросили передати тобі. Прочитай її, як матимеш нагоду. Здається, вона від Трана, тренера воїнів. Ти знайдеш його в Ковмарі.", [3] = "Прочитайте просту директиву та поговоріть з Траном Хорманом в Морозній долині.", [4] = "О, хто це тут в нас? Ще {стать:один:одна} {раса} з вказівкою. Цікаво...\n\nНі-ні, я не наміряюсь дражнити тебе, {стать:малий:мала}. Я дуже поважаю твою наполегливість. Те, що трапилось з Гномреґаном - це як би дворфи Темного Заліза заволоділи Залізогартом. Тож не думай, що твоя біда мені геть чужа.", [5] = "Що ж, раз це твоя головна директива, чи як там, даю слово - я зроблю все, що в моїх силах, щоби ти {стать:зумів:зуміла} допомогти своїм побратимам повернути свою домівку.\n\nЯк будеш {стать:готовий:готова} - дибай сюди і я з радістю навчу тебе новим навичкам. Ясна річ, не за спасибі, але не хвилюйся - мій прейскурант не кусається. Хай тобі щастить.", ["en"] = "Simple Memorandum", ["tasks"] = { ["Simple Memorandum"] = "проста директива", ["Simple Memorandum (Provided)"] = "проста директива (видано)" } },
    [3113] = { [1] = "Зашифрована директива", [2] = "Мені принесли цю директиву, поки ти {стать:займався:займалась} вовками та попросили передати тобі. Прочитай її, як матимеш нагоду. Здається, вона від Солма, тренера пройдисвітів. Ти знайдеш його в Ковмарі.", [3] = "Прочитайте зашифровану директиву та поговоріть з Солмом Гарґріном в Морозній долині.", [4] = "Радий бачити, що ти {стать:отримав:отримала} мою записку та {стать:прийшов:прийшла}. Вибач, що я підробив директиву так, наче вона була від твого керівництва... без образ. Я просто знав, що нам, разом з іншими такими, як ми, потрібно триматися разом.\n\nБагато хто скаже, що два пройдисвіти в одному місці — це не надто добре, але я вважаю, що ми гарно спрацюємося. Що скажеш?", [5] = "Я стараюся сильно не привертати уваги, щоб нас не звинувачували у зникненні речей, але якщо тобі щось знадобиться — тренування, або будь-що — приходь в будь-який час.\n\nМи з тобою розуміємо одне одного. Ми знаємо, що коли настають лихі часи, єдині кому ми можемо довіряти — це сім'я... зараз як раз такі часи, еге ж? Не дивлячись на те що, Гномреґан... захоплений, і не дивлячись на те, що ще трапиться на нашому шляху, ми завжди прикриємо одне одного. Чи не так?", ["en"] = "Encrypted Memorandum", ["tasks"] = { ["Encrypted Memorandum"] = "зашифрована директива", ["Encrypted Memorandum (Provided)"] = "зашифрована директива (видано)" } },
    [3114] = { [1] = "Гліфічна директива", [2] = "Мені принесли цю руну, поки ти {стать:займався:займалась} вовками та попросили передати тобі. Прочитай її, як матимеш нагоду. Здається, вона від Марріка, тренера магів. Ти знайдеш його в Ковмарі.", [3] = "Прочитайте гліфічну директиву та поговоріть з Марріком Нуррібітом у Ковмарі над Морозною долиною.", [4] = "Так, чого тобі, {раса:к}? І, будь ласка, говори голосніше. Мій слух притупляється після кількох кухлів елю.", [5] = "О, так! Арканічне мистецтво...звичайно.\n\nОсь, що тобі потрібно знати, {ім'я:к}: не вляпуйся у проблеми. Прибережи декілька монет, щоб купити мені елю... або будь-яке закляття, якому ти {стать:хотів би:хотіла б} навчитись. І тримайся якомога далі від Гномреґану. Якщо ти все {стать:зрозумів:зрозуміла} — гарного тобі дня! Я буду тут, якщо знадоблюся тобі, чи захочеш потренуватися... чи ще щось.", ["en"] = "Glyphic Memorandum", ["tasks"] = { ["Glyphic Memorandum"] = "гліфічна директива", ["Glyphic Memorandum (Provided)"] = "гліфічна директива (видано)" } },
    [3115] = { [1] = "Заплямована директива", [2] = "Мені принесли цю директиву, поки ти {стать:займався:займалась} вовками та попросили передати тобі. Прочитай її, як матимеш нагоду. Здається, вона від Аламара, тренера чорнокнижників. Ти знайдеш його в Ковмарі.\n\nІ будь {стать:обережний:обережна}, {ім'я} — таким, як ти, тут не надто довіряють.", [3] = "Прочитайте забруднену директиву і поговоріть з Аламаром Гріммом в Ковмарі над Морозною долиною.", [4] = "Чудово! Очевидно, ти {стать:отримав:отримала} мою директиву.\n\nНе звертай уваги на дурнів навколо, {ім'я}. Святе Світло?! Меч і щит?! Це не шлях тих, хто має такий відкритий розум, як ми. Подивись, що \"нормальна\" магія зробила з нашим домом. Через цих клятих штукарів наша раса майже вимерла. А тепер нам доводиться покладатися на дворфів — та їм більше по душі брататись з людьми, ніж допомагати нам відновлювати наш власний дім. Ми — як громадяни другого сорту. Ти {стать:бачив:бачила}, як вони на нас дивляться?", [5] = "Але все це не має значення. Важливо, щоб ти {стать:бачив:бачила} своє власне Святе Світло! Ти знаєш, звідки насправді походить сила. Ти розумієш, що мати своїх власних союзників набагато... розумніше. Особливих союзників. Союзники, які, незалежно від завдання, будуть виконувати твої накази до останнього подиху.\n\nІ ось тому я тут, {ім'я}. Я можу навчити тебе основ цієї сили. Навідуйся до мене, і я зроблю все можливе, щоб дати тобі більше знань.", ["en"] = "Tainted Memorandum", ["tasks"] = { ["Tainted Memorandum"] = "заплямована директива", ["Tainted Memorandum (Provided)"] = "заплямована директива (видано)" } },
    [3116] = { [1] = "Проста сигіла", [2] = "Цю сигілу передав мені посланець від тренерки воїнів, Алійссії. Схоже, що вона хоче про щось з тобою поговорити. Прочитай сигілу і йди до неї.", [3] = "Прочитайте просту сигілу та поговоріть з Алійссією в Тінистій долині.", [4] = "Ти {стать:прийшов:прийшла}. Я так рада тебе бачити.\n\nБагато чого сталося тут за останні кілька років, {ім'я}: створення Тельдрассілю, псування багатьох лісових створінь, відкриття земель, які ми вважали назавжди втраченими, як, наприклад, Фералас... Так багато всього і так швидко. Однак це не найважливіша причина нашого перебування тут. Найважливіше — захистити наш народ від прийдешнього зла.", [5] = "Скоро ти зустрінешся з представниками інших рас на гілках нашої домівки. Та не стався до них упереджено — вони бажані гості в наших краях і допомагають нам. Не всі вони роблять це без вигоди для себе, але деяким з них можна довіритись.\n\nТа це наразі не так важливо. Ми маємо зосередитись на тобі та на тому, як ти будеш допомагати нашому народу. Я тут не просто так. Я буду вчити тебе майстерності {клас:р} в міру того, як ти здобуватимеш досвід у своїх пригодах. Повертайся до мене в будь-який час і я допоможу тобі.", ["en"] = "Simple Sigil", ["tasks"] = { ["Simple Sigil"] = "проста сигіла", ["Simple Sigil (Provided)"] = "проста сигіла (видано)" } },
    [3117] = { [1] = "Гравійована сигіла", [2] = "Цю сигілу передав мені посланець від тренерки мисливців, Аянни. Схоже, що вона хоче про щось з тобою поговорити. Прочитай сигілу і йди до неї.", [3] = "Прочитайте гравійовану сигілу і поговоріть з Аянною Вічнохід на вершині Альдрассіля в Тінистій долині.", [4] = "Ти {стать:прийшов:прийшла}. І дуже вчасно, {ім'я:к}. Вітаю у Тінистій долині.\n\nСхоже, що моя сигіла знайшла тебе.\n\nЯк я вже казала, я буду навчати тебе, {клас:к}. Ти навчишся приручати звірів, з якими будеш битись пліч-о-пліч, стріляти з лука з надзвичайною точністю та поважати землі, що ми називаємо домом та ті, що лежать поза ними.", [5] = "Як здобудеш вдосталь досвіду в Тінистій долині — приходь навчатись до мене, я навчу тебе всього, що належить знати {клас:д}.\n\nВ ці важкі часи, {ім'я:к}, цінуй своїх супутників — цей світ приховує небезпеки, про які ти не здогадуєшся. Хай тебе береже Елуна у твоїх подорожах. Побачимось.", ["en"] = "Etched Sigil", ["tasks"] = { ["Etched Sigil"] = "гравійована сигіла", ["Etched Sigil (Provided)"] = "гравійована сигіла (видано)" } },
    [3118] = { [1] = "Зашифрована сигіла", [2] = "Цю сигілу передав мені посланець від тренера пройдисвітів, Фрагуна. Схоже, що він хоче про щось з тобою поговорити. Прочитай сигілу і йди до нього.", [3] = "Прочитайте зашифровану сигілу та поговоріть з Фрагуном Тінешепотом в Тінистій долині.", [4] = "Привіт, {ім'я}. Я радий, що ти {стать:знайшов:знайшла} мене. Я вже подумав, що ти {стать:загубився:загубилася} по дорозі сюди.\n\nНічого нового не відбувалося в Тінистій долині відтоді, як я надіслав тобі свою сигілу, але я залишу збір інформації на тебе. Поговори з мешканцями Альдрассіля, якщо бажаєш.", [5] = "А до тих пір знай, що наші послуги потрібні як ніколи, особливо в ці похмурі часи. Мир з іншими расам може у будь-який момент порушитися і ходять чутки про членів Орди, що намагаються посіяти зерна недовіри. Пам'ятайте про це.\n\nКоли ти наберешся сили та будеш відчувати себе більш {стать:підготовленим:підготовленою} — приходь до мене, і я потурбуюся про твоє навчання. Це важливо, коли поміж інших речей, ти знаєш як впоратися зі своєю обраною зброєю.", ["en"] = "Encrypted Sigil", ["tasks"] = { ["Encrypted Sigil"] = "зашифрована сигіла", ["Encrypted Sigil (Provided)"] = "зашифрована сигіла (видано)" } },
    [3119] = { [1] = "Священна сигіла", [2] = "Цю сигілу передав мені посланець від тренерки жерців, Шанди. Схоже, що вона хоче про щось з тобою поговорити. Прочитай сигілу і йди до неї.", [3] = "Прочитайте священну сигілу та поговоріть з Шандою в Альдрассолі.", [4] = "Рада бачити, що ти {стать:прийшов:прийшла} так швидко, {ім'я}. Ласкаво прошу.\n\nЯк ти вже {стать:міг:могла} чути, в Тельдрассіль постійно прибувають мандрівники. Навіть членам Альянсу було дозволено ступати на гілки Тедрасілля для того, щоб зустрітися з калдорай, які готуються до майбутніх пригод.", [5] = "Поки що не переймайся про світ за межами Тельдрассіля. У тебе іще буде час на це у майбутньому. Іди та поговори з іншими в Тінистій долині — вони розкажуть тобі більше про тутешні події. Допомагай їм усім, чим можеш, а коли відчуєш, що тобі потрібно більше тренувань — повертайся до мене і я навчу тебе всього, що знаю сама.", ["en"] = "Hallowed Sigil", ["tasks"] = { ["Hallowed Sigil"] = "священна сигіла", ["Hallowed Sigil (Provided)"] = "священна сигіла (видано)" } },
    [3120] = { [1] = "Вкрита мохом сигіла", [2] = "Цю сигілу передав мені посланець від тренера друїдів, Марданта. Схоже, що він хоче про щось з тобою поговорити. Прочитай сигілу і йди до нього.", [3] = "Прочитайте вкриту мохом сигілу та поговоріть з Мардантом Міцнодубом на дереві Альдрассіль в Тінистій долині.", [4] = "Ах, {стать:юний:юна} {клас}. Бачу, ти прагнеш навчатись. Добре.\n\nА ти вже знаєш про Смарагдовий Сон? Хоча, тобі певно ще зарано... Всьому свій час.\n\nТа до того, нам є про що поговорити.", [5] = "Поки що я буду твоїм наставником. Мій обов'язок — не тільки навчити тебе розуміти духів, а й познайомити тебе з таємницями Смарагдового Сну.\n\nКоли матимеш достатньо досвіду й сили — ти дізнаєшся більше про занурення в сон. Та до тих пір приходь до мене і я навчу тебе всього необхідного.", ["en"] = "Verdant Sigil", ["tasks"] = { ["Verdant Sigil"] = "вкрита мохом сигіла", ["Verdant Sigil (Provided)"] = "вкрита мохом сигіла (видано)" } },
    [313] = { [1] = "Посивіле лігво", [2] = "Керування облоговою машиною не кожному під силу. Це потребує міцної хватки та сталевих нервів. На щастя, в мене є і те, й інше! А в тебе? Кишка не тонка? Хочеш довести це мені?\n\nГаразд... Я хочу зробити свою машину, Тролевкладальника, трішки зручнішою. Не дістанеш мені оберемок грив вендиго з Посивілого лігва, що на захід від Хараноса? Ці гриви стануть чудовим килимком для кабіни Тролевкладальника!", [3] = "Принесіть 8 грив вендиго пілоту Камнеладу.", [4] = "Гей, {ім'я}. Вже ходив до Посивілого лігва? Ці вендиго - злющі створіння.", [5] = "О так, ці гриви згодяться! Ти міцний горішок, {клас:к}. Впевнений, я ще почую про тебе.", ["en"] = "The Grizzled Den", ["tasks"] = { ["Wendigo Mane"] = "грива вендиго", ["Wendigo Mane (Provided)"] = "грива вендиго (видано)" } },
    [3130] = { [1] = "Боротьба з кланом Гребеня Ненависті", [2] = "На цьому етапі я направляю тебе до мого заступника — Латроніка. Він уважно стежив за нагами. Хоч як би мені не хотілося завдати їм удару всіма наявними у нас силами, залишити фортецю беззахисною перед атаками Орди, здається мені не дуже розумним рішенням.\n\nХай там як, Латронік чекає на тебе. Ти {стать:проявив:проявила} себе хоробро, {ім'я}. Продовжуй в тому ж дусі.\n\nВільно.", [3] = "Поговоріть з Латроніком Місяцесписом у фортеці Перомісяць.", [5] = "Чудово, {ім'я} — я ціную готовність боротися у тих, з ким маю справу.\n\nГенерал Перомісяць доручила мені зайнятися нагами. Мої плани складаються з двох частин: по-перше, ми послабимо їх сили та позбавимо командування, а по-друге, ми з'ясуємо, що ж вони роблять у цих руїнах. З твоєю допомогою ми зможемо протидіяти нагам, не пожертвувавши безпекою фортеці.", ["en"] = "Against the Hatecrest" },
    [314] = { [1] = "Захист стада", [2] = "Ми почули крики посеред ночі. А сьогодні вранці, у стаді, дійсно, бракувало двох баранів. Цей зухвалий звір, відомий як Ваґаш, — загроза нашому джерелу існування. Оскільки більша частина армії короля Маґні перебуває в далеких краях, воюючи в складі Альянсу, немає кому розібратися з Ваґашем.\n\nМожливо, ти {стать:сміливий:смілива} на стільки, щоб вистежити та вбити звіра. Принеси мені одне з його ікол, і я віддячу тобі. Ваґаш ховається трохи вище ранчо, але будь {стать:обережний:обережна}, він смертоносний.", [3] = "Рудра Бурштинник хоче, щоб ви вбили Ваґаша і принесли його ікло на ранчо баранів.", [4] = "Ваґаш досі тероризує стадо! Будь ласка, допоможи нам, вбий цього жахливого звіра.", [5] = "Чудово виконано! Верон буде такий щасливий, коли почує добру новину. Вбити Ваґаша — завдання не з легких. Я думаю, одного дня ти будеш битися на передовій пліч-о-пліч з армією короля Маґні та силами Альянсу.", ["en"] = "Protecting the Herd", ["tasks"] = { ["Fang of Vagash"] = "ікло Ваґаша", ["Fang of Vagash (Provided)"] = "ікло Ваґаша (видано)" } },
    [315] = { [1] = "Ідеальний стаут", [2] = "Я тут по справі, а справа моя - зварити ідеальний стаут. Я знаю, що зможу - пивоваріння у мене в крові. Я лише маю скласти правильний рецепт...\n\nМорозогриві тролі високо на східних пагорбах вирощують одну травку, блискоквітом називається. Вони використовують її у чудакуватих ритуалах свого племені. Ми, дворфи, не знайшли їй ніякого застосування, однак вона має неповторний смак... І я хочу поекспериментувати з цим у броварстві!\n\nПринеси мені трішки блискоквіту. Ти знайдеш його у провидців Морозогривів або в трольських кошиках з травами.", [3] = "Принесіть 6 блискоквітів Реджольду Ячміновару в селище Всезвар.", [4] = "Ти добув блискоквіт? Я майже готовий варити нову партію і хочу спробувати кинути трішки цієї травички у вариво.", [5] = "Чудово! Аж не терпиться випробувати її в декількох моїх рецептах. Думаю, для цього вона найпаче підійде...", ["en"] = "The Perfect Stout", ["tasks"] = { ["Shimmerweed"] = "блискоквіт", ["Shimmerweed (Provided)"] = "блискоквіт (видано)" } },
    [317] = { [1] = "Доукомплектування паровика", [2] = "Я готуюсь до завдання штурмової бригади. Воно триватиме довго, тож я маю доукомплектувати паровика запасом припасів на місяць. Тож поки Сталешквар працює над моїм танком, можеш вполювати дещо для мене?\n\nМені знадобиться кілька шкур для ліжка та м'ясо кнура для провіанту. М'ясо з кнурів, хутро з ведмедів... Ти знайдеш їх на засніжених полях на південь від Посивілого лігва.", [3] = "Принесіть 4 шматки м'яса кнура та 2 товсті шкури ведмедя пілотові Беллофізу до Сховища Сталешквара.", [4] = "Підготовка проходить чудово. Як полювання?", [5] = "Клянусь бородою Маґні, оце ти добряче {стать:наполював:наполювала}! Дякую, {ім'я}.", ["en"] = "Stocking Jetsteam", ["tasks"] = { ["Chunk of Boar Meat"] = "Шматок м'яса кнура", ["Chunk of Boar Meat (Provided)"] = "шматок м'яса кнура (видано)", ["Thick Bear Fur"] = "Товста шкура ведмедя", ["Thick Bear Fur (Provided)"] = "товста шкура ведмедя (видано)" } },
    [318] = { [1] = "Вічногон", [2] = "Реджольд Ячміновар експериментує зі своїми варивами. Деякі з них мають гарний смак, деякі поганий, а деякі... ну, деякі вкладуть наповал всіх, окрім найміцнішого дворфа.\n\nВін живе у селищі Всезвар, на захід від Хараноса, і один з його напоїв, Вічногон, — це те, що мені треба. Він зігріє мене в дорозі.\n\nІ... цей благословенний напій горить так гаряче, що я можу кинути його в топку Парокоптера для сплеску енергії! Ця маленька хитрість допомагала мені вибиратися з багатьох небезпечних місць.", [3] = "Отримайте барильце Вічногону у Реджольда Ячміновара з селища Всезвар.", [5] = "Беллофізу потрібен мій Вічногон? Гм... гаразд.", ["en"] = "Evershine", ["tasks"] = { ["Get a Cask of Evershine from Rejold Barleybrew in Brewnall Village."] = "Отримайте барильце Вічногону у Реджольда Ячміновара з селища Всезвар.", ["Get a cask of Evershine from Rejold Barleybrew in Brewnall Village."] = "Отримайте барильце Вічногону у Реджольда Ячміновара з селища Всезвар." } },
    [319] = { [1] = "Послуга за Вічногон", [2] = "У мене є барильце Вічногону, але... {стать:міг би:могла б} ти зробити мені послугу? Селищу Всезвар не завадить допомога в боротьбі проти диких тварин, що блукають навколишніми снігами. Іноді вони підходять надто близько.\n\nМи не боїмося цих ведмедів, кішок і кнурів — жоден дворф, що поважає себе, не стане їх боятися, — але якби ти {стать:взяв:взяла} тих тварин на себе, у нас було б більше часу на ремесла і пивоваріння.", [3] = "Вбийте 6 льодолапих ведмедів, 8 старих скельних кнурів й 8 сніжних леопардів, а потім поверніться до Реджольда Ячміновара у селище Всезвар.", [4] = "Ти вже {стать:розібрався:розібралася} з тими дикими тваринами?", [5] = "Дяка, {ім'я}. Добре буде зайнятися ремеслом без цього ричання та хрюкання за селом.", ["en"] = "A Favor for Evershine", ["tasks"] = { ["Elder Crag Boar"] = "старий скельний кнур", ["Elder Crag Boar slain"] = "старий скельний кнур: убито", ["Ice Claw Bear"] = "льодолапий ведмідь", ["Ice Claw Bear slain"] = "льодолапий ведмідь: убито", ["Snow Leopard"] = "сніжний леопард", ["Snow Leopard slain"] = "сніжний леопард: убито" } },
    [320] = { [1] = "Повернення до Беллофіза", [2] = "Ось твоє барильце Вічногону, {ім'я}. І ще раз дякую тобі за полювання.", [3] = "Віддайте барильце Вічногону пілоту Беллофізу в Сховищі Сталешквара.", [4] = "{стать:Надибав:Надибала} Вічногон?", [5] = "Так, цього буде цілком достатньо. Гадаю, я просто зараз відкрию пляшку і скуштую ...", ["en"] = "Return to Bellowfiz", ["tasks"] = { ["Cask of Evershine"] = "барильце Вічногону", ["Cask of Evershine (Provided)"] = "барильце Вічногону (видано)" } },
    [323] = { [1] = "Доказ сили", [2] = "Морбент Скверн — некромант і союзник темних вершників. Я не можу послати тебе на битву з ним, не випробувавши твою силу.\n\nТи вже {стать:довів:довела} свою хоробрість, але якщо ти справді бажаєш зіткнутися з некромантом, то тобі потрібно проявити свою майстерність проти його прислужників.", [3] = "Вбийте 15 скелетних нальотників, 3 скелетних цілителів і 3 скелетних чатових, а потім поверніться до Свена.", [4] = "Борись до кінця, {ім'я}. І не впадай у відчай, бо відчай — найсильніша зброя зла.", [5] = "У твоїй майстерності в бою не доводиться сумніватися, {ім'я}. Твоя рішучість, можливо, ще допоможе нам проти Морбента Скверна!", ["en"] = "Proving Your Worth", ["tasks"] = { ["Skeletal Healer"] = "скелетний цілитель", ["Skeletal Healer slain"] = "скелетний цілитель: убито", ["Skeletal Raider"] = "скелетний нальотник", ["Skeletal Raider slain"] = "скелетний нальотник: убито", ["Skeletal Warder"] = "скелетний чатовий", ["Skeletal Warder slain"] = "скелетний чатовий: убито" } },
    [324] = { [1] = "Втрачені злитки", [2] = "Ви забрали злиток світлосталі зі скрині, але очевидно, що інші злитки були викрадені мурлоками. Знайдіть мурлоків-рейдерів біля розбитого корабля \"Летюча Скопа\" та відберіть у них злитки світлосталі.", [3] = "Зберіть 5 злитків світлосталі, а потім поверніться до Ґлоріна Сталеброва в Заболоття.", [4] = "Ти {стать:знайшов:знайшла} злитки світлосталі?", [5] = "А, ти їх {стать:знайшов:знайшла}! Тепер перетворімо ці злитки світлосталі на щось корисне, га?", ["en"] = "The Lost Ingots", ["tasks"] = { ["Lightforge Ingot"] = "злиток світлосталі", ["Lightforge Ingot (Provided)"] = "злиток світлосталі (видано)" } },
    [325] = { [1] = "Озброєний і готовий", [2] = "Ось зброя проти ворога, про якого ти {стать:говорив:говорила}. Ти {стать:готовий:готова}, {ім'я}. Успіхів тобі, і я з нетерпінням чекатиму на твою історію!", [3] = "Принесіть прокляття Морбента до Свена у Смерколісся.", [4] = "Привіт, {ім'я}. Давненько тебе не було, тепер я бачу вогонь у твоїх очах, якого не бачив раніше.", [5] = "А, це зброя проти Морбента Скверна! Так тримати!\n\nТи {стать:готовий:готова}. І ти здолаєш Морбента Скверна.", ["en"] = "Armed and Ready", ["tasks"] = { ["Morbent's Bane"] = "прокляття Морбента", ["Morbent's Bane (Provided)"] = "прокляття Морбента (видано)" } },
    [33] = { [1] = "Вовки за порогом", [2] = "Я ненавиджу цих мерзенних сірих вовків! Але я дуже люблю їсти вовчі стейки... Принеси мені жорстке вовче м'ясо, і я обміняю на нього щось корисне для тебе.\n\nЖорстке вовче м'ясо можна здобути з сірих і молодих вовків, що блукають лісами Північнокраю.", [3] = "Принесіть 8 шматків жорсткого вовчого м'яса Іґанові Гарбару неподалік Північнокрайового абатства.", [4] = "Агов, {ім'я:к}. Я зголоднів... Чи {стать:приніс:принесла} ти мені жорсткого вовчого м'яса?", [5] = "Бачу, ти час дарма не {стать:гаяв:гаяла}! Уже не можу дочекатися, щоб приготувати це вовче м'ясце...\n\nЯ тут маю декілька речей, які ти, можливо, захочеш — обирай!", ["en"] = "Wolves Across the Border", ["tasks"] = { ["Tough Wolf Meat"] = "жорстке вовче м'ясо", ["Tough Wolf Meat (Provided)"] = "жорстке вовче м'ясо (видано)" } },
    [332] = { [1] = "Реклама винної крамниці", [2] = "Якщо ти заговориш з будь-ким про вино, то дізнаєшся, що Ґелліни продають найкраще вино у Штормовії. І ми недалеко розташовані, у Торговому районі, уздовж милих міських каналів.\n\nОсь, візьми цю брошуру. Передай моїй сестрі Сузетті в нашій крамниці, щоб отримати безкоштовну пляшку нашого відомого піно-нуару. Ти не пошкодуєш!", [3] = "Йдіть до винарні Ґеллінів, і передайте Сузетті Ґелліні винний квиток на безкоштовну пляшку вина.", [4] = "Вітаємо і ласкаво просимо, {стать:сір:мадам}. Ви вже скуштували одне з наших чудових вин?", [5] = "О, то ви бачилися з Ренато? Ось, тримайте, {стать:сір:мадам}. Пляшка нашого особливого піно-нуару. Ви не знайдете нічого подібного у всьому Азероті!", ["en"] = "Wine Shop Advert", ["tasks"] = { ["Wine Ticket"] = "винний квиток", ["Wine Ticket (Provided)"] = "винний квиток (видано)" } },
    [333] = { [1] = "Гарлану потрібна нова поставка", [2] = "Останнім часом у нас повно роботи. Здається, всі купують обладунки та міцний одяг, ніби очікують холодної й суворої пори...\n\nАле це проблеми майбутнього. Зараз мене хвилює те, що в мене закінчується в'язаний одяг. Мені потрібна ще одна партія від нашого постачальника.\n\nЯкщо ти зможеш передати цей запит Ремі Шнайдер у кравецьку крамницю, що біля каналів, я буду дуже вдячний.", [3] = "Ідіть до крамниці кравця біля каналів Штормовію і принесіть Ремі Шнайдер запит на тканину від Гарлана Баґлі.", [4] = "Ти від пана Баґлі?", [5] = "Тут сказано, що бізнес Гарлана процвітає. Це гарна новина, але я дивуюся, навіщо людям потрібні всі ці обладунки. Я нічого не чула про нову війну... невже вельможі щось приховують від нас?\n\nНу, дякую, що {стать:приніс:принесла} запит. Ось твоя плата, а я подбаю про те, щоб Гарлан отримав свої матеріали.", ["en"] = "Harlan Needs a Resupply", ["tasks"] = { ["Cloth Request"] = "запит на тканину", ["Cloth Request (Provided)"] = "запит на тканину (видано)" } },
    [334] = { [1] = "Пакунок для Турмана", [2] = "Мій син Турман — учень в \"сукнах Ларсона\", що у кварталі магів. Він сьогодні поспішав і забув свої голки й ножиці. Певно у {стать:такого:такої} {клас:р}, як ти, є важливіші справи, та без своїх інструментів Турман не зможе займатись шиттям!\n\nПрошу, {ім'я:к}, віднеси йому швацький набір. \"Сукна Ларсона\" — одна з двох швацьких крамниць у кварталі магів. Це та, що поглибше, біля вежі магів.", [3] = "Відправляйтесь в \"сукна Ларсона\", що у кварталі магів Штормовія та віддайте Турману Шнайдеру його швацький набір.", [4] = "Вітаю! Бажаєте щось купити?", [5] = "Ой, ле! Я думав, що, забувши інструменти, я зможу не працювати. Що ж, тепер доведеться допомагати Ларсону з пошиттям...\n\nНу що ж, певно, всьому свій час.", ["en"] = "Package for Thurman", ["tasks"] = { ["Thurman's Sewing Kit"] = "швацький набір Турмана", ["Thurman's Sewing Kit (Provided)"] = "швацький набір Турмана (видано)" } },
    [335] = { [1] = "Благородний напій", [2] = "Лорд Вішок викликав неабиякий переполох серед Дому вельмож. Йому повідомили про наші тутешні справи, і він добивається розслідування. У мене є план, як затримати Вішока, але мені потрібна твоя допомога.\n\nУ саду Сталвана на околиці Темнодолу росте квітка. Ця маленька біла квітка відома як сльоза Тіллої. Мені також знадобиться мускусний корінь, який можна знайти лише біля самого підніжжя водоспаду під Каменярською дамбою в Заболотті.", [3] = "Зардет Чорний Кіготь хоче, щоб ви принесли йому сльозу Тіллої з Темнодолу та мускусний корінь із Заболоття.", [4] = "Вішок незабаром отримає достатньо підтримки, щоб завдати нам багато проблем. Ти вже {стать:дістав:дістала} сльозу Тіллої та мускусний корінь?", [5] = "Дуже чудово! Це прекрасні екземпляри!", ["en"] = "A Noble Brew", ["tasks"] = { ["Musquash Root"] = "мускусний корінь", ["Musquash Root (Provided)"] = "мускусний корінь (видано)", ["Tear of Tilloa"] = "сльоза Тіллої", ["Tear of Tilloa (Provided)"] = "сльоза Тіллої (видано)" } },
    [3361] = { [1] = "Скрута біженця", [2] = "Ми вигнали трогів з Гномреґана, але потім все пішло шкереберть! Зараз наш дім повністю опромінений і ми, гноми, розкидані по всьому Дун-Морогу.\n\nЯ так поспішав втекти від радіації, що загубив всі свої речі та всі інструменти. А тролі прибрали все до рук. Вони вкрали мій ящик, скриню і навіть відро з болтами! Вони відтягли все до себе в табір, на південний захід від Ковмара.\n\nЯ зовсім не шукач пригод, чи не {стать:міг би:могла б} ти знайти мої речі та принести їх мені сюди, будь ласка?", [3] = "Принесіть в Ковмар коробку Фелікса, скриню Фелікса і відро з болтами Фелікса та віддайте все це Феліксові Вінделболту.", [4] = "Ой божечки, {ім'я}, це місто не дуже підходить для таких як я. Тут стільки ж кепських створінь, скільки їх було в Гномреґані до катастрофи!\n\nВ тебе є мої речі? Уявити собі не можу, що з ними могли зробити тролі...", [5] = "Урааа! Тобі вдалося знайти мої речі! Ти {стать:мій рятівник, друже:моя рятівниця, подруго}. Ось, тримай, — це небагато, але хоч якась винагорода за твої клопоти. Дякую!", ["en"] = "A Refugee's Quandary", ["tasks"] = { ["Felix's Box"] = "коробка Фелікса", ["Felix's Box (Provided)"] = "коробка Фелікса (видано)", ["Felix's Bucket of Bolts"] = "відро з болтами Фелікса", ["Felix's Bucket of Bolts (Provided)"] = "відро з болтами Фелікса (видано)", ["Felix's Chest"] = "скриня Фелікса", ["Felix's Chest (Provided)"] = "скриня Фелікса (видано)" } },
    [3364] = { [1] = "Доставлення пекучої ранкображки", [2] = "Га! Я вже повинен був доставити цю смаковиту пекучу ранкображку Дарнанові Хутростригу у Ковмар, та тільки спочатку мені потрібно було завезти трохи Ґреліну. Я жодним чином не встигну дістатись до Ковмара, перш ніж бражка охолоне!\n\nТи виглядаєш {стать:прудкішим:прудкішою} за мене; може ти б це {стать:зробив:зробила}? Кухоль залишиться гарячим ще хвилин п'ять, а Дарнан не замовляв \"холодну\" ранкображку, тому йди-но. Ковмар — поселення, що в скелях на північному сході.\n\nДякую {Ім'я}, і не забудь повернути мій кухоль!", [3] = "Віднесіть пекучу ранкображку Дарнану Хутростригу у Ковмар. Це треба зробити за п'ять хвилин, перш ніж вона охолоне!", [4] = "Ага, я Дарнан Хутростриг. Маєш щось для мене?", [5] = "От добре, зараз це те, що треба. Дозволь зробити невеликий перестанок, поки я насолоджуюся пекучою ранкображкою!", ["en"] = "Scalding Mornbrew Delivery", ["tasks"] = { ["Durnan's Scalding Mornbrew"] = "пекуча ранкображка Дарнана", ["Durnan's Scalding Mornbrew (Provided)"] = "пекуча ранкображка Дарнана (видано)", ["Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!"] = "Віднесіть пекучу ранкображку Дарнану Хутростригу в Ковмарі за п'ять хвилин, доки вона не охолола!" } },
    [3365] = { [1] = "Повернення кухля", [2] = "Це саме те, що треба! Немає нічого кращого ніж свіжа, гаряча — ні, ПЕКУЧА ранкображка в холодний зимовий день, щоб зігріти ваші душі.\n\nОсь, тримай, {ім'я}. Будь ласка, зроби хорошу справу для мене — поверни цей порожній кухоль Норі.", [3] = "Поверніть Норів кухоль Норі Гідношлямбуру.", [4] = "Сподіваюсь, що пекуча ранкображка потрапила до Дарнана вчасно! Ти {стать:не забув:не забула}, принести мій кухоль назад?", [5] = "Чудово, {ім'я}! Ти здивуєшся, дізнаючись скільки кур'єрів я зустрічав, що забувають зробити найпростіше — повернути кухоль. А кухлі не ростуть на деревах, наскільки мені відомо!\n\nОсь невелика винагорода за твої зусилля. Ще раз дякую за допомогу.", ["en"] = "Bring Back the Mug", ["tasks"] = { ["Nori's Mug"] = "Норів кухоль", ["Nori's Mug (Provided)"] = "Норів кухоль (видано)", ["Return Nori's Mug to Nori Pridedrift."] = "Поверніть Норів кухоль Норі Гідношлямбуру." } },
    [3367] = { [1] = "Камені Сантари", [2] = "<Дорій стогне.>\n\nМене важко поранили, {раса:к}. В голові... паморочиться... Певно, у мене внутрішня... кровотеча.\n\nЯ маю повернутись до Залізогарту. Допоможи мені, {ім'я}.", [3] = "Допоможіть Дорію повернутись до Залізогарту.", [4] = "Я не зможу дійти...", [5] = "Цей лист був випав з рук Дорія, коли його застрелили.", ["en"] = "Suntara Stones", ["tasks"] = { ["Dorius Escort"] = "Ескорт Доріуса" } },
    [337] = { [1] = "Стара історична книга", [2] = "Не дивлячись на те, що обкладинка цієї книги подряпана та брудна, слова \"Історія Штормовію\" все ще можливо прочитати на корінці. На першій сторінці чітко вибита печатка бібліотека Штормовію.\n\nСхоже, хтось взяв почитати цю книгу та так і не повернув...", [3] = "Поверніть книгу \"Історія Штормовію\" до Штормовійської бібліотеки", [4] = "О-о-о! Що це за стара книга у вас? Можу я переглянути її?", [5] = "Нічого собі! Цієї книги не бачили на полицях із часів відновлення Штормовію, багато років тому. Звісно, її доведеться реставрувати, вона у поганому стані, але я мав би честь розмістити її серед нашої колекції рідкісних книг.\n\nДякую вам, {стать:пане:пані}. Будь ласка, прийміть це як плату за повернення книги!", ["en"] = "An Old History Book", ["tasks"] = { ["An Old History Book"] = "стара історична книга", ["An Old History Book (Provided)"] = "стара історична книга (видано)" } },
    [3375] = { [1] = "Запасний фіал", [2] = "Ем... Тобі потрібен ще один фіал провидіння? Ти жартуєш, так? Що ти {стать:зробив:зробила} з першим?! У нас і так купа роботи, {раса:к}. Ці фіали на деревах не ростуть! Було б добре, звісно, якби росли, бо я б пішов туди й зірвав один, бо іншого у мене немає!!!\n\nДля того, щоб зробити новий, мені потрібно: зілля мани, шматочок вугілля і трохи солодкого нектару. Не питай навіщо, просто принеси, і я зроблю тобі новий.", [3] = "Принесіть зілля мани, вугілля та солодкий нектар Талвашу дель Кісселю в Залізогарт, щоб отримати новий фіал провидіння Талваша.", [4] = "Щоб зробити ще один фіал, мені потрібно зілля мани, шматочок вугілля і трохи солодкого нектару.\n\nІ купа терпіння.", [5] = "{стать:Могутній шукач:Могутня шукачка} пригод все {стать:приніс:принеслв}. Ура мені! До речі, я збрехав — у мене був запасний фіал. Ось, тримай.\n\nНу а чого ти {стать:очікував:очікувала}?! \"Ось, візьми ще одну! Мені ж робити більше нічого, як роздавати магічні пристрої зв'язку!\" Але ти не хвилюйся, усе, що ти мені {стать:приніс:принесла}, знадобиться, щоб виготовити ще один фіал, коли ти й цей загубиш.\n\nБудь ласка, доведи, що я помиляюся, і не загуби ще й цей, добре?", ["en"] = "Replacement Phial", ["tasks"] = { ["Coal"] = "вугілля", ["Coal (Provided)"] = "вугілля (видано)", ["Mana Potion"] = "зілля мани", ["Mana Potion (Provided)"] = "зілля мани (видано)", ["Sweet Nectar"] = "солодкий нектар", ["Sweet Nectar (Provided)"] = "солодкий нектар (видано)" } },
    [34] = { [1] = "Незваний гість", [2] = "Знову мій сад розтоптали й спаплюжили. І я знаю, що за свиня це творить. Це той чортів кнур, якого маршал Марріс прозвав Грубопузом.\n\nТепер я не зможу пересадити нарциси до наступного сезону. Зруйновано! Все зруйновано через одного дикого кабана! Поклади кінець шкіднику! Покажи мені його ікло і я радо вручу тобі нагороду. Зазвичай він риється на полі на південний захід від Приозер'я, але буває, заблукає у мій сад.", [3] = "Марті Джайнроуз із Приозер'я хоче, аби ви вбили Грубопуза. Принесіть його ікло як доказ.", [4] = "Грубопуз все ще там, чи тобі вдалось позбавити Приозер'я від цього шкідника раз і назавжди?", [5] = "Нарешті моєму саду нічого не загрожує! Дякую тобі, {ім'я:к}, ти {стать:зробив мені велику послугу:зробила мені велику послугу}. Наступного сезону сад повністю розквітне!", ["en"] = "An Unwelcome Guest", ["tasks"] = { ["Bellygrub's Tusk"] = "ікло Грубопуза", ["Bellygrub's Tusk (Provided)"] = "ікло Грубопуза (видано)" } },
    [343] = { [1] = "Трохи про стійкість", [2] = "Я скоро виступаю з промовою про стійкість духу і хотів би використати цитату з однієї металургійної книги - \"Гартування заліза\". Екземпляр цієї книги має бути в королівській бібліотеці, що в фортеці Штормовію. Зможеш дістати її для мене? Якщо так, нехай благословить тебе Світло!\n\nКоролівська бібліотека велика, та старший бібліотекар, Мільтон Сніп, знає бібліотеку як свої п'ять пальців. Поговори з ним, він тобі допоможе.", [3] = "Йдіть до королівської бібліотеки у фортеці Штормовію та поговоріть з Мільтоном Сніпом. Він допоможе знайти книгу з металургії, необхідну брату Крістоффу для промови.", [5] = "Книга з металургії? А, так, звісно, у нас багато таких книг і я буду радий допомогти брату Крістоффу з його промовою! Що ж... яка книга його цікавить?", ["en"] = "Speaking of Fortitude" },
    [3445] = { [1] = "Затонулий храм", [2] = "Я чув про місце, яке лежить глибоко під поверхнею землі — вигнане туди силами, яких я ніколи не бачив.\n\nЯкщо ти хочеш дізнатися більше про це місце — Затонулий Храм, знайди гобліна, на ім'я Марвон Заклепник. Він досліджував багато стародавніх регіонів світу, і востаннє, як відомо, покинув свій дім у Брашпилі, щоб дослідити руїни тролів у Танарісі.\n\nУспіхів тобі у його пошуках, про нього вже давно нічого не чути.", [3] = "Знайдіть Марвона Заклепника в Танарісі.", [5] = "Так, Затонулий храм, можу сказати, що бачив його на власні очі. Можливо, ти {стать:хотів би:хотіла б} почути про нього більше?\n\nТи {стать:схожий:схожа} на {стать:любителя:любительку} пригод — я знаю дещо, що зможе тебе зацікавити...", ["en"] = "The Sunken Temple" },
    [345] = { [1] = "Поставки чорнил", [2] = "Я збирався закінчити свій примірник \"Гартування заліза\", але...\n\nРозумієш, я використовую власне чорнило для своїх книг. Це мій власний рецепт — не розтікається, не розмазується і дуже швидко висихає. Навіть занадто швидко. Моя остання партія висохла перш ніж я встиг завершити копію, і я не міг зробити більше чорнила.\n\nЩоб зробити ще, мені потрібна ретбанська залізна руда з Багрянокряжових гір. Десятник Ослоу в Приозер'ї — мій постачальник.", [3] = "Поговоріть з десятником Ослоу в Приозер'ї та запитайте у нього про ретбанську залізну руду.", [5] = "Що тобі треба?? Може ти не {стать:помітив:помітила}, але ми зайняті підсиленням оборони Приозер'я та відновленням від нещодавніх нападів орків. Якщо тобі потрібна ретбанська залізна руда, тобі доведеться її добувати самостійно!", ["en"] = "Ink Supplies" },
    [347] = { [1] = "Ретбанська руда", [2] = "Ретбанська руда названа на честь її першовідкривача — Барта Ретбана. З неї виплавляється матеріал, дещо м'якший за залізо та з насиченим темним кольором, за що й ціниться писарями.\n\nЗазвичай ми маємо вдосталь запасів, та зараз ми зайняті підготовкою до нападу орків. Крім того, в ретбанських печерах поселились багрянокряжові гноли і їх чорнороби копають руду.\n\nОтож, якщо вона тобі потрібна — ти знаєш як її дістати.", [3] = "Зберіть 5 шматків ретбанської руди та принесіть їх брату Пакстон в бібліотеку Північнокраю.", [4] = "Ти {стать:приніс:принесла} ретбанську руду?", [5] = "О, чудово! Я зможу зробити з цієї руди барвник і нарешті завершити копію \"Гартування заліза\".\n\nДякую, {ім'я}!", ["en"] = "Rethban Ore", ["tasks"] = { ["Rethban Ore"] = "ретбанська руда", ["Rethban Ore (Provided)"] = "ретбанська руда (видано)" } },
    [35] = { [1] = "Нові турботи", [2] = "Якщо ти також {стать:стурбований:стурбована} чутками про мурлоків, тоді зробімо так: іди до східного Ельвиннського мосту та поговори з вартовим Томасом. Весь минулий тиждень він чергував в тому районі, тож має бути в курсі подій.\n\nІ принеси мені його звіт.", [3] = "Маршал Дуган хоче, щоб ви поговорили з вартовим Томасом.", [5] = "Так, мурлоки оселилися в водах східного Ельвинна та навколо них. Ми не знаємо, чому вони тут, але вони агресивні та мають зачатки розуму.", ["en"] = "Further Concerns" },
    [350] = { [1] = "Допомога старого знайомого", [2] = "Цей Марзон може бути пов'язаний з Непокірними та має зв'язок з Лесковаром...\n\nЗі смертю Ван-Кліфа та Тредда нам буде важко притягнути Лесковара до відповідальності без їх свідчень. Тим більше, що Лесковар — вельможа з гарними зв'язками. По суті він недоторканий.\n\nТобі знадобиться допомога. Я тобі з цим не допоможу, але я знаю декого, хто зможе. Ти знайдеш Тріаса в торговому районі міста.", [3] = "Поговоріть з Еллінгом Тріасом в Штормовії.", [5] = "Жартуєш? Гич знову просить моєї допомоги? Заради всього святого...\n\nБратство Непокірних, кажеш? Які ще гарні новини маєш? Може ще скажеш, що Смертекрил напав на місто?\n\nЩо ж, давай з самого початку. І з усіма подробицями — я хочу знати все.", ["en"] = "Look to an Old Friend" },
    [353] = { [1] = "Доставка для Бурешпиля", [2] = "Бурешпилі — шанований клан дворфів, відомі своїми вибагливими та витонченими смаками. Тож не дивно, що Ґрінґер Бурешпиль, горянин Залізогарту, звернувся до мене за зброєю.\n\nЗброю я виготовив, але... Горянин Бурешпиль служить далеко звідси, в Лох-Модан. Якщо ти збираєшся йти на північ, може доставиш йому цей пакунок?\n\nВ останньому листі горянин Бурешпиль писав, що він знаходиться на північній сторожовій вежі Лох-Модану.", [3] = "Доставте пакунок горянину Бурешпилю в Лох-Модан.", [4] = "Ти {стать:прийшов:прийшла} до мене зі Штормовію? Я чув, що людські землі останнім часом страждають від нашестя розбійників та орків. Прекрасне місце для {стать:вмілого:вмілої} {клас:р}!", [5] = "Ага! То Ґріманд нарешті завершив мою сокиру! Мені вже не терпиться випробувати її на трогах та кобольдах!\n\nДуже дякую, {ім'я}. Це був неблизький шлях. Прийми це на знак вдячності за твої зусилля.", ["en"] = "Stormpike's Delivery", ["tasks"] = { ["Package for Stormpike"] = "пакунок для Бурешпиля", ["Package for Stormpike (Provided)"] = "пакунок для Бурешпиля (видано)" } },
    [36] = { [1] = "Гуляш по-західнокрайськи", [2] = "Я ніколи не думала, що настане день, коли я покину ферму. Але поля кишать злодіями, і для нас тепер тут надто небезпечно. Як тільки фермер Хмуробров полагодить віз, ми вирушимо в дорогу.\n\nМоже, ти б {стать:зробив:зробила} мені послугу? Я напишу свій рецепт гуляшу по-західнокрайськи, а ти віднесеш його Сальмі Салден. Ферма Салденів розташована одразу за розвилкою.", [3] = "Верна Хмуробров хоче, щоб ви передали її рецепт гуляшу по-західнокрайськи Сальмі Салден.", [4] = "Я буду дуже сумувати за Верною Хмуробров. Ти часом не {стать:зустрічав:зустрічала} її по дорозі сюди?", [5] = "Ця Верна завжди була такою милою дівчиною. Нам буде її не вистачати тут, у Західному краї, але, тільки між нами, в душі вона — міська жителька, і Штормовій підійде їй просто чудово. Але досить пліток! Тепер ми можемо приготувати гуляш по-західнокрайськи!", ["en"] = "Westfall Stew", ["tasks"] = { ["Verna's Westfall Stew Recipe"] = "рецепт гуляшу по-західнокрайськи від Верни", ["Verna's Westfall Stew Recipe (Provided)"] = "рецепт гуляшу по-західнокрайськи від Верни (видано)" } },
    [3629] = { [1] = "Гоблінська інженерія", [2] = "Інженери-експерти обирають між двома дисциплінами: гномською та гоблінською інженерією. Я згадую про гоблінську інженерію лише тому, що я чесний учитель. Гобліни обожнюють робити всілякі вибухонебезпечні штучки, і їх рідко хвилює те, що опиниться на їхньому шляху — навіть вони самі.\n\n{ім'я}, прочитай цей посібник. Якщо хочеш дізнатися, як ефектно накласти на себе руки, то віднеси цей посібник Ніксу Вертопруженю в Пристроблях. Пам'ятай — зробивши цей вибір, ти не зможеш передумати та вивчати іншу дисципліну, тому переконайся, що ти {стать:впевнений:впевнена} у своєму шляху, перш ніж виконувати його завдання.", [3] = "Якщо ви хочете дізнатися більше про гоблінську інженерію, віднесіть посібник з інженерних дисциплін Ніксу Вертопруженю в Пристроблях.", [4] = "Я відчуваю запах свіжих новобранців так само як чудовий вибуховий порошок — за кілометр. Ти {стать:прийшов:прийшла} сюди, щоб навчитися майстерності виготовлення вибухівки?", [5] = "Ну що ж, {ім'я}, ти {стать:вчинив:вчинила} мудро, звернувшись до мене за наставництвом! Будь-який приблуда може стати експертом в основах інженерії — гноми та їх опромінений дім Гномреґан є свідченням цього. Але для того, щоб володіти дисципліною гоблінської інженерії, потрібен сильний розум і стійка рука (з особливим акцентом на СТІЙКУ).\n\nТримай вуха наготові, {ім'я}, і можливо, ти чогось навчишся.", ["en"] = "Goblin Engineering", ["tasks"] = { ["Manual of Engineering Disciplines"] = "посібник з інженерних дисциплін", ["Manual of Engineering Disciplines (Provided)"] = "посібник з інженерних дисциплін (видано)" } },
    [3630] = { [1] = "Гномська інженерія", [2] = "Інженери-експерти обирають між двома дисциплінами: гномською та гоблінською інженерією. Гномська інженерія безсумнівно є найкращою з двох. Майстри гномської інженерії займаються створення дивовижних пристроїв, які полегшують життя!\n\n{ім'я}, прочитай цей посібник. Якщо ти бажаєш дізнатися більше про гномську інженерію, то віднеси цей посібник мехмайстру Надспалаху в Залізогарт. Пам'ятай — зробивши цей вибір, ти не зможеш передумати та вивчати іншу дисципліну, тому переконайся, що ти {стать:впевнений:впевнена} у своєму шляху, перш ніж виконувати його завдання.", [3] = "Якщо ви хочете дізнатися більше про гномську інженерію, віднесіть посібник з інженерних дисциплін мехмайстру Надспалаху в Залізогарт.", [4] = "Так-так, чим можу служити? Вочевидь, часу в мене більш ніж достатньо, адже все, що я роблю — це стою тут, поки наше улюблене місто охоплене смертельною радіоактивною хмарою.", [5] = "Ах, {стать:молодий інженер:молода інженерка}, {стать:зацікавлений:зацікавлена} в освоєнні єдиної й справжньої дисципліни інженерії! Пробач мою драматичність. Хоча наша ситуація залишається тяжкою, завжди приємно бачити, як інші інженери відгукуються на поклик справжньої інженерії!", ["en"] = "Gnome Engineering", ["tasks"] = { ["Manual of Engineering Disciplines"] = "посібник з інженерних дисциплін", ["Manual of Engineering Disciplines (Provided)"] = "посібник з інженерних дисциплін (видано)" } },
    [3632] = { [1] = "Гномська інженерія", [2] = "Інженери-експерти обирають між двома дисциплінами: гномською та гоблінською інженерією. Гномська інженерія безсумнівно є найкращою з двох. Майстри гномської інженерії займаються створення дивовижних пристроїв, які полегшують життя!\n\n{ім'я}, прочитай цей посібник. Якщо ти бажаєш дізнатися більше про гномську інженерію, то віднеси цей посібник мехмайстру Надспалаху. Він тут, в Залізогарті. Пам'ятай — зробивши цей вибір, ти не зможеш передумати та вивчати іншу дисципліну, тому переконайся, що ти {стать:впевнений:впевнена} у своєму шляху, перш ніж виконувати його завдання.", [3] = "Якщо ви хочете дізнатися більше про гномську інженерію, віднесіть посібник з інженерних дисциплін мехмайстру Надспалаху в Залізогарт.", [4] = "Так-так, чим можу служити? Вочевидь, часу в мене більш ніж достатньо, адже все, що я роблю — це стою тут, поки наше улюблене місто охоплене смертельною радіоактивною хмарою.", [5] = "Ах, {стать:молодий інженер:молода інженерка}, {стать:зацікавлений:зацікавлена} в освоєнні єдиної й справжньої дисципліни інженерії! Пробач мою драматичність. Хоча наша ситуація залишається тяжкою, завжди приємно бачити, як інші інженери відгукуються на поклик справжньої інженерії!", ["en"] = "Gnome Engineering", ["tasks"] = { ["Manual of Engineering Disciplines"] = "посібник з інженерних дисциплін", ["Manual of Engineering Disciplines (Provided)"] = "посібник з інженерних дисциплін (видано)" } },
    [3634] = { [1] = "Гномська інженерія", [2] = "Інженери-експерти обирають між двома дисциплінами: гномською та гоблінською інженерією. Хоч я й вважаю це марною тратою часу, ти маєш знати про інженерію гномів. Вони створюють предмети та пристрої, які можуть змінити світ, але рідко працюють.\n\n{ім'я}, прочитай цей посібник. Якщо ти бажаєш навчитися створювати безглузді металеві штуки, то віднеси цей посібник мехмайстру Надспалаху в Залізогарт. Пам'ятай — зробивши цей вибір, ти не зможеш передумати та вивчати іншу дисципліну, тому переконайся, що ти {стать:впевнений:впевнена} у своєму шляху, перш ніж виконувати його завдання.", [3] = "Якщо ви хочете дізнатися більше про гномську інженерію, віднесіть посібник з інженерних дисциплін мехмайстру Надспалаху в Залізогарт.", [4] = "Так-так, чим можу служити? Вочевидь, часу в мене більш ніж достатньо, адже все, що я роблю — це стою тут, поки наше улюблене місто охоплене смертельною радіоактивною хмарою.", [5] = "Ах, {стать:молодий інженер:молода інженерка}, {стать:зацікавлений:зацікавлена} в освоєнні єдиної й справжньої дисципліни інженерії! Пробач мою драматичність. Хоча наша ситуація залишається тяжкою, завжди приємно бачити, як інші інженери відгукуються на поклик справжньої інженерії!", ["en"] = "Gnome Engineering", ["tasks"] = { ["Manual of Engineering Disciplines"] = "посібник з інженерних дисциплін", ["Manual of Engineering Disciplines (Provided)"] = "посібник з інженерних дисциплін (видано)" } },
    [3636] = { [1] = "Нести світло", [2] = "Скара постійно загрожує Альянсу, про це ти певно вже знаєш. Я тут нещодавно дізнався дещо, {ім'я}.\n\nВ Степах знаходяться жахливі тернові зарослі, що називаються норами Бритвоболотих. Колись там жили тільки звичайні свинобрази, та після їх об'єднання зі Скарою, там поселились різні чудовиська. Ними керує ліч, на ім'я Амненнар Стужевій.\n\nПрожени це зло, {ім'я}, заради Світла!", [3] = "Архієпископ Бенедикт просить вас вбити Амненнара Стужевія в норах Бритвоболотих.", [4] = "Амненнара необхідно знищити, {ім'я}, і швидше.", [5] = "Дякую, {ім'я}. Тепер Скара не буде так бездумно посилати свої сили.\n\nНехай береже тебе Світло.", ["en"] = "Bring the Light", ["tasks"] = { ["Amnennar the Coldbringer"] = "Амненнар Стужевій", ["Amnennar the Coldbringer slain"] = "Амненнар Стужевій: убито" } },
    [3640] = { [1] = "Угода про нерозголошення", [2] = "Гномська інженерія — це теорія інженерії, пристосована до наших потреб! Вона дозволяє нам створювати пристрої, які контролюють світ навколо нас. Це було описано в книжці, яку ти {стать:прочитав:прочитала}.\n\nУ цій книжці також згадується наша давня присяга зберігати секрети наших винаходів. Коли ти стаєш на шлях гномської інженерії, це остаточно — про гоблінську інженерію можеш забути.\n\nЯкщо ти все ще хочеш займатися гномською інженерією — підпиши цю угоду про довічне нерозголошення таємниць, і знову поговори зі мною. Гарненько подумай, {ім'я}.", [3] = "Якщо ви згодні займатися гномською інженерією, підпишіть угоду про нерозголошення і ще раз поговоріть з мехмайстром Надспалахом в Залізогарті.", [4] = "Якщо ти {стать:підписав:підписала} документ і {стать:готовий:готова} віддати його мені, то це остаточно.\n\nСекрети, якими я поділюся з тобою, настільки важливі, що підписання угоди про нерозголошення є абсолютно необхідним. Я підписав її, так само як й інші майстри гномської інженерії. Ти приєднуєшся до досить приємної компанії, {стать:інженере:інженерко} {ім'я}!", [5] = "Ласкаво просимо, {ім'я}! Ти незабаром матимеш доступ до найбільш передових інженерних розробок у всьому Азероті.\n\nТепер, коли ти {стать:присвятив:присвятила} себе цим знанням, настав час випробувати твої навички. Після цього ми допоможемо тобі розкрити свій потенціал в гномській інженерії!", ["en"] = "The Pledge of Secrecy", ["tasks"] = { ["Overspark's Signed Pledge"] = "підписана угода Надспалаха", ["Overspark's Signed Pledge (Provided)"] = "підписана угода Надспалаха (видано)" } },
    [3641] = { [1] = "Покажи свою роботу", [2] = "Як твій наставник, я хочу побачити зразки твоєї роботи. Ти {стать:вправний інженер:вправна інженерка}, без сумнівів, {ім'я}. Однак я хочу проаналізувати твою роботу, щоб виділити гномські техніки у твоїй майбутній діяльності. Мені потрібні такі зразки: шість мітрилових трубок, точний приціл і два покращені манекени-мішені.\n\nПринеси мені ці предмети, і я видам тобі твою власну членську картку гномського інженера. Вона обов'язково потрібна для доступу до всіх тренерів гномської інженерії!", [3] = "Принесіть 6 мітрилових трубок, точний приціл та 2 покращені манекени-мішені мехмайстру Надспалаху в Залізогарт.", [4] = "Після того, як я побачу твої інженерні вироби, я видам тобі справжню членську картку гномського інженера! Допоки картка дійсна, у тебе буде необмежений доступ до будь-якого тренера з гномської інженерії по всьому світу.", [5] = "Ось твоя перша членська картка гномського інженера!\n\nВнесок по цій картці сплачено на чотирнадцять днів. Через два тижні термін її дії закінчиться. Коли це станеться — оплати наступний внесок будь-якому тренеру з гномської інженерії, щоб отримати нову картку. Без картки твоє членство тимчасово призупиниться, і ти не матимеш доступу до нових креслень.\n\nЦе ніяк не вплине на вже набуті знання: якщо ти вже {стать:став гномським інженером:стала гномською інженеркою}, то це назавжди.", ["en"] = "Show Your Work", ["tasks"] = { ["Accurate Scope"] = "точний приціл", ["Accurate Scope (Provided)"] = "точний приціл (видано)", ["Advanced Target Dummy"] = "вдосконалений манекен-мішень", ["Advanced Target Dummy (Provided)"] = "вдосконалений манекен-мішень (видано)", ["Advanced Target Dummy slain"] = "вдосконалений манекен-мішень: убито", ["Mithril Tube"] = "мітрилова трубка", ["Mithril Tube (Provided)"] = "мітрилова трубка (видано)" } },
    [3647] = { [1] = "Поновлення членської картки", [4] = "Щоб поновити членську картку, вам потрібно сплатити внесок у розмірі двох золотих.", [5] = "Оскільки ти займаєшся гномською інженерією й маєш гарну репутацію, я можу поновити твою членську картку за дві золоті монети. Після оплати цієї суми тобі буде видана нова картка. Це дозволить тобі мати доступ до креслень гномської інженерії від відповідних тренерів.\n\nЦя картка буде дійсна протягом двох тижнів, після чого тобі знову потрібно буде оплатити членський внесок! Якщо ти хочеш мати доступ до креслень, тобі потрібно закрити всі свої заборгованості.", ["en"] = "Membership Card Renewal", ["tasks"] = { ["Required money: 2"] = "Необхідні гроші: 2" } },
    [3681] = { [1] = "Фоліант божественності", [2] = "Вибач, що відволікаю від пригод, {раса:к}, та зі Штормовію прийшов наказ для паладинів прибути для продовження навчання.\n\nСхоже, що настав особливий час твого шляху {клас:р} — вивчення священних фоліантів.\n\nЗнайди Даторіана Ралла в Штормовії. Він зазвичай навчає паладинів в соборі Світла.", [3] = "Поговоріть з Даторіаном Раллом в Штормовії.", [5] = "Вітаю в соборі Світла, {клас:к}.", ["en"] = "Tome of Divinity" },
    [37] = { [1] = "Пошук зниклих вартових", [2] = "Кілька днів тому ми послали двох вартових, Рольфа та Малакая, на розвідку вздовж річки, але вони й донині не повернулися. Щоб завершити свій звіт, я повинен знати, що сталося з тими двома.\n\nВирушай на північ вздовж річки та знайди вартових... або їхні рештки.", [3] = "Вартовий Томас просить вас піти на північ вгору по річці та пошукати двох зниклих вартових, Рольфа та Малакая.", [5] = "Попри те, що тіло було вже пограбоване, поблизу лежить медальйон з написом: \"Піхотинець Малакай Кам'яний\".", ["en"] = "Find the Lost Guards" },
    [3702] = { [1] = "Тліючі руїни Тауріссана", [2] = "Хочеш почути коротку історію дворфів Темного Заліза?", [3] = "Вислухайте розповідь королівського історика Архіни про Тауріссана.", [4] = "Дозволь мені закінчити розповідь про Тауріссана.", [5] = "Продовжимо?", ["en"] = "The Smoldering Ruins of Thaurissan", ["tasks"] = { ["Story of Thaurissan"] = "Історія Тауріссана" } },
    [373] = { [1] = "Ненадісланий лист", [2] = "Обшукуючи тіло Едвіна Ван-Кліфа, ви серед інших речей знаходите лист. Він адресований Баросу Алекстону, головному архітектору Штормовія, ратуша, Соборна площа.\n\nСхоже, що печатка свіжа і його написали нещодавно.", [3] = "Доставте лист головному архітектору Баросу Алекстону в Штормовій.", [4] = "Слухаю. Чи можу я тобі чимось допомогти?", [5] = "Едвін Ван-Кліф, кажеш? Я б скоріш чекав листа від моєї покійної прабабусі. То ви вбили його? Вибач, але я здивований. В юності він був неперевершеним бійцем. Що ж, поглянемо, що він мені написав після стількох років.\n\n<Барос проглядає листа.>\n\nЕдвін... Схоже, він анітрохи не змінився — все той самий ідеаліст і романтик. Йому не важливо, кого зачепить його помста, {ім'я}. Жага помсти поглинула його. Та що ж, я не можу його винити...", ["en"] = "The Unsent Letter", ["tasks"] = { ["An Unsent Letter"] = "ненадісланий лист", ["An Unsent Letter (Provided)"] = "ненадісланий лист (видано)" } },
    [3763] = { [1] = "Допомога верховному друїду Оленерогу", [2] = "Перепрошую, {клас:к}, можна тебе на хвилинку?\n\nКенарійське Коло в Дарнасі шукає таких досвідчених шукачів пригод, як ти, що допоможуть їм з важливим дослідницьким проєктом. Я не знаю подробиць, та можу точно сказати, що очолює цей проєкт сам верховний друїд Фендрал Оленеріг.\n\nБудь ласка — якщо тобі цікаво, поговори з ним особисто в Кенарійському Анклаві в Дарнасі.", [3] = "Поговоріть з верховним друїдом Фендралом Оленерогом в Дарнасі.", [5] = "Що ж, {клас:к}... оскільки тобі повідомили, що я сам керую цим дослідженням, ти, очевидно, {стать:прийшов:прийшла} якнайшвидше.\n\nІ якщо ти вже тут, слухай уважно, поки я розкажу подробиці. Не маю бажання пояснювати двічі.", ["en"] = "Assisting Arch Druid Staghelm" },
    [3764] = { [1] = "Ґрунт Ун'Ґоро", [2] = "Кажуть, що ґрунт кратера Ун'Ґоро наділений потужними магічними властивостями. Я хочу дізнатись, наскільки ці чутки правдиві. Вирушай в нетрі кратера Ун'Ґоро та дістань достатньо якісних зразків ґрунту для наших досліджень.\n\nТобі може здатися, що ця справа не варта тебе. Але таке відношення не сподобається ні мені, ні Кенарійському Колу. Принеси зразки Дженалу, який, певно, ловить ґав надворі за цим деревом. Просто шукай купки землі, і знайдеш його. Постачанням займається він, а не я.", [3] = "Принесіть 20 зразків ґрунту Ун'Ґоро Дженалу в Кенарійський Анклав, що в Дарнасі.", [4] = "А, так, земля. Верховний друїд вимагає з кожного шукача пригод по двадцять купок — буде йому двадцять купок. І нехай проваляться ті, хто діє проти нас!", [5] = "Залиш свій дорогоцінний вантаж тут, {стать:благородний:благородна} {клас:к}. Мабуть, це був неабиякий тягар... не легший від тягаря, який несу я, будучи провидцем. Ось плата за твою роботу, як наказав сам верховний друїд.\n\nВін хоче знову хоче бачити тебе, {ім'я}. Його наступне завдання буде легше виконати, якщо ти розумієшся на травництві хоча б на рівні підмайстра. Але навіть якщо це не так, ти все одно зможеш допомогти Колу!", ["en"] = "Un'Goro Soil", ["tasks"] = { ["Un'Goro Soil"] = "ґрунт Ун'Ґоро", ["Un'Goro Soil (Provided)"] = "ґрунт Ун'Ґоро (видано)" } },
    [3765] = { [1] = "Заморські проблеми", [2] = "Штормовій — бурхливий центр різних діяльностей.\n\nЯ приїхав здалеку в пошуках допомоги. Я чув, що вулицями цього міста ходить багато шукачів пригод.\n\nМій брат, Ґершала, потребує допомоги. Він проживає в прибережному містечку, Аубердіні.\n\nЦе дуже далека подорож, повна пригод. Тому я й прошу допомоги {стать:такого досвідченого:такої досвідченої} {клас:р}, як ти.", [3] = "Прямуйте до Ґершали Нічношереха в Аубердін.", [5] = "То тебе прислав мій брат, Арґос? Ти певно {стать:втомився:втомилась} від такої далекої подорожі. Та нам ще багато про що треба поговорити.", ["en"] = "The Corruption Abroad" },
    [377] = { [1] = "Злочин і кара", [2] = "Мало було нам нехтування жителями Смерколісся, тепер дім вельмож наплював на рішення ради Темнодолу та лорда Чорнобривого про смертну кару для Декстрена Ворда і кинули його до Штормовійської в'язниці.\n\nВорда спіймали на продажі тіл з кладовища Морбенту Скверну, що карається смертю. І все ж Штормовій оголосив його своїм в'язнем.\n\nВбий Ворда в Штормовійській в'язниці, принеси мені його руку і я винагороджу тебе.", [3] = "Радник Млинченко з Темнодолу просить вас принести йому руку Декстрена Ворда.", [4] = "Поки такий виродок, як Декстрен Ворд, може жити, у світі немає місця правосуддю. Повернись до мене, коли смертний вирок лорда Чорнобривого буде виконано над цим осквернителем, Вордом. Ми принесемо спокій сім'ям загиблих і, що ще краще, ми нагадаємо про себе дому вельмож Штормовію.", [5] = "Отож, Декстрен Ворд нарешті заплатив за свої злочини проти людяності? Земля бетоном цьому покидьку. І велика подяка тобі. Ти не тільки {стать:приніс:принесла} спокій сім'ям померлих, а і {стать:вказав:вказала} місце цим корумпованим бюрократам з дому вельмож. Штормовій має прислухатися до проблем людей Смерколісся інакше ми позбавимося від їхньої тиранії.", ["en"] = "Crime and Punishment", ["tasks"] = { ["Hand of Dextren Ward"] = "рука Декстрена Ворда", ["Hand of Dextren Ward (Provided)"] = "рука Декстрена Ворда (видано)" } },
    [3781] = { [1] = "Дослідження світанки", [2] = "За допомогою того, що ми називаємо торбою вічного цвітіння, ми виростили насіння Тарлендріса в ґрунті з кратера Ун'Ґоро. З цього насіння проростає низка корисних трав. Одна з них — світанка, таємнича рослина, про яку ми мало що знаємо. І я збираюсь дослідити її.\n\nВіднеси це вниз, до Матренґіла, і він дасть тобі трохи насіння для початку. Якщо ти витратиш все, тобі доведеться купити у нього ще.", [3] = "Віднесіть розписку верховного друїда про видачу насіння Матренґілу Ведмелику в Кенарійський Анклав, що в Дарнасі.", [4] = "Мир і спокій тобі, {клас:к}. Ти тут за дорученням від самого верховного друїда, чи не так?", [5] = "Так, по цій розписці я можу видати тобі двадцять пакетів насіння. Якщо закінчиться — я зможу продати ще. На жаль, насіння Тарлендріса досить дорого виробляти у великій кількості. Ось чому Кенарійське Коло просить тих, хто нам допомагає, компенсувати частину витрат.\n\nТі, хто повертається зі світанкою, знають, що винагорода верховного друїда з лишком окупає витрати.", ["en"] = "Morrowgrain Research", ["tasks"] = { ["Seed Voucher"] = "розписка про видачу насіння", ["Seed Voucher (Provided)"] = "розписка про видачу насіння (видано)" } },
    [3785] = { [1] = "Дослідження світанки", [2] = "Ось твоя торба вічного цвітіння, у якій ти зможеш проростити насіння Тарлендріса. Тобі доведеться посадити їх у ґрунт Ун'Ґоро. Як матимеш все необхідне — просто скористайся торбою. Вона подбає про все інше.\n\nЯк матимеш достатньо світанки — принось її мені. І прошу, не турбуй верховного друїда, він дуже зайнятий, не варто відривати його від справ кожного разу, коли хтось приходить з черговою партією світанки!", [3] = "За допомогою торби вічного цвітіння, пакету насіння Тарлендріса та двох зразків ґрунту Ун'Ґоро спробуйте проростити світанку.\n\nПринесіть 10 світанок Матренґілу Ведмелику в Дарнас.", [4] = "Ну як, {ім'я}, тобі вдалось виростити світанку для важливих досліджень верховного друїда? Його праця для Кенарійського Кола надзвичайно важлива, і твоя допомога не залишиться непоміченою!", [5] = "Молодець, {ім'я}, я обов'язково віддам їх верховному друїду, коли вони йому знадобляться. А поки що прийми це на знак вдячності Кенарійського Кола.\n\nНам завжди потрібна світанка, тож якщо хочеш і надалі допомагати нам — повертайся, коли знову виростиш її.", ["en"] = "Morrowgrain Research", ["tasks"] = { ["Morrowgrain"] = "світанка", ["Morrowgrain (Provided)"] = "світанка (видано)" } },
    [3789] = { [1] = "Допомога верховному друїду Оленерогу", [2] = "Перепрошую, {клас:к}, можна тебе на хвилинку?\n\nКенарійське Коло в Дарнасі шукає таких досвідчених шукачів пригод, як ти, що допоможуть їм з важливим дослідницьким проєктом. Я не знаю подробиць, та можу точно сказати, що очолює цей проєкт сам верховний друїд Фендрал Оленеріг.\n\nБудь ласка — якщо тобі цікаво, поговори з ним особисто в Кенарійському Анклаві в Дарнасі.", [3] = "Поговоріть з верховним друїдом Фендралом Оленерогом в Дарнасі.", [5] = "Що ж, {клас:к}... оскільки тобі повідомили, що я сам керую цим дослідженням, ти, очевидно, {стать:прийшов:прийшла} якнайшвидше.\n\nІ якщо ти вже тут, слухай уважно, поки я розкажу подробиці. Не маю бажання пояснювати двічі.", ["en"] = "Assisting Arch Druid Staghelm" },
    [3790] = { [1] = "Допомога верховному друїду Оленерогу", [2] = "Перепрошую, {клас:к}, можна тебе на хвилинку?\n\nКенарійське Коло в Дарнасі шукає таких досвідчених шукачів пригод, як ти, що допоможуть їм з важливим дослідницьким проєктом. Я не знаю подробиць, та можу точно сказати, що очолює цей проєкт сам верховний друїд Фендрал Оленеріг.\n\nБудь ласка — якщо тобі цікаво, поговори з ним особисто в Кенарійському Анклаві в Дарнасі.", [3] = "Поговоріть з верховним друїдом Фендралом Оленерогом в Дарнасі.", [5] = "Що ж, {клас:к}... оскільки тобі повідомили, що я сам керую цим дослідженням, ти, очевидно, {стать:прийшов:прийшла} якнайшвидше.\n\nІ якщо ти вже тут, слухай уважно, поки я розкажу подробиці. Не маю бажання пояснювати двічі.", ["en"] = "Assisting Arch Druid Staghelm" },
    [38] = { [1] = "Гуляш по-західнокрайськи", [2] = "Допоможи мені зробити гуляш по-західнокрайськи! Принеси мені такі інгредієнти:\n\n3 шматки жилавого м'яса грифа\n3 рила іклоштрика\n3 ока мурлока\n3 плоди окри", [3] = "Сальмі Салден потрібні 3 шматки жилавого м'яса грифа, 3 рила іклоштрика, 3 ока мурлока та 3 плоди окри.", [4] = "Принеси мені такі інгредієнти:\n\n3 шматки жилавого м'яса грифа\n3 рила іклоштрика\n3 ока мурлока\n3 плоди окри", [5] = "Ця окра відмінно загустить бульйон! Тепер ми лише додамо жилаве м'ясо грифа, кілька очей мурлоків і ці смачнющі рила іклоштриків. Ось усе й готово! За твою допомогу, {ім'я:к}, я пропоную тобі першу порцію гуляшу по-західнокрайськи!", ["en"] = "Westfall Stew", ["tasks"] = { ["Goretusk Snout"] = "рило іклоштрика", ["Goretusk Snout (Provided)"] = "рило іклоштрика (видано)", ["Murloc Eye"] = "око мурлока", ["Murloc Eye (Provided)"] = "око мурлока (видано)", ["Okra"] = "окра", ["Okra (Provided)"] = "окра (видано)", ["Stringy Vulture Meat"] = "жилаве м'ясо грифа", ["Stringy Vulture Meat (Provided)"] = "жилаве м'ясо грифа (видано)" } },
    [3823] = { [1] = "Погасити Вогнечеревих", [2] = "Ми маємо вдарити по наших ворогах, перш ніж вони вдарять по нас!\n\nСкажу коротко, солдате.\n\nОгри клану Вогнечеревих — союзники орків Чорнокаменю. Вони разом захищають багату на корисні копалини скелю Жахобою та лінії постачання.\n\nЗалиш свій слід, {ім'я}. Змети їхні сили та повертайся до мене.\n\n<Оралій робить жест, наче когось душить.>\n\nЯ ВБ'Ю ТЕБЕ, ВІНКІ!", [3] = "Вбийте 15 вогнечеревих огр-магів, 7 вогнечеревих огрів та 7 вогнечеревих моцаків і поверніться до Оралія.", [4] = "На твоїх обладунках мало крові, солдате!", [5] = "Чудово, солдате! Оркам і ограм знадобиться кілька хвилин, а то й навіть годин, щоб оговтатися від цього удару!", ["en"] = "Extinguish the Firegut", ["tasks"] = { ["Firegut Brute"] = "вогнечеревий моцак", ["Firegut Brute slain"] = "вогнечеревий моцак: убито", ["Firegut Ogre"] = "вогнечеревий огр", ["Firegut Ogre Mage"] = "вогнечеревий огр-маг", ["Firegut Ogre Mage slain"] = "вогнечеревий огр-маг: убито", ["Firegut Ogre slain"] = "вогнечеревий огр: убито" } },
    [3824] = { [1] = "Ґор'теш, лорд моцаків.", [2] = "Вони ослаблені, кажу тобі! Наш наступний удар повинен бути вирішальним.\n\nПотрібно знищити лорда моцаків, Ґор'теша. Ще важливіше — принести мені його голову, щоб я міг підготувати третю фазу нашої атаки на вогнечеревих огрів.\n\nАле знай, солдате. Ґор'теш править не зі скелі Жахобою, а з будівлі орків Чорнокаменю, що на заході від скелі Жахобою.\n\nОтже, наказ простий. Знайди Ґор'теша та відрубай його товсту голову. Повертайся до мене, коли виконаєш завдання.\n\nСТУЛИ ПЕЛЬКУ, ВІНКІ!", [3] = "Знайдіть Ґортеша десь на заході від скелі Жахобою. Вбийте його, а потім віднесіть відрубану голову Ґор'теша до Оралія в Палаючий степ.", [4] = "О, славний день! Ти {стать:повернувся:повернулася} з головою?", [5] = "Поглянь на це, солдате. Гидота! Коли решта вогнечеревих огрів побачить цю жирну пику, настромлену на спис, на вершині їхньої скелі, почнеться паніка!\n\n<Ораліус дико регоче.>", ["en"] = "Gor'tesh the Brute Lord", ["tasks"] = { ["Gor'tesh's Lopped Off Head"] = "відрубана голова Ґор'теша", ["Gor'tesh's Lopped Off Head (Provided)"] = "відрубана голова Ґор'теша (видано)" } },
    [384] = { [1] = "Реберця кнура в пиві", [2] = "Ніщо не подобається моїм постояльцям у таверні більше, ніж кнурячі ребра, запечених у пиві! Є лиш одна проблема: місцевий мисливець, який раніше доставляв мені продукти, записався до королівської армії, щоб допомогти Альянсу в війні.\n\nМожливо, ти зможеш мені допомогти? Якщо ти принесеш мені шість ребер зі скельних кнурів та солод Рапсодія з місцевої таверни, я дам тобі рецепт моїх знаменитих кнурячих реберець в пиві, не кажучи вже про безплатну порцію! Секрет в пиві!", [3] = "Раґнар Громовар з Хараноса просить вас принести йому 6 ребер скельного кнура і кухоль солоду Рапсодія.", [4] = "Мені знадобиться шість реберець скельного кнура та кухоль солоду Рапсодія, {ім'я}.", [5] = "Свинина запечена, пиво дозріло\nІ перш ніж до діла візьмемось ми сміло\nЧекає на всіх нас тяжка боротьба\nЗа перший шматочок смачного ребра", ["en"] = "Beer Basted Boar Ribs", ["tasks"] = { ["Crag Boar Rib"] = "Ребро скельного кнура", ["Crag Boar Rib (Provided)"] = "ребро скельного кнура (видано)", ["Rhapsody Malt"] = "Солод Рапсодія", ["Rhapsody Malt (Provided)"] = "солод Рапсодія (видано)" } },
    [3841] = { [1] = "Сиротка шукає домівку", [2] = "О, привіт, {ім'я}. Я рада знову бачити тебе. Як пройшла твоя поїздка до Дарнасу?\n\nДобре, ти будеш {стать:радий:рада} почути, що ми зробили багато всього доки тебе не було. Ми навіть врятували гніздо яєць. На жаль, їхня мати загинула, перш ніж ми її дістали.\n\nСлухай, а не хочеш взяти одне яйце? Воно скоро вилупиться і йому буде {стать:потрібен хороший батько:потрібна хороша матір}. Що ти на це скажеш?\n\nЯкщо тебе це справді цікавить, візьми одне яйце і йди до Квентіна на траси для перегонів на Мерехтливих рівнинах. Він розкаже тобі більше.", [3] = "Поговоріть з Квентіном в Тисячі Шипів.", [4] = "Привіт, {клас:к}.\n\nТи не думай, я тут не заради перегонів... хоча видовище, звісно, цікаве.\n\nНасправді я прибув в Тисячу Шипів, щоб з'ясувати, чи можна врятувати ці землі. Це стало моєю особистою місією — домогтися, щоб ця пустеля знову розцвіла і зазеленіла. Можливо, мені вдасться виявити джерело води неподалік.\n\nСкажи мені, ти не {стать:помітив:помітила}, наскільки дивним є перехід між Фераласом і Тисячею Шипів? Тут напевно не обійшлося без магії...", [5] = "А, яйце райдужного хамелеона, і, якщо я не помиляюся, воно майже готове вилупитись. Дивовижно, що ти {стать:знайшов:знайшла} його, не кажучи вже про те, що воно в такому хорошому стані. Нині вони рідко зустрічаються в Фераласі. Я чув, що там було багато браконьєрів, які намагались ловити і знищувати їх з різних причин. Шкода насправді... вони такі прекрасні, коли досягають дорослого віку.\n\nЯк тобі вдалося знайти його?", ["en"] = "An Orphan Looking For a Home", ["tasks"] = { ["Unhatched Sprite Darter Egg"] = "невилуплене яйце райдужного хамелеона", ["Unhatched Sprite Darter Egg (Provided)"] = "невилуплене яйце райдужного хамелеона (видано)" } },
    [3842] = { [1] = "Інкубація", [2] = "Місяцеткачі? Цікаво. Жаль, що райдужні хамелеони не зможуть оцінити все, що ці дівчата для них роблять. Дуже, дуже здібні дівчата.\n\nОтож, вони подарували тобі яйце. Тож ти несеш відповідальність за нього. Здається, що воно майже готове вилупитися, але ми повинні переконатися, що воно здорове і не ушкоджене.\n\nМені потрібні лише два еліксири стійкості для невеликого закляття для захисту яйця. Решта компонентів у мене є.", [3] = "Принесіть 2 еліксири стійкості Квентіну в Тисячу Шипів.", [4] = "Чим довше я перебуваю тут, тим більше я хочу взяти участь у цих перегонах, {ім'я}. Це дійсно вражає...\n\nТи вже {стать:знайшов:знайшла} еліксири? Коли я переконаюся, що яйце здорове, то поверну його тобі, щоб ти {стать:зберігав:зберігала} його до моменту вилуплення.\n\nДай знати.", [5] = "Чудово. Ці підійдуть. Дай мені хвилинку, щоб змішати компоненти, і ми побачимо, наскільки здорове це яйце.", ["en"] = "A Short Incubation", ["tasks"] = { ["Elixir of Fortitude"] = "еліксир стійкості", ["Elixir of Fortitude (Provided)"] = "еліксир стійкості (видано)" } },
    [3843] = { [1] = "Новий член сім'ї", [2] = "Розкішний екземпляр, {ім'я}. Якщо ця істота доживе до вилуплення, то у тебе буде прекрасний, здоровий улюбленець!\n\nЄ ще одна річ, яку я б порадив зробити, якщо ти розраховуєш залишити його собі — вирушай на Орлиний пік у Внутрішні землі. Знайди дворфа, на ім'я Аґнар Звіролов. Він великий фахівець з розведення тварин і зможе допомогти тобі.\n\nАле поспішай, {ім'я}, це яйце дуже крихке і не протримається довго без належного догляду.", [3] = "Віднесіть крихке яйце райдужного хамелеона у Внутрішні землі та поговоріть з Аґнаром Звіроловом, але покваптесь, у вас є лише 1 година, щоб знайти його до того, як дитинча з яйця загине.", [4] = "Вітаю, {ім'я}. Як я можу тобі послужити?", [5] = "Так, так, так... Я не бачив чогось подібного вже багато років. Чарівний дракончик, якщо не помиляюся... Здається, що це яйце саме летючого хамелеона. Чудово, це просто чудово.\n\nОтже, якщо цей малюк збирається вилупитися і вижити, то ми повинні знайти для нього їжу. Добре, що ти вчасно {стать:приніс:принесла} мені це яйце.", ["en"] = "The Newest Member of the Family", ["tasks"] = { ["Fragile Sprite Darter Egg"] = "крихке яйце райдужного хамелеона", ["Fragile Sprite Darter Egg (Provided)"] = "крихке яйце райдужного хамелеона (видано)" } },
    [386] = { [1] = "Що посієш...", [2] = "Тарґорр Жахливий був головним палачем Ґат'Ільзоґґа і навіть серед орків вважався жорстоким. Багато відважних захисників королівства зазнали його страшних тортур. Тепер його утримують в Штормовійській в'язниці, засудженого на смерть. Але ось яка річ. Один з клятих бюрократів з дому вельмож відклав виконання вироку. Вони точно щось задумали.\n\nПокінчи з Тарґорром Жахливим, {ім'я}. Відправляйся до в'язниці та принеси мені його голову, поки він не уникнув покарання.", [3] = "Принесіть голову Тарґорра Жахливого вартовому Бертону в Приозер'я.", [4] = "Ти вже {стать:був:була} в Штормовії? Боюсь, що поки прийде час вироку, Тарґорр Жахливий вже втече з в'язниці. Він має померти, {ім'я}, а не бути якимось пішаком в задумах вельмож.", [5] = "Тарґорр Жахливий нарешті отримав що заслужив. Я радий, що він нарешті відчув на собі те, що сіяв усі ці роки. Ти чудово {стать:впорався:впоралась}, {ім'я}. Інколи правосуддя необхідно творити поза залою суду та без втручання вельмож.", ["en"] = "What Comes Around...", ["tasks"] = { ["Head of Targorr"] = "голова Тарґорра", ["Head of Targorr (Provided)"] = "голова Тарґорра (видано)" } },
    [387] = { [1] = "Придушення бунту", [2] = "Бунт потрібно придушити! Мені потрібна твоя допомога. Якщо підуть чутки про бунт у в'язниці, я втрачу роботу! Найважливіше зараз — змусити в'язнів підкоритися заради безпеки Штормовію.\n\nПокарання заколотникам — смерть! Вбий кількох повстанців! Це налякає інших і дозволить нам взяти ситуацію під контроль.", [3] = "Наглядач Телвотер зі Штормовію просить вас вбити 10 в'язнів Непокірних, 8 каторжників Непокірних та 8 заколотників Непокірних у Штормовійській в'язниці.", ["en"] = "Quell the Uprising", ["tasks"] = { ["Defias Convict"] = "каторжник Непокірних", ["Defias Convict slain"] = "каторжник Непокірних: убито", ["Defias Insurgent"] = "заколотник Непокірних", ["Defias Insurgent slain"] = "заколотник Непокірних: убито", ["Defias Prisoner"] = "в'язень Непокірних", ["Defias Prisoner slain"] = "в'язень Непокірних: убито" } },
    [388] = { [1] = "Колір крові", [2] = "Серце моє сповнено глибоким смутком. Мій онук, Мак, був таким хорошим. Ледь 14 виповнилось. Як армія пішла на фронт, Мак взявся за зброю, щоб захищати місто. Він був охоронцем у в'язниці, куди привезли покидьків з банди Непокірних. Мак покарав кількох в'язнів за те, що вони робили бандани — символи своєї шайки. За це вони його зарізали.\n\nЯ жадаю помсти. Принеси мені десяток їх вовняних бандан. Вони червоні... як кров.", [3] = "Нікова Раскол зі Штормовію просить вас принести 10 червоних вовняних бандан.", [4] = "Ти {стать:повернувся:повернулася}. {стать:Зібрав:Зібрала} 10 червоних вовняних бандан з цієї банди мерзотників у в'язниці?", [5] = "Тож це вони, гидкі символи цієї мерзоти, за які загинув Мак? Яке безглуздя. Яка жахлива жертва.\n\nНа жаль, минулого не вернути. Дякую, {ім'я}. Своїми діями ти {стать:приніс:принесла} долю справедливості моїй сім'ї.", ["en"] = "The Color of Blood", ["tasks"] = { ["Red Wool Bandana"] = "червона вовняна бандана", ["Red Wool Bandana (Provided)"] = "червона вовняна бандана (видано)" } },
    [389] = { [1] = "Базіл Тредд", [2] = "Ми з Ван-Кліфом були членами Гільдії Каменярів. Нашим головним проєктом була відбудова Штормовію після війни.\n\nКоли ми виконали свою роботу, нас обдурили. Дворяни відмовилися платити нам за роботу. Деяким старшим каменярам запропонували посаду в уряді, але Ван-Кліф відмовився від неї через лояльність до каменярів. Він очолив бунт і залишив місто, присягаючись помститися.\n\nЙого лейтенант, Базіл Тредд, міг знати більше про плани Ван-Кліфа. Його утримують у в'язниці Штормовію.", [3] = "Поговоріть з наглядачем Телвотером у в'язниці Штормовію.", [5] = "Чого, в ім'я Світла, ти хочеш? Хіба ти не бачиш, що у нас тут проблеми?\n\nБазіл Тредд?! Навіщо тобі говорити з цим виродком? Звідки я маю знати, що ти не {стать:один:одна} з його поплічників і не {стать:прийшов:прийшла} допомогти з його кривавим бунтом? Якби всі двері камер не підірвали, я б запроторив тебе в одну з них!", ["en"] = "Bazil Thredd" },
    [39] = { [1] = "Передача звіту Томаса", [2] = "Розкажи маршалові Дугану про смерть Малакая та Рольфа, повідом йому, що теперішня чисельність наших військ не здатна стримувати мурлоків на сході Ельвинну.\n\nЯ знаю, що у нас не так багато вільних військ, але, сподіваюся, Дугану вдасться когось знайти.", [3] = "Відзвітуйте маршалові Дугану в Злотохресті.", [5] = "Гм, це тривожні новини. Всі сили оборони розтягнуті на максимум, а втрата Рольфа та Малакая в бою з мурлоками поставила нас у ще гірше становище.\n\nЯкщо в найближчому майбутньому ситуація швидко не покращиться, то до кінця тижня бої вже будуть вестись у Злотохресті!", ["en"] = "Deliver Thomas' Report" },
    [3903] = { [1] = "Міллі Осворт", [2] = "Ти {стать:проявив:проявила} себе як {стать:надійний:надійна} {клас}, {ім'я}. {стать:Надійний:Надійна}, і ще й не боїшся забруднити руки, га?\n\nУ мене є подруга, Міллі Осворт, у якої неприємності. Вона стоїть зі своїм возом там, на іншому боці абатства, поблизу стайні. Я впевнений, що їй згодиться твоя допомога.", [3] = "Поговоріть з Міллі Осворт.", [5] = "О, заступник Віллем попросив тебе поговорити зі мною? Він хоробрий чоловік і завжди бажає допомогти, але його обов'язки утримують його в Північнокрайовому абатстві. Та й, боюся, моя сьогоднішня біда йому не під силу.\n\nМожливо, ти мені допоможеш?", ["en"] = "Milly Osworth" },
    [3904] = { [1] = "Урожай Міллі", [2] = "Банда розбійників, Непокірні, увійшли у виноградники Північнокраю якраз під час моїх жнив! Я повідомила про це гвардійцям Північнокраю, і вони запевнили, що подбають про все, але... я все ж непокоюся за свій урожай винограду! Якщо Непокірні його не розкрадуть, то наші гвардійці потім розтопчуть його, як гнатимуться за негідниками.\n\nБудь ласка, ти маєш допомогти мені! Я зібрала більшість свого урожаю, проте залишила його у виноградниках на південному сході.\n\nПринеси мені його! Врятуй мій урожай!", [3] = "Принесіть Міллі Осворт до Північнокрайового абатства 8 ящиків з її урожаєм.", [4] = "{стать:Дістав:Дістала} мій урожай, {ім'я}?", [5] = "Дякую тобі, {ім'я:к}! Ти {стать:врятував:врятувала} мій урожай! І, сподіваюся, {стать:показав:показала} кільком Непокірним, що їм немає чого тут робити.\n\nМожливо, нині нам і не вистачає вартових, проте нам пощастило мати таких героїв, як ти, що захищають нас!", ["en"] = "Milly's Harvest", ["tasks"] = { ["Milly's Harvest"] = "урожай Міллі", ["Milly's Harvest (Provided)"] = "урожай Міллі (видано)" } },
    [3905] = { [1] = "Повідомлення про постачання винограду", [2] = "А тепер, коли мій врожай врятовано, віднеси це повідомлення про постачання винограду до брата Нілса. Він керує запасами їжі та напоїв у Північнокраї. Впевнена, він зрадіє, коли почує, що матиме свіжий виноград.\n\nТи знайдеш брата Нілса в абатстві, у дзвіниці... він полюбляє смакувати там своє вино.", [3] = "Віднесіть повідомлення про постачання винограду братові Нілсу в Північнокрайове абатство.", [4] = "Видається мені, що ти в чудовому настрої! Підходь! Сідай, і ось тобі келих!", [5] = "Погляньмо, що тут у нас...\n\nО-ва! Виноград Міллі врятований! Коли вона сказала мені, що розбійники захопили її виноградники, я ледь не впав у відчай, проте моя віра у Світло не похитнулась!\n\nІ завдяки твоїй відвазі в нас є виноград для ще більшої кількості вина! Нехай Світло благословить і береже тебе, {ім'я}!", ["en"] = "Grape Manifest", ["tasks"] = { ["Grape Manifest"] = "повідомлення про постачання винограду", ["Grape Manifest (Provided)"] = "повідомлення про постачання винограду (видано)" } },
    [391] = { [1] = "Бунт у в'язниці Штормовію", [2] = "Скажу тобі одразу, {ім'я}: я тобі не довіряю. Але справи такі, що це не важливо.\n\nТож ось, що робимо: ти йдеш всередину і знаходиш Тредда. Якщо ти дійсно з нами — вбий його і принеси мені його голову. Якщо ж ти {стать:один:одна} з них — можеш залишатись там і чекати своєї смерті.", [3] = "Вбийте Базіла Тредда в Штормовійській в'язниці та принесіть його голову наглядачу Телвотеру.", [4] = "Або ти принесеш мені голову Тредда, або втратиш свою, тобі ясно, {ім'я}?", [5] = "Сподіваюсь, без ватажка цей бунт буде легше придушити...\n\nЧесно кажучи, через 20 хвилин я думав, що ти вже не вийдеш. На щастя, я помилився.\n\nДумаю, ти мало що {стать:вибив:вибила} з нього. Але я знаю одну річ про Тредда, що може тобі знадобитись.", ["en"] = "The Stockade Riots", ["tasks"] = { ["Head of Bazil Thredd"] = "голова Базіла Тредда", ["Head of Bazil Thredd (Provided)"] = "голова Базіла Тредда (видано)" } },
    [392] = { [1] = "Таємничий відвідувач", [2] = "В перші роки ув'язнення Тредда його ніхто не провідував. Мені здавалось, що він більше не потрібен братству і його покинули.\n\nАле кілька місяців тому його постійно провідували... десь раз чи два на місяць. Відвідувач був дивний. І дуже тихий. У мене виникли підозри, та з документами у нього було все добре.\n\nЗгідно з документами, його ім'я — Мелік, ось його опис. Думаю, він вже не прийде до Тредда.", [3] = "Принесіть Баросу Алекстону в Штормовій запечатаний опис відвідувача Тредда.", [4] = "Так, {ім'я}? Що в тебе?", [5] = "Хм... Мелік? Ні, мені не знайоме ні його ім'я, ні опис. Та це може бути хто завгодно! Колишній каменяр, хтось з Братства Непокірних... Та якщо він дійсно пов'язаний з ними, як підозрює Телвотер, то може його хтось впізнає. Дай мені подумати...", ["en"] = "The Curious Visitor", ["tasks"] = { ["Sealed Description of Thredd's Visitor"] = "запечатаний опис відвідувача Тредда", ["Sealed Description of Thredd's Visitor (Provided)"] = "запечатаний опис відвідувача Тредда (видано)" } },
    [393] = { [1] = "Тінь минулого", [2] = "Мені нічого не спало на думку, {ім'я}. Та є дехто, хто може тобі допомогти, і так вийшло, що він у мене в боргу... Та не будемо про це. Ти знайдеш майстра Матіаса Гича з ШУР в казармах Старого Міста. Гич знає про всі підпільні діяння у місті.\n\nЯкщо хтось і може допомогти, то це він.", [3] = "Принесіть майстру Матіасу Гичу в Штормовій запечатаний опис відвідувача Тредда.", [4] = "Вітаю. Чим я можу допомогти, {клас:к}?", [5] = "Що? Що це? Так, я знаю про кого тут йдеться, та його звати не Мелік. Вбивці ховаються за багатьма масками й іменами та забувають про них, щойно вони втрачають користь. Я знаю ще одне його ім'я — Марзон. Та певно і це не його справжнє ім'я.\n\nХай там як, він вбивця і я достатньо про нього знаю.\n\nМарзон нині працює на Грегора Лесковара, лорда з сумнівною репутацією навіть за мірками вельмож Штормовію.", ["en"] = "Shadow of the Past", ["tasks"] = { ["Sealed Description of Thredd's Visitor"] = "запечатаний опис відвідувача Тредда", ["Sealed Description of Thredd's Visitor (Provided)"] = "запечатаний опис відвідувача Тредда (видано)" } },
    [394] = { [1] = "Голова чудовиська", [2] = "Знайди Гича в Старому Місті. Дай йому знати, що з Лесковаром та його задумами покінчено, і про твою участь в цьому. Певен, він буде радий дізнатись, що серед жителів Штормовію ще є герої.\n\nВін скоріш за все відправить тебе на зустріч з принцом чи ще яким вельможею. Та не дай їм запудрити тобі мізки, {ім'я}. Вельможі думають, що керують всім в цьому місті, та вони не всемогутні.", [3] = "Поговоріть з Матіасом Гичем в Штормовії.", [5] = "Він мертвий, так? Твоє правосуддя було швидким, {ім'я}. Не хотів би я бути твоїм ворогом.\n\n<Гич сміється і плескає вас по плечу.>\n\nЯ не проти такого, {ім'я}. Не мені, голові вбивць, тебе осуджувати. Чесно кажучи, ти неабияк {стать:допоміг:допомогла} жителям Штормовію. Дякую тобі за це.", ["en"] = "The Head of the Beast" },
    [395] = { [1] = "Кінець братства", [2] = "Ах, мало не забув. Алекстон приходив, поки тебе не було, він хотів поговорити з тобою. Безсумнівно, він бажає повідомити вельможам про дії Братства Непокірних.\n\nНевеличка порада, {ім'я:к}: якщо хтось запитає, я надам усі подробиці, окрім того, що це ти {стать:покінчив:покінчила} з Лесковаром. Повір мені. Я... обізнаний... в таких речах.\n\nА що стосується Тріаса, то ні з ким не розмовляй про нього... ніколи... якщо зможеш.", [3] = "Поговоріть з Баросом Алекстоном в Штормовії.", [5] = "Радий тебе бачити, {ім'я}. Я чув, що лорда Грегора Лесковара нещодавно знайшли мертвим.\n\nСхоже, ти успішно {стать:впорався:впоралась} зі своїм завданням. Прийми мою подяку за порятунок мене та багатьох інших від помсти Ван-Кліфа.", ["en"] = "Brotherhood's End" },
    [396] = { [1] = "Аудієнція у короля", [2] = "Я підготував доповідь для короля. Думаю, ти маєш особисто передати її разом з подробицями твого розслідування. Не хвилюйся, я не сумніваюсь, що він оцінить твою відданість у виконанні обов'язку перед людьми Штормовію.\n\nАудієнція незабаром почнеться, тож краще поквапся і йди до фортеці Штормовію.", [3] = "Доставте доповідь Бароса Алекстона про Братство Непокірних королю Варіану Рінну в фортецю Штормовію.", [4] = "{ім'я}, так? Барос Алекстон повідомив мені, що ти прийдеш. Чесно кажучи, мене більше цікавить, що розкажеш ти.", [5] = "Ти заслуговуєш на похвалу за твої зусилля для Штормовію, {ім'я}. Якби Ван-Кліфу вдалось втілити свої задуми, він, без сумніву, заподіяв би великої шкоди королівству — чого ми, очевидно, не можемо дозволити.\n\nПрийми це, {клас:к}, як знак королівської вдячності. На жаль, король не може вручити його тобі особисто, бо він зайнятий дипломатичною місією і ще не скоро повернеться.", ["en"] = "An Audience with the King", ["tasks"] = { ["Report on the Defias Brotherhood"] = "доповідь про Братство Непокірних" } },
    [399] = { [1] = "Скромні дари минулого", [2] = "Здається, минула вічність, відколи я був хлопчиком і працював на фермі в Західному краї. Кажуть, ти ніколи не зможеш повернутись в минуле, і це правда. У моєму випадку двічі правда, бо дім моєї родини спалили та захопили злодії.\n\nЯ говорив з батьком про долю деяких своїх речей, у тому числі мого першого компаса. Він не зміг їх врятувати, але каже, що їх вдалося сховати на фермі.\n\nТи знайдеш садибу Алекстона на заході від Сторожового пагорба. Можливо, ти {стать:міг би:могла б} піти й забрати його для мене?", [3] = "Йдіть до будинку Бароса Алекстона в Західному краї та знайдіть його компас, а потім поверніть його йому на Соборній площі Штормовію.", [4] = "{ім'я}! Тобі вдалось?", [5] = "О, дякую, {ім'я}! Для мене він має практичної користі, тільки як пам'ять про минуле... Навіть не знаю як тобі віддячити... це певно було непросто, та й шлях до Західного краю неблизький. Візьми це в знак моєї подяки.", ["en"] = "Humble Beginnings", ["tasks"] = { ["A Simple Compass"] = "звичайний компас", ["A Simple Compass (Provided)"] = "звичайний компас (видано)" } },
    [40] = { [1] = "Риб'яча небезпека", [2] = "{Ім'я:к}, в Ельвиннському лісі з'явилася нова загроза! Мурлоки плавають у водах східного Ельвинна, відлякуючи рибу та нападаючи на мешканців!\n\nЯ попередив маршала Дугана, але він більше переживає за гнолів та бандитів. При цьому, не вважаючи мурлоків небезпечними.\n\nБудь ласка, {ім'я:к}, поговори з Дуганом і переконай його відправити більше військ на схід!", [3] = "Ремі \"Повторюха\" хоче, щоб ви поговорили з маршалом Дуганом у Злотохресті.", [5] = "Так, я розмовляв з Ремі. Я поважаю його як купця, проте всі повідомлення про мурлоків на сході у кращому випадку були поверхневими.\n\nЯ візьму до уваги твоє занепокоєння, але поки я не отримаю військовий звіт про загрози від мурлоків, ми не можемо дозволити собі відправити більше війська на схід.", ["en"] = "A Fishy Peril" },
    [400] = { [1] = "Інструменти для Сталешквара", [2] = "Белдін Сталешквар володіє місцевою ремонтною майстернею, а ще він найкращий технік облогових машин! Але він не жаліє свої інструменти. Клянусь, він ламає більше дугових гайковертів, ніж ми встигаємо виготовити!\n\nМи щойно виготовили його нове замовлення. Якщо ти доставиш його Белдіну, я певен, від добре тобі заплатить.\n\nТи знайдеш його в Сховищі Сталешквара, на північний схід від Хараноса. До речі, це улюблене місце ветеранів-пілотів облогових машин, тож будь {стать:уважний:уважна} там — може яка робота трапиться.", [3] = "Доставте інструменти Белдіну Сталешквару.", [4] = "Хм? Виглядаєш надто {стать:замолодим:замолодою} як для пілота. Гаразд... Тобі щось полагодити треба?\n\nБери номерок і чекай своєї черги. Я зараз працюю над кількома машинами і не маю часу на ще одну.\n\nЧи ти тут по іншій справі?", [5] = "Ти {стать:приніс:принесла} мої інструменти? Добре, {стать:юначе:юнко}, дуже добре! Я щойно зламав останній зубчастий торцевик, а він мені потрібен, щоб відремонтувати машину Камнелада. Як чудово, що ти {стать:приніс:принесла} ці інструменти, {ім'я}.\n\nОсь, це тобі за допомогу.", ["en"] = "Tools for Steelgrill", ["tasks"] = { ["Steelgrill's Tools"] = "інструменти Сталешквара", ["Steelgrill's Tools (Provided)"] = "інструменти Сталешквара (видано)" } },
    [401] = { [1] = "Очікування перекладу Сірри", [2] = "Я майже закінчив переклад цієї записки. Якщо ти повернешся за кілька хвилин, я закінчу.", [3] = "Зачекайте трішки, а потім знову поговоріть з Сіррою Фон'Інді.", [5] = "Ось так. Перекладено...\n\n<Повітря стає важким, ніби на місто опустилася густа чорна завіса...>", ["en"] = "Wait for Sirra to Finish" },
    [4103] = { [1] = "Бальзам з уламків душ", [4] = "Маяк Кенарія дозволяє побачити уламки душ уражених оскверненням створінь, убитих заради загального блага. Я подрібню уламки душ на реагент, придатний для виготовлення кенарійського бальзаму зцілення рослин. Ми використовуємо цей засіб, щоб вилікувати уражені скверною рослини.\n\nВ обмін на ці уламки душ я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Дуже добре, ось тобі декілька порцій кенарійського бальзаму. Шукай в Скверноліссі осквернені рослини, {ім'я}! Як знайдеш їх — використовуй бальзам, щоб очистити їх.", ["en"] = "Salve via Hunting", ["tasks"] = { ["Corrupted Soul Shard"] = "уламок оскверненої душі", ["Corrupted Soul Shard (Provided)"] = "уламок оскверненої душі (видано)" } },
    [4104] = { [1] = "Бальзам з мінералів", [4] = "Якщо під час видобутку копалин в Скверноліссі в тебе буде з собою маяк Кенарія, ти зможеш побачити уражений купорос, що проникає в жили металів. Я знаю, як очистити цей купорос і перетворити його на реагент, придатний для виготовлення кенарійського бальзаму зцілення рослин. Ми використовуємо цей засіб, щоб вилікувати уражені скверною рослини.\n\nЯкщо ти принесеш мені уражений купорос, я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Дуже добре, ось декілька порцій кенарійського бальзаму. Якщо ти знайдеш уражений купорос, коли видобуватимеш копалини у Скверноліссі, не забудь притримати його для мене! Що більше ти знайдеш, то більше бальзаму я зможу зробити.", ["en"] = "Salve via Mining", ["tasks"] = { ["Tainted Vitriol"] = "уражений купорос", ["Tainted Vitriol (Provided)"] = "уражений купорос (видано)" } },
    [4105] = { [1] = "Бальзам з осквернених трав", [4] = "Маяк Кенарія дозволяє досвідченому травнику помітити залишок скверни — мерзенний продукт осквернення, що вразило Сквернолісся. Моя робота в Скверноліссі дозволила мені навчитися перетворювати залишок скверни в очисний реагент... який ми використовуємо в кенарійському бальзамі зцілення рослин.\n\nКоли ти збиратимеш трави в Скверноліссі, ти зможеш натрапити на залишок скверни, якщо матимеш при собі маяк. В обмін на залишки я виготовлю для тебе кенарійський бальзам.", [5] = "Чудова робота, {ім'я} — коли ми їх очистимо, вони допоможуть нам повернути Сквернолісся до життя. Ось, візьми кілька порцій кенарійського бальзаму зцілення рослин та прямуй до лісу. Зцілення цих земель від скверни — невідкладна справа!", ["en"] = "Salve via Gathering", ["tasks"] = { ["Fel Creep"] = "залишок скверни", ["Fel Creep (Provided)"] = "залишок скверни (видано)" } },
    [4106] = { [1] = "Бальзам зі шкір", [4] = "Маяк Кенарія дає змогу досвідченому шкуродеру знаходити серед зібраної у Скверноліссі шкіри ту, що уражена скверною. Я переробляю цю здавалось би непотрібну шкіру в густу пасту, що прискорює дію кенарійського бальзаму зцілення рослин. Коли будеш займатися шкуродерством у Скверноліссі, обов'язково тримай при собі маяк!\n\nКоли збереш клапті ураженої шкіри — принеси їх мені, і я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Це саме те, що мені потрібно. Ось — візьми кенарійський бальзам, щоб очистити рослини Сквернолісся від осквернення. Ми повинні боротися, {ім'я}!", ["en"] = "Salve via Skinning", ["tasks"] = { ["Patch of Tainted Skin"] = "клапоть ураженої шкіри", ["Patch of Tainted Skin (Provided)"] = "клапоть ураженої шкіри (видано)" } },
    [4107] = { [1] = "Бальзам з розбитих чарів", [4] = "Сила магічного предмета відповідає силі субстанцій, які отримують унаслідок розбиття його чарів. Я винайшла спосіб перероблення сирих субстанцій, які використовують накладачі чарів, у реагент, придатний для створення кенарійського бальзаму зцілення рослин. Для цього тобі не потрібен маяк Кенарія — підійде будь-який магічний предмет, розбиття чарів якого дає малі підсвітні субстанції.\n\nМені потрібна лише одна така субстанція. За на неї я дам тобі кенарійський бальзам зцілення рослин. Підсвітня субстанція дуже потужна — навіть одної вистачить надовго!", [5] = "Ось кілька порцій кенарійського бальзаму зцілення рослин, {ім'я}, і за нього я прошу лише одну малу підсвітню субстанцію. Субстанція — це найпотужніша речовина, яку я можу використати для створення бальзаму. Якщо тобі знадобиться більше бальзаму — приходь до мене.", ["en"] = "Salve via Disenchanting", ["tasks"] = { ["Lesser Nether Essence"] = "мала підсвітня субстанція", ["Lesser Nether Essence (Provided)"] = "мала підсвітня субстанція (видано)" } },
    [412] = { [1] = "Операція Рекомбобуляція", [2] = "При подальшому аналізі Гномреґанської ситуації виявилося, що нам не тільки не вдалося викорінити трогів, але ми випадково перетворили більшу частину раси гномів на моторошних, безмозких, лиходійських лепрогномів!\n\nМи з Оззі плануємо направити у зворотній бік жахливий ефект прокази за допомогою нашого останнього винаходу — Рекомбобулятора. Ця машина майже закінчена, але нам надзвичайно потрібні зубці рестабілізації та гіромеханічні шестерні. Здобудь трохи деталей з лепрогномів перед Гномреґаном для нас.", [3] = "Принесіть Раззлові Жвавоверту в Харанос 8 зубців рестабілізації та 8 гіромеханічних шестерень.", [4] = "Рекомбобулятор буде завершено і запущено, як тільки у нас буде достатньо зубців рестабілізації та гіромеханічних шестерень.", [5] = "Ці гіромеханічні шестерні та зубці рестабілізації чудово підходять до креслення Оззі для пристрою рекомбобуляції. Як тільки я заллю трохи гідромастила в поршні внутрішнього згоряння, відрегулюю пускове руків'я і підвищу в'язкість електрогумового гелю, раса гномів буде відроджена.", ["en"] = "Operation Recombobulation", ["tasks"] = { ["Gyromechanic Gear"] = "Гіромеханічна шестірня", ["Gyromechanic Gear (Provided)"] = "гіромеханічна шестірня (видано)", ["Restabilization Cog"] = "Зубець рестабілізації", ["Restabilization Cog (Provided)"] = "зубець рестабілізації (видано)" } },
    [4124] = { [1] = "Зниклий кур'єр", [2] = "Одному моєму знайомому, Ґінро Палкому Багаттю, потрібна допомога. Він шукає кур'єра і пакунки, які той ніс. Вже понад тиждень минуло з того часу, як кур'єр зник, наші власні пошуки не дали результатів і ми зайшли в глухий кут. На жаль, мені довелося оголосити кур'єра зниклим безвісти.\n\nЯкщо у тебе є вільний час, будь ласка, поговори з Ґінро. Він має бути десь тут, у фортеці — можливо, у себе.", [3] = "Поговоріть з Ґінром Палким Багаттям у фортеці Перомісяць.", [5] = "Тебе певно Латро прислав. Хоча я думаю, що ми вже його не знайдемо, я готовий прийняти будь-яку допомогу. Я буду радий відпочити від постійних пошуків Раскала у Фераласі, тому що кожного разу я повертаюся ні з чим, окрім розчарування.", ["en"] = "The Missing Courier" },
    [4125] = { [1] = "Зниклий кур'єр", [2] = "Минуло близько тижня з того часу, як кур'єр Раскал вирушив в Таланаар. Він добре знає Фералас, він був з нами з часів, коли генерал Перомісяць вела сюди експедицію. Я знаю, що він планував пливти вздовж узбережжя на човні та спробувати перетнути південний Фералас, щоб уникнути табору Орди.\n\nЯ не знайшов його човен, але, можливо, ти зможеш. Можливо, його сховали, або він потонув. Можливо, у ньому є якась зачіпка щодо місцеперебування Раскала. Якщо знайдеш що-небудь, будь ласка, дай мені знати.", [3] = "Знайдіть човен кур'єра десь уздовж узбережжя Фераласу.", [5] = "Ви виявили затонулий човен. Крізь каламутну воду ви бачите дірки, що пронизують лівий борт. Здається, ніби човен буквально обдертий до свого дерев'яного каркаса. Таке враження, що човен намагалися розірвати навпіл. На правому борту намальовано невеликий герб фортеці Перомісяць.\n\nУ мулі, що скупчився на дні човна, видно відблиск чогось металевого...", ["en"] = "The Missing Courier" },
    [4126] = { [1] = "Гарлі Чорнодих", [2] = "Дворфи Темного Заліза під командуванням лиходія Гарлі Чорнодиха викрали найкращий рецепт світлого громузвару. Безсовісні лиходії! Вони не заслуговують пити таке чудове пиво!\n\n{Ім'я}, в мене для тебе непросте завдання. Відправляйся в Чорноскельні надра, що в Палаючому степу, знищ там усі бочки з громузваром і поверни наш рецепт!\n\nПрошу тебе, принеси цей рецепт, навіть якщо для цього доведеться перевернути догори дном всі Чорноскельні надра!", [3] = "Знайдіть втрачений рецепт Громоварів та віднесіть його Раґнару Громовару в Харанос.", [4] = "Ти {стать:приніс:принесла} рецепт, {ім'я}? Я не можу змиритися з думкою, що дворфи Темного Заліза п'ють наш сімейний напій!", [5] = "Ти {стать:знайшов:знайшла} його! Молодець! Сподіваюсь, ти добряче {стать:відлупцював:відлупцювала} цих дворфів та Гарлі Чорнодиха!\n\nГромовари до твоїх послуг, {ім'я}. Ти {стать:справжній герой:справжня героїня}!", ["en"] = "Hurley Blackbreath", ["tasks"] = { ["Lost Thunderbrew Recipe"] = "втрачений рецепт Громоварів", ["Lost Thunderbrew Recipe (Provided)"] = "втрачений рецепт Громоварів (видано)" } },
    [4127] = { [1] = "Уламки човна", [2] = "Проходячи рукою по глині, ваші пальці торкаються держака ножа. Він виглядає доглянутим, і можна припустити, що той, хто був на човні, міг його загубити. Можливо, це пов'язано з тим, що у човна відсутній великий шматок борту.\n\nВи берете ніж, пригадуючи, що Ґінро Палке Багаття з фортеці Перомісяць просив повернутися до нього якщо знайдете якісь сліди. Однак вас не полишає відчуття, що ви тут не одні...", [3] = "Поверніться в фортецю Перомісяць і покажіть Ґінру Палкому Багаттю знайдений вами ніж.", [4] = "З поверненням, {ім'я}. Сподіваюся, ти {стать:зміг:змогла} знайти якусь зачіпку щодо долі Раскала, якою б трагічною вона не була.", [5] = "Цікаво... Я думаю, що цей ніж належить Раскалу. Ти кажеш, що {стать:знайшов:знайшла} його на дні човна? Ну, можливо, цієї знахідки недостатньо, щоб робити якісь висновки про долю Раскала. Але у нас є один незвичайний спосіб дізнатися більше…\n\nТи коли-небудь {стать:чув:чула} про психометрію?", ["en"] = "Boat Wreckage", ["tasks"] = { ["Discarded Knife"] = "викинутий ніж", ["Discarded Knife (Provided)"] = "викинутий ніж (видано)" } },
    [4128] = { [1] = "Раґнар Громовар", [2] = "Здоров, {ім'я}. Я чула, що Раґнар Громовар розлючений, бо хтось викрав його ель. Він шукає відважних пригодників, які візьмуться за це завдання та готовий добре їм заплатити.\n\nПоговори з Раґнаром, якщо тобі цікаво. Він зараз на своїй винокурні в Хараносі, що в Дун-Морозі.", [3] = "Поговоріть з Раґнаром Громоваром.", [5] = "Саме так, я розлючений! Мене обікрали! Вкрали один з наших сімейних рецептів! Як вони посміли! Я і раніше ненавиді цих дворфів Темного Заліза! А тепер, ох... Вони за це заплатять!", ["en"] = "Ragnar Thunderbrew" },
    [4129] = { [1] = "Знайдений ніж", [2] = "У нас у фортеці мешкає друїд, Квінтіс Вогнепад, і він має деякі... незвичайні здібності. Одна з них полягає у психометрії — здатності розкривати історію предмета шляхом дотику. Не питай мене, як він це робить. Для мене це магія, яку я не розумію і не намагаюся зрозуміти. Але я знаю дві речі: по-перше, я бачив, як це працює, і, по-друге, він мій боржник.\n\nВізьми цей ніж і віднеси Квінтісу в його хатинку на дереві, і передай йому від мене, що його борг буде сплачено, якщо він розкриє історію цього ножа.", [3] = "Віднесіть знайдений ніж Квінтісу Вогнепаду в фортецю Перомісяць.", [4] = "Ти від Ґінро, вірно?\n\nМої навички психометрії досить виснажливі для психіки... але так само виснажливі мої поразки в калімдорський холдем. Тут у фортеці мене називають \"королем поганих ходів\". Невдаха в картах... але, мабуть, щасливчик у вивченні таємниць природи.\n\nВ будь-якому разі, звичайно, я зроблю це. Можливо, це саме те, чого нам бракує, щоб дізнатися про долю Раскаля. Давай сюди ніж і ми почнемо.", [5] = "Дякую, {ім'я}.\n\nХоча психометрію не можна назвати точним мистецтвом, але все ж в минулі часи я не раз з її допомогою розбирався в ситуаціях, які всі інші вважали безнадійними. Думаю, цього разу вона допоможе нам хоча б частково зрозуміти, що сталося з Раскалом.\n\nЦе займе небагато часу, але легкою і приємною справою я б це назвав. Тож трохи терпіння...", ["en"] = "The Knife Revealed", ["tasks"] = { ["Discarded Knife"] = "викинутий ніж", ["Discarded Knife (Provided)"] = "викинутий ніж (видано)" } },
    [413] = { [1] = "Мерехтливий стаут", [2] = "Хотів би я щоб мій брат Велларт спробував мій Мерехтливий стаут. Він горянин, їх розквартирували у південній вартовій вежі на кордоні з Лох-Моданом.\n\nВін може й не такий бровар, як інші Ячміновари, але своє пиво він любить і я певен, що це йому теж сподобається.\n\nВіднесеш йому барильце Мерехтливого стаута?", [3] = "Віднесіть барильце Мерехтливого стаута горянину Ячміновару", [4] = "Вітаю, {клас:к}! Що привело тебе сюди?\n\nЩось захоплююче, сподівають. Я вже давно добряче не бився, ще й це барильце елю майже пусте...", [5] = "<Горянин Ячміновар куштує Мерехтливий стаут...>\n\nОх, аж іскри з очей! Здається, я навіть можу бачити в темряві.", ["en"] = "Shimmer Stout", ["tasks"] = { ["Barrel of Shimmer Stout"] = "барильце \"Мерехтливого стаута\"", ["Barrel of Shimmer Stout (Provided)"] = "барильце \"Мерехтливого стаута\" (видано)", ["Take the Barrel of Shimmer Stout to Mountaineer Barleybrew."] = "Віднесіть барильце Мерехтливого стаута горянину Ячміновару." } },
    [4130] = { [1] = "Психометричні дослідження", [2] = "Вибач, мене досі трохи хитає. Хай там що, я зумів побачити кілька корисних речей.\n\nРаскал забрав зі свого човна два великих шкіряних рюкзаки та пішов вглиб суходолу, але потім повернувся до човна. Бачу скальпи гнолів... він натрапив на якихось гнолів — здається, їх називають Дереволапими. Він дуже занепокоєний — майже наляканий... чимось. Так, що не звертає уваги на водяних елементалів, що з'являються за його спиною. Видіння... обриваються тут.\n\nВибач, {ім'я}, мені потрібно відпочити. Розкажи Ґінру про те, що я побачив. Він має знати.", [3] = "Поговоріть з Гінром Палким Багаттям у фортеці Перомісяць.", [5] = "Дякую, що {стать:передав:передала} мені видіння Квінта, {ім'я}. Я постараюся пам'ятати про це і бути трохи м'якшим з ним наступного разу, коли ми гратимемо в карти.\n\nРаскал добре вміє битися, і гноли — не ті, хто може його занепокоїти, а тим більше налякати. Однак, можливо, ця інформація допоможе тобі врешті-решт розкрити цю справу.", ["en"] = "Psychometric Reading" },
    [4131] = { [1] = "Дереволапі гноли", [2] = "Наші \"друзі\" - Дереволапі, можуть бути причетні до зникнення Раскала, але щось підказує мені, що це не так. Однак, це найкраще місце для початку пошуків.\n\nЗвичайно, хотілося б мати чіткіші відомості про те, що саме там шукати, але наразі все, що я можу сказати — це \"Обшукай табори Дереволапих\". Я знаю, що гноли зберігають здобуті речі та охороняють їх. Тож, можливо, вони натрапили на рюкзаки, про які згадував Квінт. Я не ризикував раніше сунутися до гнолів, але з видінням Квінта варто спробувати.", [3] = "Обшукайте табори дереволапих гнолів у південному Фераласі, щоб знайти речі кур'єра або його самого.", [5] = "На сусідньому дереві висять два великі шкіряні рюкзаки. На кожному з них — невеликий герб фортеці Перомісяць...", ["en"] = "The Woodpaw Gnolls" },
    [4135] = { [1] = "Судомна глибочінь", [2] = "У рюкзаках ви знаходите дві речі: перша — пакунок з товарами, що був адресований в Таланаар, а друга — записка, яка була написана поспішно невідомому отримувачеві.\n\nУ записці розповідається про відкриття підступних комахоподібних істот південніше таборів гнолів в місці, що називається Судомна глибочінь. Автор відчував потребу особисто дослідити це місце, наче це була серйозна загроза для всього Фераласа. Записка підписана: \"Раскал з Перомісяця\".\n\nЗдається, ви визначили, куди зрештою пішов Раскал.", [3] = "Тепер, коли зрозуміло останнє відоме місцеперебування Раскала, продовжуйте пошуки його або його останків у Судомній глибочіні. Згідно з запискою, вона розташована на південь від таборів Дереволапих гнолів.", [5] = "Ви виявили величезний кокон незрозумілого походження. Сам кокон м'який і слизький, але зсередини в різних місцях випирає щось тверде. Розміри кокона дозволяють припустити, що всередині може перебувати гуманоїд середнього зросту... і крізь стінки кокона дійсно видніються обриси гуманоїда!", ["en"] = "The Writhing Deep", ["tasks"] = { ["Undelivered Parcel"] = "недоставлений пакунок" } },
    [414] = { [1] = "Стаут для Кедрела", [2] = "Я спробував ще цього \"Мерехтливого стаута\", що зварив мій брат - це чудова випивка! Я хочу щоб мій друг-горянин теж спробував. Його звати Кедрел і зазвичай він патрулює дорогу через Телсамар, що в Лох-Модані.\n\nЩоб дістатися Телсамара, йди на південний схід через тунель, а потім на роздоріжжі поверни на північний схід. По тій дорозі ти дійдеш прямісінько до Телсамара.\n\nДай Кедрелу барильце Мерехтливого стаута і дізнайся його думку.", [3] = "Віднесіть барильце Мерехтливого стаута горянину Кедрелу.", [4] = "Вітаю, {клас:к}, і ласкаво прошу до Телсамару!", [5] = "Нумо, спробуємо...\n\nБорода Маґні! Від цього пойла аж голова обертом! І така незвична легкість в тілі.\n\nТаке відчуття, наче я можу літати!", ["en"] = "Stout to Kadrell", ["tasks"] = { ["Cask of Shimmer Stout"] = "барильце Мерехтливого стаута", ["Cask of Shimmer Stout (Provided)"] = "барильце Мерехтливого стаута (видано)", ["Take the Cask of Shimmer Stout to Mountaineer Kadrell."] = "Віднесіть барильце Мерехтливого стаута горянину Кедрелу." } },
    [4141] = { [1] = "Муїджін та Ларіон", [2] = "Бачиш Ларіона он там? Це його провина, що ми тут!\n\nЯ казав йому, що ми рухаємось не в тому напрямку, але він не слухав. І уявляєш, після цього він ще й не бажає зі мною розмовляти! Ну, поки він не передумає, я трохи побавлюсь!\n\n{стать:Бачив:Бачила} дивні рослини що повзають по кратеру? Насправді від них одні клопоти, але я думаю, що якщо їх правильно надресувати, я зможу навчити їх виконувати команди.\n\nНасамперед мені потрібні зразки для вивчення. Зможеш зібрати для мене кілька?", [3] = "Зберіть 15 кровоцвітів та поверніться до Муїджіна.", [4] = "Ларіон точно щось задумав!", [5] = "Сподіваюся, вони не завдали тобі багато клопоту, {ім'я}. Я намагаюся триматися від них якомога далі — вони дикі!\n\nЯ намагався перестрибнути через одного... І на мене напали! Рослини не повинні так себе поводити!", ["en"] = "Muigin and Larion", ["tasks"] = { ["Bloodpetal"] = "кровоцвіт", ["Bloodpetal (Provided)"] = "кровоцвіт (видано)" } },
    [415] = { [1] = "Нове пиво Реджольда", [2] = "Реджольд Ячміновар, що мешкає в селищі Всезвар, питав про тебе.\n\nВін хоче поговорити з тобою про новий напій, який він варив... говорив щось про твою допомогу йому. Може схочеш повернутися у селище Всезвар і дізнатись, що йому треба.\n\nМоже, на тебе чекає дармова випивка...", [3] = "Поспілкуйтесь з Реджольдом Ячміноваром.", [5] = "{Ім'я}! Пам'ятаєш той блискоквіт, що ти {стать:приніс:принесла} мені? Ну, я використав його в кількох рецептах, над якими працював, і один з них виявився чудовим!\n\nОсь, спробуй і скажи, що думаєш...", ["en"] = "Rejold's New Brew" },
    [416] = { [1] = "Відлов щурів", [2] = "У нас справжнє нашестя на заході. Ці тунельні щури, кобольди, перебралися в передгір'я, влаштували собі лігва і забруднюють наші землі!\n\nМи маємо винищити їх. Перебий їх якомога більше і принеси мені їх вуха як доказ.\n\nТи знайдеш кобольдів та їх лігва на захід від Телсамару. Ними усіяний весь схил гори.", [3] = "Принесіть 12 вух тунельних щурів горянину Кедрелу в Телсамар.", [4] = "Вітаю, {ім'я}. Як проходить відлов щурів?", [5] = "Фу! Коли я просив тебе принести їх вуха, я й гадки не мав, як вони смердять!\n\nОсь твоя винагорода, {ім'я}. Ти {стать:заслужив:заслужила}.", ["en"] = "Rat Catching", ["tasks"] = { ["Tunnel Rat Ear"] = "вухо тунельного щура", ["Tunnel Rat Ear (Provided)"] = "вухо тунельного щура (видано)" } },
    [418] = { [1] = "Телсамарська кров'янка", [2] = "В Телсамарі голодних ротів завжди вистачає. Тут і дітей повно-повно, і робітників, що цілими днями тяжко працюють на розкопках. Ми славимось своєю кров'янкою, та ти, певне, навіть не {стать:куштував:куштувала}, правда ж?\n\nЩо ж, як то у нас кажуть, \"хто не працює — той не їсть\". Це й тебе стосується, {клас:к}.\n\nМені потрібно ведмеже м'ясо, кишки кнура для оболонки та лімфа павука для пікантності. Принеси мені інгредієнти, а я все приготую.", [3] = "Відра Вогнисько з Телсамару просить вас принести їй 3 шматки ведмежого м'яса, 3 кишки кнура та 3 порції павучої лімфи.", [4] = "Я готова готувати, ти {стать:приніс:принесла} інґредієнти?", [5] = "Повір мені, процес її готування важче, ніж здається, але...\n\nХм, нікому не цікавий процес приготування кров'янки, та я поділюсь з тобою рецептом про всяк випадок.\n\nОт і все, їж, поки свіжі.", ["en"] = "Thelsamar Blood Sausages", ["tasks"] = { ["Bear Meat"] = "м'ясо ведмедя", ["Bear Meat (Provided)"] = "м'ясо ведмедя (видано)", ["Boar Intestines"] = "кишки кнура", ["Boar Intestines (Provided)"] = "кишки кнура (видано)", ["Spider Ichor"] = "лімфа павука", ["Spider Ichor (Provided)"] = "лімфа павука (видано)" } },
    [4181] = { [1] = "Гоблінська інженерія", [2] = "Інженери-експерти обирають між двома дисциплінами: гномською та гоблінською інженерією. Я згадую про гоблінську інженерію лише тому, що я чесний учитель. Гобліни обожнюють робити всілякі вибухонебезпечні штучки, і їх рідко хвилює те, що опиниться на їхньому шляху — навіть вони самі.\n\n{ім'я}, прочитай цей посібник. Якщо хочеш дізнатися, як ефектно накласти на себе руки, то віднеси цей посібник Ніксу Вертопруженю в Пристроблях. Пам'ятай — зробивши цей вибір, ти не зможеш передумати та вивчати іншу дисципліну, тому переконайся, що ти {стать:впевнений:впевнена} у своєму шляху, перш ніж виконувати його завдання.", [3] = "Якщо ви хочете дізнатися більше про гоблінську інженерію, віднесіть посібник з інженерних дисциплін Ніксу Вертопруженю в Пристроблях.", [4] = "Я відчуваю запах свіжих новобранців так само як чудовий вибуховий порошок — за кілометр. Ти {стать:прийшов:прийшла} сюди, щоб навчитися майстерності виготовлення вибухівки?", [5] = "Ну що ж, {ім'я}, ти {стать:вчинив:вчинила} мудро, звернувшись до мене за наставництвом! Будь-який приблуда може стати експертом в основах інженерії — гноми та їх опромінений дім Гномреґан є свідченням цього. Але для того, щоб володіти дисципліною гоблінської інженерії, потрібен сильний розум і стійка рука (з особливим акцентом на СТІЙКУ).\n\nТримай вуха наготові, {ім'я}, і можливо, ти чогось навчишся.", ["en"] = "Goblin Engineering", ["tasks"] = { ["Manual of Engineering Disciplines"] = "посібник з інженерних дисциплін", ["Manual of Engineering Disciplines (Provided)"] = "посібник з інженерних дисциплін (видано)" } },
    [420] = { [1] = "Спостереження Сеніра", [2] = "Тунельні троги неймовірно агресивні. Вони без вагань нападають на мандрівників. Хоча ти виглядаєш так, наче маєш впоратись.\n\nЯкщо ти хочеш поговорити з Сеніром, шукай його в Хараносі.\n\nЙди через тунель, після чого продовжуй йти дорогою і ти дійдеш прямо до Хараноса.", [3] = "Доставте звіт Ґреліна до Сеніра Білоборода в Харанос.", [4] = "Як справи? Не хочеш випити по стаканчику зі мною? Те що треба в такий мороз.", [5] = "Що це? О, звіт мого брата. Хмм...\n\nЯ казав йому не зловживати іменем короля, але ж він мене не послухав. Гадаю, нічого страшного, хоча, це трішки наведе шороху в Сенаті. Але хай не розслабляються, хе-хе.\n\nТим не менш, схоже що мені теж потрібно відправити звіт до Залізогарту. Я трішки забарився з цим через цей клятий холод.\n\nВ мене буде трішки роботи для тебе, якщо тобі цікаво.", ["en"] = "Senir's Observations", ["tasks"] = { ["Deliver Grelin's report to Senir Whitebeard in Kharanos."] = "Доставте звіт Ґреліна Сеніреві Білобороду в Хараносі.", ["Grelin's Report"] = "звіт Ґреліна", ["Grelin's Report (Provided)"] = "звіт Ґреліна (видано)" } },
    [4241] = { [1] = "Маршал Віндзор", [2] = "То цей нікчемний боягуз каже, що Віндзор живий?\n\nЗбирайся, {стать:заступнику:заступнице}, ти відправишся на його пошуки. Якщо Віндзор живий, ти маєш повернути його назад. Якщо ж він мертвий — мені потрібні докази.\n\n<Максвелл сміється.>\n\nБ'юся об заклад, тобі вже набридло це чути, еге ж?", [3] = "Відправляйтесь до Чорноскельної гори, що знаходиться на північному заході та спустіться в її надра. Дізнайтеся, що сталося з маршалом Віндзором.\n\nВи пригадуєте, як Джон Лахмітник говорив щось про те, що Віндзора забрали до в'язниці.", [5] = "Де він? Я вб'ю його!", ["en"] = "Marshal Windsor" },
    [4242] = { [1] = "Втрачена надія", [2] = "Болвар — дурень. Я збирав ці дорогоцінні \"докази\" тільки для того, щоб запхати їх йому в горлянку.\n\nВін сліпий блазень. Докази стоять за два метри від нього, а він не бачить.\n\nЩо стосується зібраних мною відомостей, вони втрачені. Зникли. Безслідно.\n\nЯкщо я коли-небудь знайду Залізогуб і вилізу з цього лабіринту, я перш за все відправлюсь в Штормовій, щоб встромити свій молот між очей цієї рептилії.\n\nЗалиш мене, {ім'я}.", [3] = "Повідомте маршалу Максвеллу погані новини.", [5] = "Він, мабуть, з'їхав з глузду.\n\n<Максвелл опускає голову в знак жалоби.>\n\nШкода, що такий гордий і благородний воїн перетворився на божевільного. Здається, ми зайшли в глухий кут...\n\nТи добре {стать:потрудився:потрудилася}, {ім'я} і я маю віддячити тобі.", ["en"] = "Abandoned Hope" },
    [4263] = { [1] = "Спалахій!", [2] = "Ти {стать:впевнений:впевнена}, що Пірон перед смертю сказав \"Спалахій\"?\n\n<Джалінда важко ковтає.>\n\nЛорд Спалахій — прислужник Раґнароса! О боже... Що ж нам робити?\n\nЯк думаєш, ти впораєшся зі ще одним завданням? Мені більше нема кого відправити, {ім'я}!\n\nМи ніколи не переможемо наших ворогів, якщо Спалахій продовжить підіймати Пірона з попелу.\n\nТи {стать:повинен:повинна} знайти та знищити лорда Спалахія!", [3] = "Знайдіть лорд Спалахія в Чорноскельних надрах та знищте його!", [4] = "Ти {стать:вбив:вбила} цю нечисть?", [5] = "Ой, лишенько! Ти {стать:впевнений:впевнена}, що Спалахій сказав \"Раґнарос\"?\n\n<Джалінда простягає вам щось, поплескує по зап'ястку та занурюється у роздуми.>", ["en"] = "Incendius!", ["tasks"] = { ["Lord Incendius"] = "лорд Спалахій", ["Lord Incendius slain"] = "лорд Спалахій: убито" } },
    [4264] = { [1] = "Зім'ята записка", [2] = "Записка вкрита брудом. Текст ледь розбірливий, але можна прочитати наступне:\n\n...яка іронія...\n\n...занепад розгромленого Альянсу...\n\n...якби не старанність генерала Кузні Гніву, ми б ніколи не розгадали шифр...\n\n...Арґельмах майже закінчив розшифрування записок Віндзора.\n\nНаш повелитель підніметься з глибин і розчавить всіх, хто залишився...\n\n-Імператор Даґран Тауріссан.", [3] = "Схоже, що ви натрапили на щось, що може зацікавити маршала Віндзора. Можливо, ще не все втрачено.", [4] = "<Маршал Віндзор помітив записку у вашій руці.>\n\nЩо це в тебе, {ім'я}?", [5] = "<Маршал Віндзор бере записку та починає читати.>", ["en"] = "A Crumpled Up Note", ["tasks"] = { ["A Crumpled Up Note"] = "зім'ята записка", ["A Crumpled Up Note (Provided)"] = "зім'ята записка (видано)" } },
    [4265] = { [1] = "Звільнений з вулика", [2] = "Коли ви доторкаєтеся до кокона, він розкривається і ви бачите всередині ще живого нічного ельфа. Він, здається, цілий і неушкоджений, лише непритомний. Поки ви витягаєте його з кокона, він оживає.\n\n\"Слава Елуні — ти {стать:врятував:врятувала} мене! Я... Я — Раскал, і я прокинувся паралізованим всередині цього кокона після того, як ці комахи схопили мене. Тебе з фортеці прислали?\"\n\nСхоже, що ви знайшли зниклого кур'єра!", [3] = "Звільніть Раскаля з вулика Зукк'аш.\n\nПоверніться до Ґінро Палкого Багаття у фортецю Перомісяць і повідомте йому, що Раскал живий і здоровий.", [4] = "Є якесь повідомлення для мене, {ім'я}?", [5] = "Ласкаво просимо додому, {ім'я}. Раскал прийшов всього кілька хвилин тому і розповів мені, що сталося.\n\nЯ... та що там, вся наша фортеця не знає, як тобі дякувати за твої подвиги. Раскал загинув би, якби не твоя своєчасна допомога. А ти ж допомагаєш нам не заради плати, як якийсь найманець! Ти {стать:справжній герой:справжня героїня}. Знай, що відтепер Ґінро Палке Багаття — твій друг до кінця віків!", ["en"] = "Freed from the Hive", ["tasks"] = { ["Free Raschal."] = "Вільний Раскал." } },
    [4266] = { [1] = "Вітання героя", [2] = "{ім'я}, генерал Шандріса Перомісяць хотіла б особисто поговорити з тобою. Напевно, вона хоче подякувати тобі за службу для фортеці, але я знаю, що вона також хоче поговорити з тобою про комах, яких ти та Раскал зустріли на південному заході Фераласа. Звіти про цих комах Зукк'аш звучать... скажемо так, жахливо.\n\nГенерал Перомісяць чекає на тебе в головному таборі.", [3] = "Поговоріть з Шандрісою Перомісяць у фортеці Перомісяць.", [5] = "{ім'я}, щиро дякую тобі за допомогу. Твоя відвага перед обличчям непереборних труднощів гідна в тисячу разів більшої винагороди. Але, попри це, я сподіваюся, що ти приймеш цю скромну нагороду від імені усієї фортеці.\n\nА тепер, якщо дозволиш, я хотіла б попросити тебе ще про одну послугу. У зв'язку з виявленням вулика Зукк'аш у Фераласі, я вважаю, що це завдання слід доручити саме тобі.", ["en"] = "A Hero's Welcome" },
    [4267] = { [1] = "Нашестя силітидів", [2] = "Я довіряю тобі копію звіту, який Раскал підготував щодо нашестя в південно-східному Фераласі. Хоча повний звіт буде надіслано в Дарнас, я хочу, щоб ти {стать:передав:передала} цю копію представниці Протекторату. Її звати Ґрасіна Міцнодуха, це жриця, яка живе в храмі Місяця в Дарнасі. Вона має широкі знання щодо цих істот, і якщо вона ознайомиться з цим звітом, це піде на користь усім нам.\n\nЙди — і нехай щастить, {ім'я}. І нехай Елуна береже нас.", [3] = "Віднесіть звіт Раскала до Ґрасіни Міцнодухої в Дарнас.", [4] = "Ласкаво просимо до цього благословенного храму. Твоя дорога сюди з фортеці Перомісяць була передбачена мною. Ти {стать:приніс:принесла} звіт, який просила тебе принести Шандріс Перомісяць?", [5] = "Ми, нічні ельфи, знаємо про жах, згаданий тут. Шандріс вчинила мудро, відправивши тебе зі звітом до мене.\n\nЦі істоти швидко поглинули б Фералас. Вони є однією з найбільших загроз, з якими ми всі коли-небудь стикалися. Запам'ятай цю назву, {ім'я}: силітиди. Ці комахи, що згадуються тут, є силітидами, і вони є інструментом однієї з найбільших загроз, з якими зіткнуться як Орда, так і Альянс.\n\nЯ молюся, щоб у нас вистачило рішучості перемогти їх, перш ніж вони знищать нас.", ["en"] = "Rise of the Silithid", ["tasks"] = { ["Raschal's Report"] = "звіт Раскала", ["Raschal's Report (Provided)"] = "звіт Раскала (видано)" } },
    [4282] = { [1] = "Крихта надії", [2] = "<Маршал Віндзор схвильовано трясе запискою.>\n\nТи розумієш, що це означає, {ім'я}?\n\nМожливо, ще не все втрачено! Наскільки я розумію, інформація зараз є у двох дворфів Темного Заліза: генерала Кузні Гніву і повелителя големів Арґельмаха. Думаю, вони не віддадуть інформацію просто так, навіть якщо ми переконливо попросимо.\n\nСподіваюсь, ти {стать:готовий:готова} до бою.\n\nІди та знайти цих двох лиходіїв! Вбий їх і поверни мені втрачену інформацію.", [3] = "Поверніть маршалу Віндзору втрачену інформацію.\n\nМаршал Віндзор впевнений, що інформацією заволоділи повелитель големів Арґельмах та генерал Кузня Гніву.", [4] = "Ще трохи й це все закінчиться.", [5] = "<Маршал Віндзор вихоплює скрижалі з ваших рук.>\n\nТреба забиратися звідси!", ["en"] = "A Shred of Hope", ["tasks"] = { ["Marshal Windsor's Lost Information"] = "втрачена інформація маршала Віндзора", ["Marshal Windsor's Lost Information (Provided)"] = "втрачена інформація маршала Віндзора (видано)" } },
    [4283] = { [1] = "П'ЯТДЕСЯТ! АГА!", [2] = "Я тобі розкрию маленьку таємницю, солдате. Підійди трохи ближче.\n\nЯ ТУТ ЄДИНИЙ НОРМАЛЬНИЙ!\n\nПодивись на цей народ! Ти {стать:повірив:повірила} би, що вони всі безумці? Але вони такі! ПСИХИ! ВАР'ЯТИ!\n\n<Оралій понижує голос.>\n\nДавай просто залишимо це між нами та моїм товаришем, капітаном Вінкі.\n\n<Оралій хапає рукою повітря і стискає його.>\n\nТак от, окрім вух огрів, я збираю ще й медальйони. Сьогодні — орчі. П'ятдесят штук. ДАВАЙ!\n\n<Оралій дмухає в уявний ріг.>\n\nСТУЛИСЯ!", [3] = "Оралію потрібно 50 медальйонів Чорнокаменю. Скоріше за все, ці медальйони можна знайти в орків у Палаючому степу.", [4] = "<Оралій говорить у досить велике, відрізане вухо огра.>\n\nБаза, я Палаючий степ. База, прийом.", [5] = "Ти {стать:зробив:зробила} це! Твоя нагорода: потри мені живіт! ДАВАЙ! ТРИ!", ["en"] = "FIFTY! YEP!", ["tasks"] = { ["Blackrock Medallion"] = "медальйон Чорнокаменю", ["Blackrock Medallion (Provided)"] = "медальйон Чорнокаменю (видано)" } },
    [4286] = { [1] = "Найкраще добро", [2] = "Капітан Вінкі запевняє, що дворфи Темного Заліза з Чорноскельних надр присвоїли собі все найкраще добро. Правда, Вінкі?\n\n<Оралій всіма силами вдає з себе пірата.>\n\nАРРР, {стать:СУХОПУТНИЙ:СУХОПУТНА}! ТАК І Є!\n\nРозумієш, про що я? Ти {стать:повинен:повинна} залізти туди та принести мені кілька зразків цього їхнього добра.\n\nЙди туди та покажи на що {стать:здатен:здатна}!", [3] = "Вирушайте в Чорноскельні надра та знайдіть 20 поясних сумок Темного Заліза. Коли виконаєте завдання, поверніться до Оралія. Ви здогадуєтесь, що такі поясні сумки можна знайти у дворфів Темного Заліза.", [4] = "Не заважай мені, {ім'я}. Нам з Вінкі потрібно з деким зустрітися.", [5] = "<Оралій копирсається в купі поясних сумок.>\n\nО, ЧУДОВО!\n\n<Оралій засовує свій великий ніс у купу і принюхується.>\n\nСМАКОТА! Поглянь на всі ці смаколики!\n\nВізьми собі один, {ім'я}. Тут на всіх вистачить.", ["en"] = "The Good Stuff", ["tasks"] = { ["Dark Iron Fanny Pack"] = "поясна сумка Темного Заліза", ["Dark Iron Fanny Pack (Provided)"] = "поясна сумка Темного Заліза (видано)" } },
    [4297] = { [1] = "Їжа для малюка", [2] = "Райдужні хамелеони всеїдні і їдять як м'ясо, так і рослини. Якщо це яйце має вилупитися, нам слід підготуватися. Ці маленькі істоти полюбляють соковите сире м'ясо, зокрема вирізку срібногривих ловців. Я ніколи не зміг зрозуміти, чому це так. Мабуть, це такий задум Елуни... можливо, ельфи мали бути захисниками... не знаю.\n\nЯ попіклуюсь про яйце, а ти принеси мені кілька смачних вирізок срібногривих ловців для малюка.", [3] = "Принесіть 5 вирізок срібногривих ловців Аґнару Звіролову у Внутрішні землі.", [4] = "Вже {стать:знайшов:знайшла} м'ясо, {ім'я}? Твоє яйце майже готове вилупитися. І якщо малюк не поїсть як слід, щойно з'явившись на світ, він і тижня не проживе, і мені буде шкода, якщо таке трапиться.\n\nПравду кажучи, {ім'я}, я заздрю тобі, що ти {стать:отримав:отримала} це яйце. Не змушуй мене шкодувати про те, що я допомагаю тобі.", [5] = "Так, це м'ясо чудово підійде. А тим часом якщо я не помиляюся, твій дракончик готовий вилупитися. Ну, як відчуття? Ти скоро станеш {стать:батьком:матір'ю}! Ха-ха, не {стать:думав:думала}, що тобі доведеться мати таку відповідальність?", ["en"] = "Food for Baby", ["tasks"] = { ["Silvermane Stalker Flank"] = "вирізка срібногривого ловця", ["Silvermane Stalker Flank (Provided)"] = "вирізка срібногривого ловця (видано)" } },
    [4298] = { [1] = "У вас з'явилося маля!", [2] = "Ого, він вже вилуплюється!", [3] = "Поговоріть з Аґнаром Звіроловом у Внутрішніх землях.", [5] = "Ось, візьми яйце... Тобі краще тримати його при собі, щоб дракончик прив'язався до тебе і вважав тебе {стать:своїм батьком:своєю матір'ю}.\n\nМої вітання, {ім'я}. Ти {стать:став батьком:стала матір'ю}! Чи типу того...", ["en"] = "Becoming a Parent" },
    [432] = { [1] = "Кляті троги!", [2] = "Ці прокляті Світлом троги розгромили всю зону розкопок! Поглянь-но, вони розтрощили ще одну бочку пороху!\n\nУх, хотів би я спуститись туди та повідривати їм голови! Всіх би повбивав!\n\nАле я вже не той, що раніше, весь цей стрес і злоба... Вони нічого мені лишили!\n\nЯ б і сам їх повбивав, та здоров'я вже не те! Йди в кар'єр та повбивай цих тварюк! Я заплачу! Тільки перебий їх, всіх перебий!", [3] = "Вбийте 6 кам'янощелепих череполомів для десятника Камнеброва з кар'єру Ґол'Болар.", [4] = "Гр-р-р... Я такий злющий..", [5] = "Ох, аж легше на душі стало...\n\nАле я не заспокоюсь поки вони всі не здохнуть! Всі до одного!", ["en"] = "Those Blasted Troggs!", ["tasks"] = { ["Rockjaw Skullthumper"] = "кам'янощелепий череполом", ["Rockjaw Skullthumper slain"] = "кам'янощелепий череполом: убито" } },
    [4322] = { [1] = "Втеча!", [2] = "Нам треба забиратися звідси, {ім'я}. Допоможи мені забрати речі та звільнити друзів. Якщо нам вдасться втекти, ти маєш піти до Сторожі Моргана і поговорити з маршалом Максвеллом. Він дасть тобі подальші інструкції.", [3] = "Допоможіть маршалу Віндзору повернути його спорядження та звільнити друзів. Коли впораєтесь з цим, поверніться до маршала Максвелла.", [4] = "Ти виглядаєш {стать:виснаженим:виснаженою}, {ім'я}. Можливо, тобі краще присісти біля вогнища і відпочити.", [5] = "Дивовижно, {ім'я}. Просто дивовижно. Віндзор увірвався сюди буквально кілька хвилин тому. Він робив якісь грандіозні заяви, але стверджував, що в нього є на це докази. Зараз він прямує до Штормовію, щоб кинути виклик Болвару та... леді Престор.", ["en"] = "Jail Break!", ["tasks"] = { ["Jail Break!"] = "Втеча з в'язниці!" } },
    [433] = { [1] = "Слуга народу", [2] = "Як член Сенату та Ліги дослідників, я взяв на себе проблему трогів, що заполонили наші землі.\n\nВони без будь-якої причини рознесли кар'єр Ґол'Болар. Чим глибше ми копаємо, ти більше вони лізуть назовні, трощать обладнання і розлякують гірняків. Вони не залишили нам іншого вибору, як винищити їх якомога більше, відбудуватись і продовжити роботу.\n\nЯкщо ти допоможеш мені з трогами, я з радістю компенсую твої затрати часу.", [3] = "Вбийте 10 кам'янощелепих кісткохрустів для сенатора Мегра Камнедара в кар'єрі Ґол'Болар.", [4] = "Якщо ми зможемо позбавитись трогів у кар'єрі Ґол'Болар, це буде перший крок до нашого позбавлення від цієї загрози.", [5] = "Це тільки початок. Сподіваюсь, ми зможемо скористатись цим й поставимо загін горянинів для охорони кар'єру. Опісля, ми зможемо почати відновлювати споруди та повертати гірняків до роботи.\n\nДякую тобі за допомогу, {ім'я}.", ["en"] = "The Public Servant", ["tasks"] = { ["Rockjaw Bonesnapper"] = "кам'янощелепий кісткохруст", ["Rockjaw Bonesnapper slain"] = "кам'янощелепий кісткохруст: убито" } },
    [434] = { [1] = "В атаку!", [2] = "Коли я надягну маскування на робота-шпигуна й увімкну його, він піде поговорити з Лесковаром. Охоронці пропустять його без проблем.\n\nПоки ти {стать:збирав:збирала} все необхідне, я передав Марзону звістку про те, що йому треба зустрітись з Лесковаром. Ще й підкинув кілька хибних чуток.\n\nЛесковар відпустить свою охорону і буде чекати на Марзона в саду. Як почуєш щось про Непокірних — починай діяти. Вбий їх обох до повернення охорони та повертайся до Тріаса.", [3] = "Сховайтесь в саду і підслухайте розмову лорда Грегора Лесковара та Марзона Тихого Леза, після чого вбийте їх обох та поверніться до Еллінга Тріаса в Штормовій.", [4] = "Так, {ім'я}? Як там справи з Тіріоном? Він поділився зі мною своїм планом і я допоміг йому, змусивши Марзона зустрітись з Лесковаром.\n\nМарзон нашкодив багатьом жителям Штормовію, багато з яких — мої близькі друзі. Ніхто не переходить дорогу моїм друзям... знаючи про наслідки.\n\nШкода, що мені довелось знову допомагати Гичу та ШУР. Ну що ж, жоден план не ідеальний.", [5] = "Тож з ними покінчено? Дякую тобі за твою рішучість, {ім'я}. Ти {стать:довів:довела} свою відданість Альянсу. З твого дозволу, я слідкуватиму за твоїми діяннями — ти ще можеш знадобитись.\n\nТільки не вплутайся в халепу.", ["en"] = "The Attack!", ["tasks"] = { ["Lord Gregor Lescovar"] = "Лорд Грегор Лесковар", ["Lord Gregor Lescovar (Provided)"] = "Лорд Грегор Лесковар (видано)", ["Lord Gregor Lescovar slain"] = "лорд Грегор Лесковар: убито", ["Marzon the Silent Blade"] = "Марзон Тихе Лезо", ["Marzon the Silent Blade slain"] = "Марзон Тихе Лезо: убито" } },
    [4341] = { [1] = "Харан Могутній Молот", [2] = "Ти {стать:був:була} в руїнах Тауріссана? Тобі не траплявся жалюгідний негідник, на ім'я Харан Могутній Молот? Це дворф, який мав охороняти мою дівчинку!\n\n<Король схлипує.>\n\nА тепер вона пропала, {ім'я}!\n\nМої воїни перевернули весь степ догори дном. Їм вдалося лиш дізнатися, що моя донька може перебувати в Чорноскельних надрах. Може, вона вже мертва!\n\nХарана нібито має бути в тамтешній в'язниці... Знайди його! Мені потрібні відповіді!", [3] = "Відправляйтесь в Чорноскельні надра та знайдіть Харана Могутнього Молота.\n\nКороль говорив, що Харана утримують в тамтешній в'язниці.", [5] = "Прошу, дозволь мені все пояснити.", ["en"] = "Kharan Mighthammer" },
    [4342] = { [1] = "Розповідь Харана", [2] = "Будь ласка, вислухай мене, перш ніж приймати рішення!", [3] = "Вислухайте розповідь Харана Могутнього Молота.", [4] = "Дозволь мені закінчити розповідь.", [5] = "Як розумієш, я просто нічого не міг вдіяти.", ["en"] = "Kharan's Tale", ["tasks"] = { ["Kharan's Tale"] = "Оповідь Харана" } },
    [436] = { [1] = "Розкопки Залізоплета", [2] = "Розвідувач Залізоплет керує розкопками древніх руїн на схід від озера. Останнім часом справа йде мляво і це враховуючи, скільки ми йому відправили припасів.\n\nЗалізоплет - надійний і чесний дворф, для якого важливий результат, тож я думаю, що хтось намагається йому завадити.\n\nЙди на розкопки Залізоплета і поговори з Маґмаром Люторубом. Він займається процесами розкопок і зможе пояснити причину затримки.\n\nЩоб дістатись туди, обійди озеро з півдня і йди на схід.", [3] = "Поговоріть з дослідником Люторубом.", [5] = "Джерн хоче знати причину затримки, ге?\n\nЗалізоплет як раз закінчує свій звіт, де будуть всі подробиці, але я тобі от що скажу:\n\nЦе все троги!!", ["en"] = "Ironband's Excavation" },
    [4361] = { [1] = "Недобра звістка", [2] = "Ти {стать:повинен:повинна} передати цю інформацію королю Маґні, {ім'я}. Він знає, що робити!", [3] = "Поверніться в Залізогарт та повідомте погані новини королю Маґні Бронзобородому.", [5] = "<Король Маґні розгнівано грюкає кулаком по столі.>", ["en"] = "The Bearer of Bad News" },
    [4362] = { [1] = "Доля Залізогарта", [2] = "Здається, моя доля та доля всього Залізогарта в руках мого давнього ворога — Даґрана Тауріссана.\n\nТи моя остання надія, {ім'я}. Врятуй мою дорогу доньку, Мойру!\n\nЄ лише один спосіб впевнитись, що закляття, яке Тауріссан наклав на Мойру, знято — вбити його.\n\nІ {ім'я}, не нашкодь їй! Пам'ятай, що вона під контролем Тауріссана! Все, що вона робить чи каже — це наслідок його злих чар!", [3] = "Поверніться в Чорноскельні надра та врятуйте принцесу Мойру Бронзобороду від злих чар імператора Даґрана Тауріссана.", [5] = "<Принцеса Бронзоборода плаче через втрату імператора Даґрана Тауріссана.>\n\nЧому???", ["en"] = "The Fate of the Kingdom", ["tasks"] = { ["Emperor Dagran Thaurissan"] = "Імператор Дагран Таурісан", ["Emperor Dagran Thaurissan (Provided)"] = "Імператор Дагран Таурісан (видано)", ["Emperor Dagran Thaurissan slain"] = "Імператор Дагран Таурісан: убито" } },
    [4363] = { [1] = "Королівська несподіванка", [2] = "Тауріссан був великим і благородним дворфом. Ти {стать:зруйнував:зруйнувала} моє життя і життя моєї майбутньої дитини!\n\n<Ви впевнені, що принцеса Бронзоборода досі перебуває під дією чар Тауріссана.>\n\nПовертайся в Залізогарт і скажи моєму батькові, що його спадкоємцем стане дворф Темного Заліза.\n\nПодобається йому це чи ні, але так воно і буде.", [3] = "Поверніться в Залізогарт та поговоріть з королем Маґні Бронзобородим.", [5] = "<Король Магні Бронзобородий засмучений.>\n\nЗдається, навіть померши, Тауріссан переміг.\n\nТи {стать:вільний:вільна}, {ім'я}. Перш ніж підеш, можеш вибрати собі нагороду з королівської скарбниці.", ["en"] = "The Princess's Surprise" },
    [4441] = { [1] = "Ув'язнені скверною древні", [2] = "Флейта, яку ти {стать:знайшов:знайшла}, була зроблена з деревини древнього захисника, союзників дереванів, які вірно захищали нічних ельфів.\n\nСатири здатні порочити все, що потрапляє до їхніх рук, включаючи древніх, для яких Сквернолісся є рідною домівкою. За допомогою скверни, дух древнього потрапив у пута і тепер мучиться, не в змозі звільнитися. Без сумніву, ці зразки пут скверни, що ти {стать:знайшов:знайшла}, напевно, пов'язані з цим.\n\nМи повинні спробувати очистити цю флейту, {ім'я}. Принеси мені благословенну воду з храму Місяця, що в Дарнасі.", [3] = "Відправляйтеся в Дарнас і наповніть флакон Ерідани благословенною водою з храму Місяця. Поверніться до Ерідани з наповненим флаконом.", [4] = "Сподіваємося, що вода вивільнить дух древнього і дозволить йому знайти спокій.", [5] = "Дякую, {ім'я}. Тепер ми повинні молитися, щоб нам вдалося зцілити завдану шкоду...", ["en"] = "Felbound Ancients", ["tasks"] = { ["Vial of Blessed Water"] = "флакон з благословенною водою", ["Vial of Blessed Water (Provided)"] = "флакон з благословенною водою (видано)" } },
    [4442] = { [1] = "Очищення!", [2] = "Використовуючи воду Елуни, я спробую очистити флейту. Ми повинні покласти край цим стражданням...\n\nНехай Елуна веде мої руки й серце.\n\nПоговори зі мною за мить.", [3] = "Поговоріть з Еріданою ще раз за мить.", [5] = "З допомогою благословенної води я змогла знищити зв'язок між флейтою та духом древнього. Думаю, якщо ти використаєш цю флейту у священному місці, ти зможеш викликати духів древніх.\n\nМожливо, ти можеш спробувати в руїнах на південному заході Залізодревих лісів. Багато осквернених дереванів колись населяло цю частину Сквернолісся, і, можливо, вони все ще там проживають, навіть у формі духів.", ["en"] = "Purified!" },
    [4493] = { [1] = "Нашестя силітидів", [2] = "Схоже, що мета силітидів, а точніше — сенс їхнього існування — поглинати на своєму шляху все, що відрізняється від них. Вони дуже зосереджено займаються цим, тому й становлять серйозну загрозу всьому живому на Азероті.\n\nВсе, що ми бачили дотепер — лише перші кроки. Я підозрюю, що їхня сила походить з глибин Калімдору — кратеру Ун'Ґоро. Вирушай до Пристробляху в пустелю Танаріс і поговори з алхіміком Товкачером. Розкажи йому про мою теорію. Він неодмінно допоможе нам у боротьбі з силітидами.", [3] = "Поговоріть з алхіміком Товкачером у Пристроблясі.", [5] = "Так, я зрозумів, що тебе прислала до мене Ґрасіна. Твій досвід у боротьбі з цими чудовиськами неоціненний. Я ще не чув ні про кого, хто мав справу з ними. Щодо ідеї Ґрасіни про їх походження з кратера Ун'Ґоро... можливо, так воно і є. Ун'Ґоро — це таємничі й небезпечні джунглі на захід звідси. Можливо, там ми й знайдемо пояснення природи силітидів.", ["en"] = "March of the Silithid" },
    [45] = { [1] = "Доля Рольфа", [2] = "Після подальшого обшуку місцевості ви помічаєте сплутані сліди, що ведуть на схід уздовж берега озера Кам'яних Обелісків. Вдалині, ще східніше, можна ледь-ледь побачити поселення мурлоків.\n\nМожливо, Рольфа там спіткала страшна доля...", [3] = "Пошукайте сліди або ознаки смерті Рольфа в поселенні мурлоків.", [5] = "На шиї мерця ви знаходите металевий медальйон з гравіюванням \"Піхотинець Рольф Гартфорд\".", ["en"] = "Discover Rolf's Fate" },
    [4510] = { [1] = "Затишшя перед бурею", [2] = "{ім'я}, твоя допомога просто неоціненна. Без сумніву, прийде час, коли я знову попрошу тебе про допомогу в боротьбі з силітидами. Ми повинні засвоїти те, що ми дізналися в Ун'Горо. Боюся, що мої припущення про те, що силітиди походять з Ун'Горо, тепер помилкові... і десь їх набагато більше.\n\nВіднеси цю записку Ідріані в банк. Вона дасть тобі дещо з мого сховища на знак моєї вдячності. Дякую за допомогу, {стать:хоробрий:хоробра} {клас:к}.", [3] = "Принесіть банківську розписку Ідріані в банк Дарнасу.", [4] = "Елуне'адоре, {клас:к}. Чим я можу допомогти?", [5] = "Ця розписка уповноважує мене видати вам предмет зі сховища Ґрасіни Міцнодухої та подарувати вам. Схоже, вас можна привітати!", ["en"] = "Calm Before the Storm", ["tasks"] = { ["Bank Voucher"] = "банківська розписка", ["Bank Voucher (Provided)"] = "банківська розписка (видано)" } },
    [4512] = { [1] = "Великий шлях маленького слимака", [2] = "Та найбільше я вивчав слизнів. Розумію, звучить дивно, але ж вони всюди!\n\nНещодавно я допомагав леді з гавані Менетілів знайти її сумку — її з'їли слизні. Я бачив, як члени королівського товариства аптекарів з Підмістя збирають зразки слизу. І я хочу знати, нащо! Для чого він їм?\n\nЯ чув, що в Скверноліссі є багато слизнів. Мені потрібні зразки їх слизу для досліджень. Я дам тобі банки, в які ти зможеш зібрати зразки з вбитих слимаків.", [3] = "Принесіть 6 наповнених проклятим слизом банок та 6 наповнених забрудненим слизом банок Ларісу Розтрибу в Залізогарт.", [4] = "Деякі мої експерименти просто неймовірні. Думаю, ще трохи, і я зможу зрозуміти природу цих створінь і яку роль вони зіграли в розвитку життя Азероту... якщо вони взагалі якось з цим пов'язані.\n\nОдна з моїх найкращих теорій, в яку, однак, не всі вірять, це те, що ці слизні пов'язані зі створенням цієї планети... наче вони є її виділеннями.\n\nТа я не зможу ні довести її, ні спростувати, поки не отримаю більше зразків.", [5] = "Блискуча робота, {ім'я}! Тобі вдалось підібратись до них достатньо близько, щоб зібрати зразки й не постраждати! Дякую, це чудові зразки. Я якомога скоріше почну їх досліджувати.\n\nЯкщо в мене все вийде — я стану одним з найвеличніших науковців Ліги дослідників!\n\nЦе покаже дворфам, що вони правильно вчинили, прийнявши нас в Залізогарті після катастрофи в Гномреґані.", ["en"] = "A Little Slime Goes a Long Way", ["tasks"] = { ["Filled Cursed Ooze Jar"] = "наповнена проклятим слизом банка", ["Filled Cursed Ooze Jar (Provided)"] = "наповнена проклятим слизом банка (видано)", ["Filled Tainted Ooze Jar"] = "наповнена забрудненим слизом банка", ["Filled Tainted Ooze Jar (Provided)"] = "наповнена забрудненим слизом банка (видано)" } },
    [4513] = { [1] = "Великий шлях маленького слимака", [2] = "Мені знадобиться більше зразків, {ім'я}. Але... як би це сказати... вони мають бути чисті. Знаю, знаю. Що означає \"чисті\", Ларіс? Я не впевнений. Знаю тільки, що ці зразки такі ж забруднені, як Сквернолісся. І це важливе спостереження. Схоже, що слизні пристосовуються до умов місця, в якому вони знаходяться. І мені потрібно знайти чисті зразки, які не зазнали таких змін. Але де? Де?!\n\n{ім'я}, візьми ці контейнери про всяк випадок. Може, тобі вдасться знайти чисті зразки.", [3] = "Принесіть 10 наповнених чистими зразками слизу банок Ларісу Розтрибу в Залізогарт.\n\nЯкщо вам важко їх знайти, можливо, варто отримати більше підказок від Ларіса.", [4] = "Так багато треба обміркувати. Що це може означати? І як це впливає на жителів Азероту?", [5] = "Ти {стать:знайшов:знайшла} їх? {ім'я}, ти просто золото. Твоя відданість та допомога просто надзвичайні, я й не знаю, як віддячити.\n\nПрошу, прийми це як винагороду. Мені треба трохи попрацювати, але якщо прийдеш пізніше — впевнений, у мене буде для тебе робота.\n\nДякую тобі. Щиро дякую.", ["en"] = "A Little Slime Goes a Long Way", ["tasks"] = { ["Filled Pure Sample Jar"] = "наповнена чистим слизом банка", ["Filled Pure Sample Jar (Provided)"] = "наповнена чистим слизом банка (видано)" } },
    [453] = { [1] = "Пошуки таємничого незнайомця", [2] = "Нехай щастить, {ім'я}. Я сподіваюся, ти знайдеш цього хлопця, і сподіваюся, що знайдеш його живим.\n\nЯкщо він покинув безпечний Темноділ, то може стати здобиччю диких звірів.", [3] = "Знайдіть таємничого незнайомця. Ось ваші підказки:\n\nВін не є жителем Темнодолу.\n\nВін нервовий та дратівливий.\n\nВін покинув Темноділ і попрямував на захід.", [4] = "Хто ти {стать:такий:така}? Дай мені спокій!", [5] = "<Тремтіній зітхає...>\n\nТак, я автор цієї книги. Ти нарешті мене {стать:знайшов:знайшла}, га?\n\nНу, якщо ти {стать:прочитав:прочитала} ці записи... то знаєш лише частину історії!", ["en"] = "Finding the Shadowy Figure", ["tasks"] = { ["Book from Sven's Farm"] = "книга з ферми Свена", ["Book from Sven's Farm (Provided)"] = "книга з ферми Свена (видано)" } },
    [454] = { [1] = "Опісля засідки", [2] = "До цього... випадку ми спокійно возили діжки. Тепер нам доведеться розділити обов'язки - Міран понесе одну частину діжок, а я постежу за іншою.\n\nАле відпускати Мірана самого небезпечно. Може ти супроводиш його до розкопок?", [3] = "Поговоріть з Міраном.", [5] = "Привіт, {клас:к}.\n\nТи супроводжуватимеш мене до розкопок? Чудово... Після випадку з Саяном та його поплічниками, хтозна-що ще задумало Темне Залізо.\n\nЩо ж, мені лише залишилось дещо перевірити. Поговори зі мною, як будеш готовий йти.", ["en"] = "After the Ambush" },
    [455] = { [1] = "Альґазька битва", [2] = "Орки з клану Драконової Пащі оселились у Заболотті. А тепер вони полізли в Дун-Альґаз! Ми не можемо дозволити їм цього, інакше Лох-Модан буде відрізаний від гавані Менетілів - нашого порту та твердині у Заболотті.\n\nПрорвись через Дун-Альґаз до Заболоття та вбий стільки орків, скільки зможеш! Доповіси про виконання Вальстаґу Залізогубу в гавані Менетілів.\n\nЩоб дістатись гавані - пройди через Дун-Альґаз, потім йди на північ по дорозі, на роздоріжжі йди на захід.\n\nМи розраховуємо на тебе, {ім'я}. Не підведи.", [3] = "Пройдіть через Дун-Альґаз.\n\nВбийте 8 розвідників та 6 бугаїв Драконової Пащі.\n\nЗвітуйте Вальстаґу Залізогубу в гавань Менетілів.", [4] = "Ти {стать:прийшов:прийшла} з Лох-Модану? Як там справи з орками в тунелі Альґаз?", [5] = "Мда, нехороші новини.\n\nСхоже, що орки Драконової Пащі серйозно взялись за Альґаз. Зазвичай вони ховаються в горах. Що ж змусило їх піти на Альґаз...\n\nДякую, {ім'я}. Нам, певно, знадобиться твоя допомога з цими орками.", ["en"] = "The Algaz Gauntlet", ["tasks"] = { ["Dragonmaw Grunt"] = "бугай Драконової Пащі", ["Dragonmaw Grunt slain"] = "бугай Драконової Пащі: убито", ["Dragonmaw Scout"] = "розвідник Драконової Пащі", ["Dragonmaw Scout slain"] = "розвідник Драконової Пащі: убито", ["Traverse Dun Algaz"] = "Пройдіть через Дун-Альґаз" } },
    [456] = { [1] = "Баланс природи", [2] = "Вітання, {Ім'я}. Я — консерватор Ільталайн, і моїм призначенням у Тінистій долині є підтримка балансу природи.\n\nВесняні дощі цього року були особливо рясними, що спричинило процвітання одних лісових тварин і страждання інших.\n\nНа жаль, популяції ночезубів і татарних кнурів занадто збільшилися, але у Тінистій долині не вистачить їжі для такої кількості звірів. Допоможи нам, {стать:юний:юна} {клас:к}, скороти чисельність кнурів і ночезубів, щоб природа й надалі залишалася у гармонії.", [3] = "Убийте 7 молодих ночезубів і 4 молодих татарних кнурів, і поверніться до консерватора Ільталайна.", [4] = "У нас досі багато роботи, {Ім'я}. Повертайся до мене, коли ти скоротиш популяцію ночезубів і татарних кнурів.", [5] = "Ти чудово {стать:впорався:впоралася}, {Ім'я}.", ["en"] = "The Balance of Nature", ["tasks"] = { ["Young Nightsaber"] = "молодий ночезуб", ["Young Nightsaber slain"] = "молодий ночезуб: убито", ["Young Thistle Boar"] = "молодий татарний кнур", ["Young Thistle Boar slain"] = "молодий татарний кнур: убито" } },
    [457] = { [1] = "Баланс природи", [2] = "Прорідження молодших популяцій тварин тут, у Тінистій долині, було хорошим початком, {Ім'я}, проте залишилося ще багато роботи.\n\nРесурси лісу закінчаться надто швидко, якщо проблему не вирішити. Вбивство створінь природи — це необхідне зло задля блага всіх, хто поділяє цей край. Сходи до лісу та вбий коростяних ночезубів і татарних кнурів заради балансу.", [3] = "Консерваторові Ільталайну потрібно, щоб ви вбили 7 коростяних ночезубів і 7 татарних кнурів.", [4] = "Твоє завдання ще не виконане, {Ім'я}. Повертайся до мене, коли буде вбито 7 коростяних ночезубів і 7 татарних кнурів.", [5] = "Ти {стать:довів:довела} свою відданість природі, {Ім'я}. {стать:Юний:Юна} {клас:н}, як ти, матиме перспективне майбутнє.", ["en"] = "The Balance of Nature", ["tasks"] = { ["Mangy Nightsaber"] = "коростяний ночезуб", ["Mangy Nightsaber slain"] = "коростяний ночезуб: убито", ["Thistle Boar"] = "татарний кнур", ["Thistle Boar slain"] = "татарний кнур: убито" } },
    [458] = { [1] = "Захисниця лісів", [2] = "Яке щастя, що ти тут, {клас:к}. Шепіт лісових духів доносив до мене дивні вісті.\n\nТаємнича захисниця лісів, Таріндрелла, повернулася до Тінистої долини. Ліси Калімдору не відчували присутність цієї дріади роками. Відбулося щось справді прикре, якщо вона знову прийшла на ці землі.\n\nВідшукай Таріндреллу та дізнайся, що в неї за справи у нашому гаю. Одна з вартових доповіла, що бачила її на південний захід від Альдрассіля.", [3] = "Знайдіть дріаду, відому як Таріндрелла.", [5] = "Я бачу, ти {стать:відшукав:відшукала} мене, {стать:юний:юна} {раса:к}. Мелітар вчинив мудро, пославши тебе до мене.", ["en"] = "The Woodland Protector" },
    [459] = { [1] = "Захисниця лісів", [2] = "Щось лихе зароджується в лісах Тельдрассіля. Поглянь лише уздовж пагорбів, де жили мирні хутропузи. Вони покинули свої домівки та об'єднались в плем'я Кривої Сосни.\n\nЛише зараження від моху скверни могло викликати таке перетворення. Грели та їм подібні заполонили місцевість і тепер загрожують жителям Тінистої долини.\n\nВступи у бій з цими грелами та грелідами, {Ім'я}, та поглянь, чи справді вони підпали під чари злого моху скверни.", [3] = "Зберіть 8 мохів скверни та принесіть їх Таріндреллі.", [4] = "Підтвердь мої підозри, {Ім'я}, принеси мені 8 мохів скверни.", [5] = "Твоя допомога створінням Тінистої долини заслуговує на винагороду, {Ім'я}.\n\nОднак, ти {стать:підтвердив:підтвердила} мої побоювання. Якщо грелів уразив мох скверни, можна лише уявити, що сталося з хутропузами з племені Кривої Сосни, які колись тут жили.\n\nЯкщо ти будеш у Доланаарі, {стать:здібний:здібна} {клас:к}, знайди обізнаного друїда, Атрідаса Ведмежокрива. Він поділяє наше занепокоєння щодо благолополуччя лісу.", ["en"] = "The Woodland Protector", ["tasks"] = { ["Fel Moss"] = "мох скверни", ["Fel Moss (Provided)"] = "мох скверни (видано)" } },
    [46] = { [1] = "Нагорода за мурлоків", [2] = "Армія Штормовію оголосила нагороду за мурлоків-маскунів і мурлоків-здобувачів у Ельвинні. Вбий їх та принеси мені їхні порвані плавники, і армія Штормовію щедро віддячить тобі.\n\nМурлоки побудували поселення на озері Кам'яних Обелісків на північ звідси, а інше — на південь, де розгалужується ріка.", [3] = "Принесіть 8 порваних плавників мурлоків вартовому Томасу на східному ельвиннському мості.", [4] = "Як проходить полювання, {ім'я:к}?", [5] = "Ти {стать:дістав:дістала} плавники? Чудово! Маршал Дуган занепокоєний ситуацією з мурлоками на сході Ельвинну, і я буду радий повідомити йому, що ситуація повертається під контроль.\n\nІ цим ми завдячуємо тобі.", ["en"] = "Bounty on Murlocs", ["tasks"] = { ["Torn Murloc Fin"] = "порваний плавник мурлока", ["Torn Murloc Fin (Provided)"] = "порваний плавник мурлока (видано)" } },
    [463] = { [1] = "Вартовий Природи", [2] = "{стать:Чув:Чула} про Вартового Природи? Ти ж не шукаєш його, правда? Це було б безглуздо, та хто я такий, щоб зупиняти когось йти на гибель?\n\nЯкщо все ж хочеш знайти це чудовисько, то я чув, що він десь на болотах на схід від повороту на Дун-Модр. Бродить десь там з кроколісками та іншою нечистю.\n\nМожеш залишити свої пожитки мені, все одно вони тобі вже не знадобляться. Ти ж не хочеш, щоб цей зелений монстр подавивсь твоїм гаманцем?", [3] = "Знайдіть Вартового Природи.", [5] = "Коріння і лози кажуть добре про тебе, малявко. Я маю багато імен, та відкликаюсь тільки на декілька. Можеш звати мене Ретіль.\n\nПрислухайся... ці землі страждають від важких ран. Я попрошу тебе допомогти мені зцілити їх.", ["en"] = "The Greenwarden" },
    [464] = { [1] = "Бойові знамена", [2] = "Під кінець другої війни клан орків Драконової Пащі було майже знищено, коли вони втратили контроль над червоними драконами. Дракони були дуже розлючені й гнали їх аж до Ґрім-Батолу, звідки ті, що вижили, сховались в горах на схід від розкопок Вельґара.\n\nВідсидівшись і відновивши сили, вони розмістили свій табір на північний схід від Менетіла.\n\nНапади на їх табір і принеси їх бойові знамена, як доказ.", [3] = "Принесіть 8 військових знамен Драконової Пащі капітану Міцноруку.", [4] = "Ти вже {стать:атакував:атакувала} табір Драконової Пащі?", [5] = "Чудова робота, {ім'я}. Орки Драконової Пащі вже не несуть такої загрози, як коли вони мали драконів. Але вони все ще небезпечні супротивники.\n\nДраконову Пащу веде Нек'рош, син Некроса - минулого вождя клану. Некрос використовував могутню магію, щоб приборкати червоних драконів, але коли ця магія його підвела... дракони розлютились.\n\nНекрос загинув і його син поклявся помститись драконам, які вбили його батька.", ["en"] = "War Banners", ["tasks"] = { ["Dragonmaw War Banner"] = "бойове знамено Драконової Пащі", ["Dragonmaw War Banner (Provided)"] = "бойове знамено Драконової Пащі (видано)" } },
    [465] = { [1] = "Гамбіт Нек'роша", [2] = "Поки ти {стать:бився:билась} з орками Драконової Пащі, ми дещо дізнались про їх плани.\n\nНек'рош побудував катапульти й збирається взяти в осаду гавань Менетілів! Поки йде битва за Дун-Альґаз, ми відрізані під підмоги!\n\nТи маєш знищити ці катапульти. Вони в таборі Драконової Пащі.\n\nОсь, візьми цей трут. Пробийся до катапульт і підпали їх ним.\n\nЯк зробиш це - знайди та вбий Нек'роша. Ми завдамо удар по лідеру Драконової Пащі.", [3] = "Знищіть катапульти Драконової Пащі.", [4] = "А ось і одна з катапульт. Підпалюємо?", [5] = "Ви поміщаєте трохи труту на катапульту і підпалюєте його іскрою.\n\nВогонь спалахує і швидко поширюється!", ["en"] = "Nek'rosh's Gambit", ["tasks"] = { ["Dwarven Tinder"] = "дворфійський трут", ["Dwarven Tinder (Provided)"] = "дворфійський трут (видано)" } },
    [467] = { [1] = "В пошуках Камнеладу", [2] = "Пілот Камнелад обожнює свою облогову машину, як і кожен інший пілот! І він завжди радий знайти новий спосіб підсилити вогневу міць своєї машини.\n\nДо нього дійшли чутки про рідкісну руду і він шукає того, хто добуде її для нього. Якщо тобі не терпиться допомогти, знайди Камнелада у Сховищі Сталешквара в Дун-Морозі й дізнайся, чого він хоче.", [3] = "Поговоріть з пілотом Камнеладом.", [5] = "Привіт, {ім'я}. Ти тут за моїм завданням, еге ж? Приємно бачити {стать:юного:юну} {раса:з} в жилах {стать:якого:якої} кипить жага до пригод!", ["en"] = "Stonegear's Search" },
    [468] = { [1] = "Доповідь горянину Рокґару", [2] = "Горянин Рокґар шукає добровольців для походу через Дун-Альґаз до Заболоття.\n\nЯкщо не боїшся просякнути болотною жижею - поговори з Рокґаром в Дун-Альґазі. Це на північ по дорозі, за вартовою вежею.", [3] = "Поговоріть з горянином Рокґаром.", [5] = "Вітаю, {клас:к}! Ти хочеш відправитись з нами в розвідку, чи не так? Чудово!\n\nСподіваюсь, твоє спорядження в хорошому стані, бо задачі цієї \"розвідки\" трішки змінились...", ["en"] = "Report to Mountaineer Rockgar" },
    [469] = { [1] = "Щоденна доставка", [2] = "Вітаю, {стать:мандрівнику:мандрівнице}!\n\nЧи не прямуєш ти до гавані Менетілів? Якщо ні, то рекомендую завітати - це гарне місце, щоб поновити запаси, пропустити кілька пінт та відпочити.\n\nОтож, якщо ти все ж туди й прямуєш, може віднесеш цей оберемок кроколіскових шкір Джеймсу Галлорану, кожум'яці?\n\nЯ б і сам це зробив, але моя дружина останнім часом не в гуморі й мені їй краще на очі не попадатись.", [3] = "Доставте оберемок кроколіскових шкір Джеймсу Галлорану, кожум'яці, у гавань Менетілів.", [4] = "Вітаю, {клас:к}. Цікавить пара чудових чобіт? Чи, може, свіжа вироблена шкіра?", [5] = "Хмм, це від Ейнара, так? Він не з'являвся вже з тиждень, а шкіри відправляє. Певно, знову посварився з дружиною.\n\nТреба буде попросити дружину якось сходити поговорити з Сідою...", ["en"] = "Daily Delivery", ["tasks"] = { ["Bundle of Crocolisk Skins"] = "оберемок кроколіскових шкір", ["Bundle of Crocolisk Skins (Provided)"] = "оберемок кроколіскових шкір (видано)" } },
    [47] = { [1] = "Обмін золотим пилом", [2] = "У цих краях кобольди зазвичай носять при собі золотий пил. Мені б він справді знадобився... Дістань мені пил, і я заплачу тобі найкращу ціну в місті... найкращу ціну в місті!\n\nКобольдів знайдеш у Бездонній копальні, що на південь, а також біля Яшмової шахти на північному сході.", [3] = "Принесіть 10 порцій золотого пилу Ремі \"Повторюсі\" в Злотохрестя. Золотий пил можна відібрати у кобольдів у Ельвиннському лісі.", [4] = "Псс! {стать:Дістав:Дістала} золотий пил для мене... для мене?", [5] = "Дякую за пил, {ім'я:к}. Ось твоя платня, а ще... це в знак подяки від моїх колег. Тобі може знадобитись... знадобитись.", ["en"] = "Gold Dust Exchange", ["tasks"] = { ["Gold Dust"] = "золотий пил", ["Gold Dust (Provided)"] = "золотий пил (видано)" } },
    [470] = { [1] = "Копирсання в слизі", [2] = "Кожен тиждень я ходжу до могили Залізобородого, але цього разу на мене напали огидні хлюпаючі слизні! Я так розгубилась...\n\nЯ кинула в одного з них свою сумку, але йому хоч би що! Слизень просто поглинув її... На щастя, це дало мені час, щоб втекти.\n\nБіда в тім, що в сумці були мої речі!\n\nЯ не знаю, як тобі описати того слизня, вони всі виглядають однаково! Могила Залізобородого знаходиться на північному сході, біля Дун-Модру. Дуже тобі дякую!", [3] = "Відберіть сумку Сіди в одного зі слизнів біля могили Залізобородого і поверніть її власниці у гавань Менетілів.", [4] = "Ти {стать:знайшов:знайшла} мою сумку?", [5] = "Ох, дякую, {ім'я}! Я думала що вже не побачу її!\n\n<Сіда витрушує вміст сумки на землю перед тим і збирає його.>\n\nХм, мені ця сумка вже не знадобиться. Але ти можеш випрати її та користуватись.", ["en"] = "Digging Through the Ooze", ["tasks"] = { ["Sida's Bag"] = "сумка Сіди", ["Sida's Bag (Provided)"] = "сумка Сіди (видано)" } },
    [471] = { [1] = "Обов'язки учня", [2] = "Я відправив свого учня на болота по шкури наших знаменитих гігантських кроколісків Заболоття. Коли він не повернувся, я відправився на пошуки... Скажімо так: це було видовище не для слабкодухих.\n\nПовитуха каже, що він викарабкається, але ж мені все ще потрібні мої шкури!\n\n...Якщо у тебе є бажання повбивати ще кілька здоровил, я не проти - особливо після того, що вони зробили. Ти знайдеш кроколісків на узбережжі на північ звідси, за поселенням мурлоків.", [3] = "Зберіть 6 шкур гігантських кроколісків і принесіть їх Джеймсу Галлорану у гавань Менетілів.", [4] = "Мій учень - як син для мене. Йому буде важко прожити життя лише з однією ногою.\n\nАх, {ім'я}, як справи? Ти {стать:приніс:принесла} мої шкури?", [5] = "Гмм... Не думаю, що ти {стать:зацікавлений стати моїм учнем:зацікавлена стати моєю ученицею}, чи не так?\n\nХа! Та ні, я просто жартую. Ти {стать:застарий:застара} для цього. Окрім того, судячи з твого вигляду, здається, у тебе інші амбіції у житті. Однак, ти {стать:дістав:дістала} добрі шкури, і я знайду їм гарне застосування.", ["en"] = "Apprentice's Duties", ["tasks"] = { ["Giant Crocolisk Skin"] = "шкура гігантського кроколіска", ["Giant Crocolisk Skin (Provided)"] = "шкура гігантського кроколіска (видано)" } },
    [472] = { [1] = "Падіння Дун-Модру", [2] = "Дворфи Темного Заліза захопили Дун-Модр!\n\nМене важко поранили, {клас:к}. Більшість моїх товаришів загинули. Ми не встигли оговтатись від вибуху на віадуку Тандола, коли дворфи Темного Заліза атакували нас.\n\nНаш лідер, Довгокос, протрубив сигнал до відступу. Коли ми покидали місто, мені в спину прилетіла сокира і я знепритомнів.\n\nОговтавсь я вже тут, в гавані Менетілів. Я хвилююсь за побратимів, але надія ще є. Може, Довгокос ще живий! Сходи до Дун-Модру і спробуй знайти його, {раса:к}!", [3] = "Знайдіть Довгокоса біля Дун-Модру.", [5] = "Яке послання з Менетілу {стать:приніс славний:принесла славна} {клас}? Ага, тож ти {ім'я}.\n\nЦе гарна звістка, проблиск надії в ці темні часи. Се чудово, що юний Гарло вижив. Він отримав жахливу рану під час відступу і нам довелось відправити його до гавані на єдиному вцілілому скакуні.\n\nАле зараз ми у важкому положенні - Дун-Модр втрачено, а від нашого славного полку залишилась лиш тінь.", ["en"] = "Fall of Dun Modr" },
    [4722] = { [1] = "Викинута на берег морська черепаха", [2] = "Ви натрапили на труп морської черепахи, що деякий час тому викинулася на берег Темнобережжя. ЇЇ вже об'їли мурлоки, що оселилися навколо. Проте, схоже, що решток істоти достатньо, щоб зібрати вдосталь зразків для досліджень Ґвенніт Блі'Леґґонд в Аубердіні.", [3] = "Принесіть рештки морської черепахи Ґвенніт Блі'Леґґонд в Аубердін.", [4] = "Привіт, {ім'я}. Є щось нове про істот, що викинулися на берег?", [5] = "Ще одна знахідка для вивчення — молодець, {ім'я}! Ці рештки будуть вивчені належним чином, щойно потраплять до Дарнасу. Будь ласка, прийми цю невелику плату за рештки, надані для наших досліджень.", ["en"] = "Beached Sea Turtle", ["tasks"] = { ["Sea Turtle Remains"] = "рештки морської черепахи", ["Sea Turtle Remains (Provided)"] = "рештки морської черепахи (видано)" } },
    [4727] = { [1] = "Викинута на берег морська черепаха", [2] = "Скелет морської черепахи лежить на піщаній мілині на півночі Темнобережжя. Схоже, що сіромлисті мурлоки не знайшли цю тушу, або ж з невідомої причини остерігаються її. Хай там як, від черепахи залишилося достатньо, щоб узяти зразки для Ґвенніт Блі'Леґґонд в Аубердін для досліджень храму Місяця.", [3] = "Принесіть рештки морської черепахи Ґвенніт Блі'Леґґонд в Аубердін.", [4] = "І знову привіт, {ім'я}. Ти {стать:знайшов:знайшла} ще якихось істот на пляжі, про яких варто знати храму Місяця?", [5] = "Цікаво, що біля цієї істоти не було мурлоків. Ми матимемо це на увазі, коли будемо вивчати ці рештки. Дякуємо за твої зусилля, {ім'я}. Храм Місяця уповноважив мене передати тобі це як компенсацію за витрачений час.", ["en"] = "Beached Sea Turtle", ["tasks"] = { ["Sea Turtle Remains"] = "рештки морської черепахи", ["Sea Turtle Remains (Provided)"] = "рештки морської черепахи (видано)" } },
    [4728] = { [1] = "Викинута на берег морська істота", [2] = "На узбережжі лежить частково випотрошений труп гігантського морського ссавця. Біля цієї величезної викинутої на берег морської істоти лежить тачка та різні інструменти, ніби хтось раніше вже намагався її вивчити. Хоча мурлоки випотрошили цього звіра, його решток все ще достатньо, щоб зібрати зразок для Ґвенніт Блі'Леґґонд в Аубердіні.", [3] = "Принесіть кістки морської істоти Ґвенніт Блі'Леґґонд в Аубердін.", [4] = "І знову вітаю, {ім'я}! Що знову привело тебе до Аубердіну? Може, в тебе є нова знахідка?", [5] = "Гадаю, ти {стать:знайшов:знайшла} одну з істот, яку раніше вивчала Ліга дослідників. Вони працюють тут, на Темнобережжі, і вони згадували, що вивчали одну з викинутих на берег істот, доки їх не прогнали мурлоки. Схоже, що тобі вдалось впоратись з ними. Будь ласка, прийми цю скромну плату від імені храму Місяця.", ["en"] = "Beached Sea Creature", ["tasks"] = { ["Sea Creature Bones"] = "кістки морської істоти", ["Sea Creature Bones (Provided)"] = "кістки морської істоти (видано)" } },
    [473] = { [1] = "Доповідь капітану Міцноруку", [2] = "{ім'я}. Орки Драконової Пащі претендують не тільки на Альґаз. Капітан Міцнорук наказав направляти до нього всіх, хто бажає допомогти в боротьбі з ними. Він у фортеці, у військовій залі.", [3] = "Поговоріть з капітаном Міцноруком.", [5] = "{ім'я}. Вальстаґ доповів мені про твої успіхи з орками Драконової Пащі в Дун-Альґазі. Ти {стать:бравий:брава} {раса}.\n\nІ в мене є для тебе завдання.", ["en"] = "Report to Captain Stoutfist" },
    [4730] = { [1] = "Викинута на берег морська істота", [2] = "На узбережжі лежить напівз'їдений труп гігантського морського ссавця. Навколо загиблої істоти оселилася зграя мурлоків, сильніших, ніж ті, що були біля Аубердіну. Залишків істоти достатньо, щоб взяти зразок для Ґвенніт Блі'Леґґонд в Аубердін.", [3] = "Принесіть кістки морської істоти Ґвенніт Блі'Леґґонд в Аубердін.", [4] = "І знову привіт, {ім'я}! В тебе є чергова знахідка?", [5] = "Кістки, які ти {стать:приніс:принесла}, належать мирним морським ссавцям, що мешкають у водах біля коріння Тельдрассіля. Вони ніколи не викидалися на берег, на відміну від молотників. Цікаво, чому вони це роблять? Що ж, можливо, вивчення їхніх решток принесе свої плоди, і ми щось дізнаємося.\n\nЩе раз дякую тобі за допомогу. Будь ласка, прийми цю винагороду від храму Місяця.", ["en"] = "Beached Sea Creature", ["tasks"] = { ["Sea Creature Bones"] = "кістки морської істоти", ["Sea Creature Bones (Provided)"] = "кістки морської істоти (видано)" } },
    [4731] = { [1] = "Викинута на берег морська черепаха", [2] = "На узбережжі лежать чергові рештки викинутої на берег морської черепахи. На панцирі цієї черепахи ледь тримається покинутий візок. Можливо, це створіння привели до берега невідомі істоти та вона не сама викинулася на берег, на відміну від інших створінь. Тепер її рештки стали домівкою для могутніх сіромлистих мурлоків.\n\nУ візку ви знаходите коробку з дивними позначками. Можливо, Ґвенніт Блі'Леґґонд з Аубердіну зможе їх розтлумачити.", [3] = "Принесіть коробку з дивними відмітками до Ґвенніт Блі'Леґґонд в Аубердін.", [4] = "І знову привіт, {ім'я}. Твоя робота для храму Місяця просто неймовірна. Чи зможеш ти знову потішити нас новими знахідками?", [5] = "Я чула про візки, схожі на той, що ти {стать:знайшов:знайшла} на спині черепахи. Я думаю, що це візок наг, що використовується як у бою, так і для транспортування їхніх припасів на суші. Позначки на ящику також зроблені нагами. Можливо, істоту, яку ти {стать:знайшов:знайшла}, вбили на шляху на південь... можливо, до Ясенедолу?\n\nЯ відправлю цю скриньку до Дарнасу разом з іншими твоїми знахідками. А це — тобі. Ще раз дякую за допомогу.", ["en"] = "Beached Sea Turtle", ["tasks"] = { ["Strangely Marked Box"] = "коробка з дивним маркуванням", ["Strangely Marked Box (Provided)"] = "коробка з дивним маркуванням (видано)" } },
    [4732] = { [1] = "Викинута на берег морська черепаха", [2] = "Ви натрапили на труп морської черепахи, що деякий час тому викинулася на берег Темнобережжя. ЇЇ вже об'їли сіромлисті мурлоки, що оселилися навколо решток. Проте, схоже, що решток істоти достатньо, щоб зібрати вдосталь зразків для досліджень Ґвенніт Блі'Леґґонд в Аубердіні.", [3] = "Принесіть рештки морської черепахи Ґвенніт Блі'Леґґонд в Аубердін.", [4] = "І знову вітаю, {ім'я}. В тебе є нові знахідки для храму Місяця?", [5] = "Ти {стать:знайшов:знайшла} ще одну викинуту на берег істоту, {ім'я}? Морські черепахи зазвичай проживали у водах біля підніжжя Нордрассіля до його загибелі. Однак з появою Тельдрассіля цих створінь стає дедалі менше. Деякі з них, як ми вже знаємо, закінчують своє життя тут з невідомої причини.\n\nМожливо, твоя допомога допоможе нам розгадати цю таємницю. Будь ласка, прийми цю оплату за рештки, надані для наших досліджень.", ["en"] = "Beached Sea Turtle", ["tasks"] = { ["Sea Turtle Remains"] = "рештки морської черепахи", ["Sea Turtle Remains (Provided)"] = "рештки морської черепахи (видано)" } },
    [4733] = { [1] = "Викинута на берег морська істота", [2] = "Рештки істоти, схожої на гігантського молотника, лежать на мілині Сутінкового узбережжя. Цей молотник в кілька разів більший за тих, що мешкають у тутешніх водах. Звідки б ця істота не припливла, навряд чи вона родом з Темнобережжя.\n\nХоча туша істоти подекуди розібрана, її решток достатньо, щоб зібрати зразок для Ґвенніт Блі'Леґґонд з Аубердіну.", [3] = "Принесіть кістки морської істоти Ґвенніт Блі'Леґґонд в Аубердін.", [4] = "Дякувати Елуні — я рада знову бачити тебе, {ім'я}. Храм Місяця продовжує дослідження викинутих на берег істот. Можливо, ти можеш запропонувати ще щось цікаве для нас?", [5] = "Розміри молотника, про якого ти кажеш, просто вражають. Навіть найстаріші молотники в цих водах в кілька разів менші. Деякі великі молотники живуть поблизу Тельдрассіля, та їхня чисельність неухильно зменшується. Цікаво, чи не пов'язано це з істотами, що викидаються на берег Темнобережжя.\n\nМи продовжимо дослідження цих кісток. Будь ласка, прийми цю винагороду від імені храму Місяця. Дякую, {ім'я}.", ["en"] = "Beached Sea Creature", ["tasks"] = { ["Sea Creature Bones"] = "кістки морської істоти", ["Sea Creature Bones (Provided)"] = "кістки морської істоти (видано)" } },
    [474] = { [1] = "Вбити Нек'роша", [2] = "Тепер, коли катапульти спалено, настав час знайти й вбити ватага Нек'роша.", [3] = "Вбийте ватага Нек'роша.\n\nПринесіть голову Нек'роша капітану Міцноруку.", [4] = "Ти {стать:вбив:вбила} Нек'роша?", [5] = "Чудово спрацьовано, {ім'я}. Ти {стать:завдав:завдала} нищівного удару оркам клану Драконової Пащі. Вони ще не скоро оговтаються. До того ж зі знищенням цих катапульт, гавань Менетілів в безпеці.\n\nТи {стать:гідний:гідна} {раса} і Залізогарт щедро винагороджує таких за добру службу.", ["en"] = "Defeat Nek'rosh", ["tasks"] = { ["Nek'rosh's Head"] = "голова Нек'роша", ["Nek'rosh's Head (Provided)"] = "голова Нек'роша (видано)" } },
    [4740] = { [1] = "РОЗШУКУЄТЬСЯ: Глибоморок!", [2] = "Увага!\n\nПропонується винагорода за знищення мурлока на ім'я \"Глибоморок\". Відомо, що цей мерзенний звір винен у загибелі щонайменше однієї стражниці, а також підозрюється у потопленні щонайменше двох вантажних суден у водах Темнобережжя!\n\nВостаннє Глибоморока бачили в поселенні мурлоків на південь від Аубердіну, і вважається, що він охороняє тамтешні хатини. Винагороду за голову Глибоморока можна отримати у стражниці Ґлінди Нал'Шеї в Аубердіні.\n\nРада Аубердіну", [3] = "Знайдіть і вбийте мурлока, відомого як Глибоморок. Вважається, що ця істота захищає хатини мурлоків на південь від Аубердіну вздовж берегу.\n\nПро смерть Глибоморока повідомте стражниці Ґлінді Нал'Шеї в Аубердіні.", [4] = "Вітаю, {клас:к} — чим можуть допомогти тобі стражі? Можливо, ти {стать:прийшов:прийшла} по винагороду за Глибоморока?", [5] = "Що ж, схоже, що ти тут не просто ґав ловиш! Містяни будуть раді дізнатися, що сьогодні вони зможуть спати трохи спокійніше.\n\nСьогодні ти гідно {стать:послужив:послужила} в ролі знаряддя правосуддя для жителів Аубердіна, {ім'я}. За це я хочу запропонувати це як гідну винагороду... для {стать:справжнього героя:справжньої героїні} Аубердіна.", ["en"] = "WANTED: Murkdeep!", ["tasks"] = { ["Murkdeep"] = "Глибоморок", ["Murkdeep slain"] = "Глибоморок: убито" } },
    [475] = { [1] = "Вітер сум'яття", [2] = "Вітер сум'яття віє над лісом.\n\nҐеролас Талветрен служить Великим Вартовим сплячих Друїдів Кігтя в обителі кургану Бен'етіль. Його основний обов'язок як обраного захисника Сплячих — гарантувати їхню безпеку, щоб домовленість друїдів з Ізерою залишалася в силі.\n\nТа останнім часом вісті від Ґероласа чомусь затримуються, і я починаю хвилюватися. Вирушай на схід, у селище Зоряний Бриз, та принеси мені звіт Ґероласа. Тоді я зможу впевнитися, що мої брати та сестри сплять у безпеці.", [3] = "Відшукайте Ґероласа Талветрена в селищі Зоряний Бриз.", [5] = "Хвала лісовим духам, ти {стать:прийшов:прийшла}! Я знав, що Атрідас занепокоїться та надішле допомогу.", ["en"] = "A Troubling Breeze" },
    [476] = { [1] = "Порча Кривої Сосни", [2] = "Плем'я Кривої Сосни уражене порчею!\n\nКолись мирні хутропузи зараз проявляють агресію проти захисників лісу. Вони підстерегли мене в засаді, коли я виходив з обителі кургану Бен'етіль, а потім розграбували селище Зоряний Бриз. Їхній ватажок, Урсал Молотобій, затьмарює розум створінь за допомогою моху Скверни.\n\nУ мене багато ран, і я не можу передати Атрідасу ці страшні вісті. Це маєш зробити ти, {стать:юний:юна} {клас:к}. Мені залишається сподіватися, що оскаженілі хутропузи Кривої Сосни поки не дійшли до Бен'етіль!", [3] = "Поверніться до Атрідаса Ведмежокрива в Доланаар.", [5] = "Клянуся сузір'ями! Це воістину тривожні вісті!", ["en"] = "Gnarlpine Corruption" },
    [4766] = { [1] = "Маяра Яскравокрила", [2] = "Мій агент — Маяра Яскравокрила, вирушила в Палаючий степ, щоб дослідити руїни міста Тауріссан. В зруйнованому місті дворфів Темного Заліза може знаходитися безліч цінних предметів, які б чудово вписалися в наш родинний музей.\n\nМаяра каже, що знайшла дещо і їй потрібна допомога, щоб дістати це, щоправда, вона знайшла це не в Тауріссані. Замість цього потрібно відправитись в Чорноскельний шпиль.\n\nЯ не знаю подробиць, але якщо тобі цікаво — поговори з Маярою в Палаючому степі.", [3] = "Поговоріть з Маярою Яскравокрилою в Палаючому степі.", [5] = "Ти {стать:прийшов:прийшла} зі Штормовію? Чудово, мені відомо про один предмет мистецтва, який Ремінгтон хотів би поставити у своєму музеї. Я тобі більше скажу, він убив би за нього, але дістати цей предмет буде нелегко.\n\nОсь тут і знадобишся ти.", ["en"] = "Mayara Brightwing" },
    [4822] = { [1] = "Морозиво...", [2] = "МОРОЗИВО! О, будь ласка, будь ласка, можеш купити мені морозиво?! Якщо і є у світі щось краще за полуничне морозиво Тіґуля, то я такого не знаю! Це моє улюблене морозиво на цілому світі!\n\nЯ колись дуже давно спробував його на трасі Мерехтливих рівнин, але я чув, що його можуть продавати у місті! Будь ласка! Будь ласочка!", [3] = "Купіть полуничне морозиво для свого підопічного. Хлопець, схоже, віддає перевагу морозиву Тіґуля.", [4] = "Хотілося б, щоб вони робили більше смаків морозива, окрім полуничного, але, мабуть, мені пощастило, що полуничне — моє улюблене!", [5] = "Ммммммммм! Я обожнюю це полуничне морозиво! Якщо Тіґуль щось і вміє, так це робити морозиво!\n\nДуже дякую, {ім'я}, — це найкращий смаколик у світі!", ["en"] = "You Scream, I Scream...", ["tasks"] = { ["Tigule and Foror's Strawberry Ice Cream"] = "Полуничне морозиво від Тігуле та Форора", ["Tigule and Foror's Strawberry Ice Cream (Provided)"] = "Полуничне морозиво від Тігуле та Форора (видано)", ["Tigule and Foror's Strawberry Ice Cream slain"] = "Полуничне морозиво від Тігуле та Форора: убито" } },
    [483] = { [1] = "Реліквії Пробудження", [2] = "Ми бачили, як загарбники з Кривої Сосни спустошують обитель кургану Бен'етіль на захід звідси.\n\nСплячі друїди навічно застрягнуть у Смарагдовому Сні, не знаючи про свою долю, якщо ми їм не допоможемо. Тонкий ритуал сплячки неможливо порушити без Реліквій Пробудження.\n\nСпускайся в обитель та забери талісман Воронячого Пазура, чорне перо, сапфір небес і руну Гніздування. Друїди зберігають їх у священних скринях. Поверни їх мені, і я підготую ритуал пробудження.", [3] = "Дістаньте Реліквії Пробудження та принесіть їх Атрідасу Ведмежокривові в Доланаар.", [4] = "{Ім'я}, друїди Кігтя назавжди потраплять у пастку в Смарагдовому Сні, якщо ми не знайдемо Реліквії Пробудження в обителі Бен'етіль на заході.\n\nКожна мить нашої бездіяльності може приректи їх на вічні страждання.", [5] = "Тобі вдалося, {стать:юний:юна} {клас:к}! Чудово і, мушу зазначити, дуже вчасно.", ["en"] = "The Relics of Wakening", ["tasks"] = { ["Black Feather Quill"] = "чорне перо", ["Black Feather Quill (Provided)"] = "чорне перо (видано)", ["Raven Claw Talisman"] = "талісман Воронячого Пазура", ["Raven Claw Talisman (Provided)"] = "талісман Воронячого Пазура (видано)", ["Rune of Nesting"] = "руна Гніздування", ["Rune of Nesting (Provided)"] = "руна Гніздування (видано)", ["Sapphire of Sky"] = "сапфір небес", ["Sapphire of Sky (Provided)"] = "сапфір небес (видано)" } },
    [484] = { [1] = "Шкури молодих кроколісків", [2] = "Я Джеймс Галлоран, кожум'яка. Мої шкури кроколісків розходяться по всьому світу.\n\nВже {стать:зустрічав:зустрічала} Ейнара? Він - один з мисливців, які постачають мені шкури.\n\nВ мене вже закінчуються м'які шкури, а їх можна зняти лише з молодих кроколісків.\n\nВраховуючи обставини, ти отримаєш подвійну плату за стіс шкур. Ти знайдеш молодих кроколісків на болотах прямо за містом.", [3] = "Принесіть 6 шкур молодих кроколісків Джеймсу Галлорану в гавань Менетілів.", [4] = "{ім'я}, правильно? Ти {стать:приніс:принесла} шкури?", [5] = "Чудова робота, {ім'я}. Якість цих шкур неперевершена. Я займусь ними якнайшвидше. О, зажди, в мене є ще завдання для тебе.", ["en"] = "Young Crocolisk Skins", ["tasks"] = { ["Young Crocolisk Skin"] = "шкура молодого кроколіска", ["Young Crocolisk Skin (Provided)"] = "шкура молодого кроколіска (видано)" } },
    [486] = { [1] = "Урсал Молотобій", [2] = "Настав час врятувати Друїдів Кігтя. Якщо зараз ми зазнаємо невдачі, {Ім'я}, їхній сон стане вічним.\n\nЯ підготую Реліквії Пробудження та проведу обряд. Але щоб у мене все вийшло, клята тварюка, винна в цих поневіряннях, має бути знищена. Тільки тоді ми зможемо провести ритуал.\n\nУрсал Молотобій став у наших побратимів на заваді, і саме він повинен заплатити за свої злодіяння, щоб їх звільнити. Вирушай до поселення Кривої Сосни на південному заході й убий його.", [3] = "Убийте Урсала Молотобоя та повертайтеся до Атрідаса Ведмежокрива в Доланаар.", [4] = "Ми не зможемо розбудити наших братів, поки не вб'ємо Урсала Молотобоя, {Ім'я}.", [5] = "{Ім'я}, ти {стать:проявив:проявила} себе як дуже {стать:достойний:достойна} та {стать:спроможний:спроможна} {клас:н}. {Раса:н}, {стать:який:яка} так впевнено слідує дорогою честі, безумовно, отримає велику славу в цьому світі.\n\nХай лісові духи захищають тебе, куди б ти не {стать:пішов:пішла}.", ["en"] = "Ursal the Mauler", ["tasks"] = { ["Ursal the Mauler"] = "Урсал Молотобій", ["Ursal the Mauler slain"] = "Урсал Молотобій: убито" } },
    [4861] = { [1] = "Розлючені дикі совухи", [2] = "Вітаннячка, {стать:хлопче:дівчино}! Мене переслідував з мого табору на півдні Зимоключа якийсь кровожерливий дикий совух! Гадаю, я підійшов надто близько до того, що він охороняв.\n\nМені ледве вдалося втекти, але боюся, що моєму приятелеві пощастило менше. Чи не {стать:міг:могла} би ти кинути виклик диким совухам і піти до мого табору? Мені дуже потрібні мої припаси, і я також хотів би повернути амулет, який я знайшов вчора на місці розкопок.", [3] = "Знайдіть зруйнований табір і припаси Жарона Каменотеса на півдні Зимоключа.", [5] = "Серед решти знищених речей серед табору виділяється пошкоджений ящик...", ["en"] = "Enraged Wildkin" },
    [487] = { [1] = "Дорога в Дарнас", [2] = "Дорогу в Дарнас потрібно охороняти. Мандрівники, що прямують з Доланаара у столицю, розповідають про варварські напади заражених хутропузів з племені Кривої Сосни.\n\nКожен день у та з Дарнасу прямують вантажі та важливі повідомлення. Ми не можемо допустити, щоб зграя цих тварюк загрожувала подорожнім.\n\nВізьми зброю в ім'я священного лісу, {клас:к}. Їхнє лігво розташоване десь під цим пунктом спостереження. Убий 6 душителів з племені Кривої Сосни і відзвітуй мені.", [3] = "Убийте 6 душителів Кривої Сосни та поверніться до вартової Амари Ночеходець неподалік Доланаара.", [4] = "Дорога все ще небезпечна, {клас:к}. Убий 6 душителів з племені Кривої Сосни та повертайся до мене.", [5] = "Ти добре {стать:послужив:послужила} чесним ельфам Доланаара та Дарнасу, {стать:хоробрий:хоробра} {клас:к}. Як представниця вартових Тельдрассіля, я дякую тобі за твої зусилля.", ["en"] = "The Road to Darnassus", ["tasks"] = { ["Gnarlpine Ambusher"] = "душитель Кривої Сосни", ["Gnarlpine Ambusher slain"] = "душитель Кривої Сосни: убито" } },
    [488] = { [1] = "Торги Зенна", [2] = "Хочеш попрацювати, я дивлюсь? Тобі пощастило, не проходить і дня без того, щоб я не поторгувався із щонайменше {стать:одним:одною} {клас:о}.\n\nРозумієш, {Ім'я}, я можу зробити тебе дуже {стать:щасливим:щасливою} і дати тобі речі, про які ти навіть і не {стать:мріяв:мріяла}. Але спершу ти мусиш принести мені деякі предмети.\n\nМоя діяльність у цьому лісі часто потребує певних... реагентів. Принеси мені 3 ікла ночезубів, 3 пір'їни сов, що літають довкола, та 3 зразки павутиннолісого шовку.\n\nАле давай залишимо цю розмову між нами, {раса:к}.", [3] = "Принесіть Зенну Брудній Ратиці за межами Доланаару 3 ікла ночезуба, 3 пір'їни сови та 3 зразки павутиннолісого шовку.", [4] = "Працюєш, як маленька бджілка, {Ім'я}? Я чекав, коли ти принесеш мені те, що я просив.", [5] = "Ха-ха! Чудова робота.\n\nХто б міг подумати, що я, Зенн Брудна Ратиця, схилив {раса:з} до торгів? Точно не я! Але так і живемо... наш улюблений світ сповнений сюрпризів.\n\nТри \"Ура\" за наївних і легковажних!", ["en"] = "Zenn's Bidding", ["tasks"] = { ["Nightsaber Fang"] = "ікло ночезуба", ["Nightsaber Fang (Provided)"] = "ікло ночезуба (видано)", ["Strigid Owl Feather"] = "пір'їна сови", ["Strigid Owl Feather (Provided)"] = "пір'їна сови (видано)", ["Webwood Spider Silk"] = "павутиннолісий шовк", ["Webwood Spider Silk (Provided)"] = "павутиннолісий шовк (видано)" } },
    [489] = { [1] = "У пошуках спокути!", [2] = "До Ради Лісу дійшли новини, що ти {стать:допоміг:допомогла} Зенну Брудній Ратиці. Сатир - ворог лісу. Ти, {раса:к}, {стать:мав би бути вищим:мала б бути вищою} за осквернення наших земель вбивством дітей природи.\n\nЯкщо хочеш залишитися {стать:другом:подругою} Тельдрассіля, то мусиш почати спокутувати свої діяння в очах Ради.\n\nДля початку провчи Зенна. В лісі ти знайдеш осквернені шишки, зіпсоване опале насіння. З них йде зеленуватий дим.\n\nПринеси ці шишки Брудній Ратиці. Хай подумає, що ти {стать:приніс:принесла} йому смачненький перекус.", [3] = "Зберіть 3 осквернені шишки та віддайте їх Зеннові Брудній Ратиці за межами Доланару.", [4] = "Що ти {стать:приніс:принесла} мені, {Ім'я}? На вигляд чудова закуска.", [5] = "Ти просто чудо, {раса:к}! Я був певен, що ти станеш мені у нагоді!", ["en"] = "Seek Redemption!", ["tasks"] = { ["Fel Cone"] = "осквернена шишка", ["Fel Cone (Provided)"] = "осквернена шишка (видано)" } },
    [4906] = { [1] = "Подальше осквернення", [2] = "Друга група сатирів, яку очолює жорстокий Заварік, загрожує землям Скверноліссю на півночі. Ці підступні зрадники живляться скверною істот Сквернолісся.\n\nЗаватрас та його підручні були лише частиною великого плану — створити заражений місячний колодязь, яким мав скористатися Заварік.\n\nТепер, коли Заватрас вибув з гри, заверши справу, {ім'я}. Вирушай на північ та здолай Заваріка.", [3] = "Ерідана Блакитновій зі Сквернолісся хоче, щоб ви вбили 8 нефритожарих пеклокликів, 8 нефритожарих зрадників, 8 нефритожарих ошустів і Заваріка. Поверніться до Ерідани, коли виконаєте завдання.", [4] = "Будь ласка, поклади край стражданням створінь Сквернолісся.", [5] = "Дякую за все, що ти {стать:зробив:зробила}, {ім'я}. Нехай Елуна захищає тебе і веде на подальшому шляху.", ["en"] = "Further Corruption", ["tasks"] = { ["Jadefire Betrayer"] = "нефритожарий зрадник", ["Jadefire Betrayer slain"] = "нефритожарий зрадник: убито", ["Jadefire Hellcaller"] = "нефритожарий пеклоклик", ["Jadefire Hellcaller slain"] = "нефритожарий пеклоклик: убито", ["Jadefire Trickster"] = "нефритожарий ошуст", ["Jadefire Trickster slain"] = "нефритожарий ошуст: убито", ["Xavaric"] = "Заварік", ["Xavaric slain"] = "Заварік: убито" } },
    [4970] = { [1] = "Нагодувати кригозубів", [2] = "Якщо хочеш проявити себе, можеш почати з простого, але дуже важливого завдання.\n\nЗбери м'ясо химер та ведмедів у цій місцевості. Принеси його мені, щоб я зміг нагодувати ним кригозубів, яких треную.", [3] = "Зберіть 5 шматків м'яса щербозубів та 5 шматків м'яса студовіїв Риверну Криговію з Зимоключ.", [4] = "Дисциплінованість і цілеспрямованість — ось твої цілі. Я можу доручати тобі найпростіше завдання не один раз, і ти маєш щоразу робити все якнайкраще.", [5] = "Дякую за допомогу, {ім'я}. Моя думка про тебе згодом стає все кращою.", ["en"] = "Frostsaber Provisions", ["tasks"] = { ["Chillwind Meat"] = "м'ясо студовія", ["Chillwind Meat (Provided)"] = "м'ясо студовія (видано)", ["Shardtooth Meat"] = "м'ясо щербозуба", ["Shardtooth Meat (Provided)"] = "м'ясо щербозуба (видано)" } },
    [4986] = { [1] = "Покрита письменами дубова гілка", [2] = "Мертва рука друїда стискає, на диво, наповнену життям дубову гілку. Оглянувши її, ви бачите вирізані знаки, притаманні природі друїдів.\n\nКоли ви берете гілку до рук, ви помічаєте, що вона напрочуд тепла на дотик, тепліша, ніж має бути. Зображення дерева Тельдрассіля виникає у вашій свідомості, а саме Дарнас. А слова \"Кенарійське Коло\" крутяться на кінчику вашого язика. Схоже, що у гілку були вкладені знання про те, куди саме треба її принести.", [3] = "Судячи з магії, вкладеної в покриту письменами дубову гілку, друїд-таурен хотів доставити її до Кенарійського Кола в Дарнасі. Знайдіть одного з тамтешніх друїдів.", [4] = "Від імені Кенарійського Кола, я вітаю тебе в цьому анклаві, {клас:к}. Що привело тебе до нас?", [5] = "Це... це досить дивно. Цей друїд — більш того, друїд-таурен — довірив тобі цінну інформацію про чуму Скари. Я здивований, що таурен довірив {раса:д} таку важливу інформацію. Сподіваюся, ти кажеш правду. Ми скористаємося цими знаннями, я обіцяю тобі. Можливо, таурени не так далеко пішли від Кенарія, як вважає Фендрал...\n\nЕм, хай там як, будь ласка — прийми це на знак вдячності від Кенарійського Кола.", ["en"] = "Glyphed Oaken Branch", ["tasks"] = { ["Glyphed Oaken Branch"] = "покрита письменами дубова гілка", ["Glyphed Oaken Branch (Provided)"] = "покрита письменами дубова гілка (видано)" } },
    [5] = { [1] = "Бурчання Тремтінієвого живота", [2] = "Я вже декілька тижнів ховаюсь в цьому містечку-привиді, і їм лише комах та бур'яни! Мені потрібна нормальна їжа, і я готовий добре заплатити за неї.\n\nВлаштуй для мене бенкет і не пошкодуєш.\n\nЯ чув, що шеф-кухар Ґруал з таверни Багряний Ворон у Темноділі готує дуже смачні крабові пиріжки...", [3] = "Поговоріть з шеф-кухарем Ґруалем.", [5] = "Хочеш крабових пиріжків? Ну, я можу приготувати їх для тебе...", ["en"] = "Jitters' Growling Gut" },
    [505] = { [1] = "Душогуби Синдикату", [2] = "Я — новий війт Південнобережжя, призначений недавно після вбивства попереднього. Вбивць так і не знайшли, але завдяки нашим розслідуванням ми майже впевнені, що їх найняв Синдикат — група злодіїв, яку очолюють лиходійні шляхтичі тепер полеглого знищеного королівства Альтерак.\n\nСиндикат має табір на півночі від Тарренського Млину, зайнятого Ордою, і наші останні зачіпки ведуть туди. Убий членів Синдикату, яких знайдеш там.", [3] = "Убийте 12 харцизів Синдикату та 8 злодіїв Синдикату, після чого повертайтеся до війта Генрі Малеба у Південнобережжя.", [4] = "Сподіваюся, ти вже {стать:знищив:знищила} цих покидьків з Синдикату?", [5] = "Дякую тобі, {Ім'я}. Хоча вони ще можуть нишпорити неподалік, ми сподіваємося, що деякі з убитих тобою злодіїв відповідальні за смерть попереднього війта. Але навіть якщо це не так, Синдикат — ганьба цієї землі та всієї людської раси.\n\nЇхні смерті — добра звістка для Південнобережжя.", ["en"] = "Syndicate Assassins", ["tasks"] = { ["Syndicate Footpad"] = "харциз Синдикату", ["Syndicate Footpad slain"] = "харциз Синдикату: убито", ["Syndicate Thief"] = "злодій Синдикату", ["Syndicate Thief slain"] = "злодій Синдикату: убито" } },
    [5061] = { [1] = "Водна форма", [2] = "Ти {стать:завершив:завершила} навчання, яке проходять всі друїди-початківці перед тим, як зможуть опанувати водну форму. Тепер повертайся до свого наставника, Матренґіла Ведмелика в Дарнас. Покажи йому цю підвіску і доведи, що ти {стать:готовий:готова} засвоїти його уроки. Він завершить твоє навчання, завдяки цьому ти станеш одним цілим з водою.\n\nПрощавай, {стать:юний:юна} {клас:к}. Ми ще зустрінемось.", [3] = "Поверніться в Дарнас і покажіть Матренґілу Ведмелику підвіску Морського Лева.", [4] = "До мене дійшов слух про твоє провісне повернення до Дарнасу, однак я хочу побачити докази того, що ти {стать:засвоїв:засвоїла} уроки Місячної галявини, перш ніж почну вчити тебе приймати водну форму.\n\nЧи є у тебе підвіска морського лева?", [5] = "Чудово, {ім'я:к}. Ти {стать:готовий:готова} прийняти водну форму і я з радістю тебе цьому навчу.\n\nТакож, прийми цю річ в знак визнання твоїх успіхів у двох випробуваннях. Сподіваюсь, це буде приємним доповненням до твого спорядження у якості {стать:захисника природи та хранителя:захисниці природи та хранительки} рівноваги.", ["en"] = "Aquatic Form", ["tasks"] = { ["Pendant of the Sea Lion"] = "підвіска Морського Лева", ["Pendant of the Sea Lion (Provided)"] = "підвіска Морського Лева (видано)" } },
    [5066] = { [1] = "Заклик до зброї: Зачумлені землі!", [2] = "Увага, увага! Всіх героїв просимо прислухатися до цих слів!\n\nКоролівство Штормовій закликає до зброї! Всім, хто здатен тримати зброю, пропонується приєднатися до боротьби проти жахливої загрози Скари в північних землях Східних Королівств! Поширюються чутки про нові загрози, що з'являються з руїн Зачумлених земель!\n\nГерої королівства — знайдіть командувача Ашлама Мужнобоя, який розташувався у таборі Студовій, на північ від Альтеракських гір!", [3] = "Знайдіть командира Ашлама Мужньобоя. Він знаходиться в таборі Студовій, що на північ від Альтерацьких гір.", [5] = "Вітаю в Зачумлених землях, {стать:герою:героїне}. Це один із найнебезпечніших рубежів Азероту, особливо враховуючи загрозу Скари, що нависла на півночі та північному сході. Я радий чути, що заклик до обов'язку та служіння загальному благу не залишився непоміченим для тебе!\n\nЯкщо ти {стать:готовий:готова} забруднити руки, то тут, на краю Зачумлених земель, є чим зайнятися охочим і вмілим героям.", ["en"] = "A Call to Arms: The Plaguelands!" },
    [5090] = { [1] = "Заклик до зброї: Зачумлені землі!", [2] = "Увага, увага! Всіх героїв просимо прислухатися до цих слів!\n\nКоролівство Штормовій закликає до зброї! Всім, хто здатен тримати зброю, пропонується приєднатися до боротьби проти жахливої загрози Скари в північних землях Східних Королівств! Поширюються чутки про нові загрози, що з'являються з руїн Зачумлених земель!\n\nГерої королівства — знайдіть командувача Ашлама Мужнобоя, який розташувався у таборі Студовій, на північ від Альтеракських гір!", [3] = "Знайдіть командира Ашлама Мужньобоя. Він знаходиться в таборі Студовій, що на північ від Альтерацьких гір.", [5] = "Вітаю в Зачумлених землях, {стать:герою:героїне}. Це один із найнебезпечніших рубежів Азероту, особливо враховуючи загрозу Скари, що нависла на півночі та північному сході. Я радий чути, що заклик до обов'язку та служіння загальному благу не залишився непоміченим для тебе!\n\nЯкщо ти {стать:готовий:готова} забруднити руки, то тут, на краю Зачумлених земель, є чим зайнятися охочим і вмілим героям.", ["en"] = "A Call to Arms: The Plaguelands!" },
    [5091] = { [1] = "Заклик до зброї: Зачумлені землі!", [2] = "Увага, увага! Всіх героїв просимо прислухатися до цих слів!\n\nКоролівство Штормовій закликає до зброї! Всім, хто здатен тримати зброю, пропонується приєднатися до боротьби проти жахливої загрози Скари в північних землях Східних Королівств! Поширюються чутки про нові загрози, що з'являються з руїн Зачумлених земель!\n\nГерої королівства — знайдіть командувача Ашлама Мужнобоя, який розташувався у таборі Студовій, на північ від Альтеракських гір!", [3] = "Знайдіть командира Ашлама Мужньобоя. Він знаходиться в таборі Студовій, що на північ від Альтерацьких гір.", [5] = "Вітаю в Зачумлених землях, {стать:герою:героїне}. Це один із найнебезпечніших рубежів Азероту, особливо враховуючи загрозу Скари, що нависла на півночі та північному сході. Я радий чути, що заклик до обов'язку та служіння загальному благу не залишився непоміченим для тебе!\n\nЯкщо ти {стать:готовий:готова} забруднити руки, то тут, на краю Зачумлених земель, є чим зайнятися охочим і вмілим героям.", ["en"] = "A Call to Arms: The Plaguelands!" },
    [5092] = { [1] = "Очистити шлях", [2] = "Оскільки західні та північні дороги, що ведуть до Андоралу, гарно укріплені, я планую завдати удару з менш захищеного боку — зі сходу. Скара покладається на невмерлих, що заполонили пагорб Скорботи. Якщо ми хочемо увійти до Андоралу, нам потрібно пройти крізь пагорб Скорботи.\n\nТвоїм першим завданням буде зачистка шляху через пагорб Скорботи. Вбий скелетів та гулів, що вештаються там, та повертайся до мене.", [3] = "Вбийте 10 скелетів-випотрошувачів та 10 гулів-рабів на пагорбі Скорботи.\n\nПоверніться до командира Ашлама Мужньобою в таборі Студовій, Західні Зачумлені землі.", [4] = "Я хочу підготувати тебе до найгіршого, {ім'я}. Завдання, що стоїть перед нами, буде нелегким. Оскільки ми зрештою збираємось завдати удару по Скарі, ти будеш частиною наших передових сил! Твоє завдання на пагорбі Скорботи прокладе нам шлях до перемоги!", [5] = "Завдання виконане, {ім'я}! Чудова робота.\n\nДозволь мені нагородити тебе за твої зусилля монетою зі скарбниці Штормовію. Раджу витратити ці гроші на підготовку до наступного завдання... Адже воно приведе тебе до самих руїн Андорала.\n\nГотуйся і будь насторожі!", ["en"] = "Clear the Way", ["tasks"] = { ["Skeletal Flayer"] = "скелетний потрошитель", ["Skeletal Flayer slain"] = "скелетний потрошитель: убито", ["Slavering Ghoul"] = "слинявий гуль", ["Slavering Ghoul slain"] = "слинявий гуль: убито" } },
    [5097] = { [1] = "Вздовж сторожових веж", [2] = "Завдяки магічному пристрою, відомому як сигнальний смолоскип, ми можемо помічати цілі для майбутніх дій наших солдатів. Ми думаємо, що Скара використовує вежі Андоралу для того, щоб контролювати рух своїх військ.\n\nТвоє завдання — увірватися в Андорал та встановити смолоскипи на всіх чотирьох вежах. Тобі доведеться стати у дверному отворі кожної вежі, щоб поставити смолоскипи, а він помітить вежу. В сигнальному смолоскипі лише п'ять зарядів, тому використовуй їх розумно!", [3] = "Використовуючи сигнальний смолоскип, помітьте кожну вежу в Андоралі. Вам знадобиться стати у дверному отворі, щоб успішно помітити вежу.\n\nЯк помітите всі вежі, поверніть сигнальний смолоскип командиру Ашламу Мужньобою в табір Студовій, в Західних Зачумлених землях.", [4] = "Коли вежі будуть помічені, вони стануть пріоритетними цілями для нашого нападу на Андорал. Я підозрюю, що як тільки ми нейтралізуємо вежі, з'явиться головна загроза Андорала. З цього моменту, ми почнемо пряму боротьбу за місто!\n\nТи {стать:повернувся:повернулася}, щоб повідомити про свій успіх, еге ж? Не забудь сигнальний смолоскип, ми маємо економити наші ресурси.", [5] = "Мої жерці звітують, що отримали сигнал з усіх чотирьох веж! Схоже, що ти знову відмінно {стать:виконав:виконала} моє завдання. Чудова робота, {ім'я}.\n\nВежі помічені, і наша підготовка до атаки завершена. Настав час битви зі Скарою!", ["en"] = "All Along the Watchtowers", ["tasks"] = { ["Tower Four marked"] = "Вежа чотири позначена", ["Tower Four marked (Provided)"] = "Вежа чотири позначена (видано)", ["Tower Four marked slain"] = "Вежа чотири позначена: убито", ["Tower One marked"] = "Вежа Один позначена", ["Tower One marked (Provided)"] = "Вежа Один позначена (видано)", ["Tower One marked slain"] = "Вежа Один позначена: убито", ["Tower Three marked"] = "Вежа Три позначена", ["Tower Three marked (Provided)"] = "Вежа Три позначена (видано)", ["Tower Three marked slain"] = "Вежа Три позначена: убито", ["Tower Two marked"] = "Вежа два позначена", ["Tower Two marked (Provided)"] = "Вежа два позначена (видано)", ["Tower Two marked slain"] = "Вежа два позначена: убито" } },
    [514] = { [1] = "Лист до Бурешпиля", [2] = "Я маю колегу в Залізогарті, який, ймовірно, зможе допомогти розшифрувати цей лист. Підіть до бібліотеки в залі Дослідників Залізогарту та поговоріть з розвідувачем Бурешпилем. Скажіть йому, що вас прислав я, та покажіть йому лист. Якщо хтось і зможе прочитати це північніше Чорноскельного шпиля, то це він.", [3] = "Принесіть кмітливо зашифрований лист розвідувачеві Бурешпилю в Залізогарт.", [4] = "Тебе прислав Діббс з Південнобережжя, чи не так? Як там поживає цей старий читун?", [5] = "О, шифр! Моя спеціальність. Дай-но подивитися...", ["en"] = "Letter to Stormpike", ["tasks"] = { ["Cleverly Encrypted Letter"] = "кмітливо зашифрований лист", ["Cleverly Encrypted Letter (Provided)"] = "кмітливо зашифрований лист (видано)" } },
    [52] = { [1] = "Захист кордону", [2] = "Гей, {ім'я:к}. Чим далі ми від Злотохрестя, тим агресивнішими стають дикі тварини, а лісозаготівельний табір Східнодолу зазнає майже постійних нападів вовків та ведмедів!\n\nМи могли б скористатися твоєю допомогою.", [3] = "Убийте 8 бродячих хижаків і 5 молодих лісових ведмедів, і повертайтеся потому до вартового Томаса на східний ельвиннський міст.", [4] = "Ти {стать:вбив:вбила} цих вовків і ведмедів?", [5] = "Красно дякую за допомогу, {ім'я:к}. Щось у лісі робить звірів настільки зухвалими.\n\nЩо б то не було, я сподіваюся, що воно там і залишиться.", ["en"] = "Protect the Frontier", ["tasks"] = { ["Prowler"] = "бродячий хижак", ["Prowler slain"] = "бродячий хижак: убито", ["Young Forest Bear"] = "молодий лісовий ведмідь", ["Young Forest Bear slain"] = "молодий лісовий ведмідь: убито" } },
    [5201] = { [1] = "Вторгнення Зимокрайових", [2] = "Мою присутність тут мало хто помічає, {ім'я}. Однак, існує одна неприємність, що з'явилась у Зимоключі — це хутропузи з племені Зимокрайових.\n\nХоча я ніколи не нападав на хутропузів, вони здаються схибленими та наляканими. Я бачив, як вони вбивають безліч створінь, які просто виявилися не в той час та не в тому місці.\n\nЯ втомився від їхнього втручання — будь ласка, допоможи мені. Вбий хутропузів і не підпускай їх до узгір'я Кригозубів.", [3] = "Риверн Криговій хоче, щоб ви вбили 5 зимокрайових шаманів і 5 зимокрайових урс.", [4] = "Схоже, що хутропузи несповна розуму...", [5] = "Мене неймовірно тішить, що хоча б на короткий час ми можемо забути про вторгнення Зимокрайових.\n\nТи починаєш демонструвати свою наполегливість, {ім'я}.", ["en"] = "Winterfall Intrusion", ["tasks"] = { ["Winterfall Shaman"] = "зимокрайовий шаман", ["Winterfall Shaman slain"] = "зимокрайовий шаман: убито", ["Winterfall Ursa"] = "зимокрайовий урса", ["Winterfall Ursa slain"] = "зимокрайовий урса: убито" } },
    [5215] = { [1] = "Котли Скари", [2] = "В межах колишнього Лордерона є вісім котлів — чотири з них знаходяться тут, на заході, і ще чотири — на сході. Ці котли випускають в повітря отруйні випари, розповсюджуючи чуму по всій землі.\n\nНекромантія Кел'Тузада надто сильна, щоб просто взяти та погасити вогонь під цими котлами, але, можливо, ми зможемо використати ці котли на нашу користь. Поговори з моєю помічницею, верховною жрицею Мак-Доннелл, вона допоможе тобі з цим завданням.", [3] = "Поговоріть з верховною жрицею Мак-Доннелл в проліску Студовій, що в Західних Зачумлених землях.", [5] = "Нехай сила Світла сяє над тобою в ці темні часи, {клас:к}. Я рада, що зможу допомогти тобі, щоб розібратися з котлами Скари.\n\nНаша ціль — це змінити складові отрути в котлах, щоб ця суміш стала смертельною для Скари. Для цього доведеться взяти зразки зі всіх чотирьох котлів в Західних Зачумлених землях.\n\nПриготуйся до славної битви проти Скари!", ["en"] = "The Scourge Cauldrons" },
    [5216] = { [1] = "Ціль: Сквернокам'яне поле", [2] = "З чотирьох котлів, що знаходяться на заході, найлегше буде отримати доступ до котла на Сквернокам'яному полі. Там розташовані менш досвідчені війська Скари, але не варто їх недооцінювати.\n\nВідправляйся до Сквернокам'яного поля, на північний захід від Андорала, та розберися з тамтешнім хранителем котла. У нього має бути ключ, який надасть доступ до котла. Коли отримаєш доступ до котла, збери зразки отрути в цю пляшку. Вони знадобляться нам, щоб створити протидіючі речовини.", [3] = "Відправляйтеся до Сквернокам'яного поля в Західних Зачумлених землях, вбийте хранителя котла та використайте його ключ, щоб отримати доступ до котла. Вам знадобиться порожня пляшка для зразків зі Сквернокам'яного поля, щоб взяти зразок отрути з котла.", [4] = "Панель доступу до котла надійно зачинена. Щоб відкрити її, вам потрібно знайти ключ.", [5] = "Ключ хранителя котла Жовчерота ідеально підходить до замка панелі. Зсередини долинає неприємний сморід — в котлі вариться суміш невідомих речовин.\n\nЗбоку є невеликий кран, під який ідеально поміщається пляшка. Тепер ви можете зібрати зразки для верховної жриці Мак-Доннелл з проліску Студовій.", ["en"] = "Target: Felstone Field", ["tasks"] = { ["Empty Felstone Field Bottle"] = "порожня пляшка для зразків зі Сквернокам'яного поля", ["Empty Felstone Field Bottle (Provided)"] = "порожня пляшка для зразків зі Сквернокам'яного поля (видано)", ["Felstone Field Cauldron Key"] = "ключ від котла Сквернокам'яного поля", ["Felstone Field Cauldron Key (Provided)"] = "ключ від котла Сквернокам'яного поля (видано)" } },
    [5217] = { [1] = "Повернення до табору Студовій", [2] = "Ви наповнюєте пляшку достатньою кількістю отруйної суміші з котла для подальшого дослідження.\n\nОтримавши отруту, настав час повертатися до верховної жриці Мак-Доннелл в табір Студовій.", [3] = "Принесіть пляшку зразків зі Сквернокам'яного поля верховній жриці Мак-Доннелл в табір Студовій, що в Західних Зачумлених землях.", [4] = "З поверненням до табору Студовій, {ім'я}. Як твої справи з котлами?", [5] = "Молодець, {ім'я}. Алхімік Арбінґтон миттю проведе дослідження та знайде протидіючу речовину, яку можна додати в котел. Якщо ми зможемо викачати достатньо цієї суміші в повітря, ми послабимо Скару в цьому місці.\n\nЦе буде непросте завдання — нам доведеться постійно влаштовувати набіги на котли та додавати в них наші реагенти. Та все ж якщо ми будемо продовжувати у тому ж дусі, у нас буде значна перевага проти Скари у вирішальній битві!", ["en"] = "Return to Chillwind Camp", ["tasks"] = { ["Filled Felstone Field Bottle"] = "пляшка зразків зі Сквернокам'яного поля", ["Filled Felstone Field Bottle (Provided)"] = "пляшка зразків зі Сквернокам'яного поля (видано)" } },
    [5219] = { [1] = "Ціль: Сльози Дальсона", [2] = "Один з котлів розташований на полі колишньої ферми, нині відомої як Сльози Дальсона. Але сьогодні не час лити сльози, оскільки ми знищимо Скару та змусимо її вдавитися власним варевом!\n\nВідправляйся до Сліз Дальсона, на північ від Андорала, та вбий хранителя котла. У нього має бути ключ, як і минулого разу, що надасть тобі доступ до котла. Скористайся цією пляшкою, щоб зібрати зразки — у кожному котлі варяться різні отрути.", [3] = "Відправляйтеся до Сліз Дальсона в Західних Зачумлених землях, вбийте хранителя котла та використайте його ключ, щоб отримати доступ до котла. Вам знадобиться порожня пляшка для зразків зі Сліз Дальсона поля, щоб взяти зразок отрути з котла.", [4] = "Панель доступу до котла надійно зачинена. Щоб відкрити її, вам потрібно знайти ключ.", [5] = "Моторошний ключ хранителя котла легко проковзує в замок та одразу зникає, надаючи вам постійний доступ до котла. Огидна, густа суміш тече переплетеними трубками в основі котла.\n\nЗбоку є невеликий кран, під який ідеально поміщається пляшка. Тепер ви можете зібрати зразки для верховної жриці Мак-Доннелл з проліску Студовій.", ["en"] = "Target: Dalson's Tears", ["tasks"] = { ["Dalson's Tears Cauldron Key"] = "ключ від котла Сліз Дальсона", ["Dalson's Tears Cauldron Key (Provided)"] = "ключ від котла Сліз Дальсона (видано)", ["Empty Dalson's Tears Bottle"] = "порожня пляшка для зразків зі Сліз Дальсона", ["Empty Dalson's Tears Bottle (Provided)"] = "порожня пляшка для зразків зі Сліз Дальсона (видано)" } },
    [522] = { [1] = "Контракт вбивці", [2] = "Це контракт на вбивство війта Генрі Малеба. Він запечатаний червоним воском з характерним відбитком печатки.", [3] = "Принесіть контракт вбивці війтові Малебу в Південнобережжя.", [4] = "Ти виглядаєш геть {стать:захеканим:захеканою}! Маєш, про що доповісти?", [5] = "<Малеб оглядає контракт.>\n\nЦе пояснює останню атаку на Південнобережжя. Очевидно, Синдикат полює на мене, точнісінько так само, як і на попереднього війта!", ["en"] = "Assassin's Contract", ["tasks"] = { ["Assassin's Contract"] = "контракт вбивці", ["Assassin's Contract (Provided)"] = "контракт вбивці (видано)" } },
    [5220] = { [1] = "Повернення до табору Студовій", [2] = "Ви наповнюєте пляшку достатньою кількістю густої суміші з котла для подальшого дослідження.\n\nОтримавши отруту, настав час повертатися до верховної жриці Мак-Доннелл в табір Студовій.", [3] = "Принесіть пляшку зразків зі Сліз Дальсона верховній жриці Мак-Доннелл в табір Студовій, що в Західних Зачумлених землях.", [4] = "Ми знаємо, що в кожному котлі варяться різні суміші, що поширюють чуму. Також нам відомо, що ми маємо розробити протиотрути для кожного котла. Цей зразок зі Сліз Дальсона допоможе нам визначити речовини, необхідні для тамтешнього котла.", [5] = "О, нам буде що досліджувати. Молодець, {ім'я}!\n\nНаразі, наступний крок в наших руках. Нам потрібно скласти список реагентів, які, разом з сумішшю в котлі, викличуть зворотний ефект.\n\nДля цього доведеться помістити їх прямо у котел. Алхімік Арбінґтон знає набагато більше про це, тож поговори з ним якомога швидше.", ["en"] = "Return to Chillwind Camp", ["tasks"] = { ["Filled Dalson's Tears Bottle"] = "пляшка зразків зі Сліз Дальсона", ["Filled Dalson's Tears Bottle (Provided)"] = "пляшка зразків зі Сліз Дальсона (видано)" } },
    [5222] = { [1] = "Ціль: Кручений Привид", [2] = "Тобі вдалося відкрити вже два котли й тепер ти маєш необмежений доступ до них, але залишається іще два. Якщо ми впораємося з ними, це дозволить нам успішно ввести протидійні речовини!\n\nЦього разу твоя ціль — котел Крученого Привида. Він знаходиться на схід від Андорала, неподалік від зруйнованих стін міста. Тобі знову доведеться вбити хранителя котла, щоб забрати в нього ключ. Наповни цю пляшку зразками з котла.\n\nВдалого полювання, {ім'я}!", [3] = "Відправляйтеся до Крученого Привида в Західних Зачумлених землях, вбийте хранителя котла та використайте його ключ, щоб отримати доступ до котла. Вам знадобиться порожня пляшка для зразків з Крученого Привида, щоб взяти зразок отрути з котла.", [4] = "Панель доступу до котла надійно зачинена. Щоб відкрити її, вам потрібно знайти ключ.", [5] = "Ключ хранителя котла відкриває доступ до панелі, а потім зникає, як і попередні ключі. Рідина всередині бурлить та смердить чимось гнилим.\n\nЗбоку є невеликий кран, під який ідеально поміщається пляшка. Тепер ви можете зібрати зразки для верховної жриці Мак-Доннелл з проліску Студовій.", ["en"] = "Target: Writhing Haunt", ["tasks"] = { ["Empty Writhing Haunt Bottle"] = "порожня пляшка для зразків з Крученого Привида", ["Empty Writhing Haunt Bottle (Provided)"] = "порожня пляшка для зразків з Крученого Привида (видано)", ["Writhing Haunt Cauldron Key"] = "ключ від котла Крученого Привида", ["Writhing Haunt Cauldron Key (Provided)"] = "ключ від котла Крученого Привида (видано)" } },
    [5223] = { [1] = "Повернення до табору Студовій", [2] = "Ви обережно наповнюєте порожню пляшку. Зразок мерзенної рідини, що бурлить у котлі, переливається всередині скляної посудини.\n\nОтримавши отруту, настав час повертатися до верховної жриці Мак-Доннелл в табір Студовій.", [3] = "Принесіть пляшку зразків з Крученого Привида верховній жриці Мак-Доннелл в табір Студовій, що в Західних Зачумлених землях.", [4] = "Коли ми успішно проаналізуємо зразок з котла Крученого Привида, у нас з'явиться третій спосіб завдати нищівної шкоди Скарі!", [5] = "Іще одне чудово виконане завдання, {ім'я}! Тепер ми зможемо скористатися цими котлами проти самої Скари. Якби влада Кел'Туазада не була такою сильною, я б сказала, що ми можемо повністю нейтралізувати їх!\n\nАлхімік Арбінґтон незабаром повідомить, що потрібно додати до цього та інших котлів, щоб впоратися з чумою. Отже, настав час отримати доступ до останнього із західних котлів!", ["en"] = "Return to Chillwind Camp", ["tasks"] = { ["Filled Writhing Haunt Bottle"] = "пляшка зразків з Крученого Привида", ["Filled Writhing Haunt Bottle (Provided)"] = "пляшка зразків з Крученого Привида (видано)" } },
    [5225] = { [1] = "Ціль: Посуха Ґаррона", [2] = "Останній котел розташований на фермі під назвою Посуха Ґаррона. Він охороняється кількома посіпаками Скари — якщо точніше, примарами та привидами. З ними не варто жартувати, {ім'я}.\n\nПосуха Ґаррона знаходиться на північний схід звідси, ближче до Східних Зачумлених земель. Знову ж таки, вбий хранителя котла, у нього є ключ. Ось твоя порожня пляшка для зразків. Принеси мені її наповненою. Нехай Світло оберігає тебе на цьому небезпечному завданні, {клас:к}.", [3] = "Відправляйтеся до Посухи Ґаррона в Західних Зачумлених землях, вбийте хранителя котла та використайте його ключ, щоб отримати доступ до котла. Вам знадобиться порожня пляшка для зразків з Посухи Ґаррона, щоб взяти зразок отрути з котла.", [4] = "Панель доступу до котла надійно зачинена. Щоб відкрити її, вам потрібно знайти ключ.", [5] = "Ключ від хранителя котла Душегніва зникає, щойно торкається панелі котла. Всередині чується легкий стукіт, панель відчиняється та дає доступ до в'язкої отрути, що вариться в котлі.\n\nЗбоку є невеликий кран, під який ідеально поміщається пляшка. Тепер ви можете зібрати зразки для верховної жриці Мак-Доннелл з проліску Студовій.", ["en"] = "Target: Gahrron's Withering", ["tasks"] = { ["Empty Gahrron's Withering Bottle"] = "порожня пляшка для зразків з Посухи Ґаррона", ["Empty Gahrron's Withering Bottle (Provided)"] = "порожня пляшка для зразків з Посухи Ґаррона (видано)", ["Gahrron's Withering Cauldron Key"] = "ключ від котла Посухи Ґаррона", ["Gahrron's Withering Cauldron Key (Provided)"] = "ключ від котла Посухи Ґаррона (видано)" } },
    [5226] = { [1] = "Повернення до табору Студовій", [2] = "Ви обережно закриваєте кран на панелі керування, спостерігаючи, як краплі варева з котла стікають у порожню пляшку.\n\nОтримавши отруту, настав час повертатися до верховної жриці Мак-Доннелл в табір Студовій.", [3] = "Принесіть пляшку зразків з Посухи Ґаррона верховній жриці Мак-Доннелл в табір Студовій, що в Західних Зачумлених землях.", [4] = "На Посусі Ґаррона знаходиться останній з західних котлів, до якого у нас ще немає доступу. Отримавши зразки зілля з цього котла, ми зможемо додати наші реагенти до всіх котлів! Скара не зможе захистити їх від нас, навіть з силою Кел'Тузада.", [5] = "Вітаю, {ім'я}, тобі вдалося отримати доступ до останнього котла! Алхімік Арбінґтон скоро дізнається, які реагенти необхідно додати до нього.\n\nЩодо тебе, я впевнена, що командир Мужньобій захоче особисто подякувати тобі за твою допомогу. Без тебе наша боротьба проти Скари була б приречена. Дякую тобі, {стать:герою:героїне}!", ["en"] = "Return to Chillwind Camp", ["tasks"] = { ["Filled Gahrron's Withering Bottle"] = "пляшка зразків з Посухи Ґаррона", ["Filled Gahrron's Withering Bottle (Provided)"] = "пляшка зразків з Посухи Ґаррона (видано)" } },
    [523] = { [1] = "Смерть барона", [2] = "Контракт, що ти {стать:роздобув:роздобула}, підписаний бароном Вардусом, шляхтичем із колишнього королівства Альтерак, який також відомий своєю бездушністю та жорстокістю. Я не здивований, що за цим стоїть Вардус.\n\nЗнайди його. Знайди та зверши над ним суд. Напевно, він ховається у якомусь кублі Синдикату — в руїнах Странбрада або в долині на північ звідти.", [3] = "Принесіть голову барона Вардуса війтові Малебу в Південобережжя.", [4] = "Нехай барон Вардус не сподівається, що Південнобережжя дозволить йому безкарно підсилати до нас своїх розбійників. Мені потрібна його голова!", [5] = "Дякую тобі, {Ім'я}. Моїй власній голові тепер трохи легше, знаючи, що цей злочинець втратив свою.", ["en"] = "Baron's Demise", ["tasks"] = { ["Head of Baron Vardus"] = "голова барона Вардуса", ["Head of Baron Vardus (Provided)"] = "голова барона Вардуса (видано)" } },
    [5237] = { [1] = "Місію виконано!", [5] = "{ім'я}, твоя успішна диверсія котлів — це величезна перемога для нас!\n\n<Командир відкашлюється й гучно кричить.>\n\nПочуйте всі! За вірну і віддану службу Королівству Штормовію та Альянсу, за виконання обов'язку перед обличчям непереборних труднощів і неймовірної небезпеки — я вручаю {ім'я} цю винагороду та висловлюю {стать:йому:їй} вічну вдячність, як {стать:справжньому герою:справжній героїні} Альянсу. Ура!", ["en"] = "Mission Accomplished!" },
    [5244] = { [1] = "Руїни Кел'Теріла", [2] = "Історія Кел'Теріла пов'язана з проклятою расою, прикутою до місця, де було здійснено невдалий ритуал...\n\nВисокородні, яких ти там знайдеш, колись викрали священний артефакт, вважаючи, що можуть видобути з нього силу для своєї власної могутності. Через їхні дії реліквія вибухнула, а її шматки пішли під лід озера...\n\nЯкщо хочеш дізнатись більше, поговори з Жароном Каменотесом — він нещодавно відвідував ту місцевість та може розповісти більше.", [3] = "Поговоріть з Жароном Каменотесом у селищі Зорепад.", [5] = "Ну, звісно, я можу розповісти тобі більше про Кел'Теріл. Я не історик, але можу розповісти тобі про те, що я там бачив...", ["en"] = "The Ruins of Kel'Theril" },
    [5245] = { [1] = "Неупокоєні духи Кел'Теріла", [2] = "Високородні духи — це нещасні створіння, це точно. Вони все ще шукають шматки тієї речі, яка назавжди прив'язала їх до Кел'Теріла — викраденої реліквії.\n\nЯкщо тобі цікаво — візьми мою кирку і йди на південь до озера, спробуй зібрати шматки з-під криги.\n\nЯ не можу сказати, що саме ти знайдеш, але я знаю декого, хто може... Аврора Небоклич. Вона мешкає біля вежі Північного ходу у північній частині Східних Зачумлених земель.", [3] = "Використовуйте кирку Жарона, щоб знайти чотири фрагменти реліквії високородних. Віднесіть їх Аврорі Небоклич в Східні Зачумлені землі.", [4] = "Чому ти {стать:прийшов:прийшла} сюди?", [5] = "Минуле вищих ельфів — це те, що я не бажаю обговорювати, {ім'я}. Будь ласка, мені боляче думати про все, що сталося... І про те, що немає способу все виправити.", ["en"] = "Troubled Spirits of Kel'Theril", ["tasks"] = { ["First Relic Fragment"] = "перший фрагмент реліквії", ["First Relic Fragment (Provided)"] = "перший фрагмент реліквії (видано)", ["Fourth Relic Fragment"] = "четвертий фрагмент реліквії", ["Fourth Relic Fragment (Provided)"] = "четвертий фрагмент реліквії (видано)", ["Second Relic Fragment"] = "другий фрагмент реліквії", ["Second Relic Fragment (Provided)"] = "другий фрагмент реліквії (видано)", ["Third Relic Fragment"] = "третій фрагмент реліквії", ["Third Relic Fragment (Provided)"] = "третій фрагмент реліквії (видано)" } },
    [5249] = { [1] = "В Зимоключ", [2] = "У Зимоключі, на півночі звідси, є багато древніх ельфійських руїн. Це сувора земля, але вона містить багато секретів та місць, які варто дослідити.\n\nЗ усіма моїми справами тут, у Скверноліссі, я не мав можливості відвідати Зимоключ. Але немає жодної причини, чому ти не можеш це зробити!\n\nКоли будеш там, знайди Вінда Ночесліда. Він проводить більшість свого часу в селищі Зорепад і добре знає місцевість.", [3] = "Знайдіть селище Зорепад у Зимоключі та поговоріть з Віндом Ночеслідом.", [5] = "Ти {стать:друг:подруга} Айві Листобіг? Приємно познайомитись, {ім'я}.", ["en"] = "To Winterspring!" },
    [525] = { [1] = "Подальші таємниці", [2] = "Я розшифрував цей лист, але я не знаю, що навіть думати. Ти {стать:знайшов:знайшла} це у злодіїв в передгір'ї Альтерака? Дуже дивно...\n\nТобі варто віднести це війтові Південнобережжя. Хоча цей лист досі загадковий, його містечко — найближче до Альтерака. Якщо наростає якась загроза, він повинен про це знати.", [3] = "Принесіть розшифрований лист до війта Малеба в Південнобережжя.", [4] = "{Ім'я}. Чи {стать:подорожував:подорожувала} ти ще по горах і передгір'ях? З якими новинами ти {стать:прийшов:прийшла}?", [5] = "<Малеб читає лист.>\n\nЦе — переклад того листа, який ти {стать:знайшов:знайшла} в таборі Синдикату? Його не написала рука злодюжки, і навіть не шляхтича Альтерака.\n\nСхоже, Синдикат має зв'язки з якоюсь іншою силою, і я здригаюся від думки, що це може бути.", ["en"] = "Further Mysteries", ["tasks"] = { ["Decrypted Letter"] = "розшифрований лист", ["Decrypted Letter (Provided)"] = "розшифрований лист (видано)" } },
    [5261] = { [1] = "Іґан Гарбар", [2] = "Іґан Гарбар шукає когось, хто вполює йому кількох вовків. Це добра новина, оскільки останнім часом вовків в Півночнокрайовій долині сильно побільшало.\n\nЯкщо тебе зацікавила така пропозиція, то поговори з Іґаном. Він неподалік абатства, ліворуч.", [3] = "Поговоріть з Іґаном Гарбарем.", [5] = "Саме так! Я шукаю когось, хто вполює мені вовків! Ти зможеш?", ["en"] = "Eagan Peltskinner" },
    [5321] = { [1] = "Сплячий пробудився", [2] = "Я прямував до застави Маєстри, щоб зустрітися з Ліладріс Місяцерікою, але вирішив зупинитися тут і трохи подрімати. Відтоді, як я прокинувся від Смарагдового Сну, я весь час такий сонний...\n\n<позіхає>\n\nДопоможеш мені дійти? Я так розумію, що застава Маєстри знаходиться на південь звідси, біля дороги в Ясенеділ. Шлях може бути небезпечний, тож я сподіваюся, що у тебе є друзі, які можуть приєднатись до нас.\n\nТак, і ще дещо: я можу заснути дорогою, тож якщо тобі потрібно буде розбудити мене — скористайся моїм рогом. Він лежить у скрині.", [3] = "Проведіть Керлонія Вічнотінь до Ліладріс Місяцеріки на заставу Маєстри в Ясенеділ.", [4] = "Керлоній вже прибув?", [5] = "О, я така щаслива, що Керлоній повернувся! І я певно знайду його сплячим десь поблизу, чи не так?\n\nДякую, що {стать:показав:показала} йому шлях, {ім'я}.", ["en"] = "The Sleeper Has Awakened", ["tasks"] = { ["Horn of Awakening"] = "ріг пробудження", ["Horn of Awakening (Provided)"] = "ріг пробудження (видано)" } },
    [5343] = { [1] = "Статки родини Барових", [2] = "Мій дорогий брат Алексій. Яким же я дурнем був, коли залишив його в живих. Я дивився в обличчя ворога, невмерлого, але залишив його в живих.\n\n<Велдон спльовує.>\n\nТепер він шукає мою спадщину. Я йому цього не дозволю.\n\nЗнайди документи на землі моєї сім'ї до того, як ця мерзота дотягнеться до них своїми кістлявими руками, і я винагороджу тебе за це величезними багатствами. Документи лежать в руїнах Некроситету. Поквапся!", [3] = "Відправляйтеся до Некроситету і поверніть скарби родини Барових. Вони складаються з чотирьох документів: на Тверджу Дарроу, на Брілль, на Тарренський Млин і на Південнобережжя. Поверніться до Велдона Барова коли виконаєте завдання.", [4] = "Попіклуйся про моє майбутнє, і я попіклуюся про твоє.", [5] = "У мене є ще одне завдання для тебе, {ім'я}.", ["en"] = "Barov Family Fortune", ["tasks"] = { ["The Deed to Brill"] = "документи на Брілль", ["The Deed to Brill (Provided)"] = "документи на Брілль (видано)", ["The Deed to Caer Darrow"] = "документи на Тверджу Дарроу", ["The Deed to Caer Darrow (Provided)"] = "документи на Тверджу Дарроу (видано)", ["The Deed to Southshore"] = "документи на Південнобережжя", ["The Deed to Southshore (Provided)"] = "документи на Південнобережжя (видано)", ["The Deed to Tarren Mill"] = "документи на Тарренський Млин", ["The Deed to Tarren Mill (Provided)"] = "документи на Тарренський Млин (видано)" } },
    [537] = { [1] = "Темна Рада", [2] = "Лист, що ти мені {стать:приніс:принесла}, написаний особою, яка називає себе Наґазом і є членом Арґуського Пробудження. Я не знаю, що це за \"пробудження\", але якщо вони у спілці з Синдикатом, то становлять загрозу.\n\nЯ хочу, щоб ти {стать:знайшов:знайшла} Наґаза й арґуських тіньових магів, згаданих у тому листі. {стать:Знайшов і вбив:знайшла і вбила}.\n\nПошукай їх у Верхогір'ї, де Синдикат найсильніший. Це північніше Странбрада.\n\nЯкщо пощастить, то ти знайдеш там цих посланців Арґуського Пробудження.", [3] = "Убийте 4 арґуських тіньових магів.\n\nПринесіть голову Наґаза війтові Малебу в Південнобережжя.", [4] = "{стать:Знайшов:Знайшла} представників Арґуського Пробудження?", [5] = "Хороша робота, {Ім'я}. Арґуське Пробудження не звучить для нас як хороше керівництво Синдикату.\n\nІ, хоча ти й {стать:знищив:знищила} їхнього лідера, та Наґаз був лише прислужником когось іншого. Мережа цієї організації може міцно охоплювати весь континент.\n\nАбо навіть увесь світ.", ["en"] = "Dark Council", ["tasks"] = { ["Argus Shadow Mage"] = "арґуський тіньовий маг", ["Argus Shadow Mage slain"] = "арґуський тіньовий маг: убито", ["Head of Nagaz"] = "голова Наґаза", ["Head of Nagaz (Provided)"] = "голова Наґаза (видано)" } },
    [538] = { [1] = "Південнобережжя", [2] = "{ім'я}. Якщо ти не проти далекої подорожі, в мене є для тебе завдання, яке допоможе поповнити бібліотеку Штормовію.\n\nСтаре королівство Альтерак занепало після великої війни разом зі своєю великою бібліотекою. Це жахливо, що місто зруйноване, та ще жахливіше, що їх колекція знань втрачена! Ми маємо врятувати все, що можемо.\n\nПівденнобережжя — найближче до руїн Альтерака місто. Відправляйся туди та поговори зі знавцем Діббсом. Він направить тебе до руїн, де ти зможеш знайти книги.", [3] = "Поговоріть зі знавцем Діббсом у Південнобережжі.", [5] = "А, так, я пам'ятаю Мільтона. Ще той любитель книжок, будь він здоров.\n\nІ він має рацію. В руїнах Альтерака й досі зберігаються цінні знання, які ми можемо втратити!\n\nТепер в Альтераку живуть огри, а їх не дуже турбують пам'ятки культури.", ["en"] = "Southshore" },
    [54] = { [1] = "Донесення у Злотохрестя", [2] = "{Ім'я:к}, ти добре {стать:проявив:проявила} себе в захисті Північнокраю. Тепер у тебе інше завдання — захист навколишніх земель Ельвиннського лісу.\n\nЯкщо приймаєш цей обов'язок, візьми ці папери, які я підготував. Їх потрібно передати маршалові Дугану в Злотохрестя. Як вийдеш за ворота, тримайся дороги на південь.", [3] = "Віднесіть документи маршала Макбрайда маршалові Дугану в Злотохрестя.", [4] = "У тебе звістка від Макбрайда? Північнокрай — це садок у порівнянні з Ельвиннським лісом. Але, все одно, мені цікаво, що там у Макбрайда.\n\nДай-но поглянути на його звіт...", [5] = "Подивимося. Тут сказано, що ти {стать:був ушанований:була ушанована} званням {стать:заступника:заступниці} штормовійських маршалів. Мої вітання.\n\nІ бажаю удачі, безпека Ельвинна — непроста справа... тим більше коли більша частина армії займається невідомо чим для якогось вельможі!\n\nВажко бути в курсі всіх політичних перипетій у ці темні часи...", ["en"] = "Report to Goldshire", ["tasks"] = { ["Marshal McBride's Documents"] = "документи маршала Макбрайда", ["Marshal McBride's Documents (Provided)"] = "документи маршала Макбрайда (видано)" } },
    [540] = { [1] = "Збереження знань", [2] = "Ці кляті огри поселились в руїнах Альтераку і мене аж тіпає від думки про те, що вони можуть робити з усіма тамтешніми книгами. Ти маєш врятувати все, що зможеш!\n\nЙди в руїни Альтерака та знайди томи, вкрадені ограми. Знайди все, що зможеш та принось до мене. Але я попрошу тебе знайти конкретну книгу - \"Руку Ґрі'лека\". В ній описана давня історія тролів, яку я маю вивчити, а в руїнах Альтерака її бачили востаннє.", [3] = "Принесіть 5 врятованих томів та потерту шкіряну книгу \"Рука Ґрі'лека\" знавцю Діббсу в Південнобережжя.", [4] = "Хотів би я особисто обшукати руїни, та певно я не витримаю такого походу в гори. А як проходять твої пошуки, {ім'я}?", [5] = "Вони в тебе! Чудово! Я маю негайно почати вивчення \"Руки Ґрі'лека\"!", ["en"] = "Preserving Knowledge", ["tasks"] = { ["Recovered Tome"] = "врятований том", ["Recovered Tome (Provided)"] = "врятований том (видано)", ["Worn Leather Book"] = "потерта шкіряна книга", ["Worn Leather Book (Provided)"] = "потерта шкіряна книга (видано)" } },
    [5401] = { [1] = "Жетон Сріблястого Світанку", [5] = "Усі, хто бореться зі злом від імені Сріблястого Світанку, повинні отримати наш жетон. Він дасть право отримувати нагороди від наших квартирмейстерів.\n\nДоки ти носитимеш його, ти зможеш збирати камені Скари з вбитих прибічників Скари, які вони носять як знаки розрізнення. Збирай ці знаки та принось мені. За кожний набір ти отримаєш знак доблесті Сріблястого Світанку.\n\nПрямуй назустріч долі, {клас:к} — приєднуйся до боротьби зі злом!", ["en"] = "Argent Dawn Commission" },
    [542] = { [1] = "Повернення до Мільтона", [2] = "Мені потрібно провести деякий час за вивченням \"Руки Ґрі'лека\", яку ти мені {стать:приніс:принесла}. Та я певен, що Мільтону теж не терпиться отримати врятовані книги та поповнити бібліотеку Штормовію.\n\nОсь книги, які ти {стать:зібрав:зібрала} в руїнах Альтерака, впорядковані та упаковані. Віднеси їх Мільтону Сніпу в Штормовій, певен, він буде їм надзвичайно радий.", [3] = "Принесіть альтерацькі томи Мільтону Сніпу в Штормовій.", [4] = "{ім'я}, ти {стать:повернувся:повернулась}! Як пройшла подорож до Альтераку? Ти {стать:приніс:принесла} щось звідти?", [5] = "О, Світло! Поглянь-но на них! Не можу повірити, що вони пережили занепад Альтераку. І всіх цих огрів!\n\nДякую, {ім'я}. Неймовірно тобі дякую! Ти {стать:допоміг:допомогла} зберегти важливі знання та {стать:додав:додала} величності королівській бібліотеці Штормовію.", ["en"] = "Return to Milton", ["tasks"] = { ["Tomes of Alterac"] = "альтерацькі томи", ["Tomes of Alterac (Provided)"] = "альтерацькі томи (видано)" } },
    [543] = { [1] = "Тіара Перенольдів", [2] = "Тіара Перенольдів це давня реліквія роду Перенольдів — сім'ї, що правила Альтераком до його знищення. Кажуть, що цю тіару інкрустували найкращими смарагдами майстри-ювеліри Залізогарту.\n\nТіару було втрачено після знищення Альтераку, але ходять чутки про огр-мага, Ґрел'борґа Ницого, що знайшов тіару і зараз шукає скарби в руїнах Альтераку.\n\nМи хотіли б, щоб ти {стать:знайшов:знайшла} цю тіару.", [3] = "Принесіть тіару Перенольдів Ремінґтону Скеледужу в Штормовій.", [4] = "Вітаю, {ім'я}. Обережно, не наступи на мої штани. Вони щойно від кравця.", [5] = "Ах, чудово. Її, звісно, варто б почистити, але ти справді {стать:перевершив:перевершила} себе, {ім'я}. Я попрошу когось підготувати тіару та помістити її в нашу колекцію.\n\nНаша вдячність тобі така ж велика, як і наша колекція.", ["en"] = "The Perenolde Tiara", ["tasks"] = { ["Perenolde Tiara"] = "тіара Перенольдів", ["Perenolde Tiara (Provided)"] = "тіара Перенольдів (видано)" } },
    [55] = { [1] = "Морбент Скверн", [2] = "Морбент Скверн ховається у своєму лігві, в будинку, що розташований на пагорбі над кладовищем Воронячого пагорба, на сході. Його час на цій землі підходить до кінця...\n\nВикористай прокляття Морбента проти нього. Це зробить його захисні чари безсилими.\n\nУбий його. Убий його і врятуй нас від його злодіянь. Стань знаряддям моєї помсти та {стать:героєм:героїнею} Смерколісся!", [3] = "Використайте прокляття Морбента проти Морбента Скверна, вбийте його, а потім поверніть прокляття Морбента Свену в його табір.", [4] = "Морбент Скверн переможений?!", [5] = "Морбент Скверн переможений. Темних вершників все ще багато, але маленька частинка того, на що я безмежно сподівався, вже здійснилася.\n\nТи {стать:зробив:зробила} неможливе, і твої подвиги завжди будуть жити у легендах Смерколісся.\n\nІди, {ім'я:к}. І, можливо, одного дня доля знову приведе тебе до мене...", ["en"] = "Morbent Fel", ["tasks"] = { ["Morbent Fel"] = "Морбент Скверн", ["Morbent Fel slain"] = "Морбент Скверн: убито", ["Morbent's Bane"] = "прокляття Морбента", ["Morbent's Bane (Provided)"] = "прокляття Морбента (видано)" } },
    [5505] = { [1] = "Ключ до Некроситету", [4] = "Що ж, тримай, {ім'я}, — завершений скелетний ключ. Я впевнений, що він дозволить тобі потрапити до Некроситету. Є лиш один спосіб це перевірити. Не гай часу, перевір!", [5] = "Що ж, тримай, {ім'я}, — завершений скелетний ключ. Я впевнений, що він дозволить тобі потрапити до Некроситету. Є лиш один спосіб це перевірити. Не гай часу, перевір!\n\nЗичу удачі, {стать:могутній герою:могутня героїне}. Продовжуй нести світло в темряву!", ["en"] = "The Key to Scholomance" },
    [551] = { [1] = "Зачаклований пергамент", [2] = "На цей пергамент накладено закляттям, яке робить його неможливим для розуміння. Але одне слово зверху можна розібрати:\n\n\nНаґаз", [3] = "Віднесіть зачаклований пергамент до знавця Діббса у Південнобережжя.", [4] = "О, у вас є щось для мене? Сподіваюся, це новий клаптик знань, зібраний десь у верхів'ях гір...", [5] = "Знову зашифровані записи?\n\nХотів би я мати талант розшифровувати всі ці дивні письмена з Альтераку. Але, боюся, в мене недостатньо знань.", ["en"] = "The Ensorcelled Parchment", ["tasks"] = { ["Ensorcelled Parchment"] = "зачаклований пергамент", ["Ensorcelled Parchment (Provided)"] = "зачаклований пергамент (видано)" } },
    [5541] = { [1] = "Набої для Грімостріла", [2] = "Геґнар Грімостріл продає рушниці біля дороги на Ковмар. Стрілці та мінометні команди багато практикуються біля його крамниці і йому завжди потрібні свіжі набої.\n\nАле... Останній ящик боєприпасів, що я йому відправляв, загубився дорогою. Мій кур'єр розповів, що він стояв табором біля Посивілого лігва, коли на нього напали вендиго... і цей дурень кинув Грімострілові набої!\n\n{Ім'я}, чи {стать:не міг би:не могла б} ти знайти їх і повернути Грімострілу? Він на них чекає і, напевно, в нього набої вже закінчуються.", [3] = "Принесіть набої Геґнару Грімострілу в Дун-Морог.", [4] = "Сподіваюся, ти не за набоями, бо вони у мене майже закінчилися!", [5] = "Чудово, нові набої! Поставка стариганя Лослора, нарешті, прибула! Нехай набої і запізнилися, але, як казав мій дідусь, краще пізно, ніж ніколи!\n\nКрасно дякую, {ім'я}. Мої покупці вже зачекалися!", ["en"] = "Ammo for Rumbleshot", ["tasks"] = { ["Rumbleshot's Ammo"] = "Набої Грімостріла", ["Rumbleshot's Ammo (Provided)"] = "набої Грімостріла (видано)" } },
    [5545] = { [1] = "Зв'язка неприємностей", [2] = "У мене справжня халепа. Збігає термін замовлення на пиломатеріали, і мені катастрофічно не вистачає часу. Вовки та ведмеді на північ звідси відганяють моїх працівників від тієї деревини, яку вони вже нарубали.\n\nЯ вже говорила із заступником Райнером щодо цих тварин, але мені потрібен хтось, хто б міг піти позбирати для мене дрова. Якщо ти зможеш зібрати для мене вісім зв'язок деревини, я, можливо, встигну вчасно виконати своє замовлення.", [3] = "Принесіть 8 зв'язок деревини Релен у лісозаготівельний табір Східнодолу.", [4] = "Термін замовлення спливає, {клас:к}. Будь ласка, поквапся і позбирай ці зв'язки деревини.", [5] = "Відмінно! Завдяки тобі я зможу виконати замовлення вчасно. Щоб висловити свою подяку, я хотіла б запропонувати трохи грошей, як компенсацію за твої клопоти.\n\nДякую і прощавай.", ["en"] = "A Bundle of Trouble", ["tasks"] = { ["Bundle of Wood"] = "зв'язка деревини", ["Bundle of Wood (Provided)"] = "зв'язка деревини (видано)" } },
    [56] = { [1] = "Нічна варта", [2] = "Як командир Нічної варти, я заприсяглася захищати жителів Темнодолу. Штормовій відізвав своїх охоронців з постів, залишивши нас напризволяще.\n\nЯкщо ти відчуваєш що впораєшся з цим завданням, нам потрібна твоя допомога! Вирушай в Затишні сади, що на південь від Темнодолу, та вбий 8 скелетних воїнів та 6 скелетних магів. Ми маємо знищити загрозу невмерлих!", [3] = "Командир Альтея Чорнобрива з Темнодолу хоче, щоб ви вбили 8 скелетних воїнів та 6 скелетних магів.", [4] = "Бачу, ти {стать:повернувся:повернулася}, {ім'я:к}. Якщо ти хочеш довести, що можеш бути {стать:корисним:корисною} Нічній варті, повертайся до мене, коли вб'єш 8 скелетних воїнів та 6 скелетних магів.", [5] = "Чудово, {ім'я:к}. За службу народу Темнодолу ти будеш {стать:винагороджений:винагороджена}.", ["en"] = "The Night Watch", ["tasks"] = { ["Skeletal Mage"] = "скелетний маг", ["Skeletal Mage slain"] = "скелетний маг: убито", ["Skeletal Warrior"] = "скелетний воїн", ["Skeletal Warrior slain"] = "скелетний воїн: убито" } },
    [562] = { [1] = "Хоу, Штормовій!", [2] = "Мій колишній наставник зі Штормовійської варти надіслав мені повідомлення, що верховне командування Альянсу занепокоєне появою наг. З чуток, є хороші шанси на підвищення — або, принаймні, переведення на іншу посаду — для тих, хто добре проявить себе.\n\nЄ лише одна маленька проблема... Я не можу впоратися з нагами, {ім'я}. Звичайно, я можу розборонити п'яну бійку чи скрутити якогось жебрака, але наги — це вже занадто для мене. Допоможи мені, {ім'я}!", [3] = "Вбийте 10 берегових мисливців Клинкоспинів та 10 сирен Клинкоспинів для лейтенанта Фаррена Орінелла в Південнобережжі.", [4] = "У мене вже готовий лист майору Самуельсону зі Штормовію. Тепер мені потрібен лиш результат.", [5] = "Після того, як ми розберемось з нагами у Південнобережжі, я стану претендентом на нову посаду. Я повернуся у Штормовій... якомога далі від цього забутого Світлом порту.", ["en"] = "Stormwind Ho!", ["tasks"] = { ["Daggerspine Shorehunter"] = "береговий мисливець Клинкоспинів", ["Daggerspine Shorehunter slain"] = "береговий мисливець Клинкоспинів: убито", ["Daggerspine Siren"] = "сирена Клинкоспинів", ["Daggerspine Siren slain"] = "сирена Клинкоспинів: убито" } },
    [5621] = { [1] = "Вбрання Місяця", [2] = "Мені потрібна твоя допомога, {ім'я}. Я маю залишатися тут, щоб навчати інших, але ти зможеш допомогти нашій одній пораненій вартовій. Вона поранилася під час патрулювання міста і потребує нашої допомоги. Її звати Шая.\n\nКоли знайдеш її, зціли її рани та зміцни її тіло своїми заклинаннями. Це захистить її від лиха, принаймні на деякий час. Повертайся до мене, коли виконаєш свій обов'язок перед Елуною.", [3] = "Знайдіть вартову Шаю та зціліть її рани, використовуючи Мале зцілення (ранг 2). Після цього надайте їй Слово сили: Стійкість та поверніться до Лорни Ранкосяйва в Доланаар.", [4] = "Наші заклинання Стійкості дуже потужні, {ім'я:к}. Вони дозволяють нашим супутникам витримувати багато поранень та виживати у ситуаціях, які вони зазвичай не пережили. Але це ніщо в порівнянні з нашими здібностями зцілення. Немає кращих цілителів, ніж жерці — запам'ятай це. Твої сили можуть з легкістю змінити хід битви.", [5] = "Ти чудово {стать:впорався:впоралася} та {стать:послужив:послужила} Елуні. Я дякую тобі за це.\n\nБудь ласка, візьми це вбрання на знак моєї подяки. Воно означає, що ти {стать:заслужив:заслужила} своє місце серед нас. Якщо бажаєш — носи його з гордістю, але в будь-якому випадку, ми завжди будемо знати, що ти {стать:один:одна} з нас.\n\nІди з Елуною, {ім'я}, і дякую тобі.", ["en"] = "Garments of the Moon", ["tasks"] = { ["Heal and fortify Sentinel Shaya"] = "Зцілити та зміцнити Вартову Шайю", ["Heal and fortify Sentinel Shaya (Provided)"] = "Зцілити та зміцнити Вартову Шайю (видано)", ["Heal and fortify Sentinel Shaya slain"] = "Зцілити та зміцнити Вартову Шайю: убито" } },
    [5622] = { [1] = "На славу Елуни", [2] = "{Ім'я}, ти маєш відправитися до Доланаару, коли закінчиш свої справи в Тінистій долині. Там ти знайдеш Лорну Ранкосяйво. Вона наставить тебе далі на шлях Елуни, і саме з нею ти отримаєш своє перше вбрання, яке буде вказувати на твій статус {стать:жреця:жриці} Елуни.\n\nБережи себе, і нехай тебе береже Елуна.", [3] = "Поговоріть з Лорною Ранкосяйвом на Тельдрассілі.", [5] = "Я рада, що Шанда відправила тебе знайти мене, {ім'я}. Навчання молодих жерців шляхам Елуни приносить мені задоволення.", ["en"] = "In Favor of Elune" },
    [5623] = { [1] = "На славу Світла", [2] = "І знову привіт, {стать:юний:юна} {клас:к}. Настав час дізнатися тобі більше про нашу релігію. Як тільки ти закінчиш свої доручення в Північнокраї, будь ласка, знайди жрицю Жозетту в Злотохресті. Вона може навчити тебе більшого, і вона чула, що ти стаєш {стать:сильнішим:сильнішою} у шляхах Світла. Вона з нетерпінням чекає можливості навчати тебе.", [3] = "Поговоріть зі жрицею Жозеттою в Ельвиннському лісі.", [5] = "Я рада, що ти {стать:прийшов:прийшла}, {ім'я}. Нам є що обговорити про твоє майбутнє та твій шлях Світла.", ["en"] = "In Favor of the Light" },
    [5624] = { [1] = "Вбрання Світла", [2] = "Зазвичай, я ставлю невеликі виклики послідовникам Світла, щоб перевірити їх навички. Я хочу побачити, чи вони справді варті носіння їх перших риз — знаку того, що церква приймає цих жерців та підтримує їх.\n\nАле зараз ситуація дещо інакша. Один із жителів Злотохрестя бачив пораненого вартового біля річки, на схід звідси. Його звати Робертс. Знайди його, зціли його рани, зміцни його тіло та повернися сюди. Якщо ти впораєшся, я вважатиму що твоє випробування завершено.", [3] = "Знайдіть вартового Робертса та зціліть його рани використовуючи Мале зцілення (ранг 2). Після цього надайте йому Слово сили: Стійкість та поверніться до жриці Жозетти в Злотохрестя.", [4] = "Як ти вже {стать:міг:могла} дізнатися, наша магія зцілення життєво необхідна для виживання нашого народу у ці важкі часи. Особливо для тих мандрівників та героїв, що беруться за зброю та магію, щоб дати відсіч загрозам.\n\nНе забувай наскільки це вміння важливе. Зцілення разом зі Стійкістю зроблять твоїх супутників більш витривалими в бою, дозволивши їм витримувати потужні удари ворога.\n\nНе дозволяй нікому нехтувати твоєю магією.", [5] = "Прекрасно, {ім'я}. Іще один здоровий вартовий готовий допомагати місту. Я рада бачити, що ти вже {стать:навчився:навчилася} користуватися своїми здібностями. Коли відчуєш, що ти {стать:готовий:готова} до нових тренувань — будь ласка, повертайся до мене. А поки що прийми це вбрання. Це дозволить іншим знати, що ти {стать:один:одна} з нас. Якщо не хочеш його носити, нічого. Для нових випробувань воно тобі не знадобиться.", ["en"] = "Garments of the Light", ["tasks"] = { ["Heal and fortify Guard Roberts"] = "Зцілити та зміцнити охоронця Робертса", ["Heal and fortify Guard Roberts (Provided)"] = "Зцілити та зміцнити охоронця Робертса (видано)", ["Heal and fortify Guard Roberts slain"] = "Зцілити та зміцнити охоронця Робертса: убито" } },
    [5625] = { [1] = "Вбрання Світла", [2] = "Зазвичай, саме в цей час жерці проходять випробування, щоб побачити чи вони справді гідні, щоб носити вбрання, які позначають їхнє місце в церкві. Але, якщо чесно кажучи, у мене є більш нагальні справи. Житель Хараносу щойно прибув та розповів мені про пораненого горянина, що знаходиться прямо за містом, на південь. Його ім'я Дольф.\n\nЗціли Дольфа, дай йому стійкість, і я вважатиму, що ти {стать:пройшов:пройшла} випробування. Що скажеш?", [3] = "Знайдіть горянина Дольфа та зціліть його рани використовуючи Мале зцілення (ранг 2). Після цього надайте йому Слово сили: Стійкість та поверніться до Максана Анвола у Харанос.", [4] = "Ти вже {стать:знайшов:знайшла} Дольфа, {ім'я}?\n\nТи напевне вже {стать:зрозумів:зрозуміла}, що наша здатність до зцілення вельми корисна. Ми можемо не тільки піклуватися про поранених — без нас не обійдуться жодні \"герої\", що намагаються прославити своє ім'я. Завдяки Стійкості вони можуть витримувати більше ударів, а поки наша зцілювальна магія підтримує їхні життя, не існує нічого, що ми не змогли б подолати!", [5] = "Гарна робота, {ім'я}. Ти маєш Світло всередині себе, в цьому немає сумнівів.\n\nОсь, візьми це вбрання. Воно показуватиме всім, що ти {клас}. Можеш одягнути його, якщо хочеш.\n\nПізніше тобі доведеться пройти через інші випробування. Роби все можливе, щоб дізнатися більше про свої здібності. Спробуй свої сили у кількох битвах самотужки, а потім — разом з іншими мандрівниками.\n\nІ не хвилюйся... ти не поступаєшся їм у силі.", ["en"] = "Garments of the Light", ["tasks"] = { ["Heal and fortify Mountaineer Dolf"] = "Зцілити та зміцнити альпініста Дольфа", ["Heal and fortify Mountaineer Dolf (Provided)"] = "Зцілити та зміцнити альпініста Дольфа (видано)", ["Heal and fortify Mountaineer Dolf slain"] = "Зцілити та зміцнити альпініста Дольфа: убито" } },
    [5626] = { [1] = "На славу Світла", [2] = "Агоу! {ім'я}! Є хвилька?\n\nТи вже досит довго слідуєш Світлу, того мусиш побалакати з Максаном Анволом в Хараноси. Він навчит тебе більше шляху, їким ти йдеш, і їкщо ти доведеш своу гідніст, він даст тобі твоє перше вбраня {стать:жерца:жрици}.\n\nХутчіш! Єк си зурудуїш тут, відправляйси до Хараносу через тунель — Максан ждатиме тебе.", [3] = "Поговоріть з Максаном Анволом в Дун-Морозі.", [5] = "Оу, то тебе Брансток прислав, ге? Файно, файно. Він має рацію, вже час тобі зробити більший крок до Світла. Се зробит тебе набагато сильніше... Се загартує твоє тіло... та силу волі.", ["en"] = "In Favor of the Light" },
    [5627] = { [1] = "Зорі Елуни", [5] = "Ти {стать:довів, що вартий:довела, що варта} уваги Елуни, {ім'я}. Як відчуєш, що ти {стать:готовий:готова}, я з радістю навчу тебе одного з заклинань Елуни. Вони унікальні для нашого народу.", ["en"] = "Stars of Elune" },
    [5628] = { [1] = "Повернення додому", [2] = "Ах, так. привіт, ти {ім'я}? Я рада, що ти {стать:зупинився:зупинилася} поговорити. Ти зараз так далеко від дому в такому юному віці, я захоплена твоїм завзяттям. Хотіла б і я у твоєму віці мати таку пристрасть до мандрів.\n\nНещодавно тут була жриця твого ордену і вона шукала тебе. Вона сказала, щоб ти терміново {стать:повертався:поверталася} до храму Місяця в Дарнасі та {стать:поговорив:поговорила} зі жрицею Алатеєю. Це явно пов'язано з твоїм навчанням. На твоєму місці я б не зволікала з цим.", [3] = "Поговоріть зі жрицею Алатеєю в Дарнасі.", [5] = "Чудово, ти {стать:повернувся:повернулася} додому, {ім'я}. Ми з Тірандою завжди радіємо, коли ті, кого ми навчали, відправляються у великий світ, а потім повертаються до нас живими й неушкодженими. Як твої справи? Елуна досі благословляє твої мандри? Можливо, після того, як ми поговоримо про важливі справи, ти зможеш розказати мені більше про свої подорожі.", ["en"] = "Returning Home" },
    [5629] = { [1] = "Повернення додому", [2] = "І знову привіт, {ім'я}. Я знаю, що ти {стать:зайнятий:зайнята} допомогою нашому народу, але ти маєш приділити трохи часу і собі. Жриця Алатея прислала когось, хто шукає тебе. Схоже, що ти {стать:привернув:привернула} увагу наших старійшин, і вони відчувають, що ти {стать:готовий:готова} до великих справ. Відправляйся до храму Місяця в Дарнасі та знайди там Алатею. Вона буде чекати. Щасти тобі, та нехай Елуна береже тебе.", [3] = "Поговоріть зі жрицею Алатеєю в Дарнасі.", [5] = "Чудово, ти {стать:повернувся:повернулася}, {ім'я}. Ми з Тірандою завжди радіємо, коли ті, кого ми навчали, відправляються у великий світ, а потім повертаються до нас живими й неушкодженими. Як твої справи? Елуна досі благословляє твої мандри? Можливо, після того, як ми поговоримо про важливі справи, ти зможеш розказати мені більше про свої подорожі.", ["en"] = "Returning Home" },
    [5630] = { [1] = "Повернення додому", [2] = "Привіт, {стать:юначе:юнко}. Приємно бачити, як ти подорожуєш сими далекими землями. Без образ, але зазвичай, більшість тво' народу погано переносить сей холодний клімат. Добре, що ти більш {стать:витривалий:витривала}.\n\nНедавно одна з твоїх жриц була тут та шукала тебе — вона казала, що ти маєш знайти Алатею в храмі Місяця у Дарнасі. Сказала, що це терміново, і ти маєш відправитися туди їк май швидше.", [3] = "Поговоріть зі жрицею Алатеєю в Дарнасі.", [5] = "Чудово, ти {стать:повернувся:повернулася} додому, {ім'я}. Ми з Тірандою завжди радіємо, коли ті, кого ми навчали, відправляються у великий світ, а потім повертаються до нас живими й неушкодженими. Як твої справи? Елуна досі благословляє твої мандри? Можливо, після того, як ми поговоримо про важливі справи, ти зможеш розказати мені більше про свої подорожі.", ["en"] = "Returning Home" },
    [5631] = { [1] = "Повернення додому", [2] = "Нещодавно наші зали відвідала жриця, що розшукувала тебе, {стать:юний:юна} {раса:к}. Вона сказала, що ти маєш якомога скоріше повернутися до храму Місяця в Дарнасі. Як прибудеш туди — поговори зі жрицею Алатеєю, вона розповість тобі більше.\n\nНехай Світло буде з тобою, {ім'я}.", [3] = "Поговоріть зі жрицею Алатеєю в Дарнасі.", [5] = "Чудово, ти {стать:повернувся:повернулася} додому, {ім'я}. Ми з Тірандою завжди радіємо, коли ті, кого ми навчали, відправляються у великий світ, а потім повертаються до нас живими й неушкодженими. Як твої справи? Елуна досі благословляє твої мандри? Можливо, після того, як ми поговоримо про важливі справи, ти зможеш розказати мені більше про свої подорожі.", ["en"] = "Returning Home" },
    [5632] = { [1] = "Повернення додому", [2] = "О, так, звичайно. Привіт, {ім'я}. Нещодавно тут була посланниця від нашого ордену і вона шукала тебе. Вона сказала, що щось важливе відбувається в Дарнасі й ти маєш повернутися до храму Місяця якомога швидше. Коли прибудеш туди — поговори зі жрицею Алатеєю. Я думаю, що це пов'язано з твоїми успіхами на шляху {клас:р}.\n\nЗагалом, повертайся до Дарнасу, коли зможеш.", [3] = "Поговоріть зі жрицею Алатеєю в Дарнасі.", ["en"] = "Returning Home" },
    [5633] = { [1] = "Повернення додому", [2] = "Вітаю, {стать:юначе:юначко}. Рада бачити тебе тут, в наших величних залах. Най Світло благословить тебе та твій рід.\n\nПоки ти {стать:подорожував:подорожувала} нашими землями, жриця твого храму приходила сюди, шукаючи тебе. Вона сказала, щоб ти хутчіш {стать:повертався:поверталася} до храму Місяця. Вибач, я не можу розповісти тобі більше, але це звучало, як щось важливе. Як доберешся до храму — поговори зі жрицею Алатеєю.", [3] = "Поговоріть зі жрицею Алатеєю в Дарнасі.", [5] = "Чудово, ти {стать:повернувся:повернулася} додому, {ім'я}. Ми з Тірандою завжди радіємо, коли ті, кого ми навчали, відправляються у великий світ, а потім повертаються до нас живими й неушкодженими. Як твої справи? Елуна досі благословляє твої мандри? Можливо, після того, як ми поговоримо про важливі справи, ти зможеш розказати мені більше про свої подорожі.", ["en"] = "Returning Home" },
    [5634] = { [1] = "Відчайдушна молитва", [2] = "Ти {стать:потрібен:потрібна} у Штормовії, {ім'я}. Верховна жриця Лорена каже, що настав час тобі довести, що ти {стать:готовий:готова} до наступного рівня навчання. Не гай надто багато часу на пошуки шляху до Лорени. Ти знайдеш її у соборі Світла, що в центрі міста. Передай їй мої вітання та доведи, що ти {стать:гідний:гідна} такого покликання. Нехай Світло буде з тобою, {ім'я}.", [3] = "Поговоріть з верховною жрицею Лореною у Штормовії.", [5] = "Ти {стать:зробив:зробила} чудову послугу Світлу, ставши яскравим прикладом для тих, хто мандрує цими небезпечними землями та за їх межами. Будь ласка, прийми цей урок як подяку за все, що ти {стать:зробив:зробила}.", ["en"] = "Desperate Prayer" },
    [5635] = { [1] = "Відчайдушна молитва", [2] = "Ти {стать:привернув:привернула} увагу нашого вищого духовенства, {ім'я}. Вони просять тебе якнайшвидше прибути до собору Світла, що в Штормовії. Схоже, вони вважають, що ти вже {стать:проявив:проявила} себе і {стать:готовий:готова} продовжити своє навчання. Як прибудеш туди, знайди верховну жрицю Лорену. Вона зможе направити тебе далі. Щасти тобі та нехай Світло буде з тобою.", [3] = "Поговоріть з верховною жрицею Лореною у Штормовії.", [5] = "Я рада, що ти {стать:прийшла:прийшов}, {ім'я}. Є багато речей які нам потрібно обговорити, але найважливіше — твоє навчання зі Світлом.\n\nЄ уроки, які повинні засвоїти всі слуги Світла. Якщо ти {стать:готовий:готова}, ми почнемо один із цих уроків зараз.", ["en"] = "Desperate Prayer" },
    [5636] = { [1] = "Відчайдушна молитва", [2] = "Благослови тебе Елуна, {стать:добрий:добра} {раса:к}. Я сподіваюся твоє Світло захищає тебе.\n\nТебе нещодавно розшукував один з твоїх жерців. Він просив передати тобі, що в соборі Світла на тебе чекає верховна жриця Лорена. Схоже, що ти добре {стать:постарався:постаралася}, щоб привернути таку увагу. На твоєму місці я б не гаяла часу — ти {стать:потрібен:потрібна} своєму народові.", [3] = "Поговоріть з верховною жрицею Лореною у Штормовії.", [5] = "Я рада, що ти {стать:прийшла:прийшов}, {ім'я}. Є багато речей які нам потрібно обговорити, але найважливіше — твоє навчання зі Світлом.\n\nЄ уроки, які повинні засвоїти всі слуги Світла. Якщо ти {стать:готовий:готова}, ми почнемо один із цих уроків зараз.", ["en"] = "Desperate Prayer" },
    [5637] = { [1] = "Відчайдушна молитва", [2] = "Прийшов час тобі повернутися до Штормовію, {ім'я}. Верховна жрица Лорена хоче поговорити з тобоу в соборі Світла. Си стало щось дуже добре, або щось дуже погане, їкщо верховна жриця хоче бачити тебе особисто. Але я гадау, що так чи інакше се буде корисно для тебе.\n\nНе марнуй часу тут. Відправляйси туди як май швидше.", [3] = "Поговоріть з верховною жрицею Лореною у Штормовії.", [5] = "Я рада, що ти {стать:прийшла:прийшов}, {ім'я}. Є багато речей які нам потрібно обговорити, але найважливіше — твоє навчання зі Світлом.\n\nЄ уроки, які повинні засвоїти всі слуги Світла. Якщо ти {стать:готовий:готова}, ми почнемо один із цих уроків зараз.", ["en"] = "Desperate Prayer" },
    [5638] = { [1] = "Відчайдушна молитва", [2] = "Зовсім нещодавно один з твоїх жерців був тут та шукав тебе, {раса:к}. Він просив передати тобі, що на тебе чекають у соборі Світла. Сказав, що це дуже важливо. На твоєму місці я б не надто хвилювалася через це. Він виглядав доброзичливо... ніби це були гарні новини. Але певно тобі варто якнайшвидше піти до собору.\n\nХай береже тебе Елуна, {раса:к}.", [3] = "Поговоріть з верховною жрицею Лореною у Штормовії.", [5] = "Я рада, що ти {стать:прийшла:прийшов}, {ім'я}. Є багато речей які нам потрібно обговорити, але найважливіше — твоє навчання зі Світлом.\n\nЄ уроки, які повинні засвоїти всі слуги Світла. Якщо ти {стать:готовий:готова}, ми почнемо один із цих уроків зараз.", ["en"] = "Desperate Prayer" },
    [5639] = { [1] = "Відчайдушна молитва", [2] = "Ти {стать:потрібен:потрібна} у Штормовії, {ім'я}. Верховна жриця Лорена каже, що настав час тобі довести, що ти {стать:готовий:готова} до наступного рівня навчання. Не гай надто багато часу на пошуки шляху до Лорени. Ти знайдеш її у соборі Світла, що в центрі міста. Передай їй мої вітання та доведи, що ти {стать:гідний:гідна} такого покликання. Нехай Світло буде з тобою, {ім'я}.", [3] = "Поговоріть з верховною жрицею Лореною у Штормовії.", [5] = "Я рада, що ти {стать:прийшла:прийшов}, {ім'я}. Є багато речей які нам потрібно обговорити, але найважливіше — твоє навчання зі Світлом.\n\nЄ уроки, які повинні засвоїти всі слуги Світла. Якщо ти {стать:готовий:готова}, ми почнемо один із цих уроків зараз.", ["en"] = "Desperate Prayer" },
    [5640] = { [1] = "Відчайдушна молитва", [2] = "Хвала Елуні та твоєму Світлу, {ім'я}.\n\nНині багато членів нашого ордену вирішили зміцнити свої здібності, що відображають їх віру в Елуну. Наскільки я знаю, те ж саме відбувається і в твоєму ордені.\n\nКоли закінчиш свої справи у Дарнасі, вирушай до своєї верховної жриці для подальшого навчання.", [3] = "Поговоріть з верховною жрицею Лореною у Штормовії.", [5] = "Я рада, що ти {стать:прийшла:прийшов}, {ім'я}. Є багато речей які нам потрібно обговорити, але найважливіше — твоє навчання зі Світлом.\n\nЄ уроки, які повинні засвоїти всі слуги Світла. Якщо ти {стать:готовий:готова}, ми почнемо один із цих уроків зараз.", ["en"] = "Desperate Prayer" },
    [5641] = { [1] = "Безстрашність", [2] = "{ім'я}, твій верховний жрець Рохан призначив тобі аудієнцію в Залізогарті. Хутчіше, {стать:мій могутній друже:моя могутня подруго}, твоє наступне випробування вже не за горами. Я хотів би бути свідком особливих обрядів твоєї раси, але моє місце тут. Нехай Світло супроводжує тебе у твоїх мандрах. Рохан чекатиме на тебе у Таємній палаті Залізогарту.", [3] = "Поговоріть з верховним жерцем Роганом в Залізогарті.", [5] = "У тебе задатки {стать:великого:великої} {клас:р}, {ім'я}. Продовжуй у тому ж дусі!\n\nТи вже {стать:показав:показала}, що ти {стать:готовий:готова} до битви. Можливо, настав час навчити тебе іще дечому.", ["en"] = "A Lack of Fear" },
    [5645] = { [1] = "Безстрашність", [2] = "{ім'я}, твій верховний жрець Рохан призначив тобі аудієнцію в Залізогарті. Хутчіше, {стать:мій могутній друже:моя могутня подруго}, твоє наступне випробування вже не за горами. Я хотів би бути свідком особливих обрядів твоєї раси, але моє місце тут. Нехай Світло супроводжує тебе у твоїх мандрах. Рохан чекатиме на тебе у Таємній палаті Залізогарту.", [3] = "Поговоріть з верховним жерцем Роганом в Залізогарті.", [5] = "Добре, що ти {стать:прийшов:прийшла}, {ім'я}. Наша раса горда та сильна, настав час тобі не тільки навчитися бути собою, а й вселяти такі ж почуття та впевненість в інших. Ти {стать:готовий, хлопче:готова, дівчино}?", ["en"] = "A Lack of Fear" },
    [5647] = { [1] = "Безстрашність", [2] = "Твоя раса дуже сильна, {ім'я}. Ми пишаємося союзом з вами. І з кожним заходом сонця ти та твій рід не лише дедалі ближче до розгадки власного походження, а й до здобуття великої впевненості у виборі власного шляху в багатьох речах. Саме ця впевненість приносить вам перемогу.\n\nНещодавно з Залізогарту прийшла звістка. Тебе просять повернутися і поговорити з верховним жерцем Роханом у Таємній палаті. Не варто змушувати його чекати. Хай направить тебе Елуна.", [3] = "Поговоріть з верховним жерцем Роганом в Залізогарті.", [5] = "Добре, що ти {стать:прийшов:прийшла}, {ім'я}. Наша раса горда та сильна, настав час тобі не тільки навчитися бути собою, а й вселяти такі ж почуття та впевненість в інших. Ти {стать:готовий, хлопче:готова, дівчино}?", ["en"] = "A Lack of Fear" },
    [565] = { [1] = "Бартолова накидка з хутра єті", [2] = "Я, величний Бартоло, зроблю для тебе всесвітньо відому, прославлену Альянсом, накидку з хутра єті!\n\nПодорожуй світом, шукай собі кращу накидку, звісно. Ой, зачекай, що це я чую, {стать:маленький:маленька} {раса:к} ? \"Бартоло, кращої накидки немає!\" Так, так! Це я вже чув.\n\nМені потрібен рулон вовни, накидка жителя пагорбів, виготовлена вправним шкіряником, тонкі нитки та хутро єті, звісно ж! Принеси мені всі ці речі, і станеш {стать:щасливим власником:щасливою власницею} одного зі знаменитих плащів Бартоло!", [3] = "Принесіть Бартоло Ґінсетті з Південнобережжя рулон вовняної тканини, накидку жителя пагорбів, тонку нитку та 10 клаптів хутра єті.", [4] = "Отже, ти {стать:повернувся:повернулася} до величного Бартоло. Напевно, ти {стать:закінчив:закінчила} збирати матеріали для своєї накидки з хутра єті? А може, ти просто у захваті від величі Бартоло!", [5] = "Настав час величному Бартоло застосувати свою магію! Мені не потрібні ні чарівна палиця, ні чарівний жезл. Бо я, великий Бартоло, творю магію лише за допомогою голки та нитки!", ["en"] = "Bartolo's Yeti Fur Cloak", ["tasks"] = { ["Bolt of Woolen Cloth"] = "рулон вовняної тканини", ["Bolt of Woolen Cloth (Provided)"] = "рулон вовняної тканини (видано)", ["Fine Thread"] = "тонка нитка", ["Fine Thread (Provided)"] = "тонка нитка (видано)", ["Hillman's Cloak"] = "накидка жителя пагорбів", ["Hillman's Cloak (Provided)"] = "накидка жителя пагорбів (видано)", ["Yeti Fur"] = "хутро єті", ["Yeti Fur (Provided)"] = "хутро єті (видано)" } },
    [5664] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [5665] = { [1] = "<UNUSED>", [2] = "З Дарнасу надіслано звістку, {ім'я}. Здається, одна з твоїх жриць хоче, щоб ти повернувся додому. Поговори зі жрицею Алатеєю у Храмі Місяця, коли зможеш. Здається, вона задоволена твоїм прогресом. Я впевнений, що вона дуже пишається тим, що один зі слуг Елуни робить такі великі кроки у <його/її> вірі.\n\nНехай Світло буде з тобою.", ["en"] = "<UNUSED>" },
    [5666] = { [1] = "<UNUSED>", [2] = "О, {ім'я}, радий тебе бачити. Ходять чутки, що ти готовий до наступного випробування в Храмі Місяця. Жриця Алатея сама бажає поговорити з тобою. Тобі слід якомога швидше повернутися до Дарнасу. Заверши всі свої справи тут і поспіши.", ["en"] = "<UNUSED>" },
    [5667] = { [1] = "<UNUSED>", [2] = "Так, радий бачити, що в тебе добре йдуть навчання, юний <жрицю/жрице>. Один з твого роду нещодавно був тут і шукав тебе. Здається, тебе хочуть повернути в Дарнас. Щось про жрицю Алатею та Храм Місяця. Звучало важливо. Можливо, тобі варто скоро туди повернутися.", ["en"] = "<UNUSED>" },
    [5672] = { [1] = "Благодать Елуни", [2] = "Настав прекрасний день {ім'я}. Ти {стать:досяг:досягла} віку, в якому наші {стать:жерці:жриці} навчаються здібностей, відомих лише нічним ельфам. Але не я буду тебе навчати. Ти маєш повернутися до храму Місяця та поговорити зі жрицею Алатеєю, коли завершиш свої справи тут. Вона випробує тебе, щоб впевнитися, що ти {стать:готовий:готова}, і лише тоді вона навчить тебе благодаті Елуни.", [3] = "Поговоріть зі жрицею Алатеєю в Дарнасі.", [5] = "Присвятивши себе служінню Елуні та нашому народу, ти {стать:досяг:досягла} стану, якого не кожен з нас може досягти. Це наша традиція — навчити тебе більш могутніх здібностей за твою відданість. Чи погодишся ти?", ["en"] = "Elune's Grace" },
    [5673] = { [1] = "Благодать Елуни", [2] = "Знай, що ти можеш у будь-який час звернутися до наших тренерів, {ім'я}, але є деякі речі, які ми не зможемо тобі передати. Одна з цих речей — це вчення твоєї богині Елуни. Вона надає особливі здібності своїм вірним послідовникам, і якщо я не помиляюся, настав час тобі повернутися до свого храму Місяця, щоб пройти випробування.\n\nПовертайся туди, як тільки зможеш та поговори зі жрицею Алатеєю.", [3] = "Поговоріть зі жрицею Алатеєю в Дарнасі.", [5] = "Хай благословить тебе Елуна за таке швидке повернення. Це важливий період у твоєму навчанні, і орден дуже серйозно до цього ставиться. Коли відпочинеш з дороги — дай мені знати. Тоді ми зможемо обговорити продовження твого навчання і те, куди твій шлях поведе тебе далі.", ["en"] = "Elune's Grace" },
    [5674] = { [1] = "Благодать Елуни", [2] = "Настав прекрасний день {ім'я}. Ти {стать:досяг:досягла} віку, в якому наші {стать:жерці:жриці} навчаються здібностей, відомих лише нічним ельфам. Але не я буду тебе навчати. Ти маєш повернутися до храму Місяця та поговорити зі жрицею Алатеєю, коли завершиш свої справи тут. Вона випробує тебе, щоб впевнитися, що ти {стать:готовий:готова}, і лише тоді вона навчить тебе благодаті Елуни.", [3] = "Поговоріть зі жрицею Алатеєю в Дарнасі.", [5] = "Хай благословить тебе Елуна за твоє швидке повернення. Це важливий період у твоєму навчанні, і орден дуже серйозно до цього ставиться. Коли відпочинеш з дороги — дай мені знати. Тоді ми зможемо обговорити продовження твого навчання і те, куди твій шлях поведе тебе далі.", ["en"] = "Elune's Grace" },
    [5675] = { [1] = "Благодать Елуни", [2] = "Ми марнуємо час, {стать:хлопче:дівчино}. Пора тобі повертатися додому, в Дарнас. Жриця Алатея передала, що ти маєш повернутися туди для навчання. Схоже, вони відчувають, що ти вже {стать:готовий:готова} пройти випробування, як і ті, хто служить Світлу. Ти маєш відправитися туди, як тільки зможеш. В посланні Алатеї написано, що вона чекатиме на тебе в храмі Місяця. Щасти тобі.", [3] = "Поговоріть зі жрицею Алатеєю в Дарнасі.", [5] = "Хай благословить тебе Елуна за твоє швидке повернення. Це важливий період у твоєму навчанні, і орден дуже серйозно до цього ставиться. Коли відпочинеш з дороги — дай мені знати. Тоді ми зможемо обговорити продовження твого навчання і те, куди твій шлях поведе тебе далі.", ["en"] = "Elune's Grace" },
    [5676] = { [1] = "Арканічна віддача", [2] = "Тобі час повертатися до Штормовію, {стать:юначе:юначко}. Твої старійшини викликали тебе для подальших тренувань. І хоча це мене трохи турбує, але я роблю це в ім'я союзу між нашими расами.\n\nСкажу відверто — я не надто довіряю арканічній магії, хай вона божественна чи ні.\n\nТи зрозумієш про що я говорю коли повернешся до свого собору Світла. Поговори там з верховною жрицею Лореною.", [3] = "Поговоріть з верховною жрицею Лореною у Штормовії.", [5] = "Ми були змушені вивчити деяку магію, щоб захиститися від того, що часто називають нашим найбільшим ворогом — аркани.\n\nЯ навчу тебе заклинання, що допомогло б тобі захистити себе та своїх супутників від тих, хто володіє такою силою.", ["en"] = "Arcane Feedback" },
    [5677] = { [1] = "Арканічна віддача", [2] = "Як би мені не хотілося показати тобі наше власне особливе вчення Світла, це не наше місце. Твоє місце у Штормовії з тобі подібними, {ім'я}... поки що. Повір мені, я не маю на меті образити тебе. Коли повернешся до верховної жриці Лорени у собор Світла, ти зрозумієш про що я. Настав час приготуватись до майбутнього і вибрати свій власний шлях.", [3] = "Поговоріть з верховною жрицею Лореною у Штормовії.", [5] = "Ти саме вчасно, {ім'я}. Я вже почала сумніватися, чи всі мої посланці впоралися. Рада бачити, що це так, інакше ти б все ще {стать:тинявся:тинялась} світом в пошуках нових загроз нашого народу.\n\nТи {стать:готовий:готова} до подальших тренувань? Ти швидко набираєшся сил, і я відчуваю, що ти {стать:готовий:готова} дізнатися більше про нашу віру.", ["en"] = "Arcane Feedback" },
    [5678] = { [1] = "Арканічна віддача", [2] = "Тобі час повертатися до Штормовію, {стать:юначе:юначко}. Твої старійшини викликали тебе для подальших тренувань. І хоча це мене трохи турбує, але я роблю це в ім'я союзу між нашими расами.\n\nСкажу відверто — я не надто довіряю арканічній магії, хай вона божественна чи ні.\n\nТи зрозумієш про що я говорю коли повернешся до свого собору Світла. Поговори там з верховною жрицею Лореною.", [3] = "Поговоріть з верховною жрицею Лореною у Штормовії.", [5] = "Ти саме вчасно, {ім'я}. Я вже почала сумніватися, чи всі мої посланці впоралися. Рада бачити, що це так, інакше ти б все ще {стать:тинявся:тинялась} світом в пошуках нових загроз нашого народу.\n\nТи {стать:готовий:готова} до подальших тренувань? Ти швидко набираєшся сил, і я відчуваю, що ти {стать:готовий:готова} дізнатися більше про нашу віру.", ["en"] = "Arcane Feedback" },
    [57] = { [1] = "Нічна варта", [2] = "{Ім'я:к}, я отримую звіти про нашестя невмерлих в лісі! Якщо ти згодишся взятися за це завдання, вирушай на кладовище Воронячого пагорба та вбий 15 скелетних марників та 15 скелетних страховищ. Також повідомляють про скелетів на південь від Темнодолу, в районі цвинтаря при Затишних садах. Невмерлі мають бути вигнані зі Смерколісся!", [3] = "Командир Альтея Чорнобрива з Темнодолу хоче, щоб ви вбили 15 скелетних марників і 15 скелетних страховищ.", [4] = "Повертайся, коли вб'єш 15 скелетних марників та 15 скелетних страховищ, {ім'я:к}.", [5] = "Жителі Темнодолу дякують тобі, {ім'я:к}. Ти {стать:довів:довела} свою відданість Нічній Варті.", ["en"] = "The Night Watch", ["tasks"] = { ["Skeletal Fiend"] = "скелетний марник", ["Skeletal Fiend slain"] = "скелетний марник: убито", ["Skeletal Horror"] = "скелетне страховище", ["Skeletal Horror slain"] = "скелетне страховище: убито" } },
    [5713] = { [1] = "Один постріл — один труп", [2] = "Я прямувала до Аубердіна з важливим повідомленням, коли на мене напав хутропуз Марош і його пантрувачі. Під час нападу мене отруїли, і я ледве тримаюся на ногах. Я можу зробити протиотруту, але це займе деякий час.\n\nЯ прошу тебе захистити мене, поки я не прийму протиотруту. Я допоможу тобі своїм луком, наскільки зможу.\n\nЯкщо ми виживемо, я зможу доставити своє послання в Аубердін, а тебе попрошу поговорити з Онеєю на заставі Маєстри, і розказати їй про те, що трапилося.", [3] = "Захистіть стражницю Айнашу, після чого поговоріть з Онеєю на заставі Маєстри в Ясенедолі.", [4] = "Ти не {стать:зустрічав:зустрічала} стражницю Айнашу? Вона відправилась на важливе завдання і досі не повернулася.", [5] = "Ти {стать:приніс:принесла} довгоочікувану звістку, {клас:к}. Приємно чути, що Айнаша жива й здорова завдяки тобі. Сподіваюся, ти приймеш цю нагороду за твою доблесть. Нехай Елуна охороняє тебе та освітлює твій шлях.", ["en"] = "One Shot. One Kill.", ["tasks"] = { ["Protect Aynasha"] = "Захисти Айнашу" } },
    [574] = { [1] = "Особливі війська", [2] = "Тепер, після зменшення кількості солдатів Курцена, тобі доведеться зіткнутися з його висококваліфікованими військами. Вони або вибираються в ліс та вбивають наших повстанців, або ж їх можна знайти в глибинах поселення Курцена, в печері, яку вони називають Погребиця.\n\nЯ особисто знаю багатьох солдатів Курцена і знаю, що вони досвідчені, віддані та жорстокі. Я ставлю перед тобою нелегке завдання, {ім'я}.\n\nПісля того, як ти впораєшся з ними, відзвітуй лейтенанту Дорену, моєму командиру. Він захоче почути твою доповідь з перших вуст.", [3] = "Вбийте 10 командосів і 6 головодавів Курцена.\n\nВідзвітуйте про це лейтенанту Дорену в табір Повстання.", [4] = "Сержантка Йогва сказала мені, що ти {стать:досвідчений і хоробрий:досвідчена і хоробра}, {клас:к}. Маєш про що доповісти?", [5] = "{ім'я}. Сержантка Йогва довірилась твоїм здібностям, а я довірився їй. Ми й подумати не могли, що ти завдаси такої поразки військам Курцена. Я боявся, що ми, повстанці, залишилися зовсім самі, а наодинці ми б ніколи не змогли протистояти полковнику.\n\nМожливо, тепер у нас є надія на виживання.", ["en"] = "Special Forces", ["tasks"] = { ["Kurzen Commando"] = "командос Курцена", ["Kurzen Commando slain"] = "командос Курцена: убито", ["Kurzen Headshrinker"] = "головодав Курцена", ["Kurzen Headshrinker slain"] = "головодав Курцена: убито" } },
    [578] = { [1] = "Камінь припливів", [2] = "Якщо на острові справді є гоблін-маг і водяні елементалі, це означає, що я можу заволодіти каменем припливів!\n\nЯ хочу, щоб ти {стать:знайшов:знайшла} цей острів з духами та {стать:з'ясував:з'ясувала}, що там відбувається. Якщо ти захочеш дізнатися більше про камінь припливів, віднеси цю записку до бібліотеки Штормовію, вони знайдуть тобі книгу, в якій я вперше натрапив на цю легенду.\n\nНевже Ґазбан насправді натрапив на камінь?", [3] = "Знайдіть острів з духами для барона Ревілґаза з Грабіжної Бухти.", [4] = "{ім'я}, тролі справді володіли дивовижними магічними предметами. І тепер, думаю, в мене є можливість додати один з них до своєї великої колекції. Ти {стать:дізнався:дізналася} звідки ширяться чутки?", [5] = "Отже, історії виявились правдивими! Неймовірно!\n\nОднак, якщо ми хочемо отримати камінь припливів, нам потрібно знайти спосіб здолати прокляття, яке накладено на нього. Прокляття — справа магічна, тож нам знадобиться допомога одного з тих чарівників.", ["en"] = "The Stone of the Tides", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Locate the haunted island"] = "Знайдіть острів з духами" } },
    [58] = { [1] = "Нічна варта", [2] = "Ситуація на кладовищі Воронячого пагорба все ще залишається напруженою. Безпека Темнодолу у твоїх руках, {ім'я:к}. У мене недостатньо вартових, щоб забезпечити безпеку міста. Нам потрібно, щоб ти {стать:вирушив:вирушила} на Воронячий пагорб та {стать:знищив:знищила} 20 розповсюдників чуми в східному мавзолеї!", [3] = "Командир Альтея Чорнобрива з Темнодолу хоче, щоб ви вбили 20 розповсюдників чуми в східному мавзолеї Воронячого пагорба.", [4] = "Мені потрібна твоя допомога, {ім'я:к}. Вирушай на кладовище на північному заході та зачисти східний мавзолей від 20 розповсюдників чуми.\n\nПовертайся до мене, коли завдання буде виконане.", [5] = "Від імені народу Темнодолу і як лідер Нічної Варти, я дякую тобі, {ім'я:к}, за твою хоробрість і самовідданість. Нехай Світло осяює твій шлях.", ["en"] = "The Night Watch", ["tasks"] = { ["Plague Spreader"] = "розповсюдник чуми", ["Plague Spreader slain"] = "розповсюдник чуми: убито" } },
    [5805] = { [1] = "Ласкаво просимо!", [2] = "Ласкаво просимо до World of Warcraft!\n\nНа знак особливої подяки за придбання колекційного видання World of Warcraft, прийміть цей подарунковий сертифікат і передайте його Меріссі Стілвелл в Північнокрайовій долині. За нього ви отримаєте подарунок — маленького компаньйона, який супроводжуватиме вас у пошуках пригод і слави.\n\nЩе раз дякуємо і бажаємо приємного перебування у World of Warcraft!", [3] = "Віднесіть подарунковий сертифікат Північнокраю до Мерісси Стілвелл.", [4] = "Вітаю! Приємно познайомитися з тобою!\n\nБачу, ти маєш подарунковий сертифікат. Віддай його мені, а я запропоную тобі щось натомість.", [5] = "Ти справді {стать:особливий герой:особлива героїня}, {ім'я:к}. Ми вітаємо тебе в Азероті та пропонуємо один з цих унікальних подарунків!", ["en"] = "Welcome!", ["tasks"] = { ["Northshire Gift Voucher"] = "подарунковий сертифікат Північнокраю", ["Northshire Gift Voucher (Provided)"] = "подарунковий сертифікат Північнокраю (видано)" } },
    [5841] = { [1] = "Ласкаво просимо!", [2] = "Ласкаво просимо до World of Warcraft!\n\nНа знак особливої подяки за придбання колекційного видання World of Warcraft, прийміть цей подарунковий сертифікат і передайте його Йорі Шпарошолому в Морозній долині. За нього ви отримаєте подарунок — маленького компаньйона, який супроводжуватиме вас у пошуках пригод і слави.\n\nЩе раз дякуємо і бажаємо приємного перебування у World of Warcraft!", [3] = "Віднесіть подарунковий сертифікат Морозної долини до Йорі Шпарошолома.", [4] = "Привіт! Приємно познайомитися з тобою!\n\nБачу, ти маєш подарунковий сертифікат. Віддай його мені, а я запропоную тобі щось натомість.", [5] = "Ти справді {стать:особливий герой:особлива героїня}, {ім'я:к}. Ми вітаємо тебе в Азероті та пропонуємо один з цих унікальних подарунків!", ["en"] = "Welcome!", ["tasks"] = { ["Coldridge Valley Gift Voucher"] = "подарунковий сертифікат Морозної долини", ["Coldridge Valley Gift Voucher (Provided)"] = "подарунковий сертифікат Морозної долини (видано)" } },
    [5842] = { [1] = "Ласкаво просимо!", [2] = "Ласкаво просимо до World of Warcraft!\n\nНа знак особливої подяки за придбання колекційного видання World of Warcraft, прийміть цей подарунковий сертифікат і передайте його Орентілу Шелесту Вітру в Тінистій долині. За нього ви отримаєте подарунок — маленького компаньйона, який супроводжуватиме вас у пошуках пригод і слави.\n\nЩе раз дякуємо і бажаємо приємного перебування у World of Warcraft!", [3] = "Віднесіть подарунковий сертифікат Тінистої долини до Орентіла Шелеста Вітру.", [4] = "Вітаю! Приємно познайомитися з тобою!\n\nБачу, ти маєш подарунковий сертифікат. Віддай його мені, а я запропоную тобі щось натомість.", [5] = "Ти справді {стать:особливий герой:особлива героїня}, {ім'я:к}. Ми вітаємо тебе в Азероті та пропонуємо один з цих унікальних подарунків!", ["en"] = "Welcome!", ["tasks"] = { ["Shadowglen Gift Voucher"] = "подарунковий сертифікат Тінистої долини", ["Shadowglen Gift Voucher (Provided)"] = "подарунковий сертифікат Тінистої долини (видано)" } },
    [5882] = { [1] = "Бальзам з уламків душ", [4] = "Маяк Кенарія дозволяє побачити уламки душ уражених оскверненням тварин, убитих заради загального блага. Я подрібню уламки душ на реагент, придатний для виготовлення кенарійського бальзаму зцілення рослин. Ми використовуємо цей засіб, щоб вилікувати уражені скверною рослини.\n\nВ обмін на ці уламки душ я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Дуже добре, ось тобі декілька порцій кенарійського бальзаму. Шукай в Скверноліссі осквернені рослини, {ім'я}! Як знайдеш їх — використовуй бальзам, щоб очистити їх.", ["en"] = "Salve via Hunting", ["tasks"] = { ["Corrupted Soul Shard"] = "уламок оскверненої душі", ["Corrupted Soul Shard (Provided)"] = "уламок оскверненої душі (видано)" } },
    [5883] = { [1] = "Бальзам з мінералів", [4] = "Якщо під час видобутку копалин в Скверноліссі в тебе буде з собою маяк Кенарія, ти зможеш побачити уражений купорос, що проникає в жили металів. Я знаю, як очистити цей купорос і перетворити його на реагент, придатний для виготовлення кенарійського бальзаму зцілення рослин. Ми використовуємо цей засіб, щоб вилікувати уражені скверною рослини.\n\nЯкщо ти принесеш мені уражений купорос, я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Дуже добре, ось декілька порцій кенарійського бальзаму. Якщо ти знайдеш уражений купорос, коли видобуватимеш копалини у Скверноліссі, не забудь притримати його для мене! Що більше ти знайдеш, то більше бальзаму я зможу зробити.", ["en"] = "Salve via Mining", ["tasks"] = { ["Tainted Vitriol"] = "уражений купорос", ["Tainted Vitriol (Provided)"] = "уражений купорос (видано)" } },
    [5884] = { [1] = "Бальзам з осквернених трав", [4] = "Маяк Кенарія дозволяє досвідченому травнику помітити залишок скверни — мерзенний продукт осквернення, що вразило Сквернолісся. Моя робота в Скверноліссі дозволила мені навчитися перетворювати залишок скверни в очисний реагент... який ми використовуємо в кенарійському бальзамі зцілення рослин.\n\nКоли ти збиратимеш трави в Скверноліссі, ти зможеш натрапити на залишок скверни, якщо матимеш при собі маяк. В обмін на залишки я виготовлю для тебе кенарійський бальзам.", [5] = "Чудова робота, {ім'я} — коли ми їх очистимо, вони допоможуть нам повернути Сквернолісся до життя. Ось, візьми кілька порцій кенарійського бальзаму зцілення рослин та прямуй до лісу. Зцілення цих земель від скверни — невідкладна справа!", ["en"] = "Salve via Gathering", ["tasks"] = { ["Fel Creep"] = "залишок скверни", ["Fel Creep (Provided)"] = "залишок скверни (видано)" } },
    [5885] = { [1] = "Бальзам зі шкір", [4] = "Маяк Кенарія дає змогу досвідченому шкуродеру знаходити серед зібраної у Скверноліссі шкіри ту, що уражена скверною. Я переробляю цю здавалось би непотрібну шкіру в густу пасту, що прискорює дію кенарійського бальзаму зцілення рослин. Коли будеш займатися шкуродерством у Скверноліссі, обов'язково тримай при собі маяк!\n\nКоли збереш клапті ураженої шкіри — принеси їх мені, і я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Це саме те, що мені потрібно. Ось — візьми кенарійський бальзам, щоб очистити рослини Сквернолісся від осквернення. Ми повинні боротися, {ім'я}!", ["en"] = "Salve via Skinning", ["tasks"] = { ["Patch of Tainted Skin"] = "клапоть ураженої шкіри", ["Patch of Tainted Skin (Provided)"] = "клапоть ураженої шкіри (видано)" } },
    [5886] = { [1] = "Бальзам з розбитих чарів", [4] = "Сила магічного предмета відповідає силі субстанцій, які отримують унаслідок розбиття його чарів. Я винайшла спосіб перероблення сирих субстанцій, які використовують накладачі чарів, у реагент, придатний для створення кенарійського бальзаму зцілення рослин. Для цього тобі не потрібен маяк Кенарія — підійде будь-який магічний предмет, розбиття чарів якого дає малі підсвітні субстанції.\n\nМені потрібна лише одна така субстанція. За на неї я дам тобі кенарійський бальзам зцілення рослин. Підсвітня субстанція дуже потужна — навіть одної вистачить надовго!", [5] = "Ось кілька порцій кенарійського бальзаму зцілення рослин, {ім'я}, і за нього я прошу лише одну малу підсвітню субстанцію. Субстанція — це найпотужніша речовина, яку я можу використати для створення бальзаму. Якщо тобі знадобиться більше бальзаму — приходь до мене.", ["en"] = "Salve via Disenchanting", ["tasks"] = { ["Lesser Nether Essence"] = "мала підсвітня субстанція", ["Lesser Nether Essence (Provided)"] = "мала підсвітня субстанція (видано)" } },
    [5892] = { [1] = "Припаси Залізодонних", [2] = "До початку бойових дій ми зберігали припаси для Дун-Балдара в копальні Залізодонних. Троги, що з'явилися там, не були великою проблемою, коли наші війська охороняли шахти, але тепер, коли ми воюємо з Ордою, утримувати контроль над копальнею стало неможливо.\n\nНам потрібні припаси Залізодонних, {ім'я:к}. Іди в шахту і принеси їх сюди.", [3] = "Принесіть 10 припасів Залізодонних квартирмейстеру Альянсу в Дун-Балдар.", [4] = "Ти {стать:приніс:принесла} припаси, {ім'я:к}? Вони нам завжди потрібні!", [5] = "Чудова робота! Я використаю ці запаси з користю! Дякую тобі, {ім'я:к}!", ["en"] = "Irondeep Supplies", ["tasks"] = { ["Irondeep Supplies"] = "припаси Залізодонних", ["Irondeep Supplies (Provided)"] = "припаси Залізодонних (видано)" } },
    [59] = { [1] = "Обладунки із тканини та шкіри", [2] = "Твоя доблесть і відвага варта цього знаку, що згодиться для одної частини броні. Я хочу, щоб ти {стать:відніс:віднесла} його до Сари Древоляг в лісозаготівельний табір Східнодолу. Віддай їй знак, щоб вона створила обладунок спеціально для тебе. І після того, як ти його отримаєш, {ім'я:к}, користуйся ним для захисту Ельвинну.\n\nЛісозаготівельний табір Східнодолу розташований за постом вартового Томаса.", [3] = "Дайте Сарі Древоляг знак броні Штормовію.", [4] = "Армія Штормовію доручила мені постачати обладунки із тканини та шкіри її людям.\n\nЯкщо ти {стать:приніс:принесла} мені знак, то я з радістю щось зроблю і для тебе.", [5] = "О, дякую за знак. Будь ласка, не соромся і вибери обладунок, що тобі до вподоби.\n\nНехай щастить, {стать:хоробрий:хоробра} {клас:к}! І нехай ця броня служить тобі гідно.", ["en"] = "Cloth and Leather Armor", ["tasks"] = { ["Stormwind Armor Marker"] = "знак броні Штормовію", ["Stormwind Armor Marker (Provided)"] = "знак броні Штормовію (видано)" } },
    [5903] = { [1] = "Чуму на вас!", [2] = "Я багато разів самотужки намагався знищити Багряний Похід силою, але безрезультатно. Тому я вирішив ускладнити їхнє життя альтернативними методами.\n\nЯкщо ти бажаєш допомогти, я хочу заселити цю лісопильню найжахливішими видами термітів.\n\nВ Чумоліссі, біля колись великого Стратгольма, є ціла колонія, яка пережила чуму та Скару. Знайди термітники та набери повну банку термітів, і тоді ми зможемо випустити їх на Багряний Похід.", [3] = "Використайте порожню банку для термітів на термітниках у Східних Зачумлених землях. Після того, як назбираєте 100 термітів Зачумлених земель, поверніться до Натаніелю Дюмі в табір Студовій, що в Західних Зачумлених землях.", [4] = "Ти {стать:знайшов:знайшла} термітники, {ім'я:к}? Я чув, що їх повно в Чумоліссі.", [5] = "Чудово, {ім'я}. Дякую. Поглянь на них... їх так багато. Я навіть трохи співчуваю Багряному Походу, але знову ж таки, це ніколи не була їхня лісопильня, чи не так?", ["en"] = "A Plague Upon Thee", ["tasks"] = { ["Empty Termite Jar"] = "порожня банка для термітів", ["Empty Termite Jar (Provided)"] = "порожня банка для термітів (видано)", ["Plagueland Termites"] = "терміти Зачумлених земель", ["Plagueland Termites (Provided)"] = "терміти Зачумлених земель (видано)" } },
    [5921] = { [1] = "Місячна галявина", [2] = "Усіх друїдів радо приймуть у священних землях Місячної Галявини попри те, що наразі існує певна напруга в Колі Кентаврів між Верховним Друїдом Оленерогом і хранителем Ремулом — вартовим Місячної галявини. Тепер, коли ти {стать:став:стала} на шлях Кігтя, я навчу тебе закляття, що дозволить переноситися туди. Застосуй його, коли шукатимеш знань чи спокою на Місячній галявині.\n\nТвій перший урок — відправитися до Місячної Галявини та поговорити з Дендритом Зіркосяйвом в Нічній Гавані про шлях, яким ти зараз йдеш. Щасти тобі, {стать:молодий:молода} {клас:к}.", [3] = "Використайте заклинання \"Телепорт: Місячна галявина\", щоб відправитися до Місячної галявини. Коли прибудете, поговоріть з Дендритом Зіркосяйвом в селищі Нічна Гавань.", [5] = "\"Так все й починається, Батьку Кенарію. Так все й починається.\"\n\nДендрит робить швидкий, непомітний рух над головою. Ледь помітна аура сили окутує його.\n\n\"Перша форма, до якої ти маєш пристосуватися — форма ведмедя. Я направлю тебе на шлях пізнання цього аспекту життя друїдів, та саме ти маєш прийняти й ширити його — зараз і навіки!\"", ["en"] = "Moonglade" },
    [5923] = { [1] = "Прислухаючись до поклику", [2] = "Перепрошую, на хвилинку...\n\nМені повідомили, що Матренґіл Ведмелик бажає з тобою поговорити. Здається, твої друїдські тренування переходять на новий рівень і він особисто береться навчати тебе. Матренґіл — безпосередній помічник самого верховного друїда, а також один з найдосвідченіших і наймудріших друїдів, що є в Тельдрассілі.\n\nВін мешкає в Кенарійському Анклаві в Дарнасі, на другому рівні дерева Фендрала Оленерога.", [3] = "Поговоріть з Матренґілом Ведмеликом в Кенарійському Анклаві в Дарнасі.", [5] = "Я тішуся, що ти {стать:знайшов:знайшла} шлях сюди, {стать:юний:юна} {клас:к}. Настав час тобі зробити великий крок у ще більший світ.\n\nУ серці кожного з дітей Кенарія звучить поклик служіння природі. Тварини та рослини - наші друзі й наша опіка. Ми свідомо присвячуємо наші життя збереженню рівноваги заради їхнього і нашого блага. Щоб зробити перший крок у цей світ, ти {стать:повинен:повинна} навчитися мистецтву перетворення на ведмедя та опанувати силу тіла й серця.\n\nГотуйся!", ["en"] = "Heeding the Call" },
    [5924] = { [1] = "Прислухаючись до поклику", [2] = "Перепрошую, на хвилинку...\n\nМені повідомили, що Матренґіл Ведмелик бажає з тобою поговорити. Здається, твої друїдські тренування переходять на новий рівень і він особисто береться навчати тебе. Матренґіл — безпосередній помічник самого верховного друїда, а також один з найдосвідченіших і наймудріших друїдів, що є в Тельдрассілі.\n\nВін мешкає в Кенарійському Анклаві в Дарнасі, на другому рівні дерева Фендрала Оленерога.", [3] = "Поговоріть з Матренґілом Ведмеликом в Кенарійському Анклаві в Дарнасі.", [5] = "Я тішуся, що ти {стать:знайшов:знайшла} шлях сюди, {стать:юний:юна} {клас:к}. Настав час тобі зробити великий крок у ще більший світ.\n\nУ серці кожного з дітей Кенарія звучить поклик служіння природі. Тварини та рослини - наші друзі й наша опіка. Ми свідомо присвячуємо наші життя збереженню рівноваги заради їхнього і нашого блага. Щоб зробити перший крок у цей світ, ти {стать:повинен:повинна} навчитися мистецтву перетворення на ведмедя та опанувати силу тіла й серця.\n\nГотуйся!", ["en"] = "Heeding the Call" },
    [5925] = { [1] = "Прислухаючись до поклику", [2] = "Перепрошую, на хвилинку...\n\nМені повідомили, що Матренґіл Ведмелик бажає з тобою поговорити. Здається, твої друїдські тренування переходять на новий рівень і він особисто береться навчати тебе. Матренґіл — безпосередній помічник самого верховного друїда, а також один з найдосвідченіших і наймудріших друїдів, що є в Тельдрассілі.\n\nВін мешкає в Кенарійському Анклаві в Дарнасі, на другому рівні дерева Фендрала Оленерога.", [3] = "Поговоріть з Матренґілом Ведмеликом в Кенарійському Анклаві в Дарнасі.", [5] = "Я тішуся, що ти {стать:знайшов:знайшла} шлях сюди, {стать:юний:юна} {клас:к}. Настав час тобі зробити великий крок у ще більший світ.\n\nУ серці кожного з дітей Кенарія звучить поклик служіння природі. Тварини та рослини - наші друзі й наша опіка. Ми свідомо присвячуємо наші життя збереженню рівноваги заради їхнього і нашого блага. Щоб зробити перший крок у цей світ, ти {стать:повинен:повинна} навчитися мистецтву перетворення на ведмедя та опанувати силу тіла й серця.\n\nГотуйся!", ["en"] = "Heeding the Call" },
    [5929] = { [1] = "Дух Великого ведмедя", [2] = "У північно-західній частині Місячної галявини проживає мудра і благородна істота, котру ми називаємо духом Великого ведмедя. Для всіх друїдів він є наставником і вчителем, який дає початок розуміння справжньої природи ведмедя. Всі друїди в певний момент потребують мудрості цього створіння і ти — не вийняток.\n\nСкоріш йди до духа Великого ведмедя й осягни все, чому він захоче тебе навчити. Коли він буде задоволений тобою, повертайся в Нічну Гавань. Тоді й поглянемо, чи ти справді {стать:засвоїв:засвоїла} його уроки.", [3] = "Знайдіть дух Великого ведмедя на північному заході Місячної галявини та засвойте все, що він розкаже вам про природу ведмедя. Коли уроки будуть завершені, повертайтесь до Дендрита Зіркосяйво в Нічну Гавань на Місячній галявині.", [4] = "Повертайся тоді, коли дух Великого ведмедя відпустить тебе до мене. Без його благословіння ти не зможеш продовжити навчання.", [5] = "Дендрит робить ще один непомітний жест над головою при вашому наближенні. Його знову окутує аура сили й він ледь помітно посміхається.\n\n\"Я відчуваю мудрість в тобі, дитя, якої не було в момент нашої першої зустрічі. У твоєму погляді сила та усвідомлене прагнення, хоча ще не зовсім сформоване. Сьогодні ти навчишся зосереджувати свою силу і залучати природу ведмедя у своїх ділах.\"", ["en"] = "Great Bear Spirit", ["tasks"] = { ["Seek out the Great Bear Spirit and learn what it has to share with you about the nature of the bear."] = "Шукайте Великого Ведмедя-Духа та дізнайтеся, що він може вам розповісти про природу ведмедя." } },
    [5931] = { [1] = "Повернення в Дарнас", [2] = "Настав час нашим шляхам розійтись, {стать:юначе:юнко}, адже для подальшого навчання тобі потрібно повернутися до того, хто прислав тебе до мене. Матренґіл Ведмелик живе в справжній гармонії з природою, хоча і мешкає небезпечно близько до того місця де ця гармонія похитнулася. Слухайся його настанов і зовсім скоро ти цілком засвоїш свої перші уроки, які і визначатимуть твою роль {стать:хранителя:берегині} балансу.\n\nА зараз йди, {стать:юначе:юнко}. Ми ще зустрінемось.", [3] = "Поверніться в Дарнас і поговоріть із Матренґілом Ведмеликом в Кенарійському Анклаві.", [5] = "З поверненням, {ім'я:к}. Я відчуваю, що твоя перша зустріч з духом Великого Ведмедя повпливала на тебе так, як і на інших друїдів, які ступили на шлях Пазура... Трохи збиває з пантелику, але вражає. Зі мною теж так було.\n\nДух Великого Ведмедя був частиною Азерот з самої її появи. Ми покладаємось на її мудрість і могутність в досягненні наших цілей. Тепер настав час тобі пройти своє перше випробування на цьому шляху. Отже, слухай...", ["en"] = "Back to Darnassus" },
    [5981] = { [1] = "Буйні велетні", [2] = "Близько 4000 років тому Тіранда Шелест Вітру врятувала життя королеви кригозубів від нашестя велетнів. З того часу кригозуби стали союзниками нічних ельфів.\n\nТі самі велетні, що колись були небезпекою для кригозубів, все ще існують недалеко звідси. Вони називаються кригобоями, і зайняли велику долину на півдні.\n\nДоведи свою відданість кригозубам, убий цих велетнів в ім'я королеви кригозубів, Ши-Ротам!", [3] = "Риверн Криговій хоче, щоб ви вбили 4 велетнів-кригобоїв і 4 хранителів-кригобоїв.", [4] = "Ти маєш довести свою рішучість, {ім'я}.", [5] = "Чудово, {ім'я}. Я визнаю твою рішучість.", ["en"] = "Rampaging Giants", ["tasks"] = { ["Frostmaul Giant"] = "велетень-кригобій", ["Frostmaul Giant slain"] = "велетень-кригобій: убито", ["Frostmaul Preserver"] = "хранитель-кригобій", ["Frostmaul Preserver slain"] = "хранитель-кригобій: убито" } },
    [6] = { [1] = "Винагорода за голову Ґарріка М'якоступа", [2] = "Ґаррік М'якоступ — головоріз, який мучить наших фермерів і торговців уже тижні — був помічений в халупі поряд з виноградниками, що на схід від абатства, за мостом. Принеси мені голову цього лиходія й отримаєш винагороду!\n\nАле будь {стать:обережним:обережною}, {ім'я:к}. Ґаррік згуртував навколо себе банду злочинців. До нього нелегко буде дістатися.", [3] = "Убийте Ґарріка М'якоступа та принесіть його голову заступникові Віллему в Північнокрайове абатство.", [4] = "Ти {стать:знайшов:знайшла} халупу Ґарріка? Невже ми нарешті позбулися цього мерзотника?", [5] = "Ха-а — ти {стать:спіймав:спіймала} його! Ти {стать:зробив:зробила} Ельвиннові чудову послугу і за це отримаєш гарну винагороду!", ["en"] = "Bounty on Garrick Padfoot", ["tasks"] = { ["Garrick's Head"] = "голова Ґарріка", ["Garrick's Head (Provided)"] = "голова Ґарріка (видано)" } },
    [60] = { [1] = "Свічки кобольдів", [2] = "Вітаю, {стать:шановний пане:шановна пані}! Маєте хвилинку?\n\nМи з братом завідуємо аптекою в Штормовії, а я тут, щоб зібрати великі свічки заради воску. Чи могли б ви мені допомогти?\n\nВеликі свічки можна роздобути у кобольдів, і ходять чутки, що ці тварюки наводнили ельвиннські шахти... Бездонну копальню на півдні та Яшмову, що на північному сході. Пропоную шукати свічки в одному з цих місць.", [3] = "Принесіть 8 великих свічок Вільямові Товкачу в Злотохрестя.", [4] = "Ви вже зібрали свічки?", [5] = "О, ви були заклопотані полюванням на кобольдів! Дякую за свічки, {ім'я:к}, і ось ваша винагорода...", ["en"] = "Kobold Candles", ["tasks"] = { ["Large Candle"] = "велика свічка", ["Large Candle (Provided)"] = "велика свічка (видано)" } },
    [6001] = { [1] = "Тіло і серце", [2] = "На сході від Аубердіна знаходиться багато печер місячних совухів. У тій, що найближче до Аубердіна, стоїть камінь місячного совуха. Місяцекіготь з'явиться коли ти посиплеш на неї кенарійським місячним пилом. Місяцекіготь таїть в собі силу, якою ти, як {стать:один:одна} з друїдів Пазура {стать:повинен:повинна} володіти.\n\nТи {стать:заслужив:заслужила} право користуватися цим кенарійським місячним пилом, {ім'я:к}... тепер доведи мені, що ти також заслуговуєш володіти силами тіла і серця, які так необхідні друїду!", [3] = "Посипте кенарійським місячним пилом на камінь місячного совуха в Аубердіні, щоб викликати Місяцекігтя. Переможіть його та отримайте силу тіла і серця, якими він володіє.\n\nПо завершенню, поговоріть з Матренґілом Ведмеликом в Дарнасі.", [4] = "Доки ти не приймеш виклик, що чекає тебе, ти не зумієш цілком пізнати силу тіла і серця. До тих пір я нічим не зможу тобі помогти.", [5] = "Це твій перший крок на шляху до великих звершень, {ім'я:к}. Я відчуваю вчення духа Великого ведмедя в тобі й бачу, що ти {стать:перейняв:перейняла} силу Місяцекігтя.\n\nБільш нічого тобі не перешкоджає... дозволь мені тепер навчити тебе, що означає бути {клас:о} Пазура!", ["en"] = "Body and Heart", ["tasks"] = { ["Face Lunaclaw and earn the strength of body and heart it possesses."] = "Зіткніться з Лунаклогом і здобудьте силу тіла та серця, якою він володіє." } },
    [601] = { [1] = "Водяні елементалі", [2] = "Водяні елементалі, без сумніву, були викликані Ґазбаном, гоблінським чарівником, який, як кажуть, знайшов камінь припливів. На скільки нам відомо, камінь припливів проклинає свого власника, змушуючи його то зникати, то з'являтися, то знову зникати...\n\nМожливо, ми знайдемо спосіб зняти прокляття. Ми можемо попросити даларанського мага проаналізувати залишки магії на одному з браслетів водяних елементалів. Вирушай на острів і принеси мені кілька зразків цих браслетів.", [3] = "Принесіть 6 браслетів водяних елементалів барону Ревілґазу в Грабіжну Бухту.", [4] = "Є якісь успіхи, {ім'я}?", [5] = "Хм, мого погляду не достатньо, щоб дізнатись щось про ці браслети, але я впевнений, що принаймні один з них має допомогти. Віднеси їх в Даларан, нехай на них подивиться маг.\n\nВсе ж таки, я не можу покинути Грабіжна Бухта лише заради того, щоб поспілкуватися з тими нудними старими магами.\n\nНе те щоб я боявся, що хтось спробує зайняти моє місце і стати новим бароном. Ще ніхто не посмів встати на шляху у Ревілґаза і залишитись в живих.", ["en"] = "Water Elementals", ["tasks"] = { ["Water Elemental Bracers"] = "браслет водяного елементаля", ["Water Elemental Bracers (Provided)"] = "браслет водяного елементаля (видано)" } },
    [603] = { [1] = "Ключ Ансірема", [2] = "Маг, що володіє каменем, може збільшити його силу через певну точку фокуса... на кшталт вівтаря. Тобі потрібен предмет такої ж сили, щоб не знищити його.\n\nНа твоє щастя, я знаю, що тобі допоможе в цьому: стародавній кинджал, ще одна реліквія тролів. Але є одна маленька проблема.\n\nРіч у тому, що я знайшов кинджал під час досліджень у Тернистій долині, але віддав його своїй норовливій доньці Кателіні, яка втекла до Грабіжної Бухти, щоб стати піраткою.", [3] = "Поговоріть з Кателіною в Грабіжній Бухті.", [5] = "Мій кинджал? Ти що, жартуєш?\n\nЩо? Ти хочеш, щоб я повторила історію та перетворилася з найкращої майстрині ножового бою в Грабіжній Бухті на посміховисько серед піратів?\n\nЯ програла бій на ножах одному з піратів Кривавого Вітрила — а вони ще ті виродки! Він забрав мій клинок як трофей.\n\nНе думаю, що я зможу бути фехтувальницею завдяки одним лише образам та гострому язику...", ["en"] = "Ansirem's Key" },
    [6063] = { [1] = "Приборкання звіра", [2] = "Як {клас}, ти завжди маєш пам'ятати про відповідальність, що лежить на тобі. Природу не можна підкорити для виконання власних забаганок. Її потрібно поважати та приймати як те, без чого твоє існування неможливе.\n\n{ім'я:к}, ти маєш довести, що розумієш це до того, як я навчу тебе приручати звірів.\n\nДля свого першого завдання візьми цей жезл приборкання. З ним ти зможеш приручити павутиннолісого маскуна. Зроби це і попрактикуй свої навички {клас:р}.", [3] = "Приборкайте павутиннолісого маскуна за допомогою жезлу приборкання. Попрактикуйтесь, після чого поверніть жезл приборкання Дазалару в Доланаар.", [4] = "Ти навчишся, {ім'я:к}, і одного дня станеш {стать:великим:великою} {клас:о}.", [5] = "Чудово, {ім'я:к}! Ти швидко вчишся.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6064] = { [1] = "Приборкання звіра", [2] = "Вітаю, {стать:юначе:юнко}! То ти хоч дізнатись, як приручити собі супутника?\n\nЩо ж, почнім. Для мисливця немає нічого важливішого за спорядження. Та про мій новий шрапнельний самостріл поговоримо пізніше. Поки займемось тим, що тобі може бути цікавіше — вибором вірного звіра-супутника!\n\nНайкраще — спробувати приборкати кількох звірів і обрати того, хто сподобається більше. Тож, знайди великого скельного кнура та приборкай його з допомогою цього жезла.", [3] = "Приборкайте великого скельного кнура за допомогою жезлу приборкання. Попрактикуйтесь, після чого поверніть жезл приборкання Ґріфу Дикосерду в Харанос.", [4] = "Не переживай, {стать:юначе:юнко}! Може не з першого разу, та ти знайдеш свого вірного супутника.", [5] = "Знаю-знаю, тобі вже кортить дізнатись, що ж далі, еге ж?", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6071] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Дазаларом в Доланаарі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Дазаларом у Доланаарі.", [5] = "Так, прийшов час, {клас:к}.", ["en"] = "The Hunter's Path" },
    [6072] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Дазаларом в Доланаарі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Дазаларом у Доланаарі.", [5] = "Так, думаю, що час настав...", ["en"] = "The Hunter's Path" },
    [6073] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Дазаларом в Доланаарі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Дазаларом у Доланаарі.", [5] = "Так, прийшов час навчити тебе....", ["en"] = "The Hunter's Path" },
    [6074] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Ґріфом Дикосердом в Хараносі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Ґріфом Дикосердом в Хараносі.", [5] = "Так, я вважаю, що час настав...", ["en"] = "The Hunter's Path" },
    [6075] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Ґріфом Дикосердом в Хараносі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Ґріфом Дикосердом в Хараносі.", [5] = "Так, думаю, прийшов час навчати тебе....", ["en"] = "The Hunter's Path" },
    [6076] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Ґріфом Дикосердом в Хараносі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Ґріфом Дикосердом в Хараносі.", [5] = "Так, {клас:к}, час настав...", ["en"] = "The Hunter's Path" },
    [6084] = { [1] = "Приборкання звіра", [2] = "Ці скельні кнури досить кремезні. Може спробуєш щось граціозніше? Добренько, є й таке. На південь і на схід звідси ти знайдеш великих білих кішок, що звуться сніжними леопардами. Вони нагадують елегантно змайстровану рушницю — за їх зовнішньою красою ховається надзвичайна сила. Якщо ти шукаєш спритнішого звіра — вони підійдуть краще, ніж кнури.\n\nВізьми цей жезл приборкання і подивись, чи сподобається тобі сніжний леопард.", [3] = "Приборкайте сніжного леопарда за допомогою жезлу приборкання. Попрактикуйтесь, після чого поверніться до Ґріфа Дикосерда в Харанос.", [4] = "Ну, як тобі сніжні леопарди, {ім'я:к}?", [5] = "Коли ти будеш {стать:готовий:готова} — я навчу тебе приборкувати будь-яких звірів, які тобі сподобаються.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6086] = { [1] = "Тренування звіра", [2] = "{ім'я:к}, тепер ти вмієш приручати звірів, та ще тобі доведеться навчитись їх дресувати.\n\nВідправляйся до Залізогарту в Військовий зал. Там ти маєш поговорити з однією з наших найшанованіших мисливиць — Белією Громограніт. Вона навчить тебе, як дресувати твого нового супутника, тож поспіши, {стать:юначе:юнко}.\n\nБелія — приязна мисливиця, тож, думаю, ти швидко знайдеш з нею спільну мову. Нехай щастить, {ім'я:к}.", [3] = "Поговоріть з Белією Громограніт в Залізогарті.", [5] = "Ти {стать:новенький:новенька}, ге? Так, бачу, ти на шляху становлення {стать:великим:великою} {клас:о}.\n\nТак, я поділюсь з тобою знаннями, необхідними для дресування твого улюбленця. Ти навчишся не тільки навчати його нових здібностей, а й годувати та повертати до життя, коли знадобиться.\n\nПам'ятай, найкращий спосіб порозумітись з твоїм супутником — повага та піклування до нього. В обмін на це, ти отримаєш вірного друга.", ["en"] = "Training the Beast" },
    [61] = { [1] = "Вантаж на Штормовій", [2] = "Мій брат, Морган, чекає в Штормовії на мій вантаж зі свічками. У мене ж катастрофічно не вистачає часу, щоб самостійно здійснити поїздку, але якщо ти не проти доставити його самотужки, він добре заплатить.\n\nЯ гарненько запакував свічки, а Моргана ти знайдеш у нашій крамниці, \"Аптеці братів Товкачів\", у Торговому районі Штормовія.", [3] = "Доставте пакунок від Вільяма Морганові Товкачеві в Торговий район Штормовію.", [4] = "О, вантаж від мого брата? Чудово! Сьогодні справді мій щасливий день!", [5] = "Ось ваша платня... і поки ви ще тут, озирніться навколо! Я впевнений, у нас знайдеться зілля чи якась інша дрібничка, яка стане вам у пригоді.", ["en"] = "Shipment to Stormwind", ["tasks"] = { ["William's Shipment"] = "пакунок від Вільяма", ["William's Shipment (Provided)"] = "пакунок від Вільяма (видано)" } },
    [610] = { [1] = "\"Красунчик\" Дункан", [2] = "Тебе прислав мій БАТЬКО? Я думала, що цей старий вже махнув на мене рукою.\n\nВін не винен, що я втекла, просто він не очікував, що я не захочу жити нудним життям, читаючи затхлі книжки й спілкуючись з сивими, горбатими та нудними магами!\n\nЯкщо тобі потрібен мій кинджал, тобі доведеться забрати його у \"Красунчика\" Дункана, одного з піратів Кривавого Вітрила. Пригрози йому чим-небудь, і я впевнена, він віддасть його.", [3] = "Заберіть кинджал Кателіни у \"Красунчика\" Дункана.", [4] = "Мене ніколи раніше не перемагали, розумієш, {ім'я}? Звичайно, бувало таке, що мене ранили, без цього не обходиться жодна різанина, але він просто вдарив мене по голові і я втратила свідомість. Коли я прийшла до тями, кинджала вже не було.\n\nПо моєму прізвиську легко можна зрозуміти, щоб битися, мені потрібен кинджал і це має бути саме той кинджал.", [5] = "Ти {стать:переміг:перемогла} Дункана? Гадаю, ти не {стать:такий і простак:така і простачка}, як здавалося на перший погляд.\n\nНапевно, це означає, що мені не варто викликати тебе на бій найближчим часом!", ["en"] = "\"Pretty Boy\" Duncan", ["tasks"] = { ["Catelyn's Blade"] = "кинджал Кателіни", ["Catelyn's Blade (Provided)"] = "кинджал Кателіни (видано)" } },
    [6101] = { [1] = "Приборкання звіра", [2] = "Природа постійна у своїй мінливості, {ім'я:к}. Можна передбачити лише те, що вона ніколи не залишиться на місті. Вона постійно змінюється.\n\nМої завдання допоможуть тобі побачити й прийняти різноманітність створінь, які можуть стати твоїми супутниками.\n\nВізьми цей жезл приборкання та використай його, щоб приборкати одного з ночезубів-ловців, що мешкають на півдні. Так ти почнеш розуміти схожість та різноманітність природи.", [3] = "Приборкайте ночезуба-ловця за допомогою жезлу приборкання. Попрактикуйтесь, після чого поверніть жезл приборкання Дазалару в Доланаар.", [4] = "Розуміння й підтримка балансу з природою — невіддільна частина життя {стать:кожного:кожної} {раса:р}.", [5] = "Я бачу твою відданість і розуміння всього, чого я тебе навчаю, {ім'я:к}.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6102] = { [1] = "Приборкання звіра", [2] = "Тобі вдалось приборкати двох звірів, що живуть на суші та тепер настав час мешканців неба. Використай цей жезл, щоб приборкати сову-верескуна, що мешкає на захід звідси. Попрактикуйся з цією могутньою совою в бою.\n\nЯк повернешся — я навчу тебе приборкання звірів, щоб ти {стать:міг:могла} обрати собі супутника, який допоможе тобі в боротьбі з загрозами та отримуватиме разом з тобою досвід в бою. Також я навчу тебе, як викликати та відпускати його по твоїй волі.", [3] = "Приборкайте сову-верескуна за допомогою жезлу приборкання. Попрактикуйтесь, після чого поверніть жезл приборкання Дазалару в Доланаар.", [4] = "Я пишаюсь твоїми досягненнями, {ім'я:к}. Ти вже {стать:виконав:виконала} моє останнє завдання?", [5] = "Ти {стать:навчився:навчилась} всьому, що я міг тобі розказати, {ім'я:к}. Ще одна порада — обирай свого першого супутника розсудливо. Це буде створіння землі, води чи неба? Хай там як, без сумніву, воно буде супроводжувати тебе досить довго.\n\nОтож, {ім'я:к}, тепер я навчу тебе приборкання звіра, а також як викликати та відпускати його по своїй волі. Користуйся своїми навичками з гордістю, ти на це {стать:заслужив:заслужила}.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6103] = { [1] = "Тренування звіра", [2] = "Тепер ти вмієш приручати звірів, та ще тобі доведеться навчитись їх дресувати.\n\nВідправляйся до Дарнаса. Там ти поговориш з однією з наших найшанованіших мисливиць — Йокастою. Вона навчить тебе дресування, тож поспіши.\n\nХай Йокаста й здається суворою, вона завжди рада бачити нових мисливців. Поважай її, і вона віддячить тобі добром. Нехай щастить, {ім'я:к}.", [3] = "Поговоріть з Йокастою в Кенарійському Анклаві, що в Дарнасі.", [5] = "Бачу, ти {стать:юний:юна} {клас}. Так, я поділюсь з тобою знаннями, необхідними для дресування твого улюбленця. Ти навчишся не тільки навчати його нових здібностей, а й годувати та повертати до життя, коли знадобиться.\n\nПам'ятай, {ім'я:к}, ти маєш жити в рівновазі з природою та поважати її. Тепер йди. Ми побачимось знову, як прийде час.", ["en"] = "Training the Beast" },
    [611] = { [1] = "Прокляття припливів", [2] = "То ти шукаєш якийсь вівтар? Ну, я не експерт по руїнах тролів, як мій батько, але я чула про затонуле місто тролів біля острова, який ти шукаєш. Спробуй пошукати там.\n\nТи {стать:повернув:повернула} мені мій кинджал, тож, гадаю, ти можеш його позичити, але не забудь принести його назад, коли закінчиш!", [3] = "Знищте вівтар припливів за допомогою кинджала Кателіни, вбийте Ґазбана і принесіть камінь припливів та кинджал Кателіни барону Ревілґазу.", [4] = "Ти {стать:роздобув:роздобула} для мене камінь припливів, {ім'я}? Я вже знайшов для нього місце і придбав гарну підставку.", [5] = "Дивовижно! Камінь припливів! Він займе важливе місце в моїй колекції стародавніх артефактів тролів. Бачиш, виглядає так, ніби це і є застиглий приплив. Чарівно!", ["en"] = "The Curse of the Tides", ["tasks"] = { ["Catelyn's Blade"] = "кинджал Кателіни", ["Catelyn's Blade (Provided)"] = "кинджал Кателіни (видано)", ["Stone of the Tides"] = "камінь припливів", ["Stone of the Tides (Provided)"] = "камінь припливів (видано)" } },
    [6121] = { [1] = "Новий урок", [2] = "Тепер, {ім'я:к}, ти {стать:готовий:готова} більше дізнатися про отрути та про владу, яку ми, друїди, маємо над ними. Кенарій дарував нам вміння виводити з тіла найгірші отрути за допомогою простих чар. Цей дар не варто сприймати легковажно... Тож, для засвоєння цього, тобі доведеться впоратись з отрутою самостійно, своїми силами.\n\nВідправляйся на Місячну галявину і поговори з Дендритом Блиском Зірок — він очікує на твоє прибуття, щоб почати навчання.", [3] = "Відправляйтесь на Місячну галявину і поговоріть з Дендритом Зіркосяйвом в селищі Нічна Гавань.", [5] = "Вітаю, {стать:юний:юна} {клас:к}. Я радий бачити, що ти {стать:готовий:готова} і прагнеш дізнатись більше про зцілення від отрут.\n\nХоча більшість друїдів проходили певні випробування, тобі цього не знадобиться. В Аубердіні стався сплеск отруєння тварин і місцеві жителі не змогли з цим справитись. Представник Аубердіну попросив Місячну галявину про допомогу, тож ми відправимо тебе. Це не тренування — завдання серйозне і небезпечне, май це на увазі.", ["en"] = "Lessons Anew" },
    [6122] = { [1] = "Первісне джерело", [2] = "Скельноджерельні водоспади Темнобережжя служать основним джерелом води в цих землях, тож я підозрюю, що звідти й почалось розповсюдження отрути, від якої постраждали тамтешні звірі. Візьми цей флакон і наповни його водою біля входу до печери за водоспадом. Та будь {стать:обережний:обережна} — в печерах поселились наги.\n\nЯк наповниш — віднеси його Аланндаріан Нічній Пісні в Аубердін. Саме вона попросила нас про допомогу, тож ти відправишся їй на поміч.", [3] = "Використайте пустий флакон Скельноджерельних водоспадів, щоб взяти пробу води біля входу в печеру за водоспадом.\n\nВіднесіть наповнений флакон Скельноджерельних водоспадів Аланндаріан Нічній Пісні в Аубердін, що на Темнобережжі.", [4] = "Тебе прислало Кенарійське Коло з Місячної галявини? Це чудово! Нам не вистачає рук для допомоги нещасним оленям і ми будемо раді твоїй допомозі.\n\nТи {стать:приніс:принесла} зразок води, про який казав Дендрит Зіркосяйво? Він сказав, що ти принесеш воду і допоможеш нам зі зціленням...", [5] = "Клянусь Елуною, це просто мерзенна вода! Не дивно, що олені захворіли.\n\nЩось забруднює воду на скельноджерельних водоспадах і, як наслідок, вражає ґрунтові води всього Темнобережжя. Хворих оленів бачили всюди, а не тільки біля річок. Хоч вода і є первісним джерелом забруднення, тут щось не чисто.\n\nВір чи ні, та ця вода допоможе нам створити ліки. А поки я досліджуватиму воду, ти допоможеш мені зібрати інгредієнти для ліків...", ["en"] = "The Principal Source", ["tasks"] = { ["Filled Cliffspring Falls Sampler"] = "наповнений флакон Скельноджерельних водоспадів", ["Filled Cliffspring Falls Sampler (Provided)"] = "наповнений флакон Скельноджерельних водоспадів (видано)" } },
    [6123] = { [1] = "Створення ліків", [2] = "Основою цілющої мазі для оленів послужить вода. Для того, щоб надати їй цілющих властивостей, мені знадобиться землекорінь. Травники знають де його шукати, тому якщо тобі не пощастило і ти не {стать:один:одна} з них - доведеться знайти когось, хто допоможе.\n\nДля підсилення ефективності мазі, мені потрібні місячні гриби. Знайти їх досить легко: в печерах, на схід звідси, їх дуже багато. В цих печерах проживають місячні совухи; останнім часом вони стали дуже дратівливими, тому будь {стать:обережний:обережна}.", [3] = "Принесіть 5 землекоренів і 12 місячних грибів Аланндаріан Нічній Пісні в Аубердін, щоб вона приготувала цілющу мазь.", [4] = "Ти {стать:зібрав:зібрала} складники, необхідні для приготування мазі? Самі собою олені не зціляться, тому нам краще поспішити їм на поміч!", [5] = "Чудово, {ім'я:к}, ти {стать:приніс:принесла} так багато, що мені має вистачити на кілька великих доз мазі - принаймні, щоб зцілення почалось.\n\nПриготування засобів проти отрут інколи буває досить складним, оскільки кожен потребує певного антидота для нейтралізації дії отрути. Чудово було б вміти в будь-який момент лікувати отруєння, не переживаючи про інгредієнти для антидота.\n\nА зараз мені треба попрацювати над цим!", ["en"] = "Gathering the Cure", ["tasks"] = { ["Earthroot"] = "землекорінь", ["Earthroot (Provided)"] = "землекорінь (видано)", ["Lunar Fungus"] = "місячний гриб", ["Lunar Fungus (Provided)"] = "місячний гриб (видано)" } },
    [6125] = { [1] = "Влада над отрутою", [2] = "Ти {стать:засвоїв:засвоїла}, як це — зцілювати від отрути без допомоги духів. Пам'ятай, чого ця боротьба вартує іншим, коли прийматимеш цей дар влади над отрутою.\n\nПовертайся до Матренґіла Ведмелика в Дарнас, {ім'я:к}. Тепер, коли ти {стать:засвоїв:засвоїла} цей важливий урок, він навчить тебе важливого заклинання.\n\nНехай тобі щастить, {стать:юний:юна} {клас:к}. Ми зустрінемось знову.", [3] = "Поверніться до Матренґіла Ведмелика в Кенарійський Анклав, що в Дарнасі.", [5] = "З поверненням! Я слідкував за твоїми успіхами відколи ти {стать:покинув:покинула} нас і, зізнаюсь, я був вражений, коли дізнався про те, що сталося в Аубердіні. Ми маємо більше дізнатись про це — така отрута не залишиться непоміченою для балансу природи.\n\nТи чудово {стать:проявив:проявила} себе в цій ситуації. За це я винагороджу тебе владою над отрутою. Використовуй її мудро, {ім'я:к}.", ["en"] = "Power over Poison" },
    [6141] = { [1] = "Брат Антон", [2] = "До мого побратима по зброї, Антона, дійшли чутки про нашестя невмерлих у далекому Калімдорі, в землях, що звуться Спустошищем. Антон негайно подався туди, щоб знайти й знищити загрозу невмерлих!\n\nВін шукає хоробрих і рішучих супутників, які зможуть допомогти йому. Якщо твоє серце чисте, тобі потрібно поспілкуватися з Антоном. Він знаходиться в Спустошищі, в оплоті Найджела.", [3] = "Поговоріть з братом Антоном в Спустошищі.", [5] = "До мене дійшли чутки, що зі сходу прямує допомога. Чи це не про тебе йшлося? Ти {стать:прийшов:прийшла}, щоб допомогти Багряному Походу досягти його благородної мети?\n\nЯкщо так, то слухай уважно...", ["en"] = "Brother Anton" },
    [616] = { [1] = "Острів примар", [2] = "Барон Ревілґаз наказав мені прислухатися до чуток про дивні речі та місця в Грабіжній Бухті та Тернистій долині. Зазвичай я не дуже вірю історіям про примар, але в таверні підслухав, як моряки розповідали про острів з примарами неподалік узбережжя. Кажуть, там живуть водяні елементалі та божевільний дух гобліна.\n\nЯкщо ти зустрінешся з Ревілґазом, можеш розказати йому цю історію?", [3] = "Поговоріть з бароном Ревілґазом в Грабіжній Бухті.", [5] = "Цікаво. Колись, здається, я читав книгу, в якій йшлося про щось таке...\n\nА, точно, це була легенда тролів. Якщо Кронжек говорив правду, то незабаром я зможу додати камінь припливів до своєї колекції стародавніх артефактів і реліквій.", ["en"] = "The Haunted Isle" },
    [6181] = { [1] = "Квапливе повідомлення", [2] = "Хоча ми не отримуємо великої допомоги від Штормовію безпосередньо, я маю контакт у місті, який допомагає забезпечувати нас обладунками. Його звати Озрік Странґ. Його крамниця \"Обмежена невразливість\" - у Старому Місті Штормовія.\n\nНаші запаси обладунків закінчуються, і я повинен зв'язатися з Озріком, щоб попросити ще. Можеш передати йому цю записку?\n\nНайшвидше добратися до Штормовія — з допомогою Тора, нашого приборкувача грифонів. Він одразу вниз по схилу. Принеси йому мою записку, а потім візьми грифона до Штормовія.", [3] = "Принесіть записку Льюїса до приборкувача грифонів Тора.", [4] = "Схоже, ти поспішаєш. Що ж, тоді ти {стать:прийшов:прийшла} в правильне місце!", [5] = "Тобі треба доставити цю записку в Штормовій? Це не проблема, ти можеш взяти одного з моїх грифонів!", ["en"] = "A Swift Message", ["tasks"] = { ["Lewis' Note"] = "записка Льюїса", ["Lewis' Note (Provided)"] = "записка Льюїса (видано)" } },
    [6182] = { [1] = "Перший і останній", [2] = "Натанос Марріс був першою й останньою людиною-ватажком слідопитів. Він був учнем Сильвани Вітрогін, нині Королеви-Банші відречених.\n\nМи думали, що він загинув під час захисту Лордерону. Хоча його тіло так і не знайшли, вважалось, що він не зміг вибратись зі Східних Зачумлених земель.\n\nМатіас Гич вивчав обставини його зникнення і, можливо, має якусь нову інформацію. Відправляйся до нього, він проживає в казармах старого міста.", [3] = "Поговоріть з Матіасом Гичем в старому місті Штормовію. Він знаходиться в казармах.", [5] = "Після кількох повідомлень про незвичну активність відречених в Східних Зачумлених землях, агенти ШУР відправились на розслідування. І його результати викликають занепокоєння.", ["en"] = "The First and the Last" },
    [62] = { [1] = "Бездонна копальня", [2] = "Проблеми виникли не лише у шахті Північнокраю! В мене є свідчення, що Бездонна копальня в Ельвинні також стала притулком для кобольдів.\n\nДосліди шахту та перевір ці відомості, а потім повернися до мене. Шахта знаходиться майже на південь від Злотохрестя, між садибами Кам'янопільських і Маклурів.", [3] = "Дослідіть Бездонну копальню, а потім повертайтеся до маршала Дугана в Злотохрестя.", [4] = "Є про що доповісти, {ім'я:к}? Ти {стать:був:була} у Бездонній копальні?", [5] = "Кепські новини. Що далі, дракони?!? Нам доведеться посилити патрулювання біля цієї шахти. Дякую за твої зусилля, {ім'я:к}. Постривай... Схоже, я маю ще одне завдання для тебе.", ["en"] = "The Fargodeep Mine", ["tasks"] = { ["Scout through the Fargodeep Mine"] = "Дослідіть Бездонну копальню" } },
    [6261] = { [1] = "Дунґар Довгопий", [2] = "{Ім'я}, я зібрав у цей ящик усе, про що просив Льюїс. Зможеш відвезти ящик йому?\n\nЯкщо ти вже {стать:поспілкувався:поспілкувалася} з Тором в Західному краю, то можеш найняти грифона назад до нього. Довгопий — наш приборкувач грифонів у Торговому районі.\n\nПоговори з Дунґаром, а потім достав цей ящик Льюїсу якомога швидше. Ми не хочемо, щоб нашим бійцям у Західному краю довелося битися без нових обладунків!", [3] = "Віднесіть ящик Озріка до приборкувача грифонів Дунґара Довгопия.", [4] = "Це в тебе піт на лобі, {стать:юначе:юнко}? Ти забагато {стать:бігав:бігала}. Наступного разу візьми грифона!", [5] = "Ящик для Західного краю, так? А ти там уже {стать:бував:бувала} раніше? Якщо так, то ніяких проблем, друзяко. У мене є безліч грифонів, навчених літати по цьому маршруту!", ["en"] = "Dungar Longdrink", ["tasks"] = { ["Osric's Crate"] = "ящик Озріка", ["Osric's Crate (Provided)"] = "ящик Озріка (видано)" } },
    [627] = { [1] = "Послуга для Кронжека", [2] = "В ущелині Суховусих, далеко на півночі височини Араті, є печера. У цій печері є рідкісна руда — кривавий камінь. Це каміння у печері не найвищої якості, але навіть низькоякісний кривавий камінь високо ціниться тими, хто знає, як його використовувати.\n\nА я знаю.\n\nЯ полагоджу твій горщик, але поки я працюю над ним, принеси мені зразки кривавого каменю. Якщо принесеш достатньо, я заплачу тобі.\n\nА якщо ти не вмієш його добувати... знайди того, хто вміє!", [3] = "Принесіть 4 партії малої руди кривавого каменю Кронжеку в Грабіжну Бухту.", [4] = "Привіт, {ім'я}. Тобі вдалось добути кривавий камінь?", [5] = "Чудово! Ти {стать:зробив:зробила} велику послугу для мене.\n\nОсь твоя оплата...", ["en"] = "Favor for Krazek", ["tasks"] = { ["Lesser Bloodstone Ore"] = "мала руда кривавого каменю", ["Lesser Bloodstone Ore (Provided)"] = "мала руда кривавого каменю (видано)" } },
    [6281] = { [1] = "Переліт до Штормовія", [2] = "За невелику плату ти можеш найняти грифона для польоту до Штормовія, щоб доставити записку Льюїса Озрікові. Ти не дістанешся туди швидше жодним іншим способом.\n\nЯкщо для тебе це прийнятно, поговори зі мною знову, коли будеш {стать:готовий:готова} летіти. Я, звичайно, візьму з тебе трохи грошей, але повір — воно того варте!", [3] = "Оплатіть політ приборкувачу грифонів Торові та принесіть записку Льюїса Осрікові Странґу в крамницю \"Обмежена невразливість\", що у Старому Місті Штормовія.", [4] = "Ти {стать:подорожував:подорожувала}, еге ж? {стать:Бував:Бувала} у якихось цікавих місцях?", [5] = "А, записка від квартирмейстера Льюїса? Я не здивований, що йому знадобилася додаткова екіпіровка. Сторожовий пагорб — далеко, у краю, про який Штормовій вже майже забув.\n\nЩо ж, дякую тобі, {ім'я}. Ось трохи грошей на покриття твоїх витрат на дорогу.", ["en"] = "Continue to Stormwind", ["tasks"] = { ["Lewis' Note"] = "записка Льюїса", ["Lewis' Note (Provided)"] = "записка Льюїса (видано)" } },
    [6285] = { [1] = "Повернення до Льюїса", [2] = "Приборкувачем грифонів у Західному краї працює Тор. Якщо ти вже з ним {стать:знайомий:знайома}, то можеш долетіти до нього на одній з моїх пташок.\n\nВарто знати: грифони навчені так, що завжди можуть долетіти до столиці, але вони відвезуть тебе до приборкувачів з інших місць лише після того, як ти там побуваєш.\n\nТи вже {стать:бував:бувала} у Тора, тож просто поговори зі мною ще раз, коли будеш {стать:готовий:готова} летіти до Західного краю. А там зможеш доставити ящик Озріка квартирмейстерові Льюїсу.", [3] = "Оплатіть політ до Сторожового пагорба приборкувачу грифонів Дунґарові Довгопию, а потім віднесіть ящик Озріка Льюїсові.", [4] = "Ти вже {стать:повернувся:повернуляся} зі Штормовія? Озрік надіслав обладунки?", [5] = "Чудово, ти {стать:привіз:привезла} обладунки! Ми розподілимо їх між тими, кому вони терміново необхідні.\n\nДякую тобі, {ім'я}. Ти нам дуже {стать:допоміг:допомогла}. А тепер, коли ти {стать:знайомий:знайома} з нашими грифонами, сподіваюся, ти будеш часто прилітати до нас і надавати свою допомогу Сторожовому пагорбові!", ["en"] = "Return to Lewis", ["tasks"] = { ["Osric's Crate"] = "ящик Озріка", ["Osric's Crate (Provided)"] = "ящик Озріка (видано)" } },
    [6341] = { [1] = "Дари Тельдрассіля", [2] = "Рибалки селища Рут'Теран живуть дуже добре, бо риба тут надзвичайно велика, і її багато. Я хотіла б порівняти тутешній улов із ситуацією в материкових водах.\n\nЯ зібрала зразки риб'ячих кісток і луски, які хотіла б відправити своєму колезі на Темнобережжя. Його звати Лейрд, він продає рибу в Аубердіні.\n\nВіднеси мою колекцію зразків нашому приборкувачу гіпогрифів, Веспристу, і поговори з ним щодо польоту до Аубердіна.", [3] = "Віднесіть колекцію Несси до Весприста.", [4] = "Чим я можу допомогти? Тобі потрібен транспорт?", [5] = "А, то ти хочеш доставити це в Аубердін? Добре...", ["en"] = "The Bounty of Teldrassil", ["tasks"] = { ["Nessa's Collection"] = "колекція Несси", ["Nessa's Collection (Provided)"] = "колекція Несси (видано)" } },
    [6342] = { [1] = "Переліт до Аубердіна", [2] = "З селища Рут'Теран до Аубердіна можна дістатися двома способами: кораблем і гіпогрифом. Обидва способи швидкі та надійні, але якщо ти ще не {стать:літав:літала} в Аубердін на гіпогрифі — раджу спробувати.\n\nРаджу тобі розмовляти з приборкувачами гіпогрифів, як матимеш змогу. Після цього ти зможеш прилетіти до них з інших місць.\n\nОсь колекція Несси. Поговори зі мною знову, як будеш {стать:готовий:готова} летіти в Аубердін, щоб доставити Лейрду колекцію Несси.", [3] = "Летіть гіпогрифом приборкувача Веспріста до Аубердіна, після чого віддайте Лейрду колекцію Несси.", [4] = "Ти {стать:прибув:прибула} з Тельдрассіля? Розкажи, як там ловиться риба?", [5] = "Посилка від Несси? Дякую, {ім'я}! Вона казала, що надішле мені зразки риби, виловленої біля селища Рут'Теран. Вона вважає, що вони можуть сильно відрізнятися від тієї риби, що ловиться тут...\n\nОго! Ця щелепна кістка майже вдвічі більша, ніж у тутешніх риб. А ця луска завбільшки з кулак! Неймовірно!", ["en"] = "Flight to Auberdine", ["tasks"] = { ["Nessa's Collection"] = "колекція Несси", ["Nessa's Collection (Provided)"] = "колекція Несси (видано)" } },
    [6343] = { [1] = "Повернення до Несси", [2] = "Я маю відправити відповідь Нессі. Їй буде дуже цікаво знати, наскільки тутешня риба відрізняється від тієї, що водиться біля берегів Тельдрассіля. Ми можемо лише здогадуватися про причини, але я підозрюю, що саме Світове Дерево так впливає на природу навколо нього!\n\nБудь ласка, передай мою відповідь Нессі. Якщо хочеш летіти до Рут'терану на гіпогрифі — поговори з приборкувачкою гіпогрифів Кейліс Перомісяць. А якщо хочеш скористатись кораблем — він регулярно відходить від причалу, що на північний захід звідси.", [3] = "Віднесіть Нессі Пісні Тіней відповідь Лейрда.", [4] = "{ім'я}, ти {стать:повернувся:повернулась} з Аубердіна? {стать:Розмовляв:Розмовляла} з Лейрдом?", [5] = "Це дуже цікаво. Риба тут велика, але я не думала, що вона настільки відрізняється від риби на материку. Мабуть, на це є якась причина...\n\nЩо ж, дякую тобі, {ім'я}. Я поговорю про це з місцевими. Можливо, колись ми знайдемо причину цього дива. Але до тих пір ми будемо пожинати його плоди!", ["en"] = "Return to Nessa", ["tasks"] = { ["Laird's Response"] = "відповідь Лейрда", ["Laird's Response (Provided)"] = "відповідь Лейрда (видано)" } },
    [6344] = { [1] = "Несса Пісня Тіней", [2] = "Моя подруга, Несса Пісня Тіней, торгує рибальськими припасами в селищі Рут'Теран. Їй потрібно доставити посилку на Темнобережжя, і вона шукає когось, хто міг би їй допомогти.\n\nЯкщо хочеш допомогти Нессі — йди до селища Рут'Теран через портал в Дарнасі. Ти знайдеш його на заході від Прихрамових садів.", [3] = "Поговоріть з Нессою Піснею Тіней.", [5] = "Так, мені потрібен кур'єр, що доставить пакунок на Темнобережжя. Допоможеш мені?", ["en"] = "Nessa Shadowsong" },
    [637] = { [1] = "Лист Саллі Баллу", [2] = "Промоклий та порваний конверт миттю розчиняється і в руках залишається лист, написаний з особливою старанністю.\n\nВін адресований місіс Сарі Баллу в Залізогарт і починається зі слів \"Моя люба Сара...\"", [3] = "Доставте Сарі Баллу лист Саллі Баллу.", [4] = "Схоже, у твоєму житті було чимало мандрівок і важких битв, {клас:к}. Так, лихі настали часи. Яку звістку ти {стать:приніс:принесла} мені?", [5] = "Ти {стать:бачив:бачила} мого Саллі, затиснутого глибоко під крижаними водами? Прошу, скажи, що це неправда!\n\nДай я прочитаю, що він написав...", ["en"] = "Sully Balloo's Letter", ["tasks"] = { ["Sully Balloo's Letter"] = "лист Саллі Баллу", ["Sully Balloo's Letter (Provided)"] = "лист Саллі Баллу (видано)" } },
    [6387] = { [1] = "Винагорода для учнів", [2] = "До мене приходить багато молодих дворфів, що прагнуть навчитись гірництву. А без чого не обійдеться жоден гірник? Без кирки!\n\nВ мене є список студентів, що відмінно показали себе у навчанні і заслужили почесну кирку. Віднеси його Ґолніру Камнепалому в Залізогарт. Він підготує кирки.\n\nНайшвидше дістатись Залізогарта - на грифоні, тож йди з цим списком до приборкувача грифонів, Торґрума Боррельсона, і поговори з ним щодо польоту в Залізогарт.", [3] = "Віднесіть список Брока Торґруму Боррельсону в Телсамар.", [4] = "Тобі так швидко набрид Телсамар? Вже готовий летіти в інше місто?", [5] = "Тобі потрібно доправити це в Залізогарт, еге ж? За невелику плату я посаджу тебе на одного з моїх грифонів і він віднесе тебе прямо туди. Ну, що скажеш?", ["en"] = "Honor Students", ["tasks"] = { ["Bring Brock's List to Thorgrum Borrelson in Thelsamar."] = "Віднесіть список Брока Торґруму Боррельсону в Телсамар.", ["Brock's List"] = "список Брока", ["Brock's List (Provided)"] = "список Брока (видано)" } },
    [6388] = { [1] = "Ґріт Турден", [2] = "Ось почесні кирки для учнів Брока. Якщо ти вже {стать:був:була} в Телсамарі, можеш полетіти назад на грифоні.\n\nВіднеси кирки приборкувачу грифонів, Ґріту Турдену, і поговори з ним щодо польоту в Телсамар.", [3] = "Віднесіть почесні кирки Ґріту Турдену в Залізогарт.", [4] = "Схоже, ти кудись {стать:зібрався:зібралась} летіти. Хочеш взяти мого грифона?", [5] = "Тобі треба доставити це в Телсамар, га? Не проблема. Якщо ти там вже {стать:був:була} та {стать:говорив:говорила} з Торґуном Боррельсоном, можеш долетіти до нього на одному з моїх грифонів.", ["en"] = "Gryth Thurden", ["tasks"] = { ["Bring the Honorary Picks to Gryth Thurden in Ironforge."] = "Віднесіть почесні кирки Ґріту Турдену в Залізогарт.", ["Honorary Picks"] = "почесні кирки", ["Honorary Picks (Provided)"] = "почесні кирки (видано)" } },
    [6391] = { [1] = "Політ до Залізогарту", [2] = "Всього за кілька монет один з моїх грифонів віднесе тебе до Залізогарту. Там ти віддаси список Брока Ґолніру Камнепалому. Ти знайдеш його в гільдії гірництва Гірської Безодні. Це в районі Великої Кузні, в якому тебе і висадить мій грифон.\n\nПоговори зі мною, як будеш {стать:готовий:готова} відправитись.", [3] = "Заплатіть приборкувачу грифонів Торґруму Боррельсону за грифона до Залізогарту, де віддайте список Брока Ґолніру Камнепалому.", [4] = "Чим я можу вам допомогти, {стать:пане:пані}?", [5] = "А, новий список відмінників Брока. У мене якраз є партія кирок, яку можна відправляти. Зараз тільки виріжу імена учнів...", ["en"] = "Ride to Ironforge", ["tasks"] = { ["Brock's List"] = "список Брока", ["Brock's List (Provided)"] = "список Брока (видано)", ["Buy a gryphon to Ironforge from the gryphon master Thorgrum Borrelson, then bring Brock's List to Golnir Bouldertoe in Ironforge."] = "Придбайте у приборкувача грифонів Торґрума Боррельсона переліт до Залізогарта, а потім віднесіть список Брока Ґолніру Камнепалому." } },
    [6392] = { [1] = "Повернення до Брока", [2] = "За невелику плату ти можеш найняти одного з моїх грифонів, щоб долетіти до Телсамару... якщо ти, звісно, там вже {стать:був:була}. Грифони літають тільки до місць, які ти вже {стать:відвідав:відвідала}, то не забувай говорити з кожний зустрічним приборкувачем грифонів, щоб мати змогу повернутися туди пізніше.\n\nТи вже {стать:бачився:бачилась} з Торґрумом, приборкувачем грифонів Телсамару, отже можеш повернутись до нього. Як опинишся в Телсамарі, віддай кирки Броку Камнекопу.\n\nПоговори зі мною, як будеш {стать:готовий:готова} відправитись.", [3] = "Заплатіть приборкувачу грифонів Ґріту Турдену за грифона до Телсамару, де віддайте почесні кирки Броку Камнекопу.", [4] = "О, {ім'я}. Ти вже {стать:повернувся:повернулась} із Залізогарту?", [5] = "Ти {стать:приніс:принесла} кирки. Чудово! Я нагороджу ними своїх учнів. Впевнений, їм не терпиться випробувати їх на родовищах Лох-Модану.\n\nДякую за допомогу, {ім'я}. Я твій боржник. Сподіваюсь, ці гроші хоча б покриють витрати на дорогу.", ["en"] = "Return to Brock", ["tasks"] = { ["Buy a gryphon to Thelsamar from the gryphon master Gryth Thurden, then bring the Honorary Picks to Brock Stoneseeker in Thelsamar."] = "Придбайте у приборкувача грифонів Ґріта Турдена переліт до Телсамару, а потім віднесіть почесні кирки Броку Камнекопу.", ["Honorary Picks"] = "почесні кирки", ["Honorary Picks (Provided)"] = "почесні кирки (видано)" } },
    [64] = { [1] = "Забута спадщина", [2] = "Це було жахливо! Верна розбудила мене, коли почула гамір на полях. Там було повно хуліганів. Ми побігли в поспіху, і я забув взяти з собою кишеньковий годинник. Вернин тато подарував мені цей годинник в день нашого весілля, і мене просто нудить від думки, що ним могли заволодіти ті злодії. Я залишив годинник у шафі на фермі. Шукай гарбузове поле на захід звідси — ти його не пропустиш. Якщо повернеш мені мій годинник, я буду дуже вдячний!", [3] = "Фермер Хмуробров хоче, щоб ви забрали його кишеньковий годинник з шафи його будинку на гарбузовій фермі на заході.", [4] = "Гадаю, тобі так і не вдалося дістати мій годинник?", [5] = "Мій годинник! Красно дякую, {стать:добрий пане:добра пані}!\n\nМи лише бідні фермери, що втратили свою землю, але, будь ласка, прийми цю нагороду на знак нашої вдячності.", ["en"] = "The Forgotten Heirloom", ["tasks"] = { ["Furlbrow's Pocket Watch"] = "кишеньковий годинник Хмуроброва", ["Furlbrow's Pocket Watch (Provided)"] = "кишеньковий годинник Хмуроброва (видано)" } },
    [65] = { [1] = "Братство Непокірних", [2] = "Група покидьків, відповідальних за те, що чесні люди залишають Західний край, зве себе Братством Непокірних. Мені потрібно, щоб ти {стать:проник:проникла} в цю зграю злочинців. Нам потрібно дізнатися, хто їхній ватажок і де вони ховаються. У Приозер'ї, в таверні, мешкає пройдисвіт Вайлі, який переді мною в боргу.\n\nВирушай до Приозер'я, що в Багрянокряжових горах, на схід від Ельвинна, і довідайся про все, що зможеш.", [3] = "Ґріан Міцнокрив хоче, щоб ви поговорили з Вайлі в Приозер'ї.", [5] = "Отже, тебе послав Міцнокрив? Що ж, я перед ним в боргу.", ["en"] = "The Defias Brotherhood" },
    [653] = { [1] = "Союзники Мізраель", [2] = "<Мізраель говорить.>\n\nВільна! Я ВІЛЬНА! Тепер я можу вільно набиратися сил, сховавшись від моїх поневолювачів. Бо якби я постала перед ними зараз, вони б перемогли мене і знову ув'язнили.\n\nАле прийде час, я зустрінусь з ними й вони пошкодують, що забрали в мене свободу!\n\nТи {стать:благородний союзник:благородна союзниця}, {ім'я}. Мені скоро знову знадобиться твоя допомога. Коли я буду готова, ти викличеш мене на поверхню.\n\nПоговори з Ґерріґом Кісткохватом. Ти знайдеш його в Залізогарті, в Закинутій Печері. Він знає, як мене викликати.", [3] = "Поговоріть з Ґерріґом Кісткохватом в Закинутій Печері, що в Залізогарті.", [5] = "Пані сповістила мене про твій прихід, {клас:к}. Вітаю у моїй оселі — як і ти, я готовий служити вищій меті.", ["en"] = "Myzrael's Allies" },
    [65602] = { [1] = "Що є кохання?", [2] = "Щоб спокусити інкуба, тобі знадобиться потужний об'єкт, що уособлює велику відданість і любов. За допомогою своїх видінь я знайшов маленьку статуетку, яка має підійти для ритуалу. Тисячі років тому вона належала молодій парі. Первісних власників більше немає, але їхня пам'ятка збереглася до наших днів. Прямуй дорогою на північ до Ясенедолу, потім на захід повз заставу Маєстри. Ти побачиш будинок, захований серед дерев. Там ти й знайдеш те, що шукаєш.", [3] = "Знайдіть дерев'яну статуетку в Ясенедолі та принесіть її Ґакіну Темнопряду у квартал Магів Штормовію.", [4] = "Ти {стать:повернувся:повернулася}. Зі статуеткою, я так розумію?", [5] = "<Ґакін вертить дерев'яну статуетку в руці.>\n\nЯ відчуваю енергію емоцій, що міститься в цьому артефакті та не згасла з часом. Інкуб потягнеться до неї, як муха до меду.\n\nТакар ніколи не розчаровує.", ["en"] = "What Is Love?", ["tasks"] = { ["Wooden Figurine"] = "дерев'яна статуетка" } },
    [65603] = { [1] = "Зв'язування", [2] = "Час настав. Візьми статуетку і спускайся в підземелля внизу. Там вже підготовлене коло виклику, в центр якого ти маєш помістити статуетку. Тоді прохід відкриється, і інкуб прийде в наш світ. Та навіть не думай недооцінювати сайаада. Демон без вагань нападе, коли зрозуміє твою хитрість. Ти маєш використати все, чого тебе навчили, щоб перемогти його. Якщо тобі це вдасться, повертайся до мене, і я зв'яжу його з твоєю волею. Зазнаєш поразки — і втратиш свою душу.", [3] = "За допомогою дерев'яної статуетки підкоріть інкуба, а потім поверніть статуетку Ґакіну Темнопряду в підвал таверни \"Зарізане ягня\".", [4] = "Інкуб намагатиметься приспати твою пильність за допомогою спокуси та обману. Демон вправний у впливі на серця смертних.\n\nПам'ятай, що все, що він може тобі запропонувати — фальшивка. Для демона ти — лише здобич.", [5] = "Непогано, {ім'я}. Ти {стать:переміг:перемогла} демона, і твоя воля залишилась незламною.\n\nБагато чорнокнижників вважали себе достатньо сильними, щоб підкорити сайаада, але натомість стали його жертвами. Я радий бачити, що ти не {стать:такий дурний:така дурна}.\n\nСпостерігай уважно, і я навчу тебе заклинанню, за допомогою якого ти зможеш викликати свого підкореного інкуба.", ["en"] = "The Binding", ["tasks"] = { ["Summoned Incubus slain"] = "викликаний інкуб: убито", ["Wooden Figurine"] = "дерев'яна статуетка", ["Wooden Figurine (Provided)"] = "дерев'яна статуетка (видано)" } },
    [657] = { [1] = "Сліди нової чуми?", [2] = "<Кві переглядає теку.>\n\nЦе дійсно цікаво. Схоже, аптекар Джорелл працював над смертельно небезпечними експериментами тут, на фермі Ґо'Шек. Не знаю, яке це має відношення до Гіллзбраду, але Фіну не сподобається, якщо ми проігноруємо це.\n\nПоки тебе не було, ми зіткнулися з орками, і я не в тій формі, щоб допомагати Кінелорі. Якщо ти не проти, їй знадобиться захист, коли вона піде на ферму, щоб викрасти результати досліджень, які Джорелл ще не відправив до Тарренського Млина.", [3] = "Поговоріть з Кінелорі.", [5] = "Якщо це заспокоїть Фіна, я особисто знищу кожного з відречених. Він так багато зробив для нас після чуми. Ми ніколи не думали, що знову знайдемо друзів чи родину.\n\nКоли будеш {стать:готовий:готова}, дай мені знати. Ми негайно вирушимо в дорогу.", ["en"] = "Hints of a New Plague?" },
    [658] = { [1] = "Сліди нової чуми?", [2] = "То Фін прислав тебе перевірити, як ми? Я не здивована — він занадто багато хвилюється.\n\nМи спостерігаємо за фермою вже багато днів, і Кін запевняє, що нещодавно бачила кур'єрку, яка виходила з того маленького будиночка на півдні.\n\nВона любить поговорити, але я завжди довіряю її відчуттям, коли ми буваємо в небезпечних місцях.\n\nТи, випадково, не слідопит? Ми думаємо, що кур'єрка може нести повідослення до Тарренського Млина. Якби ми змогли дістати ці документи, це б пролило світло на те, що відбувається в Гіллзбраді.", [3] = "Знайдіть відречену-кур'єрку і принесіть її запечатану теку до Кві поблизу ферми Ґо'Шек.", [4] = "Ми вдячні тобі за допомогу в пошуках цієї кур'єрки, {ім'я}.\n\nПоки тебе не було, Кін бачила аптекаря, який виходив з того ж будинку на півдні. Я впевнена, що вони замишляють щось лихе — мені просто потрібні докази, перш ніж ми підемо і зробимо щось необачне.\n\nТобі вже вдалось знайти кур'єрку?", [5] = "Чудово!\n\nПодивімось, про що тут йдеться...", ["en"] = "Hints of a New Plague?", ["tasks"] = { ["Sealed Folder"] = "запечатана тека", ["Sealed Folder (Provided)"] = "запечатана тека (видано)" } },
    [659] = { [1] = "Сліди нової чуми?", [2] = "Вітаю, {ім'я}. Я очолюю групу шукачів пригод, які розслідують дивні події в цій місцевості.\n\nМій двоюрідний брат у Гіллзбраді нещодавно довелося приспати свого пса Стенлі, бо тварина містичним чином виросла до величезних розмірів і стала кидатися на всіх, хто до неї наближався.\n\nЯ вважаю, що до цього причетні невмерлі, і ми шукаємо докази.\n\nДві мої супутниці, Кві та Кінелорі, вирушили на ферму Ґо'Шек на височині Араті та не виходили на зв'язок вже кілька днів. Знайдеш їх для мене? Я починаю хвилюватися.", [3] = "Знайдіть Кві та Кінелорі біля ферми Ґо'Шек на височині Араті.", [5] = "Постарайся бути якомога {стать:непомітнішим, мандрівнику:непомітнішою, мандрівнице}.\n\nОрки не люблять, коли за ними шпигують, а на цій фермі їх більше, ніж здається на перший погляд.", ["en"] = "Hints of a New Plague?" },
    [66] = { [1] = "Легенда про Сталвана", [2] = "Минулої ночі по моїх жилах прокотилася жахлива тривога... Я відчула, що моя онука Аліса перебуває у великій небезпеці. Я розклала карти... і зі столу на мене глянула смерть.\n\nПісля довгої подорожі крізь темний транс я розкрила цю жахливу таємницю. До мене прийшло ім'я: Сталван.\n\nЗнайди писаря в ратуші та намагайся більше дізнатися про цього персонажа. Я боюсь за нас усіх.", [3] = "Знайдіть писаря Долтрі в ратуші Темнодолу.", [5] = "То тебе прислала мадам Єва...", ["en"] = "The Legend of Stalvan" },
    [660] = { [1] = "Сліди нової чуми?", [2] = "Гаразд, {ім'я}. Я готова, якщо ти {стать:готовий:готова}.\n\nПочнемо?", [3] = "Захищайте Кінелорі, поки вона не повернеться до Кві.", [4] = "Час для розмов минув. Захисти Кінелорі, якщо тобі не байдужі мешканці Гіллзбраду.", [5] = "Ти {стать:зробив:зробила} для нас велику послугу, {ім'я}. Дякую.\n\nСподіваюся, Кін не завдала багато клопоту. Вона дуже доброзичлива, але може бути й смертельно небезпечною, коли ти її ворог.", ["en"] = "Hints of a New Plague?", ["tasks"] = { ["Protect Kinelory"] = "Захистіть Кінелорію" } },
    [6609] = { [1] = "Я вже ніц не зможу тобі дати!", [2] = "Трясця, я ж дворф! Я не створений для риболовлі! Глянь на мене — я ж практично зроблений з каменю!\n\nЯ вже ніц не зможу тобі дати — я навчив тебе всього, що знаю!\n\nЧи ти не розумієш? Гаразд. У мене є старий товариш в Калімдорі, який мо' тобі допомогти. Його звати Нет Пеґл, файний хлопець. Шукай його на островах на південь від Терамору. Ну все, йди!", [3] = "Вирушайте на Калімдор, до прибережного міста Терамор. На південь від нього знайдіть острів, на якому на вас чекає Нет Пеґл.", [5] = "На моєму острові завжди знайдеться місце для гостей... Напевно...", ["en"] = "I Got Nothin' Left!" },
    [661] = { [1] = "Сліди нової чуми?", [2] = "Кінелорі виглядала значно гірше після нічної гулянки в таверні, ніж зараз. Схоже, ти добре її {стать:захистив:захистила}.\n\nЦі речі, які вона принесла з ферми, принаймні дадуть Фіну уявлення про те, що відбувається в Араті. Щоб переконатися, що після вашого нападу не буде удару у відповідь, ми залишимося тут ще на деякий час. Ти не {стать:хотів би:хотіла б} повернутися до Південнобережжя і поговорити з Фіном?", [3] = "Знайдіть Фіна Оделіка у Південнобережжі.", [5] = "Отже, з цими двома бешкетницями все гаразд? Ха-ха, радий це чути. Дякую, що {стать:повідомив:повідомила} мені про їхнє місцеперебування та стан — мені дуже приємно, що вони живі. Вони незамінні подруги та супутниці в подорожах.\n\nАле... набагато важливіша моя вдячність за твою допомогу. Ось, візьми. Візьми це разом із подякою від усієї нашої групи.\n\nЯкщо пощастить, ми з'ясуємо, що задумали відречені, і покладемо цьому край.", ["en"] = "Hints of a New Plague?" },
    [6612] = { [1] = "Я знаю декого...", [2] = "Я бачу по твому кухарському приладдю, що ти знаєш, що робиш. Та от я вже ніц не можу тебе навчити.\n\nАле тобі пощастило, я знаю декого. Він гоблін і, певно, майкращий кухар Калімдору.\n\nТак, а се погані новини, {стать:хлопче:дівчинко} — ти маєш відправитиси до Калімдору. Йди в Пристроблях і знайди Могиля Хуткоріза. Він тобі все пояснит.", [3] = "Прямуйте до Пристробляху в пустелю Танаріс і поговоріть з Могилем Хуткорізом про розвиток вашої кулінарної кар'єри.", [5] = "<Могиль випльовує шматок шкіри.>\n\nТьфу...\n\n<Могиль голосно кашляє.>\n\nЩо? Взагалі-то, у шкірі напрочуд багато білків і мало вуглеводів, {раса:к}.", ["en"] = "I Know A Guy..." },
    [6624] = { [1] = "Перев'язка", [2] = "Добрий день, {стать:лікарю:лікарко}. Сьогодні ти пройдеш випробування на здатність відповідно перев'язувати пацієнтів. Якщо ти успішно пройдеш цей іспит, то приєднаєшся до лав травматологів Альянсу.\n\nТепер слухай уважно! Спочатку необхідно надати допомогу смертельно пораненим пацієнтам. Після них — тим, хто має важкі травми. Останніми йдуть легкопоранені. Тобі необхідно врятувати 15 пацієнтів, щоб пройти цей іспит. Якщо 6 з твоїх пацієнтів помруть, іспит вважатиметься проваленим.\n\nНехай щастить, {стать:лікарю:лікарко}.", [3] = "Врятуйте пацієнтів, використовуючи для перев'язки їхніх ран перев'язувальні бинти. Вам потрібно врятувати 15 пацієнтів, перш ніж 6 з них помруть від отриманих травм.\n\nПам'ятайте про порядок надання допомоги! Смертельно поранені солдати помирають найшвидше, а після них ті, хто має тяжкі рани. Легкопоранені солдати можуть прожити довше, тому їм треба надавати допомогу ПІСЛЯ того, як ви перев'яжете смертельно та важко поранених солдат.", [4] = "Чудесна робота, {стать:лікарю:лікарко}. Просто диво.", [5] = "{стать:Лікар:Лікарка} {ім'я}, вітаю в лавах травматологів Альянсу.", ["en"] = "Triage", ["tasks"] = { ["15 Patients Saved!"] = "15 пацієнтів врятовано!" } },
    [6625] = { [1] = "Травматолог Альянсу", [2] = "{стать:Лікар:Лікарка} {ім'я}, я так розумію. Рада тебе бачити.\n\nУ мене для тебе чудові новини! Ґустав ван Хаузен, головний травматолог Альянсу, особисто попросив тебе поговорити з ним в Тераморі. Це може бути можливість всього життя! Я б все віддала за можливість навчатися у великого лікаря, Ґустава ван Хаузена! Не змарнуй цю можливість, {стать:лікарю:лікарко}!", [3] = "Відвідайте Терамор в Бруднолипкій трясовині та поговоріть з лікарем Ґуставом ван Хаузеном про вступ до лав травматологів Альянсу.", [5] = "Чудово. Одягай скраби, ми починаємо негайно!", ["en"] = "Alliance Trauma" },
    [6661] = { [1] = "Збір підземних щурів", [2] = "Е, стій, {стать:моряк:морячко}! А-р-р... Хочеш попрацювати? У нас тут проблема зі щурами і нам на палубі не хватає рук.\n\nШо кажеш? Тобі просто треба взяти сю флейту і пограти цім шкідникам. Вони йтимуть за тобою в саме пекло!\n\nПіймай п'ятьох цих засранців і приведи до мене. Мені вони треба живі.\n\nА-р-р...", [3] = "Піймайте 5 підземних щурів за допомогою флейти щуролова. Приведіть щурів до Монті. Не забудьте повернути йому флейту.", [4] = "А-р-р... Шо ти, обдерля, чого так довго?", [5] = "Так, ці пойдуть. Мойому братку Ніпсі вони треба бадьорі й жваві. Ти ж не хочеш їсти прокислий шашлик зі щурятини?", ["en"] = "Deeprun Rat Roundup", ["tasks"] = { ["Rat Catcher's Flute"] = "флейта щуролова", ["Rat Catcher's Flute (Provided)"] = "флейта щуролова (видано)", ["Rats Captured"] = "Спіймані щури", ["Rats Captured (Provided)"] = "Спіймані щури (видано)", ["Rats Captured slain"] = "Спіймані щури: убито" } },
    [6662] = { [1] = "Мій братко, Ніпсі", [2] = "Мій братко, Ніпсі, готує чудовий шашлик зі щурятини в іншому кінці Глибокобіжного трамвая. Відвези йому цю коробку щурів, поки вони не зіпсувались. Ну, скоріш!\n\nВже {стать:їздив:їздила} на трамваї? Се просто. Просто зайди в трамвай і насолоджуйся поїздкою. І руки-ноги не висовуй, як не хош без них остатись.", [3] = "Віднесіть Ніпсі в Штормовійське депо Глибокобіжного трамвая коробку загадкового м'яса.", [4] = "<Ніпсі засовує палець в одну з дірок в коробці.>\n\nЖивенькі... А ти вчасно!", [5] = "Бідний Монті. Він так і не відійшов від того, що сталось в Гномреґані. Малий в житті не бачив моря, а тим більше не був піратом.\n\n<НІпсі зітхає.>\n\nПринаймні він гарно справляється з постачанням м'яса.", ["en"] = "Me Brother, Nipsy", ["tasks"] = { ["Carton of Mystery Meat"] = "коробка загадкового м'яса", ["Carton of Mystery Meat (Provided)"] = "коробка загадкового м'яса (видано)" } },
    [67] = { [1] = "Легенда про Сталвана", [2] = "Сталван, так? Дай мені перевірити реєстр.\n\nСталван... Сталван... Подивимось... Ага, ось він! Є запис про містера Сталвана Імлокрива. Остання зареєстрована адреса — школа Місяцеграю. Ох, це дуже старі записи!\n\nЗроби мені послугу, якщо ти випадково будеш в Місяцеграї, дай мені знати, якщо ти дізнаєшся щось нове про цього хлопця. Мені подобається підтримувати порядок в записах.", [3] = "Вирушайте до школи Місяцеграю і принесіть будь-яку інформацію про Сталвана писарю Долтрі.", [5] = "Стара скринька зі скрипом відчиняється...", ["en"] = "The Legend of Stalvan" },
    [6721] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Дазаларом в Доланаарі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Дазаларом у Доланаарі.", [5] = "Так, прийшов час навчити тебе....", ["en"] = "The Hunter's Path" },
    [6722] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Дазаларом в Доланаарі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Дазаларом у Доланаарі.", [5] = "Так, прийшов час навчити тебе....", ["en"] = "The Hunter's Path" },
    [6761] = { [1] = "Нові рубежі", [2] = "Я доручив своєму заступнику, Матренґілу Ведмелику, відповісти на заклик Місячної галявини про допомогу. Тож з цього питання турбуй його — НЕ мене.\n\nДозволь мені дати... дружню... пораду. Це я вивів нас із темряви, коли ми втратили все — Я, а не Кенарійське Коло з Місячної галявини. Тельдрассіль дарує всім нам нове життя! Вони, певно, намагатимуться переконати тебе в чомусь іншому, але тільки дурень повірить їхній пропаганді.\n\n{стать:Сам:Сама} вирішуй, чи ти з таких.", [3] = "Поговоріть з Матренґілом Ведмеликом у Кенарійському Анклаві Дарнасу.", [5] = "Так, {клас:к}, дякую, що {стать:прийшов:прийшла}. Перепрошую за це непорозуміння... між нашим верховним друїдом і хранителем Ремулом з Місячної поляни все більше росте взаємна недовіра. Кожен підозрює іншого в темних задумах. Дивні хвороби Тельдрассіля не припиняються, і це мало сприяє довірі.\n\nТа попри це, у нас є обов'язок перед Кенарійським Колом... навіть якщо його очільники не погоджуються один з одним.", ["en"] = "The New Frontier" },
    [6762] = { [1] = "Рабін Сатурна", [2] = "Для виконання цього завдання мажордом хранителя Ремула в Місячній поляні — Рабін Сатурна — шукає допомоги в дослідженні величезної пустелі далеко на захід від Танаріса, за Ун'Ґоро. Ти знайдеш його в Нічній Гавані, головному селищі Місячної галявини.\n\nХоча ця справа, без сумніву, принесе величезну користь всім нам, я раджу тобі бути {стать:обережним:обережною}. Стосунки між Дарнасом і Місячною галявиною напружені... що далі, то гірше.", [3] = "Поговоріть з Рабіном Сатурною в селищі Нічна Гавань на Місячній галявині. Місячна галявина знаходиться між Скверноліссям та Зимоключем, шлях до неї проходить через оплот Деревопузих.", [5] = "Я Рабін Сатурна, і від імені хранителя Ремула та всіх мешканців цієї священної галявини я вітаю тебе.\n\nЯ ціную твою зацікавленість і прагнення допомогти Кенарійському Колу. Також мені відомо про невдоволення, з яким верховний друїд Дарнасса відгукнувся про твою допомогу нам. Запевняю тебе, все це для загального блага, і тебе не зачеплять жодні наслідки.\n\nТут ти серед друзів, {ім'я}.", ["en"] = "Rabine Saturna" },
    [6781] = { [1] = "Більше уламків броні", [4] = "{ім'я:к}, нам потрібно більше уламків броні, щоб забезпечити наших бійців!", [5] = "Це хороші уламки, {ім'я:к}. Я використаю їх для створення нового спорядження для наших військ.\n\nЯкщо вдасться забезпечити бронею всі наші бойові підрозділи, вони зможуть вийти на поле бою!", ["en"] = "More Armor Scraps", ["tasks"] = { ["Armor Scraps"] = "уламки броні", ["Armor Scraps (Provided)"] = "уламки броні (видано)" } },
    [68] = { [1] = "Легенда про Сталвана", [2] = "Ви знаходите вкритий пилом невідправлений лист у старій скриньці.", [3] = "Віднесіть вкритий пилом невідправлений лист до писаря Долтрі.", [4] = "А, я тебе пам'ятаю. Це ти {стать:розпитував:розпитувала} про того типа, Сталвана. Ти {стать:знайшов:знайшла} те, що {стать:шукав:шукала}?", [5] = "Цікаво. Отже, він дійсно провів деякий час у Місцеграї. Досить дивно, що лист не був доставлений. Але все ж таки, я оновлю реєстр.", ["en"] = "The Legend of Stalvan", ["tasks"] = { ["A Dusty Unsent Letter"] = "вкритий пилом невідправлений лист", ["A Dusty Unsent Letter (Provided)"] = "вкритий пилом невідправлений лист (видано)" } },
    [681] = { [1] = "Північний маєток", [2] = "Ми ведемо війну за Стромварт і програємо. Ми ділимо це колись велике місто з ограми та Синдикатом. Кожна сторона б'ється з іншою, і кінця цим сутичкам не видно.\n\nАле наші сили вичерпуються, а у ворога лише зростають.\n\nНам потрібні припаси з Південнобережжя, але складність в тому, що Синдикат контролює територію між нами.\n\nВідправляйся на базу Синдикату в Північний маєток і перебий їх усіх. Тоді, можливо, тиск на наші транспортні шляхи ослабне, і доставляти припаси стане простіше.", [3] = "Вбийте 10 нальотників та 6 найманців Синдикату.\n\nПоверніться до капітана Ніалс в Опорний пункт.", [4] = "{ім'я}, з кожною годиною втримувати позиції в Стромварті стає все складніше. Поквапся, або наш гарнізон в місті впаде.", [5] = "Дуже добре, {ім'я}. Зі смертю цих членів Синдикату нам буде простіше отримувати припаси з Південнобережжя.\n\nМожливо, у нас ще є надія.", ["en"] = "Northfold Manor", ["tasks"] = { ["Syndicate Highwayman"] = "нальотник Синдикату", ["Syndicate Highwayman slain"] = "нальотник Синдикату: убито", ["Syndicate Mercenary"] = "найманець Синдикату", ["Syndicate Mercenary slain"] = "найманець Синдикату: убито" } },
    [682] = { [1] = "Стромвартські значки", [2] = "Синдикат у Стромварті воює з силами нашого ополчення. Щоб послабити наші війська, лідери Синдикату оголосили винагороду за кожен значок Стромварту, зібраний з убитих ополченців.\n\nМи хочемо повернути ці значки — ми не можемо дозволити головорізам забирати трофеї з тіл наших героїчно загиблих воїнів.\n\nЗайди на територію Синдикату в Стромварті та відбери у них наші значки.", [3] = "Принесіть 15 Стромвартських значків до капітана Ніалс в Опорний пункт.", [4] = "Ти вже {стать:зібрав:зібрала} Стромвартські значки, {ім'я}? Ми не можемо дозволити Синдикату наживатися на смерті наших воїнів.", [5] = "Дякую тобі, {ім'я}. Ми повідомимо сім'ям цих полеглих солдатів, що вони загинули в бою.\n\nЦе будуть сумні звістки, та все ж краще, ніж невизначеність.", ["en"] = "Stromgarde Badges", ["tasks"] = { ["Stromgarde Badge"] = "cтромвартський значок", ["Stromgarde Badge (Provided)"] = "cтромвартський значок (видано)" } },
    [684] = { [1] = "Розшукується! Марез Каптур", [2] = "За її голову Марез Каптур, високопоставленого радника і члена Синдикату, призначена винагорода. Востаннє її бачили на підконтрольній Синдикату території Стромварта.\n\nВинагороду можна отримати у капітана Ніалс.\n\nБудьте обережні! Марез — досвідчена й підступна чорнокнижниця, помічена у зв'язках із демонами. Будьте особливо обережні!", [3] = "Принесіть голову Мареза до капітана Ніалс в Опорний пункт.", [4] = "Вітаю, {клас:к}. Маєш про що мені доповісти?", [5] = "Ти {стать:ліквідував:ліквідувала} Марез Каптур? Чудова робота, {ім'я}. Справді чудова!\n\nМарез була серйозною загрозою для захисників Стромварта, і ходять чутки, що вона слугувала посередницею між Синдикатом і якимись іншими, темними силами. Тепер вона не зможе використовувати їх проти нас!", ["en"] = "Wanted! Marez Cowl", ["tasks"] = { ["Marez's Head"] = "голова Марез", ["Marez's Head (Provided)"] = "голова Марез (видано)" } },
    [685] = { [1] = "Розшукується! Отто і Соколохресний", [2] = "Стромвартське ополчення призначило винагороду за голови лорда Соколохресного та його охоронця Отто. Соколохресний керує діяльністю Синдикату на височині Араті, і його смерть призведе до зриву операцій Синдикату в цих краях.\n\nХоч його охоронець, Отто, не є стратегічною ціллю, але він вбив десятки наших воїнів.\n\nЇхні голови можеш віддати капітану Ніалс.", [3] = "Принесіть голови Отто та Соколохресного до капітана Ніалс в Опорний пункт.", [4] = "Вітаю! Хочеш про щось мені доповісти?", [5] = "Соколохресний та його охоренець Отто? Чудово!\n\nОсь твоя винагорода, {ім'я}.", ["en"] = "Wanted! Otto and Falconcrest", ["tasks"] = { ["Falconcrest's Head"] = "голова Соколохресного", ["Falconcrest's Head (Provided)"] = "голова Соколохресного (видано)", ["Otto's Head"] = "голова Отто", ["Otto's Head (Provided)"] = "голова Отто (видано)" } },
    [6881] = { [1] = "Івус — повелитель лісу", [4] = "Клан Морозних Вовків захищений закляттям енергії стихій. Їхній шаман кличе сили, які, безсумнівно, знищать нас усіх, якщо його не зупинити.\n\nВтрати стали занадто великими, щоб Коло могло їх контролювати! Ми повинні викликати Івуса на допомогу.\n\nВоїни Морозних Вовків носять талісмани стихій, що називаються кристалами шторму. Ми можемо скористатися ними, щоб викликати Івуса. Іди туди та роздобудь ці кристали, {ім'я:к}!", [5] = "Молодець, {ім'я:к}. Я використаю силу цих чар для підсилення вже зібраної магії. Коли сили буде достатньо, я сфокусую її та викличу повелителя лісу, щоб він допоміг нам.", ["en"] = "Ivus the Forest Lord", ["tasks"] = { ["Storm Crystal"] = "кристал шторму", ["Storm Crystal (Provided)"] = "кристал шторму (видано)" } },
    [689] = { [1] = "Королівські почесті", [2] = "Тож наш добрий король хоче, щоб я зробив пам'ятник на честь солдата на ім'я Саллі Баллу? Цей бідолага загинув в трагедіїї на віадуці Тандола?\n\nАх, чи настане колись в Азероті мир?\n\nТа хай там як, а будь-яке доручення короля — найважливіша справа. Щоб звести справді гарний та довговічний пам'ятник, мені знадобиться найкращий матеріал. Прямуй до пагорба Дарроу в Гіллзбрад та принеси мені альтерацький граніт.", [3] = "Головний каменяр Мармуренко з Залізогарту просить вас принести йому 5 шматків альтерацького граніту.", [4] = "{ім'я}, {ім'я}, {ім'я}! Сподіваюсь, ти {стать:приніс:принесла} достатньо альтерацького граніту і я можу почати роботу над пам'ятником на честь Саллі Баллу.", [5] = "Чудово! Навіть краще, ніж я міг собі уявити!\n\nА уява в мене неабияка...", ["en"] = "A King's Tribute", ["tasks"] = { ["Alterac Granite"] = "альтерацький граніт", ["Alterac Granite (Provided)"] = "альтерацький граніт (видано)" } },
    [69] = { [1] = "Легенда про Сталвана", [2] = "О, Боже! Мабуть, я першого разу пропустив це. У реєстрі просто праворуч від першої адреси Сталвана є ще одна, частково зачеркнута. Здається, він вирушив до таверни «Гордість лева» у Злотохрестя. Можливо, тобі варто пошукати там, {ім'я:к}.", [3] = "Вирушайте в таверну «Гордість лева» і поцікавтеся, чи не знають там кого-небудь ім'я Сталван.", [5] = "Сталван? Звучить знайомо.", ["en"] = "The Legend of Stalvan" },
    [690] = { [1] = "Прохання Маліна", [2] = "Вітаю, {ім'я}. Ти здаєшся {стать:досвідченим шукачем:досвідченою шукачкою} пригод, а в мене є завдання для таких, як ти.\n\nАрхімаг Трелейн, мій колишній повелитель, не так давно тікав зі Стромварту, що на височині Араті, і попросив мене допомогти йому з поверненням його полишених речей.\n\nМісто було під облогою і він намагався обороняти вежу Аратора, але марно. Я вже маю там кількох помічників, але вони попросили про допомогу. {стать:Зацікавлений:Зацікавлена}?", [3] = "Знайдіть Скуерто в Опорному пункті на височині Араті.", [5] = "То тебе прислав Малін? А мені однаково, най хоть Мурадін воскресне і явиться тутко на драконі. Я занятий! Поговори з Критеном, якщо тобі щось треба.", ["en"] = "Malin's Request" },
    [691] = { [1] = "На вагу золота", [2] = "Архімаг Малін послав нас зі Скуерто зібрати для нього реагенти. Я трохи зайнятий і не можу піти по реагенти, зробиш це за мене?\n\nМені потрібні ікла тролів Зів'ялої Кори, їхні трави та ніж темного мисливця.\n\nЗможеш їх знайти? Тролі Зів'ялої Кори живуть на південному сході Араті.", [3] = "Принесіть 10 ікл тролів Зів'ялої Кори, 4 мішечки з травами Зів'ялої Кори та ніж темного мисливця учневі Крітену в Опорний пункт.", [4] = "Тобі вже вдалося щось знайти, {ім'я}?\n\n<Крітен у процесі читання робить помітки в журналі.>\n\nЯкщо мої дослідження вірні, ікла можна дістати у будь-яких тролів з племені Зів'ялої Кори. Мішечки з травами мають бути у їхніх знахарів. А особливі ножі дають найкращим темним мисливцям племені, коли ті проходять ритуал посвяти.", [5] = "Чудесно! Я тепер розумію, чому Малін попросив тебе приєднатися до нас — справді, чудова робота!\n\nТакими темпами ми зі Скуерто вже зовсім скоро повернемося до Штормовію.\n\nСхоже, мій товариш дворф повернувся з вилазки до табору Брилоруких. Поговори з ним, як матимеш змогу.\n\nЗдається, його трохи побили огри. Тільки не говори йому про це: він дуже чутливий до критики.", ["en"] = "Worth Its Weight in Gold", ["tasks"] = { ["Shadow Hunter Knife"] = "ніж темного мисливця", ["Shadow Hunter Knife (Provided)"] = "ніж темного мисливця (видано)", ["Witherbark Medicine Pouch"] = "мішечок з травами Зів'ялої Кори", ["Witherbark Medicine Pouch (Provided)"] = "мішечок з травами Зів'ялої Кори (видано)", ["Witherbark Tusk"] = "ікло троля Зів'ялої Кори", ["Witherbark Tusk (Provided)"] = "ікло троля Зів'ялої Кори (видано)" } },
    [693] = { [1] = "Жезл Трелейна", [2] = "Гей, {ім'я}. Вибачай що мало з тобоу спілкувавсь, мав справи.\n\nЯ знясував, де знаходитси перша річ Трелейна, а саме його жезл — він у Кор'ґреша в таборі Брилоруких. Він метав ним крижані кулі в інших огрів, тож схоже, що він починає опановувати сили жезла.\n\nТабір Брилоруких знаходитси на південь звідси, східніше віадуку Тандола. Знайди огрів і верни жезл.\n\nА поки тебе не буде, я придумаю, що нам робити зі Стромвартом.", [3] = "Знайдіть жезл Трелейна для виклику і принесіть його до Скуерто в Опорний пункт.", [4] = "Твоя ціль — жезл, {ім'я}. Зосередьсі на ньому!", [5] = "Файно, {ім'я}. Перша річ із чотирьох в нас є. Решта — в Стромварті.\n\nПоки що відпочивай та відновлюй сили — для наступного кроку знадобитси більше часу й зусиль. Вертай си як відпочинеш!", ["en"] = "Wand over Fist", ["tasks"] = { ["Trelane's Wand of Invocation"] = "жезл Трелейна для виклику", ["Trelane's Wand of Invocation (Provided)"] = "жезл Трелейна для виклику (видано)" } },
    [694] = { [1] = "Захист Трелейна", [2] = "Відпочили?\n\nОсь і наступний крок! Довкола вежі Аратора в Стромварті повно огрів. Ми активуєм систему захисту вежі, щоб урівняти наші шанси. Щоб се зробити, нам знадобитси кілька самоцвітів, які уподобали брилорукі шамани. Вони забрали їх з вежі, але най сильно не радіють — се не надовго.\n\nДістань один самоцвіт і віднеси його Крітену — він знає як зачарувати його так, щоб він працював як ключ.", [3] = "Знайдіть лазурний агат і віднесіть його учневі Крітену в Опорний пункт.", [4] = "І знову привіт, {ім'я}. Вже {стать:дістав:дістала} лазурний агат?", [5] = "Ти мене приємно дивуєш, {ім'я}. Чудова робота!\n\nДай мені хвильку, щоб я зачарував цей самоцвіт, і все буде готово.", ["en"] = "Trelane's Defenses", ["tasks"] = { ["Azure Agate"] = "лазурний агат", ["Azure Agate (Provided)"] = "лазурний агат (видано)" } },
    [6941] = { [1] = "Поклик повітря — флот Віпора", [4] = "З елітними бійцями Морозних Вовків, що охороняють лінію фронту, потрібно розібратись, солдате! Розгроми частину цих дикунів і принеси мені медалі їхніх лейтенантів та легіонерів. Коли цим недоумкам добряче дістанеться, я завдам удару з повітря.", [5] = "Флот незабаром буде готовий. Продовжуй працювати!", ["en"] = "Call of Air - Vipore's Fleet", ["tasks"] = { ["Frostwolf Lieutenant's Medal"] = "медаль лейтенанта Морозних Вовків", ["Frostwolf Lieutenant's Medal (Provided)"] = "медаль лейтенанта Морозних Вовків (видано)" } },
    [6942] = { [1] = "Поклик повітря — флот Слідора", [4] = "Мої грифони готові вдарити по лінії фронту, але через велику кількість ворогів не можуть цього зробити.\n\nБійці Морозних Вовків, яким доручено тримати лінію фронту, гордо носять на грудях медалі за свої заслуги. Зірви ці медалі з їхніх гнилих трупів і принесіть сюди.\n\nЯк тільки кількість ворогів на лінії фронту зменшиться, ми організуємо їм повітряну тривогу! Нападемо з неба!", [5] = "Не зупиняйся, солдате! Грифони Орлиного піку будуть готові до удару з хвилини на хвилину!", ["en"] = "Call of Air - Slidore's Fleet", ["tasks"] = { ["Frostwolf Soldier's Medal"] = "медаль солдата Морозних Вовків", ["Frostwolf Soldier's Medal (Provided)"] = "медаль солдата Морозних Вовків (видано)" } },
    [6943] = { [1] = "Поклик повітря — флот Ічмана", [4] = "Їхня воля зламана, солдате. Після нашого останнього невдалого удару по Орді, вони відмовляються летіти! Настав час підняти їм бойовий дух.\n\nПовернись на поле бою і розгроми командування Морозних Вовків. Вбий їхніх командирів та вартових. Збери з трупів стільки медалей, скільки зможеш запхати у свою сумку! Я впевнений, коли мої грифони побачать нагороду та відчують запах крові наших ворогів, вони піднімуться в повітря знову! А тепер йди!", [5] = "Ти це бачиш? Подивись на них, солдате! Вони злітають... Незабаром флот Ічмана знову вдарить у самісіньке серце долини! Бурешпиль керуватиме небом!", ["en"] = "Call of Air - Ichman's Fleet", ["tasks"] = { ["Frostwolf Commander's Medal"] = "медаль командира Морозних Вовків", ["Frostwolf Commander's Medal (Provided)"] = "медаль командира Морозних Вовків (видано)" } },
    [6982] = { [1] = "Припаси Кригозубих", [2] = "Орда використовує копальню Кригозубих, як склад. Мій шлунок не може переварити їжу, якою вони годують своїх солдатів, а їхня зброя та обладунки просто в жахливому стані! Але... в такі складні часи, коли кожна скибка хліба важлива, можна скористатися і їхніми припасами.\n\nВирушай в копальню Кригозубих та принеси мені їхні припаси. Це допоможе підтримувати сили Альянсу та позбавить солдатів Орди необхідного спорядження.\n\nЩасти тобі, {ім'я:к}. Шахта знаходиться на далекому півдні, в глибинах земель Орди.", [3] = "Принесіть 10 припасів Кригозубих квартирмейстеру Альянсу в Дун-Балдар.", [4] = "Ти {стать:зміг:змогла} дістатись копальні Кригозубих на території Орди, {ім'я:к}? Вдалось поцупити їхні припаси?", [5] = "Ти {стать:приніс:принесла} їх! Чудова робота, {ім'я:к}! Я перегляну припаси й віддам їх нашим бійцям!", ["en"] = "Coldtooth Supplies", ["tasks"] = { ["Coldtooth Supplies"] = "припаси Кригозубих", ["Coldtooth Supplies (Provided)"] = "припаси Кригозубих (видано)" } },
    [7] = { [1] = "Зачистка табору кобольдів", [2] = "Твоє перше завдання буде пов'язане із зачищенням, {ім'я:к}. Клан кобольдів заполонив ліси на півночі. Направляйся туди та знищ усіх кобольдів-шкідників, що зустрінуться на твоєму шляху. Зменш їхню популяцію, щоб одного дня ми змогли остаточно вигнати їх з Північнокраю.", [3] = "Убийте 10 кобольдів-шкідників, а потім поверніться до маршала Макбрайда.", [4] = "Як там твоє полювання, {ім'я:к}? Ти {стать:знайшов:знайшла} і {стать:здолав:здолала} тих шкідників?", [5] = "Молодець, {стать:громадянине:громадянко}. Ці кобольди — злодії та боягузи, але у великій кількості вони становлять загрозу для нас. А людям Штормовію не потрібна ще одна загроза.\n\nПрийми мою подяку за перемогу над ними.", ["en"] = "Kobold Camp Cleanup", ["tasks"] = { ["Kobold Vermin"] = "кобольд-шкідник", ["Kobold Vermin slain"] = "кобольд-шкідник: убито" } },
    [70] = { [1] = "Легенда про Сталвана", [2] = "Ім'я Сталван звучить знайомо. О, я згадав.\n\nБагато років тому, бурхливої ночі, до нас зайшов посланець, який шукав притулку на ніч. Близько опівночі цей чоловік, блідий від страху, збіг униз сходами в піжамі й зник.\n\nПоспішаючи, він забув свої листи у скрині нагорі. Він так і не повернувся за ними. Один лист залишився від цього Сталвана, адресований в район каналів у Штормовії. Можеш забрати його, якщо хочеш.", [3] = "Візьміть зі скрині недоставлений лист Сталвана і доставте його в район каналів Штормовію.", [4] = "Що це у тебе? Дай-но я погляну...", [5] = "У тебе вистачило нахабства принести це сюди.", ["en"] = "The Legend of Stalvan", ["tasks"] = { ["An Undelivered Letter"] = "недоставлений лист", ["An Undelivered Letter (Provided)"] = "недоставлений лист (видано)" } },
    [7022] = { [1] = "Дідусь Зима вже тут!", [2] = "Щасливої Зимової Покрови, {стать:друже:подруго}! Обов'язково привітайся з Дідусем Зимою! Якщо ти {стать:був чемним:була чемною} цього року, то отримаєш чудові ласощі у день свята Зимової Покрови. Не забудь розказати йому, що саме тобі хотілося б отримати цього року!\n\nТакож не забудь приготувати частування для тих, хто був чемним цього року. У нас є з чого вибрати. Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу!", [3] = "Поговоріть з Дідусем Зимою біля торгового майданчика Пасовищ Димного Лісу в Залізогарті.", [5] = "Хо-хо-хо, привіт. Я Дідусь Зима, і від імені моїх друзів з Пасовищ Димного Лісу, кхм... \"Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу!\", хочу побажати тобі казкового свята Зимової Покрови.\n\nЯкщо ти {стать:був чемним:була чемною} цього року, можливо, ти отримаєш ласощі від Пасовищ Димного Лісу як подарунок до свята Зимової Покрови. Хо-хо!", ["en"] = "Greatfather Winter is Here!" },
    [7023] = { [1] = "Дідусь Зима вже тут!", [2] = "Щасливої Зимової Покрови, {стать:друже:подруго}! Обов'язково привітайся з Дідусем Зимою в Залізогарті! Якщо ти {стать:був чемним:була чемною} цього року, то отримаєш чудові ласощі у день свята Зимової Покрови. Не забудь розказати йому, що саме тобі хотілося б отримати цього року!\n\nТакож не забудь приготувати частування для тих, хто був чемним цього року. У нас є з чого вибрати. Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу!", [3] = "Поговоріть з Дідусем Зимою біля торгового майданчика Пасовищ Димного Лісу в Залізогарті.", [5] = "Хо-хо-хо, привіт. Я Дідусь Зима, і від імені моїх друзів з Пасовищ Димного Лісу, кхм... \"Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу!\", хочу побажати тобі казкового свята Зимової Покрови.\n\nЯкщо ти {стать:був чемним:була чемною} цього року, можливо, ти отримаєш ласощі від Пасовищ Димного Лісу як подарунок до свята Зимової Покрови. Хо-хо!", ["en"] = "Greatfather Winter is Here!" },
    [7025] = { [1] = "Ласощі для Дідуся Зими", [2] = "Гей, можеш зробити Дідусеві Зимі послугу, {стать:хлопчику:дівчинко}?\n\nНе хочу без потреби говорити про себе в третій особі, але Дідусь Зими весь день на ногах, і йому б не завадило трохи імбирного печива і крижаного молока. Чи не {стать:міг би:могла б} ти допомогти Дідусеві Зимі, і принести їх мені?", [3] = "Принесіть 5 імбирних печив та крижане молоко Дідусеві Зимі в Залізогарт.", [4] = "Від усіх цих розмов про ласощі мені й самому захотілося чогось смачненького. Мммм... імбирне печиво з молоком...", [5] = "Ти дуже {стать:виручив:виручила} Дідуся Зиму, {ім'я}. Щасливого свята Зимової Покрови.\n\nОсь тобі дещо... ну, знаєш, за старання.", ["en"] = "Treats for Greatfather Winter", ["tasks"] = { ["Gingerbread Cookie"] = "імбирне печиво", ["Gingerbread Cookie (Provided)"] = "імбирне печиво (видано)", ["Ice Cold Milk"] = "крижане молоко", ["Ice Cold Milk (Provided)"] = "крижане молоко (видано)" } },
    [7026] = { [1] = "Збруя верхових баранів", [4] = "Бригада Бурешпиля не може йти в бій з голими руками! Нам потрібна збруя для наших баранів, ми ж не дикуни.\n\nМи могли б легко вбити баранів, що бродять біля нашої бази та отримати шкіру для виготовлення збруї, але це було б ідіотизмом. Ці барани потрібні нашим вершникам.\n\nТи маєш атакувати базу нашого ворога, вбити морозних вовків, яких вони використовують як верхових тварин та забрати їхні шкури. Принеси мені ці шкури, і я зроблю з них збрую. Вперед!", [5] = "Молодець, солдате. Я дам тобі знати, коли зберу достатньо шкур.\n\nПродовжуй працювати!", ["en"] = "Ram Riding Harnesses", ["tasks"] = { ["Frostwolf Hide"] = "шкура морозного вовка", ["Frostwolf Hide (Provided)"] = "шкура морозного вовка (видано)" } },
    [7027] = { [1] = "Порожні стайні", [2] = "Поглянь на стайні, {ім'я:к}! Вони порожні! Бригада Бурешпиля не має верхових баранів, а це значить, що кавалерії також немає.\n\nТи маєш нам допомогти, солдате. Візьми цей тренувальний нашийник та вирушай у нетрі долини. Знайди альтерацьких баранів, які блукають по околицях та скористайся нашийником, щоб зловити одного з них. Після цього приведи його до мене і я поміщу його в нашу стайню.\n\nКоли баранів буде достатньо, я повідомлю командира вершників про це. З твоєю допомогою кавалерія знову піде в бій!", [3] = "Знайдіть альтерацького барана в Альтерацькій долині. Коли знайдете барана, скористайтесь тренувальним нашийником Бурешпилів та приручіть його. Після цього приручений альтерацький баран піде з вами назад до доглядачки стайні. Поговоріть з нею, щоб отримати нагороду за впійманого барана.", [4] = "Без твоєї допомоги вершники Бурешпилів були б без баранів, на яких можна вирушити в бій. Ти робиш нам велику послугу!", [5] = "Стайні будуть заповнені в найкоротші терміни. Продовжуй в тому ж дусі!", ["en"] = "Empty Stables", ["tasks"] = { ["Ram Collared and Returned"] = "Овена спіймали на нашийник і повернули" } },
    [7042] = { [1] = "Викрадені ласощі Зимової Покрови", [2] = "Слухай... не хочу руйнувати святковий настрій, але Пасовищам Димного Лісу потрібна допомога {стать:шукача:шукачки} пригод на кшталт тебе.\n\nМи втратили важливу партію ласощів, що мала поповнити наші запаси на цей сезон, і тепер ми не можемо знайти агента Пасовищ Димного Лісу, якого ми відправили на пошуки! Будь ласка, допоможи нам. Останні відомості про ласощі були з Альтерацьких гір, туди й пішов наш агент.\n\nЗнайди там його і наші ласощі!", [3] = "Знайдіть агента Пасовищ Димного Лісу, що зник у засніжених районах Альтерацьких гір.", [5] = "Т-т-ти мене ч-ч-чуєш! Слава б-б-богам!\n\nН-ні, я не с-с-сніговик. Мене звати Т-т-торб, я п-п-працюю в Залізогартському відділенні П-п-асовищ Димного Лісу. М-м-м-м-мене відправили шукати зниклий товар, і тут н-н-на мене напала тварюка, якої я ніколи не б-б-бачив!\n\nБр-р, х-х-холодно!", ["en"] = "Stolen Winter Veil Treats" },
    [7043] = { [1] = "Ти мерзенний...", [2] = "Це с-с-с-створіння, відоме як \"М-м-мерзенний Ґрінч\", саме воно викрало нашу партію ласощів, {ім'я}. Але будь {стать:обережним:обережною}! Це він перетворив мене на цього с-с-сніговика!\n\nТобі з-з-знадобиться допомога. Я бачив, як він вештався неподалік з іншими єті. З-з-знайди ласощі, {ім'я}, поверни їх до Пасовищ Димного Лісу в Залізогарт та с-с-скажи їм, що мене потрібно роз-з-зморозити!", [3] = "Знайдіть і поверніть викрадені ласощі Хотайну Злотодзвону в Залізогарт. Востаннє вони були в Мерзенного Ґрінча, десь у засніжених районах Альтерацьких гір.", [4] = "{ім'я} — свято Зимової Покрови неможливе без ласощів! Сам Ґракку не зможе поділитися своїми смачними м'ясними пирогами зі слухняними дітками...", [5] = "Ти {стать:знайшов:знайшла} їх! Ти {стать:врятував:врятувала} свято Зимової Покрови!\n\nБідний Торб... ми надішлемо команду до нього та знайдемо спосіб розморозити його. Сподіваюсь, він повернеться до дня святкування. Він ще мусить відпрацювати пропущені години. Але це взагалі було б неможливо, якби не ти!", ["en"] = "You're a Mean One...", ["tasks"] = { ["Stolen Treats"] = "викрадені ласощі", ["Stolen Treats (Provided)"] = "викрадені ласощі (видано)" } },
    [7045] = { [1] = "Подяка від Пасовищ Димного Лісу!", [2] = "Пасовища Димного Лісу дуже вдячні тобі за повернення викрадених ласощів, {ім'я}. За це ти маєш отримати особливий подарунок... від самого Дідуся Зими!\n\nБудь ласка, поговори з Дідусем Зимою, і він вручить тобі подарунок від Пасовищ Димного Лісу. Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу... завдяки тобі, звісно!", [3] = "Поговоріть з Дідусем Зимою в Залізогарті.", [5] = "Хо-хо-хо, привіт, {стать:авантюристе:авантюристко}!\n\nГобліни сказали мені, що ти {стать:заслужив:заслужила} на особливий подарунок цього святкового сезону, і я з радістю вручаю його тобі. Тримай — бажаю тобі чудового свята Зимової Покрови в цьому і кожному наступному році!", ["en"] = "A Smokywood Pastures' Thank You!" },
    [7062] = { [1] = "Привід для свята", [2] = "Подарунки, смаколики, частування... пфф, скажу я!\n\nТі гобліни спотворюють справжнє значення цього свята — Зимової Покрови. Це час оновлення. Земля спить під ковдрою снігу, принесеного Дідусем Зимою — НЕ отим незграбним дурнем у червоному костюмі!\n\nЯкщо тобі цікаво дізнатися про справжній сенс цього свята — запитай історика Карника з Ліги Дослідників. Впевнений, він буде здивований, що хтось цікавиться історією свята, а не подарунками.", [3] = "Поговоріть з істориком Карником з Ліги Дослідників в Залізогарті про свято Зимової Покрови.", [5] = "Свято Зимової Покрови, кажеш? На жаль, у минулі часи воно мало більш вагоме значення для нас, джворфів. Зараз, здається, всі перетворили легенду про Дідуся Зиму на рекламу для цукерок та подарунків.\n\nНе дивно, що Ґолі це так засмучує. Він, та деякі інші схожі на нього дворфи, тримаються за нашу історію, як за бойовий стяг. Хоча я вважаю, що невеликі веселощі ніколи не завадять, важливо пам'ятати й про його походження.", ["en"] = "The Reason for the Season" },
    [7063] = { [1] = "Свято Зимової Покрови", [2] = "Ось — якщо тобі цікаво дізнатися більше про свято Зимової Покрови, прочитай цю книгу. Хоча я вважаю, що наше тлумачення легенди є досить вірним, я, як вчений, ціную перевірені джерела інформації.\n\nКоли закінчиш, віднеси королю Маґні Бронзобородому. Впевнений, він буде радий почути, що хтось цікавиться старими легендами.", [3] = "Прочитайте книгу \"Свято Зимової Покрови\", щоб дізнатися більше про походження свята. Коли ви закінчите, віднесіть її королю Маґні Бронзобородому в Залізогарт.", [4] = "Ласкаво просимо до королівства Залізогарт, {стать:друже:подруго}. Я завжди цікавлюся тими, хто виявляє зацікавленість у королівстві, його народі та історії. Ти ж саме через це стоїш переді мною?", [5] = "Легенди, пов'язані зі святом Зимової Покрови, з часом забулися у свідомості нашого народу. Хоча я розумію, що гобліни допомагають оживити це свято з метою своєї власної користі, той факт, що ми хоча б у якійсь формі пам'ятаємо про нього, сприяє збереженню легенд.\n\nТвоє бажання піти за межі матеріального та дізнатися про наше минуле — це похвальна риса, {стать:юний:юна} {клас:к}. Мене тішить твоя допитливість.", ["en"] = "The Feast of Winter Veil", ["tasks"] = { ["The Feast of Winter Veil"] = "Свято Зимової Покрови", ["The Feast of Winter Veil (Provided)"] = "Свято Зимової Покрови (видано)" } },
    [707] = { [1] = "Ви потрібні Залізоплету!", [2] = "{ім'я}. Я отримав звіт розвідувача Залізоплета про перебіг розкопок у Лох-Модані. Йому потрібна допомога з іншими нашими розкопками.\n\nБільше нічого сказати не можу, але якщо бажаєш трохи розім'яти ноги — вирушай до Залізоплета.", [3] = "Поговоріть з розвідувачем Залізоплетом на його розкопках у Лох-Модані.", [5] = "То тебе прислав Бурешпиль? Добре.\n\nВ мене є для тебе важливе завдання...", ["en"] = "Ironband Wants You!" },
    [7070] = { [1] = "Фрагменти тінекаменю", [2] = "Нещодавно я почав випробовувати різні кристали та їхні магічні властивості. Леді Праудмур дозволила мені звертатися до мандрівників, що прямують до Спустошища та просити їх відшукати місце під назвою Мародон. У зруйнованому храмі живуть величезні елементалі, що складаються з фіолетових кристалів, які я називаю тінекаменем.\n\nЯкщо ти вирішиш піти туди й відшукати кілька кристалів, я буду дуже вдячний тобі. Я навіть міг би виготовити з них прикрасу для тебе, якщо захочеш.", [3] = "Зберіть 10 фрагментів тінекаменю в Мародоні та поверніть їх архімагу Тервошу в Терамор, що знаходиться на узбережжі Бруднолипкої трясовини.", [4] = "Ти вже {стать:побував:побувала} в Мародоні? Я розумію, що справа ця небезпечна, але якщо ти впораєшся, нагорода окупить твої зусилля.", [5] = "Вони ідеальні, {ім'я}. Насправді звідти вже повернулися інші шукачі пригод та принесли кристали, з яких я зміг виготовити ці прикраси... Будь ласка, не соромся, візьми собі одну в знак подяки за твою важку роботу. І ще раз дякую за нові зразки для вивчення.", ["en"] = "Shadowshard Fragments", ["tasks"] = { ["Shadowshard Fragment"] = "фрагмент тінекаменю", ["Shadowshard Fragment (Provided)"] = "фрагмент тінекаменю (видано)" } },
    [708] = { [1] = "Чорний ящик", [2] = "Поверхня цього металевого чорного ящика поїдена іржею, ніби його занурювали в кислоту — схоже, він довго пролежав в шлунку гігантського кондора.\n\nПеревернувши ящик, ви знайшли символ, викарбуваний на дні. Під символом напис:\n\n\"Двигун #19 - Штурмова бригада Залізогарта\"", [3] = "Віднесіть заіржавілий чорний ящик до Військової зали у Залізогарті.", ["en"] = "The Black Box", ["tasks"] = { ["Corroded Black Box"] = "заіржавілий чорний ящик", ["Corroded Black Box (Provided)"] = "заіржавілий чорний ящик (видано)" } },
    [7081] = { [1] = "Кладовища Альтерацької долини", [2] = "Кладовища Альтерацької долини — це важливі для нас території. І Орда, і Альянс несамовито воюють за ці священні землі. {ім'я:к}, ти {стать:готовий:готова} вступити в цю битву?\n\nЯ хочу, щоб ти {стать:захопив:захопила} вороже кладовище. Знайди кладовище, на якому в землю запханий стяг Орди та витягни його! Зробиш це і можеш вважати завдання виконаним...\n\nПрослідкуй за кладовищем кілька хвилин, поки наші війська не прийдуть на допомогу.", [3] = "Захопіть кладовище та поверніться до сержанта Дурґена Бурешпиля в Альтерацькі гори.", [4] = "{ім'я:к}, ти досі не {стать:захопив:захопила} кладовище. Приходь, коли виконаєш завдання!", [5] = "Молодець! Кладовища є важливим елементом для контролю Альтерацької долини. Захоплюючи одне з них, ти допомагаєш Альянсу відстояти свої території.\n\nА тепер іди, {Ім'я:к}. Повертайся на поле бою і якщо ти побачиш кладовище з прапором Орди... ти знаєш, що робити!", ["en"] = "Alterac Valley Graveyards", ["tasks"] = { ["Graveyard Assaulted"] = "Напад на цвинтар", ["Graveyard Assaulted (Provided)"] = "Напад на цвинтар (видано)", ["Graveyard Assaulted slain"] = "Напад на цвинтар: убито" } },
    [71] = { [1] = "Звіт Томасу", [2] = "Тепер, коли у вас є обидва медальйони, віддайте їх вартовому Томасу на мосту, щоб він дізнався про долю своїх загиблих підлеглих.", [3] = "Доставте медальйони Рольфа та Малакая вартовому Томасу на східний ельвиннський міст.", [4] = "Привіт, {ім'я:к}. Ти {стать:довідався:довідалась} про долю Рольфа та Малакая?", [5] = "Мої побоювання підтвердились, {ім'я:к}. Мурлоки — це загроза, яку ми не можемо ігнорувати.", ["en"] = "Report to Thomas", ["tasks"] = { ["Rolf and Malakai's Medallions"] = "медальйони Рольфа і Малакая", ["Rolf and Malakai's Medallions (Provided)"] = "медальйони Рольфа і Малакая (видано)" } },
    [7102] = { [1] = "Вежі та бункери", [2] = "Вежі та бункери — це ключові оборонні позиції, тому нам потрібно захопити їх якомога більше! Я хочу, щоб ти {стать:атакував:атакувала} вежу або бункер в Альтерацькій долині.\n\nДля цього зайди у вежу з прапором Орди. Всередині ти знайдеш ще один ворожий прапор. Витягни його та на цьому місці з'явиться білий прапор Альянсу.\n\nЗроби це і можеш вважати завдання виконаним, але якщо ти протримаєшся на місці достатньо довго та Орда не відвоює його, то воно буде знищене!", [3] = "Знищте стяг на ворожій вежі або бункері, а потім поверніться до сержанта Дурґена Бурешпиля в Альтерацькі гори.", [4] = "Ти ще не {стать:штурмував:штурмувала} вежу, {ім'я:к}?! Чого ж ти чекаєш?", [5] = "Я отримав звіт, в якому сказано, що ти {стать:допоміг:допомогла} захопити ворожий прапор. Молодець, {ім'я:к}! Тепер, коли їхні війська відступили з позицій, ми можемо просуватися вперед!", ["en"] = "Towers and Bunkers", ["tasks"] = { ["Banner Destroyed"] = "Банер знищено" } },
    [7121] = { [1] = "Квартирмейстер", [2] = "{ім'я:к}, наш квартирмейстер доручив мені направляти до нього новобранців. Йому потрібні припаси зі схованок, що зберігаються в шахтах Альтераку і, швидше за все, він відправить тебе за ними.\n\nЙди цією дорогою на захід та знайдеш нашого квартирмейстера.", [3] = "Поговоріть з квартирмейстером Бурешпиля.", [5] = "Приємно бачити тут нових бійців, {ім'я:к}, але якщо пощастить, то ти потрапиш у бій, і {стать:новеньким:новенькою} будеш недовго!\n\nПоговоримо через хвилину. Я маю для тебе завдання, які потрібно обговорити...", ["en"] = "The Quartermaster" },
    [7122] = { [1] = "Захоплення копальні", [2] = "Шахти в Альтерацькій долині містять не лише корисні копалини. І Морозні Вовки, і Бурешпиль тримають в копальнях свої припаси... І непогано було б захопити чужі припаси!\n\nЗахопи копальню та повернись до мене. Щоб зробити це, увійди в ту копальню, яку ми не контролюємо та вбий того, хто там головний. Коли ти виконаєш це, шахта стане нашою і ми відправимо війська для її охорони!", [3] = "Захопіть шахту, яку не контролює Бурешпиль, а потім поверніться до сержанта Дурґена Бурешпиля в Альтерацькі гори.", [4] = "Ти ще не {стать:захопив:захопила} шахту, {ім'я:к}!\n\nКоли ми керуватимемо шахтою, нам буде набагато простіше добувати руду та припаси.", [5] = "Ти {стать:зробив:зробила} це! Хороша робота, {ім'я:к}!\n\nТепер, коли ми контролюємо шахтою та розмістили там наші війська, нам стало набагато легше добувати корисні копалини та припаси.", ["en"] = "Capture a Mine", ["tasks"] = { ["Mine Captured"] = "Шахта захоплена", ["Mine Captured (Provided)"] = "Шахта захоплена (видано)", ["Mine Captured slain"] = "Шахта захоплена: убито" } },
    [7141] = { [1] = "Битва за Альтерак", [2] = "Ліга дослідників вважає, що в Альтерацькій лежать цінні артефакти, але орки з Морозних Вовків не дають нам це перевірити. Ми не можемо дозволити Орді завадити нашим науковим пошукам! Вбий генерала Морозних Вовків — Дрек'Тара. Після його смерті орки втратять свою перевагу.\n\nТи зможеш знайти Дрек'Тара в форті Морозних Вовків, на півдні Альтерацької долини. Знищ його та повернись до мене.", [3] = "Вирушайте в Альтерацьку долину, вбийте ординського генерала Дрек'Тара, після чого поверніться до розвідувачки Каменетески в Альтерацькі гори.", [4] = "Вперед, {ім'я:к}. Вирушай в Альтерацьку долину та вбий генерала орків!", [5] = "Молодець, {ім'я:к}! Тепер, поки Орда оговтуватиметься від смерті їхнього генерала, ми зможемо провести наші дослідження!", ["en"] = "The Battle of Alterac", ["tasks"] = { ["Defeat Drek'thar."] = "Перемогти Дрек'тара." } },
    [7162] = { [1] = "Випробувальні землі", [2] = "Ти {стать:прийшов:прийшла} якраз вчасно, {клас:к}. Ці дикуни, Морозні Вовки, не збираються здаватися! Ми повинні показати їм міць Бурешпилів. Вони мають схилити голови перед нами.\n\nПерш ніж вирушити на поле бою, ти маєш вступити в наші ряди.\n\nНа південному заході від Дун-Балдара ти знайдеш Кригокрилу печера. У глибині печери сховано знамено Бурешпилів. Іди та знайди це знамено. Поверни його мені та я нагороджу тебе відзнакою Бурешпилів.", [3] = "Вирушайте до Кригокрилої печери, що розташована в Альтерацькій долині, на південний захід від Дун-Балдара та знайдіть знамено Бурешпилів. Принесіть знамено лейтенанту Гаґґердіну в Альтерацькі гори.", [4] = "Остерігайся гарпій, {клас:к}. Вони можуть вмить перегризти тобі горлянку!", [5] = "Візьми цю відзнаку та носи її з гордістю, {ім'я:к}. Зі зростанням твого звання в рядах Бурешпилів, змінюватиметься й твоя відзнака. Повертайся до мене, коли здобудеш шану Бурешпилів і я заміню твою відзнаку на іншу, більш поважну.\n\nМожливо, колись ти станеш легендою цього поля бою. Якщо цей день колись настане, ти отримаєш Око Командування.", ["en"] = "Proving Grounds", ["tasks"] = { ["Stormpike Banner"] = "знамено Бурешпилів", ["Stormpike Banner (Provided)"] = "знамено Бурешпилів (видано)" } },
    [7168] = { [1] = "Отримання визнання", [4] = "Більшість не доживає до моменту, коли можуть отримати те, на що заслуговують. Ти {стать:показав:показала} себе зразковим солдатом, {клас:к}. Прийшов час.\n\nДай мені свою відзнаку.", [5] = "Нехай наші вороги бачать, що їх здолав солдат зі званням! Бийся за славу Бурешпиля!", ["en"] = "Rise and Be Recognized", ["tasks"] = { ["Stormpike Insignia Rank 1"] = "відзнака Бурешпилів, ранг 1", ["Stormpike Insignia Rank 1 (Provided)"] = "відзнака Бурешпилів, ранг 1 (видано)" } },
    [7169] = { [1] = "Повага варти", [4] = "База гуде від розмов про твої подвиги на полі Чвар! Ти {стать:завдав:завдала} потужних ударів по нашому ворогу, знищивши його бойовий дух! За це ти {стать:заслужив:заслужила} почесне звання серед Бурешпилів.", [5] = "Король дізнався про твій героїзм на передовій, {клас:к}. Продовжуй стійко нести варту Бурешпилю!", ["en"] = "Honored Amongst the Guard", ["tasks"] = { ["Stormpike Insignia Rank 2"] = "відзнака Бурешпилів, ранг 2", ["Stormpike Insignia Rank 2 (Provided)"] = "відзнака Бурешпилів, ранг 2 (видано)" } },
    [7170] = { [1] = "Заслужена пошана", [4] = "Я хочу знати одне, {ім'я:к}. Коли ти дивишся прямо в очі ворогу, ти бачиш їхній страх? Чи вони розбігаються в паніці, коли бачать тебе? Вони повинні розуміти, що їм не перемогти!\n\nТи {стать:заслужив:заслужила} пошану варти. Давай свою відзнаку!", [5] = "Коли ми вперше зустрілися, в мене навіть на думці не було, що з тебе вийде {стать:герой:героїня}. Так тримати, солдате!", ["en"] = "Earned Reverence", ["tasks"] = { ["Stormpike Insignia Rank 3"] = "відзнака Бурешпилів, ранг 3", ["Stormpike Insignia Rank 3 (Provided)"] = "відзнака Бурешпилів, ранг 3 (видано)" } },
    [7171] = { [1] = "Легендарні герої", [4] = "Переді мною стоїть {стать:великий герой:велика героїня} Альянсу.\n\n<Лейтенант Гаґґердін віддає честь.>\n\nМало хто серед варти Бурешпилів має таке звання. Я бачив, як ти знищуєш ворогів. Я бачив, як вони починають тремтіти, як тільки бачать тебе. Коли ти вступаєш в бій, ти стаєш променем надії для наших воїнів!\n\nДавай свою відзнаку.", [5] = "Звісно, саме ти заслужиш Око Командування!", ["en"] = "Legendary Heroes", ["tasks"] = { ["Stormpike Insignia Rank 4"] = "відзнака Бурешпилів, ранг 4", ["Stormpike Insignia Rank 4 (Provided)"] = "відзнака Бурешпилів, ранг 4 (видано)" } },
    [7172] = { [1] = "Око Командування", [4] = "Нехай вони почують твій голос, командире! Нехай вони відчують страх. Покажи їм силу Бурешпиля, {ім'я:к}!\n\nПред'яви свою відзнаку.", [5] = "Саме ти маєш привести наші війська до перемоги, командире! Ось твої солдати. Вони будуть виконувати твої прямі накази. Веди їх! Знищ Морозних Вовків.", ["en"] = "The Eye of Command", ["tasks"] = { ["Stormpike Insignia Rank 5"] = "відзнака Бурешпилів, ранг 5", ["Stormpike Insignia Rank 5 (Provided)"] = "відзнака Бурешпилів, ранг 5 (видано)" } },
    [720] = { [1] = "Провісник надії", [2] = "<Шматком крейди на мапі грубо видряпані слова.>\n\n\"Житник,\nвони забирають мене до Ульдамана. Надішли допомогу.\n-Молотопалий\"", [3] = "Знайдіть розвідувача Житника і дайте йому знати, що Молотопалий Ґрез живий.", [5] = "Молотопалий живий?! Це чудесно, {ім'я}!", ["en"] = "A Sign of Hope" },
    [7223] = { [1] = "Уламки броні", [2] = "В Альтерацькій долині постійно лютують жахливі битви, а спорядження, що ми отримуємо з Залізогарту, недостатньо, щоб задовольнити потреби наших досвідчених бійців.\n\nЯкщо ти знайдеш уламки броні на полі бою — принеси їх мені, допоможи нашим бійцям!", [3] = "Принесіть 20 уламків броні Мурґоту Ковоглибу в Дун-Балдар.", [4] = "Ти {стать:приніс:принесла} уламки броні, {ім'я:к}?", [5] = "Це хороші уламки, {ім'я:к}. Я зможу використати їх для створення нового спорядження нашим бійцям.\n\nЯкщо у нас буде вдосталь броні, тоді, можливо, на поле бою зможуть вийти наші найкращі бойові підрозділи!", ["en"] = "Armor Scraps", ["tasks"] = { ["Armor Scraps"] = "уламки броні", ["Armor Scraps (Provided)"] = "уламки броні (видано)" } },
    [7261] = { [1] = "Суверенне право", [2] = "Ми ведемо жорстоку битву в Альтерацькій долині. З одного боку на нас нападають тролі-канібали племені Зимної Сокири, а з іншого — дикий клан Морозних Вовків. І ті, і інші мають бути знищені в ім'я короля Маґні Бронзобородого! Захоплення цієї землі, відбір і переконання мешканців є суверенним і територіальним правом королівства Залізогарт.\n\nНа жаль, солдати не ростуть на деревах! Іди до лейтенанта Гаґґердіна поряд з Альтерацькою долиною та розпочни свій шлях почесної служби Бурешпилю.", [3] = "Вирушайте в Альтерацьку долину в передгір'я Гіллзбраду. Поряд з входом в тунель знайдіть лейтенанта Гаґґердіна та поговоріть з ним.\n\nСлава Бронзобородому!", [5] = "Зробімо це!", ["en"] = "The Sovereign Imperative" },
    [7282] = { [1] = "Братська любов", [2] = "Його потрібно звільнити від страждань, солдате! Він не знає, що робить. Жахлива Королева-Банші зробила його своїм безтямним слугою.\n\nІди далі, через поле Чвар, в глибини земель Морозних Вовків. Знайди мого брата та вбий його. Потрібно покінчити з його стражданнями.", [3] = "Дістаньтесь до земель Морозних Вовків та вбийте командира Луї Філіпса. Коли виконаєте завдання, поверніться до командира Карла Філіпса.", [4] = "Я віддаю цей наказ з болем у серці, солдате.", [5] = "Ти ж не {стать:забув:забула} спалити тіло, так?", ["en"] = "Brotherly Love", ["tasks"] = { ["Commander Louis Philips"] = "командир Луї Філіпс", ["Commander Louis Philips slain"] = "командир Луї Філіпс: убито" } },
    [729] = { [1] = "Розгублений розвідувач", [2] = "Якою честю для мене було, коли майстер Сіровус доручив мені працювати під керівництвом великого розвідувача Сноходня. В академії Залізогарту всі знають про його великі відкриття.\n\nАле він досить... гм... забудькуватий...\n\nМи знайшли рештки великого поселення. Та з-під землі з'явилися жахливі големи та захопили розкопки. Але Сноходень, здавалося, так нічого й не помітив. Я побігла назад, до Аубердіна, за допомогою.\n\nПрошу тебе, вирушай на південь і перевір, чи все гаразд із розвідувачем!", [3] = "Вирушайте на південь, знайдіть розвідувача Сноходня та дізнайтесь, як у нього справи.", [5] = "Холлі, це ти? Мені потрібна допомога, треба розчистити цей камінь. Дай-но мені мою щітку для каменю, здається, я тут щось бачу.\n\nОй, ти не Холлі! Ти, мабуть, не {стать:бачив:бачила} мою щітку?\n\nТа це вже неважливо! Я обіцяв Лізі, що надішлю таємничу скам'янілість. Куди ж поділася Холлі?\n\nСтільки роботи! Де ж ця скам'янілість... і моя щітка... і Холлі...\n\nІ хто ти... Та це не важливо, якщо ти тут, щоб допомогти.\n\nДай знати, коли будеш {стать:готовий:готова} почати пошуки.", ["en"] = "The Absent Minded Prospector" },
    [730] = { [1] = "Негаразди на Темнобережжі?", [2] = "Як приємно бачити {клас:з}, що цікавиться великими археологічними чудесами нашого світу.\n\nНаші друзі з Альянсу часто вважають нашу роботу чимось на зразок хобі. Але багато хто не розуміє, що останні відкриття в Каз-Модані доводять, що велика й могутня сила загрожує всьому Азероту — від Лордерону до Калімдору.\n\nЯ дуже переживаю за свою команду, яку відправив на Темнобережжя. Від них немає звістки вже кілька тижнів.\n\nВирушай в Аубердін і дізнайся, де вони можуть бути.", [3] = "Відправляйтесь на пошуки команди дворфів-археологів в Аубердін.", [5] = "Я дуже рада, що старший археолог Сіровус послав по нас...", ["en"] = "Trouble In Darkshore?" },
    [7301] = { [1] = "Скинуті володарі небес", [2] = "Ми взяли їх у полон, {раса:к}. Я говорю про командирів повітряних сил. Це був запеклий бій у небі, але вони не змогли нас перемогти! На жаль, ми також зазнали втрат — наші найкращі пілоти були збиті під час контратаки на форт Морозних Вовків. Ти маєш з'ясувати, що з ними сталося.\n\nОбшукай західну оглядову вежу та форт Морозних Вовків. Їх востаннє бачили саме там. Ти {стать:повинен:повинна} ретельно оглянути ці місця.", [3] = "Дістаньтесь до земель Морозних Вовків та знайдіть командирів повітряних сил: Слідора, Віпора та Ічмана. Після завершення завдання поверніться до командира Даффі.", [4] = "Є щось, що я хотів би почути?", [5] = "Неймовірно! Ти ж {стать:звільнив:звільнила} їх, так? Так??? Принаймні, ми знаємо, де їх тримали.", ["en"] = "Fallen Sky Lords", ["tasks"] = { ["Ichman's Location Discovered"] = "Розташування Ічмана виявлено", ["Ichman's Location Discovered (Provided)"] = "Розташування Ічмана виявлено (видано)", ["Ichman's Location Discovered slain"] = "Розташування Ічмана виявлено: убито", ["Slidore's Location Discovered"] = "Місцезнаходження Слайдора виявлено", ["Slidore's Location Discovered (Provided)"] = "Місцезнаходження Слайдора виявлено (видано)", ["Slidore's Location Discovered slain"] = "Місцезнаходження Слайдора виявлено: убито", ["Vipore's Location Discovered"] = "Розташування Віпор виявлено", ["Vipore's Location Discovered (Provided)"] = "Розташування Віпор виявлено (видано)", ["Vipore's Location Discovered slain"] = "Розташування Віпор виявлено: убито" } },
    [731] = { [1] = "Розгублений розвідувач", [2] = "Отож, Холлі... а, точно, ти не Холлі. Де ж Холлі?\n\nГаразд, це не має значення. Ми повинні знайти ту щітку для каменю... тобто таємничу скам'янілість! Ми маємо знайти цю скам'янілість. Ліга дослідників у Дарнасі захоче отримати якийсь звіт про мою роботу.\n\nДай мені знати, коли будеш {стать:готовий:готова}, і ми знайдемо цю щітку... тобто скам'янілість! Ми знайдемо щось для звіту Лізі.\n\nНу що, ти {стать:готовий:готова}?", [3] = "Захистіть розвідувача Сноходня під час пошуків таємничої скам'янілості, а потім поверніться до археологині Холлі в Аубердін.", [4] = "Розвідувач живий?", [5] = "Дякувати зіркам, розвідувач Сноходень у безпеці! Я ж казала, що він трохи розсіяний. Не можу повірити, що він захотів залишитися там, де нишпорять всі ці жахливі істоти.", ["en"] = "The Absent Minded Prospector", ["tasks"] = { ["Escort Prospector Remtravel"] = "Ескорт-шукач Remtravel" } },
    [7364] = { [1] = "Нагорода Гномреґана", [2] = "Сам верховний штукар послав мене сюди, на поле бою, щоб захистити моїх братів і сестер. До нас дійшли чутки, що таурени вишукують і вбивають гномів. Найгірше те, що вони виривають пучки славного гном'ячого волосся з тіл полеглих. Ці звірства потрібно зупинити. Ми маємо помститися їм!\n\nЯ хочу, щоб їм відрубали копита, {клас:к}. Принеси мені їхні копита! Доведи, що ти союзник для гномів.", [3] = "Вам доручили вбивати гравців-тауренів в Альтерацькій долині.\n\nВбийте таурена і поверніться до Дірка Хитруна в Дун'Балдар з копитом цього таурена.", [4] = "Наваляй їм, {ім'я:к}. Вони повинні зрозуміти, що гноми не потерплять знущань!", [5] = "*Дірк кидає копито на купу позаду нього.*", ["en"] = "Gnomeregan Bounty", ["tasks"] = { ["Tauren Hoof"] = "копито таурена", ["Tauren Hoof (Provided)"] = "копито таурена (видано)" } },
    [7365] = { [1] = "Реквієм Оленерога", [2] = "Оленеріг віддав наказ. Всі тролі на полі бою повинні бути знищені. Вони повинні відповісти за свої безглузді заяви про те, що нічні ельфи походять від тролів.\n\nВбий їх і принеси мені їхні моджо. Повторюю — мені потрібні їхні моджо.", [3] = "Вам доручено вбивати ворожих гравців-тролів в Альтерацькій долині.\n\nВбийте троля і поверніться до Атраманіс в Дун'Балдар з моджо троля Темного Списа.", [4] = "Я все ще відчуваю запах смердючих тролів.", [5] = "Дякую, {ім'я:к}. Завдяки тобі повітря стало трохи чистішим.", ["en"] = "Staghelm's Requiem", ["tasks"] = { ["Darkspear Troll Mojo"] = "моджо троля Темного Списа", ["Darkspear Troll Mojo (Provided)"] = "моджо троля Темного Списа (видано)" } },
    [7366] = { [1] = "Милосердя архієпископа", [2] = "Архієпископ настільки ж добрий, наскільки й мудрий. Потрібно мати велике серце, щоб ставитися з милосердям до цієї нечисті...\n\n<Командир Філіпс недовірливо хитає головою.>\n\nЗанадто добрий... Занадто добрий.\n\nАрхієпископ просить, щоб ми зглянулися над відреченими та дарували їм швидку й вірну смерть. Для прояву такого милосердя нам потрібно лише дістати їхні чорні, уражені хворобою серця.\n\nПринеси мені серця відречених, щоб урочисто спалити їх в соборі Світла. Поквапся, {ім'я:к}!", [3] = "Вам доручили вбити гравців-відречених в Альтерацькій долині.\n\nВбийте відреченого і поверніться до командира Карла Філіпса (який блукає між лісопильнею і шахтою) з серцем відреченого.", [4] = "Бенедикт! Я лише маленька цяточка в тіні його величі. Слава йому!", [5] = "Слава Бенедикту! Ще одна загублена душа незабаром буде врятована білим палким полум'ям світла!\n\nВперед, солдате! Ми маємо врятувати їх всіх!", ["en"] = "The Archbishop's Mercy", ["tasks"] = { ["Forsaken Heart"] = "серце відреченого", ["Forsaken Heart (Provided)"] = "серце відреченого (видано)" } },
    [738] = { [1] = "Знайти Аґмонда", [2] = "Розвідувач Аґмонд завідував нашими розкопками у Безплідних краях, на південному заході. Я кажу \"завідував\", бо... ну, я не мав від нього звісток вже кілька тижнів. Мені потрібно, щоб ти {стать:знайшов:знайшла} Аґмонда, і тоді я зможу отримати його звіт.\n\nОстаннє, що я чув — Аґмонд був на найпівденнішій ділянці розкопок у Безплідних краях за фортецею Анґора. Я б почав шукати його там.", [3] = "Знайдіть Аґмонда.", [5] = "Мабуть, це скелет бідолашного Аґмонда. Його тіло розтрощене, а кістки начисто обдерті.", ["en"] = "Find Agmond" },
    [7382] = { [1] = "Коррак Безсмертний", [2] = "Щось тут не так... Хтось додумався спалити труп Коррака? Ці тролі не зупиняться ні перед чим, щоб відродити свого занепалого ватажка, як це часто роблять синьошкірі язичницькі людо-звірі.\n\nПросто будь напоготові, {ім'я:к}. Не лякайся несподіваної появи Коррака. І якщо це станеться, я хочу, щоб ти {стать:стратив:стратила} його та {стать:спалив:спалила} тіло дотла.\n\nДля впевненості, перш ніж підпалити його тіло, відрубай йому голову і принеси мені череп.", [3] = "Якщо Коррак Кроволютий з'явиться на полі Чвар, знайдіть його і знищте.\n\nПринесіть череп Коррака лейтенанту Гаґґердіну в передгір'я Гіллзбраду.", [4] = "Ти {стать:вбив:вбила} Коррака Кроволютого, {клас:к}? Розвідники доповіли, що він знаходиться десь на полі Чвар.", [5] = "Гарна робота, {ім'я:к}. Тепер навіть наймогутніша магія не зможе воскресити Коррака. Ти {стать:знищив:знищила} головну загрозу Альтерацької долини, солдате.", ["en"] = "Korrak the Everliving", ["tasks"] = { ["Skull of Korrak"] = "череп Коррака", ["Skull of Korrak (Provided)"] = "череп Коррака (видано)" } },
    [7383] = { [1] = "Вінець Землі", [2] = "Утім, з Тельдрассілем усе було не так добре, як того хотілося. Оленеріг склав ретельні плани, оскільки нове Дерево Життя виросло саме таким, як він мріяв. Але була одна невелика проблема — проблема, яка й стала причиною багатьох неприємностей на Тельдрассілі.\n\nОднак про це мені ще рано говорити. Ти {стать:повинен:повинна} відвідати останній місячний колодязь, розташований на північному заході, на Поляні Оракула. Під гіллям Дерева-оракула ти знайдеш перше, найпотужніше з наших джерел. Наповни фіал його водою та повертайся до мене.", [3] = "Наповніть аметистовий фіал і поверніть його Корітрасу Місяцелюті в Доланаарі.", [4] = "Друїди, Дерево-оракул та Верховний друїд пліч-о-пліч уважно спостерігали за ростом Тельдрассіля. І хоча тепер в нас є новий дім, безсмертне життя ми так і не змогли повернути.", [5] = "Перебувати у присутності Дерева-оракула... це так, неначе сама мудрість набула форми живого створіння. Але на чому я зупинився...\n\nТельдрассіль виріс, і Верховний друїд звернувся до драконів по їхні благословення, якими свого часу вони освятили Нордрассіль. Але Ноздорму, Володар Часу, відмовився дати своє благословення, докірливо звинувативши Фендрала в його нахабності. На підтримку Ноздорму, Алекстраза також відмовила Оленерогові, і без її благословення подальший ріст Тельдрассіля був приречений стати недосконалим та непередбачуваним.", ["en"] = "Crown of the Earth", ["tasks"] = { ["Filled Amethyst Phial"] = "наповнений аметистовий фіал", ["Filled Amethyst Phial (Provided)"] = "наповнений аметистовий фіал (видано)" } },
    [7386] = { [1] = "Жменя кристалів", [4] = "Бої можуть тривати кілька днів або тижнів. В цей час не забувай збирати кристали шторму в Морозних Вовків.\n\nКенарійське Коло буде раде отримати подібні дарунки, {ім'я:к}.", [5] = "Молодець, {ім'я:к}. Я використаю силу цих чар для підсилення вже зібраної магії. Коли сили буде достатньо, я сфокусую її та викличу повелителя лісу, щоб він допоміг нам.", ["en"] = "Crystal Cluster", ["tasks"] = { ["Storm Crystal"] = "кристал шторму", ["Storm Crystal (Provided)"] = "кристал шторму (видано)" } },
    [739] = { [1] = "Мурдалок", [2] = "Сліди Аґмонда ведуть із заходу. Судячи з кривавих плям на скелях та піску, дворф проповз чималу відстань.\n\nА тут він помер.\n\nПри ретельному огляді на шматку піщанику ви помічаєте грубо нашкрябане слово \"Мурдалок\".\n\nПрямо поряд з мертвою рукою Аґмонда.", [3] = "Знищте вбивцю Аґмонда, Мурдалока.\n\nУбийте 12 каменесклепих кісткохрустів.\n\nВідзвітуйте розвідувачеві Залізоплету в Лох-Модані.", [4] = "Є звістка про долю Аґмонда? Ти його {стать:знайшов:знайшла}?", [5] = "Це гірка звістка, {ім'я}. Але Аґмонд мав сильну руку та славно управлявся з молотом, а його череп був таким міцним, як ні в кого іншого! Хоча його і вбили ці прокляті троги, я впевнений, що він забрав багатьох з них із собою.", ["en"] = "Murdaloc", ["tasks"] = { ["Murdaloc"] = "Мурдалок", ["Murdaloc slain"] = "Мурдалок: убито", ["Stonevault Bonesnapper"] = "каменесклепий кісткохруст", ["Stonevault Bonesnapper slain"] = "каменесклепий кісткохруст: убито" } },
    [74] = { [1] = "Легенда про Сталвана", [2] = "В скрині ви знаходите різні предмети: вкриті пилом сімейні реліквії, портрет, кілька мисливських трофеїв та старі книги. Вже на самому дні, під глиняною вазою, ви знаходите сторінку, вирвану зі щоденника.", [3] = "Наступна підказка міститься на знайденій вами вирваній сторінці щоденника.", [4] = "Що там у тебе? Я не бачу. У мене дуже поганий зір. Поклади мені в руки.", [5] = "Я ледве можу розібрати букви, але почерк нагадує мені щось. Так, я бачив щось подібне до того, як мій зір остаточно зіпсувався.", ["en"] = "The Legend of Stalvan", ["tasks"] = { ["A Torn Journal Page"] = "вирвана сторінка щоденника", ["A Torn Journal Page (Provided)"] = "вирвана сторінка щоденника (видано)" } },
    [7402] = { [1] = "РОЗШУКУЮТЬСЯ: Орки!", [2] = "За наказом капрала Нореґа Бурешпиля, кожен боєздатний солдат Бурешпиля зобов'язаний вбити хоч одного ворожого орка на полі бою.\n\nСолдати повинні витягти ікло або зуб з пащі ворога і принести його як доказ своєї перемоги.\n\nНе забудьте одягти захисні рукавиці.", [3] = "Вам доручили вбивати ворожих гравців-орків в Альтерацькій долині.\n\nВбийте орка і віднесіть його зуб капралу Нореґу Бурешпилю в Дун-Балдар.", [4] = "Тобі потрібні затискачі, щоб виривати зуби?", [5] = "Добре, {ім'я:к}. Ці зуби їм вже не знадобляться.", ["en"] = "WANTED: Orcs!", ["tasks"] = { ["Orc Tooth"] = "зуб орка", ["Orc Tooth (Provided)"] = "зуб орка (видано)" } },
    [7482] = { [1] = "Ельфійські легенди", [2] = "Кілька років тому самотній ельфійський майстер, на ім'я Тельмій Снохочий втік зі своєї спустошеної батьківщини, прихопивши з собою кілька стародавніх ельфійських артефактів.\n\nПошуки цього загубленого майстра привели нас від руїн Квел'Таласа, через Палаючий степ та великі морські простори в Фералас.\n\nМи підозрюємо, що ельф шукав притулок в залах Ельдре'Таласа (нині відомого як Грізний Молот).\n\nТи {стать:повинен:повинна} знайти його, {клас:к}. Живим чи мертвим, але знання, які він забрав, необхідно повернути!", [3] = "Знайдіть Тельмія Снохочого в Грізному Молоті. Розкажіть дослідниці Руношип в Перомісяці про все, що зможете знайти.", [4] = "Мій напарник — таурен-мудрець, Королуск, вербує своїх союзників для виконання цього завдання.", [5] = "Шкода... Оце так трагедія. Кажеш, всі речі втрачено? І ти не {стать:знайшов:знайшла} жодних слідів Тельмія, так?", ["en"] = "Elven Legends", ["tasks"] = { ["Master Telmius Dreamseeker Found"] = "Знайдено майстра Тельміуса, шукача снів" } },
    [7495] = { [1] = "Перемога Альянсу", [2] = "Ви здійснили неможливе. Мертва матір чорних драконів лежить біля ваших ніг. Візьміть її голову та віднесіть верховному лорду.", [3] = "Принесіть голову Оніксії верховному лорду Болвару Фордраґону в Штормовій.", [4] = "Ох, клянусь бородою Утера...", [5] = "Багато років я перебував під впливом її гіпнотичного погляду. Та нарешті, правосуддя здійснено, а честь Штормовію відновлено. Сьогодні ми святкуємо велику перемогу!", ["en"] = "Victory for the Alliance", ["tasks"] = { ["Head of Onyxia"] = "голова Оніксії", ["Head of Onyxia (Provided)"] = "голова Оніксії (видано)" } },
    [7496] = { [1] = "Святкування хороших часів", [2] = "Йди до майора Маттінґлі в Долину Героїв, {ім'я}. Він чекатиме на тебе...", [3] = "Відшукайте майора Маттінґлі в Долині Героїв.", [5] = "Мало хто удостоюється такої честі, {ім'я}. Прошу, обери собі винагороду і ми почнемо святкування.", ["en"] = "Celebrating Good Times" },
    [7497] = { [1] = "Все тільки починається", [5] = "То ти не тільки вбивця драконів, а ще й {стать:майстер:майстриня} шкірництва? Ти не перестаєш мене дивувати, {ім'я}. Я вражений.\n\nПрошу, прийми цей дар в знак моєї вдячності. Ці знання допоможуть тобі, якщо ти збираєшся покінчити з родом чорних драконів.\n\nСтвори плащ з луски матері чорних драконів. Він захистить тебе і твоїх союзників від нищівного дихання повелителя Чорнокамінної гори... Нефаріана.", ["en"] = "The Journey Has Just Begun" },
    [76] = { [1] = "Яшмова шахта", [2] = "Завдяки тобі ми знаємо, що Бездонна копальня кишить кобольдами. Тепер треба розвідати більш віддалену шахту — Яшмову.\n\nОглянь її на наявність кобольдів. Рухайся на схід по дорозі, поки не дістанешся вежі Азори. Від вежі поверни на північ, і в передгір'ї знайдеш Яшмову шахту.", [3] = "Дослідіть Яшмову шахту, а потім поверніться з доповіддю до маршала Дугана у Злотохрестя.", [4] = "Вітаю, {ім'я:к}. Що ти можеш повідомити? Ти {стать:дослідив:дослідила} Яшмову шахту?", [5] = "Кобольди в Яшмовій шахті, кажеш? Прокляття! Ситуація погіршується з кожною хвилиною!\n\nДякую за доповідь, {ім'я:к}. Але хотілося б, щоб ці новини були хорошими.", ["en"] = "The Jasperlode Mine", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Scout through the Jasperlode Mine"] = "Дослідіть Яшмову шахту" } },
    [7638] = { [1] = "Лорд Сивенко Тінелом", [2] = "Прийшов твій час, {ім'я:к}, отримати те, чого ти певно давно {стать:чекав:чекала} — твого бойового коня.\n\nПоговори з лордом Сивенком Тінеломом, він тут, в соборному районі Штормовію. Він допоможе тобі не тільки дізнатись більше про вірного паладинського скакуна, але й допоможе тобі його отримати.\n\nНехай тобі щастить в цьому випробуванні. Заради Світла, {стать:благородний брате:благородна сестро}!", [3] = "Поговоріть з лордом Сивенком Тінеломом на соборній площі Штормовію.", [5] = "Радий бачити тебе, {ім'я:к}. Знаю, ти давно {стать:хотів:хотіла} отримати бойового коня. І ось прийшов твій час.\n\nТебе звісно чекає безліч різноманітних випробувань, та найголовніше — твоя рішучість перед численними перешкодами. Це будуть не навчальні завдання — твоєму досвіду вони вже не личать. Тобі доведеться вирвати свого майбутнього компаньйона з лап того самого зла, боротьбі з яким ти {стать:присвятив:присвятила} своє життя.\n\nБережи себе, твій час настав.", ["en"] = "Lord Grayson Shadowbreaker" },
    [77568] = { [1] = "Сила мисливця", [2] = "Мисливець черпає силу зі свого зв'язку та поваги до всіх істот, а не лише до своїх домашніх улюбленців. Ви полюватимете та вбиватимете багатьох звірів на службі Альянсу, але навіть у бою ви повинні поважати свого ворога.\n\nМоя попередня учениця використовувала містичну руну для посилення своїх навичок, але нерозумно спробувала потренуватися на найбільшому з павуків у печері на півночі, істоті, яку ми назвали Гітісс Мерзенна. Її неповага призвела до її загибелі.\n\nУбийте Гітісс, але не недооцінюйте її силу.", [3] = "Переможіть Гітісса Мерзенного в Печері Тіньових Ниток і знайдіть втрачену руну. Вивчіть руну, а потім поверніться до Аянні Вічна Стрічка в Тіньову Долину.", [4] = "Коли вб'єш Гітісса, відшукай руну та вивчи її магію.", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "A Hunter's Strength" },
    [77571] = { [1] = "Реліквії Калдорай", [2] = "Калдорей — стародавній народ, і наші втрачені реліквії можна знайти по всьому Азероту. За допомогою цих реліквій духи можуть навчити вас способам зміцнити ваш зв'язок зі Сном.\n\nГрелкіни вкрали одну таку реліквію. Убийте їх і поверніть реліквію, а потім дотримуйтесь її вказівок, щоб вивчити нову бойову техніку. Поверніться до мене, коли зробите це.", [3] = "Відіберіть реліквію у грелкіна в Тіньоглені. Дотримуйтесь вказівок реліквії, щоб вивчити нову здібність, а потім доповідайте Марданту Стронгуку.", [4] = "Чого тебе навчила ця реліквія?", [5] = "Молодець, {ім'я}. Застосування вивченої вами руни до вашого спорядження надасть вам нові потужні здібності.\n\nШукайте більше наших втрачених реліквій під час своїх подорожей.", ["en"] = "Relics of the Kaldorei" },
    [77573] = { [1] = "Робота на другому поверсі", [2] = "Я підготував для тебе тренувальну вправу, {ім'я}. На даху цієї будівлі є ідол сови. Ти маєш бачити його з південного входу. Усередині ідола є прихований відсік, де вигравірувана руна.\n\nПроберися на дах, знайди та запам'ятай руну, заховану в ідолі, і повернися до мене.", [3] = "Зберіть руну з прихованого ідола, а потім використовуйте її, щоб вивчити нову здібність. Після цього поверніться до Фрахуна Шепоту Тіні.", [4] = "Ви знайшли руну?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Second-Story Work" },
    [77574] = { [1] = "Медитація на Елюну", [2] = "Вступ до Альянсу зміцнив наш народ, але ми не повинні забувати, що ми — калдорейці. Наш зв'язок з Елун лежить в основі нашого єства.\n\nОчисти свій розум, {ім'я}, і зосередься на моєму голосі. Я поділюся з тобою давнім спогадом нашого роду. Іди до місячної криниці на півночі та стань на коліна у священних водах, щоб помедитувати над таємницями Елун. Як тільки ти зосередиш свої думки, ти зможеш осмислити цей спогад і вивчити нову техніку. Повернися до мене, коли зробиш це.", [3] = "Станьте на коліна біля місячної криниці, щоб помедитувати на Елюну, потім скористайтеся спогадом, щоб вивчити нову здатність. Після цього поверніться до Шанди в Тіньову Долину.\n\nНаданий предмет:", [5] = "Елун, ймовірно, подарує вам більше спогадів під час ваших подорожей. Ви можете медитувати біля місячних колодязів по всьому Азероту, щоб очистити свої думки та інтерпретувати ці спогади.\n\nДля розуміння складніших видінь може знадобитися допомога наших товаришів-священиків з Альянсу. Не бійтеся вчитися у їхньої віри, {ім'я}. Тіранда вчить, що Святе Світло, якому поклоняються люди, та Світло Елун тісно пов'язані.", ["en"] = "Meditation on Elune", ["tasks"] = { ["Memory of a Troubled Acolyte"] = "Пам'ять проблемного аколіта" } },
    [77575] = { [1] = "Серед затінених павутин", [2] = "Воїни Альянсу можуть багато чого навчити вас, але ви також повинні самостійно шукати нові техніки.\n\nНа півночі є печера, кишаща павуками-павуками. Інший молодий воїн наважився зазирнути в печеру деякий час тому і більше не повернувся. Він експериментував з гравіюванням містичних рун на своєму спорядженні, щоб покращити свою бойову майстерність.\n\nЗнайдіть руну серед павуків і самостійно вивчіть цю техніку.", [3] = "Знищи павуків-павуків у Печері Тіньових Ниток та знайдіть втрачену руну. Вивчіть руну, а потім поверніться до Алісії в Тіньову Долину.", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Amidst the Shadowed Webs" },
    [77616] = { [1] = "Втрачена руна", [2] = "Воїни Альянсу можуть багато чого тебе навчити, але ти також повинен самостійно шукати нові техніки.\n\nЩе одна молода воїнка нещодавно вирушила до шахти Ехо-Рідж. Вона експериментувала з гравіюванням містичних рун на своєму спорядженні, щоб покращити свою бойову майстерність.\n\nЯ підозрюю, що вона була приголомшена, коли кобольди захопили шахту. Знайди руну серед кобольдів і сам вивчи цю техніку.", [3] = "Знайдіть загублену руну в шахті Ехо-Рідж та використовуйте її, щоб вивчити нову здібність, а потім доповідайте Ллейну Бешеру в Нортширі.", [4] = "Ти знайшов руну?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "The Lost Rune" },
    [77617] = { [1] = "Реліквії Світла", [2] = "Реліквії Світла можна знайти по всьому Азероту. Ці реліквії, зокрема Лібрами, які керували нашим орденом з моменту його заснування, можуть допомогти вам зміцнити ваш зв'язок зі Світлом.\n\nОдин такий лібрам зберігався в архівах Абатства, але його викрали бандити Дефіас на сході. Поверніть лібрам, потім вивчіть його та дотримуйтесь його вказівок, щоб вивчити нову бойову техніку. Поверніться до мене, коли зробите це.", [3] = "Відновіть лібрам та дотримуйтесь його вказівок, щоб вивчити нову здібність, а потім поверніться до брата Саммуеля в Нортшир.", [4] = "Що тобі відкрила бібліотека, {ім'я}?", [5] = "Молодець, {ім'я}. Застосування вивченої вами руни до вашого спорядження надасть вам нові потужні здібності.\n\nШукайте більше цих реліквій під час своїх подорожей.", ["en"] = "Relics of the Light" },
    [77618] = { [1] = "Тричі вкрадено", [2] = "Мені соромно зізнатися, {ім'я}, але ці покидьки з Дефіасу мене наздогнали. Вони вкрали магічну руну, яку я... е-е, «позичив» з архівів Абатства. Я думав, що це дасть мені якусь перевагу в хаосі, але не міг зрозуміти, як це зробити.\n\nПробирайся на схід і спробуй витягнути її з їхнього сховища, добре? І спробуй використати руну сам, коли знайдеш. Здається, ти дуже любиш читати. Без образ.", [3] = "Знайдіть втрачену руну з таборів Дефіаса та використовуйте її для вивчення нової здатності, а потім поверніться до Йоріка Керрідана в Нортшир.", [4] = "Пощастило, {ім'я}?", [5] = "Гарна крадіжка, {ім'я}. Вважай цю руну подарунком від тебе самого.\n\nЯкщо брат Пакстон запитає, то у нас ніколи не було цієї розмови, так?", ["en"] = "Thrice Stolen" },
    [77619] = { [1] = "Медитація на світлі", [2] = "Світло показало мені твоє майбутнє, борючись з кобольдами в шахті Ехо-Рідж. У шахті Світло подарує тобі спогад про минуле. Як тільки це тобі відкриється, повернися до Абатства та стань на коліна в цих залах, щоб поміркувати над таємницями Світла.\n\nЯк тільки ти зосередиш свої думки, ти зможеш осмислити цей спогад і вивчити нову техніку. Повернися до мене, коли зробиш це.", [3] = "Убийте кобольдів у шахті Ехо-Рідж, щоб отримати спогад. Станьте на коліна в абатстві Нортшир, щоб помедитувати на світлі, а потім використовуйте спогад, щоб вивчити нову здібність. Після цього поверніться до жриці Анетти.", [4] = "Що тобі відкрило Світло?", [5] = "Оскільки Світло відкриває вам більше видінь, ви завжди можете медитувати у священних місцях, щоб очистити свої думки та споглядати ці таємниці.\n\nЯ також передбачив, що ваш шлях приведе вас до спілкування з нашими ельфійськими союзниками в Калімдорі. Дізнавшись більше про їхні цікаві ритуали поклоніння місяцю, ми можемо колись також привести їх до Світла.", ["en"] = "Meditation on the Light" },
    [77620] = { [1] = "Дослідження правопису", [2] = "Я навчу тебе всього, чого можу, {ім'я}, але твої власні дослідження приведуть до вражаючої сили. Вивчення нотаток, залишених найвидатнішими архімагами Азероту, – чудовий початок. Архіви Абатства колись містили безліч нотаток про таємні дослідження, але їх викрали агенти Дефіаса.\n\nВідшукай нотатки про заклинання у бандитів на сході та скористайся цим посібником, щоб розшифрувати їх. Повернися до мене, як тільки твої дослідження будуть успішними.", [3] = "Зберіть дослідницькі нотатки від бандитів з Дефіаса та використовуйте їх для вивчення нового заклинання, а потім поверніться до Хелдена Бремена в Нортширі.", [4] = "Як просуваються ваші дослідження?", [5] = "Молодець, {ім'я}. Візьми ці Чари Розуміння. Вони допоможуть тобі розшифрувати будь-які інші таємні письмена, які ти знайдеш.\n\nПродовжуй шукати нотатки із заклинаннями по всьому Азероту та використовуй їх для подальшого дослідження. Якщо тобі потрібно більше чарів, відвідай продавця реагентів.", ["en"] = "Spell Research", ["tasks"] = { ["Comprehension Primer"] = "Посібник з розуміння" } },
    [77621] = { [1] = "Вкрадена влада", [2] = "Я експериментував з новим типом магії – руною, яка може направляти енергію скверни для підживлення потужних заклинань. Я б поділився цією силою з тобою, але мої нотатки вкрали минулої ночі. Підозрюю, що в цьому винні бандити, які називають себе «Дефіас».\n\nІди на схід і подивися, чи зможеш ти знайти мою руну, заховану серед їхніх речей. Вивчи її магію та доповідай мені. Я хотів би, щоб мій експеримент був застосований.", [3] = "Знайдіть руну в таборах Дефіаса на сході та використовуйте її, щоб вивчити нову здібність, а потім поверніться до Друзілли Ла Саль у Нортширі.", [4] = "Ну що? Є якийсь прогрес?", [5] = "Здається, ти добре звик до цієї нової магії, {ім'я}. Знайди більше таких рун і вигравіюй їх на своєму спорядженні, щоб мати нові здібності проти тих, хто тобі протистоїть.\n\nКолись, можливо, твоя сила навіть затьмарить мою власну.", ["en"] = "Stolen Power" },
    [77655] = { [1] = "Втрачена руна", [2] = "Воїни Альянсу мають багато чого навчити тебе, {ім'я}, але ти також повинен самостійно шукати нові техніки.\n\nНа південь відсюди є печера, повна тролів Морозногривих. Ще один воїн-початківець наважився зайти всередину деякий час тому, але так і не повернувся. Він експериментував з гравіюванням містичних рун на своєму спорядженні, щоб покращити свою бойову майстерність.\n\nЗнайдіть руну серед тролів, один з них, ймовірно, носить її, і самостійно вивчіть цю техніку. Поверніться до мене, коли зробите це.", [3] = "Знайдіть загублену руну, яку носить троль Морозногривий у Долині Холодного Рідж. Використайте її, щоб вивчити нову здібність, а потім доповідайте Трану Хорману в Анвілмарі.", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "The Lost Rune" },
    [77656] = { [1] = "Втрачена руна", [2] = "Воїни Альянсу мають багато чого навчити тебе, {ім'я}, але ти також повинен самостійно шукати нові техніки.\n\nНа південь відсюди є печера, повна тролів Морозногривих. Ще один воїн-початківець наважився зайти всередину деякий час тому, але так і не повернувся. Він експериментував з гравіюванням містичних рун на своєму спорядженні, щоб покращити свою бойову майстерність.\n\nЗнайдіть руну серед тролів, один з них, ймовірно, носить її, і самостійно вивчіть цю техніку. Поверніться до мене, коли зробите це.", [3] = "Знайдіть загублену руну, яку носить троль Морозногривий у Долині Холодного Рідж. Використайте її, щоб вивчити нову здібність, а потім доповідайте Трану Хорману в Анвілмарі.", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "The Lost Rune" },
    [77657] = { [1] = "Реліквії Світла", [2] = "Реліквії Світла можна знайти по всьому Азероту. Ці реліквії, зокрема Лібрами, які керували нашим орденом з моменту його заснування, можуть допомогти вам зміцнити ваш зв'язок зі Світлом.\n\nМи зберігали один такий лібрам у наших архівах, але його вкрали тролі Морозногривих. Злодій, ймовірно, досі носить його з собою. Поверніть лібрам і дотримуйтесь його вказівок, щоб вивчити нову бойову техніку. Поверніться до мене, коли зробите це.", [3] = "Поверніть вкрадений лібрам, якого ніс троль Морозногривий у Долині Холодного Рідж. Дотримуйтесь його вказівок, щоб вивчити нову здібність, а потім поверніться до Бромоса Грумнера в Анвілмар.", [4] = "Що тобі відкрила бібліотека, {ім'я}?", [5] = "Молодець, {ім'я}. Застосування вивченої вами руни до вашого спорядження надасть вам нові потужні здібності.\n\nШукайте більше цих реліквій під час своїх подорожей.", ["en"] = "Relics of the Light" },
    [77658] = { [1] = "Тричі вкрадено", [2] = "Мені соромно зізнатися, {ім'я}, але ці виродки з Морозної Гриви мене випередили. Вони вкрали магічну руну, яку я... е-е, «позичив» зі скарбниці. Я думав, що це дасть мені перевагу, так би мовити, але я не міг зрозуміти, як це зробити.\n\nІди до їхньої печери на півдні та подивися, чи зможеш ти витягнути її з їхнього сховища, добре? Коли знайдеш, спробуй використати руну сам. Здається, ти дуже любиш читати. Без образ.", [3] = "Знайдіть викрадену руну з печери тролів Морозногривого в Долині Холодного Рідж. Використайте її, щоб вивчити нову здібність, а потім поверніться до Солма Харгріна в Анвілмар.", [5] = "Гарна крадіжка, {ім'я}. Вважай цю руну подарунком від тебе самого.\n\nЯкщо хтось запитає, то у нас ніколи не було цієї розмови, так?", ["en"] = "Thrice Stolen" },
    [77659] = { [1] = "Тричі вкрадено", [2] = "Мені соромно зізнатися, {ім'я}, але ці виродки з Морозної Гриви мене випередили. Вони вкрали магічну руну, яку я... е-е, «позичив» зі скарбниці. Я думав, що це дасть мені перевагу, так би мовити, але я не міг зрозуміти, як це зробити.\n\nІди до їхньої печери на півдні та подивися, чи зможеш ти витягнути її з їхнього сховища, добре? Коли знайдеш, спробуй використати руну сам. Здається, ти дуже любиш читати. Без образ.", [3] = "Знайдіть викрадену руну з печери тролів Морозногривого в Долині Холодного Рідж. Використайте її, щоб вивчити нову здібність, а потім поверніться до Солма Харгріна в Анвілмар.", [5] = "Гарна крадіжка, {ім'я}. Вважай цю руну подарунком від тебе самого.\n\nЯкщо хтось запитає, то у нас ніколи не було цієї розмови, так?", ["en"] = "Thrice Stolen" },
    [77660] = { [1] = "Похід через печери", [2] = "Мисливці — витривалий народ, {ім'я}, навіть серед гномів. Ми вирушаємо по Азероту досліджувати невідомі землі та полювати на всіляку небезпечну та екзотичну здобич. Багато разів у своїй подорожі ви опинятиметеся самі на ворожій території, виживаючи лише завдяки своїй кмітливості.\n\nТролі Морозногриві вкрали у нас руну великої сили. Ймовірно, вони сховали її у своїй печері на півдні. Знайдіть руну та використовуйте її, щоб вивчити нову бойову техніку. Поверніться до мене, як тільки зробите це.", [3] = "Знайдіть викрадену руну з печери тролів Морозногривого племені в Долині Колдрідж. Використайте руну, щоб вивчити нову здібність, а потім поверніться до Торгаса Грімсона в Анвілмар.", [4] = "Ви знайшли руну {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Trek Through the Caves" },
    [77661] = { [1] = "Медитація на світлі", [2] = "Світло показало мені твоє майбутнє, {ім'я}, у боротьбі з троґгами на південному заході. У скрині ти знайдеш спогад про минуле. Як тільки отримаєш його, повернися сюди та стань на коліна перед Вівтарем Світла. Медитуй над його таємницями.\n\nКоли ти зосередиш свої думки, ти зможеш осмислити цей спогад і вивчити нову техніку. Поговори зі мною, коли зробиш це.", [3] = "Знайдіть спогад про минуле всередині скрині в таборі троггів поблизу Анвілмара. Потім станьте навколішки біля Вівтаря Світла в Анвілмарі, щоб помедитувати на світло, і використовуйте спогад, щоб вивчити нову здібність. Після цього поговоріть з Бренстоком Халдером.", [4] = "Що тобі відкрило Світло, {ім'я}?", [5] = "Оскільки Світло відкриває вам більше видінь, ви завжди можете медитувати у священних місцях, щоб очистити свої думки та споглядати ці таємниці.\n\nЯ також передбачив, що ваш шлях приведе вас до спілкування з нашими ельфійськими союзниками в Калімдорі. Дізнавшись більше про їхні цікаві ритуали поклоніння місяцю, ми можемо колись також привести їх до Світла.", ["en"] = "Meditation on the Light" },
    [77666] = { [1] = "Вкрадена влада", [2] = "Я експериментував з новим типом магії – руною, яка може направляти енергію скверни для підживлення потужних заклинань. Я б поділився цією силою з тобою, але її вкрав один із цих надокучливих троґів.\n\nНа південному заході є табір цих шкідників-скелелазів. Подивись, чи зможеш знайти мою руну, заховану серед їхніх речей, ймовірно, у якійсь скрині. Як тільки знайдеш, вивчи її магію та повідом мені. Я хотів би, щоб мій експеримент був використаний.", [3] = "Знайдіть руну у групи троггів, що на південний захід від Анвілмара, та використовуйте її, щоб вивчити нову здібність. Потім поверніться до Аламара Грімма в Анвілмар.", [4] = "Ну що, {ім'я}? Є якийсь прогрес?", [5] = "Здається, ти добре звик до цієї нової магії, {ім'я}. Знайди більше таких рун і вигравіюй їх на своєму спорядженні. Використовуй цю силу проти тих, хто тобі протистоїть.\n\nКолись, можливо, твоя сила навіть затьмарить мою власну.", ["en"] = "Stolen Power" },
    [77667] = { [1] = "Дослідження правопису", [2] = "Як маг, дослідження арканів приведе вас до вражаючої сили. Вивчення записів, залишених найвидатнішими магами Азероту, – чудовий початок. Нещодавно я сам деякі знайшов, але їх вкрали ті надокучливі троґи на південному заході.\n\nЗнайдіть записки заклинань у таборі троґів і скористайтеся цим посібником, щоб розібратися в них. Поверніться, коли ваше дослідження буде успішним.", [3] = "Знайдіть викрадені нотатки з заклинаннями в таборі троггів на південний захід від Анвілмара, а потім використовуйте їх, щоб вивчити нову здібність. Після цього поверніться до Маррік Нуррібіт в Анвілмар.", [4] = "Як просуваються ваші дослідження, {ім'я}?", [5] = "Молодець, {ім'я}. Візьми ці Чари Розуміння. Вони допоможуть тобі розшифрувати будь-які інші таємні письмена, які ти знайдеш.\n\nПродовжуй шукати нотатки із заклинаннями по всьому Азероту та використовуй їх для подальшого дослідження. Якщо тобі потрібно більше чарів, відвідай продавця реагентів.", ["en"] = "Spell Research", ["tasks"] = { ["Comprehension Primer"] = "Посібник з розуміння" } },
    [7781] = { [1] = "Повелитель Чорнокамінної гори", [2] = "Вас сповнює знайоме почуття перемоги. Перед вами лежить величезна, вкрита ранами голова Нефаріана. Вам варто віднести її верховному лорду, {стать:чемпіоне:чемпіонко}.", [3] = "Принесіть голову Нефаріана верховному лорду Болвару Фордраґону в Штормовій.", [4] = "Неймовірно!", [5] = "Не буду розповідати, наскільки важлива твоя перемога, {ім'я}, ти й так все розумієш. Цей день увійде в історію. Такої перемоги Альянс не бачив вже багато років!", ["en"] = "The Lord of Blackrock", ["tasks"] = { ["Head of Nefarian"] = "голова Нефаріана", ["Head of Nefarian (Provided)"] = "голова Нефаріана (видано)" } },
    [7782] = { [1] = "Повелитель Чорнокамінної гори", [2] = "Йди в Долину Героїв Штормовію та поговори з фельдмаршалом Камнеміст.", [3] = "Прямуйте в Долину Героїв Штормовію та поговоріть з фельдмаршалом Камнеміст.", [5] = "<Фельдмаршал Камнеміст кланяється.>\n\nОбери свою нагороду і нехай розпочнеться свято!", ["en"] = "The Lord of Blackrock" },
    [7791] = { [1] = "Пожертва вовняного полотна", [4] = "Зараз ми приймаємо вовняне полотно. Щедра пожертва в шістдесят шматків вовняного полотна, без сумніву, позитивно позначиться на відношенні Штормовію до тебе і твоїх діянь. Наші сховища можуть прийняти від тебе шістдесят шматків вовняного полотна; ми розраховуємо і на пожертви інших.\n\nЯкщо в тебе є шістдесят шматків вовняного полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Wool", ["tasks"] = { ["Wool Cloth"] = "вовняне полотно", ["Wool Cloth (Provided)"] = "вовняне полотно (видано)" } },
    [7792] = { [1] = "Пожертва вовняного полотна", [4] = "Зараз ми приймаємо вовняне полотно. Щедра пожертва в шістдесят шматків вовняного полотна, без сумніву, позитивно позначиться на відношенні Дарнасу до тебе і твоїх діянь. Наші сховища можуть прийняти від тебе шістдесят шматків вовняного полотна; ми розраховуємо і на пожертви інших.\n\nЯкщо в тебе є шістдесят шматків вовняного полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Wool", ["tasks"] = { ["Wool Cloth"] = "вовняне полотно", ["Wool Cloth (Provided)"] = "вовняне полотно (видано)" } },
    [7793] = { [1] = "Пожертва шовкового полотна", [4] = "Як і з більшістю інших тканин, наші запаси шовку зараз малі як ніколи. Наші сховища можуть прийняти від тебе шістдесят шматків шовкового полотна; ми розраховуємо і на пожертви інших, тому нам має вистачити на перший час.\n\nДодам, що така великодушна пожертва шовку, без сумніву, позитивно позначиться на відношенні нашої спільноти до тебе! Якщо в тебе є шістдесят шматків шовкового полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Silk", ["tasks"] = { ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [7794] = { [1] = "Пожертва маготканого полотна", [4] = "Маготканого полотна замало, і ми просимо твоєї допомоги, щоб поповнити наші запаси! Розраховуючи на допомогу інших, ми очікуємо пожертву у розмірі 60 відрізків маготканого полотна, щоб ми змогли досягти нашої цілі. Така щедрість не залишиться непоміченою в Штормовії, запевняю тебе!\n\nЯкщо в тебе є шістдесят шматків маготканого полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Mageweave", ["tasks"] = { ["Mageweave Cloth"] = "маготкане полотно", ["Mageweave Cloth (Provided)"] = "маготкане полотно (видано)" } },
    [7795] = { [1] = "Пожертва рунічного полотна", [4] = "{Ім'я}, твоя допомога тканиною нам дуже відчутна. Ми важко працюємо, щоб поповнити запаси, але все одно, залишки рунічного полотна критично малі. Воно нам вкрай необхідне. І ми сподіваємося, що ти нам допоможеш, як і раніше.\n\nЯкщо можеш, прошу, принеси мені стільки рунічного полотна, скільки зможеш. Для першої пожертви ми приймаємо шістдесят шматків, а потім можна буде пожертвувати більше.", [5] = "Неймовірно! Ця тканина негайно піде в роботу, я тебе запевняю. Ще раз дякую за допомогу! Без тебе ми б не впоралися.\n\nЯ з радістю прийму від тебе більше рунічного полотна. Приходь до мене час від часу, я особисто слідкуватиму, щоб твої пожертви не пройшли непоміченими.", ["en"] = "A Donation of Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7796] = { [1] = "Більше рунічного полотна", [4] = "Ще раз вітаю, {ім'я}! Нам завжди потрібна рунічна тканина і ми завжди готові прийняти більше, якщо ти {стать:готовий:готова} її віддати. За додаткову пожертву з двадцяти рунічних полотен я подбаю про те, щоб у Штормовії відзначили твої постійні зусилля.\n\nЯкщо ти будеш {стать:готовий:готова} віддати стопку рунічного полотна, я з радістю прийму її.", [5] = "{ім'я} — без таких героїв, як ти, які віддані Штормовію, нам, безперечно, було б тяжко. Дякуємо за твої постійні старання!", ["en"] = "Additional Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7798] = { [1] = "Пожертва шовкового полотна", [4] = "Як і з більшістю інших тканин, наші запаси шовку зараз малі як ніколи. Наші сховища можуть прийняти від тебе шістдесят шматків шовкового полотна; ми розраховуємо і на пожертви інших, тому нам має вистачити на перший час.\n\nДодам, що така великодушна пожертва шовку, без сумніву, позитивно позначиться на відношенні нашої спільноти до тебе! Якщо в тебе є шістдесят шматків шовкового полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Silk", ["tasks"] = { ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [7799] = { [1] = "Пожертва маготканого полотна", [4] = "Маготканого полотна замало, і ми просимо твоєї допомоги, щоб поповнити наші запаси! Розраховуючи на допомогу інших, ми очікуємо пожертву у розмірі 60 відрізків маготканого полотна, щоб ми змогли досягти нашої цілі. Така щедрість не залишиться непоміченою в Дарнасі, запевняю тебе!\n\nЯкщо в тебе є шістдесят шматків маготканого полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Mageweave", ["tasks"] = { ["Mageweave Cloth"] = "маготкане полотно", ["Mageweave Cloth (Provided)"] = "маготкане полотно (видано)" } },
    [7800] = { [1] = "Пожертва рунічного полотна", [4] = "{Ім'я}, твоя допомога тканиною нам дуже відчутна. Ми важко працюємо, щоб поповнити запаси, але все одно, залишки рунічного полотна критично малі. Воно нам вкрай необхідне. І ми сподіваємося, що ти нам допоможеш, як і раніше.\n\nЯкщо можеш, прошу, принеси мені стільки рунічного полотна, скільки зможеш. Для першої пожертви ми приймаємо шістдесят шматків, а потім можна буде пожертвувати більше.", [5] = "Неймовірно! Ця тканина негайно піде в роботу, я тебе запевняю. Ще раз дякую за допомогу! Без тебе ми б не впоралися.\n\nЯ з радістю прийму від тебе більше рунічного полотна. Приходь до мене час від часу, я особисто слідкуватиму, щоб твої пожертви не пройшли непоміченими.", ["en"] = "A Donation of Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7801] = { [1] = "Більше рунічного полотна", [4] = "Ще раз вітаю, {ім'я}! Нам завжди потрібна рунічна тканина і ми завжди готові прийняти більше, якщо ти {стать:готовий:готова} її віддати. За додаткову пожертву з двадцяти рунічних полотен я подбаю про те, щоб у Дарнасі відзначили твої постійні зусилля.\n\nЯкщо ти будеш {стать:готовий:готова} віддати стопку рунічного полотна, я з радістю прийму її.", [5] = "{ім'я} — без таких героїв, як ти, які віддані Дарнасу, нам, безперечно, було б тяжко. Дякуємо за твої постійні старання!", ["en"] = "Additional Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7802] = { [1] = "Пожертва вовняного полотна", [4] = "Зараз ми приймаємо вовняне полотно. Щедра пожертва в шістдесят шматків вовняного полотна, без сумніву, позитивно позначиться на відношенні Залізогарту до тебе і твоїх діянь. Наші сховища можуть прийняти від тебе шістдесят шматків вовняного полотна; ми розраховуємо і на пожертви інших.\n\nЯкщо в тебе є шістдесят шматків вовняного полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Wool", ["tasks"] = { ["Wool Cloth"] = "вовняне полотно", ["Wool Cloth (Provided)"] = "вовняне полотно (видано)" } },
    [7803] = { [1] = "Пожертва шовкового полотна", [4] = "Як і з більшістю інших тканин, наші запаси шовку зараз малі як ніколи. Наші сховища можуть прийняти від тебе шістдесят шматків шовкового полотна; ми розраховуємо і на пожертви інших, тому нам має вистачити на перший час.\n\nДодам, що така великодушна пожертва шовку, без сумніву, позитивно позначиться на відношенні нашої спільноти до тебе! Якщо в тебе є шістдесят шматків шовкового полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Silk", ["tasks"] = { ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [7804] = { [1] = "Пожертва маготканого полотна", [4] = "Маготканого полотна замало, і ми просимо твоєї допомоги, щоб поповнити наші запаси! Розраховуючи на допомогу інших, ми очікуємо пожертву у розмірі 60 відрізків маготканого полотна, щоб ми змогли досягти нашої цілі. Така щедрість не залишиться непоміченою в Залізогарті, запевняю тебе!\n\nЯкщо в тебе є шістдесят шматків маготканого полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Mageweave", ["tasks"] = { ["Mageweave Cloth"] = "маготкане полотно", ["Mageweave Cloth (Provided)"] = "маготкане полотно (видано)" } },
    [7805] = { [1] = "Пожертва рунічного полотна", [4] = "{Ім'я}, твоя допомога тканиною нам дуже відчутна. Ми важко працюємо, щоб поповнити запаси, але все одно, залишки рунічного полотна критично малі. Воно нам вкрай необхідне. І ми сподіваємося, що ти нам допоможеш, як і раніше.\n\nЯкщо можеш, прошу, принеси мені стільки рунічного полотна, скільки зможеш. Для першої пожертви ми приймаємо шістдесят шматків, а потім можна буде пожертвувати більше.", [5] = "Неймовірно! Ця тканина негайно піде в роботу, я тебе запевняю. Ще раз дякую за допомогу! Без тебе ми б не впоралися.\n\nЯ з радістю прийму від тебе більше рунічного полотна. Приходь до мене час від часу, я особисто слідкуватиму, щоб твої пожертви не пройшли непоміченими.", ["en"] = "A Donation of Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7806] = { [1] = "Більше рунічного полотна", [4] = "Ще раз вітаю, {ім'я}! Нам завжди потрібна рунічна тканина і ми завжди готові прийняти більше, якщо ти {стать:готовий:готова} її віддати. За додаткову пожертву з двадцяти рунічних полотен я подбаю про те, щоб у Залізогарті відзначили твої постійні зусилля.\n\nЯкщо ти будеш {стать:готовий:готова} віддати стопку рунічного полотна, я з радістю прийму її.", [5] = "{ім'я} — без таких героїв, як ти, які віддані Залізогарту, нам, безперечно, було б тяжко. Дякуємо за твої постійні старання!", ["en"] = "Additional Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7807] = { [1] = "Пожертва вовняного полотна", [4] = "Зараз ми приймаємо вовняне полотно. Щедра пожертва в шістдесят шматків вовняного полотна, без сумніву, позитивно позначиться на відношенні біженців Гномреґану до тебе і твоїх діянь. Наші сховища можуть прийняти від тебе шістдесят шматків вовняного полотна; ми розраховуємо і на пожертви інших.\n\nЯкщо в тебе є шістдесят шматків вовняного полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Wool", ["tasks"] = { ["Wool Cloth"] = "вовняне полотно", ["Wool Cloth (Provided)"] = "вовняне полотно (видано)" } },
    [7808] = { [1] = "Пожертва шовкового полотна", [4] = "Як і з більшістю інших тканин, наші запаси шовку зараз малі як ніколи. Наші сховища можуть прийняти від тебе шістдесят шматків шовкового полотна; ми розраховуємо і на пожертви інших, тому нам має вистачити на перший час.\n\nДодам, що така великодушна пожертва шовку, без сумніву, позитивно позначиться на відношенні нашої спільноти до тебе! Якщо в тебе є шістдесят шматків шовкового полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Silk", ["tasks"] = { ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [78088] = { [1] = "Дивний артефакт", [4] = "Ви щось знайшли у вежі?", [5] = "Ти мав рацію, що приніс це мені, {ім'я}.", ["en"] = "A Strange Artifact" },
    [78089] = { [1] = "Поради від Штормовія", [2] = "Я відчуваю темну силу в цій сфері, але її джерело вислизає від мене. Нам потрібна порада від паладинів Штормовія. Принесіть їм сферу.", [3] = "Зверніться до паладинів Штормовія за порадою щодо сфери.", [4] = "Ти приніс новини з Калімдору?", [5] = "<Стурбовано розглядає кулю>", ["en"] = "Advice From Stormwind", ["tasks"] = { ["Althalaxx Orb"] = "Сфера Альталакс" } },
    [7809] = { [1] = "Пожертва маготканого полотна", [4] = "Маготканого полотна замало, і ми просимо твоєї допомоги, щоб поповнити наші запаси! Розраховуючи на допомогу інших, ми очікуємо пожертву у розмірі 60 відрізків маготканого полотна, щоб ми змогли досягти нашої цілі. Така щедрість не залишиться непоміченою біженцями Гномреґану, запевняю тебе!\n\nЯкщо в тебе є шістдесят шматків маготканого полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Mageweave", ["tasks"] = { ["Mageweave Cloth"] = "маготкане полотно", ["Mageweave Cloth (Provided)"] = "маготкане полотно (видано)" } },
    [78090] = { [1] = "Друга думка", [2] = "Я не впевнений, що думати про цю сферу, {ім'я}. Гадаю, нам знадобиться допомога... спеціаліста.\n\nНам відомо про секту чаклунів, що діє у Штормовії. Офіційно ми заперечуємо присутність чаклунів у місті. Неофіційно, їхні знання можуть бути корисними при взаємодії з демонічними силами.\n\nЗнайдіть представника цих чаклунів і запитайте його думку щодо сфери.", [3] = "Знайдіть святилище чаклунів у Штормовії та попросіть поради щодо сфери.", [4] = "Ти далеко від собору, {клас}. Сподіваюся, ти розумієш, що не маєш тут жодної влади.", [5] = "Тож Срібній Руці потрібна моя допомога? Вона обійдеться недешево.", ["en"] = "A Second Opinion", ["tasks"] = { ["Althalaxx Orb"] = "Сфера Альталакс" } },
    [78091] = { [1] = "Заробляючи свою сіль", [2] = "Я вивчу кулю і розповім тобі, що дізнаюся, але ти спочатку маєш щось для мене зробити.\n\nЧаклуни клану Чорної Скелі використовують спеціально приготовані солі для посилення своїх ритуалів виклику. Збери трохи у орків у Редріджі.\n\nКоли ти повернешся, я поділюся з тобою результатами своїх досліджень.", [3] = "Зберіть 14 Солі Призивача у Призивачів Чорної Скелі в Червоноградських Горах, а потім поверніться до Урсули Делайн у Штормовій.", [4] = "<Чаклун уважно вивчає сферу>", [5] = "А... солі. Я зовсім про них забув.\n\nЦя сфера не схожа ні на що, що я бачив, {ім'я}.", ["en"] = "Earning Your Salt" },
    [78092] = { [1] = "Його потрібно знищити", [2] = "Ця сфера справді пов'язана з могутньою сутністю десь за межами Звивистого Пустоверті. Я не можу передбачити її природу, але відчуваю, як її сприйняття досягає крізь сферу... вивчаючи мене у відповідь.\n\nМені не хочеться визнавати це, {ім'я}, але сферу потрібно знищити.\n\nВона здається невразливою до більшості пошкоджень, але може бути вразливою до зброї могутнього повелителя демонів. Я не впевнений, де ви знайдете таку зброю, але це залишається вашим найкращим варіантом.\n\nУдачі, {ім'я}.", [3] = "Знайдіть спосіб знищити сферу.", [4] = "<Ваше волосся стає дибки, коли вас оточують пекельні енергії>", [5] = "<Ти піднімеш кулю до списа>", ["en"] = "It Must Be Destroyed", ["tasks"] = { ["Althalaxx Orb"] = "Сфера Альталакс" } },
    [78093] = { [1] = "Повернення до Дельгрена", [2] = "<Розбиті залишки кулі лежали біля твоїх ніг. Делґрен захоче побачити, що ти досяг успіху.>", [3] = "Поверніть осколки сфер Делгрену.", [4] = "Ви знайшли спосіб знищити сферу?", [5] = "Це полегшення, {ім'я}. Але хто б не спостерігав за Азеротом крізь ту сферу... у мене таке відчуття, що вони не будуть раді, що її знищили.\n\nСприймай це як мою подяку за твої зусилля. І... будь обережний.", ["en"] = "Return to Delgren", ["tasks"] = { ["Orb Fragments"] = "Фрагменти сфери" } },
    [7811] = { [1] = "Пожертва рунічного полотна", [4] = "{Ім'я}, твоя допомога тканиною нам дуже відчутна. Ми важко працюємо, щоб поповнити запаси, але все одно, залишки рунічного полотна критично малі. Воно нам вкрай необхідне. І ми сподіваємося, що ти нам допоможеш, як і раніше.\n\nЯкщо можеш, прошу, принеси мені стільки рунічного полотна, скільки зможеш. Для першої пожертви ми приймаємо шістдесят шматків, а потім можна буде пожертвувати більше.", [5] = "Неймовірно! Ця тканина негайно піде в роботу, я тебе запевняю. Ще раз дякую за допомогу! Без тебе ми б не впоралися.\n\nЯ з радістю прийму від тебе більше рунічного полотна. Приходь до мене час від часу, я особисто слідкуватиму, щоб твої пожертви не пройшли непоміченими.", ["en"] = "A Donation of Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7812] = { [1] = "Більше рунічного полотна", [4] = "Ще раз вітаю, {ім'я}! Нам завжди потрібна рунічна тканина і ми завжди готові прийняти більше, якщо ти {стать:готовий:готова} її віддати. За додаткову пожертву з двадцяти рунічних полотен я подбаю про те, щоб біженці Гномреґану відзначили твої постійні зусилля.\n\nЯкщо ти будеш {стать:готовий:готова} віддати стопку рунічного полотна, я з радістю прийму її.", [5] = "{ім'я} — без таких героїв, як ти, які віддані біженцям Гномреґану, нам, безперечно, було б тяжко. Дякуємо за твої постійні старання!", ["en"] = "Additional Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [78192] = { [1] = "Таємниці Світла", [2] = "Отже, ви хочете дізнатися більше про Світло? Ви звернулися до потрібного гнома! Лікування, враження, захист – я все це роблю!\n\nЯк щодо практичного уроку? Вирушайте до Ясенеділу та розправтеся з тими зомбі Орди, які поводяться так, ніби це місце їм належить. Світло добре підходить для багатьох речей, але моє улюблене – знищення нежиті!", [3] = "Убийте 7 покинутих травників та 9 покинутих шукачів на північному заході Ясеневого долини, а потім поверніться до Маетри Слагхарт у Дарнасі.", [5] = "Чудова робота! Немає нічого кращого за розпалювання кількох нежиті, щоб налаштуватися на релігійний лад, га?", ["en"] = "Secrets of the Light" },
    [78193] = { [1] = "Таємниці Світла", [2] = "Гаразд, {ім'я}, давайте серйозно. Світло — це не якась богиня, на яку потрібно справити враження, чи дух, з яким потрібно потоваришувати. Воно в кожному з нас! Все, що вам потрібно навчитися, це відчувати його.\n\nПобалуйте себе невеликою подорожжю до Штормовія та відвідайте Собор Світла. Це чудове місце, щоб помолитися та познайомитися зі Світлом. А ця архітектура — видовище, яке варто побачити!", [3] = "Вирушайте до Штормовію та поговоріть з Верховною жрицею Лореною в Соборі Світла.", [5] = "Немає потреби доводити свою гідність, {ім'я}. Світло вітає всіх прохачів у своєму теплі.\n\nНе соромтеся залишатися в цьому святилищі скільки завгодно і медитувати над таємницями Світла.", ["en"] = "Secrets of the Light" },
    [78194] = { [1] = "Таємниці Елуни", [2] = "Приємно бачити, як {раса} цікавиться Елун. Хоча калдорай — її улюблені діти, вона піклується про всіх людей Азероту. Натомість за її благословення ми піклуємося про землю в її ім'я.\n\nНещодавно мені повідомили про порушення природного балансу — у Сутінковому лісі помітили скажених лютих вовків. Проявіть свою повагу до балансу Елун, знищивши їхню популяцію, а потім поверніться до мене з доказами своїх діянь.", [3] = "Зберіть 10 Лап Лютого Вовка у вовків у Смерколіссі.", [4] = "Які новини ви несете?", [5] = "Дякую вам, {ім'я}. Завдяки вашим зусиллям баланс міцніший.", ["en"] = "Secrets of Elune" },
    [78195] = { [1] = "Таємниці Елуни", [2] = "Місячні колодязі містять благословення Елуни, але вони також є символом зв'язків, які ми всі поділяємо. Віднесіть цю склянку води з місячної колодязі Штормовія до тієї, що в Обердіні, на берегах Калімдора. Як тільки води поєднуються, так само поєднається і ваш дух з духом калдорай.", [3] = "Принесіть флакон Сирної до місячної криниці Обердіна.", [5] = "<Сирноя додає воду з флакона до місячної криниці>\n\nЕлуна з тобою, {ім'я}. Коли твої подорожі приведуть тебе до інших місячних криниць, зупинися на мить, і ти можеш отримати її благословення.", ["en"] = "Secrets of Elune" },
    [78287] = { [1] = "Дозвольте мені зробити вам пропозицію", [2] = "Перший пробіг готовий, {ім'я}. Віднеси це до Штормовія та покажи начальству. Хтось, хто може підписати контракт сьогодні!", [3] = "Віднесіть вантаж зброї до Майстра Лісу в Штормовії.", [4] = "Доставка з Брашпиля? Я нічого не замовляв у Брашпилі.", [5] = "Постачальник зброї в Ретчеті? Що ж... Альянсу справді потрібні всі можливі припаси. І ми не хочемо, щоб Орда підписала угоду. Нам слід діяти швидко.", ["en"] = "Let Me Make You An Offer", ["tasks"] = { ["Arms Shipment"] = "Поставка зброї" } },
    [78297] = { [1] = "Ви уклали угоду", [2] = "Я поставив підписи у потрібних місцях, {ім'я}. Віднесіть це назад до Брашпиля та повідомте постачальнику, що Альянс радий співпраці.", [3] = "Поверніть підписаний контракт на закупівлю Гріззбі в Ретчет.", [4] = "Ви закрили угоду?", [5] = "Вони підписали, навіть не домовляючись? Ха! У старого Гріззбі все владнається!\n\nА ти, {ім'я}, був справжнім другом. Ось тобі маленький знак моєї подяки.\n\nА тепер, коли ми офіційно розпочали бізнес, сміливо переглядай мій асортимент спорядження та шукай, чи щось приверне твою увагу. Я навіть зроблю тобі знижку для працівників!", ["en"] = "You've Got Yourself A Deal" },
    [783] = { [1] = "Внутрішня загроза", [2] = "Сподіваюся, що ти туго {стать:затягнув:затягнула} свій пояс, {стать:молодий:молода} {клас:к}, тому що тут у Північнокраї є невиконана робота.\n\nІ я не про фермерство.\n\nВарта Штормовію насилу підтримує тут мир: занадто багато з нас перебувають у далеких краях, і занадто багато загроз нависають усе ближче. І тому ми приймаємо допомогу кожного, хто бажає захищати свій дім. І своїх побратимів.\n\nЯкщо ти тут, щоб відповісти на наш поклик, то поговори з моїм начальником, маршалом Макбрайдом. Він усередині абатства позаду мене.", [3] = "Поговоріть із маршалом Макбрайдом.", [5] = "Чудово! Ще один доброволець. Багато таких, як ти, прибуває в наші ряди останнім часом.\n\nСподіваюся, бійців нам не забракне.\n\nЗемлі людей перебувають під зовнішньою загрозою, і через це багато наших військ перевели за кордон. Що, своєю чергою, дало можливість для корумпованих та безпринципних груп процвітати на наших теренах.\n\nМи воюємо на багатьох фронтах, {ім'я}. Налаштовуйся на довгу кампанію.", ["en"] = "A Threat Within" },
    [7863] = { [1] = "Базовий набір припасів стражів", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в тіснині Пісні Війни.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в тіснині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть дружніми, а бинти — коли почесними.", ["en"] = "Sentinel Basic Care Package" },
    [7864] = { [1] = "Стандартний набір припасів стражів", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в тіснині Пісні Війни.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в тіснині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть дружніми, а бинти — коли почесними.", ["en"] = "Sentinel Standard Care Package" },
    [7865] = { [1] = "Покращений набір припасів стражів", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в тіснині Пісні Війни.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в тіснині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть дружніми, а бинти — коли почесними.", ["en"] = "Sentinel Advanced Care Package" },
    [78916] = { [1] = "Серце порожнечі", [2] = "Жахливий звір Аку'май лежить мертвим. Серед нутрощів та крові його розпухлого трупа захована величезна переливчаста перлина, що кишить непідробною енергією Порожнечі.", [3] = "Принесіть Перлину Чорної Безодні Вартові Світанку Селгорму в Дарнас.", [4] = "{ім'я}, які новини з Блекфатома?", [5] = "Слуга Стародавніх Богів, Аку'май, мертвий. Таке досягнення — гідність справжніх героїв.\n\nЦей об'єкт може бути ключем до набагато глибшого розуміння природи Порожнечі та її впливу на наш світ. Його необхідно негайно вивчити. Дякую, {ім'я}.", ["en"] = "The Heart of the Void", ["tasks"] = { ["Item #209693"] = "Товар №209693" } },
    [78921] = { [1] = "Лиходійство Чорноводних глибин", [2] = "Сила покинула мене. Потрібна твоя допомога!\n\nКолись давно це місце було великим храмом Елуни. Але нещастя призвело до руїн, коли корупція Старого Бога просочилася з-під землі та забруднила священний Місячний Колодязь.\n\nАку'Май, слуга Старого Бога, піднявся з вод.\n\nКультисти Сутінкового Молота об'єдналися з нагами, щоб зайняти ці землі. Культисти, очолювані Келрісом, приносять у жертву невинних Аку'Маю заради влади.\n\nУбийте Келріса та принесіть його голову до Селгорма в Дарнасі, {ім'я}, будь ласка.", [3] = "Принесіть голову Сутінкового Володаря Келріса Вартові Світанку Селгорму в Дарнас.", [4] = "Час — дорогоцінний товар, {клас}.\n\nМоя роль тут, у Дарнасі, полягає в тому, щоб забезпечити процвітання Срібного Світанку та придушити сили зла, що зазіхають на Калімдор.\n\nШвидше викладайте свої справи або рушайте у дорогу.", [5] = "Келріс вислизав від нас досить довго.\n\nЗдається, що щоразу, коли зло давало про себе знати в цих краях, Келріс відігравав певну роль. Деякий час ми вважали його мертвим або зниклим безвісти.\n\nАле це має сенс. Поклавши край його правлінню, ви врятували життя багатьох невинних людей.\n\nСвітлом! Принести когось у жертву слузі Старого Бога заради особистої вигоди – це поза межами докорів!\n\nВи зробили великий вчинок, {ім'я}. Я вітаю вас від імені Срібного Світанку.", ["en"] = "Blackfathom Villainy" },
    [78923] = { [1] = "Знання в глибинах", [2] = "Як ти, можливо, знаєш, я збираю знання. Старі знання. Могутні знання. Знання, що відкривають двері, і знання, що можуть пробудити Тих, Хто Спить.\n\nХодять чутки про давній уривок знань, Рукопис Лоргаліса, на дні Чорнопробних Безоднь у Попелястому Долі. Це місце — давнє житло давно померлих ельфів. Ельфів, які володіли великими знаннями, перш ніж їхнє місто загинуло.\n\nПошукай рукопис у Чорнопробних Безоднях. Зроби це, і я не забуду його. Навіть після... кінця днів.", [3] = "Принесіть рукопис Лоргаліса Геррігу Кістяному Захвату в Печері Забутих у Залізогарті.", [4] = "Подорож до Ясенеділу довга, і ваше завдання нелегке. Але якщо ви дістанете мені рукопис, {ім'я}...то ваша винагорода буде великою.", [5] = "Ви знайшли рукопис! Який радісний день сьогодні! Копії будуть зроблені та розповсюджені, і мої брати та сестри нарешті знатимуть про давні знання Лоргаліса!\n\nВаша служба нам більша, ніж ви думаєте, {ім'я}. Але я сподіваюся, що цей подарунок покаже вам нашу вдячність нашим союзникам.", ["en"] = "Knowledge in the Deeps" },
    [78925] = { [1] = "Настання сутінків", [2] = "Наділені давніми обрядами хаотичних Старих Богів, члени Сутінкового Молота прагнуть повернути своїх темних покровителів та поширити смерть і жах по всьому світу.\n\nМи віримо, що Сутінковий Молот об'єднався з нагами та збирається в Чорнопросвітніх Глибинах на узбережжі Ясенеділу.\n\nЯкий би злий план не зароджувався в глибинах старого храму, його потрібно зірвав.\n\nВійнуйте проти Молота та поверніть докази своїх діянь. Ваші зусилля будуть щедро винагороджені.", [3] = "Принесіть 10 Сутінкових Підвісок Срібному Вартовому Манадосу в Дарнасі.", [4] = "Чорнопровалні Безодні колись були стародавнім храмом нічних ельфів. Колись тут знаходилася найпотужніша місячна криниця. Хто знає, яке зло зараз там вариться від рук Сутінкового Молота.\n\nЧи досягли ви якогось прогресу в позбавленні від їхньої присутності?", [5] = "Ви, безсумнівно, хороброї та благородної крові, {ім'я}. Срібний Світанок хвалить вас за ваші зусилля проти зла.", ["en"] = "Twilight Falls" },
    [78926] = { [1] = "Дослідження порчі", [2] = "Дурні ельфи крові працюють з демонічною магією. Хіба вони не бачили, що сталося з нагами та сатирами Калімдора?\n\nЯ боюся, що ельфи крові зіткнуться з подібною деформацією. Азерот не може дозволити собі народити ще одну мерзенну расу монстрів.\n\nЯ хочу вивчити стовбури мозку сатира та наги, щоб зрозуміти, яка доля чекає на ельфів. У Чорноводних Глибинах, на узбережжі Ясенеділу, ви знайдете і сатира, і нагу.\n\nЦе довга подорож, {ім'я}.", [3] = "Гершала Нічний Шепіт в Обердіні хоче 8 Злочинних Стовбурів Мозку.", [4] = "Як тільки в мене буде достатньо зразків для вивчення, моя справжня робота зможе розпочатися. За допомогою пошкоджених мозкових стовбурів як сатира, так і наги з Чорнопросвітніх Безодень я зможу спробувати встановити зв'язок між мутаціями.\n\nМожливо, з цими отриманими знаннями ми зможемо запобігти глибшому зануренню ельфів крові у потворність та зло.", [5] = "Ви подорожували далеко і, безсумнівно, зіткнулися з великою небезпекою.\n\nВаші дії були безкорисливими. Це заради блага всього Азероту, що ви допомагаєте мені з моїми дослідженнями. Дякую вам, {ім'я}, за все, що ви зробили.\n\nА тепер, якщо вибачте, у мене багато роботи...", ["en"] = "Researching the Corruption" },
    [79] = { [1] = "Легенда про Сталвана", [2] = "Я роками слідкував за легендою Сталвана. Коли кілька років тому були вбиті ті приїжджі дворяни, я поїхав зі Знесилієм розслідувати це діло. Я знайшов ці брудні сторінки, але нам не вдалося пов'язати почерк з тим божевільним чоловіком у лісі. Твій слід доводить його вину. Віднеси цю сторінку до командира Чорнобривої та розкажи їй про все!", [3] = "Віднесіть брудну сторінку командиру Альтеї Чорнобривій.", [4] = "Краще б це було щось хороше, {клас}. Показуй, що там в тебе, але, в ім'я Світла, поквапся. Захист Темнодолу — для мене понад усе. Я не маю наміру гаяти час на зачіпки, які заведуть в глухий кут.", [5] = "Ого, а ти {стать:виявився:виявилася} справжнім детективом, {клас:к}.", ["en"] = "The Legend of Stalvan", ["tasks"] = { ["Muddy Journal Pages"] = "брудні сторінки щоденника", ["Muddy Journal Pages (Provided)"] = "брудні сторінки щоденника (видано)" } },
    [79008] = { [1] = "...і та записка, яку ти знайшов", [2] = "<Коли слабке сяйво жарин починає згасати, ви натрапляєте на залишки недавнього багаття.\n\nСеред розкиданих припасів ви знаходите обгорілу записку.>\n\n«Не все, що горить, втрачено. Знайди землю-близнюка, знайди це місце».", [3] = "Обвуглені залишки записки слугуватимуть вам єдиним орієнтиром.", ["en"] = "... and that note you found" },
    [7905] = { [1] = "Ярмарок Темного місяця", [2] = "Наближається ярмарок Темного місяця! Не забудьте випробувати всі її чудеса та хвилювання, коли вона прибуде до міста!\n\nЯкщо поквапитесь, ви зможете обміняти цей ваучер на безплатні призові купони! Просто віддайте ваучер Ґелвасу Хмурошлюзу на ярмарку.\n\nЗараз ярмарок проходить неподалік Злотохрестя, в Ельвиннському лісі. Не упустіть свій шанс! Йдіть туди просто зараз!", [3] = "Віддайте ваучер на призовий купон Ґелвасу Пилошлюзу на ярмарку Темного місяця.", [4] = "Так, {стать:пане:пані}, чим я можу допомогти? У вас є ваучер для обміну?", [5] = "Вітаю на ярмарку Темного місяця! Це ваучер на П'ЯТЬ, так-так, цілих П'ЯТЬ призових купонів!\n\nЯк назбираєте більше — приходьте до мене та обміняйте їх на цінні призи. Чим більше купонів — тим більше виграєте призів! Вперед!", ["en"] = "The Darkmoon Faire", ["tasks"] = { ["Free Ticket Voucher"] = "ваучер на призовий купон", ["Free Ticket Voucher (Provided)"] = "ваучер на призовий купон (видано)" } },
    [79077] = { [1] = "Ділячись вірою", [2] = "Світло закликає нас до справедливості та захисту, але також і до співчуття. Наші союзники — чужинці на наших землях, і ми маємо обов'язок навчити їх нашим шляхам.\nЦей нічний ельф шукає Світла, але має труднощі у своїй медитації. Чи не могли б ви йому допомогти?", [3] = "Медитуйте на Світлі, а потім помоліться разом з ельфом, який стоїть на колінах, щоб поділитися своїми медитаціями.", [4] = "Так, {ім'я}?", [5] = "Світло поширює свої благословення через вас, {ім'я}. Шануйте його, продовжуючи ділитися своєю мудрістю з прохачами, яких ви зустрічаєте у своїх подорожах.", ["en"] = "Sharing the Faith" },
    [79078] = { [1] = "Ділячись вірою", [2] = "Ця людина тягнеться до світла Елуни, але її зір затьмарений. Чи не могли б ви йому допомогти?", [3] = "Медитуйте на Елюну, а потім помоліться разом з людиною, яка стоїть на колінах, щоб поділитися своїми медитаціями.", [5] = "Світло поширює свої благословення через вас, {ім'я}. Шануйте його, продовжуючи ділитися своєю мудрістю з прохачами, яких ви зустрічаєте у своїх подорожах.", ["en"] = "Sharing the Faith" },
    [79090] = { [1] = "Відбиття загарбників", [2] = "Деякі з Вершників Пісні Війни зазнали поразки, але битва все ще триває...", [3] = "Принесіть Знак Вершника Пісні Війни Фелор Місячному Променю, Жриці Місяця, на базу Місячний Колодязь в Ясеневому Долині.", [4] = "{ім'я}, які новини з фронту?", [5] = "Ці ординські загарбники досі оскверняють наші землі та збирають урожай у нашій священній пустелі. Продовжуйте виганяти їх!\n\nЦей священний бойовий гімн може надихнути вас боротися з ними з більшою рішучістю. Дякуємо, {ім'я}.", ["en"] = "Repelling Invaders", ["tasks"] = { ["Warsong Outrider Mark"] = "Знак аутсайдера Пісні Війни", ["Warsong Outrider Mark (Provided)"] = "Знак аутсайдера Пісні Війни (видано)" } },
    [79091] = { [1] = "Архімаг Антонідас: Нескорочена автобіографія", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Ви кажете, що це з бібліотеки Айронфорджа? ...Я впевнений, що вони цього не пропустять.\n\nЯкщо ви знайдете більше магічних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Archmage Antonidas: The Unabridged Autobiography", ["tasks"] = { ["Archmage Antonidas: The Unabridged Autobiography"] = "Архімаг Антонідас: Нескорочена автобіографія", ["Archmage Antonidas: The Unabridged Autobiography (Provided)"] = "Архімаг Антонідас: Нескорочена автобіографія (видано)", ["Archmage Antonidas: The Unabridged Autobiography slain"] = "Архімаг Антонідас: Нескорочена автобіографія: убито" } },
    [79099] = { [1] = "Барон Акваніс", [2] = "Вітаю {клас}. Я чув найцікавіші історії від місцевих жителів про могутнього зіпсованого водного елементаля на ім'я Барон Акваніс, який стоїть на сторожі біля входу до руїн нічних ельфів, відомих як Чорнопровалля. Я тут, щоб найняти шукачів пригод, достатньо сміливих, щоб дістати ядро Барона Акваніса, кулю зіпсованої води. В обмін на це я готовий надати вам доступ до порталу безпосередньо до Зорамської Смуги, який я використовую для вивчення околиць навколо руїн... з безпечної відстані, звичайно.", [3] = "Принесіть Дивну Водяну Кулю Давидусу Войдстару в Обердін, Темні Береги.", [4] = "А, знову привіт {ім'я}. Ви отримали глобус?", [5] = "Хм, дуже цікаво. Цього... не те, чого я очікував. Дуже добре, дякую за це. Як і обіцяв, тепер ви можете скористатися моїм порталом до Зорам-Стренд.", ["en"] = "Baron Aquanis" },
    [79362] = { [1] = "Щит Ґранта", [2] = "Щит, залишений привидом Ґранта Валора, батька родини Валорів і героя Воронячого пагорба.\r\n\r\nДух Ґранта й досі б'ється з невмерлими, тож, можливо, його незавершеною справою було знищити ту нечисть, що поранила його на кладовищі Воронячого пагорба. Ймовірно, саме в ній досі застрягла його булава.", [3] = "Знайдіть булаву Ґранта в одного зі скелетів на кладовищі Воронячого пагорба, а потім поверніться до Сірри Вон'Інді в Темнокрай по додаткові відомості.", ["en"] = "Grant's Shield", ["tasks"] = { ["Grant's Mace"] = "Булава Гранта", ["Grant's Shield"] = "Щит Гранта" } },
    [79363] = { [1] = "Меч Сільвії", [2] = "Меч, залишений духом вартової Воронячого Пагорба Сільвії Доблесті, яка присвятила своє життя захисту мирних жителів та їхніх домівок.\r\n\r\nДух Сільвії й досі навідується до навколишніх садиб. Можливо, її незавершена справа — розгромити Непокірних, що оселилися в маєтку Еддла на південь від Воронячого Пагорба.", [3] = "Переможіть 7 Нічних клинків Непокірних і 7 чаротворців Непокірних у маєтку Еддла, а потім поверніться до Сірри Вон'Інді в Темнокрай по додаткову інформацію.", [4] = "У тебе такий вигляд, ніби ти привида побачив!", [5] = "Сільвія Відвага, гм? А, так. Славна воїтелька й захисниця нашого способу життя — хоч і мала дещо вузьке уявлення про те, яким він має бути.\r\n\r\nНе мені знати, чого б вона хотіла, але Непокірні були добрим початком. Дай-но я ще трохи досліджу цей клинок.", ["en"] = "Silvia's Sword", ["tasks"] = { ["Defias Enchanter slain"] = "чародій Непокірних: убито", ["Defias Night Blade slain"] = "нічне лезо Непокірних: убито", ["Silvia's Sword"] = "Меч Сільвії" } },
    [79482] = { [1] = "Викрадені ласощі Зимової Покрови", [2] = "Послухайте... не хочу руйнувати магію сезону, але Смокілід Пасовищам не завадила б допомога — така, яку ви, шукачі пригод, зазвичай надаєте.\n\nНам не вистачає важливої партії ласощів, яка поповнювала наші запаси на сезон, а тепер нам не вистачає агента Смокілід Пасовищ, якого ми відправили на пошуки! Будь ласка — востаннє повідомлялося про партію в горах Альтерак, і саме там наш чоловік вирушив її шукати.\n\nПеревірте, чи обидва там, цілими та неушкодженими!", [3] = "Знайдіть слідчого з Димчастих пасовищ, який зник безвісти у засніжених районах Альтеракських гір.", [5] = "І-і-ти мене м-ч-чуєш! Дякую м-м-підсумку!\n\nЯ насправді не с-н-сніговик — мене н-н-звати Сакс, і я м-м-працюю у м-м-філії «Смоківудські пасовища» в Залізогарті... Мене м-м-послали сюди шукати м-м-зниклу посилку, коли на мене напала м-м-істота, яку я ніколи раніше не бачив!\n\nТак м-м-дуже холодно...", ["en"] = "Stolen Winter Veil Treats" },
    [79484] = { [1] = "Ти мерзенний...", [2] = "І-істота на ім'я \"Жахливий Грінч\" - це та, що м-м-вкрала нашу партію ласощів, {ім'я}. Але будь м-м-обережний! Це він м-м-перетворив мене на цю с-с-снігову кашу!\n\nТобі м-м-потрібна допомога, щоб м-м-зіткнутися з ним. Я бачив, як він м-м-блукав навколо, де єті; він м-м-напевно десь тут! М-м-знайди ласощі {ім'я}, віднеси їх м-м-назад на пасовища Димчастого Лісу в Залізогарті та м-м-скажи їм, що мене м-м-потрібно розморозити!", [3] = "Знайдіть і поверніть Викрадені Ласощі Вулморту Джінглпокету в Залізогарті. Вважалося, що вони належать Гидкому Грінчу, якого можна знайти десь у засніжених регіонах Альтеракських гір.", [4] = "{ім'я} - наше Свято Зимової Покриви буде зіпсовано без цих ласощів для поповнення запасів! Сам Гракку пропустить можливість поділитися своїми смачними м'ясними пирогами з усіма хорошими хлопчиками та дівчатками цього сезону...", [5] = "Ви знайшли його! Ви врятували Свято Зимової Покрови на Пасовищі Димчастого Лісу!\n\nБідолашний Сакс... ми обов'язково відправимо туди команду та знайдемо спосіб його розморозити. Сподіваємося, що він повернеться вчасно до дня Свята; хоча йому доведеться надолужити пропущений час роботою. Однак, це було б неможливо, якби не ти!", ["en"] = "You're a Mean One..." },
    [79486] = { [1] = "Подяка від Пасовищ Димного Лісу!", [2] = "Ми, у Пасовища Димного Лісу, вдячні за повернення вкрадених ласощів, {ім'я}. За це ми хотіли б запропонувати вам особливий подарунок... подарований ні ким іншим, як самим Дідом Зимою!\n\nБудь ласка, поговоріть з Дідом Зимою, і він подарує вам ваш подарунок «Свято Зимової Покриви» від нас, у Пасовища Димного Лісу. З нашої ферми на вашу тарілку, це завжди корисні смаколики Пасовища Димного Лісу... звичайно ж, завдяки вам!", [3] = "Поговоріть з Прабатьком Зимою в Залізогарті.", [5] = "Хо-хо, привіт, шукачу пригод!\n\nГобліни сказали мені, що ти заслужив особливий подарунок цього свята, і я радий його тобі вручити. Ось тобі — чудового Свята Зимової Покрови цього та кожного наступного сезону.", ["en"] = "A Smokywood Pastures' Thank You!" },
    [79492] = { [1] = "Метцен-північний олень", [2] = "ЛИХО! Оленя Метцена викрадено!\n\nМетцен — один із восьми оленів Діда Зими, власність Смоківудських Пасовищ. Ми отримали не один, а ДВА листи з вимогою викупу від груп, які стверджують, що мають Метцена. Сезон свят розпочався, і ми прикуті до скриньки з грошима! Будь ласка, знайдіть Метцена та поверніть його нам!\n\nПеревірте листи з вимогою викупу, щоб знайти підказки, і посипте його цим оленячим пилом — це звільнить його від будь-яких пут!\n\nБудь ласка, поспішайте!", [3] = "Знайдіть оленя Метцена. Використайте надані вам нотатки, щоб отримати підказки щодо місця його утримання.\n\nКоли знайдете Метцена, візьміть Мішечок з оленячим пилом, щоб посипати його пилом; це має звільнити Метцена з пут полону.\n\nПоверніть Мішечок з оленячим пилом Вулморту Джінглпокету в Залізогарті, як тільки Метцена звільнять.\n\nНаданий предмет:", [4] = "{ім'я}! Чи було достатньо інформації в нотатках у сумці, яку я дав, щоб знайти Метцена? Мені дуже не хочеться думати про те, що ці жорстокі головорізи можуть з ним зробити... але ми ніяк не можемо дозволити собі заплатити такий непомірний викуп!", [5] = "Ти це зробив! Ура!\n\nМетцен повернувся до стайні Діда Зими — так, Метцен справді вміє літати — зовсім недавно! Пил спрацював чудово; я знав, що так і буде. Ти врятував Свято Зимової Покрови, а також Пасовища Димчастого Лісу від катастрофи. Дякую, {ім'я}.\n\nПослухай... завдяки тому, що ти тут зробив, я хочу, щоб ти це мав. Це щось ДУЖЕ особливе; якщо у тебе є маунтин, я думаю, тобі це дуже сподобається. Щасливого Зимового Покрову!", ["en"] = "Metzen the Reindeer" },
    [79501] = { [1] = "Герой дня", [2] = "Послухай... Я не маю тобі цього розповідати, але оскільки ти герой дня і все таке...\n\nУ цю пору року скрізь свіжий падуб, але він ніколи не довше зберігається. У нас є машина, яка консервує падуб — він ніколи не псується! Ми використовуємо її, щоб зробити свято гострим... і отримати прибуток влітку!\n\nЯ дозволю тобі скористатися консервантом, але тільки якщо ти майстер кулінарії. Тобі знадобиться трохи кам'яної солі та два, три, скажімо, п'ять золотих. Це принесе тобі гарну партію, яку ти зможеш залишити собі.", [3] = "Принесіть 1 глибококам'яну сіль та 5 золотих монет до будь-якого автомата сушарки для падуба, після чого ви отримаєте 5 консервованих падуба.", [4] = "Машина «Збереження падуба» спочатку виглядає як перегінний апарат, але уважний огляд виявляє деякі зміни, схожі на гоблінівські. Тим не менш, ваші кулінарні навички, здається, дозволяють вам зрозуміти, як працює машина.\n\nУ машині вже є свіжий падуб — вам просто потрібно надати трохи кам'яної солі та п'ять золотих монет, щоб машина запрацювала.", [5] = "Машина починає працювати з тихим гуркотом і невеликою кількістю пари. Невдовзі вона зупиняється, сповіщаючи про це ще один невеликий струмінь пари, що виривається з неї. Відчиняються дверцята, показуючи партію консервованого падуба!", ["en"] = "The Hero of the Day" },
    [79905] = { [1] = "Смак знань", [5] = "Зі знаннями, які ви здобули під час своїх подорожей, я вважаю, що ви готові навчитися самостійно застосовувати чари розуміння. Це допоможе вам знайти нові тексти для колекції бібліотеки.\n\nЩасливої подорожі, {ім'я}.", ["en"] = "A Taste of Knowledge" },
    [79939] = { [1] = "Зламаний молот", [2] = "Вишуканий зламаний бойовий молот лежить оточений мертвими культистами Палаючого Клинка та воїнами Багряного Хрестового Походу. Тут явно відбувся бій, і досить недавно. Ви також впізнаєте це як зброю паладина Ордена Срібної Руки. Хоча ви бачили багато подібних молотів, якість та майстерність виконання цієї зброї досить унікальні. Вам слід пошукати підказки в цій місцевості та знайти когось, хто може знати більше про цю зброю.", [3] = "Пошукайте підказки про те, що сталося в ковені Маннороків у Дезоласі, і знайдіть когось, хто може знати більше про зламаний молот.", [4] = "Що ж у тебе там є, друже?", [5] = "<Кетрін важко зітхає> Так {ім'я}, я знаю про цю зброю. Я припускав, що її власник давно помер.", ["en"] = "The Broken Hammer", ["tasks"] = { ["Broken Hammer"] = "Зламаний молоток" } },
    [79940] = { [1] = "Загублений брат", [2] = "<Кетрін здригається, тримаючи в руках розбиті фрагменти зламаного молота>\n\nЯ не розповідатиму детально про господаря цієї зброї, бо розповідь сповнила б мене сорому, але я скажу вам, що можу.", [3] = "Поговоріть з Катериною Чистокровною та дізнайтеся більше про зламаний молот.", [5] = "У вас мало підказок, тому знайти Еонаса може бути важко, але вам варто спробувати.", ["en"] = "A Lost Brother" },
    [79945] = { [1] = "Накази від Великого хрестоносця", [2] = "Схоже, це наказ від самого Великого Хрестоносця Багряного Хрестового Походу, Датрохана. Здається, Еонас зіткнувся з Хрестовим Походом. Судячи зі сцени перед вами, схоже, що Хрестовому Походу вдалося простежити за Еонасом сюди та заарештувати його. Схоже, він не здавався без бою.\n\nЗвинувачення, висунуті проти Еонаса, серйозні, але це пояснює деякі сцени, на які ви натрапили в «Спустошенні».", [3] = "Поверніть ордени Великого хрестоносця Катерині Чистокровній.", [4] = "Ти приніс звістку про Еонаса?", [5] = "<Кетрін глибоко хмуриться, читаючи листа>\n\nЕонас дотримувався деяких радикальних поглядів, коли покинув орден, але мені дуже важко повірити, що його справи в Дезоласі пов'язані з спілкуванням з демонами, нежиттю чи чимось подібним. Нам потрібно знайти його та почути його версію цієї справи. Тут є щось більше, я впевнений у цьому.", ["en"] = "Orders from the Grand Crusader", ["tasks"] = { ["Orders from the Grand Crusader"] = "Накази від Великого хрестоносця" } },
    [79946] = { [1] = "Брат у скруті", [2] = "Через... невдалу причину, чому він покинув орден, було б поганою комедією для Еонаса загинути від рук Багряного Хрестового Походу зараз. Хрестовий Похід — це організація фанатиків та божевільних, і вони стають дедалі зухвалішими у своїй готовності вчиняти насильство проти будь-кого, кого вони вважають ворогами світла. Відвідайте Багряний Монастир у Тірісфальських Галявинах і дізнайтеся, чи Еонас ще живий.", [3] = "Поговоріть з Катериною, щоб дізнатися більше про Еонаса, а потім знайдіть його в Багряному монастирі", [5] = "<Еонас виглядає критично пораненим. Він ледве видавлює кілька слів.> Вони навіть... не ставили мені жодних запитань...", ["en"] = "A Brother In Need" },
    [79963] = { [1] = "Благодаттю Світла", [2] = "Еонасу потрібне негайне зцілення, інакше він помре. Заклич світло та врятуй його.", [3] = "Зціли Еонаса.", [5] = "<Здається, Еонас дихає легше. Він все ще здається досить слабким, але йому вдається повернути голову до тебе, щоб заговорити.>\n\nТи кажеш, що тебе послала Катерина? Благослови цю жінку. Дякую тобі, {клас}. Я перед тобою боржник.", ["en"] = "By The Light's Grace" },
    [79970] = { [1] = "Еонас Виправданий", [2] = "Дякую, що врятував мене, {клас}. Здається, я вже не такий молодий, як колись, і, гадаю, мені знадобляться союзники для майбутнього. Будь ласка, зустрінь мене у Штормовії в Соборі Світла, як тільки зможеш.\n\nНе хвилюйся за мене, я можу вибратися звідси сам. Мені просто потрібно кілька хвилин, щоб відновити сили.", [3] = "Зустріньте Еонаса в Соборі Світла в Штормовії.", [5] = "Я не можу висловити вам достатньо подяки за те, що ви врятували мене з того забутого світлом місця. На жаль, боюся, що це лише початок нашої подорожі, і решта буде нелегкою. Давайте поговоримо та сплануємо наші наступні кроки.\n\nО, але спочатку... дозвольте цьому старому передати частину своїх знань молодому поколінню. Це не велика нагорода, але я сподіваюся, що ви все одно зможете використати її з користю.", ["en"] = "Aeonas the Vindicated" },
    [79987] = { [1] = "Повернення персня", [2] = "Відкриття коробки, створеної Блискочист 5200, показує те, про що ви підозрювали – блискучу каблучку! Одягнувши каблучку, ви відчуваєте, як магічна сила пронизує ваше тіло.\n\nВсередині кільця є невеликий, але помітний відбиток печатки Залізогарта. Поруч із ним вигравірувано три маленькі ініціали: \"TdK\". Це може означати або ініціали попереднього власника, або, можливо, ініціали майстра каблучки. Залиште каблучку... або поверніть її цій людині. Рішення, рішення...", [3] = "Ви можете або залишити собі каблучку, або знайти особу, відповідальну за відбиток та гравіювання на внутрішній стороні браслета.", [4] = "Гей, спокійніше, друже — я дуже важливий бізнесмен! Я впевнений, що кур'єр просто запізнився з доставкою орендної плати... зачекайте... ви ж не мій орендодавець.\n\nНу, звісно, що ні — дурень я! Ви прийшли до мене в пошуках найкращого ювеліра в усьому Айронфорджі, такого, який НЕ виготовляє ПРОКЛЯТИХ речей! Так!\n\nГм... що вам потрібно?", [5] = "Перстень, кажеш? Подивимося... так, я ж зробив цей перстень, чорт забирай.\n\nДо того, як Гномреґан зник, у мене там була невелика крамниця. Можливо, це той, який я залишив, коли втік у гори; він має простий дизайн, і я зробив кілька подібних. Можливо, він від когось, хто не вижив.\n\nЧи мав його гноми Темного Заліза? Що ж, це додає новий шар змови до дев'яти різних шарів, що вже ширяють навколо. Можливо, влада хотіла б знати; він марний на таких, як я.\n\nТепер повернемося до перстня...", ["en"] = "Return of the Ring", ["tasks"] = { ["Item #216662"] = "Товар №216662" } },
    [79990] = { [1] = "Лісоматеріали Тернистої терики", [2] = "Нам дуже потрібні додаткові ресурси та підкріплення для підтримки наших цілей у басейні Араті. Відповідну деревину було особливо важко знайти, і ми були змушені шукати аж до Тернистої Долини, щоб знайти те, що нам потрібно. Принесіть мені партію деревини з Тернистої Долини, і ваша підтримка не залишиться непоміченою.", [3] = "Принесіть сержанту Макліру партію пиломатеріалів з Тернистої ділянки.", [4] = "Ви принесли нам свіжі продукти?", [5] = "Дякуємо {клас}. Це допоможе нам змінити ситуацію в басейні Араті.", ["en"] = "Stranglethorn Lumber" },
    [80] = { [1] = "Легенда про Сталвана", [2] = "Я давно придивляюся за цим виродком Сталваном. Але якщо цю сторінку написала та ж рука, то це безперечно свідчить про його провину.\n\nПротягом усього свого життя, займаючись реєстром міста, писар Долтрі став експертом у визначенні почерку. Покажи йому цю сторінку і переконайся, чи збігається почерк з підписом у реєстрі.", [3] = "Покажіть писару Долтрі закривавлену сторінку щоденника.", [4] = "Знову {стать:повернувся:повернулася}, {ім'я}? Що у тебе на цей раз?", [5] = "Безсумнівно! Почерк на цій сторінці дійсно збігається з підписами у реєстрі.", ["en"] = "The Legend of Stalvan", ["tasks"] = { ["A Bloodstained Journal Page"] = "закривавлена сторінка щоденника", ["A Bloodstained Journal Page (Provided)"] = "закривавлена сторінка щоденника (видано)" } },
    [80131] = { [1] = "Гномське вдосконалення", [2] = "Слухай {ім'я}, ця каблучка твоя, звісно... але я можу зробити тобі кращу! Цей дизайн, як я вже казав, справді простий. Я зараз набагато вправніший, і лише за тридцять срібних монет я прикрасю її для тебе! Ну, трохи більше тридцяти, насправді...\n\nЗараз я у скрутному становищі; усі мої матеріальні запаси вичерпалися. Якщо ти принесеш мені злиток срібла та моховий агат, я додам до каблучки срібну та агатову решітку, що додасть їй трохи більше пишноти!\n\nПовір мені!", [3] = "Принесіть Блискуче золоте кільце, срібний злиток, моховий агат та 30 срібних монет Талвашу дель Кісселю в Залізогарті.", [4] = "У вас є потрібні мені матеріали? Я б не просив у вас їх, якби мені не пощастило...", [5] = "А, саме те, що мені було потрібно! Колись, коли я виберуся з цієї ями, в якій я несправедливо опинився, я зроблю для тебе, для ВСІХ найкращі дрібнички в усьому Азероті! А поки що, дякую за те, що ти люб'язний щодо реагентів. Зазвичай я б брав удесятеро більше, ніж я брав з тебе за перстень такої якості...\n\nДо речі, про персні, ось твій новий!", ["en"] = "Gnome Improvement", ["tasks"] = { ["Item #216662"] = "Товар №216662" } },
    [80135] = { [1] = "Штучні Клокморта", [2] = "Друг-гном, Клокморт Спаннерспан, надіслав мені звістку з Айронгоржа. Він каже, що йому потрібна допомога у небезпечній, але важливій місії до Гномреґану, колись великого міста гномів, яке тепер заражене та наповнене божевільними гномами та їхніми пристроями.\n\nЯ мушу залишитися тут, але моє серце болить, щоб допомогти своєму другові. Якщо ти можеш піти замість мене, то я буду тобі дуже вдячний.\n\nТи можеш знайти Клокморта в Тінкертауні, в Айронгоржі.", [3] = "Поговоріть з Клокмортом Спаннерспаном у Залізогарті.", [5] = "Так! Мені справді потрібна допомога з місією в Гномреґані. І ти саме той {клас}, щоб її виконати!", ["en"] = "Klockmort's Essentials" },
    [80136] = { [1] = "Базові штучні", [2] = "Майже універсальний механічний компонент – необхідний штучний – був дуже корисним для мідників та ковалів Гномреґану. Але під час шаленого виїзду з нашого міста ніхто не згадав взяти з собою будь-який з цих пристроїв! А мені потрібна велика їхня кількість для роботи, яку я скоро візьмуся.\n\nБудь ласка, сходіть до Гномреґану та принесіть мені кілька необхідних штучних виробів. Ви знайдете їх у глибинних районах нашого міста, вони зберігаються в контейнерах, які називаються штучними екстраполяторами.\n\nДякую, {ім'я}, і будь ласка, поспішайте!", [3] = "Принесіть 12 необхідних штучних речовин Клокморту Спаннерспану в Залізогарті.", [4] = "У вас є необхідні штучні речовини?", [5] = "Ви їх отримали! Тепер я можу розпочати свої нові експерименти!\n\nЯ безмежно вдячний вам, {ім'я}! Ваша сміливість значно просунула дослідження гномів!", ["en"] = "Essential Artificials" },
    [80137] = { [1] = "Порятунок мозку Техбота", [2] = "Коли наше улюблене місто Гномреґан упало, якась іскра, мабуть, сколихнула моє бідолашне творіння, Техбота. Колись він допомагав мені та моїм соратникам своїми незліченними пристроями та безмежним сховищем інформації, але його позитронний мозок поляризувався. Тепер він негатронний... і поведінка Техбота протилежна. Він шалено блукає Гномреґаном!\n\nАле, можливо, його можна врятувати. Можливо, якщо ви зможете отримати ядро пам'яті Техбота та принести його мені, я зможу виявити причину поляризації та полагодити мого бідолашного Техбота.", [3] = "Принесіть ядро пам'яті Техбота до Тінкмайстра Оверспарка в Залізогарті.", [4] = "Ви знайшли Техбота? Ви отримали його ядро пам'яті??", [5] = "О, це чудово! Дякую, {ім'я}! Я негайно візьмуся за роботу!!\n\nБідолашний, бідолашний Техбот... Не переймайся. Ми тебе полагодимо.\n\nА куди ж я подів ту заглушку для свого поворотного ключа з гідродомкратом...", ["en"] = "Save Techbot's Brain!" },
    [80138] = { [1] = "Мехмайстер Надспалах", [2] = "Майстер-блендер Оверспарк дуже засмучений долею свого механічного творіння, Технобота. Я пам'ятаю Технобота як доброго та корисного інструменту для гномів, але Оверспарк каже мені, що він несправний.\n\nДуже сумно. Але, якщо пощастить, можливо, його вдасться полагодити!\n\nПоговоріть з майстром-блендером Оверспарком у Місті-блендері в Залізогарті. Він буде радий вашій допомозі.", [3] = "Поговоріть з Тінкмайстром Оверспарком у Залізогарті.", [5] = "Так, це правда. Техбот став шахраєм! Будь ласка, чи можете ви мені допомогти?", ["en"] = "Tinkmaster Overspark" },
    [80139] = { [1] = "Гномальгін", [2] = "Після аварії Гноарн думає чи говорить лише про те, щоб очистити Гномреґан від нашестя троґґів та знайти ліки від хвороби, яка його мучить, {ім'я}.\n\nНа щастя, ми з Раззлом близькі до якогось ліків — або до рецепту справді потужного рому. Ми не дізнаємося, поки не проведемо випробування! Звичайно, щоб перевірити нашу теорію, нам знадобиться кілька речей, а саме: радіоактивні опади від опромінених троґґів у Гномреґані. Наповніть цю пляшечку зеленим сяйвом і принесіть її назад!", [3] = "Використовуйте порожню свинцеву колекційну склянку на опромінених загарбниках або опромінених грабіжниках, щоб зібрати радіоактивні опади. Як тільки вона наповниться, віднесіть її Оззі Тогглвольту в Харанос.\n\nНаданий предмет:", [4] = "Хіба ти не бачиш, що ми тут намагаємося вилікувати цілий вид гномів?! Нам потрібно більше зеленого сяйва!", [5] = "Чудова робота! Настав час випробувати нову формулу. Якщо це спрацює, то не тільки спійманий прокажений гном вилікується, а й у мене буде густе волосся! Відійдіть!", ["en"] = "Gnogaine", ["tasks"] = { ["Empty Leaden Collection Phial"] = "порожній свинцевий фіал для зразків" } },
    [80143] = { [1] = "Порятунок даних", [2] = "Коли ми втікали з Гномреґану, ми залишили стільки даних! Життєво важливі дані!\n\nМені потрібні дані на призматичній перфокарті з терміналу високого рівня безпеки матричний перфограф 3005-D, що знаходиться глибоко в Гномреґані. Ви повинні отримати доступ до терміналу, але для цього вам спочатку потрібен доступ... а щоб отримати його, вам потрібно отримати доступ до терміналів нижчого рівня безпеки – моделей -A, -B та -C. А для ЦЕ вам потрібні перфокартки безпеки, починаючи з білої... і ми залишили всі перфокартки в місті.\n\nЦе катастрофа! Чи можете ви допомогти?", [3] = "Принесіть призматичну перфокарту майстру-механіку Кастпайпу в Залізогарті.", [4] = "У вас є призматична перфокарта??", [5] = "Ви це зробили! Ви знайшли призматичну перфокарту та відновили втрачені дані! Життєво важливі, критично важливі, незмірно важливі дані, без яких ми не могли б прожити жодної миті!\n\nВашу службу гномам пам'ятатимуть надовго, {ім'я}.", ["en"] = "Data Rescue" },
    [80164] = { [1] = "Залпи великих ракет", [4] = "Для створення великих кластерних ракет потрібні величезні ресурси та майстерність, але їхня блискучість та краса варті цих зусиль! Принесіть мені монети предків, і я подарую вам знання їхнього виготовлення.", [5] = "Дякую, {ім'я}. Ось рецепт великих кластерних ракет. Нехай ваші вироби принесуть радість та удачу всім, хто їх побачить.", ["en"] = "Large Cluster Rockets" },
    [80165] = { [1] = "Залпи ракет", [4] = "Кластерні ракети – це колекція окремих ракет, і їхня краса вражає! Принесіть мені монети предків, і я поділюся з вами знаннями про їхнє створення...", [5] = "Ось тобі, {ім'я}. Візьми ці рецепти та дізнайся їхні секрети. Бажаю тобі удачі та з нетерпінням чекаю на твої чудові творіння.", ["en"] = "Cluster Rockets" },
    [80166] = { [1] = "Маленькі ракети", [4] = "Я володію секретами створення ракет Місячного фестивалю і з радістю поділюся своїми знаннями з шанованими.\n\nВ обмін на монети предків я можу запропонувати вам рецепт виготовлення маленької ракети...", [5] = "А, чудово. Ось твої рецепти, {ім'я}, і нехай благословить тебе моя Елуна.", ["en"] = "Small Rockets" },
    [80180] = { [1] = "Велика зрада", [2] = "Я довіряв ТермаПлюгу, {раса}. Ніколи не очікував, що він зрадить мене та весь гномський народ. І заради чого? Влади? Багатства? Усе те, що він мав би з часом. Тепер нас вигнали з нашого дому, і цей божевільний керує. Король нічого....\n\nМи повернемо Гномреґан, {ім'я}. Ми не зупинимося, доки місто не буде повернуто під наш контроль. Якщо ви хочете приєднатися до нашої боротьби, я прошу вас виконати просте завдання: вбити зрадника. Знищити Мекгініра ТермаПлюга.", [3] = "Вирушайте до Гномреґану та вбийте Мекгініра Термапліка. Поверніться до Верховного Містера Меккаторке, коли завдання буде виконано.", [5] = "Мені подобається думати, що останнє, що промайнуло в його голові, коли він упав на землю, була твоя нога, {раса}. Зі смертю Термаплага, наші плани повернути Гномреґан стали на крок ближче до здійснення.", ["en"] = "The Grand Betrayal" },
    [80181] = { [1] = "Гіробурорийки", [2] = "Це жахливо, {ім'я}. У нас не вистачить запчастин, щоб доставити наш флот гідробурових екскаваторів до Дун-Морога.\n\nНам потрібні запчастини, {ім'я}. Де краще знайти запчастини для наших машин, ніж у Гномреґані? Я чув, що боти та мехи блукають там, як худоба на відкритому пасовищі.\n\nМені потрібно, щоб ти поїхав до Гномреґану та розібрав цих роботів. Принеси мені їхні робототехнічні нутрощі. Двох десятків має бути достатньо.", [3] = "Принесіть двадцять чотири робомеханічні кишки Шоні в Штормовій.", [4] = "Якби це були перегони, ти б уже програв.", [5] = "Це чудово підійде, {ім'я}. Один гідробуровий екскаватор виправлено; залишилося 398.", ["en"] = "Gyrodrillmatic Excavationators" },
    [80182] = { [1] = "Єдиний вихід — більше зеленої субстанції", [2] = "Вашого зразка було не лише недостатньо, але й нечисто.\n\nНам потрібно більше зеленого сяйва. Трогги, очевидно, недостатньо опромінені, щоб задовольнити наші потреби. Вам доведеться піти до Гномреґану та принести трохи радіоактивних опадів прямо з-під крана. Я говорю про опромінених слизняків, луркерів та жахів. Будьте обережні, стримування такого типу опадів є складним. Вам, можливо, доведеться зробити кілька спроб з флаконом, поки не буде отримано відповідний зразок.", [3] = "Відправляйтеся до Гномреґану та принесіть туди високопотенційні радіоактивні опади. Будьте обережні, опади нестабільні та досить швидко руйнуються.\n\nОззі також знадобиться ваша склянка для колекції важкого свинцю після завершення завдання.", [4] = "Хм, ти не сяєш. Це добрий знак.", [5] = "<Оззі оглядає тебе.> Вражаюче, у тебе досі збереглися всі кінцівки. Тепер час подивитися, на що ця штука здатна!", ["en"] = "The Only Cure is More Green Glow", ["tasks"] = { ["Heavy Leaden Collection Phial"] = "важкий свинцевий фіал для зразків" } },
    [80241] = { [1] = "Походження ковальства", [2] = "Коли мені було приблизно твого віку, гном на ім'я Галван взяв мене під своє крило та навчив мене мистецтву зброяра. Перш ніж вирушити до Буті-Бей, він взяв з мене обіцянку навчити всіх, хто має бажання та рішучість просуватися в ковальському ремеслі — тож ось я тут — через усі ці роки.\n\nОтже, тепер тобі час дечому навчитися. Зроби мені шість золотих лускатих наручів, і ти дізнаєшся, звідки походить ковальська справа, {ім'я}.", [3] = "Принесіть шість Золотих Лускатих Брасерів Генку Молотові у Штормовії.", [4] = "Чи можете ви стати наступним протеже Гальвана?", [5] = "Дуже добре, {ім'я}! Слухайте та навчайтеся.\n\nКовальство ніколи не звідси походить!\n\nКовальство ніколи не звідси походить!\n\nКовальство тільки звідси походить!\n\nА тепер ви знаєте походження ковальства.", ["en"] = "The Origins of Smithing" },
    [80324] = { [1] = "Божевільний король", [2] = "Ви знаходите брудний, пошарпаний блокнот, повний пошарпаних схем та нотаток. Навіть після побіжного погляду стає зрозуміло, що будь-яке з цих творінь може бути використане для жахливого хаосу, якщо хтось колись виявиться настільки нерозумним, щоб їх створити.", [3] = "Принесіть інженерні нотатки Термоштепселя Верховному Меккаторку в Місті Меккаторке в Залізогарті.", [4] = "{ім'я}, що це у тебе таке?", [5] = "Я безмежно вдячний вам за те, що ви знайшли ці схеми. Мені моторошно подумати, що сталося б з Айронфоржем, якби Термоштекер зміг використати ці творіння проти нас.\n\nЦе заслуговує на святкування!", ["en"] = "The Mad King", ["tasks"] = { ["Item #217350"] = "Товар №217350" } },
    [8105] = { [1] = "Битва за низину Араті!", [2] = "{ім'я:к}, битва за низину Араті — це битва за ресурси та територію. Ключові пункти на цій території повинні контролюватися для забезпечення нашого війська необхідною сировиною та припасами. Я наказую тобі штурмувати найвіддаленіші точки від нашої бази в низині Араті.\n\nНапади на ферму, шахту, лісопильню та кузню, якщо їх контролює ворог. Знайди ворожий прапор і зірви його зі стовпа!\n\nКоли зробиш це з усіма чотирма точками, повернись до мене.", [3] = "Нападіть на шахту, лісопильню, кузню і ферму в низині Араті, після чого поверніться до фельдмаршала Осяйва в Опорний пункт.", [5] = "Я дізнався про твої подвиги в низині Араті, {ім'я:к}. Чудова робота! Я вірю, що з такими бійцями, як ти, одного дня ми зможемо повернути собі нашу батьківщину.", ["en"] = "The Battle for Arathi Basin!", ["tasks"] = { ["Blacksmith Assaulted"] = "Напад на коваля", ["Blacksmith Assaulted (Provided)"] = "Напад на коваля (видано)", ["Blacksmith Assaulted slain"] = "Напад на коваля: убито", ["Farm Assaulted"] = "Напад на ферму", ["Farm Assaulted (Provided)"] = "Напад на ферму (видано)", ["Farm Assaulted slain"] = "Напад на ферму: убито", ["Lumber Mill Assaulted"] = "Напад на лісопильний завод", ["Lumber Mill Assaulted (Provided)"] = "Напад на лісопильний завод (видано)", ["Lumber Mill Assaulted slain"] = "Напад на лісопильний завод: убито", ["Mine Assaulted"] = "Шахта піддана нападу", ["Mine Assaulted (Provided)"] = "Шахта піддана нападу (видано)", ["Mine Assaulted slain"] = "Шахта піддана нападу: убито" } },
    [8114] = { [1] = "Контроль над чотирма базами", [2] = "{ім'я:к}, ти {стать:відбив:відбила} атаку наших ворогів в низині Араті та {стать:заслужив:заслужила} велику пошану на цьому полі бою. Ти {стать:показав:показала} нам свою цінність і {стать:дав:дала} зрозуміти нашим ворогам, що ми не підкоримося їхньому лиходійству!\n\nВраховуючи твою репутацію, я маю для тебе важке завдання. Я хочу, щоб ти {стать:захопив та контролював:захопила та контролювала} одночасно чотири бази в низині Араті. Якщо ти зможеш це зробити, то ми не тільки забезпечимо себе критично важливими ресурсами, але й продемонструємо Орді нашу силу!\n\nВперед, {ім'я:к}, і щасливої дороги.", [3] = "Ввійдіть в низину Араті, візьміть під контроль чотири бази одночасно, після чого поверніться до фельдмаршала Осяйва в Опорний пункт.", [4] = "Ти ще не {стать:захопив:захопила} чотири бази, {ім'я:к}. Повертайся до низини Араті й виконай своє завдання!", [5] = "Відмінна робота, {ім'я:к}! До мене прибіг схвильований розвідник з доповіддю про твої подвиги. Ми в Лізі Аратора залишилися дуже задоволені!\n\nТи швидко стаєш {стать:справжнім героєм:справжньою героїнею} серед солдатів Ліги і сьогоднішній вчинок ще раз доводить твою бездоганну репутацію.", ["en"] = "Control Four Bases", ["tasks"] = { ["Control Four Bases."] = "Контролюйте чотири бази." } },
    [8115] = { [1] = "Контроль над п'ятьма базами", [2] = "{ім'я:к}, боротьба за ресурси низини Араті — кривава справа. Твої послуги дуже необхідні Лізі Аратора та ціняться повною мірою.\n\nІ в нас є для тебе ще одне завдання.\n\nЛіга хоче завдавати одного сильного удару по Труїтелях, що окупували низину Араті. Ми хочемо вигнати їх з усіх стратегічних точок на полі бою!\n\nЦе буде нелегко, але якщо хтось і може це зробити, то це ти.", [3] = "Візьміть під контроль одночасно 5 баз в низині Араті, після чого поверніться до фельдмаршала Осяйва в Опорний пункт.", [4] = "Ти ще не {стать:завершив:завершила} своє завдання, {ім'я:к}. Воно непросте, але моя віра в тебе сильна.", [5] = "Ти {стать:зробив:зробила} це! Ти {стать:захопив:захопила} усі бази! Молодець, {ім'я:к}!\n\nБагато хто сумнівався в тобі, але я знав, що ти зможеш це зробити. Дякую тобі й знай, що Ліга Аратора поважає тебе не менше, ніж відречені Труїтелі бояться одної тільки згадки твого імені!", ["en"] = "Control Five Bases", ["tasks"] = { ["Take Five Bases."] = "Візьміть п'ять баз." } },
    [8149] = { [1] = "Вшанування героя", [2] = "Під час Свята врожаю Азерота, ми висловлюємо шану героям за жертви, що вони принесли заради нас. Альянс визнає багатьох героїв, але ніхто не уособлює жертовність так, як Утер Світлоносець.\n\nДопоможи нам вшанувати Утера, віднеси ці підношення до його могили в Західні Зачумлені землі. Поклади їх до статуї, а потім повертайся до мене. Я буду тут лише до кінця фестивалю, тому не гай часу та вшануй Утера.", [3] = "Відправляйтеся до могили Утера в Західні Зачумлені землі та покладіть підношення біля статуї. Поверніться до Вагнера Молотобойця поблизу Залізогарта до завершення Свята врожаю.", [4] = "Ти {стать:був:була} біля могили Утера і {стать:поклав:поклала} підношення?\n\nДля менш досвідчених шукачів пригод ця подорож може бути небезпечною. Безпечніше, наскільки це можливо, буде пройти шляхом на північ від річки, що протікає через Гіллзбрад у Зачумлені землі. Вона витікає з озера, що прилягає до пагорба Скорботи. Йди на захід через пагорби, тримаючись якомога далі від кладовища... того, що повне Скари.", [5] = "Утер був героєм серед героїв. Я навіть не можу уявити, який біль він відчув, коли Артас — його найкращий учень і той, кого Утер любив, як рідного сина — зрадив усе людство. Проте, він піднявся, щоб спробувати зупинити Артаса, і за це його назавжди запам'ятають як справжнього паладина. Він бився до кінця, думаючи лише про тих, кого міг врятувати.\n\nДякую тобі, {ім'я}. Сьогодні ти {стать:віддав:віддала} шану великому герою, вшанувавши його дух і дух Свята врожаю.", ["en"] = "Honoring a Hero", ["tasks"] = { ["Uther's Tribute"] = "підношення Утеру" } },
    [8166] = { [1] = "Битва за низину Араті!", [2] = "{ім'я:к}, битва за низину Араті — це битва за ресурси та територію. Ключові пункти на цій території повинні контролюватися для забезпечення нашого війська необхідною сировиною та припасами. Я наказую тобі штурмувати найвіддаленіші точки від нашої бази в низині Араті.\n\nНапади на ферму, шахту, лісопильню та кузню, якщо їх контролює ворог. Знайди ворожий прапор і зірви його зі стовпа!\n\nКоли зробиш це з усіма чотирма точками, повернись до мене.", [3] = "Нападіть на шахту, лісопильню, кузню і ферму в низині Араті, після чого поверніться до фельдмаршала Осяйва в Опорний пункт.", [4] = "{ім'я:к}, ти ще не {стать:атакував:атакувала} чотири бази. Повертайся до мене, коли виконаєш своє завдання.", [5] = "Я дізнався про твої подвиги в низині Араті, {ім'я:к}. Чудова робота! Я вірю, що з такими бійцями, як ти, одного дня ми зможемо повернути собі нашу батьківщину.", ["en"] = "The Battle for Arathi Basin!", ["tasks"] = { ["Blacksmith Assaulted"] = "Напад на коваля", ["Blacksmith Assaulted (Provided)"] = "Напад на коваля (видано)", ["Blacksmith Assaulted slain"] = "Напад на коваля: убито", ["Farm Assaulted"] = "Напад на ферму", ["Farm Assaulted (Provided)"] = "Напад на ферму (видано)", ["Farm Assaulted slain"] = "Напад на ферму: убито", ["Lumber Mill Assaulted"] = "Напад на лісопильний завод", ["Lumber Mill Assaulted (Provided)"] = "Напад на лісопильний завод (видано)", ["Lumber Mill Assaulted slain"] = "Напад на лісопильний завод: убито", ["Mine Assaulted"] = "Шахта піддана нападу", ["Mine Assaulted (Provided)"] = "Шахта піддана нападу (видано)", ["Mine Assaulted slain"] = "Шахта піддана нападу: убито" } },
    [8167] = { [1] = "Битва за низину Араті!", [2] = "{ім'я:к}, битва за низину Араті — це битва за ресурси та територію. Ключові пункти на цій території повинні контролюватися для забезпечення нашого війська необхідною сировиною та припасами. Я наказую тобі штурмувати найвіддаленіші точки від нашої бази в низині Араті.\n\nНапади на ферму, шахту, лісопильню та кузню, якщо їх контролює ворог. Знайди ворожий прапор і зірви його зі стовпа!\n\nКоли зробиш це з усіма чотирма точками, повернись до мене.", [3] = "Нападіть на шахту, лісопильню, кузню і ферму в низині Араті, після чого поверніться до фельдмаршала Осяйва в Опорний пункт.", [5] = "Я дізнався про твої подвиги в низині Араті, {ім'я:к}. Чудова робота! Я вірю, що з такими бійцями, як ти, одного дня ми зможемо повернути собі нашу батьківщину.", ["en"] = "The Battle for Arathi Basin!", ["tasks"] = { ["Blacksmith Assaulted"] = "Напад на коваля", ["Blacksmith Assaulted (Provided)"] = "Напад на коваля (видано)", ["Blacksmith Assaulted slain"] = "Напад на коваля: убито", ["Farm Assaulted"] = "Напад на ферму", ["Farm Assaulted (Provided)"] = "Напад на ферму (видано)", ["Farm Assaulted slain"] = "Напад на ферму: убито", ["Lumber Mill Assaulted"] = "Напад на лісопильний завод", ["Lumber Mill Assaulted (Provided)"] = "Напад на лісопильний завод (видано)", ["Lumber Mill Assaulted slain"] = "Напад на лісопильний завод: убито", ["Mine Assaulted"] = "Шахта піддана нападу", ["Mine Assaulted (Provided)"] = "Шахта піддана нападу (видано)", ["Mine Assaulted slain"] = "Шахта піддана нападу: убито" } },
    [8168] = { [1] = "Битва за низину Араті!", [2] = "{ім'я:к}, битва за низину Араті — це битва за ресурси та територію. Ключові пункти на цій території повинні контролюватися для забезпечення нашого війська необхідною сировиною та припасами. Я наказую тобі штурмувати найвіддаленіші точки від нашої бази в низині Араті.\n\nНапади на ферму, шахту, лісопильню та кузню, якщо їх контролює ворог. Знайди ворожий прапор і зірви його зі стовпа!\n\nКоли зробиш це з усіма чотирма точками, повернись до мене.", [3] = "Нападіть на шахту, лісопильню, кузню і ферму в низині Араті, після чого поверніться до фельдмаршала Осяйва в Опорний пункт.", [5] = "Я дізнався про твої подвиги в низині Араті, {ім'я:к}. Чудова робота! Я вірю, що з такими бійцями, як ти, одного дня ми зможемо повернути собі нашу батьківщину.", ["en"] = "The Battle for Arathi Basin!", ["tasks"] = { ["Blacksmith Assaulted"] = "Напад на коваля", ["Blacksmith Assaulted (Provided)"] = "Напад на коваля (видано)", ["Blacksmith Assaulted slain"] = "Напад на коваля: убито", ["Farm Assaulted"] = "Напад на ферму", ["Farm Assaulted (Provided)"] = "Напад на ферму (видано)", ["Farm Assaulted slain"] = "Напад на ферму: убито", ["Lumber Mill Assaulted"] = "Напад на лісопильний завод", ["Lumber Mill Assaulted (Provided)"] = "Напад на лісопильний завод (видано)", ["Lumber Mill Assaulted slain"] = "Напад на лісопильний завод: убито", ["Mine Assaulted"] = "Шахта піддана нападу", ["Mine Assaulted (Provided)"] = "Шахта піддана нападу (видано)", ["Mine Assaulted slain"] = "Шахта піддана нападу: убито" } },
    [81762] = { [1] = "Деякі гарні новини", [2] = "Вітаю, {ім'я}. У мене гарні новини. Я зв'язався зі своїм другом і скоро вирушаю на зустріч з ним. Більше того, в Калімдорі з'явилася ще одна сфера. Я не можу бути в двох місцях одночасно, тому, якщо ви згодні, я б хотів, щоб ви пішли замість мене, щоб розслідувати цю нову сферу. Поговоріть з Кетрін для отримання подальших інструкцій.", [3] = "Поговоріть з Катериною Чистокровною у Соборі Світла у Штормовії.", [5] = "Радий знову тебе бачити, {ім'я}. Давай розповімо тобі про це.", ["en"] = "Some Good News" },
    [81764] = { [1] = "Таємничий торговець", [2] = "До зустрічі, {ім'я}. Шоу та його шпигуни надали нам інформацію про таємничого торговця, який щойно прибув до Калімдору та хоче позбутися колекції небезпечних артефактів. Ми дійшли висновку, що в його колекції є Сфера Відлуння. Він зупинився в корчмі «Терамор» у Пилових Болотах. Подорожуйте швидко, знайдіть сферу та нікому про це не кажіть. Ми відправляємо вас одного, щоб не привертати уваги наших ворогів.\n\nБудьте обережні та йдіть зі світлом.", [3] = "Подорожуйте до Терамору та знайдіть таємничого торговця.", [5] = "А, ти встиг! Кетрін послала мене допомогти тобі у твоїй місії. Але нам треба поспішати, наша здобич втекла!", ["en"] = "The Mysterious Merchant" },
    [81765] = { [1] = "Елрік, паладин Срібної Руки", [2] = "Паладин, який стоїть перед вами, вам не відомий. Поговоріть з ним, щоб дізнатися, що йому відомо про торговця та поточну ситуацію.", [3] = "Поговоріть з Елріком, щоб дізнатися більше.", [5] = "Дякую світлу за тебе, {клас}! Я так боявся. Я думав, що ці бандити нас уб'ють!", ["en"] = "Elrick, Paladin of the Silver Hand" },
    [81766] = { [1] = "Криваве послання", [2] = "Ви знаходите послання на тілі «паладина». Воно вкрите кров’ю і його важко прочитати, але ви можете розібрати послання на пергаменті. Вам слід вивчити його, а потім повернутися до Катерини за подальшими інструкціями.", [3] = "Віднесіть послання Катерині Чистокровній до Собору Світла в Штормовії.", [4] = "Отже, це була пастка... це дуже тривожно.", [5] = "Це благословення, що ти в безпеці, {ім'я}. Я сподіваюся, що куди б не пішов Еонас, він не потрапить у подібну небезпеку. Він винахідливий, тому я маю вірити, що з ним все буде гаразд. Якщо я щось від нього почую, я негайно зв'яжуся з тобою. Дякую, {ім'я}.\n\nІ останнє. Він довірив мені це передати тобі, коли ти повернешся. Використовуй це добре та йди за світлом.", ["en"] = "The Bloody Missive", ["tasks"] = { ["Bloody Missive"] = "Криваве послання" } },
    [81790] = { [1] = "Важливі матеріали", [2] = "Кожна з Лунуючих Сфер налаштована на окремий аспект свого господаря, і метод, який ви використали в Ясенедолі, щоб знищити Сферу Альталакса, не буде ефективним для сфери, якою ми володіємо. Я знаю про ритуал, який може дестабілізувати сферу та дозволити нам знищити її, але для нього потрібні компоненти з певним магічним значенням. Ми вже маємо деякі з необхідних матеріалів, але вам потрібно буде отримати решту. Візьміть це, це має допомогти вам у ваших пошуках.", [3] = "Знайдіть матеріали, перелічені в записці Грегорі, та поверніть їх Грегорі біля джерела водоспаду Кривава Отрута у Фехтвуді.\n\nНаданий предмет:", [4] = "Мабуть, це була справжня пригода — отримати ці предмети. Молодець.", [5] = "Тепер, коли у нас є матеріали, я маю підготувати ритуал. А поки що порадьтеся з Еонасом. Він хоче поговорити з вами.", ["en"] = "Materials of Significance", ["tasks"] = { ["Item #220170"] = "Артикул №220170" } },
    [81885] = { [1] = "Ритуал", [2] = "Я хотів би подякувати вам за ваші зусилля, {ім'я}. Без вас я, ймовірно, був би мертвим, а слуги легіону досі володіли б цим небезпечним артефактом. Я знаю, що важко довіряти агенту Короля-Ліча, але я сподіваюся, що після того, як це закінчиться, ми зможемо схилити мого друга назад до світла. Зрозуміло, що людина, про яку я піклувався, все ще там. Йому, можливо, потрібен лише поштовх.\n\nНу ж бо, ми потрібні Грегорі, щоб допомогти йому завершити ритуал. Давайте поговоримо ще раз, коли він закінчиться.", [3] = "Поговоріть з Григорієм, щоб розпочати ритуал.", [4] = "<Еонас дивиться з краю скелі з явним шоком від того, що щойно сталося>", [5] = "У мене немає слів, {ім'я}. Зустріч з Грегорі знову сповнила мене небезпечною надією. Його природа оголилася з моменту нашого відновлення зв'язку, і було багато ознак, що вказували на цей кінець. Я був сліпий до них.\n\nБудь ласка, забери цю прокляту кулю і залиш мене. Мені є над чим поміркувати.", ["en"] = "The Ritual" },
    [81944] = { [1] = "Нововідкрита мета...", [5] = "Я... не можу цього пояснити, {раса}, але гадаю, що маю дещо, що тобі потрібно. Я прийшов у цю землю, щоб шукати знань, і ці пошуки привели мене на гору он он там, до велетенського каменю світла, що впав з неба. Споглядаючи камінь, Ан'ше обдарувала мене багатьма речами. Одним з них було відчуття нової мети. Іншим було бачення нас із тобою, тут, під час цієї розмови. Гадаю, я дав тобі це.\n\nБудь ласка, візьми цей тотем. Використовуй його добре на служінні Ан'ше... на служінні світлу.", ["en"] = "A Newly Discovered Purpose..." },
    [82081] = { [1] = "Порушений ритуал", [2] = "Ця бездоганна лопатка надто впізнавана — Хаккара викликали у фізичний світ і перемогли. Тролі на острові Йоджамба захочуть почути більше про те, що сталося всередині Затонулого Храму.", [3] = "Принесіть Лопатку занепалого Аватара Молтору на острові Йоджамба.", [4] = "{ім'я}, які у тебе новини з Храму Атал'Хаккара?", [5] = "Не може бути... чутки про Храм Атал'Хаккара правдиві?\n\nТвою перемогу в Затонулому Храмі Зандалари ще довго пам'ятатимуть, друже. Ця кістка... дивний вибір для нашого визволення... але, безсумнівно, її використовували для виклику Хаккара у фізичний світ — тепер вона буде в надійних руках, {ім'я}. Нам більше не потрібно турбуватися про повернення Хаккара завдяки твоїм зусиллям, друже... чи не так?", ["en"] = "A Broken Ritual", ["tasks"] = { ["Item #221346"] = "Товар №221346" } },
    [82098] = { [1] = "В храм Атал'Гаккар", [2] = "Згідно з легендою, Храм Атал'Хаккара — це святиня, присвячена стародавньому богу Хаккару, Володарю Душ. Храм, що підтримується злим племенем тролів на ім'я Атал'ай, за чутками вважається непроникним.\n\nТепер, коли храм затонув під Озером Сліз, витягти артефакти з нього ще складніше. Але саме це мені потрібно від тебе, {ім'я}.\n\nДопоможи мені, зібравши неушкоджені Скрижалі Атал'ай. Принеси їх мені, і я повернуся до Гільдії Дослідників героєм. Разом ми розділимо славу.", [3] = "Зберіть 10 табличок Атал'ай для Брохана Каскбеллі у Штормовії.", [4] = "Коли сутінки повільно опускаються на мій шлях, я звертаюся до тебе, {ім'я}, щоб ти допоміг мені в моїх останніх пошуках Ліги Дослідників. Якби мої старі кістки могли набратися сил, щоб пройти Болото Скорботи та затонулий храм, я б бився пліч-о-пліч з тобою.\n\nГордість заважає мені просити твоєї допомоги у зборі Скрижалей Атал'ай. Але старість змушує це робити.\n\nБудь ласка, допоможи мені, {ім'я}. Я хочу піти з Ліги Дослідників, виконавши їхнє останнє завдання.", [5] = "Таблички Атал'ай! Дякую, {ім'я}!\n\nЯк тільки я доставлю їх Лізі Дослідників, наші імена разом увійдуть в історію. Ви допомогли старому гномові виконати його останній обов'язок у житті. За це я безмежно вдячний.", ["en"] = "Into The Temple of Atal'Hakkar" },
    [82099] = { [1] = "Туман зла", [2] = "Чесно кажучи, {ім'я}, я ніколи не бачив таких рослин у своїх подорожах. Можливо, мені варто з'їздити до цього кратера...\n\nУ будь-якому разі, я думаю, що знаю саме те, що шукає Муйгін — серпанок Атал'ай. Це жахлива штука, її важко зібрати, але це саме те, що йому потрібно, щоб контролювати маленьких монстрів.\n\nВам потрібно буде відвідати храм Атал'Хаккара в Болоті Скорбот. Серпанок Атал'ай можна зібрати з глибинних хованок, темних черв'яків або слизу, що там знаходяться. Удачі, {ім'я}!", [3] = "Зберіть 5 зразків Атал'айської імли, а потім поверніться до Муйгіна в кратері Ун'Горо.", [4] = "Ларіон досі зі мною не розмовляє! Він точно знає, як затаїти образу.", [5] = "Зізнаюся, я трохи вагаюся доторкатися до цієї штуки, {ім'я}! Але якщо Греган каже, що це спрацює, то я готовий спробувати!", ["en"] = "Haze of Evil" },
    [82106] = { [1] = "Кування каменю сили", [2] = "Тепер ми повинні поєднати інертні камені бича та створити зброю, щоб розтрощити ряди нежиті. Це нелегке завдання, {ім'я}. Тільки тролі затонулого храму володіють рідкісною магією, здатною обернути зло чогось проти нього самого.\n\nУ храмі тролі відомі як Гашер, Міджан, Золо, Хукку, Зул'лор та Лоро. Не відчувайте докорів сумління за їхні зіпсовані душі... вони не позбавлені зла.", [3] = "Принесіть пір'я вуду Ашламу Кулаку Доблесті.", [4] = "Ти вбив цих жалюгідних тролів?", [5] = "Це чудово, {ім'я}. Я б сказав, що здивований, але я беззаперечно знав, що ви нас не підведете.\n\nДля мене честь подарувати вам один зі Священних Каменів Могутності. Використовуйте його з розумом.", ["en"] = "Forging the Mightstone" },
    [82135] = { [1] = "Ціна надії", [2] = "<Еонас нічого не каже, він просто передає тобі кулю та відвертається>", [3] = "Принесіть Кулю Відлуння Маннорока Катерині Чистокровній у Штормовій.", [4] = "Ласкаво просимо назад, {ім'я}. Що це у тебе там...\n\nОго.", [5] = "Це досить тривожна історія. Частина мене, яка є {клас}, не може змиритися з тим, що він добровільно спілкувався з членом бича... але частина мене, {раса}, розуміє, наскільки міцними можуть бути узи дружби.\n\nДякую тобі за те, що приніс сюди кулю. Я простежу, щоб вона зберігалася в найглибшому сховищі, яке у нас є наразі.\n\nО, і останнє: я відремонтував її і сподівався подарувати Еонасу після його повернення. Думаю, він захоче, щоб ти володів нею замість нього.", ["en"] = "The Price of Hope", ["tasks"] = { ["Mannoroc Orb"] = "Сфера Маннорока" } },
    [82210] = { [1] = "Нагорода за намисто тролів", [4] = "Ви вже це зробили, але ми продовжуватимемо приймати будь-які намиста племені тролів, які ви знайдете та захочете здати. Здавши їх мені, ви продовжите покращувати своє становище серед Диких Молотів; якщо ви готові битися за нас, то й ми будемо готові битися за вас!\n\nМені потрібно п'ять намист племені тролів, щоб вони зарахувалися, {ім'я}.", [5] = "Ще один комплект намист означає, що у Внутрішніх Землях менше тролів, про яких нам доводиться турбуватися! Ти знову це зробив, {ім'я}. Продовжуй у тому ж дусі!", ["en"] = "Troll Necklace Bounty" },
    [8229] = { [1] = "Візьми брошурку", [5] = "Цієї неділі в Грабіжній Бухті відбудеться змагання з риболовлі! Ось брошурка з правилами!", ["en"] = "Could I get a Fishing Flier?" },
    [8261] = { [1] = "Стандартний набір припасів Ліги Аратора", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я:к}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в низині Араті.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в низині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть дружніми, а бинти — коли почесними.", ["en"] = "Arathor Standard Care Package", ["tasks"] = { ["The League of Arathor"] = "Ліга Аратора" } },
    [8262] = { [1] = "Покращений набір припасів Ліги Аратора", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я:к}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в низині Араті.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в низині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть дружніми, а бинти — коли почесними.", ["en"] = "Arathor Advanced Care Package" },
    [82657] = { [1] = "Жилет з дикої шкіри", [2] = "Жилети з дикої шкіри є основою будь-якого комплекту обладунків з дикої шкіри. Каркас жилета поєднується з дикою лозою, створюючи виріб, який забезпечує максимальний захист тулуба, водночас дозволяючи потужній магії проникати крізь одяг.\n\nДля цього викрійки мені знадобляться два нагрудники з луски черепахи, два комплекти рукавичок з луски черепахи та дика лоза. Це складне замовлення, але ви не повинні мати труднощів з його виконанням для мене.", [3] = "Принесіть 2 нагрудники з луски черепахи, 2 рукавички з луски черепахи та Дику лозу Пратту МакГраббену у фортеці Пернатого Місяця.", [4] = "У тебе є два нагрудники та рукавички з луски черепахи, які я замовив? Також не забудь про дику лозу!\n\nНавіть з найдавнішими викрійками ми дізнаємося, що основи форми добре підходять для складніших виробів. Хоча це різні вироби, форма нагрудників з луски черепахи готує тебе до деталей, необхідних для виготовлення жилета з дикої шкіри.\n\nА рукавички... ну, вони просто для моєї власної користі. Пам'ятай, ти працюєш на мене!", [5] = "Ось кілька дуже гарних виробів, {ім'я}. Майстерність та ретельність, вкладені у їх виготовлення, принесли б на кілька срібних центнерів більше, ніж середній виріб.\n\nВи виконали моє замовлення, а разом з ним приходить ваша нагорода. Тепер ваші знання про виготовлення жилетів з дикої шкіри!", ["en"] = "Wild Leather Vest" },
    [82662] = { [1] = "Шлях зброяра", [2] = "Як зброяр, ви побачите, що найчастіше герої та шукачі пригод звертатимуться до вас за спорядженням. Хоча робоче навантаження часом може бути нестерпним, багатство з лишком компенсує напруження спини та біль у легенях.\n\nО так, {ім'я}, зброярі — це ті, у кого все золото!\n\nЯкщо ви хочете приєднатися до наших лав, вам потрібно буде показати мені, що ви можете заробити мені срібло чи два — тобто, показати мені, що у вас є все необхідне, щоб бути тим, до кого звертаються <хлопець/дівчина>, коли людям потрібна високоякісна зброя. Беріться за роботу!", [3] = "Щоб стати Зброярем, ви повинні виготовити такі предмети та повернути їх Айронусу: 4 мечі з місячної сталі, 4 масивні залізні сокири, 2 важкі міфрилові сокири та 2 великі чорні булави.", [4] = "<Айронус зайнятий складанням золотих монет у акуратні купки.>", [5] = "Вже час! У мене чекають клієнти.\n\nДайте це сюди і зверніть увагу. Ви зробите перший крок у своїй кар'єрі зброяра.", ["en"] = "The Way of the Weaponsmith" },
    [8271] = { [1] = "Герой Бурешпиля", [5] = "Як {стать:герой:героїня} Бурешпиля, можеш вибрати один предмет з цих нещодавно викра... тобто, знайдених скарбів.", ["en"] = "Hero of the Stormpike" },
    [8275] = { [1] = "Відвоювання Силітуса", [2] = "Увага, герої Альянсу! Ми надто довго не зважали на загрозу силітидів. Їм ніхто не протистояв, і вони весь цей час готувалися до масштабного вторгнення.\n\nСили Кенарійського Кола збираються в Силітусі, щоб дати відсіч цим потворам, і ми закликаємо всіх здібних шукачів пригод приєднатися до нас!\n\nПоспішіть, доки не пізно! Допоможіть нам захистити Азерот! Поговоріть з вітрозовом Гордим Рогом у Кенарійській цитаделі, щоб отримати подальші вказівки!", [3] = "Поговоріть з вітрозовом Гордим Рогом в Кенарійській цитаделі, що в Силітусі.", [5] = "Чудово, ми завжди раді новим рекрутам, що готові виступити проти силітидів. Ласкаво просимо до Кенарійської цитаделі, {клас:к}. Приємно бачити, що слова наших емісарів доходять до таких героїв, як ти. У тебе буде вдосталь можливостей допомогти нам, і я сподіваюся, що ти станеш {стать:цінним союзником:цінною союзницею}.", ["en"] = "Taking Back Silithus" },
    [83] = { [1] = "Червоні льняні вироби", [2] = "Банда Непокірних з Північнокраю носить маски з мішковини, але Непокірні в Ельвинні надають перевагу льону, який я можу використати для пошиття вишуканих товарів.\n\nПринеси мені червоні льняні бандани, і я використаю їх, щоб зробити щось для тебе.\n\nТабори банди Непокірних є по всьому Ельвинну.", [3] = "Принесіть 6 червоних льняних бандан Сарі Древоляг у лісозаготівельний табір Східнодолу.", [4] = "У мене закінчуються запаси льону, {Ім'я}. У тебе є що-небудь для мене?", [5] = "О-о-о, гарні бандани, правда, трохи кошлаті...", ["en"] = "Red Linen Goods", ["tasks"] = { ["Red Linen Bandana"] = "червона лляна бандана", ["Red Linen Bandana (Provided)"] = "червона лляна бандана (видано)" } },
    [8311] = { [1] = "Ласощі Повечір'я святих для Джеспера!", [2] = "Я хочу піти збирати цукерки, але не можу, бо я хворий. Якщо ти підеш за мене, я обміняю отримані тобою цукерки на ті, які вже у мене! Я думаю, тобі сподобаються ці цукерки — вони змушують тебе перетворюватися на смішні й жахливі речі!\n\nКорчмар у великих містах мають цукерки, які вони віддають на Повечір'я святих — поговори з ними й виконай будь-які забаганки, які вони попросять! Також маленький гном, на ім'я Талваш у Залізогарті роздає цукерки. Коли збереш всі цукерки — повертайся з ними до мене!", [3] = "Поговоріть з корчмарями Штормовію, Залізогарта та Дарнасу, а також з Талвашем дель Кісселєм в Залізогарті. Виконайте те, що вони захочуть в обмін на ласощі.\n\nПоверніться до Джеспера в сиротинець Штормовію з марципаном Дарнасу, мармеладом Гномреґана, нугою Штормовію і м'ятною цукеркою Залізогарта.", [4] = "Ти вже {стать:закінчив:закінчила} ходити по цукерки? Мені шкода, що я не можу піти, бо хворію, але завдяки твоїй допомозі мені стало трохи легше...", [5] = "Ого, ти {стать:приніс:принесла} всі цукерки! Ти просто {стать:неймовірний:неймовірна}!\n\nДякую, що {стать:збирав:збирала} їх для мене. Ось, візьми ці гарбузові ласощі — думаю, вони тобі дуже сподобаються!\n\nЩасливого Повечір'я святих, {ім'я}!", ["en"] = "Hallow's End Treats for Jesper!", ["tasks"] = { ["Darnassus Marzipan"] = "марципан Дарнасу", ["Darnassus Marzipan (Provided)"] = "марципан Дарнасу (видано)", ["Gnomeregan Gumdrop"] = "мармелад Гномреґана", ["Gnomeregan Gumdrop (Provided)"] = "мармелад Гномреґана (видано)", ["Ironforge Mint"] = "м'ятна цукерка Залізогарта", ["Ironforge Mint (Provided)"] = "м'ятна цукерка Залізогарта (видано)", ["Stormwind Nougat"] = "нуга Штормовію", ["Stormwind Nougat (Provided)"] = "нуга Штормовію (видано)" } },
    [8353] = { [1] = "Кудахкання за цукерку", [2] = "А, ти збираєш цукерки для хворої дитини, чи не так? Я маю на увазі, ти трохи {стать:старуватий:старувата}, щоб цукерки випрошувати...\n\nЩо ж, за мої ласощі — м'ятну цукерку Залізогарта — тобі потрібно буде... кудахкати, як курка! Так, курки люблять м'ятні цукерки... ну добре, можливо, вони не ЛЮБЛЯТЬ їх... але я не дам тобі м'ятну цукерку, поки ти не закудахкаєш для мене!\n\nНу що, {клас:к}, ти {стать:готовий:готова} кудахкати чи ні?! Час заробити свої ласощі!", [3] = "Зобразіть курку перед корчмарем Вогневаром, та отримайте м'ятну цукерку Залізогарта!", [4] = "Я чекаю...", [5] = "Дуже смішно! Молодець, {ім'я}! Ось твої ласощі.\n\nЩасливого Повечір'я святих!", ["en"] = "Chicken Clucking for a Mint", ["tasks"] = { ["Cluck like a chicken for Innkeeper Firebrew"] = "Кудакни, як курка, для вогняного пива шинкаря" } },
    [8355] = { [1] = "Чух-чух, мармелад!", [2] = "Цукерки або життя! Ура!\n\nОтож, навіть якщо ти займаєшся благородною справою і збираєш цукерки для хворої дитини, я не можу так легко дати їх тобі. Я дам тобі смачний мармелад Гномреґана... якщо ти зобразиш для мене потяг! Ха-ха, так, хай буде так! Ціна цього мармеладу — звук потяга!\n\nЧух-чух, {клас:к}!", [3] = "Зобразіть потяг перед корчмарем Талвашем дель Кісселєм, та отримайте мармелад Гномреґана!", [4] = "Ну, можеш починати...", [5] = "Чух-чух! Молодець, {{ім'я}}! Ось твої ласощі.\n\nЩасливого Повечір'я святих!", ["en"] = "Incoming Gumdrop", ["tasks"] = { ["Do the \"train\" for Talvash"] = "Здійсніть \"поїзд\" до Талваша" } },
    [8356] = { [1] = "Пограй м'язами за нугу!", [2] = "Це... цікавий костюм у тебе є. Попри те, що ти {стать:добрий:добра} і допомагаєш хворій дитині збирати цукерки на Хелловін, на жаль, мені доведеться попросити тебе щось продемонструвати!\n\nПодивимося... ти виглядаєш {стать:таким сильним і мускулистим:такою сильною і мускулистою} в цьому... костюмі... давай покажи мені свої м'язи, {стать:силачу:силачко}!\n\nТільки коли ти покажеш свої м'язи, я дам тобі смачну нугу Штормовію. Це чудові ласощі для Повечір'я святих.", [3] = "Пограйте м'язами перед корчмаркою Еллісон, та отримайте нугу Штормовію!", [4] = "Ніяких ласощів, доки не покажеш м'язи, {ім'я}...", [5] = "Ти справді {стать:могутній:могутня}, ха-ха! Молодець, і дякую, що ти {стать:такий вправний:така вправна}. Ось твої цукерки.\n\nЩасливого Повечір'я святих, {ім'я}!", ["en"] = "Flexing for Nougat", ["tasks"] = { ["Flex for Innkeeper Allison"] = "Гнучкий для шинкарки Еллісон" } },
    [8357] = { [1] = "Танець за марципан", [2] = "Попри те, що ти збираєш цукерки для хворої дитини, тобі все одно потрібно щось продемонструвати, щоб отримати винагороду! Ми не можемо зраджувати традиціям, чи не так...\n\nЯ вважаю, що гідна ціна за шматочок марципана — танець! Так, я хочу побачити твої рухи! Станцюй для мене, і отримаєш смачний марципан!", [3] = "Станцюйте перед корчмаркою Саліенною, та отримайте марципан Дарнасу!", [4] = "Ти вмієш танцювати, так? Спробуй, ставиш праву ногу вперед... тепер назад... вперед... а тепер потряси нею...", [5] = "Ти справжня машина танцю, {ім'я}!\n\nОсь тобі частування за те, що ти {стать:такий вправний танцюрист:така вправна танцюристка}. Щасливого Повечір'я святих, і передавай мої найкращі побажання твоєму хворому маленькому другу! Сподіваюся, він скоро одужає.", ["en"] = "Dancing for Marzipan", ["tasks"] = { ["Dance for Innkeeper Saelienne"] = "Танець для шинкарки Саеліенн" } },
    [8371] = { [1] = "Спільні зусилля", [2] = "Ми більше не воюємо проти Орди лише з одного фронту, {стать:хлопче:дівчино}.\n\nПеремога на одному фронті означає позбавлення війська Орди ресурсів, які вони могли б використати проти нас в іншій битві. Так само й програш будь-якої битви може дати нашому супротивнику перевагу в іншому місці.\n\nАльянсу не вистачає бійців, які б добряче розуміли це... справжніх досвідчених ветеранів! {ім'я:к}, повертайся до мене після того, як побуваєш на всіх полях битви проти Орди.", [3] = "Принесіть 3 відзнаки честі Альтерацької долини, 3 відзнаки честі низини Араті та 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Як йдуть справи на фронтах, {стать:друже:подруго}?", [5] = "Я знав, що ти не підведеш, {ім'я:к}! Те, чого ти {стать:досяг:досягла}, не виміряти нікчемними медалями й нагородами. Здобути подібний досвід можна лише пройшли крізь битви на полях бою.\n\nТи молодець, {клас:к}. {стать:Справжній герой:Справжня героїня} Альянсу!", ["en"] = "Concerted Efforts", ["tasks"] = { ["Alterac Valley Mark of Honor"] = "відзнака честі Альтерацької долини", ["Alterac Valley Mark of Honor (Provided)"] = "відзнака честі Альтерацької долини (видано)", ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)", ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [83808] = { [1] = "У скрутному становищі", [2] = "Ти мало не до смерті мене налякав! Я чув, як ти йдеш, і був переконаний, що мертві нарешті мене винюхали! І все ж ти — видовище для очей. Будь ласка, мені потрібно втекти звідси та знайти свого господаря, сера Далтона. Чи не міг би ти повернути мені мою зброю? Її вирвали в мене з рук у полі, і я був змушений втекти в цей сарай.", [3] = "Знайдіть меч сквайра Катберта в полі на півдні та поверніть його йому.", [4] = "Ти дістав лезо?", [5] = "Дякую, {клас}. Я не можу висловити свою вдячність за вашу допомогу.\n\nМені потрібна лише мить, щоб зібратися з думками. Я отримав жахливий удар по голові там, на вулиці, і я не впевнений, чи зможу ще битися. О, Боже, допоможи мені, сподіваюся, сер Далтон у безпеці.", ["en"] = "In a Bind" },
    [83822] = { [1] = "Павший лицар", [2] = "Ви кажете, що знайшли його... тіло? Ні... мій пан не може бути мертвим. Наша робота ще не завершена.\n\nЯ... дякую вам, {клас}. Мені важко оговтатися від шоку, але я радий, що саме ви його знайшли.\n\nЗдається, його завдання тепер випало на мені. Однак спочатку я маю повернутися до його тіла та спалити його, щоб він не став тим самим, що прагнув знищити. Якщо дозволите ще раз вас нав'язати, чи не могли б ви, будь ласка, провести мене до місця, де загинув сер Далтон?", [3] = "Проведіть сквайра Катберта до тіла Полеглого Лицаря, якого ви знайшли раніше, і допоможіть йому спалити труп.\n\nЯкщо ви втратите сквайра Катберта, він повернеться до свого сховища в сараї біля Сліз Далсона і чекатиме на вас там.", [4] = "<Очі сквайра Катберта ніби дивляться прямо крізь тіло загиблого лицаря. Він злегка тремтить.>", [5] = "Здається, я знову у вашому боргу, {клас}. Навіть бачачи його тіло таким, важко повірити, що це правда. Я служу серу Далтону з дитинства, але відчуваю, що мені ще так багато чого потрібно навчитися, якщо я хочу завершити те, що розпочав сер Далтон.\n\nЯ не можу сподіватися, що зможу вас зараз утримати. Ви вже надзвичайно вшанували мене своєю люб'язною допомогою. Будь ласка, дозвольте мені більше не нав'язувати вас. Я якось звідси знайду дорогу.", ["en"] = "The Fallen Knight" },
    [83823] = { [1] = "Урок насильства", [2] = "Ваша техніка дуже цікава,{ім'я}. Трохи грубіша за техніку сера Далтона, але вона має більш «світський» характер, який, на мою думку, мені добре підходить. Щиро дякую, я вже стільки всього від вас навчився!", [4] = "Ваша техніка вражає! Трохи грубіша, ніж у сера Далтона, але вона має більш «світський» характер, який, на мою думку, вам пасує. Щиро дякую, я вже стільки всього у вас навчився і не можу дочекатися, щоб застосувати це проти нашого ворога!", [5] = "Ваш зброєносець покращив свої навички, подорожуючи разом з вами!", ["en"] = "A Lesson in Violence" },
    [8385] = { [1] = "Спільні зусилля", [4] = "А, {ім'я:н}. Сподіваюсь, ти продовжуєш ділитися своїм досвідом на наших фронтах. Багато наших хлопців та дівчат на передовій рівняються на таких досвідчених {стать:ветеранів:ветеранок}, як ти.", [5] = "Правду про тебе говорили, {ім'я:к}. Без таких, як ти, в Альянсу не було б жодного шансу проти диких бійців Орди.", ["en"] = "Concerted Efforts", ["tasks"] = { ["Alterac Valley Mark of Honor"] = "відзнака честі Альтерацької долини", ["Alterac Valley Mark of Honor (Provided)"] = "відзнака честі Альтерацької долини (видано)", ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)", ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [83935] = { [1] = "Розчищення шляху", [2] = "Головний біль дещо вщух, але я не думаю, що зможу вибратися звідси самостійно. Не хочу просити від вас більшого, але чи не могли б ви допомогти прорідити ряди та розчистити мені шлях для втечі?", [3] = "Убийте 5 Затьмарених зомбі, 10 Скелетних жахів та 10 Гниючих трупів, щоб допомогти сквайру Катберту розчистити шлях для втечі.", [4] = "Узбережжя чисте?", [5] = "Ще раз дякую, {клас}. Якби з нами був хтось на кшталт тебе, коли ми потрапили в засідку, я цілком впевнений, що засідка перетворилася б на розгром наших нападників за лічені хвилини!\n\nУ мене тепер відкрилося друге дихання, і я мушу знайти сера Далтона. Він дуже вправний лицар, але я впевнений, що йому потрібна моя допомога. Скажіть, ви бачили його там? Його важко не помітити в його блискучих білих пластинчастих обладунках.", ["en"] = "Clearing the Path" },
    [83936] = { [1] = "Пошуки Далтона", [2] = "<Сквайр Катберт порожньо дивиться на місце, де горить тіло Далтона. Він явно перебуває у стані шоку. Видно, що він не в стані продовжувати будь-які завдання, які він та його лорд задумали виконати. Можливо, вам варто поговорити з ним і дізнатися, чи можете ви ще допомогти?>", [3] = "Поговоріть зі сквайром Катбертом, щоб дізнатися більше про завдання сера Далтона.", [4] = "Я... дякую.", [5] = "Я... не знаю, що сказати. Незважаючи на похмурі обставини, мені неймовірно пощастило, що я опинився на службі ще одного справжнього героя Альянсу. Я можу лише сподіватися, що зможу служити вам краще, ніж служив серу Далтону.\n\nВперед, герою.", ["en"] = "Dalton's Quest" },
    [84] = { [1] = "Повернення до Біллі", [2] = "Тримай. І як віддаватимеш цей пиріг Біллі, передай, хай би він вдавився!", [3] = "Принесіть пиріг зі свинячої підчеревини Біллі Маклуру на виноградники Маклура.", [4] = "Ооой, я такий голодний! Цей пиріг випадково не для мене, {ім'я:к}?", [5] = "Мм, смакота! Цей пиріг найкращий!\n\nЗдається, я починаю щось пригадувати...", ["en"] = "Back to Billy", ["tasks"] = { ["Pork Belly Pie"] = "пиріг зі свинячої підчеревини", ["Pork Belly Pie (Provided)"] = "пиріг зі свинячої підчеревини (видано)" } },
    [84008] = { [1] = "Урок благодаті", [2] = "Ваша техніка дуже цікава,{ім'я}. Трохи грубіша за техніку сера Далтона, але вона має більш «світський» характер, який, на мою думку, мені добре підходить. Щиро дякую, я вже стільки всього від вас навчився!", [4] = "Завдяки вашим вченням я відчуваю більший зв'язок зі світлом, ніж будь-коли. Я починаю розуміти, що роль {клас} полягає в тому, щоб приймати милосердя так само, як і відточувати свою бойову майстерність. Я добре обміркую цей урок і застосую те, чого навчився, щоб зміцнити наших союзників!", [5] = "Ваш зброєносець покращив свої навички, подорожуючи разом з вами!", ["en"] = "A Lesson in Grace" },
    [84017] = { [1] = "Час убивати", [2] = "Я відчуваю, що так багато навчився за такий короткий час. Не думаю, що хтось колись буде по-справжньому готовий до того, з чим маю намір зіткнутися я, але я відчуваю себе готовим як ніколи. Що скажеш ти, {ім'я}? Може, підемо і закінчимо цю битву?\n\nЯ не впевнений, з чого почати, але підозрюю, що ми знайдемо підказки десь у Східних Чумних Землях. Нам, мабуть, варто почати з місць, де збирається Культ Проклятих.", [4] = "Помста близько, я це відчуваю!", [5] = "Здається, ми знайшли нашу здобич, але вона, здається, поза нашою досяжністю. Ми повинні знайти спосіб дістатися до неї, щоб мати змогу напасти.", ["en"] = "A Time to Kill" },
    [8404] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Не забувай, що боротьба за тіснину Пісні Війни — це більше, ніж просто захист дерев. Йдеться про збереження бар'єра між Ясенедолом та Степами. Є новини з поля бою, {ім'я:к}?", [5] = "Чудова робота, {ім'я:к}. Завдяки тобі наш захист Ясенедолу протримається ще деякий час.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8405] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Не забувай, що боротьба за тіснину Пісні Війни — це більше, ніж просто захист дерев. Йдеться про збереження бар'єра між Ясенедолом та Степами. Є новини з поля бою, {ім'я:к}?", [5] = "Чудова робота, {ім'я:к}. Завдяки тобі наш захист Ясенедолу протримається ще деякий час.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8406] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Не забувай, що боротьба за тіснину Пісні Війни — це більше, ніж просто захист дерев. Йдеться про збереження бар'єра між Ясенедолом та Степами. Є новини з поля бою, {ім'я:к}?", [5] = "Чудова робота, {ім'я:к}. Завдяки тобі наш захист Ясенедолу протримається ще деякий час.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8408] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Не забувай, що боротьба за тіснину Пісні Війни — це більше, ніж просто захист дерев. Йдеться про збереження бар'єра між Ясенедолом та Степами. Є новини з поля бою, {ім'я:к}?", [5] = "Чудова робота, {ім'я:к}. Завдяки тобі наш захист Ясенедолу протримається ще деякий час.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [84125] = { [1] = "Достатньо близько, щоб торкнутися", [2] = "Ці мерзенні некроманти та їхні хитрощі, це огидно. Ми повинні знайти спосіб пробити бар'єр, що захищає Арконоса, щоб покінчити з ним!\n\nВідомо, що багато заклиначів Культу Проклятих та Батога носять різноманітні знаряддя люті та осередки темної магії. Можливо, деякі з сусідніх Тінявих Магів або Ткачів Жаху мають щось, що ми могли б використати, щоб пробити щит?", [4] = "Що ти знайшов, {ім'я}?", [5] = "Так! Можливо, це саме те, що потрібно. Давайте швидше повернемося на бійню та випробуємо цей пристрій!", ["en"] = "Close Enough To Touch" },
    [84126] = { [1] = "Завершити бій", [2] = "Можливо, це саме воно, {ім'я}. Далтон довго вивчав Культ Проклятих і навчив мене багатьом благословенням, які можна використовувати для протидії їхній магії. Завдяки вашій старанності у завершенні мого навчання, я вважаю, що тепер я достатньо сильний, щоб накласти таке благословення на цей пристрій, щоб очистити його магію та використати його для руйнування бар'єру, що оточує Акронос.\n\nХодімо, спалімо щит цього боягуза і покінчимо з ним раз і назавжди!", [3] = "Убити Арконоса Проклятого", [4] = "Зрештою, помста.", [5] = "Мені важко повірити, що ми це зробили. Я не можу достатньо подякувати вам за допомогу, яку ви надали в цьому квесті, {ім'я}.\n\nТепер, коли це зроблено... Я не знаю, що робити з собою. Останнім часом я був так зайнятий нашою місією, що не зупинявся, щоб подумати про те, що буде потім. Думаю, поки що мені потрібен час для роздумів. Поки що я задоволений продовженням наших спільних пригод, якщо ви мене згодні. Я багато чого навчився, але все ще думаю, що мені є чого навчитися у вас.", ["en"] = "Finish the Fight", ["tasks"] = { ["Modified Shadow Scalpel"] = "Модифікований тіньовий скальпель" } },
    [84147] = { [1] = "Серйозна пропозиція", [2] = "Раді знайомству, {клас}. У мене є дещо, що може вас зацікавити.\n\nУ мене є комплект обладунків, дуже схожий на той, що носять представники вашої професії, але набагато вищої якості. Я готовий обміняти браслети на звичайні в обмін на невелику послугу.\n\nКров морозних мечів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз потрібні. Принесіть мені значний зразок разом із браслетами та невеликою кількістю золота. Ви переконаєтеся, що ваші зусилля варті ваших зусиль.", [3] = "Здобути 15 зразків крові Зимоключа та 20 золота і принести їх разом із набором наручів Дикого Серця Деліані в Залізогарті.", [4] = "Ти приніс мені те, що я тебе просив, {ім'я}?", [5] = "Чудово! Тоді давайте виконаємо обмін. Важко розлучатися з цими чудовими обладунками, але боюся, що вони мені скоро не знадобляться.\n\nЯкщо ви зацікавлені виконати для мене більше роботи, я можу бути готовий віддати решту частин.", ["en"] = "An Earnest Proposition" },
    [84148] = { [1] = "Серйозна пропозиція", [2] = "Раді знайомству, {клас}. У мене є дещо, що може вас зацікавити.\n\nУ мене є комплект обладунків, дуже схожий на той, що носять представники вашої професії, але набагато вищої якості. Я готовий обміняти браслети на звичайні в обмін на невелику послугу.\n\nКров морозних мечів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз потрібні. Принесіть мені значний зразок разом із браслетами та невеликою кількістю золота. Ви переконаєтеся, що ваші зусилля варті ваших зусиль.", [3] = "Здобути 15 зразків крові Зимоключа та 20 золота і принести їх разом із набором пут Ловця Звірів Деліані в Залізогарті.", [4] = "Ти приніс мені те, що я тебе просив, {ім'я}?", [5] = "Чудово! Тоді давайте виконаємо обмін. Важко розлучатися з цими чудовими обладунками, але боюся, що вони мені скоро не знадобляться.\n\nЯкщо ви зацікавлені виконати для мене більше роботи, я можу бути готовий віддати решту частин.", ["en"] = "An Earnest Proposition" },
    [84149] = { [1] = "Серйозна пропозиція", [2] = "Раді знайомству, {клас}. У мене є дещо, що може вас зацікавити.\n\nУ мене є комплект обладунків, дуже схожий на той, що носять представники вашої професії, але набагато вищої якості. Я готовий обміняти браслети на звичайні в обмін на невелику послугу.\n\nКров морозних мечів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз потрібні. Принесіть мені значний зразок разом із браслетами та невеликою кількістю золота. Ви переконаєтеся, що ваші зусилля варті ваших зусиль.", [3] = "Здобути 15 зразків крові Зимоключа та 20 золота і принести їх разом із набором пут Магістра Деліані в Залізогарті.", [4] = "Ти приніс мені те, що я тебе просив, {ім'я}?", [5] = "Чудово! Тоді давайте виконаємо обмін. Важко розлучатися з цими чудовими обладунками, але боюся, що вони мені скоро не знадобляться.\n\nЯкщо ви зацікавлені виконати для мене більше роботи, я можу бути готовий віддати решту частин.", ["en"] = "An Earnest Proposition" },
    [84150] = { [1] = "Серйозна пропозиція", [2] = "Раді знайомству, {клас}. У мене є дещо, що може вас зацікавити.\n\nУ мене є комплект обладунків, дуже схожий на той, що носять представники вашої професії, але набагато вищої якості. Я готовий обміняти браслети на звичайні в обмін на невелику послугу.\n\nКров морозних мечів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз потрібні. Принесіть мені значний зразок разом із браслетами та невеликою кількістю золота. Ви переконаєтеся, що ваші зусилля варті ваших зусиль.", [3] = "Здобути 15 зразків крові Зимоключа та 20 золота і принести їх разом із набором браслетів Світлогорна Деліані в Залізогарті.", [4] = "Ти приніс мені те, що я тебе просив, {ім'я}?", [5] = "Чудово! Тоді давайте виконаємо обмін. Важко розлучатися з цими чудовими обладунками, але боюся, що вони мені скоро не знадобляться.\n\nЯкщо ви зацікавлені виконати для мене більше роботи, я можу бути готовий віддати решту частин.", ["en"] = "An Earnest Proposition" },
    [84151] = { [1] = "Серйозна пропозиція", [2] = "Раді знайомству, {клас}. У мене є дещо, що може вас зацікавити.\n\nУ мене є комплект обладунків, дуже схожий на той, що носять представники вашої професії, але набагато вищої якості. Я готовий обміняти браслети на звичайні в обмін на невелику послугу.\n\nКров морозних мечів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз потрібні. Принесіть мені значний зразок разом із браслетами та невеликою кількістю золота. Ви переконаєтеся, що ваші зусилля варті ваших зусиль.", [3] = "Здобути 15 зразків крові Зимоключа та 20 золота і принести їх разом з 1 комплектом наручів побожності Деліані в Залізогарті.", [4] = "Ти приніс мені те, що я тебе просив, {ім'я}?", [5] = "Чудово! Тоді давайте виконаємо обмін. Важко розлучатися з цими чудовими обладунками, але боюся, що вони мені скоро не знадобляться.\n\nЯкщо ви зацікавлені виконати для мене більше роботи, я можу бути готовий віддати решту частин.", ["en"] = "An Earnest Proposition" },
