    [84154] = { [1] = "Серйозна пропозиція", [2] = "Раді знайомству, {клас}. У мене є дещо, що може вас зацікавити.\n\nУ мене є комплект обладунків, дуже схожий на той, що носять представники вашої професії, але набагато вищої якості. Я готовий обміняти браслети на звичайні в обмін на невелику послугу.\n\nКров морозних мечів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз потрібні. Принесіть мені значний зразок разом із браслетами та невеликою кількістю золота. Ви переконаєтеся, що ваші зусилля варті ваших зусиль.", [3] = "Здобути 15 зразків крові Зимоключа та 20 золота і принести їх разом із набором Наручів Доблесті Деліані в Залізогарті.", [4] = "Ти приніс мені те, що я тебе просив, {ім'я}?", [5] = "Чудово! Тоді давайте виконаємо обмін. Важко розлучатися з цими чудовими обладунками, але боюся, що вони мені скоро не знадобляться.\n\nЯкщо ви зацікавлені виконати для мене більше роботи, я можу бути готовий віддати решту частин.", ["en"] = "An Earnest Proposition" },
    [84163] = { [1] = "Гідна винагорода", [2] = "Ти дотримав слова та приніс пристрій, створений Муксом. Гадаю, винагорода потрібна, якщо я хочу, щоб ти продовжував цікавитися порятунком моєї шкіри. Принеси мені пояс і комплект рукавичок, які ти хочеш покращити. Обіцяю, що ті, що я тобі дам натомість, будуть набагато кращими.", [3] = "Принеси пояс Дикого Серця та комплект рукавичок Дикого Серця Деліані в Залізогарті.", [4] = "Ви готові здійснити торгівлю?", [5] = "Ти виконав свою частину угоди, я свою дотримаюся.\n\nПросто пам'ятай, що я зберігаю найкращі роботи, поки ти не закінчиш свою роботу.", ["en"] = "Just Compensation" },
    [84164] = { [1] = "Гідна винагорода", [2] = "Ти дотримав слова та приніс пристрій, створений Муксом. Гадаю, винагорода потрібна, якщо я хочу, щоб ти продовжував цікавитися порятунком моєї шкіри. Принеси мені звичайний ремінь та комплект рукавичок, які ти хочеш покращити.", [3] = "Принесіть Деліані в Залізогарті пояс Звіроловця та комплект Рукавиць Звіроловця.", [4] = "Ви готові здійснити торгівлю?", [5] = "Ти виконав свою частину угоди, я свою дотримаюся.\n\nПросто пам'ятай, що я зберігаю найкращі роботи, поки ти не закінчиш свою роботу.", ["en"] = "Just Compensation" },
    [84165] = { [1] = "Гідна винагорода", [2] = "Ти дотримав слова та приніс пристрій, створений Муксом. Гадаю, винагорода потрібна, якщо я хочу, щоб ти продовжував цікавитися порятунком моєї шкіри. Принеси мені звичайний ремінь та комплект рукавичок, які ти хочеш покращити.", [3] = "Принесіть Деліані в Залізогарт пояс Магістра та комплект рукавичок Магістра.", [4] = "Ви готові здійснити торгівлю?", [5] = "Ти виконав свою частину угоди, я свою дотримаюся.\n\nПросто пам'ятай, що я зберігаю найкращі роботи, поки ти не закінчиш свою роботу.", ["en"] = "Just Compensation" },
    [84166] = { [1] = "Гідна винагорода", [2] = "Ти дотримав слова та приніс пристрій, створений Муксом. Гадаю, винагорода потрібна, якщо я хочу, щоб ти продовжував цікавитися порятунком моєї шкіри. Принеси мені пояс і комплект рукавиць, які ти хочеш покращити. Обіцяю, що ті, що я тобі дам натомість, будуть набагато кращими.", [3] = "Принесіть Деліані в Залізогарті пояс Світлогорна та комплект рукавиць Світлогорна.", [4] = "Ви готові здійснити торгівлю?", [5] = "Ти виконав свою частину угоди, я свою дотримаюся.\n\nПросто пам'ятай, що я зберігаю найкращі роботи, поки ти не закінчиш свою роботу.", ["en"] = "Just Compensation" },
    [84167] = { [1] = "Гідна винагорода", [2] = "Ти дотримав слова та приніс пристрій, створений Муксом. Гадаю, винагорода потрібна, якщо я хочу, щоб ти продовжував цікавитися порятунком моєї шкіри. Принеси мені пояс і комплект рукавичок, які ти хочеш покращити. Обіцяю, що ті, що я тобі дам натомість, будуть набагато кращими.", [3] = "Принесіть Деліані в Залізогарт Пояс Побожності та комплект Рукавиць Побожності.", [4] = "Ви готові здійснити торгівлю?", [5] = "Ти виконав свою частину угоди, я свою дотримаюся.\n\nПросто пам'ятай, що я зберігаю найкращі роботи, поки ти не закінчиш свою роботу.", ["en"] = "Just Compensation" },
    [84168] = { [1] = "Гідна винагорода", [2] = "Ти дотримав слова та приніс пристрій, створений Муксом. Гадаю, винагорода потрібна, якщо я хочу, щоб ти продовжував цікавитися порятунком моєї шкіри. Принеси мені пояс і комплект рукавичок, які ти хочеш покращити. Обіцяю, що ті, що я тобі дам натомість, будуть набагато кращими.", [3] = "Принесіть Деліані в Залізогарт пояс Тіньової Ремесла та комплект Рукавиць Тіньової Ремесла.", [4] = "Ви готові здійснити торгівлю?", [5] = "Ти виконав свою частину угоди, я свою дотримаюся.\n\nПросто пам'ятай, що я зберігаю найкращі роботи, поки ти не закінчиш свою роботу.", ["en"] = "Just Compensation" },
    [84169] = { [1] = "Гідна винагорода", [2] = "Ти дотримав слова та приніс пристрій, створений Муксом. Гадаю, винагорода потрібна, якщо я хочу, щоб ти продовжував цікавитися порятунком моєї шкіри. Принеси мені пояс і комплект рукавичок, які ти хочеш покращити. Обіцяю, що ті, що я тобі дам натомість, будуть набагато кращими.", [3] = "Принесіть Деліані в Залізогарт пояс Жахливого Туману та набір обгорток Жахливого Туману.", [4] = "Ви готові здійснити торгівлю?", [5] = "Ти виконав свою частину угоди, я свою дотримаюся.\n\nПросто пам'ятай, що я зберігаю найкращі роботи, поки ти не закінчиш свою роботу.", ["en"] = "Just Compensation" },
    [84170] = { [1] = "Гідна винагорода", [2] = "Ти дотримав слова та приніс пристрій, створений Муксом. Гадаю, винагорода потрібна, якщо я хочу, щоб ти продовжував цікавитися порятунком моєї шкіри. Принеси мені пояс і комплект рукавиць, які ти хочеш покращити. Обіцяю, що ті, що я тобі дам натомість, будуть набагато кращими.", [3] = "Принесіть Пояс Доблесті та набір Рукавиць Доблесті Деліані в Залізогарті.", [4] = "Ви готові здійснити торгівлю?", [5] = "Ти виконав свою частину угоди, я свою дотримаюся.\n\nПросто пам'ятай, що я зберігаю найкращі роботи, поки ти не закінчиш свою роботу.", ["en"] = "Just Compensation" },
    [84179] = { [1] = "Прощальні слова Антіона", [2] = "Душа Валталака зберігалася в цьому амулеті. У своїй жадібності ми нерозумно розділили її на три частини, не знаючи прокляття, яке нас чекатиме.\n\nЄдиний спосіб зупинити чари Валталака — це зібрати медальйон назад. Поверніться до Деліани та скажіть їй, що Бодлі — її єдина надія знайти решту частин. Поговоріть з нею про будь-які нагороди, які ви домовилися.\n\nЯ, нарешті, спочиватиму з миром. Бажаю вам удачі; тобі знадобиться кожна її частинка!", [3] = "Поверніться до Деліани в Залізогарт з комплектом Чоботи Дикого Серця, Кілтом Дикого Серця та Наплечами Дикого Серця.\n\nНаданий предмет:", [4] = "Ти повернувся, {ім'я}. Ти мусиш розповісти мені все, що ти дізнався. Але спочатку давай ми організуємо твою винагороду.", [5] = "Не можу повірити, що наші життя майже повністю втрачені через якийсь дурний медальйон! І ти впевнений, що Антіон згадував Бодлі?\n\nЩо ж, ти виконав свою роботу, тож давай приберемо твою нагороду.", ["en"] = "Anthion's Parting Words" },
    [84180] = { [1] = "Прощальні слова Антіона", [2] = "Душа Валталака зберігалася в цьому амулеті. У своїй жадібності ми нерозумно розділили її на три частини, не знаючи прокляття, яке нас чекатиме.\n\nЄдиний спосіб зупинити чари Валталака — це зібрати медальйон назад. Поверніться до Деліани та скажіть їй, що Бодлі — її єдина надія знайти решту частин. Поговоріть з нею про будь-які нагороди, які ви домовилися.\n\nЯ, нарешті, спочиватиму з миром. Бажаю вам удачі; тобі знадобиться кожна її частинка!", [3] = "Поверніться до Деліани в Залізогарт з комплектом Чоботи Звіролова, Штани Звіролова та Мантія Звіролова.\n\nНаданий предмет:", [4] = "Ти повернувся, {ім'я}. Ти мусиш розповісти мені все, що ти дізнався. Але спочатку давай ми організуємо твою винагороду.", [5] = "Не можу повірити, що наші життя майже повністю втрачені через якийсь дурний медальйон! І ти впевнений, що Антіон згадував Бодлі?\n\nЩо ж, ти виконав свою роботу, тож давай приберемо твою нагороду.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Top Piece of Lord Valthalak's Amulet"] = "верхня частина амулету лорда Вальталака" } },
