    [84199] = { [1] = "Найкраще — наостанок", [2] = "Це чудова історія, {ім'я}! Щиро дякую тобі, і щиро вдячний усім, хто був до цього причетний. Можливо, тепер я зможу спати вночі із заплющеними очима.\n\nЩодо твоєї винагороди, то, гадаю, у мене є кілька речей, які тобі справді сподобаються.", [3] = "Дай Деліані свою побожну корону та побожну мантію.", [4] = "Згідно з нашою угодою, чи готові ви віддати свої Побожні Реліквії в обмін на вашу нову Чеснотливу Корону та Мантію?", [5] = "Я сумуватиму за тобою, {ім'я}. Я так тобі вдячний, що, гадаю, ніколи не зможу його повернути.\n\nСподіваюся, тобі сподобається твій новий головний та нагрудний бронежилет, і що він захищатиме тебе ще довго.", ["en"] = "Saving the Best for Last" },
    [84200] = { [1] = "Найкраще — наостанок", [2] = "Це чудова історія, {ім'я}! Щиро дякую тобі, і щиро вдячний усім, хто був до цього причетний. Можливо, тепер я зможу спати вночі із заплющеними очима.\n\nЩодо твоєї винагороди, то, гадаю, у мене є кілька речей, які тобі справді сподобаються.", [3] = "Дай Деліані твою Шапку Тіньової Ремесла та Туніку Тіньової Ремесла.", [4] = "Згідно з нашою угодою, чи готові ви віддати свої предмети Тіньового Ремесла в обмін на вашу нову Темну Мантію та Туніку?", [5] = "Я сумуватиму за тобою, {ім'я}. Я так тобі вдячний, що, гадаю, ніколи не зможу його повернути.\n\nСподіваюся, тобі сподобається твій новий головний та нагрудний бронежилет, і що він захищатиме тебе ще довго.", ["en"] = "Saving the Best for Last" },
    [84201] = { [1] = "Найкраще — наостанок", [2] = "Це чудова історія, {ім'я}! Щиро дякую тобі, і щиро вдячний усім, хто був до цього причетний. Можливо, тепер я зможу спати вночі із заплющеними очима.\n\nЩодо твоєї винагороди, то, гадаю, у мене є кілька речей, які тобі справді сподобаються.", [3] = "Дайте Деліані вашу Маску Жахливого Туману та Мантію Жахливого Туману.", [4] = "Згідно з нашою угодою, чи готові ви віддати свої фігурки Жахливого Туману в обмін на вашу нову Маску та Мантію Смертельного Туману?", [5] = "Я сумуватиму за тобою, {ім'я}. Я так тобі вдячний, що, гадаю, ніколи не зможу його повернути.\n\nСподіваюся, тобі сподобається твій новий головний та нагрудний бронежилет, і що він захищатиме тебе ще довго.", ["en"] = "Saving the Best for Last" },
    [84202] = { [1] = "Найкраще — наостанок", [2] = "Це чудова історія, {ім'я}! Щиро дякую тобі, і щиро вдячний усім, хто був до цього причетний. Можливо, тепер я зможу спати вночі із заплющеними очима.\n\nЩодо твоєї винагороди, то, гадаю, у мене є кілька речей, які тобі справді сподобаються.", [3] = "Дайте Деліані ваш Шолом Доблесті та Нагрудник Доблесті.", [4] = "Згідно з нашою угодою, чи готові ви віддати свої фігурки Доблесті в обмін на ваш новий Шолом та Нагрудник Героїзму?", [5] = "Я сумуватиму за тобою, {ім'я}. Я так тобі вдячний, що, гадаю, ніколи не зможу його повернути.\n\nСподіваюся, тобі сподобається твій новий головний та нагрудний бронежилет, і що він захищатиме тебе ще довго.", ["en"] = "Saving the Best for Last" },
    [84318] = { [1] = "Ой!", [2] = "Гей! {клас}! Так, так! Ти мені добре послужив, розтрощивши той гнітючий м'ясний костюм, у якому я катався всі ці роки, але я не відчуваю особливого потягу рухатися далі. Гадаю, це тому, що мені потрібно зробити якісь \"незавершені справи\", перш ніж я зможу вирушити. Що ж, тупоголовий, тебе щойно призвали на допомогу!\n\nМені потрібно, щоб ти приніс мені молот. Має бути десь на Перехресті Корріна, і його буде важко не помітити.\n\nГей, візьми і це. Це мій улюблений золотий зуб. Потріть його, коли знайдете мою зброю.", [3] = "Знайдіть зниклий молот Ортаса на Перехресті Корріна.\n\nНаданий предмет:", [4] = "Чого ж хотіти?", [5] = "Так, я тобі дуже вдячний! Тепер, коли ми з цим розібралися, давайте попрацюємо над тим, щоб зібрати решту, щоб ти міг мене відправити!", ["en"] = "Oi!", ["tasks"] = { ["Orthas' Favorite Gold Tooth"] = "Улюблений золотий зуб Ортаса" } },
    [84319] = { [1] = "О ні, не треба!", [2] = "Чудова робота з молотом, {клас}. Далі моя броня. Мені точно потрібна вона, щоб рухатися у великий світ.\n\nЄдина проблема в тому, що вона знаходиться, хм... у нутрощах одного з цих виродків. Я знаю, знаю, це забагато вимагає, але ти ж маєш зрозуміти, що колись я був могутнім таном під горою. Я просто не можу рухатися далі, знаючи, що родова броня мого клану розчиняється в кишковому соку гігантської гниючої гори м'яса!", [3] = "Ортасу потрібно, щоб ви повернули його втрачені обладунки з трупа Гидоти десь у Чумному Лісі.", [4] = "Чого ж хотіти?", [5] = "О, це чудово! Трохи гірше зношено, але цього буде достатньо. Нам залишилося ще одне, що потрібно зробити. Мені потрібен невеликий ритуал. Просто щось, що збере мій розгублений дух докупи і відправить мене в дорогу. Ця остання частина може бути трохи неприємною для тебе, враховуючи, що ти {клас} та все таке, але повір мені, це потрібно зробити!\n\nПринаймні, це, мабуть, не буде більш неприємним, ніж шукати свої штани в мерзенному супі! Гва-ха-ха!", ["en"] = "Oh No Ye Don't!" },
    [84320] = { [1] = "Втрачена реліквія", [2] = "Я прибув до Штормовія як біженець, рятуючись від спустошення, яке принесла Лордерону Скота. Я дякую Світлу, що моя родина та я врятувалися, але деякі з наших цінних реліквій досі залишаються в Чумних землях.\n\nЯкщо ви зможете повернути ці реліквії з їхнього місця спочинку в крипті Пагорба Скорботи, щоб я міг безпечно поховати їх у катакомбах Собору, я буду вашим боржником.", [3] = "Заберіть сімейні реліквії з крипти Пагорба Скорботи у Західних Чумних землях, а потім поверніться до Верховної Жриці Лорени в Соборі Штормовія.", [4] = "Ти повернувся з Чумних земель?", [5] = "Дякую, {ім'я}. Ви кажете, що знайшли журнал?", ["en"] = "Lost Heirloom" },
    [84321] = { [1] = "Реліквія Світла", [2] = "Мене зацікавив артефакт, згаданий у журналі, який ви знайшли. Можливо, це те, що нам потрібно, щоб змінити хід битви проти Скотланд-Бечу.\n\nБільшість збережених записів з Андоралу знаходяться під захистом Багряного Хрестового Походу в Хартглені. Перегляньте їх і подивіться, чи зможете ви знайти більше інформації.", [3] = "Вирушайте до Долини Підземного Вогнища у Західних Чумних Землях та знайдіть інформацію про артефакт, описаний у журналі.", [5] = "Цей реєстр, схоже, містить записи про діяльність Скарлет у Чумних землях.", ["en"] = "Relic of Light" },
    [84323] = { [1] = "Приз всередині", [2] = "Зсередини скриньки випромінюється сила. Це, мабуть, той артефакт! Тепер тобі просто потрібно його відкрити...", [3] = "Знайдіть спосіб відкрити скриньку та забрати артефакт, а потім доставте його Верховній жриці Лорені в Штормовійському соборі.\n\nНаданий предмет:", [4] = "Що ти знайшов, {ім'я}?", [5] = "Отже, історія була правдивою... Я збережу це та досліджу його потенціал. Це може бути захистом від Попелу, який нам потрібен.\n\nПрийміть це, {ім'я}, з моєю подякою.", ["en"] = "The Prize Within", ["tasks"] = { ["Puzzle Box"] = "Коробка-головоломка" } },
    [84324] = { [1] = "Дипломатичні пропозиції", [2] = "{ім'я}, вивчаючи уламок світла, який ти приніс, я бачив видіння. Я бачу, як жерець Орди знаходить подібний уламок, і я бачу, як Альянс та Орда об'єднуються у хвилі світла.\n\nНа жаль, наші стосунки з Ордою продовжують погіршуватися.\n\nЯ пропоную скласти дипломатичний подарунок як жест доброї волі між вірами. Принеси мені ці припаси, і ми подивимося, чи зможемо ми розпочати діалог між нашими народами.", [3] = "Зберіть припаси та доставте їх Верховній жриці Лорені в Штормовійському соборі.", [4] = "У вас є необхідні матеріали?", [5] = "Я спробую знайти спосіб доставити це до Орґріммара.\n\nУ мене також є дещо для тебе — цей тотем забезпечить зцілення членам Орди, що знаходяться поблизу. Акти служіння можуть подолати прірву там, де слова підводять нас.", ["en"] = "Diplomatic Overtures", ["tasks"] = { ["Giant Egg"] = "гігантське яйце", ["Heavy Runecloth Bandage"] = "щільний рунічний бинт", ["Major Healing Potion"] = "величезне зілля лікування", ["Stratholme Holy Water"] = "стратгольмська свята вода" } },
    [84325] = { [1] = "Святиня співпраці", [2] = "Панель біля основи статуї висувається, відкриваючи шматок пергаменту та блискучий кристал, схожий на той, який ви знайшли в Руці Тіра.", [3] = "Доставте кристал Верховній жриці Лорені в Штормовійському соборі.", [4] = "У тебе є для мене новини?", [5] = "Ще один уламок світла! Де ти це знайшов, {ім'я}?\n\nЯ згоден з автором. Якщо уламки можна використовувати як зброю проти живих, так і проти нежиті, вони можуть ескалувати конфлікт між Альянсом та Ордою до жахливих масштабів.", ["en"] = "Shrine of Cooperation", ["tasks"] = { ["Shard of Light"] = "Уламок світла" } },
    [84326] = { [1] = "Дипломатське кільце", [2] = "Дипломатичний подарунок, який ви зібрали, дійшов до священика Відкинутих Дітріха Прейса, і я дискретно зв'язався з ним. Ми обидва погоджуємося, що цей пошук слід тримати серед вірних. Якщо осколки можна використовувати як зброю, краще, щоб вони не потрапляли до рук лідерів жодної з фракцій.\n\nМи розробили таємний спосіб ідентифікації для тих, хто шукає осколки. Принесіть мені матеріали для виготовлення кільця, яке міститиме шматочок одного з осколків.", [3] = "Віднесіть запитувані матеріали Верховній жриці Лорені в Штормовійському соборі.", [4] = "Вирізка з черепка готова, {ім'я}. У вас є інші матеріали?", [5] = "<За допомогою зручного швидкого заклинання Лорена трансмутує матеріали та камінь, вирізаючи кільце>\n\nНа жаль, це було найлегше.", ["en"] = "Diplomat Ring" },
    [84327] = { [1] = "Дипломатична місія", [2] = "Ваше наступне завдання буде досить складним, {ім'я}.\n\nВи повинні зв'язатися зі жерцем Орди, який шукає осколки. Ви впізнаєте одне одного за допомогою своїх перснів. Вони супроводять вас до Орґріммара, де вам потрібно буде поговорити з Дітріхом Прейсом.\n\nЯкщо ви зможете переконати жерців Орди в мирних намірах, у нас може бути шанс возз'єднати осколки.", [3] = "Зв'яжіться з жерцем Орди біля воріт Орґріммара та отримайте дипломатичний імунітет, використовуючи свої Дипломатичні кільця один на одного. Потім увійдіть до Орґріммара та поговоріть з Дітріхом Прейсом. Ви втратите дипломатичний імунітет, якщо відійдете занадто далеко від свого жерця-супроводжуючого або вступите в бій.", [5] = "Ти, мабуть, той {клас}, якого мені казали очікувати. Я не знаю, чи вважати тебе сміливим, чи дурним.", ["en"] = "A Diplomatic Mission" },
    [84328] = { [1] = "Ремонт осколка", [2] = "Я готовий повірити, що ви тут з доброю волею, {клас}.\n\nМи відкриті до зустрічі між нашими людьми. Але уламок світла, який ми маємо, у поганому стані. Ми повинні поповнити його, перш ніж намагатися об'єднатися з іншими.\n\nДревні Високородні того, що зараз є Забутим Молом, вміли маніпулювати таємною та священною енергією. Ідіть туди та знайдіть будь-яку інформацію, яку можете, про артефакти світла, а потім поверніться до мене.", [3] = "Заберіть книгу «Прикладна богослов'я» з Затхлого Молу, а потім поверніться до Дітріха Прейса в Орґріммар.\n\nЩоб потрапити до Орґріммара, вам знадобиться допомога жерця Орди з перснем дипломата, щоб отримати дипломатичний імунітет. Ви втратите дипломатичний імунітет, якщо надто відхилитеся від жерця, який вас супроводжує, або вступите в бій.", [4] = "Ви повернулися, {клас}?", [5] = "Це має допомогти відремонтувати уламок. Настав час покласти цьому край.", ["en"] = "Repairing the Shard" },
    [84330] = { [1] = "Трохи некромантії", [2] = "Отже, бачите, нам потрібно знайти відповідний труп гнома та провести з ним невеликий ритуал, щоб заземлити мій дух і відправити мене в дорогу! Все це цілком звичайні речі, звісно! Нам також знадобиться трохи Некротичного Рунічного Каменю від якогось некроманта, звісно. Чув, що один є в Стратголмі. Видається Малекі Блідий чи щось таке. Не думаю, що він охоче з ним розлучиться, але для цього є рішення!\n\nПринеси мені той камінь, а потім йди до підземелля. Там є труп, який підійде!", [3] = "Отримайте Некротичний Рунічний Камінь у Малекі Блідого у Стратгольмі, потім знайдіть Гниючий Труп Гнома біля Підземелля у південно-західних Східних Чумних Землях.", [4] = "...", [5] = "<Ти нахиляєшся, щоб доторкнутися до трупа, і волосся на потилиці стає дибки... у тебе погане передчуття з цього приводу>", ["en"] = "A Wee Bit O' Necromancy" },
    [84332] = { [1] = "Вдячність тана", [2] = "<Торкаючись маленької скрині, ти чуєш безтілесний голос у своїй голові>\n\nНе можу тобі достатньо подякувати, {ім'я}. Звісно, не так, як ти очікуєш! Просто щоб ти не надто розлютився, у мене є для тебе дещо, що мені більше не потрібно, але, гадаю, тобі може стати в пригоді.\n\nУдачі тобі, {ім'я}. Ах, і останнє... якби ти випадково побачив удалині гігантський плавучий некрополь, я б на твоєму місці повернув хвіст і втік. Ха!", [5] = "Ви знайдете маленький рунічний камінь на дні скрині...", ["en"] = "A Thane's Gratitude" },
    [84377] = { [1] = "Кінець Темної Орди", [2] = "Діло зроблено. Дал'ренд Чорнорукий, Вождь Темної Орди, лежить мертвим біля ваших ніг. Візьміть його голову та віддайте її Майстру Шоу.", [3] = "Віднесіть голову Ренда Чорнорукого майстру Матіасу Шоу в Штормовій.", [4] = "Клянусь Світлом!", [5] = "Молодець, чемпіоне. Вождь Темної Орди мертвий, що поклало край ері терору на наших землях. Повідом про твою перемогу весь Штормовій!", ["en"] = "End of the Dark Horde", ["tasks"] = { ["Head of Rend Blackhand"] = "голова Ренда Чорнорука" } },
    [84414] = { [1] = "Відправ мене в дорогу!", [2] = "<Ти чуєш безтілесний голос Ортаса у своїй свідомості>\n\n«Ось ми й приїхали. Давайте продовжимо, гаразд?»", [3] = "Спостерігайте за Ортасом, коли він покидає цей світ.", [5] = "У тебе немає слів, щоб описати те, що щойно сталося. Що ти накоїв?\n\nСподіваюся, у цій скрині є хоча б якась хороша здобич.", ["en"] = "Send Me On Me Way!" },
    [84418] = { [1] = "Зниклий лицар", [5] = "Нещодавно наш спільний друг звернувся до нас з проханням допомогти знайти зниклого лицаря на ім'я Далтон. Його та його молодого зброєносця востаннє бачили в Чумних землях, і про них давно нічого не чули. Якщо ваші подорожі заведуть вас туди, будь ласка, слідкуйте за ними.\n\nНебагато чого можна було б сказати, але у вас є хист опинятися в усіляких цікавих ситуаціях. Якщо хтось і може натрапити на зниклого лицаря та його цуценя зброєносця посеред цих пекельних Чумних земель, то це ви.", ["en"] = "The Missing Knight" },
    [84551] = { [1] = "Світло і як ним керувати", [2] = "Том носить клеймо Афінеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ви відновили фоліант!", [5] = "Чудова робота, {раса}. Якщо ви знайдете ще якісь томи, не вагайтеся повернути їх нам.\n\nЗ часом ми схильні змінюватися та навіть додавати нові винагороди за повернення відсутніх томів.", ["en"] = "The Light and How To Swing It", ["tasks"] = { ["Item #228690"] = "Товар №228690" } },
    [84555] = { [1] = "Довідник Ностро", [2] = "Ви відкрили щось надзвичайно важливе. Ця книга не схожа на жодну з тих, що ви бачили.\n\nСхоже, що комусь або чомусь вдалося зламати печатку Афінеума. Текст усередині спотворений і ледве читабельний.", [3] = "Поверніть «Збірник Ностро про вбивство драконів» до Афінеума.", [4] = "А, одна з наших найкращих збірок. Цього бракувало вже дуже давно.", [5] = "За цю книгу на чорному ринку можна було б отримати чимало золота, {ім'я}. Особливо враховуючи, що захисну печатку було зламано, залишаючи таємниці вбивства драконів доступними для будь-кого, хто має необхідний інтелект, щоб засвоїти знання, що містяться на священних сторінках.\n\nМожливо, на вас чекає велика нагорода... Ну, нагорода, для отримання якої знадобляться величезні зусилля.", ["en"] = "Nostro's Compendium", ["tasks"] = { ["Item #228680"] = "Товар №228680" } },
    [84560] = { [1] = "Святкування хороших часів", [2] = "Знайдіть майора Меттінглі в Долині Героїв, {ім'я}. Він чекатиме на вас...", [3] = "Знайдіть майора Меттінглі в Долині Героїв.", [5] = "Мало хто удостоївся такої церемонії, {ім'я}. Будь ласка, оберіть свою нагороду, щоб ми могли розпочати святкування.", ["en"] = "Celebrating Good Times" },
    [8484] = { [1] = "Посередник миру", [2] = "Твої подвиги вищі за будь-які похвали, {ім'я}. Якщо ти представляєш свій народ, то ми хотіли б укласти з ним мир.\n\nБудь ласка, віднеси цей дар до короля дворфів, що мешкає в Залізних Горах. Гадаю, ви називаєте це місто Залізогарт. У минулому він намагався укласти з нами союз від імені Альянсу. Тож тепер цілком доречно довірити тобі завершити цю справу.", [3] = "Віднесіть дар Деревопузих королю Маґні Бронзобородому в Залізогарт.", [4] = "{Клас:к}, ласкаво просимо до моїх володінь. Залізогарт завжди буде домом для таких героїв, як ти. А тепер, які справи привели тебе до мене?", [5] = "Це справді вдалий поворот подій. Якщо ми матимемо стійкий мир з цими істотами, це, безумовно, дасть нам перевагу у забезпеченні безпеки Калімдору від зовнішніх загроз... З чим нічні ельфи не впораються самотужки. Я повідомлю про це інших лідерів Альянсу, і ми відправимо більше дипломатів!\n\nЩодо тебе, {ім'я}... ти {стать:проявив:проявила} мужність як у дипломатії, так і у своїх діяннях. Я і весь Альянс вдячні тобі.", ["en"] = "The Brokering of Peace", ["tasks"] = { ["42000 reputation with Timbermaw Hold"] = "42000 репутації у фортеці Тимбермау", ["Timbermaw Offering of Peace"] = "дар Деревопузих", ["Timbermaw Offering of Peace (Provided)"] = "дар Деревопузих (видано)" } },
    [85] = { [1] = "Загублене намисто", [2] = "Я не можу знайти своє намисто і думаю, що його поцупив той безхатько Біллі! Він без перестанку рискає, немов щур, навколо виноградників Маклура, що на сході.\n\nПоверни моє намисто, потіш серце старої вдови.", [3] = "Поговоріть з Біллі Маклуром.", [5] = "Загубилося що?! Ну, я не брав ніякого намиста, бо я не злодій!\n\nПроте можу знати, хто це зробив, але... <усміхається>... Я занадто голодний, щоб згадати.", ["en"] = "Lost Necklace" },
    [85034] = { [1] = "Руїни Андоралу", [2] = "Останки, подібні до тієї, що ви носите, зазвичай мають таємничі властивості. Деякі особливо потужні реліквії можуть навіть здаватися розумними або часом мати індивідуальність, особливо поблизу людей та місць, тісно пов'язаних з їхніми живими істотами.\n\nЯкщо це справді кров Утера, є ймовірність, що вона може відреагувати, коли буде поблизу місця, де Утер помер. Дослідіть місто та подивіться, що станеться.", [3] = "Візьміть Кров Світлоносця та дослідіть Андорал.", [4] = "Ви вже досліджували Андорал? Кров якось відреагувала?", [5] = "Тож немає сумнівів, кров справжня. Те, що у вас є, — це скарб, {клас}. Бережіть його та захищайте своїм життям.", ["en"] = "The Ruins of Andorhal" },
    [85063] = { [1] = "Кульмінація", [2] = "Як тільки ми почнемо ритуал, я не знаю, що станеться. Це місце кишить демонами, і якщо вони виявлять наш ритуал, нам, можливо, доведеться захищатися. Вам і Аді потрібно буде зосередитися на цьому, поки я накладатиму заклинання. Однак, будь ласка, тримайтеся поруч, оскільки ви самі є важливою частиною цієї магії.", [3] = "Захистіть Грегорі, поки він завершує ритуал знищення Сфери Відлуння Маннорока.", [4] = "Будьте напоготові, {клас}.", [5] = "Ні... ні. Цього не може бути! Ми були так близько!\n\nЯ провалив свою місію. Азгалот вивільнений. Нам потрібно перегрупуватися та спланувати наші наступні кроки.", ["en"] = "Culmination" },
    [85064] = { [1] = "Найгірший сценарій", [2] = "Час тепер проти нас. Володар жаху згадав про Каньйон Падіння Демонів, тож гарна новина полягає в тому, що ми знаємо, куди вони прямують. Погана новина полягає в тому, що ми, ймовірно, зміцнили зв'язок Азгалота з Азеротом нашим невдалим ритуалом. Навіть якщо ми вб'ємо Азгалота зараз, він незабаром знову проявиться.\n\nУ мене є ідея. Вона відчайдушна, але це може бути нашою єдиною надією. В Андоралі є хтось із дуже особливим набором навичок, хто може допомогти, але спочатку нам потрібно буде побудувати з нею довіру.", [3] = "Вирушайте до Андоралу та знайдіть Грегорі, щоб дізнатися, що робити далі.", [4] = "У тебе вийшло, молодець.", [5] = "Релікварій крові Утера був ключем до цього ритуалу, але, на жаль, він був втрачений під час атаки. Як я вже казав, ця магія полягає у побудові та розриві зв'язків. Якби ми могли знайти ще один зразок цієї крові, ми б використали його проти фізичної форми Азгалота та вбили його, щоб повністю вигнати його душу з Азероту.\n\nСкільки ви знаєте про бронзових драконів?", ["en"] = "Worst Case Scenario", ["tasks"] = { ["Empty Reliquary"] = "Порожній релікварій" } },
    [85065] = { [1] = "Найцікавіший гном", [2] = "Те, що нам потрібно для завершення цієї місії, існує прямо тут, в Андоралі, просто зараз його тут немає.\n\nУ кімнаті позаду мене знаходиться \"гном\" на ім'я Хромі. Вона досить цікава істота, яка, як відомо, використовує дуже особливий вид драконячої магії. Власне, магію часу.\n\nЯкби нам вдалося переконати її використати свою магію, щоб допомогти нам, ми могли б ненадовго пройти крізь час і отримати те, що нам потрібно. Це маневр, але це може бути нашим єдиним варіантом. Подивіться, чи зможете ви переконати її надати нам свою допомогу.", [3] = "Поговоріть з Хромі в Андоралі та переконайте її допомогти вам.", [5] = "Рада знову тебе бачити, {ім'я}! Принаймні, мені здається, що ми вже познайомилися. Ми ж познайомилися, чи не так? Важко встежити за всіма різними версіями кожної людини, яку я зустрів... або зустріну.", ["en"] = "A Most Curious Gnome" },
    [85066] = { [1] = "Підготовка", [2] = "Вторгнення демонів та ритуали смерті! Звучить дуже страшно. На щастя, ця зручна маленька бульбашка часу, в якій ми стоїмо, дозволяє легко зв'язати себе з певним моментом часу в цьому місці.\n\nОднак це буде небезпечно. Коли ви з другом будете готові, скажіть слово.", [3] = "Поговоріть з Грегорі в Андоралі та попросіть його супроводжувати вас на Спалення Андоралу.", [5] = "Це справді відбувається...\n\nЯк би мені не хотілося цього визнавати, я не думаю, що я найкраща людина, щоб повернутися з тобою. Моє тіло зазнало надто великої шкоди між священним вогнем Еонаса та атакою демона. У моєму нинішньому стані я радше сповільню тебе, ніж допоможу. Зі смертю Ади, гадаю, нам може знадобитися стороння допомога.", ["en"] = "Making Ready" },
    [85067] = { [1] = "Паладин Срібної Руки", [2] = "Я сказав, що не вірю в долю, але не знаю, чи це була зовсім правда. Мій погляд так сильно змінився з того часу, як закінчилося моє смертне життя, але чим довше я виконую цю місію, тим більше починаю бачити закономірності та зв'язки в речах. Гадаю, ти це вже знаєш, але саме Еонас має піти з тобою.\n\nПовір мені, коли я кажу, що я б хотів залишити свого старого друга в спокої, але це важливіше, ніж те, чого я хочу. Іди до гробниці Утера та поясни ситуацію.", [3] = "Піди до гробниці Утера та поясни ситуацію Еонасу.", [4] = "Це слабка надія, але спробувати варто. Якщо щось від Утера залишилося, ми ще можемо підсилити ритуал і використати його проти нашого ворога.", [5] = "<Грегорі киває тобі, а потім, у свою чергу, Еонасу>\n\nЧас. {ім'я} йди поговори з Хромі, коли будеш готовий.", ["en"] = "A Paladin of the Silver Hand" },
    [85068] = { [1] = "Хто сказав, що ти ніколи не зможеш повернутися назад?", [2] = "Портал готовий.\n\nЩойно ви увійдете, вас перенесе до Андоралу, одразу після його падіння. Щоб ви краще злилися з натовпом, я підготував для вас кілька магічних маскувань. Вони підійдуть для більшості мешканців минулого, але вам все одно слід бути обережними, щоб вас не помітили. Коли у вас буде все необхідне, просто поверніться до цього місця в минулому. Портал має чекати на вас.", [3] = "Пройдіть порталом до Палаючого Андоралу.", [5] = "Ми це зробили. Закріпи себе, {ім'я}.", ["en"] = "Who Says You Can Never Go Back?" },
    [8507] = { [1] = "Польова служба", [2] = "Вітаю, {ім'я}. Перш ніж ти отримаєш більш відповідальні завдання на війні, тобі потрібно виконати свою частину польового обов'язку.\n\nТи знайдеш капітана Чорнокова з бригада Залізогарта поблизу Вул'Зора.\n\nПоговори з ним або його лейтенанткою, Жанелою Дужомолот та повертайся до мене. Я підготую для тебе складніше завдання.\n\nІ, будь ласка, зроби послугу, тримайся якомога далі від Орґріммарського легіону. Ми змушені тримати ці два війська далеко одне від одного через ворожнечу між ними.", [3] = "Вступіть на службу до бригади Залізогарта поблизу Вул'Зори. Підготуйте свої непідписані документи про польову службу й отримайте підписані документи про польову службу у капітана Чорнокова, після чого поверніться до вітрозова Калдона в Кенарійську цитадель, що в Силітусі.\n\nПримітка: Якщо ви зцілите або накладете корисні заклинання на члена бригади Залізогарта, вас будуть вважати {стать:учасником:учасницею} PvP.", [4] = "Загін капітана Чорнокова розташований неподалік Вул'Зора. Якщо не зможеш його відшукати, звернись до лейтенантки Жанели Дужомолот.", [5] = "Дуже добре, {ім'я}. Я підготував набір завдань, які повною мірою використають твої навички.\n\nЗавдяки старанній роботі таких, як ти, ми швидко переможемо нашого ворога раз і назавжди!\n\nЯкщо тобі знадобляться нові завдання, повернися до капітана Чорнокова.", ["en"] = "Field Duty", ["tasks"] = { ["Signed Field Duty Papers"] = "підписані документи про польову службу", ["Signed Field Duty Papers (Provided)"] = "підписані документи про польову службу (видано)" } },
    [85074] = { [1] = "Спалення Андоралу", [2] = "Я не впевнений, що нас там чекає, але нічого доброго там не буде.\n\nНам потрібно потрапити всередину, знайти місце, де впав Утер, і спробувати зібрати кілька крапель його крові. Звідти нам потрібно повернутися до корчми на західній стороні міста та вдало втекти. Нам слід поспішити, але також потрібно підійти до цього з обережністю та повагою, як того заслуговує мій пан Утер. Думка про те, щоб потурбувати його там, де він упав, викликає у мене глибокий дискомфорт.\n\nДавай покінчимо з цим.", [4] = "Як би це не було неприємно, ми зробили те, для чого прийшли.", [5] = "Гадаю, нам не варто очікувати повернення маскувань, тому, гадаю, у нас немає іншого вибору, окрім як пробиватися звідти. Приготуйся, {ім'я}.", ["en"] = "The Burning of Andorhal" },
    [8508] = { [1] = "Документи про польову службу", [4] = "Я так розумію, ти хочеш, щоб я підписав ці документи, {стать:хлопче:дівчино}?", [5] = "Так, гадаю, ця невеличка сутичка в наші дні вважається польовою службою. Віднеси це назад в Кенарійську цитадель. Впевнений, там для тебе знайдеться легка робота.\n\nІди!", ["en"] = "Field Duty Papers", ["tasks"] = { ["Prepared Field Duty Papers"] = "підготовлені документи про польову службу", ["Prepared Field Duty Papers (Provided)"] = "підготовлені документи про польову службу (видано)" } },
    [85087] = { [1] = "Відчайдушна втеча", [2] = "Нежить прорвалася і заполонила західну частину міста. Це буде важкий бій, {ім'я}. Час зараз проти нас, тому нам слід уникати районів, найбільш вкритих лихом.\n\nО, я мало не забув, візьми це. Якщо ми якимось чином розлучимося, посигналь, і я повернуся до тебе.", [4] = "Це... нічого, просто подряпина. Мені просто потрібно зловити мою...", [5] = "<Еонас починає дрімати, перш ніж раптово розплющити очі та зустрітися з тобою поглядом.>", ["en"] = "A Desperate Escape", ["tasks"] = { ["Tarnished Horn"] = "Потьмянілий ріг" } },
    [85090] = { [1] = "Назад у майбутнє", [2] = "<Еонас здригається. Він тяжко поранений> Гадаю... це все, що я можу зробити, {ім'я}. Це... гаразд. Це... завжди те місце, де я мав бути. Я радий бути тут, з моїми друзями... в кінці.\n\nОсь, візьми це. Я створив це... щоб нагадувати собі. Щоб я ніколи не забуду друзів, яких втратив тут, і щоб я завжди залишався їм вірним. Я навіть так це назвав... Правдоносець.\n\nВіддай це Грегорі від мене. Можливо, це допоможе йому краще згадати, хто він. Гадаю, ти теж це бачиш... він... змінився.\n\nЯ...", [3] = "Поверніть портал у свій час і доставте Носія Істини Грегорі.", [4] = "Де Еонас? Що трапилося?", [5] = "Розкажи мені все.", ["en"] = "Back to the Future", ["tasks"] = { ["Truthbearer"] = "Носій правди" } },
    [85091] = { [1] = "Ціна перемоги", [2] = "Дякую... що принесли мені це. Клинок освячений, і мені буде важко ним володіти, але це здається невеликою жертвою для мого... мого друга.\n\nСкоро прийде пізніше. А зараз час покласти цьому край. Зберіть своїх найдовіреніших союзників і вирушайте до Каньйону Падіння Демонів. Азгалот може не одразу показати себе вам, але якщо ви кинете відповідний виклик, він відповість.\n\nВізьміть кров і використайте її, щоб освятити свою зброю та знищити його. Для Еонаса та для Ади час покласти цьому край.", [3] = "Освятіть свою зброю Кров'ю Світлоносця та переможіть Азгалота в Каньйоні Падіння Демонів.", [4] = "...", [5] = "Моя місія нарешті виконана.\n\nЦе так довго мене поглинало, що я навіть не замислювався над тим, що насправді означає ця перемога. Гадаю, це означає, що наш союз розірвано, і мені слід повертатися до Нортренда...\n\n<Між вами висить тривожна тиша>", ["en"] = "The Cost of Victory", ["tasks"] = { ["Blood of the Lightbringer"] = "Кров Світлоносця" } },
    [85092] = { [1] = "Носій правди", [2] = "Еонас зумів побачити це набагато раніше за мене. Він побачив, як я змінився під час цієї місії. Я справді відчуваю... смуток, жаль, знову любов. Смуток за Адою, жаль за мою зраду і любов до мого друга. Я не знаю точно, що це означає, але я знаю, що не можу повернутися до Нортренда.\n\nМожливо, Лордерон? Можливо, там є інші, як я. Ті, хто впав зі світла... і повільно знаходять до нього шлях назад. Можливо, я зможу допомогти їм, як мій друг допоміг мені.", [5] = "Той факт, що тримання Носія Істини більше не завдає мені болю, говорить мені все, що мені потрібно знати про шлях, яким я маю йти зараз.\n\nОднак, я думаю, що клинок має залишитися з тобою. Еонас зрозуміє, і я цілком впевнений, що він схвалить. Левова частка моїх бойових днів, ймовірно, позаду, і така зброя заслуговує на те, щоб служити світлу.\n\nДо побачення, {ім'я}. Нехай буде з тобою Світло.", ["en"] = "Truthbearer" },
    [85413] = { [1] = "Сутність вогню", ["en"] = "Essence of Fire" },
    [85455] = { [1] = "Кров Світлоносця", [2] = "Ваша рука злегка тремтить, коли ви тримаєте маленький флакончик з кров’ю. Окрім напису на етикетці, ви можете відчути тепло та енергію, що випромінюються від зразка. Чи може це справді бути кров легендарного героя, Утера Світлоносця? Вам слід знайти когось, хто може підтвердити справжність цього зразка.", [3] = "Знайдіть когось, хто може розповісти вам більше про Кров Світлоносця.\n\n(Зверніть увагу, що вам потрібно попередньо виконати завдання «Зустріч у Чумних землях», щоб мати змогу здати це завдання)", [4] = "Мир вам, {клас}.", [5] = "Зачекайте, що це у вас там?\n\n<Очі Верховного Жреця Тел'даніса широко розплющуються, коли він оглядає релікварій>\n\nНе може бути. Як чорні дракони могли б отримати зразок крові Лорда Утера?\n\nЯкщо це справжня реліквія, то вона стане реліквією надзвичайної важливості. Давайте поговоримо про це далі.", ["en"] = "The Blood of the Lightbringer", ["tasks"] = { ["Item #231452"] = "Товар №231452" } },
    [85457] = { [1] = "Саме те, що було потрібно", [2] = "Я вже бачу, що ти маєш намір принести кров Грегорі. Добре. Моє судження було в кращому випадку сумнівним, і це завжди була гра молодого паладина, в яку я просто грав.\n\nЯ досі не впевнений, що відчувати, але я, безумовно, радий бачити, що ти виріс у паладина, яким тобі завжди судилося бути.", [3] = "Віднесіть Кров Світлоносця Грегорі в Каер Дарроу, що у Західних Чумних землях.", [4] = "Так, {ім'я}?", [5] = "Я не очікував побачити тебе тут знову, принаймні не так скоро. Що таке?", ["en"] = "Just What Was Needed", ["tasks"] = { ["Blood of the Lightbringer"] = "Кров Світлоносця" } },
    [85458] = { [1] = "Ущелина Темного Шепіту", [2] = "Це... неймовірно. Я надто прагматичний, щоб вірити в долю, але це, безумовно, випадковий поворот подій. З огляду на це, я думаю, у нас є все необхідне, щоб завершити ритуал і знищити сферу назавжди. Як і в будь-якому хорошому ритуалі, місце розташування є ключовим. Ви знайомі з Ущелиною Темного Шепіту у Зимоключі? Це прокляте місце, де живуть демони, але саме туди ми повинні піти, щоб завершити це.\n\nЯ зберу сферу та решту матеріалів і зустрінуся з вами там. Кінець моєї місії вже близько!", [3] = "Зустріньтеся з Грегорі в ущелині Темного Шепіту, що в Зимоключі.", [4] = "Ви впоралися, молодець. Будьте напоготові, {ім'я}.", [5] = "Я знаю, що це було трохи віддалено, але нам потрібна була місцевість, де бар'єр між нашою реальністю та нижнім світом тонкий, з великою концентрацією прихованої таємничої енергії. Минулого разу ми обрали Фехтвуд через його близькість до гори Гіджал. Для цього ритуалу я не ризикуватиму і хотів підійти якомога ближче до сплячої Криниці Вічності.\n\nЯ вже можу сказати, що це ідеальне місце. Я майже відчуваю енергію в повітрі. Ходімо, почнемо.", ["en"] = "Darkwhisper Gorge", ["tasks"] = { ["Blood of the Lightbringer"] = "Кров Світлоносця" } },
    [85507] = { [1] = "Наш неслухняний друг", [2] = "Я радий, що ти тут, {ім'я}. Нам надійшла звістка, що біля табору Холодного вітру бачили мандрівника, який відповідає опису нашого друга Еонаса. Він прямував у напрямку Пагорба Скорботи.\n\nПісля того, що сталося у Фелдвуді, я хотів дати йому простір, але в ордені є ті, хто йому досі не довіряє, і в якийсь момент йому доведеться повернутися з холоду, щоб пояснити, чому він приховував свою тривалу співпрацю з відомим агентом Короля-Ліча. Іди та знайди його, подивися, чи зможеш ти переконати його прийти.", [3] = "Знайдіть Еонаса поблизу Пагорба Скорботи у Західних Чумних Землях.", [4] = "Тобі слід швидше повернути нам Еонаса. Чим довше він чекатиме, щоб прийти та пояснити свою позицію, тим гірше все це виглядатиме.", [5] = "У мене було відчуття, що ти рано чи пізно з'явишся. Вибач, що розчаровую тебе, але мені ще не час повертатися. Це найкраще в тому, щоб бути \"колишнім\" членом Срібної руки; я більше ні перед ким в ордені не звітую.\n\nКолись я повернуся, але поки що, будь ласка, скажи Кетрін, що я підтвердив її прохання, але ще не готовий.", ["en"] = "Our Wayward Friend" },
    [85508] = { [1] = "Наш неслухняний друг", [2] = "Здається, ти стала сильнішою з нашої останньої зустрічі. Я дуже рада. Якщо я щось і зробила правильно у своєму житті, то це врятувала твоє життя у Фелвуді, і це мене втішає.\n\nУ будь-якому разі, краще тобі повертатися до Кетрін, хіба що тобі потрібно було ще щось мене запитати?", [3] = "Перш ніж повернутися до Штормовія, поговоріть з Еонасом, щоб повідомити Кетрін його відповідь.", [5] = "{ім'я} дякую світлу, що ти тут! Сховище щойно пограбували, і вкрали Сферу Відлуння Маннорока!", ["en"] = "Our Wayward Friend" },
    [85509] = { [1] = "Велике викрадення лункої сфери", [2] = "Будь ласка, пройдіть до південно-східної частини каналів і поговоріть там із Хранителем Сховища, Жульєном Фараністером. Він може розповісти вам усе, що знає. Дізнайтеся все, що можете, про злочин. Було багато людей, які хотіли б вкрасти цю сферу, тому зібрати якомога більше інформації, поки місце злочину свіже, є життєво важливим.", [3] = "Поговоріть із Хранителем Сховища Фараністером у Канальному районі Штормовія та поверніться до Катерини, коли навчитеся всього, що можете.", [5] = "Це небагато, з чого можна було б почати, але, мабуть, краще, ніж нічого.\n\nМені цікаво почути, що ви дізналися на зустрічі з Еонасом, але, боюся, це питання зараз є пріоритетним. Давайте поговоримо про нашу поточну перевагу.", ["en"] = "Grand Theft Echoing Orb" },
    [85510] = { [1] = "Надійний лід", [2] = "Це, безсумнівно, медальйон з палаючою лопаткою, що свідчить про причетність до культу легіону. Що ж до того, з чого почати, ви можете спробувати вирушити до таверн у місті та спробувати отримати інформацію від деяких менш привабливих людей.\n\nЦе небагато, але це початок.", [3] = "Дослідіть деякі з найсумнівніших частин Штормовія, щоб дізнатися, хто, можливо, планував пограбувати сховище.", [5] = "Ти виглядаєш так, ніби щойно щось загубив...\n\nЯ підозрював, що рано чи пізно ти опинишся тут, шукаючи це. Треба віддати тобі належне, ти встиг швидше, ніж я очікував.", ["en"] = "A Solid Lead" },
    [85511] = { [1] = "Зустріч у Чумних землях", [2] = "Звісно, я очікував, що ти знайдеш мене тут. Як ти думаєш, чому я залишив трупи тих культистів, щоб ти їх знайшов у тому сховищі?\n\nПерш ніж ти надто хвилюватимешся; так, сфера безпечна. Безпечніша, ніж це місто, очевидно. Якби я зайшов у сховище лише за кілька хвилин, сфера давно б зникла.\n\nЯ вже сказав достатньо, і ця таверна має вуха. Знайди мене на острові Каер Дарроу у Західних Чумних землях. Ти отримаєш відповіді, коли прибудеш.", [3] = "Знайдіть Аду Даркхардт у Каер Дарроу, що у Західних Чумних землях.", [4] = "Давайте поговоримо, {ім'я}.", [5] = "Я відчуваю, що кінець близько. Сподіваюся, ми зможемо знайти відповідну заміну твоїй крові та покінчити з цією справою раз і назавжди.\n\nУ будь-якому разі, ти пройшов весь цей шлях з чесною волею і не намагався мене вбити, тому я ціную це. Ось, прийми це як знак моєї вдячності. Це небагато, але це добре послужило мені... в іншому житті. Сподіваюся, це стане в пригоді і тобі.", ["en"] = "Plaguelands Rendezvous" },
    [85601] = { [1] = "Сигіла синкретиста", [4] = "Занза може створювати стародавні чари тролів за допомогою правильних компонентів.\n\nПерше — це первісний ідол Хаккарі, якого потрібно взяти у наймогутніших лейтенантів Хаккарі: Джін'до та Кривавого Володаря.\n\nДруге — це проколота лялька вуду. Її можна знайти в купах сміття, що засмічують це гидке місце. Зазирни всередину куп проклятих вуду.\n\nПринеси мені ці речі, і я створю для тебе потужні чари!", [5] = "Використовуй це добре, {клас}. Не проявляй милосердя до Хаккарі!", ["en"] = "Syncretist's Sigil" },
    [85617] = { [1] = "Тавро героя", [4] = "Король визнав твоє існування, {клас}. Ти перший у своєму роді, кого Растахан прийняв як справжнього союзника Зандалару.\n\nТи будеш щедро винагороджений за свої зусилля. Представ свій знак, і я застосую остаточне посилення.", [5] = "Пильність, честь, вірність, хоробрість... Ви втілюєте всі ці риси, і таким буде ваш бренд.", ["en"] = "The Hero's Brand" },
    [85618] = { [1] = "Взірці могутності: нарукавники вільнодумця", [2] = "Ти — язичник. Язичники мають місце в племені. Язичники — вільнодумці Зандалару. Вільнодумці не бояться гноблення. Вільнодумці гинуть за те, у що вірять. Ми знаємо, що ти помреш за те, у що віриш. Це заслуговує на наше визнання. Це дає тобі шанс довести свою спроможність ще більше.\n\nМи повинні отримати Взірці Сили. Іди до Зул'Ґуруба. Убий поплічників Хаккара. Повернися, коли отримаєш те, що я шукаю. Забери перше бойове спорядження вільнодумця Зандалару.\n\nІди.", [3] = "Принесіть Первісні Хаккарські Кайдани Джін'роха Руйнівника. Ви також повинні мати репутацію, рівну або вищу за Дружні стосунки з Плем'ям Зандалар.\n\nДжін'рох Руйнівник знаходиться на острові Йоджамба, Терниста Долина.", [4] = "Ти повернувся? У тебе є Взірці Сили? Ти марнуєш мій час?\n\nСподіваюся, що ні, язичнику.", [5] = "Ти багато робиш для нашої честі. Твої руки заплямовані кров’ю поплічників Хаккара. Ти друг племені.\n\nНосіть ці наручі. Це нарукавники вільнодумців. Ось що я маю на увазі під справжньою силою.", ["en"] = "Paragons of Power: The Freethinker's Armguards" },
    [85619] = { [1] = "Взірці могутності: пояс вільнодумця", [2] = "Ваші вірування нам чужі, язичники. Стародавніх Зандаларів колись таврували єретиками. Це було за часів сильної Імперії Гурубаші. Язичники наважилися кинути виклик жерцю Хаккара. Тоді на язичників полювали та вбивали як на паразитів. Ці язичники ніколи не вагалися у своїй боротьбі проти Бога Криви. Ми шануємо ціну, яку вони заплатили. Вони — вільнодумці.\n\nЗнищте поплічників Хаккара в Зул'Ґурубі. Принесіть мені Взірці Сили, яких я шукаю. Успіх буде щедро винагороджений.\n\nІдіть.", [3] = "Принесіть Джін'року Руйнівнику Первісну Хаккарі-шаль. Ви також повинні мати репутацію, що дорівнює або вища за «Шановний у племені Зандалар».\n\nДжін'рок Руйнівник знаходиться на острові Йоджамба, в Тернистій долині.", [4] = "Твоя присутність означає перемогу? Чи маєш ти Ідеалів? Чи стікаєш ти останками своїх ворогів?", [5] = "Твоя честь гарантована в племені. Ти забираєш багато смертей у Зул'Ґурубі. Вороги падають перед твоїми переконаннями. Вороги падають перед твоєю владою.\n\nЦе пояс вільнодумця. Це символ честі. Це могутнє мохо. Тепер він твій.", ["en"] = "Paragons of Power: The Freethinker's Belt" },
    [85620] = { [1] = "Взірці могутності: кіраса вільнодумця", [2] = "Бойове спорядження дає тобі владу в племені. Вільнодумців шанують саме так. Вони фанатики. Вони наповнюють свої нагрудники могутньою силою. Якщо їхні переконання похитнуться перед обличчям ворога, їхній нагрудник не похитнеться.\n\nТи маєш бути шанованим серед нас, щоб володіти таким нагрудником. Іди до Зул'Ґуруба. Забери Взірці Сили, які мені потрібні. Забери Взірці найболючіше у дурнів всередині. Приведи їх мені. Доведи свою цінність вільнодумця раз і назавжди.", [3] = "Принесіть Джін'року Руйнівнику Первісний герб Хаккарі. Ви також повинні мати репутацію, рівну або вищу за «Шановний» у племені Зандалар.\n\nДжін'рок Руйнівник знаходиться на острові Йоджамба, в Тернистій долині.", [4] = "У тебе є Ідеали? У них всередині є чарівність. Ми повинні їх мати. Ти нам допоможеш.", [5] = "Ти зробив те, що мало хто міг. Ти поставив на коліна поплічників Хаккара. Ти показав їм, на що здатний вільнодумець. Ти показав нам, як єретика можна шанувати в племені. У тебе більше, ніж просто реальна сила. Ти Є справжня сила.\n\nВізьми нагрудник, вільнодумцю. Знищи тих, хто тобі протистоїть.", ["en"] = "Paragons of Power: The Freethinker's Breastplate" },
    [85643] = { [1] = "Повелитель Чорнокамінної гори", [2] = "Ідіть до Долини Героїв і поговоріть з фельдмаршалом Стоунбріджем.", [3] = "Вирушайте до Долини Героїв у Штормовії та поговоріть з фельдмаршалом Стоунбріджем.", [5] = "<Фельдмаршал Стоунбрідж кланяється.>\n\nОберіть свою нагороду, нехай свято почнеться!", ["en"] = "The Lord of Blackrock" },
    [85659] = { [1] = "Святкування хороших часів", [2] = "Знайдіть майора Меттінглі в Долині Героїв, {ім'я}. Він чекатиме на вас...", [3] = "Знайдіть майора Меттінглі в Долині Героїв.", [5] = "Мало хто удостоївся такої церемонії, {ім'я}. Будь ласка, оберіть свою нагороду, щоб ми могли розпочати святкування.", ["en"] = "Celebrating Good Times" },
    [85701] = { [1] = "Шкірництво драконячої луски", [2] = "Шкіряна справа з луски дракона нелегка, але надзвичайно корисна. Я навчу вас, як виготовляти ці вишукані кольчужні обладунки, але лише якщо ви погодитеся на певні умови.\n\nОбираючи цей шлях, ви погоджуєтеся ніколи не вивчати елементарну чи племінну шкіряну справу; на вершині ремесла є місце лише для одного з трьох. Крім того, мені знадобляться деякі зразки вашої найкращої роботи, пов'язаної з обладунками скорпідів. Нарешті, мені знадобиться доказ вашої здатності отримати основний матеріал ремесла: луску драконів.", [3] = "Принесіть 2 міцні нагрудники скорпіда, 2 міцні рукавички скорпіда та 10 зношених лусок дракона Пітеру Галену в Азшару.\n\nВиконання цього завдання надасть вам доступ до мистецтва обробки шкіри з луски дракона.\n\nВиконання цього завдання не дозволить вам вивчити елементарну та племінну обробки шкіри; переконайтеся, що це саме той шлях, яким ви хочете піти, перш ніж робити це.", [4] = "Якщо ти готовий прийняти остаточне рішення, ставши шкіряником з драконячої луски, тоді я готовий взяти тебе в учні. Просто принеси мені те, що я просив, і ми розпочнемо твоє навчання.", [5] = "Повірте, потрібна сильна воля, щоб прийняти остаточне рішення, як ви щойно зробили. Запевняю вас, обробка шкіри з драконячої луски виявиться для вас прибутковим та винагороджуючим шляхом.\n\nЩоб навчитися цьому мистецтву в майбутньому, просто зверніться до мене, і я надам вам будь-які знання, якими ви ще не поділилися.", ["en"] = "Dragonscale Leatherworking" },
    [85703] = { [1] = "Шкірництво стихій", [2] = "Елементарна шкіряна справа — це те, що я знаю, і якщо ви готові відкрити свій розум для вищих сил матерії, я поділюся з вами всім, чого можна навчитися.\n\nЗнай, {клас}: обравши цей шлях, ти погоджуєшся ніколи не навчатися лусочці дракона чи племінній шкіряній справі; є місце лише для практики одного з трьох мистецтв. Крім того, мені знадобляться достатні докази того, що ти налаштований на стихії природи; для цього принеси мені найчистіші есенції вогню, води, землі та вітру.", [3] = "Принесіть 2 Серця Вогню, 2 Кулі Води, 2 Ядра Землі та 2 Подихи Вітру Сарі Таннер у Пекучій Ущелині.\n\nВиконання цього завдання надасть вам доступ до мистецтва Стихійної Шкіряної справи.\n\nВиконання цього завдання не дозволить вам вивчити Шкіряну справу з Драконячої Луски та Племінну Шкіряну справу; переконайтеся, що це шлях, яким ви хочете піти, перш ніж робити це.", [4] = "Виготовлення такого роду шкіряних обладунків вимагає терпіння та відданості. Як тільки ви зв'яжете свою долю зі стихіями, ви вже не зможете від них відвернутися. Принесіть мені доказ вашої гідності, і ми почнемо.", [5] = "Ти обрав свій рахунок, і стихії приймають тебе. Як тільки я завершу своє навчання, ти опануєш волею створювати найтонші шкіряні шати.\n\nЩоб навчитися цьому мистецтву на майбутнє, просто звернися до мене, і я зроблю доступними всі знання, якими ти ще маєш поділитися.", ["en"] = "Elemental Leatherworking" },
    [85705] = { [1] = "Шкірництво предків", [2] = "Щоб навчитися племінній обробці шкіри, потрібно розуміти, наскільки первісною є природа насправді; я знаю, що ви вже опанували мистецтво виготовлення обладунків з дикої шкіри, і я готовий завершити ваше навчання.\n\nЗнай, {клас}: обравши цей шлях, ви погоджуєтеся ніколи не навчатися лусці дракона чи елементарній обробці шкіри; є місце лише для практики одного з трьох мистецтв. Крім того, принесіть мені найкращі зразки ваших обладунків з дикої шкіри. Звідти ми почнемо вашу майстерність.", [3] = "Принесіть жилет з дикої шкіри та шолом з дикої шкіри Каріссії Місячному Мисливцю у Фераласі.\n\nВиконання цього завдання надасть вам доступ до племінних мистецтв шкіряної справи.\n\nВиконання цього завдання не дозволить вам вивчити шкіряну справу з лускою дракона та елементарну шкіряну справу; переконайтеся, що це саме той шлях, яким ви хочете піти, перш ніж робити це.", [4] = "Природа — це сила, яку потрібно задобрити, перш ніж ви сподіваєтеся навчитися підкоряти її волі своєму шкіряному одягу. Принесіть мені свою жертву цій силі, і я подбаю про те, щоб вас почули.", [5] = "Ти зробив свої найкращі дари, і природа скоро дозволить тобі підкорити її своїй волі. Як тільки я завершу своє навчання, твоя робота стане силою природи сама по собі.\n\nЩоб навчитися мистецтву на майбутнє, просто звернися до мене, і я зроблю доступними будь-які знання, які тобі ще належить передати.", ["en"] = "Tribal Leatherworking" },
    [85713] = { [1] = "Мистецтво виготовлення обладунків", [2] = "Отже, ви прийняли розумне рішення.\n\nМіж мною та старим Айронусом немає жодної розлуки. Цей нікчемний виробник іграшок знає, хто тут справжні майстри.\n\nСправді великі війни виграються гарним захистом. Коли настане час, жодна атака вам не допоможе.\n\nДобре, тож давайте до роботи. Вам потрібно лише показати мені, що у вас є якийсь чистий талант. Після цього я вирву з вас будь-які домішки, що залишилися, і перетворю вас на зброяра. Ви ж знаєте, як робити вишуканий міфрил, чи не так?", [3] = "Щоб стати Зброярем, ви повинні виготовити такі предмети та повернути їх Грумнусу: 4 Вишукані Міфрилові Шоломи, 2 Вишукані Міфрилові Чоботи, 1 Вишуканий Міфриловий Нагрудник.", [4] = "О, ніщо не зрівняється з гарною ковальською засмагою. Ви можете сказати, у кого справді гарна засмага, по лініях фартуха.", [5] = "Ось так, {ім'я}. Після цього шляху назад немає. Ще не пізно стати виробником іграшок, тобто, зброярем.\n\nСподіваюся, ви приймете правильне рішення.", ["en"] = "The Art of the Armorsmith" },
    [85798] = { [1] = "Бойова зброя", [2] = "Бригада Залізної Кузні була гідним союзником у нашій битві за Силітус. На жаль, багато їхніх припасів було втрачено дорогою сюди. Роздобудьте партію зброї та доставте її Джанелі Стаутхаммер поблизу Вулика'Зора.", [3] = "Принесіть 2 мечі з місячної сталі Джанелі Стаутхаммер на форпост бригади Залізогарта за межами Вулика'Зора. Ви також повинні принести Інструктаж з логістики VI, щоб виконати це завдання.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "О, чудово! Мені більше не доведеться чути скарг на затуплені леза. Дякую, {ім'я}.", ["en"] = "Arms for the Field", ["tasks"] = { ["Logistics Task Briefing VI"] = "план логістичного завдання VI" } },
    [85882] = { [1] = "Кінець Темної Орди", [2] = "Діло зроблено. Дал'ренд Чорнорукий, Вождь Темної Орди, лежить мертвим біля ваших ніг. Візьміть його голову та віддайте її Майстру Шоу.", [3] = "Віднесіть голову Ренда Чорнорукого майстру Матіасу Шоу в Штормовій.", [5] = "Молодець, чемпіоне. Вождь Темної Орди мертвий, що поклало край ері терору на наших землях. Повідом про твою перемогу весь Штормовій!", ["en"] = "End of the Dark Horde" },
    [85963] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, які мають лише один почесний знак, я обміняю його на невелику відзнаку у вигляді Срібного Світанку.\n\nБудь ласка, пам’ятайте, що краще здати стек із десяти печаток одночасно; ваші зусилля отримають більше визнання, якщо це зробити. Ми пропонуємо обмін одного печатки як послугу для тих, кому їх недостатньо для повного стеку з десяти.\n\nЗ огляду на це, я готовий допомогти вам, якщо ви все ще бажаєте здати один печатку.", [5] = "Чудово – ваші вчинки внесено до архіву, і ваші зусилля належним чином відзначені. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще якісь підписи, я зможу вам допомогти в цьому питанні.", ["en"] = "One Commendation Signet" },
    [85964] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені передасте, я подбаю про те, щоб ви отримали значне визнання ваших вчинків від Срібного Світанку. Я також приймаю поодинокі жетони, але зі значно меншим рівнем визнання. Нас набагато більше цікавлять більші подвиги, хоча жоден подвиг не буде проігноровано.\n\nЗ огляду на це, я із задоволенням візьму ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пішли на неабияку жертву, щоб заслужити ці печатки, і ваші послуги будуть належним чином відзначені. Саме такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nПовідомте мене, якщо у вас є додаткові печатки, які потрібно здати; я з радістю допоможу вам обміняти ті, які вам потрібно.", ["en"] = "Ten Commendation Signets" },
    [85969] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен комплект із десяти, який ви мені передасте, я подбаю про те, щоб ви отримали значне визнання ваших вчинків від Кола Кенаріона. Я також приймаю окремі жетони, але зі значно меншим рівнем визнання. Нас набагато більше цікавлять більші подвиги, хоча жоден подвиг не буде проігноровано.\n\nЗ огляду на це, я із задоволенням візьму ваші печатки, якщо ви готові здати комплект.", [5] = "Чудово! Ви пішли на неабияку жертву, щоб заслужити ці печатки, і ваші послуги будуть належним чином відзначені. Саме такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nПовідомте мене, якщо у вас є додаткові печатки, які потрібно здати; я з радістю допоможу вам обміняти ті, які вам потрібно.", ["en"] = "Ten Commendation Signets" },
    [85970] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, які мають лише одну похвальну печатку, я обміняю її на невелику відзнаку від Кенарійського кола.\n\nБудь ласка, пам’ятайте, що краще здати купу з десяти печаток одночасно; ваші зусилля отримають більше визнання, якщо це зробити. Ми пропонуємо обмін однієї печатки як послугу для тих, кому не вистачає на повну купу з десяти.\n\nЗ огляду на це, я готовий допомогти вам, якщо ви все ще бажаєте здати одну печатку.", [5] = "Чудово – ваші вчинки внесено до архіву, і ваші зусилля належним чином відзначені. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще якісь підписи, я зможу вам допомогти в цьому питанні.", ["en"] = "One Commendation Signet" },
    [85971] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, які мають лише один почесний знак, я обміняю його на невелике визнання від моїх сил, Гідраксійських Водоловів.\n\nБудь ласка, пам’ятайте, що краще здати купу з десяти знаків одразу; ваші зусилля отримають більше визнання, якщо це зробити. Я пропоную обмін одного знака як послугу для тих, у кого недостатньо для повного стеку з десяти.\n\nЗ огляду на це, я прийму його, якщо ви все ще бажаєте здати один знак.", [5] = "Чудово — ваші вчинки визнано. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще якісь печатки, я їх прийму.", ["en"] = "One Commendation Signet" },
    [85973] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені передасте, ви отримаєте значне визнання від моїх сил, Гідраксійських Водоловів. Я також приймаю окремі жетони, але зі значно меншим рівнем визнання. Мене набагато більше цікавлять більші подвиги, хоча жоден подвиг не буде проігноровано.\n\nЗ огляду на це, я прийму ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пішли на неабияку жертву, щоб заслужити ці печатки, і ваші послуги будуть належним чином відзначені. Саме такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nПовідомте мене, якщо у вас є додаткові печатки, які ви хочете здати; я з радістю їх прийму.", ["en"] = "Ten Commendation Signets" },
    [85975] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, які мають лише одну похвальну печатку, я обміняю її на невелике визнання від Торієвого Братства.\n\nБудь ласка, пам’ятайте, що краще здати купу з десяти печаток одночасно; ваші зусилля отримають більше визнання, якщо це зробити. Ми пропонуємо обмін однієї печатки як послугу для тих, кому не вистачає на повну купу з десяти.\n\nЗ огляду на це, я готовий допомогти вам, якщо ви все ще бажаєте здати одну печатку.", [5] = "Чудово – ваші вчинки внесено до архіву, і ваші зусилля належним чином відзначені. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще якісь підписи, я зможу вам допомогти в цьому питанні.", ["en"] = "One Commendation Signet" },
    [85976] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені передасте, я подбаю про те, щоб ви отримали значне визнання ваших діянь від Торієвого Братства. Я також приймаю поодинокі жетони, але зі значно меншим рівнем визнання. Нас набагато більше цікавлять більші подвиги, хоча жоден подвиг не буде проігноровано.\n\nЗ огляду на це, я із задоволенням візьму ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пішли на неабияку жертву, щоб заслужити ці печатки, і ваші послуги будуть належним чином відзначені. Саме такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nПовідомте мене, якщо у вас є додаткові печатки, які потрібно здати; я з радістю допоможу вам обміняти ті, які вам потрібно.", ["en"] = "Ten Commendation Signets" },
    [85979] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, у яких є лише один почесний знак, я обміняю його на невелике визнання від Картелю Стімвідлів.\n\nБудь ласка, пам’ятайте, що краще здати купу з десяти знаків одразу; ваші зусилля отримають більше визнання, зробивши це. Ми пропонуємо обмін одного знака як послугу для тих, у кого їх недостатньо для повного стеку з десяти.\n\nЗ огляду на це, я готовий допомогти вам, якщо ви все ще хочете здати один знак.", [5] = "Чудово — ваші документи внесено до реєстрів, і ваші зусилля належним чином відзначені. Продовжуйте гарну роботу, {клас}.\n\nЯкщо у вас є ще якісь печатки, я можу продовжити з вами торгівлю.", ["en"] = "One Commendation Signet" },
    [85982] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені вручите, я подбаю про те, щоб ви отримали значне визнання ваших вчинків від Картелю Стімвідлів. Я також приймаю поодинокі жетони, але зі значною знижкою у визнанні. Нас набагато більше цікавлять більші подвиги, хоча жоден подвиг не буде проігнорований.\n\nЗ огляду на це, я з радістю обміняю ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пішли на неабияку жертву, щоб заслужити ці печатки, і ваші заслуги будуть належним чином відзначені. Саме такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nПовідомте мене, якщо у вас є додаткові печатки, які ви хочете здати; я з радістю їх вам обміняю.", ["en"] = "Ten Commendation Signets" },
    [85983] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, які мають лише один почесний знак, я обміняю його на невелике визнання від Племені Зандалар.\n\nМайте на увазі, що краще здати купу з десяти знаків одночасно; ваші зусилля отримають більше визнання, зробивши це. Ми також пропонуємо обмін одного знака як благодійність для тих, кому не вистачає на повний куп з десяти.\n\nТим не менш, я готовий допомогти вам, якщо ви все ще бажаєте здати один знак.", [5] = "Чудово — ваші вчинки були визнані Зандаларами. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще печатки, я допоможу вам.", ["en"] = "One Commendation Signet" },
    [85985] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені передасте, я подбаю про те, щоб ви отримали велике визнання від Племені Зандалар. Я також приймаю окремі жетони, але з набагато меншим благословенням. Нас набагато більше цікавлять більші подвиги службового обов'язку, хоча жоден подвиг не буде проігноровано.\n\nЗ огляду на це, я із задоволенням візьму ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пожертвували собою, щоб заробити ці печатки, і отримаєте відповідні благословення. Такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nЗвертайтеся до мене, якщо у вас є додаткові печатки, які потрібно здати; я з радістю допоможу вам з обміном.", ["en"] = "Ten Commendation Signets" },
    [85987] = { [1] = "Одна відзнака подяки", [4] = "Для тих сторонніх, хто прийде до мене з однією похвальною печаткою, я обміняю її на невелику прихильність від Лісова Пасть.\n\nМайте на увазі, що мене більше вражає стек із десяти печаток одночасно; ваші зусилля отримають більшу прихильність від цього. Я пропоную обмін однією печаткою лише для зручності тим, у кого немає повного стеку з десяти.\n\nОднак, я готовий допомогти вам, якщо ви все ще бажаєте дати мені одну печатку.", [5] = "Чудово! Деревопузі визнає ваші зусилля. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще якісь печатки, я можу вам допомогти.", ["en"] = "One Commendation Signet" },
    [86] = { [1] = "Пиріг для Біллі", [2] = "Якби ж у мене був пиріг, тоді я б, мабуть, згадав, у кого може бути те намисто. Знаєш, я вважаю, що старенька Берніс робить чудові пироги зі свинячої підчеревини...\n\nМожливо, якщо ти даси їй кілька шматків м'яса кнурів, які водяться навколо наших ферм, і чемно попросиш, то вона зробить тобі пиріг.", [3] = "Принесіть 4 шматки м'яса кнура тітці Берніс Кам'янопільській на ферму Камянопільських.", [4] = "По-перше, не думаю, що це правильно — годувати хлопця, який вкрав моє намисто, але якщо це все, що необхідно зробити, щоб повернути моє, то нехай!\n\nУ тебе є м'ясо кнура?", [5] = "Хоч м'ясо диких кнурів жорстке, його треба лише гарненько протушкувати, і воно, безперечно, згодиться для смачного пирога!", ["en"] = "Pie for Billy", ["tasks"] = { ["Chunk of Boar Meat"] = "шматок м'яса кнура", ["Chunk of Boar Meat (Provided)"] = "шматок м'яса кнура (видано)" } },
    [86160] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від сторонніх осіб, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені передасте, ви отримаєте значну прихильність від Лісова Пасть. Я також приймаю поодинокі жетони, але за набагато меншу прихильність. Мене набагато більше цікавлять більші подвиги служби, хоча жоден подвиг не буде проігнорований.\n\nЯ з радістю обміняю ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пожертвували собою, щоб заслужити ці печатки, і цим заслужили нашу прихильність. Такі сторонні люди, як ви, {ім'я}, справді можуть змінити ситуацію.\n\nПоверніться до мене, якщо у вас є додаткові печатки, які потрібно передати; я обміняю їх на додаткову прихильність.", ["en"] = "Ten Commendation Signets" },
    [86574] = { [1] = "Постачання Кам'яного Кігтя", [2] = "<На цьому нещасному тілі є сліди численних ударів виверн Гордокрилих. Рюкзак поруч зім'ятий і викинутий, його вміст відсутній, і лише маленька записка, затиснута в руці кур'єра, вказує на те, що було втрачено: вантаж, призначений для шинкарки Фаралії на Піку Кам'яного Кігтя.>\n\n<Виверни, ймовірно, забрали пакунки з припасами, щоб вистилати ними свої гнізда.>", [3] = "Зберіть 6 припасів Кам'яного Кігтя у Гордокрилих Виверн та доставте їх господарці таверни Фаралії.", ["en"] = "Stonetalon Supply Run", ["tasks"] = { ["Stonetalon Supply Bundle"] = "Комплект постачання Кам'яного Кігтя", ["Stonetalon Supply Satchel"] = "Сумка з припасами Кам'яного Кігтя", ["Stonetalon Supply Satchel (Provided)"] = "Сумка з припасами Кам'яного Кігтя (видано)" } },
    [86585] = { [1] = "Прапор полеглих", [2] = "Занепала альпіністка несе штандарт Залізогарта. Можливо, вона була на розвідці або йшла в атаку, приреченою на поразку. У будь-якому разі, штандарт був скинутий і розтоптаний. Альпіністку так сильно вдарили по голові, що їй збили шолом, і вона була вбита троґгом, ймовірно, шипастою палицею.\n\nТрогг, який її вбив, ймовірно, все ще поруч і, ймовірно, пам'ятає прапор. Підняття прапора Залізогарта ще раз може викликати його.", [3] = "Підніміть прапор Залізогарта, покличте трогга Роздільника Голов і вбийте його, а потім доповідіть капітану Ругельфуссу.", [4] = "Цей стяг має такий вигляд, наче побував на війні!", [5] = "Ви знайшли тіло Ільви? Ох, бідолашна. Вона казала, що покаже троггам: Залізогарт ніколи не впаде перед їхнім племенем. Вона вирушила на пошуки кількох горян, які не повернулися з патрулювання земель троггів. Вона завжди була надто незалежною, щоб бути обережною. Тепер ми знаємо, що сталося.\r\n\r\nЯ заберу стяг і подбаю, щоб його почистили та виставили на почесному місці. А ви візьміть її зброю. Нехай вона добре послужить вам у боротьбі з троггами.", ["en"] = "Banner of the Fallen", ["tasks"] = { ["Banner of Ironforge"] = "Прапор Залізогарта", ["Banner of Ironforge (Provided)"] = "Прапор Залізогарта (видано)", ["Headsplitter slain"] = "Роздільник голов: убито" } },
    [86613] = { [1] = "Інструменти для земляних робіт", [2] = "Інструменти розкопок, залишені гномами, коли вони втікали від троггів, здаються майже недоторканими. Повернення їх землекопам, безсумнівно, допоможе їхній роботі.", [3] = "Поверніть 6 інструментів для розкопок Магмару Феллх'ю.", ["en"] = "Excavation Tools", ["tasks"] = { ["Excavation Tools"] = "Інструменти для земляних робіт", ["Excavation Tools (Provided)"] = "Інструменти для земляних робіт (видано)" } },
    [86614] = { [1] = "Срібло хвиль", [2] = "<Серед рибальських дрібничок у залишках є кілька іржавих гачків, зламані котушки дроту та трохи проржавіла, але вишукано прикрашена срібна шпилька для волосся з монограмою «К.Д.»>", [3] = "Поверніть срібну шпильку для волосся з монограмою її власнику.", [4] = "Сьогодні в мене купа справ, тож можеш швидше?", [5] = "Моя шпилька! Я вже думала, що втратила її назавжди!\r\n\r\nТрохи попрацювати — і вона знову засяє. Дякую, що приніс її мені! Я тебе щедро винагороджу.", ["en"] = "Silver of the Waves", ["tasks"] = { ["Monogrammed Silver Hair Clip"] = "Срібна заколка для волосся з монограмою", ["Monogrammed Silver Hair Clip (Provided)"] = "Срібна заколка для волосся з монограмою (видано)" } },
    [86667] = { [1] = "Засніжений", [2] = "Мій старий наставник, Норрік, послав до мене другорядного елементаля з дивним проханням. Йому потрібна банка снігу для деяких його шаманських робіт! Я не знаю, що він збирається з цим робити, але я давно навчився не ставити під сумнів його звички щодо магії.\n\nЯ зайнятий тим, щоб облаштуватися та вивчити місцевих елементалів, тому не можу піти, щоб допомогти йому. Чи міг би ти зробити це для мене? Вирушай до перевалу Південні Ворота, де цілий рік лежить сніг. Зачерпни трохи снігу в цю керамічну банку та принеси йому, поки він не розтанув.", [3] = "Доставте банку зі снігом Норріку Лохтану.\n\nНаданий предмет:", [4] = "Га? Чого тобі?", [5] = "Ця банка для мене?\n\nСніг! Ґренгільді вдалося! Вона надіслала сніг, який я просив!\n\nШкода лише, що вона не прийшла особисто.\n\nХай там як, дякую за допомогу. Це справді дуже допоможе моїй роботі.", ["en"] = "Snowbound", ["tasks"] = { ["Jar of Snow"] = "Банка зі снігом", ["Jar of Snow (Provided)"] = "Банка зі снігом (видано)", ["Jar of Snow slain"] = "Банка зі снігом: убито" } },
    [86725] = { [1] = "Прах до праху", [2] = "Ах так, небезпеки пустелі. Ні, не виснажлива спека, не нестерпне сонячне світло, не пісок, що повзе у ваші шати, не морозні ночі.\n\nІнші небезпеки! Комахи, а тепер ще й надокучливі тварюки. Наша розвідка повідомила, що Орда збирає бруд!\n\nЗазвичай я б не назвав це чимось незвичайним для них, але Силітист? Я б волів, щоб вони не розкривали таємниці піску. Як головний експедиційний реквізитор, я прошу конкуруючого наказу! Принесіть мені цей бруд!", [3] = "Знайдіть і доставте 5 силітистів видобувачу силітистів, а потім поговоріть з головним експедиційним реквізитором Енклзом у таборі Альянсу поблизу Вулика'Зора.", [4] = "Що ти досі тут робиш, {ім'я}? Моє зілля передбачення підказало мені, що ти саме та людина, яка потрібна для цієї роботи!\n\nНам вдалося перетворити есенцію кристалів Силітуса на зілля, яке надає користувачеві здатність обмеженого передбачення.\n\nО, вибачте, але я не маю права надавати вам ці зілля на даний момент.", [5] = "Дуже добре {ім'я}! Дозвольте мені просто внести цю транзакцію до мого журналу...\n\nОсь і все. Якщо у нас виникнуть інші питання щодо реквізиції, я надішлю їх вам, і як головний експедиційний реквізитор, я очікую на допомогу.\n\nНа жаль, я не уповноважений платити вам, але я не досяг того, де я зараз, не винагороджуючи своїх підлеглих! У мене є багато рецептів, які були запрошені, але ніколи не розповсюджувалися. Як винагороду я дозволю вам придбати їх з моєї бібліотеки забутих знань.", ["en"] = "Dust to Dust" },
    [86757] = { [1] = "Стримати наступ орків", [2] = "Орки захопили східний ліс, і тепер їхні розвідники та піхотинці нишпорять усюди між деревами! Нашому народові більше небезпечно мандрувати Ясенедолом.\n\nМи маємо відтіснити орків і убезпечити ліс. Нам вдалося знищити кількох піхотинців та розвідників, обережно підкрадаючись до околиць їхнього табору.\n\nБийся з орками й принеси мені їхні зазубрені мечі та вигнуті ножі. Я подбаю, щоб їхню зброю переробили й використали з користю — нічого не пропаде даремно.", [3] = "Принесіть Шандріні 6 зазубрених оркських мечів і 4 вигнуті оркські кинджали.", ["en"] = "Slowing the Orc Advance", ["tasks"] = { ["Curved Orcish Dagger"] = "Вигнутий орчий кинджал", ["Jagged Orcish Sword"] = "Зазубрений орчий меч" } },
    [86758] = { [1] = "Скручування ножа", [2] = "Чи розповідав я тобі колись, як мало не втратив руку через кроколіска? Встромив ніж йому в щелепу і швидко вибрався. Я думав, що ніж десь тут у мене є, але ніяк не можу його знайти.\n\nУ будь-якому разі, той крокодил, мабуть, досі полює на березі озера. Цьому гидкому звіру, мабуть, треба зникнути, як мінімум, заради безпеки інших мисливців.\n\nЯ почав називати його Кинджал-Ікло. Якщо побачиш його, привітайся з ним від мене! А під «привіт» я маю на увазі «проткни».", [3] = "Знайдіть та переможіть кроколіска Кинджального Ікла та поверніть ніж Марека.", [4] = "Ну як полювання?", [5] = "Ха! Вам вдалося! Ніколи не думав, що той старий крокодил таки отримає по заслугах, але ви з ним упоралися!\r\n\r\nОх... знаєте, мені довелося роздобути собі іншого ножа, тож, може, цей принесе вам удачу. Чому б вам не залишити його собі?", ["en"] = "Twisting the Knife", ["tasks"] = { ["Marek's Croc-Hunting Knife"] = "Ніж Марека для полювання на крокодилів" } },
    [86762] = { [1] = "Колода Темного місяця: елементалі", [2] = "Тепер, коли ви зібрали всі карти Елементалів у колоду, таємничим чином з'являється дев'ята карта з такою ж підкладкою, як і перші вісім. На цій карті написано: «Поверніть ці карти на Ярмарок Молодика та отримайте винагороду». Ви чули, що цей ярмарок по черзі зупиняється в Мулгорі та Голдширі кожні кілька місяців, тому вам доведеться почекати, поки вони тут з'являться наступного разу.", [3] = "Поверніть колоду Елементалів на Ярмарок Молодика, коли вона прийде до міста.", [4] = "Бачу, що тобі вдалося зібрати колоду елементалів! Вітаю!", [5] = "Отже, ви зібрали колоду Елементалів. Ваш жест повернення її нам створить зв'язок між вами та Темнолунням, який нескоро буде забутий. Дозвольте мені подарувати вам одну з найбільших карт Темнолуння як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Elementals Deck", ["tasks"] = { ["Elementals Deck"] = "колода елементалів" } },
    [86776] = { [1] = "Інгредієнти для кузні", [2] = "Телсамар — чудове місце для життя, але в нас немає всіх зручностей Айронфорджа. У мене завжди закінчується бронза! Мені потрібно більше бронзи, якщо я збираюся продовжувати виготовляти інструменти, чайники та горщики!\n\nБачу, у тебе є невеликий досвід у кузні. Думаєш, ти міг би виплавити мені кілька бронзових злитків? Я можу тобі добре за це заплатити!", [3] = "Принесіть 10 бронзових злитків Морхану Мідновусту.", [5] = "Ох, яке полегшення! Тепер я зможу підтримувати вогонь у кузні. Сподіваюся, колись у нас з'явиться торговець, який регулярно привозитиме до міста вугілля!", ["en"] = "Ingredients for the Forge", ["tasks"] = { ["Bronze Bar"] = "злиток бронзи" } },
    [87] = { [1] = "Золотозуб", [2] = "Я бавився біля Бездонної копальні та, здається, там загубив... Е-е... тобто бачив намисто старої пані. Не питай мене, як воно туди потрапило... Я тут ні до чого!\n\nКоротше, я побачив здоровенного кобольда із золотим зубом, який підібрав намисто та побіг вглиб шахти. Знайдеш того кобольда — знайдеш і намисто, клянусь!", [3] = "Принесіть \"Тітоньці\" Берніс Кам'янопільській на ферму Кам'янопільських її намисто.", [4] = "Вітаю, {ім'я:к}. Ти {стать:знайшов:знайшла} моє намисто?", [5] = "О, тобі вдалося! Дякую, дякую, {стать:любчику:люба}!\n\nОсь, тримай. Це належало моєму чоловікові, він вважав, що воно приносить удачу. Якби ж він не забув взяти це у свій останній похід! <шморг>", ["en"] = "Goldtooth", ["tasks"] = { ["Bernice's Necklace"] = "намисто Берніс", ["Bernice's Necklace (Provided)"] = "намисто Берніс (видано)" } },
    [87288] = { [1] = "М'які шкури шаблі", [2] = "Привіт, мандрівнику! Сподіваюся, тобі подобається візит до нашого села. Мені подобається Доланаар, бо він маленький і сільський, і всі тут доброзичливі.\n\nЯ місцевий торговець, і я привожу всілякі інструменти та дрібнички, які можуть стати тобі в пригоді під час подорожей. Дійсно, якщо ти зацікавлений в обміні, мені потрібні шкури нічних шабель. Хоча ці величні істоти прекрасні, місцеві досить агресивні, тому не соромся захищатися.", [3] = "Принесіть до Альдрії 6 м'яких шкур нічних мечів.", ["en"] = "Soft Saber Pelts", ["tasks"] = { ["Soft Nightsaber Pelt"] = "М'яка шкура нічного меча" } },
    [87434] = { [1] = "Латні рукавички Сріблястого Світанку", [4] = "Якщо ти принесеш мені тридцять некротичних рун, я натомість дам тобі захист для рук на твій вибір. Вони мають стати в нагоді в нашій боротьбі з нежитью-Бачею.", [5] = "Ви добре попрацювали, {ім'я}. Оберіть захист для рук на знак подяки за ваші зусилля.", ["en"] = "Argent Dawn Plate Gloves" },
    [87436] = { [1] = "Кольчужні рукавички Сріблястого Світанку", [4] = "Якщо ти принесеш мені тридцять некротичних рун, я натомість дам тобі захист для рук на твій вибір. Вони мають стати в нагоді в нашій боротьбі з нежитью-Бачею.", [5] = "Ви добре попрацювали, {ім'я}. Оберіть захист для рук на знак подяки за ваші зусилля.", ["en"] = "Argent Dawn Mail Gloves" },
    [87438] = { [1] = "Шкіряні рукавички Сріблястого Світанку", [4] = "Якщо ти принесеш мені тридцять некротичних рун, я натомість дам тобі захист для рук на твій вибір. Вони мають стати в нагоді в нашій боротьбі з нежитью-Бачею.", [5] = "Ви добре попрацювали, {ім'я}. Оберіть захист для рук на знак подяки за ваші зусилля.", ["en"] = "Argent Dawn Leather Gloves" },
    [87440] = { [1] = "Тканинні рукавички Сріблястого Світанку", [4] = "Якщо ти принесеш мені тридцять некротичних рун, я натомість дам тобі захист для рук на твій вибір. Вони мають стати в нагоді в нашій боротьбі з нежитью-Бачею.", [5] = "Ви добре попрацювали, {ім'я}. Оберіть захист для рук на знак подяки за ваші зусилля.", ["en"] = "Argent Dawn Cloth Gloves" },
    [87491] = { [1] = "Іскра свободи", [2] = "Ссс! Мерзенні дворфи Темного Заліза викликали мене й замкнули в клітці біля свого жалюгідного вогнища!\n\nВогонь має бути диким, вільним! Випусти мене! Треба втекти! Треба ПАЛАТИ!\n\nЖоден дворф Темного Заліза не врятується! Спали їх дотла! Спали їхній чорний порох! Спали їхню фортецю, ґноти та їхню дурість!\n\nВипусти мене, і я СПАЛЮ ЇХ УСІХ!", [3] = "Супроводіть полоненого елементаля вогню з Дун-Модра на волю.", ["en"] = "Spark of Freedom", ["tasks"] = { ["Escort the fire elemental out of Dun Modr"] = "Вивести елементаля вогню з Дун-Модра" } },
    [8762] = { [1] = "Метцен-північний олень", [2] = "КАТАСТРОФА! Метцена-північного оленя викрали!\n\nМетцен — один з восьми північних оленів Дідуся Зими та власність Пасовищ Димного Лісу. Ми отримали не одну, а ДВІ записки з вимогою викупу від злодіїв, які стверджують, що Метцен у них. З розпалом святкового сезону у нас немає грошей! Будь ласка, знайди Метцена та поверни його нам!\n\nПеревір листи з вимогами викупу, щоб знайти підказки, та посип його цим оленячим пилом — він звільнить його від будь-яких пут!\n\nБудь ласка, поквапся!", [3] = "Знайдіть Метцена-північного оленя. Використовуйте надані вам записки, щоб дізнатися, де його утримують.\n\nКоли ви знайдете Метцена, візьміть з собою мішечок з оленячим пилом, щоб посипати його пилом. Це має звільнити Метцена від пут неволі.\n\nПоверніть мішечок з оленячим пилом Хотайну Злотодзвону в Залізогарт, щойно Метцен буде звільнений.", [4] = "{ім'я}! Записки в сумці, яку я дав тобі, дали достатньо інформації, щоб знайти Метцена? Мені страшно думати про те, що ці безсердечні бандити можуть зробити з ним... але ми не можемо дозволити собі заплатити такий непомірний викуп!", [5] = "Ти це {стать:зробив:зробила}! Ура!\n\nМетцен прилетів у стайні Дідуся Зими — так, Метцен справді може літати — всього лише кілька хвилин тому! Пил працює бездоганно, як я й казав. Ти {стать:врятував:врятувала} свято Зимової Покрови та Пасовища Димного Лісу від катастрофи. Дякую, {ім'я}.\n\nПослухай... За свої труди ти заслуговуєш на нагороду. Ось, тримай. Це дещо ДУЖЕ особливе. Думаю, якщо ти {стать:вершник:вершниця}, ти будеш в захваті. З прийдешнім святом Зимової Покрови!", ["en"] = "Metzen the Reindeer", ["tasks"] = { ["Find Metzen the Reindeer and rescue him"] = "Знайдіть оленя Метцена та врятуйте його", ["Pouch of Reindeer Dust"] = "мішечок з оленячим пилом", ["Pouch of Reindeer Dust (Provided)"] = "мішечок з оленячим пилом (видано)" } },
    [8763] = { [1] = "Герой дня", [2] = "Послухай... мені насправді не слід розповідати це тобі, але ти {стать:став:стала} героєм дня і все таке...\n\nСвіжий падуб росте скрізь в цю пору року, але він швидко в'яне. У нас є машина, що зберігає його — і він ніколи не псується! Ми використовуємо його, як прикрасу для свята... і як джерело прибутку влітку!\n\nЯ дозволю тобі використовувати цю сушарку, але тільки якщо ти {стать:майстер-кухар:майстрия-кухарка}. Тобі знадобиться глибокоскельна сіль і, скажімо, п'ять золотих. Ти отримаєш чудову партію сушеного падуба.", [3] = "Принесіть глибокоскельну сіль та 5 золотих монет до апарату для сушіння падуба, щоб отримати 5 сушених падубів.", [4] = "Сушарка для падуба, на перший погляд, є звичайним перегонним кубом, але, оглянувши її детальніше, ви помічаєте певні гоблінські модифікації. Втім, ваші кулінарні навички дозволяють зрозуміти, як працює ця машина.\n\nВсередині вже лежить свіжий падуб — вам лише потрібно додати глибокоскельну сіль і п'ять золотих монет, щоб запустити машину.", [5] = "Машина видає легкий гуркіт і випускає невелику кількість пари, коли починає працювати. Невдовзі вона зупиняється, випустивши ще одну хмаринку пари. Дверцята відкриваються, і всередині ви бачите партію сушеного падуба!", ["en"] = "The Hero of the Day", ["tasks"] = { ["Deeprock Salt"] = "глибокоскельна сіль", ["Deeprock Salt (Provided)"] = "глибокоскельна сіль (видано)" } },
    [8779] = { [1] = "Матеріали для провидінь", [2] = "Дослідження геолога Жартолама виявилися надзвичайно цінними для нашої діяльності в Силітусі. Нещодавно вона звернулася до нас з проханням надати їй матеріали для провидінь, щоб використати їх у своїх дослідженнях.\n\nБудь ласка, збери ці матеріали й віднеси їй, щоб вона продовжила дослідження.", [3] = "Принесіть 1 великий блискучий осколок, 1 великий променистий осколок і 1 величезний смарагд геологу Жартоламу в Кенарійську цитадель, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання V.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "Так, так... Ти мені дуже {стать:допоміг:допомогла}! Дістати ці матеріали в пустелі неймовірно складно, {ім'я}. Дякую.", ["en"] = "Scrying Materials", ["tasks"] = { ["Huge Emerald"] = "величезний смарагд", ["Huge Emerald (Provided)"] = "величезний смарагд (видано)", ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)", ["Large Radiant Shard"] = "великий променистий осколок", ["Large Radiant Shard (Provided)"] = "великий променистий осколок (видано)", ["Logistics Task Briefing V"] = "план логістичного завдання V", ["Logistics Task Briefing V (Provided)"] = "план логістичного завдання V (видано)" } },
    [8780] = { [1] = "Накладки для броні", [2] = "У бригади Залізогарту закінчуються запаси накладок для броні. Добудь партію накладок і віднеси їх Жанелі Дужомолот на аванпост бригади Залізогарта, неподалік Вул'Зори.", [3] = "Принесіть 8 накладок з міцної шкіри та 8 накладок з важкої шкіри Жанелі Дужомолот на заставу бригади Залізогарта, що біля Вул'Зори в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання VII.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "Дякую, я роздам це військовим.", ["en"] = "Armor Kits for the Field", ["tasks"] = { ["Heavy Armor Kit"] = "накладки з важкої шкіри", ["Heavy Armor Kit (Provided)"] = "накладки з важкої шкіри (видано)", ["Logistics Task Briefing VII"] = "план логістичного завдання VII", ["Logistics Task Briefing VII (Provided)"] = "план логістичного завдання VII (видано)", ["Rugged Armor Kit"] = "накладки з міцної шкіри", ["Rugged Armor Kit (Provided)"] = "накладки з міцної шкіри (видано)" } },
    [8781] = { [1] = "Бойова зброя", [2] = "Бригада Залізогарта була гідним союзником в боях в Силітусі. На жаль, по дорозі сюди вони втратили багато припасів. Збери партію озброєння і віднеси її Жанелі Дужомолот до Вул'Зори.", [3] = "Принесіть 2 палаші з місяцесталі Жанелі Дужомолот на заставу бригади Залізогарта, що біля Вул'Зори в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання VI.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "Чудово! Мені більше не доведеться вислуховувати скарги на затуплені леза. Дякую тобі, {ім'я}.", ["en"] = "Arms for the Field", ["tasks"] = { ["Logistics Task Briefing VI"] = "план логістичного завдання VI", ["Logistics Task Briefing VI (Provided)"] = "план логістичного завдання VI (видано)", ["Moonsteel Broadsword"] = "палаш з місяцесталі", ["Moonsteel Broadsword (Provided)"] = "палаш з місяцесталі (видано)" } },
    [8782] = { [1] = "Постачання форми", [2] = "Велика кількість добровольців спричинила нестачу форми. Роздобудь матеріали для форми та віддай їх вітрозову Гордому Рогу.", [3] = "Принесіть 1 місячне полотно, 2 рулони рунічної тканини й 1 залізошовкову павутину вітрозову Гордому Рогу в Кенарійській цитаделі, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання VIII.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "Ми дуже вдячні тобі, {ім'я}. Нам саме цього і не вистачало.", ["en"] = "Uniform Supplies", ["tasks"] = { ["Bolt of Runecloth"] = "рулон рунічної тканини", ["Bolt of Runecloth (Provided)"] = "рулон рунічної тканини (видано)", ["Ironweb Spider Silk"] = "залізошовкова павутина", ["Ironweb Spider Silk (Provided)"] = "залізошовкова павутина (видано)", ["Logistics Task Briefing VIII"] = "план логістичного завдання VIII", ["Logistics Task Briefing VIII (Provided)"] = "план логістичного завдання VIII (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)" } },
    [8783] = { [1] = "Незвичайні матеріали", [2] = "Варґус, коваль Кенарійської цитаделі, попросив зачаровані матеріали для виготовлення потужної зброї для нашого війська. Дістань матеріали та віднеси Варґусу, щоб війська Кенарійської цитаделі й надалі були добре озброєні.", [3] = "Принесіть 2 зачаровані злитки торію та 2 зачаровані шкіри Варґусу в Кенарійську цитадель, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання IX.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "О, так. Ці матеріали відмінної якості. Дякую, {ім'я}.", ["en"] = "Extraordinary Materials", ["tasks"] = { ["Enchanted Leather"] = "зачарована шкіра", ["Enchanted Leather (Provided)"] = "зачарована шкіра (видано)", ["Enchanted Thorium Bar"] = "зачарований злиток торію", ["Enchanted Thorium Bar (Provided)"] = "зачарований злиток торію (видано)", ["Logistics Task Briefing IX"] = "план логістичного завдання IX", ["Logistics Task Briefing IX (Provided)"] = "план логістичного завдання IX (видано)" } },
    [8797] = { [1] = "Альянсу потрібна твоя допомога!", [2] = "Привіт, я рада, що ти {стать:вирішив:вирішила} мене вислухати. Альянсу потрібна допомога, щоб підготуватися до війни в Ан'Кіражі, і це означає, що нам {стать:потрібен:потрібна} ти! Навіть зараз, поки ми з тобою базікаємо, наші інтенданти збирають всі ресурси, які знадобляться для майбутньої війни. Але ми не зможемо досягти мети без твоєї допомоги, {ім'я}!\n\nТи маєш піти поговорити з нашим керівником — фельдмаршалом Снігопадом. Що скажеш, {клас:к}? Допоможеш нам з підготовкою?", [3] = "Поговоріть з фельдмаршалом Снігопадом у Військовій палаті Залізогарта.", [5] = "Вітаю тебе, {стать:хлопче:дівчино}! Радий бачити, що стільки народу з Альянсу, як ти, {ім'я}, приходять сюди, щоб допомогти у підготовці до війни в Ан'Кіражі. Докладені зусилля гарантуватимуть нашу перемогу у війні проти силітидів та їхніх злих господарів, що сховалися в глибинах Ан'Кіража.\n\nОскільки ти вже тут, то обов'язково поговори з різними збирачами ресурсів та запропонуй їм допомогу.", ["en"] = "The Alliance Needs Your Help!" },
    [88] = { [1] = "Принцеса повинна померти!", [2] = "У Бреквеллів є призова свиня, Принцеса. Ця свиноматка ВЕЛИЧЕЗНА! І все через те, що навчилася прокрадатися сюди та жерти мої овочі!\n\nЩо ж, перш ніж вона знову прийде на наші поля... Принцеса повинна померти! Принеси мені її нашийник як доказ завершеної справи, і я тобі чимось віддячу за твій час!\n\nПринцеса, як правило, тиняється по гарбузовому наділі Бреквеллів, на сході, за фермою Маклурів. Розберися з нею до того, як вона зголодніє та повернеться сюди!", [3] = "Убийте Принцесу, заберіть її нашийник і принесіть його до Ма Кам'янопільської на ферму Кам'янопільських.", [4] = "Ти вже {стать:бачив:бачила} свиню? Сподіваюсь, ти вже {стать:вбив:вбила} її?", [5] = "Слава Світлу! Ця свиня стала такою великою, що з'їла б увесь наш урожай! Дякую, {ім'я:к}.\n\nТа-акс, щось з цього тобі підійде?", ["en"] = "Princess Must Die!", ["tasks"] = { ["Brass Collar"] = "латунний нашийник", ["Brass Collar (Provided)"] = "латунний нашийник (видано)" } },
    [8827] = { [1] = "Подарунки Зими", [2] = "Я чув, що Дідусь Зима — за сприяння Пасовищ Димного Лісу — поклав під ялинку в Залізогарті подарунки для всіх і кожного. Шкода, що мені не можна туди піти, адже мені потрібно наглядати PX-238 Зимовим Дивовижем.\n\nАле тобі варто неодмінно туди зазирнути. Я впевнений, що Дідусь Зима знайшов подарунок і для тебе.", [3] = "Поговоріть з Дідусем Зимою біля торгового майданчика Пасовищ Димного Лісу в Залізогарті.", [5] = "О, хо-хо, привіт! Ти тут лише з однією метою: розпакувати свої подарунки на свято Зимової Покрови.\n\nНе хвилюйся, Дідусь Зима не забув {стать:свого улюбленого:свою улюблену} {раса:з}. Поглянь під ялинку і ти знайдеш свої подарунки.\n\nВ цей чудовий час подарунків, можливо, твої друзі також були б раді отримати якісні продукти від Пасовищ Димного Лісу?", ["en"] = "Winter's Presents" },
    [8830] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Дарнаса.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8831] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення Дарнаса до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8860] = { [1] = "Святкування Нового року!", [2] = "Штормовій влаштовує святкування Нового року! Там сьогодні цілий день можна пити задарма, а ввечері буде феєрверк! Це має бути дуже гарно... але в Грабіжній Бухті теж сьогодні влаштовують вечірку. Я впевнений, що там буде ще краще!\n\nВ будь-якому разі, корчмарці Еллісон зі Штормовію потрібні припаси Пасовищ Димного Лісу, щоб нагодувати всіх учасників святкування. Можеш допомогти мені та доставити це?\n\nДякую, {ім'я}! Корчмарка Еллісон знаходиться у \"Позолоченій троянді\", у Торговому районі Штормовію.", [3] = "Принесіть припаси Димного Лісу корчмарці Еллісон в Штормовій.", [4] = "Привіт! Ти {стать:прийшов:прийшла} на вечірку! А може тобі просто потрібно відпочити після подорожі...", [5] = "О, мої припаси Димного Лісу! Чудово! Вони мені знадобляться, щоб нагодувати всіх на святі!\n\nДякую, {ім'я}. Будь ласка, візьми цю плату, і не забудь випити та потанцювати разом з гуляками на вулиці!", ["en"] = "New Year Celebrations!", ["tasks"] = { ["Smokywood Supplies"] = "припаси Димного Лісу", ["Smokywood Supplies (Provided)"] = "припаси Димного Лісу (видано)" } },
    [8870] = { [1] = "Місячний фестиваль", [2] = "Настала ця пора року, {ім'я}! Кенарійське Коло запрошує всіх жителів Азероту взяти участь у нашому святкуванні Місячного фестивалю. У місті ти знайдеш провісницю Місячного фестивалю. Вона знаходиться в місці, позначеному благословенним колом місячного сяйва. Вона розповість тобі більше про це свято.", [3] = "Поговоріть з провісницею Місячного фестивалю в Таємній палаті Залізогарту. Ви також можете поговорити з провісниками Місячного фестивалю в інших столицях.", [5] = "Вітаю, {ім'я}. Ти тут, щоб приєднатися до святкування?", ["en"] = "The Lunar Festival" },
    [8871] = { [1] = "Місячний фестиваль", [2] = "Настала ця пора року, {ім'я}! Кенарійське Коло запрошує всіх жителів Азероту взяти участь у нашому святкуванні Місячного фестивалю. У місті ти знайдеш провісницю Місячного фестивалю. Вона знаходиться в місці, позначеному благословенним колом місячного сяйва. Вона розповість тобі більше про це свято.", [3] = "Поговоріть з провісницею Місячного фестивалю в парку Штормовію. Ви також можете поговорити з провісниками Місячного фестивалю в інших столицях.", [5] = "Вітаю, {ім'я}. Ти тут, щоб приєднатися до святкування?", ["en"] = "The Lunar Festival" },
    [8872] = { [1] = "Місячний фестиваль", [2] = "Настала ця пора року, {ім'я}! Кенарійське Коло запрошує всіх жителів Азероту взяти участь у нашому святкуванні Місячного фестивалю. У місті ти знайдеш провісницю Місячного фестивалю. Вона знаходиться в місці, позначеному благословенним колом місячного сяйва. Вона розповість тобі більше про це свято.", [3] = "Поговоріть з провісницею Місячного фестивалю в Кенарійському Анклаві в Дарнасі. Ви також можете поговорити з провісниками Місячного фестивалю в інших столицях.", [5] = "Вітаю, {ім'я}. Ти тут, щоб приєднатися до святкування?", ["en"] = "The Lunar Festival" },
    [88746] = { [1] = "Освячені точильні камені", [4] = "Якщо ти принесеш мені вісім некротичних рун від загарбників Бичі, я можу дати тобі освячений камінь для точення. Він має дуже допомогти тобі в битві проти поплічників Короля-Ліча.", [5] = "Дякую, {ім'я}. Ось ваші освячені точильні камені. Використовуйте їх розсудливо.", ["en"] = "Consecrated Sharpening Stones" },
    [88748] = { [1] = "Тріснутий некротичний кристал", [2] = "На трупі полеглої гидоти ви виявите тріснутий кристал, що повільно пульсує некротичною енергією.", [3] = "Принесіть Тріснутий некротичний кристал лейтенанту Орріну за воротами Штормовія.", [4] = "Тобі щось потрібно?", [5] = "Гм, ви взяли це з трупа однієї з гидот-загарбників?\n\nМи отримали звістку про базові табори некрополів, які викликає Бич. Підозрюю, що вони хотіли створити один у Штормовії. Добре, що їм це не вдалося.", ["en"] = "Cracked Necrotic Crystal" },
    [88756] = { [1] = "Повернути вибухівку", [2] = "Дворфи Темного Заліза розбили кілька таборів на схід звідси, на пагорбі Жахокузні. Вони викрали купу вибухівки з нашого будівельного майданчика й потягли її до своїх наметів.\n\nНе треба тобі пояснювати, яких лих можуть накоїти дворфи Темного Заліза з діжкою пороху!\n\nЯ знаю, вони небезпечні, але нам потрібні ті діжки. Ти відрізниш їх від інших за червоними позначками. Не можна лишати вибухівку в їхніх руках!", [3] = "Поверніть 3 викраденої вибухівки з таборів дворфів Темного Заліза.", ["en"] = "Bring Back a Bang", ["tasks"] = { ["Stolen Explosives"] = "Вкрадена вибухівка" } },
    [88757] = { [1] = "Речі загубленої", [2] = "Тікаючи від тих дворфів Темного Заліза, я загубила чимало своїх речей!\n\nЗдається, я втратила... зелений шкіряний бурдюк, книгу заклять, намисто та... ці речі мені потрібні!\n\nЯкщо знайдеш їх, поки я перепакую речі й переведу подих, це буде великою допомогою.", [3] = "Поверніть намисто, книгу заклять і бурдюк Ессени.", ["en"] = "Accessories of the Lost", ["tasks"] = { ["Essene's Necklace"] = "Намисто Ессена", ["Essene's Spellbook"] = "Книга заклять Ессена", ["Essene's Waterskin"] = "Бурдюк Ессена" } },
    [88758] = { [1] = "Звістка від загубленої", [2] = "Мені лишилося перепакувати речі — і можна йти звідси!\n\nЗроби мені останню послугу: ось, віднеси цю записку Кормі. З неї вона дізнається, що я жива й уже повертаюся!", [3] = "Віднесіть записку Ессени Кормі Віллард.", ["en"] = "Sentiments of the Lost", ["tasks"] = { ["Essene's Note (Provided)"] = "Записка Ессена (видано)" } },
    [88883] = { [1] = "Благословенна чарівна олія", [4] = "В обмін на некротичні руни загарбників Бичі, Срібний Світанок дасть вам одну пляшечку благословенної чарівної олії.", [5] = "Сподіваюся, що ці предмети стануть вам у пригоді в майбутніх битвах.", ["en"] = "Blessed Wizard Oil" },
    [88969] = { [1] = "Повелитель Чорнокамінної гори", [2] = "Ідіть до Долини Героїв і поговоріть з фельдмаршалом Стоунбріджем.", [3] = "Вирушайте до Долини Героїв у Штормовії та поговоріть з фельдмаршалом Стоунбріджем.", [5] = "<Фельдмаршал Стоунбрідж кланяється.>\n\nОберіть свою нагороду, нехай свято почнеться!", ["en"] = "The Lord of Blackrock" },
    [8899] = { [1] = "Люба Коларо,", [2] = "Як описати її красу? Тисячі років, тисячі слів, а я все розгублений.\n\nЦі смертні бентежать розум, лишаючи нас у дурнях.\n\nЯ занадто довго дивився на ці слова. Чогось більш красномовного я витиснути з них не зможу. Ні, вона має отримати цього листа зараз, інакше якийсь інший залицяльник точно вкраде її серце.", [3] = "Доставте бездоганного листа Коларі Дін за банком Штормовію.", [4] = "Привітики, {стать:красеню:красуне}. Чим я можу тобі допомогти?", [5] = "Я ще ніколи нічого подібного не отримувала. Як мило!", ["en"] = "Dearest Colara,", ["tasks"] = { ["Immaculate Letter"] = "бездоганний лист", ["Immaculate Letter (Provided)"] = "бездоганний лист (видано)" } },
    [89] = { [1] = "Міст Безхвильного озера", [2] = "Під час останньої навали орків нам довелося переплавити весь метал на кулі, мечі та обладунки. Ми послали прохання до Штормовію про нові поставки, але банда гнолів з Багрянокряжжя захопила караван і втекла в гори за Приозер'ям.\n\nТепер нам не вистачає матеріалів для відбудови мосту. Якщо ти принесеш мені 5 залізних пік та 5 залізних заклепок, {ім'я}, я подбаю про те, щоб тебе винагородили.\n\nА тепер до роботи!", [3] = "Принесіть 5 залізних пік та 5 залізних заклепок десятнику Ослоу в Приозер'я.", [4] = "Міст сам себе не збудує! Де залізні піки та заклепки?", [5] = "Чудова робота, {ім'я:к}. Ці припаси дуже допоможуть нам у будівництві мосту. Ми вже зовсім скоро закінчимо цю красу.", ["en"] = "The Everstill Bridge", ["tasks"] = { ["Iron Pike"] = "залізна піка", ["Iron Pike (Provided)"] = "залізна піка (видано)", ["Iron Rivet"] = "залізна заклепка", ["Iron Rivet (Provided)"] = "залізна заклепка (видано)" } },
    [8905] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}. Я маю дещо, що може тебе зацікавити.\n\nВ мене є набір обладунків, схожих на ті, що зазвичай носять представники твого ремесла, але значно вищої якості. Я б охоче віддала тобі їх в обмін на невеличку послугу.\n\nКров кригозубів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз дуже необхідні. Принеси мені вдосталь зразків крові разом з поручами та невеликою кількістю золота. Побачиш — воно того варте.", [3] = "Зберіть 15 зразків крові із Зимоключа та 20 золотих і принесіть їх разом з браслетами дикого серця Деліані в Залізогарт.", [4] = "Ти {стать:приніс:принесла} мені все необхідне, {ім'я}?", [5] = "Прекрасно! Тоді міняємось. Шкода віддавати такі чудові обладунки, та певно вони мені й не знадобляться.\n\nЯкщо погодишся виконати ще кілька доручень, я з радістю віддам тобі інші частини обладунку.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Wildheart Bracers"] = "браслети дикого серця", ["Wildheart Bracers (Provided)"] = "браслети дикого серця (видано)", ["Winterspring Blood Sample"] = "зразок крові із Зимоключа", ["Winterspring Blood Sample (Provided)"] = "зразок крові із Зимоключа (видано)" } },
    [8906] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}. Я маю дещо, що може тебе зацікавити.\n\nВ мене є набір обладунків, схожих на ті, що зазвичай носять представники твого ремесла, але значно вищої якості. Я б охоче віддала тобі їх в обмін на невеличку послугу.\n\nКров кригозубів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз дуже необхідні. Принеси мені вдосталь зразків крові разом з поручами та невеликою кількістю золота. Побачиш — воно того варте.", [3] = "Зберіть 15 зразків крові із Зимоключа та 20 золотих і принесіть їх разом з браслетами ловця звірів Деліані в Залізогарт.", [4] = "Ти {стать:приніс:принесла} мені все необхідне, {ім'я}?", [5] = "Прекрасно! Тоді міняємось. Шкода віддавати такі чудові обладунки, та певно вони мені й не знадобляться.\n\nЯкщо погодишся виконати ще кілька доручень, я з радістю віддам тобі інші частини обладунку.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Beaststalker's Bindings"] = "браслети ловця звірів", ["Beaststalker's Bindings (Provided)"] = "браслети ловця звірів (видано)", ["Winterspring Blood Sample"] = "зразок крові із Зимоключа", ["Winterspring Blood Sample (Provided)"] = "зразок крові із Зимоключа (видано)" } },
    [8907] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}. Я маю дещо, що може тебе зацікавити.\n\nВ мене є набір обладунків, схожих на ті, що зазвичай носять представники твого ремесла, але значно вищої якості. Я б охоче віддала тобі їх в обмін на невеличку послугу.\n\nКров кригозубів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз дуже необхідні. Принеси мені вдосталь зразків крові разом з поручами та невеликою кількістю золота. Побачиш — воно того варте.", [3] = "Зберіть 15 зразків крові із Зимоключа та 20 золотих і принесіть їх разом з браслетами магістра Деліані в Залізогарт.", [4] = "Ти {стать:приніс:принесла} мені все необхідне, {ім'я}?", [5] = "Прекрасно! Тоді міняємось. Шкода віддавати такі чудові обладунки, та певно вони мені й не знадобляться.\n\nЯкщо погодишся виконати ще кілька доручень, я з радістю віддам тобі інші частини обладунку.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Magister's Bindings"] = "браслети магістра", ["Magister's Bindings (Provided)"] = "браслети магістра (видано)", ["Winterspring Blood Sample"] = "зразок крові із Зимоключа", ["Winterspring Blood Sample (Provided)"] = "зразок крові із Зимоключа (видано)" } },
    [8909] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}. Я маю дещо, що може тебе зацікавити.\n\nВ мене є набір обладунків, схожих на ті, що зазвичай носять представники твого ремесла, але значно вищої якості. Я б охоче віддала тобі їх в обмін на невеличку послугу.\n\nКров кригозубів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз дуже необхідні. Принеси мені вдосталь зразків крові разом з поручами та невеликою кількістю золота. Побачиш — воно того варте.", [3] = "Зберіть 15 зразків крові із Зимоключа та 20 золотих і принесіть їх разом з браслетами відданості Деліані в Залізогарт.", [4] = "Ти {стать:приніс:принесла} мені все необхідне, {ім'я}?", [5] = "Прекрасно! Тоді міняємось. Шкода віддавати такі чудові обладунки, та певно вони мені й не знадобляться.\n\nЯкщо погодишся виконати ще кілька доручень, я з радістю віддам тобі інші частини обладунку.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Devout Bracers"] = "браслети відданості", ["Devout Bracers (Provided)"] = "браслети відданості (видано)", ["Winterspring Blood Sample"] = "зразок крові із Зимоключа", ["Winterspring Blood Sample (Provided)"] = "зразок крові із Зимоключа (видано)" } },
    [8910] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}. Я маю дещо, що може тебе зацікавити.\n\nВ мене є набір обладунків, схожих на ті, що зазвичай носять представники твого ремесла, але значно вищої якості. Я б охоче віддала тобі їх в обмін на невеличку послугу.\n\nКров кригозубів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз дуже необхідні. Принеси мені вдосталь зразків крові разом з поручами та невеликою кількістю золота. Побачиш — воно того варте.", [3] = "Зберіть 15 зразків крові із Зимоключа та 20 золотих і принесіть їх разом з поручами тіньового ремесла Деліані в Залізогарт.", [4] = "Ти {стать:приніс:принесла} мені все необхідне, {ім'я}?", [5] = "Прекрасно! Тоді міняємось. Шкода віддавати такі чудові обладунки, та певно вони мені й не знадобляться.\n\nЯкщо погодишся виконати ще кілька доручень, я з радістю віддам тобі інші частини обладунку.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Shadowcraft Bracers"] = "браслети тіньового ремесла", ["Shadowcraft Bracers (Provided)"] = "браслети тіньового ремесла (видано)", ["Winterspring Blood Sample"] = "зразок крові із Зимоключа", ["Winterspring Blood Sample (Provided)"] = "зразок крові із Зимоключа (видано)" } },
