    [8912] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}. Я маю дещо, що може тебе зацікавити.\n\nВ мене є набір обладунків, схожих на ті, що зазвичай носять представники твого ремесла, але значно вищої якості. Я б охоче віддала тобі їх в обмін на невеличку послугу.\n\nКров кригозубів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз дуже необхідні. Принеси мені вдосталь зразків крові разом з поручами та невеликою кількістю золота. Побачиш — воно того варте.", [3] = "Зберіть 15 зразків крові із Зимоключа та 20 золотих і принесіть їх разом з браслетами доблесті Деліані в Залізогарт.", [4] = "Ти {стать:приніс:принесла} мені все необхідне, {ім'я}?", [5] = "Прекрасно! Тоді міняємось. Шкода віддавати такі чудові обладунки, та певно вони мені й не знадобляться.\n\nЯкщо погодишся виконати ще кілька доручень, я з радістю віддам тобі інші частини обладунку.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Bracers of Valor"] = "браслети доблесті", ["Bracers of Valor (Provided)"] = "браслети доблесті (видано)", ["Winterspring Blood Sample"] = "зразок крові із Зимоключа", ["Winterspring Blood Sample (Provided)"] = "зразок крові із Зимоключа (видано)" } },
    [8922] = { [1] = "Надприродний пристрій", [2] = "Я маю знайти спосіб поговорити з Антіоном Гармоном... точніше, з його привидом!\n\nЯ знаю одного інженера, який цікавиться надприродним. Він стверджує, що може створити машину, яка дозволить йому розмовляти з мертвими!\n\nКров, яку ти {стать:зібрав:зібрала}, призначалася йому. Відправляйся до Пристробляха та віддай це йому як плату за його послуги!", [3] = "Принесіть запечатаний контейнер з кров'ю Муксу Маношкрябу в Пристроблях, що в Танарісі.", [4] = "У тебе є щось для мене?", [5] = "Чудово! Вона в мене якраз закінчується!\n\nКажеш, тебе Деліана прислала?", ["en"] = "A Supernatural Device", ["tasks"] = { ["Sealed Blood Container"] = "запечатаний контейнер з кров'ю", ["Sealed Blood Container (Provided)"] = "запечатаний контейнер з кров'ю (видано)" } },
    [8926] = { [1] = "Гідна винагорода", [2] = "Ти {стать:дотримав:дотримала} слова і {стать:приніс:принесла} пристрій Мукса. І якщо я хочу, щоб ти знову {стать:виручив:виручила} мене — винагорода має бути відповідною. Принеси мені пояс і рукавички, які хочеш оновити. Обіцяю, ті, які я дам тобі натомість, будуть набагато кращими.", [3] = "Принесіть пояс дикого серця та рукавички дикого серця Деліані в Залізогарт.", [4] = "{стать:Готовий:Готова} обмінятись?", [5] = "Ти {стать:виконав:виконала} свою частину угоди, а я виконаю свою.\n\nТа пам'ятай, що найкращі частини обладунку все ще в мене, і я віддам їх, коли твоя робота буде закінчена.", ["en"] = "Just Compensation", ["tasks"] = { ["Wildheart Belt"] = "пояс дикого серця", ["Wildheart Belt (Provided)"] = "пояс дикого серця (видано)", ["Wildheart Gloves"] = "рукавички дикого серця", ["Wildheart Gloves (Provided)"] = "рукавички дикого серця (видано)" } },
