    [8936] = { [1] = "Гідна винагорода", [2] = "Ти {стать:дотримав:дотримала} слова і {стать:приніс:принесла} пристрій Мукса. І якщо я хочу, щоб ти знову {стать:виручив:виручила} мене — винагорода має бути відповідною. Принеси мені пояс і рукавиці, які хочеш оновити. Обіцяю, ті, які я дам тобі натомість, будуть набагато кращими.", [3] = "Принесіть пояс імли жаху та обмотки імли жаху Деліані в Залізогарт.", [4] = "{стать:Готовий:Готова} обмінятись?", [5] = "Ти {стать:виконав:виконала} свою частину угоди, а я виконаю свою.\n\nТа пам'ятай, що найкращі частини обладунку все ще в мене, і я віддам їх, коли твоя робота буде закінчена.", ["en"] = "Just Compensation", ["tasks"] = { ["Dreadmist Belt"] = "пояс імли жаху", ["Dreadmist Belt (Provided)"] = "пояс імли жаху (видано)", ["Dreadmist Wraps"] = "обмотки імли жаху", ["Dreadmist Wraps (Provided)"] = "обмотки імли жаху (видано)" } },
    [8937] = { [1] = "Гідна винагорода", [2] = "Ти {стать:дотримав:дотримала} слова і {стать:приніс:принесла} пристрій Мукса. І якщо я хочу, щоб ти знову {стать:виручив:виручила} мене — винагорода має бути відповідною. Принеси мені пояс і рукавиці, які хочеш оновити. Обіцяю, ті, які я дам тобі натомість, будуть набагато кращими.", [3] = "Принесіть пояс доблесті та рукавиці доблесті Деліані в Залізогарт.", [4] = "{стать:Готовий:Готова} обмінятись?", [5] = "Ти {стать:виконав:виконала} свою частину угоди, а я виконаю свою.\n\nТа пам'ятай, що найкращі частини обладунку все ще в мене, і я віддам їх, коли твоя робота буде закінчена.", ["en"] = "Just Compensation", ["tasks"] = { ["Belt of Valor"] = "пояс доблесті", ["Belt of Valor (Provided)"] = "пояс доблесті (видано)", ["Gauntlets of Valor"] = "рукавиці доблесті", ["Gauntlets of Valor (Provided)"] = "рукавиці доблесті (видано)" } },
    [8951] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Деліани та скажи їй, що Бодлі — її єдиний шанс знайти інші частини. Поговори з нею і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Деліани в Залізогарт з чоботами дикого серця, кілтом дикого серця та наплічниками дикого серця.", [4] = "Ти {стать:повернувся:повернулась}, {ім'я}. Розказуй все, про що {стать:дізнався:дізналась}. Та спершу поговорімо про твою винагороду.", [5] = "Я не можу повірити, що всі наші життя в небезпеці через якийсь дурний медальйон! І ти {стать:впевнений:впевнена}, що Антіон згадав Бодлі?\n\nЩо ж, ти свою справу {стать:зробив:зробила}, тому давай розберемось з твоєю винагородою.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Wildheart Boots"] = "чоботи дикого серця", ["Wildheart Boots (Provided)"] = "чоботи дикого серця (видано)", ["Wildheart Kilt"] = "кілт дикого серця", ["Wildheart Kilt (Provided)"] = "кілт дикого серця (видано)", ["Wildheart Spaulders"] = "наплічники дикого серця", ["Wildheart Spaulders (Provided)"] = "наплічники дикого серця (видано)" } },
    [8952] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Деліани та скажи їй, що Бодлі — її єдиний шанс знайти інші частини. Поговори з нею і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Деліани в Залізогарт з чоботами ловця звірів, штанами ловця звірів та напліччям ловця звірів.", [4] = "Ти {стать:повернувся:повернулась}, {ім'я}. Розказуй все, про що {стать:дізнався:дізналась}. Та спершу поговорімо про твою винагороду.", [5] = "Я не можу повірити, що всі наші життя в небезпеці через якийсь дурний медальйон! І ти {стать:впевнений:впевнена}, що Антіон згадав Бодлі?\n\nЩо ж, ти свою справу {стать:зробив:зробила}, тому давай розберемось з твоєю винагородою.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Beaststalker's Boots"] = "чоботи ловця звірів", ["Beaststalker's Boots (Provided)"] = "чоботи ловця звірів (видано)", ["Beaststalker's Mantle"] = "напліччя ловця звірів", ["Beaststalker's Mantle (Provided)"] = "напліччя ловця звірів (видано)", ["Beaststalker's Pants"] = "штани ловця звірів", ["Beaststalker's Pants (Provided)"] = "штани ловця звірів (видано)" } },
    [8954] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Деліани та скажи їй, що Бодлі — її єдиний шанс знайти інші частини. Поговори з нею і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Деліани в Залізогарт зі світлокованими чоботами, світлокованими поножами та світлокованими наплічниками.", [4] = "Ти {стать:повернувся:повернулась}, {ім'я}. Розказуй все, про що {стать:дізнався:дізналась}. Та спершу поговорімо про твою винагороду.", [5] = "Я не можу повірити, що всі наші життя в небезпеці через якийсь дурний медальйон! І ти {стать:впевнений:впевнена}, що Антіон згадав Бодлі?\n\nЩо ж, ти свою справу {стать:зробив:зробила}, тому давай розберемось з твоєю винагородою.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Lightforge Boots"] = "світлоковані чоботи", ["Lightforge Boots (Provided)"] = "світлоковані чоботи (видано)", ["Lightforge Legplates"] = "світлоковані поножі", ["Lightforge Legplates (Provided)"] = "світлоковані поножі (видано)", ["Lightforge Spaulders"] = "світлоковані наплічники", ["Lightforge Spaulders (Provided)"] = "світлоковані наплічники (видано)" } },
    [8955] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Деліани та скажи їй, що Бодлі — її єдиний шанс знайти інші частини. Поговори з нею і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Деліани в Залізогарт із сандалями відданості, спідницею відданості та напліччям відданості.", [4] = "Ти {стать:повернувся:повернулась}, {ім'я}. Розказуй все, про що {стать:дізнався:дізналась}. Та спершу поговорімо про твою винагороду.", [5] = "Я не можу повірити, що всі наші життя в небезпеці через якийсь дурний медальйон! І ти {стать:впевнений:впевнена}, що Антіон згадав Бодлі?\n\nЩо ж, ти свою справу {стать:зробив:зробила}, тому давай розберемось з твоєю винагородою.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Devout Mantle"] = "напліччя відданості", ["Devout Mantle (Provided)"] = "напліччя відданості (видано)", ["Devout Sandals"] = "сандалі відданості", ["Devout Sandals (Provided)"] = "сандалі відданості (видано)", ["Devout Skirt"] = "спідниця відданості", ["Devout Skirt (Provided)"] = "спідниця відданості (видано)" } },
    [8956] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Деліани та скажи їй, що Бодлі — її єдиний шанс знайти інші частини. Поговори з нею і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Деліани в Залізогарт з чоботами тіньового ремесла, штанами тіньового ремесла та наплічниками тіньового ремесла.", [4] = "Ти {стать:повернувся:повернулась}, {ім'я}. Розказуй все, про що {стать:дізнався:дізналась}. Та спершу поговорімо про твою винагороду.", [5] = "Я не можу повірити, що всі наші життя в небезпеці через якийсь дурний медальйон! І ти {стать:впевнений:впевнена}, що Антіон згадав Бодлі?\n\nЩо ж, ти свою справу {стать:зробив:зробила}, тому давай розберемось з твоєю винагородою.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Shadowcraft Boots"] = "чоботи тіньового ремесла", ["Shadowcraft Boots (Provided)"] = "чоботи тіньового ремесла (видано)", ["Shadowcraft Pants"] = "штани тіньового ремесла", ["Shadowcraft Pants (Provided)"] = "штани тіньового ремесла (видано)", ["Shadowcraft Spaulders"] = "наплічники тіньового ремесла", ["Shadowcraft Spaulders (Provided)"] = "наплічники тіньового ремесла (видано)" } },
    [8958] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Деліани та скажи їй, що Бодлі — її єдиний шанс знайти інші частини. Поговори з нею і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Деліани в Залізогарт із сандалями імли жаху, поножами імли жаху та напліччям імли жаху.", [4] = "Ти {стать:повернувся:повернулась}, {ім'я}. Розказуй все, про що {стать:дізнався:дізналась}. Та спершу поговорімо про твою винагороду.", [5] = "Я не можу повірити, що всі наші життя в небезпеці через якийсь дурний медальйон! І ти {стать:впевнений:впевнена}, що Антіон згадав Бодлі?\n\nЩо ж, ти свою справу {стать:зробив:зробила}, тому давай розберемось з твоєю винагородою.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Dreadmist Leggings"] = "поножі імли жаху", ["Dreadmist Leggings (Provided)"] = "поножі імли жаху (видано)", ["Dreadmist Mantle"] = "напліччя імли жаху", ["Dreadmist Mantle (Provided)"] = "напліччя імли жаху (видано)", ["Dreadmist Sandals"] = "сандалі імли жаху", ["Dreadmist Sandals (Provided)"] = "сандалі імли жаху (видано)" } },
    [8959] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Деліани та скажи їй, що Бодлі — її єдиний шанс знайти інші частини. Поговори з нею і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Деліани в Залізогарт з чоботами доблесті, поножами доблесті та наплічниками доблесті.", [4] = "Ти {стать:повернувся:повернулась}, {ім'я}. Розказуй все, про що {стать:дізнався:дізналась}. Та спершу поговорімо про твою винагороду.", [5] = "Я не можу повірити, що всі наші життя в небезпеці через якийсь дурний медальйон! І ти {стать:впевнений:впевнена}, що Антіон згадав Бодлі?\n\nЩо ж, ти свою справу {стать:зробив:зробила}, тому давай розберемось з твоєю винагородою.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Boots of Valor"] = "чоботи доблесті", ["Boots of Valor (Provided)"] = "чоботи доблесті (видано)", ["Legplates of Valor"] = "поножі доблесті", ["Legplates of Valor (Provided)"] = "поножі доблесті (видано)", ["Spaulders of Valor"] = "наплічники доблесті", ["Spaulders of Valor (Provided)"] = "наплічники доблесті (видано)" } },
    [8977] = { [1] = "Повернення до Деліани", [2] = "Приємно було попрацювати з тобою, {ім'я}. Ось готовий пристрій.\n\nСподіваюся, він допоможе у твоїй справі. Так, і якщо ти не проти, розповідай усім про мене. Мені нові клієнти не завадять!", [3] = "Принесіть міжвимірний шукач привидів Деліані в Залізогарт.", [4] = "Вже {стать:повернувся:повернулась}?", [5] = "Чудово! Гарна робота, {ім'я}. Я не дуже довіряю гоблінським пристроям, та в мене не залишається вибору.", ["en"] = "Return to Deliana", ["tasks"] = { ["Extra-Dimensional Ghost Revealer"] = "міжвимірний шукач привидів", ["Extra-Dimensional Ghost Revealer (Provided)"] = "міжвимірний шукач привидів (видано)" } },
    [8993] = { [1] = "Підношення дарів", [4] = "Ти тут для того, щоб піднести дар кохання та обожнювання своєму улюбленому лідеру?", [5] = "Чудово! Чудово! Я покладу це до купи інших подарунків.\n\nЯ не очікував, що їх буде настільки багато! Мабуть, ви справді любите своїх лідерів.\n\nА тепер, дозволь мені додати іще один подарунок до рахунку...", ["en"] = "Gift Giving", ["tasks"] = { ["Alliance Gift Collection"] = "колекція дарів Альянсу", ["Alliance Gift Collection (Provided)"] = "колекція дарів Альянсу (видано)" } },
    [8997] = { [1] = "Повернення на початок", [2] = "Схоже, що настав час прощатися, {стать:друже:подруго}. Але я завжди буду тут, якщо ти захочеш поговорити зі мною. Приходь, коли хочеш. Можливо, поки будеш чекати тут на друзів для походу до Чорноскельного шпиля.\n\nВсе, йди, поки я не розплакався. Повертайся до Деліани в Залізогарт і розкажи їй про все, що сталося.", [3] = "Поговоріть з Деліаною на Високому троні в Залізогарті.", [5] = "Рада бачити, що тобі вдалось повернутись до мене, {ім'я}. Виглядаєш чудово, хіба що трохи {стать:потріпаний:потріпана}.\n\nДавай, розказуй мені про все, що з тобою сталося.", ["en"] = "Back to the Beginning" },
    [8999] = { [1] = "Найкраще — наостанок", [2] = "Це дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Тепер, можливо, я зможу спати, не боячись, чи прокинусь вранці.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись.", [3] = "Віддайте Деліані капюшон дикого серця та жилет дикого серця.", [4] = "Як ми й домовлялись, ти {стать:готовий:готова} віддати частини свого обладунку дикого серця в обмін на новий капюшон та жилет лютого серця?", [5] = "Я сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки та що вони довго служитимуть тобі.", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Wildheart Cowl"] = "капюшон дикого серця", ["Wildheart Cowl (Provided)"] = "капюшон дикого серця (видано)", ["Wildheart Vest"] = "жилет дикого серця", ["Wildheart Vest (Provided)"] = "жилет дикого серця (видано)" } },
    [9] = { [1] = "Убивчі поля", [2] = "Поглянь, на що перетворилося це місце! Колись на цих землях мешкали чесні селяни. Але прокляті злодії вижили звідси їх усіх. Тільки не мене! Однак, здається, поля захоплені жнивальними доглядачами.\n\nЯкщо ти {стать:готовий:готова} попрацювати, я попросив би тебе піти туди та вбити двадцять жнивальних доглядачів. Повертайся по оплату, коли все буде зроблено. Як завершиш з моїм полем — зачисть і поля моїх сусідів.", [3] = "Вбийте 20 жнивальних доглядачів на прохання фермера Салдена.", [4] = "О, я бачу, ти вже {стать:повернувся:повернулася}! Сподіваюся, ти наполегливо {стать:попрацював:попрацювала}, зачищаючи наші поля від жнивальних доглядачів. Уже {стать:вбив:вбила} двадцять?", [5] = "Відмінна робота, {стать:друже:подруго}. Ти добре {стать:відпрацював:відпрацювала} свою плату. Хтозна, може, Західний край знов розквітне.", ["en"] = "The Killing Fields", ["tasks"] = { ["Harvest Watcher slain"] = "жнивальний доглядач: убито" } },
    [90] = { [1] = "Пряний кебаб з вовчатини", [2] = "Пряний кебаб з вовчатини — улюблена страва в нашому домі! Звичайно, я можу його приготувати, але спочатку мені знадобляться інгредієнти. Принеси мені 10 пісних вовчих боків, а також трохи штормовійських приправ. Тут у лісі багато вовків, тому знайти м'ясо не буде проблемою. Щодо приправ, звернись до Феліції Ґамп у її магазин квітів у районі каналів Штормовію.", [3] = "Зберіть 10 пісних вовчих боків та штормовійську приправу та поверніться до шеф-кухаря Ґруала в Темноділ.", [4] = "Ти вже {стать:знайшов:знайшла} 10 пісних вовчих боків? А як щодо трав від Феліції зі Шторомовію?", [5] = "Дуже гарна робота, {ім'я}! Насолоджуйся делікатесом, відомим як пряний кебаб з вовчатини!", ["en"] = "Seasoned Wolf Kabobs", ["tasks"] = { ["Lean Wolf Flank"] = "пісний вовчий бік", ["Lean Wolf Flank (Provided)"] = "пісний вовчий бік (видано)", ["Stormwind Seasoning Herbs"] = "штормовійська приправа", ["Stormwind Seasoning Herbs (Provided)"] = "штормовійська приправа (видано)" } },
    [9000] = { [1] = "Найкраще — наостанок", [2] = "Це дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Тепер, можливо, я зможу спати, не боячись, чи прокинусь вранці.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись.", [3] = "Віддайте Деліані шапку ловця звірів та мундир ловця звірів.", [4] = "Як ми й домовлялись, ти {стать:готовий:готова} віддати частини свого обладунку ловця звірів в обмін на нову шапку та мундир володаря звірів?", [5] = "Я сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки та що вони довго служитимуть тобі.", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Beaststalker's Cap"] = "шапка ловця звірів", ["Beaststalker's Cap (Provided)"] = "шапка ловця звірів (видано)", ["Beaststalker's Tunic"] = "мундир ловця звірів", ["Beaststalker's Tunic (Provided)"] = "мундир ловця звірів (видано)" } },
    [9001] = { [1] = "Найкраще — наостанок", [2] = "Це дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Тепер, можливо, я зможу спати, не боячись, чи прокинусь вранці.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись.", [3] = "Віддайте Деліані корону магістра та мантію магістра.", [4] = "Як ми й домовлялись, ти {стать:готовий:готова} віддати частини свого обладунку магістра в обмін на нову корону та мантію чаклуна?", [5] = "Я сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки та що вони довго служитимуть тобі.", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Magister's Crown"] = "корона магістра", ["Magister's Crown (Provided)"] = "корона магістра (видано)", ["Magister's Robes"] = "мантія магістра", ["Magister's Robes (Provided)"] = "мантія магістра (видано)" } },
    [9002] = { [1] = "Найкраще — наостанок", [2] = "Це дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Тепер, можливо, я зможу спати, не боячись, чи прокинусь вранці.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись.", [3] = "Віддайте Деліані світлокований шолом та світлоковану кірасу.", [4] = "Як ми й домовлялись, ти {стать:готовий:готова} віддати частини свого світлокованого обладунку в обмін на новий духокований шолом та кірасу?", [5] = "Я сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки та що вони довго служитимуть тобі.", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Lightforge Breastplate"] = "світлокована кіраса", ["Lightforge Breastplate (Provided)"] = "світлокована кіраса (видано)", ["Lightforge Helm"] = "світлокований шолом", ["Lightforge Helm (Provided)"] = "світлокований шолом (видано)" } },
    [9003] = { [1] = "Найкраще — наостанок", [2] = "Це дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Тепер, можливо, я зможу спати, не боячись, чи прокинусь вранці.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись.", [3] = "Віддайте Деліані корону відданості та мантію відданості.", [4] = "Як ми й домовлялись, ти {стать:готовий:готова} віддати частини свого обладунку відданості в обмін на нову корону та мантію доброчесності?", [5] = "Я сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки та що вони довго служитимуть тобі.", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Devout Crown"] = "корона відданості", ["Devout Crown (Provided)"] = "корона відданості (видано)", ["Devout Robe"] = "мантія відданості", ["Devout Robe (Provided)"] = "мантія відданості (видано)" } },
    [9004] = { [1] = "Найкраще — наостанок", [2] = "Це дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Тепер, можливо, я зможу спати, не боячись, чи прокинусь вранці.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись.", [3] = "Віддайте Деліані шапку тіньового ремесла та мундир тіньового ремесла.", [4] = "Як ми й домовлялись, ти {стать:готовий:готова} віддати частини свого обладунку тіньового ремесла в обмін на нову шапку та мундир покрову темряви?", [5] = "Я сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки та що вони довго служитимуть тобі.", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Shadowcraft Cap"] = "шапка тіньового ремесла", ["Shadowcraft Cap (Provided)"] = "шапка тіньового ремесла (видано)", ["Shadowcraft Tunic"] = "мундир тіньового ремесла", ["Shadowcraft Tunic (Provided)"] = "мундир тіньового ремесла (видано)" } },
    [9005] = { [1] = "Найкраще — наостанок", [2] = "Це дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Тепер, можливо, я зможу спати, не боячись, чи прокинусь вранці.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись.", [3] = "Віддайте Деліані маску імли жаху та мантію імли жаху.", [4] = "Як ми й домовлялись, ти {стать:готовий:готова} віддати частини свого обладунку імли жаху в обмін на нову маску та мантію імли смерті?", [5] = "Я сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки та що вони довго служитимуть тобі.", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Dreadmist Mask"] = "маска імли жаху", ["Dreadmist Mask (Provided)"] = "маска імли жаху (видано)", ["Dreadmist Robe"] = "мантія імли жаху", ["Dreadmist Robe (Provided)"] = "мантія імли жаху (видано)" } },
    [9006] = { [1] = "Найкраще — наостанок", [2] = "Це дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Тепер, можливо, я зможу спати, не боячись, чи прокинусь вранці.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись.", [3] = "Віддайте Деліані шолом доблесті та нагрудник доблесті.", [4] = "Як ми й домовлялись, ти {стать:готовий:готова} віддати частини свого обладунку доблесті в обмін на новий шолом та кірасу героїзму?", [5] = "Я сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки та що вони довго служитимуть тобі.", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Breastplate of Valor"] = "нагрудник доблесті", ["Breastplate of Valor (Provided)"] = "нагрудник доблесті (видано)", ["Helm of Valor"] = "шолом доблесті", ["Helm of Valor (Provided)"] = "шолом доблесті (видано)" } },
    [9030] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Деліани та скажи їй, що Бодлі — її єдиний шанс знайти інші частини.\n\nА я, нарешті, буду спочивати з миром. Бажаю тобі вдачі — вона тобі знадобиться!", [3] = "Поговоріть з Деліаною в Залізогарті.", ["en"] = "Anthion's Parting Words" },
    [90567] = { [1] = "Незнайома брутальність", [2] = "<Ви знайшли на лабораторному столі флакон з неприємною, в'язкою рідиною. Він був оточений різними інгредієнтами, які були ретельно відміряні та нарізані на ретельні порції. Хоча трави неможливо ідентифікувати, поруч лежало одне неушкоджене та знебарвлене серце звіра.\n\nАлхіміки в Дарнасі можуть мати уявлення про те, як скористатися будь-якими відновлювальними властивостями, які можуть бути присутніми в зіллі. Вам також слід принести їм кілька квітів, щоб не вбігти до магазину лише з купою сердець.>", [3] = "Зберіть Знебарвлені Серця Звірів та Кровоточачі Серця з Чумних Земель. Принесіть їх разом із Неправильно використаним Цілющим Зіллям зацікавленому алхіміку в Дарнасі.", [4] = "Ішну-алах, мандрівнику. Ти прийшов практикувати мистецтво алхімії чи є ще чимось, з чим я можу тобі допомогти?", [5] = "Я майже підозрював таке, невже ви не могли б повірити, що ви не перший, хто показав мені саме це одкровення? Якби наслідки не були такими жахливими, я б припустив, що це складний розіграш на мій рахунок.\n\nВивчення наслідків Чумних земель, хоча часто й захоплююче, не є практичним через їхню віддаленість від дому. Тим не менш, я досяг прогресу з попередніми зразками, які мені надали, і хотів би поділитися своїми знахідками з вами.\n\nБудь ласка, пам’ятайте про мене, якщо знайдете більше зразків.", ["en"] = "Unfamiliar Foulness" },
    [9094] = { [1] = "Рукавиці Сріблястого Світанку", [4] = "Якщо принесеш мені тридцять некротичних рун, я запропоную рукавиці на твій вибір. Вони стануть у пригоді в боротьбі зі Скарою.", [5] = "Гарна робота, {ім'я}. На знак подяки за твої зусилля обери собі рукавиці.", ["en"] = "Argent Dawn Gloves", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [91] = { [1] = "Закон Соломона", [2] = "Вороги Штормовію оселились у східних передгір'ях Багрянокряжжя. За допомогою арканічної магії цей негідник на ім'я Морґант сіє жах та страждання в нашому місті.\n\nЗараз Морґант контролює Тінешкурих гнолів, і вони виконують його накази. Згідно із законом Приозер'я, пособництво злочинцям Королівства карається смертю.\n\nЦі мерзенні гноли мають бути знищені!\n\nПринеси мені 10 підвісок Тінешкурих, і отримаєш винагороду.", [3] = "Принесіть 10 підвісок Тінешкурих судовому приставу Конахеру в ратушу Приозер'я.", [4] = "Принеси мені 10 підвісок Тінешкурих і отримаєш винагороду.", [5] = "Суд Приозер'я високо цінить твою відданість правосуддю, {ім'я:к}. Забезпечуючи дотримання законів Королівства, ти допомагаєш збереженню справедливості в наших землях.", ["en"] = "Solomon's Law", ["tasks"] = { ["Shadowhide Pendant"] = "підвіска Тінешкурих", ["Shadowhide Pendant (Provided)"] = "підвіска Тінешкурих (видано)" } },
    [916] = { [1] = "Отрута павутиннолісих", [2] = "Я прийшов до Тінистої долини спостерігати за павутиннолісими павуками, що живуть у печері Тіненитки. Вони родичі набагато меншого виду павуків, і я вірю, що Світове Дерево мало на них значний вплив. Я б хотів зразки для вивчення, щоб підтвердити моє припущення.\n\nДля початку мені потрібна їхня отрута. Збери отруйні залози павутиннолісих павуків у та навколо печери Тіненитки на півночі. Тоді я зможу порівняти їх на предмет схожості з отрутою їхньої меншої братії.", [3] = "Принесіть 10 отруйних залоз павутиннолісих Ґілшалану Вітроступові в Альдрассіль.", [4] = "Чи ти {стать:зібрав:зібрала} отруйні залози, {Ім'я}?", [5] = "Дякую тобі, {Ім'я}. Коли я повернуся до Дарнаса, я порівняю отруту з цих залоз із отрутою інших павуків. Я вірю, що в неї будуть властивості, пов'язані з недавнім ростом нашого нового Світового Дерева.", ["en"] = "Webwood Venom", ["tasks"] = { ["Webwood Venom Sac"] = "отруйна залоза павутиннолісих", ["Webwood Venom Sac (Provided)"] = "отруйна залоза павутиннолісих (видано)" } },
    [91740] = { [1] = "Голова Крокі", [2] = "Цей мурлок, безсумнівно, вже деякий час тероризує місцеві дороги. Ви підозрюєте, що сусідні вартові захочуть дізнатися про його загибель.", [3] = "Доставте голову Крокі до Мерелл Росс у Прикордонну вежу.", ["en"] = "Croaky's Head", ["tasks"] = { ["Croaky's Head"] = "Голова Крокі", ["Croaky's Head (Provided)"] = "Голова Крокі (видано)" } },
    [91746] = { [1] = "Голова Елмпау", [2] = "Трофей слугує вражаючим нагадуванням про вашу перемогу над Елмпо. Місцевому мисливцю чи шкуродеру може бути цікаво почути цю історію.", [3] = "Доставте голову Елмпау Гелені Пелцкіннер поблизу Голдшира.", ["en"] = "Elmpaw's Head", ["tasks"] = { ["Elmpaw's Head"] = "Голова Елмпау", ["Elmpaw's Head (Provided)"] = "Голова Елмпау (видано)" } },
    [918] = { [1] = "Насіння деревників", [2] = "Деревники Тельдрассіля - елементалі природи. Певним чином вони відображають природний порядок флори та фауни нашого великого дерева.\n\nТому мене тривожить, що вони так розлютилися.\n\nЯ вважаю, що це якось пов'язане із землею. Я працював з різними методами підживлення рослин і хотів би спробувати їх на насінні деревників. Будь ласка, збери для мене насіння з деревників, що ходять навколо озера Аль'Амет.", [3] = "Принесіть 8 насінин деревників Деналану біля озера Аль'Амет.", [4] = "Ти {стать:приніс:принесла} насіння? Я горю бажанням його посадити.", [5] = "Тобі вдалося. Це добре!\n\nЯ посаджу насіння в спеціально підготовлений мною ґрунт. Я вірю, що насіння проросте у більш спокійних деревників. Можливо, згодом ти побачиш результати!", ["en"] = "Timberling Seeds", ["tasks"] = { ["Timberling Seed"] = "насіння деревника", ["Timberling Seed (Provided)"] = "насіння деревника (видано)" } },
    [919] = { [1] = "Паростки деревників", [2] = "Маленькі деревники проростають навколо вод озера Аль'Амет. Боюся, що їм допомагати вже пізно - нам слід спробувати прибрати їх з землі, перш ніж вони виростуть досить великими, щоб стати для нас проблемою.\n\nЯкщо побачиш паростки деревників, блукаючи навколо озера, будь ласка, візьми їх. Допоможи зберегти нашу землю в чистоті!", [3] = "Принесіть 12 паростків деревників Деналану біля озера Аль'Амет.", [4] = "Привіт, {Ім'я}. Ти {стать:знайшов:знайшла} паростки біля води?", [5] = "Це багато! Боюся, вони розростаються з надзвичайною швидкістю. Сподіваюся, що зможу розгадати загадку того, що їх вражає.\n\nДякую за допомогу, {Ім'я}. Завдяки твоїм зусиллям земля стала чистішою.", ["en"] = "Timberling Sprouts", ["tasks"] = { ["Timberling Sprout"] = "паросток деревника", ["Timberling Sprout (Provided)"] = "паросток деревника (видано)" } },
    [92] = { [1] = "Багрянокрязький гуляш", [2] = "Я б з радістю приготувала для тебе багрянокрязький гуляш. Але є невелика проблема. Під час нещодавнього вторгнення орків мені довелося годувати цілу штормовійську бригаду і всі мої запаси закінчились. Але якщо ти зможеш знайти для мене необхідні інгредієнти — я з радістю приготую для тебе кілька порцій.\n\nПросто принеси мені п'ять шматків жорсткого м'яса кондора, п'ять рил великих іклоштриків та п'ять порцій хрумкого павучого м'яса.", [3] = "Шеф-кухарка Бренна з Приозер'я просить вас принести їй п'ять шматків жорсткого м'яса кондора, п'ять рил великих іклоштриків та п'ять порцій хрумкого павучого м'яса.", [4] = "Мені все ще потрібні п'ять шматків жорсткого м'яса кондора, п'ять рил великих іклоштриків та п'ять порцій хрумкого павучого м'яса.", [5] = "Молодець, {ім'я}. Ще й такі гарні шматки! А ось і моя коронна страва — багрянокрязький гуляш!", ["en"] = "Redridge Goulash", ["tasks"] = { ["Crisp Spider Meat"] = "хрумке павуче м'ясо", ["Crisp Spider Meat (Provided)"] = "хрумке павуче м'ясо (видано)", ["Great Goretusk Snout"] = "рило великого іклоштрика", ["Great Goretusk Snout (Provided)"] = "рило великого іклоштрика (видано)", ["Tough Condor Meat"] = "жорстке м'ясо кондора", ["Tough Condor Meat (Provided)"] = "жорстке м'ясо кондора (видано)" } },
    [921] = { [1] = "Вінець Землі", [2] = "Настав час тобі знайти своє призначення, {Ім'я}. Але перед тим, як ти будеш {стать:готовий:готова} вийти у великий світ поза нашими чарівними лісами, тобі ще багато потрібно вивчити про нашу недавню історію.\n\nБагато чого змінилося для нашого народу після битви при горі Гіджал. Нордрассіль тепер є бляклою тінню того, чим він колись був. Уся його сила була використана на подолання Архімонда та вигнання Палаючого Легіону...\n\nДля тебе є завдання. Йди до місячного колодязя на північ від Альдрассіля та принеси мені фіал, наповнений його водою.", [3] = "Наповніть кришталевий фіал і принесіть його Тенарону Штормохапу на вершині Альдрассілю.", [4] = "Місячні колодязі бережуть воду з Колодязя Вічності, древнього джерела магії, яке призвело до стількох жахіть у нашому світі.\n\nДруїди користуються її властивостями, а вартові шанують колодязі як святилища Елуни, але чародійство — заборонене.", [5] = "Ось ти й {стать:почув:почула} першу частину розповіді про часи після битви при горі Гіджал. Залишається ще багато чого розповісти, і завдання, яке ти тут {стать:розпочав:розпочала}, супроводжуватиме тебе впродовж усієї подорожі Тельдрассілем аж до Дарнаса.", ["en"] = "Crown of the Earth", ["tasks"] = { ["Filled Crystal Phial"] = "наповнений кришталевий фіал", ["Filled Crystal Phial (Provided)"] = "наповнений кришталевий фіал (видано)" } },
    [92109] = { [1] = "Мій перший набір для алхімії", [2] = "Емм... «Привіт, <пан/панночка>. Я не маю права розмовляти з незнайомцями, але... Гей, для чого ці блискучі пляшечки стирчать з твого рюкзака? Ти алхімік? Це так круто!\n\nКоли я виросту, я теж хочу бути алхіміком. Тато не дозволяє мені гратися з жодною з його трав; занадто небезпечно, каже він.\n\nНу, я хочу почати вчитися зараз. Чи не міг би ти, будь ласка, дістати мені якісь матеріали?»", ["en"] = "My First Alchemy Set", ["tasks"] = { ["Empty Vial"] = "порожній фіал", ["Peacebloom"] = "мироквіт", ["Silverleaf"] = "срібнолист" } },
    [92110] = { [1] = "Моє перше справжнє зілля", [2] = "Ого, моє перше зілля! Чи знаєте ви, що змішування цих двох трав разом змінює колір зілля на яскраво-червоний, коли ви тільки починали?\n\nЦе було весело, але змішування кількох квітів не схоже на ту алхімію, яку використовує тато. Він також використовує інші інгредієнти.\n\nЯ не знаю, що ще використовувати, тож давайте спробуємо перше, що спаде на думку! Подивимося... можливо, очі мурлоків? Звучить так огидно, але б'юся об заклад, щось станеться.", ["en"] = "My First Real Potion", ["tasks"] = { ["Murloc Eye"] = "око мурлока" } },
    [922] = { [1] = "Релліан Зеленоватрий", [2] = "{Ім'я}, не {стать:міг би:могла б} ти взяти одну з принесених тобою насінин та передати її моєму другові, Релліану Зеленоватрому? Він друїд з Дарнаса, і, коли ми востаннє розмовляли, він проявив чималий інтерес до моєї роботи з деревниками. У нього були цікаві ідеї, тож він буде вдячний за цей зразок насіння для подальшої роботи.\n\nДякую, {Ім'я}. Ти мені дуже {стать:допоміг:допомогла}. Я сподіваюся, що колись ти побачиш плід моїх праць.\n\nРелліана ти зможеш знайти на стежинах Кенарійського Анклаву в Дарнасі.", [3] = "Принесіть насіння деревника Релліану Зеленоватрому в Дарнас.", [4] = "Привіт...\n\nЧим я можу допомогти?", [5] = "Ах, насіння деревника? Я хотів спробувати виростити одного з них, щоб допомогти Деналану з його дослідами.\n\nАле, боюсь, я виявив, що багатьох деревників захопила порча. Як мені відомо, це спадково передається у насінні цих істот, і моїх сил недостатньо, щоб їх очистити.\n\nДеналан дуже добре справляється з усім, що росте. Думаю, він здатен знайти ліки для майбутніх деревників. Він може бути їхньою єдиною надією.", ["en"] = "Rellian Greenspyre", ["tasks"] = { ["Timberling Seed"] = "насіння деревника", ["Timberling Seed (Provided)"] = "насіння деревника (видано)" } },
    [923] = { [1] = "Пухлини", [2] = "Деревників дедалі більше вражає якась порча. Ми намагаємося знайти джерело, але зараз, щоб зберегти Телдрассіль, ми повинні позбутися деревників, яким уже пізно допомогти. Особливо порча вразила тих, що ходять довкола Джерельного озера на півночі Тельдрассіля. Їх треба знищити!\n\nЗроби це і збери вкриті мохом пухлини, що ростуть на них. Принеси мені пухлини, щоб ми могли їх спалити.", [3] = "Принесіть 5 вкритих мохом пухлин Релліану Зеленоватрому в Дарнасі.", [4] = "Ти вже {стать:був:була} на Джерельному озері, {Ім'я}? {стать:Вполював:вполювала} тамтешніх деревників?", [5] = "Чудово! Ці пухлини є симптомом ураження деревників хворобою. Вони наповнені отрутою, яку ми повинні очистити з нашої нової землі.\n\nЯ знищу ці пухлини. Дякую, {Ім'я}.", ["en"] = "Tumors", ["tasks"] = { ["Mossy Tumor"] = "вкрита мохом пухлина", ["Mossy Tumor (Provided)"] = "вкрита мохом пухлина (видано)" } },
    [92415] = { [1] = "Пам'ятай, що я тебе кохаю", [2] = "<Рваний і заплямований пакунок пергаменту ледве вцілів на втоптаній нежиттю землі кладовища. У ньому згадується зникла дитина з родини Серцеткарів. Можливо, сирота-наглядачка у Штормовії знатиме більше.>", [3] = "Принесіть Закривавленого Листа сирітці-матроні Найтінгейл у Штормовії.", ["en"] = "Remember That I Love You", ["tasks"] = { ["Blood-Stained Letter"] = "Лист, заплямований кров’ю", ["Blood-Stained Letter (Provided)"] = "Лист, заплямований кров’ю (видано)" } },
    [92456] = { [1] = "Зелений зразок", [2] = "Якщо вже надумалося мене турбувати, то хоч принеси якусь користь. Мені треба виконати одне доручення.\n\nЯк на місто магів, Даларан виявляє дивовижний інтерес до ботаніки. Кірін-Тор тримається осторонь, але мені дуже хотілося б отримати зразок їхніх рослин, насичених маною.\n\nВочевидь, тобі не звикати бувати там, де тобі не раді. Можливо, знайдеш спосіб потрапити в місто. Якщо вдасться, принеси мені щось із того, що росте в їхньому центральному саду.", ["en"] = "A Green Sample", ["tasks"] = { ["Fel Infused Blossom"] = "Квітка, насичена Скверною" } },
    [92479] = { [1] = "Намальований лист", [2] = "Мене попросили звернути на це вашу увагу, щойно ви повернетеся з таборів кобольдів, {ім'я}. Схоже, це лист, запечатаний клеймом Тордріна Стемблейда, нашого місцевого тренера мисливців. Знайдіть хвилинку, щоб прочитати його, перш ніж займатися будь-якими іншими справами тут, в Абатстві.", [3] = "Прочитайте Намальованого Листа та поговоріть із Тордріном Стемблейдом у Нортширському Абатстві.", ["en"] = "A Scribbled Letter", ["tasks"] = { ["Scribbled Letter"] = "Намальований лист", ["Scribbled Letter (Provided)"] = "Намальований лист (видано)" } },
    [92489] = { [1] = "Незборима сила", [2] = "Кірін-Тор здавна був союзником Альянсу. Після того як верховний демон Архімонд зруйнував їхнє місто, колись горде місто магів замкнулося в собі й стало недовірливим до чужинців.\n\nОстанніми роками вони почали відбудову, прагнучи повернути Даларану колишню славу. Однак, за повідомленнями, їм важко стримувати спалахи некерованої арканічної енергії.\n\nМи маємо допомогти їм подолати ці напади, інакше втратимо одного з наймогутніших союзників.", ["en"] = "Power Overwhelming", ["tasks"] = { ["Arcanic Enigma"] = "Арканічна загадка", ["Arcanic Enigma slain"] = "Арканічна загадка: убито" } },
    [92596] = { [1] = "Вищий порядок", [2] = "Аура арканної енергії, яка тебе оточує, сильна, навіть попри те, що ти не посвячений як маг. Я цілком впевнений, що ти станеш здібним шукачем пригод, і твій зв'язок з нашою давньою магією завжди буде для тебе лише благом, навіть якщо ти ніколи не вимовиш жодного слова сили під час заклинань.\n\nХодімо, давайте сядемо та поговоримо трохи за моїм наказом про природу арканної енергії тут, на Зефрасі, та про тяжке становище нашого народу.", [3] = "Сядьте та поговоріть з Ратхірілом Санлансом.", [5] = "Місія Високого Ордену життєво важлива для виживання нашого народу. Ми з найвищою пошаною ставимося до наших стихійних благодійників, але мусимо дивитися правді у вічі: їх більше немає, і тепер ми самі по собі.\r\n\r\nМіж внутрішніми загрозами на кшталт Ал'Акету та невизначеністю нашої безпеки на цьому плані наша доля — як нащадків Високородних із прабатьківського дому Елдре'Талас — скористатися своїми дарами, щоб шен'дорай знову могли стояти на власних ногах.", ["en"] = "The High Order", ["tasks"] = { ["Listen to Rathiril Sunlance"] = "Слухайте Ратхіріла Санленса" } },
    [92597] = { [1] = "Читання лей-ліній", [2] = "Тут, на елементальному плані, ми черпаємо значну частину нашої арканної сили з лей-ліній, які досі проходять крізь землю під нашими ногами. Останнім часом ці лей-лінії почали пронизувати поверхню, надаючи нам більш прямий і потужний доступ до цих прихованих арканних енергій.\n\nІдіть до стоячих каменів на північному сході. Там є лей-лінія. Доторкніться до свого первородного права та втягніть його енергію.", [3] = "Використайте свою расову здатність «Читання лей-ліній» на лей-лінії в Тендал-Гроув.", [5] = "Відчуваєш? Так? Добре! Ти зробив перші кроки. Завдяки своїм здібностям ти зможеш у багатьох місцях черпати приховану магічну енергію. Це дасть тобі безліч переваг — одні вагомі, інші ледь помітні. Не дізнаєшся, доки не спробуєш. Але в цьому й найкраща частина дару... робити невідоме відомим.\r\n\r\nЯкщо ми хочемо пережити ці лихі часи, мусимо бути непохитними у своїх пошуках знань... і сили.", ["en"] = "Reading the Ley Lines", ["tasks"] = { ["Use your Read Ley Line ability near the Thendal Grove Ley Line"] = "Використайте свою здатність «Читати лей-лінію» поблизу лей-лінії Тендал Гроув." } },
    [9262] = { [1] = "Розвідка Скари в Дарнасі", [2] = "Скара розташувала свій табір прямо біля нашого порогу. Ми не можемо сидіти склавши руки! Чи встанеш ти на захист Дарнаса від цих проклятих загарбників?\n\nЗзовні ми побачили дивні рунічні кола, що світяться тією ж енергією, що оточує невмерлих та Некрополь там, нагорі. Я впевнений, що вони мають якесь призначення, і я хочу, щоб ти {стать:дізнався:дізналася}, яке саме. Поки ти цим займаєшся, зменш кількість цих потвор і принеси мені докази їхньої смерті разом з результатами свого розслідування, і я тебе винагороджу. Іди!", [3] = "Зберіть три тьмяні некротичні камені зі Скари поблизу Дарнаса та дослідіть сяйливі рунічні кола поруч з їхнім табором.", [4] = "Ти вже {стать:завершив:завершила} дослідження кіл Скари? Немає часу для балачок!", [5] = "Хмм... Судячи з того, що ти мені {стать:розповів:розповіла}, ці голоси всередині рунічних кіл... схоже, що їх використовують для комунікації. Я здригаюся від самої думки про те, з якими жахливими почварами можна зв'язатися за допомогою такої магії. Проте тобі вдалося залишитися {стать:цілим та неушкодженим:цілою та неушкодженою}. Сріблястий Світанок цінує твою службу.", ["en"] = "Investigate the Scourge of Darnassus", ["tasks"] = { ["Dim Necrotic Stone"] = "тьмяний некротичний камінь", ["Dim Necrotic Stone (Provided)"] = "тьмяний некротичний камінь (видано)" } },
    [92699] = { [1] = "Верховний Магістр", [2] = "Тепер, коли ви прибули до Валанаару, вам, ймовірно, варто познайомитися з іншими членами Високого Ордену. Нинішній Верховний Магістр, Елаадрін Евенгейл, та його люди діють з ложі на крайньому південно-східному краї Валанаару.\n\nВам також слід бути обережним, Вищий Орден та Творці Вітру тут не дуже добре ладнають. Будьте обережні та обходьте Творців Вітру якомога далі. У нас і так достатньо турбот з культом, я не потерплю насильства між фракціями на вулицях Валанаару.", [3] = "Знайдіть Елаадрін Вечірній Вітер у Валанаарі.", ["en"] = "The Supreme Magister" },
    [927] = { [1] = "Вкрите мохом серце", [2] = "Серце Сморідного Чорномоха вкрите темним, маслянистим мохом. Насправді єдине, що нагадує в цьому серце — це повільний глухий ритм... Биття, яке продовжується навіть зараз.\n\nМожливо, Деналан захоче побачити це серце.", [3] = "Принесіть вкрите мохом серце Деналану біля озера Аль'Амет.", [4] = "{Ім'я}! Ти маєш щось для мене?", [5] = "...Що це? Серце деревника?? Вкрите паскудним мохом!\n\nДякую, що {стать:приніс:принесла} його мені, {Ім'я}. Я огляну серце і, якщо пощастить, визначу природу цього моху.", ["en"] = "The Moss-twined Heart", ["tasks"] = { ["Moss-twined Heart"] = "вкрите мохом серце", ["Moss-twined Heart (Provided)"] = "вкрите мохом серце (видано)" } },
    [92701] = { [1] = "До Валанаару", [2] = "Наразі, здається, пілон і село в безпеці, тому я хотів би, щоб ви передали цей звіт Валеннійському Буревіснику у Валанаарі, на південно-східному краю острова. Валеннія — лідер миротворців на острові, і їй потрібно знати, що тут сталося.\n\nКульт швидко розширюється, і миротворці досі уникали прямих зіткнень, але ці дні минули. Валанаару потрібно бути готовим до бою.\n\nУ будь-якому разі, дякую. У вас завжди будуть друзі в Шен'дарі, {ім'я}.", [3] = "Доставте письмовий звіт Аонди Валенії Штормфіст у Валанаар.", ["en"] = "To Valanaar", ["tasks"] = { ["Aonda's Written Report"] = "Письмовий звіт Аонди", ["Aonda's Written Report (Provided)"] = "Письмовий звіт Аонди (видано)" } },
    [92709] = { [1] = "Велика пригода", [2] = "Твій високородний рід сяє у твоїх очах так само яскраво, як небо над ними. Ти один із нас, і саме молодь, як і ти, допоможе нам врятувати наш дім. Але спочатку дозволь мені розповісти тобі більше про нашу місію та плани тут, на Зефрасі... і за його межами.", [3] = "Послухайте, що каже Елаадрін Евенгейл з Валанаару.", ["en"] = "A Grand Adventure", ["tasks"] = { ["Listen to Elaadrin"] = "Слухайте Елаадрін" } },
    [92727] = { [1] = "Зниклий вчений", [2] = "Пошук знань — головне завдання Високого Ордену, але ця робота ніколи не була небезпечнішою, ніж зараз на Зефрасі.\n\nОдин з наших вчених — Філліон Полум'яний Бриз — прямував до Шен'дарського нагір'я, щоб вивчати магію вітру, яка скупчується в деяких районах. На жаль, він не повернувся, і ми боїмося, що з ним щось трапилося в дорозі.\n\nЯкщо ви можете, будь ласка, знайдіть його для нас. Востаннє його бачили на дорозі, що веде на захід від Валанаару до Шен'дарського нагір'я.", [3] = "Дізнайтеся, що сталося з Філліоном Флеймбрізом.", ["en"] = "The Missing Scholar" },
    [92741] = { [1] = "Небажані гості", [2] = "Ліс Тіньових Стрілок неймовірно небезпечний і зазвичай недоступний для звичайних шукачів пригод. В останні місяці спостерігається вибухове зростання популяції верескучих кігтів, і вони почали розширювати свою територію за межі лісу, що є потенційною проблемою. Мене цікавлять алхімічні властивості верескучих кігтів, тому їхнє вкрай необхідне знищення також дає можливість для наукових досліджень.\n\nПодорожуйте до Лісу Тіньових Стрілок і політь на звірів. Принесіть мені якомога більше їхніх кігтів.", [3] = "Вирушайте до Тіньоголового лісу та зберіть 8 Верескучих Кігтів для Іадарії Гіркого Вітру у Валанаарі.", ["en"] = "Unwelcome Visitors", ["tasks"] = { ["Shriekling Talons"] = "Верескітні кігті" } },
    [92742] = { [1] = "Випробування свердловин", [2] = "Ми повинні визначити джерело та природу отрути, що псує цю землю. Почнемо з ґрунтових вод під фермами в цьому районі.\nВідвідайте садибу Янсен та ферму Молсен і зберіть там зразки зі свердловин.", [3] = "Використовуйте набір для відбору проб води зі свердловин, щоб зібрати зразки зі свердловин на фермі Янсен та на фермі Молсен.", [4] = "Ти зібрав зразки?", [5] = "Дякую. Дай-но погляну...", ["en"] = "Testing the Wells", ["tasks"] = { ["Jansen Stead Water Sample"] = "Зразок води Jansen Stead", ["Molsen Farm Water Sample"] = "Зразок води з ферми Молсен", ["Well Water Sample Kit"] = "Набір для аналізу води зі свердловин", ["Well Water Sample Kit (Provided)"] = "Набір для аналізу води зі свердловин (видано)" } },
    [92744] = { [1] = "Мурлок Гіллс", [2] = "Пошкодження, що вражає врожаї Вестфоллу, можливо, просочилося і в океан. Якщо місцева риба також постраждає, це може приректи Штормовій на голод.\nЗберіть зябра мурлоків вздовж берегової лінії та принесіть їх мені. Мурлоки досить витривалі, але їхня фізіологія надзвичайно чутлива до забруднень. Будь-які токсини в морській воді будуть легко помітні на зябрах, які ви знайдете.", [3] = "Альба Фейрмун хоче, щоб ви зібрали 7 Довгобережових Мурлоцьких Зябер вздовж берегової лінії Вестфоллу.", [4] = "Сподіваюся, мурлоки не завдали тобі надто багато клопоту?", [5] = "Бачу... поки що ці зябра виглядають здоровими. Але нам не можна втрачати пильність.", ["en"] = "Murloc Gills", ["tasks"] = { ["Longshore Murloc Gill"] = "Лонгшор Мерлок Гілл", ["Longshore Murloc Gill (Provided)"] = "Лонгшор Мерлок Гілл (видано)", ["Longshore Murloc Gill slain"] = "Лонгшор Мерлок Гілл: убито" } },
    [92745] = { [1] = "Стан шахт", [2] = "Зразки свердловин, які ви зібрали, містять токсичні метали! Якщо ми швидко не покладемо край цьому корупційному процесу, пройдуть десятиліття, перш ніж урожай знову зможе рости на цьому ґрунті.\nДефіа захопили шахти Вестфолла та використовують істот як робочу силу для видобутку їхніх ресурсів. Зіпсуйте їхню роботу, знищивши шахтарів у шахті Джанголод на півночі та в кар'єрі Золотого Берега на заході.", [3] = "Убийте 4 кобольдів-копачів у шахті Джанголод та 6 шахтарів Річколап у кар'єрі Золотого Берега.", [5] = "Гарна робота, {ім'я:к}. Та боюся, джерело отрути може бути десь в іншому місці...", ["en"] = "The State of the Mines", ["tasks"] = { ["Kobold Digger slain"] = "кобольд-землекоп: убито", ["Riverpaw Miner slain"] = "річколапий шахтар: убито" } },
    [92747] = { [1] = "Шпигунство Мунбрука", [2] = "Дивно — отрута, здається, не походить з шахт, які ви досліджували.\n\nМені сказали, що Мертві шахти під містом Мунбрук — найбільші та найглибші шахти Вестфоллу, але вони були покинуті з часів Першої війни. Чи можуть Мертві шахти знову бути активними?\n\nБудь ласка, вирушайте до Мунбрука, {ім'я}, та пошукайте докази гірничої справи чи промислової діяльності. Це остання зачіпка, яку ми маємо!", [3] = "Зберіть 8 підозрілих промислових матеріалів у Мунбруку.", [4] = "Ти щось знайшов?", [5] = "Що це все таке?", ["en"] = "Moonbrook Espionage", ["tasks"] = { ["Suspicious Industrial Supplies"] = "Підозрілі промислові товари" } },
    [92748] = { [1] = "Вибухова консультація", [2] = "Знайдені вами запаси вказують на величезне промислове підприємство десь у Мертвих Копнях. Немає сумнівів, що це джерело токсинів, що отруюють сільськогосподарські угіддя Вестфоллу. Нам потрібно швидко це зупинити.\n\nЩо б там не було, буде важко знищити. Вирушайте до гномського району Штормовія та знайдіть інженера, який може постачити нам вибухівку.", [3] = "Вирушайте до гномського району в Штормовії та знайдіть інженера, який може допомогти.", ["en"] = "Explosive Consultation" },
    [92749] = { [1] = "План «Динаміт»", [2] = "Промисловий саботаж? Ви привернули мою увагу!\nПочнемо з динаміту...", [3] = "Отримайте 10 одиниць грубого динаміту в крафтингу, торгівлі або на аукціоні, а потім поверніться до Фея Стрибокрут у гномьому районі Штормовія.", ["en"] = "A Dynamite Plan", ["tasks"] = { ["Coarse Dynamite"] = "шорсткий динаміт" } },
    [92750] = { [1] = "Детонація на відстані", [2] = "Гадаю, ви хочете «контрольованого» вибуху? Не так весело, але непоганий вибір, якщо хочете зберегти всі кінцівки.\nБоюся, у мене немає дистанційного детонатора — чому б вам не звернутися до хитрих людей у розвідці Штормовія? Вони повинні нам щось знайти.", [3] = "Поговоріть з кимось зі Штормовійської розвідки про отримання дистанційного детонатора.", ["en"] = "Detonation at a Distance" },
    [92751] = { [1] = "Детонація на відстані", [2] = "Тобі потрібно щось знищити? Чи це має якесь відношення до твоєї діяльності в Мунбруку? Не дивись здивовано. SI:7 постійно в курсі всього, що відбувається в землях Штормовія.\nЯкщо ти плануєш здійснити вибух у печерах під Вестфолом, тобі слід бути заздалегідь на вулиці. Візьми цей дистанційний детонатор — це нещодавній прототип від наших інженерів.\nО, і було б краще, якби ти не згадував про мою причетність своєму другові-ельфу.", [3] = "Віднесіть комплект дистанційного детонатора до Спрайта Джамппрокет у Дворфійський район Штормовія.", ["en"] = "Detonation at a Distance", ["tasks"] = { ["Remote Detonator Kit"] = "Комплект дистанційного детонатора", ["Remote Detonator Kit (Provided)"] = "Комплект дистанційного детонатора (видано)" } },
    [92752] = { [1] = "Вибухова консультація", [2] = "От і все — бомба готова до вибуху! Обережно з детонатором.", [3] = "Поверніться до Альби Фейрмун у Вестфоллі.", ["en"] = "Explosive Consultation", ["tasks"] = { ["Extra-Destructive Explosives"] = "Надруйнівні вибухові речовини", ["Extra-Destructive Explosives (Provided)"] = "Надруйнівні вибухові речовини (видано)" } },
    [92753] = { [1] = "Руйнування в Мертвих шахтах", [2] = "Джерелом отрути, ймовірно, є якась велика металургійна кузня. Знайдіть шлях до Мертвих Шахт і знайдіть кузню, а потім розмістіть вибухівку.\nЯ чекатиму на вас у пагорбах за Мунбруком. Як тільки ви повернетеся, ми зможемо підірвати вибухівку. Сподіваюся, що після зникнення кузні земля почне загоюватися.", [3] = "Знайдіть кузню, заховану в Мертвих Копнях, і розмістіть поблизу надзвичайно руйнівну вибухівку. Потім зустріньтесь з Альбою Фейрмун біля виходу з Мертвих Копень.", ["en"] = "Destruction in Deadmines", ["tasks"] = { ["Explosives placed"] = "Розміщено вибухівку", ["Extra-Destructive Explosives"] = "Надруйнівні вибухові речовини", ["Extra-Destructive Explosives (Provided)"] = "Надруйнівні вибухові речовини (видано)" } },
    [92819] = { [1] = "Руйнування в Мертвих шахтах", [2] = "Ми майже закінчили. Використайте детонатор і покладіть цьому край.", [3] = "Використайте детонатор.", ["en"] = "Destruction in Deadmines", ["tasks"] = { ["Detonator used"] = "Використаний детонатор" } },
    [92834] = { [1] = "Десятикратна помста", [2] = "Коли культ розпочав свою кампанію насильства, Миротворці та Вітротворці відповіли позерством. Я вважав це безглуздою ескалацією, тому виступав за мирний діалог. Вчора я відправив свого друга Белатаана Брайтвіша до Святилища Акіра, сподіваючись налагодити цей діалог.\n\nЩойно прибула коробка з язиком Белатаана, зануреним у срібний пігмент.\n\nТепер мені зрозуміло, що з культом немає жодних підстав для роздумів. Убийте будь-яких культистів, яких побачите, і принесіть мені молитовні амулети, які вони носять.", [3] = "Зберіть 10 оберегів з вітряного каменю Ал'Акет у культистів Ал'Акет, яких можна знайти на північ від Валанаара на полях Густберрі або у святилищі Акіра.", ["en"] = "Avenged Tenfold", ["tasks"] = { ["Al'Aketh Windstone Charm"] = "Оберіг з вітряного каменю Аль'Акет" } },
    [92840] = { [1] = "Ловити вітер", [2] = "Та сама магія, що підтримує цей острів, витає навколо каменів у Шен'дарському нагір'ї. На жаль, ці місця вважаються священними та перебувають під безпосередньою охороною Творців Вітрів, що ускладнює для нас вивчення магії, присутньої там.\n\nОскільки Творці Вітрів зосереджені в іншому місці, у нас є можливість вивчити природу цієї елементарної магії.\n\nВіднесіть цей пристрій до каменів та захистіть його, поки він збиратиме важливі дані. Будьте обережні, будь ласка.", [3] = "Віднесіть Індекс Езотерії до Стоячих Кам'ян Оверлуку в Шен'дарському Нагір'ї та використовуйте його там. Захистіть Індекс від пошкоджень, поки він збирає дані.", ["en"] = "Catching Wind", ["tasks"] = { ["Index Esoteria"] = "Індекс Езотерія", ["Index Esoteria (Provided)"] = "Індекс Езотерія (видано)", ["Protect the Index"] = "Захистіть індекс" } },
    [92849] = { [1] = "Зниклий вчений", [2] = "<Судячи з того, що ви щойно знайшли, дуже ймовірно, що Філліона тут спіткало якесь нещастя. Він все ще може бути неподалік і потребувати допомоги. Ви помічаєте печеру трохи північніше вашого поточного місцезнаходження. Вам слід продовжити його пошуки там.>", [3] = "Продовжуйте шукати Філліона Флеймбріза.", ["en"] = "The Missing Scholar", ["tasks"] = { ["Carry Fillion Flamebreeze to safety while avoiding enemies"] = "Донесіть Філліона Полум'яного Бризу до безпечного місця, уникаючи ворогів.", ["Find Fillion Flamebreeze"] = "Знайдіть Філліона Полум'яного Бриза" } },
    [92850] = { [1] = "Зниклий вчений", [2] = "Мені вже набагато краще. Я маю певні навички з арканними мистецтвами, і ми знаходимося зовсім недалеко від Валанаару. Я можу дістатися туди сам. Однак важливіше за мою безпеку те, як близько до Валанаару звили гнізда ці верескуни та яку небезпеку вони становлять. Будь ласка, поверніться всередину та візьміть голову цього звіра!\n\nПісля цього ви знайдете мене з Дондалліоном у Валанаарі. Мені потрібно повернутися до нього якомога швидше. Він, мабуть, розривається від хвилювання.", [3] = "Убийте Верескливу Матріарх у Верескливому Лігві, а потім поверніть її голову Дондалліону Шелесту Вітру у Валанаарі.", ["en"] = "The Missing Scholar", ["tasks"] = { ["Shriekling Matriarch's Head"] = "Голова верескучої матріархи" } },
    [92860] = { [1] = "На службі у Зефраса", [2] = "Вищий Орден зробив усе можливе, щоб уникнути прямого конфлікту з культом, але це явно більше не варіант. Їхня ворожість була чітко продемонстрована, і тепер ходять чутки про масштабніші рухи культів по всьому острову. Вони явно готуються до чогось, і що б це не було, це не може бути добре для народу Зефраса.\n\nПовідомте Валеннії Буревістка та повідомте їй, що Вищий Орден пропонує нашу повну підтримку зусиллям Валанаара проти Ал'Акет, якщо виникне така потреба.", [3] = "Звернися до Валеннії Буревісник і повідом їй, що Вищий Порядок з ними в боротьбі проти Ал'Акет.", ["en"] = "In Service of Zephras" },
    [929] = { [1] = "Вінець Землі", [2] = "Передусім, дозволь мені детальніше розказати про завдання, що стоїть перед тобою. Друїди Дарнаса користуються водою місячних колодязів, розташованих у різних куточках Тельдрассіля, і деколи їхні запаси води потрібно поновлювати. За допомогою цих спеціально виготовлених фіалів ти й зможеш набирати воду з колодязів.\n\nВіднеси ємність до місячного колодязя у селищі Зоряного Бризу, що лежить на сході, набери з нього трохи води, а потім повертайся до мене. Коли виконаєш це завдання, я продовжу свою оповідь з того моменту, на якому її перервав Тенарон...", [3] = "Наповніть нефритовий фіал і поверніть його Корітрасу Місяцелюті в Доланаарі.", [4] = "З поверненням, {Ім'я}. Ти {стать:виконав:виконала} своє завдання?", [5] = "Після битви при горі Гіджал ми згубили свій шлях. Нордрассіль димився від полум'я запеклих боїв, і наше безсмертя — сама сутність нас, нічних ельфів! — було втрачене.\n\nСаме в цю пору випробувань Зрадник вирвався зі свого ув'язнення, а Шан'до Шаленство Бурі безслідно зник. Для всіх нас настали темні часи.", ["en"] = "Crown of the Earth", ["tasks"] = { ["Filled Jade Phial"] = "наповнений нефритовий фіал", ["Filled Jade Phial (Provided)"] = "наповнений нефритовий фіал (видано)" } },
    [92909] = { [1] = "Збирання врожаю комбайнів", [2] = "О ні... Мене зараз чекає!\n\nЯ чув про комбайнів, які тероризують поля Вестфоллу, тому я проїхав аж із Айронгоржа, щоб спробувати їх перекалібрувати. Але вони набагато агресивніші, ніж передбачали мої розрахунки, і вони переслідували мене аж до цієї стайні!\n\nЯкби в мене були ізопружини та гіростабілізатори від комбайнів, я міг би створити пристрій для прикриття моєї втечі. Чи не міг би ти зібрати для мене деталі?", [3] = "Озвін Айронспрокет з ферми Салдіна хоче, щоб ви принесли йому 14 ізопружин големів та 5 гіростабілізаторів комбайна.", ["en"] = "Harvesting the Harvesters", ["tasks"] = { ["Golem Isospring"] = "Ізопружина Голема", ["Harvester Gyrostabilizer"] = "Гіростабілізатор комбайна" } },
    [92910] = { [1] = "Збирання врожаю комбайнів", [2] = "Частина, яку вам вдалося врятувати від збирача, виглядає майже неушкодженою. Хтось, хто цікавиться ґолемами-жниварями, може захотіти її побачити.", [3] = "Принесіть збірку прецесивного автопізнання Озвіну Айронспрокету на ферму Салдіна.", ["en"] = "Harvesting the Harvesters", ["tasks"] = { ["Precessive Autocognition Assembly"] = "Прецесивна збірка автопізнання", ["Precessive Autocognition Assembly (Provided)"] = "Прецесивна збірка автопізнання (видано)" } },
    [92911] = { [1] = "Збирання врожаю комбайнів", [2] = "Зрозуміло... це дає мені деяке уявлення про те, що рухає цими монстрами. У мене є ідея, як ми могли б перезапустити їхні системи, хоча б на мить.\n\nЯ продовжуватиму бавитися з тим, що ти мені приніс. Тим часом, чи не міг би ти знайти деякі деталі для пристрою?", [3] = "Озвін Айронспрокет з ферми Салдіна хоче, щоб ви принесли йому 8 ізопружин големів, 4 мідні модулятори та простий приціл.", ["en"] = "Harvesting the Harvesters", ["tasks"] = { ["Copper Modulator"] = "мідний модулятор", ["Crude Scope"] = "кустарний приціл", ["Golem Isospring"] = "Ізопружина Голема" } },
    [93] = { [1] = "Темні крабові пиріжки", [2] = "Розкрию тобі маленьку таємницю — темні крабові пиріжки насправді зроблені з павучих лапок! Я знаю, що це трохи огидно, але пиріжки мають приємний пікантний смак і добре підходять як перекус! Принеси мені липкі лапки павука, і я приготую для тебе декілька.\n\nЯ чув, що найкращі лапки в отруйних колопрядів — вони гніздяться на півночі, між гірськими схилами та рікою.", [3] = "Зберіть 6 липких павучих лапок і принесіть їх шеф-кухарю Ґруалу в Темноділ.", [4] = "Привіт, {ім'я}. Ти вже {стать:дістав:дістала} липкі павучі лапки?", [5] = "О так, гарна купа лапок! Мені потрібно просто приправити їх своїми секретними спеціями... не дивись! І трохи піджарити на сковороді...\n\nІ, хоча темні крабові пиріжки — моя фірмова страва, я не буду розкривати її рецепт. Ось рецепт страви, яка майже така ж смачна.", ["en"] = "Dusky Crab Cakes", ["tasks"] = { ["Gooey Spider Leg"] = "липка павуча лапка", ["Gooey Spider Leg (Provided)"] = "липка павуча лапка (видано)" } },
    [930] = { [1] = "Сяючий плід", [2] = "Під гілками цієї сяючої рослини висить великий круглий плід.\n\nВи впевнені, що Деналану захочеться його вивчити.", [3] = "Принесіть сяючий плід Деналану біля озера Аль'Амет.", [4] = "{Ім'я}, схоже, що ти маєш що мені сказати. Ти {стать:приніс:принесла} новини стосовно деревників?", [5] = "Ти {стать:знайшов:знайшла} це на Тельдрассілі? Цікаво... це досить екзотичний фрукт. Можливо, його насіння привезли сюди здалеку. Можливо, навіть не з Азероту! У цьому фрукті щось є... Здається, він дуже дивно відреагував на землю Тельдрассіля.\n\nДякую, {Ім'я}. Тепер, якщо ти мене вибачиш, я мушу це вивчити більш детально...", ["en"] = "The Glowing Fruit", ["tasks"] = { ["Glowing Fruit"] = "сяючий плід", ["Glowing Fruit (Provided)"] = "сяючий плід (видано)" } },
    [93089] = { [1] = "Що буде далі", [2] = "Будь ласка, передайте мою подяку Елаадріну за все, що Вищий Орден та ваші нові друзі з цього «Кірін Тор» зробили для острова Зефрас. Я знаю про плани Вищого Ордену покинути острів, і ваш орден має моє благословення та побажання успіхів у цій експедиції.\n\nЯ можу лише сподіватися, що будь-яке таємне рішення, яке знайде Вищий Орден, справді забезпечить нам стабільність, якої нам бракувало останніми роками. Якщо ви плануєте піти з ними... що ж, його місія буде від цього ще сильнішою.\n\nХай вітер буде з вами, {ім'я}.", [3] = "Поговоріть з Елаадрін Евенгейл, коли будете готові покинути острів Зефраса.", ["en"] = "What Comes Next" },
    [931] = { [1] = "Мерехтливий паросток", [2] = "Паростки цієї рослини мерехтять у лісовому світлі, надаючи їй мінливого, пульсуючого світіння.\n\nВам спадає на думку, що Деналана зацікавить її зразок.", [3] = "Принесіть мерехтливий паросток Деналану біля озера Аль'Амет.", [4] = "У тебе є щось для мене?", [5] = "Де ти це {стать:взяв:взяла}? Я не бачив такої рослини з часів перебування в болоті Скорбот... кілька десятиліть тому! Дивовижно, що цей зразок потрапив аж до Тельдрассіля. Ще й виріс до таких розмірів!\n\nДякую, {Ім'я}. Пробач мені мою небагатослівність, але я мушу провести дослідження цього паростка...", ["en"] = "The Shimmering Frond", ["tasks"] = { ["Shimmering Frond"] = "мерехтливий паросток", ["Shimmering Frond (Provided)"] = "мерехтливий паросток (видано)" } },
    [9317] = { [1] = "Освячені точильні камені", [4] = "Якщо принесеш мені вісім некротичних рун, я дам тобі освячений точильний камінь. Він стане тобі у пригоді в битві з послідовниками Короля-ліча.", [5] = "Дякую, {ім'я}. Ось твої освячені точильні камені. Використовуй їх з розумом.", ["en"] = "Consecrated Sharpening Stones", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [9318] = { [1] = "Благословенна чарівна олія", [4] = "В обмін на некротичні руни загарбників Скари, Сріблястий Світанок дасть тобі один флакон благословенної чарівної олії.", [5] = "Сподіваюся, це стане тобі у пригоді в майбутніх битвах.", ["en"] = "Blessed Wizard Oil", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [932] = { [1] = "Викривлена ненависть", [2] = "Я маю попередити тебе, {Ім'я}, ця справа повинна залишатися між нами. Сатири й так вже завдають нам чималих клопотів, а цей ще й нишпорить поряд із нашими домівками.\n\nЙого називають лордом Меленасом. Він проживає неподалік у печері Каменю Скверни, де він зібрав довкола себе велику зграю грелів-воїнів. Серце у нього чорніше ночі, а задуми - огидні.\n\nЗнайди його в печері неподалік на північ звідси та принеси мені його голову!", [3] = "Убийте лорда Меленаса та принесіть його голову Таллонкаю Спритнокореню в Доланаар.", [4] = "Ти вже {стать:вбив:вбила} лорда Меленаса? Вкрай важливо, щоб усе пройшло швидко та тихо, {Ім'я}. Подальше його існування бентежить усіх нас.", [5] = "Зі смертю лорда Меленаса я нарешті можу перейти до інших справ. Дякую, {Ім'я}.", ["en"] = "Twisted Hatred", ["tasks"] = { ["Melenas' Head"] = "голова Меленаса", ["Melenas' Head (Provided)"] = "голова Меленаса (видано)" } },
    [9321] = { [1] = "Величезне зілля лікування", [4] = "Окрім інших припасів, у нас також є кілька величезних зіллів лікування, які можуть стати тобі в пригоді. Я дам вам одне в обмін на п'ятнадцять некротичних рун.", [5] = "Ось, тримай, {ім'я}. Обережніше там. Нас не так багато, щоб ми могли дозволити собі великі втрати на полі бою.", ["en"] = "Major Healing Potion", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [9324] = { [1] = "Викрадення полум'я Орґріммара", [2] = "Це полум'я, викрадене із серця Орґріммара, переповнює вас теплом. Ця первісна сила чужа для вас, але знавець, можливо, знає більше...", [3] = "Принесіть полум'я Орґріммара до фестивального знавця.", [4] = "Ти майже палаєш, {раса:к}. Що це у тебе?", [5] = "Що це? Якщо я не помиляюся, цей вогонь був взятий прямо з самого серця Орґріммара! Сильні серця орків і тролів відображаються в його пекельному жарі. Який чудовий додаток до нашої колекції. Яку ж це треба мати мужність, щоб проникнути в лігво ворога і заволодіти священним вогнем!\n\nЦікаво, яка сила ховається в інших містах...", ["en"] = "Stealing Orgrimmar's Flame", ["tasks"] = { ["Flame of Orgrimmar"] = "полум'я Орґріммара", ["Flame of Orgrimmar (Provided)"] = "полум'я Орґріммара (видано)" } },
    [9325] = { [1] = "Викрадення полум'я Громового Бескиду", [2] = "Це полум'я, викрадене у шаманів Громового Бескиду, переповнює вас теплом. Ця первісна сила чужа для вас, але знавець, можливо, знає більше...", [3] = "Принесіть полум'я Громового Бескиду до фестивального знавця.", [4] = "Ти майже палаєш, {раса:к}. Що це у тебе?", [5] = "Якщо я не помиляюся, цей вогонь було взято з круч Громового Бескиду! Він співає силою духів! Ти дійсно {стать:вправний злодій:вправна злодійка}, {ім'я}. Прийми це як справедливу винагороду за твою майстерність. Якби ж у нас були вогні всіх трьох міст...", ["en"] = "Stealing Thunder Bluff's Flame", ["tasks"] = { ["Flame of Thunder Bluff"] = "полум'я Громового Бескиду", ["Flame of Thunder Bluff (Provided)"] = "полум'я Громового Бескиду (видано)" } },
    [9326] = { [1] = "Викрадення полум'я Підмістя", [2] = "Це полум'я, викрадене з руїн над Підмістям, переповнює вас теплом. Ця первісна сила чужа для вас, але знавець, можливо, знає більше...", [3] = "Принесіть полум'я Підмістя до фестивального знавця.", [4] = "Ти майже палаєш, {раса:к}. Що це у тебе?", [5] = "Гм... який дивний вогонь! Він майже тліє, але тепло неймовірне. І ти кажеш, що {стать:приніс:принесла} його з Підмістя? Це захоплює. З вогнями всіх трьох міст, хто знає, що ми зможемо зробити...", ["en"] = "Stealing the Undercity's Flame", ["tasks"] = { ["Flame of the Undercity"] = "полум'я Підмістя", ["Flame of the Undercity (Provided)"] = "полум'я Підмістя (видано)" } },
    [933] = { [1] = "Вінець Землі", [2] = "На південному сході від входу в Дарнас, вздовж берегів Арлітріенських ставів ти знайдеш ще один місячний колодязь. Вартовим дедалі важче патрулювати цю територію з огляду на агресію та постійні напади хутропузів племені Кривої Сосни.\n\nБудь насторожі під час пошуків колодязя і тримай свою зброю напоготові.", [3] = "Наповніть турмаліновий фіал і поверніть його Корітрасу Місяцелюті в Доланаарі.", [4] = "Спершу ніхто не звертав уваги на звістки про оскаженілих хутропузів. Хто б міг подумати, що ці миролюбні людоведмеді можуть впадати в таку шалену лють? Скільки ж ще бід впаде на наші голови тут, у нашому новому домі?", [5] = "Шан'до Шаленство Бурі так і не повернувся, навіть сьогодні ми не маємо жодної звістки про нього. Друїди були в сум'ятті. Після зникнення Малфуріона, Верховний друїд Фендрал Оленеріг очолив друїдів, переконавши Коло Древніх на Темнобережжі, що настав час нашому народові повернути собі колишню міць і безсмертя.\n\nОтримавши схвалення Кола, Оленеріг за підтримки наймогутніших друїдів виростив Тельдрассіль, нове Світове Дерево.", ["en"] = "Crown of the Earth", ["tasks"] = { ["Filled Tourmaline Phial"] = "наповнений турмаліновий фіал", ["Filled Tourmaline Phial (Provided)"] = "наповнений турмаліновий фіал (видано)" } },
    [9337] = { [1] = "Величезне зілля мани", [4] = "Окрім інших припасів, у нас також є кілька величезних зіллів мани, які можуть стати тобі в пригоді. Я дам вам одне в обмін на п'ятнадцять некротичних рун.", [5] = "Ось, тримай, <ім'я>. Обережніше там. Нас не так багато, щоб ми могли дозволити собі великі втрати на полі бою.", ["en"] = "Major Mana Potion", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [9339] = { [1] = "Нагорода крадія", [2] = "Це полум'я, викрадене із серця Штормовію, переповнює вас теплом. Ця первісна сила чужа для вас, але знавець, можливо, знає більше...", [3] = "Принесіть полум'я Штормовію до фестивального оповідника.", [5] = "Сьогодні ти {стать:показав:показала} себе, {ім'я}.\n\nХоча мені більше нічого тобі дати, я маю цю корону — гідний подарунок для {стать:завойовника:завойовниці}. Нехай вона освітлює твій шлях.", ["en"] = "A Thief's Reward" },
    [9341] = { [1] = "Гербова накидка Сріблястого Світанку", [4] = "Твоя допомога нашій справі була дуже цінною, {ім'я}. Якщо бажаєш, ти можеш отримати гербову накидку Сріблястого Світанку. Ми пишаємося мати таких союзників як ти.", [5] = "Візьми цю гербову накидку і носи її з гордістю. Можливо, твої вчинки надихнуть інших взяти до рук зброю і підтримати нашу боротьбу проти Скари.", ["en"] = "Tabard of the Argent Dawn", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [93461] = { [1] = "Ласкаво просимо до села Шен'дар", [2] = "У тебе цей вигляд \"Вищого Ордену\". Ті, хто має високородне походження, завжди мають легкий блиск в очах, який це видає. Перш ніж я почну тобі тут працювати, тобі слід зателефонувати до нашого місцевого старійшини Вищого Ордену Ратіріла Санленса. Ти можеш знайти його тут, у головному будинку, одразу за рогом від мене.\n\nО, і ще зателефонуй до Коріелли Калбріз, вона керує місцевим заїздом і може забезпечити тебе житлом та припасами, якщо тобі це знадобиться.", [3] = "Поговоріть з Ратхірілом Санланс та Коріеллою Калмбріз у селі Шен'дар.", [5] = "Тож ти вже відмітився в Ратіріла? Чудово. Останнім часом між Високим Орденом і вітротворцями чимало напруги, але тут, у Шен'дарі, вони поводяться пристойно. Ну, принаймні в самому селищі. Що відбувається в дикій місцевості — там і лишається.\r\n\r\nРаз із цим покінчено, ти схожий на того, хто шукає, чим би зайняти руки. У мене є кілька справ, які треба владнати, якщо не проти трохи попрацювати?", ["en"] = "Welcome to Shen'dar Village", ["tasks"] = { ["Speak with Rathiril Sunlance"] = "Поговоріть з Ратхірілом Санланс", ["Speak with the Innkeeper"] = "Поговоріть з господарем готелю" } },
    [935] = { [1] = "Вінець Землі", [2] = "Без благословень Алекстрази, Берегині Життя, та Ноздорму, Володаря Часу, Тельдрассіль виріс із вадами. Чудні створіння лізуть з-під його кореневища, а оскаженілі хутропузи нападають на мандрівників, що проходять повз їхні селища.\n\nЗалишається лише сподіватися, що Верховний друїд швидко знайде якесь рішення. Я наповню флакон водою з усіх принесених тобою фіалів, щоб ти {стать:доставив:доставила} їх у Дарнас.\n\nВіднеси його Фендралові Оленерогу, ти знайдеш його в діброві друїдів.", [3] = "Віднесіть наповнений флакон Верховному друїду Фендралові Оленерогу в Дарнас.", [4] = "Я не кликав тебе, тож не розумію, навіщо ти {стать:прийшов:прийшла} відволікати мене своїми балачками.\n\nЩо б там не було, кажи, будь ласка, швидше.", [5] = "О, так, це та вода, яку я просив мені надіслати. Тенарон і Корітрас, очевидно, не надто з цим поспішали... і гінця, можливо, обрали не найнадійнішого... хм-м.\n\nУ будь-якому разі, тепер я, нарешті, можу повернутися до роботи. Тягар усіх бід Тельдрассіля важким ярмом лежить на моїх плечах. Залишається лише сподіватися, що скоро я його позбудуся.\n\nОсь, візьми. Можливо, тобі це знадобиться.", ["en"] = "Crown of the Earth", ["tasks"] = { ["Filled Vessel"] = "наповнений флакон", ["Filled Vessel (Provided)"] = "наповнений флакон (видано)" } },
    [937] = { [1] = "Зачарована поляна", [2] = "Мене відправили сюди з невеликою групою вартових, щоб захистити Дерево-оракул від гарпій, які позвивали свої гнізда всією галявиною. Потроху ми намагаємося вигнати їх звідси.\n\nКоли Дерево-оракул спробувало відправити гінця з доповіддю в Дарнас, на посланника напала зграя гарпій і вбила його.\n\nЯкщо ти берешся за це завдання, то вирушай до гнізд гарпій, вбий їх і принеси мені їхні пояси як доказ.", [3] = "Роздобудьте 6 поясів Кривавоперих і принесіть їх вартовій Аринії Хмарелам на поляну Оракула.", [4] = "Їхні гострі пазурі та дзьоби можуть стати важким випробуванням для твоїх здібностей, {Ім'я}, але я вірю, що ти впораєшся з цим завданням.", [5] = "Я вражена тим, чого ти тут {стать:досяг:досягла} за такий короткий період. Хотілося б попросити тебе залишитися тут і допомогти мені із моїми обов'язками... але в душі я розумію, що на тебе очікують важливіші справи.\n\nЯ помітила, що Дерево-оракул щойно впустило частинку своєї кори. Схоже, в нього є завдання для тебе.", ["en"] = "The Enchanted Glade", ["tasks"] = { ["Bloodfeather Belt"] = "пояс Кривавоперих", ["Bloodfeather Belt (Provided)"] = "пояс Кривавоперих (видано)" } },
    [93791] = { [1] = "Поговоріть з Беланном", [2] = "{ім'я}, очевидно, що твої навички магії зростають, і я вважаю, що тобі час долучитися до однієї з найдавніших традицій Високого Ордену для молодих та початківців магів. Тобі час створити власний фокус заклинань.\n\nЗнайди Беланна Віндвуда у Валанаарі. Він виготовляє палиці та чарівні палички для Високого Ордену вже понад століття, тож ти будеш у надійних руках.", [3] = "Поговоріть з Беланн Віндвуд у Валанаарі.", ["en"] = "Speak with Belann" },
    [93797] = { [1] = "Гілки на вітрі", [2] = "Це шанована часом традиція для молодих магів створювати власний фокус заклинань, коли вони демонструють певний рівень магічної майстерності. Зазвичай це робиться шляхом збору поваленої гілки з наших найстаріших дерев, оскільки на них є деякі сліди стихійного вітру.\n\nЯ знайшов найкращі з них поблизу святилища вітру, трохи південніше села Фалаат. Піди і принеси мені велику гілку, і я розповім тобі про традиції, поки ми створюватимеш твій фокус заклинань.", [3] = "Принесіть наповнену вітром гілку до Беланн Вітрового Лісу у Валанаарі.", ["en"] = "Boughs in the Wind", ["tasks"] = { ["Wind-Infused Bough"] = "Гілка, настояна на вітрі" } },
    [938] = { [1] = "Імла", [2] = "Хутро самиці шаблезуба має відмінний сірий колір, який гармонічно зливається із навколишнім лісом. Поки вона лежить на місці, ви помічаєте, що тварина сильно постраждала, а в областях спини та живота простежуються глибокі рвані рани.\n\nСамиця піднімає голову і дивиться на вас, яскравими розумними синіми очима. Здається, вона готова слідувати за вами.", [3] = "Проведіть Імлу до вартової Аринії Хмарелам, яка знаходиться біля місячного колодязя поблизу Дерева-оракула.", [4] = "Імла... Це була моя вина! Ті відьми застали мене зненацька... Я не повинна була їм дозволити захопити тебе...", [5] = "Дуже дякую, {Ім'я}! Я боялася, що більше ніколи не побачу Імлу, тужила всім серцем по її смерті, думаючи, що навік розлучилася зі своєю вірною супутницею... Я в неоплатному боргу перед тобою! Прийми мою безмежну вдячність.", ["en"] = "Mist", ["tasks"] = { ["Lead Mist safely to Sentinel Arynia Cloudsbreak"] = "Безпечно проведіть Туман до Вартової Аринії" } },
    [93835] = { [1] = "Протистояти Лортуні", [2] = "Лортуна втекла на шпилі, використовуючи якийсь портал. Аєсса та Елаадрін пішли за нею. Це було лише кілька хвилин тому.\n\nБоюся, я отримав забагато ударів, і тут я залишуся. Пройдіть через портал, знайдіть Елаадрін та допоможіть їм зупинити Лортуну.\n\nЯкщо допомога, за якою, за словами Елаадрін та Аєсса, вони послали, скоро не прибуде, то ви будете самі. Удачі, {клас}.", [3] = "Пройдіть порталом до Шпилів Рохаші над головою та приєднайтеся до Елаадрін Евенгейл та Айєсси Світанкової у їхній сутичці з Верховною Жрицею Лортуною.", ["en"] = "Confront Lorthuna", ["tasks"] = { ["Confront Lorthuna"] = "Протистояти Лортуні" } },
    [939] = { [1] = "Флейта Заваріка", [2] = "Ви оглядаєте просту дерев'яну флейту, яку забрали після перемоги над Заваріком.\n\nВузлувате дерево відчувається міцним, але здається, що візерунки на поверхні починають обертатися та рухатися, коли ви обертаєте флейту в руках. Вас раптово охоплює страх...\n\nВи хитаєте головою, впевнені, що це просто гра уяви.\n\nАле, можливо, в інших сатирів знайдеться розгадка таємниці вашої знахідки. Принесіть свої знахідки друїдці Ерідані Блакитновій, яка мешкає на півдні Сквернолісся.", [3] = "Принесіть флейту Заваріка та 5 зразків скверни нефритожарих до Ерідани Блакитновій у південному Скверноліссі.", [4] = "Що таке, {клас:к}? Ти виглядаєш {стать:стурбованим:стурбованою}.", [5] = "Я відчуваю страждання древніх, {ім'я}...\n\nТримати ці предмети нестерпно...", ["en"] = "Flute of Xavaric", ["tasks"] = { ["Flute of Xavaric"] = "флейта Заваріка", ["Flute of Xavaric (Provided)"] = "флейта Заваріка (видано)", ["Jadefire Felbind"] = "нефритожарі пута скверни", ["Jadefire Felbind (Provided)"] = "нефритожарі пута скверни (видано)" } },
    [93963] = { [1] = "Дослідження Альянсу", [2] = "Штормовій, Айронфорж і Дарнас мають унікальні народи та культури. Як гість Альянсу тут, в Азероті, вам варто приділити трохи часу, щоб відвідати кожну з наших столиць по черзі.\n\nПоговоріть з Рендалом Емерсоном у південній передпокої, щоб отримати вказівки, як розпочати.", [3] = "Поговоріть з Рендалом Емерсоном у Штормовійській фортеці, щоб отримати подальші інструкції. Використайте отримані інструкції, щоб знайти короля Магні Бронзобородого, Верховного Містера Меккаторке та Тіранду Віспервітер та поговорити з ними.", ["en"] = "Exploring the Alliance", ["tasks"] = { ["Recieve Instructions from Randal Emerson"] = "Отримати інструкції від Рендала Емерсона", ["Speak with High Tinker Mekkatorque"] = "Поговоріть з Верховним Мітником Меккаторкве", ["Speak with King Magni Bronzbeard"] = "Поговоріть з королем Магні Бронзбердом", ["Speak with Tyrande Whisperwind"] = "Поговоріть з Тірандою Шепіт Вітру" } },
    [94] = { [1] = "Пильне око", [2] = "Мій суперник, Морґант - порочний маг, що живе у вежі Ілґалара в Багрянокряжжі. Я розробив засіб шпигування - Око Азори, і тепер я можу слідкувати за ним здалеку.\n\nАле щоб вивчити його думки... Мені потрібна допомога.\n\nЯкщо ти {стать:готовий:готова}, віднеси мій гліф Азори до вежі Ілґалара. Помісти його на статую лева біля вежі.\n\nКоли ти це зробиш, сила Азори дозволить мені побачити майбутні плани Морґанта.", [3] = "Віднесіть гліф Азори до статуї лева біля вежі Ілґалара в Багрянокряжжі.", [4] = "Статуя лева стоїть тут десятиліттями та самотньо стежить за сумнозвісною вежою Ілґалара.\n\nВ основі статуї знаходиться виїмка, куди можна вставити самоцвіт або гліф...", [5] = "Ви кладете гліф Азори у виїмку. Він ніби вростає в камінь... і з нього лунає безтілесний голос Теокрита:\n\n\"Прийми мою подяку, {стать:юний:юна} {Ім'я}. Тепер ти можеш говорити зі мною через цей гліф, а я знайду для тебе завдання... Після того, як прощупаю думки Морґанта.", ["en"] = "A Watchful Eye", ["tasks"] = { ["Glyph of Azora"] = "гліф Азори", ["Glyph of Azora (Provided)"] = "гліф Азори (видано)" } },
    [941] = { [1] = "Посіяти серце", [2] = "Я видалив цей смердючий мох з серця, але воно досі заражене...\n\nСпробуй посадити його в мою діжку. Вона наповнена родючою землею, яка може очистити та вилікувати це серце.", [3] = "Посадіть заражене серце у діжці Деналана.", [4] = "Діжка наповнена землею, спеціально підготовленою Деналаном.", [5] = "Ви садите серце в діжку, і воно швидко заривається в землю!\n\nЧерез кілька секунд серце знову виринає на поверхню... В'яло пульсуючи... заохочуючи вас взяти його в руки.", ["en"] = "Planting the Heart", ["tasks"] = { ["Tainted Heart"] = "заражене серце", ["Tainted Heart (Provided)"] = "заражене серце (видано)" } },
    [9415] = { [1] = "Звіт маршалу Блакитномуру", [2] = "Ти {стать:новобранець:новобранка} маршала Блакитномура? Звісно, так і є.\n\nЧого ж ти чекаєш? Хороші солдати гинуть у пустелі. Хіба ти не хочеш приєднатися до них?\n\nА тепер йди й не помри від спраги по дорозі.", [3] = "Поговоріть з маршалом Блакитномуром у таборі Альянсу біля Вул'Зори.", [5] = "Альянсу потрібна допомога всіх, хто здатен тримати зброю. Орда регулярно отримує підкріплення з північної частини континенту, і ми намагаємося від них не відставати.\n\nДозволь пояснити тобі ситуацію.", ["en"] = "Report to Marshal Bluewall" },
    [9419] = { [1] = "Прочісування пустелі", [2] = "Нещодавно ми дізналися, що Орда обстежувала Силітус у пошуках цінних ресурсів. Ми думали, що в цій задушливій пустелі не варто розміщувати велику кількість військ.\n\nОднак ми зрозуміли важливість цих ресурсів, і тепер марно намагаємося наздогнати Орду.\n\nЯкщо хочеш допомогти — йди в пустелю, знайди силітист і принеси його сюди.", [3] = "Знайдіть і принесіть силітист до екстрактора силітиста, після чого поговоріть з маршалом Блакитномуром у таборі Альянсу біля Вул'Зори.", [4] = "Будь {стать:обережним:обережною}, але все ж не барись. Нам не можна гаяти час.", [5] = "Хвала Світлу, тобі вдалося.\n\nЯкби ми почали раніше, ми б не були в такому відчайдушному становищі. Ми не можемо допустити, щоб багатства цієї пустелі потрапили до рук Орди.", ["en"] = "Scouring the Desert", ["tasks"] = { ["Return Silithyst"] = "Повернення Силітиста", ["Return Silithyst (Provided)"] = "Повернення Силітиста (видано)", ["Return Silithyst slain"] = "Повернення Силітиста: убито" } },
    [942] = { [1] = "Розгублений розвідувач", [2] = "Ця скам'янілість разюче схожа на ту, що я одного разу бачив в Залізогарті. Археолог на ім'я Флягопуз приносив її на щорічну конференцію Ліги дослідників. Він вважав, що в ній прихована сила, яку можна якимось чином вивільнити.\n\nВостаннє я чув, що Флягопуз влаштувався в таверні \"Глибоководдя\", що в гавані Менетілів і збирається піти на розкопки Вельґара. Знайди його і покажи йому скам'янілість Сноходня. Можливо, він зуміє розкрити таємниці минулого.\n\nКорабель до Менетілів відходить з Аубердіна.", [3] = "Віднесіть таємничу скам'янілість археологу Флягопузу в гавань Менетілів.", [4] = "Що се в тебе, {стать:друже:подруго}?", [5] = "Йой! Кажеш, це з далеких земель Калімдору?\n\nДивовижно! Просто дивовижно!", ["en"] = "The Absent Minded Prospector", ["tasks"] = { ["Mysterious Fossil"] = "таємнича скам'янілість", ["Mysterious Fossil (Provided)"] = "таємнича скам'янілість (видано)" } },
    [94369] = { [1] = "Доля Зефраса", [2] = "Ансірем багато розповів мені про володарів стихій, і я боюся, що у нас є вагомі підстави боятися Ал'Акіра тепер, коли обереги, що приховували Зефраса, зникли. Якщо Володар Вітру вирішить напасти на нас, у нас немає жодного шансу захиститися, поки ми тут, у його володіннях.\n\nВерховний Старійшина Тіней Пісня має знати про небезпеку, в якій ми знаходимося, і, що ще важливіше, про наші наміри щодо нашої місії в Азерот. Ми знайдемо засоби, щоб врятувати наш дім. Клянусь.", [3] = "Поговоріть із Талаанісом Шодосонг у Валанаарі.", ["en"] = "The Fate of Zephras", ["tasks"] = { ["Speak with Talaanis Shadowsong"] = "Поговоріть з Талаанісом Тіньоспівом" } },
    [94375] = { [1] = "Поклик землі", [2] = "Візьми від мене цей необроблений кварц і принеси його Тео Хамерсторму як доказ нашої зустрічі. Він створить для тебе тотем, а цей камінчик буде його серцем. Яким би маленьким він не здавався, ти зрозумієш, що розмір не має значення, і що навіть найменші речі можуть пережити багато інших.\n\nБудь терплячим, {ім'я}. Залишайся сильним. І шукай мудрості. Цього просить від тебе земля. Зрештою, ти станеш єдиним цілим із землею — поважай її, як вона поважатиме тебе.", [3] = "Принесіть необроблений кварц Тео Хамершторму в Анвілмар.", ["en"] = "Call of Earth", ["tasks"] = { ["Rough Quartz"] = "грубий кварц", ["Rough Quartz (Provided)"] = "грубий кварц (видано)" } },
    [944] = { [1] = "Глефа властителя", [2] = "Дивно, що наги опинилися тут, на Темнобережжі. Але ще дивніше... Сутінковий Молот. Цей культ поклоняється старим, дуже старим повелителям землі. Повелителям, переможеним давним-давно.\n\nГлефа властителя, що на півдні — місце, де поліг один з таких старих повелителів.\n\nЙди туди та пошукай інших культистів Сутінкового Молота.\n\nВізьми цей фіал провидіння. Як розвідаєш все біля Глефи властителя — створи з нього чашу провидіння. Зв'яжись зі мною за допомогою цієї чаші.", [3] = "Розвідайте місцевість, після чого скористайтесь фіалом провидіння, щоб створити чашу провидіння, з допомогою якої поговоріть з Ону.", [4] = "Глефа властителя, {ім'я}.\n\nПрямуй туди, і потім поговори зі мною знову.", [5] = "Ти {стать:бачив:бачила} Сутінковий Молот біля Глефи властителя?\n\nШкода.\n\nСтарий повелитель, простромлений мечем, давно помер, але це не означає, що в його рештках немає залишків його сили.\n\nСутінковий Молот, мабуть, шукає цю силу.", ["en"] = "The Master's Glaive", ["tasks"] = { ["Enter the Master's Glaive"] = "Входить Глефа Майстра", ["Explore Zone"] = "Дослідіть місцевість" } },
    [94413] = { [1] = "Чарівна образа", [2] = "Нещодавня поява лей-ліній на поверхні Зефраса мала величезне значення для нашого ордену. Ми маємо більш прямий та відчутний доступ до енергій, що пронизують це місце, і це значно розширило наше розуміння цієї магії.\n\nОднак, Творці Вітру розглядають ці появи як шрами на землі, які необхідно «зцілити». Це образа нашого ордену, і ми просто не можемо цього терпіти.\n\nІдіть до лей-лінії в лісі на південний захід і проженіть Творців Вітру, яких ви там знайдете.", [3] = "Убийте 6 новачків-провидців-формувальників вітру в Шен'дарському нагір'ї.", [5] = "Іноді мені важко відрізнити сліпий фанатизм культу Ал'Акету від упертої відмови вітротворців змінюватися.\r\n\r\nЯкби вони справді вірили, що вітри ведуть нас, то мали б відчути, куди вони дмуть, і плисти за течією, а не проти неї.", ["en"] = "A Magical Affront", ["tasks"] = { ["Windshaper Novice Seer defeated"] = "Початківець-провидець Творця вітру переможений" } },
    [94449] = { [1] = "Поклик вогню", [2] = "Минуло багато часу з того часу, як тебе востаннє випробовували, {ім'я}. Ти проявив терпіння, так -- але тепер настав час тобі навчитися хаосу... руйнування. Поклик вогню гучний, і якщо ти готовий заплатити його ціну, він заговорить з тобою.\n\nЗнайди Брюгса Кіндлборна далеко на сході в горах. Він мешкає в печері над форпостом Південних Воріт. Він знатиме, чи ти справді готовий.", [3] = "Знайдіть Брюггський Кіндлборн у Дун-Морогу.", ["en"] = "Call of Fire" },
    [94465] = { [1] = "Поклик вогню", [2] = "Так, у тебе є сила нести тотем вогню, хлопче, але однієї сили ти не підготуєшся.\n\nЗа Долиною Королів, у скелях Лох Модан, лежить прихований шлях до однієї з наших священних вершин. Там Бралдір Попелястий Мантл охороняє Святилище Сплячого Полум'я.\n\nВіднеси йому цей смолоскип — він показує твій намір. Поверни його палаючим біля жаровні святилища, і я простежу, як ти заслужиш справжній тотем.", [3] = "Принесіть Смолоскип Сплячого Полум'я до Бралдіра Попелястого Мантла в Лох-Модан.", ["en"] = "Call of Fire", ["tasks"] = { ["Torch of the Dormant Flame"] = "смолоскип дрімаючого полум'я", ["Torch of the Dormant Flame (Provided)"] = "смолоскип дрімаючого полум'я (видано)" } },
    [94467] = { [1] = "Поклик вогню", [2] = "Вогняна сапта готова, {ім'я}. Тепер стань обличчям до полум'я. Використай його біля святилища, а потім піднімися на вершину. Там ти побачиш духа — він не вдарить, поки ти не вдариш, але він знатиме, що ти його бачиш.\n\nБий швидко, хлопче. Чим довше чекатимеш, тим сильніше він горить. Коли він впаде, візьми його жарке вугілля та поклади його в жаровню. Запали смолоскип і заслужи прихильність вогню.", [3] = "Перемогти Малий Прояв Вогню та помістити Розсіяний Вугілля в жаровню на вершині Храму Вічного Полум'я.", ["en"] = "Call of Fire", ["tasks"] = { ["Glowing Ember"] = "розжарена вуглинка", ["Torch of the Dormant Flame"] = "смолоскип дрімаючого полум'я", ["Torch of the Dormant Flame (Provided)"] = "смолоскип дрімаючого полум'я (видано)" } },
    [94468] = { [1] = "Поклик вогню", [2] = "Міцно тримаючи смолоскип, ви відвертаєтеся від жаровні та дивитеся на озеро Лох-Модан. Ви відчуваєте, як ваше серце охоплює хвилювання, коли вітер посилюється і змушує полум'я шалено танцювати.\n\nВи вирушаєте стежкою назад до Дун-Морога в пошуках Брюгга Кіндлборн.", [3] = "Принесіть Смолоскип Вічного Вогню до Брюгга Кіндлборн у Дун-Морог.", ["en"] = "Call of Fire", ["tasks"] = { ["Torch of the Eternal Flame"] = "смолоскип вічного полум'я", ["Torch of the Eternal Flame (Provided)"] = "смолоскип вічного полум'я (видано)" } },
    [94494] = { [1] = "Поклик води", [2] = "Давно минуло відтоді, як тебе востаннє випробовували, {ім'я}. Ти досі виявив терпіння у своїх дослідженнях, але настав час тобі дізнатися про чистоту води.\n\nЗнайди Норріка Лохтана в озері Лох Модан. Він знаходиться на північно-західному краю озера, на південь від Кам'яної греблі. Ти знайдеш його там, у його норі. Удачі тобі, {ім'я}.", [3] = "Знайдіть Норріка Лохтана в озері Лох Модан.", ["en"] = "Call of Water" },
    [94495] = { [1] = "Поклик води", [2] = "Якщо є одна істина, яку вам потрібно вивчити про воду, то це ось що: вода означає відродження. Вона висікає камінь, очищає від бруду та зцілює втомлених – але лише тоді, коли вона чиста. Забрудніть її, і вона зіпсує все, до чого торкнеться.\n\nЯкщо ви шукаєте водну сапту, знайдіть Гервдану Саегрунд у Болотах. Її родина мешкає в печері під південним водоспадом.\n\nТоді йдіть, не дозволяйте річці випередити вас.", [3] = "Знайдіть Гервдану Саегрунд у водно-болотних угіддях.", ["en"] = "Call of Water" },
    [94497] = { [1] = "Поклик води", [2] = "А, отже, ти прийшов шукати сапту, чи не так? Ну тоді слухай уважно, люба. Щоб знайти розуміння та заслужити сапту, ти повинен шукати воду в її різних формах. Збираючи зразки, тримай очі відкритими. Спостерігай за звірами, які її охороняють, за землею, яку вона живить, і за тим, як вона змінює життя.\n\nПочнемо з простого: наповни цей бурдюк біля підніжжя водоспаду, де прісна вода зустрічається з солонуватою. Іди зараз і обережно стався до болота.", [3] = "Наповніть порожній коричневий бурдюк з водою на дні водоспадів під печерою Гервдани та поверніть його їй у водно-болотних угіддях.\n\nНаданий предмет:", ["en"] = "Call of Water", ["tasks"] = { ["Full Brown Waterskin"] = "Повний коричневий бурдюк" } },
    [94499] = { [1] = "Поклик води", [2] = "Так, Редрідж п'є з озера Еверстілл глибоко, але до того часу, як вода стрімко стікає до водоспаду Стоунвотч, щось просочується всередину. Мурлоки там, внизу, — великі, покручені тварюки. Не такі, як ті, що тут чи в озері. На щастя для городян, вони тримаються біля підніжжя водоспаду.\n\nПринесіть мені зразок. Я маю намір дізнатися, чи це магія, отрута чи щось гірше забруднює води біля того старого форту.", [3] = "Наповніть порожній червоний бурдюк біля водоспаду Кам'яна Варта, неподалік від мурлоків-нічників, і поверніться до Гервдани Саеґрунд у Болотах.\n\nНаданий предмет:", ["en"] = "Call of Water", ["tasks"] = { ["Full Red Waterskin"] = "Повний червоний бурдюк" } },
    [945] = { [1] = "Втеча Терилуни", [2] = "Допоможіть!\n\nЯ блукала навколо Глефи властителя, як раптом мене оточили ці брудні сектанти. На щастя, я гарно вмію ховатися!\n\nВи можете допомогти мені вибратися звідси? І ще, мені потрібно буде повідомити моїй сестрі Терисіль, що зі мною все гаразд. Вона в Ясенедолі, на півдні, біля вівтаря Аессіни.", [3] = "Допоможіть Терилуні втекти, а потім скажіть Терисіль біля вівтаря Аессіни, що її сестра в безпеці.", [5] = "Де була моя сестра? Терилін любить блукати всілякими брудними місцинами, але все ж! Це дуже далеко, а Глефа властителя — місце небезпечне...\n\nЩо ж, спасибі, {ім'я}. З вашого боку було дуже люб'язно повідомити мені, що з нею все гаразд.", ["en"] = "Therylune's Escape", ["tasks"] = { ["Escort Therylune away from the Master's Glaive"] = "Супроводьте Терілуну подалі від Глефи Майстра" } },
    [94500] = { [1] = "Поклик води", [2] = "Візьміть цей бурдюк з водою та вирушайте вглиб смарагдової тіні Ясенеділу. Астранар лежить серед вод, не зачеплених тлінням. Руїни розкидані по дну озера, натякаючи на минулу епоху. Принесіть зразок з озера. Чиста, стародавня і, можливо, зачарована вода.\n\nЦе остання рідина, яка мені потрібна, перш ніж я відправлю вас назад до Норріка.\n\nСідайте на човен у Менетілі до Обердіна, він зупиняється на Південному Березі дорогою туди.\n\nІ пам'ятайте... у лісу є очі, і вони не кліпають.", [3] = "Наповніть порожній синій бурдюк біля вод Астранара в Ясенедолі та поверніться до Гервдани Саеґрунд у Болотах.\n\nНаданий предмет:", ["en"] = "Call of Water", ["tasks"] = { ["Full Blue Waterskin"] = "Повний синій бурдюк для води" } },
    [94501] = { [1] = "Поклик води", [2] = "У Норріка буде ще одне завдання, перш ніж він нагородить вас обрядами тотема води. Флакон з водою, який я вам дав, необхідний для будь-якого цього завдання. Ідіть зараз і знайдіте його. Ми колись знову зустрінемося.", [3] = "Принесіть флакон найчистішої води Норріку Лохтану в озері Лох Модан.", ["en"] = "Call of Water", ["tasks"] = { ["Vial of Purest Water"] = "фіал найчистішої води", ["Vial of Purest Water (Provided)"] = "фіал найчистішої води (видано)" } },
    [94502] = { [1] = "Поклик води", [2] = "У Вестфоллі, за Місячним струмком, лежить Ставок Стендела. Колись чисте джерело, якого тепер торкнулися темні сили. Духи там замовкли.\n\nВи повинні зіткнутися з псуванням, яке забруднює воду. Візьміть його захисні лати та останні краплі зілля Гервдани, а потім покладіть їх на святилище. Це викличе духа, очищеного та правдивого. Поговоріть з ним, дізнайтеся, що можете.\n\nПринесіть мені доказ того, що діяння скоєно, і я дам вам тотем.", [3] = "Очистіть від псування ставку Стендела у Вестфоллі.\nПісля завершення поверніться до Норріка в Лох-Модан.", ["en"] = "Call of Water", ["tasks"] = { ["Corrupt Manifestation's Bracers"] = "наручі зіпсованого прояву", ["Remaining Drops of Purest Water"] = "залишки крапель найчистішої води", ["Remaining Drops of Purest Water (Provided)"] = "залишки крапель найчистішої води (видано)" } },
    [94503] = { [1] = "Поклик води", [2] = "Світло спалахує, коли останнє слово злітає з твоїх вуст. Шипіння води, що перетворюється на туман, зникає в тиші, і твої почуття паморочаться, коли зіпсовані духи навколо тебе розплутуються, їхня сутність розвіюється, як попіл на вітрі.", [3] = "Поговоріть з Малим Проявом Води у Вестфоллі.", ["en"] = "Call of Water" },
    [94505] = { [1] = "Поклик води", [2] = "Візьми уламок. Візьми уламок і дай життя.\n\nДай життя і зрозумій. Зрозумій, вода — це життя... корупція зупиняє життя.\n\nТи захищаєш і даєш життя силою води.", [3] = "Принесіть Уламок Води Норріку Лохтану в Лох Модані.", ["en"] = "Call of Water", ["tasks"] = { ["Shard of Water"] = "осколок води", ["Shard of Water (Provided)"] = "осколок води (видано)" } },
    [947] = { [1] = "Печерні гриби", [2] = "Я працюю над зіллям, для якого потрібні рідкісні гриби, що ростуть лише в одній-єдиній печері. Вона знаходиться за Скельноджерельним водоспадом, на схід і трохи на північ звідси, вздовж гір.\n\nЯ б і сам туди пішов, але в діброві Древніх мені порадили триматися подалі від цього місця. Наші шановні союзники відчувають, що в печері ховається нове зло Темнобережжя.\n\nПрошу, {ім'я}, збери для мене гриби. А поки збиратимеш їх — розвідай ту печеру. Можливо, тобі вдасться знайти підтвердження словам древніх.", [3] = "Принесіть 5 лусконіжок та 1 мертвянку Барітрасу Місячній Тіні в Аубердін.", [4] = "Ти {стать:зібрав:зібрала} гриби, {ім'я}? Вже {стать:ходив:ходила} до печери?", [5] = "Дуже дякую, {ім'я}. Це чудові екземпляри!\n\nДо речі, ти {стать:бачив:бачила} якісь підтвердження слів древніх біля Скельноджерельного водоспаду?\n\nДревні мудрі, але я сподівався, що цього разу вони помилилися.", ["en"] = "Cave Mushrooms", ["tasks"] = { ["Death Cap"] = "мертвошляпка", ["Death Cap (Provided)"] = "мертвошляпка (видано)", ["Scaber Stalk"] = "лусконіжка", ["Scaber Stalk (Provided)"] = "лусконіжка (видано)" } },
    [94773] = { [1] = "Божественна благодать", ["en"] = "Divine Grace" },
    [94774] = { [1] = "Божественна благодать", [2] = "Ви привернули увагу нашого начальства, {ім'я}. Вони попросили вас якомога швидше вирушити до Собору Світла у Штормовії. Очевидно, вони вважають, що ви вже довели свою спроможність і готові продовжити навчання. Коли ви туди потрапите, знайдіть Верховну Жрицю Лорену. Вона зможе направити вас далі. Удачі вам, і нехай Світло буде з вами.", [3] = "Поговоріть з Верховною жрицею Лореною у Штормовії.", ["en"] = "Divine Grace" },
    [94775] = { [1] = "Божественна благодать", [2] = "Благословляє тебе Елуна, добра {раса}. Сподіваюся, твоє Світло знайде тебе і добре захистить цього дня.\n\nНещодавно тут був один із твоїх жерців, який шукав тебе. Він згадав, що ти маєш якомога швидше повернутися до Собору Світла, щоб поговорити з Верховною Жрицею Лореною. Здається, ти добре вчинила, що привернула таку увагу. Я б не витрачала тут забагато часу — твій народ потребує тебе.", ["en"] = "Divine Grace" },
    [94776] = { [1] = "Божественна благодать", [2] = "Тобі час вирушати до Штормовія, {ім'я}. Верховна жриця Лорена з Собору Світла хоче поговорити з тобою. Має бути щось справді хороше чи справді погане, щоб Верховна жриця хотіла тебе там особисто, але, гадаю, ти добре впорався лише для себе, і це добре, що вона хоче поговорити з тобою.\n\nАле не гай забагато часу. Я б вирушив туди якомога швидше.", ["en"] = "Divine Grace" },
    [94777] = { [1] = "Божественна благодать", [2] = "Зовсім недавно один із ваших священиків був тут і шукав вас, {раса}. Він сказав, що якщо я вас побачу, я маю направити вас до Собору Світла. Він сказав, що це дуже важливо, але я б не надто хвилювався на вашому місці. Його поведінка здавалася позитивною... ніби це були гарні новини. Я б не витратив багато часу, щоб дістатися туди, якби був на вашому місці.\n\nХай Елуна буде з вами, добра {раса}.", ["en"] = "Divine Grace" },
    [94778] = { [1] = "Божественна благодать", [2] = "Ти потрібен у Штормовії, {ім'я}. Верховна жриця, Лорена, каже, що тобі час довести, що ти гідний наступного рівня твого навчання. Не витрачай забагато часу на пошуки туди. Ти можеш знайти її в Соборі Світла в центрі міста. Передай їй від мене вітання та доведи, наскільки ти гідний такого покликання. Хай Світло буде з тобою, {ім'я}.", ["en"] = "Divine Grace" },
    [94779] = { [1] = "Божественна благодать", [2] = "Хвала Елюні та твоєму Світлу, {ім'я}.\n\nПриблизно в цей час багато хто з нашого ордену опановує здібності, що відображають їхню віру в Елюну. Якщо знання служать мені, я вважаю, що те саме стосується і твого ордену.\n\nКоли твої справи в Дарнасі будуть завершені, я б розшукав одну з твоїх Верховних Жриць для подальшого навчання.", ["en"] = "Divine Grace" },
    [94789] = { [1] = "Поклик повітря", [2] = "Вітри Азероту вітають тебе, і невдовзі ти станеш поруч із наймогутнішими з наших братів та сестер. Я пишаюся тим, як далеко ти зайшов на своєму шляху. Твоє майбутнє справді світле.\n\nОпанувати стихію повітря непросто, але я вірю, що твої вміння допоможуть подолати будь-яке випробування.\n\nВирушай на північ, у нагір'я Араті. На його північних пагорбах знайдеш Вейріка Громожила. Він навчить тебе більшого.", ["en"] = "Call of Air" },
    [94792] = { [1] = "Приборкання звіра", [2] = "Багато мисливців надають перевагу подорожам у супроводі тварин. Зі звіром поруч ви виявите, що можете вижити навіть у найнебезпечніших обставинах. Як то кажуть, з другом все легше. Однак, знайти тварину-компаньйона потрібно робити обережно. Баланс природи крихкий і його завжди потрібно поважати.\n\nВізьміть цей жезл для приборкання з собою в ліс. З його допомогою ви зможете приручити скельного кабана та потренувати свої мисливські навички.", [3] = "Використайте жезл для приборкання, щоб приборкати кам'яного кабана. Потренуйте свої навички, а потім поверніть жезл для приборкання Джозефіні Карсон.", ["en"] = "Taming the Beast", ["tasks"] = { ["Tame a Rockhide Boar"] = "Приручити кам'яного кабана", ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [94793] = { [1] = "Тренування звіра", [2] = "Тепер у вас є сила приручити домашнього улюбленця, але ви також повинні здобути навички його дресирування. Для цього немає кращого за Ісаака Чана, лісника, який все життя провів у лісництві. Він дасть вам можливість дресирувати вашого нового улюбленця.\n\nПливай за вітром, юний {клас}.", [3] = "Поговоріть з Ісааком Чаном у Голдширі.", ["en"] = "Training the Beast" },
    [94817] = { [1] = "Збентежений спалах", ["en"] = "Confounding Flash" },
    [94818] = { [1] = "План дій у надзвичайних ситуаціях", ["en"] = "Contingency Plan" },
    [94819] = { [1] = "План дій у надзвичайних ситуаціях", [2] = "{ім'я}, твоя Верховна Жриця Мімс бажає прийняти тебе в Залізогарті. Поспішай, мій розумний друже, твоє наступне випробування швидко наближається. Хоча я й хотіла б бути свідком особливих обрядів твоєї раси, моє місце тут. Але нехай Світло супроводжує тебе у твоїх подорожах. Мімс все ще має бути в Містичному Окрузі, як тільки ти досягнеш міста. Вона чекатиме на тебе.", [3] = "Поговоріть з Верховною Жрицею Мімс у Залізогарті.", ["en"] = "Contingency Plan" },
    [94820] = { [1] = "План дій у надзвичайних ситуаціях", [2] = "Ваша раса така розумна, {ім'я}. Ми пишаємося тим, що можемо назвати вас союзниками. І з кожним днем, коли сонце заходить, ви та ваші родичі наближаєтеся до повернення свого міста, але з тягарем забезпечення безпеки ваших сімей у вигнанні. Це прагнення додому, мабуть, важко обтяжує вас.\n\nНещодавно надійшла звістка з Залізогарта. Там вас просили повернутися туди та поговорити з Верховною Жрицею Мімс у Містичному Окрузі. Я не змушуватиму її чекати. Нехай Елуна веде ваші подорожі.", ["en"] = "Contingency Plan" },
    [94821] = { [1] = "Збентежений спалах", [2] = "Нещодавно один священик відвідав наші зали, щоб знайти тебе, юний {раса}. Він сказав, що має на меті знайти тебе, і що тобі слід якомога швидше повернутися до Зали Таємниць у Залізогарті. Коли прибудеш, звернися до Верховної Жриці Мімс — вона розповість тобі більше.\n\nНехай Світло буде з тобою, {ім'я}.", ["en"] = "Confounding Flash" },
    [94822] = { [1] = "Збентежений спалах", [2] = "Ви привернули увагу нашого начальства, {ім'я}. Вони попросили вас якомога швидше вирушити до Зали Таємниць у Залізогарті. Очевидно, вони вважають, що ви вже довели свою спроможність і готові продовжити навчання. Коли ви туди потрапите, знайдіть Верховну Жрицю Мімс. Вона зможе направити вас далі. Удачі вам, і нехай Світло буде з вами.", [3] = "Поговоріть з Верховною Жрицею Мімс у Залізогарті.", ["en"] = "Confounding Flash" },
    [94823] = { [1] = "Збентежений спалах", [2] = "Благословить тебе Елуна, добра {раса}. Сподіваюся, твоє Світло знайде тебе та добре захистить цього дня.\n\nОдин із твоїх жерців нещодавно був тут і шукав тебе. Він згадав, що ти маєш якомога швидше повернутися до Зали Таємниць, щоб поговорити з Верховною Жрицею Мімс. Здається, ти добре вчинила, привернувши таку увагу. Я б не витрачала тут забагато часу — твій народ потребує тебе.", ["en"] = "Confounding Flash" },
    [94824] = { [1] = "Збентежений спалах", [2] = "Тобі час вирушати до Штормовія, {ім'я}. Верховна жриця Мімс у Залі Таємниць наказує тобі поговорити з нею. Має бути щось справді хороше чи справді погане, щоб Верховна жриця хотіла, щоб ти там був особисто, але, гадаю, ти зробив добре лише для себе, і це добре, що вона хоче поговорити з тобою.\n\nАле не гай забагато часу. Я б вирушив туди якомога швидше.", [3] = "Поговоріть з Верховною Жрицею Мімс у Залізогарті.", ["en"] = "Confounding Flash" },
    [94825] = { [1] = "Збентежений спалах", [2] = "Зовсім недавно один із ваших жерців був тут і шукав вас, {раса}. Він сказав, що якщо я вас побачу, я маю направити вас до Зали Таємниць. Він сказав, що це дуже важливо, але я б не надто хвилювався на вашому місці. Його поведінка здавалася позитивною... ніби це були гарні новини. Я б не витратив багато часу, щоб дістатися туди, якби був на вашому місці.\n\nХай Елуна буде з вами, добра {раса}.", ["en"] = "Confounding Flash" },
    [94826] = { [1] = "Збентежений спалах", [2] = "Хвала Елюні та твоєму Світлу, {ім'я}.\n\nПриблизно в цей час багато хто з нашого ордену опановує здібності, що відображають їхню віру в Елюну. Якщо знання служать мені, я вважаю, що те саме стосується і твого ордену.\n\nКоли твої справи в Дарнасі будуть завершені, я б звернувся до твоєї Верховної Жриці для подальшого навчання.", ["en"] = "Confounding Flash" },
    [94863] = { [1] = "Приборкання звіра", [2] = "Ви вже опанували приручення кабана, тепер час для наступного уроку. У лісі є лютіші друзі, і з обережністю ви можете заслужити їхню довіру.\n\nВізьміть цей жезл для приборкання та знайдіть Сірого Лісового Вовка. Пам'ятайте, що баланс природи має бути дотриманий. Доведіть свою майстерність мисливця ще раз.", [3] = "Використайте Палицю Приручення, щоб приборкати Сірого Лісового Вовка. Потренуйте свої навички, а потім поверніть Палицю Приручення Джозефіні Карсон.", ["en"] = "Taming the Beast", ["tasks"] = { ["Tame a Gray Forest Wolf"] = "Приручити сірого лісового вовка", ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [94864] = { [1] = "Приборкання звіра", [2] = "Ви довели свою спроможність, приборкавши кабана та вовка, а тепер настав час для вашого останнього випробування. Рівновага Елвінн залежить від поваги та майстерності. Візьміть цей жезл для приборкання та знайдіть молодого лісового ведмедя. Покажіть, що ви можете заслужити довіру навіть наймогутнішого компаньйона.\n\nЗавершення цього уроку поглибить вашу розуміння звірів.", [3] = "Використайте Палицю приборкання, щоб приборкати молодого лісового ведмедя. Потренуйте свої навички, а потім поверніть Палицю приборкання Джозефіні Карсон.", ["en"] = "Taming the Beast", ["tasks"] = { ["Tame a Young Forest Bear"] = "Приручіть молодого лісового ведмедя", ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [949] = { [1] = "Сутінковий табір", [2] = "Невідомо, що затіває Сутінковий Молот біля Глефи властителя. Але певно щось недобре.\n\nОбшукай їхній табір біля Глефи... Знайди щось, що може допомогти нам зрозуміти їхні наміри.\n\nБо ми маємо дізнатися про їхні наміри, перш ніж складати план дій.", [3] = "Знайдіть зачіпку в таборі Сутінкового Молота біля Глефи властителя.", [5] = "Ця книга надрукована вручну стародавньою мовою та майстерно проілюстрована.", ["en"] = "The Twilight Camp" },
    [94912] = { [1] = "Дитя природи", [2] = "Вітання, юний {клас}.\n\nВи чули про Коло Кенаріона? Гадаю, що ні. Це давній орден натуралістів та практиків друїдських мистецтв, дуже схожих на вас. У місті Штормовій ви знайдете нічного ельфа на ім'я Шелдрас Місячне Дерево. Він навчить вас, як дістатися до фортеці Кола Кенаріона на Калімдорі, місця під назвою Місячна Галявина.\n\nІдіть зараз. Вам потрібно багато чого навчитися, якщо ви хочете врятувати свій дім.", [3] = "Поговоріть з Шелдрасом Місячним Деревом у Штормовії.", ["en"] = "Child of Nature" },
    [94914] = { [1] = "Місячна галявина", [2] = "Усіх друїдів вітають у священних землях Мунґлейду. Хранитель Ремулос — охоронець Мунґлейду — стежить за всіма друїдами, які там зимують. Я навчу тебе заклинанню, яке дозволить тобі перенестися туди. Використовуй його щоразу, коли шукатимеш знань чи розради Мунґлейду.\n\nЩодо твого першого уроку тут, на Азероті, вируши до Мунґлейду та поговори з Дендритом Зоряним Сяйвом у Нічній Гавані про шлях, яким ти зараз йдеш. Удачі тобі, юний друїде.", [3] = "Використайте заклинання «Телепорт: Місячна галявина», щоб потрапити до Місячної галявини. Коли прибудете, поговоріть з Дендритом Зоряним Сяйвом у селі Найтгейн.", ["en"] = "Moonglade" },
    [94946] = { [1] = "Чарівне місто Даларан", [2] = "Я мав намір першим з нас ступити на Азерот, але нещодавні події з культом змінили мої плани. В результаті я залишуся тут, у Валанаарі, на деякий час. Але не хвилюйся, один з наших магів чекатиме на тебе після твого прибуття до Даларана. Я б закликав тебе дослідити Азерот, поки ми тут налагоджуємо наші справи. Ми звернемося до тебе, коли ти знадобишся.\n\nКоли будеш готовий, будь ласка, пройди до причалу біля цього будиночка та сядь там на скайкатер.", [3] = "Сядьте на корабель-небесоносець з острова Зефраса до міста Даларан і по прибуттю поговоріть з Данааріс Старгейл.", ["en"] = "The Magical City of Dalaran" },
    [94947] = { [1] = "Ласкаво просимо до Азероту", [2] = "Тут, унизу, великий світ, і нам потрібно, щоб наші люди почали його досліджувати. Ось тут-то й з'являєтеся ви.\n\nКірін-Тор є членом «Альянсу» однодумців. Фактичним серцем цього альянсу є місто Штормовій на півдні. Елаадрін попросила мене знайти когось, хто поїде до Штормовію та зустрінеться з тамтешнім лордом-регентом, людиною на ім'я Болвар Фордрагон.\n\nКоли ви будете готові, маги Кірін-Тор створили спеціальний портал для Високого Ордену, щоб отримати доступ до Штормовію.", [3] = "Відвідайте Небеснорожденний Портал до Штормовія та з'явіться до Болвара Фордрагона в Штормовійській фортеці.", ["en"] = "Welcome to Azeroth", ["tasks"] = { ["Take the Skyborne Portal to Stormwind"] = "Віднесіть Небесний портал до Штормграда" } },
    [95] = { [1] = "Помста Свена", [2] = "Я колись працював на одній з ферм на південному сході... до тих пір, коли темні вершники з перевалу Мертвого Вітру вдерлися на мою ферму та вбили мою родину, коли мене не було вдома!\n\nПовернувшись, я побачив темну постать, що копала щось біля амбара. Він втік, перш ніж я зміг його наздогнати, а я не міг затримуватися, бо за мною по п'ятах гналися темні вершники. Тож я так і не дізнався, що там було заховано.\n\nЯкщо ти можеш знайти те, що приховував цей незнайомець, я був би тобі дуже вдячний. Схованка знаходиться за старим пеньком біля амбара.", [3] = "Йдіть на ферму Свена і знайдіть те, що було закопано за старим пнем.", [5] = "Ви знайшли купу землі, яку поспішно копали, ніби комусь треба було щось швидко приховати... а часу було обмаль.", ["en"] = "Sven's Revenge" },
    [950] = { [1] = "Повернення до Ону", [2] = "Вдивляючись у сутінковий фоліант, можна збожеволіти. Текст починає плисти й танцювати перед очима після першого ж погляду, а колись прекрасний орнамент набуває гротескних форм.\n\nВам вдається лиш вирвати одну сторінку божевільних письмен, поки ви не знепритомніли.", [3] = "Принесіть Ону віднайдені божевільні письмена.", [4] = "{ім'я}. Ти {стать:повернувся:повернулась}.", [5] = "Хаотична, первісна магія оточує цей пергамент з письменами. Я відчуваю в ньому роботу древніх сил.\n\nБудемо сподіватися, що він розкриє наміри Сутінкового Молота на Темнобережжі...", ["en"] = "Return to Onu", ["tasks"] = { ["Insane Scribbles"] = "божевільні письмена", ["Insane Scribbles (Provided)"] = "божевільні письмена (видано)" } },
    [95065] = { [1] = "Час риболовлі", [2] = "Який краєвид... Найкращий, про який тільки може мріяти старий.\n\nРиба вже клює, хоча в мене залишилася остання наживка. Не думаю, що у вас є запасне рибальське спорядження? Звичайно, ні, вибачте. Я так хвилююся від думки про закидання ще однієї волосіні, що мені навіть не спадало на думку, що я можу бути одним з небагатьох, хто всюди носить із собою припаси.\n\nЧи не могли б ви допомогти оновити мій запас? У Кетрін Ліланд є асортимент рибальських товарів на захід від Торгового району вздовж каналів. Скажіть, що вас послав її старий Грей.", [3] = "Принесіть 1 Блискучу дрібничку та 3 Нічних Зміїників Гілберту Грею в гавані Штормовія.", ["en"] = "Fishin' Time", ["tasks"] = { ["Nightcrawlers"] = "опариші", ["Nightcrawlers (Provided)"] = "опариші (видано)", ["Shiny Bauble"] = "блискуча блешня", ["Shiny Bauble (Provided)"] = "блискуча блешня (видано)" } },
    [95189] = { [1] = "Герб Лордерона", [2] = "<Вивітрений герб із зображенням знака Лордерона. З огляду на те, що після падіння королівства залишилося так мало реліквій, хтось у Штормовії дуже хотів би його роздобути.>", [3] = "Поверніть Герб Лордерона леді Дені Кеннеді у Штормовій.", ["en"] = "Crest of Lordaeron", ["tasks"] = { ["Crest of Lordaeron"] = "Герб Лордерона", ["Crest of Lordaeron (Provided)"] = "Герб Лордерона (видано)" } },
    [95195] = { [1] = "Закривавлені знаки розрізнення", [2] = "<Стародавні знаки розрізнення Альянсу, схоже, належали солдату Лордерона. Ці руїни, ймовірно, заповнені подібними медалями, які живі родичі були б вдячні їм повернути.>", [3] = "Зберіть 10 закривавлених знаків розрізнення та віднесіть їх генералу Маркусу Джонатану в Штормовій.", ["en"] = "Bloodied Insignia", ["tasks"] = { ["Bloodied Insignia"] = "Закривавлені знаки розрізнення", ["Bloodied Insignia (Provided)"] = "Закривавлені знаки розрізнення (видано)" } },
    [952] = { [1] = "Діброва Древніх", [2] = "Якщо вже в тебе знайшовся час, щоб доставити звіт від Дерева-оракула, то, певно, тобі не складно буде віднести повідомлення в діброву Древніх, що у Темнобережжі, на південь від Аубердіну.\n\nСкоріше за все, тобі доведеться скористатись гіпогрифом, але я впевнений, що ти впораєшся з цим. Віднеси це Ону, древньому знань. Він чекає на звістку від мене так само, як я чекав на новини з поляни Оракула.", [3] = "Доставте повідомлення Фендрала Ону на Темнобережжя в діброву Древніх, що на південь від Аубердіну.", [4] = "Ох. {Клас}. Чим Ону може допомогти тобі?", [5] = "Ох, дякую, {ім'я}. Хоча це й дивно. Верховний друїд завжди так поспішає. Ліс знає, що всьому свій час. Шан'до Шаленство Бурі це розумів.", ["en"] = "Grove of the Ancients", ["tasks"] = { ["Fandral's Message"] = "повідомлення Фендрала", ["Fandral's Message (Provided)"] = "повідомлення Фендрала (видано)" } },
    [95250] = { [1] = "Огидні істоти", [2] = "Чого ти хочеш, {раса}? Хіба ти не бачиш, що війну треба виграти?\n\nМій господар уже вступив у бій і наказав мені залишатися на своєму посту. Однак минуло чимало часу.\n\nСумніваюся, що ти переживеш десять хвилин у бою, але якщо це зайняте твій простий розум, чому б тобі не пошукати Великого Маршала. Він найвищий і найстатніший герой, якого ти будь-коли бачив. Ти впізнаєш його, коли побачиш.", ["en"] = "Abominable Creatures", ["tasks"] = { ["Head of the Baron"] = "Голова барона" } },
    [953] = { [1] = "Падіння Амет'Арану", [2] = "На схід звідси знаходяться руїни Амет'Арану. Зараз їх населяють неупокоєні духи високородних, що колись мешкали в його стінах, але колись це було місце, де слуги Азшари вільно практикували свою могутню магію.\n\nМене послали дослідити руїни, і я натрапила на дві великі таблички, на яких була написана історія Амет'Арану і його падіння. Коли я читала руни, на мене напали духи, і я втекла.\n\nБудь ласка, якщо можеш, вирушай до руїн і розшифруй таблички замість мене.", [3] = "Вивчіть скрижалі, які розповідають про Амет'Аран і його падіння, а потім поверніться до стражниці Тиші Місяцеклинок на Темнобережжя.", [4] = "Коли ти вивчиш скрижалі та дізнаєшся про падіння Амет'Арану, я передам знання до Аубердіну і повідомлю про це Колу Древніх.", [5] = "До нас дійшло небагато записів з часів Війни Древніх, а особливо — періоду руйнування Колодязя Вічності. Що не дивно, враховуючи всі потрясіння та катаклізми, що відбувалися в той час.\n\nДякую, {ім'я}. Завдяки твоїй допомозі моя робота тут завершена, і я зможу надати Колу повну доповідь.", ["en"] = "The Fall of Ameth'Aran", ["tasks"] = { ["Read the Fall of Ameth'Aran"] = "Прочитайте «Падіння Амет'Арана»", ["Read the Fall of Ameth'Aran (Provided)"] = "Прочитайте «Падіння Амет'Арана» (видано)", ["Read the Fall of Ameth'Aran slain"] = "Прочитайте «Падіння Амет'Арана»: убито", ["Read the Lay of Ameth'Aran"] = "Прочитайте «Песню про Амет'Аран»", ["Read the Lay of Ameth'Aran (Provided)"] = "Прочитайте «Песню про Амет'Аран» (видано)", ["Read the Lay of Ameth'Aran slain"] = "Прочитайте «Песню про Амет'Аран»: убито" } },
    [95646] = { [1] = "Жахи нагір'я", [2] = "Ці солонуваті заболочені землі приховують велике джерело прісних південних вод. Мені боляче, та своїм корінням я відчуваю, як крізь ту гірську ущелину просочується скверна.\n\nТамтешні істоти, як і мешканці наших низин, болісніше реагують на отруту. Від початку свого існування вони не знали гартівної морської солі, тому мають мало сил проти такого зла.\n\nВирушай у те нагір'я й принеси мені кореневу серцевину нагірного жаху.", [3] = "Убийте нагірного жаха на розкопках і принесіть його кореневу серцевину Ретілю Вартовому Природи в Заболотті.", ["en"] = "Horrors in the Highland", ["tasks"] = { ["Horrible Rootcore"] = "Жахливе кореневе осердя" } },
    [95647] = { [1] = "Загублений у хащах", [2] = "Мій чоловік Ардін має рідкісний дар відчувати природу. Він видереться на будь-яку вершину, щоб зібрати трави й квіти для моєї алхімії та поповнити наші полиці й комору.\n\nТа боюся, він потрапив у біду. Тут проходила експедиція розкопувачів у пошуках припасів. Серед іншого вони розповідали про велетенські трави, яких ніколи раніше не бачили. Ардін сказав, що мусить побачити їх на власні очі. Його вже надто довго немає!\n\nБуду вдячна за будь-яку звістку про нього.", [3] = "Знайдіть Ардіна Трав'яного на розкопках.", ["en"] = "Lost in the Thicket Things", ["tasks"] = { ["Learn what happened to Ardin Grassman"] = "Дізнатися, що сталося з Ардіном Трав'яним" } },
    [957] = { [1] = "Башал'Аран", [2] = "Цю печатку, що утримувала мою в'язницю, було створено одним з наймогутніших високородних. В Амет'Арані — таких самих руїнах на південь звідси — досі горить древнє синє полум'я. Цю печатку можна знищити тільки у ньому.\n\nБудь {стать:обережним:обережною} в тих руїнах, {ім'я}...", [3] = "Знищте древню печатку місячного каменю біля древнього полум'я в Амет'Арані, після чого поверніться до Астеріона в Башал'Аран.", [4] = "Чесно кажучи, {ім'я}, я боюся... Боюся, що ви, і все це — лише плід мого божевільного розуму. Чи можете ви уявити, які це тортури? I... Прошу, покваптесь.", [5] = "Я вільний, {ім'я}! Нарешті я можу на власні очі побачити, як змінився наш світ... Я знав про це лише уривками. Подумати тільки, коли я востаннє гуляв на волі, ще існувало Джерело, а високородні засідали при дворі з Азшарою, нашою улюбленою королевою.\n\nЯ відчуваю, що мій тюремник, мій колишній господар, Атрікус, ще живий... І моє почуття безнадійності поступається місцем думкам про помсту.", ["en"] = "Bashal'Aran", ["tasks"] = { ["Destroy the seal at the ancient flame"] = "Знищи печатку біля стародавнього полум'я", ["Destroy the seal at the ancient flame (Provided)"] = "Знищи печатку біля стародавнього полум'я (видано)", ["Destroy the seal at the ancient flame slain"] = "Знищи печатку біля стародавнього полум'я: убито" } },
    [95795] = { [1] = "Загиблий у болоті", [2] = "<Ви накриваєте тіло дворфа його плащем.>\n\nВирушайте в Приозер'я й особисто розкажіть Доріну Лезоспіву, що сталося з його братом на розкопках.", [3] = "Поверніться до Доріна Лезоспіва.", [5] = "Ох, ні...\n<Він ховає обличчя в долонях і ридає.>\n\nЯ мав піти з ними.\n\nБільшість речей, які я кував, були для нього. Хотів зробити сюрприз, але не встиг закінчити, коли він прийшов по спорядження для подорожі.\n\nТепер усе готове, а в мене не стане духу ні перекувати це, ні продати.\nБери. Це найменше, що можу зробити для тебе за цю сумну звістку.", ["en"] = "Fallen in the Fen" },
    [95809] = { [1] = "Сплетене серце", [2] = "Мені треба трохи перепочити, перш ніж самостійно вибиратися звідси.\n\n<Він дістає з наплічника кілька очеретин і швидко сплітає з них серце.>\n\nВізьми це й віднеси Кейтлін. Скажи їй, що я скоро буду вдома! Завдяки тобі шлях тепер вільний, тож я зберу свої оберемки й піду твоїм слідом.\n\nДякую.", [3] = "Поверніться до Кейтлін Трав'яної в гавані Менетілів.", [4] = "Я вже страшенно хвилююся за нього!", [5] = "Боже мій, як жахливо!\n\nДякувати Світлу, що він серед тих, хто вижив.\n\n<Вона притискає сплетене з очерету серце до грудей.>\n\nПочну готувати для нього ситну вечерю. Дякую, що приніс мені це. Візьми дещо на знак нашої вдячності.", ["en"] = "Heartwoven", ["tasks"] = { ["Reed-woven Heart (Provided)"] = "Серце, сплетене з очерету (видано)" } },
    [95810] = { [1] = "Доставка загубленої реліквії", [2] = "Ви підіймаєте уламок кам'яно-механічного автомата. На дотик він не схожий ні на що знайоме: це складений матеріал невідомої будови. Безперечно, це радше частина «пристрою», ніж просто «уламок».\n\nМожливо, сам розвідувач Вельґар на своїх розкопках зможе розповісти щось корисне про цю реліквію.", [3] = "Віднесіть реліквію титанів розвідувачу Вельґару на розкопках у Заболотті.", ["en"] = "Lost Relic Carry", ["tasks"] = { ["Titan Relic"] = "Реліквія титанів" } },
    [95998] = { [1] = "На свіжому повітрі", [2] = "Ну, привіт, {клас:н}. Бачу, що в тебе вигляд шукача пригод. Молодець. Світу потрібно більше нас, неспокійних душ, які прагнуть багатства та слави.\n\nСвіт величезний, і тобі потрібно навчитися процвітати в дикій природі, щоб досягти успіху. Не впевнений, як твої навички перебування на природі, але, гадаю, міг би навчити тебе чогось, якщо ти схильний до навчання.\n\nСядьте біля вогню, влаштуйтеся зручніше. Я проведу вас крізь це.", [3] = "Сядьте біля Базового Багаття Сема, набравши /sit у вікні чату, та зачекайте, поки отримаєте баф «Посилений відпочинок».", ["en"] = "The Great Outdoors", ["tasks"] = { ["Gain the Boosted Rest buff"] = "Отримайте бафф «Посилений відпочинок»", ["Use the /sit emote near the campfire"] = "Використайте емодзі /сидіти біля багаття" } },
    [95999] = { [1] = "РОЗШУКУЄТЬСЯ: Сміттєспалювач Гар'їм", [2] = "Розшукується! Спалитель Гар'їм, ватажок вторгнення орків у Долину Рендер. Нібито співпрацює з Чорною Скелею з Замку Кам'яної Варти.\n\nОстерігайтеся Спалителя Гар'їма. Він та його Заклиначі Тіні надзвичайно небезпечні. Щедра винагорода буде надана будь-якій сміливій душі, яка зможе надати магістрату Соломону доказ загибелі Спалителя Гар'їма.", [3] = "Доставте зламаний посох сміттєспалювача Гар'їма магістрату Соломону в Лейкширі.", [4] = "Що це в тебе там, {раса:к}?", [5] = "Чудова робота, {ім'я:к}! Спопеляч Гар'ім готувався зміцнити оборону фортеці Кам'яної Варти. Завдяки цій перемозі ми ще можемо повернути фортецю!", ["en"] = "WANTED: Incinerator Gar'im", ["tasks"] = { ["Broken Staff of Incinerator Gar'im"] = "Зламаний посох сміттєспалювача Гар'їм" } },
    [96031] = { [1] = "Кемпінг 101: Шкіряна справа", [2] = "Ти став шкіряником. Молодець, {клас}. Гадаю, я знаю когось, хто може навчити тебе, як зробити собі намет, у якому буде прохолодно в спекотні дні та сухо в дощові.\n\nЗ гарним наметом над головою ти гарантовано отримаєш весь необхідний відпочинок, щоб залишатися бадьорим під час подорожей.", [3] = "Поговоріть з Греттою Файнспіндл у Залізогарті, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Leatherworking", ["tasks"] = { ["Raise your leatherworking skill to 20"] = "Підвищте свою майстерність обробки шкіри до 20" } },
    [96044] = { [1] = "Кемпінг 101: Ковальська справа", [2] = "Отже, ви стали ковалем. Це чудовий вибір, якщо ви хочете бути впевнені, що ваші клинки ніколи не затупляться.\n\nГадаю, я знаю когось, хто може допомогти вам у цьому, навчивши вас, як виготовити точильне колесо. Принесіть одне з них у свій табір, і всі воїни та розбійники в окрузі вишикуються в чергу, щоб відточити свою зброю.", [3] = "Поговоріть з Тогнусом Флінтфаєром у Хараносі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Blacksmithing", ["tasks"] = { ["Raise your blacksmithing skill to 20"] = "Підвищіть навичку ковальства до 20" } },
    [96045] = { [1] = "Кемпінг 101: Алхімія", [2] = "Тепер, коли ти опанував Алхімію, я також можу навчити тебе, як створити Колодязь Мани для твого табору, як тільки ти трохи навчишся. Збудуй один з них, і всі цілителі та чаклуни збігатимуться, щоб насолодитися освіжаючим смаком.", [3] = "Поговоріть з Восуром Брактелем у Залізогарті, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Alchemy", ["tasks"] = { ["Raise your alchemy skill to 20"] = "Підвищте свою навичку алхімії до 20" } },
    [96046] = { [1] = "Основи таборування: гірництво", [2] = "Гірництво — не найефектніше ремесло, але це чесна праця й чудовий фах, який тобі варто опанувати.\n\nЗдається, я знаю декого, хто навчить тебе створювати магнетит для табору. Зроби один — і кожен, хто полюбляє махати мечем, охоче збереться біля твого вогнища, щоб відчути додаткову силу, яка підвищить його бойову міць.", [3] = "Поговоріть з Ярром Молотокаменем у Хараносі, щоб навчитися створювати табірний предмет для своєї професії, коли досягнете належної майстерності.", ["en"] = "Camping 101: Mining", ["tasks"] = { ["Raise your mining skill to 20"] = "Підвищте свій рівень майнінгу до 20" } },
    [96047] = { [1] = "Кемпінг 101: Перша допомога", [2] = "Отже, ви почали навчатися наданню першої допомоги? Це почесне... і прагматичне прагнення як {клас}.\n\nГадаю, я знаю когось, хто може навчити вас, як створити аптечку першої допомоги для вашого табору. Травми — це реальність у світі пригод, і пропонування так необхідного лікування у вашому таборі може навіть врятувати життя.", [3] = "Поговоріть з Тамнером Полом у Хараносі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", [5] = "Ось і все! Тепер ти можеш самостійно виготовити аптечку першої допомоги. Більшість людей не надто любить табори в центрі міста, тож випробувати аптечку доведеться в дикій місцевості.\n\nІ ще пам'ятай: жоден табір не обходиться без багаття. Воно знадобиться тобі, щоб облаштувати табір. Більшість кухарів можуть навчити розпалювати вогонь. Якщо ти ще не опанував основи куховарства, звернися до інструктора.", ["en"] = "Camping 101: First Aid", ["tasks"] = { ["Raise your first aid skill to 20"] = "Підвищіть навичку першої допомоги до 20" } },
    [96050] = { [1] = "Кемпінг 101: Риболовля", [2] = "Можливо, ви так не думаєте, але ваші навички рибалки можуть стати в нагоді в таборі.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити акваріум для вашого табору. Ви можете використовувати цей інструмент, щоб подарувати трохи радості собі та своїм товаришам-шукачам пригод. Щасливий шукач пригод – це сильний шукач пригод, і я впевнений, що ваші бойові здібності це відображатимуть.", [3] = "Поговоріть з Пакстоном Гантером біля озера Айсфлоу в Дун-Морогу, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Fishing", ["tasks"] = { ["Raise your fishing skill to 20"] = "Підвищте свій рівень риболовлі до 20" } },
    [96055] = { [1] = "Кемпінг 101: Трав'ярство", [2] = "Мені здається, ти набув певних навичок у травництві. Збирання квітів — це не просто для розваг, знаєш. Це може бути корисним... і прибутковим.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити ароматичну свічку для твого табору. Піднесений дух — ключовий компонент для підтримки цілителів та заклинателів у бою, а ароматична свічка може дати підкріплення, яке маги точно оцінять.", [3] = "Поговоріть з Рейною Стоунгіч у Залізогарті, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", [5] = "Ось і все — тепер ти можеш власноруч виготовити пахощеву свічку. Більшості містян не до вподоби табори посеред міста, тож, якщо хочеш її випробувати, доведеться вирушити в дику місцевість.\r\n\r\nІ пам'ятай: жоден табір не обходиться без багаття. Воно знадобиться тобі ще до того, як почнеш облаштовувати табір. Більшість кухарів можуть навчити тебе розпалювати вогонь. Якщо ти ще цього не зробив, знайди когось, хто навчає кулінарії, та опануй основи.", ["en"] = "Camping 101: Herbalism", ["tasks"] = { ["Raise your herbalism skill to 20"] = "Підвищте свій рівень навичок травництва до 20" } },
    [96056] = { [1] = "Кемпінг 101: Зняття шкури", [2] = "Вміння вміло збирати шкури та шкури полеглих звірів – одна з найцінніших навичок, якими може володіти шукач пригод.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити похідне крісло для вашого табору. Іноді важливо просто розслабитися, і ви можете використати деякі з цих зібраних шкур, щоб зробити зручне крісло. Трохи відпочинку може допомогти вам бути у найкращій формі та вдарити там, де це потрібно, наступного разу, коли ви опинитеся в запиленій хаосі.", [3] = "Поговоріть з Балтусом-Каменолесосом у Залізогарті, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Skinning", ["tasks"] = { ["Raise your skinning skill to 20"] = "Підвищте свою навичку зняття шкури до 20" } },
    [96057] = { [1] = "Кемпінг 101: Кравецька справа", [2] = "Кравецька справа — це напрочуд потужна навичка, в яку варто інвестувати, і я впевнений, що вона вам добре послужить.\n\nЯ знаю людину, яка може навчити вас, як створити прапор фракції для вашого табору, за умови, що у вас є для цього відповідні навички. Натхнення та моральний дух є ключовими складовими успіху на будь-якому полі бою, а натхненний прапор може значною мірою зарядити вас енергією.", [3] = "Поговоріть з Утраром Трексом у Залізогарті, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Tailoring", ["tasks"] = { ["Raise your tailoring skill to 20"] = "Підвищте свою кравецьку майстерність до 20" } },
    [96058] = { [1] = "Кемпінг 101: Інженерія", [2] = "Такі інженери, як ви, можуть створювати всілякі штуки, ботів та бомби для розваги та прибутку.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Бота-Реагента для вашого табору. Цей корисний автомат може допомогти вам добре постачатися, щоб у вас та ваших союзників ніколи не закінчувалися матеріали, необхідні для підживлення ваших заклинань.", [3] = "Поговоріть з Бронк Газлгір у Хараносі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Engineering", ["tasks"] = { ["Raise your engineering skill to 20"] = "Підвищте свій інженерний рівень до 20" } },
    [96059] = { [1] = "Кемпінг 101: Чарівний", [2] = "Тепер, коли ви розпочали свою подорож до чарівництва, я думаю, що можу навчити вас, як створити Зачаровану лютню для вашого табору, як тільки ви вивчите всі основи.\n\nТак важливо знаходити розваги під час відпочинку, і ця частинка магії може допомогти вам бути готовими до всіляких випробувань, коли ви знову вирушите на стару запилену стежку.", [3] = "Поговоріть з Тонісом Пілларстоуном у Залізогарті, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Enchanting", ["tasks"] = { ["Raise your enchanting skill to 20"] = "Підвищте свою майстерність зачарування до 20" } },
    [96137] = { [1] = "Кинджал Іри", [2] = "Невеликий кинджал, що належав самопроголошеному рейнджеру Ірі, який оберігав ліси від нападів на подорожніх звірів.\n\nПоки дух Іри все ще блукав лісами, можливо, її незавершеною справою було позбутися ворґів, які продовжують забирати жертв по всьому лісу.", [3] = "Перемогти 10 Молодих Чорних Руйнівників та 7 Чорних Руйнівників, а потім повернутися до Сірри Вон'Інді в Темноширі за додатковою інформацією.", [4] = "Що це в тебе там?", [5] = "Іра? Ти впевнений? Схоже, ця жінка ще за життя була мало не привидом. Дивуюся, що тобі вдалося її знайти.\r\n\r\nНе хвилюйся, я подбаю про цей кинджал як слід.", ["en"] = "Ira's Dagger", ["tasks"] = { ["Black Ravager slain"] = "чорний спустошник: убито", ["Ira's Dagger"] = "Кинджал Іри", ["Ira's Dagger (Provided)"] = "Кинджал Іри (видано)", ["Young Black Ravager slain"] = "молодий чорний спустошник: убито" } },
    [96138] = { [1] = "Лук Мерріка", [2] = "Лук, залишений духом Мерріка Валора, відомого Вартового, який пишався тим, що оберігав дороги від ворогів.\n\nПоки дух Мерріка все ще блукає дорогами, можливо, його незавершеною справою було позбутися загарбників біля його будинку на Рейвен-Гілл. Можливо, його дух турбують огри на південь від міста.", [3] = "Перемогти 8 воїнів-розколотих кулаків та 4 таскмайстрів-розколотих кулаків, а потім повернутися до Сірри Вон'Інді в Темноширі за додатковою інформацією.", ["en"] = "Merrick's Bow", ["tasks"] = { ["Merrick's Bow"] = "Лук Мерріка", ["Merrick's Bow (Provided)"] = "Лук Мерріка (видано)", ["Splinter Fist Taskmaster slain"] = "орудар Сколотого Кулака: убито", ["Splinter Fist Warrior slain"] = "воїн Сколотого Кулака: убито" } },
    [96139] = { [1] = "Родина Валор", [2] = "У такі темні часи важливо пам'ятати наших героїв так само, як і наших ворогів. Темношир не стояв би досі, якби не хоробрість таких людей, як добра леді Алтея, або тих, хто загинув у Рейвен-Гілл.\n\nВи багато читали про Рейвен-Гілл? Ні, звичайно, ні. Його історія була стерта разом з його людьми. У моїй бібліотеці, хоч і вражаюча, мало що є на цю тему.\n\nЯкщо ви щось знайдете, я буду вдячний, якщо принесете це сюди. Ці люди заслуговують на те, щоб їх пам'ятали.", [3] = "Пошукайте на Рейвен-Гілл щось цікаве та поверніться до Сірри Вон'Інді в Темноширі.", [4] = "Тобі вдалося щось знайти? Я вже майже не сподіваюся.", [5] = "Схоже, цей фоліант розповідає про родину Велорів. Здається, я чув про декого з них. Хороші люди. Хоча не певен, що вони заслуговують на цілу книгу.\r\n\r\nЯ зроблю для тебе копію фоліанта. Якщо під час мандрів натрапиш на щось іще, пов’язане з ними, я залюбки заберу це з твоїх рук.", ["en"] = "The Valor Family", ["tasks"] = { ["Raven Hill Tome"] = "Том Рейвен Гілл" } },
    [96243] = { [1] = "Поклик землі", [2] = "Тобі давно час звернути увагу на землю, хоробрий шамане. Стихії вже поколюють твою шкіру, але щойно ти заговориш з каменем, сама земля затвердіє під твоїми підошвами — і в твоїй душі.\n\nШукай Тео МолотШторму в Долині Колдрідж. Ти знайдеш його в Анвілмарі, фортеці, викуваній молотом, вогнем і волею.", ["en"] = "Call of Earth" },
    [96394] = { [1] = "Неспокійні мерці", [2] = "Щось потурбувало гробниці внизу в Залі Танів, і з глибини склепінь чути дивні звуки. Духи померлих сплять легко, і що б там не відбувалося, схоже, їх налякало.\n\nСпускайтеся туди і подивіться, що ви можете для нас зробити. Якщо хтось із померлих не спить — що ж, відпустіть їх назад!", [3] = "Убийте 15 розлючених привидів, 10 змучених душ та заспокоїте дух Анвілмара.", [5] = "О, добре, отже, з цим покінчено. Не можу ж я дозволити іншим доглядачам відмовлятися заходити до зали й виконувати свої обов'язки через «привидів» та «розлючених мерців», чи не так?", ["en"] = "The Restless Dead", ["tasks"] = { ["Enraged Apparition"] = "Розлючена привид", ["Enraged Apparition (Provided)"] = "Розлючена привид (видано)", ["Enraged Apparition slain"] = "Розлючена привид: убито", ["Tormented Soul"] = "Змучена душа", ["Tormented Soul (Provided)"] = "Змучена душа (видано)", ["Tormented Soul slain"] = "Змучена душа: убито" } },
    [96408] = { [1] = "Відвідувач Дун-Морога", [2] = "Минулої ночі один з наших альпіністів помітив багаття на схилі пагорба на сході. Здається, воно досить високо, з видом на кар'єр Гол'Болар.\n\nЙмовірно, нічого страшного, але я хотів би, щоб ви пішли перевірити той табір. Якщо вони дружелюбні, то нічого страшного. Якщо ні... ну, ви знаєте, що робити.", [3] = "Дослідіть кемпінг з видом на кар'єр Гол'Болар.", [5] = "Вітаю, друже. Як справи?", ["en"] = "A Visitor to Dun Morogh" },
    [96606] = { [1] = "На свіжому повітрі", [2] = "Вітаю, {клас}. Бачу, що у вас вигляд шукача пригод. Це добре. Світу потрібно більше нас, неспокійних душ, які прагнуть багатства та слави.\n\nТобі потрібно навчитися процвітати в дикій природі, щоб досягти успіху в цій сфері. Не впевнений, як у тебе справи з навичками активного відпочинку на природі, але я, мабуть, можу тебе дечому навчити, якщо ти схильний до навчання.\n\nСядьте біля вогню та влаштуйтеся зручніше. Я тобі все розповім.", [3] = "Сядьте біля базового багаття Ліріни, набравши /sit у вікні чату, і зачекайте, поки отримаєте посилення відпочинку.", ["en"] = "The Great Outdoors", ["tasks"] = { ["Gain the Boosted Rest buff"] = "Отримайте бафф «Посилений відпочинок»", ["Use the /sit emote near the campfire"] = "Використайте емодзі /сидіти біля багаття" } },
    [96608] = { [1] = "На свіжому повітрі", [2] = "Вітаю, {клас:к}. Одразу видно, що в тобі живе дух шукача пригод. І це добре. Світу потрібно більше таких невгамовних душ, що шукають багатства й слави.\n\nЩоб досягти успіху в цій справі, тобі доведеться навчитися виживати в дикій природі. Не знаю, наскільки ти знаєшся на житті просто неба, але, якщо маєш бажання, я можу дечого тебе навчити.\n\nСідай біля вогню та влаштовуйся зручніше. Я все поясню.", [3] = "Сядьте біля звичайного вогнища Еріка, ввівши /sit у вікні чату, і зачекайте, доки не отримаєте ефект «Покращений відпочинок».", [4] = "Уміння виживати просто неба вкрай важливі. Добре відпочилий і підготовлений шукач пригод має значно більше шансів вижити за такого способу життя.", [5] = "Тепер, коли ми розібралися з основами, чому б тобі не опанувати ремесло в наставників у сусідньому селищі? Вони також навчать тебе створювати табірне оснащення, що відповідає твоєму новому фаху.", ["en"] = "The Great Outdoors", ["tasks"] = { ["Gain the Boosted Rest buff"] = "Отримайте бафф «Посилений відпочинок»", ["Use the /sit emote near the campfire"] = "Використайте емодзі /сидіти біля багаття" } },
    [96626] = { [1] = "Основи таборування: куховарство", [2] = "Отже, ви хочете дізнатися більше про кемпінг, га? Молодець, {клас}. Перший крок, який має зробити будь-який шукач пригод, — це стати кухарем і навчитися розводити багаття.\n\nКулінарія — це не просто приготування смачної їжі. Це також основа вашого табору.", [3] = "Поговоріть з Томасом у Голдширі, щоб навчитися бути кухарем.", ["en"] = "Camping 101: Cooking", ["tasks"] = { ["Learn cooking from Tomas in Goldshire"] = "Навчіться готувати у Томаса в Голдширі" } },
    [96627] = { [1] = "Шукач пригод", [2] = "{ім'я}, ви вже довели свою компетентність як захисник. Саме тому я довіряю вам незвичайне завдання.\n\nЯ чув про нового шукача пригод неподалік, біля Голдшира. Сходіть і подивіться, що він робить.", [3] = "Поговоріть із Семом Сарспаріллою поблизу Голдшира.", ["en"] = "The Adventurer" },
    [96628] = { [1] = "Шукач пригод", [2] = "Зажди, {ім'я:к}. Перш ніж ти відважишся пройти тим тунелем, маю до тебе ще одне прохання. Мої горяни доповіли про шукача пригод, який з'явився неподалік Караноса. Можеш доставити йому ці припаси?", [3] = "Доставте пакунок з припасами Еріку Ясномолоту неподалік Караноса.", [4] = "Ти прийшов дізнатися, як влаштовувати табір у дикій природі?", [5] = "Кажеш, це від горянинів? Ага, мені вони стануть у пригоді. Дякую тобі, {клас:к}.\n\nГей, ти й сам схожий на шукача пригод. Хочеш навчитися влаштовувати табір?", ["en"] = "The Adventurer", ["tasks"] = { ["Deliver the Supply Bundle to Eric Brighthammer near Kharanos."] = "Доставте пакунок з припасами Еріку Ясномолоту неподалік Караноса.", ["Supply Bundle"] = "пакунок з припасами", ["Supply Bundle (Provided)"] = "пакунок з припасами (видано)" } },
    [96629] = { [1] = "Основи таборування: куховарство", [2] = "То ти хочеш більше дізнатися про таборування, га? Молодець, {клас:к}. Перший крок для кожного шукача пригод — стати кухарем і навчитися розпалювати вогнище.\n\nКуховарство — це не лише смачні страви. Це ще й основа твого табору.", [3] = "Поговоріть із Брагом Пивзнором у Хараносі, щоб навчитися куховарства.", [4] = "Добре вогнище — основа кожного доброго табору.", [5] = "З цим ти зможеш розбити табір будь-де в дикій місцевості. Ти опанував лише основи, тож поки не зможеш розставити навколо нього багато начиння.\r\n\r\nПідвищуй навичку кулінарії — і, можливо, навчишся розпалювати ще більші багаття.\r\n\r\nОснов облаштування табору можна також навчитися в наставників інших ремесел, якщо ти достатньо вправний у них.", ["en"] = "Camping 101: Cooking", ["tasks"] = { ["Learn cooking from Gremlock Pilsnor in Kharanos"] = "Навчіться куховарства у Брага Пивзнора в Хараносі" } },
    [96630] = { [1] = "Шукач пригод", [2] = "<Щоденник виглядає досить простим, детально описує життя та пригоди когось, про кого ви ніколи не чули.\n\nЄ кілька записів, де згадується кемпінг. Здається, це досить... весело.>", [3] = "Принесіть щоденник Ліріні Сутінковий Клинок біля Доланаара.", ["en"] = "The Adventurer", ["tasks"] = { ["Lost Journal"] = "Втрачений щоденник", ["Lost Journal (Provided)"] = "Втрачений щоденник (видано)" } },
    [96634] = { [1] = "Основи таборування: куховарство", [2] = "Отже, ви хочете дізнатися більше про кемпінг, га? Молодець, {клас}. Перший крок, який має зробити будь-який шукач пригод, — це стати кухарем і навчитися розводити багаття.\n\nКулінарія — це не просто приготування смачної їжі. Це також основа вашого табору.", [3] = "Поговоріть із Зарріном у Доланаарі, щоб навчитися бути кухарем.", ["en"] = "Camping 101: Cooking", ["tasks"] = { ["Learn cooking from Zarrin in Dolanaar"] = "Навчіться готувати у Зарріна в Доланаарі" } },
    [967] = { [1] = "Вежа Алталакса", [2] = "Мій учитель, Дельґрен Очиститель — паладин, який люб'язно запропонував свою допомогу в захисті наших лісів від сил демонів і невмерлих. Він багато чого повідав мені про Святе Світло та мистецтво бою.\n\nДельґрен має негайно дізнатися про діяльність культу.\n\nТи знайдеш його далеко на південь звідси, на заставі Маєстри в Ясенедолі. Поквапся — я боюся, що загроза від культу Темного Пасма зростає з кожною годиною.", [3] = "Передайте лист Балтула Дельґренові Очистителю в Ясенеділ.", [4] = "У тебе є щось для мене, {клас:к}?", [5] = "Можу сказати, що ти виглядаєш надто добре {стать:екіпірованим:екіпірованою}, як для гінця, чи не так? Гадаю, Балтул хотів впевнитись, що його лист потрапить до мене. Подивимося, що він написав...\n\nЦе тривожні новини. Коли знаходять невмерлих або демонів, я допомагаю стражам знищити їх.\n\nСпочатку традиції нічних ельфів були надто незвичними для мене, але з часом я почав надзвичайно поважати їх як союзників.", ["en"] = "The Tower of Althalaxx", ["tasks"] = { ["Letter to Delgren"] = "лист до Дельґрена", ["Letter to Delgren (Provided)"] = "лист до Дельґрена (видано)" } },
    [968] = { [1] = "Сили підземні", [2] = "Попри те, що ця книга жахливо пошарпана і потерта, на її обкладинці все ще можна прочитати назву:\n\n\"Сили підземні\"\n\nУсередині книги — перелік невимовних імен зі зловісними назвами, методи поклоніння та улюблені жертвоприношення... які включають живих розумних створінь.\n\nНа внутрішньому боці обкладинки є слова: \"Руни й чаклунства Кісткохвата, Закинута Печера, Залізогарт. Власник: Ґерріґ Кісткохват\".\n\nЯкщо Кісткохват торгує такими книгами, можливо, його зацікавить і ця.", [3] = "Принесіть книгу \"Сили підземні\" Ґерріґу Кісткохвату в Закинуту Печеру, що в Залізогарті.", [4] = "Вітаю, {стать:пане:пані}.\n\nЧи можуть вас зацікавити мої фоліанти?", [5] = "А, примірник \"Сил підземних\". Цікавий текст, так. А для когось і корисний...\n\nАле ця книга в жахливому стані. І погляньте-но! Нотатки на полях — майже на кожній сторінці!\n\nХм... Я пам'ятаю цей примірник. Я продав його Болґару торік. Ви... його знаєте? Так, я так і думав. У вас в очах таке ж полум'я!\n\nНу, що ж, друг Болґара — мій друг. І ми дбаємо про своїх, правда?", ["en"] = "The Powers Below", ["tasks"] = { ["Book: The Powers Below"] = "книга \"Сили підземні\"", ["Book: The Powers Below (Provided)"] = "книга \"Сили підземні\" (видано)" } },
    [97] = { [1] = "Легенда про Сталвана", [2] = "Негайно повідом командиру Чорнобривій, що почерк збігається, {ім'я}! Її підозри підтвердилися!", [3] = "Повідомте про новини командира Чорнобриву.", [4] = "Так, {ім'я}?", [5] = "Я так і знала! Гарна робота, {ім'я}.", ["en"] = "The Legend of Stalvan" },
    [97005] = { [1] = "Чол'арук Пожирач", [2] = "Ходять чутки про жахливу гидоту, яка влаштувала собі лігво в печері на північний захід звідси, на плато, відомому як Терновий пагорб. Острий Грив називає її Чол'арук або \"Пожирач\", і ті, хто її бачив, кажуть, що вона настільки величезна, що може проковтнути орка цілком.\n\nМало хто вірить таким казкам, але я вірю... бо сам бився з подібним. Заради тих, кого я втратив через ці істоти, ця істота має померти.\n\nЗберіть сильних союзників і знайдіть лігво Чол'арук. Убийте гидоту і принесіть мені її голову.", [3] = "Принесіть голову Чол'арука до Бейнхема в Степах.", ["en"] = "Chol'aruk the Ravener", ["tasks"] = { ["Chol'aruk's Head"] = "Голова Чол'арука" } },
    [97263] = { [1] = "Ваша посилка прибула", [2] = "<Біля поштової скриньки залишилося кілька загублених посилок. Ви помічаєте, що одна з них позначена для доставки з Піку Ері, до Залізогарта, до Елдруна Бурелома. Вона позначена як «терміново».>", [3] = "Доставте загублений пакет Елдруна.", [4] = "Що це в тебе там?", [5] = "Що?! Я щодня ходив до поштової скриньки біля банку й чекав на цей пакунок! Цьому місту треба щось робити з плануванням. Не те що на Гніздовому Піку — там легко знайти дорогу!\r\n\r\nПогляньмо, що тут... інструменти для різьблення тотемів... запасна сокира... якийсь гоблінський пристрій? Я цього не замовляв! А, просто відішлю назад.\r\n\r\nЕ-е, тобто... дякую, що приніс усе це. Ось дещо за клопіт.", ["en"] = "Your Package Has Arrived", ["tasks"] = { ["Misplaced Package"] = "Загублений пакет", ["Misplaced Package (Provided)"] = "Загублений пакет (видано)" } },
    [97277] = { [1] = "Ґрунд і Ґозвін", [2] = "Ох, стояв я спиною, готував печеню з вепра, аж тут чую — мій друзяка Ґозвін верещить так, ніби його ріжуть!\n\nОбернувся — тільки люті ікла та якась розмита пляма. А лапи які здоровезні! Сніжний леопард тягнув кудись свою гномську здобич. Я схопив рушницю й пальнув над звіром. Той кинув Ґозвіна й дременув геть.\n\nНа щастя, старий Ґоз відбувся лише кількома глибокими подряпинами. Повертайся до табору на північно-західних пагорбах і забери журнал механіка Ґозвіна. І якщо побачиш того сніжного леопарда — убий його!", [3] = "Знайдіть табір Ґрунда й Ґозвіна на пагорбах на північному заході. Поверніть журнал механіка Ґозвіна та вбийте сніжного леопарда-скрадача.", [4] = "Бідолашний Ґоз більше переймається своїм механічним ходоком, ніж собою. Каже, якщо хтось заволодіє його журналом механіка, йому гаплик. Ха! Ось чому я казав йому залишати роботу вдома!", [5] = "Ага, мене не дивує, що той сніжний леопард ласував вепром, якого ми збиралися засмажити!\n\nТепер, коли ти повернув журнал Ґозвіна, він матиме на одну турботу менше. Може, нарешті зосередиться на одужанні.\n\nДякую, {ім'я}. Візьми дещо на знак вдячності за довгу дорогу й захист пагорбів.", ["en"] = "Grund and Gozwin", ["tasks"] = { ["Gozwin's Mechanic's Log"] = "журнал механіка Ґозвіна", ["Gozwin's Mechanic's Log (Provided)"] = "журнал механіка Ґозвіна (видано)", ["Snow Leopard Prowler"] = "сніжний леопард-скрадач", ["Snow Leopard Prowler slain"] = "сніжний леопард-скрадач: убито" } },
    [97894] = { [1] = "Бізнес в Обердіні", [2] = "Приємно познайомитися з вами! Мене звати Боргус, я з єдиної та неповторної родини Сталеруків. Ви завжди можете розраховувати на Сталеруків у чесній угоді!\n\nКілька тижнів тому мій брат Горбольд приєднався до торговельного кіоску в Обердіні. Там можна заробити купу грошей, постачаючи кораблі, скажу я вам! Щасливчик.\n\nЯ не чув про нього з того часу — не могли б ви перевірити його, якщо прямуєте в цьому напрямку?\n\nУ гавані є новий корабель, який доставить вас прямо туди. Прямуйте до найпівденнішого причалу; не пропустите його!", [3] = "Перевірте Горбольда Сталерукого в Обердіні на Темному Березі.\n\nБоргус згадав про човен на найпівденнішому причалі в гавані Штормовія, який може вас туди доставити.", ["en"] = "Business in Auberdine", ["tasks"] = { ["Take the boat to Auberdine and find Gorbold Steelhand."] = "Сядь на човен до Обердіна та знайди Горбольда Сталерукого." } },
    [97914] = { [1] = "Розширення горизонтів", [2] = "Обердін — скромне місце, {клас}. Ви не почуєте його назви в гілках Дарнасу. Більшість згадує лише те, що Розкол забрав у нас — квітучі міста Амет'Аран, Башал'Аран і... Латар'Лазал.\n\nПроте Обердін залишається в їхній тіні.\n\nЯ хочу, щоб нашу роботу тут визнали. Новий корабель з'єднує нас з королівством Штормовій, приносячи життя та припаси до наших берегів. Благаю вас приєднатися до його наступної подорожі та доставити цього листа людині на ім'я Барос Алекстон.\n\nЗробіть наш дім відомим.", [3] = "Принесіть листа Тандріса Баросу Алексстону в Штормовій.\n\nТандріс згадував про човен в Обердіні, який може доставити вас туди.", ["en"] = "Expanding Horizons", ["tasks"] = { ["Thundris' Letter"] = "Лист Тундріса", ["Thundris' Letter (Provided)"] = "Лист Тундріса (видано)" } },
    [97915] = { [1] = "Кемпінг 101: Алхімія", [2] = "Отже, ти вирішив варити зілля та напої як Алхімік. Я впевнений, що це стане тобі в пригоді в подорожах.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити Колодязь Мани для твого табору. Збудуй один з них, і всі цілителі та чарівники збігатимуться, щоб насолодитися освіжаючим смаком.", [3] = "Поговоріть з алхіміком Меллорі в Елвіннському лісі поблизу Штормовія, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Alchemy", ["tasks"] = { ["Raise your alchemy skill to 20"] = "Підвищте свою навичку алхімії до 20" } },
    [97916] = { [1] = "Кемпінг 101: Ковальська справа", [2] = "Отже, ви стали ковалем. Це чудовий вибір, якщо ви хочете бути впевнені, що ваші клинки ніколи не затупляться.\n\nГадаю, я знаю когось, хто може допомогти вам у цьому, навчивши вас, як виготовити точильне колесо. Принесіть одне з них у свій табір, і всі воїни та розбійники в окрузі вишикуються в чергу, щоб відточити свою зброю.", [3] = "Поговоріть зі Смітом Аргусом у Голдширі, щоб навчитися створювати предмети для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Blacksmithing", ["tasks"] = { ["Raise your blacksmithing skill to 20"] = "Підвищіть навичку ковальства до 20" } },
    [97917] = { [1] = "Кемпінг 101: Чарівний", [2] = "Чарівники роблять усе кращим і завжди раді бачити їх у будь-якому таборі в дикій природі.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Зачаровану лютню для вашого табору. Так важливо знаходити розваги під час відпочинку, і ця частинка магії може допомогти вам бути готовими до всіляких випробувань, коли ви знову вирушите на стару запилену стежку.", [3] = "Поговоріть з Бетті Квін у Штормовії, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Enchanting", ["tasks"] = { ["Raise your enchanting skill to 20"] = "Підвищте свою майстерність зачарування до 20" } },
    [97918] = { [1] = "Кемпінг 101: Інженерія", [2] = "Такі інженери, як ви, можуть створювати всілякі штуки, ботів та бомби для розваги та прибутку.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Бота-Реагента для вашого табору. Цей корисний автомат може допомогти вам добре постачатися, щоб у вас та ваших союзників ніколи не закінчувалися матеріали, необхідні для підживлення ваших заклинань.", [3] = "Поговоріть зі Спрайтом Джамппрокетом у Штормовії, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Engineering", ["tasks"] = { ["Raise your engineering skill to 20"] = "Підвищте свій інженерний рівень до 20" } },
    [97919] = { [1] = "Кемпінг 101: Перша допомога", [2] = "Отже, ви почали навчатися наданню першої допомоги? Це почесне... і прагматичне прагнення як {клас}.\n\nГадаю, я знаю когось, хто може навчити вас, як створити аптечку першої допомоги для вашого табору. Травми — це реальність у світі пригод, і пропонування так необхідного лікування у вашому таборі може навіть врятувати життя.", [3] = "Поговоріть з Мішель Белль у Голдширі, щоб навчитися створювати предмети для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: First Aid", ["tasks"] = { ["Raise your first aid skill to 20"] = "Підвищіть навичку першої допомоги до 20" } },
    [97920] = { [1] = "Кемпінг 101: Риболовля", [2] = "Можливо, ви так не думаєте, але ваші навички рибалки можуть стати в нагоді в таборі.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити акваріум для вашого табору. Ви можете використовувати цей інструмент, щоб подарувати трохи радості собі та своїм товаришам-шукачам пригод. Щасливий шукач пригод – це сильний шукач пригод, і я впевнений, що ваші бойові здібності це відображатимуть.", [3] = "Поговоріть з Лі Брауном поблизу Голдшира, щоб навчитися створювати предмети для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Fishing", ["tasks"] = { ["Raise your fishing skill to 20"] = "Підвищте свій рівень риболовлі до 20" } },
    [97921] = { [1] = "Кемпінг 101: Трав'ярство", [2] = "Мені здається, ти набув певних навичок у травництві. Збирання квітів — це не просто для розваг, знаєш. Це може бути корисним... і прибутковим.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити ароматичну свічку для твого табору. Піднесений дух — ключовий компонент для підтримки цілителів та заклинателів у бою, а ароматична свічка може дати підкріплення, яке маги точно оцінять.", [3] = "Поговоріть з травником Помероєм в Елвіннському лісі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Herbalism", ["tasks"] = { ["Raise your herbalism skill to 20"] = "Підвищте свій рівень навичок травництва до 20" } },
    [97922] = { [1] = "Кемпінг 101: Шкіряна справа", [2] = "Ти став шкіряником. Молодець, {клас}. Гадаю, я знаю когось, хто може навчити тебе, як зробити собі намет, у якому буде прохолодно в спекотні дні та сухо в дощові.\n\nЗ гарним наметом над головою ти гарантовано отримаєш весь необхідний відпочинок, щоб залишатися бадьорим під час подорожей.", [3] = "Поговоріть з Адель Філдер у Голдширі, щоб навчитися створювати предмети для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Leatherworking", ["tasks"] = { ["Raise your leatherworking skill to 20"] = "Підвищте свою майстерність обробки шкіри до 20" } },
    [97923] = { [1] = "Основи таборування: гірництво", [2] = "Гірничодобувна справа — не найгламурніше, але це гарна чесна робота та чудова професія, яку варто досліджувати.\n\nГадаю, я знаю когось, хто може навчити тебе виготовляти магніт для твого табору. Збудуй один з них, і кожен, хто хоче розмахувати мечем, захоче зібратися навколо твого вогнища та насолодитися його додатковою «силою», щоб підвищити свою бойову майстерність.", [3] = "Поговоріть з Гельманом Кам'яною Рукою у Штормовії, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Mining", ["tasks"] = { ["Raise your mining skill to 20"] = "Підвищте свій рівень майнінгу до 20" } },
    [97924] = { [1] = "Кемпінг 101: Зняття шкури", [2] = "Вміння вміло збирати шкури та шкури полеглих звірів – одна з найцінніших навичок, якими може володіти шукач пригод.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити похідне крісло для вашого табору. Іноді важливо просто розслабитися, і ви можете використати деякі з цих зібраних шкур, щоб зробити зручне крісло. Трохи відпочинку може допомогти вам бути у найкращій формі та вдарити там, де це потрібно, наступного разу, коли ви опинитеся в запиленій хаосі.", [3] = "Поговоріть з Хелен Пелцкіннер у Голдширі, щоб навчитися створювати предмети для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Skinning", ["tasks"] = { ["Raise your skinning skill to 20"] = "Підвищте свою навичку зняття шкури до 20" } },
    [97925] = { [1] = "Кемпінг 101: Кравецька справа", [2] = "Кравецька справа — це напрочуд потужна навичка, в яку варто інвестувати, і я впевнений, що вона вам добре послужить.\n\nЯ знаю людину, яка може навчити вас, як створити прапор фракції для вашого табору, за умови, що у вас є для цього відповідні навички. Натхнення та моральний дух є ключовими складовими успіху на будь-якому полі бою, а натхненний прапор може значною мірою зарядити вас енергією.", [3] = "Поговоріть з Елдріном у лісозаготівельному таборі Іствейл в Елвіннському лісі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Tailoring", ["tasks"] = { ["Raise your tailoring skill to 20"] = "Підвищте свою кравецьку майстерність до 20" } },
    [97926] = { [1] = "Роблячи", [2] = "Шкода, що допомогти не так просто, {клас:н}. Справді.\n\nЯкщо ви вирішите провести більше часу в наших землях, то виявите, що багато хто залишився без допомоги. Скарбниці Штормовія вже не ті, що колись були, а те, що залишилося, розпорошилося.\n\nПередайте цю відповідь старійшині наступного разу, коли побачите його. Це не те, на що він сподівається, але це все, що я можу запропонувати зараз.", [3] = "Принесіть відповідь Алексстона Тундрісу Вітроткачу в Аубердіні на Темному Березі.", ["en"] = "Making Do", ["tasks"] = { ["Alexston's Reply"] = "Відповідь Алексстона", ["Alexston's Reply (Provided)"] = "Відповідь Алексстона (видано)" } },
    [97938] = { [1] = "Кемпінг 101: Алхімія", [2] = "Отже, ти вирішив варити зілля та напої як Алхімік. Я впевнений, що це стане тобі в пригоді в подорожах.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити Колодязь Мани для твого табору. Збудуй один з них, і всі цілителі та чарівники збігатимуться, щоб насолодитися освіжаючим смаком.", [3] = "Поговоріть із Синдрою Кайндвіспер у Доланаарі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Alchemy", ["tasks"] = { ["Raise your alchemy skill to 20"] = "Підвищте свою навичку алхімії до 20" } },
    [97939] = { [1] = "Кемпінг 101: Ковальська справа", [2] = "Отже, ви стали ковалем. Це чудовий вибір, якщо ви хочете бути впевнені, що ваші клинки ніколи не затупляться.\n\nГадаю, я знаю когось, хто може допомогти вам у цьому, навчивши вас, як виготовити точильне колесо. Принесіть одне з них у свій табір, і всі воїни та розбійники в окрузі вишикуються в чергу, щоб відточити свою зброю.", ["en"] = "Camping 101: Blacksmithing", ["tasks"] = { ["Raise your blacksmithing skill to 20"] = "Підвищіть навичку ковальства до 20" } },
    [97940] = { [1] = "Кемпінг 101: Чарівний", [2] = "Чарівники роблять усе кращим і завжди раді бачити їх у будь-якому таборі в дикій природі.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Зачаровану лютню для вашого табору. Так важливо знаходити розваги під час відпочинку, і ця частинка магії може допомогти вам бути готовими до всіляких випробувань, коли ви знову вирушите на стару запилену стежку.", [3] = "Поговоріть з Аланною Рейвенай на Галявині Оракула в Тельдрассілі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Enchanting", ["tasks"] = { ["Raise your enchanting skill to 20"] = "Підвищте свою майстерність зачарування до 20" } },
    [97941] = { [1] = "Кемпінг 101: Інженерія", [2] = "Такі інженери, як ви, можуть створювати всілякі штуки, ботів та бомби для розваги та прибутку.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Бота-Реагента для вашого табору. Цей корисний автомат може допомогти вам добре постачатися, щоб у вас та ваших союзників ніколи не закінчувалися матеріали, необхідні для підживлення ваших заклинань.", ["en"] = "Camping 101: Engineering", ["tasks"] = { ["Raise your engineering skill to 20"] = "Підвищте свій інженерний рівень до 20" } },
    [97942] = { [1] = "Кемпінг 101: Перша допомога", [2] = "Отже, ви почали навчатися наданню першої допомоги? Це почесне... і прагматичне прагнення як {клас}.\n\nГадаю, я знаю когось, хто може навчити вас, як створити аптечку першої допомоги для вашого табору. Травми — це реальність у світі пригод, і пропонування так необхідного лікування у вашому таборі може навіть врятувати життя.", [3] = "Поговоріть з Б'янсі в Доланаарі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: First Aid", ["tasks"] = { ["Raise your first aid skill to 20"] = "Підвищіть навичку першої допомоги до 20" } },
    [97943] = { [1] = "Кемпінг 101: Риболовля", [2] = "Можливо, ви так не думаєте, але ваші навички рибалки можуть стати в нагоді в таборі.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити акваріум для вашого табору. Ви можете використовувати цей інструмент, щоб подарувати трохи радості собі та своїм товаришам-шукачам пригод. Щасливий шукач пригод – це сильний шукач пригод, і я впевнений, що ваші бойові здібності це відображатимуть.", [3] = "Поговоріть з Астаєю в Дарнасі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Fishing", ["tasks"] = { ["Raise your fishing skill to 20"] = "Підвищте свій рівень риболовлі до 20" } },
    [97944] = { [1] = "Кемпінг 101: Трав'ярство", [2] = "Мені здається, ти набув певних навичок у травництві. Збирання квітів — це не просто для розваг, знаєш. Це може бути корисним... і прибутковим.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити ароматичну свічку для твого табору. Піднесений дух — ключовий компонент для підтримки цілителів та заклинателів у бою, а ароматична свічка може дати підкріплення, яке маги точно оцінять.", [3] = "Поговоріть з Малорном Клинолистом у Доланаарі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Herbalism", ["tasks"] = { ["Raise your herbalism skill to 20"] = "Підвищте свій рівень навичок травництва до 20" } },
    [97946] = { [1] = "Кемпінг 101: Шкіряна справа", [2] = "Ти став шкіряником. Молодець, {клас}. Гадаю, я знаю когось, хто може навчити тебе, як зробити собі намет, у якому буде прохолодно в спекотні дні та сухо в дощові.\n\nЗ гарним наметом над головою ти гарантовано отримаєш весь необхідний відпочинок, щоб залишатися бадьорим під час подорожей.", [3] = "Поговоріть з Надією Манівевер дорогою до Дарнасу з Доланаара, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Leatherworking", ["tasks"] = { ["Raise your leatherworking skill to 20"] = "Підвищте свою майстерність обробки шкіри до 20" } },
    [97948] = { [1] = "Основи таборування: гірництво", [2] = "Гірничодобувна справа — не найгламурніше, але це гарна чесна робота та чудова професія, яку варто досліджувати.\n\nГадаю, я знаю когось, хто може навчити тебе виготовляти магніт для твого табору. Збудуй один з них, і кожен, хто хоче розмахувати мечем, захоче зібратися навколо твого вогнища та насолодитися його додатковою «силою», щоб підвищити свою бойову майстерність.", [3] = "Поговоріть з Курдрамом Кам'яним Молотом в Обердіні, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Mining", ["tasks"] = { ["Raise your mining skill to 20"] = "Підвищте свій рівень майнінгу до 20" } },
    [97949] = { [1] = "Кемпінг 101: Зняття шкури", [2] = "Вміння вміло збирати шкури та шкури полеглих звірів – одна з найцінніших навичок, якими може володіти шукач пригод.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити похідне крісло для вашого табору. Іноді важливо просто розслабитися, і ви можете використати деякі з цих зібраних шкур, щоб зробити зручне крісло. Трохи відпочинку може допомогти вам бути у найкращій формі та вдарити там, де це потрібно, наступного разу, коли ви опинитеся в запиленій хаосі.", [3] = "По дорозі з Доланаара до Дарнасуса поговоріть з Раднаалом Маневрівером, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Skinning", ["tasks"] = { ["Raise your skinning skill to 20"] = "Підвищте свою навичку зняття шкури до 20" } },
    [97950] = { [1] = "Кемпінг 101: Кравецька справа", [2] = "Кравецька справа — це напрочуд потужна навичка, в яку варто інвестувати, і я впевнений, що вона вам добре послужить.\n\nЯ знаю людину, яка може навчити вас, як створити прапор фракції для вашого табору, за умови, що у вас є для цього відповідні навички. Натхнення та моральний дух є ключовими складовими успіху на будь-якому полі бою, а натхненний прапор може значною мірою зарядити вас енергією.", [3] = "Поговоріть з Тріанною в Дарнасі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Tailoring", ["tasks"] = { ["Raise your tailoring skill to 20"] = "Підвищте свою кравецьку майстерність до 20" } },
    [97973] = { [1] = "Кемпінг 101: Кравецька справа", [2] = "Кравецька справа — це напрочуд потужна навичка, в яку варто інвестувати, і я впевнений, що вона вам добре послужить.\n\nЯ знаю людину, яка може навчити вас, як створити прапор фракції для вашого табору, за умови, що у вас є для цього відповідні навички. Натхнення та моральний дух є ключовими складовими успіху на будь-якому полі бою, а натхненний прапор може значною мірою зарядити вас енергією.", [3] = "Поговоріть з Талін Мерехтрід у селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Tailoring", ["tasks"] = { ["Raise your tailoring skill to 20"] = "Підвищте свою кравецьку майстерність до 20" } },
    [97979] = { [1] = "Богиня забезпечує", [2] = "Ви народжені калдорай — дітьми зірок — і успадкували право народження, не схоже ні на кого іншого в цьому світі. Милість Елуни може освітити наші сильні сторони, допомагаючи нашим ударам влучати в ціль, або ж вона може допомогти приховати нас, так само як місяць може затьмарити сонце.\n\nНаше Довге Чування після захисту гори Хіджал закінчилося, і ми приєдналися до Альянсу інших, з якими ви зустрінетеся у свій час. А зараз ви затишно перебуваєте в гілках Тельдрассілу.\n\nПродемонструйте дари Матері Місяць і насолоджуйтесь її благословеннями.", [3] = "Використайте Злиття Світла та Тіні Елуни.", ["en"] = "The Goddess Provides", ["tasks"] = { ["Elune's Light cast"] = "Акторський склад «Світла Елуни»", ["Shadowmeld cast"] = "Акторський склад Shadowmeld" } },
    [98] = { [1] = "Легенда про Сталвана", [2] = "Сталван Імлокрив жив життям порочника. Невинні жертви померли від його рук. Напевне, він винен у безлічі злочинів. Тепер цей божевільний загрожує Темнодолу. Лише Світло знає, які жахи він задумав. Вирушай до його дому, що на північ від міста, {клас:к}, і покінчи зі Сталваном раз і назавжди.\n\nКоли впораєшся, вирушай до мадам Єви та покажи їй його сімейний перстень. Зрештою, саме її передчуття дозволили нам розкрити цей темний злочин. Завдяки їй у Темнодолі стане безпечніше.", [3] = "Вбийте Сталвана Імлокрива і покажіть мадам Єві його фамільний перстень.", [4] = "Так, {ім'я}?", [5] = "Я знаю, {ім'я}, Сталвана вже немає. Я відчула хвилю надії, що пробігла опоганеним лісом. Нарешті, Смерколісся звільнене від його кровожерності. Моя радість пригнічена думками про тих, хто став жертвою цього жахливого чудовиська. Однак, ти — {стать:хоробрий та кмітливий:хоробра та кмітлива} {клас}.", ["en"] = "The Legend of Stalvan", ["tasks"] = { ["Mistmantle Family Ring"] = "сімейний перстень Імлокривів", ["Mistmantle Family Ring (Provided)"] = "сімейний перстень Імлокривів (видано)" } },
    [98021] = { [1] = "Подорож до Сентінел-Гілл", [2] = "Якщо ви хочете почати робити щось хороше в нашому світі, я б рекомендував звернутися до чоловіка на ім'я Гріан Стаутмантл у Вестфоллі на півдні, в поселенні, відомому як Сентінел-Гілл. Його народ потребує допомоги.\n\nПісля подорожі сюди з іншого плану існування проблеми, з якими стикаються наші землі, можуть здатися незначними. Запевняю вас, допомога, яку ви надаєте тим, хто постраждав від таких проблем, означає для них все, і ви станете сильнішими завдяки своїм зусиллям.\n\nУдачі тобі, шукачу пригод!", [3] = "Зверніться до Гріана Стаутмантла на Вартовий пагорб у Вестфоллі.", ["en"] = "Journey to Sentinel Hill" },
    [98025] = { [1] = "РОЗШУКУЄТЬСЯ: Джай'вханель", [2] = "Увага!\n\nЗа смерть сови \"Джай'вханель\", також відомої як \"Мечеперо\", пропонується винагорода.\n\nНа жаль, ця сова збожеволіла та почала нападати на подорожніх, коли вони подорожують дорогою поблизу Обердіна.\n\nВостаннє Джай'вханель бачили на північ від руїн Амет'Аран біля підніжжя гори. Принесіть одне з її чорних як смола пір'їн як доказ її смерті.\n\nЗаявки на винагороду за цю нагороду слід подати до Вартової Глінди Нал'Ші в Обердіні.\n\nСільська рада Обердіна", [3] = "Знайдіть і вбийте сову на ім'я Джай'вханель і візьміть одне з її пера. Чорну сову востаннє бачили на північ від руїн Амет'Аран, біля підніжжя гори. Повідомте про смерть Джай'вханеля вартовій Глінді Нал'Шіа в Обердіні.", ["en"] = "WANTED: Jai'vhanel", ["tasks"] = { ["Feather of Jai'vhanel"] = "Перо Джайвханеля" } },
    [98027] = { [1] = "Блискуче намисто-півмісяць", [2] = "<Срібне намисто у ваших руках м'яко сяє, поки ви його розглядаєте. Невеличкий півмісяць нагадує інші символи нічних ельфів, які ви бачили раніше.\n\nПеревернувши намисто, ви знаходите маленький напис: «Alor'lormah, Maliynn». Можливо, воно належить Майлін з Астранаара?>", ["en"] = "Gleaming Crescent Necklace", ["tasks"] = { ["Gleaming Crescent Necklace"] = "Блискуче намисто-півмісяць" } },
    [98028] = { [1] = "Барон Марінуус", [2] = "Все, що залишилося від могутнього елементаля, це куля з чогось, що здається чистою водою, затуманена якоюсь невідомою речовиною. Краї сфери здаються прозорими, поки ви її не повернете — ніби хмара активно заважає вам зазирнути всередину.\n\nЩо б не сталося з нею — і з руїнами, які вона охороняла — вона все ще якимось чином активна.\n\nТільки Ону, Стародавній Знань у Гаю Стародавніх на далекому півдні, мав би шанс дізнатися більше.", [3] = "Принесіть Захмарену Водяну Кулю Ону в Гай Стародавніх на Темному Березі.", ["en"] = "Baron Marinous", ["tasks"] = { ["Clouded Water Globe"] = "Замутнена водна куля", ["Clouded Water Globe (Provided)"] = "Замутнена водна куля (видано)" } },
    [98059] = { [1] = "Запаси Гіллзбраду", [2] = "Рада Гіллзбраду не відповідає на листи нашого нового магістрату. Остання звістка, яку я витягнув із проїжджого купця з того містечка, мало виправдовує їхнє мовчання.\n\nМи просимо лише невеликий взвод, а мені кажуть, що на огородженому подвір'ї стоїть кілька облогових баліст у чудовому стані.\n\nЗайди в їхню ратушу, наче громадянин, що повертає переписну анкету, й акуратно поклади це на стіл для ведення обліку.\n\nКоли зробиш, повернися до мене.", ["en"] = "Hillsbrad's Hoard", ["tasks"] = { ["Sealed Company Request delivered to Hillsbrad council"] = "Доставити запечатаний запит роти раді Гіллзбраду" } },
    [98067] = { [1] = "Очі Вартових", [2] = "Генерал Пернатий Місяць гарантує, що всі вартові мають час помолитися Елуні. Справжня мисливиця володіє не лише мечем, а й дарами богині, щоб перемагати наших ворогів.\n\nВи можете допомогти мені з моїми щоденними обов'язками. Розставте вартових по місту — почніть з тунелів, що ведуть під фортецею Кенаріона на північ, банку в центрі міста, корчми на Терасі Ремісників на північний схід і міських воріт. Вартові можуть вам допомогти.\n\nЩось не так у Тельдрассілі — ми повинні залишатися пильними.", [3] = "Розмістіть Вартових Сов біля входу до глибин Твердині Кенаріона, Банку Дарнасу, таверни «Тераса Ремісника» та Міських Воріт для Вартової Далії Сонячного Клинка у Храмі Місяця в Дарнасі.\n\nНаданий предмет:", ["en"] = "Eyes of the Sentinels", ["tasks"] = { ["Cenarion Hold depths entrance"] = "Вхід до глибин фортеці Кенаріона", ["Cenarion Hold depths entrance (Provided)"] = "Вхід до глибин фортеці Кенаріона (видано)", ["Cenarion Hold depths entrance slain"] = "Вхід до глибин фортеці Кенаріона: убито", ["City Gate"] = "Міська брама", ["City Gate (Provided)"] = "Міська брама (видано)", ["City Gate slain"] = "Міська брама: убито", ["Craftsman's Terrace Inn"] = "Готель «Craftsman's Terrace Inn»", ["Craftsman's Terrace Inn (Provided)"] = "Готель «Craftsman's Terrace Inn» (видано)", ["Craftsman's Terrace Inn slain"] = "Готель «Craftsman's Terrace Inn»: убито", ["Darnassus Bank"] = "Банк Дарнас", ["Darnassus Bank (Provided)"] = "Банк Дарнас (видано)", ["Darnassus Bank slain"] = "Банк Дарнас: убито" } },
    [98071] = { [1] = "Пивоварський обмін", [2] = "Домовився про невеликий обмін із пивоварами Дун-Ґарока. Здається, не лише ми сумуємо за виноградниками родини Фоллрук! Більшість найкращих витриманих вин давно випито, але кілька ящиків ще лишилося в льохах.\n\nВіднеси цей ящик сортового вина Фоллруків у Дун-Ґарок на південному сході й залиш біля спільного вогнища на нижньому поверсі їхньої фортеці.\n\nНатомість принеси звідти мішок хмелю для домашнього пива.\n\nТа фортеця — найближче до дому, що тут є!", [3] = "Доставте пляшки сортового вина Фоллруків у Дун-Ґарок на південному сході передгір'я Гіллзбраду й принесіть звідти мішок хмелю для домашнього пива.", ["en"] = "Brewer's Trade", ["tasks"] = { ["Fallrook Varietal delivered to Dun Garok"] = "Доставити сортове вино Фоллруків у Дун-Ґарок", ["Sack of Homebrew Hops"] = "Мішок домашнього хмелю" } },
    [98155] = { [1] = "Бездоганні шкури паршивих гієн", [2] = "Паршиві гієни Тисячі Шипів мають надзвичайно гарне хутро. За всі свої подорожі я не бачила настільки яскравого забарвлення!\n\nХотіла б відіслати кілька шкур своїм сестрам у Штормовій, бо знаю: вони зроблять із них щось неймовірне.\n\nЯ не маю бойового досвіду, тож буду дуже вдячна, якщо збереш кілька шкур паршивих гієн замість мене.", [3] = "Принесіть 5 бездоганних шкур паршивих гієн Крісті Ґрант.", ["en"] = "Pristine Pesterhide Pelts", ["tasks"] = { ["Pristine Pesterhide Pelt"] = "Бездоганна шкура Докучношкіра" } },
    [98189] = { [1] = "Повернення статуетки", [2] = "Боже мій, це ж... це ж чудово!\n\n\"Сліпа Принцеса\" мала доставити це до гавані Менетіл, перш ніж сталася трагедія. Ми були так близько!\n\nГадаю, це мав підписати капітан Стаутфіст у фортеці Менетіл, одразу за нами. Чому б тобі не взяти на себе честь завершити цю роботу?", ["en"] = "Return the Statuette", ["tasks"] = { ["Menethil Statuette"] = "статуетка Менетіла", ["Menethil Statuette (Provided)"] = "статуетка Менетіла (видано)" } },
    [98190] = { [1] = "Друг родини", [2] = "Тобі варто негайно віднести це до Штормовія. Хоч я й пишаюся тим, що ця фортеця та гавань носять ім'я короля Теренаса Менетіла II, ми — тиха гавань у дуже лютій бурі ворогів. Тут просто небезпечно.\n\nЗокрема, Драконяча Паща пожертвувала б багатьом, щоб пограбувати щось подібне... і мені страшно подумати, що вони з цим зроблять.\n\nНе турбуйся підніматися по ланцюжку командування з цього приводу, <хлопець/дівчина>. Іди з цим прямо до Верховного лорда Фордрагона. Він знатиме, де це найкраще зберігати.", ["en"] = "A Friend of the Family", ["tasks"] = { ["Menethil Statuette"] = "статуетка Менетіла", ["Menethil Statuette (Provided)"] = "статуетка Менетіла (видано)" } },
    [98191] = { [1] = "Друг родини", [2] = "Король Теренас був доброю людиною. Побожною людиною. Улюбленим своїм народом, і саме тому ми взагалі маємо цей Альянс.\n\nІронія полягає в тому, що він був скромним — він ненавидів такі пам'ятки, і їх так мало. І з них мало хто пережив падіння Лордерона.\n\nЗдається, Світло об'єдналося в цій статуетці. Найкраще її зберігати в Соборі Світла на Соборній площі, в центрі міста. Віднесіть її лорду Грейсону, Тіньолому, для безпечного зберігання.", ["en"] = "A Friend of the Family", ["tasks"] = { ["Menethil Statuette"] = "статуетка Менетіла", ["Menethil Statuette (Provided)"] = "статуетка Менетіла (видано)" } },
    [98197] = { [1] = "Військові трофеї", [2] = "Цю гавань вперше побудувала Стара Орда як плацдарм для свого морського вторгнення в Гіллсбрад. Вона повністю обійшла оборону Лордерона!\n\nСтільки життів втрачено...\n\nЩе гірше те, що цей флот був побудований саме тими ресурсами, які вони вкрали у Хаз Модана!\n\nВелика їх кількість залишилася в гавані після того, як адмірал Праудмур розгромив цих негідників і побудував це місце для Альянсу. Нам це знадобиться, щоб посилити оборону міста, поки Драконяча Пасть рухається.", [3] = "Добудьте в Гавані Менетіла 6 од. деревини Каз-Модану та 30 од. заліза Каз-Модану для Валстаґа Залізнощелепа.", [4] = "Не втрачай пильності під хвилями. Там унизу повно всілякої погані!", [5] = "О! Трохи вогке, але кілька днів на сонці — і все буде гаразд.\r\n\r\nДякую, <class>. Приємно хоч раз не залежати лише від поставок із Терамора чи Аубердіна!", ["en"] = "Spoils of War", ["tasks"] = { ["Khaz Modan Iron"] = "Залізо Каз-Модану", ["Khaz Modan Timber"] = "Деревина Каз-Модану" } },
    [98216] = { [1] = "Розуміння сьогодення", [2] = "Старі Боги?! Це зовсім не добра звістка!\n\nЯ розібрав ще один уривок на камені. У ньому йдеться про якогось вартового. Хто б він не був, він мусить бути пов'язаний із каменем!\n\nВізьми його й спробуй знайти на розкопках велику конструкцію титанів. Прочитай цей останній уривок на камені й подивися, що станеться!\n\nЯкщо я маю рацію, ти активуєш ту штуковину. Тоді знищ її, але постарайся зберегти все цікаве! Ми просто мусимо дізнатися більше!", [3] = "Використайте камінь Ґоаза біля вартового Ґоаза й принесіть його наріжний камінь титанів розвідувачу Вельґару.", ["en"] = "Understanding Our Present", ["tasks"] = { ["Titanic Keystone"] = "Титанічний ключ-камінь" } },
    [98219] = { [1] = "Осоромлений лейтенант", [2] = "Ще раз дякую за безпечну доставку статуетки, {ім'я}.\n\nМені потрібна ваша допомога ще з дечим. Є член міської варти, якого перевели на службу в Саутберег, у передгір'ях Гіллсбрада.\n\nЙого батько був моїм другом, і хоча я не заперечую, що йому знадобився б цей урок... я все одно хотів би бачити його успіх. Йому б дуже знадобилася допомога такого, як ви.\n\nЄ човен, який може доставити вас туди з гавані Менетіл, якщо ви повертаєтесь через неї.", [3] = "Поговоріть із лейтенантом Фарреном Орінеллем у Південнобережжі, що в Гіллзбрадовому передгір'ї.", ["en"] = "The Shamed Lieutenant" },
    [98221] = { [1] = "З попелу", [2] = "Під час Другої війни Драконова Паща збудувала флот там, де ми зараз стоїмо, щоб захопити Гіллзбрад. Їм майже вдалося!\n\nЧервоні дракони розгромили їх, лишивши тільки розрізнені загони в глибині гір. Однак останнім часом їхній табір на північний схід від Менетілів помітно пожвавився.\n\nДун-Альґаз доводить, що вони знову готуються до війни й хочуть повернути ці землі. Знайди їхні плани нападу, запам'ятай усе важливе й знищ їх. Треба знати, куди вони вдарять далі!", [3] = "Капітан Міцнорук із фортеці Менетілів просить знищити 4 плани нападу в таборі Лютого Ікла.", ["en"] = "From the Ashes", ["tasks"] = { ["Attack Plan: Ironforge destroyed"] = "План нападу: Залізогарт — знищено", ["Attack Plan: Menethil Harbor destroyed"] = "План нападу: гавань Менетілів — знищено", ["Attack Plan: Southshore destroyed"] = "План нападу: Південнобережжя — знищено", ["Attack Plan: Thelsamar destroyed"] = "План нападу: Телсамар — знищено" } },
    [98223] = { [1] = "Старі звички", [2] = "Ця книга сильно обгоріла — можливо, від драконячого вогню, який знищив більшу частину клану Драконової Пащі.\n\nНечисленні розбірливі уривки, схоже, описують ритуали використання Душі Демона, якою клан підкорював драконів.\n\nКнига надто неповна, щоб мати справжню користь, але грубо вставлені сторінки з тваринної шкіри свідчать, що Нек'рош намагався її відновити. Щойно висохле чорнило згадує «Тіньову Раду».\n\nКапітан Міцнорук у гавані Менетілів захоче про це дізнатися.", [3] = "Віднесіть пошарпану книгу заклять капітану Міцноруку в гавань Менетілів.", ["en"] = "Old Habits", ["tasks"] = { ["Tattered Spellbook (Provided)"] = "Пошарпана книга заклять (видано)" } },
    [98230] = { [1] = "Ця земля була їхньою", [2] = "Після Війни Трьох Молотів, яка розірвала звичний світ дворфів, Дикі Молоти оселилися тут і заснували гірську фортецю Ґрім-Батол.\n\nЦе було дивовижне місце. Куди не глянь, ширяли грифони, пірнаючи вниз до боліт, щоб схопити рибу.\n\nНа жаль, тривало це недовго.\n\nГовін Доброперий — один із перших Диких Молотів, які повернулися сюди за багато років. Він тримається осторонь, далеко від міста. Йди дорогою на схід — зрештою знайдеш його. Допомога йому напевно знадобиться.", [3] = "Знайдіть Говіна Доброперого біля дороги на схід від гавані Менетілів.", ["en"] = "This Land Was Their Land" },
    [98240] = { [1] = "Доставка багряного ящика", [2] = "Офіційно поширилася чутка про цих цуценят, {ім'я}. У нас вже є замовлення!\n\nЯ гарненько їх упакую для тебе, а ти віднесеш клієнту. Знаю, знаю; це просто остання послуга, обіцяю!\n\nЦе буде для одного \"Хауїн Кайндфізер\". Він відправив свого грифона до міста, як не дивно, з листом для замовлення! Каже, що він якраз біля дороги на схід, трохи далі за місцем розкопок Велгара, якщо ти знайомий.", ["en"] = "Crimson Crate Delivery", ["tasks"] = { ["Crimson Crate"] = "Багряний ящик", ["Crimson Crate (Provided)"] = "Багряний ящик (видано)" } },
    [98245] = { [1] = "Голкогубне проколювання", [2] = "Не знаю, кого я ненавиджу більше: клятих Темних Заліз, Драконячої Пащі чи драконів, на яких вони їздили.\n\n<Хауїн плюється.>\n\nЯ маю намір все виправити. Але нам знадобляться деякі припаси.\n\nЦя луска цуценят добре захистить від драконячого вогню, але їхнє сплітання разом — це справжній головний біль.\n\nХижі Острозубі Пащі на хребті Раптор на північному сході та в Солоній Глині на північному заході названі так через свої гострі гризуни — їм слід пробити луску.\n\nПринесіть мені жменю різців.", [3] = "Зберіть 10 різців Остропащі для Говіна Доброперого.", [4] = "Ну що, вдалося повитягувати ті зуби? Мені вони потрібні цілими, щоб не ламалися об луску з першого ж удару.", ["en"] = "Razormaw Needling", ["tasks"] = { ["Razormaw Incisor"] = "Різець бритвогубий" } },
    [98246] = { [1] = "Важкі часи", [2] = "Мені знадобляться яйця, якщо мій план спрацює. Окуню потрібен гарний і повний живіт — я ж не маю наміру стрибати на спині похмурого грифона.\n\nВони мають бути ідеальними — без тріщин чи чогось такого.\n\nВізьміть трохи яєць у хижих птахів Острозубих Палиць — вони відомі тим, що мають жовтки розміром з головку гнома. Ви можете знайти їх у Раптор-Рідж на північному сході та в Солтспрей-Глен на північному заході.\n\nДавайте зробимо гарну рівну дюжину, про всяк випадок.", [3] = "Зберіть 12 бездоганних яєць Остропащі для Говіна Доброперого.", [4] = "Гострощелепам навряд чи сподобається, що ти забираєш їхні яйця, тож готуйся до бійки.", [5] = "Вони не для мого плану — ними я годуватиму Низькодзьоба. Повір, коли вона голодна, від неї жодної користі. А якщо розлютиться, може бути небезпечнішою за орків!\r\n\r\nОстаннім часом у цих краях дедалі важче знайти незіпсовану їжу...", ["en"] = "Trying Times", ["tasks"] = { ["Perfect Razormaw Egg"] = "Ідеальне яйце бритвогуба" } },
    [98247] = { [1] = "Етикетка доставки", [2] = "<На боці повністю заповненого ящика можна знайти розірвану транспортну етикетку. Хоча адреса одержувача відірвана, деталі його походження все ще збереглися.\n\n«Власність Торгового Управління Азероту. Будь ласка, поверніть порожні ящики або невиконані відправлення до нашого місцевого торгового центру на перехресті Трьох Кутів у Червоногір'ї. Кур'єрам буде компенсовано їхній час та проїзд».\n\nПоруч із текстом знаходиться грубо намальована карта місцевості поблизу вищезгаданого пункту призначення.>", [3] = "Доставте транспортну етикетку комусь у торговому центрі Торговельної управи Азероту у Червонобріджських горах.", ["en"] = "Shipping Label", ["tasks"] = { ["Shipping Label"] = "Етикетка доставки" } },
    [98282] = { [1] = "Алхімічні небезпеки", [2] = "Для деяких алхімічних рецептів потрібні інгредієнти, що походять з, ну, дуже небезпечних місць. І це часто лише базові трави! Інші інгредієнти ще гірші!\n\nМені потрібно зробити більше протиотрути, перш ніж я зможу знову піти. Клянусь, все в цьому болоті отруйне. Ніби воно протікає крізь саму землю!\n\nЧи можете ви мені допомогти? Мені знадобиться отруйна залоза від павуків у Тельген-Рок на далекому південному сході. Але вона має бути нерозірваною, інакше забагато отрути вилиється, перш ніж ви зможете сюди дістатися. Вибачте!", [3] = "Зберіть нерозірвану залозу сталкера зі скелі Телген для Кейтлін Грассман у гавані Менетіл.", ["en"] = "Alchemical Hazards", ["tasks"] = { ["Unruptured Stalker Gland"] = "Нерозривна залоза сталкера" } },
    [98286] = { [1] = "Кемпінг 101: Чарівний", [2] = "Чарівники роблять усе кращим і завжди раді бачити їх у будь-якому таборі в дикій природі.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Зачаровану лютню для вашого табору. Так важливо знаходити розваги під час відпочинку, і ця частинка магії може допомогти вам бути готовими до всіляких випробувань, коли ви знову вирушите на стару запилену стежку.", [3] = "Поговоріть з Насаланною Вітроспівачкою в селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Enchanting", ["tasks"] = { ["Raise your enchanting skill to 20"] = "Підвищте свою майстерність зачарування до 20" } },
    [98287] = { [1] = "Кемпінг 101: Інженерія", [2] = "Такі інженери, як ви, можуть створювати всілякі штуки, ботів та бомби для розваги та прибутку.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Бота-Реагента для вашого табору. Цей корисний автомат може допомогти вам добре постачатися, щоб у вас та ваших союзників ніколи не закінчувалися матеріали, необхідні для підживлення ваших заклинань.", ["en"] = "Camping 101: Engineering", ["tasks"] = { ["Raise your engineering skill to 20"] = "Підвищте свій інженерний рівень до 20" } },
    [98291] = { [1] = "Смерть Драконовій Пащі", [2] = "Я збираюся повернутися в Ґрім-Батол і відвоювати його для Диких Молотів, {ім'я}. Або хоча б дещо розвідати.\n\nНе дивися на мене так. Я знаю про ризики. Не збираюся вдиратися туди, розмахуючи молотом.\n\nТа спершу мені потрібна твоя допомога. Орки Драконової Пащі вже виступають. Вони заполонили своє укриття, де колись їх розгромили червоні дракони.\n\nТреба зменшити їхні сили, інакше я навіть не наближуся. Йди дорогою на схід — не проминеш їх.", [3] = "Убийте 8 відвойовників, 5 зв'язувачів душ і 3 проникників Драконової Пащі в укритті Драконової Пащі для Говіна Доброперого.", ["en"] = "Death to the Dragonmaw", ["tasks"] = { ["Dragonmaw Infiltrator"] = "Проникник Драконової Пащі", ["Dragonmaw Infiltrator slain"] = "Проникник Драконової Пащі: убито", ["Dragonmaw Reclaimer"] = "Відвойовник Драконової Пащі", ["Dragonmaw Reclaimer slain"] = "Відвойовник Драконової Пащі: убито", ["Dragonmaw Soulbinder"] = "Зв'язувач душ Драконової Пащі", ["Dragonmaw Soulbinder slain"] = "Зв'язувач душ Драконової Пащі: убито" } },
    [98293] = { [1] = "Примусове роззброєння", [2] = "Драконяча Пасть накопичує всіляку зброю. Було б розумно позбавити їх від неї, перш ніж можна буде озброїти більше солдатів.\n\nКапітан Стаутфіст у фортеці Менетіл, безсумнівно, буде зацікавлений у цьому.", [3] = "Зберіть 30 озброєння Драконової Пащі в Прихистку Драконової Пащі, а потім принесіть його капітану Міцнокулаку до фортеці Менетіла.", ["en"] = "Forced Disarmament", ["tasks"] = { ["Dragonmaw Armaments"] = "Озброєння Драконячої Пащі" } },
    [98297] = { [1] = "Розірвати коло", [2] = "Поки тебе не було, я здійснив короткий пробний політ. Добра звістка: обладунок, який ми з твоєю допомогою зробили для Басбіка, працює бездоганно!\n\nА дуже погана звістка — я побачив, як група орків Драконової Пащі поневолює червоного драконіда.\n\nТільки не це. Не знову.\n\nТи мусиш його вбити. Без друзів тобі точно не впоратися. Спершу вбий чорнокнижників, які його утримують, — це має звільнити його. А потім поклади край його стражданням.\n\nНіхто з них не стане на шляху Дикого Молота.", [3] = "Убийте поневоленого драконіда біля воріт Драконової Пащі для Говіна Доброперого.", ["en"] = "Stopping the Cycle", ["tasks"] = { ["Subdued Dragonspawn"] = "Поневолений драконід", ["Subdued Dragonspawn slain"] = "Поневолений драконід: убито" } },
    [98310] = { [1] = "Пізнання майбутнього", [2] = "По всьому Заболоттю є й інші, більші големи. Написи називають їх Адосом, Модром, Ґолмом і Неру — саме так позначені відсутні частини знайденого тобою каменя Ґоаза!\n\nГотовий закластися: якщо принесемо і їхні частини, розкриємо ще більше таємниць каменя Ґоаза!\n\nАдоса знайдеш біля воріт Драконової Пащі на сході, неподалік Ґрім-Батола. Модр стоїть просто за Дун-Модром на півночі. Ґолм — під Ґрім-Батолом, на схід від Дун-Альґаза. Неру — за пагорбом Жахокузні на північному сході.", [3] = "Використайте камінь Ґоаза біля Адоса, Модра, Ґолма та Неру й принесіть їхні серця розвідувачу Вельґару.", ["en"] = "Gleaning Our Future", ["tasks"] = { ["Heart of Ados"] = "Серце Адоса", ["Heart of Golm"] = "Серце Ґолма", ["Heart of Modr"] = "Серце Модра", ["Heart of Neru"] = "Серце Неру" } },
    [98319] = { [1] = "Захист гори", [2] = "Мало нам проблем із тролями, так ще й гори кишать вендиго! Зазвичай вони сидять у своїх печерах, але тепер плодяться, наче кролики. Вони вже заполонили Посивіле лігво на північ звідси.\n\nЩоб отримати звіт Білоборода, нам потрібно знайти мого напарника Корнеліуса. Цей бовдур трохи розпалився й стрімголов кинувся всередину. Хоробро, але нерозумно.\n\nЗайди в печеру й дізнайся, де він. І можеш дорогою прорідити цих звірів.", [3] = "Знайдіть горянина Корнеліуса в Посивілому лігві для горянинки Ґретхен.", [5] = "От же дурень...\n\nДякую за допомогу, {ім'я:к}. Здається, звіт у нас готовий.", ["en"] = "Secure the Mountain", ["tasks"] = { ["Mountaineer Cornelius found"] = "Знайти горянина Корнеліуса", ["Mountaineer Cornelius found (Provided)"] = "Альпініст Корнеліус знайшов (видано)", ["Mountaineer Cornelius found slain"] = "Альпініст Корнеліус знайшов: убито" } },
    [98321] = { [1] = "Вантаж Кресала", [2] = "Хо-ха! Радий бачити {раса:з}, що не боїться забруднити руки.\n\nЯкщо шукаєш роботу, боюся, зараз мені трохи бракує припасів. Наше найнадійніше джерело руди заполонили вендиго, і тепер печеру покинуто. Шахтарям довелося кинути все, коли вони тікали!\n\nСлухай, чому б тобі не зазирнути до Посивілого лігва на заході й не пошукати кілька наших зниклих вантажів? Це позбавило б нас чималого клопоту.", [3] = "Зберіть 8 вантажів Кресала в Посивілому лігві для Тоґна Кресала в Хараносі.", [4] = "Вендиго — мерзенні тварюки. Добре хоч усі шахтарі вибралися з Посивілого лігва цілими й неушкодженими!", [5] = "Оце вже інша справа! З цими вантажами ми швидко відновимо роботу кузні!", ["en"] = "Flintfire's Shipment", ["tasks"] = { ["Flintfire's Shipment"] = "вантаж Кресала", ["Flintfire's Shipment (Provided)"] = "вантаж Кресала (видано)" } },
    [98322] = { [1] = "Захист гори", [2] = "Досліджувати темні печери — робота для шукачів пригод. Моє діло — складати звіти й відправляти їх до Залізогарта. От тільки один із моїх звітів... так і не надійшов.\n\nЯ попросив кількох горянинів дізнатися більше про проблему з вендиго в цих краях, але від них досі немає звістки. Якщо ти все одно збираєшся в дорогу, то, може, навідаєш горянинку Ґретхен на захід від міста? Я й так уже запізнююся!", [3] = "Навідайте горянинку Ґретхен на захід від Хараноса.", [4] = "Шукаєш гінця? Щойно полетів геть, наче маленька пташка.\n\nНе можу винуватити бідолаху. З цими вендиго кепські справи.", [5] = "Старий Білобород послав тебе, га?\n\nЯ отримала його звіт. Ситуація тут — справжнє лихо!", ["en"] = "Secure the Mountain" },
    [98323] = { [1] = "Захист гори", [2] = "Сподіваюся, поки ти {стать:був:була} там, то {стать:вклав:вклала} чимало тих дворняг. Шкода Корнеліуса. З твого опису повідомити особливо нічого — хіба що печеру втрачено.\n\nБілобородові така відповідь не сподобається, але я не насмілюся відправити ще когось у ту смертельну пастку. Передай йому це повідомлення, {ім'я:к}. Я не зрушу з місця, доки гора не буде в безпеці.", [3] = "Доставте звіт горянинки Ґретхен Сенірові Білобороду в Харанос.", [4] = "А, ти повернувся саме вчасно.\n\nЩо сталося, друже? На тобі лиця немає.", [5] = "Усю печеру заполонили? Чого ж я не дивуюся.\n\nЩо ж, це теж потрапить до звіту.\n\n<Сенір кладе лист Ґретхен до стосу своїх нотаток.>", ["en"] = "Secure the Mountain", ["tasks"] = { ["Deliver Mountaineer Gretchen's Report back to Senir Whitebeard in Kharanos."] = "Поверніть звіт горянинки Ґретхен Сенірові Білобороду в Хараносі.", ["Mountaineer Gretchen's Report"] = "Звіт альпіністки Гретхен", ["Mountaineer Gretchen's Report (Provided)"] = "Звіт альпіністки Гретхен (видано)", ["Mountaineer Gretchen's Report slain"] = "Звіт альпіністки Гретхен: убито" } },
    [98391] = { [1] = "Сестринство Елуни", [2] = "Благословення вам, {клас}. Сестринство Елуни було стовпом суспільства калдорай протягом тисячоліть.\n\nДо Великого Розколу, до Війни Древніх, через Довге Чування, ми вели та зцілювали наш народ крізь темряву. Таке наше завдання, і така вимога незрівнянної Матері Місяця.\n\nЗараз нам потрібна ваша допомога у справі великої важливості. Сестра Аквінна чекає на ваше прибуття до Дарнасу.", [3] = "Поговоріть із сестрою Аквінною в Дарнасі.", ["en"] = "The Sisterhood of Elune" },
    [98392] = { [1] = "Темрява на галявині", [2] = "Ці ремені... уважно подивіться на шкіру, {ім'я}. Бачите, як пляма просочується крізь волокна?\n\nУ мене є підозра щодо її походження, але нам потрібні додаткові докази, щоб бути впевненими.\n\nПоверніться до гнізд гарпій на заході та знищіть їхніх ватажків. Якщо їхні намиста несуть ту ж темряву, що й ці ремені, ми отримаємо відповідь.", [3] = "Зберіть Амулет Ненависного Крику, Амулет Вітросудді та Амулет Відьми-матері Ариси для Вартової Аринії Хмарний Прорив на Галявині Оракула.", ["en"] = "Darkness in the Glade", ["tasks"] = { ["Hatescreech's Amulet"] = "Амулет Ненависного Крику", ["Windmistress Gaedress' Amulet"] = "Амулет Господині Вітрів Гедри", ["Witchmother Arysa's Amulet"] = "Амулет Відьми-Матері Ариси" } },
    [98393] = { [1] = "Великий котячий дух", [2] = "Здається, ти готовий до наступного кроку у своїй подорожі, юний друїде. Дендрит Зоряний Блейз послав за тобою і бажає, щоб ти знову знайшов його в Мунґлейді.\n\nТи вже навчився закликати магію, щоб вона перенесла тебе до Мунґлейду, тому ти зможеш негайно вирушити на корабель, якщо забажаєш. Я б порадив тобі вирушити незабаром, якщо ти хочеш продовжити своє друїдське навчання.", [3] = "Поговоріть з Дендритом Зоряним Сяйвом у селі Найтхейвен, Місячна Галявина.", ["en"] = "The Great Cat Spirit" },
    [98394] = { [1] = "Великий котячий дух", [2] = "У південній частині Місячної Галявини, на пагорбі, з якого видно міст, мешкає мудра та хитра істота, яку ми називаємо Великим Духом Кота.\n\nПодібно до Великого Духа Ведмедя, цей дух служив наставником та вихователем для друїдів, які бажають прийняти котячу форму. Усі друїди зрештою шукають його мудрості, і якщо ви бажаєте прийняти котячу форму, ви теж її отримаєте.\n\nЗустріньтеся з Великим Духом Кота та дізнайтеся, чого він вас навчить.", [3] = "Знайдіть Великого Котячого Духа в південній частині Місячної Галявини та дізнайтеся, що він може вам розповісти про котячу природу.", ["en"] = "The Great Cat Spirit" },
    [98396] = { [1] = "Великий котячий дух", [2] = "Щоб звернутися до мого духу, тобі знадобиться більше, ніж кілька слів. Щоб зрозуміти та поважати мою форму, ти повинен довести, що можеш втілювати хитрість, скритність, а якщо тебе заганять у кут, то й лютість.\n\nУ Курганних Лігвах, на схід від цього місця, знаходяться три реліквії моєї милості, які ти повинен здобути. Їх охороняють могутні розлючені духи, які нападуть на тебе одразу. Статуя біля входу благословить тебе тимчасовою скритністю, щоб ти міг пройти повз них.\n\nПоверни мені ці реліквії. Подивимося, чи готовий ти прийняти мою форму.", [3] = "Знайдіть Реліквію Ікла, Реліквію Кігтя та Реліквію Мовчазної Тіні з Кургану Буревісника та поверніть їх Великому Духу Кота.", ["en"] = "The Great Cat Spirit", ["tasks"] = { ["Relic of the Claw"] = "Реліквія Кігтя", ["Relic of the Fang"] = "Реліквія Ікла", ["Relic of the Silent Shadow"] = "Реліквія Мовчазної Тіні" } },
    [98397] = { [1] = "До Дарнасу", [2] = "Настав час знову розлучитися, юний, оскільки застосування твоїх уроків повертає тебе до того, хто послав тебе до мене. Здається, твій інструктор, Матренгіл Ведмежий Вокер, знайшов у тобі гідного учня. Гадаю, я теж такого бачу. Зважай на його уроки, і незабаром ти зможеш звернутися до Великого Котячого Духа, щоб прийняти його форму.\n\nПовернися туди, звідки ти прийшов. Коли настане час, ми знову зустрінемося.", [3] = "Поверніться до Дарнасу та поговоріть з Матренгіл Ведмежою Вокеркою в Анклаві Кенаріона.", ["en"] = "To Darnassus" },
    [98398] = { [1] = "Дерево Оракула", [2] = "Я вражений тим, чого ви досягли тут за такий короткий час, {ім'я}. Якби я міг попросити вас залишитися тут, щоб допомогти мені з моїми обов'язками... але в глибині душі я знаю, що попереду на вас чекають важливіші завдання.\n\nЯ помітив, що Дерево Оракула щойно скинуло шматок своєї кори. Безсумнівно, у нього є завдання, яке воно бажає виконати. Вам слід поговорити з ним.", [3] = "Знайдіть неподалік кору дерева оракула, щоб отримати її послання.", ["en"] = "The Oracle Tree" },
    [98417] = { [1] = "Слід помсти", [2] = "Коли доля зробила нас найбільш вразливими, на наші поселення впало лихо. Сатири осквернили храми, заплямувавши священні гілки своїм нечестивим дотиком, і безжально вбивали невинних.\n\nКуротеля поглинула лють. Друїди пішли воювати із сатирами, і він рушив за ними.\n\nНаш зв'язок не урвався. Я відчуваю свого чоловіка на заході, серед цих лісів. Будь ласка, повернися зі звісткою про його долю.", [3] = "Масеара Осінній Місяць просить вас шукати серед демонів Сатирнаара на захід від Лісової Пісні. Повернувшись, повідомте їй усе, що дізнаєтеся про її чоловіка Куротеля.", ["en"] = "Vengeful Trail", ["tasks"] = { ["Vine-Wrapped Scroll"] = "Сувій, обвитий лозою" } },
    [98418] = { [1] = "Спільна лють", [2] = "Куротель згадував, що бачив істот, яких називають вовкулаками. Тепер їхня зграя дедалі численніша в нашому лісі. Востаннє, коли ми говорили, друїди намагалися порозумітися з тими, хто мав звірине серце, але ще стримував тваринні інстинкти.\n\nЙого лист свідчить про похмурішу боротьбу. Якщо можемо хоч якось знову побачити ЙОГО, то приборкання демонічної загрози, яка штовхає його до цієї палкої зміни, напевно допоможе його змученій душі.\n\nУбий ксавіанських демонів, {ім'я}.", [3] = "Убийте по 5 ксавіанських пройдисвітів, присяжників Скверни, зрадників і пеклокликачів.\nПотім поверніться до Масеари Осіннього Місяця в Лісову Пісню.", ["en"] = "Shared Fury", ["tasks"] = { ["Xavian Betrayer"] = "Ксавіанський зрадник", ["Xavian Betrayer slain"] = "Ксавіанський зрадник: убито", ["Xavian Felsworn"] = "Ксавіанський присяжник Скверни", ["Xavian Felsworn slain"] = "Ксавіанський присяжник Скверни: убито", ["Xavian Hellcaller"] = "Ксавіанський пеклокликач", ["Xavian Hellcaller slain"] = "Ксавіанський пеклокликач: убито", ["Xavian Rogue"] = "Ксавіанський пройдисвіт", ["Xavian Rogue slain"] = "Ксавіанський пройдисвіт: убито" } },
    [98423] = { [1] = "Договір про взаєморозуміння", [2] = "Усередині сховища ви знайдете табличку з детальним описом умов мирного договору між кланами гномів Бронзобороди та Дикого Молота. Схоже, що вона датується періодом одразу після Війни Трьох Молотів і, ймовірно, є визначною пам'яткою історії гномів. Король Залізогарта, безсумнівно, зацікавився б цим артефактом.", [3] = "Доставте Договір про взаєморозуміння Магні Бронзобороду в Залізогарті.", [4] = "Що ти приніс із глибин, воїне?", [5] = "А, так. Мій предок Мадоран був першим королем Залізогарта з клану Бронзобородих після великої громадянської війни між кланами Дикого Молота, Бронзобородих і Темного Заліза. Цей договір уклали, щоб закріпити припинення ворожнечі та умови миру після перемоги Бронзобородих у горі.\n\nЯк бачиш, його підписали Дикі Молоти й Бронзобороді... а Темне Залізо — ні.\n\nДякую, що {стать:відшукав:відшукала} його й {стать:приніс:принесла} мені, {стать:воїне:воїтелько}.", ["en"] = "The Treaty of Understanding", ["tasks"] = { ["Deliver the Treaty of Understanding to Magni Bronzebeard in Ironforge."] = "Доставте Договір про взаєморозуміння Магні Бронзобороду в Залізогарті.", ["Treaty of Understanding"] = "Договір про взаєморозуміння", ["Treaty of Understanding (Provided)"] = "Договір про взаєморозуміння (видано)" } },
    [98459] = { [1] = "Брак чесноти", [2] = "Барт Тайдвотер — нікчемний скупердяй, кажу вам!\n\nВін себе називає «Капітаном Дівочої Чесноти». Цей корабель доплив аж до скелі в Танарісі! Він не капітан, він актор, який виграв достатньо роздач у покер, щоб купити Чесноту!\n\nЯкщо ти колись опинишся в гавані Менетіл у Болотах, віддай йому це і скажи, що це від старого Напівриби.\n\nДо речі, звідси є човен, який може доставити тебе прямо до гавані. Це буде друга зупинка!\n\nІ він шахраює в покері!", [3] = "Доставте подарунок Тома Барту Тайдвотеру в гавані Менетіл у водно-болотних угіддях.", ["en"] = "A Lack of Virtue", ["tasks"] = { ["Tom's Gift"] = "Подарунок Тома", ["Tom's Gift (Provided)"] = "Подарунок Тома (видано)" } },
    [98461] = { [1] = "Нерозділене кохання", [2] = "Якщо ти збираєшся з Обердіна, мені знадобиться твоя допомога!\n\nМи з моїм дорогим другом Таррелом були однокласниками в школі. О, він був таким швидким у всьому, що пов'язано з розкопками! Після випуску нас розділили — його до Болотних Угідь, а мене сюди, до Темнобережжя.\n\n<Голлі зітхає, потім її брови злегка хмуряться.>\n\nВибач, а його дружина... Меррін.\n\nЦе не має значення. Якщо ти поїдеш до Болотних Угідь, чи не міг би ти переконатися, що з ним все гаразд? І, можливо, передати йому ось це? Він, мабуть, біля гавані Менетіл. Прямо там є човен.", [3] = "Доставте записку Холлі Таррелу Рок-Ткачу біля гавані Менетіл у Болотах.", ["en"] = "Unrequited Love", ["tasks"] = { ["Hollee's Note"] = "Записка Холлі", ["Hollee's Note (Provided)"] = "Записка Холлі (видано)" } },
    [98463] = { [1] = "Про що гомонить місто", [2] = "Слухай, я радий бачити тебе у своєму барі, і саме тому кажу це.\n\nДе справжні веселощі? У таверні «Солоний Моряк» у Грабіжній Бухті. Так, у Тернистій долині — у тій самій Грабіжній Бухті.\n\nНе дивися на мене так. Знаю, там усім заправляють гобліни. Бармени балакають, а відвідувачі — ДУЖЕ багато. Я лише кажу: якщо хочеш побачити по-справжньому шалені веселощі, вирушай туди.\n\nНіксраз Наливайко подбає, щоб твій кухоль був повним. Навіть не хвилюйся.", ["en"] = "Talk of the Town" },
    [98471] = { [1] = "Послання від верховного магістра", [2] = "Вітаю, {ім'я}.\n\nМаю для тебе доручення найвищої важливості. Зустрінься зі мною в Альтерацьких горах, на північний захід від поселення Странбрад. Я чекатиму на скелі над долиною Нагір'я.\n\nПриходь сам і нікому не кажи.", ["en"] = "Message from the Supreme Magister", ["tasks"] = { ["Message from the Supreme Magister (Provided)"] = "Послання від верховного магістра (видано)" } },
    [98574] = { [1] = "Священний Меморандум", [2] = "Поки ти мені допомагав, мені дали цей меморандум, щоб я його тобі передав. Приділи трохи часу, щоб його прочитати, коли матимеш нагоду. Гадаю, він від тренера священиків Бренстока. Поглянь на нього та йди пошукай його в Анвілмарі, коли матимеш таку можливість.", [3] = "Прочитайте Священний Меморандум і поговоріть з Бренстоком Халдером в Анвілмарі.", ["en"] = "Hallowed Memorandum", ["tasks"] = { ["Hallowed Memorandum"] = "Священний Меморандум", ["Hallowed Memorandum (Provided)"] = "Священний Меморандум (видано)", ["Hallowed Memorandum slain"] = "Священний Меморандум: убито" } },
    [98581] = { [1] = "Архаїчна руна", [2] = "Поки ти мені допомагав, мені дали цю руну, щоб я передав її тобі. Приділи трохи часу, щоб прочитати її, коли матимеш таку можливість. Виходячи зі стилю цих написів у стилі Дикого Молота, я гадаю, що вона належить тренеру шаманів Тео Молотковому. Поглянь на неї та йди знайди його в Анвілмарі, коли матимеш таку можливість.", [3] = "Прочитайте Архаїчну Руну та поговоріть з Тео Молотштормом в Анвілмарі.", ["en"] = "Archaic Rune", ["tasks"] = { ["Archaic Rune"] = "Архаїчна руна", ["Archaic Rune (Provided)"] = "Архаїчна руна (видано)", ["Archaic Rune slain"] = "Архаїчна руна: убито" } },
    [98731] = { [1] = "Благословення Великого Котячого Духа", [2] = "Тепер, коли ти отримав моє благословення, повертайся до Дендрита. Він надасть тобі подальші вказівки. Я дуже сподіваюся, що ми колись знову зустрінемося.\n\nНехай тіні назавжди приховують тебе, а твої вороги легко стануть жертвами твоїх кігтів, юний.", ["en"] = "Blessings of the Great Cat Spirit" },
    [98824] = { [1] = "Доісторична призма", [2] = "З такими схожими на титанські написами на гранях їй місце лише в Залі дослідників Залізогарту.\n\nХочеться вірити, що твоє ім'я увійде до історії в каталозі: «Знайдено: {ім'я}! Автентичність підтверджена розвідувачем Вельґаром...» Ох, щось я захопився.\n\nСтарший дослідник Маґеллас прийме тебе. З огляду на вишуканість твоєї знахідки, він напевно щедро віддячить, якщо подаруєш її музею.\n\nГарна знахідка!", [3] = "Віднесіть реліквію титанів старшому досліднику Маґелласу в Залу дослідників Залізогарту.", ["en"] = "Prehistoric Prism", ["tasks"] = { ["Titan Relic"] = "Реліквія титанів" } },
    [99046] = { [1] = "Загублений бігун", [2] = "Лісова Рада деякий час тому відправила невелику групу вартових до Дерева Оракула. Дерево надсилає повідомлення нашим старійшинам, і нам доводиться безпечно доставити їх до Дарнасу.\n\nЯ отримав звістку, що наш останній бігун ще не прибув. Повідомлення Оракула надходять з різною частотою, але вони надходять незвично довго.\n\nБудь ласка, прямуйте до Галявини Оракула дорогою на захід і перевірте її стан. Це була черга Ералії Тіні Листя, і вона все ще тренується. Елуна вас проведе.", [3] = "Шукайте Вартову Ералію Тінь Листя на дорозі, що веде до Галявини Оракула.", ["en"] = "The Lost Runner" },
    [99047] = { [1] = "Ще не мертвий", [2] = "Моїх сестер і мене... відправили... Оракул Дерево...\n\nДерево... повідомлення. Я... гарпії... всюди...\n\n<Ералія кашляє кров'ю, кривляючись від болю.>\n\nМожливо, мені недовго залишиться... ніхто не прийде. Будь ласка... Б'янсі... у Доланаарі...", [3] = "Зверніться за допомогою до Б'янсі в Долаанарі для отримання Вартової Ералії Тіні Листя.", ["en"] = "Not Dead Yet" },
    [99050] = { [1] = "Велике дерево забезпечує", [2] = "Мені знадобиться ваша допомога у придбанні інгредієнтів, необхідних для зупинки хвороби на достатній термін, щоб Ералья могла повернутися сюди для подальшого лікування.\n\nНа щастя, наш живий дім все ще щедрий і забезпечить нас у скрутний час.\n\nОсновним інгредієнтом є росяне листя лашера. Ви знайдете його навколо озера Аль'Амет, що знаходиться прямо на південь від нас, або біля озера Веллспринг та його річки на північний захід.\n\nКрім того, мені знадобиться порожня пляшечка та трохи джерельної води. І те, й інше можна купити тут, у місті, або обміняти.", [3] = "Зберіть 6 росяних гілок батога, порожню пляшечку та освіжаючу джерельну воду для Б'янсі в Доланаарі.", ["en"] = "The Great Tree Provides", ["tasks"] = { ["Dewy Lasher Frond"] = "Росястий візерунок", ["Empty Vial"] = "порожній фіал", ["Refreshing Spring Water"] = "освіжаюча джерельна вода" } },
    [99053] = { [1] = "Втеча з Бан'етілу", [2] = "Мої молитви почуті! Я вдячний, що ви пробилися сюди.\n\nМене сюди послало Дерево Оракула, щоб доставити повідомлення сплячим друїдам, але я виявив, що його повністю захопили фурболги! Вони влаштували мені засідку, перш ніж я встиг повернутися, і привели мене сюди — боюся за їхню наступну трапезу.\n\nНе знаю, як ви, але я ненавиджу це місце. Під землею немає місця для калдорай.", [3] = "Допоможіть Вартовій Лінессі Сутінковий Цвіт втекти з Кургану Бан'етіл та повідомте Вартовій Кірі Зоряної Пісні в Доланаарі про її безпеку.", ["en"] = "Escaping Ban'ethil", ["tasks"] = { ["Escort Lynessa Duskblossom out of Ban'ethil"] = "Виведіть Лінессу Сутінкову квітку з Бан'етилу" } },
    [99073] = { [1] = "Полегшення страждань", [2] = "Мазь готова. Швидко віднесіть її Ералії.\n\nЯ не знаю, чи це справді її вилікує. Гниль швидко гноїться і міцніє, поширюючись.\n\nЦе, як мінімум, полегшить її страждання. І це все одно варте вашої поспішності.", [3] = "Віднесіть мазь Лашвода до Вартової Ералії Тіні Листя на дорозі до Дерева Оракула.", ["en"] = "Easing Suffering", ["tasks"] = { ["Lashwater Salve"] = "Бальзам для вій", ["Lashwater Salve (Provided)"] = "Бальзам для вій (видано)" } },
    [99127] = { [1] = "Мережева катастрофа", [2] = "Риба сьогодні просто не клює, і з нею щось не так. Це не просто порожні гачки. Я взагалі не бачив жодного малька у воді.\n\nЛі тут на ніч розставив кілька пасток, перевір, чи є у нас там хоча б якась рибина. Якщо знайдеш щось дивне, обов'язково покажи мені.", [3] = "Перевірте рибальські сіті в озері Крістал.", ["en"] = "A Net Disaster", ["tasks"] = { ["Half-Eaten Fish"] = "Напівз'їдена риба", ["Half-Eaten Fish (Provided)"] = "Напівз'їдена риба (видано)", ["Half-Eaten Fish slain"] = "Напівз'їдена риба: убито" } },
    [99128] = { [1] = "Слизька загроза", [2] = "Це може бути лише роботою тих мурлоків з іншого боку озера. Вони огидні маленькі створіння, з лютим характером та відповідними зубами.\n\nЯкщо ми дозволимо цьому продовжуватися, то в цьому озері не залишиться жодної риби. Якби ви могли трохи їх очистити, це б мені дуже допомогло.", [3] = "Убийте мурлоків на Кришталевому озері.", ["en"] = "Slimy Menace", ["tasks"] = { ["Murloc"] = "мурлок", ["Murloc Streamrunner"] = "мурлок-річковий бігун", ["Murloc Streamrunner slain"] = "мурлок-річковий бігун: убито", ["Murloc slain"] = "мурлок: убито" } },
    [99129] = { [1] = "Людина про мурлока", [2] = "Ремі згадував про мурлоків днями... Я впевнений, що він ненавидить цих маленьких мерзотників так само сильно, як і я.\n\nМожливо, у нього є якісь ідеї, як тримати їх подалі від моїх рибок у майбутньому. Я хотів би попросити вас поспілкуватися з ним і дізнатися, чи є щось, що він може придумати.", [3] = "Поговоріть з Ремі \"Двічі\" про проблеми Джейсона з мурлоками.", ["en"] = "A Man About a Murloc" },
    [99130] = { [1] = "Приваблива пропозиція", [2] = "У мене є кілька ідей, як боротися з мурлоками. І одна з них також допомагає деяким іншим у цьому процесі.\n\nНа фермах у цій місцевості часто зустрічається бур'ян під назвою сутінковий дурник, і у великих кількостях його пелюстки токсичні для більшості тварин. Якщо ми зробимо приманку для мурлоків з цієї рослини, сподіваємося, що це зможе навчити цих істот триматися подалі.\n\nІ деякі фермери в процесі очищають свої поля. Дійсно безпрограшний варіант... справді безпрограшний варіант.", [3] = "Зберіть інгредієнти для приманки для мурлоків.", ["en"] = "An Enticing Offer", ["tasks"] = { ["Duskweed Petal"] = "Пелюстка сутінкової трави", ["Duskweed Petal (Provided)"] = "Пелюстка сутінкової трави (видано)", ["Duskweed Petal slain"] = "Пелюстка сутінкової трави: убито", ["Vial of Animal Blood"] = "Флакон з тваринною кров'ю", ["Vial of Animal Blood (Provided)"] = "Флакон з тваринною кров'ю (видано)", ["Vial of Animal Blood slain"] = "Флакон з тваринною кров'ю: убито" } },
    [99131] = { [1] = "Заманені для успіху", [2] = "Скажи Мазерсу, що він може прийти за наживкою пізніше сьогодні. Я розповім йому, як її правильно використовувати.\n\nСподіваюся, він скоро знову зможе продавати свою рибу. І в цьому світі буде менше мурлоків.", [3] = "Повернення до Джейсона Матерса.", ["en"] = "Baited for Success" },
    [99143] = { [1] = "Пляшки та дрібнички", [2] = "Ці риболови, мабуть, думають як справжні риби, чи не так? Це означає, що все, що подобається їм, подобається і рибі!\n\nЯкщо ви переберете їхнє мотлох і повернетеся до мене з чимось, що здається гарною наживкою, я вас винагороджу.", [3] = "Зберіть 6 шматків блискучого мотлоху з сусіднього табору мурлоків.", ["en"] = "Bottles and Baubles", ["tasks"] = { ["Shiny Junk"] = "Блискучий сміття", ["Shiny Junk (Provided)"] = "Блискучий сміття (видано)", ["Shiny Junk slain"] = "Блискучий сміття: убито" } },
    [99158] = { [1] = "Світанок у горах", [2] = "У горах живе священник, який належить до організації під назвою Сріблястий Світанок. Це свята спільнота, що присвятила себе пошуку та знищенню всього нечестивого й неприродного.\n\nА от отець Ґевін радше прагне допомагати та зцілювати всіх, ніж братися за зброю. Він облаштував стару будівлю як місце відпочинку для мандрівників.\n\nУ мене є партія святих свічок, яку треба йому доставити. Якщо тобі по дорозі, можеш віднести їх?", [3] = "Віднесіть ящик свічок отцю Ґевіну.", [4] = "Чому Світло привело тебе сюди сьогодні?", [5] = "А, свічки із Залізогарта.\n\nЗдебільшого я можу жити самітником без сторонньої допомоги, але є кілька речей із міста, за які я вдячний вірянам.", ["en"] = "Dawn in the Mountains", ["tasks"] = { ["Bring the crate of candles to Father Gavin at Misty Pine Refuge."] = "Віднесіть ящик свічок отцю Ґевіну до прихистку Імлистої Сосни.", ["Bring the crate of candles to Father Gavin."] = "Віднести ящик свічок отцю Ґевіну", ["Crate of Candles"] = "ящик свічок", ["Crate of Candles (Provided)"] = "ящик свічок (видано)" } },
    [99159] = { [1] = "Знаходження тепла", [2] = "Моє вогнище відкрите, щоб зігріти будь-яку душу, але я хотів би попросити вас допомогти мені, якщо ви можете.\n\nМені просто потрібно більше дров. Зазвичай я б зробив це сам, але я був зайнятий іншими справами.", [3] = "Зберіть 14 дров.", [4] = "Нехай Світло веде тебе в твоїх справах.", [5] = "А, чудово. Ці дрова згодяться. Ті, що зараз надто мокрі, я залишу висихати.\n\nЯкщо ти не проти, мені знадобиться допомога ще з кількома справами.", ["en"] = "Finding Warmth", ["tasks"] = { ["Mostly Dry Firewood"] = "Переважно сухі дрова", ["Mostly Dry Firewood (Provided)"] = "Переважно сухі дрова (видано)", ["Mostly Dry Firewood slain"] = "Переважно сухі дрова: убито" } },
    [99160] = { [1] = "Гнів Рима", [2] = "Можливо, ви помітили стихій поблизу. Кілька днів тому з гірських вершин упав кам'яний та крижаний уламок, що їх розлютило.\n\nЦі замерзлі гори вже підступні для пересічного гнома чи людини, навіть якщо стихії не набувають форми. Я більше не з тих, хто вбиває, тому будь-який дух, якого ви можете вбити, допоможе зробити дорогу безпечнішою.", [3] = "Знищити 10 другорядних крижаних елементалів.", [5] = "Хотілося б, щоб їх можна було просто втихомирити. На жаль, я не знав як, а залишати їх було надто небезпечно.", ["en"] = "Rime's Wrath", ["tasks"] = { ["Minor Ice Elemental"] = "Незначний крижаний елементаль", ["Minor Ice Elemental (Provided)"] = "Незначний крижаний елементаль (видано)", ["Minor Ice Elemental slain"] = "Незначний крижаний елементаль: убито" } },
    [99161] = { [1] = "Гнів Рима", [2] = "Я помітив, що перший елементаль, який з'явився після зсуву скель, був більшим за своїх аналогів. І, наскільки я можу судити, він був джерелом періодичних змін погоди та інших незначних зсувів.\n\nЯ називав його «Авала». Якщо ви зможете його вбити та отримати ядро як доказ, я винагороджу вас.", [3] = "Знищити Авалу та повернути її ядро.", [4] = "Стережися зими, друже.", [5] = "Нехай Світло благословить тебе, {стать:воїне:воїтелько}. Завдяки твоїм зусиллям тут стало значно безпечніше, і, сподіваюся, більше ніхто не загине марно.", ["en"] = "Rime's Wrath", ["tasks"] = { ["Avala's Core"] = "Ядро Авали", ["Avala's Core (Provided)"] = "Ядро Авали (видано)", ["Avala's Core slain"] = "Ядро Авали: убито" } },
    [99162] = { [1] = "Підступний холод", [2] = "Навіть альпіністи з Айронфорджу повинні бути пильними, перетинаючи вершини Дун Морог. Падаючий сніг та лід часто означають кінець життя деяких новачків.\n\nПісля обвалу я зазвичай намагаюся знайти будь-які ознаки тих, хто вижив, чи жертв, молячись Світлу, щоб нічого не знайшли. Але через стихію я утримався від блукання надто далеко. Якщо ви можете пошукати кількох заблукалих альпіністів і принести мені їхні гвинтівки, я поверну їх до Айронфорджу.", [3] = "Зберіть гвинтівки полеглих альпіністів.", [4] = "Що тобі потрібно?", [5] = "Горяни викарбовують свої імена на прикладах рушниць. Це допомагає впізнати їх, якщо станеться лихо. Я відправлю рушниці до Залізогарта — там їх передадуть родинам.", ["en"] = "Treacherous Cold", ["tasks"] = { ["Coalbeard's Rifle"] = "Гвинтівка Вугільної Бороди", ["Coalbeard's Rifle (Provided)"] = "Гвинтівка Вугільної Бороди (видано)", ["Coalbeard's Rifle slain"] = "Гвинтівка Вугільної Бороди: убито", ["Stoneanvil's Rifle"] = "Гвинтівка Кам'яної Ковадла", ["Stoneanvil's Rifle (Provided)"] = "Гвинтівка Кам'яної Ковадла (видано)", ["Stoneanvil's Rifle slain"] = "Гвинтівка Кам'яної Ковадла: убито", ["Sunhammer's Rifle"] = "Гвинтівка Сонячного Молота", ["Sunhammer's Rifle (Provided)"] = "Гвинтівка Сонячного Молота (видано)", ["Sunhammer's Rifle slain"] = "Гвинтівка Сонячного Молота: убито" } },
    [99191] = { [1] = "Пожертва вовняного полотна", ["en"] = "A Donation of Wool", ["tasks"] = { ["Wool Cloth"] = "вовняне полотно" } },
    [99260] = { [1] = "Місія Філліона", [2] = "Мені доручили здобути важливі дані про потоки стихійної енергії біля стоячих каменів Оглядової скелі. Ці дані життєво необхідні для наших планів безпечних подорожей між Небесною Виссю й Азеротом. Без них наші розрахунки будуть неповними, а спроби провести небесні кораблі крізь стихійний вимір зазнають невдачі.\n\nТепер дані, скоріш за все, втрачено, а я не в тому стані, щоб збирати їх знову. Я розповів верховному магістрові, як ти мене врятував, і він хоче знову поговорити з тобою.", [3] = "Поговоріть з Елаадріном Вечірнім Вітром у Валанаарі.", [5] = "Дякую, що врятував Філліона, {ім'я}. Певен, він пояснив, наскільки важливі дані, по які його послали.\n\nБез цих даних наші перспективи відкрити безпечні шляхи до Азероту опинилися під серйозною загрозою. Шпигуни повідомляють, що Творці Вітру вже здобули засоби для подорожей між вимірами й, без сумніву, ревно берегтимуть цю таємницю.\n\nЯк завжди, їхня догматична пиха важливіша за добробут нашого народу. Вони ненабагато кращі за Ал'Акетів.", ["en"] = "Fillion's Mission" },
    [99267] = { [1] = "Нещасливий кінець", [5] = "Мертвий вартовий Нічної Варти перед вами вкритий глибокими ранами й порізами. Вочевидь, його розшматував якийсь великий звір.\n\nВи помічаєте, що труп досі тримає незапалений смолоскип. Схоже, раніше ви його так і не взяли.\n\nНахиляєтеся й вивільняєте смолоскип із закляклих пальців. Він може стати в пригоді під час мандрів Смерколіссям та іншими землями, освітлюючи те, що ховається в темряві.", ["en"] = "An Unfortunate End" },
    [997] = { [1] = "Земля Деналана", [2] = "То ти йдеш на південь? До озера Аль'Амет? Якщо так, не {стать:міг би:могла б} ти виконати одне моє прохання...\n\nМій побратим Деналан мешкає в таборі біля східної частини озера. Він займається вивченням життя рослин Тельдрассіля та проводить власні дослідження. Для продовження йому потрібна рідкісна земля з Дарнасу, але її доставили нам лише недавно в Доланаар із запізненням.\n\nЧи не {стать:міг би:могла б} ти віднести йому цю пригорщу?", [3] = "Віднесіть пригорщу рідкісної землі Деналану біля озера Аль'Амет.", [4] = "Ти щось мені {стать:приніс:принесла}?", [5] = "Нарешті! Я вже давно чекаю на цю землю. Сподіваюся, вона ще свіжа...\n\nБезмежно вдячний тобі за допомогу, {Ім'я}. Ти {раса}, що не шкодує свого часу на благі діяння!", ["en"] = "Denalan's Earth", ["tasks"] = { ["Rare Earth"] = "рідкісна земля", ["Rare Earth (Provided)"] = "рідкісна земля (видано)" } },
}
addonTable.quest_alliance = quest_alliance

local quest_horde = {
    [1000] = { [1] = "Нові рубежі", [2] = "Увага, герої!\n\nКенарійське Коло шукає здібних осіб, які допоможуть в дослідженні нових безкраїх рубежів Калімдору! Далеко на заході від Танарісу та Пристробляху лежить загадкова пустеля, сповнена неймовірних небезпек, і Колу потрібні охочі та благородні герої, що діятимуть від його імені.\n\nУсі зацікавлені повинні звернутися до Кенарійського Кола. Поговоріть з верховним друїдом Гамуулом Рунним Тотемом на Верхів'ї Старійшин у Громовому Бескиді для отримання подальшої інформації!", [3] = "Поговоріть з верховним друїдом Гамуулом Рунним Тотемом на Верхів'ї Старійшин у Громовому Бескиді з приводу заклику Кенарійського Кола на експедицію до нових рубежів Калімдору.", [5] = "Вітаю, {клас:к}.\n\nЯ радий бачити, що такі, як ти, цікавляться благополуччям природи; тобі передують розповіді про твої величні діяння, і тут раді тобі. Твоя присутність переді мною вселяє почуття впевненості в тому, що Кенарійське Коло отримає належну допомогу, якої потребує.\n\nНаш зв'язок із Кенарійським Колом в Місячній галявині вищий за расові та політичні розбіжності. Пам'ятай про це, коли працюватимеш від імені Кола, і тоді ти досягнеш успіху.", ["en"] = "The New Frontier" },
    [1004] = { [1] = "Нові рубежі", [2] = "Увага, герої!\n\nКенарійське Коло шукає здібних осіб, які допоможуть в дослідженні нових безкраїх рубежів Калімдору! Далеко на заході від Танарісу та Пристробляху лежить загадкова пустеля, сповнена неймовірних небезпек, і Колу потрібні охочі та благородні герої, що діятимуть від його імені.\n\nУсі зацікавлені повинні звернутися до Кенарійського Кола. Поговоріть з верховним друїдом Гамуулом Рунним Тотемом на Верхів'ї Старійшин у Громовому Бескиді для отримання подальшої інформації!", [3] = "Поговоріть з верховним друїдом Гамуулом Рунним Тотемом на Верхів'ї Старійшин у Громовому Бескиді з приводу заклику Кенарійського Кола на експедицію до нових рубежів Калімдору.", [5] = "Вітаю, {клас:к}.\n\nЯ радий бачити, що такі, як ти, цікавляться благополуччям природи; тобі передують розповіді про твої величні діяння, і тут раді тобі. Твоя присутність переді мною вселяє почуття впевненості в тому, що Кенарійське Коло отримає належну допомогу, якої потребує.\n\nНаш зв'язок із Кенарійським Колом в Місячній галявині вищий за расові та політичні розбіжності. Пам'ятай про це, коли працюватимеш від імені Кола, і тоді ти досягнеш успіху.", ["en"] = "The New Frontier" },
    [1013] = { [1] = "Книга Ура", [2] = "{Ім'я}, у фортеці Тіньового Ікла знаходиться книга Ура, яку я б дуже хотів мати у своїй колекції. Ур був видатним магом Даларану до приходу Скари, його дослідження інших світів безцінні для... деяких відречених.\n\nВирушай у фортецю Тіньового Ікла і знайди цю книгу. Принеси її мені і я доповім про твою службу нашій Темній Леді...", [3] = "Принесіть книгу Ура до хранителя Бел'дуґура, що знаходиться в Апотекарії в Підмісті.", [4] = "Ти {стать:знайшов:знайшла} книгу, {ім'я}?", [5] = "Дуже добре. Ця книга чудово доповнить мою колекцію робіт Ура. Його знання були величні, але совість утримувала його від справжньої міці. Саме через це, коли прийшла Скара, він не зміг їй протистояти.\n\nМи, відречені, не можемо дозволити собі такої слабкості, якщо хочемо вижити...\n\n...або підкоряти.", ["en"] = "The Book of Ur", ["tasks"] = { ["The Book of Ur"] = "книга Ура", ["The Book of Ur (Provided)"] = "книга Ура (видано)" } },
    [1014] = { [1] = "Аруґал мусить померти", [2] = "Срібнохвойний параліс є важливим стратегічним опорним пунктом для Темної Леді. Але ми не зможемо закріпитися тут, доки Аруґал живий. Він досі знаходиться у фортеці Тіньового Ікла.\n\nЯ подбаю про те, щоб його магія була викорінена, {Ім'я}. Але саме ти маєш зробити так, щоб Аруґал помер. Він заслуговує на це.\n\nНаправляйся до фортеці Тіньового Ікла і поклади край його нечистій магії, раз і назавжди. Принеси мені голову цього мерзенного чаклуна!", [3] = "Вбийте Аруґала і принесіть його голову Далару Ранньоткачу в Крипту.", [4] = "Зі смертю Аруґала ми зміцнимо позиції Темної Леді в Лордероні.", [5] = "Срібнохвойний праліс нарешті звільнився від порочного Аруґала. Ти гарно {стать:послужив:послужила} Темній Леді, {Ім'я}. Твоя завзятість буде винагороджена.", ["en"] = "Arugal Must Die", ["tasks"] = { ["Head of Arugal"] = "голова Аруґала", ["Head of Arugal (Provided)"] = "голова Аруґала (видано)" } },
    [1018] = { [1] = "Нові рубежі", [2] = "Увага, герої!\n\nКенарійське Коло шукає здібних осіб, які допоможуть в дослідженні нових безкраїх рубежів Калімдору! Далеко на заході від Танарісу та Пристробляху лежить загадкова пустеля, сповнена неймовірних небезпек, і Колу потрібні охочі та благородні герої, що діятимуть від його імені.\n\nУсі зацікавлені повинні звернутися до Кенарійського Кола. Поговоріть з верховним друїдом Гамуулом Рунним Тотемом на Верхів'ї Старійшин у Громовому Бескиді для отримання подальшої інформації!", [3] = "Поговоріть з верховним друїдом Гамуулом Рунним Тотемом на Верхів'ї Старійшин у Громовому Бескиді з приводу заклику Кенарійського Кола на експедицію до нових рубежів Калімдору.", [5] = "Вітаю, {клас:к}.\n\nЯ радий бачити, що такі, як ти, цікавляться благополуччям природи; тобі передують розповіді про твої величні діяння, і тут раді тобі. Твоя присутність переді мною вселяє почуття впевненості в тому, що Кенарійське Коло отримає належну допомогу, якої потребує.\n\nНаш зв'язок із Кенарійським Колом в Місячній галявині вищий за расові та політичні розбіжності. Пам'ятай про це, коли працюватимеш від імені Кола, і тоді ти досягнеш успіху.", ["en"] = "The New Frontier" },
    [1049] = { [1] = "Компендіум полеглих", [2] = "Служителі Землі мали чисті наміри щодо наших постраждалих від чуми побратимів. Та хто зна, які наміри у тих, хто нашіптує всіляке на вуха членам ради Старійшин?\n\nУ наших нових союзників, відречених, давня історія підступних задумів. Занадто швидко ми уклали з ними союз. Можливо, Керну варто було прислухатись до попереджень Орґріммару.\n\nГлибоко в Багряному монастирі лежить книга, \"Компендіум полеглих\", яку охороняють людські фанатики. Хоч вони й керуються божевіллям, та їх дослідження стануть нам у пригоді.", [3] = "Знайдіть \"Компендіум полеглих\" в монастирі Тірісфальського перелісся та поверніть її Любомудру Шукачу Істини в Громовий Бескид.", [4] = "Керн — сміливий і благородний лідер, якому я б довірив своє життя. Та є й ті, кому я не довіряю.\n\nЩойно я зберу всі необхідні знання, я зможу дати гідну пораду нашому ватагу.\n\nТи вже {стать:ходив:ходила} до Тірісфальського перелісся? В Багряний монастир? Компендіум полеглих лиш невелика частина задуму...", [5] = "Компендіум полеглих! Я вже думав, що його не існує!\n\nТи гідно {стать:послужив:послужила} тауренам Громового Бескиду, {ім'я}. Ми не забудемо твоєї відданості.", ["en"] = "Compendium of the Fallen", ["tasks"] = { ["Compendium of the Fallen"] = "Компендіум полеглих", ["Compendium of the Fallen (Provided)"] = "Компендіум полеглих (видано)" } },
    [105] = { [1] = "Шкода, Андорал", [2] = "Шкода, але настав час атакувати Андорал та вигнати звідти ліча, який контролює місто.\n\nВ самому серці руїн міста влаштувався ліч — Араж-Закликач. Його охороняють найкращі бійці Скари, що оточують решту центру міста. Тобі знадобиться велика кількість союзників, щоб мати хоч якийсь шанс протистояти йому.\n\nЗнищ Аража, {ім'я}, та принеси мені уламок його філактерії як доказ!", [3] = "Принесіть уламок філактерії Аража верховному карателю Деррінґтону на Вал, в Західні Зачумлені землі.", [4] = "Тобі дали завдання, {ім'я}. Ти {стать:приніс:принесла} уламок філактерії ліча як доказ того, що ти {стать:виконав:виконала} його?", [5] = "Ти {стать:зробив:зробила} це! Араж... ліч нарешті переможений!\n\nСьогодні ти {стать:зробив:зробила} величезну послугу Орді, {ім'я}. Твої сміливість та наполегливість є свідченням твого справжнього героїзму. Прошу, прийми цей знак, щоб всі знали, що завдяки тобі Орда здобула велику перемогу!", ["en"] = "Alas, Andorhal", ["tasks"] = { ["Araj's Phylactery Shard"] = "уламок філактерії Аража", ["Araj's Phylactery Shard (Provided)"] = "уламок філактерії Аража (видано)" } },
    [1051] = { [1] = "Помста Воррела", [2] = "Хоч я й маю волю, я не можу служити Темній Леді. Мій час на Азероті добігає кінця. Життєві сили покидають мене.\n\nЦе зробив зі мною допитувач Вішас! Він тижнями катував мене! Ще й забрав мою обручку і віддав своїй дружині. Покидьок!\n\nЯ хочу помсти!\n\nЦей дурень вихвалявся своєю дружиною, Ненсі, що живе на озері Лордамер. Знайди її, забери обручку і віддай моїй дружині, Моніці. Вона живе на Тарренському Млині.\n\nПрошу, виконай моє останнє прохання...", [3] = "Поверніть обручку Воррела Сенґутца Моніці Сенґутц в Тарренський Млин.", [4] = "Чого ти хочеш, {стать:незнайомцю:незнайомко}?", [5] = "Воррел мав непросте життя. Та він був мені гарним чоловіком...\n\nКляті бридкі люди!\n\nНе бути нам разом в невмерлості. Та принаймні я маю добру звістку про здійснену тобою помсту. Дякую тобі за це.\n\nТепер залиш мене наодинці з моїм горем...", ["en"] = "Vorrel's Revenge", ["tasks"] = { ["Vorrel's Wedding Ring"] = "обручка Воррела", ["Vorrel's Wedding Ring (Provided)"] = "обручка Воррела (видано)" } },
    [1058] = { [1] = "Лісова магія Джин'Зіла", [2] = "Я в захваті!\n\nТри маленькі клітки для трьох маленьких ельфів! Але що нам робити з нашими милими друзями дереволюбами? А давай ми дамо їм відчути смак... як вони це називають... лісової магії!\n\nМені знадобиться добряча порція каміннопазуристої живиці. Принеси мені кілька сутінкових вусів цих жахливих котів. І, звісно ж, багато очей оленів — їх ніколи не буває забагато. А, і не забудь цінну луску чародракончика.\n\nПоспіши на Каміннопазуристий пік, {ім'я}, щоб я зміг зварити трохи лісової магії!", [3] = "Знахарю Джин'Зілу з Малака'джина потрібно 5 порцій каміннопазуристої живиці, 5 сутінкових вусів, 30 очей оленя і луска чародракончика.", [4] = "Поглянь на наших бідолашних друзів-ельфів. Сидять у клітках і не можуть потрапити до лісу, де можна було б погратися!\n\nТи {стать:зміг:змогла} знайти мені трохи живиці? Як щодо вусів сутінкового бігуна? Невже у тебе немає луски чародракончика?\n\nІ очі! Мені потрібно багато очей! Неможливо створити люте лісове магічне вариво без добрячої порції очей!", [5] = "Як же зрадіють ці маленькі лісові німфи! Ми змусимо їх відчувати себе як вдома, приготувавши спеціальне вариво!", ["en"] = "Jin'Zil's Forest Magic", ["tasks"] = { ["Courser Eye"] = "око оленя", ["Courser Eye (Provided)"] = "око оленя (видано)", ["Fey Dragon Scale"] = "луска чародракончика", ["Fey Dragon Scale (Provided)"] = "луска чародракончика (видано)", ["Stonetalon Sap"] = "каміннопазуриста живиця", ["Stonetalon Sap (Provided)"] = "каміннопазуриста живиця (видано)", ["Twilight Whisker"] = "сутінковий вус", ["Twilight Whisker (Provided)"] = "сутінковий вус (видано)" } },
    [1060] = { [1] = "Лист для Джин'Зіла", [2] = "Ти гарно {стать:потрудився:потрудилася} для мене, {ім'я}. Ти справжній щасливий подарунок фортуни для мене, і я хочу тобі щось показати.\n\nСтепи - не батьківщина для гарпій. Вони походять з місця під назвою Каміннопазуристі гори, далеко на північний захід звідси. Скоріш за все, це небезпечне для тебе місце, проте даний лист конче необхідно доправити моєму старому другові, який там живе, знахарю на ім'я Джин'Зіл.\n\nВін зрадіє, дізнавшись, що Серена Кривавопера мертва. А ще, я думаю, що Каміннопазуристі гори видадуться тобі цікавим місцем.", [3] = "Віднесіть лист Дарсока до Джин'Зіла в печеру Малака'Джин, що в Каміннопазуристих горах.", [4] = "{стать:Якийсь:Якась} ти {стать:підозрілий:підозріла}? Маєш що мені сказати?", [5] = "Ааа, лист від Дарсока. Я не чув від нього вже сто років.\n\nТож остання з Кривавоперих мертва, га? Чудова новина, пам'ятаю, коли мій друг Рохан пішов із тим божевільним мок'наталом, щоб вбити її старшу сестру. Ох, от би знову бути молодим, як ти.", ["en"] = "Letter to Jin'Zil", ["tasks"] = { ["Letter to Jin'Zil"] = "лист для Джин'Зіла", ["Letter to Jin'Zil (Provided)"] = "лист для Джин'Зіла (видано)" } },
    [1061] = { [1] = "Духи Каміннопазуристих гір", [2] = "Духи Каміннопазуристих гір розгнівані, бо гобліни та їхні слуги розоряють і випалюють землю. Тож земля закричала, і ті, хто здатен її чути... почули.\n\nСірет Камнелом, багатонадійна шаманка Орди, вирушила до Каміннопазуристих гір. Вона повідомляє, що гобліни масово вирубують ліси і просить про допомогу.\n\nЗустрінься з Сірет в Каміннопазуристих горах. Щоб туди дістатися, прямуй від Перехрестя, що в Степах, дорогою на захід. Сірет отаборилася біля Високолісої долини.", [3] = "Поговоріть з Сірет Камнелом в Каміннопазуристих горах.", [5] = "А, {клас}. Дуже добре. Нам знадобиться твоя допомога, щоб розібратися з цими мародерами!", ["en"] = "The Spirits of Stonetalon" },
    [1062] = { [1] = "Гоблінські загарбники", [2] = "ТзНБ \"Авантюра\", якою керують гобліни, вдерлася в Каміннопазуристі гори. Вони вирубують дерева і спалюють величезні ділянки лісу. Духи цих земель у нестямі від болю та люті. Ми повинні зупинити ТзНБ \"Авантюра\"!\n\nПрямуй на північний захід, за Високолісу долину, до Вітрокосих скель. Ти знайдеш гоблінів та їхніх слуг за роботою — покажи їм, що Орда не дозволить плюндрувати Каміннопазуристі гори. Поясни їм це мовою, яку вони найкраще розуміють...\n\nМовою насильства.", [3] = "Вбийте 15 лісорубів ТзНБ \"Авантюра\", а потім поверніться до Сірет Камнелом на кордон Каміннопазуристих гір та Степів.", [4] = "Високоліса долина лежить на північний захід звідси, {ім'я}. Прямуй туди і всели страх у тих, хто хоче розграбувати ці землі!", [5] = "Це відважний вчинок, {ім'я}.\n\nЗрештою, нам може знадобитися мудрість старійшин тауренів, щоб заспокоїти духів Каміннопазуристих гір, але...\n\nПозбавлення від працівників ТзНБ \"Авантюра\" — гарний перший крок.", ["en"] = "Goblin Invaders", ["tasks"] = { ["Venture Co. Logger"] = "лісоруб ТзНБ \"Авантюра\"", ["Venture Co. Logger slain"] = "лісоруб ТзНБ \"Авантюра\": убито" } },
    [1063] = { [1] = "Старша відьма", [2] = "Щоб остаточно заспокоїти духів Каміннопазуристих гір, ми маємо порадитися зі старійшинами тауренів.\n\nЯ знаю небагато імен їхніх старійшин, лиш одне: Маґата. Я чула, що вона дуже стара і багато знає. Якщо хтось з тауренів і може допомогти нам з духами, то це вона.\n\nМаґата мешкає в столиці тауренів — Громовому Бескиді, на Верхів'ї Старійшин — північно-східній вершині міста. Поговори з Маґатою і розкажи їй про те, що коїться в Каміннопазуристих горах.", [3] = "Поговоріть з Маґатою в Громовому Бескиді.", [5] = "Вітаю тебе. Ти {стать:прийшов:прийшла} за порадою?", ["en"] = "The Elder Crone" },
    [1064] = { [1] = "Допомога відречених", [2] = "Таурени мають тісний зв'язок із землею, і мені боляче чути про те, що коїться в Каміннопазуристих горах. Але я боюся, що для зцілення цієї землі ми спершу маємо вилікувати її від хвороби.\n\nХіба це не щастя, що відречені — наші союзники? Вони багато знають про хвороби. Я впевнена, що вони зможуть допомогти нам, і цим самим зміцнити довіру між нашими народами.\n\nПоговори з аптекаркою Замою. Вона — вчена і представниця відречених. Ти знайдеш її біля Джерел Видіння під Верхів'ям Духів.", [3] = "Поговоріть з аптекаркою Замою біля Джерел Видіння у Громовому Бескиді.", [5] = "Маґата попередила про твій прихід, {ім'я}. Хоча моє серце більше не б'ється, я все ж відчуваю скорботу за духами Каміннопазуристих гір.\n\nВідречені готові допомогти всім, чим зможуть.", ["en"] = "Forsaken Aid" },
    [1065] = { [1] = "Подорож до Тарренського Млина", [2] = "Нам доведеться вдатися до крайніх заходів, щоб позбавити Каміннопазуристі гори від ТзНБ \"Авантюра\". Крайні, але не кровопролитні.\n\nУ одного мого колеги може знайтися саме те, що нам потрібно. Його звуть Лідон, він мешкає в містечку Тарренський Млин у передгір'ї Гіллзбраду, що у далеких землях Лордерону.\n\nЩоб потрапити до Гіллзбраду, вирушай дирижаблем до нашої столиці, Підмістя. Йди на північ до Тірісфальського перелісся, потім на південний захід до Срібнохвою і тоді на південь до Гіллзбраду.\n\nЗнайди Лідона і передай йому цю записку. Там написано, що нам від нього потрібно.", [3] = "Віднесіть записку Зами аптекарю Лідону в Тарренський Млин.", [4] = "Ага, ти {стать:привів:привела} мені нових піддослідних?", [5] = "Записка від Зами? У неї, мабуть, великі проблеми, якщо вона пише в таку далечінь. Подивимося, що вона хоче...\n\nЧудово! Я знаю, що їй треба!", ["en"] = "Journey to Tarren Mill", ["tasks"] = { ["Zamah's Note"] = "записка Зами", ["Zamah's Note (Provided)"] = "записка Зами (видано)" } },
    [1066] = { [1] = "Кров невинних", [2] = "Я створю токсин, який витягне сили з ТзНБ \"Авантюра\", зробить їх слабкими й покірними. Це має вирішити проблеми Орди в Каміннопазуристих горах, так?\n\nАле для створення токсину мені знадобиться кров невинних, а її важко дістати.\n\nНа щастя, Синдикат, група людських розбійників, наймає тіньових магів... а вони збирають кров невинних для своїх власних, нечистих цілей.\n\nТи знайдеш тіньових магів Синдикату у фортеці Дарнгольд на південному сході.", [3] = "Принесіть 5 флаконів крові невинних аптекареві Лідону в Тарренський Млин.", [4] = "Тобі вдалося знайти тіньових магів Синдикату і забрати у них кров?", [5] = "Дуже добре! Сподіваюся, Синдикат не доставив тобі клопоту?\n\nЯк я вже казав, кров невинних дістати нелегко. Нам пощастило, що тіньові маги Синдикату виконали за нас важку роботу.\n\nА тепер почекай, поки я створюю своє зілля...", ["en"] = "Blood of Innocents", ["tasks"] = { ["Vial of Innocent Blood"] = "флакон крові невинних", ["Vial of Innocent Blood (Provided)"] = "флакон крові невинних (видано)" } },
    [1067] = { [1] = "Повернення до Громового Бескиду", [2] = "Ось токсин. Якщо ти застосуєш його проти ТзНБ \"Авантюра\", він повинен дати тобі гарний результат, можливо, навіть заразливий. Маю сказати, це дуже цікаво — бачити, як мою роботу застосовують на практиці!\n\nУтім, спершу віднеси його аптекарці Замі. Вона має розробити ефективний спосіб доставки токсину, щоб його дія була максимальною.", [3] = "Принесіть токсин Лідона аптекарці Замі в Громовий Бескид.", [4] = "Ти {стать:повернувся:повернулась}, {ім'я}. Тобі вдалось отримати допомогу від аптекаря Лідона?", [5] = "Токсин від аптекаря Лідона? Чудово. Якщо я добре знаю Лідона, цей токсин має бути досить ефективним проти ТзНБ \"Авантюра\"...", ["en"] = "Return to Thunder Bluff", ["tasks"] = { ["Lydon's Toxin"] = "токсин Лідона", ["Lydon's Toxin (Provided)"] = "токсин Лідона (видано)" } },
    [1068] = { [1] = "Подрібнювальні машини", [2] = "Існує зв'язок між духовною магією шаманів і природною магією друїдів. Ось чому ми, шамани, можемо чути благання духів Каміннопазуристих гір. Я можу розібрати не все, що вони шепочуть, але одне послання, одне видіння було чітким...\n\nЯ бачила видіння двох людиноподібних машин серед Вітрокосих скель, що на північний захід від Високолісої долини, які рубали дерева з неймовірною швидкістю. Цих металевих тварюк потрібно зупинити!\n\nУ моєму видінні машини були позначені дивними символами:\n\nXT:4 та XT:9.", [3] = "Знищіть подрібнювачі XT:4 та XT:9, після чого поверніться до Сірет Камнелом на кордон Каміннопазуристих гір та Степів.", [4] = "Духи дерев плачуть за своїми загиблими побратимами, {ім'я}. Ти маєш знищити подрібнювачі XT:4 та XT:9, інакше, боюся, Каміннопазуристі гори ніколи не зціляться.", [5] = "Знищення машин XT:4 та XT:9 заспокоїло багатьох духів Каміннопазуристих гір, {ім'я}. Будемо сподіватися, що з їхньою втратою ТзНБ \"Авантюра\" забереться з цих гір.\n\nБо якщо вони цього не зроблять, то я боюся, що лихо, що спіткало ці землі, буде дрібницею в порівнянні з тим, що чекає на нас попереду.", ["en"] = "Shredding Machines", ["tasks"] = { ["XT:4"] = "ХТ:4", ["XT:4 slain"] = "ХТ:4: убито", ["XT:9"] = "ХТ:9", ["XT:9 slain"] = "ХТ:9: убито" } },
    [1086] = { [1] = "Порт для літальних апаратів", [2] = "Токсин готовий. Залишилося лише доставити його. І саме ти, {ім'я}, це зробиш.\n\nУ ТзНБ \"Авантюра\" має бути засіб для доставки повідомлень і легких вантажів між штаб-квартирою і Каміннопазуристими горами. Ймовірно, це невеликий повітряний порт — недостатньо великий для дирижабля, але, можливо, придатний для літальних апаратів. Ти маєш обшукати підконтрольні ТзНБ \"Авантюра\" території Каміннопазуристих гір і знайти цей повітряний порт, якщо він існує. Як знайдеш його — розмісти там токсин.\n\nРозмісти його і швидко тікай.", [3] = "Віднесіть розсіювач токсичного туману до небопорту ТзНБ \"Авантюра\", після чого поверніться до аптекарки Зами.", [4] = "Ти маєш знайти повітряний порт ТзНБ \"Авантюра\", якщо він існує, {ім'я}.", [5] = "Ти {стать:знайшов:знайшла} порт? Молодець, {ім'я}! Я впевнена, що гоблінам сподобається твій подарунок! Будемо сподіватися, що токсин потрапить до їхньої штаб-квартири.\n\nТи добре {стать:послужив:послужила} своєму народу, тож нехай тебе не мучить совість через отруєння ТзНБ \"Авантюра\". Вони заслуговують значно гіршого.\n\nСоюзникам відречених варто навчитися важливої мудрості:\n\nНе цурайся темних шляхів... якщо вони ведуть до перемоги.", ["en"] = "The Flying Machine Airport", ["tasks"] = { ["Place the Toxic Fogger"] = "Розмістіть токсичний фумігатор" } },
    [1087] = { [1] = "Спадщина Кенарія", [2] = "Ти не можеш уявити собі ненависть, яку я відчуваю до цих жалюгідних земель. Такі, як Кенарій і калдорайські друїди, мешкають на цій вершині та використовують свої жалюгідні сили, щоб придушити потік магії, навіть так далеко на південь від їхніх жалюгідних володінь... їхніх улюблених лісів.\n\nЯ так хочу повернутися до Джеденара і насолоджуватися потоком магії, але мій майстер не дозволить мені повернутися, поки робота не буде виконана.\n\nЯ не сумніваюся, що ти ненавидиш нічних ельфів та їхніх союзників так само як і я. Допоможи мені, і ми обоє будемо задоволені.", [3] = "Вбийте 4 синів Кенарія, 4 дочок Кенарія та 4 кенарійських ботаніків для Брейлін Вогнерукої з Сонцескельної криївки.", [4] = "Спрямовувати магію тут — це як черпати воду з колодязя дірявим відром.", [5] = "Я вже відчуваю її... так... силу, таку солодку... її стрімкий потік. Дурні калдорай, що відкидають дари цього світу, не дають магії вільно, співочим потоком, текти по жилах.\n\nЯке ж життя бліде без цього палкого потоку!", ["en"] = "Cenarius' Legacy", ["tasks"] = { ["Cenarion Botanist"] = "кенарійський ботанік", ["Cenarion Botanist slain"] = "кенарійський ботанік: убито", ["Daughter of Cenarius"] = "Дочка Кенарія", ["Daughter of Cenarius (Provided)"] = "Дочка Кенарія (видано)", ["Daughter of Cenarius slain"] = "Дочка Кенарія: убито", ["Son of Cenarius"] = "Син Кенарія", ["Son of Cenarius (Provided)"] = "Син Кенарія (видано)", ["Son of Cenarius slain"] = "Син Кенарія: убито" } },
    [1088] = { [1] = "Ордан", [2] = "Вони думали, що зможуть зупинити потік магії. Але вони помилялися. Вони думали, що зможуть сховати Ордана, але я дістану його голову!\n\nМагія дарує мені можливість бачити істину. Так... ось він. Перехрестя... На верхівці великого дерева в лісі Ясенеділ. Ім'я... прихисток Незайманого лісу. Один зі старших синів бога лісу. Вони забрали його з цієї вершини швидше, ніж я змогла знайти його, але його час спливає.\n\nПринеси мені його голову і я поділюся з тобою могутністю.", [3] = "Принесіть голову Ордана до Брейлін Вогнерукої в Сонцескельну криївку.", [4] = "Коли мій господар відправив мене в Каміннопазуристі гори, я думала, що потрібно лише знищити нічних ельфів, які повзають по священних руїнах нашого древнього храму Азшари, оскверняючи святість цього місця... але Ордан вислизнув від мене.", [5] = "Колись, дуже давно, я знала Ордана. Він був гордим, як і всі його родичі й навіть вважав себе вищим за високородних.\n\nТепер він не може підняти голову так високо, чи не так, {ім'я}?\n\nЯ пообіцяла тобі нагороду і ти її отримаєш. Слухай мене.", ["en"] = "Ordanus", ["tasks"] = { ["Ordanus' Head"] = "голова Ордана", ["Ordanus' Head (Provided)"] = "голова Ордана (видано)" } },
    [1089] = { [1] = "Лігво", [2] = "На Каміннопазуристому піку друїди побудували лігво Кігтя, в ньому вони зберігають багато потужних предметів.\n\nВони розробили складну схему, аби ці предмети не потрапили в чужі руки.\n\nНа щастя, мені вдалося... витягти деякі подробиці з одного з них.\n\nУ маленькому ліхтарику біля входу в Лігво ти знайдеш ключ хранителя воріт — за допомогою нього ти зможеш відкрити схованки навколо Лігва. Предмети з цих схованок дозволять тобі відкрити їхню скарбницю, розташовану в одному з центральних приміщень.", [3] = "Відправляйтеся до Лігва на Каміннопазуристий пік. Використовуючи ключ хранителя воріт, відшукайте заховані предмети друїдів. Використайте ці предмети, щоб відкрити скарбницю лігва Кігтя.", [4] = "В камені вирізані три отвори для ключів.", [5] = "Коли три ключі входять у відповідні отвори, в центрі мерехтливого сяйва з'являться кілька предметів.", ["en"] = "The Den", ["tasks"] = { ["Barrow Key"] = "ключ прихистку", ["Barrow Key (Provided)"] = "ключ прихистку (видано)", ["Claw Key"] = "ключ пазура", ["Claw Key (Provided)"] = "ключ пазура (видано)", ["Sleepers' Key"] = "ключ сплячих", ["Sleepers' Key (Provided)"] = "ключ сплячих (видано)" } },
    [1098] = { [1] = "Смертолови у фортеці Тіньового Ікла", [2] = "В підготовці до штурму фортеці Тіньового Ікла, два смертолова були послані зібрати розвіддані. Минуло вже багато днів, а вони ще досі не повернулися, але ми повинні отримати їхній звіт, щоб мати хоч якусь надію на успішну атаку!\n\nТож ось твоє завдання, {Ім'я}. Вирушай до фортеці Тіньового Ікла, що на південь звідси, та знайди смертоловів Адаманта та Вінсента. Знайди їх, можливо, їм потрібна допомога.\n\nЦе завдання дуже важливе й небезпечне, {Ім'я}. Не підведи.", [3] = "Знайдіть смертоловів Адаманта і Вінсента.", [5] = "Тіло Вінсента лежить розтрощене і нерухоме.\n\nХоча смертолов Адамант і надішле звіт Гадреку... будь-які дані, зібрані Вінсентом, залишаться з ним.\n\nАле його рука стискає маленьку дрібничку...", ["en"] = "Deathstalkers in Shadowfang" },
    [1102] = { [1] = "Мстива доля", [2] = "Керн — благородний лідер, що об'єднав наш народ в Громовому Бескиді.\n\nТа я не можу пробачити тих, хто вигнав нас з земель наших предків. Ми жили в південних Степах багато років. Це були наші священні землі. Та нас вигнали наші вороги.\n\nВелика помста чекає на відьму, Чарлґу Бритвобоку, що збирає нечестиве вояцтво в краалі Бритвоболотих.\n\nПринеси мені серце Бритвобокої, {ім'я}. Це принесе мені спокій.", [3] = "Принесіть серце Бритвобокої Ольду Кам'яному Шпилю в Громовий Бескид.", [4] = "Щойно з потворами крааля Бритвоболотих буде покінчено, я зможу спочивати з миром.\n\nТи вже {стать:був:була} в краалі? Я чекаю на серце Бритвобокої.", [5] = "Бачу, кляті свинобрази з крааля Бритвоболотих тепер відчують на собі страждання мого народу. Як їм і належить.\n\nВигнання цілого народу з їх священної землі — злочин, гідний суворої кари.\n\nДякую, що не {стать:залишив:залишив} мене з моєю бідою, {ім'я}.", ["en"] = "A Vengeful Fate", ["tasks"] = { ["Razorflank's Heart"] = "серце Бритвобокої", ["Razorflank's Heart (Provided)"] = "серце Бритвобокої (видано)" } },
    [1109] = { [1] = "Не все те золото...", [2] = "Як ти можеш бачити, {ім'я}, ми в королівському товаристві аптекарів проводимо... цікаві досліди.\n\nМоя робота як майстра-аптекара — спостерігати за найперспективнішими алхімічними проєктами. Роботи в мене купа, а часу обмаль.\n\nСхоже, тобі не звикати до подорожей, {клас:к}. Допоможеш?\n\nМені потрібен один рідкісний і неприємний інгредієнт. Його можна дістати у кажанів, що водяться в дірі, що називається краалем Бритвоболотих. Принеси мені гуано краальських кажанів і ми розпочнемо роботу...", [3] = "Принесіть купу гуано краальського кажана майстру-аптекару Фаранеллу в Підмістя.", [4] = "Бачу, ти вже {стать:повернувся:повернулась}. Вдалось дістати гуано краальських кажанів?", [5] = "Це те, що треба! Тепер ми можемо починати, {ім'я}.", ["en"] = "Going, Going, Guano!", ["tasks"] = { ["Kraul Guano"] = "гуано краальського кажана", ["Kraul Guano (Provided)"] = "гуано краальського кажана (видано)" } },
    [1123] = { [1] = "Рабін Сатурна", [2] = "Для виконання цього завдання мажордом хранителя Ремула в Місячній поляні — Рабін Сатурна — шукає допомоги в дослідженні величезної пустелі далеко на захід від Танаріса, за Ун'Горо. Ти знайдеш його в Нічній Гавані, головному селищі Місячної галявини.\n\nЯ хочу, щоб ти {стать:розумів:розуміла} всю важливість твоєї присутності там. Стосунки між нічними ельфами Дарнасу і Кенарійським Колом Місячної галявини напружені. Будь вище расових відмінностей і скористайся мудрістю предків у спілкування з Колом, {ім'я}. Щасти тобі.", [3] = "Поговоріть з Рабіном Сатурною в селищі Нічна Гавань на Місячній галявині. Місячна галявина знаходиться між Скверноліссям та Зимоключем, шлях до неї проходить через оплот Деревопузих.", [5] = "Я Рабін Сатурна, і від імені хранителя Ремула та всіх мешканців цієї священної галявини я вітаю тебе.\n\nЯ ціную твою зацікавленість і прагнення допомогти Кенарійському Колу. Таурени виявили неймовірну прихильність принципам Кенарія, і завдяки їм Орду вітають на цій галявині. Адже збереження Азероту — наша спільна мета.\n\nТут ти серед друзів, {ім'я}.", ["en"] = "Rabine Saturna" },
    [1130] = { [1] = "Звістка від Мелора", [2] = "{ім'я}, Мелор Кам'яне Копито дізнався про твої подвиги і намітив для тебе шлях.\n\nЯкщо ти хочеш пройти його — вирушай до Громового Бескиду і поговори з Мелором. Ти знайдеш його на Верхів'ї Мисливців.", [3] = "Поговоріть з Мелором Кам'яним Копитом у Громовому Бескиді.", [5] = "Отже, ти {стать:прийшов:прийшла}, {ім'я}. Чи {стать:готовий:готова} ти до подорожі далекими землями?\n\nЯкщо так, {стать:юний:юна} {клас:к}, то слухай...", ["en"] = "Melor Sends Word" },
    [1131] = { [1] = "Сталекус", [2] = "Іноді ми полюємо заради їжі. Іноді — заради честі. А іноді ми полюємо, щоб засвоїти вчення Матері-Землі.\n\nАле полювання, яке чекає на тебе, не має з цими речами нічого спільного. Ти маєш вбити істоту, яка не має благословення Матері-Землі.\n\nГієна на прізвисько Сталекус блукає Тисячею Шипів, що на південь від Степів. До нього прибиваються інші гієни і разом вони сіють страх серед інших, більш мирних звірів.\n\nЗнайди Сталекуса, {ім'я}. Знайди його і вбий.", [3] = "Принесіть ребро Сталекуса Мелору Кам'яному Копиту в Громовий Бескид.", [4] = "Тобі вдалося здолати Сталекуса, {ім'я}?", [5] = "Перемігши Сталекуса, ти {стать:очистив:очистила} Тисячу Шипів від жахливої напасті.\n\nІ це, {ім'я}, твій сьогоднішній урок.", ["en"] = "Steelsnap", ["tasks"] = { ["Steelsnap's Rib"] = "ребро Сталекуса", ["Steelsnap's Rib (Provided)"] = "ребро Сталекуса (видано)" } },
    [1136] = { [1] = "Кригопаща", [2] = "{Ім'я}, настав час для твоєї подорожі в далекі краї. Ти {стать:готовий:готова}.\n\nТепер ти полюватимеш на Кригопащу, єті з Альтерацьких гір. Він невловний, його біла шкура зливається зі снігами його гірського житла. Його рідко можна побачити.\n\nАле я покажу тобі, як приманити таку істоту, як цей єті. Ось, візьми цей сувій. На ньому я написав, як можна приманити Кригопащу.\n\nА тепер йди, {ім'я}. Шлях неблизький і на тебе чекає багато випробувань. Повертайся з гривою Кригопащі.", [3] = "Принесіть гриву Кригопащі Мелору Кам'яному Копиту в Громовий Бескид.", [4] = "Ти вже {стать:бував:бувала} в Альтерацьких горах, {ім'я}? Чи зустрічався тобі Кригопаща?", [5] = "Щоб знайти і вбити Кригопащу, {ім'я}, потрібні і сила, і хитрість. У тебе є обидві ці якості.\n\nТвій шлях привів тебе в долини Тисячі Шипів і у високі гори Альтераку. Одного дня він проведе тебе через усі краї Матері-Землі, бо такий шлях мисливця.", ["en"] = "Frostmaw", ["tasks"] = { ["Frostmaw's Mane"] = "грива Кригопащі", ["Frostmaw's Mane (Provided)"] = "грива Кригопащі (видано)" } },
    [1145] = { [1] = "Рій росте", [2] = "Багато мандрівників, які приходили в Перехрестя, допомагали мені збирати яйця з Поля Велетнів, а потім розповідали, які смертоносні істоти там живуть. Я почув достатньо, щоб вважати цих комах набагато більшою загрозою, ніж думали мої господарі.\n\nМені потрібен кур'єр, що відправиться до Орґріммару на зустріч з Белґромом Скелебоєм. Це буде нелегка справа, яку можна доручити тільки тому, хто поставиться до завдання серйозно.\n\nЗазвичай Белґрома можна знайти біля цехового будинку воїнів.", [3] = "Доставте запечатану записку Коррана Белґрому Скелебою в Орґріммар.", [4] = "Я заздрю тобі, {клас:к}. Схоже, ти {стать:мав:мала} вдосталь пригод за межами стін Орґріммара.\n\nЯ б і сам вирушив у подорож на славу воєвождя, якби Тралл не потребував моєї роботи тут, у місті. Але він мудрий правитель, і я залишуся тут доти, доки буду йому потрібен.", [5] = "А, записка від Коррана. Він вже давно служить Орді з усією відданістю. Я саме збирався дізнатися, як у нього справи в Перехресті.", ["en"] = "The Swarm Grows", ["tasks"] = { ["Korran's Sealed Note"] = "запечатана записка Коррана", ["Korran's Sealed Note (Provided)"] = "запечатана записка Коррана (видано)" } },
    [1146] = { [1] = "Рій росте", [2] = "Отже, Корран дійшов схожого висновку щодо цих комах — схоже, що вони становлять набагато більшу загрозу, ніж ми думали.\n\nКілька днів тому з Тисячі Шипів повернувся ледь живий мисливець. Його із загоном відправили на Мерехтливі рівнини, щоб вигнати звідти групу дворфів, які проводили розкопки. Але під час бою з печери на місці розкопок вирвалося ще більше цих комах і ледь не вбили весь загін.\n\nЇх очолював Моктар Крін, і зараз вони стали табором на кордоні Мерехтливих рівнин. Передай йому цю записку.", [3] = "Передайте запечатану записку Белґрома Моктару Кріну в Тисячу Шипів.", [4] = "Мене і мій загін привела на Мерехтливі рівнини війна, {клас:к}. А що привело сюди тебе?", [5] = "Не звертай уваги на відлуння гуркоту, що лунає серед гір. Гобліни та гноми влаштовують перегони по рівнинах, змагаючись один з одним на кошмарних машинах, породжених тим, що вони називають \"наукою\". Тут, у Тисячі Шипів, є більші загрози, одна з яких нещодавно вбила більшу частину мого загону.\n\nАле ми залишимося тут, доки не отримаємо звістку від Белґрома з Орґріммару. До тих пір ми утримуватимемо наші позиції та стоятимемо на сторожі.", ["en"] = "The Swarm Grows", ["tasks"] = { ["Belgrom's Sealed Note"] = "запечатана записка Белґрома", ["Belgrom's Sealed Note (Provided)"] = "запечатана записка Белґрома (видано)" } },
    [1147] = { [1] = "Рій росте", [2] = "Гм. Схоже, Белґром вважає цих монстрів загрозою та хоче, щоб їх загнали в глибини, з яких вони вилізли.\n\nЯ так розумію, що вбивства дворфів з Ліги дослідників було йому недостатньо. Тепер я маю відправити напівмертвий загін у ще один бій. Ми не впораємося самотужки, принаймні не в такому стані. Розкопки знаходяться на південь звідси. Там більше не має бути дворфів. Хочеш допомогти нам своїм мечем чи посохом?", [3] = "Вбийте 5 силітидів-шукачів, 5 силітидів-трутнів та 5 силітидів-загарбників та поверніться до Моктара Кріна в Тисячу Шипів.", [4] = "Зважаючи на кількість мандрівників, які приїхали на рівнини, щоб подивитися перегони, я впевнений, що ми знайдемо шукачів пригод, що допоможуть нам відбитися від цих комах. А доти мій загін не зможе покинути цей пост.", [5] = "Ха! Ця лімфа, якою ти {стать:покритий:покрита}, пасує тобі, {ім'я}! Хоча смердиш ти так, що аж очі ріже. Не підходь надто близько до кодо — вони або втечуть, або накинуться на тебе.\n\nГадаю, мої товариші погодяться, що твій запах сам по собі є доказом того, що ти {стать:зробив:зробила} свій внесок у боротьбу з цими комахами. Дякую, {ім'я}.", ["en"] = "The Swarm Grows", ["tasks"] = { ["Silithid Hive Drone"] = "силітид-трутень", ["Silithid Hive Drone slain"] = "силітид-трутень: убито", ["Silithid Invader"] = "силітид-загарбник", ["Silithid Invader slain"] = "силітид-загарбник: убито", ["Silithid Searcher"] = "силітид-шукач", ["Silithid Searcher slain"] = "силітид-шукач: убито" } },
    [1149] = { [1] = "Випробовування віри", [2] = "Що ж, ти {стать:знайшов:знайшла} мене, чи, можливо, тебе привела до мене доля? Неважливо. Тепер ти тут, і перед тобою лежить новий шлях.\n\nОсобистість складається з багатьох граней: душі, тіла і розуму. Деякі з цих аспектів визначаються культурними традиціями, про наявність інших ми можемо тільки здогадуватися. Якщо ти погодишся, я випробую деякі з цих граней у тобі.\n\nЯкщо пройдеш випробування — станеш сильніше. Якщо ж провалиш — пізнаєш всю безодню Підсвіття.\n\nПерше випробування — це випробування віри.", [3] = "Якщо у вас є віра, стрибніть з дощок над Тисячею Шипів.", [4] = "Віра. Вона є набагато важливішою, ніж дехто може собі уявити.\n\nНеважливо у що ти віриш. Головне — вірити у щось.", [5] = "Лише тоді, коли ми постаємо перед непередбачуваними труднощами, ми починаємо усвідомлювати, наскільки сильний наш дух. Ти {стать:повірив:повірила} у себе, навіть не маючи гарантій того, що ти виживеш. Твій розум відкритий, твій дух готовий до того, що чекає попереду.\n\nЯкщо бажаєш, можеш приступити до наступного випробування.", ["en"] = "Test of Faith", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість" } },
    [1150] = { [1] = "Випробовування витривалості", [2] = "Я радий бачити, що твоя мужність залишається непохитною, незважаючи ні на що. Твоя віра стійка, прийшов час випробувати твоє тіло.\n\nПершим буде випробування на витривалість. Вирушай з друзями у лігво Оперених пройдисвіток на захід від застави Розкутого Вітру. Проберися в саме серце лігва та знищ їхні запаси їжі. Це має розлютити тамтешніх гарпій, і якщо ти виживеш, сама Ґренка Крововиск прийде за тобою. Вбий її та принеси мені її кіготь, щоб пройти це випробування.", [3] = "Принесіть кіготь Ґренки Дорну Рівнинному Ловцю в Тисячу Шипів.", [4] = "Ти маєш бути {стать:готовим:готовою} духовно, фізично та ментально для завдання, що чекає на тебе.\n\nДуже часто ми мчимо вперед непідготовленими. Я вважаю своїм обов'язком підготувати всіх новачків, які приходять до мене, незалежно від їхнього походження. Вони мають знати, з чим їм доведеться зіткнутися за порогом рідного дому.", [5] = "Ґренка була дуже сильною, навіть для {стать:такого:такої} {раса:р}, як ти. Ти маєш пишатися своїм сьогоднішнім досягненням.\n\nПід час твого випробування віри, ти {стать:продемонстрував:продемонструвала} силу духу, а зараз ти {стать:показав:показала} свою витривалість, зустрівшись в бою з опереними пройдисвітками. Та настав час для нового випробування.", ["en"] = "Test of Endurance", ["tasks"] = { ["Grenka's Claw"] = "кіготь Ґренки", ["Grenka's Claw (Provided)"] = "кіготь Ґренки (видано)" } },
    [1151] = { [1] = "Випробовування сили", [2] = "За часів Старих Богів, елементалі населяли більшу частину світу. Вони поклонялися Старим Богам і таким чином, Боги, завдяки своїй силі, прив'язали елементалів до цього світу. Коли ж Старих Богів вигнали, елементалі теж покинули цей світ і тепер з'являються лише за покликом могутніх магів.\n\nАле є й винятки. Деякі елементалі настільки сильні, що можуть залишатися в цьому світі. Один з таких елементалів — Рок'Алім.\n\nЩоб випробувати свою силу, знайди Рок'Аліма в Тисячі Шипів та вбий його.", [3] = "Принесіть фрагменти Рок'аліма Дорну Рівнинному Ловцю в Тисячу Шипів.", [4] = "Племена кентаврів називають Рок'Аліма Руйнівником через гуркіт його кулаків, якими він лупцює тих, хто досить сміливий або дурний для того, щоб опинитися на його шляху.", [5] = "Випробовування сили завершено. Ти {стать:продемонстрував:продемонструвала} свою силу та хоробрість, і тепер {стать:готовий:готова} до наступного та останнього випробовування після якого твоя посвята завершиться.", ["en"] = "Test of Strength", ["tasks"] = { ["Fragments of Rok'Alim"] = "фрагменти Рок'аліма", ["Fragments of Rok'Alim (Provided)"] = "фрагменти Рок'аліма (видано)" } },
    [1152] = { [1] = "Випробування знань", [2] = "Твій час зі мною добігає кінця. Я знаю багато, але не можу проводити випробовування знань. Є іще багато уроків, які тобі варто засвоїти та місць, які треба відвідати.\n\nЯкщо ти {стать:готовий:готова}, знайди Брауґа Тьмяного Духа. Він дуже мудрий шаман. Він буде випробовувати тебе далі, тож прислуховуйся до його слів, {ім'я}.\n\nЯк будеш {стать:готовий:готова}, знайди тунель, що з'єднує Каміннопазуристі гори з Ясенедолом. Брауґ мешкає там. Будь {стать:обережним:обережною}, {ім'я}, нічні ельфи можуть завадити твоєму випробовуванню.", [3] = "Знайдіть Брауґа Тьмяного Духа поруч з входом до Пазуродертого тунеля в Каміннопазуристих горах.", [5] = "Дні та ночі холоднішають по всьому світу, гобліни роздирають землю, а нічні ельфи принижують молодші раси. Не тільки відречені та орки винні у негараздах, що спіткали Калімдор та Лордерон. Багато розумних рас заподіяли світу чимало болю. Дорн знає це, і він прислав тебе до мене, бо ти {стать:показав:показала}, що також це усвідомлюєш.\n\nІ тепер ти стоїш перед Брауґом.", ["en"] = "Test of Lore" },
    [1153] = { [1] = "Зразок нової руди", [2] = "{Клас:к}, ти добряче мені {стать:допоміг:допомогла} минулого разу. Наразі воєвождь задоволений моїми досягненнями та наказує продовжувати з новою рішучістю. Моя честь вимагає, щоб я по-справжньому відзначив тебе перед воєвождем за весь твій вклад, але спершу я знову попрошу тебе про допомогу.\n\nНещодавно сюди прибули мандрівники з півдня - місцевості, під назвою Тисяча Шипів. Там вони вбили кобольда, у якого був зразок незвичайної руди, але вони не захотіли мені його продати. А я конче хочу дослідити такий зразок.", [3] = "Знайдіть неочищений зразок руди у жорствопикого копача або землеміра і віддайте його Таттернаку Сталевару в табір Таурахо, що в Степах.", [4] = "Я знову побачив тих мандрівників - які не продали мені зразок руди. Плював я на них з високої гірки за те, що вони відмовилися допомогти воєвождю!\n\nНехай вони загинуть в бою як боягузи, а не як воїни, бо таке право мають лише ті, хто стали союзниками Орди.", [5] = "Ладний зразок, {Ім'я}. Справді, хороший зразок.\n\nНехай вам повилазить, мандрівники! Тепер і в мене є руда, завдяки тобі, звісно ж.\n\nЯ негайно стану до роботи. Якщо метал виявиться достатньо міцним, то я зроблю зброю і надішлю її до воєвождя, щоб показати йому наш успіх.\n\nЯ не забуду твоєї допомоги, {клас:к}.", ["en"] = "A New Ore Sample", ["tasks"] = { ["Unrefined Ore Sample"] = "неочищений зразок руди", ["Unrefined Ore Sample (Provided)"] = "неочищений зразок руди (видано)" } },
    [1154] = { [1] = "Випробування знань", [2] = "Ти {стать:пройшов:пройшла} випробовування Дорна, а тепер прагнеш пройти наступне? Дуже добре. Але всі твої попередні випробування були лише забавою для малюків. Випробовувати своє тіло легко, а от розум — це зовсім інша річ.\n\nЯ поясню простіше: знайди книгу, яку я назву, вивчи її та дай відповідь на мої питання, що стосуються цієї книги.\n\n\"Що за книга?\" - ти запитаєш. \"Спадщина Аспектів\". Вона знаходиться на дні Дор'Даніла, що на півдні Ясенедолу, і охороняється мертвими друїдами та їхніми ж вбивцями.", [3] = "Знайдіть книгу \"Спадщина Аспектів\" та принесіть її Брауґу Тьмяному Духу, що знаходиться біля входу до Пазуродертого тунелю в Каміннопазуристих горах.", [4] = "Принеси мені книгу після того, як ти вивчиш її. Я не буду ставити тобі запитання, поки ти не віддаси мені книгу.", [5] = "Це саме та книга, про яку я казав. Що ж, є надія, що ти відповіси на мої питання правильно... якщо ти не {стать:забув:забула} вивчити її зміст.\n\nКоли будеш {стать:готовий:готова} — поговори зі мною, і я поставлю тобі запитання.", ["en"] = "Test of Lore", ["tasks"] = { ["Legacy of the Aspects"] = "Спадщина Аспектів", ["Legacy of the Aspects (Provided)"] = "Спадщина Аспектів (видано)" } },
    [1159] = { [1] = "Випробування знань", [2] = "Молодець, {ім'я}. Ти {стать:пройшов:пройшла} першу стадію випробування знань, але є іще одне питання, на яке ти маєш дати відповідь. Щоправда, ставити його буду не я.\n\nВідшукай Парквела Фінталласа в Лордероні. Він був великим істориком до того, як став жертвою Чуми. Він продовжує шукати просвітлення, але в іншій природі.\n\nУ нього буде доручення для тебе перед тим, як він поставить тобі питання, але ти {стать:впорався:впоралася} прекрасно минулого разу, тож я впевнений, що труднощів у тебе не виникне.", [3] = "Знайдіть Парквела Фінталласа в Підмісті.", [5] = "Тебе прислав Брауґ? Неможливо.\n\n<Парквел оглядає вас.>\n\n{стать:Відзначився:Відзначилася} в Дор'Данілі, {стать:зробив:зробила} стрибок віри і {стать:впорався:впоралася} з могутнім елементалем? Тьху! Ти явно {стать:якийсь самозванець:якась самозванка}, {стать:який наслухався:яка наслухалася} казочок у таверні. І ти думаєш, що зможеш пройти моє випробування? Ну що ж, добре... {клас:к}.", ["en"] = "Test of Lore" },
    [1164] = { [1] = "Крадіжка у злодіїв", [2] = "Шльондра! Свинюка! Кената досі жива, її сім'я ціла та процвітає, поки я страждаю. Справді, відречена!\n\nМоя сім'я загинула - її забрала чума. Зникла і наша домівка, спалена та розграбована під час війни. І після всіх цих жахіть вона та її виродки мали нахабство викрасти єдині цінності, які в мене залишилися.\n\nМене більше не цікавлять речі, які вони вкрали. Тепер мені потрібні їхні голови!\n\nУбий їх для мене! Йди до хутора Дабірі в Араті, на північний схід від Опорного пункту.", [3] = "Принесіть Женаві Болотянці в Підмістя голови Кенати, Фардела та Марселя Дабірі.", [4] = "Убий їх усіх і принеси мені їхні голови!", [5] = "Ти стоїш переді мною, як образ помсти, і я кланяюся тобі у своїй вдячності.\n\nЗі смертю цієї корови та знаючи, що її поріддя більше не розмножуватиметься на поверхні Азерот, я можу скерувати свою енергію на щось корисніше. Сподіваюся, ти {стать:вигріб:вигребла} їхній хутір після того, як їх {стать:прикінчив:прикінчила}.", ["en"] = "To Steal From Thieves", ["tasks"] = { ["Fardel's Head"] = "голова Фардела", ["Fardel's Head (Provided)"] = "голова Фардела (видано)", ["Kenata's Head"] = "голова Кенати", ["Kenata's Head (Provided)"] = "голова Кенати (видано)", ["Marcel's Head"] = "голова Марселя", ["Marcel's Head (Provided)"] = "голова Марселя (видано)" } },
    [1166] = { [1] = "Занепокоєння властителя Мок'Морокка", [2] = "Поклонись перед властитель Мок'Морокк!\n\nРексар зробив мене могутнім лідером клану Каменедовбня!\n\nЯ добрий лідер. Я охороняти клан від небезпек.\n\nВеликі дракони прилетіти та спалити наш старий дім. Я розумний огр. Я знайшов нову оселю для клану тут.\n\nАле ми покинути свої оселі так швидко, що я забув свої речі. {стать:Маленький:Маленька} {клас} знайде мої речі. Піди на південь і знайди мій смачний грог, мій тютюн і мій сейф. Як знайдеш їх, я буду дуже вдячний. Шукай у лігві Полум'я та руїнах Каменедовбні... Вони там, це точно!", [3] = "Властитель Мок'Морокк з селища Папорохащі хоче, щоб ви знайшли його грог, тютюн і сейф в Бруднолипкій трясовині.", [4] = "Я хочу грог. І тютюн теж хочу. Де сейф? Ти знайти їх для властитель Мок'Морокк.\n\nШукати на півдні, у старому домі. Я дуже зайнятий, керую ограми.", [5] = "Ти {стать:хороший:хороша} {раса}. Я дуже за цим сумував. Тепер ти мені подобатись.", ["en"] = "Overlord Mok'Morokk's Concern", ["tasks"] = { ["Mok'Morokk's Grog"] = "грог Мок'Морокка", ["Mok'Morokk's Grog (Provided)"] = "грог Мок'Морокка (видано)", ["Mok'Morokk's Snuff"] = "тютюн Мок'Морокка", ["Mok'Morokk's Snuff (Provided)"] = "тютюн Мок'Морокка (видано)", ["Mok'Morokk's Strongbox"] = "сейф Мок'Морокка", ["Mok'Morokk's Strongbox (Provided)"] = "сейф Мок'Морокка (видано)" } },
    [1168] = { [1] = "Армія чорного дракона", [2] = "Мок'Морокк став властителем завдяки Рексару. Він більше цікавиться владою, ніж ограми.\n\nЧорні дракони вбили багатьох огрів. Вони вбили дружину Тарґа. Мок'Морокк велів нам тікати.\n\nОгри повинні боротися. Огри не дуже вміють тікати. Мок'Морокк турбується тільки про себе.\n\nЯ мешкав в руїнах Каменедовбні на півдні. Мені там подобалось. Це місце — не мій дім.\n\nДопоможи ограм в битві проти армії чорних драконів. Я хочу помститися і повернутися додому.", [3] = "Тарґ з селища Папорохащі хоче, щоб ви вбили 15 вогнегривих розвідників, 10 вогнегривих попелехвостів і 5 вогнегривих лускоклятів.", [4] = "Мок'Морокк наказав усім ограм залишитися та охороняти це місце. Я вважаю, що огри повинні вбити армію чорного дракона і повернути собі дім.\n\nТи допоможеш ограм повернутися додому. Допоможи ограм помститися.", [5] = "Ти {стать:вбив:вбила} багатьох з армії чорних драконів. Ти {стать:хоробрий:хоробра} {раса}.\n\n{стать:Зробив:Зробила} Тарґа щасливим.", ["en"] = "Army of the Black Dragon", ["tasks"] = { ["Firemane Ash Tail"] = "вогнегрива попелехвостка", ["Firemane Ash Tail slain"] = "вогнегрива попелехвостка: убито", ["Firemane Scalebane"] = "вогнегривий лускоклят", ["Firemane Scalebane slain"] = "вогнегривий лускоклят: убито", ["Firemane Scout"] = "вогнегривий розвідник", ["Firemane Scout slain"] = "вогнегривий розвідник: убито" } },
    [1169] = { [1] = "Корінь зла", [2] = "Поки боягуз Мок'Морокк насолоджується владою, а Тарґ бореться з тугою і бажанням помсти та змагається за лідерство в клані, здається, що тільки я — єдиний, хто хоче встановити причину лиха, що звалилося на наш старий дім.\n\nЧому ти дивуєшся, {ім'я}? {стать:Чекав:Чекала}, що я буду говорити, наче неотесаний грубіян тільки через те, я — огр?\n\nАле ж до справи. Принеси мені серця та язики дракончиків, які щойно вилупились. Я відшукаю корінь цього зла...", [3] = "Драз'Зільб з селища Папорохащі просить вас принести йому 15 палючих язиків та 15 палючих сердець.", [4] = "За допомогою палючих сердець та язиків дитинчат чорних драконів я можу визначити, яке створіння напустило своїх нащадків на наш дім. Можливо, з більшим розумінням наших ворогів, ми зможемо раз і назавжди знищити їх та підняти Каменедовбню з руїн.\n\nЗвісно, змусити Мок'Морокка відірвати свій ледачий товстий зад від землі — вже саме по собі важке завдання...", [5] = "Без сумнівів, збір сердець та язиків був небезпечною справою. Тепер я проникну в глибини таємниць, та з'ясую, звідки в наш колишній дім прийшла ця чорна загроза.", ["en"] = "Identifying the Brood", ["tasks"] = { ["Searing Heart"] = "палюче серце", ["Searing Heart (Provided)"] = "палюче серце (видано)", ["Searing Tongue"] = "палючий язик", ["Searing Tongue (Provided)"] = "палючий язик (видано)" } },
    [1170] = { [1] = "Виводок Оніксії", [2] = "Селище Каменедовбня було захоплено виводком Оніксії. Але чому дочка чорного володаря драконів, Смертекрила, спустилася на наші землі?\n\nЦе дуже тривожно. Безумовно, Оніксія була тут не лише для того, щоб атакувати невелику групу огрів.\n\nПовідом Мок'Морокка негайно! Треба діяти.", [3] = "Поговоріть з властителем Мок'Морокком в селищі Папорохащі.", [5] = "Навіщо ти розповідати мені про дракони? Мені не подобаються дракони. Мені подобається тут. Ніяких драконів тут.", ["en"] = "The Brood of Onyxia" },
    [1171] = { [1] = "Виводок Оніксії", [2] = "Дай мені спокій. Іди скажи Драз'Зільб, ми залишатись тут. Ніяких чорних драконів тут.", [3] = "Поговоріть з Драз'Зільбом в селищі Папорохащі.", [5] = "Лінивий боягуз!\n\nМок'Морокк показав силу, коли Рексар був нашим лідером. Але незабаром після від'їзду Рексара Мок'Морокк почав прагнути влади. Замість того, щоб керувати, він вимагає. Він не служить своєму народові, а очікує, що ми будемо йому служити.\n\nТреба щось робити.", ["en"] = "The Brood of Onyxia" },
    [1172] = { [1] = "Виводок Оніксії", [2] = "Виводок Оніксії розповзся по всьому Драконохмуру. Не можна допустити, щоб решта її дитинчат вилупились.\n\nПоспіши до Змієдолу на південному заході Бруднолипкої трясовини. Напевно, вона зробила там своє гніздо. Знайди яйця злої драконихи та знищ їх!\n\nМи ніколи не зможемо повернути селище Каменедовбню, якщо навколо нього плодитимуться дракони.\n\nЩодо Мок'Морокка... У мене на нього інші плани.", [3] = "Драз'Зільб з селища Папорохащі хоче, щоб ви знищили 5 яєць Оніксії.", [4] = "Ти маєш поспішати до Драконохмура, {ім'я}. Поки яйця Оніксії розкидані по Змієдолу, вони завжди переважатимуть нас числом.\n\nЗнищ її яйця! Не дай заразі чорних драконів розповзатися нашими землями!", [5] = "Чудово! Мине деякий час, перш ніж Оніксія зможе відкласти нові яйця.\n\nВід імені мого народу я дякую тобі, {ім'я}.\n\nЯ вже багато про що просив тебе, але, може, ти зробиш останню послугу для клану Каменедовбнів.\n\nМок'Морокк не гідний нас очолювати. Тарґ був би чудовим лідером, але йому заважають травми та вік. Вижени Мок'Морокка звідси силою. Тільки тоді ми зможемо обрати нового лідера, щоб повернутися до нашого істинного дому на півдні.", ["en"] = "The Brood of Onyxia", ["tasks"] = { ["Egg of Onyxia destroyed"] = "Яйце Оніксії знищено" } },
    [1173] = { [1] = "Виклик властителю Мок'Морокку", [2] = "Ти кидати виклик властитель Мок'Морокк?\n\nХа!\n\nЯ розчавити {стать:дрібний:дрібна} {раса}!\n\nСкажи, коли {стать:готовий:готова} до биття.", [3] = "Переможіть Мок'Морокка та повідомте про це Драз'Зільба в селищі Папорохащі.", [4] = "Я думав, що ти збираєшся вигнати Мок'Морокка з селища. Але замість цього ти {стать:прийшов:прийшла} до мене, щоб побазікати?", [5] = "Ця боягузлива туша, Мок'Морокк, втік як перелякане дитя. Ти {стать:зробив:зробила} нам величезну послугу, {ім'я}.\n\nТепер наш народ може вибрати собі нового лідера, який допоможе нам відновити наш старий дім.", ["en"] = "Challenge Overlord Mok'Morokk", ["tasks"] = { ["Drive Overlord Mok'Morokk from Brackenwall Village"] = "Виженіть Повелителя Мок'Морокка з села Брекенволл" } },
    [1184] = { [1] = "Частини рою", [2] = "Повертайся до Белґрома в Оргріммар та скажи йому, що Моктар зробить усе, що від нього вимагається в Тисячі Шипів. Також скажи йому, що я роблю прогрес у дослідженнях, і сподіваюся скоро дізнатися ще більше. Він буде радий це почути.", [3] = "Поверніться до Белґрома Скелебоя в Орґріммар.", [5] = "Я вдячний тобі за твої зусилля, {клас:к}. Воєвождь із задоволенням послухає, {стать:яким наполегливим:якою наполегливою} ти {стать:був:була}, виконуючи свої обов'язки.\n\nО, і звичайно, я зазначу йому твоє ім'я. Він часто зі мною розмовляє та дуже цінує мою думку.\n\nА тепер іди, у мене ще багато справ. Якщо будеш говорити з Корраном, і у нього будуть новини про цих створінь — повертайся до мене. Я думаю, що до цих створінь не варто ставитися легковажно.", ["en"] = "Parts of the Swarm" },
    [1195] = { [1] = "Священне полум'я", [2] = "Кентаври племені Ґалак у Тисячі Шипів охороняють артефакт, що зберігся ще з часів створення кентаврів.\n\nМи хотіли б отримати його, але для цього нам знадобиться фіал води з одного з місячних колодязів нічних ельфів.\n\nЩоб набрати води, тобі спочатку потрібно отримати один з фіалів дріад, що мешкають поблизу прихистку Незайманого лісу в самому серці Ясенедолу. Біля західного берега Далекоплинної річки, на південь від головної дороги, є місячний колодязь, де ти зможеш наповнити фіал.", [3] = "Принесіть наповнений гравійований фіал Занґену Кам'яному Копиту в Громовий Бескид.", [4] = "Щойно в нас буде наповнений фіал, ми надішлемо його моєму помічникові, Рау, в Тисячу Шипів. Саме він і просив фіал цієї води і йому краще знати, що з нею робити далі.", [5] = "Дуже добре. Це те, що потрібно Рау. Зможеш передати йому це? Тобі може сподобатися в Шипах.", ["en"] = "The Sacred Flame", ["tasks"] = { ["Filled Etched Phial"] = "наповнений гравійований фіал", ["Filled Etched Phial (Provided)"] = "наповнений гравійований фіал (видано)" } },
    [1196] = { [1] = "Священне полум'я", [2] = "Віднеси цей наповнений фіал Рау Скелеброду на заставу Розкутого Вітру, що на південному сході Тисячі Шипів. Ти зможеш дістатись туди, скориставшись Великим підйомником на південному краю Степів.\n\nДумаю, ти й надалі зможеш допомагати нам.", [3] = "Передайте наповнений гравійований фіал Рау Скелеброду на заставу Розкутого Вітру.", [4] = "Невже тебе прислав Занґен, гм?", [5] = "Так, цей фіал гарно послужить нашим цілям. Завдяки спільному походженню дріад і кентаврів, вода з місячних колодязів дозволить нам подолати захист вічного полум'я, що оточує реліквію кентаврів.", ["en"] = "The Sacred Flame", ["tasks"] = { ["Filled Etched Phial"] = "наповнений гравійований фіал", ["Filled Etched Phial (Provided)"] = "наповнений гравійований фіал (видано)" } },
    [1197] = { [1] = "Священне полум'я", [2] = "За допомогою цієї води ти зможеш загасити полум'я, що охороняє реліквію кентаврів. Однак воно згасне ненадовго, тому тобі доведеться діяти швидко.\n\nНа північ звідси знаходяться скелі Розщепленого Копита — фортеця кентаврів. Полум'я зберігається в укріпленні Розщепленого Копита, частині скелі, що ретельно охороняється.\n\nОднак будь {стать:обережний:обережна}, кентаврів племені Ґалак там дуже багато, і вони неохоче віддадуть таку цінну річ.", [3] = "Принесіть роздвоєне копито Рау Скелеброду на заставу Розкутого Вітру.", [4] = "Не можу дочекатись, коли нарешті доторкнутись до роздвоєного копита. Ти вже {стать:дістав:дістала} його?", [5] = "Я відчуваю дивну енергію в цьому копиті... Не сумніваюся, що вивчивши його детальніше, ми дізнаємося багато нового про кентаврів.\n\nЯ вдячний тобі, {ім'я}. А тепер я маю почати вивчення таємниць цієї реліквії.", ["en"] = "The Sacred Flame", ["tasks"] = { ["Cloven Hoof"] = "роздвоєне копито", ["Cloven Hoof (Provided)"] = "роздвоєне копито (видано)" } },
    [1201] = { [1] = "Тераморські шпигуни", [2] = "Орда та Альянс утримують хитке перемир'я. Одна сторона проводить таємні операції проти іншої, і наша мета — забезпечення переваги Орди!\n\nЗараз є шанс зробити це.\n\nШпигуни Альянсу зайняли позиції на сході від селища Папорохащі. Вони шпигують за селищем і повідомляють про наші дії Терамор. Ми не можемо це дозволити.\n\nВідшукай цих шпигунів та вбий їх. Цим ми дамо їхнім командирам ясно зрозуміти, що ми не терпітимемо присутності їхніх шпигунів!", [3] = "Убийте 9 тераморських шпигунів, а потім поверніться до Назіра Кровосписа в селище Папорохащі.", [4] = "Ти {стать:знайшов:знайшла} шпигунів, {ім'я}?", [5] = "Молодець. Їхні шпигуни вправні, але не настільки, щоб втекти від пильного ока Орди!", ["en"] = "Theramore Spies", ["tasks"] = { ["Theramore Infiltrator"] = "тераморський шпигун", ["Theramore Infiltrator slain"] = "тераморський шпигун: убито" } },
    [1202] = { [1] = "Доки Терамору", [2] = "{ім'я}, ми відправили двох шпигунів, щоб викрасти документи з корабля в доках Терамору. Вони отримали папери, але були викриті та змушені кинути документи у море.\n\nОдин зі шпигунів пізніше втік, але не зміг забрати документи. Він повідомив мені про свою невдачу, і тепер я доручаю це завдання тобі.\n\nДокументи знаходяться в скриньці, у водах десь під доками Терамору. Знайди ці документи, {ім'я}, та принеси їх мені.", [3] = "Принесіть документи капітана Назіру Кровоспису в селище Папорохащі.", [4] = "Ти {стать:знайшов:знайшла} документи, {ім'я}? Вони містять інформацію, життєво важливу для стабільності Альянсу, а отже, життєво важливу для безпеки Орди.", [5] = "Я вітаю тебе, {ім'я}. Це було нелегке завдання. Але документи, які ти {стать:здобув:здобула}, дуже цінні для наших командирів.", ["en"] = "The Theramore Docks", ["tasks"] = { ["Captain's Documents"] = "документи капітана", ["Captain's Documents (Provided)"] = "документи капітана (видано)" } },
    [1205] = { [1] = "Сипун", [2] = "Сипун — це древній кроколіск з Бруднолипкої трясовини. Йому давно вже пора померти.\n\nСкриплячи старими кістками він тягне свою величезну тушу по болоту. І хоча він все ще рухається з силою та швидкістю молодої тварини, його невгасимий полум'яний дух уже зносив своє старе тіло.\n\nАле тепер він живе в постійному болю, який його мучить. Ти маєш покласти край стражданням цієї благородної істоти, {ім'я}. Принеси Сипуну спокій.", [3] = "Принесіть зуб Сипуна Мелору в Громовий Бескид.", [4] = "Зуб Сипуна в тебе, {ім'я}? Чи вдалося тобі припинити страждання цієї істоти?", [5] = "Дуже добре, {ім'я}.\n\nЯ впевнений, що це полювання було нелегким випробуванням, але я радий, що страждання цього звіра нарешті припинилися.", ["en"] = "Deadmire", ["tasks"] = { ["Deadmire's Tooth"] = "зуб Сипуна", ["Deadmire's Tooth (Provided)"] = "зуб Сипуна (видано)" } },
    [1238] = { [1] = "Загублений звіт", [2] = "Просіюючи землю, ви знаходите відрубану руку орка, що стискає різьблену кістяну трубку. В трубці — заляпаний брудом пергамент.\n\nЦе звіт орка, що багато тижнів шпигував за Терамором.\n\nСхоже, що його потрібно доставити командиру орків-розвідників в селище Папорохащі.", [3] = "Принесіть звіт шпигуна Назіру Кровоспису в селище Папорохащі.", [4] = "В тебе є щось для мене?", [5] = "Хороша робота, {ім'я}. Наш агент, Марґ Ночеокий, працював біля Терамору. Йому було доручено шпигувати за містом.\n\nСхоже, що це його останній звіт... Судячи з твоїх слів, Марґ зустрів свій кінець на болотах...", ["en"] = "The Lost Report", ["tasks"] = { ["Spy's Report"] = "звіт шпигуна", ["Spy's Report (Provided)"] = "звіт шпигуна (видано)" } },
    [1239] = { [1] = "Відрубана голова", [2] = "Варто було копнути трохи глибше і ви знаходите відрубану голову орка. На його обличчі застиг вищир, а в його темних очах — зухвалість.", [3] = "Принесіть голову зухвалого орка Назіру Кровоспису в селище Папорохащі.", [4] = "Є ще якесь повідомлення для мене, {ім'я}?", [5] = "Це голова Марґа Ночеокого! Цього я й боявся.\n\nПодивись на поріз на його шиї! Чи могла зброя зробити такий розріз, чи якийсь звір убив нашого агента?\n\nМи маємо з'ясувати це, {ім'я}. Ми повинні дізнатися, чи винен Альянс в смерті Марґа!", ["en"] = "The Severed Head", ["tasks"] = { ["Defiant Orc Head"] = "голова зухвалого орка", ["Defiant Orc Head (Provided)"] = "голова зухвалого орка (видано)" } },
    [1240] = { [1] = "Троль-знахар", [2] = "Нам потрібно дізнатися про події, які призвели до смерті Марґа! І єдиний спосіб це зробити, {ім'я} — через магію тролів.\n\nПринеси голову Марґа до Кін'вілея в військовий табір Ґром'ґол, що в Тернистій долині.\n\nКін'вілей наймогутніший знахар тролів Темного Списа. Якщо хтось і може поговорити з духом Марґа Ночеокого, то це він.", [3] = "Віднесіть голову зухвалого орка до Кін'вілея в військовий табір Ґром'ґол, що в Тернистій долині.", [4] = "В тобі живе злий дух, {стать:брате:сестро}. Що привело тебе до Кін'вілея?", [5] = "А, тепер я бачу. Дух цього орка застряг у нашому світі й розгніваний через невиконане завдання.\n\nДобре, поговорімо з цим сердитим орком...", ["en"] = "The Troll Witchdoctor", ["tasks"] = { ["Defiant Orc Head"] = "голова зухвалого орка", ["Defiant Orc Head (Provided)"] = "голова зухвалого орка (видано)" } },
    [1251] = { [1] = "Чорний щит", [2] = "Залізний щит, почорнілий від пожежі, що вирувала в таверні, прикріплений до зруйнованого каміна, однієї з небагатьох вцілілих частин споруди, яка колись була таверною «Відпочинок у затінку».\n\nЩит можна зняти.", [3] = "Принесіть почорнілий залізний щит Кроґу в селище Папорохащі.", [4] = "Що це у тебе, {ім'я}? Зачіпка з руїн таверни «Відпочинок у затінку»?", [5] = "У людей дивний смак у декоруванні, але навіщо вішати над каміном простий металевий щит? Можливо, цей щит повісили туди ті, хто спалив таверну.\n\nМожливо, це попередження? Чи погроза?", ["en"] = "The Black Shield", ["tasks"] = { ["Blackened Iron Shield"] = "почорнілий залізний щит", ["Blackened Iron Shield (Provided)"] = "почорнілий залізний щит (видано)" } },
    [1261] = { [1] = "Марґ говорить", [2] = "Клятий брудопанцирник! Ти не вб'єш Марґа! А, я мертвий. Тож він убив мене...\n\nАле моє завдання! Моє завдання! Ти, {ім'я}, {стать:повинен:повинна} його завершити.\n\nПоблизу Терамору я помітив групу солдат Альянсу, які стали табором на пляжі. І один з них носив кулон... кулон, вкритий великою кількістю самоцвітів, які простий солдат дозволити собі не міг!\n\nТої ночі я потай забрав цей кулон з їхнього табору, але коли я повертався до бази мене вбив брудопанцирний людо-краб!\n\n{ім'я}, ти повинен знайти того людо-краба та повернути кулон!", [3] = "Принесіть кулон з самоцвітами Назіру в селище Папорохащі.", [4] = "{ім'я}, ти {стать:дізнався:дізналася} про долю Марґа?", [5] = "Цей кулон носив солдат Штормовію?\n\nДякую, {ім'я}. Ти {стать:розкрив:розкрила} таємницю смерті Марґа. Але цей кулон — нова загадка, яка може мати негативні наслідки для Альянсу та Орди.", ["en"] = "Marg Speaks", ["tasks"] = { ["Jeweled Pendant"] = "кулон з самоцвітами", ["Jeweled Pendant (Provided)"] = "кулон з самоцвітами (видано)" } },
    [1262] = { [1] = "Доповідь для Зора", [2] = "Дивно, що кулон, який Марґ вкрав, був в руках простого солдата. Можливо, його власник маскувався, або ж самі солдати його й вкрали!\n\nНезалежно від того, правда це чи ні, це кулон шляхтича, і ми повинні знайти його справжнього власника, якщо хочемо розгадати цю таємницю.\n\nВіднеси цей кулон Зору Самітному Дереву в Орґріммар. Він добре знається на політиці Альянсу і зможе сказати, чи пов'язаний цей кулон з вельможами Штормовію.", [3] = "Принесіть кулон з самоцвітами Зору Самітному Дереву в Орґріммар.", [4] = "Ти {стать:прийшов:прийшла} аж з селища Папорохащі, що в Бруднопилкій трясовині? Як поживає Назір, і як його справи на болоті?", [5] = "Це кулон напрочуд тонкої та майстерної роботи, {ім'я}. Жоден орк не бажав би таку коштовність...\n\nНа відміну від людей.\n\nЯ зроблю дослідження цього кулону. Будемо сподіватися, що з часом його таємниці розкриються нам.", ["en"] = "Report to Zor", ["tasks"] = { ["Jeweled Pendant"] = "кулон з самоцвітами", ["Jeweled Pendant (Provided)"] = "кулон з самоцвітами (видано)" } },
    [1268] = { [1] = "Підозрілі сліди копит", [2] = "Сліди копит ведуть від все ще тліючих руїн таверни «Відпочинок у затінку». Є принаймні кілька чітких відбитків і багато інших слідів, ледве помітних на м'якому болотистому ґрунті.", [3] = "Повідомте про підозрілі сліди в таверні «Відпочинок у затінку» Кроґа в селищі Папорохащі.", [5] = "Сліди копит... Думаю, це можуть бути свинобрази. Або навіть кентаври. Те, що вони прийшли зі Степів, щось означає, і, здається мені, вони здатні на такий вчинок.\n\nЯ тобі не казав? Вони не просто спалили таверну... дружину та дитину власника вбили. Погана справа...\n\nГаразд, я пошлю Каґоро подивитися, куди ведуть сліди.", ["en"] = "Suspicious Hoofprints" },
    [1269] = { [1] = "Лейтенант Павал Ріт", [2] = "Блиск на землі привертає вашу увагу, і ви помічаєте під завалами блискучий предмет. Обтерши його від сміття й попелу, ви розумієте, що це знак Терамора — золотий якір на білому фоні.\n\nПід якорем викарбувано ім'я \"Лейтенант Павал Ріт\".", [3] = "Принесіть жетон Ріта капітану Кроґу в селище Папорохащі.", [4] = "Вдалось знайти щось цікаве на руїнах таверни «Відпочинок у затінку»?", [5] = "Я знаю цю людину, Павала Ріта. Жалюгідний навіть як для свого виду. Він здезертирував і зараз ховається у лісі.\n\nЯ відправив Оґрона на його пошуки. Дехто підозрює, що він крав наші запаси. Я бачив, як Оґрон прямував на південний схід.", ["en"] = "Lieutenant Paval Reethe", ["tasks"] = { ["Reethe's Badge"] = "жетон Ріта", ["Reethe's Badge (Provided)"] = "жетон Ріта (видано)" } },
    [1270] = { [1] = "Втеча Смердючки", [2] = "Чудово, нарешті знайшовся хтось, хто не хоче з'їсти мене!\n\nМені потрібна допомога, щоб розібратися з тутешніми звірами, а ти якраз підходиш, {стать:приятелю:приятелько}.\n\nГобліну з Брашпиля, на ім'я Мебок Міцрікс потрібне листя болотних бобів для зілля, чи чогось такого... Чесно кажучи, мені байдуже, для чого воно йому потрібне — він непогано платить, а я знаю це болото, ось тому я й тут.\n\nВ будь-якому разі, під час пошуку болотних бобів... Мене оточили! Зможеш допомогти мені вибратися звідси та прикрити мене, поки я шукатиму ці боби?", [3] = "Проведіть \"Смердючку\" Іґнаца, після чого поговоріть з Мебоком Міцріксом у Брашпилі.", [5] = "Смердючка був тут з листям болотних бобів, і він розповів мені, що ти {стать:допоміг:допомогла} йому в скрутній ситуації. Гарна робота! Друг Смердючки — мій друг!\n\nПеред тим як повертатися на болота, він попросив передати тобі це.", ["en"] = "Stinky's Escape", ["tasks"] = { ["Help Stinky find Bogbean Leaves"] = "Допоможіть Смердючому знайти Листя Богобана" } },
    [1273] = { [1] = "Допит Ріта", [2] = "Пошуки Ріта зайняли деякий час, але я знайшов його. Він добре сховався, як для людини.\n\nОґрон занепокоєний, що після стількох днів у болоті він міг зійти з розуму. Пішли, поговоримо з ним.", [3] = "Разом з Оґроном поговоріть з Рітом, а потім поверніться до Кроґа в селище Папорохащі.", [4] = "Ти {стать:знайшов:знайшла} Ріта?", [5] = "Хмм. Добре, що Ріт більше не ховається на болоті, але шкода, що люди такі слабкі, що не можуть відновитись після невеликого поранення стрілою.\n\nЗдається, ця зачіпка нікуди не привела, і нам доведеться шукати інші сліди.", ["en"] = "Questioning Reethe", ["tasks"] = { ["Question Reethe with Ogron"] = "Розпитайте Ріта про Огрона" } },
    [1276] = { [1] = "Чорний щит", [2] = "Ах, згадав! Мосарн — це відомий коваль у Громовому Бескиді. Я знав, що чув його ім'я десь раніше.\n\nВ знак подяки, Служителі Землі відзначили мене комплектом броні, створеної Мосарном. Дуже гарна робота.\n\nМожливо, він зможе розповісти тобі більше про щит, який він створив.\n\nЦе не дуже великий крок вперед, але, оскільки ми не дізналися нічого корисного від Ріта, це все, що маємо.", [3] = "Покажіть почорнілий залізний щит Мосарну в Громовому Бескиді.", [4] = "Привіт, {клас:к}. Допомогти тобі з чимось?", [5] = "Так, ти маєш рацію. Цей щит я зробив.\n\nБоюся, що я більше нічого не можу тобі розповісти, {ім'я}. Я виготовляю так багато різних щитів та обладунків, що не можу встежити за ними всіма.", ["en"] = "The Black Shield", ["tasks"] = { ["Blackened Iron Shield"] = "почорнілий залізний щит", ["Blackened Iron Shield (Provided)"] = "почорнілий залізний щит (видано)" } },
    [1321] = { [1] = "Чорний щит", [2] = "Хмм... Нічого незвичайного на цьому щиті не бачу. Можливо, нам слід попросити коваля, До'ґола, розповісти більше про нього. Але я б надто на це не розраховував...", [3] = "Покажіть почорнілий залізний щит До'ґолу в селищі Папорохащі.", [4] = "Що це в тебе, {клас:к}?", [5] = "Це хороший щит. Дуже міцний, важкий, хороший. Але До'ґолу він не потрібен. Я роблю щити, а не купую їх, {ім'я}.\n\nТи маєш це знати.", ["en"] = "The Black Shield", ["tasks"] = { ["Blackened Iron Shield"] = "почорнілий залізний щит", ["Blackened Iron Shield (Provided)"] = "почорнілий залізний щит (видано)" } },
    [1322] = { [1] = "Чорний щит", [2] = "Хм, тут є напис на ободі щита, але прочитати його важко — він майже весь обгорів.\n\nМені потрібна кислота, щоб відчистити його. Отрута темножвалих павуків, що мешкають у болотах, підійде. Принеси мені трохи їхніх отруйних залоз, і я зможу відчистити цей щит.", [3] = "Добудьте 6 їдких отруйних залоз для До'ґола з селища Папорохащі.", [4] = "Ти {стать:добув:добула} залози з павуків?", [5] = "Мені не подобаються павуки, які настільки великі, що я не можу на них сісти й розчавити.\n\nДякую, що {стать:добув:добула} їх, {ім'я}. Тепер я їх розірву і заллю щит...", ["en"] = "The Black Shield", ["tasks"] = { ["Acidic Venom Sac"] = "їдка отруйна залоза", ["Acidic Venom Sac (Provided)"] = "їдка отруйна залоза (видано)" } },
    [1323] = { [1] = "Чорний щит", [2] = "Йой, мабуть, я налив на щит надто багато кислоти. Дай я трішки протру...\n\nГм, важко прочитати, але здається, що тут написано ім'я Мосарн. Я ніколи не чув про нього. Може Кроґ знає. Кроґ знає багато народу.", [3] = "Поговоріть з Кроґом в селищі Папорохащі.", [5] = "Мосарн? Звучить знайомо... Не можу пригадати. Може, потім згадаю.\n\nЦе, мабуть, не важливо. Щит міг потрапити туди звідки завгодно...", ["en"] = "The Black Shield" },
    [1359] = { [1] = "Доставка Зінґе", [2] = "Вовчі серця, як ти {стать:роздобув:роздобула}, мають особливість, небачену в інших схожих особин. Їхня токсичність мала б бути смертельною для самих вовків, у чиїх грудях ці серця билися!\n\nЦе просто надзвичайно, і ми повинні вивчити це глибше. Я зберіг кілька зразків цих сердець. Віднеси їх моїй колезі, аптекарці Зінґе. Ти знайдеш її у нашому осередку в Підмісті.", [3] = "Принесіть зразки вовчих сердець аптекарці Зінґе в Підмістя.", [4] = "Ти маєш щось для мене?", [5] = "О, так, це ті самі зразки, про які говорив Ренферрел. Мені не терпиться поекспериментувати з ними... Королівському товариству аптекарів завжди цікаво, коли відкривають нові форми токсинів.", ["en"] = "Zinge's Delivery", ["tasks"] = { ["Wolf Heart Samples"] = "зразки вовчих сердець", ["Wolf Heart Samples (Provided)"] = "зразки вовчих сердець (видано)" } },
    [1361] = { [1] = "Реґтар Згубобрама", [2] = "Воїн Орди, Реґтар Згубобрама, вербує агентів для завдання на землях Спустошища. Поговори з ним, якщо хочеш долучитися. Знайти Реґтара можна в Степах, в одному з бункерів на захід від Перехрестя.\n\nІ підготуй зброю. Спустошище — це небезпечне місце, в якому постійно іде війна.", [3] = "Поговоріть з Реґтаром Згубобрамою.", [5] = "Так, я шукаю добровольців, які готові відправитися в Спустошище та воювати проти місцевих кентаврів. Щоб ти {стать:міг:могла} розпочати за роботу, я швиденько введу тебе в курс справи.", ["en"] = "Regthar Deathgate" },
    [1362] = { [1] = "Колкари Спустошища", [2] = "Колкарські кентаври мешкають в Спустошищі, але їх також можна побачити й в Степах. Це відомий факт і Орда відправила своїх агентів для боротьби з ними.\n\nАле поки кентаври сильні в Спустошищі, вони завжди нестимуть загрозу для нас. Настав час від них позбутися.\n\nПоговори з Фелґуром Дворізом на заставі Блукаючих Привидів в Спустошищі. Його відправили туди збирати відомості про кентаврів. Він найкраще знає, як впоратися з Колкарами зі Спустошища.", [3] = "Поговоріть з Фелґуром Дворізом на заставі Блукаючих Привидів в Спустошищі.", [5] = "Ти тут за наказом Реґтара? Тоді ти маєш розв'язати проблему з кентаврами. Добре.\n\nСподіваюся, ти {стать:відпочив:відпочила}. Я не знаю, як закінчиться наша боротьба з кентаврами, але знаю, що вона буде довгою.\n\nПрисядь і послухай.", ["en"] = "The Kolkar of Desolace" },
    [1365] = { [1] = "Хан Дез'геп", [2] = "Колкари — не єдині кентаври в Спустошищі. Багато кланів блукають цими сухими рівнинами, борються один з одним та вмирають. Добре, що вони воюють між собою, бо це сильні та жорстокі воїни. Якби кентаври об'єдналися, нам би важко було боротися проти них.\n\nНам потрібно розібратися з ними до того, як вони об'єднаються.\n\nТвоє перше завдання — знищити клан Колкарів. Для цього потрібно вибити їхнього лідера, хана Дез'гепа.\n\nПоселення Колкарів на північному сході звідси. Йди та нехай щастить тобі.", [3] = "Принесіть голову хана Дез'гепа Фелґуру Дворізу в Спустошище.", [4] = "{ім'я}, тобі вдалося перемогти хана Дез'гепа?", [5] = "Молодець. Цей удар по клану Колкарів був ефективною демонстрацією сили, а сила — це те, що кентаври розуміють найкраще.\n\nСмерть лідера Колкарів не лише розколе клан, але й стане застереженням для інших кентаврів.", ["en"] = "Khan Dez'hepah", ["tasks"] = { ["Khan Dez'hepah's Head"] = "голова хана Дез'гепа", ["Khan Dez'hepah's Head (Provided)"] = "голова хана Дез'гепа (видано)" } },
    [1366] = { [1] = "Нагорода за кентаврів", [2] = "Тепер, коли ти {стать:налякав:налякала} кентаврів, настав час пустити їм кров. Подорожуючи Спустошищем, полюй на кентаврів. Мені байдуже, на який клан ти полюватимеш. Просто збирай вуха. Купу вух!\n\nЗменшивши кількість кентаврів, ти послабиш їхню рішучість і викоріниш у них будь-які думки про завоювання цих земель.\n\nВдалого полювання, {ім'я}.", [3] = "Принесіть 15 вух кентаврів Фелґуру Дворізу в Спустошище.", [4] = "Як проходить збір вух, {ім'я}? Багато {стать:нарізав:нарізала}?", [5] = "Тепер кентаври назавжди запам'ятають твоє ім'я. Я впевнений, що вони тебе знають, поважають і бояться. І так само як вони знають тебе, вони знають стяг, під яким ти воюєш.\n\nСтяг Орди.", ["en"] = "Centaur Bounty", ["tasks"] = { ["Centaur Ear"] = "вухо кентавра", ["Centaur Ear (Provided)"] = "вухо кентавра (видано)" } },
    [1372] = { [1] = "Нічого, крім правди", [2] = "Наші експедиційні сили були відправлені за дорученням Варіматраса для дослідження нижнього Азероту.\n\nПід час розвідки я помітив людину-шпигуна, що шпигував за притулком Бідаків. Перед тим, як я хотів його затримати, деякі наші оркські... побратими... захопили його і взяли з собою до Камінарда, їхньої фортеці у болоті Скорбот.\n\nЯ хочу... допомогти... нашим оркським союзникам. Вони не помітили наш табір, але я все одно збираюся протягнути їм руку допомоги.\n\nПопрацюй з Фаустіном тут, щоб розробити... сироватку правди для нашого друга у Камінарді.", [3] = "Поговоріть з аптекарем Фаустіном у притулку Бідаків.", [5] = "Зредус щойно розповів мені про цього шпигуна перед тим, як ти {стать:прийшов:прийшла}.\n\nЦе справді серйозна проблема. Останнє, що нам потрібно, це шпигун, який винюхує щось в притулку Бідаків.\n\nЯ впевнений, що орки в Камінарді з цікавістю вислухають його. Зважаючи на те, що вони наші союзники... кхм... ми повинні допомогти їм вивідати будь-яку інформацію, яку вони можуть отримати від цієї людини.\n\nДопоможи мені, {ім'я}, і ми доставимо сироватку правди в Камінард.\n\nЗа Орду!\n\n...я ж правильно сказав?", ["en"] = "Nothing But The Truth" },
    [1383] = { [1] = "Нічого, крім правди", [2] = "Я знаю одну сироватку, яка нам може підійти. Вона розкриє правду як слід.\n\nЩоб зробити її, мені знадобиться кілька сердець тіньових пантер з болота. Також потрібна зачарований гриб з повелителя болота, який мешкає неподалік. Я впевнений, що {стать:такий досвідчений:така досвідчена} {клас}, як ти, {ім'я}, зможе його переконати поділитися з тобою.\n\nІ найважче — тобі потрібно знайти пухлину глибокохода з далекого Спустошища. Ці гіганти рідко хворіють, а пухлини в них з'являються ще рідше.\n\nА тепер йди!", [3] = "Аптекарю Фаустіну з притулку Бідаків потрібні 5 сердець тіньової пантери, гриб повелителя болота і пухлина глибокохода.", [4] = "Той шпигун у Камінарді безперечно... розкриє всю правду... після того, як вип'є моєї спеціальної сироватки. Ха-ха!\n\nНеобхідні інгредієнти зовсім не просто знайти. Тіньові пантери зазвичай знаходяться в болоті, але зібрати достатньо сердець для наших цілей може бути непросто. А повелитель болота може бути досить примхливим чудовиськом.\n\nТа й пухлину глибокохода теж надзвичайно складно знайти. Але хімічна реакція, яку можна отримати з неї, неперевершена.", [5] = "Чудово, {ім'я}! І саме вчасно. Судячи з того, що розповів мені Зредус, шпигун оговтався від ран і готовий до допиту.\n\nДай мені хвилинку, щоб підготувати отру... тобто підготувати сироватку правди.", ["en"] = "Nothing But The Truth", ["tasks"] = { ["Deepstrider Tumor"] = "пухлина глибокохода", ["Deepstrider Tumor (Provided)"] = "пухлина глибокохода (видано)", ["Mire Lord Fungus"] = "гриб повелителя болота", ["Mire Lord Fungus (Provided)"] = "гриб повелителя болота (видано)", ["Shadow Panther Heart"] = "серце тіньової пантери", ["Shadow Panther Heart (Provided)"] = "серце тіньової пантери (видано)" } },
    [1388] = { [1] = "Нічого, крім правди", [2] = "Все йде за планом, {ім'я}. Я хочу, щоб ти {стать:дав:дала} цю сироватку правди смертолову Зредусу, і він покаже тобі, як правильно її... застосовувати.\n\nХа-ха!", [3] = "Віддайте сироватку правди Фаустіна смертолову Зредусу в притулку Бідаків.", [4] = "Схоже, що ти добре {стать:допоміг:допомогла} нашому дорогому другові, аптекарю Фаустіну.", [5] = "Я знав, що старий Фаустін придумає щось гарне! Ти нам дуже {стать:допоміг:допомогла}, без сумніву.\n\nА тепер перейдімо до справи, еге ж?", ["en"] = "Nothing But The Truth", ["tasks"] = { ["Faustin's Truth Serum"] = "сироватка правди Фаустіна", ["Faustin's Truth Serum (Provided)"] = "сироватка правди Фаустіна (видано)" } },
    [1391] = { [1] = "Нічого, крім правди", [2] = "Нам потрібно діяти обережно. Зрештою, ти ж не збираєшся туди просто зайти та переконати дурня випити сироватку Фаустіна, правда?\n\nАле від випивки жодна людина не відмовиться. Я змішаю сироватку Фаустіна з цим елем. Я гарантую, що бідолаха без вагань прийме цю випивку.\n\nПоспішай до Камінарда в болото Скорбот, {ім'я}. І збережи наше маленьке завдання в таємниці...", [3] = "Віднесіть вариво Зредуса шпигуну Марксену в Камінард.", [4] = "Будь ласка, змилуйся наді мною! Я маю відомості, які не стосуються Альянсу. Хоча я й не прихильник Орди, але ми зіткнулися зі зрадою, яку я маю викрити!", [5] = "Напій для мене? Як мило з твого боку. Мені вже кілька днів не дозволяють пити. Дозволь мені випити це, а потім я розповім тобі, що я дізнався...", ["en"] = "Nothing But The Truth", ["tasks"] = { ["Zraedus's Brew"] = "вариво Зредуса", ["Zraedus's Brew (Provided)"] = "вариво Зредуса (видано)" } },
    [1394] = { [1] = "Остання подорож", [2] = "Ти гарно {стать:впорався:впоралася}, {ім'я}. Ти {стать:пройшов:пройшла} моє та всі попередні випробування. Повертайся до Дорна в Тисячу Шипів. Він відчує зміни в тобі, і побачить, що твій розум, тіло та дух досить сильні, щоб винагородити тебе за твої зусилля.\n\nЗавжди зберігай у собі ту гармонію, що ти {стать:демонстрував:демонструвала} в цих випробуваннях, {ім'я}, і тоді в майбутньому Дорн зможе випробувати тебе знову.", [3] = "Поговоріть з Дорном Рівнинним Ловцем в Тисячі Шипів.", [5] = "А, {ім'я}. Пройшло чимало часу відтоді, як ти {стать:ступив:ступила} на поріг мого дому. Схоже, що багато місяців минуло з того часу, як ти {стать:зробив:зробила} свій перший стрибок, який наставив тебе на шлях.\n\nІ зараз, ти повертаєшся до мене, набагато {стать:сильнішим:сильнішою} ніж раніше... І набагато {стать:мудрішим:мудрішою}. Це радує мене. За те, що ти {стать:пройшов:пройшла} всі мої випробування, ти отримаєш гідну винагороду.", ["en"] = "Final Passage" },
    [1418] = { [1] = "Ніка Кровошрам", [2] = "Безплідні краї суворі й межують з територією Альянсу — Лох-Моданом, тому сполучення між Камінардом і аванпостом у Безплідних краях часто розривається.\n\nУ тебе є можливість проявити себе, {Ім'я}. Вирушай в Безплідні краї та поговори з Нікою Кровошрамом, старшою розвідницею Карґату, а потім принеси мені її доповідь.", [3] = "Поговоріть з Нікою Кровошрамом.", [5] = "Гелґраму потрібна доповідь, га? Не минуло і трьох днів, як я посилала гінця в Камінард. Він що, провалив своє завдання? Якщо в Камінарді немає моєї доповіді, то, схоже, він зазнав невдачі.\n\nБудемо сподіватися, що наступний вістовий, якого я пошлю, матиме більше навичок, або більше талану.", ["en"] = "Neeka Bloodscar" },
    [1419] = { [1] = "Койоти-злодії", [2] = "Чи багато днів ти {стать:провів:провела} у Безплідних краях, {клас:к}? Чи {стать:відчув:відчула} ти їхню спеку? Чи зустрічалися тобі тварюки, що блукають їхніми запиленими рівнинами? Час для цього настав.\n\nСкельні койоти — міцної породи. Міцної та достатньо сміливої, щоб пробиратися у Карґат і красти нашу їжу. Допоможи нам позбутися цих злодіїв!\n\nВполюй скельних койотів, {ім'я}. Вполюй їх і принеси мені їхні щелепи. Принесеш вдосталь, і, можливо, тоді я повірю, що ти дійсно знаєш Безплідні краї.", [3] = "Принесіть 30 щелеп койотів до Ніки Кровошрам у Карґат.", [4] = "Ти {стать:приніс:принесла} щелепи?", [5] = "Це мила колекція щелеп, {ім'я}. Тепер-то ці койоти не шматуватимуть наші припаси у пошуках недоїдків.\n\nЧудова робота. Койоти Безплідних країв — не така вже й легка здобич. Твій вчинок доводить, що ти зможеш тут вижити.", ["en"] = "Coyote Thieves", ["tasks"] = { ["Coyote Jawbone"] = "щелепа койота", ["Coyote Jawbone (Provided)"] = "щелепа койота (видано)" } },
    [1420] = { [1] = "Доповідь Гелґрамові", [2] = "Я написала нову доповідь для Гелґрама з Камінарда. Віднеси її йому.\n\nІ якщо ти вважаєш себе гінцем, то не збийся зі шляху. І не попадайся ворогам.", [3] = "Принесіть доповідь Ніки Гелґрамові Прудкому в Камінард.", [4] = "Ти {стать:повернувся:повернулась}. Доповідь при тобі?", [5] = "Дякую, {ім'я}. З доповіді Ніки я бачу, що Альянсові не бракне власних проблем. І, можливо, ми виявимо, що у нас є спільні вороги.", ["en"] = "Report to Helgrum", ["tasks"] = { ["Neeka's Report"] = "доповідь Ніки", ["Neeka's Report (Provided)"] = "доповідь Ніки (видано)" } },
    [1422] = { [1] = "Загроза з моря", [2] = "Поки я буду працювати над твоєю зброєю, чому б тобі не поговорити з Катаром? Він, говорив, що йому потрібна допомога з патрулюванням узбережжя, і я б радше бачив як ти тримаєш розум та зброю напоготові, замість того, щоб напиватись з деякими іншими невдахами з цього табору.", [3] = "Поговоріть з Катаром на болоті Скорбот.", [5] = "Помовч трохи, {клас:к}. Навіть крізь глухий рев моря все ще чутно огидне булькання риболюдів.", ["en"] = "Threat From the Sea" },
    [1424] = { [1] = "Став Сліз", [2] = "Воєвождь відправив нас дослідити дивовиська, що відбуваються в храмі Атал'Гаккар.\n\nТролі Атал'ай — плем'я темних заклинателів, відомих тим, що використовують заборонену магію. Можеш собі уявити, як ми були вражені, коли дізналися що храм затоплений.\n\nТепер його чатують зелені дракони, які висувають права на звання захисників Азероту.\n\nМи повинні з'ясувати, що сталося. Досліди околиці ставу Сліз і збери артефакти Атал'ай. Таким чином я зможу скласти цю головоломку.", [3] = "Зберіть 10 артефактів Атал'ай для Фел'зерула з Камінарда.", [4] = "Ніхто не знає, які темні обряди творилися в храмі Атал'Гаккар. Але ми знаємо, що там застосовувалися потужні закляття.\n\nМи повинні дізнатися якомога більше про цю магію. Можливо, заклинання Атал'ай виявляться корисними для Орди.\n\nЯкщо ти збереш достатньо артефактів Атал'ай в околицях ставу Сліз, я зможу зрозуміти, чого саме сподівались досягти тролі та в чому була їх жахлива помилка.", [5] = "Твоя старанність в збиранні артефактів Атал'ай заслуговує похвали, {клас:к}.", ["en"] = "Pool of Tears", ["tasks"] = { ["Atal'ai Artifact"] = "артефакт Атал'ай", ["Atal'ai Artifact (Provided)"] = "артефакт Атал'ай (видано)" } },
    [1426] = { [1] = "Загроза з моря", [2] = "Не маю любові ані до моря, ані до жодної істоти, що лізе з його глибин. Це могутня, але сліпа, стихія; байдужа і жорстока. З великим задоволенням я винищував би цих риболюдів сотнями, якби це було в моїх силах. Але мені принесе радість видовище їх загибелі від рук тих, хто виконує волю Орди.\n\nВід твоїх рук, {клас:к}. Скількох ти зможеш вбити? Чи хочеш ти випробувати себе і битися з найсильнішими з них?", [3] = "Убийте 10 трясовинних мурлоків, 10 трясовинних чорнильників і 10 трясовинних живоїдів, після чого поверніться до Катара на болото Скорбот.", [4] = "Я терплячий. Терплячий і вічний, як старий камінь з Дренору. Риболюди не порушать наші кордони, поки я ще можу стояти. Якби у нас була армія, я очистив би цей, і всі інші світи, від них. Я відчуваю, як моя ненависть клекоче, навіть, коли лише говорю про них.", [5] = "Море здається величезним і невблаганним, але ти {стать:заплямував:заплямувала} його кров'ю його власних породжень. Риболюди знають, що таке біль. Їх тупість змусить їх згуртувати ряди після того розгрому, який ти їм {стать:учинив:учинила}, і це добре.\n\nНехай їх булькітливі крики заглушають шум моря аж до ночі. Я буду посміхатися кожен раз як почую, що хтось із них замовк.\n\nПовертайся до мене, якщо раптом захочеться повбивати ще риболюдів. Я із задоволенням винагороджу тебе за це ще раз.", ["en"] = "Threat From the Sea", ["tasks"] = { ["Marsh Flesheater"] = "трясовинний живоїд", ["Marsh Flesheater slain"] = "трясовинний живоїд: убито", ["Marsh Inkspewer"] = "трясовинний чорнильник", ["Marsh Inkspewer slain"] = "трясовинний чорнильник: убито", ["Marsh Murloc"] = "трясовинний мурлок", ["Marsh Murloc slain"] = "трясовинний мурлок: убито" } },
    [1427] = { [1] = "Загроза з моря", [2] = "Перш ніж піти відпочити, поговори з Ток'Каром знов. Поки тебе не було, думаю, він закінчив роботу над зброєю. За твою допомогу він запропонує її тобі. Було б непогано, якби ти {стать:випробував:випробувала} її силу на риболюдях, коли будеш {стать:готовий:готова}... зроби мені ласку.", [3] = "Поговоріть з Ток'Каром на болоті Скорбот.", [5] = "А, {ім'я}, ти {стать:повернувся:повернулась}. Добре. Я якраз закінчив виготовляти зброю для нашої боротьби проти мурлоків. За свіже м'ясо пилкозубів і за те, що {стать:змусив:змусила} Катара трохи посміхнутись, вибери собі щось.", ["en"] = "Threat From the Sea" },
    [1428] = { [1] = "Тривала загроза", [2] = "Мені приємно бачити, що ненависть, яку ти відчуваєш до риболюдів, зростає, як і моя.\n\nЗнайди їх на узбережжі, а потім, коли битва буде закінчена, повертайся. Тоді ми вирішимо, як винагородити тебе за старанність.", [3] = "Вбийте 10 трясовинних чорнильників, 10 трясовинних живоїдів і 10 трясовинних оракулів, після чого поверніться до Катара на болото Скорбот.", [4] = "Доти, поки море і всі його породження не сконають, я не буду задоволений... особливо ті огидні риболюди.", [5] = "Відмінно, {клас:к}. Але я вимагаю більше їхньої крові. Нехай всі риболюди згинуть.", ["en"] = "Continued Threat", ["tasks"] = { ["Marsh Flesheater"] = "трясовинний живоїд", ["Marsh Flesheater slain"] = "трясовинний живоїд: убито", ["Marsh Inkspewer"] = "трясовинний чорнильник", ["Marsh Inkspewer slain"] = "трясовинний чорнильник: убито", ["Marsh Oracle"] = "трясовинний оракул", ["Marsh Oracle slain"] = "трясовинний оракул: убито" } },
    [1429] = { [1] = "Вигнанець Атал'ай", [2] = "Поки ти сміливо {стать:долав:долала} небезпеки ставу Сліз, один з моїх розвідників повернувся з сувоєм написаним кров'ю на висушеній плоті. Здається, це судовий вирок жерцеві племені Атал'ай.\n\nЦей жрець був засуджений до долі гіршої, ніж смерть серед своїх.\n\nВін був вигнаний на північ до Внутрішніх земель, жити серед тролів племені Зів'ялої Кори.\n\nЯ упакую ці артефакти, а тобі належить знайти вигнанця і з'ясувати їх призначення. Повертайся до мене, коли завершиш подорож.", [3] = "Принесіть пакунок з артефактами Атал'ай до вигнанця Атал'ай у Внутрішні земліі.", [4] = "Прийти сюди було сміливим вчинком. Сміливим або дурним...", [5] = "Ти {стать:приніс:принесла} мені артефакти виклику Атал'ай?\n\nЯ бачу, Джаммал'ан-Пророк веде своїх послідовників Кривавої Палати до обраної ними долі. Цікаво, чи повернувся Гаккар у свій храм? Чи зустріли вони свою долю?", ["en"] = "The Atal'ai Exile", ["tasks"] = { ["Bundle of Atal'ai Artifacts"] = "пакунок з артефактами Атал'ай", ["Bundle of Atal'ai Artifacts (Provided)"] = "пакунок з артефактами Атал'ай (видано)" } },
    [1430] = { [1] = "Свіже м'ясо", [2] = "Серед моїх покупців високий попит на соковите м'ясо повзунів, особливо м'ясо жахливого повзуна.\n\nЯкщо ти плануєш вирушити на узбережжя, то можеш зробити це з вигодою. Принеси мені кілька ніг жахливого повзуна і я відправлю їх до Орґріммару.\n\nУзбережжя знаходиться на схід звідси, в тебе не має виникнути проблем з пошуком тих істот, що снують на березі та під водою.", [3] = "Принесіть 10 ніг жахливих повзунів Дару на болото Скорбот.", [4] = "У мене тут барильце вина чекає твого повернення, {ім'я}. Як на мене, товар спершу треба скуштувати, і лише потім відсилати замовнику.", [5] = "Ех, це має бути відмінно. Не дочекаюся, коли спробую м'ясо повзуна, приготовлене належним чином на відкритому вогні. Візьми з собою в дорогу дещицю. Смак просто незрівнянний.", ["en"] = "Fresh Meat", ["tasks"] = { ["Monstrous Crawler Leg"] = "нога жахливого повзуна", ["Monstrous Crawler Leg (Provided)"] = "нога жахливого повзуна (видано)" } },
    [1431] = { [1] = "Відносини з Альянсом", [2] = "Почекай, {клас:к}, дозволь мені поділитися з тобою дечим важливим для нашого народу, та геть не очевидним.\n\nМи гордий народ, і війна з людьми виснажила навіть терпіння Тралла. Бачиш, наш воєвождь мудрий і розважливий, а інтереси нашого народу для нього понад усе. Зрештою, він дипломат, і за час, проведений з людьми, він багато чому навчився у них.\n\nЯкщо тобі це цікаво — знайди Келдрана біля західного виходу з міста. Його халупа там.", [3] = "Поговоріть з Келдраном в Орґріммарі.", [5] = "Патанні, {стать:благородний:благородна} {клас:к}. Мене звати Келдран, я вивчаю магію... та інші таємні мистецтва.\n\nСправа, з приводу якої Крейвен послав тебе до мене, вимагає дещо більшої витонченості, ніж ті, з якими ти {стать:мав:мала} справу раніше, але це не означає, що ти не можеш нам допомогти.\n\nБудь ласка, влаштовуйся зручніше, і я розповім тобі, чому воєвождю потрібна моя... і твоя допомога.\n\nВсе починається з зовнішності, {ім'я}. Якою бачить себе Орда. Якими нас бачать наші союзники. І найголовніше — якими нас бачать наші вороги.", ["en"] = "Alliance Relations" },
    [1432] = { [1] = "Відносини з Альянсом", [2] = "У міру того, як Альянс просувається все глибше і глибше в Калімдор, може скластися враження, що Орда вступає в союз з Палаючим Легіоном. Воєвождь не може цього допустити. І з його благословення я беру під свій контроль їх усунення.\n\nУ мене є свої агенти в районі Спустошища на заставі Блукаючих Привидів на північ від великого кладовища кодо. Прямуй на південь від Обвугленої долини в Каміннопазуристих горах, і натрапиш на неї. Коли прибудеш туди, розшукай Такату Гостроклина.", [3] = "Поговоріть з Такатою Гостроклином в Спустошищі.", [5] = "Вітаю, {клас:к}. У тебе є звістки з Орґріммара? Це добре.\n\nТутешні краї наповнені демонами — навіть більше, ніж гноєм кентаврів. Конелюди вважають ці землі своїми, але очевидно, що є сили, з якими їм ніяк не впоратися, якщо не тримати їх під контролем.\n\nМені не подобається, що ми опосередковано допомагаємо кентаврам, але це на благо Орди, тож я виконую свій обов'язок перед воєвождем, навіть якщо це означає допомогу чорнокнижникам всередині Орди.", ["en"] = "Alliance Relations" },
    [1433] = { [1] = "Відносини з Альянсом", [2] = "У Палаючого Леза багато планів, але знайте, що вони віддані злу до глибини душі, їхні душі зіпсовані, і єдиний спосіб їх зупинити — це знищити.\n\nКелдран відправив Мавріна зі мною тому, що він знає багато чого про Палаюче Лезо і розуміється на методах чорнокнижників.\n\nВін бореться з Лезом, поки я займаюсь іншими демонічними загрозами у Спустошищі.\n\nПоговори з ним, і він розкаже тобі про свої плани.", [3] = "Поговоріть з Мавріном Кісткощепом в Спустошищі.", [5] = "О, так. Нам завжди знадобиться допомога тих, хто відданий воєвождю.\n\nМене звати Маврін. Я тут за наказом Келдрана і нашого юного воєвождя, Тралла. Я хочу допомогти нашому молодому лідеру протистояти злу, що загрожує його правлінню.\n\nПідійди-но ближче, {клас:к}. Я розкажу тобі про свої плани усунення цього гнійного нариву, яким є Палаюче Лезо.", ["en"] = "Alliance Relations" },
    [1434] = { [1] = "Спаплюжені сатирами", [2] = "Нашестя демонів не відбувається на пустому місці — щось має дозволити злу закріпитися.\n\nЦе може бути слабкість духу, безглузде прагнення влади чи жага помсти. Коли нас охоплює біль, зло може скористатися нами — таке зло, як сатири.\n\nВони пов'язані з Палаючим Лезом і Тралл хоче, щоб їх перебили. Шукай їх на північному сході та повертайся до мене, коли розберешся з ними.", [3] = "Вбийте 7 скаженолютих пройдисвітів, 7 скаженолютих скверноклятів, 7 скаженолютих зрадників та 7 скаженолютих пеклокликів і поверніться до Такати Гостроклина в Спустошище.", [4] = "Один товариш-таурен попередив мене, що сатири — не зовсім ті, якими здаються. Він вважає, що в них є щось більше, що їхнє зло — це викривлення їхньої справжньої природи. Але я цього не помічав.\n\nЯ бачу лише як вони безжально вбивають слабких і оскверняють душі тих, хто звертається до темних сил.\n\nІ я буду знищувати їх, допоки воєвождь не накаже мені інше. До тих пір мій меч не знатиме милосердя.", [5] = "Ти добре {стать:потрудився:потрудилася}, {ім'я}. Ти {стать:проявив:проявила} свою честь і відданість.\n\nКоли ми покінчимо з нашими справами в Спустошищі, воєвождь неодмінно дізнається про те, що ти {стать:допоміг:допомогла} нам виконати його волю.\n\nДякую тобі.", ["en"] = "Befouled by Satyr", ["tasks"] = { ["Hatefury Betrayer"] = "скаженолютий зрадник", ["Hatefury Betrayer slain"] = "скаженолютий зрадник: убито", ["Hatefury Felsworn"] = "скаженолютий скверноклят", ["Hatefury Felsworn slain"] = "скаженолютий скверноклят: убито", ["Hatefury Hellcaller"] = "скаженолютий пеклоклик", ["Hatefury Hellcaller slain"] = "скаженолютий пеклоклик: убито", ["Hatefury Rogue"] = "скаженолютий пройдисвіт", ["Hatefury Rogue slain"] = "скаженолютий пройдисвіт: убито" } },
    [1435] = { [1] = "Спалення духів", [2] = "Смерть — єдиний вихід для цих жалюгідних створінь. Але смерті недостатньо, коли маєш справу з тими, хто віддався на поталу темряві.\n\nВізьми цей самоцвіт. Коли один з послідовників Палаючого Леза буде при смерті, активуй його. Закляття витягне зіпсованого духа з його жертви, залишивши по собі наповнений самоцвіт.\n\nПринеси мені ці самоцвіти, а я з ними розберуся.\n\nІди ж, і нехай тебе не наздожене смерть.", [3] = "Принесіть палаючий самоцвіт і 15 наповнених палаючих самоцвітів Мавріну Кісткощепу в Спустошище.", [4] = "Я намагався зробити закляття якомога простішим. Витягнути душу твоєї жертви з її вмираючого тіла має бути дитячою забавкою. Але не розраховуй, що магія самоцвіту сама вб'є твого ворога. Ти маєш використовувати самоцвіт лише тоді, коли твій ворог близький до смерті, інакше нічого не вийде.", [5] = "А, ти {стать:повернувся:повернулася} з перемогою. Це добре. Віддай мені самоцвіти, і я покладу їх в надійне місце....\n\nУ мене більше немає для тебе доручень, {клас:к}. Поговори з Такатою, коли відпочинеш. Можливо, у нього знайдуться інші завдання, або, можливо, він попросить тебе повернутися до Орґріммару, щоб повідомити Келдрану про наші успіхи у Спустошищі.", ["en"] = "The Burning of Spirits", ["tasks"] = { ["Burning Gem"] = "палаючий самоцвіт", ["Burning Gem (Provided)"] = "палаючий самоцвіт (видано)", ["Infused Burning Gem"] = "наповнений палаючий самоцвіт", ["Infused Burning Gem (Provided)"] = "наповнений палаючий самоцвіт (видано)" } },
    [1436] = { [1] = "Відносини з Альянсом", [2] = "Справи йдуть непогано, {ім'я}. Можливо, якщо ми продовжимо здобувати такі великі перемоги над демонами та їхніми поплічниками, воєвождь дозволить нам повернутися до наших домівок ще до наступної пори року.\n\nПовертайся до Келдрана і розкажи йому, чого нам вдалося досягти. Я впевнений, що він винагородить тебе. Його справа важлива для нього, і він пишатиметься тим, що воєвождь цінує його зусилля.", [3] = "Поговоріть з Келдраном в Орґріммарі.", [5] = "Тобі вдалося досягти успіху в Спустошищі, та ще й якого, {ім'я}. Дякую тобі.\n\nДякую за твої зусилля, за витрачений час і за розуміння моєї справи. Тралл бажає миру між Ордою та Альянсом, і, вживаючи заходів щодо покращення відносин до нас, ми запобіжимо новим конфліктам.\n\nЯ твій боржник.", ["en"] = "Alliance Relations" },
    [1444] = { [1] = "Повернення до Фел'зерула", [2] = "Пророк Джаммал'ан прирік мене до заслання з храму Атал'Гаккар. Раніше я вважав верховного жерця достойним лідером.\n\nАле його непохитна віра в пророцтво приведе до руйнування Атал'ай. Якщо це ще не сталося.\n\nКоли я висловив свою стурбованість, мене назвали невірним і вигнали з храму.\n\nАртефакти, які ти {стать:приніс:принесла} мені, нешкідливі. Але якщо Джаммал'ан знайшов необхідний для ритуалу виклику фетиш, то всьому світу загрожує смертельна небезпека.", [3] = "Поверніться до Фел'зерула в Камінард.", [5] = "Минуло досить багато часу відтоді, як ми розмовляли, {клас:к}. Сподіваюся, твоя подорож була успішною.\n\nЯкі знання ти {стать:отримав:отримала} від вигнанця Атал'ай у Внутрішніх землях?", ["en"] = "Return to Fel'Zerul" },
    [1473] = { [1] = "Створіння Порожнечі", [2] = "Схоже, що ти {стать:готовий:готова} навчитися виклику пустотника.\n\nЦе створіння було створене хаосом, який лежить за межами нашого світу, і якщо ти викличеш його, та не зможеш його контролювати, ти будеш {стать:розірваний:розірвана} на шматки.\n\nПерший пустотник був викликаний Еґаліном, і у його гримуарі описано, як це робиться.\n\nНа жаль, його викрав у нас агент Багряного Походу, який переховує його на своїй базі у вежі на заході. Принеси його мені, і я передам тобі знання.", [3] = "Отримайте гримуар Еґаліна та принесіть його Карендіну Галґару у храм Проклятих.", [4] = "Еґалін був моїм наставником, він навчав мене. Він з легкістю міг керувати пустотником, якого викликав.\n\nКоли настала моя черга підкорити це створіння, я був занадто самовпевнений. Не грайся з силою, якою володієш, {ім'я}, вона може пожерти навіть {стать:найсильнішого:найсильнішу}.", [5] = "Це чудово. Мабуть, Перрін навіть не здогадувався про справжню силу цієї старезної книги, яку він вкрав у нас.\n\nВона більше не вислизне з наших рук. Подивись, {ім'я}, на структуру заклинання та на те, як потрібно спрямовувати свою силу.", ["en"] = "Creature of the Void", ["tasks"] = { ["Egalin's Grimoire"] = "гримуар Еґаліна", ["Egalin's Grimoire (Provided)"] = "гримуар Еґаліна (видано)" } },
    [1476] = { [1] = "Чисті серця", [2] = "Щоб приманити суккуба, потрібні чисті серця. Та чи ще існують такі непорочні смертні?\n\nМені знадобилося багато часу на пошуки, але з кількох історій мені вдалося знайти двох людей, що підійдуть.\n\nПершим є Далін Файноков, який присвятив своє життя допомозі біженцям Лордерона, від яких відмовилися їхні родичі, біля стіни Сивогрива.\n\nІнша — Корма Віллард, жінка, яка залишається вірною своєму втраченому коханню і блукає по Заболоттю, шукаючи знаків від неї.\n\nПринеси їхні серця Карендіну. Але спочатку дозволь мені показати тобі твоїх жертв.", [3] = "Принесіть серця Даліна Файнокова та Корми Віллард до Карендіна Галґара у храм Проклятих.", [4] = "Я приємно здивований швидкістю твого прогресу, {ім'я}. Принеси мені серця і ти знову вразиш мене.", [5] = "Здається, серце порядної людини схоже на будь-яке інше, чи не так?\n\nМожливо, ми маємо дещо... інші... погляди на цю тему. Ці підійдуть. Я не сумніваюся, що сукуб піддасться їхній чистоті.", ["en"] = "Hearts of the Pure", ["tasks"] = { ["Comar's Heart"] = "серце Комара", ["Comar's Heart (Provided)"] = "серце Комара (видано)", ["Dalin's Heart"] = "серце Даліна", ["Dalin's Heart (Provided)"] = "серце Даліна (видано)" } },
    [1480] = { [1] = "Спотворювач", [2] = "Ця обдерта шкіра пахне гниллю, але вона напрочуд гнучка, хоча на перший погляд здається сухою і крихкою.\n\nРозгорнувши її, ви можете чітко побачити червоні письмена якоюсь незрозумілою мовою. В нижній частині шкіри дуже чіткий символ, схожий на підпис.\n\nМожливо, Маврін міг би розповісти більше про це?", [3] = "Принесіть обдерту шкіру демона Мавріну Кісткощепу в Спустошище.", [4] = "Палаюче Лезо починає усвідомлювати, наскільки вони слабкі. Їхня магія жалюгідна, а їхня сила слабка.\n\nЄдина їхня сила походить від тих, кому вони служать, а не від розуміння справжньої сили та знань законів магії.", [5] = "Цікаво, ці руни дійсно є якоюсь мовою, {ім'я}, старою мовою. Віддалено вона здається схожою на мову ередан, але відмінності, однозначно, є. Якщо я не помиляюся, це якийсь контракт.... Так, цей символ — підпис демона: лорд Азреток.", ["en"] = "The Corrupter", ["tasks"] = { ["Flayed Demon Skin"] = "обдерта шкіра демона", ["Flayed Demon Skin (Provided)"] = "обдерта шкіра демона (видано)" } },
    [1481] = { [1] = "Спотворювач", [2] = "Думаю, я зможу знайти цього лорда демонів, якщо матиму певні реагенти.\n\nЯкщо він справді такий могутній, як я думаю, мені знадобляться предмети, зібрані зі смертоносних істот. Але ти борешся в ім'я воєвождя, тому я впевнений, що ти виконаєш моє завдання.\n\nНасамперед мені доведеться зламати всі його захисні бар'єри проти споглядачів. Для цього мені знадобиться скальп сатира, але не звичайного. Скальп повинен належати скаженолютому тінелову.\n\nШукай їх серед стародавніх руїн на північному сході Спустошища.", [3] = "Принесіть скальп тінелова Мавріну Кісткощепу в Спустошище.", [4] = "Знайди саме скальп тінелова, {клас:к}. Використання неправильних реактивів може призвести до смерті. Лорд демонів може мати запасні заклинання, що вбивають непрошених споглядачів.\n\nДосить з мене страждань.", [5] = "Тінелови не змогли вбити тебе, {клас:к}. Дивовижно... навіть дуже дивовижно.\n\nЦей скальп ідеально підійде для мого заклинання. Поки тебе не було, я зібрав інші реагенти, необхідні для заклинання.\n\nВсе майже готово. Мені потрібно лише сфокусуватись на чомусь для заклинання. Потрібно щось, що спроєктує образ лорда демонів і його місцеперебування.", ["en"] = "The Corrupter", ["tasks"] = { ["Shadowstalker Scalp"] = "скальп тінелова", ["Shadowstalker Scalp (Provided)"] = "скальп тінелова (видано)" } },
    [1482] = { [1] = "Спотворювач", [2] = "Кристал оракула чудово б підійшов нам. Їх створюють наги для своїх оракулів.\n\nНа північний захід звідси, вздовж узбережжя, знаходиться величезний кораловий риф, який наги зробили своїм домом, бо він близько до берега. Там ти зможеш знайти оракулів. Слизькорізи смертельно небезпечні, вони не будуть раді твоєму вторгненню, тому будь {стать:обережним:обережною} та поквапся.\n\nКоли повернешся, ми спробуємо відшукати цього лорда демонів Азретока.", [3] = "Принесіть кристал оракула Мавріну Кісткощепу в Спустошище.", [4] = "Я готовий використати кристал оракула, {клас:к}. Якщо ми знайдемо й знищимо цього лорда Азретока, воєвождь буде дуже вдячний нам. Ми маємо працювати разом і працювати швидко, щоб досягти мети й завоювати прихильність воєвождя.", [5] = "Дорогоцінний кристал оракула... бездоганний... прекрасний.\n\nМи розпочнемо негайно. Наша першочергова задача — знайти цього лорда демонів, а потім потрібно сконцентруватись на його знищенні.\n\nЗроби крок назад, {клас:к}, подивимося, що це за демон і де він знаходиться.", ["en"] = "The Corrupter", ["tasks"] = { ["Oracle Crystal"] = "кристал оракула", ["Oracle Crystal (Provided)"] = "кристал оракула (видано)" } },
    [1484] = { [1] = "Спотворювач", [2] = "Це створіння набагато небезпечніше, ніж я думав. Не сумніваюся, Таката не вірить, що я зможу його здолати, для нього буде образою, якщо я не проінформую його про те, що сталося.\n\nПоговори з Гостроклином, скажи йому, що ти {стать:готовий:готова} убити демона, якщо він дозволить, але не тисни на нього. Нехай думає, що це його власне рішення.", [3] = "Поговоріть з Такатою Гостроклином в Спустошищі.", [5] = "Я був свідком того, що щойно сталося між Мавріном і лордом демонів. Здається, ця істота навіть у вигляді привида має більшу силу, ніж мій супутник чорнокнижник. Цікаво, чи зможе він перемогти цього монстра? Для воєвождя було б краще, якби я сам пішов туди. Але я зганьблю свій клан, якщо залишу свої обов'язки тут та піду боротися зі злом заради слави.", ["en"] = "The Corrupter" },
    [1488] = { [1] = "Спотворювач", [2] = "Хоч я нічого й не знаю про цього лорда Азретока, я згоден з Мавріном, що його треба зупинити; особливо якщо він намагається підкорити Палаюче Лезо для досягнення своїх цілей.\n\nТвоє прагнення служити вождю вже не потребує доказів, тому я довіряю тобі зібрати команду, щоб вбити лорда демонів і його слугу-чорнокнижника.\n\nКоли будеш {стать:готовий:готова}, прямуй на південь і повертайся тільки тоді, коли знищиш загрозу.", [3] = "Вбийте лорда Азретока і Жуґара Ґрім'рода та поверніться до Такати Гостроклина в Спустошище.", [4] = "Слава Орді й смерть нашим ворогам, {ім'я}!\n\nДемони в Спустошищі стали небезпечнішими, ніж будь-коли раніше. Я втрачаю надію, що зможу коли-небудь повернутися до воєвождя, оскільки з'являється все більше і більше мерзенних створінь.\n\nІноді мені хочеться мати справу тільки з кентаврами.", [5] = "Це величезна перемога для всіх нас, {ім'я}. Всі ми радіємо твоєму успіху. Тепер я впевнений, що наше майбутнє тут не таке похмуре, як я колись думав.\n\nДемонів буде знищено, Палаюче Лезо зазнає поразки та одного дня у нас знову буде місце, яке ми зможемо сміливо називати домом.", ["en"] = "The Corrupter", ["tasks"] = { ["Jugkar Grim'rod"] = "Жуґар Ґрім'род", ["Jugkar Grim'rod slain"] = "Жуґар Ґрім'род: убито", ["Lord Azrethoc"] = "лорд Азреток", ["Lord Azrethoc slain"] = "лорд Азреток: убито" } },
    [1489] = { [1] = "Гамуул Рунний Тотем", [2] = "В панцирах, що ти мені {стать:приніс:принесла}, я відчуваю порчу, яку ще ніколи не бачив. Я впевнений, що вода оазису є тому причиною, і я вже відчуваю загрозу, яку вона несе цим землям. Це схоже на те, як ніби земля спить і не може прокинутися.\n\nПлачучі печери повинні бути джерелом порчі. Але перед тим, як ти туди підеш, поговори з Гамуулом Рунним Тотемом, старшим друїдом. Я надіслав йому звістку про події в Степах. Він мудрий, і може запропонувати тобі пораду.\n\nТи знайдеш його в Громовому Бескиді, на Верхів'ї Старійшин.", [3] = "Поговоріть з Гамуулом Рунним Тотемом.", [5] = "Вітаю тебе, {ім'я}. Ласкаво прошу і пропоную тобі зібрати всі свої сили. Завдання, яке ми доручимо тобі, буде вкрай нелегким.", ["en"] = "Hamuul Runetotem" },
    [1490] = { [1] = "Нара Дика Грива", [2] = "Я перенісся у світ сновидінь і побачив орден друїдів, що мешкає в Плачучих печерах. Колись їх вела благородна мета, але нині вони зійшли зі свого шляху. Тепер вони — слуги зла, що просочується через Степи.\n\nЯ старий і сили мої вже не ті, тож я не зміг пробути в сні довше, щоб дізнатись більше про цих проклятих друїдів. Та Нара молода і міцна духом. Вона не покинула сон зі мною і залишилась там на довший час.\n\nПоговори з Нарою. Вона он в тому шатрі.", [3] = "Поговоріть з Нарою Дикою Гривою.", [5] = "Так, це правда. Я знаю дещо про друїдів з Плачучих печер і бачила їх спотворені, вкриті лускою обличчя. І я знаю, що вони затіяли.\n\nТи маєш зупинити їх, {ім'я}.", ["en"] = "Nara Wildmane" },
    [1492] = { [1] = "Завідувач причалу Запаморок", [2] = "Мені потрібно відправити ящик з зіллям, реактивами та іншими речами моїм партнерам зі Старого Світу. Я не маю часу, щоб самотужки нести його до причалу в Брашпиль, а останній караван вже відбув.\n\nЯкщо можеш — будь ласка, віднеси це завідувачеві причалу Запамороку. Він подбає про те, щоб це доставили наступним човном до Бухти Чорноводдя.", [3] = "Віднесіть запечатаний ящик завідувачеві причалу Запамороку в Брашпиль.", [4] = "Бажаєш відплисти на наступному кораблі чи хочеш відправити щось на інший край світу?", [5] = "Невеликий ящик. Так, думаю, для нього знайдеться місце на борту корабля. Він відпливе з наступним припливом, це досить скоро? Чудово. Дозволь мені тільки записати це в мій гросбух.\n\nНу ось, все готово! Гарного дня, {клас:к}.", ["en"] = "Wharfmaster Dizzywig", ["tasks"] = { ["Secure Crate"] = "запечатаний ящик", ["Secure Crate (Provided)"] = "запечатаний ящик (видано)" } },
    [1501] = { [1] = "Створіння Порожнечі", [2] = "Так мало залишилось чорнокнижників... Ми багато ризикуємо, але наші ризики виправдані. Якщо ти хочеш бути {стать:корисним:корисною} для Орди та воєвождя, тобі потрібно дуже швидко досягти успіхів у своїх здібностях.\n\nНастав час вивчити нове заклинання виклику.\n\nТа спочатку тобі потрібно відновити скрижаль Верґи, яку викрали чорнокнижники Палаючого Леза і яка зараз зберігається в їхньому лігві в Скелі Черепа, що на сході від міста. З цією скрижаллю я покажу тобі руни, необхідні для виклику пустотника.", [3] = "Принесіть скрижаль Верґи Ґан'рулу Кривавому Оку в Орґріммар.", [4] = "Скрижаль Верґи у тебе, {ім'я}? Якщо ні, то я не хочу розмовляти з тобою, доки ти її не знайдеш.", [5] = "Чудово. Сподіваюся, ти {стать:завдав:завдала} Палаючому Лезу багато втрат, коли {стать:забирав:забирала} її.\n\nВони були кісткою в горлі для воєвождя та великою загрозою для чорнокнижників в цілому.", ["en"] = "Creature of the Void", ["tasks"] = { ["Tablet of Verga"] = "скрижаль Верґи", ["Tablet of Verga (Provided)"] = "скрижаль Верґи (видано)" } },
    [1523] = { [1] = "Поклик вогню", [2] = "Минуло багато часу відтоді, як ти {стать:проходив:проходила} своє останнє випробування, {ім'я}. До цього часу ти {стать:був старанним:була старанною} у своєму навчанні, але настав час тобі пізнати більше. Настав час тобі дізнатися про руйнування... і хаос. Ти пізнаєш елемент вогню, якщо будеш {стать:готовий:готова} заплатити за це.\n\nЗнайди Кранала Фісса у Степах. Він проживає у маленькій хатині на півночі від Перехрестя. Але май на увазі: якщо ти {стать:потрапив:потрапила} до земель нічних ельфів, ти {стать:зайшов:зайшла} надто далеко.", [3] = "Знайдіть Кранала Фісса у Степах.", [5] = "Хм... То тебе Заніс прислав, так?\n\nТоді добре, Занісу завжди можна було довіряти, тож це має означити, що ти {стать:готовий:готова} спробувати наступну сапту — сапту вогню.\n\nЯ вже бачу це у твоїх очах, палання, жадання. Ти вже {стать:відчув:відчула} силу і тепер {стать:готовий:готова} до більшого. Терпіння, {ім'я}. Пам'ятай, чого навчила тебе земля. Сила й руйнування даються легко, але ти все одно {стать:повинен:повинна} знати, коли зупинитися.", ["en"] = "Call of Fire" },
    [1524] = { [1] = "Поклик вогню", [2] = "Ти вже достатньо {стать:могутній:могутня}, щоб володіти тотемом вогню, але це не означає, що ти {стать:готовий:готова} до цього.\n\nУздовж Південнолютної річки у Дуротарі, не доходячи до Великого моря, лежить прихована стежка до одної з найвищих вершин цієї землі. Знайди шлях на самий верх, де ти побачиш один з наших священних вівтарів, про який піклується Телф Джуулам — вівтар дрімаючого полум'я.\n\nВіднеси йому цей смолоскип. Це знак того, що ти намагаєшся приборкати вогонь. Запали його у жаровні коло вівтаря та принеси мені. А я подбаю про те, щоб ти {стать:отримав:отримала} тотем вогню.", [3] = "Принесіть смолоскип дрімаючого полум'я Телфу Джууламу в Дуротар.", [4] = "Вітаю, {ім'я}. Ти {стать:прийшов:прийшла} до вівтаря дрімаючого полум'я. Тільки ті, хто достатньо володіють шаманським мистецтвом зможуть пізнати таємниці та силу цього місця. Шкода, що тобі довелося подолали весь цей шлях тільки для того, щоб повернутися назад. Подорож сюди аж ніяк не безпечна. Але я — хранитель вівтаря, і я не можу дозволити блукати тут аби кому.", [5] = "Ах, я помилився, {ім'я}. Перепрошую. Я не усвідомлював, що ти володієш смолоскипом. Приємно познайомитися.\n\nБагато шукачів пригод потрапляли сюди у пошуках загублених скарбів або містичних істот, тільки щоб розчаровано піти геть від, на перший погляд, порожнього вівтаря. Але ми знаємо правду, еге ж, {ім'я}?\n\nЦей вівтар зберігає велику таємницю, яка недосяжна для звичайних членів Орди. Але для нас він священний.", ["en"] = "Call of Fire", ["tasks"] = { ["Torch of the Dormant Flame"] = "смолоскип дрімаючого полум'я", ["Torch of the Dormant Flame (Provided)"] = "смолоскип дрімаючого полум'я (видано)" } },
    [1532] = { [1] = "Поклик повітря", [2] = "Вітри Калімдору линуть тобі назустріч, і незабаром тебе буде зараховано до числа наших наймогутніших {стать:братів:сестер}. Я пишаюся тим, що ти вже стільки {стать:досяг:досягла} і бачу, що на тебе чекає велике майбутнє.\n\nСтихією повітря важко керувати, але я вірю, що твої навички подолають будь-які перешкоди, що постануть перед тобою.\n\nПрямуй на самий південь Степів та увійди у Тисячу Шипів. Саме там, далеко на сході, ти знайдеш Прату Пантрувачку Хмар. Вона продовжить твоє навчання.", [3] = "Знайдіть Прату Пантрувачку Хмар у Тисячі Шипів.", [5] = "Наразі я дам тобі те, що тобі потрібно для зосередження своїх заклинань та виклику духів повітря. Візьми цей тотем, а коли будеш {стать:готовий:готова} продовжити навчання — приходь знову.", ["en"] = "Call of Air" },
    [1656] = { [1] = "Незавершене завдання", [2] = "{Ім'я}, будь ласка, я прошу тебе, ти можеш мені допомогти? Я ще не закінчила своє завдання тут на Плато — лишень пройшла половину Обряду Сили — а мій батько вже просить мене донести ці шкури у таверну в Кривавому Копиті.\n\nЯ ще не достатньо відпочила, щоб пройти і обряд, і виконати його доручення. Як ти дивишся на те, щоб зробити це замість мене?\n\nТаверна — приємне та чудове місце для відпочинку після довгих мандрівок. Я впевнена, ти погодишся зі мною, як тільки прийдеш туди.", [3] = "Принесіть зв'язку хутра корчмареві Кауту в селище Криваве Копито.", [4] = "Так, {стать:юначе:юначка}? Що Каут може зробити для тебе?\n\nДля одних подорож з Плато видається жахливим тягарем, для інших — приємним дозвіллям. Цікаво, яка вона для тебе?", [5] = "Ах, я чекав на ці хутра. Дякую.\n\nТи {стать:впорався:впоралась} швидше, ніж я очікував. Вони стануть хорошими ковдрами для тих, хто захоче тут переночувати.\n\nБудь ласка, залишайся стільки, скільки забажаєш. Моя таверна завжди відчинена, і ми раді кожному з нашого народу. І не недооцінюй хороший нічний відпочинок. Він може сильно допомогти протягом твоїх мандрівок.", ["en"] = "A Task Unfinished", ["tasks"] = { ["Bundle of Furs"] = "зв'язка хутра", ["Bundle of Furs (Provided)"] = "зв'язка хутра (видано)" } },
    [172] = { [1] = "Дитячий тиждень", [2] = "Ти бажаєш допомогти нам у притулку для сиріт? Нехай благословлять тебе духи, твоя допомога під час Дитячого тижня буде дуже важливою.\n\nВізьми цей свисток. Ти зможеш використовувати його лише короткий період часу — зазвичай до кінця Дитячого тижня. Свиснувши в нього, ти зможеш спілкуватися з дитиною, про яку {стать:погодився:погодилася} піклуватися. Щоб дитина пішла, використай свисток ще раз.\n\nПрошу, {ім'я} — скористайся свистком і зустрінься з твоїм підопічним! Я впевнена, що дитина буде надзвичайно рада познайомитися з тобою.", [3] = "Використовуйте свисток орка-сироти, щоб поговорити з дитиною, за якою ви будете доглядати протягом Дитячого тижня.", [5] = "Заґ-заґ! Мене звати Ґрант. А ти тепер піклуватимешся про мене? Ти {стать:шукач:шукачка} пригод, зовсім як були мої мама з татом... Моя опікунка каже, що вони загинули з честю в бою. Я дуже радий познайомитися з тобою!\n\nСподіваюся, ми зможемо багато разом побачити. Мені стільки всього хочеться зробити, а опікунка сказала, що ти весь тиждень будеш для мене, як {стать:старший брат:старша сестра}. Гайда до пригод!", ["en"] = "Children's Week", ["tasks"] = { ["Orcish Orphan Whistle"] = "свисток орка-сироти" } },
    [1821] = { [1] = "Реліквії Аґамандів", [2] = "Я служив Аґамандам при житті й через них я його втратив. А тепер вони заслужено стали безмозкими слугами Короля-ліча.\n\nМені потрібно позбавити їх залишків гордості. Спускайся в їх сімейний склеп і забери їх родові реліквії: меч, сокиру, кинджал і булаву. Принеси їх мені!\n\nСімейний склеп Аґамандів знаходиться на північ від млинів Аґамандів. Його оберігає бродяча Скара і мертві Аґаманди.", [3] = "Принесіть Коулмену Фартингу родовий меч Аґамандів, родову сокиру Аґамандів, родовий кинджал Аґамандів та родову булаву Аґамандів.", [4] = "Ти {стать:приніс:принесла} реліквії, {ім'я}?", [5] = "Ага! Ось і вони! Тепер залишки честі і пам'яті про Аґамандів полишать ці землі. Віднині їх рід знищено!", ["en"] = "Agamand Heirlooms", ["tasks"] = { ["Agamand Family Axe"] = "родова сокира Аґамандів", ["Agamand Family Axe (Provided)"] = "родова сокира Аґамандів (видано)", ["Agamand Family Dagger"] = "родовий кинджал Аґамандів", ["Agamand Family Dagger (Provided)"] = "родовий кинджал Аґамандів (видано)", ["Agamand Family Mace"] = "родова булава Аґамандів", ["Agamand Family Mace (Provided)"] = "родова булава Аґамандів (видано)", ["Agamand Family Sword"] = "родовий меч Аґамандів", ["Agamand Family Sword (Provided)"] = "родовий меч Аґамандів (видано)" } },
    [1822] = { [1] = "Родова зброя", [5] = "Я заберу собі три реліквії на пам'ять про мій біль і втрату. Але прошу, {ім'я}, візьми собі одну з них.\n\nХай вона служить тобі достойніше, ніж минулим проклятим власникам.", ["en"] = "Heirloom Weapon" },
    [1858] = { [1] = "Розтрощена Рука", [2] = "Я лишаю відкриття ранця Тазана на тебе — принеси мені його вміст. Замикальний механізм складний, тому буде простіше відкрити його, якщо у тебе буде ключ.\n\nНа трупі Тазана ключа не було? Значить, він його комусь віддав... Ах, ну так, звісно. У нього був помічник, Ґамон. Він пияка, тож шукай його у таверні. Можливо, тобі вдасться тихо поцупити в нього ключ.", [3] = "Викрадіть ключ Тазана та скористайтеся ним, щоб відкрити його ранець. Принесіть вміст ранця Терзоку в Розколину Тіні, що в Орґріммарі.", [4] = "Хіба не прикро тримати в руках те, що тобі потрібно, та не мати можливості його дістати?", [5] = "А ось це вже цікаво. Ти не тільки {стать:довів:довела} свою цінність, ти {стать;зробив:зробила} навіть більше, {ім'я}. Я вражений. Можеш вважати себе новим членом Розтрощеної Руки. Візьми це — думаю, воно тобі знадобиться.", ["en"] = "The Shattered Hand", ["tasks"] = { ["Tazan's Logbook"] = "щоденник Тазана", ["Tazan's Logbook (Provided)"] = "щоденник Тазана (видано)" } },
    [1859] = { [1] = "Терзок", [2] = "Розмовляй тихіше, {ім'я}. Так, я знаю твоє ім'я. Мені наказали стежити за {раса:о}, {стать:схожим:схожою} на тебе.\n\nЯ чув, що ти можеш постояти за себе у відкритому бою та не проти, час від часу, вдатися до хитрощів.\n\nЧи не так?\n\nТак чи інакше, ти маєш побачитися з Терзоком в Орґріммарі. У нього є для тебе пропозиція.", [3] = "Поговоріть з Терзоком в Розколині Тіні в Орґріммарі.", [5] = "Дуже добре, я радий що Каплак зумів тебе перехопити.\n\nУ нас є багато речей, про які варто поговорити. Насамперед — про твоє майбутнє в Руці.", ["en"] = "Therzok" },
    [1885] = { [1] = "Меннет Каркад", [2] = "{ім'я}? Не зовсім те, що я очікував, враховуючи, що сам Каркад зацікавився тобою. Та зовнішність може бути оманливою, чи не так?\n\nУ будь-якому разі, тобі варто зустрітися з ним якомога швидше. Краще тобі не знати, що сталося з тими дурнями, що вирішили проігнорувати його виклик.", [3] = "Поговоріть з Меннетом Каркадом у кварталі Пройдисвітів Підмістя.", [5] = "Гм. Немає сумнівів, що ти {стать:прийшов:прийшла} сюди за першим же моїм покликом, так? Звісно. Я б не очікував меншого від {стать:перспективного смертолова:перспективної смертоловки}.", ["en"] = "Mennet Carkad" },
    [1886] = { [1] = "Смертолови", [2] = "Якщо ти хочеш приєднатися до Смертоловів, елітної гвардії лорда Варіматраса, тобі доведеться спершу довести, що ти {стать:вартий:варта} цього.\n\nНе буду брехати тобі, {ім'я}, це завдання може коштувати тобі життя.\n\nМені потрібна допомога в кількох справах. Для початку, мені потрібні особисті речі Астора Хадрена, гінця, який подорожує між Срібнохвоєм та Підмістям. Як ти це зробиш — вирішувати тобі.\n\nПоки що це все, що тобі слід знати. Впораєшся — я розповім тобі більше.", [3] = "Отримайте рекомендаційний лист Астора та поверніться до Меннета Каркада у квартал Пройдисвітів.", [4] = "Є успіхи?", [5] = "Молодець, {ім'я}. Ти {стать:пройшов:пройшла} першу частину випробовування. Сподіваюся, Андрон нічого не дізнався про твої, і ти зможеш переконати його, що ти і є той гінець, на якого він чекає.", ["en"] = "The Deathstalkers", ["tasks"] = { ["Astor's Letter of Introduction"] = "рекомендаційний лист Астора", ["Astor's Letter of Introduction (Provided)"] = "рекомендаційний лист Астора (видано)" } },
    [1898] = { [1] = "Смертолови", [2] = "Рекомендаційного листа має бути достатньо, щоб переконати Андрона, що ти саме той посланець, на якого він чекає. Я зустрічав Андрона раніше, він не настільки розумний, щоб щось запідозрити.\n\nЛорд Варіматрас підозрює, що Андрон таємно допомагає іншій групі. Він хоче знати що це за організація, і вимагає доказів.\n\nЯ хочу, щоб ти {стать:поговорив:поговорила} з Андроном та {стать:отримав:отримала} цю інформацію. Ти знайдеш його в його крамниці біля Апотекарія.", [3] = "Поговоріть з Андроном Ґантом в Підмісті.", [4] = "Вітаю. Чим я можу допомогти?", [5] = "А, так, я чекав на тебе. Гадаю, наші спільні знайомі задоволені інформацією, яку я надав?\n\nТа певно немає сенсу питати тебе, навряд чи тебе обтяжують зайвими знаннями. Навіщо довіряти гінцеві такі таємниці, еге ж?", ["en"] = "The Deathstalkers", ["tasks"] = { ["Astor's Letter of Introduction"] = "рекомендаційний лист Астора", ["Astor's Letter of Introduction (Provided)"] = "рекомендаційний лист Астора (видано)" } },
    [1899] = { [1] = "Смертолови", [2] = "На книжковій полиці позаду мене ти знайдеш гросбух з інформацією, яку шукають ваші роботодавці. Достав її з усіма моїми вітаннями, і скажи їм, що якщо вони захочуть продовжити співпрацю, я волів би мати справу з тобою.", [3] = "Принесіть гросбух Андрона Меннету Каркаду в квартал Пройдисвітів Підмістя.", [4] = "Є успіхи, {ім'я}?", [5] = "Що ж, це явно більше, ніж я очікував отримати від Андрона. Дай мені трохи часу, щоб прочитати її перед тим, як я відправлю тебе на твоє наступне завдання.", ["en"] = "The Deathstalkers", ["tasks"] = { ["Andron's Ledger"] = "гросбух Андрона", ["Andron's Ledger (Provided)"] = "гросбух Андрона (видано)" } },
    [1918] = { [1] = "Забруднений елементаль", [2] = "Вбивши елементаля, ви отримали водяну кулю, що яскраво сяє. Вміст кулі виглядає, м'яко кажучи, огидно. Можна з упевненістю припустити, що джерело забруднення озера Містраль присутнє й в цій кулі.\n\nНе зовсім зрозуміло, хто може бути зацікавлений у такій знахідці. Можливо, Масток Хитрошип з застави при Тріснутому Дереві, який відправив вас сюди, щось знає.", [3] = "Принесіть забруднену водяну кулю Мастоку Хитрошипу на заставу при Тріснутому Дереві, що в Ясенедолі.", [4] = "Еге, чого хочеш?", [5] = "Ти {стать:знайшов:знайшла} огидну водяну бульбашку і {стать:приніс:принесла} її мені? Я що, схожий на Служителя Землі?\n\nДо речі, це непогана ідея. Може, тобі й справді варто звернутися до Служителів Землі. Якщо це раз і назавжди прояснить ситуацію з озером, я згодний.\n\nТи ж знаєш, хто такі Служителі Землі, {ім'я}?", ["en"] = "The Befouled Element", ["tasks"] = { ["Befouled Water Globe"] = "забруднена водяна куля", ["Befouled Water Globe (Provided)"] = "забруднена водяна куля (видано)" } },
    [1963] = { [1] = "Розтрощена Рука", [2] = "Воєвождь дуже витончений у своїх методах. Він боїться вивільнити всю силу Орди. Колись ми були сильнішими, могутніми завойовниками. Плем'я має повернути цю гордість, і Розтрощена Рука зробить це.\n\nМи черпаємо нашу силу з тіні та б'ємо по відкритих місцях, таємно підстерігаючи наших ворогів. Завдання яке ти маєш виконати для мене — довести свою цінність.\n\nТроль Тазан торгує з піратами біля Брашпиля. Він володіє інформацією, яка мені потрібна. Вбий його та принеси мені його ранець.", [3] = "Вбийте Тазана та принесіть його ранець Терзоку в Розколину Тіні, що в Орґріммарі.", [4] = "Тільки дурень вважає, що ривок з сокирою небезпечніший за кинджал у спину.", [5] = "Гм, я радий, що Тазан більше не з нами, але від замкнутого ранця немає ніякої користі. Нам потрібна інформація, яка захована всередині.\n\nОсь і друге завдання для {стать:того:тої}, хто хоче приєднатися до Розтрощеної Руки.", ["en"] = "The Shattered Hand", ["tasks"] = { ["Tazan's Satchel"] = "ранець Тазана", ["Tazan's Satchel (Provided)"] = "ранець Тазана (видано)" } },
    [1978] = { [1] = "Смертолови", [2] = "Синдикат? Ніколи б не подумав. Низько ж впали лорди Альтераку за роки, що минули з часу їхньої зради.\n\nЛорд Варіматрас із задоволенням послухає про це, і оскільки ти {стать:взяв:взяла} активну участь у цьому відкритті — ти й розповіси йому все.\n\nЙой. Як я міг забути?\n\nЛаскаво просимо до Смертоловів.", [3] = "Доставте гросбух Андрона Варіматрасу в зал Темної Леді в Підмісті.", [4] = "Так?", [5] = "Хм, це цікаво. Смертолови чудово виконали свій обов'язок.\n\nНаскільки я знаю, ти також заслуговуєш на похвалу за свою роботу. Сподіваюся, це стане для тебе звичною справою, {ім'я}, моїм Смертоловам завжди потрібні вправні руки.", ["en"] = "The Deathstalkers", ["tasks"] = { ["Andron's Ledger"] = "гросбух Андрона", ["Andron's Ledger (Provided)"] = "гросбух Андрона (видано)" } },
    [1998] = { [1] = "Фенвік Татрос", [2] = "Лорд Варіматрас тільки що надіслав мені звістку про небезпеку, що загрожує відреченим, з якою слід негайно розібратися. Його ім'я — Фенвік Татрос, і лорд Варіматрас вважає, що він є лідером невмерлих, що пустили своє коріння в Срібнохвойному пралісі.\n\nЯ негайно згадав про тебе, {ім'я}. Я довіряю твоїм здібностям і впевнений, що ти виконаєш це доручення бездоганно.\n\nОстанній звіт Смертоловів зі Срібнохвою свідчить, що Тантроса бачили біля закинутої пристані на озері Лордамер.", [3] = "Вбийте Фенвіка Татроса та принесіть його голову Меннету Каркаду у квартал Пройдисвітів Підмістя.", [4] = "Я цілком покладаюся на тебе. Виконай доручення лорда Варіматраса.", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Мені здається, що ти {стать:зробив:зробила} багато корисного для Смертоловів, тим самим довівши свою цінність. Схоже, що настав час продовжити твоє навчання тіньового мистецтва.", ["en"] = "Fenwick Thatros", ["tasks"] = { ["Fenwick's Head"] = "голова Фенвіка", ["Fenwick's Head (Provided)"] = "голова Фенвіка (видано)" } },
    [1999] = { [1] = "Професійні інструменти", [2] = "Чаклуни Кірін-Тору в Бурштиновому Млині зберігають важливі документи, що стосуються поточних справ у Даларані. Ми це дізналися від одного з наших в'язнів. Лорд Варіматрас доручив Смертоловам повернути ці документи.\n\nЧесть виконати це завдання випала тобі, {ім'я}. Тобі знадобиться деяке спорядження та вміння злому замків. Поговори з Естель Ґендрі, нашою екіпірувальницею, і попроси у неї набір інструментів, перш ніж вирушати в дорогу.", [3] = "Знайдіть звіт про ситуацію в Даларані та віддайте його Меннету Каркаду у кварталі Пройдисвітів Підмістя.", [4] = "Ти {стать:знайшов:знайшла} документи, {ім'я}?", [5] = "Дуже добре, {ім'я}! Тобі вдалося освоїти мистецтво злому, і навіть швидше, ніж я очікував.\n\nЯ бачу, що не помилився, довірившись тобі. Повір мені, {стать:стать:хлопче:дівчино}, ти далеко підеш у цій справі.", ["en"] = "Tools of the Trade", ["tasks"] = { ["Dalaran Status Report"] = "звіт про ситуацію в Даларані", ["Dalaran Status Report (Provided)"] = "звіт про ситуацію в Даларані (видано)" } },
    [2] = { [1] = "Кіготь Гостропазура", [2] = "Могутнього Гостропазура вбито, а кіготь гіпогрифа — свідоцтво вашої перемоги. Сенані Грозове Серце на заставі при Тріснутому Дереві буде зацікавлена в цьому трофеї як доказі вашої звитяги.", [3] = "Принесіть кіготь Гостропазура до Сенані Грозове Серце на заставу при Тріснутому Дереві, що в Ясенедолі.", [4] = "Так, {стать:могутній:могутня} {клас:к}, я відчула твоє прибуття. Чи є у тебе інші вісті щодо твого полювання?", [5] = "Я вражена, {ім'я:к}... кіготь Гостропазура — нелегкий трофей. Ти робиш успіхи в Ясенедільському полюванні!\n\nГостропазур давно вже лякав наймитів з лісозаготівельних таборів, коли вони подорожували сюди, в заставу при Тріснутому Дереві. Коли вони дізнаються, що ти {стать:знищив:знищила} звіра, чимало пісень про твою хоробрість буде чутно біля вечірніх вогнищ скрізь у Ясенедолі!", ["en"] = "Sharptalon's Claw", ["tasks"] = { ["Sharptalon's Claw"] = "кіготь Гостропазура", ["Sharptalon's Claw (Provided)"] = "кіготь Гостропазура (видано)" } },
    [2000] = { [1] = "Рокар Тінелезо", [2] = "Забагато вільного часу для тебе, {ім'я}. Настав час тобі більше дізнатися про нашу справу. Буквально минулої ночі п'ятьох наших знайшли мертвими в одній з тріщин в Орґріммарі, майже без зачіпок. Є ті, хто протистоїть нам, використовуючи наші власні методи проти нас.\n\nТож я вирішив, що тобі слід навчитися мистецтву відмикання замків.\n\nНа жаль, це майстерність, до якої мої руки не дуже пристосовані. Тобі слід знайти Рокара, який живе в пагорбах поблизу Дуротара. Навіть у похилому віці, я підозрюю, що він досі має до цього хист.", ["en"] = "Rokar Bladeshadow" },
    [216] = { [1] = "Між каменем та Колючохутрими", [2] = "Хутропузи з клану Колючохутрих загрожують нашій експансії! Селище Колючохутрих на схід звідси блокує шлях між нами та заставою при Тріснутому Дереві. Це шлях в обхід села Астранаар. Без нього ми подаруємо Альянсу зайвий шанс до розширення.\n\n{ім'я}, ми не повинні допустити... розриву шляху!\n\nЙди до селища Колючохутрих і проріди ряди хутропузів. За це завдання ти отримаєш винагороду і на додаток — виконаєш свій обов'язок перед Ордою!", [3] = "Вбийте 12 колючохутрих месників і 12 колючохутрих шаманів. Більшість з них можна знайти на схід від Зорамського узбережжя в селищі Колючохутрих. По завершенні повертайтесь до Каранґа Амаккара на форпост Зорам'ґар, що в Ясенедолі.", [4] = "Ну що, {стать:прийняв:прийняла} бій з Колючохутрими? З вільним шляхом між нашими базами, наші шанси захопити весь Ясенеділ різко зростуть.", [5] = "Молодець, {клас:к}, чудова робота! Я продовжуватиму посилати війська, аби проріджувати хутропузів, але я можу принаймні розраховувати на інший шлях в обхід сил Альянсу. Завоювання Ясенедолу Ордою в самому розпалі!\n\nСьогодні ти {стать:заслужив:заслужила} свою платню, {стать:герою:героїне}. Я вітаю тебе!", ["en"] = "Between a Rock and a Thistlefur", ["tasks"] = { ["Thistlefur Avenger"] = "колючохутрий месник", ["Thistlefur Avenger slain"] = "колючохутрий месник: убито", ["Thistlefur Shaman"] = "колючохутрий шаман", ["Thistlefur Shaman slain"] = "колючохутрий шаман: убито" } },
    [2161] = { [1] = "Ноша наймита", [2] = "Перепрошую? Допоможете?\n\nУ мене тута купа їдла. Я собі зухвало йшов цією дорогою, незважаючи на скорпидів, павучків і навіть гірших тварюк. Ніс їдло до долини Випробувань, бо думав, їм треба, тож захотів допомогти. Але їм не треба їдло! Тому я маю віднести його назад до Колючого Пагорба, але страшусь отих всіх звірюк по дорозі...\n\nМожете взяти його за мене? Я просто наймит, але ви герой. Ви нічого не боїтесь!\n\nВіднесіть їдло корчмарю Ґроску у таверні Колючого Пагорба. Дякую!", [3] = "Принесіть ношу Укора до корчмаря Ґроска у Колючому Пагорбі.", [4] = "Вітаємо у Колючому Пагорбі!", [5] = "А, це їжа, яку Укор ніс до долини Випробувань. Їм не знадобилось? Ну, схоже, їм подобається морити голодом героїв-початківців. Кажуть, це загартовує дух!\n\nДякую за повернення їжі. Я покладу її назад на полиці... але дозволь мені спочатку запропонувати тобі трохи перекусити!\n\nІ не забудь відпочити тут у корчмі. Ти може і {стать:хоробрий:хоробра}, {клас:н}, {стать:повний:повна} жаги завоювати цей світ, але без енергії ні собі, ні Орді сильно не допоможеш.", ["en"] = "A Peon's Burden", ["tasks"] = { ["Ukor's Burden"] = "ноша Укора", ["Ukor's Burden (Provided)"] = "ноша Укора (видано)" } },
    [2202] = { [1] = "В Ульдаман за реагентами", [2] = "Я чув про нещодавно відкриту рослину — гриб-малиновик. Вони ростуть цілими колоніями глибоко в розкопках Ульдамана. Певне, вони можуть рости ще десь, але поки мені відомо тільки про це місце. Я хочу вивчити можливості їх застосування в алхімії і тут-то ти мені й знадобишся.\n\nВідшукай і принеси мені дюжину цих грибів. Але будь {стать:обережний:обережна} — від зайвих рухів вони можуть випустити отруйні спори.\n\nЯкщо виконаєш моє доручення — я приготую для тебе партію мого знаменитого відновлювального зілля!", [3] = "Принесіть 12 грибів-малиновиків Джаркалу Змішаному Моху в Карґат.", [4] = "Ти {стать:приніс:принесла} гриби-малиновики для моїх алхімічних досліджень? Немає грибів — немає нагороди!", [5] = "Чудово, {ім'я}, ти знову {стать:показав:показала} на що {стать:здатен:здатна}! Ці гриби будуть здорово корисними в дослідженнях, дуже здорово!\n\nА тепер, як я й обіцяв, ти можеш насолодитись одним з найкращих зіллів з моїх запасів...\n\nЯкщо ти добре знаєш алхімію, ми могли б обговорити ще одну справу. У всякому разі, дякую тобі за допомогу!", ["en"] = "Uldaman Reagent Run", ["tasks"] = { ["Magenta Fungus Cap"] = "гриб-малиновик", ["Magenta Fungus Cap (Provided)"] = "гриб-малиновик (видано)" } },
    [2203] = { [1] = "Забіг по реагенти Безплідними краями ІІ", [2] = "Ти мене дуже {стать:виручив:виручила}, {клас:к}. Я б нагородив тебе навіть рецептом пійла, яке я дав тобі раніше... Але спершу я дам тобі ще одне завдання, досить небезпечне. Вислухай моє прохання.\n\nУ цій скриньці — три порожні тавматургічні флакони. Вони зачаровані для витягування крові з випалених драконів-стражів. Це їх не на жарт розлютить, тож будь {стать:обережний:обережна}. Як наповниш всі три флакони — повертайся до мене.\n\nЗроби це, і рецепт стане твоїм.", [3] = "Застосуйте порожні тавматургічні флакони на випалених драконах-стражах, яких можна знайти у Безплідних краях. Коли наповните їх, принесіть їх Джаркалу Змішаному Моху в Карґат.", [4] = "Ти вже {стать:використав:використала} флакони, щоб добути потрібну мені кров випалених драконів-стражів? Так, знаю, це небезпечне завдання. Але в нагороду тебе чекає рецепт мого відновлювального варева. А воно варте того... варте...", [5] = "Честь і хвала тобі, кажу як алхімік алхіміку. А ось і твій заслужений рецепт, користуйся. Хай він принесе тобі успіх і багатство, які роками приносив мені.", ["en"] = "Badlands Reagent Run II", ["tasks"] = { ["Vessel of Dragon's Blood"] = "флакон з кров'ю дракона", ["Vessel of Dragon's Blood (Provided)"] = "флакон з кров'ю дракона (видано)" } },
    [2258] = { [1] = "Забіг по реагенти Безплідними краями", [2] = "{ім'я}, я хотів би скористатися твоєю допомогою, якщо ти не проти. Я — досить визначний алхімік, і мені потрібна твоя допомога у здобутті деяких реагентів, які можна відшукати в Безплідних краях.\n\nОсь що мені потрібно, щоб поповнити свої запаси: п'ять шлунків канюка, десять ікл скельного койота і п'ять уламків кам'яних елементалів. Очевидно, що їх можна добути з цих самих створінь. Та якщо ти не любиш битись — попроси допомоги у друзів.\n\nРоздобудь для мене ці реагенти, і я непогано заплачу. Що скажеш?", [3] = "Принесіть 5 шлунків канюка, 10 ікл скельного койота та 5 уламків кам'яних елементалів Джаркалові Змішаному Моху до Карґата у Безплідних краях.", [4] = "Ти {стать:добув:добула} все необхідне? Поки не принесеш - не заплачу.", [5] = "О, чудова робота! Цього мені має вистачити на деякий час. Ось твоя плата, як я й обіцяв.\n\nЯкщо ти не проти ще допомогти, мені потрібно ще кілька реагентів. Деякі з них, однак, можна знайти лише на розкопках Ульдамана. Це буде нелегко, але й винагорода буде відповідна, якщо візьмешся.\n\nМожливо, щось більше, ніж декілька блискучих монет, га?", ["en"] = "Badlands Reagent Run", ["tasks"] = { ["Buzzard Gizzard"] = "шлунок канюка", ["Buzzard Gizzard (Provided)"] = "шлунок канюка (видано)", ["Crag Coyote Fang"] = "ікло скельного койота", ["Crag Coyote Fang (Provided)"] = "ікло скельного койота (видано)", ["Rock Elemental Shard"] = "уламок кам'яного елементаля", ["Rock Elemental Shard (Provided)"] = "уламок кам'яного елементаля (видано)" } },
    [2283] = { [1] = "Відновлення намиста", [2] = "У нас є робота для тебе, якщо, звісно, тобі вистачить сміливості!\n\nГлибоко в Безплідних краях знаходиться місце розкопок Ульдамана. Ми чули історію про якогось ідіота-паладина, який нещодавно там загинув. При ньому було дуже цінне намисто з трьома самоцвітами: рубіном, сапфіром і топазом.\n\nКоротко кажучи, нам потрібне це намисто, і ми готові заплатити за нього чистим сріблом. Воно може бути пошкодженим, але це неважливо — ми його якось полагодимо.", [3] = "Знайдіть цінне намисто на місці розкопок Ульдамана і принесіть його Драну Дрофферсу в Орґріммар. Намисто може бути пошкоджене.", [4] = "Ну що, намисто в тебе? Ти не отримаєш від нас і мідяка, якщо не принесеш його!", [5] = "Ммм, здобич! Я навіть звідси відчуваю його. Дай-но поглянути...\n\nГей, що це нам хочеш підсунути? У ньому не вистачає каменів! {стать:Думав:Думала}, ми не помітимо? Навіть Малтон помітив би, що каміння немає.\n\nНу, може, це й не ти їх {стать:вкрав:вкрала}... але без них намисто нічого не варте! Ні-ні, твоя робота ще не закінчена!", ["en"] = "Necklace Recovery", ["tasks"] = { ["Shattered Necklace"] = "пошкоджене намисто", ["Shattered Necklace (Provided)"] = "пошкоджене намисто (видано)" } },
    [23] = { [1] = "Лапа Урсанґо", [2] = "Лапа могутнього ведмедя Урсанґо — ваш трофей цього етапу Ясенедільського полювання. На лапі видно символ — півмісяць. Ви не знаєте, що він означає.\n\nЛапу слід принести Сенані Грозове Серце на заставу при Тріснутому Дереві, аби довести, що ви подолали могутнього звіра та завершили цей етап полювання.", [3] = "Принесіть лапу Урсанґо до Сенані Грозове Серце на заставу при Тріснутому Дереві, що в Ясенедолі.", [4] = "А, {ім'я:н}, я щойно думала про тебе! Як полювання?", [5] = "Лапа Урсанґо! Твої здібності вражають, {клас:к}. Цей ведмідь загубив чимало душ. Півмісяць на його лапі, безсумнівно, свідчить про те, що його тренували нічні ельфи, які вештаються Ясенедолом. Урсанґо — один... був одним з наймогутніших ведмедів в цій місцині. Подолати такого звіра означає проявити неабияку силу волі та рішучість.\n\nТвої пращури пишалися б тобою!", ["en"] = "Ursangous's Paw", ["tasks"] = { ["Ursangous's Paw"] = "лапа Урсанґо", ["Ursangous's Paw (Provided)"] = "лапа Урсанґо (видано)" } },
    [2341] = { [1] = "Відновлення намиста, третя спроба", [2] = "Пів справи зроблено, а Дран і Малтон Дрофферси вже сваряться через нову здобич. Тепер потрібно відправитися в Безплідні краї, адже там, в Карґаті, на вас чекає особлива нагорода від Джаркала Змішаного Моха.", [3] = "Відвідайте Джаркала Змішаного Моха в Карґаті.", [5] = "Джерело сили, яке ти мені {стать:приніс:принесла}, перевершило всі мої сподівання. Я зміг виготовити намисто для нас обох, і в ньому залишилося достатньо сили, щоб зробити ще принаймні три. За них можна буде отримати чималу винагороду, а Дрофферси ні про що не здогадаються.\n\nОсь, тримай. Я тобі дуже вдячний.", ["en"] = "Necklace Recovery, Take 3" },
    [2342] = { [1] = "Повернення скарбів", [2] = "Підмітати загони для кажанів цією мітлою не личить Ґарретам! Я заробив трохи грошей на цій мерзенній роботі та хочу витратити їх на поліпшення свого становища.\n\nРодинна зброя сім'ї Ґарретів замкнена в нашій скрині в південній загальній залі Ульдаману ще з тих часів, коли ми, Ґаррети, працювали там землекопами. Без неї я застрягну тут навіки — буквально — прибираючи лайно за цими клятими кажанами.\n\nДістань мій родинний скарб! Допоможи мені повернути те, що належить мені по праву!", [3] = "Дістаньте родинний скарб Патріка Ґаррета з його родинної скрині південній загальній залі Ульдамана і принесіть його йому в Підмістя.", [4] = "Прибиранню немає кінця... Ці кажани не перестають знущатися наді мною і моєю мітлою. Будь ласка, скажи, що тобі вдалося повернути скарб моєї сім'ї! Я готовий віддати тобі все моє срібло — хіба цього недостатньо?!", [5] = "Нарешті — мітла, гідна Ґаррета. Ти, чорт забирай, {стать:вартий:варта} кожного витраченого на тебе срібляка!\n\nВи чуєте мене, кляті кажани? Тепер у мене є справжня зброя родини Ґарретів! Тремтіть, кажани, тремтіть!", ["en"] = "Reclaimed Treasures", ["tasks"] = { ["Garrett Family Treasure"] = "родинний скарб Ґарретів", ["Garrett Family Treasure (Provided)"] = "родинний скарб Ґарретів (видано)" } },
    [235] = { [1] = "Ясенеділське полювання", [2] = "Увага, юні шукачі пригод! Дикі хащі Ясенедолу чекають на вас!\n\nОрді вдалося закріпитися в землях на північ від Степів. Дві наші застави — при Тріснутому Дереві та на Зорамському узбережжі — б'ються за славу Орди! Ті, хто хоче проявити себе у подвигах, можуть вирушити туди. Зверніть увагу: Сенані Грозове Серце на заставі при Тріснутому Дереві, що на північ від Степів, шукає охочих взяти участь у великому полюванні в Ясенедолі!", [3] = "Поговоріть з Сенані Грозовим Серцем на заставі при Тріснутому Дереві, що в Ясенедолі.", [5] = "Ласкаво просимо на наш новий рубіж, {ім'я}. Ясенеділ — це земля можливостей, де {стать:такому юній:такій юній} {клас:д}, як ти, знайдеться вдосталь шансів довести свою силу. Оглянь цю заставу та обов'язково сходи на Зорамське узбережжя — в Орди й там є застава.\n\nЯк розумію, ти тут для того, щоб дізнатися більше про полювання. Слухай уважно, і я з радістю поділюся з тобою всім, що тобі потрібно знати.", ["en"] = "The Ashenvale Hunt" },
    [2380] = { [1] = "До Орґріммару!", [2] = "Ти, звісно, далеко ще не фахівець з непомітності та обману, проте все це може змінитися. Принаймні, начальство явно звернуло на тебе увагу, оскільки сам Шентул запам'ятав твоє ім'я.\n\nРушай звідси на північ, до Орґріммару, та поговори з Шентулом в Розколині Тіні.", [3] = "Поговоріть з Шентулом в Розколині Тіні в Орґріммарі.", [5] = "Дуже важливо, щоб Розтрощена Рука зберігала пильність перед обличчям змін, які Тралл має намір запровадити в Орді. Нашої чисельності буде недостатньо, щоб змагатися з його владою — ми маємо покладатись на непомітність та хитрість.", ["en"] = "To Orgrimmar!" },
    [2383] = { [1] = "Простий пергамент", [2] = "О, {ім'я}! Поки тебе не було, мене попросили передати тобі цей пергамент.\n\nПрочитай його, як матимеш час. Якщо не помиляюсь, він від тренера воїнів Франґа. Певно, ти захочеш поговорити з ним. Знайти його можна біля Лігва, десь в затінку.", [3] = "Прочитайте простий пергамент і поговоріть з Франґом в долині Випробувань.", [4] = "Що це в тебе? Пергамент? Ти що, вмієш читати?", [5] = "А, так, це ж я написав. Я почув, що ти будеш в долині, {ім'я}. Радий, що тобі вдалось добратися сюди. Будемо сподіватись, що ти впораєшся і з майбутніми випробуваннями. Як я й писав - приходь до мене і я зроблю з тебе {стать:справжнього:справжню} {клас:з}.\n\nХай щастить, {ім'я}. Приходь, як будеш {стать:готовий:готова}.", ["en"] = "Simple Parchment", ["tasks"] = { ["Simple Parchment"] = "простий пергамент", ["Simple Parchment (Provided)"] = "простий пергамент (видано)" } },
    [24] = { [1] = "Голова Шадумбри", [2] = "Колись швидкий, як вітер, Шадумбра тепер спокійно лежить біля ваших ніг. Голова вбитого ночезуба — гідний трофей для {стать:учасника:учасниці} Ясенедільского полювання. Якщо ви принесете її Сенані Грозове Серце на заставу при Тріснутому Дереві, вона винагородить вас за перемогу в цьому етапі полювання.", [3] = "Принесіть голову Шадумбри до Сенані Грозове Серце на заставу при Тріснутому Дереві, що в Ясенедолі.", [4] = "І знову вітаю, {ім'я:к}! Ти {стать:прийшов:прийшла} з мисливським трофеєм?", [5] = "{Ім'я:н} — {стать:переможець:переможниця} Ясенеділського полювання! Молодець! Голова Шадумбри — гідна нагорода за таку битву.\n\nЛютість Шадумбри добре відома тут, на заставі. Через цього тигра будь-яка піша подорож на захід, до Зорамського узбережжя, була смертельно небезпечною. Завдяки тобі цю небезпеку усунуто.", ["en"] = "Shadumbra's Head", ["tasks"] = { ["Shadumbra's Head"] = "голова Шадумбри", ["Shadumbra's Head (Provided)"] = "голова Шадумбри (видано)" } },
    [2440] = { [1] = "Платинові диски", [2] = "Я зосереджу свої сили на цих дисках і врешті-решт розкрию їх таємниці.\n\nА щодо тебе, {ім'я}, я маю віддячити за те, що ти {стать:приніс:принесла} їх мені. Віднеси цей талон Бені Зимовому Копиту, тренерці алхімії в Громовому Бескиді. Вона дасть тобі одну річ, яка, я впевнений, тобі сподобається, а ще запропонує тобі на вибір зілля з моїх особистих запасів.\n\nІ скоріш повертайся до мене, бо чую я, що на нас чекає ще багато пригод з цією знахідкою.", [3] = "Віднесіть ваш талон на винагороду Бені Зимовому Копиту в Громовий Бескид.", [4] = "Вітаю, {клас:к}! Ти {стать:прийшов:прийшла} навчатись алхімії чи, може, за чимось ще?", [5] = "Що ж, {ім'я}, схоже, ти гарно {стать:догодив:догодила} Любомудру Шукачу Істини, якщо маєш отримати цю річ. Також ти можеш обрати собі винагороду з його запасів зілля. Обирай: п'ять відмінних зіллів лікування чи п'ять сильних зіллів мани?", ["en"] = "The Platinum Discs", ["tasks"] = { ["Reward Voucher"] = "талон на винагороду", ["Reward Voucher (Provided)"] = "талон на винагороду (видано)" } },
    [247] = { [1] = "Кінець полювання", [5] = "{ім'я}, ти {стать:вбив:вбила} всіх трьох звірів, які були цілями Ясенедільського полювання. Ти {стать:приніс:принесла} мені гідні докази їх смерті. Твоя сила та завзяття поза сумнівами. У твоїх жилах тече кров {стать:мисливця:мисливиці}. Ти заслуговуєш на винагороду!\n\nБудь ласка, прийми цю дрібничку як нагороду за великі справи, вчинені тобою в Ясенедолі на честь Орди. Нехай бережуть тебе пращури!", ["en"] = "The Hunt Completed" },
    [2478] = { [1] = "Місія здійсненна, але малоймовірно", [2] = "Тобі доведеться вкрасти ключ від вежі у штейгера Силіксиза, {ім'я}. Як ви отримаєте ключ, збережи його — він мені ще знадобиться.\n\nПам'ятай, отрута послабила всіх у цій вежі. Скористайся своїми здібностями, щоб принести хаос і руйнування її мешканцям. Вбий їх всіх, ніякого милосердя!\n\nКоли все всередині перетвориться на криваву баню, зламай скриню Ґаллівікса та викради з неї запас зміненої суміші Занзіла. Принеси голову та суміш Шентулу в Орґріммар.", [3] = "Викрадіть ключ від вежі Силіксиза у штейгера Силіксиза, а потім вбийте двох мутованих мерців, двох патрульних та двох спостерігачів ТзНБ \"Авантюра\".\n\nВбийте старшого штейгера Ґаллівікса та заберіть його голову, потім зламайте замок на скрині Ґаллівікса та викрадіть запас зміненої суміші Занзіла. Принесіть запас суміші та голову Ґаллівікса Шентулу в Орґріммар для отримання подальших вказівок.", [4] = "У тебе є що доповісти, {ім'я}?", [5] = "Бідний Фіззул, він був гарним агентом — одним з кращих. На жаль, це ціна, яку ми платимо, {ім'я}. Бути польовим агентом Розтрощеної Руки — це небезпечна робота.\n\nТи чудово {стать:впорався:впоралася} зі своїм завданням, {клас:к}. Добре, що тобі вдалося вижити, адже ти можеш служити нам далі.", ["en"] = "Mission: Possible But Not Probable", ["tasks"] = { ["Cache of Zanzil's Altered Mixture"] = "запас зміненої суміші Занзіла", ["Cache of Zanzil's Altered Mixture (Provided)"] = "запас зміненої суміші Занзіла (видано)", ["Gallywix's Head"] = "голова Ґаллівікса", ["Gallywix's Head (Provided)"] = "голова Ґаллівікса (видано)", ["Mutated Venture Co. Drone"] = "мутований мрець ТзНБ \"Авантюра\"", ["Mutated Venture Co. Drone slain"] = "мутований мрець ТзНБ \"Авантюра\": убито", ["Silixiz's Tower Key"] = "ключ від вежі Силіксиза", ["Silixiz's Tower Key (Provided)"] = "ключ від вежі Силіксиза (видано)", ["Venture Co. Lookout"] = "спостерігач ТзНБ \"Авантюра\"", ["Venture Co. Lookout slain"] = "спостерігач ТзНБ \"Авантюра\": убито", ["Venture Co. Patroller"] = "патрульний ТзНБ \"Авантюра\"", ["Venture Co. Patroller slain"] = "патрульний ТзНБ \"Авантюра\": убито" } },
    [2480] = { [1] = "Допомога Гінотта", [2] = "Я ніколи не бачив такого дивовижного ефекту від отрути! Занзіл, кажеш? Ніколи не чув про нього, проте, маю віддати йому належне за створення такої чудової суміші.\n\nНу що ж, я вилікую тебе, а потім навчу користуватися отрутою.\n\nДай мені кілька хвилин, {ім'я}, я маю вивчити токсин.", [3] = "Дочекайтеся, доки Серж Гінотт завершить ліки.", [5] = "Ліки готові! Випий цю протиотруту і це повзуче божевілля зупиниться. Проте, я нічого не зможу зробити з цим запахом.", ["en"] = "Hinott's Assistance", ["tasks"] = { ["Cure Completed"] = "Лікування завершено" } },
    [25] = { [1] = "Перешкода в Каміннопазуристих горах", [2] = "Хочеш бути {стать:корисним:корисною}? Розберися з ситуацією в Пазуродертому тунелі.\n\nТранспортне сполучення між Ясенедолом та Каміннопазуристими горами зупинилося через озеро, що ожило та почало нападати на все, що наближається. Окрім приструнчення водяних елементалів, корисно було б також розвідати альтанку на озері Містраль — ту, з якої добре видно заставу Альянсу.\n\nТо що, доведеш свою користь?", [3] = "Вбийте 12 забруднених елементалів води біля озера Містраль на схід від Пазуродертого тунелю та південний захід від застави при Тріснутому Дереві.\n\nРозвідайте альтанку на озері Містраль, з якої видно заставу Альянсу.\n\nПоверніться до Мастока Хитрошипа на заставу при Тріснутому Дереві, що в Ясенедолі.", [4] = "Вже {стать:повернувся:повернулася}? Як там справи — все {стать:розчистив:розчистила}?", [5] = "Так, я вже чув, що хтось продерся через те озеро, як пиловий дідько через Степи. Схоже, що є можливість встановити там спостережний пост, аби спостерігати за нашими приятелями з Альянсу. Звісно, якщо не висовуватися...\n\nА ти, зрештою, {стать:довів:довела} свою корисність. Сполучення між заставою та Каміннопазуристими горами повинно відновитися. Візьми це — ти {стать:заслужив:заслужила}.", ["en"] = "Stonetalon Standstill", ["tasks"] = { ["Befouled Water Elemental"] = "забруднений елементаль води", ["Befouled Water Elemental slain"] = "забруднений елементаль води: убито" } },
    [2621] = { [1] = "Збезчещений", [2] = "Розкаяння. Це все, що у мене лишилось. Одне неправильне рішення з багатьма жахливими наслідками. Якби я тільки дочекався тих наказів. Можливо, вони б детально описали жахи, які чекали нас в цих проклятих землях! Можливо, вони мали перенаправити нас на інше завдання? Зрештою, це я винен. Це я винен у всьому, що сталось.\n\nІ ось я тут, в очікуванні наказів. Я повинен знати. Мені потрібні ті накази.\n\nКомандир зв'язку Руаґ перебуває в Камінарді. Знайди його і дізнайся, що сталося з тими наказами.", [3] = "Поговоріть з командиром зв'язку Руаґом у Камінарді.", [5] = "Хватка Тралла... Ця історія все ще свіжа у моїй пам'яті.\n\n<Командир Руаґ хитає головою.>\n\nЖахлива річ, яка сталася з тим підрозділом. Орда втратила кількох своїх кращих воїнів, коли цей підрозділ був знищений.", ["en"] = "The Disgraced One" },
    [2622] = { [1] = "Зниклі накази", [2] = "Накази? Для чого ти хочеш отримати ці накази?\n\nЩо ти маєш на увазі, {ім'я}? Звичайно, я передав ці накази! Солдати, з якими я їх відправляв, потрапили в засідку і були безжально розбиті мурлоками. Вижив тільки один, якщо це можна так назвати. Він ледь може говорити, не може ходити і його доводиться годувати через трубку. Якщо хочеш знати, що сталося з тими наказами, поговори з Бенґором. Я впевнений, що він десь тут... і ще, {ім'я} стеж, куди сунеш свій ніс — бо можеш його втратити.", [3] = "Поговоріть з Бенґором.", [5] = "Болотний ба... баз.. базікало...", ["en"] = "The Missing Orders" },
    [2623] = { [1] = "Болотний Базікало", [2] = "Накази були віддані командиром зв'язку. Ми прийняли... прийняли накази. На шляху до Спустошених земель — засідка.\n\nМурлоки... багато мурлоків... Одного звали Болотний Базікало. Вирвав накази у мене з рук, вдарив списом мені в голову. Схід... печера...\n\n<Бенґор непритомніє.>", [3] = "Заберіть накази воєвождя і поверніть їх полеглому герою Орди.", [4] = "Очікую накази.", [5] = "Це гірше, ніж я очікував. Дев'ятнадцять моїх соратників були б позбавлені від страждань, на які вони наражались. Якби я не діяв так нерозумно.\n\nДопоможи їм, {ім'я}! Я безсилий щось зробити.", ["en"] = "The Swamp Talker", ["tasks"] = { ["Warchief's Orders"] = "накази воєвождя", ["Warchief's Orders (Provided)"] = "накази воєвождя (видано)" } },
    [264] = { [1] = "Доки смерть не розлучить нас", [2] = "Клятий покидьок! Покинув мене заради свого клятого походу. Тому що \"Світло понад усе, це наш єдиний захист проти невмерлих!\".\n\nА як же діти?! А як же я?! Багато ночей я терпляче чекала на нього... я завжди була на другому місці після його клятого обов'язку!\n\nЩо ж, подивись на плоди \"правосуддя\", {ім'я}! Він мертвий, а стала тим, що він намагався зупинити!\n\nВізьми цей мотлох і поклади на його могилу в Крипті. Мені не потрібне більше це сміття... і він сам теж!", [3] = "Покладіть кулон Клариси на могилу Юріва в Срібнохвої.", [4] = "Кам'яна плита холодна на дотик. Могила була сплюндрована: навколо валяється сміття, з барельєфа вибиті шмати, а могила заросла травою.\n\nНікому немає діла до тих, хто тут похований, особливо якщо це жертва чуми.", [5] = "Ви кладете кулон на могилу, і дорогоцінний камінь у ньому помітно тьмяніє.\n\nПідвівшись, ви дивитесь на кулон. Він лежить на плиті, тьмяний і холодний. Ваші думки перериває різкий, холодний вітер, що проноситься над Криптою. На мить все навколо завмирає.", ["en"] = "Until Death Do Us Part", ["tasks"] = { ["Clarice's Pendant"] = "кулон Клариси", ["Clarice's Pendant (Provided)"] = "кулон Клариси (видано)" } },
    [27] = { [1] = "Необхідний урок", [2] = "{ім'я:к}, я з задоволенням спостерігав за твоїми успіхами. Ти безперечно станеш {стать:відомим захисником:відомою захисницею} природи.\n\nНастав час тобі дізнатись більше про один з аспектів тварин, здатність перетворюватись в яких дарував нам Кенарій. Про аспект, який дає тобі владу над водою. Для цього тобі потрібно відправитись в селище Нічна Гавань на Місячній галявині й поговорити з Дендритом Зіркосяйвом з Кенарійського Кола. Він буде твоїм наставником.", [3] = "Поговоріть з Дендритом Зіркосяйвом у селищі Нічна Гавань на Місячній галявині.", [5] = "Мої вітання, {стать:юний:юна} {клас:к}. Настав час тобі пізнати водну форму. В ній ти зможеш вільно і необмежено пересуватися у воді. Цей аспект буде для тебе корисним інструментом і благословінням... Але перш ніж опанувати це уміння, його потрібно заслужити.\n\nТебе чекає два випробування. Перше перевірить твою здатність працювати під тиском води. Друге — перевірить твою рішучість пізнати аспект самої форми.\n\nГотуйся — час випробування настав.", ["en"] = "A Lesson to Learn" },
    [2742] = { [1] = "Рін'джі в пастці!", [2] = "Привіт, {раса:к}!\n\nРін'джі втратив свою сокиру і його схопили! Будь ласка, допоможи Рін'джі втекти. Я знаю, шо такі як ти, {раса:к}, не люблять таких як Рін'джі, але Рін'джі просе! Ми повинні вийти звідси!\n\nЯ маю шось для {раса:р}, якшо ти поможеш Рін'джі втекти звідси...\n\nРін'джі сховав таємничку на Оглядовій кручі.", [3] = "Виведіть Рінджі з оселі Квел'Даніл, а потім знайдіть те, що він сховав біля Оглядових круч на сході.", [4] = "Рінджі напуганий!", [5] = "Ця скрижаль тролів, мабуть, і є \"таємничкою\", про яку говорив Рін'джі.\n\nВона вкрита дивними позначками і ви не можете розшифрувати, що на ній написано.", ["en"] = "Rin'ji is Trapped!", ["tasks"] = { ["Escort Rin'ji to safety"] = "Супроводьте Рінджі у безпечне місце" } },
    [2751] = { [1] = "Варварські обладунки", [2] = "Двадцять поколінь Омоші тримали цей молот, {ім'я}. Ми перекували сотні тисяч тонн металу. Трагічно, все це закінчується на Орокку, невдасі сім'ї Омош: без спадкоємців я неспроможний продовжити рід.\n\nЯ не можу дозволити, щоб секретні рецепти Омош померли разом зі мною! Хтось має продовжити справу роду Омош!\n\nДоведи Орокку свою майстерність, {ім'я}. Принеси Орокку наступне: дві пари візерунчастих бронзових поручів, два довгі бронзові мечі та два гострих кігті. Принеси їх Орокку, і ми продовжимо.", [3] = "Принесіть дві пари візерунчастих бронзових поручів, два довгих бронзових меча та два гострі кігті до Орокка Омоша в Орґріммар.", [4] = "Бронза, {ім'я}! Більше бронзи!!", [5] = "Рід згасне, але, можливо, легенда про Омош продовжиться!\n\nТи {стать:довів:довела}, що ти коваль, {ім'я}. Для коваля справжньою нагородою є задоволення бачити свою зброю й обладунки, вкриті кров'ю ворогів!\n\nНехай обладунки, які ти створиш для наступних поколінь, будуть просякнуті кров'ю твоїх ворогів!", ["en"] = "Barbaric Battlements", ["tasks"] = { ["Bronze Greatsword"] = "довгий бронзовий меч", ["Bronze Greatsword (Provided)"] = "довгий бронзовий меч (видано)", ["Patterned Bronze Bracers"] = "візерунчасті бронзові поручі", ["Patterned Bronze Bracers (Provided)"] = "візерунчасті бронзові поручі (видано)", ["Sharp Claw"] = "гострий кіготь", ["Sharp Claw (Provided)"] = "гострий кіготь (видано)" } },
    [2752] = { [1] = "Залізні наплічники", [2] = "Орокк бачить жадібність у твоїх очах, {ім'я}. Ти, як губка, вбираєш мудрість Омош.\n\nТри уроки я викладу!\n\nПовернись до ковадла, відчуй спеку плавильні, створи для Орокка чотири бронзові бойові сокири та чотири бронзові бойові молоти. Тільки тоді ти навчишся створювати залізні наплічники.", [3] = "Принесіть чотири бронзові бойові сокири та чотири бронзові бойові молоти до Орокка Омоша в Орґріммар.", [4] = "Покажи мені свою відданість, {раса:к}.", [5] = "Ти змушуєш Орокка пишатися, {ім'я}. Ось, читай це та навчись створювати залізні наплічники!", ["en"] = "On Iron Pauldrons", ["tasks"] = { ["Bronze Battle Axe"] = "бронзова бойова сокира", ["Bronze Battle Axe (Provided)"] = "бронзова бойова сокира (видано)", ["Bronze Warhammer"] = "бронзовий бойовий молот", ["Bronze Warhammer (Provided)"] = "бронзовий бойовий молот (видано)" } },
    [2753] = { [1] = "Важка хода", [2] = "У Орокка залишилось лише два уроки, {ім'я}. Твоє тіло болить, я знаю, але продовжуй заради Омош!\n\nПринеси Орокку чотири зелених залізних шоломи, чотири пари зелених залізних браслетів та двоє зелених залізних поножів — і я навчу тебе того, що лякатиме твоїх ворогів!", [3] = "Принесіть чотири зелені залізні шоломи, чотири пари зелених залізних браслетів та двоє зелених залізних поножів до Орокка Омоша в Орґріммар.", [4] = "Їхні черепи тріщатимуть під тиском твоїх чобіт!", [5] = "Ти нагадуєш Орокку його діда, вождя Ґорокка з Омош! Прочитай і вивчи креслення залізних чобіт.", ["en"] = "Trampled Under Foot", ["tasks"] = { ["Green Iron Bracers"] = "зелені залізні браслети", ["Green Iron Bracers (Provided)"] = "зелені залізні браслети (видано)", ["Green Iron Helm"] = "зелений залізний шолом", ["Green Iron Helm (Provided)"] = "зелений залізний шолом (видано)", ["Green Iron Leggings"] = "зелені залізні поножі", ["Green Iron Leggings (Provided)"] = "зелені залізні поножі (видано)" } },
    [2754] = { [1] = "Роги люті", [2] = "Це останнє, чому навчить тебе Орокк, {ім'я}. До священного ковадла і кузні ти повернешся! Принеси для Орокка два міцні залізні молоти, дві пари посріблених бронзових чобіт і дві пари посріблених бронзових рукавиць.\n\nТи побачиш страх в їхніх очах, коли наблизишся!", [3] = "Принесіть два міцні залізні молоти, дві пари посріблених бронзових чобіт і дві пари посріблених бронзових рукавиць до Орокка Омоша в Орґріммар.", [4] = "Покажи залізу, хто тут {стать:головний:головна}, {ім'я}!", [5] = "Дивовижно! Ти {стать:пізнав:пізнала} шлях роду Омош, {ім'я}!", ["en"] = "Horns of Frenzy", ["tasks"] = { ["Silvered Bronze Boots"] = "посріблені бронзові чоботи", ["Silvered Bronze Boots (Provided)"] = "посріблені бронзові чоботи (видано)", ["Silvered Bronze Gauntlets"] = "посріблені бронзові рукавиці", ["Silvered Bronze Gauntlets (Provided)"] = "посріблені бронзові рукавиці (видано)", ["Solid Iron Maul"] = "міцний залізний молот", ["Solid Iron Maul (Provided)"] = "міцний залізний молот (видано)" } },
    [2755] = { [1] = "Радощі роду Омош", [2] = "Орокк не плаче, {ім'я}. В око потрапила сажа.\n\n<Орокк витирає сльозу.>\n\nЄ ще одна остання таємниця сім'ї Омош, якої Орокк навчить тебе. Орокк помре щасливим завдяки {ім'я}.\n\nВивчи танець радості роду Омош, і тоді ти навчишся кувати залізний кулак!", [3] = "Навчіться танцю радості роду Омош.", [5] = "<Орокк віддихується>.\n\nПройшло дуже багато часу відколи Орокк танцював танець радості Омош. Вчись, {ім'я}!", ["en"] = "Joys of Omosh", ["tasks"] = { ["Omosh Dance of Joy Learned"] = "Омош Танець радості вивчений" } },
    [2757] = { [1] = "До Грабіжної Бухти!", [2] = "Чуєш, дитино, ти тут нічого не навчишся.\n\nЯ знаю хлопця, який знає одного типа. Він часто швендяє біля кузні в Грабіжній Бухті. Якщо ти покажеш йому цей знак, він розкаже тобі все про мітрил.\n\nТо шо скажеш? Залиш ці дитячі штучки немовлятам у підгузках, {ім'я} — тобі час рухатися далі.\n\nЯкщо це тебе цікавить, його звати Макґаван. Покажи йому цю дрібничку, і він все зрозуміє.", [3] = "Поговоріть з Макґаваном в Грабіжній Бухті.", [4] = "Оце тебе занесло, {стать:приятелю:приятелько}. Дай-но мені поглянути на цю печатку.", [5] = "Клянуся гривою Чорного Копита — нарешті, хтось {стать:гідний:гідна} ордену мітрилу!", ["en"] = "Booty Bay or Bust!", ["tasks"] = { ["Mithril Insignia"] = "мітрилова печатка", ["Mithril Insignia (Provided)"] = "мітрилова печатка (видано)" } },
    [2782] = { [1] = "Таємничка Рін'джі", [2] = "Ця скрижаль вкрита знаками тролів Зів'ялої Кори. Таємничка Рін'джі насправді дуже цікава...\n\nМожливо, у ваших руках дуже цінна річ. А можливо й ні. Троль Зів'ялої Кори міг пообіцяти будь-що, аби його врятували...", [3] = "Розшифрувати табличку, можливо, зможе Орана Змієкрут, відома дослідниця тролів Зів'ялої Кори. Вона мешкає у кварталі Магії в Підмісті.", [4] = "А це що таке?", [5] = "Ця скрижаль... Досить незвичайна... Де ти її {стать:знайшов:знайшла}, {ім'я}?", ["en"] = "Rin'ji's Secret", ["tasks"] = { ["Rin'ji's Secret"] = "таємничка Рін'джі", ["Rin'ji's Secret (Provided)"] = "таємничка Рін'джі (видано)" } },
    [2784] = { [1] = "Втрата Благодаті", [2] = "Послухай мою історію, {раса:к}.", [3] = "Послухайте історію полеглого героя Орди.", [4] = "Послухай, що я тобі скажу.", [5] = "Як дух, я безсилий, {ім'я}. Допоможи мені. Дозволь мені повернути свою честь.", ["en"] = "Fall From Grace", ["tasks"] = { ["The Tale of Sorrow"] = "Казка про печаль" } },
    [28] = { [1] = "Випробування озера", [2] = "Твоїм першим випробуванням буде пошук прикраси з вівтаря в озері Елуна'ара. Вона швидко руйнується, тож тобі доведеться швидко віднести її до вівтаря Ремула. Поклади прикрасу на вівтар і поговори там з Таджаррі. Вона — одна з найдовіреніших вартових Місячної галявини.\n\nУ тебе обмаль часу і тобі, певно, доведеться змагатись з іншими друїдами в пошуках прикраси. Твоя фізична й духовна міць допоможуть тобі досягти успіху.\n\nНехай щастить, {ім'я:к}.", [3] = "Знайдіть прикрасу вівтаря в озері Елуна'ара, принесіть її до вівтаря Ремула на північному заході Місячної галявини та використайте її там.\n\nПісля цього поговоріть з Таджаррі біля вівтаря, щоб завершити випробування.", [4] = "Щоб завершити випробування озера — використай прикрасу біля вівтаря. Поки цього не зробиш — твоє випробування не може вважатись завершеним і ти можеш зазнати невдачі.", [5] = "Що ж, здається, ще {стать:один:одна} {клас:н} успішно {стать:завершив:завершила} випробування озера! Вітаю, {ім'я:к}, ти чудово {стать:впорався:впоралась}.\n\nЯк я вже казала, мене звати Таджаррі. Мій обов'язок і честь — стояти на варті Місячної галявини, а конкретно — цього вівтаря. Хранитель Ремул направляє Кенарійське Коло у збереженні природи та рівноваги, а цей вівтар — вшанування його пам'яті. Поклавши цю прикрасу тут, ти {стать:вшанував:вшанувала} його важливість.", ["en"] = "Trial of the Lake", ["tasks"] = { ["Complete the Trial of the Lake."] = "Пройдіть випробування озера.", ["Shrine Bauble"] = "прикраса вівтаря" } },
    [2822] = { [1] = "Знак якості", [2] = "Я пишаюся майстерністю своєї роботи зі шкірою, і вважаю, що це одразу видно. Якість має бути понад усе — без жодних компромісів. А той, хто говоритиме, ніби якість не має значення, мабуть, захоче переконати тебе і в тому, ніби земля не зберігає таємниць!\n\nУ своєму нещодавньому пошуку високоякісних матеріалів, я натрапив на товсті шкури єті. Єті Фераласа можна знайти на заході звідси, в долині Лихий Шрам. Я дам тобі на вибір один з моїх шкіряних виробів за десять таких шкур. Якщо тебе це влаштовує, то ми домовились!", [3] = "Принесіть 10 товстих шкур єті Джанґдору Стрімкому Вершнику в табір Мохаче.", [4] = "Тобі вдалося зібрати десять товстих шкур єті? Мої вироби зі шкіри неперевершені, і я поділюся ними з тобою, якщо у тебе є шкури.\n\nЯкщо ти не можеш знайти єті, я тобі підкажу де їх знайти. Спробуй пошукати на заході звідси, поблизу Забутого узбережжя, біля долини Лихий Шрам.", [5] = "Чудово! Якщо їх правильно обробити, вони цілком можуть бути міцнішими за залізо! Багато спроб знадобиться, щоб знайти правильну суміш для дублення, але я впевнений, що вони дозволять мені підняти мій рівень якості на наступний рівень.\n\nЩодо тебе, {ім'я}... твоя допомога виявилась надзвичайно корисною для мене. Будь ласка, обирай будь-який з моїх виробів.", ["en"] = "The Mark of Quality", ["tasks"] = { ["Thick Yeti Hide"] = "товста шкура єті", ["Thick Yeti Hide (Provided)"] = "товста шкура єті (видано)" } },
    [2856] = { [1] = "Жилет з дикої шкіри", [2] = "Жилети з дикої шкіри є основою будь-якого комплекту обладунків з дикої шкіри. Каркас жилета та диколоззя, вплетене в нього, створюють виріб, який надає максимальний захист корпусу, дозволяючи потужній магії лози проникати через одяг.\n\nДля викрійки цього жилета мені знадобиться дві кіраси з черепашачої луски, дві пари рукавиць з черепашачої луски та диколоззя. Це не легке завдання, але ти безперечно маєш достатні навички, щоб його успішно виконати.", [3] = "Принесіть 2 кіраси з черепашачої луски, 2 пари рукавиць з черепашачої луски та диколоззя Джанґдору Стрімкому Вершнику в табір Мохаче.", [4] = "Ти {стать:приніс:принесла} дві кіраси та дві пари рукавиць з черепашачої луски? І не забудь про диколоззя!\n\nЩе працюючи з найпростішими викрійками, ми розуміємо, що складне і просте будується за одними й тими ж принципами. Таким чином, виготовлення кірас з черепашачої луски готує тебе до створення жилета з дикої шкіри.\n\nЩо далі ти навчаєшся, то більше твоє ремесло стає схожим на мистецтво!", [5] = "Дуже гарні вироби, {ім'я}. Майстерність і увага, вкладені в їх створення, свідчать про твою повну відданість цим завданням.\n\nТи {стать:виконав:виконала} моє замовлення, ось твоя винагорода. Знання створення жилетів з дикої шкіри тепер належить тобі!", ["en"] = "Wild Leather Vest", ["tasks"] = { ["Turtle Scale Breastplate"] = "кіраса з черепашачої луски", ["Turtle Scale Breastplate (Provided)"] = "кіраса з черепашачої луски (видано)", ["Turtle Scale Gloves"] = "рукавиці з черепашачої луски", ["Turtle Scale Gloves (Provided)"] = "рукавиці з черепашачої луски (видано)", ["Wildvine"] = "диколоззя", ["Wildvine (Provided)"] = "диколоззя (видано)" } },
    [2862] = { [1] = "Війна з Дереволапими", [2] = "Гноли... вони більше, ніж просто неприємність. Вони — постійна загроза існуванню цього табору! Я не знаю, чи завжди вони жили у Фераласі, чи прийшли сюди звідкись іще, але якщо ми не протистоятимемо їм досить рішуче, нам тут не вижити.\n\nА останнім часом гноли зовсім озвіріли. Нам потрібна твоя допомога, щоб скоротити їх чисельність. Принеси мені десяток їхніх грив і я щедро винагороджу тебе за твої зусилля.\n\nЙди!", [3] = "Принесіть 10 грив дереволапих гнолів Гадокену Жвавобігу в табір Мохаче.", [4] = "Ми відбиваємо їх напади, а вони все лізуть і лізуть! Їх явно щось жене... Чи, може, хтось? О, ти {стать:повернувся:повернулася}, {ім'я}? Для винагороди мені потрібні гриви, ти ж їх {стать:зібрав:зібрала}?", [5] = "Гарний початок, {ім'я}. Твої бойові навички заслуговують на похвалу.\n\nТи не {стать:єдиний:єдина}, кого я просив виконати це завдання. До тебе чимало бійців боролися з гнолами, і в минулі часи цих зусиль вистачало, щоб змусити їх відступити. Однак останнім часом вони вперто пруть на північ, у наші землі. Гноли б'ються так відчайдушно... ніби їм нема куди відступати!\n\nУ мене є план, {ім'я}, який може раз і назавжди розв'язати цю проблему...", ["en"] = "War on the Woodpaw", ["tasks"] = { ["Woodpaw Gnoll Mane"] = "грива дереволапого гнола", ["Woodpaw Gnoll Mane (Provided)"] = "грива дереволапого гнола (видано)" } },
    [2863] = { [1] = "Вбивство вожаків", [2] = "План полягає в тому, щоб одним махом знищити всіх вожаків гнолів, які називають себе альфами. Якщо нам це вдасться, то гноли розбіжаться в паніці. Можливо, до цих блохастих тварюк навіть дійде, що ми можемо і будемо знищувати їх!\n\nЯ хочу, щоб ти {стать:був вісником:була вісницею} моєї волі. Убий п'ять їхніх альф за одну годину, {ім'я}, інакше весь план піде нанівець!", [3] = "Убийте 5 дереволапих альф і поверніться до Гадокена Жвавобіга протягом однієї години.", [4] = "Час спливає, {ім'я}! Якщо ти тут не для того, щоб повідомити, що {стать:вбив:вбила} альф, то ти марнуєш час!", [5] = "Ти {стать:виконав:виконала} моє завдання, і за це я тобі дякую. Прийми цю невелику нагороду як компенсацію за свої зусилля, {ім'я}.\n\nПісля того, як ти {стать:скоротив:скоротила} їхню чисельність та {стать:вбив:вбила} їхніх вожаків, гноли подумають двічі, перш ніж нападати на табір. Однак проблему це не вирішує...\n\nМає бути причина чому гноли так озвіріли. Я хочу з'ясувати причину до того, як вони зможуть перегрупуватися.", ["en"] = "Alpha Strike", ["tasks"] = { ["Woodpaw Alpha"] = "дереволапий альфа", ["Woodpaw Alpha slain"] = "дереволапий альфа: убито" } },
    [2902] = { [1] = "Розслідування у таборі Дереволапих", [2] = "Гноли не найрозумніші істоти, але останнім часом у їхній діяльності простежуються ознаки ретельного планування. Якби ми могли добути їхні плани, можливо, нам було б простіше зрозуміти, чому вони так заворушилися.\n\nЯ хочу, щоб ти {стать:повернувся:повернулася} до Дереволапих і {стать:знайшов:знайшла} що-небудь схоже на бойові плани. Знайди їх і повертайся до мене.", [3] = "Знайдіть бойові плани гнолів в таборах гнолів на південь від табору Мохаче.", [5] = "Ви дивитесь на карту і розумієте, що це ті самі бойові плани, про які казав Гадокен Жвавобіг. На карті намальовані стрілки, які, можливо, означають переміщення військ, хоча більшість з них, здається, спрямовані на південь, а не на північ, де знаходиться табір Мохаче.\n\nІнша частина карти містить малюнок, що нагадує якусь велику комаху, з різними позначками під нею. Схоже, що гноли воюють з якимись комахами...", ["en"] = "Woodpaw Investigation" },
    [2903] = { [1] = "Бойові плани", [2] = "Треба віднести ці плани битви Гадокену Жвавобігу в табір Мохаче. Можливо, він або ще хто-небудь зуміє розібратися в планах гнолів.", [3] = "Принесіть бойові плани Дереволапих до Гадокена Жвавобіга в табір Мохаче.", [4] = "З поверненням, {ім'я}. Чи вдалося тобі знайти плани гнолів?", [5] = "Так, це те, що потрібно. Я, щоправда, не дуже розумію ці карлючки, але я бачив достатньо бойових планів за своє життя, щоб зрозуміти, що відбувається з гнолами. Здається, вони ведуть війну з двох фронтів. Один з них — з нами, але... здається, що їхні основні сили кинуті на південь.\n\nТут більше, ніж здається на перший погляд. Можливо, настав час з'ясувати, з ким ще вони воюють.", ["en"] = "The Battle Plans", ["tasks"] = { ["Woodpaw Battle Plans"] = "бойові плани Дереволапих", ["Woodpaw Battle Plans (Provided)"] = "бойові плани Дереволапих (видано)" } },
    [2932] = { [1] = "Зловісне послання", [2] = "Тролі Зів'ялої Кори колись були союзниками Орди, але вони зрадили Тралла... і вони повинні заплатити за це!\n\nВізьми мій спис і вирушай до Внутрішніх земель, далеко на північ. Спочатку знайди Тарренський Млин — поселення наших союзників, відречених, а звідти йди на північний схід.\n\nКоли потрапиш у Внутрішні землі, вбивай тролів Зів'ялої Кори. Насади їхні черепи на мій спис та встроми його в землю в одному з їхніх менших селищ — Гірі'вата або Зун'вата.\n\nПокажи їм, що їхні паскудні вчинки мають наслідки!", [3] = "Зберіть черепи тролів Зів'ялої Кори та насадіть їх на спис Німбої. Розмістіть спис Німбої в одному з селищ Зів'ялої Кори у Внутрішніх землях, а потім поверніться до Німбої в Тернисту долину.", [4] = "Ти ще не {стать:виконав:виконала} моє завдання, {ім'я}.", [5] = "До мене дійшли чутки про твій вчинок. Похмурий вчинок, але гідний честі. Будемо сподіватися, що тролі Зів'ялої Кори прислухаються до твого послання.", ["en"] = "Grim Message", ["tasks"] = { ["Place the grim message."] = "Розмістіть похмуре повідомлення.", ["Witherbark Skull"] = "череп троля Зів'ялої Кори" } },
    [2933] = { [1] = "Пляшки з отрутою", [2] = "У цих пляшках міститься огидна зелена отрута.\n\nВраховуючи кількість пляшок у цьому селищі, тролі Зів'ялої Кори, мабуть, дуже цінують їх. Можливо, аптекар у Тарренському Млину захоче отримати зразок.", [3] = "Принесіть пляшку з отрутою до аптекаря в Тарренський Млин.", [4] = "Доброго дня, {стать:шановний:шановна} {клас:к}. День був довгим, і жоден експеримент не вдався... Сподіваюся, ти {стать:приніс:принесла} мені хороші новини.", [5] = "Ах, і що це? Здається, це отрута... якоїсь павукоподібної істоти. І де ти його {стать:взяв:взяла}?", ["en"] = "Venom Bottles", ["tasks"] = { ["Venom Bottle"] = "пляшка з отрутою", ["Venom Bottle (Provided)"] = "пляшка з отрутою (видано)" } },
    [2934] = { [1] = "Неушкоджена отруйна залоза", [2] = "Мені потрібен свіжий зразок отрути, яку ти мені {стать:приніс:принесла}. Павуки, з яких вона була зібрана, мають бути у Внутрішніх землях — полюй на них, доки не знайдеш неушкоджену отруйну залозу, і принеси її мені. Ти знайдеш багато павуків біля міста тролів Шадра'Алор.\n\nІ не зволікай, {ім'я}, отруйна залоза повинна бути свіжою.", [3] = "Принесіть неушкоджену отруйну залозу аптекарю Лідону в Тарренський Млин.", [4] = "Ти {стать:приніс:принесла} неушкоджену отруйну залозу, {ім'я}? Мені потрібно робити експерименти зі свіжою отрутою, і я вже замовив невелику партію жахливо миленьких тваринок для випробувань!", [5] = "О, чудово! Отрута досить свіжа і, я впевнений, дуже смертельна. Дякую!", ["en"] = "Undamaged Venom Sac", ["tasks"] = { ["Undamaged Venom Sac"] = "неушкоджена отруйна залоза", ["Undamaged Venom Sac (Provided)"] = "неушкоджена отруйна залоза (видано)" } },
    [2935] = { [1] = "Порада майстра Ґадріна", [2] = "Отрута цих павуків не була такою ж потужною, як отрута, яку ти {стать:приніс:принесла}. Ймовірно, вона була з інших павуків.\n\nЯ хочу свіжий зразок тієї отрути. Щоб з'ясувати, звідки вона походить, тобі потрібно порадитися з троллем, який добре знає плем'я Зів'ялої Кори — майстром Ґадріном у селищі Сен'джин. Прямуй в Дуротар і поговори з Ґадріном. Можливо, він знає, де тролі Зів'ялої Кори беруть цю отруту.", [3] = "Поговоріть з майстром Ґадріном в селищі Сен'джин.", [5] = "А, то ти хочеш отримати свіжу отруту Зів'ялої Кори, так? Тоді сідай... тобі не сподобається те, що я скажу.", ["en"] = "Consult Master Gadrin" },
    [2936] = { [1] = "Павуча богиня", [2] = "Тролі Зів'ялої Кори поклоняються павучій богині та беруть у неї найсильнішу отруту. Тож якщо тобі потрібна ця отрута, ти маєш викликати їхню богиню!\n\nДля цього тобі потрібно дізнатись її справжнє ім'я, яке знаходиться на скрижалі, закопаній в місті тролів, Зул'Фарраку, що в Танарісі. Там є гробниця, яку оберігає Тека Мученик.\n\nЗдолай Теку, знайди його скрижаль та прочитай ім'я павучої богині. Після цього повертайся до мене.", [3] = "Прочитайте текст на скрижалі Теки, щоб дізнатися ім'я павучої богині тролів Зів'ялої Кори, після чого поверніться до майстра Ґадріна.", [4] = "Ти {стать:дізнався:дізналася} ім'я павучої богині?", [5] = "А, Елорта но Шадра... Вимовляй це ім'я лише пошепки, тому, що воно має велике значення для духів.\n\nЯ напишу його на пергаменті й створю для тебе закляття виклику...", ["en"] = "The Spider God", ["tasks"] = { ["Find the Spider God's Name"] = "Знайдіть ім'я бога-павука" } },
    [2937] = { [1] = "Виклик Шадри", [2] = "Візьми цей пергамент і прочитай його на вівтарі Шадра'Алор, глибоко в володіннях Зів'ялої Кори у Внутрішніх землях. Це викличе богиню павуків Шадру.", [3] = "Здолайте Шадру біля вівтаря Шадра'Алор та принесіть її отруту аптекарю Лідону в Тарренський Млин.", [4] = "Ти {стать:приніс:принесла} отруту?", [5] = "Чудово, ти {стать:приніс:принесла} її!", ["en"] = "Summoning Shadra", ["tasks"] = { ["Shadra's Venom"] = "отрута Шадри", ["Shadra's Venom (Provided)"] = "отрута Шадри (видано)" } },
    [2938] = { [1] = "Отрута в Підмістя", [2] = "Отрута, яку ти {стать:зібрав:зібрала} у богині павуків Зів'ялої Кори, дійсно вражає! Я зміг вбити майже два десятки кроликів всього лише краплею. Звісно, деякі з цих кроликів були дуже маленькі й могли поміститись на долоні, тому їхній імунітет до отрут був досить низьким, але не можна заперечувати, що ця отрута дуже потужна!\n\nЯ хотів би, щоб ти {стать:надіслав:надіслала} зразок моєму керівнику, аптекарю Фаранеллу в Апотекарії Підмістя. Я впевнений, що він захоче перевірити її самостійно.", [3] = "Принесіть пакунок Фаранелла майстру-аптекару Фаранеллу в Підмістя.", [4] = "Мене повідомили про твій приїзд, {ім'я}. У тебе є пакунок для мене?", [5] = "Дуже добре. Лідон згадав, що отрута в цьому пакунку — найсильніша з усіх, з якими йому доводилося працювати, і він зайнятий роботою над новими способами її застосування.\n\nЯкщо пощастить, ми знайдемо багато застосувань.\n\nДякую, {ім'я}. Твої заслуги перед Королівським товариством аптекарів беззаперечні.", ["en"] = "Venom to the Undercity", ["tasks"] = { ["Faranell's Parcel"] = "пакунок Фаранелла", ["Faranell's Parcel (Provided)"] = "пакунок Фаранелла (видано)" } },
    [2949] = { [1] = "Повернення персня", [2] = "Відкривши коробку, виготовлену Блискочистом 5200, ви бачите блискучий перстень! Ви відчуваєте, як він випромінює чарівну силу.\n\nНа його внутрішній стороні є невеликий, але помітний відбиток печатки Орґріммара. Поруч викарбувано літери, але навіть після очищення можна прочитати лише перші три: «НОҐ...».\n\nЦе може бути ім'я власника, а може — ювеліра, що виготовив перстень. Залишити його собі... чи знайти цього \"НОҐ...\". Непросте рішення...", [3] = "Ви можете залишити перстень собі, або знайти того, чиї ініціали викарбувані на його внутрішній стороні.", [4] = "Ну нічого, ми покажемо цим брудним маленьким гномам. Я впевнений, що це вони вкрали у нас ту машину! Ох, вже ці кляті... е-е-е, так? Тобі щось потрібно?", [5] = "Перстень з Гномреґана? Цікаво... але ні, це не моє.\n\nЦя історія з Гномреґаном — з цією купою дурнів не могло статись нічого кращого. Роками вони були посміховиськом, а тепер майже за одну ніч вони почали робити кращі машини, ніж ми?\n\nЩо, перстень був у дворфа Темного Заліза? Це ще цікавіше! Знаєш, може, гноми вкрали їхні божевільні схеми големів і модифікували їх. Отже, тепер дворфи Темного Заліза прагнуть помсти. Дуже цікаво...\n\nА щодо персня...", ["en"] = "Return of the Ring", ["tasks"] = { ["Brilliant Gold Ring"] = "блискучий золотий перстень", ["Brilliant Gold Ring (Provided)"] = "блискучий золотий перстень (видано)" } },
    [2950] = { [1] = "Вдосконалення персня", [2] = "Ні-ні-ні, я не збираюся стверджувати, що перстень мій. Зазвичай я такого не роблю, але твоя інформація про Темне Залізо була надзвичайно корисною. Я вдосконалю цей перстень для тебе, краще, ніж міг би зробити той, хто виготовив цю просту дрібничку. Напевно, це був якийсь гном...\n\nЯкщо ти принесеш мені злиток срібла, моховий агат і тридцять срібних монет за мою роботу, я додам до персня срібну решітку та агат, що посилить його магічні властивості. Хочеш?", [3] = "Принесіть блискучий золотий перстень, злиток срібла, моховий агат та 30 срібних монет Ноґґу в Орґріммар.", [4] = "Ти {стать:приніс:принесла} матеріали, які я просив? Без них я не зможу вдосконалити перстень.", [5] = "Ось твій перстень, кращий за попередній. Ще раз дякую за інформацію про дворфів Темного Заліза. Це може пояснити, звідки у цих гномів раптом з'явилася гоблінська майстерність.", ["en"] = "Nogg's Ring Redo", ["tasks"] = { ["Brilliant Gold Ring"] = "блискучий золотий перстень", ["Brilliant Gold Ring (Provided)"] = "блискучий золотий перстень (видано)", ["Moss Agate"] = "моховий агат", ["Moss Agate (Provided)"] = "моховий агат (видано)", ["Silver Bar"] = "злиток срібла", ["Silver Bar (Provided)"] = "злиток срібла (видано)" } },
    [2965] = { [1] = "Провісники Ульдуму", [2] = "А, {ім'я}, як добре, що ти знову {стать:прийшов:прийшла} до мене. Твої відкриття на розкопках Ульдаману викликали неабиякі обговорення серед мудреців. Я якраз розмовляв про це з одною з друїдів, Нарою Дикою Гривою, коли раптом зрозумів, що її минулі пригоди можуть мати велике значення для подальших досліджень.\n\nЯ хотів би, щоб ти {стать:поговорив:поговорила} з нею про її подорож в долину Наглядачів, що в пустелі Танаріс. Вона чекатиме тебе на Верхів'ї Старійшин.", [3] = "Поговоріть з Нарою Дикою Гривою на Верхів'ї Старійшин в Громовому Бескиді.", [5] = "В пустелі Танаріс є місце, що називається долиною Наглядачів. Ці диски, які ти {стать:знайшов:знайшла}... в їх написах згадується місце під назвою Ульдум. Вважається, що це місце — всього лише міф.\n\nТа я знаю, що це не так. Ульдум існує. Я була там. Ну... принаймні поруч.\n\nСуть в чому, {ім'я}: ми вважаємо, що ці диски якимось чином пов'язані з Ульдумом, тож ти маєш туди відправитись.", ["en"] = "Portents of Uldum" },
    [2966] = { [1] = "Що буде далі", [2] = "Ми з Любомудром Шукачем Істини хочемо, щоб ти {стать:відніс:віднесла} ці диски до запечатаних воріт Ульдуму. Але ми... не впевнені, до чого це призведе.\n\nЗвучить ризиковано, так, ми це розуміємо. Однак, може, нічого і не станеться. Можливо тобі доведеться до чогось їх притулити. А може, в присутності дисків відкриються ворота. Не бійся експериментувати та будь {стать:готовий:готова} до будь-яких наслідків.\n\nЯк щось дізнаєшся — повертайся до мене. Впевнена, нам буде що обговорити.", [3] = "Принесіть мініатюрні платинові диски до воріт Ульдуму в Танаріс та перевірте, чи є між ними зв'язок.", [4] = "З розпеченого піску видніється знайомий постамент. Можливо, він тут не просто так...", [5] = "Щойно ви торкаєтесь постаменту, мініатюрні диски з Ульдаману починають гудіти та світитись. В руках відчувається знайоме поколювання і перед воротами Ульдуму з'являється кам'яний наглядач.\n\n\"Вітаю. Я — вартовий цього проходу. Серед використаних вами дисків відсутні пластини Ульдуму. Будь ласка, додайте ці пластини до вашого набору та повторіть спробу доступу. Дякую.\"", ["en"] = "Seeing What Happens", ["tasks"] = { ["Miniature Platinum Discs"] = "мініатюрні платинові диски", ["Miniature Platinum Discs (Provided)"] = "мініатюрні платинові диски (видано)" } },
    [2967] = { [1] = "Повернення до Громового Бескиду", [2] = "Ви торкаєтесь постаменту і платинові диски знову опиняються у вашому рюкзаку.\n\nТепер, дізнавшись більше про кам'яного наглядача та повернувши диски, ви можете повернутись до Громового Бескиду та розказати про все Нарі Дикій Гриві.", [3] = "Поговоріть з Нарою Дикою Гривою в Громовому Бескиді.", [4] = "З поверненням, {ім'я}. Тобі вдалось якось використати диски?", [5] = "Тобі не вистачило дисків? Цікаво... Схоже, що диски Норґаннона — лише одна з частин більшого набору. Простіше кажучи, вони як один з ключів на зв'язці.\n\nЯкщо ми знайдемо пластини Ульдуму, то зможемо й потрапити до самого комплексу. Навіть не знаю, радіти цьому чи жахатись.\n\nМожливо, нам доведеться пожертвувати всім, щоб впевнитись, що таємниці нашої планети, які можуть знищити нас, залишаться таємницями.", ["en"] = "Return to Thunder Bluff", ["tasks"] = { ["Miniature Platinum Discs"] = "мініатюрні платинові диски", ["Miniature Platinum Discs (Provided)"] = "мініатюрні платинові диски (видано)" } },
    [2973] = { [1] = "Новий блискучий плащ", [2] = "Вітаю, {клас:к}. Я вирушив до Фераласа зі своїми супутниками за завданням з Орґріммара.\n\nМоя дружина, Коррін, дуже любить нове вбрання, тому я хочу зробити для неї новий плащ, прикрашений крилами чарівних дракончиків. Можеш допомогти мені? Райдужні хамелеони з розкішними крилами водяться на заході від табору Мохаче.", [3] = "Принесіть 10 переливчастих крил райдужних хамелеонів Крюґу Черепотрощителю в табір Мохаче.", [4] = "Летючі хамелеони можуть бути дуже небезпечні, якщо їх провокувати, {клас:к}. Тож будь {стать:обережним:обережною}, коли з ними зустрінешся. Ще варто остерігатися нічних ельфів, які також можуть ховатися в цих лісах.\n\nКоли збереш достатню кількість крил, приходь до мене, і я в боргу не залишуся!", [5] = "Чудово, {клас:к}! Ці крила підійдуть. Цього вистачить, щоб зробити плащ для Коррін і, можливо, ще й залишиться! Дякую.\n\nСподіваюся, полювання було не занадто небезпечним? Фералас не славиться поблажливістю, але ти, вочевидь, досить добре {стать:впорався:впоралася}.\n\nДякую тобі ще раз, {клас:к}.", ["en"] = "A New Cloak's Sheen", ["tasks"] = { ["Iridescent Sprite Darter Wing"] = "переливчасте крило райдужного хамелеона", ["Iridescent Sprite Darter Wing (Provided)"] = "переливчасте крило райдужного хамелеона (видано)" } },
    [2974] = { [1] = "Зловісне відкриття", [2] = "Що!? Ти {стать:зустрів:зустріла} тауренів? Ти жартуєш! Як вони виглядали!?\n\nКлан Зловісного Тотема! Ти {стать:бачив:бачила} їх? Белґром, один з наших майстрів, цікавиться ними... він навіть призначив за них винагороду.\n\nТи маєш повернутися туди, {клас:к}. Повернись і принеси мені їх роги... якомога більше рогів. Не варто недооцінювати клан Зловісного Тотема. Повернись та вбий їх. Нехай ріки Фераласа почервоніють від їхньої темної крові.", [3] = "Принесіть 20 рогів Зловісного Тотема Крюґу Черепотрощителю в табір Мохаче.", [4] = "Не сприймай мої слова легковажно, {клас:к}, Зловісний Тотем — злий клан. Якщо тобі вдалося виявити їхнє гніздо, найкраще — завдати превентивного удару... перш ніж вони прийдуть на наші землі, щоб зруйнувати наші поселення та пограбують наші землі.", [5] = "Це гарні роги, {клас:к}. Ти добре {стать:попрацював:попрацювала}. Я візьму їх і обов'язково повідомлю Белґрома коли ми повернемося до Орґріммара. Ти мені вже двічі {стать:допоміг:допомогла}, і я запам'ятаю це. Можливо в майбутньому я зможу допомогти тобі! Хай щастить.", ["en"] = "A Grim Discovery", ["tasks"] = { ["Grimtotem Horn"] = "ріг Зловісного Тотема", ["Grimtotem Horn (Provided)"] = "ріг Зловісного Тотема (видано)" } },
    [2975] = { [1] = "Огри Фераласа", [2] = "Вплив магії огрів племені Ґордунні важко не помітити. Подивись навколо, {ім'я}: вони руйнують цю землю. Ми повинні зупинити їх до того, як вони просунуться далі в Фераласі.\n\nЙди вздовж річки на північ, і ти знайдеш їхню заставу. Задай їм жару, {ім'я}. Нехай знають, що їм тут не раді.", [3] = "Рок Орхан з табору Мохаче хоче, щоб ви вбили 10 огрів Ґордунні, 10 огр-магів Ґордунні та 5 моцаків Ґордунні.", [4] = "Поквапся, {ім'я}. Чи завдання, яке я тобі дала, занадто складне?", [5] = "Чудово, {ім'я}. З часом ця земля зцілиться. Ми не повинні здаватися.", ["en"] = "The Ogres of Feralas", ["tasks"] = { ["Gordunni Brute"] = "моцак Ґордунні", ["Gordunni Brute slain"] = "моцак Ґордунні: убито", ["Gordunni Ogre"] = "огр Ґордунні", ["Gordunni Ogre Mage"] = "огр-маг Ґордунні", ["Gordunni Ogre Mage slain"] = "огр-маг Ґордунні: убито", ["Gordunni Ogre slain"] = "огр Ґордунні: убито" } },
    [2976] = { [1] = "Зловісне відкриття", [2] = "Що?!\n\nА, я казав про нагороду, так? Ну що ж, це навчить мене тримати язик за зубами, ге?\n\nТи {стать:виконав:виконала} роботу, тому я вважаю, що ти маєш отримати найбільшу нагороду за неї. Бери роги, я запакую їх в ящик для тебе. Знайди Белґрома Скелебоя у долині Честі, він захоче дізнатися про те, що ти {стать:бачив:бачила}, і винагородить тебе за важку роботу.\n\nБувай, {клас:к}, і ще раз дякую за все, що ти {стать:зробив:зробила}.", [3] = "Принесіть ящик з рогами Зловісного Тотема Белґрому Скелебою в Орґріммар.", [4] = "Поквапся, {клас:к}, у мене ще багато справ сьогодні.", [5] = "Зловісний Тотем?! Це цікаво. Ти кажеш, що {стать:натрапив:натрапила} на них, полюючи у Фераласі? Це правда?\n\nМої колеги захочуть почути ці новини, {клас:к}. Розкажи детальніше, а я поки що відрахую твою нагороду.\n\nПеред тим, як підеш, знай, що я вдячний за інформацію, яку ти {стать:приніс:принесла} мені.", ["en"] = "A Grim Discovery", ["tasks"] = { ["Crate of Grimtotem Horns"] = "ящик з рогами Зловісного Тотема", ["Crate of Grimtotem Horns (Provided)"] = "ящик з рогами Зловісного Тотема (видано)" } },
    [2979] = { [1] = "Темна церемонія", [2] = "Це схоже на плани для якоїсь темної церемонії, {ім'я}. З того, що я можу зрозуміти, її проводять маги-лорди Ґордунні.\n\nЗнайди одного з цих магів-лордів та забери у нього сферу.\n\nСфера мага містить велику силу і допоможе нам дізнатися більше про цю церемонію та магію, якою володіють огри Ґордунні.", [3] = "Рок Орхан з табору Мохаче просить вас знайти сферу Ґордунні.", [4] = "Ми повинні дізнатися чому Ґордунні тут, {ім'я}.", [5] = "Ця сфера дасть нам більше інформації про Ґордунні... яку ми потім використаємо для їхнього знищення, {ім'я}.", ["en"] = "Dark Ceremony", ["tasks"] = { ["Gordunni Orb"] = "сфера Ґордунні", ["Gordunni Orb (Provided)"] = "сфера Ґордунні (видано)" } },
    [2980] = { [1] = "Огри Фераласа", [2] = "Тепер, коли ти {стать:довів:довела} свою міць, я вірю, що тобі вистачить мужності виконати й наступне завдання.\n\nВирушай до Безкрайньої глушини, на південний захід звідси. Там лежать покинуті та зруйновані споруди, що колись належали нічним ельфам. Знайди ці руїни, і коли побачиш засохлі дерева та спаплюжену землю, ти знайдеш Ґордунні. Прожени їх звідти.\n\nЦі огри набагато сильніші за тих, з якими ти {стать:бився:билася} раніше, {ім'я}. Будь {стать:обачним:обачною}.", [3] = "Рок Орхан з табору Мохаче хоче, щоб ви вбили 10 шаманів Ґордунні, 10 чорнокнижників Ґордунні та 5 молотобоїв Ґордунні.", [4] = "Ти {стать:знайшов:знайшла} руїни, {ім'я}?", [5] = "Так, {ім'я}, ти справді {стать:надійний і вірний союзник:надійна і вірна союзниця}.", ["en"] = "The Ogres of Feralas", ["tasks"] = { ["Gordunni Mauler"] = "молотобій Ґордунні", ["Gordunni Mauler slain"] = "молотобій Ґордунні: убито", ["Gordunni Shaman"] = "шаман Ґордунні", ["Gordunni Shaman slain"] = "шаман Ґордунні: убито", ["Gordunni Warlock"] = "чорнокнижник Ґордунні", ["Gordunni Warlock slain"] = "чорнокнижник Ґордунні: убито" } },
    [2981] = { [1] = "Загроза в Фераласі", [2] = "Фералас — ідеальне місце для того, щоб {стать:такий:така} {клас:н}, як ти, {стать:міг:могла} проявити себе. Плем'я огрів під назвою Ґордунні домінує там, і їхня чисельність зростає. Їх треба зупинити, перш ніж вони загрожуватимуть нашим силам у Фераласі.\n\nЯ знаю одну воїтельку, на ім'я Рок Орхан, вона живе в таборі Мохаче у Фераласі. Йди до неї. Вона розповість тобі про ситуацію докладніше.", [3] = "Белґром Скелебій просить вас поговорити з Рокою Орханою в таборі Мохаче.", [5] = "То тебе прислав Белґром. Ти якраз вчасно, {раса:к}.\n\nДозволь мені пояснити ситуацію, а там вже вирішуй, чи тобі це до снаги... Але якщо тебе прислав Белґром, значить, твоя хоробрість не має викликати сумнівів.", ["en"] = "A Threat in Feralas" },
    [2984] = { [1] = "Поклик вогню", [2] = "Минуло багато часу відтоді, як ти {стать:проходив:проходила} своє останнє випробування, {ім'я}. До цього часу ти {стать:був старанним:була старанною} у своєму навчанні, але настав час тобі пізнати більше. Настав час тобі дізнатися про руйнування... і хаос. Ти пізнаєш елемент вогню, якщо будеш {стать:готовий:готова} заплатити за це.\n\nЗнайди Кранала Фісса у Степах. Він проживає у маленькій хатині на півночі від Перехрестя. Але май на увазі: якщо ти {стать:потрапив:потрапила} до земель нічних ельфів, ти {стать:зайшов:зайшла} надто далеко.", [3] = "Знайдіть Кранала Фісса у Степах.", [5] = "Хм... То тебе Нарм прислав, так?\n\nТоді добре, Нарму завжди можна було довіряти, тож це має означити, що ти {стать:готовий:готова} спробувати наступну сапту — сапту вогню.\n\nЯ вже бачу це у твоїх очах, палання, жадання. Ти вже {стать:відчув:відчула} силу і тепер {стать:готовий:готова} до більшого. Терпіння, {ім'я}. Пам'ятай, чого навчила тебе земля. Сила й руйнування даються легко, але ти все одно {стать:повинен:повинна} знати, коли зупинитися.", ["en"] = "Call of Fire" },
    [2986] = { [1] = "Поклик води", [2] = "Минуло багато часу з твого останнього випробування, {ім'я}. Досі ти {стать:проявляв:проявляла} чимало терпіння у своєму навчанні, та настав час тобі зробити новий крок. Настав час пізнати чистоту води.\n\nПоговори з Іслен Морською Провидицею в Степах. Ти знайдеш її в рибальській хатині на східному узбережжі, на південь від Південнолютної річки та Брашпиля. Щасти тобі, {ім'я}.", [3] = "Знайдіть Іслен Морську Провидицю в Степах.", [5] = "Ти твердо крокуєш по землі, а твій дух вже зігрітий вогнем — я б сказала, що настав час тобі пізнати чистоту води.\n\nТвій шлях привів тебе так далеко, і сила твого духу дасть тобі сил йти далі. Але перший крок ти маєш зробити {стать:сам:сама}.", ["en"] = "Call of Water" },
    [2987] = { [1] = "Кобальт Ґордунні", [2] = "Я тільки-но прибув у Фералас і чув, що огри клану Ґордунні, що мешкають у тутешніх хащах, мають деякі цікаві мінерали. Хто знає, що вони з ним роблять, але вони дуже сильно охороняють їх! Вони закопують їх, щоб бізнесменам на кшталт мене важче було до них дістатися.\n\nЯкщо ти {стать:згоден:згодна} допомогти, я дам тобі свою лопату. Йди до застави Ґордунні на півночі звідси та викопай для мене кобальт Ґордунні. Шукай, де трапиться синій блиск і починай копати!", [3] = "Принесіть 12 зразків кобальту Ґордунні Орвіну Приладику в табір Мохаче.", [4] = "Йди нагору і починай копати!\n\nА мені треба багато куди сходити та багато кого побачити... Час — це гроші!", [5] = "Чудово! Я візьму це з собою, {ім'я}. Я впевнений, що зможу знайти когось, хто заплатить за цей кобальт чималі гроші.\n\nОсь, візьми це за свій клопіт.", ["en"] = "Gordunni Cobalt", ["tasks"] = { ["Gordunni Cobalt"] = "кобальт Ґордунні", ["Gordunni Cobalt (Provided)"] = "кобальт Ґордунні (видано)", ["Orwin's Shovel"] = "лопата Орвіна", ["Orwin's Shovel (Provided)"] = "лопата Орвіна (видано)" } },
    [2995] = { [1] = "Лінії зв'язку", [2] = "Оселя Квел'Даніл є центром комунікацій вищих ельфів у Внутрішніх землях. Їхні посли працюють над тим, щоб встановити взаємовідносини з іншими расами, поширюючи знання про тролів Зів'ялої Кори, які живуть у південних Внутрішніх землях. Усі документи щодо комунікацій зберігають в оселі.\n\nНам не потрібно, щоб Високодільні будували союзи з іншими, {Ім'я}.\n\nЗнищ документи Високодільних. Ми повинні спалити їхні лінії зв'язку... буквально.", [3] = "Орана Змієкрут з Підмістя просить вас відправитись у Внутрішні землі та спалити там записи Високодільних, звіти Високодільних і нотатки Високодільних.", [4] = "Утримувати Високодільних ельфів у ізоляції - ось у чому ключ. Ти вже {стать:знайшов:знайшла} оселю?", [5] = "Чудово, {Ім'я}. Поки Високодільні працюють над відновленням своєї загубленої інформації, ми зможемо ще краще перекрити лінії...", ["en"] = "Lines of Communication", ["tasks"] = { ["Burn the Highvale Notes"] = "Спаліть нотатки Хайвейла", ["Burn the Highvale Notes (Provided)"] = "Спаліть нотатки Хайвейла (видано)", ["Burn the Highvale Notes slain"] = "Спаліть нотатки Хайвейла: убито", ["Burn the Highvale Records"] = "Спаліть записи Хайвейла", ["Burn the Highvale Records (Provided)"] = "Спаліть записи Хайвейла (видано)", ["Burn the Highvale Records slain"] = "Спаліть записи Хайвейла: убито", ["Burn the Highvale Report"] = "Спаліть звіт Хайвейл", ["Burn the Highvale Report (Provided)"] = "Спаліть звіт Хайвейл (видано)", ["Burn the Highvale Report slain"] = "Спаліть звіт Хайвейл: убито" } },
    [30] = { [1] = "Випробування морського лева", [2] = "Для другого випробування тобі потрібно зібрати дві половини підвіски морського лева. Одна з половинок уособлює спритність аспекту морського лева, що стрімко плаває в товщі води. Інша ж — уособлює його неймовірну витривалість. Друїди покладаються на обидві ці якості, щоб опанувати водну форму.\n\nПоговори з жителями Місячної галявини, щоб дізнатись, де знаходяться ці половинки та принеси їх сюди. Коли об'єднаєш їх — віддай підвіску Дендриту Зіркосяйву.", [3] = "Знайдіть половинку підвіски водної спритності та половинку підвіски водної витривалості. Поговоріть з жителями Місячної галявини, щоб дізнатись про їх місцеперебування.\n\nОб'єднайте половинки в підвіску морського лева, перебуваючи біля вівтаря Ремула.\n\nОб'єднану підвіску принесіть Дендриту Зіркосяйву в Нічну Гавань, що на Місячній галявині.", [4] = "Ти вже {стать:об'єднав:об'єднала} половинки підвіски, {ім'я:к}? Якщо тобі потрібна допомога — звернись до місцевих жителів. Так ти не тільки дізнаєшся, де їх шукати, а й краще познайомишся з цією прекрасною священною галявиною.", [5] = "Тобі вдалось пройти випробування морського лева, {ім'я:к}, вітаю тебе!\n\nУ своїх зусиллях з їх пошуків тобі довелось проявити спритність та витривалість, які так необхідні тобі для гармонії з водними глибинами. Одне не може існувати без іншого і без обох цих якостей ти не зможеш прийняти аспект морського лева.\n\nДобре запам'ятай цей урок і згадуй про нього, коли наважишся прийняти водну форму.", ["en"] = "Trial of the Sea Lion", ["tasks"] = { ["Pendant of the Sea Lion"] = "підвіска Морського Лева", ["Pendant of the Sea Lion (Provided)"] = "підвіска Морського Лева (видано)" } },
    [3002] = { [1] = "Сфера Ґордунні", [2] = "Хоча я добре знаю свого ворога, я всього-на-всього воїтелька, {ім'я}. Я навіть приблизно не уявляю, на що здатна ця сфера.\n\nАле я знаю одного мага в Орґріммарі, який зможе розповісти нам про неї більше. Віднеси сферу до нього!", [3] = "Принесіть сферу Ґордунні до Утель'ная в хижу Темношипа, що в Орґріммарі.", [4] = "Що там у тебе, {раса:к}?", [5] = "Фантастично, {ім'я}...\n\nЦя сфера дуже потужна, але й дуже небезпечна.", ["en"] = "The Gordunni Orb", ["tasks"] = { ["Gordunni Orb"] = "сфера Ґордунні", ["Gordunni Orb (Provided)"] = "сфера Ґордунні (видано)" } },
    [3062] = { [1] = "Темне серце", [2] = "Едана Злопазур — королева північноджерельних гарпій, що мешкають в руїнах на заході. Вона — чисте зло, я чув, що у неї кам'яне серце. У неї немає жодних почуттів, окрім ненависті до всього живого. Вбий Едану та принести мені її темне серце.\n\nЯ чув про ріг, який носять при собі гарпії — якщо затрубити в нього біля каменів Злопазура в північній частині руїн, то з'явиться королева.\n\nУяви, як вона здивується, коли зрозуміє, що її кличуть не родичі, а її власна смерть.", [3] = "Принесіть Тало Обдертому Копиту в табір Мохаче темне серце Едани Злопазур.", [4] = "Ненависть, яку поширює Едана, необхідно зупинити!", [5] = "Тепер я знаю, що Едана справді померла. Це серце... я збережу його на пам'ять про те, що ти {стать:зробив:зробила} для мене, {ім'я}. Дякую тобі.", ["en"] = "Dark Heart", ["tasks"] = { ["Edana's Dark Heart"] = "темне серце Едани", ["Edana's Dark Heart (Provided)"] = "темне серце Едани (видано)" } },
    [3063] = { [1] = "Помста Північноджерельним гарпіям", [2] = "У свої часи я був досвідченим мисливцем. Не було жодної істоти, якої б я боявся. Аж доки...\n\nЯ був у лісі, гострив свій клинок після важкої битви, коли на мене напали гарпії. Вони оточили мене, і я ледь зміг врятуватись.\n\nНавіть зараз я чую їхні крики...\n\nЯ більше ніколи не був таким, як раніше. Але ненависть палає в мені — усі ці роки я жадаю помсти.\n\nПівнічноджерельних гарпій можна знайти на заході звідси. {ім'я}, помстися за мене.", [3] = "Тало Обдерте Копито просить вас вбити 4 північноджерельних гарпій, 4 північноджерельних оперених пройдисвіток, 4 північноджерельних вітрозовок і 4 північноджерельних вбивць.", [4] = "Крила північноджерельних гарпій чорні, як ніч. Не зводь з них очей, щоб вони не зникли в темряві.", [5] = "Дякую, {ім'я}. Ти {стать:заспокоїв:заспокоїла} старого таурена.", ["en"] = "Vengeance on the Northspring", ["tasks"] = { ["Northspring Harpy"] = "північноджерельна гарпія", ["Northspring Harpy slain"] = "північноджерельна гарпія: убито", ["Northspring Roguefeather"] = "північноджерельна оперена пройдисвітка", ["Northspring Roguefeather slain"] = "північноджерельна оперена пройдисвітка: убито", ["Northspring Slayer"] = "північноджерельна вбивця", ["Northspring Slayer slain"] = "північноджерельна вбивця: убито", ["Northspring Windcaller"] = "північноджерельна вітрозовка", ["Northspring Windcaller slain"] = "північноджерельна вітрозовка: убито" } },
    [3065] = { [1] = "Проста скрижаль", [2] = "О, {ім'я}! Поки тебе не було, мене попросили передати тобі цей пергамент.\n\nПрочитай його, як матимеш час. Якщо не помиляюсь, він від тренера воїнів Франґа. Певно, ти захочеш поговорити з ним. Знайти його можна біля Лігва, десь в затінку.", [3] = "Прочитайте просту скрижаль та поговоріть з Франґом в долині Випробувань.", [4] = "О, ще {стать:один:одна} {раса} в наших рядах. Ти здаєшся {стать:здібним:здібною}.\n\nТобі певно важко буде справитись з хорошою сокирою, та який-небудь спис теж згодиться.\n\nВітаю в долині Випробувань!", [5] = "Ти призвичаїшся до цього місця, поки будеш вчитись майстерності {клас:р}. Якщо маєш якісь питання - не бійся, запитуй. А як будеш {стать:готовий:готова} - приходь до мене на тренування. Я не поступаюсь жодному тутешньому воїну та можу поділитись з тобою знаннями... за невелику плату.", ["en"] = "Simple Tablet", ["tasks"] = { ["Simple Tablet"] = "проста скрижаль", ["Simple Tablet (Provided)"] = "проста скрижаль (видано)" } },
    [3082] = { [1] = "Гравійована скрижаль", [2] = "О, {ім'я:н}! Поки тебе не було, мене попросили передати тобі цю скрижаль.\n\nПрочитай її, як матимеш час. Якщо не помиляюсь, вона від тренерки мисливців Джен'шан. Певно, ти захочеш поговорити з нею.", [3] = "Поговоріть з Джен'шан в долині Випробувань.", [4] = "Джен'шан бачить {стать:могутнього:могутню} {клас:з}. Духи раді тобі.\n\nШлях мисливців — один з найдавніших. Орда покладалась на наші навички, коли намагалась вижити на Азерот і просили навчити, поділившись нашими таємницями. Вони вже були сильні по своєму: хтось був сильним воїном, а хтось — могутнім шаманом. Та шлях мисливців тоді ще був не для них...", [5] = "Тепер ми вчимо їх мистецтву мисливства, а вони нас — своїм вмінням. Ми практично стали одним цілим і є давніми союзниками. Не забувай їм допомагати. А Джен'шан не забуватиме допомагати тобі.\n\nДжен'шан навчить тебе мистецтва мисливців... добре навчить. Пам'ятай — мисливців завжди поважають в племені. Тебе чекає велике майбутнє — не забувай про це.\n\nЯк буде потреба — приходь до Джен'шан. Вона навчить тебе всього, чого зможе.", ["en"] = "Etched Tablet", ["tasks"] = { ["Etched Tablet"] = "гравійована скрижаль", ["Etched Tablet (Provided)"] = "гравійована скрижаль (видано)" } },
    [3083] = { [1] = "Зашифрована скрижаль", [2] = "О, {ім'я}! Поки тебе не було, мене попросили передати тобі цю скрижаль.\n\nПрочитай її, як матимеш час. Якщо не помиляюсь, вона від тренера пройдисвітів Рваґа. Певно, ти захочеш поговорити з ним.", [3] = "Прочитайте зашифровану скрижаль і поговоріть з Рваґом в долині Випробувань.", [4] = "Ласкаво просимо у долину Випробувань, {ім'я}. Тебе б тут не було, якби ти не {стать:отримав:отримала} мою скрижаль, отож, я перейду до справи.\n\nЯ Рваґ, і я відповідальний за тренування пройдисвітів, злодіїв та нишпорок тут, у долині. Я той, до кого звернеться Рука, якщо ти будеш не {стать:готовим:готовою} до того, що має статися. Але не переймайся, Рука не буде контролювати все, що ти робиш, але було б розумно співпрацювати з ними, особливо, якщо їм знадобляться твої таланти.", [5] = "До того часу ти будеш під моєю опікою. Я покажу тобі як, що і де. Коли відчуєш себе {стать:готовим:готовою}, приходь до мене, і я подбаю про подальше навчання. А до тих пір практикуй свої навички та відточуй їх до блиску. Хто зна, коли тобі знадобиться навіть найнезначніша здібність.", ["en"] = "Encrypted Tablet", ["tasks"] = { ["Encrypted Tablet"] = "зашифрована скрижаль", ["Encrypted Tablet (Provided)"] = "зашифрована скрижаль (видано)" } },
    [3084] = { [1] = "Рунічна скрижаль", [2] = "О, {ім'я}! Поки тебе не було, мене попросили передати тобі цю скрижаль.\n\nПрочитай її, як матимеш час. Якщо не помиляюсь, вона від тренерки шаманів Шікрік. Певно, ти захочеш поговорити з нею.", [3] = "Поговоріть з Шікрік в долині Випробувань.", [4] = "А, привіт, {ім'я}. Я радий, що ти {стать:прибув:прибула}. У мене чимало справ, і учнів вистачає, але щоразу, як до мене з'являється хтось з твого племені, це приносить мені відчуття виконаного обов'язку — адже колись я сама вчилася в одного з ваших шаманів.", [5] = "Як ти, напевно, вже знаєш, стихії дають нам могутність. Вогонь, земля, вода й повітря — це наші знаряддя.\n\nНаша сила походить від духів наших предків. Ми повинні вести наш народ. Для міст і сіл, де ми буваємо, ми повинні стати тим самим, чим став Тралл для всієї Орди. Вони шукатимуть у нас мудрості та захисту. Але щоб бути {стать:готовим:готовою}, тобі знадобиться чимало тренуватися. Коли відчуєш, що {стать:став сильнішим:стала сильнішою}, приходь до мене, і я навчу тебе всього, що вмію.", ["en"] = "Rune-Inscribed Tablet", ["tasks"] = { ["Rune-Inscribed Tablet"] = "рунічна скрижаль", ["Rune-Inscribed Tablet (Provided)"] = "рунічна скрижаль (видано)" } },
    [3085] = { [1] = "Священна скрижаль", [2] = "О, {ім'я}! Поки тебе не було, мене попросили передати тобі цю скрижаль.\n\nПрочитай її, як матимеш час. Якщо не помиляюсь, вона від тренера жерців Кен'джая. Певно, ти захочеш поговорити з ним.", [3] = "Прочитайте священну скрижаль та поговоріть з Кен'джай біля лігва в долині Випробувань.", [4] = "Ти тут... добре, добре. Духи сказали мені, що ти скоро прийдеш, щоб побачитись з Кен'джаєм. Дозволь мені одним з перших привітати тебе в долині Випробувань. Це місце недовго буде твоїм домом, але поки це так, чом би тобі цим не скористатись.", [5] = "Випробувавши себе, ти зрозумієш, що можеш все краще контролювать духів. Ти будеш кликати їх для потужних здібностей... і з цим тобі допоможе старий Кен'джай. Приходь поговорити зі мною, коли будеш {стать:готовий:готовий}. Якщо духи погодяться, я зможу навчити тебе потужних здібностей... але тіки якщо вони погодяться.\n\nІди но, поговори з іншими жителями долини. Поговорим пізніше.", ["en"] = "Hallowed Tablet", ["tasks"] = { ["Hallowed Tablet"] = "священна скрижаль", ["Hallowed Tablet (Provided)"] = "священна скрижаль (видано)" } },
    [3086] = { [1] = "Гліфічна скрижаль", [2] = "О, {ім'я:н}! Поки тебе не було, мене попросили передати тобі цю скрижаль.\n\nПрочитай її, як матимеш час. Якщо не помиляюсь, вона від тренерки магів Май'а. Певно, ти захочеш поговорити з нею.", [3] = "Прочитайте гліфічну скрижаль та поговоріть з Май'а біля входу до Лігва в долині Випробувань.", [4] = "Здається, ти вже {стать:зацікавив:зацікавила} Май'а, {ім'я:н}. Це добре. Ти поважатимеш Май'а, а Май'а поважатиме тебе. Але досить про це, ти тут, щоб вчитися магії, а не слухати розмови Май'а.\n\nЄ тільки одна річ, якої Май'а не зможе навчити тебе, {ім'я:н}, і це те, як зупинити скверну.", [5] = "Ти будеш {стать:одним:однією} з наймогутніших істот у світі, {ім'я:н}... це без сумнівів. І всі це дізнаються... добре дізнаються!\n\nАле будь {стать:обережний:обережна}! Бо боятися треба не орка, не ельфа, і не дворфа... Боятися треба речей, яких не бачиш. Магія потужна. Вона змушує робити те, чого не хочеш. Змушує думати, що ти {стать:сильніший:сильніша}, ніж є насправді. Будь {стать:терплячим:терплячою}. Будь {стать:розумним:розумною}.\n\nКоли відчуєш, що {стать:готовий:готова} до тренувань — повертайся до Май'а. Вона тебе всього навчить, без проблем.", ["en"] = "Glyphic Tablet", ["tasks"] = { ["Glyphic Tablet"] = "гліфічна скрижаль", ["Glyphic Tablet (Provided)"] = "гліфічна скрижаль (видано)" } },
    [3087] = { [1] = "Гравійований пергамент", [2] = "О, {ім'я:н}! Поки тебе не було, мене попросили передати тобі цей пергамент.\n\nПрочитай його, як матимеш час. Якщо не помиляюсь, він від тренерки мисливців Джен'шан. Певно, ти захочеш поговорити з нею.", [3] = "Прочитайте гравійований пергамент і поговоріть з Джен'шан в долині Випробувань.", [4] = "О, нарешті, ти тут. Добре. Джен'шан чекала на тебе.\n\nБагато хто каже, що це простий шлях, та послухай Джен'шан. Се не проста справа — впоратись зі звірами Дуротару та інших земель. Не легше, ніж покорити арканічну магію чи спілкуватись з духами предків.\n\nМо' користування луком чи рушницею не таке небезпечне, як жбурляння вогняних куль. Та не для твоїх ворогів.", [5] = "Як закінчимо розмову — поговори з жителями долини. Вони попросять тебе про допомогу. Се перевірить твою міць та привчить до небезпеки.\n\nЯк наберешся досвіду — приходь до мене. Джен'шан навчить тебе нових навичок та покаже кілька рухів.", ["en"] = "Etched Parchment", ["tasks"] = { ["Etched Parchment"] = "гравійований пергамент", ["Etched Parchment (Provided)"] = "гравійований пергамент (видано)" } },
    [3088] = { [1] = "Зашифрований пергамент", [2] = "О, {ім'я}! Поки тебе не було, мене попросили передати тобі цей пергамент.\n\nПрочитай його, як матимеш час. Якщо не помиляюсь, він від тренера пройдисвітів, Рваґа. Певно, ти захочеш поговорити з ним.", [3] = "Прочитайте зашифрований пергамент і поговоріть з Рваґом в долині Випробувань.", [4] = "Тсс, не так голосно. Я не довіряю Нартоку. Тому, хто ховається в печері глибше ніж я, не варто довіряти.\n\nСподіваюся, ти без проблем {стать:зорієнтувався:зорієнтувалася}?", [5] = "Оскільки ти знаєш, де я переховуюся, я маю тобі дещо розказати: в Розтрощеній Руці попросили мене приглянути за тобою. Вони хочуть, щоб я почав тебе тренувати та інформувати про те, що їм може знадобитися. Навіть якщо ти поки що не хочеш допомагати їм — що було б безглуздо — я зроблю все можливе, щоб навчити тебе...за невелику плату. Приходь до мене в будь-який час, і ми побачимо, на що ти {стать:здатен:здатна}.", ["en"] = "Encrypted Parchment", ["tasks"] = { ["Encrypted Parchment"] = "зашифрований пергамент", ["Encrypted Parchment (Provided)"] = "зашифрований пергамент (видано)" } },
    [3089] = { [1] = "Рунічний пергамент", [2] = "О, {ім'я}! Поки тебе не було, мене попросили передати тобі цей пергамент.\n\nПрочитай його, як матимеш час. Якщо не помиляюсь, він від тренерки шаманів Шікрік. Певно, ти захочеш поговорити з нею.", [3] = "Прочитайте рунічний пергамент і поговоріть з Шікрік у долині Випробувань.", [4] = "Отже, ти {стать:прийшов:прийшла}. Я вже почала сумніватися, чи ти з'явишся. Я відправила пергамент досить давно, але не була впевнена, що його тобі доставили.\n\nАле досить балачок... Ти тут тому, що {стать:був обраний:була обрана}, щоб стати {стать:духовним провідником:духовною провідницею} нашого народу.", [5] = "Ти будеш {стать:посередником:посередницею} між нами та духами наших предків. Сила стихій буде у твоєму розпорядженні. Перемагати ворогів буде дитячою забавкою, а зцілювати союзників буде так само просто, як дихати. Пам'ятай про це, коли зустрінешся з новими викликами, і повертайся до мене так часто, як тобі захочеться. Я залишуся тут, щоб навчити тебе нових заклинань і наставити на вірний шлях, коли ти будеш {стать:готовий:готова}.", ["en"] = "Rune-Inscribed Parchment", ["tasks"] = { ["Rune-Inscribed Parchment"] = "рунічний пергамент", ["Rune-Inscribed Parchment (Provided)"] = "рунічний пергамент (видано)" } },
    [3090] = { [1] = "Заплямований пергамент", [2] = "О, {ім'я}! Поки тебе не було, мене попросили передати тобі цей пергамент.\n\nЗазвичай я уникаю спілкування з чорнокнижниками, коли це можливо, але я думаю, що тобі слід прочитати його, як матимеш час. Якщо не помиляюсь, він від нового тренера, Нартока. Певно, ти захочеш поговорити з ним.", [3] = "Прочитайте брудний пергамент і поговоріть з Нартоком у Лігві в долині Випробувань.", [4] = "Нарешті, ти {стать:прибув:прибула}... і досить непомітно. Добре.\n\nНаш світ повний йолопів, {ім'я}. Навіть могутній Тралл має недоліки. Він відвертається від сили, яка може допомогти повністю підкорити ці землі! Ми вже не ті, ким маніпулювали істоти з Підсвіття. Ми самі собі господарі. Ми горді... і ми сильні.", [5] = "А тепер і ти {стать:приєднався:приєдналася} до наших рядів. Зрозумій мене правильно, {ім'я}. У тебе є сила, на яку багато хто зазіхає, але це не означає, що тебе легко приймуть. Тралл допускає таких, як ми, до Орґріммару, бо ми все ще його родичі — він не може відвернутися від нас, інакше ми стали б такими ж жалюгідними, як люди, що поневолили його. Я хочу сказати: будь {стать:обережним:обережною}. Ти можеш бути {стать:сильним:сильною}, але якщо ти {стать:дурний:дурна}, то ти все одно, що {стать:мертвий:мертва}.\n\nЯкщо тобі потрібно буде вивчити нові заклинання — повертайся до мене.", ["en"] = "Tainted Parchment", ["tasks"] = { ["Tainted Parchment"] = "заплямований пергамент", ["Tainted Parchment (Provided)"] = "заплямований пергамент (видано)" } },
    [3091] = { [1] = "Проста записка", [2] = "Щойно посланниця шукала тебе, {ім'я}. Здається, її прислав тренер воїнів Гарутт. Якщо ця записка від Гарутта, я б не став зволікати з її прочитуванням.", [3] = "Прочитайте просту записку та поговоріть із Гаруттом Громовим Рогом у таборі Нараче.", [4] = "А, нарешті ти {стать:прийшов:прийшла}, {клас:к}. Я не збрехав у своїй записці, {ім'я}. Ми не настільки відрізняємось від друїдів та шаманів нашого племені, наша порода також є особливою. Ти настільки ж {стать:важливий:важлива}. Ми ті, хто захищає наші кордони, полює на кентаврів та йде на війну.", [5] = "Кожен з нас виконує свою роль у нашому племені. Кожен з нас також повинен пройти через усі обряди. Ніколи не дозволяй своїй гордості казати тобі інакше.\n\nЯ залишаюсь тут, щоб тренувати нових воїнів, які жадають слави битв і які слідують шляхами наших стародавніх предків. Коли ти відчуєш себе {стать:готовим:готовою}, повертайся до мене і я зроблю усе від мене залежне для твого подальшого тренування. Іди з благословенням племені, {ім'я}.", ["en"] = "Simple Note", ["tasks"] = { ["Simple Note"] = "проста записка", ["Simple Note (Provided)"] = "проста записка (видано)" } },
    [3092] = { [1] = "Гравійована записка", [2] = "Щойно посланниця шукала тебе, {ім'я:к}. Здається, її прислав тренер мисливців Ланка. Якщо ця записка від Ланка, я б не став зволікати з її прочитуванням.", [3] = "Прочитайте гравійовану записку та поговоріть з Ланкою Далекострілом у плато Червоної Хмарини.", [4] = "Ласкаво прошу до табору Нараче, {ім'я:к}. Я чув хороші речі про тебе. У тебе сильний родовід і багато старійшин вважають тебе уже достатньо {стать:вправним:вправною}. Але ми це перевіримо.\n\nРівнини Мулґору будуть твоїм домом деякий час і ти {стать:повинен:повинна} якомога краще вивчити їх. Одного дня ти помандруєш до незнайомих країв, щоб опанувати вищі вміння. Ти маєш бути {стать:готовим:готовою} до цього.", [5] = "Це і є моєю роботою — впевнитись, що ти {стать:готовий:готова}, навчаючи тебе основ нашої професії — як приручити звіра, як поцілити з рушниці та багатьох інших навичок, котрі знадобляться тобі.\n\nМисливство є вагомою частиною нашої традиції та історії, {ім'я:к}. Ти маєш добре запам'ятати, що ти — важлива частина племені. Тебе поважатимуть та шануватимуть, якщо ти добре послужиш нашому народу.", ["en"] = "Etched Note", ["tasks"] = { ["Etched Note"] = "гравійована записка", ["Etched Note (Provided)"] = "гравійована записка (видано)" } },
    [3093] = { [1] = "Рунічна записка", [2] = "Щойно посланниця шукала тебе, {ім'я}. Здається, її прислала тренерка шаманів Міла. Якщо ця записка від Міли, я б не став зволікати з її прочитуванням.", [3] = "Прочитайте рунічну записку та поговоріть із Мілою Світанковою Мандрівницею в таборі Нараче.", [4] = "Швидко, як вода падає з неба, ти {стать:з'явився:з'явилася} переді мною. Мене тішить твій поспіх. Це означає, що ти усвідомлюєш важливість нашої зустрічі та свого перебування тут. Я не вождь, але я розумію стихії та говорю з духами нашого народу. Я навчу тебе цього.", [5] = "Ми ще не раз зустрінемося з тобою, і щоразу ти будеш йти від мене трохи {стать:сильнішим:сильнішою}... трохи {стать:підготовленішим:підготовленішою}. Твій дух палатиме подібно до Вічного вогню.\n\nА тепер йди, {ім'я}, і випробуй себе. Повертайся, якщо тобі знадобиться моя допомога.", ["en"] = "Rune-Inscribed Note", ["tasks"] = { ["Rune-Inscribed Note"] = "рунічна записка", ["Rune-Inscribed Note (Provided)"] = "рунічна записка (видано)" } },
    [3094] = { [1] = "Вкрита мохом записка", [2] = "Щойно посланниця шукала тебе, {ім'я:к}. Здається, її прислав тренер друїдів Ґарт. Якщо ця записка від Ґарта, я б не став зволікати з її прочитуванням.", [3] = "Прочитайте вкриту мохом записку та поговоріть з Ґартом Мрякогоном у таборі Нараче.", [4] = "Ти {стать:прийшов:прийшла}. Це добре. Щось тривожить духів наших предків в Мулгорі та за його межами, але ми не можемо зрозуміти, що саме. Відтепер твоїм обов'язком буде спілкування з духами та виконання їх волі. Пам'ятай про це.", [5] = "Хоч ми й маємо багато спільного з нічними ельфами, не чекай від них приязності. Їх засліпила гордість, та нехай це тебе не турбує. Зосередься на вченні Матері-Землі, а я навчатиму тебе в міру твого досвіду.\n\nЗаходь до мене, {ім'я:к}. І ти побачиш, як Матір-Земля щедро винагороджує своїх вірних послідовників.", ["en"] = "Verdant Note", ["tasks"] = { ["Verdant Note"] = "вкрита мохом записка", ["Verdant Note (Provided)"] = "вкрита мохом записка (видано)" } },
    [3095] = { [1] = "Простий сувій", [2] = "А, ось і ти! Поки ти {стать:займався:займалася} бездумною Скарою, тобі принесли цей сувій. Думаю, це щось важливе — на ньому печатка тренера воїнів Даннала. Я б на твоєму місці його негайно прочитав.", [3] = "Прочитайте простий сувій та поговоріть з Данналом Штерном в Смертедзвоні.", [4] = "О, ти {стать:прийшов:прийшла}. Добре. Я чув, що ти не {стать:єдиний:єдина}, хто {стать:уник:уникла} забуття. Ще кілька таких, як ти прямують до міста. Можливо, ця стійкість знадобиться в майбутньому.\n\nМожеш подякувати Сильвані за свою свободу... свободу тіла й душі. Ти звісно нікуди не подінешся від наслідків чуми, та зате ти маєш волю.", [5] = "Я буду тут, завжди готовий навчити тебе новому, як матимеш достатньо досвіду. Приходь коли забажаєш. Грошей я багато не візьму, зате поділюсь цінними знаннями.\n\nА тепер йди і спробуй себе в бою. Чомусь ти навчишся самостійно, з часом, а всьому іншому навчу тебе я. Сильвані знадобляться такі гідні {стать:воїни:воїтельки}, як ти, знай це. Ти станеш опорою нашого спасіння.", ["en"] = "Simple Scroll", ["tasks"] = { ["Simple Scroll"] = "простий сувій", ["Simple Scroll (Provided)"] = "простий сувій (видано)" } },
    [3096] = { [1] = "Зашифрований сувій", [2] = "А, ось і ти! Поки ти {стать:займався:займалася} бездумною Скарою, тобі принесли цей сувій. Думаю, це щось важливе — на ньому печатка тренера пройдисвітів Девіда Тріаса. Я б на твоєму місці його негайно прочитав.", [3] = "Прочитайте зашифрований сувій та поговоріть з Девідом Тріасом в Смертедзвоні.", [4] = "Тож, ти {стать:прийшов:прийшла}? Чудово, нам знадобиться якомога більше пройдисвітів. Тінелови точно захочуть знайти тебе, коли вважатимуть за потрібне, тож не роби помилок та того, про що потім пожалкуєш. Їм потрібні талановиті агенти... а не нишпорки та дурні.", [5] = "Більшу частину свого часу я проводжу тут, у таверні, спостерігаючи за новими обличчями та просто стежачи за перспективними кандидатами. Не сунь носа, куди не слід, і я навчу тебе кількох речей. Приходь до мене, коли ти забажаєш і побачимо, чи {стать:готовий:готова} ти навчитися нових навичок.", ["en"] = "Encrypted Scroll", ["tasks"] = { ["Encrypted Scroll"] = "зашифрований сувій", ["Encrypted Scroll (Provided)"] = "зашифрований сувій (видано)" } },
    [3097] = { [1] = "Священний сувій", [2] = "А, ось і ти! Поки ти {стать:займався:займалася} бездумною Скарою, тобі принесли цей сувій. Думаю, це щось важливе — на ньому печатка тренера жерців Дюстена. Я б на твоєму місці його негайно прочитав.", [3] = "Прочитайте священний сувій та поговоріть з темним священником Дюстеном у церкві Смертодзвону.", [4] = "Тож, між вогнем, чумою, бунтів та іще чого гіршого, до мене {стать:прийшов один:прийшла одна} з \"вірних\". Що ж, дозволь мені привітати тебе, {клас:к}. І дозволь мені пояснити дещо перед тим, як ти вирушиш шукати нові пригоди: Святе Світло забуло про тебе, історії про духів твоїх пращурів — казочки, а істоти з Підсвіття не хочуть тебе.\n\nРозумієш мене?", [5] = "Є лише одна річ, яку ти {стать:повинен:повинна} знати: ми вижили лише завдяки своїй волі. Саме віра у власні сили відрізняє нас від інших, з нашими силами ми зможемо змінити весь Азерот. Слабші прийдуть, щоб покластися на тебе. Прокажені будуть називати тебе {стать:мілордом:міледі}. А невігласи шукатимуть у тебе настанови. Мій обов'язок — переконатися, що у тебе є все необхідне, щоб ти {стать:був готовим:була готовою}, коли настане час. Коли наберешся досвіду — знайди мене. Я навчу тебе більшого, коли ти будеш {стать:готовий:готова}.", ["en"] = "Hallowed Scroll", ["tasks"] = { ["Hallowed Scroll"] = "священний сувій", ["Hallowed Scroll (Provided)"] = "священний сувій (видано)" } },
    [3098] = { [1] = "Гліфічний сувій", [2] = "А, ось і ти! Поки ти {стать:займався:займалася} бездумною Скарою, тобі принесли цей сувій. Думаю, це щось важливе — на ньому печатка тренерки магів Ізабелли. Я б на твоєму місці його негайно прочитав.", [3] = "Прочитайте гліфічний сувій та поговоріть з Ізабеллою у церкві Смертедзвону.", [4] = "Я знав, що ти прийдеш до мене, {ім'я:к}. Не тому, що ти не маєш волі йти своїм власним шляхом, але тому, що ми подібні духом. Ми обидва відчули біль, ми обидва страждали. І зараз ми хочемо здобути силу, щоб повернути те, що належить нам: нашу землю, наше життя, нашу долю. Але тобі ще багато чому потрібно навчитись.", [5] = "Тобі треба частіше навідувати мене, якщо ти хочеш стати достатньо {стать:сильним:сильною}, щоб знищити тих, хто буде нам протистояти. Правила магії все ще стосуються тебе, {ім'я:к}. Ти все ще будеш помічати, що скверна слідує за тобою, як голодні вовки вночі. Ти помітиш, що її ласка нічим не відрізняються від залежності. Але ці речі можна стримувати. Скверна буде контролювати тебе лише якщо ти дозволиш їй це зробити.\n\nМожеш йти. Повертайся до мене, коли станеш {стать:могутнішим:могутнішою}.", ["en"] = "Glyphic Scroll", ["tasks"] = { ["Glyphic Scroll"] = "гліфічний сувій", ["Glyphic Scroll (Provided)"] = "гліфічний сувій (видано)" } },
    [3099] = { [1] = "Заплямований сувій", [2] = "А, ось і ти! Поки ти {стать:займався:займалася} бездумною Скарою, тобі принесли цей сувій. Думаю, це щось важливе — на ньому печатка тренера чорнокнижників Максимільйона. Я б на твоєму місці його негайно прочитав.", [3] = "Прочитайте замащений сувій та поговоріть з Максимільйоном в Смертедзвоні.", [4] = "Я вітаю тебе, {стать:брате:сестро}. Я знав, що ти прийдеш. Це було лише питання часу.\n\nТе, що я сказав, зацікавило тебе, чи не так? Я зачепив за живе... щось всередині тебе знало, що те, що я сказав, було правдою. Що ж, добре.\n\nАле знай: я не зрадник Сильвани. Якщо вже на те пішло, вона сама визнала б мою правоту, тому що її власні погляди поставили відречених в те положення, у якому вони знаходяться зараз.", [5] = "Я згадував, що раб завжди залишається рабом, хто б не був господарем. Пам'ятаєш? Ми обоє знаємо, що саме такий контроль — саме така влада — кличе нас. Ми прагнемо, щоб створіння служили нам. Ми знаємо, що ми сильніші й заслуговуємо на більшу повагу, ніж дають нам інші... і тепер ми прагнемо взяти своє.\n\nЯ буду твоїм союзником у цій боротьбі — боротьбі за нашу власну свободу. Свободу шукати наші власні союзи. Коли ти будеш {стать:готовий:готова} — повертайся до мене, і я навчу тебе всього, що знаю.", ["en"] = "Tainted Scroll", ["tasks"] = { ["Tainted Scroll"] = "заплямований сувій", ["Tainted Scroll (Provided)"] = "заплямований сувій (видано)" } },
    [31] = { [1] = "Водна форма", [2] = "Ти {стать:завершив:завершила} навчання, яке проходять всі друїди-початківці перед тим, як зможуть опанувати водну форму. Тепер повертайся до свого наставника, Турака Рунного Тотема в Громовий Бескид. Покажи йому цю підвіску і доведи, що ти {стать:готовий:готова} засвоїти його уроки. Він завершить твоє навчання, завдяки цьому ти станеш одним цілим з водою.\n\nПрощавай, {стать:юний:юна} {клас:к}. Ми ще зустрінемось.", [3] = "Поверніться до Громового Бескиду і покажіть Тураку Рунному Тотему підвіску Морського Лева.", [4] = "До мене дійшов слух про твоє провісне повернення до Громового Бескиду, однак я хочу побачити докази того, що ти {стать:засвоїв:засвоїла} уроки Місячної галявини, перш ніж почну вчити тебе приймати водяну форму.\n\nЧи є у тебе підвіска морського лева?", [5] = "Чудово, {ім'я:к}. Твої предки пишалися б твоїми успіхами! Ти {стать:готовий:готова} прийняти водну форму і я з радістю тебе цьому навчу.\n\nТакож, прийми цю річ в знак визнання твоїх успіхів у двох випробуваннях. Сподіваюсь, це буде приємним доповненням до твого спорядження у якості {стать:захисника природи та хранителя:захисниці природи та берегині} рівноваги.", ["en"] = "Aquatic Form", ["tasks"] = { ["Pendant of the Sea Lion"] = "підвіска Морського Лева", ["Pendant of the Sea Lion (Provided)"] = "підвіска Морського Лева (видано)" } },
    [3121] = { [1] = "Дивне прохання", [2] = "Нііру Вогняне Лезо в Орґріммарі має те, що мені потрібно для роботи! Він зробив суміш, яка мені потрібна для... ну, ти побачиш.\n\nШвидше вирушай до Орґріммару. Ось, візьми це з собою. Це всохла голова, яку я обіцяв Нііру в обмін на трави. Це голова якогось бідолахи дворфа, на якого я нарвався в лісі. Я впевнений, що Нііру буде задоволений.\n\nТи знайдеш Нііру в Розколині Тіні.", [3] = "Віднесіть всохлу голову Нііру Вогняному Лезу в Орґріммар.", [4] = "Так?", [5] = "Я чекав, коли Узер'і надішле це...\n\nДозволь віддати тобі трав'яну суміш, який я приготував для його... ну, експериментів...", ["en"] = "A Strange Request", ["tasks"] = { ["A Shrunken Head"] = "всохла голова", ["A Shrunken Head (Provided)"] = "всохла голова (видано)" } },
    [3122] = { [1] = "Повернення до знахаря Узер'і", [2] = "Ось трави, {ім'я}. Віднеси їх знахареві Узер'і.\n\nБудь ласка, скажи йому, що я задоволений всохлою головою.", [3] = "Доставте мішечок трав Нііру знахареві Узер'і в Фералас.", [4] = "Ти {стать:розмовляв:розмовляла} з Нііру?", [5] = "Це саме те, що мені потрібно, щоб виготовити посудину зменшення, {ім'я}. Незабаром ми побачимо, чи мої останні заклинання виявляться настільки сильними, як я сподівався.\n\nЗачекай, будь ласка. Я маю провести ритуал і використати трави...", ["en"] = "Return to Witch Doctor Uzer'i", ["tasks"] = { ["Neeru's Herb Pouch"] = "мішечок трав Нііру", ["Neeru's Herb Pouch (Provided)"] = "мішечок трав Нііру (видано)" } },
    [3123] = { [1] = "Випробування посудини", [2] = "Це буде випробуванням як для ритуалу, який я провів, так і для твоїх здібностей. Візьми цю посудину, {ім'я}. З її допомогою ти зможеш зменшити та помістити створіння всередину.\n\nЇдь у Внутрішні землі та знайди створінь, відомих як дикі совухи, які колись були улюбленцями богині нічних ельфів Елуни. Злі, примітивні або дикі совозвірі — твої цілі, {ім'я}. Вбий десятьох з них і використовуй посудину зменшення, щоб зменшити та захопити їх, перш ніж їхні духи втечуть.", [3] = "Відправляйтеся у Внутрішні землі та знайдіть совозвірів. Вбийте 10 і використовуйте посудину зменшення, щоб зменшити та захопити совозвірів.\n\nПринесіть 10 зменшених совозвірів і посудину зменшення знахареві Узер'і в Фералас.", [4] = "Ти {стать:зміг:змогла} спіймати совозвірів?\n\nЯкщо тобі це вдасться, ми зможемо підкоряти собі інших істот у Фераласі.", [5] = "Після насильницької смерті дух істоти може втекти й шукати помсти. Зменшення істот, як це {стать:зробив:зробила} ти, {ім'я}, не дає духу втекти. Тепер ми можемо використовувати його як завгодно!", ["en"] = "Testing the Vessel", ["tasks"] = { ["Wildkin Muisek"] = "зменшений совозвір", ["Wildkin Muisek (Provided)"] = "зменшений совозвір (видано)", ["Wildkin Muisek Vessel"] = "посудина зменшення совозвірів", ["Wildkin Muisek Vessel (Provided)"] = "посудина зменшення совозвірів (видано)" } },
    [3124] = { [1] = "Зменшені гіпогрифи", [2] = "Оскільки ти {стать:довів:довела} свою надійність та здібність використовувати посудину зменшення, я хочу, щоб ти {стать:захопив:захопила} інших створінь.\n\nГіпогрифи були вірними компаньйонами нічних ельфів протягом багатьох років. Їхні духи вірні та незламні.\n\nТвоє завдання — вбити 10 тертопір'їстих гіпогрифів, та якомога швидше зменшити та захопити їх посудиною зменшення, щоб їх дух був збережений. Ти знайдеш їх у Безкрайній глушині, на південь звідси.", [3] = "Вбийте 10 тертопір'їстих гіпогрифів будь-якого виду, а потім використовуйте посудину зменшення, щоб зменшити та захопити їх.", [4] = "Вдалося захопити душі гіпогрифів?", [5] = "Якщо ми дозволимо духу вбитої тварини втекти, він може прийняти форму ще більшої істоти. Ми ніколи не зможемо сховатися від його помсти.\n\nЦе небезпечна робота, {ім'я}. І ти знову добре її {стать:виконав:виконала}.", ["en"] = "Hippogryph Muisek", ["tasks"] = { ["Hippogryph Muisek"] = "зменшений гіпогриф", ["Hippogryph Muisek (Provided)"] = "зменшений гіпогриф (видано)", ["Hippogryph Muisek Vessel"] = "посудина зменшення гіпогрифів", ["Hippogryph Muisek Vessel (Provided)"] = "посудина зменшення гіпогрифів (видано)" } },
    [3125] = { [1] = "Зменшені чарівні дракончики", [2] = "{ім'я}, наступне створіння яке я попрошу тебе захопити, на перший погляд, може виглядати досить крихітним і невинним, але його потужний дух — це те, що нам потрібно. Чарівні дракончики, про яких я говорю, були союзниками нічних ельфів. Ми повинні захопити їх, щоб Орда також могла скористатися цією силою духу.\n\nОсь посудина зменшення, {ім'я}. Вбий 8 райдужних хамелеонів або райдужних дракончиків і захопи їхні душі. Їх можна знайти на заході звідси.", [3] = "Вбийте 8 райдужних хамелеонів або райдужних дракончиків. Використовуйте посудину зменшення, щоб зменшити та захопити їх.", [4] = "Вдалося захопити душі чарівних дракончиків?", [5] = "Дякую тобі, {ім'я}. Тепер нам буде доступна сила духу чарівних дракончиків.\n\nСподіваюся, ти не відмовишся виконати для мене ще одне завдання.", ["en"] = "Faerie Dragon Muisek", ["tasks"] = { ["Faerie Dragon Muisek"] = "зменшений чарівний дракончик", ["Faerie Dragon Muisek (Provided)"] = "зменшений чарівний дракончик (видано)", ["Faerie Dragon Muisek Vessel"] = "посудина зменшення чарівних дракончиків", ["Faerie Dragon Muisek Vessel (Provided)"] = "посудина зменшення чарівних дракончиків (видано)" } },
    [3126] = { [1] = "Зменшені деревані", [2] = "Наступною ціддю, {ім'я}, є мандрівні лісові деревані, яких можна знайти в лісі. Вони — союзники нічних ельфів союзників у боротьбі проти Орди. Вони дещо повільні, але як захисники вони незамінні.\n\nНезабаром ми зможемо використати цю силу на свою користь.\n\nЗнайди 3 мандрівних лісових дереванів, вбий їх та використовуй цю посудину зменшення, щоб зменшити та захопити їх.", [3] = "Вбийте 3 мандрівних лісових дереванів. Використовуйте посудину зменшення, щоб зменшити та захопити їх.", [4] = "Вдалося захопити мандрівних лісових дереванів?", [5] = "Дякую тобі, {ім'я}. Наша колекція духів майже завершена.", ["en"] = "Treant Muisek", ["tasks"] = { ["Treant Muisek"] = "зменшений деревань", ["Treant Muisek (Provided)"] = "зменшений деревань (видано)", ["Treant Muisek Vessel"] = "посудина зменшення дереванів", ["Treant Muisek Vessel (Provided)"] = "посудина зменшення дереванів (видано)" } },
    [3127] = { [1] = "Зменшені гірські велетені", [2] = "Останнє твоє завдання — вирушити на північний захід та відшукати останню ціль.\n\nГірські велетні вийшли з гір, щоб допомогти нічним ельфам, коли Палаючий Легіон прийшов у наш світ. Ти впізнаєш велетнів за їх величезним розміром та тремтінням землі, коли вони проходять поблизу.\n\nЯ жадаю використовувати таку силу. Вбий 7 гірських велетнів, а потім скористайся посудиною зменшення, щоб захопити їхні потужні душі.", [3] = "Вбийте 7 сухопутних ходаків або скельних велетнів. Використовуйте посудину зменшення, щоб зменшити та захопити їх.", [4] = "Вдалося захопити душі гірських велетнів?", [5] = "Тільки уяви собі, {ім'я}, якими можливостями ми тепер володіємо! З тими матеріалами, які тобі вдалося зібрати, я зможу скільки завгодно ловити душі цих створінь.", ["en"] = "Mountain Giant Muisek", ["tasks"] = { ["Mountain Giant Muisek"] = "зменшений гірський велетень", ["Mountain Giant Muisek (Provided)"] = "зменшений гірський велетень (видано)", ["Mountain Giant Muisek Vessel"] = "посудина зменшення гірських велетнів", ["Mountain Giant Muisek Vessel (Provided)"] = "посудина зменшення гірських велетнів (видано)" } },
    [3128] = { [1] = "Природні матеріали", [2] = "Мені знадобляться певні матеріали, щоб завершити справу... Ти можеш збирати їх одночасно з виконанням інших моїх завдань.\n\nМені знадобляться розколоті колоди дереванів Фераласа. Вкриті кіркою мінерали можна знайти у гірських велетнів і чарівних дракончиків на заході. Також мені потрібні еластичні сухожилля, які можна знайти у совозвірів у Внутрішніх землях або у гіпогрифів Фераласа. Ще мені знадобиться велика кількість металевих фрагментів від будь-яких з цих істот.", [3] = "Принесіть 2 розколоті колоди, 6 вкритих кіркою мінералів, 20 еластичних сухожиль і 40 металевих фрагментів знахареві Узер'і в табір Мохаче.", [4] = "Ти {стать:зміг:змогла} зібрати всі необхідні мені матеріали?", [5] = "Чудово! Ці матеріали в поєднанні з духами істот повинні дати саме ті результати, які нам потрібні.", ["en"] = "Natural Materials", ["tasks"] = { ["Encrusted Minerals"] = "вкритий кіркою мінерал", ["Encrusted Minerals (Provided)"] = "вкритий кіркою мінерал (видано)", ["Metallic Fragments"] = "металеві фрагменти", ["Metallic Fragments (Provided)"] = "металеві фрагменти (видано)", ["Resilient Sinew"] = "еластичне сухожилля", ["Resilient Sinew (Provided)"] = "еластичне сухожилля (видано)", ["Splintered Log"] = "розколота колода", ["Splintered Log (Provided)"] = "розколота колода (видано)" } },
    [3129] = { [1] = "Зброя духу", [2] = "Вселити дух істоти в зброю — складний процес. Тепер, коли у мене є всі необхідні матеріали та духи істот, яких ти {стать:спіймав:спіймала}, я можу почати. Зачекай, будь ласка, я повернуся за мить.", [3] = "Знахар Узер'і просить вас зачекати, поки він робить зброю.", [5] = "Як я й обіцяв, у тебе є вибір, {ім'я}. Душі істот були назавжди запечатані у цій зброї.\n\nТепер ти можеш володіти їхньою силою, як своєю власною. Використовуй її з розумом.", ["en"] = "Weapons of Spirit" },
    [32] = { [1] = "Нашестя силітидів", [2] = "Ось твій звіт. Я раджу тобі передати цей звіт кому-небудь, хто має практичні знання у цій справі.\n\nЯ знаю троля-науковця, на ім'я Зілзібін Ударник. Він провів багато часу, вивчаючи форми життя, що є унікальними для екології Азероту, а ще він історик! Якщо ти хочеш, щоб хтось допоміг з'ясувати, що саме є цією загрозою, і, що ще важливіше, як зупинити її — передай йому звіт. Нам потрібна допомога.\n\nВостаннє я чув, що він знаходиться на другому ярусі Тракту, що в Орґріммарі.", [3] = "Віднесіть звіт про дослідження комах Зілзібіну Ударнику в Орґріммар.", [4] = "Вибач, я тебе не знаю... але, судячи з усього, ти про мене щось {стать:чув:чула}. Тож, чим я можу тобі допомогти? У тебе є щось для мене?", [5] = "Цей звіт... Я вже мав справу з цими істотами. Шипохідник вчинив мудро, відправивши тебе до мене.\n\nЦі істоти швидко поглинули б пустелю Танаріс; вони є однією з найбільших загроз, з якими ми всі коли-небудь стикалися. Запам'ятай цю назву, {ім'я}: силітиди. Ці комахи, що згадуються тут, є силітидами, і вони є інструментом однієї з найбільших загроз, з якими зіткнуться як Орда, так і Альянс.\n\nЯкби ж ми були достатньо розумними, щоб зрозуміти це раніше.", ["en"] = "Rise of the Silithid", ["tasks"] = { ["Insect Analysis Report"] = "звіт про дослідження комах", ["Insect Analysis Report (Provided)"] = "звіт про дослідження комах (видано)" } },
    [3221] = { [1] = "Розмова з Ренферрелом", [2] = "Поки ти там {стать:займався:займалася} допомогою нашим смертоловам, аптекар Ренферрел хотів тебе бачити. Він не розповів мені подробиць, але хотів поговорити з тобою про вовчі серця, які ти йому {стать:дав:дала}.", [3] = "Поговоріть с аптекарем Ренферрелом у Крипті.", [5] = "О, дуже добре. Є справа, яка стосується сердець вовків, що ти {стать:приніс:принесла} мені раніше, і вона вимагає нашої уваги.", ["en"] = "Speak with Renferrel" },
    [3261] = { [1] = "Джорн Небесний Провидець", [2] = "Твій час зі мною закінчився, {Ім'я}. Тобі потрібно піти до табору Таурахо на південь і поговорити з Джорном Небесним Провидцем, щоб вчитися далі. Він продовжить наставляти тебе.", [3] = "Поговоріть з Джорном Небесним Провидцем у таборі Таурахо.", [5] = "Мої вітання, {стать:юначе:юнко}! Ти тут, щоб іти шляхом мисливства?\n\nЧудово. Розпочнімо ж.", ["en"] = "Jorn Skyseer" },
    [3281] = { [1] = "Вкрадене срібло", [2] = "Може ти й {стать:вбив:вбила} рапторів, та вкрадене ними срібло необхідно повернути! У мене є дані, що ящери гніздяться на південь від Брашпиля, у місці, що називається долиною рапторів. Цілком ймовірно, що вони потягли наше вкрадене срібло саме туди.\n\nВирушай в це лігво рапторів і пошукай наше срібло. Як знайдеш — повертайся з ним до мене.", [3] = "Принесіть вкрадене срібло Ґазроґу на Перехрестя.", [4] = "{стать:Знайшов:Знайшла} срібло?", [5] = "Ага! Отже, раптори все ж сховали срібло у своєму лігві. Важко зрозуміти, навіщо цим звірям срібло. Можливо, байки про їхній інтелект не такі вже й далекі від істини!\n\nДякую, {ім'я}. Прийми це як нагороду за твої послуги та знай, що вартові перехрестя отримають свою виплату завдяки тобі.", ["en"] = "Stolen Silver", ["tasks"] = { ["Stolen Silver"] = "вкрадене срібло", ["Stolen Silver (Provided)"] = "вкрадене срібло (видано)" } },
    [3301] = { [1] = "Мура Рунний Тотем", [2] = "Моя одноплемінниця, Мура Рунний Тотем, вирушила до Срібнохвою, щоб допомогти нашим невмерлим союзникам. Срібнохвой — хворий, вмираючий ліс, і Мура сподівалася дати йому нове життя. Можливо, дивна живність Степів допоможе їй у роботі в Срібнохвої.\n\nВізьми зразок здобутих тобою панцирів і віднеси його Мурі в Срібнохвой. Вона зупинилася в Крипті. Якщо пощастить, оглянувши панцир, вона зможе придумати, як зцілити це хворе місце.", [3] = "Поговоріть з Мурою Рунним Тотемом в Крипті.", [4] = "Від тебе пахне пилом Степів, {клас:к}. Ти {стать:прийшов:прийшла} здалеку.", [5] = "А це що? Цей панцир світиться зсередини, немов у ньому, як і раніше, жевріє життя. Дивовижно! Я маю ретельніше вивчити його.\n\nДякую, {ім'я}. Якщо пощастить, цей панцир розкриє секрет зцілення земель Срібнохвою.", ["en"] = "Mura Runetotem", ["tasks"] = { ["Sample Snapjaw Shell"] = "зразок панцира тріскощелепа", ["Sample Snapjaw Shell (Provided)"] = "зразок панцира тріскощелепа (видано)" } },
    [3341] = { [1] = "Нести погибель", [2] = "В Степах знаходяться жахливі тернові зарослі, що називаються норами Бритвоболотих. Спершу ми думали, що вони не несуть великої загрози, та наші нещодавні відкриття значно серйозніші...\n\nСвинобрази з нір Бритвоболотих об'єднались зі Скарою. Тепер ними керує ліч, на ім'я Амненнар Стужевій, контролюючи кожен їх рух.\n\nАмненнар має прямий телепатичний зв'язок з Нер'зулом. Ми маємо обірвати його, {ім'я}. Поклади кінець Стужевію.", [3] = "Ендрю Браунелл просить вас вбити Амненнара Стужевія і принести його череп.", [4] = "Це надзвичайно важливо, {ім'я}. Ми маємо завадити Скарі зміцнити свої ряди.", [5] = "Вірність ліча непохитна, {ім'я}. Та ти {стать:показав:показала} їм, до чого це приводить.", ["en"] = "Bring the End", ["tasks"] = { ["Skull of the Coldbringer"] = "череп Стужевія", ["Skull of the Coldbringer (Provided)"] = "череп Стужевія (видано)" } },
    [3369] = { [1] = "У кошмарах", [2] = "Цей уламок зберігає великі секрети. Це істинне єство Смарагдового Сну. Однак те, що я бачу в ньому — зовсім не сон. Дехто називає такі видіння кошмаром.\n\nНе хочу тебе хвилювати, {ім'я}, але я вважаю, що якнайкраще буде віддати цей уламок в руки мудрого друїда, і якнайшвидше.\n\nГамуул Рунний Тотем у Верхів'ї Старійшин — це саме той, кого потрібно знайти. Вирушай до Громового Бескиду. На жаль, я більше нічого не можу сказати.", [3] = "Принесіть уламок кошмару Гамуулу Рунному Тотему на Верхів'я Старійшин.", [4] = "Чим можу тобі допомогти?", [5] = "Фалла послала тебе до мене? Ану-ну, подивімось на той уламок, що, як ти кажеш, так її наполохав...\n\n<Гамуул вглядається в уламок>\n\nО... Я не... Ну.\n\n{ім'я}, дякую, що ти {стать:приніс:принесла} мені це. Необачно обговорювати подібні речі, але я все-таки, дам тобі одну пораду. Не варто тобі перейматися цією справою.\n\nСкажімо так: в Смарагдовому Сні все виявляється зовсім не так, як ми вважали...\n\nМожливо, у майбутньому наші з тобою шляхи знову перетнуться.", ["en"] = "In Nightmares", ["tasks"] = { ["Nightmare Shard"] = "уламок кошмару", ["Nightmare Shard (Provided)"] = "уламок кошмару (видано)" } },
    [3376] = { [1] = "Розтрощити Гостроікло!", [2] = "{Ім'я}... я чула про тебе, {стать:новачок:новенька}. Можливо, ти {стать:той:та}, хто допоможе нам там, де інші зазнали невдачі.\n\nМи, таурени, не без втрат заснували домівку в цих землях. Щетиношкурі свинобрази з ущелини Лезожини під командуванням вождя Гостроікла Колючкошкура, ускладнили нам життя своєю тривалою війною. Я покладаю на тебе відповідальність принести мені його голову!\n\nТи знайдеш його у долині на сході, у їхньому поселенні.", [3] = "Принесіть голову вождя Гостроікла Колючкошкура сміливиці Вітряній Пір'їні на плато Червоної Хмарини.", [4] = "Гостроікло більше нас не потривожить, як тільки ти принесеш мені доказ його смерті. Мені потрібна його голова, {Ім'я}.\n\nМи, таурени, живемо з мисливства, і немає більш славетного полювання, ніж на спроможних вполювати нас. Якщо в тебе все пройде успішно, {стать:юначе:дівчино}, ти зрозумієш, про що я.", [5] = "Завдяки твоїм швидким діям, {Ім'я}, сьогодні ми досягли справедливості. Нехай це буде попередженням для всіх, хто загрожуватиме нашому дому.\n\nТи {стать:заслужив:заслужила} цю нагороду. Вона має стати тобі у нагоді, {клас:к}.", ["en"] = "Break Sharptusk!", ["tasks"] = { ["Chief Sharptusk Thornmantle's Head"] = "голова вождя Гостроікла Колючкошкура", ["Chief Sharptusk Thornmantle's Head (Provided)"] = "голова вождя Гостроікла Колючкошкура (видано)" } },
    [3380] = { [1] = "Затонулий храм", [2] = "{ім'я}, цей світ сповнений неспокійними духами. Серед них є такі, що були ув'язнені в місцях з древнім злом...\n\nЯ чув про місце, яке лежить глибоко під поверхнею землі — вигнане туди силами, яких я ніколи не бачив.\n\nЯкщо ти хочеш дізнатися більше про це місце — Затонулий Храм, знайди гобліна, на ім'я Марвон Заклепник. Він досліджував багато стародавніх регіонів світу, і востаннє, як відомо, покинув свій дім у Брашпилі, щоб дослідити руїни тролів у Танарісі.", [3] = "Знайдіть Марвона Заклепника в Танарісі.", [5] = "Так, Затонулий храм, можу сказати, що бачив його на власні очі. Можливо, ти {стать:хотів би:хотіла б} почути про нього більше?\n\nТи {стать:схожий:схожа} на {стать:любителя:любительку} пригод — я знаю дещо, що зможе тебе зацікавити...", ["en"] = "The Sunken Temple" },
    [3504] = { [1] = "Зрадниця", [2] = "Зрадниця і злодійка! Інших слів для неї у мене немає!\n\nЯ зробив велику помилку, {ім'я}. Я довірився ельфі крові!\n\nВона запевняла, що в Азшарі лежать великі багатства... могутні артефакти. Я мав лише відправити з нею кількох воїнів для охорони, і отримав би свою долю. Та я залишився в дурнях — вона їх усіх вбила.\n\nЯ жадаю помсти, {ім'я}, але вже не можу послати туди інших воїнів. Знайди Аґ'тора у Хоробрині, на північ від табору Гальдаррів. Він розповість, що робити далі.", [3] = "Передайте запечатаний лист Аґ'тору Кровокулаку в Азшару.", [4] = "Ах, Белґром нарешті наважився послати нам на допомогу когось не зі своїх, еге?\n\nУ цьому таборі колись було з десяток воїнів, {ім'я}, але тепер вони всі мертві. Ця чаклунка, Рімторі, вбила їх усіх. Вона обвела Белґрома навколо пальця... навіть спокусила його. Це не моя справа, але між нами кажучи, вона ще те стерво. Напевно, тому я все ще тут і допомагаю Белгрому — на його місці я б, напевно, зробив те ж саме.", [5] = "Ми відправили на неї та її поплічників всіх, кого мали, але вони занадто сильні. Нікому не вдалось повернутися. Я думаю, що більшість з них загинули, та впевнений, що деякі просто втекли... боягузи.\n\nАле тепер, коли прибуло підкріплення, можливо, ми зможемо покарати її за брехню та зраду.\n\nЩо скажеш, ти з нами?", ["en"] = "Betrayed", ["tasks"] = { ["Sealed Letter to Ag'tor"] = "запечатаний лист до Аґ'тора", ["Sealed Letter to Ag'tor (Provided)"] = "запечатаний лист до Аґ'тора (видано)" } },
    [3505] = { [1] = "Зрадниця", [2] = "Я так і думав.\n\nМи почнемо похід проти її поплічників уздовж південних урвищ на північному півострові Азшари. Вбивай їх без жалю — нехай знають, що зрадили не тих.\n\nПоки що не турбуйся щодо неї — вона проводить більшу частину часу зі своїми охоронцями, нишпорячи Азшарою. Після того, як вб'єш її поплічників, знайти її табір. Потрібно спочатку розвідати можливості нападу на неї. Можливо, там є щось, за допомогою чого можна виманити її з табору.", [3] = "Вбийте 10 ельфів крові-відновників та 10 ельфів крові-землемірів, після чого розшукайте табір чаклунки Рімторі. У таборі знайдіть що-небудь цінне для чаклунки, щоб викликати її на бій.", [4] = "На чорній шкіряній обкладинці золотом викарбувано назву книги — \"калдорайський фоліант виклику\". Відкривши книгу, ви бачите, що вона дуже стара, але досі в чудовому стані.\n\nСхоже, що текст написаний якоюсь давньою мовою... можливо, калдорайською?\n\nІнтуїція підказує, що краще повернутися сюди, після того, як ви покінчите з ельфами крові.", [5] = "Ви починаєте гортати фоліант, поки знаходите сторінку, закладену тонкою смужкою чорного шовку.\n\nНамагаючись розшифрувати незрозумілі слова, ви бачите внизу однієї зі сторінок схему. Оглянувшись, ви розумієте, що кристали, коло і деякі інші предмети на землі розташовані так само як на схемі.", ["en"] = "Betrayed", ["tasks"] = { ["Blood Elf Reclaimer"] = "ельф крові-відновник", ["Blood Elf Reclaimer slain"] = "ельф крові-відновник: убито", ["Blood Elf Surveyor"] = "ельф крові-землемір", ["Blood Elf Surveyor slain"] = "ельф крові-землемір: убито" } },
    [3506] = { [1] = "Зрадниця", [2] = "Ще кілька хвилин роздумів — і на думку спадає кілька ідей: можливо, знищення кристалів спровокує ельфу крові, що зрадила Белґрома?\n\nВи продовжуєте розглядати фоліант і розумієте, що один з кристалів пов'язаний з творцем кола — інші ж пов'язані з чимось набагато зловіснішим.\n\nВи закриваєте книгу і починаєте обдумувати, який з кристалів слід знищити.", [3] = "Знищте арканічний фокусувальний кристал чаклунки Рімторі, після чого вбийте її. Віднесіть голову чаклунки Рімторі до Аґ'тора Кровокулака в Азшару.", [4] = "Як твої успіхи у знищенні зрадників-ельфів крові, {ім'я}?\n\nСподіваюся, тобі вистачить сил поставити цю мерзоту на коліна! За все, що вона накоїла, вона заслуговує найболючішої смерті!", [5] = "Р-р-р!! Неймовірно!\n\nТобі вдалося! Белґром буде радий! Нарешті душі десятків наших воїнів спочиватимуть з миром. Дякую тобі, {ім'я}.", ["en"] = "Betrayed", ["tasks"] = { ["Head of Magus Rimtori"] = "голова чаклунки Рімторі", ["Head of Magus Rimtori (Provided)"] = "голова чаклунки Рімторі (видано)" } },
    [3507] = { [1] = "Зрадниця", [2] = "Повертайся до Белґрома в Орґріммар. Він захоче побачити її голову на власні очі! Ми теж скоро повернемося туди.\n\nАх, це справді прекрасний день. Дякую за допомогу, {ім'я}.", [3] = "Поговоріть з Белґромом Скелебоєм в Орґріммарі.", [4] = "Я пам'ятаю тебе, {клас:к}. Я просив тебе вирушити в Азшару, щоб знищити ту негідницю, що зрадила мене! Здається, ніби це було багато місяців тому. Тільки не кажи мені, що Аг'тор та інші теж мертві!", [5] = "ХА-ХА! Поглянь на себе, жалюгідне дівчисько! Я плюю на твої рештки!\n\nДякую тобі, {ім'я}. Дякую від щирого серця! Це справді чудовий день!\n\nЯ б подарував тобі ціле королівство, якби міг! Але, можливо, тобі вистачить цього?\n\n<Белґром дивиться на голову чаклунки, що зрадила його.>\n\nХа-ха! Дурна ельфа, ось що з тобою стало... в мішку і без тіла! Не треба було зраджувати Белґрома!", ["en"] = "Betrayed", ["tasks"] = { ["Head of Magus Rimtori"] = "голова чаклунки Рімторі", ["Head of Magus Rimtori (Provided)"] = "голова чаклунки Рімторі (видано)" } },
    [3513] = { [1] = "Сувій з рунами", [2] = "Сувій виглядає дуже по-офіційному, щільно обмотаний сріблястою стрічкою. Ви впевнені, що комусь його буде цікаво побачити, але кому?\n\nНа північному кордоні з Ясенеділом стоїть форпост. Якщо інформація в цьому згортку стосується нічних ельфів, то саме туди його і варто віднести.", [3] = "Віднесіть сувій з рунами до північної вартової вежі Степів.", [4] = "Шо це таке?!", [5] = "Ну гаразд... де ти це {стать:знайшов:знайшла}?", ["en"] = "The Runed Scroll", ["tasks"] = { ["Runed Scroll"] = "сувій з рунами", ["Runed Scroll (Provided)"] = "сувій з рунами (видано)" } },
    [3514] = { [1] = "Присутність Орди", [2] = "Цей сувій від тієї підступної дріади Ринтаріель, ключниці лігва Кігтя на Каміннопазуристому піку.\n\nЩо ж, більше вона не зустрінеться з вістовим, у якого ти це {стать:забрав:забрала}, але ми повинні відстояти своє. Орда не потерпить такого нахабства!\n\n{ім'я}, вирушай до лігва Кігтя. Вбий Ринтаріель і встанови там знак, щоб видно було звідусіль. Візьми цей стяг Орди, {ім'я}. Розмісти його в самому лігві Кігтя, щоб наступного разу вони двічі подумали, перш ніж відправити посланця через нашу територію.", [3] = "Убийте ватажка лігва Кігтя, ключницю Ринтаріель.", [4] = "Ми не можемо дозволити Альянсу шастати по нашій території, {ім'я}. Провчи їх як слід!", [5] = "Ну ти {стать:крутий:крута}! Спекатися Ринтаріель в лігві Кігтя - це важливий крок, {ім'я}. Поки вони помалу перегруповуватимуться, по Степах бігатиме менше шпигунів Альянсу. Пройде час, перш ніж вони наважаться відправити наступного.\n\nДякую.", ["en"] = "Horde Presence", ["tasks"] = { ["Rynthariel the Keymaster"] = "ключниця Ринтаріель", ["Rynthariel the Keymaster slain"] = "ключниця Ринтаріель: убито" } },
    [3517] = { [1] = "Вкрадені знання", [2] = "Зізнаюсь, {ім'я}, я використовую своє положення в Азшарі на повну. Покарання Белґрома мало свої плюси.\n\nПеред тим, як я поїхала, я досліджувала регіон, і ти здивуєшся, скільки цінних предметів лежить без господаря.\n\nЯ розповім тобі більше про свої угоди та навіть дам тобі частину з прибутку, якщо допоможеш мені зібрати деякі з них.\n\nУ східній частині руїн Ельдарата є кілька скрижалей, які мені потрібні. Усі чотири названі на честь магів високородних. Знайди їх для мене, і ми обговоримо деталі.", [3] = "Знайдіть скрижаль Бет'Амари, скрижаль Джін'яеля, скрижаль Маркрі та скрижаль Саель'гай, перш ніж повернутися до Джедіґи в Азшару.", [4] = "Скрижалі, які я прошу тебе зібрати, можуть принести гарні гроші, якщо їх продати правильним торговцям. Я скажу тобі, кому їх треба передати, після того, як ти їх знайдеш. Але я не дурепа... ти отримаєш свою частину після того, як я побачу докази їх доставки.\n\nТак що давай, ми не можемо марнувати час. Чи я можу знайти когось іншого, хто допоможе мені.", [5] = "Ідеально, {ім'я}, і вони в хорошому стані. Це повинно принести нам хороший прибуток від усіх зацікавлених сторін.\n\nДавай не будемо затримуватися тут довше, ніж потрібно. Нам треба заробити грошей.", ["en"] = "Stealing Knowledge", ["tasks"] = { ["Tablet of Beth'Amara"] = "скрижаль Бет'Амари", ["Tablet of Beth'Amara (Provided)"] = "скрижаль Бет'Амари (видано)", ["Tablet of Jin'yael"] = "скрижаль Джін'яеля", ["Tablet of Jin'yael (Provided)"] = "скрижаль Джін'яеля (видано)", ["Tablet of Markri"] = "скрижаль Маркрі", ["Tablet of Markri (Provided)"] = "скрижаль Маркрі (видано)", ["Tablet of Sael'hai"] = "скрижаль Саель'гай", ["Tablet of Sael'hai (Provided)"] = "скрижаль Саель'гай (видано)" } },
    [3518] = { [1] = "Доставка Маґаті", [2] = "Першу скрижаль потрібно доставити до тауренки, на ім'я Маґата. Вона є однією зі старійшин у Громовому Бескиді та підтримує союз між тауренами та відреченими. Саме вона більше за інших серед старійшин вірить, що таурени та їхні звичаї можуть допомогти відреченим знайти шлях повернення до людськості.\n\nПринеси їй скрижаль Бет'Амари. Скрижаль може бути тією ланкою, яка їй потрібна, щоб знайти спосіб допомогти відреченим... принаймні, так вона стверджує.", [3] = "Принесіть скрижаль Бет'Амари Маґаті в Громовий Бескид.", [4] = "Так, {ім'я}. Що я можу для тебе зробити? У мене багато важливих справ, тож швидше, будь ласка.", [5] = "А, нарешті, скрижаль Бет'Амари. Я вже думала, що моє партнерство з Джедіґою провалилося, чи бідолашна орчиня знайшла свою смерть в Азшарі. Я рада, що все вдалося.\n\nБет'Амара була однією з найвпливовіших алхіміків високородних. Говорили, що саме ця чарівниця навчилася виконувати трансмутацію металів.", ["en"] = "Delivery to Magatha", ["tasks"] = { ["Tablet of Beth'Amara"] = "скрижаль Бет'Амари", ["Tablet of Beth'Amara (Provided)"] = "скрижаль Бет'Амари (видано)" } },
    [3526] = { [1] = "Гоблінська інженерія", [2] = "Інженери-експерти обирають між двома дисциплінами: гномською та гоблінською інженерією. Очевидно, що гоблінська інженерія — це вибір найталановитіших інженерів. Підкори світ, використовуючи потужну вибухівку та фантастичне спорядження!\n\n{ім'я}, прочитай цей посібник. Якщо ти бажаєш дізнатися більше про гоблінську інженерію, то віднеси цей посібник Ніксу Вертопруженю в Пристроблях. Пам'ятай — зробивши цей вибір, ти не зможеш передумати та вивчати іншу дисципліну, тому переконайся, що ти {стать:впевнений:впевнена} у своєму шляху, перш ніж виконувати його завдання.", [3] = "Якщо ви хочете дізнатися більше про гоблінську інженерію, віднесіть посібник з інженерних дисциплін Ніксу Вертопруженю в Пристроблях.", [4] = "Я відчуваю запах свіжих новобранців так само як чудовий вибуховий порошок — за кілометр. Ти {стать:прийшов:прийшла} сюди, щоб навчитися майстерності виготовлення вибухівки?", [5] = "Ну що ж, {ім'я}, ти {стать:вчинив:вчинила} мудро, звернувшись до мене за наставництвом! Будь-який приблуда може стати експертом в основах інженерії — гноми та їх опромінений дім Гномреґан є свідченням цього. Але для того, щоб володіти дисципліною гоблінської інженерії, потрібен сильний розум і стійка рука (з особливим акцентом на СТІЙКУ).\n\nТримай вуха наготові, {ім'я}, і можливо, ти чогось навчишся.", ["en"] = "Goblin Engineering", ["tasks"] = { ["Manual of Engineering Disciplines"] = "посібник з інженерних дисциплін", ["Manual of Engineering Disciplines (Provided)"] = "посібник з інженерних дисциплін (видано)" } },
    [354] = { [1] = "Смерті в сім'ї", [2] = "Родина Аґамандів була найзаможнішою в Тірісфальському переліссі. Я працював на їхніх млинах... до Чуми.\n\nКоли вперше прийшла Cкара, Аґаманди укріпилися вдома та переконали своїх робітників залишитися і допомогти з обороною. Ми були бовдурами, але, принаймні, вірними бовдурами.\n\nСвоєю гординею Аґаманди прирекли нас на невмерлість. І тепер вони є маріонетками Скари!\n\nПослужи відреченим - знищи Аґамандів, які померли від Чуми. Послужи і мені, принісши мені їхні рештки.", [3] = "Принесіть рештки Ґреґора, рештки Нісси та рештки Турмана до Коулмена Фартинга у Брілль.", [4] = "Ти вже маєш рештки Аґамандів? Ці прокляті чудовиська нарешті знищені?", [5] = "Помста солодка на смак, чи не так? Коли ти {стать:знищував:знищувала} Аґамандів, чи {стать:відчув:відчула} ти хоча б крихту свободи волі у них усередині? Я сподіваюся, що так. Я сподіваюся, що вони відчували страх перед тим, як були спроваджені у забуття.\n\nЦе марна надія, я знаю. Але це надія, яку я все ж плекаю.", ["en"] = "Deaths in the Family", ["tasks"] = { ["Gregor's Remains"] = "рештки Ґреґора", ["Gregor's Remains (Provided)"] = "рештки Ґреґора (видано)", ["Nissa's Remains"] = "рештки Нісси", ["Nissa's Remains (Provided)"] = "рештки Нісси (видано)", ["Thurman's Remains"] = "рештки Турмана", ["Thurman's Remains (Provided)"] = "рештки Турмана (видано)" } },
    [3541] = { [1] = "Доставка Джес'рімону", [2] = "Я маю контакт в Орґріммарі. Він проживає в районі Тракту. Його складно знайти, якщо не знаєш, де шукати, але ти зможеш знайти його в одному з найвищких будинків.\n\nЗроби мені послугу, не кричи про його місцеперебування і про справи по всьому Калімдору — це було б шкідливо і для мене, і для нього.\n\nВін заплатить нам більш ніж справедливу ціну за скрижаль Джін'яеля. Я не знаю, чому, але тобі варто було бачити, наскільки він був захоплений, коли дізнався про її місцеперебування.", [3] = "Принесіть скрижаль Джін'яеля Джес'рімону в Орґріммар.", [4] = "Так, шо тобі треба, мон? У мене сьодні багато справ, про які треба подбать, і тебе серед них нема. Хотя може я найду хвилинку для тебе.", [5] = "А-а-а, Джедіґа одправила свій пакунок аж з Азшари. Добре. Я ждав на нього.\n\nДжедіґа — прекрасна жінка... і смертельно небезпечна. Шо може буть краще?\n\nГлянь на це... скрижаль в ідеальному стані. З тебе вийде {стать:гарний кур'єр:гарна кур'єрка}, {ім'я}.", ["en"] = "Delivery to Jes'rimon", ["tasks"] = { ["Tablet of Jin'yael"] = "скрижаль Джін'яеля", ["Tablet of Jin'yael (Provided)"] = "скрижаль Джін'яеля (видано)" } },
    [3542] = { [1] = "Доставка Андрону Ґанту", [2] = "Мій наступний контакт — Андрон Ґант. Зазвичай він знаходиться в Підмісті, поряд з Апотекарієм.\n\nВін був небагатослівним, коли йшлося про те, для чого йому потрібна скрижаль. Схоже, що деякі маги Підмістя хочуть вивчити кілька арканічних заклинань, які використовували високородні. Вони думають, що ця табличка їм в цьому допоможе. Маркрі був майстром виклику створінь, особливо елементалів.\n\nВіднеси скрижаль Маркрі та повертайся до мене, щоб отримати свою частину винагороди.", [3] = "Принесіть скрижаль Маркрі Андрону Ґанту в Підмістя.", [4] = "Ну... <гик>... оце так несподіванка. {стать:Шукач:Шукачка} пригод... <гик>!\n\nЩо я можу для тебе зробити... <гик>?", [5] = "Ось, візьми монетку... купи собі... <гик>... нові обладунки абощо.\n\nЦе принесе блискучий золотий або два правильним... <гик> торговцям.", ["en"] = "Delivery to Andron Gant", ["tasks"] = { ["Tablet of Markri"] = "скрижаль Маркрі", ["Tablet of Markri (Provided)"] = "скрижаль Маркрі (видано)" } },
    [355] = { [1] = "Розмова з Севреном", [2] = "Ти {стать:приніс:принесла} мені рештки Аґамандів і цим {стать:задовольнив:задовольнила} моє бажання помсти. Але млини Аґамандів є загрозою не лише для мене, а й для усіх відречених.\n\nЯ розповів війту Севрену про твої звитяги проти Аґамандів, і він бажає поговорити з тобою особисто.", [3] = "Поговоріть з війтом Севреном у Бріллі.", [5] = "Коулмен добре відгукується про тебе, {Ім'я}, і про твої успішні набіги на млини Аґамандів.\n\nВідречені знову потрібна твоя допомога...", ["en"] = "Speak with Sevren" },
    [356] = { [1] = "Патруль тилової сторожі", [2] = "Захисники Валу, які обороняють Тірісфаль від Зачумлених земель, постійно насторожі. Проте деколи Скара все ж прослизає повз них.\n\nНаш успіх на Валу залежить від боротьби на одному фронті: ми не можемо дозволити атаки з тилу або відрізання ліній постачання наших оборонців.\n\nДопоможи Валу. Попатрулюй схід і знищ усю Скару, що знайдеш. Особливо зосередься на хуторі Бальнірів — він тепер кишить бродячою падаллю.", [3] = "Убийте 8 кривавих страховищ і 8 блукаючих духів, а потім відзвітуйте Ліннеї в її таборі.", [4] = "Ти вже маєш звіт зі свого патруля?", [5] = "Дуже добре. Твої зусилля значно посприяли стриманню Скари. Я відправлю рекомендацію моєму керівнику, карателю Зиґанду.", ["en"] = "Rear Guard Patrol", ["tasks"] = { ["Bleeding Horror"] = "криваве страховище", ["Bleeding Horror slain"] = "криваве страховище: убито", ["Wandering Spirit"] = "блукаючий дух", ["Wandering Spirit slain"] = "блукаючий дух: убито" } },
    [3561] = { [1] = "Доставка архімагу Зілему", [2] = "Цю останню скрижаль потрібно передати дуже небезпечній особі, {ім'я}. Можеш не сумніватися, я довіряю йому набагато менше, ніж будь-кому з тих, до кого я тебе відправляла.\n\nАрхімаг Зілем має вежу на пагорбах Азшари. Він людина, але вчинки його зовсім не людські... він випромінює силу, і я не смію питати у нього, що він планує робити зі скрижаллю.\n\nВін звернувся до мене, але сказав, що його охоронець Санат допоможе мені дістатися до вежі, коли я буду готова зустрітися з ним. Шукай Саната на півночі.", [3] = "Принесіть скрижаль Саель'гай архімагу Зілему в Азшару.", [4] = "Чим я можу тобі допомогти, {ім'я}?", [5] = "Ах, скрижаль Саель'гай... як давно я мріяв дослідити її.\n\nДякую, {ім'я}. Можеш сказати Джедідзі, що вона добре попрацювала. Це, безумовно, буде коштувати тієї плати, яку вона просила.", ["en"] = "Delivery to Archmage Xylem", ["tasks"] = { ["Tablet of Sael'hai"] = "скрижаль Саель'гай", ["Tablet of Sael'hai (Provided)"] = "скрижаль Саель'гай (видано)" } },
    [3563] = { [1] = "Плата Джес'рімона Джедідзі", [2] = "Однеси цей лист Джедіґі. І передай, шо наша угода була вигодною і я довольний її роботою.\n\nСкажи їй, шоб вона пошвидше поверталася в Орґріммар, і Джес'рімон про неї подбає.\n\nСкажи їй це, і може в майбутньому мені знов знадобляться твої послуги, {ім'я}.", [3] = "Передайте записку Джес'рімона Джедідзі в Азшарі.", [4] = "Ти вже {стать:говорив:говорила} з Джес'рімоном?\n\nВін кнур серед тролів, але його інформація зазвичай точна, а робота добре оплачується.\n\nЯкщо ти зможеш витримати його ставлення, то зможеш заробити непогані гроші на його справах.", [5] = "Судячи з його записки, він був більш ніж задоволений... навіть занадто задоволений.\n\nМожливо, колись я знайду час, щоб переконатися, що він знає, як сильно я ціную його залицяння. Ну, тепер я маю ще одну причину затриматися в Азшарі.\n\nОсь твоя частка нашої оплати.", ["en"] = "Jes'rimon's Payment to Jediga", ["tasks"] = { ["Jes'rimon's Note"] = "записка Джес'рімона", ["Jes'rimon's Note (Provided)"] = "записка Джес'рімона (видано)" } },
    [3565] = { [1] = "Плата Зілема Джедідзі", [2] = "Що? А, так, твоя оплата. Звісно.\n\nВізьми це і йди. Я впевнений, що Джедіґа з нетерпінням чекає на твоє повернення.", [3] = "Передайте записку Зілема Джедідзі в Азшарі.", [4] = "Ну, що сказав Зілем? Він же нічого тобі не зробив? Не зачарував тебе? Не примусив працювати на нього?", [5] = "Ніяких проблем? Зовсім ніяких? Ну, це вже щось... Я очікувала, що він проявить якесь небажання або принаймні розірве нашу угоду. Хм, може, йому все-таки можна довіряти.\n\nНе варто так сильно на цьому зациклюватися. Ось твоя частка. Дякую за допомогу.", ["en"] = "Xylem's Payment to Jediga", ["tasks"] = { ["Xylem's Note"] = "записка Зілема", ["Xylem's Note (Provided)"] = "записка Зілема (видано)" } },
    [357] = { [1] = "Особа ліча", [2] = "Є ліч, який мешкає на острові посеред Ясноводного озера на півночі. Хоча він — відречений з вільною волею, він вважає, що всі інші невмерлі є рабами Скари та наказав своїм прислужникам нападати на будь-кого, хто наблизиться.\n\nАле оскільки він є відреченим, Королева захоче його служби. А якщо він ще і вправний у некромантії, то його знання будуть... досить корисними для нас.\n\nЩоб дізнатися про його особу та навички, я повинен побачити його фоліант. Прокрадися в його табір і роздобудь його, а тоді повертайся до мене.", [3] = "Принесіть фоліант ліча Беторові Кригозламу в Підмістя.", [4] = "{Ім'я}, ти вже {стать:роздобув:роздобула} фоліант?", [5] = "Дуже добре, {Ім'я}. Я вивчу цю книгу та визначу особу цього ліча. Ти добре {стать:послужив:послужила} Королеві.\n\n<Бетор відкриває фоліант та уважно оглядає його сяючі сторінки...>\n\nДивовижно! Принесений тобою фоліант належить нікому іншому, як Ґюнтерові Арканусу!\n\nЗа життя Ґюнтер був вправним некромантом; ми з ним були друзями та товаришами по службі перед Чумою. І, судячи з цього фоліанту, він став навіть ще могутнішим після смерті.\n\nЙого вміння були б для нас великим здобутком.", ["en"] = "The Lich's Identity", ["tasks"] = { ["The Lich's Spellbook"] = "фоліант ліча", ["The Lich's Spellbook (Provided)"] = "фоліант ліча (видано)" } },
    [358] = { [1] = "Мародери", [2] = "Масові поховання південно-західніше пристанища Ґаррена на півночі були місцем для... значної... кількості померлих Тірісфалю, коли прийшла Чума.\n\nПоки що тіла в цих могилах не настигла невмирущість, але Скара тепер посилає гнилошкурих гнолів, щоб зібрати трупи та використати їх для поповнення своєї армії. Цього не можна дозволити!\n\nУ тебе подвійне завдання: знищи Гнилошкурих біля масового поховання та на пристанищі Ґаррена і збери з них бальзамувальну сукровицю, що дає їм життя.", [3] = "Убийте гнилошкурих мародерів і гнилошкурих дворняг.\n\nПринесіть 8 бальзамувальних сукровиць до війта Севрена у Брілль.", [4] = "Твоє завдання виконано? Ти вже {стать:знищив:знищила} цих собакоподібних створінь і {стать:зібрав:зібрала} їхню сукровицю?", [5] = "Майстерна робота, {Ім'я}. Скара помиляється, думаючи, що вона зможе підняти цих мерців проти нас, а рідина, яку ти {стать:зібрав:зібрала} з гнилошкурих рабів, буде вивчена нашими аптекарами. У ній можуть бути приховані таємниці, які ми зможемо використати проти Скари.\n\nЯк я вже говорив, чудова робота. Але наша боротьба продовжується, і вона напевне дасть тобі ще не одну можливість довести свою цінність для відречених.", ["en"] = "Graverobbers", ["tasks"] = { ["Embalming Ichor"] = "бальзамувальна сукровиця", ["Embalming Ichor (Provided)"] = "бальзамувальна сукровиця (видано)", ["Rot Hide Graverobber"] = "гнилошкурий розкрадач могил", ["Rot Hide Graverobber slain"] = "гнилошкурий розкрадач могил: убито", ["Rot Hide Mongrel"] = "гнилошкура дворняга", ["Rot Hide Mongrel slain"] = "гнилошкура дворняга: убито" } },
    [359] = { [1] = "Служба відречених", [2] = "Мені потрібен свіжий звіт із застави Смертестражі на схід звідси.\n\nЯ мушу знати, чи проникли сили Скари крізь Вал у Тірісфаль. Ми повинні дотримуватися пильності на кордоні з Зачумленими землями: не можна дозволити Скарі закріпитись тут!\n\nЙди на південь уздовж дороги, а потім зверни на схід на роздоріжжі, до застави. Поговори зі смертестражем Ліннеєю. У неї є інформація, яка мені треба.", [3] = "Поговоріть зі смертестражем Ліннеєю.", [5] = "Війт Севрен хоче звіт? Звичайно: захисники Валу стримують більшість сил Скари, але деякі все ж просочуються час від часу.\n\nМи спостерігали періодичну активність сил Скари на сході від нашої застави, зосереджену навколо хутора Бальнірів.", ["en"] = "Forsaken Duties" },
    [360] = { [1] = "Повернення до війта", [2] = "Тепер повертайся до війта Севрена з інформацією, що я тобі надала. Він захоче почути її якнайшвидше, тому поспіши.\n\nА якщо побачиш сили Скари по дорозі назад — убий їх: ми не можемо дозволити їм розгулювати по наших землях.", [3] = "Поверніться до війта Севрена у Брілль.", [5] = "Те, що Скара проникає крізь Вал - тривожні новини. Король-ліч та його прислужники не стримуються у своїх нападах.\n\nАле ми не здамося. Він не оволодіє нами знову!", ["en"] = "Return to the Magistrate" },
    [361] = { [1] = "Недоставлений лист", [2] = "Цей лист написаний Турманом, найстаршим сином Ґреґора Аґаманда. Він призначений для Іветт Фартинг. Хоча, схоже, він до неї не дійшов...", [3] = "Знайдіть Іветт Фартинг і віддайте їй лист від Турмана Аґаманда.", [4] = "Так?", [5] = "Ох... мій бідний Турман! Я благала його покинути млини Аґамандів зі мною та моїм батьком, але він був надто відданий своїй сім'ї! Я знала це! Я знала, що Бранд мав намір йому нашкодити! Ох, будь проклята ця Чума та ця Скара!\n\n<Лице Іветт розгладжується та стає холодним.>\n\nАле шкодування - для слабких. Як відречена, я маю нові цілі, і любов - не одна з них. Я дякую тобі за листа, оскільки мені було цікаво, що сталося з моїм колишнім коханням.\n\nАле те життя закінчене. Назавжди.", ["en"] = "A Letter Undelivered", ["tasks"] = { ["Thurman's Letter"] = "лист Турмана", ["Thurman's Letter (Provided)"] = "лист Турмана (видано)" } },
    [362] = { [1] = "Млини примар", [2] = "Девлін Аґаманд був молодшим з двох синів Аґамандів, і не могло бути двох більш несхожих братів при житті. Турман був високим і доброзичливим, а його молодший брат - слабким і мав гострий язик.\n\nКоли на їхні млини прийшла Чума, я не здивувався новинам, що Девлін швидко їй піддався. Його божевільну балаканину досі можна почути біля дороги, що туди веде.\n\nЯ збираю рештки Аґаманідів, і мені потрібен Девлін. Знайди його, вбий і принеси мені його кістки.", [3] = "Вбийте Девліна Аґаманда та принесіть його рештки Коулмену Фартингу в Брілль.", [4] = "{Стать:Знайшов:Знайшла} Девліна?", [5] = "Дякую тобі. Кістки Девліна чудово ляжуть на мою мантію.\n\nЯкщо щось і може зігріти моє серце, то це звістка про знищення Аґамандів. Вони підвели мене та мою сім'ю, коли прийшла Чума - і тепер я присягаюся, що розтопчу їхні рештки власними ногами!", ["en"] = "The Haunted Mills", ["tasks"] = { ["Devlin's Remains"] = "рештки Девліна", ["Devlin's Remains (Provided)"] = "рештки Девліна (видано)" } },
    [363] = { [1] = "Різке пробудження", [2] = "Нарешті ти {стать:прокинувся:прокинулася}. Ми вже думали кинути тебе у вогнище, як інших, але, схоже, ти {стать:оговтався:оговталася}.\n\nЯ — Мордо, наглядач за криптою Смертедзвону. А ти — більше не {стать:раб:рабиня} Короля-ліча.\n\nПоговори із жерцем тіні Сарвісом у каплиці при пагорбі. Він розповість тобі все, що ти тепер мусиш знати.", [3] = "Поговоріть із жерцем тіні Сарвісом.", [5] = "Ще один ходячий мрець, гм? Мабуть, було шокуюче прокинутися у крипті, де тебе привітали лиш холод і Мордо...\n\nЯ бачу розгубленість на твоєму обличчі. Дозволь мені пояснити нашу... ситуацію... тобі.\n\nНас звільнила від контролю Короля-ліча наша нова лідерка - леді Сильвана. Темна Леді веде нас у нашій війні проти ненависної Скари та загонів людей, які нишпорять за кожним нашим кроком.", ["en"] = "Rude Awakening" },
    [3635] = { [1] = "Гномська інженерія", [2] = "Інженери-експерти обирають між двома дисциплінами: гномською та гоблінською інженерією. Хоч я й вважаю це марною тратою часу, ти маєш знати про інженерію гномів. Вони створюють предмети та пристрої, які можуть змінити світ, але рідко працюють.\n\n{ім'я}, прочитай цей посібник. Якщо ти бажаєш навчитися створювати безглузді металеві штуки, то віднеси цей посібник Оґлторпу Обриднусу в Грабіжну Бухту. Пам'ятай — зробивши цей вибір, ти не зможеш передумати та вивчати іншу дисципліну, тому переконайся, що ти {стать:впевнений:впевнена} у своєму шляху, перш ніж виконувати його завдання.", [3] = "Якщо ви хочете дізнатися більше про гномську інженерію, віднесіть посібник з інженерних дисциплін Оґлторпу Обриднусу в Грабіжну Бухту.", [4] = "Вітаннячка! Якщо ти {стать:прийшов:прийшла} з приводу самонавідного робота, що пробив стіну твого будинку, то я заздалегідь перенаправлю тебе до мого адвоката. Якщо ж ні, то чим я можу тобі допомогти сьогодні?", [5] = "Отож, ти {стать:прийшов:прийшла} вчитися гномській інженерії? Чудово, ти {стать:звернувся:звернулася} до правильного гнома. Хоча керівна фракція Гномреґана може використовувати політику для відсторонення тих, кого вони вважають занадто розумним, вони знають, що знання не можна контролювати.\n\nМи з ними чудово розуміємо, що після того, як я залишив Гномреґан, вони втратили одного з найвидатніших гномських інженерів сучасності. Якщо ти {стать:здібний учень:здібна учениця}, я навчу тебе всього, що знаю сам.", ["en"] = "Gnome Engineering", ["tasks"] = { ["Manual of Engineering Disciplines"] = "посібник з інженерних дисциплін", ["Manual of Engineering Disciplines (Provided)"] = "посібник з інженерних дисциплін (видано)" } },
    [3637] = { [1] = "Гномська інженерія", [2] = "Інженери-експерти обирають між двома дисциплінами: гномською та гоблінською інженерією. Хоч я й вважаю це марною тратою часу, ти маєш знати про інженерію гномів. Вони створюють предмети та пристрої, які можуть змінити світ, але рідко працюють.\n\n{ім'я}, прочитай цей посібник. Якщо ти бажаєш навчитися створювати безглузді металеві штуки, то віднеси цей посібник Оґлторпу Обриднусу в Грабіжну Бухту. Пам'ятай — зробивши цей вибір, ти не зможеш передумати та вивчати іншу дисципліну, тому переконайся, що ти {стать:впевнений:впевнена} у своєму шляху, перш ніж виконувати його завдання.", [3] = "Якщо ви хочете дізнатися більше про гномську інженерію, віднесіть посібник з інженерних дисциплін Оґлторпу Обриднусу в Грабіжну Бухту.", [4] = "Вітаннячка! Якщо ти {стать:прийшов:прийшла} з приводу самонавідного робота, що пробив стіну твого будинку, то я заздалегідь перенаправлю тебе до мого адвоката. Якщо ж ні, то чим я можу тобі допомогти сьогодні?", [5] = "Отож, ти {стать:прийшов:прийшла} вчитися гномській інженерії? Чудово, ти {стать:звернувся:звернулася} до правильного гнома. Хоча керівна фракція Гномреґана може використовувати політику для відсторонення тих, кого вони вважають занадто розумним, вони знають, що знання не можна контролювати.\n\nМи з ними чудово розуміємо, що після того, як я залишив Гномреґан, вони втратили одного з найвидатніших гномських інженерів сучасності. Якщо ти {стать:здібний учень:здібна учениця}, я навчу тебе всього, що знаю сам.", ["en"] = "Gnome Engineering", ["tasks"] = { ["Manual of Engineering Disciplines"] = "посібник з інженерних дисциплін", ["Manual of Engineering Disciplines (Provided)"] = "посібник з інженерних дисциплін (видано)" } },
    [364] = { [1] = "Безтямні", [2] = "Ми, відречені, воюємо з армією Короля-ліча, Скарою — піднятими некромантією військами невмерлих, з мерзенними тварюками півночі та змученими духами.\n\nПівнічну частину селища заполонили безтямні, і їх потрібно знищити. Тож знищ їх, не жаліючи, хай як вони й схожі на наших колишніх братів та сестер. Полеглі — лише раби Короля-ліча.", [3] = "Жрець тіні Сарвіс хоче, щоб ви вбили 8 безтямних зомбі та 8 жалюгідних зомбі.", [4] = "Ти недалеко підеш у цьому новому житті, якщо не в змозі вбити навіть найслабших зомбі, {Ім'я}. Не повертайся до мене, доки не впораєшся з ними.", [5] = "На жаль, Скару не можна переманити на наш бік: їхня численність нам би знадобилась у майбутніх битвах.\n\nАле вони до нас не приєднаються, тому в нас немає іншого вибору, окрім як знищити їх.", ["en"] = "The Mindless Ones", ["tasks"] = { ["Mindless Zombie"] = "безтямний зомбі", ["Mindless Zombie slain"] = "безтямний зомбі: убито", ["Wretched Zombie"] = "жалюгідний зомбі", ["Wretched Zombie slain"] = "жалюгідний зомбі: убито" } },
    [3642] = { [1] = "Угода про нерозголошення", [2] = "Гномська інженерія — це теорія інженерії, пристосована до наших потреб! Вона дозволяє нам створювати пристрої, які контролюють світ навколо нас. Це було описано в книжці, яку ти {стать:прочитав:прочитала}.\n\nУ цій книжці також згадується наша давня присяга зберігати секрети наших винаходів. Коли ти стаєш на шлях гномської інженерії, це остаточно — про гоблінську інженерію можеш забути.\n\nЯкщо ти все ще хочеш займатися гномською інженерією — підпиши цю угоду про довічне нерозголошення таємниць, і знову поговори зі мною. Гарненько подумай, {ім'я}.", [3] = "Якщо ви згодні займатися гномською інженерією, підпишіть угоду про нерозголошення і ще раз поговоріть з Оґлторпом Обриднусом в Грабіжній Бухті.", [4] = "Якщо ти {стать:підписав:підписала} документ і {стать:готовий:готова} віддати його мені, то це остаточно.\n\nХоча я й не згоден із політикою Гномреґана — особливо з таким дурнем, як мехмайстер Надспалах — угода про нерозголошення важливіша за такі речі! Ти маєш погодитися присвятити себе одному шляху і слідувати йому протягом усього свого життя.", [5] = "Ласкаво просимо, {ім'я}! Ти незабаром матимеш доступ до найбільш передових інженерних розробок у всьому Азероті.\n\nТепер, коли ти {стать:присвятив:присвятила} себе цим знанням, настав час випробувати твої навички. Після цього ми допоможемо тобі розкрити свій потенціал в гномській інженерії!", ["en"] = "The Pledge of Secrecy", ["tasks"] = { ["Oglethorpe's Signed Pledge"] = "підписана угода Оґлторпа", ["Oglethorpe's Signed Pledge (Provided)"] = "підписана угода Оґлторпа (видано)" } },
    [3643] = { [1] = "Покажи свою роботу", [2] = "Як твій наставник, я хочу побачити зразки твоєї роботи. Ти {стать:вправний інженер:вправна інженерка}, без сумнівів, {ім'я}. Однак я хочу проаналізувати твою роботу, щоб виділити гномські техніки у твоїй майбутній діяльності. Мені потрібні такі зразки: шість мітрилових трубок, точний приціл і два покращені манекени-мішені.\n\nПринеси мені ці предмети, і я видам тобі твою власну членську картку гномського інженера. Вона обов'язково потрібна для доступу до всіх тренерів гномської інженерії!", [3] = "Принесіть 6 мітрилових трубок, точний приціл та 2 покращені манекени-мішені Оґлторпу Обриднусу в Грабіжну Бухту.", [4] = "Після того, як я побачу твої інженерні вироби, я видам тобі справжню членську картку гномського інженера! Допоки картка дійсна, у тебе буде необмежений доступ до будь-якого тренера з гномської інженерії по всьому світу.", [5] = "Ось твоя перша членська картка гномського інженера!\n\nВнесок по цій картці сплачено на чотирнадцять днів. Через два тижні термін її дії закінчиться. Коли це станеться — оплати наступний внесок будь-якому тренеру з гномської інженерії, щоб отримати нову картку. Без картки твоє членство тимчасово призупиниться, і ти не матимеш доступу до нових креслень.\n\nЦе ніяк не вплине на вже набуті знання: якщо ти вже {стать:став гномським інженером:стала гномською інженеркою}, то це назавжди.", ["en"] = "Show Your Work", ["tasks"] = { ["Accurate Scope"] = "точний приціл", ["Accurate Scope (Provided)"] = "точний приціл (видано)", ["Advanced Target Dummy"] = "вдосконалений манекен-мішень", ["Advanced Target Dummy (Provided)"] = "вдосконалений манекен-мішень (видано)", ["Advanced Target Dummy slain"] = "вдосконалений манекен-мішень: убито", ["Mithril Tube"] = "мітрилова трубка", ["Mithril Tube (Provided)"] = "мітрилова трубка (видано)" } },
    [365] = { [1] = "Поля скорботи", [2] = "Так, що тут у нас? Ти виглядаєш, як {стать:новоспечений:новоспечена} {клас:н}. Якщо ти сподіваєшся довести свою цінність Темній Леді, ти {стать:повинен:повинна} слідувати звичаям відречених.\n\nНа заході ти знайдеш ферму. Люди налізли на цю землю, як мухи на гнилий труп. Мало того, Багряний Похід патрулює неподалік, зі своєї вежі. Провчи цих покидьків і викради в них 10 їхніх цінних гарбузів.\n\nКоли будеш мати десяток, віднеси їх аптекареві Йогаану до Брілля.", [3] = "Викрадіть 10 гарбузів з ферми на заході, трохи північніше Смертедзвону, і принесіть їх аптекареві Йогаану в Брілль.", [4] = "Смертестраж Сіммер сповістив мене, що ти зможеш забезпечити мене дуже важливими реагентами. Ти {стать:зміг:змогла} зібрати 10 гарбузів, {ім'я:к}?", [5] = "Ти чудово {стать:виконав:виконала} своє завдання, {стать:юний:юна} {клас:к}. Ти доводиш, що можеш бути дуже цінним надбанням для війська Темної Леді.", ["en"] = "Fields of Grief", ["tasks"] = { ["Tirisfal Pumpkin"] = "тірісфальський гарбуз", ["Tirisfal Pumpkin (Provided)"] = "тірісфальський гарбуз (видано)" } },
    [366] = { [1] = "Повернення книги", [2] = "Багато років тому Ґюнтер і я разом з Тулом Воронокігтем, тепер некромантом Скари, були друзями та студентами в Кірін-Торі — товаристві магів Даларану.\n\nМи з Ґюнтером обоє загинули від Чуми, але я думав, що він або залишався мертвим, або його оживили до рядів Короля-ліча. Добре знати, що він вільний.\n\nМи повинні залучити його. Я наклав закляття на його фоліант, і, коли він його побачить, то зрозуміє, що я вільний від влади Короля-ліча. Сподіваюся, що після цього він приєднається до нас.", [3] = "Поверніть Ґюнтеру його фоліант. Його можна знайти на острові Прихистку Ґюнтера.", [4] = "Твої господарі бовдури, якщо послали тебе сюди — я ніколи не буду рабом Скари знову!", [5] = "Мій фоліант??? То ось {стать:злодій:злодійка}, що {стать:викрав:викрала} її!\n\nАле... що це за нові чари на ньому… Бетор? У Лордероні?\n\nЯкщо він досі є, можливо, він також втік від хватки Короля-ліча...", ["en"] = "Return the Book", ["tasks"] = { ["Gunther's Spellbook"] = "фоліант Ґюнтера", ["Gunther's Spellbook (Provided)"] = "фоліант Ґюнтера (видано)" } },
    [367] = { [1] = "Нова чума", [2] = "Леді Сильвана скликала Королівське товариство аптекарів. Темна Леді вірить, що наші знання в парі з новоздобутою магією відкриють нам ключ до знищення Артаса. Вона наказала нам приготувати нову чуму, яка буде більш згубною, ніж будь-яка пошесть на Азероті. Це має зруйнувати армію Скари Артаса.\n\nМої дослідження показують, що кров звірів може виявитися наріжним каменем. Принеси мені 5 пробірок з кров'ю темногончих, щоб я зміг випробувати свої здогадки.", [3] = "Аптекар Йогаан з містечка Брілль просить вас зібрати 5 пробірок крові темногончих.", [4] = "Ти уже {стать:зібрав:зібрала} 5 пробірок з кров'ю темногончих, {Ім'я}? Час спливає!", [5] = "Ти добре {стать:потрудився:потрудилася}, {Ім'я}, і я дякую тобі за твої зусилля.", ["en"] = "A New Plague", ["tasks"] = { ["Darkhound Blood"] = "кров темногончої", ["Darkhound Blood (Provided)"] = "кров темногончої (видано)" } },
    [368] = { [1] = "Нова чума", [2] = "Поки ти {стать:збирав:збирала} для мене зразки, мої експерименти допомогли мені зрозуміти, що потрібно більше інгредієнтів для правильного поширення пошесті. Отруєння безпорадних жертв є дитячою забавкою. Поширення чуми на весь світ - це більш складно.\n\nМені буде потрібно 5 огидних лусок плавників з місцевих мурлоків. Ти зможеш їх знайти вздовж узбережжя на півночі чи заході.", [3] = "Аптекар Йогаан з містечка Брілль потребує 5 огидних лусок плавників мурлоків з Тірісфальського перелісся.", [4] = "{Ім'я}, ти {стать:зміг:змогла} дістати 5 огидних лусок плавників з мурлоків?", [5] = "Ці луски просто чудові, {Ім'я}. Саме те, що мені треба для створення відвару.", ["en"] = "A New Plague", ["tasks"] = { ["Vile Fin Scale"] = "луска Злобного Плавника", ["Vile Fin Scale (Provided)"] = "луска Злобного Плавника (видано)" } },
    [369] = { [1] = "Нова чума", [2] = "Поки ти {стать:здобував:здобувала} інгредієнти, я знайшов старі записи в одному з моїх фоліантів про те, що стародавня чума знищила тисячі невинних жертв. Пізніше відкрили, що смертоносний штам пошесті зберігся в отруті нічних колопрядів.\n\nПринеси мені трохи отрути цих злих нічних колопрядів, щоб закінчити експеримент. Я хочу побачити, чи буде цей заразний елемент у ній працювати з моїм новим відваром. Кажуть, що таких павуків можна знайти на сході Тірісфальського перелісся.", [3] = "Аптекар Йогаан з містечка Брілль хоче, щоб ви зібрали 4 зразки отрути злих нічних колопрядів.", [4] = "Маєш уже отруту злих нічних колопрядів, {Ім'я}? Це останній інгредієнт, якого я потребую для випробування мого експериментального варива.", [5] = "О, ця отрута чудово підійде, {Ім'я}. Усе інше вже додано у відвар і приготоване. Нарешті, я готовий випробувати цей новий смертельний штам!", ["en"] = "A New Plague", ["tasks"] = { ["Vicious Night Web Spider Venom"] = "отрута злого нічного колопряда", ["Vicious Night Web Spider Venom (Provided)"] = "отрута злого нічного колопряда (видано)" } },
    [370] = { [1] = "Війна з Багряним Походом", [2] = "Стратегічні документи від карателя Аррена містять усі деталі, які нам потрібні, щоб вичавити людську заразу з нашого краю. Згідно з цими відомостями, Багряний Похід направив капітана Перріна й один загін до зруйнованої вежі, що розташована в південно-західному напрямку від Брілля.\n\nУбий Перріна, 3 ревнителів, 3 місіонерів і відзвітуй мені.", [3] = "Каратель Зиґанд в Бріллі хоче, щоб ви убили капітана Перріна, 3 ревнителів Багряного Походу і 3 місіонерів Багряного Походу.", [4] = "{стать:Юний:Юна} {клас:к}, не марнуй свій час тут у Бріллі, коли ти {стать:потрібен:потрібна}, щоб боротися за свій народ. Бери зброю, відправляйся в південно-західному напрямі до зруйнованої вежі, та вбий там капітана Перріна, 3 ревнителів і 3 місіонерів. Ми приведемо Багряний Похід до їхньої загибелі.", [5] = "Смерть капітана Перріна, безсумнівно, потішить Темну Леді. Ти добре {стать:впорався:впоралась} зі своїм обов'язком, {клас:к}.", ["en"] = "At War With The Scarlet Crusade", ["tasks"] = { ["Captain Perrine"] = "капітан Перрін", ["Captain Perrine slain"] = "капітан Перрін: убито", ["Scarlet Missionary"] = "місіонер Багряного Походу", ["Scarlet Missionary slain"] = "місіонер Багряного Походу: убито", ["Scarlet Zealot"] = "ревнитель Багряного Походу", ["Scarlet Zealot slain"] = "ревнитель Багряного Походу: убито" } },
    [371] = { [1] = "Війна з Багряним Походом", [2] = "Ми досі воюємо, а сила Багряного Походу зростає. Звіт карателя Аррена повідомляє, що Багряний Похід вчиняє набіги зі зруйнованої вежі на південному-сході біля хутора Бальнірів, під очільництвом капітана Вачона.\n\nУбий Вачона разом з 5 ченцями Багряного Походу. Це має завдати спустошливого удару по Походу!", [3] = "Каратель Зиґанд в Бріллі просить вас вбити капітана Вачона та 5 ченців Багряного Походу.", [4] = "Я бачу, що ти {стать:повернувся:повернулася}, але завдання не {стать:виконав:виконала}. Може, тебе не трубує, що якісь людиська втручаються у плани Темної Леді? Чи, може, ти можеш виконати свій обов'язок і вбити капітана Вачона та його ченців!", [5] = "Смерть капітана Вачона досить сильно зупинить наступ Багряного Походу в Тірісфальському переліссі. Але інші загрози нависають над нами.", ["en"] = "At War With The Scarlet Crusade", ["tasks"] = { ["Captain Vachon"] = "капітан Вачон", ["Captain Vachon slain"] = "капітан Вачон: убито", ["Scarlet Friar"] = "ченець Багряного Походу", ["Scarlet Friar slain"] = "ченець Багряного Походу: убито" } },
    [372] = { [1] = "Війна з Багряним Походом", [2] = "Багряний Похід робить набіги зі зруйнованої вежі у північному Тірісфалі, біля Спочину Фаола. Згідно з нашими даними, безжальний командир на ім'я капітан Мелрач очолює цей загін.\n\nЯ довіряю тобі це особливе та небезпечне завдання. Вбий Мелрача та двох його охоронців в ім'я Темної Леді.", [3] = "Каратель Зиґанд з містечка Брілль хоче, щоб ви вбили капітана Мелрача та двох його тілоохоронців.", [4] = "Ти не {стать:виконав:виконала} свій обов'язок, {Ім'я}. Ми не можемо сподіватися на реалізацію плану Темної Леді, коли нашим солдатам докучає Багряний Похід. Принеси їм смерть і виконай свої зобов'язання перед Сильваною!", [5] = "Ти неймовірно добре {стать:впорався:впоралася}, {клас:к}. З такими безжалісними бійцями, як ти, що перемагають на славу відречених, ми вже на крок ближчі до поразки Артаса раз і назавжди. У мене хороші передчуття щодо тебе, {стать:товаришу:товаришко}.", ["en"] = "At War With The Scarlet Crusade", ["tasks"] = { ["Captain Melrache"] = "капітан Мелрач", ["Captain Melrache slain"] = "капітан Мелрач: убито", ["Scarlet Bodyguard"] = "тілоохоронець Багряного Походу", ["Scarlet Bodyguard slain"] = "тілоохоронець Багряного Походу: убито" } },
    [374] = { [1] = "Доказ загибелі", [2] = "Каратель Зиґанд розповів мені, як ти вправно {стать:вбивав:вбивала} членів Багряного Походу. Тірісфальське перелісся переповнене ними.\n\nВаріматрас, лейтенант Темної Леді, особисно взявся за цю справу, щоб азеротська нечисть - люди - були стерті в порох. Тут у Тірісфалі ми зустрілися із особливо набридливим видом - Багряним Походом.\n\nЙди та завдай удару по Багряному Походу, {клас:к}. Принеси мені 10 перснів-відзнак Багряного Походу як доказ своєї вірності Варіматрасу та Темній Леді.", [3] = "Принесіть 10 перснів-відзнак Багряного Походу смертестражу Бурґессу у Брілл.", [4] = "Ти вже {стать:зібрав:зібрала} 10 перснів-відзнак Багряного Походу, {клас:к}?", [5] = "Варіматрас пишатиметься тобою. Ти добре {стать:послужив:послужила} своїм лідерам, {клас:к}.", ["en"] = "Proof of Demise", ["tasks"] = { ["Scarlet Insignia Ring"] = "перстень-відзнака Багряного Походу", ["Scarlet Insignia Ring (Provided)"] = "перстень-відзнака Багряного Походу (видано)" } },
    [375] = { [1] = "Холодок смерті", [2] = "Так холодно... Чума невмирущості звивається у моїх жилах, як льодяна змія. Скоро мене поглине божевілля, але жодна невідворотна доля не зупинить мене від служби нашій Темній Леді. Коли мене викликали, я шила сумки для тіл загиблих воїнів армії Сильвани.\n\nТепер мої руки трясуться від холоду. Якби ти {стать:приніс:принесла} мені 5 шкурок сутінкового кажана, я б могла пошити собі ковдру. Допоможи мені, {Ім'я}, і я зможу продовжувати служити нашій справі.", [3] = "Принесіть 5 шкур сутінкового кажана та трохи грубої нитки для Ґретхен Дедмар у Брілль.", [4] = "Ти вже маєш 5 шкурок сутінкового кажана та трохи грубої нитки, {Ім'я}?", [5] = "Я ціную твої зусилля, {Ім'я}. Сподівають, одного дня твою хоробрість помітить Сильвана...", ["en"] = "The Chill of Death", ["tasks"] = { ["Coarse Thread"] = "груба нитка", ["Coarse Thread (Provided)"] = "груба нитка (видано)", ["Duskbat Pelt"] = "шкура сутінкового кажана", ["Duskbat Pelt (Provided)"] = "шкура сутінкового кажана (видано)" } },
    [376] = { [1] = "Прокляті", [2] = "Мої обов'язки включають допомогу нашим пораненим воїнам, пошиття броні й одягу та поміч жерцю тіні Сарвісу з будь-чим, що йому потрібно.\n\nСудячи з твого вигляду, тебе також призначили йому на службу... для полювання на бездумних, наскільки я його знаю. Добре, якщо хочеш залишитись {стать:цілим:цілою} — а я в цьому не сумніваюся — я зможу тобі допомогти. В мене закінчуються лапи та крила, і, якщо принесеш мені декілька, я знайду для тебе якусь броню. Ти знайдеш вдосталь вовків і кажанів на півдні.", [3] = "Послушниця Елрет потребує 6 лап падальників і 6 крил сутінкового кажана.", [4] = "Постарайся залишитись {стать:неушкодженим:неушкодженою}, доки я не видам тобі броню.", [5] = "Дякую, {ім'я}. Це броня повинна стати тобі в пригоді.\n\nСподіваюся, вона послужить тобі краще, ніж тому, хто носив її до тебе...", ["en"] = "The Damned", ["tasks"] = { ["Duskbat Wing"] = "крило сутінкового кажана", ["Duskbat Wing (Provided)"] = "крило сутінкового кажана (видано)", ["Scavenger Paw"] = "лапа падальника", ["Scavenger Paw (Provided)"] = "лапа падальника (видано)" } },
    [3761] = { [1] = "Ґрунт Ун'Ґоро", [2] = "Кажуть, що ґрунт кратера Ун'Ґоро наділений потужними магічними властивостями. Кенарійському Коло хоче вивчити його. Вирушай в нетрі кратера Ун'Ґоро та дістань достатньо зразків ґрунту для наших досліджень.\n\nЦей ґрунт часом можна знайти у великих купах, а іноді його можна знайти у звірів. Принеси зразки Ґеду — шукай купи землі й таурена, що роздає накази. Він не злий, просто постарайся йому не дошкуляти.", [3] = "Принесіть 20 зразків ґрунту Ун'Ґоро Ґеду на Верхів'я Старійшин, що в Громовому Бескиді.", [4] = "Вільно, {стать:рядовий:рядова}. Якщо ти тут, щоб вивантажити ґрунт Ун'Ґоро — чудово! Якщо ні — кругом і марш звідси.", [5] = "Гаразд, {стать:рядовий:рядова} {ім'я}, не намагайся допомагати мені звалювати цю землю до купи! Якби Великі Духи цього хотіли, то просто тут і влаштували б диво, чи не так?!\n\nВерховний друїд Рунний Тотем хоче знову поговорити з тобою, але для його наступного завдання тобі знадобляться знання травництва хоча б на рівні підмайстра. Але навіть якщо це не так, він все одно знайде тобі діло.", ["en"] = "Un'Goro Soil", ["tasks"] = { ["Un'Goro Soil"] = "ґрунт Ун'Ґоро", ["Un'Goro Soil (Provided)"] = "ґрунт Ун'Ґоро (видано)" } },
    [3762] = { [1] = "Допомога верховному друїду Рунному Тотему", [2] = "Перепрошую, {клас:к}, можна тебе на хвилинку?\n\nКенарійське Коло в Громовому Бескиді зацікавлене в таких досвідчених шукачах пригод, як ти, що допоможуть їм з важливим дослідницьким проєктом. Я не знаю подробиць, та можу точно сказати, що очолює цей проєкт сам верховний друїд Гамуул Рунний Тотем.\n\nБудь ласка — якщо тобі цікаво, поговори з ним особисто на Верхів'ї Старійшин у Громовому Бескиді.", [3] = "Поговоріть із верховним друїдом Гамуулом Рунним Тотемом у Громовому Бескиді.", [5] = "Вітаю, {клас:к}. Радий бачити твою зацікавленість в нашому дослідженні. Роботи дуже багато, але я поведуся негарно, якщо не попереджу тебе про те, що вона досить небезпечна. Сподіваюся, тебе це не лякає... з іншого боку, дивлячись на тебе, переконуюся, що ти вже {стать:досвідчений:досвідчена} в таких справах.", ["en"] = "Assisting Arch Druid Runetotem" },
    [3782] = { [1] = "Дослідження світанки", [2] = "За допомогою того, що ми називаємо торбою вічного цвітіння, ми виростили насіння Тарлендріса в ґрунті з кратера Ун'Ґоро. З цього насіння проростає низка корисних трав. Одна з них — світанка, таємнича рослина, про яку ми мало що знаємо. І я збираюсь дослідити її таємниці для Кола.\n\nВіднеси це моїй доньці, Башані, і вона дасть тобі трохи насіння, щоб ти {стать:міг:могла} нам допомогти. Якщо ти все витратиш, тобі доведеться купити у неї ще.", [3] = "Віднесіть розписку про видачу насіння Башані Рунному Тотему в Громовий Бескид.", [4] = "Мир тобі, {клас:к}. Ти тут за дорученням від самого верховного друїда, чи не так?", [5] = "Так, по цій розписці я можу видати тобі двадцять пакетів насіння. Якщо закінчиться — я зможу продати ще.\n\nНа жаль, насіння Тарлендріса досить дорого виробляти у великій кількості. Ось чому Кенарійське Коло просить тих, хто нам допомагає, компенсувати частину витрат. Ті, хто повертається зі світанкою, знають, що винагорода верховного друїда з лишком окупає витрати.", ["en"] = "Morrowgrain Research", ["tasks"] = { ["Seed Voucher"] = "розписка про видачу насіння", ["Seed Voucher (Provided)"] = "розписка про видачу насіння (видано)" } },
    [3784] = { [1] = "Допомога верховному друїду Рунному Тотему", [2] = "Перепрошую, {клас:к}, можна тебе на хвилинку?\n\nКенарійське Коло в Громовому Бескиді зацікавлене в таких досвідчених шукачах пригод, як ти, що допоможуть їм з важливим дослідницьким проєктом. Я не знаю подробиць, та можу точно сказати, що очолює цей проєкт сам верховний друїд Гамуул Рунний Тотем.\n\nБудь ласка - якщо тобі цікаво, поговори з ним особисто на Верхів'ї Старійшин у Громовому Бескиді.", [3] = "Поговоріть із верховним друїдом Гамуулом Рунним Тотемом у Громовому Бескиді.", [5] = "Вітаю, {клас:к}. Радий бачити твою зацікавленість в нашому дослідженні. Роботи дуже багато, але я поведуся негарно, якщо не попереджу тебе про те, що вона досить небезпечна. Сподіваюся, тебе це не лякає... з іншого боку, дивлячись на тебе, переконуюся, що ти вже {стать:досвідчений:досвідчена} в таких справах.", ["en"] = "Assisting Arch Druid Runetotem" },
    [3786] = { [1] = "Дослідження світанки", [2] = "Ось твоя торба вічного цвітіння, у якій ти зможеш проростити насіння Тарлендріса. Тобі доведеться посадити їх у ґрунт Ун'Ґоро. Як матимеш все необхідне — просто скористайся торбою. Вона подбає про все інше.\n\nЯк матимеш достатньо світанки — принось її мені на Верхів'я Старійшин. І прошу, не турбуй верховного друїда, він дуже зайнятий дослідженнями та безліччю інших важливих справ!", [3] = "За допомогою торби вічного цвітіння, пакету насіння Тарлендріса та двох зразків ґрунту Ун'Ґоро спробуйте проростити світанку.\n\nПринесіть 10 світанок Башані Рунному Тотему в Громовий Бескид.", [4] = "Ну як, {ім'я}, тобі вдалось виростити світанку для важливих досліджень верховного друїда? З кожним днем ми дізнаємось все більше таємниць кратера Ун'Ґоро завдяки зусиллям таких, як ти.", [5] = "Молодець, {ім'я}, я обов'язково віддам їх верховному друїду, коли вони йому знадобляться. А поки що прийми це на знак вдячності Кенарійського Кола.\n\nНам завжди потрібна світанка, тож якщо хочеш і надалі допомагати нам — приходь до мене, коли виростиш ще.", ["en"] = "Morrowgrain Research", ["tasks"] = { ["Morrowgrain"] = "світанка", ["Morrowgrain (Provided)"] = "світанка (видано)" } },
    [379] = { [1] = "Вгамувати спрагу", [2] = "Тобі потрібно джерело енергії. Я можу допомогти з цим. Знаєш, що я хочу натомість? Я хочу щось випити! Принеси мені п'ять бурдюків з водою Пустелебродів, і я дам тобі 4711-FTZ.\n\nА тепер... здогадайся, де можна знайти ці бурдюки з водою! Чому б тобі не попросити їх в одного з Пустелебродів на сході? Розкажеш, що з цього вийде.", [3] = "Принесіть 5 бурдюків з водою Пустелебродів головному інженеру Трюмосвисту в Пристроблях.", [4] = "Ну як, кочівники \"поділились\" з тобою водою?", [5] = "Чудово, джерело енергії твоє. Щоправда, воно не зовсім пристосоване для використання в такому для польових досліджень, тож у тебе буде обмежена кількість часу, перш ніж усі зібрані тобою дані зітруться!\n\nКоли збереш, все, що потрібно, принеси цю штуковину мені, щоб я відключив її як слід. У тебе буде щонайбільше дві години на це.\n\nЯкщо ти не встигнеш, я завжди можу продати тобі ще одне джерело енергії. Ключове слово — продати!", ["en"] = "Slake That Thirst", ["tasks"] = { ["Wastewander Water Pouch"] = "бурдюк з водою Пустелебродів", ["Wastewander Water Pouch (Provided)"] = "бурдюк з водою Пустелебродів (видано)" } },
    [380] = { [1] = "Лігво нічних колопрядів", [2] = "Однією з наших найбільших проблем є здобуття природних ресурсів, які потрібні для виживання. Золото було рідкістю навіть у часи розквіту Альянсу.\n\nНа північний захід звідси є золота шахта, і вона переповнена павуками. Нам потрібне золото з цієї шахти, але ми не можемо навіть потрапити всередину, поки ці павуки там усюди лазять. Я не маю достатньо підлеглих, щоб дати їм це завдання, тож ми спробуємо виконати його потрохи.\n\nПіди та поглянь, що ти можеш для нас там зробити, {Ім'я}.", [3] = "Каратель Аррен хоче, що ви знищили 10 молодих нічних колопрядів і 8 нічних колопрядів.", [4] = "Стережися отрути павуків, {Ім'я}. Якщо ти відчуєш різке печіння, тобі, певно, знадобиться огляд.", [5] = "Гм, добре, це початок. Повне очищення цього місця від нашестя павуків займе кілька тижнів або місяців. Після цього нам потрібно буде спуститися туди з факелами, щоб спалити все павутиння.\n\nТи добре {стать:виконав:виконала} свій обов'язок, {Ім'я}. Певно, я зможу знайти ще якусь роботу для тебе.", ["en"] = "Night Web's Hollow", ["tasks"] = { ["Night Web Spider"] = "нічний колопряд", ["Night Web Spider slain"] = "нічний колопряд: убито", ["Young Night Web Spider"] = "молодий нічний колопряд", ["Young Night Web Spider slain"] = "молодий нічний колопряд: убито" } },
    [3804] = { [1] = "Світанка для Громового Бескиду", [4] = "Верховному друїду завжди потрібна світанка для проведення досліджень Кенарійського Кола в кратері Ун'Ґоро. Ми приймаємо її по десять одиниць і натомість даємо кілька корисних речей. Коли збереш десять світанок — принось мені, і я тебе гідно винагороджу.", [5] = "Чудово — ця світанка, без сумніву, допоможе нам, коли прийде час. Ми знаємо, що нічні ельфи проводять подібні дослідження цієї рослини, хоча й не ясно, як вони будуть її використовувати, якщо щось відкриють. Верховний друїд вважає, що світанка буде потрібна нам доти, доки ми не розгадаємо її таємниці.\n\nЦе для тебе, {ім'я}. Кенарійське Коло дякує за твою постійну допомогу.", ["en"] = "Morrowgrain to Thunder Bluff", ["tasks"] = { ["Morrowgrain"] = "світанка", ["Morrowgrain (Provided)"] = "світанка (видано)" } },
    [381] = { [1] = "Багряний Похід", [2] = "Тобі буде приємно дізнатися, що ми, схоже, досягаємо успіхів у шахті, не в останню чергу завдяки твоїм зусиллям. Тепер ми можемо зайнятися іншими справи.\n\nМої розвідники доповіли, що загін Багряного Походу лаштує табір на південний схід звідси. Багряний Похід — нікчемна організація, яка полює на нас, і вони не зупиняться, доки кожного невмерлого — зі Скари Короля-ліча чи ні — не буде знищено. Ми повинні вдарити першими!\n\nБудь {стать:обережним:обережною}, їхня нечестива ревність робить їх небезпечними супротивниками.", [3] = "Принесіть карателю Аррену 12 багряних пов'язок з новонавернених і посвячених Багряного Походу.", [4] = "Ці дурні... Вони самі прирекли себе на загибель.", [5] = "Якби вони лише дослухалися до глузду, еге ж, {Ім'я}? Можливо, ми б змогли сісти за стіл для конструктивного дискурсу... ага!\n\nЗасліплені світлом ідіоти.", ["en"] = "The Scarlet Crusade", ["tasks"] = { ["Scarlet Armband"] = "багряна пов'язка", ["Scarlet Armband (Provided)"] = "багряна пов'язка (видано)" } },
    [382] = { [1] = "Червоний посланець", [2] = "Звіти від мого начальства у Бріллі повідомляють, що з Багряного монастиря відіслали агента Багряного Походу сюди, до Смертедзвона. Згідно з цими відомостями, посланець має при собі важливу інформацію. Я не маю подробиць, але що б це не було, ми повинні нею заволодіти!\n\nТи є найбільш {стать:придатним:придатною} з тих, кому я можу це доручити, {ім'я}. Знайди посланця та принеси мені будь-яку інформацію, яку спроможешся відшукати.", [3] = "Убийте Мевена Корґала, посланця у таборі Багряного Походу, та повертайтеся з будь-якою роздобутою інформацією до карателя Аррена.", [4] = "Як твої успіхи на завданні, {клас:к}?", [5] = "Гм-м... Погляньмо, що тут у тебе...\n\n<Він починає перебирати документи, які ви роздобули.>\n\nНовини щодо їхніх дій проти нас... Нікчемно. Доповіді розвідки... Нові накази: \"Продовжуйте будувати табір біля зруйнованого міста...\". Нічого такого, чого ми вже не знаємо... О, а це що? Карта розташувань їхніх польових командирів і агентів? Нам це згодиться.", ["en"] = "The Red Messenger", ["tasks"] = { ["Scarlet Crusade Documents"] = "документи Багряного Походу", ["Scarlet Crusade Documents (Provided)"] = "документи Багряного Походу (видано)" } },
    [3821] = { [1] = "Скеля Жахобою", [2] = "Ша'ні направили досліджувати повідомлення про дивну ритуальну діяльність серед Вогнечеревих огрів у Палаючому степу понад три тижні тому.\n\nКлинозуб каже, що не отримував звісток від жодного члена того загону, і що найкраще зараз мені рухатися далі та зосередитися на нагальних справах. Можеш у таке повірити? Це ж моя дружина!\n\nЯ не маю права залишити свій пост, {ім'я}, але я повинен знати, що сталося з Ша'ні. Вирушай до Палаючого степу і пошукай її.", [3] = "Прямуйте до Палаючого степу та з'ясуйте, що сталося з Ша'ні Гордий Бивень.", [5] = "Бідний мій Тал'трак.\n\nА ми ж планували переселитися до моїх батьків у Внутрішні землі, коли наша служба закінчиться. Тепер цим мріям не дано збутися.", ["en"] = "Dreadmaul Rock" },
    [3822] = { [1] = "Кром'Ґрул", [2] = "Моя вся рота була захоплена, {ім'я}. Їх всіх, окрім мене, вбили.\n\nЇх лідер, Кром'Ґрул, хотів зберегти мене для якогось ритуалу.\n\nМене прикували до вівтаря і катували чудовиськом. Через годину цих тортур моє фізичне тіло померло. Тоді ця тварюка вирвала у мене з носа обручку і натягла на свій палець. У житті не зустрічала подібного варварства!\n\nЗнайди Кром'Ґрула та вбий його! Віднеси мою обручку Тал'траку.\n\nІ, {ім'я}, скажи йому, що ми зустрінемося знову... в іншому житті.", [3] = "Знайдіть обручку Ша'ні у Кром'Ґрула і поверніть її Тал'траку в Карґат. Шукайте в печерах та шахтах скелі Жахобою.", [4] = "Ти {стать:знайшов:знайшла} Ша'ні? З нею все гаразд?", [5] = "<Тал'трак опускається на підлогу.>\n\nМи збиралися переїхати у Внутрішні землі. Вона розповідала? Це було її останнє завдання.\n\n<Тал'трак ридає.>\n\nВона мені не потрібна, {ім'я}. Залиш її собі, викинь, мені все одно! Ця обручка тепер нічого не варта. Без неї вона ніщо...", ["en"] = "Krom'Grul", ["tasks"] = { ["Sha'ni's Nose-Ring"] = "обручка Ша'ні", ["Sha'ni's Nose-Ring (Provided)"] = "обручка Ша'ні (видано)" } },
    [383] = { [1] = "Надважливі відомості", [2] = "Це потрібно донести до мого начальника, карателя Зиґанда, до Брілля. З цією інформацією ми зможемо завдати вирішального удару по Багряному Походу. Твоя служба була корисною тут, у Смертодзвоні, але мені потрібен хтось, щоб доставити це до Зиґанда, і я думаю, що він зможе знайти тобі краще завдання.\n\nЙди дорогою на північ від Смертедзвона. Незабаром, як вийдеш на простори Тірісфалю, дійдеш до роздоріжжя. Поверни у східному напрямку та простуй далі на схід. По дорозі пройдеш повз садибу Холодне Вогнище.", [3] = "Доставте документи Багряного Походу до карателя Зиґанда у Брілль.", [4] = "Так, чого ти хочеш?", [5] = "О, це дуже добре. Ти добре {стать:вчинив:вчинила}, що {стать:роздобув:роздобула} цю інформацію, {Ім'я}. Гм-м... імена офіцерів у Тірісфальському переліссі...\n\nУяви, якого удару по моралі цих чортових ревнителів ми б могли завдати, якби знищили їхніх лідерів одним стрімким ударом.", ["en"] = "Vital Intelligence", ["tasks"] = { ["Scarlet Crusade Documents"] = "документи Багряного Походу", ["Scarlet Crusade Documents (Provided)"] = "документи Багряного Походу (видано)" } },
    [3901] = { [1] = "Брязкіт кісток", [2] = "Ти {стать:показав:показала} свій потенціал для відречених у нормальних умовах, {Ім'я}. А тепер поглянемо, як ти впораєшся під тиском.\n\nБрязкокісткові скелети, ще більш безвільні раби Короля-ліча, є сильнішими ворогами, ніж зомбі, з якими ти {стать:бився:билася} до цього. Знову ж, проріди їхні ряди та послужи відреченим. Не зволікай і, коли виконаєш завдання, повертайся знову до мене.", [3] = "Убийте 12 брязкокісткових скелетів і поверніться до жерця тіні Сарвіса у Смертедзвін.", [4] = "Хто зволікає з таким завданням, можуть скінчити тим, що безцільно бродитимуть навколо, як наші полеглі брати та сестри з селища. Сподіваймося ж, що ти справишся краще за них, еге ж?", [5] = "Я побачив достатньо, {ім'я} - ти {стать:показав:показала} себе {стать:вартим:вартою} свободи, що тобі дана. Багато хто протистоятиме тобі через те, чим ти {стать:став:стала}, але знай, що наперекір будь-чому, що вони можуть спробувати використати проти нас, ми - вільні, і нас не закувати знову.\n\nВізьми це та рушай своїм шляхом. На тебе чекають великі досягнення, {клас:к}.", ["en"] = "Rattling the Rattlecages", ["tasks"] = { ["Rattlecage Skeleton"] = "брязкокістковий скелет", ["Rattlecage Skeleton slain"] = "брязкокістковий скелет: убито" } },
    [3902] = { [1] = "Обшук Смертедзвона", [2] = "Гей, ти! Якщо шукаєш, що б зробити корисне, тоді слухай!\n\nНам потрібно, щоб наші свіжі тільки-з-землі рекрути подалися у Смертедзвін і пошукали там якесь корисне спорядження. Найімовірніше, що воно буде в нагромаджених коробках. Ми надіємося скоро підняти більше рекрутів, і, якщо ми не хочемо, щоб вони тут вешталися голі, нам варто почати шукати!\n\nЩо ж, вперед до роботи, нікчемний лантух з кістками! Я не нагороджуватиму тих, хто нічого не робить.", [3] = "Обшукайте Смертедзвін й округу та знайдіть там 6 віднайдених припасів, а потім поверніть їх смертестражеві Салтейну.", [4] = "Вдалося роздобути щось корисне для нас? Немає сорому в тому, щоб використовувати знову те, що колись викинули. Ніхто не подарує нам жодних подачок, тому ми, відречені, самі про себе попіклуємося!", [5] = "Чудова робота, {ім'я}. Я знав, що ти не {стать:безнадійний:безнадійна}. Ось, вибери собі одну з кращих речей, які я обрав з того, що вже вдалось зібрати.", ["en"] = "Scavenging Deathknell", ["tasks"] = { ["Scavenged Goods"] = "віднайдені припаси", ["Scavenged Goods (Provided)"] = "віднайдені припаси (видано)" } },
    [3907] = { [1] = "Дисгармонія вогню", [2] = "Я відчуваю, як нечисть витає в повітрі, {ім'я}. Джерело її ховається в надрах Чорноскельної гори.\n\nЙого ім'я чути в стогонах вітру та землі: лорд Спалахій... але хтось... щось... керує ним. Він лише посланець.\n\nЗнайди його і дізнайся, де ховається його господар. Повертайся до мене, коли все дізнаєшся.", [3] = "Увійдіть у Чорноскельні надра та розшукайте лорда Спалахія. Вбийте його та принесіть будь-яку інформацію про його господаря до Громосерда.", [4] = "Полум'я скоро охопить ці землі. Поспіши, {ім'я}!", [5] = "<Громоcерд стискає скрижаль Курнії.>\n\nРагнарос... тут...\n\nСтарійшини мали рацію, боячись зла Чорноскельної гори. Генерал Старих Богів! ПРИЙШОВ В НАШ СВІТ! Нам потрібно оцінити наше становище тут, в Карґаті. Ми маємо вирішити, чи варто залишатися та боротись, чи тікати перед жахом нового розколу.\n\nКраще не наближайся до Чорноскельної гори, {ім'я}. В її вогненних глибинах живе чи не найбільше зло цього світу.", ["en"] = "Disharmony of Fire", ["tasks"] = { ["Lord Incendius"] = "лорд Спалахій", ["Lord Incendius slain"] = "лорд Спалахій: убито", ["Tablet of Kurniya"] = "скрижаль Курнії", ["Tablet of Kurniya (Provided)"] = "скрижаль Курнії (видано)" } },
    [3921] = { [1] = "Венікі Цебробовт", [2] = "Здається, я зламав самофланж. Це недобре, бо я вже розповів про нього кільком колегам з Підштольні, і вони були дуже заінтриговані. Ми маємо полагодити його!\n\nВіднеси зламаний самофланж до Венікі Цебробовт, на південь від оплоту Мор'шан, форпосту орди між Степами і Ясенедолом. Вона дуже розумна і допитлива. Покажи їй самофланж, б'юся об заклад, вона не упустить можливість полагодити його.", [3] = "Принесіть зламаний самофланж до Венікі Цебробовт.", [4] = "Я дуже зайнята, {клас:к}. Якщо у тебе немає для мене чогось важливого, краще йди своєю дорогою...", [5] = "А це що таке? Самофланж, кажеш? Що за самофланж?\n\nА... але поглянь-но, як він рухається, коли береш його до рук. А всередині дзижчать шестерні. Йой! Я маю полагодити його і дізнатися, що він робить, а ти?", ["en"] = "Wenikee Boltbucket", ["tasks"] = { ["Broken Samophlange"] = "зламаний самофланж", ["Broken Samophlange (Provided)"] = "зламаний самофланж (видано)" } },
    [3922] = { [1] = "Заготовки для деталей", [2] = "Я хочу полагодити цей самофланж, але для цього мені знадобляться деякі матеріали. У мене закінчилися заготовки для деталей на 17.5, а для роботи мені знадобиться їх ціла купа.\n\nНайближче місце, де їх можна дістати — Драговина шламу на сході. Працівники ТзНБ \"Авантюра\" зазвичай тримають їх у відрах з інструментами. Йди туди та пошукай заготовки, а як назбираєш достатньо — повертайся до мене.", [3] = "Принесіть 15 заготовок для деталей Венікі Цебробовт в Степи.", [4] = "{стать:Знайшов:Знайшла} заготовки для деталей, {ім'я}? Я вже не можу дочекатися, коли зможу попрацювати над самофланжем.", [5] = "Чудово, вони в тебе! А тепер до роботи...", ["en"] = "Nugget Slugs", ["tasks"] = { ["Nugget Slug"] = "заготовка для деталі", ["Nugget Slug (Provided)"] = "заготовка для деталі (видано)" } },
    [3923] = { [1] = "Ріллі Мастилоплюв", [2] = "Що ж, це не спрацювало. Я додала кілька додаткових датчиків на самофланж, щоб виміряти його структурну цілісність, і вони показали, що цілісність на рекордно низькому рівні. Я могла б додати ще кілька циферблатів чи важелів, але... Думаю, так стане тільки гірше.\n\nВіднеси самофланж до Ріллі Мастилоплюва. Він раніше працював на ТзНБ \"Авантюра\" — якщо хтось і знає, як полагодити цю штуку, то це Ріллі.\n\nТи знайдеш його в майстерні Ноґґа в Орґріммарі, в долині Честі.", [3] = "Принесіть зламаний та пошарпаний самофланж Ріллі Мастилоплюву в Орґріммар.", [4] = "Обережніше з головою! Не заважай мені працювати!", [5] = "А це що? Та це ж самофланж! Звідки він у тебе? Ти {стать:нишпорив:нишпорила} на майданчику ТзНБ \"Авантюра\" в Степах?\n\nТи або дуже {стать:хоробрий:хоробра}, або дуже {стать:дурний:дурна}.", ["en"] = "Rilli Greasygob", ["tasks"] = { ["Broken and Battered Samophlange"] = "зламаний та пошарпаний самофланж", ["Broken and Battered Samophlange (Provided)"] = "зламаний та пошарпаний самофланж (видано)" } },
    [3924] = { [1] = "Посібник з експлуатації самофланжа", [2] = "Думаю, я зможу полагодити самофланж, але спершу мені знадобиться посібник з експлуатації. Коли я працював у ТзНБ \"Авантюра\", у мене був суперник, бос Мідноштепсель, який зберігав таємниці самофланжа і ділився лише краплинами знань про пристрій з тими, кому він довіряв. Я не був одним з тих небагатьох...\n\nБос Мідноштепсель зазвичай перебуває у шахті Валун Вапняку на північному сході Степів. Забери у нього посібник і сторінки з нього, які він, певно, комусь встиг роздати.", [3] = "Принесіть посібник з експлуатації самофланжа Ріллі Мастилоплюву в Орґріммар.", [4] = "Ти {стать:приніс:принесла} посібник?", [5] = "Тобі вдалося дістати посібник! Не можу дочекатися, щоб прочитати його і дізнатися, як полагодити самофланж! Я розмовляв зі Гуркоклапаном в Брашпилі — він хотів подякувати тобі за допомогу і передати винагороду.\n\nІ я теж дуже вдячний. Якщо я коли-небудь полагоджу цю штуку, я дам тобі знати...", ["en"] = "Samophlange Manual", ["tasks"] = { ["Samophlange Manual"] = "посібник з експлуатації самофланжу", ["Samophlange Manual (Provided)"] = "посібник з експлуатації самофланжу (видано)" } },
    [398] = { [1] = "Розшукується: Червиве Око", [2] = "Розшукується: Червиве Око!\n\nПаскудну тварюку, навіть по мірам гнолів, Червиве Око засуджено до смерті за злочини проти відречених. Цей нікчемний поганець викрадає трупи для використання армією Короля-ліча. Востаннє його бачили за розоренням місцевості біля пристанища Ґаррена на північ від Брілля.\n\nМістечко Брілль цим пропонує нагороду вправній душі, яка зможе провести страту. Покажіть карателю Зиґандові лапу злочинця, коли справу буде зроблено.\n\nМилосердя - для слабких.", [3] = "Убийте Червиве Око та повертайтеся з його лапою до карателя Зиганда у Брілль по нагороду.", [4] = "Так?", [5] = "Червиве Око нарешті спіткала розплата за його мерзенні злочини. Можливо, твої доблесні дії ясно попередять тих, хто хоче нашкодити нашому народові. Від імені містечка Брілля, я дякую тобі, {Ім'я}.", ["en"] = "Wanted: Maggot Eye", ["tasks"] = { ["Maggot Eye's Paw"] = "лапа Червивого Ока", ["Maggot Eye's Paw (Provided)"] = "лапа Червивого Ока (видано)" } },
    [3981] = { [1] = "Командир Ґор'шак", [2] = "Бідолашний Ґарґал, він навіть не встиг нічого зрозуміти, як — бац! — і стріла влучила йому прямо в голову. Він і раніше не був генієм, але тепер...\n\n<Ґаламав робить сумну гримасу.>\n\nКоли ми витягли стрілу, то помітили записку, прикріплену до держака. На ній був грубо намальований орк за ґратами з підписом командира Ґор'шака.\n\nЯкщо він ще живий та знаходиться в Чорноскельних надрах, ти маєш відшукати його.\n\nДумаєш, пастка? Яка ще пастка, що ти верзеш?! Негайно іди туди!", [3] = "Знайдіть командира Ґор'шака в Чорноскельних надрах.\n\nВи пригадуєте, що поверх портрета орка були намальовані ґрати. Можливо, варто відшукати якусь в'язницю.", [5] = "У нас обмаль часу. Слухай уважно, {раса:к}. Те, що я розкажу тобі, є секретною інформацією.", ["en"] = "Commander Gor'shak" },
    [3982] = { [1] = "Що відбувається?", [2] = "Мене відправили сюди під захистом Тралла. Ти справді думаєш, що ці блазні могли мене схопити? Я дозволив себе схопити, щоб зібрати розвіддані.\n\n<Ґор'шак шепоче.>\n\nПринцесу Залізогарту — Бронзобороду, викрав імператор Тауріссан. Вона в цьому місті! Б'юся об заклад, серце старого Маґні мало не зупинилося, коли він почув про це.\n\n<Ґор'шак сміється.>\n\nТихо! Ти це чуєш? Варта йде! ЗАХИЩАЙСЯ!", [3] = "Захистіть Ґор'шака.", [4] = "Захищайся, {стать:дурень:дурепо}!", [5] = "Ледь не вляпались. Але тепер вони знають, що ти тут... і неодмінно відправлять ще більше вартових.", ["en"] = "What Is Going On?", ["tasks"] = { ["Survive the Onslaught"] = "Пережити натиск" } },
    [4001] = { [1] = "Що відбувається?", [2] = "Поки що я не зміг толком поспілкуватись з дворфом Хараном, що сидить в камері навпроти. Однак мені вдалося переконати його, що я, точніше — ми, не бажаємо йому зла.\n\nПоговори з ним і дізнайся якомога більше про принцесу та її викрадачів. Перекажи всю інформацію воєвождю.\n\nТралл не хоче, щоб принцесі зашкодили, в нього навіть є якийсь грандіозний план для її безпечного повернення в Залізогарт. Харан вже все це знає... Йди!", [3] = "Поговоріть з Хараном Могутнім Молотом і дізнайтесь деталі про викрадення принцеси Мойри Бронзобородої. Передайте цю інформацію Траллу в Орґріммар.\n\nВи пригадуєте, як Ґор'шак говорив, що Харана утримують у в'язниці неподалік.", [4] = "Що привело тебе в це кляте місце?", [5] = "Це шанс для Орди назавжди змінити політичну ситуацію в нашому понівеченому війною світі. Слухай уважно, {ім'я}.\n\nПровал цієї місії — неприпустимий.", ["en"] = "What Is Going On?", ["tasks"] = { ["Information Gathered from Kharan"] = "Інформація, зібрана з Харана" } },
    [4002] = { [1] = "Східні Королівства", [2] = "Ти {стать:приніс:принесла} чудову інформацію, {ім'я}.\n\nЯк воєвождь, я зобов'язаний робити тільки найкраще для Орди. Щоб наші наступні покоління не були приречені на безнадійне існування.\n\nНам випала можливість визначити долю наших майбутніх союзів. Допомога дворфам може значно зміцнити наші відносини з Східними Королівствами. Тому ти не можеш зазнати невдачі!\n\nТи {стать:готовий:готова}?", [3] = "Поговоріть з Траллом, якщо ви готові взятися за його завдання.", [5] = "Відтепер шляху назад немає, {ім'я}.", ["en"] = "The Eastern Kingdoms" },
    [4003] = { [1] = "Порятунок принцеси", [2] = "Цей удар по дворфах Темного Заліза прокотиться ударною хвилею по всьому королівству.\n\nПринцеса Бронзоборода перебуває під впливом чар імператора Тауріссана. Щоб звільнити її, ти маєш вбити імператора. Будь {стать:обережний:обережна}, твоє завдання вдвічі небезпечніше, оскільки Бронзоборода без вагань нападе на тебе, перебуваючи під впливом імператора.\n\nНЕ НАШКОДЬ ЇЙ!", [3] = "Вбийте імператора Даґрана Тауріссана та звільніть принцесу Мойру Бронзобороду від його злих чар.", [4] = "<Принцеса Мойра тремтить від страху.>", [5] = "Що ти {стать:накоїв:накоїла}?!", ["en"] = "The Royal Rescue", ["tasks"] = { ["Emperor Dagran Thaurissan"] = "Імператор Дагран Таурісан", ["Emperor Dagran Thaurissan (Provided)"] = "Імператор Дагран Таурісан (видано)", ["Emperor Dagran Thaurissan slain"] = "Імператор Дагран Таурісан: убито" } },
    [4004] = { [1] = "Принцеса врятована?", [2] = "Ти {стать:вбив:вбила} мого чоловіка, {раса:к}! Моя дитина з'явиться на світ без батька!\n\n<Принцеса Мойра вказує на вас.>\n\nЗапевняю тебе, це дитя стане наступним правителем Залізогарту. За цей злочин тебе і твій рід переслідуватимуть до кінця днів!\n\n<Ви впевнені, що принцеса Мойра досі перебуває під дією чар Тауріссана.>\n\nЗалиш мене, {раса:к}. Я впевнена, твій воєвождь буде радий почути про успішне виконання його мерзенних задумів.", [3] = "Поверніться до Тралла!", [5] = "<Тралл приголомшений вашою розповіддю.>\n\nНезабаром в нас з'явиться нова загроза. Коли Маґні не стане, шлях до трону Залізогарта буде відкритий для ще ненародженого спадкоємця Темного Заліза.\n\nТи {стать:виконав:виконала} моє доручення й отримаєш за це винагороду.\n\nА тепер залиш мене, {ім'я:к}! Я маю порадитись з Сильваною та Керном.", ["en"] = "The Princess Saved?" },
    [4021] = { [1] = "Контратака!", [2] = "Орда високо цінує твої успіхи в боротьбі із кланом Колкар, але вони самі шаленіють від люті. У мене є відомості про те, що загін Колкарів покинув Спустошище, свою домівку, та попрямував до Степів у пошуках помсти. Останній звіт говорив про те, що вони вже зараз на підході до цих укріплень, із заходу!\n\nВиступи проти Колкарів-загарбників і поклади кінець небезпеці, що вони несуть Степам. Убивай їх, допоки не з'явиться їхній вождь, воєвода Кром'зар. Здолай його та принеси клаптик його стягу як доказ твоєї перемоги.\n\nМи розраховуємо на тебе, {ім'я}.", [3] = "Принесіть клаптик стягу Кром'зара Реґтарові Згубобрамі на захід від Перехрестя.", [4] = "Ти {стать:приніс:принесла} стяг?", [5] = "Тобі вдалося! Ти {стать:переміг:перемогла} плем'я Колкар!\n\nЯ переконаюся, щоб Тралл дізнався про твої тутешні звитяги, {ім'я}.\n\nОрда пишається тобою, пишайся й ти!", ["en"] = "Counterattack!", ["tasks"] = { ["Piece of Krom'zar's Banner"] = "клаптик стягу Кром'зара", ["Piece of Krom'zar's Banner (Provided)"] = "клаптик стягу Кром'зара (видано)" } },
    [404] = { [1] = "Cмердюче завдання", [2] = "Скара просочилася у Тірісфальське перелісся та заполонила місцевість на захід від Брілля, біля старого мосту.\n\nСтупай туди і відбий гниючих мерців і порваних трупів, яких там знайдеш. Порозкидай їхні кістки та принеси їхні смердючі пазури, і смертестражі нагородять тебе.", [3] = "Принесіть 7 смердючих пазурів смертестражу Діллінджеру в Брілль.", [4] = "Ти вже {стать:виконав:виконала} завдання, яке я тобі доручив? {стать:Приніс:Принесла} мені смердючі пазури?", [5] = "Гарна робота. Шкода, мене там не було, щоб побачити, як ти трощиш цих мерців в гниючу масу!", ["en"] = "A Putrid Task", ["tasks"] = { ["Putrid Claw"] = "смердючий пазур", ["Putrid Claw (Provided)"] = "смердючий пазур (видано)" } },
    [405] = { [1] = "Блудний ліч", [2] = "Бетор Кригозлам, високопоставлений і могутній маг у Підмісті на півдні, наказує мені прислати йому {стать:підлеглого:підлеглу} з доведеною цінністю в боротьбі зі Скарою. Ти, {Ім'я}, {стать:ним:нею} станеш.\n\nПокажи ці накази Беторові. Після цього він проінструктує тебе щодо твоєї місії. Я не знаю деталей, але вона пов'язана із залученням на наш бік якогось норовливого ліча. І вона буде небезпечною.\n\nТож приготуйся, {клас:к}. Ти {стать:повинен:повинна} не підвести.\n\nТи зможеш знайти Бетора у кварталі Магії у Підмісті.", [3] = "Покажіть накази Севрена Бетору Кригозламові в Підмісті.", [4] = "Вітаю. Або ти не знаєш, хто я, або твоя справа до мене невідкладна.\n\nТому що якщо жоден з цих здогадів не правдивий, ти б не {стать:був:була} настільки {стать:нерозумним:нерозумною}, щоб тривожити мене...", [5] = "А-а, ти - {стать:той підлеглий, якого:та підлегла, яку} прислав війт Севрен. Тоді, так - твоя справа до мене є надважливою.\n\nЯ вірю, що він залучив когось, придатного для мого завдання... але побачимо.", ["en"] = "The Prodigal Lich", ["tasks"] = { ["Sevren's Orders"] = "накази Севрена", ["Sevren's Orders (Provided)"] = "накази Севрена (видано)" } },
    [4061] = { [1] = "Повстання машин", [2] = "Вперше ми побачили ці машини, коли почались набіги в Випалену ущелину. Потім з'ясувалося, що їх привозять з Палаючого степу, можливо з Чорноскельних надр. Саме для цього нам і знадобиться твоя допомога, {ім'я}.\n\nТвоє перше завдання — вирушити в Палаючий степ та зібрати уламки елементалів з кам'яних големів та менших кам'яних створінь цього регіону. Коли збереш достатню кількість, повертайся до мене, і я спробую дізнатися, звідки вони походять.", [3] = "Відправляйтеся в Палаючий степ і знайдіть 10 уламків елементалів для ієрофанта Теодори Мульваданії.\n\nВи пригадуєте, що Теодора згадувала про големів та елементалів цього регіону.", [4] = "Не стався до цього завдання легковажно, {ім'я}!", [5] = "<Теодора розкладає перед собою фрагменти.>\n\n<Теодора уважно розглядає фрагменти за допомогою величезного монокля.>\n\nЦікаво. На структурній основі кожного з цих фрагментів викарбувані... ініціали.", ["en"] = "The Rise of the Machines", ["tasks"] = { ["Fractured Elemental Shard"] = "тріснутий уламок елементаля", ["Fractured Elemental Shard (Provided)"] = "тріснутий уламок елементаля (видано)" } },
    [4062] = { [1] = "Повстання машин", [2] = "П.Г.А.\n\nЦі 'ініціали' вигравіювані на уламках елементалей. Під ними викарбувано напис, мабуть, що вказує на якийсь ранг. Механізми, що ти {стать:знищив:знищила} у Палаючому степу, мали 'Ранг IV'. Я припускаю, що це найнижчий ранг.\n\nВіднеси цей зразок уламка Лотвілю Веріату у таборі на сході. Це відомий вчений, що вивчає елементалей. Він може допомогти нам.", [3] = "Віднесіть зразок уламка елементаля Лотвілю Веріату.\n\nВи згадуєте як Теодора казала, що Лотвіль зупинився у таборі на сході.", [4] = "Що там у тебе, {раса:к}?", [5] = "<Лотвіль несподівано блідне.>\n\nЯ... Я впізнаю це маркування.", ["en"] = "The Rise of the Machines", ["tasks"] = { ["Elemental Shard Sample"] = "зразок уламка елементаля", ["Elemental Shard Sample (Provided)"] = "зразок уламка елементаля (видано)" } },
    [4063] = { [1] = "Повстання машин", [2] = "Це не може бути Арґельмах! Його вбили десять років тому. Чому я такий впевнений? Я сам його вбив.\n\nВін був мерзенним одержимим дворфом, який постійно знущався з моїх винаходів, щоб задовольнити власні диявольські потреби. Здається, що такі мерзенні істоти, як він, завжди знаходять спосіб уникнути правосуддя.\n\nЯкщо це справа рук Арґельмаха, то його треба знищити. Мені потрібні зразки його останніх творінь. З хорошими зразками я, скоріше за все, зможу зупинити це повстання. Арґельмаха охороняють його творіння в Чорноскельних надрах.", [3] = "Знайдіть та вбийте повелителя големів Арґельмаха. Віднесіть його голову Лотвілю. Також зберіть 10 неушкоджених ядер елементалей з нещадних големів та бойових творінь, що захищають Арґельмаха. Вам передали цю інформацію у підсвідомість.", [4] = "Це був він? Він справді живий?", [5] = "Що це таке?!? Ця голова не з плоті, це якесь створіння з темного заліза. Тінь Арґельмаха була ЩЕ ОДНОЮ машиною! Підозрюю, що Арґельмах знищений ненадовго, і на його місці незабаром буде інший.", ["en"] = "The Rise of the Machines", ["tasks"] = { ["Head of Argelmach"] = "голова Арґельмаха", ["Head of Argelmach (Provided)"] = "голова Арґельмаха (видано)", ["Intact Elemental Core"] = "неушкоджене ядро елементаля", ["Intact Elemental Core (Provided)"] = "неушкоджене ядро елементаля (видано)" } },
    [407] = { [1] = "Поля cкорботи", [2] = "Невинні гарбузи, чи не так? Принаймні, так здається. Якщо ми хочемо перемогти наступ Артаса з півночі та людську пошесть з півдня, нам варто почати використовувати весь потенціал нашого дару невмирущості.\n\nТрішки винахідливості — і простий гарбуз стає кинджалом в руках Темної Леді. Цей овоч, наповнений моїм останнім винаходом, стане чудовим частуванням.\n\nТут спіймали ще одного ревнителя Багряного Походу, і він зараз у підвалі таверни «Край шибениці». Принеси гарбуз цьому бовдурові.", [3] = "Принесіть оброблений гарбуз до полоненого ревнителя Багряного Походу, якого утримують у підвалі таверни «Край шибениці».", [4] = "Забирайся, мерзотне й осквернене створіння! Світло, захисти мене! Багряний Похід очистить Азерот від твоєї...\n\n...стривай. Ця їжа - для мене? Я такий голодний…", [5] = "Хвала Світлу! Нарешті їжа! Такий солодкий, солодущий гарбуз...", ["en"] = "Fields of Grief", ["tasks"] = { ["Laced Pumpkin"] = "оброблений гарбуз", ["Laced Pumpkin (Provided)"] = "оброблений гарбуз (видано)" } },
    [408] = { [1] = "Сімейний склеп", [2] = "Місцевість біля млинів Аґамандів стала плацдармом для Скари. Їхньою найукріпленішою точкою є сімейний склеп Аґамандів, де створив штаб їх командувач, скелет на ім'я капітан Дарґол. Силою некромантії він підняв предків Аґамандів і планує використати їх проти нас.\n\nТак не піде, і ти мусиш це зупинити. Вирушай до сімейного склепу Аґамандів і побори піднятих предків.\n\nА ще принеси мені череп капітана Дарґола.", [3] = "Убийте 8 тужливих предків і 8 гниючих предків.\n\nУбийте капітана Дарґола та принесіть його череп війту Севрену до Брілля.", [4] = "Час - це розкіш, і його у нас обмаль, {Ім'я}. З кожною годиною сила Скари у Тірісфальському переліссі міцніє.", [5] = "Твої дії завдали важкого удару по Скарі. І твоя перемога не залишиться непоміченою - ні відреченими, ні нашими ворогами.\n\nПродовжуй боротися, як всі ми, {Ім'я}, й одного дня ми виженемо з Азероту самого Короля-ліча!", ["en"] = "The Family Crypt", ["tasks"] = { ["Dargol's Skull"] = "череп Дарґола", ["Dargol's Skull (Provided)"] = "череп Дарґола (видано)", ["Rotting Ancestor"] = "гниючий предок", ["Rotting Ancestor slain"] = "гниючий предок: убито", ["Wailing Ancestor"] = "тужливий предок", ["Wailing Ancestor slain"] = "тужливий предок: убито" } },
    [4081] = { [1] = "ВБИТИ НА МІСЦІ: дворфи Темного Заліза", [2] = "За наказом воєводи Клинозуба, командира карґатського експедиційного загону:\n\nВсі сили генерала Кузні Гніву в Чорноскельних надрах мають бути знищені.\n\nДворфи Лютого Ковадла — безжальні вбивці, відповідальні за масове вбивство 109-ї дивізії карґатського експедиційного загону. Потрібно бути вкрай обережними у протистоянні з цими покидьками.\n\nКожен, хто зробить свій внесок в знищення фронтових військ генерала Кузні Гніву в Чорноскельних надрах, отримає нагороду.", [3] = "Відправляйтеся в Чорноскельні надра та винищіть нікчемних агресорів!\n\nВоєвода Клинозуб хоче, щоб ви вбили 15 гвардійців, 10 вартових та 5 піхотинців Лютого Ковадла. Поверніться до нього, коли виконаєте завдання.", [4] = "Що таке, {раса:к}? Не бачиш, що мені ще взводом командувати?", [5] = "Цей удар має добряче налякати Кузню Гніву. А тепер, іди, солдате. У мене ще є робота, яку треба завершити, битви, які треба спланувати та вороги, яких треба знищити!\n\nСлідкуй за оголошеннями, можливо, ще знайдеться робота для тебе.", ["en"] = "KILL ON SIGHT: Dark Iron Dwarves", ["tasks"] = { ["Anvilrage Footman"] = "піхотинець Лютого Ковадла", ["Anvilrage Footman slain"] = "піхотинець Лютого Ковадла: убито", ["Anvilrage Guardsman"] = "гвардієць Лютого Ковадла", ["Anvilrage Guardsman slain"] = "гвардієць Лютого Ковадла: убито", ["Anvilrage Warden"] = "вартовий Лютого Ковадла", ["Anvilrage Warden slain"] = "вартовий Лютого Ковадла: убито" } },
    [4082] = { [1] = "ВБИТИ НА МІСЦІ: Високопоставлені чиновники Темного Заліза", [2] = "За наказом воєводи Клинозуба, командира карґатського експедиційного загону:\n\nГолова розвідувального підрозділу К.Е.З., гросмейстер Лекслорт, повернувся з новинами про місцеперебування високопоставлених чиновників Темного Заліза. За зачиненими воротами, в самому серці міста, вони тренують своїх солдатів знищувати наших людей. Відправляйтесь в Чорноскельні надра та знищте їх!\n\nЗа виконання цього завдання ви отримаєте винагороду.", [3] = "Відправляйтеся в Чорноскельні надра та винищіть нікчемних агресорів!\n\nВоєвода Клинозуб хоче, щоб ви вбили 10 медиків, 10 солдатів та 10 офіцерів Лютого Ковадла. Поверніться до нього, коли виконаєте завдання.", [4] = "Знову ти? Мушу потиснути тобі руку, {ім'я}, ти досить {стать:наполегливий:наполеглива}.", [5] = "Кузня Гніву безсумнівно... розгнівається. Повертайся до мене, коли отримаєш третю нагороду та ми займемось операцією \"Смерть Кузні Гніву\". Я не буду розголошувати подробиці, але дещо сказати можу — хтось точно помре.", ["en"] = "KILL ON SIGHT: High Ranking Dark Iron Officials", ["tasks"] = { ["Anvilrage Medic"] = "медик Лютого Ковадла", ["Anvilrage Medic slain"] = "медик Лютого Ковадла: убито", ["Anvilrage Officer"] = "офіцер Лютого Ковадла", ["Anvilrage Officer slain"] = "офіцер Лютого Ковадла: убито", ["Anvilrage Soldier"] = "солдат Лютого Ковадла", ["Anvilrage Soldier slain"] = "солдат Лютого Ковадла: убито" } },
    [409] = { [1] = "Доказ вірності", [2] = "Ти кажеш, що ти не {стать:підвладний:підвладна} Королю-лічу, і чари, які Бетор наклав на мій фоліант, підтверджують це. Але перед тим, як повірити тобі, мені потрібен доказ, що ти є ворогом Скари.\n\nПри південному березі цього острова є старий закривавлений вівтар. Його використовує могутня прислужниця Скари, Лілліт Нефара.\n\nВізьми свічку поклику з ось цього ящика. Запалиш її на вівтарі — і Лілліт прокинеться. Знищ її, і тоді я повірю, що ти — ворог Короля-ліча.", [3] = "Здобудьте свічку поклику.\n\nВикличте Лілліт Нефару та вбийте її.\n\nПоверніться до Ґюнтера на його острів.", [4] = "Я очікую на доказі твоєї вірності, {клас:к}.", [5] = "Ти {стать:переміг:перемогла} Лілліт Нефару та цим {стать:довів:довела}, що ти є справжнім ворогом Скари. Неймовірно.\n\nЯ думав, що тільки я є {стать:невмерлим:невмерлою} зі свободою волі, але ти {стать:показав:показала} мені, що є й інші, хто спромігся вирватися з-під панування Короля-ліча.", ["en"] = "Proving Allegiance", ["tasks"] = { ["Lillith Nefara"] = "Лілліт Нефара", ["Lillith Nefara slain"] = "Лілліт Нефара: убито" } },
    [410] = { [1] = "Дрімотна тінь", [4] = "Це старий, пощерблений, закривавлений стіл.", [5] = "Ви ставите свічку поклику на стіл і запалюєте її...", ["en"] = "The Dormant Shade", ["tasks"] = { ["Candle of Beckoning"] = "свічка поклику", ["Candle of Beckoning (Provided)"] = "свічка поклику (видано)" } },
    [4102] = { [1] = "Очищення Сквернолісся", [2] = "Рослини дають життя Скверноліссю, хоча навіть вони вражені скверною. Я знаю способи їх очищення, але не можу ділитися такими знаннями з тими, кого не знаю, чи кому не довіряю. Доведи мені, що ти дійсно {стать:союзник:союзниця} Кенарійського Кола!\n\nНа північ звідси знаходяться печери Залізолісся. На очищення тамтешніх елементалів, Хибнодревів, вже немає надії. Я прошу тебе принести мені їхню застиглу смолу, кривавий бурштин. Сподіваюсь, що вивчивши його, ми зможемо врятувати інші тутешні форми життя.", [3] = "Принесіть 15 кривавих бурштинів Майбессі Річковий Вітер у Сквернолісся.", [4] = "Я знаю, що Сквернолісся страждає, {ім'я} — я страждаю разом з ним! Але я маю залишатись стійкою у своїх переконаннях — якби мої знання зцілення потрапили в злі руки, це стало б катастрофою для всього Сквернолісся.\n\nПринеси мені кривавий бурштин з убитих Хибнодревів, і я повірю, що ти щиро допомагаєш мені в пошуках засобу боротьби зі скверною.", [5] = "Цей кривавий бурштин допоможе мені знайти засіб боротьби з заразою, що вразила Сквернолісся. Ти {стать:довів:довела} мені, що {стать:готовий:готова} зробити все для Кенарійського Кола. Тепер я довіряю тобі.\n\nМоже здатися дивним, що доказом твоєї відданості стало винищення елементалів, але порятунок безлічі живих істот виправдовує такі засоби. Тепер ми з тобою можемо зосередитись на порятунку життів за допомогою бальзамів, які я можу створити.\n\n{ім'я}, настав час очистити Сквернолісся.", ["en"] = "Cleansing Felwood", ["tasks"] = { ["Blood Amber"] = "кривавий бурштин", ["Blood Amber (Provided)"] = "кривавий бурштин (видано)" } },
    [4108] = { [1] = "Бальзам з уламків душ", [4] = "Маяк Кенарія дозволяє побачити уламки душ уражених оскверненням тварин, убитих заради загального блага. Я подрібню уламки душ на реагент, придатний для виготовлення кенарійського бальзаму зцілення рослин. Ми використовуємо цей засіб, щоб вилікувати уражені скверною рослини.\n\nВ обмін на ці уламки душ я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Дуже добре, ось тобі декілька порцій кенарійського бальзаму. Шукай в Скверноліссі осквернені рослини, {ім'я}! Як знайдеш їх — використовуй бальзам, щоб очистити їх.", ["en"] = "Salve via Hunting", ["tasks"] = { ["Corrupted Soul Shard"] = "уламок оскверненої душі", ["Corrupted Soul Shard (Provided)"] = "уламок оскверненої душі (видано)" } },
    [4109] = { [1] = "Бальзам з мінералів", [4] = "Якщо під час видобутку копалин в Скверноліссі в тебе буде з собою маяк Кенарія, ти зможеш побачити уражений купорос, що проникає в жили металів. Я знаю, як очистити цей купорос і перетворити його на реагент, придатний для виготовлення кенарійського бальзаму зцілення рослин. Ми використовуємо цей засіб, щоб вилікувати уражені скверною рослини.\n\nЯкщо ти принесеш мені уражений купорос, я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Дуже добре, ось декілька порцій кенарійського бальзаму. Якщо ти знайдеш уражений купорос, коли видобуватимеш копалини у Скверноліссі, не забудь притримати його для мене! Що більше ти знайдеш, то більше бальзаму я зможу зробити.", ["en"] = "Salve via Mining", ["tasks"] = { ["Tainted Vitriol"] = "уражений купорос", ["Tainted Vitriol (Provided)"] = "уражений купорос (видано)" } },
    [411] = { [1] = "Повернення блудного ліча", [2] = "Віднеси цей самоцвіт Підсвіття до мого старого друга Бетора. З його допомогою ми зможемо спілкуватися... а я багато чого маю йому розповісти.", [3] = "Віднесіть самоцвіт Підсвіття до Бетора Кригозлама в Підмістя.", [4] = "Ти {стать:повернув:повернула} книжку Ґюнтера? Він щось відповів?", [5] = "Ти {стать:переконав:переконала} його приєднатися до нас! Ти {стать:вчинив:вчинила} велике діло для відречених, {Ім'я}. Темну Леді сповістять про це.", ["en"] = "The Prodigal Lich Returns", ["tasks"] = { ["Nether Gem"] = "самоцвіт Підсвіття", ["Nether Gem (Provided)"] = "самоцвіт Підсвіття (видано)" } },
    [4110] = { [1] = "Бальзам з осквернених трав", [4] = "Маяк Кенарія дозволяє досвідченому травнику помітити залишок скверни — мерзенний продукт осквернення, що вразило Сквернолісся. Моя робота в Скверноліссі дозволила мені навчитися перетворювати залишок скверни в очисний реагент... який ми використовуємо в кенарійському бальзамі зцілення рослин.\n\nКоли ти збиратимеш трави в Скверноліссі, ти зможеш натрапити на залишок скверни, якщо матимеш при собі маяк. В обмін на залишки я виготовлю для тебе кенарійський бальзам.", [5] = "Чудова робота, {ім'я} — коли ми їх очистимо, вони допоможуть нам повернути Сквернолісся до життя. Ось, візьми кілька порцій кенарійського бальзаму зцілення рослин та прямуй до лісу. Зцілення цих земель від скверни — невідкладна справа!", ["en"] = "Salve via Gathering", ["tasks"] = { ["Fel Creep"] = "залишок скверни", ["Fel Creep (Provided)"] = "залишок скверни (видано)" } },
    [4111] = { [1] = "Бальзам зі шкір", [4] = "Маяк Кенарія дає змогу досвідченому шкуродеру знаходити серед зібраної у Скверноліссі шкіри ту, що уражена скверною. Я переробляю цю здавалось би непотрібну шкіру в густу пасту, що прискорює дію кенарійського бальзаму зцілення рослин. Коли будеш займатися шкуродерством у Скверноліссі, обов'язково тримай при собі маяк!\n\nКоли збереш клапті ураженої шкіри — принеси їх мені, і я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Це саме те, що мені потрібно. Ось — візьми кенарійський бальзам, щоб очистити рослини Сквернолісся від осквернення. Ми повинні боротися, {ім'я}!", ["en"] = "Salve via Skinning", ["tasks"] = { ["Patch of Tainted Skin"] = "клапоть ураженої шкіри", ["Patch of Tainted Skin (Provided)"] = "клапоть ураженої шкіри (видано)" } },
    [4112] = { [1] = "Бальзам з розбитих чарів", [4] = "Сила магічного предмета відповідає силі субстанцій, які отримують унаслідок розбиття його чарів. Я винайшла спосіб перероблення сирих субстанцій, які використовують накладачі чарів, у реагент, придатний для створення кенарійського бальзаму зцілення рослин. Для цього тобі не потрібен маяк Кенарія — підійде будь-який магічний предмет, розбиття чарів якого дає малі підсвітні субстанції.\n\nМені потрібна лише одна така субстанція. За на неї я дам тобі кенарійський бальзам зцілення рослин. Підсвітня субстанція дуже потужна — навіть одної вистачить надовго!", [5] = "Ось кілька порцій кенарійського бальзаму зцілення рослин, {ім'я}, і за нього я прошу лише одну малу підсвітню субстанцію. Субстанція — це найпотужніша речовина, яку я можу використати для створення бальзаму. Якщо тобі знадобиться більше бальзаму — приходь до мене.", ["en"] = "Salve via Disenchanting", ["tasks"] = { ["Lesser Nether Essence"] = "мала підсвітня субстанція", ["Lesser Nether Essence (Provided)"] = "мала підсвітня субстанція (видано)" } },
    [4120] = { [1] = "Сила скверни", [2] = "Як мисливець, я намагаюсь вивчати сильні сторони своїх супротивників. Знання ворога може обернути ситуацію в битві на твою користь, {ім'я}.\n\nУ місці, під назвою Сквернолісся, на північ від Ясенедолу, створіння заразилися субстанцією, що називають скверною. Ведмеді та вовки від неї геть оскаженіли, але водночас скверна зробила їх ще сильнішими.\n\nЙди, {ім'я}. Вирушай до Сквернолісся та вбий цих звірів. Дізнайся, чи справді вони такі сильні.", [3] = "Тало Обдерте Копито з табору Мохаче, що у Фераласі, просить вас вбити 12 гризлі-лютопазурів та 12 сквернолапих спустошників у Скверноліссі.", [4] = "Все, до чого торкається скверна, випромінює дивне зелене сяйво... Я відчуваю, що воно зле, але водночас дуже потужне.", [5] = "З твоїх слів звучить так, ніби істоти проявляють безглузду жорстокість...\n\nБудь {стать:пильним:пильною}, {ім'я}. У твоїх інтересах дізнатися більше про скверну. Завжди знай свого ворога.", ["en"] = "The Strength of Corruption", ["tasks"] = { ["Angerclaw Grizzly"] = "гризлі-лютопазур", ["Angerclaw Grizzly slain"] = "гризлі-лютопазур: убито", ["Felpaw Ravager"] = "сквернолапий спустошник", ["Felpaw Ravager slain"] = "сквернолапий спустошник: убито" } },
    [4121] = { [1] = "Скрутне становище", [2] = "Ти справді віриш, що зможеш дістатися до місця зустрічі, тримаючи мене під вартою? Ти розраховуєш увірватися до добре захищеної фортеці Чорнокаменю та, викравши їхній цінний актив, втекти {стать:непоміченим:непоміченою}?\n\nТе тебе порвуть на шматки!", [3] = "Проведіть вашого полоненого, Ґрарка Лоркруба, через Палаючий степ та Чорноскельну гору до Випаленої ущелини.\n\nВи пригадуєте, як Лекслорт казав, що його підлеглі чекатимуть на тому боці, щоб взяти Ґрарка під варту.\n\nВам також потрібно віддати Лекслорту торієві кайдани.", [4] = "Давай сюди цього зрадливого мерзотника, {ім'я}.", [5] = "Твій героїзм не залишиться непоміченим, {ім'я}. Ти {стать:заслужив:заслужила} цю винагороду. Тепер воєвода розповість тобі деталі останнього завдання.", ["en"] = "Precarious Predicament", ["tasks"] = { ["Thorium Shackles"] = "торієві кайдани", ["Thorium Shackles (Provided)"] = "торієві кайдани (видано)" } },
    [4122] = { [1] = "Ґрарк Лоркруб", [2] = "Я йшов за ним від Випаленої ущелини, через гору аж до Палаючого степу. Цього зрадника спіймали на гарячому, коли він передавав оркам Чорнокаменю важливу інформацію про нашу діяльність. Я говорю про Ґрарка Лоркруба.\n\nЗараз його тримають у Палаючому Степі, під їхньою надійною вартою — принаймні він так думає.\n\nВізьми ці кайдани, {ім'я}. Знайди Грарка, одягни їх на нього та проведи його через Чорноскельну гору. Зроби це і винагорода твоя.", [3] = "Вирушайте до Палаючого степу та знайдіть Ґрарка Лоркруба. Лекслорт розповідав, що його востаннє бачили у фортеці близ Чорноскельної гори.\n\nЗнайшовши Ґрарка Лоркруба, надягніть на нього торієві кайдани, а потім проведіть через Чорноскельну гору до Випаленої ущелини. На іншому боці на вас чекатимуть підлеглі Лекслорта, які візьмуть Ґрарка під варту.", [5] = "Хіба ти не розумієш, яку силу можна здобути, приєднавшись до легіону Чорнокаменю?", ["en"] = "Grark Lorkrub", ["tasks"] = { ["Thorium Shackles"] = "торієві кайдани" } },
    [4132] = { [1] = "Операція: смерть Кузні Гніву", [2] = "Ти чудово {стать:виконав:виконала} роботу, {ім'я}. Настав час для останнього завдання.\n\nГенерал Кузня Гніву, відповідальний за напад Темного Заліза на 109-ту дивізію К.Е.З. і масове вбивство наших військ, повинен бути притягнутий до відповідальності.\n\nБезсумнівно, це буде найважче завдання для тебе, але якщо ти його виконаєш, тебе щедро винагородять.", [3] = "Вирушайте в Чорноскельні надра та вбийте генерала Кузню Гніву! Коли виконаєте завдання, поверніться до воєводи Клинозуба.", [4] = "Ти {стать:розправився:розправилася} з м'ясарем Чорнокаменю?", [5] = "Нарешті! Лиходія притягнуто до відповідальності! Ти {стать:видатний герой:видатна героїня}, {ім'я}. Носи цей медальйон як символ твоєї непохитної відданості Орді та К.Е.З.", ["en"] = "Operation: Death to Angerforge", ["tasks"] = { ["General Angerforge"] = "генерал Кузня Гніву", ["General Angerforge slain"] = "генерал Кузня Гніву: убито" } },
    [4133] = { [1] = "Вівіан Лягроб", [2] = "Вівіан Лягроб потрібна твоя допомога. Вона зараз в Безплідних краях, на сторожовій заставі Карґат, розслідує чутки про якесь вариво, виготовлене дворфами Темного Заліза в Чорноскельних надрах.\n\nПоговори з Вівіан. Вона на тебе чекає.", [3] = "Поговоріть з тінемагинею Вівіан Лягроб у Карґаті.", [5] = "Дякую, що {стать:прийшов:прийшла}, {ім'я}. Це місце має свій особливий шарм, але йому бракує деяких принад з Апотекарія.\n\nДосить люб'язностей. Перейдемо до справи, так?", ["en"] = "Vivian Lagrave" },
    [4145] = { [1] = "Ларіон та Муїджін", [2] = "Бачиш Муїджіна он там? Це ЙОГО провина, що ми загубилися!\n\nЯ знав дорогу, але він наполягав, що знає коротший шлях, і ось ми застрягли тут!\n\nЩо ще гірше, тепер він взявся розводити кляті кровоцвіти, щоб дошкуляти мені. Я розлючений, і не збираюся розмовляти з ним, але ці рослини неможливо ігнорувати.\n\nЧому б нам не спробувати обмежити його постачання? Перш за все, йди та вбий кровоцвітів, а потім повертайся до мене.", [3] = "Вполюйте 5 кровоцвітів-хляскунів, 5 кровоцвітів-молотників, 5 кровоцвітів-потрошителів та 5 кровоцвітів-капканників для Ларіона з прихистку Маршала.", [4] = "Муїджін спочатку має попросити вибачення, якщо хоче, щоб я з ним розмовляв!", [5] = "Дякую за допомогу, {ім'я}, але, боюся, у мене погані новини...", ["en"] = "Larion and Muigin", ["tasks"] = { ["Bloodpetal Flayer"] = "кровоцвіт-потрошитель", ["Bloodpetal Flayer slain"] = "кровоцвіт-потрошитель: убито", ["Bloodpetal Lasher"] = "кровоцвіт-хляскун", ["Bloodpetal Lasher slain"] = "кровоцвіт-хляскун: убито", ["Bloodpetal Thresher"] = "кровоцвіт-молотник", ["Bloodpetal Thresher slain"] = "кровоцвіт-молотник: убито", ["Bloodpetal Trapper"] = "кровоцвіт-капканник", ["Bloodpetal Trapper slain"] = "кровоцвіт-капканник: убито" } },
    [4146] = { [1] = "Паливо для знищувача", [2] = "Тобі пощастило, {ім'я}! Поки Марвона не було, я працювала над власними експериментами, і одним з них є прилад для знищення жуків на короткій відстані. Після деяких налаштувань він відмінно підійде для боротьби з цими кровоцвітами.\n\nЯ можу дати тобі один з моїх зразків знищувача, але тобі все одно потрібно буде зібрати паливо для нього. Тобі знадобиться туман Атал'ай, який можна знайти в храмі Атал'Гаккар. Його можна зібрати з глибинних маскунів, болотяних червів або слизнів, що там зустрічаються.", [3] = "Віднесіть розряджений знищувач і 5 зразків туману Атал'ай Ларіону в прихисток Маршала.", [4] = "Це виснажливо, {ім'я}. Вони не дають мені спокою!", [5] = "Отже, Марвона не було? Ну, все одно показуй, що там в тебе.", ["en"] = "Zapper Fuel", ["tasks"] = { ["Atal'ai Haze"] = "туман Атал'ай", ["Atal'ai Haze (Provided)"] = "туман Атал'ай (видано)", ["Unloaded Zapper"] = "розряджений знищувач", ["Unloaded Zapper (Provided)"] = "розряджений знищувач (видано)" } },
    [4147] = { [1] = "Майстерня Марвона", [2] = "Мені вдалося підглянути, що робить Муїджін, і він насправді вирощує ці кляті рослини!\n\nДумаю, єдине, що я можна зробити... ні, не йти балакати з ним... Про що ти думаєш? Ми маємо боротись!\n\nНам знадобиться допомога мого друга Марвона, котрий має майстерню в Брашпилі. Думаю, він зможе створити якийсь пристрій, що допоможе нам.", [3] = "Рушайте в майстерню Марвона Заклепника в Брашпилі.", [5] = "Марвона вже давно немає, {ім'я}. Він поїхав у Танаріс вивчати руїни древніх тролів.\n\nОтже, ти {стать:казав:казала}, що тобі щось потрібно?", ["en"] = "Marvon's Workshop" },
    [421] = { [1] = "Доведи свою цінність", [2] = "Леді Сильвана доручила Варіматрасу завоювати людські та дворфські землі на півдні.\n\nАле цей дурень, Аруґал - даларанський шарлатан, а тепер проклятий звір із фортеці Тіньового Ікла - дозволив своїй безрозсудній магії посіяти хаос у стратегічній твердині Срібнохвойного пралісу.\n\nМені потрібен хтось досвічений у битвах, щоб допомогти розгребти цей безлад Аруґала. Доведи мені свою придатність, вбивши 5 білоскальпів Місяцесказу. Цих мерзенних звірюк часто можна знайти одразу на узбіччі дороги, уздовж схилу нижче.", [3] = "Далар Ранньоткач з Крипти хоче, щоб ви вбили 5 білоскальпів Місяцесказу.", [4] = "Якщо хочеш довести мені свою придатність — вбий 5 білоскальпів Місяцесказу. Виконай це завдання, і я подбаю про те, щоб твої вміння були застосовані в серйозніших завданнях.", [5] = "Ти добре {стать:послужив:послужила} мені, {клас:к}. Мені очевидно, що ти будеш {стать:гідним помічником:гідною помічницею} в позбавленні Срібнохвойного пралісу від прокляття Аруґала.", ["en"] = "Prove Your Worth", ["tasks"] = { ["Moonrage Whitescalp"] = "білоскальп Місяцесказу", ["Moonrage Whitescalp slain"] = "білоскальп Місяцесказу: убито" } },
    [422] = { [1] = "Дурість Аруґала", [2] = "Як Аруґала взагалі прийняли в Кірін-Торі - за межею мого розуміння. Його знання у застосуванні заклять здавалися такими ж прозорими, як скляна куля.\n\nЩо важливо зараз - так це дізнатися, яку саме магію використовував Аруґал, щоб я міг обернути її проти нього і забезпечити панування Темної Леді у Срібнохвойному пралісі.\n\nСпочатку Аруґал зупинився на пшеничній фермі, що на північ від мосту. Один зі смертоловів повідомив, що бачив якісь книги з закляттями, але не зміг їх взяти. Знайди для мене закляття з назвою \"Засіб Аруґала\" серед цих книг.", [3] = "Роздобудьте \"Засіб Аруґала\" для Далара Ранньоткача з Крипти.", [4] = "Перш ніж я дізнаюся, з чим ми маємо тут справу, {клас:к}, я повинен ретельно дослідити закляття, відоме як \"Засіб Аруґала\". Принеси його мені, або я буду змушений знайти собі більш гідного слугу.", [5] = "Так, це саме те закляття, яке я шукав, {клас:к}. Якщо твоя відданість справі Темної Леді залишиться непохитною, на тебе чекає досить непогане майбутнє серед відречених.", ["en"] = "Arugal's Folly", ["tasks"] = { ["Remedy of Arugal"] = "\"Засіб Аруґала\"", ["Remedy of Arugal (Provided)"] = "\"Засіб Аруґала\" (видано)" } },
    [423] = { [1] = "Дурість Аруґала", [2] = "Після вивчення роботи Аруґала мої найгірші підозри справдилися. Старий шкарбан не був гідним навіть для чистки нічних горщиків у Даларані, не кажучи вже про те, щоб представляти Кірін-Тор у його найжахливішу годину. Дурні!\n\nАруґал використовував зачаровані предмети для підсилення своєї нікчемної магії. Мені потрібно особисто дослідити ці речі. Прямуй далі та вбивай ненажер і темнодухів Місяцесказу, доки не збереш достатню кількість їхніх зачарованих кайданів для мого дослідження. Цих мерзенних істот бачили на півночі та на сході.", [3] = "Принесіть 6 кайданів ненажер та 3 кайданів темнодухів Даларові Ранньоткачу в Крипту.", [4] = "Мені потрібні 6 кайданів ненажер та 3 кайданів темнодухів, перш ніж я зможу оцінити ситуацію та розробити остаточне рішення по Аруґалу. Тепер повертайся до свого завдання та вбивай ненажер Місяцесказу й темнодухів Місяцесказу, поки не здобудеш те, що мені потрібно.", [5] = "Сподіваюсь, я зможу одержати достатньо енергії з такої обмеженої кількості матеріалу. Можливо, мені слід було доручити тобі зібрати більше кайданів.\n\nОднак, ти чудово себе {стать:проявив:проявила}, збираючи їх, {клас:к}.", ["en"] = "Arugal's Folly", ["tasks"] = { ["Darksoul Shackle"] = "кайдани темнодуха", ["Darksoul Shackle (Provided)"] = "кайдани темнодуха (видано)", ["Glutton Shackle"] = "кайдани ненажери", ["Glutton Shackle (Provided)"] = "кайдани ненажери (видано)" } },
    [424] = { [1] = "Дурість Аруґала", [2] = "Розкриття темних секретів, що стоять за чарами, які використав Аруґал, насправді займе більше часу, ніж я думав.\n\nАле тим часом тобі потрібно буде попіклуватися про невелику проблему, з якою зіткнулися наші темнолови. Схоже, що магія Аруґала поширилася на шахту Глибинний Елем, що в пагорбах на південному сході.\n\nШахта стала б досить цінним ресурсом для наступу Варіматраса.\n\nЯ хочу, щоб ти {стать:обезголовив:обезголовила} спаплюженого десятника шахти, Ґрімсона Блідого. Після його смерті шахта стане нашою.", [3] = "Убийте Ґрімсона Блідого та принесіть його голову Даларові Ранньоткачу в Крипту.", [4] = "Ти вже {стать:вбив:вбила} Ґрімсона Блідого? Варіматрасу не сподобається, якщо ми проігноруємо його накази.", [5] = "Чудово. Шахта забезпечить наші сили відмінними ресурсами для нашого просування у Срібнохвойному пралісі та вглиб Азероту.", ["en"] = "Arugal's Folly", ["tasks"] = { ["Head of Grimson"] = "голова Ґрімсона", ["Head of Grimson (Provided)"] = "голова Ґрімсона (видано)" } },
    [425] = { [1] = "Айвар Нечистий", [2] = "Нам з братом Квінном доручили провести розвідку Срібнохвойного пралісу та відзвітувати верховному карателю Гадрекові. Але ми не зайшли далеко: коли проходили через цю ферму, на нас напав гуль Айвар Нечистий.\n\nМи втекли від Айвара, але він серйозно поранив Квінна. Він зцілюється зіллям, що ти йому {стать:дав:дала}, але Айвар може повернутися, перш ніж Квінн одужає.\n\nУбий Айвара, щоб у Квінна був час на зцілення. Айвар зазвичай сидить у тому сараї, чекаючи, коли я втрачу пильність.", [3] = "Убийте Айвара Нечистого та принесіть голову Айвара до Рейни Йорік на ділянку Айвара.", [4] = "Ти {стать:вбив:вбила} Айвара Нечистого? Якщо ти не зробиш цього для мене та мого брата, тоді зроби це заради відречених.", [5] = "Ох, дякую. Я дуже вдячний тобі, {ім'я}.\n\nІ я включу твій внесок до звіту, який направлю своєму керівництву.", ["en"] = "Ivar the Foul", ["tasks"] = { ["Ivar's Head"] = "голова Айвара", ["Ivar's Head (Provided)"] = "голова Айвара (видано)" } },
    [426] = { [1] = "Захоплені млини", [2] = "Скара намагається створити базу на млинах Аґамандів. Якщо їм це вдасться, вони зможуть втілювати подальші атаки на Тірісфаль.\n\nНаказ відданий: Скару на млинах потрібно знищити.\n\nВирушай до Млинів. Збери там надщерблені ребра з брязкокісткових солдатів і солдатів з тріснутими черепами, а також почорнілі черепи з темнооких заклиначів кісток.\n\nЩоб туди дістатися, йди дорогою на захід. Як перейдеш міст, зверни на північ на наступному роздоріжжі, туди ж і прямуй. Битва почнеться, коли побачиш млини.", [3] = "Зберіть 5 надщерблених ребер і 3 почорнілі черепи та повертайтеся до смертестража Діллінджера у Брілль.", [4] = "Наші битви зі Скарою тривають, {Ім'я}. Зроби свій внесок і відкинь цих проклятих, бездумних мерців назад до Зачумлених земель!", [5] = "Ми відчуваємо твої зусилля у цій війні, {Ім'я}. Я не подякую тобі за те, що ти робиш необхідне, але смертестражі Тірісфалю пам'ятатимуть твоє ім'я.", ["en"] = "The Mills Overrun", ["tasks"] = { ["Blackened Skull"] = "почорнілий череп", ["Blackened Skull (Provided)"] = "почорнілий череп (видано)", ["Notched Rib"] = "надщерблене ребро", ["Notched Rib (Provided)"] = "надщерблене ребро (видано)" } },
    [427] = { [1] = "Війна з Багряним Походом", [2] = "Документи карателя Аррена надала нам саме той прорив, який був потрібен у нашій битві проти клятого Багряного Походу. Тепер ми знаємо їхні точні позиції по Тірісфальському переліссю.\n\nПроте Смертестража має більші турботи. Армія Короля-ліча зростає щоночі. Нам {стать:потрібен хтось такий \"ініціативний\":потрібна хтось така \"ініціативна\"}, як ти, щоб звести Багряний Похід в їхню могилу.\n\nДоведи, що ти {стать:здатен:здатна} служити Темній Леді: вирушай до вежі на заході, повз хутір Солліденів, і вбий 10 воїнів Багряного Походу.", [3] = "Каратель Зиґанд з Брілля хоче, щоб ви убили 10 воїнів Багряного Походу.", [4] = "Якщо ти хочеш довести свою користь Темній Леді, вбий 10 воїнів Багряного Походу, {клас:к}.", [5] = "Просто чудово, {клас:к}. Твої бойові навички беззаперечні.", ["en"] = "At War With The Scarlet Crusade", ["tasks"] = { ["Scarlet Warrior"] = "воїн Багряного Походу", ["Scarlet Warrior slain"] = "воїн Багряного Походу: убито" } },
    [428] = { [1] = "Зниклі смертолови", [2] = "Кілька тижнів тому двоє з наших смертоловів, Рейна та Квінн Йоріки, були відправлені на розвідувальну місію по півночі Срібнохвою. З того часу ми від них нічого не чули.\n\nМожливо, вони стали жертвою Скари, і, якщо це правда, то мені потрібно підтвердження. Знайди цих смертоловів.\n\nЇхньою першою ціллю було розвідати ферми у північному Срібнохвої. Тобі варто почати свої пошуки там.", [3] = "Знайдіть смертоловів Квінна та Рейну Йоріків.", [5] = "Ти {стать:знайшов:знайшла} нас! Ще мить — і було б вже пізно...", ["en"] = "Lost Deathstalkers" },
    [429] = { [1] = "Дикі серця", [2] = "Мій брат Квінн був сильно поранений гулем, Айваром Нечистим, і я не знаю, чи зможе він вилікуватися без допомоги магії. Хоча я й не аптекар, я знаю, що вони у нас уміють робити цілющі зілля зі знебарвлених сердець воргів.\n\nЗбери такі серця та принеси їх аптекареві Ренферрелу в Крипту на півдні. Потім повертайся сюди з зіллям.\n\nТи зможеш знайти багато воргів дорогою до саду Мальдена, що на сході.", [3] = "Зберіть 6 знебарвлених сердець воргів і принесіть їх до аптекаря Ренферрела у Крипту.", [4] = "Я не маю часу, {клас:к}. Темна Леді доручила мені надважливе завдання.", [5] = "<Ренферрел бере серця.>\n\nМені тривожно чути, що наші смертолови провалили своє завдання.\n\nБудемо сподіватися, що такі невдачі будуть нечастими.\n\nЯ дам тобі зілля за мить, але ось його рецепт: якщо ці смертолови потребуватимуть допомоги у майбутньому, то, можливо, ти зможеш надати її самостійно.", ["en"] = "Wild Hearts", ["tasks"] = { ["Discolored Worg Heart"] = "знебарвлене серце ворга", ["Discolored Worg Heart (Provided)"] = "знебарвлене серце ворга (видано)" } },
    [430] = { [1] = "Повернення до Квінна", [2] = "Ось зілля, що допоможе Квіннові Йоріку одужати.\n\nТепер, якщо ти мені вибачиш, у мене є дуже важливі справи...", [3] = "Принесіть Квіннове зілля Квіннові Йоріку на ділянку Айвара на північ від Крипти.", [4] = "Моя сестра сказала мені, що ти тут, щоб допомогти нам. Це правда?", [5] = "<Квінн бере зілля та випиває його.>\n\nТак, я відчуваю, що воно працює. Скоро я зможу подорожувати.\n\nТи {стать:зробив:зробила} мені велику послугу, {ім'я}.", ["en"] = "Return to Quinn", ["tasks"] = { ["Quinn's Potion"] = "Квіннове зілля", ["Quinn's Potion (Provided)"] = "Квіннове зілля (видано)" } },
    [431] = { [1] = "Свічки поклику", [5] = "Ви хапаєте одну зі свічок і кладете її собі в сумку.", ["en"] = "Candles of Beckoning" },
    [435] = { [1] = "Супроводжуючи Ерланда", [2] = "Вовки ззовні ніяк не підуть, і вони злісно на мене дивляться щоразу, коли я виходжу за двері. Вони, мабуть, неймовірно голодні, якщо думають, що я вартий того, щоб мене з'їсти.\n\nМені потрібно відзвідувати моїй напарниці, смертоловці Рейні Йорік. А щоб дістатися до Рейни, мені знадобиться допомога проти цих вовків.\n\nБудь ласка, супроводь мене! Назовні багато вовків, тому наші шанси зростуть, якщо в тебе є друзі, які зможуть допомогти...", [3] = "Проведіть Ерланда через вовків до Рейни Йорік.", [4] = "Будь ласка, будь {стать:лаконічним:лаконічною}. Навколо дуже небезпечно, і ми не можемо стояти без діла в розмові.", [5] = "Дякую за допомогу, {ім'я}. Я побоювалася, що Ерланда настигли небезпеки Срібнохвою. Але бачу, що ні, завдяки тобі.", ["en"] = "Escorting Erland", ["tasks"] = { ["Erland must reach Rane Yorick"] = "Ерланд має дістатися Рейни Йорік" } },
    [437] = { [1] = "Мертві поля", [2] = "Наші початкові звіти з розвідки Срібнохвою говорять, що Гнилошкурі мають базу на старій фермі на північ звідси — Мертвих полях. Ми направляли проти них невеликі загони, але кожного разу їм на допомогу приходить банші Нічнохльостка, яка використовує свою магію, щоб розгромити наші сили.\n\nМи хочемо, щоб Нічнохльостка була знищена.\n\nЙди до Мертвих полів та напади на Гнилошкурих. Якщо не побачиш Нічнохльостку, вбивай Гнилошкурих доти, доки вона не з'явиться, а потім знищ її.\n\nЇї сутність обернеться в пил. Принеси мені цей пил як доказ.", [3] = "Убивайте Гнилошкурих гнолів на Мертвих полях.\n\nКоли з'явиться Нічнохльостка, вбийте її.\n\nПринесіть сутність Нічнохльостки до верховного карателя Гадрека у Крипту.", [4] = "Ти вже {стать:переміг:перемогла} Нічнохльостку, {ім'я}? Від її знищення залежить наш успіх у боротьбі проти Гнилошкурих!", [5] = "Я чув, що твій напад на Гнилошкурих був вельми успішним, {ім'я}, і ця сутність є доказом смерті Нічнохльостки.\n\nСкара програла сьогодні. Твоя цінність для відречених зростає.", ["en"] = "The Dead Fields", ["tasks"] = { ["Essence of Nightlash"] = "сутність Нічнохльостки", ["Essence of Nightlash (Provided)"] = "сутність Нічнохльостки (видано)" } },
    [438] = { [1] = "Трухлявий пором", [2] = "{ім'я}, ми виявили нове гніздо Скари: Трухлявий пором. Пором розташований на сході від Крипти, і його ретельно патрулюють Гнилошкурі й інші невмерлі.\n\nДля захоплення цього району Скарою має бути причина. Йди до Трухлявого порома та з'ясуй, чому Скара там.", [3] = "Вирушайте до Трухлявого порома.\n\nЗнайдіть причину присутності там Скари.", [5] = "У цьому човні накидали купу загорнутих трупів. І, дивлячися на схід через Лордамерське озеро, навпроти можна побачити пристань на острові Фенріса.\n\nДоля трупів напевне пов'язана з ним.", ["en"] = "The Decrepit Ferry" },
    [439] = { [1] = "Докази на Гнилошкурих", [2] = "З купи трупів стирчить оголена рука. Це — рука жінки, вкрита плямами від чуми, але відносно свіжа.\n\nНа руці є перстень. Знявши його й оглянувши, можна побачити гравіювання:\n\n\"Для Деліі\"", [3] = "Принесіть перстень Делії верховному карателю Гадреку в Крипту.", [4] = "{ім'я}. Ти {стать:повернувся:повернулася}, тож я припускаю, що твоє розслідування принесло плоди?", [5] = "Ти кажеш, що цей перстень носила жінка, яку нещодавно вбили?\n\nЄдиним джерелом поблизу для такого тіла можуть бути тільки масові поховання в Тірісфалі. Гнилошкурі гноли, певно, забирають ті трупи на острів Фенріса!", ["en"] = "Rot Hide Clues", ["tasks"] = { ["Deliah's Ring"] = "перстень Делії", ["Deliah's Ring (Provided)"] = "перстень Делії (видано)" } },
    [440] = { [1] = "Гравійований перстень", [2] = "Якщо ти хочеш знайти чоловіка або коханого, що дав Делії її перстень... то поговори з війтом Севреном у Бріллі. Він повинен мати записи про недавні смерті та, якщо пощастить, зможе виявити, ким була Делія.\n\nАле я б не сподівався. Той, хто дав їй це кільце, мабуть, вже вмер. Або, якщо він невмерлий, то, ймовірно, більше не турбується про Делію.", [3] = "Принесіть перстень Делії війтові Севрену до Брілля.", [4] = "Привіт, {ім'я}. Що привело тебе назад до Брілля?", [5] = "У Бріллі справді жила Делія не так давно. Її поховали у спільній могилі, але, якщо те, що ти кажеш — правда, тоді Гнилошкурі гноли, скоріш за все, викрали її тіло та віднесли його до Срібнохвою.\n\nГнилошкурі, як і вся інша Скара, повинні бути знищені. Я вірю, що ти вживаєш заходів, щоб це сталося.", ["en"] = "The Engraved Ring", ["tasks"] = { ["Deliah's Ring"] = "перстень Делії", ["Deliah's Ring (Provided)"] = "перстень Делії (видано)" } },
    [4402] = { [1] = "Ґалґаровий пиріг з кактусовими яблуками", [2] = "А тут в долині Випробувань стає справді гаряче.\n\n<Ґалґар витирає чоло.>\n\nЯкби ж у мене було декілька кактусових яблук, я міг би приготувати мій славнозвісний десерт! Ніщо не охолоджує швидше, ніж шматочок цього чарівного смаколика.\n\nЯ ось що тобі скажу, {Ім'я}. Якщо принесеш мені 10 кактусових яблук, я приготую декілька порцій пирога, які ти зможеш взяти з собою у мандри. Якщо {стать:зацікавився:зацікавилась} - ці яблука ростуть поруч із кактусами.", [3] = "Принесіть Ґалґару 10 кактусових яблук. Ви пригадуєте, як він казав, що їх можна знайти біля кактусів.", [4] = "Ти {стать:закінчив:закінчила} збирати кактусові яблука?", [5] = "Чудово, {Ім'я}! Як обіцяв, ось твій пиріг з кактусовими яблуками, плюс дещо зверху.", ["en"] = "Galgar's Cactus Apple Surprise", ["tasks"] = { ["Cactus Apple"] = "кактусове яблуко", ["Cactus Apple (Provided)"] = "кактусове яблуко (видано)" } },
    [441] = { [1] = "Ралей та Підмістя", [2] = "У Деліі був чоловік, Ралей, котрий зараз мешкає в Підмісті. Якщо перстень справді належав Делії, що жила в Бріллі, то Ралей його впізнає.\n\nТи знайдеш його в Торговому кварталі Підмістя.", [3] = "Принесіть Ралею перстень Делії.", [4] = "Я тебе знаю?", [5] = "Так, цей перстень належав моїй дружині. Її настигла така ж доля, як і всіх, хто не зміг пережити ці суворі часи. Я нічого не відчуваю ні з приводу її смерті, ні з цієї історії про викрадення її тіла, що ти розповідаєш.\n\nТакі почуття вже давно охололи в мені. Проте жага досі горить у моєму мертвому серці, {ім'я}.\n\nЖага помсти.", ["en"] = "Raleigh and the Undercity", ["tasks"] = { ["Deliah's Ring"] = "перстень Делії", ["Deliah's Ring (Provided)"] = "перстень Делії (видано)" } },
    [442] = { [1] = "Штурм острова Фенріса", [2] = "Тепер настав час напасти на твердиню Скари в Срібнохвойному пралісі: острів Фенріса.\n\nТобі потрібно знову вирушити на острів і знищити Тула Воронокігтя. Мені потрібна його голова!\n\nЦя місія настільки ж небезпечна, наскільки й важлива, {ім'я}. Ти не можеш зазнати невдачі.", [3] = "Принесіть голову Тула верховному карателю Гадреку в Крипту.", [4] = "Ми не вожемо дозволити Скарі зоставатися в Срібнохвої, {ім'я}. Повертайся до мене, коли будеш мати доказ смерті Тула.", [5] = "Смерть Тула Воронокігтя - значуща подія, {ім'я}. Ренферрел сказав мені, що енергію, яка вивільнилася, коли ти його {стать:знищив:знищила}, було відчутно аж у Крипті.\n\nТвої дії справили враження в рядах відречених. Твоя цінність для нас зростає.", ["en"] = "Assault on Fenris Isle", ["tasks"] = { ["Thule's Head"] = "голова Тула", ["Thule's Head (Provided)"] = "голова Тула (видано)" } },
    [443] = { [1] = "Пасока Гнилошкурих", [2] = "Перш ніж ми почнемо штурм острова Фенріса, ми маємо з'ясувати, хто стоїть за Гнилошкурими гнолами. Наші аптекарі вважають, що їхнє виникнення пов'язане з незвичайною рідиною, яка тече в їхніх тілах.\n\nЙди до острова Фенріса, що на сході від Трухлявого порома, та збери пасоку Гнилошкурих із гнолів, яких знайдеш там. Принеси її до аптекаря Ренферрела, який перебуває біля Крипти.", [3] = "Принесіть 8 пляшок пасоки Гнилошкурих до аптекаря Ренферрела у Крипту.", [4] = "У тебе є вже пасока Гнилошкурих, {Ім'я}?", [5] = "Дуже добре. Ця пасока допоможе нам зрозуміти природу Гнилошкурих і, можливо, відкриє нам, у чому їхня слабкість...\n\n...якщо вона в них є.", ["en"] = "Rot Hide Ichor", ["tasks"] = { ["Rot Hide Ichor"] = "пасока Гнилошкурих", ["Rot Hide Ichor (Provided)"] = "пасока Гнилошкурих (видано)" } },
    [444] = { [1] = "Походження Гнилошкурих", [2] = "Я очистив пасоку, яку ти мені {стать:приніс:принесла}, і розділив його на базові компоненти. Мої результати неоднозначні, але я визначив, що у створенні цієї рідини використали чорнокнижну та некромантську магії.\n\nПоки я продовжую вивчати пасоку, я хочу, щоб ти {стать:доставив:доставила} зразок Беторові Кригозламу в Підмістя. Бетор не аптекар, але його знання магії може допомогти нам розгадати таємницю Гнилошкурих.\n\nІди. Ти знайдеш Бетора у кварталі Магії Підмістя.", [3] = "Принесіть зразок пасоки Беторові Кригозламу в Підмістя.", [4] = "Мої дослідження потребують великої концентрації. Тож я сподіваюся, що твій візит — не просто примха.", [5] = "Ця речовина пронизана потужними заклинаннями, деякі з яких я не бачив протягом дуже, дуже довгого часу...\n\nХвилинку, я маю застосувати закляття провидіння...", ["en"] = "Rot Hide Origins", ["tasks"] = { ["Sample Ichor"] = "зразок пасоки", ["Sample Ichor (Provided)"] = "зразок пасоки (видано)" } },
    [445] = { [1] = "Доставка в Срібнохвойний праліс", [2] = "Час - це розкіш, яку не можуть собі дозволити ті, хто під прямим командуванням леді Сильвани. Ти, звісно, про це вже знаєш.\n\nЯк член Королівського товариства аптекарів, я зобов'язаний ділитися своїми знаннями з колегами, щоб наші спільні зусилля одного дня забезпечили Темну Леді новою чумою, яку вона так сильно бажає.\n\nВіднеси ці дослідження до аптекаря Ренферрела, який зараз знаходиться в Крипті у Срібнохвойному пралісі. Йди вздовж дороги на південь від Брілля, а біля Підмістя поверни на південний захід.", [3] = "Візьміть дослідження аптекаря Йогаана та принесіть їх аптекареві Ренферрелу у Срібнохвойний праліс.", [4] = "Яка в тебе справа до мене, {клас:к}?", [5] = "О, як добре, що аптекар Йогаан надіслав мені свої дослідження. З усіма цими справами у Срібнохвої, я майже забув про знахідки з Лордерону та Тірісфальського перелісся. Це нагадало мені, що я незабаром повинен надіслати зразки до Некрополя.\n\nАле пробач мені за мою балаканину. Залишайся у Срібнохвої, {Ім'я}. Нам би тут {стать:згодився такий вправний:згодилася така вправна} {клас:н}, як ти.", ["en"] = "Delivery to Silverpine Forest", ["tasks"] = { ["Johaan's Findings"] = "дослідження Йогаана", ["Johaan's Findings (Provided)"] = "дослідження Йогаана (видано)" } },
    [446] = { [1] = "Тул Воронокіготь", [2] = "Цю пасоку створив мій давній колега - Тул Воронокіготь. Він був молодим, перспективним магом до великої війни. Але коли Король-ліч досяг могутності, він зрадив своїх побратимів і ввійшов у союз зі Скарою.\n\nЯ не усвідомлював, що він досі живий, а тим паче — що він очолює набіги Гнилошкурих на нас!\n\nЯ знаю багато його заклять і це може допомогти зварити проти них зілля. Віднеси цей сувій до аптекаря Ренферрела. У ньому написані заклинання, необхідні для варива.", [3] = "Принесіть сувій Бетора аптекареві Ренферрелу до Крипти Срібнохвою.", [4] = "Вітання тобі, {Ім'я}. Що розповів тобі Бетор?", [5] = "Цей сувій пронизаний потужною магією. Я ніколи не використовував такі сили для зілля... це буде потужна суміш, і вона повинна добре тобі послужити, якщо ти вирішиш атакувати Тула в його фортеці на острові Фенріса.", ["en"] = "Thule Ravenclaw", ["tasks"] = { ["Bethor's Scroll"] = "сувій Бетора", ["Bethor's Scroll (Provided)"] = "сувій Бетора (видано)" } },
    [447] = { [1] = "Рецепт смерті", [2] = "Сили Артаса незчисленні, але з Новою Чумою ми зможемо раз і назавжди покінчити як з армією Скари, так і з людьми.\n\nМої дослідження довели, що павуча кров у поєднанні з токсином, отриманим з серця посивілого ведмедя, перетворюється на смертельний еліксир. Збери зразки з павуків із Дріботливої Темряви на північному заході та з ведмедів, що блукають по всьому Срібнохвойному пралісу. Достав реагенти майстру-аптекареві Фаранеллу з Королівського товариства аптекарів в Підмістя.", [3] = "Зберіть 6 сердець посивілих ведмедів і 6 зразків дріботливої крові та доставте їх майстрові-аптекарю Фаранеллу в Підмістя.", [4] = "Вітаю тебе, {клас:к}. Яку справу ти маєш до Королівського товариства аптекарів?", [5] = "Як правильно зробив аптекар Ренферрел, що прислав тебе до мене, {ім'я}. Ці зразки дійсно стануть корисними для нашої справи. Я негайно почну вивчати їхні токсичні та забруднювальні властивості.", ["en"] = "A Recipe For Death", ["tasks"] = { ["Grizzled Bear Heart"] = "серце посивілого ведмедя", ["Grizzled Bear Heart (Provided)"] = "серце посивілого ведмедя (видано)", ["Skittering Blood"] = "дріботлива кров", ["Skittering Blood (Provided)"] = "дріботлива кров (видано)" } },
    [448] = { [1] = "Доповідь Гадрекові", [2] = "Перед тим, як ти почнеш атаку на острів Фенріса, відзвітуй верховному карателю Гадрекові. Він може надати додаткову інформацію чи спорядження, що може тобі знадобитись.", [3] = "Відзвітуйте верховному карателю Гадрекові у Крипті.", [5] = "Якщо те, що говорить Бетор, правда, то Тул Воронокіготь - це сила, з якою потрібно розібратися, і розібратися скоро.\n\nДля цього завдання ти можеш узяти щось з нашого арсеналу...", ["en"] = "Report to Hadrec" },
    [449] = { [1] = "Звіт смертоловів", [2] = "Хоча рани Квінна ще загоюються, я хочу якомога швидше доставити наш звіт до верховного карателя Гадрека. Він містить інформацію, яка є життєво важливою для захоплення Срібнохвою відреченими.", [3] = "Віднесіть звіт смертоловів до верховного карателя Гадрека у Крипту.", [4] = "Ти {стать:дізнався:дізналася} про долю смертоловів?", [5] = "Я не розраховував ні на такий рівень присутності Скари, що ми бачимо в Срібнохвойному пралісі, ні на неприємності, з якими наші смертолови зіткнулися у процесі розвідувальної діяльності.\n\nТвоя допомога нашим смертоловам була неоціненною, {ім'я}. І тебе буде нагороджено.", ["en"] = "The Deathstalkers' Report", ["tasks"] = { ["Deathstalker Report"] = "звіт смертоловів", ["Deathstalker Report (Provided)"] = "звіт смертоловів (видано)" } },
    [4494] = { [1] = "Нашестя силітидів", [2] = "Схоже, що мета силітидів, а точніше — сенс їхнього існування — поглинати на своєму шляху все, що відрізняється від них. Вони дуже зосереджено займаються цим, тому й становлять серйозну загрозу всьому живому на Азероті.\n\nВсе, що ми бачили дотепер — лише перші кроки. Я підозрюю, що їхня сила походить з глибин Калімдору — кратеру Ун'Ґоро. Вирушай до Пристробляху в пустелю Танаріс і поговори з алхіміком Товкачером. Розкажи йому про мою теорію. Він неодмінно допоможе нам у боротьбі з силітидами.", [3] = "Поговоріть з алхіміком Товкачером у Пристроблясі.", [5] = "Так, я зрозумів, що тебе прислав до мене Зілзібін. Твій досвід у боротьбі з цими чудовиськами неоціненний. Я ще не чув ні про кого, хто мав справу з ними. Щодо ідеї Зілзібіна про їх походження з кратера Ун'Ґоро... можливо, так воно і є. Ун'Ґоро — це таємничі й небезпечні джунглі на захід звідси. Можливо, там ми й знайдемо пояснення природи силітидів.", ["en"] = "March of the Silithid" },
    [450] = { [1] = "Рецепт смерті", [2] = "Ти можеш ще послужити Королівському товариству аптекарів, {ім'я}.\n\nКоли Аруґал навів свою мерзенну магію на ліс, він прокляв одного з наших найбільш перспективних членів, аптекаря Берарда. Нині бездумний слуга Аруґала, нам Берард нічим не корисний. Проте його дослідження можуть виявитися вартісними. Він вивчав стародавню чуму, що вбила все живе в озері Лордамер віки тому.\n\nЗабери щоденник Берарда з його кабінету в таверні Поховальних Вогнищ та віднеси його до аптекаря Ренферрела.", [3] = "Знайдіть щоденник аптекаря Берарда в селі Поховальні Вогнища та віднесіть його до аптекаря Ренферрела в Крипту.", [4] = "Бачу, ти {стать:повернувся:повернулася}, {ім'я}.", [5] = "Щоденник аптекаря Берарда! А ти досить {стать:хоробрий:хоробра}, {ім'я}. Тепер подивімося, чим займався Берард до того, як збожеволів...", ["en"] = "A Recipe For Death", ["tasks"] = { ["Berard's Journal"] = "щоденник Берарда", ["Berard's Journal (Provided)"] = "щоденник Берарда (видано)" } },
    [4505] = { [1] = "Осквернений колодязь", [2] = "Дехто може сказати, що я надзвичайно жорстока... Але насправді, я лиш жадаю здобути для Орди перевагу над Альянсом у будь-який спосіб.\n\nЗараз мене цікавить місячний колодязь в руїнах Сузірви, на південь звідси. Його охороняють нефритожарі сатири. Місячний колодязь, колись символ оновлення для цих нестерпних нічних ельфів, зараз осквернений, і породжує дедалі більше сатирів.\n\nУ мене є ідея, {ім'я}, і мені потрібен зразок води звідти... для цієї маленької кішечки.", [3] = "Візьміть зразок оскверненої води з місячного колодязя нефритожарих сатирів і принесіть його Вінні Гроззі на Кровотруйну заставу.", [4] = "Це надзвичайно важливо. Іди вже.", [5] = "Дуже добре. Треба знайти спосіб використати цю скверну проти наших ворогів...", ["en"] = "Well of Corruption", ["tasks"] = { ["Filled Flasket"] = "наповнена колба", ["Filled Flasket (Provided)"] = "наповнена колба (видано)" } },
    [4506] = { [1] = "Осквернені шаблезуби", [2] = "Ця осквернена вода може стати нам у пригоді, {ім'я}. Від однієї лиш краплі води моє кошеня виросло вдвічі та, здається, стало сильнішим... в дечому. Ці коти можуть виявитися корисними...\n\nОсь, {ім'я}, візьми цю переноску і випусти кошеня поруч із місячним колодязем у руїнах Сузірви. Ха-ха... Я впевнена, що ти будеш {стать:задоволений:задоволена} результатами!\n\nПоверни мені кішку, і я щось запропоную тобі в замін.", [3] = "Віднесіть кошеня Вінни до оскверненого місячного колодязя, відпустіть його, а потім поверніть до Вінни.\n\nПовернувшись до Вінни, клацніть на кошеня, щоб відпустити його.", [4] = "Не кажи мені, що ти не можеш туди повернутися! Давай вже, йди!", [5] = "Чудово!\n\nВідречені вдадуться до будь-яких засобів, щоб знищити Альянс! Використання оскверненої води, безсумнівно, дуже допоможе нам у майбутньому...", ["en"] = "Corrupted Sabers", ["tasks"] = { ["Return the corrupted cat to Winna Hazzard"] = "Поверніть зіпсованого кота Вінні Хаззард" } },
    [4509] = { [1] = "Затишшя перед бурею", [2] = "Мої останні відкриття та знання, які ми отримали сьогодні, мають потрапити в руки тих, хто може з цим щось зробити. Попри те, як багато ресурсів ми маємо в Пристроблях, ми не можемо зробити цього самі.\n\nПередай мій останній звіт Зілзібіну Ударнику в Орґріммар; він все ще має бути у верхній частині Тракту, чи не так? У нього є друзі, які є великими шишками Орди; якщо ми зможемо залучити їх до цієї справи, {ім'я}, то, можливо, ми виберемося звідси живими.", [3] = "Принесіть звіт Товкачера по ситуації в Ун'Ґоро до Зілзібіна Ударника в Орґріммар.", [4] = "Вони дурні, {ім'я}! Вони навіть не можуть подумати про більшу загрозу, що оточує їх. Їхня ірраціональна ненависть до Альянсу стане для нас усіх кінцем. Я не знаю, як ще можна довести їм реальність загрози силітидів, окрім як запхнути їх в одне з гнізд, щоб вони могли побачити все на власні очі!\n\nТи {стать:приніс:принесла} якісь новини для мене?", [5] = "Хоча я дуже вдячний тобі, я не впевнений, чи з цього щось вийде. Орда ігнорує будь-які загрози, окрім Альянсу. Тралл неодмінно вжив би заходів, якби йому представили всі факти, але він з усіх боків оточений безглуздими порадами. Вони готові ганятися за власним хвостом, сподіваючись застати Альянс зненацька!\n\nТи {стать:бачив:бачила} загрозу на власні очі, {ім'я}. Ми повинні здолати силітидів!", ["en"] = "Calm Before the Storm", ["tasks"] = { ["Pestlezugg's Un'Goro Report"] = "звіт Товкачера по ситуації в Ун'Ґоро", ["Pestlezugg's Un'Goro Report (Provided)"] = "звіт Товкачера по ситуації в Ун'Ґоро (видано)" } },
    [451] = { [1] = "Рецепт смерті", [2] = "Згідно з записами в щоденнику Берарда, мох озерного тайноходця та озерного підкрадача може виявитися корисним для нашої задачі з виведення нової чуми. Ці істоти мешкають на островах озера Лордамер на сході.\n\nВін також згадує про дуже рідкісну затверділу пухлину, яку він знайшов на мурлоку з племені Злобного Плавника. Певно, пухлина настільки рідкісна, що Берарду вдалося добути лише одну.\n\nЗбери зразки моху, а також рідкісну затверділу пухлину, та віднеси їх майстрові-аптекарю Фаранеллу в Підмістя.", [3] = "Принесіть 6 зразків моху озерного підкрадача, 6 зразків моху озерного тайноходця та затверділу пухлину до майстра-аптекаря Фаранелла в Підмістя.", [4] = "Що привело тебе назад в Підмістя, {ім'я}?", [5] = "Втрата Берарда - то важкий удар для Королівського товариства аптекарів. Але завдяки твоїй важкій праці та старанним дослідженням аптекаря Ренферрела вчення Бернара все ще будуть корисними у справах Темної Леді.\n\nМи зараз на порозі чогось насправді величного, {ім'я}. Якби ти не {стать:був таким умілим:була такою вмілою} у мистецтві бою, я б спробував завербувати тебе в Товариство.", ["en"] = "A Recipe For Death", ["tasks"] = { ["Hardened Tumor"] = "затверділа пухлина", ["Hardened Tumor (Provided)"] = "затверділа пухлина (видано)", ["Lake Creeper Moss"] = "мох озерного підкрадача", ["Lake Creeper Moss (Provided)"] = "мох озерного підкрадача (видано)", ["Lake Skulker Moss"] = "мох озерного тайноходця", ["Lake Skulker Moss (Provided)"] = "мох озерного тайноходця (видано)" } },
    [452] = { [1] = "Засада в Поховальних Вогнищах", [2] = "Ти дуже вчасно {стать:добрався:добралася} до нас, {ім'я}!\n\nРада Поховальних Вогнищ повернеться будь-якої миті. Аруґал має інші справи, що затримують його у фортеці. Він використовує раду лише як маріонеток, щоб тримати безмозких посіпак Поховальних Вогнищ під своїм контролем. Проте я вважаю, що без керівництва ради сини Аруґала навернуться проти свого господаря.\n\nЯ не можу впоратися з ними всіма сама. Мені потрібна твоя допомога. Разом ми зможемо рознести раду для Леді Сильвани.", [3] = "Допоможіть смертоловці Фарлеї вбити раду Поховальних Вогнищ.", [5] = "Ти {стать:боровся, як справжній послідовник:боролася, як справжня послідовниця} Темної Леді, {ім'я}. Тепер, коли рада мертва, ймовірно, ми зможемо отримати контроль над цим містечком раз і назавжди та вигнати Аруґала з фортеці Тіньового Ікла. Віддаю тобі честь!", ["en"] = "Pyrewood Ambush", ["tasks"] = { ["Aid Faerleia in killing the Pyrewood Council"] = "Допоможіть Фарлеї вбити раду Поховальних Вогнищ" } },
    [4521] = { [1] = "Дикі захисники", [2] = "Зимоключ лежить за Деревопузими, на північний схід від Сквернолісся. Ти {стать:був:була} там?\n\nЯ чув, що в цій області повно створінь, які називаються дикими совухами. Відомо, що ці звірі охороняють таємниці нічних ельфів.\n\nМи повинні зрозуміти, що може бути сховане в Зимоключі.\n\nЯ чув, що обдертих совозвірів можна знайти на південь від дороги, але є інші, що називаються лютими совозвірами, яких можна знайти в центрі Зимоключа. Позбудься їх та розчисть дорогу.", [3] = "Трулл Чахлоклят зі Сквернолісся хоче, щоб ви вбили 15 лютих совозвірів і 15 обдертих совозвірів.", [4] = "Приходь до мене після того, як виконаєш моє завдання.", [5] = "Це чудова новина, {ім'я}. Коли ці звірі більше не стоять на нашому шляху, ми можемо продовжувати досліджувати Зимоключ. Ти {стать:готовий:готова} до більшого?", ["en"] = "Wild Guardians", ["tasks"] = { ["Ragged Owlbeast"] = "обдертий совозвір", ["Ragged Owlbeast slain"] = "обдертий совозвір: убито", ["Raging Owlbeast"] = "лютий совозвір", ["Raging Owlbeast slain"] = "лютий совозвір: убито" } },
    [4542] = { [1] = "Повідомлення для застави Розкутого Вітру", [2] = "{стать:Сміливий мандрівнику:Смілива мандрівнице}, кентаври посилили свої атаки в цій місцевості. Про це потрібно терміново доповісти на заставу Розкутого Вітру! Знайди спостерігача скель Довгорогого на заставі Розкутого Вітру на південний схід звідси та віддай йому це термінове повідомлення.\n\nПопереджаю, уникай клан Зловісного Тотема, їхнє поселення неподалік... останнім часом вони дуже дивно поводяться.", [3] = "Доставте термінове повідомлення спостерігачу скель Довгорогому на заставу Розкутого Вітру.", [4] = "Чого ти хочеш, {клас:к}? Термінове повідомлення для мене?", [5] = "Все більше поганих новин! Ці кентаври зайшли занадто далеко! Вони пограбували один із моїх караванів з постачаннями та вирізали всіх, хто там був. Це просто жах, вони мають бути за це покарані!", ["en"] = "Message to Freewind Post", ["tasks"] = { ["Urgent Message"] = "термінове повідомлення", ["Urgent Message (Provided)"] = "термінове повідомлення (видано)" } },
    [461] = { [1] = "Прихована ніша", [2] = "Мені відомо про приховану нішу в межах фортеці, яка містить предмет, дорогий Тулові та його старим колегам. Вона також містить дещо, що може бути тобі корисним. Віднеси мене туди!\n\nАльков розташований у південно-західній вежі фортеці, позаду запилених полиць.\n\nВізьми моє тіло, але залиш чоботи. Все одно вони ніколи мені не підходили...", [3] = "Віднесіть Аларіка до замаскованого алькова.", [4] = "Це те саме місце! Піднеси мене ближче...", [5] = "Ось, ніша відкрита. Залиш мене тут. Я провів найкращі дні свого життя в цій фортеці, і думка про упокоєння в її стінах дає мені почуття комфорту.\n\nОбов'язково зачини альков щільно: я не хочу, щоб ці Гнилошкурі знайшли мене.\n\nО, і візьми це. Ти {стать:заслужив:заслужила}.", ["en"] = "The Hidden Niche", ["tasks"] = { ["Alaric's Remains"] = "останки Аларіка", ["Alaric's Remains (Provided)"] = "останки Аларіка (видано)" } },
    [4641] = { [1] = "Твоє місце у світі", [2] = "{Ім'я}, нарешті ти {стать:досяг:досягла} віку, коли можна почати боротьбу в ім'я Орди та завоювання во славу воєвождя.\n\nТак…\n\n<Калтунк оглядає вас.>\n\nТи впораєшся.\n\nБез сумніву, ти мрієш одразу знайти могутнього дракона чи демона, а потім власноруч його придушити, але зараз, можливо, було б розумніше почати з дечого менш… небезпечного.\n\n<Калтунк сміється.>\n\nВідрапортуй Ґорнеку, він зможе дати тобі підходяще завдання, {стать:молодий:молода} {клас:к}. Ти знайдеш його у Лігві, на заході.", [3] = "Поговоріть з Ґорнеком. Ви згадуєте про позначку, яку поставив Калтунк на карті з його місцезнаходженням. Ґорнек знаходиться у Лігві, будівлі, що стоїть на заході.", [5] = "Ще один Калтунків рекрут, еге ж?\n\nСхоже, настали скрутні часи, якщо ти - це найкраще, що може направити мені на службу Орда. Нічого. Перш ніж ти покинеш долину, я зроблю з тебе {стать:гордого:горду} {клас:з} Орди.", ["en"] = "Your Place In The World" },
    [4721] = { [1] = "Дикі захисники", [2] = "Гінці повернулись з Зимоключа з повідомленнями про низку невеликих печер в південній частині Зимоключа. Здається, що в них також мешкають дикі совухи. Якщо вони охороняють щось цінне, то, гадаю, саме там ми це і знайдемо.\n\nЗ цими дикими совухами тобі буде набагато складніше впоратися, ніж з попередніми, {ім'я}. Ці істоти, здається, збожеволіли від контакту з тим, що вони намагаються захистити.", [3] = "Трулл Чахлоклят зі Сквернолісся хоче, щоб ви вбили 10 совозвірів-берсерків в Зимоключі.", [4] = "Ти знаєш, що робити, {ім'я}.", [5] = "Важка праця — це те, що я поважаю, {ім'я}. Тепер ми можемо рухатися далі з нашими планами в Зимоключі.", ["en"] = "Wild Guardians", ["tasks"] = { ["Berserk Owlbeast"] = "совозвір-берсерк", ["Berserk Owlbeast slain"] = "совозвір-берсерк: убито" } },
    [4741] = { [1] = "Дикі захисники", [2] = "У північних районах Зимоключа дикі совухи ще більш жорстокі. І саме туди ти й відправишся.\n\nВирушай на полювання на осяяних місяцем совозвірів в Зимоключ, а заразом досліди місцевість, де вони мешкають.\n\nМісця там дикі, але я знаю, що ти впораєшся. Повертайся до мене, як вб'єш 13 осяяних місяцем совозвірів.", [3] = "Трулл Чахлоклят зі Сквернолісся хоче, щоб ви вбили 13 осяяних місяцем совозвірів.", [4] = "Тільки не кажи, що тобі страшно! Вперед!", [5] = "Я відчуваю, що ти отримуєш задоволення від своєї роботи. І я вірю, що ми на правильному шляху.", ["en"] = "Wild Guardians", ["tasks"] = { ["Moontouched Owlbeast"] = "осяяний місяцем совозвір", ["Moontouched Owlbeast slain"] = "осяяний місяцем совозвір: убито" } },
    [4767] = { [1] = "Приборкувачі виверн", [2] = "Мене попросили набрати нових виверн для приборкувачів. Їх кількість постійно зростає, і я сподіваюся, що я колись сам зможу стати приборкувачем виверн. Проте, виверни мають великий попит, і нам їх постійно не вистачає. Можливо ти зможеш допомогти мені, {ім'я}?\n\nМені потрібно, щоб ти {стать:відправився:відправилася} до Високого Сідала та {стать:добув:добула} яйця виверн. Звідси йди на північний захід, вздовж стін каньйону, до підйому, що веде до Високого Сідала. Будь {стать:обережним:обережною}, виверни не люблять чужинців, а за свої кладки вони будуть готові розірвати кого завгодно.", [3] = "Принесіть 10 яєць виверн з Високого Сідала до Елу на заставу Розкутого Вітру.", [4] = "{ім'я}, ти {стать:зібрав:зібрала} для мене яйця виверн? Мені не терпиться почати тренування!", [5] = "Чудово! З цими яйцями я зможу зробити перший крок, щоб стати приборкувачем виверн. Ось, візьми це на знак моєї вдячності й нехай тобі завжди щастить на полюванні, {клас:к}.", ["en"] = "Wind Rider", ["tasks"] = { ["Highperch Wyvern Egg"] = "яйце виверни з Високого Сідала", ["Highperch Wyvern Egg (Provided)"] = "яйце виверни з Високого Сідала (видано)" } },
    [477] = { [1] = "Перетини кордону", [2] = "Як ти, мабуть, знаєш, Бурштиновий Млин залишається джерелом людського опору. В основному завдяки підтримці, яку вони отримують від чарівників Даларана.\n\nЯ не знаю, в чому суть їхнього плану, але те, що вони проявляють цікавість до такої глухомані, як Бурштиновий Млин, вказує, що воно має чимале значення.\n\nВони постачають контейнери фургоном з Гіллзбраду. Багато з цих запасів потрапляють у маленький табір на північ від Поховальних Вогнищ. Здобудь вміст однієї зі скринь і повертайся до мене.", [3] = "Здобудьте вміст однієї зі скринь даларанських чарівників. Ви знайдете село Поховальні Вогнища на півдні.", [5] = "<Відкривши кришку скрині, ви знаходите там набір ретельно запакованих предметів. Поверх них лежить зв'язка пожовклих від часу мап, на яких, схоже, зображено Срібнохвойний праліс та інші частини західного Лордерону.\n\nПід мапами лежить таємничий магічний кулон.>", ["en"] = "Border Crossings" },
    [4770] = { [1] = "Шлях додому", [2] = "Будь ласка, допоможи мені, {клас:к}. Я вже кілька днів ховаюся у Високому Сідалі, і за цей час не зустрів жодного дружнього обличчя. Я прийшов сюди щоб вивчати виверн і, схоже, занадто близько підійшов до них. Після того, як я втік від їхнього гнізда, я загубився.\n\nМені потрібно повернутися на Білосяжну заставу! Мотеґа іще не знає, що я зник, і дуже розлютиться, якщо дізнається, що я відправився у Високе Сідало один.\n\nБілосяжна застава знаходиться на схід звідси... будь ласка, проведи мене туди!", [3] = "Виведіть Пао'ку Стрімку Гору з Високого Сідала, потім поговоріть з Мотеґою Вогняною Гривою на Білосяжній заставі.", [5] = "Що?! Якби я знав, що Пао'ка полізе у Високе Сідало, я б прикував його до тотема! Його батько неохоче погодився відпустити свого сина зі мною в Тисячу Шипів. Ми прийшли сюди, щоб дослідити різних створінь, що населяють ці прекрасні землі.\n\nЯ вдячний тобі за допомогу Пао'ку. Сподіваюся, що це компенсує всі твої витрати.", ["en"] = "Homeward Bound", ["tasks"] = { ["Escort Pao'ka from Highperch"] = "Ескорт Пао'ки з Хайперча" } },
    [478] = { [1] = "Мапи та руни", [2] = "<Ви швидко витягуєте кулон зі скрині та закриваєте кришку.>", [3] = "Принесіть дивний кулон темному жерцю Аллістерові до Крипти.", [4] = "{Стать:Дізнався:Дізналася} що-небудь корисне, {ім'я}?", [5] = "Мапи та цей... кулон, гм? Цікаво.\n\nОчевидно, що чарівники Даларана чомусь цікавляться Бурштиновим Млином, але їхня мета все ще невідома.\n\nМожливо, Далар зможе з'ясувати щось про їх плани.", ["en"] = "Maps and Runes", ["tasks"] = { ["Rune-inscribed Pendant"] = "покритий рунами кулон", ["Rune-inscribed Pendant (Provided)"] = "покритий рунами кулон (видано)" } },
    [479] = { [1] = "Розслідування в Бурштиновому Млині", [2] = "Далар намагається визначити джерело сили чарівницьких заклинань. А поки що ми мусимо сповільнити їхній прогрес усіма можливими способами...\n\nЗаклинателі, маги та захисники, без сумніву, мають при собі кулони. Зніми їх і забери.\n\nТримайся головної дороги на південь і на роздоріжжі зверни на схід до Бурштинового Млина.", [3] = "Здобудьте 8 даларанських кулонів для жерця тіні Аллістера в Крипті.", [4] = "Нам потрібно поспішати. Їхні плани не повинні здійснитися, інакше ми можемо втратити свою владу в Срібнохвойному пралісі.", [5] = "Далар з'ясував, що плетіння чар зайшло досить далеко, попри затримки.\n\nМагічну енергію скеровує якийсь дуже могутній чарівник. Його потрібно негайно зупинити.", ["en"] = "Ambermill Investigations", ["tasks"] = { ["Dalaran Pendant"] = "даларанський кулон", ["Dalaran Pendant (Provided)"] = "даларанський кулон (видано)" } },
    [480] = { [1] = "Ткач", [2] = "Якийсь дуже могутній архімаг контролює процес реактивації лей-енергетичного вузла. Вони вже далеко зайшли, тож єдиний спосіб їх зупинити — вбити його. Але це буде важко: його, без сумніву, захищають багато інших магів і вартових.\n\nТобі потрібно піти туди та швидко з ним розібратися. А коли він помре — забери його посох для мене. Вирушай уже.", [3] = "Убийте даларанського архімага, заберіть його посох і віднесіть його жерцю тіні Аллістерові у Крипту.", [4] = "Поспішай, часу обмаль, {ім'я}!", [5] = "Магія чарівників розсіюється, а лей-енергія знову заспокоюється. Твої зусилля були плідними, {ім'я}, і ми завдали серйозного удару нашим ворогам і зухвалим чарівникам Даларана.\n\nПроте, ми повинні бути пильними, знаючи, що таке потужне джерело енергії знаходиться зовсім близько... Потрібно розробити плани на майбутнє.", ["en"] = "The Weaver", ["tasks"] = { ["Ataeric's Staff"] = "посох Атеріка", ["Ataeric's Staff (Provided)"] = "посох Атеріка (видано)" } },
    [481] = { [1] = "Аналіз Далара", [2] = "Віднесіть кулон Даларові Ранньоткачу: можливо, він зможе пролити світло на плани чарівників.", [3] = "Віднесіть покритий рунами кулон Даларові Ранньоткачу до Крипти.", [4] = "Слухаю, {клас:к}? Що це?", [5] = "Цікаво, схоже на нові махінації Кірін-Тору. Це — потужний артефакт. Його часто використовували могутні чарівники Кірін-Тору для спрямування магічних енергій.\n\nТе, що вони звозять їх до Бурштинового Млина, свідчить про те, що вони затівають щось серйозне.\n\nПоглянемо, чи зможу я пробити їхні щити та з'ясувати їхні наміри.", ["en"] = "Dalar's Analysis", ["tasks"] = { ["Rune-inscribed Pendant"] = "покритий рунами кулон", ["Rune-inscribed Pendant (Provided)"] = "покритий рунами кулон (видано)" } },
    [482] = { [1] = "Наміри Даларану", [2] = "Звісно! Як я міг забути?\n\nБурштиновий Млин був одним із місць, відмічених Кірін-Тором, тому, що під ним є сплячий вузол лей-енергії. Чарівники, певно, планують реактивувати вузол і використати його енергію для якоїсь більш серйозної мети.\n\nМи не можемо цього допустити...\n\nДля активації лей-енергії цієї місцевості знадобиться багато сил, тож ми можемо їх зупинити, відібравши кулони у чарівників.\n\nПередай цю інформацію Аллістеру. Він вирішить, як діяти далі.", [3] = "Поговоріть із жерцем тіні Аллістером у Крипті.", [5] = "Кепські новини ти {стать:приніс:принесла}, {ім'я}. Якщо Далар має рацію — а я не маю причин вважати інакше — ми мусимо діяти швидко.\n\nЯ повинен обговорити з ним наш план нападу. А тим часом нам доведеться затримати їхній прогрес.", ["en"] = "Dalaran's Intentions" },
    [4821] = { [1] = "Чужоземне яйце", [2] = "З'явилась чутка про чужоземне яйце тут, в Тисячі Шипів. Ті, хто його бачили, не змогли навіть підійти достатньо близько, щоб детально оглянути. Змії оберігають його так, наче воно їх власне.\n\nЯ хочу, щоб ти {стать:знайшов:знайшла} це яйце та {стать:приніс:принесла} його мені для дослідження. Доповідають, що воно знаходиться в зміїному лігві, але таких лігв декілька вздовж схилу скель на півдні на північному сході від застави Розкутого Вітру.", [3] = "Принесіть чужоземне яйце Агару Блискавичному Копиту на заставу Розкутого Вітру.", [4] = "Я маю краще дослідити це загадкове яйце, хто зна, що з нього вилупиться.", [5] = "Так, нарешті... я отримав загадкове яйце. А тепер дозволь мені краще його роздивитись... Що!.. Що це?..", ["en"] = "Alien Egg", ["tasks"] = { ["Alien Egg"] = "чужоземне яйце", ["Alien Egg (Provided)"] = "чужоземне яйце (видано)" } },
    [4841] = { [1] = "Заспокоїти кентаврів", [2] = "{ім'я}, я доручаю тобі розпочати полювання на кентаврів. Вони мусять відчути гнів нашої помсти. Напади на табір кентаврів, що знаходиться на північ від застави Розкутого Вітру! Нехай гнів скеровує твою руку!", [3] = "Вбийте 12 розвідників, 10 чередників та 6 вітроловів племені Ґалак, після чого поверніться до спостерігача скель Довгорогого на заставу Розкутого Вітру.", [4] = "Ну ж бо, {ім'я}, я знаю, що ти іще не {стать:вбив:вбила} вдосталь кентаврів. Вбий їх, і тоді, на знак вдячності, я дам тобі винагороду.", [5] = "На знак моєї дяки, ось, тримай, це тобі, {ім'я}.", ["en"] = "Pacify the Centaur", ["tasks"] = { ["Galak Scout"] = "розвідник племені Ґалак", ["Galak Scout slain"] = "розвідник племені Ґалак: убито", ["Galak Windchaser"] = "вітроловка племені Ґалак", ["Galak Windchaser slain"] = "вітроловка племені Ґалак: убито", ["Galak Wrangler"] = "чередник племені Ґалак", ["Galak Wrangler slain"] = "чередник племені Ґалак: убито" } },
    [4865] = { [1] = "Зміїна дикість", [2] = "Якби я не побачив це на власні очі, то ніколи в житті б не повірив! Помста прийшла в Тисячу Шипів!\n\n<Агар втирає чоло.>\n\n{ім'я}, ти мусиш діяти швидко! Вирушай негайно і знайди Мотеґу Вогняну Гриву. Він на Білосяжній заставі, що вздовж дороги на північний захід від застави Розкутого Вітру. Він знатиме, що робити!", [3] = "Звістіть Мотеґу Вогняну Гриву про свою знахідку.", [5] = "Помста! Отже, легенда про Арікару — правда. Авжеж, це проблема, що має бути вирішена негайно.", ["en"] = "Serpent Wild" },
    [4882] = { [1] = "Охорона таємниць", [2] = "Ви не можете зрозуміти, чи важлива ваша знахідка — намисто, що впало з шиї нещодавно вбитого дикого совуха. Воно випромінює яскраве світло, що пульсує.\n\nМожливо, Трулл Чахлоклят зможе щось розповісти — схоже, він дуже багато знає про диких совухів. Варто розпитати його про це намисто.", [3] = "Віднесіть намисто з синього пір'я до Трулла Чахлоклята на Кровотруйну заставу.", [4] = "{стать:Повернувся:Повернулася} за новим завданням?", [5] = "Важлива знахідка?", ["en"] = "Guarding Secrets", ["tasks"] = { ["Blue-feathered Necklace"] = "намисто з синього пір'я", ["Blue-feathered Necklace (Provided)"] = "намисто з синього пір'я (видано)" } },
    [4883] = { [1] = "Охорона таємниць", [2] = "Хоча я багато знаю про совухів, яких ти {стать:переміг:перемогла} в Зимоключі, я не дуже добре знаюся на їхніх чарах. Але, здається, я знаю декого, хто зможе оглянути намисто і, швидше за все, скаже тобі, що це таке.\n\nНара Дика Грива з Громового Бескиду є експертом у цій галузі, тож звернись до неї. Хай щастить, {ім'я}.", [3] = "Віднесіть намисто з синього пір'я Нарі Дикій Гриві.", [4] = "Чим я можу допомогти тобі, {ім'я}?", [5] = "Енергія цього намиста, {ім'я}. Я думаю вона має лише одне джерело.\n\n<Нара заплющує очі та замовкає на мить.>\n\nДикі совухи, ошукані та перелякані істоти, не завжди були такими. Вони були створені для того, щоб служити нічним ельфам. Богиня нічних ельфів Елуна створила їх, щоб охороняти священні місця.\n\nЗвичайно, це здається неважливим, проте я закликаю тебе заглянути глибше.\n\nСвого часу ти зрозумієш. Дякую, що {стать:приніс:принесла} мені це намисто, {ім'я}.", ["en"] = "Guarding Secrets", ["tasks"] = { ["Blue-feathered Necklace"] = "намисто з синього пір'я", ["Blue-feathered Necklace (Provided)"] = "намисто з синього пір'я (видано)" } },
    [4904] = { [1] = "Нарешті вільна!", [2] = "Арнак думав, що одружиться зі мною... але після того, як я відхилила його пропозицію, він повернувся вночі та викрав мене. Мій брат намагався його зупинити, але Арнак був надто сильним... він вбив мого брата, а після цього привів мене сюди. Мій бідолашний брат...\n\n{ім'я}, чи не {стать:міг би:могла б} ти вивести з Темнохмарного верхів'я? Прошу... мені потрібно повернутися до Талії. Вона певно страшенно переймається через мене.", [3] = "Виведіть Лакоту Пісню Вітру з Темнохмарного верхів'я, після чого поговоріть з Талією Бурштиношкурою на заставі Розкутого Вітру.", [5] = "Дякую тобі, {ім'я}. Десь в глибині душі я вірила, що вона знайде спосіб повернутися до мене. Вона розповіла мені про твою хоробрість, і як ти {стать:допоміг:допомогла} їй втекти. Ці речі належали її брату. Я точно знаю, що вона хотіла б, щоб вони залишились у тебе.", ["en"] = "Free at Last", ["tasks"] = { ["Escort Lakota Windsong from the Darkcloud Pinnacle."] = "Супровід Лакота Пісні Вітру з Вершини Темної Хмари." } },
    [491] = { [1] = "Жезл для Бетора", [2] = "Одного разу Тул розповів мені, як колись давно він і два його колеги створили магічний жезл, сплетений воєдино з учнівських жезлів, що належали кожному з магів. Цей жезл був символом їхньої дружби, і, хоча Тул ненавидів його, він не міг ні розпрощатися з ним, ні дозволити іншим ним володіти. Тож він украв жезл і сховав його у фортеці Фенріса.\n\nОсь. Віднеси жезл Беторові Кригозламу, одному з друзів Тула з минулого. Я впевнений, що він буде радий отримати його.", [3] = "Віднесіть сплетений жезл до Бетора Кригозлама у квартал Магії Підмістя.", [4] = "{Ім'я}, ти {стать:покінчив:покінчила} з Тулом Воронокігтем?", [5] = "...що це? Тул володів нашим сплетеним жезлом? Я думав, що його було втрачено, коли наша дружба розвалилася і він перейшов на бік Короля-ліча!\n\nНапевно, він не викликав його силу, бо якби він це зробив, я б відчув. І це добре, що він його не використовував...\n\nЦе дивовижна знахідка. Я щиро вдячний, {ім'я}, і я винагороджу тебе.", ["en"] = "Wand to Bethor", ["tasks"] = { ["Woven Wand"] = "сплетений жезл", ["Woven Wand (Provided)"] = "сплетений жезл (видано)" } },
    [492] = { [1] = "Нова чума", [2] = "Смертестраж повідомив мені, що вони схопили ще одного дурного дворфійського горянина. Смертестражі зазвичай використовують підвал таверни «Край шибениці» як місце утримання, допоки вони «як слід» не попрацюють з в'язнем.\n\nЧому б тобі не подивитися, як цей полонений горянин смакуватиме особливий напій, що я приготував для нього? Він містить в собі витончений натяк на те, що Темна Леді планує зробити з рештою Азероту.", [3] = "Принесіть особливий напій Йогаана полоненому горянину.", [4] = "Якби я мав свою вірну рушницю, то ти б уже {стать:відкинув:відкинула} ноги, {клас:к}. Почекай лише, доки Паровотанкова бригада не приїде мене рятувати!", [5] = "О, нарешті є що випити. Я впевнений, це не фірмова «Рапсодія солоду», але наразі я прийму будь-що, щоб змочити горло.", ["en"] = "A New Plague", ["tasks"] = { ["Johaan's Special Drink"] = "особливий напій Йогаана", ["Johaan's Special Drink (Provided)"] = "особливий напій Йогаана (видано)" } },
    [4921] = { [1] = "Пропала у бою", [2] = "Ми билися в невеликому тауренському таборі, коли нас розділили - вона стиналася з трьома Щетиношкурими одночасно. Численність була не на нашу користь. Я відвів деяких подалі, та лише побачив, як на неї набігло ще більше нових ворогів. У своїй люті я кинувся на них, але вони з легкістю мене здолали завдяки своїх неосяжній кількості.\n\nКоли я отямився, то побачив таурена-друїда, що доглядав мої рани - він надибав мене на Шляху Золота.\n\nБудь ласка, {клас:к}, знайди хоч якісь сліди моєї дружини.", [3] = "Знайдіть дружину Манкріка, а потім поверніться до нього на Перехрестя.", [4] = "У тебе є хоча б якісь звістки про неї? Біль у грудях говорить, що сталося найгірше, але я сподіваюся, ти знайдеш її здоровою та неушкодженою.", [5] = "Я зрозумів. Дякую, {клас:к}.", ["en"] = "Lost in Battle", ["tasks"] = { ["Find Mankrik's Wife"] = "Знайти дружину Манкрика" } },
    [493] = { [1] = "Подорож до передгір'я Гіллзбраду", [2] = "Королівське товариство аптекарів зазнає надзвичайного тиску з боку Темної Леді щодо розробки нової чуми. Ми старанно працюємо та досягли значного прогресу. На наш погляд, успіх буде здобуто набагато швидше, якщо ми ділитимемося інформацією у товаристві.\n\nЗ цієї причини я хочу, щоб ти {стать:доставив:доставила} мої останні дані досліджень аптекареві Лідону в Тарренський Млин, маленьке містечко, розташоване в передгір'ях Гіллзбраду. Шлях неблизький.\n\nРушай на південь і тримайся доріг. Чітко слідуй вказівникам!", [3] = "Віднесіть дані досліджень аптекаря Ренферрела аптекарю Лідону до міста Тарренський Млин у передгір'я Гіллзбраду.", [4] = "У тебе є щось для мене?", [5] = "Ах, просто чудово. Я глибоко поважаю аптекаря Ренферрела. Мені не терпиться вивчити його роботи.", ["en"] = "Journey to Hillsbrad Foothills", ["tasks"] = { ["Renferrel's Findings"] = "дані досліджень Ренферрела", ["Renferrel's Findings (Provided)"] = "дані досліджень Ренферрела (видано)" } },
    [494] = { [1] = "Час завдати удару", [2] = "Тихо та уважно, {клас:к}.\n\nМене відправили на цю позицію для того, щоб обстежити Гіллзбрад. Моя місія — розвідка. Вкрай важливо, щоб ти негайно {стать:доставив:доставила} повідомлення верховній карательці Дарталії в Тарренський Млин. Передай їй, що я, смертоловка Леш, надсилаю наступне послання:\n\n\"Крик ворона із заходу вабить\".\n\nЙди дорогою на схід і уважно стеж за знаками. А тепер поспішай! Вирушай до Тарренського Млина, і, мушу зауважити, терміново!", [3] = "Відправляйтеся в Тарреньский Млин, щоб доставити послання смертоловки Леші верховній карательці Дарталії.", [5] = "Крик ворона із заходу вабить?\n\nЧудові новини! Гіллзбрад готовий до нападу. Тепер ми можемо здійснити наш план знищення. Варіматрас буде задоволений.", ["en"] = "Time To Strike" },
    [4941] = { [1] = "Мудрість Ейтріґа", [2] = "Ренд живий?\n\nНеможливо!\n\nВважалося, що він загинув десятки років тому.\n\nЗвернись за порадою до Ейтріґа, {ім'я}. Ніхто не знає про орків Чорнокаменю краще за нього, і якщо те, що написано тут — правда, Ейтріґу варто про це знати. Нікому не можна відмовляти в праві на помсту.\n\nТи знайдеш його в Орґріммарі.\n\nПісля того, як поговориш з Ейтріґом, йди до воєвождя за вказівками.", [3] = "Поговоріть з Ейтріґом в Орґріммарі. Обговоривши питання з Ейтріґом, зверніться за порадою до Тралла.\n\nВи пригадуєте, що бачили Ейтріґа в приймальній залі Тралла.", [4] = "Хіба ти не бачиш, що я зайнятий?", [5] = "<Схоже, що Тралл стурбований вашою звісткою.>", ["en"] = "Eitrigg's Wisdom", ["tasks"] = { ["Council with Eitrigg."] = "Рада з Ейтріґґом." } },
    [495] = { [1] = "Корона Волі", [2] = "Муґ'Тола та його банду огрів послали до Альтераку, щоб вони роздобули Корону Волі для леді Сильвани. На жаль, замість того, щоб її принести, цей ідіот вирішив надягнути її... Гадаю, огри не можуть встояти перед чимось яскравим і блискучим.\n\nОднак, його дурні дії створюють певні труднощі. Корона Волі наділила його силою противитися одержимості, яку наклали на нього, щоб служити леді Сильвані.\n\nТемна Леді хоче його провчити, тож йди до Тарренського Млина у Гіллзбраді та відрапортуй Мелісарі, моїй лейтенантці.", [3] = "Відзвітуйте Мелісарі у Тарренському Млину, розташованому в передгір'ї Гіллзбраду.", [5] = "Тебе прислала Шарліндра? Дуже добре, тоді ти побачиш, що я не марную час дурними балачками.\n\nМуґ'Тол дратує, тому ми розберемося з ним швидко, ретельно та без зайвих пригод.", ["en"] = "The Crown of Will" },
    [496] = { [1] = "Еліксир страждання", [2] = "Ах, ще один жалюгідний день у Тарренському Млині. Це чисте повітря так псує мені настрій, {ім'я}.\n\nЧим швидше ми зможемо знищити тутешніх людей, тим краще. Я проводжу інтенсивні дослідження можливих вбивчих речовин, які можна використати в моїх рецептах, але у мене немає часу, щоб зібрати їх усі.\n\nЯкщо ти хочеш принести мені користь, здобудь для мене 10 сірих ведмежих язиків та дуже рідкісний і важкодоступну пасоку підкрадача. І ведмедів, і підкрадачів ти знайдеш неподалік від Тарренського Млину.", [3] = "Аптекареві Лідону із Тарренського Млина потрібні 10 язиків сірого ведмедя і пасока підкрадача.", [4] = "Бачу, ти {стать:повернувся:повернулася}. Сподіваюсь, тобі вдалося зібрати потрібні мені реагенти. Ще один безсмертний день наганяє на мене такий похмурий настрій.", [5] = "Ці зразки ідеальні. Що ж, {ім'я}, тобі вдалося принести мені легкий натяк на радість у цей черговий похмурий день. Я ціню твої зусилля.", ["en"] = "Elixir of Suffering", ["tasks"] = { ["Creeper Ichor"] = "пасока підкрадача", ["Creeper Ichor (Provided)"] = "пасока підкрадача (видано)", ["Gray Bear Tongue"] = "язик сірого ведмедя", ["Gray Bear Tongue (Provided)"] = "язик сірого ведмедя (видано)" } },
    [4966] = { [1] = "Захистити Канаті Сіру Хмару", [2] = "Кентаврів може бути більше, ніж я гадав. Прошу, {ім'я}, бийся разом зі мною проти цих нікчемних душогубів.", [3] = "Захистіть Канаті Сіру Хмару від нападу кентаврів.", [5] = "Дякую за допомогу, {ім'я}. Без тебе я б не зумів їх стримати.", ["en"] = "Protect Kanati Greycloud", ["tasks"] = { ["Protect Kanati Greycloud"] = "Захистіть Канаті Грейхлауд" } },
    [498] = { [1] = "Порятунок", [2] = "Я та кілька інших воїнів були послані воєвождем забрати об'єкт з Дарнгольда та дослідити цей так званий Синдикат.\n\nМи вирушили до Дарнгольду, щоб оглянути місцевість, але були захоплені зненацька великою кількістю людей. Ми хоробро билися, але їхньої кількості було достатньо, щоб перемогти нас. Декого з нас вони взяли в полон, але мені вдалося втекти.\n\nДарнгольд знаходиться на південний схід звідси, за річкою. Там утримують Друлла і Тоґ'тара, ти маєш піти та врятувати їх.", [3] = "Краск з Тарренського Млина хоче, щоб ви звільнили Друлла і Тоґ'тара з фортеці Дарнгольд.", [4] = "Ти маєш поквапитись, {клас:к}. Я здригаюся від думки, що люди можуть зробити з Друллом і Тоґ'таром.", [5] = "Тож люди додумалися перетворити наших воїнів на рабів, чи не так? Ми їм покажемо!\n\nСхоже, вони забрали Ґол'діра, нашого ватажка, в інше місце. Ми повинні знайти його і врятувати. Але наразі ми не знаємо, де він...\n\nКоли у нас з'явиться зачіпка, я обов'язково скажу тобі, {ім'я}.", ["en"] = "The Rescue", ["tasks"] = { ["Rescue Drull"] = "Звільніть Друлла", ["Rescue Tog'thar"] = "Звільніть Тоґ'тара" } },
    [4987] = { [1] = "Покрита письменами дубова гілка", [2] = "Мертва рука друїда стискає, на диво, наповнену життям дубову гілку. Оглянувши її, ви бачите вирізані знаки, притаманні природі друїдів.\n\nКоли ви берете гілку до рук, ви помічаєте, що вона напрочуд тепла на дотик, тепліша, ніж має бути. Зображення Громового Бескиду виникає у вашій свідомості, а саме Верхів'я Старійшин. А слова \"Кенарійське Коло\" крутяться на кінчику вашого язика. Схоже, що у гілку були вкладені знання про те, куди саме треба її принести.", [3] = "Судячи з магії, вкладеної в покриту письменами дубову гілку, друїд-таурен хотів доставити її до Кенарійського Кола в Громовому Бескиді. Знайдіть одного з тамтешніх друїдів.", [4] = "Від імені Кенарійського Кола, я вітаю тебе в цьому анклаві, {клас:к}. Що привело тебе до нас?", [5] = "Отже, це від Мулґріса? Му чули, що він прагнув позбавити створінь Зачумлених земель страждань, але це дуже несподівано... та дуже сумно. Мулґріс був... гарним другом. Я глибоко сумуватиму з приводу його смерті.\n\nАле завдяки тобі його зусилля не були марними. У цій гілці міститься безліч знань про наступ чуми на наші землі. Ми уважно вивчимо їх. А щодо тебе, будь ласка, прийми це. Це найменше, що ми можемо зробити за твої старання.", ["en"] = "Glyphed Oaken Branch", ["tasks"] = { ["Glyphed Oaken Branch"] = "покрита письменами дубова гілка", ["Glyphed Oaken Branch (Provided)"] = "покрита письменами дубова гілка (видано)" } },
    [499] = { [1] = "Еліксир страждання", [2] = "Мені знадобиться лише секунда, щоб змішати ці компоненти в те, що я назвав еліксиром страждання.\n\nОсь так! Ніщо так не скрашує похмурий день у цих жалюгідних передгір'ях, як внесення у світ трохи страждань.\n\nДавай подивимося, чи досягло наше маленьке зілля бажаного ефекту.\n\nДай моєму помічникові Умпі спробувати, що Темна Леді запланувала для людей і створінням Скари.", [3] = "Дайте Умпі еліксир страждання.", [4] = "Ква!", [5] = "Квак!", ["en"] = "Elixir of Suffering", ["tasks"] = { ["Elixir of Suffering"] = "еліксир страждання", ["Elixir of Suffering (Provided)"] = "еліксир страждання (видано)" } },
    [501] = { [1] = "Еліксир болю", [2] = "О, {ім'я}. . . у Гіллзбраді розпускаються квіти, а повітря таке свіже і бадьоре. Мене від цього просто нудить! Я дивлюся у своє брудне вікно і жадаю того дня, коли наша нова чума принесе цьому світу заслужену смерть.\n\nЯк би мені не хотілося сидіти й роздумувати цілими днями, але мій обов'язок перед Темною Леді кличе мене. Допоможи мені, будь ласка. Мої дослідження приводять мене до думки, що я можу приготувати найпрекрасніше смертельне зілля з крові гірського лева. Принеси мені трохи крові, і ми розважимося.", [3] = "Принесіть 10 флаконів крові гірського лева аптекарю Лідону у Тарренський Млин.", [4] = "Я пам'ятаю тебе, {ім'я}. Ти {стать:збирався:збиралася} допомогти мені з приготуванням мого останнього еліксиру. Мені знадобиться кров, перш ніж я зможу принести свій особливий вид страждань мешканцям Гіллзбраду.", [5] = "Чудова робота, {ім'я}.", ["en"] = "Elixir of Pain", ["tasks"] = { ["Mountain Lion Blood"] = "кров гірського лева", ["Mountain Lion Blood (Provided)"] = "кров гірського лева (видано)" } },
    [502] = { [1] = "Еліксир болю", [2] = "Ніщо не може зрівнятися із запахом свіжої крові в передгір'ї!\n\nТепер ми змішаємо трохи цього і трішки того, і почнемо справжню забаву! Те, що я створив із цієї крові, мені хотілося б назвати еліксиром болю. Якщо мої розрахунки вірні, це зілля може стати початком чогось дуже прекрасного для леді Сильвани. Але нам потрібен тест.\n\nВіднеси цей еліксир на північну ферму в поля Гіллзбраду на південному заході. Подивимось, як сподобається цей \"смаколик\" маленькому песику фермера Рея — Стенлі.", [3] = "Напоїть Стенлі еліксиром болю.", [4] = "Гав?", [5] = "Ви наливаєте трохи еліксиру собі в долоню і простягаєте її Стенлі.", ["en"] = "Elixir of Pain", ["tasks"] = { ["Elixir of Pain"] = "еліксир болю", ["Elixir of Pain (Provided)"] = "еліксир болю (видано)" } },
    [5023] = { [1] = "Краще пізно, ніж ніколи", [2] = "Ви берете пакунок, стираючи з нього шар пилу та бруду. Ім'я адресата написано нашвидкуруч — Єремія Сквернокамінь з Лордерону. Пакунок мав прибути чотири роки тому.\n\nПопри те, що невідомо, чи Єремія Сквернокамінь живий, всім відомо, що у Підмістя, раніше відомого як Лордерон, є реєстр населення міста. Вам варто поговорити з королівськими інспекторами перепису Підмістя.", [3] = "Поговоріть з королівськими інспекторами Підмістя, щоб дізнатися місцеперебування Єремії Сквернокамінь. Зазвичай, офіцера перепису можна знайти біля пункту реєстрації гільдії.", [4] = "Тобі потрібна інформація з реєстру Підмістя, чи ти хочеш дізнатись, чи не помер хтось з твоїх знайомих? Мене часто це питають.", [5] = "Пакунок для Єремії Сквернокамінь, остання адреса проживання — Лордерон... Я допоможу тобі.\n\nЄремія Сквернокамінь проживав у місті перед чумою. Тобто, колишній Єремія Сквернокамінь — більшість відречених змінили свої прізвища, щоб позбутися свого минулого. І цей випадок — не виняток. Єремія Сквернокамінь тепер відомий як Єремія Пейсон.\n\nХвилиночку... а це не він продає тарганів?", ["en"] = "Better Late Than Never", ["tasks"] = { ["Janice's Parcel"] = "пакунок Дженіс", ["Janice's Parcel (Provided)"] = "пакунок Дженіс (видано)" } },
    [503] = { [1] = "Ґол'дір", [2] = "Судячи з добутих тобою документів, Ґол'діра утримують на великій базі Синдикату на півночі, ймовірно, в Альтерацьких горах. Він був у полоні занадто довго, час звільнити його.", [3] = "Звільніть Ґол'діра, а потім поверніться до Краска в Тарренський Млин.", [4] = "Дай мені ключ, {клас:к}, я сам відчиню замок.", [5] = "Дякую, {ім'я}. Я очолив експедицію з Дуротара за наказом воєвождя, але, як бачиш, наші плани дещо порушилися. Вони тримали мене в полоні в цьому місті, змушуючи працювати, тягати тягарі, копати...\n\nАле те, що я пережив — неважливо. Є важливіша інформація, яку ти маєш передати тому, хто зараз очолює нашу групу.", ["en"] = "Gol'dir", ["tasks"] = { ["Rusted Iron Key"] = "іржавий залізний ключ", ["Rusted Iron Key (Provided)"] = "іржавий залізний ключ (видано)" } },
    [5041] = { [1] = "Припаси для Перехрестя", [2] = "Під час нападу на караван ми втратили припаси, які нам були вкрай необхідні.\n\nТобі вистачило хоробрості, щоб битися з плем'ям Бритвогривих, і я попрошу тебе зробити це знову, але цього разу пошукай наші припаси. Ти, напевно, знайдеш їх у їхньому таборі, де свинобрази жирують на чужому добрі.\n\nЖителі Перехрестя будуть перед тобою в боргу.", [3] = "Знайдіть і поверніть ящики з припасами для Перехрестя Торку в Степи.", [4] = "Як просуваються твої пошуки припасів, {ім'я}? Думаю, ти легко впораєшся зі свинобразами.", [5] = "Ха-ха! Дякую, {ім'я}! Ти нам неймовірно {стать:допоміг:допомогла}. Ти — спасіння для Перехрестя і для всієї Орди. Якщо я можу тобі чимось допомогти, прошу, дай мені знати.", ["en"] = "Supplies for the Crossroads", ["tasks"] = { ["Crossroads' Supply Crates"] = "ящики з припасами для Перехрестя", ["Crossroads' Supply Crates (Provided)"] = "ящики з припасами для Перехрестя (видано)" } },
    [5044] = { [1] = "Мудрість Аґамаґґана", [4] = "Шамани та геоманти племен свинобразих <фиркає> прикликають силу Аґамаґґана для допомоги у битвах та ритуалах, {раса:к}.\n\nЯкщо ти теж бажаєш отримати благословення Аґамаґґана для своїх заклять - принеси 4 кривавих скалки, і Кривозуб тобі допоможе.", [5] = "Твої вороги ще дужче боятимуться тебе, {раса:к}.\n\nРозкажи Кривозубові історії про свою винахідливість у бою, коли ми зустрінемось в майбутньому — в цьому житті чи наступному. <фирк>", ["en"] = "Wisdom of Agamaggan", ["tasks"] = { ["Blood Shard"] = "кривавий скалок", ["Blood Shard (Provided)"] = "кривавий скалок (видано)" } },
    [5045] = { [1] = "Піднесення духу", [4] = "Усякий воїн <фиркає> потребує сильного духу. Він спонукатиме тебе на ще більші звершення, навіть коли надії вже немає. Племені Бритвогривих це здавна відомо. <фиркає> Ми - духовне плем'я та більше пишаємося своїм зв'язком з Аґамаґґаном, ніж нашою майстерністю <фиркає> в бою.\n\nПринеси мені 4 кров'яних скалки, і я благословлю твій дух для бою. <фиркає>", [5] = "Наші найвправніші воїни та наймогутніші <фиркає> шамани позаздрили б твоїй силі волі, {раса:к}.\n\nПодолай ще більше Щетиношкурих, знаючи, що вони не можуть тебе зупинити! <фиркає>", ["en"] = "Rising Spirit", ["tasks"] = { ["Blood Shard"] = "кривавий скалок", ["Blood Shard (Provided)"] = "кривавий скалок (видано)" } },
    [5046] = { [1] = "Бритвошкура", [4] = "Тому, хто йде в бій, <фиркає> захист не завадить. Їхні кістки мають бути міцними, а шкіра - жорсткою. <фиркає> Моє плем'я чудово знає це, і, крім дарованих нам від природи голок і товстої шкури, <фиркає> ми часто просимо Аґамаґґана про захист перед тим, як йти на війну.\n\nПринеси мені 4 криваві скалки <фиркає>, і я дарую тобі такий самий захист.", [5] = "Іди в бій, {раса:к}.", ["en"] = "Razorhide", ["tasks"] = { ["Blood Shard"] = "кривавий скалок", ["Blood Shard (Provided)"] = "кривавий скалок (видано)" } },
    [5052] = { [1] = "Криваві скалки Аґамаґґана", [2] = "Кров зачепила не тільки терни, <фиркає> але й інші аспекти землі: криваво-червоні камені, змішані з іншими мінералами. Щетиношкурі викопують ці обламки та застосовують їх як тотеми <фиркає>, що підсилюють їх у бою та використовують для магії. <фиркає>\n\nЯ знаю секрети цієї магії.\n\nЯк принесеш Кривозубові одну таку скалку, то він тобі покаже. А якщо принеш Кривозубу цілу купу таких, то він благословить тебе магією свинобразів - магією Аґамаґґана! <фиркає>", [3] = "Принесіть кривавий скалок Кривозубові в табір Таурахо у Степах.\n\nЗберіть більше кривавих скалків, якщо бажаєте, щоб він благословив вас силою Аґамаґґана.", [4] = "Наші племена розселяються поміж тернистих районів по всім Степам <фиркає>, тому що це - святі місця, проте жодне не зрівняється зі святістю Бритвоболота. Воно повністю створене з тіла Аґамаґґана, <фиркає>, але Нори - особливо захищені, оскільки вхід зроблений з його величної пащі! <фиркає> Він проковтне всіх, хто йому не вірний, і виплюне їхні тіла після того, як гарненько пережує! <фиркає>\n\nАґамаґґан залишив своє тіло, щоб захистити нас, і щедро ділиться своїм духом, щоб ми могли захистити його. <фиркає>", [5] = "Ов-ва, то ти таки розумієш. <фиркає> Я не дарма перед тобою розпинався, {раса:к}. Кривозуб хоч і замкнений, але жодна клітка не зможе зупинити могутність Аґамаґґана!\n\nДотик до скалка, ці відчуття... це було вже так давно, {раса:к}.\n\nТи знаєш, як це? Коли твою силу вирвали в тебе?\n\nАле ця оповідь на інший раз. Я обіцяв тобі інформацію. Я обіцяв тобі силу Аґамаґґана. Мої люди відвернулися від Кривозуба. Тож тепер я напущу тебе на них. <фиркає>", ["en"] = "Blood Shards of Agamaggan", ["tasks"] = { ["Blood Shard"] = "кривавий скалок", ["Blood Shard (Provided)"] = "кривавий скалок (видано)" } },
    [5054] = { [1] = "Урсій з щербозубів", [2] = "У засніжних горах Зимоключа, на північний захід звідси, вправний мисливець полює на свою здобич... Я маю на увазі Урсія з виду ведмедів-щербозубів, спритного та хитрого звіра.\n\nЯ відправляю тебе вбити його. Він блукає схилами на північному заході від Завшегляду. Знайди його та здолай, перш ніж він зрозуміє твої наміри.\n\nУсі, хто стикається з Урсієм, швидко стають здобиччю, адже він — мисливець. Будь {стать:обережним:обережною}.", [3] = "Шторм Тіньове Копито з Завшегляду, що у Зимоключі хоче, щоб ви вбили Урсія.", [4] = "Йди, {клас:к}. Знайди Урсія.", [5] = "Це було нелегке завдання, але ти з ним {стать:впорався:впоралася}. Але не думай, що ти мене {стать:вразив:вразила}, {ім'я}.", ["en"] = "Ursius of the Shardtooth", ["tasks"] = { ["Ursius"] = "Урсій", ["Ursius slain"] = "Урсій: убито" } },
    [5055] = { [1] = "Брумеран зі студовіїв", [2] = "Швидка і розумна, Брумеран безшумно ковзає засніженими землями південного Зимоключа. Але нехай тебе не дурить її грація — вона аж ніяк не безпечна. Всі, хто переходить їй дорогу, платять чималу ціну, а часто і власним життям.\n\nШукай Брумеран з виду химер-студовіїв. Вбий її, а потім повертайся до мене.", [3] = "Шторм Тіньове Копито з Завшегляду, що у Зимоключі хоче, щоб ви вбили Брумеран.", [4] = "Брумеран чекає тебе, {ім'я}.", [5] = "Так. Ти {стать:повернувся:повернулася}. Тепер я вірю, що ти {стать:справжній мисливець:справжня мисливиця} по своїй натурі. Ти {стать:зіткнувся:зіткнулася} з найлютішою з істот і {стать:повернувся:повернулася}, перевершивши всі мої очікування.\n\nТепер ти {стать:готовий:готова} до мого останнього прохання.", ["en"] = "Brumeran of the Chillwind", ["tasks"] = { ["Brumeran"] = "Брумеран", ["Brumeran slain"] = "Брумеран: убито" } },
    [5056] = { [1] = "Ши-Ротам", [2] = "У північному Зимоключі великі коти збираються навколо узгір'я Кригозубів. Лідером цих кішок є Ши-Ротам. Перемога над матріархом кригозубів додала б тобі багато поваги в очах твого народу.\n\nВирушай назад у глушину і збери священне м'ясо кригозубів. Знайди камінь Ши-Ротам і помісти туди м'ясо її родичів. Це спровокує гнів Ши-Ротам.\n\nБудь {стать:готовим:готовою} до її гніву та вбий її.", [3] = "Шторм Тіньове Копито з Завшегляду, що у Зимоключі хоче, щоб ви вбили Ши-Ротам.", [4] = "Ши-Ротом смілива і невблаганна, вона буде захищати свій вид з повною відданістю.", [5] = "Ти {стать:довів:довела} і свою силу, і свою рішучість. На тебе чекає ще багато випробувань. Я вже показав тобі все, що міг.", ["en"] = "Shy-Rotam", ["tasks"] = { ["Shy-Rotam"] = "Ши-Ротам", ["Shy-Rotam slain"] = "Ши-Ротам: убито" } },
    [506] = { [1] = "Спадщина Блекмура", [2] = "День чи два тому до мене прийшов ватажок цього Синдикату. Його звали Аліден Перенольд, і він називав себе лордом цих земель. Він розповів мені свої плани про поневолення орків, які виступили проти нього, як це планували його батько і його наставник, підлий Блекмур.\n\nЩе важливіше було те, що він привів із собою коханку — тендітну дівчину, на ім'я Еліза. На її шиї висіло намисто, яке бажав воєвождь.\n\nА тепер іди. Я піду своєю дорогою, коли закінчу свої справи в таборі.", [3] = "Доставте інформацію, зібрану Ґол'діром, до Краска в Тарренський Млин.", [5] = "Треба ж, які ці люди нахаби! Ми покажемо їм, що орки ніколи не підкоряться їм!\n\nВідтепер це буде нашою метою, на додачу до повернення тієї прикраси, яку бажає воєвождь. Схоже, що виконавши одне, ми виконаємо і друге.", ["en"] = "Blackmoore's Legacy" },
    [5062] = { [1] = "Священний вогонь", [2] = "Арікара — це смертельно небезпечна істота, з якою необхідно розібратись якомога швидше. Для того, щоб подолати її, тобі знадобиться священний вогонь життя, — він викличе Арікару.\n\nВирушай за рослинами рідкісної вогнистої агави. Щойно матимеш їх достатньо — знайди Маґату Зловісний Тотем на Верхів'ї Старійшин в Громовому Бескиді. Це могутня шаманка, котра може зачарувати рослину агави й створити з неї порошок, здатний запалити вогонь.\n\nПрямуй на північний схід до Киплячого ставу і збери вогнисту агаву.", [3] = "Зберіть 10 рослин вогнистої агави, після чого поговоріть з Маґатою Зловісним Тотемом на Верхів'ї Старійшин у Громовому Бескиді.", [4] = "Отже, Мотеґа Вогняна Грива шле звістку про Арікару... це жахлива звістка.\n\n<Маґата озирається навкруги.>\n\nАрікара — це смертельно небезпечна істота, народжена з єдиною ціллю — мститися тим, хто чинив мерзенні дії.\n\n<Маґата посміхається.>", [5] = "Чудово, ти {стать:зібрав:зібрала} достатньо вогнистої агави. Ця рідкісна рослина, яка росте лише в Тисячі Шипів, допоможе пробудити священний вогонь життя.\n\n<Маґата починає зачаровувати вогнисту агаву.>", ["en"] = "Sacred Fire", ["tasks"] = { ["Incendia Agave"] = "вогниста агава", ["Incendia Agave (Provided)"] = "вогниста агава (видано)" } },
    [5064] = { [1] = "Спостереження за Зловісним Тотемом", [2] = "{Ім'я}, ти гарно {стать:послужив:послужила} нам раніше, тож я довіряю тобі важливе завдання. Клан Зловісного Тотема затіває щось таємне. Протягом останніх тижнів до їхнього поселення приходили троє агентів невідомого походження. Ми дізналися, що в скринях на Темнохмарному верхів'ї знаходяться важливі папери.\n\n{Ім'я}, якщо ти успішно виконаєш це завдання, я тебе щедро винагороджу.", [3] = "Знайдіть три таємні записки на Темнохмарному верхів'ї та принесіть їх спостерігачу скель Довгорогому на заставу Розкутого Вітру.", [4] = "Ти вже {стать:дізнався:дізналася}, що саме затіває Зловісний Тотем?", [5] = "Великий Тотем Духів! Це справді страшні новини. Я маю почати готуватися до того, що на нас чекає.\n\n{ім'я}, як і було обіцяно, ось винагорода за твою сміливу допомогу.", ["en"] = "Grimtotem Spying", ["tasks"] = { ["Secret Note #1"] = "таємна записка №1", ["Secret Note #1 (Provided)"] = "таємна записка №1 (видано)", ["Secret Note #2"] = "таємна записка №2", ["Secret Note #2 (Provided)"] = "таємна записка №2 (видано)", ["Secret Note #3"] = "таємна записка №3", ["Secret Note #3 (Provided)"] = "таємна записка №3 (видано)" } },
    [507] = { [1] = "Лорд Аліден Перенольд", [2] = "Очевидно, що Перенольда треба вбити, позбавивши світ від його мерзенності. Його маєток розташований на північ звідси, на березі Лордамерського озера. Виконай свій обов'язок, {ім'я}, потім знайди намисто, яке бажає воєвождь, і повертайся сюди.", [3] = "Вбийте лорда Алідена Перенольда і розпитайте його коханку Елізу про намисто Тарети.", [4] = "Щ-що вам треба?", [5] = "Ні, ні, будь ласка, не вбивайте мене! Я ніколи не бажала вашим людям зла, він тримав мене проти моєї волі! Будь ласка... помилуйте мене!", ["en"] = "Lord Aliden Perenolde", ["tasks"] = { ["Lord Aliden Perenolde"] = "Лорд Аліден Перенольд", ["Lord Aliden Perenolde (Provided)"] = "Лорд Аліден Перенольд (видано)", ["Lord Aliden Perenolde slain"] = "лорд Аліден Перенольд: убито" } },
    [508] = { [1] = "Подарунок Тарети", [2] = "Намисто? Звичайно, можете забрати його... Заберіть його! Я не хочу про нього пам'ятати... Прошу, благаю, дайте мені спокій...", [3] = "Принесіть намисто Тарети Краску в Тарренський Млин.", [4] = "Ти {стать:повернувся:повернулася}, {ім'я}. Доповіси про успіх?", [5] = "Дивно, що воєвождь витрачає стільки сил на таку дрібницю. Я не завжди розумію його мотиви, але я піду за ним, що б він не наказав. Ти молодець, {ім'я}, без сумніву, воєвождь буде радий почути про твій успіх.", ["en"] = "Taretha's Gift", ["tasks"] = { ["Taretha's Necklace"] = "намисто Тарети", ["Taretha's Necklace (Provided)"] = "намисто Тарети (видано)" } },
    [509] = { [1] = "Еліксир агонії", [2] = "Ще один день, ще один еліксир, який треба приготувати. Якби це залежало від мене, я б просто дозволив жалюгідним людям і Скарі вбивати одне одного. Їм це так подобається.\n\nНа щастя, наша Темна Леді хоче трохи пришвидшити цей процес, тож чому б не прикрасити ці жахливі дні, поширивши трохи смерті та хвороб по всій землі?\n\nОсь план, {ім'я}: ти підеш у маєток Нетандера, на південь від Тарренського Млину та на схід від річки й Південнобережжя. Збери на полі 6 квіток Брудномордих для мого наступного еліксиру.", [3] = "Принесіть 6 квіток Брудномордих аптекарю Лідону в Тарренський Млин.", [4] = "Як успіхи в маєтку Нетандера?", [5] = "Ах, жахливий сморід від квіток Брудномордих. Принаймні, ці бридкі гноли хоч на щось придатні.", ["en"] = "Elixir of Agony", ["tasks"] = { ["Mudsnout Blossoms"] = "квітка Брудномордих", ["Mudsnout Blossoms (Provided)"] = "квітка Брудномордих (видано)" } },
    [5093] = { [1] = "Заклик до зброї: Зачумлені землі!", [2] = "Герої, почуйте мої слова! Орда закликає до рішучих дій!\n\nВсі, хто здатен тримати зброю, мають приєднатися до боротьби проти Скари! Поширюються чутки про нові загрози в руїнах Східних Королівств. Вони нависають над східними кордонами Тірісфальського перелісся, на півночі земель, нині відомих як Зачумлені землі!\n\nСміливці, знайдіть верховного карателя Деррінґтона у таборі на Валу, на схід від Підмістя!", [3] = "Знайдіть верховного карателя Деррінґтона. Його табір знаходиться на Валу, на схід від Тірісфальського перелісся та Підмістя.", [5] = "Вітаю в Зачумлених землях, {стать:герою:героїне}. Це один із найнебезпечніших рубежів Азероту, особливо враховуючи загрозу Скари, що нависла на сході від нас. Я радий чути, що заклик до обов'язку та служіння Орді не залишився непоміченим для тебе!\n\nЯкщо ти {стать:готовий:готова} забруднити руки, то тут, на краю Зачумлених земель, є чим зайнятися охочим і вмілим героям.", ["en"] = "A Call to Arms: The Plaguelands!" },
    [5094] = { [1] = "Заклик до зброї: Зачумлені землі!", [2] = "Герої, почуйте мої слова! Орда закликає до рішучих дій!\n\nВсі, хто здатен тримати зброю, мають приєднатися до боротьби проти Скари! Поширюються чутки про нові загрози в руїнах Східних Королівств. Вони нависають над східними кордонами Тірісфальського перелісся, на півночі земель, нині відомих як Зачумлені землі!\n\nСміливці, знайдіть верховного карателя Деррінґтона у таборі на Валу, на схід від Підмістя!", [3] = "Знайдіть верховного карателя Деррінґтона. Його табір знаходиться на Валу, на схід від Тірісфальського перелісся та Підмістя.", [5] = "Вітаю в Зачумлених землях, {стать:герою:героїне}. Це один із найнебезпечніших рубежів Азероту, особливо враховуючи загрозу Скари, що нависла на сході від нас. Я радий чути, що заклик до обов'язку та служіння Орді не залишився непоміченим для тебе!\n\nЯкщо ти {стать:готовий:готова} забруднити руки, то тут, на краю Зачумлених земель, є чим зайнятися охочим і вмілим героям.", ["en"] = "A Call to Arms: The Plaguelands!" },
    [5095] = { [1] = "Заклик до зброї: Зачумлені землі!", [2] = "Герої, почуйте мої слова! Орда закликає до рішучих дій!\n\nВсі, хто здатен тримати зброю, мають приєднатися до боротьби проти Скари! Поширюються чутки про нові загрози в руїнах Східних Королівств. Вони нависають над східними кордонами Тірісфальського перелісся, на півночі земель, нині відомих як Зачумлені землі!\n\nСміливці, знайдіть верховного карателя Деррінґтона у таборі на Валу, на схід від Підмістя!", [3] = "Знайдіть верховного карателя Деррінґтона. Його табір знаходиться на Валу, на схід від Тірісфальського перелісся та Підмістя.", [5] = "Вітаю в Зачумлених землях, {стать:герою:героїне}. Це один із найнебезпечніших рубежів Азероту, особливо враховуючи загрозу Скари, що нависла на сході від нас. Я радий чути, що заклик до обов'язку та служіння Орді не залишився непоміченим для тебе!\n\nЯкщо ти {стать:готовий:готова} забруднити руки, то тут, на краю Зачумлених земель, є чим зайнятися охочим і вмілим героям.", ["en"] = "A Call to Arms: The Plaguelands!" },
    [5096] = { [1] = "Диверсія Багряного Походу", [2] = "Перш ніж зайнятися Андоралом, ми маємо розібратися з прийдешньою загрозою Багряного Походу з Вогнедолу. Вони отаборилися між Сквернокам'яним полем та Слізьми Дальсона, тож ми опинилися між двох вогнів — Скари та Багряного Походу.\n\nМій план полягає у тому, щоб нацькувати їх одне на одного. Я хочу доручити тобі знищити їхній командний намет. Скористайся пляшками з полум'ям, вони лежать в ящику з запальною сумішшю. Коли підпалиш намет, встанови поруч стяг Скари. Якщо пощастить, вони проігнорують нас та сконцентруються на помсті Скарі.", [3] = "Відправляйтеся до табору Багряного Походу, розташованого між Сквернокам'яним полем та Сльозами Дальсона, та знищте їхній командний намет.\n\nРозмістіть посеред табору стяг Скари та повертайтеся до верховного карателя Деррінґтона на Вал у Західних Зачумлених землях.", [4] = "Наліт на позиції Багряного Походу дасть нам достатньо часу, щоб йти на Андорал. Я сподіваюся, ти тут, щоб доповісти про успіх.\n\nЯкщо так, то ми маємо діяти стрімко та непомітно. Якщо вони не купляться на нашу витівку, тоді нам не вистачить ресурсів та сил, щоб битися водночас проти Скари та Багряного Походу.", [5] = "Бездоганна робота, {ім'я}. Твій напад на Багряний Похід виграв нам трохи часу. Я послав свого найкращого розвідника, щоб він слідкував за табором та переконався, що сили Багряного Походу клюнули на цю наживку.\n\nЩойно натиск Багряного Походу зменшиться, ми зможемо ризикнути та зайнятися завданнями в Андоралі. Це дуже важливо, і я хотів би, щоб цим також {стать:зайнявся:зайнялася} ти — зрештою, у тебе великий досвід.", ["en"] = "Scarlet Diversions", ["tasks"] = { ["Destroy the command tent and plant the Scourge banner in the camp"] = "Знищити командний намет і встановити прапор Бичі в таборі", ["Flame in a Bottle"] = "пляшка з полум'ям" } },
    [5098] = { [1] = "Вздовж сторожових веж", [2] = "Завдяки магічному пристрою, відомому як сигнальний смолоскип, ми можемо помічати цілі для майбутніх дій наших солдатів. Ми думаємо, що Скара використовує вежі Андоралу для того, щоб контролювати рух своїх військ.\n\nТвоє завдання — увірватися в Андорал та встановити смолоскипи на всіх чотирьох вежах. Тобі доведеться стати у дверному отворі кожної вежі, щоб поставити смолоскипи, а він помітить вежу. В сигнальному смолоскипі лише п'ять зарядів, тому використовуй їх розумно!", [3] = "Використовуючи сигнальний смолоскип, помітьте кожну вежу в Андоралі. Вам знадобиться стати у дверному отворі, щоб успішно помітити вежу.\n\nЯк помітите всі вежі, поверніть сигнальний смолоскип верховному карателю Деррінґтону на Вал, в Західні Зачумлені землі.", [4] = "Коли вежі будуть помічені, вони стануть пріоритетними цілями для нашого нападу на Андорал. Я підозрюю, що як тільки ми нейтралізуємо вежі, з'явиться головна загроза Андорала. З цього моменту, ми почнемо пряму боротьбу за місто!\n\nТи {стать:повернувся:повернулася}, щоб повідомити про свій успіх, еге ж? Не забудь сигнальний смолоскип, ми маємо економити наші ресурси.", [5] = "Мої чорнокнижники звітують, що отримали сигнал з усіх чотирьох веж! Ти {стать:виконав:виконала} всі мої накази з навичками та точністю досвідченого ветерана. Твоя служба Орді буде знову винагороджена належним чином, {ім'я}.\n\nВежі помічені, і наша підготовка до атаки завершена. Настав час битви зі Скарою!", ["en"] = "All Along the Watchtowers", ["tasks"] = { ["Tower Four marked"] = "Вежа чотири позначена", ["Tower Four marked (Provided)"] = "Вежа чотири позначена (видано)", ["Tower Four marked slain"] = "Вежа чотири позначена: убито", ["Tower One marked"] = "Вежа Один позначена", ["Tower One marked (Provided)"] = "Вежа Один позначена (видано)", ["Tower One marked slain"] = "Вежа Один позначена: убито", ["Tower Three marked"] = "Вежа Три позначена", ["Tower Three marked (Provided)"] = "Вежа Три позначена (видано)", ["Tower Three marked slain"] = "Вежа Три позначена: убито", ["Tower Two marked"] = "Вежа два позначена", ["Tower Two marked (Provided)"] = "Вежа два позначена (видано)", ["Tower Two marked slain"] = "Вежа два позначена: убито" } },
    [513] = { [1] = "Еліксир агонії", [2] = "Саме тоді, коли я думав, що ще один день пройде без жодної радості, ти {стать:приніс:принесла} мені ці чудові квіти Брудномордих.\n\nСпершу я змішаю їх у чудову суміш. Потім нам знадобиться майстер-аптекар Фаранелл з Підмістя, щоб додати до неї зілля тління, і тоді ми будемо готові до справжньої забави!\n\nОсь, {ім'я}, візьми цю суміш із квітів Брудномордих і негайно віднеси її до майстра Фаранелла.", [3] = "Віднесіть порошок із квіток Брудномордих майстру-аптекарю Фаранеллу в Підмістя.", [4] = "Хіба ти не бачиш, що я зайнятий, {клас:к}? Темна Леді вимагає вивести нову чуму, доки нас не здолала Скара, що насувається з Нортренду. З півдня ж нам загрожують люди, тож час зараз надзвичайно цінний для мене. Краще б це було щось важливе!", [5] = "Тебе прислав аптекар Лідон? Що ж ти одразу не {стать:сказав:сказала}!\n\nПопри свою похмуру вдачу, аптекар Лідон — один з наших найвидатніших та найдосвідченіших учасників товариства.\n\nЦей добрий хлопець прислав суміш із квітів Брудномордих! Я знаю чим зараз займається наш друг з Гіллзбраду. І мені подобається хід його думок. Темна Леді була б дуже вражена прогресом, якого він досягає в розробці нової чуми.", ["en"] = "Elixir of Agony", ["tasks"] = { ["Mudsnout Composite"] = "суміш Брудномордих", ["Mudsnout Composite (Provided)"] = "суміш Брудномордих (видано)" } },
    [5147] = { [1] = "Розшукується — Арнак Зловісний Тотем", [2] = "Розшукується: Арнак Зловісний Тотем\n\nАрнак — вигнанець, який розшукується через огидні злочини: вбивство та викрадення. Сміливців, що наважаться притягнути цього злочинця до відповідальності, очікує щедра винагорода.\n\nВостаннє Арнака бачили на скелях Темнохмарного верхів'я. Принесіть докази його смерті спостерігачу скель Довгорогому на заставу Розкутого Вітру, щоб отримати винагороду.", [3] = "Вбийте Арнака Зловісного Тотема та принесіть доказ його смерті спостерігачу скель Довгорогому на заставу Розкутого Вітру.", [4] = "Чи є у тебе новини про цього вбивцю, Арнака Зловісного Тотема?", [5] = "Хах! Добре, це прекрасні новини! Я вже почав перейматися через те, що він уникне правосуддя!\n\nОсь, {ім'я}... і дякую. Звістки про злочини Арнака змушували мою кров кипіти від люті!", ["en"] = "Wanted - Arnak Grimtotem", ["tasks"] = { ["Arnak's Hoof"] = "копито Арнака", ["Arnak's Hoof (Provided)"] = "копито Арнака (видано)" } },
    [515] = { [1] = "Еліксир агонії", [2] = "Суміш Брудномордих? Просто геніально! Як я сам до цього не додумався?\n\nДозволь мені внести своє зілля тління в це диявольське вариво.\n\nДля того, щоб активувати отруйні речовини в суміші Брудномордих, Лідону знадобиться міцне зілля крові троля, а також трохи луски клинкоспинних наг і очі мурлоків Розірваного Плавника з південного узбережжя Гіллзбраду. Він знає, що робити, коли ти збереш йому всі складові. Ох, як же мені не терпиться дізнатися про результати його експерименту!", [3] = "Принесіть розчин Брудномордих, міцне зілля крові троля, 5 лусок клинкоспинних наг і 5 очей мурлоків Розірваного Плавника аптекарю Лідону в Тарренський Млин.", [4] = "Я радий, що ти {стать:повернувся:повернулася}, {ім'я}. Я тут страшенно нудьгував. Жодних розваг, окрім отруєння Умпі та її реанімації... знову і знову, і знову, і знову.\n\nЯк пройшла подорож до Підмістя? Тобі пощастило вбити якихось людей по дорозі?", [5] = "Від хвилювання перед цим експериментом у мене паморочиться в голові! Ти мені дуже {стать:допоміг:допомогла}, {ім'я}. Разом ми поширимо смерть і хвороби по цій землі!", ["en"] = "Elixir of Agony", ["tasks"] = { ["Daggerspine Scale"] = "луска клинкоспинної наги", ["Daggerspine Scale (Provided)"] = "луска клинкоспинної наги (видано)", ["Mudsnout Mixture"] = "розчин Брудномордих", ["Mudsnout Mixture (Provided)"] = "розчин Брудномордих (видано)", ["Strong Troll's Blood Potion"] = "міцне зілля крові троля", ["Strong Troll's Blood Potion (Provided)"] = "міцне зілля крові троля (видано)", ["Torn Fin Eye"] = "око мурлока Розірваного Плавника", ["Torn Fin Eye (Provided)"] = "око мурлока Розірваного Плавника (видано)" } },
    [5151] = { [1] = "Гіперконденсатор", [2] = "Я єдиний, хто залишився живим після нападу кентаврів на наш караван! Кремезна пантера охороняє мій найкращий пристрій, який як раз висить на її шиї. Хах! Навіть кентаври тремтять в присутності цього лютого звіра!\n\nОсь ключ від клітки. Вони забрали все, але лишили ключ. Вбий звіра та принеси назад мій гіперконденсатор, і я нагороджу тебе!\n\nРозбитий караван знаходиться на північ звідси.", [3] = "Вбийте звіра, принесіть гіперконденсатор та ключ від клітки пантери Візло Блископідшипнику.", [4] = "Ти {стать:приніс:принесла} мій гіперконденсатор?", [5] = "Мій гіперконденсатор! Це займе мене на деякий час, доки я розберуся, що він робить...", ["en"] = "Hypercapacitor Gizmo", ["tasks"] = { ["Hypercapacitor Gizmo"] = "гіперконденсатор", ["Hypercapacitor Gizmo (Provided)"] = "гіперконденсатор (видано)", ["Panther Cage Key"] = "ключ від клітки пантери", ["Panther Cage Key (Provided)"] = "ключ від клітки пантери (видано)" } },
    [516] = { [1] = "Згуба Берена", [2] = "Я отримав звіт про те, що група невмерлих зачаїлася та готується до нападу на нас. Озброївшись цією інформацією, ми можемо помінятися ролями й атакувати їх першими, зруйнувавши їхній маленький план ще у зародку.\n\nНа жаль, у моїй інформації є прогалини, у кращому випадку. Кажуть, що вони ховаються десь у місцевості, відомій як Згуба Берена. Точне місцезнаходження невідоме, але, схоже, це печера у пагорбах, поблизу ділянки, зайнятої чарівниками Даларана.\n\nЯ довіряю твоїй винахідливості. Знайди їх і знищ.", [3] = "Знайдіть Згубу Берена та вбийте 6 чорноробів Воронокігтя та 6 вартових Воронокігтя, після чого поверніться до жерця тіні Аллістера у Крипту.", [4] = "Ти вже {стать:знайшов:знайшла} їхню базу, {ім'я}? Не гай часу!", [5] = "Якщо наші розвідники й агенти продовжуватимуть здобувати таку цінну інформацію, як ця, ми дуже швидко позбавимо наші землі від Скари Короля-ліча.", ["en"] = "Beren's Peril", ["tasks"] = { ["Ravenclaw Drudger"] = "чорнороб Воронокігтя", ["Ravenclaw Drudger slain"] = "чорнороб Воронокігтя: убито", ["Ravenclaw Guardian"] = "вартовий Воронокігтя", ["Ravenclaw Guardian slain"] = "вартовий Воронокігтя: убито" } },
    [517] = { [1] = "Еліксир агонії", [2] = "Новий еліксир нарешті готовий до випробувань. Але навіщо витрачати такий чудовий, заразний засіб на жабу чи собаку? Розважмось по-справжньому в ім'я Леді Сильвани!\n\nПрямуй до Дун-Ґарока. Це казарми, де живуть ці бридкі маленькі дворфи. Вкради мені барильце \"Землекопського міцного\". Як тільки я отримаю барильце, ми з тобою влаштуємо справжню вечірку, {ім'я}.", [3] = "Принесіть барильце \"Землекопського міцного\" аптекарю Лідону в Тарренський Млин.", [4] = "Іноді мені так нудно тут, у Тарренському Млині, що я відкриваю банку з формальдегідом і вдихаю його чудовий аромат. Умпі від цього трохи нервує.\n\nТо тобі вдалося дістати барильце у дворфів? Присягаюся, якщо мені доведеться дивитися на цей смертоносний еліксир без змоги використати його на комусь ще хоч один день, я закричу.", [5] = "Нарешті! Тепер ми готові діяти!", ["en"] = "Elixir of Agony", ["tasks"] = { ["Keg of Shindigger Stout"] = "барильце \"Землекопського міцного\"", ["Keg of Shindigger Stout (Provided)"] = "барильце \"Землекопського міцного\" (видано)" } },
    [518] = { [1] = "Корона Волі", [2] = "Муґ'Тол і його скелеламські огри захопили руїни Альтерака. Важко буде завдати йому серйозного покарання, не прорідивши ряди огрів.\n\nА вже потім ми продовжимо.\n\nЗрозуміло? Чудово. Тепер іди.", [3] = "Вбийте 14 скелеламських молотобоїв для Мелісари в Тарренському Млині.", [4] = "Я бачу, що твоє завдання ще не виконано, {ім'я}. Мені повідомити Шарліндру про твою непридатність?", [5] = "Сніг червоніє від крові огрів, але ми не припинимо наших зусиль, доки не втопчемо дух і тіла Селаламів в бруд і сніг.", ["en"] = "The Crown of Will", ["tasks"] = { ["Crushridge Mauler"] = "скелеламський молотобій", ["Crushridge Mauler slain"] = "скелеламський молотобій: убито" } },
    [519] = { [1] = "Корона Волі", [2] = "Тарґ, Брудень та Ґломмус — лейтенанти Муґ'Тола. Вони віддані йому, хоча хто може сказати, що спонукає огра до вірності.\n\nПринеси мені їхні голови, {ім'я}, і тоді все, що залишиться — це відрубати голову Муґ'Тола разом із короною.", [3] = "Вбийте Тарґа, Макрейка та Ґломмуса і принесіть їхні голови Мелісарі в Тарренський Млин.", [4] = "Мені потрібні їхні голови, {ім'я}, а не виправдання.", [5] = "...а я думала, що від огрів і так неприємно пахне.\n\nКоли ти принесеш мені голову Муґ'Тола, я накажу насадити всі чотири голови на піки над Альтераком. Гідний пам'ятник тим, хто йде проти волі Темної Леді.", ["en"] = "The Crown of Will", ["tasks"] = { ["Glommus's Head"] = "голова Ґломмуса", ["Glommus's Head (Provided)"] = "голова Ґломмуса (видано)", ["Muckrake's Head"] = "голова Брудня", ["Muckrake's Head (Provided)"] = "голова Брудня (видано)", ["Targ's Head"] = "голова Тарґа", ["Targ's Head (Provided)"] = "голова Тарґа (видано)" } },
    [520] = { [1] = "Корона Волі", [2] = "Тепер, коли лейтенанти Муґ'Тола мертві, все, що залишилося — вбити його самого і повернути корону Волі. Не сумніваюся, що він не захоче з нею розлучатися. Швидше за все, він чекає на тебе, враховуючи... зникнення... його товаришів.\n\nЗнайди Муґ'Тола і принеси мені його голову разом із короною. Опору Скелаламів буде покладено край.", [3] = "Вбийте Муґ'Тола і принесіть його голову з короною Волі Мелісарі в Тарренський Млин.", [4] = "Три голови у мене, а четвертої поки що не видно. Це буде або голова Муґ'Тола, або твоя, {ім'я}. Це я обіцяю.", [5] = "Ти добре {стать:виконав:виконала} свій обов'язок, {ім'я}. Голова Муґ'Тола прикрасить найвищу вершину руїн Альтерака, а Смертестражі зітруть рештки Скелеламів з лиця землі.", ["en"] = "The Crown of Will", ["tasks"] = { ["Crown of Will"] = "корона Волі", ["Crown of Will (Provided)"] = "корона Волі (видано)", ["Mug'thol's Head"] = "голова Муґ'Тола", ["Mug'thol's Head (Provided)"] = "голова Муґ'Тола (видано)" } },
    [521] = { [1] = "Корона Волі", [2] = "Залишилося лише віднести корону Волі до Шарліндри у Підмістя. Вона простежить, щоб її передали леді Сильвані. Я б застерегла тебе від думки скористатися нею в особистих цілях, {ім'я}. Нехай доля Муґ'Тола послужить тобі уроком.", [3] = "Передайте корону Волі Шарліндрі з Підмістя.", [4] = "Так? Ти маєш щось повідомити?", [5] = "Отже, це і є та реліквія, яку огр використовував, щоб ухилитися від волі Темної Леді...\n\nДивно, що щось таке просте могло володіти такою великою силою. І потрапити в такі незграбні руки. Молодець, {ім'я}, я передам корону леді Сильвані й доповім їй про твої подвиги.", ["en"] = "The Crown of Will", ["tasks"] = { ["Crown of Will"] = "корона Волі", ["Crown of Will (Provided)"] = "корона Волі (видано)" } },
    [5228] = { [1] = "Котли Скари", [2] = "В межах колишнього Лордерона є вісім котлів — чотири з них знаходяться на заході, і ще чотири — на сході. Ці котли випускають в повітря отруйні випари, розповсюджуючи чуму по всій землі.\n\nНекромантія Кел'Тузада надто сильна, щоб просто взяти та погасити вогонь під цими котлами, але, можливо, ми зможемо використати ці котли на нашу користь. Поговори з моєю помічницею, жрицею тіні Вандіс, вона допоможе тобі з цим завданням.", [3] = "Поговоріть з жрицею тіні Вандіс на Валу, в Західних Зачумлених землях.", [5] = "Тіні вітають тебе, {стать:брате:сестро} {клас:к}. Я допоможу тобі розібратися з котлами Скари.\n\nНаша ціль — це змінити складові отрути в котлах, щоб ця суміш стала смертельною для Скари. Для цього доведеться взяти зразки зі всіх чотирьох котлів в Західних Зачумлених землях.\n\nНастав час тобі завдати удару по Скарі, {стать:герою:героїне}.", ["en"] = "The Scourge Cauldrons" },
    [5229] = { [1] = "Ціль: Сквернокам'яне поле", [2] = "З чотирьох котлів Західних Зачумлених земель, найлегше буде отримати доступ до котла на Сквернокам'яному полі. Там розташовані менш досвідчені війська Скари, але не варто їх недооцінювати.\n\nВідправляйся до Сквернокам'яного поля, на схід звідси та на північний захід від Андорала, та розберися з тамтешнім хранителем котла. У нього має бути ключ, який надасть доступ до котла. Коли отримаєш доступ до котла, збери зразки отрути в цю пляшку. Вони знадобляться нам, щоб створити протидіючі речовини.", [3] = "Відправляйтеся до Сквернокам'яного поля в Західних Зачумлених землях, вбийте хранителя котла та використайте його ключ, щоб отримати доступ до котла. Вам знадобиться порожня пляшка для зразків зі Сквернокам'яного поля, щоб взяти зразок отрути з котла.", [4] = "Панель доступу до котла надійно зачинена. Щоб відкрити її, вам потрібно знайти ключ.", [5] = "Ключ хранителя котла Жовчерота ідеально підходить до замка панелі й одразу зникає. Схоже, що тепер панель можна відкрити без ключа. Зсередини долинає неприємний сморід — в котлі вариться суміш невідомих речовин.\n\nЗбоку є невеликий кран, під який ідеально поміщається пляшка. Тепер ви можете зібрати зразки для жриці тіні Вандіс на Валу.", ["en"] = "Target: Felstone Field", ["tasks"] = { ["Empty Felstone Field Bottle"] = "порожня пляшка для зразків зі Сквернокам'яного поля", ["Empty Felstone Field Bottle (Provided)"] = "порожня пляшка для зразків зі Сквернокам'яного поля (видано)", ["Felstone Field Cauldron Key"] = "ключ від котла Сквернокам'яного поля", ["Felstone Field Cauldron Key (Provided)"] = "ключ від котла Сквернокам'яного поля (видано)" } },
    [5230] = { [1] = "Повернення до Валу", [2] = "Ви наповнюєте пляшку достатньою кількістю отруйної суміші з котла для подальшого дослідження.\n\nОтримавши отруту, настав час повертатися до жриці тіні Вандіс на Вал.", [3] = "Принесіть пляшку зразків зі Сквернокам'яного поля жриці тіні Вандіс на Вал, що в Західних Зачумлених землях.", [4] = "З поверненням до Валу, {ім'я}. Як твої справи з котлами?", [5] = "Молодець, {ім'я}. Аптекар Дітерс миттю проведе дослідження та знайде протидіючу речовину, яку можна додати в котел. Якщо ми зможемо викачати достатньо цієї суміші в повітря, ми послабимо Скару в цьому місці.\n\nЦе буде непросте завдання — нам доведеться постійно влаштовувати набіги на котли та додавати в них наші реагенти. Та все ж якщо ми будемо продовжувати у тому ж дусі, у нас буде значна перевага проти Скари у вирішальній битві!", ["en"] = "Return to the Bulwark", ["tasks"] = { ["Filled Felstone Field Bottle"] = "пляшка зразків зі Сквернокам'яного поля", ["Filled Felstone Field Bottle (Provided)"] = "пляшка зразків зі Сквернокам'яного поля (видано)" } },
    [5231] = { [1] = "Ціль: Сльози Дальсона", [2] = "Один з котлів розташований на полі колишньої ферми, нині відомої як Сльози Дальсона. Але сьогодні ми не литимемо сльози, оскільки ми нападемо на Скару та отримаємо доступ до цих котлів!\n\nВідправляйся до Сліз Дальсона, на північ від Андорала, та вбий хранителя котла. У нього має бути ключ, як і минулого разу, що надасть тобі доступ до котла. Скористайся цією пляшкою, щоб зібрати зразки — у кожному котлі варяться різні отрути.", [3] = "Відправляйтеся до Сліз Дальсона в Західних Зачумлених землях, вбийте хранителя котла та використайте його ключ, щоб отримати доступ до котла. Вам знадобиться порожня пляшка для зразків зі Сліз Дальсона, щоб взяти зразок отрути з котла.", [4] = "Панель доступу до котла надійно зачинена. Щоб відкрити її, вам потрібно знайти ключ.", [5] = "Скелетний ключ хранителя котла легко проковзує в замок та одразу зникає, надаючи вам постійний доступ до котла. Огидна, густа суміш тече переплетеними трубками в основі котла.\n\nЗбоку є невеликий кран, під який ідеально поміщається пляшка. Тепер ви можете зібрати зразки для жриці тіні Вандіс на Валу.", ["en"] = "Target: Dalson's Tears", ["tasks"] = { ["Dalson's Tears Cauldron Key"] = "ключ від котла Сліз Дальсона", ["Dalson's Tears Cauldron Key (Provided)"] = "ключ від котла Сліз Дальсона (видано)", ["Empty Dalson's Tears Bottle"] = "порожня пляшка для зразків зі Сліз Дальсона", ["Empty Dalson's Tears Bottle (Provided)"] = "порожня пляшка для зразків зі Сліз Дальсона (видано)" } },
    [5232] = { [1] = "Повернення до Валу", [2] = "Ви наповнюєте пляшку достатньою кількістю густої суміші з котла для подальшого дослідження.\n\nОтримавши отруту, настав час повертатися до жриці тіні Вандіс на Вал.", [3] = "Принесіть пляшку зразків зі Сліз Дальсона жриці тіні Вандіс на Вал, що в Західних Зачумлених землях.", [4] = "Ми знаємо, що в кожному котлі варяться різні суміші, що поширюють чуму. Також нам відомо, що ми маємо розробити протиотрути для кожного котла. Цей зразок зі Сліз Дальсона допоможе нам визначити речовини, необхідні для тамтешнього котла.", [5] = "О, нам буде що досліджувати. Молодець, {ім'я}!\n\nНаразі, наступний крок в наших руках. Нам потрібно скласти список реагентів, які, разом з сумішшю в котлі, викличуть зворотний ефект.\n\nДля цього доведеться помістити їх прямо у котел. Аптекар Дітерс знає набагато більше про це, тож поговори з ним якомога швидше.", ["en"] = "Return to the Bulwark", ["tasks"] = { ["Filled Dalson's Tears Bottle"] = "пляшка зразків зі Сліз Дальсона", ["Filled Dalson's Tears Bottle (Provided)"] = "пляшка зразків зі Сліз Дальсона (видано)" } },
    [5233] = { [1] = "Ціль: Кручений Привид", [2] = "Тобі вдалося відкрити вже два котли й тепер ти маєш необмежений доступ до них, але залишається іще два. Якщо ми впораємося з ними, це дозволить нам успішно ввести протидійні речовини!\n\nЦього разу твоя ціль — котел Крученого Привида. Він знаходиться на схід від Андорала, неподалік від зруйнованих стін міста. Тобі знову доведеться вбити хранителя котла, щоб забрати в нього ключ. Наповни цю пляшку зразками з котла.\n\nВдалого полювання, {ім'я}!", [3] = "Відправляйтеся до Крученого Привида в Західних Зачумлених землях, вбийте хранителя котла та використайте його ключ, щоб отримати доступ до котла. Вам знадобиться порожня пляшка для зразків з Крученого Привида, щоб взяти зразок отрути з котла.", [4] = "Панель доступу до котла надійно зачинена. Щоб відкрити її, вам потрібно знайти ключ.", [5] = "Ключ хранителя котла відкриває доступ до панелі, а потім зникає, як і попередні ключі. Рідина всередині бурлить та смердить чимось гнилим.\n\nЗбоку є невеликий кран, під який ідеально поміщається пляшка. Тепер ви можете зібрати зразки для жриці тіні Вандіс на Валу.", ["en"] = "Target: Writhing Haunt", ["tasks"] = { ["Empty Writhing Haunt Bottle"] = "порожня пляшка для зразків з Крученого Привида", ["Empty Writhing Haunt Bottle (Provided)"] = "порожня пляшка для зразків з Крученого Привида (видано)", ["Writhing Haunt Cauldron Key"] = "ключ від котла Крученого Привида", ["Writhing Haunt Cauldron Key (Provided)"] = "ключ від котла Крученого Привида (видано)" } },
    [5234] = { [1] = "Повернення до Валу", [2] = "Ви обережно наповнюєте порожню пляшку. Зразок мерзенної рідини, що бурлить у котлі, переливається всередині скляної посудини.\n\nОтримавши отруту, настав час повертатися до жриці тіні Вандіс на Вал.", [3] = "Принесіть пляшку зразків з Примарної Ферми жриці тіні Вандіс на Вал, що в Західних Зачумлених землях.", [4] = "Коли ми успішно проаналізуємо зразок з котла Крученого Привида, у нас з'явиться третій спосіб завдати нищівної шкоди Скарі!", [5] = "Іще одне чудово виконане завдання, {ім'я}! Тепер ми зможемо скористатися цими котлами проти самої Скари. Якби влада Кел'Туазада не була такою сильною, я б сказала, що ми можемо повністю нейтралізувати їх!\n\nАптекар Дітерс незабаром повідомить, що потрібно додати до цього та інших котлів, щоб впоратися з чумою. Отже, настав час отримати доступ до останнього із західних котлів!", ["en"] = "Return to the Bulwark", ["tasks"] = { ["Filled Writhing Haunt Bottle"] = "пляшка зразків з Крученого Привида", ["Filled Writhing Haunt Bottle (Provided)"] = "пляшка зразків з Крученого Привида (видано)" } },
    [5235] = { [1] = "Ціль: Посуха Ґаррона", [2] = "Останній котел розташований на фермі під назвою Посуха Ґаррона. Він охороняється кількома посіпаками Скари — якщо точніше, примарами та привидами. З ними не варто жартувати, {ім'я}.\n\nПосуха Ґаррона знаходиться на сході від Валу, ближче до Східних Зачумлених земель. Знову ж таки, вбий хранителя котла, у нього є ключ. Ось твоя порожня пляшка для зразків. Принеси мені її наповненою. Нехай тінь оберігає тебе на цьому небезпечному завданні, {клас:к}.", [3] = "Відправляйтеся до Посухи Ґаррона в Західних Зачумлених землях, вбийте хранителя котла та використайте його ключ, щоб отримати доступ до котла. Вам знадобиться порожня пляшка для зразків з Посухи Ґаррона, щоб взяти зразок отрути з котла.", [4] = "Панель доступу до котла надійно зачинена. Щоб відкрити її, вам потрібно знайти ключ.", [5] = "Ключ від хранителя котла Душегніва зникає, щойно торкається панелі котла. Всередині чується легкий стукіт, панель відчиняється та дає доступ до в'язкої отрути, що вариться в котлі.\n\nЗбоку є невеликий кран, під який ідеально поміщається пляшка. Тепер ви можете зібрати зразки для жриці тіні Вандіс на Валу.", ["en"] = "Target: Gahrron's Withering", ["tasks"] = { ["Empty Gahrron's Withering Bottle"] = "порожня пляшка для зразків з Посухи Ґаррона", ["Empty Gahrron's Withering Bottle (Provided)"] = "порожня пляшка для зразків з Посухи Ґаррона (видано)", ["Gahrron's Withering Cauldron Key"] = "ключ від котла Посухи Ґаррона", ["Gahrron's Withering Cauldron Key (Provided)"] = "ключ від котла Посухи Ґаррона (видано)" } },
    [5236] = { [1] = "Повернення до Валу", [2] = "Ви обережно закриваєте кран на панелі керування, спостерігаючи, як краплі варева з котла стікають у порожню пляшку.\n\nОтримавши отруту, настав час повертатися до жриці тіні Вандіс на Вал.", [3] = "Принесіть пляшку зразків з Посухи Ґаррона жриці тіні Вандіс на Вал, що в Західних Зачумлених землях.", [4] = "На Посусі Ґаррона знаходиться останній з західних котлів, до якого у нас ще немає доступу. Отримавши зразки зілля з цього котла, ми зможемо додати наші реагенти до всіх котлів! Скара не зможе захистити їх від нас, навіть з силою Кел'Тузада.", [5] = "Вітаю, {ім'я}, тобі вдалося отримати доступ до останнього котла! Аптекар Дітерс скоро дізнається, які реагенти необхідно додати до нього.\n\nЩодо тебе, я впевнена, що верховний каратель Деррінґтон захоче особисто подякувати тобі за твою допомогу. Без тебе наша боротьба проти Скари була б приречена. Дякую тобі, {стать:герою:героїне}.", ["en"] = "Return to the Bulwark", ["tasks"] = { ["Filled Gahrron's Withering Bottle"] = "пляшка зразків з Посухи Ґаррона", ["Filled Gahrron's Withering Bottle (Provided)"] = "пляшка зразків з Посухи Ґаррона (видано)" } },
    [5238] = { [1] = "Місію виконано!", [5] = "{ім'я}, твоя успішна диверсія котлів — це величезна перемога для нас!\n\n<Верховний каратель відкашлюється й гучно кричить.>\n\nПочуйте всі! За вірну службу відреченим та Орді, за виконання обов'язку перед обличчям непереборних труднощів і неймовірної небезпеки — я вручаю {ім'я} цю винагороду та висловлюю {стать:йому:їй} вічну вдячність, як {стать:справжньому герою:справжній героїні} Орди. Ура!", ["en"] = "Mission Accomplished!" },
    [524] = { [1] = "Еліксир агонії", [2] = "Поруч смертестражі тримають кількох полонених фермерів. Верховна карателька Дарталія підозрює, що серед них переховується один з військових стратегів Штормовія. Вочевидь, його знайшли мертвим у Зачумлених землях минулої ночі. Дарталія завжди піклується про мене і вирішила залишити полонених у моєму розпорядженні.\n\nГадаю, настав час влаштувати цим фермерам вечірку. Ох, повеселимося!\n\nПостав це зіпсоване барильце на килим у їхній кімнаті. Всім по чумному пиву!", [3] = "Поставте зіпсоване барильце на килимок біля полонених фермерів.", [4] = "Від килима йде затхлий запах.", [5] = "Ви ставите зіпсоване барильце на вкритий пилом килим.", ["en"] = "Elixir of Agony", ["tasks"] = { ["Tainted Keg"] = "зіпсоване барильце", ["Tainted Keg (Provided)"] = "зіпсоване барильце (видано)" } },
    [527] = { [1] = "Битва за Гіллзбрад", [2] = "Звертаючись до мене, стань струнко, {клас:к}.\n\nЯ перебуваю під прямим командуванням Варіматраса. Ми повинні придушити людську навалу, поки наші аптекарі працюють над новою чумою.\n\nЗа нашими відомостями місто Гіллзбрад вразливе для нападу. Твоє перше завдання — вивести з ладу їхні запаси продовольства та інфраструктуру.\n\nВирушай на захід. Влаштуй набіг на найпівнічніші ферми Гіллзбрадських полів. Переконайся, що землевласники, фермер Рей і фермер Ґетц, також будуть страчені.", [3] = "Вбийте 6 гіллзбрадських робітників, 6 гіллзбрадських фермерів, фермера Рея та фермера Ґетца і поверніться до Дарталії в Тарренський Млин.", [4] = "Я верховний каратель Тарренського Млину, під прямим командуванням Варіматраса і Темної Леді, тож ти {стать:зобов'язаний:зобов'язана} виконувати мої накази.\n\nЧи може ти легковажно ставишся до війни з Альянсом? Якщо це так, то я повинна відрубати тобі голову тут і зараз. Якщо ж ні — вирушай на захід, до міста Гіллзбрад, і бийся з людьми, як наказано.\n\nВільно.", [5] = "Вільно, {клас:к}. Бачу, ти {стать:повернувся:повернулася} з битви. Мої джерела стверджують, що ти добре {стать:проявив:проявила} себе на Гіллзбрадському фронті.", ["en"] = "Battle of Hillsbrad", ["tasks"] = { ["Farmer Getz"] = "фермер Ґетц", ["Farmer Getz slain"] = "фермер Ґетц: убито", ["Farmer Ray"] = "фермер Рей", ["Farmer Ray slain"] = "фермер Рей: убито", ["Hillsbrad Farmer"] = "гіллзбрадський фермер", ["Hillsbrad Farmer slain"] = "гіллзбрадський фермер: убито", ["Hillsbrad Farmhand"] = "гіллзбрадський робітник", ["Hillsbrad Farmhand slain"] = "гіллзбрадський робітник: убито" } },
    [528] = { [1] = "Битва за Гіллзбрад", [2] = "Звістка про напад на північні ферми викликала паніку у містян. Це дуже добре.\n\nНаші Смертолови повідомляють, що селяни тікають на поля в південному Гіллзбраді. Дурні думають, що зможуть врятуватися від загибелі в садах.\n\nДоведи, що вони помиляються, {ім'я}. Повертайся на поля Гіллзбраду і шукай селян, що втікають. Знищуй їх в ім'я нашої Темної Леді.\n\nВільно!", [3] = "Вбийте 15 гіллзбрадських селян і поверніться до Дарталії в Тарренський Млин.", [4] = "Ти {стать:отримав:отримала} наказ, {клас:к}. Досить байдикувати у Тарренському Млині коли в тебе є завдання.", [5] = "Смерть стискає лещата навколо Гіллзбрада. Битва йде добре.", ["en"] = "Battle of Hillsbrad", ["tasks"] = { ["Hillsbrad Peasant"] = "гіллзбрадський селянин", ["Hillsbrad Peasant slain"] = "гіллзбрадський селянин: убито" } },
    [529] = { [1] = "Битва за Гіллзбрад", [2] = "Жителі Гіллзбраду чинять несподіваний опір. Проблема полягає в тому, що мешканців міста озброює місцевий коваль. Нам потрібно перекрити всі лінії постачання.\n\nТвоїм завданням буде стратити коваля Веррінґтана. Вбий також його учнів. І заодно принеси партію заліза з їхніх запасів. Вони стануть у пригоді, коли ми закінчимо завоювання Гіллзбраду і почнемо спустошувати Південнобережжя.", [3] = "Вбийте коваля Веррінґтана та 4 гіллзбрадських учнів коваля.\n\nЗаберіть партію заліза і поверніться до Дарталії в Тарренський Млин.", [4] = "Ти {стать:виконав:виконала} накази, {клас:к}? Ти {стать:позбувся:позбулася} Веррінґтана і його учнів? І де вантаж заліза?", [5] = "Завдання виконано, {клас:к}. І, варто зауважити, дуже майстерно.", ["en"] = "Battle of Hillsbrad", ["tasks"] = { ["Blacksmith Verringtan"] = "Коваль Веррінгтан", ["Blacksmith Verringtan (Provided)"] = "Коваль Веррінгтан (видано)", ["Blacksmith Verringtan slain"] = "коваль Веррінґтан: убито", ["Hillsbrad Apprentice Blacksmith"] = "гіллзбрадський учень коваля", ["Hillsbrad Apprentice Blacksmith slain"] = "гіллзбрадський учень коваля: убито", ["Shipment of Iron"] = "партія заліза", ["Shipment of Iron (Provided)"] = "партія заліза (видано)" } },
    [530] = { [1] = "Помста чоловіка", [2] = "Валдред був колись моїм добрим другом, а став вбивцею моєї дружини. I, хоча я не здатен горювати, я все ж прагну помсти. Якщо вб'єш Валдреда та принесеш мені його прокляті руки, то я тебе винагороджу.\n\nВостаннє я чув, що він був біля стіни Сивогрива на півдні Срібнохвою, намагаючись втекти в королівство Ґілнеас.", [3] = "Вбийте Валдреда Морея.\n\nПринесіть його руки Ралею Андреану в Підмістя.", [4] = "Ти {стать:приніс:принесла} його руки, {ім'я}?", [5] = "Ах, чудово. Ці руки вбили мою дружину, Делію. Помста за її вбивство була моєю єдиною турботою, і ти {стать:був:була} інструментом цієї помсти.\n\nОсь, візьми кільце, яке ти {стать:повернув:повернула} раніше. Делія померла для мене так давно, що її обручка - то дрібничка, яка мені більше не потрібна. Натомість я залишу собі ці руки на пам'ять про зраду свого друга.", ["en"] = "A Husband's Revenge", ["tasks"] = { ["Valdred's Hands"] = "руки Валдреда", ["Valdred's Hands (Provided)"] = "руки Валдреда (видано)" } },
    [532] = { [1] = "Битва за Гіллзбрад", [2] = "Гіллзбрад у повному хаосі, і ми віримо, що він незабаром впаде. Однак ми повинні залишатися безжалісними, поки людські покидьки не будуть стерті з передгір'я назавжди.\n\nПопри величезні втрати, люди продовжують боротися і підтримують свого лідера. Ми повинні ліквідувати їхнього ватажка, війта Шкваростіна, а разом з ним і міську раду. Знищити їх священний політичний документ — прокламацію Гіллзбраду. А також викрасти міський реєстр.", [3] = "Вбийте війта Шкваростіна та 5 гіллзбрадських радників. Знищте прокламацію Гіллзбраду. Викрадіть реєстр Гіллзбраду. Після цього поверніться до Дарталії у Тарренський Млин.", [4] = "Які у тебе новини?", [5] = "Звістка про твої успіхи в Гіллзбраді розлетілася досить швидко. Ти відмінно {стать:попрацював:попрацювала}, {клас:к}.", ["en"] = "Battle of Hillsbrad", ["tasks"] = { ["Hillsbrad Councilman"] = "гіллзбрадський радник", ["Hillsbrad Councilman slain"] = "гіллзбрадський радник: убито", ["Hillsbrad Proclamation destroyed"] = "прокламацію Гіллзбраду знищено", ["Hillsbrad Town Registry"] = "реєстр Гіллзбраду", ["Hillsbrad Town Registry (Provided)"] = "реєстр Гіллзбраду (видано)", ["Magistrate Burnside"] = "війт Шкваростін", ["Magistrate Burnside slain"] = "війт Шкваростін: убито" } },
    [533] = { [1] = "Проникнення", [2] = "Нарешті до нас починають доходити чутки та навіть відомості про місцеперебування Ґол'діра. Люди постійно змінювали місця його ув'язнення, але ми змогли звузити сферу пошуку до великого табору Синдикату на північ звідси.", [3] = "Отримайте інформацію про місцеперебування Ґол'діра для Краска в Тарренському Млині.", [4] = "Ну як, вдалося що-небудь дізнатися? Боюся, перспективи Ґол'діра погіршуються з кожним днем...", [5] = "Нарешті ми знаємо, де утримують Ґол'діра. Табір, про який йде мова, знаходиться недалеко звідси. Будемо сподіватися, що вони не будуть так добре підготовлені, як тоді, коли нас застали зненацька.", ["en"] = "Infiltration", ["tasks"] = { ["Syndicate Missive"] = "послання Синдикату", ["Syndicate Missive (Provided)"] = "послання Синдикату (видано)" } },
    [5341] = { [1] = "Статки родини Барових", [2] = "У Некроситеті зберігаються статки родини Барових. Я, Алексій Баров, один з двох останніх спадкоємців роду Барових. Другий — це мій брат Велдон.\n\nЦей жалюгідний боягуз втік, коли почалась війна, щоб зберегти своє нікчемне людське життя.\n\nТепер він шукає документи, щоб забрати весь спадок собі. Знайди їх раніше за мого брата і я зроблю тебе неймовірно {стать:багатим:багатою}!", [3] = "Відправляйтеся до Некроситету і поверніть скарби родини Барових. Вони складаються з чотирьох документів: на Тверджу Дарроу, на Брілль, на Тарренський Млин і на Південнобережжя. Поверніться до Алексія Барова коли виконаєте завдання.", [4] = "Схили голову переді мною, {раса:к}. Я, зрештою, вельможа, а ти — {стать:простак:простачка} без копійчини в кишені.", [5] = "Чудова робота, {раса:к}. Тепер потрібно захистити мій спадок...", ["en"] = "Barov Family Fortune", ["tasks"] = { ["The Deed to Brill"] = "документи на Брілль", ["The Deed to Brill (Provided)"] = "документи на Брілль (видано)", ["The Deed to Caer Darrow"] = "документи на Тверджу Дарроу", ["The Deed to Caer Darrow (Provided)"] = "документи на Тверджу Дарроу (видано)", ["The Deed to Southshore"] = "документи на Південнобережжя", ["The Deed to Southshore (Provided)"] = "документи на Південнобережжя (видано)", ["The Deed to Tarren Mill"] = "документи на Тарренський Млин", ["The Deed to Tarren Mill (Provided)"] = "документи на Тарренський Млин (видано)" } },
    [5342] = { [1] = "Останній Баров", [2] = "Звичайно, поки мій брат залишається в живих, з розділом спадщини можуть виникнути певні проблеми. Цього не має трапитися.\n\nЯ сподіваюся, що {стать:такий:така} волоцюга, як ти, не відмовиться від невеличкого холодного вбивства.\n\nЦе легке завдання, і я вірю, що ти його виконаєш. Ти ж хочеш отримати нагороду.\n\nВелдон сидить під захистом Альянсу в таборі Студовій, на сході. Вбий його та принеси мені його голову.\n\n<Алексі позіхає>\n\nНу ж бо, хутчіш!", [3] = "Відправляйтеся до табору Студовій — територію Альянсу — та вбийте Велдона Барова. Заберіть його голову та поверніться до Алексія Барова.\n\nБудьте обережні, Велдона охоронятимуть покидьки Альянсу.", [4] = "Захисти мої статки, і отримаєш свою частину.", [5] = "Чудово! Тепер тільки сила та багатство роду Барових в моїх руках!\n\n<Алексі жбурляє в вас великий мішок.>\n\nРешту залиш собі, тварюко.", ["en"] = "The Last Barov", ["tasks"] = { ["Head of Weldon Barov"] = "голова Велдона Барова", ["Head of Weldon Barov (Provided)"] = "голова Велдона Барова (видано)" } },
    [535] = { [1] = "Валік", [2] = "У-у-у-ух… поранений, вмираю й оточений ворогом.\n\nЗвісно, ти все одно мене вб'єш, але якщо принесеш мені \"Південнобережне міцне\" — ваша братія його п'є, чи не так? — я розповім тобі те, що ти хочеш знати.", [3] = "Принесіть кухоль \"Південнобережного міцного\" Валіку в табір Синдикату.", [4] = "Ти {стать:приніс:принесла} мені щось випити чи {стать:прийшов:прийшла} завершити діло?", [5] = "Враховуючи мою неминучу смерть, гадаю, можу з чистою совістю сказати, що це — найсолодший на смак трунок у світі... Ось, візьми це, мені, мертвому, воно ні до чого.\n\nЩо ж, покінчімо з цим!", ["en"] = "Valik", ["tasks"] = { ["Southshore Stout"] = "південнобережне міцне", ["Southshore Stout (Provided)"] = "південнобережне міцне (видано)" } },
    [5361] = { [1] = "Родинне дерево", [2] = "Мій брат Натака знаходиться на заставі Блукаючих Привидів в Спустошищі. Я хотів би попросити тебе... чи не {стать:міг би:могла б} ти передати йому цей звіт? Минув рік з того часу, як я востаннє писав, і ось зараз кентаври знову щось затівають. Мій брат має дізнатися про це.\n\nПрямуй в Каміннопазуристі гори, на захід від Перехрестя, а потім прямуй на захід, в Обвуглену долину. Спустошище знаходиться на південь від долини. Йди дорогою на південь і побачиш заставу Блукаючих Привидів.", [3] = "Доставте звіт спостерігача скель Довгорогого до Натаки Довгорогого на заставу Блукаючих Привидів, що в Спустошищі.", [4] = "Які в тебе новини, {клас:к}? Повідомлення від мого брата, кажеш? Ну тоді давай сюди цей звіт!", [5] = "Я не знаю, що тебе пов'язує з моїм братом, але схоже, що він довіряє тобі, {клас:к}.\n\nЯ, Натака Довгорогий, вітаю тебе на заставі Блукаючих Привидів. {Клас:н} нам тут точно не завадить! Поговори з іншими, можливо ти комусь знадобишся.", ["en"] = "Family Tree", ["tasks"] = { ["Cliffwatcher Longhorn Report"] = "звіт спостерігача скель Довгорогого", ["Cliffwatcher Longhorn Report (Provided)"] = "звіт спостерігача скель Довгорогого (видано)" } },
    [5381] = { [1] = "Рука Ірукзуса", [2] = "До рук Палаючого Леза попала демонічна скриня. В ній зберігається могутній артефакт — рука Ірукзуса. Орки Палаючого Леза використовують її для відкриття демонічних порталів в руїнах Маннорок. Ми маємо зупинити вторгнення демонів у наш світ, {ім'я}!\n\nРозколи червоний кристал у фортеці Грозової Сокири цією демонічною киркою, щоб отримати демонічну скриню.", [3] = "Дістаньте демонічну скриню з фортеці Грозової Сокири та віднесіть її разом з демонічною киркою Тайзі Мудрій Гриві у селище Тінездобич.", [4] = "{ім'я}, ти {стать:дістав:дістала} демонічну скриню?", [5] = "О так, демонічна скриня. Дай її мені, {клас:к}, я відкрию її... і покажу тобі руку Ірукзуса.", ["en"] = "Hand of Iruxos", ["tasks"] = { ["Demon Box"] = "демонічна скриня", ["Demon Box (Provided)"] = "демонічна скриня (видано)", ["Demon Pick"] = "демонічна кирка", ["Demon Pick (Provided)"] = "демонічна кирка (видано)" } },
    [5386] = { [1] = "Гарний улов", [2] = "Тут, на заставі Блукаючих Привидів, вже давно не було чути запаху смаженої риби. Тролі з Селища Тінездобич — чудові рибалки... але, на жаль, через цих кентаврів я ніяк не можу знайти час, щоб завітати до тролів. Хм...\n\nЗроби мені послугу і вирушай до селища Тінездобич. Поговори з місцевим рибалкою Джінар'Зілленом і привези мені мою улюблену рибу — кровочеревку. Дорога на південь звідси приведе тебе до селища тролів.", [3] = "Поговоріть з Джінар'Зілленом у селищі Тінездобич, а потім принесіть Натаці Довгорогому 2 кровочеревки.", [4] = "У мене вже слина тече від нетерпіння, коли думаю про смажену кровочеревку... Ти щось {стать:приніс:принесла}?", [5] = "Ти {стать:мій рятівник:моя рятівниця}, {ім'я}! А ця кровочеревка виглядає так добре, що хоч сирою їж її.\n\n<Натака ковтає слину.>\n\nОсь — візьми щось з цього, як оплату за рибу.", ["en"] = "Catch of the Day", ["tasks"] = { ["Bloodbelly Fish"] = "кровочеревка", ["Bloodbelly Fish (Provided)"] = "кровочеревка (видано)" } },
    [539] = { [1] = "Битва за Гіллзбрад", [2] = "У реєстрі Гіллзбраду зазначено, що Лазурова копальня перебуває під контролем Альянсу. Крім того, шахта є основним джерелом залізної руди для арсеналів Альянсу.\n\nПопри те, що ми завдали вирішального удару по Гіллзбраду, Альянс усе ще підтримує і захищає Лазурову копальню.\n\nШахта знаходиться на південь від Гіллзбрада. Відправляйся туди та вбий десятника, людину на ім'я Бондс. Також вбий його шахтарів. Це стане гарним уроком для Альянсу.", [3] = "Вбийте десятника Бондса та 10 гіллзбрадських шахтарів, після чого поверніться до Дарталії в Тарренський Млин.", [4] = "Ти {стать:отримав:отримала} наказ напасти на Лазурову копальню. У тебе мають бути вагомі причини для байдикування на Тарренському Млині, інакше я відрубаю тобі голову за зраду.", [5] = "Темна Леді буде задоволена, коли дізнається, що у неї з'явилася нова копальня, завдяки якій вона може озброїти своїх солдатів.", ["en"] = "Battle of Hillsbrad", ["tasks"] = { ["Foreman Bonds"] = "десятник Бондс", ["Foreman Bonds slain"] = "десятник Бондс: убито", ["Hillsbrad Miner"] = "гіллзбрадський шахтар", ["Hillsbrad Miner slain"] = "гіллзбрадський шахтар: убито" } },
    [5405] = { [1] = "Жетон Сріблястого Світанку", [5] = "Усі, хто бореться зі злом від імені Сріблястого Світанку, повинні отримати наш жетон. Він дасть право отримувати нагороди від наших квартирмейстерів.\n\nДоки ти носитимеш його, ти зможеш збирати камені Скари з вбитих прибічників Скари, які вони носять як знаки розрізнення. Збирай ці знаки та принось мені. За кожний набір ти отримаєш знак доблесті Сріблястого Світанку.\n\nПрямуй назустріч долі, {клас:к} — приєднуйся до боротьби зі злом!", ["en"] = "Argent Dawn Commission" },
    [5406] = { [1] = "Камені осквернителів Скари", [4] = "Камінь осквернителя Скари — це відзнака володарів Скари. Вона є у кожної істоти, що має владу над Скарою. Вбивство таких істот служить благу Сріблястого Світанку... та узагалі загальному благу!\n\nВід імені Сріблястого Світанку, я дам тобі знак доблесті за кожну з цих відзнак. Тільки будь {стать:обережним:обережною}, {ім'я} — з такими могутніми істотами не варто жартувати.", [5] = "Вітаю, {ім'я} — я радий нагородити тебе жетоном доблесті Сріблястого Світанку!\n\nЗдобуття жетона доблесті в такий спосіб свідчить про те, що ти є {стать:справжнім поборником:справжньою поборницею} добра. Ми цінуємо всі зусилля, спрямовані на боротьбу зі Скарою, але знищити одного з їхніх лідерів — значить завдати їм нищівної поразки!\n\nЗа Світанок, {стать:брате мій:сестро моя}!", ["en"] = "Corruptor's Scourgestones", ["tasks"] = { ["Corruptor's Scourgestone"] = "камінь осквернителя Скари", ["Corruptor's Scourgestone (Provided)"] = "камінь осквернителя Скари (видано)" } },
    [5407] = { [1] = "Камені загарбників Скари", [4] = "Камені загарбників Скари — знак відзнаки серед елітних солдатів Скари. Ці камені можна знайти у сильних солдатів, які знаходяться в Зачумлених землях. Вбивство такої істоти — ще те випробування, але воно має бути пройденим заради знищення зла.\n\nСріблястий Світанок пропонує знак доблесті в обмін на 10 таких відзнак. Принеси їх мені, і я подбаю про те, щоб ти {стать:отримав:отримала} гідну винагороду.", [5] = "Вітаю, {ім'я}. Я з радістю вручаю тобі знак доблесті Сріблястого Світанку!\n\nКожен знак доблесті, вручений гідним одержувачам, наближає час перемоги над Скарою. Дедалі більше героїв борються проти Скари на її власних землях, і Сріблястий Світанок, без сумніву, буде в перших рядах, коли прийде час останньої битви проти зла Скари. Я сподіваюся, що доблесть, яку ти {стать:показав:показала} для одержання цього знака, теж допоможе нам того дня.", ["en"] = "Invader's Scourgestones", ["tasks"] = { ["Invader's Scourgestone"] = "камінь загарбника Скари", ["Invader's Scourgestone (Provided)"] = "камінь загарбника Скари (видано)" } },
    [5408] = { [1] = "Камені посіпак Скари", [4] = "Камені посіпак Скари — знак відзнаки рядових солдатів Скари. Ці камені можна знайти у слабших солдатів, які знаходяться в Зачумлених землях, хоча поняття \"слабших\" не дуже доречне. Скару, які б це створіння не були, не варто недооцінювати.\n\nСріблястий Світанок пропонує знак доблесті в обмін на 20 таких відзнак — обмін, який я з радістю зроблю, за умови, що ти збереш достатню кількість каменів Скари!", [5] = "Вітаю, {ім'я}. Я з радістю вручаю тобі знак доблесті Сріблястого Світанку!\n\nЦі знаки слугують двом цілям. По-перше — вони дають змогу зміцнити твої позиції серед Сріблястого Світанку. Завдяки цьому тобі стануть доступні нові можливості та винагороди, які ми бережемо для найвідданіших союзників. Друга — їх можна віддати квартирмейстерам для плати за цінні предмети Світанку.\n\nЩо б ти не {стать:вирішив:вирішила}, знай, що ти на них заслуговуєш. Молодець!", ["en"] = "Minion's Scourgestones", ["tasks"] = { ["Minion's Scourgestone"] = "камінь посіпаки Скари", ["Minion's Scourgestone (Provided)"] = "камінь посіпаки Скари (видано)" } },
    [541] = { [1] = "Битва за Гіллзбрад", [2] = "Дворфи допомагають людям? Будь прокляті ці брудні маленькі тварюки.\n\nМи перевіримо на міцність так званий Альянс. Побачимо, як ці маленькі розбишаки поспішатимуть на допомогу людям, коли відчують наш гнів. Ми точно знаємо, де знаходиться їхній опорний пункт.\n\nВони облаштували казарму на південному сході Гіллсбраду, вздовж стіни Торадіна, під назвою Дун-Ґарок. Останнє завдання цієї битви — взяти в облогу Дун-Ґарок, {клас:к}. Капітан Залізопагорб, їхній ватажок, має загинути.", [3] = "Відправляйтесь в Дун-Ґарок і вбийте 10 горян, 8 стрільців, 4 жерців і капітана Залізопагорба, а потім поверніться до Дарталії в Тарренський Млин.", [4] = "Дун-Ґарок тобі не по зубах, {клас:к}? А я думала, що ти {стать:довів:довела} свою доблесть у Гіллзбраді.\n\nЯкщо ти не впораєшся з цим завданням, я знайду когось іншого, хто зможе досягти кращих результатів. Що ж до тебе, то я впевнена, що Темній Леді не завадять нові гробокопачі у Тірісфальському переліссі.", [5] = "Твої дії на полі бою заслуговують на найвищу відзнаку.", ["en"] = "Battle of Hillsbrad", ["tasks"] = { ["Captain Ironhill"] = "капітан Залізопагорб", ["Captain Ironhill slain"] = "капітан Залізопагорб: убито", ["Dun Garok Mountaineer"] = "дун-ґароцький горянин", ["Dun Garok Mountaineer slain"] = "дун-ґароцький горянин: убито", ["Dun Garok Priest"] = "дун-ґароцький жрець", ["Dun Garok Priest slain"] = "дун-ґароцький жрець: убито", ["Dun Garok Rifleman"] = "дун-ґароцький стрілець", ["Dun Garok Rifleman slain"] = "дун-ґароцький стрілець: убито" } },
    [5421] = { [1] = "Рибка у відрі", [2] = "Я винагороджу кожного, хто хоч трохи полегшить моє життя... Чим менше я роблю, тим лучче, {стать:друже:подруго}!\n\nУ селищі Тінездобич, під доками, я розставив пастки на молюсків. Якщо ти будеш настільки {стать:люб'язний:люб'язною}, що зробиш мою роботу і збереш молюсків для мене, то я подарю тобі те, шо ти захочеш... розумієш, про шо я, ге?", [3] = "Джінар'Зіллен просить вас зібрати 5 молюсків з пасток поблизу селища Тінездобич.", [4] = "Я винагороджу кожного, хто хоч трохи полегшить моє життя... Чим менше я роблю, тим лучче, {стать:друже:подруго}!\n\nУ селищі Тінездобич, під доками, я розставив пастки на молюсків. Якщо ти будеш настільки {стать:люб'язний:люб'язною}, що зробиш мою роботу і збереш молюсків для мене, то я подарю тобі те, шо ти захочеш... розумієш, про шо я, ге? За кожні п'ять молюсків, які ти мені принесеш, я дам тобі чудову кровочеревку!", [5] = "{стать:Друже:Подруго}, немає нічого кращого за гарно виконану роботу, особливо, якщо її робить хтось інший... еге ж?", ["en"] = "Fish in a Bucket", ["tasks"] = { ["Shellfish"] = "молюск", ["Shellfish (Provided)"] = "молюск (видано)" } },
    [544] = { [1] = "Вторгнення до в'язниці", [2] = "Я приїхав до Тарренського Млина, щоб провести дослідження, але зараз мушу вирішити кризову ситуацію. Бачиш, четверо відречених втекли з Підмістя кілька місяців тому. Вони зрадили своїх побратимів, але що ще гірше... вони обікрали Темну Леді.\n\nЦі злодії вдерлися до захищеного сховища і викрали чотири артефакти — предмети, необхідні нашим аптекарям для певних досліджень. Сильвана жадає повернути ці артефакти.\n\nЗлодії втекли з Підмістя до Даларану, і тамтешні чарівники помістили їх у Лордамерський ізоляційний табір.", [3] = "Знайдіть зрадників і заберіть їхні артефакти, а потім поверніться до чаклуна Пустогляда в Тарренський Млин.", [4] = "Тобі вдалося знайти злодіїв? І, що важливіше, чи вдалося повернути те, що вони вкрали?", [5] = "Ти {стать:зробив:зробила} велику послугу для відречених, {ім'я}. Цих артефактів нам дуже бракувало.\n\nПриємно чути, що Кеґан та інші зрадники отримали по заслузі.", ["en"] = "Prison Break In", ["tasks"] = { ["Bloodstone Marble"] = "кулька з кривавого каменю", ["Bloodstone Marble (Provided)"] = "кулька з кривавого каменю (видано)", ["Bloodstone Oval"] = "овал з кривавого каменю", ["Bloodstone Oval (Provided)"] = "овал з кривавого каменю (видано)", ["Bloodstone Shard"] = "осколок з кривавого каменю", ["Bloodstone Shard (Provided)"] = "осколок з кривавого каменю (видано)", ["Bloodstone Wedge"] = "клин з кривавого каменю", ["Bloodstone Wedge (Provided)"] = "клин з кривавого каменю (видано)" } },
    [5441] = { [1] = "Ліниві наймити", [2] = "Прокляті наймити! Вони тяжко працюють, збираючи деревину по долині, але також постійно дрихнуть! Мені потрібен хтось, хто б допоміг з їх дисципліною.\n\nТи виглядаєш як {стать:той:та} {раса:н}, {стать:який:яка} {стать:потрібен:потрібна} для цього завдання. Ось, візьми цей кийок і використай його на наймитах, які сплять на роботі. Хороший ляпас одразу налаштує їх! Повернеш кийок, коли закінчиш.\n\nВшиві ліниві наймити...", [3] = "Використайте кийок десятника на лінивих наймитах, коли ті сплять. Розбудіть 5 наймитів, потім поверніть кийок десятнику Тазз'рілу в долину Випробувань.", [4] = "В ледачості нічого хорошого…\n\nЕ? Мій кийок у тебе? Ти {стать:спіймав:спіймала} когось, хто спить на роботі?!", [5] = "Добре, добре. Можливо, наступного разу вони подумають двічі, перш ніж розслаблятись! Дякую за допомогу!", ["en"] = "Lazy Peons", ["tasks"] = { ["Foreman's Blackjack"] = "кийок десятника", ["Foreman's Blackjack (Provided)"] = "кийок десятника (видано)", ["Peons Awoken"] = "Пробуджені пеони", ["Peons Awoken (Provided)"] = "Пробуджені пеони (видано)", ["Peons Awoken slain"] = "Пробуджені пеони: убито" } },
    [545] = { [1] = "Даларанські патрулі", [2] = "Чарівники Даларана побудували величезний магічний купол навколо серця свого міста. Дехто вважає, що це було зроблено для захисту від небезпек, тоді як інші кажуть, що вони просто хотіли усамітнитися, щоб вчитися і будувати плани.\n\nМені особисто байдуже, якою була причина. Мене цікавлять руїни на околицях їхнього міста, за межами купола, де можуть ховатися цінні магічні скарби.\n\nАле цю територію патрулюють чаклуни та їхні елементалі-невільники.\n\nТож напади на них і повернись, коли суттєво скоротиш їхню кількість.", [3] = "Вбийте 6 даларанських закликачів і 12 елементалів-невільників, а потім поверніться до чаклуна Пустогляда в Тарренський Млин.", [4] = "Ти вже {стать:зменшив:зменшила} кількість даларанських патрулів в руїнах?", [5] = "Дуже добре. Тепер ці руїни мають бути достатньо безпечними для пошуків, але треба бути обережними.\n\nСпасибі тобі, {ім'я}.", ["en"] = "Dalaran Patrols", ["tasks"] = { ["Dalaran Summoner"] = "даларанський закликач", ["Dalaran Summoner slain"] = "даларанський закликач: убито", ["Elemental Slave"] = "елементаль-невільник", ["Elemental Slave slain"] = "елементаль-невільник: убито" } },
    [546] = { [1] = "Сувеніри смерті", [2] = "Я чув, що тебе завербувала Дарталія для війни проти людей Гіллзбраду. Я так тобі заздрю...\n\nПоки ти розважаєшся — вбиваєш людей, грабуєш місто, тероризуєш невинних людей, — я стирчу тут, на варті Тарренського Млина.\n\nМожливо, ти зглянешся над старим смертестражем? Бачиш, я збираю людські черепи, а тобі доведеться вбити чимало людей. Збери під час битви 30 черепів, принеси мені, і я тобі добре заплачу.", [3] = "Смертестраж Самса з Тарренського Млина просить вас принести 30 людських черепів з Гіллзбраду.", [4] = "А от і {ім'я}! Скільки людей ти сьогодні {стать:вбив:вбила}? Сотні, напевно!\n\nМаєш черепи для мене?", [5] = "Чудові черепи! Такі гарні! Ось твоя плата, як я й обіцяв, {ім'я}!", ["en"] = "Souvenirs of Death", ["tasks"] = { ["Hillsbrad Human Skull"] = "людський череп з Гіллзбраду", ["Hillsbrad Human Skull (Provided)"] = "людський череп з Гіллзбраду (видано)" } },
    [547] = { [1] = "Меч Гумберта", [2] = "Верховна карателька Дарталія послала мене наглядати за Дун-Ґароком. Я розбив табір подалі від дворфів. Але коли настав ранок і мені потрібно було закип'ятити воду, я пішов збирати дрова.\n\nПовернувшись, я виявив, що мої речі зникли.\n\nОчевидно, якісь дворфи-розвідники з Дун-Ґарока проходили повз і вкрали їх. Мені потрібен мій меч! Якщо ти зможеш його повернути, я буду дуже вдячний. Там так багато дворфів... буде досить важко знайти маленького брудного злодія, який його вкрав.", [3] = "Заберіть меч смертестража Гумберта з Дун-Ґарока та поверніть його йому в Тарренський Млин.", [4] = "Ти {стать:зміг:змогла} дістати мій меч, {ім'я}? Верховна карателька Дарталія повісить мене на кроквах, якщо дізнається про мою дурість.", [5] = "Ти {стать:знайшов:знайшла} його!\n\nАх, як приємно знову відчувати в руці мій дорогоцінний меч. Дуже дякую тобі!", ["en"] = "Humbert's Sword", ["tasks"] = { ["Humbert's Sword"] = "меч Гумберта", ["Humbert's Sword (Provided)"] = "меч Гумберта (видано)" } },
    [5481] = { [1] = "Завдання Ґордо", [2] = "Хазяїнові потрібні бур'яни. Ми мати великі руки, погано збирати. Ти помогти нам, ми тебе не чіпати. Нам треба бур'ян мороку. Багато з них рости біля дороги і десь тута.\n\nКоли ти мати достатньо бур'яну, ти нести його хазяїну Голланду на кладовище у Бріллі.", [3] = "3беріть 3 бур'яни мороку та віднесіть їх молодшому аптекареві Голланду на Брілльське кладовище.", [4] = "Де ця бездарна погань? Або в тебе є те, що мені потрібно, або краще забирайся звідси та знайди його.", [5] = "Що це? Бур'ян мороку?! Мені не потрібен бур'яну мороку! Ця тупа гора м'яса збирає там маргаритки та переконує інших, Леді знає скількох, йолопів, як ти, робити те ж саме. Не ображайся.\n\nПринаймні, ти вже тут, і це те, що мені потрібно. Оскільки я не збираюся знову пробувати та щось втовкмачити тій потворі, може, ти збереш те, що мені потрібно насправді - бур'ян приречення!", ["en"] = "Gordo's Task", ["tasks"] = { ["Gloom Weed"] = "бур'ян мороку", ["Gloom Weed (Provided)"] = "бур'ян мороку (видано)" } },
    [5482] = { [1] = "Бур'ян приречення", [2] = "Як бачиш, я у скрутному становищі, {Ім'я}. Та штука там збирає не ті трави! Я добре оплачу твій час, якщо ти збереш те, що мені потрібно. Принеси мені достатньо бур'яну приречення, і я тебе достойно нагороджу.\n\nНаскільки я розумію, їм подобається отруювати флору біля кладовища, що північніше Брілля. Поспіши та остерігайся місцевих гнолів.", [3] = "Позбирайте 10 бур'янів приречення і принесіть їх молодшому аптекареві Голланду.", [4] = "Сподіваюся, ти з чимось хорошим. Уже маєш усі потрібні мені бур'яни приречення?", [5] = "О, мої бур'яни приречення. Чудово!\n\n<Молодший аптекар Голланд жадібно потирає руки.>\n\nЦе стане в нагоді. Ти чудово {стать:послужив:послужила} мен.., е-е-е, Леді, {Ім'я}. Як і обіцяно, ось твоя заслужена винагорода.", ["en"] = "Doom Weed", ["tasks"] = { ["Doom Weed"] = "бур'ян приречення", ["Doom Weed (Provided)"] = "бур'ян приречення (видано)" } },
    [549] = { [1] = "РОЗШУКУЮТЬСЯ: прихильники Синдикату", [2] = "За наказом леді Сильвани всі члени організації, відомої під назвою Синдикат, засуджені до смерті. Ті, кого затримають або візьмуть у полон, будуть страчені без суду і слідства. Наразі відомо, що вони збираються в руїнах замку Дарнгольд, на південний схід від Тарренського Млину.\n\nВсім, хто надасть докази їхніх діянь верховній карательці Дарталії, пропонується щедра винагорода.", [3] = "Вбийте 10 пройдисвітів Синдикату та 10 вартових Синдикату. Поверніться до верховної карательки Дарталії в Тарренський Млин за нагородою.", [4] = "Ти не маєш нічого кращого, ніж стояти тут переді мною, {клас:к}? У мене, як у верховної карательки, є важливіші справи, ніж витріщатися на твою гнилувату пику.", [5] = "Чудово, {клас:к}. З такою швидкістю шкідники із Синдикату будуть винищені в найкоротші терміни.", ["en"] = "WANTED: Syndicate Personnel", ["tasks"] = { ["Syndicate Rogue"] = "пройдисвіт Синдикату", ["Syndicate Rogue slain"] = "пройдисвіт Синдикату: убито", ["Syndicate Watchman"] = "вартовий Синдикату", ["Syndicate Watchman slain"] = "вартовий Синдикату: убито" } },
    [550] = { [1] = "Битва за Гіллзбрад", [2] = "Оскільки ти {стать:бився:билася} з неабиякою відвагою та завзяттям у Гіллзбраді, я написала цю грамоту, вихваляючи твої героїчні подвиги, щоб вище командування їх визнало.\n\nВіднеси цю запечатану грамоту Варіматрасу в Підмістя. Йди з гордістю, {клас:к}.", [3] = "Віднесіть запечатану грамоту Дарталії до Варіматраса в Підмістя.", [4] = "Що привело {клас:з} з поля бою аж до Підмістя?", [5] = "То ти {стать:той самий славнозвісний:та сама славнозвісна} {клас:н}, що {стать:завдав:завдала} вирішального удару по військах Альянсу в передгір'ї Гіллзбраду? Чутки про твої славетні подвиги швидко долетіли до Підмістя.\n\nУ тебе велике майбутнє в лавах бійців Темної Леді, якщо ти й надалі проявлятимеш таку відданість в бою.\n\nХоча наша головна загроза — армія Короля-ліча, що наступає з півночі, людська \"проблема\" продовжує перешкоджати нашим планам. Однак, ти {стать:показав:показала}, що люди можуть і будуть програвати.", ["en"] = "Battle of Hillsbrad", ["tasks"] = { ["Darthalia's Sealed Commendation"] = "запечатана грамота Дарталії", ["Darthalia's Sealed Commendation (Provided)"] = "запечатана грамота Дарталії (видано)" } },
    [5502] = { [1] = "Опікун Орди", [2] = "Ти {стать:був:була} дуже {стать:добрим:доброю} до мене, {ім'я}. Я й уявити не міг, що дитячий тиждень буде таким веселим. Дякую. Я не хочу засмучуватися через власну долю — мої батьки завжди казали мені, що я маю переборювати всі нещастя. Знаєш, коли я виросту, я хочу стати героєм... як ти.\n\nЯк це не сумно, та мені пора додому. Давай повернемося, і я розповім нашій опікунці, наскільки ти {стать:класний:класна}!", [3] = "Поверніть свого підопічного до притулку Орґріммара, передавши свисток орка-сироти опікунці сиротинця Зойку Битви в долині Честі.", [4] = "Приємно знову бачити тебе, {ім'я}. Ти {стать:виконав:виконала} всі обов'язки, на які ти добровільно {стать:погодився:погодилася} під час дитячого тижня?", [5] = "Хай духи благословлять тебе, {ім'я}. Ти {стать:зробив:зробила} більше для Ґранта, ніж багато хто зумів би зробити для нього. Дякую тобі — ти втілення того, що значить бути {стать:героєм:героїнею} Орди.\n\nБудь ласка, якщо у тебе буде час — заходь до нас у гості. Ґрант хотів би цього не менше за мене.\n\nЙому було так весело з тобою, {ім'я}. Ґрант хотів подарувати тобі одного зі своїх улюбленців, щоб ти завжди {стать:згадував:згадувала} його.", ["en"] = "A Warden of the Horde", ["tasks"] = { ["Orcish Orphan Whistle"] = "свисток орка-сироти", ["Orcish Orphan Whistle (Provided)"] = "свисток орка-сироти (видано)" } },
    [5504] = { [1] = "Покриви Світанку", [2] = "Твоє служіння Сріблястому Світанку варте похвали, {ім'я}. Ти справді {стать:шанований:шанована} серед нас. Мені доручено надати тобі доступ до придбання однієї з найцінніших речей Світанку — покриву захисту від магії.\n\nПрикріплення такого покриву до наплічників посилить опір до одного з п'яти видів магії. На знак відданості нашій справі, я попрошу тебе принести 10 знаків доблесті в обмін на доступ до цих покривів.", [3] = "Принесіть 10 знаків доблесті Сріблястого Світанку квартирмейстеру Гасані на Вал, що в Західних Зачумлених землях.", [4] = "О, {стать:благородний:благородна} {клас:к}! Ти {стать:приніс:принесла} знаки доблесті? Як тільки ти мені їх принесеш, у тебе буде доступ до придбання наших покривів.", [5] = "Приголомшливо — твій внесок Світанку відзначений належним чином, {ім'я}. Оскільки ти {стать:виконав:виконала} завдання, я з радістю надаю тобі доступ до придбання наших покривів. Якщо ти й надалі підтримуватимеш ставлення нашого ордену до тебе, ти зможеш купити ці покриви у будь-яких квартирмейстерів Сріблястого Світанку.\n\nЗа Світанок, {стать:брате мій:сестро моя}!", ["en"] = "Mantles of the Dawn", ["tasks"] = { ["21000 reputation with Argent Dawn"] = "21000 репутації у Сріблястого Світанку", ["Argent Dawn Valor Token"] = "знак доблесті Сріблястого Світанку", ["Argent Dawn Valor Token (Provided)"] = "знак доблесті Сріблястого Світанку (видано)" } },
    [5511] = { [1] = "Ключ до Некроситету", [4] = "Що ж, тримай, {ім'я}, — завершений скелетний ключ. Я впевнений, що він дозволить тобі потрапити до Некроситету. Є лиш один спосіб це перевірити. Не гай часу, перевір!", [5] = "Що ж, тримай, {ім'я}, — завершений скелетний ключ. Я впевнений, що він дозволить тобі потрапити до Некроситету. Є лиш один спосіб це перевірити. Не гай часу, перевір!\n\nЗичу удачі, {стать:могутній герою:могутня героїне}. Нехай твої перемоги продовжують приносити тобі силу та славу, коли ти спустошиш Некроситет!", ["en"] = "The Key to Scholomance" },
    [5514] = { [1] = "Ціна форми", [2] = "Гобліна, з яким тобі потрібно поговорити, звати Крінкл Файносталь. Він працює в Пристроблясі, що в пустелі Танаріс. Йому під силу зробити потрібну нам форму, але це обійдеться недешево. Ми просимо тебе не скупитися та заплатити стільки, скільки він попросить.\n\nЯ аптекар, а не банкір. Якби в мене була купа золота, мене б тут не було.\n\nЗдається, я знову бовкнув щось зайве. Упс.\n\nПристроблях чекає на тебе! Удачі!", [3] = "Принесіть загартовані фрагменти скелетів та 15 золотих монет Крінклу Файносталі в Пристроблях.", [4] = "Так, я знаю хто ти {стать:такий:така}, і я знаю, чому ти тут. Дітерс надіслав мені звістку про тебе. Перейдімо до справи?\n\nУ мене є форма, яку ти можеш використати для відливання скелетного ключа, але це коштуватиме тобі 15 золотих. Гроші вперед і ніяких торгів. Я покладу у форму фрагменти скелетів і покажу, як відлити ключ без знань ковальства... і все це безплатно!\n\nХай не кажуть, що я за мідяк вдавлюсь.", [5] = "Дітерс казав, що ти принесеш усе необхідне, і так воно і є! Угода є угода, дай-но я складу фрагменти скелетів у форму.\n\nНевже Дітерс їх укріпив? Прекрасно... Інакше тобі довелося б повертатись назад, до Валу.", ["en"] = "Mold Rhymes With...", ["tasks"] = { ["Imbued Skeletal Fragments"] = "загартовані фрагменти скелетів", ["Imbued Skeletal Fragments (Provided)"] = "загартовані фрагменти скелетів (видано)" } },
    [552] = { [1] = "Помста Гелькулара", [2] = "Майстер Гелькулар майже завершив своє перетворення на ліча, коли розлючений натовп знайшов його ритуальне лігво на пагорбах і жорстоко вбив його. Що ще гірше, вони поховали його на кладовищі Південнобережжя.\n\nТака неповага до великого чарівника неприпустима. Як його учень, я хочу помститися Південнобережжю.\n\nАле спершу нам потрібен жезл Гелькулара. Його ритуальне лігво захопили єті. Жезл має бути в одного з них.", [3] = "Заберіть жезл Гелькулара у єті та поверніть його послушнику Тайванду в Тарренський Млин.", [4] = "Ти вже {стать:знайшов:знайшла} жезл Гелькулара? Там так багато єті, що знайти його буде непросто. Але нам без нього не обійтися.", [5] = "Ти {стать:знайшов:знайшла} його! Неймовірно, {ім'я}!", ["en"] = "Helcular's Revenge", ["tasks"] = { ["Helcular's Rod"] = "жезл Гелькулара", ["Helcular's Rod (Provided)"] = "жезл Гелькулара (видано)" } },
    [553] = { [1] = "Помста Гелькулара", [2] = "Ось, візьми жезл Гелькулара. Він тобі знадобиться.\n\nГелькулар створив 3 церемоніальних вогнища як частину свого наймогутнішого заклинання. Полум'я Азеля та полум'я Вераза знаходяться в печерах передгір'я. Полум'я Узеля знаходиться в печері вище, далі на північ у горах.\n\nЖезл Гелькулара повинен бути заряджений від кожного з трьох полум'їв. Після завершення ритуалу встроми жезл в могилу Гелькулара в Південнобережжі, місті людей на півдні, що ретельно охороняється. Ми помстимося!", [3] = "Зарядіть жезл Гелькулара силою полум'я Азеля, полум'я Вераза та полум'я Узеля.\n\nВіднесіть заряджений жезл до могили Гелькулара в Південнобережжя.", [4] = "Могила Гелькулара наповнена містичною енергією.", [5] = "З-під землі лунає сильний гуркіт.", ["en"] = "Helcular's Revenge", ["tasks"] = { ["Flame of Azel charged"] = "полум'я Азеля заряджено", ["Flame of Azel charged (Provided)"] = "полум'я Азеля заряджено (видано)", ["Flame of Azel charged slain"] = "полум'я Азеля заряджено: убито", ["Flame of Uzel charged"] = "полум'я Узеля заряджено", ["Flame of Uzel charged (Provided)"] = "полум'я Узеля заряджено (видано)", ["Flame of Uzel charged slain"] = "полум'я Узеля заряджено: убито", ["Flame of Veraz charged"] = "полум'я Вераза заряджено", ["Flame of Veraz charged (Provided)"] = "полум'я Вераза заряджено (видано)", ["Flame of Veraz charged slain"] = "полум'я Вераза заряджено: убито", ["Rod of Helcular"] = "жезл Гелькулара", ["Rod of Helcular (Provided)"] = "жезл Гелькулара (видано)" } },
    [556] = { [1] = "Кам'яні талісмани", [2] = "Чарівники Даларана славляться своїм зв'язком з елементалями — могутніми створіннями з інших вимірів, якими вони керують за допомогою магічних талісманів. Чаклун Пустогляд хотів би вивчити ці талісмани.\n\nВирушай на землі даларанських чаклунів, на захід від Гіллзбраду, і збери талісмани.\n\nТи можеш знайти талісмани у будь-якого жителя Даларана, але я раджу пошукати їх в ізоляційному таборі. Там набагато безпечніше, ніж у самому Даларані.", [3] = "Принесіть 10 потертих кам'яних талісманів хранителю Бел'варілу в Тарренський Млин.", [4] = "Чи є у тебе потерті кам'яні талісмани, {ім'я}? Чаклун прагне розкрити їхні таємниці.", [5] = "Чудові талісмани. Хоча, здається, їхня магія вже згасла. Та воно й на краще — нехай для початку чарівник поекспериментує проводилися на менш активних екземплярах, як ці.\n\nДякую, {ім'я}.", ["en"] = "Stone Tokens", ["tasks"] = { ["Worn Stone Token"] = "потертий кам'яний талісман", ["Worn Stone Token (Provided)"] = "потертий кам'яний талісман (видано)" } },
    [557] = { [1] = "Зв'язувальні браслети", [2] = "Чаклун буде зайнятий вивченням зібраних тобою кам'яних талісманів, але незабаром йому знадобляться зразки пов'язаних з ними предметів — зв'язувальних браслетів. Їх одягають на зап'ястя елементалів, щоб змусити їх виконувати волю мага.\n\nВбивай елементалів у руїнах Даларана і збирай їхні браслети зв'язування землі. Чаклун буде задоволений.", [3] = "Принесіть 4 зв'язувальні браслети землі хранителю Бел'варілу в Тарренський Млин.", [4] = "Привіт, {ім'я}. Елементалі — непрості супротивники, але я не сумніваюся, що ти впораєшся. Ти вже {стать:зібрав:зібрала} зв'язувальні браслети?", [5] = "Ти {стать:знайшов:знайшла} їх. Сподіваюся, елементалі, з яких ти {стать:зняв:зняла} ці браслети, не надто опиралися?\n\nХм... здається, смерть не тільки зупинила моє серце, але й позбавила мене почуття гумору.\n\nЩо ж, дякую тобі, {ім'я}. Ти добре служиш чаклуну, а отже і Темній Леді.", ["en"] = "Bracers of Binding", ["tasks"] = { ["Bracers of Earth Binding"] = "зв'язувальні браслети землі", ["Bracers of Earth Binding (Provided)"] = "зв'язувальні браслети землі (видано)" } },
    [5581] = { [1] = "Портали Легіону", [2] = "Дивись — це рука Ірукзуса. Воістину, жахливе видовище.\n\nЯкщо ти плануєш закрити демонічні портали на руїнах Маннорок — про що я тебе зараз і хочу попросити — вона має бути в тебе. Загроза з боку демонів зростає і ми повинні закрити ці портали, щоб ці істоти більше не мали доступу в цей світ. Щасти тобі, {ім'я}... і остерігайся вартових порталу.", [3] = "Закрийте 6 порталів на руїнах Маннорок, після чого поверніться до Тайги Мудрої Гриви в селище Тінездобич.", [4] = "Ти {стать:закрив:закрила} демонічні портали на руїнах Маннорок?", [5] = "Ти заслуговуєш похвали, {ім'я}. Завдяки твоєму вкладу в боротьбу з загрозою демонів, Азерот став безпечнішим.", ["en"] = "Portals of the Legion", ["tasks"] = { ["Hand of Iruxos"] = "рука Ірукзуса", ["Hand of Iruxos (Provided)"] = "рука Ірукзуса (видано)", ["Portals Banished"] = "Вигнані портали", ["Portals Banished (Provided)"] = "Вигнані портали (видано)", ["Portals Banished slain"] = "Вигнані портали: убито" } },
    [5642] = { [1] = "Тінестраж", [2] = "На тебе чекає щось важливе в Орґріммарі, {ім'я}.\n\nЗазвичай посланці, що приходять сюди у пошуках тролів-жерців, дуже неквапливі. Але цього разу, вони, здається, дуже поспішали. Не затримуйся надовго в Громовому Бескиді. Гадаю, тобі варто повернутися в долину Духів якомога швидше.", [3] = "Поговоріть з Ур'кьо в Орґріммарі.", [5] = "Скоро почнеться найважливіший обряд ініціації {клас:р}. Я поясню тобі більше — ти {стать:готовий:готова}.", ["en"] = "Shadowguard" },
    [5643] = { [1] = "Тінестраж", [2] = "Як і більшість наших жерців, твоє плем'я також проводить ритуали посвячення. Ці ритуали зазвичай навчають жерців особливих здібностей, життєво необхідних для виживання. Я відчуваю, що твій час теж настав. Ти маєш повернутися в долину Духів, що в Орґріммарі, та поговорити з Ур'кьо. Те, чого він тебе навчить, знадобиться тобі у майбутньому.", [3] = "Поговоріть з Ур'кьо в Орґріммарі.", [5] = "Скоро почнеться найважливіший обряд ініціації {клас:р}. Я поясню тобі більше — ти {стать:готовий:готова}.", ["en"] = "Shadowguard" },
    [5644] = { [1] = "Пожираюча чума", [2] = "Ах, який же це чудовий день для тебе, {ім'я}. Я бачу, що ти багато чого {стать:навчився:навчилась}, тож настав час тобі повернутися до Ельталісти. Є речі, яких тільки вона може навчити тебе, але тільки тоді, коли ти покажеш на що {стать:здатен:здатна}.\n\nНе буду псувати тобі сюрприз, та пам'ятаю себе іще молодим жерцем, коли я дізнався про справжню силу... божественну силу. Оце були часи.\n\nПовертайся до Ельталісти в Підмістя, {ім'я}. Вона чекатиме на тебе у кварталі Війни.", [3] = "Поговоріть з Ельталістою в Підмісті.", [5] = "Добре, ти {стать:повернувся:повернулася}, і не {стать:запізнився:запізнилася} ні на мить. Ми маємо обговорити дещо важливе, {ім'я}. Твої сили зростають і ми маємо впевнитися, що ти {стать:готовий:готова}.", ["en"] = "Devouring Plague" },
    [5646] = { [1] = "Пожираюча чума", [2] = "Ельталіста виявила велику повагу моєму народу, відправляючи моїх учнів до мене для подальшого тренування, а тепер я зроблю те саме для її племені.\n\nПовертайся до Підмістя, {ім'я}. Вона чекає на тебе у кварталі Війни, щоб розповісти більше про твій народ та його звичаї. Йди туди, не зволікай.", [3] = "Поговоріть з Ельталістою в Підмісті.", [5] = "Добре, ти {стать:повернувся:повернулася}, і не {стать:запізнився:запізнилася} ні на мить. Ми маємо обговорити дещо важливе, {ім'я}. Твої сили зростають і ми маємо впевнитися, що ти {стать:готовий:готова}.", ["en"] = "Devouring Plague" },
    [5648] = { [1] = "Вбрання духовності", [2] = "Ти {стать:готовий:готова} до свого першого випробування, {ім'я}. На південь від Колючого Пагорба, прямо за містом, одна з наших бугаїв поранилась, відбиваючись од праудмурських стариганів. Вона кепсько себе почуває, і їй би не завадила наша допомога. Найди її — її ім'я Кор'жа — вилікуй її рани та дай їй благословення наших предків.\n\nЗроби це, і я вважатиму, що ти {стать:готовий:готова} йти далі нашим шляхом.", [3] = "Знайдіть Кор'жу та вилікуйте її рани використовуючи Мале зцілення (ранг 2). Після цього надайте їй Слово сили: Стійкість та поверніться до Тай'джин в Колючий Пагорб.", [4] = "Багато хто думає, що магія лікування сильна, але мало хто розуміє, наскільки вона сильна. Ти можеш зберегти життя багатьом, замість того, щоб вони йшли до своїх предків. Ця цілюща магія разом зі стійкістю — дуже потужна комбінація заклинань. Пам'ятай це. Вона корисна для всіх — від воїнів до магів.", [5] = "Добре, значить, Кор'жа жива і може знову захищати наше місто від цих бісових людей. Я люблю згадувати дні битв, де сила проявлялася в бою, а мудрі знищували тих, хто покладався лише на свою силу.\n\nТи добре {стать:вчинив:вчинила}, {ім'я}. Візьми це вбрання. Можливо воно стане тобі в пригоді, а можливо тобі байдуже, проте ти {стать:заслужив:заслужила} його, і я пишаюся тим, що називаю тебе {стать:братом:сестрою}.", ["en"] = "Garments of Spirituality", ["tasks"] = { ["Heal and fortify Grunt Kor'ja"] = "Зцілити та зміцнити Грунта Кор'джу", ["Heal and fortify Grunt Kor'ja (Provided)"] = "Зцілити та зміцнити Грунта Кор'джу (видано)", ["Heal and fortify Grunt Kor'ja slain"] = "Зцілити та зміцнити Грунта Кор'джу: убито" } },
    [5649] = { [1] = "На славу духовності", [2] = "Наш народ приєднавсь до Орди, бо вони були добрі до нас. Вони вірні, вони навчають нас таких речей, як честь. Наші старі звичаї важко забуть. Можливо, орки не сприймають деякі з них, але це не заважає нам дотримуватися їх в таємниці від інших.\n\nТи знаєш це, тому я одправляю тебе до Тай'джин на Колючий Пагорб. Вона навчить тебе нашій історії. Вона навчить тебе звичаїв нашого племені. Йди до неї коли будеш {стать:готовий:готова}.", [3] = "Поговоріть з Тай'джин у Дуротарі.", [5] = "Ах... нарешті ти {стать:прийшов:прийшла} до Тай'джин. Це добре.\n\nТи вже розумієш, що ми вже не те плем'я, яке було раніше. Тепер ми набагато сильніші. Ми стали сильнішими, бо ми швидко пристосовуємось. Орда багато чому нас навчила. Ми більше не розгромлюєм ворогів, а потім набираємся сил — тепер ми набираємся сил, а потім розгромлюєм ворогів.\n\nРізниця незначна, але ти навчишся цьому. От побачиш. Плем'я розраховує на те, шо ти навчишся цих речей.", ["en"] = "In Favor of Spirituality" },
    [5650] = { [1] = "Вбрання темряви", [2] = "Наша черпаємо силу з темряви й тіні, {ім'я}, але це не єдина твоя роль. Ти {стать:зрозумів:зрозуміла}, що у лікувальному мистецтві теж є користь. Це мудро. Але перш ніж пізнати темряву, ти маєш пізнати світло. А для цього у мене є випробування для тебе.\n\nНа північ від кладовища знаходиться поранений смертестраж Кел. Він захищав нас від гнолів деякий час та потребує лікування. Ти також маєш укріпити його тіло перед тим, які він повернеться до виконання своїх обов'язків. Зроби це за допомогою своїх заклинань та повертайся до мене.", [3] = "Знайдіть смертестража Кела та зціліть його рани використовуючи Мале зцілення (Ранг 2). Після цього надайте йому Слово сили: Стійкість та поверніться до темного священника Берила в Брілль.", [4] = "Наші сили дають нам неймовірні можливості, {ім'я}. Так чи інакше ти зрозумієш, що наші здібності лікувати рани та зміцнювати союзників завжди будуть бажаними. Тільки не дай цьому відмовити тебе від інших шляхів, {клас:к} — ти можеш бути {стать:ефективним:ефективною} в багатьох напрямках. Але... якщо ти справді бажаєш нищити своїх ворогів магічною енергією, можливо, тобі більше сподобається темна магія.", [5] = "Ти з легкістю {стать:пройшов:пройшла} моє випробовування. Добре.\n\nСкоро, ти будеш {стать:готовим:готовою} взяти на себе ще одну відповідальність, і ця дорога поведе тебе до темніших сил — сил, які жодні жерці інших рас не мають.\n\nВізьми це вбрання на знак твого становища. Ти на це заслуговуєш. Якщо ти не хочеш одягати робу, тоді нехай так і буде, можеш робити з нею все, що забажаєш. Ми ніколи не забудемо чого ти {стать:досяг:досягла} в наших рядах.", ["en"] = "Garments of Darkness", ["tasks"] = { ["Heal and fortify Deathguard Kel"] = "Зціліть та зміцніть Кела, Вартового Смерті", ["Heal and fortify Deathguard Kel (Provided)"] = "Зціліть та зміцніть Кела, Вартового Смерті (видано)", ["Heal and fortify Deathguard Kel slain"] = "Зціліть та зміцніть Кела, Вартового Смерті: убито" } },
    [5651] = { [1] = "На славу темряви", [2] = "Відречені винесли багато уроків зі свого досвіду і зрозуміли речі, про які деякі раси тільки починають здогадуватися. І хоча наш шлях пролягає через темряву, ти зрозумієш, що багато величних речей залежать від неї не менше, ніж від світла. Ти навчишся використовувати й те, й інше... використовувати з розсудом. Але прислухайся до моїх слів: ніколи не забувай, що нас створили у гної та залишили гнити в купі трупів. Темрява — це наш дім.\n\nКоли будеш {стать:готовий:готова} дізнатися більше — знайди темного священника Берила у Бріллі.", [3] = "Поговоріть з темним священником Берилом у Тірісфальському переліссі.", [5] = "Нарешті, ти {стать:прибув:прибула}. Покладаючись лише на свою віру та силу волі, ти не зможеш пройти випробовування, {стать:юначе:дівчинко}. Відчуття невідкладності та трошки амбіцій допоможуть тобі.", ["en"] = "In Favor of Darkness" },
    [5652] = { [1] = "Зурочення слабкості", [2] = "Мене відправили сюди, щоб я переконався, що ти не блукаєш надто далеко від дому, {ім'я}. Мене відправили за тобою тому, що Ур'кьо, найкращий з наших жерців, хотіти поговорити з тобою. Йди до нього. Прямуй в долину Духів у місті орків та поговори з Ур'кьо. Він чекає тебе.", [3] = "Поговоріть з Ур'кьо в Орґріммарі.", [5] = "Тобі краще бути {стать:уважним:уважною} на цьому уроці, {стать:юначе:дівчинко}. Зурочення слабкості добре слугуватиме тобі в бою. Пізніше у мене буде випробування для тебе, щоб перевірити тебе та довести твою цінність для племені.", ["en"] = "Hex of Weakness" },
    [5653] = { [1] = "<NYI> Прокляття слабкості", [2] = "Один із ваших жерців передав нам звістку, що якщо ми вас побачимо, то маємо сказати вам повернутися до Орґріммара, {ім'я}. Здається, один із ваших ближніх — жрець на ім'я Ур'кьо, якщо я не помиляюся — вважає, що ви готові до подальшого навчання. Це пов'язано з деякими практиками вашої культури, сказав він, і він хоче, щоб ви знайшли цього Ур'кьо в Долині Духів.", ["en"] = "<NYI> Hex of Weakness" },
    [5654] = { [1] = "Зурочення слабкості", [2] = "Час тобі зустрітись з Ур'кьо, {ім'я}. Він находиться в долині Духів в місті орків. Йди туди та поговори з ним. Час тобі пізнати більше про старі звичаї нашого народу. Пора вступити в коло і стати {стать:справжнім:справжньою} {клас:о} нашого племені.", [3] = "Поговоріть з Ур'кьо в Орґріммарі.", [5] = "Добре, ти тут. Ми можем почать твоє вчення старих звичаїв.", ["en"] = "Hex of Weakness" },
    [5655] = { [1] = "Зурочення слабкості", [2] = "Мене відправили сюди, щоб я переконався, що ти не блукаєш надто далеко від дому, {ім'я}. Мене відправили за тобою тому, що Ур'кьо, найкращий з наших жерців, хотіти поговорити з тобою. Йди до нього. Прямуй в долину Духів у місті орків та поговори з Ур'кьо. Він чекає тебе.", [3] = "Поговоріть з Ур'кьо в Орґріммарі.", [5] = "Добре, ти тут. Ми можем почать твоє вчення старих звичаїв.", ["en"] = "Hex of Weakness" },
    [5656] = { [1] = "Зурочення слабкості", [2] = "Моє невмируще серце радіє, коли я бачу, як жерці різних культур мандрують цим світом. Добре знати, що існує не арканічна сила, що цілком доступна нам. Ось для мене честь направити тебе додому, {ім'я}.\n\nУр'кьо, твій старший жрець в Орґріммарі, хотів би бачити тебе. Ти знайдеш його у долині Духів.", [3] = "Поговоріть з Ур'кьо в Орґріммарі.", [5] = "Добре, ти тут. Ми можем почать твоє вчення старих звичаїв.", ["en"] = "Hex of Weakness" },
    [5657] = { [1] = "Зурочення слабкості", [2] = "Додому. Повертайся додому, {стать:юний:юна} {раса:к}.\n\nТвій духовний лідер Ур'кьо просить тебе повернутися до нього та поговорити про обраний тобою шлях.\n\nПрямуй в долину Духів у величному місті Орди, Орґріммарі. Ти знайдеш його там.", [3] = "Поговоріть з Ур'кьо в Орґріммарі.", [5] = "Добре, ти тут. Ми можем почать твоє вчення старих звичаїв.", ["en"] = "Hex of Weakness" },
    [5658] = { [1] = "Дотик слабкості", [2] = "Ти далеко од дому, {клас:к}. На тебе ждуть там, у твому підземному місті. Твоя майстриня, Ельталіста, приказує тобі повернуться. Як і в мойому племені, є речі, яких тебе може навчить тіки вона. Не затримуйся тута надовго. Ти маєш бистріше прямувать до кварталу Війни, шо в Підмісті.", [3] = "Поговоріть з Ельталістою в Підмісті.", [5] = "Ах, {стать:юний:юна} {клас:н}, я рада, що ти {стать:повернувся:повернулася} сюди. Я збираюся навчити тебе дечого, і раджу слухати уважніше. Ти {стать:готовий:готова}?", ["en"] = "Touch of Weakness" },
    [5659] = { [1] = "<NYI> Дотик слабкості", [2] = "Це не місце для тебе, {ім'я}. Тобі слід якомога швидше вирушити до Військового Кварталу в Підмісті. Ельталіста скликала туди всіх своїх жерців і жриць, щойно вони будуть готові. Настав час їм дізнатися більше про свою силу та як її використовувати.\n\nВона не потерпить запізнень чи виправдань, тому тобі краще йти своїм шляхом.", ["en"] = "<NYI> Touch of Weakness" },
    [566] = { [1] = "РОЗШУКУЄТЬСЯ: барон Вардус", [2] = "За наказом верховної карательки Дарталії людину, відому як барон Вардус, розшукують за злочини проти відречених. Відомо, що Вардус є високопоставленим членом організації, відомої як Синдикат.\n\nВостаннє його бачили на Верхогір'ї в Альтерацьких горах, на північ від Тарренського Млину.\n\nЙого розшукують мертвим. Принесіть докази його загибелі верховній карательці Дарталії, щоб отримати винагороду.", [3] = "Вбийте барона Вардуса і доставте його голову верховній карательці Дарталії в Тарренський Млин.", [4] = "А, {ім'я}. Можливо, ти {стать:прийшов:прийшла} по винагороду за голову барона Вардуса?", [5] = "Чудова робота, {ім'я}. Зі смертю барона Вардуса кількість ватажків Синдикату зменшується. Недовго їм залишилося опиратись.", ["en"] = "WANTED: Baron Vardus", ["tasks"] = { ["Head of Baron Vardus"] = "голова барона Вардуса", ["Head of Baron Vardus (Provided)"] = "голова барона Вардуса (видано)" } },
    [5660] = { [1] = "Дотик слабкості", [2] = "Ти далеко од дому, {клас:к}. На тебе ждуть там, у твому підземному місті. Твоя майстриня, Ельталіста, приказує тобі повернуться. Як і в мойому племені, є речі, яких тебе може навчить тіки вона. Не затримуйся тута надовго. Ти маєш бистріше прямувать до кварталу Війни, шо в Підмісті.", [3] = "Поговоріть з Ельталістою в Підмісті.", [5] = "О, добре, іще {стать:один прибув:одна прибула}. Для мене час не має значення, але для тебе він біжить швидко. Тобі багато чому треба навчитися, і я багато чому тебе навчу. Та ти маєш довести свою цінність. Зроби це, і отримаєш гідну винагороду.", ["en"] = "Touch of Weakness" },
    [5661] = { [1] = "Дотик слабкості", [2] = "Тут, в селищі Криваве Копито, ти далеко од дому, {ім'я}. Мене послали сюда шукать жерців з мого племені, шоб потім одправить їх до наших старійшин. Але я можу помогти й тобі.\n\nЯ чув, шо ваша верховна жриця-дух наказала всім відреченим-жерцям прийти до неї — є дещо, чому вона має тебе навчить.\n\nНайди Ельталісту в кварталі Війни, що в твому рідному місті.", [3] = "Поговоріть з Ельталістою в Підмісті.", [5] = "О, добре, іще {стать:один прибув:одна прибула}. Для мене час не має значення, але для тебе він біжить швидко. Тобі багато чому треба навчитися, і я багато чому тебе навчу. Та ти маєш довести свою цінність. Зроби це, і отримаєш гідну винагороду.", ["en"] = "Touch of Weakness" },
    [5662] = { [1] = "Дотик слабкості", [2] = "Моя повага тобі та твоєму роду, {ім'я}. Зазвичай я навчаю тільки членів мого племені. Твоїм навчанням займеться Ельталіста в місті, що раніше називалося Лордероном.\n\nТи маєш повернутися до неї, якщо ти хочеш навчитися здібностей, що відокремили тебе від інших вірувань.\n\nЙди до кварталу Війни в Підмісті та знайди там свою майстриню.", [3] = "Поговоріть з Ельталістою в Підмісті.", [5] = "О, добре, іще {стать:один прибув:одна прибула}. Для мене час не має значення, але для тебе він біжить швидко. Тобі багато чому треба навчитися, і я багато чому тебе навчу. Та ти маєш довести свою цінність. Зроби це, і отримаєш гідну винагороду.", ["en"] = "Touch of Weakness" },
    [5663] = { [1] = "Дотик слабкості", [2] = "Ельталіста надіслала звістку всім її жерцям. Ми тут, щоб направити наших юних жерців на навчання до Підмістя.\n\nТи зможеш знайти Ельталісту в кварталі Війни, що знаходиться в глибинах Підмістя.", [3] = "Поговоріть з Ельталістою в Підмісті.", [5] = "О, добре, іще {стать:один прибув:одна прибула}. Для мене час не має значення, але для тебе він біжить швидко. Тобі багато чому треба навчитися, і я багато чому тебе навчу. Та ти маєш довести свою цінність. Зроби це, і отримаєш гідну винагороду.", ["en"] = "Touch of Weakness" },
    [567] = { [1] = "Особливо небезпечні!", [2] = "Особливо небезпечні!\n\nНаступні жителі Гіллзбраду були визнані небезпечними і верховна карателька Дарталія пропонує винагороду за їхні голови:\n\nПисар Горацій Білокінь. Розшукується за вбивство смертестража Тома.\n\nМістянин Вілкс. Розшукується за вбивство аптекаря Елі.\n\nШахтар Гаккет. Розшукується за вбивство смертолова Фрая.\n\nФермерка Калаба. Розшукується за напад на караван із припасами з Підмістя.\n\nВсі ці злочинці ховаються, і знайти їх буде нелегко. Нагороду буде видано тим, хто здійснить над ними правосуддя.", [3] = "Верховна карателька Дарталія з Тарренського Млину пропонує винагороду за писаря Горація Білоконя, містянина Вілкса, шахтаря Гаккета і фермерку Калабу.", [4] = "Так?", [5] = "Ти {стать:справжній мисливець:справжня мисливиця} за головами, {клас:к}. Молодець.", ["en"] = "Dangerous!", ["tasks"] = { ["Citizen Wilkes"] = "містянин Вілкс", ["Citizen Wilkes slain"] = "містянин Вілкс: убито", ["Clerk Horrace Whitesteed"] = "Клерк Горрас Вайтстід", ["Clerk Horrace Whitesteed (Provided)"] = "Клерк Горрас Вайтстід (видано)", ["Clerk Horrace Whitesteed slain"] = "писар Горацій Білокінь: убито", ["Farmer Kalaba"] = "фермерка Калаба", ["Farmer Kalaba slain"] = "фермерка Калаба: убито", ["Miner Hackett"] = "шахтар Гаккет", ["Miner Hackett slain"] = "шахтар Гаккет: убито" } },
    [5679] = { [1] = "Пожираюча чума", [2] = "Ельталіста виявила велику повагу моєму народу, відправляючи моїх учнів до мене для подальшого тренування, а тепер я зроблю те саме для її племені.\n\nПовертайся до Підмістя, {ім'я}. Вона чекає на тебе у кварталі Війни, щоб розповісти більше про твій народ та його звичаї. Йди туди, не зволікай.", [3] = "Поговоріть з Ельталістою в Підмісті.", [5] = "Я навчу тебе пожираючої чуми, якщо ти відчуваєш, що {стать:готовий:готова}, {ім'я}. Це потужне закляття і воно допоможе у тобі в майбутніх битвах. Практикуйся, випробування будуть пізніше.", ["en"] = "Devouring Plague" },
    [568] = { [1] = "Оборона Ґром'ґола", [2] = "Тром'ка, {клас:к}!\n\nТи дуже вчасно {стать:прибув:прибула} в Ґром'ґол. Як командир військового табору воєвождя, я відповідаю честю за безпеку всіх членів Орди тут, у джунглях. Нашій місії з забезпечення безперебійного ланцюга постачання до Камінарда перешкоджають деякі місцеві жителі.\n\nЯ призначаю тебе {стать:відповідальним:відповідальною} за зменшення популяції хижаків за межами Ґром'ґола. Як тільки досягнеш значних успіхів — повертайся, і я назначу тобі нове завдання.", [3] = "Командир Аґґро'ґош з військового табору Ґром'ґол хоче, щоб ви вбили 15 хлястохвостих рапторів.", [4] = "Нашим постачанням все ще перешкоджають місцеві раптори, {клас:к}.", [5] = "Ти {стать:виконав:виконала} свій обов'язок з честю, {клас:к}.", ["en"] = "The Defense of Grom'gol", ["tasks"] = { ["Lashtail Raptor"] = "хлястохвостий раптор", ["Lashtail Raptor slain"] = "хлястохвостий раптор: убито" } },
    [5680] = { [1] = "Тінестраж", [2] = "Як і більшість наших жерців, твоє плем'я також проводить ритуали посвячення. Ці ритуали зазвичай навчають жерців особливих здібностей, життєво необхідних для виживання. Я відчуваю, що твій час теж настав. Ти маєш повернутися в долину Духів, що в Орґріммарі, та поговорити з Ур'кьо. Те, чого він тебе навчить, знадобиться тобі у майбутньому.", [3] = "Поговоріть з Ур'кьо в Орґріммарі.", [5] = "Твій ритуал скоро почнеться. А поки що я навчу тебе заклинання, що буде корисним в бою.", ["en"] = "Shadowguard" },
    [569] = { [1] = "Оборона Ґром'ґола", [2] = "Коли ми вперше прибули в ці джунглі, ми не мали наміру воювати з місцевими племенами. Наша місія — постачання Камінарда, має найвищий пріоритет. Але виникли ускладнення. Місцеві огри зайняли руїни Мізжа на південному сході від Ґром'ґола. І попри попередження, вони продовжують нападати на наші каравани з припасами.\n\nЯ призначаю тебе {стать:відповідальним:відповідальною} за боротьбу з цими впертими ограми.\n\nВирушай до руїн і спробуй вигнати їх звідти. Принаймні, це буде їм хорошим уроком.", [3] = "Командир Аґґро'ґош з військового табору Ґром'ґол хоче, щоб ви вбили 10 мош'оґґських моцаків та 5 мош'оґґських знахарів.", [4] = "Ти вже {стать:просунувся:просунулась} в завданні з ограми з руїн Мізжа, {клас:к}?", [5] = "Молодець. Ти з честю {стать:послужив:послужила} воєвождю.", ["en"] = "The Defense of Grom'gol", ["tasks"] = { ["Mosh'Ogg Brute"] = "мош'оґґський моцак", ["Mosh'Ogg Brute slain"] = "мош'оґґський моцак: убито", ["Mosh'Ogg Witch Doctor"] = "мош'оґґський знахар", ["Mosh'Ogg Witch Doctor slain"] = "мош'оґґський знахар: убито" } },
    [5691] = { [1] = "<NYI> <TXT> Створено в темряві", ["en"] = "<NYI> <TXT> In the Dark it was Created" },
    [5692] = { [1] = "<NYI> Створено в темряві", [2] = "Я навчу тебе всього, що знаю, {ім'я}, але є речі, яких тебе може навчити лише твоє плем'я. Одна з них — як створити для тебе нове вбрання... таке, що відображатиме твоє місце у вірі.\n\nЕльталіста сказала направити тебе до неї в Підмістя. Вона чекатиме на тебе у Військовому кварталі. Якщо не підеш, вона буде дуже незадоволена нами обома.", ["en"] = "<NYI> In the Dark It was Created" },
    [5693] = { [1] = "<NYI> Створено в темряві", [2] = "Радий бачити, що ти... ще живеш, {ім'я}.\n\nЕльталіста просила тебе повернутися в Підмістя, коли закінчиш свої справи тут, у Громовому Бескиді. Схоже, ти вже маєш достатньо сили, і вона вважає, що тобі час отримати нове вбрання... здається, мантію.\n\nВона чекатиме на тебе у Військовому кварталі.", ["en"] = "<NYI> In the Dark It was Created" },
    [570] = { [1] = "Чари Мок'тардіна", [2] = "Орда повинна вивчити силу джунглів та почати використовувати її. Мені вже вдалося досягти успіху в ритуалах. Я можу накладати дуже потужні чари. Для тебе, {стать:хоробрий:хоробра} {клас:к}, я зроблю особливу річ.\n\nПринеси мені пазурі тінепащих пантер, а також ікло тигриці. Аби яке ікло не підійде. Воно повинно бути в бездоганному стані.\n\nЦі звірі ховаються по всіх джунглях, але ти можеш знайти кількох неподалік, за річкою, поблизу руїн Мізжа, що на південному сході.", [3] = "Провидець Мок'тардін з військового табору Ґром'ґол хоче, щоб ви принесли йому 8 пазурів тінепащих пантер і бездоганне ікло тигриці.", [4] = "Які новини ти {стать:приніс:принесла}?", [5] = "Ти добре знаєш джунглі, {ім'я}. Ці екземпляри ідеально підійдуть. Я подякую духам за те, що вони принесли в жертву таких чудових звірів заради потреб Орди.", ["en"] = "Mok'thardin's Enchantment", ["tasks"] = { ["Pristine Tigress Fang"] = "бездоганне ікло тигриці", ["Pristine Tigress Fang (Provided)"] = "бездоганне ікло тигриці (видано)", ["Shadowmaw Claw"] = "пазур тінепащої пантери", ["Shadowmaw Claw (Provided)"] = "пазур тінепащої пантери (видано)" } },
    [571] = { [1] = "Чари Мок'тардіна", [2] = "Наступний компонент буде дуже важко знайти.\n\nЩоб з'єднати все це пір'я, пазурі та бездоганне ікло разом, мені потрібна магічна мотузка. Для неї підійде лише сухожилля старої горили.\n\nЙого можна отримати лише у старої туманодільної горили. Відомо, що вони полюють на сході від Грабіжної Бухти.\n\nСухожилля має бути ідеальним. Можливо, тобі доведеться вбити чимало тварин, щоб знайти те, що мені потрібно, але полювання буде варте того.", [3] = "Принесіть сухожилля старої горили провидцю Мок'тардіну в Ґром'ґол.", [4] = "Чи була удача на твоїй стороні, {ім'я}? Чи {стать:зміг:змогла} ти дістати сухожилля старої горили?", [5] = "Чудове сухожилля, {ім'я}. Твої зусилля незабаром окупляться.", ["en"] = "Mok'thardin's Enchantment", ["tasks"] = { ["Aged Gorilla Sinew"] = "сухожилля старої горили", ["Aged Gorilla Sinew (Provided)"] = "сухожилля старої горили (видано)" } },
    [572] = { [1] = "Чари Мок'тардіна", [2] = "Предмети, які тобі вдалося зібрати з котячих Тернистої долини — це лише перше, що потрібно для потужного зачарованого предмета. Ці дрібнички з джунглів у поєднанні з моїм шаманським ритуалом дадуть тобі дуже корисний інструмент для допомоги Орді та воєвождю.\n\nАле зараз ти {стать:повинен:повинна} дістати для мене пір'я ловця джунглів. Зазвичай ці звірі носять пір'я на лапах. Ти знайдеш це плем'я рапторів на південь від Ґром'ґола, неподалік великої арени.", [3] = "Принесіть 10 пір'їн ловця джунглів провидцю Мок'тардіну в військовий табір Ґром'ґол.", [4] = "Чи принесло плоди твоє полювання?", [5] = "Чудово. Я негайно їх підготую.", ["en"] = "Mok'thardin's Enchantment", ["tasks"] = { ["Jungle Stalker Feather"] = "перо ловця джунглів", ["Jungle Stalker Feather (Provided)"] = "перо ловця джунглів (видано)" } },
    [5722] = { [1] = "У пошуках втраченої сумки", [2] = "Троги — не єдине, що цікавить Маґату у прірві Лютого Полум'я. До неї дійшли чутки, що один з її слуг, Маур Зловісний Тотем, знайшов в прірві щось особливе, але вибратися звідти йому не вдалося. Вона хоче, щоб хто-небудь знайшов тіло Маура — якщо воно ще ціле — і з'ясував, що ж він таке знайшов, намагаючись вести переговори з трогами.\n\nЯкщо знайдеш що-небудь цікаве, принеси це Маґаті, і вона не поскупиться на нагороду.\n\nЗнову ж таки, прірву ти знайдеш в найтемніших закутках Орґріммара.", [3] = "Обшукайте прірву Лютого Полум'я в пошуках тіла Маура Зловісного Тотема та знайдіть всі незвичайні предмети.", [5] = "Тіло виглядає так, ніби Маура жорстоко били кийками чи кулаками, але більша частина одягу і спорядження, здається, на місці. Схоже, що трогам не надто були потрібні його пожитки.\n\nВи починаєте оглядати тіло в пошуках будь-яких предметів, які могли б зацікавити Маґату.", ["en"] = "Searching for the Lost Satchel" },
    [5723] = { [1] = "Випробування сили ворога", [2] = "Настирливі істоти, відомі як троги, раптом полізли із заповнених лавою тунелів під Орґріммаром. Великодушна Маґата хотіла домовитися з цими потворами, але вони накинулися на її дипломатів і перебили їх. Вона не може допустити такого поводження з тауренами, тож тепер для неї ці тварюки — вороги Орди.\n\nВона просить тебе розправитися з цими трогами, перш ніж вони почнуть загрожувати Орді з-під землі. Знайди прірву Лютого Полум'я і знищ їх усіх.", [3] = "Знайдіть в Орґріммарі прірву Лютого Полум'я, убийте 8 трогів і 8 шаманів Лютого Полум'я. Після цього поверніться до Рахауро в Громовий Бескид.", [4] = "Як справи з пошуком прірви? А з трогами?\n\nЯкщо ми дозволимо цій загрозі й надалі існувати — вона завдасть шкоди нашим побратимам-оркам.", [5] = "Я радий, що ти серйозно {стать:поставився:поставилась} до прохання Маґати. Дякую тобі, {ім'я}. Тепер, коли трогів поменшало, вони вже не полізуть так нахабно на поверхню!\n\nМоже, в майбутньому ми зуміємо дізнатися, звідки взялися ці істоти, і що їм потрібно насправді.", ["en"] = "Testing an Enemy's Strength", ["tasks"] = { ["Ragefire Shaman"] = "шаман Лютого Полум'я", ["Ragefire Shaman slain"] = "шаман Лютого Полум'я: убито", ["Ragefire Trogg"] = "трог Лютого Полум'я", ["Ragefire Trogg slain"] = "трог Лютого Полум'я: убито" } },
    [5724] = { [1] = "Повернення втраченої сумки", [2] = "Під тілом загиблого таурена ви знаходите сумку. Він все ще міцно стискає її в руках — мабуть, він намагався уберегти її від трогів.\n\nЗвільнивши сумку з його міцної хватки, ви закидаєте її до свого спорядження і готуєтеся до виходу з тунелів, щоб відправитися до Рахауро в Громовий Бескид.", [3] = "Віднесіть сумку Зловісного Тотема до Рахауро в Громовий Бескид.", [4] = "Тобі вдалося щось знайти, {ім'я}? Будь-які зачіпки щодо того, чому одному з членів її клану довелося померти без потреби, були б корисними.", [5] = "Прекрасно, {ім'я}. Дякую тобі.\n\nМагата сказала мені, що якщо тобі вдасться знайти члена її клану, я маю віддати тобі ось це. Прошу, прийми це на знак подяки.", ["en"] = "Returning the Lost Satchel", ["tasks"] = { ["Grimtotem Satchel"] = "сумка Зловісного Тотема", ["Grimtotem Satchel (Provided)"] = "сумка Зловісного Тотема (видано)" } },
    [5726] = { [1] = "Таємні вороги", [2] = "Я не потерплю зрадників серед нас, {ім'я}. Однак було б безглуздо діяти напролом — це не допоможе викорінити заразу з наших земель, а лише призведе до її поглиблення.\n\nАле ти, {стать:юний шукаче:юна шукачко} пригод, можеш проникнути туди, куди моїм агентам не дістатись... можеш дізнатися правду... можеш знайти справжню голову цієї потвори.\n\nЯкщо тобі вистачає хоробрості — вирушай до Скелі Черепа на схід від Орґріммару, знайди в одного з послідовників Палаючого Леза знак розрізнення лейтенанта і принеси його мені.", [3] = "Принесіть знак розрізнення лейтенанта Траллу в Орґріммар.", [4] = "Тобі вдалося тобі дістати знак розрізнення, {ім'я}?\n\nЦе важлива деталь для проникнення до організації, яку я вважаю найбільшою загрозою для Орди, що дозволить нарешті принести мир у наш новий дім.\n\nТи дізнаєшся, наскільки складні й підступні задуми можуть затіяти люди та орки, керовані жадібністю і жагою влади. Ти побачиш їх таємні плани та опинишся в епіцентрі війни, про існування якої навіть не {стать:підозрював:підозрювала}.", [5] = "Добре, {ім'я}! Хвала духам, можливо, саме ти нарешті покладеш край моїм найбільшим страхам! Хто б міг подумати, що такі юні та хоробрі шукачі пригод боротимуться за нашу справу? Ти нагадуєш мені мене самого в молодості. Я подбаю про те, щоб тебе гідно винагородили за зусилля, якщо ми обидва переживемо прийдешню бурю.\n\nАле час для похвали буде пізніше. Те, що тобі вже вдалося зробити — дрібниці у порівнянні з тим, що тебе чекає... але це гарний початок.", ["en"] = "Hidden Enemies", ["tasks"] = { ["Lieutenant's Insignia"] = "знак розрізнення лейтенанта", ["Lieutenant's Insignia (Provided)"] = "знак розрізнення лейтенанта (видано)" } },
    [5727] = { [1] = "Таємні вороги", [2] = "А тепер давай подивимося, чи вартий знайдений тобою знак розрізнення цих зусиль.\n\nУ місті є чорнокнижник, який упевнений, що я йому повністю довіряю. Він і не підозрює, що мені відомо про його зраду. Насправді він — ватажок Палаючого Леза. Але не поспішай вступати з ним у бій. Він нам ще знадобиться — ми використаємо його проти наших ворогів.\n\nВіднеси цей знак розрізнення йому в Розколину Тіні, що в Орґріммарі. Поговори з ним і переконайся, що він прийме тебе за {стать:одного зі своїх:одну зі своїх}, а потім повертайся до мене.", [3] = "Віднесіть знак розрізнення лейтенанта Нііру Вогняному Лезу і поговоріть з ним. Переконайтесь, що він вірить у вашу приналежність до Палаючого Леза, а потім поверніться до Тралла в Орґріммар.", [4] = "Ну що, {клас:к}? Він повірив у наш трюк, чи все гірше, ніж я думав?\n\nЯкщо ти доведеш свою цінність для Нііру, нам буде набагато легше проникнути в Раду Тіні. У нього буде вдосталь інформації, яку ми зможемо використати, щоб вивести на чисту воду тих, хто хоче згубити все, що ми побудували в Дуротарі.", [5] = "Чудово! Просто чудово, {клас:к}!\n\nТе, що ти {стать:зробив:зробила} сьогодні, — лише перший крок до знищення Ради Тіні, раз і назавжди.\n\nПерекажи мені все, що він говорив... і не пропусти жодного слова — дрібниці можуть виявитися важливішими, ніж ти думаєш.", ["en"] = "Hidden Enemies", ["tasks"] = { ["Gauge Neeru Fireblade's reaction to you being a member of the Burning Blade"] = "Реакція Гейджа Ніру Вогняного Клинка на те, що ти є членом Палаючого Клинка" } },
    [5728] = { [1] = "Таємні вороги", [2] = "Хм, ватажки Випаленого Клинка... Це серйозно. Якщо Нііру ними дорожить, значить, саме їх і потрібно ліквідувати. Цей сатир... Баззалан, і той, другий, якого згадував Нііру, — він хто, чорнокнижник? — їх слід вбити.\n\nПовертайся до Розколини Тіні та проникни до прірви Лютого Полум'я, {ім'я}. Знайди цих ватажків Випаленого Клинка й убий їх. Але будь {стать:обережний:обережна}, щоб Нііру не дізнався, що це твоїх рук справа. Нехай, як і раніше, вважає тебе {стать:одним з братів:однією з сестер} по зброї.", [3] = "Убийте Баззалана та Єргоша-Заклинателя перед поверненням до Тралла в Орґріммар.", [4] = "Ти їх ще не {стать:знайшов:знайшла}, {ім'я}? Лідерів Випаленого Клинка.\n\nЯ знав, що Рада Тіні прагнула забрати у мене Орґріммар та всю Орду, але я не усвідомлював, як швидко вони змогли проникнути в місто. У цього звіра стільки рук... Ми можемо їх виснажити, але ми не просунемося далі, аніж від того, з чого почали. Я накажу своїм шпигунам подвоїти зусилля.", [5] = "Я радий, що ти {стать:повернувся:повернулася}, {ім'я}. Мої агенти вже повідомили, що в печерах під Орґріммаром запанував хаос після смерті їхніх ватажків. Мені навіть доповідали, що Нііру дуже стривожений. Схоже, ми надломили його броню. Не можу не визнати, що мене це тішить... Нехай це й невелика, але все ж перемога.", ["en"] = "Hidden Enemies", ["tasks"] = { ["Bazzalan"] = "Баззалан", ["Bazzalan slain"] = "Баззалан: убито", ["Jergosh the Invoker"] = "Єргош-Заклинатель", ["Jergosh the Invoker slain"] = "Єргош-Заклинатель: убито" } },
    [573] = { [1] = "Чари Мок'тардіна", [2] = "Для накладання чарів не вистачає лише одного реагенту.\n\nНа півдні, на західному узбережжі, високо над урвищами розміщується святе джерело. Це джерело є предметом великого конфлікту між релігійними та містичними вченими. Кожна раса в Азероті стверджує, що води джерела освячені саме для їхнього народу.\n\nМоє останнє прохання до тебе: принеси мені воду зі святого джерела. Будь {стать:обережним:обережною}. Зараз його околиці захопили наги-дослідники. З ними теж слід розібратися.", [3] = "Провидцю Мок'тардіну з Ґром'ґола потрібна вода святого джерела. Він також просить вас вбити 10 наг-дослідників.", [4] = "Я майже готовий накласти чари. Ти {стать:виконав:виконала} моє прохання?", [5] = "Завдяки цій джерельній воді, я можу накласти чари на обрядове намисто.\n\nНоси його з гордістю, {ім'я}, в ім'я воєвождя і для захисту могутньої Орди.", ["en"] = "Mok'thardin's Enchantment", ["tasks"] = { ["Holy Spring Water"] = "вода святого джерела", ["Holy Spring Water (Provided)"] = "вода святого джерела (видано)", ["Naga Explorer"] = "нага-дослідник", ["Naga Explorer slain"] = "нага-дослідник: убито" } },
    [5761] = { [1] = "Убити звіра", [2] = "Головне завдання, яке доручив мені наш великий воєвождь, — це викорінити тих тварюк, відповідальних за зараження нашого великого міста демонічною заразою. Палаюче Лезо — головна, але не єдина загроза. Є ще, наприклад, Випалений Клинок, культ, який влаштувався в прірві Лютого Полум'я і потай бентежить розуми простих представників Орди.\n\nЩоб їх зупинити, потрібно вбити їхнього ватажка — вартового скверни, на ім'я Тараґаман Ненажерливий.\n\nУбий його, і його серце заспокоїть Тралла, в цьому я впевнений.", [3] = "Спустіться до прірви Лютого Полум'я, убийте Тараґамана Ненажерливого і принесіть його серце Нііру Вогняному Лезу в Орґріммар.", [4] = "Ну що, вдалося тобі вбити цього звіра? Він, безумовно, повинен бути ватажком Випаленого Клинка у прірві Лютого Полум'я.", [5] = "Ха! Тобі це вдалося! Тралл буде в захваті.\n\nЯ забезпечу належний догляд за цим серцем.\n\nНу, а ти можеш відсвяткувати свою перемогу. Я повідомлю Траллу про твої успіхи.\n\nДякую за допомогу, {клас:к}.", ["en"] = "Slaying the Beast", ["tasks"] = { ["Taragaman the Hungerer's Heart"] = "серце Тараґамана Ненажерливого", ["Taragaman the Hungerer's Heart (Provided)"] = "серце Тараґамана Ненажерливого (видано)" } },
    [5763] = { [1] = "Полювання в Тернистій долині", [2] = "Багато років тому один дворф прийшов на ці землі. Його звали Гемет і він хотів вполювати великого звіра. Він вміло поводився з рушницею, і ми багато днів полювали разом. Ми навіть забули про ворожнечу між нашими народами.\n\nКоли він йшов зі Спустошища в Тернисту долину, я поклявся, що коли б він не повернувся, ми підемо на полювання, як і раніше. І ось цей час настав.\n\nВіднеси цей ріг кодо Гемету. Він зрозуміє, що це від мене. Ти знайдеш його в Тернистій долині, на північ від військового табору Ґром'ґол.", [3] = "Віднесіть Рууновий ріг кодо Гемету Ернінґвею в Тернисту долину.", [4] = "Присядь, {клас:к}. Незабаром ти знову відправишся в джунглі.", [5] = "О, цей ріг належить таурену, Рууну Дикій Гриві. Ми з ним гарно провели час, полюючи на звірів в Спустошищі. То Руун запрошує мене на полювання, чи не так?\n\nУ нас зараз багато справ в джунглях, але я все одно вдячний тобі, {ім'я}. Можливо, моя наступна експедиція приведе мене в Спустошище, в землі кентаврів.", ["en"] = "Hunting in Stranglethorn", ["tasks"] = { ["Roon's Kodo Horn"] = "Рууновий ріг кодо", ["Roon's Kodo Horn (Provided)"] = "Рууновий ріг кодо (видано)" } },
    [5802] = { [1] = "Кузня Вогнеперої скелі", [2] = "Тобі потрібні два злитки торію та потужне джерело тепла, щоб викувати основу ключа. Торій знайди самостійно, а з нагрівом я можу допомогти.\n\nНа заході, в кратері Ун'Ґоро, є Вогнепера скеля — киплячий вулкан. Лавове озеро нагорі достатньо гаряче, щоб сплавити торій з кістками. Твої гроші витрачені не дарма — цю форму можна просто занурити в вогняне озеро, а все інше зробить лава.\n\nЦе все, чим я можу тобі допомогти. Дітерс розкаже тобі, як завершити ключ.", [3] = "Віднесіть форму для скелетного ключа та 2 злитки торію на вершину Вогнеперої скелі в кратер Ун'Ґоро. Використовуйте форму для скелетного ключа біля озера лави, щоб викувати незавершений скелетний ключ.\n\nВіднесіть незавершений скелетний ключ аптекару Дітерсу на Вал в Західні Зачумлені землі.", [4] = "Тобі вдалося зробити основу скелетного ключа? Мені справді шкода, що ти {стать:мусив:мусила} купувати форму за власні гроші, але кожен з нас має робити свій внесок у боротьбу зі Скарою. Якщо ти віддаси мені незавершений ключ, ти будеш {стать:готовий:готова} до останньої деталі, необхідної для його завершення.\n\nЦе важке завдання, але твоя підготовка до нападу на Андорал не пройде даремно. Ось побачиш.", [5] = "Недешево обійшлася тобі ця основа скелетного ключа, еге ж, {ім'я}? Проте він залишається незавершеним. Прийшов час останнього етапу, а він найскладніший. Для завершення ключа тобі доведеться зіткнутися з головним ворогом, що чекав на нас в Андоралі... з істотою, що керує руїнами міста.\n\nЯ маю на увазі Аража-Закликача — ліча, одне з найпотужніших створінь Скари.", ["en"] = "Fire Plume Forged", ["tasks"] = { ["Unfinished Skeleton Key"] = "незавершений скелетний ключ", ["Unfinished Skeleton Key (Provided)"] = "незавершений скелетний ключ (видано)" } },
    [5804] = { [1] = "Скарабей Аража", [2] = "Араж-Закликач править Андоралом з серця зруйнованого міста. Ми знаємо, що він був лідером Некроситету, поки не захопив місто. Щоб завершити ключ, нам потрібен його перстень — він називається скарабеєм — це буде головка ключа.\n\nВідправляйся в саме серце Андорала та позбав його влади над містом. Як вб'єш його, витягни скарабея з його філактерії.\n\nКлюч до Некроситету чекає, {ім'я}!", [3] = "Вбийте Аража-Закликача та принесіть скарабея Аража аптекареві Дітерсу на Вал, що в Західних Зачумлених землях.", [4] = "Ти {стать:зайшов:зайшла} досить далеко, {ім'я}, але лиш знищення Аража-Закликача дозволить нам завершити ключ. Забери скарабея Аража, чого б тобі це не вартувало, та принеси його мені — я зроблю з нього головку ключа.", [5] = "Так, це він! Я... знову ж таки, вражений глибиною твоєї рішучості та хоробрості. Це просто вражає, на що ти {стать:здатен:здатна} піти, щоб досягти перемоги.\n\nТепер дозволь мені відіграти свою роль. Я приготував особливий розчин, який дозволить мені закріпити скарабея на ключі. Ця сила зможе відчинити двері в Некроситеті.\n\nЦе займе лиш мить...", ["en"] = "Araj's Scarab", ["tasks"] = { ["Araj's Scarab"] = "скарабей Аража", ["Araj's Scarab (Provided)"] = "скарабей Аража (видано)" } },
    [581] = { [1] = "Пошуки Єнніку", [2] = "Приреченість прийшла до нас. І вона спіткала сина мого вождя, Єнніку. За звичаєм нашого народу, він був відданий тролям Ґурубаші з Зул'Ґуруба, але після того, як моє плем'я — плем'я Темного Списа, пішло за орком Траллом, ми втратили бідолашного Єнніку. Мене послали з далекого Орґріммару назад в Тернисту долину на пошуки сина мого вождя.\n\nІ я вважаю, що він в руках племені Кровоскальпих.\n\nЯкщо ти хочеш мені допомогти, то вбий Кровоскальпих. Їх можна знайти на півночі. Збери їхні ікла і повернись до мене.", [3] = "Принесіть 9 ікл Кровоскальпих до Німбої в військовий табір Ґром'ґол.", [4] = "{Клас:к}. Доведи мені, що воїни племені Кровоскальпих полягли від твоєї руки.\n\nПокажи мені трофеї.", [5] = "Це гарні ікла, {ім'я}. Ти {стать:довів:довела}, що можеш полювати на Кровоскальпих.\n\nІ це добре, бо полювання ще не закінчено.", ["en"] = "Hunt for Yenniku", ["tasks"] = { ["Bloodscalp Tusk"] = "ікло Кровоскальпого", ["Bloodscalp Tusk (Provided)"] = "ікло Кровоскальпого (видано)" } },
    [582] = { [1] = "Полювання за головами", [2] = "Ми повинні з'ясувати, чи Єнніку мертвий.\n\nВбий мисливців за головами з племені Кровоскальпих та забери у них сушені голови. Тобі потрібно зібрати якомога більше голів, і я огляну їх, щоб переконатися, що серед них немає голови Єнніку.\n\nІ якщо Єнніку вбили Кровоскальпі, то нехай впаде 600-річне прокляття на дух їхнього вождя, Ґан'зули!\n\nІди, {ім'я}. Ти знайдеш багато мисливців за головами на руїнах Зуулдая та Зул'Кунда, вздовж узбережжя на півночі.", [3] = "Принесіть 20 сушених голів Німбої в військовий табір Ґром'ґол.", [4] = "{ім'я}. Я боюся за сина нашого вождя. Ти {стать:приніс:принесла} мені голови, щоб я міг їх оглянути?", [5] = "Дякую тобі, {ім'я}. Я огляну ці голови, щоб переконатися, чи бідолашний Єнніку врятувався від сокири мисливця за головами.", ["en"] = "Headhunting", ["tasks"] = { ["Shrunken Head"] = "сушена голова", ["Shrunken Head (Provided)"] = "сушена голова (видано)" } },
    [584] = { [1] = "Голови племені Кровоскальпих", [2] = "Єнніку не було серед голів і я дякую за це Великому Змієві. Але ми не сильно просунулися в його пошуках.\n\nМи мусимо з'ясувати правду, та боюся, що її знають лише вождь Кровоскальпих та його знахар. Вони вороги племені Темного Списа і не будуть говорити просто так, тому ми повинні вирвати правду з їхніх мертвих вуст!\n\nПринеси мені голови Ґан'зули та Неззліока Зловісного і поклади їх у цей казан.\n\nВони живуть в глибинах руїн Зул'Кунда. Принеси їхні голови, ми змусимо їх говорити.", [3] = "Принесіть голову Ґан'зули та голову Неззліока і покладіть їх до киплячого казана в військовому таборі Ґром'ґол.", [4] = "В казані кипить зелене вариво.", [5] = "Ви кладете голови Ґан'зули та Неззліока в казан...", ["en"] = "Bloodscalp Clan Heads", ["tasks"] = { ["Gan'zulah's Head"] = "голова Ґан'зули", ["Gan'zulah's Head (Provided)"] = "голова Ґан'зули (видано)", ["Nezzliok's Head"] = "голова Неззліока", ["Nezzliok's Head (Provided)"] = "голова Неззліока (видано)" } },
    [5843] = { [1] = "Ласкаво просимо!", [2] = "Ласкаво просимо до World of Warcraft!\n\nНа знак особливої подяки за придбання колекційного видання World of Warcraft, прийміть цей подарунковий сертифікат і передайте його Маґґі в долині Випробувань. За нього ви отримаєте подарунок — маленького компаньйона, який супроводжуватиме вас у пошуках пригод і слави.\n\nЩе раз дякуємо і бажаємо приємного перебування у World of Warcraft!", [3] = "Віднесіть подарунковий сертифікат долини Випробувань до Маґґи.", [4] = "Привіт! Приємно познайомитися з тобою!\n\nБачу, ти маєш подарунковий сертифікат. Віддай його мені, а я запропоную тобі щось натомість.", [5] = "Ти справді {стать:особливий герой:особлива героїня}, {ім'я:к}. Ми вітаємо тебе в Азероті та пропонуємо один з цих унікальних подарунків!", ["en"] = "Welcome!", ["tasks"] = { ["Valley of Trials Gift Voucher"] = "подарунковий сертифікат долини Випробувань", ["Valley of Trials Gift Voucher (Provided)"] = "подарунковий сертифікат долини Випробувань (видано)" } },
    [5844] = { [1] = "Ласкаво просимо!", [2] = "Ласкаво просимо до World of Warcraft!\n\nНа знак особливої подяки за придбання колекційного видання World of Warcraft, прийміть цей подарунковий сертифікат і передайте його Ворну Небесному Провидцю в таборі Нараче. За нього ви отримаєте подарунок — маленького компаньйона, який супроводжуватиме вас у пошуках пригод і слави.\n\nЩе раз дякуємо і бажаємо приємного перебування у World of Warcraft!", [3] = "Віднесіть подарунковий сертифікат табору Нараче до Ворна Небесного Провидця.", [4] = "Вітаю! Приємно познайомитися з тобою!\n\nБачу, ти маєш подарунковий сертифікат. Віддай його мені, а я запропоную тобі щось натомість.", [5] = "Ти справді {стать:особливий герой:особлива героїня}, {ім'я:к}. Ми вітаємо тебе в Азероті та пропонуємо один з цих унікальних подарунків!", ["en"] = "Welcome!", ["tasks"] = { ["Camp Narache Gift Voucher"] = "подарунковий сертифікат табору Нараче", ["Camp Narache Gift Voucher (Provided)"] = "подарунковий сертифікат табору Нараче (видано)" } },
    [5847] = { [1] = "Ласкаво просимо!", [2] = "Ласкаво просимо до World of Warcraft!\n\nНа знак особливої подяки за придбання колекційного видання World of Warcraft, прийміть цей подарунковий сертифікат і передайте його Клер Вербній в Смертедзвоні. За нього ви отримаєте подарунок — маленького компаньйона, який супроводжуватиме вас у пошуках пригод і слави.\n\nЩе раз дякуємо і бажаємо приємного перебування у World of Warcraft!", [3] = "Віднесіть подарунковий сертифікат Смертедзвону до Клер Вербної.", [4] = "Вітаю! Приємно познайомитися з тобою!\n\nБачу, ти маєш подарунковий сертифікат. Віддай його мені, а я запропоную тобі щось натомість.", [5] = "Ти справді {стать:особливий герой:особлива героїня}, {ім'я:к}. Ми вітаємо тебе в Азероті та пропонуємо один з цих унікальних подарунків!", ["en"] = "Welcome!", ["tasks"] = { ["Deathknell Gift Voucher"] = "подарунковий сертифікат Смертедзвону", ["Deathknell Gift Voucher (Provided)"] = "подарунковий сертифікат Смертедзвону (видано)" } },
    [585] = { [1] = "Розмова з Неззліоком", [2] = "<Голова Неззліока починає говорити.>\n\nЦе правда. Я знаю, куди забрали дитя племені Темного Списа. Ти {стать:переміг:перемогла} мене і {стать:зв'язав:зв'язала} мій дух, але я все одно не буду говорити задарма!\n\nКровоскальпі воюють з Черепотрощителями. Щоб завоювати мою прихильність, викради у Черепотрощителів 3 трофейні черепи, принеси їх сюди та поклади їх до нас, щоб мій дух мав рабів у Підсвітті. Один череп має бути з їхньої трофейної купи в Баліа'мі, інший — з Зіата'джай, а останній — з Зул'Мамве.", [3] = "Принесіть трофей з Баліа'ма, трофей з Зіата'джай і трофей з Зул'Мамве і покладіть їх до киплячого казана у військовому таборі Ґром'ґол.", [4] = "Я чекаю на черепи...", [5] = "Так. Вони добре служитимуть мені. Коли мій дух звільниться, я ввійду в Підсвіття з трьома прекрасними слугами!\n\nТи — гордість для свого клану, {раса:к}, і ти {стать:заслужив:заслужила} на мою прихильність.", ["en"] = "Speaking with Nezzliok", ["tasks"] = { ["Balia'mah Trophy"] = "трофей з Баліа'ма", ["Balia'mah Trophy (Provided)"] = "трофей з Баліа'ма (видано)", ["Ziata'jai Trophy"] = "трофей з Зіата'джай", ["Ziata'jai Trophy (Provided)"] = "трофей з Зіата'джай (видано)", ["Zul'Mamwe Trophy"] = "трофей з Зул'Мамве", ["Zul'Mamwe Trophy (Provided)"] = "трофей з Зул'Мамве (видано)" } },
    [586] = { [1] = "Розмова з Ґан'зулою", [2] = "<Голова Ґан'зули починає говорити.>\n\nБудь ти {стать:проклятий:проклята}! І будь прокляті твої предки!!!\n\nТільки кров і помста можуть охолодити мою лють, тож якщо ти цього бажаєш, то... зроби це:\n\nВирушай в саме серце Черепотрощителів на сході. Убий найлютішого з них, а якщо виживеш... то кинь виклик їхньому вождю, Ана'теку Жорстокому. Ха! Принеси мені його розтрощені обладунки, якщо зможеш!\n\nНехай він відірве твої кінцівки та залишить тебе гнити. Тебе пожеруть стерв'ятники!", [3] = "Убийте 8 мисливців, 6 мисливців за головами та 4 берсерків з племені Черепотрощителів.\n\nПринесіть розтрощені обладунки Ана'тека та покладіть їх до киплячого казана у військовому таборі Ґром'ґол.", [4] = "Хоч і моя власна плоть поступово злізає з мого черепа, я все ще відчуваю запах твого страху.\n\nХа! Ти ніколи не виконаєш моє завдання...", [5] = "Я не хочу в це вірити, але й не можу заперечувати того, що ти {стать:зробив:зробила}. І мій гнів вщухає, коли я знаю, що Ана'тек переможений.\n\nТвоя міць приведе тебе до великих звершень, {ім'я}. Але одного дня... ми зустрінемось в Підсвітті та знову поміряємося силами.\n\nЯ чекатиму.", ["en"] = "Speaking with Gan'zulah", ["tasks"] = { ["Broken Armor of Ana'thek"] = "розтрощені обладунки Ана'тека", ["Broken Armor of Ana'thek (Provided)"] = "розтрощені обладунки Ана'тека (видано)", ["Skullsplitter Berserker"] = "берсерк Черепотрощителів", ["Skullsplitter Berserker slain"] = "берсерк Черепотрощителів: убито", ["Skullsplitter Headhunter"] = "мисливець за головами Черепотрощителів", ["Skullsplitter Headhunter slain"] = "мисливець за головами Черепотрощителів: убито", ["Skullsplitter Hunter"] = "мисливець Черепотрощителів", ["Skullsplitter Hunter slain"] = "мисливець Черепотрощителів: убито" } },
    [588] = { [1] = "Доля Єнніку", [2] = "<Голова Неззліока починає говорити.>\n\nТи {стать:упокоїв:упокоїла} мене і мого вождя, тож я розповім тобі те, що ти хочеш дізнатися...\n\nЮний Єнніку назавжди втрачений для свого племені.\n\nЙого викрав знахар Занзіл-Вигнанець. Тепер Занзіл контролює його тіло і душу, і тільки найсильніша магія може звільнити його.\n\nМагія, якою ти не володієш, {клас:к}.\n\nМожливо, твої союзники з Темного Списа зможуть дати надію на порятунок Єнніку. Але я сумніваюся в цьому.", [3] = "Поговоріть з Кін'вілеєм.", [5] = "Занзіл-Вигнанець?\n\nЯкщо Єнніку утримує той троль, мерзенний і могутній знахар, то, на жаль, надії залишається небагато.\n\nТа все ж вона є.", ["en"] = "The Fate of Yenniku" },
    [5881] = { [1] = "Зміна варти", [2] = "Орда тримає наші війська у формі... з часів Великої Війни ми успішно проживаємо тут, у Калімдорі.\n\nЗроби мені послугу, є один хлопець, на ім'я Ґріш Довгобіг, який охороняє Великий Підйомник у південних Степах. Передай йому цього листа. В ньому говориться, що я маю воїна з запасу, який замінить його на службі, щоб він міг провідати свою сім'ю. Ґріш нещодавно просив про це і буде радий почути таку новину.", [3] = "Маґґран просить вас передати листа Ґрішу Довгобігу, що знаходиться біля Великого Підйомника в Степах.", [4] = "В тебе є новини від Маґґрана Землев'яза?", [5] = "Це чудова новина. Я надто довго сидів тут, оберігаючи цей шматок дерева. Тепер я зможу хоч трохи провести час зі своєю сім'єю... Ура!", ["en"] = "Calling in the Reserves", ["tasks"] = { ["Maggran's Reserve Letter"] = "лист Маґґрана", ["Maggran's Reserve Letter (Provided)"] = "лист Маґґрана (видано)" } },
    [5887] = { [1] = "Бальзам з уламків душ", [4] = "Маяк Кенарія дозволяє побачити уламки душ уражених оскверненням тварин, убитих заради загального блага. Я подрібню уламки душ на реагент, придатний для виготовлення кенарійського бальзаму зцілення рослин. Ми використовуємо цей засіб, щоб вилікувати уражені скверною рослини.\n\nВ обмін на ці уламки душ я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Дуже добре, ось тобі декілька порцій кенарійського бальзаму. Шукай в Скверноліссі осквернені рослини, {ім'я}! Як знайдеш їх — використовуй бальзам, щоб очистити їх.", ["en"] = "Salve via Hunting", ["tasks"] = { ["Corrupted Soul Shard"] = "уламок оскверненої душі", ["Corrupted Soul Shard (Provided)"] = "уламок оскверненої душі (видано)" } },
    [5888] = { [1] = "Бальзам з мінералів", [4] = "Якщо під час видобутку копалин в Скверноліссі в тебе буде з собою маяк Кенарія, ти зможеш побачити уражений купорос, що проникає в жили металів. Я знаю, як очистити цей купорос і перетворити його на реагент, придатний для виготовлення кенарійського бальзаму зцілення рослин. Ми використовуємо цей засіб, щоб вилікувати уражені скверною рослини.\n\nЯкщо ти принесеш мені уражений купорос, я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Дуже добре, ось декілька порцій кенарійського бальзаму. Якщо ти знайдеш уражений купорос, коли видобуватимеш копалини у Скверноліссі, не забудь притримати його для мене! Що більше ти знайдеш, то більше бальзаму я зможу зробити.", ["en"] = "Salve via Mining", ["tasks"] = { ["Tainted Vitriol"] = "уражений купорос", ["Tainted Vitriol (Provided)"] = "уражений купорос (видано)" } },
    [5889] = { [1] = "Бальзам з осквернених трав", [4] = "Маяк Кенарія дозволяє досвідченому травнику помітити залишок скверни — мерзенний продукт осквернення, що вразило Сквернолісся. Моя робота в Скверноліссі дозволила мені навчитися перетворювати залишок скверни в очисний реагент... який ми використовуємо в кенарійському бальзамі зцілення рослин.\n\nКоли ти збиратимеш трави в Скверноліссі, ти зможеш натрапити на залишок скверни, якщо матимеш при собі маяк. В обмін на залишки я виготовлю для тебе кенарійський бальзам.", [5] = "Чудова робота, {ім'я} — коли ми їх очистимо, вони допоможуть нам повернути Сквернолісся до життя. Ось, візьми кілька порцій кенарійського бальзаму зцілення рослин та прямуй до лісу. Зцілення цих земель від скверни — невідкладна справа!", ["en"] = "Salve via Gathering", ["tasks"] = { ["Fel Creep"] = "залишок скверни", ["Fel Creep (Provided)"] = "залишок скверни (видано)" } },
    [589] = { [1] = "Співочі кристали", [2] = "Легенди розповідають про коштовний камінь, захований глибоко в серці Тернистої долини. Ми називаємо його Оком Розуму, і воно має в собі велику силу. Якщо ти дістанеш його, то, можливо, нам вдасться повернути загубленого Єнніку з темряви.\n\nЯ попрошу духів джунглів допомоги в пошуках Ока Розуму. Поки я займатимусь цим, вирушай в Кришталеву копальню, що на південному сході звідси та збери пульсуючі блакитні осколки із залізощелепих василісків. Осколки рідкісні, але нам знадобляться їхні чари, щоб підкорити Око Розуму.", [3] = "Принесіть 3 пульсуючі блакитні осколки Кін'вілею у військовий табір Ґром'ґол.", [4] = "Ти {стать:зібрав:зібрала} осколки, {ім'я}? Вони потрібні для мого останнього ритуалу, коли ми матимемо Око Розуму.", [5] = "Ти добре {стать:попрацював:попрацювала}, {ім'я}. Ці осколки правильної форми. Я вже відчуваю їхнії спів.\n\nПоки тебе не було, я говорив з духами джунглів. Я знаю, де знаходиться Око Розуму.\n\n...І хто його охороняє.", ["en"] = "The Singing Crystals", ["tasks"] = { ["Pulsing Blue Shard"] = "пульсуючий блакитний осколок", ["Pulsing Blue Shard (Provided)"] = "пульсуючий блакитний осколок (видано)" } },
    [5890] = { [1] = "Бальзам зі шкір", [4] = "Маяк Кенарія дає змогу досвідченому шкуродеру знаходити серед зібраної у Скверноліссі шкіри ту, що уражена скверною. Я переробляю цю здавалось би непотрібну шкіру в густу пасту, що прискорює дію кенарійського бальзаму зцілення рослин. Коли будеш займатися шкуродерством у Скверноліссі, обов'язково тримай при собі маяк!\n\nКоли збереш клапті ураженої шкіри — принеси їх мені, і я дам тобі кілька порцій кенарійського бальзаму.", [5] = "Це саме те, що мені потрібно. Ось — візьми кенарійський бальзам, щоб очистити рослини Сквернолісся від осквернення. Ми повинні боротися, {ім'я}!", ["en"] = "Salve via Skinning", ["tasks"] = { ["Patch of Tainted Skin"] = "клапоть ураженої шкіри", ["Patch of Tainted Skin (Provided)"] = "клапоть ураженої шкіри (видано)" } },
    [5891] = { [1] = "Бальзам з розбитих чарів", [4] = "Сила магічного предмета відповідає силі субстанцій, які отримують унаслідок розбиття його чарів. Я винайшла спосіб перероблення сирих субстанцій, які використовують накладачі чарів, у реагент, придатний для створення кенарійського бальзаму зцілення рослин. Для цього тобі не потрібен маяк Кенарія — підійде будь-який магічний предмет, розбиття чарів якого дає малі підсвітні субстанції.\n\nМені потрібна лише одна така субстанція. За на неї я дам тобі кенарійський бальзам зцілення рослин. Підсвітня субстанція дуже потужна — навіть одної вистачить надовго!", [5] = "Ось кілька порцій кенарійського бальзаму зцілення рослин, {ім'я}, і за нього я прошу лише одну малу підсвітню субстанцію. Субстанція — це найпотужніша речовина, яку я можу використати для створення бальзаму. Якщо тобі знадобиться більше бальзаму — приходь до мене.", ["en"] = "Salve via Disenchanting", ["tasks"] = { ["Lesser Nether Essence"] = "мала підсвітня субстанція", ["Lesser Nether Essence (Provided)"] = "мала підсвітня субстанція (видано)" } },
    [5893] = { [1] = "Припаси Кригозубих", [2] = "Колись північна копальня Кригозубих була ідеальним місцем для зберігання припасів, але тепер, коли війна з Бурешпилем стає дедалі запеклішою, ми не завжди маємо вільних воїнів для охорони шахти. Через це контроль над нею часто переходить до Альянсу, або до підземних мешканців...\n\nАле нам все одно потрібно повернути припаси, {ім'я:к}! Вирушай до копальні Кригозубих та принеси їх мені. Остерігайся ворогів, в цьому місці постійно виникають сутички...", [3] = "Принесіть 10 припасів Кригозубих квартирмейстеру Орди в форт Морозних Вовків.", [4] = "Ти вже {стать:був:була} в копальні Кригозубих, {ім'я:к}? {стать:Приніс:Принесла} припаси, про які я просив?", [5] = "Так, це вони! Чудова робота, {ім'я:к}! Припаси трохи запліснявіли від довгого перебування в темній шахті, але це не завадить нам скористатися ними.\n\nДякую тобі, {ім'я:к}. Завдяки тобі, ми зможемо підтримувати сили наших воїнів.", ["en"] = "Coldtooth Supplies", ["tasks"] = { ["Coldtooth Supplies"] = "припаси Кригозубих", ["Coldtooth Supplies (Provided)"] = "припаси Кригозубих (видано)" } },
    [590] = { [1] = "Угода пройдисвіта", [2] = "Що?\n\nЩо?!\n\nХочеш гроші? Я тобі не винен жодних грошей.\n\nЛист? Який лист? Що, хочеш побитися? Що ж, {стать:друже:подруго}... зробімо це! Ну-ну, винен тобі гроші....", [3] = "Переможіть Кальвіна Монтенґ'ю в Смертедзвоні.", [4] = "Непогано, {стать:друже:подруго}, дуже навіть непогано.", [5] = "Надзвичайно! Які навички!\n\nДумав, ти будеш легкою здобиччю, {Ім'я}. Але {стать:спіймав:спіймала} ти мене добре.\n\nОсь, тримай монету, як і обіцялося... не так багато, як було сказано, але я ж і від початку не був з тобою чесним.", ["en"] = "A Rogue's Deal", ["tasks"] = { ["Defeat Calvin Montague"] = "Здолайте Кальвіна Монтеґ'ю" } },
    [5901] = { [1] = "Чуму на вас!", [2] = "Отже, щоб накликати біль і чвари на Багряний Похід, я хочу відняти у них їхню цінну лісопильню. Я впевнена, що втрата такого цінного ресурсу значно ослабить їх в обороні та відбудові містечка для їхніх потреб. Чи допоможеш ти мені, {ім'я:к}?\n\nПочни з того, що віднесеш цю банку в Чумолісся у Східних Зачумлених землях. Наповни її термітами з насипів, які знайдеш по лісу. Повертайся, коли будеш мати достатньо комах.", [3] = "Використайте порожню банку для термітів на термітниках у Східних Зачумлених землях. Після того, як назбираєте 100 термітів Зачумлених земель, поверніться до Мікі Левін на Валу в Тірісфальському переліссі.", [4] = "Ти вже маєш термітів, {Ім'я}? Я впевнена, що це неважко для {стать:такого кмітливого:такої кмітливої} {клас:р}, як ти.\n\nКоли ми матимемо їх достатньо, ми подбаємо про те, щоб ніхто не зміг знову користуватися цією лісопилкою!", [5] = "Ці чудово підійдуть, {Ім'я}. Дякую.\n\nЯкщо ти {стать:готовий:готова}, ми можемо перейти до наступного кроку.", ["en"] = "A Plague Upon Thee", ["tasks"] = { ["Empty Termite Jar"] = "порожня банка для термітів", ["Empty Termite Jar (Provided)"] = "порожня банка для термітів (видано)", ["Plagueland Termites"] = "терміти Зачумлених земель", ["Plagueland Termites (Provided)"] = "терміти Зачумлених земель (видано)" } },
    [5902] = { [1] = "Чуму на вас!", [2] = "Тепер, коли ми маємо вдосталь термітів, віднеси цю укріплену сталлю бочку до лісопильні Північного кряжу, що на півдні від Вогнедолу — ти знайдеш її на заході від дороги, що веде до цього містечка.\n\nЯк будеш там — постав бочку в центрі лісопильні, на щось високе, як ящик чи щось подібне.\n\nПісля того, як відкриєш її, все вирішиться саме собою. Просто повертайся сюди, і я тебе нагороджу за допомогу.", [3] = "Знайдіть зручне місце в центрі лісопильні Північного кряжу в Західних Зачумлених землях, щоб розмістити там бочку з термітами Зачумлених земель.", [5] = "Терміти явно починають метушитись, коли ви ставите бочку на ящик.", ["en"] = "A Plague Upon Thee", ["tasks"] = { ["Barrel of Plagueland Termites"] = "бочка з термітами Зачумлених земель" } },
    [591] = { [1] = "Око Розуму", [2] = "Око Розуму знаходиться в огра-мага на сході звідси, в глибинах огрівського згірка Мош'Оґґ. Його звуть Май'Зот. Я знаю його ще з часів, коли плем'я Темного Списа мешкало в Тернистій долині — він жорстокий, а його магія сильна.\n\nА якщо в нього є Око Розуму, то його магія ще сильніша.\n\nТи {стать:повинен:повинна} зустрітися з Май'Зотом і відібрати у нього Око Розуму. Це небезпечне завдання, але це наша єдина надія на порятунок Єнніку.", [3] = "Принесіть Око Розуму до Кін'вілея в військовий табір Ґром'ґол.", [4] = "Вітаю, {ім'я}. Духи співають про твою хоробрість, але вони не говорять про твою битву з Май'Зотом.\n\nТи {стать:дістав:дістала} Око?", [5] = "Тобі вдалося добути Око! Про твою могутність ходитимуть легенди, {ім'я}!\n\nКрім того, добуваючи Око, ти {стать:переміг:перемогла} Май'Зота, і {стать:відправив:відправила} його в Підсвіття. Ось чому духи мовчали про нього.\n\nДобре, що він пішов зі світу плоті та кісток, але тепер, коли він у царстві духів... я боюся, що Май'Зот знову прийде до влади.\n\nАле про це вже будемо турбуватися іншим разом. Зараз я повинен провести ритуал, щоб пристосувати Око Розуму для наших потреб...", ["en"] = "The Mind's Eye", ["tasks"] = { ["Mind's Eye"] = "Око Розуму", ["Mind's Eye (Provided)"] = "Око Розуму (видано)" } },
    [592] = { [1] = "Порятунок Єнніку", [2] = "Я перетворив Око Розуму на камінь душі. Він має два призначення: з його допомогою оглуши Єнніку, а потім поклади камінь йому на голову, щоб захопити його душу.\n\nПісля цього віднеси камінь Німбої.\n\nЄнніку мешкає разом із Занзілом-Вигнанцем у руїнах Абораз, вздовж Кришталевого узбережжя на далекому мисі Тернистої долини.", [3] = "Принесіть Німбої наповнений камінь душі.", [4] = "{ім'я}. Кін'вілей сказав мені, що відправив тебе за Єнніку.\n\nЦе правда? Він у тебе?", [5] = "Ти {стать:зробив:зробила} це! Ти {стать:звільнив:звільнила} Єнніку від волі Занзіла і {стать:виконав:виконала} завдання, яке здавалося мені таким безнадійним.\n\nНаше плем'я буде оспівувати твоє ім'я, {ім'я}, і ми викарбуємо повість про тебе на камені, щоб цієї історії ніколи не забули.", ["en"] = "Saving Yenniku", ["tasks"] = { ["Filled Soul Gem"] = "наповнений камінь душі", ["Filled Soul Gem (Provided)"] = "наповнений камінь душі (видано)" } },
    [5922] = { [1] = "Місячна галявина", [2] = "Усіх друїдів радо приймуть у священних землях Місячної Галявини — як тауренів, так і нічних ельфів. Хранитель Ремул наглядає над друїдами, що перебувають там в сплячці. Тепер, коли ти {стать:став:стала} на шлях Кігтя, я навчу тебе закляття, що дозволить переноситися туди. Застосуй його, коли шукатимеш знань чи спокою на Місячній галявині.\n\nТвій перший урок — відправитися до Місячної Галявини та поговорити з Дендритом Зіркосяйвом в Нічній Гавані про шлях, яким ти зараз йдеш. Щасти тобі, {стать:молодий:молода} {клас:к}.", [3] = "Використайте заклинання \"Телепорт: Місячна галявина\", щоб відправитися до Місячної галявини. Коли прибудете, поговоріть з Дендритом Зіркосяйвом в селищі Нічна Гавань.", [5] = "\"Так все й починається, Батьку Кенарію. Так все й починається.\"\n\nДендрит робить швидкий, непомітний рух над головою. Ледь помітна аура сили окутує його.\n\n\"Перша форма, до якої ти маєш пристосуватися — форма ведмедя. Я направлю тебе на шлях пізнання цього аспекту життя друїдів, та саме ти маєш прийняти й ширити його — зараз і навіки!\"", ["en"] = "Moonglade" },
    [5926] = { [1] = "Прислухаючись до поклику", [2] = "Перепрошую, на хвилинку...\n\nМені повідомили, що Турак Рунний Тотем хоче з тобою поговорити. Здається, твої друїдські тренування переходять на новий рівень і він особисто береться навчати тебе. Турак — один з помічників верховного друїда. Він відомий як мудрий і терплячий наставник; ти багато чому в нього навчишся.\n\nТи знайдеш його в Громовому Бескиді, всередині головного шатра Кенарійського Кола на Верхів'ї Старійшин.", [3] = "Поговоріть з Тураком Рунним Тотемом на Верхів'ї Старійшин в Громовому Бескиді.", [5] = "Я тішуся, що ти {стать:знайшов:знайшла} шлях сюди, {стать:юний:юна} {клас:к}. Настав час тобі зробити великий крок у ще більший світ.\n\nУ серці кожного з дітей Кенарія звучить поклик служіння природі. Тварини та рослини - наші друзі й наша опіка. Ми свідомо присвячуємо наші життя збереженню рівноваги заради їхнього і нашого блага. Щоб зробити перший крок у цей світ, ти {стать:повинен:повинна} навчитися мистецтву перетворення на ведмедя та опанувати силу тіла й серця.\n\nГотуйся!", ["en"] = "Heeding the Call" },
    [5927] = { [1] = "Прислухаючись до поклику", [2] = "Перепрошую, на хвилинку...\n\nМені повідомили, що Турак Рунний Тотем хоче з тобою поговорити. Здається, твої друїдські тренування переходять на новий рівень і він особисто береться навчати тебе. Турак — один з помічників верховного друїда. Він відомий як мудрий і терплячий наставник; ти багато чому в нього навчишся.\n\nТи знайдеш його в Громовому Бескиді, всередині головного шатра Кенарійського Кола на Верхів'ї Старійшин.", [3] = "Поговоріть з Тураком Рунним Тотемом на Верхів'ї Старійшин в Громовому Бескиді.", [5] = "Я тішуся, що ти {стать:знайшов:знайшла} шлях сюди, {стать:юний:юна} {клас:к}. Настав час тобі зробити великий крок у ще більший світ.\n\nУ серці кожного з дітей Кенарія звучить поклик служіння природі. Тварини та рослини — наші друзі й наша опіка. Ми свідомо присвячуємо наші життя збереженню рівноваги заради їхнього і нашого блага. Щоб зробити перший крок у цей світ, ти {стать:повинен:повинна} навчитися мистецтва перетворення на ведмедя та опанувати силу тіла й серця.\n\nГотуйся!", ["en"] = "Heeding the Call" },
    [5928] = { [1] = "Прислухаючись до поклику", [2] = "Перепрошую, на хвилинку...\n\nМені повідомили, що Турак Рунний Тотем хоче з тобою поговорити. Здається, твої друїдські тренування переходять на новий рівень і він особисто береться навчати тебе. Турак — один з помічників верховного друїда. Він відомий як мудрий і терплячий наставник; ти багато чому в нього навчишся.\n\nТи знайдеш його в Громовому Бескиді, всередині головного шатра Кенарійського Кола на Верхів'ї Старійшин.", [3] = "Поговоріть з Тураком Рунним Тотемом на Верхів'ї Старійшин в Громовому Бескиді.", [5] = "Я тішуся, що ти {стать:знайшов:знайшла} шлях сюди, {стать:юний:юна} {клас:к}. Настав час тобі зробити великий крок у ще більший світ.\n\nУ серці кожного з дітей Кенарія звучить поклик служіння природі. Тварини та рослини - наші друзі й наша опіка. Ми свідомо присвячуємо наші життя збереженню рівноваги заради їхнього і нашого блага. Щоб зробити перший крок у цей світ, ти {стать:повинен:повинна} навчитися мистецтву перетворення на ведмедя та опанувати силу тіла й серця.\n\nГотуйся!", ["en"] = "Heeding the Call" },
    [5930] = { [1] = "Дух Великого ведмедя", [2] = "У північно-західній частині Місячної галявини проживає мудра і благородна істота, котру ми називаємо духом Великого ведмедя. Для всіх друїдів він є наставником і вчителем, який дає початок розуміння справжньої природи ведмедя. Всі друїди в певний момент потребують мудрості цього створіння і ти — не вийняток.\n\nСкоріш йди до духа Великого ведмедя й осягни все, чому він захоче тебе навчити. Коли він буде задоволений тобою, повертайся в Нічну Гавань. Тоді й поглянемо, чи ти справді {стать:засвоїв:засвоїла} його уроки.", [3] = "Знайдіть дух Великого ведмедя на північному заході Місячної галявини та засвойте все, що він розкаже вам про природу ведмедя. Коли уроки будуть завершені, повертайтесь до Дендрита Зіркосяйво в Нічну Гавань на Місячній галявині.", [4] = "Повертайся тоді, коли дух Великого ведмедя відпустить тебе до мене. Без його благословіння ти не зможеш продовжити навчання.", [5] = "Дендрит робить ще один непомітний жест над головою при вашому наближенні. Його знову окутує аура сили й він ледь помітно посміхається.\n\n\"Я відчуваю мудрість в тобі, дитя, якої не було в момент нашої першої зустрічі. У твоєму погляді сила та усвідомлене прагнення, хоча ще не зовсім сформоване. Сьогодні ти навчишся зосереджувати свою силу і залучати природу ведмедя у своїх ділах.\"", ["en"] = "Great Bear Spirit", ["tasks"] = { ["Seek out the Great Bear Spirit and learn what it has to share with you about the nature of the bear."] = "Шукайте Великого Ведмедя-Духа та дізнайтеся, що він може вам розповісти про природу ведмедя." } },
    [5932] = { [1] = "Повернення в Громовий Бескид", [2] = "Настав час нашим шляхам розійтись, {стать:юначе:юнко}, адже для подальшого навчання тобі потрібно повернутися до того, хто прислав тебе до мене. Хоча таурени не так давно почали слідувати ученням Кенарія, Турак Рунний Тотем живе у гармонії з природою. Слухайся його настанов і зовсім скоро ти цілком засвоїш свої перші уроки, які і визначатимуть твою роль {стать:хранителя:берегині} балансу.\n\nА зараз йди, {стать:юначе:юнко}. Ми ще зустрінемось.", [3] = "Поверніться в Громовий Бескид і поговоріть із Тураком Рунним Тотемом на Верхів'ї Старійшин.", [5] = "З поверненням, {ім'я:к}. Я відчуваю, що твоя перша зустріч з духом Великого Ведмедя повпливала на тебе так, як і на інших друїдів, які ступили на шлях Пазура... Трохи збиває з пантелику, але вражає. Зі мною теж так було.\n\nДух Великого Ведмедя був частиною Азерот з самої її появи. Ми, таурени, уважно прислухаємось до таких духів і їх цілі ведуть нас до процвітання. Тепер настав час тобі пройти своє перше випробування на цьому шляху. Отже, слухай...", ["en"] = "Back to Thunder Bluff" },
    [596] = { [1] = "Намиста з кривавих кісток", [2] = "Мене відправили в Ґром'ґол, щоб допомогти Німбої в його пошуках, але... У мене є тут й свої справи.\n\nПлем'я Кровоскальпих — ворог нашого племені. Зібрані з ворогів трофеї дають нам владу над ними. Ти можеш допомогти нашому племені, полюючи на ворогів.\n\nВони живуть на півночі. Вбий якомога більше тролів з племені Кровоскальпих і забери у них намисто з кривавих кісток. Збери якнайбільше і я щедро віддячу тобі.", [3] = "Принесіть 25 намист з кривавих кісток Кін'вілею у військовий табір Ґром'ґол.", [4] = "Одного дня Темний Спис розчавить Кровоскальпих! Ти {стать:приніс:принесла} намисто наших приречених ворогів?", [5] = "О, дуже добре. Я зварю їх, висмокчу з них силу і духи наших ворогів ослабнуть!\n\nОсь, {ім'я}. Цього має бути достатньо, щоб віддячити тобі.", ["en"] = "Bloody Bone Necklaces", ["tasks"] = { ["Bloody Bone Necklace"] = "намисто з кривавих кісток", ["Bloody Bone Necklace (Provided)"] = "намисто з кривавих кісток (видано)" } },
    [5961] = { [1] = "Обранець Королеви-Банші", [2] = "Мені так подобається бачити, як до нашої боротьби приєднуються загартовані в битвах мандрівники. Наші ряди зростають у чисельності та силі з кожним днем. Можливо, ти {стать:готовий:готова} випробувати свої сили, {клас:к}?\n\nОдним з перших моїх обранців був Натанос, тепер відомий як Гнилоклич. Мало хто в наших лавах має більше відданості та запалу.\n\nЗнайди його у Східних Зачумлених землях. Він живе в маєтку Маррісів, час від часу блукаючи понищеною пусткою і вбиваючи всю скарівську й альянсівську мерзоту, яка зустрінеться на його шляху.", [3] = "Поговоріть з Натаносом Гнилокличем у Східних Зачумлених землях. Подейкують, що він проживає у маєтку Маррісів.", [5] = "Звісно ж, Темна Леді не вважає тебе {стать:достойним:достойною} зустрічі з її обранцем. Ти тут, щоб нагодувати моїх гончих, так? Інакше навіщо ти мене турбуєш?", ["en"] = "The Champion of the Banshee Queen" },
    [598] = { [1] = "Намиста з розщеплених кісток", [2] = "Тепер, коли ти {стать:зібрав:зібрала} трофеї з Кровоскальпих, я маю для тебе ще одне завдання. На південному сході живуть тролі з племені Черепотрощителів, ми воюємо з ними вже багато років. Хоч Темні Списи вже не мешкають у Тернистій долині, ми не забули про наші конфлікти.\n\nТож починай полювати на них. Збери якомога більше намист з розщеплених кісток і повертайся до мене. Допоможи нам у війні й тоді ти завоюєш визнання Темного Списа.", [3] = "Принесіть 25 намист з розщеплених кісток Кін'вілею у військовий табір Ґром'ґол.", [4] = "Черепотрощителі проклянуть той день, коли втягнули нас у війну! Ти {стать:виконав:виконала} завдання?", [5] = "В тебе велика сила, якщо тобі вдалось здобути ці намиста, {ім'я}. Черепотрощителі падали від твоїх ударів, як молоді саджанці під важкими кроками василіска!\n\nТвої діяння — дар для нас.", ["en"] = "Split Bone Necklace", ["tasks"] = { ["Split Bone Necklace"] = "намисто з розщеплених кісток", ["Split Bone Necklace (Provided)"] = "намисто з розщеплених кісток (видано)" } },
    [6002] = { [1] = "Тіло і серце", [2] = "В землях на захід від Таурахо в Степах — там, де вони переходять у Мулґор — знаходиться камінь місячного совуха. Місячні совухи — звірі особливі, в тутешніх краях вони не живуть. Місяцекіготь, захисник каменю, з'явиться перед тобою коли ти посиплеш камінь кенарійським місячним пилом. Місяцекіготь таїть в собі силу, якою ти, як {стать:один:одна} з друїдів Пазура, {стать:повинен:повинна} володіти.\n\nТи {стать:заслужив:заслужила} право користуватися цим кенарійським місячним пилом, {ім'я:к}... тепер доведи мені, що ти також заслуговуєш володіти силами тіла і серця, які так необхідні друїду!", [3] = "Посипте кенарійським місячним пилом на камінь місячного совуха між Мулґором та Степами, щоб викликати Місяцекігтя. Переможіть його та отримайте силу тіла і серця, якими він володіє.\n\nПо завершенню, поговоріть з Тураком Рунним Тотемом в Громовому Бескиді.", [4] = "Доки ти не приймеш виклик, що чекає тебе, ти не зумієш цілком пізнати силу тіла і серця. До тих пір я нічим не зможу тобі помогти.", [5] = "Це твій перший крок на шляху до великих звершень, {ім'я:к}. Я відчуваю вчення духа Великого ведмедя в тобі й бачу, що ти {стать:перейняв:перейняла} силу Місяцекігтя.\n\nБільш нічого тобі не перешкоджає... дозволь мені тепер навчити тебе, що означає бути {клас:о} Пазура!", ["en"] = "Body and Heart", ["tasks"] = { ["Face Lunaclaw and earn the strength of body and heart it possesses."] = "Зіткніться з Лунаклогом і здобудьте силу тіла та серця, якою він володіє." } },
    [6022] = { [1] = "Умисне вбивство", [2] = "Якщо хочеш працювати зі мною — готуйся вбивати.\n\nТвоє перше завдання — нагодувати моїх псів.\n\nВізьми ступку та товкач і відправляйся до перехрестя Коріна. Там у тебе буде широкий вибір Скари, яку треба вбити. З їхніх свіжих туш ти маєш зібрати живу гниль. Кинь її до ступки, подрібни та дай настоятися, щоб вона згусла. Принеси згущену гниль мені.\n\nІ, дурепо, жива гниль з не довго залишиться \"живою\". Ти маєш вбивати їх швидко!", [3] = "Відправляйтеся до перехрестя Коріна на схід та вбийте членів Скари, що населяють місто. Зберіть 7 шматків живої гнилі не більше ніж за 10 хвилин. За допомогою ступки та товкача перетворіть живу гниль у згущену гниль.", [4] = "{Ім'я}, ти що, плачеш? Якщо ця робота не для тебе, раджу тобі чухати назад до Темної Леді та розказати їй, як погано ставилися до тебе на моїй фермі.\n\nА тепер геть звідси!", [5] = "Шкода. Я сподівався, що нагодую своїх гончаків тобою.\n\n<Натанос позіхає.>\n\nНу добре, принаймні у них є що поїсти.", ["en"] = "To Kill With Purpose", ["tasks"] = { ["Coagulated Rot"] = "згущена гниль", ["Coagulated Rot (Provided)"] = "згущена гниль (видано)" } },
    [6029] = { [1] = "Доповідь з Завшегляду", [2] = "Я шукаю відповідального працівника, що допоможе мені у невеликій, але важливій справі. Я представляю інтереси Сріблястого Світанку в місцевому управлінні Завшегляда. Мені потрібно передати доповідь офіцеру Сріблястого Світанку Ґарушу на Валу. Це далеко звідси, в Західних Зачумлених землях.\n\nЯкщо мені це вдасться, це буде чудова нагода представити тебе моєму начальнику й можливо, знайти для тебе трохи роботи!", [3] = "Передайте доповідь з Завшегляду офіцеру Сріблястого Світанку Ґарушу на Вал, що в Західних Зачумлених землях.", [4] = "Вітаю, {клас:к}. Від імені Сріблястого Світанку я забезпечу тобі безпеку і притулок, поки ти тут, на Валу. Я також можу запропонувати тобі можливість боротися за справу, за яку варто боротися!", [5] = "Грегор досить винахідливий, як для людини. Він вже довгий час має справу з картелем Паровиманювання і став експертом у \"мистецтві\" переговорів з гоблінами. Хоч це й правда, що головні уподобання гоблінів лежать в руках тих, у кого найбільші гаманці, вони також знають і поважають цінність дипломатії. Якщо вона так чи інакше забезпечує їм постійних клієнтів...\n\nВ будь-якому випадку, Сріблястий Світанок визнає твої зусилля. Будь ласка, прийми це на знак нашої подяки.", ["en"] = "The Everlook Report", ["tasks"] = { ["Everlook Report"] = "доповідь з Завшегляду", ["Everlook Report (Provided)"] = "доповідь з Завшегляду (видано)" } },
    [6042] = { [1] = "Незручності нежиття", [2] = "Ти не зможеш зробити й двох кроків не напоровшись на одного з цих бісових кажанів. Я хочу спокійно брати своїх собак та займатися винищенням Скари, не відволікаючись на цих клятих кажанів. Очевидно, що мені є чим займатися замість того, щоб полювати на кажанів. Проте у тебе є купа вільного часу.\n\nЩо? Ти тренуєшся? Це і є твоє тренування! А тепер не муляй мені очі та не повертайся, доки не вб'єш кілька десятків цих крилатих мерзотників. Не розчаруй мене.", [3] = "Вбийте 20 згубних чумних кажанів та 10 жахливих чумних кажанів. Поверніться до Натаноса Гнилоклича, коли завершите завдання.", [4] = "Могло бути й гірше. Я міг би тебе змусити збирати їхнє гуано.\n\n<Натанос задумливо дивиться на вас.>\n\nГм... Гей! Ану зачекай. Куди це ти?", [5] = "Просто неймовірно, чого можна досягти завдяки гніву та злобі.", ["en"] = "Un-Life's Little Annoyances", ["tasks"] = { ["Monstrous Plaguebat"] = "жахливий чумний кажан", ["Monstrous Plaguebat slain"] = "жахливий чумний кажан: убито", ["Noxious Plaguebat"] = "згубний чумний кажан", ["Noxious Plaguebat slain"] = "згубний чумний кажан: убито" } },
    [6061] = { [1] = "Приборкання звіра", [2] = "Для таурена важливо дотримуватись звичаїв своїх предків під час боротьби з могутніми створіннями. Перемагаючи їх, ми вбираємо в себе їх дух, стаючи ближче до Матері-Землі.\n\nТак само й приборкання звіра, з яким ти будеш битись разом, робить тебе ближче до природи, що оточує нас. Врешті-решт, ти зможеш приручити звіра собі до вподоби. Та спершу тобі доведеться повчитись. Візьми цей жезл приборкання і потренуйся, приручивши дорослого рівнинобіга.", [3] = "Приборкайте дорослого рівнинобіга за допомогою жезлу приборкання. Попрактикуйтесь, після чого повертайтесь до Йова Гострогрива в селище Криваве Копито.", [4] = "Потренуй свої навички, {ім'я:к}. Приборкай дорослого рівнинобіга.", [5] = "Матір-Земля дала мені знак. Ти чудово {стать:впорався:впоралась}.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6062] = { [1] = "Приборкання звіра", [2] = "Керування створіннями природи — велике вміння. Як {клас}, ти маєш навчитись використовувати силу і міць, що притаманні обраним тобою створінням.\n\nУтримання контролю над звіром — непроста справа. Тобі знадобиться вся твоя рішучість.\n\nДля твого першого завдання візьми цей жезл приборкання і за допомогою нього приборкай лютого крапчастого кнура. Ти знайдеш їх біля Колючого Пагорба. Попрактикуй свої вміння з кнурами та повертайся до мене.", [3] = "Приборкайте лютого крапчастого кнура за допомогою жезлу приборкання. Попрактикуйтесь, після чого поверніть жезл приборкання Тотару на Колючий Пагорб.", [4] = "Успіхів, {стать:юний:юна} {клас:к}.", [5] = "Ти чудово {стать:впорався:впоралась}, {ім'я:к}. Схоже, що ти {стать:готовий:готова} до наступного завдання.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6065] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Йовом Гострогривом в селищі Криваве Копито. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Йовом Гострогривом в селищі Криваве Копито.", [5] = "Так, прийшов час почати твоє навчання.", ["en"] = "The Hunter's Path" },
    [6066] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Йовом Гострогривом в селищі Криваве Копито. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Йовом Гострогривом в селищі Криваве Копито.", [5] = "Так, схоже, що ти {стать:готовий:готова}...", ["en"] = "The Hunter's Path" },
    [6067] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Йовом Гострогривом в селищі Криваве Копито. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Йовом Гострогривом в селищі Криваве Копито.", [5] = "Так, схоже, ти {стать:готовий:готова}...", ["en"] = "The Hunter's Path" },
    [6068] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Тотаром на Колючому Пагорбі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Тотаром на Колючому Пагорбі.", [5] = "Так, думаю, ти {стать:готовий:готова}....", ["en"] = "The Hunter's Path" },
    [6069] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Тотаром на Колючому Пагорбі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Тотаром на Колючому Пагорбі.", [5] = "Так, думаю, ти {стать:готовий:готова} до тренувань....", ["en"] = "The Hunter's Path" },
    [6070] = { [1] = "Шлях мисливця", [2] = "Вітаю, {стать:юний:юна} {клас:к}. Здається, ти вже достатньо {стать:досвідчений:досвідчена}, щоб приборкати звіра і навчити його бути чудовим компаньйоном.\n\nТи маєш зустрітись з Тотаром на Колючому Пагорбі. Він допоможе тобі здобути чудового супутника.", [3] = "Поговоріть з Тотаром на Колючому Пагорбі.", [5] = "Так, думаю, прийшов час навчати тебе....", ["en"] = "The Hunter's Path" },
    [6081] = { [1] = "Тренування звіра", [2] = "Тепер ти вмієш приручати звірів, та ще тобі доведеться навчитись їх дресувати.\n\nВідправляйся до Орґріммару. Там ти поговориш з одним з наших найшанованіших мисливців — Ормаком Лютострілом. Він навчить тебе дресування. Ти знайдеш його біля залу Відваги.\n\nНехай щастить, {ім'я:к}.", [3] = "Поговоріть з Ормаком Лютострілом в Орґріммарі.", [5] = "А, {стать:юний:юна} {клас}. Так, я навчу тебе вмінням, необхідним для дресування твого улюбленця. Ти навчишся не тільки навчати його нових здібностей, а й годувати та повертати до життя, коли знадобиться.\n\nТепер йди, {клас:к}. Ми побачимось знову, як прийде час.", ["en"] = "Training the Beast" },
    [6082] = { [1] = "Приборкання звіра", [2] = "Останній звір, якого тобі належить приборкати — броньований скорпід. Він б'є різко і наповал, та як {клас} ти маєш вміти давати раду і таким сильним створінням.\n\nЯк повернешся — я навчу тебе самостійно приборкувати звірів собі до вподоби. Під твоїм командуванням звір буде вірним союзником і отримуватиме досвід в бою разом з тобою. А ще я навчу тебе викликати та відпускати його по твоїй волі.", [3] = "Приборкайте броньованого скорпіда за допомогою жезлу приборкання. Попрактикуйтесь, після чого повертайтесь до Тотара на Колючий Пагорб.", [4] = "Ти {стать:зміг:змогла} приборкати скорпіда?", [5] = "Ти {стать:навчився:навчилась} всьому, що я міг тобі розказати, {ім'я:к}. Прийшов час використати на практиці все, про що я розповідав і вибрати собі супутника.\n\nОтож, {ім'я:к}, тепер я навчу тебе приборкання звіра, а також як викликати та відпускати його по своїй волі. Користуйся своїми навичками з гордістю, ти на це {стать:заслужив:заслужила}.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6083] = { [1] = "Приборкання звіра", [2] = "Твій супутник подарує тобі чималу перевагу в бою, {ім'я:к}. Приборкуючи звіра, ти отримуєш і його силу. Ти стаєш з ним одним цілим.\n\nТвоє наступне завдання відправить тебе до моря. Там, на узбережжі, між селищем Сен'джин та островами Ехо, ти знайдеш наступного звіра — спритного краба, що називається береговим повзуном. Приборкай його за допомогою жезлу приборкання і попрактикуйся.", [3] = "Приборкайте берегового повзуна за допомогою жезлу приборкання. Попрактикуйтесь, після чого повертайтесь до Тотара на Колючий Пагорб.", [4] = "Ти маєш практикуватись, щоб навчитись добре керувати своїм супутником. Ти вже {стать:приборкав:приборкала} берегового повзуна?", [5] = "А ти швидко вчишся, {ім'я:к}. Молодець.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6087] = { [1] = "Приборкання звіра", [2] = "Ти маєш запальний дух, {клас:к}. Бачу, ти з нетерпінням чекаєш на новий виклик.\n\nТвоє наступне завдання — приручити вовка, що зветься степовим ловцем. Створіння це напрочуд стрімке та безстрашне. Приймаючи його своїм компаньйоном, ти також маєш прийняти його здібності.\n\nПід час бою ти навчишся працювати зі своїм супутником в команді. Врешті-решт ви станете єдиним цілим, б'ючись пліч-о-пліч.\n\nОсь, тримай цей жезл приборкання, {ім'я:к}. Приручи степового ловця і попрактикуй свої навички.", [3] = "Приборкайте степового ловця за допомогою жезлу приборкання. Попрактикуйтесь, після чого повертайтесь до Йова Гострогрива в селище Криваве Копито.", [4] = "Ти {стать:знайшов:знайшла} степового ловця?", [5] = "Так... Матір-Земля каже, що ти {стать:готовий:готова} до наступного уроку.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6088] = { [1] = "Приборкання звіра", [2] = "Останнім твоїм завданням стане приборкання жителя неба. Хапун — важкий супротивник, та він може стати грізним союзником, рубаючи твоїх ворогів.\n\nЗ волі Матері-Землі, коли ти повернешся, я навчу тебе, як приручити звіра, що стане твоїм вірним супутником. Це створіння допоможе тобі в боротьбі з загрозами та отримуватиме разом з тобою досвід в бою. Також я навчу тебе, як викликати та відпускати його по твоїй волі.", [3] = "Приборкайте хапуна за допомогою жезлу приборкання. Попрактикуйтесь, після чого повертайтесь до Йова Гострогрива в селище Криваве Копито.", [4] = "Незабаром ти будеш {стать:готовий:готова}, {ім'я:к}.", [5] = "Ти {стать:навчився:навчилась} всьому, що я міг тобі розказати, {ім'я:к}. Хай благословення Матері-Землі допоможе тобі у виборі супутника.\n\nОтож, {ім'я:к}, тепер я навчу тебе приборкання звіра, а також як викликати та відпускати його по своїй волі. Користуйся своїми навичками з гордістю та шаною до Матері-Землі.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [6089] = { [1] = "Тренування звіра", [2] = "Тепер ти вмієш приручати звіра, та ще ти маєш навчитись його дресувати.\n\nЙди до Громового Бескиду. Там ти маєш поговорити з одним з наших найшанованіших мисливців — Гольтом Громовим Рогом. Якщо він визнає тебе {стать:гідним:гідною}, то навчить дресування твого нового супутника.\n\nГольт поборов наймогутніших та найстрашніших звірів Азероту і приборкував багатьох сильних створінь. Його зв'язок з Матір'ю-Землею сильний і ти навчишся у нього багатьом речам. Нехай щастить, {ім'я:к}.", [3] = "Поговоріть з Гольтом Громовим Рогом на Верхів'ї Мисливців у Громовому Бескиді.", [5] = "А, {стать:юний:юна} {клас}. Так, я поділюсь з тобою знаннями, необхідними для дресування твого улюбленця. Ти навчишся не тільки навчати його нових здібностей, а й годувати та повертати до життя, коли знадобиться.\n\nТепер йди. Нехай Матір-Земля направляє тебе на шляху. Ми побачимось знову, як прийде час.", ["en"] = "Training the Beast" },
    [6126] = { [1] = "Новий урок", [2] = "Тепер, {ім'я:к}, ти {стать:готовий:готова} більше дізнатися про отрути та про владу, яку ми, друїди, маємо над ними. Кенарій дарував нам вміння виводити з тіла найгірші отрути за допомогою простих чар. Цей дар не варто сприймати легковажно... Тож, для засвоєння цього, тобі доведеться впоратись з отрутою самостійно, своїми силами.\n\nВідправляйся на Місячну галявину і поговори з Дендритом Блиском Зірок — він очікує на твоє прибуття, щоб почати навчання.", [3] = "Відправляйтесь на Місячну галявину і поговоріть з Дендритом Зіркосяйвом в селищі Нічна Гавань.", [5] = "Вітаю, {стать:юний:юна} {клас:к}. Я радий бачити, що ти {стать:готовий:готова} і прагнеш дізнатись більше про зцілення від отрут.\n\nХоча більшість друїдів проходили певні випробування, тобі цього не знадобиться. В Перехресті, що в Степах, стався сплеск отруєння тварин і місцеві жителі не змогли з цим справитись. Вони попросили Місячну галявину про допомогу, тож ми відправимо тебе. Це не тренування — завдання серйозне і небезпечне, май це на увазі.", ["en"] = "Lessons Anew" },
    [6127] = { [1] = "Первісне джерело", [2] = "Вершина Зловісного Туману, що на північний захід від Перехрестя, — найімовірніше джерело розповсюдження отрути. Там знаходяться озера, випаровування з яких розносяться вітрами по всіх Степах. Я підозрюю, що їх води нині забруднені демонопоклонниками Палаючого Леза.\n\nВізьми цей флакон і набери в нього води з вершини. Як наповниш — віднеси його Тонзі Рунному Тотему на Перехрестя. Саме він попросив нас про допомогу, тож ти відправишся йому на поміч.", [3] = "Використайте пустий флакон вершини Зловісного Туману, щоб взяти пробу води з озер на вершині.\n\nВіднесіть наповнений флакон вершини Зловісного Туману Тонзі Рунному Тотему в Перехрестя, що в Степах.", [4] = "Тебе прислало Кенарійське Коло з Місячної галявини, так? Це неймовірно! Нам не вистачає сил для допомоги нещасним хворим газелям в північних Степах. Ми будемо раді твоїй допомозі.\n\nТи {стать:приніс:принесла} зразок води, про який казав Дендрит Зіркосяйво? Він сказав, що ти принесеш воду і допоможеш нам зі зціленням...", [5] = "Клянусь предками, це просто мерзенна вода! Не дивно, що газелі захворіли.\n\nЩось забруднює воду на вершині Зловісного Туману і, як наслідок, вражає екосистему всіх північних Степів. Хворих газелей бачили всюди на північ від цієї дороги зі сходу на захід. Хоч вода і є первісним джерелом забруднення, тут щось не чисто.\n\nВір чи ні, та ця вода допоможе нам створити ліки. А поки я досліджуватиму воду, ти допоможеш мені зібрати інгредієнти для ліків...", ["en"] = "The Principal Source", ["tasks"] = { ["Filled Dreadmist Peak Sampler"] = "наповнений флакон вершини Зловісного Туману", ["Filled Dreadmist Peak Sampler (Provided)"] = "наповнений флакон вершини Зловісного Туману (видано)" } },
    [6128] = { [1] = "Створення ліків", [2] = "Основою цілющої мазі для газелей послужить вода. Для надання їй цілющої сили, мені знадобиться землекорінь. Травники знають де його шукати, тому якщо тобі не пощастило і ти не {стать:один:одна} з них — доведеться знайти когось, хто допоможе.\n\nДля підсилення ефективності мазі мені потрібні роги кодо — уламки не підійдуть. Кодо, з якими ти впораєшся, мешкають на півночі Степів. Вбий кілька звірів, заразом і природний баланс відновиться, {ім'я:к}. Відпиляй у них роги та принеси мені.", [3] = "Принесіть 5 землекоренів і 5 рогів кодо Тонзі Рунному Тотему на Перехрестя, щоб він приготував цілющу мазь.", [4] = "Ти {стать:зібрав:зібрала} складники, необхідні для приготування мазі? Самі собою газелі не зціляться, тому нам краще поспішити їм на поміч!", [5] = "Чудово, {ім'я:к}, ти {стать:приніс:принесла} так багато, що мені має вистачити на кілька великих доз мазі — принаймні, щоб зцілення почалось.\n\nПриготування засобів проти отрут інколи буває досить складним, оскільки кожен потребує певного антидота для нейтралізації дії отрути. Чудово було б вміти в будь-який момент лікувати отруєння, не переживаючи про інгредієнти для антидота.\n\nА зараз мені треба попрацювати над цим!", ["en"] = "Gathering the Cure", ["tasks"] = { ["Earthroot"] = "землекорінь", ["Earthroot (Provided)"] = "землекорінь (видано)", ["Kodo Horn"] = "ріг кодо", ["Kodo Horn (Provided)"] = "ріг кодо (видано)" } },
    [6129] = { [1] = "Зцілення хворих", [2] = "Мазі, виготовленої з інгредієнтів, які ти {стать:приніс:принесла} мені, {ім'я:к}, вистачить на десять доз. Поки я працюю тут, в селищі, намагаючись виготовити якомога більше цієї мазі, я хотів би, щоб ти {стать:допоміг:допомогла} нам почати зцілення. По всій північній частині Степів бродять хворі газелі. Скористайся цією маззю для їх зцілення.\n\nЯ впевнений, Дендрит Зіркосяйво з Місячної галявини захоче поговорити з тобою, коли ти закінчиш. Будь ласка, передай нашу подяку Кенарійському Колу... і дозволь мені подякувати тобі особисто за допомогу!", [3] = "Нанесіть мазь для зцілення тварин на 10 хворих газелей, що мешкають в північній частині Степів, — це має їх зцілити. За чутками, хворі газелі живуть північніше дороги, яка проходить через Перехрестя зі сходу на захід.", [4] = "Ти {стать:завершив:завершила} те, про що тебе просив Тонґа Рунний Тотем на Перехресті? Твоє завдання ще не виконане.", [5] = "Ти добре {стать:зробив:зробила}, що {стать:потурбувався:потурбувалася} про хворих газелей Степів; це мимовільні жертви прокльону й осквернення, яке розповзається по всьому краю. Ти, {раса:н}, краще інших осягаєш мудрість Кенарія. Ти, як і мудреці з Громового Бескиду, відчуваєш, що необхідність досягнення балансу вища за штучні міжрасові кордони.\n\nХай там що, ти {стать:довів:довела}, що ти — друг природи та Кола; прийми це як відзнаку цієї твоєї якості.", ["en"] = "Curing the Sick", ["tasks"] = { ["Sickly Gazelle cured"] = "Хвора Газель вилікувалась", ["Sickly Gazelle cured (Provided)"] = "Хвора Газель вилікувалась (видано)", ["Sickly Gazelle cured slain"] = "Хвора Газель вилікувалась: убито" } },
    [6130] = { [1] = "Влада над отрутою", [2] = "Ти {стать:засвоїв:засвоїла}, як це, зцілювати від отрути без допомоги духів. Пам'ятай, чого ця боротьба вартує іншим, коли прийматимеш цей дар влади над отрутою.\n\nПовертайся до Турака Рунного Тотема в Громовий Бескид, {ім'я:к}. Тепер, коли ти {стать:засвоїв:засвоїла} цей важливий урок, він навчить тебе важливого заклинання.\n\nНехай тобі щастить, {стать:юний:юна} {клас:к}. Ми зустрінемось знову.", [3] = "Поверніться до Турака Рунного Тотема на Верхів'я Старійшин, що в Громовому Бескиді.", [5] = "З поверненням! Я слідкував за твоїми успіхами відколи ти {стать:покинув:покинула} нас і, зізнаюсь, я був вражений, коли дізнався про те, що сталося в Аубердіні. Ми маємо більше дізнатись про це — така отрута не залишиться непоміченою для балансу природи.\n\nТи чудово {стать:проявив:проявила} себе в цій ситуації. За це я винагороджу тебе владою над отрутою. Використовуй її мудро, {ім'я:к}.", ["en"] = "Power over Poison" },
    [6133] = { [1] = "Наказ ватажка слідопитів", [2] = "Вищі ельфи хижини Квел'Лішен мають дещо, що належить мені, {клас:к} — папери, в яких детально описується моє смертне життя.\n\nІ ні, тебе це ніяк не стосується, тож навіть не здумай сунути туди ніс! Просто роби, що я кажу, нікчемо — поверни реєстр.\n\nІ ще, дурепо, не забудь залишити після себе якомога більше шкоди. Нехай вони страждають...", [3] = "Відправляйтеся до північних кордонів Східних Зачумлених земель та добудьте реєстр Квел'Таласа. Він знаходиться десь в хижині Квел'Лішен.\n\nВи також маєте вбити 8 слідопитів, 8 розвідниць та 8 лісників.", [4] = "Не змушуй мене чекати, {клас:к}.", [5] = "Я знаю, що ти не {стать:читав:читала} реєстр. Це надто ідіотський вчинок навіть для тебе.", ["en"] = "The Ranger Lord's Behest", ["tasks"] = { ["Pathstrider"] = "розвідниця", ["Pathstrider slain"] = "розвідниця: убито", ["Quel'Thalas Registry"] = "реєстр Квел'Таласа", ["Quel'Thalas Registry (Provided)"] = "реєстр Квел'Таласа (видано)", ["Ranger"] = "слідопит", ["Ranger slain"] = "слідопит: убито", ["Woodsman"] = "лісник", ["Woodsman slain"] = "лісник: убито" } },
    [6135] = { [1] = "Смеркокрил, шляк би його трафив...", [2] = "Що ж, ти {стать:виконав:виконала} всі мої завдання, хоч і не надто швидко.\n\nПевно, ти вже {стать:готовий:готова} до справжнього виклику. Так... Так, притрушене ти створіння, можливо ти й справді {стать:готовий:готова} до тяжчого завдання.\n\nДемонічний кажан альбінос — Смеркокрил, блукає на півночі звідси. Вистеж його та знищ. Повернися до мене зі жмутом його хутра і я дам тобі нагороду.", [3] = "Знайдіть Смеркокрила та вбийте його. Візьміть з його трупа жмут хутра та поверніться до Натаноса Гнилоклича.", [4] = "Я б не радив тобі виконувати це завдання самостійно, {клас:к}.", [5] = "Прекрасна робота, дурепо. Тепер я маю почаклувати над цим хутром, щоб ти {стать:міг:могла} ним користуватися.", ["en"] = "Duskwing, Oh How I Hate Thee...", ["tasks"] = { ["Patch of Duskwing's Fur"] = "жмут хутра Смеркокрила", ["Patch of Duskwing's Fur (Provided)"] = "жмут хутра Смеркокрила (видано)" } },
    [6136] = { [1] = "Товстун", [2] = "За табором Сріблястого Світанку і Каплицею Надії Світла, на захід від Північнодолу, ти знайдеш товстезного черв'яка, Гидкослиза.\n\nЯ втратив цілі полки через це чудовисько. Його розміри неймовірні! Що більше він їсть, то більше росте...\n\nХоча мені загалом все одно, чи зжере тебе хробак, все ж краще, щоб ти {стать:залишився живим:залишилася живою}. Я рекомендую тобі попросити когось про допомогу. Гидкослиз охоче пожирав маленькі групи безумців, що спробували напасти на нього.", [3] = "Знайдіть Гидкослиза в північній пустці Східних Зачумлених земель та вбийте його. Поверніться до Натаноса Гнилоклича коли виконаєте завдання.", [4] = "Я вже казав, що я ненавиджу тебе?", [5] = "Продовжуй у тому ж дусі, і можливо я підвищу тебе з {стать:імбецила:імбецилки} до розумово {стать:відсталого:відсталої}.", ["en"] = "The Corpulent One", ["tasks"] = { ["Borelgore"] = "Гидкослиз", ["Borelgore slain"] = "Гидкослиз: убито" } },
    [6142] = { [1] = "Приманка з молюска", [2] = "Ти {стать:схожий:схожа} на рибалку, {клас:к}! Я люблю рибалити — рибалю все життя. Найкраща наживка — м'ясо м'якопанцирного молюска, риба просто не може встояти, можеш мені повірити.\n\nНа півночі звідси, біля узбережжя, ти знайдеш затонулий корабель. М'якопанцирні молюски так і кишать навколо нього. Якщо ти принесеш мені 10 шматків м'яса м'якопанцирного молюска, я натомість дам тобі дещо корисне.", [3] = "Знайдіть 10 шматків м'яса м'якопанцирного молюска і принесіть їх до Май'Лагі в селище Тінездобич.", [4] = "Не можу дочекатися, щоб піти на риболовлю зі свіжим м'ясом м'якопанцирних молюсків. Ти ж {стать:приніс:принесла} мені 10 шматочків, як я просила?", [5] = "Це просто чудово. Знаєш, що знахар сказав на рахунок мого головного болю? Він сказав: \"Май'Лагі, йди рибалити. Тобі стане легше\".\n\nНу, мені й справді стає легше, дякую!", ["en"] = "Clam Bait", ["tasks"] = { ["Soft-shelled Clam Meat"] = "м'ясо м'якопанцирного молюска", ["Soft-shelled Clam Meat (Provided)"] = "м'ясо м'якопанцирного молюска (видано)" } },
    [6143] = { [1] = "Цікавіші справи", [2] = "Можливо, ти {стать:чув:чула}, а може й ні... ми з командою рибалили неподалік острова Раназжар, північніше від затонулого корабля, на північному узбережжі. Ми постійно рибалили там, а тепер я ні про що інше не можу думати, окрім як про помсту за своїх друзів.\n\nОдного ранку на нас напали наги та вбили всіх, окрім мене.\n\nЯ не можу змиритися з провиною, {клас:к}. Я хочу, щоб ти {стать:пішов туди й розправився:пішла туди й розправилася} з цими нагами. Я добряче віддячу тобі. Ти ж мені допоможеш?", [3] = "Убийте 7 слизькорізих мірмідонів, 7 слизькорізих наг і 5 слизькорізих чаклунок, а потім поверніться у селище Тінездобич в Спустошищі та поговоріть з Друлзеґаром.", [4] = "Я досі чую їхні голоси, як вони кликали на допомогу, коли наги спустили на нас усю свою лють. Якби моє коліно було здоровим, я б пішов і допоміг тобі вбити цих клятих наг!\n\nЗазвичай, їх можна знайти глибоко під поверхнею, в коралових рифах... вони ховаються... готують свої підступні плани...", [5] = "Як же приємно слухати про перемогу над нагами, але в моєму серці все ще порожньо. Я присвячу все своє життя тому, щоб знищити їх усіх.\n\nОсь твоя винагорода, як я й обіцяв. Хоча вона невелика в порівнянні з моєю вдячністю.", ["en"] = "Other Fish to Fry", ["tasks"] = { ["Slitherblade Myrmidon"] = "слизькорізий мірмідон", ["Slitherblade Myrmidon slain"] = "слизькорізий мірмідон: убито", ["Slitherblade Naga"] = "слизькоріза нага", ["Slitherblade Naga slain"] = "слизькоріза нага: убито", ["Slitherblade Sorceress"] = "слизькоріза чаклунка", ["Slitherblade Sorceress slain"] = "слизькоріза чаклунка: убито" } },
    [6144] = { [1] = "Наказ командування", [2] = "Прийшов наказ, {клас:к}. Сам Варіматрас попросив мене відправити своїх \"найздібніших\" агентів до Підмістя для виконання надважливої тактичної операції.\n\nНа жаль, мої найздібніші агенти загинули понад три роки тому. А замість них у мене є ціла купка недоумків.\n\n<Натанос холодно витріщається на вас.>\n\nНегайно вирушай до Підмістя та звітуй Варіматрасу. Не осором мене, {клас:к}!", [3] = "Відправляйтеся до Підмістя та поговоріть з Варіматрасом.", [5] = "Верховний лицар спокійно сидить в Багряному бастіоні, поки його війська хазяйнують у наших краях, вбиваючи та нищачи все на своєму шляху.\n\nТемна Леді наказала мені розібратися з цим слимаком та назавжди. І ти станеш тим самим знаряддям відплати відречених.", ["en"] = "The Call to Command" },
    [6146] = { [1] = "Хитрість Натаноса", [2] = "Я вніс деякі зміни в цей наказ. Якщо наша витівка спрацює, Багряний Оракул залишиться без захисту, і тоді ми завдамо їм удару!\n\nТепер слухай уважно, {клас:к}. Ти маєш доставити цей наказ лорду Вальдемару.\n\nЯк? Особисто йому в руки, дурепо.\n\nВізьми цей наказ і гниле яблуко та іди до Десниці Тіра. Як опинишся там — з'їж яблуко. Ти перетворишся на щось... прийнятніше для людського ока. Візьми наказ та віддай його особисто лорду Багряного Походу, Вальдемару.", [3] = "Відправляйтеся до Десниці Тіра, на південний схід маєтку Маррісів. Опинившись там, відкусіть гниле яблуко. Під виглядом члена Багряного Походу передайте наказ верховного лицаря лорду Багряного Походу Вальдемару.", [4] = "Це неприпустимо, солдате!", [5] = "Де тебе носило? Ми вже подумали, що тебе зжерла Скара.", ["en"] = "Nathanos' Ruse", ["tasks"] = { ["The Grand Crusader's Command"] = "наказ верховного лицаря", ["The Grand Crusader's Command (Provided)"] = "наказ верховного лицаря (видано)" } },
    [6147] = { [1] = "Повернення до Натаноса", [2] = "Верховний лицар прислав дуже незвичний наказ. Гм, не дивлячись на це... все що він скаже, буде виконано. Повертайся до Багряного бастіону та повідом, що Оракул висувається негайно.\n\nМи докладемо усіх зусиль, щоб впевнитися, що вона добереться до Стратгольму цілою та неушкодженою.", [3] = "Поверніться до Натаноса Гнилоклич з новою інформацією.", [5] = "Дурні! Мій обман ніхто не помітив! Приготуйся, {клас:к}. Настав час завдати вирішального удару!", ["en"] = "Return to Nathanos" },
    [6148] = { [1] = "Багряний Оракул, Деметрія", [2] = "Деметрія — головна радниця верховного лицаря. Її називають Оракулом через її \"потойбічне\" чуття. Завдяки їй Багряний Похід отримав низку перемог над Скарою.\n\nЯкщо наша хитрість спрацює, ми побачимо, чи справді вона володіє силами провидіння. Тоді вона буде очікувати на неприємності. Ти і забезпечиш їй ці \"неприємності\".\n\nВистеж Оракула та вбий її. Поки ми говоримо, вони саме мають вирушати з Десниці Тіра. Зроби так, щоб я тобою пишався, нікчемо.", [3] = "Багряний Похід вирушив в дорогу. Десь на шляху від Десниці Тіра до Стратгольму ви знайдете Оракула, Деметрію та її охорону. Вистежте її та вбийте. Поверніться до Натаноса Гнилоклича після успішного завершення завдання.", [4] = "Який статус твого завдання, {ім'я}?", [5] = "Вони роками будуть оговтуватися від цього удару! Молодець, {ім'я}! Ти {стать:заробив:заробила} не тільки мою повагу, а й цю нагороду.", ["en"] = "The Scarlet Oracle, Demetria", ["tasks"] = { ["Demetria"] = "Деметрія", ["Demetria slain"] = "Деметрія: убито" } },
    [6162] = { [1] = "Остання битва коханого", [2] = "Мій чоловік прийшов у Сквернолісся битись за честь нашого клану, борючись проти Тіньової Ради та інших мерзотних почвар!\n\nПісля того, як він неодноразово уникав смерті, я отримала від нього листа, в якому йшлося про те, що один друїд просив його про допомогу проти зараженого скверною хутропуза, на ім'я властитель Рор — відтоді про них більше ніхто не чув.\n\nЯ хочу, щоб ти {стать:приніс:принесла} мені відрубану пазуристу лапу цього Рора, {ім'я}. Я хочу, щоб він заплатив за те, що залишив мене вдовою! Здається, ця потвора знаходиться на півдні... біля кордону з Ясенедолом.", [3] = "Убийте властителя Рора і принесіть його кіготь Дрека'Сурі на Кровотруйну заставу у Сквернолісся.", [4] = "Ти вже {стать:дістав:дістала} кіготь цього звіра, {ім'я}? Він заплатить за свої злочини. Мені байдуже, чи він заражений, чи просто злий через те, що живе в цьому похмурому лісі. Жоден хутропуз не житиме довго, якщо чинитиме такі злочини проти моєї родини!", [5] = "Ти робиш мені честь тим, що {стать:стримав:стримала} своє слово. Мій чоловік загинув у бою — він би пишався цим. Але я не могла заспокоїтися, поки не дізналася, що істота, яка змусила мене прожити своє життя на самоті, заплатила за те, що вона зробила.\n\nЩе раз дякую тобі, {ім'я}.", ["en"] = "A Husband's Last Battle", ["tasks"] = { ["Overlord Ror's Claw"] = "кіготь властителя Рора", ["Overlord Ror's Claw (Provided)"] = "кіготь властителя Рора (видано)" } },
    [6163] = { [1] = "Рамштайн", [2] = "Мене задавили кількістю.... На цій самій фермі. Я стояв... тримав оборону Лордерона. Мою ферму та околиці накрила хвиля незліченного воїнства Скари.\n\nНікчема... Мерзота... Він навис наді мною, і нутрощі вивалювалися з його туші.\n\nЯ прокинувся як солдат Скари. Я довго... дуже довго був безпомічною іграшкою Скари. Мій розум був підконтрольним волі Короля-Ліча.\n\nА потім вона прийшла за мною... Я чекав, я сподівався і нарешті здобув свободу.\n\nТепер я хочу помститися тому, хто забрав моє життя. Вбий його!", [3] = "Відправляйтеся до Стратгольма і вбийте Рамштайна-Ненажеру. Візьміть його голову як сувенір для Натаноса.", [4] = "Після того, як Сильвана звільнила мене, я дуже довго висліджував його, але безрезультатно. Чудовисько знайшло свій прихисток в Стратгольмі. Паскуда...", [5] = "Цікаво... він просив про милосердя? Чи знає він взагалі, що таке милосердя?\n\n<Натанос сплюнув.>\n\nЯ повішу голову цієї тварюки собі на стіну.\n\nГарна робота, {ім'я}. Ти {стать:заслужив:заслужила} на мою повагу.", ["en"] = "Ramstein", ["tasks"] = { ["Head of Ramstein the Gorger"] = "голова Рамштайна-Ненажери", ["Head of Ramstein the Gorger (Provided)"] = "голова Рамштайна-Ненажери (видано)" } },
    [6282] = { [1] = "Загроза гарпій", [2] = "Таурени пишаються тим, що захищають ці землі. Безсумнівно, ти здогадуєшся, чому я стурбований кількістю гарпій, що мешкають тут, в Каміннопазуристих горах.\n\nДжерелом такої кількості гарпій у Калімдорі є Криваволюті; вони зазіхають на життя кожного, не даючи невинним жителям покинути це місце.\n\nЯ хочу, щоб ти {стать:знищив:знищила} гарпій, {ім'я}!", [3] = "Маґґран Землев'яз з Сонцескельної криївки хоче, щоб ви вбили 7 криваволютих гарпій, 7 криваволютих душительок, 7 криваволютих вбивць і 7 криваволютих оперених пройдисвіток.", [4] = "Не дай Обвугленій долині втомити тебе, в тих пагорбах живе багато злих створінь. Залишайся {стать:сильним:сильною}, {ім'я} і ти переможеш цю загрозу для нашого народу. Йди та завдай удару — нехай наші діти ніколи не дізнаються про те зло, яке тут було.", [5] = "Чудова новина! Розкажи мені ще раз, як ти {стать:вселив:вселила} страх у холодні серця цих мерзенних гарпій. Криваволютим завдано серйозного удару!", ["en"] = "Harpies Threaten", ["tasks"] = { ["Bloodfury Ambusher"] = "криваволюта душителька", ["Bloodfury Ambusher slain"] = "криваволюта душителька: убито", ["Bloodfury Harpy"] = "криваволюта гарпія", ["Bloodfury Harpy slain"] = "криваволюта гарпія: убито", ["Bloodfury Roguefeather"] = "криваволюта оперена пройдисвітка", ["Bloodfury Roguefeather slain"] = "криваволюта оперена пройдисвітка: убито", ["Bloodfury Slayer"] = "криваволюта вбивця", ["Bloodfury Slayer slain"] = "криваволюта вбивця: убито" } },
    [6283] = { [1] = "Ватажок Криваволютих", [2] = "Зменшити кількість криваволютих гарпій буде недостатньо. Єдине, чим можна викорінити цю заразу, це вбивство їхнього ватажка, криваволютої різниці!\n\nДля цих мерзенних створінь вона майже королева. Вбий її, і гарпій стане менше.\n\nПовернись до Обвугленої долини й знайдеш її на західних пагорбах. Її не так легко перемогти, але нагорода буде немалою.", [3] = "Маґґран з Сонцескельної криївки хоче, щоб ви вбили криваволюту різницю і принесли її рештки в доказ вашого подвигу.", [4] = "Криваволюта різниця — жахливе створіння! Ти знайдеш її на підніжжі до західних пагорбів в Обвугленій долині.\n\nБез неї криваволюті гарпії будуть безпорадні... і ми зможемо перемогти їх назавжди!", [5] = "Я вже відчуваю, як злість покидає мене. Що мені тепер робити? Усвідомлення того, що зло ходить поруч з моєю землею, змушувало мої думки рухатися, а зараз вони замовкли. Можливо, це добре... можливо, тепер я зможу зосередитися на доброті, як і потрібно усім тауренам.\n\nБудь ласка, прийми це як винагороду за твої турботи.", ["en"] = "Bloodfury Bloodline", ["tasks"] = { ["Bloodfury Ripper's Remains"] = "рештки криваволютої різниці", ["Bloodfury Ripper's Remains (Provided)"] = "рештки криваволютої різниці (видано)" } },
    [6284] = { [1] = "Арахнофобія", [2] = "Попередження: дорога в Сиширський каньйон на захід звідси небезпечна, заходити на свій страх і ризик.\n\nБесселет та її восьминогі діти лісу перетворили цей каньйон на своє павутинне лігво.\n\nМаґґран Землев'яз з Сонцескельної криївки назначив нагороду за голову Бесселет. Убийте її й принесіть докази Маґґрану. Тоді ви отримаєте нагороду за знищення цієї восьминогої загрози.", [3] = "Убийте Бесселет і принесіть її ікло Маґґрану в Сонцескельну криївку.", [4] = "Бесселет — безжалісний хижак... Я боюся за тих, хто подорожує Павутиновитою стежкою вночі. Саме тоді вона разом зі своїми дітьми полює на невинних мандрівників. Одного разу я сам ледь став жертвою її двометрового ікла смерті, але, на щастя, мені вдалося відбитися від неї та дістатися до безпечного місця. Я віддав би все, щоб побачити це чудовисько мертвим.", [5] = "Бачу, полювання було вдале, {ім'я:к}! Бесселет вже давно загрожує цим землям... і я не буду за нею сумувати. Візьми цю винагороду як знак того, що ти {стать:герой:героїня} цього лісу.\n\n<Маґґран потирає рану, залишену Бесселет.>\n\nМожливо, тепер набагато більше народу приходитиме до Сонцескельної криївки, не боячись того, що ховається в темряві.", ["en"] = "Arachnophobia", ["tasks"] = { ["Besseleth's Fang"] = "ікло Бесселет", ["Besseleth's Fang (Provided)"] = "ікло Бесселет (видано)" } },
    [629] = { [1] = "Підступний риф", [2] = "Давним-давно, через великий землетрус було затоплено старе місто тролів поруч з водами Дикого узбережжя на північному заході. Ми називаємо це місце Підступним рифом, бо на руїнах міста тепер мешкають мурлоки, які нападають на кожного, хто наближається до них.\n\nДесь в тих руїнах є стара скрижаль, яка несе давню історію про Ґрі'лека, героя легенд тролів. Ця історія священна для племені Темного Списа, хоч і скрижаль занадто велика і її неможливо перенести, я хочу, щоб хоча б один її уламок був у нашому новому домі в Орґріммарі.", [3] = "Принесіть уламок скрижалі Кін'вілею в військовий табір Ґром'ґол.", [4] = "Я чекаю на уламок скрижалі, {ім'я}.", [5] = "Добре. Коли я повернусь в Орґріммар, я віднесу цей уламок у священне місце. Він буде нагадувати нам про могутність і честь Ґрі'лека.\n\nДякую тобі, {ім'я}. Твої вчинки знаменують зміцнення дружби з племенем Темного Списа.", ["en"] = "The Vile Reef", ["tasks"] = { ["Tablet Shard"] = "уламок скрижалі", ["Tablet Shard (Provided)"] = "уламок скрижалі (видано)" } },
    [6301] = { [1] = "Цикл відродження", [2] = "Жадібність промисловців і безперервна війна зруйнували землі Каміннопазуристих гір. Лише благословення Матері-Землі може вилікувати такі рани.\n\n{Ім'я}, я хочу, щоби ти {стать:знайшов:знайшла} особливе насіння — насіння Ґеї. Воно росте лише тут, на Каміннопазуристих горах, на північ від Сонцескельної криївки на Хмуромутному озері, біля самої води.\n\nКоли ти принесеш мені насіння, я наповню його шаманською силою, щоб прискорити ріст.", [3] = "Таммра Перекотиполе з Сонцескельної криївки просить вас зібрати 10 насінин Ґеї.", [4] = "Безперервні руйнування, спричинені війною та тими, хто прагне нажитися на деревині, завдають мені сильного болю. Щоб розпочати цикл відродження і відновити землі, мені потрібне насіння Ґеї. Ти маєш його, {клас:к}?", [5] = "О, {ім'я}, ти {стать:дістав:дістала} насіння Ґеї. Дивись і побачиш, як благословення Матері-Землі може змусити навіть ці маленькі зернятка життя квітнути та процвітати.", ["en"] = "Cycle of Rebirth", ["tasks"] = { ["Gaea Seed"] = "насіння Ґеї", ["Gaea Seed (Provided)"] = "насіння Ґеї (видано)" } },
    [6321] = { [1] = "Забезпечення Крипти", [2] = "Каратель Гадрек попросив мене оцінити запаси нашого обладнання у Крипті. Поки в лісах затаїлися й армія Скари, і щось ще гірше, він не хоче, щоб Смертестражам не вистачило спорядження, яке їм може знадобитися.\n\nЯ з'ясував, що, загалом, ми добре забезпечені, але нам усе ж треба більше зброї, щоб замінити втрачену в бою.\n\nОсь замовлення на закупівлю всього необхідного для торговця зброєю Гордона Вендгема у Підмісті. Віднеси його до нашого майстра кажанів, Кароса Разока, та поговори з ним з приводу польоту до Підмістя.", [3] = "Принесіть замовлення Подріґа Каросові Разоку.", [4] = "Ти, схоже, з важливою справою...", [5] = "О, замовлення на постачання. Ти хочеш доставити його до Підмістя, без сумніву. І швидко, щоб Крипта не залишилася без припасів.", ["en"] = "Supplying the Sepulcher", ["tasks"] = { ["Podrig's Order"] = "замовлення Подріґа", ["Podrig's Order (Provided)"] = "замовлення Подріґа (видано)" } },
    [6322] = { [1] = "Майкл Ґаррет", [2] = "Я поклав припаси для Крипти в цей ящик. Якщо ти вже {стать:відвідував:відвідувала} Крипту та {стать:розмовляв:розмовляла} з їхнім майстром кажанів, то зможеш повернутися до нього верхи на кажані.\n\nПоговори з майстром кажанів Підмістя, Майклом Ґарретом. Він може надати тобі кажана до Крипти.", [3] = "Принесіть ящик Гордона до Майкла Ґаррета.", [4] = "Якщо тобі треба подорожувати на довгу відстань, то кажан — найліпший варіант.", [5] = "Цей ящик потрібно доставити до Крипти у Срібнохвою? Це легко зробити: наші кажани літають туди щодня.", ["en"] = "Michael Garrett", ["tasks"] = { ["Gordon's Crate"] = "ящик Гордона", ["Gordon's Crate (Provided)"] = "ящик Гордона (видано)" } },
    [6323] = { [1] = "Політ до Підмістя", [2] = "Один з моїх кажанів може відвезти тебе в Підмістя, за невелику плату. Поговори зі мною знову, як будеш {стать:готовий:готова}, щоб ми могли організувати тобі політ.\n\nТи знайдеш Гордона Вендгема у Торговому кварталі Підмістя. Це — той же квартал, де приземлиться мій кажан.", [3] = "Купіть кажана до Підмістя у майстра кажанів Кароса Разока, а потім віднесіть замовлення Подріґа Гордонові Вендгему в Підмістя.", [4] = "Я тримаю свою зброю в ідеальному стані. Вона почищена та готова до використання.", [5] = "Замовлення з Крипти? Дуже добре. Це честь — служити тим, хто служить нашій Темній Леді.", ["en"] = "Ride to the Undercity", ["tasks"] = { ["Podrig's Order"] = "замовлення Подріґа", ["Podrig's Order (Provided)"] = "замовлення Подріґа (видано)" } },
    [6324] = { [1] = "Повернення до Подріґа", [2] = "Майстром кажанів в Крипті є Карос Разок. Якщо ти вже {стать:познайомився:познайомилася} з ним, то я можу дати тобі кажана, щоб повернутися до нього.\n\nНаші кажани завжди можуть літати в Підмістя, але щоб дістатися до більш віддалених місцин, їхній вершник повинен спершу відвідати місцевість і поговорити з тамтешніми майстрами кажанів.\n\nТи вже зустрічав Кароса в Крипті, тож тепер ти зможеш літати туди на кажанах. Поговори зі мною, як будеш {стать:готовий:готова}.", [3] = "Купіть політ кажаном до Крипти у майстра кажанів Майкла Ґаррета, а потім принесіть ящик Гордона смертестражу Подріґові у Крипті.", [4] = "{ім'я}, ти {стать:повернувся:повернулася}. Ти маєш наші постачання з Підмістя?", [5] = "Хороша робота, {ім'я}. Ця зброя гарантуватиме, що наших смертестражів не застануть непідготовленими.\n\nТи гарно {стать:послужив:послужила} Темній Леді.", ["en"] = "Return to Podrig", ["tasks"] = { ["Gordon's Crate"] = "ящик Гордона", ["Gordon's Crate (Provided)"] = "ящик Гордона (видано)" } },
    [6361] = { [1] = "Оберемок шкур", [2] = "У мене є в'язка шкур з тварин Степів, які треба доправити в Громовий Бескид. Мій колега, Агану, використовує їх для створення шкіряної броні.\n\nМожливо, ти віднесеш їх йому замість мене?\n\nНайшвидший шлях до Громового Бескиду - на спині виверни. Віднеси оберемок шкур Девраку, нашому приборкувачу виверн на Перехресті, і поговори з ним про поїздку до Громового Бескиду.", [3] = "Принесіть оберемок шкур приборкувачу виверн Девракові на Перехрестя.", [4] = "Тобі потрібна виверна? Треба щось перевезти?", [5] = "Якщо тобі потрібно доставити ці шкури до Громового Бескиду - ти {стать:звернувся:звернулась} до правильного орка!", ["en"] = "A Bundle of Hides", ["tasks"] = { ["Bundle of Hides"] = "оберемок шкур", ["Bundle of Hides (Provided)"] = "оберемок шкур (видано)" } },
    [6362] = { [1] = "Поїздка до Громового Бескиду", [2] = "За невелику плату я відправлю тебе на одній з моїх виверн до Громового Бескиду. Швидшого шляху до міста не існує!\n\nПодумай, і якщо це тобі підходить - то дай мені знати, як зберешся в дорогу.\n\nЯкщо ти везеш ці шкури Агану, то він, мабуть, у зброярні Геви у підніжжі вежі виверн, саме тієї, в якій ти приземлишся!", [3] = "Заплатіть приборкувачу виверн Девраку за політ на виверні до Громового Бескиду, а там віднесіть оберемок шкур до Агану.", [4] = "Ти {стать:весь вкритий:вся вкрита} пилом! Певно, ти {стать:прибув:прибула} зі Степів. {стать:Говорив:Говорила} з моїм другом Джаганом?", [5] = "О! Новий оберемок шкур. Я негайно почну працювати над ними!\n\nСпасибі, {стать:брате:сестро}. Ти добре мені {стать:допоміг:допомогла}. Ось кілька монет, щоб відшкодувати згаяний час та витрати на поїздку.", ["en"] = "Ride to Thunder Bluff", ["tasks"] = { ["Bundle of Hides"] = "оберемок шкур", ["Bundle of Hides (Provided)"] = "оберемок шкур (видано)" } },
    [6363] = { [1] = "Приборкувач виверн Тал", [2] = "Я підготував Джагану шкіряні вироби на продаж на Перехресті. Віднесеш їх йому?\n\nЯкщо ти вже {стать:був:була} на Перехресті та {стать:розмовляв:розмовляла} з місцевим приборкувачем виверн, то без проблем зможеш повернутися туди верхи на одній з них з Громового Бескиду.\n\nВізьми цю шкіргалантерею та прямуй до Тала, нашого приборкувача виверн у цьому місті, та домовся з ним щодо перельоту до Перехрестя.", [3] = "Занесіть шкіргалантерею Агану до Тала в Громовий Бескид.", [4] = "Мої вітання, {клас:к}. Чим я можу тобі допомогти?", [5] = "Тобі потрібно доставити це на Перехрестя, еге? Не питання! Якщо ти вже {стать:був:була} там і {стать:розмовляв:розмовляла} з Девраком, тоді можеш взяти туди одну з моїх виверн.", ["en"] = "Tal the Wind Rider Master", ["tasks"] = { ["Ahanu's Leather Goods"] = "шкіргалантерея Агану", ["Ahanu's Leather Goods (Provided)"] = "шкіргалантерея Агану (видано)" } },
    [6364] = { [1] = "Повернення до Джагана", [2] = "Для того, щоб полетіти до містечка, ти вже хоча б раз {стать:мусив:мусила} побувати там і поговорити з місцевим приборкувачем виверн. А оскільки ти вже {стать:бував:бувала} на Перехресті та {стать:знайомий:знайома} з Девраком, тож за символічну плату можеш взяти мою виверну та долетіти звідси до нього.\n\nЯ буду тут, якщо надумаєш. Опинившися на Перехресті, зможеш доставити шкіряні вироби Джаганові Ястубиному Крилу.", [3] = "Заплатіть за виверну до Перехрестя приборкувачу Талу, а там знайдіть Джагана Яструбине Крило та віддайте йому шкіргалантерею Агану.", [4] = "{Ім'я}, ти {стать:повернувся:повернулася} з Громового Бескиду? Ти {стать:віддав:віддала} шкури Агану?", [5] = "Агану надіслав мені готові вироби? Дуже добре. На Перехресті нині багато мисливців та шукачів пригод, тож торгівля наразі дуже жвава. Я впевнений, що всі ці товари швиденько порозпродаю.\n\nДякую за всі твої зусилля, {Ім'я}. Я у боргу перед тобою.", ["en"] = "Return to Jahan", ["tasks"] = { ["Ahanu's Leather Goods"] = "шкіргалантерея Агану", ["Ahanu's Leather Goods (Provided)"] = "шкіргалантерея Агану (видано)" } },
    [6365] = { [1] = "М'ясце до Орґріммара", [2] = "У мене є декілька смачнючих м'ясних вирізок, які я хочу надіслати подрузі. Її звуть Гришка, корчмарка в Орґріммарі. Ти не {стать:міг би:могла б} доставити м'ясо для мене?\n\nНайшвидший шлях до Орґріммару — верхи на виверні. Візьми пакунок та прямуй до приборкувача виверн Перехрестя, Деврака. З ним і домовся про переліт до Орґріммару.", [3] = "Принесіть м'ясо від Зарґа Девракові на Перехрестя.", [4] = "Тобі потрібно кудись швиденько дістатися? Тоді ти {стать:звернувся:звернулась} до правильного орка!", [5] = "Ти маєш доправити це м'ясо до Орґріммара? Без проблем. За символічну платню моя виверна тебе туди віднесе.", ["en"] = "Meats to Orgrimmar", ["tasks"] = { ["Zargh's Meats"] = "м'ясо від Зарґа", ["Zargh's Meats (Provided)"] = "м'ясо від Зарґа (видано)" } },
    [638] = { [1] = "Тролебій", [2] = "Після смерті Тораса Тролебоя та руйнації Стромварту, Вол'джин велів нам докласти всіх зусиль, щоб забрати у людей легендарний меч Трол'калар. Тоді ми зможемо скористатися ним в наших майбутніх битвах з тролями Зул'Ґуруба.\n\nЗенґу, один із наших досвідчених мисливців, вирушив до Молотобою, що на північному сході височини Араті, щоб простежити за цим.", [3] = "Вирушайте до Молотобою на височину Араті та поговоріть із Зенґу.", [5] = "Як справи, {клас:к}? Вол'джин дав нам непросте завдання і ми із задоволенням приймемо будь-яку допомогу.", ["en"] = "Trollbane" },
    [6381] = { [1] = "Нове життя", [2] = "От бачиш, {клас:к}, хоч земля і понівечена, але цикл життя — це потужна річ. Тепер нам потрібно зробити свій внесок, щоб допомогти їй. Посади це насіння в самому центрі руйнувань, на заході, в Обвугленій долині. Але будь {стать:обережним:обережною}, бо на понівеченій землі все ще бродять гарпії та розлючені вогняні елементалі.\n\n{ім'я}, візьми це зачароване насіння Ґеї й посади в родючі насипи ґрунту. Цикл життя повинен продовжуватися!", [3] = "Посадіть 10 насінин Ґеї в насипи ґрунту Ґеї, а потім поверніть решту зачарованих насінин Ґеї Таммрі у Сонцескельну криївку.", [4] = "Насіння, яке ти саджаєш, сильне, воно здатне протистояти псуванню та створювати підґрунтя для іншого життя. Воно буде рости й рости, спочатку не даючи розповсюджуватись гнилі та зцілюючи понівечену землю, а потім, в один прекрасний день, знову перетворить Каміннопазуристі гори на пишний ліс.\n\nТи {стать:посадив:посадила} все насіння Ґеї?", [5] = "Це велика перемога для цих земель. З часом все зміниться: ТзНБ \"Авантюра\" забереться звідси разом зі своїми бензопилами та сокирами, розлючені духи вогню заспокояться, а гарпії будуть витіснені з цих земель.\n\nЛише тоді, {ім'я}, настане справжній мир у Каміннопазуристих горах.\n\nТи добре {стать:попрацював:попрацювала}, {клас:к}. Візьми один з цих предметів як подяку за нове життя, яке ти {стать:створив:створила} сьогодні.", ["en"] = "New Life", ["tasks"] = { ["Enchanted Gaea Seeds"] = "зачароване насіння Ґеї", ["Enchanted Gaea Seeds (Provided)"] = "зачароване насіння Ґеї (видано)", ["Gaea seed planted"] = "Насіння Геї посаджене", ["Gaea seed planted (Provided)"] = "Насіння Геї посаджене (видано)", ["Gaea seed planted slain"] = "Насіння Геї посаджене: убито" } },
    [6382] = { [1] = "Ясенеділське полювання", [2] = "Твоя сила вражає, {клас:к}, а жага до полювання дає впевненість, що незабаром тобі можна буде доручити більшу дичину... і серйознішу.\n\nЯсенеділ — це величезні простори неприборканої дикої природи, які Орда хоче підпорядкувати собі як політично, так і в духовно. Якщо ти прагнеш проявити себе в незвіданих землях — звернись за допомогою до Сенані Грозового Серця на заставі при Тріснутому Дереві. Вона знаходиться на північ від шляху зі Степів.", [3] = "Поговоріть з Сенані Грозовим Серцем на заставі при Тріснутому Дереві, що в Ясенедолі.", [5] = "Ласкаво просимо на наш новий рубіж, {ім'я}. Ясенеділ — це земля можливостей, де {стать:такому юній:такій юній} {клас:д}, як ти, знайдеться вдосталь шансів довести свою силу. Оглянь цю заставу та обов'язково сходи на Зорамське узбережжя — в Орди й там є застава.\n\nЯк розумію, ти тут для того, щоб дізнатися більше про полювання. Слухай уважно, і я з радістю поділюся з тобою всім, що тобі потрібно знати.", ["en"] = "The Ashenvale Hunt" },
    [6383] = { [1] = "Ясенедільське полювання", [5] = "Є три легендарні істоти, які є цілями Ясенедільского полювання. Знайди їх та випробуй себе проти їхньої хитрості та міці. Можливо, в процесі ти дізнаєшся щось про себе. Ці істоти — ведмідь Урсанґо, ночезуб Шадумбра та гіпогриф Гостропазур.\n\nСтворіння Ясенедільского полювання могутні. Можливо, ти потребуватимеш допомоги. Якщо тобі вдасться подолати їх — принеси мені докази своєї звитяги.", ["en"] = "The Ashenvale Hunt" },
    [6384] = { [1] = "Поїздка до Орґріммара", [2] = "Усього за кілька монет моя виверна перевезе тебе до Орґріммара. Потрапивши туди, зможеш занести пакунок із м'ясом від Зарги до Гришки. Її корчма розташована у долині Сили, недалеко від Небесної башти, куди моя виверна теде доставить.\n\nДай знати, як будеш {стать:готовий:готова} до подорожі.", [3] = "Оплатіть приборкувачеві виверн Девраку поїздку до Орґріммара, а там віднесіть м'ясо від Зарґа корчмарці Гришці.", [4] = "Щось смачно пахне! Це у тебе часом не сире м'ясо?", [5] = "Ой, чудово! Які гарні шматки! Це ж від Зарґа, правильно? Цей орк знає, як полонити жіноче серце...\n\nОх, аж не дочекаюся, коли його приготую. Проте не занадто! М'ясо найкраще подавати з кров'ю, еге ж?", ["en"] = "Ride to Orgrimmar", ["tasks"] = { ["Zargh's Meats"] = "м'ясо від Зарґа", ["Zargh's Meats (Provided)"] = "м'ясо від Зарґа (видано)" } },
    [6385] = { [1] = "Приборкувач виверн Дорас", [2] = "Я написала лист подяки Зарґу. Будь {стать:ласкавий:ласкава} віднести послання до нього? Якщо ти вже {стать:бував:бувала} на Перехресті та {стать:знайомий:знайома} з місцевим приборкувачем виверн, то можеш полетіти туди на одній з виверн.\n\nБери мій лист і біжи до Дораса, приборкувача виверн Орґріммара. Домовся з ним про переліт до Перехрестя.", [3] = "Віднесіть лист Гришки до Дораса в Орґріммар.", [4] = "Тобі потрібна одна із моїх виверн?", [5] = "Треба доставити це до Перехрестя у Степи? Звісно, я можу тебе туди доправити...", ["en"] = "Doras the Wind Rider Master", ["tasks"] = { ["Gryshka's Letter"] = "лист Гришки", ["Gryshka's Letter (Provided)"] = "лист Гришки (видано)" } },
    [6386] = { [1] = "Повернення на Перехрестя", [2] = "Мої виверни навчені літати до багатьох різних місць, якщо ти вже {стать:бував:бувала} у місці призначення та {стать:знайомий:знайома} з моїм колегою в там.\n\nОскільки ти вже {стать:бував:бувала} на Перехресті та знаєш приборкувача виверн Деврака, то можеш летіти звідси прямісінько до нього. Опинившися на Перехресті, зможеш віддати лист Гришки Заргові.\n\nПовідом мене, коли зберешся в путь-дорогу.", [3] = "Сплатіть за переліт до Перехрестя приборкувачу виверн Дорасу, а по прибутті віддайте Заргові лист Гришки.", [4] = "Ти щойно з Орґріммару? Чи сподобалося Гришці м'ясо, що я надіслав?", [5] = "Ах! Схоже, воно їй до вподоби! Ніщо не змушує леді так рум'яніти, як великий, соковитий стейк!\n\nДякую, {ім'я:к}. Ти мені добре {стать:допоміг:допомогла}. Ось гроші за твій клопіт, і не дивуйся, якщо я запрошу тебе на своє весілля!", ["en"] = "Return to the Crossroads.", ["tasks"] = { ["Gryshka's Letter"] = "лист Гришки", ["Gryshka's Letter (Provided)"] = "лист Гришки (видано)" } },
    [639] = { [1] = "Сигіла Строма", [2] = "В давні часи, тролі воювали проти імперії Аратора і їхній лідер, лорд Іґнай Стромський, названий Тролебоєм, був найсильнішим з них. Він йшов у бій, тримаючи в руках Трол'калар — \"вбивцю тролів\", їхньою давньою мовою.\n\nАле тепер сини Тролебоя слабкі, а їхнє королівство занепало.\n\nМеч захищений кількома сигілами, які були розподілені між захисниками Стромварта, і ми повинні їх відшукати!\n\nПершу сигілу захопив Синдикат, і вона має бути у когось з їхніх членів в Стромварті.", [3] = "Дістаньте сигілу Строма для Зенґу з Молотобою.", [4] = "Ти вже {стать:знайшов:знайшла} першу сигілу? Скоріш за все вона в одного з агентів Синдикату в Стромварті.", [5] = "Чудово... Це гарний початок для збору всіх сигіл, що знадобляться нам, щоб витягти Трол'калар з могили Тролебоя.", ["en"] = "Sigil of Strom", ["tasks"] = { ["Sigil of Strom"] = "сигіла Строма", ["Sigil of Strom (Provided)"] = "сигіла Строма (видано)" } },
    [6390] = { [1] = "Чуму на вас!", [2] = "Ви оглядаєте лісопильню в пошуках чогось, щоб відкрити бочку і знаходите лом, що цілком підходить для цієї мети.\n\nВи готуєтесь накивати п'ятами та молитесь, що встигнете вибратися з лісопильні до того, як до вас доберуться терміти.", [3] = "Випустіть термітів Зачумлених земель на лісопильні Північного кряжу, а потім поверніться з бочкою термітів Зачумлених земель до Мікі Левін, що на Валу в Тірісфальському переліссі.", [4] = "Тобі вдалося, {ім'я}? Ти {стать:випустив:випустила} термітів на лісопильні?\n\nЦе жахливо, що моя сім'я втратила роботу і життя, але ще гірше бачити, як місце, пройшло моє дитинство, захоплене цими удаваними святенниками... Тьфу на них!", [5] = "Дякую тобі, {ім'я}. Ось, тримай монету. Вибачай, що нема більше, але отримай насолоду від допомоги в знищенні Багряного Походу!", ["en"] = "A Plague Upon Thee", ["tasks"] = { ["Barrel of Plagueland Termites"] = "бочка з термітами Зачумлених земель", ["Barrel of Plagueland Termites (Provided)"] = "бочка з термітами Зачумлених земель (видано)" } },
    [6393] = { [1] = "Війна елементалів", [2] = "Рада Припливів послала мене в Каміннопазуристі гори, щоб розпочати війну з вогняними елементалями. Нептулон Хвилелов, повелитель усіх водяних елементалів, особисто зацікавлений у знищенні всіх наших вогняних родичів.\n\n{ім'я}, ти можеш допомогти мені заслужити прихильність ради, знищивши вогняних елементалів в Обвугленій долині. Після смерті вогняні елементалі залишають вогняні кристали — спалахтити. Принеси їх мені й ти отримаєш нагороду.", [3] = "Принесіть 10 спалахтитів Цунамену в Сонцескельну криївку.", [4] = "Рада Припливів втрачає терпіння. Вони прагнуть покласти край війні, що бушує в усіх вимірах вже не одне століття. Мої брати з нетерпінням чекають звістки про славну перемогу над ненависними вогняними елементалями. Чи є у тебе спалахтити, які мені потрібні?", [5] = "Духи води всередині мене булькають від захоплення. {ім'я}, ти {стать:подарував:подарувала} мені славну перемогу, про яку я маю повідомити в Раду Припливів.", ["en"] = "Elemental War", ["tasks"] = { ["Incendrites"] = "спалахтит", ["Incendrites (Provided)"] = "спалахтит (видано)" } },
    [6394] = { [1] = "Кайло Тазз'ріла", [2] = "{Ім'я}, на {стать:такого:таку} {раса:з} як ти можна покластись. Чи можу я розраховувати на тебе ще в одному завданні?\n\nЯкийсь час тому я обстежував північну печеру на наявність мінералів і лишив там своє улюблене кайло. Повертаючись за ним, я побачив, що печера вже була заповнена злими тварюками! Я до чого… Чи не {стать:міг би:могла б} ти сходити туди по моє кайло?\n\nЯ залишив його у невеликій залі з водоспадом. Моє кайло зачароване, тому ти побачиш його у темряві. Не забивай голову тим, як його шукати. Краще подумай про те, як забиратимеш його у тих тварюк…", [3] = "Принесіть десятникові Тазз'рілу його кайло.", [4] = "Ти вже {стать:ходив:ходила} у печеру Палаючого Леза, {Ім'я}? {стать:Знайшов:Знайшла} моє кайло?", [5] = "Чудово, ти {стать:дістав:дістала} його! Дякую тобі, {Ім'я}. Це моє улюблене кайло! А тепер, якщо мої наймити закінчили рубати дерева, ми можливо знайдемо хорошу печеру для видобутку руди!", ["en"] = "Thazz'ril's Pick", ["tasks"] = { ["Thazz'ril's Pick"] = "кайло Тазз'ріла", ["Thazz'ril's Pick (Provided)"] = "кайло Тазз'ріла (видано)" } },
    [6395] = { [1] = "Останнє бажання Марли", [2] = "Моя подруга Марла Фіппс жила зі своїм чоловіком Семюелем перед Чумою, але коли настала ця пошесть, Семюель піддався їй і долучився до Скари.\n\nМарла врятувалася від невмирущості тільки, щоб загинути від рук свого чоловіка, що втратив розум. Проте її любов була настільки сильною, що останнім її проханням було бути похованою з її коханим Семюелем.\n\nСемюель Фіппс бродить по зруйнованому табору при дорозі на північний схід від Смертедзвону. Вбий його та подаруй Марлі її останнє бажання: поховай його у її могилі, у першому ряді нашого цвинтаря.", [3] = "Принесіть рештки Семюеля Фіппса до могили Марли та повертайтеся до послушниці Елрет.", [4] = "Ми повинні поважати наших померлих, {Ім'я}. Це - одна з речей, які відрізняють нас від Скари...", [5] = "Сьогодні ти {стать:зробив:зробила} хорошу справу, {Ім'я}. Хоча наша боротьба проти Скари продовжується, сподіваймося, що Марла та Семюель знайдуть спокій разом в їхньому останньому спочинку.", ["en"] = "Marla's Last Wish", ["tasks"] = { ["Samuel's Remains Buried"] = "Останки Самуїла поховані", ["Samuel's Remains Buried (Provided)"] = "Останки Самуїла поховані (видано)", ["Samuel's Remains Buried slain"] = "Останки Самуїла поховані: убито" } },
    [640] = { [1] = "Зламана сигіла", [2] = "Могила Тораса Троллебоя захищена трьома сигілами, одну з яких ти {стать:відібрав:відібрала} у Синдикату. Інші дві дістати буде складніше, оскільки ними володіє ополчення Стромварта.\n\nСигіла Торадіна була розділена на одинадцять частин його сином, Ґаленом, які він розподілив між захисників Стромварта. Збери фрагменти сигіли та віднеси їх Тор'ґану, тролю-шаману — він зможе скласти їх в єдине ціле.", [3] = "Заберіть 11 фрагментів сигіли у захисників Стромварта та принесіть їх Тор'ґану в Молотобій.", [4] = "Тром'ка, {клас:к}. Зенґу повідомив, що тобі потрібна моя допомога.", [5] = "А, то тобі треба відновити сигілу? Це буде не надто складно... Всі частини, здається, на місці, а магічну структуру буде легко відновити.\n\nМабуть, тобі краще заплющити очі...", ["en"] = "The Broken Sigil", ["tasks"] = { ["Sigil Fragment"] = "фрагмент сигіли", ["Sigil Fragment (Provided)"] = "фрагмент сигіли (видано)" } },
    [6401] = { [1] = "Кайя жива!", [2] = "Розкажи Таммрі Перекотиполю, тітці Кайї, яка живе в Сонцескельній криївці, хороші новини! Кайя жива! Ми думали, що вона загинула під час того жахливого нападу на наше селище. Йди стежкою на захід і ти дістанешся до Сонцескельної криївки.", [3] = "Передайте хороші новини Таммрі Перекотиполю, що живе в Сонцескельній криївці.", [5] = "Боже мій, моя племінниця Кайя жива! Це справді хороша новина. Дякую тобі, {ім'я}.", ["en"] = "Kaya's Alive" },
    [641] = { [1] = "Сигіла Торадіна", [2] = "Реконструкція пройшла бездоганно. Тепер сигілу можна використати, щоб відкрити печатку на могилі Тролебоя. Повертайся до Зенґу, у нього точно знайдеться завдання для тебе.", [3] = "Віднесіть відновлену сигілу Торадіна до Зенґу в Молотобій.", [4] = "{ім'я}! Ти вже {стать:дістав:дістала} другу сигілу?", [5] = "Ми на півдорозі до того, щоб витягти Трол'калар з гробниці Тролебоя. Ми точно не знаємо, де знаходиться третя сигіла, оскільки її власники постійно пересуваються по Араті. Але я вірю, що тобі вдасться її відшукати.", ["en"] = "Sigil of Thoradin", ["tasks"] = { ["Sigil of Thoradin"] = "сигіла Торадіна", ["Sigil of Thoradin (Provided)"] = "сигіла Торадіна (видано)" } },
    [6421] = { [1] = "Ущелина Крутих валунів", [2] = "Щось не так тут, у Каміннопазуристих горах. Відчуваєш напругу в повітрі, {ім'я}?\n\nНа південний схід звідси в ущелині Крутих валунів є глибока печера. Там кобольди відчайдушно видобувають рідкісні кристали — резоніт. Я хочу, щоб ти {стать:приніс:принесла} кілька зразків, щоб я міг зрозуміти, що відбувається в тій печері. Також було б добре, якби ти {стать:дослідив:дослідила} глибини тієї печери.\n\nВперед, {стать:юний:юна} {клас:к}, мені вкрай необхідно знати, яке зло ховається під цими горами.", [3] = "Дослідіть глибини печери в ущелині Крутих валунів і принесіть 10 кристалів резоніту Мор'роґалу в Сонцескельну криївку.", [4] = "Які новини ти {стать:дізнався:дізналася} з ущелини Крутих валунів? Я пригадую якусь легенду, пов'язану з резонітом... Але нема за що вхопитися. Можливо, якщо ми дізнаємося, що лежить на дні печери, то зможемо пролити світло на їхні підступні наміри.", [5] = "Оо... Так! Це воно. Кристали резоніту мають сліди земельної магії. Мабуть, кобольди копали глибоко і знайшли земельника.\n\nЛегенда стверджує, що земельники — це істоти, створені титанами. З їхньою допомогою був створений земний ґрунт, по якому ми ходимо. Це, безумовно, загроза, яку не можна ігнорувати.\n\n<Мор'роґал хитає головою.>\n\nМожливо, я зможу зачарувати ці шматки руди, щоб використати їх проти кобольдів.", ["en"] = "Boulderslide Ravine", ["tasks"] = { ["Resonite Crystal"] = "кристал резоніту", ["Resonite Crystal (Provided)"] = "кристал резоніту (видано)" } },
    [643] = { [1] = "Сигіла Аратора", [2] = "Вони ледве утримують Стромварт, не кажучи вже про Араті. Людський принц збирає рештки кавалерії в околицях. Я не розумію навіщо він це робить, але хто може зрозуміти мислення людей, еге ж?.\n\nЯкими б не були його наміри, важливіше те, що він віддав одну зі своїх сигіл лейтенанту Доблекличу, командиру кавалерії. Знайди його і принеси мені цю сигілу.", [3] = "Добудьте сигілу Аратора та віддайте її Зенґу в Молотобій.", [4] = "Доблеклича буде непросто вистежити, {ім'я}. Верхи на коні він може швидко пересуватися. Та попри це, нам потрібна ця сигіла.", [5] = "Втрата командира кавалерії стане серйозним ударом для захисників Стромварта. А ще краще те, що нас від Трол'калара відділяє лише одна сигіла.", ["en"] = "Sigil of Arathor", ["tasks"] = { ["Sigil of Arathor"] = "сигіла Аратора", ["Sigil of Arathor (Provided)"] = "сигіла Аратора (видано)" } },
    [644] = { [1] = "Сигіла Тролебоя", [2] = "Остання сигіла, необхідна для відкриття гробниці Тораса Тролебоя, знаходиться в його сина. Він засів глибоко в Стромварті, в каплиці, яку утримує ополчення. Принц Ґален добре захищений і є вмілим воїном, тож це завдання може бути найскладнішим.", [3] = "Вбийте принца Ґален Тролебоя та принесіть його сигілу до Зенґу в Молотобій.", [4] = "Ти {стать:повернувся:повернулася}, {ім'я}. Вже {стать:покінчив:покінчила} з родом Іґная Тролебоя?", [5] = "Який сьогодні вдалий день, {клас:к}. Кров Тролебоїв більше не буде переслідувати мій народ, а сигіли, необхідні для отримання Трол'калара, тепер у нашому розпорядженні. Скоро, дуже скоро, ми вдаримо по мерзенних тролях Зул'Ґуруба.", ["en"] = "Sigil of Trollbane", ["tasks"] = { ["Sigil of Trollbane"] = "сигіла Тролебоя", ["Sigil of Trollbane (Provided)"] = "сигіла Тролебоя (видано)" } },
    [6441] = { [1] = "Роги сатирів", [2] = "Вітаннячка! Я подорожувала через Ясенеділ в Брашпиль і вирішила зупинитися тут, на заставі при Тріснутому Дереві. Я завжди в пошуку нових можливостей, і схоже, що в Брашпилі зараз високий попит на роги сатирів.\n\nЯ розпиталася і дізналася, що сатири в Ночеплині, Сатирнаарі та Завіані мають саме такі роги, які мені потрібні. Сама я з ними битися не можу... на відміну від тебе!\n\nОсь що, збери для мене роги, а я тобі за це добре віддячу.", [3] = "Зберіть 16 рогів сатирів для Піксель на заставі при Тріснутому Дереві.", [4] = "Сподіваюся, ти швиденько збереш ті роги, {ім'я}. Мені час повертатися до Брашпиля!", [5] = "Вони ідеальні, {ім'я}! Дякую за допомогу!\n\nА це тобі за працю...", ["en"] = "Satyr Horns", ["tasks"] = { ["Satyr Horns"] = "роги сатира", ["Satyr Horns (Provided)"] = "роги сатира (видано)" } },
    [6442] = { [1] = "Наги на Зорамському узбережжі", [2] = "На узбережжі ховається зло, {раса:к}.\n\nЦе місце спочинку приреченого міста Зорам, давно зруйнованого і зануреного під воду. Загубленого і майже забутого.\n\nАле наги повернулися, з невідомої причини. Проте причина не має значення. Ми повинні захистити землю, яку ми так важко здобували.\n\nПовертайся до мене з двадцятьма їхніми головами! Відкинь наг назад до глибин!", [3] = "Принесіть 20 голів гнівохвостих наг до Марукай на Зорамське узбережжя.", [4] = "Кількість наг збільшується, {ім'я}. Будь ласка, заверши це завдання.", [5] = "Нам не вистачає таких, як ти, {ім'я}. Дякую за допомогу.", ["en"] = "Naga at the Zoram Strand", ["tasks"] = { ["Wrathtail Head"] = "голова гнівохвостої наги", ["Wrathtail Head (Provided)"] = "голова гнівохвостої наги (видано)" } },
    [645] = { [1] = "Трол'калар", [2] = "Що це? Коли всі чотири сигіли опинилися поруч, вони утворили одну сигілу. Вона повинна зняти закляття з могили Тролебоя.\n\nРештки Тролебоя поховані у святилищі позаду каплиці Стромварта. Здобудь Трол'калар.", [3] = "Дістаньте Трол'калар із могили Тролебоя в Стромварті.", [4] = "Лінії на могилі Тролебоя збігаються з сяючими лініями сигіли Іґная...", [5] = "Коли лінії на могилі Тролебоя та на сигілі Іґная збігаються, спалах світла поглинає сигілу і легендарний меч Трол'калар вивільняється з рук кам'яної статуї.", ["en"] = "Trol'kalar", ["tasks"] = { ["Sigil of Ignaeus"] = "сигіла Іґная", ["Sigil of Ignaeus (Provided)"] = "сигіла Іґная (видано)" } },
    [646] = { [1] = "Трол'калар", [2] = "Сяйво повільно згасає і меч Трол'калар вивільняється з каменю.", [3] = "Віднесіть Трол'калар до Зенґу в Молотобій.", [4] = "{ім'я}! Тобі вдалося забрати меч?", [5] = "Поколіннями сили Строма та Аратора винищували тролів. Тепер їхня найсильніша зброя в наших руках. Більше ми не будемо топтатися на місці в дрімучих лісах Зул'Ґуруба!\n\nТвоя допомога неоціненна, {ім'я}, і тролі Темного Списа в боргу перед тобою!\n\nЯ подбаю про те, щоб цей меч доставили до Німбої в Ґром'ґол.", ["en"] = "Trol'kalar", ["tasks"] = { ["Sheathed Trol'kalar"] = "Трол'Калар в піхвах", ["Sheathed Trol'kalar (Provided)"] = "Трол'Калар в піхвах (видано)" } },
    [6461] = { [1] = "Кровопивці", [2] = "Ми, тролі, тут, в Малака'джині, існуємо завдяки цій землі; Каміннопазуристі гори дають нам можливість полювати, щоб ми могли жити.\n\nТільки от повадилися до нас останнім часом непрохані гості... павуки, що живуть у цих горах, вночі нападають на наші табори, намагаючись вкрасти нашу здобич.\n\nЯкщо ти допоможеш нам винищити цих зловіщих істот, ми, тролі Малака'джина, будемо у тебе в боргу. В Каміннопазуристих горах павуки всюди — просто йди на північ і ти побачиш, що я маю на увазі.", [3] = "Ксен'зілла з Малака'джина хоче, щоб ви вбили 10 густомохових підкрадачів та 7 густомохових ядоплюїв.", [4] = "Агов, {стать:друже:подруго}, ти {стать:вбив:вбила} волохатих кровопивць? Я нікого не боюся тут, у Каміннопазуристих горах, але я не гуляю вночі... якщо ти розумієш, про що я, {стать:друже:подруго}!\n\nПоки я тримаюся якомога далі від їхньої павутини, все буде добре.\n\nУдачі тобі, {клас:к}!", [5] = "Круто! Гарна новина, сподіваюсь, сьогодні ми будемо вечеряти без небажаних гостей.\n\nЩиро дякуємо, {ім'я}. Ми навічно у тебе в боргу.", ["en"] = "Blood Feeders", ["tasks"] = { ["Deepmoss Creeper"] = "густомоховий підкрадач", ["Deepmoss Creeper slain"] = "густомоховий підкрадач: убито", ["Deepmoss Venomspitter"] = "густомоховий ядоплюй", ["Deepmoss Venomspitter slain"] = "густомоховий ядоплюй: убито" } },
    [6462] = { [1] = "Трольські обереги", [2] = "Мої родичі подорожували сюди з купою оберегів, але Колючохутрі хутропузи напали та вбили їх ще до того, як вони дісталися Зорам'ґару! Кляті хутропузи!\n\nЯ сумую за братами та сестрами, яких було вбито, але ми зустрінемося знову на тому боці. Проте їхні обереги все ще мають велику цінність в цьому світі. Те, що вони в руках хутропузів — велика ганьба!\n\n{ім'я}, ти маєш повернути ці обереги. Вони лежать в скринях в печерах Колючохутрих на околиці селища хутропузів, що на північ від Астранаару.", [3] = "Принесіть 8 трольських оберегів Міцуві на форпост Зорам'ґар.", [4] = "{стать:Знайшов:Знайшла} обереги, {ім'я}? Мої нутрощі киплять від люті, поки ці священні речі в їх лапах!", [5] = "Ти {стать:знайшов:знайшла} їх! Дякую, {ім'я}! Ти й гадки не маєш, що це для мене означає.\n\nТроль без оберега як орк без бойових шрамів...\n\nНічого не вартий.", ["en"] = "Troll Charm", ["tasks"] = { ["Troll Charm"] = "трольський оберіг", ["Troll Charm (Provided)"] = "трольський оберіг (видано)" } },
    [6481] = { [1] = "Пробудження земельника", [2] = "Завдяки тобі, {клас:к}, було виявлено містичну загрозу для землі. У резонітовому контейнері, який ти {стать:знайшов:знайшла} в тій печері, дрімав земельник, на ім'я Ґоґґерок.\n\nЗа допомогою своїх шаманських сил, я змінив вміст кристалів резоніту, які ти {стать:приніс:принесла}. Візьми зачарований кристал резоніту і вдар по резонітовому контейнеру, в якому спить земельник.\n\nПрокинувшись, Ґоґґерок буде ослаблений... Убий його, {ім'я}!", [3] = "Відкрийте резонітовий контейнер за допомогою зачарованого кристала резоніту, а потім вбийте Ґоґґерока. Поверніться до Мор'роґала з новинами та зачарованим кристалом резоніту.", [4] = "Боюся, якщо ми негайно не усунемо цю загрозу, то втратимо Каміннопазуристі гори. Могутність земельника неможливо порівняти ні з чим. Прокинувшись, Ґоґґерок буде ослабленим від довгого сну, ти {стать:повинен:повинна} скористатися цією можливістю... Йди негайно {ім'я}!", [5] = "Ти {стать:приніс:принесла} хороші новини, {клас:к}! Я боявся того, що земельник може зробити з Калімдором.\n\nЗавдання вбити Ґоґґерока {стать:міг виконати тільки такий герой:могла виконати тільки така героїня}, як ти. Ти добре {стать:впорався:впоралася}. Всі Каміннопазуристі гори та Калімдор в боргу перед тобою, {стать:шляхетний:шляхетна} {клас:к}.\n\nПрийми це як почесну винагороду.", ["en"] = "Earthen Arise", ["tasks"] = { ["Enchanted Resonite Crystal"] = "зачарований кристал резоніту", ["Enchanted Resonite Crystal (Provided)"] = "зачарований кристал резоніту (видано)", ["Goggeroc"] = "Ґоґґерок", ["Goggeroc slain"] = "Ґоґґерок: убито" } },
    [6482] = { [1] = "Свободу Руулу", [2] = "Що? Ти хто?\n\n{ім'я}? Ти не хутропуз. Кляті потвори! Вони вирішили, що я ведмідь та схопили мене, а тепер вони морять мене голодом! Я втрачаю сили...\n\nДопоможи мені втекти, а потім поговори з моєю сестрою Ямою на заставі при Тріснутому Дереві, що на сході.\n\n{ім'я}! Я маю вибратися звідси!", [3] = "Проведіть Руула в безпечне місце, а потім поговоріть з Ямою Сніжним Копитом на заставі при Тріснутому Дереві.", [4] = "Ти {стать:бачив:бачила} мого брата Руула? Він пішов до лісу кілька днів тому й досі не повернувся...", [5] = "Ти {стать:знайшов:знайшла} мого брата! Його схопили Колючохутрі? Це жахливі новини, бо хоча деякі хутропузи — шляхетні істоти, плем'я Колючохутрих спотворено.\n\nДякую, що {стать:визволив:визволила} мого брата, {ім'я}. Не хочу й думати про те, як вони поводилися з бідолашним Руулом. Скоріше за все, він буде довго висипатися після цього випробування.", ["en"] = "Freedom to Ruul", ["tasks"] = { ["Escort Ruul from the Thistlefurs."] = "Ескорт Руула з Будячих Хутрянок." } },
    [649] = { [1] = "Повернення шипучки", [2] = "У мене є для тебе одне дільце, і якщо ти, як і я, любиш чудову шипучку — тобі сподобається це завдання. Шипучка!\n\nЦе напій такий, дурепо.\n\nНа покинутій ординській заставі є заначка медової шипучки Внутрішніх земель. Такого чудового питва більше не роблять! Один із цих бовдурів, помічників Малтона, знає, куди треба йти. Сходи до нього, принеси ящик шипучки та кілька пляшок для моєї колекції! Поговори з Малтоном, він розповість тобі всі деталі.", [3] = "Поговоріть з Малтоном Дрофферсом в Орґріммарі.", [5] = "А, так, ти щодо шипучки, що потрібна батьку! Він хоче продати її в таверну в Орґріммарі, але ми отримаємо більше грошей, якщо вона буде в оригінальній упаковці. Я знаю декого, хто може її добути, і він живе у Внутрішніх землях, де й знаходиться шипучка. Але він, тойво... вищий ельф.\n\nНу, він хороший вищий ельф, бо він не з Альянсу. Ну, він не стільки хороший ельф, скільки п'яний ельф. Він любить випивку. Прямо ОБОЖНЮЄ її.", ["en"] = "Ripple Recovery" },
    [650] = { [1] = "Повернення шипучки", [2] = "Ельфа, з яким тобі потрібно буде поговорити, звати Ґілверадін Сонцеслід. Він так знається на винах, що вміє за запахом визначити не тільки сорт вина, а і якого воно врожаю! Він може надіслати потрібну нам шипучку, потрібно лише поговорити з ним. Нам потрібно шість пляшок на продаж, дві — батьку... а може й більше. Коли забереш пакунок шипучки разом з кількома пляшками для батька — повертайся сюди!\n\nҐілверадін живе неподалік від оселі вищих ельфів у Внутрішніх землях. А ті вищі ельфи — не добрі, повір мені.", [3] = "Поговоріть з Ґілверадіном Сонцеслідом. Його табір розташований у Внутрішніх землях.", [5] = "То ти знаєш Малтона? Він мій давній товариш по пляшці. Розумієш, я знайшов те, що долає всі штучні кордони й умовності — випивку. Якби розумні істоти випивали, замість того щоб воювати, світ став би набагато кращим і чистішим.\n\nТа щось мені підказує, що ти тут не для того, щоб слухати про благословенні властивості алкоголю, чи не так?", ["en"] = "Ripple Recovery" },
    [6503] = { [1] = "Вісниці Ясенедолу", [2] = "Нам доповіли, що вісниці Ясенедолу нещодавно покинули Срібнокрилу заставу і тепер підкрадаються до наших лісних кордонів. Ми не хочемо, щоб вони збирали відомості про нашу оборону!\n\nСпробуй прокрастись лісами на південь від нашого посту і на схід від Срібнокрилої застави, що належить Альянсу. Знайди й вбий вісниць, а потім повертайся до мене.", [3] = "Вбийте 9 вісниць Ясенедолу та поверніться до Курай'біна на заставу Розщепленого Дерева.", [4] = "Я чекаю на твою доповідь про вбитих вісниць, {ім'я}.", [5] = "Дуже добре, {ім'я}. Твої мисливські навички вражають...\n\nВтрата цих вісниць допоможе осліпити Альянс. Якщо їм бракуватиме розвідданих, ймовірність нападів зменшиться.", ["en"] = "Ashenvale Outrunners", ["tasks"] = { ["Ashenvale Outrunner"] = "вісниця Ясенедолу", ["Ashenvale Outrunner slain"] = "вісниця Ясенедолу: убито" } },
    [6504] = { [1] = "Втрачені сторінки", [2] = "Я тільки-но забрала подрібнювач в Брашпилі та поверталася до лісозаготівельного табору Пісні Війни, де я повинна служити. Мені дали інструкцію про те, як користуватися подрібнювачем, але різкий порив вітру вирвав її з рук. Сторінки розлетілися, залишилася тільки обкладинка.\n\nНапевно, ті сторінки вже можуть бути де завгодно... але без них я не знаю, як користуватися подрібнювачем! Пошукаєш їх для мене?", [3] = "Знайдіть 12 загублених сторінок інструкції з експлуатації подрібнювача і складіть їх разом, щоб сформувати розділи 1, 2 і 3. Поверніть сторінки Ґурді Лютошрам на заставу при Тріснутому Дереві.", [4] = "Сподіваюся, ти скоро знайдеш ті сторінки, {ім'я}! Мені конче потрібно повертатися до роботи!", [5] = "Читання — не одна з моїх сильних сторін... але тепер я можу повернутися до роботи! Дякую, {ім'я}!", ["en"] = "The Lost Pages", ["tasks"] = { ["Shredder Operating Manual - Chapter 1"] = "інструкція з експлуатації подрібнювача — розділ 1", ["Shredder Operating Manual - Chapter 1 (Provided)"] = "інструкція з експлуатації подрібнювача — розділ 1 (видано)", ["Shredder Operating Manual - Chapter 2"] = "інструкція з експлуатації подрібнювача — розділ 2", ["Shredder Operating Manual - Chapter 2 (Provided)"] = "інструкція з експлуатації подрібнювача — розділ 2 (видано)", ["Shredder Operating Manual - Chapter 3"] = "інструкція з експлуатації подрібнювача — розділ 3", ["Shredder Operating Manual - Chapter 3 (Provided)"] = "інструкція з експлуатації подрібнювача — розділ 3 (видано)" } },
    [6521] = { [1] = "Нечестивий союз", [2] = "Малкін написав, що він знаходиться біля нір Бритвоболотих. Цього посла треба вбити — ми не можемо дозволити йому виконати волю Короля-ліча.\n\nЙого присутність в цих землях все пояснює — сили деяких тамтешніх свинобразів різко зросли водночас проявляючи ознаки Чуми. Схоже, вони про щось домовились з Малкіном.\n\nЗнайди й вбий його, {ім'я}. Повертайся, як виконаєш це завдання.", [3] = "Принесіть голову посла Малкіна до Варматраса в Підмістя.", [4] = "Тобі вдалось знайти посла, {ім'я}? Він мертвий?\n\nМи не можемо дозволити Скарі закріпитись в Калімдорі. Вони вже несуть вдосталь загрози нашим землям — ми не можемо дозволити їм відкрити ще один фронт.\n\nЄдине, що вселяє оптимізм — те, що сама відьма, здається, не прийняла цю силу. Схоже, вона розуміє, що хоча Скара й може запропонувати велику силу, та з нею вона не зможе заволодіти Степами.", [5] = "Добре. Дуже добре, {клас:к}.\n\nТепер, коли Малкін мертвий, ми можемо бути впевнені, що Скара поки не зможе просунутись далі. Темна Леді дякує тобі за відданість та хоче запропонувати винагороду.\n\nХоч ми й не знаємо всіх масштабів поширення Скари в норах Бритвоболотих, я впевнений, незабаром ми розкриємо їхні плани.", ["en"] = "An Unholy Alliance", ["tasks"] = { ["Ambassador Malcin's Head"] = "голова посла Малкіна", ["Ambassador Malcin's Head (Provided)"] = "голова посла Малкіна (видано)" } },
    [6522] = { [1] = "Нечестивий союз", [2] = "Моя Леді,\n\nНаша пропозиція вам добре відома. Це чудова можливість отримати владу над Степами та навколишніми землями. В обмін ми просимо лише про свободу нашої діяльності в цих землях.\n\nПросимо розглянути й обговорити нашу пропозицію. Ми володіємо великими силами, якими охоче поділимось з усіма, хто достатньо розсудливий, щоб приєднатись до нас. Я чекатиму біля нір Бритвоболотих.\n\nЗ найкращими побажаннями,\nПосол Малкін", [3] = "Принесіть маленький сувій Варіматрасу в Підмістя.", [4] = "Про що ти хочеш поговорити, {ім'я}? Сподіваюсь, це щось дійсно важливе, якщо ти продовжуєш докучати мені.", [5] = "Я впізнаю знак на цьому сувої, {ім'я}. Ти {стать:знайшов:знайшла} це у тієї відьми, що править краалем Бритвоболотих? Цікаво.\n\nСхоже, що Скарі мало одного континенту. Цей посол Малкін — один зі слуг Скари. Він був дипломатом у людей Лордерону до того як все... змінилось.\n\nЯкщо Скара дійсно хоче закріпитись в Калімдорі — прийшла пора діяти.", ["en"] = "An Unholy Alliance", ["tasks"] = { ["Small Scroll"] = "маленький сувій", ["Small Scroll (Provided)"] = "маленький сувій (видано)" } },
    [6523] = { [1] = "Захист Кайї", [2] = "Дякую, що {стать:врятував:врятувала} мене! Треба швидше тікати, поки вони не дізналися, що я на волі. Будь ласка, проведи мене до табору Апарахе. Звідти я вже знаю дорогу.\n\nМій батько, Макаба Пласке Копито, напевно, місця собі не знаходить, не знаючи де я.", [3] = "Проведіть Кайю Плоске Копито до табору Апарахе, потім поверніться до Макаби Плаского Копита на південно-східний край Каміннопазуристих гір.", [5] = "Кайя жива! {ім'я}, дякую, що {стать:врятував:врятувала} її.", ["en"] = "Protect Kaya", ["tasks"] = { ["Kaya Escorted to Camp Aparaje"] = "Каю супроводжують до табору Апараже" } },
    [6541] = { [1] = "Доповідь Кадраку", [2] = "Ти вже {стать:бував:бувала} в Ясенедолі, на півночі? Орда нещодавно організувала там заставу на Зорамському узбережжі, і нам завжди потрібні новобранці для захисту нових кордонів.\n\nЯкщо тобі це до персонажа, зустрінься з Кадраком у північних Степах, на сторожовій вежі. Він керує кампанією в Ясенедолі та може дати тобі доручення.", [3] = "Поговоріть з Кадраком на сторожовій вежі в північних Степах.", [5] = "Ясенеділ — розділений війною край, але наші нещодавні зусилля були дуже плідними. Ми заснували заставу не тільки на Зорамському узбережжі, але й прямо на північ звідси, при Тріснутому Дереві.", ["en"] = "Report to Kadrak" },
    [6542] = { [1] = "Доповідь Кадраку", [2] = "Ти вже {стать:бував:бувала} в Ясенедолі, на півночі? Орда нещодавно організувала там заставу на Зорамському узбережжі, і нам завжди потрібні новобранці для захисту нових кордонів.\n\nЯкщо тобі це до персонажа, зустрінься з Кадраком у північних Степах, на сторожовій вежі. Він керує кампанією в Ясенедолі та може дати тобі доручення.", [3] = "Поговоріть з Кадраком на сторожовій вежі в північних Степах.", [5] = "Ясенеділ — розділений війною край, але наші нещодавні зусилля були дуже плідними. Ми заснували заставу не тільки на Зорамському узбережжі, але й прямо на північ звідси, при Тріснутому Дереві.", ["en"] = "Report to Kadrak" },
    [6543] = { [1] = "Накази Пісні Війни", [2] = "Нещодавно я відправив кількох розвідників в Ясенеділ і мені потрібен гінець, що доставить їм накази та повернеться з їхніми звітами про спостереження.\n\nТвоєю першою зупинкою має бути форпост Зорам'ґар, що на Зорамському узбережжі, де ти знайдеш першого гінця. Також тобі доведеться зазирнути на заставу при Тріснутому Дереві, що на півночі, і вздовж дороги на схід, біля Азшари. Там ти знайдеш розвідницю та вершницю.\n\nПередай кожному з них накази, а від них отримай звіти про їхні спостереження.", [3] = "Відкрийте зв'язку наказів. Передайте накази Пісні Війни розвідниці Пісні Війни, гінцю Пісні Війни та вершниці Пісні Війни. Віднесіть отримані у них звіти Кадраку на північну сторожову вежу в Степах.", [4] = "Поквапся, {ім'я}. Вони мають отримати свої накази, це терміново.", [5] = "Бачу, на тебе можна покластися. Ці звіти є надзвичайно важливими для здійснення наших планів щодо розширення влади в Ясенедолі. Тепер ми можемо планувати наш наступний крок.", ["en"] = "The Warsong Reports", ["tasks"] = { ["Warsong Outrider Update"] = "звіт вершниці Пісні Війни", ["Warsong Outrider Update (Provided)"] = "звіт вершниці Пісні Війни (видано)", ["Warsong Runner Update"] = "звіт гінця Пісні Війни", ["Warsong Runner Update (Provided)"] = "звіт гінця Пісні Війни (видано)", ["Warsong Scout Update"] = "звіт розвідниці Пісні Війни", ["Warsong Scout Update (Provided)"] = "звіт розвідниці Пісні Війни (видано)" } },
    [6544] = { [1] = "Наліт Торека", [2] = "Гей! {Клас:к}! Йди-но сюди!\n\nЯ і мої рейдери збираємося напасти на Срібнокрилу заставу на заході. Наша ціль — їхня командирка, Дюріель Місяцежар. Розвідники доповідають, що заставу добре охороняють вартові та воїни. Битва буде славною!\n\nХочеш розділити цю славу, {ім'я}? Тоді по закінченню звітуй про наш успіх моєму начальнику, Ертоґу Лютоіклу на заставі при Тріснутому Дереві.\n\nТо що скажеш? Ти з нами?", [3] = "Супроводжуйте Торека під час його нападу на Срібнокрилу заставу та Дюріель Місяцежар, а потім звітуйте Ертоґу Лютоіклу на заставі при Тріснутому Дереві.", [4] = "Торек мав завдання напасти на Срібнокрилу заставу. Чи був напад успішним?", [5] = "То напад Торека вдався! Чудова робота, {ім'я}. Нічні ельфи — гідний ворог. Трохи кістляві, але сильні та люті! Впевнений, що битва була видовищною...\n\nСподіваюся, ти {стать:отримав:отримала} кілька шрамів!", ["en"] = "Torek's Assault", ["tasks"] = { ["Take Silverwing Outpost."] = "Займіть форпост Срібнокрилих." } },
    [6545] = { [1] = "Звіт гінця Пісні Війни", [4] = "То ти тут з моїм наказом? Завжди приємно бачити новобранців з буйним характером і сильною волею.\n\nТобі краще швидко вчитися, якщо не хочеш відставати від інших. Загроза з боку наг зростає, {ім'я}. Відколи я прибув сюди, я бачив кілька нападів та брав участь в обороні.\n\nАле якщо хочеш долучитися, поговори з кимось іншим в аванпості.", [5] = "Що ж, Кадрак дізнається про це все з мого звіту. Віднеси це йому якнайшвидше.", ["en"] = "Warsong Runner Update", ["tasks"] = { ["Warsong Report"] = "наказ Пісні Війни", ["Warsong Report (Provided)"] = "наказ Пісні Війни (видано)" } },
    [6546] = { [1] = "Звіт від вершниці Пісні Війни", [4] = "{ім'я}, на цьому шляху на тебе чекає багато небезпечних зустрічей. Май це на увазі, подорожуючи цими землями. Альянс зовсім близько.\n\nМи оточені ворогами з усіх боків. В східному Ясенедолі сатири — грізна сила, що переважає нашу. До того ж я дізналася, що наги захопили значну територію Азшари.\n\nПриємно бачити, що наша чисельність росте. Будь {стать:готовий:готова} до того, що чекає попереду, {ім'я}.", [5] = "Віднеси мій звіт Кадраку. Поквапся, {ім'я}.", ["en"] = "Warsong Outrider Update", ["tasks"] = { ["Warsong Report"] = "наказ Пісні Війни", ["Warsong Report (Provided)"] = "наказ Пісні Війни (видано)" } },
    [6547] = { [1] = "Звіт розвідниці Пісні Війни", [4] = "Будь {стать:уважний:уважна}, {раса:к}. Ельфи часто ховаються в тінях...\n\nМи завжди повинні бути напоготові. Ми доклали неймовірних зусиль, аби завоювати цю землю, а ельфи шукають можливість забрати її у нас.\n\nГадаю, у тебе є для мене нові накази від Кадрака?", [5] = "Прозвітуй Кадраку про наші успіхи в стримуванні нічних ельфів. Все йде за планом.", ["en"] = "Warsong Scout Update", ["tasks"] = { ["Warsong Report"] = "наказ Пісні Війни", ["Warsong Report (Provided)"] = "наказ Пісні Війни (видано)" } },
    [6548] = { [1] = "Помстися за моє селище", [2] = "На моє село напав клан Зловісний Тотем і вбив майже всіх. Я знищив всіх, кого міг, але сам ледве врятував власне життя.\n\n{Ім'я}, все, чого я бажаю зараз, це щоб померло якомога більше цих негідників. Ти знайдеш їх на захід звідси.", [3] = "Вбийте 8 розбійників і 6 найманців Зловісного Тотема, а потім поверніться до Макаби Плаского Копита, що очікує вас на південно-східному кордоні Каміннопазуристих гір.", [4] = "Ти вже {стать:вбив:вбила} їх?", [5] = "{ім'я}, я вдячний тобі... але я ніколи не забуду, що Зловісний Тотем зробив з моїм селищем.", ["en"] = "Avenge My Village", ["tasks"] = { ["Grimtotem Mercenary"] = "найманець Зловісного Тотема", ["Grimtotem Mercenary slain"] = "найманець Зловісного Тотема: убито", ["Grimtotem Ruffian"] = "розбійник Зловісного Тотема", ["Grimtotem Ruffian slain"] = "розбійник Зловісного Тотема: убито" } },
    [655] = { [1] = "Молотобій", [2] = "Я... досі пам'ятаю все, ніби це було вчора. Стільки років без надії, прикутий до цього жахливого місця деревом і сталлю. І ось нарешті з'явився вождь! Молот Згуби, закутий у свою броню, з високо піднятим бойовим молотом.\n\nЦе було... Жахливо... Один удар цього боягуза вбив нашого героя. Він наскочив ззаду і пронизав його списом... Я впав на коліна, це був кінець. Яка надія? Яка ще може бути надія...", [3] = "Поговоріть з Тор'ґаном в Молотобої.", [5] = "А, ти щодо Ґор'мула. Так, схоже, що він так і не оговтався від смерті Молота Згуби.\n\nВін був полоненим тут, коли Орґрім і Тралл билися за звільнення табору. Але коли земля затряслася і наші брати втекли, він залишився. Позбавлений надії, він роками поневірявся на самоті, аж доки ми не повернулися, щоб закріпитися в Молотобої.", ["en"] = "Hammerfall" },
    [65593] = { [1] = "Серця закоханих", [2] = "Інкуба приваблюють серця закоханих, і що сильніше кохання, то потужнішою є приманка.\n\nУ своїх видіннях я бачу двох, перед чиїм коханням не встоїть жоден інкуб.\n\nУ Срібнохвойному пралісі Авеліна Ліллі шиє одяг для полеглих чарівників Бурштинового Млина. А в Степах Айзек Пірсон сподівається заробити статки у приморському містечку Ретчет.\n\nВони працюють, не покладаючи рук, але їхні серця прагнуть лише одне одного. Принеси ці серця Карендіну.", [3] = "Принесіть серця Авеліни Ліллі та Айзека Пірсона до Карендіна Галґара у храм Проклятих.", [4] = "А, {ім'я}, ти {стать:повернувся:повернулася}. Тобі вдалося здобути серця закоханих?", [5] = "Як і очікувалося. Чудова робота, {ім'я}.\n\n\n\nНедоумки.", ["en"] = "Hearts of the Lovers", ["tasks"] = { ["Avelina's Heart"] = "серце Авеліни", ["Isaac's Heart"] = "серце Айзека" } },
    [65597] = { [1] = "Зв'язування", [2] = "Час нарешті настав. Віднеси серця до кола виклику внизу. Поклади їх у центр і виклич інкуба.\n\nДемон не зрадіє, коли зрозуміє, що його заманили в пастку. Не піддавайся на його спокусу, {ім'я}. Ти маєш повністю підкорити його.\n\nТільки тоді я зможу навчити тебе заклинання, що зв'яже його з твоєю волею.", [3] = "За допомогою сердець закоханих викличте і підкоріть інкуба, а потім поверніть серця Карендіну Галґару у квартал Магії Підмістя.", [4] = "Інкуб володіє бойовою майстерністю, але ілюзорні чари — його найпотужніша зброя. Втратиш пильність хоча б на мить, і демон скористається можливістю зачарувати тебе.\n\nНе дай йому цього зробити, {ім'я}.", [5] = "Дивовижно. Напрочуд дивовижно. Сайаади спеціалізуються у полюванні на смертних. Багато чорнокнижників вважали себе достатньо сильними, щоб керувати ними, але натомість самі підкорялись їхнім чарам.\n\nЦе випробування не зламало тебе, {ім'я}, і ти {стать:заслужив:заслужила} на винагороду. Я навчу тебе заклинання виклику інкуба.", ["en"] = "The Binding", ["tasks"] = { ["Lovers' Hearts"] = "серця закоханих", ["Lovers' Hearts (Provided)"] = "серця закоханих (видано)", ["Summoned Incubus slain"] = "викликаний інкуб: убито" } },
    [65601] = { [1] = "Нещасне кохання", [2] = "Чоловіків-сайаадів називають інкубами. Ці істоти сповнені злоби й витонченої хитрості. Демона потрібно заманити в наш світ особливою приманкою — предметом, який уособлює велику любов і відданість. Якщо ти {стать:готовий:готова} довіритися сліпому поводиреві, {ім'я}, то слухай. В Орґріммарі, на схід від Розколини Тіні, вздовж Тракту, живе Маґар. Він тужить за Крільґе, своїм коханим. Знайди його. Він попросить тебе відшукати дещо цінне. Це і буде річ, яку ти маєш віднести Ґан'рулу.", [3] = "Поговоріть з Маґаром в Орґріммарі.", [5] = "Хто розповів тобі про Крільґе? Ти знаєш, де він? Краще не жартуй зі мною...", ["en"] = "Love Hurts" },
    [65604] = { [1] = "Зв'язування", [2] = "Так... Я відчуваю залишки почуттів, що переплелися з цими нитками. Любов вплетена в їхні стібки. Інкуб не зможе встояти. Віднеси це до кола виклику в наметі Нііру, {ім'я}. Виклич мерзенного інкуба і покажи йому, хто тут господар. Не сподівайтеся на легку перемогу. Приготуйся використовувати в бою всі свої здібності. Багато чорнокнижників поплатилися життям, недооцінивши демона. Коли підкориш інкуба — поверни тканину мені. Я повідомлю Маґару про твою знахідку.", [3] = "За допомогою вицвілої хустки викличте і підкоріть сукуба, а потім поверніть хустку Ґан'рулу Кривавому Оку в Орґріммар.", [4] = "Сайаади — володарі умів і мучителі душ. Їхній вигляд приносить радість серцю, залишаючи тебе без захисту, коли вони шматують твою плоть батогом і кігтями.\n\nНе піддавайся чарам інкуба, {ім'я}. Покінчи з ним швидко.", [5] = "Ха! Тобі вдалося, звісно!\n\nТи {стать:підкорив:підкорила} інкуба, і я із задоволенням навчу тебе викликати його. Твоя сила зростає, і я не сумніваюся, що це лише перші кроки до ще більшої могутності.\n\nЯ поверну хустку Маґару. Я знаю цього орка багато років, і ніколи не думав, що він буде піклуватися про когось так, як він піклувався про Крільґе.\n\nЦе ще раз нагадує про те, як ми відрізняємось від демонів. Ми володіємо їхніми силами, але вони ніколи не володітимуть нами.", ["en"] = "The Binding", ["tasks"] = { ["Summoned Incubus slain"] = "викликаний інкуб: убито", ["Withered Scarf"] = "вицвіла хустка", ["Withered Scarf (Provided)"] = "вицвіла хустка (видано)" } },
    [65610] = { [1] = "Якби ж ти був зі мною", [2] = "Я зустрів Крільґе, коли виготовляв місячне полотно в Ясенедолі. Його відправили туди для захисту місцевих жителів, але одного разу він зник... Його перестали шукати й вважають дезертиром, але я в це не вірю. Ми часто зустрічалися на озері Впалого Неба, поки його не захопили ті дикі трясовики. Я рідко прошу інших про допомогу, але буду дуже вдячний, якщо ти пошукаєш сліди Крільґе в Ясенедолі.", [3] = "Дослідіть озеро Впалого Неба в Ясенедолі та повідомте про свої знахідки Ґан'рулу Кривавому Оку в Орґріммарі.", [4] = "Так, що таке?", [5] = "Що це в тебе, {ім'я}? Хустка з... місячного полотна? Навіть не намагайся загравати зі мною.", ["en"] = "Wish You Were Here", ["tasks"] = { ["Withered Scarf"] = "вицвіла хустка" } },
    [6563] = { [1] = "Сутність Аку'Май", [2] = "На стінах тунелів до Чорноводни глибин можна знайти великі скупчення сапфірів. Нещодавно ми помітили, що наги збирають їх. Ми поки не знаємо, для чого їх сапфіри, та думаю, що наг потрібно зупинити. Ці кристали містять великі сили стихій, що робить їх потужним компонентом для магічних заклять.\n\nТи допоможеш мені, {ім'я}? Чорноводні глибини знаходяться на Зорамському узбережжі на північ від нашого форпосту.", [3] = "Принесіть 20 сапфірів Аку'Май до Дже'неу Санкрі в Ясенеділ.", [4] = "Як проходять пошуки сапфірів, {ім'я}? Ти {стать:бачив:бачила}, як наги їх збирають? Я молю предків, щоб нам вдалось зрозуміти, нащо їм ці кристали.", [5] = "Чудова робота, {ім'я}. Це ті самі кристали, про які я говорив. Цікаво...\n\nЯ відчуваю силу, що міститься в них. Вона притягує духів води. Що б наги не задумали робити з цими сапфірами... що ж, я радий, що ми відібрали їх.", ["en"] = "The Essence of Aku'Mai", ["tasks"] = { ["Sapphire of Aku'Mai"] = "сапфір Аку'Май", ["Sapphire of Aku'Mai (Provided)"] = "сапфір Аку'Май (видано)" } },
    [6565] = { [1] = "Відданість Старим Богам", [2] = "Ми не можемо дозволити цьому послідовнику Сутінкового Молота здійснити свій задум. Сутінковий Молот не розуміє духів природи. Вони вірять в Старих Богів — створінь хаосу й нищення, переможених за давніх-давен. Ми не дозволимо цьому Лорґусу добитися свого. Ти маєш зупинити його, {ім'я}. Я не можу цього зробити — мені не вистачить сили.\n\nЙти в Чорноводні глибини, знайди його і вбий. Повертайся до мене в Зорам'ґар, як закінчиш.", [3] = "Вбийте Лорґуса Джетта в Чорноводних глибинах і поверніться до Дже'неу Санкрі в Ясенеділ.", [4] = "Ти ще не {стать:знайшов:знайшла} його, {ім'я}? Ми маємо зупинити Лорґуса!", [5] = "Чудово! Дякую тобі, {ім'я}. Хай ми ще не покінчили з Сутінковим Молотом, та принаймні зірвали їх черговий план повернення Старих Богів.\n\nХтозна, що ще вони задумали. Та поки що ми можемо перепочити.", ["en"] = "Allegiance to the Old Gods", ["tasks"] = { ["Lorgus Jett"] = "Лорґус Джетт", ["Lorgus Jett slain"] = "Лорґус Джетт: убито" } },
    [6566] = { [1] = "Що приніс вітер", [2] = "Радий знову тебе бачити, {ім'я}. Вітер приніс новини зі Східних Королівств.\n\nСядь, послухай.", [3] = "Вислухайте Тралла.", [4] = "Терпіння, {ім'я}. Слухай уважно!", [5] = "Чи {стать:готовий:готова} ти взятися за це завдання?", ["en"] = "What the Wind Carries", ["tasks"] = { ["Thrall's Tale"] = "Оповідь Тралла" } },
    [6567] = { [1] = "Чемпіон орди", [2] = "Я отримав звістку від одного з моїх найвідданіших чемпіонів про те, що він, можливо, знайшов шлях до лігва дракона. Ти маєш знайти його.\n\nРексар блукає пустельними краями Спустошища, мандруючи між Каміннопазуристими горами та Фераласом. Він чекає на твоє прибуття.", [3] = "Розшукайте Рексара. Воєвождь сказав, що він мандрує дорогами Спустошища, між Каміннопазуристими горами та Фераласом.", [5] = "Існує лише один шлях до лігва дракона, {раса:к}.\n\nЛише найсильнішим з драконів чорної зграї дозволено входити до лігва матері чорних драконів. Для цього потрібно пройти багато випробувань і отримати ключ, зачарований самим генералом Драккісатом!\n\nІ оскільки ти не належиш до роду чорних драконів, у тебе можуть виникнути певні труднощі з отриманням пропуску.", ["en"] = "The Champion of the Horde" },
    [6568] = { [1] = "Завіт Рексара", [2] = "Що ти знаєш про ілюзії, {ім'я}? Розумієш, тобі потрібно створити ілюзію, щоб обійти захист Чорного крила.\n\nЯ знаю хто зможе допомогти тобі з цим. Вона вже не раз допомагала нам раніше, допоможе й тобі, якщо вважатиме, що твоє діло заслуговує на це.\n\nТи зможеш знайти відьму Міранду в Західних Зачумлених землях. Колись вона була головною ілюзіоністкою альянсу Лордерона, але її вигнали. Відправляйся туди й візьми з собою це послання.", [3] = "Передайте завіт Рексара відьмі Міранді в Західні Зачумлені землі.", [4] = "Не часто я бачу когось з Орди в цій частині Лордерону. Що ти {стать:приніс:принесла} для Міранди?", [5] = "<Міранда бере записку, завмирає на мить та посміхається.>\n\nЯк він? Маю на увазі, Рексар. Перестань, не роби такий розгублений вигляд. Лист не просто так залишено порожнім. Він несе у собі наміри й думки свого відправника. Судячи з його змісту, не дивно, що Рексар залишив його таким. Уяви, якби тебе схопили або вбили, а ця інформація опинилася б у ворога!\n\nТа не бери в голову! Міранда допоможе тобі, {раса:к}. Я в боргу перед воєвождем.", ["en"] = "The Testament of Rexxar", ["tasks"] = { ["Rexxar's Testament"] = "завіт Рексара", ["Rexxar's Testament (Provided)"] = "завіт Рексара (видано)" } },
    [6569] = { [1] = "Ілюзії Ока", [2] = "Отже, {раса:н} хоче стати {стать:одним:однією} з Чорного крила, правильно?\n\nСтворити потрібну тобі ілюзію не важко, але компоненти, необхідні для накладання чарів, дістати досить складно. Якщо Рексар і воєвождь довірили тобі це завдання, то Міранді залишається тільки погодитися з цим.\n\nВідправляйся до верхньої цитаделі Чорноскельного шпиля та вбий достатньо чорних драконідів, щоб наповнити їхніми очима одну з твоїх сумок.\n\nКоли збереш достатньо очей, повернись до Міранди.", [3] = "Відправляйтесь в Чорноскельний шпиль та зберіть 20 очей чорних драконідів. Коли виконаєте завдання, поверніться до відьми Міранди.", [4] = "Найважливіший інгредієнт будь-якої ілюзії — очі тих, кого ми хочемо імітувати.\n\n<Міранда вказує на мішок, вщерть набитий очима. На ньому красується напис \"Багряний Похід\".>\n\n<Міранда регоче.>", [5] = "Дай-но Міранді поглянути, {раса:к}.\n\nО, так, ці підійдуть.\n\nЗа допомогою цих очей Міранда зробить для тебе медальйон, який створить ілюзію, здатну обдурити вартових крила чорних драконів.", ["en"] = "Oculus Illusions", ["tasks"] = { ["Black Dragonspawn Eye"] = "око чорного драконіда", ["Black Dragonspawn Eye (Provided)"] = "око чорного драконіда (видано)" } },
    [6570] = { [1] = "Вуглечвар", [2] = "Я налаштувала цей медальйон необхідною магією для створення ілюзії підтримки всередині печери Вуглечвара.\n\nВуглучвар — старий дракон, древній воротар Нефаріана, котрий мав обов'язок перевіряти драконідів, що прагнуть стати елітними вартовими Оніксії.\n\nВідправляйся у Змієділ, що в Бруднопилкій трясовині, та увійди в лігво Вуглечвара. Опинившись усередині, вдягни на себе амулет і йди за своєю долею!", [3] = "Відправляйтесь у Змієділ, що в Бруднопилкій трясовині, та знайдіть лігво Вуглечвара. Коли потрапите всередину, одягніть на себе амулет обману драконів і поговоріть з Вуглечваром.", [5] = "Чи у нас закінчились здібні солдати, що Нефаріан присилає мені дитинча? Ти ніколи не пройдеш мої випробування, щеня.", ["en"] = "Emberstrife", ["tasks"] = { ["Amulet of Draconic Subversion"] = "амулет обману драконів" } },
    [6571] = { [1] = "Припаси для Пісні Війни", [2] = "В лісозаготівельному таборі Пісні Війни закінчуються припаси!\n\nПостачальниця за ім'ям Піксель в заставі при Тріснутому Дереві має наш вантаж пиляльних лез. В Грабіжній Бухті завідувач причалу Лозґіл має ящик з сокирами.\n\nЗ вантажем мастила та мотузки буде важкувато. Мотузки розкрадено Колючохутрими та Гидколісовими хутропузами, а сатири перехопили вантаж мастила та використовують його для огидних ритуалів в Ночеплині, Сатирнаарі та Завіані!\n\nДопоможеш мені?", [3] = "Зберіть припаси для Пісні Війни: пиляльні леза, лісозаготівельну мотузку, мастило та вантаж сокир для Локе Окарра на заставі при Тріснутому Дереві.", [4] = "Сподіваюся, ти знайдеш всі припаси. Якщо я не доставлю їх найближчим часом, я в халепі!", [5] = "Чудово, {ім'я}! Ти {стать:зекономив:зекономила} мені багато зусиль!\n\nАле не думай, що я невдячний!", ["en"] = "Warsong Supplies", ["tasks"] = { ["Logging Rope"] = "лісозаготівельна мотузка", ["Logging Rope (Provided)"] = "лісозаготівельна мотузка (видано)", ["Warsong Axe Shipment"] = "вантаж сокир Пісні Війни", ["Warsong Axe Shipment (Provided)"] = "вантаж сокир Пісні Війни (видано)", ["Warsong Oil"] = "мастило Пісні Війни", ["Warsong Oil (Provided)"] = "мастило Пісні Війни (видано)", ["Warsong Saw Blades"] = "пиляльні леза Пісні Війни", ["Warsong Saw Blades (Provided)"] = "пиляльні леза Пісні Війни (видано)" } },
    [6581] = { [1] = "Пиляльні леза Пісні Війни", [4] = "Прямісінько з Брашпиля, пиляльні леза Пісні Війни! Еге ж, маю їх тутечки.\n\nАле чим ти мені платитимеш? Я їх тобі не подарую! І мій час недешевий!\n\nОсь що мені насправді потрібно — то це рушниця, яку можна брати з собою в подорожі. Треба ж дівчині себе захистити, еге ж? Є рушниця, яка дуже мені подобається, і я впевнена, що вправний інженер легко таку зробить.\n\nТож якщо ти принесеш мені смертоносний мушкетон, я віддам тобі вантаж із пиляльними лезами. Домовилися?", [5] = "Ідеально — саме те, що потрібно! Ось твій вантаж.", ["en"] = "Warsong Saw Blades", ["tasks"] = { ["Deadly Blunderbuss"] = "смертоносний мушкетон", ["Deadly Blunderbuss (Provided)"] = "смертоносний мушкетон (видано)" } },
    [6601] = { [1] = "Вознесіння...", [2] = "З черепів наших ворогів формується медальйон. Ти впізнаєш цей медальйон, чи не так? Певно, ти {стать:бачив:бачила} його на своїх старійшинах.\n\nВізьми його, драконеня. Повертайся до Чорноскельного шпиля та передай медальйон генералу Драккісату. Генерал накладе на нього останнє закляття на медальйон, налаштує його на твій дух.\n\nТи носитимеш медальйон як знак честі, символ твоєї приналежності до одного з наших найвищих рангів: страж матері роду.\n\nЙди!", [3] = "Схоже, що обман виявився. Ви знаєте, що амулет обману драконів, який створила для вас відьма Міранда, не працюватиме всередині Чорноскельного шпиля. Можливо, вам слід знайти Рексара та пояснити йому все. Покажіть йому згаслий амулет полум'я дракона. Можливо, він знатиме, що робити далі.", [4] = "Без паніки, {ім'я}!", [5] = "Це просто балаканина драконів, {ім'я} — купа гарячого повітря і нуль суттєвої інформації. На твоєму місці, я б не надавав стільки значення їхнім словам.", ["en"] = "Ascension...", ["tasks"] = { ["Dull Drakefire Amulet"] = "згаслий амулет полум'я дракона", ["Dull Drakefire Amulet (Provided)"] = "згаслий амулет полум'я дракона (видано)" } },
    [6605] = { [1] = "Дивачка", [2] = "Я щойно повернувся зі Сквернолісся, {ім'я}. Дорогою я зупинився на Кровотруйній заставі та зустрів дуже дивну пані... Здавалося, її дуже цікавила одна річ, і я міг би розповісти тобі, що саме, але, думаю, вона краще про це розповість.\n\nЯкщо тобі цікаво, вирушай до Кровотруйної застави у західному Скверноліссі та знайди Вінну Гроззу.\n\nХто знає, можливо, їй знадобиться твоя допомога...", [3] = "Поговоріть з Вінною Гроззою у Скверноліссі.", [5] = "О, {клас}. Надія ще є. Ти тут, щоб допомогти мені?", ["en"] = "A Strange One" },
    [6606] = { [1] = "Трохи удачі", [2] = "Нам наколи не завадить трохи удачі, чи не так? Невелика перевага — це все, що потрібно, щоб повернути все на свою користь...\n\nЯкось мені довелося познайомитися з доволі ексцентричною знахаркою. Вона зробила мені талісман на щастя... за певну плату. Але повір, воно того варте!\n\nМожливо, ти захочеш собі такий же? Тоді знайди знахарку Мав'арі в Завшегляді. Я свій не віддам!", [3] = "Поговоріть зі знахаркою Мав'арі в Завшегляді.", [5] = "То тебе прислав Гарло? Ну, хто ти {стать:такий:така}? Гадаю, тобі потрібна моя допомога?", ["en"] = "A Little Luck" },
    [6608] = { [1] = "Нема чому тебе вже вчити", [2] = "Лумак не може більше вчити {ім'я}. Нема чому тебе вже вчити! Знайди друга Лумака, Нета Пеґла. Він людина, але не злий! Це друг Лумака! Нет навчить тебе ліпше ловити рибу.\n\nТи знайдеш Нета в Бруднолипкій трясовині, на південь від містечка людиськ, Терамо-якось-там. Нет, мабуть, рибалить. Йди!", [3] = "Здається, Лумак намагається сказати вам, що він більше не може допомогти вам вдосконалити ваші навички рибальства. Ви можете спробувати знайти його друга, Нета Пеґла, людину, що рибалить біля одного з островів на південь від Терамору (принаймні, вам здається, що Лумак так сказав).", [5] = "Ти, мабуть, друг Лумака.\n\nРибалиш? Я можу розказати тобі все про риболовлю.", ["en"] = "You Too Good." },
    [6611] = { [1] = "До Пристробляху!", [2] = "Ти ждеш, шо Замджа навчить тебе чомусь? В тебе є всі кулінарні рецепти Замджі, але ти все одно хоч більше!\n\nЗамджа не може помогти. {стать:Товстунчик:Товстунка} {раса} має піти в Пристроблях. Там ти найдеш маленького гобліна, на ім'я Могиль — він поможе тобі, {стать:товстунчик:товстунко}.\n\nКоли ти станеш {стать:великим кухарем:великою кухаркою}, повертайся і навчи Замджу, добре? А тепер йди!", [3] = "Прямуйте до Пристробляху в пустелю Танаріс і поговоріть з Могилем Хуткорізом про розвиток вашої кулінарної кар'єри.", [5] = "<Могиль випльовує шматок шкіри.>\n\nТьфу...\n\n<Могиль голосно кашляє.>\n\nЩо? Взагалі-то, у шкірі напрочуд багато білків і мало вуглеводів.", ["en"] = "To Gadgetzan You Go!" },
    [6621] = { [1] = "Король Гидколісових", [2] = "{ім'я}, на південний схід від Астранаару живе ще одне плем'я фурболгів — Гидколісові. Їх не так багато, як Колючохутрих, але їхня жорстокість становить загрозу в майбутньому. Демонструючи силу, ми можемо її усунути.\n\nВізьми цю хоругву, вирушай до поселення Гидколісових і встанови її на їхньому тотемному пагорбі. Вони намагатимуться знищити хоругву, але не здавайся, доки не з'явиться їхній вождь, Мурґут. Принеси мені його тотем.\n\nЗбери своїх союзників, {ім'я}. Це завдання не для {стать:одного:однієї} {клас:р}.", [3] = "Встановіть хоругву Каранґа на тотемному пагорбі племені Гидколісових. Не дозволяйте хутропузам знищити її. Подолайте вождя Мурґута і принесіть тотем Мурґута Каранґу Амаккару в Зорам'ґар.", [4] = "Ти {стать:переміг:перемогла} вождя Мурґута, {ім'я}? Чи вдалося тобі здобути його тотем?", [5] = "Чудова робота, {ім'я}. Кинути виклик Гидколісовим та подолати їхнього ватажка означає надіслати їм чітку звістку:\n\nЗ Ордою не жартують.\n\nДумаю, що це плем'я ще довго нас не турбуватиме.", ["en"] = "King of the Foulweald", ["tasks"] = { ["Murgut's Totem"] = "тотем Мурґута", ["Murgut's Totem (Provided)"] = "тотем Мурґута (видано)" } },
    [6622] = { [1] = "Перев'язка", [2] = "Добрий день, {стать:лікарю:лікарко}. Сьогодні ти пройдеш випробування на здатність відповідно перев'язувати пацієнтів. Якщо ти успішно пройдеш цей іспит, то приєднаєшся до лав травматологів Орди.\n\nТепер слухай уважно! Спочатку необхідно надати допомогу смертельно пораненим пацієнтам. Після них — тим, хто має важкі травми. Останніми йдуть легкопоранені. Тобі необхідно врятувати 15 пацієнтів, щоб пройти цей іспит. Якщо 6 з твоїх пацієнтів помруть, іспит вважатиметься проваленим.\n\nТи отримаєш перев'язувальні бинти.\n\nНехай щастить, {стать:лікарю:лікарко}.", [3] = "Врятуйте пацієнтів, використовуючи для перев'язки їхніх ран перев'язувальні бинти. Вам потрібно врятувати 15 пацієнтів, перш ніж 6 з них помруть від отриманих травм.\n\nПам'ятайте про порядок надання допомоги! Смертельно поранені солдати помирають найшвидше, а після них ті, хто має тяжкі рани. Легкопоранені солдати можуть прожити довше, тому їм треба надавати допомогу ПІСЛЯ того, як ви перев'яжете смертельно та важко поранених солдат.", [4] = "Чудесна робота, {стать:лікарю:лікарко}. Просто диво.", [5] = "{стать:Лікар:Лікарка} {ім'я}, вітаю в лавах травматологів Орди.", ["en"] = "Triage", ["tasks"] = { ["15 Patients Saved!"] = "15 пацієнтів врятовано!" } },
    [6623] = { [1] = "Травматолог Орди", [2] = "{стать:Лікар:Лікарка} {ім'я}, я так розумію. Радий тебе бачити.\n\nУ мене для тебе чудові новини! Грегорі Віктор, головний травматолог Орди, особисто попросив тебе поговорити з ним в Молотобої. Це може бути можливість всього життя! Я б все віддав за можливість навчатися у великого лікаря, Грегорі Віктора! Не змарнуй цю можливість, {стать:лікарю:лікарко}!", [3] = "Відвідайте Молотобій на височині Араті та поговоріть з лікарем Грегорі Віктором про вступ до лав травматологів Орди.", [5] = "Чудово. Одягай скраби, ми починаємо негайно!", ["en"] = "Horde Trauma" },
    [6627] = { [1] = "Випробування знань", [2] = "Ти {стать:приніс:принесла} мені книгу, настав час для запитання. Ти {стать:готовий:готова}?\n\nЧас — це не проблема, {клас:к}, тож не поспішай. Ти можеш відповідати стільки, скільки хочеш.", [3] = "Дайте правильну відповідь на питання Брауґа Тьмяного Духа, а потім знову поговоріть з ним. Він чекатиме в Каміннопазуристих горах, коли ви будете готові.", [4] = "Життя повне питань, {клас:к}. Ти ніколи не зможеш дати відповіді на всі, але якщо присвятиш трошки часу навчанню, можливо ти станеш більш {стать:обізнаним:обізнаною}.", [5] = "Молодець, {клас:к}. Ти {стать:вивчив:вивчила} книгу, а тепер маєш пройти іще одне випробовування.", ["en"] = "Test of Lore", ["tasks"] = { ["Answer Braug Dimspirit's question correctly"] = "Дайте правильну відповідь на запитання Брауга Дімспіріта" } },
    [6629] = { [1] = "Убити Ґрандіґа Темну Хмару", [2] = "{ім'я:к}, ти добре {стать:попрацював:попрацювала} над негідниками зі Зловісного Тотема. Але Ґрандіґ Темна Хмара і його власна банда громил набагато гірші. Це він очолив жорстокий напад на моє селище.\n\nТи знайдеш його на заставі Зловісного Тотема, трохи далі по дорозі на захід. Вбий його і я завжди буду вдячний тобі.", [3] = "Вбийте Ґрандіґа Темну Хмару та 6 моцаків з племені Зловісний Тотем і поверніться до Макаби Плаского Копита, який чекає на південно-східному краї Каміннопазуристих гір.", [4] = "Ти {стать:вбив:вбила} Ґрандіґа Темну Хмару і його моцаків?", [5] = "Ґрандіґ Темна Хмара мертвий! {ім'я}, я завжди буду вдячний тобі за те, що ти {стать:зробив:зробила} сьогодні.", ["en"] = "Kill Grundig Darkcloud", ["tasks"] = { ["Grimtotem Brute"] = "моцак Зловісного Тотема", ["Grimtotem Brute slain"] = "моцак Зловісного Тотема: убито", ["Grundig Darkcloud"] = "Ґрандіґ Темна Хмара", ["Grundig Darkcloud slain"] = "Ґрандіґ Темна Хмара: убито" } },
    [6641] = { [1] = "Ворша Катівниця", [2] = "Ворша Катівниця... жахлива гідра, що блукає морями...\n\nВона нападала на наш форпост зненацька, знищуючи все на своєму шляху.\n\nАле я готовий, {ім'я}. Я можу подолати гідру та покінчити з цими нападами на Зорам'ґар.\n\nНаги вшановують люту сутність цієї істоти, запалюючи жарівницю на острові неподалік від узбережжя. Думаю, якщо ми її погасимо, то розлючена Ворша з'явиться аби покарати нас.\n\nНам буде потрібна допомога, тож не забудь взяти з собою сильних друзів.", [3] = "Захищайте Муґлаша, поки він прямує до жарівниці. Допоможіть йому погасити жарівницю, а потім захистіть його під час битви з нагами.\n\nПо успішному виконанню завдання, поверніться до форпосту Зорам'ґар та повідомте гінця Пісні Війни про смерть Ворші Катівниці.", [5] = "За час мого перебування в форпості я бачив багато нападів наг. Мене заспокоює думка про те, що Ворша більше не буде вільно блукати морем.\n\nМи твої боржники, {ім'я}.", ["en"] = "Vorsha the Lasher", ["tasks"] = { ["Defeat Vorsha the Lasher"] = "Переможіть Воршу Батога" } },
    [671] = { [1] = "Нечиста магія", [2] = "Я відчув щось дивне в повітрі... відчуття, яке кипіло в моїй крові. У мене виникли підозри, чому це сталося. Я вирушив на пошуки джерела мого занепокоєння і виявив на заході, в Північному маєтку, залишкові сліди виклику демона. Коли я наблизився, моя кров буквально закипіла люттю.\n\nНа землі я знайшов амулет з кривавого каменю, який використовується для виклику демонів. Однак магічна сила знайденого мною амулету була вичерпана. Мені потрібен інший зразок для вивчення, але я не ризикну повертатися в маєток. Можеш принести мені звідти кілька амулетів?", [3] = "Принесіть 10 амулетів з кривавого каменю Тор'ґану в Молотобій.", [4] = "Колись проклята кров все ще тече в моїх жилах, {ім'я}. Якщо хтось викликає демонів, його треба зупинити!", [5] = "Мені знадобиться деякий час, щоб зрозуміти наміри Синдикату, але їхній очевидний зв'язок з темними, демонічними силами мене непокоїть. Я розповім тобі більше згодом.", ["en"] = "Foul Magics", ["tasks"] = { ["Bloodstone Amulet"] = "амулет з кривавого каменю", ["Bloodstone Amulet (Provided)"] = "амулет з кривавого каменю (видано)" } },
    [672] = { [1] = "Підняття духу", [2] = "Ми намагалися заспокоїти його, підбадьорити, розповідали йому про наше велике місто Орґріммар на Калімдорі, але його ніщо не чіпляє.\n\nІсторії про нашого молодого вождя, Тралла, що носить обладунки та молот Орґріма... але, можливо... Можливо! Демонстрація нашої відродженої шаманської магії може дати йому промінь надії. Варто спробувати!\n\nМи могли б зробити для нього одну річ, так... принеси мені очі рапторів, і я подивлюсь, що можна для нього зробити.", [3] = "Здобудьте 10 очей плоскогірних рапторів у плоскогірних бігунів та плоскогірних трупоїдів для Тор'ґана в Молотобої.", [4] = "Я зроблю для Ґор'мула амулет, який надасть йому силу рапторів. Можливо, це розпалить його внутрішній вогонь...", [5] = "Чудово. Душі рапторів, що віддали ці очі, наповнять цей амулет своєю силою.", ["en"] = "Raising Spirits", ["tasks"] = { ["Highland Raptor Eye"] = "око плоскогірного раптора", ["Highland Raptor Eye (Provided)"] = "око плоскогірного раптора (видано)" } },
    [673] = { [1] = "Нечиста магія", [2] = "У мене немає жодних сумнівів, що в стінах Стромварта живе могутній чорнокнижник. Час від часу вони використовують таємничу магічну реліквію, завдяки якій чорнокнижник викликає полчище демонів. Ми маємо негайно усунути це джерело енергії.\n\nЗнайди та вбий цього чорнокнижника. Принеси цей магічний предмет, і я зроблю все, щоб знищити його, і захистити цю землю від його злої сили.", [3] = "Заберіть мерзенну сферу з кривавого каменю у Марез Каптур і принесіть її Тор'ґану в Молотобій.", [4] = "Моя кров палає... дедалі сильніше з кожним днем. Чорнокнижника потрібно зупинити!", [5] = "Мої безсонні ночі нарешті закінчаться і я зможу відпочити, коли зруйную цю сферу. Дякую тобі, {ім'я}. Це моторошне нагадування про владу демонів над орками до того, як Пеклокрик звільнив їх від прокляття.", ["en"] = "Foul Magics", ["tasks"] = { ["Befouled Bloodstone Orb"] = "мерзенна сфера з кривавого каменю", ["Befouled Bloodstone Orb (Provided)"] = "мерзенна сфера з кривавого каменю (видано)" } },
    [674] = { [1] = "Підняття духу", [2] = "Ось, візьми цей амулет, віддай його Ґор'мулу, і поглянь, чи пробудить сила раптора полум'я воїна, що колись палало в його жилах.", [3] = "Віднесіть амулет із пазура раптора до Ґор'мула.", [4] = "Яка може бути надія, коли рука боягуза може вбити наймогутнішого із наймогутніших? Яка надія, скажи мені!", [5] = "Що це? Відшліфована кістка? Яка мені від неї користь? Хіба здатна ця дрібничка відновити честь Орди?", ["en"] = "Raising Spirits", ["tasks"] = { ["Raptor Talon Amulet"] = "амулет із пазура раптора", ["Raptor Talon Amulet (Provided)"] = "амулет із пазура раптора (видано)" } },
    [6741] = { [1] = "Більше здобичі!", [4] = "Мені потрібно більше уламків броні, {ім'я:к}! Ти маєш ще?", [5] = "І знову дякую, {ім'я:к}. Орда пишається тобою...", ["en"] = "More Booty!", ["tasks"] = { ["Armor Scraps"] = "уламки броні", ["Armor Scraps (Provided)"] = "уламки броні (видано)" } },
    [675] = { [1] = "Підняття духу", [2] = "<Ґор'мул кидає амулет на землю.>\n\nТебе послав Тор'ґан, так? Тьху! Ніяк не можу зрозуміти, нащо він жаліє мене! Милосердя відвернулося від мене, коли я не загинув в бою разом з вождем. Доля жорстоко розправилася зі мною...", [3] = "Поговоріть з Тор'ґаном.", [5] = "Бачу, що це не спрацювало. Нічого. Я відчуваю, що, показавши силу шаманів, ми допоможемо Ґор'мулу повернути віру в себе. Сила амулета була недостатньо велика, щоб переконати його в нашій відродженій силі.", ["en"] = "Raising Spirits" },
    [676] = { [1] = "Бій Молота", [2] = "Слабаки... всі вони. А ти, {клас:к}, на що {стать:витріщився:витріщилася}? Думаєш, ти {стать:особливий:особлива}, га? Чому б тобі не довести це?\n\nНа аванпост Молотобій в Араті напали вороги. Якщо ми не допоможемо їм найближчим часом, вони не встоять.\n\nУтім, не поспішай. Спершу треба випробувати твої навички. На північний схід від Стормґарду в Араті знаходиться курган огрів, який населяє плем'я Брилоруких. Коли ти впораєшся з ограми та їхніми громилами, вирушай до Драма Кепського в Молотобій.", [3] = "Вбийте 8 брилоруких огрів і 10 брилоруких громил, а потім знайдіть Драма Кепського на аванпості Молотобоя на височині Араті.", [4] = "У мене немає часу сокиру нагострити, не кажучи вже про те, щоб покинути заставу і вбити тих тварюк, що намагаються вбити моїх братів.\n\nТобі, здається, не вистачає досвіду навіть для звичайного бугая, не кажучи вже про {стать:повноцінного:повноцінну} {клас:р}. Чого ж ти хочеш, {ім'я}?", [5] = "Гадаєш, ти достатньо {стать:сильний:сильна}, щоб допомогти Молотобою? Хай буде так.\n\nСмалець відправив тебе на той курган огрів або сподіваючись, що ти там загинеш, або вважаючи, що ти достатньо {стать:сильний:сильна}, щоб допомогти нам. Так чи інакше, ти зараз тут, а мені потрібні бійці для боротьби з постійними нападами.\n\nЯкщо ти плануєш залишитися в Молотобої, то відпочинь, а потім приходь до мене. У нас вистачить для тебе роботи.", ["en"] = "The Hammer May Fall", ["tasks"] = { ["Boulderfist Enforcer"] = "брилорукий громило", ["Boulderfist Enforcer slain"] = "брилорукий громило: убито", ["Boulderfist Ogre"] = "брилорукий огр", ["Boulderfist Ogre slain"] = "брилорукий огр: убито" } },
    [677] = { [1] = "Заклик до зброї", [2] = "Тролі племені Зів'ялої Кори та огри клану Брилоруких співпрацюють разом, щоб вижити нас із цієї землі, але ми не збираємося поступатися ні їм, ні кому-небудь ще. Ми маємо їх перебити та показати, що ця земля є нашим домом.\n\nТролі від нас відреклися, а огри хочуть зжерти нас та відібрати у нас цінні речі. Та ми їм цього не дозволимо.\n\nМи почнемо атаку на тролів Зів'ялої Кори, що утримують територію на південь звідси. Перебий їх трохи, і повертайся коли їхні поселення заллються кров'ю.", [3] = "Вбийте 10 сокирожбурів Зів'ялої Кори, 10 мисливців за головами Зів'ялої Кори та 8 знахарів Зів'ялої Кори, після чого поверніться до Драма Кепського на аванпост Молотобій.", [4] = "Якщо ти ще не {стать:виконав:виконала} своє завдання — не стій тут, а йди та виконуй його. Чи може ти {стать:такий же зрадник:така ж зрадниця}, як і ці тролі.", [5] = "Я бачу сліди битви на твоїх обладунках, і піт на твоєму чолі. Дуже добре...", ["en"] = "Call to Arms", ["tasks"] = { ["Witherbark Axe Thrower"] = "сокирожбур Зів'ялої Кори", ["Witherbark Axe Thrower slain"] = "сокирожбур Зів'ялої Кори: убито", ["Witherbark Headhunter"] = "мисливець за головами Зів'ялої Кори", ["Witherbark Headhunter slain"] = "мисливець за головами Зів'ялої Кори: убито", ["Witherbark Witch Doctor"] = "знахар Зів'ялої Кори", ["Witherbark Witch Doctor slain"] = "знахар Зів'ялої Кори: убито" } },
    [679] = { [1] = "Заклик до зброї", [2] = "Настав час покінчити з цими почварами... і для цього знадобиться велика сила, {ім'я:к}. Ти {стать:довів:довела} кожною своєю дією готовність завдати цього останнього потужного удару. Лідери цих мародерів та вбивць сновигають в руїнах Стромварту, символі людської слабкості.\n\nЗнайди та вбий брилоруких лордів та їхніх прислужників-шаманів, що намагаються вигнати нас з цих земель.", [3] = "Вбийте 15 брилоруких шаманів, та 10 брилоруких лордів, після чого поверніться до Драма Кепського в аванпост Молотобій.", [4] = "Я бачу, як твоя сміливість згасає. Це говорить про те, що мої здогадки про тебе правдиві: твоя сила — ніщо в порівнянні з твоїми хвастощами.\n\nПовертайся, коли знищиш ворогів, або не повертайся ніколи.", [5] = "Твій народ може пишатися тобою, {ім'я}. Загроза тепер значно зменшилася, і я впевнений, що ми зможемо процвітати на цій височині.", ["en"] = "Call to Arms", ["tasks"] = { ["Boulderfist Lord"] = "брилорукий лорд", ["Boulderfist Lord slain"] = "брилорукий лорд: убито", ["Boulderfist Shaman"] = "брилорукий шаман", ["Boulderfist Shaman slain"] = "брилорукий шаман: убито" } },
    [680] = { [1] = "Справжня загроза", [2] = "Ти добре {стать:послужив:послужила} моєму чоловікові, {клас:к}. Але він не знає чому на наш форт постійно нападають.\n\nОр'Калар, права рука Муґ'Тола в Стромварті, ненавидить мого чоловіка і бажає йому смерті вже багато років.\n\nМої ворожіння говорять, що Ор'Калар готує пастку для мого чоловіка, тому я приховала від нього факт присутності цього огра.\n\nМій чоловік стрімголов кинеться битись з цим огром, щойно дізнається, тож я прошу тебе допомогти в убивстві цієї тварюки.", [3] = "Вбийте Ор'Калара та принесіть його голову до Коріни Кепської в Молотобій.", [4] = "Біля Вежі Аратора — ось де ти знайдеш Ор'Калара. Його смерть зупинить напади на Молотобій і захистить мого чоловіка.\n\nЯ бачу у твоїх очах, що ти вважаєш мене слабкою і безчесною через моє мовчання. Колись ти зрозумієш, що таке любов. Можливо, тоді ти зрозумієш, що є й інший вид сили й честі.\n\nА поки що, зроби, як я прошу, і вбий Ор'Калара.", [5] = "Ти {стать:зробив:зробила} мені велику послугу, {ім'я:к}. Знай, що мій чоловік та Молотобій будуть в безпеці завдяки тобі. Будь ласка, прийми цю нагороду за твою сміливість.", ["en"] = "The Real Threat", ["tasks"] = { ["Or'Kalar's Head"] = "голова Ор'Калара", ["Or'Kalar's Head (Provided)"] = "голова Ор'Калара (видано)" } },
    [6801] = { [1] = "Локолар — повелитель льоду", [4] = "Я родом з Громового Бескиду, {раса:к}. Сам Керн наказав мені допомогти клану Морозних Вовків у ці важкі часи.\n\nАле не будемо марно гаяти час. Ти маєш вбити наших ворогів і принести мені їхню кров. Коли крові буде достатньо, можна буде розпочати проведення ритуалу виклику.\n\nПеремога буде в наших руках, коли могутній елементаль ослабить армію Бурешпиля.", [5] = "Ми пролили достатньо ворожої крові. Я змішаю цю кров з рештою... І коли зберемо всі компоненти для жертвоприношення, повелитель льоду обвалить на цих псів з Бурешпиля увесь гнів клану Морозних Вовків!", ["en"] = "Lokholar the Ice Lord", ["tasks"] = { ["Stormpike Soldier's Blood"] = "кров солдата Бурешпиля", ["Stormpike Soldier's Blood (Provided)"] = "кров солдата Бурешпиля (видано)" } },
    [6825] = { [1] = "Поклик повітря — флот Ґаси", [4] = "Ми повинні підготувати новий підрозділ бойових вершників, {раса:к}. Мої вершники можуть завдавати вирішальний удар в бою, але перед підготовкою до штурму потрібно вгамувати їхній апетит.\n\nМені потрібно багато плоті солдат Бурешпиля, щоб прогодувати вершників! Сотні фунтів! Я впевнений, ти впораєшся, правда? Ворушись!", [5] = "Флот харчується їхньою плоттю. Вони їдять наших ворогів.\n\nСкоро ми вступимо в бій!", ["en"] = "Call of Air - Guse's Fleet", ["tasks"] = { ["Stormpike Soldier's Flesh"] = "плоть солдата Бурешпиля", ["Stormpike Soldier's Flesh (Provided)"] = "плоть солдата Бурешпиля (видано)" } },
    [6826] = { [1] = "Поклик повітря — флот Джезтора", [4] = "Ти багато {стать:зробив:зробила}, проте це лише початок!\n\nМої бойові вершники повинні з'їсти вдосталь плоті своїх жертв. Тоді вони зможуть завдати точних ударів по ворогах!\n\nМій флот другий по силі в повітряних військах. Це значить, що вони зможуть вдарити по найсильніших наших ворогах. Але для цього, моїм вершникам потрібна плоть лейтенантів Бурешпиля.\n\nПоквапся, солдате!", [5] = "Більше! Більше! Принеси ще більше м'яса, щоб мої вершники якнайшвидше вступили в бій!", ["en"] = "Call of Air - Jeztor's Fleet", ["tasks"] = { ["Stormpike Lieutenant's Flesh"] = "плоть лейтенанта Бурешпиля", ["Stormpike Lieutenant's Flesh (Provided)"] = "плоть лейтенанта Бурешпиля (видано)" } },
    [6827] = { [1] = "Поклик повітря — флот Малверіка", [4] = "Усі ці дні я сидів у клятій дворфійській дірі. Думаю, ти розумієш, що я хочу помсти!\n\nМи повинні усе чітко спланувати.\n\nДля початку, моїм бойовим вершникам потрібні цілі — особливі цілі. Потрібно наготувати їх плоттю командирів Бурешпиля. Але ці боягузи сховались глибоко у ворожих окопах. Та ти точно впораєшся з цим завданням", [5] = "Чому так мало?! Від кого, від кого, але від тебе я такого не очікував, {ім'я:к}. Давай, солдате! ВОРУШИСЬ! Потрібно більше плоті!", ["en"] = "Call of Air - Mulverick's Fleet", ["tasks"] = { ["Stormpike Commander's Flesh"] = "плоть командира Бурешпиля", ["Stormpike Commander's Flesh (Provided)"] = "плоть командира Бурешпиля (видано)" } },
    [688] = { [1] = "Союзники Мізраель", [2] = "<Мізраель говорить.>\n\nВільна! Я ВІЛЬНА! Тепер я можу вільно набиратися сил, сховавшись від моїх поневолювачів. Бо якби я постала перед ними зараз, вони б перемогли мене і знову ув'язнили.\n\nАле прийде час, я зустрінусь з ними й вони пошкодують, що забрали в мене свободу!\n\nТи {стать:благородний союзник:благородна союзниця}, {ім'я}. Мені скоро знову знадобиться твоя допомога. Коли я буду готова, ти викличеш мене на поверхню.\n\nПоговори з Заруком в Молотобої. Він знає, як мене викликати.", [3] = "Поговоріть з Заруком в Молотобої.", [5] = "Вітаю, {клас:к}. Пані сповістила мене про твій прихід, і якщо ми хочемо повернути її на поверхню, нам потрібно багато чого обговорити...", ["en"] = "Myzrael's Allies" },
    [6921] = { [1] = "Серед руїн", [2] = "Сутінковий Молот проник до руїн місячної святині в Чорноводних глибинах. Їхня присутність націлена на те, щоб обернути стихії проти нас. Якщо ми не будемо діяти, вони захоплять ці місця.\n\n{ім'я}, йди до Чорноводних глибин і знайди в руїнах камінь глибин. Він має бути десь неподалік під водою. В ньому заховано ядро глибин — пристрій, що дозволить нам зчитати дані про всю активність стихій. Якщо принесеш його мені — ми зі Служителями Землі зможемо зупинити їх!", [3] = "Принесіть ядро глибин Дже'неу Санкрі на форпост Зорам'ґар, що в Ясенедолі.", [4] = "Тобі вдалося знайти ядро глибин? Без нього ми не дізнаємось, чим там займається Сутінковий Молот.", [5] = "Це те, що мені потрібно! Ядро глибин — невичерпне джерело інформації, яку ми можемо звідти добути. Що б там не замислив Сутінковий Молот — а повір мені, нічого хорошого — ми з моїми побратимами дізнаємось про це.\n\nТи сьогодні добре {стать:потрудився:потрудилася} і Служителі Землі неймовірно вдячні тобі за це. Це також і допомога Орді, тож можеш пишатися собою.", ["en"] = "Amongst the Ruins", ["tasks"] = { ["Fathom Core"] = "ядро глибин", ["Fathom Core (Provided)"] = "ядро глибин (видано)" } },
    [6922] = { [1] = "Барон Акваніс", [2] = "Переможений водяний елементаль залишив після себе дивну водяну кулю. Ви припускаєте, що ця річ якимось чином живила потвору енергією. Всередині кулі хлюпоче гнила на вигляд вода. Сама куля здається непроникною для будь-якої фізичної сили.\n\nЯкщо хтось і може розібратися в ній, це Дже'неу Санкрі зі Служителів Землі. Він знаходиться на ординській заставі Зорам'ґар в Ясенедолі.", [3] = "Принесіть дивну водяну кулю Дже'неу Санкрі на форпост Зорам'ґар, що в Ясенедолі.", [4] = "О, ще раз вітаю, {ім'я}. Я тут зчитував морські хвилі, як завжди. Що привело тебе на заставу?", [5] = "Оце так знахідка, {ім'я}.\n\nКажеш, {стать:добув:добула} її у барона Акваніса в Чорноводних глибинах? Барон Акваніс здавна вважався спотвореним елементалем. Ця куля розкаже, що саме його зіпсувало. Я не здивуюся, якщо це Сутінковий Молот, але наші дослідження також покажуть, як саме вони зуміли це зробити.\n\nДобре, що ти мені це {стать:приніс:принесла}. Будь ласка, прийми це разом з найтеплішими побажаннями від Служителів Землі.", ["en"] = "Baron Aquanis", ["tasks"] = { ["Strange Water Globe"] = "дивна водяна куля", ["Strange Water Globe (Provided)"] = "дивна водяна куля (видано)" } },
    [6961] = { [1] = "Дідусь Зима вже тут!", [2] = "Щасливої Зимової Покрови, {стать:друже:подруго}! Обов'язково привітайся з Дідусем Зимою! Якщо ти {стать:був чемним:була чемною} цього року, то отримаєш чудові ласощі у день свята Зимової Покрови. Не забудь розказати йому, що саме тобі хотілося б отримати цього року!\n\nТакож не забудь приготувати частування для тих, хто був чемним цього року. У нас є з чого вибрати. Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу!", [3] = "Поговоріть з Дідусем Зимою біля торгового майданчика Пасовищ Димного Лісу в Орґріммарі.", [5] = "Хо-хо-хо, привіт. Я Дідусь Зима, і від імені моїх друзів з Пасовищ Димного Лісу, кхм... \"Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу!\", хочу побажати тобі казкового свята Зимової Покрови.\n\nЯкщо ти {стать:був чемним:була чемною} цього року, можливо, ти отримаєш ласощі від Пасовищ Димного Лісу як подарунок до свята Зимової Покрови. Хо-хо!", ["en"] = "Great-father Winter is Here!" },
    [6962] = { [1] = "Ласощі для Дідуся Зими", [2] = "Гей, можеш зробити Дідусеві Зимі послугу, {стать:хлопчику:дівчинко}?\n\nНе хочу без потреби говорити про себе в третій особі, але Дідусь Зими весь день на ногах, і йому б не завадило трохи імбирного печива і крижаного молока. Чи не {стать:міг би:могла б} ти допомогти Дідусеві Зимі, і принести їх мені?", [3] = "Принесіть 5 імбирних печив та крижане молоко Дідусеві Зимі в Орґріммар.", [4] = "Від усіх цих розмов про ласощі мені й самому захотілося чогось смачненького. Мммм... імбирне печиво з молоком...", [5] = "Ти дуже {стать:виручив:виручила} Дідуся Зиму, {ім'я}. Щасливого свята Зимової Покрови.\n\nОсь тобі дещо... ну, знаєш, за старання.", ["en"] = "Treats for Great-father Winter", ["tasks"] = { ["Gingerbread Cookie"] = "імбирне печиво", ["Gingerbread Cookie (Provided)"] = "імбирне печиво (видано)", ["Ice Cold Milk"] = "крижане молоко", ["Ice Cold Milk (Provided)"] = "крижане молоко (видано)" } },
    [6963] = { [1] = "Викрадені ласощі Зимової Покрови", [2] = "Слухай... не хочу руйнувати святковий настрій, але Пасовищам Димного Лісу потрібна допомога {стать:шукача:шукачки} пригод на кшталт тебе.\n\nМи втратили важливу партію ласощів, що мала поповнити наші запаси на цей сезон, і тепер ми не можемо знайти агента Пасовищ Димного Лісу, якого ми відправили на пошуки! Будь ласка, допоможи нам. Останні відомості про ласощі були з Альтерацьких гір, туди й пішов наш агент.\n\nЗнайди там його і наші ласощі!", [3] = "Знайдіть агента Пасовищ Димного Лісу, що зник у засніжених районах Альтерацьких гір.", [5] = "Т-т-ти мене ч-ч-чуєш! Слава б-б-богам!\n\nН-ні, я не с-с-сніговик. Мене звати Т-т-торб, я п-п-працюю в Орґріммарському відділенні П-п-асовищ Димного Лісу. М-м-м-м-мене відправили шукати зниклий товар, і тут н-н-на мене напала тварюка, якої я ніколи не б-б-бачив!\n\nБр-р, х-х-холодно!", ["en"] = "Stolen Winter Veil Treats" },
    [6964] = { [1] = "Привід для свята", [2] = "Подарунки, смаколики, частування... пфф, скажу я!\n\nТі гобліни спотворюють справжнє значення цього свята — Зимової Покрови. Це час оновлення. Земля спить під ковдрою снігу, принесеного Дідусем Зимою — НЕ отим незграбним дурнем у червоному костюмі!\n\nЯкщо тобі цікаво дізнатися про справжній сенс цього свята — запитай Саґорна Хребтоступа. Впевнений, він буде здивований, що хтось цікавиться історією свята, а не подарунками.", [3] = "Поговоріть з Саґорном Хребтоступом в долині Мудрості Орґріммара про свято Зимової Покрови.", [5] = "Свято Зимової Покрови, кажеш? На жаль, у минулі часи воно мало більш вагоме значення для нас, тауренів. Зараз, здається, всі перетворили легенду про Дідуся Зиму на рекламу для цукерок та подарунків.\n\nНе дивно, що Фурмунда це так засмучує. Він, та деякі інші схожі на нього таурени, тримаються за нашу історію, як за бойовий стяг. Хоча я вважаю, що невеликі веселощі ніколи не завадять, важливо пам'ятати й про його походження.", ["en"] = "The Reason for the Season" },
    [698] = { [1] = "Недостача надлишку", [2] = "Я намагаюся здобути припаси для нашого поста на узбережжі, на схід звідси. Ток'Кар робить, що може, але між змінами вартової служби та приготуванням їжі для солдатів, у нього залишається небагато часу.\n\nВони з задоволенням готують м'ясо пилкозубів, але я не встиг відправити їм нову партію. Не {стать:міг би:могла б} ти допомогти?\n\nМолоді пилкозуби не такі смачні, як дорослі, тому не чіпай їх — дай ще рік-два підрости.", [3] = "Принесіть 8 сирих вирізок пилкозуба Ток'Кару на болото Скорбот.", [4] = "Лок'тар, {клас:к}. Подорож через болота легкою не назвеш. Ти {стать:сміливий:смілива}, якщо випробовуєш свою вдачу тут.", [5] = "Ух! Чудово! Свіже м'ясо на вогнищі до вечері! Дякую, {ім'я}.\n\nТи {стать:допоміг:допомогла} зробити прийдешні вечори більш стерпними. Вогонь горить яскраво і наші шлунки будуть наповнені.\n\nПриємна несподіванка, що ти {стать:привіз:привезла} нам вантаж. Дар — не найпривабливіший орк у світі, але, принаймні, його ставлення приємніше, ніж його запах.", ["en"] = "Lack of Surplus", ["tasks"] = { ["Unprepared Sawtooth Flank"] = "сира вирізка пилкозуба", ["Unprepared Sawtooth Flank (Provided)"] = "сира вирізка пилкозуба (видано)" } },
    [6983] = { [1] = "Ти мерзенний...", [2] = "Це с-с-с-створіння, відоме як \"М-м-мерзенний Ґрінч\", саме воно викрало нашу партію ласощів, {ім'я}. Але будь {стать:обережним:обережною}! Це він перетворив мене на цього с-с-сніговика!\n\nТобі з-з-знадобиться допомога. Я бачив, як він вештався неподалік з іншими єті. З-з-знайди ласощі, {ім'я}, поверни їх до Пасовищ Димного Лісу в Орґріммар та с-с-скажи їм, що мене потрібно роз-з-зморозити!", [3] = "Знайдіть і поверніть викрадені ласощі Якобу Хапмідяку в Орґріммар. Востаннє вони були в Мерзенного Ґрінча, десь у засніжених районах Альтерацьких гір.", [4] = "{ім'я} — свято Зимової Покрови неможливе без ласощів! Сам Ґракку не зможе поділитися своїми смачними м'ясними пирогами зі слухняними дітками...", [5] = "Ти {стать:знайшов:знайшла} їх! Ти {стать:врятував:врятувала} свято Зимової Покрови!\n\nБідний Торб... ми надішлемо команду до нього та знайдемо спосіб розморозити його. Сподіваюсь, він повернеться до дня святкування. Він ще мусить відпрацювати пропущені години. Але це взагалі було б неможливо, якби не ти!", ["en"] = "You're a Mean One...", ["tasks"] = { ["Stolen Treats"] = "викрадені ласощі", ["Stolen Treats (Provided)"] = "викрадені ласощі (видано)" } },
    [6984] = { [1] = "Подяка від Пасовищ Димного Лісу!", [2] = "Пасовища Димного Лісу дуже вдячні тобі за повернення викрадених ласощів, {ім'я}. За це ти маєш отримати особливий подарунок... від самого Дідуся Зими!\n\nБудь ласка, поговори з Дідусем Зимою, і він вручить тобі подарунок від Пасовищ Димного Лісу. Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу... завдяки тобі, звісно!", [3] = "Поговоріть з Дідусем Зимою в Орґріммарі.", [5] = "Хо-хо-хо, привіт, {стать:авантюристе:авантюристко}!\n\nГобліни сказали мені, що ти {стать:заслужив:заслужила} на особливий подарунок цього святкового сезону, і я з радістю вручаю його тобі. Тримай — бажаю тобі чудового свята Зимової Покрови в цьому і кожному наступному році!", ["en"] = "A Smokywood Pastures' Thank You!" },
    [6985] = { [1] = "Припаси Залізодонних", [2] = "Дворфи Бурешпиля використовують копальню Залізодонних як склад. Я хочу, щоб ти {стать:пішов:пішла} в цю копальню і {стать:приніс:принесла} мені припаси звідти. Це послабить воїнів Бурешпиля в Альтерацькій долині та забезпечить нас необхідним спорядженням!\n\nБудь {стать:обережним:обережною}, {ім'я:к}. Копальня Залізодонних розташована на території Альянсу, і контролюють її так само мінливо, як падає сніг в Альтераці.", [3] = "Принесіть 10 припасів Залізодонних квартирмейстеру Орди в форт Морозних Вовків.", [4] = "Ти {стать:був:була} в копальні Залізодонних? А припаси? Ти {стать:забрав:забрала} їх?", [5] = "Ти {стать:зробив:зробила} це! Молодець, {ім'я:к}! Сподіваюсь, під час свого рейду ти {стать:пролив:пролила} кров кількох дворфів за Морозних Вовків!", ["en"] = "Irondeep Supplies", ["tasks"] = { ["Irondeep Supplies"] = "припаси Залізодонних", ["Irondeep Supplies (Provided)"] = "припаси Залізодонних (видано)" } },
    [699] = { [1] = "Недостача надлишку", [2] = "Мурлоки на узбережжі становлять небезпеку, тому ми тут, щоб захистити Камінард або, якщо сили ворога виявляться занадто великі, підняти тривогу. В нас небагато часу на відпочинок, і ми не відмовимося від додаткової допомоги.\n\nЗ пазурів пилкозубих кусачів виходить добра зброя, якщо виробити їх належним чином. Принеси мені кілька пазурів, і ти отримаєш нашу зброю в подяку за свіже м'ясо і хорошу компанію.", [3] = "Принесіть 6 пазурів пилкозубих кусачів Ток'Кару на болото Скорбот.", [4] = "Добра медовуха, тепле вогнище, армія орків і повний арсенал... це все, що дійсно треба нам на цьому узбережжі. Я не шкодую, що несу свою варту тут, охороняючи Камінард, але було б непогано якось зробити тут бункер або хоча б вежу.", [5] = "Радий бачити тебе {стать:живим і здоровим:живою і здоровою}, {ім'я}.\n\nЦі пазурі нам дуже знадобляться. Чим більше зброї у нас буде напоготові, тим краще.\n\nПочну роботу над твоїм екземпляром якомога швидше. Це не займе багато часу, я став досить вправним і швидким у виготовленні зброї.", ["en"] = "Lack of Surplus", ["tasks"] = { ["Sawtooth Snapper Claw"] = "пазур пилкозубого кусача", ["Sawtooth Snapper Claw (Provided)"] = "пазур пилкозубого кусача (видано)" } },
    [7001] = { [1] = "Порожні стайні", [2] = "Війна в долині забрала багато сил у наших солдатів. Ми повинні відновити сили!\n\nЯкщо ми наповнимо стайні, вовчі вершники знову зможуть виїхати на поле бою.\n\nВізьми цей намордник і знайди морозних вовків, що живуть у сусідньому лісі. Коли знайдеш вовка, скористайся намордником, щоб приручити його. Приведи прирученого звіра до мене та я поміщу його в стайню.\n\nКоли в нашій стайні буде достатньо вовків — вовчі вершники зможуть повернуться до патрулювання фронту.", [3] = "Знайдіть морозного вовка в Альтерацькій долині. Коли знайдете звіра, скористайтесь намордником Морозних Вовків та приручіть його. Після цього приручений морозний вовк піде з вами назад до доглядачки стайні Морозних Вовків. Поговоріть з нею, щоб отримати нагороду за впійманого вовка.", [4] = "Без твоєї допомоги вершники з племені Морозних Вовків були б без вовків, на яких можна вирушити в бій. Ти робиш нам велику послугу!", [5] = "Мені залишається тільки сподіватися, що ті, хто займається збором баранячих шкур, такі ж рішучі, як і ти, {ім'я:к}.\n\nТакими темпами ми заповнимо стайні за лічені години!", ["en"] = "Empty Stables", ["tasks"] = { ["Frostwolf Muzzled and Returned"] = "Морозний Вовк закуваний у намордник і повернувся" } },
    [7002] = { [1] = "Збруя зі шкури барана", [4] = "Поки одні наші солдати зайняті виловлюванням вовків для доглядачки стайні, інші повинні подбати про все, що необхідно для верхової їзди. Звісно, я говорю про збрую.\n\nТобі доведеться полювати на місцевих баранів. Тих самих баранів, яких кавалерія Бурешпиля використовує як коней!\n\nВбий їх та принеси мені їхню шкуру. Як тільки ми зберемо достатньо, можна буде зробити збрую для вершників. Вершники Морозних Вовків знову будуть їздити верхи!", [5] = "Молодець, солдате. Я дам тобі знати, коли зберу достатньо шкур.\n\nПродовжуй працювати!", ["en"] = "Ram Hide Harnesses", ["tasks"] = { ["Alterac Ram Hide"] = "шкура альтерацького барана", ["Alterac Ram Hide (Provided)"] = "шкура альтерацького барана (видано)" } },
    [701] = { [1] = "Підступність раптора", [2] = "З кількома додатковими компонентами я зможу створити предмет, що наповнить Ґормула підступністю раптора! Ця сила буде протікати по його венах, він пізнає нашу нову силу та знову пробудить в собі справжнього воїна.\n\nМені знадобляться серця рапторів, щоб створити предмет і зачаклувати його.", [3] = "Здобудьте 12 сердець рапторів з плоскогірних плотожерів для Тор'ґана.", [4] = "Я все приготував, тепер мені потрібні лише серця рапторів.", [5] = "Так, вони чудово підійдуть. Я поміщу сили та дух рапторів в цю сферу. Вона наповнить Ґор'мула їхньою лютою силою та розумом.", ["en"] = "Guile of the Raptor", ["tasks"] = { ["Raptor Heart"] = "серце раптора", ["Raptor Heart (Provided)"] = "серце раптора (видано)" } },
    [702] = { [1] = "Підступність раптора", [2] = "Візьми цю сферу і використай її енергію, щоб наділити Ґор'мула сутністю раптора. Впевнений, це підбадьорить його і відкриє нові горизонти життя. Коли він повернеться до нас, ми зможемо роз'яснити йому, в якому становищі перебуває нині Орда та отримаємо великого воїна, який буде битись з нами пліч-о-пліч.", [3] = "Віднесіть сферу Тор'ґана до Ґор'мула.", [4] = "Знову ти? Жалості Тор'ґана мені ще не вистачає...\n\nЩо ти {стать:приніс:принесла} мені цього разу? Кольорову ниточку? Чи, може, мотузку, щоб я міг покласти край своїм стражданням...", [5] = "Принаймні, цього разу це щось цікаве... Я відчуваю дивну силу...", ["en"] = "Guile of the Raptor", ["tasks"] = { ["Tor'gan's Orb"] = "сфера Тор'ґана", ["Tor'gan's Orb (Provided)"] = "сфера Тор'ґана (видано)" } },
    [7021] = { [1] = "Дідусь Зима вже тут!", [2] = "Щасливої Зимової Покрови, {стать:друже:подруго}! Обов'язково привітайся з Дідусем Зимою в Орґріммарі! Якщо ти {стать:був чемним:була чемною} цього року, то отримаєш чудові ласощі у день свята Зимової Покрови. Не забудь розказати йому, що саме тобі хотілося б отримати цього року!\n\nТакож не забудь приготувати частування для тих, хто був чемним цього року. У нас є з чого вибрати. Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу!", [3] = "Поговоріть з Дідусем Зимою біля торгового майданчика Пасовищ Димного Лісу в Орґріммарі.", [5] = "Хо-хо-хо, привіт. Я Дідусь Зима, і від імені моїх друзів з Пасовищ Димного Лісу, кхм... \"Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу!\", хочу побажати тобі казкового свята Зимової Покрови.\n\nЯкщо ти {стать:був чемним:була чемною} цього року, можливо, ти отримаєш ласощі від Пасовищ Димного Лісу як подарунок до свята Зимової Покрови. Хо-хо!", ["en"] = "Great-father Winter is Here!" },
    [7024] = { [1] = "Дідусь Зима вже тут!", [2] = "Щасливої Зимової Покрови, {стать:друже:подруго}! Обов'язково привітайся з Дідусем Зимою в Орґріммарі! Якщо ти {стать:був чемним:була чемною} цього року, то отримаєш чудові ласощі у день свята Зимової Покрови. Не забудь розказати йому, що саме тобі хотілося б отримати цього року!\n\nТакож не забудь приготувати частування для тих, хто був чемним цього року. У нас є з чого вибрати. Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу!", [3] = "Поговоріть з Дідусем Зимою біля торгового майданчика Пасовищ Димного Лісу в Орґріммарі.", [5] = "Хо-хо-хо, привіт. Я Дідусь Зима, і від імені моїх друзів з Пасовищ Димного Лісу, кхм... \"Свіжі продукти Пасовищ Димного Лісу — корисна смакота з лану до столу!\", хочу побажати тобі казкового свята Зимової Покрови.\n\nЯкщо ти {стать:був чемним:була чемною} цього року, можливо, ти отримаєш ласощі від Пасовищ Димного Лісу як подарунок до свята Зимової Покрови. Хо-хо!", ["en"] = "Great-father Winter is Here!" },
    [7061] = { [1] = "Свято Зимової Покрови", [2] = "Ось — якщо тобі цікаво дізнатися більше про свято Зимової Покрови, прочитай цю книгу. Хоча я вважаю, що наше тлумачення легенди є досить вірним, я, як знавець легенд, ціную перевірені джерела інформації.\n\nКоли закінчиш, віднеси книгу Керну Кривавому Копиту в Громовий Бескид. Впевнений, він буде радий почути, що хтось цікавиться історією нашого народу.", [3] = "Прочитайте книгу \"Свято Зимової Покрови\", щоб дізнатися більше про походження свята. Коли ви закінчите, віднесіть її Керну Кривавому Копиту в Громовий Бескид.", [4] = "Ласкаво просимо до Мулґору і нашого скромного поселення Громового Бескиду, {стать:друже:подруго}. Я завжди цікавлюся тими, хто виявляє зацікавленість у нашому народі та його історії. Ти ж саме через це стоїш переді мною?", [5] = "Легенди, пов'язані зі святом Зимової Покрови, з часом забулися у свідомості нашого народу. Так, я знаю, що гобліни допомагають оживити це свято з метою своєї власної користі, однак той факт, що ми хоча б у якійсь формі пам'ятаємо про нього, сприяє збереженню легенд.\n\nТвоє бажання піти за межі матеріального та дізнатися про наше минуле — це похвальна риса, {стать:юний:юна} {клас:к}. Мене тішить твоя мудрість.", ["en"] = "The Feast of Winter Veil", ["tasks"] = { ["The Feast of Winter Veil"] = "Свято Зимової Покрови", ["The Feast of Winter Veil (Provided)"] = "Свято Зимової Покрови (видано)" } },
    [7068] = { [1] = "Фрагменти тінекаменю", [2] = "У священному для кентаврів — Мародоні — була знайдена сильна магія. Племена кентаврів в Спустошищі готові віддати життя за цю територію, але вони не зможуть завадити нам взяти те, що нам потрібно!\n\nТи {стать:повинен:повинна} піти у Мародон і знайти там кам'яних створінь з тіньового каменю. Принеси мені ці фіолетові кристали, і Утель'най віддячить тобі.\n\nІ візьми з собою друзів, там небезпечно.", [3] = "Зберіть 10 фрагментів тінекаменю в Мародоні та поверніть їх Утель'наю в Орґріммар.", [4] = "Ти вже {стать:знайшов:знайшла} кристали? Ритуали сили, могутні закляття — цей тіньовий камінь дуже корисний для будь-яких видів арканічної магії.", [5] = "Ого! Це саме те, що потрібно для моєї магії. Ось, візьми одну з цих дрібничок та йди звідси... В мене купа справ.", ["en"] = "Shadowshard Fragments", ["tasks"] = { ["Shadowshard Fragment"] = "фрагмент тінекаменю", ["Shadowshard Fragment (Provided)"] = "фрагмент тінекаменю (видано)" } },
    [7082] = { [1] = "Кладовища Альтерака", [2] = "Лінія фронту в Альтерацькій долині постійно змінюється. Наші кордони постійно зміщуються, то туди, то сюди, коли ми зустрічаємося з нашими ворогами у смертельній сутичці. І, {ім'я:к}, кладовища — це місце, де точаться найзапекліші бої.\n\nЯ хочу, щоб ти {стать:атакував:атакувала} кладовище, яке утримує Альянс! Знайди кладовище з прапором Альянсу та вирви його з землі.\n\nЗробиш це і можеш вважати завдання виконаним, але... тобі потрібно буде протриматись на кладовищі кілька хвилин. Тоді воно стане нашим і війська прийдуть тобі на підмогу.", [3] = "Нападіть на кладовище та поверніться до капрала Тіки Кроворев в Альтерацькі гори.", [4] = "Атакуй кладовище, яке утримує Альянс!", [5] = "Молодець, {ім'я:к}! Чим більше кладовищ під нашим контролем, тим більше духів наших ворогів будуть безцільно блукати.", ["en"] = "The Graveyards of Alterac", ["tasks"] = { ["Graveyard Assaulted"] = "Напад на цвинтар", ["Graveyard Assaulted (Provided)"] = "Напад на цвинтар (видано)", ["Graveyard Assaulted slain"] = "Напад на цвинтар: убито" } },
    [7101] = { [1] = "Вежі та бункери", [2] = "Вежі та бункери — це важливі позиції й ми повинні захопити та утримати їх усі! Тому я хочу, щоб ти {стать:атакував:атакувала} бункер, який контролює ворог.\n\nДля цього зайди в бункер з прапором Альянсу. Всередині буде ще один прапор. Витягни цей прапор і на його місці з'явиться білий прапор Орди.\n\nЗроби це і можеш вважати завдання виконаним, але якщо ти протримаєшся на місці достатньо довго та якщо Альянс не відвоює його, то воно буде знищене!", [3] = "Захопіть ворожу вежу та поверніться до капрала Тіки Кроворев в Альтерацькі гори.", [4] = "Ти ще не {стать:штурмував:штурмувала} бункер, {ім'я:к}?! Чекаєш, поки інші відберуть твою славу?", [5] = "Я чув про твої досягнення! Це радує мене...\n\nТепер наші війська можуть безкарно просуватися вперед і довести, що Альтерацька долина — не місце для Альянсу!", ["en"] = "Towers and Bunkers", ["tasks"] = { ["Tower Captured"] = "Вежа захоплена", ["Tower Captured (Provided)"] = "Вежа захоплена (видано)", ["Tower Captured slain"] = "Вежа захоплена: убито" } },
    [7123] = { [1] = "Розмова з квартирмейстером", [2] = "{ім'я:к}, квартирмейстер Морозних Вовків набирає рекрутів для виконання завдань в шахтах Альтерацької долини. Поговори з ним, він розповість більше.\n\nЙди дорогою на захід та потрапиш до бункера, потім скористайся західним виходом, там ти знайдеш нашого квартирмейстера.", [3] = "Поговоріть з квартирмейстером Морозних Вовків.", [5] = "Вітаю тебе, {ім'я:к}! Радий бачити {стать:такого:таку} {клас:з}, як ти, що прагне зробити свій внесок для Орди. Поговорімо через хвилину, я маю для тебе життєво важливі завдання...", ["en"] = "Speak with our Quartermaster" },
    [7124] = { [1] = "Захоплення копальні", [2] = "Битва, яка розгорнулась в Альтерацькій долині дійшла до копалень Кригозубих та Залізодонних. Обидві копальні багаті на мінерали та обидві використовуються для зберігання припасів, тож не дивно, що їх так високо цінять!\n\nДопоможи нашим військам, {ім'я:к}! Захопи одну з копалень для Орди! Для цього увійди в ту копальню, яку ми не контролюємо та вбий того, хто там головний. Коли зробиш це, шахта стане нашою і ми відправимо війська для охорони!", [3] = "Захопіть шахту та поверніться до капрала Тіки Кроворев в Альтерацькі гори.", [4] = "Ти ще не {стать:захопив:захопила} шахту, {ім'я:к}! Знайди шахту, яку ми не контролюємо і вбий тамтешнього лідера!", [5] = "Ти {стать:захопив:захопила} шахту! Ми відправимо туди наших воїнів, це дозволить нам з легкістю видобувати руду з її надр та збирати припаси, що там сховані.\n\nХороша робота, {ім'я:к}.Ти {стать:зробив:зробила} вагомий внесок для наших військових.", ["en"] = "Capture a Mine", ["tasks"] = { ["Mine Captured"] = "Шахта захоплена", ["Mine Captured (Provided)"] = "Шахта захоплена (видано)", ["Mine Captured slain"] = "Шахта захоплена: убито" } },
    [7142] = { [1] = "Битва за Альтерак", [2] = "Дворфи Бурешпиля та їхні союзники вдерлися в Альтерацьку долину, і ми повинні вигнати їх звідти! Щоб виграти битву за Альтерак, ми повинні вбити їхнього генерала, Ванндара Бурешпиля!\n\nТи знайдеш Ванндара в Дун-Балдарі, на півночі Альтерацької долини.\n\nВбий його, {ім'я:к}, а потім повертайся до мене.", [3] = "Вирушайте в Альтерацьку долину та вбийте дворфійського генерала Ванндара Бурешпиля. Потім поверніться до Воґґи Смертехвата в Альтерацькі гори.", [4] = "Ми не потерпимо дворфів у себе вдома! Напади на наших ворогів та вбий їхнього ватажка, генерала Бурешпиля!", [5] = "Чудова робота, {ім'я:к}! Даремно Бурешпиль вдерся в наші землі.\n\nХа! Все, чого вони досягли — це смерті свого генерала!", ["en"] = "The Battle for Alterac", ["tasks"] = { ["Defeat Vanndar Stormpike."] = "Перемогти Ванндара Буревісника." } },
    [7161] = { [1] = "Випробувальні землі", [2] = "Вітаю, {клас:к}. Багато часу минуло відтоді, коли ми востаннє брали участь в бою. Важко розбудити старі почуття, але якщо вони прокинулися, то кров обов'язково проллється. Лють бою кличе нас...\n\nУсі новоприбулі до долини мають спочатку пройти бойове хрещення.\n\nГлибоко в печері Диколапих гнолів знаходиться знамено Морозних Вовків. Вирушай туди та знайди його. Поверни його мені і я нагороджу тебе відзнакою Морозних Вовків.", [3] = "Вирушайте до печери Диколапих, що розташована в Альтерацькій долині, на південний схід від головної бази та знайдіть знамено Морозних Вовків. Принесіть знамено отаману Лаґґронду.", [4] = "Прокинься! Прокинься, {ім'я:к}! Це не сон. Ти справді {стать:опинився:опинилася} в епіцентрі жорстокої битви!", [5] = "Жар, який ти відчуваєш — це пробудження твоєї душі. Твій дух прийняв заклик до зброї.\n\nВідтепер ти — {стать:один:одна} з Морозних Вовків, {ім'я:к}. Прийми мої вітання.\n\nЗавжди носи цю відзнаку з собою. В залежності від того, яке звання ти здобудеш в рядах Морозних Вовків, я заміню цю відзнаку на іншу, більш потужну.\n\nМожливо, колись ти досягнеш найвищого звання в клані Морозних Вовків. Якщо цей день коли-небудь настане, ти отримаєш Око Командування.", ["en"] = "Proving Grounds", ["tasks"] = { ["Frostwolf Banner"] = "знамено Морозних Вовків", ["Frostwolf Banner (Provided)"] = "знамено Морозних Вовків (видано)" } },
    [7163] = { [1] = "Отримання визнання", [4] = "<Отаман Лаґґронд віддає військове вітання.>\n\nПрийшов твій час, {ім'я:к}. Ти багато {стать:зробив:зробила} для клану Морозних Вовків і тим самим {стать:заслужив:заслужила} місце не лише солдата Морозних Вовків, але й {стать:друга:подруги}.\n\nЧудова робота! Давай свою відзнаку новачка.", [5] = "Ця нова відзнака показує твій ранг серед Морозних Вовків. Завжди носи її при собі.\n\nІ {клас:к}... Коли прийде твій час — помри з честю!", ["en"] = "Rise and Be Recognized", ["tasks"] = { ["Frostwolf Insignia Rank 1"] = "відзнака Морозних Вовків, ранг 1", ["Frostwolf Insignia Rank 1 (Provided)"] = "відзнака Морозних Вовків, ранг 1 (видано)" } },
    [7164] = { [1] = "Повага клану", [4] = "Радий знову бачити тебе, {клас:к}. Я не думав, що ти повернешся. Але ти {стать:показав:показала} що ти — сміливий і почесний солдат Морозних Вовків.\n\nЗнову прийшов твій час, {ім'я:к}. Ти {стать:заслужив:заслужила} новий ранг і, відповідно, нову відзнаку, що підкреслить це.\n\nДавай свою відзнаку.", [5] = "<Отаман Лаґґронд віддає військове вітання.>\n\nВперед, {ім'я:к}! Продовжуй захищати Морозних Вовків. Цю війну потрібно виграти! За Дрек'Тара! За воєвождя!", ["en"] = "Honored Amongst the Clan", ["tasks"] = { ["Frostwolf Insignia Rank 2"] = "відзнака Морозних Вовків, ранг 2", ["Frostwolf Insignia Rank 2 (Provided)"] = "відзнака Морозних Вовків, ранг 2 (видано)" } },
    [7165] = { [1] = "Заслужена пошана", [4] = "Так багато полягло. Кров залила поля. І все ж... Ти {стать:вижив:вижила}. Ти {стать:вистояв:вистояла}. Завдяки тобі наша армія здобула багато перемог. За це, солдате, ти {стать:заслужив:заслужила} нове звання.\n\nПред'яви свою візнаку.", [5] = "<Отаман Лаґґронд ричить.>\n\nПро твої подвиги вже складають пісні, солдате. Бурешпиль тремтить від страху, коли чує твоє ім'я. Не зупиняйся!", ["en"] = "Earned Reverence", ["tasks"] = { ["Frostwolf Insignia Rank 3"] = "відзнака Морозних Вовків, ранг 3", ["Frostwolf Insignia Rank 3 (Provided)"] = "відзнака Морозних Вовків, ранг 3 (видано)" } },
    [7166] = { [1] = "Легендарні герої", [4] = "Ти випромінюєш владу і силу, {клас:к}. Морозні Вовки пишаються твоїм героїзмом, а ворог тремтить при згадці твого імені.\n\nВстань, {стать:герою:героїне} Морозних Вовків. Встань і прийми пошану!\n\nПокажи свою відзнаку.", [5] = "Незабаром все на полі бою буде під твоїм пильним поглядом. Командування долиною та її військами буде твоїм!", ["en"] = "Legendary Heroes", ["tasks"] = { ["Frostwolf Insignia Rank 4"] = "відзнака Морозних Вовків, ранг 4", ["Frostwolf Insignia Rank 4 (Provided)"] = "відзнака Морозних Вовків, ранг 4 (видано)" } },
    [7167] = { [1] = "Око Командування", [4] = "Дрек'Тар вихваляє тебе. Калімдор гуде від розповідей про твої подвиги. Воєвождь радіє — твій непохитний захист нашого клану йому дуже сподобався.\n\nТи {стать:заслужив:заслужила} Око Командування.\n\nПокажи свою відзнаку, командир {ім'я:н}.", [5] = "Спрямуй силу своєї відзнаки. Нехай ворог почує тебе. Могутність Орди незламна!", ["en"] = "The Eye of Command", ["tasks"] = { ["Frostwolf Insignia Rank 5"] = "відзнака Морозних Вовків, ранг 5", ["Frostwolf Insignia Rank 5 (Provided)"] = "відзнака Морозних Вовків, ранг 5 (видано)" } },
    [7201] = { [1] = "Останній елемент", [2] = "Є робота для тих, хто наважиться спуститися в надра гори, {ім'я}.\n\nКлан Темного Заліза навчився створювати надзвичайно потужних големів.\n\nСудячи з повідомлень від наших шпигунів, все вказує на те, що дворфи використовують унікальне джерело енергії, щоб наділити свої творіння надзвичайно вбивчою силою.\n\nТільки уяви, що б ми могли зробити з нашими потворами, якби роздобули цю сутність стихій! Переверни це місто догори дном, якщо потрібно, але не повертайся, доки не знайдеш сутність! Винагорода буде варта такого ризику.", [3] = "Відправляйтеся в Чорноскельні надра та відшукайте 10 сутностей стихій. Певно, найкраще почати пошуки з големів та їхніх творців. Ви також пригадуєте, що Вівіан Лягроб також бурмотіла щось про елементалів.", [4] = "<Потирає руки.>\n\nНу ж бо, покажи їх мені!", [5] = "Чудово! Я негайно відправлю їх кур'єром в Підмістя!\n\nОсь тобі оплата, як і обіцяла. Решту залиш собі, брудна тварюко!", ["en"] = "The Last Element", ["tasks"] = { ["Essence of the Elements"] = "сутність стихій", ["Essence of the Elements (Provided)"] = "сутність стихій (видано)" } },
    [7224] = { [1] = "Здобич з ворогів", [2] = "Коли вбиватимеш ворогів, збирай уламки їхньої броні та принось мені. З цих уламків я зроблю обладунки для нашого війська!", [3] = "Принесіть 20 уламків броні ковалю Реґзару в селище Морозних Вовків.", [4] = "Як іде полювання, {ім'я:к}? Ти {стать:зібрав:зібрала} для мене уламки броні?", [5] = "Так, ці підійдуть. Я їх сплавлю і підлатаю і ніхто ніколи не дізнається, що це обладунки тих боягузів з Бурешпиля!\n\nДякую, {ім'я:к}. Дозволь мені відполірувати твої обладунки...", ["en"] = "Enemy Booty", ["tasks"] = { ["Armor Scraps"] = "уламки броні", ["Armor Scraps (Provided)"] = "уламки броні (видано)" } },
    [7241] = { [1] = "На захист Морозних Вовків", [2] = "Здалека чутно барабани війни, {клас:к}. Клан твого воєвождя зазнає нападу з боку мерзенної варти Бурешпиля з Залізогарту.\n\nДивлячись на тебе, відразу видно, що ти зможеш вистояти в бою і стати на захист Морозних Вовків.\n\nТепер тобі потрібно зробити наступний крок для вдосконалення своїх навичок.\n\nЙди на північ від Тарренського Млину, в Альтераці, там буде вхід в Альтерацьку долину. Саме там ти знайдеш отамана Лаґґронда. Поквапся, бо битва незабаром почнеться!", [3] = "Вирушайте в Альтерацьку долину, що розташована в Альтерацьких горах. Поговоріть з отаманом Лаґґрондом, який стоїть біля входу в тунель, щоб розпочати свою кар'єру солдата Морозних Вовків. Ви знайдете Альтерацьку долину біля підніжжя Альтерацьких гір, на північ від Тарренського Млину.", [5] = "Щоб стати солдатом Морозних Ввовків, потрібно спочатку пройти випробування...", ["en"] = "In Defense of Frostwolf" },
    [728] = { [1] = "У Підмістя за збірником Яґіна", [2] = "Ця табличка говорить багато про що. І все ж цього недостатньо! І близько недостатньо!\n\nІснує книга, збірник, яку Яґін писав століття тому. Ті... від кого я втік... вони зберігають цю книгу в багатьох місцях. І наймудріші з них вивчають її. Вона містить великі знання. Знання, що здатні захистити нас!\n\nВирушай до хранителя Бел'дуґура у Підмістя, що в Лордероні. Покажи йому цю сигілу і він прийме тебе за свого. Попроси у нього збірник Яґіна... і принеси його мені!", [3] = "Принесіть сигілу молота хранителеві Бел'дуґуру в Підмістя.", [4] = "Ах, я бачу, що у нас тут {стать:нетерплячий:нетерпляча} {клас:н}. {стать:Прийшов:Прийшла} вивчати мою колекцію? Добре!\n\nАле пам'ятай: подібно до того, як знання дають силу сильним... вони зводять з розуму слабких.", [5] = "Будь {стать:розбірливим:розбірливою} зі своїми знаками, {клас:к}. Є ті, хто не вірить у праведність нашої обітниці.\n\nА є ті, хто, дізнавшись про нас, бажали б нашого знищення.\n\nМи повинні бути завжди обережними. І пильними. І терплячими.", ["en"] = "To the Undercity for Yagyin's Digest", ["tasks"] = { ["Sigil of the Hammer"] = "сигіла Молота", ["Sigil of the Hammer (Provided)"] = "сигіла Молота (видано)" } },
    [7281] = { [1] = "Братська любов", [2] = "Це велика трагедія... Я зіштовхнувся зі своїм братом на полі бою і він — один із командирів Бурешпиля.\n\nЗ чотирьох командирів Бурешпиля, він без сумніву найнебезпечніший. Можливо, якщо його хтось вб'є, Королева-Банші зможе воскресити його, як воскресила мене і тоді я доведу йому, як він помилявся...\n\nТи знайдеш мого брата далеко на території ворога. Вбий його і повертайся до мене. Я певен, ти впораєшся з цим завданням, солдате.\n\nІ, {ім'я:к}, не йди {стать:сам:сама}.", [3] = "Дістаньтесь до земель Бурешпилів та вбийте командира Карла Філіпса. Коли виконаєте завдання, поверніться до командира Луї Філіпса.", [4] = "Напевно, це дуже боляче. Бути живим, коли його улюблений брат відійшов у вічність.", [5] = "Твій героїзм не залишиться непоміченим, {ім'я:к}.\n\nМені не можна даремно витрачати час, якщо я хочу його врятувати. Потрібно зв'язатися з Сільваною!", ["en"] = "Brotherly Love", ["tasks"] = { ["Commander Karl Philips"] = "командир Карл Філіпс", ["Commander Karl Philips slain"] = "командир Карл Філіпс: убито" } },
    [7302] = { [1] = "Скинуті володарі небес", [2] = "Наші повітряні сили повністю розбиті, {ім'я:к}. Командири були збиті над ворожою територією. Ти {стать:повинен:повинна} з'ясувати, що з ними сталося, щоби ми спробували їх врятувати!\n\nВостаннє Ґас бачили, коли вона пролітала над Кригокрилим бункером. Бойового вершника Джезтора було помічено біля лісопильні Бурешпиля. А Малверік... Хтось бачив, як цей безвідповідальний дурень розбився біля північного бункера Дун-Балдара.\n\nЦе вся інформація, яка мені відома. Іди! Ретельно оглянь місцевість.", [3] = "Дізнайтеся, що сталося з командирами повітряних сил: Ґас, Джезтором та Малверіком. Коли виконаєте завдання, поверніться до командира Мулфорта.", [4] = "Як справи з полюванням, солдате?", [5] = "Молодець! Інформація, яку ти {стать:зібрав:зібрала}, має дуже важливе значення для нашої справи.", ["en"] = "Fallen Sky Lords", ["tasks"] = { ["Guse's Location Discovered"] = "Місцезнаходження Гусе виявлено", ["Guse's Location Discovered (Provided)"] = "Місцезнаходження Гусе виявлено (видано)", ["Guse's Location Discovered slain"] = "Місцезнаходження Гусе виявлено: убито", ["Jeztor's Location Discovered"] = "Розкрито місцезнаходження Джезтора", ["Jeztor's Location Discovered (Provided)"] = "Розкрито місцезнаходження Джезтора (видано)", ["Jeztor's Location Discovered slain"] = "Розкрито місцезнаходження Джезтора: убито", ["Mulverick's Location Discovered"] = "Розташування Малверіка виявлено", ["Mulverick's Location Discovered (Provided)"] = "Розташування Малверіка виявлено (видано)", ["Mulverick's Location Discovered slain"] = "Розташування Малверіка виявлено: убито" } },
    [7321] = { [1] = "Ніжний черепаховий суп", [2] = "Хто каже, що невмерлі нічого не розуміють в кулінарії? Зараз я розкрию тобі свій секретний рецепт черепахового супу. Знаю декого, хто повертався з мертвих лише для того, щоб насолодитися цією стравою! Хе-хе...\n\nДо речі, останнім часом мені ніяк не вдавалося його приготувати. Раніше я сам ходив до озера Лордамер, щоб знайти черепах, але я не можу відірватися від своєї роботи тут.\n\nЯкщо принесеш мені трохи черепашачого м'яса і духмяні спеції — я покажу тобі, як його готувати!", [3] = "Принесіть 10 шматків черепашачого м'яса і духмяні спеції Христофу Кітелю в Тарренський Млин.", [4] = "Вдалося знайти інгредієнти? Скажу тобі, що шпигунів Альянсу зараз занадто багато в цій місцині... Я вважаю, що вони підійшли вже занадто близько...", [5] = "Мій ніжний черепаховий суп зігріє тебе в холодну ніч... якщо, звісно, ти відчуваєш холод.", ["en"] = "Soothing Turtle Bisque", ["tasks"] = { ["Soothing Spices"] = "духмяні спеції", ["Soothing Spices (Provided)"] = "духмяні спеції (видано)", ["Turtle Meat"] = "черепашаче м'ясо", ["Turtle Meat (Provided)"] = "черепашаче м'ясо (видано)" } },
    [7361] = { [1] = "Прихильність Темного Списа", [2] = "<Наджак бурчить.>\n\nДо того, як з'явилися нічні ельфи, існували тролі. Саме від тролів походять нічні ельфи.\n\nМи не стерпимо їхні бунтівні напади на мій народ. Оленеріг прагне знищити нас, щоб не залишилося й сліду від тих, хто породив його і йому подібних. Цього ніколи не буде!\n\nЗа кожного нічного ельфа, якого ти вб'єш і обезголовиш, Наджак даруватиме тобі прихильність народу Темного Списа. Чутки про твої подвиги розійдуться по Калімдору та Східних Королівствах. Іди та служи Темному Спису!", [3] = "Вам доручили вбивати гравців-нічних ельфів у Альтерацькій долині.\n\nВбийте нічного ельфа і поверніться до Наджака Проклятуна в форт Морозних Вовків з відрубаною головою цього ельфа.", [4] = "Вони прагнуть нас знищити? Це ми їх знищимо.", [5] = "{ім'я:к}, це лише одна з тисяч. Проте, робота виконана добре.", ["en"] = "Favor Amongst the Darkspear", ["tasks"] = { ["Severed Night Elf Head"] = "відрубана голова нічного ельфа", ["Severed Night Elf Head (Provided)"] = "відрубана голова нічного ельфа (видано)" } },
    [7362] = { [1] = "Союзник тауренів", [2] = "Старша Відьма відправила мене на це поле бою для вивчення інших рас. Якщо точніше, я збираю зразки гномів. Маґата насамперед зацікавлена в тому, щоб вони були живі. Хоч гноми й жалюгідно слабкі та крихітні, але вони виділяються високою стійкістю на полі бою і не тільки.\n\nТобі пощастило, бо я якраз шукаю головоріза, який зможе виконати розпорядження Маґати. Дістань мені пучки волосся гномів і таурени будуть відноситись до тебе, як до {стать:союзника:союзниці}.", [3] = "Вам доручили вбивати ворожих гравців-гномів в Альтерацькій долині.\n\nВбийте гнома і віднесіть пучок його волосся Раваку Зловісному Тотему в форт Морозних Вовків.", [4] = "Мені байдуже, звідки саме ти вирвеш волосся, {раса:к}.", [5] = "Так, це без сумніву гном. Ти добре {стать:попрацював:попрацювала}, {раса:к}, але попереду ще багато роботи.", ["en"] = "Ally of the Tauren", ["tasks"] = { ["Tuft of Gnome Hair"] = "пучок волосся гнома", ["Tuft of Gnome Hair (Provided)"] = "пучок волосся гнома (видано)" } },
    [7363] = { [1] = "Людські хвороби", [2] = "Люди такі огидні.\n\n<Командир Філіпс кривиться.>\n\nХоч я і солдат Морозних Вовків, але я все одно залишаюся слугою Сильвани.\n\nУ вільний від служби час я підпрацьовую, допомагаючи аптекарям Підмістя.\n\nМені доручили збирати уламки людських кісток, які будуть використовуватись для лікування людських хвороб.\n\nЯ уповноважений давати такі завдання своїм підлеглим.\n\nЗнайди їх. Вбий їх. Та принеси мені уламки їхніх кісток.", [3] = "Вам доручили вбивати ворожих гравців-людей в Альтерацькій долині.\n\nВбийте людину і поверніться до командира Луї Філіпса (який блукає між лінією фронту і фортом Морозних Вовків) з уламком людської кістки.\n\nЛіки проти людських хвороб вже близько!", [4] = "Так, це правда. Мій брат — людина. Ганебно... Це пляма на моїй майже бездоганній репутації.", [5] = "Було б легше, якби вони просто прийняли свою хворобу і піддалися твоєму цілющому дотику. Хоча, мабуть, це було б не так весело. Не зупиняйся! Так чи інакше, ми їх вилікуємо.", ["en"] = "The Human Condition", ["tasks"] = { ["Human Bone Chip"] = "уламок людської кістки", ["Human Bone Chip (Provided)"] = "уламок людської кістки (видано)" } },
    [7381] = { [1] = "Повернення Коррака", [2] = "Хоч Коррака і вбили, залишається одне питання — чи справді він залишиться мертвим? Тролі відомі своєю потойбічною магією. Я не здивуюся, якщо він повернеться з мертвих, щоб знову правити своїм кланом.\n\nТи знаєш, що робити, якщо це станеться.\n\n<Отаман Лаґґронд проводить пальцем по своїй шиї.>\n\nІ цього разу мені потрібен його череп. Просто будь {стать:готовим:готовою}, солдате.\n\nВільно!", [3] = "Якщо Коррак Кроволютий з'явиться на полі Чвар, знайдіть його і знищте.\n\nПринесіть череп Коррака отаману Лаґґронду в передгір'я Гіллзбраду.", ["en"] = "The Return of Korrak", ["tasks"] = { ["Skull of Korrak"] = "череп Коррака", ["Skull of Korrak (Provided)"] = "череп Коррака (видано)" } },
    [7385] = { [1] = "Відро крові", [4] = "Було б добре якби ти {стать:приносив:приносила} мені більше крові, {ім'я:к}. Я б з радістю приймав її відрами.", [5] = "Ми пролили достатньо ворожої крові. Я змішаю цю кров з рештою... І коли зберемо всі компоненти для жертвоприношення, повелитель льоду обвалить на цих псів з Бурешпиля увесь гнів клану Морозних Вовків!", ["en"] = "A Gallon of Blood", ["tasks"] = { ["Stormpike Soldier's Blood"] = "кров солдата Бурешпиля", ["Stormpike Soldier's Blood (Provided)"] = "кров солдата Бурешпиля (видано)" } },
    [7401] = { [1] = "РОЗШУКУЮТЬСЯ: Дворфи!", [2] = "За наказом сержанта Язри Кроворев всі дворфи на полі бою повинні бути знищені на місці.\n\nЯкщо ви вб'єте дворфа в бою, вирвіть йому хребет та залиште це безхребетне смердюче тіло — воно буде лякати всіх, хто посміє протистояти могутності Морозних Вовків.\n\nПринесіть сержанту Язрі Кроворев докази свого подвигу.", [3] = "Вам доручили вбивати ворожих гравців-дворфів в Альтерацькій долині.\n\nВбийте дворфа і вирвіть йому хребет. Віднесіть цей хребет сержанту Язрі Кроворев у форт Морозних Вовків.", [4] = "Я працюю з іронією, солдате.", [5] = "Тепер ти можеш знищувати дворфів десятками, {клас:к}!\n\n<Язра на мить вдивляється в далечінь.>\n\nТи ніколи не забудеш свого першого вбивства...", ["en"] = "WANTED: Dwarves!", ["tasks"] = { ["Dwarf Spine"] = "хребет дворфа", ["Dwarf Spine (Provided)"] = "хребет дворфа (видано)" } },
    [742] = { [1] = "Ясенеділське полювання", [2] = "Увага, юні шукачі пригод! Дикі хащі Ясенедолу чекають на вас!\n\nОрді вдалося закріпитися в землях на північ від Степів. Дві наші застави — при Тріснутому Дереві та на Зорамському узбережжі — б'ються за славу Орди! Ті, хто хоче проявити себе у подвигах, можуть вирушити туди. Зверніть увагу: Сенані Грозове Серце на заставі при Тріснутому Дереві, що на північ від Степів, шукає охочих взяти участь у великому полюванні в Ясенедолі!", [3] = "Поговоріть з Сенані Грозовим Серцем на заставі при Тріснутому Дереві, що в Ясенедолі.", [5] = "Ласкаво просимо на наш новий рубіж, {ім'я}. Ясенеділ — це земля можливостей, де {стать:такому юній:такій юній} {клас:д}, як ти, знайдеться вдосталь шансів довести свою силу. Оглянь цю заставу та обов'язково сходи на Зорамське узбережжя — в Орди й там є застава.\n\nЯк розумію, ти тут для того, щоб дізнатися більше про полювання. Слухай уважно, і я з радістю поділюся з тобою всім, що тобі потрібно знати.", ["en"] = "The Ashenvale Hunt" },
    [743] = { [1] = "Небезпека Вітролютих", [2] = "Дякую, що {стать:знайшов:знайшла} час поговорити зі мною, {ім'я:к}. Я Руул, воїн і наставник.\n\nТи {стать:досяг:досягла} того віку, коли потрібно готуватися до випробувань що чекають тебе за межами Мулґора.\n\nЯкщо хочеш перевірити свою міць, почни з Вітролютих гарпій на південному сході. Вони гніздяться вздовж гір, подалі від дороги.\n\nЦі гарпії є одними з наших природних ворогів у Мулґорі, і вони стануть хорошим випробуванням твоєї майстерності.", [3] = "Принесіть 8 кігтів Вітролютих Руулові Орлиному Кігтю у селище Криваве Копито.", [4] = "Вітролюті — смертельні вороги. Їхня сила у бою може зрівнятись лише з їхньою жагою до свіжого м'яса.", [5] = "Ти добре {стать:впорався:впоралась}, {Ім'я}. Схоже, ти вже {стать:готовий:готова} подорожувати далі. Нехай вітри завжди віють тобі у спину.", ["en"] = "Dangers of the Windfury", ["tasks"] = { ["Windfury Talon"] = "кіготь Вітролютих", ["Windfury Talon (Provided)"] = "кіготь Вітролютих (видано)" } },
    [744] = { [1] = "Підготовка до церемонії", [2] = "{ім'я}, мій брат незабаром постане перед Вождем Кривавим Копитом, і мені випала велика честь зробити для нього головний убір.\n\nЯ хочу попросити тебе про послугу, поки я вичиняю ці шкіряні смужки. У мене немає часу, щоб знайти вдосталь пір'я, і я хотів би попросити тебе зібрати його для мене.\n\nПір'я потрібного розміру можна знайти у гарпій, що мешкають далеко на півночі та північному заході від Громового Бескиду. Мені потрібно лише 6 лазурових і 6 бронзових пір'їн, щоб закінчити роботу.", [3] = "Зберіть 6 лазурових і 6 бронзових пір'їн та принесіть їх Еяну Орлиному Кігтю в Громовий Бескид.", [4] = "Цей головний убір стане чудовим подарунком для мого брата.", [5] = "Дякую тобі за допомогу, {ім'я}.\n\nМоя участь у церемонії мого брата майже завершена. Мені залишається лише подарувати йому цей головний убір і спостерігати за церемонією.", ["en"] = "Preparation for Ceremony", ["tasks"] = { ["Azure Feather"] = "лазурова пір'їна", ["Azure Feather (Provided)"] = "лазурова пір'їна (видано)", ["Bronze Feather"] = "бронзова пір'їна", ["Bronze Feather (Provided)"] = "бронзова пір'їна (видано)" } },
    [745] = { [1] = "Розділення володінь", [2] = "{ім'я:к}, цю землю ранять безліч протистоянь. Я сподіваюся, що тобі не доведеться побачити їх стільки, скільки бачив їх я. Та все ж є одне, у якому я б попросив тебе взяти участь. Це допоможе тобі зрозуміти, наскільки жахливою може стати навіть найменша загроза для землі, якщо її не вирішити.\n\nБляклогриві гноли оселилися на південь від Кривавого Копита та у печері на заході. Вони ігнорують усі наші спроби налагодити з ними контакт та несамовито знищують природу Мулґору.\n\nСлова тут більше не зарадять.", [3] = "Убийте 10 бляклогривих дубильників, 8 бляклогривих шкуродерів і 5 бляклогривих браконьєрів, і повертайтеся до Бейна Кривавого Копита у селище Криваве Копито.", [4] = "Якби Бляклогриви більше поважали цю землю та її жителів, цього протистояння ніколи б не відбулося.", [5] = "{Ім'я}, це добре, що ти серйозно {стать:поставився:поставилась} до цього завдання. Важливо поважати землю та її створінь. Смерть і життя - це одне коло... неминучість. Одне не може існувати без іншого. Обдумай це без поспіху та постарайся ніколи не забувати.", ["en"] = "Sharing the Land", ["tasks"] = { ["Palemane Skinner"] = "бляклогривий шкуродер", ["Palemane Skinner slain"] = "бляклогривий шкуродер: убито", ["Palemane Tanner"] = "бляклогривий кожум'яка", ["Palemane Tanner slain"] = "бляклогривий кожум'яка: убито" } },
    [746] = { [1] = "Дворфійські розкопки", [2] = "На північному заході звідси дворфи готуються до розкопок. Вони думають, що таємниці приховані глибоко в землі, і це правда. Але осквернення та спустошення землі - не той шлях, який відкриє її мудрість.\n\nЗбери інструменти дворфів, розтрощи їх і повертайся до мене.\n\nЛамати інструменти можна в кузні. Одна з них розташована в Громовому Бескиді, але підійде будь-яка, навіть та, що у дворфійскому таборі.", [3] = "Зберіть 5 кайл розвідувачів.\n\nРозтрощіть кайла геологів у кузні, щоб отримати зламані інструменти.\n\nПринесіть 5 зламаних інструментів Бейну Кривавому Копиту в селище Криваве Копито.", [4] = "Привіт, {Ім'я}. Зламані інструменти у тебе? Дворфійські розкопки розлючують кодо Мулґору. Час покласти край оскверненню нашої землі!", [5] = "Дякую тобі, {Ім'я}. Це заспокоїть тварин Мулґору. Якщо на те буде воля духів, дворфи зрозуміють, що буріння землі - не найкращий шлях до нових знань.", ["en"] = "Dwarven Digging", ["tasks"] = { ["Broken Tools"] = "зламані інструменти", ["Broken Tools (Provided)"] = "зламані інструменти (видано)" } },
    [747] = { [1] = "Полювання розпочинається", [2] = "Ти виглядаєш досить багатонадійно і я вірю, що ти принесеш користь племені. Можливо, одного дня тебе приймуть у великому Громовому Бескиді. Та спершу ти маєш проявити себе перед моїм батьком, вождем Соколиним Вітром.\n\nТут, на плато Червоної Хмарини, ми відточили наші навички полювання. Таурени полюють і за необхідності, і для розваги. Та нині наші запаси м'яса вичерпуються і нам потрібно більше пір'я для одежі. Вполюй кількох рівнинобігів неподалік і поповни запаси селища.", [3] = "Ґрулл Соколиний Вітер з табору Нараче хоче, щоб ви принесли йому 7 пір'їн рівнинобіга та 7 шматків м'яса рівнинобіга.", [4] = "Принесені тобою м'ясо та пір'я будуть першим кроком, щоб показати себе {стать:справжнім:справжньою} {клас:о} перед вождем.", [5] = "Мешканці Нараче дякують тобі, {ім'я}. Ти подаєш великі сподівання.", ["en"] = "The Hunt Begins", ["tasks"] = { ["Plainstrider Feather"] = "пір'я рівнинобіга", ["Plainstrider Feather (Provided)"] = "пір'я рівнинобіга (видано)", ["Plainstrider Meat"] = "м'ясо рівнинобіга", ["Plainstrider Meat (Provided)"] = "м'ясо рівнинобіга (видано)" } },
    [748] = { [1] = "Отруйні води", [2] = "Гобліни та їхні посіпаки забруднили наші колодязі зі священною водою! Ми не можемо цього допустити.\n\nДля очищення кожного колодязя я повинен створити очисний тотем, тоді тобі потрібно принести його до колодязя та провести ритуал очищення.\n\nПершим ми зробимо тотем для колодязя Зимового Копита. Для цього земля повинна запропонувати нам свою допомогу. Вполюй степових вовків задля їхніх лап і дорослих рівнинобігів задля їхніх кігтів. Вони на південному заході.\n\nПовертайся до мене з лапами та кігтями, {ім'я:к}.", [3] = "Принесіть 6 лап степового вовка і 4 кігті рівнинобіга Муллу Громовому Рогу в Криваве Копито.", [4] = "Ти {стать:зібрав:зібрала} лапи та кігті, {ім'я:к}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я:к}. Я візьму їх та вплету їхню силу в тотем очищення.", ["en"] = "Poison Water", ["tasks"] = { ["Plainstrider Talon"] = "кіготь рівнинобіга", ["Plainstrider Talon (Provided)"] = "кіготь рівнинобіга (видано)", ["Prairie Wolf Paw"] = "лапа степового вовка", ["Prairie Wolf Paw (Provided)"] = "лапа степового вовка (видано)" } },
    [7481] = { [1] = "Ельфійські легенди", [2] = "Кілька років тому самотній ельфійський майстер, на ім'я Тельмій Снохочий втік зі своєї спустошеної батьківщини, прихопивши з собою кілька стародавніх ельфійських артефактів.\n\nПошуки цього загубленого майстра привели нас від руїн Квел'Таласа, через Палаючий степ та великі морські простори в Фералас.\n\nМи підозрюємо, що ельф шукав притулок в залах Ельдре'Таласа (нині відомого як Грізний Молот).\n\nТи {стать:повинен:повинна} знайти його, {клас:к}. Живим чи мертвим, але знання, які він забрав, необхідно повернути!", [3] = "Знайдіть Тельмія Снохочого в Грізному Молоті. Розкажіть мудрецю Королуску в таборі Мохаче про все, що зможете знайти.", [4] = "Моя напарниця — Руношип, нічна ельфа-дослідниця, вербує своїх союзників для виконання цього завдання.", [5] = "Шкода... Оце так трагедія. Кажеш, всі речі втрачено? І ти не {стать:знайшов:знайшла} жодних слідів Тельмія, так?", ["en"] = "Elven Legends", ["tasks"] = { ["Master Telmius Dreamseeker Found"] = "Знайдено майстра Тельміуса, шукача снів" } },
    [7489] = { [1] = "Тенета Лестендріс", [2] = "Ельфа крові Лестендріс перейшла всі межі. Вона так прагнула отримати магічну силу, що пішла проти своїх побратимів і створила підступний пристрій — тенета для збору брудної магічної енергії Грізного Молота. Навіть зараз вона збирає енергію і хоче випустити її на своїх ворогів.\n\nМи маємо зупинити Лестендріс. Знайди її у кварталі Хибнодревів, що в Грізному Молоті, здолай її та принеси мені тенета, щоб я відніс їх для вивчення більш свідомим ельфам крові.", [3] = "Принесіть тенета Лестендріс до Тало Обдертого Копита в табір Мохаче, що в Фераласі.", [4] = "{Ім'я}, ти {стать:дістав:дістала} тенета Лестендріс?", [5] = "Ти добре {стать:попрацював:попрацювала}, {ім'я}. Ці тенета наповнені величезними запасами магії Грізного Молота і я навіть боюся уявити, яку шкоду вона могла заподіяти, якщо б її використала така безвідповідальна ельфа, як Лестендріс. Я засмучений через її смерть, але знаю, що вона б ніколи не розлучилася зі своїми тенетами, поки була жива.\n\nДякую тобі, {ім'я}. Я відправлю тенета більш відповідальним спеціалістам з магії, аніж Лестендріс. Вони стануть новими хранителями цієї сили.", ["en"] = "Lethtendris's Web", ["tasks"] = { ["Lethtendris's Web"] = "тенета Лестендріс", ["Lethtendris's Web (Provided)"] = "тенета Лестендріс (видано)" } },
    [749] = { [1] = "Розорений караван", [2] = "Декілька днів тому ми помітили караван ТзНБ \"Авантюра\", що йшов під охороною по північному березі озера Кам'яного Бика. Ми втратили двох наших у битві раніше, тож ми були швидкі на напад і знищили караван.\n\nМи залишили позаду ящики з вантажем, думаючи, що наші смолоскипи знищать все цінне, але оскільки дехто з ТзНБ були помічені недалеко від спалених фургонів, можливо, ми помилялися.\n\nМоже, ти {стать:міг:могла} би піти до каравану та роздивитися вміст ящиків.", [3] = "Морін Ловець Хмар хоче, щоб ви обстежили вміст вантажних ящиків у розореному каравані.", [5] = "Усі сторони ящика пропечатані позначками шахтарського відділу ТзНБ \"Авантюра\". Обережно видрукувані примітки на боці картонних коробок вказують, що вміст призначений для переробки на одному з центральних заводів ТзНБ.", ["en"] = "The Ravaged Caravan" },
    [7490] = { [1] = "Перемога Орди", [2] = "Ви здійснили неможливе. Мертва матір чорних драконів лежить біля ваших ніг. Візьміть її голову та віднесіть вашому воєвождю.", [3] = "Принесіть голову Оніксії Траллу в Орґріммар.", [4] = "<Коли Тралл бачить величезну голову Оніксії, здається, на мить він втрачає звичний спокійний вигляд і несвідомо береться за свій легендарний Молот Згуби.>", [5] = "Це велика перемога для Орди, {ім'я}. Тобі вже не раз траплялося вшанувати свого воєвождя. Настав час і воєвождю вшанувати тебе.", ["en"] = "Victory for the Horde", ["tasks"] = { ["Head of Onyxia"] = "голова Оніксії", ["Head of Onyxia (Provided)"] = "голова Оніксії (видано)" } },
    [7491] = { [1] = "Щоб усі бачили", [2] = "Властитель Рунтак чекає на тебе в долині Сили.\n\n<Тралл віддає вам честь.>\n\nНе змушуй його чекати, {стать:герою:героїне}.", [3] = "Знайдіть властителя Рунтака в долині Сили.", [5] = "Обери свою винагороду і нехай розпочнеться святкування твоєї славетної перемоги!", ["en"] = "For All To See" },
    [7492] = { [1] = "Табір Мохаче", [2] = "Тало Обдерте Копито, старійшина тауренів у Фераласі, просить про допомогу. Він не надав подробиць, але сказав, що йому потрібні агенти для делікатної... та небезпечної справи.\n\nПослужи Орді, {ім'я}. Прямуй в табір Мохаче та поговори з Тало.", [3] = "Поговоріть з Тало Обдертим Копитом у таборі Мохаче, що у Фераласі.", [5] = "Приємно бачити {клас:р}, що {стать:відгукнувся:відгукнулася} на моє прохання. Мені потрібна твоя допомога, {ім'я}, але боюся, що це завдання заведе тебе в небезпечне місце...\n\nТвій шлях лежить в Грізний Молот.", ["en"] = "Camp Mojache" },
    [7493] = { [1] = "Все тільки починається", [5] = "Ти не тільки вбивця драконів, а ще й {стать:майстер:майстриня} шкірництва? Ти не перестаєш мене дивувати, {ім'я}. Я вражений.\n\nПрошу, прийми цей дар в знак моєї вдячності. Ці знання допоможуть тобі, якщо ти збираєшся покінчити з родом чорних драконів.\n\nСтвори плащ з луски матері чорних драконів. Він захистить тебе і твоїх союзників від нищівного дихання повелителя Чорнокамінної гори... Нефаріана.", ["en"] = "The Journey Has Just Begun" },
    [750] = { [1] = "Полювання продовжується", [2] = "Досвічений у полюванні таурен знає, що його здобич — це не просто трофей. Тварини рівнин дають нам ресурси для виживання. Ти справиш досить сильне враження на наших старійшин, якщо принесеш кілька шкур гірських пум. Ти знайдеш цих тварин на півдні, де вони скрадаються по схилах.\n\nНашим дітям потрібна одежа, а наші шатра варто підлатати.", [3] = "Ґрулл Соколиний Вітер у таборі Нараче хоче, щоб ви принесли йому 10 шкур гірських пум.", [4] = "Якщо ти зможеш забезпечити наше плем'я шкурами, я повідомлю своєму батьку, вождю Соколиному Вітру, про твої шляхетні вчинки.", [5] = "Таурени Нараче дякують тобі за цей внесок, {ім'я:к}. З такими мисливськими навичками одного дня тебе неодмінно шануватимуть у Громовому Бескиді.", ["en"] = "The Hunt Continues", ["tasks"] = { ["Mountain Cougar Pelt"] = "шкура гірської пуми", ["Mountain Cougar Pelt (Provided)"] = "шкура гірської пуми (видано)" } },
    [751] = { [1] = "Розорений караван", [2] = "Відкриття кришки розкриває тісно запаковані набори руди та мінералів - додатковий доказ гірничих операцій ТзНБ \"Авантюра\" у Мулґорі. З-понад матеріалів ви піднімаєте міцно зв'язаний стос паперів.\n\nВище у передгір'ї на сході ви можете ледве чути звуки роботи та бачити дим від великого вогнища.", [3] = "Поверніть папери ТзНБ \"Авантюра\" Моріну Ловцю Хмар біля селища Кривавого Копита.", [4] = "Вітання, {Ім'я}. Ти {стать:дізнався:дізналася} що-небудь нове про плани та операції ТзНБ \"Авантюра\" на наших землях?\n\nЯкщо вони планують розорювати наші землі так, як вони це робили з іншими, наші гінці швидко покладуть цьому край.", [5] = "Схоже на те, що ТзНБ \"Авантюра\" й справді намагається пограбувати нас на наші природні ресурси. Добре знати це напевно, і тепер, здається, ми повинні щось з цим зробити.", ["en"] = "The Ravaged Caravan", ["tasks"] = { ["Venture Co. Documents"] = "документи ТзНБ \"Авантюра\"", ["Venture Co. Documents (Provided)"] = "документи ТзНБ \"Авантюра\" (видано)" } },
    [752] = { [1] = "Скромне прохання", [2] = "Усі члени нашого племені поділяють життєву гармонію. Ми живемо разом і працюємо разом.\n\nНаша відданість одне одному несе з собою відповідальність. У мене є одне скромне прохання до тебе.\n\nМоя матінка вирушила на південний схід від Нараче набрати води з колодязя. З тої пори вже пройшло багато часу. Можливо, ти {стать:міг:могла} би її знайти, поки я займаюсь справами племені?", [3] = "Вождь Соколиний Вітер просить вас пошукати його матір біля колодязя на південному сході від табору Нараче.", [5] = "Ти {стать:пройшов:пройшла} увесь цей шлях лише для того, щоб допомогти старій жінці? Ох, у тебе дуже велике серце.", ["en"] = "A Humble Task" },
    [753] = { [1] = "Скромне прохання", [2] = "Я пройшла багато стежок за своє життя, і мої старі ноги вже не такі прудкі, як були раніше. Та все ж, я можу виконувати свої обов'язки перед плем'ям. Просто іноді робота забирає в літньої жінки трохи більше часу.\n\nАле ти {стать:схожий:схожа} на {стать:палкого:палку} {клас:з}. Випробуймо твою юнацьку жвавість. Візьми цей глечик для води та принеси його моєму сину, вождю, у табір Нараче.\n\nПам'ятай, що навіть найзвичайніше прохання може стати запорукою визнання старійшин.", [3] = "Наберіть глечик води з колодязя.\n\nПоверніть глечик вождю Соколиному Вітру в таборі Нараче, що лежить на північному заході від колодязя.", [4] = "Схоже, ти щойно {стать:повернувся:повернулась} з рівнин. Ти {стать:приніс:принесла} якусь звістку від праматері Соколиний Вітер?", [5] = "Бачу, ти {стать:приніс:принесла} цей глечик на прохання праматері.\n\nТвоя готовність допомагати іншим і піклуватися про тауренів табору Нараче впевнює мене у тому, що одного дня ти прославиш наше плем'я у Громовому Бескиді.", ["en"] = "A Humble Task", ["tasks"] = { ["Water Pitcher"] = "глечик води", ["Water Pitcher (Provided)"] = "глечик води (видано)" } },
    [754] = { [1] = "Очищення Зимового Копита", [2] = "Я змайстрував очисний тотем колодязя Зимового Копита. Тепер ти мусиш взяти його до колодязя та провести ритуал очищення. Ти знайдеш його на південний схід, під охороною мерзотних гоблінів!\n\nЦе буде непростим завданням, але ти {стать:повинен:повинна} зробити його, якщо ми хочемо коли-небудь використовувати воду колодязя знову.\n\nЩасти тобі, {Ім'я}.", [3] = "Використайте очисний тотем Зимового Копита біля колодязя Зимового Копита, після чого поверніться до Мулла Громового Рога.", [4] = "Не барися, {Ім'я}. Потрібно вичистити заразу з колодязя Зимового Копита!", [5] = "Новини про твій вчинок досягли мене лише миті тому: тварини радісно п'ють з нього воду.\n\nТи {стать:зробив:зробила} велику справу для цієї землі, {Ім'я}. І ти {стать:зробив:зробила} велику справу для народу тауренів.", ["en"] = "Winterhoof Cleansing", ["tasks"] = { ["Cleanse the Winterhoof Water Well"] = "Очистіть криницю Зимового Копита" } },
    [7541] = { [1] = "Служба Орді", [5] = "Нашим знавцям знадобиться час, щоб вивчити кулон, який ти нам {стать:приніс:принесла}. Але за твою службу Орді я хотів би запропонувати тобі невелику винагороду.\n\nДякую, {ім'я}. Твої вчинки приносять честь і тобі, і нам.", ["en"] = "Service to the Horde" },
    [755] = { [1] = "Обряди Матері-Землі", [2] = "Твоя готовність допомагати у повсякденних завданнях тауренів Нараче та завзятість до навчання - благородні риси, {Ім'я}. Я вірю, що одного дня тебе представлятимуть у Громовому Бескиді як {стать:величного:величну} {клас:з}.\n\nПроте до цього ти мусиш пройти Обряди Матері-Землі, яких всього три.\n\nПерша перевірка - це Обряд Сили. Йди до Провидця Сірого Язика і передай йому, що тебе прислав вождь Соколиний Вітер.\n\nТи знайдеш житло провидця на південь від табору Нараче, сховане серед пагорбів.", [3] = "Прямуйте до Провидця Сірого Язика, що живе серед пагорбів на південь від табору Нараче.", [5] = "Тебе прислав вождь Соколиний Вітер? Проходження Обрядів Матері-Землі - це не проста задача...", ["en"] = "Rites of the Earthmother" },
    [756] = { [1] = "Тотем Громового Рога", [2] = "Для створення очисного тотема Громового Рога, ти маєш зібрати пазурі хижаків, що живуть на рівнинах Мулґору. Вполюй ловців прерій і рівнинних пум задля їхніх пазурів і повертайся до мене.\n\nТи знайдеш цих хижаків на сході та на заході.", [3] = "Принесіть 6 пазурів ловця та 6 пазурів пуми Муллу Громовому Рогу.", [4] = "{Ім'я}, у тебе є пазурі, які я просив зібрати? З кожною годиною колодязь Громового Рогу забруднюється все більше!", [5] = "Дякую тобі, {Ім'я}. Непорочність, з якою ці тварини полюють, є надзвичайно важливою у створенні очисного тотема.\n\nГобліни ніколи не зрозуміють різницю між боротьбою із землею та життям у гармонії з нею.", ["en"] = "Thunderhorn Totem", ["tasks"] = { ["Cougar Claws"] = "пазурі пуми", ["Cougar Claws (Provided)"] = "пазурі пуми (видано)", ["Stalker Claws"] = "пазурі ловця", ["Stalker Claws (Provided)"] = "пазурі ловця (видано)" } },
    [757] = { [1] = "Обряд Сили", [2] = "Обряди Матері-Землі - це перші кроки, які {стать:повинен:повинна} пройти {стать:юний таурен:юна тауренка}, щоб заслужити повагу в Громовому Бескиді.\n\nСпершу ти маєш пройти Обряд Сили. У цьому випробуванні тобі потрібно довести свою сміливість, вбиваючи ворогів племені.\n\nЩетиношкури ущелини Лезожини на сході зазіхають на наші племінні землі. Вони роблять засідки на наші мисливські групи та грабують селище з приходом ночі.\n\nПокажи свою звитягу, убивши цих злодіїв, і повертайся до вождя у табір Нараче з їхніми поясами - доказами твоїх діянь.", [3] = "Убийте Щетиношкурів з ущелини Лезожини та принесіть 12 поясів Щетиношкурів вождю Соколиному Вітру в табір Нараче.", [4] = "Ти {стать:пройшов:пройшла} Обряд Сили, {Ім'я}? Мені потрібні докази твоєї звитяги проти ворога нашого племені, Щетиношкурів.", [5] = "Ти {стать:пройшов:пройшла} перше випробування з Обрядів Матері-Землі. Плем'я буде тобою пишатися.", ["en"] = "Rite of Strength", ["tasks"] = { ["Bristleback Belt"] = "пояс Щетиношкурих", ["Bristleback Belt (Provided)"] = "пояс Щетиношкурих (видано)" } },
    [759] = { [1] = "Тотем Дикої Гриви", [2] = "Залишилось очистити один колодязь, названий на честь клану Дикої Гриви. Щоб він став чистим, земля повинна надати зуби лютого хижака, степового альфа-вовка. Знайди альф на півночі та повертайся до мене, коли твоє полювання завершиться.\n\nАльфи часто блукають біля підніжжя нашого могутнього міста, Громового Бескида.", [3] = "Принесіть 8 зубів степового альфи Муллові Громовоому Рогу до селища Криваве Копито.", [4] = "{Ім'я}, у тебе є зуби, про які я просив?", [5] = "Дуже добре, {Ім'я}. Я відчуваю пожертву землі у цьому підношенні, і мій дух наповнюється сумом і гордістю.", ["en"] = "Wildmane Totem", ["tasks"] = { ["Prairie Alpha Tooth"] = "зуб степового альфи", ["Prairie Alpha Tooth (Provided)"] = "зуб степового альфи (видано)" } },
    [761] = { [1] = "Полювання на хапунів", [2] = "Хапун - хитра пташка, яку складно і знайти, і вполювати. Збірка пір'їн хапуна - це відзнака розуму та цілеспрямованості мисливця.\n\nЯкщо хочеш взятися за це завдання, йди на рівнини та вполюй хапунів.\n\nПринесі мені їхні пір'їни, і цим принеси честь своєму кланові.\n\nХапунів можна знайти будь-де у Мулґорі, але твій зір має бути гострим, а копита - швидкими, щоб помітити їх та наздогнати.", [3] = "Принесіть 8 трофейних пір'їн хапуна Гаркену Тотему Вітру у селище Криваве Копито.", [4] = "Ти {стать:знайшов:знайшла} хапунів, {Ім'я}? Їхні пір'їни у тебе?", [5] = "Я знаю, що збір цих пір'їн був непростим завданням, {Ім'я}. Виконавши його, ти {стать:довів:довела}, що ти - {стать:достойний:достойна} {клас:н}. Добре, що ти {стать:завітав:завітала} до Кривавого Копита.", ["en"] = "Swoop Hunting", ["tasks"] = { ["Trophy Swoop Quill"] = "трофейна пір'їна хапуна", ["Trophy Swoop Quill (Provided)"] = "трофейна пір'їна хапуна (видано)" } },
    [76156] = { [1] = "Стежте з Матір'ю-Землею", [2] = "Шамане, я відчуваю в тобі прихований талант до тонких мистецтв. Використай цю маску, щоб проникнути на сусідню шахту ТзНБ \"Авантюра\" та вкрасти їхні припаси. Це може здатися непереконливою маскуванням, але вправний розбійник може прослизнути повз будь-якого охоронця лише за допомогою привабливої посмішки та хитрої відволікаючої манери. Я вірю, що ця здатність є і в тобі.", [3] = "Прокрадіться до шахти ТзНБ \"Авантюра\" на південний схід від Громового Бескиду та зберіть з возів із вибухівкою 5 сифорієвих зарядів, а потім поверніться до Боартона Тінетотема в Громовий Бескид.", [4] = "Нам потрібно попрацювати над твоїми навичками скритності, {клас}. Я почув, як ти наближаєшся, щойно ти ступив на месу.", [5] = "Хм... можливо, маскування — не твоя сильна сторона.", ["en"] = "Stalk With The Earthmother", ["tasks"] = { ["Seaforium Mining Charge"] = "Плата за видобуток Seaforium", ["Venture Co Disguise"] = "Маскування Venture Co", ["Venture Co Disguise (Provided)"] = "Маскування Venture Co (видано)" } },
    [76160] = { [1] = "Стежте з Матір'ю-Землею", [2] = "Я звертаюся до тебе з твого майбутнього, коли Орда зіткнеться з загрозами, які ти не можеш собі уявити. Оскільки інші не можуть мене бачити, я покладаюся на тебе, щоб ти вивчив мої навички та передав їх племені.\n\nМожливо, твої навички полягають в отрутах, а не в маскуванні. Гарпії на півночі гніздяться на дереві, яке виробляє сильнодіючу смолу. Збери опалі шишки навколо гнізд, а потім розчави їх, щоб зробити мазь. Нанесена на лезо, ця мазь випалить рани твого супротивника в його плоть і перетворить його кров на сіль.", [3] = "Зберіть 8 Конусів Лютості Вітру на північ від Громового Бескиду, використовуйте їх зі Ступкою та Маточком, потім поверніться до Тотема Тіні Боартона в Громовому Бескиді з результатом.\n\nНаданий предмет:", [4] = "Будьте обережні з маззю після завершення, {клас}. Навіть контакт зі шкірою може бути досить болючим.", [5] = "{клас}, це не та отруйна мазь, яку я просив. Ти приніс мені кедрову пасту. Ти впевнений, що виконав мої інструкції?\n\nНамастити її на пряний хліб буде набагато корисніше, ніж на кинджал. Хоча ти був би досить потужним проти ворога з алергією на горіхи.", ["en"] = "Stalk With The Earthmother", ["tasks"] = { ["Pine Salve"] = "Соснова мазь", ["Windfury Cone"] = "Конус люті вітру" } },
    [76240] = { [1] = "Стежте з Матір'ю-Землею", [2] = "У мене є ще одна ідея, яка може привести нас до успіху. Я все ще відчуваю, що у вас є прихований талант, але давайте спробуємо розкрити його менш прямим підходом.\n\nІдіть і роздобудьте сиру блискучу дрібну рибку, а потім принесіть її сюди. Використайте ці кинджали, щоб почистити та нарізати її філе. Не думайте надто багато — робіть те, що дає вам природа.", [3] = "Купіть або зловіть сиру блискучу рибку, а потім скористайтеся набором ножів, щоб нарізати її філе перед тотемом тіні Боартона в Громовому Бескиді.\n\nНаданий предмет:", [4] = "У тебе є щось для мене?", [5] = "Це був справжній виступ, {клас}. Не та шахрайська точність, на яку я сподівався, але ти володієш вражаючою амбідекстрією.\n\nТепер я бачу, що ти не будеш тим, хто навчатиме мій народ тонким мистецтвам, але є одна річ, якій я можу тебе навчити. Удачі тобі в подорожах, {клас}. Орді знадобляться такі герої, як ти.", ["en"] = "Stalk With The Earthmother", ["tasks"] = { ["Fish Chunks"] = "Шматочки риби" } },
    [763] = { [1] = "Обряди Матері-Землі", [2] = "Для продовження Обрядів Матері-Землі ти {стать:повинен:повинна} пройти ще два випробування. Настав час прокласти власний шлях, {ім'я:к}.\n\nПрямуй до селища Криваве Копито та розшукай вождя, Бейна Криваве Копито, сина Керна. Звідти ти зможеш продовжити свою подорож та здобути визнання старійшин Громового Бескиду.\n\nПринеси цей тотем Бейнові. Він упізнає мою різьбу та допоможе тобі у твоїх мандрах.\n\nЙди дорогою з табору Нараче та поспішай. Не сходь зі свого шляху, щоб не заблукати.", [3] = "Принесіть тотем Соколиного Вітру Бейнові Кривавому Копиту в селище Криваве Копито. Прямуйте дорогою з табору Нараче.", [4] = "Що привело тебе у моє селище, {клас:к}?", [5] = "Звістка від мого хорошого друга, вождя Соколиного Вітру! Ах, по різьбі я бачу, що ти особливої породи.", ["en"] = "Rites of the Earthmother", ["tasks"] = { ["Totem of Hawkwind"] = "тотем Соколиного Вітру", ["Totem of Hawkwind (Provided)"] = "тотем Соколиного Вітру (видано)" } },
    [764] = { [1] = "ТзНБ \"Авантюра\"", [2] = "Це пояснює зосередження робітників й устаткування ТзНБ \"Авантюра\" у Мулґорі. Ці гобліни… їхня компанія розширюється занадто швидко, на шкоду їм самим. Як кажуть, покажи щось гоблінові, й одразу почуєш звук його терез.\n\nМаленькі жадюги. На жаль для їхньої справи, ми, таурени, не можемо дозволити їм проводити свої операції на наших землях. Йди до їхньої шахти на північний схід від розореного каравану та надішли їм повідомлення.", [3] = "Убийте 14 робітників ТзНБ \"Авантюра\" і 6 наглядачів ТзНБ \"Авантюра\" для Моріна Ловця Хмар у селищі Криваве Копито.", [4] = "ТзНБ \"Авантюра\" було відмовлено у правах на видобування тут у Мулґорі, але, схоже, що вони не сприймають \"ні\" за відповідь. Ми, таурени, не з тих, хто розкидується словами, але у нас є інші способи донести свою позицію.", [5] = "Не думаю, що наш сигнал можна сприйняти надто неоднозначно, гм? ТзНБ \"Авантюра\" знатиме, що не варто сприймати тауренів несерйозно або бути настільки нахабними та вважати, що ми мовчки дозволимо їм красти природні ресурси навколо нас.", ["en"] = "The Venture Co.", ["tasks"] = { ["Venture Co. Supervisor"] = "керівник ТзНБ \"Авантюра\"", ["Venture Co. Supervisor slain"] = "керівник ТзНБ \"Авантюра\": убито", ["Venture Co. Worker"] = "робітник ТзНБ \"Авантюра\"", ["Venture Co. Worker slain"] = "робітник ТзНБ \"Авантюра\": убито" } },
    [765] = { [1] = "Наглядач Шуморакета", [2] = "Згідно з паперами, які ти {стать:знайшов:знайшла} у каравані, ТзНБ \"Авантюра\" склало багато планів, щоб спробувати вигнати нас з наших земель. Так вони зможуть безперешкодно грабувати наші землі.\n\nМені гидкі й обурливі глибини ницості, у які вони готові впасти заради досягнення своїх цілей. Я хочу, щоб натхненник їхніх планів був убитий. Його ім'я — наглядач Шуморакета, ти знайдеш його у шахті ТзНБ на схід від розореного каравану. Принеси мені його записник, подивимося, чи там знайдеться щось корисне.", [3] = "Убийте наглядача Шуморакету та принесіть його записник Моріну Ловцю Хмар у селище Криваве Копито.", [4] = "Мене збурює гнів від думки про звірства, які готове застосувати проти нас ТзНБ \"Авантюра\" заради прибутку.", [5] = "Мій гнів дещо стих від новини про смерть злодія Шуморакети. Я пройдуся по його особистих записах і подивлюся, чи немає там якої-небудь додаткової інформації про плани ТзНБ на майбутнє. Дякую за твої зусилля, {Ім'я}.", ["en"] = "Supervisor Fizsprocket", ["tasks"] = { ["Fizsprocket's Clipboard"] = "записник Шуморакети", ["Fizsprocket's Clipboard (Provided)"] = "записник Шуморакети (видано)" } },
    [766] = { [1] = "Маззраначе", [2] = "Мій дід оповідав мені історії про битви із рівнинним бігуном на ім'я Маззраначе. Він описував його демонічні червоні очі, гострі, як бритва, кігті й отруйний укус.\n\nТак вже сталося, що я зустрів його під час мандрівок рівнинами й він сильно вкусив мене за плече. Він виявився рівно таким жахливим, як його й описував мій дід. Щоб очистити цю рану від інфекції, мені знадобляться деякі рідкісні частини тварин: серце вовка, стегнова кістка пуми, луска рівнинобіга та шлунок хапуна.\n\nПоспішай, часу обмаль.", [3] = "Принесіть серце степового вовка, стегнову кістку рівнинної пуми, луску рівнинобіга та шлунок хапуна Маурові Накликачу Дощу в Кривавому Копиті.", [4] = "Мій жар зростає, і я відчуваю, як мої думки поринають у лихоманливі жахіття… Мені слід було знати, що я не зможу самостійно упоратися зі звіром, якого не зміг перемогти мій дід…\n\nУ тебе є складники для протиотрути? Боюсь, якщо я скоро не прочищу рану, вона й стане моєю смертю.", [5] = "Ах, дякую тобі, {ім'я:к}. З тим, що ти мені {стать:приніс:принесла}, я зможу зробити протиотруту, щоб зупинити розповсюдження інфекції та з часом повністю вилікуватися від неї. Я зобов'язаний тобі своїм життям.\n\nАле я ніколи не забуду той різкий крик, з яким Маззраначе наблизився до мене, і яскравий спалах, коли він ударив своїм дзьобом…\n\nБережи себе у своїх мандрах.", ["en"] = "Mazzranache", ["tasks"] = { ["Flatland Cougar Femur"] = "стегнова кістка рівнинної пуми", ["Flatland Cougar Femur (Provided)"] = "стегнова кістка рівнинної пуми (видано)", ["Plainstrider Scale"] = "луска рівнинобіга", ["Plainstrider Scale (Provided)"] = "луска рівнинобіга (видано)", ["Prairie Wolf Heart"] = "серце степового вовка", ["Prairie Wolf Heart (Provided)"] = "серце степового вовка (видано)", ["Swoop Gizzard"] = "шлунок хапуна", ["Swoop Gizzard (Provided)"] = "шлунок хапуна (видано)" } },
    [767] = { [1] = "Обряд Прозріння", [2] = "Обряд Прозріння, один із Обрядів Матері-Землі, допоможе тобі на шляху до визнання серед старійшин Громового Бескиду.\n\nНаш народ навчився, що земля є нашим найсвятішим джерелом. Щоб узяти участь у ритуальному видінні, ти {стать:повинен:повинна} поговорити із духовним лідером нашого селища, Зарлманом Два-Місяці.", [3] = "Поговоріть із Зарлманом Два-Місяці у селищі Криваве Копито.", [5] = "Я відчував, що ти прийдеш до мене, {клас:к}. Я завжди впізнаю тих, хто прагне пройти Обряди Матері-Землі.", ["en"] = "Rite of Vision" },
    [768] = { [1] = "Збір шкіри", [2] = "Вітаю, {стать:юначе:юначко}. Я бачу блиск в твоїх очах. Схоже, що тобі не терпиться повернутися на рівнину для полювання. Нехай прибуде з тобою честь для твого клану!\n\nЯ працюю зі шкірами тварин — роблю з них одяг та обладунки для мешканців Громового Бескиду.\n\nЯкщо ти принесеш мені шкіри звірів, я зроблю щось і для тебе.", [3] = "Зберіть 12 легких шкір Верену Високоступу в Громовий Бескид.", [4] = "І знову привіт. Вже {стать:був:була} на полюванні? Є шкіра для мене?", [5] = "Ах, яка гарна шкіра. З неї вийдуть гарні вироби.\n\nТримай, {ім'я}. Візьми це на знак подяки...", ["en"] = "Gathering Leather", ["tasks"] = { ["Light Leather"] = "легка шкіра", ["Light Leather (Provided)"] = "легка шкіра (видано)" } },
    [769] = { [1] = "Сумка зі шкіри кодо", [2] = "Кодо Мулґору — звірі сильні та витривалі, а ми такі риси поважаємо. Якщо ти вмієш працювати зі шкірою і хочеш навчитися робити сумки зі шкіри кодо — принеси мені необхідні матеріали.\n\nЗробиш це — і я поділюся з тобою своїми знаннями.", [3] = "Принесіть 4 легкі шкіри та 4 мотки грубої нитки Верену Високоступу в Громовий Бескид.", [4] = "Ти {стать:дістав:дістала} матеріали, {ім'я}?", [5] = "Ах, дуже добре. Дякую, {ім'я}. Моє серце розпирає від гордості, коли я бачу молодь, яка цікавиться шкірництвом.", ["en"] = "Kodo Hide Bag", ["tasks"] = { ["Coarse Thread"] = "груба нитка", ["Coarse Thread (Provided)"] = "груба нитка (видано)", ["Light Leather"] = "легка шкіра", ["Light Leather (Provided)"] = "легка шкіра (видано)" } },
    [77] = { [1] = "Слизька справа", [2] = "У мене є тара для шипучки, про яку казав Дран Дрофферс. Я допоможу тобі розлити шипучку для батька Мальтона... за винагороду у вигляді двох пляшок шипучки для мене. Вони знаходяться в ящиках навколо покинутої бази Орди біля Замаскованої печери.\n\nЦе буде непросто — руїни кишать брудними слизнями. Ходять чутки, що у них є ватажок, такий собі верховний слимак. Але іншого шляху немає — збери шипучку і повертайся до мене.", [3] = "Знайдіть 10 пляшок медової шипучки Внутрішніх земель у ящиках, розкиданих навколо покинутої бази Орди біля Замаскованої печери.", [4] = "Я так розумію, ти {стать:повернувся:повернулась}, бо вже {стать:зібрав:зібрала} вдосталь пляшок з шипучкою, так?", [5] = "Чудова робота, {ім'я}. Я радий, що ти не {стать:зіпсував:зіпсувала} шипучку. Немає нічого гіршого, ніж збовтана шипучка.\n\nЗачекай хвилинку, магії потрібен час, щоб подіяти на цей цінний вантаж. Насправді ніякої магії тут немає — я лише переллю все в нові пляшки з-під \"медової шипучки Внутрішніх земель\". Це перетворить ці звичайні пляшки на неоціненний алкогольний скарб.\n\nНу ось і готово!", ["en"] = "A Sticky Situation", ["tasks"] = { ["Hinterlands Honey Ripple"] = "медова шипучка Внутрішніх земель", ["Hinterlands Honey Ripple (Provided)"] = "медова шипучка Внутрішніх земель (видано)" } },
    [770] = { [1] = "Пошматований демонами плащ", [2] = "Поношена шкура Примарного Вия досі має жахливу рану, отриману вовком у битвах проти Палаючого Легіону.\n\nМожливо, комусь у селищі Криваве Копито варто знати про смерть Примарного Вия…", [3] = "Знайдіть когось, хто знає про Примарного Вия.", [5] = "Я ледве можу повірити моїм старим очам! Ти {стать:переміг:перемогла} великого вовка Примарного Вия? Тепер я по-новому дивлюся на тебе, з повагою, {стать:юний:юна} {клас:к}. Ти - {стать:ловець:ловчиня} неймовірних умінь!\n\nДозволь мені дещо запропонувати тобі. Мої дні мисливства минули, але для мене буде честю, якщо ти використовуватимеш одну з моїх зброй у своїх полюваннях.\n\nХай вона вражає напевно та принесе тобі визнання.\n\nІ будемо сподіватися, що дух Примарного Вия нарешті знайшов спокій.", ["en"] = "The Demon Scarred Cloak", ["tasks"] = { ["Demon Scarred Cloak"] = "пошматований демонами плащ" } },
    [771] = { [1] = "Обряд Прозріння", [2] = "Щоб пройти Обряд Прозріння, ти {стать:повинен:повинна} зібрати реагенти, необхідні для створення Води Провидців.\n\nМені будуть потрібні камені, які можна знайти біля колодязів у Мулґорі. Я поєднаю їх з бурштиновими насінинами, які падають з могутніх дерев нашої землі.\n\nЦі реагенти містять магічні елементи, і якщо їх приготувати та застосувати перед племінним багаттям, вони дозволять тобі бачити видіння. Йди за ним, і воно приведе тебе до наступного кроку цього священного завдання.", [3] = "Зберіть 2 колодязних камені та 2 бурштинових насінини, та принесіть їх Зарлманові Два-Місяці у селищі Криваве Копито.", [4] = "Як тільки ти збереш достатньо каменів навколо колодязя і бурштинових насінин під деревами, я приготую для тебе Воду Провидців.", [5] = "Я бачу, ти {стать:навчився:навчилася} збору з наших священних земель, {Ім'я}. Мені треба всього лише хвилинка, щоб приготувати Воду Провидців.", ["en"] = "Rite of Vision", ["tasks"] = { ["Ambercorn"] = "бурштинова насінина", ["Ambercorn (Provided)"] = "бурштинова насінина (видано)", ["Well Stone"] = "колодязний камінь", ["Well Stone (Provided)"] = "колодязний камінь (видано)" } },
    [772] = { [1] = "Обряд Прозріння", [2] = "Я дарую тобі воду Провидців.\n\nКоли будеш {стать:готовим:готова}, випий воду біля племінного вогнища. Видіння з'явиться перед вогнем за кілька митей після того, як ти ковтнеш священної води.\n\nЗ цього моменту лише ти можеш йти за ним до своєї долі…", [3] = "Випийте воду Провидців навпроти племінного багаття у селищі Криваве Копито та слідуйте за видінням, яке вам явиться.", [5] = "Не бійся, {Ім'я}. Ти успішно {стать:пройшов:пройшла} Обряд Видіння.", ["en"] = "Rite of Vision", ["tasks"] = { ["Water of the Seers"] = "вода провидців" } },
    [773] = { [1] = "Обряд Мудрості", [2] = "Щоб заслужити прийняття у старійшин Громового Бескиду, наступним ти {стать:повинен:повинна} пройти Обряд Мудрості.\n\nОскільки ти {стать:пройшов:пройшла} Обряд Видіння, духи предків Червоних скель дадуть тобі благословення наших пращурів. Лише ті, хто випив воду Провидців, можуть отримати їхній дар.\n\nЙди на схід від Громового Бескиду, до Червоних скель, і знайди там Дух Предків, {Ім'я}.", [3] = "Прямуйте до Червоних скель на схід від Громового Бескиду та поговоріть з духом Предків.", [5] = "Ти {стать:проявив:проявила} велику старанність у своєму прагненні пройти Обряди Матері-Землі, {Ім'я}.\n\nМи, духи предків, утілюємо могутніх тауренів, які хоробро віддали свої життя задля заснування та захисту нашого великого міста - Громового Бескиду. Тепер я покладаю цей обов'язок захисту на тебе.\n\nТи {стать:пройшов:пройшла} Обряд Мудрості, {стать:юний:юна} {клас:к}. Приходь у Громовий Бескид із гордістю.", ["en"] = "Rite of Wisdom" },
    [7730] = { [1] = "Нашестя Зукк'аш", [2] = "Судячи з інформації, отриманої розвідкою, вороги, що тіснять гнолів з півдня — це раса комахоподібних істот. Невідомо, чи вони розумні — але, відверто кажучи, це й неважливо. Якщо гноли їх так бояться, що вважають за краще нападати на нас, значить, ці тварюки не менш небезпечні за гнолів.\n\nВирушай в місце, де живуть ці комахи Зукк'аш, відоме як Судомна глибочінь. Скороти їх чисельність та повертайтеся до мене з доказами своєї роботи — їхніми панцирами.", [3] = "Принесіть 20 панцирів Зукк'аш Гадокену Жвавобігу в табір Мохаче, що в Фераласі.", [4] = "Як проходить полювання, {ім'я}? Ти тут, щоб повідомити про свій успіх?", [5] = "Молодець, {клас:к}. Хоча Зукк'аш не вдасться зупинити нічим іншим, окрім повномасштабного вторгнення, ти {стать:виграв:виграла} нам трохи часу, щоб ми змогли розробити правильну стратегію.\n\nЯ велю дослідити ці панцири — ми маємо дізнатися про цих тварюк якомога більше, перш ніж мати справу з такою масштабною загрозою.", ["en"] = "Zukk'ash Infestation", ["tasks"] = { ["Zukk'ash Carapace"] = "панцир Зукк'аш", ["Zukk'ash Carapace (Provided)"] = "панцир Зукк'аш (видано)" } },
    [7731] = { [1] = "Жалохвіст", [2] = "Один з наших розвідників повідомив, що побачив велику комахоподібну істоту, що блукає по Судомній глибочіні. Вона не лише більша за інших комах, які там зустрічаються, але також виділяє якусь ауру, якої інші комахи не мають. Ми назвали цю істоту — Жалохвіст.\n\nВнутрішності цієї тварини будуть надзвичайно корисні нам, щоб зрозуміти, як краще боротися з цією новою загрозою. Виріж його залозу та принеси її мені!", [3] = "Вбийте Жалохвіста в Судомній глибочіні, і принесіть його залозу Гадокену Жвавобігу в табір Мохаче, що в Фераласі.", [4] = "Ти вже {стать:розібрався:розібралася} с Жалохвостом?", [5] = "Вражає, {клас:к}... дуже вражає! Якщо Жалохвіст дійсно один з найсильніших цих звірів, його вивчення виявиться цінним у майбутньому. Тепер я маю подбати, щоб ми вистояли досить довго, щоб зуміти скористатися здобутими знаннями!\n\nБудь ласка, {ім'я}, прийми ці гроші на знак подяки від усього табору. Гарна робота.", ["en"] = "Stinglasher", ["tasks"] = { ["Stinglasher's Glands"] = "залоза Жалохвоста", ["Stinglasher's Glands (Provided)"] = "залоза Жалохвоста (видано)" } },
    [7732] = { [1] = "Звіт про Зукк'аш", [2] = "Ти добре {стать:впорався:впоралася} з захистом табору Мохаче від комах Зукк'аш. Але загроза від цих істот не минула, і я хотів би попросити тебе про ще одне завдання для Орди.\n\nЦі папери містить всю інформацію, яку ми зібрали про комах Зукк'аш. Я хочу, щоб ти {стать:відніс:віднесла} їх Зілзібіну Ударнику в Тракт, що в Орґріммарі. Він фахівець з незвичайних істот, як ці, і я сподіваюся, що здобуті нами знання йому знадобляться.", [3] = "Передайте звіт про Зукк'аш Зілзібіну Ударнику. Він мешкає в Тракті, що в Орґріммарі.", [4] = "Привіт, {стать:друже:подруго}... Бачу, в тебе якась термінова справа. Чим я можу тобі допомогти?", [5] = "Так, я цього очікував. Ці істоти, з якими ти {стать:зіткнувся:зіткнулася}... це давня загроза, яку Орда продовжує ігнорувати. Гадокен вчинив мудро, пославши мені звіт і тебе.\n\nЗукк'аш — це ті самі істоти, які називаються силітидами. Багатьом здається, ніби це просто безтямні тварюки, але дозволь тебе запевнити: вони значно, значно небезпечніші за будь-яку загрозу з боку Альянсу!\n\nІ мені б дуже знадобилася твоя допомога в тому, щоб привернути увагу до цієї загрози.", ["en"] = "Zukk'ash Report", ["tasks"] = { ["Camp Mojache Zukk'ash Report"] = "звіт про комах Зукк'аш з табору Мохаче", ["Camp Mojache Zukk'ash Report (Provided)"] = "звіт про комах Зукк'аш з табору Мохаче (видано)" } },
    [7734] = { [1] = "Найвища якість", [2] = "Я знаю, де можна добути ще КРАЩІ шкури, хоча в це й важко повірити! В північній частині Фераласа — глибоко в печері Лютошрамих — живе ще одна зграя єті. Вони міцніші за тих, з якими ти {стать:бився:билася} раніше, тому якщо ти {стать:готовий:готова} до виклику, тебе це має зацікавити!\n\nЯ щедро винагороджу тебе за десять шкур цих єті. Просто принеси мені їх.", [3] = "Принесіть 10 шкур лютошрамних єті Джанґдору Стрімкому Вершнику в табір Мохаче, що в Фераласі.", [4] = "Якщо ці шкури не поступаються шкурам лихошрамних єті, вони цілком можуть бути не менш міцними за торій!\n\nТільки уяви!", [5] = "Чудово, чудово! Вони вийдуть неймовірними — я вже бачу, що після належної обробки вони стануть набагато міцнішими.\n\nЩе раз дякую за допомогу, {ім'я}. Ось — будь ласка, візьми один з моїх останніх виробів.", ["en"] = "Improved Quality", ["tasks"] = { ["Rage Scar Yeti Hide"] = "шкура лютошрамного єті", ["Rage Scar Yeti Hide (Provided)"] = "шкура лютошрамного єті (видано)" } },
    [7738] = { [1] = "Ідеальна шкура єті", [2] = "Ви знайшли ідеальну шкуру єті, надзвичайно товсту та міцну — навіть міцнішу за шкури лютошрамних єті.\n\nВраховуючи, що Джанґдор Стрімкий Вершник з табору Мохаче цікавиться шкурами єті, цю знахідку варто показати йому.", [3] = "Принесіть ідеальну шкуру єті Джанґдору Стрімкому Вершнику в табір Мохаче.", [4] = "Що це, {ім'я} — у тебе є щось особливе для мене?", [5] = "Це неймовірна знахідка! Я вважаю, що це найкращий зразок шкури єті, який я коли-небудь бачив!\n\nДійсно, це заслуговує на відповідну винагороду. Зазвичай я не плачу стільки за одну шкуру, але я впевнений, що зможу зробити з неї щось особливе. Дякую, що {стать:згадав:згадала} про мене, {ім'я}!", ["en"] = "Perfect Yeti Hide", ["tasks"] = { ["Perfect Yeti Hide"] = "ідеальна шкура єті", ["Perfect Yeti Hide (Provided)"] = "ідеальна шкура єті (видано)" } },
    [775] = { [1] = "Подорож до Громового Бескиду", [2] = "Відтепер тебе шануватимуть у стінах нашого великого міста. Пройшовши Обряди Матері-Землі, ти заслужиш на таку честь.\n\nВиконай останнє завдання, відшукай благородного вождя Керна Криваве Копито, що проживає на вершині найвищого плато Громового Бескиду.", [3] = "Поговоріть з Керном Кривавим Копитом у Громовому Бескиді.", [5] = "Вітаю, {стать:молодий:молода} {клас:к}. Бачу ти {стать:знайшов:знайшла} шлях до моїх дверей.", ["en"] = "Journey into Thunder Bluff" },
    [77582] = { [1] = "Випробування фізичної форми", [2] = "Понад усе, воїн Орди повинен мати міцну статуру. У своїй подорожі ти пройдеш багато випробувань на витривалість та стійкість.\n\nДля цього я заховав схованку серед скель позаду себе. Ти можеш побачити її, якщо стоятимеш біля багаття в центрі села. Дістатися до неї буде нелегко. У схованці є руна великої сили.\n\nТвоє випробування — знайти цю руну та повернутися, коли дізнаєшся її таємниці.", [3] = "Знайдіть Прихований Тайник у скелях за Франгом. Вивчіть руну всередині, а потім доповідайте Франгу в Долині Випробувань.", [4] = "Ви знайшли руну {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "A Trial of Fitness" },
    [77583] = { [1] = "На вершині скель", [2] = "Я підготував для тебе тренувальну вправу, {ім'я}. Я заховав схованку серед скель неподалік. Ти можеш її побачити, якщо стоятимеш біля багаття в центрі села. У схованці знаходиться руна великої сили.\n\nТвоє випробування — отримати цю руну та повернутися, коли дізнаєшся її секрети.", [3] = "Знайдіть Прихований Сховище у скелях, що оточують Долину Випробувань. Вивчіть руну всередині, а потім доповідайте Рвагу в Лігві.", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Atop the Cliffs" },
    [77584] = { [1] = "Полювання за руною", [2] = "Мисливець черпає силу зі зв'язку зі світом природи. Під час своєї подорожі ви будете вистежувати здобич крізь усіляку сувору місцевість, виживаючи лише завдяки своїй кмітливості.\n\nНещодавно інший мисливець-початківець, на жаль, зазнав невдачі. Він вирушив полювати на скорпідів і так і не повернувся. Він експериментував з гравіюванням містичних рун на своєму спорядженні, щоб покращити свою бойову майстерність.\n\nЗнайдіть його руну серед скорпідів поблизу та поверніться, коли дізнаєтеся її секрети.", [3] = "Знайдіть загублену руну, вбивши скорпідів у Долині Випробувань. Вивчіть силу руни, а потім доповідайте Джен'сан.", [4] = "Ви знайшли руну {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Hunt for the Rune" },
    [77585] = { [1] = "Ікони влади", [2] = "Шаманізм — це давня практика, {ім'я}. По всьому Азероту можна знайти багато артефактів, сповнених духовної енергії. Нещодавно я сам виявив ікону надзвичайної сили, але її вкрали ці надокучливі скорпіди.\n\nОдин із них, ймовірно, носить її з собою, вважаючи її блискучою рідкістю для прикраси свого гнізда.\n\nКоли знайдеш ікону, дізнайся про її силу та повернися до мене.", [3] = "Знайдіть викрадену ікону, вбивши скорпідів у Долині Випробувань. Дізнайтеся її силу, а потім доповідайте Шикрику.", [4] = "Ви знайшли значок {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Icons of Power", ["tasks"] = { ["Learn: Engrave Chest - Overload"] = "Дізнайтеся: Гравірування скрині - Перевантаження" } },
    [77586] = { [1] = "Вкрадена влада", [2] = "Я експериментував з новим типом магії — руною, яка може направляти енергію скверни для підживлення потужних заклинань. Я б поділився цією силою з тобою, але її вкрав один із цих надокучливих фамільярів Палаючого Клинка.\n\nІди до їхнього ковену, на північ, і подивися, чи зможеш знайти мою руну, заховану серед їхніх речей. За моїм досвідом, фамільяри схильні ховати свою здобич у важкодоступних місцях.\n\nЯк тільки знайдеш руну, вивчи її магію та доповідай мені. Я хотів би, щоб мій експеримент був представлений нам.", [3] = "Знайдіть викрадену руну всередині Ковену Палаючого Клинка. Дізнайтеся її силу, а потім поверніться до Нартока в Лігво.", [4] = "Ви знайшли руну {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Stolen Power" },
    [77587] = { [1] = "Ікони влади", [2] = "Шаманізм — це давня практика, {ім'я}. По всьому Азероту можна знайти багато артефактів, сповнених духовної енергії. Нещодавно я сам виявив ікону надзвичайної сили, але її вкрали ці надокучливі скорпіди.\n\nОдин із них, ймовірно, носить її з собою, вважаючи її блискучою рідкістю для прикраси свого гнізда.\n\nКоли знайдеш ікону, дізнайся про її силу та повернися до мене.", [3] = "Знайдіть викрадену ікону, вбивши скорпідів у Долині Випробувань. Дізнайтеся її силу, а потім доповідайте Шикрику.", [4] = "Ви знайшли значок {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Icons of Power" },
    [77588] = { [1] = "Випробування фізичної форми", [2] = "Понад усе, воїн Орди повинен мати міцну статуру. У своїй подорожі ти пройдеш багато випробувань на витривалість та стійкість.\n\nДля цього я заховав схованку серед скель позаду себе. Ти можеш побачити її, якщо стоятимеш біля багаття в центрі села. Дістатися до неї буде нелегко. У схованці є руна великої сили.\n\nТвоє випробування — знайти цю руну та повернутися, коли дізнаєшся її таємниці.", [3] = "Знайдіть Прихований Тайник у скелях за Франгом. Вивчіть руну всередині, а потім доповідайте Франгу в Долині Випробувань.", [4] = "Ви знайшли руну {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "A Trial of Fitness" },
    [77590] = { [1] = "Пересічена місцевість", [2] = "Мисливець черпає силу зі зв'язку зі світом природи. Під час своєї подорожі ви будете вистежувати здобич крізь усіляку сувору місцевість, виживаючи лише завдяки своїй кмітливості.\n\nНещодавно інший мисливець-початківець, на жаль, зазнав невдачі. Він вирушив полювати на скорпідів і так і не повернувся. Він експериментував з гравіюванням містичних рун на своєму спорядженні, щоб покращити свою бойову майстерність.\n\nЗнайдіть його руну серед скорпідів поблизу та поверніться, коли дізнаєтеся її секрети.", [3] = "Знайдіть загублену руну, вбивши скорпідів у Долині Випробувань. Вивчіть силу руни, а потім доповідайте Джен'сан.", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Rugged Terrain" },
    [77592] = { [1] = "На вершині скель", [2] = "Я підготував для тебе тренувальну вправу, {ім'я}. Я заховав схованку серед скель неподалік. Ти можеш її побачити, якщо стоятимеш біля багаття в центрі села. У схованці знаходиться руна великої сили.\n\nТвоє випробування — отримати цю руну та повернутися, коли дізнаєшся її секрети.", [3] = "Знайдіть Прихований Сховище у скелях, що оточують Долину Випробувань. Вивчіть руну всередині, а потім доповідайте Рвагу в Лігві.", [4] = "Ви знайшли руну {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Atop the Cliffs" },
    [77642] = { [1] = "Мудрість Лоа", [2] = "Приєднання до Орди дало нашому народу безпечний дім, {ім'я}, але ми повинні пам'ятати, що саме Лоа завжди пильнують нас.\n\nА тепер очисти свій розум, і я поділюся з тобою давнім спогадом. Іди до Вівтаря Лоа в селі Сен'джін і стань перед ним на коліна, щоб поспілкуватися з великим духом Лоа. Як тільки ти отримаєш мудрість Лоа, ти зрозумієш пам'ять, яку я тобі дав. Завдяки цьому розумінню ти відкриєш нову силу.\n\nПовернися до мене, як тільки зробиш це.", [3] = "Станьте на коліна біля вівтаря Лоа в селі Сен'джін. Поспілкуйтеся з духом Лоа, потім скористайтеся спогадом, щоб вивчити нову здатність. Після цього поверніться до Кен'джая в Долині Стежок.\n\nНаданий предмет:", [4] = "Чого тебе навчили Лоа, {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nЛоа подарують вам багато спогадів під час вашої подорожі. Ви можете молитися біля вівтарів Лоа по всьому Азероту, щоб очистити свої думки та інтерпретувати їх, як ви щойно зробили.\n\nРозуміння складніших видінь може вимагати допомоги інших жерців в Орді. Не бійтеся вчитися у їхньої віри, {ім'я}. Мудрість Лоа можна знайти в усьому.", ["en"] = "Wisdom of the Loa", ["tasks"] = { ["Memory of a Troubled Acolyte"] = "Пам'ять проблемного аколіта" } },
    [77643] = { [1] = "Дослідження правопису", [2] = "Як маг, дослідження арканів приведе вас до вражаючої сили. Вивчення записів, залишених найвидатнішими магами Азероту, – чудовий початок. Нещодавно я сам деякі знайшов, але їх вкрали ці надокучливі фаміліари з Палаючих Клинків.\n\nЗнайдіть записки заклинань з ковену на півночі та скористайтеся цим посібником, щоб розшифрувати їх. Поверніться, коли ваше дослідження буде успішним.", [3] = "Знайдіть викрадені нотатки заклинань у ковені Палаючих Клинків, а потім використовуйте їх, щоб вивчити нову здібність. Після цього поверніться до Май'аха в Долині Стежок.", [4] = "Як просуваються ваші дослідження, {ім'я}?", [5] = "Молодець, {ім'я}. Візьми ці Чари Розуміння. Вони допоможуть тобі розшифрувати будь-які інші таємні письмена, які ти знайдеш.\n\nПродовжуй шукати нотатки із заклинаннями по всьому Азероту та використовуй їх для подальшого дослідження. Якщо тобі потрібно більше чарів, відвідай продавця реагентів.", ["en"] = "Spell Research", ["tasks"] = { ["Comprehension Primer"] = "Посібник з розуміння", ["Comprehension Primer (Provided)"] = "Посібник з розуміння (видано)", ["Learn: Engrave Gloves - Ice Lance"] = "Дізнайтеся: Гравірування рукавичок - Крижане спис" } },
    [77648] = { [1] = "Реліквії Тауренів", [2] = "Таурени — стародавній народ, {ім'я}, і наші втрачені реліквії можна знайти по всьому Азероту. Через них духи можуть навчити вас способам зміцнити ваш зв'язок зі Сном.\n\nЩетинохребий вепр вкрав у нас одну таку реліквію. Ймовірно, вони сховали її в Ярузі Ожини. Поверніть реліквію та дотримуйтесь її вказівок, щоб вивчити нову бойову техніку. Поверніться до мене, коли зробите це.", [3] = "Поверніть викрадену реліквію з Яру Ожининого Клинка. Дотримуйтесь вказівок реліквії, щоб вивчити нову здатність, а потім доповідайте Гарту Міструннеру в таборі Нараче.", [4] = "Чого тебе навчила ця реліквія. {ім'я}?", [5] = "Молодець, {ім'я}. Застосування вивченої вами руни до вашого спорядження надасть вам нові потужні здібності.\n\nШукайте більше наших втрачених реліквій під час своїх подорожей.", ["en"] = "Relics of the Tauren" },
    [77649] = { [1] = "Сила мисливця", [2] = "Мисливці є центральною частиною способу життя тауренів, {ім'я}. Наш народ розглядає нас як охоронців і постачальників. Багато разів у своїй подорожі ви будете самі на ворожій території, виживаючи лише завдяки своїй кмітливості.\n\nНещодавно мисливець-початківець експериментував з містичними рунами, щоб покращити свою бойову майстерність. Він вирушив випробувати свої нові здібності на Бойових Вепрахах-Щириках на сході, але так і не повернувся.\n\nЗнайдіть його руну та використовуйте її, щоб вивчити нову бойову техніку. Поверніться до мене, як тільки зробите це.", [3] = "Знайдіть відсутню руну, вбивши Бойових Кабанів Щетинистого Спинного в Ярузі Ожини. Використайте руну, щоб вивчити нову здатність, а потім поверніться до Ланки Фаршот у Табір Нараче.", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "A Hunter's Strength" },
    [77651] = { [1] = "У ожину", [2] = "Воїни Орди мають багато чого навчити тебе, {ім'я}, але ти також повинен самостійно шукати нові техніки.\n\nЯк тобі, можливо, відомо, на сході є група ворожих вепрів. Ще один воїн-початківець наважився проникнути на їхню територію деякий час тому і так і не повернувся. Він експериментував з гравіюванням містичних рун на своєму спорядженні, щоб покращити свою бойову майстерність.\n\nЗнайди руну серед вепрів і сам вивчи цю техніку. Повернися до мене, коли зробиш це.", [3] = "Знайдіть втрачену руну з Яру Ожининого Клинка. Використайте руну, щоб вивчити нову здатність, а потім поверніться до Харутта Громового Рогу в таборі Нараче.", [4] = "Ви знайшли руну {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Into the Brambles" },
    [77652] = { [1] = "Ікони влади", [2] = "Шаманізм — це давня практика, {ім'я}. По всьому Азероту можна знайти багато артефактів, сповнених духовної енергії. Нещодавно я сам виявив ікону значної сили, але її вкрав квілбор.\n\nВирушайте на їхню територію, на схід, і знайдіть вкрадену ікону. Ймовірно, її несе один з їхніх шаманів, намагаючись зрозуміти її таємниці.\n\nЯк тільки знайдете ікону, дізнайтеся її силу та поверніться до мене.", [3] = "Відіберіть втрачену ікону у шаманів-ожинок в ущелині Ожинні Клинки. Дізнайтеся її силу, а потім доповідайте Харутту Громорогу в таборі Нараче.", [4] = "Ви знайшли значок {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "Icons of Power", ["tasks"] = { ["Learn: Engrave Chest - Overload"] = "Дізнайтеся: Гравірування скрині - Перевантаження" } },
    [77668] = { [1] = "Втрачена руна", [2] = "Воїни Темної Леді можуть багато чого тебе навчити, але ти також повинен самостійно шукати нові техніки.\n\nЩе один воїн нещодавно вирушив на північ, до Улоговини Нічної Павутини. Він експериментував з гравіюванням містичних рун на своєму спорядженні, щоб покращити свою бойову майстерність.\n\nЯ підозрюю, що його приголомшили павуки, що кишіли в шахті. Знайди руну серед їхньої павутини та вивчи цю техніку сам.", [3] = "Знайдіть руну, заховану в Улоговині Нічної Павутини, та використовуйте її, щоб вивчити нову техніку, а потім доповідайте Данналу Стерну в Смертельному Дзвоні.", [4] = "Що ви знайшли?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "The Lost Rune" },
    [77669] = { [1] = "Червона Руна", [2] = "Ким ти був у житті, {ім'я}? Шпигуном? Злодієм? Кухарем, який особливо вправно володів ножем? Яким би не було твоє минуле, час прийняти нову тактику. Розбійники з Відреклих користуються кожною перевагою, що їм пропонується.\n\nНавернені в Багряне на сході б'ються так, ніби ніколи не бачили бою, але Хрестовий похід дав їм містичні руни, щоб посилити їхні здібності. Вкради одну з цих рун і вивчи її магію, а потім повернися до мене.", [3] = "Кишеньковий злодій або вбийте Навернених у Червоне Волосся, щоб знайти руну, а потім використайте її для вивчення нової здатності. Після цього поверніться до Девіда Тріаса в Смертельному Дзвоні.", [4] = "Ви знайшли руну {ім'я}?", [5] = "Молодець, {ім'я}. Застосування руни до вашого спорядження надасть вам нові потужні здібності.\n\nВ Азероті є багато таких рун. Шукайте їх, оскільки вони допоможуть вам у вашій подорожі.", ["en"] = "The Scarlet Rune" },
    [77670] = { [1] = "Медитація про нежить", [2] = "Я покличу у твою свідомість спогад про живих – це може бути навіть твій власний спогад. Піди на цвинтар біля цієї каплиці та знайди, де холод смерті найсильніший, потім стань на коліна та зосередь свої думки. Зосередившись на таємницях нежиті, ти знайдеш ясність у цьому спогаді та вивчиш нову техніку. Повернися до мене, коли зробиш це.", [3] = "Станьте на коліна на цвинтарі, щоб помедитувати про нежить, потім скористайтеся руною, щоб вивчити нову здатність. Після цього поверніться до Темного Клірика Дуестена в каплиці Смертельного Дзвона.\n\nНаданий предмет:", [4] = "Якщо вам важко зосередитися на смерті, ви можете спробувати померти ще раз. Малоймовірно, що другий раз це буде остаточно.", [5] = "Живі чіпляються за Світло з однієї причини – вони бояться забуття смерті. Як Покинуті, цей страх більше не має над вами влади. Хоча Світло тепер відкидає навіть тих серед нас, хто колись був його найпалкішими послідовниками, ми керуємо темними силами, що лежать за межами тіні смерті.\n\nУ міру того, як ви станете сильнішими, я рекомендую провести деякий час з тролями Орди. Хоча їхня культура примітивна, «лоа», яких вони шанують, мають певний зв'язок з нежитью. Вони можуть дати уявлення про нашу природу.", ["en"] = "Meditation on Undeath", ["tasks"] = { ["Memory of a Troubled Acolyte"] = "Пам'ять проблемного аколіта" } },
    [77671] = { [1] = "Дослідження правопису", [2] = "Арканісти Королівського аптекарського товариства присвячують своє неживе дослідженню заклинань на службі Відреклимся. Пригоди можуть бути вашим покликанням, але ви можете служити Темній Леді, збираючи та досліджуючи записки заклинань, які ви знайдете у своїх подорожах.\n\nВбийте посвячених у Багряний Хрестовий Похід, що розбили табір біля Смертного Дзвона, та захопіть їхні записки заклинань. Використайте цей посібник, щоб розшифрувати записки та вивчити нове заклинання, а потім поверніться до мене.", [3] = "Вбийте посвячених у Скарлет, щоб знайти нотатки до заклинань та використати їх для вивчення нової здатності, а потім поверніться до Ізабелли в Смертельному Дзвоні.", [4] = "Чого ти навчився, {ім'я}?", [5] = "Молодець, {ім'я}. Візьми ці Чари Розуміння. Вони допоможуть тобі розшифрувати будь-які інші таємні письмена, які ти знайдеш.\n\nПродовжуй шукати нотатки із заклинаннями по всьому Азероту та використовуй їх для подальшого дослідження. Якщо тобі потрібно більше чарів, відвідай продавця реагентів.", ["en"] = "Spell Research", ["tasks"] = { ["Comprehension Primer"] = "Посібник з розуміння" } },
    [77672] = { [1] = "Втрачена руна", [2] = "Я експериментував з новим типом магії — руною, яка може направляти енергію скверни для підживлення потужних заклинань. Я відправив учня випробувати руну проти павуків у шахті на півночі, але він не повернувся. Підозрюю, що ми більше його не побачимо.\n\nМожливо, ти виявишся більш стійким. Іди до шахти та дістань руну з павутиння. Вивчи її магію та доповісти мені.", [3] = "Знайдіть руну з Улоговини Нічної Павутини та використовуйте її, щоб вивчити нову здібність, потім поверніться до Максимілліона в Смертельному Дзвоні.", [4] = "Що ти знайшов, {ім'я}?", [5] = "Здається, ти добре звик до цієї нової магії, {ім'я}. Знайди більше таких рун і вигравіюй їх на своєму спорядженні, щоб мати нові здібності проти тих, хто тобі протистоїть.\n\nКолись, можливо, твоя сила навіть затьмарить мою власну.", ["en"] = "The Lost Rune", ["tasks"] = { ["Learn: Engrave Gloves - Haunt"] = "Дізнайтеся: Гравірування рукавичок - Привид" } },
    [7783] = { [1] = "Повелитель Чорнокамінної гори", [2] = "Вас сповнює знайоме почуття перемоги. Перед вами лежить величезна, вкрита ранами голова Нефаріана. Вам варто віднести її воєвождю, {стать:чемпіоне:чемпіонко}.", [3] = "Принесіть голову Нефаріана Траллу в Орґріммар.", [4] = "Хотів би я бути там і побачити морду цієї тварюки, коли ти {стать:завдав:завдала} їй смертельного удару, {ім'я}.", [5] = "Ти знову {стать:приніс:принесла} славу Орді, {ім'я}. Син Смертекрила мертвий. Звісно, нечисть тепер заворушиться.", ["en"] = "The Lord of Blackrock", ["tasks"] = { ["Head of Nefarian"] = "голова Нефаріана", ["Head of Nefarian (Provided)"] = "голова Нефаріана (видано)" } },
    [7784] = { [1] = "Повелитель Чорнокамінної гори", [2] = "Знайди верховного надповелителя Саурфанґа в долині Сили.", [3] = "Поговоріть з верховним надповелителем Саурфанґом в Орґріммарі. Він чекає вас в долині Сили.", [5] = "Обери свою нагороду і я встановлю голову цієї тварюки так, щоб усі її бачили.", ["en"] = "The Lord of Blackrock" },
    [780] = { [1] = "Бойові кнури", [2] = "Бойові кнури з ущелини Лезожини на сході зазіхають на мисливські угіддя нашого племені. Їх виховують бути злючими Свинобрази племені Щетиношкурів, з якими ми у війні.\n\nПіди й убий цих жорстоких істот і принеси декілька їхніх рил і вирізок, щоб ми могли зробити трохи тушковини для нашої малечі.", [3] = "Ґрулл Соколиний Вітер з табору Нараче хоче, щоб ви убили бойових кнурів і принесли йому 8 рил бойових кнурів і 8 вирізок бойових кнурів.", [4] = "Атаки бойових кнурів стають частішими. Ти вже {стать:послав:послала} їм чіткий знак і {стать:приніс:принесла} декілька рил і боків?", [5] = "Прекрасно! З цих інгредієнтів ми зробимо смачну страву, а втрата тих кнурів стане хорошим уроком тим злим Щетиношкурам.", ["en"] = "The Battleboars", ["tasks"] = { ["Battleboar Flank"] = "вирізка бойового кнура", ["Battleboar Flank (Provided)"] = "вирізка бойового кнура (видано)", ["Battleboar Snout"] = "рило бойового кнура", ["Battleboar Snout (Provided)"] = "рило бойового кнура (видано)" } },
    [7813] = { [1] = "Пожертва вовняного полотна", [4] = "Зараз ми приймаємо вовняне полотно. Щедра пожертва в шістдесят шматків вовняного полотна, без сумніву, позитивно позначиться на відношенні Підмістя до тебе і твоїх діянь. Наші сховища можуть прийняти від тебе шістдесят шматків вовняного полотна; ми розраховуємо і на пожертви інших.\n\nЯкщо в тебе є шістдесят шматків вовняного полотна і ти {стать:готовий:готова} їх пожертвувати - я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Wool", ["tasks"] = { ["Wool Cloth"] = "вовняне полотно", ["Wool Cloth (Provided)"] = "вовняне полотно (видано)" } },
    [7814] = { [1] = "Пожертва шовкового полотна", [4] = "Як і з більшістю інших тканин, наші запаси шовку зараз малі як ніколи. Наші сховища можуть прийняти від тебе шістдесят шматків шовкового полотна; ми розраховуємо і на пожертви інших, тому нам має вистачити на перший час.\n\nДодам, що така великодушна пожертва шовку, без сумніву, позитивно позначиться на відношенні нашої спільноти до тебе! Якщо в тебе є шістдесят шматків шовкового полотна і ти {стать:готовий:готова} їх пожертвувати - я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Silk", ["tasks"] = { ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [7815] = { [1] = "Тріскощелепи, чувак!", [2] = "Не дозволяй їхнім великим очам обманути себе, чувак! Ці морські тріскощелепи — неабияка загроза. Я не можу порибалити навіть п'ять хвилин: вони відривають мою волосінь та крадуть приманки.\n\nЗроби мені та жителям селища Сколотий Бивень послугу та вбий їх, чувак.\n\nВбий їх усіх!", [3] = "Рибалка Катум з селища Сколотий Бивень у Внутрішніх землях просить вас вбити 15 морських тріскощелепів. Поверніться до нього, коли виконаєте це завдання.", [4] = "Як проходить полювання?", [5] = "Ох, чувак! Не знаю, як тобі віддячити! Сподіваюся, ця вудка буде достатньою винагородою за твою роботу.", ["en"] = "Snapjaws, Mon!", ["tasks"] = { ["Saltwater Snapjaw"] = "морський тріскощелеп", ["Saltwater Snapjaw slain"] = "морський тріскощелеп: убито" } },
    [7816] = { [1] = "Ґаммеріта, чувак!", [2] = "Йо! Там є черепаха, не така як інші. Ґаммеріта, лідерка морських тріскощелепів, відверто брудна й злодійкувата рептилія.\n\nЧувак, вона вкрала мою найкращу приманку прямо з мого вудилища! Відтоді риба зовсім не клює.\n\nЗнайди Ґаммеріту та вийми мою приманку з її шлунку.", [3] = "Катум-Рибалка з селища Сколотий Бивень у Внутрішніх землях просить вас вбити Ґаммеріту і забрали з її тіла найкращу приманку Катума.\n\nКатум казав, що Ґаммеріта мешкає на узбережжі з іншими черепахами.", [4] = "Ти {стать:дістав:дістала} її?", [5] = "ЧУВАК! Це неймовірно! З моєю найкращою приманкою і зменшеною популяцією тріскощелепів, риби буде вдосталь.", ["en"] = "Gammerita, Mon!", ["tasks"] = { ["Katoom's Best Lure"] = "найкраща приманка Катума", ["Katoom's Best Lure (Provided)"] = "найкраща приманка Катума (видано)" } },
    [7817] = { [1] = "Пожертва маготканого полотна", [4] = "Маготканого полотна замало, і ми просимо твоєї допомоги, щоб поповнити наші запаси! Розраховуючи на допомогу інших, ми очікуємо пожертву у розмірі 60 відрізків маготканого полотна, щоб ми змогли досягти нашої цілі. Така щедрість не залишиться непоміченою в Підмісті, запевняю тебе!\n\nЯкщо в тебе є шістдесят шматків маготканого полотна і ти {стать:готовий:готова} їх пожертвувати - я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Mageweave", ["tasks"] = { ["Mageweave Cloth"] = "маготкане полотно", ["Mageweave Cloth (Provided)"] = "маготкане полотно (видано)" } },
    [7818] = { [1] = "Пожертва рунічного полотна", [4] = "{Ім'я}, твоя допомога тканиною нам дуже відчутна. Ми важко працюємо, щоб поповнити запаси, але все одно, залишки рунічного полотна критично малі. Воно нам вкрай необхідне. І ми сподіваємося, що ти нам допоможеш, як і раніше.\n\nЯкщо можеш, прошу, принеси мені стільки рунічного полотна, скільки зможеш. Для першої пожертви ми приймаємо шістдесят шматків, а потім можна буде пожертвувати більше.", [5] = "Неймовірно! Ця тканина негайно піде в роботу, я тебе запевняю. Ще раз дякую за допомогу! Без тебе ми б не впоралися.\n\nЯ з радістю прийму від тебе більше рунічного полотна. Приходь до мене час від часу, я особисто слідкуватиму, щоб твої пожертви не пройшли непоміченими.", ["en"] = "A Donation of Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7819] = { [1] = "Більше рунічного полотна", [4] = "Ще раз вітаю, {ім'я}! Нам завжди потрібна рунічна тканина і ми завжди готові прийняти більше, якщо ти {стать:готовий:готова} її віддати. За додаткову пожертву з двадцяти рунічних полотен я подбаю про те, щоб у Підмісті відзначили твої постійні зусилля.\n\nЯкщо ти будеш {стать:готовий:готова} віддати стопку рунічного полотна, я з радістю прийму її.", [5] = "{ім'я} - без таких героїв, як ти, які допомагають нам, відреченим, ми, безперечно, страждали б. Дякуємо за твої постійні старання!", ["en"] = "Additional Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [78196] = { [1] = "Таємниці нежиті", [2] = "Якщо ви шукаєте «віри» чи «поклоніння» серед жерців Відреклих, ви будете розчаровані. Ми бачили за межами смерті і знаємо, що там нас нічого не чекає. Наша віра походить від холодного досвіду, а не від наївної надії.\n\nДосвід... можливо, це те, що вам потрібно. Зберіть тіньове листя у болотних істот Ясенеділу, а потім поверніться до мене. У мене є ідея, яка може відповісти на ваші запитання.", [3] = "Зберіть 12 Тінистих листів у елементалів Тінистій Гущавини в Ясеневому Долині.", [4] = "Ви зібрали тінисте листя?", [5] = "Зачекай хвилинку, я щось тобі приготую...", ["en"] = "Secrets of Undeath" },
    [78197] = { [1] = "Таємниці нежиті", [2] = "Усі Покинуті пережили межу смерті. Бачити, як існування добігає кінця, без жодних богів за ним... це може здатися жахливим, але це справді звільняє. Наша воля — наша власна, вона не залежить від жодних сил, окрім нас самих.\n\nІдіть на цвинтар у Бріллі та випийте цю настоянку. Вона доставить вас на межу смерті та утримає там. Зустріньте забуття з рішучістю, і ви знайдете шлях назад до життя. Я не можу уявити кращого способу поділитися тим, що означає бути Покинутим.", [3] = "Відправляйтеся на цвинтар Брілла в Тірісфальських галявинах і використовуйте Настоянку Неспання.", [4] = "Ти намагаєшся покликати духа-цілителя, але не видаєш ні звуку. Його погляд проходить крізь тебе, не помічаючи.", [5] = "Твій жах здається далеким, оскільки настоянка послаблює зв'язок між твоєю душею та розумом. Перед тобою простягається вічність нічого.\n\nНа мить ти сприймаєш весь Азерот, теперішнє та майбутнє. Нитка твоєї долі виривається з гобелена та відкидається, не залишаючи сліду. Світ продовжує обертатися, не помічаючи твоєї відсутності.\n\nТи повільно приходиш до тями, коли дія настоянки зникає. Чи... так постійно почуваються Відреклі?", ["en"] = "Secrets of Undeath", ["tasks"] = { ["Tincture of Waking Death"] = "Настоянка смерті наяву" } },
    [78198] = { [1] = "Таємниці Лоа", [2] = "Могутні імперії тролів наших предків були побудовані на силі лоа — духів великої сили, які правлять по всьому Азероту. Ми поклоняємося багатьом лоа в племені Темного Списа, але якщо ви зацікавлені поділитися нашою вірою, є один особливий, хто може бути готовий торгуватися з вами.\n\nСпочатку вам потрібно буде підготувати жертву. Вирушайте до Таррен Млин і завдайте удару по людях, які оскаржують претензії Орди на цю територію. Зберіть кістки своїх жертв і поверніться до мене.", [3] = "Зберіть 14 людських кісток з Гіллсбраду у людей у Передгір'ях Гіллсбраду, а потім поверніться до Бадж'ури в Підмісті.", [4] = "Як проходить битва з людьми?", [5] = "Чудово... ці останки стануть чудовою пропозицією.", ["en"] = "Secrets of the Loa" },
    [78199] = { [1] = "Таємниці Лоа", [2] = "Віднесіть жертву на південь, до Островів Ехо. Вздовж пляжів острова ви знайдете святилище Бвонсамді, лоа смерті. Жертва від Відреклого безсумнівно приверне його увагу.\n\nОднак попереджаю вас, {ім'я}. Завжди доводиться платити ціну, торгуючись з лоа. Ви можете не усвідомлювати, чим зараз відмовляєтеся, але Бвонсамді завжди зрештою стягує свої борги.", [3] = "Подорожуйте до Островів Відлуння та скористайтеся підношенням у святилищі Бвонсамді.", [4] = "Повітря навколо вас ніби згущується, коли ви кладете свою жертву на купу.", [5] = "Твоя жертва спалахує пурпуровим полум'ям, коли тінь падає на землю. Ти нікого не бачиш, але відчуваєш присутність лоа смерті, що хитро дивиться за тобою.\n\nОбрази наповнюють твою свідомість. Стіна масок, що простягається за межі поля зору та сміється з тебе. Храм у великому болоті, наповнений душами померлих.\n\nКоли видіння прояснюється, у повітрі лунає сміх...", ["en"] = "Secrets of the Loa", ["tasks"] = { ["Voodoo Offering"] = "Підношення вуду" } },
    [782] = { [1] = "Розірвані союзи", [2] = "Завдяки союзу Орди з драконом Смертекрилом часів Другої війни ми знаємо, що два його лейтенанти, Чорнохлист та Гемат, були ув'язнені далеко на сході, в ущелині Летлор. Щоб відновити честь Орди, ми повинні змусити замовкнути наших порочних союзників з минулого!\n\nМи найняли То'ґруна та його зграю огрів-найманців допомогти нам здобути знак Землі — ключ, необхідний, щоб відчинити в'язницю драконів. Але То'ґрун нас зрадив, розбивши наші сили, і забрав знак собі. Вирушай до табору Бофф і відбери його!", [3] = "Убийте ватажка То'ґруна і принесіть знак Землі Ґорну в Карґат.", [4] = "Зрада То'ґруна... і хтось ще дивується, чому огри більше не в Орді? Я буду радий його смерті та поверненню знака Землі.\n\nЯкщо ти ще не {стать:розправився:розправилася} з ним, не марнуй час і вирушай до табору Бофф. Це на південний схід від Карґата.", [5] = "Оскільки То'ґрун мертвий, а його скелет обчистили пустельні вітри та нишпорки-канюки, серед огрів почнеться безлад. Хоч це й мала перемога, та вона призведе до значно більшої.\n\nЗнак Землі тепер у нас, і ми зможемо відімкнути в'язницю чорних драконів у Летлорі. Ми звільнимо їх від їхнього вічного ув'язнення, хоча й для їхньої погибелі!", ["en"] = "Broken Alliances", ["tasks"] = { ["Sign of the Earth"] = "знак Землі", ["Sign of the Earth (Provided)"] = "знак Землі (видано)" } },
    [7820] = { [1] = "Пожертва вовняного полотна", [4] = "Зараз ми приймаємо вовняне полотно. Щедра пожертва в шістдесят шматків вовняного полотна, без сумніву, позитивно позначиться на відношенні Громового Бескиду до тебе і твоїх діянь. Наші сховища можуть прийняти від тебе шістдесят шматків вовняного полотна; ми розраховуємо і на пожертви інших.\n\nЯкщо в тебе є шістдесят шматків вовняного полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Wool", ["tasks"] = { ["Wool Cloth"] = "вовняне полотно", ["Wool Cloth (Provided)"] = "вовняне полотно (видано)" } },
    [7821] = { [1] = "Пожертва шовкового полотна", [4] = "Як і з більшістю інших тканин, наші запаси шовку зараз малі як ніколи. Наші сховища можуть прийняти від тебе шістдесят шматків шовкового полотна; ми розраховуємо і на пожертви інших, тому нам має вистачити на перший час.\n\nДодам, що така великодушна пожертва шовку, без сумніву, позитивно позначиться на відношенні нашої спільноти до тебе! Якщо в тебе є шістдесят шматків шовкового полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Silk", ["tasks"] = { ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [7822] = { [1] = "Пожертва маготканого полотна", [4] = "Маготканого полотна замало, і ми просимо твоєї допомоги, щоб поповнити наші запаси! Розраховуючи на допомогу інших, ми очікуємо пожертву у розмірі 60 відрізків маготканого полотна, щоб ми змогли досягти нашої цілі. Така щедрість не залишиться непоміченою в Громовому Бескиді, запевняю тебе!\n\nЯкщо в тебе є шістдесят шматків маготканого полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Mageweave", ["tasks"] = { ["Mageweave Cloth"] = "маготкане полотно", ["Mageweave Cloth (Provided)"] = "маготкане полотно (видано)" } },
    [7823] = { [1] = "Пожертва рунічного полотна", [4] = "{Ім'я}, твоя допомога тканиною нам дуже відчутна. Ми важко працюємо, щоб поповнити запаси, але все одно, залишки рунічного полотна критично малі. Воно нам вкрай необхідне. І ми сподіваємося, що ти нам допоможеш, як і раніше.\n\nЯкщо можеш, прошу, принеси мені стільки рунічного полотна, скільки зможеш. Для першої пожертви ми приймаємо шістдесят шматків, а потім можна буде пожертвувати більше.", [5] = "Неймовірно! Ця тканина негайно піде в роботу, я тебе запевняю. Ще раз дякую за допомогу! Без тебе ми б не впоралися.\n\nЯ з радістю прийму від тебе більше рунічного полотна. Приходь до мене час від часу, я особисто слідкуватиму, щоб твої пожертви не пройшли непоміченими.", ["en"] = "A Donation of Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7824] = { [1] = "Пожертва рунічного полотна", [4] = "{Ім'я}, твоя допомога тканиною нам дуже відчутна. Ми важко працюємо, щоб поповнити запаси, але все одно, залишки рунічного полотна критично малі. Воно нам вкрай необхідне. І ми сподіваємося, що ти нам допоможеш, як і раніше.\n\nЯкщо можеш, прошу, принеси мені стільки рунічного полотна, скільки зможеш. Для першої пожертви ми приймаємо шістдесят шматків, а потім можна буде пожертвувати більше.", [5] = "Неймовірно! Ця тканина негайно піде в роботу, я тебе запевняю. Ще раз дякую за допомогу! Без тебе ми б не впоралися.\n\nЯ з радістю прийму від тебе більше рунічного полотна. Приходь до мене час від часу, я особисто слідкуватиму, щоб твої пожертви не пройшли непоміченими.", ["en"] = "A Donation of Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7825] = { [1] = "Більше рунічного полотна", [4] = "Ще раз вітаю, {ім'я}! Нам завжди потрібна рунічна тканина і ми завжди готові прийняти більше, якщо ти {стать:готовий:готова} її віддати. За додаткову пожертву з двадцяти рунічних полотен я подбаю про те, щоб у Громовому Бескиді відзначили твої постійні зусилля.\n\nЯкщо ти будеш {стать:готовий:готова} віддати стопку рунічного полотна, я з радістю прийму її.", [5] = "{ім'я} — без таких героїв, як ти, які віддані Громовому Бескиду, нам, безперечно, було б тяжко. Дякуємо за твої постійні старання!", ["en"] = "Additional Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7826] = { [1] = "Пожертва вовняного полотна", [4] = "Зараз ми приймаємо вовняне полотно. Щедра пожертва в шістдесят шматків вовняного полотна, без сумніву, позитивно позначиться на відношенні Орґріммару до тебе і твоїх діянь. Наші сховища можуть прийняти від тебе шістдесят шматків вовняного полотна; ми розраховуємо і на пожертви інших.\n\nЯкщо в тебе є шістдесят шматків вовняного полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Wool", ["tasks"] = { ["Wool Cloth"] = "вовняне полотно", ["Wool Cloth (Provided)"] = "вовняне полотно (видано)" } },
    [7827] = { [1] = "Пожертва шовкового полотна", [4] = "Як і з більшістю інших тканин, наші запаси шовку зараз малі як ніколи. Наші сховища можуть прийняти від тебе шістдесят шматків шовкового полотна; ми розраховуємо і на пожертви інших, тому нам має вистачити на перший час.\n\nДодам, що така великодушна пожертва шовку, без сумніву, позитивно позначиться на відношенні нашої спільноти до тебе! Якщо в тебе є шістдесят шматків шовкового полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Silk", ["tasks"] = { ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [78277] = { [1] = "Знак подяки", [5] = "Можливо, це було дурницею, але Туле, Гунтар і я були як родина... брати. Ми ніколи не очікували, що наш світ буде розірвано, ані того, що Туле стане на бік Короля-ліча, залишивши Гунтара та мене боротися за нашу людяність...\n\nЯ відчуваю, як скверна бича просочується в частину палички Туле. Вона назавжди буде зіпсована, зіпсована його зрадою, але, на жаль, я не готовий відпустити... можливо, з часом.\n\nБудь ласка, прийміть цей знак знання як мою останню подяку.", ["en"] = "A Token of Gratitude" },
    [7828] = { [1] = "Зловити ловців", [2] = "Багато хоробрих тролів загинули у жорстоких диких краях Внутрішніх земль, {раса:к}. Срібногриві вовки є однією з найбільших загроз нашим мисливцям. Вони чатують, ховаючись серед кущів та трави, а потім раптово нападають.\n\nТака жорстокість не може залишатись безкарною!\n\nТобі потрібно думати, як срібногривий вовк. Вистеж хижаків! Покінчи з ними!", [3] = "Мисливець Маркгор з селища Сколотий Бивень у Внутрішніх землях просить вас вбити 15 срібногривих ловців та 15 срібногривих ревунів. Поверніться до нього коли виконаєте завдання.\n\nМаркгор згадував, що вовки ховаються в дикій природі Внутрішніх земель.", [4] = "Покажи їм силу Сколотого Бивня!", [5] = "Чудова робота, {раса:к}. Плем'я Сколотого Бивня дякує тобі.", ["en"] = "Stalking the Stalkers", ["tasks"] = { ["Silvermane Howler"] = "срібногривий ревун", ["Silvermane Howler slain"] = "срібногривий ревун: убито", ["Silvermane Stalker"] = "срібногривий ловець", ["Silvermane Stalker slain"] = "срібногривий ловець: убито" } },
    [78288] = { [1] = "Дозвольте мені зробити вам пропозицію", [2] = "Перший пробіг готовий, {ім'я}. Віднеси це до Орґріммара та покажи начальству. Хтось, хто може підписати контракт сьогодні!", [3] = "Віднесіть вантаж зброї Зел'маку в Орґріммар.", [4] = "Доставка з Брашпиля? Я нічого не замовляв у Брашпилі.", [5] = "Постачальник зброї в Ретчеті? Хм... Орда намагається перенаправити бізнес гоблінів до нас, а не від Альянсу. Нам слід діяти швидко, щоб скористатися цією новою можливістю.", ["en"] = "Let Me Make You An Offer", ["tasks"] = { ["Arms Shipment"] = "Поставка зброї" } },
    [7829] = { [1] = "Полювання на дикунів", [2] = "Одні з найагресивніших представників дикої природи Внутрішніх земель — дикі совозвірі. Багато добрих воїнів Сколотого Бивня загинуло від жорстоких кігтів та дзьобів цих істот.\n\nУбий всіх диких совозвірів, яких зустрінеш, {раса:к}. Повертайся до мене, коли не зможеш більше проливати кров. Твоя допомога буде зважена, виміряна і гідно оцінена.", [3] = "Мисливець Маркгор з селища Сколотий Бивень у Внутрішніх землях просить вас вбити 20 диких совозвірів. Поверніться до нього коли виконаєте завдання.\n\nМаркгор згадував, що дикі совозвірі заполонили дикі ліси Внутрішніх земель.", [4] = "Очисть свою голову від нечистих думок, {раса:к}. Стань одним цілим з дикою природою!", [5] = "Ти {стать:виявився гідним союзником:виявилася гідною союзницею} Сколотого Бивня, {ім'я}. Молодець.", ["en"] = "Hunt the Savages", ["tasks"] = { ["Savage Owlbeast"] = "дикий совозвір", ["Savage Owlbeast slain"] = "дикий совозвір: убито" } },
    [7830] = { [1] = "Помста за полеглих", [2] = "Ця нечисть, яка називає себе Диким Молотом, тренує грифонів, щоб вбивати тролів. Жахливо, я знаю, але не хвилюйся, скоро ми здійснимо правосуддя.\n\nА зараз я хочу, щоб ти {стать:зосередився:зосередилася} на винищенні старших грифонів у цих землях. Вони відомі як гостродзьобі володарі неба.\n\nВбий одного з них і повертайся до мене з його пір'ям.", [3] = "Мисливець Маркгор з селища Сколотий Бивень у Внутрішніх землях просить вас вбити гостродзьобого володаря неба і забрати його перо. Поверніться до Маркгора, коли завдання буде виконано.\n\nМаркгор згадував, що гостродзьобий володар неба — рідкісна порода, яка, як правило, мешкає в дикій природі Внутрішніх земель.", [4] = "Гостродзьобий володар неба — набагато рідкісніший вид грифонів, відповідальний за спарювання і створення смертоносного потомства.", [5] = "<Маркгор розглядає перо.>\n\nЦікаво, скількох наших мисливців зжер цей звір, перш ніж ти {стать:здійснив:здійснила} правосуддя?", ["en"] = "Avenging the Fallen", ["tasks"] = { ["Skylord Plume"] = "перо володаря неба", ["Skylord Plume (Provided)"] = "перо володаря неба (видано)" } },
    [78304] = { [1] = "Ви уклали угоду", [2] = "Я підписав і скріпив контракт, {ім'я}. Скажи цьому гобліну, що він тепер має справу виключно з Ордою.", [3] = "Поверніть підписаний контракт на закупівлю Гріззбі в Ретчет.", [4] = "Ви закрили угоду?", [5] = "Вони підписали, навіть не домовляючись? Ха! У старого Гріззбі все владнається!\n\nА ти, {ім'я}, був справжнім другом. Ось тобі маленький знак моєї подяки.\n\nА тепер, коли ми офіційно розпочали бізнес, сміливо переглядай мій асортимент спорядження та шукай, чи щось приверне твою увагу. Я навіть зроблю тобі знижку для працівників!", ["en"] = "You've Got Yourself A Deal" },
    [7831] = { [1] = "Пожертва маготканого полотна", [4] = "Маготканого полотна замало, і ми просимо твоєї допомоги, щоб поповнити наші запаси! Розраховуючи на допомогу інших, ми очікуємо пожертву у розмірі 60 відрізків маготканого полотна, щоб ми змогли досягти нашої цілі. Така щедрість не залишиться непоміченою в Орґріммарі, запевняю тебе!\n\nЯкщо в тебе є шістдесят шматків маготканого полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Mageweave", ["tasks"] = { ["Mageweave Cloth"] = "маготкане полотно", ["Mageweave Cloth (Provided)"] = "маготкане полотно (видано)" } },
    [7832] = { [1] = "Більше рунічного полотна", [4] = "Ще раз вітаю, {ім'я}! Нам завжди потрібна рунічна тканина і ми завжди готові прийняти більше, якщо ти {стать:готовий:готова} її віддати. За додаткову пожертву з двадцяти рунічних полотен я подбаю про те, щоб в Орґріммарі відзначили твої постійні зусилля.\n\nЯкщо ти будеш {стать:готовий:готова} віддати стопку рунічного полотна, я з радістю прийму її.", [5] = "{ім'я} — без таких героїв, як ти, які віддані Орґріммару, нам, безперечно, було б тяжко. Дякуємо за твої постійні старання!", ["en"] = "Additional Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7833] = { [1] = "Пожертва вовняного полотна", [4] = "Зараз ми приймаємо вовняне полотно. Щедра пожертва в шістдесят шматків вовняного полотна, без сумніву, позитивно позначиться на відношенні тролів Темного Списа до тебе і твоїх діянь. Наші сховища можуть прийняти від тебе шістдесят шматків вовняного полотна; ми розраховуємо і на пожертви інших.\n\nЯкщо в тебе є шістдесят шматків вовняного полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Wool", ["tasks"] = { ["Wool Cloth"] = "вовняне полотно", ["Wool Cloth (Provided)"] = "вовняне полотно (видано)" } },
    [7834] = { [1] = "Пожертва шовкового полотна", [4] = "Як і з більшістю інших тканин, наші запаси шовку зараз малі як ніколи. Наші сховища можуть прийняти від тебе шістдесят шматків шовкового полотна; ми розраховуємо і на пожертви інших, тому нам має вистачити на перший час.\n\nДодам, що така великодушна пожертва шовку, без сумніву, позитивно позначиться на відношенні нашої спільноти до тебе! Якщо в тебе є шістдесят шматків шовкового полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Silk", ["tasks"] = { ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [7835] = { [1] = "Пожертва маготканого полотна", [4] = "Маготканого полотна замало, і ми просимо твоєї допомоги, щоб поповнити наші запаси! Розраховуючи на допомогу інших, ми очікуємо пожертву у розмірі 60 відрізків маготканого полотна, щоб ми змогли досягти нашої цілі. Така щедрість не залишиться непоміченою тролями Темного Списа, запевняю тебе!\n\nЯкщо в тебе є шістдесят шматків маготканого полотна і ти {стать:готовий:готова} їх пожертвувати — я можу прийняти їх просто зараз.", [5] = "Чудово! Ми вдячні тобі за таку щедру пожертву, {ім'я}!", ["en"] = "A Donation of Mageweave", ["tasks"] = { ["Mageweave Cloth"] = "маготкане полотно", ["Mageweave Cloth (Provided)"] = "маготкане полотно (видано)" } },
    [7836] = { [1] = "Пожертва рунічного полотна", [4] = "{Ім'я}, твоя допомога тканиною нам дуже відчутна. Ми важко працюємо, щоб поповнити запаси, але все одно, залишки рунічного полотна критично малі. Воно нам вкрай необхідне. І ми сподіваємося, що ти нам допоможеш, як і раніше.\n\nЯкщо можеш, прошу, принеси мені стільки рунічного полотна, скільки зможеш. Для першої пожертви ми приймаємо шістдесят шматків, а потім можна буде пожертвувати більше.", [5] = "Неймовірно! Ця тканина негайно піде в роботу, я тебе запевняю. Ще раз дякую за допомогу! Без тебе ми б не впоралися.\n\nЯ з радістю прийму від тебе більше рунічного полотна. Приходь до мене час від часу, я особисто слідкуватиму, щоб твої пожертви не пройшли непоміченими.", ["en"] = "A Donation of Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7837] = { [1] = "Більше рунічного полотна", [4] = "Ще раз вітаю, {Ім'я}! Нам завжди потрібна рунічна тканина і ми завжди готові прийняти більше, якщо ти {стать:готовий:готова} її віддати. За додаткову пожертву з двадцяти рунічних полотен я подбаю про те, щоб тролі Темного Списа відзначили твої постійні зусилля.\n\nЯкщо ти будеш {стать:готовий:готова} віддати стопку рунічного полотна, я з радістю прийму її.", [5] = "{ім'я} — без таких героїв, як ти, які віддані тролям Темного Списа, нам, безперечно, було б тяжко. Дякуємо за твої постійні старання!", ["en"] = "Additional Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [7839] = { [1] = "Хулігани Миршавого Гілля", [2] = "Ці мерзотники з племені Миршавого Гілля напали на наше селище і вкрали мої інструменти! Я звісно маю запасні, але той набір, що вони вкрали, був подарований мені добросердечним гномом, який врятував мене, коли я був юним орком.\n\nЯ хочу повернути ці інструменти, {ім'я} — вони дуже цінні для мене.\n\nМаркгор повідомив, що інструменти були помічені біля храмів Аґол'вата і Шаол'вата.\n\nЦі храми знаходяться на північному сході Внутрішніх земель.\n\nЗнайди мої інструменти!", [3] = "Коваль Вуглепал з селища Сколотий Бивень у Внутрішніх землях просить вас знайти загублені інструменти Вуглепала. Поверніться до нього коли виконаєте це завдання.\n\nКоваль Вуглепал згадував, що інструменти можуть бути в одному з храмів Миршавого Гілля в північно-східній частині Внутрішніх земель. Також варто перевірити в Замаскованій печері.", [4] = "Стережись тролів племені Миршавого Гілля, {ім'я}. Вони дуже жорстокі та агресивні.", [5] = "Мої інструменти! Ти {стать:знайшов:знайшла} їх! Славний день! Спасибі тобі, {ім'я}.", ["en"] = "Vilebranch Hooligans", ["tasks"] = { ["Slagtree's Lost Tools"] = "загублені інструменти Вуглепала", ["Slagtree's Lost Tools (Provided)"] = "загублені інструменти Вуглепала (видано)" } },
    [784] = { [1] = "Розчавити зрадників", [2] = "Під командуванням адмірала Праудмура люди Кул-Тіраса вторглись в Дуротар. Цим вони порушили договір воєвождя з Джайною Праудмур, що був підписаний для сумісної перемоги над Архімондом багато років тому.\n\nНаші сили відбили людську агресію, Тіраґардська твердиня пала. Але нещодавно резерви адмірала, під командуванням лейтенанта Бенедикта, захопили твердиню і знову загрожують нашій батьківщині. Ці люди не виказують ніякої поваги до дипломатії.\n\nДоведи свою гідність і відправляйся на південь до Тіраґардської твердині. Прожени звідти людських загарбників.", [3] = "Убийте 10 кул-тіраських моряків, 8 кул-тіраських морських піхотинців і лейтенанта Бенедикта, після чого поверніться до Ґар'Тока у Колючий Пагорб.", [4] = "У тебе є наказ, {Ім'я}. Безпека Дуротару під загрозою. Заверши завдання або схили голову у ганьбі.\n\nДоведи свою гідність і переможи людей у Тіраґардській твердині.", [5] = "Чутки про твою хоробрість швидко розповсюджуються, {Ім'я}. Розповіді про перемогу у Тіраґардській твердині будуть ширитись Орґріммаром.", ["en"] = "Vanquish the Betrayers", ["tasks"] = { ["Kul Tiras Marine"] = "кул-тіраський морський піхотинець", ["Kul Tiras Marine slain"] = "кул-тіраський морський піхотинець: убито", ["Kul Tiras Sailor"] = "кул-тіраський моряк", ["Kul Tiras Sailor slain"] = "кул-тіраський моряк: убито", ["Lieutenant Benedict"] = "лейтенант Бенедикт", ["Lieutenant Benedict slain"] = "лейтенант Бенедикт: убито" } },
    [7840] = { [1] = "Лард загубив свій обід", [2] = "Лард був на пікніку в таємному місці, коли злі гімнюки з племені Миршавого Гілля побили його здоровою палкою. Лард побіг назад до Сколотого Бивня, але забув свой обід. Лард голодний. Може, ти змож вернуться в таємне місце і забрать мій обід? Лард боїться. Йди на півнєч! Остров на півнєчі — моє таємне місце для пікніка.", [3] = "Лард з селища Сколотий Бивень у Внутрішніх землях просить вас знайти його обід. Поверніться до нього, коли виконаєте це завдання.\n\nЛард згадував, що залишив його на острові на півночі. Остерігайтеся тролів Миршавого Гілля.", [4] = "<Лард потирає свій величезний живіт.>\n\nЛард такий голодний.", [5] = "<Лард бере у вас величезний шмат м'яса і пхає його собі в рот>.\n\nОх як харашо! Пасіба, {стать:малий:мала}.\n\nЛард зробить для тебе спеціальний кошик для пікніка, за те шо ти {стать:поміг:помогла} Ларду.", ["en"] = "Lard Lost His Lunch", ["tasks"] = { ["Lard's Lunch"] = "обід Ларда", ["Lard's Lunch (Provided)"] = "обід Ларда (видано)" } },
    [7842] = { [1] = "Ще одне послання Дикому Молоту", [2] = "Кажуть, що дворфи Дикого Молота і грифони настільки ж близькі, як троль та його дружина. Огидно, але ми можемо використати це на свою користь. Ми відправимо їм ще одне послання.\n\nВбивай всіх грифонів, яких зустрінеш у Внутрішніх землях, і збери їх пір'я. З нього ми складемо останнє послання.", [3] = "Отон Моджі'ко з селища Сколотий Бивень у Внутрішніх землях хоче, щоб ви принесли йому 10 довгих елегантних пір'їн грифонів, що мешкають у Внутрішніх землях. Поверніться до нього коли виконаєте це завдання.\n\nВідомо, що грифони мешкають у кожному регіоні Внутрішніх земель.", [4] = "Останнє повідомлення їх точно налякає. Або розлютить їх, дуже сильно.", [5] = "Ох, це буде круто. Ще один крок, і Дикий Молот зрозуміє, що з тролями не варто жартувати!", ["en"] = "Another Message to the Wildhammer", ["tasks"] = { ["Long Elegant Feather"] = "довге елегантне перо", ["Long Elegant Feather (Provided)"] = "довге елегантне перо (видано)" } },
    [7843] = { [1] = "Останнє послання Дикому Молоту", [2] = "<Отон передає вам довгий закривавлений спис, обгорнутий пір'ям грифона.>\n\nВізьми його, {стать:друже:подруго}. Йди на Орлиний пік, прямо в центр міста, до колодязя. Встроми його прямо в землю! Покажи цим дворфам, що з нами не варто жартувати! Повертайся, коли зробиш це. Сподіваюсь, що ти повернешся {стать:живим:живою}.", [3] = "Отон Моджі'ко з селища Сколотий Бивень у Внутрішніх землях хоче, щоб ви вирушили на Орлиний пік у західному регіоні Внутрішніх земель і розмістили останнє послання Дикому Молоту біля колодязя в центрі міста. Поверніться до нього коли виконаєте це завдання.\n\nОстерігайтеся розлючених дворфів Дикого Молота та шалених членів Альянсу.", [4] = "Що за затримка, {стать:друже:подруго}?", [5] = "Хотів би я бути там і бачити їхні обличчя, {стать:друже:подруго}. Вони пакують валізи? Залишають місто?\n\nГарна робота, {ім'я}. Дуже гарна. Отон нагородить тебе великим талісманом.", ["en"] = "The Final Message to the Wildhammer", ["tasks"] = { ["Message to the Wildhammer Delivered"] = "Послання до Дикого Молота доставлено" } },
    [7844] = { [1] = "Родичі-канібали", [2] = "Внутрішні землі населяють три різні племені тролів, {ім'я}. Це все, що є спільного між нами: ми всі тролі та живемо в Внутрішніх землях.\n\nПлем'я Миршавого Гілля заслужено отримало таку назву — це зіпсоване плем'я. Вони їдять інших тролей і взагалі всіх, хто підвернеться.\n\nЯкби Зул'джин був тут, він знищив би всю цю ватагу одним рухом — та на жаль, Зул'джин ще не повернувся, і нам треба впоратись самостійно.\n\nЗнищ цю нечисть!", [3] = "Містик Яйо'джін з селища Сколотий Бивень у Внутрішніх землях просить вас вбити 30 скальпорізів Миршавого Гілля та 15 віщунів Миршавого Гілля. Поверніться до неї, коли виконаєте завдання.\n\nЯйо'джін сказала, що цих тролів можна знайти біля храмів Шаол'вата та Аґол'вата на півночі на північному сході Внутрішніх земель.", [4] = "Віщуни й скальпорізи Миршавого Гілля населяють північні та північно-східні райони Внутрішніх земель.", [5] = "Дуже добре, {клас:к}. Сам Зул'джин не зробив би краще!", ["en"] = "Cannibalistic Cousins", ["tasks"] = { ["Vilebranch Scalper"] = "скальпоріз Миршавого Гілля", ["Vilebranch Scalper slain"] = "скальпоріз Миршавого Гілля: убито", ["Vilebranch Soothsayer"] = "віщун Миршавого Гілля", ["Vilebranch Soothsayer slain"] = "віщун Миршавого Гілля: убито" } },
    [7845] = { [1] = "Викрадено старійшину Розірваного Бивня!", [2] = "Мого чоловіка захопили дикуни з племені Миршавого Гілля під час нічного набігу на наше селище. Наші шпигуни повідомили мені, що він все ще живий і його утримують в полоні на вершині Джінта'Алора. Кажуть, що підступна жриця Гекс готує його для жертвоприношення безликому богу крові Гаккару.\n\nТи маєш врятувати його, {ім'я}! Наше селище не переживе такої тяжкої втрати.", [3] = "Голова Розірваний Бивень з селища Сколотий Бивень у Внутрішніх землях хоче, щоб ви врятували її чоловіка, старійшину Розірваного Бивня, з Джінта'Алора.\n\nВам повідомили, що його утримують у полоні на вершині Джінта'Алора, столиці племені Миршавого Гілля, розташованої на півдні Внутрішніх земель.", [5] = "Ти маєш діяти швидко, {ім'я}. Вартових попередили про твій прихід.", ["en"] = "Kidnapped Elder Torntusk!" },
    [7846] = { [1] = "Знайди ключ!", [2] = "Ключ від моїх кайданів у Гітаг'ї-Хранительки. Вона знаходиться неподалік, в печері. Будь {стать:обережним:обережною}, {клас:к}, у неї багато охоронців.\n\nВбий її та принеси ключ, щоб зняти ці кайдани. Тільки тоді я зможу повернутися додому.", [3] = "Старійшина Розірваний Бивень у Джінта'Алорі просить вас вбити Гітаг'ю-Хранительку і забрати ключ від його кайданів. Поверніться до старійшини Розірваного Бивня, коли знайдете ключ.", [4] = "Поквапся!", [5] = "Нарешті, свобода! Дякую тобі, {ім'я}. Сколотий Бивень дізнається про твій вчинок!", ["en"] = "Recover the Key!", ["tasks"] = { ["Shackle Key"] = "ключ від кайданів", ["Shackle Key (Provided)"] = "ключ від кайданів (видано)" } },
    [7847] = { [1] = "Повернення до голови Розірваного Бивня", [2] = "Повернись до моєї дружини, голови Розірваний Бивень в селище Сколотий Бивень. Скажи їй, що я повертаюся додому! Вона обов'язково винагородить тебе.", [3] = "Старійшина Розірваний Бивень в Джінта'Алорі хоче, щоб ви повернулися до голови Розірваного Бивня в селище Сколотий Бивень зі звісткою про його порятунок.", [5] = "Ти {стать:зробив:зробила} нашому племені велику послугу, {ім'я}! Ми в неоплатному боргу перед тобою.", ["en"] = "Return to Primal Torntusk" },
    [7849] = { [1] = "Туга розлуки", [2] = "Як і багато хто в нашому селищі, я теж втратив близьких в лісі. На жаль, це був мій брат Малкгор — тролі Миршавого Гілля взяли його в полон тієї ж ночі, що й чоловіка старійшини.\n\nНа жаль, мого брата дуже швидко стратили, а його останки кинули на поживу слизням і вовкам Миршавого Гілля.\n\nРятувати його життя вже надто пізно, але ми можемо врятувати його душу. Знайди його останки, {ім'я}.", [3] = "Мисливець Маркгор з селища Сколотий Бивень у Внутрішніх землях хоче, щоб ви повернули останки його брата. Знайдіть і поверніть череп і кістки мисливця Малкгора мисливцю Маркгору.\n\nМаркгор сказав, що останки його брата були згодовані слизням та вовкам Миршавого Гілля. Він також згадав, що в Джінта'Алорі є яма, заповнена слизнями, а також вовче лігво. Обидва ці місця знаходяться неподалік вершини храму.", [4] = "Коли в мене будуть його останки, я віднесу їх до Яйо'джін і підготую до належного поховання.", [5] = "Мій любий братику, як я за тобою сумую...\n\nДякую тобі за допомогу, {ім'я}. В моїх очах ти {стать:справжній герой:справжня героїня}.", ["en"] = "Separation Anxiety", ["tasks"] = { ["Huntsman Malkhor's Bones"] = "кістки мисливця Малкгора", ["Huntsman Malkhor's Bones (Provided)"] = "кістки мисливця Малкгора (видано)", ["Huntsman Malkhor's Skull"] = "череп мисливця Малкгора", ["Huntsman Malkhor's Skull (Provided)"] = "череп мисливця Малкгора (видано)" } },
    [7850] = { [1] = "Темні посудини", [2] = "Тролі з племені Миршавого Гілля б'ються з надзвичайною жорстокістю. Це через нечисту магію підступної жриці Гекс.\n\nПо всьому Джінта'Алорі можна знайти темні посудини із забрудненою кров'ю. Ці посудини випромінюють нечисту магію безликого бога крові, яка надає сили племені Миршавого Гілля та водночас робить їх божевільними.\n\nВкради ці посудини та принеси їх мені, щоб я змогла очистити їх від нечистої магії та врешті-решт послабити владу бога крові.", [3] = "Голова Розірваний Бивень з селища Сколотий Бивень у Внутрішніх землях хоче, щоб ви добули 10 посудин із забрудненою кров'ю з Джінта'Алора. Поверніться до голови Розірваний Бивень коли виконаєте це завдання.", [4] = "Будь {стать:обережним:обережною} у борьбі з Миршавим Гіллям, {ім'я}. Їх розум затьмарений — вони б'ються на смерть.", [5] = "Темна енергія, якій підкорялися тролі Миршавого Гілля, ослабла. Принаймні поки що. Ми повинні завжди залишатися пильними в нашій боротьбі зі злом, навіть якщо підступна жриця буде знищена, її місце незабаром займе хтось інший.", ["en"] = "Dark Vessels", ["tasks"] = { ["Vessel of Tainted Blood"] = "посудина із забрудненою кров'ю", ["Vessel of Tainted Blood (Provided)"] = "посудина із забрудненою кров'ю (видано)" } },
    [78506] = { [1] = "Стихійне лихо", [2] = "Слухай, {ім'я}. Пошкодження, про яке я говорив раніше, виходить за межі Барона Акваніса. Я вже деякий час відчуваю певний неспокій у світі стихій. Боюся, що щось серйозно не так, і пошкоджування Барона Акваніса лише посилює мої підозри.\n\nЗнайди більше цих стихій, які страждають: тут, в Ясеневому Долині, та в сусідніх Кігтеподібних Горах. Принеси мені частинки їхньої сутності. Можливо, я зможу проаналізувати їх і почати розуміти природу їхньої люті.", [3] = "Зберіть частинки стихійної люті та принесіть їх Дже'неу Санкреа на форпості Зорам'гар, Ясенеділ.", [4] = "Елементалі дуже страждають, {ім'я}. Я мушу знати чому.", [5] = "Дякую, {ім'я}. Сподіваюся, це дасть деякі відповіді.", ["en"] = "Elemental Distress" },
    [78537] = { [1] = "Еліксир Прозріння", [2] = "Зібрані тобою частинки є важливою підказкою, {ім'я}, але нам також знадобиться духовне керівництво, якщо ми хочемо повністю зрозуміти ситуацію.\n\nЄ ритуал, який я часто практикую, для якого потрібен Еліксир Прозріння. Видіння, які він дарує, покажуть нам наступні кроки, які ми повинні зробити.\n\nЯ можу зварити еліксир з двох інших. Еліксир Водяного Дихання, щоб звільнити тіло, та Еліксир Мудрості, щоб відкрити розум.\n\nПринеси їх мені, і ми зможемо розпочати ритуал.", [3] = "Принесіть еліксир водного дихання та еліксир мудрості Дже'неу Санкреа на форпості Зорам'гар, Ясенеділ.", [4] = "Ви придбали еліксири компонентів, {ім'я}?", [5] = "Молодець. Тепер ритуал можна розпочати.", ["en"] = "Elixir of Insight" },
    [78561] = { [1] = "Еліксир Прозріння", [2] = "Еліксир готовий, {ім'я}. Спустися до багаття на пляжі та випий його. Прислухайся до видіння, даного тобі духами, і повернися до мене зі своїми знахідками.", [3] = "Випийте Еліксир Прозріння біля багаття на форпості Зорам'гар і побачте видіння, яке він вам дарує.\n\nНаданий предмет:", [4] = "Що тобі відкрили духи, {ім'я}?", [5] = "Квілбоар {клас} ... поневолює елементалів? Це, безумовно, тривожить.", ["en"] = "Elixir of Insight", ["tasks"] = { ["Elixir of Insight"] = "Еліксир Прозріння" } },
    [78575] = { [1] = "Гіржек", [2] = "Той вепр, якого ти бачив у своєму видінні; я вважаю, що це був Гірзек.\n\nЗемляне Кільце вже деякий час знає про грубу версію шаманізму вепрів. Однак ходять чутки, що деякі з них останнім часом роблять тривожні кроки. Гізрек — один із таких вепрів.\n\nЗ того, що ти бачив, схоже, що він поневолює елементалів, а не співпрацює з ними, як це зробили б ми з тобою. Безсумнівно, це завдає страждань елементальному плану.\n\nТи повинен зупинити його, {ім'я}. Заради блага шаманів та елементалів.", [3] = "Убийте Гірзека на Чорнотерновому хребті, що в Степах, і принесіть його посох Джен'неу Санкреї на форпост Зорам'гар, що в Ясенедолі.", [4] = "Дії Гіржека є образою шаманських звичаїв та самих стихій. Його потрібно зупинити.", [5] = "<Дженеу бере посох у руки.>\n\nТи зробив великий вчинок, {ім'я}. Мені полегшено дізнатися, що тортури Гірзека закінчилися. Хоча, боюся, він може бути лише симптомом більшої хвороби. Так багато елементалів Азероту досі кличуть у муках.\n\nБагато питань залишаються без відповіді; можливо, більше, ніж коли ми починали. Тим не менш, я дякую тобі за твою службу Земному Кільцю.", ["en"] = "Hirzek" },
    [786] = { [1] = "Перешкодити агресії Колкарів", [2] = "Говори тихше, {клас:к}. Кентаври клану Колкар розмістились одразу за пагорбом, на заході від скель Колкарів.\n\nМинулої ночі, поки вони полювали, я прокрався до їхнього поселення і дізнався, що ці брудні скоти планують трирівневу атаку на тролів та орків Дуротару.\n\nМи маємо перешкодити їхньому вторгненню. Можливо, тобі не забракне сил проникнути у скелі Колкарів і знищити ці плани?\n\nОстаннє, що я помітив — вони поділили їх на три частини і роздали трьом ватажкам.", [3] = "Лар Нишпорний Бивень з околиць селища Сен'джин хоче, щоб ви знищили 3 плани атаки кентаврів, що зберігаються серед скель Колкарів.", [4] = "Здається, кентаври вже стали постійною загрозою для Орди. Але ми не можемо спокійно спостерігати за їхніми намірами захопити наші землі.", [5] = "Орда, без сумніву, перемогла б у разі нападу кентаврів. Проте, запобігши такому нападу, ми уберегли наших могутніх воїнів від непотрібної різанини.\n\nКров ще проллється. Це настільки ж точно, як і те, що пустелю Танаріса покриває пісок.\n\nТи {стать:послужив:послужила} своєму народові на славу, {клас:к}.", ["en"] = "Thwarting Kolkar Aggression", ["tasks"] = { ["Attack Plan: Orgrimmar destroyed"] = "План атаки: знищення Орґріммара", ["Attack Plan: Sen'jin Village destroyed"] = "План атаки: знищено село Сен'джін", ["Attack Plan: Valley of Trials destroyed"] = "План атаки: Долина випробувань знищена" } },
    [7861] = { [1] = "Розшукується: Підступна жриця Гекс та її послідовники", [2] = "За наказом голови Розірваний Бивень, підступна жриця Гекс та її послідовники мають бути притягнуті до відповідальності!\n\nВеличезна нагорода пропонується тому, хто вб'є підступну жрицю Гекс і всю її елітну варту аман'сазі.", [3] = "Вам наказано вбити підступну жрицю Гекс і 20 вартових-аман'сазі з племені Миршавого Гілля. Після виконання цього завдання зверніться до голови Розірваний Бивень в селище Сколотий Бивень у Внутрішніх землях.\n\nПідступну жрицю Гекс і вартових-аман'сазі можна знайти на вершині Джінта'Алора у Внутрішніх землях.", [4] = "Ти {стать:приніс:принесла} новини з Джінта'Алора?", [5] = "Це дійсно нищівний удар по племені Миршавого Гілля. Ти будеш щедро {стать:винагороджений:винагороджена}, {ім'я:к}.", ["en"] = "Wanted: Vile Priestess Hexx and Her Minions", ["tasks"] = { ["Vile Priestess Hexx"] = "підступна жриця Гекс", ["Vile Priestess Hexx slain"] = "підступна жриця Гекс: убито", ["Vilebranch Aman'zasi Guard"] = "вартовий-аман'сазі Миршавого Гілля", ["Vilebranch Aman'zasi Guard slain"] = "вартовий-аман'сазі Миршавого Гілля: убито" } },
    [7862] = { [1] = "Вакансія: Капітан варти селища Сколотий Бивень", [2] = "Зі смертю капітана варти Малкгора посада капітана варти Сколотого Бивня знову відкрита. Якщо ви зацікавлені в цій посаді, виконайте наступні завдання та подайте заявку голові Розірваний Бивень:\n\nЗнищте берсерків Миршавого Гілля.\n\nЗнищте темних мисливців Миршавого Гілля.\n\nЗнищте кровопивць Миршавого Гілля.\n\nЗнищте пожирачів душ Миршавого Гілля.", [3] = "Перед вами стоїть завдання знищити 20 берсерків, 20 темних мисливців, 20 кровопивць та 20 пожирачів душ Миршавого Гілля.\n\nКоли виконаєте це завдання, поверніться до голови Розірваний Бивень в селище Сколотий Бивень у Внутрішніх землях", [4] = "Ти з приводу вакансії?", [5] = "Ти дійсно {стать:гідний кандидат:гідна кандидатка} на нову посаду, {ім'я:к}. Прийми цю дрібничку на знак нашої вдячності за свою наполегливу працю. Я розглядатиму всі заявки наступного року.", ["en"] = "Job Opening: Guard Captain of Revantusk Village", ["tasks"] = { ["Vilebranch Berserker"] = "берсерк Миршавого Гілля", ["Vilebranch Berserker slain"] = "берсерк Миршавого Гілля: убито", ["Vilebranch Blood Drinker"] = "кровопивця Миршавого Гілля", ["Vilebranch Blood Drinker slain"] = "кровопивця Миршавого Гілля: убито", ["Vilebranch Shadow Hunter"] = "темний мисливець Миршавого Гілля", ["Vilebranch Shadow Hunter slain"] = "темний мисливець Миршавого Гілля: убито", ["Vilebranch Soul Eater"] = "пожирач душ Миршавого Гілля", ["Vilebranch Soul Eater slain"] = "пожирач душ Миршавого Гілля: убито" } },
    [7866] = { [1] = "Базовий набір припасів авангарду", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в тіснині Пісні Війни.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в тіснині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть дружніми, а бинти — коли почесними.", ["en"] = "Outrider Basic Care Package" },
    [7867] = { [1] = "Стандартний набір припасів авангарду", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в тіснині Пісні Війни.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в тіснині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть дружніми, а бинти — коли почесними.", ["en"] = "Outrider Standard Care Package" },
    [7868] = { [1] = "Покращений набір припасів авангарду", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в тіснині Пісні Війни.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в тіснині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть дружніми, а бинти — коли почесними.", ["en"] = "Outrider Advanced Care Package" },
    [788] = { [1] = "Набивання руки", [2] = "Перш ніж перейти до серйозних завдань, треба тебе трошки розім'яти. Звичайно, я міг би одразу відправити тебе у Степи полювати на кодо, але, якщо чесно, ти {стать:корисніший нам живим, аніж мертвим:корисніша нам живою, аніж мертвою}.\n\nГадаю, для початку непогано згодяться й крапчасті кнури, яких ти знайдеш на північ звідси.", [3] = "Вбийте 10 крапчастих кнурів і поверніться до Ґорнека у Лігво.", [4] = "Я сподіваюсь ти не {стать:повернувся:повернулась} переконувати мене, що {стать:завершив:завершила} завдання, {Ім'я}? Ні, звичайно ні. Я про тебе кращої думки.", [5] = "Хммм, непогано, {Ім'я}. Але не треба одразу гоноритися. На своєму шляху ти зустрінеш ще багато значно сильніших супротивників, ніж кнури.\n\nТим не менш, ти {стать:показав:показала} себе добре, і у наступному випробуванні тебе чекає сутичка зі значно небезпечнішим супротивником. Тому тобі потрібен додатковий захист.", ["en"] = "Cutting Teeth", ["tasks"] = { ["Mottled Boar"] = "крапчастий кнур", ["Mottled Boar slain"] = "крапчастий кнур: убито" } },
    [789] = { [1] = "Жало скорпіда", [2] = "І могутньому воїну, і незграбному новачку однаково шкодить отруйне жало скорпіда. Ти знайдеш велику кількість цих тварюк на північному заході звідси. Дістань мені десять їхніх хвостів як доказ твоєї майстерності у битві.\n\nПротиотрута від скорпідів взагалі-то робиться з отрути, видобутої з їхніх жал. Ми тримаємо велику кількість цих лікувальних засобів під рукою для порятунку новачків на кшталт тебе…\n\nАле я певен, що тобі це взагалі не знадобиться, правда ж?", [3] = "Принесіть 10 хвостів скорпідів-робітників Ґорнеку у Лігво.", [4] = "Панцир скорпіда не настільки твердий, щоб стримати силу рішучого воїна. Бий сильно, не вагайся, і скорпіди стануть легкою здобиччю.", [5] = "Є важливий урок, який тобі потрібно винести з битви зі скорпідами. Будь-який ворог, незалежно від розміру, може забрати твоє життя. У запеклому бою будь-що може призвести до смерті.\n\nМені більше нічому тебе вчити, {ім'я:к}. Ти добре {стать:впорався:впоралась}, і я охоче спостерігатиму за твоїми подальшими досягненнями.", ["en"] = "Sting of the Scorpid", ["tasks"] = { ["Scorpid Worker Tail"] = "хвіст скорпіда-робітника", ["Scorpid Worker Tail (Provided)"] = "хвіст скорпіда-робітника (видано)" } },
    [78917] = { [1] = "Серце порожнечі", [2] = "Жахливий звір Аку'май лежить мертвим. Серед нутрощів та крові його розпухлого трупа захована величезна переливчаста перлина, що кишить непідробною енергією Порожнечі.", [3] = "Принесіть Перлину Чорної Непроглядності до Рунічного Тотему Башани в Громовій Утесі.", [4] = "{ім'я}, які новини з Блекфатома?", [5] = "Слуга Стародавніх Богів, Аку'май, мертвий. Цим вчинком ви зробили величезну послугу мешканцям Калімдора.\n\nПерлина також може бути ключем до набагато глибшого розуміння природи Порожнечі та її впливу на наш світ. Її необхідно негайно вивчити. Йдіть з Матір'ю-Землею, {ім'я}.", ["en"] = "The Heart of the Void", ["tasks"] = { ["Item #211452"] = "Товар №211452", ["Item #211452 (Provided)"] = "Товар №211452 (видано)" } },
    [78920] = { [1] = "Барон Акваніс", [2] = "Переможений водний елементаль залишив після себе дивну водяну кулю. Ви припускаєте, що цей об'єкт якимось чином живив енергією звіра. Усередині кулі хлюпає гнила на вигляд форма води. Сама куля здається невразливою до будь-якої фізичної сили.\n\nЯкщо хтось і може зрозуміти цей предмет, то це Дже'неу Санкреа з Земляного Кільця. Він знаходиться на форпості Зорам'гар Орди в Ясеневому Долині.", [3] = "Принесіть Дивну Водяну Кулю Дже'неу Санкреа на форпост Зорам'гар, Ясенеділ.", [4] = "А, знову привіт {ім'я}. Я просто читав хвилі на морі, як завжди. Що привело тебе на форпост?", [5] = "Це... це справжня знахідка, {ім'я}.\n\nКажете, ви отримали це від барона Акваніса в Блекфатомі? Барона Акваніса довго вважали зіпсованою стихійною силою; ця глобус доведе, що саме його зіпсувало. Хоча не буде дивно, якщо це виявиться Молот Сутінків, наші дослідження також покажуть, як вони це зробили.\n\nВи добре вчинили, що принесли це мені. Будь ласка, візьміть це разом з найтеплішими побажаннями від Земного Кільця.", ["en"] = "Baron Aquanis", ["tasks"] = { ["Item #211454"] = "Товар №211454", ["Item #211454 (Provided)"] = "Товар №211454 (видано)" } },
    [78922] = { [1] = "Лиходійство Чорноводних глибин", [2] = "Сила покинула мене. Потрібна твоя допомога!\n\nКолись давно це місце було великим храмом Елуни. Але нещастя призвело до руїн, коли корупція Старого Бога просочилася з-під землі та забруднила священний Місячний Колодязь.\n\nАку'Май, слуга Старого Бога, піднявся з вод.\n\nКультисти Сутінкового Молота об'єдналися з нагами, щоб зайняти ці землі. Культисти, очолювані Келрісом, приносять у жертву невинних Аку'Маю заради влади.\n\nУбийте Келріса та принесіть його голову до Башани в Громовій Утесі, {ім'я}, будь ласка.", [3] = "Принесіть голову Сутінкового Володаря Келріса до Башани Рунототем у Громовій Утесі.", [4] = "Хай Мати-Земля буде з тобою, {ім'я}.\n\nМир між землею та всіма її людьми має бути нашою метою. У неї є грандіозний план для природи, і ми всі маємо відіграти свою роль у цьому плані.", [5] = "Келріс деякий час уникав Срібного Світанку.\n\nДеякий час вони вважали його мертвим або зниклим безвісти.\n\nПоклавши край його правлінню, ви врятували життя багатьох невинних людей, {ім'я}.\n\nСлава Матері-Землі! Приносити в жертву іншого слузі Старого Бога заради особистої вигоди — це більш ніж огидно!\n\nВи зробили велику справу цього дня. Келріс був істотою зла і прагнув повернути світ до часів хаосу, поклоняючись таким істотам, як Старі Боги. Дякую, {ім'я}.", ["en"] = "Blackfathom Villainy" },
    [78927] = { [1] = "Відданість Старим Богам", [2] = "Цьому послідовнику Сутінкового Молота не можна дозволити завершити свій план. Сутінковий Молот не розуміє духів природи. Вони вірять у Стародавніх Богів – істот хаосу та руйнування, яких давно переможено. Цьому Лоргусу не можна дозволити досягти успіху. Ти мусиш зупинити його, {ім'я}. Я не можу зробити це сам – я надто слабкий.\n\nІди в Чорнопросвітні Глибини, знайди його та вбий. Повернися до мене сюди, в Зорам'гар, коли це буде зроблено.", [3] = "Убийте Лорґуса Джетта в Чорноводних глибинах, а потім поверніться до Дже'неу Санкрі в Ясенеділ.", [5] = "Дуже добре!! Дякую, {ім'я}. Можливо, ми не повністю зупинили Молот Сутінків, але принаймні ви запобігли ще одному з їхніх планів повернути владу Старих Богів.\n\nХто знає, які ще плани вони мають, але поки що ми можемо бути спокійні.", ["en"] = "Allegiance to the Old Gods", ["tasks"] = { ["Lorgus Jett slain"] = "Лорґус Джетт: убито" } },
    [790] = { [1] = "Саркот", [2] = "{Клас:к}! Я вже думав, що помру тут, і ніхто про це не дізнається. Полюючи на скорпідів, я перестрів особливо злючу тварюку. Накинувшись на нього, я зміг сильно пошкодити його клешню, перш ніж вона зімкнулась на моїй нозі.\n\nАле я не був готовий до жала, що увійшло у мої груди, прорізало плоть і пустило кров. Прошу, вбий заради мене цього скорпіда! Комусь треба відстояти мою честь! Я бився з ним на височині на півдні.", [3] = "Вбийте Саркота і принесіть його клешню Гана'зуа.", [4] = "Оох… Мій батько завжди казав, що я багато не досягну. Лежачи під деревом та відчуваючи, як життя просочується скрізь пальці, немов пісок, я розумію, що він мав рацію.\n\nПринаймні я хотів би померти, знаючи, що мій останній ворог також був убитий.", [5] = "Мого удару було недостатньо, щоб убити його, але я дивлюсь на шкоду, що завдав його клешні, і це наповнює мене невеликим почуттям гордості. Це маленьке досягнення — все, що залишиться після мене, якщо я помру. У такому стані... настільки короткий список моїх досягнень сповнює мене люттю.", ["en"] = "Sarkoth", ["tasks"] = { ["Sarkoth's Mangled Claw"] = "понівечена клешня Саркота", ["Sarkoth's Mangled Claw (Provided)"] = "понівечена клешня Саркота (видано)" } },
    [79007] = { [1] = "...і та записка, яку ти знайшов", [2] = "Слабке сяйво темніючих вугілля, ти натикаєшся на залишки нещодавньої пожежі.\nСеред розкиданих провізій ти знаходиш обгорілий записку.\n«Не все, що горить, втрачено. Знайди землю-близнюка, знайди це місце».", [3] = "Обвуглені залишки записки слугуватимуть вам єдиним орієнтиром.", [5] = "Коли ви натикаєтеся на залишки чергового обвугленого трупа, ваш погляд падає на послання, прикріплене до дерев'яної дошки.", ["en"] = "...and that note you found" },
    [79079] = { [1] = "Ділячись вірою", [2] = "Цей бідний жрець-Покинутий, здається, не може знайти лоа, який би з ним торгувався. Можливо, ти міг би замість цього дати йому благословення?", [3] = "Медитуйте про Лоа, а потім помоліться разом із колінами Покинутими, щоб поділитися своїми медитаціями.", [5] = "Нежить не дуже популярна серед лоа, але це добре з твого боку, що ти допомагаєш цьому. Спробуй виявити до них трохи співчуття, якщо зустрінеш ще когось, кому потрібна допомога, гаразд?", ["en"] = "Sharing the Faith" },
    [79080] = { [1] = "Ділячись вірою", [2] = "Цей троль розмірковує про смерть, але йому бракує певного... знайомства з цією темою. Будь ласка, допоможіть йому прояснити її розуміння.", [3] = "Медитуйте про нежить, а потім моліться разом з тролем, що стоїть на колінах, щоб поділитися своїми медитаціями.", [4] = "Так, {ім'я}?", [5] = "З мого досвіду, наші люди в кращому випадку є цікавими для решти Орди. Однак, обмін знаннями — це простий спосіб завоювати їхню довіру. Пам’ятайте про це під час своїх подорожей.", ["en"] = "Sharing the Faith" },
    [79094] = { [1] = "Уроки Та'зо", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "The Lessons of Ta'zo", ["tasks"] = { ["The Lessons of Ta'zo"] = "Уроки Та'зо" } },
    [79098] = { [1] = "Очистіть ліс!", [2] = "Цього вбито, але цей розлючений альянс продовжує боротьбу... що це за чари?", [3] = "Принесіть амулет Срібнокрилого Вартового Казрагору, Далековидному Провидцю, на базу Багаття в Ясенедолі.", [4] = "{ім'я}, які новини з фронту?", [5] = "Ці пси Альянсу все ще заважають нам збирати ресурси, необхідні для Орґріммара. Продовжуйте виганяти їх!\n\nЦей бойовий барабан Пісні Війни надихне вас боротися з ними з більшою рішучістю. Лок'тар Огар, {ім'я}!", ["en"] = "Clear the Forest!", ["tasks"] = { ["Silverwing Sentinel Charm"] = "Оберіг Срібнокрилого Вартового" } },
    [791] = { [1] = "Тягнути торбу", [2] = "Роки відплатили мені безпорадністю. Я вже не придатний до битв, але намагаюсь бути корисним в іншому.\n\nЯ сиджу тут, на височині, і дивлюся, чи не з'являться вороги. Але в міру того, як наші сили ростуть, мені все рідше і рідше доводиться сурмити в сигнальний ріг.\n\nЩоб проводити час з користю, я майструю речі для молодших сильніших воїнів, здатних боронити нашу вітчизну.\n\nЯ можу змайструвати тобі сумку для речей. Якщо тобі вона потрібна, принеси мені трохи полотна. Цю тканину частенько використовують люди та кентаври.", [3] = "Фурлу Презирному Чолу зі сторожової вежі Колючого Пагорба потрібно 8 уривків полотна.", [4] = "Я гордо бився пліч-о-пліч з воєвождем, коли ми лишень ступили на ці землі. Моє тіло усіяне шрамами битв.\n\nМоя сокира, мій бойовий клич захищали честь Орди, коли ми завдали поразки Архімонду в мерзенному, проте необхідному союзі з людьми та ельфами.\n\nАле зараз ця служба вартового дає мені нове відчуття користі.", [5] = "Надзвичайно, {Ім'я}. Цій торбі точно можна знайти застосування на полі бою.\n\nЯ вшановую твою силу та готовність померти в ім'я Орди!", ["en"] = "Carry Your Weight", ["tasks"] = { ["Canvas Scraps"] = "уривки полотна", ["Canvas Scraps (Provided)"] = "уривки полотна (видано)" } },
    [792] = { [1] = "Паскудні фамільяри", [2] = "Я вірю, що долина Випробувань навчить тебе багато чого нового, {стать:юний:юна} {клас:к}.\n\nМене відправили сюди, щоб я стала твоєю наставницею, але виявляється, у вас тут серйозні проблеми...\n\nГрупа, що зве себе Палаючим Лезом, оселилась у долині Випробувань. Вони ховаються в печері на північному сході, а їхні паскудні фамільяри вилазять з її нутра, спустошуючи все навколо.\n\nЩо ж, ось твоє перше завдання в боротьбі з Палаючим Лезом: перебий їх стільки, скільки зумієш, і, якщо виживеш, повертайся до мене.", [3] = "Убийте 12 паскудних фамільярів.\n\nПоверніться до Зурііти Далековзірної, що стоїть ззовні Лігва.", [4] = "Щоб проявити себе у битві з Палаючим Лезом, ти маєш спершу перемогти паскудних фамільярів. Повертайся, тільки-но закінчиш з цим.", [5] = "Гарна робота, {Ім'я}.\n\nХоч паскудні фамільяри й були лише ручними тваринками темних сил Палаючого Леза, твій успіх передує великим діянням.", ["en"] = "Vile Familiars", ["tasks"] = { ["Vile Familiar"] = "паскудний фамільяр", ["Vile Familiar slain"] = "паскудний фамільяр: убито" } },
    [7926] = { [1] = "Ярмарок Темного місяця", [2] = "Наближається ярмарок Темного місяця! Не забудьте випробувати всі її чудеса та хвилювання, коли вона прибуде до міста!\n\nЯкщо поквапитесь, ви зможете обміняти цей ваучер на безплатні призові купони! Просто віддайте ваучер Ґелвасу Хмурошлюзу на ярмарку.\n\nЗараз ярмарок проходить неподалік Громового Бескиду, в Мулґорі. Не упустіть свій шанс! Йдіть туди просто зараз!", [3] = "Віддайте ваучер на призовий купон Ґелвасу Пилошлюзу на ярмарку Темного місяця.", [4] = "Так, {стать:пане:пані}, чим я можу допомогти? У вас є ваучер для обміну?", [5] = "Вітаю на ярмарку Темного місяця! Це ваучер на П'ЯТЬ, так-так, цілих П'ЯТЬ призових купонів!\n\nЯк назбираєте більше — приходьте до мене та обміняйте їх на цінні призи. Чим більше купонів — тим більше виграєте призів! Вперед!", ["en"] = "The Darkmoon Faire", ["tasks"] = { ["Free Ticket Voucher"] = "ваучер на призовий купон", ["Free Ticket Voucher (Provided)"] = "ваучер на призовий купон (видано)" } },
    [793] = { [1] = "Розірвані союзи", [2] = "Печатку Землі утримують три рунічні камені, сховані у діамантовому, опаловому й аметистовому стовпах в ущелині Летлор. За допомогою знака Землі ти зможеш витягти рунні камені та зламати печатку Землі.\n\nАле будь {стать:обачним:обачною}, {ім'я}: з Чорнохлистом та Гематом не варто жартувати. Вбий їх і принести мені їхні кайдани.\n\nЩоб дістатися ущелини, подорожуй до східного краю Безплідних країв. Однак будь {стать:обережним:обережною}: в ущелині мешкає безліч дракончиків.", [3] = "Застосуйте знак Землі, щоб активувати діамантовий, опаловий і аметистовий стовпи, і витягнути рунічні камені.\n\nПомістіть рунні камені на печатку Землі, щоб звільнити Чорнохлиста і Гемата.\n\nУбийте драконів і принесіть Ґорну наручники Чорнохлиста, ланцюги Гемата і знак Землі.", [4] = "Мало хто з ворогів смертельніший за драконяче поріддя, і дуже мало було драконів, які билися так само люто, як Чорнохлист та Гемат.", [5] = "Крило чорних драконів продовжує об'єднуватися з відступниками — орками Чорнокаменю, і їх усіх потрібно провчити або усунути. Зі смертю Чорнохлиста та Гемата ми можемо звернути свою увагу на захід, у напрямку Чорноскельного шпиля.", ["en"] = "Broken Alliances", ["tasks"] = { ["Blacklash's Bindings"] = "наручники Чорнохлиста", ["Blacklash's Bindings (Provided)"] = "наручники Чорнохлиста (видано)", ["Chains of Hematus"] = "ланцюги Гемата", ["Chains of Hematus (Provided)"] = "ланцюги Гемата (видано)", ["Sign of the Earth"] = "знак Землі", ["Sign of the Earth (Provided)"] = "знак Землі (видано)" } },
    [79358] = { [1] = "Буря, земля й вогонь", [2] = "Затопити Тисячу Голок — це тобі не дрібниця, {ім'я}. Якби я сам не відчув люті стихій, нізащо б у це не повірив. Але ось ми тут.\n\nСвинобрази не перші, хто безвідповідально обертає стихії на зброю, і не останні. Якщо ми хочемо підготувати власний контрритуал, нам треба краще зрозуміти ці викривлені стихії. Візьми цю книгу. У ній описано багатьох мешканців Азероту й те, як вони практикують шаманізм.\n\nЯкщо зможеш у них повчитися, можливо, ми знайдемо рішення.", [3] = "Зберіть 5 викривлених тотемів вогню, 5 викривлених тотемів землі, 5 викривлених тотемів повітря та 5 викривлених тотемів води для Вейріка Громомолота у височині Араті.", ["en"] = "Storm, Earth, and Fire" },
    [79360] = { [1] = "Елементальна допомога", [2] = "Я чув про Гірзека та про варварські кроки, на які вони пішли, щоб маніпулювати стихіями.\n\n<Очі Рау блукають, він розмірковує над запискою, розмовляючи сам з собою вголос.>\n\nШторм лютуватиме, земля гримітиме, а приплив підніметься...\n\n<Очі Рау фокусуються на тобі та розширюються, коли він усвідомлює це.>\n\nВони, мабуть, використовують якесь жорстоке чаклунство, якого навчилися від Гірзека. Вони планують затопити каньйон і воскресити нас усіх у нежить.\n\nБоюся, що для досягнення своєї мети їм потрібні руйнівні стихійні сили.", [3] = "Хоча багато мешканців Тисячі Голок є нашими ворогами, ми не можемо стояти осторонь і спостерігати, як їх змиває. Записка була чіткою: вони планують зібрати армію нежиті після цього, що потенційно загрожує всім нам.\n\nМи погано підготовлені до боротьби з цим, але я чув про шамана зі Східних Королівств, який вправно володіє елементальним наповненням зброї, він може бути здатний допомогти.\n\nЗнайдіть цього шамана та попросіть його про допомогу.", [5] = "<Ти передаєш записку Бат'рі, яка перечитує її та ледь чутно хихикає.>\n\nАх, то це правда, друже... Я теж відчував сильне занепокоєння в елементарному плані, і це, мабуть, одна з причин.\n\nЩоб затопити всю Тисячу Голок, знадобиться великий шторм, і багато життів буде втрачено.\n\nГадаю, у мене є для тебе якась справа, але це буде нелегко.", ["en"] = "Elemental Aid" },
    [79361] = { [1] = "Сила вітру", [2] = "Щоб поширитися по всій землі, сильний шторм такого масштабу вимагатиме сили вітру. Яким би не був цей ритуал, ми повинні захистити вас від цієї стихії.\n\nЕлементалі вихору спустошили Пустощі та є одними з небагатьох стихій, здатних населяти цю землю. Принесіть мені їхню сутність.", [3] = "Зберіть 5 одиниць Вирової Есенції у елементалів виру в Пустощі та принесіть їх Бат'рі, Спостережливій за вітром, в Альтеракських горах.", [4] = "А, ти трохи запилений надворі?", [5] = "О так, так. Ми зараз готуватимемо.", ["en"] = "Power of da Wind" },
    [79364] = { [1] = "Простий контейнер", [2] = "Ти добре впорався, друже. Хоча я не знаю, з чим ти зіткнешся там, у Тисячі Голок, це точно забезпечить тобі певний захист від стихій, що загрожують твоїй землі.\n\n<Бат'ра починає перебирати свої речі, і ти можеш бачити, як він трохи розчарований, оскільки він шукає все швидше і швидше, перш ніж сором'язливо подивитися на тебе.>\n\nЩо ж, є ще дещо, що мені потрібно від тебе.\n\n<Його посмішка стає ширшою, перш ніж він знову заговорить.>\n\nЗдається, я загубив свої флакони з зіллям...", [3] = "Ти ж не думав, що я буду робити для тебе якусь божевільну зброю, чи не так? Ні, ні, ні, друже, це ж зілля захисту.\n\nБоротися з вогнем вогнем не завжди правильний підхід, друже.\n\nПринеси кришталеву склянку Бат'рі, Спостережливій за вітром, в Альтеракські гори.", [4] = "Нам потрібен більший флакон кришталевої прозорості, щоб вмістити ці елементи.", [5] = "Знав, що можу на тебе розраховувати.", ["en"] = "A Simple Container" },
    [79365] = { [1] = "З вітром під крилами", [2] = "Ось тобі, друже, зілля для боротьби зі шквалом — це те, що тобі потрібно. Випий це, щоб захиститися від стихії бурі, але пам'ятай, що воно триватиме недовго.\n\nА тепер іди, повертайся до своїх друзів, які потребують допомоги. Я більше нічим не можу тобі допомогти.", [3] = "Поверніться до Рау Скеляного Рау в Тисячі Голок на Пості Вільного Вітру.\n\nНаданий предмет:", [5] = "Наші вітролові знайшли щось, але вони не змогли підійти достатньо близько, щоб оцінити ситуацію. Чи змогли ви знайти щось, що могло б нам допомогти?", ["en"] = "With Wind Beneath Your Wings", ["tasks"] = { ["Item #212982"] = "Товар №212982" } },
    [79366] = { [1] = "Затишшя перед бурею", [2] = "Ми виявили незвично високу штормову активність, ізольовану на скелях на північному сході поблизу території Рейзорфена.\n\nВітер був надто сильним, щоб вершники могли підійти близько, а густий дощ не дозволяв бачити, що чекає на вас всередині ока. Але, можливо, з цим зіллям ви зможете прорватися на інший бік.\n\nПоговоріть з Найс, Майстром Вершників Вітру, коли будете готові. Вона надасть вам виверну, щоб вирушити в шторм.", [3] = "Вирушайте в око бурі та зіткніться з квілборами.", [4] = "Що ви знайшли?", [5] = "Гуркіт землі стих, і в глибині душі я знав, що ти нас врятував. Тобі наша вдячність, {ім'я}.\n\nБудь ласка, прийми один із цих подарунків як знак нашої вдячності.", ["en"] = "Calm Before the Storm", ["tasks"] = { ["Item #212982"] = "Товар №212982" } },
    [794] = { [1] = "Медальйон Палаючого Леза", [2] = "Ворожіння показали мені предмет великої сили, схований глибоко в надрах печери Палаючого Леза. Його охороняє зграя небезпечних тварюк і завіса чорної магії.\n\nЦей предмет зветься медальйоном Палаючого Леза, і твоїм наступним завданням буде знайти його і забрати з печери.\n\nАле будь {стать:обережним:обережною}, медальйон може бути у одного з членів Палаючого Леза. Якщо це так, то сила твого ворога перевищуватиме всіх фамільярів, з якими ти {стать:мав:мала} справу до цього.\n\nЙди, {Ім'я}. Ти знайдеш медальйон у печері, на північному заході.", [3] = "Принесіть медальйон Палаючого Леза Зурііті Далековзірній, що стоїть перед Лігвом.", [4] = "Твоє завдання виконане, {Ім'я}? Ти {стать:приніс:принесла} медальйон Палаючого Леза?", [5] = "Ти його {стать:дістав:дістала}! Чудово!\n\nТвої зусилля у нашій боротьбі проти Палаючого Леза зіграють ключову роль у викоріненні цього культу з долини Випробувань. Але боюсь, що це лише початок конфлікту...\n\nДопоки їм не видно кінця.", ["en"] = "Burning Blade Medallion", ["tasks"] = { ["Burning Blade Medallion"] = "медальйон Палаючого Леза", ["Burning Blade Medallion (Provided)"] = "медальйон Палаючого Леза (видано)" } },
    [79442] = { [1] = "Наздоганяємо", [2] = "Наші люди безмежно вам вдячні, але мені це око не потрібне. Можливо, той старий Вітроглядач міг би знайти його з користю?", [3] = "Поверніться до Бат'раха, Спостерігача за вітром, в Альтеракських горах і подивіться, чи зможе він використати Око Бурі.", [4] = "Ааа! Здається, ти повернувся цілим і неушкодженим. А тепер розкажи мені, як справилося зілля?\n\nДобре, що я в тебе повірив. Бо це зілля — просто чудовий удар, брате. Набагато смачніше, ніж ефективніше проти тих штормів.\n\nНу ж бо... не сердься на мене. Тобі потрібно було лише трохи підбадьорення. Все вийшло так, як і мало бути.\n\nАле оскільки ти тут... я помітив, який чудовий погляд ти тримаєш...", [5] = "Знаєш що. Більше жодних трюків, жодних ігор. У мене є дещо, що тебе зацікавить.\n\nОбміняй мені це око, і я дам тобі цю могутню чудову руну, яка готова навчити тебе новим трюкам.\n\nЩо скажеш?", ["en"] = "Catching Up", ["tasks"] = { ["Eye of the Tempest"] = "Око Бурі" } },
    [79483] = { [1] = "Викрадені ласощі Зимової Покрови", [2] = "Послухайте... не хочу руйнувати магію сезону, але Смокілід Пасовищам не завадила б допомога — така, яку ви, шукачі пригод, зазвичай надаєте.\n\nНам не вистачає важливої партії ласощів, яка поповнювала наші запаси на сезон, а тепер нам не вистачає агента Смокілід Пасовищ, якого ми відправили на пошуки! Будь ласка — востаннє повідомлялося про партію в горах Альтерак, і саме там наш чоловік вирушив її шукати.\n\nПеревірте, чи обидва там, цілими та неушкодженими!", [3] = "Знайдіть слідчого з Димчастих пасовищ, який зник безвісти у засніжених районах Альтеракських гір.", [5] = "І-і-ти мене м-ч-чуєш! Дякую м-д-підсумку!\n\nЯ не зовсім с-н-сніговик — мене н-н-звати Сакс, і я м-м-працюю в Орґріммарському м-м-відділенні Смоківудських Пасовищ... Мене м-м-послали сюди шукати м-м-зниклу посилку, коли на мене напала м-м-істота, яку я ніколи раніше не бачив!\n\nТак м-м-дуже холодно...", ["en"] = "Stolen Winter Veil Treats" },
    [79485] = { [1] = "Ти мерзенний...", [2] = "І-істота на ім'я \"Жахливий Грінч\" - це та, що м-м-вкрала нашу партію ласощів, {ім'я}. Але будь м-м-обережний! Це він м-м-перетворив мене на цю с-с-снігову кашу!\n\nТобі м-м-потрібна допомога, щоб м-м-зіткнутися з ним. Я бачив, як він м-м-блукав навколо, де єті; він м-м-напевно десь тут! М-м-знайди ласощі {ім'я}, віднеси їх м-м-назад до Пасовищ Димчастого Лісу в Орґріммарі та м-м-скажи їм, що мене м-м-потрібно розморозити!", [3] = "Знайдіть і поверніть Викрадені Ласощі Каймарду Мідному Шкрябі в Орґріммарі. Вважалося, що вони належать Гидкому Грінчу, якого можна знайти десь у засніжених регіонах Альтеракських гір.", [4] = "{ім'я} - наше Свято Зимової Покриви буде зіпсовано без цих ласощів для поповнення запасів! Сам Гракку пропустить можливість поділитися своїми смачними м'ясними пирогами з усіма хорошими хлопчиками та дівчатками цього сезону...", [5] = "Ви знайшли його! Ви врятували Свято Зимової Покрови на Пасовищі Димчастого Лісу!\n\nБідолашний Сакс... ми обов'язково відправимо туди команду та знайдемо спосіб його розморозити. Сподіваємося, що він повернеться вчасно до дня Свята; хоча йому доведеться надолужити пропущений час роботою. Однак, це було б неможливо, якби не ти!", ["en"] = "You're a Mean One..." },
    [79487] = { [1] = "Подяка від Пасовищ Димного Лісу!", [2] = "Ми, у Пасовища Димного Лісу, вдячні за повернення вкрадених ласощів, {ім'я}. За це ми хотіли б запропонувати вам особливий подарунок... подарований ні ким іншим, як самим Прадідом Зимою!\n\nБудь ласка, поговоріть з Прадідом Зимою, і він подарує вам ваш подарунок «Свято Зимової Покриви» від нас, у Пасовища Димного Лісу. З нашої ферми на вашу тарілку, це завжди корисні смаколики Пасовища Димного Лісу... звичайно ж, завдяки вам!", [3] = "Поговоріть з Прабатьком Зимою в Орґріммарі.", [5] = "Хо-хо, привіт, шукачу пригод!\n\nГобліни сказали мені, що ти заслужив особливий подарунок цього свята, і я радий його тобі вручити. Ось тобі — чудового Свята Зимової Покрови цього та кожного наступного сезону.", ["en"] = "A Smokywood Pastures' Thank You!" },
    [79495] = { [1] = "Метцен-північний олень", [2] = "ЛИХО! Оленя Метцена викрадено!\n\nМетцен — один із восьми оленів прадіда Зими, власність Смоківудських Пасовищ. Ми отримали не один, а ДВА листи з вимогою викупу від груп, які стверджують, що мають Метцена. Сезон свят розпочався, і ми прикуті до скриньки з грошима! Будь ласка, знайдіть Метцена та поверніть його нам!\n\nПеревірте листи з вимогою викупу, щоб знайти підказки, і посипте його цим оленячим пилом — це звільнить його від будь-яких пут!\n\nБудь ласка, поспішайте!", [3] = "Знайдіть оленя Метцена. Використайте надані вам нотатки, щоб отримати підказки щодо місця його утримання.\n\nКоли знайдете Метцена, візьміть Мішечок з оленячим пилом, щоб посипати його пилом; це має звільнити Метцена з пут полону.\n\nПоверніть Мішечок з оленячим пилом Каймарду Міднійщипці в Орґріммар, як тільки Метцена звільнять.\n\nНаданий предмет:", [4] = "{ім'я}! Ви його знайшли? Чи нотатки в моїй сумці дали вам достатньо інформації, щоб знайти Метцена? Мені дуже не хочеться думати про те, що ці жорстокі головорізи можуть з ним зробити... але ми ніяк не можемо дозволити собі заплатити такий непомірний викуп!", [5] = "Ти це зробив! Ура!\n\nМетцен повернувся до стайні Прадіда Зими — так, Метцен справді вміє літати — зовсім недавно! Пил спрацював чудово; я знав, що так і буде. Ти врятував Свято Зимової Покрови, а також Пасовища Димчастого Лісу від катастрофи. Дякую, {ім'я}.\n\nПослухай... завдяки тому, що ти тут зробив, я хочу, щоб ти це мав. Це щось ДУЖЕ особливе; якщо у тебе є маунтин, я думаю, тобі це дуже сподобається. Щасливого Зимового Покрову!", ["en"] = "Metzen the Reindeer" },
    [79502] = { [1] = "Герой дня", [2] = "Послухай... Я не маю тобі цього розповідати, але оскільки ти герой дня і все таке...\n\nУ цю пору року скрізь свіжий падуб, але він ніколи не довше зберігається. У нас є машина, яка консервує падуб — він ніколи не псується! Ми використовуємо її, щоб зробити свято гострим... і отримати прибуток влітку!\n\nЯ дозволю тобі скористатися консервантом, але тільки якщо ти майстер кулінарії. Тобі знадобиться трохи кам'яної солі та два, три, скажімо, п'ять золотих. Це принесе тобі гарну партію, яку ти зможеш залишити собі.", [3] = "Принесіть 1 сіль Глибокої Камені та 5 золотих монет до автомата сушарки для падуба, після чого ви отримаєте 5 консервованих падуба.", [4] = "Машина «Збереження падуба» спочатку виглядає як перегінний апарат, але уважний огляд виявляє деякі зміни, схожі на гоблінівські. Тим не менш, ваші кулінарні навички, здається, дозволяють вам зрозуміти, як працює машина.\n\nУ машині вже є свіжий падуб — вам просто потрібно надати трохи кам'яної солі та п'ять золотих монет, щоб машина запрацювала.", [5] = "Машина починає працювати з тихим гуркотом і невеликою кількістю пари. Невдовзі вона зупиняється, сповіщаючи про це ще один невеликий струмінь пари, що виривається з неї. Відчиняються дверцята, показуючи партію консервованого падуба!", ["en"] = "The Hero of the Day" },
    [79991] = { [1] = "Лісоматеріали Тернистої терики", [2] = "Нам дуже потрібні додаткові ресурси та підкріплення для підтримки наших цілей у басейні Араті. Відповідну деревину було особливо важко знайти, і ми були змушені шукати аж до Тернистої Долини, щоб знайти те, що нам потрібно. Принесіть мені партію деревини з Тернистої Долини, і ваша підтримка не залишиться непоміченою.", [3] = "Принесіть Смертеловителю Мортісу партію пиломатеріалів з Тернистої Терни.", [4] = "Ви принесли нам свіжі продукти?", [5] = "Дякуємо {клас}. Це допоможе нам змінити ситуацію в басейні Араті.", ["en"] = "Stranglethorn Lumber" },
    [8] = { [1] = "Угода пройдисвіта", [2] = "Гей, {стать:приятелю:приятелько}! Зроби-но послугу для парубка, що набив безтямних зомбі та павуків на все життя наперед?\n\nЯ маю тут лист, що потрібно доставити у Брілль... до корчмарки Рені якось-там... ЇЇ прізвище значення не має.\n\nУ будь-якому разі, це гарне затишне місце повне жертв чуми, що хочуть знайти своє місце у цьому світі. А ще це гарне місце для відпочинку. Тобі варто його відвідати... Зроби це, і я заплачу сповна.", [3] = "Доставте непідписаний лист корчмарці Рені в Тірісфальське перелісся.", [4] = "Так? Так? Що це?\n\nВідречені. У них, безумовно, величезний апетит. Почувайся, як удома.... так, знайди відпочинок для своїх втомлених кісток. Мене звати Рені, і я до твоїх послуг, якщо щось знадобиться.", [5] = "Га? Лист? Гарні новини! Я так чекала на звістку від моєї любої старої матусі зі Смертедзвону. Вона для мене просто, як свята. Цікаво, як вона там тримається.\n\nЩо? Занадто радісно? Не віриш мені, чи не так?\n\nНу що ж, тоді забирайся.... мені все одно, хто надіслав цей лист. Ну ж бо, забирайся звідси!\n\nПовертайся, коли зможеш витратити тут хоч трохи монети... трупарисько.\n\nНе встигнеш і оком моргнути, як ти повернешся сюди, щоб відпочити після якоїсь багатоденної пригоди чи ще чогось такого ж дурного.", ["en"] = "A Rogue's Deal", ["tasks"] = { ["Nondescript Letter"] = "непідписаний лист", ["Nondescript Letter (Provided)"] = "непідписаний лист (видано)" } },
    [80132] = { [1] = "Техновійни", [2] = "Технологія гномів – два роки тому її найчастіше використовували як жартівливу фразу. Часи точно змінилися. Тепер вони створили нову установку, яка краща за всі наші моделі шредерів разом узяті. Мені потрібні креслення, {ім'я}!\n\nНа жаль, креслення замкнені в сейфі біля мекженер Термоштепсель. Що ще гірше, комбінацію до сейфа знає лише мекженер Термоштепсель.\n\nЗробіть усе можливе, щоб отримати цю комбінацію, {ім'я}. Потім відкрийте цей сейф і принесіть ці креслення!", [3] = "Заберіть креслення бурової установки та безпечну комбінацію термоштекера у Гномреґана та принесіть їх Ноггу в Орґріммар.", [4] = "Я не бачу жодних креслень. Ти їх десь сховав на своєму тілі чи просто стоїш тут, щоб мене дратувати?", [5] = "Я знав, що ти зможеш це зробити, {ім'я}! Совік же мав сумніви.\n\nТепер, коли у нас є креслення, це лише питання часу, коли ми розберемося з усіма гномськими інноваціями, які були використані для створення установки, і зробимо їх гоблінськими інноваціями для наших нових моделей шредерів.", ["en"] = "Rig Wars" },
    [80133] = { [1] = "Старший інженер Скуті", [2] = "Щойно ми отримали звістку від Кернобі про новий гномський транспорт, ми зі Скуті почали працювати над Трансполіпортером 6000: найшвидшим і найнадійнішим способом до Гномреґану.\n\nНарешті він готовий до посадки пасажирів, {ім'я}. Якщо хочете спробувати, вирушайте до Буті-Бей і поговоріть зі Скуті на стоянці для вітряних вершників. Щоб дістатися до Буті-Бей, сідайте на човен з Ретчета.\n\nЗвичайно, ви завжди можете спробувати дістатися до Гномреґану через гори Дун-Морог, що кишать гномами!", [3] = "Поговоріть зі Скуті в Буті-Бей.", [5] = "Вона ж красуня, чи не так? Вершина технології транспортування гоблінів — вибухала лише з десяток разів.\n\nНе хвилюйся, {ім'я}, я її повністю полагодив. Вона не вибухне прямо на тебе — а якщо й вибухне, то це буде швидко та безболісно.", ["en"] = "Chief Engineer Scooty" },
    [80134] = { [1] = "До Гномреґану!", [2] = "Поки у вас є транспондер, все, що вам потрібно зробити, це наступити на майданчик, і вас телепортують до Гномреґану.\n\nВи можете відчути деякі незвичайні побічні ефекти, але жоден з них не повинен бути постійним... більше.\n\nЯ мало не забув найважливішу частину — повернення. Коли ви будете готові повернутися, просто наступіть на майданчик транспондера в Гномреґані!\n\nТепер потрібно відкалібрувати транспондер відповідно до вашого розміру та ваги.", [3] = "Зачекайте, поки Скуті відкалібрує транспондер Гоблінів.", [5] = "Готово! Коли будете готові, просто наступіть на килимок.", ["en"] = "Gnomer-gooooone!", ["tasks"] = { ["Goblin Transponder"] = "гоблінський транспондер" } },
    [80140] = { [1] = "Повернення персня", [2] = "Відкриваючи коробку, виготовлену Блискочист 5200, ви бачите блискучу каблучку! Одягнувши каблучку, ви відчуваєте, як магічна сила пронизує ваше тіло.\n\nВсередині каблучки знаходиться невеликий, але помітний відбиток печатки Орґріммара. Поруч із нею вигравірувані літери, але навіть після очищення видно лише перші три: «NOG...»\n\nЦе може означати або ініціали попереднього власника, або, можливо, ініціали майстра каблучки. Залиште каблучку... або знайдіть «NOG» - рішення, рішення...", [3] = "Ви можете або залишити собі каблучку, або знайти особу, відповідальну за відбиток та гравіювання на внутрішній стороні браслета.", [4] = "Можна було б подумати, що ми самі знайдемо спосіб перевершити цих брудних маленьких гномів. Я навіть б'юся об заклад, що вони взагалі вкрали у нас той снаряд! Ба, ці жирні, брудні... ем, так? Вам щось потрібно?", [5] = "Перстень з Гномреґану? Подивимося... не мій, але цікавий.\n\nЦя штука з Гномреґаном — з більш приємною купою тупих не могло статися. Роками вони були жартом, а тепер майже за одну ніч роблять кращі снасті, ніж ми?\n\nПерстень був у гномів Темного Заліза? Це ще цікавіше! Знаєте, можливо, гноми вкрали їхні божевільні плани големів і модифікували їх. Ці Темні Заліза, вони точно хотіли б якоїсь великої помсти. Це точно варто розслідувати.\n\nЗнаєте, щодо того перстня...", ["en"] = "Return of the Ring", ["tasks"] = { ["Item #216662"] = "Товар №216662" } },
    [80141] = { [1] = "Вдосконалення персня", [2] = "Ні, ні, ні — я не кажу раптом, що перстень мій. Зазвичай я цього не роблю, але твоя інформація про Темних Заліз була дуже корисною. Я вдосконалю твій перстень для тебе, краще, ніж той, хто зробив цю просту дрібничку, зміг би зробити. Мабуть, якийсь гном...\n\nЯкщо ти принесеш мені злиток срібла, моховий агат і тридцять срібних монет за мої зусилля, я додам до перстня срібно-агатову решітку, яка посилить магію всередині нього. Зацікавлені?", [3] = "Принесіть Ноггу в Орґріммар Блискуче золоте кільце, срібний злиток, моховий агат та 30 срібних монет.", [4] = "У вас є необхідні матеріали? Я не можу покращити цей дизайн без усього, що я просив.", [5] = "Ось твій перстень, кращий, ніж раніше. Ще раз дякую за інформацію про тих гномів із Темного Заліза. Це здається логічною підказкою щодо того, як цих гномів раптом охопило натхнення, подібне до гоблінів.", ["en"] = "Nogg's Ring Redo" },
    [80325] = { [1] = "Божевільний король", [2] = "Ви знаходите брудний, пошарпаний блокнот, повний пошарпаних схем та нотаток. Навіть після побіжного погляду стає зрозуміло, що будь-яке з цих творінь може бути використане для жахливого хаосу, якщо хтось колись виявиться настільки нерозумним, щоб їх створити.", [3] = "Принесіть інженерні нотатки Термоштепселя Ноггу в Долину Честі в Орґріммарі.", [4] = "Що ти мені приніс?", [5] = "<Очі Ноґґа спалахують, коли він читає збірку нотаток та схем>\n\nЯ збираюся підірвати стільки всього цим матеріалом.\n\nЧудова робота, {ім'я}. Думаю, це заслуговує на святкування!", ["en"] = "The Mad King", ["tasks"] = { ["Item #217351"] = "Товар №217351" } },
    [804] = { [1] = "Саркот", [2] = "Твої дії наповнюють моє серце відвагою. Я не здамся так просто! Я маю витримати!\n\nАле я все ще не зможу дістатись до Лігва без допомоги. Прошу, {Ім'я}, повернись туди і розкажи Ґорнеку про те, що зі мною сталося. Можливо, він зможе мені допомогти.", [3] = "Донесіть звістку про стан Гана'зуа Ґорнеку в Лігво.", [5] = "Судячи з опису тієї тварюки, я гадаю, ти говориш про Саркота! Не дивно, що Гана'зуа програв той бій. Я негайно направлю туди підмогу, можеш більше не хвилюватись про стан Гана'зуа.\n\nПопри все це, мене вразила звістка про твою перемогу над Саркотом. Це подвиг, яким можна пишатись, {Ім'я}. І те, що ти борешся за честь незнайомця, відсуваючи власні справи на задній план, підвищує твою гідність в сотню разів.", ["en"] = "Sarkoth" },
    [805] = { [1] = "Звітування у селище Сен'джин", [2] = "Твоя боротьба з Палаючим Лезом закінчена… в долині. Але я хочу, щоб ти {стать:доповів:доповіла} про свої знахідки.\n\nЙди в селище тролів Сен'джин і знайди майстра Ґадріна. Селище Сен'джин лежить на сході від долини Випробувань, праворуч від роздоріжжя.\n\nРозповіси Ґадріну про Палаюче Лезо, і про те, чого вони досягли в долині Випробувань. Дізнайся від нього, чи дійшли вони до селища Сен'джин.\n\nЙди, {Ім'я}, і не барись. Я боюсь, що зло, знайдене у печері Палаючого Леза, є вісником більшої загрози…", [3] = "Поговоріть з майстром Ґадріном у селищі Сен'джин.", [5] = "Хмм… Твоя розповідь прийшла у поганий час. Палаюче Лезо не помічали тут у Сен'джині, але їхнє зло проросло по узбережжю, на островах Ехо.\n\nОрки — друзі Тролів Темного Списа. Шановані друзі. Ми хочемо допомогти оркам, але… нам теж потрібна допомога.", ["en"] = "Report to Sen'jin Village" },
    [806] = { [1] = "Темний шторм", [2] = "Ми не можемо дозволити Палаючому Лезу закріпитись у Дуротарі! Ми мусимо знищити їх, перш ніж ця гниль розповсюдиться!\n\nЯ провів власне розслідування і дізнався, що чорнокнижник Палаючого Леза, гоблін Фіззл Темношторм, став табором посеред Громового кряжа на північному заході. Звідти він і його посіпаки-культисти поширюють хаос нашими землями.\n\nЗнайди, вбий Фіззла і принеси мені його кіготь!", [3] = "Принесіть кіготь Фіззла Орґнілу Духошраму у Колючий Пагорб.", [4] = "Ти {стать:знайшов:знайшла} Фіззла, {Ім'я}? Його разом із рештою Палаючого Леза потрібно раз і назавжди викурити з наших земель!", [5] = "Ага! Ти його {стать:дістав:дістала}!\n\nКлан може пишатися тобою, {Ім'я}. І саме завдяки тобі, Дуротар став вільним ще від одного прибічника злих сил.", ["en"] = "Dark Storms", ["tasks"] = { ["Fizzle's Claw"] = "кіготь Фіззла", ["Fizzle's Claw (Provided)"] = "кіготь Фіззла (видано)" } },
    [808] = { [1] = "Череп Міншини", [2] = "Я чую голос мого брата, Міншини, що зве мене у моїх снах.\n\nЙого забрав Залазейн, чорнокнижник з островів Ехо, що на сході. Мій брат мертвий.\n\nАле смерть не стала звільненням для нього. Дух Міншини заточений у пастці свого ж черепа, під дією магії Залазейна. У своїх снах я бачу його поряд із іншими черепами, у колі сили, на найбільшому з островів Ехо. Поки він знаходиться там, душа мого брата приречена на страждання.\n\nПрошу, {Ім'я}. Знайди коло і забери череп Міншини. Принеси мені його.\n\nЗвільни його!", [3] = "Дістаньте череп Міншини з кола сили на островах Ехо.\n\nПоверніть його майстру Ґадріну в селище Сен'джин.", [4] = "Череп мого брата у тебе, {Ім'я}? Він нарешті вільний?", [5] = "Дякую тобі, {Ім'я}. Ти {стать:врятував:врятувала} Міншину. Ти {стать:врятував:врятувала} душу мого брата від рабства!", ["en"] = "Minshina's Skull", ["tasks"] = { ["Minshina's Skull"] = "череп Міншини", ["Minshina's Skull (Provided)"] = "череп Міншини (видано)" } },
    [809] = { [1] = "Ак'Зелот", [2] = "З часів останньої великої війни, в якій Палаючий Легіон зазнав поразки, я шукаю джерела демонічної гнилі серед орків. І нашийник, що ти {стать:приніс:принесла}, підтверджує мої страхи.\n\nВін належить Палаючому Лезу, культу, що об'єднується навколо предмета, наповненого демонічною силою. Цей предмет зветься Демоновим Сім'ям, і знаходиться він у Степах, на вершині Зловісного Туману. Сім'я має бути знищене!\n\nЙди на Далекостежну заставу, що на кордоні зі Степами на заході, і поговори з моїм учнем, Ак'Зелотом. Він направить тебе далі.", [3] = "Поговоріть з Ак'Зелотом у Степах.", [5] = "Нііру хоче, щоб Демонове Сім'я було знищене, справді? Дивно…\n\nЩо ж, добре. Якщо він цього хоче, я розповім тобі як його позбутись.", ["en"] = "Ak'Zeloth", ["tasks"] = { ["Destroy the Demon Seed"] = "Знищити Насіння Демона" } },
    [81] = { [1] = "Доставка шипучки", [2] = "Я подбав про те, щоб нічого не пропало і закріпив у бочці не лише упаковану шипучку для Драна, а й додаткові пляшки для нього. Не те щоб я тепло ставився до Драна, але немає нічого гіршого, ніж розлита шипучка. Ось, тримай.\n\nА тепер віднеси цю бочку Драну Дрофферсу в його крамницю в Орґріммарі. І передавай мої вітання Мальтону. Скажи, що якщо він скучить за відмінною випивкою і чудовою компанією — ми будемо раді його візиту.", [3] = "Доставте бочку Драну Дрофферсу в Орґріммар.", [4] = "Якщо ти нічого не купуєш чи доставляєш — не марнуй мій час! Де моя шипучка?", [5] = "Що ж, давай поглянемо, що в цій бочці!\n\nТак, так, схоже, що все на місці. Ось твоя винагорода за доставку, гарна робота. Я отримаю вп'ятеро більше, коли продам її в таверну! Ха-ха!\n\nНу, а ці пляшки медової шипучки Внутрішніх земель прибережемо для особливих випадків. Треба спробувати змішати її з шампанським. Я назву це... медовим шампанським!", ["en"] = "Ripple Delivery", ["tasks"] = { ["Dran's Ripple Delivery"] = "вантаж шипучки для Драна", ["Dran's Ripple Delivery (Provided)"] = "вантаж шипучки для Драна (видано)" } },
    [812] = { [1] = "У пошуках зцілення", [2] = "{Ім'я}... ти дуже вчасно. Я лише сподіваюсь, що також зможу віддячити за твою швидкість.\n\nЯ був необережний, б'ючись з отрутохвостами, і один з них глибоко мене вжалив. Я відчуваю, як його отрута ослаблює мене, навіть від того, що ми розмовляємо. Мені залишилось жити десь з годину. Але щоб вижити, мені треба твоя допомога…\n\nКор'ґхан в Орґріммарі знає набагато більше про протиотруту. Знайди його… і поквапся, {Ім'я}. Я довго не протримаюсь. Він має бути у Розколині Тіні.", [3] = "Знайдіть Кор'ґхана в Орґріммарі та отримайте протиотруту з отрутохвоста. Потім принесіть протиотруту Рінаґу на північному заході Дуротару.", [4] = "Я навіть радий, що не можу повернутись до селища Сен'джин в цьому стані. Мою слабкість і тупість обов'язково б висміяли там.", [5] = "{Ім'я}, ти {стать:врятував:врятувала} моє життя. Дякую тобі.\n\nБудь ласка, візьми це. Якщо не зможеш виручити за це кілька монет, то, сподіваюсь, воно хоча б допоможе тобі у твоїх мандрівках. З того, що ти кажеш, я все одно не зможу цим користуватись найближчим часом. Кор'ґхан прожене мене через купу своїх ритуалів, перш ніж я доведу свою гідність. Далі убивати кабанів, далі збирати хвости скорпідів… <зітхає>", ["en"] = "Need for a Cure", ["tasks"] = { ["Venomtail Antidote"] = "протиотрута з отрутохвоста", ["Venomtail Antidote (Provided)"] = "протиотрута з отрутохвоста (видано)" } },
    [8120] = { [1] = "Битва за низину Араті!", [2] = "Без сумніву, ти вже {стать:чув:чула}, що Ліга Аратора відправляє велику кількість військ в низину Араті. Жадаючи їжі та припасів, ці дурні з Альянсу хочуть захопити та контролювати тамтешні джерела ресурсів. Ми повинні показати їм, що Араті більше ніколи не буде домом для людей!\n\nВирушай в низину Араті та напади на шахту, лісопильню, кузню та стайню. Зірви ворожі прапори, тим самим проголосивши ці території підконтрольними Орді.\n\nІди, {ім'я:к}. Доповіси мені, коли завдання буде виконано.", [3] = "Нападіть на шахту, лісопильню, кузню та стайню в низині Араті, після чого поверніться до повелительки смерті Двайр в Молотобій.", [5] = "Розвідник Труїтелів доповів про твої успіхи, {ім'я:к}. Гарна робота.\n\nЩоб перемогти в битві за низину Араті, нам потрібно бути завжди пильними та придушувати будь-які спроби розширення територій Альянсу. Виконуй це, і тоді перемога Орди гарантована.", ["en"] = "The Battle for Arathi Basin!", ["tasks"] = { ["Blacksmith Assaulted"] = "Напад на коваля", ["Blacksmith Assaulted (Provided)"] = "Напад на коваля (видано)", ["Blacksmith Assaulted slain"] = "Напад на коваля: убито", ["Lumber Mill Assaulted"] = "Напад на лісопильний завод", ["Lumber Mill Assaulted (Provided)"] = "Напад на лісопильний завод (видано)", ["Lumber Mill Assaulted slain"] = "Напад на лісопильний завод: убито", ["Mine Assaulted"] = "Шахта піддана нападу", ["Mine Assaulted (Provided)"] = "Шахта піддана нападу (видано)", ["Mine Assaulted slain"] = "Шахта піддана нападу: убито", ["Stable Assaulted"] = "Стайня піддалася нападу", ["Stable Assaulted (Provided)"] = "Стайня піддалася нападу (видано)", ["Stable Assaulted slain"] = "Стайня піддалася нападу: убито" } },
    [8121] = { [1] = "Зайняти чотири бази", [2] = "{ім'я:к}, поки вирують битви за низину Араті, новини про твої подвиги розійшлись по різних куточках наших земель. Ми високо цінуємо тебе, а це дає мені впевненість у тому, що ти зможеш виконати завдання, яке я маю для тебе.\n\nНастав час відправити послання в Лігу Аратора. Ми повинні дати їм зрозуміти, що їхні позиції в Араті слабкі, і втратити їх дуже легко. Ми доведемо їм це, взявши під контроль одночасно чотири стратегічні точки в низині Араті.\n\nДосягни успіху, {ім'я:к}, і ти заслужиш велику повагу серед Труїтелів.", [3] = "Візьміть під контроль одночасно чотири бази в низині Араті, після чого поверніться до повелительки смерті Двайр в Молотобій.", [4] = "Повертайся до низини Араті, {ім'я:к}, і виконай те, за чим тебе відправили! Захопи та утримай чотири бази!", [5] = "Гарна робота, {ім'я:к}! Твої звершення в низині Араті були нелегкими, і твої успіхи заслуговують на похвалу. Ліга Аратора, мабуть, оговтується від останніх сутичок в низині, зализує рани та, будемо сподіватися, подумує, чи варто вести цю війну далі.", ["en"] = "Take Four Bases", ["tasks"] = { ["Hold Four Bases."] = "Утримуйте чотири бази." } },
    [8122] = { [1] = "Зайняти п'ять баз", [2] = "Важко помітити, наскільки глибоко ми занурилися в конфлікт, але наші шпигуни повідомляють про послаблення рішучості Ліги Аратора. Ми повинні скористатися цим і завдати їм жорстокого удару! Повертайся в низину Араті та бийся проти наших ворогів. Вбивай їх і візьми під контроль всі п'ять стратегічних баз! Нехай їхні солдати з криками біжать з поля бою та стікають кров'ю, і нехай розповіді про твою жорстокість лунають з їхніх тремтячих губ.\n\nЗроби це і здобудь велику перемогу для Труїтелів.", [3] = "Візьміть під контроль одночасно п'ять баз в низині Араті, після чого поверніться до повелительки смерті Двайр в Молотобій.", [5] = "Крики твоїх ворогів можна було почути навіть звідси, {ім'я:к}. Мені навіть трохи шкода їх. Трохи, але це нічого не значить.\n\nБез сумніву, ти маєш велике значення для Труїтелів. Твої подвиги в низині Араті вражають, а звістки про них лунають в покоях Варіматраса... і аж самої Темної Леді.", ["en"] = "Take Five Bases", ["tasks"] = { ["Hold Five Bases."] = "Утримуйте п'ять баз." } },
    [813] = { [1] = "У пошуках протиотрути", [2] = "Отрутохвости — одні з найсмертельніших скорпідів Дуротару. Рінаґ вчинив немудро, полюючи на них без протиотрути, але осуд — це останнє, що йому потрібно.\n\nПринеси мені декілька отруйних залоз отрутохвостів, що водяться біля воріт Орґріммара, і я зроблю для Рінаґа протиотруту.\n\nПоспіши, {Ім'я}. Один з наших потребує твоєї допомоги.", [3] = "Принесіть 4 отруйні залози отрутохвостів Кор'ґхану в Орґріммар.", [4] = "Пам'ятай, неважливо на кого ти полюєш, ти маєш уважно вивчити його і зрозуміти його поведінку. Це знання може врятувати твоє життя.", [5] = "Ось протиотрута, {Ім'я}. Віднеси її Рінаґу так швидко, як можеш, і будь {стать:обережний:обережна}.", ["en"] = "Finding the Antidote", ["tasks"] = { ["Venomtail Poison Sac"] = "отруйна залоза отрутохвоста", ["Venomtail Poison Sac (Provided)"] = "отруйна залоза отрутохвоста (видано)" } },
    [815] = { [1] = "Розбити кілька яєць", [2] = "Оува! Я ледь не забув приготувати сніданок.\n\n{Ім'я}, збирайся і принеси мені декілька яєць хвостохлястів. Мені потрібно щонайменше три, якщо я захочу приготувати достатньо їжі на завтра.\n\nКривавопазурові хвостохлясти можуть бути агресивними і відчайдушно захищають свою кладку аж до самої смерті. Інколи, в цілях захисту, вони закопують яйця занадто глибоко в землю, але якщо ти підеш прямо на острови Ехо, що на південному сході від селища Сен'джин, то зможеш з легкістю побачити достатню їх кількість довкола.", [3] = "Принесіть 3 яйця хвостохлястів кухарю Торці в Колючому Пагорбі.", [4] = "Сніданок, обід, вечеря! Кому яка різниця, що подають? Комусь все одно треба все це готувати — точніше, мені!", [5] = "Ти може й {стать:слабак:слабка}, але хоча б не незграба, {Ім'я}.\n\nОсь, візьми це і вали з моїх очей. Мені треба готувати.", ["en"] = "Break a Few Eggs", ["tasks"] = { ["Taillasher Egg"] = "яйце хвостохляста", ["Taillasher Egg (Provided)"] = "яйце хвостохляста (видано)" } },
    [8150] = { [1] = "Вшанування героя", [2] = "Під час Свята врожаю Азерота, ми висловлюємо шану героям за жертви, що вони принесли заради нас. Орда визнає багатьох героїв, але ніхто не уособлює жертовність так, як Ґром Пеклокрик.\n\nДопоможи нам вшанувати Ґрома, віднеси ці підношення до його пам'ятника в каньйон Погибелі демона, що в Ясенедолі. Поклади їх до пам'ятника, а потім повертайся до мене. Я буду тут лише до кінця фестивалю, тому не гай часу та вшануй Ґрома.", [3] = "Відправляйтеся до пам'ятника Ґрому в каньйон Погибелі демона, що в Ясенедолі та покладіть підношення до підніжжя пам'ятника. Поверніться до Явніра Нашака поблизу Орґріммара до завершення Свята врожаю.", [4] = "Ти {стать:був:була} біля пам'ятника Ґрому і {стать:поклав:поклала} підношення?\n\nМісце, де стоїть пам'ятник, все ще знаходиться під впливом Палаючого Легіону. Якщо ти недостатньо {стать:досвідчений мандрівник:досвідчена мандрівниця}, будь {стать:обережний:обережна}, коли опинишся там.", [5] = "Повне ім'я Ґрома — Ґроммаш — означає \"серце велетня\". Воістину, йому знадобилося серце велетня, щоб самотужки вистояти проти Маннорота! Правильно сказав воєвождь, що прокляття орків почалося з Ґрома, і Ґром з ним покінчив! Доречно, що його жертва — і, можливо, спокута — стала тим, з чого почалась сьогоднішня Орда.\n\nДякую, {ім'я}. Сьогодні ти {стать:віддав:віддала} шану великому герою, вшанувавши його дух і дух Свята врожаю.", ["en"] = "Honoring a Hero", ["tasks"] = { ["Grom's Tribute"] = "підношення Ґрому" } },
    [816] = { [1] = "Зниклий, але не забутий", [2] = "{Ім'я}, прошу, ти допоможеш мені? Мій син Крон пішов полювати декілька днів тому, і досі не повернувся. Він пішов на захід у сторону Степів полювати на кроколісків вздовж Південнолютної річки. Я боюсь найгіршого.\n\nХоч він і був сильним, але його вперта гордість приводила його до небезпек. Я попереджала його про лють і силу кроколісків. Але він лише розізлився і кинувся геть.\n\nЯкщо ти не зможеш знайти його, принаймні дізнайся, що з ним сталось… Навіть якщо тобі доведеться розрізати живіт кожного з кроколісків на берегах Південнолютної.", [3] = "Дізнайтесь, що сталось з Кроном і дайте знати Міші Тор'крен на фермі на північному заході від Колючого Пагорба.", [4] = "Я молюсь, щоб Крон повернувся, але майже впевнена, що вже знаю його долю.", [5] = "Ох, мій сину… мій прекрасний сину.\n\nНевпевнена щодо долі мого сина, я мучилась з того дня, як він пішов. Тепер, знаючи, що з ним сталось, я нарешті можуть почати оплакувати його.\n\nДякую тобі, {Ім'я}. Будь ласка, візьми це, я хотіла віддати Крону як подарунок, коли він повернеться. Тепер, знаючи, що він мертвий, я не можу на це дивитись.", ["en"] = "Lost But Not Forgotten", ["tasks"] = { ["Kron's Amulet"] = "амулет Крона", ["Kron's Amulet (Provided)"] = "амулет Крона (видано)" } },
    [8169] = { [1] = "Битва за низину Араті!", [2] = "Без сумніву, ти вже {стать:чув:чула}, що Ліга Аратора відправляє велику кількість військ в низину Араті. Жадаючи їжі та припасів, ці дурні з Альянсу хочуть захопити та контролювати тамтешні джерела ресурсів. Ми повинні показати їм, що Араті більше ніколи не буде домом для людей!\n\nВирушай в низину Араті та напади на шахту, лісопильню, кузню та стайню. Зірви ворожі прапори, тим самим проголосивши ці території підконтрольними Орді.\n\nІди, {ім'я:к}. Доповіси мені, коли завдання буде виконано.", [3] = "Нападіть на шахту, лісопильню, кузню та стайню в низині Араті, після чого поверніться до повелительки смерті Двайр в Молотобій.", [5] = "Розвідник Труїтелів доповів про твої успіхи, {ім'я:к}. Гарна робота.\n\nЩоб перемогти в битві за низину Араті, нам потрібно бути завжди пильними та придушувати будь-які спроби розширення територій Альянсу. Виконуй це, і тоді перемога Орди гарантована.", ["en"] = "The Battle for Arathi Basin!", ["tasks"] = { ["Blacksmith Assaulted"] = "Напад на коваля", ["Blacksmith Assaulted (Provided)"] = "Напад на коваля (видано)", ["Blacksmith Assaulted slain"] = "Напад на коваля: убито", ["Lumber Mill Assaulted"] = "Напад на лісопильний завод", ["Lumber Mill Assaulted (Provided)"] = "Напад на лісопильний завод (видано)", ["Lumber Mill Assaulted slain"] = "Напад на лісопильний завод: убито", ["Mine Assaulted"] = "Шахта піддана нападу", ["Mine Assaulted (Provided)"] = "Шахта піддана нападу (видано)", ["Mine Assaulted slain"] = "Шахта піддана нападу: убито", ["Stable Assaulted"] = "Стайня піддалася нападу", ["Stable Assaulted (Provided)"] = "Стайня піддалася нападу (видано)", ["Stable Assaulted slain"] = "Стайня піддалася нападу: убито" } },
    [817] = { [1] = "Корисна здобич", [2] = "Більшість шкур, які ми використовуємо, добуваються з дуротарських тигрів, {Ім'я}. Ковдри, обладунки, намети: є багато причин, чому ми полюємо на цих звірів, і так само багато причин, чому ми не заважаємо поширенню їхньої популяції.\n\nТа настав час прорідити отару, так би мовити. Наші ряди ростуть і наші потреби починають перевищувати наші запаси. Мені потрібні шкури, щоб підготувати більше речей.\n\nПринеси мені 4 шкури дуротарських тигрів і я тобі віддячу. Ти знайдеш їх на островах на півдні звідси.", [3] = "Принесіть 4 шкури дуроторського тигра Вел'ріну Іклу в селище Сен'джин.", [4] = "Я пам'ятаю моє перше полювання на тигрів, {Ім'я}. Я обрав найбільший з островів Ехо, чудово затаївся у тіні листя майже на весь день… видивляючись… очікуючи.\n\nМої м'язи були напружені, я був готовий до удару. Коли тигр нарешті вхопив наживку, це була одна з моїх найславетніших перемог.", [5] = "Я задоволений, {Ім'я}. З твоєю допомогою наш народ буде захищений і не замерзне, коли зміниться пора року.\n\nДякую тобі.", ["en"] = "Practical Prey", ["tasks"] = { ["Durotar Tiger Fur"] = "хутро дуротарського тигра", ["Durotar Tiger Fur (Provided)"] = "хутро дуротарського тигра (видано)" } },
    [8170] = { [1] = "Битва за низину Араті!", [2] = "Без сумніву, ти вже {стать:чув:чула}, що Ліга Аратора відправляє велику кількість військ в низину Араті. Жадаючи їжі та припасів, ці дурні з Альянсу хочуть захопити та контролювати тамтешні джерела ресурсів. Ми повинні показати їм, що Араті більше ніколи не буде домом для людей!\n\nВирушай в низину Араті та напади на шахту, лісопильню, кузню та стайню. Зірви ворожі прапори, тим самим проголосивши ці території підконтрольними Орді.\n\nІди, {ім'я:к}. Доповіси мені, коли завдання буде виконано.", [3] = "Нападіть на шахту, лісопильню, кузню та стайню в низині Араті, після чого поверніться до повелительки смерті Двайр в Молотобій.", [4] = "Ти ще не {стать:виконав:виконала} своє завдання, {ім'я:к}. Напади на кожну з чотирьох баз, про які я казала, і після цього повертайся до мене!", [5] = "Розвідник Труїтелів доповів про твої успіхи, {ім'я:к}. Гарна робота.\n\nЩоб перемогти в битві за низину Араті, нам потрібно бути завжди пильними та придушувати будь-які спроби розширення територій Альянсу. Виконуй це, і тоді перемога Орди гарантована.", ["en"] = "The Battle for Arathi Basin!", ["tasks"] = { ["Blacksmith Assaulted"] = "Напад на коваля", ["Blacksmith Assaulted (Provided)"] = "Напад на коваля (видано)", ["Blacksmith Assaulted slain"] = "Напад на коваля: убито", ["Lumber Mill Assaulted"] = "Напад на лісопильний завод", ["Lumber Mill Assaulted (Provided)"] = "Напад на лісопильний завод (видано)", ["Lumber Mill Assaulted slain"] = "Напад на лісопильний завод: убито", ["Mine Assaulted"] = "Шахта піддана нападу", ["Mine Assaulted (Provided)"] = "Шахта піддана нападу (видано)", ["Mine Assaulted slain"] = "Шахта піддана нападу: убито", ["Stable Assaulted"] = "Стайня піддалася нападу", ["Stable Assaulted (Provided)"] = "Стайня піддалася нападу (видано)", ["Stable Assaulted slain"] = "Стайня піддалася нападу: убито" } },
    [8171] = { [1] = "Битва за низину Араті!", [2] = "Без сумніву, ти вже {стать:чув:чула}, що Ліга Аратора відправляє велику кількість військ в низину Араті. Жадаючи їжі та припасів, ці дурні з Альянсу хочуть захопити та контролювати тамтешні джерела ресурсів. Ми повинні показати їм, що Араті більше ніколи не буде домом для людей!\n\nВирушай в низину Араті та напади на шахту, лісопильню, кузню та стайню. Зірви ворожі прапори, тим самим проголосивши ці території підконтрольними Орді.\n\nІди, {ім'я:к}. Доповіси мені, коли завдання буде виконано.", [3] = "Нападіть на шахту, лісопильню, кузню та стайню в низині Араті, після чого поверніться до повелительки смерті Двайр в Молотобій.", [5] = "Розвідник Труїтелів доповів про твої успіхи, {ім'я:к}. Гарна робота.\n\nЩоб перемогти в битві за низину Араті, нам потрібно бути завжди пильними та придушувати будь-які спроби розширення територій Альянсу. Виконуй це, і тоді перемога Орди гарантована.", ["en"] = "The Battle for Arathi Basin!", ["tasks"] = { ["Blacksmith Assaulted"] = "Напад на коваля", ["Blacksmith Assaulted (Provided)"] = "Напад на коваля (видано)", ["Blacksmith Assaulted slain"] = "Напад на коваля: убито", ["Lumber Mill Assaulted"] = "Напад на лісопильний завод", ["Lumber Mill Assaulted (Provided)"] = "Напад на лісопильний завод (видано)", ["Lumber Mill Assaulted slain"] = "Напад на лісопильний завод: убито", ["Mine Assaulted"] = "Шахта піддана нападу", ["Mine Assaulted (Provided)"] = "Шахта піддана нападу (видано)", ["Mine Assaulted slain"] = "Шахта піддана нападу: убито", ["Stable Assaulted"] = "Стайня піддалася нападу", ["Stable Assaulted (Provided)"] = "Стайня піддалася нападу (видано)", ["Stable Assaulted slain"] = "Стайня піддалася нападу: убито" } },
    [818] = { [1] = "Розчинник духу", [2] = "Хоч мої очі мене підводять, я все ще досить добре бачу. Дедалі частіше я маю покладатись на свої алхімічні здібності для допомоги з магією, що колись так просто мені давалась. Але я відмовляюсь брати учня — досі не натрапляв на гідного троля чи орка!\n\nТи {стать:гідний:гідна}? Звісно… Звісно ж ти думаєш, що так….\n\nДістанеш для мене дещо?\n\nМені потрібні непошкоджені очі макрури і фіали зі слизом повзунів. Ти знайдеш їх у будь-якої макрури чи повзуна в Дуротарі. Принесеш, тоді побалакаємо.", [3] = "Принесіть 4 неушкоджених ока макрури та 8 фіалів зі слизом повзунів до майстра Ворнала в селищі Сен'джин.", [4] = "Час — справжнє випробування сили та волі. Втратиш терпіння чи піддасися слабкостям, і справжнє нутро покаже себе.", [5] = "Дуже добре, {стать:юначе:дівчинко}… Дійсно дуже добре.", ["en"] = "A Solvent Spirit", ["tasks"] = { ["Crawler Mucus"] = "слиз повзуна", ["Crawler Mucus (Provided)"] = "слиз повзуна (видано)", ["Intact Makrura Eye"] = "неушкоджене око макрури", ["Intact Makrura Eye (Provided)"] = "неушкоджене око макрури (видано)" } },
    [819] = { [1] = "Порожня діжка Ченя", [2] = "Невелика табличка на одному з боків діжки говорить:\n\n\"Чень Бурехміль-\n\nНехай твій дух буде сповненим, а кухоль завжди наповненим.\"", [3] = "Знайдіть когось, хто володіє інформацією про порожню діжку Ченя.", [4] = "Так?", [5] = "А щоб я...\n\nЦе одна з діжок Ченя Бурехміля. Він колись давно мандрував разом із Рексаром. Я не бачив і не чув про нього вже з вік кодо. Вельми вдячний тобі за те, що {стать:приніс:принесла} мені це барильце, {Ім'я}.", ["en"] = "Chen's Empty Keg", ["tasks"] = { ["Chen's Empty Keg"] = "порожня діжка Ченя", ["Chen's Empty Keg (Provided)"] = "порожня діжка Ченя (видано)" } },
    [81960] = { [1] = "Очищення повітря", [2] = "Нерозбірливі нотатки обгорнуті навколо якоїсь сапти. Вона каламутніша, ніж ти пам'ятаєш, але, здається, злита з тією ж магією. Тобі ніяково дивитися на неї, ніби вона була заплямована якимось нечесним впливом. Поруч має бути Скеля Духів, хоча ти не знаєш жодного святого місця поблизу. Можливо, ти зможеш докопатися до суті цієї дивності, знайшовши її.", [3] = "Знайдіть заражену Камінь Духів та випийте Каламутну Повітряну Сапту.\n\nНаданий предмет:", [5] = "Ти повертаєш життя. Ти достатньо сильний. Зрозумій... так... ти зупиняєш корупцію.\n\nШукай і зупиняй корупцію.", ["en"] = "Clarifying Air", ["tasks"] = { ["Murky Air Sapta"] = "Каламутне повітря Сапта" } },
    [81968] = { [1] = "Відповідаючи на виклик Air", [2] = "Ти достатньо сильний. Зрозумій... так... ти зупиняєш псування.\n\n<Елементальне перетворення відчуває дискомфорт.>\n\nЕлементи у Фераласі. Використай Есенцію, щоб знайти Святилище.\n\nВізьми фрагмент. Допоможе з псуванням.", [3] = "Зберіть 3 Елементальні Есенції з водних елементалів на Забутому Березі навпроти острова Сардор у Фераласі та поєднайте їх з Фрагментом Повітря, щоб викликати допомогу в зіпсованому святилищі.\n\nНаданий предмет:", [4] = "Ви знайшли святиню. Уточніть, що таке святиня.", [5] = "Корупція... уточніть зараз. Потрібна допомога. Можливо, інші... так... інші елементи допоможуть.", ["en"] = "Answering Air's Call", ["tasks"] = { ["Fragment of Air"] = "Фрагмент повітря" } },
    [82071] = { [1] = "Очисний вогонь", [2] = "Є щось, навколо чого обгорнуті обвуглені нотки. Якась сапта. Ви не пам'ятаєте, щоб вона виглядала чи пахла саме так, але в іншому вона виглядає так само. Щось у ній дивне, ніби її забруднила якась інша магія. Поруч має бути Скеля Духів, хоча ви не пам'ятаєте, щоб вона там була. Її знахідка може дозволити вам дістатися до суті цієї дивності.", [3] = "Знайдіть заражену Скелю Духів та випийте Сапту Каламутного Вогню.\n\nНаданий предмет:", [5] = "Ти сильний. Ти очищувальний вогонь. Ти зупиняєш корупцію.\n\nТи знаходиш і зупиняєш корупцію.", ["en"] = "Purifying Fire", ["tasks"] = { ["Murky Fire Sapta"] = "Каламутний вогонь Сапта" } },
    [82072] = { [1] = "Очищення Землі", [2] = "Знайома пляшка сапти лежала, загорнута в розмазані нотки. Вона дивно каламутна, проте магія здебільшого здається знайомою. Є слабке відчуття іноземної магії, що заплямує суміш. Ваші інстинкти підказують, що десь поруч має бути Скеля Духів, хоча ви не можете її пригадати. Її знаходження може допомогти вам розгадати цю таємницю.", [3] = "Знайдіть заражену Скелю Духів та випийте Сапту Каламутної Землі.\n\nНаданий предмет:", [5] = "Життя знову зростає. Потрібна сила.\n\nКорупція деінде. Знайдіть і зупиніть.", ["en"] = "Purging Earth", ["tasks"] = { ["Murky Earth Sapta"] = "Каламутна Земля Сапта" } },
    [82073] = { [1] = "Очищувальна вода", [2] = "Вицвілі та мокрі нотки обгорнуті навколо каламутної пляшки. Сапта. Ви не можете пригадати, щоб вона колись так виглядала, але здається досить схожою. Пахне дивно, ніби якось зіпсовано. Десь неподалік має бути Скеля Духів, хоча вона давно покинута. Її пошук може бути відсутнім елементом цієї дивної головоломки.", [3] = "Знайдіть заплямований Духовний Камінь та випийте Каламутну Воду Сапта.\n\nНаданий предмет:", [5] = "Ти очистив. Ти відновив. Сильний духом. Ти допомагаєш.\n\nКорупція все ще живе. Зупини її.", ["en"] = "Cleansing Water", ["tasks"] = { ["Murky Water Sapta"] = "Каламутна вода Сапта" } },
    [82074] = { [1] = "Відповідаючи на поклик вогню", [2] = "Ти сильний. Досить сильний.\n\n<Елементарний іскри та мерехтить.>\n\nЕлементи Фераласу. Есенція. Знайди Святилище.\n\nВізьми Фрагмент. Допоможе.", [3] = "Зберіть 3 Елементальні Есенції з водних елементалів на Забутому Березі навпроти острова Сардор у Фераласі та поєднайте їх з Фрагментом Вогню, щоб викликати допомогу в зіпсованому святилищі.\n\nНаданий предмет:", [4] = "Очистить святиню.", [5] = "Потрібна допомога. Інші елементи сильні. Приведіть їх.", ["en"] = "Answering Fire's Call", ["tasks"] = { ["Fragment of Fire"] = "Фрагмент вогню" } },
    [82075] = { [1] = "Відповідаючи на поклик Землі", [2] = "Життя росте зараз. Потрібно більше. Потрібно зупинити корупцію.\n\n<Скелі шкрябаються одна об одну, коли елементарний рух змінюється.>\n\nФералас. Елементи. Есенція та Святилище.\n\nЗнайди. Використай Фрагмент та знайди. Допоможи життю рости.", [3] = "Зберіть 3 Елементальні Есенції з водних елементалів на Забутому Березі навпроти острова Сардор у Фераласі та поєднайте їх з Фрагментом Землі, щоб викликати допомогу в зіпсованому святилищі.\n\nНаданий предмет:", [4] = "Життя тут зараз процвітає.", [5] = "Життя росте тут і зараз. Потрібно більше. Інші елементи. Допомога.", ["en"] = "Answering Earth's Call", ["tasks"] = { ["Fragment of Earth"] = "Фрагмент Землі" } },
    [82076] = { [1] = "Відповідаючи на поклик води", [2] = "Сильний дух. Ти допомагаєш зупинити псування.\n\n<Вода вирує, кружляючи навколо елементаля.>\n\nБрати. Елементи Фералас допомагають. Есенція знайде Святилище.\n\nФрагмент також допомагає. Очищає псування.", [3] = "Зберіть 3 Елементальні Есенції з водних елементалів на Забутому Березі навпроти острова Сардор у Фераласі та поєднайте їх з Фрагментом Води, щоб викликати допомогу в зіпсованому святилищі.\n\nНаданий предмет:", [4] = "Очистить святиню.", [5] = "Очистіть святилище зараз. Недостатньо сильно. Потрібні інші. Інші елементи.", ["en"] = "Answering Water's Call", ["tasks"] = { ["Fragment of Water"] = "Фрагмент води" } },
    [82083] = { [1] = "Порушений ритуал", [2] = "Ця бездоганна лопатка надто впізнавана — Хаккара викликали у фізичний світ і перемогли. Тролі на острові Йоджамба захочуть почути більше про те, що сталося всередині Затонулого Храму.", [3] = "Принесіть Лопатку занепалого Аватара Молтору на острові Йоджамба.", [4] = "{ім'я}, які у тебе новини з Храму Атал'Хаккара?", [5] = "Не може бути... чутки про Храм Атал'Хаккара правдиві?\n\nТвою перемогу в Затонулому Храмі Зандалари ще довго пам'ятатимуть, друже. Ця кістка... дивний вибір для нашого визволення... але, безсумнівно, її використовували для виклику Хаккара у фізичний світ — тепер вона буде в надійних руках, {ім'я}. Нам більше не потрібно турбуватися про повернення Хаккара завдяки твоїм зусиллям, друже... чи не так?", ["en"] = "A Broken Ritual", ["tasks"] = { ["Item #221363"] = "Товар №221363" } },
    [821] = { [1] = "Порожня діжка Ченя", [2] = "Бажаєш скуштувати напій, названий іменем Ченя? Ох, бурехміль — міцне вариво. Чень поділився рецептом з моїм наставником, а той — передав його мені. Щоправда, мені не вистачає кількох компонентів, але я запевняю тебе: вштирить добре! Воно того варте.\n\nРоздобудь мені 5 ікл будь-якого лева савани, 5 нирок будь-якого рівнинобіга та 1 ріг будь-якого виду громоящера. Цього має вистачити для браги.\n\nЦі інгредієнти не важко дістати по всіх Степах.", [3] = "Принесіть 5 ікл лева савани, 5 нирок рівнинобіга й 1 ріг громоящера бровареві Дрону до Брашпиля.", [4] = "Як просуваються пошуки?", [5] = "Ха-ха... Я ніколи не думав, що знову варитиму це питво.\n\nТи {стать:розбурхав:розбурхала} в мені почуття сильної ностальгії, {ім'я}. Згадався останній раз, коли я зварив трозьку брагу. Дякую. Ці спогади зігрівають мені нутро.", ["en"] = "Chen's Empty Keg", ["tasks"] = { ["Plainstrider Kidney"] = "нирка рівнинобіга", ["Plainstrider Kidney (Provided)"] = "нирка рівнинобіга (видано)", ["Savannah Lion Tusk"] = "ікло лева савани", ["Savannah Lion Tusk (Provided)"] = "ікло лева савани (видано)", ["Thunder Lizard Horn"] = "ріг громоящера", ["Thunder Lizard Horn (Provided)"] = "ріг громоящера (видано)" } },
    [82100] = { [1] = "Храм Атал'Гаккар", [2] = "Тож він говорив про пророцтво Джаммал'ана?\n\nДуховний лідер Атал'ай вірить, що як тільки Хаккар повернеться до Азероту з Нижнього світу, бог дарує племені Атал'ай безсмертя.\n\nНа мою думку, це дурний обман, щоб викликати передчасний кінець світу.\n\nАле ви кажете, що вигнанець говорив про зачаровані фетиші? Це мене дуже непокоїть. Якщо це справді ключ до ритуалу Атал'ай, який спричинив цей безлад, ми повинні зрозуміти їхню внутрішню силу.\n\nЗайдіть у Храм і захопіть фетиші!", [3] = "Зберіть 20 фетишів Хаккара та принесіть їх Фел'Зерулу в Стонарді.", [4] = "Якщо фетиші Атал'ай мають силу викликати Хаккара та виконати пророцтво Джаммал'ана, їх потрібно захопити. Орда повинна зрозуміти такі сили!", [5] = "Хоробрий {клас}, ти довів, що ти великий чемпіон Орди.\n\nТепер з цією колекцією фетишів Хаккара треба негайно розібратися!", ["en"] = "The Temple of Atal'Hakkar" },
    [82101] = { [1] = "Паливо для знищувача", [2] = "Тобі пощастило, {ім'я}! Поки Марвона не було, я працював над кількома власними експериментами, і один з них — це знеболювальний комаха малої дальності. З кількома налаштуваннями він має бути чудовим способом позбутися цих шкідників-кривавопелюстків.\n\nЯ можу дати тобі один зі своїх прототипів знеболювальника, але тобі все одно потрібно буде зібрати паливо. Ти можеш отримати необхідний знеболювальник Атал'айський туман, який потрібен знеболювальнику, у храмі Атал'Хаккара. Тобі знадобиться його отримати з глибинних луркерів, темних черв'яків або слизу.", [3] = "Доставте розвантажений Заппер та 5 зразків Атал'айської імли Ларіону в Притулок Маршала.", [4] = "Це виснажливо, {ім'я}. Ці речі просто не залишають мене в спокої!", [5] = "Тож, Марвона не було поруч? Ну, то покажи мені, що в тебе є, в будь-якому разі.", ["en"] = "Zapper Fuel" },
    [82113] = { [1] = "Вуду", [2] = "Духовного тотема просто недостатньо. Нам знадобиться трохи магії вуду, щоб це спрацювало як слід.\n\nТролі в затонулому храмі мають пір'я, сильне магією вуду. Ідіть туди та вбийте Гашера, Міджана, Золо, Хукку, Зул'лора та Лоро. Тоді у нас буде достатньо магії для справжнього духового тотема.", [3] = "Принеси пір'я вуду Бат'рі, Спостережливій за вітром.", [4] = "Де пір'я, друже?", [5] = "Цьому тролю час виспатися! Духовний тотем наглядатиме за мною.\n\nЯ давно збираю речі, можливо, тобі щось потрібне за всі твої клопоти?", ["en"] = "Da Voodoo" },
    [822] = { [1] = "Порожня діжка Ченя", [2] = "Чудовий напій, цей бурехміль, еге ж?\n\nУ мене є ще один рецепт, який повідав мені Чень. Цікавить? Приготування не займе багато часу, а ще напій може бути корисним тобі в подальших пригодах.\n\nПринеси мені 5 громозалоз будь-якого бурешкура, 1 слинну залозу з більшеньких громояструбів і печінку кодо від будь-якого кодо, що зустрінеться тобі на просторах Степів.\n\nЗуб даю, ця штука крута. Це трозька брага, про яку я розповідав тобі раніше.", [3] = "Дістаньте 5 громозалоз, 1 слинну залозу громояструба та 1 печінку кодо для броваря Дрона у Брашпилі.", [4] = "Ти досі шукаєш інгредієнти, {Ім'я}?", [5] = "Ха-ха! Я знав, що ти не встоїш перед цим хмільним напоєм. Повертайся у будь-який час, як захочеш ще, {ім'я}. Просто знову принеси мені все необхідне.", ["en"] = "Chen's Empty Keg", ["tasks"] = { ["Kodo Liver"] = "печінка кодо", ["Kodo Liver (Provided)"] = "печінка кодо (видано)", ["Lightning Gland"] = "громозалоза", ["Lightning Gland (Provided)"] = "громозалоза (видано)", ["Thunderhawk Saliva Gland"] = "слинна залоза громояструба", ["Thunderhawk Saliva Gland (Provided)"] = "слинна залоза громояструба (видано)" } },
    [8228] = { [1] = "Візьми брошурку", [5] = "Цієї неділі в Грабіжній Бухті відбудеться змагання з риболовлі! Ось, тримай брошурку з правилами, якщо хочеш взяти участь!", ["en"] = "Could I get a Fishing Flier?" },
    [823] = { [1] = "Звітування Орґнілу", [2] = "У нас в селищі Сен'джин своїх проблем достатньо, і ми дякуємо тобі за твою допомогу. Але новини, що ти {стать:приніс:принесла}, стосовно Палаючого Леза, можуть бути проблемою для усіх.\n\nУ Колючому Пагорбі є орк, Орґніл Духошрам, який охороняє Дуротар від подібного зла! Йди до Орґніла і розкажи йому про нашу ситуацію, а також про твої новини з долини Випробувань. Він захоче почути про це.\n\nКолючий Пагорб знаходиться на півночі.", [3] = "Поговоріть з Орґнілом Духошрамом на Колючому Пагорбі.", [5] = "Так? Тобі є що повідомити? Ну, тоді розказуй!", ["en"] = "Report to Orgnil" },
    [824] = { [1] = "Дже'неу зі Служителів Землі", [2] = "Служителі Землі — об'єднання шаманів, які займаються вивченням і збереженням стихій. Те, що ми знаємо про божевільних старих богів та стародавні легенди ніщо в порівнянні з їх знаннями.\n\nТобі пощастило: я знаю декого зі Служителів тут, в Ясенедолі. Прямуй до форпосту Зорам'гар на Зорамському узбережжі. Покажи Дже'неу Санкрі свою знахідку. Тільки він зможе відкрити її таємниці.", [3] = "Принесіть забруднену водяну кулю Дже'неу Санкрі на форпост Зорам'ґар, що в Ясенедолі.", [4] = "О, вітаю. Я старанно вивчаю воду — та й всі інші стихії — настільки, що іноді не помічаю навколишніх.\n\nЧи можу я тобі чимось допомогти?", [5] = "Ця куля... вона мене дуже бентежить. Багато могутніх елементалів отримують свою силу та енергію через такі прилади. Знайти такий майже неушкодженим — це одне, але настільки забрудненим — то зовсім інше.\n\nЯ простежу, щоб ця куля була належним чином вивчена Служителями Землі. Можливо, ми зможемо покласти край спотворенню стихій. Будь ласка, прийми це як винагороду за привернення уваги Служителів до цієї проблеми.", ["en"] = "Je'neu of the Earthen Ring", ["tasks"] = { ["Befouled Water Globe"] = "забруднена водяна куля", ["Befouled Water Globe (Provided)"] = "забруднена водяна куля (видано)" } },
    [825] = { [1] = "З уламків....", [2] = "Один із моїх найбільш спостережливих розвідників доповів, що уламки флоту Праудмура досі знаходяться вздовж дуротарського узбережжя, на схід від Тіраґардської твердині.\n\nНі для кого не секрет, що люди в альянсі з цими брудними коротунами-гномами, які, своєю чергою, досить непогано розбираються у питаннях механіки. Ми мусимо мати повне розуміння наших потенційних ворогів. Увесь наш народ теж виграє від цих знань.\n\nПопірнай між уламками, {Ім'я}, і дістань мені інструменти Альянсу.", [3] = "Ґар'Ток з Колючого Пагорба хоче, щоб ви дістали 3 інструменти гномів з корабельних уламків вздовж берега.", [4] = "Як тільки ми зрозуміємо, як люди керують своїми дивними машинеріями, то отримаємо величезну перевагу у майбутніх битвах.\n\nЗ отриманими знаннями Орда стане ще сильнішою.", [5] = "Твоя місія по отриманню інструментів була успішною, {клас:к}. Я простежу, щоб вони дістались Орґріммару з наступним караваном.\n\nГарна робота.", ["en"] = "From The Wreckage....", ["tasks"] = { ["Gnomish Tools"] = "інструменти гномів", ["Gnomish Tools (Provided)"] = "інструменти гномів (видано)" } },
    [8259] = { [1] = "Більш доречна винагорода", [5] = "Ах, {ім'я}... ваші зусилля проти Темного Розбійника були надзвичайними — зусилля, дозвольте додати, які заслуговували на набагато кращу винагороду, ніж ви отримали. Будь ласка, прийміть цей шолом як додатковий подарунок для вас за ваші досягнення в Несхольності.\n\nЩе раз дякую.", ["en"] = "A More Fitting Reward" },
    [826] = { [1] = "Залазейн", [2] = "Знахар Залазейн мешкає на островах Ехо, що лежать на сході. Островах, які ми колись називали домом.\n\nЗвідти він відправляє своїх тролів на материк, щоб докучати нашому народу — зачаровуючи їх і перетягуючи під свій контроль.\n\nЙого потрібно зупинити.\n\nУбий Залазейна і його посіпак — колишніх тролів Темного Списа. Їх вже не врятувати… Принеси мені його голову і я буду знати, що цьому злу настав кінець.", [3] = "Переможіть Залазейна.\n\nУбийте 8 тролів вуду і 8 зачарованих тролів.\n\nПринесіть голову Залазейна Ґадріну.", [4] = "Залазейн вже переможений, {Ім'я}?", [5] = "Зі смертю Залазейна наше плем'я знову може спати спокійно.\n\nДякую тобі, {Ім'я}. Плем'я Темного Списа тобі дуже зобов'язане. Якщо тебе турбує якийсь недуг, звернись до мого помічника Бом'бея, позаду мене. В нього достатньо сильне вуду...", ["en"] = "Zalazane", ["tasks"] = { ["Hexed Troll"] = "зачарований троль", ["Hexed Troll slain"] = "зачарований троль: убито", ["Voodoo Troll"] = "троль вуду", ["Voodoo Troll slain"] = "троль вуду: убито", ["Zalazane's Head"] = "голова Залазейна", ["Zalazane's Head (Provided)"] = "голова Залазейна (видано)" } },
    [8264] = { [1] = "Стандартний набір припасів Труїтелів", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я:к}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в низині Араті.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в низині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть почесними, а бинти — коли шанованими.", ["en"] = "Defiler's Standard Care Package", ["tasks"] = { ["The Defilers"] = "Осквернителі" } },
    [8265] = { [1] = "Покращений набір припасів Труїтелів", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я:к}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в низині Араті.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в низині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть почесними, а бинти — коли шанованими.", ["en"] = "Defiler's Advanced Care Package", ["tasks"] = { ["The Defilers"] = "Осквернителі" } },
    [82656] = { [1] = "Жилет з дикої шкіри", [2] = "Жилети з дикої шкіри є основою будь-якого комплекту обладунків з дикої шкіри. Каркас жилета та переплетення дикої лози всередині нього створюють виріб, який забезпечує максимальний захист тулуба, водночас дозволяючи потужній магії проникати крізь одяг.\n\nДля цього викрійки мені знадобляться два нагрудники з луски черепахи, два комплекти рукавичок з луски черепахи та дика лоза. Це нелегкий урок, але ви точно маєте навички, щоб його виконати.", [3] = "Принесіть 2 нагрудники з луски черепахи, 2 рукавички з луски черепахи та Дику лозу Джангдору Швидкому Мандрівнику в Табір Мохаче.", [4] = "У вас є два нагрудники та рукавички з луски черепахи? Також не забудьте про дику лозу!\n\nНавіть з найпершими викрійками ми дізнаємося, що основи форми добре переносяться на складніші вироби. Хоча це різні предмети, форма нагрудників з луски черепахи готує вас до деталей, необхідних для виготовлення жилета з дикої шкіри.\n\nУ міру того, як ви будете просуватися на уроках, навички, які я навчаю, перетворюватимуться на мистецтво.", [5] = "Ось кілька дуже гарних виробів, {ім'я}. Майстерність та турбота, вкладені у їх створення, свідчать про те, що ви вирішили повністю присвятити себе цим завданням.\n\nВи виконали мої прохання, і з цим приходить ваша винагорода. Знання про виготовлення жилетів дикої шкіри тепер ваші!", ["en"] = "Wild Leather Vest" },
    [82665] = { [1] = "Шлях зброяра", [2] = "Одного дня я створю легендарний молот. Молот, гідний Вождя!\n\nЦе справа всього мого життя, {ім'я}. Моя пристрасть. Я усвідомлюю, що у тебе є потенціал бути серед нас, одним із нас – зброярем. Я той, хто може допомогти тобі використати цей потенціал.\n\nПросте завдання – це все, що ти маєш виконати. Просте для того, хто має твої виняткові навички.", [3] = "Щоб стати Зброярем, ви повинні виготовити такі предмети та повернути їх Боргошу: 4 мечі з місячної сталі, 4 масивні залізні сокири, 2 важкі міфрилові сокири та 2 великі чорні булави.", [4] = "Заради слави Орди!", [5] = "Це останній крок перед тим, як ви розпочнете свою нову кар'єру зброяра, {ім'я}. Якщо ви вирішите відмовитися, зараз ваш останній шанс. В іншому випадку, готуйтеся бути поглинутими знаннями!", ["en"] = "The Way of the Weaponsmith" },
    [827] = { [1] = "Скеля Черепа", [2] = "{Ім'я}. На сході від Орґріммару Палаюче Лезо захопило печеру, відому як Скеля Черепа. Там вони проводять свої дикі ритуали і спалюють власну плоть опаляючими нашийниками.\n\nДумаю, що вдягаючи ці нашийники, культисти намагаються осягнути демонічні сили. Але щоб підтвердити цю гіпотезу, мені потрібно декілька цих предметів для аналізу.\n\nЙди до Скелі Черепа і забери опаляючі нашийники у культистів. Принеси їх мені, і я розкрию їхні секрети.", [3] = "Заберіть опаляючі нашийники у культистів зі Скелі Черепа.\n\nПринесіть їх Марґозу у його табір.", [4] = "Ти {стать:ходив:ходила} до Скелі Черепа, {Ім'я}? {стать:Приніс:Принесла} мені опаляючі нашийники?", [5] = "Чудово. Ці нашийники приховують в собі секрети Палаючого Леза. І я їх розкрию...", ["en"] = "Skull Rock", ["tasks"] = { ["Searing Collar"] = "опалюючий нашийник", ["Searing Collar (Provided)"] = "опалюючий нашийник (видано)" } },
    [8272] = { [1] = "Герой Морозних Вовків", [5] = "Як відчуття, {ім'я:к}? Як це — розбивати своїх ворогів і дивитися, як їхні ряди розсипаються? Приємно, чи не так?\n\nПрийми нагороду за свої героїчні діяння, солдате.", ["en"] = "Hero of the Frostwolf" },
    [8273] = { [1] = "Подяка Орани", [5] = "Тож ти {стать:знайшов:знайшла} цю скрижаль на маленькому острові на Оглядових кручах у Внутрішніх землях, {клас:к}? Це дійсно цікаво.\n\nЯ дякую тобі за твої зусилля у цій справі. Темна Леді буде дуже задоволена цією знахідкою. Ось, дозволь мені гідно віддячити тобі.", ["en"] = "Oran's Gratitude" },
    [8276] = { [1] = "Відвоювання Силітуса", [2] = "Увага, герої Орди! Ми занадто довго не звертали уваги на серйозну загрозу. Тремтіння землі біля вуликів силітидів по всьому Азероту свідчать про значне зростання їхньої чисельності у зв'язку з підготовкою до масштабного вторгнення.\n\nСили Кенарійського Кола збираються в Силітусі, щоб дати відсіч силітидам, поки не стало надто пізно! Ми не дозволимо їм і далі плюндрувати нашу землю!\n\nВсі, хто здатен тримати зброю, мають звернутися до вітрозова Гордого Рога в Кенарійську цитадель! Силітиди будуть знищені!", [3] = "Поговоріть з вітрозовом Гордим Рогом в Кенарійській цитаделі, що в Силітусі.", [5] = "Чудово, ми завжди раді новим рекрутам, що готові виступити проти силітидів. Ласкаво просимо до Кенарійської цитаделі, {клас:к}. Приємно бачити, що слова наших емісарів доходять до таких героїв, як ти. У тебе буде вдосталь можливостей допомогти нам, і я сподіваюся, що ти станеш {стать:цінним союзником:цінною союзницею}.", ["en"] = "Taking Back Silithus" },
    [828] = { [1] = "Марґоз", [2] = "Один із наших шаманів, Марґоз, знає більше про гниль Палаючого Леза. За його словами, в печері, що зветься Скеля Черепа, одразу за Орґріммаром, оселилась велика кількість послідовників Палаючого Леза.\n\nПерш ніж ти підеш у Скелю Черепа, поговори з Марґозом. Він мудрий, а його поради дуже цінні.\n\nВін став табором на північному сході, між узбережжям і Сухощільним яром.\n\nПрислухайся до його порад, але хоч що там Марґоз тобі казатиме, {Ім'я}, я все одно хочу, щоб ти {стать:роздавив:роздавила} тих культистів!", [3] = "Поговоріть з Марґозом.", [5] = "Вітаю, {ім'я:к}. До мене дійшли розмови про тебе і твої подвиги у Дуротарі.\n\nТвоя майстерність росте пропорційно твоїй славі, {клас:к}.\n\nПродовжуй йти цим шляхом, і на тебе чекає велике майбутнє.", ["en"] = "Margoz" },
    [829] = { [1] = "Нііру Вогняне Лезо", [2] = "Ці опалюючі нашийники, які ти мені {стать:приніс:принесла} — потужні демонічні знаряддя. На жаль, визначити їхнє походження поза межами моїх шаманських вмінь. Нам потрібен чорнокнижник щоб вивчити їх.\n\nВіднеси опалюючий нашийник до Нііру Вогняного Леза. Він досвідчений чорнокнижник, але стверджує, що використовує свою силу лише для приборкання демонів і що його окультні досліди йдуть на користь Орді. Правда це чи ні, та нам може знадобитись його допомога в боротьбі з демонічним культом в Дуротарі.\n\nТи знайдеш Нііру в Орґріммарі, у Розколині Тіні.", [3] = "Принесіть зразок ошийника Нііру Вогняному Лезу в Орґріммар.", [4] = "Мої найпокірніші вітання, {клас:к}. Як можу я допомогти моєму побратиму-{раса:д}?", [5] = "Арх, і звідки ти це {стать:дістав:дістала}? Добрий Марґоз з Колючого Пагорбу послав тебе до мене, чи не так?\n\nНу що ж, поглянемо поближче...", ["en"] = "Neeru Fireblade", ["tasks"] = { ["Example Collar"] = "зразок ошийника", ["Example Collar (Provided)"] = "зразок ошийника (видано)" } },
    [830] = { [1] = "Накази адмірала", [2] = "Ви відкриваєте старий зім'ятий конверт і бачите якийсь офіційний документ. Ви помічаєте знак з печаткою адмірала Праудмура.\n\nСкоріше за все, це важливий документ. Можливо Ґар'Ток, командувач Колючого Пагорба, буде зацікавлений у цій інформації.", [3] = "Принесіть накази адмірала Праудмура Ґар'Току в Колючий Пагорб.", [4] = "Маєш занепокоєний вигляд, {клас:к}. Що там у тебе?", [5] = "Нам це не обіцяє нічого хорошого. Передати мені цю інформацію було розумно з твого боку.", ["en"] = "The Admiral's Orders", ["tasks"] = { ["Admiral Proudmoore's Orders"] = "накази адмірала Праудмура", ["Admiral Proudmoore's Orders (Provided)"] = "накази адмірала Праудмура (видано)" } },
    [831] = { [1] = "Накази адмірала", [2] = "Людям нема віри. Ми билися пліч-о-пліч з ними, але в глибині душі знали, що рано чи пізно вони нас зрадять.\n\nАдмірал Праудмур був убитий, але цього виявилося недостатньо, щоб зупинити їх зраду. Цей підступний чоловік встиг до кінця все продумати й перед смертю виклав свої плани на папері.\n\nСхоже, що його правління не помре навіть разом з Бенедиктом. Хто знає, коли наступна хвиля людей Праудмура рухне на наші береги?\n\nЦі накази слід негайно передати в Орґріммар, Назґрелу! Ти знайдеш його в приймальній залі Тралла.", [3] = "Віднесіть накази адмірала Праудмура Назґрелу в приймальну залу Тралла в Орґріммарі.", [4] = "Ти що, не бачиш, що я зайнятий? Сподіваюсь, це важливо…", [5] = "О, скільки разів я переконував воєвождя не довіряти людям! Однак тут мова не про особисту гордість.\n\nТи гідно {стать:послужив:послужила} Орді, {стать:юний:юна} {клас:к}.\n\nА тепер вибач, я маю негайно поговорити з Траллом...", ["en"] = "The Admiral's Orders", ["tasks"] = { ["Admiral Proudmoore's Orders"] = "накази адмірала Праудмура", ["Admiral Proudmoore's Orders (Provided)"] = "накази адмірала Праудмура (видано)" } },
    [8312] = { [1] = "Ласощі Повечір'я святих для Бупса!", [2] = "Я хочу піти збирати цукерки, але не можу, бо я хворий. Якщо ти підеш за мене, я обміняю отримані тобою цукерки на ті, які вже у мене! Я думаю, тобі сподобаються ці цукерки — вони змушують тебе перетворюватися на смішні й жахливі речі!\n\nКорчмар у великих містах мають цукерки, які вони віддають на Повечір'я святих — поговори з ними й виконай будь-які забаганки, які вони попросять! Також тролька, на ім'я Калі Ремік у селищі Сен'джин роздає цукерки. Коли збереш всі цукерки — повертайся з ними до мене!", [3] = "Поговоріть з корчмарями Орґріммара, Підмістя та Громового Бескиду, а також з Калі Ремік у селищі Сен'джин. Виконайте те, що вони захочуть в обмін на ласощі.\n\nПоверніться до Бупса в сиротинець Орґріммара з марципаном Громового Бескиду, мармеладом Темного списа, нугою Орґріммара і м'ятною цукеркою Підмістя.", [4] = "Ти вже {стать:закінчив:закінчила} ходити по цукерки? Мені шкода, що я не можу піти, бо хворію, але завдяки твоїй допомозі мені стало трохи легше...", [5] = "Ого, ти {стать:приніс:принесла} всі цукерки! Ти просто {стать:неймовірний:неймовірна}!\n\nДякую, що {стать:збирав:збирала} їх для мене. Ось, візьми ці гарбузові ласощі — думаю, вони тобі дуже сподобаються!\n\nЩасливого Повечір'я святих, {ім'я}!", ["en"] = "Hallow's End Treats for Spoops!", ["tasks"] = { ["Darkspear Gumdrop"] = "мармелад Темного Списа", ["Darkspear Gumdrop (Provided)"] = "мармелад Темного Списа (видано)", ["Orgrimmar Nougat"] = "нуга Орґріммара", ["Orgrimmar Nougat (Provided)"] = "нуга Орґріммара (видано)", ["Thunder Bluff Marzipan"] = "марципан Громового Бескиду", ["Thunder Bluff Marzipan (Provided)"] = "марципан Громового Бескиду (видано)", ["Undercity Mint"] = "м'ятна цукерка Підмістя", ["Undercity Mint (Provided)"] = "м'ятна цукерка Підмістя (видано)" } },
    [833] = { [1] = "Священне поховання", [2] = "Тільки найзвитяжніші таурени можуть бути поховані на Червоних скелях, нашому священному кладовищі. Ця честь випадає лише найзвитяжнішим воїнам, які заснували і захищали Громовий Бескид, тим, хто віддав свої життя на благо свого племені та ватажків.\n\nАле схоже, що нечиста загроза проторила свій шлях на нашу святу землю. Могили опоганюють встрягачі із племені Щетиношкурих, а я занадто старий, щоб прогнати їх.\n\nПроти них допоможе лише сила, {Ім'я}.", [3] = "Хранитель знань Дощовий Тотем хоче, щоб ви вбили 8 щетиношкурих встяграчів на Червоних скелях.", [4] = "Встрягачів із племені Щетиношкурих потрібно вигнати з нашого священного кладовища, {Ім'я}.", [5] = "Хороша робота. Ти {стать:відправив:відправила} цим брудним Щетиношкурим чітке повідомлення. Тепер вони подумають двічі, перш ніж знову оскверняти святі для нас місця.", ["en"] = "A Sacred Burial", ["tasks"] = { ["Bristleback Interloper"] = "щетиношкурий встрягач", ["Bristleback Interloper slain"] = "щетиношкурий встрягач: убито" } },
    [8354] = { [1] = "Кудахкання за цукерку", [2] = "А, ти збираєш цукерки для хворої дитини, чи не так? Я маю на увазі, ти трохи {стать:старуватий:старувата}, щоб цукерки випрошувати...\n\nЩо ж, за мої ласощі — м'ятну цукерку Підмістя — тобі потрібно буде... кудахкати, як курка! Так, курки люблять м'ятні цукерки... ну добре, можливо, вони не ЛЮБЛЯТЬ їх... але я не дам тобі м'ятну цукерку, поки ти не закудахкаєш для мене!\n\nНу що, {клас:к}, ти {стать:готовий:готова} кудахкати чи ні?! Час заробити свої ласощі!", [3] = "Зобразіть курку перед корчмарем Норманом, та отримайте м'ятну цукерку Підмістя!", [4] = "Я чекаю...", [5] = "Дуже смішно! Молодець, {ім'я}! Ось твої ласощі.\n\nЩасливого Повечір'я святих!", ["en"] = "Chicken Clucking for a Mint", ["tasks"] = { ["Cluck like a chicken for Innkeeper Norman"] = "Кудакни, як курка, для шинкаря Нормана" } },
    [8358] = { [1] = "Чух-чух, мармелад!", [2] = "Цукерки або життя! Так, мон!\n\nОтож, навіть якщо ти займаєшся благородною справою і збираєш цукерки для хворої дитини, я не можу так легко дати їх тобі. Я дам тобі смачний мармелад Темного Списа... якщо ти зобразиш для мене потяг! Ха-ха, так, хай буде так! Ціна цього мармеладу — звук потяга!\n\nЧух-чух, {клас:к}!", [3] = "Зобразіть потяг перед Калі Ремік, та отримайте мармелад Темного Списа!", [4] = "Ну, можеш починати...", [5] = "Чух-чух! Молодець, {{ім'я}}! Ось твої ласощі.\n\nЩасливого Повечір'я святих!", ["en"] = "Incoming Gumdrop", ["tasks"] = { ["Do the \"train\" for Kali Remik"] = "Зробіть \"поїзд\" для Калі Ремік" } },
    [8359] = { [1] = "Пограй м'язами за нугу!", [2] = "Це... цікавий костюм у тебе є. Попри те, що ти {стать:добрий:добра} і допомагаєш хворій дитині збирати цукерки на Хелловін, на жаль, мені доведеться попросити тебе щось продемонструвати!\n\nПодивимося... ти виглядаєш {стать:таким сильним і мускулистим:такою сильною і мускулистою} в цьому... костюмі... давай покажи мені свої м'язи, {стать:силачу:силачко}!\n\nТільки коли ти покажеш свої м'язи, я дам тобі смачну нугу Орґріммара. Це чудові ласощі для Повечір'я святих.", [3] = "Пограйте м'язами перед корчмаркою Гришкою, та отримайте нугу Орґріммара!", [4] = "Ніяких ласощів, доки не покажеш м'язи мені, {ім'я}...", [5] = "Ти справді {стать:могутній:могутня}, ха-ха! Молодець, і дякую, що ти {стать:такий вправний:така вправна}. Ось твої цукерки.\n\nЩасливого Повечір'я святих, {ім'я}!", ["en"] = "Flexing for Nougat", ["tasks"] = { ["Flex for Innkeeper Gryshka"] = "Флекс для шинкаря Гришки" } },
    [8360] = { [1] = "Танець за марципан", [2] = "Попри те, що ти збираєш цукерки для хворої дитини, тобі все одно потрібно щось продемонструвати, щоб отримати винагороду! Ми не можемо зраджувати традиціям, чи не так...\n\nЯ вважаю, що гідна ціна за шматочок марципана — танець! Так, я хочу побачити твої рухи! Станцюй для мене, і отримаєш смачний марципан!", [3] = "Станцюйте перед корчмаркою Палою, та отримайте марципан Громового Бескиду!", [4] = "Ти вмієш танцювати, так? Спробуй, ставиш праву ногу вперед... тепер назад... вперед... а тепер потряси нею...", [5] = "Ти справжня машина танцю, {ім'я}!\n\nОсь тобі частування за те, що ти {стать:такий вправний танцюрист:така вправна танцюристка}. Щасливого Повечір'я святих, і передавай мої найкращі побажання твоєму хворому маленькому другу! Сподіваюся, він скоро одужає.", ["en"] = "Dancing for Marzipan", ["tasks"] = { ["Dance for Innkeeper Pala"] = "Танець для шинкаря Пали" } },
    [8367] = { [1] = "Велика честь", [2] = "Служити Орді в битві проти Альянсу — велика честь! Найкращі ж наші воїни — ті, кому довелося битися на ВСІХ полях битви. Дрібні сутички не допоможуть нам здолати ворога. Лише ретельно спланувавши наступ, ми зможемо перемогти.\n\nЙди й розтрощи Альянс в низині Араті, Альтерацькій долині та тіснині Пісні Війни! За честь! За Орду!", [3] = "Принесіть 3 відзнаки честі Альтерацької долини, 3 відзнаки честі низини Араті та 3 відзнаки честі тіснини Пісні Війни війноносцю Орди біля входу на поле бою.", [4] = "Араті просякнута кров'ю великих воїнів, а брязкіт сталі все ще лунає по всьому Альтераку. Не гай даремно мій час — йди на поле бою!", [5] = "На твою долю випали непрості випробування, але твоя відвага і сила не підвели тебе. Знаки перемоги — дрібниця, {клас:к}. Не вони принесуть тобі славу. Вище голову, {ім'я:к}. Сьогодні ти можеш ходити з гордістю, бо ти - {стать:справжній герой:справжня героїня}!", ["en"] = "For Great Honor", ["tasks"] = { ["Alterac Valley Mark of Honor"] = "відзнака честі Альтерацької долини", ["Alterac Valley Mark of Honor (Provided)"] = "відзнака честі Альтерацької долини (видано)", ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)", ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [837] = { [1] = "Вторгнення", [2] = "Коли ми прибули, бритвогриві свинобрази тримали більшу частину землі і були для нас справжньою скалкою в дупі. Своїми силами ми вигнали велику їх кількість, але подекуди досі трапляються їхні добре укріплені табори.\n\nЦе продовжується занадто довго. Для власного захисту, ми не можемо дозволити Бритвогривим закріпитись у наших землях. Їхні табори можна відшукати на заході. Орієнтуйся на колючі чагарники і знайдеш їх. Сьогодні ми виженемо їх з Дуротару, а завтра, можливо, з усього Калімдору!", [3] = "Убийте 4 бритвогривих свинобразів, 4 бритвогривих розвідників, 4 бритвогривих пилоступів і 4 бритвогривих боєстражів для Ґар'Тока у Колючому Пагорбі.", [4] = "Хоч вони і володіють якимись знаннями, і мають певну організованість, але я продовжую дивуватись, як ці свинобрази були здатні захопити і утримувати так багато територій у Калімдорі. Можливо, вони є більш підступним ворогом, ніж я вважав раніше…", [5] = "Я розповім усім, що свинобрази були вигнані зі своїх барлогів і тепер їхні будівлі можна спалити. Вигнання Бритвогривих з Дуротару підводить нас ближче до повного закріплення кордонів нашої нової батьківщини.", ["en"] = "Encroachment", ["tasks"] = { ["Razormane Battleguard"] = "бритвогривий боєстраж", ["Razormane Battleguard slain"] = "бритвогривий боєстраж: убито", ["Razormane Dustrunner"] = "бритвогривий пилобіг", ["Razormane Dustrunner slain"] = "бритвогривий пилобіг: убито", ["Razormane Quilboar"] = "бритвогривий свинобраз", ["Razormane Quilboar slain"] = "бритвогривий свинобраз: убито", ["Razormane Scout"] = "бритвогривий розвідник", ["Razormane Scout slain"] = "бритвогривий розвідник: убито" } },
    [838] = { [1] = "Некроситет", [2] = "На острові Тверджа Дарроу знаходиться Некроситет — школа, що слугує фортецею для Скари. В її надрах наші вороги спокійно проводять дослідження і стають дедалі сильнішими. Двері загороджують нам шлях, і як ми не намагалися, без відповідного ключа їх не відчинити.\n\nАптекар Дітерс багато знає про Некроситет, і у нього є ідея, як отримати цей ключ. Ти {стать:довів:довела}, що ти {стать:той:та}, хто завжди сумлінно виконує поставлені задачі, тож я довіряю це завдання тобі. Обговори подробиці з аптекарем.", [3] = "Поговоріть з аптекарем Дітерсом на Валу, в Західних Зачумлених землях.", [5] = "Так, {клас:к}, верховний каратель зазначив, що тобі можна довірити завданням з ключем. Я присвятив чимало часу дослідженням Некроситету, і мені здається, що я знаю, як отримати ключ, що дозволить відчинити вхідні двері.\n\nЦе завдання, звісно, не буде простим. Ти безсумнівно розумієш, про що я кажу.", ["en"] = "Scholomance" },
    [8388] = { [1] = "Велика честь", [4] = "Багато хоробрих воїнів беруть з тебе приклад, йдучи в бій проти Альянсу, {ім'я:к}. Що нового ти {стать:приніс:принесла} зі своїх мандрів?", [5] = "Ти продовжуєш приносити перемоги для Орди, {ім'я:к}. Приємно бачити, що ти не {стать:розм'як:розм'якла}.", ["en"] = "For Great Honor", ["tasks"] = { ["Alterac Valley Mark of Honor"] = "відзнака честі Альтерацької долини", ["Alterac Valley Mark of Honor (Provided)"] = "відзнака честі Альтерацької долини (видано)", ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)", ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [840] = { [1] = "Новобранець Орди", [2] = "Гмм, ти виглядаєш досить {стать:сильним:сильною}.\n\nСлухай, мій хороший друг Карґал потребує кількох новобранців для служби у Степах. Я знаю, ти хочеш допомогти Орді. Що ж, це твій шанс.\n\nВіднеси цей вербувальний лист Карґалу і подивимось, чи він підпише його.", [3] = "Йдіть західним шляхом від Колючого Пагорбу через міст до Степів.\n\nЗупиніться на заставі орків за мостом.\n\nВіддайте Карґалу Битвошраму на заставі, що в Степах, ваш вербувальний лист.", [4] = "Чого тобі, щеня? Якщо ти тут щодо вербування, то в мене нема на тебе часу.", [5] = "Ох, то це Такрін послав тебе? Він відмінний розвідник, не знаю, що б я робив без нього.\n\nЯ підпишу твого листа, але нам більше б знадобилася чиясь допомога у Перехресті.", ["en"] = "Conscript of the Horde", ["tasks"] = { ["Recruitment Letter"] = "вербувальний лист", ["Recruitment Letter (Provided)"] = "вербувальний лист (видано)" } },
    [8411] = { [1] = "Опанування стихій", [2] = "Здоров, {стать:друже:подруго}. Принеси мені стихії, тоді й побалакаєм.", [3] = "Принесіть первородні землю, повітря, вогонь та воду Бат'раху Вітрогляду.", [4] = "Де стихії, {стать:друже:подруго}?", [5] = "Це те, шо мені нада. Тепер поговорим.", ["en"] = "Mastering the Elements", ["tasks"] = { ["Elemental Air"] = "первородне повітря", ["Elemental Air (Provided)"] = "первородне повітря (видано)", ["Elemental Earth"] = "первородна земля", ["Elemental Earth (Provided)"] = "первородна земля (видано)", ["Elemental Fire"] = "первородний вогонь", ["Elemental Fire (Provided)"] = "первородний вогонь (видано)", ["Elemental Water"] = "первородна вода", ["Elemental Water (Provided)"] = "первородна вода (видано)" } },
    [84155] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас}! З твоєї поведінки я бачу, що ти багато бачив і робив у цьому світі. Однак готовий посперечатися, що ти ніколи не бачив такого обладунку.\n\nЗроби мені невелику послугу, і я буду готовий обміняти його на звичайний набір браслетів.\n\nМені потрібен великий зразок отрути, витягнутої з павуків та скорпіонів, що мешкають у Силітусі. Принеси мені це разом з кількома золотими монетами, і я здійсню обмін.", [3] = "Здобудьте 15 зразків отрути Силітуса та 20 золота і принесіть їх разом із набором наручів Дикого Серця Моквару в Орґріммарі.", [4] = "Ви отримали потрібні мені предмети, {ім'я}?", [5] = "Ах, так. Мукс буде цим цілком задоволений.\n\nЦі наручі були частиною більшого комплекту обладунків. Якщо ви зацікавлені в наданні мені подальшої допомоги, я готовий розглянути можливість розлучення з рештою.", ["en"] = "An Earnest Proposition" },
    [84156] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас}! З твоєї поведінки я бачу, що ти багато бачив і робив у цьому світі. Однак готовий посперечатися, що ти ніколи не бачив такого обладунку.\n\nЗроби мені невелику послугу, і я буду готовий обміняти його на звичайний набір браслетів.\n\nМені потрібен великий зразок отрути, витягнутої з павуків та скорпіонів, що мешкають у Силітусі. Принеси мені це разом з кількома золотими монетами, і я здійсню обмін.", [3] = "Здобути 15 зразків отрути Силітуса та 20 золота і принести їх разом із набором пут Звіроловця до Моквара в Орґріммарі.", [4] = "Ви отримали потрібні мені предмети, {ім'я}?", [5] = "Ах, так. Мукс буде цим цілком задоволений.\n\nЦі наручі були частиною більшого комплекту обладунків. Якщо ви зацікавлені в наданні мені подальшої допомоги, я готовий розглянути можливість розлучення з рештою.", ["en"] = "An Earnest Proposition" },
    [84157] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас}! З твоєї поведінки я бачу, що ти багато бачив і робив у цьому світі. Однак готовий посперечатися, що ти ніколи не бачив такого обладунку.\n\nЗроби мені невелику послугу, і я буду готовий обміняти його на звичайний набір браслетів.\n\nМені потрібен великий зразок отрути, витягнутої з павуків та скорпіонів, що мешкають у Силітусі. Принеси мені це разом з кількома золотими монетами, і я здійсню обмін.", [3] = "Здобути 15 зразків отрути Силітуса та 20 золота і принести їх разом із набором пут Магістра до Моквара в Орґріммарі.", [4] = "Ви отримали потрібні мені предмети, {ім'я}?", [5] = "Ах, так. Мукс буде цим цілком задоволений.\n\nЦі наручі були частиною більшого комплекту обладунків. Якщо ви зацікавлені в наданні мені подальшої допомоги, я готовий розглянути можливість розлучення з рештою.", ["en"] = "An Earnest Proposition" },
    [84158] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас}! З твоєї поведінки я бачу, що ти багато бачив і робив у цьому світі. Однак готовий посперечатися, що ти ніколи не бачив такого обладунку.\n\nЗроби мені невелику послугу, і я буду готовий обміняти його на звичайний набір браслетів.\n\nМені потрібен великий зразок отрути, витягнутої з павуків та скорпіонів, що мешкають у Силітусі. Принеси мені це разом з кількома золотими монетами, і я здійсню обмін.", [3] = "Здобудьте 15 зразків отрути Силітуса та 20 золота і принесіть їх разом із набором наручів відданості Моквару в Орґріммарі.", [4] = "Ви отримали потрібні мені предмети, {ім'я}?", [5] = "Ах, так. Мукс буде цим цілком задоволений.\n\nЦі наручі були частиною більшого комплекту обладунків. Якщо ви зацікавлені в наданні мені подальшої допомоги, я готовий розглянути можливість розлучення з рештою.", ["en"] = "An Earnest Proposition" },
    [84159] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас}! З твоєї поведінки я бачу, що ти багато бачив і робив у цьому світі. Однак готовий посперечатися, що ти ніколи не бачив такого обладунку.\n\nЗроби мені невелику послугу, і я буду готовий обміняти його на звичайний набір браслетів.\n\nМені потрібен великий зразок отрути, витягнутої з павуків та скорпіонів, що мешкають у Силітусі. Принеси мені це разом з кількома золотими монетами, і я здійсню обмін.", [3] = "Здобудьте 15 зразків отрути Силітуса та 20 золота і принесіть їх разом із набором наручів Тіньової майстерності Моквару в Орґріммар.", [4] = "Ви отримали потрібні мені предмети, {ім'я}?", [5] = "Ах, так. Мукс буде цим цілком задоволений.\n\nЦі наручі були частиною більшого комплекту обладунків. Якщо ви зацікавлені в наданні мені подальшої допомоги, я готовий розглянути можливість розлучення з рештою.", ["en"] = "An Earnest Proposition" },
    [84160] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас}! З твоєї поведінки я бачу, що ти багато бачив і робив у цьому світі. Однак готовий посперечатися, що ти ніколи не бачив такого обладунку.\n\nЗроби мені невелику послугу, і я буду готовий обміняти його на звичайний набір браслетів.\n\nМені потрібен великий зразок отрути, витягнутої з павуків та скорпіонів, що мешкають у Силітусі. Принеси мені це разом з кількома золотими монетами, і я здійсню обмін.", [3] = "Здобути 15 зразків отрути Силітуса та 20 золота і принести їх разом із набором «Пов'язки стихій» Моквару в Орґріммарі.", [4] = "Ви отримали потрібні мені предмети, {ім'я}?", [5] = "Ах, так. Той старий гоблін буде цілком задоволений цією кров’ю.\n\nЦі наручі були частиною більшого комплекту обладунків. Якщо ви зацікавлені в наданні мені подальшої допомоги, я готовий розглянути можливість розлучення з рештою.", ["en"] = "An Earnest Proposition" },
    [84161] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас}! З твоєї поведінки я бачу, що ти багато бачив і робив у цьому світі. Однак готовий посперечатися, що ти ніколи не бачив такого обладунку.\n\nЗроби мені невелику послугу, і я буду готовий обміняти його на звичайний набір браслетів.\n\nМені потрібен великий зразок отрути, витягнутої з павуків та скорпіонів, що мешкають у Силітусі. Принеси мені це разом з кількома золотими монетами, і я здійсню обмін.", [3] = "Здобудьте 15 зразків отрути Силітуса та 20 золота і принесіть їх разом із набором наручів Жахливого Туману Моквару в Орґріммарі.", [4] = "Ви отримали потрібні мені предмети, {ім'я}?", [5] = "Ах, так. Мукс буде цим цілком задоволений.\n\nЦі наручі були частиною більшого комплекту обладунків. Якщо ви зацікавлені в наданні мені подальшої допомоги, я готовий розглянути можливість розлучення з рештою.", ["en"] = "An Earnest Proposition" },
    [84162] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас}! З твоєї поведінки я бачу, що ти багато бачив і робив у цьому світі. Однак готовий посперечатися, що ти ніколи не бачив такого обладунку.\n\nЗроби мені невелику послугу, і я буду готовий обміняти його на звичайний набір браслетів.\n\nМені потрібен великий зразок отрути, витягнутої з павуків та скорпіонів, що мешкають у Силітусі. Принеси мені це разом з кількома золотими монетами, і я здійсню обмін.", [3] = "Здобудьте 15 зразків отрути Силітуса та 20 золота і принесіть їх разом із набором наручів доблесті Моквару в Орґріммарі.", [4] = "Ви отримали потрібні мені предмети, {ім'я}?", [5] = "Ах, так. Мукс буде цим цілком задоволений.\n\nЦі наручі були частиною більшого комплекту обладунків. Якщо ви зацікавлені в наданні мені подальшої допомоги, я готовий розглянути можливість розлучення з рештою.", ["en"] = "An Earnest Proposition" },
    [84171] = { [1] = "Гідна винагорода", [2] = "Ви виявилися дуже надійною людиною, {ім'я}. Хоча я й вірю, що ви допоможете мені вийти з цієї скрутної ситуації, було б мудро з мого боку винагородити вас відповідно до ваших результатів.\n\nА поки що я обміняю ваш пояс і рукавички. Якщо ми обидва впораємося з цим, я надаю вам решту речей.", [3] = "Принесіть Моквару в Орґріммар пояс Дикого Серця та комплект рукавичок Дикого Серця.", [4] = "Ви готові здійснити обмін?", [5] = "Наша угода залишається в силі. Пам'ятай, це лише мала частина того, що тебе чекає. Звільни мене від цієї проклятої долі, і я винагороджу тебе предметами справді великої сили.", ["en"] = "Just Compensation" },
    [84172] = { [1] = "Гідна винагорода", [2] = "Ви виявилися дуже надійною людиною, {ім'я}. Хоча я й вірю, що ви допоможете мені вийти з цієї скрутної ситуації, було б мудро з мого боку винагородити вас відповідно до ваших результатів.\n\nА поки що я обміняю ваш пояс і рукавички. Якщо ми обидва впораємося з цим, я надаю вам решту речей.", [3] = "Принесіть Моквару в Орґріммар пояс Звіроловця та комплект Рукавиць Звіроловця.", [4] = "Ви готові здійснити обмін?", [5] = "Наша угода залишається в силі. Пам'ятай, це лише мала частина того, що тебе чекає. Звільни мене від цієї проклятої долі, і я винагороджу тебе предметами справді великої сили.", ["en"] = "Just Compensation" },
    [84173] = { [1] = "Гідна винагорода", [2] = "Ви виявилися дуже надійною людиною, {ім'я}. Хоча я й вірю, що ви допоможете мені вийти з цієї скрутної ситуації, було б мудро з мого боку винагородити вас відповідно до ваших результатів.\n\nА поки що я обміняю ваш пояс і рукавички. Якщо ми обидва впораємося з цим, я надаю вам решту речей.", [3] = "Принесіть Моквару в Орґріммар пояс Магістра та комплект рукавичок Магістра.", [4] = "Ви готові здійснити обмін?", [5] = "Наша угода залишається в силі. Пам'ятай, це лише мала частина того, що тебе чекає. Звільни мене від цієї проклятої долі, і я винагороджу тебе предметами справді великої сили.", ["en"] = "Just Compensation" },
    [84174] = { [1] = "Гідна винагорода", [2] = "Ви виявилися дуже надійною людиною, {ім'я}. Хоча я й вірю, що ви допоможете мені вийти з цієї скрутної ситуації, було б мудро з мого боку винагородити вас відповідно до ваших результатів.\n\nА поки що я обміняю ваш пояс і рукавички. Якщо ми обидва впораємося з цим, я надаю вам решту речей.", [3] = "Принесіть Моквару в Орґріммарі Пояс побожності та комплект Рукавиць побожності.", [4] = "Ви готові здійснити обмін?", [5] = "Наша угода залишається в силі. Пам'ятай, це лише мала частина того, що тебе чекає. Звільни мене від цієї проклятої долі, і я винагороджу тебе предметами справді великої сили.", ["en"] = "Just Compensation" },
    [84175] = { [1] = "Гідна винагорода", [2] = "Ви виявилися дуже надійною людиною, {ім'я}. Хоча я й вірю, що ви допоможете мені вийти з цієї скрутної ситуації, було б мудро з мого боку винагородити вас відповідно до ваших результатів.\n\nА поки що я обміняю ваш пояс і рукавички. Якщо ми обидва впораємося з цим, я надаю вам решту речей.", [3] = "Принесіть Моквару в Орґріммар пояс Тіньової Ремесла та комплект Рукавиць Тіньової Ремесла.", [4] = "Ви готові здійснити обмін?", [5] = "Наша угода залишається в силі. Пам'ятай, це лише мала частина того, що тебе чекає. Звільни мене від цієї проклятої долі, і я винагороджу тебе предметами справді великої сили.", ["en"] = "Just Compensation" },
    [84176] = { [1] = "Гідна винагорода", [2] = "Ви виявилися дуже надійною людиною, {ім'я}. Хоча я й вірю, що ви допоможете мені вийти з цієї скрутної ситуації, було б мудро з мого боку винагородити вас відповідно до ваших результатів.\n\nА поки що я обміняю ваш пояс і рукавиці. Якщо ми обидва впораємося з цим, я надаю вам решту речей.", [3] = "Принесіть Моквару в Орґріммарі Шнур Стихій та набір Рукавиць Стихій.", [4] = "Ви готові здійснити обмін?", [5] = "Наша угода залишається в силі. Пам'ятай, це лише мала частина того, що тебе чекає. Звільни мене від цієї проклятої долі, і я винагороджу тебе предметами справді великої сили.", ["en"] = "Just Compensation" },
