    [84194] = { [1] = "Прощальні слова Антіона", [2] = "Душа Валталака зберігалася в цьому амулеті. У своїй жадібності ми нерозумно розділили її на три частини, не знаючи прокляття, яке нас чекатиме.\n\nЄдиний спосіб зупинити чари Валталака — це зібрати амулет назад. Поверніться до Моквара та скажіть йому, що Бодлі — його єдина надія знайти решту частин. Поговоріть з ним про будь-які нагороди, які ви домовилися.\n\nЯ, нарешті, спочиватиму з миром. Бажаю вам удачі; тобі знадобиться кожна її частинка!", [3] = "Поверніться до Моквара в Оргіммар з комплектом Чоботи Доблесті, Нагрудні пластини Доблесті та Наплечники Доблесті.\n\nНаданий предмет:", [4] = "Ти повернувся, і я бачу по твоїх очах, що тобі є багато чого мені розповісти, {ім'я}. Давай спочатку подбаємо про твою винагороду.", [5] = "Це прокляття було наслано на нас лише за медальйон. Лорд Валталак точно знає, як затаїти образу.\n\nМи спробуємо знайти решту фрагментів — сподіваємося, перш ніж я зустріну передчасну кончину. Але перед цим давайте подивимося, яка буде ваша нагорода.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Top Piece of Lord Valthalak's Amulet"] = "верхня частина амулету лорда Вальталака" } },
    [842] = { [1] = "Призов на Перехрестя", [2] = "Візьми цей підписаний вербувальний лист до Перехрестя.\n\nСерґра Темношип, хай їй трясця, там головна. Вона нудотна шаманка, яка запаморочить тобі мізки, перш ніж дозволити зробити хоч щось корисне. Тралл переконаний, що вона особлива, але я в тому не впевнений.\n\nТи вже {стать:сам:сама} маєш вирішити для себе, {стать:малий:мала}…", [3] = "Йдіть західною дорогою від Далекостежної застави Карґала.\n\nНа роздорожжі поверніть ліворуч і йдіть південним шляхом.\n\nЗнайдіть Серґру Темношип на перетині доріг в Перехресті.", [4] = "Так так так, що ми тут маємо? Карґал вирішив відзначити мене черговим новобранцем?", [5] = "Добре, {Ім'я}. Ти хочеш зробити свій внесок у справу Орди? Що ж, тут вдосталь роботи, тому слухай уважно і роби те, що тобі кажуть.\n\n{стать:Я бачу цей погляд у твоїх очах, не думай, що буду терпіти таку зухвалість. Тралл особисто оголосив жінок Орди рівними чоловікам. Ставитимешся до мене зневажливо, і відчуєш, що таке справжній біль.:Я рада, що зустріла тебе. Траллу буде приємно дізнатись, що дедалі більше жінок бере на себе ініціативу щодо розширення нашого впливу у Степах.}", ["en"] = "Crossroads Conscription", ["tasks"] = { ["Signed Recruitment Letter"] = "підписаний вербувальний лист", ["Signed Recruitment Letter (Provided)"] = "підписаний вербувальний лист (видано)" } },
    [84203] = { [1] = "Найкраще — наостанок", [2] = "Справді дивовижна історія, {ім'я}! Моя подяка, і щира подяка всіх, хто був причетний, запевняю вас. Завдяки вашим зусиллям ми позбавлені помилок минулого.\n\nЩодо вашої винагороди, я вважаю, що маю кілька речей, які ви точно заслужили і якими справді насолоджуватиметесь.", [3] = "Дайте Моквару свій клобук Дикого Серця та жилет Дикого Серця.", [4] = "Ти готовий віддати мені свої фігурки Дикого Серця в обмін на твій новий капюшон та жилет Дикого Серця?", [5] = "Я справді сумуватиму за тобою, {ім'я}. У мене є борг перед тобою, який я, можливо, ніколи не зможу повернути.\n\nНасолоджуйся своїм новим обладунком на голову та груди. Нехай він захищає тебе ще довго та допомагає тобі досягти ще більшої шани!", ["en"] = "Saving the Best for Last" },
    [84204] = { [1] = "Найкраще — наостанок", [2] = "Справді дивовижна історія, {ім'я}! Моя подяка, і щира подяка всіх, хто був причетний, запевняю вас. Завдяки вашим зусиллям ми позбавлені помилок минулого.\n\nЩодо вашої винагороди, я вважаю, що маю кілька речей, які ви точно заслужили і якими справді насолоджуватиметесь.", [3] = "Дайте Моквару свою шапку Звіроловця та туніку Звіроловця.", [4] = "Ти готовий віддати мені свої фігурки Звіроловця в обмін на твої нові Шапку та Туніку Звірогосподаря?", [5] = "Я справді сумуватиму за тобою, {ім'я}. У мене є борг перед тобою, який я, можливо, ніколи не зможу повернути.\n\nНасолоджуйся своїм новим обладунком на голову та груди. Нехай він захищає тебе ще довго та допомагає тобі досягти ще більшої шани!", ["en"] = "Saving the Best for Last" },
    [84205] = { [1] = "Найкраще — наостанок", [2] = "Справді дивовижна історія, {ім'я}! Моя подяка, і щира подяка всіх, хто був причетний, запевняю вас. Завдяки вашим зусиллям ми позбавлені помилок минулого.\n\nЩодо вашої винагороди, я вважаю, що маю кілька речей, які ви точно заслужили і якими справді насолоджуватиметесь.", [3] = "Дайте Моквару свою Корону Магістра та Мантію Магістра.", [4] = "Ти готовий віддати мені фігури свого Магістра в обмін на твою нову Чаклунську Корону та Мантії?", [5] = "Я справді сумуватиму за тобою, {ім'я}. У мене є борг перед тобою, який я, можливо, ніколи не зможу повернути.\n\nНасолоджуйся своїм новим обладунком на голову та груди. Нехай він захищає тебе ще довго та допомагає тобі досягти ще більшої шани!", ["en"] = "Saving the Best for Last" },
    [84206] = { [1] = "Найкраще — наостанок", [2] = "Справді дивовижна історія, {ім'я}! Моя подяка, і щира подяка всіх, хто був причетний, запевняю вас. Завдяки вашим зусиллям ми позбавлені помилок минулого.\n\nЩодо вашої винагороди, я вважаю, що маю кілька речей, які ви точно заслужили і якими справді насолоджуватиметесь.", [3] = "Дай Моквару свою побожну корону та побожну мантію.", [4] = "Ти готовий віддати мені свої Побожні взірці в обмін на твою нову Чеснотливу Корону та Мантію?", [5] = "Я справді сумуватиму за тобою, {ім'я}. У мене є борг перед тобою, який я, можливо, ніколи не зможу повернути.\n\nНасолоджуйся своїм новим обладунком на голову та груди. Нехай він захищає тебе ще довго та допомагає тобі досягти ще більшої шани!", ["en"] = "Saving the Best for Last" },
    [84207] = { [1] = "Найкраще — наостанок", [2] = "Справді дивовижна історія, {ім'я}! Моя подяка, і щира подяка всіх, хто був причетний, запевняю вас. Завдяки вашим зусиллям ми позбавлені помилок минулого.\n\nЩодо вашої винагороди, я вважаю, що маю кілька речей, які ви точно заслужили і якими справді насолоджуватиметесь.", [3] = "Дайте Моквару вашу Шапку Тіньової Ремесла та Туніку Тіньової Ремесла.", [4] = "Ти готовий віддати мені свої вироби Тіньової Ремесла в обмін на твою нову Темну Мантію та Туніку?", [5] = "Я справді сумуватиму за тобою, {ім'я}. У мене є борг перед тобою, який я, можливо, ніколи не зможу повернути.\n\nНасолоджуйся своїм новим обладунком на голову та груди. Нехай він захищає тебе ще довго та допомагає тобі досягти ще більшої шани!", ["en"] = "Saving the Best for Last" },
    [84208] = { [1] = "Найкраще — наостанок", [2] = "Справді дивовижна історія, {ім'я}! Моя подяка, і щира подяка всіх, хто був причетний, запевняю вас. Завдяки вашим зусиллям ми позбавлені помилок минулого.\n\nЩодо вашої винагороди, я вважаю, що маю кілька речей, які ви точно заслужили і якими справді насолоджуватиметесь.", [3] = "Дайте Моквару ваш Койф стихій та Жилет стихій.", [4] = "Ти готовий віддати мені свої частини Елементів в обмін на твій новий Капюшон та Жилет П'яти Громів?", [5] = "Я справді сумуватиму за тобою, {ім'я}. У мене є борг перед тобою, який я, можливо, ніколи не зможу повернути.\n\nНасолоджуйся своїм новим обладунком на голову та груди. Нехай він захищає тебе ще довго та допомагає тобі досягти ще більшої шани!", ["en"] = "Saving the Best for Last" },
    [84209] = { [1] = "Найкраще — наостанок", [2] = "Справді дивовижна історія, {ім'я}! Моя подяка, і щира подяка всіх, хто був причетний, запевняю вас. Завдяки вашим зусиллям ми позбавлені помилок минулого.\n\nЩодо вашої винагороди, я вважаю, що маю кілька речей, які ви точно заслужили і якими справді насолоджуватиметесь.", [3] = "Дайте Моквару свою Маску Жахливого Туману та Мантію Жахливого Туману.", [4] = "Ти готовий віддати мені свої фігурки з Туману Жаху в обмін на твою нову Маску та Мантію Смертного Туману?", [5] = "Я справді сумуватиму за тобою, {ім'я}. У мене є борг перед тобою, який я, можливо, ніколи не зможу повернути.\n\nНасолоджуйся своїм новим обладунком на голову та груди. Нехай він захищає тебе ще довго та допомагає тобі досягти ще більшої шани!", ["en"] = "Saving the Best for Last" },
    [84210] = { [1] = "Найкраще — наостанок", [2] = "Справді дивовижна історія, {ім'я}! Моя подяка, і щира подяка всіх, хто був причетний, запевняю вас. Завдяки вашим зусиллям ми позбавлені помилок минулого.\n\nЩодо вашої винагороди, я вважаю, що маю кілька речей, які ви точно заслужили і якими справді насолоджуватиметесь.", [3] = "Дайте Моквару свій Шолом Доблесті та Нагрудник Доблесті.", [4] = "Ти готовий віддати мені свої фігурки Доблесті в обмін на твій новий Шолом і Нагрудник Героїзму?", [5] = "Я справді сумуватиму за тобою, {ім'я}. У мене є борг перед тобою, який я, можливо, ніколи не зможу повернути.\n\nНасолоджуйся своїм новим обладунком на голову та груди. Нехай він захищає тебе ще довго та допомагає тобі досягти ще більшої шани!", ["en"] = "Saving the Best for Last" },
    [843] = { [1] = "Вороття Ґанна", [2] = "Я блукаю цими дорогами на самоті.\n\nДворфи Бель-Модана не виявляють і краплини поваги до моєї землі. Несамовиті вибухи пробивають глибокі діри в землі, а громохкі машини розпанахують пагорби. Земля, яка колись служила домом і годувальницею мого племені, тепер переповнена руйнівними дворфами.\n\nСпроби досягти консенсусу дипломатичним шляхом провалилися. Настав час рішучих дій.\n\nПрожени дворфів з розкопок Бель-Модана силою та принеси мені журнал їхнього керівника, розвідувача Хазґорма.", [3] = "Ґанн Кам'яний Шпиль просить вас вбити 15 бель'дунських копачів та 5 бель'дунських бригадирів.\n\nПоверніться до Ґанна Кам'яного Шпиля з журналом Хазґорма.", [4] = "Багато невинних тауренів загинули або були вимушені покинути батьківщину, коли сюди прибули дворфи Бель-Модана. Я маю повернути нашу землю!", [5] = "Хазґорм зустрів долю, на яку заслужив. В мене немає жалю для того телепня. Він не ставився з повагою до землі, на яку прийшов.\n\nНехай його смерть буде попередженням для всіх, хто планує порушити наше спокійне життя.\n\nА тепер, мені потрібно пару хвилин, щоб переглянути журнал дворфа...", ["en"] = "Gann's Reclamation", ["tasks"] = { ["Bael'dun Excavator"] = "бель'дунський копач", ["Bael'dun Excavator slain"] = "бель'дунський копач: убито", ["Bael'dun Foreman"] = "бель'дунський бригадир", ["Bael'dun Foreman slain"] = "бель'дунський бригадир: убито", ["Khazgorm's Journal"] = "журнал Хазґорма", ["Khazgorm's Journal (Provided)"] = "журнал Хазґорма (видано)" } },
    [844] = { [1] = "Гроза рівнинобігів", [2] = "Твоя перша здобич буде легкою.\n\nРівнинобіги, що водяться на сході, безперестанку зазіхають на наші запаси їжі та вже стоять нам у горлі.\n\nПеребий їх і повертайся до мене з дзьобами.", [3] = "Зберіть 7 дзьобів рівнинобігів і принесіть їх Серґрі Чорношип на Перехрестя.", [4] = "Ти {стать:назбирав:назбирала} дзьоби рівнинобігів?", [5] = "Дуже добре, {ім'я}. Без рівнинобігів нам буде легше контролювати поставки провіанту. І я сподіваюся, що ти {стать:навчився:навчилась} кільком хитрощам там, у Степах, бо твоя наступна здобич трохи більш норовиста за рівнинобігів...", ["en"] = "Plainstrider Menace", ["tasks"] = { ["Plainstrider Beak"] = "дзьоб рівнинобіга", ["Plainstrider Beak (Provided)"] = "дзьоб рівнинобіга (видано)" } },
    [84405] = { [1] = "Втрачена реліквія", [2] = "Перш ніж чума мене перевернула, я був досить важливим торговцем в Андоралі. Місто, ймовірно, поховало моє колишнє багатство та сімейні записи в крипті Гора Скорботи, коли вважало мене зниклим.\n\nЧи не могли б ви забрати мої речі з крипти та повернути їх мені?", [3] = "Заберіть сімейні реліквії з крипти Пагорба Скорботи у Західних Чумних землях, а потім поверніться до Дітріха Прейса в Орґріммар.", [4] = "Ти повернувся з Чумних земель?", [5] = "Дякую, {ім'я}. Ви кажете, що знайшли журнал?", ["en"] = "Lost Heirloom" },
    [84406] = { [1] = "Реліквія Світла", [2] = "Ця зброя світла, описана в журналі, мене непокоїть. Якби Червоний Хрестовий Похід або Альянс отримали таку річ, це могло б стати серйозною загрозою для Відреклих.\n\nБільшість збережених записів з Андоралу знаходяться під захистом Червоного Хрестового Походу в Хартглені. Пошукайте в них і подивіться, чи зможете ви знайти більше інформації.", [3] = "Вирушайте до Долини Підземного Вогнища у Західних Чумних Землях та знайдіть інформацію про артефакт, описаний у журналі.", [5] = "Цей реєстр, схоже, містить записи про діяльність Скарлет у Чумних землях.", ["en"] = "Relic of Light" },
    [84407] = { [1] = "Приз всередині", [2] = "Зсередини скриньки випромінюється сила. Це, мабуть, той артефакт! Тепер тобі просто потрібно його відкрити...", [3] = "Знайдіть спосіб відкрити скриньку та отримати артефакт, а потім доставте його Дітріху Прейсу в Орґріммар.\n\nНаданий предмет:", [4] = "Що ти знайшов, {ім'я}?", [5] = "Отже, історія була правдивою... Я буду триматися за це та досліджувати її потенціал. Не тільки наші вороги позбавлені цієї зброї, але й у наших руках вона може стати потужним захистом від Скотію.\n\nПрийміть це, {ім'я}, з моєю подякою.", ["en"] = "The Prize Within", ["tasks"] = { ["Puzzle Box"] = "Коробка-головоломка" } },
    [84408] = { [1] = "Дипломатичні пропозиції", [2] = "{ім'я}, вивчаючи уламок світла, який ти приніс, я бачив видіння. Я бачу, як жрець Альянсу знаходить подібний уламок, і я бачу, як Альянс та Орда об'єднуються у хвилі світла.\n\nНа жаль, Альянс продовжує ставитися до нас як до не більш ніж паразитів.\n\nЯ пропоную скласти дипломатичний подарунок як жест доброї волі між вірами. Принесіть мені ці припаси, і ми подивимося, чи зможемо ми розпочати діалог між нашими людьми.", [3] = "Зберіть припаси та доставте їх Дітріху Прейсу в Орґріммар.", [4] = "У вас є необхідні матеріали?", [5] = "Я спробую знайти спосіб доставити це до Штормовія.\n\nУ мене також є дещо для тебе — цей тотем забезпечить зцілення членам Альянсу, що знаходяться поблизу. Акти служіння можуть подолати прірву там, де слова підводять нас.", ["en"] = "Diplomatic Overtures" },
    [84410] = { [1] = "Святиня співпраці", [2] = "Панель біля основи статуї висувається, відкриваючи шматок пергаменту та блискучий кристал, схожий на той, який ви знайшли в Руці Тіра.", [3] = "Доставте кристал Дітріху Прайсу в Орґріммар.", [4] = "У тебе є для мене новини?", [5] = "Ще один уламок світла! Де ти це знайшов, {ім'я}?\n\nЯ згоден з автором. Якщо уламки можна використовувати як зброю проти живих, а також проти {раса}, вони можуть ескалувати конфлікт між Альянсом та Ордою до жахливих масштабів.", ["en"] = "Shrine of Cooperation", ["tasks"] = { ["Shard of Light"] = "Уламок світла" } },
    [84411] = { [1] = "Дипломатське кільце", [2] = "Дипломатичний подарунок, який ви зібрали, дійшов до Верховної Жриці Лорени у Штормовії, і я дискретно зв'язався з ними. Ми обидві погоджуємося, що цей пошук слід тримати в таємниці вірних. Якщо осколки можна використовувати як зброю, краще, щоб вони не потрапляли до рук лідерів жодної з фракцій.\n\nМи розробили таємний спосіб ідентифікації для тих, хто шукає осколки. Принесіть мені матеріали для виготовлення кільця, яке міститиме шматочок одного з осколків.", [3] = "Принесіть запитувані матеріали Дітріху Прайсу в Орґріммар.", [4] = "Вирізка з черепка готова, {ім'я}. У вас є інші матеріали?", [5] = "<За допомогою зручного швидкого заклинання Дітріх трансмутує матеріали та камінь, вирізаючи кільце>\n\nНа жаль, це було найлегше.", ["en"] = "Diplomat Ring" },
    [84412] = { [1] = "Дипломатична місія", [2] = "Ваше наступне завдання буде досить складним, {ім'я}.\n\nВи повинні зв'язатися зі жерцем Альянсу, який шукає осколки. Ви впізнаєте одне одного за допомогою своїх кілець. Вони супроводять вас до собору Штормовія, де вам потрібно буде поговорити з Верховною жрицею Лореною.\n\nЯкщо ви зможете переконати жерців Альянсу в мирних намірах, у нас може бути шанс возз'єднати осколки.", [3] = "Зв'яжіться зі Жрецем Альянсу біля воріт Штормовія та отримайте Дипломатичний Імунітет, використовуючи свої Дипломатичні Кільця один на одному. Потім увійдіть до Собору Штормовія та поговоріть з Верховною Жрицею Лореною. Ви втратите Дипломатичний Імунітет, якщо відійдете занадто далеко від Жреця-супроводжуючого або вступите в бій.", [5] = "Ви, мабуть, той {клас}, якого мені сказали очікувати. Сподіваюся, мої співвітчизники були ввічливими, якщо не привітними.", ["en"] = "A Diplomatic Mission" },
    [84413] = { [1] = "Ремонт осколка", [2] = "Я готовий повірити, що ви тут з доброю волею, {клас}.\n\nМи відкриті до зустрічі між нашими людьми. Але уламок світла, який ми маємо, у поганому стані. Ми повинні поповнити його, перш ніж намагатися об'єднатися з іншими.\n\nДревні Високородні того, що зараз є Забутим Молом, вміли маніпулювати таємною та священною енергією. Ідіть туди та знайдіть будь-яку інформацію, яку можете, про артефакти світла, а потім поверніться до мене.", [3] = "Заберіть книгу «Прикладна богослов'я» з Затятого Молу, а потім поверніться до Верховної жриці Лорени в Штормовійському соборі.\n\nЩоб потрапити до Штормовію, вам знадобиться допомога жерця Альянсу з перснем дипломата, щоб отримати дипломатичний імунітет. Ви втратите дипломатичний імунітет, якщо відійдете занадто далеко від свого жерця-супроводжуючого або вступите в бій.", [4] = "Ви повернулися, {клас}?", [5] = "Це має допомогти відремонтувати уламок. Настав час покласти цьому край.", ["en"] = "Repairing the Shard" },
    [845] = { [1] = "Жеври", [2] = "Жеври, хоч і не найлихіші звірі Степів, все ж сильніші за рівнинобігів. Не хвилюйся: настане час, і ми пошлемо тебе по більшу здобич, але поки що тобі варто трохи попрактикуватись.\n\nУполюй жевр, на півночі та півдні, та позбирай їхні копита. Принеси їх мені, і, можливо, наступного разу ми оберемо тобі небезпечнішого звіра.", [3] = "Убивайте жевр-скакунів, поки не назбираєте 4 копита жеври для Серґри Темношип на Перехресті.", [4] = "Скільки жевр ти {стать:забив:забила}?", [5] = "Непогано, {ім'я}. Жеври мають багато сили у своїх ногах. Різкий удар від них може завалити на дупу навіть таурена!\n\nСхоже, в тобі теж є трохи сили. Ти {стать:готовий:готова} до справжнього виклику?", ["en"] = "The Zhevra", ["tasks"] = { ["Zhevra Hooves"] = "копита жеври", ["Zhevra Hooves (Provided)"] = "копита жеври (видано)" } },
    [84561] = { [1] = "Щоб усі бачили", [2] = "Повелитель Рунтак чекає на ваше прибуття в Долину Сили.\n\n<Тралл салютує вам.>\n\nНе змушуйте свою публіку чекати, герою.", [3] = "Знайдіть повелителя Рунтака в Долині Сили.", [5] = "Оберіть свою нагороду та нехай розпочнеться святкування вашої славної перемоги.", ["en"] = "For All To See" },
    [846] = { [1] = "Помста Ґанна", [2] = "Зрозуміло, що розвідувач покладався на вибухівку та на ті гуркітливі машини, щоб розривати землю. Думаю, незабаром сюди пришлють нового бригадира.\n\nЯ хочу відплатити дворфам їхньою ж монетою. Згідно з цими схемами, якщо поєднати нітрогліцерин з целюлозою та нітратом натрію, ми зможемо створити вибуховий заряд. Усі ці компоненти можна знайти у стрільців, солдатів та офіцерів у фортеці.\n\nЗбери все необхідне та принеси мені. Я змайструю таку вибухівку, яку дворфи ніколи не забудуть!", [3] = "Ґанн Кам'яний Шпиль просить вас принести йому 6 флаконів нітрогліцерину, 6 пучків целюлози та 6 зразків нітрату натрію.", [4] = "Я бачу, ти {стать:повернувся:повернулася}, {ім'я}.\n\nМожливо смерть Хазґорма й відстрочить ненадовго розкопки на землі моїх пращурів, проте ні в якому разі не призведе до повного припинення руйнування.\n\nФортеця Бель-Модана — це військова загроза, що невпинно росте. Її збудували для захисту розкопок, але тепер вона стала плацдармом для воєнних дій.\n\nЯкщо ти збереш всі необхідні компоненти, я зможу створити запал, який змусить дворфів переглянути свої плани на Степи.", [5] = "Я бачу, що ти доволі {стать:завзятий:завзята} {клас:н}.\n\nНезабаром дворфи отримають сюрприз, на який заслуговують.", ["en"] = "Revenge of Gann", ["tasks"] = { ["Nitroglycerin"] = "нітрогліцерин", ["Nitroglycerin (Provided)"] = "нітрогліцерин (видано)", ["Sodium Nitrate"] = "нітрат натрію", ["Sodium Nitrate (Provided)"] = "нітрат натрію (видано)", ["Wood Pulp"] = "целюлоза", ["Wood Pulp (Provided)"] = "целюлоза (видано)" } },
    [847] = { [1] = "Підступність раптора", [2] = "Ця... Сила... Це і є сила шаманів, яку мені намагався показати Тор'ґан? Мушу визнати, це цікаво. Скажи Тор'ґану, що він мене переконав... поки що. Я вислухаю його.", [3] = "Поговоріть з Тор'ґаном.", [5] = "Коли чари спадуть, я з ним поговорю. Дякую тобі за допомогу в поверненні Ґор'мула до життя. Я не сумніваюся, що він також дуже вдячний тобі.", ["en"] = "Guile of the Raptor" },
    [848] = { [1] = "Спори грибів", [2] = "Оазиси Степів приховують таємницю. Життєва енергія тече в їхніх водах, що живить рослини та звірів, які її п'ють.\n\nЖивить і змінює.\n\nБіля цих оазисів водиться особливий гриб. Його спори мають деякі властивості, які ми, аптекарі Лордерона, вважаємо корисними.\n\nПринеси мені ці спори, а ми тобі щедро віддячимо.", [3] = "Принесіть 4 спори грибів аптекарю Гелбріму на Перехрестя.", [4] = "Ти {стать:дістав:дістала} спори, {ім'я}? У Громовому Бескиді моя колега чекає на концентрат відвару, що я маю зготувати, тож мені конче необхідні спори...", [5] = "О-о, так. Які чудові зразки. Дозрілі.\n\nЯ з відречених, а ми слів на вітер не кидаємо. Ось твоя нагорода, {ім'я}.", ["en"] = "Fungal Spores", ["tasks"] = { ["Fungal Spores"] = "спори грибів", ["Fungal Spores (Provided)"] = "спори грибів (видано)" } },
    [8485] = { [1] = "Посередник миру", [2] = "Твої подвиги вищі за будь-які похвали, {ім'я}. Якщо ти представляєш свій народ, то ми хотіли б укласти з ним мир.\n\nБудь ласка, віднеси цей дар до воєвождя орків, що мешкає в землях Дуротару. Гадаю, ви називаєте це місто Орґріммар. У минулому він намагався укласти з нами союз від імені Орди. Тож тепер цілком доречно довірити тобі завершити цю справу.", [3] = "Віднесіть дар Деревопузих Траллу в Орґріммар.", [4] = "Воєвождь вітає тебе, {клас:к}. Твої вчинки зміцнюють Орду в ці тривожні часи. А тепер, які справи привели тебе до мене?", [5] = "Це справді вдалий поворот подій. Якщо ми матимемо стійкий мир з цими істотами, це, безумовно, дасть нам перевагу у забезпеченні безпеки Калімдору від зовнішніх загроз. Я повідомлю про це інших лідерів Орди, і ми відправимо більше дипломатів!\n\nЩодо тебе, {ім'я}... ти {стать:проявив:проявила} мужність як у дипломатії, так і у своїх діяннях. Я і вся Орда вдячні тобі.", ["en"] = "The Brokering of Peace", ["tasks"] = { ["42000 reputation with Timbermaw Hold"] = "42000 репутації у фортеці Тимбермау", ["Timbermaw Offering of Peace"] = "дар Деревопузих", ["Timbermaw Offering of Peace (Provided)"] = "дар Деревопузих (видано)" } },
    [849] = { [1] = "Помста Ґанна", [2] = "Слідуючи плану Хазґорма, створити вибухівку буде не складно.\n\nА, ось і готово!\n\nТепер, {ім'я}, я збираюся доручити тобі дуже особливе завдання. Візьми цю вибухівку і скористайся нею, щоб підірвати літальний апарат в Бель-Модані.\n\nМало того, що літальний апарат є ключовою частиною інфраструктури розкопок, його також використовують у військових цілях. А ще важливіше те, що цей літальний апарат — символ могутності дворфів і образа пам'яті мого племені.\n\nЗроби так, щоб я пишався тобою. Виконай це героїчне завдання — і будеш щедро {стать:винагороджений:винагороджена}.", [3] = "Зруйнуйте літальний апарат в Бель-Модані та поверніться до Ґанна Кам'яного Шпиля.", [4] = "Як тільки літальний апарат дворфів буде знищений, я відчую солодкий присмак помсти.", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}! Нехай тебе цінують у Громовому Бескиді як {стать:захисника:захисницю} священних земель тауренів та {стать:поборника:поборницю} загубленого племені.", ["en"] = "Revenge of Gann", ["tasks"] = { ["Bael Modan Flying Machine destroyed"] = "Літальний апарат Баель Модан знищено" } },
    [850] = { [1] = "Лідери Колкарів", [2] = "Кентаври багато років дошкуляють тауренам. А останнім часом клан Колкар зі Степів перетворився на справжню загрозу. Зазвичай, місцеві з цих істоти - дезорганізовані, але в їхніх рядах з'явилися нові лідери, згуртовуючи їх.\n\nЗаради збереження нашого осередку тут, цих кентаврських лідерів необхідно знищити.\n\nПринеси мені голову Барака Кодобоя. Він облаштував табір біля Забутих ставів, що на півночі.\n\nЗдолай його, потому повертайся до мене.", [3] = "Принесіть голову Барака Реґтарові Згубобрамі західніше Перехрестя.", [4] = "Вітаю, {ім'я}. Маєш голову Барака?", [5] = "Блискуче, {ім'я}. Кентаври - примітивні, тупоголові істоти, але деякі мають достатньо кмітливості та ідей для лідерства. І такі - найнебезпечніші.\n\nБарак був таким кентавром. Добре, що він мертвий.", ["en"] = "Kolkar Leaders", ["tasks"] = { ["Barak's Head"] = "Голова Барака", ["Barak's Head (Provided)"] = "Голова Барака (видано)", ["Barak's Head slain"] = "Голова Барака: убито" } },
    [851] = { [1] = "Вероґ-Дервіш", [2] = "Кентавр Вероґ-Дервіш блукає по Степах, і його досить важко знайти. Але він живе у наметі командування кентаврів у Застійному оазисі на південному сході. Можливо, тобі вдасться виманити його до себе.\n\nПрямуй до Застійного оазису на південний схід і атакуй кентаврів, що тиняються поблизу командного намету. Це вкрай небезпечно, але якщо ти зможеш вбити чимало тих істот - вони піднімуть тривогу. І на поклик прийде Вероґ.\n\nПринеси мені його голову, щоб я поклав її поруч із Бараковою.", [3] = "Принесіть голову Вероґа Реґтарові Згубобрамі на захід від Перехрестя.", [4] = "Ти {стать:знайшов:знайшла} Вероґа, {ім'я}?", [5] = "Дуже добре. Певно, ти по-справжньому {стать:сполохав:сполохала} всіх кентаврів: наші вартові помітили активність близ Застійного оазису, певно, викликану тобою.\n\nТобі варто пишатися своєю роботою, {Ім'я}. У тобі багато сміливості.", ["en"] = "Verog the Dervish", ["tasks"] = { ["Verog's Head"] = "голова Вероґа", ["Verog's Head (Provided)"] = "голова Вероґа (видано)" } },
    [852] = { [1] = "Гезрул Кровослід", [2] = "Гезрул Кровослід - лідер кентаврів клану Колкар в Степах. Він лютий, жорстокий і лукавий. Його кончина підірве і зламає Колкарів, значно зменшивши їхню загрозу для нас.\n\nТак що вбий його. І нехай голова Гезрула приєднається до Баракової і Вероґової.\n\nВін керує своїми послідовниками з оазису Рясноводдя, що на південь звідси.", [3] = "Принесіть голову Гезрула Реґтарові Згубобрамі на захід від Перехрестя.", [4] = "Ти {стать:здолав:здолала} Гезрула, {ім'я}?", [5] = "Хвалю тебе, {ім'я}. Ці кентаври недисципліновані та не можуть сконцентрувати свою лють так, як орки, але все-таки вони завзяті. У перемозі над ними ти ще раз {стать:продемонстрував:продемонструвала} свою доблесть.", ["en"] = "Hezrul Bloodmark", ["tasks"] = { ["Hezrul's Head"] = "голова Герзула", ["Hezrul's Head (Provided)"] = "голова Герзула (видано)" } },
    [853] = { [1] = "Аптекарка Зама", [2] = "Я переробив спори, що ти мені {стать:дав:дала}, в емульсію. Тепер час відправити їх моїй колезі, аптекарці Замі. Якщо віднесеш їй пакунок, то отримаєш у нагороду щось із наших алхімічних запасів.\n\nТи знайдеш її в Джерелах Видіння, печері під місцем зібрання шаманів Громового Бескиду. Шлях до цієї печери добре прихований, але ти знайдеш його біля Верхів'я Духів.\n\nПоспішай! Ефективність моєї емульсії досить швидкоплинна, тож її слід обробити та перекоркувати якомога швидше.", [3] = "Віднесіть оброблені спори аптекарці Замі до Громового Бескиду, доки не спливе наданий на це час.", [4] = "Ти {стать:приніс:принесла} щось від аптекаря Гелбріма?", [5] = "О-о, спори із Степів, які збирав сам Гелбрім. Ти {стать:допоміг:допомогла} йому доставити їх? Добре.\n\nА емульсія все ще дієва. Бачу, що ти не {стать:ловив:ловила} ґав по дорозі сюди. Молодчага, {клас:к}.", ["en"] = "Apothecary Zamah", ["tasks"] = { ["Rendered Spores"] = "оброблені спори", ["Rendered Spores (Provided)"] = "оброблені спори (видано)" } },
    [854] = { [1] = "Подорож до Перехрестя", [2] = "Я передбачив твій прихід, {стать:юний:юна} {клас:к}. Хоча, можливо, ти вже не {стать:такий юний:така юна}, як раніше.\n\nГадаю, тобі час піти вглиб цієї землі. Я відчуваю, що тобі судилися великі діяння.\n\nПерехрестя, ось що ти маєш знайти. Наші життя переплетені з життями орків, і вони потребують нашої допомоги. Йди далі по цій дорозі на схід і прямуй нею на північ до Перехрестя. Знайди Торка за його стінами, він несе благословіння Матері-Землі.", [3] = "Поговоріть з Торком у Перехресті, що у Степах.", [5] = "Як добре, що все більше союзників нашої раси приходять допомогти нам з такої далечини, як Громовий Бескид. Вітаю тебе.", ["en"] = "Journey to the Crossroads" },
    [855] = { [1] = "Наручі кентаврів", [2] = "Плем'я Колкар загрожує пануванню Орди у Степах, тому ми повинні зменшити чисельність їхніх військ. Тобто, пора відрядити тебе полювання.\n\nВирушай на території Колкарів, убий якомога більше їхніх воїнів і позбирай кентаврські наручі. Повертайся, коли у тебе буде ціла купа трофеїв, і Орда тебе щедро винагородить.", [3] = "Принесіть 15 наручів кентаврів Реґтарові Згубобрамі на захід від Перехрестя.", [4] = "Як твоє полювання, {ім'я}?", [5] = "Чудова робота. Я впевнений, що ти {стать:нагнав:нагнала} страху на кентаврів, що вижили, {ім'я}. Якщо у них є здоровий глузд, вони заспокояться та припинять свої атаки.\n\nАле, щось мені каже, що вони не отямляться. Прикро.\n\nПрикро... для них.", ["en"] = "Centaur Bracers", ["tasks"] = { ["Centaur Bracers"] = "наручі кентаврів", ["Centaur Bracers (Provided)"] = "наручі кентаврів (видано)" } },
    [85555] = { [1] = "Хеві-метал", [2] = "Великий плоский диск елементію, який ви тримаєте перед собою, ніби пульсує від стихійної енергії. Коли ви тримаєте його, ви майже чуєте, як духи стихій шепочуть вам щось. Ви не впевнені, яке застосування ви можете знайти для цього, але зв'язок, який ви відчуваєте з ним, миттєвий.\n\nЗ невеликими зусиллями достатньо талановитого коваля, здатного працювати з таємничим металом, відомим як елементій, ви підозрюєте, що з нього можна зробити зброю або обладунки.", [3] = "Знайдіть когось, хто вміє працювати з екзотичними металами та готовий допомогти вам створити щось особливе з цього шматка елементію.", [4] = "Що це у тебе там є?", [5] = "Ого! Який у тебе там шмат металу, {клас}.\n\nЕлементій, кажеш? Як ти взявся за щось таке? Насправді, мабуть, краще, якщо я не знаю. У будь-якому разі, я знаю хлопця, який міг би допомогти тобі зробити з нього щось хороше. Звати його Крікс. Останній раз я чув, що він працює в Чорній Горі на хлопця на ім'я, хм, Вік, здається. Не знаю, чим його найняли, але вони не зовсім в'яжуть светри в тій горі, якщо ти розумієш, до чого я.", ["en"] = "Heavy Metal", ["tasks"] = { ["Item #231995"] = "Товар №231995" } },
    [85556] = { [1] = "Певний набір навичок", [2] = "Крікс, безперечно, геній, але він може бути не дуже доброзичливим, якщо ви просто увірветесь у ту гору, вимагаючи його допомоги, не кажучи вже про головорізів, якими це місце, ймовірно, кишить. Вам, ймовірно, захочеться знайти спосіб дістатися до нього, не спалюючи все це місце по дорозі, що, ймовірно, буде досить складно.\n\nЯкщо ви зможете придумати спосіб потрапити туди, не зарізавши, не вразивши струмом і не обпаливши когось, це, мабуть, гарний початок. У мене самого немає жодних ідей, як це зробити, тож удачі!", [3] = "Знайдіть спосіб потрапити до Лігва Чорнокрилих та поговорити з Майстром-Формувальником Стихій Кріксіксом, не вступаючи з ним у бій.", [4] = "Хіба тобі не слід працювати, коханий?", [5] = "Чого тобі треба, хіба ти не бачиш, що я тут зайнятий? Зачекай, де ти взяв цей шматок шлаку? Клянусь, якщо ці недоумки в лабораторії марнують мій продукт, я його зіпсую!\n\nТак-так, я впевнений, що міг би зробити з нього щось корисне для тебе, але я відстаю від графіка, а Вік не відомий своїм терпінням. Тепер, якщо ти не допоможеш мені клонувати себе або виростити купу додаткових рук, то йди геть. У мене є робота.", ["en"] = "A Particular Set of Skills", ["tasks"] = { ["Item #231995"] = "Товар №231995" } },
    [85603] = { [1] = "Палкі обійми вуду", [4] = "Занза може створювати стародавні чари тролів за допомогою правильних компонентів.\n\nПерше — це первісний ідол Хаккарі, якого потрібно взяти у наймогутніших лейтенантів Хаккарі: Джін'до та Кривавого Володаря.\n\nДруге — це проколота лялька вуду. Її можна знайти в купах сміття, що засмічують це гидке місце. Зазирни всередину куп проклятих вуду.\n\nПринеси мені ці речі, і я створю для тебе потужні чари!", [5] = "Використовуй це добре, {клас}. Не проявляй милосердя до Хаккарі!", ["en"] = "Vodouisant's Vigilant Embrace" },
    [85604] = { [1] = "Ясне видіння Вудрії", [4] = "<Мейвікі вказує на твій талісман.>\n\nПодивись на нього, {ім'я}! Він ожив. Духи танцюють навколо кулі.\n\nВіддай його Мейвікі, щоб вона могла зробити останнє налаштування.", [5] = "Одного дня, {ім'я}, ти зможеш використовувати цю сферу для безпосереднього спілкування зі мною. Щойно ця битва з Хаккаром закінчиться і Мейвікі повернеться додому, давайте закличемо духів і попросимо їх, щоб цей день настав швидше.", ["en"] = "The Unmarred Vision of Voodress" },
    [85605] = { [1] = "Взірці могутності: браслети авгура", [2] = "Авгурів нашого племені шанують за їхні дари божественного бачення, друже. Вони не знахарі; вони проводять свій час, кидаючи кістки або читаючи листя для осяяння, а не заклинаючи людей. Як шаман, ти вже дещо знаєш про силу ворожіння; ми, Зандалар, цінуємо розуміння, яке вони дають племені.\n\nПринеси мені жертву Взірців Сили з Зул'Ґуруба та доведи нам свою цінність. Зроби це для нас, і я дам тобі кілька наручів, які наші авгури цінують понад усе!", [3] = "Принесіть Мейвікі Зулдазара Первісну Хаккарську Нарукавну Шину. Ви також повинні мати репутацію, рівну або вищу, ніж Дружні з Плем'ям Зандалар.\n\nМейвікі Зулдазара розташована на острові Йоджамба, Терниста Долина.", [4] = "Отримав у Зул'Ґуруба потрібні мені Взірці Сили? Ці наручі варті будь-яких зусиль, які тобі доведеться докласти!", [5] = "Здається, у тобі є трохи зандаларського віщуна. Ми знаємо про вчинки, які ти зробив у Зул'Ґурубі від нашого імені, друже. Ці Взірці Сили дуже допоможуть племені Зандалар — племені, до якого, додам я, ти можеш звернутися як до друзів. Візьми ці наручі, {ім'я}; ти їх заслужив, та ще й більше!", ["en"] = "Paragons of Power: The Augur's Bracers" },
    [85606] = { [1] = "Взірці могутності: пояс авгура", [2] = "Авгури знають чари стихій, друже. Вони використовують їх як засіб, щоб привести плем'я до слави. У темні дні після того, як Імперія Гурубаші розвалилася, наші авгури привели нас до безпечної гавані в Південних морях. Вони також привели нас назад сюди, до Долини, прямо до серця зла, що вирує в Зул'Ґурубі.\n\nПринеси мені жертву Взірців Сили з Зул'Ґуруба та доведи нам свою цінність. Зроби це, і я дам тобі пояс, який використовують наші авгури — той, що з потужними чарами всередині!", [3] = "Принесіть Мейвікі Зулдазара Первісний пояс Хаккарі. Ви також повинні мати репутацію, що дорівнює або вища за «Шановний у племені Зандалар».\n\nМейвікі Зулдазара розташована на острові Йоджамба, в Тернистій долині.", [4] = "Взірці Сили — це те, що мені потрібно, друже — ми вичерпаємо з них силу в нашій боротьбі зі злом із Зул'Ґуруба. У тебе є вони для мене?", [5] = "Я відчуваю на тобі запах переможеного зла, {ім'я}. Це солодкий запах, друже... гадаю, ти його добре знаєш.\n\nЯ знаю, що це немалий подвиг — принести мені Взірці Сили, необхідні для пояса. Твої вчинки не лише вшанували плем'я, а й тебе вшанували серед мого племені. Ось тобі — візьми пояс авгура та одягни його як свій!", ["en"] = "Paragons of Power: The Augur's Belt" },
    [85607] = { [1] = "Взірці могутності: гауберк авгура", [2] = "Авгури Зандалару носять особливий нагрудник, який називається хауберк. Він виготовлений з найкращого шовку та тканини, переплетений міцним ланцюгом. Це символ не лише їхньої божественності, а й їхньої влади, друже. Ніколи не мудро перечити тому, чиє життя присвячене розмовам з духами...\n\nПринеси мені жертву Взірців Сили з Зул'Ґуруба та доведи нам свою цінність. Зроби це, і я дам тобі один з найкращих хауберків, які наші авгури коли-небудь сподівалися б носити!", [3] = "Принесіть Мейвікі Зулдазара Первісний гербовий накидок Хаккарі. Ви також повинні мати репутацію, що дорівнює або вища за «Шановний» у племені Зандалар.\n\nМейвікі Зулдазара розташована на острові Йоджамба, в Тернистій долині.", [4] = "Взірці Сили — ключове джерело магічної сили — тієї самої сили, яка використовується для виготовлення хауберка авгура. Принесіть мені те, що мені потрібно, і я зможу поділитися найкращим облаченням, яке будь-який зандаларський авгур забажає собі.", [5] = "Я знаю, через що тобі довелося пройти, щоб принести мені Взірці Сили, {ім'я}. Це було нелегко, друже — перемогти зло, що просочується з Зул'Ґуруба, як гидкий слиз, — але тепер, коли все сказано і зроблено, я можу легко сказати, що тебе шануватимуть серед Зандаларів ще багато років!\n\nОсь — візьми хауберк авгура та носи його з гордістю!", ["en"] = "Paragons of Power: The Augur's Hauberk" },
    [85644] = { [1] = "Повелитель Чорнокамінної гори", [2] = "Знайдіть Верховного Повелителя Саурфанга в Долині Сили.", [3] = "Поговоріть з Верховним Повелителем Саурфангом в Орґріммарі. Він чекає на вас у Долині Сили.", [5] = "Обери собі нагороду, щоб я міг зійти на голову звіра на загальний огляд.", ["en"] = "The Lord of Blackrock" },
    [85658] = { [1] = "Щоб усі бачили", [2] = "Повелитель Рунтак чекає на ваше прибуття в Долину Сили.\n\n<Тралл салютує вам.>\n\nНе змушуйте свою публіку чекати, герою.", [3] = "Знайдіть повелителя Рунтака в Долині Сили.", [5] = "Оберіть свою нагороду та нехай розпочнеться святкування вашої славної перемоги.", ["en"] = "For All To See" },
    [857] = { [1] = "Сльоза Місяця", [2] = "Її сила була в моїх руках! В моїх руках! І я хочу повернути її! Повернути, кажу!\n\nЦі брудні копачі відкопали її... і вона була прекрасна. Її назвали Сльозою Місяця — це було перше велике відкриття, яке ми зробили в Бель-Модані.\n\nВона мала бути моєю! Моєю, кажу!\n\nГенерал Двокосий заздрив силі, яку вона давала мені. Він замкнув її у фортеці. Сказав, що вона проклята! Дурень!\n\nІнші теж хотіли отримати її, і я мав їх зупинити! А цей виродок, Двокосий, вигнав мене.\n\nТепер я хочу повернути її. Повернути, кажу!", [3] = "Фіґлі Вигнанець просить вас повернути йому Сльозу Місяця.", [4] = "Де Сльоза Місяця? Вона потрібна мені! Потрібна, кажу!", [5] = "Нарешті, її сила знову моя! Моя, кажу!", ["en"] = "The Tear of the Moons", ["tasks"] = { ["Tear of the Moons"] = "Сльоза Місяця", ["Tear of the Moons (Provided)"] = "Сльоза Місяця (видано)" } },
    [85702] = { [1] = "Шкірництво драконячої луски", [2] = "Шкіряна справа з луски дракона нелегка, але надзвичайно корисна. Я навчу вас, як виготовляти ці вишукані кольчужні обладунки, але лише якщо ви погодитеся на певні умови.\n\nОбираючи цей шлях, ви погоджуєтеся ніколи не вивчати елементарну чи племінну шкіряну справу; на вершині ремесла є місце лише для одного з трьох. Крім того, мені знадобляться деякі зразки вашої найкращої роботи, пов'язаної з обладунками скорпідів. Нарешті, мені знадобиться доказ вашої здатності отримати основний матеріал ремесла: луску драконів.", [3] = "Принесіть 2 міцні нагрудники скорпіда, 2 міцні рукавички скорпіда та 10 зношених лусок дракона Торкафу Драконячому Оку в Безплідних землях.\n\nВиконання цього завдання надасть вам доступ до мистецтва обробки шкіри з луски дракона.\n\nВиконання цього завдання не дозволить вам вивчити елементарну та племінну обробки шкіри; переконайтеся, що це саме той шлях, яким ви хочете піти, перш ніж робити це.", [4] = "Якщо ти готовий прийняти остаточне рішення, ставши шкіряником з драконячої луски, тоді я готовий взяти тебе в учні. Просто принеси мені те, що я просив, і ми розпочнемо твоє навчання.", [5] = "Повірте, потрібна сильна воля, щоб прийняти остаточне рішення, як ви щойно зробили. Запевняю вас, обробка шкіри з драконячої луски виявиться для вас прибутковим та винагороджуючим шляхом.\n\nЩоб навчитися цьому мистецтву в майбутньому, просто зверніться до мене, і я надам вам будь-які знання, якими ви ще не поділилися.", ["en"] = "Dragonscale Leatherworking" },
    [85704] = { [1] = "Шкірництво стихій", [2] = "Елементарна шкіряна справа — це те, що я знаю, і якщо ви готові відкрити свій розум для вищих сил матерії, я поділюся з вами всім, чого можна навчитися.\n\nЗнай, {клас}: обравши цей шлях, ти погоджуєшся ніколи не навчатися лусочці дракона чи племінній шкіряній справі; є місце лише для практики одного з трьох мистецтв. Крім того, мені знадобляться достатні докази того, що ти налаштований на стихії природи; для цього принеси мені найчистіші есенції вогню, води, землі та вітру.", [3] = "Принесіть 2 Серця Вогню, 2 Кулі Води, 2 Ядра Землі та 2 Подихи Вітру до Брумна Зимового Копита в горах Араті.\n\nВиконання цього завдання надасть вам доступ до мистецтва Стихійної Шкірянини.\n\nВиконання цього завдання не дозволить вам вивчити Шкірянину з Драконячої Луски та Племінну Шкірянину; переконайтеся, що це шлях, яким ви хочете піти, перш ніж робити це.", [4] = "Виготовлення такого роду шкіряних обладунків вимагає терпіння та відданості. Як тільки ви зв'яжете свою долю зі стихіями, ви вже не зможете від них відвернутися. Принесіть мені доказ вашої гідності, і ми почнемо.", [5] = "Ти обрав свій рахунок, і стихії приймають тебе. Як тільки я завершу своє навчання, ти опануєш волею створювати найтонші шкіряні шати.\n\nЩоб навчитися цьому мистецтву на майбутнє, просто звернися до мене, і я зроблю доступними всі знання, якими ти ще маєш поділитися.", ["en"] = "Elemental Leatherworking" },
    [85706] = { [1] = "Шкірництво предків", [2] = "Щоб навчитися племінній обробці шкіри, потрібно розуміти, наскільки первісною є природа насправді; я знаю, що ви вже опанували мистецтво виготовлення обладунків з дикої шкіри, і я готовий завершити ваше навчання.\n\nЗнай, {клас}: обравши цей шлях, ви погоджуєтеся ніколи не навчатися лусці дракона чи елементарній обробці шкіри; є місце лише для практики одного з трьох мистецтв. Крім того, принесіть мені найкращі зразки ваших обладунків з дикої шкіри. Звідти ми почнемо вашу майстерність.", [3] = "Принесіть Се'Джібу в Тернисту Долину Жилет з Дикої Шкіри та Шолом з Дикої Шкіри.\n\nВиконання цього завдання надасть вам доступ до племінних мистецтв шкіряної справи.\n\nВиконання цього завдання не дозволить вам вивчити Шкіряну справу з Драконячої Луски та Елементальну шкіряну справу; переконайтеся, що це саме той шлях, яким ви хочете піти, перш ніж робити це.", [4] = "Природа — це сила, яку потрібно задобрити, перш ніж ви сподіваєтеся навчитися підкоряти її волі своєму шкіряному одягу. Принесіть мені свою жертву цій силі, і я подбаю про те, щоб вас почули.", [5] = "Ти зробив свої найкращі дари, і природа скоро дозволить тобі підкорити її своїй волі. Як тільки я завершу своє навчання, твоя робота стане силою природи сама по собі.\n\nЩоб навчитися мистецтву на майбутнє, просто звернися до мене, і я зроблю доступними будь-які знання, які тобі ще належить передати.", ["en"] = "Tribal Leatherworking" },
    [85712] = { [1] = "Мистецтво виготовлення обладунків", [2] = "Задоволення. Це те, що я черпаю з молота та ковадла. Бачити гордого воїна Орди, захищеного під моєю сталлю, нагадує мені про те, що значить бути живим. Це залежність, від якої я ніколи не смію відмовитися, {ім'я}.\n\nЯ не можу дарувати тобі це задоволення, лише направити тебе на цей шлях. Як і всі життєві починання, шлях зброяра – це подорож.\n\nЯкщо ти хочеш бути одним із небагатьох обраних, тобі потрібно лише попросити, і я навчу тебе, але це завдання, яке ти спочатку повинен виконати.", [3] = "Щоб стати зброярем, ви повинні виготовити такі предмети та повернути їх Окотосу: 4 вишуканих міфрилових шолома, 2 вишуканих міфрилових чоботи, 1 вишуканий міфриловий нагрудник.", [4] = "Я буду стукати по сталі, доки в мене не перехопить подих.", [5] = "Це останній крок перед тим, як ви почнете свою нову кар'єру зброяра, {ім'я}. Якщо ви вирішите відмовитися, зараз ваш останній шанс. В іншому випадку, приготуйтеся до життя, сповненого слави.", ["en"] = "The Art of the Armorsmith" },
    [85772] = { [1] = "Стихійне лихо", [2] = "Слухай, {ім'я}. Пошкодження, про яке я говорив раніше, виходить за межі Барона Акваніса. Я вже деякий час відчуваю певний неспокій у світі стихій. Боюся, що щось серйозно не так, і пошкоджування Барона Акваніса лише посилює мої підозри.\n\nЗнайди більше цих стихій, які страждають: тут, в Ясеневому Долині, та в сусідніх Кігтеподібних Горах. Принеси мені частинки їхньої сутності. Можливо, я зможу проаналізувати їх і почати розуміти природу їхньої люті.", [3] = "Зберіть частинки стихійної люті та принесіть їх Дже'неу Санкреа на форпості Зорам'гар, Ясенеділ.", [5] = "Нещодавно я розмовляв з групою героїв, які вирушили до Чорнопровалних Глибин і боролися зі злом, що мешкало там. Вони принесли мені серце могутнього елементаля Барона Акваніса, і я ламаю голову над тим, що зіпсувало його та інших елементалів.\n\nЧи не могли б ви допомогти мені в розслідуванні?", ["en"] = "Elemental Distress" },
    [85883] = { [1] = "За Орду!", [2] = "Ренд наважується робити такі грандіозні заяви через захист, який йому надає чорна зграя.\n\nТи, {ім'я}, знайдеш спосіб пройти через Чертоги Вознесіння. Потім ти знайдеш «Вождя» Ренда Чорнорукого та знищиш його — ЗАРАДИ ОРДИ!\n\n<Тралл б'є кулаком по трону.>\n\nНаступного разу, коли ти повернешся до моїх покоїв, ти високо піднімеш його голову в тріумфі, а потім піднесеш її своєму Вождю. Зроби це і будь шанований як герой Орди.", [3] = "Вирушайте до Шпиля Чорної Скелі та вбийте Вождя Ренда Чорнорукого. Відніміть його голову та поверніться до Орґріммара.", [5] = "Ви завдали нищівного удару силам Чорної Скелі, {ім'я}. Зі вбивством їхнього вождя, легіон Чорної Скелі знову кинутий у пащу хаосу.\n\nНа честь вашого героїзму народ Калімдору буде винагороджений!", ["en"] = "For The Horde!" },
    [85965] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, які мають лише один почесний знак, я обміняю його на невелику відзнаку у вигляді Срібного Світанку.\n\nБудь ласка, пам’ятайте, що краще здати стек із десяти печаток одночасно; ваші зусилля отримають більше визнання, якщо це зробити. Ми пропонуємо обмін одного печатки як послугу для тих, кому їх недостатньо для повного стеку з десяти.\n\nЗ огляду на це, я готовий допомогти вам, якщо ви все ще бажаєте здати один печатку.", [5] = "Чудово – ваші вчинки внесено до архіву, і ваші зусилля належним чином відзначені. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще якісь підписи, я зможу вам допомогти в цьому питанні.", ["en"] = "One Commendation Signet" },
    [85966] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені передасте, я подбаю про те, щоб ви отримали значне визнання ваших вчинків від Срібного Світанку. Я також приймаю поодинокі жетони, але зі значно меншим рівнем визнання. Нас набагато більше цікавлять більші подвиги, хоча жоден подвиг не буде проігноровано.\n\nЗ огляду на це, я із задоволенням візьму ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пішли на неабияку жертву, щоб заслужити ці печатки, і ваші послуги будуть належним чином відзначені. Саме такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nПовідомте мене, якщо у вас є додаткові печатки, які потрібно здати; я з радістю допоможу вам обміняти ті, які вам потрібно.", ["en"] = "Ten Commendation Signets" },
    [85967] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен комплект із десяти, який ви мені передасте, я подбаю про те, щоб ви отримали значне визнання ваших вчинків від Кола Кенаріона. Я також приймаю окремі жетони, але зі значно меншим рівнем визнання. Нас набагато більше цікавлять більші подвиги, хоча жоден подвиг не буде проігноровано.\n\nЗ огляду на це, я із задоволенням візьму ваші печатки, якщо ви готові здати комплект.", [5] = "Чудово! Ви пішли на неабияку жертву, щоб заслужити ці печатки, і ваші послуги будуть належним чином відзначені. Саме такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nПовідомте мене, якщо у вас є додаткові печатки, які потрібно здати; я з радістю допоможу вам обміняти ті, які вам потрібно.", ["en"] = "Ten Commendation Signets" },
    [85968] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, які мають лише одну похвальну печатку, я обміняю її на невелику відзнаку від Кенарійського кола.\n\nБудь ласка, пам’ятайте, що краще здати купу з десяти печаток одночасно; ваші зусилля отримають більше визнання, якщо це зробити. Ми пропонуємо обмін однієї печатки як послугу для тих, кому не вистачає на повну купу з десяти.\n\nЗ огляду на це, я готовий допомогти вам, якщо ви все ще бажаєте здати одну печатку.", [5] = "Чудово – ваші вчинки внесено до архіву, і ваші зусилля належним чином відзначені. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще якісь підписи, я зможу вам допомогти в цьому питанні.", ["en"] = "One Commendation Signet" },
    [85972] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, які мають лише один почесний знак, я обміняю його на невелике визнання від моїх сил, Гідраксійських Водоловів.\n\nБудь ласка, пам’ятайте, що краще здати купу з десяти знаків одразу; ваші зусилля отримають більше визнання, якщо це зробити. Я пропоную обмін одного знака як послугу для тих, у кого недостатньо для повного стеку з десяти.\n\nЗ огляду на це, я прийму його, якщо ви все ще бажаєте здати один знак.", [5] = "Чудово — ваші вчинки визнано. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще якісь печатки, я їх прийму.", ["en"] = "One Commendation Signet" },
    [85974] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені передасте, ви отримаєте значне визнання від моїх сил, Гідраксійських Водоловів. Я також приймаю окремі жетони, але зі значно меншим рівнем визнання. Мене набагато більше цікавлять більші подвиги, хоча жоден подвиг не буде проігноровано.\n\nЗ огляду на це, я прийму ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пішли на неабияку жертву, щоб заслужити ці печатки, і ваші послуги будуть належним чином відзначені. Саме такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nПовідомте мене, якщо у вас є додаткові печатки, які ви хочете здати; я з радістю їх прийму.", ["en"] = "Ten Commendation Signets" },
    [85977] = { [1] = "Одна відзнака подяки", ["en"] = "One Commendation Signet" },
    [85978] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені передасте, я подбаю про те, щоб ви отримали значне визнання ваших діянь від Торієвого Братства. Я також приймаю поодинокі жетони, але зі значно меншим рівнем визнання. Нас набагато більше цікавлять більші подвиги, хоча жоден подвиг не буде проігноровано.\n\nЗ огляду на це, я із задоволенням візьму ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пішли на неабияку жертву, щоб заслужити ці печатки, і ваші послуги будуть належним чином відзначені. Саме такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nПовідомте мене, якщо у вас є додаткові печатки, які потрібно здати; я з радістю допоможу вам обміняти ті, які вам потрібно.", ["en"] = "Ten Commendation Signets" },
    [85980] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, у яких є лише один почесний знак, я обміняю його на невелике визнання від Картелю Стімвідлів.\n\nБудь ласка, пам’ятайте, що краще здати купу з десяти знаків одразу; ваші зусилля отримають більше визнання, зробивши це. Ми пропонуємо обмін одного знака як послугу для тих, у кого їх недостатньо для повного стеку з десяти.\n\nЗ огляду на це, я готовий допомогти вам, якщо ви все ще хочете здати один знак.", [5] = "Чудово — ваші документи внесено до реєстрів, і ваші зусилля належним чином відзначені. Продовжуйте гарну роботу, {клас}.\n\nЯкщо у вас є ще якісь печатки, я можу продовжити з вами торгівлю.", ["en"] = "One Commendation Signet" },
    [85981] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені вручите, я подбаю про те, щоб ви отримали значне визнання ваших вчинків від Картелю Стімвідлів. Я також приймаю поодинокі жетони, але зі значною знижкою у визнанні. Нас набагато більше цікавлять більші подвиги, хоча жоден подвиг не буде проігнорований.\n\nЗ огляду на це, я з радістю обміняю ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пішли на неабияку жертву, щоб заслужити ці печатки, і ваші заслуги будуть належним чином відзначені. Саме такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nПовідомте мене, якщо у вас є додаткові печатки, які ви хочете здати; я з радістю їх вам обміняю.", ["en"] = "Ten Commendation Signets" },
    [85984] = { [1] = "Одна відзнака подяки", [4] = "Для тих шукачів пригод, які мають лише один почесний знак, я обміняю його на невелике визнання від Племені Зандалар.\n\nМайте на увазі, що краще здати купу з десяти знаків одночасно; ваші зусилля отримають більше визнання, зробивши це. Ми також пропонуємо обмін одного знака як благодійність для тих, кому не вистачає на повний куп з десяти.\n\nТим не менш, я готовий допомогти вам, якщо ви все ще бажаєте здати один знак.", [5] = "Чудово — ваші вчинки були визнані Зандаларами. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще печатки, я допоможу вам.", ["en"] = "One Commendation Signet" },
    [85986] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від шукачів пригод, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені передасте, я подбаю про те, щоб ви отримали велике визнання від Племені Зандалар. Я також приймаю окремі жетони, але з набагато меншим благословенням. Нас набагато більше цікавлять більші подвиги службового обов'язку, хоча жоден подвиг не буде проігноровано.\n\nЗ огляду на це, я із задоволенням візьму ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пожертвували собою, щоб заробити ці печатки, і отримаєте відповідні благословення. Такі шукачі пригод, як ви, {ім'я}, справді мають значення.\n\nЗвертайтеся до мене, якщо у вас є додаткові печатки, які потрібно здати; я з радістю допоможу вам з обміном.", ["en"] = "Ten Commendation Signets" },
    [85988] = { [1] = "Одна відзнака подяки", [4] = "Для тих сторонніх, хто прийде до мене з однією похвальною печаткою, я обміняю її на невелику прихильність від Лісова Пасть.\n\nМайте на увазі, що мене більше вражає стек із десяти печаток одночасно; ваші зусилля отримають більшу прихильність від цього. Я пропоную обмін однією печаткою лише для зручності тим, у кого немає повного стеку з десяти.\n\nОднак, я готовий допомогти вам, якщо ви все ще бажаєте дати мені одну печатку.", [5] = "Чудово! Деревопузі визнає ваші зусилля. Продовжуйте в тому ж дусі, {клас}.\n\nЯкщо у вас є ще якісь печатки, я можу вам допомогти.", ["en"] = "One Commendation Signet" },
    [861] = { [1] = "Шлях мисливця", [2] = "А ти {стать:охочий:охоча} до мандрівок, я можу сказати. Я теж мав жагу до блукання, колись…\n\nБлукати та полювати, бо полювання для таурена - найбільша честь.\n\nЯкщо ти справді хочеш йти шляхами мисливця, тоді Мелор Кам'яне Копито може показати тобі путь. Він у Громовому Бескиді, на верхів'ї Мисливців.\n\nІ щоб показати йому твої вміння та рішучість, принеси йому пазурі рівнинних скрадачів Мулґору. Вони сильні та хитрі - підхожа здобич для {стать:молодого:молодої} {клас:р} на шляху мисливця.", [3] = "Принесіть 4 пазури рівнинного скрадача Мелорові Кам'яному Копиту до Громового Бескиду.", [4] = "Вітаю. Твоя присутність багато про що говорить. У нас є, про що поговорити?", [5] = "Скорн Біла Хмара - мудрий таурен. Він полював багато років, і, хоч його тіло вже старе, його дух запекло палає. Він робить нам честь, будучи серед нас.\n\nЯкщо Скорн послав тебе до мене, значить, у тебе теж є мисливський дух. А ці зібрані тобою пазурі показують твої вміння, які вже дали паростки.\n\nМожливо, ти {стать:готовий:готова} йти шляхом.", ["en"] = "The Hunter's Way", ["tasks"] = { ["Flatland Prowler Claw"] = "пазур рівнинного скрадача", ["Flatland Prowler Claw (Provided)"] = "пазур рівнинного скрадача (видано)" } },
    [86161] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю похвальні печатки від сторонніх осіб, які отримали їх під час виконання службових обов'язків. За кожен набір із десяти, який ви мені передасте, ви отримаєте значну прихильність від Лісова Пасть. Я також приймаю поодинокі жетони, але за набагато меншу прихильність. Мене набагато більше цікавлять більші подвиги служби, хоча жоден подвиг не буде проігнорований.\n\nЯ з радістю обміняю ваші печатки, якщо ви готові здати набір.", [5] = "Чудово! Ви пожертвували собою, щоб заслужити ці печатки, і цим заслужили нашу прихильність. Такі сторонні люди, як ви, {ім'я}, справді можуть змінити ситуацію.\n\nПоверніться до мене, якщо у вас є додаткові печатки, які потрібно передати; я обміняю їх на додаткову прихильність.", ["en"] = "Ten Commendation Signets" },
    [864] = { [1] = "Повернення до аптекарки Зінґе", [2] = "«Ось воно, джерело енергії безпечно видалено, а дані збережено. Ну що ж, бажаю безпечної подорожі тощо. Сподіваюся, що цей мерзенний науковий експеримент спрацював для тебе і все таке».\n\nГоблін відвертається від вас, щоб виголосити вимоги Пристробляхводоканалу. Ви запаковуєте запечатаний набір для досліджень і готуєтесь до повернення в Підмістя. Там на нього та вас очікує аптекарка Зінґе.", [3] = "Принесіть запечатаний набір для польових досліджень аптекарці Зінґе у Підмістя.", [4] = "Вітаю тебе з поверненням. Принаймні, якщо ти {стать:повернувся:повернулася} з опечатаний набором для досліджень. Інакше я зроблю вигляд, що не помітила твою цілковиту некомпетентність, і побережу тебе від свого гніву, доки ти не вчиниш так, як тобі сказали, і не виконаєш своє завдання.", [5] = "Я негайно проаналізую ці дані. Можливо, божевілля Ківера все ж стане моєю геніальністю.\n\nА щодо тебе... Ти - {стать:корисний:корисна} для мене, а я добре винагороджую тих, хто залишається корисним. Візьми цю річ, дзвінку монету та, що найважливіше, мою подяку на додачу.\n\nЧас від часу повертайся до мене — б'юся об заклад, що це ще не кінець нашої роботи над цим проєктом.", ["en"] = "Return to Apothecary Zinge", ["tasks"] = { ["Sealed Field Testing Kit"] = "запечатаний набір для польових досліджень", ["Sealed Field Testing Kit (Provided)"] = "запечатаний набір для польових досліджень (видано)" } },
    [86442] = { [1] = "Пошесть Нефарія", [2] = "Чемпіоне, це ти? Тисячу років минуло відтоді, як мені довірили цей уламок, і саме в мою найпохмурішу годину хтось має повстати, щоб позбавити мене його... Але що було б трагедією без жорстокості?\n\n<Ваеластраз слабо кашляє.>\n\nНе... Нефаріус тепер тримає уламок скіпетра.\n\nЧас має вирішальне значення. Нефаріус планує знищити уламок. Ти повинен поспішати!", [3] = "Убийте Нефаріана та знайдіть осколок Червоного Скіпетра. Поверніть осколок Червоного Скіпетра Анахроносу в Печери Часу в Танарісі. У вас є 5 годин, щоб виконати це завдання.", [4] = "Ще один наш герой загинув через породження Смертокрила. Ми будемо прокляті цими стражданнями навіки...", [5] = "Душа Ваеластраза спокійна, чемпіоне. Усі Аспекти з великим інтересом спостерігають за твоїм прогресом. Знай, що в тебе є могутні союзники.\n\nМені наказано дарувати тобі щось, що допоможе тобі в цій боротьбі. Використай це добре...", ["en"] = "Nefarius's Corruption" },
    [86445] = { [1] = "Гнів Нептулона", [2] = "Я вже згадував погану новину? Її звати Пащеки: 100 футів смерті та руйнувань. Мабуть, я забув цю дрібницю.\n\nЗгідно з моїм чудовим психо-псионічним ясновидінням, ви побачите, що найкраще місце для закидання цього буя — біля узбережжя Азшари, в Затоці Штормів.\n\nШукайте вир, що вирує, найімовірніше, захаращений уламками.\n\nДо речі, сподіваюся, у вас є друзі.\n\nА тепер, якщо вам якимось дивом вдасться, віднесіть осколок скіпетра Анахроносу.", [3] = "Використайте Арканітовий буй у Вируючому Вирі в Затоці Штормів в Азшарі.\n\nНаданий предмет:", [4] = "Час спливає, чемпіоне.", [5] = "Молодець, {ім'я}. Скоро я зможу реформувати Скіпетр Змінних Пісків.", ["en"] = "The Wrath of Neptulon" },
    [86576] = { [1] = "Брелоки Кривавої Люті", [2] = "Окрім поширення своєї гидоти по Обвугленій Долині, гарпії Кривавої Люті збирають усе блискуче, що можуть знайти. Мені казали, що вони збирають різноманітні золотисто-жовті сонячні камені для прикрас. Мені не потрібні такі дрібнички, але Мор'рогал вже згадував про їх використання раніше.\n\nПоки ти будеш битися з гарпіями Долини, слідкуй за Блискучими Сонячними Каменями. Принеси будь-які, що знайдеш, Мор'рогалу, на пагорби над нами.", [3] = "Принесіть Мор'рогалу 15 блискучих сонячних каменів.", ["en"] = "Bloodfury Trinkets", ["tasks"] = { ["Glittering Sunstone"] = "Блискучий сонячний камінь" } },
    [86670] = { [1] = "Рятівник Калімдора", [2] = "До Печер Часу йдеш, <Пане/Пані> {ім'я}. Анахронос чекає на твоє повернення. Віддай йому око К'Туна, бо він безсумнівно захоче додати його до колекції свого господаря.", [3] = "Віднесіть Око К'Туна до Анахроноса в Печерах Часу.", [4] = "Господи {ім'я}! Скінчилося...", [5] = "Майстер залишив це для тебе, чемпіоне. З позачасової схованки: Колекція артефактів, що охоплюють тисячі років — вибір за тобою.", ["en"] = "The Savior of Kalimdor", ["tasks"] = { ["Eye of C'Thun"] = "око К'Туна" } },
    [867] = { [1] = "Гарпії-напасниці", [2] = "Занадто довго прокляті гарпії розорювали наші каравани з припасами. Настав час перерізати пару горлянок, і тим самим зменшити їхню кількість.\n\nЯ понишпорив довкола їхніх гнізд і з'ясовував, хто є хто. Завдамо нищівного удару по нижніх ланках командування, і поступово дістанемося до ватажків.\n\nНа все свій час, спершу покінчи з гарпіями та опереними пройдисвітками зграї Чарокрилих на північному заході, та принеси мені 8 їхніх кігтів. Це для початку...", [3] = "Зберіть 8 кігтів зграї Чарокрилих.\n\nПринесіть їх Дарсоку Хуткоклину на Перехрестя.", [4] = "Багатьох {стать:відправив:відправила} на той світ? Продовжуй сікти та збирати трофеї. Мені потрібні 8 кігтів Чарокрилих.", [5] = "О, а ці нічогенькі такі. Справді добротні... Гарно {стать:попрацював:попрацювала}, {ім'я}. З нетерпінням чекаю, коли знову зможу помилуватися на твою роботу.", ["en"] = "Harpy Raiders", ["tasks"] = { ["Witchwing Talon"] = "кіготь чарокрилої", ["Witchwing Talon (Provided)"] = "кіготь чарокрилої (видано)" } },
    [86724] = { [1] = "Прах до праху", [2] = "{ім'я}, вислухай мене. Рани Капітана стають дедалі важчими. Табір святкує кожну перемогу зі своєю звичною радістю, але я не можу приєднатися до їхніх оплесків. Не тоді, коли я бачив рани, які він приховує під бронею.\n\nІнфекція? Ні, ні, я б сказав, що це набагато ближче до... зараження. Я готую суміш, але мені все ще потрібен один ключовий інгредієнт — Силітист.\n\nМені він потрібен, і швидко. Виходячи з мого огляду стану Капітана, боюся, що він недовго протримається без нього.", [3] = "Знайдіть і доставте 5 силітистів видобувачу силітистів, а потім поговоріть з аптекарем Квінардом у таборі Орди поблизу Вулика'Регал.", [4] = "Обережно {ім'я}. З того, що я зібрав з наших розвідувальних звітів, Альянс починає розуміти цінність піску.\n\nЗ огляду на це, я раджу вам взятися загартованим. Зараз пустелею бродить два типи черв'яків.", [5] = "Чудово. Ви все зібрали, і ані на мить раніше. Я негайно приготую цю суміш для капітана Круга.\n\nЯ не можу винагородити вашу хоробрість грошима, але можу обдарувати вас деякими своїми знаннями. Я б розлучився з банкнотами, якими частував солдатів і наповнював їхні шлунки, звичайно, за певну плату.", ["en"] = "Dust to Dust" },
    [86784] = { [1] = "Палиці та кістки", [2] = "Моя колега Елеонор Шеклтон пишається тим, що подорожує дикою природою, виживає, незважаючи на негоду та монстрів. Зараз вона таборує неподалік звідси, на пагорбах на заході, і я пам'ятаю пораду, яку вона мені колись дала: «Коли думаєш, що в тебе достатньо дров, збери вп'ятеро більше».\n\nЯкщо у тебе є вільний час, ти можеш зібрати трохи дров у цей кошик і віднести їх до її табору. Я впевнений, що вона могла б дати тобі кілька порад про існування мандрівного шукача пригод.", [3] = "Зберіть 6 сухих гілок та принесіть їх Елеонор Шеклтон.\n\nНаданий предмет:", ["en"] = "Sticks and Bones", ["tasks"] = { ["Dry Branch"] = "Суха гілка" } },
    [868] = { [1] = "Полювання на яйця", [2] = "Агов, {ім'я}. Мене відправили на Перехрестя доглядати за землею, та повідомляти начальству в Орґріммар про все, що тут відбувається.\n\nОдним з об'єктів моїх досліджень являються комахоподібні істоти на південь звідси, на полі Велетнів. Нам мало що відомо про цих істот, тож моя мета - дізнатися більше. Здається, їхній інтелект більш розвинений, ніж у звичайних тварин.\n\nВізьми цей рийний кіготь і збери яйця істот із курганів, але будь {стать:обережним:обережною}: якщо вони тебе помітять - відразу нападуть.", [3] = "Принесіть 12 яєць силітидів та рийний кіготь Коррану на Перехрестя.", [4] = "Будь {стать:обережним:обережною} з яйцями, що знайдеш, {ім'я}. Биті яйця мені ні до чого.", [5] = "Ну, ти мене тішиш, {ім'я}. І яйця, і інструмент. Чудова робота.\n\nЩодо твоєї винагороди...", ["en"] = "Egg Hunt", ["tasks"] = { ["Digging Claw"] = "рийний кіготь", ["Digging Claw (Provided)"] = "рийний кіготь (видано)", ["Silithid Egg"] = "яйце силітида", ["Silithid Egg (Provided)"] = "яйце силітида (видано)" } },
    [869] = { [1] = "Раптори-злодії", [2] = "Нещодавно з нашої сторожової вежі вкрали партію срібла. Срібло призначалося на зарплату вартових Перехрестя, і ми маємо його повернути.\n\nДивна річ... ми спіймали одного зі злодіїв у ніч крадіжки. І... це виявився раптор! Неймовірно!\n\nНе знаю, навіщо рапторам срібло. Але мені байдуже: коли вони будуть мертві — крадіжки припиняться!\n\nПовбивай рапторів у Степах і принеси мені їхні голови!", [3] = "Принесіть 12 голів рапторів Ґазроґу на Перехрестя.", [4] = "Ти {стать:приніс:принесла} їхні голови, {ім'я}?", [5] = "Тобі вдалося позбавитись від рапторів!\n\nДякую тобі, {ім'я}. Ти — {стать:гідний:гідна} {клас}.", ["en"] = "Raptor Thieves", ["tasks"] = { ["Raptor Head"] = "голова раптора", ["Raptor Head (Provided)"] = "голова раптора (видано)" } },
    [870] = { [1] = "Забуті стави", [2] = "Давним-давно Степи були родючою місцевістю, де вирувало життя. Але війна та катаклізм понівечили землю, випалюючи її та лишаючи тільки сухе лушпиння. Так у житті буває, і від того моє серце журиться.\n\nАле за останні кілька років у Степах утворилися нові оазиси, і життя пожвавлюється. А ми, друїди, відчуваємо, що на поверхню просочується якась сила.\n\nТреба знайти її джерело. Прямуй до Забутих ставів, на північний захід від Перехрестя. Пошукай у водоймах джерело сили та потому повертайся назад.", [3] = "Відзвітуйте Тонзі Рунному Тотемові про свої знахідки.", [4] = "Ти вже {стать:був:була} на Забутих ставах, {Ім'я}? Щось {стать:знайшов:знайшла}?", [5] = "Що? Розколина в землі, з якої просочується газ? Дивно. Можливо, це і є відповідь на наші запитання, але поки що ми не можемо бути певними.\n\nОднак, це вже щось. І я вдячний, що ти це {стать:знайшов:знайшла}.", ["en"] = "The Forgotten Pools", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Explore the waters of the Forgotten Pools"] = "Дослідіть води Забутих Пул" } },
    [871] = { [1] = "Саботаж атак", [2] = "Всі, без винятку, свинобрази наші вороги, {ім'я}. Просто з деякими більше мороки ніж з іншими.\n\nПлем'я Бритвогривих неспинно нападає на наші лінії постачання з Дуротара, нескінченно надокучаючи нам. Мої розвідники вишукують лідера цих набігів, а тим часом будь-які втрати, які ти зможеш завдати тим брудним свиноподібним потворам, допоможуть нам.\n\nПочинай з північного сходу в бік Дуротара. Як побачиш чагарники з величезної тернистої лози, що повилазила з-під землі — знай, там їхній барліг. Вистежуй їх і вбивай.", [3] = "Вбийте 8 водошукачів, 8 терноткачів та 3 мисливців племені Бритвогривих і поверніться до Торка в Перехрестя.", [4] = "Чим довше потрібно часу для припинення цих атак, тим важче буде забезпечити припасами мешканців Перехрестя.", [5] = "Блискуча робота, {ім'я}. Ці нахабні свинобрази нарешті зарубають собі на носі, що міць Орди не слід ігнорувати.", ["en"] = "Disrupt the Attacks", ["tasks"] = { ["Razormane Hunter"] = "бритвогривий мисливець", ["Razormane Hunter slain"] = "бритвогривий мисливець: убито", ["Razormane Thornweaver"] = "бритвогривий терноткач", ["Razormane Thornweaver slain"] = "бритвогривий терноткач: убито", ["Razormane Water Seeker"] = "бритвогривий водошукач", ["Razormane Water Seeker slain"] = "бритвогривий водошукач: убито" } },
    [872] = { [1] = "Кінець свавіллю", [2] = "Один з моїх розвідників став свідком нападу на караван з Дуротару, {ім'я}. Винуватцями й справді є плем'я Бритвогривих. Один зі свинобразів на ім'я Крініг Рилоскал - їхній ватажок. Його бачили на північний схід звідси, на південь від дороги до Дуротару. Допоки Крініг живий - набігам не буде кінця-краю.\n\nА щоб остаточно відбити в них бажання нападати в майбутньому - давай-но додамо дрібку приниження до їхньої поразки. Прикінчи Крініга і якомога більше його прибічників та повертайся до мене з його іклом.", [3] = "Вбийте 8 геомантів та 8 захисників племені Бритвогривих, а також Крініга Рилоскала.\n\nПринесіть ікло Крініга Рилоскала Торку на Перехрестя.", [4] = "Відріж голову ватажку і їх охопить хаос, {ім'я}. Зарубай собі це на носі. Стане в пригоді тобі у майбутньому.\n\nКнурі почнуть безцільно метушитися, а ми ж відвоюємо Степи.", [5] = "Чудова робота, {ім'я}. Завдяки смерті Крініга число набігів на наші каравани значно зменшиться.\n\nТвій народ повинен пишатися тим, що ти {стать:один:одна} із них.", ["en"] = "The Disruption Ends", ["tasks"] = { ["Kreenig Snarlsnout's Tusk"] = "ікло Крініга Рилоскала", ["Kreenig Snarlsnout's Tusk (Provided)"] = "ікло Крініга Рилоскала (видано)", ["Razormane Defender"] = "бритвогривий захисник", ["Razormane Defender slain"] = "бритвогривий захисник: убито", ["Razormane Geomancer"] = "бритвогривий геомант", ["Razormane Geomancer slain"] = "бритвогривий геомант: убито" } },
    [873] = { [1] = "Іша Авак", [2] = "Величний Іша Авак - володар цих вод. Величний у своїй силі, та непохитний у своїй пихатості. Люди узбережжя страшаться його, бо багатьох він поглинув.\n\nАле я його не боюся. Я вдячна, що він тут. Він гідний суперник і почесна здобич.\n\nЯкщо ти {стать:готовий:готова}, тоді відпливай якомога далі та шукай Ішу Авака, Погибель глибин.\n\nЙого дух живе в серці, і прислухавшись до його биття ти дізнаєшся свою долю.", [3] = "Принесіть серце Іши Авака до Марен Небесної Провидиці.", [4] = "Не бійся вод, {раса:к}.", [5] = "Тепер ти одне ціле з Ішею Аваком, {ім'я}. Його дух з тобою. Він зачаївся у твоїх очах...\n\nОчах, які одного дня навчаться бачити.", ["en"] = "Isha Awak", ["tasks"] = { ["Heart of Isha Awak"] = "серце Іши Авака", ["Heart of Isha Awak (Provided)"] = "серце Іши Авака (видано)" } },
    [8731] = { [1] = "Польова служба", [2] = "Вітаю, {ім'я}. Перш ніж ти отримаєш більш відповідальні завдання на війні, тобі потрібно виконати свою частину польової служби.\n\nТи знайдеш капітана Череполама з Орґріммарського легіону поруч з Вул'Регалем.\n\nПоговори з ним і повертайтеся до мене з доказами виконання польової служби. Я підготую для тебе складніше завдання.\n\nІ, будь ласка, зроби послугу, тримайся якомога далі від бригади Залізогарта. Між добровольцями Альянсу та Орди постійно виникають суперечки.", [3] = "Вступіть на службу до Краґа Череполама на пост Орґріммарського легіону, що навпроти Вул'Регаля. Підготуйте свої непідписані документи про польову службу, отримайте підписані документи про польову службу та віднесіть їх вітрозову Калдону в Кенарійську цитадель.\n\nПримітка: Якщо ви зцілите або накладете корисні заклинання на члена Орґріммарського легіону, вас будуть вважати {стать:учасником:учасницею} PvP.", [4] = "Ти {стать:виконав:виконала} своє польове завдання, {ім'я}? Капітана Череполама можна знайти поруч з Вул'Регалем.", [5] = "Можу сказати, що Краґ не любить тяганину з документами. Він підписав це кров'ю силітида!\n\nЧудово, {ім'я}. Я підготував перелік завдань, які повною мірою використають твої навички {клас:р}.\n\nЗавдяки старанній роботі таких, як ти, наші вороги незабаром будуть знищені!", ["en"] = "Field Duty", ["tasks"] = { ["Signed Field Duty Papers"] = "підписані документи про польову службу", ["Signed Field Duty Papers (Provided)"] = "підписані документи про польову службу (видано)" } },
    [8732] = { [1] = "Документи про польову службу", [4] = "Документи про польову службу? Що це за нісенітниці, {ім'я}?", [5] = "В старі добрі часи я б помітив твоє чоло кров'ю, щоб відзначити виконання обов'язку. Але Тралл наполягає, щоб ми виконували прохання друїдів.\n\nВізьми ці документи й повертайся в Кенарійську цитадель. Я впевнений, вони знайдуть для тебе відповідну роботу.", ["en"] = "Field Duty Papers", ["tasks"] = { ["Prepared Field Duty Papers"] = "підготовлені документи про польову службу", ["Prepared Field Duty Papers (Provided)"] = "підготовлені документи про польову службу (видано)" } },
    [874] = { [1] = "Марен Небесна Провидиця", [2] = "Ти {стать:вполював:вполювала} багатьох звірів Степів. Дух твій сильний. Але мисливець повинен бути завжди напоготові. Справжній мисливець може переслідувати здобич в будь-яких умовах. Чи то гори, чи болота, ніщо не зіб'є ловця з пантелику.\n\nНавіть море.\n\nЗнайди мою сестру, Марен. Вона полює на великих морських звірів вздовж узбережжя. Вона й буде вчити тебе.\n\nАле будь насторожі, бо узбережжя Степів захопили люди.", [3] = "Поговоріть з Марен Небесною Провидицею.", [5] = "Мій брат прислав тебе, чи не так? Отже, ти справді себе гарно перед ним {стать:зарекомендував:зарекомендувала}. Якщо Джорн тебе шанує, то поважатиму і я.\n\n{стать:Готовий:Готова} йти далі мисливським шляхом?", ["en"] = "Mahren Skyseer" },
    [87433] = { [1] = "Латні рукавички Сріблястого Світанку", [4] = "Якщо ти принесеш мені тридцять некротичних рун, я натомість дам тобі захист для рук на твій вибір. Вони мають стати в нагоді в нашій боротьбі з нежитью-Бачею.", [5] = "Ви добре попрацювали, {ім'я}. Оберіть захист для рук на знак подяки за ваші зусилля.", ["en"] = "Argent Dawn Plate Gloves" },
    [87435] = { [1] = "Кольчужні рукавички Сріблястого Світанку", [4] = "Якщо ти принесеш мені тридцять некротичних рун, я натомість дам тобі захист для рук на твій вибір. Вони мають стати в нагоді в нашій боротьбі з нежитью-Бачею.", [5] = "Ви добре попрацювали, {ім'я}. Оберіть захист для рук на знак подяки за ваші зусилля.", ["en"] = "Argent Dawn Mail Gloves" },
    [87437] = { [1] = "Шкіряні рукавички Сріблястого Світанку", [4] = "Якщо ти принесеш мені тридцять некротичних рун, я натомість дам тобі захист для рук на твій вибір. Вони мають стати в нагоді в нашій боротьбі з нежитью-Бачею.", [5] = "Ви добре попрацювали, {ім'я}. Оберіть захист для рук на знак подяки за ваші зусилля.", ["en"] = "Argent Dawn Leather Gloves" },
    [87439] = { [1] = "Тканинні рукавички Сріблястого Світанку", [4] = "Якщо ти принесеш мені тридцять некротичних рун, я натомість дам тобі на вибір захист для рук. Вони мають стати в нагоді в нашій боротьбі проти {раса} Бичі.", [5] = "Ви добре попрацювали, {ім'я}. Оберіть захист для рук на знак подяки за ваші зусилля.", ["en"] = "Argent Dawn Cloth Gloves" },
    [87442] = { [1] = "Атієш, великий посох Вартівника", [2] = "Це останнє завдання буде найскладнішим з усіх, {ім'я}. Ти зустрівся та переміг як Старого Бога, так і Генерала Короля-Ліча, але тепер тобі доведеться зіткнутися з рукою Саргераса.\n\nВіднеси посох до Стратхольма. Саме там ти знайдеш шматок освяченої землі: землю, де були вбиті найвидатніші лицарі Лордерона. Поклади осквернений посох на святу землю та приготуйся до того, що сутність величезної сили вирветься зсередини... Переможи демонічну істоту, яка контролює посох, і повернися до мене.", [3] = "Анахронос з Печер Часу в Танарісі хоче, щоб ви віднесли Атієша, Великий посох Хранителя, до Стратхольма та використали його на Освяченій Землі. Переможіть сутність, яку вигнано з посоха, та поверніться до нього.", [4] = "Я не повинен втручатися, {раса}.", [5] = "Не можна недооцінювати масштаб цього досягнення, {ім'я}. Ви зробили те, що більшість вважала б неможливим. На жаль, це було призначено долею. Персонал зробив свій вибір...", ["en"] = "Atiesh, Greatstaff of the Guardian" },
    [87443] = { [1] = "Атієш, великий посох Вартівника", [2] = "Це останнє завдання буде найскладнішим з усіх, {ім'я}. Ти зустрівся та переміг як Старого Бога, так і Генерала Короля-Ліча, але тепер тобі доведеться зіткнутися з рукою Саргераса.\n\nВіднеси посох до Стратхольма. Саме там ти знайдеш шматок освяченої землі: землю, де були вбиті найвидатніші лицарі Лордерона. Поклади осквернений посох на святу землю та приготуйся до того, що сутність величезної сили вирветься зсередини... Переможи демонічну істоту, яка контролює посох, і повернися до мене.", [3] = "Анахронос з Печер Часу в Танарісі хоче, щоб ви віднесли Атієша, Великий посох Хранителя, до Стратхольма та використали його на Освяченій Землі. Переможіть сутність, яку вигнано з посоха, та поверніться до нього.", [4] = "Я не повинен втручатися, {раса}.", [5] = "Не можна недооцінювати масштаб цього досягнення, {ім'я}. Ви зробили те, що більшість вважала б неможливим. На жаль, це було призначено долею. Персонал зробив свій вибір...", ["en"] = "Atiesh, Greatstaff of the Guardian", ["tasks"] = { ["Atiesh, Greatstaff of the Guardian"] = "Атієш, великий посох Вартівника" } },
    [87444] = { [1] = "Атієш, великий посох Вартівника", [2] = "Це останнє завдання буде найскладнішим з усіх, {ім'я}. Ти зустрівся та переміг як Старого Бога, так і Генерала Короля-Ліча, але тепер тобі доведеться зіткнутися з рукою Саргераса.\n\nВіднеси посох до Стратхольма. Саме там ти знайдеш шматок освяченої землі: землю, де були вбиті найвидатніші лицарі Лордерона. Поклади осквернений посох на святу землю та приготуйся до того, що сутність величезної сили вирветься зсередини... Переможи демонічну істоту, яка контролює посох, і повернися до мене.", [3] = "Анахронос з Печер Часу в Танарісі хоче, щоб ви віднесли Атієша, Великий посох Хранителя, до Стратхольма та використали його на Освяченій Землі. Переможіть сутність, яку вигнано з посоха, та поверніться до нього.", [4] = "Я не повинен втручатися, {раса}.", [5] = "Не можна недооцінювати масштаб цього досягнення, {ім'я}. Ви зробили те, що більшість вважала б неможливим. На жаль, це було призначено долею. Персонал зробив свій вибір...", ["en"] = "Atiesh, Greatstaff of the Guardian", ["tasks"] = { ["Atiesh, Greatstaff of the Guardian"] = "Атієш, великий посох Вартівника" } },
    [8746] = { [1] = "Метцен-північний олень", [2] = "КАТАСТРОФА! Метцена-північного оленя викрали!\n\nМетцен — один з восьми північних оленів Дідуся Зими та власність Пасовищ Димного Лісу. Ми отримали не одну, а ДВІ записки з вимогою викупу від злодіїв, які стверджують, що Метцен у них. З розпалом святкового сезону у нас немає грошей! Будь ласка, знайди Метцена та поверни його нам!\n\nПеревір листи з вимогами викупу, щоб знайти підказки, та посип його цим оленячим пилом — він звільнить його від будь-яких пут!\n\nБудь ласка, поквапся!", [3] = "Знайдіть Метцена-північного оленя. Використовуйте надані вам записки, щоб дізнатися, де його утримують.\n\nКоли ви знайдете Метцена, візьміть з собою мішечок з оленячим пилом, щоб посипати його пилом. Це має звільнити Метцена від пут неволі.\n\nПоверніть мішечок з оленячим пилом Якобу Хапмідяку в Орґріммар, щойно Метцен буде звільнений.", [4] = "{ім'я}! Ти {стать:знайшов:знайшла} його? Записки в сумці, яку я дав тобі, дали достатньо інформації, щоб знайти Метцена? Мені страшно думати про те, що ці безсердечні бандити можуть зробити з ним... але ми не можемо дозволити собі заплатити такий непомірний викуп!", [5] = "Ти це {стать:зробив:зробила}! Ура!\n\nМетцен прилетів у стайні Дідуся Зими — так, Метцен справді може літати — всього лише кілька хвилин тому! Пил працює бездоганно, як я й казав. Ти {стать:врятував:врятувала} свято Зимової Покрови та Пасовища Димного Лісу від катастрофи. Дякую, {ім'я}.\n\nПослухай... За свої труди ти заслуговуєш на нагороду. Ось, тримай. Це дещо ДУЖЕ особливе. Думаю, якщо ти {стать:вершник:вершниця}, ти будеш в захваті. З прийдешнім святом Зимової Покрови!", ["en"] = "Metzen the Reindeer", ["tasks"] = { ["Find Metzen the Reindeer and rescue him"] = "Знайдіть оленя Метцена та врятуйте його", ["Pouch of Reindeer Dust"] = "мішечок з оленячим пилом", ["Pouch of Reindeer Dust (Provided)"] = "мішечок з оленячим пилом (видано)" } },
    [875] = { [1] = "Лейтенанти гарпій", [2] = "Ха-ха-ха, {ім'я}. Хочеш ще? Добре, радий це чути.\n\nЦього разу я хочу, щоб ти {стать:позбувся:позбулася} деяких лейтенантів гарпій на Сухих пагорбах. З усієї зграї Чарокрилих, лише душогубки можуть бути лейтенантами, а ти зможеш їх вирізнити завдяки персням, які вони носять. Паскудні створіння, але вони ведуть частину підлеглих за собою. Ліквідація хоча б шести з них стане неабияким ударом по їхньому матріархату.\n\nПостарайся, щоб вони помирали в муках, {ім'я}. Нехай ті гарпії-нетіпахи зарубають собі на пір'ях, яка то дурість задиратися з Ордою.", [3] = "Зберіть 6 лейтенантських перснів гарпій з вбивць зграї Чарокрилих, і поверніться до Дарсока Хуткоклина на Перехрестя.", [4] = "{стать:Дістав:Дістала} 6 лейтенантських перснів гарпій? Нехай отримають справедливу кару за свої варварські нападки на Орду.", [5] = "Відмінна робота, друже. Я думаю, ти багато чого досягнеш в Орді.", ["en"] = "Harpy Lieutenants", ["tasks"] = { ["Harpy Lieutenant Ring"] = "лейтенантський перстень гарпії", ["Harpy Lieutenant Ring (Provided)"] = "лейтенантський перстень гарпії (видано)" } },
    [876] = { [1] = "Серена Кривавопера", [2] = "Ти так добре {стать:справився:справилася} з лейтенантами та поплічниками, що я хотів аби ти {стать:зробив:зробила} ще одну, останню річ для мене.\n\nСерена Кривавопера - сестра гарпії, на ім'я Кривавопера, яку Рексар вбив досить давно. Можливо, ці нападки на ординські каравани - це її помста за смерть сестри.\n\nПотрібно, щоб ти {стать:відтяв:відтяла} і {стать:приніс:принесла} мені її голову. Я хочу розмістити її на наступному каравані, що ми відправимо... Щоб всі гарпії задумались.", [3] = "Убийте Серену Кривавоперу і принесіть її голову Дарсоку Хуткоклину на Перехрестя.", [4] = "Ти нічого не отримаєш, допоки я не побачу голови Серени.", [5] = "ХА! Блискуче, {ім'я}! Чудова робота... Я не був упевнений, що ти впораєшся із завданням, але виявляється, ти ще {стать:той відчайдух:та відчайдуха}. Спасибі тобі, що {стать:допоміг:допомогла} нам придушити це нашестя гарпій. Ось твоя винагорода, користуйся з розумом.", ["en"] = "Serena Bloodfeather", ["tasks"] = { ["Serena's Head"] = "голова Серени", ["Serena's Head (Provided)"] = "голова Серени (видано)" } },
    [877] = { [1] = "Застійний оазис", [2] = "Можливо, й інші оазиси Степу мають тріщини на кшталт тієї, що ти {стать:знайшов:знайшла} у Забутих ставах. Якщо так, то, напевно, розколини і є джерелом життя оазисів.\n\nПотрібно це перевірити.\n\nОсь, візьми це насіння. Воно мертве та безплідне, проте все ж віднеси його до Застійного оазису на південний схід. Якщо там є розколина - помісти в неї насіння... та уважно спостерігай.", [3] = "Обстежте Застійний оазис та поверніться до Тонґи на Перехрестя.", [4] = "Ти вже {стать:побував:побувала} в Застійному оазисі? Чи є там щілина під його водами?", [5] = "Твоя знахідка дивовижна! Насіння, яке я тобі дав, було висохле та мертве. Що б не було під цими оазисами, воно може створити життя з нічого!\n\nМи повинні добряче це дослідити...", ["en"] = "The Stagnant Oasis", ["tasks"] = { ["Test the Dried Seeds"] = "Перевірте сушене насіння", ["Test the Dried Seeds (Provided)"] = "Перевірте сушене насіння (видано)", ["Test the Dried Seeds slain"] = "Перевірте сушене насіння: убито" } },
    [878] = { [1] = "Війна племен", [2] = "Ти {стать:повинен:повинна} помститися моїм ворогам. <фиркає> Ти мусиш допомогти Кривозубові та Бритвогривим, послабивши Щетиношкурих. Обидва племені дуже духовні - прив'язані до землі та її могутності. <фиркає> Це надає нам силу у всьому... особливо на війні.\n\nЯкщо кортить дізнатися, хто насправді спричиняє Торкові <фиркає> та Орді такий клопіт, то допоможи Кривозубові! Напади на духовних лідерів Щетиношкурих на півночі; ослаб їх, щоб Бритвогриві змогли перемогти та запанували на теренах Степів.", [3] = "Убийте 6 щетиношкурих водошукачів, 12 щетиношкурих терноткачів і 12 щетиношкурих геомантів та поверніться до Кривозуба у табір Таурахо, що в Степах.", [4] = "Більше інформації <фиркає> для Орди отримаєш тільки після того, як уб'єш мудреців Щетиногривих, {раса:к}. <фиркає> Ні на мить раніше! Кривозуб - не дурень.", [5] = "Так-так... я мав би бути сповненим щастя, що, нарешті, <фиркає> Щетиношкурі відчувають біль мого племені, {раса:к}. Але ні, щось мені не радісно.\n\nОсь ти допомагаєш своїм - і вони тебе шанують. Кривозуб допомагав своїм, і що ж? Вони відвернулися від нього. Його забули, залишили гнити у клітці!\n\nЯ допомагав їм навіть з-поза ґрат, але ні… ніхто не прийшов мені на допомогу!", ["en"] = "Tribes at War", ["tasks"] = { ["Bristleback Geomancer"] = "щетиношкурий геомант", ["Bristleback Geomancer slain"] = "щетиношкурий геомант: убито", ["Bristleback Thornweaver"] = "щетиношкурий терноткач", ["Bristleback Thornweaver slain"] = "щетиношкурий терноткач: убито", ["Bristleback Water Seeker"] = "щетиношкурий водошукач", ["Bristleback Water Seeker slain"] = "щетиношкурий водошукач: убито" } },
    [8785] = { [1] = "Орґріммарському легіону потрібне моджо!", [2] = "Орґріммарський легіон подав запит на кілька незвичайних інгредієнтів. Враховуючи їхні успіхи в Силітусі, ми б хотіли виконати їхнє прохання якнайшвидше. Збери матеріали й принеси їх трольці, на ім'я Шаї.", [3] = "Принесіть 6 потужних моджо, 6 фляг великого моджо та 8 пляшок олії жертвоприношення жриці тіні Шаї до Вул'Регалю у Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання IV.", [4] = "Ти {стать:приніс:принесла} мої матеріали, {ім'я}?", [5] = "О, так. Саме те, що мені потрібно! Я зроблю з цього особливу суміш. Силітидам це не сподобається!", ["en"] = "The Orgrimmar Legion Needs Mojo!", ["tasks"] = { ["Flask of Big Mojo"] = "фляга великого моджо", ["Flask of Big Mojo (Provided)"] = "фляга великого моджо (видано)", ["Logistics Task Briefing IV"] = "план логістичного завдання IV", ["Logistics Task Briefing IV (Provided)"] = "план логістичного завдання IV (видано)", ["Oil of Immolation"] = "олія жертвоприношення", ["Oil of Immolation (Provided)"] = "олія жертвоприношення (видано)", ["Powerful Mojo"] = "потужне моджо", ["Powerful Mojo (Provided)"] = "потужне моджо (видано)" } },
    [879] = { [1] = "Зрада зсередини", [2] = "З Крааля вийшло троє моїх одноплемінників, щоб керувати набігами на Орду. <фиркає> Вони безжальні та хитрі, але як тільки ти їх позбудешся, то ваше Перехрестя і навіть більшість Степів відчують полегшення... <фиркає> принаймні, від племені Бритвогривих. <фиркає>\n\nНак, Каз і Лок Орковбивця — саме ті, хто тобі треба. Вони перебувають далеко на півдні Степів. Один — заклинатель, інший — мисливець, а їхній лідер — той, що зветься Орковбивцею — <фиркає> воїн. Убий їх, {раса:к}, як вони вбили мене.", [3] = "Вбийте Нака, Каза та Лока Орковбивцю та принесіть їхні черепи Кривозубу в табір Таурахо, що в Степах.", [4] = "Ну як там твоє полювання, {раса:к}?\n\nТорк думає, що знає, хто очолює набіги на його народ, але він скоро збагне, наскільки був неправий. Якщо ти впораєшся.\n\nМоя смерть неминуча, але ти {стать:завдав:завдала} великого болю моїм ворогам, тому Кривозуб ні про що не шкодує.", [5] = "Нарешті! Краще такий кінець, вважає Кривозуб. <фиркає> Вони повинні були <фиркає> впевнитися, що я мертвий, перш ніж лишати <фиркає> мене тут, у цій покинутій клітці.\n\nТобі залишилося виконати лише одне завдання, {раса:к}.", ["en"] = "Betrayal from Within", ["tasks"] = { ["Kuz's Skull"] = "череп Каза", ["Kuz's Skull (Provided)"] = "череп Каза (видано)", ["Lok's Skull"] = "череп Лока", ["Lok's Skull (Provided)"] = "череп Лока (видано)", ["Nak's Skull"] = "череп Нака", ["Nak's Skull (Provided)"] = "череп Нака (видано)" } },
    [8792] = { [1] = "Орді потрібна твоя допомога!", [2] = "Привіт, я рада, що ти {стать:вирішив:вирішила} мене вислухати. Орді потрібна допомога, щоб підготуватися до війни в Ан'Кіражі, і це означає, що нам {стать:потрібен:потрібна} ти! Навіть зараз, поки ми з тобою базікаємо, наші інтенданти збирають всі ресурси, які знадобляться для майбутньої війни. Але ми не зможемо досягти мети без твоєї допомоги, {ім'я}!\n\nТи маєш піти поговорити з нашим керівником — воєводою Ґорчуком. Що скажеш, {клас:к}? Допоможеш нам з підготовкою?", [3] = "Поговоріть з воєводою Ґорчуком в долині Духів в Орґріммарі.", [5] = "Тром'ка, {клас:к}! Радий бачити, що стільки членів Орди, як ти, {ім'я}, приходять сюди, щоб допомогти у підготовці до війни в Ан'Кіражі. Докладені зусилля гарантуватимуть нашу перемогу у війні проти силітидів та їхніх злих господарів, що сховалися в глибинах Ан'Кіража.\n\nОскільки ти вже тут, то обов'язково поговори з різними збирачами ресурсів та запропонуй їм допомогу.", ["en"] = "The Horde Needs Your Help!" },
    [8793] = { [1] = "Орді потрібна твоя допомога!", [2] = "Привіт, я радий, що ти {стать:вирішив:вирішила} мене вислухати. Орді потрібна допомога, щоб підготуватися до війни в Ан'Кіражі, і це означає, що нам {стать:потрібен:потрібна} ти! Навіть зараз, поки ми з тобою базікаємо, наші інтенданти збирають всі ресурси, які знадобляться для майбутньої війни. Але ми не зможемо досягти мети без твоєї допомоги, {ім'я}!\n\nТи маєш піти поговорити з нашим керівником — воєводою Ґорчуком. Що скажеш, {клас:к}? Допоможеш нам з підготовкою?", [3] = "Поговоріть з воєводою Ґорчуком в долині Духів в Орґріммарі.", [5] = "Тром'ка, {клас:к}! Радий бачити, що стільки членів Орди, як ти, {ім'я}, приходять сюди, щоб допомогти у підготовці до війни в Ан'Кіражі. Докладені зусилля гарантуватимуть нашу перемогу у війні проти силітидів та їхніх злих господарів, що сховалися в глибинах Ан'Кіража.\n\nОскільки ти вже тут, то обов'язково поговори з різними збирачами ресурсів та запропонуй їм допомогу.", ["en"] = "The Horde Needs Your Help!" },
    [8794] = { [1] = "Орді потрібна твоя допомога!", [2] = "Привіт, я рада, що ти {стать:вирішив:вирішила} мене вислухати. Орді потрібна допомога, щоб підготуватися до війни в Ан'Кіражі, і це означає, що нам {стать:потрібен:потрібна} ти! Навіть зараз, поки ми з тобою базікаємо, наші інтенданти збирають всі ресурси, які знадобляться для майбутньої війни. Але ми не зможемо досягти мети без твоєї допомоги, {ім'я}!\n\nТи маєш піти поговорити з нашим керівником — воєводою Ґорчуком. Що скажеш, {клас:к}? Допоможеш нам з підготовкою?", [3] = "Поговоріть з воєводою Ґорчуком в долині Духів в Орґріммарі.", [5] = "Тром'ка, {клас:к}! Радий бачити, що стільки членів Орди, як ти, {ім'я}, приходять сюди, щоб допомогти у підготовці до війни в Ан'Кіражі. Докладені зусилля гарантуватимуть нашу перемогу у війні проти силітидів та їхніх злих господарів, що сховалися в глибинах Ан'Кіража.\n\nОскільки ти вже тут, то обов'язково поговори з різними збирачами ресурсів та запропонуй їм допомогу.", ["en"] = "The Horde Needs Your Help!" },
    [8799] = { [1] = "Герой дня", [2] = "Послухай... мені насправді не слід розповідати це тобі, але ти {стать:став:стала} героєм дня і все таке...\n\nСвіжий падуб росте скрізь в цю пору року, але він швидко в'яне. У нас є машина, що зберігає його — і він ніколи не псується! Ми використовуємо його, як прикрасу для свята... і як джерело прибутку влітку!\n\nЯ дозволю тобі використовувати цю сушарку, але тільки якщо ти {стать:майстер-кухар:майстрия-кухарка}. Тобі знадобиться глибокоскельна сіль і, скажімо, п'ять золотих. Ти отримаєш чудову партію сушеного падуба.", [3] = "Принесіть глибокоскельну сіль та 5 золотих монет до апарату для сушіння падуба, щоб отримати 5 сушених падубів.", [4] = "Сушарка для падуба, на перший погляд, є звичайним перегонним кубом, але, оглянувши її детальніше, ви помічаєте певні гоблінські модифікації. Втім, ваші кулінарні навички дозволяють зрозуміти, як працює ця машина.\n\nВсередині вже лежить свіжий падуб — вам лише потрібно додати глибокоскельну сіль і п'ять золотих монет, щоб запустити машину.", [5] = "Машина видає легкий гуркіт і випускає невелику кількість пари, коли починає працювати. Невдовзі вона зупиняється, випустивши ще одну хмаринку пари. Дверцята відкриваються, і всередині ви бачите партію сушеного падуба!", ["en"] = "The Hero of the Day", ["tasks"] = { ["Deeprock Salt"] = "глибокоскельна сіль", ["Deeprock Salt (Provided)"] = "глибокоскельна сіль (видано)" } },
    [880] = { [1] = "Видозмінені істоти", [2] = "Твої відкриття просто неймовірні, {ім'я}! Джерело властивостей оазисів певно надходить ззовні. А можливо навпаки, із надр, із самого лона землі.\n\nХотілось би знати, як ці проломи впливають на звірів, які п'ють з води оазисів.\n\nВистежи тріскощелепів у Застійному оазисі та на Рясноводді. А панцирі неси мені, щоб я міг їх оглянути.", [3] = "Принесіть 8 панцирів видозмінених тріскощелепів Тонзі Рунному Тотемові на Перехрестя.", [4] = "Як проходить збір? Ти {стать:дістав:дістала} панцирі?", [5] = "Дякую, {ім'я}. Вивчення звірів тієї чи іншої місцевості може багато розповісти про саму місцевість. Подивимося, що розкажуть нам ці панцирі.\n\nПрийми мою вдячність за допомогу... і візьми ці монети. Мені вони вже не треба, а тобі, можливо, ще знадобляться.", ["en"] = "Altered Beings", ["tasks"] = { ["Altered Snapjaw Shell"] = "панцир видозміненого тріскощелепа", ["Altered Snapjaw Shell (Provided)"] = "панцир видозміненого тріскощелепа (видано)" } },
    [881] = { [1] = "Ечеякі", [2] = "Біломла, або ж Ечеякі мовою тауренів - король серед котячих Савани. Він настільки майстерно таїться на полюванні, ніби тонка, біла імла, що непомітно стелиться по землі. А ще настільки миттєво вбиває свою здобич, що та не має часу жахнутися чи відчути біль.\n\nТаурени кажуть, що Ечеякі - це і милість, і смерть одночасно.\n\nОт і дізнаєшся, правда це чи вигадки. Бо нині я відряджаю тебе на шлях полювання на Ечеякі. Його лігво розташоване на північному сході від Перехрестя, серед кісток велетенського кодо.\n\nЙди. Подуй у цю сурму, коли дістанешся його лігва. Засурми - і він прийде.", [3] = "Принесіть шкуру Ечеякі до Серґри Чорношип на Перехрестя.", [4] = "Великий кіт чекає на тебе, {ім'я}.", [5] = "Ти {стать:здолав:здолала} Ечеякі, і хоча його дні полювання скінчилися... його дух віднині - з тобою. Він навчить тебе виявляти силу в грації та честь у милосерді.\n\nТвій шлях ще довгий, {клас:к}. Сподіваймося ж, що ти легко ним ітимеш.", ["en"] = "Echeyakee", ["tasks"] = { ["Echeyakee's Hide"] = "шкура Ечеякі", ["Echeyakee's Hide (Provided)"] = "шкура Ечеякі (видано)" } },
    [882] = { [1] = "Ішамугал", [2] = "Ішамугал, Списезуб - найлютіший сонцелуский раптор Степів. Він не полює ні заради спорту, ні заради їжі. Він полює, бо полювання - його пристрасть. І він убиває, бо його природа - вбивати.\n\nА ти повчишся у його природи, {Ім'я}, тому що твій шлях тепер проходить по кігтистих слідах Ішамугала.\n\nРозпочни полювання. Убий його улюблену здобич, жевру, та принеси її тушу до мертвого дерева на північний захід від Брашпиля. Ішамугал унюхає її і з'явиться на її запах.\n\nБудь {стать:готовий:готова} до його приходу.", [3] = "Принесіть ікло Ішамугала до Джорна в табір Таурахо.", [4] = "{Ім'я}, ти {стать:здолав:здолала} Ішамугала?", [5] = "Саме ікло - не більше, ніж сувенір, але те, що воно уособлює, має глибокий зміст.\n\nСила Ішамугала в тобі, {Ім'я}. Користуйся ж нею розсудливо. Це - твій тягар.\n\nІ це ж твоя честь.", ["en"] = "Ishamuhale", ["tasks"] = { ["Ishamuhale's Fang"] = "ікло Ішамугала", ["Ishamuhale's Fang (Provided)"] = "ікло Ішамугала (видано)" } },
    [8828] = { [1] = "Подарунки Зими", [2] = "Я чув, що Дідусь Зима — за сприяння Пасовищ Димного Лісу — поклав під ялинку в Орґріммарі подарунки для всіх і кожного. Шкода, що мені не можна туди піти, адже мені потрібно наглядати PX-238 Зимовим Дивовижем.\n\nАле тобі варто неодмінно туди зазирнути. Я впевнений, що Дідусь Зима знайшов подарунок і для тебе.", [3] = "Поговоріть з Дідусем Зимою біля торгового майданчика Пасовищ Димного Лісу в Орґріммарі.", [5] = "О, хо-хо, привіт! Ти тут лише з однією метою: розпакувати свої подарунки на свято Зимової Покрови.\n\nНе хвилюйся, Дідусь Зима не забув {стать:свого улюбленого:свою улюблену} {раса:з}. Поглянь під ялинку і ти знайдеш свої подарунки.\n\nВ цей чудовий час подарунків, можливо, твої друзі також були б раді отримати якісні продукти від Пасовищ Димного Лісу?", ["en"] = "Winter's Presents" },
    [883] = { [1] = "Лакота'мані", [2] = "Копито Лакота'мані є символом сили величного кодо.", [3] = "Принесіть копито Лакота'мані Джорну в табір Таурахо.", [4] = "{ім'я}, я помітив нову силу у твоїй ході. Скажи мені, чи твій дух вже зустрівся з величним Лакота'мані?", [5] = "Лакота'мані нашою мовою означає «землеструс», адже кроки його - здригають наче грім. Він тепер із тобою, а мужність його сплететься із твоєю. Відтепер, немає такої проблеми з якою б ти не {стать:впорався:впоралась}.\n\nШануйся, {ім'я}. Знай собі ціну, Землеструсе.", ["en"] = "Lakota'mani", ["tasks"] = { ["Hoof of Lakota'mani"] = "копито Лакота'мані", ["Hoof of Lakota'mani (Provided)"] = "копито Лакота'мані (видано)" } },
    [884] = { [1] = "Оватанка", [2] = "Коли ви торкаєтесь хвостового шипа Оватанки, з нього вилітають іскри.", [3] = "Принесіть хвостовий шип Оватанки Джорну в табір Таурахо.", [4] = "{Ім'я:к}, я бачу у твоїх очах сяйво нової сили! Ти {стать:зустрівся:зустрілась} з могутньою Оватанкою, чи не так?", [5] = "Ім'я громоящірки Оватанки мовою тауренів означає \"блакитна блискавка\", бо в ній живе стрімкість, не властива її розмірам. Кажуть, що Оватанку колись вразила блискавка і, наситившись гнівом небес, вона отримала безмежний запас сил.\n\nНехай її енергія тече в тобі, {ім'я:к}. Бо тепер ти не {стать:поступився б:поступилась би} Оватанці в стрімкості.", ["en"] = "Owatanka", ["tasks"] = { ["Owatanka's Tailspike"] = "хвостовий шип Оватанки", ["Owatanka's Tailspike (Provided)"] = "хвостовий шип Оватанки (видано)" } },
    [885] = { [1] = "Ваште Пауні", [2] = "До пера Ваште Пауні боляче доторкатися.", [3] = "Принесіть Джорну Небесному Провидцю в табір Таурахо перо Ваште Пауні.", [4] = "Бачу, ти {стать:сповнений:сповнена} рішучості, {ім'я}. рішучості, породженої болем...\n\nТебе обтяжує смерть Ваште Пауні?", [5] = "Громояструби — рідкісні звірі Степів, і їх смерть передвіщає велику удачу або ж велику загибель.\n\nАле смерть Ваште Пауні, що мовою тауренів означає \"Пожирач Духів\", не означає ні те, ні інше... або і те, і інше.\n\nБіль, що ти {стать:відчув:відчула} під час полювання на Пожирача Духів, — це біль, якого зазнають усі, хто досягає величі великою ціною. Цей біль — наслідок жалю.\n\nВтім, я бачу, що тобі вдалось впоратись з ним. Ти {стать:зрозумів:зрозуміла}, що жаль перетворюється на мудрість і лише через біль можна здобути силу.\n\nТи багато чого {стать:навчився:навчилась}, {ім'я}.", ["en"] = "Washte Pawne", ["tasks"] = { ["Washte Pawne's Feather"] = "перо Ваште Пауні", ["Washte Pawne's Feather (Provided)"] = "перо Ваште Пауні (видано)" } },
    [8861] = { [1] = "Святкування Нового року!", [2] = "Громовий Бескид влаштовує святкування Нового року! Там сьогодні цілий день можна пити задарма, а ввечері буде феєрверк!\n\nЦе має бути дуже гарно... але в Грабіжній Бухті теж сьогодні влаштовують вечірку. Я впевнений, що там буде ще краще!\n\nВ будь-якому разі, корчмарці Пала з Громового Бескиду потрібні припаси Пасовищ Димного Лісу, щоб нагодувати всіх учасників святкування. Можеш допомогти мені та доставити це?\n\nДякую, {ім'я}! Корчмарка Пала знаходиться в таверні біля мосту на Верхів'я Мисливців.", [3] = "Принесіть припаси Димного Лісу корчмарці Палі в Громовий Бескид.", [4] = "Доброго дня, {клас:к}! Ти {стать:прибув:прибула} до Громового Бескиду на наше свято? Чи ти тут, щоб відпочити між полюваннями?", [5] = "О, дуже добре! Ці припаси допоможуть нагодувати всіх, хто святкує Новий рік!\n\nЯ дякую тобі, {ім'я}. Я у тебе в боргу. Прошу, візьми ці монети... і прислухайся до моєї поради — пий від душі з бочок надворі, і приєднуйся до наших гуляк у танці!", ["en"] = "New Year Celebrations!", ["tasks"] = { ["Smokywood Supplies"] = "припаси Димного Лісу", ["Smokywood Supplies (Provided)"] = "припаси Димного Лісу (видано)" } },
    [88718] = { [1] = "Ніколи не відпочиває", [2] = "Приводьте мені будь-які приречені душі, які перетинаються на вашому шляху, {ім'я}.\n\nДозвольте мені перефразувати це – ви ПОВИННІ привести їх до мене.\nМій обов'язок – залишатися та направляти душі загиблих. Ваш обов'язок – привести їх до мене.\n\nПорада: ніколи не беріть більше однієї душі одночасно. Повірте мені, ваша душа може витримати лише певну кількість, а ваш розум... ну... він може витримати ще менше.\n\nЦей тягар тепер ваш. Тому що ви можете, ви повинні.\n\nВважайте це моральним обов'язком.", [3] = "Принесіть ще одне Серце Долі Брату Луктусу в Каплицю Надії Світла у Східних Чумних землях.", [4] = "Лихо ніколи не відпочиває, тому ми ніколи не повинні відпочивати, {ім'я}.", [5] = "{ім'я}, з кожним поверненим серцем я стою в покорі. Деякі з душ належать могутнім воїнам. Деякі здавалися незламними... і все ж... вони впали.\n\nБич охопив їх, корупція проникла в їхні розуми, або, в деяких випадках, вони добровільно скорилися.\n\nТака величезна сила була знищена.\n\nІ тепер, завдяки вам, вони зберігають свою останню крихту доблесті.\n\nБез вас жахи їхньої смерті переважили б героїзм їхнього життя.", ["en"] = "Never at Rest" },
    [8873] = { [1] = "Місячний фестиваль", [2] = "Настала ця пора року, {ім'я}! Кенарійське Коло запрошує всіх жителів Азероту взяти участь у нашому святкуванні Місячного фестивалю. У місті ти знайдеш провісницю Місячного фестивалю. Вона знаходиться в місці, позначеному благословенним колом місячного сяйва. Вона розповість тобі більше про це свято.", [3] = "Поговоріть з провісницею Місячного фестивалю в долині Мудрості в Орґріммарі. Ви також можете поговорити з провісниками Місячного фестивалю в інших столицях.", [5] = "Вітаю, {ім'я}. Ти тут, щоб приєднатися до святкування?", ["en"] = "The Lunar Festival" },
    [8874] = { [1] = "Місячний фестиваль", [2] = "Настала ця пора року, {ім'я}! Кенарійське Коло запрошує всіх жителів Азероту взяти участь у нашому святкуванні Місячного фестивалю. У місті ти знайдеш провісницю Місячного фестивалю. Вона знаходиться в місці, позначеному благословенним колом місячного сяйва. Вона розповість тобі більше про це свято.", [3] = "Поговоріть з провісницею Місячного фестивалю біля входу в Підмістя. Ви також можете поговорити з провісниками Місячного фестивалю в інших столицях.", [5] = "Вітаю, {ім'я}. Ти тут, щоб приєднатися до святкування?", ["en"] = "The Lunar Festival" },
    [88747] = { [1] = "Освячені точильні камені", [4] = "Якщо ти принесеш мені вісім некротичних рун від загарбників Бичі, я можу дати тобі освячений камінь для точення. Він має дуже допомогти тобі в битві проти поплічників Короля-Ліча.", [5] = "Дякую, {ім'я}. Ось ваші освячені точильні камені. Використовуйте їх розсудливо.", ["en"] = "Consecrated Sharpening Stones" },
    [88749] = { [1] = "Тьмяний некротичний кристал", [2] = "На трупі полеглого витвора ви знайдете кристал, який слабко випромінює некротичну енергію.", [3] = "Принесіть Слабкий Некротичний Кристал лейтенанту Рукагу у внутрішній двір Підмістя.", [4] = "Чи можу я вам чимось допомогти?", [5] = "Ви кажете, що це було взято у витвора, який атакував місто?\n\nМи отримали звістку про базові табори некрополів, які викликає Бич. Я підозрюю, що вони намагалися створити один у Підмісті. Нам доведеться бути пильними в майбутньому.", ["en"] = "Faint Necrotic Crystal" },
    [8875] = { [1] = "Місячний фестиваль", [2] = "Настала ця пора року, {ім'я}! Кенарійське Коло запрошує всіх жителів Азероту взяти участь у нашому святкуванні Місячного фестивалю. У місті ти знайдеш провісницю Місячного фестивалю. Вона знаходиться в місці, позначеному благословенним колом місячного сяйва. Вона розповість тобі більше про це свято.", [3] = "Поговоріть з провісницею Місячного фестивалю на Верхів'ї Старійшин в Громовому Бескиді. Ви також можете поговорити з провісниками Місячного фестивалю в інших столицях.", [5] = "Вітаю, {ім'я}. Ти тут, щоб приєднатися до святкування?", ["en"] = "The Lunar Festival" },
    [88882] = { [1] = "Благословенна чарівна олія", [4] = "В обмін на некротичні руни загарбників Бичі, Срібний Світанок дасть вам одну пляшечку благословенної чарівної олії.", [5] = "Сподіваюся, що ці предмети стануть вам у пригоді в майбутніх битвах.", ["en"] = "Blessed Wizard Oil" },
    [889] = { [1] = "Дух вітру", [4] = "Принеси Кривозубові 10 кривавих скалок, і я благословлю тебе великою швидкістю. Ти бігатимеш нарівні з жеврами, і навіть вітер тобі позаздрить.\n\nТриватиме це не довго, але має бути достатньо для того, щоб перетнути Степи.", [5] = "Гаразд. Тепер можеш відправлятися в путь, і нехай дух Аґамаґґана веде тебе у правильному напрямку, {раса:к}. Повертайся до мене, якщо знадобиться більше чарів Аґамаґґана.", ["en"] = "Spirit of the Wind", ["tasks"] = { ["Blood Shard"] = "кривавий скалок", ["Blood Shard (Provided)"] = "кривавий скалок (видано)" } },
    [88968] = { [1] = "Повелитель Чорнокамінної гори", [2] = "Знайдіть Верховного Повелителя Саурфанга в Долині Сили.", [3] = "Поговоріть з Верховним Повелителем Саурфангом в Орґріммарі. Він чекає на вас у Долині Сили.", [5] = "Обери собі нагороду, щоб я міг зійти на голову звіра на загальний огляд.", ["en"] = "The Lord of Blackrock" },
    [8900] = { [1] = "Люба Еленіє,", [2] = "Вона була такою сумною. Я зрозумів це, щойно побачив її. Тобто, вона здавалася сумною — розумієш?\n\nАле після розмови у нас з нею виник зв'язок. Ніколи не міг подумати, що хтось зможе зрозуміти мене, але вона змогла!\n\nКоли я розповів про це іншим, вони сміялися з мене, тому я більше з нею не розмовляв. Але я сумую за нею. Можеш передати їй цього листа? Я хочу бути впевненим, що він потрапить до неї.", [3] = "Доставте злегка пом'яту записку Еленії Гайдон біля банку Підмістя.", [4] = "О, і чим я зобов'язана такій радості?", [5] = "Не очікувала, що орки можуть бути такими красномовними. Звісно у нас не було можливості дізнатися про них більше до цього часу. Дякую, що {стать:приніс:принесла} мені це.", ["en"] = "Dearest Elenia,", ["tasks"] = { ["Slightly Creased Note"] = "злегка пом'ята записка", ["Slightly Creased Note (Provided)"] = "злегка пом'ята записка (видано)" } },
    [8901] = { [1] = "Люба Еленіє,", [2] = "Чи відомо тобі, що таке кохання, {стать:юначе:дівчино}? Донедавна воно було для мене чимось чужим, але потім я зустрів у Підмісті ту дівчину — Еленію. Для мого народу це рідкісна подія — зупинити свій погляд на комусь іншої раси, не кажучи вже про відречених.\n\nА вона полонила мої думки, і я думаю про неї що вдень, що вночі.\n\nЧи не зможеш ти передати ти їй цього листа? Я хочу, щоб вона приїхала сюди, в Мулґор. Сподіваюся, вона погодиться.", [3] = "Доставте ретельно написаного листа Еленії Гайдон біля банку Підмістя.", [4] = "О, і чим я зобов'язана такій радості?", [5] = "Які милі слова написав мені Темма. Але, попри те, що його слова зворушили мене, я не зможу покохати таурена. Наші тіла та думки занадто різні.\n\nДобре, що мені не довелося казати ці слова йому особисто. Я не зуміла б розбити його серце.", ["en"] = "Dearest Elenia,", ["tasks"] = { ["Carefully Written Letter"] = "ретельно написаний лист", ["Carefully Written Letter (Provided)"] = "ретельно написаний лист (видано)" } },
    [8902] = { [1] = "Люба Еленіє,", [2] = "Ціле життя тому я був зарученим з Еленією, моєю подругою дитинства. Минули роки відтоді, як я востаннє згадував про неї. Але останнім часом вона полонила мої думки.\n\nМожливо, після всього, що було, в нашому житті все ж залишиться місце для кохання.\n\nЯ впевнений, що вона також змінилася. Ти можеш передати їй цього листа? Я занадто хвилююся, щоб передати його особисто.", [3] = "Доставте лист, написаний з любов'ю Еленії Гайдон біля банку Підмістя.", [4] = "О, і чим я зобов'язана такій радості?", [5] = "Цей лист викликає спогади з минулого життя, {ім'я}. Еленія Тор. Таким мало бути моє прізвище. У нас була б гарна церемонія на березі озера. А коли він вийшов би на пенсію, ми б оселилися на фермі.\n\nПрості мрії.\n\nАле якби він побачив мене зараз, я сумніваюся, що він впізнав би у мені ту Еленію. Лишилась лише холодна плоть та мертве серце...", ["en"] = "Dearest Elenia,", ["tasks"] = { ["Lovingly Composed Letter"] = "лист, написаний з любов'ю", ["Lovingly Composed Letter (Provided)"] = "лист, написаний з любов'ю (видано)" } },
    [891] = { [1] = "Зброя Північної Варти", [2] = "Ці фанатики з фортеці Північної Варти потопили ще один корабель з мого флоту!\n\nПора розібратися з цими мерзотниками. Їх параноя перейшла всі межі. Ці безрозсудні негідники стріляють у все, що рухається.\n\nВирушай на південь уздовж узбережжя Торгівця до фортеці та розбий їхні війська. Принеси мені медалі їхніх солдатів як доказ. І, в ім'я мого флоту, вбий капітана Честостанну та її клятих канонірів!", [3] = "Капітан Тало'тас Ясносвіт з Брашпиля просить вас зібрати 10 медалей Терамору та вбити капітана Честостанну, каноніра Вессана та каноніра Смайта.", [4] = "Мій флот у небезпеці, капітан Честостанна та її кляті каноніри постійно стріляють по кораблях з фортеці Північної Варти. Я хочу, щоб її солдати теж заплатили за це нахабство. Принеси мені жменю їхніх медалей, і я знатиму, що ти {стать:помстився:помстилась} за моїх полеглих побратимів.", [5] = "Праведні гармати Альянсу нарешті замовкли, як шкода. Ти отримаєш винагороду за свою допомогу, {ім'я}.\n\nТепер ми можемо знайти тіла загиблих....", ["en"] = "The Guns of Northwatch", ["tasks"] = { ["Theramore Medal"] = "медаль Терамору", ["Theramore Medal (Provided)"] = "медаль Терамору (видано)" } },
    [8913] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}! По тобі видно, що тобі чимало довелося побачити і зробити в цьому світі. Але б'юся об заклад, що таких обладунків, як ці, ти ще не {стать:бачив:бачила}!\n\nЗроби мені невелику послугу, і я віддам їх тобі в обмін на звичайний набір поручів.\n\nМені потрібен зразок отрути павуків і скорпіонів, що мешкають у Силітусі. Принеси його мені разом з кількома золотими монетами, і поручі твої.", [3] = "Зберіть 15 зразків отрути з Силітуса та 20 золотих і принесіть їх разом з браслетами дикого серця Моквару в Орґріммар.", [4] = "Ти {стать:зібрав:зібрала} все необхідне, {ім'я}?", [5] = "О, так. Мукс буде в захваті.\n\nЦі поручі — частина більшого набору обладунків. Якщо ти погодишся допомагати мені й далі, я готовий розглянути можливість віддати тобі й решту.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Silithus Venom Sample"] = "зразок отрути з Силітуса", ["Silithus Venom Sample (Provided)"] = "зразок отрути з Силітуса (видано)", ["Wildheart Bracers"] = "браслети дикого серця", ["Wildheart Bracers (Provided)"] = "браслети дикого серця (видано)" } },
    [8915] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}! По тобі видно, що тобі чимало довелося побачити і зробити в цьому світі. Але б'юся об заклад, що таких обладунків, як ці, ти ще не {стать:бачив:бачила}!\n\nЗроби мені невелику послугу, і я віддам їх тобі в обмін на звичайний набір браслетів.\n\nМені потрібен зразок отрути павуків і скорпіонів, що мешкають у Силітусі. Принеси його мені разом з кількома золотими монетами, і браслети твої.", [3] = "Зберіть 15 зразків отрути з Силітуса та 20 золотих і принесіть їх разом з браслетами магістра Моквару в Орґріммар.", [4] = "Ти {стать:зібрав:зібрала} все необхідне, {ім'я}?", [5] = "О, так. Мукс буде в захваті.\n\nЦі браслети — частина більшого набору обладунків. Якщо ти погодишся допомагати мені й далі, я готовий розглянути можливість віддати тобі й решту.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Magister's Bindings"] = "браслети магістра", ["Magister's Bindings (Provided)"] = "браслети магістра (видано)", ["Silithus Venom Sample"] = "зразок отрути з Силітуса", ["Silithus Venom Sample (Provided)"] = "зразок отрути з Силітуса (видано)" } },
    [8917] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}! По тобі видно, що тобі чимало довелося побачити і зробити в цьому світі. Але б'юся об заклад, що таких обладунків, як ці, ти ще не {стать:бачив:бачила}!\n\nЗроби мені невелику послугу, і я віддам їх тобі в обмін на звичайний набір поручів.\n\nМені потрібен зразок отрути павуків і скорпіонів, що мешкають у Силітусі. Принеси його мені разом з кількома золотими монетами, і поручі твої.", [3] = "Зберіть 15 зразків отрути з Силітуса та 20 золотих і принесіть їх разом з поручами тіньового ремесла Моквару в Орґріммар.", [4] = "Ти {стать:зібрав:зібрала} все необхідне, {ім'я}?", [5] = "О, так. Мукс буде в захваті.\n\nЦі поручі — частина більшого набору обладунків. Якщо ти погодишся допомагати мені й далі, я готовий розглянути можливість віддати тобі й решту.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Shadowcraft Bracers"] = "браслети тіньового ремесла", ["Shadowcraft Bracers (Provided)"] = "браслети тіньового ремесла (видано)", ["Silithus Venom Sample"] = "зразок отрути з Силітуса", ["Silithus Venom Sample (Provided)"] = "зразок отрути з Силітуса (видано)" } },
    [8920] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}! По тобі видно, що тобі чимало довелося побачити і зробити в цьому світі. Але б'юся об заклад, що таких обладунків, як ці, ти ще не {стать:бачив:бачила}!\n\nЗроби мені невелику послугу, і я віддам їх тобі в обмін на звичайний набір поручів.\n\nМені потрібен зразок отрути павуків і скорпіонів, що мешкають у Силітусі. Принеси його мені разом з кількома золотими монетами, і поручі твої.", [3] = "Зберіть 15 зразків отрути з Силітуса та 20 золотих і принесіть їх разом з браслетами доблесті Моквару в Орґріммар.", [4] = "Ти {стать:зібрав:зібрала} все необхідне, {ім'я}?", [5] = "О, так. Мукс буде в захваті.\n\nЦі поручі — частина більшого набору обладунків. Якщо ти погодишся допомагати мені й далі, я готовий розглянути можливість віддати тобі й решту.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Bracers of Valor"] = "браслети доблесті", ["Bracers of Valor (Provided)"] = "браслети доблесті (видано)", ["Silithus Venom Sample"] = "зразок отрути з Силітуса", ["Silithus Venom Sample (Provided)"] = "зразок отрути з Силітуса (видано)" } },
    [8923] = { [1] = "Надприродний пристрій", [2] = "Ти, мабуть, дуже {стать:хоробрий:хоробра}, якщо {стать:залишився:залишилась}. Або я зацікавив тебе тим обладунком. Так, у мене є й інші частини цього обладунку, і ти їх отримаєш, якщо продовжиш допомагати мені.\n\nЗразки отрути, що ти {стать:зібрав:зібрала}, призначені для мого знайомого, Мукса Маношкряба, інженера, який цікавиться всім надприродним. Його останній проєкт — пристрій, що дозволяє спілкуватися з мертвими! Я сподіваюся за допомогою цього приладу зв'язатися з Антіоном і отримати від нього пораду.", [3] = "Принесіть запечатаний контейнер з отрутою Муксу Маношкрябу в Пристроблях, що в Танарісі.", [4] = "Ти хочеш щось мені сказати?", [5] = "Чудово! Вона в мене якраз закінчується!\n\nКажеш, тебе Моквар прислав?", ["en"] = "A Supernatural Device", ["tasks"] = { ["Sealed Venom Container"] = "запечатаний контейнер з отрутою", ["Sealed Venom Container (Provided)"] = "запечатаний контейнер з отрутою (видано)" } },
    [8927] = { [1] = "Гідна винагорода", [2] = "Ти {стать:довів:довела}, що на тебе можна покластися, {ім'я}. Оскільки я вірю, що ти допоможеш мені виплутатися з цих неприємностей, було б мудро з мого боку винагородити тебе за твої старання.\n\nТепер я обміняю твій пояс і рукавички. Якщо ми доведемо справу до кінця, я віддам тобі й решту речей.", [3] = "Принесіть пояс дикого серця та рукавички дикого серця Моквару в Орґріммар.", [4] = "{стать:Готовий:Готова} до обміну?", [5] = "Наша угода залишається в силі. Тільки пам'ятай, що це лише дещиця того, що на тебе чекає. Звільни мене від цього прокляття, і я щедро винагороджу тебе гарними речами.", ["en"] = "Just Compensation", ["tasks"] = { ["Wildheart Belt"] = "пояс дикого серця", ["Wildheart Belt (Provided)"] = "пояс дикого серця (видано)", ["Wildheart Gloves"] = "рукавички дикого серця", ["Wildheart Gloves (Provided)"] = "рукавички дикого серця (видано)" } },
    [893] = { [1] = "Бажана зброя", [2] = "На південь, по той бік Поля велетнів, свинобрази племені Бритвогривих не мають майстерних ковалів, як мені казали, але, схоже, вони додумалися розробити міцнішу зброю. Мені хотілося б отримати кілька зразків, щоб вивчити їхню техніку роботи... Думаєш, це можливо?\n\nЯкщо хочеш принести славу Орді - дістань для мене зразки цієї зброї. Мені знадобиться кинджал їхніх ловців, паличка провидців і щит, що носять їхні очмани. Цього має вистачити!", [3] = "Принесіть Таттернакові Сталевару в табір Таурахо, що в Степах, стилет, обгорілу паличку та бойовий щит Бритвогривих.", [4] = "Я теж сумніваюся в тому, що жалюгідні свинобрази можуть навчитися ковальству, проте я виконую накази воєвождя, тому я маю дізнатися якомога більше про плем'я Бритвогривих.\n\nУ мене були і гірші завдання, та я охоче виконую їх заради добробуту орків.", [5] = "Чудові, справді чудові екземпляри.\n\nСвинобрази куди вправніші, ніж я очікував.\n\nОсь, {клас:к}, візьми це і не заважай! А мені треба ознайомитися з цією зброєю. Схоже, ми недооцінили нашого ворога, а такої помилки ми не можемо собі дозволити.", ["en"] = "Weapons of Choice", ["tasks"] = { ["Charred Razormane Wand"] = "обгоріла паличка Бритвогривих", ["Charred Razormane Wand (Provided)"] = "обгоріла паличка Бритвогривих (видано)", ["Razormane Backstabber"] = "стилет Бритвогривих", ["Razormane Backstabber (Provided)"] = "стилет Бритвогривих (видано)", ["Razormane War Shield"] = "бойовий щит Бритвогривих", ["Razormane War Shield (Provided)"] = "бойовий щит Бритвогривих (видано)" } },
    [8930] = { [1] = "У пошуках Антіона", [2] = "Що ж, {ім'я}. Нам залишається випробувати гоблінський винахід. Кажуть, Антіон загинув під натиском легіонів Стратгольма, коли намагався увійти до його воріт.\n\nСпробуй скористатися цим пристроєм там і перевір, чи справді ти зможеш розмовляти з мертвими!", [3] = "Скористайтесь міжвимірним шукачем привидів біля входу до Стратгольма і поговоріть з привидом Антіона Гармона.", [5] = "Тебе прислав Моквар? Я зроблю все можливе, щоб допомогти тобі, та спершу маю попросити про послугу.", ["en"] = "In Search of Anthion", ["tasks"] = { ["Extra-Dimensional Ghost Revealer"] = "міжвимірний шукач привидів" } },
    [8938] = { [1] = "Гідна винагорода", [2] = "Ти {стать:довів:довела}, що на тебе можна покластися, {ім'я}. Оскільки я вірю, що ти допоможеш мені виплутатися з цих неприємностей, було б мудро з мого боку винагородити тебе за твої старання.\n\nТепер я обміняю твій пояс і рукавички. Якщо ми доведемо справу до кінця, я віддам тобі й решту речей.", [3] = "Принесіть пояс ловця звірів та рукавички ловця звірів Моквару в Орґріммар.", [4] = "{стать:Готовий:Готова} до обміну?", [5] = "Наша угода залишається в силі. Тільки пам'ятай, що це лише дещиця того, що на тебе чекає. Звільни мене від цього прокляття, і я щедро винагороджу тебе гарними речами.", ["en"] = "Just Compensation", ["tasks"] = { ["Beaststalker's Belt"] = "пояс ловця звірів", ["Beaststalker's Belt (Provided)"] = "пояс ловця звірів (видано)", ["Beaststalker's Gloves"] = "рукавички ловця звірів", ["Beaststalker's Gloves (Provided)"] = "рукавички ловця звірів (видано)" } },
    [8939] = { [1] = "Гідна винагорода", [2] = "Ти {стать:довів:довела}, що на тебе можна покластися, {ім'я}. Оскільки я вірю, що ти допоможеш мені виплутатися з цих неприємностей, було б мудро з мого боку винагородити тебе за твої старання.\n\nТепер я обміняю твій пояс і рукавички. Якщо ми доведемо справу до кінця, я віддам тобі й решту речей.", [3] = "Принесіть пояс магістра та рукавички магістра Моквару в Орґріммар.", [4] = "{стать:Готовий:Готова} до обміну?", [5] = "Наша угода залишається в силі. Тільки пам'ятай, що це лише дещиця того, що на тебе чекає. Звільни мене від цього прокляття, і я щедро винагороджу тебе гарними речами.", ["en"] = "Just Compensation", ["tasks"] = { ["Magister's Belt"] = "пояс магістра", ["Magister's Belt (Provided)"] = "пояс магістра (видано)", ["Magister's Gloves"] = "рукавички магістра", ["Magister's Gloves (Provided)"] = "рукавички магістра (видано)" } },
    [8940] = { [1] = "Гідна винагорода", [2] = "Ти {стать:довів:довела}, що на тебе можна покластися, {ім'я}. Оскільки я вірю, що ти допоможеш мені виплутатися з цих неприємностей, було б мудро з мого боку винагородити тебе за твої старання.\n\nТепер я обміняю твій пояс і рукавички. Якщо ми доведемо справу до кінця, я віддам тобі й решту речей.", [3] = "Принесіть пояс відданості та рукавички відданості Моквару в Орґріммар.", [4] = "{стать:Готовий:Готова} до обміну?", [5] = "Наша угода залишається в силі. Тільки пам'ятай, що це лише дещиця того, що на тебе чекає. Звільни мене від цього прокляття, і я щедро винагороджу тебе гарними речами.", ["en"] = "Just Compensation", ["tasks"] = { ["Devout Belt"] = "пояс відданості", ["Devout Belt (Provided)"] = "пояс відданості (видано)", ["Devout Gloves"] = "рукавички відданості", ["Devout Gloves (Provided)"] = "рукавички відданості (видано)" } },
    [8942] = { [1] = "Гідна винагорода", [2] = "Ти {стать:довів:довела}, що на тебе можна покластися, {ім'я}. Оскільки я вірю, що ти допоможеш мені виплутатися з цих неприємностей, було б мудро з мого боку винагородити тебе за твої старання.\n\nТепер я обміняю твій ремінь та рукавиці. Якщо ми доведемо справу до кінця, я віддам тобі й решту речей.", [3] = "Принесіть ремінь стихій та рукавиці стихій Моквару в Орґріммар.", [4] = "{стать:Готовий:Готова} до обміну?", [5] = "Наша угода залишається в силі. Тільки пам'ятай, що це лише дещиця того, що на тебе чекає. Звільни мене від цього прокляття, і я щедро винагороджу тебе гарними речами.", ["en"] = "Just Compensation", ["tasks"] = { ["Cord of Elements"] = "ремінь стихій", ["Cord of Elements (Provided)"] = "ремінь стихій (видано)", ["Gauntlets of Elements"] = "рукавиці стихій", ["Gauntlets of Elements (Provided)"] = "рукавиці стихій (видано)" } },
    [8943] = { [1] = "Гідна винагорода", [2] = "Ти {стать:довів:довела}, що на тебе можна покластися, {ім'я}. Оскільки я вірю, що ти допоможеш мені виплутатися з цих неприємностей, було б мудро з мого боку винагородити тебе за твої старання.\n\nТепер я обміняю твій пояс і рукавиці. Якщо ми доведемо справу до кінця, я віддам тобі й решту речей.", [3] = "Принесіть пояс імли жаху та обмотки імли жаху Моквару в Орґріммар.", [4] = "{стать:Готовий:Готова} до обміну?", [5] = "Наша угода залишається в силі. Тільки пам'ятай, що це лише дещиця того, що на тебе чекає. Звільни мене від цього прокляття, і я щедро винагороджу тебе гарними речами.", ["en"] = "Just Compensation", ["tasks"] = { ["Dreadmist Belt"] = "пояс імли жаху", ["Dreadmist Belt (Provided)"] = "пояс імли жаху (видано)", ["Dreadmist Wraps"] = "обмотки імли жаху", ["Dreadmist Wraps (Provided)"] = "обмотки імли жаху (видано)" } },
    [8944] = { [1] = "Гідна винагорода", [2] = "Ти {стать:довів:довела}, що на тебе можна покластися, {ім'я}. Оскільки я вірю, що ти допоможеш мені виплутатися з цих неприємностей, було б мудро з мого боку винагородити тебе за твої старання.\n\nТепер я обміняю твій пояс і рукавиці. Якщо ми доведемо справу до кінця, я віддам тобі й решту речей.", [3] = "Принесіть пояс доблесті та рукавиці доблесті Моквару в Орґріммар.", [4] = "{стать:Готовий:Готова} до обміну?", [5] = "Наша угода залишається в силі. Тільки пам'ятай, що це лише дещиця того, що на тебе чекає. Звільни мене від цього прокляття, і я щедро винагороджу тебе гарними речами.", ["en"] = "Just Compensation", ["tasks"] = { ["Belt of Valor"] = "пояс доблесті", ["Belt of Valor (Provided)"] = "пояс доблесті (видано)", ["Gauntlets of Valor"] = "рукавиці доблесті", ["Gauntlets of Valor (Provided)"] = "рукавиці доблесті (видано)" } },
    [8957] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Моквара та скажи йому, що Бодлі — його єдиний шанс знайти інші частини. Поговори з ним і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Моквара в Орґріммар з чоботами стихій, кілтом стихій та напліччям стихій.", [4] = "Ти {стать:повернувся:повернулась}, і я бачу по твоїх очах, що ти хочеш мені багато чого розповісти, {ім'я}. Та спершу подбаймо про твою винагороду.", [5] = "На нас наклали це прокляття за один лише медальйон. Лорд Вальталак, безумовно, вміє затаїти образу.\n\nМи постараємося знайти решту частин — сподіваюся, до того, як я загину. Але спершу давай обговоримо твою винагороду.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Boots of Elements"] = "чоботи стихій", ["Boots of Elements (Provided)"] = "чоботи стихій (видано)", ["Kilt of Elements"] = "кілт стихій", ["Kilt of Elements (Provided)"] = "кілт стихій (видано)", ["Pauldrons of Elements"] = "напліччя стихій", ["Pauldrons of Elements (Provided)"] = "напліччя стихій (видано)" } },
    [897] = { [1] = "Жнець", [2] = "Ця дивна, комахоподібна істота виглядає неприродно для Степів.", [3] = "Принесіть Джорнові Небесному Провидцю голову женця.", [4] = "Тебе щось турбує, {ім'я}. Як проходить твоє навчання в Степах? Що тебе так схвилювало?", [5] = "Я нічого не можу сказати про природу цього звіра, бо його духу не залишилось. Але, як ти вже {стать:здогадався:здогадалась}, йому не місце в Степах. Боюся, він може бути вісником похмурого майбутнього для нашого народу...\n\nА поки що готуйся до найгіршого і будемо сподіватися, що з часом ми розгадаємо таємницю цієї істоти.", ["en"] = "The Harvester", ["tasks"] = { ["Harvester's Head"] = "голова женця", ["Harvester's Head (Provided)"] = "голова женця (видано)" } },
    [8978] = { [1] = "Повернення до Моквара", [2] = "Приємно було попрацювати з тобою, {ім'я}. Ось готовий пристрій.\n\nСподіваюся, він допоможе у твоїй справі. Так, і якщо ти не проти, розповідай усім про мене. Мені нові клієнти не завадять!", [3] = "Поверніться до Моквара в Орґріммар з міжвимірним шукачем привидів.", [4] = "Ти {стать:повернувся:повернулась} з пристроєм?", [5] = "Ти {стать:повернувся:повернулась} з пристроєм! Я вражений твоєю відданістю, {ім'я}. Гарна робота.", ["en"] = "Return to Mokvar", ["tasks"] = { ["Extra-Dimensional Ghost Revealer"] = "міжвимірний шукач привидів", ["Extra-Dimensional Ghost Revealer (Provided)"] = "міжвимірний шукач привидів (видано)" } },
    [898] = { [1] = "На волю!", [2] = "Нарешті! Хтось прийшов мені на поміч!\n\nНе можу повірити, що ти {стать:пройшов:пройшла} повз вартових. Ці фанатики з Терамору не сповна розуму. Вони потопили наш корабель і ув'язнили мене, єдиного вцілілого. Мене назвали ворогом і загрозою для Альянсу.\n\nЯ! Загроза цілковитому стидовиську Альянсу? Я був матросом на судні, що перевозило самогон від Брашпиля до Грабіжної Бухти.\n\nГоді базікати. Допоможеш мені повернутися до Брашпиля? Дай мені знати, коли будеш {стать:готовий:готова}, і ми втечемо звідси.", [3] = "Забезпечте безпечний супровід Гілтаресу Вогневіту до капітана Ясносвіта в Брашпиль.", [4] = "Га?", [5] = "Отакої! Ми гадали, що Вогневіт давно згинув!\n\nТвій подвиг здобув тобі почесне місце серед корсарів Тало'дану, {ім'я}.", ["en"] = "Free From the Hold", ["tasks"] = { ["Escort Gilthares Firebough back to Ratchet"] = "Супровід Гілтереса Фаєрбауа назад до Ретчета" } },
    [899] = { [1] = "Поглинутий ненавистю", [2] = "Можливо, тобі відома мука постійної невпевненості, а, можливо, й ні, {клас:к}. Але уяви собі: я стою тут кожнісінький день, від сходу сонця до його заходу, вишукуючи на горизонті цих потвор. Я вбивав кожну людиноподібну свиню на своєму шляху, проте моя жага їхньої крові далека від утамування. Напевно, замість того, щоб іти на північ до Перехрестя, мені варто було б прямувати в Таурахо.\n\nТи, {клас:к} - ти {стать:міг би:могла б} мені допомогти.\n\nПовбивай їх. Забий стільки, скільки зможеш. Принеси мені їхні ікла, і ми разом відсвяткуємо їхню кончину.", [3] = "Принесіть 60 ікл щетиношкурих свинобразів Манкріку на Перехрестя.", [4] = "Свинобрази за це заплатять, {ім'я}. Присягаюсь!", [5] = "{Клас:к}, ти відповідально {стать:поставився:поставилася} до мого заклику, і за це я дякую тобі.\n\nМоя жага помсти нікуди не поділася, проте тепер я, принаймні, можу усміхнутися, знаючи, що свинобрази теж відчули біль.", ["en"] = "Consumed by Hatred", ["tasks"] = { ["Bristleback Quilboar Tusk"] = "ікло щетиношкурого свинобраза", ["Bristleback Quilboar Tusk (Provided)"] = "ікло щетиношкурого свинобраза (видано)" } },
    [8998] = { [1] = "Повернення на початок", [2] = "Схоже, що настав час прощатися, {стать:друже:подруго}. Але я завжди буду тут, якщо ти захочеш поговорити зі мною. Приходь, коли хочеш. Можливо, поки будеш чекати тут на друзів для походу до Чорноскельного шпиля.\n\nВсе, йди, поки я не розплакався. Повертайся до Моквара в Орґріммар і розкажи йому про все, що сталося.", [3] = "Поговоріть з Мокваром у фортеці Ґроммаш, розташованій в долині Мудрості, що в Орґріммарі.", [5] = "Радий бачити, що тобі вдалось повернутись до мене, {ім'я}. Виглядаєш чудово, хіба що трохи {стать:загартованішим:загартованішою}.\n\nДавай, розказуй мені про все, що з тобою сталося.", ["en"] = "Back to the Beginning" },
    [9007] = { [1] = "Найкраще — наостанок", [2] = "Це справді дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Твої зусилля звільнили нас від наслідків наших минулих помилок.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись. Ти їх {стать:заслужив:заслужила}.", [3] = "Віддайте Моквару капюшон дикого серця та жилет дикого серця.", [4] = "Ти {стать:готовий:готова} віддати частини свого обладунку дикого серця в обмін на новий капюшон та жилет лютого серця?", [5] = "Я справді сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки. Нехай вони довго служать тобі у твоїх великих діяннях!", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Wildheart Cowl"] = "капюшон дикого серця", ["Wildheart Cowl (Provided)"] = "капюшон дикого серця (видано)", ["Wildheart Vest"] = "жилет дикого серця", ["Wildheart Vest (Provided)"] = "жилет дикого серця (видано)" } },
    [9008] = { [1] = "Найкраще — наостанок", [2] = "Це справді дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Твої зусилля звільнили нас від наслідків наших минулих помилок.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись. Ти їх {стать:заслужив:заслужила}.", [3] = "Віддайте Моквару шапку ловця звірів та мундир ловця звірів.", [4] = "Ти {стать:готовий:готова} віддати частини свого обладунку ловця звірів в обмін на нову шапку та мундир володаря звірів?", [5] = "Я справді сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки. Нехай вони довго служать тобі у твоїх великих діяннях!", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Beaststalker's Cap"] = "шапка ловця звірів", ["Beaststalker's Cap (Provided)"] = "шапка ловця звірів (видано)", ["Beaststalker's Tunic"] = "мундир ловця звірів", ["Beaststalker's Tunic (Provided)"] = "мундир ловця звірів (видано)" } },
