    [9012] = { [1] = "Найкраще — наостанок", [2] = "Це справді дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Твої зусилля звільнили нас від наслідків наших минулих помилок.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись. Ти їх {стать:заслужив:заслужила}.", [3] = "Віддайте Моквару маску імли жаху та мантію імли жаху.", [4] = "Як ми й домовлялись, ти {стать:готовий:готова} віддати частини свого обладунку імли жаху в обмін на нову маску та мантію імли смерті?", [5] = "Я справді сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки. Нехай вони довго служать тобі у твоїх великих діяннях!", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Dreadmist Mask"] = "маска імли жаху", ["Dreadmist Mask (Provided)"] = "маска імли жаху (видано)", ["Dreadmist Robe"] = "мантія імли жаху", ["Dreadmist Robe (Provided)"] = "мантія імли жаху (видано)" } },
    [9013] = { [1] = "Найкраще — наостанок", [2] = "Це справді дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Твої зусилля звільнили нас від наслідків наших минулих помилок.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись. Ти їх {стать:заслужив:заслужила}.", [3] = "Віддайте Моквару шолом доблесті та нагрудник доблесті.", [4] = "Ти {стать:готовий:готова} віддати частини свого обладунку доблесті в обмін на новий шолом та кірасу героїзму?", [5] = "Я справді сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки. Нехай вони довго служать тобі у твоїх великих діяннях!", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Breastplate of Valor"] = "нагрудник доблесті", ["Breastplate of Valor (Provided)"] = "нагрудник доблесті (видано)", ["Helm of Valor"] = "шолом доблесті", ["Helm of Valor (Provided)"] = "шолом доблесті (видано)" } },
    [9014] = { [1] = "Найкраще — наостанок", [2] = "Це справді дивовижно, {ім'я}! Прийми мою подяку — і не тільки мою, а й усіх, кому ти {стать:допоміг:допомогла}. Твої зусилля звільнили нас від наслідків наших минулих помилок.\n\nА щодо винагороди... в мене є кілька речей, які мають тобі сподобатись. Ти їх {стать:заслужив:заслужила}.", [3] = "Віддайте Моквару корону магістра та мантію магістра.", [4] = "Як ми й домовлялись, ти {стать:готовий:готова} віддати частини свого обладунку магістра в обмін на нову корону та мантію чаклуна?", [5] = "Я справді сумуватиму за тобою, {ім'я}, і, певно, ніколи не зможу гідно віддячити за твої зусилля.\n\nСподіваюсь, тобі сподобаються нові обладунки. Нехай вони довго служать тобі у твоїх великих діяннях!", ["en"] = "Saving the Best for Last", ["tasks"] = { ["Magister's Crown"] = "корона магістра", ["Magister's Crown (Provided)"] = "корона магістра (видано)", ["Magister's Robes"] = "мантія магістра", ["Magister's Robes (Provided)"] = "мантія магістра (видано)" } },
    [9016] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Моквара та скажи йому, що Бодлі — його єдиний шанс знайти інші частини. Поговори з ним і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Моквара в Орґріммар з чоботами дикого серця, кілтом дикого серця та наплічниками дикого серця.", [4] = "Ти {стать:повернувся:повернулась}, і я бачу по твоїх очах, що ти хочеш мені багато чого розповісти, {ім'я}. Та спершу подбаймо про твою винагороду.", [5] = "На нас наклали це прокляття за один лише медальйон. Лорд Вальталак, безумовно, вміє затаїти образу.\n\nМи постараємося знайти решту частин — сподіваюся, до того, як я загину. Але спершу давай обговоримо твою винагороду.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Wildheart Boots"] = "чоботи дикого серця", ["Wildheart Boots (Provided)"] = "чоботи дикого серця (видано)", ["Wildheart Kilt"] = "кілт дикого серця", ["Wildheart Kilt (Provided)"] = "кілт дикого серця (видано)", ["Wildheart Spaulders"] = "наплічники дикого серця", ["Wildheart Spaulders (Provided)"] = "наплічники дикого серця (видано)" } },
    [9017] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Моквара та скажи йому, що Бодлі — його єдиний шанс знайти інші частини. Поговори з ним і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Моквара в Орґріммар з чоботами ловця звірів, штанами ловця звірів та напліччям ловця звірів.", [4] = "Ти {стать:повернувся:повернулась}, і я бачу по твоїх очах, що ти хочеш мені багато чого розповісти, {ім'я}. Та спершу подбаймо про твою винагороду.", [5] = "На нас наклали це прокляття за один лише медальйон. Лорд Вальталак, безумовно, вміє затаїти образу.\n\nМи постараємося знайти решту частин — сподіваюся, до того, як я загину. Але спершу давай обговоримо твою винагороду.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Beaststalker's Boots"] = "чоботи ловця звірів", ["Beaststalker's Boots (Provided)"] = "чоботи ловця звірів (видано)", ["Beaststalker's Mantle"] = "напліччя ловця звірів", ["Beaststalker's Mantle (Provided)"] = "напліччя ловця звірів (видано)", ["Beaststalker's Pants"] = "штани ловця звірів", ["Beaststalker's Pants (Provided)"] = "штани ловця звірів (видано)" } },
    [9018] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Моквара та скажи йому, що Бодлі — його єдиний шанс знайти інші частини. Поговори з ним і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Моквара в Орґріммар з чоботами магістра, поножами магістра та напліччям магістра.", [4] = "Ти {стать:повернувся:повернулась}, і я бачу по твоїх очах, що ти хочеш мені багато чого розповісти, {ім'я}. Та спершу подбаймо про твою винагороду.", [5] = "На нас наклали це прокляття за один лише медальйон. Лорд Вальталак, безумовно, вміє затаїти образу.\n\nМи постараємося знайти решту частин — сподіваюся, до того, як я загину. Але спершу давай обговоримо твою винагороду.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Magister's Boots"] = "чоботи магістра", ["Magister's Boots (Provided)"] = "чоботи магістра (видано)", ["Magister's Leggings"] = "поножі магістра", ["Magister's Leggings (Provided)"] = "поножі магістра (видано)", ["Magister's Mantle"] = "напліччя магістра", ["Magister's Mantle (Provided)"] = "напліччя магістра (видано)" } },
    [9020] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Моквара та скажи йому, що Бодлі — його єдиний шанс знайти інші частини. Поговори з ним і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Моквара в Орґріммар з чоботами тіньового ремесла, штанами тіньового ремесла та наплічниками тіньового ремесла.", [4] = "Ти {стать:повернувся:повернулась}, і я бачу по твоїх очах, що ти хочеш мені багато чого розповісти, {ім'я}. Та спершу подбаймо про твою винагороду.", [5] = "На нас наклали це прокляття за один лише медальйон. Лорд Вальталак, безумовно, вміє затаїти образу.\n\nМи постараємося знайти решту частин — сподіваюся, до того, як я загину. Але спершу давай обговоримо твою винагороду.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Shadowcraft Boots"] = "чоботи тіньового ремесла", ["Shadowcraft Boots (Provided)"] = "чоботи тіньового ремесла (видано)", ["Shadowcraft Pants"] = "штани тіньового ремесла", ["Shadowcraft Pants (Provided)"] = "штани тіньового ремесла (видано)", ["Shadowcraft Spaulders"] = "наплічники тіньового ремесла", ["Shadowcraft Spaulders (Provided)"] = "наплічники тіньового ремесла (видано)" } },
    [9021] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Моквара та скажи йому, що Бодлі — його єдиний шанс знайти інші частини. Поговори з ним і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Моквара в Орґріммар із сандалями імли жаху, поножами імли жаху та напліччям імли жаху.", [4] = "Ти {стать:повернувся:повернулась}, і я бачу по твоїх очах, що ти хочеш мені багато чого розповісти, {ім'я}. Та спершу подбаймо про твою винагороду.", [5] = "На нас наклали це прокляття за один лише медальйон. Лорд Вальталак, безумовно, вміє затаїти образу.\n\nМи постараємося знайти решту частин — сподіваюся, до того, як я загину. Але спершу давай обговоримо твою винагороду.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Dreadmist Leggings"] = "поножі імли жаху", ["Dreadmist Leggings (Provided)"] = "поножі імли жаху (видано)", ["Dreadmist Mantle"] = "напліччя імли жаху", ["Dreadmist Mantle (Provided)"] = "напліччя імли жаху (видано)", ["Dreadmist Sandals"] = "сандалі імли жаху", ["Dreadmist Sandals (Provided)"] = "сандалі імли жаху (видано)" } },
    [9022] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Моквара та скажи йому, що Бодлі — його єдиний шанс знайти інші частини. Поговори з ним і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Моквара в Орґріммар з чоботами доблесті, поножами доблесті та наплічниками доблесті.", [4] = "Ти {стать:повернувся:повернулась}, і я бачу по твоїх очах, що ти хочеш мені багато чого розповісти, {ім'я}. Та спершу подбаймо про твою винагороду.", [5] = "На нас наклали це прокляття за один лише медальйон. Лорд Вальталак, безумовно, вміє затаїти образу.\n\nМи постараємося знайти решту частин — сподіваюся, до того, як я загину. Але спершу давай обговоримо твою винагороду.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Boots of Valor"] = "чоботи доблесті", ["Boots of Valor (Provided)"] = "чоботи доблесті (видано)", ["Legplates of Valor"] = "поножі доблесті", ["Legplates of Valor (Provided)"] = "поножі доблесті (видано)", ["Spaulders of Valor"] = "наплічники доблесті", ["Spaulders of Valor (Provided)"] = "наплічники доблесті (видано)" } },
    [903] = { [1] = "Скрадачі Степів", [2] = "Настав час полювання на щось дійсно кусюче. Скрадачі Степів — не із сумирної породи. Жорсткі, винахідливі, хитрі... та смертоносні. Ти знайдеш їх серед високої трави на південному заході від Перехрестя.\n\nБудь насторожі під час полювання, {ім'я}, бо не встигнеш отямитися, як перетворишся з ловця на здобич.", [3] = "Назбирайте 7 пазурів скрадачів савани для Серґри Чорношип на Перехресті.", [4] = "Як там твоє полювання, {ім'я}? {стать:Знайшов:Знайшла} скрадачів?", [5] = "О-о, я бачу, ти часу дарма не {стать:гаяв:гаяла}, ховаючись у траві та полюючи на скрадачів. Як думаєш, чи стане тобі сил зустрітися з найсильнішим з них?", ["en"] = "Prowlers of the Barrens", ["tasks"] = { ["Prowler Claws"] = "пазурі скрадача", ["Prowler Claws (Provided)"] = "пазурі скрадача (видано)" } },
    [9032] = { [1] = "Нещасна доля Бодлі", [2] = "Амулет містив душу Вальталака? Не дивно, що він був захищений таким потужним прокляттям.\n\nЗнайти Бодлі буде непросто. Я чув, що він готувався повернутися до Чорноскельного шпиля. Але відтоді про нього ніхто не чув.\n\nШукай його на Чорноскельній горі, хоча, боюся, що він, напевно, вже мертвий. Раджу тобі взяти з собою пристрій гобліна.", [3] = "Відправляйтесь до Чорноскельної гори та скористайтесь міжвимірним шукачем привидів, щоб знайти Бодлі в Чорноскельному шпилі.", [5] = "Ти навіть не уявляєш, як я радий, що ти можеш мене бачити. Нарешті мені є з ким поговорити!\n\nТи допоможеш нам, {ім'я}? Ми не знали, що творили, і вчинили велике зло, а тепер маємо все виправити. Якщо в тебе дійсно вже є верхня частина амулета лорда Вальталака, я можу підказати, де ти зможеш знайти інші частини, щоб об'єднати їх та покласти всьому цьому край.\n\nТак, до речі, мене звуть Бодлі. Приємно познайомитись!", ["en"] = "Bodley's Unfortunate Fate" },
    [905] = { [1] = "Злющі серпопазурі", [2] = "Тепер, {Ім'я}, полювання стає складнішим. Тепер ти мусиш здолати свою здобич, а потім знайти шлях до її лігва.\n\nПолюй на сонцелуских рапторів на півдні. Убивай їх і не забувай збирати пір'я, які вони носять. Поклади пір'я в гніздах серпопазурів на південний захід від Застійного оазису. Покажи рапторам, що ти їх не боїшся!", [3] = "Убивайте сонцелуских рапторів і збирайте їхнє пір'я. Використайте пір'я в 3 гніздах серпопазурів. Повертайтеся до Серґри Темношип на Перехрестя.", [4] = "Ти вже {стать:був у:була в} гніздах, {Ім'я}?", [5] = "Отже, ти {стать:побував:побувала} біля гнізд і {стать:поклав:поклала} пера своїх жертв у них. Безумовно, це потребувало немало хоробрості.\n\nЧи почуваєшся ти тепер трохи {стать:дужчим:дужчою}, {Ім'я}? Бо тепер ти виглядаєш більш {стать:дужим:дужою}, ніж коли ти вперше сюди {стать:прибув:прибула}. Схоже, Степи роблять своє.", ["en"] = "The Angry Scytheclaws", ["tasks"] = { ["Visit Blue Raptor Nest"] = "Відвідайте гніздо блакитного хижака", ["Visit Blue Raptor Nest (Provided)"] = "Відвідайте гніздо блакитного хижака (видано)", ["Visit Blue Raptor Nest slain"] = "Відвідайте гніздо блакитного хижака: убито", ["Visit Red Raptor Nest"] = "Відвідайте гніздо червоного хижака", ["Visit Red Raptor Nest (Provided)"] = "Відвідайте гніздо червоного хижака (видано)", ["Visit Red Raptor Nest slain"] = "Відвідайте гніздо червоного хижака: убито", ["Visit Yellow Raptor Nest"] = "Відвідайте гніздо жовтого хижака", ["Visit Yellow Raptor Nest (Provided)"] = "Відвідайте гніздо жовтого хижака (видано)", ["Visit Yellow Raptor Nest slain"] = "Відвідайте гніздо жовтого хижака: убито" } },
    [90560] = { [1] = "Знайома бруднота", [2] = "<Ви знайшли на лабораторному столі флакон із смердючою, в'язкою рідиною. Він був оточений різними інгредієнтами, які були ретельно відміряні та нарізані на ретельні порції. Хоча трави неможливо ідентифікувати, поруч лежить одне неушкоджене та знебарвлене серце звіра.\n\nСумішаність знайома, нагадує нещодавні експерименти, проведені Королівським аптекарським товариством. Якщо ваша цікавість переважає огиду, можливо, хтось із їхніх членів зацікавиться вашим відкриттям.>", [3] = "Зберіть Знебарвлені Серця Звірів у істот у Чумних Країнах, а потім принесіть їх разом із Неправильно використаним Цілющим Зіллям зацікавленому члену Королівського Аптекарського Товариства в Підмісті.", [4] = "Хм? У тебе щось є для мене?", [5] = "Ах, гм, яка ж то ввічлива пропозиція, мабуть. Якби я мав трохи часу та кілька додаткових реагентів, я б, мабуть, зміг розгадати будь-яку таємницю, яку ти хочеш розгадати, за допомогою цього зілля, але зараз у мене є набагато терміновіші справи. Хворі серця істот — це, мабуть, сильніша сторона аптекаря Ренферрела.\n\nНа щастя для тебе, я вже давно збирався виконати доручення для Ренферрела. Ти готовий убити двох людей однією чумою? ...Метафорично кажучи, звичайно.", ["en"] = "Familiar Foulness" },
    [90566] = { [1] = "О, мої кровоточачі серця!", [2] = "Гадаю, ви добре звикли до Чумних земель, враховуючи вражаючу пляму, присутню на ваших зразках. Цілком логічно, що ви розумієте, наскільки незручно будь-якому самотньому члену Королівського аптекарського товариства перетинати Бастіон за припасами.\n\nРенферрел стверджує, що цікавиться кровоточачими серцями, квіткою, на додаток до колись б'ючихся сердець. Я не впевнений, чи це для алхімічних досліджень, чи для їхньої візуальної привабливості, але я знаю, що він був би вдячний за доставку різних сердець.", [3] = "Доставте кошик із знебарвленими серцями звірів та кілька кровоточивих сердець з Чумних земель аптекарю Ренферрелу в Гробниці Сріблястого лісу.", [4] = "Чи очікую я доставку?\n\n<Аптекар Ренферрел перевіряє свої нотатки.>\n\nВи не схожі на того піддослідного, якого я просив...", [5] = "Ох. Мої криваві серця. Після місяців очікування на Фаранелл, він нарешті прибуває, хоча я давно вже покинув ці дослідження. Чудово.\n\nОднак, мене заінтригувало те, що знаходиться у вашому кошику. Мені нагадують серця місцевих воргів, тільки вони, здається, набагато стійкіші до гниття та псування.\n\nЦей рецепт натхненний давнішою сумішшю, яку я розробив раніше. Спробуйте і повідомте мені, як воно піде.", ["en"] = "Oh, My Bleeding Hearts!", ["tasks"] = { ["Basket of Hearts"] = "Кошик із сердечками" } },
    [906] = { [1] = "Зрада зсередини", [2] = "Віднеси голову Лока Торку на Перехрестя, {раса:к}. <фиркає> Нехай дізнається, що сталося з моїм племенем — ха, навряд чи він повірить, що Кривозуб приклав до цього руку. Але я впевнений, що він нагородить тебе за здійснення такого великого подвигу. <фиркає>\n\nЙ допоки я сидітиму в цій клітці, не перестану благословляти тебе силою Аґамаґґана, {раса:к}. А тепер — прощавай!", [3] = "Принесіть череп Лока Торку на Перехрестя, що в Степах.", [4] = "Ну, що ще?", [5] = "Ти {стать:знайшов:знайшла} ватажка Бритвогривих і {стать:прикінчив:прикінчила} його власноруч, {ім'я}? Неперевершено!\n\nЯ не можу дібрати слів, але це не означає, що я невдячний. Жителям Перехрестя варто поважати твою силу.\n\nМаю визнати, я вважав лідером набігів на лінії постачання нашої провізії геть іншого свинобраза. Дякую тобі ще раз, {Ім'я}.", ["en"] = "Betrayal from Within", ["tasks"] = { ["Lok's Skull"] = "череп Лока", ["Lok's Skull (Provided)"] = "череп Лока (видано)" } },
    [907] = { [1] = "Озвірілі громоящери", [2] = "Тепер, {Ім'я}, ти {стать:повинен:повинна} зіткнутися з величними громоящерами. Ці звіри настільки великі, що земля дрижить, коли вони тупотять по рівнинах. Бережися, б'ючися з ними, бо один неправильний крок - і ти, ймовірно, опинишся в них під ногами.\n\nЗнайти громоящерів можна у південних Степах. Вони відомі як буреморди, бурешкури та громоголови. Повертайся до мене, як подолаєш їх.", [3] = "Принесіть 3 зразки крові громоящера Джорнові Небесному Провидцю у табір Таурахо.", [4] = "Ти вдалось здолати громоящерів, {Ім'я}?", [5] = "Любо бачити, що ти повертаєшся з доказом перемоги. І добре знати, що тобі вдалось це зробити і залишитись з цілими кістками.", ["en"] = "Enraged Thunder Lizards", ["tasks"] = { ["Thunder Lizard Blood"] = "кров громоящера", ["Thunder Lizard Blood (Provided)"] = "кров громоящера (видано)" } },
    [909] = { [1] = "Барон Акваніс", [2] = "Переможений водяний елементаль залишив після себе дивну водяну кулю. Ви припускаєте, що ця річ якимось чином живила потвору енергією. Всередині кулі хлюпоче гнила на вигляд вода. Сама куля здається непроникною для будь-якої фізичної сили.\n\nЯкщо хтось і може розібратися в ній, це Дже'неу Санкрі зі Служителів Землі. Він знаходиться на ординській заставі Зорам'ґар в Ясенедолі.", [3] = "Принесіть дивну водяну кулю Дже'неу Санкрі на форпост Зорам'ґар, що в Ясенедолі.", [4] = "О, ще раз вітаю, {ім'я}. Я тут зчитував морські хвилі, як завжди. Що привело тебе на заставу?", [5] = "Оце так знахідка, {ім'я}.\n\nКажеш, {стать:добув:добула} її у барона Акваніса в Чорноводних глибинах? Барон Акваніс здавна вважався спотвореним елементалем. Ця куля розкаже, що саме його зіпсувало. Я не здивуюся, якщо це Сутінковий Молот, але наші дослідження також покажуть, як саме вони зуміли це зробити.\n\nДобре, що ти мені це {стать:приніс:принесла}. Будь ласка, прийми це разом з найтеплішими побажаннями від Служителів Землі.", ["en"] = "Baron Aquanis", ["tasks"] = { ["Strange Water Globe"] = "дивна водяна куля", ["Strange Water Globe (Provided)"] = "дивна водяна куля (видано)" } },
    [90902] = { [1] = "Відкриття світла заново", [2] = "Я пишаюся тим, що вітаю ще одного новоспеченого паладина в наших лавах. Коли ви почнете відновлювати зв'язок зі світлом, ви можете помітити, що певні здібності, які колись були для вас другою натурою, можуть завдавати вам значного болю, особливо ті, що пов'язані з використанням світла для зцілення себе чи інших.\n\nЄдиний спосіб вирішити цю проблему – це, на жаль, пройти через це. Як і будь-який інший м'яз, який атрофувався, ви повинні проштовхнути біль і тренувати плоть, щоб вона повернула повну функцію.", [3] = "Вилікуйте 5 поранених Гвардійців Смерті своєю здатністю «Священне світло».", ["en"] = "Rediscovering the Light", ["tasks"] = { ["Injured Deathguard healed"] = "Поранений Смертельний Гвардієць зцілений" } },
    [91208] = { [1] = "Домовленості", [2] = "Не всі наші товариші-паладини, які повертаються, швидко звикають до нової реальності. Деяким важко змиритися з тим, що вони тепер, певним чином, є тим самим, проти чого боролися все своє життя.\n\nЦим людям часто потрібен лише добрий жест і співчутливе вухо. На жаль, багато інших швидко вдаються до насильства. Знайдіть переляканого паладина, який утік у пагорби прямо на захід від цієї каплиці. Простягніть руку дружби. Проведіть їх назад до світла, якщо зможете.", [3] = "Знайдіть Переляканого Паладина у Смертельному Дзвоні.", ["en"] = "Coming to Terms", ["tasks"] = { ["Offer aid to the Frightened Paladin"] = "Запропонуйте допомогу переляканому паладину" } },
    [91209] = { [1] = "Продовжуйте своє навчання", [2] = "Лордерон, можливо, вже не такий, як колись, але наш дім все ще потребує захисту від усіляких загроз, і тобі час вийти та зустрітися зі світом. Твоєю наступною зупинкою має бути місто Брілл у центрі Тірісфальських галявин. Зустрінься там із Шарі Стілвелл. Вона зможе подбати про твоє подальше навчання.\n\nОстання порада перед твоїм від'їздом — будь особливо обережним як паладин, який подорожує Занедбаними землями. Багато хто на службі у Темної Леді не довіряє нам та нашій близькості до світла.", [3] = "Йдіть дорогою на схід від Дедкнелла, щоб знайти місто Брілл. Зверніться до Шарі Стілвелл, щоб продовжити навчання.", ["en"] = "Continue Your Training", ["tasks"] = { ["Report to Shari Stilwell in Brill"] = "Звітувати Шарі Стілвелл у Бріллі" } },
    [91282] = { [1] = "Другий дім", [2] = "Приємно бачити, як мої новопочаті брати та сестри процвітають так само, як і ви. Однак лише завдяки спільноті та спільній вірі ми можемо по-справжньому реалізувати свій повний потенціал, і з цією метою ми почали формувати новий орден паладинів прямо тут, у Тірісфалі.\n\nЯкщо ви хочете дізнатися більше, вам варто відвідати наш монастир на Північній Скелі. Він називається Замок Бандаріон. Він розташований на урвищах трохи північно-західно від ферми Солліден, і його важко пропустити.", [3] = "Знайдіть фортецю Бандаріон-Кріп і доповідайте там Бретону Семюелсу.", ["en"] = "A Second Home" },
    [91285] = { [1] = "Мурлоки біля воріт", [2] = "Зазвичай ми б виявили трохи більше гостинності до наших новачків, але зараз у нас невелика проблема з мурлоками.\n\nПлем'я мурлоків використовувало фортецю як місце для нересту. Вони були проблемою з тих пір, як ми переїхали та вигнали їх, але тепер ситуація починає виходити з-під контролю. Здається, ти вже бачив якісь дії. Чи не міг би ти допомогти нам відігнати деяких із цих шкідників? Ти знайдеш їх, що ховаються на скелях вздовж дороги на схід, та в таборах навколо озера на захід.", [3] = "Убийте 8 Мерзенних Атакуючих Плавників та 8 Мерзенних Провидців Плавників і повідомте Бретону Семюелсу, коли це буде зроблено.", ["en"] = "Murlocs at the Gates", ["tasks"] = { ["Vile Fin Attacker slain"] = "Злочинний нападник на плавниках: убито", ["Vile Fin Seer slain"] = "Мерзенний провидець плавців: убито" } },
    [91294] = { [1] = "Огляд території", [2] = "Тепер, коли безпосередня загроза нападів мурлоків під контролем, я б закликав вас показати нашу фортецю. Вона ще не дуже велика, але це ваш дім.\n\nКоли ви закінчите дослідження, зверніться до Даніти Морр, нашої лідерки. Вона допоможе вам облаштуватися.\n\nЯ дуже рада, що зустріла вас, {ім'я}. Нехай світло буде вашим провідником.", [3] = "Поговоріть з мешканцями фортеці Бандаріон.", ["en"] = "Touring the Grounds", ["tasks"] = { ["Speak with Ander Solliden"] = "Поговоріть з Андером Солліденом", ["Speak with Danitha Morr"] = "Поговоріть з Данітою Морр", ["Speak with Hilda the Breaker"] = "Поговоріть з Гільдою Руйнівницею", ["Speak with Jorin Croge"] = "Поговоріть з Йоріном Кроге" } },
    [913] = { [1] = "Скрик громояструба", [2] = "Громояструб, {ім'я}, це лютий звір. Прийшов час тобі зустрітися з ним. Твоє завдання - вистежити істоту та принести мені його крила, як доказ успішного полювання.\n\nЧим швидше впораєшся - тим швидше закінчиться твоє навчання.", [3] = "Знайдіть і вбийте громояструба, принесіть його крила Джорну Небесному Провидцю в табір Таурахо.", [4] = "Завдання виконано? Тобі вдалось здолати громояструба?", [5] = "Ти, як той громояструб, маєш пишатися собою. Зі сміливістю, честю та силою ти {стать:подолав:подолала} кожну ціль поставлену перед тобою.\n\nАле твій шлях, {ім'я}, продовжується. Скоро ти зрозумієш, що справжні мисливці постійно борються, і довіку йдуть своїм шляхом з високо піднятою головою. Точнісінько як ти!\n\nНастав час рухатися далі.", ["en"] = "Cry of the Thunderhawk", ["tasks"] = { ["Thunderhawk Wings"] = "крила громояструба", ["Thunderhawk Wings (Provided)"] = "крила громояструба (видано)" } },
    [91316] = { [1] = "Виконання ремонтних робіт", [2] = "Так далеко від Підміста логістика є складною, і в нас гостра нестача будівельних матеріалів, необхідних для відновлення цієї фортеці. Я б хотів вашої допомоги в цьому.\n\nЗруйноване село Тіньова Вейл можна знайти в Шепітливому Лісі, трохи південно-західно звідси. В одній з будівель є старий кореневий льох, який використовувався для зберігання всіляких речей. Там, ймовірно, є корисні матеріали. Зберіть, що зможете, і поверніться до нас.", [3] = "Зберіть 12 шматків міцної деревини в Тінісфальській галявині.", ["en"] = "Making Repairs", ["tasks"] = { ["Sturdy Lumber"] = "Міцна деревина" } },
    [91317] = { [1] = "Заплямований", [2] = "Не всі повсталі паладини добре звикли до нашого нового існування, як ви, можливо, вже самі бачили. Деякі перенесли свої упередження з життя і продовжують чинити насильство над своїми побратимами-відреклими.\n\nНаразі нам не довіряють наші люди, які добре пам'ятають переслідування, що їх чинили живі в ім'я світла, і ці напади не допомагають. Кілька з цих заплямованих оселилися в Тіньовій Долині на південному заході. Покінчіть з ними і принесіть мені голову їхнього лідера.", [3] = "Убийте 8 заплямованих трудяг, 6 заплямованих фанатиків та зберіть голову командира Рудольфа Гельхардта в Тірісфальських галявинах.", ["en"] = "The Tarnished", ["tasks"] = { ["Rudolph Gelhardt's Head"] = "Голова Рудольфа Гельхардта", ["Tarnished Drudge slain"] = "Заплямований трудяга: убито", ["Tarnished Zealot slain"] = "Заплямований фанатик: убито" } },
    [914] = { [1] = "Лідери Ікла", [2] = "Друїди Плачучих печер, друїди Ікла, вражені порчею. Колись вони були частиною ордена благородних друїдів, що поклявся зцілити Степи, але тепер вони прагнуть зробити цю землю подібною своїм власним, спотвореним видінням.\n\nДруїди Ікла мають чотирьох лідерів, кожен із яких володіє самоцвітом сновидінь. Навіть тепер вони переслідують мене в кошмарах! Здолай лідерів і принеси мені їх самоцвіти. І тоді Степи знову зможуть зазнати мир.\n\nВперед, {ім'я}. Ти знайдеш їх укриття глибоко в Плачучих печерах.", [3] = "Принесіть Нарі Дикій Гриві в Громовий Бескид самоцвіти Кобрана, Анакондри, Пітонаса й Серпентіса.", [4] = "Спогади про мої кошмари переслідують мене, {ім'я}. Чи вдалося тобі перемогти лідерів ікла і здобути їх самоцвіти?", [5] = "Ти {стать:впорався:впоралась}, {ім'я}! Ти {стать:вбив:вбила} лідерів Ікла. Тепер мої сни вільні від їх жахливих облич, а ти {стать:допоміг:допомогла} врятувати Степи.\n\nДякую тобі, {ім'я}. І дякую тобі від імені друїдів Громового Бескиду, і від імені цих земель.", ["en"] = "Leaders of the Fang", ["tasks"] = { ["Gem of Anacondra"] = "самоцвіт Анакондри", ["Gem of Anacondra (Provided)"] = "самоцвіт Анакондри (видано)", ["Gem of Cobrahn"] = "самоцвіт Кобрана", ["Gem of Cobrahn (Provided)"] = "самоцвіт Кобрана (видано)", ["Gem of Pythas"] = "самоцвіт Пітонаса", ["Gem of Pythas (Provided)"] = "самоцвіт Пітонаса (видано)", ["Gem of Serpentis"] = "самоцвіт Серпентіса", ["Gem of Serpentis (Provided)"] = "самоцвіт Серпентіса (видано)" } },
    [91858] = { [1] = "Дипломатичний інцидент", [2] = "Вкрай невдалий поворот подій у Срібній Пайні надав нам унікальну можливість довести свою цінність в очах орди.\n\nДвоє високопосадовців із Земляного Кільця зникли безвісти у Срібній Пайні дорогою до Таррен-Мілл. Ми мало що знаємо, але ходять чутки, що це перетворюється на досить дипломатичний інцидент. Якщо ми зможемо знайти цих зниклих безвісти осіб, це може допомогти нам отримати легітимність, яка нам так потрібна.\n\nУ нас є людина в Гробниці, Треван Рол. Поїдьте туди та поговоріть з ним.", [3] = "Вирушайте до Гробниці у Сріблястому лісі та поговоріть з Треваном Ролом про зниклих мандрівників Земляного Кільця.", ["en"] = "Diplomatic Incident" },
    [91859] = { [1] = "Цікава пара", [2] = "Переходячи одразу до суті, ці «сановники» — не звичайні дипломати. Один був тауреном. Досить звичайним для Земного Кільця, але інший — і ви навряд чи повірите в це — був ельфом. *Вищим* ельфом. Вони були в плащах, але я вже бачив кель'дорей раніше, і б'юся об заклад, що саме це я бачив.\n\nЧому ельф супроводжував таурена через територію Орди? Що ж, ваша здогадка така ж вірна, як і моя. Це все, що я знаю, тому я б порадив поговорити з Вартовим Смерті Балдреном біля входу в місто.", [3] = "Поговоріть зі Смертевартом Балдреном про таємничих мандрівників із Земляного Кільця, які нещодавно пройшли через Гробницю.", ["en"] = "A Curious Pair" },
    [91860] = { [1] = "Похмура доля", [2] = "Вчора ввечері, патрулюючи, я помітив групу гнолів, які скидали дуже велике тіло на багаття на березі острова Фенріс. Я не бачив ні ельфа, ні якихось менших трупів, але, гадаю, це не віщує їм нічого доброго.\n\nЯкщо ви сміливі чи дурні, ласкаво просимо на острів Фенріс, щоб дізнатися більше, але, як на мене, знайти якогось зарозумілого ельфа, який, ймовірно, давно помер, буде важко.\n\nЯ знаю, що ви, паладини, любите клястися та братися за безнадійні справи, але ця того не варта. Повірте мені.", [3] = "Дослідіть острів Фенріс на сході та дізнайтеся про долю мандрівної групи Земляного Кільця.", ["en"] = "A Grim Fate" },
    [91861] = { [1] = "У фортецю Фенріс", [2] = "<Те, що ви знайшли лише одне тіло, — обнадійливий знак. Можливо, Високий ельф, якого описали Треван і Хадрек, все ще живий десь глибоко всередині сусідньої фортеці?>", [3] = "Дослідіть Фенріс. Тримайтеся півночі та спробуйте знайти зниклого члена групи Земляного Кільця.", ["en"] = "Into Fenris Keep" },
    [91862] = { [1] = "Люміна Віндсінгер", [2] = "Квел'дорей? Ні, я не \"квел'дорей\". Я Люміна Вітроспівачка, і я шен'дорей. Одна з Небеснорожденних Творців Вітру.\n\nЯ прибула на ці землі як гість Земляного Кільця. Ми з моїм супутником Баноном проходили через Срібну Сосну, щоб дістатися до Араті-Нагір'я, щоб вивчити там стихійні збіги. Зрозуміло, що ми туди не дісталися.\n\nАле зараз у нас немає на це часу. Убийте гнолів поблизу. Заберіть ключ від цієї клітки та звільніть мене. Я розповім вам решту, як тільки ми будемо безпечно геть.", [3] = "Отримайте ключ від острова Фенріс у гноллів з Гнилої Шкури та використовуйте його, щоб звільнити Люміну Вітроспіву.", ["en"] = "Lumina Windsinger", ["tasks"] = { ["Fenris Isle Key"] = "Ключ до острова Фенріс" } },
    [924] = { [1] = "Демонове Сім'я", [2] = "Демонове Сім'я — могутній інструмент Палаючого Легіону. Воно перебуває у печері на вершині Зловісного Туману, над демонічним жертовником вогню.\n\nЯ підготував силові камені, які при розміщенні біля Сім'я зруйнують його зв'язок з Легіоном.\n\nВізьми камінь зі столу і принеси його до жертовника на вершині Зловісного Туману. Йди на захід, потім на північ до роздоріжжя. Вершина буде зліва. Найбезпечніший підйом — з північної частини гори.\n\nІ поспіши, сила каменя з часом поглине його.", [3] = "Візьміть тріснутий камінь сили. Віднесіть його до жертовника вогню перш ніж камінь зникне, після чого поверніться до Ак'Зелота.", [4] = "Демонове Сім'я все ще існує. Я відчуваю його силу…", [5] = "Твоє завдання виконане. Ти {стать:знищив:знищила} Демонове Сім'я, як того й вимагав Нііру. Але це ще не кінець…\n\nЗнищення Демонового Сім'я спричинило імпульс енергії надзвичайної сили. Я відчуваю її, і упевнений, що інші також. Інші, хто допоки не може зрозуміти, чому їх іграшка не працює...\n\nАле лишимо це питання на майбутнє, у мене для тебе є дещо. Нііру надіслав мені це для оплати твоєї роботи і попросив подякувати за допомогу.\n\nТож, дякую.", ["en"] = "The Demon Seed", ["tasks"] = { ["Destroy the Demon Seed"] = "Знищити Насіння Демона", ["Destroy the Demon Seed (Provided)"] = "Знищити Насіння Демона (видано)", ["Destroy the Demon Seed slain"] = "Знищити Насіння Демона: убито" } },
    [92401] = { [1] = "Перелякане прохання", [2] = "Це мій чоловік Едвард...\n\nВін не повернувся зі своєї щотижневої подорожі до кладовища в руїнах Лордерона. Наш син загинув, коли Артас зруйнував місто, і мій дорогий Едвард досі сповнений почуття провини та горя, що ми так і не знайшли його тіла. Я намагалася застерегти його від пошуку в тих захоплених руїнах, але він відмовляється здаватися. Я намагаюся не хвилюватися, але минули дні.\n\nЄ речі, з якими я не можу впоратися, але якщо ви згодні, мені потрібно знати долю мого чоловіка.", [3] = "Розслідуйте зникнення Едварда Хартвівера в руїнах Лордерона.", ["en"] = "A Frightened Request", ["tasks"] = { ["Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron."] = "Розслідуйте зникнення Едварда Хартвівера в руїнах Лордерона." } },
    [92421] = { [1] = "Справедливість світла", [2] = "Як паладин Відреклих, мій обов'язок — виконувати волю нашої Темної Леді, піклуючись про потреби нашого народу. Нам пощастило мати можливість досягти і того, і іншого.\n\nНад Підмістем бич все ще безконтрольно бродить у великій кількості. Наші сили скорочуються, намагаючись повернути нашу землю, а гниючу плоть неможливо відновити. Не без заміни.\n\nЯкби ж наш славний капітан Гарек Бандаріон все ще був з нами, я знаю, чого б він бажав. Завершити те, що він почав, і зцілити наших родичів. Заради Лордерона!", [3] = "Зберіть 25 неушкоджених кінцівок у руїнах Лордерона для Морбіна Лайтбейна в Підмісті.", ["en"] = "Light's Justice", ["tasks"] = { ["Intact Limbs"] = "Неушкоджені кінцівки", ["Intact Limbs (Provided)"] = "Неушкоджені кінцівки (видано)", ["Intact Limbs slain"] = "Неушкоджені кінцівки: убито" } },
    [92467] = { [1] = "Поклик землі", [2] = "Сапта — це напій, створений для зв'язування наших духів зі стихіями. Змішане з магією, зілля дозволить людям з сильною волею бачити стихії так, як ніхто інший. Ваш дух буде пов'язаний зі стихією, для якої була створена сапта, і лише кілька обраних шаманів знають рецепт.\n\nСапту завжди п'ють у священному місці і ніколи більше ніде — пам'ятайте про це.\n\nЗнайдіть Піднесення Духів на перевалі на північний схід звідси. Випийте там свою сапту, і... ну, ви побачите те, що вам потрібно побачити.", [3] = "Знайдіть Піднесення Духів та випийте Земну Сапту.\n\nНаданий предмет:", ["en"] = "Call of Earth", ["tasks"] = { ["Earth Sapta"] = "сапта землі" } },
    [92468] = { [1] = "Поклик землі", [2] = "Візьми від мене цей необроблений кварц і принеси його тому, кого ти називаєш Вітроутворювачем Боро, як доказ нашої зустрічі. Він створить для тебе тотем, а цей уламок буде його серцем. Яким би малим він не здавався, ти зрозумієш, що розмір не має значення, і що навіть найменші речі можуть пережити багато інших.\n\nБудь терплячим, {ім'я}. Залишайся сильним. І шукай мудрості. Цього вимагають від тебе стихії. Зрештою, ти станеш єдиним цілим із землею – поважай її, як вона поважатиме тебе.", [3] = "Принесіть необроблений кварц до Вітротворця Бороса в Тендал Гай.", ["en"] = "Call of Earth", ["tasks"] = { ["Rough Quartz"] = "грубий кварц", ["Rough Quartz (Provided)"] = "грубий кварц (видано)" } },
    [92514] = { [1] = "Ласкаво просимо до села Шен'дар", [2] = "У тебе є щось на кшталт \"Вітроутворювача\". Щось у тому, що я можу відчути ледь помітну статику на шкірі, коли поруч є хтось, до кого торкнувся дух, і це мене видає. Перш ніж я по-справжньому призначу тобі роботу тут, тобі слід звернутися до нашої старійшини Вітроутворювача, Іллаї Амбервінд. Вона живе недалеко від центру міста.\n\nО, і ще звернися до Коріелли Калбріз, вона керує місцевим заїздом і може надати житло та припаси, якщо вони тобі знадобляться.", [3] = "Поговоріть з Іллайєю Янтарний Вінд та Коріеллою Калмбріз у селі Шен'дар.", ["en"] = "Welcome to Shen'dar Village", ["tasks"] = { ["Speak with Illaya Amberwind"] = "Поговоріть з Іллайєю Амбервінд", ["Speak with the Innkeeper"] = "Поговоріть з господарем готелю" } },
    [92519] = { [1] = "Поповнення запасів лазарету", [2] = "Аптекар Джорелл мав принести нам ящик протиотрут та еліксирів ще кілька днів тому, але ми досі нічого не отримали. Той дурень, мабуть, знову отруївся, варячи зілля в погано провітрюваній халупі, яку називає лабораторією.\n\nЯкщо хочеш і далі допомагати нашому лазарету, для цього доручення ти будеш значно надійнішим вибором.\n\nЙди дорогою до ферми Ґо'шека, на південь і трохи на захід звідси. Скоріш за все, припаси вже запаковані й готові до відправлення, а Джорелл або десь зник, або забув про свої обов'язки.", ["en"] = "Ward Restocking", ["tasks"] = { ["Packaged Tonics"] = "Запаковані тоніки" } },
    [92579] = { [1] = "До Валанаару", [2] = "Наразі, здається, пілон і село в безпеці, тому я хотів би, щоб ви передали цей звіт Валеннійському Буревіснику у Валанаарі, на південно-східному краю острова. Валеннія — лідер миротворців на острові, і їй потрібно знати, що тут сталося.\n\nКульт швидко розширюється, і миротворці досі уникали прямих зіткнень, але ці дні минули. Валанаару потрібно бути готовим до бою.\n\nУ будь-якому разі, дякую. У вас завжди будуть друзі в Шен'дарі, {ім'я}.", [3] = "Доставте письмовий звіт Аонди Валенії Штормфіст у Валанаар.", ["en"] = "To Valanaar", ["tasks"] = { ["Aonda's Written Report"] = "Письмовий звіт Аонди", ["Aonda's Written Report (Provided)"] = "Письмовий звіт Аонди (видано)", ["Aonda's Written Report slain"] = "Письмовий звіт Аонди: убито" } },
    [92595] = { [1] = "«Творці вітру»", [2] = "<Іллая тепло посміхається тобі.>\n\nЯ рада, що ти повернулася, щоб поговорити зі мною, дитино вітрів. Я зрозуміла з першої ж миті, як ти з'явилася переді мною, що ти сильна у небесному видінні. Чи вважаєш ти це дивним? Навіть ті, хто не навчався на шамана, можуть мати цей дар.\n\nХодімо, давайте поговоримо про доручення Творців Вітрів, природу нашої боротьби на Зефрасі та тяжке становище нашого народу.", [3] = "Послухайте, що каже Іллая Амбервінд.", ["en"] = "The Windshapers", ["tasks"] = { ["Listen to Illaya"] = "Слухайте Іллаю" } },
    [92598] = { [1] = "Дар небесного бачення", [2] = "Як Творець Вітру, ви маєте здатність використовувати священне бачення неба, подароване нам духами стихій. Подорожуйте до стоячих каменів на північний схід від села. Знайдіть там місце злиття стихій та скористайтеся своїм даром.\n\nВи побачите, що можете черпати з небесного бачення будь-де, але його благодать набагато потужніша, якщо ви робите це за наявності місця злиття стихій. Часом ви також можете отримувати інші мудрості від духів, яких притягують такі місця сили.", [3] = "Використайте свою расову здатність «Небесний погляд» у З'єднанні стихій у Гаю Тендал.", ["en"] = "The Gift of Skysight", ["tasks"] = { ["Use Skysight near the Elemental Convergence"] = "Використовуйте Skysight поблизу Elemental Convergence" } },
    [92646] = { [1] = "Протистояти Лортуні", [2] = "Лортуна втекла на шпилі, використовуючи якийсь портал. Аєсса та Елаадрін пішли за нею. Це було лише кілька хвилин тому.\n\nБоюся, я отримав забагато ударів, і тут я залишуся. Пройдіть через портал, знайдіть Аєссу та допоможіть їм зупинити Лортуну.\n\nЯкщо допомога, за якою, за словами Елаадрін та Аєсси, вони послали, скоро не прибуде, то ви будете самі звідси. Удачі, {клас}.", [3] = "Пройдіть порталом до Шпилів Рохаші над головою та приєднайтеся до Елаадрін Евенгейл та Айєсси Світанкової у їхній сутичці з Верховною Жрицею Лортуною.", ["en"] = "Confront Lorthuna", ["tasks"] = { ["Confront Lorthuna"] = "Протистояти Лортуні" } },
    [92700] = { [1] = "Великий Небесний Провидець", [2] = "Тепер, коли ви прибули до Валанаару, вам, ймовірно, варто познайомитися з іншими членами Вітротворців. Нинішня Велика Небовидиця та її люди діють з ложі поблизу центру Валанаару.\n\nВи також повинні знати, що Вітротворці та Вищий Орден не дуже добре ладнають у цих краях. Будьте обережні та обходьте Вищий Орден якомога ближче. У нас і так достатньо турбот з культом, я не потерплю насильства між фракціями на вулицях Валанаару.", [3] = "Знайдіть Айессу Доунсінгер у Валанаарі.", ["en"] = "The Grand Skyseer" },
    [92708] = { [1] = "Велика пригода", [2] = "Вітротворці наполегливо працювали, намагаючись відреагувати на поточну кризу на острові Зефрас. Ми зробили кілька несподіваних відкриттів у пошуках зниклих духів вітру та розробляємо план дій, який може допомогти нам отримати засоби для порятунку острова.\n\nОднак, для цього нам знадобляться сильні молоді шукачі пригод, такі як ви. Будь ласка, якщо у вас є хвилинка, дозвольте нам поговорити про це детальніше.", [3] = "Послухайте, що каже Айєсса Донсінгер.", ["en"] = "A Grand Adventure", ["tasks"] = { ["Listen to Ayessa"] = "Слухайте Айєсу." } },
    [92871] = { [1] = "На службі у Зефраса", [2] = "Валеннія Буревісник та її миротворці завжди були захисниками Зефраса, і ми зробили все можливе, щоб надати допомогу, де могли. Ходять чутки про масштабніші культові рухи на острові, і вони явно до чогось готуються.\n\nПовідомте Валеннію та повторіть їй, що Вітротворці пропонують свою повну підтримку зусиллям Валанаара проти Ал'Акет, якщо виникне така потреба.", [3] = "Звернися до Валеннії Буревісник і повідом їй, що Вітротворці з ними у боротьбі проти Ал'Акет.", ["en"] = "In Service of Zephras" },
    [93090] = { [1] = "Що буде далі", [2] = "Будь ласка, передайте мою подяку Айєсі за все, що Творці Вітрів та ваші нові друзі з цього «Земляного Кільця» зробили для острова Зефра. Я знаю про план забрати шаманів Творців Вітрів та покинути острів, і ваш орден має моє благословення та побажання успіхів у цій експедиції.\n\nЯ можу лише сподіватися, що будь-яке рішення, яке знайдуть Творці Вітрів, справді забезпечить нам стабільність, якої нам бракувало в останні роки.\n\nХай вітри з вами, {ім'я}.", [3] = "Поговоріть з Айєсою Світанковою Співачкою, коли будете готові покинути острів Зефраса.", ["en"] = "What Comes Next" },
    [9320] = { [1] = "Величезне зілля мани", [4] = "Окрім інших припасів, у нас також є кілька величезних зіллів мани, які можуть стати тобі в пригоді. Я дам вам одне в обмін на п'ятнадцять некротичних рун.", [5] = "Ось, тримай, {ім'я}. Обережніше там. Нас не так багато, щоб ми могли дозволити собі великі втрати на полі бою.", ["en"] = "Major Mana Potion", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [9330] = { [1] = "Викрадення полум'я Штормовію", [2] = "Це полум'я, викрадене із серця Штормовію, переповнює вас теплом. Ця первісна сила чужа для вас, але оповідник, можливо, знає більше...", [3] = "Принесіть полум'я Штормовію до фестивального оповідника.", [4] = "Ти майже палаєш, {раса:к}. Що це у тебе?", [5] = "Цей яскравий вогонь... ти кажеш, що він зі Штормовію? Неймовірно! Це певно була дуже захоплива пригода! Звичайно, я заплачу тобі за це. Якщо ти знайдеш щось подібне, будь ласка, одразу приходь до мене.", ["en"] = "Stealing Stormwind's Flame", ["tasks"] = { ["Flame of Stormwind"] = "полум'я Штормовію", ["Flame of Stormwind (Provided)"] = "полум'я Штормовію (видано)" } },
    [9331] = { [1] = "Викрадення полум'я Залізогарта", [2] = "Це полум'я, викрадене із серця Залізогарта, переповнює вас теплом. Ця первісна сила чужа для вас, але оповідник, можливо, знає більше...", [3] = "Принесіть полум'я Залізогарта до фестивального оповідника.", [4] = "Ти майже палаєш, {раса:к}. Що це у тебе?", [5] = "Це міцне полум'я мусить бути з залів Залізогарта. Воно таке ж міцне, як самі дворфи. Чудовий здобуток, {ім'я}. Якби я мав вогні інших міст... але це не важливо. Ось твоя винагорода.", ["en"] = "Stealing Ironforge's Flame", ["tasks"] = { ["Flame of Ironforge"] = "полум'я Залізогарта", ["Flame of Ironforge (Provided)"] = "полум'я Залізогарта (видано)" } },
    [9332] = { [1] = "Викрадення полум'я Дарнаса", [2] = "Це полум'я, викрадене з берегів Тельдрассіля, переповнює вас теплом. Ця первісна сила чужа для вас, але оповідник, можливо, знає більше...", [3] = "Принесіть полум'я Дарнаса до фестивального оповідника.", [4] = "Ти майже палаєш, {раса:к}. Що це у тебе?", [5] = "Цей вогонь переповнений древнім смутком, {ім'я}. Ти кажеш, що {стать:вийняв:вийняла} його з коренів Тельдрассіля? Неймовірно! Ось твоя нагорода за твою майстерність. Звертайся до мене, якщо знайдеш ще щось подібне.", ["en"] = "Stealing Darnassus's Flame", ["tasks"] = { ["Flame of Darnassus"] = "полум'я Дарнаса", ["Flame of Darnassus (Provided)"] = "полум'я Дарнаса (видано)" } },
    [9333] = { [1] = "Рукавиці Сріблястого Світанку", [4] = "Якщо принесеш мені тридцять некротичних рун, я запропоную рукавиці на твій вибір. Вони стануть у пригоді в боротьбі зі Скарою.", [5] = "Гарна робота, {ім'я}. На знак подяки за твої зусилля обери собі рукавиці.", ["en"] = "Argent Dawn Gloves", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [9334] = { [1] = "Благословенна чарівна олія", [4] = "В обмін на некротичні руни загарбників Скари, Сріблястий Світанок дасть тобі один флакон благословенної чарівної олії.", [5] = "Сподіваюся, це стане тобі у пригоді в майбутніх битвах.", ["en"] = "Blessed Wizard Oil", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [9335] = { [1] = "Освячені точильні камені", [4] = "Якщо принесеш мені вісім некротичних рун, я дам тобі освячений точильний камінь. Він стане тобі у пригоді в битві з послідовниками Короля-ліча.", [5] = "Дякую, {ім'я}. Ось твої освячені точильні камені. Використовуй їх з розумом.", ["en"] = "Consecrated Sharpening Stones", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [9336] = { [1] = "Величезне зілля лікування", [4] = "Окрім інших припасів, у нас також є кілька величезних зіллів лікування, які можуть стати тобі в пригоді. Я дам вам одне в обмін на п'ятнадцять некротичних рун.", [5] = "Ось, тримай, {ім'я}. Обережніше там. Нас не так багато, щоб ми могли дозволити собі великі втрати на полі бою.", ["en"] = "Major Healing Potion", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [9343] = { [1] = "Гербова накидка Сріблястого Світанку", [4] = "Твоя допомога нашій справі була дуже цінною, {ім'я}. Якщо бажаєш, ти можеш отримати гербову накидку Сріблястого Світанку. Ми пишаємося мати таких союзників як ти.", [5] = "Візьми цю гербову накидку і носи її з гордістю. Можливо, твої вчинки надихнуть інших взяти до рук зброю і підтримати нашу боротьбу проти Скари.", ["en"] = "Tabard of the Argent Dawn", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [936] = { [1] = "Допомога верховному друїду Рунному Тотему", [2] = "Перепрошую, {клас:к}, можна тебе на хвилинку?\n\nКенарійське Коло в Громовому Бескиді зацікавлене в таких досвідчених шукачах пригод, як ти, що допоможуть їм з важливим дослідницьким проєктом. Я не знаю подробиць, та можу точно сказати, що очолює цей проєкт сам верховний друїд Гамуул Рунний Тотем.\n\nБудь ласка — якщо тобі цікаво, поговори з ним особисто на Верхів'ї Старійшин у Громовому Бескиді.", [3] = "Поговоріть із верховним друїдом Гамуулом Рунним Тотемом у Громовому Бескиді.", [5] = "Вітаю, {клас:к}. Радий бачити твою зацікавленість в нашому дослідженні. Роботи дуже багато, але я поведуся негарно, якщо не попереджу тебе про те, що вона досить небезпечна. Сподіваюся, тебе це не лякає... з іншого боку, дивлячись на тебе, переконуюся, що ти вже {стать:досвідчений:досвідчена} в таких справах.", ["en"] = "Assisting Arch Druid Runetotem" },
    [9365] = { [1] = "Нагорода крадія", [2] = "Це полум'я, викрадене із серця Штормовію, переповнює вас теплом. Ця первісна сила чужа для вас, але оповідник, можливо, знає більше...", [3] = "Принесіть полум'я Штормовію до фестивального оповідника.", [5] = "Сьогодні ти {стать:показав:показала} себе, {ім'я}.\n\nХоча мені більше нічого тобі дати, я маю цю корону — гідний подарунок для {стать:завойовника:завойовниці}. Нехай вона освітлює твій шлях.", ["en"] = "A Thief's Reward" },
    [93735] = { [1] = "Зламана конструкція", [2] = "Історично склалося так, що Творці Вітру доглядали за магічними інструментами та пристроями, подарованими нам духами вітру. Це включає безліч магічних конструкцій по всьому острову. Відколи духи покинули нас, лише деякі з них досі функціональні.\n\nОдна з небагатьох робочих конструкцій, що залишилися у Валанаарі, пошкоджена. Одного з наших ремісників було відправлено на допомогу, але йому, можливо, потрібна допомога. Вирушайте до західного кінця міста та запропонуйте будь-яку допомогу, яку можете.", [3] = "Знайдіть Ріаані Нічний Вітер на західній стороні Валанаару.", ["en"] = "The Broken Construct" },
    [93736] = { [1] = "Небажані духи", [2] = "Найголовніше завдання Вітротворців — краще зрозуміти, чому духи покинули нас, і що ми можемо зробити, щоб повернути їх. Однією з цікавих рис Тіньового лісу на півночі є присутність дивної форми вітрового спрайта, яку деякі називають «порожнечами». Ми мало знаємо про них і чому вони там, але ми точно знаємо, що вони почали з'являтися після того, як духи вітру покинули нас.\n\nМені потрібно, щоб ти пішов туди та розвіяв їх. Збери останки та принеси їх сюди.", [3] = "Зберіть 10 сутностей Вітряної Ущелини з Вітряних Ущелин у Лісі Тіньовітру.", ["en"] = "Unwelcome Spirits", ["tasks"] = { ["Wind Hollow Essence"] = "Сутність Вітряної Ущелини", ["Wind Hollow Essence (Provided)"] = "Сутність Вітряної Ущелини (видано)", ["Wind Hollow Essence slain"] = "Сутність Вітряної Ущелини: убито" } },
    [93737] = { [1] = "Зламана конструкція", [2] = "О, привіт. Айєсса послала тебе мені допомогти? Добре тоді.\n\nНе знаю, що може зробити такий очевидний новачок, як ти, але якщо ти даси мені хвилинку, щоб витягнути голову з нутрощів цієї конструкції, у мене може бути кілька ідей, як ти можеш допомогти.", [3] = "Поговоріть з Ріанні Найтвінд і вислухайте, що він має сказати.", ["en"] = "The Broken Construct", ["tasks"] = { ["Air Construct Core"] = "Повітряний конструкційний ядро", ["Air Construct Core (Provided)"] = "Повітряний конструкційний ядро (видано)", ["Air Construct Core slain"] = "Повітряний конструкційний ядро: убито", ["Crystallized Lightning"] = "Кристалізована блискавка", ["Crystallized Lightning (Provided)"] = "Кристалізована блискавка (видано)", ["Crystallized Lightning slain"] = "Кристалізована блискавка: убито", ["Enchanted Gyrozephyr"] = "Зачарований Гірозефір", ["Enchanted Gyrozephyr (Provided)"] = "Зачарований Гірозефір (видано)", ["Enchanted Gyrozephyr slain"] = "Зачарований Гірозефір: убито", ["Listen to what Riaani Nightwind has to say"] = "Послухайте, що каже Ріані Найтвінд" } },
    [93738] = { [1] = "Зламана конструкція", [2] = "Яскраве бажання, га? Отже, Вищий Орден з якоїсь причини хотів видалити ці компоненти. Але чому?\n\nВищий Орден завжди був настирливим, постійно бажаючи експериментувати з магією духів вітру. Вони надто сміливі, і ми суворо заборонили їм втручатися у знання, що знаходяться під контролем Вітротворців, але останнім часом вони випробовують наше терпіння.\n\nЯ думаю, тобі варто повідомити про те, що ти дізнався, Айєсі Світанковій Співачці. Вона може далі вказати тобі, що робити.", [3] = "Повідомте про це Айєсі Доунсінгер у Валанаарі.", ["en"] = "The Broken Construct" },
    [93739] = { [1] = "Дослідження Орди", [2] = "Азерот — це великий світ, а територія Орди неосяжна. Підмісто, Орґріммар і Громова Утеса мають унікальні люди та культуру.\n\nЯкщо ви маєте бути гостем Орди тут, в Азероті, вам було б добре відвідати кожну з наших столиць по черзі. Поговоріть з моїм радником Назгрелем, щоб дізнатися дорогу.", [3] = "Поговоріть з Назгрелем у фортеці Громмаш, щоб отримати подальші інструкції. Використайте отримані інструкції, щоб знайти Вол'джина, Керна Кривавого Копита та Леді Сильвану Вітрокрилку та поговорити з ними.", ["en"] = "Exploring the Horde", ["tasks"] = { ["Obtain Instructions from Nazgrel"] = "Отримати інструкції від Назгрела", ["Speak with Cairne Bloodhoof"] = "Поговоріть з Керном Кривавим Копитом", ["Speak with Lady Sylvanas Windrunner"] = "Поговоріть з леді Сільваною Віндраннер", ["Speak with Vol'jin"] = "Поговори з Вол'джином" } },
    [93740] = { [1] = "Кров за кров", [2] = "Кілька наших новачків-вітроутворювачів були знайдені мертвими у Високогір'ї сьогодні вранці. Ми не можемо бути впевнені, але є велика ймовірність, що за це відповідальні Ал'Акети. Вітроутворювачі щоразу обмінюють кров на кров.\n\nВирушайте на північ і вбивайте будь-якого Ал'Акета, якого зустрінете. Принесіть мені їхні молитовні амулети з вітряного каменю як доказ скоєного. Ми не прощаємо і не забуваємо.", [3] = "Зберіть 10 оберегів Вітряного каменю Ал'Акет з трупів культистів Ал'Акет у Низині Гастберрі.", ["en"] = "Blood for Blood", ["tasks"] = { ["Al'Aketh Windstone Charm"] = "Оберіг з вітряного каменю Аль'Акет", ["Al'Aketh Windstone Charm (Provided)"] = "Оберіг з вітряного каменю Аль'Акет (видано)", ["Al'Aketh Windstone Charm slain"] = "Оберіг з вітряного каменю Аль'Акет: убито" } },
    [93746] = { [1] = "Рішуча відповідь", [2] = "Вищий Орден попереджено про наслідки втручання у справи Вітротворця. Я думаю, нам потрібно взяти приклад з Белатаана та відправити його назад до Вищого Ордену з кількома синцями та здоровою повагою до встановлених нами меж.\n\nБелатаана бачили, як він виходив з міста, прямуючи на північ до Святилища Акіра. Я не знаю, чому він туди йшов, але зустрітися з ним наодинці на дорозі — найбезпечніший варіант. Знайдіть його та вселіть трохи страху в його серце.", [3] = "Зіткніться з Белтааном Брайтвішем дорогою до святилища Акіра.", ["en"] = "A Firm Response", ["tasks"] = { ["Confront Belathaan Brightwish"] = "Протистояти Белатаану Брайтвішу", ["Defeat the Living Storms"] = "Переможіть Живі Бурі" } },
    [93836] = { [1] = "Доля Зефраса", [2] = "Мулн багато розповів мені про володарів стихій, і я боюся, що у нас є вагомі підстави боятися Ал'Акіра. Тепер, коли охоронні чари, що приховували Зефраса від його очей, зняті, ми абсолютно беззахисні... Якщо він вирішить напасти на нас, у нас немає жодних шансів протистояти йому тут, у його власних володіннях.\n\nВерховний старійшина Тіньопісні повинен знати про небезпеку, в якій ми знаходимося, і, що ще важливіше, про наші наміри щодо нашої місії в Азерот. Ми знайдемо засоби, щоб врятувати наш дім. Клянусь.", [3] = "Поговоріть із Талаанісом Шодосонг у Валанаарі.", ["en"] = "The Fate of Zephras", ["tasks"] = { ["Speak with Talaanis Shadowsong"] = "Поговоріть з Талаанісом Тіньоспівом" } },
    [9416] = { [1] = "Звіт генералу Кіріці", [2] = "Ти, мабуть, {стать:один:одна} з новобранців генерала Кіріки. Ти вчасно {стать:прийшов:прийшла}. Тіла швидко виснажуються у пустелі.\n\nДворфи щодня отримують підкріплення і ми не можемо поступитися їм в боротьбі за ресурси Силітуса.\n\nГенерал надасть тобі вказівки. В мої обов'язки це не входить, мені наказали просто знайти тебе.", [3] = "Поговоріть з генералом Кірікою в таборі Орди біля Вул'Регаля.", [5] = "Добре, що ти тут, але у нас немає часу на пусті балачки. Я проінструктую тебе, і ти одразу підеш звідси.\n\nСлухай уважно.", ["en"] = "Report to General Kirika" },
    [9422] = { [1] = "Прочісування пустелі", [2] = "Вже тривалий період часу ми добуваємо кристали пустелі Силітуса. Єдиною небезпекою, з якою ми досі стикалися, були місцеві істоти, пісок, пил та спека.\n\nАле тепер, схоже, Альянс зацікавився тим, чим ми тут займаємося. Тепер ми змагаємося за те, щоб захопити якомога більше ресурсів.\n\nМені потрібна кожна вільна пара рук. Сподіваюся, ти мені допоможеш.", [3] = "Знайдіть і принесіть силітист до екстрактора силітиста, після чого поговоріть з генералом Кірікою у таборі Орди біля Вул'Регаля.", [4] = "Пустеля дуже небезпечна, тож будь {стать:обережним:обережною}, {ім'я}. Будь-який крок може стати для тебе останнім, солдати Альянсу ховаються в дюнах.", [5] = "Ти добре {стать:попрацював:попрацювала}, {ім'я}. Ці ресурси відправляться на склад, до усіх наших запасів, і кожен шматочок піде на користь нам та на шкоду нашим ворогам.", ["en"] = "Scouring the Desert", ["tasks"] = { ["Deliver Silithyst"] = "Доставити Силітист" } },
    [94411] = { [1] = "Настирливі маги", [2] = "Будьте обережні, членів Високого Ордену бачили поблизу каменів на північ від села. Ми неодноразово попереджали їх не втручатися в наші священні місця, але вони стають дедалі зухвалішими у своєму тиску. Доведіть нам свою рішучість, підійшовши до каменів та розвіявши їх.\n\nЯ не хочу виправдовувати відверте кровопролиття, але зробіть усе необхідне, щоб їх відігнати. Поверніться до мене, коли воно закінчиться.", [3] = "Убийте 6 учнів вищого ордена у Шен'дарському нагір'ї.", ["en"] = "Meddlesome Mages", ["tasks"] = { ["High Order Apprentice defeated"] = "Учень Вищого Ордена переможений" } },
    [94427] = { [1] = "Урок богослов'я", [2] = "Ключовою рисою паладіна є прагнення до божественності. Це не прагнення до божественності, а лише прагнення до добра як такого, заради добра. Ми всі потрапили сюди через трагедію в тій чи іншій формі, і було б легко втратити ту благодать, яка визначала нас як паладінів за життя.\n\nВирушайте до Підмістя та знайдіть Таніса Алдервуда в Торговому кварталі. Вони потребують допомоги, і їм може дуже допомогти трохи благодаті.", [3] = "Поговоріть з Танісом Алдервудом у Підмісті.", ["en"] = "A Lesson in Divinity" },
    [94434] = { [1] = "Урок богослов'я", [2] = "Зачекай, ти хочеш... допомогти? Чому паладин хоче допомогти такому жебраку, як я?\n\nНу, гадаю, ти міг би якось допомогти.\n\nБачиш, це моя дружина. Вона, ну... вона розвалюється. Я маю на увазі це буквально. Аптекарі можуть зашити її докупи, як дощ, але вони займаються справами Темної Леді, і ніхто не може допомогти. Якщо ти міг би принести мені трохи свіжої тканини, я міг би хоча б зробити їй обгортку, щоб вона трималася, поки ми чекаємо на аптекарів.", [3] = "Принесіть 10 одиниць лляної тканини Танісу Олдервуду в Підмісті.", ["en"] = "A Lesson in Divinity", ["tasks"] = { ["Linen Cloth"] = "лляна тканина" } },
    [94435] = { [1] = "Урок богослов'я", [2] = "Не знаю, чому ти так старався мені допомогти, але я це ціную. Якщо хтось надіслав тобі мене, скажи йому, що я теж його ціную. У тебе завжди буде друг у Танісі Алдервуді, {клас}.", [3] = "Поверніться до Даніти Морр у фортецю Бандаріон.", ["en"] = "A Lesson in Divinity" },
    [94436] = { [1] = "Урок богослов'я", [2] = "Настав час продемонструвати вашу здатність використовувати один з найвеличніших дарів світла.\n\nПредмет, який я щойно вам дав, називається Символ Життя. Будьте обережні, оскільки використання такого талісмана світла може завдати вам певного дискомфорту. Світло може бути анафемою для сили, яка нас створила, але воно все ще наш провідник і союзник. Біль нагадує нам про це.\n\nПідійдіть до Стража Смерті Біллмута внизу. Він щойно прибув і попросив нас про допомогу. Покажіть йому та Відреклимся, на що здатний справжній паладин.", [3] = "Поговоріть зі Смертеваржем Біллмутом у Бандеріонській фортеці.\n\nЯкщо ви загубите свій Символ Життя, поверніться до Даніти Морр за заміною.", ["en"] = "A Lesson in Divinity", ["tasks"] = { ["Speak with Deathguard Billmuth at Tyr's Watch."] = "Поговоріть зі Смертельним Вартом Біллмутом у Варті Тіра." } },
    [94438] = { [1] = "Урок богослов'я", [2] = "Нас з Фалганом відправили на місію розвідати активність червоних істот у Веномвеб-Вейл. Нам вдалося підкрастися досить близько до одного з їхніх таборів, щоб почути про нові накази щодо нападу на Брілла. Перш ніж ми встигли вирішити, що робити далі, я наступив на гілочку, і шум сповістив їх про нас.\n\nФалган крикнув мені, щоб я біг, тож я побіг. Поки я зрозумів, що його немає зі мною, я був на півдорозі до Брілла. Той хоробрий ідіот, мабуть, залишився, щоб стримати їх для мене.\n\nБудь ласка, знайдіть мого друга та допоможіть йому, якщо можете.", [3] = "Візьміть Символ Життя та використайте його, щоб воскресити Стража Смерті Фалгана у Долині Отрути.\n\nЯкщо ви загубите свій Символ Життя, поверніться до Даніти Морр за заміною.", ["en"] = "A Lesson in Divinity", ["tasks"] = { ["Take the Symbol of Life and use it to resurrect Deathguard Falgan at Venomweb Vale."] = "Візьміть Символ Життя та використовуйте його, щоб воскресити Стража Смерті Фалгана у Веномвеб-Великій Долині." } },
    [94440] = { [1] = "Урок богослов'я", [2] = "Ці Багряні Хрестоносці часто носять сумки зі своїми наказами про розгортання. Ми знаємо, що наближається атака, але якщо нам вдасться отримати їхні накази, ми зможемо попередити решту Гвардії Смерті та підготувати засідку.\n\nТи явно вражаючий паладин. Убий цих багряних тварин, візьми копію їхніх наказів і принеси їх до Гвардійця Смерті Біллмута. Далі він візьметься за справу.", [3] = "Заберіть плани атаки Червоного хрестоносного походу у Червоних хрестоносців у Долині Отруйної Павутини та поверніть їх до Вартового Смерті Біллмута у Варту Тіра.", ["en"] = "A Lesson in Divinity", ["tasks"] = { ["Scarlet Crusade Attack Plans"] = "Плани атаки Червоного хрестового походу" } },
    [94441] = { [1] = "Урок богослов'я", [2] = "Будь ласка, передайте від мене подяку Даніті Морр і скажіть їй, що решта Гвардії Смерті почує про службу, яку паладини Варти Тіра надали нам.\n\nВи подаєте великі надії як паладин, і я пишаюся тим, що такі, як ви, є в лавах Відреклих. Темна Леді пильнує вас, {ім'я}.", [3] = "Поговоріть з Данітою Морр у фортеці Варти Тіра.", ["en"] = "A Lesson in Divinity" },
    [94911] = { [1] = "Дитя природи", [2] = "Вітаю, юний {раса}. Бачу, що ти маєш великі надії в мистецтві друїдів. У місті Громовий Бескид є один, з ким тобі, можливо, варто поговорити, на ім'я Турак Рунототем. Він навчить тебе, як дістатися до фортеці Кола Кенаріона на Калімдорі, Місячної Поляни.\n\nТебе там радо зустрінуть, і друїди кола поділяться з тобою своїми знаннями.\n\nЯк сказав би твій народ — йди з благословенням вітру, юний. Бажаю тобі удачі в твоїх пригодах.", [3] = "Поговоріть з Тураком Рунотомом у Громовій Утепі.", ["en"] = "Child of Nature" },
    [94913] = { [1] = "Місячна галявина", [2] = "Усіх друїдів вітають у священних землях Мунґлейду. Хранитель Ремулос — охоронець Мунґлейду — стежить за всіма друїдами, які там зимують. Я навчу тебе заклинанню, яке дозволить тобі перенестися туди. Використовуй його щоразу, коли шукатимеш знань чи розради Мунґлейду.\n\nЩодо твого першого уроку тут, на Азероті, вируши до Мунґлейду та поговори з Дендритом Зоряним Сяйвом у Нічній Гавані про шлях, яким ти зараз йдеш. Удачі тобі, юний друїде.", [3] = "Використайте заклинання «Телепорт: Місячна галявина», щоб потрапити до Місячної галявини. Коли прибудете, поговоріть з Дендритом Зоряним Сяйвом у селі Найтгейн.", ["en"] = "Moonglade" },
    [95034] = { [1] = "Борг", [2] = "Гадаю, тобі слід знати, що насправді це не гноли напали на нас на дорозі.\n\nНасправді на нас напала гігантська істота, схожа на вовка, яку я тепер знаю як «воргена». Вона відправила наших охоронців і побігла за мною, але Банон кинувся їй на шляху. Мені вдалося зняти заклинання, яке налякало істоту та змусило її втекти, але Банон вже був сильно покусаний. Він наполягав, щоб я залишив його там, але я відмовився.\n\nМи шкутильгали назад сюди, коли нас знайшли гноли. Те, що сталося далі, було жахливим...", [3] = "Поговоріть з Люміною Віндсінгер у Гробниці.", ["en"] = "The Debt", ["tasks"] = { ["Speak with Lumina Windsinger"] = "Поговоріть з Люміною Віндсінгер" } },
    [95036] = { [1] = "Лезо, поцілуване місяцем", [2] = "Треван каже мені, що воргени становлять серйозну загрозу для мешканців Сріблястого Лісу. Незважаючи на їхню силу та стійкість, їх можна вбити, але є один, який, здається, ніколи не залишається мертвим через невідому магію.\n\nЦе той, хто напав на нас. Він відомий як Старий Вогняний Око, і він найбільший і найпідліший з їхнього виду. Щоб його знищити, нам знадобиться особлива зброя.\n\nПоговоріть з Треваном, і він надасть вам список того, що потрібно для виготовлення такої зброї.", [3] = "Поговоріть з Треваном Ролом у Гробниці та принесіть йому необхідні матеріали.", ["en"] = "A Moon-Kissed Blade", ["tasks"] = { ["Enchanted Silver Ingot"] = "Зачарований срібний злиток", ["Purified Kor Gem"] = "очищений самоцвіт Кора", ["Trevan's Weapon Notes"] = "Нотатки Тревана про зброю", ["Whitestone Oak Lumber"] = "деревина білокам'яного дуба" } },
    [95042] = { [1] = "Пошуки самоцвіту Кора", [2] = "Покинутий паладин... тут, у Ясенедолі? Цікаво.\n\nОтже, ви шукаєте самоцвіт Кор? Не дивно, адже його іноді використовують для посилення магічної зброї та знарядь паладини альянсу. Чому такий занепалий паладин, як ви, має бути іншим?\n\nЯкщо ви справді бажаєте одного з самоцвітів, то вам слід вирушити на північ до руїн, відомих як Чорнопровалля. Наги, які досі використовують самоцвіти, знаходяться внизу. Не йдіть самі, {клас}.", [3] = "Принесіть самоцвіт Кора Ульріку Фроствейлю в Ясенеділ.", ["en"] = "Seeking the Kor Gem", ["tasks"] = { ["Corrupted Kor Gem"] = "осквернений самоцвіт Кора" } },
    [95111] = { [1] = "Недооцінений талант", [2] = "У Таррен-Мілл є зброяр на ім'я Отт. За всіма даними, він нічим не примітний коваль, який продає прості клинки мандрівникам. Я сам купив у нього меч, і коли через деякий час відніс його до Підмістя на ремонт, ковалі там були здивовані його якістю. Вони припустили, що він від відомого майстра-коваля, але ні, це був просто Отт.\n\nЯ хотів би дати цьому орку шанс зробити щось справді особливе. Віднесіть матеріали Отту в Таррен-Мілл і запропонуйте йому замовлення.", ["en"] = "An Underrated Talent", ["tasks"] = { ["Bundle of Blacksmithing Materials"] = "Набір ковальських матеріалів", ["Bundle of Blacksmithing Materials (Provided)"] = "Набір ковальських матеріалів (видано)" } },
    [95125] = { [1] = "Шедевр Отта", [2] = "Це справді чудові матеріали, {клас}. Ви вшановуєте мене, дозволивши мені викувати для вас цей клинок, і я лише сподіваюся, що зможу виправдати ваші очікування.\n\nБудь ласка, відійдіть, щоб я міг розпочати процес кування.", ["en"] = "Ott's Masterwork", ["tasks"] = { ["Watch Ott craft the blade"] = "Дивіться, як Отт виготовляє клинок" } },
    [95126] = { [1] = "Місячно-срібний клинок", [2] = "Ось клинок. Ти казав, що тебе послав паладин на ім'я Треван? Будь ласка, передай йому від мене подяку за цю можливість, коли наступного разу його побачиш. Іди з честю, друже.", ["en"] = "The Moonsilver Blade", ["tasks"] = { ["Ott's Masterwork"] = "Шедевр Отта", ["Ott's Masterwork (Provided)"] = "Шедевр Отта (видано)" } },
    [95140] = { [1] = "Старий Вогняний Око", [2] = "Бачу, що у тебе тепер є зброя, {клас}. Молюся, щоб вона тебе не підвела.\n\nМісцеві жителі кажуть мені, що Старий Вогняний Око полює на великій території на південь звідси, і зазвичай його можна знайти біля воріт до Гілнеасу. Знайди його та використовуй свій новий клинок, щоб убити його. Коли це буде зроблено, повернися, і ти отримаєш вдячність Вітротворців.", [3] = "Використайте Срібний Клинок Місяця, щоб знищити Око Старого Вогню в Сріблястому Лісі.", ["en"] = "Old Fire-Eye", ["tasks"] = { ["Moonsilver Blade"] = "Клинок Місячно-срібного кольору", ["Old Fire-Eye slain"] = "Старий Вогняний Око: убито" } },
    [95216] = { [1] = "Нова чума", [2] = "Ласкаво просимо до найважливішого органу Підземного Міста: Апотекарію! Тут ми експериментуємо з найшкідливішими екзотичними зразками Азероту.\n\nВи підняли мені настрій, тож я розповім вам про своє останнє розслідування. Схоже, що над нашим прекрасним містом по руїнах крадеться особливо отруйне членистоноге. Кажуть, що його токсини роз'їдають навіть плоть нежиті. Як це захопливо!\n\nЯ хочу підтвердити ці твердження. Якщо ви помрете від його укусу, я буду радий отримати зразок.", [3] = "Зберіть високотоксичний штам у Визерфанга в Руїнах Лордерона для Теодора Гріффа в Підмісті.", ["en"] = "The New Plague", ["tasks"] = { ["Highly Toxic Strain"] = "Високотоксичний штам", ["Highly Toxic Strain (Provided)"] = "Високотоксичний штам (видано)", ["Highly Toxic Strain slain"] = "Високотоксичний штам: убито" } },
    [95328] = { [1] = "Шепіт жахливого залишку", [2] = "Всупереч здоровому глузду, ти збираєш звиваючі останки звіра. Комусь в Підмісті вони можуть знадобитися.", [3] = "Доставте Залишки Шепіту Жахів Отцю Ланкестеру у Військовому Кварталі Підмістя.", ["en"] = "Whispering Horror Residue", ["tasks"] = { ["Whispering Horror Residue"] = "Шепіт жахливого залишку" } },
    [95349] = { [1] = "Земляне кільце", [2] = "Нещодавні події з культом відклали мої плани подорожі до Азероту, і я маю деякий час залишитися тут, у Валанаарі. Ви та кілька інших Вітротворців будете нашим авангардом. Алаана Буревісниця чекатиме на вас після прибуття до Мулгору, і я б закликала вас дослідити Азерот, поки ми завершуємо наші справи тут. Ми скоро до вас приєднаємося.\n\nКоли будете готові, будь ласка, пройдіть до причалу одразу за цим будиночком і сідайте там на корабель-небескосмер. Бану-Алах, {ім'я}.", [3] = "Сядьте на корабель-небесоносець з острова Зефрас до Мулгору та поговоріть з Аланою Штормвокер, коли прибудете.", ["en"] = "The Earthen Ring" },
    [95350] = { [1] = "Ласкаво просимо до Азероту", [2] = "Тут, внизу, великий світ, і наші нові союзники є ключем до нашого виживання.\n\nЗемляне Кільце є членом «Орди», гордої спільноти однодумців. Сусіднє місто Громовий Бескид є частиною орди, а далі на схід лежить столиця Орґріммара.\n\nЗнайдіть керівника польотів у центрі Громового Бескиду. Він доставить вас до Орґріммара, де ви зв'яжетеся з вождем орди – Траллом, від імені Творців Вітрів. Вітри ведуть вас, {ім'я}.", [3] = "Вирушайте до Орґріммара та поговоріть з Траллом у Долині Мудрості.", ["en"] = "Welcome to Azeroth" },
    [95494] = { [1] = "Побита гордість і лев'ячі шкури", [2] = "Мені потрібна людина з сильною рукою, що володіє мечем, і вільним часом, щоб допомогти мені зібрати лев'ячі шкури. Мені шкодить гордість просити про цю допомогу незнайомця, але нещодавно я отримав травму ноги. Поки я не одужую, я не в змозі сам полювати, але маю зобов'язання.\n\nУ великих льодяників у цьому районі зазвичай найкращі шкури, тому почніть з них.", [3] = "Зберіть 6 шкур левів Савани у матріархів Савани та патріархів Савани у Степах.", ["en"] = "Bruised Pride and Lion Hides", ["tasks"] = { ["Savannah Lion Hide"] = "Шкура лева савани" } },
    [95495] = { [1] = "Відлюдник Таннер", [2] = "Ці шкури призначені для шкіряника, з яким я часто торгую. Він щось на зразок відлюдника і живе сам на вершині хребта позаду мене. Підйом крутим схилом пагорба зараз мені нелегко впоратися, тому я був би вам у боргу, якби ви могли доставити цю шкуру для мене.\n\nО, і щодо зовнішності цього шкіряника... вам не варто хвилюватися. Незважаючи на його зовнішній вигляд, він не становить загрози. Клянусь, це правда.", [3] = "Принесіть Згорток Шкур відлюднику на хребті з видом на Сухі Пагорби в Степах.", ["en"] = "The Hermit Tanner", ["tasks"] = { ["Bundle of Hides"] = "оберемок шкур", ["Bundle of Hides (Provided)"] = "оберемок шкур (видано)" } },
    [95507] = { [1] = "Гра Вранга", [2] = "Поки ти там, мені було б дуже корисно, якби ти перевірив мої пастки. Я розкидав їх по всій долині.\n\nПринеси будь-яку дрібну дичину, яку я спіймав. Однак слідкуй за іншими дикими тваринами. Ця місцевість може бути небезпечною, якщо ти не будеш уважним.", [3] = "Зберіть 8 одиниць полонених тварин з пасток, знайдених у Пружинних пастках у Степях.", ["en"] = "Vrang's Game", ["tasks"] = { ["Trapped Game"] = "Гра в пастці" } },
    [95508] = { [1] = "Небажані гості", [2] = "Так, я колись був членом флоту Кул-Тіраса. Після того, як лорд-адмірал взяв Терамор і розпочав свою кампанію в Дуротарі, у мене виникли... \"заперечення\" проти його методів. Зокрема, проти методів, що передбачають страту цивільних осіб.\n\nЦе ще дещо, але... зачекайте... що це?\n\nГрупа чоловіків піднімається на хребет!", [3] = "Допоможіть Волтону пережити сутичку з Террі Лонгдрінк та морськими піхотинцями Кул-Тіраса.", ["en"] = "Unwelcome Guests", ["tasks"] = { ["Assist Walton"] = "Асист Волтона" } },
    [95621] = { [1] = "Проблеми в долині", [2] = "Цього ранку я помітив групу людей, які щось шукали в долині внизу. Мені вдалося використати приціл гвинтівки, щоб краще роздивитися, і було зрозуміло, що це солдати в лівреях Кул-Тіраса.\n\nЯкщо ви готові взятися за мою роботу, вирушайте туди, де ці солдати розбили табір біля розбитого фургона на півдні. Вбийте всіх, кого знайдете, і спробуйте дізнатися, чому вони тут.", [3] = "Подорожуйте до розбитого каравану та дізнайтеся більше про те, чому тут опинилися кул-тирани.", ["en"] = "Trouble in the Valley", ["tasks"] = { ["Benedict's Orders"] = "Ордени Бенедикта" } },
    [95664] = { [1] = "Знання старійшин", [2] = "Цей незвичайний уламок зі складеного матеріалу розсіює світло, мов жива призма. Його природа невідома, але сила здається прадавньою. Найкращих знавців артефактів тієї давно минулої доби варто шукати на верхів'ї Старійшин у Громовому Бескиді.", [3] = "Віднесіть реліквію титанів на верхів'я Старійшин у Громовому Бескиді й знайдіть когось, хто зможе розповісти про неї більше.", ["en"] = "Elder Knowledge", ["tasks"] = { ["Titan Relic"] = "Реліквія титанів" } },
    [95697] = { [1] = "Зміна смаків", [2] = "Замджа каже, що нам потрібно більше домашніх страв.\nВона думає, що м'ясо рапторів привабить відвідувачів, які зазвичай оминають вогнище Борстена.\n\nНепогана думка. Але я хочу чогось вишуканішого за пахощі наших рідних сіл. Ми ж в Орґріммарі! Борстен має запропонувати їм величну версію знайомих улюблених страв.\n\nНещодавно один мисливець повернувся із Заболоття з величезним кігтем хащового раптора з розкопок.\n\nВізьмешся за роботу?", [3] = "Вирушайте на розкопки в Заболотті й принесіть м'ясо хащових рапторів.", ["en"] = "Changing Tastes", ["tasks"] = { ["Thicket Raptor Meat"] = "М'ясо чагарникового раптора" } },
    [95774] = { [1] = "Її звати Ольгра", [2] = "Цілитель, який мене врятував, не зміг її врятувати, і вона загинула в бою. Її звати Ольгра, і я ніколи її не забуду.\n\nВи не знайшли її прикрас на її тілі? Вона носила багато коштовностей з полірованої кістки.\n\nУбийте Острогривих Розбійників поблизу місця, де вона впала, і знайдіть її дорогоцінні витвори мистецтва!\n\nЯ покладу їх поруч із меморіалом, який я зведу на її пам'ять.", [3] = "Убийте вепрів та зберіть 4 Прикраси Ольгри для меморіалу Манкрика.", ["en"] = "Her Name Is Olgra", ["tasks"] = { ["Olgra's Adornments"] = "Прикраси Ольгри" } },
    [95803] = { [1] = "Знак доброї віри", [2] = "Тепер, коли ми заволоділи головою заплямованого командира, мені потрібно, щоб ви доставили її до Підмістя. Сильвана Віндраннер дуже нам не довіряє і майже відкрито зневажає нас.\n\nДоставте голову Рудольфа Гелхардта Темній Леді. Покажіть їй, що ми піклуємося про свій дім і віддані процвітанню покинутих.", [3] = "Принесіть голову Рудольфа Гелхардта Сильвані Віндраннер у Підмісто.", ["en"] = "A Token of Good Faith", ["tasks"] = { ["Rudolph Gelhardt's Head"] = "Голова Рудольфа Гельхардта", ["Rudolph Gelhardt's Head (Provided)"] = "Голова Рудольфа Гельхардта (видано)" } },
    [95805] = { [1] = "Благодать Ан'ше та Му'ші", [2] = "Сонце і місяць, Ан'ше та Му'ша, не є частиною нашого світу, як стихії, проте їхнє світло дає нам життя, керівництво та надію.\n\nМи висловлюємо повагу духам світу, тому ми також висловлюємо повагу близнюкам.\n\nЯкщо ви бажаєте виявити свою повагу, візьміть цей тліючий пахощ і принесіть його до святилища на пагорбах на південний схід, з видом на месу, на південь від квілбору. Будьте швидкі, щоб дістатися святилища, перш ніж пахощі згорять.\n\nНе намочіть його!", [3] = "Віднесіть Тліючий Ладан до святилища Ан'ше та Му'ші на південно-східних пагорбах, перш ніж ладан згорить дотла за десять хвилин!", ["en"] = "Grace of An'she and Mu'sha", ["tasks"] = { ["Pouch of Smoldering Incense"] = "Мішечок тліючого ладану", ["Pouch of Smoldering Incense (Provided)"] = "Мішечок тліючого ладану (видано)" } },
    [95981] = { [1] = "Спостереження за дорогами", [2] = "Забрання їхніх кулонів – це лише перший крок. Якщо Кірін Тор справді постійно постачає реліквії з Даларана, ми повинні зупинити їх біля джерела.\n\nОбшукайте дороги навколо Амбермілла в пошуках чарівників та спостерігачів Даларана. Їхня присутність надто довго дозволяла вільний доступ через наші кордони. Якщо ми зможемо скоротити їхню кількість, це має покласти край потраплянню цих кулонів до Срібного Лісу.", [3] = "Убийте 8 даларанських чарівників та 8 даларанських спостерігачів для Тіньового жерця Аллістера в Гробниці.", ["en"] = "Watching the Roads", ["tasks"] = { ["Dalaran Watcher slain"] = "даларанський наглядач: убито", ["Dalaran Wizard slain"] = "даларанський чарівник: убито" } },
    [96102] = { [1] = "Кемпінг 101: Кравецька справа", [2] = "Кравецька справа — це напрочуд потужна навичка, в яку варто інвестувати, і я впевнений, що вона вам добре послужить.\n\nЯ знаю людину, яка може навчити вас, як створити прапор фракції для вашого табору, за умови, що у вас є для цього відповідні навички. Натхнення та моральний дух є ключовими складовими успіху на будь-якому полі бою, а натхненний прапор може значною мірою зарядити вас енергією.", [3] = "Поговоріть зі Снангом в Орґріммарі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Tailoring", ["tasks"] = { ["Raise your tailoring skill to 20"] = "Підвищте свою кравецьку майстерність до 20" } },
    [96130] = { [1] = "Чакуяк", [2] = "Серед прерійних вовків, які полюють на сусідніх пагорбах, є один особливо агресивний. Ми почали називати його Чакуяк. Він став загрозою для мандрівників з-за кордону.\n\nВін нишпорить по деревах на захід від озера Стоунбулл, переходячи з одного дерева на інше.\n\nПокладіть край цій загрозі та принесіть мені її шкуру, і я передам вам хвалу вождю. Остерігайтеся, бо вона небезпечна! Ви можете побачити інших мисливців, які шукають її там, і, можливо, ви могли б працювати в команді.", [3] = "Переможіть Чакуяк та поверніть її шкуру.", ["en"] = "Chakuyak", ["tasks"] = { ["Chakuyak's Pelt"] = "Шкура Чакуяка" } },
    [962] = { [1] = "Змієквіт", [2] = "Королівське товариство аптекарів, що знаходиться в Підмісті, направило мене сюди з особливою справою, {ім'я}. Можливо, ти зможеш допомогти мені, а отже й Темній Леді, на благо відречених.\n\nНещодавно я вивчала рідкісний екземпляр місцевої флори, що зветься змієквітом. І я впевнена, що в більших кількостях він має великий потенціал.\n\nНа жаль, змієквіт росте лише в найтемніших закутках Плачучих печер — небезпечних підземеллях Степів.", [3] = "Аптекарка Зама з Громового Бескиду просить вас принести 10 змієквітів.", [4] = "Сподіваюсь, ти збереш достатньо змієквіту в Плачучих печерах. Я багатьох туди відправляла, та ще ніхто не повернувся.", [5] = "Ах, чудові екземпляри. Ти гарно {стать:попрацював:попрацювала}, {ім'я}.", ["en"] = "Serpentbloom", ["tasks"] = { ["Serpentbloom"] = "змієквіт", ["Serpentbloom (Provided)"] = "змієквіт (видано)" } },
    [96204] = { [1] = "Гнів Творця Вітру", [2] = "Тепер, коли я вільний, я зроблю так, що ці мерзенні істоти пошкодують, що взагалі бачили Вітроутворювача.\n\nХодімо звідси, {клас}.", [3] = "Супроводжуйте Люміну Вітроспівачку та допоможіть їй вибратися з фортеці Фенріс.", ["en"] = "The Windshaper's Wrath", ["tasks"] = { ["Escort Lumina Windsinger to safety"] = "Супровід Луміни Віндсінгер у безпечне місце" } },
    [96241] = { [1] = "Поговорімо про отрути, мон", [2] = "Щось дивне коїться там, на Сході мороку. Старий Мазу'кон тільки й чує про нових мерзенних тварюк, які там повсюди шастають.\n\nКажуть, отрута тих повзучих страховиськ має незвичайні властивості. І це мене зацікавило. Бери мій екстрактор. Скористайся ним на трупах, що там валяються, і збери отруту. Зробиш це — буду перед тобою в боргу, мон.", [3] = "Використайте екстрактор токсинів, щоб зібрати 5 зразків токсину Сходу мороку з обгризених трупів на Сході мороку.", ["en"] = "Talkin' bout Toxins, Mon", ["tasks"] = { ["Gloomrise Toxin Sample"] = "Зразок токсину Похмурого Сходу", ["Toxin Extractor (Provided)"] = "Екстрактор токсинів (видано)" } },
    [96259] = { [1] = "Захист померлих", [2] = "На Сході мороку, на північний захід від цього табору, є давнє тауренське кладовище. Останнім часом його заполонив особливо лютий виводок павуків. Вони не лише загрожують мешканцям Мулґору, а й руйнують місце, яке більшість тауренів вважає священним.\n\nТи зробиш велику послугу, якщо вирушиш на Схід мороку й покладеш край цій навалі. Предки неодмінно будуть прихильні до тебе, якщо виконаєш це.", [3] = "Убийте 10 павучат і 5 павуків-солдатів Сходу мороку.", ["en"] = "Defending the Dead", ["tasks"] = { ["Gloomrise Hatchling"] = "Павуча Сходу мороку", ["Gloomrise Hatchling slain"] = "Павуча Сходу мороку: убито", ["Gloomrise Soldier"] = "Павук-солдат Сходу мороку", ["Gloomrise Soldier slain"] = "Павук-солдат Сходу мороку: убито" } },
    [96260] = { [1] = "Міцніше за сталь", [2] = "Чув, що сталося з кладовищем на Сході мороку? Велетенські павуки, чия отрута, подейкують, здатна пробуджувати мертвих, розплодилися, мов пожежа. Мерзенна справа, як на мене.\n\nОдин із розвідників, яких послали розібратися, повернувся напівмертвим і вкритим неймовірно міцним кристалічним павутинням. Я зібрав усе, що міг, але для подальшого вивчення мені дуже потрібні нові зразки.\n\nПринеси мені ще цього кристалічного павутиння, і я винагороджу тебе.", [3] = "Зберіть 3 пасма кристалічного павутиння з прядильників Сходу мороку.", ["en"] = "Stronger than Steel", ["tasks"] = { ["Crystalline Silk"] = "Кристалічний шовк" } },
    [96261] = { [1] = "Мати виводка", [2] = "Коли виникає така навала, як на Сході мороку, стрімке розмноження ворожих павуків часто спричиняє одна могутня матріархиня.\n\nЯкщо хочемо назавжди позбутися цих тварюк, треба знайти їхню праматір і вбити її. Вирушивши на Схід мороку, знайди й знищ матір виводка. Раджу взяти союзників і бути готовим до всього. Здається, це не звичайні павуки.", [3] = "Убийте матір виводка Валракс на Сході мороку.", ["en"] = "The Broodmother", ["tasks"] = { ["Broodmother Valraxx"] = "Мати виводка Валракс", ["Broodmother Valraxx slain"] = "Мати виводка Валракс: убито" } },
    [96294] = { [1] = "Похмура правда", [2] = "<Мати виводка, яку ви щойно вбили, виявилася зовсім не павуком, а нічною ельфійкою-друїдкою, що набула спотвореної звіриної подоби. Вас переповнюють запитання про природу й призначення павуків на Сході мороку.\n\nВи помічаєте записку, що визирає зі складок вбрання мертвої ельфійки. Можливо, цей документ відповість на деякі з ваших запитань.>", [3] = "Віднесіть лист, знайдений у матері виводка Валракс, Мулну Люті Землі на плато Небесного Вартового.", ["en"] = "A Darker Truth", ["tasks"] = { ["Bloody Parchment (Provided)"] = "Закривавлений пергамент (видано)" } },
    [964] = { [1] = "Фрагменти скелетів", [2] = "Ключ до Некроситету називається Скелетним Ключем. Він кується із залишків скелетів — точніше, з декількох — та укріплюється одним з найміцніших металів у відповідній формі. Тільки сила створіння, що може відкрити портал до Некроситету, змусить ключ працювати.\n\nАле почнемо з найважливішого, {ім'я}. Нам знадобляться фрагменти скелетів, щоб викувати ключ. Скелети з Андорала чудово підійдуть, хоча й ті, що знаходяться за стіною, теж згодяться.", [3] = "Принесіть 15 фрагментів скелетів аптекарю Дітерсу на Вал, в Західні Зачумлені землі.", [4] = "Вбивай якомога більше і частіше, {клас:к} — нам знадобиться чимала кількість фрагментів скелетів, щоб зробити зовнішню оболонку ключа. Його ж не дарма називають скелетним ключем.", [5] = "Так, вони підійдуть, {ім'я}! Тепер моя черга — я загартую фрагменти таким чином, щоб вони змогли витримати напружений процес кування, через який їм доведеться пройти.\n\nНаступний крок — знайти відповідну форму для відливання. Я знаю одного гобліна-коваля з Танаріса, який колись робив схожі форми. Він працює на того, на кого зазвичай і працюють гобліни — на того, хто більше платить.", ["en"] = "Skeletal Fragments", ["tasks"] = { ["Skeletal Fragments"] = "фрагменти скелетів", ["Skeletal Fragments (Provided)"] = "фрагменти скелетів (видано)" } },
    [96604] = { [1] = "На свіжому повітрі", [2] = "Вітаю, {клас}. Бачу, що у вас вигляд шукача пригод. Це добре. Світу потрібно більше нас, неспокійних душ, які прагнуть багатства та слави.\n\nТобі потрібно навчитися процвітати в дикій природі, щоб досягти успіху в цій сфері. Не впевнений, як у тебе справи з навичками активного відпочинку на природі, але я, мабуть, можу тебе дечому навчити, якщо ти схильний до навчання.\n\nСядьте біля вогню та влаштуйтеся зручніше. Я тобі все розповім.", [3] = "Сядьте біля Базового Багаття Бракка, набравши /sit у вікні чату, та зачекайте, поки отримаєте баф «Посилений відпочинок».", ["en"] = "The Great Outdoors", ["tasks"] = { ["Gain the Boosted Rest buff"] = "Отримайте бафф «Посилений відпочинок»", ["Use the /sit emote near the campfire"] = "Використайте емодзі /сидіти біля багаття" } },
    [96605] = { [1] = "На свіжому повітрі", [2] = "Вітаю, {клас}. Бачу, що у вас вигляд шукача пригод. Це добре. Світу потрібно більше нас, неспокійних душ, які прагнуть багатства та слави.\n\nТобі потрібно навчитися процвітати в дикій природі, щоб досягти успіху в цій сфері. Не впевнений, як у тебе справи з навичками активного відпочинку на природі, але я, мабуть, можу тебе дечому навчити, якщо ти схильний до навчання.\n\nСядьте біля вогню та влаштуйтеся зручніше. Я тобі все розповім.", [3] = "Сядьте біля базового багаття Каги, набравши /sit у вікні чату, і зачекайте, поки отримаєте баф «Посилений відпочинок».", ["en"] = "The Great Outdoors", ["tasks"] = { ["Gain the Boosted Rest buff"] = "Отримайте бафф «Посилений відпочинок»", ["Use the /sit emote near the campfire"] = "Використайте емодзі /сидіти біля багаття" } },
    [96607] = { [1] = "На свіжому повітрі", [2] = "Вітаю, {клас}. Бачу, що у вас вигляд шукача пригод. Це добре. Світу потрібно більше нас, неспокійних душ, які прагнуть багатства та слави.\n\nТобі потрібно навчитися процвітати в дикій природі, щоб досягти успіху в цій сфері. Не впевнений, як у тебе справи з навичками активного відпочинку на природі, але я, мабуть, можу тебе дечому навчити, якщо ти схильний до навчання.\n\nСядьте біля вогню та влаштуйтеся зручніше. Я тобі все розповім.", [3] = "Сядьте біля базового багаття Елеонори, набравши /sit у вікні чату, і зачекайте, поки отримаєте посилення відпочинку.", ["en"] = "The Great Outdoors", ["tasks"] = { ["Gain the Boosted Rest buff"] = "Отримайте бафф «Посилений відпочинок»", ["Use the /sit emote near the campfire"] = "Використайте емодзі /сидіти біля багаття" } },
    [9665] = { [1] = "Зміцнення нашої оборони", [2] = "Агенти відречених викрили плани Альянсу щодо створення нових форпостів у покинутих вежах по всій території Східних Зачумлених земель.\n\nНам вкрай важливо не дозволити їм закріпитись на наших східних кордонах, тому ми повинні запобігти цьому. Наші поточні плани полягають у тому, щоб вигнати їх з усіх захоплених ними веж, і розмістити там наші сили.", [3] = "Захопіть вежу Королівської варти, Східну вежу, вежу Північного ходу, і вежу Чумолісся у Східних Зачумлених землях, а потім поверніться до емісара Ґормока, близ Каплиці Надії Світла.", [4] = "Вони неймовірно дурні, якщо думають, що ми дозволимо їм розмістити пости так близько до однієї з наших столиць.\n\nМи будемо розбивати їх, доки вони не відступлять на південь.", [5] = "Це чудові новини, {ім'я}. Це буде нескінченна боротьба за Зачумлені землі, доки ми повністю не витіснимо сили Альянсу.\n\nТож я сподіваюся на твою подальшу допомогу.", ["en"] = "Bolstering Our Defenses", ["tasks"] = { ["Capture Crown Guard Tower"] = "Захоплення вежі Коронної варти", ["Capture Crown Guard Tower (Provided)"] = "Захоплення вежі Коронної варти (видано)", ["Capture Crown Guard Tower slain"] = "Захоплення вежі Коронної варти: убито", ["Capture Eastwall Tower"] = "Захоплення вежі Істволл", ["Capture Eastwall Tower (Provided)"] = "Захоплення вежі Істволл (видано)", ["Capture Eastwall Tower slain"] = "Захоплення вежі Істволл: убито", ["Capture Northpass Tower"] = "Захоплення вежі Нортпасс", ["Capture Northpass Tower (Provided)"] = "Захоплення вежі Нортпасс (видано)", ["Capture Northpass Tower slain"] = "Захоплення вежі Нортпасс: убито", ["Capture Plaguewood Tower"] = "Захоплення вежі Чумного лісу", ["Capture Plaguewood Tower (Provided)"] = "Захоплення вежі Чумного лісу (видано)", ["Capture Plaguewood Tower slain"] = "Захоплення вежі Чумного лісу: убито" } },
    [96652] = { [1] = "Шукач пригод", [2] = "<Щоденник виглядає досить простим, детально описує життя та пригоди когось, про кого ви ніколи не чули.\n\nЄ кілька записів, де згадується кемпінг. Здається, це досить... весело.>", [3] = "Принесіть щоденник Бракку біля пагорба Рейзор.", ["en"] = "The Adventurer", ["tasks"] = { ["Lost Journal"] = "Втрачений щоденник", ["Lost Journal (Provided)"] = "Втрачений щоденник (видано)" } },
    [96655] = { [1] = "Основи таборування: куховарство", [2] = "Отже, ви хочете дізнатися більше про кемпінг, га? Молодець, {клас}. Перший крок, який має зробити будь-який шукач пригод, — це стати кухарем і навчитися розводити багаття.\n\nКулінарія — це не просто приготування смачної їжі. Це також основа вашого табору.", [3] = "Поговоріть з кухарем Торкою в Рейзор-Гілл, щоб навчитися бути кухарем.", ["en"] = "Camping 101: Cooking", ["tasks"] = { ["Learn cooking from Cook Torka in Razor Hill"] = "Навчіться готувати у кухаря Торки в Рейзор-Гілл" } },
    [96656] = { [1] = "Шукач пригод", [2] = "{ім'я}, ти довела свою надійність у своїх зусиллях проти Червоного Хрестового Походу. Ось чому я зараз довіряю тобі незвичайне завдання.\n\nЯ чув про нову шукачку пригод неподалік, біля Брілл. Піди і подивись, що вона робить.", [3] = "Поговоріть з Елеонорою Шеклтон біля Брілла.", ["en"] = "The Adventurer" },
    [96658] = { [1] = "Основи таборування: куховарство", [2] = "Отже, ви хочете дізнатися більше про кемпінг, га? Молодець, {клас}. Перший крок, який має зробити будь-який шукач пригод, — це стати кухарем і навчитися розводити багаття.\n\nКулінарія — це не просто приготування смачної їжі. Це також основа вашого табору.", [3] = "Поговоріть з Вільямом Пікманом у Бріллі, щоб навчитися бути кухарем.", ["en"] = "Camping 101: Cooking", ["tasks"] = { ["Learn cooking from William Pickman in Brill"] = "Навчіться кулінарії у Вільяма Пікмана в Бріллі" } },
    [96659] = { [1] = "Шукач пригод", [2] = "Зачекай, {ім'я}. У мене є ще одне прохання до тебе, перш ніж ти нас покинеш.\n\nЄ шукачка пригод на ім'я Кага Дике Копито, яка розбила табір недалеко від села Криваве Копито. Вона дуже допомогла мені в минулому, і тепер я бачу свій шанс віддячити їй. Чи не міг би ти доставити їй ці припаси?", [3] = "Доставте збірку припасів Казі Дикому Копиту біля села Криваве Копито.", ["en"] = "The Adventurer", ["tasks"] = { ["Supply Bundle"] = "пакунок з припасами", ["Supply Bundle (Provided)"] = "пакунок з припасами (видано)" } },
    [96661] = { [1] = "Основи таборування: куховарство", [2] = "Отже, ви хочете дізнатися більше про кемпінг, га? Молодець, {клас}. Перший крок, який має зробити будь-який шукач пригод, — це стати кухарем і навчитися розводити багаття.\n\nКулінарія — це не просто приготування смачної їжі. Це також основа вашого табору.", [3] = "Поговоріть з Пайаллом Безмовною Ходою в селі Кривавих Копит, щоб навчитися бути кухарем.", ["en"] = "Camping 101: Cooking", ["tasks"] = { ["Learn cooking from Pyall Silentstride in Bloodhoof Village"] = "Навчіться готувати у Пайалла Безмовної Стриби в селі Криваве Копито" } },
    [96774] = { [1] = "Стародавній ідол Ґурубаші", [2] = "Давні Ґурубаші з Тернистої долини були майстрами темної магії крові. Подейкують, для цього лихого-лютого вуду вони використовували ідолів із чистого ясносрібла.\n\nСтарий Мазу'кон охоче прибрав би одного з тих ідолів до рук... виключно для науки, розумієш. Як щодо того, щоб зібрати друзів та влаштувати маленький грабунок у тому затонулому місті, яке стирчить з океану біля узбережжя Тернистої долини? Убий там найповажнішого на вигляд жерця, і в нього неодмінно знайдеться те, що я шукаю.", ["en"] = "Ancient Gurubashi Idol", ["tasks"] = { ["Ancient Gurubashi Idol"] = "Стародавній ідол Ґурубаші" } },
    [96821] = { [1] = "Легінгінг", [2] = "Ми бачимо все менше і менше мандрівників з Рейзор-Гілл. Скорпіди ніколи не були веселими, але тепер я чую, що павуки в'ють собі гнізда вздовж дороги.\n\nЯкщо ваші подорожі ведуть на північ, убийте кількох павуків по дорозі. Потім повідомте Рейзор-Гілл, що стежка для них трохи безпечніша.", [3] = "Убийте 6 Кріперів Ріджтін та 6 Прихистків Ріджтін у південному Дуротарі, а потім зверніться до Гар'тока в Рейзор-Гілл.", ["en"] = "Legging It", ["tasks"] = { ["Ridgeshade Creeper slain"] = "Ріджшейд-Кріпер: убито", ["Ridgeshade Lurker slain"] = "Прихований Ріджшейд: убито" } },
    [96822] = { [1] = "За честь", [2] = "Ми втратили багатьох хоробрих воїнів Орди, коли розграбували Тірагардський замок. Тепер, коли люди зміцнили руїни, ми не можемо зібрати їхні останки, щоб належним чином вшанувати їхню смерть.\n\nІдіть до руїн, що оточують замок, і пошукайте зброю, залишену нашими полеглими родичами. Ми виставимо її на почесному місці.", [3] = "Зберіть Бойову Сокиру Рейдера, Лук Рейдера та Щит Рейдера на околиці Тірагардського замку, а потім поверніть їх Турроку на Рейзор-Гілл.", ["en"] = "For Honor", ["tasks"] = { ["Raider's Battleaxe"] = "Бойова сокира рейдера", ["Raider's Bow"] = "Лук рейдера", ["Raider's Shield"] = "щит рейдера" } },
    [96825] = { [1] = "Цей фрукт може вкусити у відповідь", [2] = "Наші мисливці та рибалки приносять багато смачної їжі для наших військ, але рідко отримують солодкі ласощі.\n\nЯ бачив кактус, який дає колючі, смачні плоди. Але він росте лише на пагорбах на заході, де жалюгідні кабани розбивають свої табори. Пройдіть повз кабани та принесіть мені трохи цих плодів. І будьте обережні — плоди такі ж колючі, як і кабани!", [3] = "Кухар Торка з Рейзор-Гілл хоче, щоб ви зібрали 8 плодів опунції на землях Рейзормейн на захід від міста.", ["en"] = "This Fruit Could Bite Back", ["tasks"] = { ["Prickly Pear Fruit"] = "Плід опунції" } },
    [96873] = { [1] = "Біль у шиї", [2] = "Тролі на схід звідси втратили свою волю через чаклуна Залазана. Він використовує багато жорстокої магії, щоб контролювати розуми своїх в'язнів, але один з його улюблених трюків — змушувати їх носити кулони, загорнуті в злісні заклинання.\n\nПотренуйтеся в своїх чарівних навичках, знімаючи магію з цих кулонів, і принесіть мені результати. І не повісьте випадково один на шию, якщо ви цінуєте свою свободу!", [3] = "Пазула з села Сен'джін просить вас зібрати 3 Світлих Залишки. Світлий Залишок можна отримати, розчарувавши Закляті Підвіски, що випадають з тролів на Островах Відлуння.", ["en"] = "A Pain in the Neck", ["tasks"] = { ["Luminous Residue"] = "Світловий залишок" } },
    [96874] = { [1] = "Це Спинальна Сокира", [2] = "Ти бачив величезних звірів Громового Хребта? Я весь час думаю, що колючки на їхніх спинах ідеально підійдуть для виготовлення наконечника могутньої сокири. Сару засміявся, коли я йому розповів... але що він знає!?\n\nВ рамках твоїх уроків ковальської справи ти можеш мені допомогти! Принеси мені трохи цих колючок разом із шліфувальним камінням, щоб їх заточити.", [3] = "Уг'ток з Орґріммару хоче, щоб ви зібрали 5 вивітрюваних шипів у звірів у Громовому Хребті, а також 5 грубих шліфувальних каменів.", ["en"] = "This Is Spinal Axe", ["tasks"] = { ["Rough Grinding Stone"] = "грубий шліфувальний камінь", ["Weathered Spine"] = "Вивітрюваний хребет" } },
    [96875] = { [1] = "Звірі Громового Хребта", [2] = "Орґріммар постійно розширюється, {клас}. І коли пеонам потрібні шкури, щоб обшити стіни та дахи наших нових будівель, вони звертаються до мене!\n\nШкури ящірок у Громовому Хребті зазвичай занадто товсті для броні, але вони є чудовим будівельним матеріалом. Принесіть мені трохи їхніх шкур, а також кілька легших висушених шкур. Подивимося на вашу майстерність у роботі зі шкірою!", [3] = "Камарі з Орґріммару хоче, щоб ви зібрали 5 шкір грубої ящірки у звірів у Громовому Хребті, а також 2 шкір вицвілого світла.", ["en"] = "Beasts of Thunder Ridge", ["tasks"] = { ["Cured Light Hide"] = "оброблена легка шкура", ["Rough Lizard Hide"] = "Шорстка шкура ящірки" } },
    [96876] = { [1] = "Загублений пакет Укора", [2] = "На клапані пачки грубо вишитий напис «Укор».", [3] = "Поверніть зграю до Укора в південному Дуротарі.", ["en"] = "Ukor's Lost Pack", ["tasks"] = { ["Ukor's Lost Pack"] = "Загублений пакет Укора", ["Ukor's Lost Pack (Provided)"] = "Загублений пакет Укора (видано)" } },
    [96877] = { [1] = "Копито Халікора", [2] = "Величезне копито служить доказом вашої перемоги над могутньою ящіркою.", [3] = "Доставте копито Халікора до Орґріммара.", ["en"] = "Halikor's Hoof", ["tasks"] = { ["Halikor's Hoof"] = "Копито Халікора", ["Halikor's Hoof (Provided)"] = "Копито Халікора (видано)" } },
    [96895] = { [1] = "Срібний посланець", [2] = "Не впевнений, чи ви чули, але тут щойно пройшли два посланці Срібного Світанку. Я не проти Срібного Світанку, але мені також не подобається, що вони нишпорять по Тірісфалю без нагляду. Вони обидва були Відреклими... але це не робить мене менш нервовим.\n\nОдин з них щойно пройшов повз, прямуючи на південний схід. У тому напрямку на околицях міста нишпорить група культистів Бича. Якби ці двоє почули про них, немає сумнівів, що це привернуло б їхню увагу.", [3] = "Знайдіть члена Срібного Світанку біля входу до Підмістя.", ["en"] = "The Argent Emissary" },
    [96896] = { [1] = "Праведна справа", [2] = "Ми з Данітою боролися проти лиха, захищаючи Підмісто, коли Накшрамас напав. Того дня ми втратили багатьох добрих друзів, зокрема героя, на честь якого названо цю фортецю, — Гарека Бандаріона.\n\nМожливо, він був першим Відреклимся, хто знову відкрив для себе, як володіти світлом як паладин. Мене надихає бачити його спадщину та потенціал тут, з Данітою та її когортою.\n\nЯкби ж решта Відреклих відчували те саме...", [3] = "Зверніть увагу на розмову між Данітою Морр та Леонідом Варфаломієм Преподобним.", ["en"] = "A Righteous Cause" },
    [96897] = { [1] = "Культ проклятих", [2] = "Ця лихо — лихо для наших земель, а їхні живі слуги — найгірші з них. Народу Тірісфаля й так достатньо доводиться мати справу між бездумними мерцями та Багряним хрестовим походом. Якщо ви хочете зробити щось добре, допоможіть мені покласти край цій покидьці.", [3] = "Убийте 8 темних неофітів та 8 темних виконавців у Тірісфальських галявинах.", ["en"] = "The Cult of the Damned", ["tasks"] = { ["Dark Enforcer slain"] = "Темний Виконавець: убито", ["Dark Neophyte slain"] = "Темний неофіт: убито" } },
    [96898] = { [1] = "Залишки війни", [2] = "Нещодавно цитадель Наксрамаса напала на це місто, маючи намір стерти Відреклих з карти. І Відреклі, і Срібний Світанок втратили багато того дня, щоб забезпечити майбутнє Відреклих.\n\nПід час битви великий некротичний фокусуючий кристал, що висів під Наксрамасом, був розбитий, а його фрагменти розкидані по всій цій місцевості. Я підозрюю, що саме для цього тут і знаходяться культисти. Допоможіть мені повернути фрагменти та позбавити їх бича.", [3] = "Зберіть 12 уламків некротичних кристалів у Тірісфальських галявинах.", ["en"] = "Remnants of War", ["tasks"] = { ["Necrotic Crystal Fragment"] = "Фрагмент некротичного кристала" } },
    [96899] = { [1] = "Фортеця Бандаріон", [2] = "Ви зробили велику справу для справи Срібного Світанку сьогодні, і я вам дякую. Я не знаю, наскільки ви знайомі з фортецею Бандаріон, але ми з моїм командиром прямували туди, щоб зустрітися з паладинами, які там мешкають. Це було ще до того, як ми дізналися про присутність Культу Проклятих.\n\nЯкщо ви хочете дізнатися більше про Срібний Світанок та нашу місію, знайдіть мого командира в Бандаріонському фортеці, на північний захід звідси. Я залишуся тут, щоб прибрати решту цього безладу.", [3] = "Зустріньте Леоніда Варфаломія у фортеці Бандаріон у Тірісфальських галявинах.", ["en"] = "Bandarion Keep" },
    [96986] = { [1] = "Могильний лицар", [2] = "У надрах міста магів на півночі ховається зрадник нашого народу. Некромант із моторошним хистом. Він збирає військо нежиті просто під носом у Кірін-Тору.\n\nМені байдуже до долі міста магів, {ім'я}, але цей могильний лицар плює на все, за що стоїмо ми, відречені. Поклади йому край. Покажи: ніхто не сховається від Темної Пані.", [3] = "Здолайте Атрексіса Могильного Лицаря в Даларані для Мелісари з Млина Таррен.", ["en"] = "The Grave Knight", ["tasks"] = { ["Atrexis the Grave Knight"] = "Атрексіс Могильний Лицар", ["Atrexis the Grave Knight slain"] = "Атрексіс Могильний Лицар: убито" } },
    [96987] = { [1] = "Навчання з нагоди", [2] = "О, та це ж підприємець із таким самим мисленням! Потай пробираєшся в Даларан у такі скрутні часи? Ай-ай-ай.\n\nОце я розумію, {раса}!\n\nПоки наші друзі-маги зайняті, може, знайдемо собі трохи «загублених» скарбів. У них цілі бібліотеки присвячені хитромудрій арканічній магії. Якби ти приніс мені один із їхніх таємних фоліантів, я міг би продати його за добрі гроші. Прибуток поділимо.\n\nГей-гей, не дивися на мене так. Ти ж і сам тут не на екскурсії. То як, ти з нами?", ["en"] = "Opportunistic Education", ["tasks"] = { ["The Founding of Dalaran"] = "Заснування Даларана" } },
    [96988] = { [1] = "Джерело сили", [2] = "Даларан узяли в облогу його ж власні конструкції. Ідеальна нагода, скажімо так, позичити кілька зразків.\n\nУяви собі військо поганищ, живлених арканічною енергією. Темній Пані доведеться визнати мою алхімічну майстерність. Може, навіть призначить мене головою Королівського товариства аптекарів?\n\nВирушай у місто й знайди ядра конструкцій. Добровільно вони їх навряд чи віддадуть, тож роби що мусиш.", [3] = "Зберіть 6 тріснутих ядер вартових у Даларані для доктора Мартіна Фелбена в Підмісті.", ["en"] = "Source of Power", ["tasks"] = { ["Cracked Sentry Core"] = "Тріснуте ядро вартового" } },
    [97003] = { [1] = "Чол'арук Пожирач", [2] = "Ти там, {клас}. Мені потрібна твоя допомога. Ходять чутки про звіра, який влаштовує собі лігво глибоко в печері на Терновому пагорбі, на північний схід звідси. Острий Грив називає його Чол'арук або \"Пожирач\". Він нібито вп'ятеро більший за звичайного вепра з жагою крові, яку ніколи не можна вгамувати.\n\nБільшість не вірить цим казкам. Але я вірю, бо я вже бився з ним подібним раніше.\n\nЗнайди його лігво та вбий Чол'арука. Принеси мені його голову. Але попереджаю тебе: добре готуйся і не ходи сам.\n\nКров і грім, {клас}.", [3] = "Принесіть голову Чол'арука до Гур'ака в Степах.", ["en"] = "Chol'aruk the Ravener", ["tasks"] = { ["Chol'aruk's Head"] = "Голова Чол'арука" } },
    [97242] = { [1] = "Попурі Єлмака", [2] = "Єлмак не хоче, щоб його учень щось зламав. Ну, щось більше, ніж він уже зламав.\n\nВін сказав мені, що молодий майстер-практикант має забагато гордості, щоб просити про допомогу, коли вона йому справді потрібна. Єлмак хоче дати йому скуштувати певний домашній рецепт.\n\nЗберіть суміш живців рогозу та стручкової трави, взятих з рослин, що ростуть навколо води в Долині Честі. Я б приніс їх сам, але якби я вийшов з магазину, Вхуут точно б знав, що ми задовольняємо його настрій.", [3] = "Візьміть трохи живців рогозу та списоцвіту, що ростуть навколо водних потоків у Долині Честі, та поверніться до Кор'гельда в Алхімії та Зілля Єлмака.", ["en"] = "Yelmak's Medley", ["tasks"] = { ["Handful of Cattails"] = "Жменя рогозу", ["Speargrass Cuttings"] = "Живці коприволистої трави" } },
    [97243] = { [1] = "Поклик вогню", [2] = "Хоча ми й перебуваємо у царстві Небесної Стіни, це все ще стихійний план. Духи всіх чотирьох стихій говорять з нами, якщо ми зволимо їх послухати. Один серед нас, Вітроутворювачів, особливо налаштований на стихію вогню. Шен'дорай на ім'я Оларіан Швидкогорючий.\n\nПринесіть це йому до Святилища Полум'я в Низині Гастберрі. Ви знайдете його захованим на краю острова, на захід від Валанаара.", [3] = "Принесіть Смолоскип Сплячого Полум'я Оларіану Швидкоберну у Храм Полум'я в Низині Гастберрі.", ["en"] = "Call of Fire", ["tasks"] = { ["Torch of the Dormant Flame"] = "смолоскип дрімаючого полум'я", ["Torch of the Dormant Flame (Provided)"] = "смолоскип дрімаючого полум'я (видано)" } },
    [97244] = { [1] = "Поклик вогню", [2] = "Існує жрець Неба Ал'Акета на ім'я Фаладіель. Колись він був закликачем полум'я та стійким творцем вітру. Як і багато інших Ал'Акетів, він пожертвував своєю вірністю заради влади, і його руки тепер заплямовані кров'ю колишніх братів і сестер.\n\nВи знайдете жреця Неба Фаладіеля на фермі на північний схід за Валанааром, трохи південніше від Святилища Акіра. Убийте зрадника. Принесіть мені його серце. Це жахливе завдання, але воно потрібне для ритуалу, який ми маємо виконати.", [3] = "Убийте Небесного жерця Фаладіеля в Низині Гастберрі та зберіть Серце Фаладіеля.", ["en"] = "Call of Fire", ["tasks"] = { ["Faladiel's Heart"] = "Серце Фаладіеля" } },
    [97245] = { [1] = "Поклик вогню", [2] = "Мешканці Шен'дарського нагір'я розповідають про стародавнього лісового духа на ім'я Курамаа. Кажуть, що він живе всередині покрученого пня на вершині пагорба поблизу Якірного Пілона нагір'я.\n\nІдіть у нагір'я та знайдіть цей пень. Постукайте кулаком по корі, і з'явиться Курамаа. Переможіть духа в бою та принесіть мені його дерев'яну маску.\n\nОднак будьте обережні, ця сутність буде надзвичайно стійкою до більшої частини вашої магії. Лише дотик полум'я придушить духа.", [3] = "Знайдіть дім Курамаа у Шен'дарському нагір'ї та переможіть духа в бою. Після перемоги принесіть Маску Курамаа Оларіану Швидкогорючому у Гастберрі.", ["en"] = "Call of Fire", ["tasks"] = { ["Kuramaa's Mask"] = "Маска Курамаа" } },
    [97246] = { [1] = "Апеляція щодо страв", [2] = "Мій син, Мігі, завжди цілий день ходить гратися з друзями. Я кажу йому взяти обід у Борстана, але я знаю, що він майже ніколи цього не робить, бо повертається додому голодним. Ці діти думають, що їхні ігри важливіші за власні тіла!\n\nБудь ласка, зайди біля Вогнища Борстана і скажи йому, що ти прийшов доставити обід Мігі. Ти майже напевно знайдеш Мігі за Громмаш-Холдом з рештою його друзів.\n\nОбов'язки тримають мене тут протягом дня, і я не можу стежити за кожним його прийомом їжі.", [3] = "Відвідайте Вогнище Борстана та скажіть йому, що Татог хоче, щоб ви особисто доставили йому обід Мігі.", ["en"] = "Meal Appeal" },
    [97249] = { [1] = "Улюблена їжа", [2] = "Тепер, коли я знаю, що його батьки хвилюються про те, скільки він насправді наїдається, у мене є ідея.\n\nВони змусили мене пообіцяти не брати з собою одну й ту саму страву щодня, тому Мігі починає любити більше, ніж одну. Тим не менш, коли коптильня сита, і ми готуємо сендвічі з поросячим черевцем у солодкій глазурі, він завжди з'являється на обід. Ми почали кришити залишки хрусткої глазурі як начинку — щось, що ми можемо додавати щодня.\n\nВіднесіть це йому. Можливо, він почне приходити раніше і приводити друзів!", [3] = "Принесіть обід Мігі йому за форт Громмаш", ["en"] = "Favorite Food", ["tasks"] = { ["Migi's Lunch"] = "Обід у Мігі", ["Migi's Lunch (Provided)"] = "Обід у Мігі (видано)" } },
    [97250] = { [1] = "Неправильно звинувачений, справедливо виправлений", [2] = "Мандрівнику, ти плануєш вирушити до Пилових Болот? Я чув чутки, що кілька людських солдатів зайняли позиції на його кордоні та руйнують орієнтири, залишені нашими тауренами-слідопитами.\n\nХодять чутки, що улюблена таверна згоріла дотла, і, як це типово для Альянсу, вони одразу ж звинувачують Орду! Я не знаю, чи є в їхньому твердженні якась правда, але їхнє вторгнення на НАШУ землю не повинно мати місця.\n\nСпочатку вбий, потім розслідуй!", [3] = "Знищте солдатів Альянсу, які вторгаються в Степу на кордоні з Пиловими болотами, а потім поверніться до Грунта Логмара в табір Таураджо.", ["en"] = "Wrongly Blamed, Justly Corrected", ["tasks"] = { ["Encroaching Soldier slain"] = "Зазіхаючий солдат: убито", ["Outraged Pillager slain"] = "Обурений грабіжник: убито" } },
    [97257] = { [1] = "Поклик вогню", [2] = "Тепер ми виконаємо ритуал.\n\nЯ покладу матеріали на вівтар і покличу духів полум'я. Якщо жертву буде прийнято, вони з'являться та запалять Вічний вогонь. Потім ви триматимете свій смолоскип уперед і захопите полум'я.\n\nВіднесіть запалений смолоскип до Валанаару та помістіть його в жаровню Вічного вогню. Ви повинні зробити це швидко, бо полум'я Вогняних земель швидко розсіюється тут, у Небесній стіні.", [3] = "Зачекайте, поки Оларіан розпочне ритуал біля Жаровні Підношень, і виконайте його інструкції.\n\nВи повинні доставити Вічний Вогонь до Валанаару, перш ніж закінчиться час.", ["en"] = "Call of Fire", ["tasks"] = { ["Complete the Ritual with Olariaan"] = "Завершіть ритуал з Оларіаном", ["Light the Brazier of Eternal Flame"] = "Запаліть жаровню Вічного вогню", ["Torch of Eternal Flame"] = "Факел Вічного Вогню", ["Torch of Eternal Flame (Provided)"] = "Факел Вічного Вогню (видано)" } },
    [97275] = { [1] = "Який же пік?", [2] = "Хуут — вундеркінд. Це правда. Але йому ще бракує досвіду, мудрості та часу на міксері, щоб знати, як поважати алхімічні процеси.\n\nВін вичерпує всі найрідкісніші та найекзотичніші реагенти, які ми маємо, не зупиняючись на практику та вдосконалення своїх базових навичок.\n\nДай йому це зілля, яке я зварив швидким тонізуючим методом. Він перегляне все, що робить, коли дізнається, що місцеві засоби та обережний дотик — це перша справжня майстерність.", [3] = "Віддайте зілля Єлмака Вхууту.", ["en"] = "Whuut's the Rush", ["tasks"] = { ["Yelmak's Potion"] = "Зілля Єлмака", ["Yelmak's Potion (Provided)"] = "Зілля Єлмака (видано)" } },
    [97288] = { [1] = "Нескінченні муки", [2] = "<Коли істота падає, її голова відвалюється. Здається, ніби її кілька разів прикріплювали назад, і з кожним повторним з'єднанням зв'язок слабшає.\n\nХтось у Підмісті мав би знати більше про цю унікальну гидоту.>", [3] = "Доставте Гидку Голову комусь у Підмісті.", ["en"] = "Unending Torment", ["tasks"] = { ["Abominable Head"] = "Огидна Голова", ["Abominable Head (Provided)"] = "Огидна Голова (видано)", ["Deliver the Abominable Head to someone within the Undercity."] = "Доставте Гидку Голову комусь у Підмісті." } },
    [97289] = { [1] = "Нескінченні муки", [2] = "Ми постійно створюємо голови гидот, але ця особлива. Колись вона належала Великому Маршалу Альянсу. Особливо неприємній. Темна Леді мала задоволення сама її знищити.\n\nОх, які б таємниці вона могла розповісти, якби могла говорити. І вона може! Якщо ми знову прикріпимо її до відповідного носія.\n\nСміливо розмістіть її поруч із доступним тілом у сусідній кімнаті. Але не прикріплюйте її. Ще ні.", [3] = "Принесіть голову барона до тіла Отмара в Підмісті.", ["en"] = "Unending Torment", ["tasks"] = { ["Head of the Baron"] = "Голова барона", ["Head of the Baron (Provided)"] = "Голова барона (видано)" } },
    [97290] = { [1] = "Нескінченні муки", [2] = "Ти... гидота...\n\nЧому я маю... допомагати тобі...\n\nЗникни...", [3] = "Повідомте про свої знахідки Майстру-аптекарю Фаранеллу в Підмісті.", ["en"] = "Unending Torment" },
    [97291] = { [1] = "Нескінченні муки", [2] = "З прикріпленою головою нам залишилося лише прив'язати її до волі Темної Леді. Це не повинно бути проблемою. У звіра ледве залишився мозок після всіх отриманих побоїв.\n\nНам просто потрібно його мотивувати.\n\nПринесіть мені Отруйну Шлемницю від міс Грізетт у Торговому Кварталі. О, і трохи Пухнастої Трави від наших місцевих тренерів-травників, Зірок-Альє. Сміливо беріть трохи, вони мені винні. І нарешті трохи Есенції Агонії. Будь-який старий продавець отрути підійде.\n\nНам потрібно приготувати зілля!", [3] = "Зберіть Отруйну черепну шапку у Рудо-коричневої Грізетти в Торговому кварталі, Пухирчасту траву біля Тренера з травництва та Есенцію мук у продавця отрут у Кварталі Розбійників для Майстра-аптекаря Фаранелла в Підмісті.", ["en"] = "Unending Torment", ["tasks"] = { ["Blisterweed"] = "Пухирник", ["Essence of Agony"] = "сутність агонії", ["Toxic Skullcap"] = "Токсичний черепок" } },
    [97292] = { [1] = "Нескінченні муки", [2] = "Я приготував чудову сироватку, яку наш новий гість точно знайде досить... стимулюючою.\n\nВізьми це. Згодуй її в механізми, що капають згори. Подивимося, чи не зможемо ми показати йому, чому в його інтересах служити вірно.\n\nІ постарайся не впустити її. Я не можу дозволити собі нового помічника.", [3] = "Введіть Шиплячу сироватку в систему над тілом Отмара для Майстра-аптекаря Фаранелла.", ["en"] = "Unending Torment", ["tasks"] = { ["Hissing Serum"] = "Шипляча сироватка", ["Hissing Serum (Provided)"] = "Шипляча сироватка (видано)", ["Hissing Serum administered"] = "Введена шипляча сироватка" } },
    [97326] = { [1] = "Від скель до відпочинку", [2] = "Гей! У тебе є час нам допомогти! Я знаю, що маєш, це видно з твоєї посмішки, коли ми дивилися гру.\n\nЦе місце за фортом Громмаш гарне, бо там достатньо вільно, щоб ми могли розставити наші фігури. Але що погано, так це те, що у нас немає достатньо каміння для стільців чи столів.\n\nТи великий і сильний... як думаєш, міг би ти принести кілька каміння середнього розміру, достатньо гладеньких, щоб на них сидіти, якщо нам знадобиться відпочити?", [3] = "Поверніть 8 гладких валунів Тра за фортецею Громмаш.", ["en"] = "Rocks to Rests", ["tasks"] = { ["Smooth Boulder"] = "Гладкий валун" } },
    [97485] = { [1] = "Традиції Блаффа", [2] = "Благословення Ан'ше, друже.\n\nУ нас, тауренів, є традиція розкидати пахощі за вітром, і я сподівався, що ти зацікавишся шануванням цієї традиції.\n\nТобі потрібно буде виготовити пахощі, придбавши трави у Ніди, кедр у Нати, сухожилля у Маху на середині підйому, а церемоніальний кремінь і трут у Наала на верхньому підйомі. Як тільки у тебе будуть ці предмети, змішай їх і розклади їх біля південної скелі Мисливського підйому.\n\nТи знайдеш килимок і пахощі на місці церемоніального проведення.", [3] = "Купіть пучок трав у Ніди, травниці, пучок кедрових гілочок у Нати, чарівної постачальниці, сухожилля у Маху, постачальника шкіри, та церемоніальний кремінь і трут у Наала, постачальника кулінарних виробів.\n\nЗмішайте предмети та посипте ладаном Мисливську гору.", ["en"] = "Traditions of the Bluff", ["tasks"] = { ["Prepared Incense"] = "Підготовлений пахощ", ["Spread incense"] = "Розпорошити пахощі" } },
    [97538] = { [1] = "Пігменти для фарб", [2] = "Вітаю, друже. Чи можу я попросити тебе про послугу? У мене щойно закінчився червоний пігмент для фарб, і я шукаю когось із молодшими копитами, щоб здійснити довгу подорож у Кігті-Гори замість мене.\n\nПосеред гірського перевалу розташоване велике кругле озеро, озеро Миркфаллон, у водах якого росте унікальна рослина. Стручки цієї рослини, зворушки, стають яскраво-червоними після висихання. Збери стручки цієї рослини для мене, і я щедро винагороджу тебе за твої зусилля.", [3] = "Та Зимове Копито у Громовій Утесі хоче 30 стручків Лихоросу з озера Лихопаллон.", ["en"] = "Pigments for Paints", ["tasks"] = { ["Mirkweed Pods"] = "Стручки лихоцвіту" } },
    [97539] = { [1] = "Шовкові шви", [2] = "Цей табір кинули напризволяще. Пошкодження від облоги так і не відремонтовано, наче занедбаність тут стала правилом. У своєму лазареті я такого не допущу. Він під моїм керівництвом, і я подбаю, щоб він працював.\n\nПрипаси майже скінчилися. Мені потрібно більше матеріалів — досить, щоб робітники й вартові трималися на ногах.\n\nУ скрутних умовах зі скрученого павутиння можна зробити досить ефективну нитку для польових швів.\n\n{клас:к}, принеси мені павутиння павуків, що полюють у цьому нагір'ї.", [3] = "Принесіть 12 хірургічних павутинних ниток лікарю Грегорі Віктору в Молотобій у нагір'ї Араті.", ["en"] = "Silky Sutures", ["tasks"] = { ["Surgical Spidersilk"] = "Хірургічний павучий шовк" } },
    [97583] = { [1] = "ВИКОРИСТОВУВАТИСЯ.", [2] = "<Маленький слизняк виглядає задоволеним і намагається відтворити ваші рухи, поки ви танцюєте. Однак він починає виглядати втомленим.\n\nМаленький слизняк зависає над невеликою кількістю мулу та поглинає його, виглядаючи трохи омолодженим.\n\nЗдається, всі ці танці вичерпали його. Можливо, хтось у каналах Підмістя продає більше цього поживного мулу?>", ["en"] = "WRIGGLE.", ["tasks"] = { ["Nutritious Slime Sludge"] = "Поживний слизовий мул" } },
    [97891] = { [1] = "Швидкий роздавач зілля", [2] = "Ти! Швидко, мені потрібно, щоб ти переніс це зілля через слизовий канал доктору Мартіну Фельбену в аптекаріум!\n\nВоно має дуже обмежений термін придатності, і ні, я не можу піти сам, мої коліна тремтять і підкошуються, якщо я спробую втекти.\n\nМабуть, це ще один чудовий побічний ефект нежиті.\n\nАле ми марнуємо час! Ось, бери це та йди!\n\n<Алессандро робить жест, що штовхає.>", [3] = "Принесіть Нестабільне Зілля Доктору Мартіну Фельбену в Аптекаріум протягом відведеного часу.\n\nНаданий предмет:", ["en"] = "Prompt Potion Runner", ["tasks"] = { ["Speak to Doctor Martin Felben"] = "Поговоріть з доктором Мартіном Фельбеном" } },
    [97899] = { [1] = "Кемпінг 101: Алхімія", [2] = "Отже, ти вирішив варити зілля та напої як Алхімік. Я впевнений, що це стане тобі в пригоді в подорожах.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити Колодязь Мани для твого табору. Збудуй один з них, і всі цілителі та чарівники збігатимуться, щоб насолодитися освіжаючим смаком.", [3] = "Поговоріть з Вхуутом в Орґріммарі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Alchemy", ["tasks"] = { ["Raise your alchemy skill to 20"] = "Підвищте свою навичку алхімії до 20" } },
    [97900] = { [1] = "Кемпінг 101: Ковальська справа", [2] = "Отже, ви стали ковалем. Це чудовий вибір, якщо ви хочете бути впевнені, що ваші клинки ніколи не затупляться.\n\nГадаю, я знаю когось, хто може допомогти вам у цьому, навчивши вас, як виготовити точильне колесо. Принесіть одне з них у свій табір, і всі воїни та розбійники в окрузі вишикуються в чергу, щоб відточити свою зброю.", [3] = "Поговоріть із Двуком у Рейзор-Гілл, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Blacksmithing", ["tasks"] = { ["Raise your blacksmithing skill to 20"] = "Підвищіть навичку ковальства до 20" } },
    [97901] = { [1] = "Кемпінг 101: Чарівний", [2] = "Чарівники роблять усе кращим і завжди раді бачити їх у будь-якому таборі в дикій природі.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Зачаровану лютню для вашого табору. Так важливо знаходити розваги під час відпочинку, і ця частинка магії може допомогти вам бути готовими до всіляких випробувань, коли ви знову вирушите на стару запилену стежку.", [3] = "Поговоріть з Джагом в Орґріммарі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Enchanting", ["tasks"] = { ["Raise your enchanting skill to 20"] = "Підвищте свою майстерність зачарування до 20" } },
    [97902] = { [1] = "Кемпінг 101: Інженерія", [2] = "Такі інженери, як ви, можуть створювати всілякі штуки, ботів та бомби для розваги та прибутку.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Бота-Реагента для вашого табору. Цей корисний автомат може допомогти вам добре постачатися, щоб у вас та ваших союзників ніколи не закінчувалися матеріали, необхідні для підживлення ваших заклинань.", [3] = "Поговоріть з Мукдраком на Рейзор-Гілл, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Engineering", ["tasks"] = { ["Raise your engineering skill to 20"] = "Підвищте свій інженерний рівень до 20" } },
    [97903] = { [1] = "Кемпінг 101: Перша допомога", [2] = "Отже, ви почали навчатися наданню першої допомоги? Це почесне... і прагматичне прагнення як {клас}.\n\nГадаю, я знаю когось, хто може навчити вас, як створити аптечку першої допомоги для вашого табору. Травми — це реальність у світі пригод, і пропонування так необхідного лікування у вашому таборі може навіть врятувати життя.", [3] = "Поговоріть з Рорком у Рейзор-Гілл, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: First Aid", ["tasks"] = { ["Raise your first aid skill to 20"] = "Підвищіть навичку першої допомоги до 20" } },
    [97904] = { [1] = "Кемпінг 101: Риболовля", [2] = "Можливо, ви так не думаєте, але ваші навички рибалки можуть стати в нагоді в таборі.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити акваріум для вашого табору. Ви можете використовувати цей інструмент, щоб подарувати трохи радості собі та своїм товаришам-шукачам пригод. Щасливий шукач пригод – це сильний шукач пригод, і я впевнений, що ваші бойові здібності це відображатимуть.", [3] = "Поговоріть з Лау'Тікі біля села Сен'джін, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Fishing", ["tasks"] = { ["Raise your fishing skill to 20"] = "Підвищте свій рівень риболовлі до 20" } },
    [97905] = { [1] = "Кемпінг 101: Трав'ярство", [2] = "Мені здається, ти набув певних навичок у травництві. Збирання квітів — це не просто для розваг, знаєш. Це може бути корисним... і прибутковим.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити ароматичну свічку для твого табору. Піднесений дух — ключовий компонент для підтримки цілителів та заклинателів у бою, а ароматична свічка може дати підкріплення, яке маги точно оцінять.", [3] = "Поговоріть з Джанді в Орґріммарі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Herbalism", ["tasks"] = { ["Raise your herbalism skill to 20"] = "Підвищте свій рівень навичок травництва до 20" } },
    [97906] = { [1] = "Кемпінг 101: Шкіряна справа", [2] = "Ти став шкіряником. Молодець, {клас}. Гадаю, я знаю когось, хто може навчити тебе, як зробити собі намет, у якому буде прохолодно в спекотні дні та сухо в дощові.\n\nЗ гарним наметом над головою ти гарантовано отримаєш весь необхідний відпочинок, щоб залишатися бадьорим під час подорожей.", [3] = "Поговоріть з Каролеком в Орґріммарі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Leatherworking", ["tasks"] = { ["Raise your leatherworking skill to 20"] = "Підвищте свою майстерність обробки шкіри до 20" } },
    [97907] = { [1] = "Основи таборування: гірництво", [2] = "Гірничодобувна справа — не найгламурніше, але це гарна чесна робота та чудова професія, яку варто досліджувати.\n\nГадаю, я знаю когось, хто може навчити тебе виготовляти магніт для твого табору. Збудуй один з них, і кожен, хто хоче розмахувати мечем, захоче зібратися навколо твого вогнища та насолодитися його додатковою «силою», щоб підвищити свою бойову майстерність.", [3] = "Поговоріть з Кранном у Рейзор-Гілл, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Mining", ["tasks"] = { ["Raise your mining skill to 20"] = "Підвищте свій рівень майнінгу до 20" } },
    [97908] = { [1] = "Кемпінг 101: Зняття шкури", [2] = "Вміння вміло збирати шкури та шкури полеглих звірів – одна з найцінніших навичок, якими може володіти шукач пригод.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити похідне крісло для вашого табору. Іноді важливо просто розслабитися, і ви можете використати деякі з цих зібраних шкур, щоб зробити зручне крісло. Трохи відпочинку може допомогти вам бути у найкращій формі та вдарити там, де це потрібно, наступного разу, коли ви опинитеся в запиленій хаосі.", [3] = "Поговоріть з Тудом в Орґріммарі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Skinning", ["tasks"] = { ["Raise your skinning skill to 20"] = "Підвищте свою навичку зняття шкури до 20" } },
    [97927] = { [1] = "Кемпінг 101: Алхімія", [2] = "Отже, ти вирішив варити зілля та напої як Алхімік. Я впевнений, що це стане тобі в пригоді в подорожах.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити Колодязь Мани для твого табору. Збудуй один з них, і всі цілителі та чарівники збігатимуться, щоб насолодитися освіжаючим смаком.", [3] = "Поговоріть з Креєм у Громовій Утепі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Alchemy", ["tasks"] = { ["Raise your alchemy skill to 20"] = "Підвищте свою навичку алхімії до 20" } },
    [97928] = { [1] = "Кемпінг 101: Ковальська справа", [2] = "Отже, ви стали ковалем. Це чудовий вибір, якщо ви хочете бути впевнені, що ваші клинки ніколи не затупляться.\n\nГадаю, я знаю когось, хто може допомогти вам у цьому, навчивши вас, як виготовити точильне колесо. Принесіть одне з них у свій табір, і всі воїни та розбійники в окрузі вишикуються в чергу, щоб відточити свою зброю.", [3] = "Поговоріть з Трагом Кам'яне Копитом у Громовій Утепі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Blacksmithing", ["tasks"] = { ["Raise your blacksmithing skill to 20"] = "Підвищіть навичку ковальства до 20" } },
    [97929] = { [1] = "Кемпінг 101: Чарівний", [2] = "Чарівники роблять усе кращим і завжди раді бачити їх у будь-якому таборі в дикій природі.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Зачаровану лютню для вашого табору. Так важливо знаходити розваги під час відпочинку, і ця частинка магії може допомогти вам бути готовими до всіляких випробувань, коли ви знову вирушите на стару запилену стежку.", ["en"] = "Camping 101: Enchanting", ["tasks"] = { ["Raise your enchanting skill to 20"] = "Підвищте свою майстерність зачарування до 20" } },
    [97930] = { [1] = "Кемпінг 101: Інженерія", [2] = "Такі інженери, як ви, можуть створювати всілякі штуки, ботів та бомби для розваги та прибутку.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Бота-Реагента для вашого табору. Цей корисний автомат може допомогти вам добре постачатися, щоб у вас та ваших союзників ніколи не закінчувалися матеріали, необхідні для підживлення ваших заклинань.", ["en"] = "Camping 101: Engineering", ["tasks"] = { ["Raise your engineering skill to 20"] = "Підвищте свій інженерний рівень до 20" } },
    [97931] = { [1] = "Кемпінг 101: Перша допомога", [2] = "Отже, ви почали навчатися наданню першої допомоги? Це почесне... і прагматичне прагнення як {клас}.\n\nГадаю, я знаю когось, хто може навчити вас, як створити аптечку першої допомоги для вашого табору. Травми — це реальність у світі пригод, і пропонування так необхідного лікування у вашому таборі може навіть врятувати життя.", [3] = "Поговоріть з Вірою Янгхуф у селі Криваве Копито, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: First Aid", ["tasks"] = { ["Raise your first aid skill to 20"] = "Підвищіть навичку першої допомоги до 20" } },
    [97932] = { [1] = "Кемпінг 101: Риболовля", [2] = "Можливо, ви так не думаєте, але ваші навички рибалки можуть стати в нагоді в таборі.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити акваріум для вашого табору. Ви можете використовувати цей інструмент, щоб подарувати трохи радості собі та своїм товаришам-шукачам пригод. Щасливий шукач пригод – це сильний шукач пригод, і я впевнений, що ваші бойові здібності це відображатимуть.", [3] = "Поговоріть з Утаном Стіллвотером у селі Криваве Копито, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Fishing", ["tasks"] = { ["Raise your fishing skill to 20"] = "Підвищте свій рівень риболовлі до 20" } },
    [97933] = { [1] = "Кемпінг 101: Трав'ярство", [2] = "Мені здається, ти набув певних навичок у травництві. Збирання квітів — це не просто для розваг, знаєш. Це може бути корисним... і прибутковим.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити ароматичну свічку для твого табору. Піднесений дух — ключовий компонент для підтримки цілителів та заклинателів у бою, а ароматична свічка може дати підкріплення, яке маги точно оцінять.", [3] = "Поговоріть з Коміном Зимовим Копитом у Громовій Утесі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Herbalism", ["tasks"] = { ["Raise your herbalism skill to 20"] = "Підвищте свій рівень навичок травництва до 20" } },
    [97934] = { [1] = "Кемпінг 101: Шкіряна справа", [2] = "Ти став шкіряником. Молодець, {клас}. Гадаю, я знаю когось, хто може навчити тебе, як зробити собі намет, у якому буде прохолодно в спекотні дні та сухо в дощові.\n\nЗ гарним наметом над головою ти гарантовано отримаєш весь необхідний відпочинок, щоб залишатися бадьорим під час подорожей.", [3] = "Поговоріть з Чоу Міцною Шкірою в Селі Кривавих Копит, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Leatherworking", ["tasks"] = { ["Raise your leatherworking skill to 20"] = "Підвищте свою майстерність обробки шкіри до 20" } },
    [97935] = { [1] = "Основи таборування: гірництво", [2] = "Гірничодобувна справа — не найгламурніше, але це гарна чесна робота та чудова професія, яку варто досліджувати.\n\nГадаю, я знаю когось, хто може навчити тебе виготовляти магніт для твого табору. Збудуй один з них, і кожен, хто хоче розмахувати мечем, захоче зібратися навколо твого вогнища та насолодитися його додатковою «силою», щоб підвищити свою бойову майстерність.", [3] = "Поговоріть з Бреком Кам'яне Копитом у Громовій Утепі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Mining", ["tasks"] = { ["Raise your mining skill to 20"] = "Підвищте свій рівень майнінгу до 20" } },
    [97936] = { [1] = "Кемпінг 101: Зняття шкури", [2] = "Вміння вміло збирати шкури та шкури полеглих звірів – одна з найцінніших навичок, якими може володіти шукач пригод.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити похідне крісло для вашого табору. Іноді важливо просто розслабитися, і ви можете використати деякі з цих зібраних шкур, щоб зробити зручне крісло. Трохи відпочинку може допомогти вам бути у найкращій формі та вдарити там, де це потрібно, наступного разу, коли ви опинитеся в запиленій хаосі.", [3] = "Поговоріть з Йонном Діпкат у селі Кривавих Копит, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Skinning", ["tasks"] = { ["Raise your skinning skill to 20"] = "Підвищте свою навичку зняття шкури до 20" } },
    [97937] = { [1] = "Кемпінг 101: Кравецька справа", [2] = "Кравецька справа — це напрочуд потужна навичка, в яку варто інвестувати, і я впевнений, що вона вам добре послужить.\n\nЯ знаю людину, яка може навчити вас, як створити прапор фракції для вашого табору, за умови, що у вас є для цього відповідні навички. Натхнення та моральний дух є ключовими складовими успіху на будь-якому полі бою, а натхненний прапор може значною мірою зарядити вас енергією.", ["en"] = "Camping 101: Tailoring", ["tasks"] = { ["Raise your tailoring skill to 20"] = "Підвищте свою кравецьку майстерність до 20" } },
    [97951] = { [1] = "Кемпінг 101: Алхімія", [2] = "Отже, ти вирішив варити зілля та напої як Алхімік. Я впевнений, що це стане тобі в пригоді в подорожах.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити Колодязь Мани для твого табору. Збудуй один з них, і всі цілителі та чарівники збігатимуться, щоб насолодитися освіжаючим смаком.", [3] = "Поговоріть з Керолай Аніс у Бріллі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Alchemy", ["tasks"] = { ["Raise your alchemy skill to 20"] = "Підвищте свою навичку алхімії до 20" } },
    [97952] = { [1] = "Кемпінг 101: Ковальська справа", [2] = "Отже, ви стали ковалем. Це чудовий вибір, якщо ви хочете бути впевнені, що ваші клинки ніколи не затупляться.\n\nГадаю, я знаю когось, хто може допомогти вам у цьому, навчивши вас, як виготовити точильне колесо. Принесіть одне з них у свій табір, і всі воїни та розбійники в окрузі вишикуються в чергу, щоб відточити свою зброю.", [3] = "Поговоріть з Безілом Фраєм в Підмісті, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Blacksmithing", ["tasks"] = { ["Raise your blacksmithing skill to 20"] = "Підвищіть навичку ковальства до 20" } },
    [97953] = { [1] = "Кемпінг 101: Чарівний", [2] = "Чарівники роблять усе кращим і завжди раді бачити їх у будь-якому таборі в дикій природі.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Зачаровану лютню для вашого табору. Так важливо знаходити розваги під час відпочинку, і ця частинка магії може допомогти вам бути готовими до всіляких випробувань, коли ви знову вирушите на стару запилену стежку.", [3] = "Поговоріть з Венсом Андерглумом у Бріллі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Enchanting", ["tasks"] = { ["Raise your enchanting skill to 20"] = "Підвищте свою майстерність зачарування до 20" } },
    [97954] = { [1] = "Кемпінг 101: Інженерія", [2] = "Такі інженери, як ви, можуть створювати всілякі штуки, ботів та бомби для розваги та прибутку.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Бота-Реагента для вашого табору. Цей корисний автомат може допомогти вам добре постачатися, щоб у вас та ваших союзників ніколи не закінчувалися матеріали, необхідні для підживлення ваших заклинань.", [3] = "Поговоріть з Гремом Ван Таленом в Підмісті, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Engineering", ["tasks"] = { ["Raise your engineering skill to 20"] = "Підвищте свій інженерний рівень до 20" } },
    [97955] = { [1] = "Кемпінг 101: Перша допомога", [2] = "Отже, ви почали навчатися наданню першої допомоги? Це почесне... і прагматичне прагнення як {клас}.\n\nГадаю, я знаю когось, хто може навчити вас, як створити аптечку першої допомоги для вашого табору. Травми — це реальність у світі пригод, і пропонування так необхідного лікування у вашому таборі може навіть врятувати життя.", [3] = "Поговоріть з медсестрою Нілою в Бріллі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: First Aid", ["tasks"] = { ["Raise your first aid skill to 20"] = "Підвищіть навичку першої допомоги до 20" } },
    [97956] = { [1] = "Кемпінг 101: Риболовля", [2] = "Можливо, ви так не думаєте, але ваші навички рибалки можуть стати в нагоді в таборі.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити акваріум для вашого табору. Ви можете використовувати цей інструмент, щоб подарувати трохи радості собі та своїм товаришам-шукачам пригод. Щасливий шукач пригод – це сильний шукач пригод, і я впевнений, що ваші бойові здібності це відображатимуть.", [3] = "Поговоріть з Клайдом Келленом у Бріллі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Fishing", ["tasks"] = { ["Raise your fishing skill to 20"] = "Підвищте свій рівень риболовлі до 20" } },
    [97957] = { [1] = "Кемпінг 101: Трав'ярство", [2] = "Мені здається, ти набув певних навичок у травництві. Збирання квітів — це не просто для розваг, знаєш. Це може бути корисним... і прибутковим.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити ароматичну свічку для твого табору. Піднесений дух — ключовий компонент для підтримки цілителів та заклинателів у бою, а ароматична свічка може дати підкріплення, яке маги точно оцінять.", [3] = "Поговоріть з Фарузою в Бріллі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Herbalism", ["tasks"] = { ["Raise your herbalism skill to 20"] = "Підвищте свій рівень навичок травництва до 20" } },
    [97958] = { [1] = "Кемпінг 101: Шкіряна справа", [2] = "Ти став шкіряником. Молодець, {клас}. Гадаю, я знаю когось, хто може навчити тебе, як зробити собі намет, у якому буде прохолодно в спекотні дні та сухо в дощові.\n\nЗ гарним наметом над головою ти гарантовано отримаєш весь необхідний відпочинок, щоб залишатися бадьорим під час подорожей.", [3] = "Поговоріть з Шелін Робарт дорогою до Підмістя з Брілла, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Leatherworking", ["tasks"] = { ["Raise your leatherworking skill to 20"] = "Підвищте свою майстерність обробки шкіри до 20" } },
    [97959] = { [1] = "Основи таборування: гірництво", [2] = "Гірничодобувна справа — не найгламурніше, але це гарна чесна робота та чудова професія, яку варто досліджувати.\n\nГадаю, я знаю когось, хто може навчити тебе виготовляти магніт для твого табору. Збудуй один з них, і кожен, хто хоче розмахувати мечем, захоче зібратися навколо твого вогнища та насолодитися його додатковою «силою», щоб підвищити свою бойову майстерність.", [3] = "Поговоріть з Бромом Кілліаном в Підмісті, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Mining", ["tasks"] = { ["Raise your mining skill to 20"] = "Підвищте свій рівень майнінгу до 20" } },
    [97960] = { [1] = "Кемпінг 101: Зняття шкури", [2] = "Вміння вміло збирати шкури та шкури полеглих звірів – одна з найцінніших навичок, якими може володіти шукач пригод.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити похідне крісло для вашого табору. Іноді важливо просто розслабитися, і ви можете використати деякі з цих зібраних шкур, щоб зробити зручне крісло. Трохи відпочинку може допомогти вам бути у найкращій формі та вдарити там, де це потрібно, наступного разу, коли ви опинитеся в запиленій хаосі.", [3] = "Поговоріть з Рендом Робартом дорогою до Підмістя з Брілла, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Skinning", ["tasks"] = { ["Raise your skinning skill to 20"] = "Підвищте свою навичку зняття шкури до 20" } },
    [97961] = { [1] = "Кемпінг 101: Кравецька справа", [2] = "Кравецька справа — це напрочуд потужна навичка, в яку варто інвестувати, і я впевнений, що вона вам добре послужить.\n\nЯ знаю людину, яка може навчити вас, як створити прапор фракції для вашого табору, за умови, що у вас є для цього відповідні навички. Натхнення та моральний дух є ключовими складовими успіху на будь-якому полі бою, а натхненний прапор може значною мірою зарядити вас енергією.", [3] = "Поговоріть з Боуеном Брісбойзом дорогою до Брілла з Дедкнелла, щоб навчитися створювати кемпінговий предмет для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Tailoring", ["tasks"] = { ["Raise your tailoring skill to 20"] = "Підвищте свою кравецьку майстерність до 20" } },
    [97972] = { [1] = "Кемпінг 101: Кравецька справа", [2] = "Кравецька справа — це напрочуд потужна навичка, в яку варто інвестувати, і я впевнений, що вона вам добре послужить.\n\nЯ знаю людину, яка може навчити вас, як створити прапор фракції для вашого табору, за умови, що у вас є для цього відповідні навички. Натхнення та моральний дух є ключовими складовими успіху на будь-якому полі бою, а натхненний прапор може значною мірою зарядити вас енергією.", [3] = "Поговоріть з Талін Мерехтрід у селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Tailoring", ["tasks"] = { ["Raise your tailoring skill to 20"] = "Підвищте свою кравецьку майстерність до 20" } },
    [97985] = { [1] = "Громові серця", [2] = "Дивовижні, правда? Я вперше отримав доступ до таємниць створення поганищ.\n\nЯ вивчав ці нотатки, і, схоже, нам потрібне серце. Величезне!\n\nКажуть, у Тисячі Шипів уздовж краю каньйону бродить велетенська громова ящірка на ім'я Буресерце. Із таким ім'ям вона мусить мати ідеальне серце. Воно мені потрібне!\n\nО, і раджу взяти друзів. Буресерце не славиться лагідністю.", [3] = "Убийте Буресерця в Тисячі Шипів і здобудьте його серце.", ["en"] = "Thundering Hearts", ["tasks"] = { ["Stormheart's Still-beating Heart"] = "Серце Буресерця, що досі б'ється" } },
    [98024] = { [1] = "Подорож до Перехрестя", [2] = "Після подорожі сюди з елементального плану, проблеми, з якими стикаються наші землі, можуть здатися незначними. Будьте певні, небезпеки, з якими стикається орда, цілком реальні, і ви станете грізними, якщо переживете свою службу.\n\nЯкщо ви хочете почати робити щось добро в нашому світі, вирушайте на південний захід до неосяжних земель, відомих як Степу. Там є поселення, відоме як Перехрестя. Горді мешканці завжди потребують допомоги.\n\nІди з честю, шукачу пригод!", [3] = "Зверніться до Торка на Перехрестя в Степах.", ["en"] = "Journey to the Crossroads" },
    [98069] = { [1] = "Викрадені припаси Розкутого Вітру", [2] = "Кляті гарпії! Вони напали на останній караван, який я відправила з припасами до застави Розкутого Вітру. Поки що нам усього вистачає, але без поповнення запаси невдовзі скінчаться.\n\nНе знаю, що гарпії планують робити з цими припасами, але буду вдячна, якщо повернеш їх мені. Їхнє лігво на захід звідси. Знайдеш їх і біля підніжжя скелі, і в печері на її вершині.", [3] = "Принесіть 8 викрадених припасів Розкутого Вітру Джандії на заставу Розкутого Вітру.", ["en"] = "Stolen Freewind Supplies", ["tasks"] = { ["Stolen Freewind Supplies"] = "Вкрадені припаси Вільного Вітру" } },
    [98070] = { [1] = "Припинити вереск", [2] = "У Верескливому каньйоні живе зграя гарпій, відомих своєю люттю та набігами. Вони напали із засідки на кілька останніх караванів із припасами, які наважилися пройти цими місцями.\n\nБоюся, якщо нічого не зробити, незабаром жоден караван не наважиться йти до застави Розкутого Вітру.\n\nІди й убий якнайбільше цих гарпій. Коли впораєшся, повернися до мене, і я щедро винагороджу твої зусилля.", [3] = "Убийте 5 крикнявих гарпій, 5 крикнявих оперених пройдисвіток і 5 крикнявих вітрозовок.", ["en"] = "Stop the Screeching", ["tasks"] = { ["Screeching Harpy"] = "Крикнява гарпія", ["Screeching Harpy slain"] = "Крикнява гарпія: убито", ["Screeching Roguefeather"] = "Крикнява оперена пройдисвітка", ["Screeching Roguefeather slain"] = "Крикнява оперена пройдисвітка: убито", ["Screeching Windcaller"] = "Крикнява вітрозовка", ["Screeching Windcaller slain"] = "Крикнява вітрозовка: убито" } },
    [98093] = { [1] = "Поле для очищення", [2] = "Я так рада, що ти мене побачив!\n\nСьогодні вранці погода була чудова, тому я пішов з табору Таураджо золотою дорогою. Коли настав час повертатися назад, я не зміг — зграя гієн почала кружляти навколо, а ящірки Бурехливої Шкіри заблокували мій єдиний шлях до порятунку.\n\nЯ видерся на це дерево, і тепер навколо о цій порі забагато ворогів, щоб я міг бігти додому через поля.\n\nНе міг би ти позбутися цих переслідувачів Бурехливої Шкіри та Хекльфанга?", [3] = "Сульхаса з південного Степу хоче, щоб ви знищили 7 ящірок Бурехливих та 7 переслідувачів-Чарівників у цьому районі, щоб вона могла безпечно покинути дерево.", ["en"] = "Field to Clear", ["tasks"] = { ["Hecklefang Stalker slain"] = "бісозубий ловець: убито", ["Stormhide slain"] = "бурешкур: убито" } },
    [98094] = { [1] = "Підтримка скаутів", [2] = "Тепер, коли ми можемо довірити тобі доставку важливої інформації нашим передовим шпигунам, для тебе є додаткове завдання.\n\nДостав це Смертелю Масою майже прямо на південь від нас. Він матиме для тебе більше справ, як тільки ти туди доберешся і передаси це йому. Він розміщений на височині на північ від гнилого виноградника, який вони називають Нетандер Стед.\n\nНаш план взяти під контроль ці землі невпинно продовжується.", ["en"] = "Scout Support", ["tasks"] = { ["Darthalia's Orders"] = "Накази Дарталії", ["Darthalia's Orders (Provided)"] = "Накази Дарталії (видано)" } },
    [98095] = { [1] = "Цінні переваги", [2] = "Наше вище командування вводить стратегічні війська, використовуючи вершників на кажанах. Ключові точки навколо передгір'їв втратили свої сигнальні маяки.\n\nВізьміть ці флакони. Відкоркуйте їх у трьох місцях: пагорби, що межують з Дун-Гароком, плато з видом на фортецю Дунголд, і останній на хребті мису над містом Гіллсбрад. Випари, що виходять, будуть як потужний налаштування для чуття кажана, знову притягуючи його до бажаних точок висадки.\n\nШукайте роздавлені порожні флакони та оновлюйте наші позначки.", ["en"] = "Valuable Vantages", ["tasks"] = { ["Northern vial placed"] = "Північна флакон розміщено", ["Southern vial placed"] = "Південний флакон розміщено", ["Western vial placed"] = "Західний флакон розміщено" } },
    [98248] = { [1] = "Етикетка доставки", [2] = "<На боці повністю заповненого ящика можна знайти розірвану транспортну етикетку. Хоча адреса призначення одержувача відірвана, відомості про його походження все ще збереглися.\n\n«Пошкоджені вантажі або порожні ящики поверніть до торгового форпосту постачання та логістики Дуротар, який тепер зручно розташований на захід від Перехрестя в Степах. Ваш час цінний, і ми компенсуємо вам ваші зусилля!»\n\nПоруч із текстом знаходиться грубо намальована карта місцевості поблизу вищезгаданого пункту призначення.>", [3] = "Доставте транспортну етикетку комусь у торговому центрі постачання та логістики Дуротара поблизу Перехрестя в Степах.", ["en"] = "Shipping Label", ["tasks"] = { ["Shipping Label"] = "Етикетка доставки" } },
    [98251] = { [1] = "Ніколи не повернуся", [2] = "Ааа!\n\nЯ такий злий. Казали, що в Ясенедолі легко стежити. Кому легко? Звірам? Птахам?\n\nОдну мить я збирав траву, а наступної — у пастці в цьому яру. Невже мені справді потрібно обійти півлісу, щоб дістатися туди, де я стояв лише кілька хвилин тому?\n\nКоли я такий, мої чари стають нестабільними та поводяться... інакше.\n\nЧи міг би ти прорідити диких тварин поблизу? Навіть їхні дурні копита ріжуть мене. Я зневажливо ставлюся до цього проклятого лісу.", [3] = "Убийте 6 оленів Тіньового Рогу та 6 ведмедів Ясенеділу та поверніться до Ва'ксугської Вогняної Люті на північний захід від Озера Падшого Неба.", ["en"] = "Never Coming Back", ["tasks"] = { ["Ashenvale Bear slain"] = "ясенедільський ведмідь: убито", ["Shadowhorn Stag slain"] = "тінерогий олень: убито" } },
    [98252] = { [1] = "Порожній шлях", [2] = "Покажи моєму Оку Кілрогга вихід з цього яру назад до дороги до Ясенеділу. Тримай його, а я піду за тобою, щойно побачу вільний шлях.\n\nЯ залишуся тут — один із нас має тримати курс. Якщо ти заблукаєш, я можу провести тебе назад через око. Я не дозволю нам обом блукати наосліп у цьому зловісному лісі.\n\nЯ можу утримувати канал чотири хвилини. Не довше. Доберися до дороги, перш ніж зникне видіння, або повернися до мене, і ми спробуємо ще раз.", ["en"] = "A Void Path", ["tasks"] = { ["Eye of Kilrogg guided to the road"] = "Око Кілрогга, спрямоване на дорогу" } },
    [98284] = { [1] = "Кемпінг 101: Чарівний", [2] = "Чарівники роблять усе кращим і завжди раді бачити їх у будь-якому таборі в дикій природі.\n\nГадаю, я знаю когось, хто може навчити вас, як створити Зачаровану лютню для вашого табору. Так важливо знаходити розваги під час відпочинку, і ця частинка магії може допомогти вам бути готовими до всіляких випробувань, коли ви знову вирушите на стару запилену стежку.", [3] = "Поговоріть з Насаланною Вітроспівачкою в селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Enchanting", ["tasks"] = { ["Raise your enchanting skill to 20"] = "Підвищте свою майстерність зачарування до 20" } },
    [98340] = { [1] = "Великий котячий дух", [2] = "Здається, ти готовий до наступного кроку у своїй подорожі, юний друїде. Дендрит Зоряний Блейз послав за тобою і бажає, щоб ти знову знайшов його в Мунґлейді.\n\nТи вже навчився закликати магію, щоб вона перенесла тебе до Мунґлейду, тому ти зможеш негайно вирушити на корабель, якщо забажаєш. Я б порадив тобі вирушити незабаром, якщо ти хочеш продовжити своє друїдське навчання.", [3] = "Поговоріть з Дендритом Зоряним Сяйвом у селі Найтхейвен, Місячна Галявина.", ["en"] = "The Great Cat Spirit" },
    [98342] = { [1] = "Великий котячий дух", [2] = "Щоб звернутися до мого духу, тобі знадобиться більше, ніж кілька слів. Щоб зрозуміти та поважати мою форму, ти повинен довести, що можеш втілювати хитрість, скритність, а якщо тебе заганять у кут, то й лютість.\n\nУ Курганних Лігвах, на схід від цього місця, знаходяться три реліквії моєї милості, які ти повинен здобути. Їх охороняють могутні розлючені духи, які нападуть на тебе одразу. Статуя біля входу благословить тебе тимчасовою скритністю, щоб ти міг пройти повз них.\n\nПоверни мені ці реліквії. Подивимося, чи готовий ти прийняти мою форму.", [3] = "Знайдіть Реліквію Ікла, Реліквію Кігтя та Реліквію Мовчазної Тіні з Кургану Буревісника та поверніть їх Великому Духу Кота.", ["en"] = "The Great Cat Spirit", ["tasks"] = { ["Relic of the Claw"] = "Реліквія Кігтя", ["Relic of the Fang"] = "Реліквія Ікла", ["Relic of the Silent Shadow"] = "Реліквія Мовчазної Тіні" } },
    [98362] = { [1] = "До Тандер-Блафф", [2] = "Настав час знову розлучитися, юний, оскільки застосування твоїх уроків повертає тебе до того, хто послав тебе до мене. Здається, твій наставник, Турак Рунототем, знайшов у тобі гідного учня. Гадаю, я теж такого бачу. Звертай увагу на його уроки, і незабаром ти зможеш звернутися до Великого Котячого Духа, щоб прийняти його форму.\n\nПовернися туди, звідки ти прийшов. Коли настане час, ми знову зустрінемося.", [3] = "Поверніться до Громової Утеси та поговоріть з Тураком Рунотомом на Підйомі Старійшин.", ["en"] = "To Thunder Bluff" },
    [98389] = { [1] = "Світло в темряві", [2] = "Вітання, {клас}. Так, я паладин. Навіть смерть не може зупинити Світло.\n\nЦе спільне для мого виду з усіма Відреклими — ми подолали те, що живі вважають своїм кінцем. Однак, деякі навіть серед наших бояться нас; вони підозрюють, що ми вразимо їх як якусь потвору.\n\nНасправді, наші стосунки з нежитью складні, але я тут не для того, щоб завдати шкоди нашим. Допоможіть мені показати це іншим. Вирушайте до Нічної Павутини на північний захід і звільніть щойно піднятих дурнів, яких там спіймали павуки.", [3] = "Безкоштовно отримайте 6 жертв з павутинням у Павутинній Долині Нічного світу для Араміса Молота Рука у Смертельному Дзвоні.", ["en"] = "A Light in the Darkness", ["tasks"] = { ["Webbed Forsaken freed"] = "Звільнений Павутинний Відрек" } },
    [98405] = { [1] = "Великий котячий дух", [2] = "У південній частині Місячної Галявини, на пагорбі, з якого видно міст, мешкає мудра та хитра істота, яку ми називаємо Великим Духом Кота.\n\nПодібно до Великого Духа Ведмедя, цей дух служив наставником та вихователем для друїдів, які бажають прийняти котячу форму. Усі друїди зрештою шукають його мудрості, і якщо ви бажаєте прийняти котячу форму, ви теж її отримаєте.\n\nЗустріньтеся з Великим Духом Кота та дізнайтеся, чого він вас навчить.", [3] = "Знайдіть Великого Котячого Духа в південній частині Місячної Галявини та дізнайтеся, що він може вам розповісти про котячу природу.", ["en"] = "The Great Cat Spirit" },
    [98424] = { [1] = "Нотатки Шуморакети", [2] = "Деякі особливо потерті папери зберігаються окремо, складені у внутрішній нагрудній кишені Фізспрокет.\n\nЗдається, вони містять важливу інформацію, яку можна було б використати проти ТзНБ \"Авантюра\" та її діяльності в регіоні. Було б розумно пошукати більше, перш ніж повертатися до Морін Хмарсталкер.", [3] = "Зберіть решту сторінок керівника Шуморакети в шахті ТзНБ \"Авантюра\" та принесіть їх Моріну Ловцю Хмар біля селища Криваве Копито.", ["en"] = "Fizsprocket's Notes", ["tasks"] = { ["Barrens Operations Best Practices"] = "Найкращі практики операцій у степах", ["Mulgore Expansion Plans"] = "Плани розширення Мулгора", ["One \"Gerenzo\", of Stonetalon"] = "Один «Геренцо» з Стоунталона", ["Shredder Operation Instructions"] = "Інструкції з експлуатації шредера" } },
    [98427] = { [1] = "Припинення діяльності", [2] = "Подрібнювач, про який йдеться на одній зі сторінок, — я вже бачив їх у своїх подорожах. Вони можуть знищити ліс за лічені секунди, ніж рука та сокира.\n\nЦілі галявини — домівки для дітей Матері-Землі протягом тисячоліть — стерті за лічені дні.\n\nМи не дозволимо цьому статися в нашому домі, за крок від того місця, де наші малюки роблять свої перші кроки.\n\n{ім'я}, я мушу попросити вас зібрати інших, повернутися в шахту на північний схід і переконатися, що там більше не буде зрубано жодного дерева.", [3] = "Принесіть Ключ Лісоруба Моріну Хмарнолову біля села Криваве Копито.", ["en"] = "Ceasing Operations", ["tasks"] = { ["Clearcutter Key"] = "Ключ для рубки" } },
    [98430] = { [1] = "Довгоходи", [2] = "Вітаю, {клас}. Що привело тебе глибоко в таке темне та насильницьке місце?\n\nМене сюди відправив Верховний Вождь Керн Криваве Копито, щоб зв'язатися з гнолами, які тут оселилися. Решта моєї місії має залишатися в таємниці, як і все, що стосується Довгоходів, довірених розвідників нашого вождя.\n\nВсе, що ти маєш знати, це те, що наша дипломатія була зустрінута насильством, і боюся, що я можу стати сьогоднішнім бенкетом для гнолів, якщо ти не допоможеш мені втекти.\n\nТи готовий до завдання?", [3] = "Допоможіть Періту Штормового Копита втекти з Палевої Скелі та повідомте про його безпеку Керну Кривавому Копиту в Громовій Утесі.", ["en"] = "The Longwalkers", ["tasks"] = { ["Escort Perith Stormhoof out of Palemane Rock"] = "Супровід Періта Буреногого з Палевої Скелі" } },
    [98435] = { [1] = "Звіт Громового Рогу", [2] = "Наші старійшини у Громовому Бескиді повинні знати про прогрес, якого ми тут досягли завдяки вашій допомозі.\n\nБудь ласка, віднесіть це Архідруїду Хамуулу Рунототему у Громовому Бескиді. Ви знайдете його на Старійшинському Підйомі, на східній стороні міста. Вам потрібно піднятися ліфтами до центру міста, а потім перетнути мости, щоб дістатися туди.", [3] = "Принесіть звіт Громового Рогу Архідруїду Хамуулу Руническому Тотему в Громовій Утесі.\n\nНаданий предмет:", ["en"] = "Thunderhorn's Report", ["tasks"] = { ["Cleanse the Wildmane Well"] = "Очистіть криницю Дикої Гриви" } },
    [98517] = { [1] = "Поклик вогню", [2] = "Вітаю тебе, юний Небесний. Духи говорили про тебе і кажуть мені, що ти готовий прислухатися до поклику вогню. Однак, не я буду тим, хто почне тебе цим Шляхом. Повернися до свого дому на елементальному плані, шукай там своїх наставників. Вони скажуть тобі, що треба робити.", ["en"] = "Call of Fire", ["tasks"] = { ["Torch of the Dormant Flame"] = "смолоскип дрімаючого полум'я" } },
    [98545] = { [1] = "Лист Леоніда", [2] = "Оскільки ви тут, я хотів би, щоб ви доставили цього листа моєму старому другу в Підмісті. Я б доставив його сам, але в мене дещо пишна історія з Темною Леді, і було б краще, якби доставку здійснила нейтральна третя сторона.\n\nВи шукаєте гобліна на ім'я Глікс Ксіззікс у Торговому кварталі Підмісті. Я впевнений, що він буде радий компенсувати вам ваш час.\n\n<Леонід тихо сміється, передаючи вам листа.>", [3] = "Доставте Запечатаного Листа Гліксу Ксіззіксу в Підмісті.", ["en"] = "Leonid's Letter", ["tasks"] = { ["Sealed Letter"] = "Запечатаний лист", ["Sealed Letter (Provided)"] = "Запечатаний лист (видано)" } },
    [98575] = { [1] = "Заплямовану таблетку", [2] = "А, поки тебе не було, тобі прийшла табличка, {ім'я}.\n\nЯ зазвичай уникаю спілкування з чаклунами, якщо можу, але думаю, тобі варто прочитати її, коли матимеш час. Якщо я не помиляюся, вона надійшла від твого новопризначеного тренера, Нартока. Він поговорить з тобою, коли ти будеш готовий.", [3] = "Прочитайте Заплямовану Скрижаль та поговоріть з Нартоком у Лігві в Долині Випробувань.", ["en"] = "Tainted Tablet", ["tasks"] = { ["Tainted Tablet"] = "Заплямовану таблетку", ["Tainted Tablet (Provided)"] = "Заплямовану таблетку (видано)" } },
    [98576] = { [1] = "Гліфічний пергамент", [2] = "А, поки тебе не було, тобі прийшов пергамент, {ім'я}.\n\nПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренерки магів Майї. Вона поговорить з тобою, коли ти будеш готовий.", [3] = "Прочитайте Гліфічний пергамент і поговоріть з Май'ах біля входу до Лігва в Долині Випробувань.", ["en"] = "Glyphic Parchment", ["tasks"] = { ["Glyphic Parchment"] = "Гліфічний пергамент", ["Glyphic Parchment (Provided)"] = "Гліфічний пергамент (видано)" } },
    [98601] = { [1] = "Важкий шлях", [2] = "Поки ти мав справу з бездумною Скотією, тобі прибув цей сувій. Від нього тхне світлом, тому я гадаю, що він має певне значення для такого паладина, як ти.\n\nПрочитай його, перш ніж знову вирушити. Тільки, будь ласка, відійди, коли будеш йти. Паладини мене досить непокоять.", [3] = "Прочитайте Освячений Сувій та поговоріть з Арамісом Молотком у церкві в Смертельному Дзвоні.", ["en"] = "A Difficult Path", ["tasks"] = { ["Consecrated Scroll"] = "Освячений сувій", ["Consecrated Scroll (Provided)"] = "Освячений сувій (видано)" } },
    [98739] = { [1] = "Благословення Великого Котячого Духа", [2] = "Тепер, коли ти отримав моє благословення, повертайся до Дендрита. Він надасть тобі подальші вказівки. Я дуже сподіваюся, що ми колись знову зустрінемося.\n\nНехай тіні назавжди приховують тебе, а твої вороги легко стануть жертвами твоїх кігтів, юний.", [3] = "Поговоріть з Дендритом.", ["en"] = "Blessings of the Great Cat Spirit" },
    [98823] = { [1] = "Відлуння земельників", [2] = "Це справді дивовижний предмет.\n\nУсе свідчить, що це значно більше, ніж просто різьблення чи скульптура.\n\nНаші старійшини, можливо, захочуть оглянути цей артефакт, але найбільше про засипані руїни й забуті землі знає Земляне Кільце. Знайди Мулна Лють Землі. З огляду на важливість твоєї ноші, найкраще звернутися прямо до нього.\n\nЙого та інших старійшин ради Земляного Кільця знайдеш на плато Небесного Вартового, на північному заході Мулґору.", [3] = "Віднесіть реліквію титанів Мулну Люті Землі на плато Небесного Вартового на північному заході Мулґору.", ["en"] = "Earthen Echo", ["tasks"] = { ["Titan Relic"] = "Реліквія титанів" } },
    [99] = { [1] = "Дурість Аруґала", [2] = "Разом із моїм розумінням магії Аруґала зростає і моє презирство до цього нещасного дурня. Я вже майже завершив своє дослідження його так званого \"засобу\".\n\nМої знання будуть повні, коли я дізнаюся, які саме чари спричиняють ті дивацтва в селі Поховальні Вогнища. Протягом дня селяни виглядають, як люди. Але з заходом сонця мешканці перетворюються на воргенів Місяцесказу.\n\nМені потрібно витягти енергію з зачарованих кайданів, що Аруґал надягнув на них. Принеси мені шість кайданів з Поховальних Вогнищ, {ім'я}.", [3] = "Принесіть 6 кайданів з Поховальних Вогнищ до Далара Ранньоткача в Крипту.", [4] = "Тобі вже вдалося роздобути кайдани з Поховальних Вогнищ, {ім'я}?", [5] = "Твоя наполегливість похвальна. За допомогою даних, що ти {стать:допоміг:допомогла} мені зібрати, Аруґала буде здолано, а його необачну магію - розсіяно. Твоє здоров'я, {ім'я}.", ["en"] = "Arugal's Folly", ["tasks"] = { ["Pyrewood Shackle"] = "кайдани з Поховальних Вогнищ", ["Pyrewood Shackle (Provided)"] = "кайдани з Поховальних Вогнищ (видано)" } },
    [99048] = { [1] = "Відсутня рука", [2] = "Член Розбитої Руки, групи більш... витончених бійців, спостерігав за Тірагардською Твердою здалеку. Її звіти раптово перестали надходити.\n\nСумніваюся, що люди спіймали б її, тому я хвилююся, що щось небезпечніше відбувається. Подивіться, чи зможете ви її знайти. Сподіваюся, що повідомлення просто затримуються.", [3] = "Знайдіть Геглана Шадіє на північ від Тірагардської фортеці.", ["en"] = "A Missing Hand" },
    [99049] = { [1] = "Загроза знизу", [2] = "<Навколишня територія зруйнована, є очевидні сліди сутички. Хто б не влаштував засідку на Хеглана, він не вийшов з неї неушкодженим. Ймовірно, поблизу є сліди того, що сталося.\n\nОргніл, ймовірно, захоче побачити будь-які докази, залишені нападниками.>", [3] = "Знайдіть сліди того, що напало на Хеглана Шейдай.", ["en"] = "Threat from Below", ["tasks"] = { ["Banner Scrap"] = "Брухт банера", ["Broken Bone Trident"] = "Тризуб зламана кістка", ["Orcish Dagger"] = "Орчий кинджал" } },
    [99051] = { [1] = "Загроза знизу", [2] = "Це не перший раз, коли ці змії турбують нас. Їм потрібно навчити, що їхня присутність тут не допускається.\n\nЗнайдіть, де їхні розвідники розбивають табір, і вбийте їх. Принесіть мені їхні плавники як доказ. Нам потрібно діяти швидко, щоб переконатися, що вони зрозуміли.", [3] = "Зберіть 9 колючих плавників Нага.", ["en"] = "Threat from Below", ["tasks"] = { ["Naga Spinefin"] = "Нага Колючий плавник" } },
    [99052] = { [1] = "Загроза знизу", [2] = "Один з моїх розвідників повідомив, що морський велетень стежив за тими нагами сюди. Не впевнений, чи вони привели його навмисно, чи що, але він у будь-якому разі небезпечний.\n\nВін молодий, але все ще може розірвати орка навпіл вмить, якщо його заскочать зненацька. Мені потрібно, щоб він зник. Але я б порадив вам знайти допомогу, щоб розібратися з цим.", [3] = "Убийте морського велетня вздовж північного узбережжя Дуротара та принесіть доказ своїх досягнень.", ["en"] = "Threat from Below", ["tasks"] = { ["Aggor's Belt"] = "Пояс Аггора" } },
    [99079] = { [1] = "Лонгвокер Малах", [2] = "Довгоходи — найдовіреніші розвідники нашого народу. Хоча вони віддані лише Верховному Вождю, молодий Бейн часом звертається до них за допомогою.\n\nЦе один із таких випадків. Довгоходицю Малах було відправлено поблизу наших кордонів на схід і не повернулася минулої ночі через три дні. Коли це станеться, наш обов'язок — підтвердити їхню безпеку.\n\nЯ маю забезпечити безпеку села. Доведіть свою спроможність і знайдіть Малах. Ви впізнаєте її за пов'язкою на голову та пір'яним посохом, що є символом Довгоходів.", [3] = "Знайдіть Довгомандрівницю Малах Довгийвітер на схід від села Криваве Копито, недалеко від околиці Мулгору.", ["en"] = "Longwalker Malah" },
    [99080] = { [1] = "Виженіть їх", [2] = "Уважно послухайте мої слова: ми не віддамо кентавру жодної травинки.\n\nІдіть до їхнього табору зараз, поки вони не відпочили і не мали можливості дістатися до нашого села. Вибийте їх усіх. Переконайтеся, що ніхто не втече до Степу, щоб зібрати інших на допомогу.\n\nЯкщо ви знайдете ватажка цього потенційного загону розбійників, принесіть мені його голову, щоб вона могла служити попередженням для інших, хто наважиться ступити на нашу батьківщину предків.", [3] = "Убийте 6 галакських кентаврів, 4 галакських втікачів та принесіть голову Герака Розбійника до Бейна Кривавого Копита.", ["en"] = "Drive Them Out", ["tasks"] = { ["Galak Centaur slain"] = "кентавр племені Ґалак: убито", ["Galak Outrunner slain"] = "вістовий племені Ґалак: убито", ["Herak's Head"] = "Голова Герака" } },
    [99081] = { [1] = "Похмурі новини", [2] = "Ви можете побачити щось схоже на новий табір кентаврів у напрямку, звідки мали б прилетіти стріли в спину Малах. Чути активність, що свідчить про те, що невеликий загін рейдувальників пробрався до Мулгору.\n\nДовгоходка тримає звіт у своїй все ще стиснутій руці. Хоробрий Дикий Бігун захоче знати про долю Малах – і про її вбивць.", [3] = "Принесіть звіт Довгоходки Мала Хороброму Дикому Бігуну в Село Кривавих Копит.\n\nНаданий предмет:", ["en"] = "Grim Tidings", ["tasks"] = { ["Longwalker Malah's Report"] = "Звіт Лонгвокера Малаха" } },
    [99082] = { [1] = "Верховний вождь", [2] = "Ваша хоробрість, захищаючи свій народ, заслуговує на визнання. Вирушайте до Громового Бескиду на північному заході, нашого могутнього міста, чия тінь дарує нам затінок у теплі місяці, та домагайтеся аудієнції у мого батька.\n\nСаме він очолив атаку з молодим Вождем Траллом, щоб повернути ці рівнини та назавжди прогнати кентавра. Як Верховний Вождь, він щедро винагородить вас за ваш внесок у забезпечення того, щоб його власну хоробрість було вшановано.\n\nВи повинні скористатися ліфтом, щоб дістатися до Верховного Вождя, який сидить на центральному пагорбі.", [3] = "Зверніться до Верховного Вождя Керна Кривавого Копита у Громовій Утесі.", ["en"] = "The High Chieftain" },
    [99101] = { [1] = "Наш давній ворог", [2] = "Бейн Криваве Копито очолює наше село. Він має негайно дізнатися про це вторгнення.\n\nПринесіть йому звіт Довгохода Малаха. Ви знайдете його в центрі міста.\n\nШвидше, зараз. Немає часу гаяти!", [3] = "Принесіть доповідь Довгохода Малах до Бейна Кровавого Копита.", ["en"] = "Our Ancient Enemy", ["tasks"] = { ["Longwalker Malah's Report"] = "Звіт Лонгвокера Малаха", ["Longwalker Malah's Report (Provided)"] = "Звіт Лонгвокера Малаха (видано)" } },
    [99108] = { [1] = "Спаринг-матч", [2] = "Вітаю тебе, юний {клас}. Хоча ти не воїн, і я не можу навчити тебе цьому шляху, це не означає, що ти не отримаєш користі від моєї опіки.\n\nПеред тобою лежить арена. На ній не має значення, кого ти називаєш матір'ю, чи володієш ти мечем чи луком. Усі рівні, і всі вчаться гострити свої роги в прямому бою.\n\nЧи увійдеш ти в наш простір і сам вивчиш наші шляхи? Ти можеш зіткнутися з будь-ким із цих новачків або з будь-яким іншим добровільним супротивником. Мені байдуже, з ким.", [3] = "Переможіть 3 інших гравців у дуелях або воїнів-новачків, щоб отримати Танга Кам'яне Копито.", ["en"] = "Sparring Match", ["tasks"] = { ["Player Duels won or Novice Warriors defeated"] = "Виграні дуелі гравців або перемога над воїнами-новачками" } },
    [99123] = { [1] = "Загублений у тінях", [2] = "Я вирішив трохи розвідати скелю самостійно. На жаль, моя магія закінчилася в самий невідповідний час, і з того часу я застряг тут, ховаючись.\n\nЯкщо ви можете допомогти мені втекти, я буду вдячний.", [3] = "Допоможіть Пал'джу вибратися зі скелі Колкар і повідомте звістку про ваш успіх майстру Ворналу в селі Сен'джін.", ["en"] = "Lost in the Shadows", ["tasks"] = { ["Escort Pal'juh out of Kolkar Crag."] = "Супроводьте Пал'джуха зі скелі Колкар." } },
    [99134] = { [1] = "Дисципліна", [2] = "Ти не є членом Гвардії Смерті, і тому ще не розчарував мене.\n\nЯк винагороду за твою некомпетентність, тебе буде винагороджено покаранням тих, хто надмірно продемонстрував такі таланти.\n\nШвидше зараз --{ім'я}, так? -- або я додам твоє ім'я до своєї книги як винагороду для когось іншого.", [3] = "Покарайте 5 Гвардійців Смерті за Виконавця Зіганда.\n\n(1)\n\nНаданий предмет:", ["en"] = "Discipline", ["tasks"] = { ["Deathguard Abraham"] = "Страж Смерті Абрахам", ["Deathguard Billmuth"] = "Страж Смерті Біллмут", ["Deathguard Gavin"] = "Страж смерті Гевін", ["Deathguard Lawrence"] = "Страж Смерті Лоуренс", ["Deathguard Phillip"] = "Філіп, страж смерті", ["Deathguards motivated (5) Deathguard Linnea"] = "Мотивовані Вартові Смерті (5) Вартові Смерті Ліннея" } },
    [99141] = { [1] = "Терпіння", [2] = "Не помиляйтеся, {клас} -- Темна Леді вимагає бездоганного виконання її волі. Як Виконавець, мій обов'язок — простежити за цим.\n\nЗвіти від кількох моїх Вартових Смерті вже давно надійшли. Звісно, моє терпіння вичерпалося. Отримайте їхні звіти та принесіть їх мені в ім'я Темної Леді.\n\nВи знайдете Вартового Смерті Діллінджера трохи західніше звідси, біля цвинтаря. Вартовий Смерті Крістоф розташований на станції на сході. І перевірте гидоту Гордо; він блукає на захід біля Стіллвотер-Понд.", [3] = "Отримайте звіти від Вартових Діллінджера, Вартових Крістофа та Гордо для Виконавця Зайганда.", ["en"] = "Patience", ["tasks"] = { ["Dillinger's Report"] = "Звіт Діллінджера", ["Gordo's Report"] = "Звіт Гордо", ["Kristof's Report"] = "Звіт Крістофа" } },
    [99142] = { [1] = "Гробничий бур'ян", [2] = "Якщо ви прямуєте на схід, до ферми Балнір, у мене є дещо, чим ви могли б мені допомогти. Гарну допомогу зараз дуже важко знайти, адже ваша зустріч з Гордо висвітлюється так чітко.\n\nЗдобуваючи траву фаталі, я проводжу деякі незначні алхімічні зміни та пересаджую її на тій фермі, щоб виростити своє остаточне творіння. Я називаю її травою гробниці, і вона буде вісником моєї славної долі.\n\nСлідкуйте за Скотчем у цій місцевості, поки ви там. Здається, їх... тягне... до трави. Цікаво.", [3] = "Збери 5 гробниць та достав їх молодшому аптекарю Голланду.", ["en"] = "Tomb Weed", ["tasks"] = { ["Tomb Weed"] = "Гробничий бур'ян" } },
    [99144] = { [1] = "Шукаючи притулку", [2] = "Благословляє вас Світло за те, що ви мене знайшли. Я прямував з фортеці Бандаріон, щоб доставити повідомлення Шарі Стілвелл у Брілл, коли ці монстри захопили мене. Вони володіють Світлом з ненавистю в серцях, яка змушує закипати залишки моєї крові. Це суперечить усьому, заради чого я медитую... усьому, що я прагну захистити!\n\n<Барет Донстоун заспокоюється.>\n\nЯ знаю, що дехто досі не має нічого спільного з моїми родичами, але запевняю вас, наші наміри чисті. Якщо ви допоможете мені втекти з цього місця, я буду вам вічно вдячний.", [3] = "Допоможіть Барету Донстоуну втекти з форпосту Хрестоносців та повідомте про його безпеку Шарі Стілвелл у Бріллі.", ["en"] = "Seeking Refuge", ["tasks"] = { ["Escort Bareth Dawnstone out of Crusader's Outpost"] = "Супроводьте Барета Донстоун з форпосту хрестоносців" } },
    [99152] = { [1] = "Як угорі, так і внизу", [2] = "Хоча Затьмарені в Тіньовій Долині на південному заході, безумовно, є проблемою, ми не можемо дозволити підвалам під містом перетворитися на повномасштабне повстання Скотчу на Бандеріонській фортеці.\n\nМені потрібно навчити цих стажерів на випадок, якщо це станеться. Ви ж, однак, пройдете те, що я люблю називати прискореним курсом.\n\nПодорожуйте під Тіньовій Долиною та знайдіть деякі з їхніх жалюгідних кісток, щоб ми могли їх вивчити далі. Мені потрібні ті, що все ще зберігають частину початкової магії реанімації – це ті, що світяться.", [3] = "Зберіть 6 ледь сяйливих кісток для Гільди Трощительки.", ["en"] = "As Above, So Below", ["tasks"] = { ["Faintly Glowing Bone"] = "Слабо світиться кістка" } },
    [99153] = { [1] = "Той, що втік", [2] = "Гей, ти! Чутка швидко поширюється серед наших лав. Я чув про роботу, яку ти виконував з культистами щодо залишків битви з Наксрамасом.\n\nПроблема в тому, що один з цих культистів втік зі шматком фокусуючого кристала. Здається, у ньому ще є якась сила. Найкраще, що ми можемо припустити, це те, що він десь під Тіньоверхим Вейл. Він або піднімає їх, або робить їх сильнішими, а тобі не потрібне ні те, ні інше.\n\nЗнайди той кристал, поки ситуація не вийшла з-під контролю.", [3] = "Знайдіть прихований фрагмент кристала під Тіньоудейлом для Ефрама Барбаро.", ["en"] = "The One That Got Away", ["tasks"] = { ["Glowing Crystal Fragment"] = "Фрагмент сяючого кристала" } },
    [99156] = { [1] = "Патруль тилової сторожі", [2] = "Чорт забирай! Поки ти патрулював, надійшов новий звіт. Побачили мерзоту-зрадника, що блукає Східними Тірісфальськими галявинами, поблизу Долини Отруйної Павутини.\n\nЩось не так. Гидоти не прослизають непоміченими через Бастіон.\n\nТримайте це питання суворо в секреті. Однак, така істота не впаде легко; тобі знадобляться союзники, якщо ти хочеш бути чимось більшим, ніж просто її наступна страва.\n\nДоведіть це до кінця, і ви будете належним чином винагороджені. Принесіть мені її серце як доказ скоєного.", [3] = "Принесіть Серце Ріптіара Вартовій Смерті Ліннеї.", ["en"] = "Rear Guard Patrol", ["tasks"] = { ["Riptear's Heart"] = "Серце Ріптіара" } },
    [99196] = { [1] = "Пожертва вовняного полотна", ["en"] = "A Donation of Wool", ["tasks"] = { ["Wool Cloth"] = "вовняне полотно", ["Wool Cloth (Provided)"] = "вовняне полотно (видано)" } },
    [99197] = { [1] = "Пожертва шовкового полотна", ["en"] = "A Donation of Silk", ["tasks"] = { ["Silk Cloth"] = "шовкове полотно" } },
    [99411] = { [1] = "Кайл зник!", [2] = "Допоможи, {ім'я}! Моє улюблене цуценя Кайл утекло! Певен, він блукає селом Кривавого Копита, загублений і голодний.\n\nЗнайдеш його й нагодуєш? Коли поїсть, заспокоїться й повернеться додому.\n\nЩоб його нагодувати, треба знайти їжу. Найбільше він любить ніжне м'ясо довгоногів. Просто вирушай на схід — там їх повно. Вполюй одного й віднеси соковите м'ясо Кайлу. Побачивши його в селі, поклади м'ясо на землю, і він неодмінно прибіжить до тебе.", [3] = "Агаб Пшеничне Копито із села Кривавого Копита в Мулґорі просить нагодувати його улюблене цуценя, несамовитого Кайла.\n\nНагодуйте Кайла ніжним м'ясом довгонога й поверніться до Агаба Пшеничного Копита.", ["en"] = "Kyle's Gone Missing!", ["tasks"] = { ["Kyle Fed"] = "Нагодувати Кайла", ["Tender Strider Meat"] = "Ніжне м’ясо довгонога" } },
}
addonTable.quest_horde = quest_horde

local quest_both = {
    [1] = { [1] = "Квест «Чоу» (123)aa", [2] = "$Tpunk;! Убийте Кобольдів-Шкодників, 2 з них. ЗНОВУ НОВИЙ ВИПРОБУВАННЯ", ["en"] = "The \"Chow\" Quest (123)aa" },
    [10] = { [1] = "Спокута Полотноміра", [2] = "О, це жахливо! Я відправив мого найкращого помічника, молодшого землеміра Полотноміра, в пустелю на південь звідси. Цей район ми називаємо Зяючим проваллям. Що ж, він зник, а в його останньому звіті йшлося про дивних комах. Чи може бути так, що вони захопили два великі регіони пустелі?\n\nПрошу тебе, рушай в Зяюче провалля та знайди Полотноміра. Або хоча б його землемірне спорядження. Боюсь, що це може бути все, що залишилося від бідолахи.", [3] = "Дізнайтеся про долю молодшого землеміра Полотноміра і приведіть його або принесіть його землемірне спорядження старшому землеміру Шипохіднику в Пристроблях.", [4] = "Ну, є якісь новини? Ти виглядаєш так, ніби {стать:побував:побувала} у справжній битві... Полотномір живий?", [5] = "Він був хорошим гобліном, юний Полотномір. Будемо сподіватися, що його смерть не була марною, оскільки він зміг зібрати це за допомогою свого землемірного спорядження.\n\nЗдається, у нас серйозна проблема з цими комахами. Вони надто хитрі, але всі дослідження вказують на те, що на цих тварюк впливає третя сторона! Якщо це так, то це несприятливо вплине не тільки на Пристроблях, а й на всю пустелю!", ["en"] = "The Scrimshank Redemption", ["tasks"] = { ["Scrimshank's Surveying Gear"] = "землемірне спорядження Полотноміра", ["Scrimshank's Surveying Gear (Provided)"] = "землемірне спорядження Полотноміра (видано)" } },
    [100] = { [1] = "Поклик води", [2] = "Спалах світла засліплює вас, щойно ви закінчуєте заклинання. Звуки крапель води, що вдаряються об полум'я, стихають, і вам легшає, оскільки духи псування навколо вас знищені.", [3] = "Поговоріть із меншим проявом води в Срібнохвойному пралісі.", [5] = "Дякую тобі. Дякую шаманам.\n\nПсування відступає, але життя продовжує згасати. Місія шаманів — це захист життя.", ["en"] = "Call of Water" },
    [1003] = { [1] = "Дзижчатор 525", [2] = "За звуками булькання, що лунають з машини, ви чуєте віддалений голос Бацбаха.\n\n\"Наштупне місце далеко на південь по дорозі. Знайти буде нескладно... прямо біля узбіччя...*Гик!* ...біля болота. Здається, я сховав його в кушчах... Куш-чах. Хе-хе... Так, Дзижчатору 525 потрібні скальпи з посивілих татарних ведмедів. Ммм! Неперевершене пійло! Тартарних... Хе-хе-хе...\"\n\nВи чуєте звуки ковтків і машина замовкає. Раптом вона знову оживає.\n\n\"Чотири!\"", [3] = "Зберіть 4 скальпи з посивілих татарних ведмедів на південь від Аубердіну та помістіть їх у Дзижчатор 525.", [4] = "Ви чуєте, як з Дзижчатора 525 лунає спів.\n\n\"Гарне ж повжунів вино й шолодке... Ж молотників ель гарно в голову б'є... *Гик!* Місяцескрадний первак до рання шибає... Е-е-е... Я ш у полоні нав'язливих дум... *Гик!* ...лиш пиво татарне непокоїть мій ум!\"\n\nПриймач відчинений і чекає на 4 посивілі скальпи, а пісенька повторюється знову й знову.", [5] = "\"То шо, ти вже {стать:поклав:поклала} скальпи всередину? Гаразд... Га? А, так, ти певно вже {стать:здогадався:здогадалась}, що ми можемо спілкуватись без цих матеріалів у машині. Але я не брехав — вони дійсно зламані!\n\nБач, Дзижчатори служать не тільки як... *Гик!* ...засіб комунікації — вони ще й варять гарне питво. Вибач, що умовчав про це, та нічним ельфам не дуже подобається, коли я торгую алкоголем в їх поселеннях. Я поклав у цей Дзижчатор дещо на знак вдячності за твої ж-ж-жусилля. Дякую!\"", ["en"] = "Buzzbox 525", ["tasks"] = { ["Grizzled Scalp"] = "посивілий скальп", ["Grizzled Scalp (Provided)"] = "посивілий скальп (видано)" } },
    [1005] = { [1] = "Що ховається за межами", ["en"] = "What Lurks Beyond" },
    [1006] = { [1] = "Що лежить за межами", ["en"] = "What Lies Beyond" },
    [1007] = { [1] = "Стародавня статуетка", [2] = "Я маю для тебе завдання, {ім'я}.\n\nЯ пропливав над затопленими руїнами Зорама на своєму маленькому човні, коли на мене напали наги. Вони намагалися розідрати мене своїми кігтями! Я втік, прихопивши з собою все, що міг, аби облаштувати цей убогий табір.\n\nАле похапцем дістаючись берега, я втратив дещо цінне.\n\nБлагаю, {ім'я}, знайди місце нападу, на півночі неподалік від берега, і пошукай там стародавню статуетку. Саме заради неї я наважився вирушити до небезпечного Зорамського узбережжя.", [3] = "Принесіть стародавню статуетку Талену в табір біля Зорамського узбережжя.", [4] = "Ти {стать:знайшов:знайшла} статуетку, {ім'я}?", [5] = "Ти {стать:знайшов:знайшла} її! Дякую, {ім'я}!\n\nДавнє місто Зорам зберігає багато таємниць, і ця статуетка може бути ключем до однієї з них.", ["en"] = "The Ancient Statuette", ["tasks"] = { ["Ancient Statuette"] = "стародавня статуетка", ["Ancient Statuette (Provided)"] = "стародавня статуетка (видано)" } },
    [1008] = { [1] = "Зорамське узбережжя", [2] = "Зло оселилося на північному заході Ясенедолу — на Зорамському узбережжі.\n\nЦе місце спочинку приреченого міста Зорам, зруйнованого під час Розколу та зануреного під воду. Нічні ельфи втратили його століття тому. Втратили та майже забули.\n\nАле тепер повернулися наги, і ми не знаємо, чому. Але причини не мають значення: ми повинні знищити цих істот та відкинути їх назад до глибин!\n\nПовертайся до мене, коли завершиш своє завдання.", [3] = "Принесіть 20 голів гнівохвостих наг Шиндрел Спалах в Астранаар.", [4] = "Ми не можемо дозволити нагам загарбати наше узбережжя, {ім'я}. Дуже важливо, щоби ти {стать:вирушив:вирушила} до Зорамського узбережжя та {стать:виконав:виконала} своє завдання.", [5] = "Молодець, {ім'я}. Твої звитяги на Зорамському узбережжі проти наг варті поваги.\n\nЯ знаю, що зробити це було непросто, бо сила та хитрість наг відомі нічним ельфам. Зрештою, ми з ними маємо спільну історію.\n\nІсторію, яку мені не хотілося б повторювати.", ["en"] = "The Zoram Strand", ["tasks"] = { ["Wrathtail Head"] = "голова гнівохвостої наги", ["Wrathtail Head (Provided)"] = "голова гнівохвостої наги (видано)" } },
    [1009] = { [1] = "Руузель", [2] = "Боюся, що таємниці стародавньої статуетки залишаться нерозгаданими, якщо ти не знайдеш ключ до замка.\n\nЦей ключ — зорамський перстень. Він належав правителям цього міста до того, як його накрили хвилі Розколу.\n\nРоками перстень вважався втраченим, але недавно його знайшли наги.\n\nЇхня проводирка, Руузель, живе на острові, що на північній межі Зорама. Благаю, {ім'я}, принеси мені той перстень!", [3] = "Принесіть зорамський перстень Талену неподалік від Зорамського узбережжя.", [4] = "Кажуть, що зорамський перстень може відімкнути будь-який замок у місті. Ти {стать:знайшов:знайшла} його, {ім'я}?", [5] = "Ти {стать:знайшов:знайшла} перстень! Дякую, {ім'я}. Будь ласка, прийми цю плату і знай, що я ніколи не забуду про твої подвиги.", ["en"] = "Ruuzel", ["tasks"] = { ["Ring of Zoram"] = "зорамський перстень", ["Ring of Zoram (Provided)"] = "зорамський перстень (видано)" } },
    [1010] = { [1] = "Батранове волосся", [2] = "Є рослина, яка колись росла в старих руїнах пристанища Батрана на півночі. Рослина називалася \"батранове волосся\" і була відома тим, що виліковувала душевні хвороби.\n\nУ селі є хвора дитина, і я вважаю, що це не просто тілесна недуга. Чи підеш ти до пристанища Батрана, аби пошукати там батранове волосся? Рослина може знадобитися мені, аби як слід вилікувати дитину.\n\nПристанище Батрана знаходиться на північ від застави Маєстри та трохи південніше кордону з Темнобережжям.", [3] = "Принесіть 5 стебел батранового волосся Оренділу Широколисту в Ясенеділ.", [4] = "Ти {стать:зібрав:зібрала} батранове волосся, {ім'я}? Дитина слабшає з кожною годиною...", [5] = "О, ти {стать:приніс:принесла} батранове волосся! Тепер я змішаю ліки для дитини та молитимуся, що моя суміш подіє.\n\nІ... Відречені у пристанищі Батрана? Це дуже тривожні новини. Дуже тривожні...", ["en"] = "Bathran's Hair", ["tasks"] = { ["Bathran's Hair"] = "батранове волосся", ["Bathran's Hair (Provided)"] = "батранове волосся (видано)" } },
    [1011] = { [1] = "Пошесті відречених", [2] = "Відречені, ординські невмерлі, прокралися до Ясенедолу і причаїлись у наших руїнах і курганах. Ми вважаємо, що їхня мета — поширити пошесті в землях нічних ельфів. Ми повинні знайти докази!\n\nНа південь звідси є табір відречених, біля обителі кургану Дор'даніл. Там вони створюють отрути та пошесті та розливають їх у пляшки. Пробийся до цього табору й викради пляшечку з пошестю. Я перевірю її та дізнаюся про її призначення.", [3] = "Принесіть пляшку пошесті Кейнету Штилю в Лісову Пісню.", [4] = "Тобі вдалося знайти табір, {ім'я}? Ти {стать:приніс:принесла} пляшку з пошестю?", [5] = "Чудово, {ім'я}. Тепер... я перевірю вміст цієї пляшки та дізнаюся, що саме замислили відречені!", ["en"] = "Forsaken Diseases", ["tasks"] = { ["Bottle of Disease"] = "пляшка пошесті", ["Bottle of Disease (Provided)"] = "пляшка пошесті (видано)" } },
    [1012] = { [1] = "Божевільні друїди", [2] = "Коли я боровся з отрутою відречених, у мене було видіння. Я бачив друїдів в обителі кургану Дор'даніл, отруєних... вбитих невмерлими! Тепер вони привиди, відірвані від своїх тіл і нестямні.\n\nАби духи друїдів змогли знайти спокій, ти мусиш проникнути в обитель кургану Дор'Даніл і знищити колись великих ватажків: Таніла Темноліса, Утіла Місяцезова та Маворіса Хмаролома.\n\nЗроби це, а потім повертайся до мене.", [3] = "Вбийте друїдів Таніла Темноліса, Утіла Місяцезова та Маворіса Хмаролома, а потім поверніться до Кейнета Штиля в Лісову Пісню.", [4] = "Страждання друїдів Дор'Даніла і досі ввижаються мені у снах, {ім'я}. Ти маєш знищити їхніх ватажків!", [5] = "Я відчув, як страждання друїдів кургану Дор'даніл стихає, і зрозумів, що ти {стать:виконав:виконала} своє завдання.\n\nТи {стать:взяв:взяла} на себе сумний обов'язок, {ім'я}, тому що знищені тобою духи були лише жертвами злих діянь відречених. Але знищивши їх, ти {стать:дав:дала} нам надію, що інші нестямні духи знайдуть спокій.", ["en"] = "Insane Druids", ["tasks"] = { ["Mavoris Cloudsbreak"] = "Маворіс Хмаролом", ["Mavoris Cloudsbreak slain"] = "Маворіс Хмаролом: убито", ["Taneel Darkwood"] = "Таніл Темноліс", ["Taneel Darkwood slain"] = "Таніл Темноліс: убито", ["Uthil Mooncall"] = "Утіл Місяцезов", ["Uthil Mooncall slain"] = "Утіл Місяцезов: убито" } },
    [1016] = { [1] = "Браслети елементалів", [2] = "Візьми цей сувій — він може визначити творця цих елементалів. Але тобі знадобиться щось від них як реагент для фокусування магії сувою. Їхні браслети повинні добре підійти.\n\nДекількох неушкоджених браслетів повинно бути достатньо. Решта не знадобляться для наших цілей, але вони можуть чогось коштувати, якщо ти захочеш їх продати. Після того, як ти отримаєш неушкоджені браслети, застосуй сувій. Повернись до мене з результатами — і ми знатимемо як діяти далі.", [3] = "Зберіть 5 неушкоджених браслетів елементалів та застосуйте до них сувій провіщення. Після цього принесіть сувій з провіщенням стражниці Велені Зоребій в притулок Срібновію.", [4] = "Оскільки для того, щоб убити елементалів, потрібно знищити браслети, знайти ті, що містять важливу інформацію, буде важко. Ти можеш обмінятися браслетами з іншими, аби отримати потрібні. Чи може ти вже маєш сувій з провіщенням?", [5] = "Молодець, {ім'я}, це дасть нам інформацію, необхідну для викриття винуватця. Не хочеш прибрати мага, який наповнює наші водойми спотвореними елементалями? Серце стискається від думки про спотворення Ясенедолу та інших земель, але присутність мага, який намагається поширити його, ще огидніша. Ми змусимо його заплатити.", ["en"] = "Elemental Bracers", ["tasks"] = { ["Divined Scroll"] = "сувій з провіщенням", ["Divined Scroll (Provided)"] = "сувій з провіщенням (видано)" } },
    [1017] = { [1] = "Маг-закликач", [2] = "Існує тільки один невмерлий маг в Степах, здатний на споганення такої кількості водяних елементалів. Він також єдиний, кому вистачить розуму таке зробити. Сарілус Гидкородний певно сидить собі на вершині Зловісного Туману та сміється наді мною.\n\n{ім'я}, вирушай на ворожу територію та знищи цього лиходія. Я більше не терпітиму його недоумкуваті витівки — ми маємо показати йому, що трапляється з тими, хто дратує стражів.\n\nЗнищи його та принеси мені його голову. Але будь {стать:обережний:обережна}: Орда може слідкувати за тобою.", [3] = "Вбийте Сарілуса Гидкородного і принесіть його голову стражниці Велені Зоребій в притулок Срібновію.", [4] = "Все зроблено? Сарілус Гидкородний мертвий?", [5] = "Нарешті його бридка посмішка назавжди стерта з його обличчя. Чудова робота, {ім'я}. Візьми це, сяйво Елуни. Випий його, коли буде здаватися, що все втрачено і смерть поряд. Якщо на те воля богині, це може тебе врятувати.", ["en"] = "Mage Summoner", ["tasks"] = { ["Sarilus Foulborne's Head"] = "голова Сарілуса Гидкородного", ["Sarilus Foulborne's Head (Provided)"] = "голова Сарілуса Гидкородного (видано)" } },
    [1020] = { [1] = "Ліки Оренділа", [2] = "{ім'я}, я створив ліки, які можуть допомогти хворій дитині. Віднеси їх в Астранаар і віддай батькові дитини, Пельтурасу Біломісяцю.\n\nАби дістатися Астранаара, йди дорогою на південь, а потім поверни на схід.", [3] = "Принесіть ліки Оренділа Пельтурасу Біломісяцю в Астранаар.", [4] = "Мушу вибачитися, бо не маю часу на балачки. Моя донька Релара смертельно хвора!", [5] = "Це від Оренділа?\n\nВін багато знає про трави та лікування. Ці ліки дають мені надію, яку я майже втратив...", ["en"] = "Orendil's Cure", ["tasks"] = { ["Orendil's Cure"] = "ліки Оренділа", ["Orendil's Cure (Provided)"] = "ліки Оренділа (видано)" } },
    [1021] = { [1] = "Паскудні сатири! Дріади в небезпеці!", [2] = "Слухай, я не знаю, хто ти, але мені потрібна твоя допомога. Мої сестри пішли, аби забрати гілку Кенарія в сатирів. Вони сказали, що скоро повернуться, але вже минуло два дні!\n\n{ім'я:к}, ти маєш знайти їх! Вони шукали руїни храму нічних ельфів в Завіані, що на північному сході. Навіть не знаю, що думати. Шукай Анілію, вона очолювала пошуки.", [3] = "Знайдіть Анілію в Завіані.", [5] = "Судячи з величезної рани в боці, Анілія на порозі смерті.", ["en"] = "Vile Satyr! Dryads in Danger!" },
    [1022] = { [1] = "Долина Виття", [2] = "Хоча ми доклали багато ресурсів і зусиль, аби позбавитися від решти демонів в Скверноліссі на півночі, наші успіхи були незначними. Нам вдалося захистити Ясенеділ від більшості демонів.\n\nНа півночі, біля кордону зі Скверноліссям, загадкові вовколюди захопили зруйноване святилище Мел'Тандріс. Їх жахливе завивання дало тій місцині назву — долина Виття. Фоліант Мел'Тандріс, що зберігається у святилищі, може допомогти дізнатися причину появи вовколюдів.", [3] = "Йдіть до долини Виття та прочитайте фоліант Мел'Тандріс, а потім поверніться до вартової Мелірії Криготінь біля вівтаря Аессіни.", [4] = "Фоліант, що зберігається у святилищі — загадкова річ. Він не є книгою в традиційному сенсі. Сторінки фоліанта були освячені самою Мел'Тандріс, і містять записи про важливі події.\n\nЦе важко пояснити. Якщо підеш до святилища, ти зрозумієш.", [5] = "Фоліант Мел'Тандріс працює дивним чином. Події, які в ньому записано та які він показує... ніхто не розуміє, чому він робить те, що робить.\n\nІ все ж-таки очевидно, що те, що отримала жриця Зорепісня — коса Елуни — потребує подальшого дослідження.", ["en"] = "The Howling Vale", ["tasks"] = { ["View the Tome of Mel'Thandris"] = "Перегляньте фоліант Мел'Тандріса" } },
    [1023] = { [1] = "Очищення Рене", [2] = "Обшукуючи речі Тероніса, ви знайшли неушкоджений щоденник.\n\nЩоденник ви забрали, а тіло Тероніса залишили, як є.\n\nЗосталося тільки знайти камінь, який шукав Тероніс. Рене сказала, що він має бути в цій місцевості. Може, він у мурлоків...", [3] = "Знайдіть сяючий самоцвіт і поверніться до Рене Вовкогін в Астранаар зі щоденником Тероніса.", [4] = "З поверненням, {ім'я}.", [5] = "Тероніс помер?! Це жахливо, {ім'я}.\n\nУ нас ще буде час на жалобу, але зараз ми маємо зосередити наші зусилля. Я відправлю кількох стражів, аби якнайшвидше знайти тіло Тероніса.\n\nТи {стать:приніс:принесла} щоденник Тероніса і камінь, який він шукав. Чи можеш ти завершити його справу? Я спатиму спокійніше, якщо знатиму, що його смерть не була марною.", ["en"] = "Raene's Cleansing", ["tasks"] = { ["Glowing Gem"] = "сяючий самоцвіт", ["Glowing Gem (Provided)"] = "сяючий самоцвіт (видано)" } },
    [1025] = { [1] = "Найкраща оборона — це напад", [2] = "Перш ніж ти вирушиш до місячного колодязя, я маю для тебе ще одне завдання, яке допоможе жителям Ясенедолу, якщо бажаєш випробувати свої сили.\n\nУздовж дороги, що веде на схід до Далекоплинної річки, хутропузи нападають на мандрівників. Їхній зболений розум живиться страхом, а апетити втамовуються кров'ю невинних.\n\nДопоможи стражам захистити ці землі, дай цим чудовиськам скуштувати того ж милосердя, яким вони годують нас.\n\nЯ гадаю, їхні табори знаходяться на південь від дороги... будь {стать:обережний:обережна}.", [3] = "Вбийте 1 наглядача лігва, 10 тотемістів та 12 воїнів племені Гидколісних, а потім поверніться до Рене Вовкогін в Астранаар.", [4] = "Хутропузи не завжди були нашими ворогами, {ім'я}. Але часи змінюються, і тут, в темноліссі, більше немає миру.", [5] = "Хороша робота, {ім'я}. Дякую.", ["en"] = "An Aggressive Defense", ["tasks"] = { ["Foulweald Den Watcher"] = "гидколісний наглядач лігва", ["Foulweald Den Watcher slain"] = "гидколісний наглядач лігва: убито", ["Foulweald Totemic"] = "гидколісний тотеміст", ["Foulweald Totemic slain"] = "гидколісний тотеміст: убито", ["Foulweald Ursa"] = "гидколісний урса", ["Foulweald Ursa slain"] = "гидколісний урса: убито", ["Foulweald Warrior"] = "гидколісний воїн", ["Foulweald Warrior slain"] = "гидколісний воїн: убито" } },
    [1027] = { [1] = "Очищення Рене", [2] = "Останню частину жезла було віддано на зберігання друїдам Дор'даніла. Не знаю, де саме вони її сховали. Вибач, що не можу нічим допомогти.\n\nМожу лише порадити рушати дорогою, що веде до Степів. Друїди оселилися на схід від цієї дороги, та вони не зможуть тобі допомогти. Нещодавно їх було вбито... не люблю про це думати.\n\nКоли знайдеш останню частину, принеси її мені — я допоможу тобі відновити жезл.", [3] = "Знайдіть останню частину жезла Дартола та поверніться до Шел'дрін біля місячного колодязя.", [4] = "Ти {стать:знайшов:знайшла} останню частину жезла, {ім'я}?", [5] = "Ти {стать:знайшов:знайшла} останню частину жезла? Чудові вісті для тебе... і для Рене.\n\nГадаю, час його полагодити.", ["en"] = "Raene's Cleansing", ["tasks"] = { ["Iron Pommel"] = "залізне навершя", ["Iron Pommel (Provided)"] = "залізне навершя (видано)" } },
    [1028] = { [1] = "Очищення Рене", [2] = "А ось і готовий жезл, {ім'я}. Відновити його було легко... важко буде найти святилище, в якому можна його зарядити.\n\nАле для тебе, з твоєю цілеспрямованістю та сумлінністю, це завдання не таке вже й важке. Ти вже так багато {стать:досягнув:досягла}.\n\nРушай на південний схід, але будь {стать:обережний:обережна}: стежок тут мало. Дивись на північ — святилище ховається в горах, що оточують цю галявину.\n\nЯк знайдеш потрібне місце, поклади жезл на вівтар. Все інше за тебе зробить магія.", [3] = "Знайдіть потаємне святилище та зачаруйте жезл Дартола заново.", [4] = "Ви відчуваєте ледве помітну, але могутню енергію, що охоплює святилище та дерева навколо.\n\nВи ледь встигли покласти жезл на вівтар, як відчуваєте рух повітря навколо вас, поки вівтар охоплює яскраве сяйво...", [5] = "Коли сяйво зникає, ви бачите зачарований жезл в чаші вівтаря.", ["en"] = "Raene's Cleansing", ["tasks"] = { ["Reconstructed Rod"] = "відтворений жезл", ["Reconstructed Rod (Provided)"] = "відтворений жезл (видано)" } },
    [103] = { [1] = "Хранитель полум'я", [2] = "Ніч, коли загинула родина наглядача маяка, була жахливою. Я безпорадно спостерігав за тим, як сам старий Мутноок очолював атаку. Але що сталося, те сталося, і тепер життя моряків, чиї кораблі у Великому морі наближаються до небезпечних скель берегової лінії — моя турбота. Підтримувати вогонь маяка нікому, і цей обов'язок випав на мої плечі.\n\nДопоможи мені зберегти вогонь факела — принеси 5 фляг з мастилом, зібравши його зі жнивальних страховиськ.", [3] = "Принесіть 5 фляг з мастилом капітанові Сивенку на маяк Західного краю.", [4] = "Вогонь недовго горітиме без мастила, {ім'я}.", [5] = "Хвала тобі, {стать:хоробрий:хоробра} {раса:к}. Скелі узбережжя Західного краю будуть освітлені завдяки твоїй праці. Безліч життів буде врятовано, поки факел горить.\n\nМене спіткала безглузда смерть на цьому самому узбережжі. Мій обов'язок у потойбічному житті — стежити, щоб ніхто не повторив моєї долі.", ["en"] = "Keeper of the Flame", ["tasks"] = { ["Flask of Oil"] = "фляга з мастилом", ["Flask of Oil (Provided)"] = "фляга з мастилом (видано)" } },
    [1030] = { [1] = "Очищення Рене", [2] = "На жаль, я не знаю, якими були його подальші плани.\n\nЯкщо те, що він розповів про силу жезла — правда, цей артефакт дозволить тобі прийняти іншу форму. Яку саме — я не знаю.\n\nМожливо, він планував використати магію жезла, аби підібратися ближче до спотворених хутропузів. Проте навіть вільні від порчі істоти вмить знищили б його за найменшої необережності. Змінивши форму, Дартол міг би говорити з хутропузом, неушкодженим мохом скверни.\n\nРаджу почати пошуки з південно-східного узбережжя озера Містраль.", [3] = "Знайдіть хутропуза, не ураженого порчею, та поговоріть з ним, скориставшись жезлом Дартола.", [5] = "Так, так... ти {стать:мій:моя} {стать:родич:родичка}, але досі {стать:дужий:дужа}. Досі {стать:чистий:чиста}.\n\nНе знаю, як ти {стать:врятувався:врятувалася} від жорстокості нічних ельфів, але я радий знати, що я не сам.\n\nСпотворена кров тече тепер в жилах нашого роду, дитино, і цю порчу навели на нас пихаті нічні ельфи. Це вони зробили таке з нашим народом... Це вони винні в тому, що мене вигнали з племені.\n\nВ нічній темряві я й досі бачу вогнища.", ["en"] = "Raene's Cleansing", ["tasks"] = { ["Dartol's Rod of Transformation"] = "жезл трансформації Дартола" } },
    [1031] = { [1] = "Гілка Кенарія", [2] = "Анілія торкається ваших плечей, аби ви нахилилися ближче. Задихаючись, вона вказує на арку на північ звідси, а потім заплющує очі й останні слова злітають з її вуст. \"Він забрав її... Ґелтаріс...\" Ви розумієте, що останнє бажання Анілії — повернути гілку Кенарія до рук дріад.", [3] = "Вбийте Ґелтаріса та поверніть гілку Кенарія Ілліяні біля вівтаря Аессіни.", [4] = "Ти {стать:знайшов:знайшла} їх? Що сказала Анілія? Де вона?", [5] = "Анілія померла? Ні... це неможливо! Тільки вчора ми вдвох грали у лісі.\n\nНапевно, цього більше не буде...", ["en"] = "The Branch of Cenarius", ["tasks"] = { ["Branch of Cenarius"] = "гілка Кенарія", ["Branch of Cenarius (Provided)"] = "гілка Кенарія (видано)" } },
    [1032] = { [1] = "Полювання на сатирів", [2] = "Повірити не можу, що Анілії більше немає... Колись ми вдвох грали у лісі. Мені майже... сумно.\n\nАле я знаю, що може підняти мені настрій. Будь ласка, вбий сатирів, які забрали в мене Анілію! Принеси мені їх роги як доказ і я буду вічно тобі вдячна.", [3] = "Принеси 16 рогів сатирів до Ілліяни біля вівтаря Аессіни.", [4] = "Благаю, допоможи мені помститися за смерть Анілії.", [5] = "Дякую, {стать:добросердий:добросерда} {раса:к}. Дух моєї сестри радіє твоїм успіхам.", ["en"] = "Satyr Slaying!", ["tasks"] = { ["Satyr Horns"] = "роги сатира", ["Satyr Horns (Provided)"] = "роги сатира (видано)" } },
    [1033] = { [1] = "Сльоза Елуни", [2] = "Я сподівався, що ліки Оренділа врятують Релару, але боюся, що вони лише сповільнили розвиток хвороби. Ми повинні знайти потужніші ліки! На щастя, Оренділ розповів мені про інші засоби, які можна спробувати.\n\nСльоза Елуни — це камінь, який знаходиться лише в одному місці: на острові посеред Райдужного озера, що на схід від Астранаару. Оренділ сказав, що цей камінь змиє порчу... Будь ласка, {ім'я}, принеси мені сльозу Елуни й молися, щоб вона вилікувала мою дитину!", [3] = "Принесіть сльозу Елуни Пельтурасу в Астранаар.", [4] = "{ім'я}, ти {стать:знайшов:знайшла} Райдужне озеро? Чи {стать:приніс:принесла} ти сльозу?", [5] = "Ти {стать:знайшов:знайшла} її! Я додам її до юшки й молитимусь, аби вона вилікувала мою дитину.\n\nДякую! Дякую, {ім'я}!", ["en"] = "Elune's Tear", ["tasks"] = { ["Elune's Tear"] = "сльоза Елуни", ["Elune's Tear (Provided)"] = "сльоза Елуни (видано)" } },
    [1034] = { [1] = "Руїни Зорепилу", [2] = "Сльоза Елуни частково полегшила стан моєї доньки. ЇЇ більше не мучать кошмари і я вдячний богині за її благословення. Але... вона досі охоплена лихоманкою.\n\nОренділ розповів мені про морозний пил, який можна знайти в руїнах Зорепилу. Можливо, він полегшить лихоманку Релари. Збери трохи пилу та повернись до мене.\n\nТи знайдеш руїни Зорепилу на півдні, {ім'я}. Нехай Елуна прискорить твою подорож.", [3] = "Принесіть 5 жмень зорепилу Пельтурасу в Астранаар.", [4] = "Ти вже {стать:приніс:принесла} зорепил, {ім'я}?", [5] = "Ти {стать:приніс:принесла} пил! З нього я зроблю припарку — вона повинна полегшити лихоманку.\n\nЩе раз дякую, {ім'я}. Без твоєї допомоги моя дитина загинула б.", ["en"] = "The Ruins of Stardust", ["tasks"] = { ["Handful of Stardust"] = "жменя зорепилу", ["Handful of Stardust (Provided)"] = "жменя зорепилу (видано)" } },
    [1035] = { [1] = "Озеро Впалого Неба", [2] = "Релару більше не лихоманить, але вона досі дуже слабка. Я не думаю, що час поверне їй втрачені сили. Для цього знадобиться сила місячного каменя.\n\nМи збирали місячне каміння біля озера Впалого Неба на південному сході... доки не прийшли створіння Тінезарості.\n\nЇхній вождь, оракул Тінезарості, зібрав усі впалі місячні камені та зберігає їх у скарбниці. Тепер ти маєш забрати місячний камінь в оракула.\n\nБоюся, що для цього тобі доведеться його вбити.", [3] = "Заберіть впалий місячний камінь в оракула Тінезарості та принесіть його Пельтурасу в Астранаар.", [4] = "Ти {стать:здолав:здолала} оракула Тінезарості, {ім'я}? Якщо так, будь ласка, віддай мені місячний камінь. У Релари залишилося сил лише на кілька подихів!", [5] = "{ім'я}, ти {стать:врятував:врятувала} мою дочку! Я знаю, що сила місячного каменю поверне їй сили!\n\nЯ ніколи не зможу повністю віддячити тобі за допомогу, але... будь ласка, візьми це. Крім Релари, це найдорожче, що в мене є.", ["en"] = "Fallen Sky Lake", ["tasks"] = { ["Fallen Moonstone"] = "впалий місячний камінь", ["Fallen Moonstone (Provided)"] = "впалий місячний камінь (видано)" } },
    [1036] = { [1] = "Бережися, сухопутний пацюк!", [2] = "{ім'я}... так, я чув про тебе. Я чув, що Грабіжна Бухта тобі не друг, так само як і нам, піратам Кривавого Вітрила. Командувач флоту Фіраллон шукає таких же здорових і дужих {стать:чоловіків:жінок}, як ти, для виконання особливої місії.\n\nЯкщо тебе це зацікавило, вирушай на \"Багряну вуаль\" і поговори з ним. Корабель пришвартовано біля Дикого узбережжя, що на схід звідси, поруч з \"Бистриною\" і \"Дівочою вдачею\".", [3] = "Поговоріть з командувачем флоту Фіраллоном на борту \"Багряної вуалі\", що на узбережжі Тернистої долини.", [5] = "Стережися, сухопутний пацюк. Я чув, що ти з тих, хто не гребує розбоєм. Що ж, якщо Грабіжна Бухта тобі не друг, то серед піратів Кривавого Вітрила для тебе знайдеться особливе місце.\n\nАррррр...", ["en"] = "Avast Ye, Scallywag", ["tasks"] = { ["3000 reputation with Bloodsail Buccaneers"] = "3000 репутації у Піратів Кривавого Парусу" } },
    [1037] = { [1] = "Велінда Зорепісня", [2] = "Велінда Зорепісня була моєю попередницею тут в Ясенедолі. Спочатку здавалося, що вона тримала справи в Скверноліссі під контролем, але потроху її зусилля зійшли на нівець. Одного дня вона просто зникла.\n\nМене відправили сюди, аби продовжувати її справу. Проте боюся, що я нічого не знаю про жрицю. Можливо, Тін'тель Лезоткаля, одна з командирів стражів, знає щось про її зникнення.\n\nВона має зрозуміти важливість такої інформації.", [3] = "Поговоріть з Тін'тель Лезоткалею на терасі Воїнів в Дарнасі.", [5] = "Велінда Зорепісня? Про те, що жриця зникла деякий час тому, знають всі. А от щодо обставин її зникнення... таку інформацію я можу розкрити тільки з вагомої причини.", ["en"] = "Velinde Starsong" },
    [104] = { [1] = "Загроза на узбережжі", [2] = "Коли моє життя обірвалося на скелях, я й гадки не мав, що чекає мене на тому світі. Маяк тієї ночі не світив, бо старий Мутноок налякав сім'ю доглядача, і вони втекли. Потім вони повернулися та знову запалили полум'я, але Мутноок змусив слабших мурлоків напасти на маяк разом з ним. Вдруге родині доглядача не пощастило, і вони безпорадно загинули в мене на очах.\n\nУбий старого Мутноока, якщо побачиш його на березі, та принеси мені одну з його лусок, і я віддячу тобі.", [3] = "Принесіть луску старого Мутноока капітанові Сивенку на маяк Західного краю.", [4] = "Ти вже {стать:знищив:знищила} загрозу на ім'я старий Мутноок? Помічали, як він блукав уздовж узбережжя Західного краю.\n\nПовертайся до мене, коли ця огидна тварюка буде мертвою.", [5] = "Отже, це мерзенне чудовисько, Мутноок, мертве. Молодець, {ім'я}. Обірвавши своїми руками одне життя, ти, можливо, {стать:врятував:врятувала} безліч інших. Велике море, і так сповнене небезпеки, стане цієї ночі трішечки безпечнішим завдяки твоєму героїчному вчинку.", ["en"] = "The Coastal Menace", ["tasks"] = { ["Scale of Old Murk-Eye"] = "луска старого Мутноока", ["Scale of Old Murk-Eye (Provided)"] = "луска старого Мутноока (видано)" } },
    [1040] = { [1] = "Подорож до Грабіжної бухти", [2] = "Ось, нарешті знайшов. Що ж ти не {стать:сказав:сказала}, що вона недавно була тут? Так, подивимось.\n\nВелінда. Забронювала місце на Чорному Яструбі до Грабіжної Бухти. Судячи з моїх нотаток, човен прибув до місця призначення без пригод.\n\nБільше нічого не можу сказати, але вона цікавилася наземними подорожами у тій місцині, і я згадав про Разґота, водія каравану, що базується в Грабіжній Бухті. Можливо, ця Велінда подорожувала з ним.\n\nВсе, йди вже. Я не маю часу на балачки.", [3] = "Сядьте на човен до Грабіжної Бухти та поговоріть з караванщиком Разґотом.", [5] = "Так? Щось не схоже, що ти маєш товари для перевезення, тож або ти шукаєш роботу в моєму каравані — а її зараз немає — або ти розмовляєш не з тим гобліном.\n\nТо що тобі потрібно?", ["en"] = "Passage to Booty Bay" },
    [1041] = { [1] = "Караванний шлях", [2] = "Схоже, я помилявся в тобі, а таке трапляється не кожного дня.\n\nТак сталося, що я пам'ятаю цю Велінду, яку ти шукаєш. Нечасто зустрінеш жрицю з нічних ельфів, яка хоче подорожувати з моїм брудним, старим — але чудовим для перевезення будь-яких товарів! — караваном.\n\nНаші шляхи розійшлися на північній дорозі, вона прямувала до Темнодолу. Писар в тому місті зберігає всі нотатки. Може й знає щось корисне.\n\nОбережніше в джунглях — це смертельно небезпечне місце навіть в найкращі часи.", [3] = "Поговоріть з писарем Долтрі в Темнодолі.", [5] = "Зважаючи на всі дивні події останніх років, я якомога ретельніше зберігаю записи про незнайомців. Ніколи не знаєш, коли вони можуть стати в пригоді... хоча коли це трапляється, приємного мало. Але я не маю на увазі нічого поганого про Велінду, яку ти шукаєш.", ["en"] = "The Caravan Road" },
    [1046] = { [1] = "Очищення Рене", [2] = "Повертайся до свого племені й розкажи їм про свою перемогу.\n\nПокажи їм свій трофей та насолоджуйся славою...", [3] = "Принесіть череп Рана Кривавозубого та жезл Дартола Рене Вовкогін в Астранаар.", [4] = "Стражі роблять все, що можуть в Ясенедолі, але саме завдяки таким, як ти, ми досягли того, що маємо.", [5] = "То це і є череп найлютішого хутропуза в Ясенедолі?\n\nЯ дуже задоволена твоїми здібностями, {ім'я}. Стражі вдячні тобі. Сподіваюся, ми знову зможемо до тебе звернутися, коли наші люди потребуватимуть допомоги.\n\nЯ покладу цей череп та жезл Дартола в почесному місці, де всі їх зможуть побачити.\n\nТероніс пишався б тобою. Ще раз дякую.", ["en"] = "Raene's Cleansing", ["tasks"] = { ["Dartol's Rod of Transformation"] = "жезл трансформації Дартола", ["Dartol's Rod of Transformation (Provided)"] = "жезл трансформації Дартола (видано)", ["Ran Bloodtooth's Skull"] = "череп Рана Кривавозубого", ["Ran Bloodtooth's Skull (Provided)"] = "череп Рана Кривавозубого (видано)" } },
    [1048] = { [1] = "В Багряний монастир", [2] = "Поки Темну Леді турбує загроза з півночі у вигляді Короля-ліча, я займаюсь вирішенням більш нагальних проблем.\n\nОдна з найбільших проблем — мерзотні люди, що називають себе Багряним Походом. Все Тірісфальське перелісся кишить цими багряними шкідниками.\n\nВідправляйся до монастиря, {клас:к}, і покінчи з верховною інквізиторкою Білогривою та її заступниками.", [3] = "Вбийте верховну інквізиторку Білогриву, командира Багряного Походу Моґрейна, чемпіона Багряного Походу Герода та псаря Локсі та відзвітуйте Варіматрасу в Підмістя.", [4] = "Можливо я неясно висловився, {клас:к}. Ти маєш вбити верховну інквізиторку Білогриву і заодно її поплічників.\n\nПокінчи з цим фанатиком, командиром Багряного Походу Моґрейном. Прикінчи чемпіона Багряного Походу Герода та псаря Локсі з його брудними шавками.\n\nТепер йди!", [5] = "Ти гарно {стать:послужив:послужила} Темній Леді, {клас:к}. Це була непроста задача.\n\nТвоя відданість відреченим буде відзначена. А завзятість в бою не буде забута.", ["en"] = "Into The Scarlet Monastery", ["tasks"] = { ["Herod"] = "Ірод", ["Herod (Provided)"] = "Ірод (видано)", ["Herod slain"] = "Ірод: убито", ["High Inquisitor Whitemane"] = "Верховний інквізитор Вайтмейн", ["High Inquisitor Whitemane (Provided)"] = "Верховний інквізитор Вайтмейн (видано)", ["High Inquisitor Whitemane slain"] = "Верховний інквізитор Вайтмейн: убито", ["Houndmaster Loksey"] = "псар Локсі", ["Houndmaster Loksey slain"] = "псар Локсі: убито", ["Scarlet Commander Mograine"] = "командир Багряного Походу Моґрейн", ["Scarlet Commander Mograine slain"] = "командир Багряного Походу Моґрейн: убито" } },
    [1052] = { [1] = "В Багряний Похід", [2] = "Ми, учасники Багряного Походу, заявляємо свої права на землі від Вогнедолу до Тірісфальського перелісся. Ми пишаємося нашою боротьбою за чистоту Лордерона.\n\nТи {стать:зарекомендував:зарекомендувала} себе у боротьбі з невмерлими у Спустошищі. Але справжня загроза чуми криється в Лордероні.\n\nВідправляйся до міста Південнобережжя, що у Східних Королівствах. Розшукай хрестоносця Релі Благочестивого. Віддай йому мій рекомендаційний лист, і він проведе тебе до нашого Багряного монастиря.", [3] = "Віднесіть рекомендаційний лист брата Антона до Релі Благочестивого в Південнобережжя.", [4] = "Хто ти? Чого ти хочеш від мене?", [5] = "Брат Антон все ще проповідує ідеї Багряного Походу? Боже мій...", ["en"] = "Down the Scarlet Path", ["tasks"] = { ["Letter of Commendation"] = "рекомендаційний лист", ["Letter of Commendation (Provided)"] = "рекомендаційний лист (видано)" } },
    [1055] = { [1] = "Очищення Рене", [2] = "Нарешті ви тримаєте в руках відтворений жезл. Шел'дрін захоче почути про ваші успіхи.", [3] = "Поверніться до Шел'дрін біля місячного колодязя.", [5] = "Тобі вдалося, {ім'я}! Молодець!", ["en"] = "Raene's Cleansing" },
    [1056] = { [1] = "Подорож до Каміннопазуристого піку", [2] = "Лісові духи кажуть про твою хоробрість і жагу до подорожей.\n\nНа півдні, неподалік від озера Містраль, є Пазуродертий тунель. Через нього ти зможеш дістатися до місцини, що зветься Вітрокосі скелі в Каміннопазуристих горах. Коли ти опинишся там, рушай на південний захід повз Скельнодонне озеро, а потім на північ й вгору крутим схилом, аж поки не дістанешся до Каміннопазуристого піку.\n\nТам на тебе чекатиме хранитель Альбаґорм. Слухайся його наказів, {раса:к}.\n\nПодорож буде небезпечною.", [3] = "Рушайте до хранителя Альбаґорма на Каміннопазуристий пік.", [5] = "Нарешті ти {стать:прибув:прибула}. Бачу, Фалдріс прислухався до лісових духів...", ["en"] = "Journey to Stonetalon Peak" },
    [1069] = { [1] = "Яйця мохового павука", [2] = "Омлети з павучих яєць - це новий хіт в Грабіжній Бухті! Проблема в тому, що... в бухті не має яєць.\n\nЯ відчуваю запах прибутку!\n\nНа північному заході Каміннопазуристих гір, у Вітрокосих скелях та Сиширському каньйоні, живуть мохові павуки. Принеси мені їхні яйця, а я заплачу від душі!\n\nУ Вітрокосих скелях ти знайдеш яйця під тим, що залишилось від дерев.\n\nЩодо Сиширського каньйону... ну, якщо у тебе слабкий шлунок, можливо, варто збирати яйця лише у Вітрокосих скелях...", [3] = "Принесіть 15 яєць мохового павука Мебоку Міцріксу у Брашпиль.", [4] = "Ти {стать:роздобув:роздобула} яйця, {ім'я}? А то я вже уклав угоду про постачання з завідувачем причалу Запамороком!", [5] = "Тобі вдалося! Дякую!\n\nЯ відправлю їх Запамороку та організую перевезення до Грабіжної Бухти. Я вже відчуваю смак прибутку!\n\nОсь, твоя доля, {ім'я}. Ця угода не відбулася б без тебе.", ["en"] = "Deepmoss Spider Eggs", ["tasks"] = { ["Deepmoss Egg"] = "яйце мохового павука", ["Deepmoss Egg (Provided)"] = "яйце мохового павука (видано)" } },
    [1070] = { [1] = "На варті в Каміннопазуристих горах", [2] = "Вітаю, {ім'я}.\n\nСудячи з твого вигляду, ти {стать:сповнений:сповнена} жаги до мандрів. Ти {стать:бував:бувала} у Каміннопазуристих горах? Ця земля потерпає від ТзНБ \"Авантюра\" та інших ворогів нічних ельфів.\n\nНещодавно вартова Вовкогін відправила туди мою подругу Кейлу Тінеспис, аби дослідити, що відбувається з цими землями, але я досі не отримала від неї звістки. Мене ще більше непокоїть те, що Альянс відправив з нею гномського мага... вірна ознака неприємностей.\n\nМожеш знайти її та доповісти мені?", [3] = "Знайдіть Кейлу Тінеспис, яка стоїть на варті долини біля Вітрокосих скель в Каміннопазуристих горах.", [5] = "А, ти {стать:прибув:прибула} з Ясенедолу за наказом Тари. Я так сумую за нею, моєю батьківщиною та друзями. Мабуть, її справи в лавах стражів йдуть добре, якщо вона наймає мандрівників для інших завдань. Я пишаюся нею.\n\nДуже рада познайомитися з тобою, {ім'я}.", ["en"] = "On Guard in Stonetalon" },
    [1073] = { [1] = "Невмілість + хімікати = веселощі", [2] = "Хахаха... тобі потрібен нітроміргліцероній, щоб зупинити гоблінів від знищення лісу?\n\nМені байдуже, знаєш ти Ґаксима чи ні... Я дам тобі цю речовину, тільки щоб побачити, як ти або вони розлетяться на дрібні шматочки.\n\nАле є одна проблема: в мене закінчилися хімікати.\n\nАле ось що я тобі скажу: ти принесеш мені потрібне зілля і я відразу тобі дещо приготую.\n\nПринаймні, ти зможеш довести, що розумієш щось в алхімії, перш ніж я дам тобі зразок свого найвеличнішого творіння.", [3] = "Принесіть 4 крихітних зілля мани та 2 крихітні еліксири стійкості Ломаку Зубчастику в Залізогарт.", [4] = "Я не можу створити нітроміргліцероній, не маючи зілля... воно життєво необхідне для його створення.", [5] = "Це підійде.\n\nЯкби я не знав тебе краще, {стать:незнайомцю:незнайомко}, я б подумав, що ти щось розумієш в алхімії. Добре, добре... Світ — це не тільки мечі та чаклунство, чи не так?", ["en"] = "Ineptitude + Chemicals = Fun", ["tasks"] = { ["Elixir of Minor Fortitude"] = "крихітний еліксир стійкості", ["Elixir of Minor Fortitude (Provided)"] = "крихітний еліксир стійкості (видано)", ["Minor Mana Potion"] = "крихітне зілля мани", ["Minor Mana Potion (Provided)"] = "крихітне зілля мани (видано)" } },
    [1074] = { [1] = "Невмілість + хімікати = веселощі", [2] = "Тримай, {стать:незнайомцю:незнайомко}. Але будь {стать:обережним:обережною}... це нестабільна речовина.\n\nЯкщо Ґаксим тобі справді друг, передай йому привіт від мене. Якщо ж ні — веселись, підриваючи себе.", [3] = "Принесіть нітроміргліцероній Ґаксиму Іржошипу в Каміннопазуристі гори.", [4] = "О, добре, добре, ти {стать:повернувся:повернулася}.", [5] = "Ти бездоганно {стать:виконав:виконала} завдання, {ім'я}.\n\nНГ-5 - незамінний компонент для підриву вагонів з вибухівкою.\n\nЩо? Так, вибухівка... цілі вагони. Це ідеальний маневр, щоб відвести увагу, кажу тобі... просто зачекай і побачиш.", ["en"] = "Ineptitude + Chemicals = Fun", ["tasks"] = { ["NG-5"] = "НГ-5", ["NG-5 (Provided)"] = "НГ-5 (видано)" } },
    [1078] = { [1] = "Пошук для Морена", [2] = "Мандрівники постійно запитують мене про Каміннопазуристі гори. Здається, це популярне місце для шукачів пригод, хтось шукає там виверн, хтось елементалів, а хтось співпрацює з ТзНБ \"Авантюра\".\n\nВ Обвугленій долині, що ховається в Каміннопазуристих горах, колись мешкали особливі види василісків, чия луска, розтерта в пил, буде чудовим реагентом для деяких моїх заклинань.\n\nЯкщо ці василіски ще живуть там, я б хотів отримати кілька їхніх лусок.\n\nЯкщо ти не поспішаєш, виділи трохи часу для цього, я можу добре заплатити.", [3] = "Принесіть 8 кристалічних лусок Колліну Морену в Штормовій.", [4] = "Привіт знову, {ім'я}.\n\nТобі вдалося дістати луску з тієї долини в Каміннопазуристих горах?", [5] = "Це чудово, {ім'я}. Дуже дякую тобі.\n\nМожливо, у майбутньому я також зможу допомогти тобі.", ["en"] = "Retrieval for Mauren", ["tasks"] = { ["Crystalized Scales"] = "кристалічна луска", ["Crystalized Scales (Provided)"] = "кристалічна луска (видано)" } },
    [108] = { [1] = "<TXT> Таємнича винагорода", ["en"] = "<TXT> Mystery Reward" },
    [1081] = { [1] = "Запрошення від Тіранди", [2] = "{ім'я}, я впевнена, що Тіранда Шелест Вітру сама б хотіла подякувати тобі за участь в цьому завданні.\n\nНа перший погляд, здається, що це не так, але те, що було зроблено з твоєю допомогою, зміцнить наші позиції в Каміннопазуристих горах.\n\nЯкщо ти й далі хочеш допомагати нам у боротьбі з цим звірством, зустрінься з Тірандою в храмі Місяця у Дарнасі.", [3] = "Знайдіть Тіранду Шелест Вітру в Дарнасі.", [5] = "Вітаю тебе, {ім'я}. Мені доводилося чути твоє ім'я раніше і я рада, що не зважаючи на свій вік, ти вже {стать:обрав:обрала} свій шлях.\n\nЦе буде честю для мене, якщо ти приймеш цей подарунок на знак подяки.", ["en"] = "Reception from Tyrande" },
    [1090] = { [1] = "Накази Ґерензо", [2] = "Знаєш, колись я був другою за важливістю людиною у цьому місці. Усе змінилося, коли Ґерензо прийшов до влади. Він звільнив мого керівника, Зіза Фіззікса і відправив мене працювати в шахти. Але Зіз сказав мені залишатися тут і збирати інформацію. Його нове керівництво добре заплатить нам, якщо ми дізнаємося про плани Ґерензо.\n\nТак чи інакше, я знаю, що Ґерензо наказав видобути якомога більше цієї золотисто-зеленої руди. Я можу дістати зразок, щоб ти {стать:відніс:віднесла} його Зізу, але в цей час тобі доведеться стежити чи не наближається варта.", [3] = "Отримайте зразок таємничої руди у Пізніка, коли він добуде її.", [4] = "Обережно, тут постійно ходять патрулі та робітники і якщо нас впіймають, можуть бути проблеми.", [5] = "Дякую, {ім'я}. Було кілька небезпечних моментів і ми, мабуть, привернули до себе забагато уваги.\n\nАле важливо те, що у нас є зразок руди й нам потрібно якнайшвидше віднести його Зізу.", ["en"] = "Gerenzo's Orders", ["tasks"] = { ["Keep Piznik safe while he mines the mysterious ore"] = "Захистіть Пізніка, поки він видобуває таємничу руду." } },
    [1092] = { [1] = "Накази Ґерензо", [2] = "Гадаю, мені теж варто подумати про те, як вибратися звідси. Керівництво швидко дізнається про те, що тут сталося і я впевнений, що вони не будуть раді зустрічі зі мною.\n\nЯ виберуся звідси й зустрінуся з Зізом. Сподіваюся, він зможе знайти мені нову роботу!\n\nЯ спробую трохи прибрати тут, а ти {стать:повинен:повинна} негайно віднести зразок руди Зізу. Він сказав мені, що розмістив табір десь на західній стороні Вітрокосої скелі. Щасти тобі.", [3] = "Доставте невідому руду Зізу Фіззіксу в Каміннопазуристі гори.", [4] = "Я можу тобі чимось допомогти?", [5] = "Ох, я так і знав, що вчинив правильно, коли попросив Пізніка залишитися. Я впевнений, що інженерам з Підштольні буде дуже цікаво подивитися на це...\n\nЗвісно, я залишу собі шматочок, але якщо вони цього не знатимуть, їм це не зашкодить, чи не так?", ["en"] = "Gerenzo's Orders", ["tasks"] = { ["Unidentified Ore"] = "невідома руда", ["Unidentified Ore (Provided)"] = "невідома руда (видано)" } },
    [1093] = { [1] = "Супер дереворуб 6000", [2] = "ТзНБ \"Авантюра\" напакостила тут, чи не так? Про що вони думали? Гоблінська компанія найняла гнома!\n\nНа щастя для мене, Гуркоклапан бачить генія з одного погляду. Найняв мене відразу, як тільки мене вигнали звідти!\n\nМені сказали, що ТзНБ \"Авантюра\" будує якісь величезні дереворізальні верстати й Клапан хоче, щоб я викрав для нього креслення. На жаль, Ґерензо — клятий гном — хоче мене вбити... Може, ти замість мене викрадеш ті креслення? Вони мають бути в одного з їхніх операторів.", [3] = "Дістаньте креслення Супер дереворуба 6000 для Зіза Фіззікса в Каміннопазуристих горах.", [4] = "Ти {стать:дістав:дістала} креслення? Я хочу справити враження на нового керівника. Сподіваюся, коли він переконається в моїй лояльності — ну, наскільки його взагалі можна переконати... гоблінська честь, розумієш? — він знайде ідеальне застосування моєму дивовижному розуму.", [5] = "Чекай, це те, що я думаю? Чудово!\n\nА тепер подивимось. Ого... і як розуміти ці нісенітниці?... не можу збагнути, чим ці гноми думають. Я здивований, що вони взагалі змогли зробити колесо, не кажучи вже про літальні апарати, які їм так подобаються.", ["en"] = "Super Reaper 6000", ["tasks"] = { ["Super Reaper 6000 Blueprints"] = "креслення Супер дереворуба 6000", ["Super Reaper 6000 Blueprints (Provided)"] = "креслення Супер дереворуба 6000 (видано)" } },
    [1094] = { [1] = "Подальші вказівки", [2] = "У цьому конверті вся інформація, яку мені вдалося дістати, до того як мене виставили за двері... Внутрішні документи ТзНБ \"Авантюра\", деякі інструкції, технічні речі... І, звісно, креслення Супер дереворуба 6000.\n\nГуркоклапан оселився в Брашпилі у Степах. Знайти його буде нескладно, він маленький зелений тип.", [3] = "Доставте запечатаний конверт Гуркоклапану в Степи.", [4] = "Привіт! Чим я можу тобі допомогти?", [5] = "Фіззікс, так? Не можу сказати, що я йому довіряю, але інформація здається правдивою. Що б я тільки не віддав, щоб це ТзНБ \"Авантюра\" від мене відчепилося.\n\nХоча вони привезли з собою непогані машини... Не буду заперечувати, деякі їхні винаходи дійсно корисні, ми їх використовуємо.", ["en"] = "Further Instructions", ["tasks"] = { ["Sealed Envelope"] = "запечатаний конверт", ["Sealed Envelope (Provided)"] = "запечатаний конверт (видано)" } },
    [1095] = { [1] = "Подальші вказівки", [2] = "В Підштольні цей гном, найнятий ТзНБ \"Авантюра\", викликав неабиякий переполох. Торгові принци не схвалюють спілкування Раздунка з цим Ґерензо.\n\nШарадник попросив мене розібратися з цією проблемою і я впевнений, що він отримав ці вказівки від одного з торгових принців. Звісно, директор мені цього не сказав. Скажімо так, у мене є здогадки.\n\nХай там як, але Ґерензо треба усунути, це буде хорошим випробуванням для Фіззікса.", [3] = "Віднесіть нові вказівки Зізу Фіззіксу в Каміннопазуристі гори.", [5] = "Усунути Герензо? Я не заперечую проти такої перспективи.\n\nГноми й так досить неприємний народ, а цей Ґерензо тільки погіршує ситуацію. Судячи з усього, він був одним з головних інженерів у Гномреґані, де працював над секретним проєктом, але нам так і не вдалося проникнути до Дун-Морога та дізнатися деталі. Це був провал. У наших звітах говориться, що цей проєкт буквально вибухнув у них перед носом.", ["en"] = "Further Instructions" },
    [1096] = { [1] = "Ґерензо Свистоключ", [2] = "Я зустрічав Ґерензо одного разу і скажу тобі, вигляд у нього не з приємних. Його плоть виглядає так, ніби гниє, він замінив деякі частини свого тіла на механічні та причепив до себе метал та шестерні.\n\nНа північному сході звідси, високо над Скельнодонним озером, біля водяного колеса, стоїть Ґерензо та наглядає за всією територією. Я не зміг би пробратися туди, не кажучи вже про те, щоб здолати Ґерензо... Але, здається, ти зможеш це зробити.\n\nЯкщо ти вб'єш його для мене, я щедро віддячу за це!", [3] = "Принесіть механічну руку Ґерензо Свистоключа та віддайте її Зізу Фіззіксу в Каміннопазуристих горах.", [4] = "Гуркоклапан захоче якісь докази того, що Ґерензо мертвий. Думаю, його механічна рука підійде.", [5] = "Поглянь на цю штуку... Тільки гном міг таке придумати. Я не розумію, навіщо відрізати руку і заміняти її цією штукою, якщо можна було просто залишити обидві руки й причепити третю!\n\nГноми, скажу я тобі...\n\nПринаймні, Ґерензо мертвий. Сподіваюся, цього буде достатньо і Гуркоклапан назначить мене в одну з майстерень Спілки штукарів у Пристроблясі, а може, навіть у Підштольні.", ["en"] = "Gerenzo Wrenchwhistle", ["tasks"] = { ["Gerenzo's Mechanical Arm"] = "механічна рука Ґерензо", ["Gerenzo's Mechanical Arm (Provided)"] = "механічна рука Ґерензо (видано)" } },
    [1099] = { [1] = "Гобліни перемогли!", ["en"] = "Goblins Win!", ["tasks"] = { ["Goblin Race Ticket"] = "квиток на перегони гоблінів" } },
    [110] = { [1] = "Дослідження частин комах", [2] = "Я збираюся приділити деякий час огляду спорядження землеміра Полотноміра... а також привести до ладу його особисті речі. Мені здається, що це не остання наша втрата у боротьбі з цими комахами.\n\nЯ хотів би, щоб ти {стать:зайшов:зайшла} до алхіміка Товкачера, щоб перевірити, чи готові результати досліджень частин комах, які ми надіслали йому. І якщо вони готові — принеси їх мені.", [3] = "Поверніться за результатами досліджень частин комах до алхіміка Товкачера в Пристроблях.", [5] = "Так, результати готові. І вони... щонайменше, тривожні.\n\nНа жаль, наші підозри підтвердилися, і комах контролює невідома зовнішня сила. І не просто невідома, а й дуже зла. Ці комахи перетворилися на справжніх спустошників. Я ніколи не бачив нічого подібного.", ["en"] = "Insect Part Analysis" },
    [1100] = { [1] = "Журнал Однобрового", [2] = "Ви повільно розгортаєте пошарпаний щоденник Генріґа Однобрового...", [3] = "Прочитайте щоденник Генріґа Однобрового.", [4] = "Судячи з твого стурбованого погляду, сталося щось погане...", [5] = "Кажеш, ти {стать:знайшов:знайшла} цей щоденник у мертвого дворфа? Дай-но мені трохи часу, я прогляну сторінки...", ["en"] = "Lonebrow's Journal", ["tasks"] = { ["Lonebrow's Journal"] = "щоденник Однобрового", ["Lonebrow's Journal (Provided)"] = "щоденник Однобрового (видано)" } },
    [1103] = { [1] = "Поклик води", [2] = "Здоров, {стать:брате:сестро}! Ти теж {стать:прийшов:прийшла} очистити тутешні води та довести Іслен своє розуміння?\n\nЯ щойно сам переміг зіпсованого духа води, і якраз збираюся покласти його наручі та залишки води в жаровню.\n\nЩо це? А... Тьєв добре розуміє, коли щось йде не так. Що ж, я можу допомогти тобі, якщо тобі знову потрібен чистий дух води.\n\nПринеси мені сапту води від Іслен, як доказ твоєї готовності, я почекаю.", [3] = "Якщо вам не вдалося поговорити з меншим проявом води, принесіть сапту води Тьєву Мордуну у Срібнохвойний праліс.", [4] = "У тебе є сапта, {стать:брате:сестро}?\n\nЯ знаю ше кой-кого, хто мав проблеми після перемоги над злим водяним духом — кажеться, він сильно довго ждав і вийшов з світу духів надто швидко. Не хочу, шоб це сталося з кимось ше, тож пожду тут трохи — впевнюсь, шо моя допомога більше нікому не треба.", [5] = "А-а-а, то ти {стать:готовий:готова}...\n\nЯ положу свої речі в жаровню, а ти зможеш поговорить з духом.\n\nІ не переживай, шо не побачиш потойбічний світ за допомогою сапти... Старий Тьєв знає коє-шо про те, як працює магія сапти.\n\nПішли зо мною до святилища, поговорим з духами разом, {стать:брате:сестро}.", ["en"] = "Call of Water", ["tasks"] = { ["Water Sapta"] = "сапта води", ["Water Sapta (Provided)"] = "сапта води (видано)" } },
    [1104] = { [1] = "Отрута соляних рівнин", [2] = "У мене є дуже багато нових креслень для нового боліда! Так багато! І я маю всіх їх спробувати!\n\nЯ працюю над новим видом палива. Палива, яке буде горіти дуже-дуже сильно!! У мене все ще немає ідеальної формули, але я знаю, що мені потрібно...\n\nУ скорпідів, що тиняються Мерехтливими рівнинами, є отрута в якій міститься купа солі. Вона унікальна! І це саме те, що мені потрібно!\n\nПринеси мені отруту і повір мені, наш болід буде літати!!", [3] = "Принесіть 6 порцій солоної отрути скорпіда Фіззлу Латуноболту на Мерехтливі рівнини.", [4] = "Гей, гей, гей! Ти {стать:приніс:принесла} отруту??", [5] = "Чудово! Ця отрута ідеально підійде! Дякую, {ім'я}!\n\nТепер, я маю прокип'ятити її, додати скіпер-отомер та нега-каталізатор і... Дідько! Де мої записи!?", ["en"] = "Salt Flat Venom", ["tasks"] = { ["Salty Scorpid Venom"] = "солона отрута скорпіда", ["Salty Scorpid Venom (Provided)"] = "солона отрута скорпіда (видано)" } },
    [1105] = { [1] = "Міцні панцири", [2] = "Мій брат працює над новим паливом для його боліда. Він у цій справі просто геній. Такий геній, що... я думаю, що його нове паливо, яке він розробляє, настільки потужне, що воно роз'їсть усю машину!\n\nТому я хочу зміцнити паливні баки до того, як це станеться.\n\nТут, на рівнинах, живуть черепахи з дуже міцними панцирами. Я хочу використати їх, щоб створити нові баки для нашого боліда.\n\nНу як, хочеш взятися за цю роботу і принести мені кілька панцирів?", [3] = "Принесіть 9 міцних черепашачих панцирів Віззлу Латуноболту на Мерехтливі рівнини.", [4] = "Мій брат має неабиякі успіхи в розробці палива, і це мене хвилює. Я маю якнайшвидше почати працювати над паливними баками з черепашачих панцирів!\n\n{ім'я}, ти вже {стать:зібрав:зібрала} їх?", [5] = "Вони у тебе! Дякую, {ім'я}!\n\nОго, та вони ще твердіші, ніж я очікував! Хех, коли буду з ними працювати, я погну всі свої інструменти!", ["en"] = "Hardened Shells", ["tasks"] = { ["Hardened Tortoise Shell"] = "міцний черепашачий панцир", ["Hardened Tortoise Shell (Provided)"] = "міцний черепашачий панцир (видано)" } },
    [1106] = { [1] = "Мартек Вигнанець", [2] = "Я розробляю новий двигун, який змусить їхати машину швидше! Достатньо швидко, щоб летіти, я знаю про що кажу! Мені лише потрібно зробити поршні, які зможуть витримати дуже велике навантаження. Всі мої випробування провалилися тому, що я не можу зробити поршні достатньо міцними!\n\nАле є дехто, хто може знати, як їх зробити.\n\nЙого звати Мартек Вигнанець. Він прекрасний коваль, і знає про метали більше, ніж будь-хто. Передай йому цього листа, я впевнений, що він зможе допомогти!\n\nАле він дуже далеко — в Азероті, в Безплідних краях, в таборі з гобліном!\n\nЗнайди його!", [3] = "Принесіть лист Фіззла Мартеку Вигнанцю в Безплідні краї.", [4] = "Що ж, ти {стать:знайшов:знайшла} мене. Вітаю.\n\nТи {стать:прийшов:прийшла} сюди через сокиру, яку я зробив для Ґат'Ільзоґґа? Чи ти тут, щоб повернути честь герцогині Памеї?\n\nА взагалі-то, мені байдуже, чому ти тут. Якщо ти {стать:прийшов:прийшла} сюди заради бійки, тоді давай швидше з цим покінчимо...", [5] = "Фіззл прислав тебе? Це ж зовсім інша справа! Звичайно, я допоможу тобі. Фіззл та його брат — одні з небагатьох, хто не бажає мені смерті!\n\nТож Фіззл хоче зробити поршні, га? Поршні, які витримають будь-які заплановані ним навантаження. А якщо я добре знаю Фіззла, то його нова машина — це вулкан на колесах!", ["en"] = "Martek the Exiled", ["tasks"] = { ["Fizzle Brassbolts' Letter"] = "лист Фіззла Латуноболта", ["Fizzle Brassbolts' Letter (Provided)"] = "лист Фіззла Латуноболта (видано)" } },
    [1107] = { [1] = "Засіб проти тертя", [2] = "Наш болід — найшвидша штукенція, яку можна знайти на рівнинах. Настільки швидка що... Я боюся, що тертя просто розірве її на частини!\n\nЩоб запобігти цьому, мені потрібно зробити матеріал, яким можна буде покрити рухливі частини машини. Цей матеріал повинен бути міцним, але не крихким, і також має бути стійким до соляної корозії, інакше він довго не протягне на Мерехтливій рівнині.\n\nТи коли-небудь {стать:чув:чула} про Підступний риф, {ім'я}? Він знаходиться біля узбережжя Тернистої долини. Там живуть Солонолускі мурлоки живуть, і їхні хвостові плавники чудово підійдуть для мого матеріалу.", [3] = "Принесіть 10 вкритих сіллю хвостових плавників Віззлу Латуноболту на Мерехтливі рівнини.", [4] = "Ти {стать:приніс:принесла} хвостові плавники? Якщо я не зможу захистити болід від його ж власної швидкості, вона не довго протягне.", [5] = "Дякую, {ім'я}! Після того, як я подрібню плавники та об'єднаю їх з іншими інгредієнтами, матеріал буде готовий. І після цього болід буде вбережений від власної швидкості.\n\nПринаймні, поки не вріжеться у щось...", ["en"] = "Encrusted Tail Fins", ["tasks"] = { ["Encrusted Tail Fin"] = "вкритий сіллю хвостовий плавник", ["Encrusted Tail Fin (Provided)"] = "вкритий сіллю хвостовий плавник (видано)" } },
    [1108] = { [1] = "Індурій", [2] = "Я тут не тільки тому, що хочу триматися від усіх подалі. В Безплідних краях знаходиться дуже багато металу, {ім'я}, та його не кожен зможе добути.\n\nЦей метал називається індурієм, і подейкують, що він має дивовижну стійкість до температур та механічних навантажень. Це може знадобитися для машини Фіззла.\n\nДавай-но це перевіримо. Принеси мені зразки індурія, і я досліджу його властивості.\n\nСправжня індурієва руда знаходиться глибоко в Ульдамані, але Каменесклепі троги Безплідних країв інколи носять з собою шматки цього металу. Принеси їх мені.", [3] = "Принесіть 10 шматків індурію Мартеку Вигнанцю в Безплідні краї.", [4] = "Ти {стать:знайшов:знайшла} шматки індурію, {ім'я}? Я вже розігрів свою кузню та готовий перевірити цей метал.", [5] = "О, так, це підійде. А тепер ми нагріємо їх та подивимося, як вони протримаються...", ["en"] = "Indurium", ["tasks"] = { ["Indurium Flake"] = "шматок індурію", ["Indurium Flake (Provided)"] = "шматок індурію (видано)" } },
    [1110] = { [1] = "Деталі болідів", [2] = "Хех, з усіма цими перегонами, які вони тут проводять, не дивно що тут стається так багато аварій. Оглянься навколо — всі Мерехтливі рівнини всипані уламками болідів!\n\nІ за всі ці деталі гноми та гобліни можуть добряче заплатити. Вони завжди шукають, який би ще мотлох прикріпити на свої машини.\n\nТож йди та збери ці деталі. Принеси мені купку, і я тобі добре заплачу.", [3] = "Принесіть 30 деталей болідів Крейвелу Вуглебороду на Мерехтливі рівнини.", [4] = "{ім'я}, ти вже {стать:був:була} на рівнинах? Ти {стать:приніс:принесла} мені купку деталей, які я просив?", [5] = "Вау, тільки поглянь на все це! В цій купі мотлоху є багато класних штукенцій. Я можу продати їх за чималі гроші.\n\nІ... це що, відірване вухо?? Йой! Хех, не хотів би я бути на місці цього пілота!\n\nДякую, {ім'я}. Ось твоя плата. І ще безплатна порада...\n\nЯкщо добре пошукати, то завжди можна знайти вигоду в чиїйсь біді.", ["en"] = "Rocket Car Parts", ["tasks"] = { ["Rocket Car Parts"] = "деталі боліда", ["Rocket Car Parts (Provided)"] = "деталі боліда (видано)" } },
    [1111] = { [1] = "Завідувач причалу Запаморок", [2] = "Моя робота полягає в тому, щоб виконувати замовлення покупців. І гноми замовили у мене комплект запчастин, який прибув до Брашпиля ще тиждень тому. Але у мене не було нагоди забрати їх.\n\n{стать:Готовий:Готова} до невеликої прогулянки? Вирушай до Брашпиля та віддай це замовлення запчастин завідувачу причалу Запамороку — він має бути на причалі.\n\nЗроби це для мене, і я знайду для тебе більше роботи.\n\nРобота, між іншим, {стать:друже:подруго}, потенційно дуже прибуткова...", [3] = "Принесіть замовлення запчастин Крейвела завідувачу причалу Запамороку в Брашпиль.", [4] = "Наступний! Відправлення чи отримання?", [5] = "О, так! Запчастини для Крейвела. Радий, що ти тут. Ці штуки пролежали тут не один день, і я вже переживав, що вони поржавіють!", ["en"] = "Wharfmaster Dizzywig", ["tasks"] = { ["Kravel's Parts Order"] = "замовлення запчастин Крейвела", ["Kravel's Parts Order (Provided)"] = "замовлення запчастин Крейвела (видано)" } },
    [1112] = { [1] = "Запчастини для Крейвела", [2] = "Ось пакунок для Крейвела, {ім'я}. Коли віднесеш, скажи йому... захоче ще особливих замовлень — най розрахується з боргами спершу!", [3] = "Віднесіть Крейвелу Вуглебороду його запчастини на Мерехтливі рівнини.", [4] = "Ти вже {стать:забрав:забрала} запчастини з Брашпиля?", [5] = "О, запчастини, ти {стать:приніс:принесла} їх! Треба віддати їх гномам, але спершу....\n\nДавай обережненько заберемо одну маленьку штучку...", ["en"] = "Parts for Kravel", ["tasks"] = { ["Kravel's Parts"] = "запчастини Крейвела", ["Kravel's Parts (Provided)"] = "запчастини Крейвела (видано)" } },
    [1113] = { [1] = "Ревнісні серця", [2] = "Нащо мені це рідкісне гуано, спитаєш ти мене. Що ж, в цьому експерименті ми поглянемо, як взаємодіють між собою діаметрально протилежні сутності. Особливо, в токсичному середовищі, для... жахливіших результатів.\n\nНа північному сході Тірісфальського перелісся знаходиться Багряний монастир. В ньому живуть божевільні послідовники Багряного Походу. Вбий їх і принеси мені їх ревнісні серця.\n\nЦе буде надзвичайно!", [3] = "Принесіть майстру-аптекару Фаранеллу в Підмістя 20 ревнісних сердець.", [4] = "Ти вже {стать:повернувся:повернулась} з Багряного монастиря? Для цього чудового експерименту мені знадобиться багато сердець!\n\nПевен, Варіматрас та Темна Леді також будуть раді позбавленню від цієї багряної нечисті.", [5] = "Ох, яка чудова кривава картина, {ім'я}! Твої успіхи неймовірні!", ["en"] = "Hearts of Zeal", ["tasks"] = { ["Heart of Zeal"] = "ревнісне серце", ["Heart of Zeal (Provided)"] = "ревнісне серце (видано)" } },
    [1114] = { [1] = "Доставка гномам", [2] = "Що ж, тепер, коли у мене є все, що мені потрібно, віддай ці запчастини Фіззлу Латуноболту. Він дуже довго чекав на них. Впевнений, що він навіть не помітить відсутність однієї маленької деталі.\n\nНе варто навіть говорити йому, що я її забрав. Ця деталька зовсім крихітна й абсолютно не потрібна.\n\nСлово честі.", [3] = "Віднесіть крихкі запчастини для машини Фіззлу Латуноболту на Мерехтливі рівнини.", [4] = "У тебе є дещо для мене? Чудово! Давай-но подивимось...", [5] = "Це вони! Мої гідрохраповики та підсилювальні болти! Саме те, що треба! Дякую!", ["en"] = "Delivery to the Gnomes", ["tasks"] = { ["Delicate Car Parts"] = "крихкі запчастини для машини", ["Delicate Car Parts (Provided)"] = "крихкі запчастини для машини (видано)" } },
    [1115] = { [1] = "Пліткар", [2] = "Що ж, з гномами ми розібрались, саме час для послуги гоблінам!\n\nКажуть, що гоблінський пілот Назз Пароварченко не завжди виступав під цим іменем. І мені цікаво, чому він змінив його. Дуже цікаво... чи таємниця це? І наскільки ця таємниця цінна для нього?\n\nЯкщо хтось і знає правду, то це хіба що Кронжек з Грабіжної Бухти, на півдні Тернистої долини. Поговори з Кронжеком і запитай у нього про пілота.\n\nЯкщо отримаєш цінну інформацію — ми знайдемо, як отримати з неї вигоду.", [3] = "Поговоріть з Кронжеком в Грабіжній Бухті.", [5] = "Хочеш дізнатись про Назза Пароварченка? Це ж наче пілот з Мерехтливих рівнин?\n\nТак, я можу роздобути інформацію про нього... але це буде аж ніяк не просто. І не швидко.\n\nІ не дешево.", ["en"] = "The Rumormonger" },
    [1116] = { [1] = "Пудра блаженства на болоті", [2] = "Збір інформації на Назза — це непроста справа, {ім'я}. Зовсім непроста. Але якщо вже ти {стать:прийшов:прийшла} аж з Мерехтливих рівнин за нею... може ще трішки пройдешся?\n\nЕмм... чому б тобі не зібрати для мене дещо, поки я виходжу на своїх інформаторів?\n\nХмм... що ж би це могло бути? Як щодо пудри блаженства з дракончиків на болоті Скорбот? О так, я б хотів трішки цієї пудри в колекцію до свого нюхального тютюну.\n\nДістань її для мене, {ім'я}, і я поділюсь з тобою всією потрібною тобі інформацією.", [3] = "Принесіть 10 дрібок пудри блаженства Кронжеку в Грабіжну Бухту. Пудру можна зібрати з дракончиків на болоті Скорбот.", [4] = "Ти вже {стать:повернувся:повернулась}? {стать:Дістав:Дістала} мою пудру блаженства?", [5] = "Ти тільки глянь на це! Це ж пудра блаженства!\n\nНу і як тобі болото, {ім'я}? Кажуть, що там нормальної їжі й вдень зі свічками не знайдеш.", ["en"] = "Dream Dust in the Swamp", ["tasks"] = { ["Speck of Dream Dust"] = "дрібка пудри блаженства", ["Speck of Dream Dust (Provided)"] = "дрібка пудри блаженства (видано)" } },
    [1117] = { [1] = "Чутки для Крейвела", [2] = "Мені довелось зробити декілька послуг, подарувати декому рідкісну пляшку ельфійського вина, і навіть робити складні висновки самостійно! І все ж я знайшов інформацію, яку ти {стать:шукав:шукала}.\n\nОсь, я написав листа з дуже цікавими рядками про нашого дружка, Назза Пароварченка. Роби з цим, що хочеш — для мене це надто небезпечна інформація.\n\nАле нікому не кажи де її {стать:дістав:дістала}!", [3] = "Віднесіть гоблінські чутки Крейвелу Вуглебороду на Мерехтливі рівнини.", [4] = "{стать:Знайшов:Знайшла} щось на Назза Пароварченка? Будь-що, що він хотів би залишити у таємниці?", [5] = "Так-так-так! Це цікаво... дуже цікаво. Хех, мабуть, я мушу вклонитись перед гоблінським пілотом під час наступної зустрічі.\n\nЦе дуже цінна інформація, {ім'я}. Певен, що Назз добряче заплатить за те, щоб його таємниця залишалась... таємницею.", ["en"] = "Rumors for Kravel", ["tasks"] = { ["Goblin Rumors"] = "гоблінські чутки", ["Goblin Rumors (Provided)"] = "гоблінські чутки (видано)" } },
    [1118] = { [1] = "Назад до Грабіжної Бухти", [2] = "{Ім'я}, ти {клас:н}, {стать:якому:якій} я можу довірити виконати роботу та при цьому знатиму, що ти триматимеш рот на замку.\n\nЯ розробляв тут новий план. Він трохи ризикований, але якщо все спрацює, ми з тобою конкретно заробимо грошенят! І я думаю, що ти ідеально для цього підходиш.\n\nДля початку, ти маєш повернутися до Грабіжної Бухти. Вибач, {ім'я}. Я знаю, що ти вже {стать:був:була} там за моїм дорученням. Але цього разу тобі треба буде поговорити з Вибриком Бульчуком.\n\nПередай йому цього листа. І якщо йому потрібна буде допомога — зроби все можливе. Повір, воно того варте.", [3] = "Віднесіть план Крейвела Вибрику Бульчуку в Грабіжну Бухту.", [4] = "Привіт-привіт. І що ж привело {стать:такого шляхетного:таку шляхетну} {раса:з} до Грабіжної Бухти?", [5] = "Зрозуміло. Крейвел придумав дуже хитру схему. У нього гострий розум, це мені в ньому подобається.\n\nОтже, тобі потрібно щось, щоб задурити голову, так? Щось сильне...\n\nМені цікаво, чи підійде суміш, якою Занзіл годує своїх зомбі...", ["en"] = "Back to Booty Bay", ["tasks"] = { ["Kravel's Scheme"] = "план Крейвела", ["Kravel's Scheme (Provided)"] = "план Крейвела (видано)" } },
    [1119] = { [1] = "Суміш Занзіла та Йолопиво", [2] = "Я зрозумів як використати суміш Занзіла разом з пивом, щоб зробити могутній напій! \"Йолопиво\". Я гадаю, що це буде те, що потрібно Крейвелу. Віднеси йому напій, нехай спробує. Розповіси потім, як усе пройшло.\n\nІ {ім'я}, не тримай його занадто довго на повітрі. Суміш Занзіла дивно впливає на дріжджі, тож свіжим він буде недовго.", [3] = "Принесіть \"Йолопиво\" Крейвелу на Мерехтливі рівнини.", [4] = "Привіт, {ім'я}. Бульчук погодився нам допомогти?", [5] = "Чудово! Бульчук пішов нам на зустріч! Я обов'язково віддячу йому за першої нагоди.\n\nІ дякую тобі, {ім'я}. Ти чудово {стать:впорався:впоралася}, і ми обоє заробимо на цьому багато грошей...", ["en"] = "Zanzil's Mixture and a Fool's Stout", ["tasks"] = { ["Fool's Stout"] = "Йолопиво", ["Fool's Stout (Provided)"] = "Йолопиво (видано)" } },
    [1120] = { [1] = "Напоїти гномів", [2] = "Нам потрібно спробувати напоїти одного члена команди на піт-стопі. Якщо хочеш випробувати його на гномах, ось, візьми пиво та подай його гному-начальнику піт-стопу.\n\nНе затримуйся. Зрештою, цей шмурдяк швидко вивітрюється.", [3] = "Принесіть \"Йолопиво\" гному-начальнику піт-стопу.", [4] = "Гей! Маєш щось для мене?", [5] = "Міцне пивко? Яка увага! Дякую!\n\nВзагалі, ми не маємо пиячити прямо перед перегонами, але... можливо, моїм хлопцям не завадило б трохи. До того ж не може це пиво бути настільки міцним, правда ж?", ["en"] = "Get the Gnomes Drunk", ["tasks"] = { ["Fool's Stout"] = "Йолопиво", ["Fool's Stout (Provided)"] = "Йолопиво (видано)" } },
    [1121] = { [1] = "Напоїти гоблінів", [2] = "Нам потрібно спробувати напоїти одного члена команди на піт-стопі. Якщо хочеш випробувати його на гоблінах, ось, візьми міцного пива та подай його гобліну-начальнику піт-стопу.\n\nНе затримуйся. Зрештою, цей шмурдяк швидко вивітрюється.", [3] = "Принесіть \"Йолопиво\" гобліну-начальнику піт-стопу.", [4] = "На що {стать:витріщився:витріщилася}?", [5] = "Що у нас тут? Випивка, га?\n\nЩо ж, я не проти, якщо ми трошки вип'ємо...", ["en"] = "Get the Goblins Drunk", ["tasks"] = { ["Fool's Stout"] = "Йолопиво", ["Fool's Stout (Provided)"] = "Йолопиво (видано)" } },
    [1122] = { [1] = "Повернення до Бульчука", [2] = "Це \"Йолопиво\" чудово спрацювало! Я зробив ставку на наступні перегони, і... сподіваюся, що команда, яку ти {стать:напоїв:напоїла}, доїде до старту!\n\nУ мене є ще одне завдання для тебе — віднеси цю записку Вибрику Бульчуку в Грабіжну Бухту. Він точно захоче дізнатися про успіх.\n\nСподіваюся, ми зможемо дістати більше цього \"Йолопива\" для майбутніх перегонів!", [3] = "Віддайте звіт про \"Йолопиво\" Вибрику Бульчуку в Грабіжну Бухту.", [4] = "Привіт, {ім'я}. Як спрацювало \"Йолопиво\"? Міцне пійло, чи не так?", [5] = "В записці написано, що \"Йолопиво\" спрацювало. Це чудові новини!\n\nЯкщо захочеш ще — дай мені знати, і я попрошу тебе зібрати ще суміші Занзіла.", ["en"] = "Report Back to Fizzlebub", ["tasks"] = { ["Fool's Stout Report"] = "звіт про \"Йолопиво\"", ["Fool's Stout Report (Provided)"] = "звіт про \"Йолопиво\" (видано)" } },
    [1124] = { [1] = "Пустка", [2] = "Західніше від кратера Ун'Ґоро, за північно-західним гребенем, розташовна сувора пустка — Силітус. Мало хто знає, що у стародавні часи там розгорнулася війна між нічними ельфами та лихою, чужорідною силою. Зло замкнули, але тепер ми підозрюємо, що певні сили намагаються розворушити цей… немислимий жах.\n\nЗнайди Лайо Зоревдара, одного з наших розвідників у Силітусі. Шукай його біля Спочину Доблесті — останнього притулку загиблих у цих пустинних землях. Віддай йому цей лист, і він довіриться тобі.", [3] = "Поговоріть з Лайо Зоревдаром біля цвинтаря Спочин Доблесті в Силітусі та покажіть йому лист Рабіна.", [4] = "Це небезпечний край для такої недбалості, {клас:к}. Що привело тебе до пусток Силітусу?", [5] = "Тебе прислав Рабін, чи не так? Що ж, вважай себе {стать:бажаним гостем:бажаною гостею}... наскільки цей відлюдний і покинутий край може бути гостинним.\n\nЯ не застав часи великих нещасть, що тут відбулися, але у цій пустелі все ще є місця, які можуть послужити моторошними образами забутого минулого. Можливо, з твоєю допомогою Кенарійське Коло зможе покласти край тій загрозі, яка повинна була зникнути ще кілька поколінь тому.", ["en"] = "Wasteland", ["tasks"] = { ["Rabine's Letter"] = "лист Рабіна", ["Rabine's Letter (Provided)"] = "лист Рабіна (видано)" } },
    [1125] = { [1] = "Духи Південного Вітру", [2] = "На південний захід звідси є трагічне місце — руїни селища Південний Вітер. Там ми й почнемо, {ім'я}.\n\nНам відомо, що це селище колись було базою нічних ельфів для операцій в Силітусі. Воно вже давно захоплене силітидами, які наводнили ці пустки. Я можу лише уявити жахіття, що відбувались у селищі в ті часи...\n\nЗакатовані духи загиблих друїдів і вартових безцільно блукають цими руїнами. Досліди це місце та звільни душі цих нещасних істот.", [3] = "Звільніть душі 8 закатованих друїдів і 8 закатованих вартових у селищі Південний Вітер та поверніться до Лайо Зоревдара на кладовище Спочин Доблесті в Силітусі.", [4] = "З Альянсу чи з Орди, не має значення — жодна істота не заслуговує на те, щоб її неупокоєна душа була ув'язнена в цьому світі. Звільнення цих душ — це хороший вчинок, {ім'я}.", [5] = "Я задумувався, що величезний вулик, розташований біля руїн селища, зіграв велику роль у його загибелі. Здається, ти {стать:підтвердив:підтвердила} це проробленою роботою. Цей вулик буде заважати будь-якій нашій діяльності.\n\nДякую тобі за милосердя у звільненні душ загиблих, я знаю, як важко таке робити. Однак, коли ти будеш {стать:готовий:готова}, я хотів би ще раз попросити тебе про допомогу...", ["en"] = "The Spirits of Southwind", ["tasks"] = { ["Tortured Druid"] = "закатований друїд", ["Tortured Druid slain"] = "закатований друїд: убито", ["Tortured Sentinel"] = "закатована вартова", ["Tortured Sentinel slain"] = "закатована вартова: убито" } },
    [1126] = { [1] = "Вулик у вежі", [2] = "Прийшов час зайнятися вуликом в селищі Південний Вітер і, я думаю, що знаю, як до нього дістатися. Завдяки своєму досвіду, я знаю, що вулики силітидів дуже чутливі до навколишнього середовища, це пояснює їхні напади після передсмертних криків духів.\n\nНайсильніші силітиди у тій вежі, навколо якої кружляють оси. Піднімись на вежу і розворуши їхній вулик. Повідом про все, що дізнаєшся, але будь {стать:обережним:обережною}! Якщо знайдеш щось, що може нам допомогти, принеси це мені.", [3] = "Підніміться на вежу селища Південний Вітер та знайдіть спосіб розворушити вулик силітидів. Принесіть усе незвичайне, що знайдете там Лайо Старстрайку на цвинтар Спочин Доблесті в Силітус.", [4] = "Ну що, спрацювало? Ти все ще {стать:цілий:ціла}, це вже добре. {стать:Знайшов:Знайшла} що-небудь?", [5] = "Що за... що це?\n\nЦе... коробка? Вона вкрита чимось міцним. Зачекай, тут можна заглянути всередину... це книга під усією цією гидотою?\n\nДумаю, ти {стать:натрапив:натрапила} на дещо цікаве, {ім'я}... принаймні, я на це сподіваюся. Можливо, під цією шкаралупою зберігся щоденник чи журнал з минулого.\n\nЗдається, я знаю спосіб дізнатися, що це.", ["en"] = "Hive in the Tower", ["tasks"] = { ["Encrusted Silithid Object"] = "вкрита хітином річ", ["Encrusted Silithid Object (Provided)"] = "вкрита хітином річ (видано)" } },
    [1127] = { [1] = "Йолопиво", [2] = "То ти хочеш випити \"Йолопива\", так? Хочеш знову повернутися на перегони?\n\nГаразд, принеси мені трохи суміші Занзіла і я зроблю тобі ще.", [3] = "Принесіть 12 порцій суміші Занзіла Вибрику Бульчуку у Грабіжну Бухту.", [4] = "Ти вже {стать:зібрав:зібрала} суміш Занзіла, {ім'я}?", [5] = "О, чудово! Ось твоя оплата.\n\nІ ще дещо зверху... за мовчання.", ["en"] = "Fool's Stout", ["tasks"] = { ["Zanzil's Mixture"] = "суміш Занзіла", ["Zanzil's Mixture (Provided)"] = "суміш Занзіла (видано)" } },
    [113] = { [1] = "Дослідження частин комах", [2] = "Старший землемір Шипохідник має негайно побачити цей звіт. Насправді... кожен, хто вміє читати, має побачити його. Ми зіткнулися з великою та серйозною загрозою не тільки для Танарісу та Пристробляху, а й для всього південного Калімдора. Дідько, можливо, це загрожує всьому Азероту. І немає жодних ознак того, що ці тварюки зупиняться.\n\nНехай Шипохідник зробить копію звіту для того, щоб ти {стать:зміг:змогла} поширити його серед усіх своїх союзників. Нехай усі дізнаються про цю загрозу!", [3] = "Передайте звіт старшому землеміру Шипохіднику в Пристроблясі. Отримайте копію звіту, як просив алхімік Товкачер.", [4] = "Ну що, {стать:молодший землеміре:молодша землемірко} {ім'я}, старий Товкачер вже підготував звіт?", [5] = "Дякую тобі за доставлення звіту, {стать:молодший землеміре:молодша землемірко} {ім'я}. Ось твоя оплата за віддану службу Пристробляхводоканалу.\n\nХоча я не надто люблю задарма ділитися інформацією з тими, хто міг би заплатити за неї дзвінкою монетою, я знайомий з Товкачером вже багато років. Якщо він просить розповісти про це всім, то так і має бути. Зачекай хвилинку, і я зроблю копію для тебе.", ["en"] = "Insect Part Analysis", ["tasks"] = { ["Insect Analysis Report"] = "звіт про дослідження комах", ["Insect Analysis Report (Provided)"] = "звіт про дослідження комах (видано)" } },
    [1132] = { [1] = "Фіора Довговуха", [2] = "Ех, от би знову відправитись в плавання! Відчути ніжний дотик вітру, щоб хвилі колихали мене, як колись колихала моя матінка.\n\nЯк же тобі пощастило, {клас:к}, що ти можеш відправитись в море.\n\nМоя робота - розповідати нетерплячим мандрівникам про Калімдор, край можливостей! Як хочеш випробувати вдачу за морем - сідай на корабель, що доставить тебе до порту Терамору. Поговори там з моєю партнеркою, Фіорою Довговухою.\n\nВона відправить тебе в незабутні пригоди Калімдором!", [3] = "Поговоріть з Фіорою Довговухою в Тераморі.", [5] = "Вітаю! Тебе підправив пан Кремінь з гавані Менетілів? Що ж, пан Флінт розуміється на шукачах пригод. Якщо він відправив тебе сюди — без сумніву, ти тут знадобишся!", ["en"] = "Fiora Longears" },
    [1135] = { [1] = "Отрута Високого Сідала", [2] = "Як ти, певно, вже знаєш, орки часто приручають виверн як їздових тварин. Проте менш відомо, що в деяких колах отрута виверн є ціннішою, ніж самі звірі. Тож якщо ти не проти трішки пополювати на них, то у мене є для тебе робота.\n\nВ Тисячі Шипів, що на захід звідси, є місце під назвою Високе Сідало. Тамтешні виверни мають потужну отруту. Потужну та цінну.", [3] = "Принесіть 10 отруйних залоз Високого Сідала Фіорі Довговухій в Терамор.", [4] = "Ти {стать:знайшов:знайшла} Високе Сідало, {ім'я}? Є якийсь успіх з тамтешніми вивернами?", [5] = "Ах, більшість з них мало не лопаються від отрути, {ім'я}. Зазвичай такі залози збирають з молодих виверн або вагітних самок. Напевно, нелегко тобі було у Високому Сідалі!", ["en"] = "Highperch Venom", ["tasks"] = { ["Highperch Venom Sac"] = "отруйна залоза Високого Сідала", ["Highperch Venom Sac (Provided)"] = "отруйна залоза Високого Сідала (видано)" } },
    [1137] = { [1] = "Новини для Фіззла", [2] = "Індурій має чудову стійкість до нагрівання! Я впевнений, що він гарно послужить Фіззловим поршням. Але йому треба повноцінна індурієва руда, а не ці уламки.\n\nЩоб добути руду, потрібно копати глибоко в Ульдамані, що на північному кордоні Безплідних країв. Саме там знаходиться справжнє джерело індурію.\n\nПередавай вітаннячка Фіззлу Латуноболту та розкажи йому те, що я розповів тобі.\n\nБезпечних мандрів, {ім'я}. Не здивуюся, якщо ми знову зустрінемося. Коли Фіззл дізнається про індурій, він точно відправить тебе в Ульдаман, щоб добути його.", [3] = "Поговоріть з Фіззлом Латуноболтом на Мерехтливій рівнині.", [5] = "{ім'я}, ти {стать:повернувся:повернулася}! Ти {стать:знайшов:знайшла} Мартека? Ти {стать:говорив:говорила} з ним? Що він сказав? Він зможе допомогти??", ["en"] = "News for Fizzle" },
    [1139] = { [1] = "Втрачені скрижалі волі", [2] = "Ми змогли стримати клан Тінегарту, відрізавши їхні сили від Чорноскельного шпиля, але завдання Молотопалого ще не завершено. Його смерть не повинна бути марною. Він мріяв знайти скрижаль волі — кам'яний уламок, на якому самі титани викарбували магічні письмена, щоб вдихнути життя у свої творіння і дати їм власну волю, — принаймні, так свідчать легенди.\n\nМи маємо повернути скрижаль до того, як її знайде клан Тінегарта.\n\nПовертайся до Ульдамана, знайди скрижаль і негайно принеси її мені.", [3] = "Знайдіть скрижаль волі та принесіть її раднику Белґраму в Залізогарт.", [4] = "Ми маємо виконати завдання Молотопалого, {ім'я}. Я багато чим зобов'язаний йому.\n\nТвоє повернення до Ульдаману необхідне не тільки для цього, але й для безпеки всього роду дворфів. Якщо скрижаль потрапить до рук Темного Заліза, хто знає, наскільки потужною стане їхня армія големів.", [5] = "<Радник Белґрам недовірливо хитає головою, коли ви передаєте йому кам'яний уламок.>\n\n{ім'я}, це дивовижно. Я простежу, щоб скрижаль доставили королівським магам якомога швидше. Вони захочуть вивчити її, щоб перевірити правдивість легенд. Але про це поговоримо іншим разом: ти {стать:допоміг:допомогла} нашому народу більше, ніж я міг сподіватися — дякую тобі.", ["en"] = "The Lost Tablets of Will", ["tasks"] = { ["Tablet of Will"] = "скрижаль волі", ["Tablet of Will (Provided)"] = "скрижаль волі (видано)" } },
    [1140] = { [1] = "Вежа Алталакс", [2] = "Писемність орків не набагато краща за дитячі каракулі. Багато хто з мого ордену насміхався, коли я вирішив вивчити їхню мову, але це допомагає мені краще розуміти моїх ворогів.\n\nЗ каракулів Ілкруда можна зрозуміти, що в Атріка залишилось ще два камені душі, і вони знаходяться у Ночеплині та Сатирнаарі, зайнятих сатирами місцях на північному сході Ясенедолу.\n\nОбережніше там, {ім'я:к}, від вигляду залитих кров'ю храмів сатирів може стати зле навіть {стать:такому досвідченому:такій досвідченій} {клас:д}, як ти.", [3] = "Визвольте душі високородних в Ночеплині та Сатирнаарі, після чого поверніться до Дельґрена Очистителя на заставу Маєстри.", [4] = "Я чув, що історія сатирів якимось чином пов'язана з історією нічних ельфів, але мої гостинні господарі не дуже охоче говорили про це.", [5] = "Можливо, ми занадто довго дозволяли сатирам залишатися в лісі. Я поговорю про це з Еліссою, коли наступного разу буду в Аубердіні.\n\nПроте, зі знищенням каменів душі, сила Атріка значно зменшиться. Ми маємо скористатися цією можливістю, щоб знищити Атріка і його культ.", ["en"] = "The Tower of Althalaxx", ["tasks"] = { ["Free the Highborne soul in Night Run"] = "Звільніть душу Високонароджених у Нічному забігу", ["Free the Highborne soul in Night Run (Provided)"] = "Звільніть душу Високонароджених у Нічному забігу (видано)", ["Free the Highborne soul in Night Run slain"] = "Звільніть душу Високонароджених у Нічному забігу: убито", ["Free the Highborne soul in Satyrnaar"] = "Звільніть душу Високонароджених у Сатирнаарі", ["Free the Highborne soul in Satyrnaar (Provided)"] = "Звільніть душу Високонароджених у Сатирнаарі (видано)", ["Free the Highborne soul in Satyrnaar slain"] = "Звільніть душу Високонароджених у Сатирнаарі: убито" } },
    [1143] = { [1] = "Вежа Алталакса", [2] = "Ясно. Що ж, якщо те, що ти кажеш — правда, то зараз саме час для атаки. Я думаю, що Атрікус мешкає на вершині вежі. Але будь {стать:обережний:обережна} - його оточують могутні чорнокнижники, набагато небезпечніші за тих, що траплялись тобі раніше.", [3] = "Вбийте Атріка Нарассіна і принесіть його голову Балтулу Тіневдару біля вежі Алталакса.", [4] = "Атрік Нарассін — древній і могутній чорнокнижник. Можливо, нам варто дочекатися допомоги Делґрена, але він, вочевидь, дуже сильно вірить в тебе, якщо послав тільки тебе.", [5] = "Сподіваюся, що зі смертю Атріка демонічні сили відступлять. Я не сумніваюся, що вони перегрупуються і повернуться, але тоді ми будемо краще підготовлені до битви з ними.", ["en"] = "The Tower of Althalaxx", ["tasks"] = { ["Athrikus Narassin's Head"] = "голова Атріка Нарассіна", ["Athrikus Narassin's Head (Provided)"] = "голова Атріка Нарассіна (видано)" } },
    [1144] = { [1] = "Імпортер Віллікс", [2] = "Нарешті, спасіння!\n\nНавіть не уявляєш, скільки я тут сиджу!\n\nРозумієш, я підприємець і завжди шукаю можливості підзаробити. От я й почув, що Мебок Міцрікс гарно платить за тутешні бульби червонолиста. Я й подумав що це пригода на п'ять хвилин — зайшов-вийшов. Та, як бачиш, я помилявся.\n\nХай там як, та якщо допоможеш мені вийти звідси — я тебе гарно винагороджу.", [3] = "Виведіть Імпортера Віллікса з краалю Бритвоболотих.", [5] = "Дякую, {стать:друже:подруго}. Як і обіцяв, ось твоя винагорода.", ["en"] = "Willix the Importer", ["tasks"] = { ["Help Willix the Importer escape from Razorfen Kraul"] = "Допоможіть Вілліксу-імпортеру втекти з Краула Розорфена" } },
    [1148] = { [1] = "Частини рою", [2] = "Ви уважно оглядаєте панцир. Покрутивши його в руках, ви розумієте, що хітинове покриття щільно переплетене, що робить панцир неймовірно міцним. Ви досі не бачили нічого подібного. Ви оглядаєте рештки далі, і розумієте, наскільки ці створіння сильні та розвинені.\n\nДивлячись знову на панцир, ви думаєте, що Коррану було б цікаво вивчити цих істот детальніше. Це допомогло б йому дізнатися, що це за створіння, та звідки вони беруться.", [3] = "Принесіть 1 серце, 5 кігтів та 3 цілі панцири силітидів Коррану на Перехрестя.", [4] = "Ох, пройшло чимало часу з тої пори, як ти {стать:приходив:приходила} до мене, {ім'я}. Чим я можу тобі допомогти? Ти виглядаєш так, ніби ти нещодавно {стать:брав:брала} участь у битві. Добре... це добре для Орди та для тебе. Чим більше битв ти побачиш, тим корисніше і сильніше ти будеш.", [5] = "О, то ти нещодавно {стать:бачився:бачилася} з Моктаром? Він завжди дбав про мене. Прикро чути про те, що він витрачає свій час на те, щоб наглядати за своєю групою, замість того, щоб самому брати участь в бою. Та я впевнений, що він отримує задоволення від вбивства членів Ліги дослідників.\n\nТи {стать:вчинив:вчинила} правильно, принісши мені ці зразки, {ім'я}. Разом з цими яйцями, які ми знайшли на Полі велетнів, це дасть мені чудовий початок в дослідженні того, що це за комахи, і чого вони взагалі хочуть.", ["en"] = "Parts of the Swarm", ["tasks"] = { ["Intact Silithid Carapace"] = "неушкоджений панцир силітида", ["Intact Silithid Carapace (Provided)"] = "неушкоджений панцир силітида (видано)", ["Silithid Heart"] = "серце силітида", ["Silithid Heart (Provided)"] = "серце силітида (видано)", ["Silithid Talon"] = "кіготь силітида", ["Silithid Talon (Provided)"] = "кіготь силітида (видано)" } },
    [1155] = { [1] = "<NYI> <TXT> побічний квест з кристалом жука", [2] = "х", ["en"] = "<NYI> <TXT> bug crystal side quest" },
    [1157] = { [1] = "<NYI> <TXT> Пестлезуґґ потребує предметів", ["en"] = "<NYI> <TXT> pestlezugg needs items" },
    [1158] = { [1] = "<NYI> <TXT> поговоріть з Рабіне Сатурною", [2] = "х", ["en"] = "<NYI> <TXT> speak to rabine saturna" },
    [1160] = { [1] = "Випробування знань", [2] = "Я скажу, що тобі доведеться шукати та навіть поставлю своє запитання, та не тому, що ти хочеш проявити себе. Знання не менш важливі за силу. Навіть якщо хтось перевершує тебе в силі, твої знання можуть бути кориснішими.\n\nЙди в монастир, що на півночі Тірісфальського перелісся. В бібліотеці ти знайдеш книгу, що називається \"Джерела загрози невмерлих\". З неї нині збожеволілі паладини черпають знання для знищення моїх побратимів.\n\nПринеси її мені.", [3] = "Знайдіть книгу \"Джерела загрози невмерлих\" і поверніть її Парквелу Фінталласу в Підмістя.", [4] = "Сподіваюсь, ти {стать:приніс:принесла} вдосталь страждань Багряному Походу, поки {стать:шукав:шукала} книгу.\n\nМоє ставлення до них не безпідставне. Хай вони колись і служили Світлу, та тепер їх мета — знищення всіх, хто не поділяє їх погляди. Вони вважають, що всі невмерлі — відречені чи ні — мають бути знищені. А всіх, хто ходить нашими землями називають або безумцями, або жертвами заклять невмерлих. Ідіоти. Ідіоти та дурні. Всі вони.", [5] = "Це та сама книга, за якою я тебе відправив.\n\n<Парквел повільно проводить рукою по обкладинці книги, оглядаючи її.>\n\nТо тепер ти чекаєш на питання, щоб довести, що розум твій не поступається силі та духу. Якщо ти уважно {стать:прочитав:прочитала} книгу — дай відповідь на моє наступне питання і ми завершимо ці випробування!", ["en"] = "Test of Lore", ["tasks"] = { ["Beginnings of the Undead Threat"] = "Джерела загрози невмерлих", ["Beginnings of the Undead Threat (Provided)"] = "Джерела загрози невмерлих (видано)" } },
    [1161] = { [1] = "<NYI> <TXT> плітки тіні бурштинового місяця", [2] = "х", ["en"] = "<NYI> <TXT> gossip shade of ambermoon" },
    [1162] = { [1] = "<NYI> <TXT> поговорити з хамуулом рунетом", [2] = "х", ["en"] = "<NYI> <TXT> speak to hamuul runetotem" },
    [1163] = { [1] = "<NYI> <TXT> поговорити з Тірандою ШепітВінд", [2] = "х", ["en"] = "<NYI> <TXT> speak to tyrande whisperwind" },
    [1167] = { [1] = "Вежа Алталакса", [2] = "Перш ніж протистояти Атріку, мабуть, варто порадитися з Балтулом. Не сумніваюся, що він пильно стежить за вежею і може знати щось про нещодавні події.", [3] = "Поговоріть з Балтулом Тіневдаром біля вежі Алталакса.", [5] = "Приємно знову тебе бачити, {ім'я}! Тут відбувалися дивні речі, тож я дуже радий, що ти {стать:повернувся:повернулась}!\n\nЦе було дуже дивно, {ім'я}. Все здавалося нормальним — ну, настільки, наскільки все це може бути нормальним, — і раптом у верхній кімнаті вежі трапився яскравий спалах світла. Потім почалися крики. Крики пронизували повітря, а в землю час від часу вдаряли блискавки. Що все це може означати?", ["en"] = "The Tower of Althalaxx" },
    [1174] = { [1] = "Гноми перемогли!", ["en"] = "Gnomes Win!", ["tasks"] = { ["Gnome Race Ticket"] = "квиток на перегони гномів" } },
    [1175] = { [1] = "Перепони на дорозі", [2] = "Після страшної аварії за участі гоблінського перегонового боліда \"Червоний Грім\" та василіска, Вайлоїзд найняв мене слідкувати за треком. Не знаю, чим харчуються ці тварини на рівнинах, щоб виростати настільки здоровезними, але ми маємо обережно прорідити їх виводок, щоб вони не бродили по треку під час перегонів.\n\nЗнаєш що? Якщо хочеш трішки підробити, сходи розберись з декількома василісками.", [3] = "Вбийте 10 соляних василісків, 10 соляних кришталешкурів та 6 соляних камнеглядів для начальника перегонового треку Жеріна на Мерехтливих рівнинах.", [4] = "Це жахливо, прибирати залишки боліда з місця аварії без змоги відділити їх від обгорілих решток тварин.", [5] = "Сподіваюсь, ти не {стать:вбивав:вбивала} василісків саме на треках! Туші дуже довго розкладаються на сонці, і я б не хотів прибирати їх лопатою.", ["en"] = "A Bump in the Road", ["tasks"] = { ["Saltstone Basilisk"] = "соляний василіск", ["Saltstone Basilisk slain"] = "соляний василіск: убито", ["Saltstone Crystalhide"] = "соляний кришталешкур", ["Saltstone Crystalhide slain"] = "соляний кришталешкур: убито", ["Saltstone Gazer"] = "соляний камнегляд", ["Saltstone Gazer slain"] = "соляний камнегляд: убито" } },
    [1176] = { [1] = "Зменшення ваги", [2] = "Коли справа стосується перегонів, будь-що може мати значення! Чи то незначні зміни потужності, невелике послаблення натяжних котушок, чи полегшення ваги рами, ти маєш врахувати все!\n\nМи використовуємо у своїх болідах кістки стерв'ятників, що забезпечує ідеальний баланс міцності та ваги. До того ж їх дуже легко знайти, адже соляні рівнини кишать стерв'ятниками.\n\nПринеси мені кілька кісток, і я гарно тобі заплачу.", [3] = "Принесіть 10 порожнистих кісток стерв'ятника Поззіку на Мерехтливі рівнини.", [4] = "Ти {стать:дістав:дістала} кістки? Я якраз збирався почати працювати над полегшенням керма, та не хочу розпочинати без усіх необхідних деталей.", [5] = "Чудово! Піду покличу команду, щоб вони почали працювати. Дякую, {ім'я}!", ["en"] = "Load Lightening", ["tasks"] = { ["Hollow Vulture Bone"] = "порожниста кістка стерв'ятника", ["Hollow Vulture Bone (Provided)"] = "порожниста кістка стерв'ятника (видано)" } },
    [1177] = { [1] = "Голодний!", [2] = "Моя — великий огр.\n\nМоя голодний.\n\nТи йти бити рибка. Ти нести їжа для Мул.\n\nТи годувати Мул, або Мул їсти тебе.", [3] = "Принесіть 12 голів моквоплавникових мурлоків Мулоляпу Брудноступу в північну Бруднолипку трясовину.", [4] = "Дай їжа, або я їсти тебе.", [5] = "Я любити рибна голова!\n\nЯ поки тебе не їсти.", ["en"] = "Hungry!", ["tasks"] = { ["Mirefin Head"] = "голова моквоплавникового мурлока", ["Mirefin Head (Provided)"] = "голова моквоплавникового мурлока (видано)" } },
    [1178] = { [1] = "Гоблінська підтримка", [2] = "Наша команда з перегонів — гордість гоблінів по всьому світу. Ти здивуєшся, дізнавшись, що за особистості тією чи іншою мірою допомагають нашій команді.\n\nТи знаєш Ґазлоу? Він збирає для нас деталі по всьому світу. Він навіть якось прийшов до нас, щоб попрацювати над нашими машинами.\n\nКілька тижнів тому він пообіцяв надіслати новий прототип паливного регулятора, але він досі не прийшов. Зазвичай, він дуже швидко надсилає деталі... Можливо, ти не проти відправитись до Брашпиля, та запитати у нього про неї? Я б не був таким настирливим, але ці гноми наздоганяють нас!", [3] = "Поговоріть з Ґазлоу в Брашпилі.", [5] = "Поззік прислав тебе, га? Знаєш, раніше Поззік був одним з кращих штукарів в усій Підштольні, доки він не почав працювати над перегонами.\n\nПерше, що він зробив, приєднавшись до команди — розробив дві нові моделі двигунів. Спілка штукарів може сильно постраждати без його роботи, але яке йому діло, правда ж? Для нього немає нічого важливішого за перегони.", ["en"] = "Goblin Sponsorship" },
    [1179] = { [1] = "Брати Латуноболти", [2] = "Ти коли-небудь {стать:чув:чула} про Мерехтливі рівнини? Це величезне соляне плато в Калімдорі, на півдні каньйону Тисячі Шипів. Це чудово місце для перегонів тому, що... ну... це рівнини!\n\nТам живе кілька братів-гномів — мої друзі, вони будують новий болід, і кажуть, що він дуже швидкий! Хех, настільки швидкий, що пілоти постійно розбиваються й калічаться.\n\nТож, вони попросили в мене кілька облогових шоломів, але у мене є важливі справи, і я не можу їх відвезти!\n\nА ти зможеш?", [3] = "Принесіть ящик захисних шоломів Віззлу Латуноболту на Мерехтливі рівнини.", [4] = "Дивись куди преш! Гей, обережно!! Ці штуки дуже делікатні, а якщо ми хочемо виграти, все має працювати ідеально!", [5] = "Ох! Довгобород відправив тебе разом з купою шоломів! Ура!\n\nМожливо тепер ми зможемо вмовити пілота сісти в нашу машину...", ["en"] = "The Brassbolts Brothers", ["tasks"] = { ["Crate of Crash Helmets"] = "ящик захисних шоломів", ["Crate of Crash Helmets (Provided)"] = "ящик захисних шоломів (видано)" } },
    [1180] = { [1] = "Гоблінська підтримка", [2] = "Повернемося до того, за чим ти {стать:прийшов:прийшла}. Я знаю, що обіцяв Поззіку новенький паливний регулятор, але я все ще його не отримав. Ревілґаз з Грабіжної Бухти сказав, що вислав його, але схоже, що він кудись зник.\n\nЯкщо це правда, то ми не зможемо нічого з цим поробити. Принаймні, ми можемо дізнатися, чи його відправили з Грабіжної Бухти.\n\nПоговори із завідувачем причалу Лозґілом, він може подивитися у свої записи.", [3] = "Поговоріть із завідувачем причалу Лозґілом в Грабіжній Бухті.", [5] = "Доставка до Брашпиля? Дай-но мені перевірити записи...\n\nНі, єдиною доставкою до Брашпиля є чоботи від Мжичника. Більше нічого такого немає, тільки обладнання для будівництва та інструменти. Жодних запчастин для перегонів.", ["en"] = "Goblin Sponsorship" },
    [1181] = { [1] = "Гоблінська підтримка", [2] = "Боюся, я більше нічим не зможу тобі допомогти, {ім'я}. Якщо ти хочеш дізнатися подробиці, раджу тобі поговорити з самим бароном. Ніхто не знає справи Ревілґаза краще за самого Ревілґаза.\n\nТи знайдеш його на верхньому поверсі таверни, що на іншому боці гавані.", [3] = "Поговоріть з бароном Ревілґазом в Грабіжній Бухті.", [5] = "О, так, я розумію, про що ти. Ні, я не зможу тобі допомогти. Мої хлопці мали добути креслення паливного регулятора, але вони повернулися з порожніми руками.", ["en"] = "Goblin Sponsorship" },
    [1182] = { [1] = "Гоблінська підтримка", [2] = "Розумієш, подрібнювачі ТзНБ \"Авантюра\", поруч з озером Назферіті, що на півночі Тернистої долини, оснащені новими моделями паливного регулятора. Я подумав, що це могло б бути корисним для Поззіка. Та на жаль, Коззл, тамтешній бригадир, виявився дещо кмітливішим, ніж я думав.\n\nМожливо, тобі більше пощастить, і ти отримаєш креслення. Мені відомо, що він тримає їх у своєму будинку, але вони певно під замком.", [3] = "Принесіть креслення паливного регулятора барону Ревілґазу в Грабіжну Бухту.", [4] = "Як би сильно я не хотів це визнавати, але ця команда гномів досить хороша. Нашим хлопцям потрібно краще старатися.", [5] = "А тепер, дай-но я зроблю копію цих креслень для особистого користування, а ці ти можеш віднести Поззіку. Не хотілося б, щоб він подумав, що один з його спонсорів кинув його.", ["en"] = "Goblin Sponsorship", ["tasks"] = { ["Fuel Regulator Blueprints"] = "креслення паливного регулятора", ["Fuel Regulator Blueprints (Provided)"] = "креслення паливного регулятора (видано)" } },
    [1183] = { [1] = "Гоблінська підтримка", [2] = "Ось, тепер ти {стать:готовий:готова}, можеш йти. Передавай Поззіку мої найщиріші вітання і скажи йому, що якщо йому щось знадобиться, то хай не соромиться попросити у мене. Я буду чекати новин про те, як він поб'є свій рекорд на треку.", [3] = "Принесіть креслення паливного регулятора Поззіку на Мерехтливі рівнини.", [4] = "{Ім'я}! Тобі вдалося знайти паливний регулятор?", [5] = "Я сподівався, що він прибуде в готовому вигляді, але це дає нам унікальну можливість покращити конструкцію. Дякую, {ім'я}. Скоро я зможу створити покращені креслення регулятора, зібрати його і встановити.", ["en"] = "Goblin Sponsorship", ["tasks"] = { ["Fuel Regulator Blueprints"] = "креслення паливного регулятора", ["Fuel Regulator Blueprints (Provided)"] = "креслення паливного регулятора (видано)" } },
    [1185] = { [1] = "А під хітином було...", [5] = "Гей, це знову ти! Тобто, саме ти й ніхто інший — {Ім'я}! Так, точно ти!\n\nТак, дозволь мені почати заново!\n\nТой предмет, що ти {стать:знайшов:знайшла} у Силітусі — це дійсно книга. Це був журнал, написаний дуже древнім діалектом мови, яку зараз ми називаємо дарнасійською. Це займе деякий час, але я збираюся ретельно пройтися по ньому. Я подумав, що ти маєш знати: твоя знахідка — неймовірно цінна для Кола.\n\nМатуся-ведмедиця дуже схвильований і все таке!", ["en"] = "Under the Chitin Was..." },
    [1186] = { [1] = "Вісімнадцятий пілот", [2] = "Я буду зайнятий, працюючи над цим новим паливним регулятором для наших болідів, але якщо ти хочеш допомогти нашій команді, то поговори з Раззеріком. Він наш пілот... хм, наш вісімнадцятий пілот, якщо точніше. І він любить додавати власні модифікації до наших болідів.\n\nВін трохи схиблений, тож не дивуйся, якщо що.", [3] = "Поговоріть з Раззеріком на Мерехтливих рівнинах.", [5] = "Ти {стать:той:та} {раса:н}, що {стать:допомагав:допомагала} Поззіку, чи не так? Колись і я був таким як ти: зайчик на побігеньках, який допомагав механікам на піт-стопах.\n\nТепер подивись-но на мене! Я — найкращий пілот гоблінів!", ["en"] = "The Eighteenth Pilot" },
    [1187] = { [1] = "Налаштування Раззеріка", [2] = "Поззік — чудовий механік, я це знаю, але він боїться додати потужності та вирватися вперед. Але це не про мене.\n\nПісля того, як Поззік закінчить працювати з болідом, я внесу кілька модифікацій, ну, ти знаєш, послаблю обмежувачі, приберу кілька частин з корпуса та додам більше палива!\n\nЯ замовив сифорієвий прискорювач від Шріва з Ґізморія, що в Пристроблясі, але дирижабль, на якому летів прискорювач, розбився в Бруднолипкій трясовині! Я маю врятувати прискорювач, {ім'я}!", [3] = "Знайдіть сифорієвий прискорювач для Раззеріка на Мерехтливих рівнинах.", [4] = "І як я маю з'явитися на треку без прискорювача? Це якась нісенітниця, я тобі кажу.", [5] = "Тільки-но подивися на цю красу! 7 кілограмів чистої сифорієвої сили! Щойно я прикріплю цю штуку до свого боліда, я буду ганяти по треку так швидко, що обжену гномів двічі!", ["en"] = "Razzeric's Tweaking", ["tasks"] = { ["Seaforium Booster"] = "сифорієвий прискорювач", ["Seaforium Booster (Provided)"] = "сифорієвий прискорювач (видано)" } },
    [1188] = { [1] = "Безпека понад усе", [2] = "Чекай, що це? Шрів залишив запобіжники увімкненими. Але ж це обмежить потужність, яку я можу вичавити з прискорювача. Я ж казав йому, щоб відключив! Так не годиться.\n\nТи маєш віднести це в Гізморій, що в Пристроблясі, та змусити Шріва прибрати це.", [3] = "Принесіть сифорієвий прискорювач Шріву в Пристроблях.", [4] = "Наскільки я розумію, ти знаєш, що в Гізморії є все для роботи з будь-якими механізмами. Чим я можу допомогти?", [5] = "Тільки Раззерік зміг з першого погляду зрозуміти, що я поставив сюди запобіжник. Цей прискорювач майже повністю складається з вибухового сифорію. Я модифікував його так, що його потужність буде збільшуватися поступово, але Раззерік не заспокоїться, поки не підірветься до біса зі своїм драндулетом!", ["en"] = "Safety First", ["tasks"] = { ["Seaforium Booster"] = "сифорієвий прискорювач", ["Seaforium Booster (Provided)"] = "сифорієвий прискорювач (видано)" } },
    [1189] = { [1] = "Безпека понад усе", [2] = "Ось, я зробив те, що просив Раззерік. Просто скажи йому, щоб він діяв якомога обережніше, коли він вимкне запобіжник. Якщо він припуститься хоча б найменшої помилки, він не рухатиметься вперед, а перетвориться на купку попелу на треку.\n\nА нам би не хотілося шукати дев'ятнадцятого пілота.", [3] = "Поверніть модифікований сифорієвий прискорювач Раззеріку на Мерехтливі рівнини.", [4] = "Уявляєш, Поззік поклав в болід відро з піском! Як я зможу розвинути максимальну швидкість з відром піску під сидінням?", [5] = "Ось так набагато краще! Хотів би я бачити пики цих гномів, коли я запущу цю крихітку.\n\nЯк прикро, що я буду зайнятий встановленням нового рекорду треку!", ["en"] = "Safety First", ["tasks"] = { ["Modified Seaforium Booster"] = "модифікований сифорієвий прискорювач", ["Modified Seaforium Booster (Provided)"] = "модифікований сифорієвий прискорювач (видано)" } },
    [1190] = { [1] = "Наздогнати та перегнати", [2] = "Брати Латуноболти винайшли новий матеріал для конструювання — це єдине розумне пояснення. Їхні машини їздять швидше ніж раніше, але конструкція та інші параметри, які ми отримали з попередніх заїздів, анітрохи не змінилися.\n\nЄдине що ми знаємо, це те, що брати Різзл Латуноболт ніколи не розлучається зі своїми кресленнями, і в них точно знаходяться деталі їхніх досліджень.\n\nЗамек влаштує диверсію, і ти зможеш викрасти ці схеми.", [3] = "Дочекайтеся, поки Замек влаштує диверсію, потім вкрадіть креслення Різзла для Поззіка на Мерехтливих рівнинах.", [5] = "Неначе курка лапою, сувій розписаний нотатками та концептами, які стосуються перероблення якоїсь сировини.", ["en"] = "Keeping Pace" },
    [1191] = { [1] = "Диверсія Замека", [5] = "Поїхали!", ["en"] = "Zamek's Distraction" },
    [1192] = { [1] = "Індурієва руда", [4] = "Я хотів би використати індурій в деяких частинах наших болідів, але мені потрібна велика кількість індурію, щоб створити ці частини.\n\nТи можеш знайти індурієву руду на розкопках Ульдамана в Безплідних краях, на іншому боці моря, в Каз-Модані.\n\nГноми постійно отримують постачання цієї руди, тому дуже важливо, щоб і ми не відставали.", [5] = "Прекрасно! Піду покличу команду, щоб вони почали працювати над частинами, які нам знадобляться для наступних перегонів.", ["en"] = "Indurium Ore", ["tasks"] = { ["Indurium Ore"] = "індурієва руда", ["Indurium Ore (Provided)"] = "індурієва руда (видано)" } },
    [1193] = { [1] = "Зламана пастка", [4] = "Перед вами лежить велика зламана пастка. Судячи з усього, огри намагалися полагодити її, але безрезультатно. Поруч з пасткою лежить спішно написана записка, в якій, як не дивно, детально описано, що саме потрібно для полагодження пастки: торієвий пристрій і трохи крижаної олії. Якби пастку полагодили, то в неї міг потрапити огр, який проходив би повз і тоді його можна було б оминути.\n\nОчевидно, що дуже мало огрів вміють читати.\n\nОчевидно.", [5] = "Торієвий пристрій легко встає на місце, створюючи канал для заливання крижаної олії. Коли останні краплі олії залито, пастка стає в робоче положення.\n\nНе пощастить ж якомусь необережному огру, що випадково потрапить в неї!", ["en"] = "A Broken Trap", ["tasks"] = { ["Frost Oil"] = "крижана олія", ["Frost Oil (Provided)"] = "крижана олія (видано)", ["Thorium Widget"] = "торієвий пристрій", ["Thorium Widget (Provided)"] = "торієвий пристрій (видано)" } },
    [1194] = { [1] = "Креслення Різзла", [2] = "Креслення Різзла описують процес обробки індурієвої руди. З його каракулів можна зрозуміти, що ця руда добувається на дворфійських розкопках Ульдамана в Безплідних краях.\n\nБільшість інших нотаток вказують на стійкість руди до екстремальних температур.\n\nКресленнях були притиснуті шматком каменю — схоже, що це і є необроблена індурієва руда.", [3] = "Принесіть зразок індурієвої руди Поззіку на Мерехтливі рівнини.", [5] = "Індурій? Цікаво... Якщо руда здатна переносити такі температури, стає зрозуміло, чому гноми так відзначилися на останніх перегонах.\n\nЗразок, який ти мені {стать:приніс:принесла}, мені дуже знадобиться. Я зможу провести з ним кілька тестів, але мені знадобиться більше індурію, щоб отримати з нього хоч якусь користь.", ["en"] = "Rizzle's Schematics", ["tasks"] = { ["Sample of Indurium Ore"] = "зразок індурієвої руди" } },
    [1198] = { [1] = "У пошуках Талріда", [2] = "Останнім часом ширяться чутки про об'єднання Сутінкового Молота з нагами в Чорноводних глибинах на узбережжі Ясенедолу.\n\nМоє завдання тут — збирати інформацію для Сріблястого Світанку, щоб ми розуміли, де потребують нашої допомоги.\n\nПройшло вже кілька тижнів з того часу, як ми відправили розвідника до Чорноводних глибин. Вартовий Сріблястого Світанку Талрід досі не повернувся.\n\nІнші розвідники зайняті важливішими справами.\n\nРозшукай Талріда й допоможи йому, {ім'я:к}.", [3] = "Розшукайте вартового Сріблястого Світанку Талріда в Чорноводних глибинах.", [5] = "Добре, що світанковий вартовий Шедласс послав тебе сюди. Тут дійсно затіваються лихі речі.", ["en"] = "In Search of Thaelrid" },
    [1200] = { [1] = "Лиходійство Чорноводних глибин", [2] = "Сили покидають мене. Мені потрібна твоя допомога!\n\nКолись давно на цьому місці був храм Елуни. На жаль, його було знищено, коли порча Старих Богів просочилась з-під землі та зіпсувала священний місячний колодязь.\n\nАку'май, слуга Старих Богів, піднялася з глибин.\n\nКультисти Сутінкового Молота об'єднались з нагами, щоб захопити ці землі. На чолі з Келрісом вони приносять жертви, щоб Аку'май набрався сил.\n\n{ім'я}, благаю, вбий Келріса і принеси його голову Селґорму в Дарнас.", [3] = "Принесіть світанковому вартовому Селґорму в Дарнас голову сутінкового лорда Келріса.", [4] = "У мене обмаль часу, {клас:к}.\n\nМоє завдання в Дарнасі — забезпечити виконання задач Сріблястого Світанку та зірвати плани злих сил на Калімдорі.\n\nРозказуй чому {стать:прийшов:прийшла}, тільки швидше.", [5] = "Келріс довгий час переховувався від нас.\n\nСхоже, що він стояв за всіма нещодавніми проявами зла в цих краях. Деякий час вважалося, що Келріс мертвий.\n\nПокінчивши з ним, ти {стать:врятував:врятувала} багато невинних життів.\n\nКлянусь світлом! Немає прощення тим, хто приносить жертви Старим Богам!\n\nСріблястий Світанок не забуде твого великого подвигу, {ім'я}.", ["en"] = "Blackfathom Villainy", ["tasks"] = { ["Head of Kelris"] = "голова Келріса", ["Head of Kelris (Provided)"] = "голова Келріса (видано)" } },
    [1203] = { [1] = "Ярлу потрібне лезо", [2] = "Мені треба дещо порізати. Я не можу сказати, що саме я збираюся різати, але... Мені потрібне лезо. Одне хороше лезо...\n\nКажуть, він зветься палашем з місяцесталі. Я ж називаю його: зручне лезо.\n\nДопоможеш мені? Може, знайдеш його десь в місті, чи, може, якийсь коваль зробить його на замовлення.\n\nГоловне, поквапся. Те, що я збираюся різати, довго не чекатиме...", [3] = "Принесіть палаш з місяцесталі Ярлу в Бруднолипку трясовину.", [4] = "Ти {стать:приніс:принесла} мені лезо??", [5] = "Це хороше лезо. Добре збалансоване. Так, це і є зручне лезо. Дякую. Дякую, дякую, дякую!!! Тепер я хочу спробувати його...\n\nАле пізніше. Я спробую пізніше. Отож, як я казав... дякую.", ["en"] = "Jarl Needs a Blade", ["tasks"] = { ["Moonsteel Broadsword"] = "палаш з місяцесталі", ["Moonsteel Broadsword (Provided)"] = "палаш з місяцесталі (видано)" } },
    [1206] = { [1] = "Ярлу потрібні очі", [2] = "Очний сік — це хороший напій. Шкода, що у більшості живих істот лише два ока.\n\nАле павуки мають більше очей. Набагато більше. А сік з очей імлистого павука смачний. М'який та солоний! Цілі очі імлистих павуків... Я вже відчуваю їх смак.\n\nІмлисті павуки водяться в Імлистій печері, що на захід звідси. Ось як ти думаєш, це павуків назвали на честь печери чи навпаки?", [3] = "Принесіть 40 цілих очей імлистих павуків Ярлу \"Болотному Оку\" в Світломлакий маєток.", [4] = "Ну, де очі?", [5] = "Ти {стать:знайшов:знайшла} очі! Ти {стать:знайшов:знайшла} їх! Смачні, смачнющі очі!\n\nЯкщо довго вдивлятися в деякі з них, вони почнуть вдивлятися в тебе. Їж їх останніми. Щоб не їсти на самоті.\n\nПривіт, маленькі павучі оченята. Привіт! Ви на смак, як курка. Липка, солона курка!\n\nМмм...", ["en"] = "Jarl Needs Eyes", ["tasks"] = { ["Unpopped Darkmist Eye"] = "ціле око імлистого павука", ["Unpopped Darkmist Eye (Provided)"] = "ціле око імлистого павука (видано)" } },
    [1218] = { [1] = "Духмяні спеції", [2] = "Мені подобається готувати. В болоті гарно готувати. Смажені зелені жаб'ячі лапки та інші такі страви.\n\nАле для готування мені потрібні спеції. Духмяні спеції. Тоді я зроблю гуляш, поїм його і тобі теж дам трохи.\n\nТо як, хочеш гуляш?", [3] = "Принесіть 3 порції духмяних спецій Ярлу \"Болотному Оку\" в Бруднолипку трясовину.", [4] = "Спеції. Без них життя зовсім прісне. {стать:Згоден:Згодна}?", [5] = "А, ось і спеції! А тепер приготуємо гарний болотяний гуляш.", ["en"] = "Soothing Spices", ["tasks"] = { ["Soothing Spices"] = "духмяні спеції", ["Soothing Spices (Provided)"] = "духмяні спеції (видано)" } },
    [1219] = { [1] = "Звіт орка", [2] = "Просіюючи землю, ви знаходите відрубану руку орка, що стискає різьблену кістяну трубку. В трубці — заляпаний брудом пергамент.\n\nПергамент написаний мовою орків... і виглядає важливим.", [3] = "Принесіть звіт шпигуна лейтенанту в Терамор.", [4] = "Ти щось хочеш мені повідомити?", [5] = "Хм... Я не дуже добре розумію оркську мову, але це виглядає як звіт... написаний шпигуном Орди!", ["en"] = "The Orc Report", ["tasks"] = { ["Spy's Report"] = "звіт шпигуна", ["Spy's Report (Provided)"] = "звіт шпигуна (видано)" } },
    [1220] = { [1] = "Капітан Ваймс", [2] = "Капітан Ваймс має поглянути на звіт орка, який ти {стать:знайшов:знайшла}, {ім'я}. Він знає оркську мову краще, ніж більшість з нас. І він повинен знати, що поруч з Терамором є шпигуни Орди!\n\nКапітан знаходиться в казармах у північно-східній частині острова Терамор.", [3] = "Принесіть звіт шпигуна капітану Ґаррану Ваймсу.", [4] = "Маєш щось для мене?", [5] = "Звіт шпигуна орків! Як ти {стать:знайшов:знайшла} це? Не важливо — погляньмо, що там написано...", ["en"] = "Captain Vimes", ["tasks"] = { ["Spy's Report"] = "звіт шпигуна", ["Spy's Report (Provided)"] = "звіт шпигуна (видано)" } },
    [1221] = { [1] = "Бульби синьолиста", [2] = "Бульби синьолиста — рідкісний делікатес! Дуже рідкісний. Він росте лиш в одному місці — глибоко під Степами в краалі Бритвоболотих.\n\nДо того ж їх важко знайти, якщо не знати, де шукати! Тому я надресував цих шморгоносів, щоб вони знаходили їх під землею. У них гарний нюх, тож вони можуть знайти ці бульби за кілька десятків метрів.\n\nЦе буде нелегко, та якщо принесеш кілька бульб — я щедро винагороджу тебе.", [3] = "Візьміть ящик з отворами.\nВізьміть палицю керування шморгоносом.\nВізьміть та прочитайте посібник власника шморгоноса.\n\nВ краалі Бритвоболотих випустіть шморгоноса з ящика з отворами та за допомогою палиці керування накажіть йому шукати бульби.\n\nПринесіть 6 бульб синьолиста, палицю керування шморгоносом та ящик з отворами Мебоку Міцріксу в Брашпиль.", [4] = "Ти {стать:приніс:принесла} бульби, {ім'я}?", [5] = "Чудово, вони в тебе! Я знаю, де їх можна гарно продати.\n\nДякую за доставку, {ім'я}! Я радий нашій співпраці.", ["en"] = "Blueleaf Tubers", ["tasks"] = { ["Blueleaf Tuber"] = "бульба синьолиста", ["Blueleaf Tuber (Provided)"] = "бульба синьолиста (видано)", ["Crate With Holes"] = "ящик з отворами", ["Crate With Holes (Provided)"] = "ящик з отворами (видано)", ["Snufflenose Command Stick"] = "палиця керування шморгоносом", ["Snufflenose Command Stick (Provided)"] = "палиця керування шморгоносом (видано)", ["Snufflenose Owner's Manual"] = "посібник власника шморгоноса", ["Snufflenose Owner's Manual (Provided)"] = "посібник власника шморгоноса (видано)" } },
    [126] = { [1] = "Виття з-за пагорбів", [2] = "{ім'я}, гноли все ще там. Я чую їхній гавкіт, коли вони полюють в горах над Приозер'ям. І один із них виє голосніше за інших — Скавчало, їхній лідер.\n\nВбий Скавчала і вся його зграя розбіжиться! Принеси мені його лапу як доказ.\n\nІ будь {стать:обережний:обережна}, цей гнол не дарма їхній лідер. Він не якийсь звичайний дворняга...", [3] = "Принесіть лапу Скавчала до Вернера Осґуда в Приозер'я.", [4] = "Скавчало — небезпечне створіння, {ім'я}. Якщо ти ще не {стать:готовий:готова} до битви з ним, я тебе розумію.", [5] = "І знову дякую тобі за допомогу. Армія Штормовію настільки зайнята боротьбою з орками, що у них не вистачає війська, щоб захистити Багрянокряжжя від таких загроз, як гноли.", ["en"] = "Howling in the Hills", ["tasks"] = { ["Yowler's Paw"] = "лапа Скавчала", ["Yowler's Paw (Provided)"] = "лапа Скавчала (видано)" } },
    [1260] = { [1] = "Морган Штерн", [2] = "Я розробляю нове меню для ресторану. Воно буде наповнене стравами сільської тематики та \"болотистого\" стилю. Думаю, клієнтам \"Синього Відлюдника\" сподобається!\n\nЯ відправив мого племінника Моргана в Терамор — місто на межі Бруднолипкої трясовини. Він там збирає місцеві кулінарні рецепти, і я маю дізнатись, як його успіхи.\n\nШлях до Терамору довгий. Занадто довгий для мене. Але я впевнений, що {стать:такий молодий:така молода} {клас}, як ти, з радістю погодиться на таку подорож, правда ж?", [3] = "Поговоріть з Морганом Штерном в Тераморі.", [5] = "Тебе прислав мій дядько, так?\n\nНу, я досліджував рецепти та маю певні успіхи, але мені потрібна допомога.\n\nСподіваюся, ти не боїшся промочити ноги.", ["en"] = "Morgan Stern" },
    [1263] = { [1] = "Палаючий заїзд <CHANGE TO GOSSIP>", ["en"] = "The Burning Inn <CHANGE TO GOSSIP>" },
    [1272] = { [1] = "Пошук Ріта <CHANGE INTO GOSSIP>", ["en"] = "Finding Reethe <CHANGE INTO GOSSIP>" },
    [1275] = { [1] = "Дослідження порчі", [2] = "Безрозсудні ельфи крові стали заручниками демонічної магії. Невже їх нічому не навчило те, що сталося з нагами та сатирами Калімдору?\n\nБоюсь, що ельфи крові можуть зазнати такого ж перетворення. Ми не можемо дозволити, щоб на Азероті з'явилась ще одна раса злісних чудовиськ.\n\nЯ хочу вивчити мозкові стовбури наг і сатирів, щоб зрозуміти, що чекає на ельфів. Ти знайдеш наг і сатирів в Чорноводних глибинах, що на узбережжі Ясенедолу.\n\nШлях неблизький, {ім'я}.", [3] = "Ґершала Нічношерех з Аубердіну просить вас принести 8 заражених мозкових стовбурів.", [4] = "Щойно ми матимемо достатньо зразків, я зможу стати до роботи. Мозкові стовбури сатирів і наг допоможуть мені дослідити кореляції в їхніх мутаціях.\n\nМожливо з цими знаннями ми можемо запобігти перетворенню ельфів крові на злих потвор.", [5] = "Шлях твій був неблизький і, певно, повний небезпек.\n\nДіяння твої воістину великодушні. Твоя допомога в моїх дослідах дозволить нам вберегти Азерот. Дякую тобі, {ім'я}, за всі твої діяння.\n\nА тепер дозволь мені зайнятись роботою...", ["en"] = "Researching the Corruption", ["tasks"] = { ["Corrupted Brain Stem"] = "заражений мозковий стовбур", ["Corrupted Brain Stem (Provided)"] = "заражений мозковий стовбур (видано)" } },
    [1277] = { [1] = "<nyi> <TXT> Сліди копит кентавра", [2] = "Кагоро розповів, що сліди копит кентавра належать якимось товстоголовим у Маврадоні.", ["en"] = "<nyi> <TXT> The Centaur Hoofprints" },
    [1278] = { [1] = "<nyi> <TXT> Клан Похмурого Тотема", ["en"] = "<nyi> <TXT> The Grim Totem Clan" },
    [1279] = { [1] = "<nyi> <TXT>Слідки копит кентавра", [2] = "Завершіть один з трьох.", ["en"] = "<nyi> <TXT>The Centaur Hoofprints" },
    [1280] = { [1] = "<nyi> <TXT>Слідки копит кентавра", ["en"] = "<nyi> <TXT>The Centaur Hoofprints" },
    [1281] = { [1] = "Пісня Джима <CHANGE TO GOSSIP>", ["en"] = "Jim's Song <CHANGE TO GOSSIP>" },
    [1283] = { [1] = "Пожежа в Тіньовому Відпочинку <CHANGE TO GOSSIP>", ["en"] = "Fire at the Shady Rest <CHANGE TO GOSSIP>" },
    [1287] = { [1] = "Дезертири", [2] = "Ріті? Цей боягуз?\n\nМи вигнали його з нашого табору, тому що він наполягав на тому, щоб викрасти запаси огрів з селища Папорохащі. Нас не так багато, щоб протистояти цим безтямним моцакам.\n\nВін надто багато разів переступив межу, тому ми вирішили, що з нас досить.\n\nОсь, я допоміг тобі... Тому, чому б тобі не допомогли нам і забути про нашу зустріч?", [3] = "Поговоріть про Ріта з капітаном Ґарраном Ваймсом в Тераморі.", [5] = "Я відправлю лейтенанта Кальдвела, щоб розв'язати проблему з дезертирами на Зруйнованій заставі та знайти Ріта. Болота не настільки великі, щоб Ріт міг сховатись від нас.", ["en"] = "The Deserters" },
    [1288] = { [1] = "Звіт Ваймса", [2] = "Гарна робота, {ім'я}, навіть чудова, як для новачка.\n\nЛеді Праудмур просила, щоб я повідомляв її про цю ситуацію, але я давно не спілкувався з нею.\n\nЯ планував подати свій звіт пізніше, але, здається, буде доречніше, якщо ти прийдеш до неї з цим звітом. Ти набагато краще за мене відповіси на її запитання.", [3] = "Принесіть звіт Ваймса леді Джайні Праудмур в Терамор.", [5] = "Зважаючи на звіт капітана Вімса, ти дуже {стать:допоміг:допомогла} йому у розслідуванні, і за це я тобі дуже вдячна.\n\nТепер я можу спокійно спати, знаючи, що справа в надійних руках. Я хотіла б попросити тебе повернутися до капітана Ваймса і допомогти йому розкрити цю таємницю.", ["en"] = "Vimes's Report", ["tasks"] = { ["Vimes's Report"] = "звіт Ваймса", ["Vimes's Report (Provided)"] = "звіт Ваймса (видано)" } },
    [1291] = { [1] = "<nyi> <TXT> Сліди копит кентавра", ["en"] = "<nyi> <TXT> Centaur Hoofprints" },
    [1292] = { [1] = "<nyi><TXT> Сліди копит кентавра", ["en"] = "<nyi><TXT> Centaur Hoofprints" },
    [1293] = { [1] = "<nyi> <TXT> Сліди копит кентавра", ["en"] = "<nyi> <TXT> Centaur Hoofprints" },
    [1294] = { [1] = "<nyi> <TXT>Співчуття до Кентавра", ["en"] = "<nyi> <TXT>Centaur Sympathies" },
