    [1300] = { [1] = "<nyi> <TXT> Похмурий тотем Похмурого Покинутого", ["en"] = "<nyi> <TXT> Lorn Grim Totem" },
    [1301] = { [1] = "Джеймс Хіал", [2] = "Перш ніж я почав працювати тут, в Синьому відлюднику, мене навчав один із найкращих шеф-кухарів і корчмарів, яких я коли-небудь зустрічав. Його звали Джеймс Хіал. Все, що я маю в житті, я отримав завдяки йому.\n\nЦікаво, як у нього справи. Він зі своїм братом Вінсентом пішов працювати в таверну в гавані Менетілів, але я давно не чув про нього.\n\nЯкщо ти колись опинишся поруч, може, ти {стать:міг би:могла б} передати йому від мене привіт?", [3] = "Поговоріть з Вінсентом Хіалом в гавані Менетілів.", [5] = "Джеймс? О, він пішов досить давно.\n\nМабуть, відчув нову хвилю патріотизму. Неважко зрозуміти, чому він це зробив. Після всього цього божевілля в Лордероні, багато людей відправилися з Джайною Праудмур за море.", ["en"] = "James Hyal" },
    [1302] = { [1] = "Джеймс Хіал", [2] = "Мій брат Джеймс відправився з пані Праудмур через море. Останнє, що я чув, це те що бої там припинилися, і Джеймс засновував таверну десь на континенті. Де б він не був, я впевнений, в нього все добре. Він був чудовим кухарем.\n\nЯ вже деякий час нічого про нього не чув — б'юсь об заклад, що він надто зайнятий своєю таверною — але писар у Тераморі, мабуть, міг би направити тебе до Джеймса.", [3] = "Поговоріть з писарем Лендрі в Тераморі.", [5] = "Джеймс Хіал, Джеймс Хіал... Чому це ім'я звучить так знайомо?\n\nЗвичайно! Той самий інцидент в таверні «Відпочинок у затінку». Якщо в вас є якась інформація про те, що там відбулося — поговоріть щодо цього з капітаном Ваймсом. Він веде розслідування.", ["en"] = "James Hyal" },
    [1318] = { [1] = "Незакінчена справа Ґордоків", [2] = "Тепер ти король, значить можливо ти зможеш відібрать цінний артефакт Ґордоків у того страшного ельфа, шо зове себе принцом! Прошлий король не справився з цим, як і всі інші, хто пробував його повернути, з тої давнини, як Тортельдрін, той страшний ельф, вкрав його в короля Ґордока!\n\nАртефакт зоветься рукавичкою могутності Ґордока. Старі легенди кажуть, шо повернуть її може тільки справжній король Ґордок. В старій легенді також говориться, шо цей страшний ельф все ще вештається десь поруч. Найди цей артефакт і матимеш могутню рукавичку, яку зможеш носить завжди!", [3] = "Знайдіть рукавичку могутності Ґордока і поверніть її капітану Дужохрусту в Грізний Молот.\n\nЗа словами Дужохруста, \"стара легенда\" свідчить, що Тортельдрін — \"страшний\" ельф, який називав себе принцом — вкрав її в одного з королів Ґордоків.", ["en"] = "Unfinished Gordok Business", ["tasks"] = { ["Gauntlet of Gordok Might"] = "рукавичка могутності Ґордока", ["Gauntlet of Gordok Might (Provided)"] = "рукавичка могутності Ґордока (видано)" } },
    [1358] = { [1] = "Зразок для Гелбріма", [2] = "Мій колега в Калімдорі, аптекар Гелбрім, досліджує дію лордеронських токсинів на звірів Калімдору. Він буде дуже зацікавлений зразками вовчих сердець, які мені надіслав Ренферрел.\n\nГелбрім перебуває у Степах, в поселенні, відомому як Перехрестя. Щоб добратися до нього, сідай на дирижабль і лети до столиці орків - Орґріммару, а потім йди пішки на південь, у Дуротар. Прямуй на захід у Степи та незабаром дійдеш до Перехрестя.", [3] = "Принесіть зразок вовчого серця аптекареві Гелбріму в Степи.", [4] = "У тебе для мене пакунок?", [5] = "О, дуже добре. Якщо початкові звіти правдиві, токсичність цих сердець може привести нас до подальших прогресу у нашому знанні отрут.\n\nЦе довгоочікуваний пакунок, {Ім'я}. Ти справді {стать:заробив:заробила} свою нагороду.", ["en"] = "Sample for Helbrim", ["tasks"] = { ["Wolf Heart Sample"] = "зразок вовчого серця", ["Wolf Heart Sample (Provided)"] = "зразок вовчого серця (видано)" } },
    [136] = { [1] = "Захований скарб капітана Сандерса", [2] = "Якщо ти читаєш це — значиться, дідуньо капітан Сандерс покоїться у водяній могилі. Отже, мій скарб тепер твій, тобі лише треба слідувати підказкам.\n\nСпочатку тобі треба знайти мо' скриньку. Скоріше за все її вже занесло піском на західному узбережжі Західного краю, біля розтрощеного корабля. На узбережжі буде багато уламків кораблів, але лише один ржавий якір. Знайди цей якір — і ти знайдеш мо' скриньку! Пошукай там наступну підказку.", [3] = "Знайдіть скриньку капітана Сандерса та пошукайте у ній наступну підказку.", ["en"] = "Captain Sander's Hidden Treasure" },
    [1363] = { [1] = "Вказівки Мазена", [2] = "Моя відповідальність, як хранителя бібліотеки академії арканічних мистецтв і наук — оберігати магічні фоліанти та сувої. Хтозна, яка біда може статись, якщо вони потраплять в погані руки.\n\nДо речі, про це. Мій помічник, Делліс, минулого тижня припустився помилки. Він досить здібний і добре орієнтується в бібліотеці, та розгублюється, щойно виходить за ворота Штормовія. Прошу тебе, допоможи Деллісу з його труднощами.", [3] = "Поговоріть з помічником Деллісом в ШтормовіЇ.", [5] = "Це не моя вина. Чесно.", ["en"] = "Mazen's Behest" },
    [1364] = { [1] = "Вказівки Мазена", [2] = "Майстер Мазен дав чіткі вказівки: доставити важливе дослідження наглядачу Магару Ба в фортецю Підсвітньої Варти.\n\nТа я ніколи не був раніше у Спустошених землях! Це була жахлива подорож!\n\nНа болоті Скорбот я помилився шляхом і втрапив у засідку жахливих болотяних рослин-чудовиськ. Вони збирались напасти на мене, тому я втік. Та в поспіху я загубив дослідження. Я впевнений, його забрало одне з чудовиськ.\n\nЧи не {стать:міг би:могла б} ти знайти її та доставити Магару Ба?", [3] = "Знайдіть дослідження просторової конвергенції Кадґара та доставте його наглядачу Магару Ба у фортецю Підсвітньої Варти.", [4] = "Що привело тебе до фортеці Підсвітньої Варти, {раса:к}?", [5] = "А, чудово!\n\nЯ вже боявся, що майстер Мазен з академії арканічних мистецтв і наук пропустив моє замовлення дослідження просторової конвергенції Кадґара.\n\nВін певно ледь справляється з запитами, враховуючи купу нещодавніх дивних подій.\n\nА тепер вибач, та я маю продовжити свої дослідження. Нарешті я зможу доторкнутись до результатів проникливості величного Кадґара, це так хвилююче...", ["en"] = "Mazen's Behest", ["tasks"] = { ["Khadgar's Essays on Dimensional Convergence"] = "дослідження просторової конвергенції Кадґара", ["Khadgar's Essays on Dimensional Convergence (Provided)"] = "дослідження просторової конвергенції Кадґара (видано)" } },
    [1367] = { [1] = "Союз з Маґрамами", [2] = "Щоб перемогти кентаврів, ми повинні використати їхню ненависть проти них самих. Ми об'єднаємося з одним із кланів і з його допомогою дізнаємось, як перемогти всі клани.\n\nЯкщо ти вирішиш об'єднатися з Маґрамами, вбий їхніх ворогів — Ґелкісів. Так ти завоюєш повагу серед Маґрамів. Коли вони будуть достатньо довіряти тобі, зустрінься з речником Маграмів Варуґом на околиці поселення Маґрамів, що на південному сході Спустошища.", [3] = "Досягніть дружніх відносин з Маґрамами та поговоріть з Варуґом.", [4] = "Йди геть! Маґрами не говорять зі слабкими. Ми вбиваємо їх!\n\nЯкщо ти хочеш поговорити зі мною, то покажи мені свою силу. Повертайся, коли вб'єш багато Ґелкісів.", [5] = "Ґелкіси плачуть, коли чують твоє ім'я, {ім'я}. Вони бояться і ненавидять тебе. Так само як ненавидять Маґрамів!\n\nМожливо, ти {стать:такий же сильний:така ж сильна}, як і Маґрами. Подивимось...", ["en"] = "Magram Alliance", ["tasks"] = { ["3000 reputation with Magram Clan Centaur"] = "3000 репутації у кланового кентавра Маграм" } },
    [1368] = { [1] = "Союз з Ґелкісами", [2] = "Щоб перемогти кентаврів, ми повинні використати їхню ненависть проти них самих. Ми об'єднаємося з одним з кланів і з його допомогою дізнаємось, як перемогти всі клани.\n\nЯкщо ти вирішиш об'єднатися з Ґелкісами, вбий їхніх найненависніших суперників — Маґрамів. Після того, як ти завоюєш повагу Ґелкісів, постарайся зустрітися з шаманкою Утекою Розсудливою на околиці поселення Ґелкісів, що на південному заході Спустошища.", [3] = "Досягніть дружніх відносин з Ґелкісами та поговоріть з Утекою Розсудливою.", [4] = "Твої ноги ступили на землю Ґелкісів. Тобі тут не раді!\n\nДоведи, що ти хочеш дружити з Ґелкісами. Убий маґрамських кентаврів. Повертайся, коли маґрамська кров змочить землю.", [5] = "Земля говорить зі мною. І вона каже, що ти {стать:вбив:вбила} багато Маґрамів. Це добре.\n\nЯкщо ти хочеш бути {стать:другом:подругою} для Ґелкісів, тоді слухай. Я маю ще одне завдання для тебе.", ["en"] = "Gelkis Alliance", ["tasks"] = { ["3000 reputation with Gelkis Clan Centaur"] = "3000 репутації у кентавра клану Гелкіс" } },
    [1369] = { [1] = "Розбиті сльози", [2] = "Ґелкіси думають, що наша мати кентаврів, Терадрас, захищає нас. Вони дурні. Кентавра ніхто не захищає. Маґрами не потребують захисту! Ми найсильніші!\n\nПокажи Ґелкісам, що вони дурні. Йди до печери в їхньому селищі. У тій печері вони зберігають кристали, сльози Терадрас. Знищи сльози та принеси мені осколки!", [3] = "Для підтримки відносин з Маґрамами принесіть 3 розбиті сльози до Варуґа в поселення Маґрамів.", [4] = "Якщо ти нам не ворог, то зробиш те, що я прошу!", [5] = "Ти {стать:дістав:дістала} сльози! Тепер Ґелкіси знатимуть, що Терадрас їм не допоможе. Вона не буде плакати, коли ми їх розтрощимо! Маґрами правитимуть!\n\nТи розумно {стать:вчинив:вчинила}, коли {стать:допоміг:допомогла} нам, {ім'я}. Ми найсильніші.", ["en"] = "Broken Tears", ["tasks"] = { ["3000 reputation with Magram Clan Centaur"] = "3000 репутації у кланового кентавра Маграм", ["Broken Tears"] = "розбиті сльози", ["Broken Tears (Provided)"] = "розбиті сльози (видано)", ["Tears Destroyed"] = "Знищені сльози" } },
    [137] = { [1] = "<NYI> <TXT> Похвала Штормовію", [2] = "Якщо отримаєш похвалу від одного з наших маршалів, то принеси її мені. Вона підійде для однієї з наших рукавичок з емблемою Лева.", ["en"] = "<NYI> <TXT> Stormwind Commendation", ["tasks"] = { ["Commendation - Elwynn Forest"] = "Подяка — Ельвиннський ліс" } },
    [1370] = { [1] = "Викрадення припасів", [2] = "Коли ми не воюємо, ми полюємо заради м'яса. М'ясо дає нам силу, а з повним шлунком воювати набагато краще, ніж з порожнім.\n\nТак само і з Маґрами. Вони запасаються м'ясом, щоб довше воювати. Якщо ти нападеш на їхнє селище на сході й викрадеш запаси м'яса, то вони стануть слабшими.", [3] = "Принесіть 6 мішків грубо в'яленого м'яса та віддайте Утеці Розсудливій в поселенні Ґелкісів.", [4] = "Повертайся тоді, коли доведеш свою цінність для Ґелкісів!", [5] = "Добре. Я чую, як гучно буркотять животи Маґрамів в їхньому селищі. Чую це навіть тут!\n\nЯ віддам м'ясо Ґелкісам. І ми будемо довго воювати без відпочинку.\n\nТе, що ти {стать:зробив:зробила}, добре для Ґелкісів, {ім'я}.", ["en"] = "Stealing Supplies", ["tasks"] = { ["3000 reputation with Gelkis Clan Centaur"] = "3000 репутації у кентавра клану Гелкіс", ["Crudely Dried Meat"] = "грубо в'ялене м'ясо", ["Crudely Dried Meat (Provided)"] = "грубо в'ялене м'ясо (видано)" } },
    [1371] = { [1] = "Штучка для Варуґа", [2] = "Давним-давно до Спустошища прийшов маленький гном. У нього були коні та візок з дивними речами. Кумедними речами. Деякі світились різними кольорами. Деякі рухалися і при цьому не були живими. Я вбив цього маленького гнома, але перед тим... він змусив мене сміятися.\n\nЯ забрав свою улюблену річ з його возика. Це був дерев'яний чоловічок, який махав мені рукою, поки я не вдарив його і не зламав.\n\nЯ хочу нового дерев'яного чоловічка. Дістань мені ще одного!", [3] = "Для підтримки відносин з Маґрамами принесіть вдосконалений манекен-мішень Варуґу в поселення Маґрамів у Спустошище.", [4] = "Якщо ти нам не ворог, то зробиш те, що я прошу!", [5] = "Так, саме такий чоловічок у мене був! Я змушу його рухатися знову. Це веселить мене!", ["en"] = "Gizmo for Warug", ["tasks"] = { ["3000 reputation with Magram Clan Centaur"] = "3000 репутації у кланового кентавра Маграм", ["Advanced Target Dummy"] = "вдосконалений манекен-мішень", ["Advanced Target Dummy (Provided)"] = "вдосконалений манекен-мішень (видано)", ["Advanced Target Dummy slain"] = "вдосконалений манекен-мішень: убито" } },
    [1373] = { [1] = "Онґеку", [2] = "Тобі ще належить багато працювати над нашими відносинами й наступне завдання доведеться виконувати далеко звідси. Тож поки що Ґелкіси воюватимуть проти Маґрамів без тебе.\n\nЗемля розкриває безліч таємниць тим, хто вміє слухати її. І одна з них — таємниця червоного кристала, який називають дренетистом. Він походить з місця, де гори літають в небі й де панують демони.\n\nПринеси мені уламок дренетиста, з ним моя магія стане сильнішою! Уламок знаходиться в місці, що зветься болотом Скорбот, його оберігає один із загублених — Онґеку.", [3] = "Для підтримки відносин з Ґелкісами принесіть уламок дренетиста Утеці Розсудливій в поселення Ґелкісів в Спустошищі.", [4] = "Доведи, що ти {стать:друг:подруга} Ґелкісів, {ім'я}.", [5] = "Так, це той самий уламок, про який шепотіла земля. Я відчуваю сильну магію в ньому! Я використаю її проти ворогів Ґелкісів.\n\nТи {стать:виконав:виконала} для нас ще одне завдання, {ім'я}. Можливо, скоро ми зможемо називати тебе {стать:нашим другом:нашою подругою}.", ["en"] = "Ongeku", ["tasks"] = { ["3000 reputation with Gelkis Clan Centaur"] = "3000 репутації у кентавра клану Гелкіс", ["Draenethyst Shard"] = "уламок дренетиста", ["Draenethyst Shard (Provided)"] = "уламок дренетиста (видано)" } },
    [1374] = { [1] = "Хан Джен", [2] = "Земля говорить зі мною і вона каже, що Маґрами втрачають свою силу. Прийшов час вбити їхнього хана!\n\nПринеси мені голову хана Маґрамів, Джена!", [3] = "Принесіть голову хана Джена Утеці Розсудливій в поселення Ґелкісів у Спустошищі.", [4] = "Доведи, що ти {стать:друг:подруга} Ґелкісів, {ім'я}.", [5] = "Хан Джен був сильним, але дурним. Він думав, що наділений великою силою. Але не бачив, що магія землі сильніша. Тепер, без свого ватажка, Маґрамські кентаври падуть, а Ґелкіси правитимуть!", ["en"] = "Khan Jehn", ["tasks"] = { ["3000 reputation with Gelkis Clan Centaur"] = "3000 репутації у кентавра клану Гелкіс", ["Khan Jehn's Head"] = "голова хана Джена", ["Khan Jehn's Head (Provided)"] = "голова хана Джена (видано)" } },
    [1375] = { [1] = "Хан Шака", [2] = "Ти допомагаєш Маґрамам, тому ти мені подобаєшся. А тепер іди та вбий хана Ґелкісів! Це хан Шака, мені потрібна його голова! Я хочу дивитися на неї й сміятися з нього!", [3] = "Для підтримки відносин з Маґрамами принесіть голову хана Шаки Варуґу в поселення Маґрамів в Спустошище.", [4] = "Виконай завдання для Маґрамів, і я допоможу тобі.", [5] = "Хан Шака мертвий! Я насаджу його голову на піку і поставлю її поряд, щоб Шака бачив силу Маґрамів!", ["en"] = "Khan Shaka", ["tasks"] = { ["3000 reputation with Magram Clan Centaur"] = "3000 репутації у кланового кентавра Маграм", ["Khan Shaka's Head"] = "голова хана Шаки", ["Khan Shaka's Head (Provided)"] = "голова хана Шаки (видано)" } },
    [138] = { [1] = "Захований скарб капітана Сандерса", [2] = "Підказка до пошуку скарбу така: \"Хороша робота, друзяко! Тепер чапай на схід. На схід через кручі, на схід до дороги. Шукай на узбіччі дороги рештки старого димоходу. Там знайдеш стару бочку, в якій буде наступна підказка.\"", [3] = "Знайдіть стару діжку поблизу зруйнованого димоходу і пошукайте в ній наступну підказку.", [5] = "Хороша робота, {стать:мисливцю:мисливице} за скарбами!", ["en"] = "Captain Sanders' Hidden Treasure", ["tasks"] = { ["A Clue to Sander's Treasure"] = "підказка до скарбів Сандерса" } },
    [1380] = { [1] = "Хан Грата", [2] = "{ім'я}, ти {стать:допоміг:допомогла} нам перемогти Маґрамів. Тепер допоможи нам перемогти Мародінів! Вбий їхнього ватажка, хана Грата!\n\nЩоб викликати його, потрібно засурмити в бойовий ріг Мародінів. Він знаходиться на високій скелі в долині Списів.\n\nДля того, щоб засурмити в бойовий ріг, тобі потрібно дістати мундштук. Ці штуки досить рідкісні, їх мають лише довірені мародінські кентаври.\n\nПісля того, як ти засурмиш в ріг, з'являться кентаври. Тобі доведеться вбивати їх, доки не доберешся до Грати.\n\nХан Грата має шматок... одного ключа. Принеси його мені...", [3] = "Для підтримки відносин з Ґелкісами принесіть мародінський фрагмент ключа Утеці Розсудливій в поселення Ґелкісів.", [4] = "Хан Грата мертвий? Ти {стать:дістав:дістала} фрагмент ключа?", [5] = "Він мертвий! Хан Грата мертвий! Тепер Мародіни падуть! Коли Ґелкіси будуть правити цією землею, {ім'я}, ми не забудемо про тебе. Духи землі оспівуватимуть твоє ім'я вічно.", ["en"] = "Khan Hratha", ["tasks"] = { ["3000 reputation with Gelkis Clan Centaur"] = "3000 репутації у кентавра клану Гелкіс", ["Maraudine Key Fragment"] = "мародінський фрагмент ключа", ["Maraudine Key Fragment (Provided)"] = "мародінський фрагмент ключа (видано)" } },
    [1381] = { [1] = "Хан Грата", [2] = "Хан Ґелкісів мертвий, а тепер і Мародіни падуть! Вбий хана Мародінів, Грата!\n\nЩоб викликати його, засурми в ріг на високій скелі в долині Списів. Але без мундштука ти не зможеш засурмити в ріг. Тобі потрібно вбивати мародінських кентаврів, поки не знайдеш мундштук. Потім засурми в ріг.\n\nКоли ти зробиш це, до вежі збіжаться мародінські кентаври. Вбивай їх, поки не з'явиться хан Грата. Він має фрагмент ключа. Принеси його мені...", [3] = "Для підтримки відносин з Маґрамами принесіть мародінський фрагмент ключа Варуґу в поселення Маґрамів в Спустошище.", [4] = "Зроби те, що я прошу. Доведи мені, що ти {стать:гідний:гідна} бути {стать:союзником:союзницею} Маґрамів!", [5] = "Хан Грата мертвий! Тепер Маґрами — найсильніші серед кентаврів! Ми розтрощимо інших і будемо правити Спустошищем!\n\nТвоє ім'я буде завжди в нашій пам'яті, {ім'я} і коли всі інші вмиратимуть під нашими копитами, ми не завдамо тобі шкоди.", ["en"] = "Khan Hratha", ["tasks"] = { ["3000 reputation with Magram Clan Centaur"] = "3000 репутації у кланового кентавра Маграм", ["Maraudine Key Fragment"] = "мародінський фрагмент ключа", ["Maraudine Key Fragment (Provided)"] = "мародінський фрагмент ключа (видано)" } },
    [1382] = { [1] = "Дивний союз", [2] = "Нам пощастило, що клани кентаврів воюють між собою, бо якби вони об'єдналися, їх було б не зупинити. Так, нам пощастило, і ми повинні використати нашу перевагу.\n\nОдин з кланів кентаврів, клан Ґелкісів, веде жорстоку війну з кланом Маґрамів. Якщо ми нападемо на Маґрамів, то, можливо, вдасться укласти союз з Гелкісами.\n\nПоговори з Утекою Розсудливою, ти зможеш її знайти в околицях табору Ґелкісів на південному заході Спустошища. Через неї ми можемо укласти союз з Ґелкісами.", [3] = "Досягніть дружніх відносин з Ґелкісами та поговоріть з Утекою Розсудливою.", [4] = "Йди геть! Ґелкіси не хочуть бачити тебе тут. Іди негайно!!!\n\nПовертайся, коли вб'єш багато Маґрамів, тоді й поговоримо.", [5] = "Ґелкіси говорять про тебе. На твоїх руках багато крові Маґрамів. Це добре.\n\nМожливо, буде також добре, якщо ми поговоримо. Скажи, що ти можеш зробити для Ґелкісів і що ми можемо зробити для тебе.", ["en"] = "Strange Alliance", ["tasks"] = { ["3000 reputation with Gelkis Clan Centaur"] = "3000 репутації у кентавра клану Гелкіс" } },
    [1384] = { [1] = "Наліт на клан Колкар", [2] = "Колкарські кентаври думають, що їхня магія сильна. Але вони нічого не розуміють в магії! Вони б не пізнали магію, навіть якби вона їх вкусила!\n\nТи маєш показати їм, що їхня магія слабка. Йди на північний схід знайди Колкарів та вбий їх. Відбери в них їхні обереги та принеси мені, а я кину їх у вогонь і сміятимусь!", [3] = "Для підтримки відносин з Ґелкісами принесіть 10 грубих оберегів Утеці Розсудливій в поселення Ґелкісів у Спустошищі.", [4] = "Ти {стать:дістав:дістала} обереги? Ти {стать:показав:показала} Колкарам які вони слабкі?", [5] = "Ти {стать:зробив:зробила} добру справу для Ґелкісів. Колкари слабкі й через це помруть. Їхня жалюгідна магія не врятує їх. Ти {стать:показав:показала} їм це і страх зробить їх ще слабшими!\n\nА на наших землях слабаки швидко вмирають.", ["en"] = "Raid on the Kolkar", ["tasks"] = { ["3000 reputation with Gelkis Clan Centaur"] = "3000 репутації у кентавра клану Гелкіс", ["Crude Charm"] = "грубий оберіг", ["Crude Charm (Provided)"] = "грубий оберіг (видано)" } },
    [1385] = { [1] = "Політика жорстокості", [2] = "Спустошище — це земля, охоплена війною. Кентаври ведуть війну один з одним, і ми боїмося того, що переможна сторона нападе на нас та зруйнує наші фортеці. Ми не можемо цього допустити.\n\nМи повинні навчитися перемагати кентаврів, а для цього... нам потрібно об'єднатися з одним із кланів. Маґрамські кентаври воюють з Ґелкісами. Якщо ти битимешся проти Ґелкісів, Маґрами можуть розглянути можливість союзу з нами.\n\nЗаслужи прихильність Маґрамів і поговори з Варуґом у селищі Маґрамів на південному сході Спустошища.", [3] = "Досягніть дружніх відносин з Маґрамами та поговоріть з Варуґом.", [4] = "Іди геть, або Маґрами розчавлять тебе! Щоб стати нашим другом, ти маєш вбити Ґелкісів.", [5] = "Багато Ґелкісів загинули від твоєї руки. Мені це подобається. Можливо, ти зробиш щось ще, що мені сподобається. Можливо, ти зможеш здружитися з Маґрамами.", ["en"] = "Brutal Politics", ["tasks"] = { ["3000 reputation with Magram Clan Centaur"] = "3000 репутації у кланового кентавра Маграм" } },
    [1386] = { [1] = "Напад на клан Колкар", [2] = "Колкари думають, що вони сильні, але ми насміхаємося з них! Ми сміємось та вбиваємо їх! Ти вбиваєш їх також. Покажи, що ти можеш вбивати Колкарів не гірше нас. Прямуй на північ та вбий їх усіх!", [3] = "Для підтримки відносин з Маґрамами вбийте 12 колкарських кентаврів, 12 колкарських розвідників і 6 колкарських молотобоїв, потім поверніться до Варуґа в поселення Маґрамів в Спустошище.", [4] = "Ти боїшся Колкарів? Чому ти не {стать:вбив:вбила} їх? Може, ти {стать:забув:забула} як вбивати? Поквапся та вбий Колкарів, поки вони не загинули!", [5] = "Тепер Колкари бояться тебе! Сподіваюсь, ти {стать:сміявся:сміялась}, коли {стать:вбивав:вбивала} їх. Краще сміятись, коли вбиваєш, щоб ворог бачив який він слабкий.", ["en"] = "Assault on the Kolkar", ["tasks"] = { ["3000 reputation with Magram Clan Centaur"] = "3000 репутації у кланового кентавра Маграм", ["Kolkar Centaur"] = "колкарський кентавр", ["Kolkar Centaur slain"] = "колкарський кентавр: убито", ["Kolkar Mauler"] = "колкарський молотобій", ["Kolkar Mauler slain"] = "колкарський молотобій: убито", ["Kolkar Scout"] = "колкарський розвідник", ["Kolkar Scout slain"] = "колкарський розвідник: убито" } },
    [1387] = { [1] = "Нагорода за кентаврів", [2] = "Раса кентаврів складається з багатьох кланів. У кожного з них є свій лідер і свої цілі, але всі клани мають одну спільну рису. Жорстокість.\n\nЯкщо ми хочемо досягти миру, кентаврів треба знищити. І я доручаю тобі це зробити.\n\nБлукаючи Спустошищем, ти будеш вбивати кентаврів і збирати їхні вуха. Принеси мені багато вух.\n\nЗроби це на благо Альянсу, {ім'я}, і ми станемо на крок ближче до завершення цієї війни.", [3] = "Принесіть 15 вух кентаврів капралу Мелкінсу в оплот Найджела, що в Спустошищі.", [4] = "Ти маєш що сказати, {ім'я}?", [5] = "О, вуха. Молодець.\n\nЖодних сумнівів, ти {стать:зробив:зробила} великий вклад для Альянсу, {ім'я}. Повір, кров, яку ти {стать:пролив:пролила} в Спустошищі, врятує незліченну кількість життів.", ["en"] = "Centaur Bounty", ["tasks"] = { ["Centaur Ear"] = "вухо кентавра", ["Centaur Ear (Provided)"] = "вухо кентавра (видано)" } },
    [1389] = { [1] = "Кристали дренетисту", [2] = "Загублені, що живуть в Тьмяному пристановищі, на вигляд від нас не відрізняються, але насправді це чудовиська... збожеволілі під час тяжкого шляху до Азероту. Колись вони були нашими братами, але тепер вони живуть в Тьмяному пристановищі, на схід звідси, захоплюючи та вбиваючи будь-кого, хто блукатиме поруч.\n\nВони вкрали дещо священне для нас — кристали дренетисту.\n\nВ нас не вистачає сил увірватися в Тьмяне пристановище і повернути наш вкрадений дренетист, але без тих кристалів... ми теж можемо втратити свій шлях.", [3] = "Принесіть 6 кристалів дренетисту Маґтуру в Сховище, що на болоті Скорбот.", [4] = "Тобі вдалося повернути кристали?", [5] = "Дякую, {ім'я}. Ми в боргу перед тобою.", ["en"] = "Draenethyst Crystals", ["tasks"] = { ["Draenethyst Crystal"] = "кристал дренетисту", ["Draenethyst Crystal (Provided)"] = "кристал дренетисту (видано)" } },
    [139] = { [1] = "Захований скарб капітана Сандерса", [2] = "Обшукуючи бочку, ви знаходите ще один шматок пергаменту. На ньому написано: \"А тепер поверни мармизу на північ від сієї бочки. Прямо, як ворон летить, чимчикуй, доки не натрапиш на порожній глечик поруч із самотнім вітряком на прибережних бескидах. Якщо ретельно потермосиш той глечик — може, знайдеш те, що шукаєш.\"", [3] = "Обшукайте порожній глечик біля вітряка для наступної підказки.", [5] = "Ви ще ближче до мети, шукачу скарбів!", ["en"] = "Captain Sanders' Hidden Treasure", ["tasks"] = { ["Another Clue to Sander's Treasure"] = "ще одна підказка до скарбів Сандерса" } },
    [1392] = { [1] = "Нобору-Дубина", [2] = "Нобору місяцями нападав на дренеїв Сховища, і його дубина стала символом жорстокості, якої вони зазнали від рук Загублених.", [3] = "Принесіть дубину Нобору очільнику Сховища на болото Скорбот.", [4] = "Вітаю. І ласкаво просимо до Сховища.", [5] = "Ти {стать:здобув:здобула} зброю жахливого Нобору? Отже, він мертвий?\n\nЦе радісний день для всього Сховища. Нобору і його банда багато років тероризували нас, вони блукали по болотах і вбивали кожного дренея, що траплявся на їхньому шляху. Він був прямою загрозою для нашого виживання, і ми не мали сил впоратися з ним самостійно.\n\nНам пощастило мати такого друга, як ти, {ім'я}.", ["en"] = "Noboru the Cudgel", ["tasks"] = { ["Noboru's Cudgel"] = "дубина Нобору", ["Noboru's Cudgel (Provided)"] = "дубина Нобору (видано)" } },
    [1393] = { [1] = "Втеча Ґалена", [2] = "Будь ласка, допоможи! Ці тварюки хочуть мене з'їсти!\n\nЯкщо ти допоможеш мені вибратися звідси, то отримаєш великий скарб! Він лежить в моєму таборі, в болотах на північ від Камінарду, але сейф міцний і тільки я знаю, як його відчинити.\n\nЯкщо ти допоможеш мені, я навчу тебе, як відкрити сейф.", [3] = "Виведіть Ґалена з небезпечного місця, потім знайдіть його табір на болоті Скорбот і відкрийте його сейф.", [4] = "Замкова щілина цього сейфа залита чорною смолою. Відкрити його неможливо.", [5] = "Замкова щілина цього сейфа залита чорною смолою. Відкрити його неможливо.\n\nАле Ґален розповів вам про прихований засув на дні сейфа...\n\n...Після швидкого огляду сейфа засув знайдено. Засув ляскає, і сейф відчиняється...", ["en"] = "Galen's Escape", ["tasks"] = { ["Escort Galen out of the Fallow Sanctuary."] = "Виведіть Галена з Непарного святилища." } },
    [140] = { [1] = "Захований скарб капітана Сандерса", [2] = "Звичайно ж, глибоко всередині старого глечика лежить ще одна підказка щодо скарбу Сандерса. Чорнило подекуди розплилося і від паперу тхне віскі, але дещо вам вдалося розібрати: \"Якщо вже тобі вдалося знайти мо' старий глечик з-під віскі, значить, ти близько до скарбу! Йди від пляшки на захід і спустися до берега. Як доберешся до води — не зупиняйся! Пливи на захід, доки не знайдеш острів, де є мо' скриня зі скарбом!\"", [3] = "Знайдіть скриню капітана Сандерса й отримайте з неї вашу винагороду.", [5] = "Петлі на старій скрині іржаві, але вони все ще працюють. Ви з зусиллям відкриваєте скриню та дістаєте здобич.\n\nВітання!", ["en"] = "Captain Sanders' Hidden Treasure", ["tasks"] = { ["Final Clue to Sander's Treasure"] = "остання підказка до скарбів Сандерса" } },
    [1437] = { [1] = "Пошукова операція Валарріеля", [2] = "Вітаю, {ім'я}, мене звати Валарріель. Я прибув сюди, щоб з'ясувати місцеперебування двох зниклих дворян з поважної дарнаської сім'ї — дому Малемів. Голава дому боїться, що могло статися найгірше і я маю зробити все можливе, щоб знайти його зниклих дітей. Щоправда, я ще не почав шукати Тіраніса і Далінду, але сподіваюся, що не затримаюся тут надовго.\n\nОстаннє, що я чув — вони проїжджали через Каміннопазуристі гори кілька тижнів тому.\n\nЯкщо ти побачиш їхній віз, будь ласка, сповісти мене якнайшвидше.", [3] = "Відправляйтеся в Спустошище й знайдіть віз Тіраніса та Далінди Малемів.", [5] = "Судячи з вигляду воза, стає очевидно, що його атакували як заклинаннями, так і зброєю. Схоже, бій був коротким, і в однієї зі сторін не було жодних шансів — не видно ні крові, ні решток тіл.\n\nХто б не напав на віз, він діяв ефективно і швидко.", ["en"] = "Vahlarriel's Search" },
    [1438] = { [1] = "Пошукова операція Валарріеля", [2] = "Постарайся відшукати Далінду та Тіраніса і, що б ти не {стать:знайшов:знайшла}, негайно дай мені знати. Почни пошуки з тієї фортеці, а я негайно зв'яжуся з моїм керівництвом у Дарнасі й повідомлю про ситуацію.\n\n{ім'я}, є ще дещо, що я хотів би тобі повідомити. Моє керівництво застерігало мене щодо Тіраніса і його мотивів приїзду сюди. Для них важливіше знайти Далінду живою і неушкодженою. А от Тіраніса потрібно... перевірити.", [3] = "Знайдіть Далінду Малем в Спустошищі.", [5] = "Дякувати Елуні, хтось нарешті прийшов на допомогу. Будь ласка, {клас:к}, допоможи мені. Орки Палаючого Леза схопили мене і мого брата Тіраніса й притягли сюди. Я думаю, вони хочуть принести мене в жертву своїм демонічним господарям!\n\nЯ знала, що поїздка в Спустошище була помилкою, але Тіраніс так наполягав... Він жадав дізнатися усі таємниці — навіть, якщо це буде проти волі нашого народу. Він був готовий піти в цей похід навіть після всіх розповідей про тутешніх демонів.\n\nБоюся, що з ним сталося щось дуже погане.", ["en"] = "Vahlarriel's Search" },
    [1439] = { [1] = "Пошуки Тіраніса", [2] = "Нас притягли сюди після того, як орки перебили усю нашу охорону та слуг. Ти уявити собі не можеш, які жахливі речі вони з ними робили! Я думала, що вони нас теж вб'ють, але виявилося, що у них були інші плани.\n\nТіраніс намагався поговорити з ними. Думаю, він хотів вразити їх своїм знанням таємниць... Не знаю, навіщо.\n\nБудь ласка, допоможи. Я не можу піти звідси, поки не дізнаюся, що сталося з моїм братом. Знайди його, або хоча б дізнайся, що з ним сталось...", [3] = "Відшукайте Тіраніса Малема в Спустошищі.", [4] = "Боюся, що Тіраніс спробує дізнатися таємниці Палаючого Леза і стати одним з них, якщо, звісно, вони це дозволять — його завжди захоплювала сила, яку дає магія.\n\nНе думаю, що зможу повернутися додому до своєї сім'ї, знаючи, що душа Тіраніса наражається на таку небезпеку. Мій народ вважає вивчення подібної магії важким злочином, але стати тим, від кого ми намагаємося захиститися...", [5] = "Це жахливо! Але це був єдиний вихід. Якщо не ти, то його убив би мій народ. Гадаю, я маю подякувати тобі — будь ласка, вибач, якщо це звучить достатньо щиро. Думаю, ти розумієш, чому.\n\nТепер, коли я дізналася, про долю мого брата, думаю, настав час тікати звідси. Якщо ти ще не {стать:передумав:передумала}, я прийму твою допомогу та покину це жахливе місце.\n\nКоли будеш {стать:готовий:готова}, скажи мені й ми вирушимо до безпечного місця.", ["en"] = "Search for Tyranis", ["tasks"] = { ["Tyranis' Pendant"] = "кулон Тіраніса", ["Tyranis' Pendant (Provided)"] = "кулон Тіраніса (видано)" } },
    [1440] = { [1] = "Повернення до Валарріеля", [2] = "Отже, час настав? Я ціную твої зусилля, дозволь мені подякувати за все, що ти {стать:зробив:зробила} для мене і моєї сім'ї. Якщо ти {стать:готовий:готова}, то мені тут більше нічого робити — можемо вирушати.", [3] = "Виведіть Далінду Малем з фортеці Грозової Сокири, а потім поверніться до Валарріеля Демоновбивці в Спустошище.", [5] = "Дякую тобі, {ім'я}. Далінда успішно повернулася в оплот Найджела і вона в набагато кращому стані, ніж я міг би сподіватися. Той факт, що вона дісталася сюди власними силами - добрий знак. Сподіваюся, з тобою теж усе гаразд?\n\nМені боляче усвідомлювати, що Тіраніс не повернувся разом з Даліндою, але їй доведеться з цим змиритися. До того ж їй ще доведеться мати справу з наслідками його дій, коли вона повернеться до Дарнасу.", ["en"] = "Return to Vahlarriel", ["tasks"] = { ["Rescue Dalinda Malem"] = "Врятуйте Далінду Малем" } },
    [1441] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [1442] = { [1] = "Пошуки самоцвіту Кора", [2] = "Вітаю, {ім'я}. Чим я можу бути корисний {стать:послідовнику:послідовниці} Світла?\n\nО, так, коваль Стілвелл... давно ми не бачились. Я добре його пам'ятаю, хоч і давно не чув про нього.\n\nВін ніколи не здавався мені злим чоловіком, тож, думаю, його бажання отримати самоцвіт Кора благородне.\n\nЯкщо ти хочеш отримати один з цим самоцвітів — йди на північний захід Ясенедолу. Там, серед древніх руїн храму лежать Чорноводні глибини. Ти знайдеш там наг, що досі використовують ці самоцвіти. Не йди туди {стать:сам:сама}, {клас:н}.", [3] = "Принесіть самоцвіт Кора Тандрісу Вітроткачу в Темнобережжя.", [4] = "Я б менше довіряв тому, хто хоче отримати самоцвіт Кора, якби це не був послідовник Світла. Але таким, як ти, я довіряю більше ніж деяким нічним ельфам. Я б не оцінював ваш орден по діяннях лише одного з ваших послідовників.", [5] = "Це саме той самоцвіт, який потрібен Стілвеллу. Та перш ніж ти підеш, дозволь мені очистити його. Наги наповнюють їх силою, але своєю, злою силою.\n\nПередай Стілвеллу, що сила каменю очищена і він може використовувати його у своїх ритуалах.\n\nСподіваюсь, ти знаєш, що робиш, {клас:к}. В твоїх руках могутня річ.", ["en"] = "Seeking the Kor Gem", ["tasks"] = { ["Corrupted Kor Gem"] = "осквернений самоцвіт Кора", ["Corrupted Kor Gem (Provided)"] = "осквернений самоцвіт Кора (видано)" } },
    [1445] = { [1] = "Храм Атал'Гаккар", [2] = "То він говорив про пророцтво Джаммал'ана?\n\nДуховний лідер Атал'ай вірить, що коли Гаккар повернеться з Підсвіття до Азероту, бог дарує племені Атал'ай безсмертя.\n\nЯк на мене, безглуздий трюк, з метою наблизити судний день.\n\nАле ти {стать:казав:казала}, що вигнанець говорив про зачаровані фетиші? Це мене дуже хвилює. Якщо серед них справді є ключ до ритуалу Атал'ай, який спричинив весь цей безлад, ми маємо зрозуміти його справжню силу.\n\nЙди в храм і роздобудь фетиші!", [3] = "Зберіть 20 фетишів Гаккара та віднесіть їх Фел'Зерулу в Камінард.", [4] = "Якщо фетиші Атал'ай можуть викликати Гаккара і виконати пророцтво Джаммал'ана, ми маємо роздобути їх. Орда має зрозуміти їхню силу!", [5] = "{стать:Сміливий:Смілива} {клас:к}, ти {стать:довів:довела}, що ти є {стать:великим героєм:великою героїнею} Орди.\n\nТепер ми розберемося з цими фетишами Гаккара!", ["en"] = "The Temple of Atal'Hakkar", ["tasks"] = { ["Fetish of Hakkar"] = "фетиш Гаккара", ["Fetish of Hakkar (Provided)"] = "фетиш Гаккара (видано)" } },
    [1446] = { [1] = "Джаммал'ан-Пророк", [2] = "Мої товариші з племені Зів'ялої Кори не дуже люблять чужинців у своєму домі.\n\nА я? У мене більше немає дому. Мій народ з великого племені Атал'ай, з болота Скорбот, вигнав мене.\n\nУ нашого духовного лідера Джаммал'ана, є те, що він сам називає пророцтвом. Він вірить, що якщо викликати бога Гаккара, то він принесе безсмертя.\n\nАле я порекомендував йому бути обережним. Що, як пророцтво було звичайною маніпуляцією?\n\nЯ хочу помститися за своє вигнання. Принеси мені голову Джаммал'ана. Може, тоді мій народ звільниться.", [3] = "Принесіть вигнанцю Атал'ай з Внутрішніх земель голову Джаммал'ана.", [4] = "Як тільки Джаммал'ана приберуть, у мене з'явиться можливість повернутися до свого народу.\n\nЗ таким духовним лідером, як Джаммал'ан, Атал'ай приречені.", [5] = "Безоглядна довіра Джаммал'ана до фальшивих видінь привела мій народ до вічних страждань.\n\nДякую тобі, {клас:к}, що {стать:помстився:помстилася} за мене. Я оплакую свій народ. В мене більше немає дому, в який я міг би повернутися.", ["en"] = "Jammal'an the Prophet", ["tasks"] = { ["Head of Jammal'an"] = "голова Джаммал'ана", ["Head of Jammal'an (Provided)"] = "голова Джаммал'ана (видано)" } },
    [1448] = { [1] = "У пошуках храму", [2] = "Був час, коли я був молодий і сповнений сил, як ти, {клас:к}.\n\nАле тепер я старий і не можу досліджувати світ, як колись. Ах, чого я тільки не бачив!\n\nАле була одна загадка, яка вислизала від мене. Моїм останнім завданням в Лізі дослідників був пошук храму Атал'Гаккара. Подейкували, що він знаходиться в болоті Скорбот.\n\nЧерез мою слабкість та старість я облетів ці землі на грифоні, але так нічого і не знайшов.\n\nДопоможеш старому дворфу? Можливо, пішки тобі пощастить більше.", [3] = "Броган Бочкопуз зі Штормовію просить вас знайти храм Атал'Гаккара.", [4] = "Я обійшов весь світ: від джунглів Азероту до засніжених вершин Каз-Модану.\n\nНіколи раніше я не просив про допомогу в моїх пригодах. Але мої старі суглоби ниють і не дають мені подорожувати.\n\nНіщо не принесе мені більшого задоволення, ніж завершення мого останнього завдання Ліги дослідників.\n\nЯкщо ти допоможеш мені знайти храм Атал'Гаккара, {клас:к}, я буду дуже вдячний.\n\nДосліди болото Скорбот та розкажи про свої знахідки!", [5] = "Храм Атал'Гаккара затоплений в ставі Сліз? І оточений зеленими драконами?\n\nЦе дивовижне відкриття, {клас:к}. Але, вочевидь, в цьому храмі сталось щось жахливе.", ["en"] = "In Search of The Temple", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Search for the Temple of Atal'Hakkar"] = "Пошук храму Атал'Хаккара" } },
    [1449] = { [1] = "У Внутрішні землі", [2] = "Як я вже казав, я намагався самотушки знайти храм з повтря. Що ж, я був не зовсім сам.\n\nЯ взяв навченого грифона у знаменитому пташнику на Орлиному піку у Внутрішніх землях. Грифоном керував один з їхніх найкращих пілотів. Але він випав з сідла та впав у болото...\n\nМоя стара дурна голова вже забула, як його звали. Та господар вольєра певно має пам'ятати.\n\nВідправляйся туди та поговори з Фальстадом Диким Молотом.\n\nМи маємо дізнатись, що сталось з тим пілотом.", [3] = "Поговоріть з верховним таном Фальстадом Диким Молотом у Внутрішніх землях.", [5] = "Чого тобі, {стать:приятелю:приятелько}? Ти не бачиш, що у мене тут і без тебе вдосталь проблем? Немає в мене часу на балачки з тобою.\n\nТролі лізуть з усіх напрямків! Тож давай скоріше.", ["en"] = "To The Hinterlands" },
    [145] = { [1] = "Посланець до Темнодолу", [2] = "Мені знову потрібна твоя допомога. Я написав листа лорду Чорнобривому з проханням надіслати своїх навчених бійців Нічної варти на захист Приозер'я. Вкрай важливо, щоб це повідомлення дійшло до нього якнайшвидше. Але будь {стать:обережний:обережна}. Чорнобривий — міський голова Темнодолу, що знаходиться у самому серці Смерколісся. Не сходь з дороги.", [3] = "Війт Соломон просить вас віднести листа лорду Чорнобривому в Темноділ.", [4] = "Здається, ти {стать:прибув:прибула} здалеку, {клас:к}. Що привело тебе до Темнодолу?", [5] = "Дякую за твою довгу подорож сюди. Це справді важлива інформація.", ["en"] = "Messenger to Darkshire", ["tasks"] = { ["Solomon's Plea to Darkshire"] = "прохання Соломона до Темнодолу", ["Solomon's Plea to Darkshire (Provided)"] = "прохання Соломона до Темнодолу (видано)" } },
    [1450] = { [1] = "Приборкувач грифонів Кігтеруб", [2] = "Так от, ти — просто {стать:підручний:підручна} якогось старця з Ліги дослідників, чи не так?\n\nНу, слухай, {клас:к}. Я не знаю, з ким твій старий приятель літав по Азероту. Чи я здаюсь тобі приборкувачем грифонів Кігтерубом? Здаюсь?\n\nЯкщо ти так {стать:зацікавився:зацікавилася} польотами, то чому б тобі не поговорити з приборкувачем грифонів? Якщо я побачу тебе без діла, то завалю справжньою роботою.\n\nТож швидше рушай в дорогу.", [3] = "Поговоріть з приборкувачем грифонів Кігтерубом у вольєрі Орлиного Піку.", [5] = "О, так звичайно, я пам'ятаю, що я відправив одного зі своїх грифонів, щоб допомогти Брогану Бочкопузу.\n\nЯ завжди мав слабкість до Ліги дослідників. Насправді мій батько брав участь у експедиції, яка відкрила Ульдаман.\n\nЯ відправив свого найкращого приборкувача грифонів на той час разом з Броганом. Це був хлопець, на ім'я Рапсодій Жартогін.\n\nАх, яким вершником він був!! Ну, доки...", ["en"] = "Gryphon Master Talonaxe" },
    [1451] = { [1] = "Рапсодій Жартогін", [2] = "Рапсодій страшенно полюбляв випивку. Зрозумій мене правильно — всі ми, дворфи, любимо добрий ель в правильний час.\n\nАле Жартогін полюбив напій, як грифон — повітря. І це стало для нього прокляттям. Ніхто не літав так, як Рапсодій.\n\nПерші проблеми виникли, коли він повернувся після завдання з твоїм товаришем Броганом. Все швидко почало йти шкереберть. Довелося відпустити його.\n\nОстаннє, що я чув — він відкрив пивнушку на схід звідси...", [3] = "Знайдіть Рапсодія Жартогона у Внутрішніх землях.", [5] = "Гик!\n\nЯ дивлюся прямо на тебе, але ти все час підскакуєш вгору та вниз. Мені стає погано від цього. Хо-хо!\n\nГик!\n\nВау! Ти {стать:відчув:відчула} це? Земля тремтить, {стать:друже:подруго}. Мені потрібно випити.\n\nГик!", ["en"] = "Rhapsody Shindigger" },
    [1457] = { [1] = "Пожитки Карнітола", [2] = "Віднеси речі Карнітола до Ройттена в Залізогарт і він добре тобі заплатить.\n\nХа-ха, але обережно — якщо твоя робота йому сподобається, він візьме тебе до нас на повний робочий день.\n\nЗнову ж таки, чудова робота, {ім'я}.\n\nБудь {стать:обережним:обережною} на зворотному шляху і не затримуйся — Карнітол не любить чекати... зате він добре платить!", [3] = "Віднесіть торбу Карнітола Ройттену Камнемолоту в Залізогарт.", [4] = "Бізнес процвітає, {ім'я}, і в мене немає часу на балачки. Якщо в тебе є справи до корпорації \"Віднова\", то я готовий тебе вислухати. Якщо ж ні, то краще пудри мізки комусь з моїх підлеглих — вони достатньо тямлять в справах, щоб відповісти на твої запитання.", [5] = "А, так, було діло з Карнітолом в Спустошищі. Чудово!\n\nОтже, скриню знищено, але всі речі на місці, правильно? Що ж, добре. Одна з переваг у моїй справі полягає в тому, що якщо хтось незадоволений, я можу послати його до біса! Вони платять за те, що ми знайдемо їхні речі... а не за те, що вони будуть у гарному стані.\n\nЧудова робота, {ім'я}. Давай-но подивимося, скільки тобі можна заплатити.", ["en"] = "The Karnitol Shipwreck", ["tasks"] = { ["Karnitol's Satchel"] = "торба Карнітола", ["Karnitol's Satchel (Provided)"] = "торба Карнітола (видано)" } },
    [1458] = { [1] = "Реагенти для корпорації \"Віднова\"", [2] = "Одне з моїх завдань тут — збір реактивів для Лівшиці, гнома-мага з Хараноса. Ройттен, мабуть, думає, що це легко, якщо ми вже тут. Йому байдуже, що ми не підготовлені до цього.\n\nПерші кілька реактивів з його списку буде досить легко дістати, а той, хто мені допоможе з цим, отримає кілька монет.\n\nМені потрібні роги та кігті скаженолютих сатирів — вони живуть неподалік, на сході. Принеси їх мені, а потім ми займемося рештою списку.", [3] = "Принесіть 10 кігтів скаженолютих сатирів і 10 рогів скаженолютих сатирів Крелдіґу Унґору в Спустошище.", [4] = "Огидні створіння, ці сатири. Кажуть, що вони якось пов'язані з нічними ельфами, але я не надто в це вірю.\n\nДумаю, ці чутки пішли через одного ельфа, який втягнув їх у війну кілька років тому. З того часу весь світ змінився. Став набагато небезпечнішим і страшнішим.", [5] = "Добре, добре, {ім'я}. Не впевнений щодо їхньої якості, але якщо Лівшиця хотів якісь особливі реактиви, треба було говорити це до того, як відправляти нас сюди.\n\nНу що, поглянемо що там далі в списку?", ["en"] = "Reagents for Reclaimers Inc.", ["tasks"] = { ["Hatefury Claw"] = "кіготь скаженолютого сатира", ["Hatefury Claw (Provided)"] = "кіготь скаженолютого сатира (видано)", ["Hatefury Horn"] = "ріг скаженолютого сатира", ["Hatefury Horn (Provided)"] = "ріг скаженолютого сатира (видано)" } },
    [1459] = { [1] = "Реагенти для корпорації \"Віднова\"", [2] = "Що там далі в списку Лівшиці... подивимось... хм. А, ось.\n\nДосить легко, тут навіть є чіткі вказівки. Йому потрібна отрута скорпаші та шкура кодо. Дрібним шрифтом написано, що і те, і інше — від конкретних істот: отруту потрібно добути з будь-яких скорпаші, а шкура — саме зі старих кодо, але ні в якому разі не від вмираючих чи древніх.\n\nЦі маги, я тобі кажу... їм постійно потрібні якісь дивні речі.", [3] = "Принесіть 7 флаконів отрути скорпаші та 3 шкури старого кодо Крелдіґу Унґору в Спустошище.", [4] = "Вибач, що не сказав тобі, де знайти кодо чи скорпаші. Я погано знаю це місце та в мене не було часу, щоб вивчити його.", [5] = "Твоя допомога просто неоціненна, {ім'я}. Завдяки тобі я проведу в Спустошищі удвічі менше часу. Ще трохи, і я зможу повернутись в Залізогарт та добряче відпочити...\n\nКоли ми розберемося з цим списком і я повернуся додому, знайди мене, я обов'язково пригощу тебе елем.\n\nА поки що займемося рештою реагентів.", ["en"] = "Reagents for Reclaimers Inc.", ["tasks"] = { ["Aged Kodo Hide"] = "шкура старого кодо", ["Aged Kodo Hide (Provided)"] = "шкура старого кодо (видано)", ["Scorpashi Venom"] = "отрута скорпаші", ["Scorpashi Venom (Provided)"] = "отрута скорпаші (видано)" } },
    [1460] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [1461] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [1462] = { [1] = "Сапта землі", [3] = "Поговоріть з провидицею Вороняче Перо, щоб отримати ще одну сапту землі.", [5] = "Візьми її та пам'ятай — вона священна.", ["en"] = "Earth Sapta" },
    [1463] = { [1] = "Сапта землі", [3] = "Поговоріть з Канагою Землезовом, щоб отримати ще одну сапту землі.", [5] = "Я даю тобі її зі спокійною душею. Одного разу ти вже {стать:проявив:проявила} себе, але надалі тобі варто бути {стать:обережнішим:обережнішою}.", ["en"] = "Earth Sapta" },
    [1464] = { [1] = "Сапта вогню", [3] = "Поговоріть з Телфом Джууламом, щоб отримати ще одну сапту вогню.", [5] = "Нехай вогонь палає у твоєму серці, {ім'я}.\n\nСтихії чекають на тебе.", ["en"] = "Fire Sapta" },
    [1465] = { [1] = "Пошукова операція Валарріеля", [2] = "Під час огляду воза, ви знаходите не лише кулон, але й сліди, що ведуть на південь. Вдалині ви бачите дим, що здіймається з великого форту. Це дим від розпаленого багаття, а не від пожежі, і ваші інстинкти підказують, що Малемів повели в тому напрямку, якщо вони ще живі.\n\nВи вважаєте, що Валарріелю з оплоту Найджела потрібно неодмінно показати знайдений кулон та розказати про побачене на півдні.", [3] = "Поверніть кулон Малемів Валарріелю Демоновбивці в Спустошище.", [5] = "Я розлючений! Це фіаско!\n\nЇх обох попереджали про те, як небезпечно сюди приїжджати. А тепер вони обоє зникли... або ще гірше.\n\nТи {стать:казав:казала}, що {стать:бачив:бачила} сліди, що ведуть до форту неподалік? Що ж, можливо, у нас ще є надія.\n\nМісцеві кажуть, що ця фортеця кишить членами Палаючого Леза — орками, які присвятили своє життя службі демонам. Можливо, не всі члени Орди підтримують такі вірування, але це зараз не так важливо — ці орки злі й відразу вб'ють тебе, якщо спіймають.", ["en"] = "Vahlarriel's Search", ["tasks"] = { ["Malem Pendant"] = "кулон Малемів", ["Malem Pendant (Provided)"] = "кулон Малемів (видано)" } },
    [1466] = { [1] = "Реагенти для корпорації \"Віднова\"", [2] = "Це останнє в списку, не буду тобі брехати, задання не з приємних. Скоріше за все, воно займе в тебе трохи більше часу, ніж попередні.\n\nГаразд, досить застережень, до роботи. Лівшиця каже, що йому потрібно: десять мізків маноїдів, мисливців на магів або лей-мисливців. Десять крил підсвітної діви, сестри або чаклунки, і... десять флаконів крові стража приречення від капітанів чи лордів.\n\nДосить легко, чи не так? Якщо ти не захочеш виконувати це, я тебе зрозумію.", [3] = "Принесіть 10 мізків скверногончих, 10 підсвітних крил та 10 флаконів крові стража приречення Крелдіґу Унґору в Спустошище.", [4] = "Я навіть уявити собі не міг, що всі ці демонічні істоти живуть в Спустошищі. Я чув лише про кентаврів, що населили ці землі після того, як нічні ельфи покинули їх багато років тому.\n\nЦікаво, як ці створіння опинилися тут і навіщо?", [5] = "Чесно кажучи, ніколи б не подумав, що тобі це вдасться. Ти {стать:дивовижний:дивовижна}, {ім'я}. Боротися з демонами заради експериментів схибленого мага і повернутися {стать:цілим і неушкодженим:цілою і неушкодженою}. Чудова робота!\n\nЯ особисто розповім про тебе Ройттену коли повернуся в Залізогарт.", ["en"] = "Reagents for Reclaimers Inc.", ["tasks"] = { ["Doomwarder Blood"] = "кров стража приречення", ["Doomwarder Blood (Provided)"] = "кров стража приречення (видано)", ["Felhound Brain"] = "мозок скверногончої", ["Felhound Brain (Provided)"] = "мозок скверногончої (видано)", ["Nether Wing"] = "підсвітне крило", ["Nether Wing (Provided)"] = "підсвітне крило (видано)" } },
    [1467] = { [1] = "Реагенти для корпорації \"Віднова\"", [2] = "Щоб отримати оплату, тобі доведеться повернутися в Залізогарт і поговорити з Ройттеном. Думаю, він буде радий позбутися від пакунка Лівшиці. Просто віддай йому це і ти отримаєш свою винагороду.\n\nІ не хвилюйся, я замовлю за тебе слівце, коли повернуся. Мені теж не дуже хочеться сидіти в Спустошищі.", [3] = "Віднесіть пакунок Лівшиці Ройттену Камнемолоту в Залізогарт.", [4] = "Радий тебе бачити, {ім'я}. Бізнес процвітає, ковадла дзвенять по усьому Залізогарту, міхи роздмухують вогонь, а моя дружина пече для мене пиріг. Чи може життя бути кращим?", [5] = "О, пакунок для Лівшиці зі Спустошища. Чудово. Я ціную твою роботу і своєчасність виконання, {клас:к}. Радий, що ти {стать:взявся:взялася} за це завдання.\n\nОсь твоя оплата. Нехай усі знають, що корпорація \"Віднова\" завжди гідно платить за важку роботу.", ["en"] = "Reagents for Reclaimers Inc.", ["tasks"] = { ["Leftwitch's Package"] = "пакунок Лівшиці", ["Leftwitch's Package (Provided)"] = "пакунок Лівшиці (видано)" } },
    [1470] = { [1] = "Відкриваючи завісу", [2] = "Вітаю, дитино. Я бачу, що ти ще {стать:молодий:молода} у вміннях {стать:чорнокнижника:чорнокнижниці}, сила все ще ухиляється від тебе. Я відчуваю твоє бажання вчитися.\n\nІ ти будеш вчитися.\n\nНемає сили в незнанні. Знання — наша найбільша сила. Завдяки цій силі ми можемо контролювати магію хаосу та істот безодні, підкоряючи їх нашій волі.\n\nЯ покажу тобі, як підкорити прислужника своїй волі, але спершу ти маєш принести мені три черепи брязкокісткових скелетів, що ходять поблизу покинутої кузні.", [3] = "Принесіть Венії Мартанд 3 черепи брязкокісткового скелета.", [4] = "Твоя сила поки невелика, хоча я підозрюю, що ти вже відчуваєш можливості.\n\nНавіть мертвий може відчути себе живим, коли ця сила проймає нас.", [5] = "Хоча ти ще {стать:недосвідчений:недосвідчена} та {стать:молодий:молода} у своєму знанні, ти {стать:довів:довела}, що маєш вдосталь здібностей, щоб опанувати заклинання виклику біса. Нехай тебе не вводять в оману його розміри. Хоча він не має фізичної сили, він володіє здібностями та хитрістю, які дуже тобі стануть у пригоді.\n\nСлухай мене уважно, {ім'я}, бо повторювати я не буду, і я поділюсь з тобою цим знанням.", ["en"] = "Piercing the Veil", ["tasks"] = { ["Rattlecage Skull"] = "череп брязкокісткового скелета", ["Rattlecage Skull (Provided)"] = "череп брязкокісткового скелета (видано)" } },
    [1471] = { [1] = "Зв'язування", [2] = "Ти, безперечно, {стать:бачив:бачила} коло виклику під нами? Тільки там ти зможеш викликати пустотника.\n\nВикористовуючи ці руни, ти зможеш викликати його, а потім ти {стать:повинен:повинна} підкорити його силою зброї та магії.\n\nКоли ти підкориш його, він буде зобов'язаний тобі. Тоді повернись до мене, і я навчу тебе заклинанню виклику, щоб він міг служити тобі коли ти забажаєш.", [3] = "За допомогою руни виклику викличте і підкоріть пустотника, а потім поверніть руну виклику Карендіну Галґару у квартал Магії Підмістя.", [4] = "Сподіваюся, ти досягнеш успіху, {ім'я}. Однак, якщо ти не виправдаєш моїх очікувань, це буде найменшою з твоїх турбот.", [5] = "Ти гарно {стать:впорався:впоралася}, {ім'я}. Тепер я навчу тебе виклику пустотника.\n\nСила, яка тобі відкрилася, тепер належить тобі. Використовуй її з розумом.", ["en"] = "The Binding", ["tasks"] = { ["Summoned Voidwalker"] = "викликаний пустотник", ["Summoned Voidwalker slain"] = "викликаний пустотник: убито" } },
    [1472] = { [1] = "Пожирачка душ", [2] = "Сайаади — це пожирачі душ, що пригнічують волю і вводять у спокусу. Це створіння, сповнені зла і витонченої хитрості.\n\nУ історіях, що розповідають як праведні, так і нечестиві, цих демонів називають сукубами, якщо йдеться про жіночу форму, та інкубами, якщо про чоловічу.\n\nПросто так в наш світ їх не викличеш, тому потрібно використовувати особливу приманку. Сайаад не зможе встояти перед серцями чистих та люблячих людей. Він з'явиться в нашому світі й тоді ти зможеш перемогти та підкорити його.\n\nЗвернись до мого помічника Ґодріка Фарсана в храмі. Він допоможе тобі знайти приманку.", [3] = "Поговоріть з Ґодріком Фарсаном у храмі Проклятих.", [5] = "Тебе прислав Карендін? Тоді ти {ім'я}.\n\nНе думай про мене погано через те, що я втратив зір. Тепер я бачу речі, які раніше лежали поза моїм полем зору, з ясністю, якої ніколи не знав раніше. Те, що колись вважав прокляттям, тепер є благословенням для мене.", ["en"] = "Devourer of Souls" },
    [1474] = { [1] = "Зв'язування", [2] = "Використовуючи ці серця, наклади заклинання на коло виклику, щоб відкрити прохід, через який з'явиться сукуб. Твоя сила тепер велика, і тобі знадобиться вся вона, щоб перемогти сукуба.\n\nОбережно з її спокусливими чарами, {ім'я}, багато сильних розумів було поневолено її волі. Коли ти переможеш сукуба, вона повернеться до безодні і я навчу тебе магії, що дозволить тобі викликати її за твоїм бажанням.", [3] = "За допомогою чистих сердець викличте і підкоріть сукуба, а потім поверніть чисті серця Карендіну Галґару у квартал Магії Підмістя.", [4] = "З-поміж всіх жителів безодні, сукуб — одна з найнебезпечніших, оскільки слабкі найлегше піддаються її впливу.\n\nЗапам'ятай це раз і назавжди.", [5] = "Ти знову чудово {стать:впорався:впоралася}, {ім'я}. Пройшло чимало часу з того моменту, як я бачив {стать:такого молодого:таку молоду} {клас:з} з таким потенціалом. Будь {стать:впевнений:впевнена}, що я буду продовжувати спостерігати за твоїм прогресом, готувати та допомагати у твоїх майбутніх випробуваннях.\n\nА тепер дозволь мені показати заклинання для виклику твого щойно підкореного сукуба.", ["en"] = "The Binding", ["tasks"] = { ["Summoned Succubus"] = "викликаний сукуб", ["Summoned Succubus slain"] = "викликаний сукуб: убито" } },
    [1475] = { [1] = "В храм Атал'Гаккар", [2] = "За легендою, храм Атал'Гаккар — це святилище древнього бога Гаккара, Здирача Душ. Храм оберігає злісне плем'я тролів, на ім'я Атал'ай, і кажуть, що він був непроникним.\n\nТепер, коли храм затонув у ставі Сліз, витягти артефакти звідти стало ще складніше. Але це саме те, про що я тебе прошу, {ім'я}.\n\nДопоможи мені зібрати вцілілі скрижалі Атал'ай. Принеси їх мені і я повернуся до Ліги дослідників героєм. Ми розділимо славу між собою.", [3] = "Зберіть 10 скрижалей Атал'ай для Брогана Бочкопуза зі Штормовію.", [4] = "В моїй кар'єрі наступили темні часи і я прошу тебе, {ім'я}, про допомогу з моїм останнім завданням для Ліги дослідників. Якби мої старі кістки дали мені пройти через болото Скорбот та дістатись в Затонулий храм, я б бився пліч-о-пліч з тобою.\n\nЯ занадто гордий, щоб просити тебе про допомогу у зборі скрижалей Атал'ай. Але старість змушує це робити.\n\nБудь ласка, допоможи мені, {ім'я}. Я хочу піти з Ліги дослідників, завершивши останнє завдання.", [5] = "Скрижалі Атал'ай! Дякую тобі, {ім'я}!\n\nЩойно я передам їх Лізі дослідників, наші імена увійдуть в історію. Ти {стать:допоміг:допомогла} старому дворфу виконати його останній обов'язок. За це я безмежно вдячний тобі.", ["en"] = "Into The Temple of Atal'Hakkar", ["tasks"] = { ["Atal'ai Tablet"] = "скрижаль Атал'ай", ["Atal'ai Tablet (Provided)"] = "скрижаль Атал'ай (видано)" } },
    [1477] = { [1] = "Життєво необхідні поставки", [2] = "Наші маги проводять важливі для розуміння Темних Порталів дослідження у фортеці Підсвітньої Варти, що в Спустошених землях. Їм постійно потрібні припаси, але наші шляхи постачання до них ненадійні.\n\nТи маєш допомогти з постачанням припасів до Підсвітньої Варти. Поговори з начальником варти Соріґалом в Темнодолі та виконай його доручення. Ти відправишся у небезпечні землі, {ім'я}, тож приготуйся.", [3] = "Поговоріть з начальником варти Соріґалом.", [5] = "Тебе відправив Андромат? Дуже добре. Я маю для тебе важливе завдання...", ["en"] = "Vital Supplies" },
    [1478] = { [1] = "Виклик Галґара", [2] = "А, {ім'я}! Я щойно отримав повідомлення від Карендіна Галґара, він бажає бачити тебе для подальшого навчання.\n\nТи можеш пишатися собою, {ім'я}. Не кожен день Майстер Галґар вирішує особисто навчати {стать:молодого:молоду} {клас:з}.\n\nТи знайдеш його у кварталі Магії в Підмісті, неподалік від храму Проклятих.", [3] = "Поговоріть з Карендіном Галґаром у Підмісті.", [5] = "Чудово, я бачу, Аґерону вдалось знайти тебе, {ім'я}. Давай не будемо витрачати час на балачки та люб'язності, а зосередимося на твоєму навчанні. Тобі ще багато чого треба навчитися.", ["en"] = "Halgar's Summons" },
    [1479] = { [1] = "Гілка Вічності", [2] = "Я чув розповіді про те, що у нічних ельфів є банк у дереві, яке схоже на ведмедя! Це так круто! Нічні ельфи цікаві, вони люблять природу і все таке, але ведмеді — це просто неймовірно круто!\n\nЯ хочу побачити ведмеде-дерево в Дарнасі. Будь ласка. Є човен, який доставить нас туди, і це не займе багато часу. Будь ласка, будь ласка, будь ласка!", [3] = "Відведіть сироту в банк Дарнасу. Сам банк знаходиться у дереві, відомому як Гілка Вічності.", [4] = "Ми вже прийшли?", [5] = "Вау, це було ще крутіше, ніж я уявляв — Гілка Вічності! Я не думав, що вона буде такою великою, але вона була! Ти {стать:бачив:бачила} птаха на її вершині?! Цікаво, як вони змогли зробити гілки такими!\n\nДякую, що {стать:взяв:взяла} мене до Дарнасу, {ім'я}. Ти {стать:неймовірний:неймовірна}!", ["en"] = "The Bough of the Eternals", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Go to the bank in Darnassus, otherwise known as the Bough of the Eternals."] = "Сходіть до банку в Дарнасі, також відомого як Гілка Вічних." } },
    [1483] = { [1] = "Зіз Фіззікс", [2] = "ТзНБ \"Авантюра\" переманила багато кращих гоблінських умів, та часом у нас з'являється можливість дещо повернути.\n\nНещодавно підрозділ ТзНБ \"Авантюра\" у Каміннопазуристих горах найняв Ґерензо Свистоключа — гнома! Інший їхній інженер, Зіз Фіззікс, був настільки вражений цим, що благав мене знайти йому нову роботу у Спілці штукарів. Я дав йому кілька завдань, але йому може знадобитися допомога.\n\nМоже, заглянеш до нього? Він живе біля західного краю Вітрокосих скель.", [3] = "Поговоріть з Зізом Фіззіксом на Вітрокосих скелях.", [5] = "Я думав, що начальство ТзНБ \"Авантюра\" — справжні тирани, але потім я зустрів Гуркоклапана, і він гірший за них усіх!\n\nХа! Хоча це краще, ніж сидіти без роботи... Чи ще гірше — працювати з цим Ґерензо. Якщо ти тут, щоб допомогти, для тебе знайдеться справа.", ["en"] = "Ziz Fizziks" },
    [1485] = { [1] = "Підлі фамільяри", [2] = "Ті чорнокнижники, які були перед нами, заробили собі погану репутацію і заслужили недовіру Орди, і хоча нас терплять, нас не люблять.\n\nПроте це не згуртувало чорнокнижників, багато з них вирішили стати відлюдниками, займаючись магією самотужки. Я не намагатимусь повести тебе тим чи іншим шляхом, але допоможу тобі у твоєму становленні.\n\nПерш ніж я навчу тебе виклику, принеси мені шість голів паскудних фамільярів з печери на північному сході.", [3] = "Принесіть 6 голів паскудних фамільярів Рузану.", [4] = "Важливо, щоб ти {стать:міг:могла} контролювати істот, яких викликаєш за допомогою своєї магії. Тих, хто цікавиться ремеслом чорнокнижників, і так мало, тож я не дозволю тобі ризикувати життям перш ніж побачу, що ти до цього {стать:готовий:готова}.", [5] = "Протягом твого навчання, ти навчишся викликати найрізноманітніших істот. Усі вони по-своєму корисні, навіть якщо це не очевидно на перший погляд.\n\nНе дай обдурити себе маленьким розміром біса. Як ти, без сумніву, {стать:помітив:помітила}, це все ще небезпечний супротивником.", ["en"] = "Vile Familiars", ["tasks"] = { ["Vile Familiar Head"] = "голова паскудного фамільяра", ["Vile Familiar Head (Provided)"] = "голова паскудного фамільяра (видано)" } },
    [1486] = { [1] = "Спотворені шкури", [2] = "З того часу, як Наралекс глибоко занурився у свій кошмар, з глибин Степів до Плачучих печер вилізли дивні створіння.\n\nЦі спотворені істоти мають дивні, потойбічні властивості. І, хоча вони повні зла, на мою думку, з їхнього існування тут, у Калімдорі, ми можемо отримати деяку користь. Я думаю, що їх шкури можуть бути корисними у шкірництві.\n\nЯкщо це завдання тобі під силу — вирушай в печери під нами й здобудь кілька спотворених шкур.", [3] = "Налпак з Плачучих печер просить вас принести йому 20 спотворених шкур.", [4] = "Я зацікавлений в тому, щоб дослідити шкури зі спотворених істот, що заполонили ці печери. Чи вдалось тобі зібрати декілька, {клас:к}?", [5] = "Твої зусилля не залишиться непоміченим, {ім'я}.\n\nДякую тобі за самовідданість.", ["en"] = "Deviate Hides", ["tasks"] = { ["Deviate Hide"] = "спотворена шкура", ["Deviate Hide (Provided)"] = "спотворена шкура (видано)" } },
    [1487] = { [1] = "Викорінення спотворень", [2] = "Наралекс мав благородну мету.\n\nНаш великий лідер прагнув увійти в Смарагдовий Сон і допомогти перетворенню цих суворих земель назад у густий ліс, яким вони колись й були. Але щось пішло не так.\n\nМрія Наралекса перетворилася на кошмар і спаплюжені істоти почали заселяти печери.\n\nВ той час, як деякі послідовники Наралекса прагнуть пробудити нашого майстра, я турбуюсь про те, щоб позбути ці печери від злісних потвор.\n\nВирушай до печер, {ім'я}, і викорени спотворення.", [3] = "Ебру з Плачучих печер просить вас вбити 7 спотворених спустошників, 7 спотворених гадюк, 7 спотворених шаркунів і 7 спотворених жахокликів.", [4] = "{ім'я}, нам, послідовникам Наралекса, потрібна твоя допомога. Наша численність зменшується відколи наш майстер потрапив у пастку своїх викривлених кошмарів. У нас недостатньо сил, щоб впоратись з потворами, що заполонили ці печери.\n\nПрошу тебе, йди до печер і очисть їх від цих спотворених істот!", [5] = "Як послідовник Наралекса, я шаную твою хоробрість, {ім'я}.\n\nТвоя допомога в очищенні печер є першим кроком на нашому довгому шляху відновлення Степів.\n\nДякую! І хай тобі щастить.", ["en"] = "Deviate Eradication", ["tasks"] = { ["Deviate Dreadfang"] = "спотворений жахоклик", ["Deviate Dreadfang slain"] = "спотворений жахоклик: убито", ["Deviate Ravager"] = "спотворений спустошник", ["Deviate Ravager slain"] = "спотворений спустошник: убито", ["Deviate Shambler"] = "спотворений шаркун", ["Deviate Shambler slain"] = "спотворений шаркун: убито", ["Deviate Viper"] = "спотворена гадюка", ["Deviate Viper slain"] = "спотворена гадюка: убито" } },
    [1491] = { [1] = "Напої розумності", [2] = "Що ж, роги рапторів не підійшли. Та нічого — нікому ще не вдалось розбагатіти з першої спроби. Крім того, я придумав дещо краще!\n\nЄ одна субстанція, що називається плачучою сутністю. Її можна дістати з ектоплазматичних створінь в Плачучих печерах, що на заході. Вбий цих створінь і збери з них сутність.", [3] = "Принесіть 6 плачучих сутностей Мебоку Міцріксу в Брашпиль.", [4] = "Ну, де мої плачучі сутності?", [5] = "Чудово, в тебе вийшло! Швидше б спробувати їх. Вони зроблять мене багатим, я це точно знаю!\n\nДякую, {ім'я}. Ось тобі гроші. Як розбагатію — відправлю тобі ще, обіцяю!", ["en"] = "Smart Drinks", ["tasks"] = { ["Wailing Essence"] = "плачуча сутність", ["Wailing Essence (Provided)"] = "плачуча сутність (видано)" } },
    [1498] = { [1] = "Мистецтво захисту", [2] = "Одна з твоїх найважливіших задач, як {клас:р}... захист. Ми — щит Орди, що оберігає наших слабших побратимів. Якщо ти хочеш вступити до наших рядів — доведи свою стійкість.\n\nЙди до Громового кряжу, що в Дуротарі. Там водяться блискавкошкури та громоящіри. Доведи свою міць в бою проти них. Як вистоїш проти них — принеси мені їх припалену луску.\n\nВпораєшся — і я погоджусь навчати тебе.", [3] = "Принесіть 5 припалених лусок Узеку на Далекостежну заставу в Степах.", [4] = "{стать:Приніс:Принесла} луску, {ім'я:к}? Якщо не впораєшся з громоящірами, я не буду тебе навчати.", [5] = "А-а-а, бачу, ти {стать:поборов:поборола} громоящірів, а отже і {стать:довів:довела} свою стійкість. Тепер я покажу тобі, як міцність тіла та спритність рухів формують непробивний захист.\n\nДобре запам'ятай мої настанови, {ім'я:к}. І будь {стать:готовий:готова} до подальших вказівок.", ["en"] = "Path of Defense", ["tasks"] = { ["Singed Scale"] = "припалена луска", ["Singed Scale (Provided)"] = "припалена луска (видано)" } },
    [1499] = { [1] = "Паскудні фамільяри", [2] = "Зурііта часто посилає таких новачків, як ти, щоб допомогти розібратись зі створіннями у печері, біля якої ти {стать:боровся:боролася} з паскудними фамільярами.\n\nДумаю, тобі не завадить набратися досвіду, допомагаючи їй. Не забудь сказати їй, що ти {стать:вирішив:вирішила} проблему з бісами — вона, ймовірно, нагородить тебе за це.", [3] = "Поговоріть з Зуріітою Далековзірною.", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}.\n\nХоча паскудні фамільяри були лише ручними звірятками темних сил Палаючого Леза, однак твій успіх віщує про твої великі подвиги в майбутньому.", ["en"] = "Vile Familiars" },
    [1500] = { [1] = "Пробудження Наралекса", ["en"] = "Waking Naralex" },
    [1502] = { [1] = "Тун'ґрім Вогнегляд", [2] = "Зброя воїна має бути найкращою. Якщо хто і вміє робити високоякісну зброю, так це Тун'ґрім Вогнегляд. Він - самітник, що живе на пагорбах, що на сході від Перехрестя.\n\nЯкщо тобі потрібна добра зброя - йди до Тун'ґріма. Щоб дістатись до нього, тобі слід відправитись на захід до Перехрестя, а потім йти на схід, прямісінько на пагорб. Він живе на вершині.", [3] = "Поговоріть з Тун'ґрімом Вогнеглядом в Степах.", [5] = "Мої очі давно висохли від жару кузні, та дещо я ще бачу. Бачу, що тобі щось треба від мене.\n\nІ раз ти {стать:знайшов:знайшла} дорогу до мене, то я здогадуюсь, чого саме ти хочеш.", ["en"] = "Thun'grim Firegaze" },
    [1503] = { [1] = "Кована сталь", [2] = "Буде тобі зброя, {ім'я}. Та спочатку ти маєш допомогти мені. Кілька днів тому на мене напало плем'я Бритвогривих з північного заходу. Вони побоялися битись зі мною, та знаючи, що я погано бачу - відволікли мене своїм фирканням та поцупили дещо в мене! Боягузи!\n\nВони забрали залізну скриню, в якій було кілька брусків кованої сталі. Якщо повернеш їх мені - я дам тобі зброю.\n\nПошукай залізну скриню в таборах свинобразів і повертайся зі сталлю.", [3] = "Принесіть бруски кованої сталі Тун'ґріму Вогнегляду в Степи.", [4] = "Ти {стать:приніс:принесла} мої бруски сталі.", [5] = "Ти {стать:знайшов:знайшла} їх! І всі вони на місці, що й не дивно. Звідки Бритвогривим знати, що робити з такою чудовою сталлю.\n\nДякую, {ім'я}. Ось твоя зброя. Хай вона добре послужить тобі.", ["en"] = "Forged Steel", ["tasks"] = { ["Forged Steel Bars"] = "бруски кованої сталі", ["Forged Steel Bars (Provided)"] = "бруски кованої сталі (видано)" } },
    [1504] = { [1] = "Зв'язування", [2] = "Поглянь на скрижаль Верґи, вона містить гліфи, які знадобляться тобі для виклику. Віднеси їх до кола в наметі Нііру Вогняного Леза на іншому боці печери. Там ти зможеш викликати пустотника.\n\nТи {стать:повинен:повинна} перемогти його будь-якими фізичними та магічними засобами. Коли це буде зроблено, повернись до мене з гліфами виклику, і я продемонструю, як ти можеш підкорити цю істоту своїй волі.", [3] = "За допомогою гліфів виклику викличте і підкоріть пустотника, а потім поверніть гліфи виклику Ґан'рулу Кривавому Оку в Орґріммар.", [4] = "Пустотник — дуже сильне створіння. Я пам'ятаю, коли я був на твоєму місці, {ім'я}. З роками мій власний пустотник став менше опиратися мені, хоча я підозрюю, що це лише тому, що він сподівається, що я втрачу пильність.\n\nПам'ятай це, {ім'я}.", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Я покажу тобі, як викликати пустотника, подібного до того, якого ти щойно {стать:переміг:перемогла}.\n\nТи {стать:повинен:повинна} знати, що ми багато очікуємо від тебе, і поки що ти виправдовуєш всі наші очікування.\n\nОднак хай успіх не затьмарює тобі голову, оскільки попереду тебе чекає ще багато викликів і завдань.", ["en"] = "The Binding", ["tasks"] = { ["Summoned Voidwalker"] = "викликаний пустотник", ["Summoned Voidwalker slain"] = "викликаний пустотник: убито" } },
    [1505] = { [1] = "Ветеран Узек", [2] = "Орда шанує своїх воїнів і їх сила не піддається жодним сумнівам. Але справжній воїн має бути хорошим учнем.\n\nЗнайди Узека. Він — ветеран багатьох битв і зараз навчає молодих воїнів мистецтву битви. Ти знайдеш його південніше Далекостежної застави, гарнізону орків на кордоні Степів та Дуротару.", [3] = "Поговоріть з Узеком на Далекостежній заставі.", [5] = "Вітаю, {стать:юначе:юначко}. Ти {стать:прийшов:пришла} навчатись, так?", ["en"] = "Veteran Uzzek" },
    [1506] = { [1] = "Виклик Ґан'рула", [2] = "Ти {стать:прийшов:прийшла}. {ім'я}, чи не так?\n\nСподіваюсь, у тебе немає запланованих справ, оскільки Ґан'рул хоче негайно побачитися з тобою. Ти знайдеш його разом зі старшими чорнокнижниками в Розколині Тіні.\n\nВиходячи з мого минулого досвіду спілкування з Ґан'рулом, його виклик може бути як дуже хорошою, так і дуже поганою річчю.", [3] = "Поговоріть з Ґан'рулом Кривавим Оком в Орґріммарі.", [5] = "Добре. Я боявся, що Офек не зможе знайти тебе.\n\nЧас розширити твої знання {клас:р}. Будь-які справи доведеться відкласти на потім.\n\nЯ сподіваюся, це не буде проблемою?", ["en"] = "Gan'rul's Summons" },
    [1507] = { [1] = "Пожирачка душ", [2] = "Настала пора дізнатися більше про магію виклику. Ти будеш вчитися викликати сайаада — створіння з неймовірними ментальними здібностями, що може підкорювати волю слабких духом створінь — але не бійся! Я впевнений, що ти впораєшся з цим викликом.\n\nСайаад може бути викликаний лише за умови, що його спокусить предмет, що відображає велику любов та відданість. Я залишаю пошуки такого предмета на тебе.\n\nХочеш пораду? Поговори з Казулом... Цьому древньому чорнокнижнику багато що відомо.", [3] = "Поговоріть з Казулом в Розколині Тіні.", [5] = "Гм... {ім'я}. Ти все ще новачок на своєму шляху, але я відчуваю в тобі потенціал для величі.\n\nТи {стать:народився:народилася} з даром, {ім'я}. Дивись, не згай його.", ["en"] = "Devourer of Souls" },
    [1508] = { [1] = "Сліпий Казул", [2] = "Якщо Ґан'рул відправив тебе до мене, то, мабуть, тому, що ти маєш викликати сайаада і тобі потрібна приманка. Гмм... Якщо ти довіряєш сліпому поводиреві, {ім'я}, то слухай. У скелях Орґріммару, західніше від вежі приборкувачів виверн, живе Занкая. Вона чекає на повернення свого партнера. Йди до неї.", [3] = "Поговоріть з Занкаєю в Орґріммарі.", [5] = "Ти {стать:прийшов:прийшла} з новиною про Доґрана? Він мав повернутися кілька днів тому, але я досі нічого не чула про нього...", ["en"] = "Blind Cazul" },
    [1509] = { [1] = "Звістка про Доґрана", [2] = "Мій чоловік, Доґран, недавно був призначений на службу в Перехресті. Це було підвищення, і він був дуже гордий.\n\nЗвичайно, я була сумною, але не показувала йому цього. І була занепокоєною. Степи — це більш небезпечне місце, ніж Орґріммар, і я боялась найгіршого.\n\nА зараз вже минув тиждень від того, як він мав повернутися, та я не отримала жодної вісточки від нього...\n\nМожливо, ти {стать:міг би:могла б} сходити до Перехрестя та дізнатися, чи є якісь новини? Він служив з Ґазроґом, який має бути там на службі.", [3] = "Поговоріть з Ґазроґом на Перехресті.", [5] = "Занкая? Це дружина Доґрана, вірно?\n\nТак, я чув про нього, але це не та новина, яку потрібно їй дізнатися...\n\nНі, він не помер. Але він поранений і у полоні свинобразів.", ["en"] = "News of Dogran" },
    [1510] = { [1] = "Звістка про Доґрана", [2] = "Він був призначений до табору Таурахо, де ми намагалися знищити свинобразів. Він повів за собою кількох бугаїв до одного з їхніх таборів, де його сильно поранили. Решта повернулась і спробувала його врятувати. Він мав поганий вигляд, його рани гноїлися, тому вони побоялися рухати його в такому стані.\n\nВони надіслали повідомлення сюди, щоб отримати лікувальне зілля у тролів у Малака'джина на підніжжі Каміннопазуристих гір. Ми відправили туди посланця, щоб забрати зілля, але він ще не повернувся.", [3] = "Поговоріть з Кен'зіґлом в Малака'джині.", [5] = "Ще один орк, еге ж? Сподіваюся, ти не {стать:прийшов:прийшла} за тим, іншим. Він не впорався. Про нього попіклувались гобліни.\n\nВін встиг сказати, що йому потрібен лікувальний настій, але нічого більше.", ["en"] = "News of Dogran" },
    [1511] = { [1] = "Настій Кен'зіґли", [2] = "Я передбачав, що хтось ще прийде забрати настій, тому все підготував.\n\nОсь, тримай, {ім'я}. Пам'ятай, ти {стать:повинен:повинна} дати йому лише половину! Цього буде достатньо, щоб він міг рухатися, не стікаючи кров'ю. Зачекай ніч, а потім дай йому другу половину.\n\nТак чи інакше, тобі потрібно передати це Лоґмару в табір Таурахо. За словами першого, хто до мене прийшов, він повинен знати, де знаходиться цей Доґран.", [3] = "Принесіть настій Кен'зіґли бугаю Лоґмару в табір Таурахо.", [4] = "Так, що це в тебе?", [5] = "Нарешті! Доґран вмирає там, чекаючи на цей настій.\n\nМи маємо негайно доставити це йому, але більшість моїх бугаїв знаходиться на завданні.", ["en"] = "Ken'zigla's Draught", ["tasks"] = { ["Ken'zigla's Draught"] = "настій Кен'зіґли", ["Ken'zigla's Draught (Provided)"] = "настій Кен'зіґли (видано)" } },
    [1512] = { [1] = "Дар кохання", [2] = "Занкая молода і прекрасна. Бути прикутою до каліки... Я не дозволю їй страждати від такої несправедливості.\n\nЗалиш мене, {ім'я}. І дякую тобі. Я краще закінчу своє життя в славній битві, а не буду тягнути це жалюгідне існування.\n\nІ, будь ласка, я прошу тебе не говорити їй про це... Я не хочу, щоб вона почувалася винною.", [3] = "Віднесіть вкритий брудом кулон Ґан'рулу Кривавому Оку в Орґріммар.", [4] = "Ти {стать:повернувся:повернулася}. {стать:Готовий:Готова} до битви з сукубом?", [5] = "Якщо ти кажеш, що цього достатньо, то я вірю тобі, {ім'я}. Але дозволь мені його почистити... Так, блискучий та чистий, він буде ще привабливішим для сукуба.", ["en"] = "Love's Gift", ["tasks"] = { ["Dirt-caked Pendant"] = "вкритий брудом кулон", ["Dirt-caked Pendant (Provided)"] = "вкритий брудом кулон (видано)" } },
    [1513] = { [1] = "Зв'язування", [2] = "Віднеси цей кулон до кола виклику в наметі Нііру, {ім'я}. Виклич потворного сукуба, а потім продемонструй свою майстерність. Я вірю у силу твоєї магії. Однак, будь {стать:обережним:обережною}, оскільки гордість та самовпевненість зламали багатьох перспективних чорнокнижників.\n\nКоли переможеш, поверни кулон мені, щоб я міг повідомити Занкаї цю новину.", [3] = "За допомогою кулона Доґрана викличте і підкоріть сукуба, а потім поверніть кулон Ґан'рулу Кривавому Оку в Орґріммар.", [4] = "Коли я дивлюся на сукуба, моє серце починає битися сильніше... Але водночас, я майже відчуваю, як моя душа відпливає, розходячись, як прилив і відлив.\n\nБудь {стать:обачним:обачною}.", [5] = "Успіх! Безумовно, меншого я й не очікував від {стать:свого найкращого учня:своєї найкращої учениці}.\n\nТи {стать:показав:показала} чого ти {стать:вартий:варта}, і я з радістю покажу тобі заклинання виклику твого підкореного сукуба. Йди, тобі ще багато чого треба навчитись, і коли наступного разу я побачу тебе, я очікуватиму, що ти по-справжньому підкориш сукуба.\n\nНе сумуй за Доґраном і Занкаєю, але пам'ятай про цю історію, вона стане добрим захистом від хитрощів темної сили, яку ти {стать:навчився:навчилася} викликати сьогодні.", ["en"] = "The Binding", ["tasks"] = { ["Summoned Succubus"] = "викликаний сукуб", ["Summoned Succubus slain"] = "викликаний сукуб: убито" } },
    [1514] = { [1] = "Осквернений вітроцвіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на вітроцвіт. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите дві порції кенарійського бальзаму зцілення рослин на вітроцвіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Windblossom", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [1515] = { [1] = "Полон Доґрана", [2] = "Ти {стать:зайшов:зайшла} вже далеко, тому я не зупинятиму тебе, якщо ти бажаєш довести це до кінця. Але я не можу надати тобі своїх воїнів, ти будеш {стать:сам:сама}.\n\nДоґрана утримують в таборі свинобразів на північ звідси. Шукай дві хати, в яких його утримують. Він буде під посиленою охороною — якщо його ще не вбили, або він не помер від ран.\n\nХай щастить.", [3] = "Принесіть настій Кен'зіґли до Доґрана в Степи.", [4] = "Уууф-фф...", [5] = "Яка гидота...\n\nЯ відчуваю силу, якої вистачить, щоб шкандибати звідси... Але моя нога, я втратив її назавжди. І руку теж.", ["en"] = "Dogran's Captivity", ["tasks"] = { ["Ken'zigla's Draught"] = "настій Кен'зіґли", ["Ken'zigla's Draught (Provided)"] = "настій Кен'зіґли (видано)" } },
    [1516] = { [1] = "Поклик землі", [2] = "Час прийшов, {стать:юний:юна} {клас:к}. Твої сили зросли, а твій дух непохитний, як земля. Те, що ти {стать:вирішив:вирішила} йти шляхом {клас:р}, саме по собі є доказом твоєї мудрості.\n\nСтихія землі направить твою долю та стане частиною тебе, якщо ти {стать:готовий:готова} до цього. Але тобі доведеться постати перед самою землею. Якщо ти {стать:готовий:готова}, то побачиш речі, що відомі лише шаманам.\n\nВідшукай на півночі скверноловів і забери в них два копита. Після цього повернись до мене і ми обговоримо твоє майбутнє.", [3] = "Принесіть 2 копита скверноловів Каназі Землезову у долину Випробувань.", [4] = "Терпіння — найбільша чеснота землі. Земля є свідком змін багатьох речей: гори стають пустелями, річки — ущелинами. Земля — найбільш вперта та мудра з усіх стихій і вона не виносить нетерплячість.\n\nЗемля кличе тебе зараз, бо наближається час битви. Коли ти повернешся до мене, то будеш ще на крок ближче до своєї цілісності.\n\nУсі інші будуть заздрити твоїй мудрості та ненавидіти тебе через своє невігластво.", [5] = "Чудово. Твій успіх доводить, що ти {стать:готовий:готова}.\n\nЗ усіх стихій земля являє собою основу для усіх речей. Це твоя сила, твоя витривалість та твоє терпіння. Земля захистить тебе, але тільки якщо ти ставитимешся до неї з належною повагою. Як і інші елементи, навіть земля може бути норовливою. Земля — основа життя, і, дотримуючись її законів, ти отримаєш більшу мудрість. Ніколи не забувай про таємниці, якими ділиться із тобою земля.\n\nТепер я зроблю для тебе сапту, і прийнявши її, ти зрозумієш свій шлях.", ["en"] = "Call of Earth", ["tasks"] = { ["Felstalker Hoof"] = "копито сквернолова", ["Felstalker Hoof (Provided)"] = "копито сквернолова (видано)" } },
    [1517] = { [1] = "Поклик землі", [2] = "Сапта — це напій, створений для того, щоб зв'язувати наш дух зі стихіями. З'єднаний з магією, цей напій дозволить тим, хто володіє сильною волею, побачити стихії так, як ніхто інший. Твій дух поєднається зі стихією, для якої було створено сапту. Рецепт цієї сапти відомий лише кільком шаманам.\n\nСапту можна пити лише у священних місцях і ніде більше. Пам'ятай про це.\n\nВідшукай камінь духа на південний захід звідси. Він розташований наприкінці Прихованої стежки. Випий там свою сапту та... ну, {стать:сам:сама} побачиш.", [3] = "Знайдіть камінь духа та випийте біля нього сапту землі.", [5] = "А... {ім'я}... земля рада, що ти тут.\n\nПоєднавши своє тіло із духом, ти підеш вперед, знаючи, що гори — твоя сила, рівнини — твоє терпіння, а сам світ — основа твоєї сутності.\n\nУсе, що потрібно тобі, щоб виконати цей обряд — це покірно постати перед землею. Але інші обряди вимагатимуть активніших дій. Вони можуть бути непередбачуваними та часто жорстокими, але така вже природа стихій. Тобі слід навчитися справлятися з вічною боротьбою протилежностей, що лежить в їхній основі.", ["en"] = "Call of Earth", ["tasks"] = { ["Earth Sapta"] = "сапта землі" } },
    [1518] = { [1] = "Поклик землі", [2] = "Візьми в мене цей грубий кварц та віднеси його Каназі Землезову як підтвердження нашої зустрічі. Він створить для тебе тотем, серцем якого буде цей камінчик. Яким би малим він не здавався, ти згодом зрозумієш що розмір не має значення, і що навіть найменші речі можуть пережити багато інших.\n\nНаберись терпіння, {ім'я}. Залишайся {стать:сильним:сильною}. І шукай мудрості. Це те, про що тебе просить земля. Зрештою, ти станеш одним цілим із землею — шануй її, і вона шануватиме тебе.", [3] = "Принесіть грубий кварц Каназі Землезову у долину Випробувань.", [4] = "Ось ти й {стать:став:стала} на перший з чотирьох шляхів, які назавжди вестимуть тебе до твоєї долі.\n\nЯкщо ти маєш камінь, що дала тобі земля, я дам тобі обіцяний тотем.\n\nЯкщо ж ні, то повертайся коли знайдеш свій шлях.", [5] = "Чудово!\n\nТотем, який я зроблю для тебе — це більше, ніж символ твого статусу {клас:р} — він потрібен не тільки для цього. Один із варіантів його застосування — це зосередження на ньому заклинань. Ці заклинання пов'язані із землею, і згодом, як ти набуватимеш все більшої й більшої мудрості, тобі стане доступно більше здібностей землі.\n\nТренери знатимуть, коли ти будеш {стать:готовий:готова} отримати нові знання.\n\nА поки що візьми цей тотем землі...", ["en"] = "Call of Earth", ["tasks"] = { ["Rough Quartz"] = "грубий кварц", ["Rough Quartz (Provided)"] = "грубий кварц (видано)" } },
    [1519] = { [1] = "Поклик землі", [2] = "Час настав, {стать:молодий:молода} {клас:к}. Твоє тіло кріпшає і дух твій міцніє подібно землі. Я бачу, ти вже {стать:набув:набула} мудрості.\n\nЗемля веде наш народ, і розмовляє з нами, як одного разу розмовлятиме з тобою. Але ти маєш пройти випробування. Якщо ти {стать:готовий:готова}, то зможеш побачити речі, про які знаємо лише ми.\n\nШукай щетиношкурих шаманів у їхній ущелині на сході, і забери в них мазь, яку вони використовують у своїх ритуалах. Повертайся до мене лише тоді, коли збереш достатньо мазі для приготування зілля.", [3] = "Принесіть 2 порції ритуальної мазі провидиці Вороняче Перо у табір Нараче.", [4] = "Земля терпляча і чекатиме, доки ти не будеш {стать:готовий:готова}, бо що вона знає, що з часом усе руйнується та відроджується. Це цикл життя. Гори стають пустелями. Річки стають каньйонами. Земля — найвпертіша і наймудріша з усіх стихій.\n\nПерш за все ти маєш навчитися терпіння та витривалості. Земля кличе тебе, бо відчуває твою готовність. Якщо тобі вдасться, вважай це за переродження. Більше ніколи ти не зможеш повернутись до невігластва.", [5] = "Добре, {ім'я}. Твоє повернення означає, що ти {стать:готовий:готова} до наступного кроку.\n\nСеред усіх елементів земля являє собою основу для усіх речей. Це твоя сила, твоя витривалість та твоє терпіння. Матінка Земля захистить тебе, але тільки якщо ти ставитимешся до неї з належною повагою. Земля є основою життя, і, дотримуючись її законів, ти отримаєш більшу мудрість. Ніколи не забувай про таємниці, якими ділиться із тобою земля.\n\nТепер я зроблю для тебе сапту, яка відкриє тобі новий шлях.", ["en"] = "Call of Earth", ["tasks"] = { ["Ritual Salve"] = "ритуальна мазь", ["Ritual Salve (Provided)"] = "ритуальна мазь (видано)" } },
    [152] = { [1] = "Зачистка узбережжя", [2] = "Ти, мабуть, {стать:помітив:помітила} усі ці уламки кораблів уздовж узбережжя. І справді, Велике море дуже підступне. Узбережжя Західного краю потрібно підтримувати вільним, щоб моряки, що припливають до наших берегів, були в безпеці. Однак, мурлоки залишаються великою проблемою.\n\nУбий 7 хвилеловів, 7 воїнів, 7 оракулів і 7 берегобігунів, і на тебе чекатиме винагорода.", [3] = "Убийте 7 хвилеловів, 7 воїнів, 7 оракулів і 7 берегобігунів і поверніться до капітана Сивенко на маяк Західного краю.", [4] = "Убий 7 хвилеловів, 7 воїнів, 7 оракулів і 7 берегобігунів, і на тебе чекатиме винагорода.", [5] = "Хороша робота, {ім'я}. У тебе відмінні бойові навички. Завдяки тобі на узбережжі Західного краю стало безпечніше.", ["en"] = "The Coast Isn't Clear", ["tasks"] = { ["Murloc Coastrunner"] = "мурлок-берегобігун", ["Murloc Coastrunner slain"] = "мурлок-берегобігун: убито", ["Murloc Oracle"] = "мурлок-оракул", ["Murloc Oracle slain"] = "мурлок-оракул: убито", ["Murloc Tidehunter"] = "мурлок-хвилелов", ["Murloc Tidehunter slain"] = "мурлок-хвилелов: убито", ["Murloc Warrior"] = "мурлок-воїн", ["Murloc Warrior slain"] = "мурлок-воїн: убито" } },
    [1520] = { [1] = "Поклик землі", [2] = "Сапта — це напій, створений для того, щоб зв'язувати наш дух зі стихіями. З'єднаний з магією, цей напій дозволить найбільш сприйнятливим побачити стихії так, як ніхто інший раніше їх не бачив. Твій дух назавжди поєднається зі стихією, для якої було створено сапту. Секрет створення цієї сапти відомий лише декільком шаманам.\n\nСапту можна пити лише у священних місцях, і ніде більше.\n\nВідшукай шаманський вівтар на схід звідси та випий там сапту.", [3] = "Знайдіть камінь кодо та випийте біля нього сапту землі.", [5] = "А... {ім'я}... земля рада, що ти тут.\n\nПоєднавши своє тіло із духом, ти підеш вперед, знаючи, що гори — твоя сила, рівнини — твоє терпіння, а сам світ — основа твоєї сутності.\n\nУсе, що потрібно тобі, щоб виконати цей обряд — це покірно постати перед землею. Але інші обряди вимагатимуть активніших дій. Вони можуть бути непередбачуваними та часто жорстокими, але така вже природа стихій. Тобі слід навчитися справлятися з вічною боротьбою протилежностей, що лежить в їхній основі.", ["en"] = "Call of Earth", ["tasks"] = { ["Earth Sapta"] = "сапта землі" } },
    [1521] = { [1] = "Поклик землі", [2] = "Візьми в мене цей грубий кварц та віднеси його провидиці Вороняче Перо як підтвердження нашої зустрічі. Вона створить для тебе тотем, серцем якого буде цей камінчик. Яким би малим він не здавався, ти згодом зрозумієш що розмір не має значення, і що навіть найменші речі можуть пережити гори.\n\nНаберись терпіння, {ім'я}. Залишайся {стать:сильним:сильною}. І шукай мудрості. Це те, про що тебе просить земля. Зрештою, ти станеш одним цілим із землею — шануй її, і вона шануватиме тебе.", [3] = "Принесіть грубий кварц до провидиці Вороняче Перо в табір Нараче.", [4] = "Мої вітання, {ім'я}. Ти б не {стать:повернувся:повернулась} до мене, якби не {стать:виконав:виконала} свого завдання. Дозволь мені першою привітати тебе з першими кроками на першому з чотирьох шляхів, що завжди вестимуть тебе до твоєї долі.\n\nЯкщо ти маєш камінь, що дала тобі земля, я дам тобі обіцяний тотем. Якщо ж ні, то мені тебе шкода. Ти відчуєш велику гордість, коли повністю присвятиш себе стихіям.", [5] = "Блискуче!\n\nТотем, який я тобі зроблю — це більше, ніж просто символ, він потрібен для дечого більшого. Один із варіантів його застосування — це зосередження на ньому заклинань. Ці заклинання пов'язані із землею, і згодом, як ти набуватимеш все більшої й більшої мудрості, тобі стане доступно більше здібностей землі. Тренери по усьому Калімдору знатимуть, коли ти будеш {стать:готов:готова} отримати нові знання, і дадуть тобі знати про це при зустрічі.\n\nА поки що візьми цей тотем землі...", ["en"] = "Call of Earth", ["tasks"] = { ["Rough Quartz"] = "грубий кварц", ["Rough Quartz (Provided)"] = "грубий кварц (видано)" } },
    [1522] = { [1] = "Поклик вогню", [2] = "Нехай вогонь буде із тобою, {стать:друже:подруго}. Я бачу, тобі вже знайомі сили землі, тож певно ти {стать:готовий:готова} поговорити з Краналом.\n\nКранал живе на півночі від Перехрестя у Степах. Він добре володіє стихіями та може навчити тебе володіти вогнем... якщо ти відчуваєш, що {стать:готовий:готова} до цього.\n\nЙого легко знайти, просто не заходь дуже далеко — а то опинишся в землях ельфів.", [3] = "Знайдіть Кранала Фісса у Степах.", [5] = "Хм... То тебе Палько прислав, так?\n\nТоді добре, Палькові завжди можна було довіряти, тож це має означити, що ти {стать:готовий:готова} спробувати наступну сапту — сапту вогню.\n\nЯ вже бачу це у твоїх очах, палання, жадання. Ти вже {стать:відчув:відчула} силу і тепер {стать:готовий:готова} до більшого. Терпіння, {ім'я}. Пам'ятай, чого навчила тебе земля. Сила й руйнування даються легко, але ти все одно {стать:повинен:повинна} знати, коли зупинитися.", ["en"] = "Call of Fire" },
    [1525] = { [1] = "Поклик вогню", [2] = "Але ти {стать:прийшов:прийшла} сюди не на урок історії, чи не правда? Ти {стать:прийшов:прийшла} в пошуках Вічного вогню і тотема вогню.\n\nПерший крок — створити сапту та зв'язати тебе з полум'ям.\n\nЯ зможу створити для тебе сапту вогню, якщо ти принесеш мені дві речі. Перша річ — це вогняна смола, простий предмет, який зазвичай носять бритвогриві заклиначі у східних Степах.\n\nДругий предмет буде важче здобути: мішечок з реагентами від одного з культистів Палаючого Леза. Ти знайдеш їх у печері над ярами на північний схід від Колючого Пагорба.", [3] = "Принесіть вогняну смолу та мішечок з реагентами Телфу Джууламу в Дуротар.", [4] = "У мене достатньо інгредієнтів для сапти вогню. Потрібно лише щоб ти {стать:приніс:принесла} мішечок з реагентами та трохи вогняної смоли. Культисти Палаючого Леза носять необхідні компоненти для більшості своїх заклинань у мішечках, і, як правило, у них там вже є інгредієнти, які мені потрібні, щоб нам не довелось шукати щось інше.\n\nСапти завжди виготовляються з інгредієнтів, які тісно пов'язані з відповідними стихіями. Це полегшує нашу роботу через зв'язок чорнокнижників з вогнем.", [5] = "Це саме те, що було потрібно, {ім'я}.\n\nВогонь — це більше, ніж хаос і руйнування, пам'ятай про це. Вогонь — це також життя та творення. Таким чином всі речі пов'язані між собою. Сили протистоять одна одній, але водночас одна без іншої не може існувати. Обидві гасять одна одну, але також надають одна одній сенс. Завжди пам'ятай про це.\n\nПоєднання різних видів магії означає не тільки справжню майстерність, але й велику мудрість.", ["en"] = "Call of Fire", ["tasks"] = { ["Fire Tar"] = "вогняна смола", ["Fire Tar (Provided)"] = "вогняна смола (видано)", ["Reagent Pouch"] = "мішечок з реагентами", ["Reagent Pouch (Provided)"] = "мішечок з реагентами (видано)" } },
    [1526] = { [1] = "Поклик вогню", [2] = "Сапта вогню готова. Настав час тобі зустрітися з полум'ям. Випий сапту біля вівтаря та вирушай на вершину гори, щоб зустрітися з проявом стихії. Він не нападе, доки ти не будеш {стать:готов:готова}, але він знатиме, що ти його бачиш.\n\nТи маєш перемогти його якнайшвидше, {ім'я}, оскільки чим довше ви будете битись, тим більше зростатиме його сила. Коли прояв вогню погасне, помісти його розжарені вуглинки в жаровню та запали смолоскип.", [3] = "Переможіть менший прояв вогню та покладіть розжарену вуглинку в жаровню на вершині храму Вічного Вогню.", [4] = "Жаровня заввишки приблизно з третину вашого зросту і виглядає цілком звичайною, за винятком написів уздовж гладких металевих рейок. Метал виглядає як новий, а чаша на вершині жаровні прохолодна на дотик.", [5] = "Біле гаряче полум'я спалахує в чаші, щойно ви кладете в неї вуглинку. Ви відчуваєте магічний ефект сапти, що протікає по вашому тілу, а вогонь ритмічно танцює перед вами.\n\nВи поміщаєте верхню частину смолоскипа в чашу, і вона одразу ж спалахує.", ["en"] = "Call of Fire", ["tasks"] = { ["Glowing Ember"] = "розжарена вуглинка", ["Glowing Ember (Provided)"] = "розжарена вуглинка (видано)", ["Torch of the Dormant Flame"] = "смолоскип дрімаючого полум'я", ["Torch of the Dormant Flame (Provided)"] = "смолоскип дрімаючого полум'я (видано)" } },
    [1527] = { [1] = "Поклик вогню", [2] = "Міцно тримаючи факел у руці, ви відвертаєтесь від жаровні й дивитеся на Дуротар. Ви відчуваєте хвилювання, яке переймає ваш дух, коли вітер підіймається і змушує вогонь бурхливо танцювати.\n\nВи починаєте свій зворотний шлях до Степів в пошуках Кранала Фісса.", [3] = "Принесіть смолоскип вічного полум'я до Кранала Фісса у Степи.", [4] = "О, {ім'я}? Що там в тебе?", [5] = "Твій дух горить яскравіше, ніж будь-який смолоскип, який я коли-небудь бачив, {ім'я}, і ти маєш пишатися цим.\n\nЯкщо ти продовжиш йти цим шляхом, стихії коритимуться тобі, а наші побратими шукатимуть в тебе порад та мудрості.", ["en"] = "Call of Fire", ["tasks"] = { ["Torch of the Eternal Flame"] = "смолоскип вічного полум'я", ["Torch of the Eternal Flame (Provided)"] = "смолоскип вічного полум'я (видано)" } },
    [1528] = { [1] = "Поклик води", [2] = "Вода — твоє майбутнє, {стать:друже:подруго}. Я бачу, шо ти вже {стать:покорив:покорила} огонь, і думаю, ти {стать:готовий:готова} поговорить з Іслен.\n\nВона живе на березі Степів. Іди на південь вздовж Південнолютної річки й не пропустиш її — шукай здорову акулу! Іслен — вміла повелителька стихій і покаже тобі путь води... якщо ти до цього {стать:готовий:готова}.\n\nЇї просто знайти, тіки не заходь сильно далеко на південь — вона зразу за Брашпилем.", [3] = "Знайдіть Іслен Морську Провидицю в Степах.", [5] = "Ти твердо крокуєш по землі, а твій дух вже зігрітий вогнем — я б сказала, що настав час тобі пізнати чистоту води.\n\nТвій шлях привів тебе так далеко, і сила твого духу дасть тобі сил йти далі. Але перший крок ти маєш зробити {стать:сам:сама}.", ["en"] = "Call of Water" },
    [1529] = { [1] = "Поклик води", [2] = "Минуло багато часу з твого останнього випробування, {ім'я}. Досі ти {стать:проявляв:проявляла} чимало терпіння у своєму навчанні, та настав час тобі зробити новий крок. Настав час пізнати чистоту води.\n\nПоговори з Іслен Морською Провидицею в Степах. Ти знайдеш її в рибальській хатині на східному узбережжі, на південь від Південнолютної річки та Брашпиля. Щасти тобі, {ім'я}.", [3] = "Знайдіть Іслен Морську Провидицю в Степах.", [5] = "Ти твердо крокуєш по землі, а твій дух вже зігрітий вогнем — я б сказала, що настав час тобі пізнати чистоту води.\n\nТвій шлях привів тебе так далеко, і сила твого духу дасть тобі сил йти далі. Але перший крок ти маєш зробити {стать:сам:сама}.", ["en"] = "Call of Water" },
    [1530] = { [1] = "Поклик води", [2] = "Насамперед ти маєш засвоїти, що вода означає відродження.\n\nЇї сила тече, розмиває та очищає все суще. Її здатність зцілювати й відновлювати незрівнянна, але тільки тоді, коли вона чиста.\n\nКоли ти зрозумієш, що забруднена вода може спустошити все, до чого торкається, ти зрозумієш і те, наскільки вона важлива для нашого буття.\n\nЯкщо ти бажаєш отримати сапту води, відшукай Бріну в південних Степах. На її домівку постійно нападають тамтешні свинобрази.", [3] = "Знайдіть Бріну в південних Степах.", [5] = "Так?\n\nЗдається, я знаю твоє перше питання: кому може спасти на думку жити в глибинах Степів, поруч зі свинобразами, та ще й без жодного захисту? Що ж, у кожного з нас свої причини діяти так чи інакше. У мене ж інше питання: що змусило {стать:простого:просту} {раса:з} прийти в глибини Степів, щоб поговорити з жінкою, яку, очевидно, не турбує власний добробут?\n\nГотова посперечатися, що ми обоє знаємо відповідь на це питання.", ["en"] = "Call of Water" },
    [1531] = { [1] = "Поклик повітря", [2] = "Гля, а ти просуваєсся. Я певен шо ти {стать:гідний:гідна} отримати тотем вітру, але сперва тобі слід найти Прату Пантрувачку Хмар у Тисячах Шипів. Будь {стать:поважним:поважною} з нею і вона розкаже тобі, як здобути його.\n\nТопай на південь Степів, і як достанешся до Тисячі Шипів, вертай на схід. Вона ховається десь в норі зі своїм хлопцем — хаха! Тіки не пробовкнись їй шо я таке сказав, бо вона узлиться.", [3] = "Знайдіть Прату Пантрувачку Хмар у Тисячі Шипів.", [5] = "Наразі я дам тобі те, що тобі потрібно для зосередження своїх заклинань та виклику духів повітря. Візьми цей тотем, а коли будеш {стать:готовий:готова} продовжити навчання — приходь знову.", ["en"] = "Call of Air" },
    [1534] = { [1] = "Поклик води", [2] = "Візьми цей бурдюк і вирушай вглиб густого лісу, який нічні ельфи називають Ясенедолом. Він знаходиться далеко на півночі від Степів.\n\nЩойно увійдеш до лісу — рушай на захід. Біля кряжа, що розділяє Каміннопазуристі гори і Ясенеділ, і за озером Містраль, ти знайдеш священне місце — руїни Зорепилу. У центрі озера, на острівці, є маленький фонтан.\n\nПринеси мені зразок води з нього. Це останній компонент, який тобі потрібно зібрати, перш ніж повернутись до Іслен.", [3] = "Наповніть порожній блакитний бурдюк в руїнах Зорепилу, що в Ясенедолі та поверніться з ним до Бріни в Степи.", [4] = "Ти вже {стать:набрав:набрала} води, {ім'я}? Кажуть, що руїни охороняють величезні створіння природи, які не шанують гостей, але, ймовірно, це всього лише легенди, що мають відлякувати ворогів нічних ельфів.\n\nХоч би що там було, будь {стать:обережний:обережна}.", [5] = "Чудово, {ім'я}. Тепер у мене є всі три зразки води, і я можу створити для тебе фіал з найчистішою водою, яку тільки здатна знайти жива істота. Вона знадобиться тобі на наступних етапах твоєї посвяти.\n\nЯ рада, що серед тих, хто обрав наш шлях, є такі, як ти, {ім'я}. Усі шамани пишаються тобою, і я з нетерпінням чекаю почути про твої подвиги в майбутньому.", ["en"] = "Call of Water", ["tasks"] = { ["Filled Blue Waterskin"] = "наповнений блакитний бурдюк", ["Filled Blue Waterskin (Provided)"] = "наповнений блакитний бурдюк (видано)" } },
    [1535] = { [1] = "Поклик води", [2] = "Щоб знайти порозуміння та отримати від мене сапту, тобі доведеться відшукати найчистішу воду. Коли ти збиратимеш її зразки, поглянь на навколишній світ. Зверни увагу на істот, які покладаються на воду і захищають її. Подивись, як вона впливає на ліси й пустелі. Ти побачиш, як те, що підтримує життя, змушує істот забирати це життя в інших.\n\nПочнемо з простого завдання: під моєю хатиною є ставок з цією дорогоцінною рідиною. Наповни нею цей бурдюк і повертайся до мене.", [3] = "Наповніть порожній коричневий бурдюк в ставку під хатиною Бріни та поверніться з ним до Бріни в Степи.", [4] = "Я готова дати тобі наступне завдання. Ти вже {стать:наповнив:наповнила} бурдюк?\n\nЯ знаю, як ревниво свинобрази можуть захищати водопій. Навіть таке маленьке джерело води для них — справжній скарб. Вони влаштовують великі бенкети, коли в Степах йде навіть найменший дощ. Вода для них священна, бо її так мало. Розумієш?", [5] = "Я припускала, що кровопролиття не уникнути, якщо ти спробуєш взяти воду зі ставу. Шкода, що свинобрази не розуміють, що все живе пов'язане між собою. Їхня жадібність лише посилює біль і страждання їхнього ж народу. Як багато вони могли б досягти, якби забули про суперечки й об'єднались...\n\nЗнову ж таки, для них це погано, але для інших мешканців Степів — радше добре.", ["en"] = "Call of Water", ["tasks"] = { ["Filled Brown Waterskin"] = "наповнений коричневий бурдюк", ["Filled Brown Waterskin (Provided)"] = "наповнений коричневий бурдюк (видано)" } },
    [1536] = { [1] = "Поклик води", [2] = "Колись давно я з кількома товаришами вирушила у передгір'я Гіллзбраду. Нам довелося відбиватися від людей, що оселилися в тих краях, і врешті-решт ми опинилися в маленькому містечку, яке захопили відречені — Тарренському Млині.\n\nСаме там я виявила дивовижну річ: у центрі містечка був невеликий колодязь зі свіжою джерельною водою. Не думаю, що уражені чумою мешканці міста усвідомлюють його цінність — це маленький промінь світла в царстві темряви.\n\nНабери воду з того колодязя в цей бурдюк і принеси мені.", [3] = "Наповніть порожній червоний бурдюк з колодязя на Тарренському Млині та поверніться з ним до Бріни в Степи.", [4] = "Колодязь, що залишився чистим в такому місці, нагадує мені історії, які мені розповідали в дитинстві, {ім'я}. Навіть у часи великого болю і скорботи можна знайти промінь надії, навколо якого можна згуртуватися. Саме таким променем надії для орків є Тралл. Він вижив, незважаючи ні на що, і повів за собою наш народ.\n\nНе думаю, що хоч хтось з орків страждав стільки, скільки страждав він, але водночас жодному орку не була дарована така сила.", [5] = "Добре, {ім'я}. Ти {стать:відданий:віддана} своїй справі та вмієш йти до мети.\n\nЩе один зразок, і я зможу створити реагент, необхідний для твоєї сапти. Іслен буде задоволена.", ["en"] = "Call of Water", ["tasks"] = { ["Filled Red Waterskin"] = "наповнений червоний бурдюк", ["Filled Red Waterskin (Provided)"] = "наповнений червоний бурдюк (видано)" } },
    [1537] = { [1] = "<NYI> Поклик повітря", ["en"] = "<NYI> Call of Air" },
    [1558] = { [1] = "Каменярська дамба", [2] = "Залізогарт — це місце, де живуть усі гноми й дворфи. Поряд з ним знаходиться місце під назвою Лох-Модан, і дворфи побудували там ВЕЛИЧЕЗНУ дамбу. Кажуть, це одна з найбільших споруд, які коли-небудь створювали. Вау!\n\nЧи можеш ти взяти мене до Лох-Модану, щоб я міг побачити ту дамбу, будь ласка? Здається, її називають \"Кам'яна...\" ем... \"Камнярська дамба\"? \"Каменярська\"? Вона велика — це точно. Я хочу подивитися на величезний водоспад. Обіцяю, що не буду нахилятися надто далеко!", [3] = "Відведіть свого підопічного до Каменярської дамби в Лох-Модані. Відведіть його на середину дамби, щоб він міг подивитися на гігантський водоспад.", [4] = "Ми вже прийшли?", [5] = "ВАУ, дамба набагато більша, ніж я думав! Я майже не міг почути свій голос через гуркіт води! Як думаєш, вода коли-небудь закінчиться? Що станеться, якщо ця дамба розірветься? ВАУ, це було б жахливо!\n\nДякую, що {стать:взяв:взяла} мене на дамбу. Ти дуже {стать:добрий:добра}. Я ж казав, що не нахилятимусь надто далеко!", ["en"] = "The Stonewrought Dam", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Go to the top of the Stonewrought Dam in Loch Modan."] = "Підніміться на вершину дамби Stonewrought у озері Лох-Модан." } },
    [1559] = { [1] = "Рецепт світлової бомби", [5] = "То ти {стать:інженер:інженерка}, так? Що ж, за те, що ти {стать:допоміг:допомогла} мені дістати ці перлини, тримай креслення світлової бомби.\n\nЩасти тобі, і бережи очі!", ["en"] = "Flash Bomb Recipe" },
    [1560] = { [1] = "Завдання Тооґи", [2] = "Я заблукав!\n\nМоя дружина, Торта, послала мене за обідом, і я, мабуть, звернув десь не там.\n\nВідведи мене, будь ласка, назад до Торти! Вона чекає на мене на півдні від порту Паровиманювання.", [3] = "Проведіть Тооґу до його дружини, Торти.", [4] = "Де Тооґа?", [5] = "Тож він не зміг самостійно знайти дорогу назад? Зрозуміло.\n\nГадаю, ти заслуговуєш щось за свої клопоти.", ["en"] = "Tooga's Quest", ["tasks"] = { ["Lead Tooga to Torta"] = "Ведіть Тугу до Торти" } },
    [1579] = { [1] = "Світлоштепселі", [2] = "Я прибув до Аубердіна в пошуках спокою. Я хочу займатися своїми винаходами у тихому місці, бо після ночі пияцтва я не можу витримати весь цей шум в Залізогарті!\n\nТому я взяв корабель до Аубердіна і трохи перебрав по дорозі. І впустив свою коробку зі світлоштепселями за борт! Мені потрібні мої світлоштепселі!\n\nЯ не знаю, де саме я їх випустив, але якщо ти будеш рибалити в океані, тобі може пощастити...", [3] = "Принесіть 8 світлоштепселів Бацбаху Корбаклацу в Аубердін.", [4] = "Ти {стать:знайшов:знайшла} мої світлоштепселі, {ім'я}? Без них я не зможу налаштувати дугошипно-обертальний механізм!", [5] = "Не можу повірити, що ти їх {стать:знайшов:знайшла}! Оце так тобі щастить!", ["en"] = "Gaffer Jacks", ["tasks"] = { ["Gaffer Jack"] = "світлоштепсель", ["Gaffer Jack (Provided)"] = "світлоштепсель (видано)" } },
    [1580] = { [1] = "Електропелери", [2] = "Ми знаємо, що тобі щастить, але... наскільки щастить, {ім'я}?\n\nОдного разу вночі я блукав дорогами Темнобережжя. Шукав якусь гарну річку або озеро, щоб випробувати свою нову самокеровану, вибухову качину приманку, і, мабуть, був злегка п'яний... бо я втратив свідомість і прийшов до тями в Аубердіні через кілька годин. Моє волосся було обгоріле, а сумка з електропелерами зникла! Можливо, я впустив її у воду!\n\nМені потрібні ті електропелери! Можливо, ти зможеш витягти їх із якого-небудь озера чи річки в Темнобережжі...", [3] = "Принесіть 12 електропелерів Бацбаху Корбаклацу в Аубердін.", [4] = "Ти {стать:знайшов:знайшла} електропелери? Вони мені знадобляться, щоб продовжити дослідження качиних приманок...", [5] = "Я не можу в це повірити! Ти {стать:знайшов:знайшла} їх! Ти {стать:найкращий:найкраща} рибалка, {стать:якого:яку} я коли-небудь бачив!\n\nСпасибі тобі, {ім'я}. І ось, візьми це. Хоча {стать:такий вправний:така вправна} рибалка, як ти, впорається й без них, та все ж вони можуть допомогти тобі.", ["en"] = "Electropellers", ["tasks"] = { ["Electropeller"] = "електропелер", ["Electropeller (Provided)"] = "електропелер (видано)" } },
    [1598] = { [1] = "Вкрадена книга", [2] = "Гей ти! Ти {ім'я:н}, вірно?\n\nЯ сподіваюся, що ти {стать:впевнений:впевнена} у своєму рішенні стати {стать:чорнокнижником:чорнокнижницею}, інакше ти так і залишишся на дні.\n\nЯ навчу тебе, але спершу маю переконатися, що ти достатньо {стать:сильний:сильна}.\n\nУ абатстві був послушник, який втік, щоб приєднатися до Братства Непокірних. Яке мені до цього діло? Він вкрав кілька важливих книг.\n\nОдна з них — \"Сили Порожнечі\", саме та книга, яка мені потрібна. Вкради її для мене, вони ховають її у своєму наметі на виноградниках.", [3] = "Поверніть книгу \"Сили Порожнечі\" Друсіллі ла Салле.", [4] = "Для мене було б надто небезпечно намагатися викрасти цю книгу з абатства. Яке щастя, що цей простак зробив всю брудну роботу за мене!", [5] = "Чудово... Мені ніколи б не вдалося отримати доступ до цього тексту, він зберігався в захищеному крилі бібліотеки, тож було б підозріло, якби я там вешталась.\n\nЩо ж, ти добре {стать:виконав:виконала} це завдання, і я переконана, що ти, ймовірно, зможеш керувати своїм власним бісом, тож я не бачу причин не навчити тебе його виклику.", ["en"] = "The Stolen Tome", ["tasks"] = { ["Powers of the Void"] = "Сили Порожнечі", ["Powers of the Void (Provided)"] = "Сили Порожнечі (видано)" } },
    [1599] = { [1] = "Початок", [2] = "Ти, мабуть, {стать:новий:нова} {стать:чорнокнижник:чорнокнижниця}, про {стать:якого:яку} всі шепочуться. Мабуть, ти комусь дуже {стать:сподобався:сподобалася}, якщо мене попросили відірватися від моїх досліджень, щоб розпочати твоє навчання.\n\nНе хвилюйся, я не тримаю на тебе зла.\n\nНайпростіше заклинання виклику, яке ти маєш вчити, це виклик біса. Однак, перш ніж я тебе навчу, ти {стать:повинен:повинна} довести, що маєш необхідні магічні та фізичні здібності.\n\nПринеси мені три обереги з пір'я, що носять морозогриві послушники з печери на південному заході.", [3] = "Принесіть 3 обереги з пір'я Аламару Грімм в Ковмар.", [4] = "Ті обереги з пір'я, що носять ці послушники, мають в собі певну магічну силу. Буде цікаво їх дослідити. Я не очікував такого від тролів.", [5] = "Добре, дуже добре! Ти молодець, {ім'я}. Можливо, твоя слава дійсно заслужена.\n\nУтім, це не мені вирішувати. Якщо твій біс не перевершить тебе і не зіпсує твою кар'єру в зародку. Але наразі я задоволений тим, що ти, ймовірно, переживеш перші кілька місяців як {клас}.\n\nДо речі, про біса, {ім'я}. Ти певно це й так розумієш, та все ж не дай його розміру обманути тебе — його магія може бути дуже небезпечною.", ["en"] = "Beginnings", ["tasks"] = { ["Feather Charm"] = "оберіг з пір'я", ["Feather Charm (Provided)"] = "оберіг з пір'я (видано)" } },
    [162] = { [1] = "Нашестя силітидів", [2] = "Я раджу тобі передати цей звіт кому-небудь, хто має практичні знання у цій справі.\n\nЯ знаю нічну ельфу-науковицю, на ім'я Ґрасіна Міцнодуха. Вона провела багато часу, вивчаючи форми життя, що є унікальними для екології Азероту, а ще вона історик! Якщо ти хочеш, щоб хтось допоміг з'ясувати, що саме є цією загрозою, і, що ще важливіше, як зупинити її — передай їй звіт. Нам потрібна допомога.\n\nВостаннє я чув, що вона знаходиться в храмі Місяця, що в Дарнасі.", [3] = "Віднесіть звіт про дослідження комах Ґрасіні Міцнодухій в Дарнас.", [4] = "Мир і спокій тобі, {стать:незнайомцю:незнайомко}. Навіщо ти {стать:шукав:шукала} мене?", [5] = "Цей звіт... Ми, нічні ельфи, знаємо про жах, що згадується тут. Шипохідник вчинив мудро, відправивши тебе до мене.\n\nЦі істоти швидко б поглинули пустелю Танаріс; вони є однією з найбільших загроз, з якими ми всі коли-небудь стикалися. Запам'ятай цю назву, {ім'я}: силітиди. Ці комахи, що згадуються тут, є силітидами, і вони є інструментом однієї з найбільших загроз, з якими зіткнуться як Орда, так і Альянс.\n\nЯкби ж ми були достатньо розумними, щоб зрозуміти це раніше.", ["en"] = "Rise of the Silithid", ["tasks"] = { ["Insect Analysis Report"] = "звіт про дослідження комах", ["Insect Analysis Report (Provided)"] = "звіт про дослідження комах (видано)" } },
    [1638] = { [1] = "Навчання воїна", [2] = "Ти {стать:довів:довела}, що ти {стать:вправний:вправна} {клас}, {ім'я}. Але ти ще {стать:юний:юна} і маєш багато чому навчитись.\n\nПоговори з Гаррі Яровартом — ти знайдеш його в таверні \"Свиня і Свисток\" в Старому Місті Штормовію. Гаррі досвідчений боєць і гарний вчитель. Він може показати тобі кілька прийомів, що дозволять тобі прожити довше.", [3] = "Поговоріть з Гаррі Яровартом.", [5] = "О-хо! Випий зі мною, {стать:хлопче:дівко}. Виглядаєш кремезно, та подивимось, що з тобою зроблять кілька кухлів тутешнього пійла!\n\nЧи... ти вчитись {стать:прийшов:прийшла}?", ["en"] = "A Warrior's Training" },
    [1650] = { [1] = "Фоліант доблесті", [2] = "Чудово! Відсутність вагань є вірною ознакою того, що ти {стать:готовий:готова} і прагнеш випробувати себе. Тож хай буде так.\n\nНа самому півдні Довгоберегу, що в Західному краї, стоїть будинок з видом на океан. Там живуть Стілвелли. Джордан — неймовірно вправний коваль, тож він відправився на деякий час до Залізогарту, щоб зустрітись з дворфами. Та його дружина, Дафна, залишається вдома одна, без захисту.\n\nНаші дані свідчать про те, що Непокірні захопили тамтешні землі, тож Дафні може знадобитись захист від цих негідників. Відправляйся до неї.", [3] = "Знайдіть Дафну Стілвелл у Західному краї.", [5] = "Вітаю, {ім'я:к}. Судячи з твоїх обладунків та зброї, ти або хочеш захопити мої землі, або ж церква нарешті прислала когось мені на захист, поки Джордан відправився до Залізогарту.\n\nЩо ж, я Дафна Стілвелл. Приємно познайомитись.\n\nТи не надто пізно. Я встигла вбити лише з десяток цих покидьків за сьогодні. До цього вони сюди не надто поспішали, та побачивши тебе, вони можуть прийти будь-якої миті.", ["en"] = "The Tome of Valor" },
    [1651] = { [1] = "Фоліант доблесті", [2] = "Вони скоро повернуться, тож приготуйся.\n\nВ мене є рушниця вдома, тож я спробую тобі допомогти. Та загалом — покладайся тільки на себе.\n\nНе знаю, скільки їх прийде цього разу, та певно більше, ніж раніше.\n\nМоли Світло про благословення, бо... Чуєш? Схоже, вони вже тут.\n\nМи приймемо бій біля будинку!", [3] = "Захистіть Дафну Стілвелл від нападу Непокірних.\n\nНі її, ні ваш дух не має покинути тіло.\n\nПісля перемоги знову поговоріть з Дафною Стілвелл.", [4] = "Ми приймемо бій біля будинку!", [5] = "Ми впорались, {ім'я:к}! Дякую тобі за допомогу. Це було просто неймовірно! Не думала, що {клас} може впоратись з такою кількістю ворогів.\n\nТвоя хоробрість в бою з переважаючими силами просто вражає.", ["en"] = "The Tome of Valor", ["tasks"] = { ["Protect Daphne Stilwell"] = "Захистіть Дафну Стілвелл" } },
    [1652] = { [1] = "Фоліант доблесті", [2] = "Прошу, повертайся до Даторіана і передай, що я в безпеці. Все завдяки тобі й церкві.\n\nВін відправить звістку до Залізогарту, щоб Джордан не хвилювався за мене.\n\nОх, як я сумую за своїм чоловіком. Не можу дочекатись, коли він повернеться.", [3] = "Поговоріть з Даторіаном Раллом в Штормовії.", [5] = "Ось ми й знову зустрілися, {ім'я:к}. Бачу, ти в гарному настрої.\n\nБудинок Стілвеллів буде в безпеці ще деякий час. А з твоєї розповіді ясно, що небезпеки було вдосталь. Гарна робота.\n\nДафна та Джонатан дуже допомогли церкві. Тож те, що ти {стать:захистив:захистила} їх майно і життя — найменше, що ми могли зробити.\n\nЗа свою доблесть ти отримаєш гідну винагороду.", ["en"] = "The Tome of Valor" },
    [1653] = { [1] = "Випробування праведності", [2] = "Насправді, я не сумніваюсь, що Джордан і сам міг би тобі віддячити. Тим більше, що мені потрібен посланець, який передасть йому, що його дружина в безпеці. А ти чудово підходиш.\n\nДжордан раніше теж був паладином Світла, поки не вирішив продовжити справу свого батька, тож він добре знайомий з нашими звичаями та вважається одним з найвірніших послідовників нашого шляху.\n\nЗараз він має бути десь в Залізогарті. Йому подобається працювати за воротами міста, насолоджуючись свіжим гірським повітрям.", [3] = "Поговоріть з Джорданом Стілвеллом в Залізогарті", [5] = "Добридень, {ім'я:к}. Ти служиш Світлу, чи не так?\n\nТебе прислав Даторіан? Як там моя дружина? Я знав, щойно я поїду, вдома почнуться проблеми. Прошу, скажи, що з нею все... Ох, хвала Світлу. Я так радий, що вона в безпеці. Непокірні були небезпечними задовго до цих нападів, але тепер радники короля не зможуть ігнорувати цю загрозу.\n\nЩо ще Даторіан просив передати?\n\nТи {стать:той:та}, кого відправили захищати Дафну? Тоді ще раз дякую тобі, {ім'я:к}. Не можу уявити собі кращого випробовування доблесті.", ["en"] = "The Test of Righteousness" },
    [1657] = { [1] = "Сморід Південнобережжя", [2] = "Святкуй Повечір'я святих зі стилем... завдаючи страждань нашим ворогам у Південнобережжі!\n\nВізьми одну з цих спеціально виготовлених смердючих бомб. Вона наповнена запахом, який жодна людина — або будь-яка слабкодуха тварина — не зможе витримати. Тобі потрібно кинути її прямо у серце Південнобережжя, щоб вона спрацювала як треба, тому будь {стать:готовим:готовою} до битви з Альянсом!\n\nКоли виконаєш це завдання... тобто внесок у наше визволення, повертайся до мене!", [3] = "Киньте три смердючі бомби відречених в серце Південнобережжя, що в Гіллзбраді, а потім поверніться до Янки Темноклич на фестиваль Плетеного чоловічка в Тірісфальське перелісся.", [4] = "Ти {стать:доставив:доставила} наш \"подарунок\" жителям Південнобережжя?\n\n<Янка злісно сміється.>", [5] = "Ах, молодець! Сподіваюся, Альянс подавиться отрутою, яку ми їм даруємо, так само як ми були змушені задихатися від гніту рабства під Скарою!\n\nТи {стать:зберіг:зберегла} справжні традиції Повечір'я святих, {ім'я}, і за це я тобі кланяюся. Як додатковий бонус, дозволь поділитися з тобою цими ласощами Повечір'я святих. Думаю, тобі буде дуже приємно насолодитися ними!", ["en"] = "Stinking Up Southshore", ["tasks"] = { ["Toss Stink Bomb into Southshore"] = "Киньте смердючу бомбу в Південний берег", ["Toss Stink Bomb into Southshore (Provided)"] = "Киньте смердючу бомбу в Південний берег (видано)", ["Toss Stink Bomb into Southshore slain"] = "Киньте смердючу бомбу в Південний берег: убито" } },
    [1659] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [1660] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [1661] = { [1] = "Фоліант благородства", [2] = "Радий знову бачити тебе, {ім'я:к}. Я пишаюсь називати тебе {стать:братом:сестрою}, твоя самовідданість — знак великої поваги до всіх нас.\n\nПрийшов час вручити тобі великий дарунок. Але знай, зараз я даю тобі його за твої минулі діяння, та коли прийде час — я запропоную тобі пройти велике випробування.\n\nПриходь до мене за подарунком в будь-який час.", [3] = "Поговоріть з Даторіаном Раллом в Штормовії.", [5] = "Вітаю тебе. І нехай оберігає тебе Світло.", ["en"] = "The Tome of Nobility" },
    [1662] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [1663] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [1664] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [1678] = { [1] = "Веджрік", [2] = "Хороший воїн має бути міцним. Я можу навчити тебе кільком вмінням, та перед цим ти маєш довести свою силу в бою.\n\nВеджрік — один з найсильніших тролів в цих краях. Його ти й маєш перемогти. Знайти його можна в хижах на південь від поселення Морозогривих.\n\nПринеси мені його голову і ми розпочнемо.", [3] = "Принесіть голову Веджріка Мурену Бурешпилю в Залізогарт.", [4] = "Ти вже {стать:був:була} у Веджріка, {ім'я}? Це від тебе тролем смердить?", [5] = "Веджрік той же потвора, скажи? Чудова робота, {ім'я}! Що ж, ти {стать:сильний:сильна}, можемо розпочати тренування...\n\nМожливо ти не в курсі, та гарний захист - одне з важливих вмінь {клас:р}. Це дозволяє вистояти проти найважчих супротивників і захистити побратимів.", ["en"] = "Vejrek", ["tasks"] = { ["Vejrek's Head"] = "голова Веджріка", ["Vejrek's Head (Provided)"] = "голова Веджріка (видано)" } },
    [1679] = { [1] = "Мурен Бурешпиль", [2] = "Вітаю, {клас:к}! Ти непогано себе {стать:проявив:проявила} тут, та ти маєш багато чому навчитись. А кращого вчителя за Мурена Бурешпиля ти не знайдеш.\n\nТи знайдеш Мурена у військовій залі військової палати Залізогарту. Поговори з ним, коли захочеш навчатись ремеслу {клас:р}.", [3] = "Поговоріть з Муреном Бурешпилем.", [5] = "А, {ім'я}. Чув я щось про тебе від воїнів Дун-Морогу. Сподіваюсь, ти не весь час {стать:провів:провела} в тевернах.", ["en"] = "Muren Stormpike" },
    [1680] = { [1] = "Торм Ковоглиб", [2] = "Тепер, коли ти {стать:вивчив:вивчила} нові прийоми, прийшов час роздобути хорошу зброю. Поговори з Тормом Ковоглибом. Певен, тобі сподобається його робота.\n\nТи знайдеш його в Залізогарті біля Великої Кузні.", [3] = "Поговоріть з Тормом Ковоглибом.", [5] = "Тебе Мурен прислав, еге ж? Так, я можу зробити тобі гарну зброю... Та спершу я попрошу тебе дещо зробити для мене.\n\nНе хвилюйся, це буде небезпечне завдання, на якому ти можеш загинути. Те, що треба для {стать:такого:такої} {клас:р}, як ти.", ["en"] = "Tormus Deepforge" },
    [1683] = { [1] = "Ворл Мерзенне Копито", [2] = "Перш ніж я почну навчати тебе, ти маєш довести свою рішучість.\n\nСатир, на ім'я Ворл Мерзенне Копито знайшов один з наших місячних колодязів на південний схід від обителі кургану Бен'етіль. Тепер він бовтається в його священних водах, оскверняючи їх своїм брудом.\n\nЗнайди Ворла біля колодязя і вбий його. Принеси мені його ріг як доказ і ми почнемо твої тренування {клас:р}.\n\nШлях до місячного колодязя знайти нелегко, {ім'я}, тому тобі доведеться добре постаратись в пошуках.", [3] = "Принесіть Еланарії ріг Ворла.", [4] = "Ріг у тебе, {ім'я}? Чи очистився наш місячний колодязь від нечисті Ворла?", [5] = "Молодець, {ім'я}. Приємно знати, що Ворл переможений, а наш місячний колодязь очищений, і приємно бачити молодих воїнів, які прагнуть уберегти наш улюблений Тельдрассіль від порчі.\n\nТепер почнім твоє навчання...", ["en"] = "Vorlus Vilehoof", ["tasks"] = { ["Horn of Vorlus"] = "ріг Ворла", ["Horn of Vorlus (Provided)"] = "ріг Ворла (видано)" } },
    [1684] = { [1] = "Еланарія", [2] = "Вітаю, {клас:к}. Твої навички ростуть, та на шляху воїна тобі належить навчитись багатьом речам. Тобі потрібен вчитель.\n\nВоїтелька Еланарія живе в Дарнасі, на терасі Воїнів. Вона зможе навчити тебе.", [3] = "Поговоріть з Еланарією.", [5] = "Вітаю тебе, {ім'я}. Тебе часто згадують в Дарнасі, адже ти подаєш великі надії. Та скоро ми побачимо, чи достатньо в тобі волі йти шляхом {клас:р}.", ["en"] = "Elanaria" },
    [1685] = { [1] = "Виклик Ґакіна", [2] = "От як так воно працює? Весь день шукав тебе і не міг знайти, а тепер, коли я не очікую, ти з'являєшся і йдеш просто до мене.\n\nЯ вже витратив достатньо часу, намагаючись знайти тебе, тому не буду затримувати тебе надовго. Майстер Ґакін запросив тебе на додаткову підготовку. Мені здається, тобі слід знайти його якнайшвидше.\n\nТи знайдеш його в підвалі таверни \"Зарізане ягня\". Між іншим, тобі, слід тримати це місце в таємниці. Не хочу, щоб про нього дізналися всі.", [3] = "Поговоріть з Ґакіном Темнопрядом у кварталі Магів Штормовію.", [5] = "Нарешті ти {стать:з'явився:з'явилася}. Хоча, можливо, я мав послати когось більш здібного, ніж Ремен, щоб знайти тебе.\n\nНеважливо.\n\nТи вже давно не {стать:тренувався:тренувалася}, а {клас} без тренувань не може довго тримати голову на плечах.", ["en"] = "Gakin's Summons" },
    [1686] = { [1] = "Тінь Елури", [2] = "Ти добре вчишся, {ім'я}. Тепер ти маєш отримати зброю. Справжню зброю {клас:р}.\n\nДля цього тобі доведеться відправитись на Темнобережжя.\n\nДавним-давно на скелях біля маяка Аубердіну розбився корабель, розкидавши по морському дну багато ящиків елунітової руди.\n\nЯщики елуніту охороняються тінню Елури. Колись вона була капітаном корабля, та після катастрофи стала приреченою охороняти вантаж. Переможи її, дістань її медальйон і збери залишки вантажу елуніту.", [3] = "Принесіть 8 шматків елунітової руди та медальйон Елури до Еланарії в Дарнас.", [4] = "Ти вже {стать:переміг:перемогла} тінь Елури і {стать:зібрав:зібрала} елунітову руду?", [5] = "Чудова робота, {ім'я}.\n\nТи {стать:подарував:подарувала} тіні Елури заслужений спокій, а ми зможемо зробити чудову зброю з елуніту.", ["en"] = "The Shade of Elura", ["tasks"] = { ["Elunite Ore"] = "елунітова руда", ["Elunite Ore (Provided)"] = "елунітова руда (видано)", ["Elura's Medallion"] = "медальйон Елури", ["Elura's Medallion (Provided)"] = "медальйон Елури (видано)" } },
    [1687] = { [1] = "Моторошний маяк", [2] = "Іноді пізно вночі, наші опікунки в притулку розповідають нам страшні історії. Вони просто класні! Одна з них про привида, який мешкає біля маяка в Західному краю. Кажуть, він був капітаном піратів і його корабель захопили інші пірати. Вау!\n\nЧи можеш ти, будь ласка, взяти мене до маяка у Західному краю? Я хочу побачити, чи є там привид того капітана! Обіцяю бути поруч з тобою і не тікати!", [3] = "Відведіть сироту подивитися на маяк біля узбережжя Західного краю.", [4] = "Ми вже прийшли?", [5] = "ВАУ, це був справжній привид! Це було так круто — я не можу дочекатися, щоб розповісти всім у притулку. Капітан Сивенко... він навіть виглядав як справжній пірат! Коли я виросту, я теж хочу стати привидом-піратом!\n\nДякую, що {стать:взяв:взяла} мене з собою до Західного краю, {ім'я}. Я знаю, що там, у диких землях Західного краю, є страшніші речі, і сподіваюся, що я не був надокучливим. Ти {стать:крутий:крута}!", ["en"] = "Spooky Lighthouse", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Go to the Westfall Lighthouse."] = "Ідіть до маяка Вестфолл." } },
    [1688] = { [1] = "Сурена Каледон", [2] = "У мене була учениця, на ім'я Сурена Каледон. Вона стояла там, де ти стоїш зараз, прагнучи навчитися мистецтва чорнокнижництва, і володіла неабияким талантом. Окрім того, вона була молода і гарна. Якби ж я тоді побачив, яка вона зрадлива погань!\n\nЦя злодійка втекла з одним із Непокірних — Ерланом Драджмуром. Хоч її втрата малозначна для мене, я подарував їй кольє із кривавого каменю, яке мені все ще потрібне.\n\nЇї життя для мене більше не має значення. Ти знайдеш її на гарбузовому наділі Бреквеллів. Забери те, що належить мені.", [3] = "Поверніть кольє Сурени Ґакіну Темнопряду у Штормовій.", [4] = "Навіть старші та мудріші можуть бути підвладні чарам молодості та краси, {ім'я}. Це порада, яку ти {стать:повинен:повинна} добре запам'ятати на все своє життя.", [5] = "Сурена була талановитою, але не настільки, щоб самостійно опанувати магію чорнокнижництва. Шкода бачити, як талант марнується, але іноді це необхідно.\n\nСподіваюсь, мій вклад в тебе принесе інші результати.", ["en"] = "Surena Caledon", ["tasks"] = { ["Surena's Choker"] = "кольє Сурени", ["Surena's Choker (Provided)"] = "кольє Сурени (видано)" } },
    [1689] = { [1] = "Зв'язування", [2] = "Повернувши моє кольє та перемігши Сурену, ти {стать:довів:довела}, що є принаймні {стать:таким же здібним:такою ж здібною}, як і вона.\n\nПроте я бачу, що ти гостро потребуєш навчання. Ти можеш керувати потоками магії, але бути чорнокнижником — це значно більше.\n\nЯ покажу тобі, як керувати пустотником, але перед цим тобі потрібно викликати його у колі виклику та підкорити його, використовуючи будь-яку зброю — фізичну та магічну — яка є у твоєму розпорядженні. Використай магію цього кольє на колі виклику, що знаходиться нижче.", [3] = "За допомогою кольє із кривавого каменю підкоріть пустотника, а потім поверніть кольє Ґакіну Темнопряду у Штормовій.", [4] = "Я не можу показати тобі, як контролювати пустотника, поки ти не здолаєш його.", [5] = "В тебе вийшло краще, ніж я очікував, {ім'я}, але я на це й сподівався. Тепер ти можеш навчитися керувати своїм підкореним пустотником — союзником, який буде корисним у випробуваннях, які неодмінно постануть перед тобою.\n\nНаразі мені більше немає чому тебе навчити, але я ще не закінчив з тобою, {ім'я}.", ["en"] = "The Binding", ["tasks"] = { ["Bloodstone Choker"] = "кольє з кривавого каменю", ["Bloodstone Choker (Provided)"] = "кольє з кривавого каменю (видано)", ["Summoned Voidwalker"] = "викликаний пустотник", ["Summoned Voidwalker slain"] = "викликаний пустотник: убито" } },
    [1690] = { [1] = "Правосуддя для Пустелебродів", [2] = "Гей, ти! Час тобі стати {стать:великим помічником:великою помічницею} Пристробляхводоканалу.\n\nКочівники Пустелеброди з пустелі Танаріс захопили майже всі колодязі! Без доступу до них наші запаси води миттєво вичерпаються. Якщо ти хочеш заслужити нашу прихильність — допоможи нам принести правосуддя цим кочівникам!\n\nВирушай на схід, вбий десять бандитів та злодіїв Пустелебродів, а потім повертайся до мене. Правосуддя не омине жодної людини... чи гобліна... ай, неважливо, іди собі!", [3] = "Знищіть 10 бандитів та злодіїв Пустелебродів на сході від Пристробляху, а потім повідомте про це головному інженеру Трюмосвисту.", [4] = "Вже {стать:повернувся:повернулася}? Сподіваюсь, ти {стать:зміг:змогла} показати гоблінське правосуддя цим бандитам і злодіям Пустелебродів, як я тебе й просив!", [5] = "Ось це я називаю ефективністю! Ти {стать:зменшив:зменшила} кількість кочівників настільки, що ми можемо починати думати про те, щоб відновити контроль над тими колодязями.\n\nПристробляхводоканал вдячний тобі за допомогу, але ми далекі від завершення справи з цими клятими кочівниками. Слухай — ось що нам потрібно зробити далі...", ["en"] = "Wastewander Justice", ["tasks"] = { ["Wastewander Bandit"] = "бандит Пустелебродів", ["Wastewander Bandit slain"] = "бандит Пустелебродів: убито", ["Wastewander Thief"] = "злодій Пустелебродів", ["Wastewander Thief slain"] = "злодій Пустелебродів: убито" } },
    [1691] = { [1] = "Більше правосуддя для Пустелебродів", [2] = "Тепер нам потрібно, щоб ти {стать:взявся:взялася} за сильніших Пустелебродів. Досі ти добре {стать:попрацював:попрацювала}, але якщо ми хочемо повернути ці колодязі під наш контроль — нам потрібно, щоб цих кочівників стало менше!\n\nЦього разу тобі потрібно вбити їхніх тіньових магів, пройдисвітів і душогубів. Ти знайдеш їх на сході та південному сході звідси.\n\nНе буду тобі брехати — вони дуже небезпечні. Зроби це для нас, і ми зможемо повернути те, що належить нам по праву!", [3] = "Знищіть 10 тіньових магів, 8 пройдисвітів і 8 душогубів Пустелебродів, а потім повідомте про це головному інженеру Трюмосвисту в Пристроблях.", [4] = "Ну що, ти {стать:зміг:змогла} вигнати тих кочівників, як я просив? Пристробляхводоканал розробляє плани, що залежать від твоїх успіхів! Не підведи нас...", [5] = "Першокласна робота, {ім'я}... першокласна! Число кочівників скоротилося настільки, що ми можемо кинути їм виклик!\n\nТи вже {стать:поговорив:поговорила} з оператором крана Сіпаком? Він пропонує винагороду за будь-які бурдюки з водою Пустелебродів, які могли трапитися тобі в боях з кочівниками!", ["en"] = "More Wastewander Justice", ["tasks"] = { ["Wastewander Assassin"] = "душогуб Пустелебродів", ["Wastewander Assassin slain"] = "душогуб Пустелебродів: убито", ["Wastewander Rogue"] = "пройдисвіт Пустелебродів", ["Wastewander Rogue slain"] = "пройдисвіт Пустелебродів: убито", ["Wastewander Shadow Mage"] = "тіньовий маг Пустелебродів", ["Wastewander Shadow Mage slain"] = "тіньовий маг Пустелебродів: убито" } },
    [1692] = { [1] = "Коваль Матіель", [2] = "Я помістила зібраний тобою елуніт в ящик. Віднеси його ковалю Матіелю і він зробить для тебе елунітову зброю.\n\nТи знайдеш Матіеля з іншої сторони будівлі на півдні.", [3] = "Принесіть ящик елуніту до коваля Матіеля.", [4] = "ВІтаю, {стать:юний:юна} {клас:к}. Чим я можу тобі допомогти?", [5] = "А, елунітова руда. Це чудовий матеріал, благословенний самою богинею Елуною. Викувати елунітову зброю - це велика честь.\n\nПочекай, зараз я візьмусь за роботу...", ["en"] = "Smith Mathiel", ["tasks"] = { ["Case of Elunite"] = "ящик елуніту", ["Case of Elunite (Provided)"] = "ящик елуніту (видано)" } },
    [1693] = { [1] = "Елунітова зброя", [5] = "{ім'я}, я викував цю зброю з твого елуніту. Прошу, обирай свою.\n\nІ дуже тобі дякую. Працювати з елунітом не тільки легко - це велика честь.", ["en"] = "Weapons of Elunite" },
    [1698] = { [1] = "Йорус Ячміновар", [2] = "Йорус Ячміновар кинув виклик воїнам Альянсу. Він чекає в таверні Приозер'я, в Багрянокряжжі, і обіцяє гарну винагороду для всіх, хто впорається.", [3] = "Поговоріть з Йорусем Ячміноваром.", [5] = "Ха! Отже, ти {стать:чув:чула} про мій виклик, так?\n\nЩо ж, сідай і слухай уважно. Замов щось і насолоджуйся... як востаннє.", ["en"] = "Yorus Barleybrew" },
    [1699] = { [1] = "Ретбанський виклик", [2] = "Я називаю своє випробування Ретбанським викликом. Щоб пройти його, необхідно зайти в Ретбанські печери, дійти до першої розвилки і повернутись до мене. Раз плюнути! Та є нюанс...\n\nТи маєш повернутись за годину.\n\nА ще по дорозі ти зустрінеш купу гнолів.\n\nПеред початком, ти маєш хльобнути фірмового напою моєї сім'ї - Ячміноварсього Пекучого!\n\nТо що скажеш? Ретбанські печери знаходяться в горах на північ від Приозер'я. {стать:Готовий:Готова} до Ретбанського виклику?", [3] = "Зайдіть в Ретбанські печери, дістаньтесь до першої розвилки й поверніться до Йоруса Ячміновара за відведений час.\n\nВи не маєте помирати.", [4] = "Не гай часу, {ім'я}. На твоєму місці я б поспішив...", [5] = "Ти {стать:впорався:впоралась}! Молодець! Вип'ємо за твоє здоров'я!", ["en"] = "The Rethban Gauntlet", ["tasks"] = { ["Enter the Rethban Caverns"] = "Увійдіть до печер Ретбан", ["Explore Zone"] = "Дослідіть місцевість" } },
    [17] = { [1] = "В Ульдаман за реагентами", [2] = "Я чув про нещодавно відкриту рослину — гриб-малиновик. Вони ростуть цілими колоніями глибоко в розкопках Ульдамана. Певне, вони можуть рости ще десь, але поки мені відомо тільки про це місце. Я хочу вивчити можливості їх застосування в алхімії, і тут-то ти мені й знадобишся.\n\nВідшукай і принеси мені дюжину цих грибів. Але будь {стать:обережний:обережна} — від зайвих рухів вони можуть випустити отруйні спори.\n\nЯкщо виконаєш моє доручення — я приготую для тебе партію мого знаменитого відновлювального зілля!", [3] = "Принесіть 12 грибів-малиновиків Ґхаку Цілителю в Телсамар.", [4] = "Ти {стать:приніс:принесла} гриби-малиновики для моїх алхімічних досліджень? Немає грибів — немає нагороди!", [5] = "Чудово, {ім'я:к}, ти знову {стать:показав:показала} на що {стать:здатен:здатна}! Ці гриби будуть здорово корисними в дослідженнях, дуже корисними!\n\nА тепер, як я й обіцяв, ти можеш насолодитись одним з найкращих зіллів з моїх запасів...\n\nЯкщо ти добре знаєш алхімію, ми могли б обговорити ще одну справу. У всякому разі, дякую тобі за допомогу!", ["en"] = "Uldaman Reagent Run", ["tasks"] = { ["Magenta Fungus Cap"] = "гриб-малиновик", ["Magenta Fungus Cap (Provided)"] = "гриб-малиновик (видано)" } },
    [1701] = { [1] = "Загартований вогнем обладунок", [2] = "Отож, ти {стать:отримав:отримала} гарний щит, та це не все. Я знаю секрет виготовлення надзвичайно міцних обладунків. Це не просто та потребує рідкісних матеріалів, та якщо ти не проти трохи побігати - матимеш неймовірні обладунки.\n\nТо що, {ім'я}? Якщо хочеш зайнятись цим - я дам тобі список необхідних матеріалів з рекомендаціями по їх пошуку.", [3] = "Зберіть необхідні матеріали та принесіть їх Фьюрену Довгобороду в Штормовій.", [4] = "Як проходить збір, {ім'я}? Вже є щось?", [5] = "Ти все {стать:зібрав:зібрала}? Неймовірно! Я боявся, що ті химери тебе з'їдять!\n\nЩо ж, можна починати робити обладунки...", ["en"] = "Fire Hardened Mail", ["tasks"] = { ["Charred Horn"] = "обвуглений ріг", ["Charred Horn (Provided)"] = "обвуглений ріг (видано)", ["Galvanized Horn"] = "гальванізований ріг", ["Galvanized Horn (Provided)"] = "гальванізований ріг (видано)", ["Scorched Spider Fang"] = "обпалене павуче ікло", ["Scorched Spider Fang (Provided)"] = "обпалене павуче ікло (видано)", ["Vial of Phlogiston"] = "фіал флогістону", ["Vial of Phlogiston (Provided)"] = "фіал флогістону (видано)" } },
    [1702] = { [1] = "Щитник", [2] = "Впоравшись з випробуванням, ти {стать:показав:показала} на що {стать:здатен:здатна}, {ім'я}. А я тримаю слово. Ти отримаєш обіцяну винагороду...\n\nАле вона в Штормовії.\n\nПоговори з моїм приятелем, Фьюреном Довгобородом, у дворфійському районі Штормовію. Його щити відомі на весь світ, і він дещо винен мені.\n\nОсь, віднеси Фьюрену це барильце Ячміноварського Пекучого і попроси у нього щит. У нього знайдеться щось гарне.", [3] = "Віднесіть Фьюрену Довгобороду барильце пекучої бражки.", [4] = "Привіт! Жаркувато сьогодні, правда ж?", [5] = "Ах, Ячміноварське Пекуче. Гарний напій! Отож, ти від Йоруса, ге?\n\nБуде тобі щит, звісно! Кращого ніде не знайдеш!", ["en"] = "The Shieldsmith", ["tasks"] = { ["Cask of Scalder"] = "барильце пекучої бражки", ["Cask of Scalder (Provided)"] = "барильце пекучої бражки (видано)" } },
    [1705] = { [1] = "Палаюча кров", [2] = "Мені неприємно це визнавати, та схоже, що Фьюрен дійсно відкрив щось нове. Але щоб впевнитись в цьому, я маю випробувати його підхід на новому обладунку. Якщо ти допоможеш мені з матеріалами, {ім'я}, ти зможеш забрати його собі.\n\nЩоб зробити обладунок, мені знадобиться палаюча кров та палаючий камінь.\n\nЄдине місце, де їх можна добути — Смерколісся. Палаючу кров ти знайдеш у воргенів Ночегибелі, що живуть у шахті Погуби Роланда, а у їх лідера, Кишкодера, ти знайдеш камінь.\n\nНе зволікай, {ім'я}.", [3] = "Принесіть 20 фіалів палаючої крові та палаючий камінь Ґріманду Елмору в Штормовій.", [4] = "{ім'я}, кров і камінь у тебе? Без них я обладунок не зроблю.", [5] = "Чудово! А тепер перепрошую, мені треба працювати...", ["en"] = "Burning Blood", ["tasks"] = { ["Burning Blood"] = "палаюча кров", ["Burning Blood (Provided)"] = "палаюча кров (видано)", ["Burning Rock"] = "палаючий камінь", ["Burning Rock (Provided)"] = "палаючий камінь (видано)" } },
    [1706] = { [1] = "Обладунок Ґріманда", [5] = "Очам своїм не вірю! Підхід Фьюрена виявився вдалим і цей обладунок здатний витримати серйозні удари.\n\nТримай, {ім'я}. І величезне тобі спасибі. Якби ти не {стать:приніс:принесла} мені матеріали, я б так і не повірив у відкриття Фьюрена.", ["en"] = "Grimand's Armor" },
    [1707] = { [1] = "Винагорода за бурдюки з водою", [2] = "Вітаю, {ім'я}! Мене звати Сіпак, і у нас є для тебе важлива робота, якщо ти {стать:готовий:готова} до неї! Ура!\n\nЯ, як досвідчений оператор крана, найбільше хотів би взяти будь-які бурдюки з водою Пустелебродів, які ти можеш знайти у пустелі. Це все наша вода — кочівники її просто вкрали! Пристробляхводоканал пропонує в нагороду польовий набір за кожні п'ять бурдюків. Але що більш важливо — ти допоможеш Пристробляху!", [3] = "Принесіть 5 бурдюків з водою Пустелебродів оператору крана Сіпаку в Пристроблях.", [4] = "Ти {стать:приніс:принесла} п'ять бурдюків з водою Пустелебродів? Якщо так, то польовий набір Пристробляхводоканалу, модель 103-XB — твій!", [5] = "Чудово — чим більше бурдюків з водою ми зможемо повернути, тим далі ми всі будемо від катастрофи! Принось їх ще, і за кожні п'ять одиниць ти отримуватимеш по польовому набору.", ["en"] = "Water Pouch Bounty", ["tasks"] = { ["Wastewander Water Pouch"] = "бурдюк з водою Пустелебродів", ["Wastewander Water Pouch (Provided)"] = "бурдюк з водою Пустелебродів (видано)" } },
    [1708] = { [1] = "Залізний корал", [2] = "Я хочу випробувати підхід Фьюрена Довгоборода на моєму власному обладунку. І так як ти {стать:допоміг:допомогла} Фьюрену, а він допоміг мені - я дозволю тобі забрати його собі коли я закінчу!\n\nЩоб завершити обладунок, мені потрібен особливий корал - обпалюючий корал. Він росте лише в одному місці - вздовж берега на південь від гавані Менетілів, що в Заболотті.\n\nПринеси мені достатньо обпалюючого коралу і я відразу займусь обладунком. Поспіши, {ім'я}. У мене аж руки сверблять почати!", [3] = "Принесіть 20 обпалюючих коралів Клокморту Гайковерту в Залізогарт.", [4] = "Привіт-привіт, {ім'я}! Корали в тебе? Мені кортить взятися за роботу!", [5] = "Те, що треба! Чудова робота! Тепер дозволь мені зайнятись його обробкою і я зможу поєднати техніку Фьюрена з моєю власною.\n\nОх-ох! Я впевнений, що обладунок буде дуже-дуже крутий!", ["en"] = "Iron Coral", ["tasks"] = { ["Searing Coral"] = "обпалюючий корал", ["Searing Coral (Provided)"] = "обпалюючий корал (видано)" } },
    [1709] = { [1] = "Творіння Клокморта", [5] = "Ось твій обладунок, {ім'я}. Підхід Фьюрена спрацював бездоганно! Ідеально! Неймовірно, чесно!\n\nЙого можна переїхати облоговою машиною, та він не втратить свою форму!", ["en"] = "Klockmort's Creation" },
    [1710] = { [1] = "Випалені сонцем шкаралупи", [2] = "Мій колега, Фьюрен Довгобород, зробив відкриття, яке мені не терпиться перевірити. Я хочу випробувати його на новій броні, певно, методи Фьюрена покращать мої результати.\n\nТи мені допоможеш? Якщо збереш необхідні для виготовлення броні матеріали - я зроблю для тебе додатковий екземпляр.\n\nМені потрібна випалена сонцем яєчна шкаралупа виверн, які живуть у Високому Сідалі, в Тисячі Шипів. Ти знайдеш шкаралупу під їхніми гніздами. Як збереш достатньо - повертайся до мене.", [3] = "Принесіть 20 випалених сонцем шкаралуп Матіелю в Дарнас.", [4] = "Шкаралупи у тебе, {ім'я}? Вони досить міцні, тож я зроблю з них лак, яким покрию ланки нової кольчуги.", [5] = "Ах, дякую! Вони чудово підійдуть!\n\nЯ негайно почну робити обладунок...", ["en"] = "Sunscorched Shells", ["tasks"] = { ["Sunscorched Shell"] = "випалена сонцем шкаралупа", ["Sunscorched Shell (Provided)"] = "випалена сонцем шкаралупа (видано)" } },
    [1711] = { [1] = "Обладунок Матіеля", [5] = "Я завершив твій обладунок і я дуже задоволений. Нова техніка Фьюрена ідеально поєднується з моєю і я впевнений, що ця броня буде міцною.\n\nДякую, {ім'я}. І нехай він добре послужить тобі у майбутніх битвах.", ["en"] = "Mathiel's Armor" },
    [1712] = { [1] = "Циклоніан", [2] = "Я давно спостерігаю за цими місцями в очікуванні падіння Циклоніана. Але я ще не зустрів гідного героя, що зміг би його подолати.\n\nМожливо цим героєм будеш ти.\n\nДоведи, що ти — {стать:гідний:гідна} {клас:н}. Принеси мені предмети для виклику Циклоніана. Можливо, тобі вдасться перемогти його і добути серце вихору.\n\nЯкщо так станеться — я використаю силу серця для створення зброї для тебе.\n\nОсь пергамент зі списком всього необхідного.", [3] = "Принесіть предмети зі списку Бат'раху Вітрогляду в Альтерак.", [4] = "Предмети в тебе, {ім'я}? Збери їх і будеш {стать:готовий:готова} зустрітись з Циклоніаном.", [5] = "Ти {стать:зібрав:зібрала} всі необхідні предмети і {стать:довів:довела} свою силу і здібність. Але далі буде складніше.\n\nБудемо сподіватись, що твої сили не підведуть.", ["en"] = "Cyclonian", ["tasks"] = { ["Bloodscalp Tusk"] = "ікло Кровоскальпого", ["Bloodscalp Tusk (Provided)"] = "ікло Кровоскальпого (видано)", ["Essence of the Exile"] = "сутність вигнанця", ["Essence of the Exile (Provided)"] = "сутність вигнанця (видано)", ["Liferoot"] = "життєкорінь", ["Liferoot (Provided)"] = "життєкорінь (видано)" } },
    [1713] = { [1] = "Виклик", [2] = "Я готовий провести ритуал виклику Циклоніана. Коли він з'явиться, ти маєш перемогти його і забрати його серце вихору. Його я використаю, щоб зачарувати зброю силою Циклоніана.\n\n{ім'я}, ти {стать:готовий:готова} зустрітись з володарем вітру?", [3] = "Принесіть серце вихору Бат'раху Вітрогляду.", [4] = "{ім'я}, мені потрібне серце вихору!", [5] = "Тобі вдалось! Ти {стать:переміг:перемогла} Циклоніана і {стать:добув:добула} серце вихору!", ["en"] = "The Summoning", ["tasks"] = { ["Whirlwind Heart"] = "серце вихору", ["Whirlwind Heart (Provided)"] = "серце вихору (видано)" } },
    [1714] = { [1] = "Сутність вигнанця", [4] = "Казан булькає, манячи випарами...", [5] = "Обереги повільно опускаються на дно казана...\n\nВелика бульбашка підійматися на поверхню і лускає...\n\n...вивільняючи розплавлений кам'яний талісман.", ["en"] = "Essence of the Exile", ["tasks"] = { ["Burning Charm"] = "палаючий оберіг", ["Burning Charm (Provided)"] = "палаючий оберіг (видано)", ["Cresting Charm"] = "бурунистий оберіг", ["Cresting Charm (Provided)"] = "бурунистий оберіг (видано)", ["Thundering Charm"] = "буревійний оберіг", ["Thundering Charm (Provided)"] = "буревійний оберіг (видано)" } },
    [1715] = { [1] = "Зарізане ягня", [2] = "Хмм. Колись всі чорнокнижники Каз-Модану навчалися під егідою майстрів Гномреґану, але зараз, коли нас всіх змусили переїхати у цю діру в Залізогарті, а Маґні пильно стежить за нами, ми змушені відправляти наших новачків на навчання в Штормовій.\n\nНа щастя, Ґакін не злякався цих змін, ти все одно вивчиш те що {стать:повинен:повинна} знати, але моя кров кипить від цього всього!\n\nТак чи інакше, Ґакін знаходиться в підвалі \"Зарізаного ягняти\" в Штормовії.", [3] = "Поговоріть з Ґакіном Темнопрядом у кварталі Магів Штормовію.", [5] = "Тебе прислав Чорноключ, чи не так? Кляті чорнокнижники Залізогарта повинні вирішити свої проблеми. У Штормовії не так багато кімнат і вчителів. З таким напливом учнів ми рано чи пізно привернемо до себе увагу.", ["en"] = "The Slaughtered Lamb" },
    [1716] = { [1] = "Пожирачка душ", [2] = "Сайаади — це пожирачі душ, що пригнічують волю і вводять у спокусу. Породження чистого зла. Цих демонів також називають суккубами, якщо йдеться про жінок, та інкубами, якщо це чоловіки. Щоб викликати та підкорити такого демона, тобі знадобиться приманка — символ кохання. Однак, буде важко знайти щось подібне. Тобі слід поговорити з Такаром Провидцем. Ти знайдеш його в Степах, біля табору Таурахо.", [3] = "Поговоріть з Такаром Провидцем у Степах.", [5] = "Як твоя подорож, {ім'я}? Ти {стать:подолав:подолала} довгий шлях, щоб поговорити зі мною. Але не хвилюйся, я знаю, чому тебе послав Ґакін, і це було мудро з його боку, бо я можу допомогти тобі у твоїх пошуках.", ["en"] = "Devourer of Souls" },
    [1717] = { [1] = "Виклик Ґакіна", [2] = "{ім'я}! Не очікував побачити тебе в цих краях, але мені доручили наглядати за тобою.\n\nТи давно не {тренувався:свій:тренувалася}, тож заглянь до Ґакіна, коли наступного разу будеш у Штормовії. Він чекатиме на тебе.", [3] = "Поговоріть з Ґакіном Темнопрядом у кварталі Магів Штормовію.", [5] = "Я радий, що хоча б хтось зміг зв'язатися з тобою, {ім'я}. Я почав боятися найгіршого. Було б шкода втратити тебе після всього часу та зусиль, які ми в тебе вклали.\n\nМи поговоримо пізніше. Твоє навчання — єдине, що має значення зараз.", ["en"] = "Gakin's Summons" },
    [1718] = { [1] = "Остров'янин", [2] = "Ти стаєш {стать:славетним:славетною} {клас:о}, {ім'я:к}. Настав час позмагатись з твоїми побратимами по зброї.\n\nНеподалік від узбережжя Степів, на південь від Брашпиля, є острів. Це острів Битв, на якому збираються воїни.\n\nЗбираються і змагаються.\n\nПоговори зі старшим воїном острова, Кланноком Маклеодом. Він допоможе тобі на твоєму шляху {клас:р}, якщо вирішить, що ти {стать:готовий:готова}.\n\nДо острова Битв можна дістатися по піщаній мілині, що вздовж узбережжя Торгівця.", [3] = "Поговоріть з Кланноком Маклеодом.", [5] = "Привіт, {клас:к}. Добре, що ти {стать:дістався:дісталася} до острова Битв. Сподіваюсь, тобі тут сподобається...", ["en"] = "The Islander" },
    [1719] = { [1] = "Побоїще", [2] = "Якщо хочеш навчатись в мене, спершу ти маєш пройти випробування - Побоїще. Через нього проходять всі молоді воїни, які хочуть довести свою велич.\n\nЩоб почати - пройди через натовп та стань на решітку. Твіґґі Пласкоголов зрозуміє, що ти {стать:готовий:готова} і покличе твоїх суперників.\n\nПереможеш їх всіх - і проти тебе вийде здоровань Вілл. Вбий його і повертайся до мене.", [3] = "Вбийте здорованя Вілла та поговоріть з Кланноком Маклеодом на острові Битв.", [4] = "Ти {стать:впорався:впоралась} з випробуванням?", [5] = "Чудово, {ім'я}. Ти {стать:пройшов:пройшла} випробування Побоїщем!\n\nТи {стать:достойний:достойна} {клас} і я з радістю навчатиму тебе.", ["en"] = "The Affray", ["tasks"] = { ["Big Will"] = "здоровань Вілл", ["Big Will slain"] = "здоровань Вілл: убито" } },
    [1739] = { [1] = "Зв'язування", [2] = "За допомогою серцедерева ти зможеш накласти заклинання на коло виклику у підвалі та відкрити портал, щоб викликати сукуба в наш світ.\n\nБудь {стать:обережний:обережна}, {ім'я}, сукуби можуть заволодіти навіть найсильнішими розумами.\n\nЯкщо ти здолаєш її та відправиш назад у безодню, повертайся до мене, і я покажу тобі, як викликати та керувати нею.", [3] = "За допомогою серцевини серцедерева підкоріть сукуба, а потім поверніть серцевину Ґакіну Темнопряду в підвал таверни \"Зарізане ягня\".", [4] = "Іноді я думаю, чи не була Сурена переодягненою сукубою, посланою, щоб викривити та перекрутити мою свідомість... Ха! Думаю, я їй надто багато приписую..", [5] = "Відмінно, відмінно, {ім'я}. Бачу, що ми зробили правильний вибір, навчаючи тебе. Твоя робота, безумовно, не розчаровує.\n\nЯ покажу, як контролювати твою щойно зв'язаного сукуба. Спостерігай уважно.", ["en"] = "The Binding", ["tasks"] = { ["Summoned Succubus"] = "викликаний сукуб", ["Summoned Succubus slain"] = "викликаний сукуб: убито" } },
    [1740] = { [1] = "Сфера Соран'рука", [2] = "Коли демони Легіону втрачають прихильність, їх дух ув'язнюється у сфери, які роздають магам та чорнокнижникам.\n\nБагато цих сфер носили їх слуги в Азероті. Навіть розколоті на частини, вони все ще зберігають силу демонів, ув'язнених всередині.\n\nСферу Соран'рука розбили на дві частини: одну з них подрібнили на три, щоб їх використовували слуги Сутінкового Молота у Чорноводних глибинах, а іншою, більшою частиною, володіє чаклун у фортеці Тіньового Ікла. Знайди їх і я зможу знову зібрати цю сферу.", [3] = "Знайдіть 3 фрагменти Соран'рука та 1 великий фрагмент Соран'рука та принесіть їх Доану Каргану в Степи.", [4] = "Мені знадобилося багато років, щоб зібрати шматочки сфери Зарґейна, натомість вона добре послужила мені, як служитиме тобі сфера Соран'рука.", [5] = "Так... Ця сфера не сильно пошкоджена, і майже всі шматочки тут. Відновити її, щоб знову зробити Соран'рука єдиним цілим — справа нескладна.\n\nЯ присвятив своє життя вивченню сфер Палаючого Легіону та їх відновленню. Ти {стать:зробив:зробила} мені велику послугу, збираючи ці частини для вивчення, і я поверну їх тобі — повністю відновлені — у формі, яку ти обереш.", ["en"] = "The Orb of Soran'ruk", ["tasks"] = { ["Large Soran'ruk Fragment"] = "великий фрагмент Соран'рука", ["Large Soran'ruk Fragment (Provided)"] = "великий фрагмент Соран'рука (видано)", ["Soran'ruk Fragment"] = "фрагмент Соран'рука", ["Soran'ruk Fragment (Provided)"] = "фрагмент Соран'рука (видано)" } },
    [1758] = { [1] = "Фоліант змови", [2] = "Для того, щоб викликати скверногончу на бій, тобі знадобиться більше, ніж просто коло виклику.\n\nМої три послідовники і я допоможемо тобі створити магічні кола. Тобі потрібна копія давно втраченого фоліанта змови. Він був написаний групою чорнокнижників, які змогли вперше викликати скверногончу.\n\nМожливо, Кром Міцнорук зможе допомогти. Нині мандрівний чорнокнижник, він проводить свої дні, збираючи стародавні тексти та нишпорячи по бібліотеці в Залізогарті.", [3] = "Поговоріть з Кромом Міцноруком в Залізогарті.", [5] = "Фоліант змови? Хмм... звучить знайомо. Я його тут раніше не бачив, і повір мені, я пам'ятаю кожну книгу, яку я читав.\n\nХмм...\n\nЗвісно! Я бачив посилання на нього в каталогах бібліотеки.", ["en"] = "Tome of the Cabal" },
    [178] = { [1] = "Доручення Теокріта", [2] = "<Ви чуєте безтілесний голос...>\n\nНе лякайся. Я Теокріт, верховний маг вежі Азори, що в Ельвиннському лісі. За допомогою цієї підвіски тінешкурі гноли спілкуються зі своїм повелителем Морґантом.\n\nЯ витратив багато часу, щоб теж навчитися спілкуватися за допомогою цих підвісок. Якщо ти чуєш моє повідомлення, значить, моє заклинання спрацювало.\n\nПринеси мені цю підвіску, і я щедро винагороджу тебе.", [3] = "Принесіть тьмяну підвіску Тінешкурих магові Теокріту.", [4] = "Кажеш, що я розмовляв з тобою через підвіску? Хм... Я маю її вивчити, дай-но її сюди.", [5] = "Дякую тобі, {ім'я}. Я розіслав це повідомлення по підвісках Тінешкурих кілька тижнів тому і вважав, що заклинання не спрацювало. Але, здається, зрештою воно дійшло до деяких з них, хоч і зі значним запізненням.\n\nЗ часом я сподіваюся навчитися посилати таким чином бойові заклинання та знерухомлювати тінешкурих гноллів, які носять ці підвіски.\n\nАле перш ніж я зможу це зробити, потрібно провести ще багато досліджень.", ["en"] = "Theocritus' Retrieval", ["tasks"] = { ["Faded Shadowhide Pendant"] = "тьмяна підвіска Тінешкурих", ["Faded Shadowhide Pendant (Provided)"] = "тьмяна підвіска Тінешкурих (видано)" } },
    [1782] = { [1] = "Обладунок Фьюрена", [5] = "Ось твій обладунок, {ім'я}. Він витримає будь-який удар, клянусь ім'ям Фьюрена Довгоборода!\n\nА ще я дякую тобі. Я багато чому навчився, працюючи з цими матеріалами. Думаю, скоро я зроблю щось нове!\n\nЯ поділюсь своїми відкриттями з іншими ковалями Альянсу.\n\nЗвісно, я й про тебе згадаю. Може, вони захочуть тобі віддячити.", ["en"] = "Furen's Armor" },
    [1791] = { [1] = "Вітрогляд", [2] = "Тепер, коли ти знаєш стійку берсерка, тобі знадобиться гарна зброя.\n\nПоговори Бат'рахом Вітроглядом, тролем-самітником, що живе між Альтерацькими горами та Західними Зачумленими землями. Він умілий майстер зброї та могутній шаман.\n\nЩоб знайти Бат'раха - йди по річці, що тече на схід від Тарренського Млину. Йди на північ - Бат'рах живе серед руїн на березі річки.", [3] = "Поговоріть з Бат'рахом Вітроглядом", [5] = "Ти {стать:прийшов:прийшла} здалеку, {стать:молодий:молода} {клас:к}. Шукаєш потужну зброю, еге ж?\n\nЯ можу допомогти тобі з цим. А ти натомість допоможеш мені.", ["en"] = "The Windwatcher" },
    [1792] = { [1] = "Зброя вихору", [5] = "Нарешті в нас є серце вихору і я можу помістити його у вмістилище на твій вибір.\n\nОбери собі зброю, {ім'я}, і пам'ятай, що це - сила Циклоніана.", ["en"] = "Whirlwind Weapon" },
    [1793] = { [1] = "Фоліант доблесті", [5] = "Ти вже {стать:довів:довела}, що Світло оберігає тебе. Та часи нині важкі, тому важливо знати, яка сила ховається в тобі. Коли демони, дракони та інші злі створіння прийдуть на наші землі — прийде час випробовування твого духу. Та чи вистачить тобі сил?\n\nХоробрість для паладина не менш важлива за його зброю, обладунки та Світло. Захист слабких та непохитність віри — це ще кілька речей, які ти засвоїш під час свого навчання в соборі Світла.", ["en"] = "The Tome of Valor" },
    [1794] = { [1] = "Фоліант доблесті", [5] = "Ти вже {стать:довів:довела}, що Світло оберігає тебе. Та часи нині важкі, тому важливо знати, яка сила ховається в тобі. Коли демони, дракони та інші злі створіння прийдуть на наші землі — прийде час випробовування твого духу. Та чи вистачить тобі сил?\n\nХоробрість для паладина не менш важлива за його зброю, обладунки та Світло. Захист слабких та непохитність віри — це ще кілька речей, які ти засвоїш під час свого навчання в соборі Світла.", ["en"] = "The Tome of Valor" },
    [1795] = { [1] = "Зв'язування", [2] = "Якщо ти достатньо {стать:підготувався:підготувалася}, то ми можемо розпочинати. Дозволь мені пояснити тобі план.\n\nЯ створю базовий круг виклику. Після цього мої помічники використають жезли для створення більшого кола.\n\nПісля цього прочитай заклинання з фоліанта Змови, і відбудеться виклик скверногончої. Будь {стать:обережним:обережною}, {ім'я}. Скверногонча — це сильний ворог, і я б хотів бачити, як ти збережеш свою голову на плечах.", [3] = "За допомогою фоліанта Змови підкоріть скверногончу, а потім поверніть фоліант Страгаду Фарсану в Брашпиль.", [4] = "{стать:Кожен:Кожна} {клас} {стать:повинен:повинна} мати у своєму розпорядженні скверногончу. Хоча її важко приручити, та сила, яку він приносить своєму господареві, набагато перевищує ціну.", [5] = "Мушу визнати, {ім'я}, я вражений. Коли я зіткнувся зі своєю скверногончою, я ледь зберіг своє життя. Я відчуваю, що у тебе є потенціал стати {стать:одним:однією} з наймогутніших {стать:чорнокнижників:чорнокнижниць} цієї ери.", ["en"] = "The Binding", ["tasks"] = { ["Summoned Felhunter"] = "викликана скверногонча", ["Summoned Felhunter slain"] = "викликана скверногонча: убито", ["Tome of the Cabal"] = "Фоліант Змови", ["Tome of the Cabal (Provided)"] = "Фоліант Змови (видано)" } },
    [1796] = { [1] = "Матеріали для золотої кровомантії", [2] = "Перший предмет, який я допоможу тобі створити — мантію. Ти збереш для мене необхідні предмети, і ми складемо їх разом. Якщо ти успішно впораєшся з цим завданням, то отримаєш перший з багатьох предметів, які зроблять тебе потужніше і допоможуть тобі у твоїй боротьбі.\n\nЩоб почати, тобі потрібно мати мантію аркани. Цю мантію може зшити кравець, або ти можеш придбати її в когось іншого — я була б дуже вражена, якби ти {стать:зробив:зробила} її {стать:сам:сама} — але в будь-якому випадку для початку принеси мені мантію.", [3] = "Принесіть мантію аркани до Менари Пустоплестої в Степи.", [4] = "Є успіхи в пошуку мантії, {ім'я}? Ти створиш її самостійно? Коли робиш щось {стать:сам:сама}, приємніше наповнювати цей предмет магією. Отримуєш більше задоволення. Але я зрозумію, якщо ти обереш простіший шлях і замовиш її у когось — така... цілеспрямованість також має свої переваги.", [5] = "Це те, що потрібно, {ім'я}.\n\nВ основі всіх чарівних предметів має лежати річ високої якості. Чим більше зусиль та майстерності вкладено в предмет, тим більші магічні властивості він може мати. Рідкісні та дорожчі компоненти краще утримують магію. Ти не пошкодуєш, що {стать:віддав:віддала} мені цю мантію — коли ми закінчимо, ти отримаєш набагато кращу.", ["en"] = "Components for the Enchanted Gold Bloodrobe", ["tasks"] = { ["Robes of Arcana"] = "мантія аркани", ["Robes of Arcana (Provided)"] = "мантія аркани (видано)" } },
    [1798] = { [1] = "У пошуках Страгада", [2] = "Пора тобі навчитися викликати скверногончу, {ім'я}. У мене немає необхідних реагентів та предметів, щоб навчити тебе тут, тому тобі доведеться звернутися до іншого чорнокнижника — Страгада Фарсана, ще одного з нашого найближчого оточення.\n\nВін проживає в гоблінському порту, Брашпилі. Я попереджу його про твій прихід.", [3] = "Поговоріть зі Страгадом Фарсаном в Степах.", [5] = "{ім'я}? Ах, звичайно. Наша нова обдарованість. Реальність зазвичай не відповідає легенді, на жаль.\n\nНеважливо, ти {стать:прийшов:прийшла} сюди, щоб вчитися, а не слухати, як я жартую сам з собою.", ["en"] = "Seeking Strahad" },
    [1799] = { [1] = "Фрагменти сфери Орагіла", [2] = "Чудово, тоді ми можемо починати.\n\nСпочатку тобі потрібно поговорити з моїми послідовниками всередині вежі. Обери один зі шляхів, які вони запропонують.\n\nПотім тобі потрібно відправитися до Спустошища та знайти сферу пекельника в одного з чорнокнижників в руїнах Маннорок. Цю сферу тобі потрібно очистити за допомогою магині, на ім'я Табета, яка проживає на південному заході Бруднопилкої трясовини. Вона допоможе тобі заради мене.\n\nЗнову ж таки, не повертайся, поки не виконаєш обидва завдання.", [3] = "Поговоріть з послідовниками Менари у вежі над Брашпилем, та оберіть свій шлях.\n\nПісля цього принесіть сферу пекельника до Табети в Бруднопилку трясовину.", [4] = "Очевидно, ти не {стать:маг:магиня}, тож я запитую себе, чи можна взагалі тобі довіряти. Я відчуваю в тобі силу арканічної магії, але, здається, ти {стать:уникнув:уникнула} смороду скверни, яка так часто заволодіває твоїми побратимами.\n\nТак, {клас}... {клас} {стать:звернувся:звернулася} до мене за допомогою.\n\nОтож, що я можу зробити для тебе, {ім'я}?", [5] = "Отже, тебе послала Менара. Добре... Я припускаю, що ти можеш залишитися на деякий час. Але в тебе, напевне, дуже важлива справа — можливо, ти тут, щоб знайти втрачену силу? Можливо, я помилилась. Можливо, скверна вже й не так далеко від тебе.", ["en"] = "Fragments of the Orb of Orahil", ["tasks"] = { ["Infernal Orb"] = "сфера пекельника", ["Infernal Orb (Provided)"] = "сфера пекельника (видано)" } },
    [1800] = { [1] = "Тронний зал Лордерона", [2] = "Опікунки у притулку розповідають вночі історії про битви та легенди, якщо ми були слухняними й виконували свої обов'язки. Одна з історій розповідала про падіння Лордерона і про те, як злий Артас вбив свого власного батька, щоб стати правителем.\n\nУ нього не було честі, {ім'я}! Коли я виросту і стану сильним воїном Орди, моє лезо буде кероване честю — і ніяк не злом!\n\nПокажеш мені тронний зал, будь ласка? Він знаходиться прямо перед спуском в Підмістя.", [3] = "Відведіть свого підопічного до старої тронної зали Лордерона, що знаходиться перед спуском у Підмістя.", [4] = "Ми вже прийшли?", [5] = "Тронний зал такий страшний, {ім'я}! Хоч він і порожній, але я відчував, що там сталося велике зло. Я відчував гнів... а ще сум. Я розумію, чому опікунки розповідають нам такі історії. Я ніколи не зраджу так свій народ!\n\nДякую, що {стать:відвів:відвела} мене до тронного залу, {ім'я}. Я багато чому навчився.", ["en"] = "Lordaeron Throne Room", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Go to the old Lordaeron Throne Room that lies just before descending into the Undercity."] = "Ідіть до старої Тронної зали Лордерона, яка знаходиться безпосередньо перед спуском у Підмісто." } },
    [1801] = { [1] = "Фоліант змови", [2] = "Для того, щоб викликати скверногончу на бій, тобі знадобиться більше, ніж просто коло виклику.\n\nМої три послідовники і я допоможемо тобі створити магічні кола. Тобі потрібна копія давно втраченого фоліанта змови. Він був написаний групою чорнокнижників, які змогли вперше викликати скверногончу.\n\nМожливо, Джорах Аннісон зможе допомогти. Зараз він працює картографом в Підмісті, але все ще знає більше стародавніх текстів, ніж будь-хто з моїх знайомих.", [3] = "Поговоріть з Джорахом Аннісоном в Підмісті.", [5] = "Картографія! Картинки далекі від реальності. Вони мені не потрібні.\n\nУ книгах, в повістях, в описах! Там істина лежить. Я б обміняв усі мапи в цьому магазині на одну книгу про зародження некромантії або історію про тріумф Темної Леді.", ["en"] = "Tome of the Cabal" },
    [1802] = { [1] = "Фоліант змови", [2] = "Він втрачений, але є здогадка, де можна спробувати його пошукати.\n\nЗ нього зробили тільки одну копію і вона колись зазнала вандалізму: більшість книги була вирвана з палітурки. Ходять чутки, що вона якимось чином потрапила до рук одного кентавра із Тисячі Шипів.\n\nРешта була загублена на узбережжі на захід Південнобережжя, звідки її мали доставити човном до гавані Менетілів. Але вона туди не прибула.\n\nВ обмін на цю інформацію, я прошу тебе, якщо ти її знайдеш — принеси мені, щоб я зміг її переглянути.", [3] = "Поверніть запліснявілий фоліант і пошарпаний манускрипт Крому Міцноруку в Залізогарт.", [4] = "То чутки підтвердилися, {ім'я}?", [5] = "Неймовірно! Тепер я можу бути одним з тих небагатьох, хто бачив його зміст.\n\nЯ не можу дочекатися, коли зможу прочитати цей текст далі. Це великий день, {ім'я}! Якщо ти дозволиш мені, я з радістю перегляну його, перш ніж ти підеш. Я впевнений, що Страгад згодиться надіслати мені копію.", ["en"] = "Tome of the Cabal", ["tasks"] = { ["Moldy Tome"] = "запліснявілий фоліант", ["Moldy Tome (Provided)"] = "запліснявілий фоліант (видано)", ["Tattered Manuscript"] = "пошарпаний манускрипт", ["Tattered Manuscript (Provided)"] = "пошарпаний манускрипт (видано)" } },
    [1803] = { [1] = "Фоліант змови", [2] = "А! Бачу, що ти також {стать:чорнокнижник:чорнокнижниця} із подібними смаками до моїх. Дійсно, отримати фоліант Змови — це гідне прагнення. Чи {стать:знав:знала} ти, що колись він зберігався в стінах Лордерона? Однак його зіпсували, майже половина сторінок вирвана. Хто міг скоїти такий ганебний вчинок?\n\nОтже, половина тексту втрачена, ходять чутки, ніби вона потрапила до рук кентаврів із Тисячі Шипів.\n\nРешта тексту мала бути перевезена до Залізогарту, але була втрачена на узбережжі на захід від Південнобережжя.", [3] = "Поверніть запліснявілий фоліант і пошарпаний манускрипт Джораху Аннісону в Підмістя.", [4] = "Можливо, ти й віриш у казку, {ім'я}, але навіть в найсміливіших чутках можна знайти частку правди.", [5] = "Так-так-так! Що це ти {стать:приніс:принесла}?\n\nЦе неймовірно, {ім'я}. Я б не подумав, що це можливо, але ось він в моїх руках — цілий екземпляр фоліанта Змови.\n\nДозволь мені погортати його сторінки, хоча б на мить, перш ніж ти знову вирушиш в дорогу.", ["en"] = "Tome of the Cabal", ["tasks"] = { ["Moldy Tome"] = "запліснявілий фоліант", ["Moldy Tome (Provided)"] = "запліснявілий фоліант (видано)", ["Tattered Manuscript"] = "пошарпаний манускрипт", ["Tattered Manuscript (Provided)"] = "пошарпаний манускрипт (видано)" } },
    [1804] = { [1] = "Фоліант змови", [2] = "Як же не хочеться випускати його з рук! Але ти його {стать:знайшов:знайшла} і, звичайно ж, здійсниш з його допомогою куди важливіші справи. Тільки, будь ласка, нагадай Страгаду, що я хочу отримати копію.\n\nДо речі, про нього, він прислав мені звістку, поки тебе не було. Він просив передати тобі, що для його помічників, які допоможуть з викликом ти {стать:повинен:повинна} дістати три жезли виклику.\n\nВін може не знати, де їх знайти, але я знаю! Вони востаннє використовувалися орками з клану Драконової Пащі в Заболотті. Я б пошукав у їхніх чаклунів!", [3] = "Принесіть відновлений фоліант і 3 жезли виклику Страгаду Фарсану в Брашпиль.", [4] = "Давненько я тебе тут не бачив. Ти {стать:знайшов:знайшла} фоліант і жезли?", [5] = "Чудово робота! Фоліант виклику і три бездоганних... може, трохи подряпаних... жезлів виклику.\n\nЦе буде цікаво. Вже давно не було {стать:молодого:молодої} {клас:р}, що {стать:вирішив:вирішила} завести свою власну скверногончу.", ["en"] = "Tome of the Cabal", ["tasks"] = { ["Reconstructed Tome"] = "відновлений фоліант", ["Reconstructed Tome (Provided)"] = "відновлений фоліант (видано)", ["Rod of Channeling"] = "жезл виклику", ["Rod of Channeling (Provided)"] = "жезл виклику (видано)" } },
    [1805] = { [1] = "Фоліант змови", [2] = "Це один з найцікавіших текстів, які я читав за останні кілька років. Вибір тут дещо обмежений — переважно книги по географії — і я вже прочитав їх усі. Я сподіваюся, що Страгад надішле мені копію цього фоліанту, коли матиме можливість.\n\nДо речі, про нього, він прислав мені звістку, поки тебе не було. Для свого завдання ти {стать:повинен:повинна} дістати три жезли виклику.\n\nЯкщо дозволиш мені почитати фоліант, я розкрию тобі секрет: ти зможеш знайти жезли в орків з клану Драконової Пащі в Заболотті.", [3] = "Принесіть відновлений фоліант і 3 жезли виклику Страгаду Фарсану в Брашпиль.", [4] = "Так, {ім'я}? Чим я можу тобі послужити?", [5] = "Чудово робота! Фоліант виклику і три бездоганних... може, трохи подряпаних... жезлів виклику.\n\nЦе буде цікаво. Вже давно не було {стать:молодого:молодої} {клас:р}, що {стать:вирішив:вирішила} завести свою власну скверногончу.", ["en"] = "Tome of the Cabal", ["tasks"] = { ["Reconstructed Tome"] = "відновлений фоліант", ["Reconstructed Tome (Provided)"] = "відновлений фоліант (видано)", ["Rod of Channeling"] = "жезл виклику", ["Rod of Channeling (Provided)"] = "жезл виклику (видано)" } },
    [1806] = { [1] = "Випробування праведності", [2] = "Чом би нам прямо зараз не піти до кузні й розпочати роботу? Я чекав тебе і вже приготувався, тож це не займе багато часу.\n\nКоли ми закінчимо, ти будеш значно краще {стать:підготовлений:підготовлена} до захисту Світла, це я тобі обіцяю.\n\nБуду відвертим, {ім'я:к}, я трохи заздрю тобі, коли бачу результати твоїх діянь. Але розуміння того, що я внесу свій внесок у твої пригоди, робить мене щасливим.", [3] = "Почекайте поки Джордан Стілвелл закінчить виковувати зброю.", [5] = "Ось вона, {ім'я:к}. Зброя, гідна {стать:такого захисника:такої захисниці} Світла, як ти. Я назвав її в честь великого дворфа-паладина, що був мені другом. Його звали Веріґан... Бош Веріґан. Прошу, прийми це на знак вдячності від мене та моєї дружини. Ми в великому боргу перед тобою. Світ буде в безпеці, поки його захищають такі, як ти.", ["en"] = "The Test of Righteousness" },
    [1818] = { [1] = "Розмова з Діллінджером", [2] = "Мені тут сказали, що у смертестража Діллінджера є робота для тебе. Якщо хочеш довести свою цінність Темній Леді - негайно поговри з Діллінджером.\n\nСмертестраж Діллінджер стоїть на посту на західній околиці Брілля, біля кладовища.", [3] = "Поговоріть зі смертестражем Діллінджером в Бріллі.", [5] = "Ти тут за завданням? Чудово. У мене є тут одне для тебе. Заодно і покажеш свої навички в бою... і свою рішучість захищати відречених.", ["en"] = "Speak with Dillinger" },
    [1819] = { [1] = "Улаґ-Колун", [2] = "Коли воїни Скари наводнили Тірісфальське перелісся, нам вдалось схопити одного з них для вивчення. Він мав свідомість і називав себе Улаґом-Колуном. Та не дивлячись на це, він все ще був поневолений Королем-лічем.\n\nМи сподівались знайти спосіб розірвати цей зв'язок та зазнали невдачі. Що ж, прийшов час звільнити його.\n\nЗвільни його і вбий.\n\nАктивуй перемикач біля мавзолею на півночі. Він зніме з Улаґа магічну печатку, що стримує його.\n\nНехай щастить, {ім'я}.", [3] = "Вбийте Улаґа-Колуна, після чого поговоріть зі смертестражем Діллінджером.", [4] = "Ти не {стать:закінчив:закінчила} справу, {ім'я}. Не личить {клас:д} проявляти страх...", [5] = "Чудова робота, {ім'я}. Улаґ був важливим слугою Скари. Ти {стать:довів:довела} смертестражам, що ти {стать:досвідчений і вірний:досвідчена і вірна} {клас} і заслуговуєш надалі служити Темній Леді.", ["en"] = "Ulag the Cleaver", ["tasks"] = { ["Ulag the Cleaver"] = "Улаґ-Колун", ["Ulag the Cleaver slain"] = "Улаґ-Колун: убито" } },
    [1820] = { [1] = "Розмова з Коулменом", [2] = "Ти {стать:довів:довела} свою цінність Темній Леді й тепер можеш послужити одному з її підданих.\n\nКоулмен Фартинг шукає {клас:з}, що буде гідним знаряддям помсти ворогам відречених.\n\nТи знайдеш його в таверні «Край шибениці» у східному Бріллі.", [3] = "Поговоріть з Коулменом Фартингом.", [5] = "Так, все правильно. Мені потрібні твої бойові навички. Велику плату не обіцяю, але ти допоможеш не тільки мені, а й справі відречених. Справишся - і матимеш гідне визнання.", ["en"] = "Speak with Coleman" },
    [1823] = { [1] = "Розмова з Руґою", [2] = "Ти здобуваєш все більше досвіду й слави, {клас:к}. Думаю, ти {стать:готовий:готова} до випробування Руґи Тотему Люті. Ти знайдеш його в таборі Таурахо в Степах.\n\nВін чекає на воїнів, які приймуть його виклик.", [3] = "Поговоріть з Руґою Тотемом Люті.", [5] = "Ти {стать:прийшов:прийшла} за випробуванням, {ім'я}?", ["en"] = "Speak with Ruga" },
    [1824] = { [1] = "Випроба на Полі велетнів", [2] = "Щоб пройти моє випробування, ти маєш йти на Поле велетнів, що на півдні. Там ти знайдеш купу створінь, схожих на комах. Вони з'явились в Степах недавно і я маю погане передчуття щодо них.\n\nМені потрібні їх вусики, {ім'я}. Відділені від комахи, вони будуть деякий час смикатись. Щоб пройти моє випробування, ти маєш принести мені їх до того, як вони завмруть.", [3] = "Принесіть 5 судомних вусиків Руґі Тотуму Люті в табір Таурахо.", [4] = "Ти {стать:приніс:принесла} вусики? Якщо так, то давай їх сюди скоріше. Вони довго смикатись не будуть...", [5] = "Чудово, {ім'я}! Пройшовши моє випробування, ти добре {стать:просунувся:просунулась} по шляху {клас:р}.", ["en"] = "Trial at the Field of Giants", ["tasks"] = { ["Twitching Antenna"] = "судомний вусик", ["Twitching Antenna (Provided)"] = "судомний вусик (видано)" } },
    [1825] = { [1] = "Розмова з Тун'ґрімом", [2] = "Тун'ґрім Вогнегляд, знаменитий коваль орків, дізнався про твою віддану службу Орді. Він хоче виготовити для тебе гідний обладунок, тож тобі варто зустрітися з ним якомога скоріше.\n\nТун'ґрім живе в горах на схід від Перехрестя.", [3] = "Поговоріть з Тун'ґрімом Вогнеглядом в Степах.", [5] = "Так, ти {стать:прийшов:прийшла}. Це добре, нам є що обговорити.", ["en"] = "Speak with Thun'grim" },
    [1838] = { [1] = "Броня жорстокості", [2] = "Я чув про твою силу та доблесть і хочу виготовити для тебе гідний обладунок, що буде оберігати тебе у твоїх діяннях.\n\nОднак створення цього обладунку вимагатиме від тебе зусиль, {ім'я}. Мені знадобиться твоя допомога і допомога інших ковалів Орди.\n\nОсь, візьми цей сувій. Я складав цей список багато ночей, вдивляючись в пергамент ледь зрячими очима. Принеси мені всі матеріали зі списку і я створю першу частину твого обладунку.", [3] = "Принесіть Тун'ґріму Вогнегляду 15 злитків димчастого заліза, 10 одиниць молотого азуриту, 10 злитків заліза та фіал флогістону.", [4] = "Ти {стать:зібрав:зібрала} все необхідне, {ім'я}?", [5] = "Ти {стать:приніс:принесла} все, що я просив. Тепер справа за мною...", ["en"] = "Brutal Armor", ["tasks"] = { ["Iron Bar"] = "злиток заліза", ["Iron Bar (Provided)"] = "злиток заліза (видано)", ["Powdered Azurite"] = "молотий азурит", ["Powdered Azurite (Provided)"] = "молотий азурит (видано)", ["Smoky Iron Ingot"] = "злиток димчастого заліза", ["Smoky Iron Ingot (Provided)"] = "злиток димчастого заліза (видано)", ["Vial of Phlogiston"] = "фіал флогістону", ["Vial of Phlogiston (Provided)"] = "фіал флогістону (видано)" } },
    [1839] = { [1] = "Ула'елек і рукавиці жорстокості", [2] = "Троль-коваль Ула'елек виготує для тебе рукавиці жорстокості. Він живе разом зі своїми побратимами Темного Списа в Дуротарі, в селищі Сен'джин і чекає на тебе.", [3] = "Поговоріть з Ула'елеком в Дуротарі.", [5] = "Вітаю, {ім'я}. Старий Тун'ґрім попередив мене про твоє прибуття, та й без цього я чекав на тебе.\n\nДухи спостерігають за твоїми діянням, {клас:к}, і вони кажуть що ти {стать:переміг:перемогла} багатьох ворогів.", ["en"] = "Ula'elek and the Brutal Gauntlets" },
    [1840] = { [1] = "Орм Кам'яне Копито і шолом жорстокості", [2] = "Орм Кам'яне Копито славиться своєю майстерністю. Він зробить для тебе шолом жорстокості.\n\nЗнайди його в Громовому Бескиді, біля ставу під великим головним тотемом.", [3] = "Поговоріть з Ормом Кам'яним Копитом в Громовому Бескиді.", [5] = "Вітаю, {клас:к}, я Орм. Тун'ґрім сказав мені, що тобі потрібен шолом.", ["en"] = "Orm Stonehoof and the Brutal Helm" },
    [1841] = { [1] = "Велора Нітелі та набедреники жорстокості", [2] = "Кажуть, що за життя Велора Нітелі була однією з найкращих обладунниць Лордерону. Схоже, що смерть не позбавила її навичок. Поговори з нею — вона створить для тебе набедреники жорстокості.\n\nВелора займається своїм ремеслом в торговому кварталі Підмістя в Лордероні.", [3] = "Поговоріть з Велорою Нітелі в Підмісті.", [5] = "Ти щодо набедреників? Чудово!\n\nХм... А я маю зробити їх для тебе чи ти — для мене?\n\nЖартую. Смішно ж було? Я не розумію... Почуття гумору я втратила разом з іншими почуттями. Десь тоді ж, коли перестала дихати.", ["en"] = "Velora Nitely and the Brutal Legguards" },
    [1842] = { [1] = "Копита сатирів", [2] = "Я можу виготовити для тебе пару чудових рукавиць, наповнивши їх магічною силою. Та спершу ти маєш принести мені джерело цієї сили.\n\nСатири, що мешкають на північному сході Ясенедолу, використовують тамтешні сили. Вони живляться чистотою лісу, висмоктуючи та спотворюючи її. Сатирів, що ввібрали найбільше магії, ти можеш відрізнити по розбухлим нероздвоєним копитам.\n\nЦі копита містять велику силу. Вони знадобляться мені у виготовленні рукавиць.", [3] = "Принесіть 7 нероздвоєних копит сатирів Ула'елеку в селище Сен'джин, що в Дуротарі.", [4] = "Копита у тебе, {ім'я}? Їх магія сильна.", [5] = "А, ти {стать:приніс:принесла} їх! Тепер я використаю їх силу в рукавицях, витягнувши її, так само як сатири витягують сили Ясенедолу.", ["en"] = "Satyr Hooves", ["tasks"] = { ["Uncloven Satyr Hoof"] = "нероздвоєне копито сатира", ["Uncloven Satyr Hoof (Provided)"] = "нероздвоєне копито сатира (видано)" } },
    [1843] = { [1] = "Рукавиці жорстокості", [5] = "Дякую тобі, {ім'я}. Ці рукавиці - моя найкраща робота. Візьми їх і носи з гідністю. Цим ти принесеш честь мені і моїм предкам.", ["en"] = "Brutal Gauntlets" },
    [1844] = { [1] = "Ріг химери", [2] = "Я зроблю шолом для тебе, та спершу ти маєш довести, що заслуговуєш на нього.\n\nНа південному заході Каміннопазуристих гір знаходиться Обвуглена долина. Колись це була красива квітуча місцина, та нині вона знищена та випалена, а тамтешні створіння сповнені болем та відчаєм.\n\nТуди ти й відправишся, {ім'я}.\n\nЙди до Обвугленої долини та знайди химеру-матріарха. Вбий її й звільни від страждань. Принеси мені її гальванізований ріг як доказ, і я зроблю для тебе шолом.", [3] = "Принесіть гальванізований ріг Орму Кам'яному Копиту в Громовий Бескид.", [4] = "Ріг у тебе? Ти {стать:позбавив:позбавила} матріарха страждань?", [5] = "Ти {стать:виконав:виконала} завдання, {ім'я}, і {стать:довів:довела} свою хоробрість. Я зроблю для тебе шолом...", ["en"] = "Chimaeric Horn", ["tasks"] = { ["Galvanized Horn"] = "гальванізований ріг", ["Galvanized Horn (Provided)"] = "гальванізований ріг (видано)" } },
    [1845] = { [1] = "Шолом жорстокості", [5] = "Візьми цей шолом.\n\nВеликі подвиги привели тебе до мене, {ім'я}. Якщо на те буде воля Матері-Землі, тебе чекає ще багато подвигів.", ["en"] = "Brutal Helm" },
    [1846] = { [1] = "Гомілкові кістки Драконової Пащі", [2] = "Для створення набедреників жорстокості мені знадобляться міцні гомілкові кістки. У орків Драконової Пащі з Заболоття підхожі кістки. Вони мені й потрібні.\n\nАле потрібні найміцніші, тому перевір їх перед тим, як брати. Якщо можеш зламати їх голіруч - вони не підійдуть.", [3] = "Принесіть Велорі Нітелі в Підмістя 8 міцних гомілкових кісток Драконової Пащі.", [4] = "Я чекаю на гомілкові кістки, {ім'я}. Вони будуть гарною основою для твоїх набедреників.", [5] = "Чудова робота! Ці кістки виглядають надійно. Думаю, вони чудово підійдуть. Орки не були проти? Сильно опирались?\n\nЦе теж був жарт. А ти не смієшся.\n\nЩось не дуже я смішно жартую останнім часом...", ["en"] = "Dragonmaw Shinbones", ["tasks"] = { ["Sturdy Dragonmaw Shinbone"] = "міцна гомілкова кістка Драконової Пащі", ["Sturdy Dragonmaw Shinbone (Provided)"] = "міцна гомілкова кістка Драконової Пащі (видано)" } },
    [1847] = { [1] = "Набедреники жорстокості", [5] = "Ось твої набедреники, {ім'я}. Дай мені знати, якщо треба щось змінити. Я прагну догодити замовнику! Принаймні, завжди так робила...\n\nНині я вже не так дбаю про якість моєї роботи. Але це краще, ніж бути бездумною слугою Скари!\n\nНапевно...", ["en"] = "Brutal Legguards" },
    [1848] = { [1] = "Гауберк жорстокості", [5] = "Тобі певно довелось багато попрацювати і пролити крові, щоб добути це, {ім'я}. Ось результат твоєї праці.\n\nНоси його з честю і якось розкажеш, як він рятував тобі життя.", ["en"] = "Brutal Hauberk" },
    [185] = { [1] = "Мистецтво полювання на тигрів", [2] = "Коли я була ще зовсім юною дівчиною, мій батько навчив мене мистецтву полювання на тигрів.\n\nМолодих звірів набагато легше вистежити та вбити. Тому почнемо з простого. Біля нашого табору часто можна зустріти молодих тигрів.\n\nВідшукай та вбий кількох звірів, скориставшись своїми навичками слідопита.", [3] = "Барвина Гіняй з експедиції Ернінґвея хоче, щоб ви вбили 10 молодих тернистодільних тигрів.", [4] = "Поки ти не доведеш, що можеш вбити наймолодших тигрів, я не бачу сенсу далі навчати тебе, {ім'я}.", [5] = "Чудова робота, {ім'я}. Тепер ти {стать:готовий:готова} рухатись далі.", ["en"] = "Tiger Mastery", ["tasks"] = { ["Young Stranglethorn Tiger"] = "молодий тернистодільний тигр", ["Young Stranglethorn Tiger slain"] = "молодий тернистодільний тигр: убито" } },
    [186] = { [1] = "Мистецтво полювання на тигрів", [2] = "Ти швидко вчишся, {клас:к}. Подивимось, як ти впораєшся з дорослими котами. Цього разу тобі потрібно вбити 10 тернистодільних тигрів.", [3] = "Барвина Гіняй з експедиції Ернінґвея хоче, щоб ви вбили 10 тернистодільних тигрів.", [4] = "Якщо ти прагнеш досягти чогось більшого, спочатку доведи, що {стать:спроможний:спроможна} впоратись з поставленим завданням. Повертайся, коли вб'єш 10 тернистодільних тигрів.", [5] = "Я вражена, {клас:к}. Ти добре справляєшся.", ["en"] = "Tiger Mastery", ["tasks"] = { ["Stranglethorn Tiger"] = "тернистодільний тигр", ["Stranglethorn Tiger slain"] = "тернистодільний тигр: убито" } },
    [1860] = { [1] = "Розмова з Дженні", [2] = "У нас, магів, є завдання, яке необхідно виконати. Це завдання життєво важливе для безпеки Штормовію та Ельвиннського лісу.\n\nДеталі знає Дженні Гармата. Вона навчається у вежі магів, що у кварталі Магів Шторомовію. Тобі слід поспішити до неї.", [3] = "Поговоріть з Дженні Гарматою в Штормовії.", [5] = "Тебе прислали, щоб допомогти мені, {ім'я:к}? Гаразд. Радісно бачити молодих магів, що прагнуть допомогти нашій справі...\n\nЯкій справі, ти запитаєш? Всьому свій час, {стать:юначе:юначко}. Всьому свій час...", ["en"] = "Speak with Jennea" },
    [1861] = { [1] = "Дзеркальне озеро", [2] = "Цей світ став жертвою масштабних магічних битв, що порушили течію магічної енергії. Ми намагаємося визначити наслідки цих змін, і дехто з нас боїться найгіршого!\n\nАле про це ми поговоримо пізніше. Зараз нам потрібно зібрати більше інформації.\n\nОсь, візьми цю флягу. Йди до підніжжя водоспаду на Дзеркальному озері, що на південний захід від воріт Штормовію, і візьми там зразок води. Принеси мені зразок, щоб я могла перевірити його на наявність магічних забруднень.", [3] = "Принесіть зразок води Дзеркального озера до Дженні Гармати у Штормовій.", [4] = "Зразок в тебе, {ім'я:к}? Потік магічної енергії в Штормовії та Ельвинні був змінений, і я маю знати, чи не проникає вона у воду.", [5] = "Дякую, {ім'я:к}. Я перевірю магічні властивості цієї води. Будем сподіватися, що вона не містить жодних забруднень, інакше ми можемо з'ясувати, що ті, хто п'ють з Дзеркального озера, зазнають впливу магії.\n\nОсь, {ім'я:к}. Візьми цю сферу чи посох на знак моєї подяки. Нехай вони добре служать тобі.", ["en"] = "Mirror Lake", ["tasks"] = { ["Mirror Lake Water Sample"] = "зразок води Дзеркального озера", ["Mirror Lake Water Sample (Provided)"] = "зразок води Дзеркального озера (видано)" } },
    [187] = { [1] = "Мистецтво полювання на тигрів", [2] = "Цього разу я хочу підняти ставки й по-справжньому перевірити твою майстерність. Доведи, що {стать:здатен:здатна} вбити 10 старих тернистодільних тигрів. Впораєшся з цим та будеш {стать:готовий:готова} до останнього випробування, після виконання якого, я зможу оголосити тебе {стать:великим мисливцем:великою мисливицею} на тигрів у присутності майстра Ернінґвея.\n\nОкрім того, що старих тернистодільних тигрів важко знайти, вони ще й безжальні в бою.", [3] = "Барвина Гіняй з експедиції Ернінґвея хоче, щоб ви вбили 10 старих тернистодільних тигрів.", [4] = "Ти {стать:повинен:повинна} вбити 10 старих тернистодільних тигрів, перш ніж я допущу тебе до останнього випробування, яке допоможе визначити, чи є ти {стать:справжнім великим мисливцем:справжньою великою мисливицею} на тигрів.", [5] = "Вражаюче. Гадаю, ти майже {стать:готовий:готова}.", ["en"] = "Tiger Mastery", ["tasks"] = { ["Elder Stranglethorn Tiger"] = "старий тернистодільний тигр", ["Elder Stranglethorn Tiger slain"] = "старий тернистодільний тигр: убито" } },
    [1878] = { [1] = "Винагорода за бурдюки з водою", [4] = "Знову {стать:повернувся:повернулася}, {ім'я}? Якщо у тебе є ще п'ять бурдюків з водою Пустелебродів, то я маю для тебе ще один польовий набір!", [5] = "Чудово — чим більше бурдюків з водою ми зможемо повернути, тим далі ми всі будемо від катастрофи! Принось їх ще, і за кожні п'ять одиниць ти отримуватимеш по польовому набору.", ["en"] = "Water Pouch Bounty", ["tasks"] = { ["Wastewander Water Pouch"] = "бурдюк з водою Пустелебродів", ["Wastewander Water Pouch (Provided)"] = "бурдюк з водою Пустелебродів (видано)" } },
    [1879] = { [1] = "Розмова з Бінк", [2] = "{Ім'я:н}! Бінк, моя колега-гном з Залізогарту, надіслала звістку. У неї є важливе завдання і вона не покладається ні на кого, крім магів! Ти {стать:готовий:готова} допомогти їй, {ім'я:к}?\n\nЯкщо так, то поговори з Бінк. Вона проводить більшість часу у залі Таємниць, що в Таємній палаті Залізогарту.", [3] = "Поговоріть з Бінк в Залізогарті.", [5] = "Ох, я бачу в тобі непоганий потенціал, так-так! Але для того, щоб бути {стать:хорошим:хорошою} {клас:о}, потрібно більше, ніж потенціал. А якщо ти не {стать:хороший:хороша} {клас} — ти {стать:поганий:погана} {клас}. А через поганих магів і виникають усі проблеми!\n\nОй, я забігаю наперед. Почнімо з самого початку!", ["en"] = "Speak with Bink" },
    [188] = { [1] = "Мистецтво полювання на тигрів", [2] = "Ось моє останнє завдання. Ми вже кілька тижнів вистежуємо цю невловну тигрицю. Ми прозвали її Сін'Далл. Подивимося, чи зможеш ти зробити те, що не {стать:робив ще жоден:робила ще жодна} {раса:н}: розшукати та вбити Сін'Далл. Принеси мені її лапу, щоб довести своє досягнення.\n\nВистежити її буде нелегко.", [3] = "Барвина Гіняй з експедиції Ернінґвея хоче, щоб ви вбили Сін'Далл та принесли її лапу.", [4] = "Як просувається полювання на Сін'Далл?", [5] = "Мушу сказати, я вражена! Ти {стать:справжній великий мисливець:справжня велика мисливиця} на тигрів, {ім'я:к}!", ["en"] = "Tiger Mastery", ["tasks"] = { ["Paw of Sin'Dall"] = "лапа Сін'Далла", ["Paw of Sin'Dall (Provided)"] = "лапа Сін'Далла (видано)" } },
    [1880] = { [1] = "Маг-тастичний гізмонітор", [2] = "Ми, маги, робимо більше, ніж просто махаємо пальцями та створюємо красиві іскри! Ми керуємо магією — самою тканиною нашого світу! Це вимагає великої обережності, рішучості та знань... дуже багато знань!\n\nОдин з моїх пристроїв — маг-тастичний гізмонітор — збирає та зберігає ці знання у великих кількостях! Але я загубила його! Коли ми втікали з нашого дому в Гномреґані, я залишила його у скрині в одній з хатин за містом, а тепер це місце кишить лепрогномами!\n\nБудь ласка, {ім'я:к}, поверни мій гізмонітор!", [3] = "Поверніть Бінк її маг-тастичний гізмонітор.", [4] = "Ти {стать:знайшов:знайшла} гізмонітор? Я маю отримати його до того, як у нього закінчиться енергія!", [5] = "Як чудово! Коли я створювала гізмонітор, я й не уявляла, наскільки він стане для мене важливим. Тепер я зможу відновити свої дослідження!\n\nДякую, {ім'я:к}! І ось, це були мої перші магічні інструменти. Вони трохи подряпані, зате перевірені часом. Обирай — я впевнена, що будь-який з них стане тобі у пригоді.", ["en"] = "Mage-tastic Gizmonitor", ["tasks"] = { ["Mage-tastic Gizmonitor"] = "маг-тастичний гізмонітор", ["Mage-tastic Gizmonitor (Provided)"] = "маг-тастичний гізмонітор (видано)" } },
    [1881] = { [1] = "Розмова з Анастасією", [2] = "{ім'я:к}, Анастасія Гартвелл має завдання, яке тобі якраз до снаги. Поговори з нею у кварталі Магії Підмістя та підготуйся до свого першого завдання для магів відречених.", [3] = "Поговоріть з Анастасією Гартвелл.", [5] = "Вітаю, {ім'я:к}. Ти {стать:вчинив:вчинила} мудро, відповівши на мій заклик, та ще мудріше буде прислухатись до моїх слів...", ["en"] = "Speak with Anastasia" },
    [1882] = { [1] = "Хутір Бальнірів", [2] = "Зачумлені землі на сході — мерзенне творіння Короля-ліча. Вони поширюють свою магію у ґрунт, спотворюючи та знищуючи все живе. Попри певну привабливість руйнівної сили чуми, ми, маги відречених, вважаємо її некерованою і неприпустимою.\n\nАле перед тим, ми повинні виміряти, наскільки сильно вона проникла в Тірісфаль. Йди на хутір Бальнірів що на сході Тірісфаля. У саду ростуть квіти — ротики. Збери їх і повертайся.", [3] = "Принесіть ротики Бальнірів Анастасії Хартвелл у квартал Магів Підмістя.", [4] = "Ти {стать:знайшов:знайшла} ротики? Вони дуже чутливі до магічної енергії, і вивчення цих рослин поблизу Зачумлених земель допоможе нам зрозуміти, чи не потрапила чума на Тірісфальське перелісся.", [5] = "Ах, який чудовий зразок. Я відправлю його на вивчення нашим аптекарям, щоб встановити вплив зараження з Зачумлених земель.\n\nГарна робота, {ім'я:к}. За твої послуги я пропоную винагороду на твій вибір: сферу або посох. Що б ти не {стать:обрав:обрала}, ця річ буде досить корисною.", ["en"] = "The Balnir Farmstead", ["tasks"] = { ["Balnir Snapdragons"] = "ротики Бальнірів", ["Balnir Snapdragons (Provided)"] = "ротики Бальнірів (видано)" } },
    [1883] = { [1] = "Розмова з Ун'Тувою", [2] = "Ун'тува, племінний маг селища Сен'джин, виявив порушення магічних потоків у Дуротарі та просить допомоги. Поговори з Ун'тувою та зроби все можливе, щоб допомогти йому.\n\nЗроби це, і з часом тобі розкриються нові таємниці.", [3] = "Поговоріть з Ун'Тувою.", [5] = "Привіт тобі, {ім'я:к}. Хвала тобі, що {стать:відгукнувся:відгукнулася} на мій заклик. Будемо сподіватися, що ти впораєшся із завданням...", ["en"] = "Speak with Un'thuwa" },
    [1884] = { [1] = "Купи джуджу", [2] = "Чорнокнижник Залазейн з островів Ехо порушив звичайний потік магії в Дуротарі. Він робить це за допомогою зіпсованих фетишів — куп джуджу, які він розмістив біля хатин на головному Острові Ехо.\n\nЦі купи знищують нашу дику природу та надають силу чорнокнижникам та пекельникам, які ховаються в темних закутках землі.\n\nТобі необхідно знищити купи джуджу, {ім'я:к}, перш ніж потік магії зміниться назавжди.", [3] = "Знищте 4 купи джуджу, після чого поверніться до Ун'туви у селище Сен'джин.", [4] = "Ти маєш поквапитися, {ім'я:к}. Знищ купи джуджу!", [5] = "Я відчуваю, що купи джуджу Залазейна знищені, і з часом потік магії в Дуротарі має повернутись до норми.\n\nТи {стать:зробив:зробила} великий подвиг для свого народу, {ім'я:к}. І {стать:показав:показала}, що ти {стать:гідний:гідна} бути {клас:о} Орди.", ["en"] = "Ju-Ju Heaps", ["tasks"] = { ["Ju-Ju Heaps Destroyed"] = "Знищені купи джу-джу" } },
    [189] = { [1] = "Вуха Кровоскальпих", [2] = "Кляті тролі! Вони вбивають наших агентів у джунглях! Я вже втратив чимало своїх найкращих бійців у сутичках з ними. Збитки ростуть! Як я поясню це барону Ревілґазу?\n\nПотрібні рішучі дії... Думай, Кебок, думай... Тебе призначили на цю посаду не для того, щоб ти сидів, склавши руки... Придумав! Ти... {ім'я}, так? Ти ж мені допоможеш, чи не так? Є гарна можливість підзаробити!\n\nОсь, що я пропоную... ти принесеш мені вуха п'ятнадцяти кровоскальпих тролів, а я тобі добре заплачу за це.", [3] = "Роздобудьте 15 вух Кровоскальпих і принесіть їх Кебоку в Грабіжну Бухту.", [4] = "Сподіваюсь, тобі вдалося? Ці тролі скрізь. Брудні тварюки.\n\nДо речі! Візьми з собою друзів, добре? Нам би не завадила допомога!", [5] = "Чудово, чудово. Це тимчасово розв'яже проблему...\n\n<Він затихає, бурмочучи щось про прибутки й витрати...>\n\nЩо? Ти ще тут? Винагорода? А, так... звичайно, ось, візьми... цього має бути більш ніж достатньо.", ["en"] = "Bloodscalp Ears", ["tasks"] = { ["Bloodscalp Ear"] = "вухо Кровоскальпого", ["Bloodscalp Ear (Provided)"] = "вухо Кровоскальпого (видано)" } },
    [190] = { [1] = "Мистецтво полювання на пантер", [2] = "Якщо ти хочеш відправитись на полювання разом з цією відчайдушною групою, яку очолив Гемет, тобі доведеться довести, що ти {стать:вправний мисливець:вправна мисливиця} на пантер. Не хвилюйся — ми почнемо з простого. Для початку, подивимось, як ти впораєшся з вбивством 10 молодих пантер.\n\nВистежити їх — це лише половина завдання...", [3] = "Пан Йарс Имин з експедиції Ернінґвея хоче, щоб ви вбили 10 молодих пантер.", [4] = "{стать:Справжній мисливець:Справжня мисливиця} на пантер вже б {стать:був:була} в полі, намагаючись вполювати свою здобич. Докажи, що ти дійсно хочеш досягти мети, {клас:к}, і йди туди.", [5] = "Непоганий початок, {ім'я}!", ["en"] = "Panther Mastery", ["tasks"] = { ["Young Panther"] = "молода пантера", ["Young Panther slain"] = "молода пантера: убито" } },
    [191] = { [1] = "Мистецтво полювання на пантер", [2] = "Тепер ти {стать:готовий:готова} перейти на новий рівень. Якщо хочеш довести, що ти {стать:гідний:гідна} спілкуватися такими великими мисливцями, як вони, тобі потрібно вбити 10 пантер.\n\nЦі звірі витриваліші. З ними не так легко впоратись, як з тим молодняком, який ти {стать:вбивав:вбивала} раніше.", [3] = "Пан Йарс Имин з експедиції Ернінґвея хоче, щоб ви вбили 10 пантер.", [4] = "Іди та вбий 10 пантер! Покажи, на що ти {стать:здатен:здатна}!", [5] = "Чудова робота, {ім'я}!", ["en"] = "Panther Mastery", ["tasks"] = { ["Panther"] = "пантера", ["Panther slain"] = "пантера: убито" } },
    [1919] = { [1] = "Звіт для Дженні", [2] = "Твої знання нашого ремесла зростають, {стать:юний:юна} {ім'я:к}. Чи {стать:готовий:готова} ти до справжнього навчання? Чи {стать:готовий:готова} ти зайняти своє місце в таємній війні, яку ми ведемо?\n\nЯкщо так, тоді поговори з Дженні Гарматою у вежі магів, що у кварталі магів Штормовію. Вона має для тебе завдання, яке відкриє тобі вікно до невидимого світу.", [3] = "Поговоріть з Дженні Гарматою в Штормовії.", [5] = "{ім'я:к}, я маю для тебе завдання. Слухай уважно, ми не можемо гаяти час.", ["en"] = "Report to Jennea" },
    [192] = { [1] = "Мистецтво полювання на пантер", [2] = "Тепер найскладніше. {стать:Справжній мисливець:Справжня мисливиця} на пантер зможе довести свою майстерність, вбивши тінепащу пантеру, найсмертоноснішу в Тернистій долині. Доведи нам, що можеш вбити 10 таких звірів.\n\nЯкщо ти думаєш, що їх важко вистежити, спробуй ще вбити одну з них....", [3] = "Пан Йарс Имин з експедиції Ернінґвея хоче, щоб ви вбили 10 тінепащих пантер.", [4] = "Що ти тут робиш, {ім'я}? Ти {стать:мав:мала} би повзати по кущах, вбиваючи 10 тінепащих пантер. Я думав, ти {стать:мріяв:мріяла} про велике полювання, {клас:к}!", [5] = "Ти молодець, {ім'я}!", ["en"] = "Panther Mastery", ["tasks"] = { ["Shadowmaw Panther"] = "тінепаща пантера", ["Shadowmaw Panther slain"] = "тінепаща пантера: убито" } },
    [1920] = { [1] = "Розслідування в \"Синьому відлюднику\"", [2] = "Нам повідомили про порушення у таверні \"Синій відлюдник\", що у кварталі магів. Дивні невидимі створіння блукають по таверні, і я боюся, що там утворився розлом мани.\n\nЯ хочу, щоб ти {стать:подивився:подивилась} що коїться в таверні та {стать:захопив:захопила} цих створінь. Скористайся закляттям прояву в таверні, щоб розсіяти їхню невидимість, здолай їх, а потім кинь скриню стримування, щоб їх зловити. Коли закінчиш, повернись із заповненими скринями стримування, ящиком та закляттям прояву.", [3] = "Візьміть закляття прояву та ящик зі скринями стримування за спиною у Дженні Пушки. Принесіть 3 заповнені скрині стримування, ящик зі скринями стримування та закляття прояву до Дженні у вежу магів.", [4] = "Ти {стать:захопив:захопила} створінь, {ім'я:к}? Ми маємо вивчити їх, щоб визначити причину їхнього прибуття.", [5] = "Гарна робота! Я ретельно вивчу цих створінь і, якщо пощастить, з'ясую, як вони потрапили в наш світ.\n\nТи приносиш спільноті магів дедалі більше користі, {ім'я:к}.", ["en"] = "Investigate the Blue Recluse", ["tasks"] = { ["Cantation of Manifestation"] = "закляття прояву", ["Cantation of Manifestation (Provided)"] = "закляття прояву (видано)", ["Chest of Containment Coffers"] = "ящик зі скринями стримування", ["Chest of Containment Coffers (Provided)"] = "ящик зі скринями стримування (видано)", ["Filled Containment Coffer"] = "заповнена скриня стримування", ["Filled Containment Coffer (Provided)"] = "заповнена скриня стримування (видано)" } },
    [1921] = { [1] = "Збір матеріалів", [2] = "Ти добре {стать:послужив:послужила} своїм побратимам магам. Прийшов час тобі отримати власну мантію чарівника. Вінн Ларсон може виготовити її, але ти маєш принести їй необхідні матеріали.\n\nМантія буде виготовлена з льону, який легко знайти, але крім нього ти маєш дістати заряджені камені розлому. Єдиним відомим їх місцем знаходження є копальня Срібних потоків у Лох-Модані. Їх залишили у ящиках дворфи з Ліги шахтарів.\n\nЗбери льон і камені та принеси їх до Вінн Ларсон в \"сукна Ларсона\", що у кварталі магів.", [3] = "Принесіть 10 відрізів лляної тканини та 6 заряджених каменів розлому до Вінн Ларсон у Штормовій.", [4] = "Привіт, {ім'я:к}. Дженні сказала мені, що ти прийдеш. В тебе є щось для мене?", [5] = "Так, це чудові відрізи льону. З них я можу пошити гарну мантію. А після того, як я вплету в неї камені розлому, у нас буде одяг, гідний {клас:р}!", ["en"] = "Gathering Materials", ["tasks"] = { ["Charged Rift Gem"] = "заряджений камінь розлому", ["Charged Rift Gem (Provided)"] = "заряджений камінь розлому (видано)", ["Linen Cloth"] = "лляна тканина", ["Linen Cloth (Provided)"] = "лляна тканина (видано)" } },
    [193] = { [1] = "Мистецтво полювання на пантер", [2] = "Ти майже {стать:довів:довела}, що ти {стать:великий мисливець:велика мисливиця} на пантер. Джунглями блукає одна пантера, на ім'я Баґ'тіра. До сьогодні їй вдавалося уникати зустрічі з нашою групою. Спробуй використати свої навички, щоб вбити велику Баґ'тіру.\n\nПринеси мені її ікло й ти заслужиш мою повагу!", [3] = "Пан Йарс Имин з експедиції Ернінґвея хоче, щоб ви принесли йому ікло Баґ'тіри.", [4] = "Баґ'тіра — невловний звір. Як іде полювання?", [5] = "Отже, велика Баґ'тіра мертва! Слава тобі, {ім'я}. Ти справді {стать:могутній:могутня} {клас:н}!", ["en"] = "Panther Mastery", ["tasks"] = { ["Fang of Bhag'thera"] = "ікло Баґ'тіри", ["Fang of Bhag'thera (Provided)"] = "ікло Баґ'тіри (видано)" } },
    [1938] = { [1] = "Трактат Ура про темну магію", [2] = "Давним-давно в цій вежі вчилися три маги, поки один з них не зацікавився темними мистецтвами. Його закликали відмовитися від цієї темної магії, але він не зміг встояти. І тому його вигнали.\n\nНовим прихистком мага-вигнанця стала вежа Ілґалара у Багрянокряжжі, а з собою він прихопив могутню книгу — трактат Ура про темну магію.\n\nМи, маги Штормовію, хочемо повернути цю книгу. Увійди до вежі Ілґалара, знайди книгу у його бібліотеці та принеси мені.", [3] = "Принесіть трактат Ура про темну магію верховному чаклуну Андромату в Штормовій.", [4] = "Книга в тебе, {ім'я:к}? Її таємниці не призначені для непідготовлених, а детальне її вивчення може призвести до загибелі.", [5] = "Я боявся, що Морґант знайде інше місце, щоб сховати книгу або знайде спосіб відкрити та прочитати її вміст.\n\nДобре бачити, що цього не сталося, і що печатки, які ми наклали на трактат Ура про темну магію, ще діють.", ["en"] = "Ur's Treatise on Shadow Magic", ["tasks"] = { ["Ur's Treatise on Shadow Magic"] = "трактат Ура про темну магію", ["Ur's Treatise on Shadow Magic (Provided)"] = "трактат Ура про темну магію (видано)" } },
    [1939] = { [1] = "Верховний чаклун Андромат", [2] = "Верховний чаклун Андромат бажає поговорити з тобою, {ім'я:к}. Він знаходиться на верхньому поверсі вежі магів, в районі магів Штормовія.\n\nБуло б мудро поговорити з ним, оскільки Андромат є одним з наймогутніших магів за межами Даларана. Його поради високо цінуються.", [3] = "Поговоріть з верховним чаклуном Андроматом.", [5] = "Вітаю, {ім'я:к}. Я радий бачити тебе і сподіваюсь, що у тебе є час послухати слова старця...", ["en"] = "High Sorcerer Andromath" },
    [194] = { [1] = "Мистецтво полювання на рапторів", [2] = "Ти вважаєш, що твої мисливські навички на висоті? Я можу легко це перевірити прямо зараз. Вирушай у джунглі та вбий 10 тернистодільних рапторів. Побачимо, наскільки ти {стать:готовий:готова} до полювання на великих звірів.\n\nІ ні, я не скажу тобі, де їх можна знайти! Розшукати цих звірів — це частина завдання.", [3] = "Гемет Ернінґвей хоче, щоб ви вбили 10 тернистодільних рапторів.", [4] = "Я ніколи не бачив {стать:мисливця, який би вполював:мисливицю, яка б вполювала} когось, стоячи біля багаття. Ти плануєш вбити тих рапторів чи сподіваєшся, що вони помруть від старості?", [5] = "Гарна робота, {стать:старий:стара}!", ["en"] = "Raptor Mastery", ["tasks"] = { ["Stranglethorn Raptor"] = "тернистодільний раптор", ["Stranglethorn Raptor slain"] = "тернистодільний раптор: убито" } },
    [1940] = { [1] = "Бездоганне павутиння", [2] = "Твоя служба була непохитною, {ім'я:к}. Можливо, настав час тобі отримати більш вишукане вбрання, відповідно до твого статусу мага-адепта. Якщо ти збереш необхідні матеріали, ми зможемо виготовити мантію.\n\nТобі потрібно піти в Смерколісся та полювати на мертвоїдів-самітників. Збери їх павутиння, але лише найкраще, бездоганне павутиння. Коли назбираєш достатньо — принеси його Вінн Ларсон в \"сукна Ларсона\", що у кварталі магів. Вона пошиє тобі мантію.", [3] = "Принесіть 8 бездоганних павутинь Вінн Ларсон у Штормовій.", [4] = "А, так. Маги з вежі попередили, що ти прийдеш. У тебе є потрібне павутиння?", [5] = "Гарні зразки. Я одразу берусь до роботи!", ["en"] = "Pristine Spider Silk", ["tasks"] = { ["Pristine Spider Silk"] = "бездоганне павутиння", ["Pristine Spider Silk (Provided)"] = "бездоганне павутиння (видано)" } },
    [1942] = { [1] = "Вбрання астрального плетіння", [5] = "Твоє вбрання готове! І павутиння, що ти {стать:зібрав:зібрала}, неймовірне... Я не втрималась і залишила трохи собі, тож вбрання вийшло коротшим...\n\nЖартую. Воно тобі дуже пасуватиме, і чудово підійде як для пригод, так і для урочистостей. Насолоджуйся!", ["en"] = "Astral Knot Garment" },
    [1943] = { [1] = "Розмова з Дейно", [2] = "Трольці-магині Дейно потрібна твоя допомога, {ім'я:к}. Вона знаходиться в Орґріммарі, в хижі Темношипа.", [3] = "Поговоріть з Дейно.", [5] = "Добре, що ти {стать:прийшов:прийшла}. Моє завдання нелегке, але життєво важливе для товариства магів. Ти маєш допомогти мені, я впевнена, тебе це зацікавить.", ["en"] = "Speak with Deino" },
    [1944] = { [1] = "Води Завіана", [2] = "Легендарне місто Завіан лежить у глибині східного Ясенедолу, і розповіді про його давні знання добре відомі серед освічених людей. Кажуть, що води Завіана мають величезну магічну силу.\n\nЯ хотіла б отримати зразок цієї води.\n\nВізьми цю флягу і вирушай до Завіана. Набери води з підніжжя його найвищого водоспаду і повертайся до мене. І будь {стать:обережний:обережна}, руїни цього стародавнього міста заполонили сатири, і вони не люблять, коли маги втручаються в їхні справи.", [3] = "Принесіть зразок води Завіана до Дейно в Орґріммар.", [4] = "Я рада, що ти {стать:повернувся:повернулася} з головою на плечах, {ім'я:к}. Тобі вдалось взяти зразок води? Мені не терпиться вивчити її властивості.", [5] = "Ах, дуже добре. Певно, сатири Завіана завдали тобі клопоту?\n\nДякую, {ім'я:к}. Я негайно займуся вивченням цієї води.", ["en"] = "Waters of Xavian", ["tasks"] = { ["Xavian Water Sample"] = "зразок води Завіана", ["Xavian Water Sample (Provided)"] = "зразок води Завіана (видано)" } },
    [1945] = { [1] = "Сміхотливі сестри", [2] = "За твої послуги, я хочу винагородити тебе новою магічною мантією, але тобі доведеться зібрати необхідні матеріали...\n\nТобі потрібно повернутися до Ясенедолу та зібрати волосся сміхотливих сестер — дріад, що збираються біля прихистку Незайманого лісу.\n\nКоли збереш їхнє волосся, принеси його тролю-кравцю Кіл'галі на Перехрестя. Він-то й пошиє для тебе нову мантію.", [3] = "Принесіть 12 волосин сміхотливих сестер до Кіл'гали на Перехрестя.", [4] = "Вітаю, {ім'я:к}. Дейно сказала, що ти прийдеш і принесеш волосся сміхотливих сестер. Воно в тебе?", [5] = "Ах, з цього волосся вийде прекрасна мантія, {ім'я:к}. Шкода що сміхотливі сестри мали загинути, щоб розлучитися з ним, втім, добровільно вони його все одно не віддали б.\n\nШкода, але не дуже.", ["en"] = "Laughing Sisters", ["tasks"] = { ["Laughing Sister's Hair"] = "волосина сміхотливої сестри", ["Laughing Sister's Hair (Provided)"] = "волосина сміхотливої сестри (видано)" } },
    [1946] = { [1] = "Вбрання підсвітнього плетіння", [5] = "Ось твої вбрання підсвітного плетіння, {ім'я:к}. Вони зручні та міцні, і зберігають в собі магію веселих сестер.\n\nНасолоджуйся, і якщо вони тобі сподобаються, будь ласка, згадай про це в розмові з Дейно. Вона з тих магів, з якими варто підтримувати добрі стосунки...", ["en"] = "Nether-lace Garment" },
    [1947] = { [1] = "Подорож до болота", [2] = "Настав час тобі здобути свій магічний жезл. Для початку звернися до відлюдниці з Бруднолипкої трясовини, людини на ім'я Табета. Ти знайдеш її хатину глибоко в болоті на заході від Терамору.\n\nПоговори з нею, її знання безмежні. Хатина Табети знаходиться на заході від Терамору, трохи північніше руїн Каменедовбні.", [3] = "Поговоріть з Табетою.", [5] = "Тихо! Я зосереджена, не турбуй мене!\n\nХвилинку...", ["en"] = "Journey to the Marsh" },
    [1948] = { [1] = "Предмети сили", [2] = "Створити жезл мага непросто. Для цього потрібні рідкісні компоненти та посудина, що може вмістити велику кількість магічної енергії. Ти маєш зібрати ці речі та принести мені.\n\nЯ написала на пергаменті список того, що тобі потрібно, та вказівки, як це дістати. Принеси мені все, що є в списку, і чітко дотримуйся моїх вказівок, бо інакше під час створення жезла може статися... біда.", [3] = "Принесіть нефрит і заряджену блискавкою тростину до Табети в Бруднолипку трясовину.", [4] = "Привіт, {ім'я:к}. Ти {стать:приніс:принесла} компоненти?", [5] = "Ага! Ти {стать:знайшов:знайшла} нефрит і {стать:виготовив:виготовила} тростину! Гарна робота!\n\nЦе у тебе дим вух йде? Можливо, ти {стать:був:була} занадто близько до тростини, коли в неї вдарила блискавка... але не хвилюйся. Удар блискавкою — то на щастя!", ["en"] = "Items of Power", ["tasks"] = { ["Bolt Charged Bramble"] = "заряджена блискавкою тростина", ["Bolt Charged Bramble (Provided)"] = "заряджена блискавкою тростина (видано)", ["Jade"] = "нефрит", ["Jade (Provided)"] = "нефрит (видано)", ["Jade slain"] = "Нефрит: убито" } },
    [1949] = { [1] = "Приховані таємниці", [2] = "Щоб створити жезл, мені потрібно прочитати кілька розділів одної книги. Книга називається \"Ритуали сили\", написана чаклуном Тіртом.\n\nУ мене її немає, та й у жодній бібліотеці її не знайти. Тому ти маєш поговорити з Тіртом і отримати книгу від нього.\n\nУспіхів тобі. Колись Тірт був великим магом та вченим, але зараз він проводить час на перегонах гномів та гоблінів на Мерехтливих рівнинах, п'є та грає в азартні ігри.", [3] = "Поговоріть з чаклуном Тіртом на Мерехтливій рівнині.", [5] = "Що? Говори голосніше! У мене вже не такий гострий слух, як колись.\n\nСподіваюся, що ти {стать:прийшов:прийшла} зі свіжим кухлем елю або з відомостями щодо наступних перегонів! Якщо ні, то краще йди звідси... бо мій поліморфний жезл вже напоготові!", ["en"] = "Hidden Secrets" },
    [195] = { [1] = "Мистецтво полювання на рапторів", [2] = "А тепер перейдемо до складніших випробувань і перевіримо, чи {стать:готовий:готова} ти. Відправляйся в джунглі та вполюй десяток цих клятих хлястохвостих рапотрів. Подивимось, на що ти {стать:здатен:здатна}!", [3] = "Гемет Ернінґвей хоче, щоб ви вбили 10 хлястохвостих рапторів.", [4] = "{стать:Справжній мисливець:Справжня мисливиця} зосереджує усю свою увагу на здобичі. А тобі, {стать:друже мій:подруго моя}, здається, більше до вподоби балаканина біля вогнища. Іди та вбий 10 хлястохвостів, поки я сам не пішов і не винищив їх всіх за одне полювання.", [5] = "Саме так і здобуваються трофеї! Гарна робота, {ім'я}!", ["en"] = "Raptor Mastery", ["tasks"] = { ["Lashtail Raptor"] = "хлястохвостий раптор", ["Lashtail Raptor slain"] = "хлястохвостий раптор: убито" } },
    [1950] = { [1] = "Особлива фраза", [2] = "Я можу допомогти тобі з книгою, але спершу ти мусиш допомогти мені!\n\nТом, який ти шукаєш, знаходиться у моїй замкненій магічній скрині. Щоб відкрити цю скриню, потрібно промовити особливу фразу, і я ніяк не можу її запам'ятати! Зазвичай, мій помічник допомагає мені запам'ятовувати такі речі, але він десь зник.\n\nЯкщо хочеш мою книгу, знайди мого учня! Розпитай на треку — якщо пощастить, то хтось його бачив. Притягни його сюди, або принаймні дізнайся від нього мою чарівну фразу, щоб ми могли відкрити скриньку!", [3] = "Дізнайтеся чарівну фразу яка відкриває скриню Тірта, потім поверніться до Тірта.", [4] = "Чого ти чекаєш? Мені потрібно згадати мою магічну фразу!", [5] = "Ах так, тепер я згадав...\n\nЯ забув про це маленьке прокляття, що я наклав на Джонсона. Не пам'ятаю чому я це зробив, але я впевнений, що він заслужив на це, маленький негідник!", ["en"] = "Get the Scoop", ["tasks"] = { ["Secret phrase found"] = "Знайдена секретна фраза" } },
    [1951] = { [1] = "Ритуали сили", [2] = "Хм... я тут згадав... в мене немає книги! Бачиш, у мене були деякі борги, і щоб їх погасити, я продав останній примірник \"Ритуалів сили\" якомусь жерцеві...\n\nЧлену Багряного братства. Він, напевне, забрав її до бібліотеки Багряного монастиря у Тірісфальському переліссі!\n\nЯкщо ти так хочеш отримати книгу, тобі доведеться піти по неї в монастир. І вибач за всі ці клопоти. Я сам не свій останнім часом...", [3] = "Принесіть книгу \"Ритуали сили\" до Табети у Бруднолипку трясовину.", [4] = "Вітаю, {ім'я:к}. Книга в тебе?", [5] = "А ось і книга! Це саме те, що мені потрібно для підготовки до ритуалу створення твого жезла! Сподіваюся, знайти її було не надто складно...", ["en"] = "Rituals of Power", ["tasks"] = { ["Rituals of Power"] = "\"Ритуали сили\"", ["Rituals of Power (Provided)"] = "\"Ритуали сили\" (видано)" } },
    [1952] = { [1] = "Магічний жезл", [2] = "Що ж, піду зроблю жезли.", [3] = "Поговоріть з Табетою після ритуалу.", [5] = "Ось жезли, які я зробила. Обирай який хочеш!", ["en"] = "Mage's Wand" },
    [1953] = { [1] = "Повернення до болота", [2] = "Настав час тобі, {ім'я:к}, поговорити з Табетою — відлюдницею з Бруднолипкої трясовини. Вона допоможе тобі створити потужні магічні інструменти.\n\nХатина Табети знаходиться глибоко в Бруднолипкій трясовині, на заході від Терамору.", [3] = "Поговоріть з Табетою.", [5] = "Ах, так. Ти тут для створення сфери або посоху, {ім'я:к}? Дуже добре. Я допоможу тобі.\n\nАле попереджаю — цей процес повний небезпек і може призвести до твоєї смерті.\n\nАбо моєї смерті. Точно чиєїсь смерті...\n\nАле будемо сподіватися, що це буде чиясь інша смерть, добре?", ["en"] = "Return to the Marsh" },
    [1954] = { [1] = "Сфера пекельника", [2] = "Насамперед тобі потрібно роздобути сферу сили. У чорнокнижників Палаючого Леза є чудові сфери... шкода, що в кожній з них сидить демон! Але ми можемо це виправити, так, ми зможемо.\n\nПрямуй в Спустошище та відбери сферу пекельника у закликача Палаючого Леза. Ти знайдеш закликачів в руїнах Маннорок.\n\nЯк отримаєш сферу — повертайся до мене.", [3] = "Принесіть сферу пекельника Табеті в Бруднолипку трясовину.", [4] = "Ти {стать:приніс:принесла} сферу пекельника, {ім'я:к}?", [5] = "О, це чудова сфера! Але я не маю на увазі \"чудова\" як освіжаюча джерельна вода в спеку.\n\nНасправді не така вона й чудова, якщо подумати. Не вода. Сфера!\n\nЗосередься, {ім'я:к}! Нам потрібна твоя увага, якщо ми хочемо закінчити нашу роботу!", ["en"] = "The Infernal Orb", ["tasks"] = { ["Infernal Orb"] = "сфера пекельника", ["Infernal Orb (Provided)"] = "сфера пекельника (видано)" } },
    [1955] = { [1] = "Екзорцизм", [2] = "Тепер, коли ми маємо сферу закликача, нам потрібно вигнати демона з неї. Я це зроблю. Це найлегша частина.\n\nВажчу роботу виконаєш ти. Тобі доведеться вбити демона, коли він вийде зі сфери.\n\nІ ти маєш діяти швидко. Якщо забаришся, він стрибне назад у сферу, і нам доведеться починати спочатку!\n\nТож приготуйся. Приготуй свої найсильніші заклинання і тримай зілля під рукою, а також знайди союзників, якщо зможеш. Бо це буде не дуже приємно.", [3] = "Вбийте демона сфери, після чого поговоріть з Табетою.", [4] = "Тобі доведеться вбити цього демона, щоб позбавити сферу його впливу, {ім'я:к}.", [5] = "Молодець, {ім'я:к}! Ти {стать:показав:показала} тому демону де раки зимують, він це не скоро забуде.\n\nТепер він двічі подумає, перш ніж знову сунутися в наш світ, щоб помститися тобі. Можливо, цього разу з друзями. Які не бажають нічого, окрім як розірвати тебе на маленькі шматочки.\n\nЯ ж тебе не налякала, правда, {ім'я:к}?", ["en"] = "The Exorcism", ["tasks"] = { ["Demon of the Orb"] = "демон сфери", ["Demon of the Orb slain"] = "демон сфери: убито" } },
    [1956] = { [1] = "Сила Ульдамана", [2] = "Тепер, коли демон знищений, нам потрібно знайти джерело сили. На жаль, найкращі джерела сили, як правило, найстаріші та ними не так просто заволодіти. Цікаво, як доля часом любить кинути виклик, чи не так?\n\nОтже, тобі потрібно буде піти до Ульдамана та перемогти тамтешнього обсидіанового вартового. Він великий, він сильний, а його джерело сили — це щось!\n\nЩасти тобі, {ім'я:к}. А якщо все ж не пощастить, то, ну... було приємно з тобою познайомитися.", [3] = "Отримайте обсидіанове джерело сили та принесіть його до Табети в Бруднолипку трясовину.", [4] = "Ти {стать:був:була} в Ульдамані, {ім'я:к}? Вдалося перемогти обсидіанового вартового?", [5] = "Тобі вдалося? Вітаю!\n\nЯ розмовляла з кількома колегами, і коли я згадала твоє ім'я, вони сказали: \"Ти знаєш, що {ім'я:н} добре справляється з труднощами?\"\n\nАле коли я сказала їм, що послала тебе в Ульдаман битися з обсидіановим вартовим, вони сказали, що я з'їхала з глузду! Вони сказали: \"Табета, ти з'їхала з глузду! {Ім'я:н} не зможе його здолати!\"\n\nА я відповіла: \"Побачимо\", а вони сказали: \"Еге ж, побачимо...\"\n\nНу, ми їм показали, чи не так?", ["en"] = "Power in Uldaman", ["tasks"] = { ["Obsidian Power Source"] = "обсидіанове джерело сили", ["Obsidian Power Source (Provided)"] = "обсидіанове джерело сили (видано)" } },
    [1957] = { [1] = "Манасплески", [2] = "Ми майже закінчили, але останній крок найнебезпечніший, {ім'я:к}.\n\nУ мене є порожня сфера закликача і я готова зарядити її енергією розлому мани. Я вимовлю заклинання, яке тимчасово відкриє розлом, з якого будуть вивільняться істоти, манасплески. Тобі потрібно перемогти їх, що вивільнити їхню силу, яку я потім зберу.\n\nВбий достатню кількість манасплесків до закриття розлому, і я поміщу всю їхню енергію у твою сферу.", [3] = "Убийте 12 манасплесків за відведений час.", [4] = "Ти не {стать:вбив:вбила} необхідну кількість манасплесків, {ім'я:к}.", [5] = "В тебе вийшло! Я ні миті не сумнівалася в тобі! Добре, можливо, одну мить, чи дві... але загалом не сумнівалася.\n\nЧесно.", ["en"] = "Mana Surges", ["tasks"] = { ["Mana Surge"] = "манасплеск", ["Mana Surge slain"] = "манасплеск: убито" } },
    [1958] = { [1] = "Небесна сила", [5] = "Ти маєш пишатися собою, {ім'я:к}. Багато магів полягло від тварюк, з якими ти {стать:зіткнувся:зіткнулася}.\n\nНебесна сфера готова. Або, якщо хочеш, я можу закріпити її на посоху. Вирішуй {стать:сам:сама}. Я б обрала сферу, але хто я така, щоб вирішувати за тебе?", ["en"] = "Celestial Power" },
    [1959] = { [1] = "Звіт для Анастасії", [2] = "Маги Підмістя помітили порушення магії у місті та надіслали повідомлення магам Орди, щоб дослідити це явище.\n\nАнастасія Гартвелл зможе розповісти тобі більше деталей. Поговори з нею у кварталі Магіі в Підмісті.", [3] = "Поговоріть з Анастасією Гартвелл.", [5] = "Це правда. Було виявлено порушення магії у нашому місті. Ми ще не впевнені в його походженні або в тому, чи є воно згубним, чи доброякісним. Треба зібрати більше інформації...\n\nІ це, {ім'я:к}, підводить нас до твого завдання.", ["en"] = "Report to Anastasia" },
    [196] = { [1] = "Мистецтво полювання на рапторів", [2] = "Подивимось, як ти впораєшся з наступним завданням. Тут проживає хитра порода рапторів. Ми звемо їх ловцями джунглів. Їх набагато складніше вистежити та вбити, на відміну від тих, з якими тобі вже доводилося мати справу. Вбий 10 ловців джунглів і ти будеш {стать:найкращим мисливцем:найкращою мисливицею} на рапторів.", [3] = "Гемет Ернінґвей хоче, щоб ви вбили 10 ловців джунглів.", [4] = "Ти ба! Чого ти стоїш тут, {ім'я}! {стать:Справжній мисливець:Справжня мисливиця} на великих звірів ніколи не здається, поки в {стать:його:її} полі зору є здобич. Ці ловці джунглів не прибіжать самі та не кинуться в багаття. Дурне {стать:хлопчисько:дівчисько}.", [5] = "Хо-хо!! У нас є {стать:справжній:справжня} убивця рапторів! Молодець, {стать:старий:стара}!", ["en"] = "Raptor Mastery", ["tasks"] = { ["Jungle Stalker"] = "ловець джунглів", ["Jungle Stalker slain"] = "ловець джунглів: убито" } },
    [1960] = { [1] = "Розслідування в лавці алхіміка", [2] = "У лавці алхіміка Елджернона в Апотекарії відбуваються дивні речі. Невидимі створіння, створені виключно з магії, блукають по лавці. Для цього має бути якась причина, і ми маємо її знайти!\n\nРозслідуй порушення та злови цих створінь. Візьми скрині стримування та закляття прояву за мною. Скористайся закляттям у лавці, щоб розсіяти їхню невидимість, здолай їх, а потім кинь скриню стримування, щоб їх зловити. Повернись із заповненими скринями стримування, ящиком та закляттям прояву.", [3] = "Візьміть закляття прояву та ящик зі скринями стримування за спиною в Анастасії Гартвелл. Принесіть 3 заповнені скрині стримування, ящик зі скринями стримування та закляття прояву до Анастасії в Підмістя.", [4] = "Ти {стать:був:була} у лавці, {ім'я:к}? Тобі вдалося спіймати створінь?", [5] = "Дуже добре, {ім'я:к}. Ці створіння, що знаходяться в скринях стримування, будуть вивчені нашими кращими вченими та ми зрозуміємо що вони роблять в Підмісті.\n\nЯкщо їх поява викликана розломом у природному потоці магії, то ми повинні зрозуміти, чи був цей розрив випадковим. Якщо ж це було не випадковістю, а нападом якоїсь магічної сили, то ми повинні підготуватися до майбутніх, більш серйозних порушень.", ["en"] = "Investigate the Alchemist Shop", ["tasks"] = { ["Cantation of Manifestation"] = "закляття прояву", ["Cantation of Manifestation (Provided)"] = "закляття прояву (видано)", ["Chest of Containment Coffers"] = "ящик зі скринями стримування", ["Chest of Containment Coffers (Provided)"] = "ящик зі скринями стримування (видано)", ["Filled Containment Coffer"] = "заповнена скриня стримування", ["Filled Containment Coffer (Provided)"] = "заповнена скриня стримування (видано)" } },
    [1961] = { [1] = "Збір матеріалів", [2] = "Настала пора тобі одягнути свою першу мантію {клас:р}. Вона є знаком твого статусу та свідченням твоєї цінності.\n\nЩоб отримати мантію, тобі необхідно зібрати самоцвіти мани у даларанських магів у Срібнохвої. Їхні переконання схожі на наші, тому вбивати їх дещо неприємно, але якщо їм бракує сил, щоб протистояти нам, то вони не заслуговують на життя.\n\nПринеси кристали та льон Йосипу Ґреґоряну в лавку кравця, що у кварталі Магії.", [3] = "Принесіть 10 відрізів лляної тканини та 6 даларанських самоцвітів мани Йосипу Ґреґоряну.", [4] = "Анастасія сказала, що ти завітаєш до мене, і я готовий пошити для тебе мантію. У тебе є кристали та льон?", [5] = "Це дуже якісний матеріал, і хоча мені не вистачає таланту, щоб оцінити якість цих самоцвітів мани, незабаром ми дізнаємося, чи підходять вони для створення мантії заклинання вогню...", ["en"] = "Gathering Materials", ["tasks"] = { ["Dalaran Mana Gem"] = "даларанський самоцвіт мани", ["Dalaran Mana Gem (Provided)"] = "даларанський самоцвіт мани (видано)", ["Linen Cloth"] = "лляна тканина", ["Linen Cloth (Provided)"] = "лляна тканина (видано)" } },
    [1962] = { [1] = "Мантія заклинателя", [5] = "Ось твоя мантія, {ім'я:к}. Носи її із задоволенням.", ["en"] = "Spellfire Robes" },
    [197] = { [1] = "Мистецтво полювання на рапторів", [2] = "Оскільки ти добре {стать:проявив:проявила} себе в джунглях, дозволь мені розповісти про лютого хижака, якого навіть мені не вдалося вбити. Барвина зве цього хитрого раптора Тетісом.\n\nЯкщо ти хочеш проявити справжню майстерність, вбий Тетіса і принеси мені його кіготь. Це буде подвиг, якого ще не робив жоден мисливець на великих звірів.", [3] = "Гемет Ернінґвей хоче, щоб ви вбили Тетіса, невловного і небезпечного раптора Тернистої долини.", [4] = "Як просувається полювання на Тетіса? Сліди привели до нашого табору, ге?", [5] = "{стать:Майстер:Майстриня} {ім'я}, убивця рапторів!\n\nГарно звучить, чи не так?", ["en"] = "Raptor Mastery", ["tasks"] = { ["Talon of Tethis"] = "кіготь Тетіса", ["Talon of Tethis (Provided)"] = "кіготь Тетіса (видано)" } },
    [201] = { [1] = "Пошук табору", [2] = "Я отримав повідомлення про групу мисливців, які отаборилися вище по ріці від рудника ТзНБ \"Авантюра\", біля озера Назферіті. Я б не звернув на це уваги, але мене схвилювало те, що серед цих мисливців був Гемет Ернінґвей. Він має хороші зв'язки, тож краще заздалегідь підстелити соломку, якщо ти розумієш, про що я.\n\nЧому б тобі не зазирнути в цей табір та не дізнатись, що вони там роблять?", [3] = "Знайдіть табір мисливців і повідомте про його місцезнаходження Кронжеку з Грабіжної Бухти.", [4] = "Ну що? Ти {стать:знайшов:знайшла} табір?", [5] = "Хмм, отже, в мене була правдива інформація, як завжди. Цікаво. Ну, я не думаю, що вони становлять якусь загрозу для нашої роботи, але, можливо, вони захочуть дістати наші чудові товари. Хм...", ["en"] = "Investigate the Camp", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Locate the hunters' camp"] = "Знайдіть табір мисливців" } },
    [2018] = { [1] = "Випробування Рокара", [2] = "Ага, то тепер Терзок посилає мені своїх учнів-початківців, га? Що ж, гадаю, я можу навчити тебе кількох речей. Не те щоб я надто переймався твоїми справами, просто не хочу, щоб твоя смерть була на моїй совісті.\n\nАле спершу ти маєш довести мені, що ти цього {стать:вартий:варта}.\n\nЯ скажу тобі, {ім'я}. Мені не дуже подобається ця ТзНБ \"Авантюра\". Ці землі нагадують мені Дренор і мені не подобається, що ці гобліни їх нищать. Можливо, якщо вбити їхнього розпорядника в Драговині шламу, їх операція накриється мідним тазом.", [3] = "Вбийте розпорядника Ґліббі та поверніть його свисток Рокару Тінелезу в Дуротар.", ["en"] = "Rokar's Test" },
    [2019] = { [1] = "Професійні інструменти", [2] = "Ось, {ім'я}. Вони будуть тобі добре слугувати. Я зробив їх своїми руками, тож можу заприсягтися: кращих ти не знайдеш.\n\nНе турбуй мене розповідями про свої справи. Плани Терзока мене не цікавлять, я тепер у відставці й хочу жити спокійно.\n\nЯкщо раптом тобі знадобляться нові інструменти — приходь до мене. Але краще бережи ці!", [3] = "Поговоріть з Терзоком в Розколині Тіні в Орґріммарі.", ["en"] = "Tools of the Trade" },
    [2041] = { [1] = "Розмова з Шоні", [2] = "Можливо... Можливо, ти можеш допомогти нам у битві за Гномреґан.\n\nУ Штормовії ти знайдеш командира нашої підземного штурмового загону, Шоні Мовшунку. Їх потрібна допомога з гіробурорийками.\n\nТи знайдеш її серед дворфів у Штормовії.\n\nУдачі, {ім'я}.", [3] = "Поговоріть з Шоні Мовшункою в Штормовії.", [5] = "У тебе є повідомлення від центрального командування?", ["en"] = "Speak with Shoni" },
    [206] = { [1] = "Май'Зот", [2] = "Можливо, Курцен і мертвий, але те, що штовхнуло його на зло, все ще живе! Завдяки проведеним дослідженням, мені вдалося дізнатись про огра-мага Май'Зота, що мешкає в кургані огрів в східних горах Тернистої долини. Ходять чутки, що він використовує магію, яка контролює розум і я впевнений, що це він вплинув на Курцена.\n\nЯкщо залишити Май'Зота в живих, його зло може вплинути на інших і навіть спричинити появу ще одного Курцена.\n\nВбий його і принеси мені Око Розуму. Це артефакт, який він використовує, щоб спотворювати інших.", [3] = "Принесіть Око Розуму до брата Німіца в табір Повстання.", [4] = "Я дарую тобі своє благословення. Силу Май'Зота можна порівняти лише з його злом.", [5] = "Так! У тебе вийшло! Ти — велика сила добра, {ім'я}, і нехай твоя сила ніколи не згасне!\n\nЯ вивчу Око Розуму і дізнаюсь, чи можна його використовувати в благих цілях. Якщо ж ні... тоді воно має бути знищене.", ["en"] = "Mai'Zoth", ["tasks"] = { ["Mind's Eye"] = "Око Розуму", ["Mind's Eye (Provided)"] = "Око Розуму (видано)" } },
    [2078] = { [1] = "Помста Гірощогла", [2] = "Сухопутне створіння, ти маєш знайти мого першого помічника.\n\nВізьми цей ключ, встав йому в макітру і приведи сюди, щоб він служив своєму капітану.\n\nЦим мурлокам та їхньому вождю не сподобається, коли до них дістанеться мій помічник!", [3] = "Знайдіть першого помічника Гірощогла, Молотовбиватора 4100, і приведіть його до Ґелкака.", [4] = "Де мій перший помічник, {ім'я}? Підеш на корм рибам, якщо не поквапишся!", [5] = "Яррр, сухопутне створіння... Видно, море тобі не чуже.\n\nКапітан мо' навіть дозволить тобі мити палубу, якщо продовжиш у тому ж дусі...", ["en"] = "Gyromast's Revenge", ["tasks"] = { ["Gelkak's First Mate"] = "Перший помічник Гелкака", ["Gelkak's First Mate (Provided)"] = "Перший помічник Гелкака (видано)", ["Gelkak's First Mate slain"] = "Перший помічник Гелкака: убито" } },
    [208] = { [1] = "Мисливець на велику здобич", [2] = "{Ім'я}, ти {стать:мисливець, гідний:мисливиця, гідна} нашої компанії. Чи то на полях битви Лордерону, чи в найглибших джунглях, мені рідко доводилось бачити таку майстерність володіння зброєю, яку ти {стать:продемонстрував:продемонструвала}.\n\nТи {стать:вбив:вбила} лютого Сін'Далла, невловну Баґ'тіру і підступного Тетіса. Але справжня нагорода — це голова короля Банґалаша. Цей білий тигр — причина, чому я тут. Я вже давно слідкую за ним. Вбий короля Банґалаша і тобі не буде рівних в мисливській майстерності.", [3] = "Гемет Ернінґвей хоче, щоб ви принесли йому голову короля Банґалаша, великого білого тигра.", [4] = "Бачу, ти {стать:повернувся, старий:повернулася, стара}. Король Банґалаш не раз змушував мене приповзати назад до табору. Тримайся там.", [5] = "Молодець, чорт забирай! Так! Вітаю тебе, {ім'я}, ти {стать:досяг:досягла} успіху там, де інші зазнали невдачі.\n\nДля мене велика честь бачити тебе в рядах нашого великого мисливського загону. Ніхто ніколи не сумніватиметься у твоїх вміннях полювання та вистежування!\n\nВип'ємо за тебе! Будьмо!", ["en"] = "Big Game Hunter", ["tasks"] = { ["Head of Bangalash"] = "голова Банґалаша", ["Head of Bangalash (Provided)"] = "голова Банґалаша (видано)" } },
    [209] = { [1] = "Ікла Черепотрощителів", [2] = "Вбивати достатню кількість тигрів, щоб експортувати тигрові ікла на острови Південних морів, дорого і важко. На щастя, ми розробили техніку, яка дозволяє нам брати звичайні іклоподібні предмети та перетворювати їх на ідеальні підробки.\n\nЄдине, що найкраще підходить, як не дивно — це ікла тролів з племені Черепотрощителів.\n\nПерш ніж ти щось скажеш, я додам, що чим менше покупець знає, тим краще він спить, чи не так? Принеси мені їх якомога більше, щоб ми могли підготувати партію ікл!", [3] = "Добудьте 18 ікл Черепотрощителів і принесіть їх Кебоку.", [4] = "Міцні виродки, чи не так? Ну, що, як успіхи? Вибач за нетерплячість, але це не дає мені покою! То що?", [5] = "Молодець, молодець! Хоч можна було й краще почистити... Ну, неважливо, неважливо! Дякую тобі, {ім'я}. Завдяки тобі наша робота почне просуватись більшими темпами, а наша продуктивність зросте! Добре, добре, а тепер до інших справ...", ["en"] = "Skullsplitter Tusks", ["tasks"] = { ["Skullsplitter Tusk"] = "ікло Черепотрощителя", ["Skullsplitter Tusk (Provided)"] = "ікло Черепотрощителя (видано)" } },
    [2098] = { [1] = "Допомога Гірощоглу", [2] = "Життя пірата нелегке, сухопутне ти створіння. Це не тільки грабунки та випивка! На жаль, мій корабель затонув біля самого берега через цих клятих молотодонів.\n\nЩо мені потрібно, так це щоб мій перший помічник був у робочому стані!\n\nКоли мене прибило до берега, ключ від мого першого помічника розбився об каміння і його частини розтягли чудовиська Темнобережжя. Краєм ока я бачив, як розлючені рифові повзуни, велетенські лісобіги та мурлоки нишпорили в уламках корабля...", [3] = "Знайдіть три фрагменти ключа Ґелкака та принесіть їх Ґелкакові Гірощоглу.", [4] = "Ну що, {стать:сухопутний:сухопутна}, вдалось знайти частини ключа?", [5] = "Ахой, {стать:моряче:морячко}! Тобі вдалося! Скоро мій перший помічник буде в порядку. Ці тварюки ще не знають, що на них чекає!\n\nДо речі, ти не {стать:бачив:бачила} мого першого помічника?", ["en"] = "Gyromast's Retrieval", ["tasks"] = { ["Bottom of Gelkak's Key"] = "нижня частина ключа Ґелкака", ["Bottom of Gelkak's Key (Provided)"] = "нижня частина ключа Ґелкака (видано)", ["Middle of Gelkak's Key"] = "середня частина ключа Ґелкака", ["Middle of Gelkak's Key (Provided)"] = "середня частина ключа Ґелкака (видано)", ["Top of Gelkak's Key"] = "верхня частина ключа Ґелкака", ["Top of Gelkak's Key (Provided)"] = "верхня частина ключа Ґелкака (видано)" } },
    [2118] = { [1] = "Зачумлені землі", [2] = "Хвороба поширюється по Темнобережжю, захоплюючи розум і тіло всіх, кого вона торкається.\n\nНа татарних ведмедів вона подіяла особливо сильно. Колись благородні звірі стали знаряддям знищення — скаженими та несамовитими. Можливо, я маю ліки проти цієї недуги.\n\nВіднеси цю пастку до лісу і поклади її на землю. Будь-який скажений татарний ведмідь, який потрапить у неї, на короткий час стане слухняним. У такому стані він буде йти за тобою. Приведи його сюди, {ім'я}.", [3] = "Спіймайте живого скаженого татарного ведмедя та приведіть його до Тарнаріуна.\n\nЯкщо вам не вдасться спіймати скаженого татарного ведмедя і ви втратите пастку, поверніться до Тарнаріуна і попросіть ще одну.", [4] = "Ти {стать:привів:привела} хвору тварину, {ім'я}?\n\nЯкщо пастка не спрацює, не засмучуйся — надія Тарнаріуна вічна. Якщо тобі потрібна інша пастка — відмовся від завдання і поговори зі мною знову.", [5] = "Це лише початок, {ім'я}. Ти {стать:готовий:готова} до наступного завдання?", ["en"] = "Plagued Lands", ["tasks"] = { ["Rabid Thistle Bear Captured"] = "Скаженого ведмедя-будькуха спіймали", ["Rabid Thistle Bear Captured (Provided)"] = "Скаженого ведмедя-будькуха спіймали (видано)", ["Rabid Thistle Bear Captured slain"] = "Скаженого ведмедя-будькуха спіймали: убито" } },
    [212] = { [1] = "Страва, що подається холодною", [2] = "Однією з моїх найвідоміших страв є охолоджений василіск під лаймовим соусом вінегрет. Але проблема в тому, що... м'ясо неможливо зберегти свіжим, і я повинен подати страву сьогодні ввечері на день народження вельможі!\n\nОтже, якщо ти швидко принесеш мені охолоджене стегно щойно вбитого холодноокого василіска, я буду винен тобі королівський бенкет!\n\nХолодноокі василіски бродять вздовж пляжних дюн північно-західної Тернистої долини, тож шлях буде неблизький. Поспіши!", [3] = "Вбийте холодноокого василіска, візьміть охолоджене стегно василіска та поверніться до Анґуса Штерна в \"Синього відлюдника\".\n\n<Ваш дух не має покинути тіло, щоб успішно виконати завдання.>", [4] = "{ім'я}! Ти {стать:приніс:принесла} стегно? Мені треба скоро почати його готувати, інакше бенкет не вдасться!", [5] = "Ах, це чудове стегно! Дуже-дуже дякую!\n\nА тепер, вибач, я ще маю нарізати, замаринувати та прикрасити стегно для бенкету.", ["en"] = "A Meal Served Cold", ["tasks"] = { ["Chilled Basilisk Haunch"] = "охолоджена гомілка василіска", ["Chilled Basilisk Haunch (Provided)"] = "охолоджена гомілка василіска (видано)" } },
    [213] = { [1] = "Вороже поглинання", [2] = "Цього разу він зробив це! Мало того, що Ґелріз тисне на управителів, призначених торговими принцами, тепер він ще й намагається втрутитися в справи найвідомішого пірата!\n\nРевілґаз цього не допустить, він сказав мені, щоб я вирішив проблему будь-яким способом.\n\nЯким саме способом? Я обираю крадіжку! Геологи ТзНБ \"Авантюра\", що працюють біля озера Назферіті, цікавляться дивними блакитними кристалами, які вони знаходять у шахтах. Принеси мені зразки каменів від їхніх геологів і мені байдуже, що тобі доведеться зробити, щоб їх дістати.", [3] = "Добудьте 8 галтованих кристалів і принесіть їх Кебоку в Грабіжну Бухту.", [4] = "Мені потрібні ті камінці, {ім'я}. За будь-яку ціну! Просто зроби це, не розповідай мені подробиць!\n\nТільки результат, {ім'я}, ні більше, ні менше.", [5] = "Чудово. Те, що кристали були галтовані, може свідчити лише про те, що вони планують використовувати їх як якесь паливо або як каталізатор. Більше я нічого не знаю. Зразки треба буде відправити головному хіміку Сміхопису.", ["en"] = "Hostile Takeover", ["tasks"] = { ["Tumbled Crystal"] = "галтований кристал", ["Tumbled Crystal (Provided)"] = "галтований кристал (видано)" } },
    [2138] = { [1] = "Очищення зарази", [2] = "Як я і боявся, ліки не працюють.\n\nМені дуже прикро наказувати вбивати будь-яких створінь природи, але хворих татарних ведмедів доведеться винищити.\n\nПовертайся до лісу і знищ 20 скажених татарних ведмедів, {ім'я}. Це, звичайно, не зупинить заразу, але на короткий час стримає шкоду, яку тварини завдають нашому лісу та його мешканцям.", [3] = "Очистіть ліс від 20 скажених татарних ведмедів та поверніться до Тарнаріуна Дереволюба в Аубердін.", [4] = "Ти {стать:виконав:виконала} завдання?", [5] = "Ти гарно {стать:послужив:послужила} Аубердіну, {ім'я}, але твоя робота ще не завершена.\n\nПовертайся до мене, коли відпочинеш.\n\n...і {ім'я}, підготуй свій розум і душу до нового кровопролиття.", ["en"] = "Cleansing of the Infected", ["tasks"] = { ["Rabid Thistle Bear"] = "скажений татарний ведмідь", ["Rabid Thistle Bear slain"] = "скажений татарний ведмідь: убито" } },
    [2139] = { [1] = "Надія Тарнаріуна", [2] = "Добробут нашого народу та земель дається нам дуже дорогою ціною, {ім'я}.\n\nТи {стать:пролив:пролила} кров слуг природи, вбивши багатьох хворих тварин. Народ Аубердіна в боргу перед тобою — страждання лісу полегшились, хоч і ненадовго.\n\nУ мене є для тебе останнє завдання, але попереджаю: тобі знову доведеться вбивати. Сподіваюсь, я востаннє прошу тебе про це, {ім'я}.\n\nУ печері на північному сході, біля Башал'Арану, живе Мати лігва. Вбий її.", [3] = "Знайдіть і вбийте Мати лігва.", [4] = "Зі смертю зараженої Матері лігва, популяція скажених татарних ведмедів в наших землях має зменшитись. Не гаймо часу, {ім'я}.", [5] = "Ти хоробро {стать:бився:билася} за Аубердін, {ім'я}. На наших змучених війною землях смерть і відчай — звичні явища. Багато хто вже не намагається прийняти виклики в нашому новому домі, їхній вибір — ховатися у своїх домівках або тікати до більш укріплених земель Альянсу.\n\nДякую тобі, {ім'я}. Можливо, колись ми з тобою будемо битися пліч-о-пліч проти іншого ворога.", ["en"] = "Tharnariun's Hope", ["tasks"] = { ["Den Mother"] = "Мати лігва", ["Den Mother slain"] = "Мати лігва: убито" } },
    [2178] = { [1] = "Легке життя бігунів", [2] = "Чуєш цей смачний аромат? Це мій секретний рецепт, {ім'я} — свіжий гуляш з бігунів. Смакота!\n\nМожливо, тобі буде цікаво навчитися його готувати?\n\nПерш ніж я тебе навчу, ти маєш довести, що впораєшся з цими звірами.\n\nНе потрібно йти приручати їх і приїжджати на них до мене, але якщо ти зможеш вбити кількох і принести їхнє соковите м'ясо, я зможу відкрити тобі секрети приготування гуляшу з бігунів.", [3] = "Принесіть 5 шматків м'яса бігунів Аланндаріан Нічній Пісні в Аубердін.", [4] = "Каструля порожня, а я голодна! Чого ти так довго?", [5] = "Неймовірно! Спробуй {стать:сам:сама}, {ім'я}!", ["en"] = "Easy Strider Living", ["tasks"] = { ["Strider Meat"] = "м'ясо бігуна", ["Strider Meat (Provided)"] = "м'ясо бігуна (видано)" } },
    [220] = { [1] = "Поклик води", [2] = "Іслен доручить тобі ще одне завдання, перш ніж нагородити тебе наступним тотемом. Для цього завдання тобі знадобиться фіал з водою, що я тобі дала.\n\nЙди, поговори з нею. З тобою ми ще колись зустрінемося знову.", [3] = "Принесіть фіал найчистішої води до Іслен Морської Провидиці у Степи.", [4] = "І знову привіт, {ім'я}. Виглядаєш ти непогано.\n\nЩо привело тебе до мене так скоро?", [5] = "А, фіал з водою, створений і освячений Бріною і, звісно ж, зібраний тобою.\n\nРідина в цьому фіалі необхідна для створення сапти, але також згодиться й для іншого завдання.\n\nСапта, яку я створю для тебе, потрібна, щоб побачити духів води у святилищі в Срібнохвойному пралісі, на південь від Підмістя. Щодо води, що залишилася — добре, що ще є кілька крапель — я розповім тобі пізніше, коли ти відчуєш, що {стать:готовий:готова}.\n\nТи {стать:готовий:готова} до ще однієї подорожі, {ім'я}?", ["en"] = "Call of Water", ["tasks"] = { ["Vial of Purest Water"] = "фіал найчистішої води", ["Vial of Purest Water (Provided)"] = "фіал найчистішої води (видано)" } },
    [2200] = { [1] = "Повернення до Ульдаману", [2] = "Мій конкурент пустив чутки, що паладина прокляло моє намисто. Ясно, що ніхто не захоче купувати у ювеліра прокляті речі.\n\n{Ім'я}, давай домовимось — знайди самоцвіти, і я відновлю намисто, але за умови, що ти розкажеш усім, що на моїх виробах НЕМАЄ ніякого прокляття!\n\nСпробуй пошукати зачіпки в Ульдамані. Можливо, подивись, чи є там тіло паладина, адже він, як ми знаємо, був останнім, хто володів намистом! Коли знайдеш камені — скористайся цим і я зможу зв'язатись з тобою з Залізогарту.", [3] = "Знайдіть зачіпки щодо місцеперебування самоцвітів з намиста Талваша в Ульдамані. Вбитий паладин, про якого він згадував, був останнім власником цього намиста.", [5] = "Читаючи щоденник, стає зрозуміло, що після довгих зусиль паладин визначив місцеперебування всіх трьох зниклих самоцвітів:\n\nДворфи Тінегарту сховали рубін на своїй забарикадованій території, коли билися з трогами за контроль над Ульдаманом.\n\nТроги сховали топаз в урні, під боком у несподіваних мешканців Ульдаману — дворфів Альянсу!\n\nЗрештою, сам старійшина трогів привласнив сапфір.", ["en"] = "Back to Uldaman", ["tasks"] = { ["Talvash's Phial of Scrying"] = "фіал провидіння Талваша" } },
    [2205] = { [1] = "Пошуки ШУР", [2] = "Значок? А, це дурниця, рибко — нічого такого, з чим би ти не {стать:впорався:впоралася}. Судячи з того як ти виглядаєш, Матіас міг би прийняти тебе за {стать:торговця:торговку} сиром, а не за {стать:справжнього пройдисвіта:справжню пройдисвітку}. Проте у мене є для тебе робота, яку необхідно виконати.\n\nКоротко кажучи, достав цей пакунок Матіасу, і він, можливо, дасть тобі кілька завдань.\n\nХутчіше!", [3] = "Доставте пакунок Керіни Сільвії майстру Матіасу Гичу в бараки Штормовія.", [4] = "Чим я можу тобі допомогти, {клас:к}?", [5] = "Отже, тобі вдалося мене знайти. Дивлячись на тебе, я б сказав, що для тебе це було серйозним випробуванням як фізичних сил, так і розумових здібностей.\n\nНу що, попросити Рензіка показати тобі, де тут корчма, чи ти одразу візьмешся за роботу?", ["en"] = "Seek out SI: 7", ["tasks"] = { ["Delivery to Mathias"] = "пакунок для Матіаса", ["Delivery to Mathias (Provided)"] = "пакунок для Матіаса (видано)" } },
    [2238] = { [1] = "Прості хитрощі", [2] = "Розумієш, король вигрібає з шахти руду й коштовне каміння. Таких багатств жоден дворф за десять життів не побачить.\n\nУ Прихованого Кола є свої цінності, {ім'я}. Ми цінуємо цінності. Січеш?\n\nТепер ми вважаємо, що король має поділитися з нами, але ми не хотіли б, щоб \"Гузнобородий\" знав про це, якщо ти розумієш про що я.\n\nНам потрібно, щоб ти {стать:переговорив:переговорила} з Оніном Мак-Гаммаром в Гномреґані та {стать:повернувся:повернулася} зі звітом. Цей хитрий дворф сховався серед прокажених. Будь {стать:обережний:обережна}.", [3] = "Знайдіть Оніна Мак-Гаммар в Гномреґані.", [5] = "Тссс! Тихіше будь, довбешка. Вони ж почують нас.", ["en"] = "Simple Subterfugin'" },
    [2239] = { [1] = "Звіт Оніна", [2] = "Кар'єр? Йо, я постійно бачу, як ці страхітливі броньовані парові танки проїжджають повз цей пост кожного дня.\n\nМої інформатори на сході кажуть, що танк виїжджає з Залізогарту, заїжджає в кар'єр Ґол'Болар, зупиняється в Хараносі, щоб дозаправитися, а потім з якоїсь клятої причини робить кругаля навколо Гномреґану, перш ніж розвантажитись у Залізогарті.\n\nВсе це є у звіті, {раса:к}. Віднеси його Гульфдану — він зможе спланувати наступний крок.", [3] = "Принесіть звіт Оніна до Гульфдана Чорнобородого в Залізогарт.", [4] = "Тобі подобається сморід лепрогномів? Я питаю, бо у тебе якась божевільна посмішка на пиці.\n\nЯкі новини ти {стать:приніс:принесла} від Оніна?", [5] = "Великий гак через Гномреґан? Клянуся власною бородою!\n\nТи добре {стать:впорався:впоралася}, {ім'я}. Візьми цей кинджал та чухай звідси. Коло покличе тебе знову, коли буде готовий третій крок.\n\nЩо за третій крок? Та той, що йде після другого, а саме — я даю копняка тобі під зад.\n\nХочеш?", ["en"] = "Onin's Report", ["tasks"] = { ["Onin's Report"] = "звіт Оніна", ["Onin's Report (Provided)"] = "звіт Оніна (видано)" } },
    [2241] = { [1] = "Квіт серця", [2] = "Кажуть, що я без тями від кохання...\n\nТак, я весь час думаю про Сіарну. Так, весь мій дім вкритий картинами та малюнками Сіарни. Так, я часто не їм, не сплю й не п'ю, а тільки й думаю про кохання, яке могло б у нас бути. Хіба це так погано?\n\nТепер вона не побачить мене! МЕНЕ! Я намагався надсилати їй листи, але вона навіть не буде говорити ні з ким, тільки якщо вони не пройдисвіти.\n\nТи не {стать:міг би:могла б} передати їй цю квітку? Не забудь сказати, що це від Яннока.", [3] = "Віддайте троянду Яннока Сіарні в Дарнасі.", [4] = "Оу, хіба це не прекрасно? Ти {стать:приніс:принесла} квіти на власний похорон.", [5] = "Якби я зберігала кожну квітку, яку дарував мені цей бовдур Яннок, я могла б вже відкрити цілу крамницю! Проте, схоже останній посланець Яннока може виявитися корисним.\n\nЦікавить робота, {клас:к}?", ["en"] = "The Apple Falls", ["tasks"] = { ["Jannok's Rose"] = "троянда Яннока", ["Jannok's Rose (Provided)"] = "троянда Яннока (видано)" } },
    [2259] = { [1] = "Еріон Тінешепіт", [2] = "Не переймайся, {ім'я}, я не відправляю тебе до Сіарни. Еріон вимагає твоєї присутності в Кенарійському Анклаві. Не зволікай!", [3] = "Зв'яжіться з Еріоном Тінешепотом в Дарнасі.", [5] = "Час іти далі, {раса:к} — світ чекає.", ["en"] = "Erion Shadewhisper" },
    [2278] = { [1] = "Платинові диски", [2] = "Головним елементом цієї скарбниці є чотири платинові диски, вкриті численними символами невідомого походження. Доторкнувшись до них, ви відчуваєте поколювання в пальцях, після чого перед вами з'являється великий кам'яний наглядач.\n\n\"Вітаю. Я хранитель знань. Історія створення Творцями земельників була збережена для цього світу на дисках Норґаннона.\"\n\nВи відкрили скарбницю з раніше невідомими світу знаннями.", [3] = "Поговоріть з кам'яним наглядачем і дізнайтесь, які древні знання він зберігає, після чого активуйте диски Норґаннона.", [4] = "Голос кам'яного наглядача, здається, пронизує все ваше тіло:\n\n\"Для початку, вам необхідно пройти перевірку для доступу до дисків Норґаннона. Щойно ви виконаєте всі вимоги, вам буде дозволено отримати портативну копію збережених даних. Будь ласка, переконайтесь, що повністю вивчили це сховище.\"", [5] = "Виконуючи вказівки кам'яного наглядача, ви знову активуєте диски Норґаннона, вже знаючи історію земельників, трогів та дворфів. Від дисків доноситься короткий слабкий гул. Після чого кам'яний наглядач каже:\n\n\"Диски синтезовано. Для отримання особистої копії знову активуйте диски Норґаннона.\"", ["en"] = "The Platinum Discs", ["tasks"] = { ["Learn what lore that the stone watcher has to offer"] = "Дізнайтеся, які знання може запропонувати спостерігач за каменем" } },
    [2280] = { [1] = "Платинові диски", [2] = "Дотик до дисків Норґаннона знову викликає поколювання у ваших пальцях. Однак, цього разу зсередини дисків доноситься гучний скрегіт.\n\nВаш рюкзак раптово стає тяжче. Всередині ви знаходите мініатюрну версію дисків!\n\nБез сумніву, такий предмет — безцінна знахідка для того, хто зацікавлений в древній історії Азероту. Мудреці Громового Бескиду — одні з таких істориків Орди. Можливо, вони знайдуть їм належне застосування.", [3] = "Віднесіть мініатюрну копію дисків Норґаннона до одного з мудреців у Громовий Бескид.", [4] = "Так, {стать:юний:юна} {клас:к}, я бачив, як ти рішуче {стать:йшов:йшла} до мого шатра. Ти {стать:прийшов:прийшла} по мою пораду заради важливої для Орди справи? Чи може ти хочеш розкрити таємниці всесвіту?", [5] = "Що це в тебе?\n\nНеймовірно, {стать:юний:юна} {клас:к}! Ці диски... Я відчуваю, що вони приховують давно втрачені таємниці. Дякую, що {стать:приніс:принесла} їх мені, це було дуже мудро з твоєї сторони.", ["en"] = "The Platinum Discs", ["tasks"] = { ["Miniature Platinum Discs"] = "мініатюрні платинові диски", ["Miniature Platinum Discs (Provided)"] = "мініатюрні платинові диски (видано)" } },
    [2282] = { [1] = "Лісопильня Альтера", [2] = "Саме тут ми роками тренуємо злодіїв! Зрештою, не {стать:кожен:кожна} {клас} народжується з такою спритністю та витонченістю, як старий Лукій.\n\nВище по дорозі ти знайдеш лісопильню Альтера. Я залишив там скриню, а в ній є дещо важливе. Забери це \"дещо\" та принеси мені! Принесеш мені жетон, і отримаєш свій сертифікат розбійництва!", [3] = "Відкрийте скриню Лукія, дістаньте жетон розбійництва та поверніть його Лукію в Приозер'я.", [4] = "Я ж не забув згадати про орків?\n\nЯ чув, що вони нишпорять біля лісопильні.", [5] = "Тобі вдалось відкрити скриню, чи не так? Гарна робота, {ім'я}.\n\nТепер якщо ти загинеш, ми будемо спокійні, знаючи, що це сталося через твою власну дурість, а не через недосвідченість.", ["en"] = "Alther's Mill", ["tasks"] = { ["Token of Thievery"] = "жетон розбійництва", ["Token of Thievery (Provided)"] = "жетон розбійництва (видано)" } },
    [2284] = { [1] = "Відновлення намиста, друга спроба", [2] = "Ці камені напевно залишилися десь в Ульдамані! Це так само вірно, як те, що Мальтон — бовдур. Тобі доведеться повернутися туди та розшукати їх.\n\nЯк я вже казав, якщо те, що нам розповідали — правда, то в намисті мали бути рубін, сапфір і топаз. Знайди їх і поверни в намисто.\n\nДе вони? А хто ж їх знає? Можливо, тобі пощастить і ти знайдеш труп того паладина. Можливо, вони все ще у нього, якщо його не обчистили.", [3] = "Знайдіть підказку про місцеперебування самоцвітів у надрах Ульдаману.", [5] = "Здається, вам вдалося знайти рештки паладина, про якого говорив Дран. Обшукавши їх, ви знаходите те, що, схоже, є його щоденником. Щоденник у поганому стані, більша частина сторінок залита кров'ю. Те, що ви можете прочитати, однак, є суцільною нісенітницею. Наскільки вам відомо, це мова людей.\n\nВам доведеться знайти того, хто зможе це перекласти.", ["en"] = "Necklace Recovery, Take 2" },
    [2298] = { [1] = "Королівська облава", [2] = "І ось зібралися ми вже планувати третій крок, як тут вломилися кілька бовдурів Магні, почали нести нісенітниці про якесь пограбування та арешт членів Захованого Круга.\n\nНіхто не посміє докучати Чорнобородому! Розбірка пішла неабияка, і якимось чином спливло твоє ім'я!\n\nХочеш пораду? Бери першого ж грифона з Залізогарту і дуй в Штормовій. Йди у Старе Місто і поговори з моїм старим приятелем — Рензіком \"Пером\".", [3] = "Відправляйтеся до Штормовію та знайдіть Рензіка \"Перо\".", [5] = "Завжди приємно мати одного з пройдисвітів Гульфдана в наших рядах!", ["en"] = "Kingly Shakedown" },
    [2299] = { [1] = "До Гульфдана!", [2] = "Де тебе носило, {ім'я}? Гульфдан всюди тебе шукав. Ми вже думали, що король закував тебе в кайдани.\n\nНегайно йди до Залізогарту та поговори з Гульфданом!", [3] = "Відправляйтеся до Залізогарту та поговоріть з Гульфданом Чорнобородим.", [5] = "Говори тихіше, {ім'я}, вартові можуть почути тебе.", ["en"] = "To Hulfdan!" },
    [2300] = { [1] = "ШУР", [2] = "Рензік шукав тебе, рибко.\n\nНа твоєму місці я б не змушувала його чекати — все-таки він права рука Матіаса.", [3] = "Відправляйтеся до Штормовію та знайдіть Рензіка \"Перо\".", [5] = "Ти вже {стать:готовий:готова} братися за роботу, чи тобі потрібен відпочинок перед тим, як ми розпочнемо?", ["en"] = "SI:7" },
    [2318] = { [1] = "Переклад щоденника", [2] = "Опинившись в глухому куті, ви розумієте, що вам потрібен переклад щоденника зрозумілою мовою. Безумовно, у світі знайдеться багато знавців людської мови. Найближче місце, де можна знайти когось — форпост Карґат, що у Безплідних краях. Можливо, варто почати звідти.", [3] = "Знайдіть когось, хто зможе перекласти щоденник паладина. Найближче місце для пошуків — Карґат, що у Безплідних краях.", [5] = "{стать:Могутній:Могутня} {клас:к}, я знаю, що ти робиш тут, у Безплідних краях. Я знаю, що тобі потрібен мій дар знання мов. Ти шукаєш частин намиста, яке {стать:знайшов:знайшла} в Ульдамані.\n\n{стать:Здивований:Здивована}? Не варто: знати такі речі — моя робота. Натомість обговорімо, що ти {стать:готовий:готова} зробити задля перекладу щоденника. Повір, я єдиний, хто зможе перекласти його.\n\nА ще краще, дозволь мені запропонувати дещо краще, ніж пропонує тобі Дран Дрофферс, і при цьому ти зможеш виконати його завдання. Ну що, {стать:зацікавлений:зацікавлена}?", ["en"] = "Translating the Journal", ["tasks"] = { ["Untranslated Journal"] = "неперекладений щоденник" } },
    [232] = { [1] = "Доручення аптекарки Зінґе", [2] = "Королівське товариство аптекарів потребує твоєї допомоги. Послухай мене, і ми обидва отримаємо вигоду.\n\nАптекар Ківер, що в сусідній кімнаті, мабуть, трохи... несповна розуму... але його дослідження можуть приносити плоди, якщо їх очолить розумніший дослідник. На щастя, я саме та, хто потрібен. Віднеси цей список покупок Алессандро Луці, власнику \"Дрібничок Синього Місяця\"; він має видати набір для тестування. Як отримаєш його — повертайся до мене і я розкажу про подальші кроки.", [3] = "Віднесіть список покупок Алессандро Луці в Підмісті.", [4] = "Так-так... я можу тобі чимось допомогти? Ти у справах Королівського товариства аптекарів чи просто {стать:прийшов:прийшла} скрасити мій день?", [5] = "О, Зінґе потрібне обладнання, чи не так? Шкода, що вона особисто не вшанувала мене своєю чарівною присутністю.\n\nНу що ж, давай я тобі його спакую.", ["en"] = "Errand for Apothecary Zinge", ["tasks"] = { ["Zinge's Purchase Order"] = "список покупок Зінґе", ["Zinge's Purchase Order (Provided)"] = "список покупок Зінґе (видано)" } },
    [2338] = { [1] = "Переклад щоденника", [2] = "Дрофферсам не стане розуму, щоб відновити магію в намисті, але я зможу це зробити. Все, що мені потрібно — вивчити намисто, щоб навчитися робити їх самостійно. Для цього мені потрібне твоє намисто. Дозволь мені позичити його на деякий час, а в обмін я перекладу для тебе щоденник. А поки ти шукатимеш камінці, у мене буде вдосталь часу на вивчення.\n\nЦя угода вигідна нам обом. Ну, що скажеш?", [3] = "Дозвольте Джаркалу позичити намисто. Натомість він перекладе для вас щоденник.", [4] = "Ти вже все {стать:обдумав:обдумала}, так? Ти {стать:розумний:розумна} {клас}, якщо погодишся на цю угоду — ми обоє одержимо те, що нам потрібно, а Дрофферси думатимуть, що і вони отримають своє.", [5] = "Це дійсно гарна угода — я знав, що можу розраховувати на тебе.\n\nЗачекай хвилинку, поки я накладу закляття, щоб швидко перекласти щоденник з людської мови на зрозумілу тобі. Я — троль свого слова; запитай кого хочеш в Орді про Джаркала Змішаного Моха, і тобі скажуть те ж саме. Ну що ж, почнімо...", ["en"] = "Translating the Journal", ["tasks"] = { ["Untranslated Journal"] = "неперекладений щоденник", ["Untranslated Journal (Provided)"] = "неперекладений щоденник (видано)" } },
    [2339] = { [1] = "Пошук самоцвітів та джерела сили", [2] = "Ось перекладений щоденник, можеш самостійно прочитати його. Там написано, що дворфи сховали рубін, троги — топаз, а трог на ім'я Ґрімлок привласнив сапфір.\n\nПослухай — тобі знадобиться джерело сили, щоб намисто знову запрацювало. Та Дран Дрофферс цього не знає. Щоб знайти таке джерело — спустись глибше в Ульдаман, знайди наймогутніше творіння і вбий його. Не сумніваюсь, ти знайдеш джерело сили у нього.\n\nКоли збереш все — повертайся сюди!", [3] = "Знайдіть всі три самоцвіти та джерело сили намиста в Ульдамані та принесіть їх Джаркалу Змішаному Моху в Карґат. Джаркал вважає, що джерело сили можна знайти у наймогутнішого творіння в Ульдамані.\n\nЗі щоденника ви знаєте, що...\n* Рубін схований на забарикадованій території Тінегарту.\n* Топаз захований в урні в одному з районів, зайнятих троггами, біля дворфів Альянсу.\n* Сапфір привласнив Грімлок, ватажок трогів.", [4] = "Якщо у тебе немає самоцвітів і джерела сили, здатного спрямувати магічну силу у намисто, на тебе чекає ще одна подорож до глибин Ульдаману.\n\nТи отримаєш самоцвіти, щоб передати їх цим бовдурам в Орґріммар, а я залишу собі джерело сили, оскільки саме воно змусить намисто працювати...", [5] = "Дуже добре, {клас:к}. Тепер плоди нашої праці окупляться сторицею. Я закінчив роботу над намистом і впевнений, що тепер зможу створити таке саме.\n\nАле спершу я використаю спеціальне заклинання, щоб швидко дослідити ці самоцвіти, перш ніж ти віднесеш їх і намисто назад до Орґріммару. Це займе лиш мить.", ["en"] = "Find the Gems and Power Source", ["tasks"] = { ["Shattered Necklace Power Source"] = "джерело сили пошкодженого намиста", ["Shattered Necklace Power Source (Provided)"] = "джерело сили пошкодженого намиста (видано)", ["Shattered Necklace Ruby"] = "рубін пошкодженого намиста", ["Shattered Necklace Ruby (Provided)"] = "рубін пошкодженого намиста (видано)", ["Shattered Necklace Sapphire"] = "сапфір пошкодженого намиста", ["Shattered Necklace Sapphire (Provided)"] = "сапфір пошкодженого намиста (видано)", ["Shattered Necklace Topaz"] = "топаз пошкодженого намиста", ["Shattered Necklace Topaz (Provided)"] = "топаз пошкодженого намиста (видано)" } },
    [2340] = { [1] = "Доставка самоцвітів", [2] = "Для намиста підійде будь-яка оправа та камені, головне, щоб вони були з тих же матеріалів. Однак саме це джерело сили поверне в нього магію... Сподіваюся.\n\nЯ з радістю віддам тобі камені, які підходять для намиста, якщо джерело сили дійсно працює.\n\nВирушай до Орґріммару і виконай свою частину угоди з Дрофферсами. Тільки нікому не кажи про нашу угоду, а коли повернешся — у мене буде для тебе чудовий сюрприз.", [3] = "Доставте намисто та самоцвіти Драну Дрофферсу в Орґріммар.", [4] = "Поглянь-но, хто прийшов! Бачу, ти не {стать:поспішав:поспішала} сюди. Будемо сподіватися, що ти не марно витрачаєш мій час! Ти не отримаєш платні, поки не принесеш все, що я просив, май це на увазі. І можеш не сумніватися — ми все перевіримо, і не один раз!", [5] = "Так, все на місці. Не проти, якщо ми залишимо сумку? Ні? Дякую, дуже тобі дякую! Ха!\n\nЦе намисто — наша найбільша здобич! Але не засмучуйся, я впевнений, що намисто тобі все одно не підійшло б. Ха!\n\nУгода є угода, тож ось твоя винагорода за трофеї. На цьому все, приходь пізніше, може, у нас буде ще робота. А поки забирайся геть!", ["en"] = "Deliver the Gems", ["tasks"] = { ["Necklace and Gem Salvage"] = "намисто і самоцвіти", ["Necklace and Gem Salvage (Provided)"] = "намисто і самоцвіти (видано)" } },
    [2358] = { [1] = "Роги Незри", [2] = "Багато років тому Роги Нез'ри були викрадені з маєтку Рейвенгольдт. Я шукав їх по всіх континентах і океанах, але виявив, що ці незначні істоти весь цей час володіли ними.\n\nВбивайте кожного орка Чорної Скелі, якого перетнете, доки не знайдете Роги Нез'ри. Якщо знайдете роги, знайдіть мене в Озерному Ширі.\n\nЗробіть це для мене, і ваше ім'я стане відомим Рейвенгольдту, {ім'я}.", [3] = "Поверніть Роги Нез'ри до Тіні Арантіра в Озерному Ширі.", [4] = "У тебе є роги демонічного принца?", [5] = "Заперечувати артефакт Рейвенгольдту означало б заперечувати власне існування. Молодець, {клас}. Ти ще можеш ходити серед убивць Рейвенгольдта.\n\nБудучи молодим розбійником, який мандрував по Темних Берегах, я відкрив чай, який відновлює енергію в бою. Він добре служив мені протягом багатьох років, і тепер я передаю тобі смак чаю з будяка. Пий його, коли втомишся, {ім'я}, і знову бийся з енергією!", ["en"] = "Horns of Nez'ra", ["tasks"] = { ["Horns of Nez'ra"] = "роги Нез'ри", ["Horns of Nez'ra (Provided)"] = "роги Нез'ри (видано)" } },
    [2359] = { [1] = "Вежа Клейвена", [2] = "Я вже кілька тижнів стежу за цією вежею, {ім'я}. Нещодавно сюди прийшов великий вантаж зі Смерколісся, а разом з ним і ці охоронці.\n\nХто вони такі? Ми можемо тільки здогадуватись. Можу сказати лиш одне — це не люди.\n\nТак чи інакше, у вантажі була скриня, яку, як я вважаю, ці потвори й охороняють. У зомбі з шипами є ключ, який нам потрібний.\n\nЗабери цей ключ, проберися у вежу та з'ясуй, що лежить у цій скрині. Віднеси свої знахідки Матіасу.", [3] = "Викрадіть ключ від вежі Непокірних, проникніть туди та дізнайтеся, що лежить в скрині Смерколісся. Отримайте будь-яку інформацію та поверніться до Матіаса Гича в Штормовій. Прочитайте записи Кірнен, щоб дізнатися більше про вежу.", [4] = "Є новини від Кірнен?", [5] = "Це пояснює присутність мерців Непокірних, яких ви з Кірнен бачили біля вежі, {ім'я}. Це також може пояснити причетність ТзНБ \"Авантюра\" і ці дивні вантажі зі Смерколісся.\n\nЗгідно з цією книгою, в Тернистій долині тролі Занзіла знайшли спосіб воскрешати мертвих завдяки зіллю... а точніше, отруті.\n\nВід тебе не буде користі в ШУР без знань про отрути, {ім'я}, особливо коли формула воскресіння мертвих майже в наших руках.", ["en"] = "Klaven's Tower", ["tasks"] = { ["Defias Tower Key"] = "ключ від вежі Непокірних", ["Defias Tower Key (Provided)"] = "ключ від вежі Непокірних (видано)", ["Klaven Mortwake's Journal"] = "щоденник Клейвена Мортвейка", ["Klaven Mortwake's Journal (Provided)"] = "щоденник Клейвена Мортвейка (видано)" } },
    [2360] = { [1] = "Матіас та Непокірні", [2] = "Ти ледь не {стать:запізнився:запізнилася}, {ім'я}. Розвідка ШУР звітує про незвичну активність Непокірних в Західному краї.\n\nСхоже, що вони захопили покинуту сторожову вежу Альянсу на південний схід від Сторожового пагорба і використовують її для контрабанди товарів з Багрянокряжжя.\n\nВідправляйся до Західного краю та зв'яжися з агентом Кірнен для доповіді. Ти знайдеш її поруч з вежею.\n\n...і, {ім'я}, якщо тебе викриють — ШУР заперечуватиме будь-який зв'язок з тобою.", [3] = "Знайдіть агента Кірнен в Західному краї та поговоріть з нею.", [5] = "Матіас нарешті відправив ще одного агента мені на допомогу, ге? Що ж, я сподіваюся, він готовий почути погані новини.", ["en"] = "Mathias and the Defias" },
    [2361] = { [1] = "Відновлення намиста", [5] = "Я з радістю вручаю тобі це намисто, {стать:могутній:могутня} {клас:к}. Ти неабияк {стать:допоміг:допомогла} мені, і я дякую тобі за це. Носи його з гордістю і не забувай розказувати всім, хто зробив його для тебе!\n\nТакож, якщо додаси, що на намисті немає прокляття, це буде зовсім чудово.", ["en"] = "Restoring the Necklace" },
    [2378] = { [1] = "Пошуки Розтрощеної Руки", [2] = "Ти добре {стать:послужив:послужила} Смертоловам, {ім'я}, але схоже, що настав тобі час рухатися далі. У тебе гарні здібності у непомітності та обмані, але тобі все ще потрібно багато тренуватися.\n\nУ Смертоловів є союзники серед Розтрощеної Руки. Йди до тих, хто зможе допомогти нам — знайди Шентула в Орґріммарі.", [3] = "Доберіться до Оргріммару та поговоріть з Шентулом в Розколині Тіні.", [5] = "Так ось кого могутні союзники прислали Шентулу? Якось не вражає...", ["en"] = "Find the Shattered Hand" },
    [2379] = { [1] = "Зандо'зан", [2] = "Однієї твоєї рішучості не вистачить, щоб подолати всі перешкоди, які чекають на нас.\n\nПоговори із Зандо'заном, щоб почати навчання як агент Розтрощеної Руки.\n\nТільки тоді, коли ти опануєш навички непомітності та злодійства, ти зможеш зробити наступний крок назустріч своєї долі.", [3] = "Поговоріть із Зандо'заном в Розколині Тіні.", [5] = "Можливо, Зандо'зан помилився. Зандо'зан просить вибачення.", ["en"] = "Zando'zan" },
    [238] = { [1] = "Доручення аптекарки Зінґе", [2] = "Набір готовий, {Ім'я}. Без сумніву, Зінґе потрібен цей набір якомога скоріше. Негайно віднеси це їй і додай, що витрати будуть покриті коштом Королівського товариства аптекарів. Також, будь ласка, передай їй мої найгарячіші вітання.\n\nЧого {стать:встав:встала}? Ти ж {стать:посильний:посильна} чи як?", [3] = "Принесіть набір для польових досліджень аптекарці Зінґе в Підмісті.", [4] = "Схоже, що Лука також схвильований. Але це не має значення, просто віддай мені набір для польових досліджень. Мені ще треба буде внести певні корегування і перевірити базові матеріали.\n\nТи ж маєш набір, чи не так?", [5] = "Добре! Таке задоволення — працювати з тими, хто не витрачає мій час даремно.\n\nПісля того як я зроблю правки в цьому наборі, ти будеш {стать:готовий:готова} до наступного завдання. З його допомогою потрібно буде зібрати важливі дані.\n\nЦе займе хвильку, я майже закінчила. А поки ти чекаєш, подумай, що тобі може знадобитися в пустелі.\n\nТак, про пустелю тобі не почулося.", ["en"] = "Errand for Apothecary Zinge", ["tasks"] = { ["Field Testing Kit"] = "набір для польових досліджень", ["Field Testing Kit (Provided)"] = "набір для польових досліджень (видано)" } },
    [2381] = { [1] = "Пограбувати грабіжників", [2] = "Не хочу лякати тебе, {ім'я}, але останні п'ять крадіїв, яких я відправив викрасти скарб Південних морів, повернулися до мене по частинах!\n\nНа південь вздовж узбережжя, ти знайдеш корабель флібустьєри Південних морів — \"Припливну Бритву\". В його трюмі лежить скарб Південних морів. На другій палубі цього корабля знаходиться піратське лігво, де вони тренують своїх крадіїв.\n\nПроникни на цей корабель, викради скарб та принеси його мені. Якщо тобі знадобиться потренувати твої навички злому — скористайся піратським лігвом, але будь {стать:обережний:обережна}!", [3] = "Принесіть скарб Південних морів Реніксу Жалюгідному в Брашпиль. Не забудьте взяти В.Х.М.К та інструменти зломника з гізмотронного апарату Ренікса. Вам знадобляться ці предмети для виконання завдання.\n\nЯкщо на вас нападуть вороже налаштовані папуги — скористайтеся В.Х.М.К.!", [4] = "Що ж, принаймні у тебе всі кінцівки на місці. Тобі вдалося знайти скарб?", [5] = "Неймовірно! Прекрасно! Просто дивовижно! У тебе є талант, {ім'я}, або ж тобі неймовірно щастить!\n\nОсь твоя частка. Думаю, ти знайдеш їй краще застосування, ніж я.", ["en"] = "Plundering the Plunderers", ["tasks"] = { ["Southsea Treasure"] = "скарб Південних морів", ["Southsea Treasure (Provided)"] = "скарб Південних морів (видано)" } },
    [2382] = { [1] = "Ренікс з Брашпиля", [2] = "Зандо'зан бачив це! Так, день близький! Смерть Тралла... кинджал у його спині, отрута в його венах... Зандо'зан сказав занадто багато.\n\n{ім'я}! У Зандо'зана є завдання для тебе! {ім'я} має вирушати до Брашпиля, на схід від Перехрестя, та поговорити з Реніксом Жалюгідним. Йди!", [3] = "Відправляйтеся до Брашпиля та поговоріть з Реніксом Жалюгідним.", [5] = "Ще {стать:один:одна}? Останні п'ятеро, яких прислав мені цей божевільний троль, пішли на корм акулам. Сподіваймося, що ти протримаєшся краще, ге?", ["en"] = "Wrenix of Ratchet" },
    [241] = { [1] = "<TEST> ПРИВІТ, МІСТЕР ВІЛЬСОН!", [2] = "Опис", ["en"] = "<TEST> HEY MISTER WILSON!" },
    [2418] = { [1] = "Камені сили", [2] = "Деякий час тому у мене сталася неприємність з дворфами Тінегарту. Вони привезли мене до фортеці Анґора, щоб я вивчив два зразки дивних каменів з Ульдамана. Я виявив, що ці камені є тривалими, стабільними джерелами енергії, якщо з ними правильно поводитися. Дивовижно, що можна знайти на цих розкопках!\n\nВрешті-решт, щойно я розповів їм таємницю каміння, вони вигнали мене з фортеці Анґора і відправились за каменями в Ульдаман.\n\nЯ хочу отримати ці камені! Принеси мені кілька обох видів, і я добре тобі заплачу!", [3] = "Принесіть 8 дентрієвих каменів сили та 8 каменів сили Ан'Аллеума Смиколяпу в Безплідні краї.", [4] = "Камені сили у тебе, {ім'я}? У мене є робот-гризун, якому потрібне джерело живлення...", [5] = "Чудово, ти {стать:приніс:принесла} їх! Дуже дякую, {ім'я}. Ти {стать:найнадійніший:найнадійніша} {раса}, {стать:якого:яку} я зустрічав!\n\nНе можу дочекатися, щоб випробувати їх в моїх механізмах. Я впевнений, що за правильних умов, пристрої з цими камінцями працюватимуть вічно!", ["en"] = "Power Stones", ["tasks"] = { ["An'Alleum Power Stone"] = "камінь сили Ан'Аллеума", ["An'Alleum Power Stone (Provided)"] = "камінь сили Ан'Аллеума (видано)", ["Dentrium Power Stone"] = "дентрієвий камінь сили", ["Dentrium Power Stone (Provided)"] = "дентрієвий камінь сили (видано)" } },
    [242] = { [1] = "<UNUSED>", [2] = "Тром-ка, {клас}. Немає часу гаяти. Орки клану Драконячої Пащі укріпилися в долині на південь від цього місця.\n\nВони відмовили в повноваженнях Вождя, залишивши нам лише один варіант дій. Ми знищимо їх, щоб вони більше не бруднили ім'я Орди.", [3] = "Убийте 8 рейдерів з Драконьої Пащі, 3 Кістяних Вартових з Драконьої Пащі та Бойового Майстра з Драконьої Пащі.", ["en"] = "<UNUSED>", ["tasks"] = { ["Dragonmaw Battlemaster slain"] = "воєначальник Драконової Пащі: убито", ["Dragonmaw Bonewarder slain"] = "кісткостраж Драконової Пащі: убито", ["Dragonmaw Raider slain"] = "рейдер Драконової Пащі: убито" } },
    [243] = { [1] = "Польові дослідження", [2] = "Вирушай до пустелі Танаріс, щоб перевірити склад тканин тамтешніх василісків, скорпідів та гієн. Отримай зразки тканин і перевір їх за допомогою цього набору для польових досліджень. Думаю, деяка частина зразків не пройде дослідження. Мені потрібно по вісім зразків кожного виду.\n\nКрім того, гобліни Пристробляху мають джерело енергії, яке слід використовувати з цим модифікованим набором. Поговори зі старшим інженером Трюмосвистом і отримай таке джерело.\n\nПовертайся до мене коли збереш зразки тканин.", [3] = "Поговоріть з головним інженером Трюмосвистом в Пристробляху, щоб отримати джерело енергії для набору для польових досліджень.", [5] = "А, так, джерела енергії моделі 4711-FTZ! Зазвичай ми використовуємо їх для живлення колодязів, але завдяки цим КЛЯТИМ КОЧІВНИКАМ, у нас зараз надлишок джерел енергії.\n\nТак, я можу дати джерело енергії для будь-якого твого мерзенного наукового експерименту. Але воно тобі дорого обійдеться, {раса:к}. У Пристробляху ніщо не дістається задарма.", ["en"] = "Into the Field", ["tasks"] = { ["Field Testing Kit"] = "набір для польових досліджень" } },
    [2458] = { [1] = "Надійне прикриття", [2] = "ТзНБ \"Авантюра\"... Можливо, ти {стать:чув:чула} про них?\n\nПротягом року ми працювали над тим, щоб один з наших агентів втерся їм у довіру. І завдяки наполегливій праці та ретельному плануванню нам це вдалося.\n\nНещодавно ми отримали звістку, що ТзНБ \"Авантюра\" планує щось масштабне. Вирушай до вежі ТзНБ \"Авантюра\", що на півночі від Драговини шламу, та зв'яжися з нашим таємним агентом, орударем Фіззулом.\n\nКоли знайдеш вежу, скористайтеся цим сигнальним пістолетом, а потім підійди до Фіззула та покажи йому вітання Розтрощеної Руки.", [3] = "Відправтеся до вежі ТзНБ \"Авантюра\" північніше Драговини шламу та зв'яжіться з таємним оперативником Розтрощеної Руки, орударем Фіззулом.\n\nКоли вежа буде в полі зору, скористайтеся сигнальним пістолетом, щоб повідомити орударю Фіззулу про своє прибуття. Випустіть ДВІ сигнальні ракети, після чого підійдіть до орударя Фіззула та продемонструйте вітання (/salute) Розтрощеної Руки.\n\nЦі дії повинні бути виконані в правильному порядку, оскільки Фіззул буде нападати на всіх незнайомців.", [5] = "Приємно бачити ще одного агента Розтрощеної Руки в цих краях, проте сигнальний пістолет — це вже занадто!\n\nНаступного разу, як захочеш поговорити зі мною, дмухни у цей свисток двічі, і я зрозумію що ти союзник.", ["en"] = "Deep Cover", ["tasks"] = { ["Flare Gun"] = "сигнальний пістолет" } },
    [2460] = { [1] = "Вітання Розтрощеної Руки", [2] = "Тепер, коли ти {клас} Розтрощеної Руки, тобі слід вивчити вітання Розтрощеної Руки. Це єдиний спосіб ідентифікувати члена Руки.\n\nДивись, вчись, повторюй.", [3] = "Повторіть вітання Розтрощеної Руки за Шентулом.", [4] = "Повтори!", [5] = "Молодець, {ім'я}. Тепер ми можемо продовжувати.", ["en"] = "The Shattered Salute", ["tasks"] = { ["Shattered Salute Performed"] = "Виконано «Розбитий салют»" } },
    [2479] = { [1] = "Допомога Гінотта", [2] = "Віднеси зразок суміші Сержу Гінотту в Тарренський Млин.\n\nЯкщо хтось може вилікувати тебе — це Серж. Він тебе навчить усього, що пов'язано з отрутами... якщо ти, звісно, виживеш.", [3] = "Відправтеся до Тарренського Млина в передгір'я Гіллзбраду та доставте зразок суміші Занзіла Сержу Гінотту.\n\nЩоб дістатися Тарренського Млина, сядьте на дирижабль та відправтеся до Підмістя, йдіть південною стежкою через Срібнохвой в напрямку Гіллзбраду. Слідкуйте за знаками!", [4] = "Що це???", [5] = "Ти {стать:такий блідий:така бліда}, виглядаєш дуже апетитно, {клас:к}. І що це за неприємний запах іде від тебе?? Я мушу знати!", ["en"] = "Hinott's Assistance", ["tasks"] = { ["Sample of Zanzil's Altered Mixture"] = "зразок зміненої суміші Занзіла", ["Sample of Zanzil's Altered Mixture (Provided)"] = "зразок зміненої суміші Занзіла (видано)" } },
    [2501] = { [1] = "Забіг по реагенти Безплідними краями II", [2] = "Ти мене дуже {стать:виручив:виручила}, {ім'я}. Я б нагородив тебе навіть рецептом пійла, яке я дав тобі раніше... Але спершу я дам тобі ще одне завдання, досить небезпечне.\n\nУ цій скриньці — три порожні тавматургічні флакони. Вони зачаровані для витягування крові з випалених драконів-стражів. Це їх не на жарт розлютить, тож будь {стать:обережний:обережна}. Як наповниш всі три флакони — повертайся до мене.\n\nЗроби це, і рецепт стане твоїм.", [3] = "Застосуйте порожні тавматургічні флакони на випалених драконах-стражах, яких можна знайти у Безплідних краях. Коли наповните їх, принесіть їх до Ґхака Цілителя в Телсамар.", [4] = "Ти вже {стать:використав:використала} флакони, щоб добути потрібну мені кров випалених драконів-стражів? Так, знаю, це небезпечне завдання. Але в нагороду тебе чекає рецепт мого відновлювального варева. А воно варте того... варте...", [5] = "Честь і хвала тобі, кажу як алхімік алхіміку. А ось і твій заслужений рецепт, користуйся. Хай він принесе тобі успіх і багатство, які роками приносив мені!", ["en"] = "Badlands Reagent Run II", ["tasks"] = { ["Vessel of Dragon's Blood"] = "флакон з кров'ю дракона", ["Vessel of Dragon's Blood (Provided)"] = "флакон з кров'ю дракона (видано)" } },
    [2521] = { [1] = "Служба Кум'іші", [2] = "{Раса:к}, чи може твій дрібний мозок осягнути рідкісність бездоганної сфери з дренетисту? Дренеї витрачали цілі життя в пошуках хоча б одного такого кристала, але лиш зустрічали жахливу долю, не досягнувши своєї мети.\n\nІ от ти стоїш перед Кум'ішею, знаєш, що потрібно Кум'іші, та все ж бажаєш допомогти? Добре, {раса:к}... Якщо під час своїх мандрів цими землями ти знайдеш бездоганну сферу з дренетисту, принеси її мені, і я винагороджу тебе багатствами, про які ти навіть не {стать:мріяв:мріяла}.", [3] = "Якщо подорожуючи Спустошеними землями ви натрапите на бездоганну сферу з дренетисту, віднесіть цей предмет до Кум'іши-Збирача.\n\nАле знайте, що це один з найрідкісніших кристалів у всьому Азероті. Будь-яка істота в цих землях може мати бездоганну сферу з дренетисту.\n\nВи будете винагороджені за кожну бездоганну сферу з дренетисту, що принесете Кум'іші.", [4] = "Я присвятив все своє життя пошуку бездоганних сфер з дренетисту. Ціле життя, {раса:к}!", [5] = "Чи очі мої мене підводять? Неможливо! Звідки... Як...\n\nМожливо, зараз відкриється розлом, і ми зможемо повернутися на батьківщину.", ["en"] = "To Serve Kum'isha", ["tasks"] = { ["Flawless Draenethyst Sphere"] = "бездоганна сфера з дренетисту", ["Flawless Draenethyst Sphere (Provided)"] = "бездоганна сфера з дренетисту (видано)" } },
    [2522] = { [1] = "Починання Кум'іши", [2] = "Хоч мені й не вдалося створити портал, я не втрачаю надії, що моя наступна спроба буде успішною.\n\nНадія дренеїв така ж палка, як твоя жадібність до дрібничок, {раса:к}. Повертайся в ці прокляті землі та знайди ще одну бездоганну сферу з дренетисту.\n\nЗвісно ж, тобі вирішувати, чи братися за це завдання. <Кум'іша посміхається.>", [3] = "Знайдіть та принесіть бездоганну сферу з дренетисту Кум'іші-Збирачу.", [4] = "Ти {стать:знайшов:знайшла} ще одну бездоганну сферу з дренетисту?", [5] = "Дивовижно. Я сумнівався, що ти зможеш знайти ще одну сферу, але ось вона, пульсує у моїх руках.\n\nГарна робота, {ім'я}!\n\nЯкщо ти знайдеш ще сфери — а я вважаю, що це неможливо — принось їх мені, і я знову винагороджу тебе.", ["en"] = "Kum'isha's Endeavors", ["tasks"] = { ["Flawless Draenethyst Sphere"] = "бездоганна сфера з дренетисту", ["Flawless Draenethyst Sphere (Provided)"] = "бездоганна сфера з дренетисту (видано)" } },
    [2523] = { [1] = "Осквернений піснеквіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на піснеквіт. Плоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите кенарійський бальзам зцілення рослин на піснеквіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Songflower", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [254] = { [1] = "Копання в багнюці", [5] = "Ви копаєте розпушену землю над могилою...і знаходите рештки труни.\n\nУсередині труни ви відчуваєте шкрябання пазуристих пальців і скрегіт гнилих зубів...\n\nЧи відкриєте ви труну і дістанете серце Бальзамувальника?", ["en"] = "Digging Through the Dirt" },
    [257] = { [1] = "Хвастощі мисливця", [2] = "Думаєш тягатися з Дерілом Сміливим, га? Не раджу. Звісно, ти можеш спробувати. Ось тобі випробування, яке тобі не під силу, тож не засмучуйся, якщо в тебе нічого не вийде.\n\nТут, в Лох-Модані, загніздилась зграя канюків. Чом би тобі не спробувати вбити кількох? Знаєш що, якщо впораєшся за 15 хвилин, я віддам тобі свій лук чи рушницю.\n\n<Деріл зневажливо дивиться на вас.>\n\nВсе одно тобі втрачати нічого.", [3] = "Вбийте 6 гірських канюків і поверніться до Деріла Юного в оселю Далекоходців протягом 15 хвилин.", [4] = "Не вийшло? Ну журись, {ім'я}.\n\nНе кожен може як я.", [5] = "Що? Вийшло?\n\nНу на, забирай. Але не задирай носа - будь-який жовторотий малий з луком справився б цими... Пташенятами. Сподіваюсь, ти не занадто {стать:захопився:захопилась} вбивством канюків. Не хотілось би, щоб вони стали вимираючим видом.\n\nЩо-ж, еее... Хай не кажуть, що Деріл Сміливий не тримає слова.", ["en"] = "A Hunter's Boast", ["tasks"] = { ["Mountain Buzzard"] = "гірський канюк", ["Mountain Buzzard slain"] = "гірський канюк: убито" } },
    [258] = { [1] = "Виклик Мисливця", [2] = "{ім'я} {стать:Величний:Велична}, га? Бачу ти зараз лопнеш від гордості за проходження першого випробування, еге ж? Як я вже казав, то було не складно.\n\nА ось спробуй пополювати на кнурів. Повір мені, те не ті поросята, що в Морозній долині, з ними треба бути обережніше. Цього разу я даю тобі 12 хвилин.\n\nНе переймайся як нічого не вийде. Я тобі власну сорочку віддам, якщо впораєшся!\n\nТи {стать:чув:чула} історію про те, як я отримав цей шрам? Ні, Так, от, два роки тому...", [3] = "Вбийте 6 старих гірських кнурів і поверніться до Деріла Юного в оселю Далекоходців протягом 12 хвилин.", [4] = "Цілком нормально жаліти себе, коли перевершив хтось настільки юний як я. Не засмучуйся, {стать:Артин:Артина}.\n\nХм? Чи тебе не так звати?", [5] = "Схоже, що тобі несолодко довелося. Видно, кнури неабияк потріпали тебе, еге ж? Не переймайся, я нікому не розповім про твою поразку. Тобі і без язикатих Хвесьок важко.\n\nЩо? Ти {стать:впорався:впоралась} з кнурами? Я... Що ж... ну так, я і не здивований! {стать:Будь-який малий зміг би:Будь-яка мала змогла б}... Обіцянка?\n\nЯка обіцянка?", ["en"] = "A Hunter's Challenge", ["tasks"] = { ["Elder Mountain Boar"] = "старий гірський кнур", ["Elder Mountain Boar slain"] = "старий гірський кнур: убито" } },
    [2581] = { [1] = "Щелепи хихотунів", [2] = "Щелепи гієни неймовірно сильні, але щоб вони були здатні прокусити п'ять сантиметрів торієвої сталі? Неможливо, неймовірно, але я бачив це на власні очі.\n\nВирушай в Спустошені землі та принеси мені три щелепи хихотунів. А разом з тим шукай кнурів та скорпоків — для завершення суміші також знадобляться дві легені пеклокнурів та одна клешня скорпока.", [3] = "Принесіть три щелепи хихотунів, дві легені пеклокнура та одну клешню скорпока кривавому магу Дразіалу.", [4] = "Ти смердиш, {ім'я}. Ти по сіркових полях {стать:гуляв:гуляла}? І де мої компоненти?!", [5] = "Як ти себе почуваєш, {ім'я}? Ти випромінюєш ауру гієни-хихотуна — твоя сила не зрівняється зі смертними!\n\nНа жаль, з компонентів, які ти мені {стать:приніс:принесла}, я зміг зробити лише одну таблетку. Якщо тобі знадобиться ще одна — мені будуть потрібні нові компоненти.", ["en"] = "Snickerfang Jowls", ["tasks"] = { ["Blasted Boar Lung"] = "легеня пеклокнура", ["Blasted Boar Lung (Provided)"] = "легеня пеклокнура (видано)", ["Scorpok Pincer"] = "клешня скорпока", ["Scorpok Pincer (Provided)"] = "клешня скорпока (видано)", ["Snickerfang Jowl"] = "щелепа хихотуна", ["Snickerfang Jowl (Provided)"] = "щелепа хихотуна (видано)" } },
    [2582] = { [1] = "Віковічна лють", [2] = "О, {ім'я}, радий бачити. Здається, тобі сподобався ефект бездоганного ампліфікатора дужості. Але будь {стать:обережний:обережна}, хоча безпосереднім ефектом є титанічний прилив сили, довгострокові наслідки можуть бути небезпечним для твого духу та розуму.\n\nТо що, хочеш ще? Якщо так, то принеси мені ще три щелепи хихотуна, дві легені пеклокнура та клешню скорпока.", [3] = "Принесіть три щелепи хихотунів, дві легені пеклокнура та одну клешню скорпока кривавому магу Дразіалу.", [4] = "Тобі вдалося добути компоненти?", [5] = "Ось, тримай! І пам'ятай, що використовувати її треба обачливо. Якщо знадобиться ще — приходь до мене після того, як використаєш цю порцію.", ["en"] = "Rage of Ages", ["tasks"] = { ["Blasted Boar Lung"] = "легеня пеклокнура", ["Blasted Boar Lung (Provided)"] = "легеня пеклокнура (видано)", ["Scorpok Pincer"] = "клешня скорпока", ["Scorpok Pincer (Provided)"] = "клешня скорпока (видано)", ["Snickerfang Jowl"] = "щелепа хихотуна", ["Snickerfang Jowl (Provided)"] = "щелепа хихотуна (видано)" } },
    [2583] = { [1] = "Живучість кнура", [2] = "У цих спустошених землях існує два види кнурів: попелегриві кнури та пеклокнури.\n\nЗдається, стійкість цих звірів робить їх майже невразливими до шкоди, оскільки інші тварини вважають їх занадто важкими для вбивства, а отже й не вартими зусиль.\n\nНам потрібно дослідити їх, {ім'я}. Якщо ти принесеш мені три легені пеклокнура, дві клешні скорпока та один мозок василіска, я створю божественний еліксир з решток зразків. Ти станеш {стать:моїм першим піддослідним:моєю першою піддослідною}!", [3] = "Принесіть три легені пеклокнура, дві клешні скорпока та один мозок василіска кривавому магу Дразіалу.", [4] = "Ну, де органи, {ім'я}!?", [5] = "Дух кнура осяває твоє єство, {ім'я}! Певне, ти вважаєш себе {стать:таким же невразливим:такою ж невразливою}, як і ці звірі?", ["en"] = "A Boar's Vitality", ["tasks"] = { ["Basilisk Brain"] = "мозок василіска", ["Basilisk Brain (Provided)"] = "мозок василіска (видано)", ["Blasted Boar Lung"] = "легеня пеклокнура", ["Blasted Boar Lung (Provided)"] = "легеня пеклокнура (видано)", ["Scorpok Pincer"] = "клешня скорпока", ["Scorpok Pincer (Provided)"] = "клешня скорпока (видано)" } },
    [2584] = { [1] = "Дух кнура", [2] = "Коли я вперше дав тобі еліксир, {ім'я}, я зрозумів, що одного-двох використань не вистачить, щоб наситити твій апетит. І навіть зараз я бачу голод у твоїх очах. Цей збір викликає залежність, якій, здається, навіть не зможе протистояти найсильніша воля.\n\nНехай так! Якщо тобі потрібно більше легеневого коктейлю, повертайся в пустелю і знайди для мене три легені пеклокнура, дві клешні скорпока та один мозок василіска.", [3] = "Принесіть три легені пеклокнура, дві клешні скорпока та один мозок василіска кривавому магу Дразіалу.", [4] = "Ну, де органи, {ім'я}!?", [5] = "Я маю тебе попередити, {ім'я}, не намагайся змішувати зілля, які я створив. Хімічні властивості того зілля, яке ти {стать:вжив:вжила} останнім, завжди матимуть перевагу над попередніми чарами, тим самим заміщуючи їх.", ["en"] = "Spirit of the Boar", ["tasks"] = { ["Basilisk Brain"] = "мозок василіска", ["Basilisk Brain (Provided)"] = "мозок василіска (видано)", ["Blasted Boar Lung"] = "легеня пеклокнура", ["Blasted Boar Lung (Provided)"] = "легеня пеклокнура (видано)", ["Scorpok Pincer"] = "клешня скорпока", ["Scorpok Pincer (Provided)"] = "клешня скорпока (видано)" } },
    [2585] = { [1] = "Рішучі удари", [2] = "Ти коли-небудь {стать:бачив:бачила} їх в бою, {ім'я}? Я маю на увазі, скорпоків. Чи ти коли-небудь {стать:бачив:бачила} їхню граціозність і спритність? Рішучість їхніх ударів?\n\nЯкби ми могли якось виділити цю спритність і укласти її в капсулу, ми стали б багаті, як... тобто... це було б корисним для наукової спільноти.\n\nДопоможи мені, {ім'я}, і я дозволю тобі спробувати зразок екстракту.\n\nЩоб створити стабільний екстракт, мені знадобляться три клешні скорпока, два шлунки стерв'ятника та одна легеня пеклокнура.", [3] = "Принесіть три клешні скорпока, два шлунки стерв'ятника та одну легеню пеклокнура кривавому магу Дразіалу.", [4] = "Ну, де органи, {ім'я}!?", [5] = "Неймовірно. Це був чи не найскладніший з усіх аналізів, які мені доводилось робити.\n\nВізьми залишки цієї солі та поклади їх під язик. Ти маєш відчути легке відчуття ейфорії, за яким слідує прилив спритності та швидкості.", ["en"] = "The Decisive Striker", ["tasks"] = { ["Blasted Boar Lung"] = "легеня пеклокнура", ["Blasted Boar Lung (Provided)"] = "легеня пеклокнура (видано)", ["Scorpok Pincer"] = "клешня скорпока", ["Scorpok Pincer (Provided)"] = "клешня скорпока (видано)", ["Vulture Gizzard"] = "шлунок стерв'ятника", ["Vulture Gizzard (Provided)"] = "шлунок стерв'ятника (видано)" } },
    [2586] = { [1] = "Сіль скорпока", [2] = "Ти {стать:живий:жива}! Це справді гарна новина. Гадаю, ти {стать:повернувся:повернулась} ще новою дозою солі скорпока?\n\nЧудово, {ім'я}, тоді знову вирушай в пустку, і не повертайся, доки не збереш три клешні скорпока, два шлунки стерв'ятника та одну легеню пеклокнура.", [3] = "Принесіть три клешні скорпока, два шлунки стерв'ятника та одну легеню пеклокнура кривавому магу Дразіалу.", [4] = "Ну, де органи, {ім'я}!?", [5] = "Чудова робота, {ім'я}. Ось ще один зразок солі скорпока для тебе, і ще дев'ять для моїх досліджень.\n\nЯк знадобиться більше солі скорпока — повертайся до мене, і ми щось вигадаємо.", ["en"] = "Salt of the Scorpok", ["tasks"] = { ["Blasted Boar Lung"] = "легеня пеклокнура", ["Blasted Boar Lung (Provided)"] = "легеня пеклокнура (видано)", ["Scorpok Pincer"] = "клешня скорпока", ["Scorpok Pincer (Provided)"] = "клешня скорпока (видано)", ["Vulture Gizzard"] = "шлунок стерв'ятника", ["Vulture Gizzard (Provided)"] = "шлунок стерв'ятника (видано)" } },
    [259] = { [1] = "<UNUSED>", [2] = "Привіт, {ім'я}. Я багато чув про ваші подвиги і мушу сказати, що для мене честь познайомитися з вами. Не думаю, що ви чули історію про Старого Кельта? Ах, ну, Старий Кельт – тобто Кельт Томасін – колись вважався одним із найкращих мисливців у всьому королівстві. Не було нічого, чого б він не зробив, але потім, одного разу, він став одержимий давньою історією... міфом, насправді. Ну, як кажуть, у водах озера живе величезний трешадон. Хогвош, якщо хочете знати моє. Якщо вам цікаво, ви можете поговорити з Кельтом.", ["en"] = "<UNUSED>" },
    [2601] = { [1] = "Укус василіска", [2] = "Ця пустка кишить багрянокам'яними василісками, {ім'я}. Ці василіски чудово адаптувалися, краще ніж будь-які інші місцеві істоти.\n\nЯ спостерігала здалеку, як вони полюють та ведуть своє повсякденне життя — ці звірі демонструють процес мислення, складніший за деяких гуманоїдів.\n\nМені потрібно дослідити їхні мізки!\n\nЗнайди десять їхніх мізків для мене, {ім'я}. Проте, збір не буде повноцінним без двох шлунків стерв'ятників, які утворять основу зілля.", [3] = "Принесіть десять мізків василіска та два шлунки стерв'ятника кривавій магині Ліннор.", [4] = "Сподіваюсь, ти {стать:повернувся:повернулась} з органами?", [5] = "Це дивовижно, {ім'я}! Пропоную тобі спробувати на смак внутрішню сутність багрянокам'яних василісків.\n\nЯкщо цей збір буде тобі до вподоби, я завжди можу виготовити більше... за певну ціну.", ["en"] = "The Basilisk's Bite", ["tasks"] = { ["Basilisk Brain"] = "мозок василіска", ["Basilisk Brain (Provided)"] = "мозок василіска (видано)", ["Vulture Gizzard"] = "шлунок стерв'ятника", ["Vulture Gizzard (Provided)"] = "шлунок стерв'ятника (видано)" } },
    [2602] = { [1] = "Непохибний розум", [2] = "Так швидко зникла зосередженість? Потрібно провести більше досліджень!\n\nІ так, {ім'я}, ціна залишається тою ж. Вирушай в Спустошені землі та принеси мені десять мізків багрянокам'яних василісків і два шлунки стерв'ятників.", [3] = "Принесіть десять мізків василіска та два шлунки стерв'ятника кривавій магині Ліннор.", [4] = "Сподіваюсь, ти {стать:повернувся:повернулась} з органами?", [5] = "Так, так, дай мені хвилинку і матимеш нову дозу збору, {ім'я}.\n\nБери її... але, {ім'я}, не намагайся вживати ці експериментальні суміші одну за одною. Результати можуть бути катастрофічними.", ["en"] = "Infallible Mind", ["tasks"] = { ["Basilisk Brain"] = "мозок василіска", ["Basilisk Brain (Provided)"] = "мозок василіска (видано)", ["Vulture Gizzard"] = "шлунок стерв'ятника", ["Vulture Gizzard (Provided)"] = "шлунок стерв'ятника (видано)" } },
    [2603] = { [1] = "Снага стерв'ятника", [2] = "У цих спустошених землях смерть воістину має крила, {раса:к}. Я неодноразово спостерігала, як чорні вбивці та кісткогризи жерли тіла багатьох загиблих дослідників, пожираючи найбільш огидні та розкладені трупи. Тож дивно, як їхні внутрішні органи справляються із заразою, яка панує в цих землях.\n\nДопоможи мені в моїх дослідженнях, {ім'я}! Мені потрібні шлунки стерв'ятників! Також знадобляться дві щелепи хихотунів для основи суміші.\n\nТи будеш добре {стать:винагороджений:винагороджена} за свої зусилля.", [3] = "Принесіть десять шлунків стерв'ятників та дві щелепи хихотуна кривавій магині Ліннор.", [4] = "Не витрачай мій час, {ім'я}. Нам нема що обговорювати, якщо ти не {стать:знайшов:знайшла} компоненти, які я просила.", [5] = "Чудово! Я негайно візьмуся до роботи. Можливо, я знайду ліки проти багатьох хвороб цього світу!\n\nА, так, твоя винагорода — звісно, якщо тобі знадобиться більше, то повертайся до мене, і я дам тобі нове завдання.", ["en"] = "Vulture's Vigor", ["tasks"] = { ["Snickerfang Jowl"] = "щелепа хихотуна", ["Snickerfang Jowl (Provided)"] = "щелепа хихотуна (видано)", ["Vulture Gizzard"] = "шлунок стерв'ятника", ["Vulture Gizzard (Provided)"] = "шлунок стерв'ятника (видано)" } },
    [2604] = { [1] = "Духовне підкорення", [2] = "Я бачу, що твій внутрішній вогонь згас. Як гадаєш, духовна ейфорія тривала хоча б годину?\n\nЯкщо ти хочеш більше шлункової жуйки, то мені знадобляться нові шлунки. Відправляйся в пустку, {ім'я}. І не повертайся, доки не знайдеш десять шлунків і дві щелепи.", [3] = "Принесіть десять шлунків стерв'ятників та дві щелепи хихотуна кривавій магині Ліннор.", [4] = "Не витрачай мій час, {ім'я}. Нам нема що обговорювати, якщо ти не {стать:знайшов:знайшла} компоненти, які я просила.", [5] = "Можливо, одного дня я зможу виділити активні компоненти цієї есенції та отримати набагато ефективніший екстракт. А поки що тобі доведеться задовольнятися тим, що я в змозі зробити зараз. Повертайся до мене, якщо тобі знадобиться більше шлункової жуйки.", ["en"] = "Spiritual Domination", ["tasks"] = { ["Snickerfang Jowl"] = "щелепа хихотуна", ["Snickerfang Jowl (Provided)"] = "щелепа хихотуна (видано)", ["Vulture Gizzard"] = "шлунок стерв'ятника", ["Vulture Gizzard (Provided)"] = "шлунок стерв'ятника (видано)" } },
    [2605] = { [1] = "Спраглий гоблін", [2] = "У мене є ідея, послухай. Я чув про дивних істот, що звуться збирачами роси, які живуть на південному заході... і вони можуть зберігати воду в особливих залозах.\n\nЯ думаю, якщо я зможу дістати одну з цих залоз, я зможу створити напій, який би втамував мою жахливу спрагу! Чи можеш ти мені допомогти, {ім'я}?\n\nШукай кактусовий сад, {ім'я}. Там ти знайдеш збирачів роси.", [3] = "Зберіть насичену росяну залозу і принесіть її Маріну Гогельмогелю в Пристроблях.", [4] = "Будь ласка, скажи мені, що ти {стать:знайшов:знайшла} збирачів роси?", [5] = "О, чудово! Дай-но сюди, я її вип'ю!", ["en"] = "The Thirsty Goblin", ["tasks"] = { ["Laden Dew Gland"] = "насичена росяна залоза", ["Laden Dew Gland (Provided)"] = "насичена росяна залоза (видано)" } },
    [2606] = { [1] = "Гарний смак", [2] = "Фу! На смак жахливо! Так, ідея була невдала...\n\nПочекай, що це? О, знаю, ти вважаєш, що не варто відмовлятися від цієї штуки. Що ж, добре.\n\nУууу, в мене є ідея! Блискуча! Віднеси цю росу до моєї подруги Бризківки — вона чудовий шеф-кухар. Скажи їй, що ми тут задумали, хай вигадає, як покращити смак.\n\nЯ маю на увазі, що якщо вона така бридка, то вона має хоча б мати якийсь вплив... Але я нічого не відчуваю...", [3] = "Марін Гогельмогель хоче, щоб ви поговорили з Бризківкою в Пристробляху.", [4] = "Старий Марін знову за своє, так? З чого зроблена ця суміш?", [5] = "Марін хороший хлопець, не зрозумій мене неправильно — просто трохи... ексцентричний, я б сказала.\n\nІ, звичайно, йому знову потрібна моя допомога.", ["en"] = "In Good Taste", ["tasks"] = { ["Thistleshrub Dew"] = "чортополохова роса", ["Thistleshrub Dew (Provided)"] = "чортополохова роса (видано)" } },
    [2607] = { [1] = "Дотик Занзіла", [2] = "Схоже, що ти {стать:приніс:принесла} більше інформації, ніж я очікував. Це справді дивний поворот подій, {ім'я}.\n\nЛіки? Хм-м... спускайся до підвалу та поговори з Доком Міксільпіксіль — він зможе допомогти.", [3] = "Поговоріть з Доком Міксільпіксіль в підвалі бараків.", [5] = "Ти саме вчасно! Поклади сир на стіл та котися звідси. Осборн на виході заплатить тобі.", ["en"] = "The Touch of Zanzil" },
    [2608] = { [1] = "Дотик Занзіла", [2] = "Йой, ти виглядаєш як мрець. Поправка — мерців я бачив, ти виглядаєш гірше. Ви, {стать:пане:панно} були б тим, що виплюнула смерть.\n\nХа! Ти чув, Безрук? Запиши це!\n\n*Кхе-кхе* Хм, так, щоб я зміг тобі допомогти, мені потрібно взяти твою кров. Не бійся, буде боляче лише перші... п'ятдесят разів... лягай (/lay), як будеш {стать:готовий:готова} до процедури, {ім'я}.", [3] = "Ляжте (/lay), щоб Док Міксільпіксіль оглянув вас. Як він знайде ліки, якщо не знатиме від чого?", [4] = "Як будеш {стать:готовий:готова} до обстеження — лягай (/lay) на підлогу і я почну флеботомію.", [5] = "Дай мені час, щоб порадитися зі своїми колегами, {ім'я}. Докторе Монтгомері, пане Безрук, консиліум!", ["en"] = "The Touch of Zanzil", ["tasks"] = { ["Diagnosis Complete"] = "Діагностика завершена" } },
    [2609] = { [1] = "Дотик Занзіла", [2] = "Це очевидно, {ім'я}. У тебе цетит.\n\nНа щастя, у мене є ліки проти цетиту.\n\nОсь, що мені потрібно: один пучок простих польових квітів, один свинцевий фіал, одна бронзова трубка та останнє, та не менш важливе, одна котушка світло-оливкових шовкових ниток. Старенька Емма залишила котушку для мене в \"Найтоншій пряжі\". Ти знайдеш цю крамницю вздовж каналів.\n\nХутчіше, {ім'я}, і постарайся нікого не торкатися, поки не вилікуєшся. А, і доктор Монтгомері каже, що тобі потрібен душ. Це його слова, не мої.", [3] = "Принесіть Доку Міксільпіксіль один пучок простих польових квітів, один свинцевий фіал, одну бронзову трубку та одну котушку світло-оливкових шовкових ниток. Цетит сам себе не вилікує, {стать:юначе:юначко}.", [4] = "Якщо ти хочеш вилікуватися від цетиту, тобі доведеться докласти більше зусиль, {ім'я}. Де реагенти для ліків?", [5] = "Що я роблю? А на що це схоже? Я роблю ліки проти твого цетиту! Не відволікай мене, {ім'я}!\n\nЩе кілька секунд. Ось! Просто попшикай на себе, цим... ем... чудовим лікарським засобом, і будеш як {стать:новенький:новенька}!", ["en"] = "The Touch of Zanzil", ["tasks"] = { ["Bronze Tube"] = "бронзова трубка", ["Bronze Tube (Provided)"] = "бронзова трубка (видано)", ["Leaded Vial"] = "свинцевий фіал", ["Leaded Vial (Provided)"] = "свинцевий фіал (видано)", ["Simple Wildflowers"] = "прості польові квіти", ["Simple Wildflowers (Provided)"] = "прості польові квіти (видано)", ["Spool of Light Chartreuse Silk Thread"] = "котушка світло-оливкових шовкових ниток", ["Spool of Light Chartreuse Silk Thread (Provided)"] = "котушка світло-оливкових шовкових ниток (видано)" } },
    [261] = { [1] = "В Багряний Похід", [2] = "Буду відвертим. Ми воюємо зі Скарою. Це зло, що знищує наш народ і оскверняє наші землі. Її потрібно зупинити, поки вона не поглинула нас і не занурила наш світ у морок. Ми, учасники Багряного походу, присягнулися боротися з лихом, не шкодуючи ні тіла, ні душі.\n\nЯкщо ти з нами, то зберися з духом і доведи свою вірність — знищ невмерлих спустошників, що бродять в долині Кісток, що на півдні Спустошища.\n\nЗроби це, і Багряний Похід прийме тебе.", [3] = "Знищіть 30 невмерлих спустошників, після чого поверніться до брата Антона в оплот Найджела.", [4] = "З кожним днем Скара стає дедалі сильнішою. Якщо ти справді хочеш зупинити її, то доведи це мені.", [5] = "Ти {стать:довів:довела} свою рішучість, і Багряний Похід вдячний тобі.\n\nЯкщо тебе не лякає те, що заради праведного діла доведеться вбивати, до того ж немало, тоді тобі з нами по дорозі.", ["en"] = "Down the Scarlet Path", ["tasks"] = { ["Undead Ravager"] = "невмерлий спустошник", ["Undead Ravager slain"] = "невмерлий спустошник: убито" } },
    [2641] = { [1] = "Секретний інгредієнт Бризківки", [2] = "Коли я була дитиною, моя сестра готувала всю їжу. Було жахливо! Я могла їсти лише деякі її страви — поки я не знайшла свій \"секретний\" інгредієнт! Додай його до будь-чого, і... ВАУ! Воно дуже смачне!\n\nЩо це за інгредієнт, ти запитаєш? Це гриб під назвою фіалковий траґан. Якщо ти хочеш, щоб я допомогла тобі перетворити це жахіття в щось смачне, рушай в Внутрішні землі, і знайди там невелике озеро.\n\nА, і пам'ятай, що фіалковий траґан можна знайти тільки під водою.", [3] = "Знайдіть фіалковий траґан та принесіть його Бризківці в Пристроблях.", [4] = "Вода цього озера — це єдине місце, де можна знайти фіалковий траґан. Сподіваюся, ти вмієш затримувати дихання!", [5] = "Те що треба, {ім'я}!\n\nМає добрий вид, хоча, мабуть... Ха, жартую!", ["en"] = "Sprinkle's Secret Ingredient", ["tasks"] = { ["Violet Tragan"] = "фіалковий траган", ["Violet Tragan (Provided)"] = "фіалковий траган (видано)" } },
    [2661] = { [1] = "Доставка для Маріна", [2] = "Ось фіалковий порошок, {ім'я}. Віднеси його Маріну і скажи, що він мій боржник!", [3] = "Бризківка просить вас віднести фіалковий порошок Маріну Гогельмогелю у Пристроблях.", [4] = "О, {ім'я}, ти нарешті {стать:повернувся:повернулася}. Що ти {стать:приніс:принесла}?", [5] = "Фіалковий порошок, так? Що ж, спробуймо — гірше вже не буде, це точно!", ["en"] = "Delivery for Marin", ["tasks"] = { ["Violet Powder"] = "фіалковий порошок", ["Violet Powder (Provided)"] = "фіалковий порошок (видано)" } },
    [2662] = { [1] = "Еліксир Гогельмогеля", [2] = "Тепер треба змішати цей порошок з росою.\n\nПовернись і поговори зі мною за хвилину... Після того, як я вдосконалю дивовижний еліксир Гогельмогеля!", [3] = "Марін Гогельмогель просить вас поговорити з ним після того, як він завершить роботу над еліксиром.", [5] = "Випий це! Це абсолютно дивовижно!!!\n\nЯ знав, що в мене вийде... О, дякую ще раз, {ім'я}, за твою допомогу, але, будь ласка, не заважай мені, добре? Не перешкоджай моєму бізнесу! Я збираюся заробити мільйони на дивовижному еліксирі Гогельмогеля, мільйони!\n\nЩо це? Бризківка каже що я їй за це винен? О, ця Бризківка така приколістка!", ["en"] = "Noggenfogger Elixir" },
    [2681] = { [1] = "Камені, що нас пов'язують", [2] = "Одних лише твоїх сил не вистачить, щоб здолати Разеліха та його підлеглих.\n\nЗбери відповідну групу шукачів пригод і звільни моїх підлеглих від вічних тортур! Тобі потрібно знищити вісімнадцять каменів.\n\nБийся відважно і помри з честю, {ім'я}.", [3] = "Звільніть дев'ять слуг Разеліха, трьох слуг Севіни, трьох слуг Аллістаржа та трьох слуг Ґрола. Поверніться до загиблого героя, коли ваше завдання буде виконано. Ви повинні залишатись у безпосередній близькості від каменів, інакше процес буде невдалим.", [4] = "Це нелегке завдання, {ім'я}. Не здавайся!", [5] = "Ти {стать:зробив:зробила} це, {ім'я}! Бідні, закатовані душі нарешті можуть спочити в мирі.\n\nПроте наша робота ще не закінчена, {ім'я}. Нам ще багато чого треба обговорити та багато чого зробити.", ["en"] = "The Stones That Bind Us", ["tasks"] = { ["Servants of Allistarj Freed"] = "Звільнені слуги Алістарджа", ["Servants of Allistarj Freed (Provided)"] = "Звільнені слуги Алістарджа (видано)", ["Servants of Allistarj Freed slain"] = "Звільнені слуги Алістарджа: убито", ["Servants of Grol Freed"] = "Слуги Грола Фріда", ["Servants of Grol Freed (Provided)"] = "Слуги Грола Фріда (видано)", ["Servants of Grol Freed slain"] = "Слуги Грола Фріда: убито", ["Servants of Razelikh Freed"] = "Слуги Разеліха Фріда", ["Servants of Razelikh Freed (Provided)"] = "Слуги Разеліха Фріда (видано)", ["Servants of Razelikh Freed slain"] = "Слуги Разеліха Фріда: убито", ["Servants of Sevine Freed"] = "Слуги Севін Фрід", ["Servants of Sevine Freed (Provided)"] = "Слуги Севін Фрід (видано)", ["Servants of Sevine Freed slain"] = "Слуги Севін Фрід: убито" } },
    [2701] = { [1] = "Герої минулого", [2] = "Будь ласка, візьми цю реліквію минулого. Нам вона більше непотрібна.\n\nНехай вона добре послужить тобі у боротьбі проти легіону.", [3] = "Відкрийте скриню та отримайте свою винагороду.", [5] = "На мить вас засліплює яскраве сяйво.", ["en"] = "Heroes of Old" },
    [2702] = { [1] = "Герої минулого", [2] = "Ти {стать:вшанував:вшанувала} мене своєю благородністю та героїзмом, {ім'я}.\n\nА ще ти {стать:вшанував:вшанувала} їх...", [3] = "Поговоріть з капралом Тандом Розщепленим Копитом.", [5] = "Саме так, своїми діяннями ти {стать:вшанував:вшанувала} всіх нас. Навіть наша найщиріша подяка недостатня, щоб віддячити за твої заслуги.", ["en"] = "Heroes of Old" },
    [271] = { [1] = "Помста Вірен", [2] = "Мені здається, що ти б не проти провчити Його Крутість. Маю визнати, Деріл дійсно на щось здатен.\n\nРік тому, вся оселя Далекоходців полювала на величезного ведмедя, але жодному мисливцю так і не пощастило. Врешті-решт, Деріл вирішив сам піти на нього і ледь не залишився без ока.\n\nВбий ведмедя і покажи трофей Дерілу. Впевнена, у нього мову відбере.\n\nТого ведмедя, старого Чорниша, ти знайдеш в пагорбах близ Телсамару.", [3] = "Вбийте старого Чорниша та принесіть трофей Дерілу Юному в оселю Далекоходців.", [4] = "О, {ім'я}! Вже {стать:повернувся:повернулась}? Знову {стать:полював:полювала}? Не засмучуйся, як щось не виходить. Невдачі роблять нас сильнішими!\n\nЩо б там не було, могло бути гірше...", [5] = "Е... Що це? Нічого собі, голова ведмедя.\n\n<Деріл несвідомо проводить пальцем по шраму.>\n\nЩо ж, непогана здобич. Це не той самий...\n\n<Він різко замовкає і починає помітно тремтіти.>\n\nНі, забери це! Забери цю жахливу штуку звідси!", ["en"] = "Vyrin's Revenge", ["tasks"] = { ["Ol' Sooty's Head"] = "голова старого Чорниша", ["Ol' Sooty's Head (Provided)"] = "голова старого Чорниша (видано)" } },
    [2721] = { [1] = "Кіріт", [2] = "Щойно завершується одна глава твоїх пригод, {ім'я}, починається інша.\n\nОдин із моїх людей досі не повернувся, він загубився десь у Спустошених землях. Я кажу про лейтенанта Кіріта, звичайно.\n\nЯк я вже згадував раніше, нас обох ув'язнив і катував Аллістарж, але бідолашний Кіріт, його сила волі похитнулася. Я чув тортури зі своєї клітки, крики болю розносилися по залах печери. Відтоді про Кіріта я нічого не чув.", [3] = "Дізнайтесь, що сталося з лейтенантом Кірітом.", [5] = "Требор? Требор прислав тебе?", ["en"] = "Kirith" },
    [2741] = { [1] = "Супер Яйц-Е-Мат", [4] = "Супер Яйц-Е-Мат — останній винахід Бульки Хисткоплиг. Ця машина вражає.\n\nСупер Яйц-Е-Мат несамовито шумить, коли ви наближаєтесь до панелі управління.", [5] = "Ви поміщаєте яйце гіпогрифа в машину. Після цього лунає кілька звукових сигналів і дивні механічні звуки.\n\nЦе означає, що яйцемір зважив, виміряв і запакував ваше яйце. Ось це швидке обслуговування!", ["en"] = "The Super Egg-O-Matic", ["tasks"] = { ["Hippogryph Egg"] = "яйце гіпогрифа", ["Hippogryph Egg (Provided)"] = "яйце гіпогрифа (видано)" } },
    [2743] = { [1] = "Покров темряви", [2] = "Давай без пустих балачок, {раса:к}. Мій час тут обмежений.\n\nТи маєш знищити трійцю сили, яка захищає лорда демонів Разеліха. Це не буде таким простим завданням, як звільнення проклятої душі.\n\n<Кіріт посміхається.>\n\nБачиш, кожен з підлеглих Разеліха носить на шиї третину амулета, створеного самим Разеліхом. Саме цей самий амулет тобі знадобиться, щоб викликати архідемона.\n\nПовертайся до Требора та розкажи йому, що потрібно для виклику Разеліха. Він скаже що робити далі.", [3] = "Поверніться до полеглого героя Орди зі своїми знахідками.", [5] = "Хитрість лорда демонів не поступається його жорстокості, {ім'я}.", ["en"] = "The Cover of Darkness" },
    [2744] = { [1] = "Мисливець на демонів", [2] = "Трійця захищена Разеліхом.\n\nВ обмін на свою службу, Разеліх надав кожному з них майже необмежену владу в межах Спустошених земель. В кожному шматку амулета міститься життєва сила їх власника, надаючи їм безсмертя. Доки вони залишаються в Спустошених землях, їх не можна вбити, вони безсмертні.\n\nЄ дехто, хто може допомогти тобі, {ім'я}. Відвідай Азшару і знайди мисливця на демонів, на ім'я Лорам Таліпедес. Шукай його на островах.", [3] = "Поговоріть з Лорамом Таліпедесом в Азшарі.", [4] = "Що ти тут робиш?", [5] = "Я допоможу тобі. Однак, я не думаю, що ти повністю розумієш, з ким ти маєш справу.", ["en"] = "The Demon Hunter", ["tasks"] = { ["Conversation with Loramus"] = "Розмова з Лорамом" } },
    [2747] = { [1] = "Незвичайне яйце", [4] = "Я бачила дуже мало яєць з Фераласу у такому незвичайному стані. Вони дуже рідко зустрічаються...", [5] = "Що ж, тобі вдалося добути таке яйце — дивовижно!\n\nСподіваюся, ти завжди пам'ятатимеш добро, яке {стать:зробив:зробила} сьогодні.", ["en"] = "An Extraordinary Egg", ["tasks"] = { ["Extraordinary Egg"] = "незвичайне яйце", ["Extraordinary Egg (Provided)"] = "незвичайне яйце (видано)" } },
    [2748] = { [1] = "Чудове яйце", [4] = "Чудове яйце — це те, яке в ідеальних умовах вилупиться без наслідків впливу злих чар огрів Ґордунні.", [5] = "Дуже добре, {ім'я}. Я відправлю це яйце в Дарнас, де сподіваюсь воно вилупиться!\n\nБудь ласка, прими це як знак моєї вдячності.", ["en"] = "A Fine Egg", ["tasks"] = { ["Fine Egg"] = "чудове яйце", ["Fine Egg (Provided)"] = "чудове яйце (видано)" } },
    [2749] = { [1] = "Звичайне яйце", [4] = "Звичайні яйця гіпогрифа вилуплюються лише у половині випадків. Ми робимо все щоб доглядати за ними, і якщо пощастить, з них хтось вилупиться.", [5] = "Отже, ти {стать:знайшов:знайшла} звичайне яйце, {ім'я}? Будь ласка, дай його мені... Будемо сподіватись на краще.\n\nЦе небагато, але, будь ласка, прийми цю нагороду. Якщо знову опинишся у Фераласі, пам'ятай, що я завжди готова взяти знайдені тобою яйця.", ["en"] = "An Ordinary Egg", ["tasks"] = { ["Ordinary Egg"] = "звичайне яйце", ["Ordinary Egg (Provided)"] = "звичайне яйце (видано)" } },
    [275] = { [1] = "Пухирі на землі", [2] = "Я не знаю чому, але гниль повзе Заболоттям. Піднялися драговинні плазуни. Це хворобливі, гнійні пухирі на землі, і щоб зцілити її, необхідно загнати плазунів назад в болота, звідки вони прийшли.\n\nДраговинні плазуни водяться біля водойм Заболоття.", [3] = "Убийте 12 драговинних плазунів та поверніться до Ретіля Вартового Природи у Заболоття.", [4] = "Заболоття все ще плаче, а драговинні плазуни все ще лютують. Повернися до мене одразу, як виконаєш своє завдання.", [5] = "Ця земля заспокоюється завдяки твоїм зусиллям, і за це я вручаю тобі дар.", ["en"] = "Blisters on The Land", ["tasks"] = { ["Fen Creeper"] = "драговинний плазун", ["Fen Creeper slain"] = "драговинний плазун: убито" } },
    [2750] = { [1] = "Погане яйце", [4] = "Такі яйця вже не врятуєш — з них ніколи нічого не вилупиться.", [5] = "Боюся, у мене для тебе погані новини, {ім'я}. Це яйце вже не врятувати. Я можу забрати його в тебе, щоб позбутися від нього належним чином.\n\nБудь ласка, не засмучуйся, ми не можемо врятувати їх усіх. Якщо будеш у Фераласі знову, будь ласка, спробуй ще раз. Принеси ще яйце для Супер Яйц-Е-Мату!", ["en"] = "A Bad Egg", ["tasks"] = { ["Bad Egg"] = "погане яйце", ["Bad Egg (Provided)"] = "погане яйце (видано)" } },
    [2756] = { [1] = "Старі звичаї", [2] = "В часи легенд, Атурк розтрощував черепи своїх ворогів і розмелював кістки на дрібний порошок для використання в волокнині. Ті дні давно минули, {раса:к}. Воєвождь хоче миру між кланами. За старими ворогами ми тепер можемо тільки спостерігати!\n\nНеймовірно, я знаю, але така є воля Тралла.\n\nДосить жалітися! Ти тут, щоб навчатися, і навчишся! Принеси мені чотири сталеві кіраси та чотири сталеві шоломи, і ти відчуєш смак війни!", [3] = "Принесіть чотири сталеві кіраси та чотири сталеві шоломи Атурку Ковадлу в Орґріммар.", [4] = "Атурк, як і час, нікого не чекає! Поквапся, дурепо!", [5] = "Здається, ти просто {стать:черговий:чергова} {раса} на побігеньках у воєвождя, {ім'я}. Яке розчарування.\n\nЯк я жадаю славної смерті на полі бою. А замість цього я застряг тут, за наказом Тралла, щоб вчити немовлят ремеслу! Дивись і вчись, дитя!", ["en"] = "The Old Ways", ["tasks"] = { ["Steel Breastplate"] = "сталева кіраса", ["Steel Breastplate (Provided)"] = "сталева кіраса (видано)", ["Steel Plate Helm"] = "сталевий шолом", ["Steel Plate Helm (Provided)"] = "сталевий шолом (видано)" } },
    [2760] = { [1] = "Орден мітрилу", [2] = "Більшість наших новачків так і не дістаються Грабіжної Бухти, {ім'я}. Блиску печатки виявляється достатньо, щоб викликати жадібність навіть у найвідданіших ковалів. Але це лише дурні, оскільки ця печатка — лиш крапля в морі порівняно зі скарбами, які чекають на тебе!\n\nЗнайди Ґальвана Древнього і покажи йому цю підвіску. Його оселя знаходиться далеко на північ, між Зул'Ґурубом і огрівським згірком Мош'Оґґ.", [3] = "Поговоріть з Ґальваном Древнім в Тернистій долині.", [4] = "Вітаю! Підходь ближче, покажи Ґальвану, що це в тебе.", [5] = "Ах, скільки років минуло відтоді, як хтось був гідний посвяти в орден мітрилу. Почнімо ж!", ["en"] = "The Mithril Order", ["tasks"] = { ["Mithril Pendant"] = "мітрилова підвіска", ["Mithril Pendant (Provided)"] = "мітрилова підвіска (видано)" } },
    [2761] = { [1] = "Плавимо, не плавимо", [2] = "Багато ковалів вважають, що гірництво і ковальство — це різні, незалежні професії, але чи може бути ковальство без гірництва? Ага, це неможливо! Досвідчений коваль повинен також бути досвідченим гірником.\n\nПокажи Ґальвану, на що ти {стать:здатний:здатна}, {ім'я}. Принеси мені сорок злитків мітрилу та сорок злитків заліза. За це Ґальван навчить тебе робити вишукані мітрилові штани!", [3] = "Принесіть сорок злитків мітрилу та сорок злитків заліза Ґальвану Древньому в Тернисту долину.", [4] = "Після доброї роботи м'язи мають нити, а тіло — боліти!", [5] = "Твоя робота бездоганна, {ім'я}! Ти починаєш розуміти основи Ґальванської мінералогії! Візьми це і вивчи.", ["en"] = "Smelt On, Smelt Off", ["tasks"] = { ["Iron Bar"] = "злиток заліза", ["Iron Bar (Provided)"] = "злиток заліза (видано)", ["Mithril Bar"] = "злиток мітрилу", ["Mithril Bar (Provided)"] = "злиток мітрилу (видано)" } },
    [2762] = { [1] = "Обманне срібло", [2] = "Кажуть, що ясносрібло є сильнішим і міцнішим за мітрил. Ґальван не сперечається з цією оцінкою мінералів, але, попри свою назву, ясносрібло не є чимось надто незвичайним! Мітрил — набагато благородніший мінерал! ГА-ГА! Хай там як, для цього уроку тобі потрібно знайти це обманне срібло, {ім'я}.\n\nПринеси мені сорок злитків мітрилу та п'ять злитків ясносрібла. В обмін на це, я навчу тебе виготовляти вишукані мітрилові рукавиці, і, що ще важливіше, ти дізнаєшся, що ясносрібло — це брехня!", [3] = "Принесіть сорок злитків мітрилу та п'ять злитків ясносрібла Ґальвану Древньому в Тернисту долину.", [4] = "Після доброї роботи м'язи мають нити, а тіло — боліти!", [5] = "Нелегко з ним упоратися, {ім'я}? Я говорю про ясносрібло, звісно. Так, Ґальван провів понад десять років в горах Альтераку, перш ніж засвоїв цей урок. Візьми це і вивчи!", ["en"] = "The Great Silver Deceiver", ["tasks"] = { ["Mithril Bar"] = "злиток мітрилу", ["Mithril Bar (Provided)"] = "злиток мітрилу (видано)", ["Truesilver Bar"] = "злиток ясносрібла", ["Truesilver Bar (Provided)"] = "злиток ясносрібла (видано)" } },
    [2763] = { [1] = "Мистецтво насичування", [2] = "Збір коштовних каменів має найважливіше значення для нашого ремесла, {ім'я}. Мало каменів є такими цінними, як цитрин. Магічні властивості, якими ми насичуємо наші вироби, значно посилюються з наявністю цитрину.\n\nУ цьому уроці ми зміцнимо сорок злитків мітрилу чотирма цитринами. Результатом буде краще розуміння магічної гемології та знання створювати вишукані мітрилові наплічники.", [3] = "Принесіть сорок злитків мітрилу та чотири цитрини Ґальвану Древньому в Тернисту долину.", [4] = "Після доброї роботи м'язи мають нити, а тіло — боліти!", [5] = "Неможливо відірвати очей від його блиску, {ім'я}. Так, цитрин — славний самоцвіт.\n\nДивись уважно і дізнайся, чого може навчити така знахідка!", ["en"] = "The Art of the Imbue", ["tasks"] = { ["Citrine"] = "цитрин", ["Citrine (Provided)"] = "цитрин (видано)", ["Mithril Bar"] = "злиток мітрилу", ["Mithril Bar (Provided)"] = "злиток мітрилу (видано)" } },
    [2764] = { [1] = "Найкращий учень Ґальвана", [2] = "Якщо ти {стать:готовий:готова} завершити свою підготовку з Ґальваном, тобі слід відправитися до Пристробляху.\n\nТам ти знайдеш мого найкращого учня, Трентона Світломолота. Він може багато чого навчити тебе у справі виготовлення вишуканого мітрилу. В іншому випадку, залишайся тут і продовжуй вчитися!\n\nА, так, Пристроблях знаходиться у Танарісі.", [3] = "Поговоріть з Трентоном Світломолотом в Пристробляху.", [5] = "Тебе прислав Ґальван Древній?\n\n<Трентон вклоняється.>\n\nДля мене велика честь познайомитися з ще {стать:одним учнем:однією ученицею} майстра!", ["en"] = "Galvan's Finest Pupil" },
    [2765] = { [1] = "Коваль-експерт", [2] = "Коли ти перший раз {стать:прийшов:прийшла} до мене, я відчув, що ти станеш {стать:одним:однією} з моїх найкращих {стать:учнів:учениць}! Ти без вагань {стать:віддав:віддала} Макґавану якусь потужну дрібничку лише для того, щоб зустрітися зі мною. Така сліпа віра та відданість ремеслу повинні бути винагороджені.\n\nТи {стать:досяг:досягла} високої майстерності в ковальстві, {ім'я}. Збирай свою нагороду!", [3] = "Заберіть свою нагороду у Ґальвана Древнього!", [4] = "Збирай свою нагороду!", [5] = "Цілком доречно, що ти отримуєш дрібничку набагато більшої сили, ніж та, якою ти {стать:пожертвував:пожертвувала}, щоб потрапити сюди. Користуйся нею на здоров'я, {ім'я}.", ["en"] = "Expert Blacksmith!", ["tasks"] = { ["You Are The Big Winner"] = "Ти — головний переможець" } },
    [2766] = { [1] = "Знайти OOX-22/ФЕ!", [2] = "Ви виявили дивний яйцеподібний металевий пристрій. Покрутивши одну з його ручок, ви пробуджуєте яйце, і воно відкриває якийсь пристрій гномів! Зсередини лунає голос.\n\n\"Мене звати Оґлторп, і мій автономний робот розбився! Я винагороджу тебе, якщо знайдеш його! Будь ласка, віднеси цей маяк до робота.\n\nЯ вже вирахував координати для тебе! Він в печері біля долини Лихий Шрам.\"", [3] = "Принесіть аварійний маяк до автономного робота Оґлторпа в печеру біля долини Лихий Шрам.", [4] = "Здається, ви знайшли уламки... механічної курки? З яйця знову лунає голос:\n\n\"Так, чудова робота! Це дійсно мій автономний робот, але мої дані показують, що йому потрібен заряд енергії, щоб він зміг повернутись до Грабіжної Бухти на ремонт. Для початку помісти маяк всередину апарата. А решту він зробить сам!\"", [5] = "Ви помістили яйце... аварійний маяк... в середину курки... автономного робота.\n\nЗсередини робота лунає гудіння та дзижчання — він намагається встати. Коли робот оживає, зсередини долинає голос Оґлторпа:\n\n\"Принаймні, OOX-22/ФЕ працює, але йому потрібен капітальний ремонт! Він надто важкий для того, щоб ти {стать:зміг:змогла} нести його... але у мене є ідея. Хочеш трохи доглянути за ним?\"", ["en"] = "Find OOX-22/FE!", ["tasks"] = { ["OOX-22/FE Distress Beacon"] = "аварійний маяк OOX-22/ФЕ", ["OOX-22/FE Distress Beacon (Provided)"] = "аварійний маяк OOX-22/ФЕ (видано)" } },
    [2767] = { [1] = "Врятувати OOX-22/ФЕ!", [2] = "Голос гнома знову тріщить з робота:\n\n\"Мені потрібно перемістити OOX-22/ФЕ на відкрите, безпечне місце, щоб він міг почати тривалу процедуру зльоту. Він має вбудовану систему маскування, але мені потрібен час, щоб зробити її знову працездатною. Мені потрібно, щоб ти {стать:супроводжував:супроводжувала} робота з його поточного місцеперебування до, скажімо, доків на Забутому узбережжі! Це має бути ідеальне місце, достатньо просторе, щоб підготувати апарат до польоту!\"\n\n\"Проведи його до порту, а потім приходь поговорити зі мною в Грабіжну Бухту! Оґлторп Обриднус — кінець зв'язку!\"", [3] = "Проведіть OOX-22/ФЕ в доки на Забутому узбережжі, а потім звітуйте Оґлторпу Обриднусу в Грабіжній Бухті.", [4] = "Так, я Оґлторп Обриднус, майстер-винахідник до твоїх послуг! Чи можу я тобі чимось допомогти?", [5] = "О, ТИ - {стать:великий рятівник:велика рятівниця} OOX-22/ФЕ! У мене просто слів немає, настільки я вдячний за твою допомогу! Моя серія автономних роботів потребує вдосконалень, але завдяки тобі, я заощадив безліч часу на відновлення і купу золота на дорогі деталі!\n\nБудь ласка, обери будь-який з цих предметів. Ще раз дякую за твою щедру допомогу, мої роботи і я у тебе в боргу!", ["en"] = "Rescue OOX-22/FE!", ["tasks"] = { ["Escort OOX-22/FE to the dock along the Forgotten Coast"] = "Супровід OOX-22/FE до доку вздовж Забутого узбережжя" } },
    [2768] = { [1] = "Водоматичний стрижень", [2] = "Сержант Блай обікрав мене! Він сказав, що тільки позичить, але насправді вкрав мій водоматичний стрижень!!! Як же я без нього дізнаюсь, де копати нові колодязі?!\n\nЗнайди Блая і принеси мені мій стрижень! Я чув, що він разом зі своєю бандою недоброчесних шукачів пригод подався на пошуки скарбів у Зул'Фаррак, що на заході. Б'юся об заклад, ти знайдеш його там.\n\nСподіваюся, що тролі подбали про нього, бо якщо тобі доведеться силою забирати жезл, то це може перерости в серйозну бійку.", [3] = "Принесіть водоматичний стрижень головному інженеру Трюмосвисту в Пристроблях.", [4] = "Тобі вдалось знайти сержанта Блая? Ти {стать:забрав:забрала} у нього мій водоматичний стрижень?", [5] = "Молодець, {ім'я}, ти {стать:знайшов:знайшла} його! Тобі довелося застосовувати силу? Сподіваюсь, ти як слід {стать:надер:надерла} зад Блаю та його банді!", ["en"] = "Divino-matic Rod", ["tasks"] = { ["Divino-matic Rod"] = "водоматичний стрижень", ["Divino-matic Rod (Provided)"] = "водоматичний стрижень (видано)" } },
    [277] = { [1] = "Вогняне табу", [2] = "Мохошкурі рубають дерева Заболоття і використовують плоть дерев для вогнища, щоб зігрітись. Я не можу більше терпіти цей біль!\n\nПозбудь Мохошкурих грубого кременю, їх інструменту для створення вогню. Кремінь носять усі Мохошкурі, окрім менших мохошкурих гнолів та мохошкурих дворняг.", [3] = "Принесіть Ретілю Вартовому Природи 9 грубих кременів.", [4] = "В тебе є інструменти гнолів для розведення вогню?", [5] = "... дякую. Я розіб'ю ці кремені та кину їх в море, так вони більше ніколи не використовуватимуться для спалювання живих дерев.", ["en"] = "Fire Taboo", ["tasks"] = { ["Crude Flint"] = "грубий кремінь", ["Crude Flint (Provided)"] = "грубий кремінь (видано)" } },
    [2770] = { [1] = "Ґаз'рілла", [2] = "У глибинах Зул'Фарраку — міста піщаних тролів у Танарісі, є священний басейн. З цього басейну тролі викликають величезного звіра! Ґаз'ріллу! Він такий могутній, що навіть луска потріскує від його енергії. Саме цю енергію я хочу використати у своїй машині!\n\nПринеси мені наелектризовану луску Ґаз'рілли!\n\nАле виклик Ґаз'рілли — це таємниця тролів, з якою вони просто так не розлучаться.", [3] = "Принесіть наелектризовану луску Ґаз'рілли Віззлу Латуноболту на Мерехтливі рівнини.", [4] = "Ти {стать:приніс:принесла} луску? Мені кортить використати її енергію!", [5] = "Ого, ти {стать:дістав:дістала} луску! Дякую, {ім'я}. Я не можу дочекатися, коли почну працювати з нею!\n\nОтже, ти {стать:бачив:бачила} Ґаз'ріллу? Вона справді така велика, як про неї говорять??", ["en"] = "Gahz'rilla", ["tasks"] = { ["Gahz'rilla's Electrified Scale"] = "наелектризована луска Ґаз'рілли", ["Gahz'rilla's Electrified Scale (Provided)"] = "наелектризована луска Ґаз'рілли (видано)" } },
    [2771] = { [1] = "Гарна голова на плечах", [2] = "Здається, майстер запланував це з самого початку. Я не навчився створювати предмети, які {стать:навчився:навчилася} виготовляти ти, і тебе не було навчено того, чого навчився виготовляти я.\n\nМайстер мудрий, {ім'я}. Ми навчатимемо одне одного!\n\nПокажи мені, як створювати мітриловий капюшон та вишукані мітрилові наплічники, а я покажу тобі, як створити вишуканий мітриловий шолом.", [3] = "Принесіть два мітрилових капюшона та одну пару вишуканих мітрилових наплічників до Трентона Світломолота.", [4] = "Ти {стать:створив:створила} необхідні предмети, {ім'я}?", [5] = "Відмінно! Справедливий обмін, як на мене. Дивись і вчись, {ім'я}!", ["en"] = "A Good Head On Your Shoulders", ["tasks"] = { ["Mithril Coif"] = "мітриловий капюшон", ["Mithril Coif (Provided)"] = "мітриловий капюшон (видано)", ["Ornate Mithril Shoulder"] = "вишукані мітрилові наплічники", ["Ornate Mithril Shoulder (Provided)"] = "вишукані мітрилові наплічники (видано)" } },
    [2772] = { [1] = "Світ біля твоїх ніг", [2] = "На торішньому чемпіонаті з ковальства всі глядачі бачили, як мене збив з ніг боягузливий пес з ТзНБ \"Авантюра\". Але вони не знають, як я примудрився виграти змагання: правильно, завдяки вишуканим мітриловим чоботам!\n\nНа цьогорічний турнір мені знадобляться вишукані мітрилові штани, адже серед учасників буде подрібнювач з ТзНБ \"Авантюра\"! Навчи мене робити штани, а я навчу тебе робити чоботи!", [3] = "Принесіть дві пари важких мітрилових чобіт та одні вишукані мітрилові штани до Трентона Світломолота.", [4] = "Ти {стать:створив:створила} необхідні предмети, {ім'я}?", [5] = "Світ буде біля твоїх ніг, {ім'я}! Нехай усі припадуть до твоїх ніг від твоєї величі!", ["en"] = "The World At Your Feet", ["tasks"] = { ["Heavy Mithril Boots"] = "важкі мітрилові чоботи", ["Heavy Mithril Boots (Provided)"] = "важкі мітрилові чоботи (видано)", ["Ornate Mithril Pants"] = "вишукані мітрилові штани", ["Ornate Mithril Pants (Provided)"] = "вишукані мітрилові штани (видано)" } },
    [2773] = { [1] = "Мітриловий хлопець", [2] = "В цих краях мене знають як мітрилового хлопця. Я постачаю вишуканий мітрил мандрівникам з усього світу.\n\n<Трентон шепоче.>\n\nМало хто знає, але я не знаю техніки створення вишуканих мітрилових рукавиць. Шшш! Це буде нашою маленькою таємницею.\n\nНавчи мене створювати вишукані мітрилові рукавиці, {ім'я}, і натомість я покажу тобі плоди мого навчання під керівництвом Ґальвана: вишукану мітрилову кірасу.", [3] = "Принесіть два важкі мітрилові кіраси та одну пару вишуканих мітрилових рукавиць до Трентона Світломолота.", [4] = "Ти {стать:створив:створила} необхідні предмети, {ім'я}?", [5] = "Дякую за все, чому ти мене {стать:навчив:навчила}, {ім'я}. Незабаром ти станеш {стать:володарем:володаркою} справжнього короля вишуканого міфрилового обладунку.\n\nДивись!", ["en"] = "The Mithril Kid", ["tasks"] = { ["Heavy Mithril Breastplate"] = "важка мітрилова кіраса", ["Heavy Mithril Breastplate (Provided)"] = "важка мітрилова кіраса (видано)", ["Ornate Mithril Gloves"] = "вишукані мітрилові рукавиці", ["Ornate Mithril Gloves (Provided)"] = "вишукані мітрилові рукавиці (видано)" } },
    [278] = { [1] = "Темна загроза", [2] = "Негайно починай збирати реагенти, {ім'я}. Павучу отруту ти можеш зібрати з тутешніх павуків. Сльозу кроколіска - з кроколісків біля озера. А от з кристалами Мо'ґрош буде важче - їх видобувають огри, що живуть на північному сході. Але й у них такі кристали - рідкість.\n\nМи маємо якомога швидше знешкодити вибухівку Темного Заліза! Повертайся до мене, як знайдеш все необхідне, і я приготую суміш.", [3] = "Принесіть яд павука, кристал Мо'ґрош та сльозу кроколіска старшому інженеру Греблеру.", [4] = "Ти вже {стать:зібрав:зібрала} все необхідне? У нас обмаль часу!", [5] = "Ти якраз вчасно, {ім'я}!", ["en"] = "A Dark Threat Looms", ["tasks"] = { ["Crocolisk Tear"] = "сльоза кроколіска", ["Crocolisk Tear (Provided)"] = "сльоза кроколіска (видано)", ["Lurker Venom"] = "павуча отрута", ["Lurker Venom (Provided)"] = "павуча отрута (видано)", ["Mo'grosh Crystal"] = "кристал Мо'ґрош", ["Mo'grosh Crystal (Provided)"] = "кристал Мо'ґрош (видано)" } },
    [2781] = { [1] = "РОЗШУКУЄТЬСЯ: Халіф Скорпідожал", [2] = "РОЗШУКУЄТЬСЯ: Халіф Скорпідожал!\n\nПристробляхводоканал заплатить велику винагороду за голову Халіфа Скорпідожала, лідера банди розбійників Пустелебродів. Його злочини включають:\n\n1. Вбивство працівників Пристробляхводоканалу!\n2. Крадіжку ресурсів Пристробляхводоканалу!\n3. Захоплення майна Пристробляхводоканалу!\n\nПринесіть доказ смерті Халіфа Скорпідожала головному інженеру Трюмосвисту та отримайте винагороду!", [3] = "Принесіть голову Халіфа Скорпідожала головному інженеру Трюмосвисту в Пристроблях.", [4] = "Так, {клас:к}, я працівник Пристробляхводоканалу. Чим я можу тобі допомогти?", [5] = "Нарешті справедливість взяла гору! Ти {стать:завдав:завдала} потужного удару тим паскудним кочівникам! Можливо, смерть Скорпідожала відлякає цих розбійників від колодязів Пристробляху!\n\nВід імені Пристробляхводоканалу, я з радістю вручаю тобі цю винагороду. Ти {стать:зробив:зробила} величезну послугу всім нам.", ["en"] = "WANTED: Caliph Scorpidsting", ["tasks"] = { ["Caliph Scorpidsting's Head"] = "голова Халіфа Скорпідожала", ["Caliph Scorpidsting's Head (Provided)"] = "голова Халіфа Скорпідожала (видано)" } },
    [2783] = { [1] = "Дрібні сварки", [2] = "Ми б'ємося не з тим ворогом, {ім'я}.\n\nСправжня сила в цих землях продовжує зростати, поки ми сваримось з орками за випалену землю.\n\nЧи продовжимо ми воювати з Ордою на цих землях, лише щоб одного дня бути переможеними арміями Палаючого Легіону? Це марно.\n\nТреба не зважати на відмінності між нами, {ім'я}, поговори з полеглим героєм Орди. Він знає правду про Спустошені землі.", [3] = "Поговоріть із полеглим героєм Орди на кордоні Спустошених земель та болота.", [5] = "Альянс бажає допомогти?\n\nЯ думав, що ніколи більше не побачу цей день. День, коли Альянс пліч-о-пліч битиметься поруч з Ордою проти спільного ворога.\n\nЦе буде... ми об'єднаємося.", ["en"] = "Petty Squabbles" },
    [280] = { [1] = "Темна загроза", [2] = "Я недавно помітив кількох заколотників Темного Заліза, що плили до дамби з великою діжкою. І поруч не було жодного горянина, щоб їх зупинити! Боюсь, що вони могли закласти сефорієву вибухівку біля основи дамби і вона може вибухнути будь-якої миті! Дай-но я змішаю компоненти... Ось і нейтралізуюча суміш.\n\nА тепер бери суміш і влий в бочку, поки не пізно! Поквапся!", [3] = "Старший інженер Греблер просить вас проплисти до основи дамби, знайти бочку з вибухівкою і влити в неї нейтралізуючу суміш.", [4] = "Ви повільно відкручуєте кришку з діжки.", [5] = "Вміст діжки шипить від вливання нейтралізуючої суміші.", ["en"] = "A Dark Threat Looms", ["tasks"] = { ["Disarming Mixture"] = "нейтралізуюча суміш", ["Disarming Mixture (Provided)"] = "нейтралізуюча суміш (видано)" } },
    [2801] = { [1] = "Сумна історія", [2] = "Перш ніж ми зможемо продовжити, ти маєш почути мою історію.", [3] = "Послухайте історію полеглого героя Орди.", [4] = "Послухай, що я тобі скажу, {ім'я}.", [5] = "Настав час діяти, {ім'я}.", ["en"] = "A Tale of Sorrow", ["tasks"] = { ["A Tale of Sorrow"] = "Оповідь про горе" } },
    [283] = { [1] = "Темна загроза", [2] = "Діжка тихо шипить.", [3] = "Схоже що нейтралізуюча суміш подіяла. Поверніться до старшого інженера Греблера і повідомте добру звістку.", [5] = "Я тобі безмежно вдячний, {ім'я}! Ти {стать:врятував:врятувала} Каменярську дамбу! Без твоєї допомоги терористи Темного Заліза точно б знищили цю величну споруду. Королівство і Альянс пишаються тобою, {стать:відважний:відважна} {клас:к}.\n\nДамба знову в безпеці... Принаймні, поки що...", ["en"] = "A Dark Threat Looms" },
    [2841] = { [1] = "Техновійни", [2] = "Два роки тому технології гномів використовувались хіба що як жарт. Часи, звісно, змінилися. Зараз вони побудували машину, яка краща за всі наші моделі подрібнювачів разом узяті. Мені потрібні її креслення, {ім'я}!\n\nНа жаль, вони знаходяться в сейфі біля мекженера Термоштепселя. Що ще гірше — код від сейфа знає лише він.\n\nЗроби все можливе, щоб отримати цей код, {ім'я}. Потім відкрий сейф і принеси мені креслення!", [3] = "Дістаньте креслення машини та код від сейфа Термоштепселя в Гномреґані та принесіть їх Ноґґу в Орґріммар.", [4] = "Я не бачу креслень. Ти десь {стать:сховав:сховала} їх чи просто стоїш тут, щоб мене роздратувати?", [5] = "Я знав, що в тебе все вийде, {ім'я}! А Совік сумнівався...\n\n<Ноґґ відкашлюється.>\n\nТепер, коли ми маємо креслення, це лише питання часу, коли ми розберемось в рішеннях гномів, які були використані при створенні машини. Вони знадобляться нам для нових моделей подрібнювачів.", ["en"] = "Rig Wars", ["tasks"] = { ["Rig Blueprints"] = "креслення машини", ["Rig Blueprints (Provided)"] = "креслення машини (видано)", ["Thermaplugg's Safe Combination"] = "код від сейфа Термоштепселя", ["Thermaplugg's Safe Combination (Provided)"] = "код від сейфа Термоштепселя (видано)" } },
    [2842] = { [1] = "Старший інженер Скуті", [2] = "Щойно ми почули від Кернобі про нову машину гномів, ми зі Скуті почали працювати над Транполіпортом 6000 - найшвидшим і найнадійнішим способом дістатися до Гномреґану.\n\nІ він нарешті готовий, {ім'я}. Якщо хочеш спробувати — вирушай до Грабіжної Бухти та поговори зі Скуті, що знаходиться під гніздом грифонів, неподалік таверни «Солоний матрос». До Грабіжної Бухти можеш дістатись на човні з Брашпиля.\n\nАле звісно, ти завжди можеш спробувати добігти до Гномреґану через гори Дун-Морогу, що кишать дворфами!", [3] = "Поговоріть зі Скуті в Грабіжній Бухті.", [5] = "Вона прекрасна, чи не так? Вершина гоблінської транспортної технології — вибухнула лише з десяток разів.\n\nТа не хвилюйся, {ім'я}, вона більше не вибухне — я її полагодив. А якщо і вибухне, то все буде швидко і безболісно.", ["en"] = "Chief Engineer Scooty" },
    [2843] = { [1] = "До Гномреґану!", [2] = "Поки транспондер у тебе — все, що тобі потрібно зробити — це наступити на платформу, і ти перенесешся до Гномреґану.\n\nТи можеш відчути деякі незвичні побічні ефекти, але жоден з них не має залишитись... надовго.\n\nЛедь не забув найважливіше — повернення. Коли захочеш повернутись — просто наступи на платформу трансполіпорта на іншій стороні, у Гномреґані!\n\nТепер я маю відкалібрувати транспондер відповідно до твого розміру та ваги.", [3] = "Зачекайте, поки Скуті відкалібрує гоблінський транспондер.", [4] = "Готово!", [5] = "Все готово! Коли будеш {стать:готовий:готова} — просто наступи на платформу.", ["en"] = "Gnomer-gooooone!", ["tasks"] = { ["Goblin Transponder"] = "гоблінський транспондер" } },
    [2844] = { [1] = "Страж-велетень", [2] = "Немає з мене ніякої користі, {ім'я}. Мені доручили пильнувати за моєю маленькою подругою, Шей, але вона якось втекла від мене. Я не знаю, що саме сталося, але востаннє я бачив її, коли ми йшли повз руїни на північ звідси.\n\nВсе було добре, але потім я повернувся, а... її нема.\n\nТепер я навіть і не знаю, що мені робити. Що мені робити, {ім'я}? Я дуже хвилююся.\n\nМожливо, ти можеш піти пошукати Шей? Твої ноги можуть рухатись набагато швидше за мої.", [3] = "Знайдіть загублену нічну ельфу.", [5] = "Я так рада, що ти мене {стать:знайшов:знайшла}! Мушу зізнатися, я трохи заблукала... Але хіба це не прекрасне місце?", ["en"] = "The Giant Guardian" },
    [2845] = { [1] = "Мандрівниця Шей", [2] = "Може ти допоможеш мені знайти дорогу до мого друга Скелекуса? Він мав пильнувати мене... Але зі мною іноді трапляється, що я йду, куди очі дивляться. Навколо стільки цікавого, і я легко забуваю про все на світі.\n\nАле є одна річ, яка завжди привертає мою увагу.\n\nВ цій скрині ти знайдеш дзвіночок, який для мене дуже цінний. Я просто обожнюю його дзвін. Я даю тобі слово, якщо я заблукаю, все, що тобі потрібно зробити — це подзвонити в дзвіночок і я прибіжу до тебе.", [3] = "Візьміть зі скрині дзвіночок Шей.\n\nПроведіть Шей Листогін до табору Скелекуса.", [4] = "Я вже почав хвилюваться за тебе! Дуже дякую, що {стать:повернув:повернула} Шей додому, {ім'я}.", [5] = "Що? Кажеш, дзвіночком можна покликати Шей назад, коли вона втече? Ти ба!\n\nТи так багато для мене {стать:зробив:зробила}, {ім'я}. На, тримай.", ["en"] = "Wandering Shay", ["tasks"] = { ["Shay's Bell"] = "дзвіночок Шей", ["Shay's Bell (Provided)"] = "дзвіночок Шей (видано)" } },
    [2846] = { [1] = "Тіара Глибин", [2] = "Давним-давно у мене була красива ювелірна прикраса — тіара Глибин. Попри її красу, вона ще була наділена великою силою, якою могли користуватися тільки ті, хто вмів з нею поводитися.\n\nА коли звістка про тіару дійшла до гідроманта Велрати, вона вирішила присвоїти собі її. Вона відправила своїх підлеглих до мене, щоб вони вкрали тіару, поки мене не було вдома. Злодії!\n\nЯ хочу повернути свою тіару! Йди в Зул'Фаррак, місто тролів у Танарісі, знайди Велрату та відбери у неї тіару. Якщо принесеш мені її — заслужиш мою безмежну вдячність.", [3] = "Принесіть тіару Глибин Табеті в Бруднолипку трясовину.", [4] = "Ти {стать:приніс:принесла} тіару, {ім'я}? Велрата дізналася, чого коштує переходити мені дорогу?", [5] = "Чудово! Ти {стать:знайшов:знайшла} її! І, що не менш важливо, Велрата втратила її! Дякую, {ім'я}. Я навіки твоя боржниця!\n\nІ якщо раніше я висловлювалась трохи... неввічливо, не звертай на це уваги. Ти зрозумієш, що я набагато приємніше відношуся до тих, хто не намагається мене обікрасти.", ["en"] = "Tiara of the Deep", ["tasks"] = { ["Tiara of the Deep"] = "тіара Глибин", ["Tiara of the Deep (Provided)"] = "тіара Глибин (видано)" } },
    [2847] = { [1] = "Обладунки з дикої шкіри", [2] = "{ім'я}, твої вміння роботи зі шкірою вже неймовірні. У мене є кілька викройок, які ти {стать:міг би:могла б} опанувати... Обладунки з дикої шкіри! Дика шкіра використовує потужні та хаотичні властивості диколоззя, яке можна знайти в районах буйної рослинності та на деяких тамтешніх створіннях. Обладунки, виготовлені з використанням цих матеріалів, неперевершені для {стать:ремісника:ремісниці} твого рівня.\n\nЯ навчу тебе їх виготовленню, але тобі доведеться трохи попрацювати. Для початку принеси мені десять шматків грубої шкіри. Після цього ми обговоримо деталі.", [3] = "Принесіть 10 товстих шкір Пратту Макґруббену в фортецю Перомісяць.", [4] = "Прояснімо: ти будеш {стать:моїм учнем:моєю ученицею}, поки вивчатимеш мистецтво виготовлення обладунків з дикої шкіри. Оскільки диколоззя є потужним та хаотичним, воно дарує випадкові, але сильні характеристики обладункам, які ти створюватимеш. Проте, ці знання мені було непросто здобути.\n\nПерша плата для початку — десять шматків товстої шкіри.\n\nПісля цього ми перейдемо до роботи, яку тобі потрібно буде виконати, щоб отримати викрійки.", [5] = "Що ж, {ім'я}, я радий, що ти {стать:став моїм учнем:стала моєю ученицею}. Ти {стать:прийняв:прийняла} розумне рішення стати {стать:шкірником:шкірницею}. Всі, хто користується шкіряними обладунками, звертатиметься до тебе, коли ти навчишся створювати предмети з дикої шкіри.\n\nДо роботи. З чого хочеш почати?", ["en"] = "Wild Leather Armor", ["tasks"] = { ["Thick Leather"] = "товста шкіра", ["Thick Leather (Provided)"] = "товста шкіра (видано)" } },
    [2848] = { [1] = "Наплічники з дикої шкіри", [2] = "Наплічники з дикої шкіри чудово забезпечують відмінний захист верхньої частини рук та плечей. Як і всі обладунки з дикої шкіри, вони прошиті диколоззям, що надає їм випадкові, але дуже потужні магічні властивості.\n\nДля їх виготовлення знадобиться шість накладок з товстої шкіри та диколоззя. Це не повинно бути надто складним завданням для тебе.", [3] = "Принесіть 6 накладок з товстої шкіри та диколоззя Пратту Макґруббену в фортецю Перомісяць.", [4] = "Ти {стать:приніс:принесла} шість накладок з товстої шкіри та диколоззя?\n\nНе думай про виготовлення обладунків як про монотонну роботу. Стабільний метод виготовлення, який ти розвинеш виконуючи ці завдання, допоможе тобі підготуватись до складної роботи, необхідної для створення обладунків з дикої шкіри.\n\nБачиш — те, що ти робиш для мене, має свою мету...", [5] = "Ці накладки дуже якісні, {ім'я}. Єдине, чого я вимагаю не лише у своїй роботі, але й у роботі тих, хто працює на мене, — це якість.\n\nТи добре {стать:попрацював:попрацювала}, щоб заслужити цю викрійку. Сподіваюся, вона принесе тобі таку ж користь, як і мені.", ["en"] = "Wild Leather Shoulders", ["tasks"] = { ["Thick Armor Kit"] = "накладки з товстої шкіри", ["Thick Armor Kit (Provided)"] = "накладки з товстої шкіри (видано)", ["Wildvine"] = "диколоззя", ["Wildvine (Provided)"] = "диколоззя (видано)" } },
    [2849] = { [1] = "Жилет з дикої шкіри", [2] = "Жилети з дикої шкіри є основою будь-якого комплекту обладунків з дикої шкіри. Каркас жилета та плетення з диколоззя у ньому створюють виріб, який надає максимальний захист корпусу, дозволяючи потужній магії лози проникати через одяг.\n\nДля викрійки цього жилета мені знадобиться дві кіраси з черепашачої луски, дві пари рукавиць з черепашачої луски та диколоззя. Це не легке замовлення, але, думаю, ти впораєшся з ним.", [3] = "Принесіть 2 кіраси з черепашачої луски, 2 пари рукавиць з черепашачої луски та диколоззя Пратту Макґруббену в фортецю Перомісяць.", [4] = "Ти {стать:приніс:принесла} дві кіраси та дві пари рукавиць з черепашачої луски, про які я казав? І не забудь про диколоззя!\n\nЩе працюючи з найпростішими викрійками, ми розуміємо, що складне і просте будується за одними й тими ж принципами. Таким чином, виготовлення кірас з черепашачої луски готує тебе до створення жилета з дикої шкіри.\n\nА рукавиці... вони просто для мого власного користування. Пам'ятай, ти працюєш на мене!", [5] = "Дуже гарні вироби, {ім'я}. Майстерність і увага, вкладені в їх створення, забезпечують їм вартість на кілька срібних більше, ніж у звичайних виробів.\n\nТи {стать:виконав:виконала} моє замовлення, ось твоя винагорода. Знання створення жилетів з дикої шкіри тепер належить тобі!", ["en"] = "Wild Leather Vest", ["tasks"] = { ["Turtle Scale Breastplate"] = "кіраса з черепашачої луски", ["Turtle Scale Breastplate (Provided)"] = "кіраса з черепашачої луски (видано)", ["Turtle Scale Gloves"] = "рукавиці з черепашачої луски", ["Turtle Scale Gloves (Provided)"] = "рукавиці з черепашачої луски (видано)", ["Wildvine"] = "диколоззя", ["Wildvine (Provided)"] = "диколоззя (видано)" } },
    [2850] = { [1] = "Шолом з дикої шкіри", [2] = "Шолом з дикої шкіри надає відмінний захист життєво важливих ділянок голови без втрати комфорту. Як і для всіх обладунків з дикої шкіри, вшите в шолом диколоззя надає йому випадкові, але дуже потужні магічні властивості. Тим, хто ходить у шкіряних обладунках, така річ обов'язково знадобиться!\n\nДля цієї викрійки мені знадобляться два мундири нічного краєвиду, дві пов'язки нічного краєвиду та диколоззя. Виконай цей запит, і викрійка буде твоєю!", [3] = "Принесіть 2 мундири нічного краєвиду, 2 пов'язки нічного краєвиду та диколоззя Пратту Макґруббену в фортецю Перомісяць.", [4] = "Мені потрібно, щоб ти {стать:зробив:зробила} мундири та пов'язки, а також {стать:приніс:принесла} шматок диколоззя, перш ніж я поділюся з тобою знанням про шоломи з дикої шкіри.\n\nБудь-якому мандрівнику необхідний захист для голови, чи то проста бандана, чи то шолом, що повністю закриває голову. Основи створення головних уборів залишаються незмінними, незалежно від зовнішнього вигляду виробу.", [5] = "Спорядження нічного краєвиду, яке ти {стать:зробив:зробила}, ідеально відповідає моїм вимогам, {ім'я}. Я очікував не меншого від {стать:шкірника:шкірниці} твого рівня.\n\nТи дійсно {стать:заслужив:заслужила} цю викрійку. Я передаю її тобі та сподіваюся, що ти отримаєш від неї гідну вигоду.", ["en"] = "Wild Leather Helmet", ["tasks"] = { ["Nightscape Headband"] = "пов'язка нічного краєвиду", ["Nightscape Headband (Provided)"] = "пов'язка нічного краєвиду (видано)", ["Nightscape Tunic"] = "мундир нічного краєвиду", ["Nightscape Tunic (Provided)"] = "мундир нічного краєвиду (видано)", ["Wildvine"] = "диколоззя", ["Wildvine (Provided)"] = "диколоззя (видано)" } },
    [2851] = { [1] = "Чоботи з дикої шкіри", [2] = "Ти вже багато чому {стать:навчився:навчилася}, {ім'я}, проте ще є багато знань. Наступними будуть чоботи з дикої шкіри, основа будь-якого комплекту обладунків.\n\nЦі чоботи створені, щоб комфортно огорнути ноги, водночас захищаючи їх від небезпек пригод. А їхні м'які підошви будуть благословенням для тих, хто обирає непомітність.\n\nДля цієї викрійки мені потрібні дві пари штанів та дві пари чобіт нічного краєвиду. Також мені знадобляться два диколоззя... не одне. Коли матимеш все це, дай мені знати.", [3] = "Принесіть 2 пари штанів нічного краєвиду, 2 пари чобіт нічного краєвиду та 2 диколоззя Пратту Макґруббену в фортецю Перомісяць.", [4] = "Замовлення на штани, чоботи та диколоззя повинне бути виконане, перш ніж ти отримаєш викрійку, {ім'я}. Ти {стать:закінчив:закінчила}?\n\nВже з першої пари чобіт, яку ми навчаємось робити, ми починаємо розуміти, що якісні чоботи мають бути збалансовані між комфортом і практичністю. Дотримуючись цих вимог, ми здатні створювати вироби, які дозволяють носію не відчувати втому, яка зламала б тих, хто носить вироби нижчої якості.", [5] = "Ти знову {стать:виконав:виконала} моє замовлення з майстерністю досвідченого професіонала. Ти {стать:заслужив:заслужила} цю викрійку і мою подяку.", ["en"] = "Wild Leather Boots", ["tasks"] = { ["Nightscape Boots"] = "чоботи нічного краєвиду", ["Nightscape Boots (Provided)"] = "чоботи нічного краєвиду (видано)", ["Nightscape Pants"] = "штани нічного краєвиду", ["Nightscape Pants (Provided)"] = "штани нічного краєвиду (видано)", ["Wildvine"] = "диколоззя", ["Wildvine (Provided)"] = "диколоззя (видано)" } },
    [2852] = { [1] = "Штани з дикої шкіри", [2] = "Засвоївши основи, ти {стать:готовий:готова} освоїти складніші речі, {ім'я}. Штани з дикої шкіри є однією з найміцніших і найпотужніших частин шкіряних обладунків. Вони відмінно захищають живіт, ноги та інші важливі частини тіла. А разом з покращенням, яке забезпечує диколоззя, кожен мандрівник буде дякувати тобі за такі штани.\n\nЩоб отримати цю викрійку, ти маєш принести два шоломи з черепашачої луски, два браслети з черепашачої луски та два диколоззя.", [3] = "Принесіть 2 шоломи з черепашачої луски, 2 браслети з черепашачої луски та 2 диколоззя Пратту Макґруббену в фортецю Перомісяць.", [4] = "Ти вже {стать:виготовив:виготовила} браслети та шоломи з черепашачої луски? І не забудь про два диколоззя.\n\nТи починаєш усвідомлювати могутність, що ховається в обладунках з дикої шкіри. Уміння виготовляти такі потужні обладунки, неоціненна для шкірника. Єдине обмеження — це наявність потрібних ресурсів для виготовлення виробів, але не їхня якість!", [5] = "Ти знову бездоганно {стать:виконав:виконала} моє замовлення. Можливо, одного дня я звернусь до ТЕБЕ у пошуках знань, еге ж, {ім'я}?\n\nОсь викрійка для штанів, разом з моєю дякою. Запам'ятай ці знання, і нехай твої вироби будуть гідні твоїх здібностей!", ["en"] = "Wild Leather Leggings", ["tasks"] = { ["Turtle Scale Bracers"] = "браслети з черепашачої луски", ["Turtle Scale Bracers (Provided)"] = "браслети з черепашачої луски (видано)", ["Turtle Scale Helm"] = "шолом з черепашачої луски", ["Turtle Scale Helm (Provided)"] = "шолом з черепашачої луски (видано)", ["Wildvine"] = "диколоззя", ["Wildvine (Provided)"] = "диколоззя (видано)" } },
    [2853] = { [1] = "Майстер дикої шкіри", [2] = "Ну, {ім'я}, ти — втілення старанності. Залишилася лиш одна викрійка предмета з дикої шкіри, який ти не вмієш виготовляти. Я не примушу тебе працювати, щоб отримати її. Ти {стать:заслужив:заслужила} її, і навіть більше... але я не можу дати її тобі. Мій учитель, той, хто ввів мене в ремесло, повинен нагородити тебе.\n\nВіднеси цей лист до Телоніса; він викладає шкірництво у Дарнасі. Покажи йому лист, і дозволь йому визнати тебе {стать:рівним:рівною}, так само як і я.", [3] = "Передайте лист Пратта Телонісу, реміснику шкірництва з Дарнасу.", [4] = "Вітаю, {раса:к}... Я бачу, що ти {стать:такий же шкірник:така ж шкірниця}, як і я. Ти {стать:прийшов:прийшла} до мене, щоб вчитися, чи, можливо, маєш до мене іншу справу?", [5] = "А, так, тебе прислав Пратт. Хоча він і людина, іноді він нагадує мені нас, нічних ельфів. Його відданість і талант у роботі зі шкірою вражають. Те, що він так хвалив тебе у цьому листі, свідчить про повагу, яку я визнаю.\n\nЯ знаю, що він навчив тебе мистецтва дикої шкіри. Дозволь мені завершити твою підготовку цією викрійкою. Використовуй її з користю. Мало хто знає секрети створення плащів з дикої шкіри.", ["en"] = "Master of the Wild Leather", ["tasks"] = { ["Pratt's Letter"] = "лист Пратта", ["Pratt's Letter (Provided)"] = "лист Пратта (видано)" } },
    [2854] = { [1] = "Обладунки з дикої шкіри", [2] = "{ім'я}, твої вміння роботи зі шкірою вже неймовірні. У мене є кілька викройок, які ти {стать:міг би:могла б} опанувати... Обладунки з дикої шкіри! Дика шкіра використовує потужні та хаотичні властивості диколоззя, яке можна знайти в районах буйної рослинності та на деяких тамтешніх створіннях. Обладунки, виготовлені з використанням цих матеріалів, неперевершені для {стать:ремісника:ремісниці} твого рівня.\n\nЯ навчу тебе їх виготовленню, але тобі доведеться трохи попрацювати. Для початку принеси мені десять шматків грубої шкіри. Після цього ми обговоримо деталі.", [3] = "Принесіть 10 товстих шкір Джанґдору Стрімкому Вершнику в табір Мохаче.", [4] = "Прояснімо: ти будеш {стать:моїм учнем:моєю ученицею}, поки вивчатимеш мистецтво виготовлення обладунків з дикої шкіри. Оскільки диколоззя є потужним та хаотичним, воно дарує випадкові, але сильні характеристики обладункам, які ти створюватимеш. Проте, ці знання мені було непросто здобути.\n\nПерша плата для початку — десять шматків товстої шкіри.\n\nПісля цього ми перейдемо до роботи, яку тобі потрібно буде виконати, щоб отримати викрійки.", [5] = "Що ж, {ім'я}, я радий, що ти {стать:став моїм учнем:стала моєю ученицею}. Ти {стать:прийняв:прийняла} мудре рішення стати {стать:шкірником:шкірницею}. Всі, хто користується шкіряними обладунками, звертатиметься до тебе, коли ти навчишся володіти мистецтвом дикої шкіри.\n\nДо роботи. З чого хочеш почати?", ["en"] = "Wild Leather Armor", ["tasks"] = { ["Thick Leather"] = "товста шкіра", ["Thick Leather (Provided)"] = "товста шкіра (видано)" } },
    [2855] = { [1] = "Наплічники з дикої шкіри", [2] = "Наплічники з дикої шкіри чудово забезпечують відмінний захист верхньої частини рук та плечей. Як і всі обладунки з дикої шкіри, вони прошиті диколоззям, що надає їм випадкові, але дуже потужні магічні властивості.\n\nДля їх виготовлення знадобиться шість накладок з товстої шкіри та диколоззя. Це не повинно бути надто складним завданням для тебе.", [3] = "Принесіть 6 накладок з товстої шкіри та диколоззя Джанґдору Стрімкому Вершнику в табір Мохаче.", [4] = "Ти {стать:приніс:принесла} шість накладок з товстої шкіри та диколоззя?\n\nДумай про виготовлення обладунків як про урок стабільного та надійного ремесла. Метод виготовлення, який ти розвинеш виконуючи ці завдання, допоможе тобі підготуватись до складної роботи, необхідної для створення обладунків з дикої шкіри.\n\nКожен урок має свою мету, {ім'я}. І до кожного з них слід ставитися відповідально.", [5] = "Ці накладки дуже якісні, {ім'я}. Єдине, чого я вимагаю не лише у своїй роботі, але й у роботі своїх учнів, — це якість.\n\nТи добре {стать:попрацював:попрацювала}, щоб заслужити цю викрійку. Сподіваюся, вона принесе тобі таку ж користь, як і мені.", ["en"] = "Wild Leather Shoulders", ["tasks"] = { ["Thick Armor Kit"] = "накладки з товстої шкіри", ["Thick Armor Kit (Provided)"] = "накладки з товстої шкіри (видано)", ["Wildvine"] = "диколоззя", ["Wildvine (Provided)"] = "диколоззя (видано)" } },
    [2857] = { [1] = "Шолом з дикої шкіри", [2] = "Шолом з дикої шкіри надає відмінний захист життєво важливих ділянок голови без втрати комфорту. Як і для всіх обладунків з дикої шкіри, вшите в шолом диколоззя надає йому випадкові, але дуже потужні магічні властивості. Тим, хто ходить у шкіряних обладунках, така річ обов'язково знадобиться!\n\nДля цієї викрійки мені знадобляться два мундири нічного краєвиду, дві пов'язки нічного краєвиду та диколоззя. Виконай цей урок, і викрійка буде твоєю!", [3] = "Принесіть 2 мундири нічного краєвиду, 2 пов'язки нічного краєвиду та диколоззя Джанґдору Стрімкому Вершнику в табір Мохаче.", [4] = "Мені потрібно, щоб ти {стать:зробив:зробила} мундири та пов'язки, а також {стать:приніс:принесла} шматок диколоззя, перш ніж я поділюся з тобою знанням про шоломи з дикої шкіри.\n\nБудь-якому мандрівнику необхідний захист для голови, чи то проста бандана, чи то шолом, що повністю закриває голову. Основи створення головних уборів залишаються незмінними, незалежно від зовнішнього вигляду виробу.", [5] = "Спорядження нічного краєвиду, яке ти {стать:зробив:зробила}, ідеально відповідає моїм вимогам, {ім'я}. Я очікував не меншого від {стать:шкірника:шкірниці} твого рівня.\n\nТи {стать:гідний:гідна} виготовляти шоломи з дикої шкіри. Я передаю цю викрійку тобі та сподіваюся, що ти отримаєш від неї гідну вигоду.", ["en"] = "Wild Leather Helmet", ["tasks"] = { ["Nightscape Headband"] = "пов'язка нічного краєвиду", ["Nightscape Headband (Provided)"] = "пов'язка нічного краєвиду (видано)", ["Nightscape Tunic"] = "мундир нічного краєвиду", ["Nightscape Tunic (Provided)"] = "мундир нічного краєвиду (видано)", ["Wildvine"] = "диколоззя", ["Wildvine (Provided)"] = "диколоззя (видано)" } },
    [2858] = { [1] = "Чоботи з дикої шкіри", [2] = "Твої знання дикої шкіри невпинно зростають, {ім'я}, проте є ще багато чому навчитись.\n\nЧоботи з дикої шкіри — основа будь-якого комплекту обладунків. Ці чоботи створені, щоб комфортно огорнути ноги, водночас захищаючи їх від небезпек пригод. А їхні м'які підошви будуть благословенням для тих, хто обирає непомітність.\n\nДля цієї викрійки мені потрібні дві пари штанів та дві пари чобіт нічного краєвиду. Також мені знадобляться два диколоззя... не одне. Коли матимеш все це, ми продовжимо.", [3] = "Принесіть 2 пари штанів нічного краєвиду, 2 пари чобіт нічного краєвиду та 2 диколоззя Джанґдору Стрімкому Вершнику в табір Мохаче.", [4] = "Ти маєш принести штани, чоботи та диколоззя, перш ніж отримаєш викройку, {ім'я}. Ти маєш все що мені потрібно?\n\nВже з першої пари чобіт, яку ми навчаємось робити, ми починаємо розуміти, що якісні чоботи мають бути збалансовані між комфортом і практичністю. Дотримуючись цих вимог, ми здатні створювати вироби, які дозволяють носію не відчувати втому, яка зламала б тих, хто носить вироби нижчої якості.", [5] = "Ти знову {стать:виготовив:виготовила} вироби з майстерністю досвідченого професіонала. Ти {стать:заслужив:заслужила} цю викрійку і мої вітання.", ["en"] = "Wild Leather Boots", ["tasks"] = { ["Nightscape Boots"] = "чоботи нічного краєвиду", ["Nightscape Boots (Provided)"] = "чоботи нічного краєвиду (видано)", ["Nightscape Pants"] = "штани нічного краєвиду", ["Nightscape Pants (Provided)"] = "штани нічного краєвиду (видано)", ["Wildvine"] = "диколоззя", ["Wildvine (Provided)"] = "диколоззя (видано)" } },
    [2859] = { [1] = "Штани з дикої шкіри", [2] = "Ти {стать:готовий:готова} освоїти складніші уроки, {ім'я}. Штани з дикої шкіри є однією з найміцніших і найпотужніших частин шкіряних обладунків. Вони відмінно захищають живіт, ноги та інші важливі частини тіла. А разом з покращенням, яке забезпечує диколоззя, кожен мандрівник буде дякувати тобі за такі штани.\n\nЩоб отримати цю викрійку, ти маєш принести два шоломи з черепашачої луски, два браслети з черепашачої луски та два диколоззя.", [3] = "Принесіть 2 шоломи з черепашачої луски, 2 браслети з черепашачої луски та 2 диколоззя Джанґдору Стрімкому Вершнику в табір Мохаче.", [4] = "Ти вже {стать:виготовив:виготовила} браслети та шоломи з черепашачої луски? І не забудь про два диколоззя.\n\nТи починаєш усвідомлювати могутність, що ховається в обладунках з дикої шкіри. Уміння виготовляти такі потужні обладунки, неоціненна для шкірника. Єдине обмеження — це наявність потрібних ресурсів для виготовлення виробів, але не їхня якість!", [5] = "Ти знову бездоганно {стать:виконав:виконала} моє завдання. Можливо, одного дня я звернусь до ТЕБЕ у пошуках знань, еге ж, {ім'я}?\n\nОсь викрійка для штанів, разом з моєю дякою. Запам'ятай ці знання, і нехай твої вироби будуть гідні твоїх здібностей!", ["en"] = "Wild Leather Leggings", ["tasks"] = { ["Turtle Scale Bracers"] = "браслети з черепашачої луски", ["Turtle Scale Bracers (Provided)"] = "браслети з черепашачої луски (видано)", ["Turtle Scale Helm"] = "шолом з черепашачої луски", ["Turtle Scale Helm (Provided)"] = "шолом з черепашачої луски (видано)", ["Wildvine"] = "диколоззя", ["Wildvine (Provided)"] = "диколоззя (видано)" } },
    [2860] = { [1] = "Майстер дикої шкіри", [2] = "{ім'я}, ти {стать:опанував:опанувала} всі мої уроки. Залишилася лиш одна викрійка предмета з дикої шкіри, який ти не вмієш виготовляти. Я не примушу тебе працювати, щоб отримати її. Ти {стать:заслужив:заслужила} її, і навіть більше... але я не можу дати її тобі. Моя наставниця, та, яка ввела мене в ремесло, повинна нагородити тебе.\n\nВіднеси цей лист до Уни; вона викладає шкірництво у Громовиму Бескиді. Покажи їй лист, і дозволь їй визнати тебе {стать:рівним:рівною}, так само як і я.", [3] = "Передайте лист Джанґдора Уні, ремісниці шкірництва з Громового Бескиду.", [4] = "Вітаю, {раса:к}... Я бачу, що ти {стать:такий же шкірник:така ж шкірниця}, як і я. Ти {стать:прийшов:прийшла} до мене, щоб вчитися, чи, можливо, маєш до мене іншу справу?", [5] = "А, так, тебе прислав Джангдор. Мені приємно бачити, що один з моїх найкращих учнів тепер має {стать:власного учня:власну ученицю}.\n\nЙого відданість і талант у роботі зі шкірою вражають. Те, що він так хвалив тебе у цьому листі, свідчить про повагу, яку я визнаю.\n\nЯ знаю, що він навчив тебе мистецтва дикої шкіри. Дозволь мені завершити твою підготовку цією викрійкою. Використовуй її з користю. Мало хто знає секрети створення плащів з дикої шкіри.", ["en"] = "Master of the Wild Leather", ["tasks"] = { ["Jangdor's Letter"] = "лист Джанґдора", ["Jangdor's Letter (Provided)"] = "лист Джанґдора (видано)" } },
    [2861] = { [1] = "Завдання Табети", [2] = "Ходять чутки, що моя колега-магиня, Табета, яка живе в глибинах Бруднолипкої трясовини, точить зуб на одну пустельну трольку з Зул'Фарраку. Поговори з Табетою, вона розповість тобі більше.\n\n{ім'я}, не забудь взяти з собою друзів. Якщо Табета відправить тебе в Зул'Фаррак, то краще тобі не з'являтись там наодинці.\n\nТи зможеш знайти оселю Табети на захід від Терамора та на північ від руїн Каменедовбні.", [3] = "Поговоріть з Табетою в Бруднолипкій трясовині.", [5] = "Так, все вірно. Я справді точу зуб на цю трольку. Величезний зуб!\n\nХочеш допомогти мені?", ["en"] = "Tabetha's Task" },
    [2864] = { [1] = "Тран'рек", [2] = "У мого брата Тран'река зараз великі проблеми. Він пообіцяв мені партію панцирів скарабеїв кілька тижнів тому, але так і не приніс. Він мій кузен, тож я не хотів би відправляти когось у Пристроблях вибивати з нього гроші.\n\nЧи можеш ти поговорити з Тран'реком замість мене? Повідом йому, що якщо він не доставить мені партію панцирів, йому доведеться відповідати за свої дії.\n\nПристроблях знаходиться на півночі пустелі Танаріс, в Калімдорі.", [3] = "Поговоріть з Тран'реком у Пристроблясі.", [5] = "Привіт!\n\nТо ти {стать:говорив:говорила} з моїм кузеном Кронжеком? Як він? Сподіваюся, що його справи в Грабіжній Бухті йдуть добре...\n\nПанцири скарабеїв, кажеш? Ну... дозволь розповісти тобі історію...", ["en"] = "Tran'rek" },
    [2865] = { [1] = "Панцири скарабеїв", [2] = "Скарабеї Танаріса мають дуже тверді панцири! Достатньо тверді, щоб використовувати їх як матеріал для багатьох речей. Справді багатьох речей!\n\nНасправді ці панцири настільки корисні... що на скарабеїв вже на межі зникнення!\n\nЯ знаю, де є ще багато скарабеїв і якщо ти пообіцяєш принести мені їхні панцири, я скажу тобі, де вони знаходяться. Обіцяєш?\n\nГаразд, у скарабеїв є колонія в Зул'Фарраці. Гадаю, тролі не полюють на них заради панцирів.\n\nАле ти можеш! Йди в Зул'Фаррак і принеси мені цілі панцири!", [3] = "Принесіть 5 цілих панцирів скарабеїв Тран'реку в Пристроблях.", [4] = "Ти {стать:приніс:принесла} панцири? Мій кузен у Грабіжній Бухті дуже хоче отримати їх, і він не любить довго чекати!", [5] = "Чудово! Ти {стать:дістав:дістала} їх!\n\nДякую тобі, {ім'я}. Ти мене {стать:врятував:врятувала}!", ["en"] = "Scarab Shells", ["tasks"] = { ["Uncracked Scarab Shell"] = "цілий панцир скарабея", ["Uncracked Scarab Shell (Provided)"] = "цілий панцир скарабея (видано)" } },
    [2868] = { [1] = "<TXT> Зів'яле серце", [2] = "Перетвори цього лиходія на якусь гробницю тролів у Затонулому Храмі та отримай щось круте!", ["en"] = "<TXT> The Shriveled Heart", ["tasks"] = { ["Item #9243"] = "Товар №9243", ["Item #9243 (Provided)"] = "Товар №9243 (видано)" } },
    [2872] = { [1] = "Борг Стоулі", [2] = "Мій старий приятель Стоулі винен мені особливу пляшку рому. Він працює барменом в порту Паровиманювання в Танарісі, і клявся, що тамтешній ром міцніший за все, що можна знайти в Грабіжній Бухті. Він настільки впевнений, що навіть заявив, що якщо я спробую цей ром і не погоджуся з ним, то він подвоїть борг переді мною!\n\nНу, я думаю, що він пошкодував про свої слова, і тому й не шле мені ром. Але я про таке не забуваю, тож чому б тобі не поговорити з ним замість мене...", [3] = "Поговоріть зі Стоулі в порту Паровиманювання.", [5] = "А, то ти {стать:говорив:говорила} з МакКінлі, так?\n\nВсе зовсім не так! Я зовсім не боюся пригостити його трюмним ромом паровиманювання.\n\nУ мене просто немає рому!", ["en"] = "Stoley's Debt" },
    [2873] = { [1] = "Вантаж Стоулі", [2] = "Я заборгував \"Морському вовку\" МакКінлі з Грабіжної Бухти трохи рому, щоб владнати суперечку, але проблема в тому, що ром у мене закінчився! Капітан Куерго вкрав мою останню партію, і ховає її у тому обнесеному стінами піратському поселенні на півдні.\n\nЯкщо ти зможеш знайти мою партію рому і повернути її, то я зможу довести МакКінлі, що калімдорська випивка в сто разів краща за пійло з Грабіжної Бухти!", [3] = "Принесіть вантаж Стоулі в порт Паровиманювання.", [4] = "Ти {стать:знайшов:знайшла} мій вантаж рому, {ім'я}?", [5] = "Чудово, дякую за вантаж! Тепер я нарешті виграю парі у МакКінлі.", ["en"] = "Stoley's Shipment", ["tasks"] = { ["Stoley's Shipment"] = "вантаж Стоулі", ["Stoley's Shipment (Provided)"] = "вантаж Стоулі (видано)" } },
    [2874] = { [1] = "Доставлення до МакКінлі", [2] = "Дякую ще раз за твою допомогу, {ім'я}. Ось пляшка трюмного рому паровиманювання. Віднеси її до МакКінлі, час розвіяти його впевненість щодо рому Грабіжної Бухти.", [3] = "Принесіть пляшку Стоулі \"Морському вовку\" МакКінлі в Грабіжну Бухту.", [4] = "Стоулі розщедрився на випивку?", [5] = "Хм, дай-но спробую..\n\nЯ не можу повірити! Це пійло... жахливе! Чудово!\n\nНу що ж, я думаю, Стоулі може залишити гроші собі. Він дотримав свого слова щодо трюмного рому паровиманювання. Ця річ густа, як гравій, і пекуча, як лава!", ["en"] = "Deliver to MacKinley", ["tasks"] = { ["Stoley's Bottle"] = "пляшка Стоулі", ["Stoley's Bottle (Provided)"] = "пляшка Стоулі (видано)" } },
    [2875] = { [1] = "РОЗШУКУЄТЬСЯ: Андре Вогнебородий", [2] = "За злочини проти картелю Паровиманювання та Пристробляху розшукується безжалісний пірат Андре Вогнебородий.\n\nЗа рішенням керівної ради, будь-хто, хто читає це, має дозвіл вживати будь-яких заходів при затриманні Андре та його пособників.\n\nЗгідно з указом, якщо Андре помре або з інших причин не зможе постати перед судом, його може представляти його голова, і передача такої голови начальнику служби безпеки Трюмосвисту потягне за собою укладання досить вигідної угоди.", [3] = "Принесіть голову Андре начальнику служби безпеки Трюмосвисту в порт Паровиманювання.", [4] = "Виглядаєш трохи {стать:ошелешеним:ошелешеною}. Ти що, {стать:читав:читала} наші юридичні документи?", [5] = "А, голова Андре. Гадаю, він таки постане перед судом!\n\nДуже вдячний, {ім'я}. А тепер розпишись тут і я займуся оплатою твоїх послуг.\n\nНе турбуйся через той напис дрібним шрифтом. Там нічого важливого, і... Не думаю, що знайдеться лупа настільки мала, щоб прочитати його.", ["en"] = "WANTED: Andre Firebeard", ["tasks"] = { ["Firebeard's Head"] = "голова Вогнебородого", ["Firebeard's Head (Provided)"] = "голова Вогнебородого (видано)" } },
    [2876] = { [1] = "Розклад кораблів", [2] = "Цей сувій містить розклад руху вантажних перевезень між портом Паровиманювання та Грабіжною Бухтою. У ньому вказані як минулі, так і майбутні перевезення, а також назви кораблів, які їх везуть. Навпроти деяких стоїть «Х»,, навпроти інших замітки «ВЕЛИКИЙ СКАРБ» та «ВАЖКА БИТВА».\n\nХтось порту Паровиманювання, мабуть, має побачити цей документ.", [3] = "Повідомте про розклад кораблів керівництву порту Паровиманювання.", [4] = "Виглядаєш {стать:захеканим:захеканою}. Хочеш мені щось сказати?", [5] = "Ох, це, здається, список відправлень і прибуттів кораблів, з точними датами та часом! Якби капітан піратського корабля отримав це у свої руки, він міг би влаштувати собі справжнє свято!\n\nТо ти {стать:знайшов:знайшла} їх у пірата? Це тривожні новини...\n\nДякую, {ім'я}. Я радий, що ти {стать:знайшов:знайшла} ці папери, і що {стать:відправив:відправила} того пірата на корм рибам!", ["en"] = "Ship Schedules", ["tasks"] = { ["Ship Schedule"] = "розклад кораблів", ["Ship Schedule (Provided)"] = "розклад кораблів (видано)" } },
    [2878] = { [1] = "Осквернений піснеквіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на піснеквіт. Плоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите кенарійський бальзам зцілення рослин на піснеквіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Songflower", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [2879] = { [1] = "Посох рівнодення", [2] = "Це може бути посохом рівнодення! Цей посох — ключ до відкриття моноліту рівнодення у руїнах Вороновію, на заході материка за Гілкою Сну.\n\nЗнайди чотири полум'я, які все ще горять в тих руїнах: Самга, Імбел, Білтан та Лагасса. Збери їхні сутності, а потім, стоячи біля моноліту рівнодення, використай їх, щоб зарядити посох. Якщо це дійсно посох рівнодення, ти зможеш відкрити моноліт і забрати священний артефакт.", [3] = "Зарядіть посох Трояса та знайдіть моноліт рівнодення.", [4] = "Моноліт рівнодення безмовно височіє серед руїн. Цікаво, що він приховує?", [5] = "Втримати заряджений посох майже неможливо. Його сила пронизує ваше тіло.\n\nВи простягаєте руку до холодної поверхні моноліту рівнодення...\n\nНевеличкі двері відчиняються, дозволяючи вам простягнути руку і забрати артефакт.\n\nПромені світла осяюють все навколо моноліту рівнодення.", ["en"] = "The Stave of Equinex", ["tasks"] = { ["Stave of Equinex"] = "посох рівнодення", ["Stave of Equinex (Provided)"] = "посох рівнодення (видано)" } },
    [2881] = { [1] = "Нагорода за намисто тролів", [4] = "Ти це вже {стать:робив:робила}, але якщо захочеш принести мені ще трохи племінних намист тролів, то я з радістю прийму їх. Таким чином ти зможеш заслужити хороше ставлення Дикого Молота — якщо ти {стать:готовий:готова} битися за нас, то й ми будемо готові битися за тебе!\n\nМені потрібно п'ять племінних намист тролів, {ім'я}.", [5] = "Ще один набір намист означає, що у Внутрішніх землях стало менше тролів! Ти знову {стать:впорався:впоралася}, {ім'я}. Продовжуй в тому ж дусі!", ["en"] = "Troll Necklace Bounty", ["tasks"] = { ["Troll Tribal Necklace"] = "племінне намисто тролів", ["Troll Tribal Necklace (Provided)"] = "племінне намисто тролів (видано)" } },
    [2882] = { [1] = "Золото Куерґо", [2] = "На цій карті зображено ділянку узбережжя на півдні. Під картою витончено написані слова...\n\n\nНа півдні Танарісу, так просто неба\nЗнайти кістки, прапор й щоглу тобі треба.\nКопай там, якщо ти сміливого роду —\nКуерґово злато буде в нагороду.\nІ ключ тобі навіть не треба шукати —\nЗа нього там кров'ю заплатиш піратам.", [3] = "Знайдіть золото Куерґо!", [4] = "Ця скриня замкнена!", [5] = "Перед вами захований скарб капітана Куерґо!", ["en"] = "Cuergo's Gold", ["tasks"] = { ["Cuergo's Key"] = "ключ Куерґо", ["Cuergo's Key (Provided)"] = "ключ Куерґо (видано)" } },
    [290] = { [1] = "Зняття прокляття", [2] = "Щоб звільнити моїх побратимів від прокляття треба очистити ту... штуковину, що схована на моєму кораблі. Я не знаю, що то за штуковина, тільки що лежить вона в сейфі корабля, а ключ від нього має бути у капітана Галиндора.\n\nМій старий капітан досі приходить до мене уві сні. Він зараз на моєму проклятому кораблі, \"Відважному\". Забери в нього ключ та відкрий сейф.\n\nЯк добудеш ту прокляту штуку, віднеси її місцевому жерцю Ґлоріну Сталеброву.", [3] = "Дістаньте ключ від сейфа на \"Відважному\" у капітана Галиндора.\n\nВідчиніть ключем сейф на \"Відважному\".", [4] = "Цей сейф надійно замкнено.", [5] = "Хоч ключ і проржавів, замок легко відкрився.", ["en"] = "Lifting the Curse", ["tasks"] = { ["Intrepid Strongbox Key"] = "ключ від сейфа на \"Відважному\"", ["Intrepid Strongbox Key (Provided)"] = "ключ від сейфа на \"Відважному\" (видано)" } },
    [2904] = { [1] = "Халепа", [2] = "<Кернобі стогне.> Що... Що сталося?\n\nОстаннє, що я пам'ятаю — як мене схопила група дворфів Темного Заліза, побили до півсмерті, а потім кинули сюди до цих брудних трогів.\n\nЗабери мене звідси, {ім'я}!\n\nПлан такий: відведи мене до виходу, і якщо ми виберемося живими, ти підеш до Грабіжної Бухти та скажеш Скуті, що я ходив до Брашпиля, щоб попередити Штукарліца про участь Темного Заліза у створенні тієї супермашини.\n\nХодімо!", [3] = "Супроводіть Кернобі до Механічного проходу, після чого поговоріть зі Скуті в Грабіжній Бухті.", [4] = "А? Кернобі живий??", [5] = "Гадаю, тебе варто винагородити за повернення Кернобі цілим і неушкодженим, {ім'я}. Якщо ти збираєшся повернутись до Гномреґану, це може допомогти тобі перемогти цього підступного нікчему, мекженера Термоштепселя.", ["en"] = "A Fine Mess", ["tasks"] = { ["Kernobee Rescue"] = "Рятувальний майданчик Кернобі" } },
    [292] = { [1] = "Око Палета", [2] = "Відкривши скриню, ви бачите почорнілу сферу, яка пульсує моторошним світлом. Це скарб, про який говорив Фіцсіммонс - прокляте Око Палета.\n\nВіднесіть прокляте Око Палета дворфійському жерцю Ґлоріну Сталеброву в гавань Менетілів. Попросіть його зняти прокляття.", [3] = "Віднесіть прокляте Око Палета до Ґлоріна Сталеброва.", [4] = "Цей пияка Фіцсіммонс послав тебе до мене? Скажи йому, що елю більше нема, хай йде жебракує деінде.", [5] = "Око Палета? Неймовірно! Хмм... З ним щось не так. Ти {стать:знайшов:знайшла} його серед уламків корабля? Що ж, це багато чого пояснює. Але як воно потрапило до третього флоту...\n\nНе дивно чого Фіцсіммонс такий переляканий. Прокляте Око Палета мало кого залишить байдужим.", ["en"] = "The Eye of Paleth", ["tasks"] = { ["Cursed Eye of Paleth"] = "прокляте око Палета", ["Cursed Eye of Paleth (Provided)"] = "прокляте око Палета (видано)" } },
    [2923] = { [1] = "Мехмайстер Надспалах", [2] = "Мехмайстер Надспалах вкрай засмучений долею свого механічного творіння — Техбота. Колись Техбот був добрим і корисним помічником гномів, але Надспалах каже, що він несправний.\n\nДуже шкода. Однак, можливо, його ще можна полагодити!\n\nПоговори з мехмайстром Надспалахом у Штукарівці, що в Залізогарті. Він буде радий будь-якій допомозі.", [3] = "Поговоріть з мехмайстром Надспалахом в Залізогарті.", [5] = "Так, це правда. Техбот вийшов з-під контролю! Ти допоможеш мені?", ["en"] = "Tinkmaster Overspark" },
    [2924] = { [1] = "Базові штучні", [2] = "Базовий штучень — майже універсальний механічний компонент, що широко використовується штукарями та ковалями Гномреґану. Але під час нашої втечі з міста ніхто не здогадався прихопити з собою кілька цих пристроїв! А мені потрібен значний їх запас для проєкту, за який я незабаром візьмуся.\n\nБудь ласка, вирушай до Гномреґану і принеси мені кілька базових штучнів. Ти знайдеш їх у глибинах нашого міста, в контейнерах, які називаються штучними екстраполяторами.\n\nДякую, {ім'я}, і, прошу тебе, поспіши!", [3] = "Принесіть 12 базових штучнів Клокморту Гайковерту в Залізогарт.", [4] = "Ти {стать:приніс:принесла} базові штучні?", [5] = "Вони в тебе! Нарешті я можу почати нові експерименти!\n\nЯ навіть не знаю, як тобі віддячити, {ім'я}! Твоя хоробрість неймовірно допомогла дослідженням гномів!", ["en"] = "Essential Artificials", ["tasks"] = { ["Essential Artificial"] = "базовий штучень", ["Essential Artificial (Provided)"] = "базовий штучень (видано)" } },
    [2925] = { [1] = "Штучні Клокморта", [2] = "Мій друг, гном Клокморт Гайковерт з Залізогарту, надіслав мені листа. Він повідомив, що йому потрібна допомога у небезпечній, але дуже важливій місії в Гномреґані — колись великому місті гномів, яке тепер заражене і наповнене божевільними гномами та їхніми пристроями.\n\nЯ маю залишитися тут, але моя душа болить за друга. Якщо ти зможеш допомогти йому замість мене, я буду тобі дуже вдячний.\n\nТи знайдеш Клокморта у Штукарівці, що в Залізогарті.", [3] = "Поговоріть з Клокмортом Гайковертом в Залізогарті.", [5] = "Саме так! Мені потрібна допомога з завданням у Гномреґані. І схоже, що {стать:такий:така} {клас}, як ти, зможе з ним впоратись!", ["en"] = "Klockmort's Essentials" },
    [2926] = { [1] = "Гномальгін", [2] = "З того дня все, про що думає або говорить Гноарн — це очищення Гномреґану від нашестя троггів і пошук ліків проти хвороби, яка його мучить, {ім'я}.\n\nНа щастя, ми з Раззлом наблизилися до відкриття ліків — або до них, або до рецепта справді потужного рому. Але ми не дізнаємося, поки не спробуємо! Звісно, щоб перевірити нашу теорію, нам потрібно кілька речей, а саме радіоактивний осад з опромінених трогів у Гномреґані. Наповни цей фіал зеленою сяючою субстанцією і принеси його мені!", [3] = "Зберіть радіоактивний осад з опромінених загарбників та опромінених грабіжників за допомогою порожнього свинцевого фіала для зразків. Після того, як наповните фіал — поверніть його Оззі Вольтону в Харанос.", [4] = "Ми намагаємося вилікувати цілий народ гномів! Нам потрібно більше цієї зеленої сяючої субстанції!", [5] = "Чудова робота! Настав час випробувати нову формулу. Якщо вона спрацює, то я не тільки вилікую цього лепрогнома, а й поверну своє волосся! Відійди!", ["en"] = "Gnogaine", ["tasks"] = { ["Full Leaden Collection Phial"] = "наповнений свинцевий фіал для зразків", ["Full Leaden Collection Phial (Provided)"] = "наповнений свинцевий фіал для зразків (видано)" } },
    [2927] = { [1] = "Наступного дня", [2] = "Ти ж не думаєш, що я завжди був лисим? Аж ніяк! Це витік радіації в Гномреґані спричинив трагічну втрату волосся. До того дня я був єдиним гномом з кучерями в усьому Азероті.\n\n<Ґноарн трясе кулаком у повітрі.>\n\nБудь прокляті ці кляті брудні троги, будь всі вони прокляті!!\n\nМожливо, ще не надто пізно, {ім'я}. Ми ще можемо врятувати його — я маю на увазі місто! Поговоріть з Оззі Вольтоном у Хараносі. Він працює зі своїм партнером Раззлом над вирішенням проблеми.", [3] = "Поговоріть з Оззі Вольтоном в Хараносі.", [5] = "Я думав, що втрата цієї чудової шевелюри вб'є його, але він вижив!\n\nЯ стояв поруч з ним, коли в нього влучив заряд радіації. Його чудові каштанові локони посипалися на підлогу один за одним! Жах того, що сталося, тільки посилився, коли Ґноарн остаточно збожеволів! Так-так, кажу тобі, у нього поїхав дах! Ґноарн, не вірячи своїм очам, торкнувся своєї лисої голови, і в його погляді спалахнула помста, {ім'я}! Після цього він спрямував весь свій гнів на трогів!", ["en"] = "The Day After" },
    [293] = { [1] = "Очищення Ока", [2] = "Я не можу зняти прокляття з Ока Палета. Очі були створені людьми, тож тобі доведеться відправитись до Штормовію. Він голова собору Світла і зможе тобі допомогти.\n\nСподіваюсь, у тебе все вийде.", [3] = "Віднесіть прокляте Око Палета архієпископу Бенедикту. Його можна знайти в соборі Світла в Штормовії.", [4] = "Що це в тебе? Якась брудна... сфера?", [5] = "Це Око Палета. Але воно бачило багато печалі... певно, воно стало свідком жахливої трагедії.\n\nДай мені очистити його. Очі були створені, щоб яскраво сяяти і їх сили можуть бути досить небезпечними, коли заплямовані прокляттям.", ["en"] = "Cleansing the Eye", ["tasks"] = { ["Cursed Eye of Paleth"] = "прокляте око Палета", ["Cursed Eye of Paleth (Provided)"] = "прокляте око Палета (видано)" } },
    [2931] = { [1] = "Завдання Трубоплава", [2] = "Майстру-механіку Трубоплаву у Залізогарті потрібні шукачі пригод! Він збирає загони для проникнення до Гномреґану з надважливою місією з пошуку даних.\n\nХоч Трубоплав і не є членом Просвітленої Асамблеї Арканології, Алхімії та Інженерних Наук, як я, але він все одно розумний гном, і якщо він вважає, що це важливо, то, за моїми підрахунками, ймовірність того, що це справді важливо, становить вісімдесят чотири відсотки!\n\nЦе непогані шанси!", [3] = "Поговоріть з майстром-механіком Трубоплавом у Залізогарті.", [5] = "Я готую операції з видобутку даних у Гномреґані. Якщо ти тут для цього, то слухай уважно!", ["en"] = "Castpipe's Task" },
    [2940] = { [1] = "Історія Фераласа", [2] = "Ця книга виглядає так, ніби її давно ніхто не відкривав. Її обкладинка досить потерта, а сторінки пожовклі, але, розглянувши її, ви помічаєте, що це може бути саме те, що шукає Трояс.\n\nВи берете її до рук, але розумієте, що варто було б запитати, перш ніж брати.", [3] = "Запитайте у Дарін Легковій, чи можете ви позичити її книгу.", [5] = "Отже, ти хочеш позичити примірник \"Історії Фераласа\"?\n\nДай подумати...\n\nЯ дозволю тобі взяти цю книгу, {ім'я}, але тільки якщо ти зробиш дещо для мене.", ["en"] = "Feralas: A History" },
    [2941] = { [1] = "В обмін на книгу", [2] = "Я вивчала багато різних тем, і зараз я дуже зацікавилася тріскощелепами, що заселяють побережжя у Внутрішніх землях. Зокрема, мені хотілося б побачити одну велику тріскощелепу, на ім'я Ґаммеріта. Я б хотіла піти туди сама, але не можу відриватися від своїх досліджень. Я думаю, що зображення цієї тварини було б достатньо.\n\nВізьми цей лист та віднеси його Бульці Хисткоплиг в Танаріс. Вона створила для мене пристрій, який може зробити картинку. Здається, вона називає їх \"знімками\"...", [3] = "Віднесіть лист Бульці Хисткоплиг в Танаріс.", [4] = "Лист? Для мене?", [5] = "Ти ще {стать:один:одна} зі стажистів Дарін? Вона досить обізнаний історик, {ім'я}. Ти маєш бути {стать:вдячним:вдячною}, що навчаєшся під її керівництвом.\n\nДозволь мені показати тобі суперзахоплювач. Тобі сподобається!", ["en"] = "The Borrower", ["tasks"] = { ["A Short Note"] = "коротка записка", ["A Short Note (Provided)"] = "коротка записка (видано)" } },
    [2942] = { [1] = "Завтрашній камінь", [2] = "Щойно артефакт витягнуто з моноліту, ви відчуваєте, як енергія посоха рівнодення починає згасати.", [3] = "Поверніть іскристий камінь і посох рівнодення Троясу Місяцебризу в фортецю Перомісяць.", [4] = "Я радий, що ти {стать:повернувся:повернулася}, {ім'я}. Я з нетерпінням чекаю на твої знахідки.", [5] = "Я багато читав з того часу, як ти {стать:пішов:пішла}, {ім'я}. Цей камінь, який ти {стать:знайшов:знайшла}, називається завтрашнім каменем. Хоча я ще достеменно не знаю, для чого він потрібен, ти можеш бути {стать:впевненим:впевненою}, що це щось дуже важливе, якщо воно було так заховане всередині моноліту рівнодення.\n\nЯ продовжуватиму свої дослідження. Сподіваюся, що в майбутньому я зможу на тебе розраховувати, {ім'я}. Дякую тобі за допомогу.", ["en"] = "The Morrow Stone", ["tasks"] = { ["A Sparkling Stone"] = "іскристий камінь", ["A Sparkling Stone (Provided)"] = "іскристий камінь (видано)", ["Stave of Equinex"] = "посох рівнодення", ["Stave of Equinex (Provided)"] = "посох рівнодення (видано)" } },
    [2943] = { [1] = "Повернення до Трояса", [2] = "Ось книга, {ім'я}. Будь ласка, поводься з нею дбайливо.\n\nА тепер йди. Я впевнена, що Трояс з нетерпінням чекає на твоє повернення.", [3] = "Принесіть книгу Троясу Місяцебризу у фортецю Перомісяць.", [4] = "Привіт, {ім'я}. Ти {стать:був:була} в Дарнасі?", [5] = "Ти {стать:приніс:принесла} з собою книгу. Чудово!", ["en"] = "Return to Troyas", ["tasks"] = { ["Feralas: A History"] = "Історія Фераласа", ["Feralas: A History (Provided)"] = "Історія Фераласа (видано)" } },
    [2944] = { [1] = "Суперзахоплювач ФХ", [2] = "Ти будеш {стать:першим:першою} хто побачить мій новий винахід, {ім'я}. Тобі просто потрібно спрямувати пристрій на те, що ти хочеш зняти, та натиснути кнопку.\n\nЯкщо я не помиляюся, ти {стать:згадував:згадувала} якусь істоту з Внутрішніх земель? Ґаммеріта? Ну, успіхів тобі у її пошуках. Я впевнена, що Дарін буде дуже задоволена знімком, який ти їй принесеш.\n\nВ будь-якому випадку, тримай суперзахоплювач. Насолоджуйся!", [3] = "Використовуйте суперзахоплювач ФХ, щоб зробити знімок Ґаммеріти, а потім поверніться до Дарін Легковій у селище Рут'Теран.", [4] = "Ти нарешті {стать:повернувся:повернулася}, {ім'я}. І ти {стать:приніс:принесла} штуковину, яку для мене збудувала Булька — чудово.", [5] = "Ну що ж! Винахід Бульки виправдав усі сподівання.\n\nНе надто радій, але знай, що я задоволена твоєю роботою, {ім'я}.\n\nТак, де ж я залишила ту книгу...", ["en"] = "The Super Snapper FX", ["tasks"] = { ["Snapshot of Gammerita"] = "знімок Ґаммеріти", ["Snapshot of Gammerita (Provided)"] = "знімок Ґаммеріти (видано)", ["Super Snapper FX"] = "Суперзахоплювач ФХ", ["Super Snapper FX (Provided)"] = "Суперзахоплювач ФХ (видано)" } },
    [2945] = { [1] = "Вкритий брудом перстень", [2] = "З тіла одного з дворфів Темного Заліза ви зняли предмет, що нагадує перстень. Складно сказати, що це за перстень, оскільки він вкритий товстим шаром бруду. Носити його навряд чи можливо. Однак здається, що з-під шару бруду видніється дорогоцінний метал, а може ще й самоцвіт.\n\nЯкщо ви збираєтеся використовувати цей перстень, вам доведеться знайти спосіб очистити його від бруду.", [3] = "Знайдіть спосіб видалити бруд із вкритого брудом персня.", [4] = "Перед вами пристрій гномів, до якого прикріплена табличка з написом \"Блискочист 5200\". Судячи з інструкції під табличкою, ця машина очищає предмети від будь-яких забруднень. На ній є отвір, в який потрібно опустити три срібні монети, щоб почати очищення предмета, поміщеного всередину.\n\nСхоже, варто випробувати цей пристрій на вкритому брудом персні.", [5] = "Ви поміщаєте перстень в Блискочист 5200 та опускаєте в отвір три срібні монети.\n\nЗ машини лунає жахливий скрегіт, а її корпус трясеться. Важко уявити, що відбувається з перснем всередині машини...\n\nНарешті пристрій завмирає і віконце для предметів відкривається з дзенькітом. В ньому лежить маленька акуратно загорнута коробка із червоним бантиком. Схоже, що Блискочист 5200 також упаковує подарунки!", ["en"] = "Grime-Encrusted Ring", ["tasks"] = { ["Grime-Encrusted Ring"] = "вкритий брудом перстень", ["Grime-Encrusted Ring (Provided)"] = "вкритий брудом перстень (видано)" } },
    [2946] = { [1] = "Що буде далі", [2] = "Ми хочемо, щоб ти {стать:відніс:віднесла} ці диски до запечатаних воріт Ульдуму. Але ми... не впевнені, до чого це призведе.\n\nЗвучить ризиковано, так, ми це розуміємо. Однак, може, нічого і не станеться. Можливо тобі доведеться до чогось їх притулити. А може, в присутності дисків відкриються ворота. Не бійся експериментувати та будь {стать:готовий:готова} до будь-яких наслідків.\n\nЯк щось дізнаєшся — повертайся до Залізогарту. Впевнений, нам буде про що подумати!", [3] = "Принесіть мініатюрні платинові диски до воріт Ульдуму в Танаріс та перевірте, чи є між ними зв'язок.", [4] = "З розпеченого піску видніється знайомий постамент. Можливо, він тут не просто так...", [5] = "Щойно ви торкаєтесь постаменту, мініатюрні диски з Ульдаману починають гудіти та світитись. В руках відчувається знайоме поколювання і перед воротами Ульдуму з'являється кам'яний наглядач.\n\n\"Вітаю. Я — вартовий цього проходу. Серед використаних вами дисків відсутні пластини Ульдуму. Будь ласка, додайте ці пластини до вашого набору та повторіть спробу доступу. Дякую.\"", ["en"] = "Seeing What Happens", ["tasks"] = { ["Miniature Platinum Discs"] = "мініатюрні платинові диски", ["Miniature Platinum Discs (Provided)"] = "мініатюрні платинові диски (видано)" } },
    [2951] = { [1] = "Блискочист 5200!", [2] = "Цей пристрій виділяється серед гномів, які намагаються протистояти божевіллю, що коїться за межами кімнати. На невеликій табличці на пристрої написано: \"Блискочист 5200\", а нижче текст:\n\n\"Ваші цінні речі вкриває товстий шар бруду? Блискочист 5200 поверне їм первісний блиск! Вставте предмет, який ви хочете очистити, і опустіть три срібні монети у монетоприймач. Дайте Блискочисту 5200 трохи попрацювати, і вуаля! Ваші речі стануть чистими та блискучими!\"", [3] = "Помістіть в Блискочист 5200 вкритий брудом предмет та три срібні монети.", [4] = "Схоже, що для того, щоб пристрій запрацював, йому потрібен вкритий брудом предмет і три срібні монети. Щойно ви помістите це все всередину, Блискочист 5200 має запрацювати...", [5] = "Ви поміщаєте вкритий брудом предмет і три срібні монети в Блискочист 5200 і машина оживає, з гудінням відшкрябуючи бруд з предмета. Гучний, несамовитий стукіт лунає зсередини машини, а його металевий корпус скрипить, хитаючись з боку в бік...", ["en"] = "The Sparklematic 5200!", ["tasks"] = { ["Grime-Encrusted Object"] = "вкритий брудом предмет", ["Grime-Encrusted Object (Provided)"] = "вкритий брудом предмет (видано)" } },
    [2952] = { [1] = "Блискочист 5200!", [5] = "Блискочист 5200 зупинився так само різко, як і почав. Віконце для предметів відкривається з дзенькотом, і ньому лежить маленька акуратно загорнута коробка з бантиком. Схоже, що Блискочист 5200 також упаковує предмети після очищення. Навіть якщо предмет все ще брудний, принаймні тепер він загорнутий у красиву коробочку.\n\nЩо ж, є лише один спосіб дізнатися, чи він впорався...", ["en"] = "The Sparklematic 5200!" },
    [2953] = { [1] = "Блискочист знову в дії", [4] = "Блискочист 5200 порожній. Для початку роботи йому потрібен вкритий брудом предмет і три срібні монети!", [5] = "Блискочист 5200 оживає, хитаючись зі сторони в сторону. Всередині бруд, що вкрив предмет, розчиняється за допомогою спеціального очисника гномів.\n\nБлискочист 5200 зупиняється, сповіщаючи про це знайомим дзенькотом. У приймальному отворі машини лежить маленька акуратно загорнута коробка.", ["en"] = "More Sparklematic Action", ["tasks"] = { ["Grime-Encrusted Object"] = "вкритий брудом предмет", ["Grime-Encrusted Object (Provided)"] = "вкритий брудом предмет (видано)" } },
    [2954] = { [1] = "Кам'яний наглядач", [2] = "\"Вітаю, я — вартовий цього проходу. Поки серед ваших дисків відсутні пластини Ульдуму, вам заборонено входити на територію Ульдуму.\"\n\nМожливо, поява кам'яного наглядача Норґаннона — те, на що й очікували ті, хто відправив вас з платиновими дисками в пустелю Танаріс. Як і було доручено, перш ніж продовжувати, ви маєте дізнатись більше про кам'яного наглядача.", [3] = "Дізнайтесь про призначення кам'яного наглядача Норґаннона, після чого знову доторкніться до постаменту Ульдуму в пустелі Танаріс.", [4] = "Ви маєте дізнатись більше про призначення кам'яного наглядача, перш ніж продовжувати...", [5] = "Голос кам'яного наглядача сповнений сили та влади:\n\n\"Ваші диски буде повернуто, коли ви знову доторкнетесь до постаменту. Доступ до комплексу вимагає наявності пластин Ульдуму серед вашого набору дисків.\"", ["en"] = "The Stone Watcher", ["tasks"] = { ["Learn the purpose of the Stone Watcher of Norgannon"] = "Дізнайтеся про призначення Кам'яного Вартового з Норганнона" } },
    [296] = { [1] = "Помста Ормера", [2] = "Поки ти {стать:був:була} там внизу, я випадково помітив що один з цих звірів відрізнявся від інших. Він був кремезніший і більш загрозливо виглядав. Б'юсь об заклад, це він привів інших сюди, щоб нашкодити розкопкам зірвавши їх.\n\nЯ прошу тебе виконати останнє завдання, {ім'я}. Подбай про те, щоб Сарлозуба було притягнуто до відповідальності. А зважаючи на тяжкість його злочинів, справедливість у цьому випадку означає смерть! Принеси мені один із його пазурів як доказ його смерті.", [3] = "Ормер Залізов'яз з розкопок Вельґара хоче, щоб ви вбили Сарлозуба та повернулись до нього з одним із його пазурів як тільки завдання буде виконано.", [4] = "Сарлозуб вже мертвий? Пам'ять полеглих спокутувано?", [5] = "Дякую тобі, {ім'я}. Твої зусилля не будуть забуті. Багато невинних дворфів загинуло на цих розкопках поки просто виконували свою роботу. Помста, яку ти {стать:доніс:донесла} цим злим створінням, повинна змусити їх замислитись двічі, перш ніж знов напасти на підданих короля Маґні.", ["en"] = "Ormer's Revenge", ["tasks"] = { ["Sarltooth's Talon"] = "пазур Сарлозуба", ["Sarltooth's Talon (Provided)"] = "пазур Сарлозуба (видано)" } },
    [2962] = { [1] = "Єдиний вихід — більше зеленої субстанції", [2] = "Мало того, що твого зразка було недостатньо, так він ще й був забруднений.\n\nНам потрібно більше цієї зеленої субстанції. Очевидно, що троги недостатньо опромінені для наших потреб. Тобі доведеться піти до Гномреґану і принести трохи радіоактивних опадів, прямо з джерела. Я про опромінених слимаків, маскунів і страховищ. Але пам'ятай, що утримати цей тип осадів досить складно. Можливо, тобі не вдасться зібрати підхожий зразок з першої спроби.", [3] = "Прямуйте до Гномреґану і принесіть звідти високорадіоактивний осад. Будьте обережні, осади нестабільні та досить швидко руйнуються.\n\nПісля завершення завдання поверніть Оззі свинцевий фіал для зразків.", [4] = "Хм, ти не світишся. Це добре.", [5] = "<Оззі оглядає вас.> Вражаюче, у тебе не відпала жодна кінцівка. Тепер поглянемо, на що здатна ця штука!", ["en"] = "The Only Cure is More Green Glow", ["tasks"] = { ["Heavy Leaden Collection Phial"] = "важкий свинцевий фіал для зразків", ["Heavy Leaden Collection Phial (Provided)"] = "важкий свинцевий фіал для зразків (видано)", ["High Potency Radioactive Fallout"] = "високорадіоактивний осад", ["High Potency Radioactive Fallout (Provided)"] = "високорадіоактивний осад (видано)" } },
    [2964] = { [1] = "Задача на майбутнє", [2] = "Що ж, {ім'я}... схоже, що ми зайшли в глухий кут. Ми знаємо, що нам потрібні пластини Ульдуму, але гадки не маємо, де їх шукати. Нам потрібно буде провести чимало досліджень та розробити план подальших дій. В мене є кілька ідей щодо пошуку і я сподіваюсь, що скоро ми відправимо тебе за пластинами.\n\nТи маєш розказати про це старшому досліднику, {ім'я}. Не сумніваюсь, він захоче особисто віддячити тобі за допомогу Лізі.", [3] = "Поговоріть зі старшим дослідником Маґелласом у Залізогарті.", [5] = "Що ж, ми всі згодні з тим, що найкращий план дій — відкласти цю справу, поки ми не звузимо зону пошуків. Ми зайшли так далеко завдяки тобі, {ім'я}, і я сподіваюсь, що саме ти й відкриєш для нас Ульдум.\n\nА поки що дозволь мені вручити тобі твій гонорар. Це має з надлишком покрити твої витрати. Заходь до нас пізніше, нас чекає Ульдум!", ["en"] = "A Future Task" },
    [2968] = { [1] = "Задача на майбутнє", [2] = "Що ж, {ім'я}... схоже, що ми зайшли в глухий кут. Ми знаємо, що нам потрібні пластини Ульдуму, але гадки не маємо, де їх шукати. Нам проведемо дослідження та розробимо план подальших дій. В мене є кілька ідей щодо пошуку і я сподіваюсь, що скоро ми знову попросимо тебе про допомогу.\n\nТи маєш розказати про це Любомудру Шукачу Істини, {ім'я}. Не сумніваюсь, він захоче особисто віддячити тобі за почутий поклик про допомогу.", [3] = "Поговоріть з Любомудром Шукачем Істини у Громовому Бескиді.", [5] = "Що ж, ми всі згодні з тим, що найкращий план дій — відкласти цю справу, поки ми не звузимо зону пошуків. Ми зайшли так далеко завдяки тобі, {ім'я}, і я сподіваюсь, що саме ти й розкриєш таємниці Ульдуму.\n\nА поки що дозволь мені вручити тобі твій гонорар. Це має з надлишком покрити твої витрати. Заходь до нас пізніше, Ульдум чекає на нас.", ["en"] = "A Future Task" },
    [2971] = { [1] = "<UNUSED>", [2] = "Опис [PH]", ["en"] = "<UNUSED>", ["tasks"] = { ["[PH] Log Bullet Entry"] = "[PH] Запис у журналі" } },
    [2977] = { [1] = "Повернення до Залізогарту", [2] = "Ви торкаєтесь постаменту і платинові диски знову опиняються у вашому рюкзаку.\n\nТепер, дізнавшись більше про кам'яного наглядача та повернувши диски, ви можете повернутись до Залізогарту та розказати про все Лізі дослідників.", [3] = "Поговоріть з істориком Карником в Залізогарті.", [4] = "З поверненням, {ім'я}. Тобі вдалось якось використати диски?", [5] = "Тобі не вистачило дисків? Цікаво... Схоже, що диски Норґаннона — лише одна з частин більшого набору. Простіше кажучи, вони як один з ключів на зв'язці.\n\nЯкщо ми знайдемо пластини Ульдуму, то зможемо й потрапити до самого комплексу! Тільки уяви — ми зможемо дослідити місце, де працювали самі Творці, не риючись в землі!\n\nНе те, щоби в ритті землі було щось погане...", ["en"] = "Return to Ironforge", ["tasks"] = { ["Miniature Platinum Discs"] = "мініатюрні платинові диски", ["Miniature Platinum Discs (Provided)"] = "мініатюрні платинові диски (видано)" } },
    [2978] = { [1] = "Сувій Ґордунні", [2] = "Піднявши забруднений сувій, ви помічаєте, що на ньому, схоже, зображено якусь зустріч або церемонію. Рок Орхан зацікавилася б цим сувоєм і тим, що він може означати для клану Ґордунні.", [3] = "Принесіть сувій Ґордунні до Роки Орхани в табір Мохаче.", [4] = "Що це?", [5] = "Цей сувій... Ти {стать:знайшов:знайшла} його на заставі Ґордунні?", ["en"] = "The Gordunni Scroll", ["tasks"] = { ["Gordunni Scroll"] = "сувій Ґордунні", ["Gordunni Scroll (Provided)"] = "сувій Ґордунні (видано)" } },
    [2983] = { [1] = "Поклик вогню", [2] = "Минуло багато часу відтоді, як ти {стать:проходив:проходила} своє останнє випробування, {ім'я}. До цього часу ти {стать:був старанним:була старанною} у своєму навчанні, але настав час тобі пізнати більшу силу... справжню силу. Ти пізнаєш елемент вогню, якщо будеш {стать:готовий:готова} заплатити за це.\n\nЗнайди Кранала Фісса у Степах. Він проживає у маленькій хатині на півночі від Перехрестя. Але май на увазі: якщо ти {стать:потрапив:потрапила} до земель клятих нічних ельфів, ти {стать:зайшов:зайшла} надто далеко.", [3] = "Знайдіть Кранала Фісса у Степах.", [5] = "Хм... То тебе Сворт прислав, так?\n\nТоді добре, Сворту завжди можна було довіряти, тож це має означити, що ти {стать:готовий:готова} спробувати наступну сапту — сапту вогню.\n\nЯ вже бачу це у твоїх очах, палання, жадання. Ти вже {стать:відчув:відчула} силу і тепер {стать:готовий:готова} до більшого. Терпіння, {ім'я}. Пам'ятай, чого навчила тебе земля. Сила й руйнування даються легко, але ти все одно {стать:повинен:повинна} знати, коли зупинитися.", ["en"] = "Call of Fire" },
    [2985] = { [1] = "Поклик води", [2] = "Схоже, що ти вже {стать:готовий:готова} до наступного випробування, {ім'я}. Ти {стать:проявляв:проявляла} терпіння у своєму навчанні, та настав час тобі зробити новий крок. Настав час пізнати чистоту води.\n\nПоговори з Іслен Морською Провидицею в Степах. Ти знайдеш її в рибальській хатині на східному узбережжі, на південь від Південнолютної річки та Брашпиля. Щасти тобі, {ім'я}.", [3] = "Знайдіть Іслен Морську Провидицю в Степах.", [5] = "Ти твердо крокуєш по землі, а твій дух вже зігрітий вогнем — я б сказала, що настав час тобі пізнати чистоту води.\n\nТвій шлях привів тебе так далеко, і сила твого духу дасть тобі сил йти далі. Але перший крок ти маєш зробити {стать:сам:сама}.", ["en"] = "Call of Water" },
    [2990] = { [1] = "Тадій Хмуротінь", [2] = "Віднеси це перо Тадію Хмуротіні, провидцю. Він залишив Орлиний пік кілька років тому у пошуках темних знань, але в душі він ще з нами, з кланом Дикого Молота!\n\nМожливо, його здібності допоможуть нам знайти Гостродзьоба.\n\nЯ взяв це перо з гнізда, де він спав. Віддай його Тадію, можливо він зможе використати свої магічні здібності для того, щоб знайти Гостродзьоба.\n\nХай щастить, {ім'я}. Ти знайдеш Тадія в Спустошених землях, у вежі магів у фортеці Підсвітньої Варти.", [3] = "Принесіть перо Гостродзьоба до Тадія Хмуротіні в Спустошені землі.", [4] = "{ім'я}, ти {стать:прийшов:прийшла} з подарунком?", [5] = "Ах, так. Це перо належить прекрасному грифону. Тому, що приречений на великі звершення... якщо він доживе до дорослого віку.\n\nХочеш його знайти? Тоді слухай уважно, {стать:хоробрий:хоробра} {клас:к}...", ["en"] = "Thadius Grimshade", ["tasks"] = { ["Sharpbeak's Feather"] = "перо Гостродзьоба", ["Sharpbeak's Feather (Provided)"] = "перо Гостродзьоба (видано)" } },
    [2992] = { [1] = "Провидіння", [2] = "Дай мені простір, поки я проводжу обряд провидіння. Я знайду зв'язок між пером, яке ти мені {стать:приніс:принесла}, та його власником і піду за цим зв'язком до самого Гостродзьоба.\n\nЦе... якщо все пройде за планом. Якщо ні, то... тобі краще закрити очі.", [3] = "Зачекайте, поки Хмуротінь виконає ритуал провидіння.", [5] = "Ритуал пройшов успішно. Я знаю де Гостродзьоб і можу розповісти, як його знайти.", ["en"] = "The Divination", ["tasks"] = { ["Wait for Grimshade to finish"] = "Зачекайте, поки Грімшейд закінчить" } },
    [2996] = { [1] = "У пошуках Страгада", [2] = "Я багато чому навчив тебе, але тобі потрібен новий вчитель. Він знаходиться в Брашпилі, його ім'я Страгад. Він людина, але не дозволяй цьому обдурити себе і думати, що він слабкий. Він могутній, навіть якщо й малий. Він може навчити тебе потужнішим заклинанням виклику — я відчуваю, що ти {стать:готовий:готова}. Йди до нього. Він у Брашпилі... біля вежі над портовим містом.", [3] = "Поговоріть зі Страгадом Фарсаном в Брашпилі.", [5] = "Насичений день у Брашпилі, чи не так? Я люблю спостерігати за напруженою роботою портового містечка. Тут стільки таємниць, стільки пригод... та стільки неуцтва.\n\nЧи це ненависть у твоїх очах, {ім'я}? Чудово, ми знайдемо для неї застосування.", ["en"] = "Seeking Strahad" },
    [3001] = { [1] = "У пошуках Страгада", [2] = "Я багато чому навчив тебе, але тобі потрібен новий вчитель. Він знаходиться в Брашпилі, його ім'я Страгад. Він людина, але не дозволяй цьому обдурити себе і думати, що він слабкий. Він не твій ворог, тому поважай його. Страгад може навчити тебе потужнішим заклинанням виклику, заклинанням які ти {стать:готовий:готова} вивчити.\n\nТи знайдеш його в Брашпилі... над портовим містом, поруч з вежею.", [3] = "Знайдіть Страгада Фарсана в Брашпилі.", [5] = "Насичений день у Брашпилі, чи не так? Я люблю спостерігати за напруженою роботою портового містечка. Тут стільки таємниць, стільки пригод... та стільки неуцтва.\n\nЧи це ненависть у твоїх очах, {ім'я}? Чудово, ми знайдемо для неї застосування.", ["en"] = "Seeking Strahad" },
    [3023] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [303] = { [1] = "Війна з Темним Залізом", [2] = "Війна лютує всюди: і на наших землях, і на чужих. Поки найсміливіші дворфи віддають свої життя за Альянс на чужині, наші власні землі страждають від Темного Заліза. Вони знищили віадук Тандола, а невдовзі й захопили Дун-Модр.\n\nМи маємо зібратись з силами та відтіснити їх. Якщо вб'єш 15 дворфів Темного Заліза, 5 прохідників, 5 диверсантів та 5 підривників, ми зможемо протриматись до приходу підкріплення.\n\nПоспіши, у нас обмаль часу!", [3] = "Мотлі Гармаш в Дун-Модрі просить вас вбити 15 дворфів, 5 прохідників, 5 диверсантів та 5 підривників Темного Заліза.", [4] = "Роґґо не зміг зв'язатися з резервами. Ми маємо добряче вдарити по Темному Залізу, {клас:к}. Тепер йди і добре послужи королю Маґні!", [5] = "Ти чудово {стать:справився:справилась} із завданням, {клас:к}. Вітаю тебе, ти {стать:довів:довела} свою доблесть і відданість королю Маґні. Завдяки твоєму нападу на Темне Залізо ми маємо непогані шанси витурити їх з наших земель... якщо ці кляті резерви таки з'являться...", ["en"] = "The Dark Iron War", ["tasks"] = { ["Dark Iron Demolitionist"] = "підривник Темного Заліза", ["Dark Iron Demolitionist slain"] = "підривник Темного Заліза: убито", ["Dark Iron Dwarf"] = "дворф Темного Заліза", ["Dark Iron Dwarf slain"] = "дворф Темного Заліза: убито", ["Dark Iron Saboteur"] = "диверсант Темного Заліза", ["Dark Iron Saboteur slain"] = "диверсант Темного Заліза: убито", ["Dark Iron Tunneler"] = "прохідник Темного Заліза", ["Dark Iron Tunneler slain"] = "прохідник Темного Заліза: убито" } },
    [304] = { [1] = "Похмуре завдання", [2] = "Багато моїх вояків полягло в битві при Дун-Модрі. Мій рідний брат загинув, коли західний міст через віадук Тандола був знищений. Еге ж, дворфи Темного Заліза - диявольська порода. З того, що Роґґо вдалося дізнатися, ватажком цієї банди негідників у Заболотті є чорнокнижник на ім'я Балґарас Паскудний. Однак, він - той ще боягуз. Він посилає своїх солдатів на завдання, а сам залишається невловним, уникаючи небезпеки.\n\nЯкщо тобі вдасться знайти цього підступного негідника, убий його та принеси мені його вухо. Я винагороджу тебе, {клас:н}.", [3] = "Убийте Балґараса Паскудного і принесіть його вухо Довгокосу Похмурому за Дун-Модром.", [4] = "Тобі вже вдалося віднайти Балґараса Паскудного, {клас:к}? Він уже досить давно уникає нас.", [5] = "Балґарас Паскудний нарешті мертвий. І хоча його смерть не поверне до життя багацько невинних дворфів, які марно загинули від його руки, вона допоможе відновити душевний спокій тим, хто вижив. Зі смертю Балґараса повинно бути нескладно впоратися з рештою негідників Темного Заліза. Тепер ми повинні винищити їх під корінь, поки у них не з'явився новий ватажок.\n\nДобре {стать:спрацював:спрацювала}, {клас:к}.", ["en"] = "A Grim Task", ["tasks"] = { ["Ear of Balgaras"] = "вухо Балґараса", ["Ear of Balgaras (Provided)"] = "вухо Балґараса (видано)" } },
    [3042] = { [1] = "Трольське місиво", [2] = "Піщанолюті тролі з Зул'Фарраку виготовляють матеріал для загартування з пісковику. Я зможу використати його для загартування власних виробів, о так! Він дуже цінується серед майстрів і якщо ти принесеш мені багато цього матеріалу, я добряче віддячу тобі.\n\nЗул'Фаррак розташований на північному заході від Пристробляху. Бажаю успіхів.", [3] = "Принесіть 20 флаконів трольського місива Трентону Світломолоту в Пристроблях.", [4] = "Ти {стать:приніс:принесла} місиво, {ім'я}?", [5] = "Так, це справді чудове місиво! Ще й так багато! Я буду довго використовувати його!\n\nДякую, {ім'я}. Будь ласка, прийми це як оплату.", ["en"] = "Troll Temper", ["tasks"] = { ["Troll Temper"] = "трольське місиво", ["Troll Temper (Provided)"] = "трольське місиво (видано)" } },
    [3064] = { [1] = "<NYI> <TXT> Піратські капелюхи", [2] = "Мені потрібні піратські капелюхи для мого магазину. Купіть мені багато!", ["en"] = "<NYI> <TXT> Pirate Hats" },
    [312] = { [1] = "Викрадені припаси Тундри Мак-Ґранна", [2] = "Я мав запаси в'яленого м'яса на місяць хурделиці. Я тримав його в скрині на замку, щоб ведмеді до нього не дістались. Але поки я полював на оленів, цей звірюга, старий Кригоборід, вкрав мою скриню з м'ясом. Він не зможе зламати торієвий замок, але ж я вмру з голоду якщо не поверну його.\n\nТи здаєшся {стать:спритнішим:спритнішою} за мене. Може ти зможеш повернути мої припаси? Я покалічив ногу і не зможу швиденько пробратись в печеру і поцупити скриню.", [3] = "Дістаньте в'ялене м'ясо Тундри Мак-Ґранна з викраденої скрині в печері Старого Кригоборода.", [4] = "Ти {стать:дістався:дісталась} до скрині, {ім'я}?", [5] = "Яка ж ти добра душа, {ім'я}! Завдяки твоїй сміливості, я не помру від голоду, коли почнеться завірюха.", ["en"] = "Tundra MacGrann's Stolen Stash", ["tasks"] = { ["MacGrann's Dried Meats"] = "в'ялене м'ясо Мак-Ґранна", ["MacGrann's Dried Meats (Provided)"] = "в'ялене м'ясо Мак-Ґранна (видано)" } },
    [3141] = { [1] = "Лорам", [2] = "Отже, ти хочеш битися з демонами? Тоді для початку послухай, що я скажу.", [3] = "Послухайте історію Лорама Таліпедеса.", [4] = "Не перебивай мене, {раса:к}.", [5] = "Так тому і бути...", ["en"] = "Loramus", ["tasks"] = { ["Loramus' Story"] = "Історія Лорамуса" } },
    [316] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>", ["tasks"] = { ["Squirrel Nut"] = "білчаний горіх" } },
    [3161] = { [1] = "Ґаз'ридіан", [2] = "{ім'я}, я науковець, але в серці ще й мисливець за скарбами!\n\nДавним-давно, коли тут ще перебували тролі, вони створили велику кількість прикрас за зразком Ґаз'рілли, гідри, якій вони поклонялися як божеству. Ці прикраси виконані з особливого матеріалу, який я називаю \"ґаз'ридіан\", на честь їхнього бога-гідри.\n\nЯ знайшов кілька таких прикрас самостійно, але я б хотів мати більше, щоб дослідити їх — можливо, ти зможеш знайти ще?\n\nЯ навіть винайшов детектор, який допомагає швидко знаходити ґаз'ридіан! Просто вдягни його і розпочинай пошуки!", [3] = "Марвон Заклепник з Танаріса хоче, щоб ви зібрали 30 газ'ридіанських прикрас.", [4] = "У тебе виникли проблеми?\n\nТи можеш знайти ґаз'ридіан практично всюди в Танарісі, {ім'я}, тож продовжуй шукати!", [5] = "Чудово, ці прикраси ідеально підходять для моїх досліджень. Дуже дякую за допомогу, {ім'я}.\n\nО, і можеш повернути мій шолом?", ["en"] = "Gahz'ridian", ["tasks"] = { ["Gahz'ridian Detector"] = "ґаз'ридіанський детектор", ["Gahz'ridian Detector (Provided)"] = "ґаз'ридіанський детектор (видано)", ["Gahz'ridian Ornament"] = "ґаз'ридіанська прикраса", ["Gahz'ridian Ornament (Provided)"] = "ґаз'ридіанська прикраса (видано)" } },
    [3181] = { [1] = "Ріг чудовиська", [2] = "Цей гігантський ріг вкритий численними подряпинами й тріщинами. Крім того, в ньому застрягла якась залізяка.\n\nОглянувши його ретельніше, ви розумієте, що ця залізяка є уламком сокири. На металі видніється гравіювання:\n\nВласність горянки Щебінки.\n\nВи намагаєтесь витягнути зламану головку сокири, але вона розсипається на дрізки.\n\nУпс!", [3] = "Віднесіть гігантський ріг Марґол горянці Щебінці.", [4] = "Ні, я не відчиню ворота.", [5] = "Що це в тебе? Це ж очевидна підробка!\n\nЯ стикалась з Марґол і точно знаю, що її ріг щонайменше у вісім разів більше, ніж те, що ти тримаєш в руках, {ім'я}. Ти певно {стать:зняв:зняла} це з якогось буреморда в Степах. Ні, {стать:пане:пані}, Щебінку так легко не надурити.", ["en"] = "The Horn of the Beast", ["tasks"] = { ["Margol's Gigantic Horn"] = "гігантський ріг Марґол", ["Margol's Gigantic Horn (Provided)"] = "гігантський ріг Марґол (видано)" } },
    [3182] = { [1] = "Доказ правоти", [2] = "Ти думаєш, що я повірю в цю нісенітницю? Якби це був справжній ріг, з нього б все ще стирчало лезо моєї сокири.\n\nСлухай, неси цю підробку куратору Торію в Залізогарт. Якщо він зможе підтвердити ці слова, повертайся з доказом твоєї правоти і я дам тобі ключ від воріт до Випаленої ущелини.\n\nЙди вже!", [3] = "Віднесіть гігантський ріг Марґол куратору Торію в Залізогарт.", [4] = "Вітаю вас, {стать:юначе:юначко}. Бажаєте оглянути музей?", [5] = "Що це?\n\nОх, очам своїм не вірю! Ви усвідомлюєте, що тримаєте в руках, {раса:к}? Це ріг Марґол Лютої! Тої самої Марґол, від якої постраждав кожен археолог, що коли-небудь ступав у Випалену ущелину.\n\nЧи можу я його залишити собі?", ["en"] = "Proof of Deed", ["tasks"] = { ["Margol's Gigantic Horn"] = "гігантський ріг Марґол", ["Margol's Gigantic Horn (Provided)"] = "гігантський ріг Марґол (видано)" } },
    [3201] = { [1] = "Нарешті!", [2] = "Не можу повірити, що Щебінка сумнівалась в справжності рогу. Між нами, я думаю вона просто заздрить. Я знаю, що вона сама хотіла вбити це чудовисько, але щось пішло не так.\n\nТож вам потрібен доказ правоти? Після вашого цінного внеску до музею я з радістю випишу його.\n\n<Куратор Торій починає заповнювати величезний документ.>\n\nОсь так! Можете повертатись з цим до Щебінки.", [3] = "Покажіть доказ правоти горянинці Щебінці.", [4] = "Не можу в це повірити.", [5] = "Не знаю, як {стать:такий хиляк:така хилячка}, як ти, {стать:зміг:змогла} подолати Марґол, але угода є угода. Ось ключ.\n\nЯкщо після цього з тобою щось трапиться — ти {стать:сам винен:сама винна}.", ["en"] = "At Last!", ["tasks"] = { ["Proof of Deed"] = "доказ правоти", ["Proof of Deed (Provided)"] = "доказ правоти (видано)" } },
    [321] = { [1] = "Світлосталеве залізо", [2] = "Тут на узбережжі затонули кораблі з приреченої Третьої флотилії Кул-Тірасу, які були спалені та потоплені червоними драконами під час останньої Великої Війни.\n\nФлотилія йшла з Лордерону, але разом з нею плив один корабель, ельфійський руйнівник — Летюча Скопа. Він перевозив партію світлосталі та приєднався до Третьої флотилії для захисту. Іронія в тому, що він затонув разом з іншими кораблями під час атаки тих самих драконів...\n\nДостатньо історії. Залишки Летючої Скопи лежать на півдні від гавані Менетілів. Якщо знайдеш там світлосталь, принеси його мені.", [3] = "Пошукайте уламки Летючої Скопи в Заболотті.", [5] = "Ця затоплена скриня розбита. Слідів кігтів на скрині свідчать про те, що мурлоки обнишпорили її й вкрали вміст.\n\nПроте на дні скрині ви знайшли один злиток світлосталі. На жаль, щоб створити зброю, знадобиться набагато більше злитків.", ["en"] = "Lightforge Iron" },
    [322] = { [1] = "Благословенна зброя", [2] = "У Дворфійському районі Штормовію є дворф-зброяр, який кує вироби зі світлосталі. Його звати Ґріманд Елмор.\n\nЯ зібрав знайдені тобою злитки у скриньку. Віднеси його Ґріманду і розкажи йому свою історію. Я впевнений, що він допоможе тобі та виготовить для тебе зброю — зброю, яка змусить тремтіти навіть Морбента Скверна!", [3] = "Віднесіть ящик злитків світлосталі до Ґріманда Елмора в Штормовій.", [4] = "Що саме я можу зробити для тебе, {клас:к}?", [5] = "Оце в тебе історія. І злитки світлосталі! З таким металом я не працював роками. Це буде честю знову працювати з ним. І ти {стать:повинен:повинна} повернутися до мене пізніше і розповісти про битву з некромантом.\n\nАле ми трішки забігаємо наперед. Для початку створимо твою зброю проти Морбента Скверна...", ["en"] = "Blessed Arm", ["tasks"] = { ["Crate of Lightforge Ingots"] = "скринька зі злитками світлосталі", ["Crate of Lightforge Ingots (Provided)"] = "скринька зі злитками світлосталі (видано)" } },
    [3241] = { [1] = "<NYI> <TXT><redux> Пік Жахливої Тумани", [2] = "Зберіть тотеми з Піку Жахливої Тумани, бо там зараз гидко, і немає місця для блискучих чистих тотемів.", ["en"] = "<NYI> <TXT><redux> Dreadmist Peak" },
    [328] = { [1] = "Прихований ключ", [2] = "Хоч в цих записах і немає жодної згадки про рядового Торсена, в палітурці однієї з бухгалтерських книг Герода був захований маленький латунний ключ.\n\nА після подальшого вивчення його записів, посеред різних паперів ви знаходите кілька згадок про \"надійний сейф\". Сейф знаходиться десь у Погребиці — комплексі печер позаду поселення Курцена.\n\nЯкщо знайти цей сейф і відкрити його за допомогою цього ключа, то, можливо, таємниця розкриття Торсена буде розкрита.", [3] = "Використайте маленький латунний ключ, щоб відкрити сейф букмекера Герода.", [4] = "Сейф окутий бронзою, він дуже міцний і дуже важкий.", [5] = "Відкривши сейф, стає зрозуміло, що саме тут Герод зберігає свої найцінніші монети та предмети.", ["en"] = "The Hidden Key", ["tasks"] = { ["Small Brass Key"] = "маленький латунний ключ", ["Small Brass Key (Provided)"] = "маленький латунний ключ (видано)" } },
    [329] = { [1] = "Шпигуна розкрито!", [2] = "Серед цінностей в сейфі ви знаходите брудну, надряпану записку. Хоч і текст ледве читається, але все ж вдається зрозуміти, що це маршрут рядового Торсена. У ній детально описано маршрути його патрулювання, з ким він розмовляє і як проводить час з повстанцями. Записка підписана лише однією літерою — M.\n\nАле, хто б не написав цю записку, у нього дуже близькі відносини з Торсеном. Автор цієї записки — зрадник табору Повстання.", [3] = "Віднесіть брудну записку лейтенанту Дорену в табір Повстання.", [4] = "Ти {стать:з'ясував:з'ясувала}, хто знав таємницю Торсена? Серед нас є зрадник?", [5] = "Дякую тобі, {ім'я}. Ця записка — ключ, який нам потрібен, щоб позбутися зрадника!", ["en"] = "The Spy Revealed!", ["tasks"] = { ["Muddy Note"] = "брудна записка", ["Muddy Note (Provided)"] = "брудна записка (видано)" } },
    [330] = { [1] = "Розклад патрулювання", [2] = "Записка, яку ти мені {стать:дав:дала}, підписана літерою \"М\"... Я не знаю, що це може означати.\n\nАле, в записці також сказано, що ця людина патрулювала разом з Торсеном минулого тижня. Значить, він і є зрадником!\n\nПіди до капрала Сетмана. Він складає розклад патрулювання і зможе сказати тобі, хто був з Торсеном.", [3] = "Поговоріть з капралом Сетманом.", [5] = "О, так, я можу зробити це для тебе. Подивимось... Минулого тижня це був...\n\nРядовий Мерл працював разом з Торсеном. У них був однаковий розклад патрулювання весь минулий тиждень.", ["en"] = "Patrol Schedules" },
    [331] = { [1] = "Доповідь Дорену", [2] = "Чи не просив лейтенант Дорен, щоб ти {стать:доповів:доповіла} йому зібрану інформацію про патрулювання?", [3] = "Поговоріть з лейтенантом Дореном.", [5] = "Мені боляче чути, що нас зрадив Мерл. Він завжди був хоробрим солдатом і я думав, що в нього щире серце. Але це дуже добре, що ми його викрили — з таким шпигуном, як він, ми б довго не вистояли проти полковника Курцена.", ["en"] = "Report to Doren" },
    [3321] = { [1] = "Не це шукаєш?", [2] = "Ти {стать:зробив:зробила} багато для ордену, {ім'я}. Відданість, яку ти {стать:вклав:вклала} у досягнення цього рівня відлякала б будь-якого звичайного коваля. Я, як і Ґальван, розумію, що ти — {стать:один:одна} з нас.\n\nТому я вважаю, що ти заслуговуєш на невелику винагороду. Нічого особливого насправді, лише дрібничка. Тобі можуть бути знайомі її властивості, оскільки саме вона привела тебе до нас з самого початку.", [3] = "Зачекайте, поки Трентон закінчить свою роботу.", [4] = "Сьогодні ми завершуємо святкування твоєї відданості ордену.", [5] = "Встань і прийми наше визнання, {ім'я}, коваль ордену мітрилу.", ["en"] = "Did You Lose This?", ["tasks"] = { ["Watch Trenton Work"] = "Дивіться роботу Трентона" } },
    [336] = { [1] = "Благородний напій", [2] = "Лорд Вішок, як і всі люди, має свої слабкості. Він має пристрасть до алкоголю. Його лицемірство вражає. Цей дурень проводить дні, намагаючись закрити нашу маленьку «таверну», а ночує нагорі, збираючи рахунок, який він ніколи не оплачує. Що ж, поглянемо, як Вішоку сподобається цей особливий напій, що я приготував для нього: ель \"Чорний кіготь\". Він дуже міцний, {ім'я}.\n\nВіднеси це йому і подивись, чи йому сподобається. Швидше за все, старий дурень метушиться біля Зали прохачів.", [3] = "Віднесіть ель \"Чорний кіготь\" лорду Вішоку в Зал прохачів.", [4] = "Хіба ти не бачиш, що я зайнятий? Мої слова мають бути почуті! Це важливо для майбутнього цього Королівства!\n\nОй... що це в тебе? Схоже на освіжаючий напій...", [5] = "О, дякую, що {стать:приніс:принесла} мені цей чудовий напій, слуга. Ось тобі мідяк. А тепер забирайся геть із моїх очей, дай мені насолодитися напоєм!", ["en"] = "A Noble Brew", ["tasks"] = { ["Black Claw Stout"] = "\"Чорний Кіготь\"", ["Black Claw Stout (Provided)"] = "\"Чорний Кіготь\" (видано)" } },
    [3362] = { [1] = "Чортополоховий чагарник", [2] = "Ти коли-небудь {стать:бачив:бачила} Чортополоховий чагарник? Це надзвичайно небезпечне місце, {ім'я}.\n\nТі чудернацькі істоти там, я їм не довіряю! Чортополохові шкарбуни та коренеплети, здається, їх так називають...\n\nТак от, я хочу потрапити в чагарник, але з такою кількістю тих чортополохових тварюк у мене жодних шансів повернутись звідти живим. Ось тут ти й {стать:потрібен:потрібна} — якщо викосити частину цих істот, я, можливо, подумаю про те, щоб знову сходити туди. Що скажеш, {ім'я}? Допоможеш мені?", [3] = "Тран'рек з Пристробляху просить вас вбити 8 чортополохових шкарбунів і 8 чортополохових коренеплетів.", [4] = "Я хотів би роздивитися ближче кактуси в чагарнику... Тож залиш хоч щось цілим, гаразд?", [5] = "Вони такі великі? Мабуть, доведеться обдумати свої плани...\n\nАле ти {стать:виконав:виконала} свою частину угоди, тож ось те, що я тобі обіцяв.", ["en"] = "Thistleshrub Valley", ["tasks"] = { ["Gnarled Thistleshrub"] = "чортополоховий шкарбун", ["Gnarled Thistleshrub slain"] = "чортополоховий шкарбун: убито", ["Thistleshrub Rootshaper"] = "чортополоховий коренепліт", ["Thistleshrub Rootshaper slain"] = "чортополоховий коренепліт: убито" } },
    [3363] = { [1] = "Осквернений піснеквіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на піснеквіт. Плоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите кенарійський бальзам зцілення рослин на піснеквіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Songflower", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [3366] = { [1] = "Сяючий уламок", [2] = "Уламок яскраво зелений і, не дивлячись на суцільність, під його поверхнею клубочиться щось схоже на дим. Ви не можете відірватись від кристала і водночас він викликає тривожність.\n\nМожливо, вам варто пошукати в Брашпилі когось, хто зможе розказати про цей кристал більше.", [3] = "Відправляйтесь до Брашпиля і з'ясуйте, які секрети приховує уламок кошмару.", ["en"] = "The Glowing Shard", ["tasks"] = { ["Glowing Shard"] = "сяючий уламок", ["Glowing Shard (Provided)"] = "сяючий уламок (видано)", ["Speak with someone about the Nightmare Shard"] = "Поговоріть з кимось про Уламок Кошмару" } },
    [3368] = { [1] = "Камені Сантари", [2] = "Брате,\n\nЯкщо ти читаєш цей лист, мене більше немає в живих. Не знаю, хто доставить тобі листа, але неодмінно подякуй і винагороди його.\n\nТепер про камені: вони існують, і вони у Темного Заліза. Їхній лідер, Латорик Чорний, використовує силу каменів, щоб поневолити мою команду археологів. Їх відвели в котел. Їхній розум затьмарений, вони працюють день і ніч, щоб завершити щось під назвою Обсидіон.\n\nВрятуй їх, брате. Це моя остання воля.\n\n-Дорій", [3] = "Віднесіть обпалений лист Торію в Залізогарт. Він знаходиться в залі Дослідників.", [4] = "<Торій плаче.>", [5] = "<Торій витирає сльози.>\n\nКлянусь Світлом, ми виконаємо його волю.", ["en"] = "Suntara Stones", ["tasks"] = { ["Singed Letter"] = "обпалений лист", ["Singed Letter (Provided)"] = "обпалений лист (видано)" } },
    [3370] = { [1] = "У кошмарах", [2] = "Цей уламок зберігає великі секрети. Це істинне єство Смарагдового Сну. Однак те, що я бачу в ньому — зовсім не сон. Дехто називає такі видіння кошмаром.\n\nНе хочу тебе хвилювати, {ім'я}, але я вважаю, що якнайкраще буде віддати цей уламок в руки мудрого друїда, і якнайшвидше.\n\nМатренґіл Ведмелик у Кенарійському Колі — це саме той, кого потрібно знайти. Вирушай в Дарнас. На жаль, я більше нічого не можу сказати.", [3] = "Принесіть уламок кошмару Матренґілу Ведмелику в Дарнас.", [4] = "Чим можу тобі допомогти?", [5] = "Фалла послала тебе до мене? Ану-ну, подивімось на той уламок, що, як ти кажеш, так її наполохав...\n\n<Матренґіл вглядається в уламок>\n\nО... Я не... Ну.\n\n{ім'я}, дякую, що ти {стать:приніс:принесла} мені це. Необачно обговорювати подібні речі, але я все-таки, дещо тобі скажу. Цією справою надалі займатимуться виключно кенарійські друїди.\n\nСкажімо так: в Смарагдовому Сні все виявляється зовсім не так, як ми вважали...\n\nМожливо, у майбутньому наші з тобою шляхи знову перетнуться.", ["en"] = "In Nightmares", ["tasks"] = { ["Nightmare Shard"] = "уламок кошмару", ["Nightmare Shard (Provided)"] = "уламок кошмару (видано)" } },
    [3371] = { [1] = "Дворфійське правосуддя", [2] = "Там, де колись було моє серце, нині порожня діра, {ім'я}. Я ніколи не зможу змиритися із загибеллю Дорія. Але я маю виконати його останнє бажання — винуватці цього холоднокровного вбивства мають пізнати правосуддя.\n\nПовертайся до Випаленої ущелини та виконай його останнє прохання — звільни його товаришів.", [3] = "Повертайтесь до Випаленої ущелини та знайдіть команду археологів Дорія.", [5] = "Забудь про мене, допоможи іншим...", ["en"] = "Dwarven Justice" },
    [3372] = { [1] = "Звільни їх", [2] = "Звільни їх, {раса:к}. Навіть коли їх тіла знесиляться, сила Сантари змусить їх завершити завдання будь-якою ціною.\n\nВся справа у вівтарі Сантари. Йди на північний захід. В пагорбах, над печерою, Сутінковий Молот охороняє реліквію. Забери її та поклади на вівтар Сантари.\n\n<Археолог знесилено падає на землю.>", [3] = "Знайдіть загадковий артефакт, який охороняють ідолопоклонники Сутінкового Молота в північно-західній частині Випаленої ущелини.", [4] = "Вівтар порожній.", [5] = "Ви кладете загадковий артефакт на вівтар Сантари.", ["en"] = "Release Them", ["tasks"] = { ["Mysterious Artifact"] = "загадковий артефакт", ["Mysterious Artifact (Provided)"] = "загадковий артефакт (видано)" } },
    [3373] = { [1] = "Сутність Ераніка", [2] = "Ви торкаєтеся самоцвіту та чуєте пронизливий голос у вашій свідомості.\n\n\"{стать:Смертний:Смертна}, почуй моє благання. Я — Еранік із Крила зелених драконів, хранитель цього проклятого храму. Я мав завадити тролям в нав'язуванні віри у свого бога, але мене спіткала невдача. Коли я вклав в цей самоцвіт частину своєї сутності, я відчув, як втрачаю владу над Сном і мене поглинає хаос. Будь ласка, поклади цей самоцвіт у купіль сутності в моєму лігві та нехай магія очистить мою свідомість від пороку, щоб я зміг відпочити\".", [3] = "Помістіть сутність Ераніка в купіль сутності, розташовану в його лігві в Затонулому храмі.", [4] = "Наближаючись до купелі, про яку розповідав Еранік, його голос знову торкається вашої свідомості.\n\n\"Так, {стать:смертний:смертна}, ця купіль сутності звільнить незаплямовану частину моєї свідомості, ув'язнену у цьому самоцвіті. Поклади самоцвіт всередину купелі й дай магії Крила зелених драконів очистити мою сутність від скверни та пороку. Тільки тоді я здобуду справжню свободу і тільки тоді Крило драконів зможе відновити своє панування над Атал'ай\".", [5] = "Ви поміщаєте камінь всередину купелі з есенцією.\n\n\"Дякую тобі, {стать:смертний:смертна}, ти маєш — ні... Цього не може бути! Ні! Скверна цього проклятого бога заплямувала навіть святість купелі Крила зелених драконів! Ні, будь ласка, я відчуваю, як моя сутність виривається з мене! БІЛЬ! Я відчуваю, як мою душу поглинає вічний кошмар...\"\n\n\"{стать:Смертний:Смертна}, благаю тебе! Знайди когось з Крила зелених драконів, щоб зупинити це... Допоможи мені... Мене поглинула темрява... Вічні страждання... Будь ласка, змилуйся...\"", ["en"] = "The Essence of Eranikus", ["tasks"] = { ["Essence of Eranikus"] = "сутність Ераніка", ["Essence of Eranikus (Provided)"] = "сутність Ераніка (видано)" } },
    [3374] = { [1] = "Сутність Ераніка", [2] = "Ви застосовуєте клятвокамінь і з його допомогою Ітарій подумки промовляє до вас.\n\n\"Приймаючи силу, укладену в цей клятвокамінь, ти погоджуєшся допомогти мені та драконам Ізери звільнити понівечену душу Ераніка. Перша з багатьох жертв, на яку, без сумніву, доведеться піти і тобі, і мені — передати мені камінь, в якому сковано те, що залишилося від вільної волі Ераніка.\n\nЗроби це, {ім'я}, і далі ми будемо діяти разом, щоб звільнити душу гідну звільнення.\"", [3] = "Принесіть клятвокамінь драконів Ізери та скуту сутність Ераніка до Ітарія на болото Скорбот. Там вам доведеться зробити вибір: допомагати драконам Ізери чи ні.", [4] = "Ось ми й знов на роздоріжжі, {ім'я}. Прийшов час робити новий вибір. Що ти {стать:вирішив, смертний:вирішила, смертна}?", [5] = "Вибір зроблено, початок покладено. Поки, я вважаю твій вибір вірним. Твої дії та вчинки відтепер визначатимуть, чи слід це продовжувати.", ["en"] = "The Essence of Eranikus", ["tasks"] = { ["Chained Essence of Eranikus"] = "скута сутність Ераніка", ["Chained Essence of Eranikus (Provided)"] = "скута сутність Ераніка (видано)", ["Oathstone of Ysera's Dragonflight"] = "клятвокамінь драконів Ізери", ["Oathstone of Ysera's Dragonflight (Provided)"] = "клятвокамінь драконів Ізери (видано)" } },
    [3377] = { [1] = "Молитва Елуні", [2] = "Ти допоможеш мені, {стать:смертний:смертна}? Послухай мою історію.", [3] = "Вислухайте історію Замаеля.", [4] = "Дозволь мені закінчити розповідь.", [5] = "Я змирився зі своєю долею тут, у цій клітці, але молитву потрібно знайти.", ["en"] = "Prayer to Elune", ["tasks"] = { ["Zamael Story"] = "Історія Замаеля" } },
    [3378] = { [1] = "Молитва Елуні", [2] = "Ти допоможеш мені, {стать:смертний:смертна}? Ти відшукаєш молитву Елуні?\n\nЯк я вже казав, молитва була вигравіювана на золотій табличці, яка тепер, мабуть, в одного з цих мерзенних безбожників, що поклоняються ідолам.\n\nЯкщо тобі вдасться відшукати молитву, занеси її до Астарії Зорегляд в Дарнас. Нехай я й прийшов до віри лиш після того, як зробив багато зла цьому світу, та моя молитва має бути почута. А на прощення своїх гріхів я й не сподіваюсь...", [3] = "Знайдіть молитву Елуні та віднесіть її Астарії Зорегляд в Дарнас.", [4] = "Що привело тебе до храму Місяця, {ім'я}?", [5] = "Елуна усміхається тобі, {ім'я}. Ти {стать:повернув:повернула} їй загублену душу. Будь ласка, прийми це на знак нашої вдячності.", ["en"] = "Prayer to Elune", ["tasks"] = { ["Prayer to Elune"] = "молитва Елуні", ["Prayer to Elune (Provided)"] = "молитва Елуні (видано)" } },
    [3379] = { [1] = "Тінеплет", [2] = "Павуки Випаленої ущелини — це невичерпне джерело тінешовку. Як ти знаєш, майстри нашої професії дуже цінують тінешовк.\n\nНещодавно в ці землі проникла група браконьєрів, яка масово убиває павуків, навіть не задумуючись про наслідки своїх дій. Перша твоя задача є простою: знайти їх... і прикінчити.\n\nПочни свої пошуки на півночі.\n\nЯкщо тобі знадобиться допомога, звернись до Пожара.", [3] = "Убийте групу браконьєрів тінешовку у Випаленій ущелині. Ніліт вважає, що їх п'ятеро. Поверніться до Ніліт коли виконаєте завдання.", [4] = "Тобі вдалось їх знайти?", [5] = "Чудова робота, {ім'я}.\n\nВізьми цю нагороду — впевнена, подібних виробів з тінетканини ти ще не {стать:бачив:бачила}!", ["en"] = "Shadoweaver", ["tasks"] = { ["Shadowsilk Poacher"] = "браконьєр тінешовку", ["Shadowsilk Poacher slain"] = "браконьєр тінешовку: убито" } },
    [338] = { [1] = "Зелені пагорби Тернистої долини", [2] = "Майстер Ернінґвей так засмутиться, якщо дізнається про це!\n\nВін довірив мені вичитати рукопис свого роману \"Зелені пагорби Тернистої долини\". Все йшло добре, поки сильний порив вітру не порозкидав сторінки!\n\nМені вдалося зібрати більшість сторінок, але багато з них все ще розкидані по джунглях. Збери сторінки, щоб закінчити усі чотири розділи.\n\nЯ допоможу тобі впорядкувати їх. Тільки принеси мені всі розділи.", [3] = "Зберіть усі загублені сторінки рукопису \"Зелені пагорби Тернистої долини\". Коли знайдете всі чотири розділи, віднесіть їх Барнілу.", [4] = "Ти вже {стать:зібрав:зібрала} усі розділи, {ім'я}?", [5] = "Ти {стать:позбавив:позбавила} мене купи неприємностей, {ім'я}! Я не знаю, як тобі віддячити. Незабаром ми побачимо книгу майстра Ернінґвея в бібліотеках по всьому світу!", ["en"] = "The Green Hills of Stranglethorn", ["tasks"] = { ["Green Hills of Stranglethorn - Chapter I"] = "Зелені пагорби Тернистої долини — Розділ I", ["Green Hills of Stranglethorn - Chapter I (Provided)"] = "Зелені пагорби Тернистої долини — Розділ I (видано)", ["Green Hills of Stranglethorn - Chapter II"] = "Зелені пагорби Тернистої долини — Розділ II", ["Green Hills of Stranglethorn - Chapter II (Provided)"] = "Зелені пагорби Тернистої долини — Розділ II (видано)", ["Green Hills of Stranglethorn - Chapter III"] = "Зелені пагорби Тернистої долини — Розділ III", ["Green Hills of Stranglethorn - Chapter III (Provided)"] = "Зелені пагорби Тернистої долини — Розділ III (видано)", ["Green Hills of Stranglethorn - Chapter IV"] = "Зелені пагорби Тернистої долини — Розділ IV", ["Green Hills of Stranglethorn - Chapter IV (Provided)"] = "Зелені пагорби Тернистої долини — Розділ IV (видано)" } },
    [3381] = { [1] = "Зустріч з господарем", [2] = "А, {стать:юний:юна} {раса} {стать:завітав:завітала}, аби поговорити з Санатом. Який чудовий день! Яка честь бути вшанованим твоєю присутністю. Дякую!\n\nБудь ласка... не сприйми мій сарказм за комплімент. Прояснімо одну річ: ти мені не подобаєшся. Але ця маленька розмова не про нас. Вона щодо мого господаря.\n\nПринеси мені дві пір'їни гіпогрифа для моїх стріл і я дозволю тобі побачитися з ним. Він просив відсилати шукачів пригод до нього, якщо вони доведуть, що варті такої честі.", [3] = "Принесіть 2 неушкоджені пір'їни гіпогрифа Санату Лім-йо в Азшарі, якщо хочете поговорити з його господарем.", [4] = "Я залишаюся тут за наказом господаря. Він дозволив мені просити будь-яку ціну за переправлення до його вежі. Поки що я прошу тільки дві пір'їни з кожного мандрівника, аби продовжувати виготовляти мої особливі стріли.\n\nЯкщо будеш {стать:необережним:необережною} — підвищу ціну. Як щодо пів дюжини золотих?\n\nЯ так і думав. Поводься добре і я не завищуватиму ціну.", [5] = "Дві пір'їни, як я і просив. І зовсім не погані.\n\n{стать:Готовий:Готова}? Тільки скажи — і я відправлю тебе куди треба.\n\nІ ще раз: поводься добре... мій господар не любить недоумків, але він дуже щедрий до тих, хто йому догоджає.", ["en"] = "A Meeting with the Master", ["tasks"] = { ["Undamaged Hippogryph Feather"] = "неушкоджена пір'їна гіпогрифа" } },
    [3382] = { [1] = "Засідка!", [2] = "Ми були недалеко від берега, шукали безпечну гавань, аби кинути якір. Не минуло й години після заходу сонця, коли вони напали... кляті наги!\n\nНе знаю, що вони шукали, але очевидно, що нічого не знайшли — вони вже раз поверталися. Двійко моїх дозорних стережуть вхід в долину, аби попередити нас про наступний напад.\n\nШкода, що ти {стать:з'явився:з'явилася} саме зараз, {ім'я}, але тут вже нічого не поробиш.\n\n{стать:Готовий:Готова} до найзапеклішої битви у своєму житті?", [3] = "Захистіть капітана Ванессу Белтіс, її команду, а також пасажирів \"Дозорного небосхилу\" від нападу наг. Капітан Ванесса Белтіс повинна вижити.", [4] = "Битва буде важкою...", [5] = "У тебе вийшло! Дякую! Безумовно, це була одна з найжорстокіших битв в моєму житті. Навіть не знаю, як тобі віддячити.\n\nШкода, що не всі мої побратими змогли пережити це випробування.\n\nЯ хотіла б попросити тебе поговорити з усіма пасажирами \"Дозорного небосхилу\", які вижили. У декого з них були справи в цій місцині. Можливо, у них знайдеться кілька прохань, якщо ти не проти допомогти. Ще раз дякую за допомогу.", ["en"] = "A Crew Under Fire", ["tasks"] = { ["Protect Captain Vanessa Beltis from the naga attack"] = "Захистіть капітана Ванесу Белтіс від нападу нагів" } },
    [3383] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>", ["tasks"] = { ["Horizon Scout Cook slain"] = "Кухар-скаут Horizon: убито", ["Horizon Scout Engineer slain"] = "Інженер-розвідник Horizon: убито", ["Horizon Scout First Mate slain"] = "Перший помічник розвідника Horizon: убито", ["Roland Geardabbler slain"] = "Роланд Гірдаблер: убито" } },
    [3384] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>", ["tasks"] = { ["Roland's Mana Gem"] = "Самоцвіт Мани Роланда" } },
    [3385] = { [1] = "Підпільний ринок", [2] = "Вони називають себе Підпільним ринком: безжалісні торговці, готові продати, перевезти, торгувати й зробити майже все за правильну ціну.\n\nІ що ще гірше, {ім'я}, вони влаштували собі лігво саме тут, у Випаленій ущелині. Торговець Ковіц — їхній ватажок і має тісні зв'язки з місцевими дворфами Темного Заліза.\n\nНам потрібно завдавати потужного удару і дати зрозуміти, що тут їм не раді. Вбий торговця Ковіца та його посіпаку Брязка. Принеси його торбу торговця, коли закінчиш.\n\nВирушай у Котел!", [3] = "Убийте торговця Ковіца та його посіпаку Брязка. Заберіть торбинку торговця з його трупа та принесіть її Ніліт.", [4] = "Торговець ще живий?", [5] = "Ти {стать:завдав:завдала} вирішального удару по Підпільному ринку. Тепер їхні ватажки двічі подумають, перш ніж посилати когось в ущелину.\n\nЯ оглянула торбу — у ній немає нічого корисного. Якщо тобі сподобається щось із цього барахла — можеш залишити собі.", ["en"] = "The Undermarket", ["tasks"] = { ["Clunk"] = "Брязк", ["Clunk slain"] = "Брязк: убито", ["Trade Master Kovic"] = "майстер-торговець Ковіц", ["Trade Master Kovic slain"] = "майстер-торговець Ковіц: убито", ["Trader's Satchel"] = "торба торговця", ["Trader's Satchel (Provided)"] = "торба торговця (видано)" } },
    [339] = { [1] = "Розділ I", [2] = "Розділ I був досить захопливим! Майстер Ернінґвей в передісторії згадує своїх товаришів по полюванню, серед яких був і я!\n\nАле це вже неважливо. Дозволь мені подивитися, яких сторінок ще не вистачає. Здається, сторінки 1, 4, 6 і 8 все ще десь там, у джунглях!", [3] = "Принесіть 1, 4, 6 і 8 сторінки книги Ернінґвея \"Зелені пагорби Тернистої долини\" Барнілу Камнекухлю, щоб зібрати весь перший розділ.", [4] = "Схоже, тобі ще не вдалося знайти 1, 4, 6 і 8 сторінки. Ці чотири сторінки — це все, що нам потрібно, щоб зібрати перший розділ докупи.", [5] = "Нарешті! Перший розділ завершено!", ["en"] = "Chapter I", ["tasks"] = { ["Green Hills of Stranglethorn - Page 1"] = "Зелені пагорби Тернистої долини — Сторінка 1", ["Green Hills of Stranglethorn - Page 1 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 1 (видано)", ["Green Hills of Stranglethorn - Page 4"] = "Зелені пагорби Тернистої долини — Сторінка 4", ["Green Hills of Stranglethorn - Page 4 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 4 (видано)", ["Green Hills of Stranglethorn - Page 6"] = "Зелені пагорби Тернистої долини — Сторінка 6", ["Green Hills of Stranglethorn - Page 6 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 6 (видано)", ["Green Hills of Stranglethorn - Page 8"] = "Зелені пагорби Тернистої долини — Сторінка 8", ["Green Hills of Stranglethorn - Page 8 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 8 (видано)" } },
    [340] = { [1] = "Розділ II", [2] = "Розділ II був сповнений захопливими розповідями про полювання на пантер і тигрів. Так і хочеться просто побити себе за те, що випустив сторінки з рук!\n\nЗдається, мені вдалося зібрати більшість сторінок, не вистачає тільки 10, 11, 14 і 16.", [3] = "Принесіть 10, 11, 14 і 16 сторінки книги Ернінґвея \"Зелені пагорби Тернистої долини\" Барнілу Камнекухлю, щоб зібрати весь другий розділ.", [4] = "{ім'я}, нам все ще потрібні 10, 11, 14 і 16 сторінки, щоб завершити розділ II.", [5] = "Розділ II нарешті завершено! Молодець!", ["en"] = "Chapter II", ["tasks"] = { ["Green Hills of Stranglethorn - Page 10"] = "Зелені пагорби Тернистої долини — Сторінка 10", ["Green Hills of Stranglethorn - Page 10 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 10 (видано)", ["Green Hills of Stranglethorn - Page 11"] = "Зелені пагорби Тернистої долини — Сторінка 11", ["Green Hills of Stranglethorn - Page 11 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 11 (видано)", ["Green Hills of Stranglethorn - Page 14"] = "Зелені пагорби Тернистої долини — Сторінка 14", ["Green Hills of Stranglethorn - Page 14 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 14 (видано)", ["Green Hills of Stranglethorn - Page 16"] = "Зелені пагорби Тернистої долини — Сторінка 16", ["Green Hills of Stranglethorn - Page 16 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 16 (видано)" } },
    [3401] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [3402] = { [1] = "Підпільний ринок", [2] = "Я хочу, щоб ти особисто {стать:передав:передала} новину про смерть Ковіца Швачкліцу в Пристроблях. Він буде дуже радий це почути, і я впевнена, що він щедро винагородить тебе.", [3] = "Поговоріть зі Швачкліцом у Пристроблясі.", [5] = "Ковіц здох! Ха-ха, оце так новина, {ім'я}! Роками цей негідник проводив таємні операції на підпільному ринку, завдаючи збитків чесним, працьовитим торговцям по всьому світу.\n\nТи заслуговуєш на гідну винагороду за це! І ти її отримаєш!", ["en"] = "The Undermarket" },
    [3403] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [3404] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [3405] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [341] = { [1] = "Розділ III", [2] = "Розділ III був моїм улюбленим. У ньому розповідається про перше вбивство пана Имина та леді Гіняй з дворфівської рушниці. А кінець третього розділу такий захопливий!\n\nМені здається, нам потрібні сторінки 18, 20, 21 і 24, щоб зібрати весь розділ. Ці сторінки десь там...", [3] = "Принесіть 18, 20, 21 і 24 сторінки книги Ернінґвея \"Зелені пагорби Тернистої долини\" Барнілу Камнекухлю, щоб зібрати весь третій розділ.", [4] = "Є успіхи зі сторінками 18, 20, 21 чи 24? Це єдині частини, які нам потрібні, щоб зібрати розділ ІІІ.", [5] = "Так! Гарна робота, {ім'я}. Розділ III знову зібрано в єдине ціле!", ["en"] = "Chapter III", ["tasks"] = { ["Green Hills of Stranglethorn - Page 18"] = "Зелені пагорби Тернистої долини — Сторінка 18", ["Green Hills of Stranglethorn - Page 18 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 18 (видано)", ["Green Hills of Stranglethorn - Page 20"] = "Зелені пагорби Тернистої долини — Сторінка 20", ["Green Hills of Stranglethorn - Page 20 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 20 (видано)", ["Green Hills of Stranglethorn - Page 21"] = "Зелені пагорби Тернистої долини — Сторінка 21", ["Green Hills of Stranglethorn - Page 21 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 21 (видано)", ["Green Hills of Stranglethorn - Page 24"] = "Зелені пагорби Тернистої долини — Сторінка 24", ["Green Hills of Stranglethorn - Page 24 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 24 (видано)" } },
    [342] = { [1] = "Розділ IV", [2] = "Ех, розділ IV, великий фінал! Яка ж чудова кінцівка!\n\nНам не вистачає лише трьох сторінок для цього розділу. Потрібні сторінки 25, 26 і 27, щоб зібрати розділ IV в одне ціле.", [3] = "Принесіть 25, 26 і 27 сторінки книги Ернінґвея \"Зелені пагорби Тернистої долини\" Барнілу Камнекухлю, щоб зібрати весь четвертий розділ.", [4] = "{ім'я}, нам потрібно лише три сторінки, щоб завершити розділ IV. Ти вже маєш 25, 26 або 27 сторінку?", [5] = "Чудово! Тепер Розділ IV готовий!", ["en"] = "Chapter IV", ["tasks"] = { ["Green Hills of Stranglethorn - Page 25"] = "Зелені пагорби Тернистої долини — Сторінка 25", ["Green Hills of Stranglethorn - Page 25 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 25 (видано)", ["Green Hills of Stranglethorn - Page 26"] = "Зелені пагорби Тернистої долини — Сторінка 26", ["Green Hills of Stranglethorn - Page 26 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 26 (видано)", ["Green Hills of Stranglethorn - Page 27"] = "Зелені пагорби Тернистої долини — Сторінка 27", ["Green Hills of Stranglethorn - Page 27 (Provided)"] = "Зелені пагорби Тернистої долини — Сторінка 27 (видано)" } },
    [3421] = { [1] = "Повернення", [5] = "Я поверну тебе до табору Саната.\n\nНе звертай уваги на його погані манери — він грубий з усіма, крім господаря. Можливо, колись життя навчить його...", ["en"] = "Return Trip" },
    [3422] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [3423] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [3424] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [3425] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [344] = { [1] = "Брат Пакстон", [2] = "\"Гартування заліза\"? Так, я знаю цю книгу. Досить непогана, написана дворфійським шахтарем Марґульфом Блаґґоном кілька десятиліть тому. Він багато часу провів глибоко в горах Каз-Модану, копаючи руду. Розумний тип!\n\nТо про що це я? А, так, \"Гартування заліза\"! На жаль, цю книгу перевезли до Північнокрайового абатства. Доглядач бібліотеки абатства, Брат Пакстон, хотів зробити копію книги для власної колекції.\n\nАле це було кілька місяців тому. Цікаво, чому він так довго...", [3] = "Поговоріть з братом Пакстоном в Північнокрайовому абатстві.", [5] = "Пан Сніп цікавиться, де його книга? Що ж, перепрошую за збентеження. Книга у мене, але я все ще роблю копію і ще не готовий повернути її.", ["en"] = "Brother Paxton" },
    [3441] = { [1] = "Божественна відплата", [2] = "Послухай мою історію, {стать:мандрівнику:мандрівнице}.", [3] = "Послухайте історію Веларока Вітроріза.", [4] = "Дозволь мені закінчити, см... {раса:к}.", [5] = "Тобі все зрозуміло? Ти {стать:готовий:готова} діяти?", ["en"] = "Divine Retribution", ["tasks"] = { ["Velarok Story"] = "Історія Веларока" } },
    [3442] = { [1] = "Бездоганне полум'я", [2] = "Ти {стать:прийняв:прийняла} правильне рішення, {ім'я}.\n\nМи повинні завдати удару по найвразливішому місцю — чотирьом сторожовим вежам.\n\nЯкщо ми підпалимо вежі, дворфи не встигнуть підготуватися до нашого нападу.\n\nТобі знадобиться особливий смолоскип, щоб підпалити вежі. Для його виготовлення потрібно добути деякі матеріали.\n\nПринеси мені чотири серця полум'я та чотири мастила големів, і я створю смолоскип бездоганного полум'я.\n\nДістати ці матеріали ти зможеш у тутешніх големів та елементалів.", [3] = "Зберіть 4 серця полум'я і 4 мастила големів та принесіть їх Велароку Вітрорізу.", [4] = "Ти {стать:зібрав:зібрала} матеріали?", [5] = "Добре, {ім'я}. Ми майже готові.", ["en"] = "The Flawless Flame", ["tasks"] = { ["Golem Oil"] = "мастило голема", ["Golem Oil (Provided)"] = "мастило голема (видано)", ["Heart of Flame"] = "серце полум'я", ["Heart of Flame (Provided)"] = "серце полум'я (видано)" } },
    [3443] = { [1] = "Кування держака", [2] = "Щоб тримати бездоганне полум'я, нам знадобиться держак та захист для полум'я. Спочатку потрібно знайти відповідний держак.\n\nОрударі та поневолювачі Темного Заліза з Котла використовують зброю з зачарованого торію, надзвичайно міцного сплаву. Якщо принесеш мені вісім вкритих торієм кинджалів, то я зможу виплавити торій і використати його в створенні держака.", [3] = "Принесіть 8 вкритих торієм кинджалів Велароку Вітрорізу.", [4] = "Вісім, {ім'я}. Мені потрібно вісім кинджалів!", [5] = "Чудова робота, {ім'я}. Ти не {стать:думав:думала} про зміну професії? Стати, скажімо, детективом? Чи збирати сміття? О, я знаю — долучитися до тих дурнуватих гномів, що повзають узбережжями Азерота зі своїми пристроями для виявлення металу в пошуках скарбів. Так, це була б ідеальна робота для тебе.", ["en"] = "Forging the Shaft", ["tasks"] = { ["Thorium Plated Dagger"] = "вкритий торієм кинджал", ["Thorium Plated Dagger (Provided)"] = "вкритий торієм кинджал (видано)" } },
    [3444] = { [1] = "Круглий камінь", [2] = "Одного разу я ввійшов до страшних залів Затонулого храму. Зло там проникає у всіх, хто потрапляє в це місце; мені ще пощастило знайти шлях назовні, пробираючись через слиз, що вкриває підлогу. Все, що я пам'ятаю, це як я блукав великою круглою кімнатою, яка була наповнена змієподібними статуями...\n\nНещодавно я знайшов круглий камінь, на якому, як виявилося, був викарбуваний той самий символ змії. Я відправив його до моєї майстерні в Брашпиль. Принеси його, і, можливо, я розповім тобі більше.", [3] = "Заберіть круглий камінь з майстерні Марвона Заклепника в Брашпилі.", [4] = "Брашпиль недалеко звідси, {ім'я}. Подорож не займе багато часу.", [5] = "Так... Це той самий камінь.\n\nЯ починаю пригадувати, {ім'я}...", ["en"] = "The Stone Circle", ["tasks"] = { ["Stone Circle"] = "круглий камінь", ["Stone Circle (Provided)"] = "круглий камінь (видано)" } },
    [3446] = { [1] = "В глибинах", [2] = "Всередині храму я бачив круглу кімнату з шістьма балконами, на кожному з яких стояла статуя змії. Мені було цікаво, що станеться, якщо я штовхну одну з них, але це виявилося пасткою! Я мало не розбився на смерть від вибуху. Лежачи на виступі, я подивився вниз і помітив, що в основі кімнати була ще одна статуя, сильно схожа на вівтар... Здається, це був вівтар Гаккара.\n\nЯ думаю, вівтар і є секретом — ти маєш віднести цей знак до вівтаря в Затонулий храм.", [3] = "Знайдіть вівтар Гаккара в Затонулому храмі, що на болоті Скорбот.", [4] = "Оглянувши статую, ви помічаєте заглиблення збоку, ідентичне за розміром знаку, який вам дав Марвон...", [5] = "Ви поміщаєте круглий камінь в отвір і чуєте тихе клацання.\n\nТепер, коли камінь на місці, можна продовжити... але що робити далі?\n\nМожливо, вам варто оглянути цей вівтар...", ["en"] = "Into the Depths", ["tasks"] = { ["Atal'ai Stone Circle"] = "круглий камінь Атал'ай", ["Atal'ai Stone Circle (Provided)"] = "круглий камінь Атал'ай (видано)" } },
    [3447] = { [1] = "Таємниця кола", [2] = "Мої спогади затьмарені, але я постараюсь розповісти тобі все, що пам'ятаю. Коло статуй у Затонулому храмі, хоч і небезпечне місце, але я вірю, що вони приховують таємницю, яка приведе нас до ще більшого скарбу.\n\nЗ головного вівтаря я зміг активувати низку вогнів. Думаю, якщо ти зможеш з'ясувати, що означають ці вогні, то зможеш розкрити всі таємниці, приховані в цій кімнаті.\n\nАле попереджаю тебе, {ім'я}. В храмі ховається велике зло. Цілком ймовірно, що усі цінності будуть палко охоронятися...", [3] = "Відправляйтесь в Затонулий храм та дізнайтесь, що приховано в колі статуй.", [5] = "Око ідола яскраво виблискує навіть у темряві храму. Всередині прозорого ока приховано щось блискуче. Відсунувши його вбік, ви просовуєте руку всередину статуї й берете те, що там лежить.\n\nСкарб Атал'ай тепер ваш.", ["en"] = "Secret of the Circle" },
    [3448] = { [1] = "Передача доручення", [2] = "Мені нещодавно доручили дослідити Азшару — колись прекрасний край, який ельфи називали домом. Це було ще в ті часи, коли вони практикували магію. Нині ж небезпека цього місця не поступається його красі, та не завадить нам перевернути там все догори дном, щоб дізнатись більше про наше минуле.\n\nМій супутник Тимор запропонував мені свою допомогу, адже він і сам в цьому зацікавлений.\n\nВін живе в невеличкому будиночку поруч із залом Таємниць, тут, у місті.", [3] = "Поговоріть з Тимором в Залізогарті.", [5] = "А, тебе Карник прислав, чи не так? Я саме чекав на звістку від нього. Я дізнався цікаві речі про Азшару... Я знаю, що нічні ельфи живуть неймовірно довго, та всі забувають про деякі більш... неприємні речі в їх історії. Це не образа, просто спостереження.\n\nКолись давно там стояли величні міста ельфів, сповненні знань про магію та інші давно забуті мистецтва. Оскільки я вивчаю такі речі, я розпочав свої дослідження. І я відкрив дещо приголомшливе.", ["en"] = "Passing the Burden" },
    [3449] = { [1] = "Арканічні руни", [2] = "Колись ельфи поклонялись магії не менше, ніж самій Елуні. Деякі їх могутні чаклуни створили руни та скрижалі, в яких записані таємниці аркани та їх відкриття. Зазвичай вони залишали їх на площах, де всі могли поміркувати над ними.\n\nЯ хотів би, щоб ти {стать:зробив:зробила} замальовки рун в руїнах Ельдарату. В мене є набір, з допомогою якого ти зможеш їх зробити, але знайти їх тобі доведеться самостійно. Та будь {стать:обережний:обережна}, руїни Ельдарату цікавлять не тільки Лігу дослідників.", [3] = "За допомогою набору для малювання зробіть замальовки руни Бет'Амара, рун Джин'яель, руни Маркрі та руни Сель'гай, після чого відправляйтесь на маленький острів біля південного півострова Азшари та подайте сигнал пілоту Зіґґсу Запалювачу.", [4] = "О, радий, що тобі вдалось дістатись сюди, {ім'я}. Замальовки для Тимора в тебе?\n\nХоч це й небезпечні землі, та на узбережжі зазвичай спокійно. Можливо, тому, що наги плавають під водою, та це не моє діло... Я патрулюю небо.", [5] = "Радий бачити тебе {стать:цілим і неушкодженим:цілою і неушкодженою}, {ім'я}. Сподіваюсь, це було не надто складно.\n\nЯ одразу ж доставлю їх Тимору. Він буде неймовірно радий побачити їх.\n\nБувай, і викинь вже цей сигнальний пістолет. Він тобі певно тобі все одно вже не знадобиться, а в мене вже є новий.", ["en"] = "Arcane Runes", ["tasks"] = { ["Rubbing: Rune of Beth'Amara"] = "замальовка: руна Бет'Амара", ["Rubbing: Rune of Beth'Amara (Provided)"] = "замальовка: руна Бет'Амара (видано)", ["Rubbing: Rune of Jin'yael"] = "замальовка: руна Джин'яель", ["Rubbing: Rune of Jin'yael (Provided)"] = "замальовка: руна Джин'яель (видано)", ["Rubbing: Rune of Markri"] = "замальовка: руна Маркрі", ["Rubbing: Rune of Markri (Provided)"] = "замальовка: руна Маркрі (видано)", ["Rubbing: Rune of Sael'hai"] = "замальовка: руна Сель'гай", ["Rubbing: Rune of Sael'hai (Provided)"] = "замальовка: руна Сель'гай (видано)" } },
    [3450] = { [1] = "Проста доставка", [2] = "Я хочу, щоб замальовки доставили до моєї вежі, та тобі не обов'язково самостійно йти весь цей шлях. Його доставлять з Азшари по повітрю.\n\nЗіґґс Запалювач переді мною в боргу, та й все одно скоро буде в тих краях — йому доручили патрулювати узбережжя. Поговори з ним перед тим, як відправитись туди. Він дасть тобі сигнальний пістолет, щоб ти міг подати йому сигнал. Як матимеш замальовки — просто йди в обумовлене місце і передай їх йому. Зараз він певно у Військовій палаті.", [3] = "Проворіть з Зіґґсом Запалювачем в Залізогарті.", [5] = "Чим я можу допомогти тобі, {ім'я}? Я трохи зайнятий підготовкою моєї машини до довгого польоту. Я прийшов сюди до пілотів танків, щоб взяти кілька грив вендиго для моєї кабіни.\n\nЩо ж, у мене є зайва хвилина. Один хлопак щойно пішов у Сховище Сталешквара, щоб подивитись, чи є в них кілька зайвих грив.", ["en"] = "An Easy Pickup" },
    [3451] = { [1] = "Сигнал для посадки", [2] = "А, то тебе Тимор прислав, ге? Що, борг перед ним? От же, чортяка малий. Так, я йому з цим допоможу. Тобі знадобиться сигнальний пістолет і гарне місце для посадки... це просто.\n\nБіля південного півострова Азшари є невеличкий острів, на якому ми зробили вертолітний майданчик. Візьми цей сигнальний пістолет і використай там. Я прилечу й заберу... що йому там треба.", [3] = "Поговріть з Зіґґсом Запалювачем у Залізогарті та отримайте звичайний сигнальний пістолет.", [5] = "Ось мій сигнальний пістолет. Як даси сигнал — запасись терпінням. В ньому всього пара зарядів, а мені може знадобитись кілька хвилин, щоб долетіти до тебе. Просто помилуйся морем, як вистрілиш.", ["en"] = "Signal for Pickup" },
    [3452] = { [1] = "Захист полум'я", [2] = "Нам потрібна остання річ для створення смолоскипа.\n\nНа північному заході в горах ти знайдеш великий табір Сутінкового Молота. Ходять чутки, що вони носять знаки та ідоли, що вшановують їх бога. Ці предмети можуть містити вдосталь магії для створення магічного захисту. Принеси мені один знак Раґнароса і з його магії я спробую створити такий захист для полум'я.", [3] = "Знайдіть знак Раґнароса і принесіть його Велароку Вітрорізу.", [4] = "Я не зможу закінчити смолоскип відплати без відповідного джерела магічної енергії.", [5] = "Знак випромінює нечисту магію. Це ідеально підходить для нашого завдання.", ["en"] = "The Flame's Casing", ["tasks"] = { ["Symbol of Ragnaros"] = "знак Раґнароса", ["Symbol of Ragnaros (Provided)"] = "знак Раґнароса (видано)" } },
    [3453] = { [1] = "Смолоскип відплати", [2] = "Мені потрібно трохи часу, щоб з'єднати усі частини та накласти необхідні чари.", [3] = "Зачекайте поки Веларок Вітроріз закінчить смолоскип відплати.", [4] = "Не переривай процес накладання чар.", [5] = "Є ще одне, останнє завдання, яке ти мусиш виконати.", ["en"] = "The Torch of Retribution", ["tasks"] = { ["Torch Creation"] = "Створення факела" } },
    [3454] = { [1] = "Смолоскип відплати", [2] = "Тепер смолоскип має бути прив'язаний до свого власника. Візьми його, {ім'я}.", [3] = "Візьміть смолоскип відплати.", [5] = "Ви берете факел обома руками та відчуваєте, як хвилі гніву та ненависті пульсують крізь ваші руки.", ["en"] = "The Torch of Retribution" },
    [346] = { [1] = "Повернення до Крістоффа", [2] = "Що ж, я завершив копію, ось тримай оригінал \"Гартування заліза\". Дякую тобі за терпіння, як побачишся з Мільтоном — будь ласка, передай йому мої вибачення за затримку.", [3] = "Поверніться до брата Крістоффа на Соборну площу. Віддайте йому книгу \"Гартування заліза\".", [4] = "Ти {стать:знайшов:знайшла} книгу?", [5] = "Так, це вона! Дякую тобі, {ім'я}. Нехай Світло береже тебе!", ["en"] = "Return to Kristoff", ["tasks"] = { ["Book: Stresses of Iron"] = "книга \"Гартування заліза\"", ["Book: Stresses of Iron (Provided)"] = "книга \"Гартування заліза\" (видано)" } },
    [3461] = { [1] = "Повернення до Тимора", [2] = "Тимор не дав мені винагороду для тебе, тож тобі доведеться {стать:самому:самій} обговорити це з ним в Залізогарті. Скоріш за все він у себе в Таємній палаті. Йди до нього і вимагай гідну оплату. Місце тут не курортне, це точно.\n\nІ все ж дякую за допомогу і нехай тобі щастить.\n\nА, ні, мені не потрібен набір для малювання. Віддай йому Тимору, як побачишся з ним.", [3] = "Поверніть набір для малювання Тимору в Залізогарт.", [4] = "Ти {стать:повернувся:повернулась}! Чудово. Мій набір для малювання в тебе?", [5] = "Чудово! Радий це чути.\n\nМені вже не терпиться повернутись до моєї вежі та попрацювати над цими замальовками. Я так заздрю тобі... побувати в Азшарі. Певно, це мрія всіх дослідників магії.\n\nЩо ж, хоч ми й не домовлялись про винагороду, адже це послуга для Ліги дослідників, та ти заслуговуєш на неї.", ["en"] = "Return to Tymor", ["tasks"] = { ["Drawing Kit"] = "набір для малювання", ["Drawing Kit (Provided)"] = "набір для малювання (видано)" } },
    [3462] = { [1] = "Зброєносець Малтрейк", [2] = "Поговори з моїм посланцем, зброєносцем Малтрейком. Він пояснить тобі, як потрібно використовувати смолоскип відплати.", [3] = "Поговоріть зі зброєносцем Малтрейком.", [5] = "Ти {стать:готовий:готова} завдати удару?", ["en"] = "Squire Maltrake" },
    [3463] = { [1] = "Задай їм жару!", [2] = "Слухай уважно, {ім'я}. Хоча чотири вежі неможливо знищити, за допомогою смолоскипа відплати ти зможеш підпалити їх на дуже довгий час — вогнем, який жодна стихія чи сила не зможе загасити.\n\nПоки вежі горять, жоден вартовий чи караульний не зможе піднятися на них — а отже, першу лінію оборони противника фактично буде прорвано.\n\nТобі потрібно потрапити в кожну вежу та використати смолоскип відплати всередині. Остерігайся караульних Темного Заліза, {ім'я}.", [3] = "Підпаліть північну, південну, східну та західну сторожові вежі, використовуючи смолоскип відплати всередині кожної з веж.", [4] = "Ти {стать:заблукав:заблукала}, {ім'я}?", [5] = "Чудово! Хіба це не славно, господарю?", ["en"] = "Set Them Ablaze!", ["tasks"] = { ["Eastern Tower Ablaze"] = "Східна вежа у палаючому стані", ["Eastern Tower Ablaze (Provided)"] = "Східна вежа у палаючому стані (видано)", ["Eastern Tower Ablaze slain"] = "Східна вежа у палаючому стані: убито", ["Northern Tower Ablaze"] = "Північна вежа у палаючому стані", ["Northern Tower Ablaze (Provided)"] = "Північна вежа у палаючому стані (видано)", ["Northern Tower Ablaze slain"] = "Північна вежа у палаючому стані: убито", ["Southern Tower Ablaze"] = "Південна вежа в палаючому стані", ["Southern Tower Ablaze (Provided)"] = "Південна вежа в палаючому стані (видано)", ["Southern Tower Ablaze slain"] = "Південна вежа в палаючому стані: убито", ["Western Tower Ablaze"] = "Західна вежа у палаючому стані", ["Western Tower Ablaze (Provided)"] = "Західна вежа у палаючому стані (видано)", ["Western Tower Ablaze slain"] = "Західна вежа у палаючому стані: убито" } },
    [348] = { [1] = "Лихоманка Тернистої долини", [2] = "Я хворий... так... дуже х-х-хворий...\n\n...підхопив лихоманку Тернистої долини... смертельний в-в-вірус...\n\nЄдиний спосіб вилікуватися — з'їсти серце М-м-м-м-мокка Лютого... невловного білого звіра...\n\n...знахар Унбаґва... єдиний, хто може викликати його...\n\n...шукай Унбаґву в прихованій печері на південному мисі...\n\n...поспіши... вмираю... вмираю...", [3] = "Знайдіть знахаря Унбаґву і попросіть його викликати Мокка Лютого. Принесіть серце Мокка до Фіна Шипокрута.", [4] = "...мамо?\n\n...так холодно...\n\n...прямую в Підсвітню Крутоверть... т-т-т-тримай мене, мамо....", [5] = "...відчуваю, як повертаються сили....\n\nДе це я? У Грабіжній Бухті? О, Боже! Мені наснився дивний сон.\n\n...але я все ще відчуваю слабкість.", ["en"] = "Stranglethorn Fever", ["tasks"] = { ["Heart of Mokk"] = "серце Мокка", ["Heart of Mokk (Provided)"] = "серце Мокка (видано)" } },
    [3481] = { [1] = "Дрібнички...", [2] = "Скриня здається замкненою.", [3] = "Відчиніть скриню.", [5] = "Скриня відкривається щойно ви торкаєтеся її. Скільки тут може бути скарбів? Є лише один спосіб це з'ясувати.", ["en"] = "Trinkets..." },
    [3482] = { [1] = "<NYI> <TXT> Чорна скринька з кистями", [2] = "Це версія квесту \"Чорна скринька\" для Орди.", ["en"] = "<NYI> <TXT> The Pocked Black Box", ["tasks"] = { ["Pocked Black Box"] = "Кишенькова чорна скринька", ["Pocked Black Box (Provided)"] = "Кишенькова чорна скринька (видано)" } },
    [3483] = { [1] = "Сигнал для посадки", [5] = "А, ще один сигнальний пістолет? Так, без проблем.\n\nІ не забудь — південний мис Азшари. Там маленький острів, на якому обладнаний вертолітний майданчик. Ти його не пропустиш, якщо будеш в правильному місці.", ["en"] = "Signal for Pickup" },
    [349] = { [1] = "Лихоманка Тернистої долини", [2] = "тимчасовий текст 02 — опис", [3] = "тимчасовий текст 02 — журнал", [4] = "Знахар Унбаґва знати, хто такий Мокк Лютий. Так, так!\n\nМоя розмовляти з духами та змушувати їх прийти, так.\n\nАле інші горили також люблять коли духи говорять. Захисти знахаря Унбаґву, а моя змусити його прийти до тебе.\n\nАле спочатку знахарю Унбаґві дещо потрібно. Твоя принести 10 ікл горили і моя почати говорити з духами!", [5] = "Знахар Унбаґва любить ікла горили! Моя говорити з духами для тебе. Нехай прийде Мокк Лютий.\n\nТвоя захищати знахаря Унбаґву від інших звірів-горил, або Мокк не прийти!", ["en"] = "Stranglethorn Fever", ["tasks"] = { ["Gorilla Fang"] = "ікло горили", ["Gorilla Fang (Provided)"] = "ікло горили (видано)" } },
    [3501] = { [1] = "Кількість, а не якість", [2] = "Можливо, ти ніколи не знайдеш бездоганну сферу з дренетисту, але тобі можуть трапитись фрагменти.\n\nХоча навряд чи Кум'іша зможе використати їх для повернення додому, вони можуть знадобитись для інших, корисних для дренеїв, цілей.\n\nПринось будь-які фрагменти дренетисту, що трапляться тобі в мандрах і я винагороджу тебе.", [3] = "Принесіть недосконалі фрагменти дренетисту Кум'іші та отримайте винагороду за кожен з них.", [4] = "Є успіхи в пошуках?", [5] = "Ти розчаровуєш мене, {раса:к}. {стать:Такий дорослий:Така доросла}, а пускає слину над купою мотлоху. Жалюгідно! Забирай свою нагороду і забирайся геть з моїх очей.", ["en"] = "Everything Counts In Large Amounts", ["tasks"] = { ["Imperfect Draenethyst Fragment"] = "недосконалий фрагмент дренетисту", ["Imperfect Draenethyst Fragment (Provided)"] = "недосконалий фрагмент дренетисту (видано)" } },
    [3502] = { [1] = "Мотлох дренея...", [2] = "Що ж, від такого прояву жадібності, я ледь стримую огиду.\n\nОднак, я не збираюся довго затримуватися на твоїй матеріальній залежності.\n\nЗа кожен недосконалий фрагмент дренетисту, що ти мені принесеш, я винагороджу тебе ще яким-небудь мотлохом. Моя купа мотлоху зменшуватиметься, а твоя — збільшуватиметься. На Дренорі ми називаємо це взаємовигідним обміном.", [3] = "Принесіть Кум'іші недосконалі фрагменти дренетисту. Їх можна знайти у будь-яких створінь Спустошених земель.", [4] = "Ну? Дренетист? Пам'ятаєш?\n\n<Кум'іша стискає кулак і стукає по вашій голові.>\n\nЄ хто вдома?", [5] = "Ти розчаровуєш мене, {раса:к}. {стать:Такий дорослий:Така доросла}, а пускає слину над купою мотлоху. Жалюгідно! Забирай свою нагороду і забирайся геть з моїх очей.\n\nЗнайомо звучить? Звичайно, я кажу це тисячу разів на день.\n\nОх, як я ненавиджу цей світ.", ["en"] = "One Draenei's Junk...", ["tasks"] = { ["Imperfect Draenethyst Fragment"] = "недосконалий фрагмент дренетисту", ["Imperfect Draenethyst Fragment (Provided)"] = "недосконалий фрагмент дренетисту (видано)" } },
    [3503] = { [1] = "Зустріч з господарем", [5] = "Колись я міг вимагати з охочих бачити мого господаря все, що заманеться. Тепер я відправляю до нього будь-кого — тільки попроси!\n\nЦе засмучує мене, але накази не обговорюються. Я можу потішити себе лише знущаючись з твого одягу і жалюгідного виразу обличчя. Втім, мені й це вже набридло...\n\nНавіть від цієї розмови мене нудить! Ти хочеш побачити мого господаря, чи ні?", ["en"] = "Meeting with the Master" },
    [3508] = { [1] = "Розбити закляття", [2] = "Ти дуже {стать:безрозсудний:безрозсудна}, {ім'я}. Це цінна риса твого виду — сліпо вступати в битву, майже не маючи шансів на успіх. Я допоможу тобі хоча б заради того, щоб побачити смерть поплічників Разеліха.\n\nДля того, щоб зламати захисне закляття, що оточує їх, потрібен час і рідкісні артефакти.\n\nЗачекай, спочатку я маю здійснити ритуал просвітлення. Інформація, яку я зберу, допоможе мені створити могутню зброю.", [3] = "Зачекайте, поки Лорам завершить заклинання просвітлення.", [5] = "Необхідно відшукати ім'я звіра.", ["en"] = "Breaking the Ward" },
    [3509] = { [1] = "Ім'я чудовиська", [2] = "Є тільки один спосіб завдати шкоди лорду демонів та його послідовникам. Потрібно створити могутню зброю, на якій буде написано його справжнє ім'я.\n\nКоли така зброя буде створена, демон і всі, хто перебуває під його контролем, стануть вразливими.\n\nВ Азшарі мешкає менше божество — лорд Арккорок. Тобі потрібно знайти його, але будь {стать:обережним:обережною}, його послідовники не зупиняться ні перед чим, щоб знищити тебе.\n\nБезсумнівно, за таку інформацію тобі доведеться заплатити ціну.", [3] = "Поговоріть з лордом Арккороком в Азшарі. Щоб знайти храм Арккорана, почніть пошуки неподалік води.", [5] = "Лорд демонів?\n\n<Лорд Арккорок сміється.>\n\nМожливо, дехто зможе допомогти тобі з цією інформацією; але спочатку ти маєш допомогти цьому декому.", ["en"] = "The Name of the Beast" },
    [351] = { [1] = "Знайти OOX-17/ТН!", [2] = "Ви виявили дивний яйцеподібний металевий пристрій. Покрутивши одну з його ручок, ви пробуджуєте яйце, і воно відкриває якийсь пристрій гномів! Зсередини лунає голос.\n\n\"Мене звати Оґлторп, і мій автономний робот зник! Я винагороджу тебе, якщо знайдеш його! Будь ласка, віднеси цей маяк до робота. Чудово, я вже вирахував координати! Він зламався поблизу Зяючого провалля в Танарісі!\"", [3] = "Принесіть аварійний маяк до автономного робота Оґлторпа.", [4] = "Здається, ви знайшли уламки... механічної курки? З яйця знову лунає голос:\n\n\"Так, чудова робота! Це дійсно мій автономний робот, але мої дані показують, що йому потрібен заряд енергії, щоб він зміг повернутись до Грабіжної Бухти на ремонт. Для початку помісти маяк всередину апарата. А решту він зробить сам!\"", [5] = "Ви помістили яйце... аварійний маяк... в середину курки... автономного робота.\n\nЗсередини робота лунає гудіння та дзижчання — він намагається встати. Коли робот оживає, зсередини долинає голос Оґлторпа:\n\n\"Принаймні, OOX-17/ТН працює, але йому потрібен капітальний ремонт! Він надто важкий для того, щоб ти {стать:зміг:змогла} нести його... але у мене є ідея. Хочеш трохи доглянути за ним?\"", ["en"] = "Find OOX-17/TN!", ["tasks"] = { ["OOX-17/TN Distress Beacon"] = "аварійний маяк OOX-17/ТН", ["OOX-17/TN Distress Beacon (Provided)"] = "аварійний маяк OOX-17/ТН (видано)" } },
    [3510] = { [1] = "Ім'я чудовиська", [2] = "Вона вбиває моїх дітей, {стать:смертний:смертна}. Та, що називає себе володаркою цих океанів. Фальшиве божество, не більше. Знищ її та принеси мені всі її голови.\n\nЗа це ти отримаєш ім'я, яке хочеш дізнатися, та ще щось не менш важливе.\n\nВона блукає навколо гнізда... Її звуть - Гетаєра.\n\n<Лорд Арккорок показує на південний захід.>\n\nЙди!", [3] = "Убийте Гетаєру і поверніть закривавлену голову Гетаєри, побиту голову Гетаєри та розбиту голову Гетаєри лорду Арккороку.", [4] = "<Лорд Арккорок нахиляється, щоб оглянути вас.>\n\nДе вони?", [5] = "Нарешті, хтось гідний мудрості Арккорока!", ["en"] = "The Name of the Beast", ["tasks"] = { ["Hetaera's Beaten Head"] = "побита голова Гетаєри", ["Hetaera's Beaten Head (Provided)"] = "побита голова Гетаєри (видано)", ["Hetaera's Bloodied Head"] = "закривавлена голова Гетаєри", ["Hetaera's Bloodied Head (Provided)"] = "закривавлена голова Гетаєри (видано)", ["Hetaera's Bruised Head"] = "розбита голова Гетаєри", ["Hetaera's Bruised Head (Provided)"] = "розбита голова Гетаєри (видано)" } },
    [3511] = { [1] = "Ім'я чудовиська", [2] = "Як і обіцяв, я розкрию ім'я лорда демонів — Разеліха-Губителя. Проте спочатку мені потрібно підготувати щось надзвичайно важливе для твоєї подорожі.\n\nЗброю, яку ти прагнеш створити, потрібно буде загартувати. Дай мені хвилину, щоб вичавити кров з цих голів.\n\n<Лорд Арккорок стискає голови великими кулаками, вичавлюючи з них кров.>\n\nВіднеси кров Лораму разом з ім'ям чудовиська: Рах'ліх.", [3] = "Принесіть кров Лораму Таліпедесу.", [4] = "Ти {стать:повернувся:повернулася}! Дивовижно, {раса:к}. Ти {стать:дізнався:дізналася} його справжнє ім'я?", [5] = "Ця кров містить необхідні для гартування зброї кислоти. Залишився лише один крок до її створення.", ["en"] = "The Name of the Beast", ["tasks"] = { ["Hetaera's Blood"] = "кров Гетаєри", ["Hetaera's Blood (Provided)"] = "кров Гетаєри (видано)" } },
    [3512] = { [1] = "За словами Ераніка", [2] = "{Ім'я}, нашим першим кроком буде пошук засобу зв'язку з Ераніком через цей камінь. Зараз він перебуває у хиткому стані на межі між сном і смертю, витаючи в переплетінні нічних жахів. Хоча принесена тобою сутність сильно вражена скверною, все ще є шанс, що ми дістанемося його.\n\nВідправляйся далеко до крижаних земель на сході Зимоключа, та розшукай нашого смертного союзника, Умбранса Маромовця. Це людина, медіум, що говорить з мертвими. Хоча Еранік не зовсім мертвий, він все ж може нам допомогти.", [3] = "Відправляйтесь у східну частину Зимоключа і поговоріть з Умбрансом Маромовцем.", [5] = "Ітарій вчинив мудро відправивши тебе до мене. Поки він не мертвий, в тому сенсі, як ти розумієш смерть, Еранік скоро зможе говорити з нами. Але зараз я не можу допомогти тобі... принаймні, поки що.\n\nЯ допоможу тобі, але спочатку мені потрібна допомога того, хто, на відміну від мене, не скутий старечою неміччю. Мій найпотужніший прилад для ворожіння було відібрано проти моєї волі й поки я не поверну його, ми безсилі допомогти Ераніку.", ["en"] = "In Eranikus' Own Words" },
    [3515] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [3519] = { [1] = "Друг у біді", [2] = "У-у-ух... Мене дуже сильно вкусила павучиха Ґітісс Мерзенна, поки я оглядав павучу печеру тут неподалік. Я певно серйозно отруєний, ти маєш мені допомогти!\n\nБудь ласка, розкажи все Діраньї Срібносяй, вона зможе мені зарадити.\n\nПоспішай... У мене так паморочиться у голові...", [3] = "Поговоріть з Діраньєю Срібносяй у Тінистій долині.", [5] = "Ой лишенько, а я гадала, чому я ще не бачила Іверрона сьогодні. І я ж завжди застерігала його про цих павуків...", ["en"] = "A Friend in Need" },
    [352] = { [1] = "<UNUSED>", [2] = "Велика Маммода. Величезна, вона була, з кігтями та зубами, як мечі. Я був заскочений зненацька, але не думаю, що готовність дуже допомогла б моїй справі. Один удар і пуф! Темрява. Кажуть, мені пощастило тепер ходити...\n\nНу, не дуже приємно слухати цю стару історію, чи не так? У будь-якому разі, {ім'я}, якщо ви хочете спробувати себе проти неї, Володарки Озера,", ["en"] = "<UNUSED>" },
    [3520] = { [1] = "Духи верескунів", [2] = "Я шукаю духів долинних верескунів Фераласу. Вони є родичами одного дуже стародавнього бога, і їхні духи пов'язані з ним.\n\nВізьми цей жезл і вирушай до Фераласу. Знайди та переможи долинних верескунів в південному та центральному Фераласі і помахай моїм жезлом над їхніми тілами. Таким чином ти виманиш їхні душі. Торкнися кожної з душ і збери їх сутності.\n\nПовернись до мене з моїм жезлом та зібраними душами, і я розкажу тобі більше про того стародавнього бога, про якого я говорив.", [3] = "Захопіть 3 духів верескунів у Фераласі, а потім поверніться до Є'кіньї в порт Паровиманювання.", [4] = "Ти {стать:зібрав:зібрала} душі верескунів, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Можливо, час відкрити тобі більше...\n\nСеред тролів існує стародавнє пророцтво, згідно з яким мертвий бог Гаккар, Здирач Душ, одного дня повернеться на цю землю. Одні кажуть, що прихід Гаккара принесе радість і славу роду тролів, а інші вважають, що його воскресіння знаменує кінець усього сущого.\n\nЯ не вірю в цей міф, але я знаю, що сутність Гаккара містить велику силу, і цю силу слід берегти від тих, хто хотів би нею зловживати...", ["en"] = "Screecher Spirits", ["tasks"] = { ["Screecher Spirits Collected"] = "Зібрані духи-крикуни", ["Screecher Spirits Collected (Provided)"] = "Зібрані духи-крикуни (видано)", ["Screecher Spirits Collected slain"] = "Зібрані духи-крикуни: убито", ["Yeh'kinya's Bramble"] = "жезл Є'кіньї", ["Yeh'kinya's Bramble (Provided)"] = "жезл Є'кіньї (видано)" } },
    [3521] = { [1] = "Іверронова протиотрута", [2] = "Можливо, нам вдасться допомогти Іверронові, оскільки я знаю протиотруту, яка повинна б зарадити. Проте мені потрібні деякі інгредієнти, щоб я почала її готувати.\n\nМені знадобляться гіацинтові гриби. Ти можеш знайти їх під деревами або забрати у грелів на південь звідси. Схоже, гриби їм сподобалися. Мені також потрібні місяцепелюсткові лілеї, які ростуть лише навколо водойм.\n\nА ось останній інгредіент, мабуть, буде найважче дістати. Збери сукровицю у павутиннолісих, тих самих павуків, що отруїли Іверрона.", [3] = "Зберіть 7 гіацинтових грибів, 4 місяцепелюсткові лілеї й 1 сукровицю павутиннолісих для Діраньї Срібносяй у Тінистій долині.", [4] = "Будь ласка, збери інгредієнти, {Ім'я}. Іверрону потрібна наша допомога.", [5] = "Хвала Елуні, ти {стать:зібрав:зібрала} ці інгредієнти справді швидко!\n\nЯ приготую протиотруту вже за мить.", ["en"] = "Iverron's Antidote", ["tasks"] = { ["Hyacinth Mushroom"] = "гіацинтовий гриб", ["Hyacinth Mushroom (Provided)"] = "гіацинтовий гриб (видано)", ["Moonpetal Lily"] = "місяцепелюсткова лілея", ["Moonpetal Lily (Provided)"] = "місяцепелюсткова лілея (видано)", ["Webwood Ichor"] = "сукровиця павутиннолісих", ["Webwood Ichor (Provided)"] = "сукровиця павутиннолісих (видано)" } },
    [3522] = { [1] = "Іверронова протиотрута", [2] = "Протиотрута готова, {Ім'я}. Будь ласка, переконайся, що Іверрон її вип'є.\n\nТакож тобі варто дещо знати. Протиотрута буде дієвою лише протягом 5 хвилин, тому ти {стать:повинен:повинна} принести її Іверронові вчасно.\n\nШвидкої тобі дороги, {клас:к}.", [3] = "Принесіть Іверронову протиотруту Іверрону до того, як спливе час. Ви зможете знайти Іверрона біля печери на півночі.", [4] = "Ох... {Ім'я}, який я радий, що ти {стать:повернувся:повернулася}.", [5] = "А це що, {Ім'я}?\n\nА-а, я знав, що Діранья зможе мені допомогти!\n\nЯ завжди втрапляю в якусь халепу, а Діранья, ну, їй завжди вдається допомогти мені виплутатись.\n\nМені значно краще, але я все ж посиджу тут ще трохи, доки не почуватимуся зовсім добре. І ще, якщо чесно, я сподівався, що ти {стать:зміг би:змогла б} розчистити мені шлях крізь цих лісопавутинних павуків...", ["en"] = "Iverron's Antidote", ["tasks"] = { ["Iverron's Antidote"] = "Іверронова протиотрута", ["Iverron's Antidote (Provided)"] = "Іверронова протиотрута (видано)" } },
    [3523] = { [1] = "Скара в норах", [2] = "Неймовірно! Мене звати Белністраз і я дуже вдячний вам за порятунок. Я вже був готовий померти... чи гірше — стати кормом для цих потвор Скари. Так-так, Скара, все правильно. Тутешні свинобрази з нею об'єднались і це просто жах.\n\nСлухайте... Замість того, щоб тікати — ми маємо битись зі Скарою, заради нашого ж спільного майбутнього. Допоможете мені? Може бути небезпечно, та схоже, що вас це не лякає.", [3] = "Якщо ви згодні допомогти Белністразу, поговоріть з ним знову і віддайте клятвокамінь.", [4] = "Мене не турбує політика. І мені однаково, чи ти з Орди, чи з Альянсу. Я переймаюсь тим, що загрожує всім расам цього світу. І в цих норах загроза ця не мала.\n\nЯкщо хочете стати героями цього світу — віддайте мені клятвокамінь в знак згоди. Я не місцевий, для мого виду ці камені — важлива традиція при скріпленні угоди.", [5] = "Чудово, я знав, що вам буде цікаво! Скажу чесно, {ім'я}, нас чекає непроста робота. Але якщо ми залучимо всі зусилля — у нас все вийде.\n\nА тепер я розкажу про це більше...", ["en"] = "Scourge of the Downs", ["tasks"] = { ["Belnistrasz's Oathstone"] = "клятвокамінь Белністраза", ["Belnistrasz's Oathstone (Provided)"] = "клятвокамінь Белністраза (видано)" } },
    [3524] = { [1] = "Викинуті на берег", [2] = "Величні морські істоти викидаються на узбережжя Темнобережжя і залишаються там, поки не помруть. Останнім часом ці створіння дедалі частіше викидаються на берег. Мене направив сюди храм Місяця, щоб дослідити це, але присутність мурлоків на узбережжі ускладнює моє завдання.\n\nНа південь від Аубердіну на берег викинуло гігантську істоту і її оточили бридкі сіромлисті мурлоки. Чи не {стать:міг би:могла б} ти піти туди та добути кістки цієї істоти для нашого дослідження?", [3] = "Добудьте кістки морської істоти, викинутої на берег на південь від Аубердіну і поверніться з ними до Ґвенніт Блі'Леґґонд в Аубердін.", [4] = "Ці істоти лише нещодавно почали викидатись на берег Темнобережжя в такій тривожній кількості. Не можу сказати точно, але думаю, що це поганий знак. Дослідження кісток цієї істоти, що лежить на півдні, допомогло б нам у Дарнасі краще оцінити ситуацію!", [5] = "Сподіваюся, мурлоки не принесли тобі багато клопоту, поки ти {стать:збирав:збирала} для нас кістки! Я неодмінно доставлю їх наступним гіпогрифом до Дарнасу. Храм Місяця виділив мені трохи коштів на це дослідження. Прошу, прийми їх в знак нашої вдячності.\n\nТвій успіх спонукає мене запропонувати тобі надавати допомогу храму Місяця й надалі, якщо тобі, звісно, цікаво...", ["en"] = "Washed Ashore", ["tasks"] = { ["Sea Creature Bones"] = "кістки морської істоти", ["Sea Creature Bones (Provided)"] = "кістки морської істоти (видано)" } },
    [3525] = { [1] = "Знищення ідола", [2] = "Неподалік входу стоїть ідол, що свинобрази використовують як жертовне вогнище. Ці мерзоти буквально поїдають своїх полонених зі Степів. Я можу знешкодити ідол, щоб вони не могли його використовувати. Та мені знадобиться допомога. Допоможіть мені дійти до ідола і я зможу провести ритуал. Під час нього я не зможу навіть говорити з вами, а тим паче захищати себе, тож це я покладаю на вас. Якщо я загину — ми приречені.\n\nВи зі мною?", [3] = "Супроводіть Белністраза до ідола свинобразів в норах Бритвоболотих.\n\nЗахищайте Белністраза, поки він виконує ритуал знешкодження ідола.", [5] = "Белністраз зникає, залишивши по собі вогнище. Ви вдивляєтесь в полум'я, і бачите образ великого червоного дракона. Ваш розум наповнює грубий голос Белністраза.\n\n\"Дійсно, смертні, ваш героїзм виправдав всі мої очікування. Завдяки вам з усім, що затіяли тутешні звірі, покінчено, а моя віра в смертних створінь знову відновлена. Прийміть цю гідну винагороду.\"", ["en"] = "Extinguishing the Idol", ["tasks"] = { ["Protect Belnistrasz while he performs the ritual to shut down the idol"] = "Захистіть Белністраза, поки він виконує ритуал вимкнення ідола" } },
    [3527] = { [1] = "Пророцтво Мош'ару", [2] = "Стародавнє пророцтво Мош'ару говорить як захопити сутність бога Гаккара. Його написали на двох скрижалях і віднесли в місто тролів — Зул'Фаррак, що на захід від Пристробляха.\n\nПринеси мені скрижалі Мош'ару!\n\nПерша скрижаль — у давно покійного троля, Теки-Мученика. Кажуть, що його катівники перетворились в скарабеїв і тепер повзають по його святині.\n\nДруга скрижаль у гідроманта Велрати, біля священного басейну Газ'рілли.\n\nКоли добудеш скрижалі, принеси їх мені.", [3] = "Принесіть першу та другу скрижалі Мош'ару до Є'кіньї в Танаріс.", [4] = "Ти {стать:дістав:дістала} скрижалі пророцтва Мош'ару, {ім'я}?\n\nКоли у мене будуть скрижалі, я досліджу їх і дізнаюся, як утримувати сутність Гаккара!", [5] = "Добре. Тепер я можу об'єднати ці скрижалі та дізнатися приховані таємниці.\n\nЯ вже давно твій боржник, {ім'я}. Та стану ще більшим боржником.", ["en"] = "The Prophecy of Mosh'aru", ["tasks"] = { ["First Mosh'aru Tablet"] = "перша скрижаль Мош'ару", ["First Mosh'aru Tablet (Provided)"] = "перша скрижаль Мош'ару (видано)", ["Second Mosh'aru Tablet"] = "друга скрижаль Мош'ару", ["Second Mosh'aru Tablet (Provided)"] = "друга скрижаль Мош'ару (видано)" } },
    [3528] = { [1] = "Бог Гаккар", [2] = "Настав час ув'язнити сутність аватара Гаккара.\n\nВіднеси яйце Гаккара у святилище Занепалого Бога, що в Затонулому храмі Азероту. Скористайся силою яйця, щоб розбудити мертвого бога.\n\nВін відправить проти тебе своїх підлеглих. Розгроми цих кровопивць, збери їхню гаккарську кров та використай її, щоб загасити вічний вогонь, в якому ув'язнений дух Гаккара. Коли полум'я погасне, в наш світ увійде аватар Гаккара.\n\nЗдолай його і помісти його сутність в яйце Гаккара.", [3] = "Принесіть наповнене яйце Гаккара Є'кіньї в Танаріс.", [4] = "Ти {стать:здолав:здолала} аватар Гаккара, {ім'я}? Його сутність вже ув'язнена у яйці, яке я тобі дав?", [5] = "Сутність Гаккара ув'язнена в яйці! Навіть зараз в ньому вирує життя! Невже міфи про Гаккара — правда?\n\nЦе не може бути правдою, якщо Гаккар народиться знову, я боюсь навіть уявити, що він може наробити. Я зберігатиму це яйце, щоб воно не потрапило в недобрі руки.\n\nНаша співпраця завершена, {ім'я}. Ти {стать:доторкнувся:доторкнулася} до легенди. Можливо, колись твої діяння змінять наш світ.", ["en"] = "The God Hakkar", ["tasks"] = { ["Filled Egg of Hakkar"] = "наповнене яйце Гаккара", ["Filled Egg of Hakkar (Provided)"] = "наповнене яйце Гаккара (видано)" } },
    [3529] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [3562] = { [1] = "Плата Маґати Джедідзі", [2] = "Віднеси цю записку Джедідзі. Скажи їй, що оплата буде чекати на неї тут. І скажи, що я задоволена її роботою.\n\nІди скоріше, {ім'я}. Скажи своїй господарці, що я чекатиму на неї.", [3] = "Передайте записку Маґати Джедідзі в Азшарі.", [4] = "Що сказала Маґата? Стара відьма... Б'юся об заклад, вона була не надто ввічлива.", [5] = "Добре. Вона виявилася набагато розсудливішою, ніж я очікувала... принаймні щодо тебе. Я думала, що вона покарає тебе за мою зухвалість послати когось замість мене. Мабуть, вона дуже хотіла ту скрижаль. Цікаво.\n\nЄ над чим поміркувати.", ["en"] = "Magatha's Payment to Jediga", ["tasks"] = { ["Magatha's Note"] = "записка Маґати", ["Magatha's Note (Provided)"] = "записка Маґати (видано)" } },
    [3564] = { [1] = "Плата Андрона Джедідзі", [2] = "Ось... віднеси це... <гик> Джедідзі. Хай щастить!", [3] = "Передайте записку Андрона Джедідзі в Азшарі.", [4] = "Ти вже {стать:говорив:говорила} з Андроном? Він рідко покидає Підмістя, тож не думаю, що його буде важко знайти.", [5] = "Чудово... зачекай хвилинку.\n\nХа-ха! Що ти {стать:сказав:сказала} йому, коли {стать:приніс:принесла} скрижаль, {ім'я}? Він переплатив нам надто багато! Не те щоб я скаржилася. Ти {стать:сказав:сказала} йому, що умови змінилися? Чи він знову був п'яний?\n\nНеважливо... Ось, візьми ще частку.", ["en"] = "Andron's Payment to Jediga", ["tasks"] = { ["Andron's Note"] = "записка Андрона", ["Andron's Note (Provided)"] = "записка Андрона (видано)" } },
    [3566] = { [1] = "Повстань, Обсидіон!", [2] = "Це... Це була... пастка.\n\nПробач... мені.\n\nВбий цього покидька... Заради нас... Заради Торія.", [3] = "Вбийте Латорика Чорного та Обсидіона і поверніться до Торія в Залізогарт з головою Латорика Чорного та серцем Обсидіона.", [4] = "Не можу повірити! У тебе є докази?", [5] = "<Торій блідніє.>\n\nЦього... не може бути. Мій рідний брат? Це все його робота?\n\n<Обличчя Торія сповнюється гнівом.>\n\nВін зрадив мене, він зрадив Залізогарт! Здається, наші землі все ще знаходяться під сильним впливом Старих Богів. Якщо мого брата — колись благородного і чесного — так легко підкорили волі Рагнароса, боюсь, що ми всі в небезпеці.", ["en"] = "Rise, Obsidion!", ["tasks"] = { ["Head of Lathoric the Black"] = "голова Латорика Чорного", ["Head of Lathoric the Black (Provided)"] = "голова Латорика Чорного (видано)", ["Heart of Obsidion"] = "серце Обсидіона", ["Heart of Obsidion (Provided)"] = "серце Обсидіона (видано)" } },
    [3567] = { [1] = "Нагору", [5] = "Хочеш побачити вид з вершини Колосів-Близнюків? Я можу відправити тебе туди, {раса:к}.\n\nАле подумай, як ти будеш спускатися. Це шлях в один кінець.", ["en"] = "To the Top" },
    [3568] = { [1] = "Повзуче загнивання", [2] = "Бачиш ту тауренку позаду мене — цю, яка виглядає так, ніби будь-якої миті її може вивернути? Нещодавно вона була в Азшарі. Вона стверджує, що її поранили якісь наги, коли вона проходила через руїни Ельдарата.\n\nКоли вона відбилася від кількох з них, то перепочивала на пляжі та випила води з однієї з прибережних калюж. Тепер її нудить... і не тільки.\n\nЯ б хотів дізнатися, що вона випила. Візьми цю коробку, в ній — порожні фіали, які я промаркував. Наповни кожен з різної калюжі та повертайся назад.", [3] = "Заповніть 4 порожні фіали з прибережних калюж вздовж берегу біля руїн Ельдарата в Азшарі, після чого поверніться до хіміка К'юлі.", [4] = "Ти ж розумієш, що це означає, чи не так, {Ім'я}? У неї немає шансів вижити... подивися на неї. Найкраще, що вона може тепер зробити, це допомогти нам знайти ліки проти чуми. Ця вода, яку вона випила, може підказати нам, як це зробити. Ця тауренка все одно помре, тож вона може померти й роблячи щось благородне для нашого народу. {Стать:Згоден:Згодна}?", [5] = "Чудесно. Ти {стать:встиг:встигла} повернутись, поки вона не померла. Гаразд-гаразд.\n\nТож чому б нам не розпочати?\n\nЯ вивчав її симптоми вже протягом деякого часу, і все досить кепсько. Здивований, що вона досі стоїть. Вона вже три чи чотири рази повсюди блювала... такий приємний запашок.\n\nПочекай хвильку, і я збовтаю дещо, щоб випробувати на нашій... подрузі.", ["en"] = "Seeping Corruption", ["tasks"] = { ["Filled Vial Labeled #1"] = "наповнений фіал №1", ["Filled Vial Labeled #1 (Provided)"] = "наповнений фіал №1 (видано)", ["Filled Vial Labeled #2"] = "наповнений фіал №2", ["Filled Vial Labeled #2 (Provided)"] = "наповнений фіал №2 (видано)", ["Filled Vial Labeled #3"] = "наповнений фіал №3", ["Filled Vial Labeled #3 (Provided)"] = "наповнений фіал №3 (видано)", ["Filled Vial Labeled #4"] = "наповнений фіал №4", ["Filled Vial Labeled #4 (Provided)"] = "наповнений фіал №4 (видано)" } },
    [3569] = { [1] = "Повзуче загнивання", [2] = "Віддай це Терсі. Можливо, це вилікує її... А може й ні. Ми не дізнаємося, поки вона це не вип'є.", [3] = "Віддайте еліксир К'юлі Терсі Пісні Вітру в Підмісті.", [4] = "Я прибула до Підмістя, бо чула, що тутешні алхіміки довго та наполегливо досліджували, як знайти ліки проти їхньої власної недуги. Я подумала, що, можливо, вони зможуть допомогти і мені.\n\nХоча це місце змушує мене почуватися зовсім небажаною гостею, у мене немає вибору - ця хвороба, що спіткала мене, розриває мене зсередини, і я негайно потребую їхньої допомоги.", [5] = "Хімік К'юлі поводився дуже люб'язно... аж тривожно. Але якщо він каже, що це мені допоможе, тоді я не маю вибору. У мене немає часу на пошук інших рішень. Я вже говорила з жерцями та шаманами, і жоден з них не зміг мені допомогти.\n\nБудемо сподіватися, що Матір-Земля оберігає мою душу.", ["en"] = "Seeping Corruption", ["tasks"] = { ["Cuely's Elixir"] = "еліксир К'юлі", ["Cuely's Elixir (Provided)"] = "еліксир К'юлі (видано)" } },
    [3570] = { [1] = "Повзуче загнивання", [4] = "Ти ж розумієш, що це означає, чи не так, {Ім'я}? У неї немає шансів вижити... подивися на неї. Найкраще, що вона може тепер зробити, це допомогти нам знайти ліки проти чуми. Ця вода, яку вона випила, може підказати нам, як це зробити. Ця тауренка все одно помре, тож вона може померти й роблячи щось благородне для нашого народу. {Стать:Згоден:Згодна}?", [5] = "Я навіть не думав, що еліксир зможе так швидко подіяти. Дякую тобі, {Ім'я}. Я негайно почну працювати над рештою зразків. Упевнений, вже скоро леді Сильвана та відречені знайдуть їм застосування.", ["en"] = "Seeping Corruption" },
    [3601] = { [1] = "Так, Кім'джаєль!", [2] = "Так, Кім'джаєль!! Ти знаєш, що означає Кім'джаєль мовою ельфів крові, {ім'я}? Маленький щур... чи щось на кшталт того. Вони ті ще задири!\n\nВони найняли мене, щоб допомогти їм розвідати цю область в пошуках загубленого скарбу. Звичайно, я згодився відразу, як тільки вони згадали \"скарб\" та суму, яку вони були готові заплатити, але звичайно ж, вони підставили мене і намагалися вбити мене... МЕНЕ!\n\nЦе доводить, що ельфам крові не можна вірити.\n\nПроблема в тому, що моє спорядження все ще у них, і я не можу його повернути. Можеш допомогти мені?", [3] = "Знайдіть у Талассійському опорному таборі компас, приціл, плюшеве курча та відцентровий розтягувач Кім'джаеля, а потім поверніть їх Кім'джаєлю в Азшару.", [4] = "Смердючі ельфи крові. Кажу тобі, якби я був такий же сильний, як ти, я б сам спустився туди й провчив їх! Але мені доведеться задовольнитися тим, що я заплачу тобі, щоб ти {стать:подбав:подбала} про них.", [5] = "Ха-ха! Ти їх добре {стать:побив:побила}, чи не так?!\n\nЦе чудово! Це навчить ельфів крові не зраджувати своїх партнерів... особливо таких вірних, як гоблін-торговець! Ба, ельфи крові...!\n\nНу, найменше, що я можу для тебе зробити, це заплатити тобі за твій час... як я й обіцяв.\n\nТримай... це тобі знадобиться.", ["en"] = "Kim'jael Indeed!", ["tasks"] = { ["Kim'Jael's Compass"] = "компас Кім'джаєля", ["Kim'Jael's Compass (Provided)"] = "компас Кім'джаєля (видано)", ["Kim'Jael's Scope"] = "приціл Кім'джаєля", ["Kim'Jael's Scope (Provided)"] = "приціл Кім'джаєля (видано)", ["Kim'Jael's Stuffed Chicken"] = "плюшеве курча Кім'джаєля", ["Kim'Jael's Stuffed Chicken (Provided)"] = "плюшеве курча Кім'джаєля (видано)", ["Kim'Jael's Wizzlegoober"] = "відцентровий розтягувач Кім'джаєля", ["Kim'Jael's Wizzlegoober (Provided)"] = "відцентровий розтягувач Кім'джаєля (видано)" } },
    [3602] = { [1] = "Азшарит", [2] = "Древні скельні велетні південної частини Азшари живляться камінням. Продукт їхньої життєдіяльності — дуже пластичний та надзвичайно міцний кристал, відомий як азшарит.\n\nНа південній гряді знаходяться цілі поклади азшариту, проте його майже нікому не вдавалося добути через надзвичайну жорстокість велетнів.\n\nТи маєш вирушити на південь і зібрати достатньо азшариту для створення зброї. Мої скверношукачі допоможуть тобі у пошуках кристалів.", [3] = "Знайдіть двадцять кристалізованих азшаритів в південній Азшарі. Ви можете використати скверношукачів, які допоможуть вам \"винюхати\" місцеперебування хитромудро схованих кристалів.\n\nПоверніться до Лорама, коли завдання буде виконано.", [4] = "Зло не спить, {стать:дурню:дурепо}. Ти матимеш час для відпочинку, коли помреш. А тепер принеси мені ті кристали.", [5] = "Твої завдання в Азшарі закінчені, {стать:смертний:смертна}. Тепер мені потрібно викувати необхідні компоненти для наступного етапу твоєї пригоди.", ["en"] = "Azsharite", ["tasks"] = { ["Crystallized Azsharite"] = "кристалізований азшарит", ["Crystallized Azsharite (Provided)"] = "кристалізований азшарит (видано)" } },
    [3621] = { [1] = "Створення скверноотрути", [2] = "Зброя готова до кування. Тобі слід віднести загартований азшарит до того, хто може приборкати енергію скверни.\n\nУ Тернистій долині є такий коваль. Ґальван Древній, лідер Ордену Мітрилу, створить зброю на твоє замовлення. Ти знайдеш його в таборі між Зул'Ґурубом і огрівським згірком Мош'Оґґ.\n\nНехай твоя рішучість та віра допоможуть тобі у твоєму випробуванні. Якщо ти зазнаєш невдачі, знай, що твій Бог посміхається тобі, {стать:смертний:смертна}.", [3] = "Віднесіть вантаж Ґальвану Древньому в Тернисту долину.", [4] = "Лорам, так? Я вже багато років не чув цього імені.", [5] = "Боже мій, я можу тільки уявити, через що ти {стать:пройшов:пройшла}, щоб отримати ці матеріали. Мало хто наважується піти в Азшару і повертається звідти живим, не кажучи вже про тих, хто стикається з напівбогами та велетнями!", ["en"] = "The Formation of Felbane", ["tasks"] = { ["Shipment to Galvan"] = "вантаж для Гальвана", ["Shipment to Galvan (Provided)"] = "вантаж для Гальвана (видано)" } },
    [3622] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [3625] = { [1] = "Зачарована азшаритова зброя скверни", [2] = "{ім'я}, створення зброї займе деякий час.\n\nКрім того, ти зможеш використовувати силу прокляття скверни лише раз на три хвилини. Його дія проти Разеліха-Губителя та його поплічників може мати різну тривалість. Ось чому тобі слід вивільняти силу прокляття лише в потрібний момент!\n\nА тепер дай мені трохи часу, щоб створити твою зброю, {ім'я}.", [3] = "Зачекайте, поки Ґальван закінчить кувати зброю.", [4] = "Якщо втручатися в процес кування, зброя може вийти недосконалою. Трохи терпіння, {ім'я}.", [5] = "<Ґальван витирає піт з чола.>\n\nКращої зброї для знищення демонів ще не існувало, {ім'я}.", ["en"] = "Enchanted Azsharite Fel Weaponry", ["tasks"] = { ["Weaponry Creation"] = "Створення зброї" } },
    [3626] = { [1] = "Повернення у Спустошені землі", [2] = "Час відплати близький, {ім'я}. Тобі слід повернутися в Спустошені землі разом з твоєю новою зброєю і поговорити з полеглим героєм Орди, щоб отримати своє останнє завдання.", [3] = "Поверніться до полеглого героя Орди.", [5] = "Схоже, що битви загартували тебе, {ім'я}. Ти {стать:готовий:готова} протистояти Разеліху та його поплічникам?", ["en"] = "Return to the Blasted Lands" },
    [3627] = { [1] = "Об'єднання розбитого амулета", [2] = "Щоб дістатися до Губителя, тобі спочатку потрібно знищити трійцю влади та зібрати частини амулета. Коли ти знайдеш всі три частини, повернись до мене і я розповім як діяти далі..\n\nЙди, {ім'я}! У Спустошені землі! Севіна, Аллістарж та Ґрол повинні померти!", [3] = "Вбийте Ґрола-Винищувача, леді Севіну та архімага Аллістаржа. З їх трупів заберіть амулет Ґрола, амулет Севіни та амулет Аллістаржа.\n\nНе забудьте використовувати вашу зачаровану азшаритову зброю скверни, щоб послабити трійцю. Їх не можна вбити інакше — але використовуйте її з розумом...", [4] = "Троє сформують один, і один освітить шлях.", [5] = "Амулет Разеліха-Губителя знову єдиний, але він відчуває, що ланцюг його влади обірваний. Він знає, що ти йдеш за ним...", ["en"] = "Uniting the Shattered Amulet", ["tasks"] = { ["Amulet of Allistarj"] = "амулет Аллістаржа", ["Amulet of Allistarj (Provided)"] = "амулет Аллістаржа (видано)", ["Amulet of Grol"] = "амулет Ґрола", ["Amulet of Grol (Provided)"] = "амулет Ґрола (видано)", ["Amulet of Sevine"] = "амулет Севіни", ["Amulet of Sevine (Provided)"] = "амулет Севіни (видано)" } },
    [3628] = { [1] = "Ти — Рах'ліх, демон", [2] = "Лігво Разеліха знаходиться на вершині найвищої гори в Спустошених землях. Єдиний спосіб потрапити до лігва — використати телепортуючі руни біля гори. Поки ти маєш амулет, ти можеш вільно телепортуватись до лігва. Коли будеш в лігві, тобі потрібно призвати звіра. Амулет — твій ключ, {ім'я}. Використовуй його на вівтарі Губителя.\n\nЯкщо ти переможеш Губителя, принеси його ріг. Він стане символом надії для всіх, хто побачить його — доказом того, що герої існують у цьому зруйнованому війною світі.", [3] = "Знищте Разеліха-Губителя та принесіть відрубаний ріг Губителя полеглому герою Орди. Також вам потрібно повернути оберіг Губителя, щоб полеглий герой міг знищити його та запобігти потраплянню в злі руки.", [4] = "Більше немає чого боятися.", [5] = "Сьогодні день, який запам'ятається назавжди. З демонічним володарем Спустошених земель нарешті покінчено!", ["en"] = "You Are Rakh'likh, Demon", ["tasks"] = { ["Severed Horn of the Defiler"] = "відрубаний ріг Губителя", ["Severed Horn of the Defiler (Provided)"] = "відрубаний ріг Губителя (видано)", ["Ward of the Defiler"] = "оберіг Губителя", ["Ward of the Defiler (Provided)"] = "оберіг Губителя (видано)" } },
    [3631] = { [1] = "Виклик скверножеребця", [2] = "Хмм. Я думаю, що ти не {стать:готовий:готова}, але не мені вирішувати. Страгад має іншу думку, і це його рішення... цього разу.\n\nВін хоче поговорити з тобою, і швидко. Ти знайдеш його на тому ж місці — над Брашпилем в Степах, у його маленькій вежі з його помічниками.\n\nНе зволікай.", [3] = "Поговоріть зі Страгадом Фарсаном в Степах.", [5] = "Отже, ти {стать:вирішив:вирішила} знову відвідати мою скромну особу. Дуже мило з твого боку.\n\nМої помічники сумнівалися, що ти коли-небудь з'явишся. Я сказав їм, що не сумніваюся. Коли мова йде про силу, ти притягуєшся, як метелик до полум'я.", ["en"] = "Summon Felsteed" },
    [3633] = { [1] = "Гоблінська інженерія", [2] = "Інженери-експерти обирають між двома дисциплінами: гномською та гоблінською інженерією. Очевидно, що гоблінська інженерія — це вибір найталановитіших інженерів. Підкори світ, використовуючи потужну вибухівку та фантастичне спорядження!\n\n{ім'я}, прочитай цей посібник. Якщо ти бажаєш дізнатися більше про гоблінську інженерію, то віднеси цей посібник Ніксу Вертопруженю в Пристроблях. Пам'ятай — зробивши цей вибір, ти не зможеш передумати та вивчати іншу дисципліну, тому переконайся, що ти {стать:впевнений:впевнена} у своєму шляху, перш ніж виконувати його завдання.", [3] = "Якщо ви хочете дізнатися більше про гоблінську інженерію, віднесіть посібник з інженерних дисциплін Ніксу Вертопруженю в Пристроблях.", [4] = "Я відчуваю запах свіжих новобранців так само як чудовий вибуховий порошок — за кілометр. Ти {стать:прийшов:прийшла} сюди, щоб навчитися майстерності виготовлення вибухівки?", [5] = "Ну що ж, {ім'я}, ти {стать:вчинив:вчинила} мудро, звернувшись до мене за наставництвом! Будь-який приблуда може стати експертом в основах інженерії — гноми та їх опромінений дім Гномреґан є свідченням цього. Але для того, щоб володіти дисципліною гоблінської інженерії, потрібен сильний розум і стійка рука (з особливим акцентом на СТІЙКУ).\n\nТримай вуха наготові, {ім'я}, і можливо, ти чогось навчишся.", ["en"] = "Goblin Engineering", ["tasks"] = { ["Manual of Engineering Disciplines"] = "посібник з інженерних дисциплін", ["Manual of Engineering Disciplines (Provided)"] = "посібник з інженерних дисциплін (видано)" } },
    [3638] = { [1] = "Угода про нерозголошення", [2] = "Гоблінська інженерія — це теорія інженерії, націлена на отримання великого прибутку та великих вибухів! Вона дозволяє нам створювати потужні бомби та могутню зброю. Це було описано в книжці, яку ти {стать:прочитав:прочитала}.\n\nУ цій книжці також згадується наша давня присяга зберігати секрети наших винаходів. Коли ти стаєш на шлях гоблінської інженерії, це остаточно — про гномську інженерію можеш забути.\n\nЯкщо ти все ще хочеш займатися гоблінською інженерією — підпиши цю угоду про довічне нерозголошення таємниць, і знову поговори зі мною. Гарненько подумай, {ім'я}.", [3] = "Якщо ви згодні займатися гоблінською інженерією, підпишіть угоду про нерозголошення і ще раз поговоріть з Ніксом Вертопруженем в Пристроблясі.", [4] = "Якщо ти {стать:підписав:підписала} документ і {стать:готовий:готова} віддати його мені, то це остаточно. Тобі сказали, що це поїздка в один кінець. Якщо ти {стать:готовий:готова}, то стрибай на борт!", [5] = "Ласкаво просимо, {ім'я}! Ти незабаром матимеш доступ до найбільш передових інженерних розробок у всьому Азероті.\n\nТепер, коли ти {стать:присвятив:присвятила} себе цим знанням, настав час випробувати твої навички. Після цього ми допоможемо тобі розкрити свій потенціал в гоблінській інженерії!", ["en"] = "The Pledge of Secrecy", ["tasks"] = { ["Nixx's Signed Pledge"] = "підписана угода Нікса", ["Nixx's Signed Pledge (Provided)"] = "підписана угода Нікса (видано)" } },
    [3639] = { [1] = "Покажи свою роботу", [2] = "Як твій наставник, я хочу побачити зразки твоєї роботи. Ти {стать:вправний інженер:вправна інженерка}, без сумнівів, {ім'я}. Однак я хочу проаналізувати твою роботу, щоб виділити гоблінські техніки у твоїй майбутній діяльності. Мені потрібні такі зразки: двадцять великих залізних бомб, двадцять штук твердого динаміту і шість вибухових овець.\n\nПринеси мені ці предмети, і я видам тобі твою власну членську картку гоблінського інженера. Вона обов'язково потрібна для доступу до всіх тренерів гоблінської інженерії!", [3] = "Принесіть 20 великих залізних бомб, 20 твердого динаміту і 5 вибухових овець Ніксу Вертопруженю в Пристроблях.", [4] = "Після того, як я побачу твої інженерні вироби, я видам тобі справжню членську картку гоблінського інженера! Допоки картка дійсна, у тебе буде необмежений доступ до будь-якого тренера з гоблінської інженерії по всьому світу.", [5] = "Ось твоя перша членська картка гоблінського інженера!\n\nВнесок по цій картці сплачено на чотирнадцять днів. Через два тижні термін її дії закінчиться. Коли це станеться — оплати наступний внесок будь-якому тренеру з гоблінської інженерії, щоб отримати нову картку. Без картки твоє членство тимчасово призупиниться, і ти не матимеш доступу до нових креслень.\n\nЦе ніяк не вплине на вже набуті знання: якщо ти вже {стать:став гоблінським інженером:стала гоблінською інженеркою}, то це назавжди.", ["en"] = "Show Your Work", ["tasks"] = { ["Big Iron Bomb"] = "велика залізна бомба", ["Big Iron Bomb (Provided)"] = "велика залізна бомба (видано)", ["Explosive Sheep"] = "вибухова вівця", ["Explosive Sheep (Provided)"] = "вибухова вівця (видано)", ["Explosive Sheep slain"] = "вибухова вівця: убито", ["Solid Dynamite"] = "твердий динаміт", ["Solid Dynamite (Provided)"] = "твердий динаміт (видано)" } },
    [3644] = { [1] = "Поновлення членської картки", [4] = "Щоб поновити членську картку, вам потрібно сплатити внесок у розмірі двох золотих.", [5] = "Оскільки ти займаєшся гоблінською інженерією й маєш гарну репутацію, я можу поновити твою членську картку за дві золоті монети. Після оплати цієї суми тобі буде видана нова картка. Це дозволить тобі мати доступ до креслень гоблінської інженерії від відповідних тренерів.\n\nЦя картка буде дійсна протягом двох тижнів, після чого тобі знову потрібно буде оплатити членський внесок! Якщо ти хочеш мати доступ до креслень, тобі потрібно закрити всі свої заборгованості.", ["en"] = "Membership Card Renewal", ["tasks"] = { ["Required money: 2"] = "Необхідні гроші: 2" } },
    [3645] = { [1] = "Поновлення членської картки", [4] = "Щоб поновити членську картку, вам потрібно сплатити внесок у розмірі двох золотих.", [5] = "Оскільки ти займаєшся гномською інженерією й маєш гарну репутацію, я можу поновити твою членську картку за дві золоті монети. Після оплати цієї суми тобі буде видана нова картка. Це дозволить тобі мати доступ до креслень гномської інженерії від відповідних тренерів.\n\nЦя картка буде дійсна протягом двох тижнів, після чого тобі знову потрібно буде оплатити членський внесок! Якщо ти хочеш мати доступ до креслень, тобі потрібно закрити всі свої заборгованості.", ["en"] = "Membership Card Renewal", ["tasks"] = { ["Required money: 2"] = "Необхідні гроші: 2" } },
    [3646] = { [1] = "Поновлення членської картки", [4] = "Щоб поновити членську картку, вам потрібно сплатити внесок у розмірі двох золотих.", [5] = "Оскільки ти займаєшся гоблінською інженерією й маєш гарну репутацію, я можу поновити твою членську картку за дві золоті монети. Після оплати цієї суми тобі буде видана нова картка. Це дозволить тобі мати доступ до креслень гоблінської інженерії від відповідних тренерів.\n\nЦя картка буде дійсна протягом двох тижнів, після чого тобі знову потрібно буде оплатити членський внесок! Якщо ти хочеш мати доступ до креслень, тобі потрібно закрити всі свої заборгованості.", ["en"] = "Membership Card Renewal", ["tasks"] = { ["Required money: 2"] = "Необхідні гроші: 2" } },
    [3661] = { [1] = "Улюбленці Елуни?", [2] = "Дикі совухи — досить непередбачувані істоти, {ім'я}. Вони можуть бути добрими й милими, але щойно щось дороге для них опиняється під загрозою — в них прокидається надзвичайно жорстокий звір!\n\nПодейкують, що їх створила сама Елуна, і я хочу дізнатися, чи це справді так.\n\nНещодавно я дізнався, що серед дикої природи Внутрішніх земель живуть дикі совухи — злий, примітивний та жорстокий вид. Чи не {стать:міг би:могла б} ти зібрати для мене їхнє пір'я?", [3] = "Зберіть 15 пір'їн диких совухів у Внутрішніх землях для Ереласа Бурштинонебого з селища Рут'Теран.", [4] = "Спробуй триматись якнайдалі від диких совухів, {ім'я}. Вони можуть розцінити твою присутність, як загрозу...", [5] = "Дякую за пір'я, {ім'я}.\n\nЩо тобі вдалося дізнатись про диких совухів?\n\nМожливо, це пір'я допоможе нам дізнатися про них більше. Люті монстри чи звичайні мирні тварини? Сподіваюся, колись я дізнаюся правду...\n\nЯ продовжу свої дослідження, тож приходь пізніше, мені може знову знадобитись твоя допомога.", ["en"] = "Favored of Elune?", ["tasks"] = { ["Wildkin Feather"] = "перо дикого совуха", ["Wildkin Feather (Provided)"] = "перо дикого совуха (видано)" } },
    [3701] = { [1] = "Тліючі руїни Тауріссана", [2] = "Вирушай до тліючих руїн Тауріссана в Палаючому степі та збери якомога більше інформації.\n\nКажуть, що руїни усіяні таємничими реліквіями. Можливо, тобі варто розпочати пошуки там, {ім'я}. Остерігайся вартових-вбивць Тауріссана. Вони стережуть руїни, охороняючи всі приховані там таємниці.", [3] = "Відправляйтесь до руїн Тауріссана в Палаючий степ і добудьте інформацію про реліквії Тауріссана. Повертайтесь зі знахідкою до королівського історика Архіни.", [4] = "Є якась нова інформація?", [5] = "Лишенько! Ця інформація багато чого прояснює щодо Тауріссана.\n\nАле нам доведеться дізнатися ще більше!", ["en"] = "The Smoldering Ruins of Thaurissan", ["tasks"] = { ["Information Recovered"] = "Відновлена інформація", ["Information Recovered (Provided)"] = "Відновлена інформація (видано)", ["Information Recovered slain"] = "Відновлена інформація: убито" } },
    [3721] = { [1] = "Твій власний ООХ", [5] = "Ти {стать:знайшов:знайшла} три мої автономні роботи серії OOX! Ти {стать:зробив:зробила} набагато більше, ніж {стать:мав:мала}, то ж я дам тобі дещо особливе. Мініверсію того ж робота, який встиг тобі полюбитися!\n\nЗазвичай я не віддаю абикому такі потенціально смертоносні пристрої, але ти мені дуже {стать:допоміг:допомогла}. До того ж бойову механіку та систему самонаведення в цьому роботі було відключено.\n\nАле в усьому іншому це справжнісінький робот серії OOX, їй-бо!", ["en"] = "An OOX of Your Own" },
    [3741] = { [1] = "Намисто Гіларі", [2] = "Моя подружка Гіларі загубила своє намисто й ми не можемо його знайти. Ми тут весь день рибалили й пошукали всюди, де тільки можна. Лишається тільки думати, що воно впало в озеро. Батьки не хочуть, щоб ми купалися в озері... Мама каже, що там якісь лихі речі під водою, але ви, схоже, не боїтеся лихих речей.\n\nВи можете знайти намисто для неї, будь ласка?", [3] = "Знайдіть намисто Гіларі та поверніть його їй у Приозер'я.", [4] = "Здрастуйте. Я сумую за своїм намистечком. Татусь подарував його мені. Тато каже, там є чудовиська в озері. Ви колись бились з чудовиськами?", [5] = "Дякую, що знайшли моє намисто, {стать:пане:пані} {клас:н}... ви дуже {стать:добрий:добра}! Моя киця теж вам дякує, чи не так, Ефсі?", ["en"] = "Hilary's Necklace", ["tasks"] = { ["Hilary's Necklace"] = "намисто Гіларі", ["Hilary's Necklace (Provided)"] = "намисто Гіларі (видано)" } },
    [378] = { [1] = "Приборкання люті", [2] = "Ти {стать:довів:довела} свою відданість королю Маґні, {клас:к}. Певно, твоя ненависть до Темного Заліза не поступається моїй.\n\nЄ одна справа, яку я хотів би виконати, але маю залишатись з Довгокосом. Роґґо каже, що в нього є докази того, що Кам Темнолют був організатором нападу на віадук Тандола. Це через його плани Довгокос втратив брата.\n\nТемнолюта тримають в Штормовійській в'язниці. Він має померти, {ім'я}. За Довгокоса! Принеси мені його голову!", [3] = "Мотлі Гармаш просить вас принести йому в Дун-Модр голову Кама Темнолюта.", [4] = "Я не дозволю бюрократії якихось людських вельмож заважати нашому правосуддю, {ім'я}. У нас є достатньо доказів того, що Кам Темнолют стоїть за нападом на віадук Тандола. Кращі люди короля Маґні загинули через цього мерзотника. Хай там як би людям не було достатньо того, що Темнолют гниє у в'язниці, я не заспокоюсь, поки він не здохне.", [5] = "Отож, Кам Темнолют нарешті отримав заслужену смерть? Добре. Гидкі покидьки з Темного Заліза іншого і не заслуговують. Ти чудово {стать:впорався:впоралась}, {клас:к}. Жертви атаки на віадук Тандола — це не перші й не останні жертви цього світу, охопленого війнами та ненавистю. Їх сім'ям буде легше, коли вони будуть знати, що винуватець їх горя отримав заслужене покарання. Ми помстились за смерть брата Довгокоса.", ["en"] = "The Fury Runs Deep", ["tasks"] = { ["Head of Deepfury"] = "голова Темнолюта", ["Head of Deepfury (Provided)"] = "голова Темнолюта (видано)" } },
    [3783] = { [1] = "Механічні єті!", [2] = "Мої друзі завжди вигадують чудові ідеї. Я ніколи не думала, що зможу зрівнятися з ними... до сьогоднішнього дня! Я щойно придумала щось грандіозне! Якщо ти пообіцяєш тримати це в таємниці, я розповім тобі...\n\nЯ збираюся зробити механічного єті! Мої друзі не лише злякаються, коли побачать його, але й будуть вражені!\n\nДля початку мені потрібне густе хутро єті. Допоможеш? Ти знайдеш їх на південному сході.", [3] = "Принесіть 10 шматків густого хутра єті Умі Румпельшніцель в Завшегляд.", [4] = "Мені треба багато чого для початку. Будь ласка, принеси мені хутро якнайшвидше!", [5] = "Це хутро ідеальне, {ім'я}. Тепер можна починати!", ["en"] = "Are We There, Yeti?", ["tasks"] = { ["Thick Yeti Fur"] = "густе хутро єті", ["Thick Yeti Fur (Provided)"] = "густе хутро єті (видано)" } },
    [3787] = { [1] = "Прохання Вогнепада", [2] = "Перепрошую...\n\nОдин мій колега хоче поговорити з тобою щодо дослідження, яке він проводить спільно з Кенарійським Колом. Це друїд на ім'я Квінтіс Вогнепад, що знаходиться у фортеці Перомісяць, що у Фераласі. Він хоче поговорити про світанку... І схоже, що він хоче зберегти це в таємниці від верховного друїда.\n\nЯкщо тобі цікаво — поговори з ним, він розкаже детальніше.", [3] = "Поговоріть з Квінтісом Вогнепадом у фортеці Перомісяць.", [5] = "Дякую, що {стать:прийшов:прийшла}, {стать:мандрівниче:мандрівнице}! Дозволь представитись — я Квінтіс Вогнепад, друїд та скромний прислужник Малфуріона та Кенарійського Кола. Ми з моїми колегами, генералом Шандріс Перомісяць та Протекторатом, хотіли б поговорити про завдання, яке ти виконуєш для Фендрала Оленерога в Дарнасі.\n\nПеред тим, як ми продовжимо, я маю попросити тебе, щоб це все залишилось між нами. Якщо ти {стать:згоден:згодна}, можемо продовжити.", ["en"] = "Jonespyre's Request" },
    [3788] = { [1] = "Прохання Вогнепада", [2] = "Перепрошую...\n\nОдин мій колега хоче поговорити з тобою щодо дослідження, яке він проводить спільно з Кенарійським Колом. Це друїд на ім'я Квінтіс Вогнепад, що знаходиться тут, у фортеці Перомісяць. Він хоче поговорити про світанку... І схоже, що він хоче зберегти це в таємниці від верховного друїда.\n\nЯкщо тобі цікаво — поговори з ним, він розкаже детальніше.", [3] = "Поговоріть з Квінтісом Вогнепадом у фортеці Перомісяць.", [5] = "Дякую, що {стать:прийшов:прийшла}, {стать:мандрівниче:мандрівнице}! Дозволь представитись: я Квінтіс Вогнепад, друїд та скромний послужник Малфуріона та Кенарійського Кола. Ми з моїми колегами, генералом Шандріс Перомісяць та Протекторатом, хотіли б поговорити про завдання, яке ти виконуєш для Фендрала Оленерога в Дарнасі.\n\nПеред тим, як ми продовжимо, я маю попросити тебе, щоб це все залишилось між нами. Якщо ти {стать:згоден:згодна} — можемо продовжити.", ["en"] = "Jonespyre's Request" },
    [3791] = { [1] = "Таємниця світанки", [2] = "{Ім'я}, я буду з тобою відвертим. Мене цікавить — ні, мене хвилює, чому верховний друїд у Дарнасі користується ім'ям та можливостями Кенарійського Кола для того, щоб добувати величезну кількість світанки. Я — дослідник, і спеціалізуюсь на прокляттях. І я чув, що за певних умов світанка набуває тих самих властивостей, що й інші трави, що використовуються в примітивних прокляттях.\n\nЯ хотів би дізнатися про неї більше, тож мені потрібна твоя допомога. Принеси мені десять світанок і я гідно тобі віддячу.", [3] = "Принесіть 10 світанок Квінтісу Вогнепаду в фортецю Перомісяць.", [4] = "Мені потрібно десять світанок — цього має бути достатньо для початку досліджень. Звісно, я витрачу чимало матеріалу на тупикові експерименти, але така вже природа наукових досліджень.", [5] = "Хм, ця світанка викликає в мене... дивні відчуття. Що, в ім'я Елуни, задумав зробити з ними Оленеріг?\n\nУ будь-якому разі, ще раз дякую за твою допомогу. Ось дещо... ну, знаєш, за твої зусилля. Мої дослідження світанки займуть деякий час, і мені, безперечно, знадобиться більше. І раз я вже цим зайнявся, думаю, варто перевірити, чи можна використати світанку в алхімії. Проте, мені зле від цих рослин...", ["en"] = "The Mystery of Morrowgrain", ["tasks"] = { ["Morrowgrain"] = "світанка", ["Morrowgrain (Provided)"] = "світанка (видано)" } },
    [3792] = { [1] = "Світанка для фортеці Перомісяць", [4] = "І знову привіт, {ім'я}. Мої дослідження просуваються досить непогано, але якщо у тебе знайдеться ще п'ять світанок, я б з радістю прийняв їх. Ну... \"з радістю\" - це фігурально. Чим більше часу я провожу з ними, тим гірше почуваюся. Проте я не маю наміру відмовлятися від подальших експериментів.", [5] = "Дякую, {ім'я}. Я поки приберу їх подалі. У мене, звісно, немає таких можливостей, як в Оленерога, та все ж я зможу віддячити тобі за клопіт. Тим більше хто зна, що може статись, якщо Оленеріг отримуватиме все більше світанки... Тут щось дивне відбувається, запам'ятай мої слова!\n\nНе забувай, що мені завжди потрібна світанка. Принось ще, по п'ять штук за раз.", ["en"] = "Morrowgrain to Feathermoon Stronghold", ["tasks"] = { ["Morrowgrain"] = "світанка", ["Morrowgrain (Provided)"] = "світанка (видано)" } },
    [3801] = { [1] = "Спадщина Темного Заліза", [2] = "Вітаю, {ім'я}. Я Франклорн Файноков. Так, той самий Файноков, що придумав, як обробляти камінь для архітектурних витворів. Тобі, безсумнівно, траплялося проходити повз чи стояти на одному з моїх творінь, коли {стать:подорожував:подорожувала} розтерзаними війною землями.\n\nТобі, напевно, цікаво, чому я тут і що я хочу від тебе. Гарні питання.\n\nЗвичайно, мені потрібна твоя допомога. В обмін на допомогу я дам тобі ключ до глибин мого проклятого міста.", [3] = "Якщо ви хочете отримати ключ від міста, поговоріть з Франклорном Файноковом.", [5] = "Незалежно від того, що привело тебе сюди — жадібність чи сліпа відданість, те, що ти збираєшся зробити, буде на благо всіх нас.", ["en"] = "Dark Iron Legacy" },
    [3802] = { [1] = "Спадщина Темного Заліза", [2] = "Ти знайдеш Точеня Темноблиска за кільцем Закону, в залі Ремесла. Вбий жалюгідного виродка та поверни Залізоскверн.\n\nВіднеси Залізоскверн у святилище Тауріссана та поклади молот на його законне місце — в руки статуї, зведеної на мою честь.\n\nКоли зробиш це, відсік, в якому я зберігав головний ключ, відкриється. А найголовніше те, що Залізоскверн назавжди залишиться в моїх руках. Якщо хтось спробує забрати молот, то і статуя, і молот розлетяться на друзки та будуть втрачені назавжди.", [3] = "Вбийте Точеня Темноблиска та знайдіть великий молот, Залізоскверн. Віднесіть молот у святилище Тауріссана та покладіть його в руки статуї Франклорна Файнокова.", [4] = "Статуя зловісно нависає над вами.", [5] = "Молот міцно вкладається в руки масивного монумента Темного Заліза. В основі статуї відкривається крихітний відсік. Всередині видно...", ["en"] = "Dark Iron Legacy", ["tasks"] = { ["Ironfel"] = "Залізоскверн", ["Ironfel (Provided)"] = "Залізоскверн (видано)" } },
    [3803] = { [1] = "Світанка для Дарнасу", [4] = "Верховному друїду завжди потрібна світанка для проведення досліджень Кенарійського Кола. Ми приймаємо її по десять одиниць і натомість даємо кілька корисних речей. Коли збереш десять світанок — принось мені, і я тебе гідно винагороджу.", [5] = "Чудово! Верховний друїд, безсумнівно, буде радий цій світанці. Хоча, мушу визнати... навіть перебувати поруч із нею не дуже приємно. Уявляю, як важко верховному друїду весь час працювати з цією рослиною!\n\nЦе для тебе, {ім'я}. Кенарійське Коло дякує за твою постійну підтримку.", ["en"] = "Morrowgrain to Darnassus", ["tasks"] = { ["Morrowgrain"] = "світанка", ["Morrowgrain (Provided)"] = "світанка (видано)" } },
    [3825] = { [1] = "Голова огра на палиці = група", [2] = "Останнє завдання для тебе, солдате.\n\nЯ взяв на себе відповідальність насадити голову Ґор'теша на спис. Тепер тобі потрібно лише віднести її на вершину скелі Жахобою і встромити в землю. Потім дивись, як ті боязкі огри кинуться рятувати свої життя! Після того як це зробиш, повертайся до мене, і я винагороджу тебе за твою важку роботу.\n\n<Ораліус, здається, втрачає зв'язок з реальністю.>", [3] = "Візьміть відрубану голову Ґор'теша і віднесіть на вершину скелі Жахобою. Знайдіть купу пухкої землі та встроміть в неї спис.", [4] = "І? Ти {стать:змалював:змалювала} якусь картину з їхньої паніки?", [5] = "Неперевершена робота, солдате! Просто дивовижно! Ох, я отримаю за це медаль... ем... тобто, ти будеш щедро {стать:винагороджений:винагороджена} за це!", ["en"] = "Ogre Head On A Stick = Party", ["tasks"] = { ["Gor'tesh Head Planted"] = "Голова Гор'теша посаджена", ["Gor'tesh Head Planted (Provided)"] = "Голова Гор'теша посаджена (видано)", ["Gor'tesh Head Planted slain"] = "Голова Гор'теша посаджена: убито" } },
    [3844] = { [1] = "Це таємниця для всіх", [2] = "Розбитий пліт лежить біля узбережжя. Зважаючи на те, що це лише невеликий ставок, незрозуміло, як він тут опинився, хоча, дивлячись на дерева, можна припустити, що рівень води міг змінитися.\n\nМожливо, варто оглянути місцевість в пошуках підказок...", [3] = "Подивіться навкруги, щоб знайти підказку про те, кому може належати цей розбитий пліт.", [5] = "На дні ставка видно промоклу сумку.", ["en"] = "It's a Secret to Everybody" },
    [3845] = { [1] = "Це таємниця для всіх", [2] = "Схопивши сумку, ви тягнете її до берега. Можливо, якщо ви оглянете речі всередині, то дізнаєтесь більше про те, кому вони належать.\n\nУ прихистку Маршала є кілька мандрівників. Можливо, там ви зможете дізнатися більше.", [3] = "Огляньте предмети в сумці та віддайте їх власнику.", [4] = "Привіт. Я тебе десь бачив... Хіба ні?", [5] = "О... Так, ці речі виглядають знайомими... ну, мабуть...", ["en"] = "It's a Secret to Everybody", ["tasks"] = { ["Curled Map Parchment"] = "скручений пергамент з мапою", ["Curled Map Parchment (Provided)"] = "скручений пергамент з мапою (видано)", ["Large Compass"] = "великий компас", ["Large Compass (Provided)"] = "великий компас (видано)", ["Lion-headed Key"] = "ключ з головою лева", ["Lion-headed Key (Provided)"] = "ключ з головою лева (видано)" } },
    [385] = { [1] = "Полювання на кроколісків", [2] = "Багато мисливців приїздить до Лох-Модану для полювання на славнозвісних кроколісків. Завжди знаходяться торговці, що скуповують шкури кроколісків чи поціновувачі їх м'яса.\n\nМи теж заробляємо на цьому, але небагато, так як кроколіски ті ще звірюки, які до того ж сховались на островах озера Лох. Але я не стану тебе відмовляти - боротьба з щелепами звірів приносить неабиякі враження.\n\nЩо ж, було раз і я...", [3] = "Принесіть 5 шматків м'яса кроколіска та 6 шкур кроколіска Мареку Залізосерду в оселю Далекоходців.", [4] = "Я тобі розказував, як мені кроколіск ледь руку не відкусив? Злобна звірюга то була, зуби як леза. Але мені пощастило - я заткнув тій скотині пащу своїм ножем. Я досі бережу той ніж...", [5] = "Ну, ти {стать:добув:добула} чудові екземпляри, {ім'я}. За таке добро - слід щедро винагородити, це точно.", ["en"] = "Crocolisk Hunting", ["tasks"] = { ["Crocolisk Meat"] = "м'ясо кроколіска", ["Crocolisk Meat (Provided)"] = "м'ясо кроколіска (видано)", ["Crocolisk Skin"] = "шкура кроколіска", ["Crocolisk Skin (Provided)"] = "шкура кроколіска (видано)" } },
    [3861] = { [1] = "КУДАХ!", [2] = "\"Куд... куд... куд... КУДАХ!\n\nКуд... куд... куд.\"\n\nКурка дивиться на вас, а потім починає дряпати кігтями землю. Здається, вона виписує якесь слово, але ви не впевнені, яке саме. Чи може це... С-А-Л-Д-Е-Н? Перш ніж ви встигаєте запитати, курка повертається і йде по своїм справам.", [3] = "Знайдіть спеціальний курячий корм і поверніться до курки, з якою ви подружилися. Знайшовши його, привітайтеся (/cheer) з ним, перш ніж давати йому спеціальний курячий корм.", [4] = "Курка дивиться на вас темними, холодними очима. Вона голодна.\n\n\"КУДАХ!\n\nКуд... куд... куд...\"", [5] = "\"КУДАХ!\"\n\nКурка починає поїдати корм, який ви їй дали.\n\nЧерез мить курка злякано оглядається. Починає шкребти лапою і метушитися. Може вона хоче знести яйця? Певно варто зазирнути під неї.", ["en"] = "CLUCK!", ["tasks"] = { ["Special Chicken Feed"] = "спеціальний курячий корм", ["Special Chicken Feed (Provided)"] = "спеціальний курячий корм (видано)" } },
    [3881] = { [1] = "Порятунок експедиції", [2] = "Я не знаю, як ти сюди {стать:потрапив:потрапила}, але ми раді тобі! Мене звати Вілліден Маршал і я очолюю незалежну експедиційну групу. Остання та найважливіша наша кампанія натрапила на купу труднощів. Мабуть, найбільш суттєвим нашим прорахунком було те, що ми недооцінили небезпеку кратера Ун'Ґоро!\n\nКоли ми тікали з наших таборів на південному заході й північному сході кратера, ми залишили життєво важливі припаси. Ти виглядаєш дуже переконливо — чи можеш ти допомогти нам повернути їх?", [3] = "Принесіть ящик з провізією та дослідницьке обладнання Віллідену Маршалу в кратер Ун'Ґоро.", [4] = "Якщо ми хочемо мати хоч якийсь шанс вибратися звідси живими, нам знадобиться наш ящик з провізією. Крім того, повернення хоча б частини нашого дослідницького обладнання було б благословенням.", [5] = "Ти {стать:повернув:повернула} як їжу, так і наше дослідницьке обладнання! Ти просто {стать:врятував:врятувала} нашу експедицію — ти {стать:врятував:врятувала} наші життя. Завдяки тобі, ми, можливо, зможемо протриматися тут ще деякий час.\n\nХоч ми тут небагаті, ти не залишишся без нагороди за таку надзвичайну допомогу. Дякую, {ім'я}. І знай, що твої друзі з експедиції Маршала завжди раді допомогти тобі!", ["en"] = "Expedition Salvation", ["tasks"] = { ["Crate of Foodstuffs"] = "ящик з провізією", ["Crate of Foodstuffs (Provided)"] = "ящик з провізією (видано)", ["Research Equipment"] = "дослідницьке обладнання", ["Research Equipment (Provided)"] = "дослідницьке обладнання (видано)" } },
    [3882] = { [1] = "Кидай кості", [2] = "Можливо, ти думаєш, що я люблю копати, бо я старший землекоп в експедиції Маршала? Можливо, є гірші речі у цьому світі... але мені наразі нічого такого в голову не приходить.\n\nМи мали копати в Жахогоні — ФАНТАСТИЧНА назва до речі — для решток стегодонів та деметродонів. Але там також досить багато живих істот. Віл та Хол все ще в захваті від вивчення цієї смертельної пастки, тому нам потрібні кістки динозаврів. Але, чесно кажучи, кістки живих динозаврів також підійдуть.", [3] = "Принесіть 8 кісток динозавра Іскру Ніцокопу в кратер Ун'Ґоро.", [4] = "Думай про мене що хочеш, але їм байдуже, чи ти добудеш ці кістки з решток древніх стегодонів та деметродонів, чи з тих, що майже поїли нас, коли ми намагалися розставити наші табори. Я просто буду радий, якщо ми виживемо тут...", [5] = "Чудово, ці кістки підійдуть. І зараз, якщо ти дозволиш мені...\n\nДЯКУЮ ЗА ВИКОПУВАННЯ ВСІХ ЦИХ КІСТОК З ЗЕМЛІ ДЛЯ НАС І ЗА ТЕ ЩО НЕ {стать:ЗАВДАВ:ЗАВДАЛА} ШКОДИ МІСЦЕВИМ ЗВІРЯМ.\n\nНезалежно від того, чи ти {стать:зробив:зробила} це, чи ні, я не хочу знати. Давай це так і залишимо, добре? Ось — може, це заткне тобі рот. Я готовий на все, щоб вижити тут!", ["en"] = "Roll the Bones", ["tasks"] = { ["Dinosaur Bone"] = "кістка динозавра", ["Dinosaur Bone (Provided)"] = "кістка динозавра (видано)" } },
    [3883] = { [1] = "Екологія чужинців", [2] = "Те, що ми зазнали невдачі, не означає, що ми маємо припинити дослідження! Ми досліджували комах Ґоріші в південній частині кратера, перш ніж опинилися тут. Їхня присутність є незвичайною для екології Ун'Ґоро, і ми хочемо з'ясувати, чому вони тут з'явилися.\n\nУ їхніх вуликах мають бути інкубатори для личинок. Ти впізнаєш ці місця за висячими гронами личинок. Збери зразок зі стіни інкубатора в цей флакон і принеси його мені для дослідження. Але будь {стать:обережний:обережна}!", [3] = "Зберіть зразок зі стіни одного з вуликів Ґоріші в кратері Ун'Ґоро. Шукайте у вуликах кімнати з гронами личинок.\n\nПринесіть зразок Холанії Маршал в кратер Ун'Ґоро.", [4] = "Ти {стать:приніс:принесла} зразок вулика Ґоріші для моїх досліджень, {ім'я}?", [5] = "Так, це чудовий зразок. Ти дуже {стать:допоміг:допомогла} мені... Я хотіла б дати тобі велику нагороду, але життя в дикій природі накладає свої обмеження. Однак без твоєї допомоги наші дослідження були б неможливі.", ["en"] = "Alien Ecology", ["tasks"] = { ["Hive Wall Sample"] = "зразок стіни вулика", ["Hive Wall Sample (Provided)"] = "зразок стіни вулика (видано)" } },
    [3884] = { [1] = "Щоденник Віллідена", [2] = "Ви знайшли подертий щоденник. Деякі сторінки ще можна прочитати, і в ньому указано, що його власником є Вілліден Маршал. Якщо вірити щоденнику, то Віллідена можна знайти десь в північній частині кратера, куди він та його товариші втекли від жорстоких звірів кратера, коли їхні табори були захоплені.", [3] = "Поверніть щоденник Віллідену Маршалу десь у кратері Ун'Ґоро.", [4] = "Вітаю! Я і мої супутники раді бачити тут якихось живих істот, окрім диких звірів-переростків! Що привело тебе в кратер Ун'Ґоро?", [5] = "Це ж мій щоденник! Я думав, що він загубився, як і майже все інше, що ми привезли в Ун'Ґоро. Щиро дякую, що {стать:повернув:повернула} його мені!", ["en"] = "Williden's Journal", ["tasks"] = { ["A Mangled Journal"] = "подертий щоденник", ["A Mangled Journal (Provided)"] = "подертий щоденник (видано)" } },
    [3885] = { [1] = "<NYI> <TXT> Забіг Гаджетзана", [2] = "Супроводжуйте мене та Дадангу!", ["en"] = "<NYI> <TXT> The Gadgetzan Run", ["tasks"] = { ["Escort Petra and Dadanga!"] = "Ескорт Петри та Даданги!" } },
    [390] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [3906] = { [1] = "Дисгармонія полум'я", [2] = "Старійшини відчули неспокій серед стихій. Дворфи Темного Заліза викликали в наш світ злісного духа, який загрожує погубити наші землі вічною посухою. Цю дисгармонію полум'я необхідно дослідити.\n\nВирушай в Чорноскельну гору, через Полум'яну безодню, до каменоломні. Там ти знайдеш повелителя вогню Пірона.\n\nПоклади край його злодіянням і повертайся до мене.", [3] = "Відправляйтеся до каменоломні Чорноскельної гори та вбийте повелителя Пірона. Поверніться до Громосерда, коли виконаєте це завдання.", [4] = "Стихії досі неспокійні, {ім'я}.", [5] = "Цього не може бути... цього не має бути. Знищення Пірона лише відкрило істинний стан речей. У глибинах Чорноскельної гори ховаються набагато підступніші сили.", ["en"] = "Disharmony of Flame", ["tasks"] = { ["Overmaster Pyron"] = "повелитель Пірон", ["Overmaster Pyron slain"] = "повелитель Пірон: убито" } },
    [3908] = { [1] = "Це таємниця для всіх", [2] = "Розумієш, я не пам'ятаю, як я потрапив сюди. Ніхто не знає — це таємниця для всіх! Я просто не можу нічого пригадати...\n\nАле ці речі, які ти {стать:приніс:принесла} мені... Я починаю щось згадувати.\n\nМій меч. Я повинен був якось посилити його, але не знаю, чому. Вибач, що не можу розповісти більше, але я просто не пам'ятаю!\n\nТа все одно, я знаю, куди ти можеш його віднести — до Донови Снігосхов в Зимоключ. Ти знайдеш її біля гарячих джерел. Вона може загартувати меч у тамтешніх джерелах.", [3] = "Віднесіть меч Лінкена Донові Снігосхов у Зимоключ.", [4] = "Ого... Лінкен нарешті прислав мені свій меч.", [5] = "Звісно, я можу загартувати цей меч. Поки я працюю, ти можеш пояснити, чому Лінкен так довго не передавав його мені. Він не з тих, хто забуває щось...", ["en"] = "It's a Secret to Everybody", ["tasks"] = { ["Linken's Training Sword"] = "тренувальний меч Лінкена", ["Linken's Training Sword (Provided)"] = "тренувальний меч Лінкена (видано)" } },
    [3909] = { [1] = "Еліксир Відере", [2] = "Що? Як? Лінкен... ЗАБУВ?\n\nА, ясно... Втратив пам'ять...\n\nЩо ж, ось його меч. Він не завершений. Я знаю, хто може завершити його, але... Поговорити з ним — непросте завдання.\n\nПослухай, я знаю декого, хто може тобі допомогти. Не вдаватимуся до подробиць, але тобі потрібно знайти еліксир Відере. Єдиний, хто може допомогти тобі з цим — це Ґреґан Брагохляп. Його нелегко відшукати, але я чула, що його нещодавно бачили у лісах Фераласа.", [3] = "Знайдіть Ґреґана Брагохляпа на півночі Фераласу. Від нього ви дізнаєтеся, як можна здобути еліксир Відере, а потім поверніться до Донова Снігосхов у Зимоключ.", [4] = "Вже {стать:повернувся:повернулася}?", [5] = "Мені потрібен один флакон, щоб переконатися, що це дійсно цей еліксир... Так... Це те, що треба.", ["en"] = "The Videre Elixir", ["tasks"] = { ["Videre Elixir"] = "еліксир Відере", ["Videre Elixir (Provided)"] = "еліксир Відере (видано)" } },
    [3911] = { [1] = "Останній елемент", [2] = "Є робота для тих, хто наважиться спуститися в глибини, {ім'я}.\n\nКлан Темного Заліза навчився створювати надзвичайно потужних големів.\n\nСудячи з повідомлень від наших шпигунів, все вказує на те, що дворфи використовують унікальне джерело енергії, щоб наділити свої творіння надзвичайно вбивчою силою.\n\nТільки уяви, що б ми могли зробити з нашими потворами, якби роздобули цю сутність стихій! Переверни це місто догори дном, якщо потрібно, але не повертайся, доки не знайдеш сутність! Винагорода буде варта такого ризику.", [3] = "Відправляйтеся в Чорноскельні надра та відшукайте 10 сутностей стихій. Певно, найкраще почати пошуки з големів та їхніх творців. Ви також пригадуєте, що Вівіан Лягроб також бурмотіла щось про елементалів.", ["en"] = "The Last Element", ["tasks"] = { ["Essence of the Elements"] = "сутність стихій" } },
    [3912] = { [1] = "Зустріч на кладовищі", [2] = "Це зілля дозволить тобі спілкуватися з тим, кого зазвичай навіть не видно...\n\nВізьми зі собою еліксир Відере та меч Лінкена до кладовища, що знаходиться поблизу Пристробляху у Танарісі. Коли будеш там, випий еліксир. Результат може тебе сильно здивувати, але не панікуй.\n\nУ своїй \"іншій\" формі рушай на північ, аж доки не дістанешся до гір. Ти знайдеш його в одному з кам'яних щілин. Його звати Ґаєріан.\n\nПам'ятай, він розмовлятиме з тобою тільки в тій формі...", [3] = "Вирушайте на кладовище поблизу Пристробляху та випийте еліксир Відере. Дотримуйтесь решти інструкцій Донови, щоб знайти Ґаєріана.", [5] = "Давно вже ніхто зі мною не розмовляв...", ["en"] = "Meet at the Grave", ["tasks"] = { ["Linken's Tempered Sword"] = "загартований меч Лінкена" } },
    [3913] = { [1] = "Пошуки могили", [2] = "Коли повернешся на цвинтар, {ім'я}, то знайдеш там надгробок... Та не звичайний надгробок. Він вирізнятиметься з-поміж інших. У ньому криється таємниця.\n\nНатисни на надгробок, і ти дізнаєшся його таємниці...", [3] = "Поверніться у світ живих та знайдіть надгробок, про який казав Ґаєріан.", [4] = "Це, мабуть, той надгробок, про який згадував Ґаєріан...", [5] = "Ви сильно натискаєте на надгробок, і він відсувається, відкриваючи невелике заглиблення.\n\nПоклавши в нього меч Лінкена, ви розумієте, що він ідеально підходить...", ["en"] = "A Grave Situation", ["tasks"] = { ["Linken's Tempered Sword"] = "загартований меч Лінкена", ["Linken's Tempered Sword (Provided)"] = "загартований меч Лінкена (видано)" } },
    [3914] = { [1] = "Меч Лінкена", [2] = "Навколо меча спалахує яскраве світло. Після того як воно згасло, ви знову можете взяти меч. Він змінився!", [3] = "Віднесіть покращений меч Лінкена Лінкену в кратер Ун'Ґоро.", [4] = "О! Я пам'ятаю тебе! Ти... Ні, не підказуй!", [5] = "Мій меч... Він завершений!\n\nТепер, якби я тільки міг згадати, навіщо він мені потрібен...\n\nОсь, дозволь мені хоча б заплатити за твою роботу.", ["en"] = "Linken's Sword", ["tasks"] = { ["Linken's Superior Sword"] = "покращений меч Лінкена", ["Linken's Superior Sword (Provided)"] = "покращений меч Лінкена (видано)" } },
    [3941] = { [1] = "Допомога гномів", [2] = "Думаю... Думаю... Я знаю, що я прийшов сюди з якоюсь важливою метою...\n\nУ мене є ідея, {ім'я}. У печері неподалік знаходиться гномка, на ім'я Джей Ді, яка була дуже люб'язна до мене, коли я тут з'явився. Можливо, я щось розказував їй.\n\nЧому б тобі не піти та запитати її, чи вона щось знає? О, але будь {стать:обережним:обережною} — вона завжди працює з цими дивними кристалами, яких багато у кратері. Я не зовсім розумію, навіщо вони їй потрібні.", [3] = "Знайдіть Джей Ді Коллі в печері в прихистку Маршала.", [5] = "Стій, де стоїш, хвилинку... Я випробовую нову комбінацію кристалів.", ["en"] = "A Gnome's Assistance" },
    [3942] = { [1] = "Пам'ять Лінкена", [2] = "А... Лінкен? Так, смішний хлопець. Коли він вперше з'явився тут, він бурмотів про всякі дивні речі. Мабуть, його сильно вдарили по голові.\n\nАле є дещо, що я запам'ятала — він говорив, що майструє якийсь тотем. Сказав, що йому потрібно поговорити з кимось, на ім'я Ерідана Блакитновій... в місці, під назвою Сквернолісся, якщо не помиляюсь.\n\nСумніваюсь, що він зможе щось розповісти про це. Тож якщо хочеш дізнатися більше, гадаю, тобі варто знайти цю Ерідану.", [3] = "Знайдіть Ерідану Блакитновій на півдні Сквернолісся.", [5] = "Вітаю, {клас:к}. Чим я можу тобі допомогти?", ["en"] = "Linken's Memory" },
    [3961] = { [1] = "Пригоди Лінкена", [2] = "Особисто я вважаю, що Лінкен прийшов сюди, щоб позбавити нас від Жаропломеня... Він здається таким звичайним хлопцем, але я помітила, що він зовсім не цікавиться моїми експериментами чи пристроями, як це робили інші гноми. В нього, мабуть, серце справжнього воїна.\n\nВіднеси йому цей тотем. Подивись, чи допоможе це йому згадати, чому він прийшов сюди.", [3] = "Віднесіть срібний тотем Акваментаса Лінкену в прихисток Маршала.", [4] = "І знову привіт, {ім'я}!", [5] = "Джей Ді допомогла тобі?", ["en"] = "Linken's Adventure", ["tasks"] = { ["Silver Totem of Aquementas"] = "срібний тотем Акваментаса", ["Silver Totem of Aquementas (Provided)"] = "срібний тотем Акваментаса (видано)" } },
    [3962] = { [1] = "Небезпечно йти одному", [2] = "{ім'я}, я нарешті згадав... Я дійсно прийшов сюди, щоб битися з Жаропломенем. Це і є мета моєї подорожі!\n\nАле я вже не герой... Ти ним {стать:став:стала}. Ти так багато {стать:зробив:зробила} — це ти {стать:повинен:повинна} завершити цю справу.\n\nЖаропломінь стереже артефакт, що називається золотим полум'ям. У ньому криється сила потужніша, ніж будь-що мені відоме, тому цей артефакт не повинен потрапити в погані руки.\n\nІ моя тобі порада — не ходи {стать:один:одна}.", [3] = "Вирушайте до Вогнеперої скелі, на південь від прихистку Маршала.\n\nЗнайдіть Жаропломеня і використайте тотем, щоб розсіяти захисну ауру. Коли він буде переможений, візьміть золоте полум'я з печери.", [4] = "Жаропломінь майже непереможний під дією аури, яку йому дає золоте полум'я. Тільки ти можеш розсіяти цю ауру за допомогою срібного тотема Акваментаса.", [5] = "Дякую, {ім'я}.\n\nЗолоте полум'я повернеться до моєї батьківщини, де його можна буде захистити, щоб воно ніколи більше не використовувалося злом.\n\nБез тебе я б все ще не знав, хто я є! Оскільки ти {стать:зробив:зробила} так багато для мене, я хочу дати тобі щось особливе...\n\nВибирай будь-що!", ["en"] = "It's Dangerous to Go Alone", ["tasks"] = { ["Blazerunner"] = "Жаропломінь", ["Blazerunner slain"] = "Жаропломінь: убито", ["Golden Flame"] = "золоте полум'я", ["Golden Flame (Provided)"] = "золоте полум'я (видано)", ["Silver Totem of Aquementas"] = "срібний тотем Акваментаса", ["Silver Totem of Aquementas (Provided)"] = "срібний тотем Акваментаса (видано)" } },
    [397] = { [1] = "За твою гарну службу", [2] = "Я чув, що лорду Вішоку сподобався напій.\n\nТепер чорнокнижники Штормовію зможуть займатись своїми справами без зайвих турбот. Я приготував чудову нагороду за твою гарну службу. Ти можеш забрати її у Зґґі.", [3] = "Поговоріть зі Зґґі, прислужником Зардета Чорного Кігтя, щоб отримати винагороду.", [5] = "Повелитель наказав передати {ім'я} цей подарунок. Зґґі хоче залишити його собі, та Зґґі знає, що буде за зраду повелителя.", ["en"] = "You Have Served Us Well" },
    [4005] = { [1] = "Акваментас", [2] = "Візьміть цей мішок припасів з собою в Танаріс. Рушай до бухти Загубленого Вітрила і шукай коло з каменів.\n\nВоно на найсхіднішому півострові...\n\nВ цьому колі тобі потрібно прочитати закляття з книги Аквора. Виклич єдине створіння, здатне перетворити зібрані тобою предмети на тотем, за допомогою якого можна вбити Жаропломеня.\n\nАкваментас не буде радий пробудженню, але пам'ятай, ти маєш залишатися в колі, щоб він міг перетворити предмети.", [3] = "Віднесіть книгу Аквора, сріблясті пазурі та залізодеревне серце в Танаріс.\n\nВикористайте книгу Аквора, щоб викликати Акваментаса.\n\nОтримавши завершений тотем, віднесіть його до Джей Ді Коллі в прихисток Маршала.", [4] = "То ти {стать:повернувся:повернулася}? Хм... Дозволь мені поглянути на це, {ім'я}.", [5] = "Жаропломінь, кажеш...\n\nТак, я знаю, що у центрі кратера проживає сильний елементаль. Ми всі тримаємося якомога далі. Ніхто не зміг пробитись через потужну ауру, що оточує його. Багато народу знайшло свою смерть в серці кратера.", ["en"] = "Aquementas", ["tasks"] = { ["Silver Totem of Aquementas"] = "срібний тотем Акваментаса", ["Silver Totem of Aquementas (Provided)"] = "срібний тотем Акваментаса (видано)" } },
    [402] = { [1] = "Сірра зайнятий", [2] = "Вибач, але зараз наше місто під загрозою, тож у мене є інші обов'язки. Можливо, пізніше, якщо ми виживемо, я зможу закінчити цей переклад.", [3] = "Зайдіть до Сірри пізніше та дізнайтеся, чи він все ще зайнятий.", ["en"] = "Sirra is Busy" },
    [4022] = { [1] = "Смак полум'я", [2] = "Крило знає про твою роботу в Випаленій ущелині.\n\nПокажи її мені, {раса:к}. Скинуту шкіру, {стать:ідіот:ідіотка}.", [3] = "Покажіть Киру Покаянному скинуту шкіру чорного дракона, яку ви отримали від Веларока Вітроріза.", [4] = "<Очі Кира спалахують, мов дві вогняні кулі.>", [5] = "<Кир розглядає шкіру.>\n\nТи {стать:довів:довела}, що ти не зовсім {стать:пропащий:пропаща}, {стать:смертний:смертна}.", ["en"] = "A Taste of Flame", ["tasks"] = { ["Black Dragonflight Molt"] = "скинута шкіра чорного дракона", ["Black Dragonflight Molt (Provided)"] = "скинута шкіра чорного дракона (видано)" } },
    [4023] = { [1] = "Смак полум'я", [2] = "Ти шукаєш крило? Докажи мені, що ти {стать:гідний, смертний:гідна, смертна}.", [3] = "Покажіть Киру Покаянному доказ вашої гідності.\n\nУ вас є відчуття, що Кир знає, що ви не гідні.", [4] = "<Очі Кира спалахують, мов дві вогняні кулі.>", [5] = "<Кир розглядає шкіру.>\n\nТи {стать:довів:довела}, що ти не зовсім {стать:пропащий:пропаща}, {стать:смертний:смертна}.", ["en"] = "A Taste of Flame", ["tasks"] = { ["Black Dragonflight Molt"] = "скинута шкіра чорного дракона", ["Black Dragonflight Molt (Provided)"] = "скинута шкіра чорного дракона (видано)" } },
    [4024] = { [1] = "Смак полум'я", [2] = "Я хочу скуштувати пекуче полум'я вогняної гори. Відчути, як все моє тіло пронизує її вогонь. Ця сутність, цей палючий жар — ось, що мені потрібно.\n\nБель'Ґар мешкає в Чорноскельних надрах, він — це втілення чистого полум'я, народжене з вогню Раґнароса. Вбий Бель'Ґара та візьми з його обвуглених решток частинку його внутрішнього вогню.\n\nЩоб безпечно витягти внутрішній вогонь з його решток, використай шкуру дракона.\n\nВпорайся з цим і отримаєш велику нагороду.", [3] = "Відправляйтеся в Чорноскельні надра та вбийте Бель'Ґара.\n\nВам відомо лиш те, що велетень перебуває в Чорноскельних надрах. Використайте змінену шкуру чорного дракона на останках Бель'Ґара, щоб захопити його вогняну сутність.\n\nВіднесіть захоплену вогняну сутність Киру Покаянному.", [4] = "Велетень вже мертвий?", [5] = "<Кир вихоплює вогняну сутність з ваших рук.>\n\nТАК!\n\nЗабирай свою нагороду та йди. Геть з моїх очей!", ["en"] = "A Taste of Flame", ["tasks"] = { ["Encased Fiery Essence"] = "захоплена вогняна сутність", ["Encased Fiery Essence (Provided)"] = "захоплена вогняна сутність (видано)" } },
    [403] = { [1] = "Барильце громузвару під охороною", [5] = "Ель охороняє Ярвен Громовар. Поки він знаходиться в підвалі, до жодного барильця не дістатися.", ["en"] = "Guarded Thunderbrew Barrel" },
    [4041] = { [1] = "Еліксир Відере", [4] = "Принеси мені духокорінь, і я зроблю для тебе еліксир Відере.\n\nЯ знаю багато про трави й алхімію... Дозволь розказати тобі історію про те, як я був голодний і перетворив золото на сир... Гей, ти куди?", [5] = "Хех, швидко ти {стать:обдурив:обдурила} старого Міблона.", ["en"] = "The Videre Elixir", ["tasks"] = { ["Evoroot"] = "духокорінь", ["Evoroot (Provided)"] = "духокорінь (видано)" } },
    [406] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [4083] = { [1] = "Примарна чаша", [4] = "Примарна чаша витає в повітрі, повільно піднімаючись та опускаючись... немов у ритм биття вмирущого серця.", [5] = "Самоцвіти беззвучно падають в глиб чаші...", ["en"] = "The Spectral Chalice", ["tasks"] = { ["Gold Bar"] = "злиток золота", ["Gold Bar (Provided)"] = "злиток золота (видано)", ["Star Ruby"] = "зоряний рубін", ["Star Ruby (Provided)"] = "зоряний рубін (видано)", ["Truesilver Bar"] = "злиток ясносрібла", ["Truesilver Bar (Provided)"] = "злиток ясносрібла (видано)" } },
    [4084] = { [1] = "Срібне серце", [2] = "Я не знаю того, про кого ти говориш, {ім'я}.\n\nАле не хвилюйся. Якщо твій друг шукав мене, я знаю, чого він хотів.\n\nУ серці кратера Ун'Ґоро проживає зло в найчистішій формі. Це зло набуло форми елементаля, на ім'я Жаропломінь... Він захищений аурою, яку ніхто не може розвіяти...\n\nНіхто... окрім тих, хто має достатньо сили, щоб це зробити. Я можу навчити тебе цій силі, {ім'я}.\n\nСпочатку зроби, як я тобі кажу. Збери 11 сріблястих пазурів і 1 залізодеревне серце у створінь Сквернолісся, а потім повертайся до мене.", [3] = "Зберіть 11 сріблястих пазурів і 1 залізодеревне серце для Ерідани Блакитновій у Скверноліссі.", [4] = "Я можу розповісти тобі більше про силу, необхідну для перемоги над Жаропломенем, але спершу ти маєш зібрати необхідні мені речі.", [5] = "Дуже добре, {ім'я}. Я бачу, що ти справді хочеш допомогти своєму другові.", ["en"] = "Silver Heart", ["tasks"] = { ["Irontree Heart"] = "залізодеревне серце", ["Irontree Heart (Provided)"] = "залізодеревне серце (видано)", ["Silvery Claws"] = "сріблясті пазурі", ["Silvery Claws (Provided)"] = "сріблясті пазурі (видано)" } },
    [4101] = { [1] = "Очищення Сквернолісся", [2] = "Рослини дають життя Скверноліссю, хоча навіть вони вражені скверною. Я знаю способи їх очищення, але не можу ділитися такими знаннями з тими, кого не знаю, чи кому не довіряю. Доведи мені, що ти дійсно {стать:союзник:союзниця} Кенарійського Кола!\n\nНа північ звідси знаходяться печери Залізолісся. На очищення тамтешніх елементалів, Хибнодревів, вже немає надії. Я прошу тебе принести мені їхню застиглу смолу, кривавий бурштин. Сподіваюсь, що вивчивши його, ми зможемо врятувати інші тутешні форми життя.", [3] = "Принесіть 15 кривавих бурштинів Аратандріс Срібнонебесній у Сквернолісся.", [4] = "Я знаю, що Сквернолісся страждає, {ім'я} — я страждаю разом з ним! Але я маю залишатись стійкою у своїх переконаннях — якби мої знання зцілення потрапили в злі руки, це стало б катастрофою для всього Сквернолісся.\n\nПринеси мені кривавий бурштин з убитих Хибнодревів, і я повірю, що ти щиро допомагаєш мені в пошуках засобу боротьби зі скверною.", [5] = "Цей кривавий бурштин допоможе мені знайти засіб боротьби з заразою, що вразила Сквернолісся. Ти {стать:довів:довела} мені, що {стать:готовий:готова} зробити все для Кенарійського Кола. Тепер я довіряю тобі.\n\nМоже здатися дивним, що доказом твоєї відданості стало винищення елементалів, але порятунок безлічі живих істот виправдовує такі засоби. Тепер ми з тобою можемо зосередитись на порятунку життів за допомогою бальзамів, які я можу створити.\n\n{ім'я}, настав час очистити Сквернолісся.", ["en"] = "Cleansing Felwood", ["tasks"] = { ["Blood Amber"] = "кривавий бурштин", ["Blood Amber (Provided)"] = "кривавий бурштин (видано)" } },
    [4113] = { [1] = "Осквернений піснеквіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на піснеквіт. Плоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите кенарійський бальзам зцілення рослин на піснеквіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Songflower", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4114] = { [1] = "Осквернений піснеквіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на піснеквіт. Плоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите кенарійський бальзам зцілення рослин на піснеквіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Songflower", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4115] = { [1] = "Осквернений вітроцвіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на вітроцвіт. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите дві порції кенарійського бальзаму зцілення рослин на вітроцвіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Windblossom", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4116] = { [1] = "Осквернений піснеквіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на піснеквіт. Плоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите кенарійський бальзам зцілення рослин на піснеквіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Songflower", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4117] = { [1] = "Осквернений кнутокорінь", [4] = "Ви знайшли хвору, осквернену рослину, схожу на кнутокорінь. ЇЇ корені виглядають жорсткими та шкірястими, а вся рослина вкрита слизом. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите три порції кенарійського бальзаму зцілення рослин на кнутокорінь. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Whipper Root", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4118] = { [1] = "Осквернений піснеквіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на піснеквіт. Плоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите кенарійський бальзам зцілення рослин на піснеквіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Songflower", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4119] = { [1] = "Осквернений нічний дракон", [4] = "Ви знайшли хвору, осквернену рослину, схожу на нічного дракона. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите чотири порції кенарійського бальзаму зцілення рослин на нічного дракона. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Night Dragon", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4123] = { [1] = "Серце гори", [2] = "Вже багатьох років я шукаю один дорогоцінний камінь. Він називається Серцем гори, завбільшки з твій кулак! Дворфи Темного Заліза тримають його у своєму сховищі та, як би я не старався, вони не хочуть мені його продавати.\n\nТому доведеться забрати його силою.\n\nПроберись на нижній ярус Чорноскельних надр, зламай таємний сейф та забери Серце. Для цього тобі треба перемогти вартового Смертохвата, він з'явиться, коли ти відкриєш всі скрині зі скарбами у сховищі!\n\nЩасти вам.", [3] = "Принесіть Серце гори Максворту Суперблиску в Палаючий степ.", [4] = "Ти {стать:приніс:принесла} Серце гори? Воно надзвичайно цінне для мене.", [5] = "Ти {стать:дістав:дістала} Серце! Прекрасно! Воно красивіше, ніж я думав!\n\nБудь ласка, {ім'я}, прийми це як оплату!", ["en"] = "The Heart of the Mountain", ["tasks"] = { ["The Heart of the Mountain"] = "Серце гори", ["The Heart of the Mountain (Provided)"] = "Серце гори (видано)" } },
    [4134] = { [1] = "Втрачений рецепт Громоварів", [2] = "Ходять чутки, що Гарлі Чорнодих з Темного Заліза викрав рецепт елю. Кажуть, що цей ель — громузвар, наповнює великою силою та мужністю тих, хто його вип'є. Нам хотілось би вивчити склад цього напою. Можливо, ми знайдемо інше застосування його властивостям, яке більше відповідатиме цілям відречених.\n\nВирушай в Чорноскельні надра, знайди Гарлі, забери у нього рецепт Громоварів та принеси мені.\n\nАле щоб виманити Гарлі тобі, можливо, доведеться знищити його дорогоцінний ель.", [3] = "Принесіть втрачений рецепт Громоварів до Вівіан Лягроб в Карґат.", [4] = "Ти {стать:дістав:дістала} рецепт Громоварів, {ім'я}?", [5] = "Дуже добре. Я відправлю цей рецепт в Апотекарій для вивчення, і з часом ми розкриємо його секрети. Одного дня дворфи Альянсу виявлять, що властивості їхнього ж напою обернулись проти них самих!\n\nЯк на мене, це страшенно кумедно. Можливо, смерть якось впливає на почуття гумору, як гадаєш?", ["en"] = "Lost Thunderbrew Recipe", ["tasks"] = { ["Lost Thunderbrew Recipe"] = "втрачений рецепт Громоварів", ["Lost Thunderbrew Recipe (Provided)"] = "втрачений рецепт Громоварів (видано)" } },
    [4136] = { [1] = "Рібблі Гвинтокран", [2] = "Мій брат Рібблі завжди витягував гроші з нашої сім'ї та постійно витрачав їх різні махінації.\n\nЩо ж, остання його витівка, мабуть, була найгіршою, бо барон Ревілґаз з Грабіжної Бухти щойно призначив винагороду за голову бідолашного Рібблі. Не можу передати, як зраділи всі Гвинтокрани! Нарешті наш маленький Рібблі чогось вартий!\n\nАле зараз він ховається глибоко в Чорноскельних надрах. Прошу тебе, знайди його і приведи до мене!\n\nА якщо він не захоче йти, то нічого страшного... Просто принеси мені його голову.", [3] = "Принесіть голову Рібблі до Юки Гвинтокран в Палаючий степ.", [4] = "Ти {стать:знайшов:знайшла} Рібблі? Чи хоча б його частинку?", [5] = "Ага! Ти {стать:знайшов:знайшла} його! І... Схоже, що мій молодший брат не захотів прийти за власним бажанням. Шкода. Я хотіла б побачити вираз його обличчя, коли він дізнається, що ми збираємося здати його Ревілґазу.\n\nДякую тобі, {ім'я}. Ти {стать:ощасливив:ощасливила} мою сім'ю. А Рібблі ще ніколи не виглядав таким спокійним.", ["en"] = "Ribbly Screwspigot", ["tasks"] = { ["Ribbly's Head"] = "голова Рібблі", ["Ribbly's Head (Provided)"] = "голова Рібблі (видано)" } },
    [4142] = { [1] = "Візит до Ґреґана", [2] = "Я не зовсім розумію, що з цим робити, {ім'я}. Ці рослини... здається, мають якусь мінімальний розум.\n\nЯ не експерт у цьому питанні. Але я знаю декого, хто може допомогти!\n\nРушай на північ Фераласу і знайди мого товариша, Ґреґана Брагохляпа. Він експерт у цьому питанні.\n\nВпевнений, Ґреґан зможе нам допомогти. Ти знайдеш його в лісі. Він не з тих, хто полюбляє великі міста.", [3] = "Віднесіть кровоцвіт Ґреґану Брагохляпу в Фералас.", [4] = "Я живу тут, у лісі... Спокійно.\n\nПринаймні, я так думав. До мене сюди приходить більше відвідувачів, ніж коли я жив у Залізогарті!", [5] = "Кровоцвіт, ге? Хм... Що ж, краще поясни, чого ти хочеш, і тоді я скажу, чи зможу тобі допомогти.", ["en"] = "A Visit to Gregan", ["tasks"] = { ["Bloodpetal"] = "кровоцвіт", ["Bloodpetal (Provided)"] = "кровоцвіт (видано)" } },
    [4143] = { [1] = "Туман зла", [2] = "Правду кажучи, {ім'я}, я ніколи не бачив таких рослин у своїх подорожах. Можливо, мені варто сходити в цей кратер...\n\nВ будь-якому випадку, я знаю саме те, що потрібно Муїджіну — туман Атал'ай. Це жахлива штука, її важко зібрати, але це саме те, що йому потрібно, щоб контролювати цих маленьких монстрів.\n\nЙди до храму Атал'Гаккар у болоті Скорботи. Туман Атал'ай можна зібрати з глибинних маскунів, болотяних червів або слизнів, що там зустрічаються. Удачі, {ім'я}!", [3] = "Зберіть 5 зразків туману Атал'ай, а потім поверніться до Муїджіна в кратер Ун'Ґоро.", [4] = "Ларіон досі зі мною не розмовляє! Скільки ж можна ображатись?", [5] = "Зізнаюся, я трохи вагаюся, чи варто торкатися цієї штуки, {ім'я}! Але якщо Ґреґан каже, що це спрацює, то я готовий спробувати!", ["en"] = "Haze of Evil", ["tasks"] = { ["Atal'ai Haze"] = "туман Атал'ай", ["Atal'ai Haze (Provided)"] = "туман Атал'ай (видано)" } },
    [4144] = { [1] = "Паростки кровоцвіту", [4] = "Ось план, {ім'я}: йди та збери кілька паростків кровоцвіту — ну, тих рослин, які ще не виросли, і принеси їх сюди. Потім я побачу, що з ними може зробити туман Атал'ай.\n\nТи можеш подумати, що я мстивий... І насправді ти маєш рацію!\n\nРіч у тім, що я знаю шлях звідси, але поки Ларіон не визнає, що я мав рацію, я залишаюся тут!\n\nТож вперед, знайди паростки кровоцвіту і ми трохи повеселимося!", [5] = "Ну, почнімо, {ім'я}! Це точно приверне увагу Ларіона!", ["en"] = "Bloodpetal Sprouts", ["tasks"] = { ["Bloodpetal Sprout"] = "паросток кровоцвіту", ["Bloodpetal Sprout (Provided)"] = "паросток кровоцвіту (видано)" } },
    [4148] = { [1] = "Знищувач кровоцвітів", [4] = "Для того, щоб знищувач спрацював, необхідний зразок його цілі — кровоцвіту. Вирушай у кратер і принеси мені паросток кровоцвіту, а я вже налаштую прилад на цих дружків Муїджіна.\n\nЯкби він не був таким упертим, ми могли б вже відправились додому... Ну що ж, я просто покажу йому, що його витівки мене зовсім не турбують!", [5] = "Схоже, що він ідеально працює, {ім'я}. Як ти побачиш одного з цих шкідників, не вагаючись використовуй цей знищувач!", ["en"] = "Bloodpetal Zapper", ["tasks"] = { ["Bloodpetal Sprout"] = "паросток кровоцвіту", ["Bloodpetal Sprout (Provided)"] = "паросток кровоцвіту (видано)" } },
    [4161] = { [1] = "Рецепт калдорай", [2] = "Колись давно нічні ельфи називались калдорай, що означає \"діти зірок\". Дослідження минулого є важливим кроком на твоєму шляху як {клас:р}, {ім'я}, тому слухай уважно, що я тобі скажу.\n\nКалдорай завжди пишалися своєю гармонією з природою. Це означає, що ми беремо від неї лише те, що необхідно, і віддаємо їй сторицею. Ця рівновага нам багато дала, {ім'я}.\n\nЗнайди сім малих павучих лапок — не більше, і повертайся до мене.", [3] = "Зберіть 7 малих павучих лапок для Зарріна в Доланаарі.", [4] = "Пам'ятай про рівновагу, {ім'я}. Я бажаю тобі відкрити в собі розуміння та емпатію до створінь природи.", [5] = "Завжди пам'ятай те, про що я сказав тобі сьогодні, {ім'я}. Ти — частина рівноваги, яку нічні ельфи намагаються зберегти, навіть у такі важкі часи.", ["en"] = "Recipe of the Kaldorei", ["tasks"] = { ["Small Spider Leg"] = "мала павуча лапка", ["Small Spider Leg (Provided)"] = "мала павуча лапка (видано)" } },
    [417] = { [1] = "Помста пілота", [2] = "У своєму журналі Гілдельв писав, що зазнав нападу Свербикігтя, \"величезного крижаного пазуристого ведмедя\". Він відігнав тварину, але та встигла жахливо поранити його.\n\nСудячи зі стану трупа Гілдельва, Свербикіготь, мабуть, повернувся і вбив його.\n\nПроте, у журналі Гілдельв записав своє останнє побажання:\n\n\"Помститися Свербикігтеві\".", [3] = "Вбийте Свербикігтя.\n\nПринесіть його пазур і журнал Гілдельва пілотові Молотоногу.", [4] = "Вітаю, {ім'я}. Чи є у тебе звістка від мого друга Гілдельва?", [5] = "Сумна звістка, Гілдельв був хорошим другом. Хотів би я бути з тобою, коли ти {стать:знайшов:знайшла} звіра, Свербикігтя!\n\nДякую тобі, {ім'я}. Твій вчинок не забудуть пілоти штурмової бригади Залізогарта.", ["en"] = "A Pilot's Revenge", ["tasks"] = { ["Hildelve's Journal"] = "щоденник Гілдельва", ["Hildelve's Journal (Provided)"] = "щоденник Гілдельва (видано)", ["Mangy Claw"] = "зчесаний кіготь", ["Mangy Claw (Provided)"] = "зчесаний кіготь (видано)" } },
    [4182] = { [1] = "Драконяча загроза", [2] = "Життя у Палаючих степах переповнене конфліктами.\n\nПросто подивись на це місце! Ми дуже мало знаємо про те, що трапилося з цими будівлями, але ми знаємо, що колись, до великого вибуху, це все було частиною хребта Багрянокряжових гір.\n\nАле досить жалості! У нас є проблема, {ім'я}. Ти {стать:міг:могла} помітити драконів під цим хребтом. Нам потрібно змусити їх відступити. Вбий якомога більше та повертайся до мене. Якщо тобі вдасться, ми зможемо обміркувати інші речі.", [3] = "Вбийте 15 чорних драконенят, 10 чорних драконідів, 4 чорних драконід і 1 чорного дракончика. Після виконання завдання поверніться до Гелендіса Річкорога.", [4] = "Як проходить полювання на драконів?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Тепер, коли я знаю, що ти вмієш поводитися з драконами, ми можемо поговорити про більш нагальні справи.", ["en"] = "Dragonkin Menace", ["tasks"] = { ["Black Broodling"] = "чорне драконеня", ["Black Broodling slain"] = "чорне драконеня: убито", ["Black Dragonspawn"] = "чорний драконід", ["Black Dragonspawn slain"] = "чорний драконід: убито", ["Black Drake"] = "чорний дракончик", ["Black Drake slain"] = "чорний дракончик: убито", ["Black Wyrmkin"] = "чорна драконіда", ["Black Wyrmkin slain"] = "чорна драконіда: убито" } },
    [4183] = { [1] = "Істинні господарі", [2] = "Ми завжди припускали, що орки Чорнокаменю такі жорстокі від природи. Але те, що ми знайшли тут, відає іншу історію.\n\nСправді, кровожерливість і жага битв дає їм силу, але керують ними дракони чорного крила. Ми підозрюємо, що саме крило чорних драконів збуджує у них лють і злість.\n\nПередай цього листа війту Соломону. Він знає, що треба робити.\n\n<Гелендіс простягає вам запечатаний лист.>", [3] = "Вирушайте в Приозер'я та передайте лист Гелендіса Річкорога війту Соломону.", [4] = "Вітаю, {ім'я}. Ми раніше не зустрічалися? Ти виглядаєш {стать:знайомим:знайомою}.", [5] = "<Війт Соломон відкриває запечатаного листа від Гелендіса і починає читати.>", ["en"] = "The True Masters", ["tasks"] = { ["Helendis Riverhorn's Letter"] = "лист Гелендіса Річкорога", ["Helendis Riverhorn's Letter (Provided)"] = "лист Гелендіса Річкорога (видано)" } },
    [4184] = { [1] = "Істинні господарі", [2] = "Це жахлива новина, {ім'я}. Неважко прийти в розпач, дізнавшись, що твої смертельні вороги — лише пішаки куди страшнішого супротивника. Приозер'я не зможе пережити напад двох сил: орків з клану Чорнокаменю та крила чорних драконів. Якщо Приозер'я впаде, то за ним буде Темноділ і Злотохрестя, а потім, можливо, і Штормовій.\n\nТи маєш негайно передати цю інформацію верховному повелителю Болвару Фордраґону у Штормовій! Якщо Штормовій нам не допоможе, то вже ніщо не зможе допомогти нам.", [3] = "Вирушайте в Штормовій і передайте прошення Соломона верховному повелителю Болвару Фордраґону.\n\nБолвар знаходиться у фортеці Штормовія.", [4] = "Що привело тебе в фортецю Штормовія?", [5] = "Дракони? Неможливо!", ["en"] = "The True Masters", ["tasks"] = { ["Solomon's Plea to Bolvar"] = "прошення Соломона до Болвара", ["Solomon's Plea to Bolvar (Provided)"] = "прошення Соломона до Болвара (видано)" } },
    [4185] = { [1] = "Істинні господарі", [2] = "Це дійсно похмура звістка від Соломона. Але ми не можемо дозволити собі посилати й без того розрізнені війська на допомогу Приозер'ю, ґрунтуючись лише на здогадках. Мені потрібні докази, перш ніж я зможу діяти.\n\nПоговори з леді Престор, {ім'я}. Вона вчена жінка і багато знає про драконів та драконідів. Можливо, вона зможе пролити світло на цю ситуацію.", [3] = "Поговоріть з верховним повелителем Болваром Фордраґоном після розмови з леді Катраною Престор.", [4] = "<Болвар уважно дивиться на вас.>", [5] = "<Болвар підпирає рукою підборіддя, ніби глибоко замислившись.>\n\nЯ поважаю позицію леді Престор, але впевнений, що цієї дилеми існує рішення, яке покладе край усім нашим занепокоєнням.", ["en"] = "The True Masters", ["tasks"] = { ["Advice from Lady Prestor"] = "Поради від леді Престор" } },
    [4186] = { [1] = "Істинні господарі", [2] = "Я наділяю тебе повноваженнями {стать:заступника:заступниця} Штормовію, {ім'я}.\n\nПовертайся до війта Соломона в Приозер'я і передай йому цей указ.", [3] = "Віднесіть указ Болвара війту Соломону в Приозер'я.", [4] = "Є новини від Болвара?", [5] = "Напевно, могло бути й гірше...\n\n<Війт Соломон оглядає вас.>\n\nЗдається, тепер доля Приозер'я лежить на твоїх плечах.\n\n<Ви помічаєте, як війт Соломон починає швидко кліпати. Здається, він плаче.>", ["en"] = "The True Masters", ["tasks"] = { ["Bolvar's Decree"] = "указ Болвара", ["Bolvar's Decree (Provided)"] = "указ Болвара (видано)" } },
    [419] = { [1] = "Зниклий пілот", [2] = "Мій друг і напарник, пілот облогової машини, Морі Гілдельв, пропав в цих горах. Ми шукали рідкісну руду, необхідну для висококласного пороху і під час пошуків загнали його машину на крутий підйом, де вона й зламалася!\n\nГілдельв був впевнений, що руда десь в цих горах, тому залишив мене охороняти машини, а сам пішов далі на своїх двох.\n\nВже пройшло кілька днів, а я чув вночі звірине виття. Морі звісно міцний хлоп'яга, але я переживаю.\n\nПрошу тебе, {ім'я}, знайди його.", [3] = "Знайдіть пілота Гілдельва.", [5] = "Перед вами труп дворфа - понівечений, замерзлий і сильно погризений гірськими хижаками. В руці стиснута книжка з грубо нашкрябаними нотатками Морі Гілдельва. Тіло одягнуте в жилет бригадира, що чудово зберігся.\n\nСхоже що ця жахлива сцена і є місцем кончини пілота.", ["en"] = "The Lost Pilot" },
    [4201] = { [1] = "Любовне зілля", [2] = "Ох, цей біль невзаємного кохання! Мої чари не діють на мого любого рядового Камневузла. Він не кохає мене! Це божевілля!\n\nТи маєш допомогти мені! Ми, сукуби, розуміємось у коханні, і я можу приготувати зілля, яке зруйнує залізні стіни навколо серця Камневузла. Для цього мені знадобиться наступне: листки ґромокрові, величезні срібні жили від скельних велетнів Азшари та вода з джерел Ґолакка, що в кратері Ун'Ґоро. Помісти воду в цей флакон.\n\nПрошу тебе, {ім'я}, допоможи нещасній душі відчути щастя!", [3] = "Принесіть 4 листки ґромокрові, 10 величезних срібних жил і наповнений флакон Наґмари до владарки Наґмари в Чорноскельні надра.", [4] = "Ти {стать:приніс:принесла} інгредієнти? Біль в моєму серці росте з кожним днем!", [5] = "Так, тобі вдалося! Тепер я зможу приготувати своє зілля та закохати Камневузла в себе. Нарешті я причарую його!\n\nДякую тобі, {ім'я:к}. Ти {стать:справжній герой:справжня героїня} кохання!", ["en"] = "The Love Potion", ["tasks"] = { ["Giant Silver Vein"] = "величезна срібна жила", ["Giant Silver Vein (Provided)"] = "величезна срібна жила (видано)", ["Gromsblood"] = "ґромокров", ["Gromsblood (Provided)"] = "ґромокров (видано)", ["Nagmara's Filled Vial"] = "наповнений флакон Наґмари", ["Nagmara's Filled Vial (Provided)"] = "наповнений флакон Наґмари (видано)" } },
    [4221] = { [1] = "Осквернений вітроцвіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на вітроцвіт. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите дві порції кенарійського бальзаму зцілення рослин на вітроцвіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Windblossom", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4222] = { [1] = "Осквернений вітроцвіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на вітроцвіт. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите дві порції кенарійського бальзаму зцілення рослин на вітроцвіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Windblossom", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4223] = { [1] = "Істинні господарі", [2] = "<Війт Соломон зітхає.>\n\nТи маєш повернутися до Палаючого степу, {ім'я}. Як {стать:заступник:заступниця} Штормовію, ти {стать:зобов'язаний:зобов'язана} звітувати маршалу Максвеллу. Щасти тобі.", [3] = "Поговоріть з маршалом Максвеллом у Палаючому степі.", [5] = "<Маршал Максвелл сміється.>", ["en"] = "The True Masters" },
    [4224] = { [1] = "Істинні господарі", [2] = "Що? Думаєш, ти {стать:перший:перша}? Скільки солдатів ми маємо втратити, перш ніж Штормовій почне діяти?\n\nМи зібрали величезну кількість відомостей щодо загрози клану Чорнокаменю до того, як втратили нашого командира, маршала Віндзора. З ним зникла і вся наша цінна інформація.\n\nНам потрібна та документація. Знайди Джона Лахмітника, {ім'я}. Він був з Віндзором, коли на них напали орки Чорнокаменю. Востаннє його бачили в печері на півночі.", [3] = "Поговоріть з Джоном Лахмітником, щоб дізнатися про долю маршала Віндзора. Поверніться до маршала Максвелла, коли виконаєте це завдання.\n\nВи згадуєте, що маршал Максвелл казав вам шукати його в печері на півночі.", [4] = "Ти вже {стать:говорив:говорила} з Джоном?", [5] = "Я міг би тебе попередити, але так не цікаво.", ["en"] = "The True Masters", ["tasks"] = { ["Ragged John's Story"] = "Історія Обірваного Джона" } },
    [4243] = { [1] = "У гонитві за Е-Мі 01", [2] = "На жаль, щось сталося з одним з моїх найвеличніших винаходів. Ти {стать:бачив:бачила} механічних білок, чи не так? Щоб підібратись ближче до мавп кратера Ун'Ґоро, я створила механічну мавпу, яка могла б злитися з їхнім видом. Я назвала її Е-Мі 01.\n\nЇї очі були зроблені з магічних кристалів, через які я могла бачити все, що бачить вона. Вона дісталася до Грибкової печери — лігва мавп, на схід звідси, і саме тоді я й втратила зв'язок з нею. Останнє, що я бачила, — це те, як один з альфа-самців підійшов до неї, щоб привітатись!\n\nДопоможеш мені знайти її?", [3] = "Знайдіть Е-Мі 01 в кратері Ун'Ґоро.", [5] = "Оглянувши Е-Мі 01, ви виявляєте дві глибокі вм'ятини у творінні інженерного мистецтва Карни. Одна вм'ятина прикрашає плече робота, інша — голову.\n\nСхоже, що в машині не залишилося енергії.", ["en"] = "Chasing A-Me 01" },
    [4244] = { [1] = "У гонитві за Е-Мі 01", [2] = "Ретельніше оглянувши робота, ви виявляєте панель, що відкривається. Всередині над дротами ви бачите напис: \"Замінити мітрилову обшивку і вимкнути, а потім увімкнути живлення\".\n\nЦікаво, чи справді полагодити Е-Мі 01 і повернути її Карні Сноходень в прихисток Маршала буде так просто...\n\nНе спробуєте — не дізнаєтесь.", [3] = "Знайдіть мітрилову обшивку і поверніться до Е-Мі 01 в кратер Ун'Ґоро.", [4] = "Панель, в яку необхідно вставити мітрилову обшивку, все ще закрита. Е-Мі 01 залишається нерухомою.", [5] = "Ви знову знімаєте панель з Е-Мі 01 і обережно виймаєте стару мітрилову обшивку, яка, схоже, перегоріла. Нова обшивка легко вставляється на місце. Єдине, що залишилося зробити — це перевести перемикач у положення \"Вимкнено\", а потім назад у положення \"Увімкнено\".", ["en"] = "Chasing A-Me 01", ["tasks"] = { ["Mithril Casing"] = "мітрилова обшивка", ["Mithril Casing (Provided)"] = "мітрилова обшивка (видано)" } },
    [4245] = { [1] = "У гонитві за Е-Мі 01", [2] = "Переконавшись, чи готові ви провести Е-Мі 01 до Карни Сноходень, ви перемикаєте перемикач в положення \"Вимкнено\". Ще раз озирнувшись навколо, щоб переконатися, що жодна з мавп не наближається до вас, ви готуєтесь побачити, що станеться, коли ви повернете перемикач в положення \"Увімкнено\".\n\nЦе ваш останній шанс... ви впевнені, що хочете це зробити?", [3] = "Проведіть Е-Мі 01 до Карни Сноходень в прихисток Маршала.", [4] = "Тобі вдалося допомогти Е-Мі? Та мітрилова обшивка, про яку ти {стать:згадав:згадала}, дійсно могла перегоріти. Впевнена, якщо ти її заміниш, вона відновиться і зможе повернутися додому.", [5] = "О, тобі вдалося! Чудово! Спасибі, {ім'я}.\n\nО, моя бідна Е-Мі. Поглянь на всі ці вм'ятини. Нічого, я полагоджу тебе, будеш як новенька.\n\nЩе раз дякую, {ім'я}. Я тобі дуже вдячна.", ["en"] = "Chasing A-Me 01", ["tasks"] = { ["Protect A-Me 01 until you reach Karna Remtravel"] = "Захищайте A-Me 01, поки не досягнете Карни." } },
    [4261] = { [1] = "Древній дух", [2] = "Сквернолісся колись було мирним і спокійним краєм... Доки Легіон не захопив його. Пекельники, руйнування, хаос...\n\nЧереп Ґул'дана не оминув нікого. Усі піддались впливу скверни.\n\nНавіть зараз, як дух, я почуваюся у пастці, відчуваю страждання цього краю. Допоможи мені знайти шлях додому. Будь ласка, {ім'я}, пообіцяй, що ти відведеш древнього духа туди, де я нарешті знайду спокій.\n\nКоли я буду вільний, поговори з Кейнетом Штилем, друїдом, що мешкає в Лісовій Пісні, на сході.", [3] = "Проведіть Арея в безпечне місце, а потім поговоріть з Кейнетом Штилем в Лісовій Пісні на сході Ясенедолу.", [4] = "Що ти {стать:бачив:бачила} в цих заражених землях?", [5] = "Так, {ім'я}. Сквернолісся пережило багато труднощів. Дякую тобі за те, що ти {стать:зробив:зробила}.\n\nОдного дня ми зможемо очистити Сквернолісся від скверни. Кожна така добра справа допомагає нам.", ["en"] = "Ancient Spirit", ["tasks"] = { ["Help Arei get to Safety"] = "Допоможіть Арею дістатися до безпечного місця" } },
    [4262] = { [1] = "Повелитель Пірон", [2] = "Останні п'ятеро моїх магів, що ходили на розвідку в Чорноскельну гору, повернулися дещо засмаглими — навіть трохи хрусткими...\n\n<Джалінда підіймає з землі попіл і випускає його в повітря.>\n\nОдин мерзенний негідник, повелитель Пірон, схоже, завдає нам чимало клопоту. Нам потрібно знищити цього елементаля, щоб наша експедиція змогла дістатися до надр Чорноскельної гори!\n\nВін охороняє вхід до тамтешньої каменоломні.", [3] = "Убийте повелителя Пірона та поверніться до Джалінди Гілочки.\n\nЗдається, Джалінда казала, що Пірон охороняє каменоломню. Можливо, варто пошукати там?", [4] = "<Джалінда, здається, заглядається на вашу шкіру.>", [5] = "Спалахій? Ой, лишенько...", ["en"] = "Overmaster Pyron", ["tasks"] = { ["Overmaster Pyron"] = "повелитель Пірон", ["Overmaster Pyron slain"] = "повелитель Пірон: убито" } },
    [4281] = { [1] = "Доставка в Таланаар", [2] = "Цей пакунок товарів, який ви знайшли в таборах Дереволапих, мав бути доставлений до невеликого дорожнього табору Таланаар на південному сході Фераласа. Незалежно від долі зниклого кур'єра, завдання доставлення пакунка залишається незавершеним.\n\nОглянувши пакунок, ви бачите на ньому ім'я \"Фалфіндел Шляхостраж\". Можливо, це і є отримувач посилки.", [3] = "Принесіть недоставлений пакунок Фалфінделу Шляхостражу в Таланаар.", [4] = "Ласкаво прошу до Таланаару, {ім'я}. Тобі потрібна якась допомога?", [5] = "Хвала Елуні, посилка з фортеці Перомісяць нарешті прибула!\n\nТвоя присутність вказує мені на те, що, можливо, Раскала, нашого кур'єра, спіткала якась лиха доля. Сподіваюся, що все обійдеться. Я знаю, що останнім часом Дереволапі дуже бояться чогось, що відбувається на півдні. Може, Раскал заблукав у глушині? Будь обережніше.\n\nХай там як, ще раз дякую. Ось плата за доставлення цього пакунка.", ["en"] = "Thalanaar Delivery", ["tasks"] = { ["Undelivered Parcel"] = "недоставлений пакунок", ["Undelivered Parcel (Provided)"] = "недоставлений пакунок (видано)" } },
    [4284] = { [1] = "Кристали сили", [2] = "Я впевнена, що ти {стать:бачив:бачила} їх, {ім'я}. Вони скрізь!\n\nПро що я? Про кристали, звісно ж!\n\nКристали... Вони розкидані по всьому кратеру. Більшість не звертає уваги, але у мене є відчуття, що вони містять потужну силу. Я проводжу з досліди з ними, але мені не вдалось нічого виявити. Ну, принаймні, поки що.\n\nІ, до речі, у мене закінчуються кристали — може, ти зможеш зібрати їх для мене?", [3] = "Зберіть по 7 кристалів сили кожного кольору: червоного, синього, жовтого та зеленого. Принесіть їх Джей Ді Коллі в прихисток Маршала.", [4] = "Я просто знаю, що натрапила на щось важливе, {ім'я}!", [5] = "Тепер я продовжу свої експерименти! Дякую, {ім'я}.", ["en"] = "Crystals of Power", ["tasks"] = { ["Blue Power Crystal"] = "синій кристал сили", ["Blue Power Crystal (Provided)"] = "синій кристал сили (видано)", ["Green Power Crystal"] = "зелений кристал сили", ["Green Power Crystal (Provided)"] = "зелений кристал сили (видано)", ["Red Power Crystal"] = "червоний кристал сили", ["Red Power Crystal (Provided)"] = "червоний кристал сили (видано)", ["Yellow Power Crystal"] = "жовтий кристал сили", ["Yellow Power Crystal (Provided)"] = "жовтий кристал сили (видано)" } },
    [4285] = { [1] = "Північний пілон", [2] = "Для чого вони потрібні? Я не можу перестати думати про них!\n\nЦе зводить мене з розуму — те, що чутки про кристалічні пілони, можуть бути правдою. Можеш вважати мене наївною дурепою, але я вірю майже всьому, що мені кажуть.\n\nВзагалі-то, я чула, що один з них знаходиться досить близько. Десь на півночі... Будь ласка, знайди його, {ім'я}. Я просто знаю, що вони існують.", [3] = "Дізнайтеся, де знаходиться північний кришталевий пілон у кратері Ун'Ґоро.", [4] = "Ти {стать:знайшов:знайшла} пілон, {ім'я}?", [5] = "Я знала, що це правда, {ім'я}.", ["en"] = "The Northern Pylon", ["tasks"] = { ["Discover and examine the Northern Crystal Pylon"] = "Відкрийте та огляньте Північний кришталевий пілон" } },
    [4287] = { [1] = "Східний пілон", [2] = "Я чула про таємничі кришталеві пілони у кратері, {ім'я}. Думаю, що вони досить великі й усіяні кристалами.\n\nХоча я ніколи не бачила жодного з них, я не можу не думати, що ці чутки правдиві — і що пілони мають щось спільне з цими кристалами.\n\nЧому б тобі не допомогти задовольнити мою цікавість? За чутками, один з таких пілонів знаходиться на східній частині кратера. Зможеш його знайти?", [3] = "Дізнайтеся, де знаходиться східний кришталевий пілон у кратері Ун'Ґоро.", [4] = "Ти {стать:знайшов:знайшла} пілон, {ім'я}?", [5] = "Ун'Ґоро — таке дивне місце, {ім'я}. Це ніби зовсім інший світ...", ["en"] = "The Eastern Pylon", ["tasks"] = { ["Discover and examine the Eastern Crystal Pylon"] = "Відкрийте та огляньте Східний кришталевий пілон" } },
    [4288] = { [1] = "Західний пілон", [2] = "Мої дослідження досі не принесли позитивних результатів, {ім'я}. Я сподіваюсь, що ти зможеш допомогти мені, знайшовши один із пілонів, про які я чула.\n\nМожливо, якщо ми поєднаємо біля них кристали певних кольорів... але я надто кваплюсь. Давай спочатку знайдемо їх!\n\n{ім'я}, шукай на заході кратера. Кажуть, що один з пілонів знаходиться десь там.", [3] = "Дізнайтеся, де знаходиться західний кришталевий пілон.", [4] = "Ти {стать:знайшов:знайшла} пілон, {ім'я}?", [5] = "Уздовж країв кратера багато улоговин та печер. Спробуй дослідити їх, якщо не можеш придумати, де ще шукати.", ["en"] = "The Western Pylon", ["tasks"] = { ["Discover and examine the Western Crystal Pylon"] = "Відкрийте та огляньте Західний кришталевий пілон" } },
    [4289] = { [1] = "Мавпи Ун'Ґоро", [2] = "Цей кратер населений численними дивними створіннями — здається, вони є благороднішими версіями створінь, які зустрічаються на моїй батьківщині та далеко за її межами. Я не можу пояснити це, але мені здається, що це місце — осередок сили Матері-Землі. Я віддаю їй пошану кожного разу, коли бачу її прекрасних створінь в кратері.\n\nЯкщо і ти хочеш відчути просвітлення, то рушай на північ. Там ти знайдеш великих мавп, які є випробуванням для будь-якої смертної сили. Принеси мені їхні шкури... доведи свою силу.", [3] = "Принесіть 2 шкури ун'ґорської горили, 2 шкури ун'ґорського тупотуна та 2 шкури ун'ґорського рокотуна Торві Слідопиту близ входу до кратера Ун'Ґоро.", [4] = "Невже ці істоти перемогли тебе, {ім'я}?\n\nНе здавайся так легко. Вистежити й перемогти мавп Ун'Ґоро — непросте завдання навіть для великих мисливців.", [5] = "Отже, ти {стать:довів:довела} свою силу, достатню, щоб перемогти великих мавп Ун'Ґоро — це добре. Це випробування було легким в порівнянні з Лар'корві, але я не позбавлятиму тебе такої великої перемоги.\n\nЦі шкури стануть чудовим одягом для мого племені. Ти мені {стать:допоміг:допомогла} і {стать:показав:показала}, чого {стать:вартий:варта}.\n\nПеред ніж ти вирушиш на наступне завдання, ми прославимо Матір Землю і подякуємо духам тих мавп, яких ти {стать:знищив:знищила} — вони повинні знати, що їх смерть не даремна.", ["en"] = "The Apes of Un'Goro", ["tasks"] = { ["Un'Goro Gorilla Pelt"] = "шкура ун'ґорської горили", ["Un'Goro Gorilla Pelt (Provided)"] = "шкура ун'ґорської горили (видано)", ["Un'Goro Stomper Pelt"] = "шкура ун'ґорського топотуна", ["Un'Goro Stomper Pelt (Provided)"] = "шкура ун'ґорського топотуна (видано)", ["Un'Goro Thunderer Pelt"] = "шкура ун'ґорського рокотуна", ["Un'Goro Thunderer Pelt (Provided)"] = "шкура ун'ґорського рокотуна (видано)" } },
    [4290] = { [1] = "Здобич Лар'корві", [2] = "Колись, дуже давно, мій брат взяв трохи м'яса однієї з убитих жертв Лар'корві. Він не знав, але Лар'корві бачив його з лісу. Лар'корві стежив за моїм братом декілька днів, знищуючи все, що траплялося на його шляху. Мій брат, наляканий, нарешті вирішив втекти з кратера і відірватися від Лар'корві.\n\nЛар'корві вбив його неподалік звідси.\n\nЯкщо ти хочеш спровокувати Лар'корві, знайди його свіжу здобич і візьми трохи м'яса з неї.\n\nПісля цього повертайся до мене.", [3] = "Знайдіть тушу найсвіжішої жертви Лар'корві та вкрадіть шматок туші молотодона, перш ніж повернутися до Торви Слідопита в кратер Ун'Ґоро.", [4] = "Не сприймай мої слова легковажно, {ім'я}. Якщо ти справді хочеш зустрітися з цією істотою, ти {стать:повинен:повинна} бути {стать:обережним:обережною}... і {стать:розумним:розумною}. Тобі знадобиться багато сили, щоб вистежити Лар'корві та перемогти його.", [5] = "Цей шматок чудово підійде, {ім'я}. Здається, Лар'корві добре харчується цими днями. Хоча дивно, де він знайшов молотодона в цих краях... Дивно.\n\nОднак, я збережу це до того часу, коли ти будеш {стать:готовий:готова} зіткнутися з цим чудовиськом. Не хвилюйся за мене — я впевнений, що ти настільки {стать:розгнівав:розгнівала} Лар'корві, що він не вб'є мене, поки не скуштує твоє м'ясо.", ["en"] = "The Fare of Lar'korwi", ["tasks"] = { ["Piece of Threshadon Carcass"] = "шматок туші молотодона", ["Piece of Threshadon Carcass (Provided)"] = "шматок туші молотодона (видано)" } },
    [4291] = { [1] = "Запах Лар'корві", [2] = "Насправді мене дивує, що він ще не прийшов за тобою, {ім'я}. Але все добре, оскільки у мене є план, який приверне цього монстра до нас.\n\nЯк домінантний самець, Лар'корві має право розмножуватися з будь-якою самкою, яку він обере — і він обирає багатьох. Ти знайдеш багато яєць равазаврів на заході звідси. Підберись ближче до них, і це спровокує його супутниць. Самки виділяють запах з залоз на голові, що дозволяє самцям знати, що вони готові до розмноження. Принеси мені дві такі залози.", [3] = "Принесіть 2 феромонні залози равазавра до Торви Слідопита біля входу до кратера Ун'Ґоро.", [4] = "Будь {стать:обережним:обережною}, {ім'я}. Наближення до будь-якого гнізда з яйцями, безумовно, спровокує самок... навіть якщо ти вже {стать:взяв:взяла} залозу в них. Матері можуть бути не менш смертоносними за самого Лар'корві, коли вони боронять своє потомство. Але якщо все буде добре, то у нас буде надійний спосіб приманити Лар'корві.", [5] = "Ах, чудові зразки, {ім'я}. Ці залози будуть ідеальними приманками для Лар'корві. Я не можу дочекатися твоєї битви з цим монстром. Він величезний і має кігті, гостріші за найдосконаліші мечі. Ти подивишся йому в очі й відчуєш смерть.", ["en"] = "The Scent of Lar'korwi", ["tasks"] = { ["Ravasaur Pheromone Gland"] = "феромонна залоза равазавра", ["Ravasaur Pheromone Gland (Provided)"] = "феромонна залоза равазавра (видано)" } },
    [4292] = { [1] = "Приманка для Лар'корві", [2] = "Це буде найскладніша частина, оскільки план дещо заплутаний. На півночі звідси ти знайдеш маленьку стежку в гори. Саме там я востаннє бачив Лар'корві. Ти зрозумієш, що ти у правильному місці за кістками великих створінь, що колись блукали там. Візьми м'ясо, яке ти {стать:знайшов:знайшла}, і поклади його там. Потім натри м'ясо цією сумішшю. Якщо ці дві приманки не привернуть увагу Лар'корві, то я не знаю, що ще може допомогти.", [3] = "Використовуючи вміст торби Торви, викличте Лар'корві та переможіть його. Потім принесіть голову Лар'корві Торві Слідопиту біля входу до кратера Ун'Ґоро.", [4] = "Не дозволяй страху взяти над тобою гору, {ім'я}. Страх — великий зрадник... Ти {стать:повинен:повинна} залишатися {стать:сильним:сильною}!\n\nВізьми м'ясо, поклади його в улоговині, а потім використай залозу. Тільки тоді смерть прийде за тобою.", [5] = "Матір Земля, хвала тобі! Тобі вдалося, {ім'я}! Ти {стать:виявився великим мисливцем:виявилася великою мисливицею} як для свого розміру. Твій дух міцний. Твоя відвага безперечна. І твоя сила виросла. Я схиляюся перед твоїми навичками.\n\nТільки найвеличніші з моїх предків змогли б досягти чогось настільки неймовірного. Вітаю тебе.", ["en"] = "The Bait for Lar'korwi", ["tasks"] = { ["Lar'korwi's Head"] = "голова Лар'корві", ["Lar'korwi's Head (Provided)"] = "голова Лар'корві (видано)" } },
    [4293] = { [1] = "Зразок слимака...", [2] = "Сквернолісся розташоване далеко на півночі від Степів, далі ніж Ясенеділ. Слимаків в тому лісі можна знайти навколо водойм, до яких дісталася Скверна. Скара знищила ті землі атаками пекельників та іншої демонічної магії. Вважається, що слимаки, під час тих атак, виповзали на поверхню землі.\n\nЗбери зразки сквернолісних слимаків, тоді ми використаємо тестувальне обладнання поруч зі мною, щоб створити контрольну групу для наших подальших дослідів. Тоді ми зможемо порівнювати їх з іншими зразками, які ти збереш.", [3] = "Зберіть зразки слизу з будь-яких слимаків у Скверноліссі. Після цього, використайте тестувальне обладнання поруч із хіміком Паливком в Підмісті, і визначить, які з них найбільш забруднені. Принесіть 5 забруднених сквернолісних зразків хіміку Паливку.", [4] = "Мені потрібно щонайменше п'ять забруднених зразків для нашої контрольної групи, {Ім'я}. Продовжуй збирати сквернолісних слимаків доти, доки не буде саме стільки. Так велить Леді Сильвана...", [5] = "Чудово, ці зразки дуже добре підходять. Спасибі за допомогу.\n\nКоли ми зберемо всі зразки слимаків, ми зможемо дізнатися більше. Я починаю підозрювати, що накази леді Сильвани в цьому напрямку не лише правильні, але й дуже перспективні, на стільки, що навіть вона сама не змогла б це передбачити. Надзвичайно цікаві зразки. Зважаючи на те як вони реагують на мої суміші... хм, так, ми маємо продовжувати дослідження.", ["en"] = "A Sample of Slime...", ["tasks"] = { ["Corrupted Felwood Sample"] = "забруднений сквернолісний зразок", ["Corrupted Felwood Sample (Provided)"] = "забруднений сквернолісний зразок (видано)" } },
    [4294] = { [1] = "... і партія слизу", [2] = "{стать:Чув:Чула} про кратер Ун'Ґоро, {Ім'я}? Він розташований біля пустелі Танаріс і це чудове місце: буйна, повна життєвої сили живність і рослинність.\n\nСаме туди ти й маєш вирушити. До мене дійшли чутки, що це місце досі не було розвідане. Лише зараз мандрівники активно взялися досліджувати його таємниці.\n\nЯ хочу дослідити слизнів чи ще якусь твань цього місця. Якщо це правда і вони дійсно неушкоджені, мені треба побачити як еволюціонували ці істоти.", [3] = "Зберіть зразки слизу з будь-яких слимаків у кратері Ун'Ґоро. Після цього, використайте тестувальне обладнання поруч із хіміком Паливком в Підмісті, і визначіть, які з них найчистіші. Принесіть 5 чистих ун'ґорських зразків хіміку Паливку.", [4] = "Що, {Ім'я}? Як проходять твої пошуки?", [5] = "Це дивовижно, {Ім'я}. Цей кратер Ун'Ґоро містить більше таємниць ніж я очікував. Цікаво, про що ми ще дізнаємося, продовжуючи досліди.\n\nПросто дивовижно... Подивись на чистоту цих зразків. Цікаво, що це означає? Вони, ніби, елементалі за природою, але... і щось більше. Вони нагадують мені... Старих Богів. Ми знаходили їхні сліди по всьому Азероту, і тепер треба дізнатися чи ці створіння з ними якось пов'язані.\n\nМи маємо продовжувати дослідження.", ["en"] = "... and a Batch of Ooze", ["tasks"] = { ["Pure Un'Goro Sample"] = "чистий ун'ґорський зразок", ["Pure Un'Goro Sample (Provided)"] = "чистий ун'ґорський зразок (видано)" } },
    [4295] = { [1] = "Ель для Каменевузла", [4] = "Ех, ель! Я б зараз убив за кружку елю Темного Заліза!! Швидше, я тверезію! А коли я тверезію, мій зір затуманюється... і робить мене схожим на {стать:того:ту} {раса:р}, що я вбив минулого тижня!", [5] = "Що це? Пахне елем Темного Заліза! Хоч мій розум й затуманений випивкою, але я можу сказати тобі одне, {стать:добрий пане, ти справжній друг:добра пані, ти справжня подруга}!", ["en"] = "Rocknot's Ale", ["tasks"] = { ["Dark Iron Ale Mug"] = "кухоль елю Темного Заліза", ["Dark Iron Ale Mug (Provided)"] = "кухоль елю Темного Заліза (видано)" } },
    [4296] = { [1] = "Скрижаль Сімох", [2] = "Я прийшов в Палаючий степ, слідуючи легендам про Сімох. Це були дворфи, прославлені знаннями й силою, а отже — і багатством.\n\nЦе те, що я хочу. Багатство!\n\nЯкщо ми дізнаємося більше про Сімох, то можливо, ми зможемо збагатитися разом. В руїнах Тауріссана є скрижаль Сімох, що містить знання про древніх дворфів. Знайди цю скрижаль, перепиши її текст та принеси мені. Давай разом дізнаємось її таємниці!", [3] = "Принесіть переписаний текст зі скрижалі Максворту Суперблиску в Палаючий степ.", [4] = "Писання Сімох у тебе, {ім'я}? Чи {стать:дізнався:дізналася} ти секрети з їхньої скрижалі?", [5] = "А, ти {стать:знайшов:знайшла} скрижаль! І непогано {стать:переписав:переписала} текст! Ти {стать:впевнений:впевнена}, що ти {клас}, а не писар?\n\nТримай, {ім'я}. Ось плата, як я й обіцяв.", ["en"] = "Tablet of the Seven", ["tasks"] = { ["Tablet Transcript"] = "текст зі скрижалі", ["Tablet Transcript (Provided)"] = "текст зі скрижалі (видано)" } },
    [4299] = { [1] = "<NYI> <TXT>Гробниця Семи", [2] = "Знайдіть Гробницю Сімох і помістіть туди цей PX83-Енігматрон.", ["en"] = "<NYI> <TXT>The Tomb of the Seven", ["tasks"] = { ["Place the PX83-Enigmatron"] = "Розмістіть PX83-Енігматрон" } },
    [4300] = { [1] = "Кістяна зброя", [2] = "Хм, думаю, для тебе знайдеться робота. Так, Джес'рімону точно знадобиться твоя допомога.\n\nУ кратері Ун'Ґоро живуть раптори зі смертоносними кігтями. У більшості з них кігті чорні, як смерть, але в деяких вони білі. У Розтрощеної Руки є... клієнти... яким подобається зброя, зроблена з таких кігтів. Принеси мені побільше білих кігтів, і я добре заплачу. Зроби це якнайшвидше, і, можливо, я допоможу тобі ще чимось.", [3] = "Принесіть 8 кігтів равазавра Джес'рімону в Орґріммар.", [4] = "Мої клієнти нетерплячі, {ім'я}. Ти вже {стать:зібрав:зібрала} кігті?", [5] = "Так, це те, що треба. Дякую, {ім'я}. І ти саме вчасно.... це чудово.\n\nМожливо, ми зможемо виготовити з цих кігтів зброю і для тебе. Що скажеш?", ["en"] = "Bone-Bladed Weapons", ["tasks"] = { ["White Ravasaur Claw"] = "білий кіготь равазавра", ["White Ravasaur Claw (Provided)"] = "білий кіготь равазавра (видано)" } },
    [4301] = { [1] = "Могутній У'ча", [2] = "Поки ти {стать:подорожував:подорожувала} по Ун'Ґоро, я бачив інші речі, які могли б сподобатись {стать:такому могутньому мисливцю:такій могутній мисливиці}, як ти. Однією з них була велика мавпа серед горил на півночі. Ти вже {стать:був:була} у тій печері, але цього разу я хочу побачити, чи виживеш ти, якщо візьмеш моє завдання.\n\nЯ називаю його У'ча, і він один з найвидатніших синів Матері Землі, в цьому можна не сумніватись. Переможи У'чу і принеси мені його шкуру. Зроби це, і я захищатиму твоє право називати себе {стать:великим мисливцем:великою мисливицею}.", [3] = "Принесіть шкуру У'чі до Торви Слідопита біля входу до кратера Ун'Ґоро.", [4] = "У'ча... прекрасний звір. Величезний і червоний, а зуби його гострі, як кинджали. Руки його товсті, як стовбури дерев, а сам він швидкий, як гірський лев. Тобі пощастило зустріти таке випробування хоробрості — багатьом поколінням у моєму племені не пощастило зустріти нічого подібного.", [5] = "Вітаю, {ім'я}. Я задоволений. Ти {стать:здійснив:здійснила} велике діяння сьогодні.\n\nУ'ча був одним з найвеличніших мавп, бачених мною за все життя. Той факт, що ти {стать:здолав:здолала} його, свідчить про твою силу... і хоробрість.\n\nПрийми це на знак моєї поваги. Ти {стать:заслужив:заслужила} його.", ["en"] = "The Mighty U'cha", ["tasks"] = { ["U'cha's Pelt"] = "шкура У'чі", ["U'cha's Pelt (Provided)"] = "шкура У'чі (видано)" } },
    [4321] = { [1] = "Осмислення інформації", [2] = "Інформація, яку ти мені {стать:дізнався:дізналась} про пілони, дуже цікава...\n\nДай мені хвилинку, щоб зробити деякі розрахунки, {ім'я}. Поговори зі мною через хвилину, і я зможу дати тобі відповідь, яку ми шукали.", [3] = "Поговоріть з Джей Ді Коллі за мить.", [5] = "Що ж, {ім'я}. Це неймовірно... Я можу тільки сподіватися, що мої розрахунки правильні! Я зібрала всю інформацію в цій книзі та віддаю її тобі.\n\nДумаю, що тепер я можу відповісти на всі твої запитання про кристали, {ім'я}.", ["en"] = "Making Sense of It" },
    [4323] = { [1] = "<NYI> <TXT> Отримайте цих гієн!!!", [2] = "Я хочу шкури гієн, і тільки найкращі підійдуть! Здай мені плямисті шкури гієн, і я тобі дам крутих штучок, чувак.", [3] = "Принесіть 7 шкурок плямистої гієни до TESTTAUREN на заставі Розкутого Вітру.", ["en"] = "<NYI> <TXT> Get those Hyenas!!!", ["tasks"] = { ["Spotted Hyena Pelt"] = "шкура плямистої гієни" } },
    [4324] = { [1] = "Юка Гвинтокран", [2] = "Мій братик Рібблі все своє життя був нікчемним, але, я думаю, що нарешті він має якусь цінність! Та для того, щоб отримати якусь вигоду з нього, нам може знадобитись твоя допомога.\n\nМоя сестра Юка шукала його кілька тижнів і їй вдалось дізнатись, що він в Палаючому степу. Вона сказала, що їй потрібна допомога та просить найняти когось.\n\nТо що скажеш? Хочеш допомогти? Якщо так, то поговори з моєю сестрою. Ти знайдеш її на Жевріючій Вершині, в печері на північний захід від скелі Жахобою.", [3] = "Поговоріть з Юкою Гвинтокраном в Палаючому степу.", [5] = "Так, я шукаю свого брата. Ми повинні знайти його і повернути.\n\nАле якщо ти не зможеш привести його неушкодженим... то принеси мені хоча б його голову.", ["en"] = "Yuka Screwspigot" },
    [4343] = { [1] = "Осквернений вітроцвіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на вітроцвіт. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите дві порції кенарійського бальзаму зцілення рослин на вітроцвіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Windblossom", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4381] = { [1] = "Кристалічне відновлення", [4] = "Цей пілон дозволяє комбінувати зелені кристали сили з жовтими кристалами сили.\n\nЗгідно з посібником Джей Ді, цю комбінацію можна використовувати для зцілення себе або своїх союзників.", [5] = "Ви ретельно розкладаєте кристали згідно з діаграмою. Коли ви вставляєте останній кристал на місце, спалах світла сплавляє кристали разом.\n\nОтриманий кристал тепер ваш.", ["en"] = "Crystal Restore", ["tasks"] = { ["Green Power Crystal"] = "зелений кристал сили", ["Green Power Crystal (Provided)"] = "зелений кристал сили (видано)", ["Yellow Power Crystal"] = "жовтий кристал сили", ["Yellow Power Crystal (Provided)"] = "жовтий кристал сили (видано)" } },
    [4382] = { [1] = "Кристалічна сила", [4] = "Цей пілон дозволяє комбінувати зелені кристали сили з синіми кристалами сили.\n\nЗгідно з посібником Джей Ді, цю комбінацію можна використовувати для підняття духу.", [5] = "Ви ретельно розкладаєте кристали згідно з діаграмою. Коли ви вставляєте останній кристал на місце, спалах світла сплавляє кристали разом.\n\nОтриманий кристал тепер ваш.", ["en"] = "Crystal Force", ["tasks"] = { ["Blue Power Crystal"] = "синій кристал сили", ["Blue Power Crystal (Provided)"] = "синій кристал сили (видано)", ["Green Power Crystal"] = "зелений кристал сили", ["Green Power Crystal (Provided)"] = "зелений кристал сили (видано)" } },
    [4383] = { [1] = "Кристалічний захист", [4] = "Цей пілон дозволяє комбінувати зелені кристали сили з красними кристалами сили.\n\nЗгідно з посібником Джей Ді, ця комбінація може бути використана для посилення захисту від фізичної шкоди.", [5] = "Ви ретельно розкладаєте кристали згідно з діаграмою. Коли ви вставляєте останній кристал на місце, спалах світла сплавляє кристали разом.\n\nОтриманий кристал тепер ваш.", ["en"] = "Crystal Ward", ["tasks"] = { ["Green Power Crystal"] = "зелений кристал сили", ["Green Power Crystal (Provided)"] = "зелений кристал сили (видано)", ["Red Power Crystal"] = "червоний кристал сили", ["Red Power Crystal (Provided)"] = "червоний кристал сили (видано)" } },
    [4384] = { [1] = "Кристалічне послаблення", [4] = "Цей пілон дозволяє комбінувати червоні кристали сили з синіми кристалами сили.\n\nЗгідно з посібником Джей Ді, ця комбінація може бути використана для послаблення захисту противника.", [5] = "Ви ретельно розкладаєте кристали згідно з діаграмою. Коли ви вставляєте останній кристал на місце, спалах світла сплавляє кристали разом.\n\nОтриманий кристал тепер ваш.", ["en"] = "Crystal Yield", ["tasks"] = { ["Blue Power Crystal"] = "синій кристал сили", ["Blue Power Crystal (Provided)"] = "синій кристал сили (видано)", ["Red Power Crystal"] = "червоний кристал сили", ["Red Power Crystal (Provided)"] = "червоний кристал сили (видано)" } },
    [4385] = { [1] = "Кристалічний заряд", [4] = "Цей пілон дозволяє комбінувати червоні кристали сили з жовтими кристалами сили.\n\nЗгідно з посібником Джей Ді, ця комбінація може бути використана для створення великого вибуху, який може завдати шкоди вашим ворогам.", [5] = "Ви ретельно розкладаєте кристали згідно з діаграмою. Коли ви вставляєте останній кристал на місце, спалах світла сплавляє кристали разом.\n\nОтриманий кристал тепер ваш.", ["en"] = "Crystal Charge", ["tasks"] = { ["Red Power Crystal"] = "червоний кристал сили", ["Red Power Crystal (Provided)"] = "червоний кристал сили (видано)", ["Yellow Power Crystal"] = "жовтий кристал сили", ["Yellow Power Crystal (Provided)"] = "жовтий кристал сили (видано)" } },
    [4386] = { [1] = "Кристалічне вістря", [4] = "Цей пілон дозволяє комбінувати сині кристали сили з жовтими кристалами сили.\n\nЗгідно з посібником Джей Ді, ця комбінація може бути використана для створення щита, який завдає шкоди ворогам.", [5] = "Ви ретельно розкладаєте кристали згідно з діаграмою. Коли ви вставляєте останній кристал на місце, спалах світла сплавляє кристали разом.\n\nОтриманий кристал тепер ваш.", ["en"] = "Crystal Spire", ["tasks"] = { ["Blue Power Crystal"] = "синій кристал сили", ["Blue Power Crystal (Provided)"] = "синій кристал сили (видано)", ["Yellow Power Crystal"] = "жовтий кристал сили", ["Yellow Power Crystal (Provided)"] = "жовтий кристал сили (видано)" } },
    [4401] = { [1] = "Осквернений піснеквіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на піснеквіт. Плоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите кенарійський бальзам зцілення рослин на піснеквіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Songflower", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4403] = { [1] = "Осквернений вітроцвіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на вітроцвіт. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите дві порції кенарійського бальзаму зцілення рослин на вітроцвіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Windblossom", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4421] = { [1] = "Скверна Нефритожарих", [2] = "Тут небагато хто шукає пригод... Скверна Сквернолісся розповзається, вражаючи все без розбору.\n\nЯ, як частина Смарагдового Кола, прагну вилікувати цю землю, але є ті, хто хоче, щоб вона і далі гнила.\n\nТі, про кого я говорю — Нефритожарі сатири, які живуть на північному заході звідси, у руїнах Сузірви. Ними керує особливо жорстокий сатир, на ім'я Заватрас. Вони продовжують вражати заразою будь-яку живу істоту, яка трапляється їм на шляху.\n\nМи повинні захистити цю землю, яка колись була нашою. Здолай Заватраса та вбий його підлеглих.", [3] = "Вбийте 11 нефритожарих скверноклятів, 9 нефритожарих тінеловів, 9 нефритожарих пройдисвітів і Заватраса. Поверніться до Ерідани Блакитновій у Сквернолісся, коли виконаєте завдання.", [4] = "Скверна доводить істот до божевілля...", [5] = "Позбавлення Сквернолісся від Заватраса — це лише перший крок. Попереду ще багато роботи, щоб виправити завдану цим лісам шкоду.\n\nЯ відчуваю, що справа в чомусь більшому, ніж просто сатири, але правду ми дізнаємося лише з часом...", ["en"] = "The Corruption of the Jadefire", ["tasks"] = { ["Jadefire Felsworn"] = "нефритожарий скверноклят", ["Jadefire Felsworn slain"] = "нефритожарий скверноклят: убито", ["Jadefire Rogue"] = "нефритожарий пройдисвіт", ["Jadefire Rogue slain"] = "нефритожарий пройдисвіт: убито", ["Jadefire Shadowstalker"] = "нефритожарий тінелов", ["Jadefire Shadowstalker slain"] = "нефритожарий тінелов: убито", ["Xavathras"] = "Заватрас", ["Xavathras slain"] = "Заватрас: убито" } },
    [4443] = { [1] = "Осквернений кнутокорінь", [4] = "Ви знайшли хвору, осквернену рослину, схожу на кнутокорінь. ЇЇ корені виглядають жорсткими та шкірястими, а вся рослина вкрита слизом. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите три порції кенарійського бальзаму зцілення рослин на кнутокорінь. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Whipper Root", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4444] = { [1] = "Осквернений кнутокорінь", [4] = "Ви знайшли хвору, осквернену рослину, схожу на кнутокорінь. ЇЇ корені виглядають жорсткими та шкірястими, а вся рослина вкрита слизом. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите три порції кенарійського бальзаму зцілення рослин на кнутокорінь. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Whipper Root", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4445] = { [1] = "Осквернений кнутокорінь", [4] = "Ви знайшли хвору, осквернену рослину, схожу на кнутокорінь. ЇЇ корені виглядають жорсткими та шкірястими, а вся рослина вкрита слизом. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите три порції кенарійського бальзаму зцілення рослин на кнутокорінь. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Whipper Root", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4446] = { [1] = "Осквернений кнутокорінь", [4] = "Ви знайшли хвору, осквернену рослину, схожу на кнутокорінь. ЇЇ корені виглядають жорсткими та шкірястими, а вся рослина вкрита слизом. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите три порції кенарійського бальзаму зцілення рослин на кнутокорінь. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Whipper Root", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4447] = { [1] = "Осквернений нічний дракон", [4] = "Ви знайшли хвору, осквернену рослину, схожу на нічного дракона. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите чотири порції кенарійського бальзаму зцілення рослин на нічного дракона. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Night Dragon", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4448] = { [1] = "Осквернений нічний дракон", [4] = "Ви знайшли хвору, осквернену рослину, схожу на нічного дракона. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите чотири порції кенарійського бальзаму зцілення рослин на нічного дракона. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Night Dragon", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4449] = { [1] = "Попався!", [2] = "Гей! Гей, ти! Ходь сюди!\n\nТи {стать:повинен:повинна} мені допомогти. Я тікав від дворфів Темного Заліза й сховав си тут. Шляк би їх трафив, цих геологів і єхню магію! Вони, певно, вгледіли, як я йшов сюди, бо замкнули двері й зачинили мене тут.\n\nПровчи їх! О! І заодно можеш принести мені кілько відрізів шовкового полотна.", [3] = "Вбийте 8 геологів Темного Заліза і принесіть 15 відрізів шовкового полотна персоні, замкненій у вбиральні в Випаленій ущелині.", [4] = "Я не мо' ждать цілий день! Достань шовкове полотно! Тобто геологів. Проучи їх! Вони мають відчути муй, ну... твуй гнів.", [5] = "Йо, файна тканина!\n\nЩо? О, так... геологи. Ти ж {стать:провчив:провчила} єх, ге? Я не мо' достатньо подякувати тобі, {ім'я}. Пожди хвильку, мені тут тре' закінчити деякі справи... Пак, раз дякуву, {ім'я}.", ["en"] = "Caught!", ["tasks"] = { ["Dark Iron Geologist"] = "геолог Темного Заліза", ["Dark Iron Geologist slain"] = "геолог Темного Заліза: убито", ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [4450] = { [1] = "Гросбух з Танарісу", [2] = "О, знаєш що? Це нагадало мені про єдну справу.\n\nТи не хо' помогти мені закінчити роботу, яку я взяв у Танарісі? Це не тєжко...\n\nКрінкл Файносталь з Пристробляху шукає деякі речі, які можна знайти тута, у Випаленій ущелині, та кількох інших місцях. Мо' ти збереш се для него?\n\nЯ просто кину книгу під двері, якщо тобі се цікаво. Однеси книгу та речі з неї Крінклу.", [3] = "Візьміть копію гросбуха Файносталя і знайдіть перелічені в ньому предмети, перш ніж знайти Крінкла Файносталя в Танарісі.", [4] = "Так? Що я можу зробити для тебе, {раса:к}? Я дуже зайнятий і у мене багато клієнтів. Швидше, будь ласка. Я не хочу здатися грубим, але я просто не маю часу, якщо я хочу закінчити всю свою роботу.", [5] = "О, ти {стать:знайшов:знайшла} час, щоб виконати роботу, про яку я просив. Чудово. А я думав, що ти попросиш мене змайструвати щось для тебе.\n\nВсе ідеально... і все на місці. Дякую, {клас:к}.\n\nМожливо, не буде зайвим нагородити тебе... хмм, що б тобі було корисним...", ["en"] = "Ledger from Tanaris", ["tasks"] = { ["Goodsteel Ledger"] = "гросбух Файносталя", ["Goodsteel Ledger (Provided)"] = "гросбух Файносталя (видано)", ["Goodsteel's Balanced Flameberge"] = "збалансований фламберг Файносталя", ["Goodsteel's Balanced Flameberge (Provided)"] = "збалансований фламберг Файносталя (видано)", ["Overdue Package"] = "затриманий пакунок", ["Overdue Package (Provided)"] = "затриманий пакунок (видано)", ["Solid Crystal Leg Shaft"] = "міцна кришталева лапа", ["Solid Crystal Leg Shaft (Provided)"] = "міцна кришталева лапа (видано)" } },
    [4451] = { [1] = "Ключ до свободи", [2] = "Маленький латунний ключ виглядає досить простим. Єдине, що робить його особливим, це напис, вигравіюваний на ньому:\n\n\"Вбиральня Темного Заліза — не робити копій\".\n\nВи не маєте жодної здогадки, що це за ключ чи куди він може привести.", [3] = "Знайдіть в Випаленій ущелині застосування знайденому ключу від вбиральні Смердюха.", [4] = "*кашель*\n\nХто там? Не бач, що я занятий?", [5] = "Ото да! Як ти се {стать:зробив:зробила}? Я знаю, що трикляті дворфи Темного Заліза схували його, як замкнули мене тут! Красно дякую, {ім'я}. Ти {стать:майкращий:майкраща}! Тепер просто одчини двері й випусти старого Локіда звідсілся!", ["en"] = "The Key to Freedom", ["tasks"] = { ["Grimesilt Outhouse Key"] = "ключ від вбиральні Смердюха", ["Grimesilt Outhouse Key (Provided)"] = "ключ від вбиральні Смердюха (видано)" } },
    [4461] = { [1] = "Осквернений кнутокорінь", [4] = "Ви знайшли хвору, осквернену рослину, схожу на кнутокорінь. ЇЇ корені виглядають жорсткими та шкірястими, а вся рослина вкрита слизом. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите три порції кенарійського бальзаму зцілення рослин на кнутокорінь. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Whipper Root", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4462] = { [1] = "Осквернений нічний дракон", [4] = "Ви знайшли хвору, осквернену рослину, схожу на нічного дракона. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите чотири порції кенарійського бальзаму зцілення рослин на нічного дракона. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Night Dragon", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4463] = { [1] = "Манускрипт роздумів", [4] = "Покажи компоненти, {стать:смертний:смертна}.\n\nЗа це творіння я також візьму тридцять золотих.", [5] = "Забирай свою дрібничку, {стать:дурню:дурепо}. Не заважай мені вчитися!", ["en"] = "Libram of Rumination", ["tasks"] = { ["Black Blood of the Tormented"] = "чорна кров закатованих", ["Black Blood of the Tormented (Provided)"] = "чорна кров закатованих (видано)", ["Black Diamond"] = "чорний діамант", ["Black Diamond (Provided)"] = "чорний діамант (видано)", ["Gizzard Gum"] = "шлункова жуйка", ["Gizzard Gum (Provided)"] = "шлункова жуйка (видано)", ["Libram of Rumination"] = "манускрипт роздумів", ["Libram of Rumination (Provided)"] = "манускрипт роздумів (видано)" } },
    [4464] = { [1] = "Осквернений піснеквіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на піснеквіт. Плоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите кенарійський бальзам зцілення рослин на піснеквіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Songflower", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4465] = { [1] = "Осквернений піснеквіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на піснеквіт. Плоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите кенарійський бальзам зцілення рослин на піснеквіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Songflower", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4466] = { [1] = "Осквернений вітроцвіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на вітроцвіт. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите дві порції кенарійського бальзаму зцілення рослин на вітроцвіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Windblossom", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4467] = { [1] = "Осквернений вітроцвіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на вітроцвіт. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите дві порції кенарійського бальзаму зцілення рослин на вітроцвіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Windblossom", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [4481] = { [1] = "Манускрипт статури", [4] = "За все в цьому світі треба платити ціну. Ціна конкретної речі, яку ти шукаєш, — тридцять золотих.\n\nЗвичайно, я залишу собі більшість компонентів, які ти {стать:зібрав:зібрала}. Але не хвилюйся, ти отримаєш свою дрібничку.", [5] = "Це ганьба для його пам'яті... {стать:смертний, такий:смертна, така} як ти, закінчує справу його життя.\n\nЗабирай свою дрібничку і йди геть!", ["en"] = "Libram of Constitution", ["tasks"] = { ["Black Diamond"] = "чорний діамант", ["Black Diamond (Provided)"] = "чорний діамант (видано)", ["Libram of Constitution"] = "манускрипт статури", ["Libram of Constitution (Provided)"] = "манускрипт статури (видано)", ["Lung Juice Cocktail"] = "легеневий коктейль", ["Lung Juice Cocktail (Provided)"] = "легеневий коктейль (видано)", ["Night Dragon's Breath"] = "подих нічного дракона", ["Night Dragon's Breath (Provided)"] = "подих нічного дракона (видано)" } },
    [4482] = { [1] = "Манускрипт наполегливості", [4] = "Тридцять золотих, {раса:к}. Тридцять золотих і необхідні компоненти.", [5] = "Каріелю знадобився час в кілька твоїх життів, щоб завершити манускрипт, який ти тримаєш у руках, {раса:к}. І все заради чого? Щоб його учень міг стояти в Палаючому степі й спотворювати його дослідження, щоб задовольнити нескінченну потаємну жагу... Будь проклята ця мерзенна залежність.\n\nМені огидна твоя відсутність співчуття і ненаситна жадібність. Іди геть!", ["en"] = "Libram of Tenacity", ["tasks"] = { ["Black Diamond"] = "чорний діамант", ["Black Diamond (Provided)"] = "чорний діамант (видано)", ["Crystal Ward"] = "кристалічний захист", ["Crystal Ward (Provided)"] = "кристалічний захист (видано)", ["Eye of Kajal"] = "око Каджала", ["Eye of Kajal (Provided)"] = "око Каджала (видано)", ["Libram of Tenacity"] = "манускрипт наполегливості", ["Libram of Tenacity (Provided)"] = "манускрипт наполегливості (видано)" } },
    [4483] = { [1] = "Манускрипт стійкості", [4] = "Якщо тобі потрібна стійкість, я потребую тридцять золотих.", [5] = "Інші манускрипти загублені в цьому світі. Загублені в місцях, куди ти не {стать:наважився:наважилася} б увійти. Місцях, яких краще б не існувало.\n\nЯ вип'ю енергію цих компонентів. А ти отримаєш те, що залишиться...", ["en"] = "Libram of Resilience", ["tasks"] = { ["Black Diamond"] = "чорний діамант", ["Black Diamond (Provided)"] = "чорний діамант (видано)", ["Burning Essence"] = "палаюча сутність", ["Burning Essence (Provided)"] = "палаюча сутність (видано)", ["Crystal Spire"] = "кристалічне вістря", ["Crystal Spire (Provided)"] = "кристалічне вістря (видано)", ["Libram of Resilience"] = "манускрипт стійкості", ["Libram of Resilience (Provided)"] = "манускрипт стійкості (видано)" } },
    [4484] = { [1] = "Манускрипт жадібності", [4] = "Не марнуй мій час, {раса:к}. Дай мені те, що потрібно. Тридцять золотих і компоненти.", [5] = "В голові паморочиться... Енергії безмежних просторів всесвіту... ААХХ!\n\n<Матредіс кривиться від болю.>\n\nЗабирай, що тобі потрібно, і йди!", ["en"] = "Libram of Voracity", ["tasks"] = { ["Black Diamond"] = "чорний діамант", ["Black Diamond (Provided)"] = "чорний діамант (видано)", ["Crystal Force"] = "кристалічна сила", ["Crystal Force (Provided)"] = "кристалічна сила (видано)", ["Libram of Voracity"] = "манускрипт жадібності", ["Libram of Voracity (Provided)"] = "манускрипт жадібності (видано)", ["Whipper Root Tuber"] = "плід кнутокореня", ["Whipper Root Tuber (Provided)"] = "плід кнутокореня (видано)" } },
    [4485] = { [1] = "Фоліант благородства", [2] = "Привіт, {ім'я:к}. Бачу, твоя відданість залишається напрочуд сильною, як і твоя віра.\n\nДумаю, тобі варто поговорити з Даторіаном Раллом в Штормовії. Ти маєш ще дечому навчитись і я думаю, що ти {стать:готовий:готова}.\n\nШукай його в соборі Світла. І {ім'я:к}, сприймай його уроки з усією серйозністю. Твої досягнення зароблені смиренністю і важкою працею, тож не розчаруй нас зайвою самовпевненістю.", [3] = "Поговоріть з Даторіаном Раллом в Штормовії.", [5] = "О, ти {стать:повернувся:повернулася} до собору, {ім'я:к}. Добре. Багато чого сталось останнім часом і ти мені знадобишся, якщо ти звісно {стать:готовий:готова}.\n\nНаші підступні вороги не сплять. І мені знадобиться твоя допомога, щоб перешкодити їм.", ["en"] = "The Tome of Nobility" },
    [4486] = { [1] = "Фоліант благородства", [2] = "Так-так, погляньте но на {стать:цього могутнього:цю могутню} {клас:з}.\n\nВибач, {ім'я:к}, я не хотів тебе образити... Я просто трішки заздрю, коли бачу, чого тобі вдалось досягти. Тіза каже, що це моя слабкість і я обіцяв їй працювати над цим. Іноді це не так просто, розумієш?\n\nТа я хотів поговорити з тобою не про це. Даторіан Ралл зі Штормовію хоче зустрітись з тобою в соборі Світла коли ти будеш {стать:готовий:готова}. Схоже, готується щось важливе.", [3] = "Поговоріть з Даторіаном Раллом в Штормовії.", [5] = "О, ти {стать:повернувся:повернулася} до собору, {ім'я:к}. Добре. Багато чого сталось останнім часом і ти мені знадобишся, якщо ти звісно {стать:готовий:готова}.\n\nНаші підступні вороги не сплять. І мені знадобиться твоя допомога, щоб перешкодити їм.", ["en"] = "The Tome of Nobility" },
    [4487] = { [1] = "Виклик скверножеребця", [2] = "А, чудово, ти тут. Я послав за тобою {стать:сукуба:пекельника}, щоб привернути твою увагу, але, здається, ти {стать:встиг:встигла} швидше. Гаразд.\n\nОстаннім часом всі говорять, що твоя сила росте — це добре для тебе і, можливо, погано для інших. Але ці розмови не мають значення. Головне — я відчуваю, що ти {стать:довів:довела} свою силу і заслуговуєш на... хехе... своєрідне благословення.\n\nНад Брашпилем в Степах ти знайдеш чоловіка, на ім'я Страгад. Здається, ви вже зустрічалися раніше.", [3] = "Поговоріть зі Страгадом Фарсаном в Брашпилі.", [5] = "Отже, ти {стать:вирішив:вирішила} знову відвідати мою скромну особу. Дуже мило з твого боку.\n\nМої помічники сумнівалися, що ти коли-небудь з'явишся. Я сказав їм, що не сумніваюся. Коли мова йде про силу, ти притягуєшся, як метелик до полум'я.", ["en"] = "Summon Felsteed" },
    [4488] = { [1] = "Виклик скверножеребця", [2] = "А, {ім'я}, ти {стать:вирішив:вирішила} вшанувати нас своєю присутністю. Чудово!\n\nСподіваюсь, ти не вважаєш себе пупом землі. Може, ти й швидко набираєшся сил, але коли мова йде про справжні знання і мудрості, ти все ще щеня. Якщо ти не будеш {стать:обережним:обережною}, скверна засліпить тебе і зробить твою волю слабкою.\n\nПерейдімо до справи: Страгад бажає поговорити з тобою. Він все ще перебуває у своїй вежі, що над Брашпилем у Степах. Я раджу тобі не гаяти час.", [3] = "Поговоріть зі Страгадом Фарсаном в Брашпилі.", [5] = "Отже, ти {стать:вирішив:вирішила} знову відвідати мою скромну особу. Дуже мило з твого боку.\n\nМої помічники сумнівалися, що ти коли-небудь з'явишся. Я сказав їм, що не сумніваюся. Коли мова йде про силу, ти притягуєшся, як метелик до полум'я.", ["en"] = "Summon Felsteed" },
    [4489] = { [1] = "Виклик скверножеребця", [2] = "Ти, {раса}! Підійди сюди!\n\nТи {стать:той:та}, кого звуть {ім'я}, так?\n\nЯ так і знав. Скажу коротко: твоя сила зростає, і це всі визнають. І тепер прийшов час, коли ти будеш {стать:винагороджений:винагороджена} за свої зусилля.\n\nЙди в Степи. Там, над Брашпилем, ти знайдеш Страгада Фарсана — можливо, ти його пам'ятаєш? Він хоче поговорити з тобою. Я б на твоєму місці не затримувався.", [3] = "Поговоріть зі Страгадом Фарсаном в Брашпилі.", [5] = "Отже, ти {стать:вирішив:вирішила} знову відвідати мою скромну особу. Дуже мило з твого боку.\n\nМої помічники сумнівалися, що ти коли-небудь з'явишся. Я сказав їм, що не сумніваюся. Коли мова йде про силу, ти притягуєшся, як метелик до полум'я.", ["en"] = "Summon Felsteed" },
    [4490] = { [1] = "Виклик скверножеребця", [2] = "Я хотів би віддячити тобі за терплячість і наполегливу роботу. Але знай, що викликати скверножеребця у майбутньому буде набагато складніше. Тобі доведеться заслужити його... і це не буде легко.\n\nНаразі ти маєш здатність викликати цю істоту і використовувати її на свій розсуд.", [3] = "Поговоріть зі Страгадом Фарсаном в Брашпилі, щоб навчитися виклику скверножеребця.", [5] = "Щасти тобі, {ім'я}. Я з нетерпінням чекаю зустрічі з тобою в майбутньому.", ["en"] = "Summon Felsteed" },
    [4491] = { [1] = "З допомогою друзів", [2] = "Ух... Тут так спекотно...\n\nЯ досліджував цю місцевість, коли раптово спека стала нестерпною. Мабуть, я отримав тепловий удар.\n\nБудь ласка, допоможи мені повернутися до моєї подруги Сулиці у прихисток Маршала. Здається, що я вже оговтався і можу слідувати за тобою.\n\nЯ відчуваю невелику слабкість, тож якщо мені знову стане погано і я знепритомнію, просто побризкай на мене водою з фляги Сулиці. Сподіваюсь, це допоможе...", [3] = "Відведіть Рінґо до Сулиці Везам у прихисток Маршала.\n\nЯкщо Рінґо знепритомніє, скористайтесь флягою Сулиці, щоб привести його до тями.", [4] = "Я так хвилювалася за Рінґо...", [5] = "Рінґо не в найкращій формі, {ім'я}, але я рада, що він повернувся цілим і неушкодженим!\n\nДякую, що {стать:знайшов:знайшла} його.", ["en"] = "A Little Help From My Friends", ["tasks"] = { ["Escort Ringo to Spraggle Frock at Marshal's Refuge"] = "Супровід Рінго до Спрагл Фрок у притулку Маршала" } },
    [4492] = { [1] = "Загубився!", [2] = "Ти маєш допомогти мені, {ім'я}! Мій друг Рінґо пішов, щоб дослідити вулкан на південь від нас, і його немає вже надто довго. Я дуже хвилююся за нього.\n\nЯк думаєш, ти зможеш його знайти? Чому б тобі не взяти з собою мою флягу — якщо ти знайдеш Рінґо, я впевнена, що вона йому знадобиться!", [3] = "Знайдіть Рінґо на Вогнеперій скелі.", [4] = "Щ... Що?", [5] = "Ох... Я так радий, що хтось мене знайшов...", ["en"] = "Lost!", ["tasks"] = { ["Spraggle's Canteen"] = "фляга Сулиці", ["Spraggle's Canteen (Provided)"] = "фляга Сулиці (видано)" } },
    [4495] = { [1] = "Хороший друг", [2] = "Мій друг Іверрон зазвичай навідує мене щодня в один і той же час. Дивина в тому, що сьогодні він не завітав узагалі — навпаки, він уже на кілька годин запізнився.\n\nМушу визнати, що я трішечки хвилююся, {Ім'я}. Іверрон проводить багато часу неподалік печери на півночі, і ти певно знаєш, наскільки там небезпечно — там всюди павуки!\n\nЯкщо ти випадково будеш у тих місцях, чи не {стать:міг би:могла б} ти повиглядати його?", [3] = "Знайдіть Іверрона біля печери на півночі.", [5] = "Я такий радий, що ти {стать:знайшов:знайшла} мене, {Ім'я}. Звідки ти {стать:знав:знала}, що я тут?", ["en"] = "A Good Friend" },
    [4496] = { [1] = "Плутанина в джунглях", [2] = "Мої дослідження показали, що силітиди подібні до бджіл — знищ королеву вулика, і решта без неї пропадуть. Я створю приманку, яку ми використаємо, щоб виманити королеву. І коли вона з'явиться, ти знищиш її.\n\nСпочатку нам потрібні деякі реагенти; ми ж не хочемо, щоб ти {стать:пішов:пішла} в джунглі {стать:непідготовленим:непідготовленою}. Прямуй на захід, знайди вулик силітидів в кратері Ун'Ґоро та збери пахучу залозу в одного з цих мерзенних жуків. Мені також знадобляться зразки ґрунту Ун'Ґоро.", [3] = "Принесіть пахучу залозу Ґоріші та 5 зразків ґрунту Ун'Ґоро алхіміку Товкачеру в Пристроблях.", [4] = "Знайти правильну пахучу залозу може виявитися непросто — вона має бути в ідеальному стані, чому зовсім не сприяє спосіб видобутку. Щодо ґрунту, я припускаю, що його досить легко знайти.\n\nТак чи інакше, у тебе є реагенти, які мені потрібні для створення приманки?", [5] = "А, ось і пахуча залоза, чудово. Схоже, що мембрана ціла — відмінно. А ґрунт, так, він теж прекрасно підійде. Я дещо додам, і зроблю з цього чудову приманку.\n\nДай мені хвилинку, щоб створити приманку, {ім'я}. Коли вона буде готова, ми зможемо перейти до наступного кроку, який, сподіваємося, зупинить силітідів поки вони не захопили Пристоблях... і решту Калімдору.", ["en"] = "Bungle in the Jungle", ["tasks"] = { ["Gorishi Scent Gland"] = "пахуча залоза Ґоріші", ["Gorishi Scent Gland (Provided)"] = "пахуча залоза Ґоріші (видано)", ["Un'Goro Soil"] = "ґрунт Ун'Ґоро", ["Un'Goro Soil (Provided)"] = "ґрунт Ун'Ґоро (видано)" } },
    [4501] = { [1] = "Стережіться жаходактилів", [2] = "Розшукуються вправні бійці, щоб усунути загрозу, що йде від жаходактилів, що населяють кратер Ун'Ґоро. Їх чисельність зростає, і вони стають загрозою для мандрівників у цьому районі.\n\nЗменште їхню популяцію, знищивши 10 жаходактилів і 15 навіжених жаходактилів.\n\nПісля виконання завдання зверніться до Сулиці Везам, щоб отримати винагороду.", [3] = "Вбийте 10 жаходактилів і 15 навіжених жаходактилів, після чого поговоріть з Сулицею Везам в прихистку Маршала.", [4] = "Чесно кажучи, я не дуже переймалась всілякими дивними створіннями... Доки не побачила, напис на великому камені:\n\nСТЕРЕЖІТЬСЯ ЖАХОДАКТИЛІВ\n\nХто це написав? Не знаю, але звучить надто моторошно, щоб просто проігнорувати це!", [5] = "Жаходактилі лякають мене! Дякую, що {стать:зменшив:зменшила} їх кількість, {ім'я}. Думаю, тепер я можу наважитися вийти з прихистку Маршала.", ["en"] = "Beware of Pterrordax", ["tasks"] = { ["Frenzied Pterrordax"] = "навіжений жаходактиль", ["Frenzied Pterrordax slain"] = "навіжений жаходактиль: убито", ["Pterrordax"] = "жаходактиль", ["Pterrordax slain"] = "жаходактиль: убито" } },
    [4502] = { [1] = "Вулканічна активність", [2] = "Я багато чого навчилася під наставництвом Марвона Заклепника. Але його вже так давно немає, що я думаю провести кілька власних експериментів.\n\nЯ нещодавно читала про кратер Ун'Ґоро і про дивну вулканічну активність, що відбувається в середині кратера. Гадаю, що я могла б багато чого дізнатися, якби мені вдалося отримати трохи попелу з тамтешніх елементалів.\n\nЧи не {стать:міг би:могла б} ти зібрати його для мене, якщо все одно йдеш туди?", [3] = "Зберіть 9 зразків попелу Ун'Ґоро у вогняних елементалів навколо вулкана в кратері Ун'Ґоро і принесіть їх до Лів Хуткокріп в Брашпиль.", [4] = "Чи правда, що вулкан в Ун'Ґоро активний? Я впевнена, що могла б багато чому навчитися, отримавши трохи попелу звідти, {ім'я}.", [5] = "Ці зразки ідеально підійдуть для мого дослідження! Дякую, {ім'я}! Обіцяю, ти будеш {стать:першим:першою}, кому я розповім про свої знахідки.", ["en"] = "Volcanic Activity", ["tasks"] = { ["Un'Goro Ash"] = "попіл Ун'Ґоро", ["Un'Goro Ash (Provided)"] = "попіл Ун'Ґоро (видано)" } },
    [4503] = { [1] = "Летючий апарат Шиззла", [2] = "Я будую летючий апарат!\n\nЯ потрапив сюди, і я абсолютно жахливо розбираюсь у місцевості. Я б полетів назад до Пристробляху на грифоні чи виверні, але ці звірі мене лякають до смерті.\n\nТак от, допоможеш мені? Мені залишилося лише побудувати крила, і я думав, що перетинчасті луски жаходактилів та деметродонів ідеально підійшли б. У мене проти них немає жодних шансів, але ти виглядаєш досить {стать:міцним:міцною}. Чому б тобі не спробувати?", [3] = "Зберіть 8 перетинчастих лусок деметродонів і 8 перетинчастих лусок жаходактилів для Шиззла в прихистку Маршала.", [4] = "Кожній великій машині потрібне ім'я... Я думав назвати його... Збитий!", [5] = "Так, ці луски ідеальні. З ними я точно зможу відірвати цей апарат від землі!\n\nДякую!", ["en"] = "Shizzle's Flyer", ["tasks"] = { ["Webbed Diemetradon Scale"] = "перетинчаста луска деметродона", ["Webbed Diemetradon Scale (Provided)"] = "перетинчаста луска деметродона (видано)", ["Webbed Pterrordax Scale"] = "перетинчаста луска жаходактиля", ["Webbed Pterrordax Scale (Provided)"] = "перетинчаста луска жаходактиля (видано)" } },
    [4504] = { [1] = "Суперлипучка", [2] = "Я завжди шукаю спосіб швидко заробити, {ім'я}. Якщо ти допоможеш мені втілити мою нову ідею, я розділю з тобою прибуток. Як тобі така угода?\n\nЯ так і знав!\n\nРушай до смоляних озер у північній частині кратера Ун'Ґоро та збери для мене трохи смоли. Але не просто смоли, а смоли звірів, що живуть поруч зі смоляними озерами. Звичайна смола недостатньо липка.\n\nРослиноподібні створіння містять у своїй шкірі хлорофіл — у поєднанні зі смолою він робить її надзвичайно липкою!", [3] = "Зберіть 12 зразків надлипкої смоли для Тран'река з Пристробляху.", [4] = "Тран'рек зробить це знову — цей надлипкий клей будуть розбирати як гарячі пиріжки!", [5] = "Так, ця смола — саме те, що треба...\n\nГей, зачекай, мої руки... Я не можу їх розчепити...\n\nМожливо, це була не така вже й гарна ідея. Зачекай! Засіб для видалення надлипкої смоли! Ось на чому можна заробити справжні гроші!", ["en"] = "Super Sticky", ["tasks"] = { ["Super Sticky Tar"] = "надлипка смола", ["Super Sticky Tar (Provided)"] = "надлипка смола (видано)" } },
    [4507] = { [1] = "Пішак б'є королеву", [2] = "Ось приманка. Усередині вулика повинен бути якийсь кристал. Ми вважаємо, що силітиди використовують його як своєрідний пристрій для комунікації по всьому вулику. Щодо місця, де може бути цей кристал... я б порадив пошукати в інкубаторах всередині гнізда.\n\nЯкщо покласти приманку на цей кристал, має з'явитись з'явиться королева, але попереджаю — її, мабуть, захищатимуть стражі. Вбий королеву та вийми її мозок. Хоча це й звучить огидно, та нам дуже потрібно дослідити його. Удачі, {ім'я}!", [3] = "Викличте і переможіть королеву вулика Ґоріші.\n\nВіднесіть мозок королеви Ґоріші алхіміку Товкачеру в Пристроблях.", [4] = "Нам терміново потрібен мозок королеви для дослідження. Базуючись на наших дослідженнях, ми вважаємо, що ці силітиди перебувають під контролем злої сили. Мені страшно думати, хто може керувати такою підступною тварюкою, як силітид, {ім'я}.", [5] = "Фантастично, {ім'я}! Ми здобули чималу перемогу сьогодні. Утім, нам знадобиться трохи часу, щоб повністю розібратися з отриманими матеріалами. Але не хвилюйся, ми використаємо це на благо.\n\nЩодо силітидів, я сумніваюся, що ми зуміли зупинити їхню навалу. На жаль, це було б надто легко.", ["en"] = "Pawn Captures Queen", ["tasks"] = { ["Gorishi Queen Brain"] = "мозок королеви Ґоріші", ["Gorishi Queen Brain (Provided)"] = "мозок королеви Ґоріші (видано)" } },
    [4508] = { [1] = "Затишшя перед бурею", [2] = "Мої останні відкриття та знання, які ми отримали сьогодні, мають потрапити в руки тих, хто може з цим щось зробити. Попри те, як багато ресурсів ми маємо в Пристробляху, ми не можемо зробити цього самі.\n\nПередай мій останній звіт Ґрасіні Міцнодухій в Дарнас; вона все ще в храмі Місяця, чи не так? У неї є друзі, які є великими шишками Альянсу; якщо ми зможемо залучити їх до цієї справи, {ім'я}, то, можливо, ми виберемося звідси живими.", [3] = "Принесіть звіт Товкачера по ситуації в Ун'Ґоро до Ґрасіни Міцнодухої в Дарнас.", [4] = "Вони дурні, {ім'я}! Вони навіть не можуть подумати про більшу загрозу, що оточує їх. Їхня ірраціональна ненависть до Орди стане для нас усіх кінцем. Я не знаю, як ще можна довести їм реальність загрози силітидів, окрім як запхнути їх в одне з гнізд, щоб вони могли побачити все на власні очі!\n\nТи {стать:приніс:принесла} якісь новини для мене?", [5] = "Хоча я дуже вдячна тобі, я не впевнена, чи з цього щось вийде. Альянс ігнорує будь-які загрози, окрім Орди, і навіть наші лідери у Дарнасі не можуть вирішити, у чому саме вона полягає. Дурні на кшталт Фендрала Оленерога, запевняють, що силітиди — це ніщо у порівнянні з загрозою давнини. Його невігластво перевершує тільки його зарозумілість.\n\nТи {стать:бачив:бачила} загрозу на власні очі, {ім'я}. Ми повинні здолати силітидів!", ["en"] = "Calm Before the Storm", ["tasks"] = { ["Pestlezugg's Un'Goro Report"] = "звіт Товкачера по ситуації в Ун'Ґоро", ["Pestlezugg's Un'Goro Report (Provided)"] = "звіт Товкачера по ситуації в Ун'Ґоро (видано)" } },
    [4511] = { [1] = "Затишшя перед бурею", [2] = "{ім'я}, без тебе ми б не впорались. Без сумніву, прийде час, коли я знову попрошу тебе про допомогу в боротьбі з силітидами. Ми повинні засвоїти те, що ми дізналися в Ун'Горо. Боюся, що мої припущення про те, що силітиди походять з Ун'Горо, тепер помилкові... і десь їх набагато більше.\n\nВіднеси цю записку Карусу в банк. Він дасть тобі дещо з мого сховища на знак моєї вдячності. Дякую за допомогу, {стать:могутній:могутня} {клас:к}.", [3] = "Принесіть банківську розписку Карусу в банк Орґріммару.", [4] = "Заґ-заґ! Чим я можу допомогти, {клас:к}?", [5] = "Ця розписка уповноважує мене видати вам предмет зі сховища Зілзібіна Ударника і подарувати вам. Схоже, вас можна привітати!", ["en"] = "Calm Before the Storm", ["tasks"] = { ["Bank Voucher"] = "банківська розписка", ["Bank Voucher (Provided)"] = "банківська розписка (видано)" } },
    [4541] = { [1] = "<NYI> <TXT>", ["en"] = "<NYI> <TXT>" },
    [4561] = { [1] = "Тест на домішки - кратер Ун'Ґоро", [4] = "Ви берете зразок слимака з кратеру Ун'Ґоро та розкладаєте його в різні трубочки та мензурки на столі. Коли все починає кипіти та бризкати, слиз змінює кольори. Як тільки процес сповільнюється та рідини заспокоюються, ви бачите невелику чашу Петрі з вашими зміненими ун'ґорськими зразками слизу та якимись іншими залишками.", [5] = "Ви берете чашу Петрі зі зразком слизу всередині. Єдиний спосіб вияснити, чи зразок достатньо чистий - відкрити посудину й особисто оглянути її вміст. В ідеалі, ви знайдете там зразок, який відповідає критеріям хіміка Паливка.", ["en"] = "Testing for Impurities - Un'Goro Crater", ["tasks"] = { ["Un'Goro Slime Sample"] = "зразок ун'ґорського слизу", ["Un'Goro Slime Sample (Provided)"] = "зразок ун'ґорського слизу (видано)" } },
    [4581] = { [1] = "Кейнет Штиль", [2] = "Друїд Кейнет Штиль надіслав мені звістку. Він хоче отримати доповідь про події на нашому узбережжі та в лісі навколо Астранаару. Він побоюється, що через Ясенеділ йде хвиля спотворення... і схоже, що він не помиляється.\n\nОсь, віднеси йому мою доповідь. Ти знайдеш його в храмі Лісової Пісні, що в лісі Нічної Пісні на сході.", [3] = "Доставте лист Шиндрел до Кейнета Штиля в Лісову Пісню.", [4] = "Маєш щось для мене?", [5] = "А, доповідь Шиндрел. Дуже дякую, {ім'я}. Шиндрел — відмінна стражниця, смілива та розумна. Я повинен вивчити доповідь і знайти сліди зла, що крокує Ясенедолом.", ["en"] = "Kayneth Stillwind", ["tasks"] = { ["Shindrell's Note"] = "лист від Шиндрел", ["Shindrell's Note (Provided)"] = "лист від Шиндрел (видано)" } },
    [460] = { [1] = "Частковий відпочинок", [2] = "Ти не виглядаєш як Гнилошкурий. Добре. Бо я вже втратив надію...\n\nМене звати Аларік, і я був колись слугою й охоронцем Тула. Він використав свою магію, щоб \"захистити\" мене від Чуми невмирущості, але натомість його заклинання дало мені нежиття — стан, від якого я не можу втекти. І після створення проклятих Гнилошкурих, Тул обезголовив мене... і віддав мою голову гнолам, як іграшку!\n\nБудь ласка, віднеси мене до мого тіла. Думаю, гноли поховали його тут, у фортеці Фенріса, біля стайні, у безіменній могилі.", [3] = "Принесіть голову Аларіка до його могили.", [4] = "Ця могила була викопана нашвидкуруч.", [5] = "Дякую, {ім'я}. Я боявся, що гноли знищили моє тіло. Добре знати, що вони цього не зробили.", ["en"] = "Resting in Pieces", ["tasks"] = { ["A Talking Head"] = "балакуча голова", ["A Talking Head (Provided)"] = "балакуча голова (видано)" } },
    [4601] = { [1] = "Блискочист 5200!", [2] = "Цей пристрій виділяється серед гномів, які намагаються протистояти божевіллю, що коїться за межами кімнати. На невеликій табличці на пристрої написано: \"Блискочист 5200\", а нижче текст:\n\n\"Ваші цінні речі вкриває товстий шар бруду? Блискочист 5200 поверне їм первісний блиск! Вставте предмет, який ви хочете очистити, і опустіть три срібні монети у монетоприймач. Дайте Блискочисту 5200 трохи попрацювати, і вуаля! Ваші речі стануть чистими та блискучими!\"", [3] = "Помістіть в Блискочист 5200 вкритий брудом предмет та три срібні монети.", [4] = "Схоже, що для того, щоб пристрій запрацював, йому потрібен вкритий брудом предмет і три срібні монети. Щойно ви помістите це все всередину, Блискочист 5200 має запрацювати...", [5] = "Ви поміщаєте вкритий брудом предмет і три срібні монети в Блискочист 5200 і машина оживає, з гудінням відшкрябуючи бруд з предмета. Гучний, несамовитий стукіт лунає зсередини машини, а його металевий корпус скрипить, хитаючись з боку в бік...", ["en"] = "The Sparklematic 5200!", ["tasks"] = { ["Grime-Encrusted Object"] = "вкритий брудом предмет", ["Grime-Encrusted Object (Provided)"] = "вкритий брудом предмет (видано)" } },
    [4602] = { [1] = "Блискочист 5200!", [2] = "Цей пристрій виділяється серед гномів, які намагаються протистояти божевіллю, що коїться за межами кімнати. На невеликій табличці на пристрої написано: \"Блискочист 5200\", а нижче текст:\n\n\"Ваші цінні речі вкриває товстий шар бруду? Блискочист 5200 поверне їм первісний блиск! Вставте предмет, який ви хочете очистити, і опустіть три срібні монети у монетоприймач. Дайте Блискочисту 5200 трохи попрацювати, і вуаля! Ваші речі стануть чистими та блискучими!\"", [3] = "Помістіть в Блискочист 5200 вкритий брудом предмет та три срібні монети.", [4] = "Схоже, що для того, щоб пристрій запрацював, йому потрібен вкритий брудом предмет і три срібні монети. Щойно ви помістите це все всередину, Блискочист 5200 має запрацювати...", [5] = "Ви поміщаєте вкритий брудом предмет і три срібні монети в Блискочист 5200 і машина оживає, з гудінням відшкрябуючи бруд з предмета. Гучний, несамовитий стукіт лунає зсередини машини, а його металевий корпус скрипить, хитаючись з боку в бік...", ["en"] = "The Sparklematic 5200!", ["tasks"] = { ["Grime-Encrusted Object"] = "вкритий брудом предмет", ["Grime-Encrusted Object (Provided)"] = "вкритий брудом предмет (видано)" } },
    [4603] = { [1] = "Блискочист знову в дії", [4] = "Блискочист 5200 порожній. Для початку роботи йому потрібен вкритий брудом предмет і три срібні монети!", [5] = "Блискочист 5200 оживає, хитаючись зі сторони в сторону. Всередині бруд, що вкрив предмет, розчиняється за допомогою спеціального очисника гномів.\n\nБлискочист 5200 зупиняється, сповіщаючи про це знайомим дзенькотом. У приймальному отворі машини лежить маленька акуратно загорнута коробка.", ["en"] = "More Sparklematic Action", ["tasks"] = { ["Grime-Encrusted Object"] = "вкритий брудом предмет", ["Grime-Encrusted Object (Provided)"] = "вкритий брудом предмет (видано)" } },
    [4604] = { [1] = "Блискочист знову в дії", [4] = "Блискочист 5200 порожній. Для початку роботи йому потрібен вкритий брудом предмет і три срібні монети!", [5] = "Блискочист 5200 оживає, хитаючись зі сторони в сторону. Всередині бруд, що вкрив предмет, розчиняється за допомогою спеціального очисника гномів.\n\nБлискочист 5200 зупиняється, сповіщаючи про це знайомим дзенькотом. У приймальному отворі машини лежить маленька акуратно загорнута коробка.", ["en"] = "More Sparklematic Action", ["tasks"] = { ["Grime-Encrusted Object"] = "вкритий брудом предмет", ["Grime-Encrusted Object (Provided)"] = "вкритий брудом предмет (видано)" } },
    [4605] = { [1] = "Блискочист 5200!", [5] = "Блискочист 5200 зупинився так само різко, як і почав. Віконце для предметів відкривається з дзенькотом, і ньому лежить маленька акуратно загорнута коробка з бантиком. Схоже, що Блискочист 5200 також упаковує предмети після очищення. Навіть якщо предмет все ще брудний, принаймні тепер він загорнутий у красиву коробочку.\n\nЩо ж, є лише один спосіб дізнатися, чи він впорався...", ["en"] = "The Sparklematic 5200!" },
    [4606] = { [1] = "Блискочист 5200!", [5] = "Блискочист 5200 зупинився так само різко, як і почав. Віконце для предметів відкривається з дзенькотом, і ньому лежить маленька акуратно загорнута коробка з бантиком. Схоже, що Блискочист 5200 також упаковує предмети після очищення. Навіть якщо предмет все ще брудний, принаймні тепер він загорнутий у красиву коробочку.\n\nЩо ж, є лише один спосіб дізнатися, чи він впорався...", ["en"] = "The Sparklematic 5200!" },
    [462] = { [1] = "<UNUSED>", [2] = "Окрім тебе, ми послали двох розвідників через Алгаз. Повернувся лише один. Ось що він дізнався:\n\nДраконячі Пащі послали одного зі своїх лейтенантів, Марука Змієлуску, щоб організувати команду орків в Алгазі та перерізати сухопутний шлях до гавані Менетіл!\n\nМи повинні зупинити це зараз. Знищити Марука, а потім доповісти Валстагу Залізній Щелепі в гавані Менетіл.\n\nШтаб-квартира Марука знаходиться в невеликій печері, через ставок між другим і третім тунелями Алгазу. Менетіл знаходиться через Алгаз, потім на захід вздовж дороги.", [3] = "Убити Марука Звіролуска\n\nДоповісти Валстагу Залізнощелю в Менетил-Харбор.", ["en"] = "<UNUSED>", ["tasks"] = { ["Ma'ruk Wyrmscale slain"] = "Ма'рук Змієлуска: убито" } },
    [4621] = { [1] = "Бережися, адмірал!", [2] = "Слухай уважно, {стать:моряче:морячко}... Сила Грабіжної Бухти — це те, що не дозволяє нам, піратам Кривавого Вітрила, плавати, де заманеться і грабувати все, що нам заманеться. Якби ти {стать:приставив:приставила} ножа командувачу флоту Морському Рогу, нам би були не страшні кораблі Грабіжної Бухти. Якби ти {стать:встромив:встромила} ножа в барона Ревілґаза, ми б не підкорялись їхнім законам.\n\nЯкщо ти хочеш стати почесним адміралом серед нас — так, АДМІРАЛОМ, ти приставиш ножа їм обом, як я і сказав. А тепер іди, {стать:хлопче:дівчино} та повертайся до мене тільки тоді, коли завершиш справу.", [3] = "Вбийте командувача флоту Морського Рога і барона Ревілґаза з Грабіжної Бухти, а потім поверніться до командувача флоту Фіраллона на борт \"Багряної вуалі\", що біля узбережжя Тернистої долини.", [4] = "Ти вже {стать:повернувся:повернулася}, клятий дьоготь! Ти {стать:зробив:зробила}, що я наказав? Підведеш нас і підеш по дошці!", [5] = "Стояти... Адмірал {ім'я}! Ти {стать:пірат з піратів, хлопчику:піратка з піраток, дівчинко}!\n\nЯ з радістю дарую тобі цей капелюх. Ти ніде не знайдеш подібного і кожен, хто дивитиметься на тебе, побачить, що ти — адмірал флоту Кривавого Вітрила!", ["en"] = "Avast Ye, Admiral!", ["tasks"] = { ["3000 reputation with Bloodsail Buccaneers"] = "3000 репутації у Піратів Кривавого Парусу", ["Baron Revilgaz"] = "барон Ревілґаз", ["Baron Revilgaz slain"] = "барон Ревілґаз: убито", ["Fleet Master Seahorn"] = "командувач флоту Морський Ріг", ["Fleet Master Seahorn slain"] = "командувач флоту Морський Ріг: убито" } },
    [4642] = { [1] = "Сполучення впливів", [2] = "Ось, запакований слизень, створений зі скверноліських зразків, які ти {стать:роздобув:роздобула}. Віднеси футляр у кратер Ун'ґоро та знайди чистого слизня... первісний різновид чудово підійде. Коли будеш достатньо близько, випусти слизня з футляра, і ми побачимо, як вони один на одного зреагують.\n\nПісля завершення експерименту принеси мені зразки того, що там залишиться. Я очікуватиму на тебе тут, в Апотекарії.", [3] = "Принесіть зразок об'єднаного слизу хімікові Паливку в Підмістя.", [4] = "Як проходить експеримент, {Ім'я}? Я продовжу досліджувати зразки, які ти для мене {стать:роздобув:роздобула}: я починаю бачити, чому леді Сильвана настільки зацікавлена цими створіннями. Якщо вони дійсно є частинками Старих Богів, тоді хтозна, як це можна використати нам на користь.", [5] = "О, це просто чудово, {Ім'я}. Просто чудово.\n\nЯка історія... Хто б міг подумати, що вони так взаємодіятимуть один з одним... Мені потрібно буде проводити більше часу за вивченням умов довкілля, що спричинили зміни в цих створіннях.\n\nПоки що я продовжу своє дослідження. Можливо, ми скоро знову поговоримо. А до того часу, бажаю тобі всього найкращого.", ["en"] = "Melding of Influences", ["tasks"] = { ["Merged Ooze Sample"] = "об'єднаний зразок слизу", ["Merged Ooze Sample (Provided)"] = "об'єднаний зразок слизу (видано)" } },
    [466] = { [1] = "Пошук спалахіту", [2] = "Я чув про рідкісну руду — спалахіт, яка знайдена у Заболотті, в печері на північний захід від тунелю Альґаз. Вона дуже нестійка, нею складно користуватись не підірвавши себе у повітря. Однак, я впевнений, що якщо виплавити її належним чином, то можна зробити потужні снаряди для гармат!\n\nЗдобудь мені спалахітову руду, а я поки пошукаю когось вельми сміливого задля цього досліду.\n\nІ ще, щоб видобути ту руду, тобі потрібні навички у гірництві. Якщо в тебе немає необхідних знань, то... відправ до шахти друга, який зможе це зробити!", [3] = "Принесіть 6 партій спалахітової руди пілотові Камнеладу у Дун-Морог.", [4] = "І де ця руда, {ім'я}?!", [5] = "Ти {стать:здобув:здобула} руду! Молодець, {ім'я}! Я одразу відправлю когось попрацювати з нею. Будемо сподіватися, що він не підірве себе!", ["en"] = "Search for Incendicite", ["tasks"] = { ["Incendicite Ore"] = "спалахітова руда", ["Incendicite Ore (Provided)"] = "спалахітова руда (видано)" } },
    [4661] = { [1] = "Тест на псування - Сквернолісся", [4] = "Ви берете зразок слимака зі Сквернолісся та розкладаєте його в різні трубочки та мензурки на столі. Коли все починає кипіти та бризкати, слиз змінює кольори. Як тільки процес сповільнюється та рідини заспокоюються, ви бачите невелику чашу Петрі з вашими зміненими скверноліськими зразками слизу та якимись іншими залишками.", [5] = "Ви берете чашу Петрі зі зразком слизу всередині. Єдиний спосіб вияснити, чи зразок достатньо чистий - відкрити посудину й особисто оглянути її вміст. В ідеалі, ви знайдете там зразок, який відповідає критеріям хіміка Паливка.", ["en"] = "Testing for Corruption - Felwood", ["tasks"] = { ["Felwood Slime Sample"] = "зразок сквернолісного слизу", ["Felwood Slime Sample (Provided)"] = "зразок сквернолісного слизу (видано)" } },
    [4681] = { [1] = "Викинуті на берег", [2] = "Ця викинута на берег істота — не єдина на Темнобережжі. Вздовж узбережжя їх ще багато, та й у воді також. Я хотіла б, щоб ти {стать:дослідив:дослідила} ще одні рештки, про які нам відомо. Повідомляють, що вони лежать у воді на захід від Аубердіна, біля затонулого судна. Повертайся до мене з усіма знахідками, що можуть допомогти нашим дослідженням.\n\nКрім того, у твоїх подорожах тобі можуть трапитись інші істоти. Якщо щось знайдеш — будь ласка, не забудь принести це нам для досліджень!", [3] = "Добудьте рештки морської черепахи зі скелета морської черепахи, що лежить на захід від Аубердіну і поговоріть з Ґвенніт Блі'Леґґонд в Аубердіні.", [4] = "Після того, як ти дослідиш рештки істоти у воді на захід звідси, я зможу подати належний звіт до храму Місяця в Дарнасі. Можливо, тоді ми зможемо з'ясувати причину, по якій дедалі більше цих нещасних істот викидається на берег Темнобережжя.", [5] = "Ти неймовірно {стать:допоміг:допомогла} нам сьогодні. Тепер у нас є всі шанси дізнатись причину, з якої ці істоти викидаються на берег Темнобережжя. Думка про те, що вони можуть тікати з околиць Тельдрассіля, викликає занепокоєння. Якщо ти зустрінеш інших створінь під час своїх мандрів — будь ласка, повідом мені. Наші дослідження тут тільки починаються.\n\nВід імені храму Місяця, прошу, прийми це в знак подяки за твої зусилля. Дякую, {ім'я}!", ["en"] = "Washed Ashore", ["tasks"] = { ["Sea Turtle Remains"] = "рештки морської черепахи", ["Sea Turtle Remains (Provided)"] = "рештки морської черепахи (видано)" } },
    [4701] = { [1] = "Знайти й знищити", [2] = "Ти, безсумнівно, {стать:бачив:бачила} воргів, якими командують орки Чорнокаменю.\n\nЦікаво те, що скільки б ми їх не вбивали, їхня кількість не зменшується. Наші розвідники доповіли, що привозять їх з Чорноскельного шпиля — столиці орків Чорнокаменю, там їх вирощують та тренують. Ти маєш відправитись в Чорноскельний шпиль та знайти джерело цієї загрози. Знайти... й знищити.\n\nЩасти тобі, {ім'я}. Нехай Кенарій береже тебе...", [3] = "Відправляйтесь на Чорноскельний шпиль і знищте джерело загрози воргів. Коли ви йшли від Гелендіса, він вигукнув вслід ім'я: Галікон. Саме так орки називають цього ворга.", [4] = "Ти вже {стать:знайшов:знайшла} та {стать:знищив:знищила} джерело загрози воргів?", [5] = "Не думай про те, чи страждала вона, {ім'я}. Цей звір був зіпсований темною магією. Ти {стать:надав:надала} Альянсу велику послугу і за це отримаєш нагороду.", ["en"] = "Put Her Down", ["tasks"] = { ["Halycon"] = "Галікон", ["Halycon slain"] = "Галікон: убито" } },
    [4723] = { [1] = "Викинута на берег морська істота", [2] = "На узбережжі Кромки туману лежать рештки викинутого на берег молотника — набагато більшого, ніж можна було б очікувати побачити на Темнобережжі. Невідомо, як ця істота опинилася тут. Зграя мурлоків, що ласує цією тушею, навіть в такій чисельності занадто слабка, щоб здолати такого звіра.\n\nХоча частину туші вже об'їли, її все ще достатньо, щоб взяти зразок для досліджень Ґвенніт Блі'Леґґонд в Аубердіні.", [3] = "Принесіть кістки морської істоти Ґвенніт Блі'Леґґонд в Аубердін.", [4] = "Можливо, одного дня ми знайдемо спосіб врятувати цих бідолашних створінь від даремної смерті на узбережжі Темнобережжя. А поки що ми маємо продовжувати наші дослідження!\n\nВітаю, {ім'я}! Що в тебе нового?", [5] = "Ще одна знахідка — молодець, {ім'я}! Ці рештки будуть вивчені належним чином, щойно потраплять до Дарнасу. Будь ласка, прийми цю невелику плату за рештки, надані для наших досліджень.", ["en"] = "Beached Sea Creature", ["tasks"] = { ["Sea Creature Bones"] = "кістки морської істоти", ["Sea Creature Bones (Provided)"] = "кістки морської істоти (видано)" } },
    [4724] = { [1] = "Матір зграї", [2] = "Дехто каже, що ворги, яких контролюють орки Чорнокаменю — створіння надприродних сил. Інші кажуть, що це не справжні ворги, а порода демонічних псів, подарована оркам занепалим владикою безодні.\n\nПравда не така надумана, але не менш страшна. Ворги Чорнокаменю походять від Галікон та її самця. Галікон — це велетенська праматір, що висиджує їх у лігві. Хто її самець? Ті, хто його бачив, ще не повертались живими, щоб розповісти про це.\n\nЗавдавай удару прямо в серце зграї воргів. Вбий Галікон. І, {ім'я}, будь {стать:обережним:обережною}.", [3] = "Вбийте Галікон, матір зграї воргів Кривавої Сокири.", [4] = "Вбивши матір зграї, ми зможемо почати винищувати вартових воргів на Шпилі та зрештою зайти в місто.", [5] = "Скажені цуценята? Ґізрул-Поневолювач? І ти {стать:вижив:вижила} та розповідаєш цю історію?! Неймовірно! Ти заслуговуєш на винагороду!", ["en"] = "The Pack Mistress", ["tasks"] = { ["Halycon"] = "Галікон", ["Halycon slain"] = "Галікон: убито" } },
    [4725] = { [1] = "Викинута на берег морська черепаха", [2] = "На узбережжі лежать чергові рештки викинутої на берег морської черепахи. До панцира черепахи прикріплено покинутий візок. Можливо, цю істоту привели до берега невідомі істоти, і вона не сама викинулася на берег, на відміну від інших істот. Тепер рештки цієї істоти стали домівкою для сіромлистих мурлоків, які ласують падаллю.\n\nУ візку ви знаходите коробку з дивними позначками. Можливо, Ґвенніт Блі'Леґґонд з Аубердіну зможе їх розтлумачити.", [3] = "Принесіть коробку з дивними відмітками до Ґвенніт Блі'Леґґонд в Аубердін.", [4] = "Приємно знову бачити тебе, {ім'я}. Ми докладаємо великих зусиль, щоб дізнатися, чому величні морські істоти викидаються на берег Темнобережжя, але на кожну знайдену відповідь постає два нових запитання.\n\nТи {стать:прийшов:прийшла}, щоб знову допомогти нашим дослідженням?", [5] = "Я чула про візки, схожі на той, що ти {стать:знайшов:знайшла} на спині черепахи. Я думаю, що це візок наг, що використовується як у бою, так і для транспортування їхніх припасів на суші. Позначки на ящику також зроблені нагами. Це пояснює їхню раптову присутність у північній частині Темнобережжя.\n\nЯ відправлю цю скриньку до Дарнасу разом з іншими твоїми знахідками. А це — тобі. Ще раз дякую за допомогу.", ["en"] = "Beached Sea Turtle", ["tasks"] = { ["Strangely Marked Box"] = "коробка з дивним маркуванням", ["Strangely Marked Box (Provided)"] = "коробка з дивним маркуванням (видано)" } },
    [4726] = { [1] = "Сутність малечі", [2] = "Я досліджувала драконів у Палаючих степах протягом кількох тижнів і, нарешті, трапився прорив! Я створила пристрій — драко-в'язник 900. Він може захоплювати сутність малечі драконів!\n\nПринаймні, я так думаю.\n\nОсь, візьми пристрій і використай його в битві з малечею в Палаючому степі. Поки вони перебувають під впливом пристрою, переможи їх і пристрій звільнить їхню сутність.\n\nЯкщо так станеться, то чудово! Принеси мені зразки, щоб я могла їх дослідити!", [3] = "Принесіть 8 сутностей малечі та драко-в'язник 900 до Тінкі Пароварченко на Жевріючу Вершину в Палаючий степ.", [4] = "Ти {стать:зібрав:зібрала} сутності малечі, {ім'я}? Не можу дочекатися, щоб дослідити їх.\n\nКрім того... мій покровитель не з тих, кого хочеться розчаровувати.", [5] = "Спрацювало! Сутність у тебе! Молодець, {ім'я}! Молодець!\n\nЦя сутність надзвичайно допоможе моїм дослідженням. Я сподіваюся одного дня дізнатися, як захоплювати живих драконів або хоча б їхні яйця. Якби мені це вдалося, то мені б заздрили вчені з усього світу!\n\nМій роботодавець теж був би задоволений, і як я вже говорила раніше, такого, як він краще не засмучувати...", ["en"] = "Broodling Essence", ["tasks"] = { ["Broodling Essence"] = "сутність малечі", ["Broodling Essence (Provided)"] = "сутність малечі (видано)", ["Draco-Incarcinatrix 900"] = "драко-в'язник 900", ["Draco-Incarcinatrix 900 (Provided)"] = "драко-в'язник 900 (видано)" } },
    [4729] = { [1] = "Екзотичні тварини Кіблера", [2] = "Тобі, напевно, цікаво, що я тут роблю. Подивись на клітки! Хіба це не очевидно?\n\nЯ, в першу чергу, люблю тварин, але за професією я торговець. Я шукаю та приручаю екзотичних тварин для багатих і знаменитих клієнтів, які хочуть зробити їх своїми домашніми улюбленцями\n\nТи, напевно, захочеш спитати, \"Що я можу зробити для тебе, Кіблере?\". Відповідь проста: візьми цю клітку для звірів та впіймай мені кілька цуценят воргів. За це я приручу одного з них та віддам тобі!", [3] = "Відправляйтеся на Чорноскельний шпиль і знайдіть там цуценят воргів Кривавої Сокири. Використайте клітку, щоб захопити маленьких звірюк. Принесіть Кіблеру клітку з цуценям ворга.", [4] = "<Кіблер зайнятий суперечкою з Опусом.>", [5] = "Ти {стать:приніс:принесла} їх саме вчасно, {ім'я}. Ще трохи і я б не зміг їх приручити! Дай мені хвильку і ти зможеш забрати одного з цих малюків додому.", ["en"] = "Kibler's Exotic Pets", ["tasks"] = { ["Caged Worg Pup"] = "клітка з цуценям ворга", ["Caged Worg Pup (Provided)"] = "клітка з цуценям ворга (видано)" } },
    [4734] = { [1] = "Замороження яєць", [2] = "{ім'я}, я наполегливо працювала над новим пристроєм, який я назвала яйцеморозкопом! Він спроєктований так, щоб направити згусток холодної енергії на яйце чорного дракона та заморозити його! Можеш випробувати його для мене?\n\nЯ чула, що високо на Чорноскельному шпилі дракони мають лігво, де висиджують свої яйця. Туди тобі й потрібно піти, щоб перевірити яйцеморозкоп. Потім розкажеш мені, як все пройшло!\n\nІ не хвилюйся. Заморожені драконячі яйця не несуть загрози. Тобі треба боятися тих, що теплі!", [3] = "Використайте прототип яйцеморозкопа на яйці в Гніздів'ї.", [4] = "{Ім'я}, ти {стать:випробував:випробувала} яйцеморозкоп?", [5] = "Він працює? Чудово! Я так і думала!\n\nПоки тебе не було, я розробила нову версію яйцеморозкопа. Цей має набагато більший радіус дії.\n\nОсь, візьми собі, раптом випадково повернешся на Чорноскельний шпиль.", ["en"] = "Egg Freezing", ["tasks"] = { ["Eggscilloscope Prototype"] = "прототип яйцеморозкопа", ["Eggscilloscope Prototype (Provided)"] = "прототип яйцеморозкопа (видано)" } },
    [4735] = { [1] = "Збір яєць", [2] = "{Ім'я}, нарешті я готова досліджувати справжні драконячі яйця! Ось, візьми цей яйцезбирач. Він призначений для захоплення драконячого яйця і підготовки його до транспортування. Повертайся в Гніздів'я і скористайся яйцезбиральним пристроєм.\n\nІ не забудь спочатку заморозити їх, бо вони можуть вилупитися, поки ти їх захоплюватимеш!\n\nКоли назбираєш достатньо яєць, принеси їх мені!", [3] = "Зберіть 8 яєць драконів та віднесіть їх до Тінкі Пароварченко на Жевріючу Вершину, що в Палаючому степу, разом з яйцезбиральним пристроєм.", [4] = "Ти {стать:зібрав:зібрала} яйця, {ім'я}? Мій покровитель дізнався, що ти збираєш для мене яйця і хоче якомога скоріше отримати їх!", [5] = "Ого, ти {стать:зробив:зробила} це! Яйцезбиральний пристрій спрацював! Я геній!\n\nДякую тобі, {ім'я}. Мій покровитель дуже зрадіє, коли отримає ці яйця...", ["en"] = "Egg Collection", ["tasks"] = { ["Collected Dragon Egg"] = "зібране яйце дракона", ["Collected Dragon Egg (Provided)"] = "зібране яйце дракона (видано)", ["Collectronic Module"] = "яйцезбиральний пристрій", ["Collectronic Module (Provided)"] = "яйцезбиральний пристрій (видано)" } },
    [4736] = { [1] = "У пошуках Менари Пустоплестої", [2] = "А, привіт, {ім'я}. Ти добре просуваєшся у своєму навчанні. Так добре, що я думаю, ти заслуговуєш на винагороду за свою важку роботу — і за те, що сила магії все ще не поневолила тебе.\n\nЯкщо тобі цікаво, то звернись до Менари Пустоплестої в Брашпилі. Вона зараз перебуває в вежі Страгада Фарсана, що над містом.\n\nВона не дуже привітна, {ім'я}, тому не очікуй жодних похвал. Але якщо будеш наполегливо працювати, вона подбає про тебе.", [3] = "Поговоріть з Менарою Пустоплестою в Степах.", [5] = "А, то тебе послав Шипшилючка. Добре. Значить, чутки поширюються досить далеко, щоб знайти майбутніх учнів. Це мене тішить.\n\nЦе типово для нас, {ім'я}, об'єднуватися, незалежно від раси. Це особливо важливо, оскільки ті, з ким ми маємо справу найчастіше, не розрізняють нас у своїй злобі, якщо нам не вдається їх заспокоїти або належним чином контролювати.\n\nЯ відчуваю, що ти {стать:навчився:навчилася} багатьом речам, і якщо ти {стать:згоден:згодна}, я допоможу тобі створити інструменти, які доповнять твої навички.", ["en"] = "In Search of Menara Voidrender" },
    [4737] = { [1] = "У пошуках Менари Пустоплестої", [2] = "Хм, ти все ще намагаєшся стати {стать:сильнішим:сильнішою}. Не сумніваюся, рано чи пізно залежність від скверни заволодіє тобою, і ти станеш {стать:рабом:рабинею} того, над чим так прагнеш здобути владу.\n\nПфах! Ти {стать:дурень:дурепа}! Час доведе мою правоту — ніщо інше... тільки час.\n\nАле, здається, не всі згодні з Зевростом. Здається, Менара готова створити предмети, що допоможуть тобі стати {стать:могутнішим:могутнішою} та приборкати власну силу. Якщо тебе це зацікавило, то йди до Брашпиля в Степи. Вона живе у вежі над містом.", [3] = "Поговоріть з Менарою Пустоплестою в Степах.", [5] = "А, то тебе прислав Зеврост. Добре. Значить, чутки поширюються досить далеко, щоб знайти майбутніх учнів. Це мене тішить.\n\nЦе типово для нас, {ім'я}, об'єднуватися, незалежно від раси. Це особливо важливо, оскільки ті, з ким ми маємо справу найчастіше, не розрізняють нас у своїй злобі, якщо нам не вдається їх заспокоїти або належним чином контролювати.\n\nЯ відчуваю, що ти {стать:навчився:навчилася} багатьом речам, і якщо ти {стать:згоден:згодна}, я допоможу тобі створити інструменти, які доповнять твої навички.", ["en"] = "In Search of Menara Voidrender" },
    [4738] = { [1] = "У пошуках Менари Пустоплестої", [2] = "Давай будемо чесні, {ім'я}: я не вважаю, що ти {стать:готовий:готова} до такої відповідальності. Я не думаю, що допомога в створенні будь-якого предмета сили — це щось, в чому має брати участь новачок; особливо {стать:той:та}, хто не має достатнього досвіду.\n\nАле не мені вирішувати. Це вирішуватимуть сильні світу цього, або, принаймні, ті, хто бажає обдарувати тебе такими дарами.\n\nЯкщо тобі цікаво дізнатися більше, раджу звернутися до Менари Пустоплестої в Брашпилі. Зазвичай вона мешкає у вежі над містом.", [3] = "Поговоріть з Менарою Пустоплестою в Степах.", [5] = "А, то тебе послала Демізетта. Добре. Значить, чутки поширюються досить далеко, щоб знайти майбутніх учнів. Це мене тішить.\n\nЦе типово для нас, {ім'я}, об'єднуватися, незалежно від раси. Це особливо важливо, оскільки ті, з ким ми маємо справу найчастіше, не розрізняють нас у своїй злобі, якщо нам не вдається їх заспокоїти або належним чином контролювати.\n\nЯ відчуваю, що ти {стать:навчився:навчилася} багатьом речам, і якщо ти {стать:згоден:згодна}, я допоможу тобі створити інструменти, які доповнять твої навички.", ["en"] = "In Search of Menara Voidrender" },
    [4739] = { [1] = "У пошуках Менари Пустоплестої", [2] = "{Клас:к}! Так, саме ти!\n\nЯ бачу в тебе є не все спорядження, але очевидно, що ти {стать:готовий:готова} — у тобі відчувається впевненість. Так, я бачу це зараз.\n\nЯкщо ти вважаєш, що {стать:готовий:готова}, Менара Пустоплеста зможе тебе чомусь навчити. Вона проводить час, навчаючи молодших учнів арканічній магії. Вона навіть дарує подарунки тим, хто проходить її випробування.\n\nЯкщо тобі цікаво — вирушай до Брашпиля в Степи. Вона живе над містом у вежі Страгада.", [3] = "Поговоріть з Менарою Пустоплестою в Степах.", [5] = "А, то тебе прислав Каел. Добре. Значить, чутки поширюються досить далеко, щоб знайти майбутніх учнів. Це мене тішить.\n\nЦе типово для нас, {ім'я}, об'єднуватися, незалежно від раси. Це особливо важливо, оскільки ті, з ким ми маємо справу найчастіше, не розрізняють нас у своїй злобі, якщо нам не вдається їх заспокоїти або належним чином контролювати.\n\nЯ відчуваю, що ти {стать:навчився:навчилася} багатьом речам, і якщо ти {стать:згоден:згодна}, я допоможу тобі створити інструменти, які доповнять твої навички.", ["en"] = "In Search of Menara Voidrender" },
    [4742] = { [1] = "Печатка Вознесіння", [2] = "Як бачиш, неприкрашена печатка має три порожніх гнізда. Кожне з них має бути заповнене відповідними самоцвітами, що представляють певного правителя. Після цього властитель Змійталак, господар нижньої цитаделі, повинен викувати печатку у полум'ї Крила чорних драконів.\n\nТи маєш розуміти, {стать:смертний:смертна}: шанс того, що один з трьох генералів нижньої цитаделі матиме при собі самоцвіт влади у певний момент часу, мізерно малий. Будь {стать:уважним:уважною} в пошуках і не втрачай рішучості!", [3] = "Знайдіть три самоцвіти влади: самоцвіт Зотлілого Терену, самоцвіт Кам'яного Шпиля та самоцвіт Кривавої Сокири. Принесіть їх Велану разом з неприкрашеною печаткою Вознесіння.\n\nОсь генерали, про яких розповідав Ваелан: воєначальник Вун з клану Зотлілого Терену, верховний повелитель Омокк з клану Кам'яного Шпиля та властитель Змійталак з клану Кривавої Сокири.", [4] = "Хоробрість і терпіння понад усе, {стать:смертний:смертна}!", [5] = "<Образ Велана на мить розпливається.>\n\n<Самоцвіти, які ви зібрали, зникли.>\n\nНекована печатка Вознесіння готова. Настав час для останнього кроку.", ["en"] = "Seal of Ascension", ["tasks"] = { ["Gemstone of Bloodaxe"] = "самоцвіт Кривавої Сокири", ["Gemstone of Bloodaxe (Provided)"] = "самоцвіт Кривавої Сокири (видано)", ["Gemstone of Smolderthorn"] = "самоцвіт Зотлілого Терену", ["Gemstone of Smolderthorn (Provided)"] = "самоцвіт Зотлілого Терену (видано)", ["Gemstone of Spirestone"] = "самоцвіт Кам'яного Шпиля", ["Gemstone of Spirestone (Provided)"] = "самоцвіт Кам'яного Шпиля (видано)", ["Unadorned Seal of Ascension"] = "неприкрашена печатка Вознесіння", ["Unadorned Seal of Ascension (Provided)"] = "неприкрашена печатка Вознесіння (видано)" } },
    [4743] = { [1] = "Печатка Вознесіння", [2] = "Мало хто з чорних драконів, окрім тих, що перебувають у верхній цитаделі, здатен викувати печатку власним полум'яним диханням. Змійталак — один з таких драконів, але його волю неможливо зламати.\n\nТи {стать:повинен:повинна} відправитися в Змієділ, що знаходиться в Бруднолипкій трясовині. Там ти знайдеш древнього дракона, відомого як Вуглечвар. Зламай його волю, {ім'я}, та використай цю сферу на його ослаблену душу. В тебе буде кілька секунд, щоб підкорити розум звіра і роздмухати полум'я, яке викує печатку.", [3] = "Відправляйтесь в Змієділ, що знаходиться в Бруднолипкій трясовині. Знайдіть древнього дракона, Вуглечвара та бийте його безжально, поки зламаєте його волю.\n\nВ момент, коли воля звіра послабне, ви маєте поставити перед ним нековану печатку Вознесіння. Відразу після цього потрібно використати сферу драконічної енергії на його ослаблену душу та заволодіти його розумом. Підкоріть звіра і направте полум'я Крила чорних драконів на нековану печатку Вознесіння!", [4] = "Не гай часу, {стать:смертний:смертна}. Нефаріан наполегливо працює, щоб якомога швидше випустити своє зло в наш світ.", [5] = "Не рухайся, поки я накладаю останнє заклинання захисту.\n\n<Очі Велана перетворюються на дві вогняні кулі.>\n\nПечатка Вознесіння готова...\n\nЗнай, я наклав на артефакт потужні захисні чари. Коли тобі буде геть тяжко та здаватиметься, що все втрачено, сила червоних драконів буде у твоєму розпорядженні.", ["en"] = "Seal of Ascension", ["tasks"] = { ["Forged Seal of Ascension"] = "викувана печатка Вознесіння", ["Forged Seal of Ascension (Provided)"] = "викувана печатка Вознесіння (видано)" } },
    [4761] = { [1] = "Тандріс Вітроткач", [2] = "Твоя розвідка табору хутропузів надала нам важливу інформацію, яку слід передати Тандрісу Вітроткачу. Він люб'язно погодився виконувати обов'язки старійшини Аубердіна, мудро і справедливо керуючи нашим поселенням. Будь ласка, поділись з ним деталями щодо ситуації з хутропузами.\n\nЯ впевнений, що у нього є власні ідеї щодо джерела їхньої порчі. Можливо, разом ви зможете розробити план відновлення природної рівноваги!", [3] = "Поговоріть з Тандрісом Вітроткачем в Аубердіні.", [5] = "Вітаю тебе, {клас:к}. Ти дуже вчасно {стать:зайнявся:зайнялась} розвідкою ситуації з хутропузами. Ми вже довгий час маємо справу не лише з лісовими мешканцями, що тепер відверто вороже ставляться до нас, але й з порчею самого лісу. Сподіваюся, ти зможеш допомогти Аубердіну в ці тривожні часи.", ["en"] = "Thundris Windweaver" },
    [4762] = { [1] = "Скельноджерельна річка", [2] = "Води Скельноджерельної річки сповнилися бруду і порчі. Вона впадає в Кромку туману, і я боюся, що незабаром це лихо торкнеться й Аубердіна. Я підозрюю, що причиною забруднення є Чорнолісні хутропузи, які живуть вище по течії, але я також вважаю, що не вони є справжньою причиною.\n\nВізьми цю посудину і йди до гирла річки на північ звідси. Пройди вгору по течії до першого водоспаду і візьми там зразок води. Ти побачиш міст над ним. Коли візьмеш зразок — повертайся до мене в Аубердін.", [3] = "Прямуйте на північ від Аубердіна до першого водоспаду Скельноджерельної річки та візьміть там зразок води.\n\nПоверніться до Тандріса Вітроткача в Аубердін зі зразком води Скельноджерельної річки.", [4] = "Забруднення Скельноджерельної річки — це лише початок проблем на Темнобережжі. Зразок, який ти здобудеш, допоможе нам скласти план... і скоріше за все, план нападу.", [5] = "Я не здивований тим, наскільки сильно ця вода забруднена, але поглянь, якою мерзенною вона стає! Схоже, що діяти потрібно якнайшвидше, чи не так, {ім'я}?\n\nНа схід від нас знаходиться Сквернолісся. Це і є справжнє джерело порчі, я вже бачив таке у минулому. Я впевнений, що цей зразок це підтвердить. Можливо, ми зможемо знайти засіб для зцілення, але нам знадобиться підтримка. І коли цей час настане, {ім'я}, я сподіваюся, що ти зможеш допомогти нам.", ["en"] = "The Cliffspring River", ["tasks"] = { ["Cliffspring River Sample"] = "зразок води зі Скельноджерельної річки", ["Cliffspring River Sample (Provided)"] = "зразок води зі Скельноджерельної річки (видано)" } },
    [4763] = { [1] = "Порча Чорнолісних", [2] = "Ми дізналися, що джерелом порчі хутропузів є сатир. Вони керують жертвами за допомогою талісманів, через які спрямовують магію. Якщо у хутропузів є шанс на порятунок, ми повинні виманити сатира і забрати його талісман!\n\nНаповни цю чашу з нашого місячного колодязя і збери зразки їжі хутропузів в їхньому північному таборі. Змішай їх і постав біля вогнища, що біля річки. Всі хутропузи, які поїдять з неї, частково очистяться, що і приверне увагу сатира... якого ти маєш вбити!", [3] = "Наповніть порожню чашу очищення в місячному колодязі Аубердіна.\n\nЗберіть зразок фруктів, горіхів і зерна з північних таборів чорнолісних хутропузів.\n\nЗмішайте зразки в чаші та поставте її біля найближчого до Скельноджерельної річки вогнища у північному таборі, викликавши таким чином сатира.\n\nЗаберіть у нього талісман порчі та принесіть його Тандрісу Вітроткачу в Аубердін.", [4] = "Талісман порчі — це жахливий пристрій, що слугує лише для спотворення природного балансу. Коли забереш його у сатира, що мучить фурболгів — принеси його мені для знищення і можна буде вважати що ми здобули велику перемогу!", [5] = "Ми тільки почали цю війну за звільнення нашого лісу, але сьогодні ми виграли битву! {ім'я}, жителі Аубердіна в неоплатному боргу перед тобою. Будь ласка, прийми це в знак нашої вдячності. Те, що ми дізналися сьогодні, може одного дня назавжди звільнити наших друзів-хутропузів від страждань.", ["en"] = "The Blackwood Corrupted", ["tasks"] = { ["Talisman of Corruption"] = "талісман порчі", ["Talisman of Corruption (Provided)"] = "талісман порчі (видано)" } },
    [4764] = { [1] = "Доленосна застібка", [2] = "Високо у Чорноскельному шпилі є кімната, яку колись називали залою Багатства. Саме там дворфи Темного Заліза зберігали свої реліквії, трофеї та предмети мистецтва.\n\nЦе було дуже давно. Кажуть, що зала розвалилась і тепер використовується для... менш важливих речей. Але я вірю, що деякі старі реліквії дворфів все ще можна знайти там.\n\nОднією з таких реліквій є доленосна застібка. Її поверхня настільки інкрустована рідкісними дорогоцінними каменями, що, як кажуть, вона змусить плакати будь-якого дворфа, який подивиться на неї.\n\nТи маєш дістати цю застібку, {ім'я}.", [3] = "Принесіть доленосну застібку Маярі Яскравокрилій в Палаючий степ.", [4] = "Ти {стать:знайшов:знайшла} застібку, {ім'я}? Мій покровитель щедро заплатить за неї.", [5] = "Ти {стать:знайшов:знайшла} її! Виявляється, чутки були правдою!\n\nДякую, {ім'я}. Мій клієнт, граф Ремінгтон Скеледуж, з радістю поповнить нею свою колекцію.", ["en"] = "Doomrigger's Clasp", ["tasks"] = { ["Doomrigger's Clasp"] = "доленосна застібка", ["Doomrigger's Clasp (Provided)"] = "доленосна застібка (видано)" } },
    [4765] = { [1] = "Посилка для Скеледужа", [2] = "Я запакувала доленосну застібку у ящик, тож вона готова до відправлення в Штормовій. {Ім'я}, ти мені дуже {стать:допоміг:допомогла}, чи можу я попросити тебе про останню послугу?\n\nДостав ящик графу Ремінгтону Скеледужу. Відправляйся в Штормовій, ти знайдеш його в замку. Впевнений, він зрадіє, коли побачить, що ти {стать:приніс:принесла}.", [3] = "Віднесіть ящик Скеледужа Ремінґтону Скеледужу в Штормовій.", [4] = "Мені сказали, що прийде посланець. З даром з Чорноскельного шпиля.\n\nЦе ти?", [5] = "А, то це ти! Дякую тобі, {ім'я}. І... якщо ти не {стать:знав:знала}... подяка дворянина з дому Скеледужів майже така ж цінна, як королівська.", ["en"] = "Delivery to Ridgewell", ["tasks"] = { ["Ridgewell's Crate"] = "ящик Скеледужа", ["Ridgewell's Crate (Provided)"] = "ящик Скеледужа (видано)" } },
    [4768] = { [1] = "Скрижаль Темнокаменя", [2] = "У скрижалі Темнокаменю зберігаються записи давно померлого дворфа Ургельда Темнокаменя. Він був великим алхіміком, але сучасники вважали його божевільним та, звісно ж, не брали до уваги його дослідження.\n\nВін викарбував свої дослідження на скрижалях і, я думаю, що одна з них лежить в Чорноскельному шпилі, у кімнаті, яку колись називали Залою Багатства. Мені не відомо, яка в неї зараз назва, бо мало хто ходить до Чорноскельної гори та ще менше повертається назад.\n\nАле якщо ти {стать:готовий:готова} прийняти таку небезпеку та принести мені скрижаль, я щедро віддячу тобі.", [3] = "Принесіть скрижаль Темнокаменя тінемагині Вівіан Лягроб у Карґат.", [4] = "Ти {стать:знайшов:знайшла} скрижаль, {ім'я}? Мені не терпиться вивчити її секрети.", [5] = "Чудово. В мене піде багато часу на вивчення формул, викарбуваних на цій скрижалі, але я впевнена, що ці дослідження того варті.\n\nДякую тобі, {ім'я}. Ти нам дуже {стать:допоміг:допомогла}.", ["en"] = "The Darkstone Tablet", ["tasks"] = { ["Darkstone Tablet"] = "скрижаль Темнокаменя", ["Darkstone Tablet (Provided)"] = "скрижаль Темнокаменя (видано)" } },
    [4769] = { [1] = "Вівіан Лягроб і скрижаль Темнокаменя", [2] = "Вівіан Лягроб надіслала мені листа з Карґату, що в Безплідних краях. Вона провела дослідження та вважає, що на Чорноскельному шпилі зберігається скрижаль з древніми текстами, які могли б допомогти нашому дослідженню. Їй потрібен хтось, хто добуде цю скрижаль зі Шпиля. Це важке завдання.\n\nЯкщо тебе це зацікавило, поговори з Вівіан у Карґаті.", [3] = "Поговоріть з тінемагинею Вівіан Лягроб.", [5] = "Це справді так. Я думаю, що у Чорноскельному шпилі зберігається скрижаль, яка містить старі алхімічні рецепти. Добре, що ти тут, мені якраз потрібна допомога з пошуком цієї скрижалі.\n\nВлаштовуйся зручніше, я введу тебе в курс справи.", ["en"] = "Vivian Lagrave and the Darkstone Tablet" },
    [4771] = { [1] = "Гамбіт Світанку", [2] = "Я поклала Гамбіт Світанку в коробку, яку ти {стать:приніс:принесла}, ту саму, в якій були драконячі яйця. Твоє завдання — доставити його вглиб Некроситету.\n\nНевмерлий маг Вектус очолює команду дослідників Скари... Віднеси Гамбіт Світанку в їхню кімнату, яку вони називають \"оглядовим залом\". Після цього він має зреагувати на знайдених там невмерлих та, якщо пощастить, знищить їх!\n\nПісля цього знищення Вектуса не буде проблемою. Правда ж?", [3] = "Розмістіть Гамбіт Світанку в оглядовій кімнаті Некроситету. Здолайте Вектуса, а потім поверніться до Бетіни Біґґльзінк.", [5] = "Ти {стать:зробив:зробила} це! Вектус переможений! А Гамбіт Світанку... спрацював?\n\nХм... Можливо, мій пристрій не зовсім виправдав очікувань, але я рада, що ти все одно {стать:впорався:впоралася}. Молодець, {ім'я}!\n\nСріблястий Світанок і добрі жителі Азерота в боргу перед тобою.", ["en"] = "Dawn's Gambit", ["tasks"] = { ["Vectus"] = "Вектус", ["Vectus slain"] = "Вектус: убито" } },
    [4781] = { [1] = "Матеріали для золотої кровомантії", [2] = "Твоє наступне завдання таке ж просте, як і перше, але тобі знадобиться допомога.\n\nМені потрібна золота нитка для вишивки мантії, але золоту нитку не так просто дістати, і дуже мало хто вміє її виготовляти. На щастя, той, хто вірний нашій справі, знає її секрети та готовий допомогти тим, хто підіймається в наших рядах.\n\nПринеси злиток золота до Зиска Добрострока в Грабіжну Бухту. Він кравець-майстер і з радістю спряде для тебе нитку. Золоті злитки плавляться досвідченими шахтарями. Звернись за допомогою до шахтаря.", [3] = "Принесіть злиток золота Зиску Добростроку у Тернисту долину.", [4] = "Золоті злитки, так... так. Принеси мені один, і подивимося, що можна зробити, щоб виткати для тебе нитку. Доти я б порадив тобі сконцентруватися на тому, щоб стати сильніше. Найважчі випробування ще попереду. І повір мені... ти пошкодуєш, що не {стать:підготувався:підготувалася}, незалежно від того, наскільки {стать:сильним:сильною} ти б не {стать:був:була}.", [5] = "Чудово, {ім'я}. Я радий, що ти {стать:зміг:змогла} так швидко знайти шахтаря, щоб той тобі допоміг. Чи ти {стать:зробив:зробила} його власноруч? В будь-якому випадку, ти добре {стать:впорався:впоралася}. Нитка з цього злитка вийде чудова.\n\nВиготовлення нитки займе деякий час, тому тобі доведеться повернутися трішки пізніше... Я взагалі-то відсилаю її принцесі, яку ми замкнули у вежі, і чия єдина робота — прясти золоті нитки... ні, серйозно. Я не жартую... Гаразд, жартую.", ["en"] = "Components for the Enchanted Gold Bloodrobe", ["tasks"] = { ["Gold Bar"] = "злиток золота", ["Gold Bar (Provided)"] = "злиток золота (видано)" } },
    [4782] = { [1] = "Матеріали для золотої кровомантії", [2] = "Повернись до Менари та скажи їй, що це займе деякий час, але я обов'язково зроблю це для неї... і для тебе. Скажи їй, щоб вона доручила тобі зібрати решту компонентів — до того моменту нитка повинна бути в мене. Тоді ти зможеш повернутися і забрати її.\n\nХай щастить, {ім'я}. А, і передай вітання Страгаду від мене, коли будеш там. От старий дивак... побудував вежу прямо поруч з Брашпилем... божевільний.", [3] = "Поверніться до Менари Пустоплестої в Степи.", [5] = "Чудово, ти {стать:повернувся:повернулася}, {ім'я}. А де нитка?\n\nА, я розумію. Це прийнятно. Гоблін і його брат ще жодного нас разу не підводили — думаю, цілком зрозуміло, що він не встиг зробити її прямо зараз. Нехай буде так... Тим часом ми займемося іншими справами.\n\nТи {стать:готовий:готова} до наступного кроку?", ["en"] = "Components for the Enchanted Gold Bloodrobe" },
    [4783] = { [1] = "Матеріали для золотої кровомантії", [2] = "Наступні компоненти ти знайдеш в Спустошищі, далеко на заході від Степів, за Каміннопазуристими горами.\n\nТам, все ще панує хаос після Розколу. Там ти пройдеш випробування як на силу, так і на хитрість — ти зіткнешся з породженнями ненависті з Палаючого Легіону.\n\nПринесіть мені кров сатирів племені Скаженолютих, які знаходяться на північному сході, та камінь молодшого пекельника з руїн Маннорок.\n\nМи використаємо обидві складові для створення твоєї мантії.", [3] = "Принесіть 10 флаконів крові скаженолютих сатирів і 1 камінь молодшого пекельника Менарі Пустоплестій в Степи.", [4] = "Спустошище — небезпечне місце: наги, велетні, сатири, Палаючий Легіон... Всі вони та войовничі клани кентаврів роблять цю землю дуже небезпечною, якщо ти не будеш {стать:обережним:обережною}.\n\nЯк я вже казала, це не лише випробування твоєї сили та хитрості, а й твого терпіння. Не втрачай пильності в цих землях, {ім'я}.", [5] = "Чудово, {ім'я}. Ці зразки дуже чудові. Я поки підготовлю їх, а ти тим часом можеш зайнятися останніми двома компонентами. Ти {стать:готовий:готова}?", ["en"] = "Components for the Enchanted Gold Bloodrobe", ["tasks"] = { ["Lesser Infernal Stone"] = "камінь молодшого пекельника", ["Lesser Infernal Stone (Provided)"] = "камінь молодшого пекельника (видано)", ["Vial of Hatefury Blood"] = "флакон крові скаженолютого сатира", ["Vial of Hatefury Blood (Provided)"] = "флакон крові скаженолютого сатира (видано)" } },
    [4784] = { [1] = "Матеріали для золотої кровомантії", [2] = "Тепер мені потрібні лише три речі, {ім'я}, і ми зможемо закінчити твою мантію.\n\nПерше — це тонка золота нитка, яку для тебе зробить Зиск. Повернись до нього в Грабіжну Бухту та забери її.\n\nДруге — добудь два жаристі вугілля у вогняних елементалів на височині Араті. Якщо я правильно пам'ятаю, вони знаходяться на заході, біля стіни Торадіна.\n\nНаостанок — уламок душі, який ти створиш самостійно.\n\nПісля того, як у тебе будуть всі компоненти — повертайся у вежу і я завершу мантію для тебе.", [3] = "Принесіть тонку золоту нитку, 2 жаристих вугілля та уламок душі Менарі Пустоплестій в Степи.", [4] = "Залишилося недовго, {ім'я}. Я обіцяю тобі. Мантія задовольнить твої потреби та безперечно дасть перевагу над твоїми опонентами.", [5] = "Чудово, {ім'я}! Компоненти у нас і ми готові.\n\nЯ впевнена, тобі сподобається результат.", ["en"] = "Components for the Enchanted Gold Bloodrobe", ["tasks"] = { ["Fine Gold Thread"] = "тонка золота нитка", ["Fine Gold Thread (Provided)"] = "тонка золота нитка (видано)", ["Smoldering Coal"] = "жаристе вугілля", ["Smoldering Coal (Provided)"] = "жаристе вугілля (видано)", ["Soul Shard"] = "уламок душі", ["Soul Shard (Provided)"] = "уламок душі (видано)" } },
    [4785] = { [1] = "Тонка золота нитка", [5] = "Ось, тримай, {ім'я}. І передай вітання від нас Менарі.\n\nМи очікуємо від тебе великих звершень. Можливо, коли Легіон паде на коліна, твоє ім'я буде виголошуватися на всі лади, прославляючи твою силу. Не можу дочекатися!", ["en"] = "Fine Gold Thread" },
    [4786] = { [1] = "Завершена мантія", [2] = "Зараз я шитиму для тебе мантію. Це займе всього кілька хвилин. Не відходь далеко.", [3] = "Почекайте доки Менара Пустоплеста завершить вашу мантію та поговоріть з нею.", [4] = "Хвилинку, {ім'я}...", [5] = "Готово, {ім'я}. Ось вона, твоя нагорода. Носи її з гордістю.\n\nТи дуже наполегливо {стать:працював:працювала} і я знаю, що в тебе велике майбутнє. Пам'ятай, що для того, щоб протистояти псуванню, що супроводжує наш шлях, потрібна велика воля і стійкість. Якщо твоя воля залишається незламною — на тебе чекає великий успіх.", ["en"] = "The Completed Robe", ["tasks"] = { ["Wait for Menara Voidrender to complete your item"] = "Зачекайте, поки Менара Розбійниця Порожнечі завершить ваш предмет." } },
    [4787] = { [1] = "Древнє яйце", [2] = "Пророцтво Мош'ару говорить про древнє яйце. Це реліквія часів, коли тролі правили великими імперіями, і воно має силу утримувати сутність Гаккара. Можливо, це єдиний спосіб захистити наш світ від його зла.\n\nПринеси мені древнє яйце, {ім'я:к}. Кажуть, що воно сховане глибоко в Джинта'Алорі, що у Внутрішніх землях, у печері за амфітеатром на вершині міста.", [3] = "Принесіть древнє яйце Є'кіньї в Танаріс.", [4] = "Ти {стать:дістав:дістала} древнє яйце? Я відчуваю, як прокидаються великі сили. Боюся, у нас обмаль часу.", [5] = "А, яйце у тебе! Я кланяюсь тобі, {ім'я:к}. Твою силу і хоробрість надовго запам'ятають.", ["en"] = "The Ancient Egg", ["tasks"] = { ["Ancient Egg"] = "древнє яйце", ["Ancient Egg (Provided)"] = "древнє яйце (видано)" } },
    [4788] = { [1] = "Останні скрижалі", [2] = "Поки я розшифровую третю та четверту скрижалі Мош'ару, ти маєш знайти п'яту і шосту! Це буде нелегко, бо вони у тролів племені Зотлілого Терену в Чорноскельному шпилі. Цей шпиль — в темній вогняній горі між Палаючим Степом та Випаленою ущелиною.\n\nЩасти тобі, {ім'я}. Чорноскельний шпиль — не місце для порядних людей...", [3] = "Принесіть п'яту та шосту скрижалі Мош'ару розвідувачу Залізочоботу в Танаріс.", [4] = "Ти {стать:був:була} на шпилі, {ім'я}? П'ята та шоста скрижалі у тебе?", [5] = "Неймовірно! Ти {стать:знайшов:знайшла} їх! Ти {стать:справжній герой:справжня героїня}, {ім'я}!\n\nЦе дуже добре, бо коли я прочитав скрижалі, які ти мені {стать:приніс:принесла}, я зрозумів, що нам не обійтись без {стать:героя, який:героїні, яка} зупинить те, що нас чекає...", ["en"] = "The Final Tablets", ["tasks"] = { ["Fifth Mosh'aru Tablet"] = "п'ята скрижаль Мош'ару", ["Fifth Mosh'aru Tablet (Provided)"] = "п'ята скрижаль Мош'ару (видано)", ["Sixth Mosh'aru Tablet"] = "шоста скрижаль Мош'ару", ["Sixth Mosh'aru Tablet (Provided)"] = "шоста скрижаль Мош'ару (видано)" } },
    [48] = { [1] = "Солодке бурштинове", [2] = "В землі, що на південь, де лози повзли,\nКолодязь є повний стрімкої води.\nПрозора та чиста, як Світла дочка,\nПринеси мені воду з того джерела.", [3] = "Принесіть воду святого джерела Лютобухові Громовару.", [4] = "Гик! Хо-хо! Хочеш на біс?\n\nВ землі, що на південь, де лози повзли,\nКолодязь є повний стрімкої води.\nПрозора та чиста, як Світла дочка,\nПринеси мені воду з того джерела.", [5] = "Гик! Хо-хо!", ["en"] = "Sweet Amber", ["tasks"] = { ["Holy Spring Water"] = "вода святого джерела", ["Holy Spring Water (Provided)"] = "вода святого джерела (видано)" } },
    [4801] = { [1] = "Е'ко кригозубів", [4] = "У Зимоключі ти будеш биться з великими кішками, яких називають кригозубами. Ці звірі володіють неймовірною швидкістю і хитростю. Якшо ти хочеш отримать швидкість як у кригозубів, принеси мені е'ко, які найдеш у них.\n\nПомни, якшо хочеш найти е'ко, у твоїй сумці має буть скарб Мав'арі.", [5] = "Мав'арі може створить джуджу для {ім'я}... Використовуй скарб Мав'арі, шоб накласти це джуджу на себе або своїх союзників.", ["en"] = "Frostsaber E'ko", ["tasks"] = { ["Frostsaber E'ko"] = "е'ко кригозубів", ["Frostsaber E'ko (Provided)"] = "е'ко кригозубів (видано)" } },
    [4802] = { [1] = "Е'ко зимокрайових", [4] = "У Зимоключі ти будеш биться з заблудлими істотами, які звуться Зимокрайовими хутропузами. Завдяки їхньому лідеру, вони набули неймовірної сили. Якшо ти хочеш отримать силу як у зимокрайових, принеси мені е'ко, яке найдеш у них.\n\nПомни, якшо хочеш найти е'ко, у твоїй сумці має буть скарб Мав'арі.", [5] = "Мав'арі може створить джуджу для {ім'я}... Використовуй скарб Мав'арі, шоб накласти це джуджу на себе або своїх союзників.", ["en"] = "Winterfall E'ko", ["tasks"] = { ["Winterfall E'ko"] = "е'ко зимокрайових", ["Winterfall E'ko (Provided)"] = "е'ко зимокрайових (видано)" } },
    [4803] = { [1] = "Е'ко щербозубів", [4] = "У Зимоключі ти будеш биться з великими ведмедями у яких дуже товста шкура. Ці ведмеді-щербозуби мають неймовірний захист. Якшо ти хочеш отримать стійкість до вогню, принеси мені е'ко, яке найдеш у щербозубів.\n\nПомни, якшо хочеш найти е'ко, у твоїй сумці має буть скарб Мав'арі.", [5] = "Мав'арі може створить джуджу для {ім'я}... Використовуй скарб Мав'арі, шоб накласти це джуджу на себе або своїх союзників.", ["en"] = "Shardtooth E'ko", ["tasks"] = { ["Shardtooth E'ko"] = "е'ко щербозубів", ["Shardtooth E'ko (Provided)"] = "е'ко щербозубів (видано)" } },
    [4804] = { [1] = "Е'ко студовіїв", [4] = "У Зимоключі ти будеш биться з великимилетючими істотами, яких називають студовіями. Ці звірі володіють силою та магією криги. Якшо ти хочеш отримать стійкість до криги, принеси мені е'ко, які ти знайдеш у студовіїв.\n\nПомни, якшо хочеш найти е'ко, у твоїй сумці має буть скарб Мав'арі.", [5] = "Мав'арі може створити заклинання для {ім'я}... Використовуй сховище Мав'арі, щоб накласти закляття на себе або своїх союзників.", ["en"] = "Chillwind E'ko", ["tasks"] = { ["Chillwind E'ko"] = "е'ко студовіїв", ["Chillwind E'ko (Provided)"] = "е'ко студовіїв (видано)" } },
    [4805] = { [1] = "Е'ко льодореп'яхових", [4] = "У Зимоключі ти будеш биться з великими істотами, яких називають льодореп'яховими єті. Ці звірі движуться повільно, але здатні ухиляться од багатьох ударів завдяки захисту, який дає їм густе хутро. Якшо ти хочеш отримать здатність ухилятися від атак, принеси мені е'ко, яке найдеш у них.\n\nПомни, якшо хочеш найти е'ко, у твоїй сумці має буть скарб Мав'арі.", [5] = "Мав'арі може створить джуджу для {ім'я}... Використовуй скарб Мав'арі, шоб накласти це джуджу на себе або своїх союзників.", ["en"] = "Ice Thistle E'ko", ["tasks"] = { ["Ice Thistle E'ko"] = "е'ко льодореп'яхових", ["Ice Thistle E'ko (Provided)"] = "е'ко льодореп'яхових (видано)" } },
    [4806] = { [1] = "Е'ко кригобоїв", [4] = "У Зимоключі ти будеш биться з великими крижаними гігантами, яких називають кригобоями. Вони володіють величезною силою і міццю. Якшо ти хочеш отримать силу кригобоїв, принеси мені е'ко, яке найдеш у них.\n\nПомни, якшо хочеш найти е'ко, у твоїй сумці має буть скарб Мав'арі.", [5] = "Мав'арі може створить джуджу для {ім'я}... Використовуй скарб Мав'арі, шоб накласти це джуджу на себе або своїх союзників.", ["en"] = "Frostmaul E'ko", ["tasks"] = { ["Frostmaul E'ko"] = "е'ко кригобоїв", ["Frostmaul E'ko (Provided)"] = "е'ко кригобоїв (видано)" } },
    [4807] = { [1] = "Е'ко диких совухів", [4] = "У Зимоключі ти будеш биться зі створіннями, шо володіють вродженими магічними здібностями. Ці дикі совухи володіють потужною магією. Якшо ти хочеш підвищить свій інтелект, принеси мені е'ко, які ти знайдеш у диких совухів.\n\nПомни, якшо хочеш найти е'ко, у твоїй сумці має буть скарб Мав'арі.", [5] = "Мав'арі може створить джуджу для {ім'я}... Використовуй скарб Мав'арі, шоб накласти це джуджу на себе або своїх союзників.", ["en"] = "Wildkin E'ko", ["tasks"] = { ["Wildkin E'ko"] = "е'ко диких совухів", ["Wildkin E'ko (Provided)"] = "е'ко диких совухів (видано)" } },
    [4808] = { [1] = "Фелнок Сталепружень", [2] = "У мене є до тебе ще одне прохання.\n\nМоє перше дослідження сутності показало, що яйця драконів можна заморозити та зберігати! Я хочу перевірити цю теорію, але для цього мені потрібні спеціальні інженерні компоненти. Мій колега, Фелнок Сталепружень, може їх виготовити.\n\nОтож, віднеси цей лист Фелноку. У ньому зазначено, що мені потрібно. Ти знайдеш Фелнока у Зимоключі, в містечку під назвою Завшегляд.", [3] = "Віднесіть лист Тінкі до Фелнока Сталепруженя.", [4] = "Тут холодно! Сподіваюся, ти {стать:приніс:принесла} мені ковдру!", [5] = "Це не ковдра! Що це? Лист від Тінкі? Цікаво, що вона хоче...\n\nОтже, вона вивчає драконів у Палаючому степі. Логічно — це хороше місце для вивчення драконів. Ох, поглянь! Тут написано, що їй потрібні деталі для приладу, який вона хоче створити. Здається тут я й маю допомогти, так?", ["en"] = "Felnok Steelspring", ["tasks"] = { ["Tinkee's Letter"] = "лист Тінкі", ["Tinkee's Letter (Provided)"] = "лист Тінкі (видано)" } },
    [4809] = { [1] = "Роги студовіїв", [2] = "У мене є майже все, що потрібно Тінкі, але мені бракує одного важливого компонента — рогів студовіїв, химер, що водяться в Зимоключі. Вони слугують потужним джерелом холоду, але мені потрібні лише неушкоджені роги, щоб виконати замовлення Тінкі.\n\nПринеси мені не неушкоджені роги студовіїв, і я підготую пакунок для Тінкі.", [3] = "Принесіть 8 неушкоджених рогів студовіїв Фелноку Сталепруженю.", [4] = "Ти {стать:зібрав:зібрала} роги студовіїв, {ім'я}?", [5] = "Це хороші екземпляри. Вони наповнені холодом! Дозволь мені одягнути рукавички, а потім упакувати їх разом з іншими речами, які потрібні Тінкі...", ["en"] = "Chillwind Horns", ["tasks"] = { ["Uncracked Chillwind Horn"] = "неушкоджений ріг студовія", ["Uncracked Chillwind Horn (Provided)"] = "неушкоджений ріг студовія (видано)" } },
    [4810] = { [1] = "Повернення до Тінкі", [2] = "Гаразд, все підготовлено, упаковано і готово до транспортування! Щасти тобі у дорозі, і не забудь сказати Тінкі, що вона в боргу переді мною!", [3] = "Принесіть пакунок Фелнока до Тінкі Пароварченко у Палаючий степ.", [4] = "{Ім'я}! {стать:Говорив:Говорила} з Фелноком? Ти {стать:приніс:принесла} потрібні мені компоненти?", [5] = "Ти {стать:приніс:принесла} їх! Чудово! Я одразу ж візьмуся за роботу! Щиро дякую тобі, {ім'я}!\n\nТи мені дуже {стать:допоміг:допомогла}. Та згодом мені може знадобитися допомога для ще важливіших завдань...", ["en"] = "Return to Tinkee", ["tasks"] = { ["Felnok's Package"] = "пакунок Фелнока", ["Felnok's Package (Provided)"] = "пакунок Фелнока (видано)" } },
    [4811] = { [1] = "Червоний кристал", [2] = "На схід звідси дедалі частіше помічають ворожих місячних совухів. Колись їх вважали добрими містичними істотами. І хоча дехто продовжує шанувати їх, безпека Аубердіна змушує мене ставитися до них прагматичніше.\n\nМені повідомили, що місячних совухів приваблює великий червоний кристал, що знаходиться на східному гірському хребті Темнобережжя. Але ніхто не знає, що це за кристал, і чи існує він взагалі. Я хочу, щоб ти {стать:знайшов:знайшла} його і {стать:розповів:розповіла} мені про нього детальніше.", [3] = "Прямуйте на схід від Аубердіна та пошукайте великий червоний кристал вздовж східного гірського хребта Темнобережжя. Повідомте про знахідку стражницю Ґлінду Нал'Шею в Аубердіні.", [4] = "Маєш що розказати про цей червоний кристал? Він справді існує?", [5] = "Отже, кристал справді існує, {ім'я}? Цікаво... в будь-якому разі, ти добре {стать:впорався:впоралась} із завданням, гарна робота!\n\nЩо це за кристал? І це не єдине питання. Чому він так приваблює місячних совухів? І чи несе він загрозу нам?\n\nУ мене є ще багато запитань, але щоб отримати відповіді на них, нам потрібно ретельніше вивчити цей кристал.", ["en"] = "The Red Crystal", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Locate the large, red crystal on Darkshore's eastern mountain range"] = "Знайдіть великий червоний кристал на східному гірському хребті Темного Берега" } },
    [4812] = { [1] = "Поки тече вода", [2] = "Візьми цю порожню посудину і наповни її водою з місячного колодязя тут, в Аубердіні. Така потужна магія має допомогти нам дізнатись більше про склад кристала. Просто полий його водою з колодязя, і поспостерігай за ним.\n\nХоч я й не думаю, що з тобою може щось статись, все ж будь {стать:обережний:обережною}. На сході за горами знаходиться Сквернолісся. І якщо цей кристал пов'язаний з цим місцем, він може виявитися дуже небезпечним.", [3] = "Наповніть порожню посудину водою з місячного колодязя в Аубердіні, після чого дослідіть червоний кристал в горах на сході Темнобережжя.", [4] = "Кристал виглядає дуже незвично на фоні лісистих пейзажів Темнобережжя. Здається, з його глибин долинає легке дзижчання.", [5] = "Ви знову стоїте перед таємничим кристалом. Відкривши посудину з водою місячного колодязя, ви обережно виливаєте її вміст на верхню частину кристала. Вода стікає по його стінках, і ви бачите, як його поверхня стає прозорою...", ["en"] = "As Water Cascades", ["tasks"] = { ["Moonwell Water Tube"] = "посудина з водою місячного колодязя", ["Moonwell Water Tube (Provided)"] = "посудина з водою місячного колодязя (видано)" } },
    [4813] = { [1] = "Фрагменти в кристалі", [2] = "Вода з місячного колодязя допомогла виявити, що всередині кристалу знаходиться кілька невеликих фрагментів кісток, а також половина щелепи. Щелепна кістка, схоже, належала гуманоїду, але це неможливо з'ясувати, не розбивши кристал — що може виявитись неможливим навіть для наймогутнішої магії.\n\nЗавдання виконано, тож вам залишається лише відзвітувати стражниці Ґлінді Нал'Шеї в Аубердін.", [3] = "Розкажіть про вашу знахідку Ґлінді Нал'Шеї в Аубердіні.", [5] = "Що ж, схоже, що хоч ми й дізнались про кристал більше, але врешті-решт отримали більше запитань, ніж відповідей!\n\nЯ передам здобуту тобою інформацію до ради Аубердіну. Можливо, вони знатимуть, як діяти з цим кристалом далі. Якщо вони, звісно, вирішать, що з ним варто щось робити — поки що він залишається надто далеко на сході, щоб загрожувати нам.\n\nЩо ж до тебе, будь ласка, прийми це як винагороду за добре виконану роботу, {ім'я}.", ["en"] = "The Fragments Within" },
    [4842] = { [1] = "Дивні джерела", [2] = "Правду кажучи, хоча в Зимоключі й немає вулканів, я думаю, для виникнення цих гарячих джерел є не менш небезпечні причини...\n\nДобре, я думаю, тобі варто побачити це на власні очі. Тобі потрібно пройти через весь Зимоключ і податися на південь. Коли повітря стане густим і гарячим, а небо потемніє, ти знайдеш те, що, на мою думку, і є джерелом тепла.\n\nПоглянь {стать:сам:сама}. Я впевнена, що у тебе виникне багато питань.", [3] = "Дотримуйтесь вказівок Донови Снігосхов, а потім поверніться до неї.", [4] = "Вода в джерелах має дуже дивні властивості... Я досі не розумію, що все це означає...", [5] = "Так, демони в ущелині Темного шепоту. Я вважаю, що саме їхня присутність так впливає на землю. Я збираюся продовжувати спостереження за тутешніми гарячими джерелами та побачити, чи не дізнаюся я ще щось.\n\nЯ почекаю, поки ти наберешся сил, а потім знову попрошу тебе про допомогу з дослідженням ущелини Темного шепоту.", ["en"] = "Strange Sources", ["tasks"] = { ["Discover Darkwhisper Gorge"] = "Відкрийте для себе ущелину Темний Шепіт", ["Explore Zone"] = "Дослідіть місцевість" } },
    [485] = { [1] = "Знайти OOX-09/ВЗ!", [2] = "Ви виявили дивний яйцеподібний металевий пристрій. Покрутивши одну з його ручок, ви пробуджуєте яйце, і воно відкриває якийсь пристрій гномів! Зсередини лунає голос.\n\n\"Мене звати Оґлторп, і мій автономний робот розбився! Я винагороджу тебе, якщо знайдеш його! Будь ласка, віднеси цей маяк до робота.\n\nЯ вже вирахував координати для тебе! Він розбився на верхів'ї річки біля Замаскованої печери!\"", [3] = "Принесіть аварійний маяк до автономного робота Оґлторпа у Внутрішні землі до верхів'я річки біля Замаскованої печери.", [4] = "Здається, ви знайшли уламки... механічної курки? З яйця знову лунає голос:\n\n\"Так, чудова робота! Це дійсно мій автономний робот, але мої дані показують, що йому потрібен заряд енергії, щоб він зміг повернутись до Грабіжної Бухти на ремонт. Для початку помісти маяк всередину апарата. А решту він зробить сам!\"", [5] = "Ви помістили яйце... аварійний маяк... в середину курки... автономного робота.\n\nЗсередини робота лунає гудіння та дзижчання — він намагається встати. Коли робот оживає, зсередини долинає голос Оґлторпа:\n\n\"Принаймні, OOX-09/ВЗ працює, але йому потрібен капітальний ремонт! Він надто важкий для того, щоб ти {стать:зміг:змогла} нести його... але у мене є ідея. Хочеш трохи доглянути за ним?\"", ["en"] = "Find OOX-09/HL!", ["tasks"] = { ["OOX-09/HL Distress Beacon"] = "аварійний маяк OOX-09/ВЗ", ["OOX-09/HL Distress Beacon (Provided)"] = "аварійний маяк OOX-09/ВЗ (видано)" } },
    [4862] = { [1] = "БРИ-ДО-ТА", [2] = "Віриш чи ні, але є дехто, хто готовий платити за найогидніших тварин, яких вони потім приручають!\n\nЯ відправив Блискітку на Шпиль, щоб зібрати яйця скельного павука, але від неї вже кілька тижнів немає жодної звістки. Може, ти зможеш мені допомогти?\n\nСлухай уважно, {ім'я}. Йди до Чорноскельного шпиля й збери для мене яйця шпильного павука. Принеси їх сюди і я не тільки заплачу тобі, але й навіть приручу одного з них для тебе!", [3] = "Відправляйтеся на Чорноскельний шпиль і зберіть для Кіблера 15 яєць шпильного павука.\n\nСудячи з усього, яйця потрібно шукати біля павуків.", [4] = "Це павучі яйця у твоїй сумці чи ти просто {стать:радий:рада} мене бачити?", [5] = "Так багато! Тільки поглянь на всі ці яйця! Вони принесуть чимало золота.\n\nЯк і обіцяв, ось тобі маленька тваринка. Дивись, щоб не вкусила!", ["en"] = "En-Ay-Es-Tee-Why", ["tasks"] = { ["Spire Spider Egg"] = "яйце шпильного павука", ["Spire Spider Egg (Provided)"] = "яйце шпильного павука (видано)" } },
    [4863] = { [1] = "Розлючені дикі совухи", [2] = "Ви озираєтесь, але бачите нічого такого, щоб могло знадобитися Жерону. Однак, схоже що знайдений вами ящик був відкритий силою, ніби тут побував дикий совух...\n\nДивлячись на схід, ви ледве можете розгледіти покинутий віз. Можливо, ви знайдете там речі Жарона. Варто поглянути.", [3] = "Знайдіть розбитий фургон Жарона Каменотеса.", [5] = "Підійшовши до фургона, ви думаєте, що навряд чи всередині залишилося щось корисне для Жерона. Однак, придивившись, ви помічаєте в снігу біля фургона кілька ящиків, які виглядають неушкодженими.", ["en"] = "Enraged Wildkin" },
    [4864] = { [1] = "Розлючені дикі совухи", [2] = "Вивчивши вміст ящика, ви вирішуєте, що Жарону можуть стати в пригоді інструменти, що там лежать. Однак серед них немає й сліду амулета.\n\nСхоже, дикі совухи мешкають на північ і на схід звідси, і ви вирішуєте, що ваш наступний крок — зустріти цих істот віч-на-віч і забрати у них амулет.", [3] = "Дістаньте зі снігу припаси Жарона, а потім знайдіть дикого совуха, що вкрав амулет, про який говорив Жарон.\n\nВіднесіть припаси Жарона та амулет з синього пір'я в його оселю у Зимоключі.", [4] = "Еге... Розказуй, що там.", [5] = "Ну, я не очікував почути більше, {стать:хлопче:дівча}. Я думав, що дикі совухи знищили всі мої речі...\n\nАле ти {стать:знайшов:знайшла} мої інструменти, а головне — амулет! Цікаво, чому той совух так запекло захищав цю річ... Ну, хай там як, а я двічі подумаю, перш ніж знову вирушу в їхній бік!", ["en"] = "Enraged Wildkin", ["tasks"] = { ["Blue-feathered Amulet"] = "амулет з синього пір'я", ["Blue-feathered Amulet (Provided)"] = "амулет з синього пір'я (видано)", ["Jaron's Supplies"] = "припаси Жарона", ["Jaron's Supplies (Provided)"] = "припаси Жарона (видано)" } },
    [4866] = { [1] = "Материнське молоко", [2] = "{Раса:к}, це, мабуть, одна з найсильніших отрут у світі!\n\nПід час прогулянок до Шпиля, я підслухав, як орки говорили про її смертоносність. Вони називають отруту \"материнським молоком\", на честь матінки Жевріючої Павутини, великої бридкої павучихи з павучих печер.\n\nОсь що мені від тебе потрібно: Живий зразок цього \"молока\" у твоїх власних венах. Просто принести мені залозу з отрутою буде недостатньо! Змусь матінку отруїти тебе і повертайся до мене!\n\nТоді... я видою тебе!\n\n<Потирає руки в очікуванні.>", [3] = "У самому серці Чорноскельного шпиля ви знайдете матір Жевріючу Павутину. Викличте її та змусьте отруїти вас. Після цього, скоріше за все, вам доведеться вбити її. Коли отрута буде всередині вас, поверніться до Джона Лахмітника, щоб він \"подоїв\" вас.", [4] = "<Джон Лахмітник щипає вас.>", [5] = "З цього вийде найкращий ель!\n\nА ти {стать:думав:думала}, що я з цього зроблю? Отруту?\n\nЩо за діти...", ["en"] = "Mother's Milk", ["tasks"] = { ["Milked"] = "Доїли" } },
    [4867] = { [1] = "Урок Згуборев", [2] = "Аррр! Так важко говорити!\n\nВізьми цю записку! Принеси мені мій талісман!", [3] = "Прочитайте сувій Вароша. Принесіть Варошу його талісман.", [4] = "Ти {стать:приніс:принесла} мій талісман?", [5] = "Так! Я вже відчуваю, як мої сили повертаються до мене. Прокляття Урока більше не мучить мій розум.\n\nДякую тобі, {ім'я}! Я занадто гордий, щоб схиляти голову перед кимось, але мушу визнати, що ти мені дуже {стать:допоміг:допомогла}.\n\nБажаю тобі удачі у твоїх подорожах через Чорноскельний шпиль. Ти {стать:дурний:дурна}, якщо думаєш, що зможеш піднятися на вершину, але ти безсумнівно {стать:хоробрий:хоробра}.", ["en"] = "Urok Doomhowl", ["tasks"] = { ["Warosh's Mojo"] = "талісман Вароша", ["Warosh's Mojo (Provided)"] = "талісман Вароша (видано)" } },
    [4881] = { [1] = "План вбивства", [2] = "Таурен Канаті Сіра Хмара насмілився стати мисливським табором в Тисячі Шипів. Ми маємо вбити його та усунути всіх його прихильників. Зустрінемось на маленькому посту, що південно-західніше від Великого Підйомника.", [3] = "Попередьте Канаті Сіру Хмару на Білосяжній заставі про те, що його планують вбити.", [5] = "Вони збираються вбити мене? Я покажу їм, як б'ються таурени.", ["en"] = "Assassination Plot" },
    [49] = { [1] = "Солодке бурштинове", [2] = "Бурштиновим кольором сяє любов,\nЯк небо палає загравою знов.\nМені принеси ти, щоб диво створити,\nМішок кукурудзи, ячменю та жита.", [3] = "Принесіть Лютобухові Громовару мішок ячменю, мішок жита та мішок кукурудзи.", [4] = "На біс? Неодмінно!\n\nБурштиновим кольором сяє любов,\nЯк небо палає загравою знов.\nМені принеси ти, щоб диво створити,\nМішок кукурудзи, ячменю та жита.", [5] = "Гик! Хо-хо!", ["en"] = "Sweet Amber", ["tasks"] = { ["Sack of Barley"] = "мішок ячменю", ["Sack of Barley (Provided)"] = "мішок ячменю (видано)", ["Sack of Corn"] = "мішок кукурудзи", ["Sack of Corn (Provided)"] = "мішок кукурудзи (видано)", ["Sack of Rye"] = "мішок жита", ["Sack of Rye (Provided)"] = "мішок жита (видано)" } },
    [490] = { [1] = "<UNUSED>", [2] = "За суворим наказом Ради Дарнасу, я призначаю винагороду за Плем'я Гнарлпайн. Вони більше не друзі лісу. Їхня корупція зробила їх бездумною загрозою для нашого народу та істот галявини.\n\nЯк постановила Рада, ви будете винагороджені за усунення загрози фурболгів з Калідару. Принесіть мені їхні ікла як доказ ваших діянь.", [3] = "Шейла Найтбріз за межами Дарнасу хоче, щоб ви принесли їй 20 іклів Гнарлсоїни.", ["en"] = "<UNUSED>", ["tasks"] = { ["Gnarlpine Fang"] = "ікло хутропуза Кривої Сосни" } },
    [4901] = { [1] = "Вартові вівтаря", [2] = "На самій вершині хребта знаходиться те, що я вважаю вівтарем богині Елуни. Наскільки я розумію, нам потрібно запалити п'ять смолоскипів у кожній печері і ми зможемо отримати доступ до вівтаря.\n\nЯ переписала деякі заклинання, висічені на камені в стародавніх руїнах Кел'Теріла, які, на мою думку, є ключем до активації вівтаря. Допоможи мені запалити смолоскипи, поки я читатиму заклинання.\n\nЯкщо у нас все вийде, ти можеш доповісти Ереласу про результати!", [3] = "Захищайте Раншаллу, поки вона намагатиметься активувати вівтар Елуни. Повідомте про свої знахідки Ереласа Бурштинонебесного в селищі Рут'Теран.", [5] = "Ти {стать:зустрівся:зустрілася} з Раншаллою?", ["en"] = "Guardians of the Altar", ["tasks"] = { ["Discover the secret of the Altar of Elune"] = "Розкрийте таємницю Вівтаря Елуни" } },
    [4902] = { [1] = "Дикі совухи Елуни", [2] = "Це неймовірно!\n\nМене завжди цікавила істина… Тобі потрібно обов'язково поділитися цим знанням! Йди якнайшвидше до верховного друїда Фендрала Оленеріга — ти знайдеш його в Дарнасі, у Кенарійському Колі. Розкажи йому, що сталося, так само як {стать:розповів:розповіла} мені. Я впевнений, що йому буде так само цікаво!\n\nЦе важлива інформація, {ім'я}!", [3] = "Поговоріть з верховним друїдом Фендралом Оленерігом в Дарнасі.", [5] = "Не соромся, розкажи мені, для чого ти {стать:прийшов:прийшла}.\n\nОх, так? Хмм. Добре.\n\nДякую, що {стать:прийшов:прийшла} одразу до мене. Завжди краще йти одразу до верхівки... Але... Так. Друїди Кенарійського Кола знали про диких совухів давно. Що вони є улюбленцями Елуни та були обраними охороняти найсвятіші місця.\n\nТак що це не новина, але я вдячний за твої зусилля. Ось, візьми це — думаю, це гарна нагорода за твою роботу.", ["en"] = "Wildkin of Elune" },
    [4903] = { [1] = "Наказ воєводи", [2] = "За наказом воєводи Клинозуба, наступні мешканці Чорноскельного шпиля підлягають знищенню:\n\nОсобливо небезпечний злочинець, верховний повелитель Омокк.\n\nЖорстокий і безжалісний троль, воєначальник Вун.\n\nВластитель Змійталак, орудар меншого міста.\n\nТакож необхідно принести усі документи, знайдені у них.\n\nДосягни успіху та прослався.\n\nЯкщо провалишся — про тебе забудуть.", [3] = "Вбийте верховного повелителя Омока, воєначальника Вуна та властителя Змійталака. Добудьте важливі папери Чорнокаменю. Поверніться до воєводи Клинозуба в Карґат коли виконаєте завдання.", [4] = "<Воєначальник Горезуб віддає честь.>", [5] = "<Тьмяно-зелена шкіра на обличчі воєводи Клинозуба на мить блідіє.>", ["en"] = "Warlord's Command", ["tasks"] = { ["Highlord Omokk"] = "верховний повелитель Омокк", ["Highlord Omokk slain"] = "верховний повелитель Омокк: убито", ["Important Blackrock Documents"] = "важливі папери Чорнокаменю", ["Important Blackrock Documents (Provided)"] = "важливі папери Чорнокаменю (видано)", ["Overlord Wyrmthalak"] = "Повелитель Змій", ["Overlord Wyrmthalak (Provided)"] = "Повелитель Змій (видано)", ["Overlord Wyrmthalak slain"] = "Повелитель Змій: убито", ["War Master Voone"] = "воєначальник Вун", ["War Master Voone slain"] = "воєначальник Вун: убито" } },
    [4905] = { [1] = "<UNUSED>", [2] = "Захистіть Канаті Сіру Хмару від Кентавр-ассасинів.", ["en"] = "<UNUSED>" },
    [4907] = { [1] = "Тінкі Пароварченко", [2] = "Привіт, {ім'я}. Пам'ятаєш Тінкі Пароварченко? Бо вона тебе пам'ятає! Вона надіслала мені листа, щоб я відшукав тебе, бо... їй знову потрібна твоя допомога. Гадаю, це якось пов'язано з її дослідженням драконів.\n\nІди у Палаючий степ, на Жевріючу Вершину, та поговори з нею.", [3] = "Поговоріть з Тінкі Пароварченко.", [5] = "Фелнок сказав правду! Мені знову потрібна твоя допомога і цього разу буде дуже небезпечно.\n\nТи {стать:готовий:готова}?", ["en"] = "Tinkee Steamboil" },
    [4961] = { [1] = "Очищення сфери Орагіла", [2] = "А, сфера закликача — ось звідки йде це зло. Ми маємо вигнати з неї демона, якщо ти збираєшся її використовувати. Це я легко зможу зробити.\n\nВажчу роботу виконаєш ти. Тобі доведеться вбити демона, коли він вийде зі сфери.\n\nІ ти маєш діяти швидко. Якщо забаришся, він стрибне назад у сферу, і нам доведеться починати спочатку!\n\nТож приготуйся, {ім'я}. Приготуй свої найсильніші заклинання і тримай зілля під рукою, а також знайди союзників, якщо зможеш. Бо це буде не дуже приємно.", [3] = "Вбийте демона сфери та поговоріть з Табетою.", [4] = "Тобі доведеться вбити цього демона, щоб назавжди позбавити сферу його впливу, {ім'я}.", [5] = "Неперевершено, {ім'я}! Ти {стать:дав:дала} тому демону урок, який він не скоро забуде. Ти {стать:проявив:проявила} велику силу та майстерність. Тепер, гадаю, настав час повернутися до Менари з очищеною сферою, щоб використати її на користь.\n\nУспіхів тобі, {клас:к}. Можливо, наші шляхи ще перетнуться.", ["en"] = "Cleansing of the Orb of Orahil", ["tasks"] = { ["Demon of the Orb"] = "демон сфери", ["Demon of the Orb slain"] = "демон сфери: убито" } },
    [4962] = { [1] = "Уламок душі сквернопса", [2] = "Отже, ти хочеш захопити душу сквернопса, добре.\n\nВізьми цей рубін — з його допомогою ти зможеш захопити душу істоти. Він працює як заклинання, які ти вже знаєш: коли істота близька до смерті — скористайся каменем, і він зробить все за тебе.\n\nЯ б порадила спробувати свої сили на будь-якому зі сквернопсів у Спустошищі. Вони мають підійти.\n\nПісля того, як все зробиш, принеси захоплену душу та рубін до Менари.", [3] = "Візьміть рубін сквернолова і використайте його на одному зі сквернопсів, що знаходяться у Спустошищі. Після успішного захоплення духу принесіть рубін сквернолова та ув'язнений дух сквернопса до Менари Пустоплестої в Степи.", [4] = "Так, {ім'я}? Ти {стать:обрав:обрала}? Пекельника чи сквернопса?\n\nКожен вибір є особистим і повинен відображати твої сильні та слабкі сторони. Це звично для {клас:р} покращувати свої сильні сторони замість того, щоб вдосконалювати ті, в яких ти {стать:слабкий:слабка}. Іноді перемогти ворога — це така ж сильна тактика, як і стати більш збалансованим заклинателем.", [5] = "А, дух сквернопса. Молодець, {ім'я}.\n\nКоли в мене будуть і дух, і очищена сфера, я зможу об'єднати їх для тебе. Але не раніше.", ["en"] = "Shard of a Felhound", ["tasks"] = { ["Felhas Ruby"] = "рубін сквернолова", ["Felhas Ruby (Provided)"] = "рубін сквернолова (видано)", ["Imprisoned Felhound Spirit"] = "ув'язнений дух сквернопса", ["Imprisoned Felhound Spirit (Provided)"] = "ув'язнений дух сквернопса (видано)" } },
    [4963] = { [1] = "Уламок душі пекельника", [2] = "Отже, ти хочеш захопити душу пекельника, добре.\n\nВізьми цей смарагд — з його допомогою ти зможеш захопити душу істоти. Він працює як заклинання, які ти вже знаєш: коли істота близька до смерті — скористайся каменем, і він зробить все за тебе.\n\nЯ б порадила спробувати свої сили на будь-якому із пекельників у Спустошищі. Вони мають підійти.\n\nПісля того, як все зробиш, принеси захоплену душу та смарагд до Менари.", [3] = "Візьміть пекельний смарагд і використайте його на одному із пекельників, які знаходяться у Спустошищі. Після успішного захоплення духу принесіть пекельний смарагд та ув'язнений дух пекельника до Менари Пустоплестої в Степи.", [4] = "Так, {ім'я}? Ти {стать:обрав:обрала}? Пекельника чи сквернопса?\n\nКожен вибір є особистим і повинен відображати твої сильні та слабкі сторони. Це звично для {клас:р} покращувати свої сильні сторони замість того, щоб вдосконалювати ті, в яких ти {стать:слабкий:слабка}. Іноді перемогти ворога — це така ж сильна тактика, як і стати більш збалансованим заклинателем.", [5] = "А, дух пекельника. Молодець, {ім'я}.\n\nКоли в мене будуть і дух, і очищена сфера, я зможу об'єднати їх для тебе. Але не раніше.", ["en"] = "Shard of an Infernal", ["tasks"] = { ["Imprisoned Infernal Spirit"] = "ув'язнений дух пекельника", ["Imprisoned Infernal Spirit (Provided)"] = "ув'язнений дух пекельника (видано)", ["Infus Emerald"] = "пекельний смарагд", ["Infus Emerald (Provided)"] = "пекельний смарагд (видано)" } },
    [4964] = { [1] = "Завершена сфера Дар'Орагіла", [2] = "Я негайно почну створення твоєї сфери. Треба вселити в неї нового демона. Коли все буде готово, ти зможеш вибрати форму зброї: посох чи сферу. Я завжди вважала, що важливо приділяти увагу зброї, яку обирає {клас}... І я не бачу причини не продовжувати цю практику.", [3] = "Зачекайте, поки Менара Пустоплеста закінчить сферу Дар'Орахіла, а потім знову поговоріть з нею.", [5] = "Все готово, {ім'я}. Просто скажи мені, що ти {стать:обрав:обрала}: посох, який вимагатиме використання обох рук, або сферу, щоб ти {стать:зміг:змогла} використовувати кинджал або меч як зброю.\n\nПриручення сквернопса було великим подвигом з твого боку. Я впевнена, що цей предмет гарно послужить тобі у майбутньому. Продовжуй наполегливо вдосконалювати себе, {ім'я}. Я буду очікувати звісток про твої подвиги.", ["en"] = "The Completed Orb of Dar'Orahil", ["tasks"] = { ["Wait for Menara Voidrender to complete your item"] = "Зачекайте, поки Менара Розбійниця Порожнечі завершить ваш предмет." } },
    [4965] = { [1] = "Знання сфери Орагіла", [2] = "Ну, ну, ну... приємно бачити, що твоя сила росте, {ім'я}. Гадаю, ти вже {стать:готовий:готова} поговорити з Менарою Пустоплестою у Степах. Якщо ти ще не {стать:розмовляв:розмовляла} з нею, то дозволь сказати, що я ніколи не зустрічав іншого експерта в створенні речей — зокрема сфер, які можуть легко ув'язнити навіть демона, щоб служити нашій волі.\n\nЯкщо тобі цікаво — вона знаходиться в вежі Страгада над Брашпилем в Степах.", [3] = "Поговоріть з Менарою Пустоплестою в Степах.", [5] = "А, ти дійсно шукаєш щось більш... суттєве. Я можу допомогти тобі, якщо ти дійсно {стать:готовий:готова}.\n\nПриємно бачити, що хтось із нас прагне більшої влади в інших формах, а не лише в знаннях.\n\nОтже, думаєш, ти {стать:готовий:готова}, {ім'я}?", ["en"] = "Knowledge of the Orb of Orahil" },
    [4967] = { [1] = "Знання сфери Орагіла", [2] = "Ти все ще {стать:дурень:дурепа}, і все ще шукаєш прикраси смертних. Так, я говорю з тобою з гонором. Я бачу тебе перед собою і мені смішно. Ти {стать:жалюгідний:жалюгідна}!\n\nАле не має значення, що я думаю. Важливо лише те, що думають ті, хто хоче мати з тобою справу! І в цьому випадку, всупереч моїм переконанням, ті, хто має певну частку влади, вважають, що ти заслуговуєш на більше.\n\nЯкщо це те, чого ти прагнеш, тобі слід поговорити з Менарою Пустоплестою у вежі над Брашпилем. Гадаю, ти з нею вже {стать:зустрічався:зустрічалася}.", [3] = "Поговоріть з Менарою Пустоплестою в Степах.", [5] = "А, ти дійсно шукаєш щось більш... суттєве. Я можу допомогти тобі, якщо ти дійсно {стать:готовий:готова}.\n\nПриємно бачити, що хтось із нас прагне більшої влади в інших формах, а не лише в знаннях.\n\nОтже, думаєш, ти {стать:готовий:готова}, {ім'я}?", ["en"] = "Knowledge of the Orb of Orahil" },
    [4968] = { [1] = "Знання сфери Орагіла", [2] = "Їмм, ти далеко {стать:зайшов:зайшла}... це дійсно дивовижно. Я думала, що ти вже давно {стать:збожеволів:збожеволіла} від скверни, що просочилася у твою душу. Можливо, ми спробуємо підштовхнути тебе далі?\n\nЯкщо ти хочеш випробувати свої навички — звернись до Менари Пустоплестої, яка знаходиться у вежі Страгада над Брашпилем. Вона тебе направить.", [3] = "Поговоріть з Менарою Пустоплестою в Степах.", [5] = "А, ти дійсно шукаєш щось більш... суттєве. Я можу допомогти тобі, якщо ти дійсно {стать:готовий:готова}.\n\nПриємно бачити, що хтось із нас прагне більшої влади в інших формах, а не лише в знаннях.\n\nОтже, думаєш, ти {стать:готовий:готова}, {ім'я}?", ["en"] = "Knowledge of the Orb of Orahil" },
    [4969] = { [1] = "Знання сфери Орагіла", [2] = "Ха-ха! Ти добре справляєшся, {стать:юний:юна} {клас:к}.\n\nПрийде час, і пекельники та повелителі жаху вклонятимуться перед тобою!\n\nАле поки цей час не настав, тобі все ще доведеться користуватися зброєю, виготовленою руками смертних.\n\nЗдається, ти {стать:готовий:готова} до створення ще одної такої зброї, і якщо ти {стать:згоден:згодна} — Менара Пустоплеста захоче з тобою поговорити! Вона знаходиться біля вежі Страгада, над портовим містечком Брашпиль. Йди туди, коли будеш {стать:готовий:готова}.", [3] = "Поговоріть з Менарою Пустоплестою в Степах.", [5] = "А, ти дійсно шукаєш щось більш... суттєве. Я можу допомогти тобі, якщо ти дійсно {стать:готовий:готова}.\n\nПриємно бачити, що хтось із нас прагне більшої влади в інших формах, а не лише в знаннях.\n\nОтже, думаєш, ти {стать:готовий:готова}, {ім'я}?", ["en"] = "Knowledge of the Orb of Orahil" },
    [497] = { [1] = "<UNUSED>", [2] = "У дитинстві, вихований як гладіатор у фортеці Дернгольд, я потоваришував з Таретою, дочкою моєї годувальниці та коханки клятого покидька Блекмура.\n\nМинуле є минулим, {ім'я}, але повідомлення про пересування людей у Гіллсбраді нагадали мені про той час. Я відправив невелику групу в цей район, щоб розслідувати це та забрати... предмет... подарований мені Таретою, якщо вони зможуть.\n\nБезсумнівно, марне завдання, але, можливо...\n\nВони вже мали б повернутися, я хочу, щоб ти пішов до Таррен Млин для розслідування.", ["en"] = "<UNUSED>" },
    [4971] = { [1] = "Питання часу", [2] = "Хтось втрутився в плин часу в Андоралі, дуже схоже на Скару. Я можу спробувати виправити шкоду, але ти маєш зробити так, щоб мені не заважали.\n\nЧасові паразити — це падло, яке харчується нитками зміненого потоку часу, і тепер вони заразили силоси Андоралу. Цих паразитів можна виявити тільки за синім сяйвом. Вони дуже заважають мені. Будь ласка, {ім'я}, допоможи мені, скористайся цим часовим переміщувачем, щоб позбавитись від цих паразитів.", [3] = "Скористайтеся часовим переміщувачем поруч з одним з елеваторів Андорала та знайдіть часових паразитів.\n\nВбийте 15 часових паразитів та поверніть часовий переміщувач Хромі в таверну Андорала.", [4] = "Часові паразити завжди з'являються коли хтось втручається у плин часу. Я відчуваю, що їх багато, і вони дуже заважають мені.\n\nЯкщо ти знищиш хоча б частину, мені буде набагато простіше виправити цю ситуацію. Я відчую, коли ти впораєшся з цим завданням.", [5] = "Мені стало набагато легше виправляти плин часу. Дякую, {ім'я}. Хоча ти певно не повністю розумієш наслідки порушення лінії часу, я ціную те, що ти розумієш всю важливість протидії Скарі. І я все більше переконуюся, що це їхні злочини.\n\nЯ не бачу нічого поганого в тому, щоб нагородити тебе за твою підтримку, {стать:смертний:смертна}. Твої найбільші подвиги іще попереду, і ця невеличка дрібничка не змінить твоєї майбутньої долі. Хоча моєму крилу драконів не завадить твоя подальша допомога...", ["en"] = "A Matter of Time", ["tasks"] = { ["Temporal Displacer"] = "часовий переміщувач", ["Temporal Displacer (Provided)"] = "часовий переміщувач (видано)", ["Temporal Parasite"] = "часовий паразит", ["Temporal Parasite slain"] = "часовий паразит: убито" } },
    [4972] = { [1] = "Відлік часу", [2] = "Мені потрібно відправити тебе у світ за межами цієї кімнати, {ім'я}. Дозволь мені пояснити.\n\nТи бачиш, як ця кімната відрізняється від решти Андорала? Дракони мого роду працюють в різних плинах реальності та часу. Щоб виправити шкоду, завдану Андоралу, я дію з іншої часової лінії, щоб не залишати зайвих слідів. Щоб продовжити роботу, мені потрібні часові пристрої, що залишилися з часів приходу чуми. Знайди їх в скринях серед руїн колись величного міста.", [3] = "Знайдіть 5 годинників Андорала в скринях серед руїн міста. Поверніться з ними до Хромі в таверну Андорала.", [4] = "Часові пристрої, які я шукаю, дуже прості. Зазвичай це прості годинники, чиї стрілки зупинилися назавжди з тої пори, як чума вперше вразила Андорал.\n\nЧас ніколи не закінчується, а годинники, які ти мені принесеш, будуть незмінними... поки хаос пануватиме тут.", [5] = "Це те, що мені потрібно, {ім'я}. Дякую.\n\nДозволь мені винагородити тебе. Можливо, ти не розумієш для чого тобі потрібен такий пристрій. На жаль, я не можу розповісти тобі, коли ти скористаєшся цим предметом. Просто знай, що в майбутньому цей пристрій дуже знадобиться тобі. А чи ти збережеш його до того часу... це, {стать:друже мій:подруго моя}, вирішувати тобі.", ["en"] = "Counting Out Time", ["tasks"] = { ["Andorhal Watch"] = "годинник Андорала", ["Andorhal Watch (Provided)"] = "годинник Андорала (видано)" } },
    [4973] = { [1] = "Відлік часу", [2] = "Якщо ти {стать:готовий:готова} знову допомогти мені, я не відмовлюся. Я з радістю прийму ще більше годинників з руїн Андорала. Вони допомагають мені в боротьбі проти зловісної сили, яка намагається змінити плин часу.\n\nВ обмін на ці годинники я дам тобі річ, яка, як мені здається, може знадобитись тобі в майбутньому.", [3] = "Знайдіть 5 годинників Андорала серед руїн міста та поверніться з ними до Хромі в таверну Андорала.", [4] = "Годинники Андорала, як і той здоровий годинник на руїнах ратуші, завмерли на третій годині. Саме тоді, коли чума вперше вразила місто, забираючи з нього життя.\n\nЯк би ми не шкодували про події того дня, це вже сформувало цей плин часу, яким ви, смертні, його сприймаєте. Бронзові дракони повинні захищати цю лінію часу!", [5] = "І знову я дякую тобі за допомогу. Будь ласка, прийми цей подарунок. Хоча ти може й не розумієш, як користуватися ним, але, можливо, у майбутньому, ти дізнаєшся справжню цінність цього предмета. Можна сказати, що я передбачаю це, {ім'я}.", ["en"] = "Counting Out Time", ["tasks"] = { ["Andorhal Watch"] = "годинник Андорала", ["Andorhal Watch (Provided)"] = "годинник Андорала (видано)" } },
    [4974] = { [1] = "За Орду!", [2] = "Ренд наважується робити подібні заяви через те, що його захищають чорні дракони.\n\nТи, {ім'я}, знайдеш спосіб пройти через Зали Вознесіння. Та відшукаєш там \"воєвождя\" Ренда Чорнорука і знищиш його — ЗАРАДИ ОРДИ!\n\n<Тралл грюкає кулаком по своєму трону.>\n\nНаступного разу, коли ти повернешся в мої покої, ти з тріумфом піднімеш вгору його відрубану голову, а потім вручиш її своєму воєвождю. Зроби це і будеш {стать:вшанований:вшанована} як {стать:герой:героїня} Орди.", [3] = "Відправляйтесь в Чорноскельний шпиль і вбийте воєвождя Ренда Чорнорука. Заберіть його голову та поверніться в Орґріммар.", [4] = "<Тралл фиркає.>", [5] = "Ти {стать:завдав:завдала} нищівного удару силам Чорнокаменю, {ім'я}. Із загибеллю їхнього воєвождя, воїнство Чорнокаменю знову опинилося в пащі хаосу.\n\nЗа твій героїзм жителі Калімдору будуть винагороджені!", ["en"] = "For The Horde!", ["tasks"] = { ["Head of Rend Blackhand"] = "голова Ренда Чорнорука", ["Head of Rend Blackhand (Provided)"] = "голова Ренда Чорнорука (видано)" } },
    [4975] = { [1] = "Завершена сфера Ног'Орагіла", [2] = "Я негайно почну створення твоєї сфери. Треба вселити в неї нового демона. Коли все буде готово, ти зможеш вибрати форму зброї: посох чи сферу. Я завжди вважала, що важливо приділяти увагу зброї, яку обирає {клас}... І я не бачу причини не продовжувати цю практику.", [3] = "Зачекайте, поки Менара Пустоплеста закінчить сферу Ног'Орахіла, а потім знову поговоріть з нею.", [5] = "Все готово, {ім'я}. Просто скажи мені, що ти {стать:обрав:обрала}: посох, який вимагатиме використання обох рук, або сферу, щоб ти {стать:зміг:змогла} використовувати кинджал або меч як зброю.\n\nПриручення пекельника було великим подвигом з твого боку. Я буду очікувати звісток про твої подвиги, {ім'я}.", ["en"] = "The Completed Orb of Noh'Orahil", ["tasks"] = { ["Wait for Menara Voidrender to complete your item"] = "Зачекайте, поки Менара Розбійниця Порожнечі завершить ваш предмет." } },
    [4976] = { [1] = "Повернення очищеної сфери", [2] = "Віднеси очищену сферу назад до Менари у Брашпиль, {ім'я}. Передай їй мої вітання та будь {стать:обережним:обережною}. Я дійсно сподіваюся, що ти зможеш протистояти спокусі та скверні, які неодмінно зустрінуться на твоєму шляху.\n\nХай щастить.", [3] = "Принесіть очищену сферу пекельника до Менари Пустоплестої в Степи.", [4] = "Як проходять твої пошуки Табети та сфери, {ім'я}?\n\nТабета надзвичайно корисна, коли мова йде про магію. Я впевнена, що вона з радістю допоможе тобі, якщо ти знайдеш її.", [5] = "Дуже добре, {ім'я}. Вона чудово підійде.\n\nОстаннє, що тобі потрібно зробити — це вирішити, якого демона ти хочеш ув'язнити в очищеній сфері. Виріши, і отримаєш новий чудовий предмет сили.", ["en"] = "Returning the Cleansed Orb", ["tasks"] = { ["Cleansed Infernal Orb"] = "очищена сфера пекельника", ["Cleansed Infernal Orb (Provided)"] = "очищена сфера пекельника (видано)" } },
    [4981] = { [1] = "Агент Блискітка", [2] = "Ніколи не довіряй гоблінам, {ім'я}. Ось до чого це може привести.\n\nЇї звуть Блискітка — вона була однією з наших найкращих агентів. Потім я дізнався, що вона вела подвійне життя, працюючи на якогось чорного торговця екзотичними тваринами, на ім'я Кіблер з Палаючого степу. Гірше того, вона використовувала кошти Орди для фінансування своїх операцій.\n\nЯ хочу, щоб її привели сюди живою.\n\nВостаннє її бачили біля входу в Чорноскельний шпиль. Знайди її та приведи сюди.\n\nІ, {ім'я}, не дай їй заговорити тобі зуби.", [3] = "Відправляйтесь в Чорноскельний шпиль і дізнайтесь, що сталося з Блискіткою.", [5] = "Не хочу тобі брехати, {раса:к}. Мені були потрібні гроші! Кіблер платить дуже добре — набагато краще, ніж коли-небудь платили в К.Е.З.\n\nАле не сумнівайся в моїй відданості! Як ти думаєш, чому я тут, внизу? Щоб дістати цьому божевільному гобліну яйця екзотичних тварин або щось настільки ж безглузде? Ні, тільки хтось справді божевільний прийшов би до Чорноскельного шпиля за тваринами. Не думаю, що у світі багато таких божевільних.\n\n<Блискітка сміється.>\n\nТакі просто не мають плодитися.", ["en"] = "Operative Bijou" },
    [4982] = { [1] = "Речі Блискітки", [2] = "Вночі, коли місто гірше охороняється, я крадуся вулицями, занотовую та записую все, що бачу і те що може мати стратегічну цінність для К.Е.З.\n\nАле вчора вночі все пішло не по плану. Я натрапила на розтяжку і підняла тривогу. Я сховала своє розвідувальне спорядження і побігла в укриття! На жаль, я не можу повернутися туди. Вони посилили патрулювання вдвічі, а то й втричі! Вся інформація втрачена.\n\nЗнайди мої речі і я зможу спокійно повернутися в К.Е.З.", [3] = "Знайдіть речі Блискітки та поверніть їй. Вона говорила, що сховала їх десь в місті, на нижньому поверсі.", [4] = "Ну що, є успіхи?", [5] = "Ти {стать:зробив:зробила} це! Коли Лекслорт отримає ці плани, він забуде про все те, що погрожував зробити зі мною.\n\n{ім'я}, ти {стать:мій герой:моя героїня}!", ["en"] = "Bijou's Belongings", ["tasks"] = { ["Bijou's Belongings"] = "речі Блискітки", ["Bijou's Belongings (Provided)"] = "речі Блискітки (видано)" } },
    [4983] = { [1] = "Розвіддані Блискітки", [2] = "Віднеси цей звіт Лекслорту. Це очистить моє ім'я і, безсумнівно, дасть К.Е.З. стратегічну перевагу в боротьбі з цими орками.\n\nХочеш, щоб я пішла з тобою? У мене занадто багато роботи. Йди, їм потрібні ці звіти якнайшвидше!", [3] = "Віднесіть розвіддані Блискітки до Лекслорта в Карґат.", [4] = "Де гоблінка???", [5] = "Треба віддати їй належне, вона зуміла викрутитися з чергової халепи! Ці звіти надали неоціненну допомогу в наших справах з орками Чорнокаменю.\n\nЗвичайно ж, ти отримаєш винагороду за твою важку працю.", ["en"] = "Bijou's Reconnaissance Report", ["tasks"] = { ["Bijou's Reconnaissance Report"] = "розвіддані Блискітки", ["Bijou's Reconnaissance Report (Provided)"] = "розвіддані Блискітки (видано)" } },
    [4984] = { [1] = "Природа також страждає", [2] = "Хоча самотужки я не впораюся зі Скарою, я все одно прибув до цих земель, щоб спробувати вилікувати понівечену природу. Тварини страждають від Скари, яка продовжує душити ці землі, не шкодуючи нікого. Я прошу тебе продовжити те, чого я не зміг завершити.\n\nНе існує жодних ліків для вражених чумою тварин, тож залишається припинити їхні страждання. Знайди хворих вовків неподалік та вбий їх. Будь ласка, {ім'я}, закінчи їх муки — якщо зробиш це, мені теж стане легше.", [3] = "Вбийте 8 хворих вовків та поверніться до Мулґріса Глибокої Річки в Кручений Привид, що в Західних Зачумлених землях.", [4] = "Вовки, уражених чумою, необхідно вбити, {ім'я}. Хвороба, яку вони переносять, невиліковна. Я намагався... намагався, поки сам не став її жертвою.", [5] = "Я... я відчуваю, що душі вовків, яких ти {стать:вбив:вбила}, нарешті знайшли свій спокій. Вовки та я вдячні тобі за милосердя.\n\nАле не тільки вовки страждають в цьому проклятому місці, {ім'я}. Мені знову знадобиться твоя допомога.", ["en"] = "The Wildlife Suffers Too", ["tasks"] = { ["Diseased Wolf"] = "хворий вовк", ["Diseased Wolf slain"] = "хворий вовк: убито" } },
    [4985] = { [1] = "Природа також страждає", [2] = "На схід звідси, біля Східних Зачумлених земель, колись блукали великі та могутні гризлі. Чума, вивільнена Скарою, також вразила цих звірів. Вони вештаються в агонії, їхні м'язи заклякли, а їхні тіла гниють.\n\nЯ прошу тебе покласти край і їхнім стражданням. Єдині ліки проти чуми — це швидка смерть, яку ти можеш подарувати їм.", [3] = "Вбийте 8 хворих гризлі та поверніться до Мулґріса Глибокої Річки в Кручений Привид, що в Західних Зачумлених землях.", [4] = "Я чую твої кроки, {ім'я}. Мій зір залишив мене, але я все ще може відчувати речі навколо мене. Ти {стать:поклав:поклала} край стражданням хворих гризлі?", [5] = "\"Я знаю, що ти вже {стать:розібрався:розібралася} з гризлі, їхні муки нарешті закінчилися. У... у мене є дещо для тебе. Я написав це... на гілці, бо відчував, що мій час добігає кінця.\n\nІ справді... мені скоро прийде кінець. Дякую тобі іще раз, {стать:друже:подруго}... істоти цієї проклятої землі можуть спочивати... а тепер і я.\"\n\nДруїд важко зітхає, після чого лунає передсмертний хрип. Його тіло нерухомо лежить на дерев'яній підлозі.", ["en"] = "The Wildlife Suffers Too", ["tasks"] = { ["Diseased Grizzly"] = "хворий гризлі", ["Diseased Grizzly slain"] = "хворий гризлі: убито" } },
    [50] = { [1] = "Солодке бурштинове", [2] = "Ретельно змішаю я все для прокачки,\nНаша з тобою це буде заначка!\nНа куб перегінний потрібен метал,\nЩоб пісню свою я все ж доспівав.", [3] = "Принесіть Лютобухові Громовару ясносрібло.", [4] = "Для тебе на біс? Залюбки, {стать:друже:подруго}!\n\nРетельно змішаю я все для прокачки,\nНаша з тобою це буде заначка!\nНа куб перегінний потрібен метал,\nЩоб пісню свою я все ж доспівав.", [5] = "Гик! Хо-хо!", ["en"] = "Sweet Amber", ["tasks"] = { ["Truesilver Bar"] = "злиток ясносрібла", ["Truesilver Bar (Provided)"] = "злиток ясносрібла (видано)" } },
    [500] = { [1] = "Винагорода за Скелеламів", [2] = "Скелеламські огри насипали огрський курган високо в Альтерацьких горах — біля зруйнованого міста Альтерак. І мої розвідники доповідають, що вони також захопили й руїни міста.\n\nМи не можемо дозволити їм там облаштуватися. Якщо вони почуватимуться у безпеці, то їхнім наступним кроком буде спуск до передгір'я, тобто буквально до наших дверей!\n\nПрямуй на північ до Альтерацьких гір і вбий якомога більше огрів. Принеси мені брудні паці, які вони носять при собі, і отримаєш хорошу нагороду.", [3] = "Зберіть 9 брудних паць зі скелеламських огрів в Альтерацьких горах. Принесіть їх маршалові Редпату в Південнобережжя.", [4] = "{Ім'я}, досі полюєш на огрів? Ти вже {стать:зібрав:зібрала} паці?", [5] = "Дуже добре, {Ім'я}. Ти, напевно, {стать:вирізав:вирізала} добрячу купу огрів, щоб зібрати всі ці паці.\n\nЦе дозволить нам більше не переживати щодо їхньої загрози. Принаймні, поки що.", ["en"] = "Crushridge Bounty", ["tasks"] = { ["Dirty Knucklebones"] = "брудні паці", ["Dirty Knucklebones (Provided)"] = "брудні паці (видано)" } },
    [5001] = { [1] = "Речі Блискітки", [2] = "Зазвичай я не працюю з такими як ти, {раса:к}, але, здається, цього разу я застрягла між молотом і ковадлом. Моя місія тут надзвичайно важлива для Орди. Але інформація, яку я дізналася, стосується і добробуту Альянсу. Повір, мене не цікавить Альянс, але загроза з боку Чорнокаменю набагато більша за купку орків.\n\nДавай так, ти допоможеш мені відшукати мої речі, а я допоможу тобі з інформацією, яка може бути корисною для твоїх союзників.\n\nДомовились?", [3] = "Знайдіть речі Блискітки та поверніть її. Щасти!", [4] = "Ну що, є успіхи?", [5] = "Щоб тебе! Де вони були?", ["en"] = "Bijou's Belongings", ["tasks"] = { ["Bijou's Belongings"] = "речі Блискітки", ["Bijou's Belongings (Provided)"] = "речі Блискітки (видано)" } },
    [5002] = { [1] = "Повідомлення Максвеллу", [2] = "Я гоблінка слова, {раса:к}. А тепер слухай уважно:\n\nЦі орки використовуються в основному як в'ючні тварини та гарматне м'ясо для Крила чорних драконів!\n\nЇхній справжній ватажок ніхто інший, як Нефаріан, виводок Смертокрила. Я також визначила розташування підлеглих Нефаріана в цій частині цитаделі.\n\nВіднеси цю мапу маршалу Максвеллу в Палаючий степ. На ній позначено місцеперебування цих негідників, так їх буде легше знайти.", [3] = "Відправляйтеся в Палаючий степ та передайте інформацію Блискітки маршалу Максвеллу.", [4] = "А, {ім'я}. Давно не бачилися.", [5] = "Це збігається з більшістю відомої нам інформації. Але тут є і дещо цікаве та досить сумне.\n\nПозначки на цій карті допоможуть нам зменшити загрозу зі сторони Чорноскельної гори.", ["en"] = "Message to Maxwell", ["tasks"] = { ["Bijou's Information"] = "інформація Блискітки", ["Bijou's Information (Provided)"] = "інформація Блискітки (видано)" } },
    [5021] = { [1] = "Краще пізно, ніж ніколи", [2] = "\"Пакунок потрібно доставити... поки я не потрапила у пастку!\"\n\nПлач наляканої жінки лунає по всьому будинку. Примара сховалася в кутку на другому поверсі. Здається, вона не розуміє, що відбувається навколо, та й вас ледь помічає.\n\n\"Ти тут, щоб доставити пакунок? Прошу, зроби це, поки не стало іще гірше! Я збиралася їхати звідси. Там все ще має стояти мій кінь... чи я спізнилася?\"", [3] = "Судячи з марень жінки-примари, вона хоче доставити пакунок. Вона казала, що пакунок залишився там, де стояв її кінь. Де саме стояв кінь, чи куди мав бути доставлений пакунок — примара не уточнила.", [5] = "Пакунок стояв у сараї. Ви, можливо, не помітили б його, але зараз він виділяється серед цих руїн. Можливо, це саме той пакунок, про який говорила Дженіс Сквернокамінь...", ["en"] = "Better Late Than Never" },
    [5022] = { [1] = "Краще пізно, ніж ніколи", [2] = "Ви берете пакунок, стираючи з нього шар пилу та бруду. Ім'я адресата написано нашвидкуруч — Емма Сквернокамінь зі Штормовію. Пакунок мав прибути чотири роки тому.\n\nПопри те, що невідомо, чи Емма Сквернокамінь жива, всім відомо, що у Штормовію є реєстр населення міста. Вам варто поговорити з королівськими представниками перепису Штормовію.", [3] = "Дізнайтеся у королівських представників Штормовію місцеперебування Емми Сквернокамінь. Зазвичай офіцера перепису можна знайти в ратуші.", [4] = "Ласкаво просимо в офіс перепису Штормовію. Якщо вам потрібна інформація щодо нашого населення, я можу допомогти вам.", [5] = "Кажете, цей пакунок для Емми Сквернокамінь? Остання відома адреса проживання — Штормовій, чотири роки тому? Що ж, подивимося...\n\nСудячи з того, що ми знаємо, чотири роки тому в місті проживала Емма Сквернокамінь. Що ж, що я можу сказати — цей перепис був зроблений 5 років тому, і у мене немає звіту про її виїзд з міста. Але це не означає, що вона все іще тут.\n\nХвилинку... можливо, цей пакунок адресований старенькій Еммі...", ["en"] = "Better Late Than Never", ["tasks"] = { ["Janice's Parcel"] = "пакунок Дженіс", ["Janice's Parcel (Provided)"] = "пакунок Дженіс (видано)" } },
    [504] = { [1] = "Скелеламські войовники", [2] = "Тепер, коли ти {стать:познайомився:познайомилася} зі скелеламськими ограми, я хочу, щоб ти {стать:завдав:завдала} їм справжнього удару...\n\nПрямуй до руїн Альтерака та розшукай скелеламських войовників. Я хочу, щоб ти добряче їх {стать:повирізав:повирізала} — лише так ці рубаки навчаться триматися на відстані від території Альянсу.", [3] = "Убийте 15 скелеламських войовників, після чого повертайтеся до маршала Редпата в Південнобережжя.", [4] = "Тобі потрібно вбити більше войовників, {Ім'я}. Ти {стать:повинен:повинна} бути зараз у горах і виконувати своє завдання, а не байдикувати тут.", [5] = "Дуже добре. Ось твоя нагорода.\n\nДо речі, як виглядало місто Альтерак, коли ти там {стать:полював:полювала} на войовників? Гадаю, воно не в найкращому стані. Огри не надто люблять чистоту.\n\nНа щастя, твої зусилля допоможуть утримувати їх від Південнобережжя.", ["en"] = "Crushridge Warmongers", ["tasks"] = { ["Crushridge Warmonger"] = "скелеламський войовник", ["Crushridge Warmonger slain"] = "скелеламський войовник: убито" } },
    [5042] = { [1] = "Сила Аґамаґґана", [4] = "Мені знадобиться 4 кривавих скалки, якщо ти бажаєш отримати силу Аґамаґґана, {раса:к}.\n\nПісля мого благословення всі вороги жахатимуться твоєї могутності.\n\nТакою силою наділені найкращі воїни Бритвогривих!", [5] = "Якби тільки Кривозуб був вільний, щоб побачити, як ти {стать:винищував:винищував} тих, хто зрадив його! <фиркає>\n\nЯ вдячний тобі за те, що ти {стать:знищив:знищила} ще більше Щетиношкурих, збираючи ці скалки. Будь ласка, продовжуй в тому ж дусі, а я тобі допомагатиму. <фиркає>", ["en"] = "Agamaggan's Strength", ["tasks"] = { ["Blood Shard"] = "кривавий скалок", ["Blood Shard (Provided)"] = "кривавий скалок (видано)" } },
    [5043] = { [1] = "Спритність Аґамаґґана", [4] = "Кажуть, найкращі розвідники мого племені не мають рівних у своїй майстерності, і жоден пройдисвіт <фиркає> не зміг зрівнятися з їхньою прудкістю у бою.\n\nПринеси мені 4 кривавих скалки, і я зроблю тебе {стать:спритнішим:спритнішою} за будь-якого свинобраза.", [5] = "Нехай твоя рука буде стійкою, а зброя - влучною, {раса:к}.\n\nДух Аґамаґґана віднині з тобою. Повертайся до мене, як захочеш. Кривозуб благословить тебе знову, якщо на те буде воля величного бога-кабана.", ["en"] = "Agamaggan's Agility", ["tasks"] = { ["Blood Shard"] = "кривавий скалок", ["Blood Shard (Provided)"] = "кривавий скалок (видано)" } },
    [5047] = { [1] = "Піп Хуткокміт, до ваших послуг!", [2] = "Ти знайдеш Маліфія Темномолота в Завшегляді, {клас:к}. Скажи йому, що з Піпом все гаразд і що костюм працює ідеально.\n\nПотім передай йому це:\n\n<Піп передає шматок плоті, яка світиться.>\n\nЯ вирвав його з нутрощів звіра під час моєї \"відпустки\".\n\nБ'юся об заклад, Маліфій відразу би придумав, що зробити з частинами такого монстра!\n\nО, ти, напевно, не знаєш, де знаходиться Завшегляд, чи не так? Іди до Зимоключа, {стать:хлопче:дівчино}!", [3] = "Поговоріть з Маліфієм Темномолотом у Завшегляді.", [4] = "Так?", [5] = "Живий? Костюм спрацював? І що це тут у нас?", ["en"] = "Pip Quickwit, At Your Service!", ["tasks"] = { ["Glowing Hunk of the Beast's Flesh"] = "сяючий шматок плоті Звіра", ["Glowing Hunk of the Beast's Flesh (Provided)"] = "сяючий шматок плоті Звіра (видано)" } },
    [5048] = { [1] = "Добродушна Емма", [2] = "Це трохи груба старенька леді та, певно, вона трохи не в собі... але записи вказують на те, що старенька Емма справді підходить опис Емми Сквернокамінь.\n\nМожливо, тобі траплялась старенька Емма — вона блукає містом і бурчить собі під ніс всіляку нісенітницю. Проте вона нікому не заважає, тож люди не турбують її.\n\nВраховуючи все це, я б сказав, що старенька Емма дійсно є тією самою Еммою Сквернокамінь. Можеш запитати в неї, чи справді її прізвище Сквернокамінь.", [3] = "Знайдіть стареньку Емму в Штормовії та перевірте, чи справді вона Емма Сквернокамінь. Якщо так, то, можливо, їй хотілося б отримати пакунок від Дженіс Сквернокамінь.", [4] = "Я б сказала тобі забиратися з моєї галявини, але, як бачиш, у мене її немає.", [5] = "Мене справді звати Емма Сквернокамінь — ти {стать:перший:перша} за багато років, хто називає мене так. Хто... хто ти?\n\nТо ти кажеш, що {стать:знав:знала}... мою сестру?! Вона ще жива? Кого я дурю, звісно, що ні. Коли в Лордероні спалахнула чума, я очікувала найгіршого. Так багато членів моєї родини загинули... або ще гірше. І ось я тут, божевільна стара Емма, зовсім одна. Ти що, {стать:грабіжник:грабіжниця} могил чи що? Шукаєш свою наступну ціль?\n\nЩо... у тебе є пакунок від моєї сестри?", ["en"] = "Good Natured Emma", ["tasks"] = { ["Janice's Parcel"] = "пакунок Дженіс", ["Janice's Parcel (Provided)"] = "пакунок Дженіс (видано)" } },
    [5049] = { [1] = "Блюз Єремії", [2] = "Судячи з доказів, які я знайшов, особа, яку ти розшукуєш, і адресат посилки — Єремія Пейсон, торговець тарганами Підмістя.\n\nЯ завжди вважав, що потрібно мати особливий дар, щоб продавати... тарганів. Безсумнівно, ти зараз — в епічній подорожі, {стать:могутній:могутня} {клас:к}. Я залишу тебе для твоїх починань світового значення. Проте дозволь мені бути частиною твого magnum opus і сказати, що він знаходиться біля банку, повзаючи під тротуарами, як йому й належить.", [3] = "Знайдіть Єремію Пейсона у Підмісті та перевірте, чи насправді він є Єремією Сквернокаменем. Якщо це так, тоді, можливо, він захоче отримати пакунок від Дженіс Сквернокамінь.", [4] = "Кожен раз, коли хтось стає на тарганчика, я плачу. Будь ласка, не змушуй мене плакати.", [5] = "Мене не називали так вже багато років... Але так, в якийсь момент мого життя — до цієї славної невмерлості — це було моє прізвище.\n\nТи стверджуєш, що {стать:знав:знаєш} мою сестру... Чи, радше, що недавно {стать:говорив:говорила} з нею.\n\nЯка вже мертва.\n\nЧотири роки, як.\n\nЗнаєш, якби мої кістки вже не були такими ламкими, я б з радістю вперіщив тобі з ноги. Глумишся над чужим горем?\n\nЩо... у тебе пакунок від моєї сестри?", ["en"] = "The Jeremiah Blues", ["tasks"] = { ["Janice's Parcel"] = "пакунок Дженіс", ["Janice's Parcel (Provided)"] = "пакунок Дженіс (видано)" } },
    [5050] = { [1] = "Оберіг доброї вдачі", [2] = "Схоже, що твої наміри не мають зла, {ім'я}, і я прошу вибачення за непорозуміння. Моя сестра прислала мені деякі особисті речі, зокрема, це просто кумедно, документи на ферму Сквернокаменів. Що ж, поки доведеться почекати з поверненням туди.\n\nЯкщо привид моєї сестри все іще прив'язаний до ферми... можливо, ти повернеш їй це? Це її половина оберега доброї вдачі. Інша половина була у її чоловіка.\n\nМожливо, якщо вона дізнається, що ці речі у мене, її душа зможе спочити.", [3] = "Поверніть Дженіс Сквернокамінь в Західних Зачумлених землях її половину оберега доброї вдачі.", [4] = "Джон, коханий... це ти? Мені чомусь різко стало холодно...", [5] = "Ви віддаєте половину оберега примарі. Дженіс поглянула на оберіг, а потім на вас, наче чогось очікуючи.\n\n\"Любий, де твоя половина оберега? Ми не зможемо бути разом, поки ми не матимемо обидві половини. Любий... ти чуєш мене?\"", ["en"] = "Good Luck Charm", ["tasks"] = { ["Good Luck Half-Charm"] = "половина оберега доброї вдачі", ["Good Luck Half-Charm (Provided)"] = "половина оберега доброї вдачі (видано)" } },
    [5051] = { [1] = "Дві половини стають одним цілим", [2] = "Марення примари продовжуються:\n\n\"Мені так холодно, Джоне. Принеси мені оберіг, і ми будемо разом! Хутчіше, Джоне, чума перетворить нас на огидних звірів! Я не бачу тебе Джон... але я знаю, що ти поруч. Я відчуваю тебе поруч з собою.\"\n\nМожливо, якщо відшукати другу половину оберега та зібрати його в одне ціле, ви дізнаєтеся, що шукає душа Дженіс Сквернокамінь.", [3] = "Відшукайте іншу половину оберега доброї вдачі десь на фермі Сквернокаменів в Західних Зачумлених землях.\n\nВіддайте оберіг доброї вдачі Дженіс Сквернокамінь.", [4] = "Джон, не дай цим гулям дістати тебе... не дай їм дістати мене... мерзенні гулі... оберіг вбереже нас.", [5] = "Ваша рука простягає оберіг доброї вдачі привиду Дженіс Сквернокамінь. Щойно вона бере його до рук, ви помічаєте, як вона вмить змінюється. Її примара злегка мерехтить, і вона дивиться на вас чистими, але все іще зажуреними очима.\n\n\"Ти {стать:звільнив:звільнила} мене... Мені більше не потрібен цей оберіг. Будь ласка, візьми його, можливо, він розрадить тебе так само як і мене колись.\"", ["en"] = "Two Halves Become One", ["tasks"] = { ["Good Luck Charm"] = "оберіг доброї вдачі", ["Good Luck Charm (Provided)"] = "оберіг доброї вдачі (видано)" } },
    [5053] = { [1] = "<UNUSED>", [2] = "Цей квест надішле вам листа на вашу поштову скриньку. Просто натисніть «Завершити».", ["en"] = "<UNUSED>" },
    [5057] = { [1] = "Минулі звершення", [2] = "Перед тим, як ти {стать:заговорив:заговорила} зі мною, {ім'я}, я вже чув про твої звершення... про те, що у тебе є непохитне бажання показати себе, що ти маєш виняткові здібності {клас:р}, і тепер я знаю, що це правда.\n\nТі, хто досягає таких успіхів, заслуговують на визнання. Віднеси цей знак до мого друга Мелора Кам'яного Копита у Громовий Бескид. Впевнений, що він згадає тебе і твої подвиги. Розкажи йому про свої нещодавні досягнення. І ніколи не забувай про те, що {стать:здійснив:здійснила} сьогодні.", [3] = "Принесіть знак Шторма Тіньового Копита до Мелора Кам'яного Копита у Громовий Бескид.", [5] = "Ми навчаємося на своєму життєвому досвіді, {ім'я}. Я впевнений, що ти {стать:став:стала} тільки {стать:сильнішим:сильнішою} та {стать:мудрішим:мудрішою}. Ти дуже {стать:виріс:виросла} з того часу, коли ми вперше говорили.\n\nВізьми це, як нагадування про складні завдання, які ти {стать:виконав:виконала} як {раса}, і як {клас}. І знай, що ти назавжди {стать:завоював:завоювала} мою повагу та захоплення.", ["en"] = "Past Endeavors" },
    [5058] = { [1] = "Щоденник місис Дальсон", [5] = "У щоденнику з пожовклими від часу сторінками відкрито на останньому запису:\n\n\"Гарольд перетворився, і я не знаю, що тепер буде. Я затягнула його в єдине місце, яке можна надійно замкнути, і це забрало у мене купу сил. Я заховала ключ при собі, і молюся, щоб це спрацювало...\n\nЯ сподіваюся, що зможу вибратися звідси, але для цього мені потрібні гроші. Всі наші речі в шафі, я думаю... а чи не у Гарольда був ключ від шафи?\n\nПора мені відпочити, я страшенно втомилася\"", ["en"] = "Mrs. Dalson's Diary" },
    [5059] = { [1] = "Під замком", [4] = "Двері до вбиральні почали тріскатися, неначе їх довго та наполегливо намагалися виламати. Зараз вони замкнені ззовні.\n\nКоли ви погримали у двері, ви почули зсередини грубий стогін! Щоб це не ховалося всередині, воно явно не звучить дружньо.", [5] = "За допомогою ключа, знайденого на скелеті місис Дальсон, ви відчиняєте двері й з вбиральні вистрибує кровожерливий гуль. Він був замкнений там хтозна скільки часу.\n\nСудячи з крику гуля, стає очевидно, що фермера Дальсона вже не врятувати.", ["en"] = "Locked Away", ["tasks"] = { ["Dalson Outhouse Key"] = "ключ від вбиральні Дальсона", ["Dalson Outhouse Key (Provided)"] = "ключ від вбиральні Дальсона (видано)" } },
    [5060] = { [1] = "Під замком", [4] = "Перед вами стоїть масивна шафа, надійно замкнена на врізний замок. Дверцята шафи дуже сильно подряпані. Можна припустити, що це наслідок численних спроб відчинити шафу та дістати те, що міститься в ній.\n\nЯкщо ви збираєтеся відчинити цю шафу, вам доведеться знайти ключ.", [5] = "Ключ, взятий з останків фермера Далсона, ідеально підходить до замка. Двері шафи відчиняються, і всередині лежить кілька вцілілих предметів, які здаються вельми цінними.", ["en"] = "Locked Away", ["tasks"] = { ["Dalson Cabinet Key"] = "ключ від шафи Дальсона", ["Dalson Cabinet Key (Provided)"] = "ключ від шафи Дальсона (видано)" } },
    [5063] = { [1] = "Капелюх багряного вченого", [2] = "Кращого капелюха ти, можливо, ніколи не побачиш. З бездоганної шкури Звіра наші досвідчені майстри створять найфеноменальніший капелюх, про який тільки може мріяти чароплет!\n\nП'ятдесят золотих разом з переліченими предметами — і твою голову прикрасить капелюх багряного вченого:\n\n*Бездоганна шкура Звіра.\n\n*Зотлілі стібки потвори.\n\n*Арканічні кристали.\n\n*Зачаровані багряні нитки.\n\nІ ПРИГОТУЙСЯ ДО ДИВА!", [3] = "Щоб створити капелюх багряного вченого, вам потрібно принести наступні предмети Маліфію Темномолоту: 1 бездоганну шкуру Звіра, 5 зотлілих стібків потвори, 8 арканічних кристалів та 5 зачарованих багряних ниток.\n\nВи також повинні будете заплатити 50 золотих за виготовлення предмета.", [4] = "Якщо у тебе немає всього, що мені потрібно, то ти даремно витрачаєш мій час.", [5] = "Дивовижно! Напевно, тижні пішли на те, щоб зібрати ці компоненти... і як ти {стать:знайшов:знайшла} цю бездоганну шкуру?!?\n\nНасолоджуйся капелюхом, {ім'я}!", ["en"] = "Cap of the Scarlet Savant", ["tasks"] = { ["Arcane Crystal"] = "арканічний кристал", ["Arcane Crystal (Provided)"] = "арканічний кристал (видано)", ["Enchanted Scarlet Thread"] = "зачарована багряна нитка", ["Enchanted Scarlet Thread (Provided)"] = "зачарована багряна нитка (видано)", ["Frayed Abomination Stitching"] = "зотлілий стібок потвори", ["Frayed Abomination Stitching (Provided)"] = "зотлілий стібок потвори (видано)", ["Pristine Hide of the Beast"] = "бездоганна шкура Звіра", ["Pristine Hide of the Beast (Provided)"] = "бездоганна шкура Звіра (видано)" } },
    [5065] = { [1] = "Втрачені скрижалі Мош'ару", [2] = "Троль, з яким ти {стать:розмовляв:розмовляла}, збрехав. Дві таблички, які ти йому {стать:приніс:принесла}, розповідали про сутність Гаккара, але є продовження цієї легенди. Я довго вивчав це питання та знайшов, що існує шість скрижалей Мош'ару, а не дві! Шість!\n\nІ я боюся, що нам не сподобаються секрети, які приховують в собі інші скрижалі...\n\nЗнайди третю та четверту скрижалі Мош'ару. Вони знаходяться в Східних Зачумлених землях, у тролів племені Моходерів. Знайди скрижалі та принеси їх мені.", [3] = "Принесіть третю та четверту скрижалі Мош'ару розвідувачу Залізочоботу в Танаріс.", [4] = "Ти {стать:приніс:принесла} скрижалі? Я боюся, що вони розкриють нам велику загрозу нашому світу.", [5] = "Ти {стать:знайшов:знайшла} їх! Чудово!\n\nДякую тобі, {ім'я}. Я вивчу ці тексти та розшифрую їх значення.\n\nПроте, у мене є для тебе іще одне завдання...", ["en"] = "The Lost Tablets of Mosh'aru", ["tasks"] = { ["Fourth Mosh'aru Tablet"] = "четверта скрижаль Мош'ару", ["Fourth Mosh'aru Tablet (Provided)"] = "четверта скрижаль Мош'ару (видано)", ["Third Mosh'aru Tablet"] = "третя скрижаль Мош'ару", ["Third Mosh'aru Tablet (Provided)"] = "третя скрижаль Мош'ару (видано)" } },
    [5067] = { [1] = "Поножі Аркани", [2] = "Хоча створення такого предмета ще ніколи не було успішним, вважається, що це можливо — за певних обставин.\n\nЯкщо шукач Аркани бажає наділити поножі величезною силою, потрібно знайти наступне:\n\n*Бездоганна шкура Звіра.\n\n*Зотлілі стібки потвори.\n\n*Злитки арканіту.\n\n*Бальзамувальна рідина Кригошепта.\n\nІ ПРИГОТУЙСЯ ДО ДИВА!", [3] = "Щоб створити поножі Аркани, вам потрібно принести наступні предмети Маліфію Темномолоту: 1 бездоганну шкуру Звіра, 5 зотлілих стібків потвори, 5 злитків арканіту та 5 порцій бальзамувальної рідини Кригошепта.\n\nВи також повинні будете заплатити 50 золотих за виготовлення предмета.", [4] = "Якщо у тебе немає всього, що мені потрібно, то ти даремно витрачаєш мій час.", [5] = "Небагато мені довелося бачити, як смертні виконують неймовірні завдання. Насолоджуйся моєю роботою! Пожинай її плоди!", ["en"] = "Leggings of Arcana", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Frayed Abomination Stitching"] = "зотлілий стібок потвори", ["Frayed Abomination Stitching (Provided)"] = "зотлілий стібок потвори (видано)", ["Frostwhisper's Embalming Fluid"] = "бальзамувальна рідина Кригошепта", ["Frostwhisper's Embalming Fluid (Provided)"] = "бальзамувальна рідина Кригошепта (видано)", ["Pristine Hide of the Beast"] = "бездоганна шкура Звіра", ["Pristine Hide of the Beast (Provided)"] = "бездоганна шкура Звіра (видано)" } },
    [5068] = { [1] = "Кіраса кровожерливості", [2] = "Кажуть, що була виготовлена лише одна кіраса кровожерливості, і що її зробили для легендарної душогубки Ґарони. Чи побачить цей світ коли-небудь інша — сумнівно.\n\nАле попри це! Наші майстри можуть відтворити цей предмет за наявності необхідних компонентів:\n\n*Бездоганна шкура Звіра.\n\n*Зотлілі стібки потвори.\n\n*Злитки арканіту.\n\n*Шкіри тіні.\n\nІ ПРИГОТУЙСЯ ДО ДИВА!", [3] = "Щоб створити кірасу кровожерливості, вам потрібно принести наступні предмети Маліфію Темномолоту: 1 бездоганну шкуру Звіра, 10 зотлілих стібків потвори, 5 злитків арканіту та 5 шкір тіні.\n\nВи також повинні будете заплатити 50 золотих за виготовлення предмета.", [4] = "Якщо у тебе немає всього, що мені потрібно, то ти даремно витрачаєш мій час.", [5] = "Я думав що не доживу до цього дня.\n\nДосягнення такого масштабу може бути затьмарене лише нагородою.", ["en"] = "Breastplate of Bloodthirst", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Frayed Abomination Stitching"] = "зотлілий стібок потвори", ["Frayed Abomination Stitching (Provided)"] = "зотлілий стібок потвори (видано)", ["Pristine Hide of the Beast"] = "бездоганна шкура Звіра", ["Pristine Hide of the Beast (Provided)"] = "бездоганна шкура Звіра (видано)", ["Skin of Shadow"] = "шкіра тіні", ["Skin of Shadow (Provided)"] = "шкіра тіні (видано)" } },
    [5081] = { [1] = "Місія Максвелла", [2] = "Ця інформація заповнює останні прогалини в даних з розвідки Чорноскельного шпиля.\n\nАтака має бути рішучою, {ім'я}.\n\nСпочатку треба знищити їхнього воєначальника, троля Вуна. Без його бойових планів у війську орків Чорнокаменю посіється хаос.\n\nПотім тобі потрібно знищити верховного повелителя орків, Омокка. Боягузливі орки Чорнокаменю безсилі без його керівництва.\n\nІ, нарешті, властитель цитаделі, Змійталак. Після його смерті їхнє командування залишиться без голови.", [3] = "Відправляйтеся на Чорноскельний шпиль та вбийте воєначальника Вуна, верховного повелителя Омокка та властителя Змійталака. Коли виконаєте завдання, поверніться до маршала Максвелла.", [4] = "Яка ситуація?", [5] = "Чудова робота, {ім'я}. Принаймні, ти {стать:виграв:виграла} нам більше часу, що дуже важливо для нас.", ["en"] = "Maxwell's Mission", ["tasks"] = { ["Highlord Omokk"] = "верховний повелитель Омокк", ["Highlord Omokk slain"] = "верховний повелитель Омокк: убито", ["Overlord Wyrmthalak"] = "Повелитель Змій", ["Overlord Wyrmthalak (Provided)"] = "Повелитель Змій (видано)", ["Overlord Wyrmthalak slain"] = "Повелитель Змій: убито", ["War Master Voone"] = "воєначальник Вун", ["War Master Voone slain"] = "воєначальник Вун: убито" } },
    [5082] = { [1] = "Загроза Зимокрайових", [2] = "Я приїхала до Зимоключа, щоб дослідити гарячі джерела Кригополум'я. Я помітила, що тутешня вода має дивні властивості. Я ще не змогла виявити їх джерело, а останнім часом у мене були деякі труднощі через хутропузів з племені Зимокрайових.\n\nЇх, здається, тягне до джерел — як і мене. Вони люто захищають воду і не підпускають мене близько до двох великих джерел на півночі звідси.\n\nЯ хотіла б продовжити свої дослідження, тож чи не допоможеш ти мені?", [3] = "Донова Снігосхов у Зимоключі хоче, щоб ви вбили 8 зимокрайових слідопитів, 8 зимокрайових наглядачів лігва та 8 зимокрайових тотемістів.", [4] = "Я вдячна тобі за допомогу!", [5] = "Дуже дякую, {ім'я}! Тепер я можу повернутися до роботи.\n\nЧи {стать:знайшов:знайшла} ти щось цікаве в таборі Зимокрайових?", ["en"] = "Threat of the Winterfall", ["tasks"] = { ["Winterfall Den Watcher"] = "зимокрайовий наглядач лігва", ["Winterfall Den Watcher slain"] = "зимокрайовий наглядач лігва: убито", ["Winterfall Pathfinder"] = "зимокрайовий слідопит", ["Winterfall Pathfinder slain"] = "зимокрайовий слідопит: убито", ["Winterfall Totemic"] = "зимокрайовий тотеміст", ["Winterfall Totemic slain"] = "зимокрайовий тотеміст: убито" } },
    [5083] = { [1] = "Огневиця Зимокрайових", [2] = "Цей флакон, який ви знайшли у зимокрайового хутропуза, порожній, але на дні ви бачите кілька крапель дивної зеленої рідини, яка світиться.\n\nЧи це щось важливе?\n\nДонова Снігосхов, що перебуває біля гарячих джерел у Зимоключі, могла б розказати більше про це.", [3] = "Принесіть порожню фляжку з-під огневиці до Донови Снігосхов в Зимоключ.", [4] = "Що це ти {стать:знайшов:знайшла}?", [5] = "Ти {стать:знайшов:знайшла} це у Зимокрайових?", ["en"] = "Winterfall Firewater", ["tasks"] = { ["Empty Firewater Flask"] = "порожня фляжка з-під огневиці", ["Empty Firewater Flask (Provided)"] = "порожня фляжка з-під огневиці (видано)" } },
    [5084] = { [1] = "Зараження скверною", [2] = "Ця зеленувата рідина... вона трохи нагадує мені мул, який я бачила, коли подорожувала у Скверноліссі. А ще я бачила, як до Деревопузих йшли гінці від Зимокрайових... Можливо, це якось пов'язано з фляжкою, яку ти {стать:знайшов:знайшла}, {ім'я}.\n\nЗа оплотом Деревопузих, у Скверноліссі, живе велика група хутропузів. Їх називають плем'ям Мертволісих, вони були заражені та зведені з розуму скверною. Чому б тобі не пошукати там докази того, що між племенами Зимокрайових і Мертволісих існує якийсь зв'язок?", [3] = "Обшукайте табір Мертволісих хутропузів у північному Скверноліссі у пошуках зачіпок.", [5] = "Усередині казана булькає гнила субстанція з огидним запахом...", ["en"] = "Falling to Corruption" },
    [5085] = { [1] = "Таємничий слиз", [2] = "Зелена субстанція всередині котла схожа на ту, що ви знайшли у фляжці. Ця дивна липка речовина може бути такою ж скверною, як і хутропуз, що створив її...\n\nЯкщо Зимокрайові хутропузи використовують її, це означає, що вони скоро будуть так само заражені, як і плем'я Мертволісих?\n\nКраще повідомити Донову про свої відкриття і принести їй зразок рідини з казана.", [3] = "Розкажіть Донові Снігосхов про свої знахідки.", [4] = "Сподіваюся, ти щось {стать:знайшов:знайшла}, {ім'я}. Плем'я Зимокрайових стає все більш агресивним!", [5] = "Ти дуже {стать:винахідливий:винахідлива}, {ім'я}. Як гадаєш, чи бували Зимокрайові хутропузи в таборі Мертволісих?", ["en"] = "Mystery Goo", ["tasks"] = { ["Flask of Mystery Goo"] = "фляжка таємничого слизу", ["Flask of Mystery Goo (Provided)"] = "фляжка таємничого слизу (видано)" } },
    [5086] = { [1] = "Токсичні страховища", [2] = "Я вивчала зразок, який ти {стать:приніс:принесла}, і, хоча я не можу з упевненістю сказати, я вважаю, що він містить сліди токсичних компонентів. Однак єдиний спосіб впевнитися — зібрати кілька зразків для порівняння.\n\nЯ вважаю, що Мертволісі хутропузи можуть збирати ці компоненти з інших заражених скверною створінь у Скверноліссі, зокрема з елементалів, що живуть в Залізодревих лісах, яких називають токсичними страховищами.\n\nЗабери кілька зразків для порівняння, але будь {стать:обережним:обережною} - там дуже небезпечно!", [3] = "Зберіть 3 краплі токсичних страховищ для Донови Снігосхов в Зимоключі.", [4] = "Я думаю, що ми починаємо розуміти, що тут відбувається, {ім'я}.", [5] = "Я маю порівняти це з речовиною, яку ти {стать:знайшов:знайшла} в казані, і тоді, я впевнена, ми дізнаємося більше.", ["en"] = "Toxic Horrors", ["tasks"] = { ["Toxic Horror Droplet"] = "крапля токсичного страховища", ["Toxic Horror Droplet (Provided)"] = "крапля токсичного страховища (видано)" } },
    [5087] = { [1] = "Зимокрайові гінці", [2] = "Дуже цікаво, {ім'я}...\n\nКоли ця токсична субстанція змішується з водою гарячих джерел, вона втрачає свою токсичність, залишаючи лише здатність тимчасово впливати на тих, хто її вживає. Саме тому Зимокрайові так наполегливо захищають гарячі джерела — вони потрібні їм, щоб очистити свою огневицю.\n\nНам потрібно це зупинити — перервати контакти між племенем Зимокрайових та племенем Мертволісих. Група гінців курсує між селищем Зимокрайових та Скверноліссям. Знайди їх та вбий, а потім забери їхній вантаж.", [3] = "Знайдіть Зимокрайових гінців та не дайте їм доставити вантаж до селища Зимокрайових.", [4] = "Побачимо, що станеться, коли Зимокрайові не отримають свою огневицю!", [5] = "<Донова розглядає вміст ящика.>\n\nЦікаво, чи споживання цієї субстанції робить хутропузів більш агресивними? Вони справді здаються набагато більшими...", ["en"] = "Winterfall Runners", ["tasks"] = { ["Winterfall Crate"] = "ящик Зимокрайових", ["Winterfall Crate (Provided)"] = "ящик Зимокрайових (видано)" } },
    [5088] = { [1] = "Арікара", [2] = "Віднеси вогнистий порошок в Тисячу Шипів і вкинь його у священний вогонь життя, котрий знаходиться на окремому шипі Темнохмарного верхів'я, де хоронять мерців.\n\nЧари, що я вклала в цей порошок, прикличе Арікару до тебе, {ім'я}.\n\nЯ боюсь, що вона може переслідувати Керна Криваве Копито. Надто багато звичаїв тауренів змінилось і це могло розгнівати Арікару. Поквапся, доки ще не запізно, {клас:к}.", [3] = "Убийте Арікару та як доказ принесіть її рештки разом з вогнистим порошком Мотезі Вогняній Гриві на Білосяжну заставу.", [4] = "Чи ти вже {стать:вбив:вбила} лиху змію Арікару, {ім'я}?", [5] = "Це не має жодного сенсу. Навіщо Арікарі полювати на Керна Криваве Копито? Але Маґата не може помилятись, вона ж бо наша найбільш потужна шаманка.\n\n<Мотеґа похитує головою.>\n\nОднак, твоя велика допомога Орді не повинна залишитись непоміченою. Прошу, обери собі нагороду до смаку.", ["en"] = "Arikara", ["tasks"] = { ["Arikara Serpent Skin"] = "зміїна шкіра Арікари", ["Arikara Serpent Skin (Provided)"] = "зміїна шкіра Арікари (видано)", ["Incendia Powder"] = "вогнистий порошок", ["Incendia Powder (Provided)"] = "вогнистий порошок (видано)" } },
    [5089] = { [1] = "Наказ генерала Драккісата", [2] = "З тіла вбитого змія ви витягаєте записку, зміст якої здається вам важливим: це лист від його безпосереднього начальника, генерала Драккісата, в якому згадується якийсь протокол.\n\nВнутрішній голос підказує вам, що цей лист слід віднести маршалу Максвеллу.", [3] = "Віднесіть наказ генерала Драккісата маршалу Максвеллу в Палаючий степ.", [4] = "Що це в тебе, {ім'я}?", [5] = "Все стає набагато цікавіше...", ["en"] = "General Drakkisath's Command", ["tasks"] = { ["General Drakkisath's Command"] = "наказ генерала Драккісата", ["General Drakkisath's Command (Provided)"] = "наказ генерала Драккісата (видано)" } },
    [51] = { [1] = "Солодке бурштинове", [2] = "Ось ще нефільтрований, свіжий напій,\nЧекає обробки, почнімо ж мерщій.\nВугілля дозволить завершити справу,\nДістань мені, друже, ти гілку платана.", [3] = "Принесіть Лютобухові Громовару гілку платану.", [4] = "На біс? Для тебе, що завгодно!\n\nОсь ще нефільтрований, свіжий напій,\nЧекає обробки, почнімо ж мерщій.\nВугілля дозволить завершити справу,\nДістань мені, друже, ти гілку платана.", [5] = "Гик! Хо-хо!", ["en"] = "Sweet Amber", ["tasks"] = { ["A Sycamore Branch"] = "гілка платану", ["A Sycamore Branch (Provided)"] = "гілка платану (видано)" } },
    [510] = { [1] = "Лиховісні плани", [2] = "Серед цих документів є список необхідних припасів. Вони включають звичайні речі (їжа, зброя, одяг), а також більш екзотичне спорядження (маски, олія, отрута).\n\nПроте найбільш помітною є нагальність запитів: ці припаси були потрібні швидко, щоб провести операцію, яка в документі описана як \"важлива місія проти Південнобережжя.\"", [3] = "Принесіть лиховісні плани війтові Малебу в Південнобережжя.", [4] = "{Ім'я}, ти виглядаєш {стать:стривоженим:стривоженою}. Хочеш щось мені розповісти?", [5] = "<Малеб читає документи.>\n\nЦі папери мене дуже турбують, {Ім'я}. Судячи з інформації в цих документах і останніх дій Синдикату, варто припустити, що ця банда головорізів оголосила війну Південнобережжю.", ["en"] = "Foreboding Plans", ["tasks"] = { ["Foreboding Plans"] = "лиховісні плани", ["Foreboding Plans (Provided)"] = "лиховісні плани (видано)" } },
    [5101] = { [1] = "Найвищий тест Лі... Загибелі!", [2] = "Ба! Що ти думаєш, що це якесь випробувальне завдання? Можливо, там навіть є друкарські помилки!\n\nЯкщо ти думаєш, що моє завдання буде легким, то тебе чекає щось інше!\n\nУбий мені десять овець (1933) і не повертайся, поки не вб'єш!", [3] = "Вбий 6 овець для Бенні, а потім тікай як мага швидше!\n\nЖартую... щодо бігу.", ["en"] = "Lee's Ultimate Test Quest... of Doom!", ["tasks"] = { ["Sheep slain"] = "вівця: убито" } },
    [5102] = { [1] = "Гибель генерала Драккісата", [2] = "Ми б'ємося проти цих звірів на двох фронтах: з нашої столиці — Штормовію, ми воюємо з ними зсередини, а тут, у Палаючому степу, ми ведемо битву біля самого їхнього порога. Нам потрібно бути пильними, {ім'я}. Ніхто з них не уникне нашого гніву, так само як ніхто з наших не уникнув їхнього гніву, коли вони напали на наші домівки та сім'ї.\n\nЗнайди цього генерала Драккісата і знищ його!\n\nЗавдання, безумовно, не просте, але й винагорода буде того варта.", [3] = "Відправляйтеся на Чорноскельний шпиль та вбийте генерала Драккісата. Коли виконаєте завдання, поверніться до маршала Максвелла.", [4] = "Справу зроблено?", [5] = "Звісно, наступного удару ми завдамо по лордах драконів. Молодець, {стать:хоробрий:хоробра} {клас:к} Альянсу! Ти гарно {стать:попрацював:попрацювала}.", ["en"] = "General Drakkisath's Demise", ["tasks"] = { ["General Drakkisath"] = "Генерал Драккісат", ["General Drakkisath (Provided)"] = "Генерал Драккісат (видано)", ["General Drakkisath slain"] = "Генерал Драккісат: убито" } },
    [5103] = { [1] = "Смерть у вогні", [2] = "Єдине, що залишилося від цієї людини — кілька обвуглених кісток. Схоже, що вона загинула на відстані витягнутої руки від того, за чим полювала — неопалимих латних рукавиць.\n\nМожливо, вам варто схопити рукавиці та вибратися з вогню?", [3] = "Хтось у цьому світі повинен знати, що робити з цими рукавицями. Хай щастить!", [5] = "Якого...", ["en"] = "Hot Fiery Death" },
    [511] = { [1] = "Зашифрований лист", [2] = "Один з листів на цьому столі зашифрований і незбагненний.", [3] = "Принесіть зашифрований лист до знавця Діббса в Південнобережжя.", [4] = "Так, {стать:пане:пані}? Ви до мене у якійсь справі?", [5] = "Що це? Стривайте-но на хвилинку... дозвольте мені глянути ближче.\n\n...\n\nГм, я ніколи ще не бачив таку форму шифру, але мушу визнати, що моє знання у цій царині далеке від всеохопного.", ["en"] = "Encrypted Letter", ["tasks"] = { ["Cleverly Encrypted Letter"] = "кмітливо зашифрований лист", ["Cleverly Encrypted Letter (Provided)"] = "кмітливо зашифрований лист (видано)" } },
    [512] = { [1] = "Знатні смерті", [2] = "Я побоююся, що керівництво Синдикату націлене на знищення Південнобережжя. Ми повинні завдати удару першими, поки вони не встигли втілити свої плани в життя.\n\nВирушай до руїн Странбрада, що в Альтерацьких горах на півночі. Ми припускаємо, що саме там Синдикат розташував свій штаб.\n\nНам відомо, що цю банду головорізів очолює колишня знать Альтерака. Вони можуть прикидатися звичайними агентами Синдикату, але ти зможеш їх відрізнити за перснями-печатками.\n\nПринеси мені ці печатки.", [3] = "Принесіть 7 альтерацьких печаток війту Малебу в Південнобережжя.", [4] = "Як проходить полювання на Синдикат? {стать:Зібрав:Зібрала} печатки?", [5] = "Чистка Синдикату він знаті нівелює його здатність до дій та перетворить його на звичайну банду злодюжок.\n\nТи добре {стать:послужив:послужила} Альянсу, {Ім'я}.", ["en"] = "Noble Deaths", ["tasks"] = { ["Alterac Signet Ring"] = "альтерацька печатка", ["Alterac Signet Ring (Provided)"] = "альтерацька печатка (видано)" } },
    [5121] = { [1] = "Верховний вождь Зимокрай", [2] = "Хоча ми все ще дуже мало знаємо про те, чому хутропузи вживають цю дивну субстанцію, я вважаю, що краще покласти цьому край, поки ситуація не вийшла з-під контролю.\n\nЗимокрайові хутропузи зазвичай не є агресивним плем'ям, і ця зміна в їхній поведінці наводить мене на думку, що вони, мабуть, виконують накази свого вождя. Швидше за все, ми не зможемо виправити шкоду, яку вже було завдано, але я думаю, що якщо їхнього вождя буде вбито, гірше їм не стане.\n\nПрямуй на схід, до селища Зимокрайових.", [3] = "Донова Снігосхов з Зимоключа хоче, щоб ви перемогли верховного вождя Зимокрая.", [4] = "Можливо, ти дізнаєшся більше в селищі Зимокрайових, {ім'я}.", [5] = "Дуже дякую, {ім'я}. Я сподіваюся, що зможу повернутися до своїх досліджень, не побоюючись нападу хутропузів. Будь ласка, прийми це від мене в нагороду.", ["en"] = "High Chief Winterfall", ["tasks"] = { ["High Chief Winterfall"] = "верховний вождь Зимокрай", ["High Chief Winterfall slain"] = "верховний вождь Зимокрай: убито" } },
    [5122] = { [1] = "Медальйон віри", [4] = "Сила каплиці дає мені силу протистояти порчі в моєму серці. Якщо я покину її, то стану лицарем смерті. Але є медальйон, медальйон віри, що дасть мені силу, щоб покинути її.\n\nБудь ласка, {ім'я}, здобудь медальйон. Його охороняє Малор Ревний, божевільний член Багряного братства, який мешкає в глибині Багряного Бастіону, що в західному Стратгольмі.", [5] = "Ти {стать:здобув:здобула} медальйон! Нарешті я зможу покинути каплицю і виконати свій обов'язок.\n\nЦей обов'язок полягає в тому, щоб вбити чудовисько, яке наслало таке ж прокляття на моїх братів і сестер. Я маю вбити барона Рівендера!", ["en"] = "The Medallion of Faith", ["tasks"] = { ["Medallion of Faith"] = "медальйон віри", ["Medallion of Faith (Provided)"] = "медальйон віри (видано)" } },
    [5123] = { [1] = "Останній фрагмент пазла", [2] = "Журнал, який ви знайшли у верховного вождя, здається об'ємним, але переглянувши кілька сторінок, ви розумієте, що не можете прочитати написане. Усі нотатки настільки недбало виконані, що ви сумніваєтеся, що хтось зможе їх прочитати.\n\nАле, можливо, Донова зможе розібрати це...", [3] = "Принесіть грубо написаний журнал Донові Снігосхов в Зимоключ.", [4] = "Що це, {ім'я}?", [5] = "Цікаво, що це означає... Нічого не можу зрозуміти...", ["en"] = "The Final Piece", ["tasks"] = { ["Crudely-written Log"] = "грубо написаний журнал", ["Crudely-written Log (Provided)"] = "грубо написаний журнал (видано)" } },
    [5124] = { [1] = "Вогняні латні рукавиці", [2] = "Клянуся бородою Тауріссана!\n\nДе ти їх {стать:знайшов:знайшла}?\n\nА головне, чи {стать:готовий:готова} ти з ними розлучитися? Звичайно, я заплачу тобі за такий благородний вчинок.\n\nОсь що я тобі скажу, {ім'я}. Якщо ти віддаси мені ці неопалені рукавиці, я навчу тебе, як виготовити їх самостійно. Все, що тобі потрібно зробити, це зібрати для мене кілька речей, щоб я міг визначити точний рецепт.\n\nДомовились?\n\nОсь список того, що мені потрібно, а незачарований торій я візьму на себе, оскільки ти віддаси рукавиці.", [3] = "Принесіть Маліфію Темномолоту 6 зачарованих злитків торію, 2 сутності вогню та 4 зоряні рубіни. Вам також потрібно буде віддати неопалені латні рукавиці.", [4] = "Час — це гроші, {ім'я}, а у мене не так багато ні того, ні іншого.", [5] = "Як і обіцяв, {ім'я}, ось твій рецепт! Я також додам дещо за всю твою важку працю і відданість. Мені вони все одно не потрібні.", ["en"] = "Fiery Plate Gauntlets", ["tasks"] = { ["Enchanted Thorium Bar"] = "зачарований злиток торію", ["Enchanted Thorium Bar (Provided)"] = "зачарований злиток торію (видано)", ["Essence of Fire"] = "сутність вогню", ["Essence of Fire (Provided)"] = "сутність вогню (видано)", ["Star Ruby"] = "зоряний рубін", ["Star Ruby (Provided)"] = "зоряний рубін (видано)", ["Unfired Plate Gauntlets"] = "неопалені латні рукавиці", ["Unfired Plate Gauntlets (Provided)"] = "неопалені латні рукавиці (видано)" } },
    [5125] = { [1] = "Розплата Аурія", [5] = "{Ім'я}, я помираю... але моя душа знайшла порятунок. Я завдячую тобі сильніше, ніж можна описати словами. Прошу, візьми це.... і продовжуй боротися, о {стать:хоробрий:хоробра} {клас:к}!", ["en"] = "Aurius' Reckoning" },
    [5126] = { [1] = "Історія Лоракса", [2] = "Сатир ходить і розмовляє сам з собою. Чи хочете ви потурбувати його?", [3] = "Поговоріть з Лораксом. Послухайте, що він скаже.", [4] = "...", [5] = "<Лоракс сміється.>", ["en"] = "Lorax's Tale", ["tasks"] = { ["Listen to Lorax's Tale"] = "Послухайте казку Лоракса" } },
    [5127] = { [1] = "Демонічна кузня", [2] = "Так, Лоракс укладає угоди, але він не працює з нікчемними смертними.\n\nОднак я можу укласти з тобою угоду... візьми цю піку, вона просякнута потужною енергією скверни. Коли знайдеш Ґоралука Розбите Ковадло, вбий його і всади цю піку в його мертве серце. Він пообіцяв свою душу і я її заберу. Принеси мені піку та поверни прототип нагрудника, який вкрав цей злодій і я навчу тебе того, чого хотів навчитися він.", [3] = "Відправляйтесь на Чорноскельний шпиль та знайдіть Ґоралука Розбите Ковадло. Убийте його, а потім встроміть закривавлену піку в труп, щоб наповнити її душею Ґоралука.\n\nВи також повинні знайти прототип рунічного нагрудника.\n\nВіднесіть наповнену душею піку та прототип рунічного нагрудника Лораксу в Зимоключ.", [4] = "Не піддавайся спокусі...", [5] = "Нашу угоду ти не {стать:порушив:порушила}. Душу я забрав. Нагороду ти отримаєш.", ["en"] = "The Demon Forge", ["tasks"] = { ["Soul Stained Pike"] = "наповнена душею піка", ["Soul Stained Pike (Provided)"] = "наповнена душею піка (видано)", ["Unforged Rune Covered Breastplate"] = "прототип рунічного нагрудника", ["Unforged Rune Covered Breastplate (Provided)"] = "прототип рунічного нагрудника (видано)" } },
    [5128] = { [1] = "Слова верховного вождя", [2] = "Зимокрайові більше не становлять загрози для мене, але якщо ти все ще хочеш дізнатися, що підштовхувало хутропузів створювати та вживати цю дивну вогняну воду, я думаю, тобі слід звернутися до Келека Хранителя Неба.\n\nВін є членом групи, відомої як Смарагдове Коло, друїдів, які присвятили себе роботі у Скверноліссі, зцілюючи землю від скверни.\n\nКелек має великий досвід роботи з хутропузами у Скверноліссі та може допомогти тобі дізнатися більше про журнал.\n\nЩе раз дякую, {ім'я}.", [3] = "Віднесіть грубо написаний журнал Келеку Хранителю Неба у південному Скверноліссі.", [4] = "Смарагдове Коло дружнє до всіх, {раса:к}. Що я можу зробити для тебе?", [5] = "Так, якщо ти дозволиш мені трохи дослідити його, я, можливо, зможу перекласти його для тебе.\n\n<Келек гортає сторінки.>\n\nКоли я зможу повністю дослідити його, я тебе повідомлю.\n\nДякую, що {стать:поділився:поділилася} цим зі мною, {ім'я}. Про хутропузів з племені Зимокрайових немає майже жодних відомостей.", ["en"] = "Words of the High Chief", ["tasks"] = { ["Crudely-written Log"] = "грубо написаний журнал", ["Crudely-written Log (Provided)"] = "грубо написаний журнал (видано)" } },
    [5141] = { [1] = "Шкірництво драконячої луски", [2] = "Шкірництво драконячої луски — непросте ремесло, проте вельми прибуткове. Я можу навчити тебе виготовляти цю чудову кольчугу, але тільки якщо ти погодишся на певні умови.\n\nОбравши цей шлях, ти зобов'язуєшся ніколи не вивчати шкірництво стихій чи предків. Ти можеш практикувати лиш одне з цих трьох ремесел. Крім того, мені знадобляться зразки твоїх обладунків з луски скорпіда. Нарешті, мені потрібен доказ твоєї здатності добувати основні матеріали для цієї справи: луску драконів.", [3] = "Принесіть 2 міцні кіраси з луски скорпіда, 2 міцні рукавиці з луски скорпіда та 10 зношених драконячих лусок Пітеру Ґалену в Азшару.\n\nВиконання цього завдання відкриє вам доступ до шкірництва драконячої луски.\n\nВиконання цього завдання позбавить вас можливості вивчати шкірництво стихій та шкірництво предків. Переконайтеся, що це саме той шлях, яким ви бажаєте йти.", [4] = "Якщо ти {стать:готовий:готова} зробити вибір і стати {стать:шкірником:шкірницею} драконячої луски, то я готовий прийняти тебе в учні. Просто принеси мені речі, про які я тебе просив, і ми розпочнемо твоє навчання.", [5] = "Варто визнати, що потрібна сильна воля, щоб прийняти таке важливе рішення. Запевняю тебе, що робота з лускою дракона виявиться прибутковим та корисним заняттям для тебе.\n\nЩоб поліпшити це ремесло у майбутньому, просто звернись до мене, і я навчу тебе всього, чого тобі ще не вдалося освоїти.", ["en"] = "Dragonscale Leatherworking", ["tasks"] = { ["Tough Scorpid Breastplate"] = "міцна кіраса з луски скорпіда", ["Tough Scorpid Breastplate (Provided)"] = "міцна кіраса з луски скорпіда (видано)", ["Tough Scorpid Gloves"] = "міцні рукавиці з луски скорпіда", ["Tough Scorpid Gloves (Provided)"] = "міцні рукавиці з луски скорпіда (видано)", ["Worn Dragonscale"] = "зношена драконяча луска", ["Worn Dragonscale (Provided)"] = "зношена драконяча луска (видано)" } },
    [5142] = { [1] = "Маленька Памела", [2] = "Більшість з нас загинула в битві Дарроушира. Стільки загинуло... та навіть гірше.\n\nКоли битва почалася, я заховала свою племінницю Памелу і тепер не знаю, що з нею сталося. Я звичайний мандрівний дух, але моє серце жадає дізнатись про долю Памели.\n\nБудь ласка, {стать:добрий:добра} {клас:к}, пошукай її в Дарроуширі. Це на сході, за Посухою Ґаррона.", [3] = "Відшукайте Памелу Редпат.", [5] = "Привіт. Мене звати Памела, а тебе?", ["en"] = "Little Pamela" },
    [5143] = { [1] = "Шкірництво предків", [2] = "Для вивчення шкірництва предків необхідно розуміти, наскільки первісною є природа. Я знаю, що ти вже {стать:опанував:опанувала} мистецтво виготовлення обладунків з дикої шкіри, і я готовий завершити твою підготовку.\n\nАле знай, {клас:к}: обираючи цей шлях, ти ніколи не зможеш вивчити шкірництво драконячої луски чи шкірництво стихій. Ти можеш практикувати лиш одне з цих трьох мистецтв. Отож, принеси мені найкращі зразки твоїх обладунків з дикої шкіри. Після цього ми розпочнемо твоє навчання.", [3] = "Принесіть жилет та шолом з дикої шкіри Кариссії Місячній Мисливиці у Фералас.\n\nВиконання цього завдання відкриє вам доступ до шкірництва предків.\n\nВиконання цього завдання позбавить вас можливості вивчати шкірництво драконячої луски та шкірництво стихій. Переконайтеся, що це саме той шлях, яким ви бажаєте йти.", [4] = "Природа — це сила, яку слід задовольнити, перш ніж використовувати її у виготовленні шкіряних виробів. Принеси мені пожертву цій силі, і я подбаю про те, щоб тебе почули.", [5] = "Ти {стать:приніс:принесла} найкращу пожертву, і природа незабаром дозволить тобі підкорити її волю. Після того, як я закінчу своє наставництво, твоя робота стане втіленням сил природи.\n\nЩоб поліпшити це ремесло у майбутньому, просто звернись до мене, і я навчу тебе всього, чого тобі ще не вдалося освоїти.", ["en"] = "Tribal Leatherworking", ["tasks"] = { ["Wild Leather Helmet"] = "шолом з дикої шкіри", ["Wild Leather Helmet (Provided)"] = "шолом з дикої шкіри (видано)", ["Wild Leather Vest"] = "жилет з дикої шкіри", ["Wild Leather Vest (Provided)"] = "жилет з дикої шкіри (видано)" } },
    [5144] = { [1] = "Шкірництво стихій", [2] = "Я — майстриня шкірництва стихій, і якщо ти {стать:готовий:готова} відкрити свій розум великим силам стихій, я поділюся з тобою всім, що знаю.\n\nАле знай, {клас:к}: обираючи цей шлях, ти погоджуєшся ніколи не вивчати шкірництво драконячої луски чи шкірництво предків. Ти можеш практикувати лиш одне з цих трьох мистецтв. Крім того, мені знадобиться доказ твоєї гармонії з усіма стихіями. Для цього принеси мені найчистіші сутності вогню, води, землі та вітру.", [3] = "Принесіть 2 серця вогню, 2 кулі води, 2 ядра землі та 2 подихи вітру Сарі Кожум'яці у Випалену ущелину.\n\nВиконання цього завдання відкриє вам доступ до шкірництва стихій.\n\nВиконання цього завдання позбавить вас можливості вивчати шкірництво драконячої луски та шкірництво предків. Переконайтеся, що це саме той шлях, яким ви бажаєте йти.", [4] = "Створення такого виду шкіряних обладунків вимагає терпіння та відданості. Після того, як ти обереш свій шлях зі стихіями, ти не зможеш звернути з нього. Принеси мені доказ своєї гідності, і ми розпочнемо твоє навчання.", [5] = "Ти {стать:обрав:обрала} свій шлях, і стихії приймають тебе. Після того, як я закінчу своє наставництво, ти зможеш володіти майстерністю створення найкращих шкіряних вбрань.\n\nЩоб поліпшити це ремесло у майбутньому, просто звернись до мене, і я навчу тебе всього, чого тобі ще не вдалося освоїти.", ["en"] = "Elemental Leatherworking", ["tasks"] = { ["Breath of Wind"] = "подих вітру", ["Breath of Wind (Provided)"] = "подих вітру (видано)", ["Core of Earth"] = "ядро землі", ["Core of Earth (Provided)"] = "ядро землі (видано)", ["Globe of Water"] = "куля води", ["Globe of Water (Provided)"] = "куля води (видано)", ["Heart of Fire"] = "серце вогню", ["Heart of Fire (Provided)"] = "серце вогню (видано)" } },
    [5145] = { [1] = "Шкірництво драконячої луски", [2] = "Шкірництво драконячої луски — непросте ремесло, проте вельми прибуткове. Я можу навчити тебе виготовляти цю чудову кольчугу, але тільки якщо ти погодишся на певні умови.\n\nОбравши цей шлях, ти зобов'язуєшся ніколи не вивчати шкірництво стихій чи предків. Ти можеш практикувати лиш одне з цих трьох ремесел. Крім того, мені знадобляться зразки твоїх обладунків з луски скорпіда. Нарешті, мені потрібен доказ твоєї здатності добувати основні матеріали для цієї справи: луску драконів.", [3] = "Принесіть 2 міцні кіраси з луски скорпіда, 2 міцні рукавиці з луски скорпіда та 10 зношених драконячих лусок Торкафу Драконячому Оку в Безплідні краї.\n\nВиконання цього завдання відкриє вам доступ до шкірництва драконячої луски.\n\nВиконання цього завдання позбавить вас можливості вивчати шкірництво стихій та шкірництво предків. Переконайтеся, що це саме той шлях, яким ви бажаєте йти.", [4] = "Якщо ти {стать:готовий:готова} зробити вибір і стати {стать:шкірником:шкірницею} драконячої луски, то я готовий прийняти тебе в учні. Просто принеси мені речі, про які я тебе просив, і ми розпочнемо твоє навчання.", [5] = "Варто визнати, що потрібна сильна воля, щоб прийняти таке важливе рішення. Запевняю тебе, що робота з лускою дракона виявиться прибутковим та корисним заняттям для тебе.\n\nЩоб поліпшити це ремесло у майбутньому, просто звернись до мене, і я навчу тебе всього, чого тобі ще не вдалося освоїти.", ["en"] = "Dragonscale Leatherworking", ["tasks"] = { ["Tough Scorpid Breastplate"] = "міцна кіраса з луски скорпіда", ["Tough Scorpid Breastplate (Provided)"] = "міцна кіраса з луски скорпіда (видано)", ["Tough Scorpid Gloves"] = "міцні рукавиці з луски скорпіда", ["Tough Scorpid Gloves (Provided)"] = "міцні рукавиці з луски скорпіда (видано)", ["Worn Dragonscale"] = "зношена драконяча луска", ["Worn Dragonscale (Provided)"] = "зношена драконяча луска (видано)" } },
    [5146] = { [1] = "Шкірництво стихій", [2] = "Я — майстер шкірництва стихій, і якщо ти {стать:готовий:готова} відкрити свій розум великим силам стихій, я поділюся з тобою всім, що знаю.\n\nАле знай, {клас:к}: обираючи цей шлях, ти погоджуєшся ніколи не вивчати шкірництво драконячої луски чи шкірництво предків. Ти можеш практикувати лиш одне з цих трьох мистецтв. Крім того, мені знадобиться доказ твоєї гармонії з усіма стихіями. Для цього принеси мені найчистіші сутності вогню, води, землі та вітру.", [3] = "Принесіть 2 серця вогню, 2 кулі води, 2 ядра землі та 2 подихи вітру Брумну Зимовому Копиту на височину Араті.\n\nВиконання цього завдання відкриє вам доступ до шкірництва стихій.\n\nВиконання цього завдання позбавить вас можливості вивчати шкірництво драконячої луски та шкірництво предків. Переконайтеся, що це саме той шлях, яким ви бажаєте йти.", [4] = "Створення такого виду шкіряних обладунків вимагає терпіння та відданості. Після того, як ти обереш свій шлях зі стихіями, ти не зможеш звернути з нього. Принеси мені доказ своєї гідності, і ми розпочнемо твоє навчання.", [5] = "Ти {стать:обрав:обрала} свій шлях, і стихії приймають тебе. Після того, як я закінчу своє наставництво, ти зможеш володіти майстерністю створення найкращих шкіряних вбрань.\n\nЩоб поліпшити це ремесло у майбутньому, просто звернись до мене, і я навчу тебе всього, чого тобі ще не вдалося освоїти.", ["en"] = "Elemental Leatherworking", ["tasks"] = { ["Breath of Wind"] = "подих вітру", ["Breath of Wind (Provided)"] = "подих вітру (видано)", ["Core of Earth"] = "ядро землі", ["Core of Earth (Provided)"] = "ядро землі (видано)", ["Globe of Water"] = "куля води", ["Globe of Water (Provided)"] = "куля води (видано)", ["Heart of Fire"] = "серце вогню", ["Heart of Fire (Provided)"] = "серце вогню (видано)" } },
    [5148] = { [1] = "Шкірництво предків", [2] = "Для вивчення шкірництва предків необхідно розуміти, наскільки первісною є природа. Я знаю, що ти вже {стать:опанував:опанувала} мистецтво виготовлення обладунків з дикої шкіри, і я готовий завершити твою підготовку.\n\nАле знай, {клас:к}: обираючи цей шлях, ти ніколи не зможеш вивчити шкірництво драконячої луски чи шкірництво стихій. Ти можеш практикувати лиш одне з цих трьох мистецтв. Отож, принеси мені найкращі зразки твоїх обладунків з дикої шкіри. Після цього ми розпочнемо твоє навчання.", [3] = "Принесіть жилет та шолом з дикої шкіри Се'Джибу в Тернисту долину.\n\nВиконання цього завдання відкриє вам доступ до шкірництва предків.\n\nВиконання цього завдання позбавить вас можливості вивчати шкірництво драконячої луски та шкірництво стихій. Переконайтеся, що це саме той шлях, яким ви бажаєте йти.", [4] = "Природа — це сила, яку слід задовольнити, перш ніж використовувати її у виготовленні шкіряних виробів. Принеси мені пожертву цій силі, і я подбаю про те, щоб тебе почули.", [5] = "Ти {стать:приніс:принесла} найкращу пожертву, і природа незабаром дозволить тобі підкорити її волю. Після того, як я закінчу своє наставництво, твоя робота стане втіленням сил природи.\n\nЩоб поліпшити це ремесло у майбутньому, просто звернись до мене, і я навчу тебе всього, чого тобі ще не вдалося освоїти.", ["en"] = "Tribal Leatherworking", ["tasks"] = { ["Wild Leather Helmet"] = "шолом з дикої шкіри", ["Wild Leather Helmet (Provided)"] = "шолом з дикої шкіри (видано)", ["Wild Leather Vest"] = "жилет з дикої шкіри", ["Wild Leather Vest (Provided)"] = "жилет з дикої шкіри (видано)" } },
    [5149] = { [1] = "Лялька Памели", [2] = "Моя тітка Марлен сказала мені залишатися вдома, поки тато на війні. Мій тато — найхоробріший у світі!\n\nАле я вже так довго сиджу тут, а він все ще не повернувся. Інколи сюди приходять погані люди та шепочуть. Я так хочу, щоб тато прогнав їх, але його все немає...\n\nА іноді, коли темніє, я хочу погратися з моєю лялькою, але не можу, бо вона залишилася в місті.\n\nТи знайдеш мою ляльку?", [3] = "Знайдіть ляльку Памели.", [4] = "Ти {стать:знайшов:знайшла} мою ляльку?", [5] = "Ура, ти {стать:знайшов:знайшла} її! Моя лялька! Дякую!", ["en"] = "Pamela's Doll", ["tasks"] = { ["Pamela's Doll"] = "лялька Памели", ["Pamela's Doll (Provided)"] = "лялька Памели (видано)" } },
    [5150] = { [1] = "Даданґа голодна!", [4] = "Даданґа уважно дивиться на вас, коли ви наближаєтеся до неї. Здається, вона чогось хоче...\n\nМабуть, вона голодна!\n\nУ кратері має знайтись щось, що було б чудовою їжею для травоїдного. Даданґа — велика тварина, тому все, що ви принесете їй, повинно бути у великих кількостях!", [5] = "Ви кладете паростки перед собою і Даданґа виглядає задоволеною.\n\nНа знак подяки за ласощі вона підштовхує до вас невеликий пакунок у коричневій обгортці!", ["en"] = "Dadanga is Hungry!", ["tasks"] = { ["Bloodpetal Sprout"] = "паросток кровоцвіту", ["Bloodpetal Sprout (Provided)"] = "паросток кровоцвіту (видано)" } },
    [5152] = { [1] = "Тітонька Марлен", [2] = "Я така самотня! Де моя сім'я? Тітонька Марлен сказала мені чекати тут, але потім вона пішла і не повернулася! Ти не {стать:бачив:бачила} мого тата?\n\nМоже, тітонька Марлен знає, де він. Вона живе поруч з Андоралом, в будиночку на півдні. Здається, на пагорбі... так, вона казала, що на пагорбі.\n\nБудь ласка, {ім'я}. Ми ж тепер друзі! Поговориш з моєю тіткою?", [3] = "Поговоріть з Марлен, на південь від руїн Андорала.", [5] = "Ти {стать:бачив:бачила} Памелу? Як вона? Вона жива?? О, ні! Бідна Памела! Вона була такою малою, такою щасливою дитиною...\n\nВона не знає, що сталося з її батьком? Моїм братом, Джозефом?\n\nНі... навряд чи вона зможе це зрозуміти. А якби й могла, то я не зможу розповісти їй...", ["en"] = "Auntie Marlene" },
    [5153] = { [1] = "Дивна гномка", [2] = "Я хотіла б, щоб Джозеф знову був зі своєю дочкою, але цього не станеться. Його душу спотворила Скара, і він став чудовиськом.\n\nАле, можливо, ми зможемо змінити його долю.\n\nЗнайди серед могил пам'ятник Джозефу. Його тіла там немає, проте під пам'ятником лежить його обручка. Віднеси її до Хромі, дивної гномки... з дуже дивними здібностями.\n\nВона живе в руїнах таверни в північно-західній частині Андорала.", [3] = "Принесіть обручку Джозефа до Хромі.", [4] = "А ти вчасно... Ти ж не з майбутнього?", [5] = "Що це? Обручка? Дай-но погляну...\n\nКолись вона належала чоловіку, якого спіткала велика трагедія.\n\nТи хочеш допомогти йому? Вже пізно, хоча... можливо, ми зможемо допомогти йому в минулому!", ["en"] = "A Strange Historian", ["tasks"] = { ["Joseph's Wedding Ring"] = "обручка Джозефа", ["Joseph's Wedding Ring (Provided)"] = "обручка Джозефа (видано)" } },
    [5154] = { [1] = "Літопис Дарроушира", [2] = "Щоб врятувати Джозефа Редпата, ми маємо вивчити його минуле. Ми можемо дізнатися про це в літописі Дарроушира — книзі, що зберігається в ратуші Андорала.\n\nПринеси мені цю книгу. Ми зможемо дізнатися про долю Джозефа та, якщо пощастить... змінити її!", [3] = "Принесіть літопис Дарроушира до Хромі в Андорал.", [4] = "Ти {стать:знайшов:знайшла} книгу, {ім'я}?", [5] = "Чудово, ти {стать:знайшов:знайшла} її!\n\nТи {стать:прочитав:прочитала} її? Там є щось про Джозефа Редпата? Якщо так, тоді ми зможемо його врятувати!\n\nОу. Літопис Дарроушира каже, що під час битви Джозеф Редпат став жертвою порчі та примкнув до військ Скари! Він зрадив захисників Дарроушира.\n\nЯка печальна доля. Думаю, ми маємо змінити її, як гадаєш?", ["en"] = "The Annals of Darrowshire", ["tasks"] = { ["Annals of Darrowshire"] = "літопис Дарроушира", ["Annals of Darrowshire (Provided)"] = "літопис Дарроушира (видано)" } },
    [5155] = { [1] = "Сили Джеденара", [2] = "Якщо мені доведеться покластися на тебе в цій справі, тобі доведеться заслужити мою довіру.\n\nЯ маю знати, що ти ворог Тіньової Ради — тих, хто несе відповідальність за безліч злочинів тут і за межами цього лісу.\n\nЙди глибше в Сквернолісся. На заході ти побачиш стежку, що веде до Джеденара. Саме там Рада будує свої підступні плани разом з Палаючим Легіоном.\n\nУвійди в глибини одного з їхніх курганів, вбий їх і повертайся до мене. Тоді я знатиму, що ти справді намагаєшся допомогти нам.", [3] = "Увійдіть до Джеденара та вбийте 4 джеденарських гончих, 4 джеденарських вартових, 6 джеденарських адептів та 6 джеденарських культистів, перш ніж повернутися до Ґрети Мохового Копита у Сквернолісся.", [4] = "Як проходить твій бій, {ім'я}? Я знаю, що проливати кров для доказу честі може бути огидно, але ти маєш зрозуміти, що це слугує двом цілям: ти полегшуєш моє завдання, убиваючи їх, і ми здобуваємо повагу один до одного, що зробить нас сильнішими в майбутньому.\n\nСподіваюсь, ти розумієш це.", [5] = "Чудово, {ім'я}! Їхні ряди слабшають, і ми можемо посилити тиск на них.\n\nНу, {стать:спробував:спробувала} їхню міць? І як тобі? Вони виявилися такими ж сильними, як ти {стать:припускав:припускала}? Чи сильнішими? Чи, можливо, вони взагалі не були для тебе викликом? Хіба це не чудово?\n\nМи можемо обговорити подробиці твоїх подвигів пізніше. Зараз ми маємо зосередитись на інших справах.", ["en"] = "Forces of Jaedenar", ["tasks"] = { ["Jaedenar Adept"] = "джеденарський адепт", ["Jaedenar Adept slain"] = "джеденарський адепт: убито", ["Jaedenar Cultist"] = "джеденарський культист", ["Jaedenar Cultist slain"] = "джеденарський культист: убито", ["Jaedenar Guardian"] = "джеденарський вартовий", ["Jaedenar Guardian slain"] = "джеденарський вартовий: убито", ["Jaedenar Hound"] = "джеденарська гонча", ["Jaedenar Hound slain"] = "джеденарська гонча: убито" } },
    [5156] = { [1] = "Перевірка осквернення", [2] = "На півночі, на схід від дороги, у так званій долині Шматованих порубів, є місце, де були викликані пекельники під час останньої великої війни — кратери досі залишились там, як і самі пекельники.\n\nЯ хочу дізнатися дві речі. По-перше, чи блукають ще ентропічні елементалі в тому районі? А по-друге, чи кратери все ще наповнені оскверненою, затхлою водою, яка збирається там десятки років? Допоможеш мені перевірити це, {ім'я}? Але будь {стать:обережним:обережною}, пекельники знищують все на своєму шляху.", [3] = "Знайдіть та знищте 2 ентропічних звірів та 2 ентропічних жахів, досліджуючи долину Шматованих порубів. Після цього перевірте, чи заповнені кратери зараженою водою. Потім повертайтеся до Тарунна Червоного Пера в Сквернолісся.", [4] = "Я сподіваюсь, твої пошуки пройдуть успішно, {ім'я}. Я ще не ходив настільки далеко на північ, але визнаю, що думка про зустріч з пекельником трохи налякала мене. Ці створіння безмозкі, але все одно досить страхітливі.", [5] = "Добре, що ти {стать:живий:жива}, {ім'я}. Жаль, що вода все ще там. Я сподівався знайти принаймні одне чисте джерело води у Скверноліссі. Схоже, що мої пошуки були невдалими. Процес зцілення землі міг бути значно спрощений, якби була присутня чиста вода.\n\nДоведеться зайнятися порятунком тих істот, яких ще можна врятувати, по ходу справи винищуючи тих, чиє зараження зайшло так далеко, що вони самі стали загрозою і для себе, і для всіх, хто опинився в цьому колись могутньому лісі.", ["en"] = "Verifying the Corruption", ["tasks"] = { ["Entropic Beast"] = "ентропічний звір", ["Entropic Beast slain"] = "ентропічний звір: убито", ["Entropic Horror"] = "ентропічний жах", ["Entropic Horror slain"] = "ентропічний жах: убито" } },
    [5157] = { [1] = "Збір зараженої води", [2] = "Глибоко в Дженедарі знаходиться оплот Тіні — головна фортеця їхньої скверни та зла.\n\nТіньова Рада має захисні закляття, що оточують їхнє лігво у вигляді жаровень. Якщо я хочу дізнатися більше про нашого ворога з допомогою провидіння, то ми маємо загасити їх. Це дозволить мені шпигувати за Радою і дізнатись, хто ними керує.\n\nЯкщо можеш, візьми цю флягу і наповни її в місячному колодці, що знаходиться в центрі Дженедара. Потім повертайся до мене.", [3] = "Віднесіть порожню флягу до місячного колодязя в центрі Дженедара і наповніть її, а потім поверніться до Ґрети Мохового Копита у Сквернолісся.", [4] = "Коли ми отримаємо воду з місячного колодязя, ми очистимо її та використаємо для гасіння жаровень, які захищають оплот Тіні. Це дозволить мені дізнатись, хто саме керує цим... культом.\n\nМатір-Земля, будь з нами.", [5] = "Ця вода чудово підійде, {ім'я}.\n\nТепер нам залишається лише очистити воду та залити жаровні. Це буде не складно — доведеться лише трішки побігати.\n\nСподіваюся, ми швидко впораємося з цим.", ["en"] = "Collection of the Corrupt Water", ["tasks"] = { ["Corrupt Moonwell Water"] = "заражена вода місячного колодязя", ["Corrupt Moonwell Water (Provided)"] = "заражена вода місячного колодязя (видано)" } },
    [5158] = { [1] = "У пошуках духовної допомоги", [2] = "Віднеси цю заражену воду в Степи, {ім'я}. На півдні від Брашпиля, на узбережжі, живе моя стара приятелька, шаманка, на ім'я Іслен Морська Провидиця. Вона потужна шаманка, яка нам допоможе. Її зв'язок з духами води завжди був сильним. Наша благородна справа повинна бути достатньою, щоб переконати її та духів води допомогти нам у цьому завданні.\n\nТи знайдеш її в невеликому таборі вздовж берега. І, {ім'я}, ігноруй піратів... вони можуть бути настирними, але не будуть для тебе загрозою.", [3] = "Віднесіть заражену воду з місячного колодязя до Іслен Морської Провидиці у Степи.", [4] = "Я відчуваю, що ти не {стать:простий мандрівник:проста мандрівниця}, {стать:який:яка} шукає шлях до Брашпиля. Ходімо, присядь і відпочинь у нашому таборі. Поговоримо, коли будеш {стать:готовий:готова}.", [5] = "А, тобі потрібно очистити воду з місячного колодязя. Зупинити цю злу силу у Скверноліссі, здається достатньо благородною справою, але не мені вирішувати, чи буде вода очищена. Я запитаю духів води — вони вирішать, чи є твоя причина достатньою.\n\nДай мені хвилинку, і я розкажу їм про твоє прохання. Сподіваюся, вони переймуться до тебе співчуттям, як і я.", ["en"] = "Seeking Spiritual Aid", ["tasks"] = { ["Corrupt Moonwell Water"] = "заражена вода місячного колодязя", ["Corrupt Moonwell Water (Provided)"] = "заражена вода місячного колодязя (видано)" } },
    [5159] = { [1] = "Повернення очищеної води до Сквернолісся", [2] = "Хвала духам, {ім'я}. Це вони прийшли тобі на допомогу, а не я.\n\nЯ даю тобі цю очищену воду. Будь ласка, передай Ґреті мої вітання та найкращі побажання. Вона займається чимось важливішим, ніж більшість з нас... я впевнена, вона скоро зрозуміє це.\n\nТіньова Рада — це не та сила, до якої можна ставитись легковажно, {ім'я}. Пам'ятай про це.\n\nА тепер йди. Візьми воду і повертайся до Ґрети.", [3] = "Віднесіть очищену воду місячного колодязя Ґреті Моховому Копиту у Сквернолісся.", [4] = "Ти {стать:повернувся:повернулася}, {ім'я}. Добре. Ти {стать:знайшов:знайшла} Іслен у Степах? Чи нам доведеться шукати інший шлях до нашої цілі?", [5] = "Дуже добре, цієї води повинно вистачити для наших потреб.\n\nЯ рада чути, що Іслен змогла нам допомогти. Її сила у взаємодії з духами води завжди була великою. Вона мудра, і рідко трапляється, що духи не згодні з її цілями. Те, що вони благословили нашу справу, дає мені надію, що ми йдемо правильним шляхом.", ["en"] = "Cleansed Water Returns to Felwood", ["tasks"] = { ["Purified Moonwell Water"] = "очищена вода місячного колодязя", ["Purified Moonwell Water (Provided)"] = "очищена вода місячного колодязя (видано)" } },
    [5160] = { [1] = "Матрона-берегиня", [2] = "Тобі потрібно вирушити в Калімдор, {раса:к}. Дракони мого крила осіли в холодних просторах Зимоключа. Коли ти будеш там, знайди печери Мазторіл.\n\nУ печерах, на крижаній підлозі ти знайдеш кобальтові руни. Якщо ти візьмеш одну з моїх лусочок та встанеш на руну, ти перенесешся до нашої матрони-берегині — Гале.\n\nВіддай їй мою луску — вона зможе показати Гале все, що мені довелося бачити й відчувати у цьому проклятому місці.", [3] = "Відправляйтесь в Зимоключ і знайдіть Гале. Віддайте їй луску Авбі.", [4] = "Рада бачити тебе, {ім'я}.", [5] = "Аспекти наполягають на тому, щоб ми не втручалися у справи смертних. Але це не завжди можливо у цьому світі — особливо, коли хтось із наших родичів зневажає такі накази.", ["en"] = "The Matron Protectorate", ["tasks"] = { ["Awbee's Scale"] = "луска Авбі", ["Awbee's Scale (Provided)"] = "луска Авбі (видано)" } },
    [5161] = { [1] = "Гнів синього крила", [2] = "Ми розуміємо, що проклятий виводок Смертекрила намагається зробити, і знаємо, що цього не можна допустити.\n\nЧерез захист, який надає Нефаріану Чорноскельна гора, нам стає дедалі важче втручатися.\n\nАле ми можемо допомогти тобі, {стать:смертний:смертна}, якщо ти наважишся на це.\n\nПеред тобою лежить шлях, сповнений небезпек. Ти {стать:повинен:повинна} вирішити, чи приймати нашу допомогу. Обдумай це і знову звернись до мене, коли приймеш рішення.", [3] = "Поговоріть з Гале, якщо бажаєте продовжити.", [5] = "Хай буде так...", ["en"] = "Wrath of the Blue Flight" },
    [5162] = { [1] = "Гнів синього крила", [2] = "Сили аркани контролюю я, і ці сили відправлять тебе до твоєї наступної цілі.\n\nЯк будеш {стать:готовим:готовою}, твоя подорож почнеться. Твій шлях лежить до Зачумлених земель, де ти зустрінешся з Джезібою.\n\nВін смертний, мудрий, як древні, і терплячий, як сама земля. Ти знайдеш його в Андоралі.", [3] = "Поговоріть з Джезібою у Зачумлених землях. Він мешкає в Андоралі.", [5] = "Я Джезіба, багатьом відомий як Скульптор. Проте витісую я не статуї, а героїв.", ["en"] = "Wrath of the Blue Flight" },
    [5163] = { [1] = "Механічні єті!", [2] = "Все готово, {ім'я}!\n\nЯ вже відправила листи своїм друзям, повідомивши їх, що маю для них сюрприз. І тут на сцену виходиш ти!\n\nЯ дам тобі свого механічного єті, а ти {стать:повинен:повинна} зробити їм сюрприз, відвідавши кожного з моїх друзів, увімкнувши єті та відправивши його до них.\n\nПісля того, як ти покажеш його Леґакі в Завшегляді, Бризківці в Пристроблясі та Квіксілю в притулку Маршала, повернись і розкажи мені, як все пройшло!\n\nІ, будь ласка, не забудь повернути мені єті.", [3] = "Візьміть механічного єті Умі та лякайте ним її друзів:\n\nЛеґакі в Завшегляді (Зимоключ)\nБризківку у Пристроблясі (Танаріс)\nКвіксіль у прихистку Маршала (кратер Ун'Ґоро)\n\nКоли закінчите, поверніть механічного єті Умі.", [4] = "Не можу дочекатися, щоб почути реакцію моїх друзів!\n\nВони цього не очікують!", [5] = "Ха! Вони двічі подумають, перш ніж знову висміювати мої ідеї!\n\nДякую за допомогу, {ім'я}. Без тебе мені б не було так весело!", ["en"] = "Are We There, Yeti?", ["tasks"] = { ["Scare Legacki"] = "Скар Легацький", ["Scare Legacki (Provided)"] = "Скар Легацький (видано)", ["Scare Legacki slain"] = "Скар Легацький: убито", ["Scare Quixxil"] = "Налякати Квіксіла", ["Scare Quixxil (Provided)"] = "Налякати Квіксіла (видано)", ["Scare Quixxil slain"] = "Налякати Квіксіла: убито", ["Scare Sprinkle"] = "Налякати посипання", ["Scare Sprinkle (Provided)"] = "Налякати посипання (видано)", ["Scare Sprinkle slain"] = "Налякати посипання: убито", ["Umi's Mechanical Yeti"] = "механічний єті Умі", ["Umi's Mechanical Yeti (Provided)"] = "механічний єті Умі (видано)" } },
    [5164] = { [1] = "Журнал заблудлого", [2] = "Кращого знаряддя для правосуддя Гале не могла обрати. Прочитай цей журнал заблудлого та здобудь просвітлення.\n\nЯкщо ти вистоїш... Якщо зробиш те, про що тебе попросили... І якщо виживеш... Ти станеш {стать:героєм:героїнею}.", [3] = "Прочитайте журнал заблудлого.", [5] = "Книжка здебільшого містить сотні сторінок, розписаних дивними словами й символами.", ["en"] = "Catalogue of the Wayward" },
    [5165] = { [1] = "Гасіння захисного полум'я", [2] = "Тепер тобі потрібно повернутися в Джеденар. Жаровні, мабуть, розташовані по всьому оплоту Тіні. Загаси водою з кожну з них, і захист, що створила Рада, впаде принаймні на деякий час. Я чекатиму, коли це станеться, а потім загляну в оплот Тіні та спробую з'ясувати, хто очолює цю секту. Потім ми подумаємо про те, щоб нарешті напасти на них.", [3] = "Використовуючи очищену воду місячного колодязя, загасіть полум'я чотирьох жаровень захисту в оплоті Тіні у Скверноліссі, а потім поверніться до Ґрети Мохового Копита в Смарагдовий прихисток.", [4] = "Жаровні мають бути погашені, якщо ми хочемо бути готовими до битви. Заходити в лігво дракона без жодних знань — дурна справа. А тут все гірше, ніж з драконом. Члени Тіньової Ради несуть відповідальність за безліч злочинів і звірств. Нам доведеться діяти швидко, якщо ми хочемо їх зупинити.", [5] = "Я побачила тебе за допомогою своєї магії, щойно згасло полум'я останньої жаровні. Молодець, {ім'я}.\n\nЯ дізналася кілька речей до того, як чаклуни Тіньової Ради змогли відновити захист. Сподіваюсь, цього буде достатньо.\n\nА поки відпочинь. Я розповім тобі, що я дізналась, за мить.", ["en"] = "Dousing the Flames of Protection", ["tasks"] = { ["Extinguish the Brazier of Hatred"] = "Загасіть жаровню ненависті", ["Extinguish the Brazier of Hatred (Provided)"] = "Загасіть жаровню ненависті (видано)", ["Extinguish the Brazier of Hatred slain"] = "Загасіть жаровню ненависті: убито", ["Extinguish the Brazier of Malice"] = "Загасіть жаровню злоби", ["Extinguish the Brazier of Malice (Provided)"] = "Загасіть жаровню злоби (видано)", ["Extinguish the Brazier of Malice slain"] = "Загасіть жаровню злоби: убито", ["Extinguish the Brazier of Pain"] = "Загасіть жаровню болю", ["Extinguish the Brazier of Pain (Provided)"] = "Загасіть жаровню болю (видано)", ["Extinguish the Brazier of Pain slain"] = "Загасіть жаровню болю: убито", ["Extinguish the Brazier of Suffering"] = "Загасіть жаровню страждань", ["Extinguish the Brazier of Suffering (Provided)"] = "Загасіть жаровню страждань (видано)", ["Extinguish the Brazier of Suffering slain"] = "Загасіть жаровню страждань: убито" } },
    [5166] = { [1] = "Кіраса хроматичного крила", [2] = "Для виготовлення потужної кіраси, що покликана захищати від хроматичних драконів, знадобляться їхні власні шкури. Яка іронія.\n\nБлискучі хроматичні луски нашиваються на бездоганний панцир хроматичного дракона. Таких звірів нібито більше не існує, і ми маємо сподіватися, що вони більше ніколи не з'являться.\n\nОстанній, мабуть, найскладніший з усіх компонентів — кров героїв.\n\nСкульптор має викувати це творіння.", [3] = "Щоб викувати кірасу хроматичного крила, вам потрібно принести Джезібі-Скульптору наступні предмети:\n\n1 хроматичний панцир.\n\n10 блискучих хроматичних лусок.\n\n10 порцій крові героїв.\n\n10 зотлілих стібків потвори.", [4] = "Ти {стать:вибрав:вибрала}... мудро, {раса:к}.", [5] = "Невже ти не {стать:зрозумів:зрозуміла}? Сам шлях і був ціллю. Невже ти не відчуваєш ці бойові шрами? Біль, якого ти {стать:зазнав:зазнала}?\n\nПереживши випробування, ти {стать:став:стала} сильнішим створінням. Набагато сильнішим. Ця кіраса відображає твою внутрішню силу.", ["en"] = "Breastplate of the Chromatic Flight", ["tasks"] = { ["Blood of Heroes"] = "кров героїв", ["Blood of Heroes (Provided)"] = "кров героїв (видано)", ["Brilliant Chromatic Scale"] = "блискуча хроматична луска", ["Brilliant Chromatic Scale (Provided)"] = "блискуча хроматична луска (видано)", ["Chromatic Carapace"] = "хроматичний панцир", ["Chromatic Carapace (Provided)"] = "хроматичний панцир (видано)", ["Frayed Abomination Stitching"] = "зотлілий стібок потвори", ["Frayed Abomination Stitching (Provided)"] = "зотлілий стібок потвори (видано)" } },
    [5167] = { [1] = "Ножні лати хроматичного воїна", [2] = "Для основи ножних лат знадобиться панцир зрілого хроматичного дракона. На ній закріплюються блискучі хроматичні луски та зачаровуються кров'ю героїв. Наприкінці лати обтягуються зсередини еластичною шкірою тіні.", [3] = "Щоб викувати ножні лати хроматичного воїна, вам потрібно принести Джезібі-Скульптору наступні предмети:\n\n1 хроматичний панцир.\n\n10 блискучих хроматичних лусок.\n\n10 порцій крові героїв.\n\n5 шкір тіні.", [4] = "Таку річ іще ніхто не робив!", [5] = "Щойно ти увійдеш до їхніх залів, вони відчують запах своїх полеглих родичів, {ім'я}. Нехай їхній страх допоможе тобі знищити їх!", ["en"] = "Legplates of the Chromatic Defier", ["tasks"] = { ["Blood of Heroes"] = "кров героїв", ["Blood of Heroes (Provided)"] = "кров героїв (видано)", ["Brilliant Chromatic Scale"] = "блискуча хроматична луска", ["Brilliant Chromatic Scale (Provided)"] = "блискуча хроматична луска (видано)", ["Chromatic Carapace"] = "хроматичний панцир", ["Chromatic Carapace (Provided)"] = "хроматичний панцир (видано)", ["Skin of Shadow"] = "шкіра тіні", ["Skin of Shadow (Provided)"] = "шкіра тіні (видано)" } },
    [5168] = { [1] = "Герої Дарроушира", [2] = "Герої Дарроушира займають особливе місце у моєму серці і книга, яку ти мені {стать:приніс:принесла} — літопис Дарроушира, розповідає їхні історії.\n\nУ ній розповідається про паладина Дейвіла Сяйносвіта, і про те, як Багряний Похід забрав його манускрипт до ратуші Вогнедолу.\n\nТут також йдеться про мого брата, капітана Редпата. Після його зради, його щит розбили, і тепер він лежить у найнесподіванішому місці — біля комори Посухи Ґаррона.\n\nЗабери ці реліквії, {ім'я}. Трагічна доля пов'язує їх.", [3] = "Принесіть Карліну Редпату манускрипт Дейвіла та щит Редпата.", [4] = "Ти {стать:знайшов:знайшла} реліквії, {ім'я}?", [5] = "Ти {стать:знайшов:знайшла} манускрипт та щит!\n\nЇхня історія переплетена з історією Дарроушира, і я чомусь впевнений, що доля знову об'єднає їх.", ["en"] = "Heroes of Darrowshire", ["tasks"] = { ["Davil's Libram"] = "манускрипт Дейвіла", ["Davil's Libram (Provided)"] = "манускрипт Дейвіла (видано)", ["Redpath's Shield"] = "щит Редпата", ["Redpath's Shield (Provided)"] = "щит Редпата (видано)" } },
    [5181] = { [1] = "Лиходії Дарроушира", [2] = "В літописі Дарроушира згадується про лиходіїв цієї битви. У ньому розповідається про те, як сили Альянсу знищили повелителя гулів, Горґуса-Спустошника. Його тіло викинули в озеро, на північному заході перехрестя Коріна, а його череп досі лежить там.\n\nМардук Чорний так і не був переможений, але його легендарний меч був розбитий та втрачений. Він лежить на дні ущелини на захід від перехрестя Коріна.\n\nЗабери ці речі, {ім'я}. Я не знаю чому, але я впевнений, що твоя доля пов'язана з ними.", [3] = "Принесіть череп Горґуса та розбитий меч Мардука до Карліна Редпата в Каплицю Надії Світла.", [4] = "Тобі вдалося знайти череп та меч, {ім'я}?", [5] = "Ти {стать:знайшов:знайшла} їх! Чудово, {ім'я}! Ці реліквії містять в собі силу, яку я не повністю розумію, але яку ти колись приборкаєш.\n\nОднак вони також приносять мені сумні спогади про смерть, зраду та останню ніч Дарроушира...", ["en"] = "Villains of Darrowshire", ["tasks"] = { ["Shattered Sword of Marduk"] = "розбитий меч Мардука", ["Shattered Sword of Marduk (Provided)"] = "розбитий меч Мардука (видано)", ["Skull of Horgus"] = "череп Горґуса", ["Skull of Horgus (Provided)"] = "череп Горґуса (видано)" } },
    [5202] = { [1] = "Дивний червоний ключ", [2] = "Невеликий червоний ключ, здається, зроблений з якогось кістяного матеріалу. Він важкий, але здається дуже крихким. Для чого він був потрібен члену Тіньової Ради? Можливо, в Джеденарі є щось, що цей ключ може відкрити.", [3] = "Огляньте Джеденар, щоб дізнатися, для чого потрібен криваво-червоний ключ.", [4] = "Я починаю сумніватися, чи зможу я коли-небудь вирватися з цієї клітки.\n\nРано чи пізно вони принесуть мене в жертву демонам, яким вони поклоняються. Чудовиська!", [5] = "Ключ, ти {стать:знайшов:знайшла} його! Будь ласка, віддай його мені, і я нарешті зможу втекти!", ["en"] = "A Strange Red Key", ["tasks"] = { ["Blood Red Key"] = "криваво-червоний ключ", ["Blood Red Key (Provided)"] = "криваво-червоний ключ (видано)" } },
    [5203] = { [1] = "Порятунок з Джеденара", [2] = "Хоча мені дуже болісно, є одна річ, яку потрібно зробити перш за все: мені потрібно знайти меч Трея Світлогарта та втекти з оплоту Тіні, щоб повідомити моїх командирів про те, що тут трапилося. Ти допоможеш мені, {ім'я}?\n\nНаше спорядження неподалік звідси, і ти вже {стать:довів:довела}, що {стать:здатний:здатна} вибратися нагору.\n\nПісля того, як ми втечемо звідси, я вирушу в Дарнас, якщо ти зможеш знайти мою подругу Жезір біля кордону з Ясенедолом. Вона мала зустрітися з нами біля табору Смарагдового Кола неподалік звідси.\n\nЩо скажеш, {ім'я}? Чи зможеш ти знову допомогти мені?", [3] = "Проведіть Арко'нарін до місця, де знаходиться Світлогарт та її спорядження, а потім захищайте її під час втечі з оплоту Тіні. Після цього знайдіть Лукомісяць у Скверноліссі, щоб повідомити їй про те, що сталося з її друзями.", [4] = "Виглядаєш {стать:знервованим:знервованою}, {ім'я}. З тобою все гаразд, чи щось не так?", [5] = "То це ти {стать:допоміг:допомогла} Арко втекти? Я дуже рада, що ти мене {стать:знайшов:знайшла}. Вона проходила тут не так давно на шляху в Дарнас. У неї був меч Світлогарта, і в неї не було часу поговорити з друїдами, щоб ті її зцілили. Казала, що справа надто невідкладна.\n\nАле вона розповіла мені про твою зустріч із духом Трея. Яка жахлива доля для лицаря Сріблястої Десниці. Вона не показувала цього, але я знаю, що її душа розривається від втрати одного з її найближчих друзів.", ["en"] = "Rescue From Jaedenar", ["tasks"] = { ["Protect Arko'narin out of Shadow Hold"] = "Захистіть Арко'нарін від Тіньової фортеці" } },
    [5204] = { [1] = "Відплата Світла", [2] = "Вона вдає, що з нею все гаразд. Вона хотіла б, щоб я думала, що вона достатньо сильна, щоб впоратися з усім цим самостійно, але я знаю краще. Смерть Трея та його крики від тортур ще довго будуть переслідувати її, і ми не зможемо допомогти їй з цим. Але ми можемо дати їй трохи спокою!\n\n{ім'я}, повернись до оплоту Тіні, убий катів Трея та знайди його останки. Немає жодної причини, чому ми не можемо покінчити з цим, поки Арко'нарін оплакує загибель по-своєму?", [3] = "Поверніться до Джеденару і вбийте сукуба Ракайю, перш ніж знайти останки Трея Світлогарта.", [4] = "Ви оглядаєте тіло, без сумніву, це залишки лицаря Сріблястої Десниці, Трея Світлогарта. На мить ви думаєте про Арко'нарін і запитуєте себе, чи є хтось у вашому житті, хто значив би для вас стільки, скільки цей чоловік значив для нічної ельфи, якій ви нещодавно допомогли втекти з оплоту Тіні.\n\nЗібравшись з думками, ви розумієте, що не можете віднести останки паладина назад до Жезіри, не вбивши його катів.", [5] = "Ви якомога обережніше збираєте останки паладина, усвідомлюючи, що хоча б його дух вільний від мук, яким його піддавали.", ["en"] = "Retribution of the Light", ["tasks"] = { ["Rakaiah"] = "Ракайя", ["Rakaiah slain"] = "Ракайя: убито" } },
    [5205] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [5206] = { [1] = "Мародери Дарроушира", [2] = "Хромі сказала, що зібрані тобою реліквії, є реагентами для могутнього заклинання. Однак знадобиться ще один реагент — черепи воїнів Скари, які брали участь в битві при Дарроуширі.\n\nВізьми цей кристал, вбий чемпіонів Скари та забери їх черепи. Кристал зачарований: якщо чемпіон брав участь у битві, він буде резонувати коли ти піднесеш його до черепа. Принеси мені ці резонівні черепи.\n\nЙди, {ім'я}. Ти зможеш знайти чемпіонів Скари на Отруйній галявині, що на півночі, та в Грибковій долині на заході.", [3] = "Принесіть 5 резонівних черепів та загадковий кристал Карліну Редпату в Східні Зачумлені землі.", [4] = "Ти {стать:знайшов:знайшла} черепи? Хромі сказала, що вони критично важливі для її заклинання, яке дасть нам шанс врятувати Дарроушир.", [5] = "Ти {стать:знайшов:знайшла} їх! Чудово!\n\nХоча я не повністю розумію, як вони нам допоможуть, я відчуваю їх силу та точно знаю, що вони пов'язані з Дарроуширом.", ["en"] = "Marauders of Darrowshire", ["tasks"] = { ["Mystic Crystal"] = "загадковий кристал", ["Mystic Crystal (Provided)"] = "загадковий кристал (видано)", ["Resonating Skull"] = "резонівний череп", ["Resonating Skull (Provided)"] = "резонівний череп (видано)" } },
    [5207] = { [1] = "<NYI> <TXT> Справжній Закликач", ["en"] = "<NYI> <TXT> The True Summoner" },
    [5208] = { [1] = "<NYI> <TXT> Благословення зла", ["en"] = "<NYI> <TXT> The Blessing of Evil" },
    [5209] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [5210] = { [1] = "Брат Карлін", [2] = "Літопис Дарроушира, завдяки моїй магії, отримав сторінки в кінці, і тепер він продовжує свою історію після битви. Один з уривків розповідає про ще одного Редпата, Карліна, який пережив зраду Джозефа. Зараз Карлін перебуває на сході Зачумлених земель, у каплиці Надії Світла.\n\nВирушай туди й передай йому цю книгу.", [3] = "Принесіть доповнений літопис Дарроушира до Карліна Редпата у Східні Зачумлені землі.", [4] = "Ти {стать:прийшов:прийшла} з заходу? Як живеться решті Лордерону? Я знаю, що Андорал втрачено, але чи дісталася Скара до Тірісфаля?", [5] = "Що це за книга? Літопис Дарроушира? Я жив там до війни... війни, що знищила його! Навіщо ти {стать:приніс:принесла} мені цю книгу?\n\nАле поглянь сюди! Тут, в кінці книги, є сторінки, що розповідають про дні після битви! Тут йдеться і про мене! І про мого брата Джозефа! Невже це правда?\n\nЯ маю знати!", ["en"] = "Brother Carlin", ["tasks"] = { ["Extended Annals of Darrowshire"] = "доповнений літопис Дарроушира", ["Extended Annals of Darrowshire (Provided)"] = "доповнений літопис Дарроушира (видано)" } },
    [5211] = { [1] = "Захисники Дарроушира", [2] = "Багато захисників Дарроушира загинули у битві. І більшість з них блукають у вигляді привидів, прислужників Скари! Відшукай ці нещасні душі та припини їхні страждання!\n\nВбивай гулів-канібалів, бурмотливих гулів та хворих живодерів. Більшість цих монстрів раніше були добрими жителями Дарроушира. Знищивши їхні тіла, ти звільниш їхні душі.\n\nТи знайдеш їх в Чумоліссі, на перехресті Коріна та в інших місцях Східних Зачумлених земель, захоплених Скарою.", [3] = "Звільніть 15 духів Дарроушира та поверніться до Карліна Редпата.", [4] = "Бідолашні захисники Дарроушира приходять до мене у снах, {ім'я}. Ти маєш звільнити їх!", [5] = "Радий чути, що тобі вдалося відшукати замучені душі моїх побратимів та звільнити їх. Моє серце буде менше обливатися кров'ю, розуміючи, що більшість захисників Дарроушира більше не перебуватимуть в рабстві Скари.", ["en"] = "Defenders of Darrowshire", ["tasks"] = { ["Darrowshire Spirits Freed"] = "Звільнені духи Дарроуширу", ["Darrowshire Spirits Freed (Provided)"] = "Звільнені духи Дарроуширу (видано)", ["Darrowshire Spirits Freed slain"] = "Звільнені духи Дарроуширу: убито" } },
    [5212] = { [1] = "Плоть не бреше", [2] = "Аптекарі відречених — не є єдині істоти в цьому світі, що займаються наукою.\n\nЯ вивчала чуму протягом багатьох років, {раса:к}. Раніше ми думали, що чума з часом слабшає, але те, що ми відкрили в Зачумлених краях, нас приголомшило. Здається, чума стає лише сильнішою!\n\nМені потрібно провести більше досліджень! Найкращим джерелом чуми є гнилісна плоть нещодавно заражених. Вирушай до Стратгольму і принеси мені зразки, {ім'я}.", [3] = "Добудьте 20 зразків зачумленої плоті з істот Стратгольма і поверніться з ними до Бетіни Біґґльзінк.", [4] = "Дехто каже, що я занадто багато хвилююся, але це вони хвилюються недостатньо!", [5] = "Схоже, що щось змінило хімічну структуру збудника чуми. Потрібно більше даних.", ["en"] = "The Flesh Does Not Lie", ["tasks"] = { ["Plagued Flesh Sample"] = "зразок зачумленої плоті", ["Plagued Flesh Sample (Provided)"] = "зразок зачумленої плоті (видано)" } },
    [5213] = { [1] = "Збудник чуми", [2] = "Тобі доведеться відправитися в глибини Стратгольма, {ім'я}.\n\nЗа першими воротами ти знайдеш зикурати. Ми знаємо, що Скара черпає велику силу з цих споруд. Обшукай зикурати та повернись будь-якими даними, що там знайдеш.", [3] = "Відправляйтесь до Стратгольму та обшукайте зикурати. Знайдіть нові дані про Скару та поверніться з ними до Бетіни Біґґльзінк.", [4] = "Ми на порозі відкриття того, чим може бути цей новий збудник чуми!", [5] = "Дивовижно! Мені знадобиться кілька місяців на те, щоб проаналізувати все це. Сріблястий Світанок дякує тобі за твої зусилля, {ім'я}.\n\nТи можеш отримати печатку чи руну Світанку, на твій вибір. Можеш використовувати її замість стандартного жетона Сріблястого Світанку, щоб збирати камені Скари. Якщо ти загубиш її, поговори зі мною, і зможеш отримати нову.", ["en"] = "The Active Agent", ["tasks"] = { ["Scourge Data"] = "дані про Скару", ["Scourge Data (Provided)"] = "дані про Скару (видано)" } },
    [5214] = { [1] = "Великий Езра Ґрімм", [2] = "Те, що сталося з Езрою, воістину жахливо. Скара нищила місто, але Езра не хотів покидати свою тютюнову крамницю. Останнє, що він сказав мені: \"Я спалю все до останнього листочка, але не дозволю їм чіпати його своїми брудними ручиськами!!!\".\n\nЯ полюбляю гарний тютюн, але я не дурень. Того дня я покинув Езру і його прекрасну крамницю. Певно вона згоріла разом з ним, але, можливо, хоч щось вціліло....\n\nЩо скажеш, {ім'я}? Знайдеш тютюн для старого Димня?", [3] = "Знайдіть тютюнову крамницю Езри Ґрімма в Стратгольмі та дістаньте преміальний тютюн Ґрімма. Поверніться з ним до Димня ЛаРу.", [4] = "Я вже не витримую, {ім'я}! Ти маєш мені допомогти! Ох, я зараз помру!", [5] = "О, мій милий, прекрасний тютюн, як я за тобою сумував...", ["en"] = "The Great Ezra Grimm", ["tasks"] = { ["Siabi's Premium Tobacco"] = "Преміальний тютюн Siabi", ["Siabi's Premium Tobacco (Provided)"] = "Преміальний тютюн Siabi (видано)", ["Siabi's Premium Tobacco slain"] = "Преміальний тютюн Siabi: убито" } },
    [5218] = { [1] = "Котел Сквернокам'яного поля", [4] = "Перед вами стоїть чумний котел Скари, який випускає у повітря величезну кількість отруйних випарів. Біля масивної основи котла розташована невелика панель доступу.\n\nЗдолавши хранителя котла та отримавши його ключ, ви можете додати до котла реагенти, необхідні для знешкодження чуми.", [5] = "Після додавання реагентів до котла, ви бачите, як колір суміші починає змінюватися разом з виглядом випарів. Сили Скари, що стояли поруч, з жахом тікають від випарів нової суміші.", ["en"] = "Felstone Field Cauldron", ["tasks"] = { ["Arcane Quickener"] = "арканічний прискорювач", ["Arcane Quickener (Provided)"] = "арканічний прискорювач (видано)", ["Osseous Agitator"] = "кістяний каталізатор", ["Osseous Agitator (Provided)"] = "кістяний каталізатор (видано)", ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [5221] = { [1] = "Котел Сліз Дальсона", [4] = "Перед вами стоїть чумний котел Скари, який випускає у повітря величезну кількість отруйних випарів. Біля масивної основи котла розташована невелика панель доступу.\n\nЗдолавши хранителя котла та отримавши його ключ, ви можете додати до котла реагенти, необхідні для знешкодження чуми.", [5] = "Після додавання реагентів до котла, ви бачите, як колір суміші починає змінюватися разом з виглядом випарів. Сили Скари, що стояли поруч, з жахом тікають від випарів нової суміші.", ["en"] = "Dalson's Tears Cauldron", ["tasks"] = { ["Arcane Quickener"] = "арканічний прискорювач", ["Arcane Quickener (Provided)"] = "арканічний прискорювач (видано)", ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)", ["Somatic Intensifier"] = "соматичний підсилювач", ["Somatic Intensifier (Provided)"] = "соматичний підсилювач (видано)" } },
    [5224] = { [1] = "Котел Крученого Привида", [4] = "Перед вами стоїть чумний котел Скари, який випускає у повітря величезну кількість отруйних випарів. Біля масивної основи котла розташована невелика панель доступу.\n\nЗдолавши хранителя котла та отримавши його ключ, ви можете додати до котла реагенти, необхідні для знешкодження чуми.", [5] = "Після додавання реагентів до котла, ви бачите, як колір суміші починає змінюватися разом з виглядом випарів. Сили Скари, що стояли поруч, з жахом тікають від випарів нової суміші.", ["en"] = "Writhing Haunt Cauldron", ["tasks"] = { ["Arcane Quickener"] = "арканічний прискорювач", ["Arcane Quickener (Provided)"] = "арканічний прискорювач (видано)", ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)", ["Somatic Intensifier"] = "соматичний підсилювач", ["Somatic Intensifier (Provided)"] = "соматичний підсилювач (видано)" } },
    [5227] = { [1] = "Котел Посухи Ґаррона", [4] = "Перед вами стоїть чумний котел Скари, який випускає у повітря величезну кількість отруйних випарів. Біля масивної основи котла розташована невелика панель доступу.\n\nЗдолавши хранителя котла та отримавши його ключ, ви можете додати до котла реагенти, необхідні для знешкодження чуми.", [5] = "Після додавання реагентів до котла, ви бачите, як колір суміші починає змінюватися разом з виглядом випарів. Сили Скари, що стояли поруч, з жахом тікають від випарів нової суміші.", ["en"] = "Gahrron's Withering Cauldron", ["tasks"] = { ["Arcane Quickener"] = "арканічний прискорювач", ["Arcane Quickener (Provided)"] = "арканічний прискорювач (видано)", ["Ectoplasmic Resonator"] = "ектоплазматичний резонатор", ["Ectoplasmic Resonator (Provided)"] = "ектоплазматичний резонатор (видано)", ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [5241] = { [1] = "Дядько Карлін", [2] = "Іноді, коли стає темно, я чую плач свого дядька Карліна. Звучить так, ніби він дуже далеко, на сході.\n\nЯ сподіваюся, що він плаче не через мене! {ім'я}, будь ласка, розшукай мого дядька та скажи йому, що зі мною все гаразд.\n\nЯкщо знайдеш його, скажи, що я чекаю на нього, і дуже сумую за казками, які він розповідав мені на ніч... особливо за тією, про кроликів та варення! Вона така кумедна!", [3] = "Відшукайте Карліна Редпата.", [5] = "Ти {стать:бачив:бачила} Памелу? Вона жива?\n\nВона мертва? Ні! О, Памела! Чому твій дух досі страждає у цьому світі? Чому ти мусила загинути, а я досі топчу цю землю? Як би я хотів віддати життя замість тебе і вештатись руїнами Дарроушира!\n\nЕх, долю не змінити. Дякую, {ім'я}. Тепер мій обов'язок — помста, я усвідомлюю це ясно, як ніколи.", ["en"] = "Uncle Carlin" },
    [5242] = { [1] = "Останній удар", [2] = "На жаль, єдиний спосіб зупинити цю загрозу для Сквернолісся — це лобова атака. Інших шляхів в оплот Тіні немає, і я не маю можливості телепортувати тебе всередину. Прямий шлях в глибини оплоту — це єдиний шлях... і я знаю, кого тобі слід шукати. Його звуть Фел'дан... лорд тіней Фел'дан. Він — смертний, що має владу там, внизу... він — голова цього змія. Убий його і двох його слуг-сукубів і повертайся до мене. Це Фел'дан укладає угоди з Легіоном. Його треба зупинити.", [3] = "Вбийте Муру та Салію і принесіть голову лорда тіней Фел'дана Ґреті Моховому Копиту у Сквернолісся.", [4] = "Без Фел'дана Тіньова Рада втратить обачність і буде безпорадною. Вони боротимуться одне з одним за владу і скарби. Це буде слушний час, щоб вирізати їх та їхніх демонічних рабів.", [5] = "Слава Матері-Землі, {ім'я}! Дякую! Це дійсно великий день!\n\nПісля такого удару Тіньовій Раді буде важко досягти колишнього рівня влади. Сьогодні ти {стать:зробив:зробила} велику справу!", ["en"] = "A Final Blow", ["tasks"] = { ["Moora"] = "Мура", ["Moora slain"] = "Мура: убито", ["Salia"] = "Салія", ["Salia slain"] = "Салія: убито", ["Shadow Lord Fel'dan's Head"] = "голова лорда тіней Фел'дана", ["Shadow Lord Fel'dan's Head (Provided)"] = "голова лорда тіней Фел'дана (видано)" } },
    [5243] = { [1] = "Осередки святості", [2] = "Я дивлюся на свою невмерлість як на хворобу, {раса:к}. Ця хвороба потребує втручання, однак вона також є великим благословенням для Сріблястого Світанку. Хіба може хтось вдарити по Скарі краще за невмерлого?\n\nЯ шанований своїми товаришами по ордену за мої жертви, проте почесті нічого не значать для мене.\n\nЯкщо ти хочеш допомогти Сріблястому Світанку, я можу запропонувати тобі роботу.\n\nВирушай в Стратгольм і знайди запаси святої води. Шукай її в ящиках з припасами.", [3] = "Відправляйтеся до Стратгольму, що на півночі. Обшукайте ящики з припасами, що розкидані по місту і знайдіть в них 5 пляшок стратгольмської святої води. Поверніться з ними до Леоніда Варфоломія Шанованого.", [4] = "Будь {стать:обережний:обережна}, не всі ящики залишилися цілими й неушкодженими після руйнування міста. Скара не наважиться її торкатися, але свята вода не відлякує шкідників.", [5] = "Молодець, {раса:к}. Ти {стать:проявив:проявила} свою терпимість до ближніх, і ніщо не зупинить тебе перед знищенням маріонеток Кел'Тузада", ["en"] = "Houses of the Holy", ["tasks"] = { ["Stratholme Holy Water"] = "стратгольмська свята вода", ["Stratholme Holy Water (Provided)"] = "стратгольмська свята вода (видано)" } },
    [5246] = { [1] = "Фрагменти минулого", [2] = "Я не усвідомлювала... Вибач мені за мої грубі слова, {клас:к}.\n\nПомилки моїх предків це останнє, про що я хочу згадувати, але твоє прохання справді щире, тож я допоможу тобі.\n\n<Аврора оглядає фрагменти.>\n\nЯ впевнена, що це кристал Зін-Малора, артефакт, який містить в собі та контролює потужну силу магії. Можливо, ця магія була використана для добрих справ, але злі сили, які викрали її, розкололи кристал.\n\nВідправляйся до храму Зін-Малор в Азшарі — я можу лише сподіватися на те, що книга все ще там.", [3] = "Знайдіть священні писання високородних у храмі Зін-Малор в Азшарі, і принесіть їх до Аврори Небоклич біля вежі Північного ходу у Східних Зачумлених землях.", [4] = "Тільки завдяки сторінкам священного писання я дізнаюсь, чи зможу я тобі допомогти...", [5] = "Цих сторінок роками ніхто не торкався...", ["en"] = "Fragments of the Past", ["tasks"] = { ["Sacred Highborne Writings"] = "священні писання високородних", ["Sacred Highborne Writings (Provided)"] = "священні писання високородних (видано)" } },
    [5247] = { [1] = "Фрагменти минулого", [2] = "Я зможу допомогти тобі, якщо ти справді хочеш відновити артефакт.\n\nЩоб об'єднати частини в одне ціле, мені знадобляться предмети з сильними магічними властивостями. Зачарований злиток торію та 5 кристалічних відновлень... Тобі також знадобиться набрати трохи води з дуже сумнівного місця... Знайди зловісний ставок на шляху до алеї Ельдрет в Грізному Молоті, що у Фераласі, і наповни цей флакон.\n\nПоки тебе не буде, я спробую щось дізнатися з цих сторінок, щоб відновити цю реліквію.", [3] = "Принесіть зачарований злиток торію, 5 кристалічних відновлень та флакон зі зловісною водою до Аврори Небоклич біля вежі Північного ходу в Східних Зачумлених землях.", [4] = "Реліквія має бути в руках того, хто заслуговує довіри. Вона не має бути викрадена знову...", [5] = "Використовуючи ці речі, я зможу об'єднати фрагменти в одне ціле... сподіваюся в те, чим вони були раніше.", ["en"] = "Fragments of the Past", ["tasks"] = { ["Crystal Restore"] = "кристалічне відновлення", ["Crystal Restore (Provided)"] = "кристалічне відновлення (видано)", ["Enchanted Thorium Bar"] = "зачарований злиток торію", ["Enchanted Thorium Bar (Provided)"] = "зачарований злиток торію (видано)", ["Vial of Dire Water"] = "флакон зі зловісною водою", ["Vial of Dire Water (Provided)"] = "флакон зі зловісною водою (видано)" } },
    [5248] = { [1] = "Змучені минулим", [2] = "{ім'я}, я сумую через те, що сталося у минулому. Як і цей кристал, раса ельфів була розбита на друзки. Я не знаю, чи зберуться коли-небудь ці уламки в одне ціле, але моя скорбота полегшиться, якщо я тобі допоможу з цим невеликим завданням.\n\nМи не повинні забувати минулого, {ім'я}...\n\nБудь ласка, поверни цей кристал Зін-Малора до озера Кел'Теріл. Ти маєш знайти високородного духа, який усвідомлює помилки минулого. Покажи духу, що ми все виправили.", [3] = "Принесіть кристал Зін-Малора до озера Кел'Теріл в Зимоключі та знайдіть високородного духа, який поговорить з вами.", [4] = "Проооклятааа... Навіііікиии...", [5] = "Прошуууу, облиииш менееее...", ["en"] = "Tormented By the Past", ["tasks"] = { ["Crystal of Zin-Malor"] = "кристал Зін-Малора", ["Crystal of Zin-Malor (Provided)"] = "кристал Зін-Малора (видано)" } },
    [5250] = { [1] = "Зорепад", [2] = "У Зимоключі, що на північ від Сквернолісся, є багато стародавніх ельфійських руїн. Це суворий край, але він зберігає багато таємниць і там вдосталь місць, які варто дослідити.\n\nЯ так зайнята своїми дослідженнями тут, що вже давно не бувала у Зимоключі. Та схоже, що ти можеш відправитись туди та дослідити тамтешні руїни.\n\nЯк дістанешся туди — знайди Вінда Ночесліда. Він проводить більшу частину свого часу в селищі Зорепад і багато знає про ту місцевість.\n\nСкажи йому, що ти {стать:мій учень:моя учениця}...", [3] = "Знайдіть селище Зорепад у Зимоключі та поговоріть з Віндом Ночеслідом.", [5] = "{стать:Учень:Учениця} Даріни Легковій? Радий познайомитись з тобою, {ім'я}.", ["en"] = "Starfall" },
    [5251] = { [1] = "Архіваріус", [2] = "Будь-які крайнощі є великим злом для нашого світу, {ім'я}. Ось, наприклад, Багряний Похід. Чи ти справді віриш, що ці сліпі фанатики служать вищому благу? Скількох невинних вони знищили в ім'я Світла?\n\nБогохульники, тьху на них, всі до одного!\n\nАле один з них мене особливо цікавить. Це архіваріус Ґалфорд зі Стратгольму. Він охороняє найцінніші документи Багряного Походу. Ліквідуй його і спали архіви! Якщо впораєшся, то повертайся... і отримаєш винагороду.", [3] = "Відправляйтесь до Стратгольму і знайдіть архіваріуса Ґалфорда з Багряного Походу. Ліквідуйте його і спаліть архів Багряного Походу.", [4] = "Пам'ятай, {ім'я}, ми повинні твердо відстоювати свої переконання, але без фанатизму!", [5] = "Неймовірно, {ім'я}! Все, що вони збирали роками — втрачено! Багряний Похід справді ще не скоро оговтається від такого удару.", ["en"] = "The Archivist", ["tasks"] = { ["Archive Burned"] = "Архів спалено", ["Archive Burned (Provided)"] = "Архів спалено (видано)", ["Archive Burned slain"] = "Архів спалено: убито", ["Archivist Galford"] = "архіваріус Ґалфорд", ["Archivist Galford slain"] = "архіваріус Ґалфорд: убито" } },
    [5252] = { [1] = "Розкаяна високородна", [2] = "Кристааал...\n\nВисокородні перебувають у полоні їх жалюгідного іссснування...\n\nЯ шкодую, але усвідомлюю помилку, яка сталася так давно. Хоча ми не можемо змінити минуле, я заспокоїлася, знаючи, що ти {стать:відновив:відновила} кристал Зін-Малора...\n\nТи маєш повернути його...\n\nВін мусииить бути повернутииий.", [3] = "Поговоріть з Віндом Ночеслідом у селищі Зорепад і дізнайтесь у нього, куди потрібно помістити кристал Зін-Малора.", [4] = "Минуло досить багато часу відколи ти {стать:пішов:пішла}, {ім'я}. Як твої справи?", [5] = "Це... те, про що я думаю?", ["en"] = "Remorseful Highborne", ["tasks"] = { ["Crystal of Zin-Malor"] = "кристал Зін-Малора", ["Crystal of Zin-Malor (Provided)"] = "кристал Зін-Малора (видано)" } },
    [5253] = { [1] = "Кристал Зін-Малора", [2] = "Вражає, {ім'я}.\n\nКристал Зін-Малора ніколи не повернеться в храм, який, як ти знаєш, лежить в руїнах. Але я вважаю, що твої зусилля не повинні залишитися без нагороди.\n\nЗнайди верховного друїда Фендрала Оленерога в Дарнасі, і віддай йому кристал, {ім'я}. Він має бути в руках тих, хто не буде зловживати його силою. Здається, що тільки найсильніші маги зможуть контролювати таку силу.", [3] = "Передайте кристал Зін-Малора верховному друїду Фендралу Оленерогу в Дарнасі.", [4] = "Так, {раса:к}?", [5] = "Я чув про кристал Зін-Малора. Його власник отримує практично необмежену магічну силу, але тільки якщо він гідний цього. Я вражений тим, що ти не тільки {стать:відновив:відновила} кристал, але й розумієш свої власні межі, і не {стать:спробував:спробувала} використати його {стать:сам:сама}.\n\nДякую, {ім'я}, що {стать:приніс:принесла} його мені. Ми будемо зберігати його у безпеці, і може прокляті духи, які колись охороняли розбитий кристал, нарешті знайдуть спокій.", ["en"] = "The Crystal of Zin-Malor", ["tasks"] = { ["Crystal of Zin-Malor"] = "кристал Зін-Малора", ["Crystal of Zin-Malor (Provided)"] = "кристал Зін-Малора (видано)" } },
    [526] = { [1] = "Злитки світлосталі", [2] = "Можливо, в тій скрині ти й {стать:знайшов:знайшла} один злиток світлосталі, але цього не достатньо, щоб створити щось гідне!\n\nТобі слід повернутися туди та знайти ще. Можливо, мурлоки поблизу розбитих кораблів мають злитки світлосталі при собі.", [3] = "Зберіть 5 злитків світлосталі, а потім поверніться до Ґлоріна Сталеброва в Заболоття.", [4] = "Ти {стать:знайшов:знайшла} злитки світлосталі?", [5] = "А, ти їх {стать:знайшов:знайшла}! Тепер перетворімо ці злитки світлосталі на щось корисне, га?", ["en"] = "Lightforge Ingots", ["tasks"] = { ["Lightforge Ingot"] = "злиток світлосталі", ["Lightforge Ingot (Provided)"] = "злиток світлосталі (видано)" } },
    [5262] = { [1] = "Приголомшлива правда", [2] = "Ви намагаєтеся зібратися з думками, поки пил осідає по кімнаті. Ви намагаєтеся зібратися з думками й не можете збагнути всю серйозність ситуації.\n\nВерховний лицар Багряного Походу — демон? І не просто демон, але брат самого Варіматраса, верховного лорда Підмістя?\n\nВи акуратно кладете відрізану голову повелителя жаху у сумку. Справді, ніхто вам не повірить без доказів.\n\nГерцог Ніколас Зверенгоф має про все дізнатись!", [3] = "Віднесіть голову Бальназара до герцога Ніколаса Зверенгофа в Східні Зачумлені землі.", [4] = "Що ти мені {стать:приніс:принесла}, {ім'я}?", [5] = "Що це означає? Невже весь цей час Багряним Походом підкорявся демонам? Вони несвідомо служили більшому злу!", ["en"] = "The Truth Comes Crashing Down", ["tasks"] = { ["Head of Balnazzar"] = "голова Бальназара", ["Head of Balnazzar (Provided)"] = "голова Бальназара (видано)" } },
    [5263] = { [1] = "Вище й сильніше", [2] = "Ти {стать:продемонстрував:продемонструвала} справжній хист до руйнування і ти вмієш виконувати накази. Рідко можна побачити ці дві риси в одному тілі. Можливо, з тебе вийде ідеальне знаряддя божественного правосуддя.\n\n<Зверенгоф зводить долоні перед собою.>\n\nКел'Тузад посадив свого хлопчика на побігеньках правити Стратгольмом. Доведи мені свою вірність і доблесть. Знищ барона Рівендера і повернись до мене з його головою.", [3] = "Відправляйтесь до Стратгольму і ліквідуйте барона Рівендера. Візьміть його голову і поверніться до герцога Ніколаса Зверенгофа.", [4] = "Барон знищив більше народу, ніж ти {стать:бачив:бачила} за все своє життя.", [5] = "Минуло багато років відтоді, як я приймав до наших лав чемпіонів. Ти {стать:перший:перша}, хто отримає аудієнцію у лорда Максвелла за багато років.", ["en"] = "Above and Beyond", ["tasks"] = { ["Head of Baron Rivendare"] = "голова барона Рівендера", ["Head of Baron Rivendare (Provided)"] = "голова барона Рівендера (видано)" } },
    [5264] = { [1] = "Лорд Максвелл Тірос", [2] = "Тобі надано велику честь, {ім'я}.\n\nЛорд Максвелл бажає нагородити тебе за твою службу Сріблястому Світанку!\n\nМинуло багато років з тої пори, як Максвелл дарував аудієнцію чужинцям.", [3] = "Поговоріть з лордом Максвеллом Тіросом. Він знаходиться всередині церкви.", [5] = "Ти {стать:гідний союзник:гідна союзниця}, {ім'я}. І ти пожнеш плоди своєї відданості.", ["en"] = "Lord Maxwell Tyrosus" },
    [5265] = { [1] = "Скарбниця Світанку", [2] = "Багато років Скарбниця Світанку залишалася зачиненою. Ніхто не був гідний заглянути всередину та отримати силу Сріблястого Світанку — до сьогоднішнього дня.\n\nТепер Скарбниця Світанку відчинена для тебе, {ім'я}.", [3] = "Відкрийте скарбницю Світанку та отримайте свою винагороду.", [5] = "Ого...", ["en"] = "The Argent Hold" },
    [5281] = { [1] = "Неупокоєні душі", [2] = "Падіння Стратгольму принесло безліч трагічних смертей. Багато хто вважав, що краще покінчити з життям і кинутися у полум'я пожежі, ніж приєднатися до Скари.\n\nТепер вони ходять вулицями Стратгольму у вигляді неупокоєних душ.\n\nМи повинні допомогти їм, {ім'я}!\n\nУ мене є приятель, на ім'я Іґан, який творить дивовижні речі з привидами та духами. Знайди його. Він певно знову блукає біля Стратгольму, випробовуючи свої винаходи.", [3] = "Знайдіть Іґана. Вам відомо лиш те, що востаннє його бачили біля Стратгольму.", [5] = "Ален нарешті знайшов сміливців, ге?", ["en"] = "The Restless Souls" },
    [5282] = { [1] = "Неупокоєні душі", [2] = "Я черпаю свою силу і волю до життя з нестримної ненависті до Скари. Але я не фанатик. Я не такий, як Багряний Похід, що знищить невинного невмерлого і не виявить ні крихти співчуття.\n\nДо чого це я. Моя рушниця. Вона звільнить замучені душі Стратгольму.\n\nСтріляй нею в примар, що блукають розореними вулицями. Звільни їхні душі.", [3] = "Використайте рушницю Іґана на примарних і спектральних жителях Стратгольму. Коли неупокоєні душі вирвуться з примарних оболонок, використайте рушницю знову — і вони здобудуть свободу!\n\nЗвільніть 15 неупокоєних душ і поверніться до Іґана.", [4] = "Співчуття — ось що відрізняє нас від звірів, {ім'я}. Пам'ятай про це....", [5] = "<Іґан витирає сльозу з ока.>\n\nТи {стать:бачив:бачила} мою матір, {ім'я}. Ти {стать:звільнив:звільнила} її душу?\n\nТи — приклад благородства. Прийме це на знак вдячності...", ["en"] = "The Restless Souls", ["tasks"] = { ["Souls Freed"] = "Звільнені душі", ["Souls Freed (Provided)"] = "Звільнені душі (видано)", ["Souls Freed slain"] = "Звільнені душі: убито" } },
    [5283] = { [1] = "Мистецтво виготовлення обладунків", [2] = "Ти {стать:прийняв:прийняла} розумне рішення.\n\nМи з цим старим Залізієм один одного не переварюємо. Цей нікчемний майстер виготовлення цяцьок знає, хто майкращий ремісник в сих краях.\n\nВеликі війни не виграют си без гарного обладунку. Коли дійде до справи, нієкий меч не врятує.\n\nТо, до роботи. Тобі лиш потрібно показати мені, що в тебе є талант. Тоді я витравлю з тебе всі хиби та викую з тебе {стать:майстра:майстриню} обладунків. Ти ж знаєш, їк робити вишуканий мітрил, ге?", [3] = "Щоб стати майстром обладунків, ви повинні виготовити такі предмети та принести їх Ґрумнусу: 4 вишукані мітрилові шоломи, 2 пари вишуканих мітрилових чобіт, 1 вишукану мітрилову кірасу.", [4] = "Ніщо не зрівняється з файною ковальською засмагою. Правильну засмагу одразу видно по білих смугах від фартуха.", [5] = "Се все, {ім'я}. Після сього шляху назад немає. Ще не пізно стати майстром цяцьок, зброярем.\n\nЯ вірю, що ти приймеш правильне рішення.", ["en"] = "The Art of the Armorsmith", ["tasks"] = { ["Ornate Mithril Boots"] = "вишукані мітрилові чоботи", ["Ornate Mithril Boots (Provided)"] = "вишукані мітрилові чоботи (видано)", ["Ornate Mithril Breastplate"] = "вишукана мітрилова кіраса", ["Ornate Mithril Breastplate (Provided)"] = "вишукана мітрилова кіраса (видано)", ["Ornate Mithril Helm"] = "вишуканий мітриловий шолом", ["Ornate Mithril Helm (Provided)"] = "вишуканий мітриловий шолом (видано)" } },
    [5284] = { [1] = "Шлях зброяра", [2] = "Як зброяр, ти часто отримуватимеш замовлення від всіляких героїв та мандрівників. Хоча робота може бути важкою й виснажливою, та плата більш ніж покриває всі ці незручності.\n\nО, так, {ім'я}, у зброярів завжди є вдосталь золота!\n\nЯкщо ти бажаєш стати {стать:одним:однією} з нас, тобі потрібно довести, що ти можеш заробити хоча б декілька срібних монет — тобто, показати, що ти знаєш все необхідне, щоб стати фахівцем з виготовлення зброї найвищої якості. До роботи!", [3] = "Щоб стати зброярем, ви повинні виготовити наступні предмети та принести їх Залізію: 4 палаші місяцесталі, 4 масивні залізні сокири, 2 важкі мітрилові сокири та 2 великі чорні булави.", [4] = "<Залізій зайнятий складанням золотих монет в акуратні маленькі стопки.>", [5] = "Якраз вчасно! На мене чекають клієнти.\n\nДавай їх сюди й слухай уважно. Ти зробиш перший крок у своїй кар'єрі зброяра.", ["en"] = "The Way of the Weaponsmith", ["tasks"] = { ["Big Black Mace"] = "велика чорна булава", ["Big Black Mace (Provided)"] = "велика чорна булава (видано)", ["Heavy Mithril Axe"] = "важка мітрилова сокира", ["Heavy Mithril Axe (Provided)"] = "важка мітрилова сокира (видано)", ["Massive Iron Axe"] = "масивна залізна сокира", ["Massive Iron Axe (Provided)"] = "масивна залізна сокира (видано)", ["Moonsteel Broadsword"] = "палаш з місяцесталі", ["Moonsteel Broadsword (Provided)"] = "палаш з місяцесталі (видано)" } },
    [53] = { [1] = "Солодке бурштинове", [2] = "Як дитяча сльоза, прозорий напій,\nЗ роками медовим стане настій.\nТа перш ніж спочити могли б ми сповна,\nНам бочка дубова потрібна міцна.", [3] = "Принесіть Лютобухові Громовару зв'язку обвугленого дуба.", [4] = "Звичайно, я знову її заспіваю тобі, друже!\n\nЯк дитяча сльоза, прозорий напій,\nЗ роками медовим стане настій.\nТа перш ніж спочити могли б ми сповна,\nНам бочка дубова потрібна міцна.", [5] = "Вугіллям фільтроване, дозріле у бочці\nЗапалює душу вам з кожним ковточком.\nТож вип'єм за тих, хто варив цей нектар -\nТи, звісно ж, і я, Лютобух Громовар!", ["en"] = "Sweet Amber", ["tasks"] = { ["Bundle of Charred Oak"] = "зв'язка обвугленого дуба", ["Bundle of Charred Oak (Provided)"] = "зв'язка обвугленого дуба (видано)" } },
    [5301] = { [1] = "Мистецтво виготовлення обладунків", [2] = "Задоволення. Ось що я відчуваю від молота і ковадла. Вигляд гордого воїна Орди, захищеного моєю сталлю — це те, що дарує мені жагу до життя. Це залежність, якої я ніколи не позбудусь, {ім'я}.\n\nЗвичайно, цього я тебе навчити не зможу — я можу тільки вказати тобі шлях. Адже шлях майстра виготовлення обладунків — це подорож, як і всі життєві шляхи.\n\nЯкщо ти хочеш бути {стать:одним:однією} з небагатьох обраних — лиш попроси, і я навчатиму тебе. Але спочатку ти {стать:повинен:повинна} виконати моє завдання.", [3] = "Щоб стати майстром обладунків, ви повинні виготовити такі предмети та принести їх Окотосу: 4 вишукані мітрилові шоломи, 2 пари вишуканих мітрилових чобіт, 1 вишукану мітрилову кірасу.", [4] = "Я буду кувати сталь до останнього подиху.", [5] = "Це останній крок перед тим, як ти почнеш свою нову кар'єру {стать:майстра:майстрині} обладунків, {ім'я}. Якщо ти вагаєшся — це твій останній шанс відмовитися. А інакше готуйся до вічної слави.", ["en"] = "The Art of the Armorsmith", ["tasks"] = { ["Ornate Mithril Boots"] = "вишукані мітрилові чоботи", ["Ornate Mithril Boots (Provided)"] = "вишукані мітрилові чоботи (видано)", ["Ornate Mithril Breastplate"] = "вишукана мітрилова кіраса", ["Ornate Mithril Breastplate (Provided)"] = "вишукана мітрилова кіраса (видано)", ["Ornate Mithril Helm"] = "вишуканий мітриловий шолом", ["Ornate Mithril Helm (Provided)"] = "вишуканий мітриловий шолом (видано)" } },
    [5302] = { [1] = "Шлях зброяра", [2] = "Одного дня я створю легендарний молот. Молот, гідний самого воєвождя!\n\nЦе моя мета всього життя, {ім'я}. Моє покликання. Я відчуваю, що ти маєш потенціал стати {стать:одним:однією} з нас, {стать:одним:однією} зі зброярів. Я той, хто може допомогти тобі розкрити цей потенціал.\n\nТобі потрібно виконати просте завдання. Просте, якщо ти досить {стать:майстерний:майстерна}.", [3] = "Щоб стати зброярем, ви повинні виготовити наступні предмети та принести їх Борґошу: 4 палаші з місяцесталі, 4 масивні залізні сокири, 2 важкі мітрилові сокири та 2 великі чорні булави.", [4] = "Слава Орді!", [5] = "Це останній крок перед тим, як ти почнеш свою нову кар'єру зброяра, {ім'я}. Якщо ти вагаєшся — це твій останній шанс відмовитися. А інакше готуйся до того, що знання поглинуть тебе!", ["en"] = "The Way of the Weaponsmith", ["tasks"] = { ["Big Black Mace"] = "велика чорна булава", ["Big Black Mace (Provided)"] = "велика чорна булава (видано)", ["Heavy Mithril Axe"] = "важка мітрилова сокира", ["Heavy Mithril Axe (Provided)"] = "важка мітрилова сокира (видано)", ["Massive Iron Axe"] = "масивна залізна сокира", ["Massive Iron Axe (Provided)"] = "масивна залізна сокира (видано)", ["Moonsteel Broadsword"] = "палаш з місяцесталі", ["Moonsteel Broadsword (Provided)"] = "палаш з місяцесталі (видано)" } },
    [5305] = { [1] = "Солодка безтурботність", [2] = "Всередині Багряного оплоту приховується солодка Безтурботність. Багряний коваль молотів стереже її креслення як зіницю ока. Вбий його і принеси мені його фартух. За це я відкрию тобі секрети кування молотів.\n\nТа пам'ятай, що коли обереш шлях коваля молотів, ти вже не зможеш стати ковалем мечів чи сокир.", [3] = "Відправляйтеся до Стратгольму і вбийте багряного коваля молотів. Заберіть фартух багряного коваля молотів та поверніться до Ліліт.", [4] = "Фартух! Де він?", [5] = "То ти {стать:впевнений:впевнена}, що це те, чого ти хочеш? Стати ковалем молотів? Пам'ятай, що можливість стати ковалем мечів чи сокир буде втрачена назавжди.", ["en"] = "Sweet Serenity", ["tasks"] = { ["Crimson Hammersmith's Apron"] = "фартух багряного коваля молотів", ["Crimson Hammersmith's Apron (Provided)"] = "фартух багряного коваля молотів (видано)" } },
    [5306] = { [1] = "Змієкамінь темної мисливиці", [2] = "Не дай її красі обманути себе, {клас:к}. Темна мисливиця Вош'ґаджин смертоносна і божевільна.\n\n<Кілрам показує на шрам на обличчі.>\n\nТак, вона дала мені це — любовний удар, як вона його називала.\n\nЧас помсти настав.\n\nТи можеш знайти Вош'ґаджин у Чорноскельному шпилі. Убий її та принеси мені її змієкамінь. Зроби це, і я навчу тебе майстерності кування сокир.", [3] = "Відправляйтеся до Чорноскельного шпиля і вбийте темну мисливицю Вош'ґаджин. Знайдіть змієкамінь Вош'ґаджин та поверніться до Кілрама.", [4] = "Легенда стверджує, що один раз використавши змієкамінь Вош'ґаджин, можна зберегти гостроту леза сокири на тисячу років!", [5] = "То ти {стать:впевнений:впевнена}, що це те, чого ти хочеш? Стати ковалем сокир? Пам'ятай, що можливість стати ковалем мечів чи молотів буде втрачена назавжди.", ["en"] = "Snakestone of the Shadow Huntress", ["tasks"] = { ["Vosh'gajin's Snakestone"] = "змієкамінь Вош'ґаджин", ["Vosh'gajin's Snakestone (Provided)"] = "змієкамінь Вош'ґаджин (видано)" } },
    [5307] = { [1] = "Порча", [2] = "Скажу коротко, на це є причини. Креслення великого меча \"Порча\" були викрадені Чорною Вартою — елітним загоном скелетів барона Рівендера.\n\nТак, барона Рівендера зі Стратгольма.\n\nЗброяр Чорної Варти тепер захищає ці креслення, тож їх можна забрати лиш через його... труп.\n\nВбий його і принеси доказ його смерті, і я навчу тебе секретів кування мечів.", [3] = "Знайдіть у Стратгольмі зброяра Чорної Варти та вбийте його. Візьміть його знак Чорної Варти та принесіть Серілу Скаробою.", [4] = "Ти {стать:забув:забула}, що тобі було доручено, {ім'я}?", [5] = "То ти {стать:впевнений:впевнена}, що це те, чого ти хочеш? Стати ковалем мечів? Пам'ятай, що можливість стати ковалем молотів чи сокир буде втрачена назавжди.", ["en"] = "Corruption", ["tasks"] = { ["Insignia of the Black Guard"] = "знак Чорної Варти", ["Insignia of the Black Guard (Provided)"] = "знак Чорної Варти (видано)" } },
    [531] = { [1] = "Помста Вірен", [2] = "Світло! Не принось таке в нашу оселю... це негігієнічно, несказанно... е... еее... негігієнічно!\n\nПросто забери це звідси, добре? Нікому не потрібен цей твій бридкий трофей, чесно!", [3] = "Віддайте Вірен Стрімковій з оселі Далекоходців голову старого Чорниша.", [4] = "Чудово, {ім'я}! Ми добре провчили його! Давай мені цю голову, я подбаю про неї.", [5] = "Дякую за допомогу, {ім'я}. Я давно хотіла провчити цього дурного, пихатого хлопчину і нам це непогано так вдалось! Ось, це тобі, ти {стать:заслужив:заслужила}.", ["en"] = "Vyrin's Revenge", ["tasks"] = { ["Ol' Sooty's Head"] = "голова старого Чорниша", ["Ol' Sooty's Head (Provided)"] = "голова старого Чорниша (видано)" } },
    [5344] = { [1] = "Останній Баров", [2] = "Документи в моїх руках, але залишається іще одна справа. Алексія треба вбити. Якщо він помре, я більше не перейматимуся через найманців, яких він найняв, щоб вбити мене.\n\nЦе просте завдання. Алексій ховається під захистом Орди — на Валу.\n\nНі, ти маєш не просто зайти та вбити його, мені потрібна його голова! Як ти її отримаєш... ну, це вже твоя справа. Такі роздуми не гідні моєї аристократичної гідності.", [3] = "Відправляйтеся на Вал — територію Орди — та вбийте Алексія Барова. Заберіть його голову та поверніться до Велдона Барова.\n\nБудьте обережні, Алексія охоронятиме наволоч Орди.", [4] = "Тобі потрібні гроші, чи ні?", [5] = "Який чудовий день! Нарешті, виродок роду Барових мертвий, і моя спадщина в безпеці!\n\nВізьми це й згинь з моїх очей, {стать:простак:простачка}.", ["en"] = "The Last Barov", ["tasks"] = { ["Head of Alexi Barov"] = "голова Алексія Барова", ["Head of Alexi Barov (Provided)"] = "голова Алексія Барова (видано)" } },
    [536] = { [1] = "Вздовж узбережжя", [2] = "Мене перевели в Південнобережжя зі Штормовійської варти. Незрозуміло, як тут узагалі люди живуть... Ще й цей постійний сморід з пристані.\n\nНе кажучи вже про старого Редпата... Хоче, щоб я зайнявся мурлоками. Ха!\n\nЯ ледве можу змусити себе підійти до цих риб-переростків на Західному узбережжі. Якщо ти розберешся з ними замість мене, я буду дуже вдячний.", [3] = "Вбийте 10 хвилеловів Розірваного Плавника та 10 оракулів Розірваного Плавника для лейтенанта Фаррена Орінелла з Південнобережжя.", [4] = "Ще елю, будь ласка, бо останній, здається, просто зник!\n\nО, Світло, скільки мені ще тут стирчати?\n\nА, це ти, {ім'я}. Вже {стать:вбив:вбила} тих мурлоків?", [5] = "Сподіваюсь, цього буде достатньо, щоб переконати Редпата, що я — ха! — виконав його наказ і позбавив Південнобережжя від жахливої загрози цих мерзенних мурлоків! Бо не може бути нічого страшнішого за лють риби-переростка!", ["en"] = "Down the Coast", ["tasks"] = { ["Torn Fin Oracle"] = "оракул Розірваного Плавника", ["Torn Fin Oracle slain"] = "оракул Розірваного Плавника: убито", ["Torn Fin Tidehunter"] = "хвилелов Розірваного Плавника", ["Torn Fin Tidehunter slain"] = "хвилелов Розірваного Плавника: убито" } },
    [5382] = { [1] = "Доктор Теолен Крастінов — м'ясник", [2] = "Крастінов винен в смертях тисяч людей. Він має бути покараний, справедливість має взяти гору.\n\nЗнайди його і покарай за ті муки, які він завдав незліченній кількості невинних. Коли знищиш його, спали наші останки. Перетвори їх на попіл, {ім'я}.", [3] = "Знайдіть доктора Теолена Крастінова в Некроситеті. Вбийте його, а потім спаліть останки Єви Сархової та Люсьєна Сархова. Коли виконаєте завдання, поверніться до Єви Сархової.", [4] = "М'ясника необхідно зупинити!", [5] = "Я відчуваю, як мій дух зцілюється, {ім'я}. Ти {стать:зробив:зробила} для нас з чоловіком велику послугу, але я впевнена, що ти можеш зробити ще більше.", ["en"] = "Doctor Theolen Krastinov, the Butcher", ["tasks"] = { ["Doctor Theolen Krastinov"] = "доктор Теолен Крастінов", ["Doctor Theolen Krastinov slain"] = "доктор Теолен Крастінов: убито", ["Remains of Eva Sarkhoff Burned"] = "Спалені останки Єви Саркгофф", ["Remains of Eva Sarkhoff Burned (Provided)"] = "Спалені останки Єви Саркгофф (видано)", ["Remains of Eva Sarkhoff Burned slain"] = "Спалені останки Єви Саркгофф: убито", ["Remains of Lucien Sarkhoff Burned"] = "Спалені останки Люсьєна Саркгофа", ["Remains of Lucien Sarkhoff Burned (Provided)"] = "Спалені останки Люсьєна Саркгофа (видано)", ["Remains of Lucien Sarkhoff Burned slain"] = "Спалені останки Люсьєна Саркгофа: убито" } },
    [5384] = { [1] = "Вісник Кіртонос", [2] = "{ім'я}, ось вона.\n\n<Єва вказує на флакон у сумці.>\n\nКров невинних. Найчистіша кров, якою заспокоювали господаря Крастінова.\n\nСаме цією кров'ю можна викликати Кіртоноса. І саме вона допоможе знищити його.\n\nВіднеси кров на балкон і помісти в жаровню. Кіртонос не зможе встояти та з'явиться на поклик. Коли він з'явиться, випусти на нього лють і гнів тисяч невинно вбитих.\n\nЯкщо тобі це вдасться, ти отримаєш набагато більше, ніж просто нашу вдячність.", [3] = "Поверніться до Некроситету з кров'ю невинних. Знайдіть балкон і вилийте кров невинних у жаровню. Після цього з'явиться Кіртонос, щоб поласувати вашою душею.\n\nБоріться доблесно, не здавайтеся ні на йоту! Вбийте Кіртоноса і поверніться до Єви Сархової.", [4] = "Будь {стать:обережним:обережною}, Кіртонос досвідчений боєць.", [5] = "Кіртонос мертвий і жахлива частина історії Некроситету добігає кінця. Однак, ще багато чого потрібно зробити. Тепер усі знають про твої хоробрі вчинки. Візьми це, {ім'я}. Це частинка нашої сутності. Вона дозволить тобі спілкуватися з іншими загубленими душами Тверджі Дарроу.", ["en"] = "Kirtonos the Herald", ["tasks"] = { ["Kirtonos the Herald"] = "Вісник Кіртонос", ["Kirtonos the Herald slain"] = "Вісник Кіртонос: убито" } },
    [5385] = { [1] = "Останки Трея Світлогарта", [2] = "Ви обережно підіймаєте мішок і готуєтеся повернутися з останками до Жезір Лукомісяць на кордоні між Скверноліссям і Ясенеділом. Ви сподіваєтесь, що після того, як ви передасте останки паладина його друзям, йому будуть віддані належні почесті.", [3] = "Поверніть останки Трея Світлогарта до Жезір Лукомісяць у Сквернолісся.", [4] = "Як все пройшло в Джеденарі, {ім'я}?", [5] = "Ти {стать:зробив:зробила} це! Слава Елуні та будь-яким силам, яким ти поклоняєшся, {ім'я}. Ти {стать:вчинив:вчинила} почесно і благородно. Я впевнена, що Арко'нарін буде задоволена, що ти не лише {стать:витратив:витратила} час, щоб врятувати її, але й {стать:убив:убила} істоту, яка катувала одного з її кращих друзів.\n\nЯ хотіла б зробити для тебе більше, але, будь ласка, прийми це.", ["en"] = "The Remains of Trey Lightforge", ["tasks"] = { ["Remains of Trey Lightforge"] = "останки Трея Світлогарта", ["Remains of Trey Lightforge (Provided)"] = "останки Трея Світлогарта (видано)" } },
    [5402] = { [1] = "Камені посіпак Скари", [4] = "Камені посіпак Скари — знак відзнаки рядових солдатів Скари. Ці камені можна знайти у слабших солдатів, які знаходяться в Зачумлених землях, хоча поняття \"слабших\" не дуже доречне. Скару, які б це створіння не були, не варто недооцінювати.\n\nСріблястий Світанок пропонує знак доблесті в обмін на 20 таких відзнак — обмін, який я з радістю зроблю, за умови, що ти збереш достатню кількість каменів Скари!", [5] = "Вітаю, {ім'я}. Я з радістю вручаю тобі знак доблесті Сріблястого Світанку!\n\nЦі знаки слугують двом цілям. По-перше — вони дають змогу зміцнити твої позиції серед Сріблястого Світанку. Завдяки цьому тобі стануть доступні нові можливості та винагороди, які ми бережемо для найвідданіших союзників. Друга — їх можна віддати квартирмейстерам для плати за цінні предмети Світанку.\n\nЩо б ти не {стать:вирішив:вирішила}, знай, що ти на них заслуговуєш. Молодець!", ["en"] = "Minion's Scourgestones", ["tasks"] = { ["Minion's Scourgestone"] = "камінь посіпаки Скари", ["Minion's Scourgestone (Provided)"] = "камінь посіпаки Скари (видано)" } },
    [5403] = { [1] = "Камені загарбників Скари", [4] = "Камені загарбників Скари — знак відзнаки серед елітних солдатів Скари. Ці камені можна знайти у сильних солдатів, які знаходяться в Зачумлених землях. Вбивство такої істоти — ще те випробування, але воно має бути пройденим заради знищення зла.\n\nСріблястий Світанок пропонує знак доблесті в обмін на 10 таких відзнак. Принеси їх мені, і я подбаю про те, щоб ти {стать:отримав:отримала} гідну винагороду.", [5] = "Вітаю, {ім'я}. Я з радістю вручаю тобі знак доблесті Сріблястого Світанку!\n\nКожен знак доблесті, вручений гідним одержувачам, наближає час перемоги над Скарою. Дедалі більше героїв борються проти Скари на її власних землях, і Сріблястий Світанок, без сумніву, буде в перших рядах, коли прийде час останньої битви проти зла Скари. Я сподіваюся, що доблесть, яку ти {стать:показав:показала} для одержання цього знака, теж допоможе нам того дня.", ["en"] = "Invader's Scourgestones", ["tasks"] = { ["Invader's Scourgestone"] = "камінь загарбника Скари", ["Invader's Scourgestone (Provided)"] = "камінь загарбника Скари (видано)" } },
    [5404] = { [1] = "Камені осквернителів Скари", [4] = "Камінь осквернителя Скари — це відзнака володарів Скари. Вона є у кожної істоти, що має владу над Скарою. Вбивство таких істот служить благу Сріблястого Світанку... та узагалі загальному благу!\n\nВід імені Сріблястого Світанку, я дам тобі знак доблесті за кожну з цих відзнак. Тільки будь {стать:обережним:обережною}, {ім'я} — з такими могутніми істотами не варто жартувати.", [5] = "Вітаю, {ім'я} — я радий нагородити тебе жетоном доблесті Сріблястого Світанку!\n\nЗдобуття жетона доблесті в такий спосіб свідчить про те, що ти є {стать:справжнім поборником:справжньою поборницею} добра. Ми цінуємо всі зусилля, спрямовані на боротьбу зі Скарою, але знищити одного з їхніх лідерів — значить завдати їм нищівної поразки!\n\nЗа Світанок, {стать:брате мій:сестро моя}!", ["en"] = "Corruptor's Scourgestones", ["tasks"] = { ["Corruptor's Scourgestone"] = "камінь осквернителя Скари", ["Corruptor's Scourgestone (Provided)"] = "камінь осквернителя Скари (видано)" } },
    [5461] = { [1] = "Рас Кригошепт — людина", [2] = "Невмерлі бояться життя не менше, ніж живі — смерті. Після перевтілення вони часто знищують будь-які згадки про своє минуле.\n\nНа жаль, щоб мати змогу перетворити Раса Кригошепта на смертного, нам знадобиться якась річ, що містить спогади про його людське життя.\n\nТи маєш відправитися до зруйнованого міста Стромварт, де колись проживав Кригошепт, та знайти такий предмет. Нехай тобі щастить, {ім'я}.", [3] = "Відправляйтеся до височини Араті, в руїни Стромварту. Пошукайте в Стромварті спогад про людяність. Якщо ви знайдете її, повертайтеся до війта Мардука.", [4] = "Такий предмет непросто буде знайти, {ім'я}.", [5] = "Чесно кажучи, я сумнівався, що така річ взагалі існує. Перед нами відкривається чудова можливість — головне, її не впустити.\n\nПриготуйся, {ім'я}, те, про що я тебе попрошу, заведе тебе в самі глибини пекла.", ["en"] = "The Human, Ras Frostwhisper", ["tasks"] = { ["Keepsake of Remembrance"] = "спогад про людяність", ["Keepsake of Remembrance (Provided)"] = "спогад про людяність (видано)" } },
    [5462] = { [1] = "Рас Кригошепт — мрець", [2] = "На нечестивому ґрунті ти пов'яжеш цей спогад.\n\nПодейкують, що саме в Стратгольмі Кригошепт підкорився Королю-лічу. На закривавленій землі він добровільно віддав своє життя, щоб стати одним з невмерлих.\n\nСаме цю землю ми повинні знайти.\n\nВ Каплиці Надії Світла ти знайдеш Леоніда Варфоломія Шанованого. Колись він служив Скарі, його звільнила Королева-Банші, та тепер він вірний Сріблястому Світанку. Знайди його, {ім'я}, можливо, він знає більше, ніж я.", [3] = "Відправляйтеся до Каплиці Надії Світла в Східних Зачумлених землях та знайдіть Леоніда Варфоломія Шанованого. Покажіть йому спогад про людяність та розкажіть, що вам вдалося дізнатися.", [4] = "Не став мені питання, якщо не хочеш дізнатися відповіді.", [5] = "<Леонід оглядає книгу.>\n\nТи змушуєш мене згадувати події, про які я сподівався забути навіки.", ["en"] = "The Dying, Ras Frostwhisper", ["tasks"] = { ["Keepsake of Remembrance"] = "спогад про людяність", ["Keepsake of Remembrance (Provided)"] = "спогад про людяність (видано)" } },
    [5463] = { [1] = "Дар Менетіла", [2] = "Я на власні очі бачив, як Рас Кригошепт приніс свою нечестиву душу в жертву Королю-Лічу. Він встромив кинджал собі в горлянку і з усмішкою на лиці розрізав її від вуха до вуха. Його тіло впало в центр пентаграми. Король-Ліч став понад тілом мага й за одним рухом Рас Кригошепт повстав в образі ліча.\n\n<Леонід на мить опускає погляд, після чого знову дивиться на вас.>\n\nТак, {раса:к}, я пам'ятаю. Те, що ти шукаєш, має назву — дар Менетіла. Це земля, благословенна Королем-Лічем — свята земля для Скари.", [3] = "Вирушайте в Стратгольм і знайдіть дар Менетіла. Покладіть спогад про людяність на нечестиву землю.", [4] = "Площа навколо дару Менетіла надзвичайно холодна.", [5] = "Ви кладете спогад про людяність на нечестивий ґрунт.", ["en"] = "Menethil's Gift", ["tasks"] = { ["Keepsake of Remembrance"] = "спогад про людяність", ["Keepsake of Remembrance (Provided)"] = "спогад про людяність (видано)" } },
    [5464] = { [1] = "Дар Менетіла", [2] = "Душа чіпляється за те, що символізувало її колишнє життя, і перетворює цей предмет на власну пам'ятку. Ви підіймаєте предмет та ховаєте його до себе в сумку.", [3] = "Принесіть спогад душі Леоніду Варфоломію в Східні Зачумлені землі.", [4] = "<Леонід здригається.>", [5] = "Як ця душа чіпляється за спогад, так само має чіплятися до своєї фізичної форми — Раса Кригошепта.", ["en"] = "Menethil's Gift", ["tasks"] = { ["Soulbound Keepsake"] = "спогад душі", ["Soulbound Keepsake (Provided)"] = "спогад душі (видано)" } },
    [5465] = { [1] = "Спогад душі", [2] = "Повертайся до Мардука зі спогадом душі, {ім'я}. Він розповість, як цим користуватися.", [3] = "Поверніться до війта Мардука у Тверджу Дарроу. Покажіть йому спогад душі.", [4] = "Тобі вдалося зробити неможливе?", [5] = "Я був впевненим, що ти повернешся до мене в образі нещасного духа.", ["en"] = "Soulbound Keepsake", ["tasks"] = { ["Soulbound Keepsake"] = "спогад душі", ["Soulbound Keepsake (Provided)"] = "спогад душі (видано)" } },
    [5466] = { [1] = "Рас Кригошепт — ліч", [2] = "Залишилося виконати лише одне завдання, {ім'я}. Виступити проти ліча, Раса Кригошепта, в його лігві.\n\nВикористай спогаду душі проти цього чудовиська — будь {стать:безжалісним:безжалісною}! Терпи удари, які він неодмінно завдаватиме тобі. Не піддавайся болю!\n\nКоли ритуал завершиться, Рас знову стане смертним і ти зможеш його вбити. Знищ його і забери його людську голову.", [3] = "Знайдіть Раса Кригошепта у Некроситеті. Використайте спогад душі на його невмерлій подобі. Якщо вам вдасться зробити його смертним, вбийте його та заберіть людську голову Раса Кригошепта. Віднесіть голову війту Мардуку.", [4] = "Ти несеш тягар тисяч неупокоєних душ, {ім'я}.", [5] = "Тисяч душ волають в унісон, {ім'я}! Ти {стать:завдав:завдала} смертельного удару Скарі та її покровителям.", ["en"] = "The Lich, Ras Frostwhisper", ["tasks"] = { ["Human Head of Ras Frostwhisper"] = "людська голова Раса Кригошепта", ["Human Head of Ras Frostwhisper (Provided)"] = "людська голова Раса Кригошепта (видано)" } },
    [548] = { [1] = "<NYI> <TXT> Підвіска з кривавого каменю", [2] = "Це розпочне квестову лінію «Пеленка з кривавого каменю»...<NYI>", ["en"] = "<NYI> <TXT> Bloodstone Pendant" },
    [5501] = { [1] = "Збирач кісток", [2] = "Ми тут сидимо на золотій жилі, я тобі кажу — на золотій копальні! Кістки кодо змінять світ назавжди... У мене є клієнти, які виготовляють з них меблі, музичні інструменти і навіть вибуховий порошок!\n\nЄ караван, який приїжджає і забирає мої кістки кодо, а потім продає їх у селищі Тінездобич. Якщо ти можеш відправитися на кладовище кодо на південь звідси і принести мені десять кісток кодо, я дам тобі щось натомість. Згода?", [3] = "Принесіть 10 кісток кодо з кладовища кодо у халупу Кормека і віддайте їх Біблі Пряжкоклацу.", [4] = "Ну, ти {стать:приніс:принесла} кістки? Караван ось-ось прийде. Мені потрібно десять кісток кодо, щоб досягти вершини кар'єри. Я тобі кажу, вершина кар'єри!", [5] = "Ох, ось вони! Мої кістки!\n\nЯ не можу дочекатися, коли хлопці вдома побачать моє обличчя на обкладинці \"Кезанського вісника\". Я стану найбагатшим гобліном у світі... Тоді всі дізнаються хто я такий, а особливо мій учитель фізкультури, який вічно казав, що я ніколи нічого не досягну!", ["en"] = "Bone Collector", ["tasks"] = { ["Kodo Bone"] = "кістка кодо", ["Kodo Bone (Provided)"] = "кістка кодо (видано)" } },
    [5503] = { [1] = "Жетон Сріблястого Світанку", [5] = "Усі, хто бореться зі злом від імені Сріблястого Світанку, повинні отримати наш жетон. Він дасть право отримувати нагороди від наших квартирмейстерів.\n\nДоки ти носитимеш його, ти зможеш збирати камені Скари з вбитих прибічників Скари, які вони носять як знаки розрізнення. Збирай ці знаки та принось мені. За кожний набір ти отримаєш знак доблесті Сріблястого Світанку.\n\nПрямуй назустріч долі, {клас:к} — приєднуйся до боротьби зі злом!", ["en"] = "Argent Dawn Commission" },
    [5506] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [5507] = { [1] = "Покриви Світанку", [2] = "Твоє служіння Сріблястому Світанку варте похвали, {ім'я}. Ти справді {стать:шанований:шанована} серед нас. Мені доручено надати тобі доступ до придбання однієї з найцінніших речей Світанку — покриву захисту від магії.\n\nПрикріплення такого покриву до наплічників посилить опір до одного з п'яти видів магії. На знак відданості нашій справі, я попрошу тебе принести 10 знаків доблесті в обмін на доступ до цих покривів.", [3] = "Принесіть 10 знаків доблесті Сріблястого Світанку квартирмейстеру Іскросяю в табір Студовій, що в Західних Зачумлених землях.", [4] = "О, {стать:благородний:благородна} {клас:к}! Ти {стать:приніс:принесла} знаки доблесті? Як тільки ти мені їх принесеш, у тебе буде доступ до придбання наших покривів.", [5] = "Приголомшливо — твій внесок Світанку відзначений належним чином, {ім'я}. Оскільки ти {стать:виконав:виконала} завдання, я з радістю надаю тобі доступ до придбання наших покривів. Якщо ти й надалі підтримуватимеш ставлення нашого ордену до тебе, ти зможеш купити ці покриви у будь-яких квартирмейстерів Сріблястого Світанку.\n\nЗа Світанок, {стать:брате мій:сестро моя}!", ["en"] = "Mantles of the Dawn", ["tasks"] = { ["21000 reputation with Argent Dawn"] = "21000 репутації у Сріблястого Світанку", ["Argent Dawn Valor Token"] = "знак доблесті Сріблястого Світанку", ["Argent Dawn Valor Token (Provided)"] = "знак доблесті Сріблястого Світанку (видано)" } },
    [5508] = { [1] = "Камені осквернителів Скари", [4] = "Камінь осквернителя Скари — це відзнака володарів Скари. Вона є у кожної істоти, що має владу над Скарою. Вбивство таких істот служить благу Сріблястого Світанку... та узагалі загальному благу!\n\nВід імені Сріблястого Світанку, я дам тобі знак доблесті за кожну з цих відзнак. Тільки будь {стать:обережним:обережною}, {ім'я} — з такими могутніми істотами не варто жартувати.", [5] = "Вітаю, {ім'я} — я радий нагородити тебе жетоном доблесті Сріблястого Світанку!\n\nЗдобуття жетона доблесті в такий спосіб свідчить про те, що ти є {стать:справжнім поборником:справжньою поборницею} добра. Ми цінуємо всі зусилля, спрямовані на боротьбу зі Скарою, але знищити одного з їхніх лідерів — значить завдати їм нищівної поразки!\n\nЗа Світанок, {стать:брате мій:сестро моя}!", ["en"] = "Corruptor's Scourgestones", ["tasks"] = { ["Corruptor's Scourgestone"] = "камінь осквернителя Скари", ["Corruptor's Scourgestone (Provided)"] = "камінь осквернителя Скари (видано)" } },
    [5509] = { [1] = "Камені загарбників Скари", [4] = "Камені загарбників Скари — знак відзнаки серед елітних солдатів Скари. Ці камені можна знайти у сильних солдатів, які знаходяться в Зачумлених землях. Вбивство такої істоти — ще те випробування, але воно має бути пройденим заради знищення зла.\n\nСріблястий Світанок пропонує знак доблесті в обмін на 10 таких відзнак. Принеси їх мені, і я подбаю про те, щоб ти {стать:отримав:отримала} гідну винагороду.", [5] = "Вітаю, {ім'я}. Я з радістю вручаю тобі знак доблесті Сріблястого Світанку!\n\nКожен знак доблесті, вручений гідним одержувачам, наближає час перемоги над Скарою. Дедалі більше героїв борються проти Скари на її власних землях, і Сріблястий Світанок, без сумніву, буде в перших рядах, коли прийде час останньої битви проти зла Скари. Я сподіваюся, що доблесть, яку ти {стать:показав:показала} для одержання цього знака, теж допоможе нам того дня.", ["en"] = "Invader's Scourgestones", ["tasks"] = { ["Invader's Scourgestone"] = "камінь загарбника Скари", ["Invader's Scourgestone (Provided)"] = "камінь загарбника Скари (видано)" } },
    [5510] = { [1] = "Камені посіпак Скари", [4] = "Камені посіпак Скари — знак відзнаки рядових солдатів Скари. Ці камені можна знайти у слабших солдатів, які знаходяться в Зачумлених землях, хоча поняття \"слабших\" не дуже доречне. Скару, які б це створіння не були, не варто недооцінювати.\n\nСріблястий Світанок пропонує знак доблесті в обмін на 20 таких відзнак — обмін, який я з радістю зроблю, за умови, що ти збереш достатню кількість каменів Скари!", [5] = "Вітаю, {ім'я}. Я з радістю вручаю тобі знак доблесті Сріблястого Світанку!\n\nЦі знаки слугують двом цілям. По-перше — вони дають змогу зміцнити твої позиції серед Сріблястого Світанку. Завдяки цьому тобі стануть доступні нові можливості та винагороди, які ми бережемо для найвідданіших союзників. Друга — їх можна віддати квартирмейстерам для плати за цінні предмети Світанку.\n\nЩо б ти не {стать:вирішив:вирішила}, знай, що ти на них заслуговуєш. Молодець!", ["en"] = "Minion's Scourgestones", ["tasks"] = { ["Minion's Scourgestone"] = "камінь посіпаки Скари", ["Minion's Scourgestone (Provided)"] = "камінь посіпаки Скари (видано)" } },
    [5512] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [5513] = { [1] = "Покриви Світанку", [2] = "Твоє служіння Сріблястому Світанку варте похвали, {ім'я}. Ти справді {стать:шанований:шанована} серед нас. Мені доручено надати тобі доступ до придбання однієї з найцінніших речей Світанку — покриву захисту від магії.\n\nПрикріплення такого покриву до наплічників посилить опір до всіх п'яти видів магії. На знак відданості нашій справі, я попрошу тебе принести 10 знаків доблесті в обмін на доступ до цих покривів.", [3] = "Принесіть 10 знаків доблесті Сріблястого Світанку квартирмейстерці Брамолам в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "О, {стать:благородний:благородна} {клас:к}! Ти {стать:приніс:принесла} знаки доблесті? Як тільки ти мені їх принесеш, у тебе буде доступ до придбання наших покривів.", [5] = "Приголомшливо — твій внесок Світанку відзначений належним чином, {ім'я}. Оскільки ти {стать:виконав:виконала} завдання, я з радістю надаю тобі доступ до придбання наших покривів. Якщо ти й надалі підтримуватимеш ставлення нашого ордену до тебе, ти зможеш купити ці покриви у будь-яких квартирмейстерів Сріблястого Світанку.\n\nЗа Світанок, {стать:брате мій:сестро моя}!", ["en"] = "Mantles of the Dawn", ["tasks"] = { ["21000 reputation with Argent Dawn"] = "21000 репутації у Сріблястого Світанку", ["Argent Dawn Valor Token"] = "знак доблесті Сріблястого Світанку", ["Argent Dawn Valor Token (Provided)"] = "знак доблесті Сріблястого Світанку (видано)" } },
    [5515] = { [1] = "Мішок жахів Крастінова", [2] = "Ми зняли великий тягар з наших сердець, {ім'я}, але твоє завдання все ще не завершено. Господар Крастінова — Кіртонос, все ще живий.\n\nПерш ніж зустрітися з Кіртоносом, ти маєш знайти спосіб його виклику.\n\nКажуть, що Джандіс Барова переправляє кров невинних від Крастінова до Кіртоноса.\n\nВідшукай її в затоплених підземеллях Некроситету та вбий. Принеси усі докази, які зможеш знайти.", [3] = "Знайдіть Джандіс Барову в Некроситеті та вбийте її. Заберіть у неї мішок жахів Крастінова. Віднесіть його Єві Сарховій.", [4] = "<Єва то з'являється, то зникає.>", [5] = "Мішок жахів!", ["en"] = "Krastinov's Bag of Horrors", ["tasks"] = { ["Krastinov's Bag of Horrors"] = "мішок жахів Крастінова", ["Krastinov's Bag of Horrors (Provided)"] = "мішок жахів Крастінова (видано)" } },
    [5516] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [5517] = { [1] = "Хроматичний покрив Світанку", [2] = "{стать:Брате:Сестро} {ім'я} — твоїх подвигів на славу Сріблястого Світанку не злічити. На знак вдячності, я розлучуся з одним з наших особливих Хроматичних покривів Світанку — тих самих, що захищають від усіх видів магії одночасно. Хроматичні покриви Світанку призначені лише для наймогутніших героїв Світанку!\n\nПринеси мені двадцять п'ять знаків доблесті й отримаєш найкращий з усіх наших покривів.", [3] = "Принесіть 25 знаків доблесті Сріблястого Світанку квартирмейстерці Брамолам в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Вітаю, {стать:могутній:могутня} {клас:к}! Ти {стать:приніс:принесла} знаки доблесті? Як тільки віддаси їх мені, я видам тобі твій власний хроматичний покрив Світанку.", [5] = "Неймовірно, {ім'я} — Хроматичний покрив Світанку тепер твій!\n\nДопоки ти підтримуватимеш ставлення нашого ордену до тебе, ти зможеш придбати додаткові Хроматичні покриви. Вони будуть доступні тобі у будь-якого квартирмейстера Світанку.", ["en"] = "Chromatic Mantle of the Dawn", ["tasks"] = { ["42000 reputation with Argent Dawn"] = "42000 репутації у Сріблястого Світанку", ["Argent Dawn Valor Token"] = "знак доблесті Сріблястого Світанку", ["Argent Dawn Valor Token (Provided)"] = "знак доблесті Сріблястого Світанку (видано)" } },
    [5518] = { [1] = "Костюм ґордоцького огра", [2] = "Якщо ти збираєшся битися з королем цього звалища — а я певен, що саме це ти й збираєшся робити — тобі доведеться пройти повз капітана Дужохруста. Звичайно, ти можеш просто вбити його. Але, можливо, краще залишити його в живих.\n\nТи запитаєш, як? Я вже давно тут сиджу і думаю, що знаю, як зробити костюм огра, який протримається достатньо довго, щоб обдурити цих бовдурів. Єдина проблема — стійкість, його вистачить максимум на десять хвилин. Принеси мені все, що потрібно і я зшию тобі його. Я чекатиму тут...", [3] = "Принесіть 4 рулони рунічної тканини, 8 кусків міцної шкіри, 2 мотки рунічної нитки та огрську дубильну рідину Вузлу Наперстку. Зараз він прикутий ланцюгами в районі Ґордоків, що в Грізному Молоті.", [4] = "Думаю, зі всього, що мені потрібно для пошиття костюма, найважче знайти огрську дубильну рідину — можливо, в них нагорі щось є? Я не можу потрапити туди тому, що скований цим ланцюгом...\n\nВ будь-якому випадку, просто принеси мені все, що потрібно і я зшию для тебе костюм огра, який змусить капітана Дужохруста прийняти тебе за одного зі своїх.", [5] = "Так, це підійде. Трохи підшити тут і підігнути тут... хах — він виглядатиме просто чудесно! <Посмішка не сходить з обличчя прикутого гобліна.>\n\nОсь так, все готово. Не забувай — ця річ не дасть тобі повну безпеку. В тебе буде десять хвилин, перш ніж костюм розійдеться по швах і тебе розкриють! Постарайся надягнути його не раніше, як підійдеш до капітана і пам'ятай, що капітан вважатиме тільки тебе {стать:своїм союзником:своєю союзницею}, а твої товаришів — ні!", ["en"] = "The Gordok Ogre Suit", ["tasks"] = { ["Bolt of Runecloth"] = "рулон рунічної тканини", ["Bolt of Runecloth (Provided)"] = "рулон рунічної тканини (видано)", ["Ogre Tannin"] = "огрська дубильна рідина", ["Ogre Tannin (Provided)"] = "огрська дубильна рідина (видано)", ["Rugged Leather"] = "міцна шкіра", ["Rugged Leather (Provided)"] = "міцна шкіра (видано)", ["Rune Thread"] = "рунічна нитка", ["Rune Thread (Provided)"] = "рунічна нитка (видано)" } },
    [5519] = { [1] = "Костюм ґордоцького огра", [4] = "Потрібен ще один костюм, так? Ну, здається, я нікуди не збираюся найближчим часом — принеси мені ті ж самі речі, що я просив раніше і я зшию тобі ще один костюм огра.", [5] = "Ось, будь ласка, {ім'я} — вдягни цю штуку і в тебе буде десять хвилин, щоб зробити все, що забажаєш. Щасти!\n\nА, і якщо ти випадково натрапиш на ключ, який витягне мене звідси, БУДЬ ЛАСКА, ДАЙ ЗНАТИ ПРО ЦЕ!!!", ["en"] = "The Gordok Ogre Suit", ["tasks"] = { ["Bolt of Runecloth"] = "рулон рунічної тканини", ["Bolt of Runecloth (Provided)"] = "рулон рунічної тканини (видано)", ["Ogre Tannin"] = "огрська дубильна рідина", ["Ogre Tannin (Provided)"] = "огрська дубильна рідина (видано)", ["Rugged Leather"] = "міцна шкіра", ["Rugged Leather (Provided)"] = "міцна шкіра (видано)", ["Rune Thread"] = "рунічна нитка", ["Rune Thread (Provided)"] = "рунічна нитка (видано)" } },
    [5520] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [5521] = { [1] = "Хроматичний покрив Світанку", [2] = "{стать:Брате:Сестро} {ім'я} — твоїх подвигів на славу Сріблястого Світанку не злічити. На знак вдячності, я розлучуся з одним з наших особливих хроматичних покривів Світанку — тих самих, що захищають від усіх видів магії одночасно. Хроматичні покриви Світанку призначені лише для наймогутніших героїв Світанку!\n\nПринеси мені двадцять п'ять знаків доблесті й отримаєш найкращий з усіх наших покривів.", [3] = "Принесіть 25 знаків доблесті Сріблястого Світанку квартирмейстеру Іскросяю в табір Студовій, що в Західних Зачумлених землях.", [4] = "Вітаю, {стать:могутній:могутня} {клас:к}! Ти {стать:приніс:принесла} знаки доблесті? Як тільки віддаси їх мені, я видам тобі твій власний хроматичний покрив Світанку.", [5] = "Неймовірно, {ім'я} — хроматичний покрив Світанку тепер твій!\n\nДопоки ти підтримуватимеш ставлення нашого ордену до тебе, ти зможеш придбати додаткові хроматичні покриви. Вони будуть доступні тобі у будь-якого квартирмейстера Світанку.", ["en"] = "Chromatic Mantle of the Dawn", ["tasks"] = { ["42000 reputation with Argent Dawn"] = "42000 репутації у Сріблястого Світанку", ["Argent Dawn Valor Token"] = "знак доблесті Сріблястого Світанку", ["Argent Dawn Valor Token (Provided)"] = "знак доблесті Сріблястого Світанку (видано)" } },
    [5522] = { [1] = "Леонід Варфоломій", [2] = "Я отримала листа від мого господаря, Вектуса. Ну, насправді повідомлення було від когось, на ім'я Леонід Варфоломій. Я не знаю Леоніда, але він знав мого господаря, а ніхто не може знати мого господаря, якщо він сам цього не забажає.\n\nЛеонід каже, що Вектусу потрібні драконячі яйця. Він хоче, щоб ти {стать:приніс:принесла} їх йому до каплиці Надії Світла у Східних Зачумлених землях.\n\nЦе неприємно. Чому саме ти? Невже Вектус не довіряє мені? Ох, що ж... Просто візьми яйця і скажи Леоніду, що я виконала те, що вимагав наш господар.", [3] = "Принесіть заморожені яйця Леоніду Варфоломію у Східні Зачумлені землі.", [4] = "Ага, це ти {стать:влаштував:влаштувала} ту бійню в Чорноскельному шпилі, так? У тебе є те, що я просив?", [5] = "Дуже добре. Ти ще не знаєш, наскільки велике зло криється за тими, на кого ти {стать:працював:працювала}, але я відкрию тобі правду. І не бійся — я не служу їм. Я Леонід Варфоломій, відомий як Шанований серед моїх побратимів у Сріблястому Світанку.\n\nЯ обдурив Тінкі, щоб вона відправила тебе з драконячими яйцями до мене. І добре, що все вийшло як треба, бо якби ці яйця досягли своєї призначеної мети, в руках ворога опинилася б велика сила.", ["en"] = "Leonid Barthalomew", ["tasks"] = { ["Frozen Eggs"] = "заморожені яйця", ["Frozen Eggs (Provided)"] = "заморожені яйця (видано)" } },
    [5523] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [5524] = { [1] = "Хроматичний покрив Світанку", [2] = "{стать:Брате:Сестро} {ім'я} — твоїх подвигів на славу Сріблястого Світанку не злічити. На знак вдячності, я розлучуся з одним з наших особливих хроматичних покривів Світанку — тих самих, що захищають від усіх видів магії одночасно. Хроматичні покриви Світанку призначені лише для наймогутніших героїв Світанку!\n\nПринеси мені двадцять п'ять знаків доблесті й отримаєш найкращий з усіх наших покривів.", [3] = "Принесіть 25 знаків доблесті Сріблястого Світанку квартирмейстеру Гасані на Вал, що в Західних Зачумлених землях.", [4] = "Вітаю, {стать:могутній:могутня} {клас:к}! Ти {стать:приніс:принесла} знаки доблесті? Як тільки віддаси їх мені, я видам тобі твій власний хроматичний покрив Світанку.", [5] = "Неймовірно, {ім'я} — хроматичний покрив Світанку тепер твій!\n\nДопоки ти підтримуватимеш ставлення нашого ордену до тебе, ти зможеш придбати додаткові хроматичні покриви. Вони будуть доступні тобі у будь-якого квартирмейстера Світанку.", ["en"] = "Chromatic Mantle of the Dawn", ["tasks"] = { ["42000 reputation with Argent Dawn"] = "42000 репутації у Сріблястого Світанку", ["Argent Dawn Valor Token"] = "знак доблесті Сріблястого Світанку", ["Argent Dawn Valor Token (Provided)"] = "знак доблесті Сріблястого Світанку (видано)" } },
    [5525] = { [1] = "Звільнення Вузла!", [4] = "Він називається ключем від кайданів Ґордока — принаймні, так його називають ці \"жартівники\". Гадаю, він може бути в будь-якого огра, але я не знаю в якого конкретно. Думаю, більше шансів знайти його в охоронців...\n\nТа про що я говорю, ключ вже в тебе, чи не так?! Так?!", [5] = "Ти для мене на першому місці. Всі інші — після тебе. Дякую, що {стать:звільнив:звільнила} мене!\n\nЯ знав, що моя доля стати чимось більшим, аніж закускою для якогось огра!", ["en"] = "Free Knot!", ["tasks"] = { ["Gordok Shackle Key"] = "ключ від кайданів Ґордока", ["Gordok Shackle Key (Provided)"] = "ключ від кайданів Ґордока (видано)" } },
    [5526] = { [1] = "Уламки Сквернолози", [2] = "Твої знання про Ельдре'Талас — Грізний Молот — що в Фераласі тепер стануть у пригоді, {Ім'я}. У східній частині зруйнованого міста Альззін-Диковертень веде своє нечестиве панування. Йди туди якомога швидше та хоробро зустрінь будь-які виклики, що чекатимуть на тебе.\n\nПлід родючості, нині споганений і перетворений на Сквернолозу, повинен бути неподалік від Альззіна. Коли демон згине, збери стільки есенції Сквернолози, скільки зможеш. Запечатай її у релікварії та принеси мені.\n\nЩасти, і швидкості Кенарія тобі.", [3] = "Знайдіть Сквернолозу в Грізному Молоті та дістаньте її уламок. Найімовірніше, вам вдасться здобути його лише після смерті Альззіна-Диковертня. Скористайтесь релікварієм чистоти, щоб надійно запечатати уламок усередині, та повертайтеся з ним до Рабіна Сатурни в Нічну Гавань на Місячній галявині.", [4] = "Отримавши запечатаний релікварій чистоти, ми зможемо не лише усунути загрозу порчі з цього світу, але й дослідити її під нашим розсудливим наглядом. Можливо, ми навіть зможемо винайти нові способи боротьби з будь-яким зараженням, що коли-небудь загрожуватиме Азероту.\n\nЯ знаю, Міллі б цього хотіла…", [5] = "Справу завершено, {cтать:хоробрий:хоробра} {клас:к}, і тепер Кенарійське Коло в боргу перед тобою. Хоча війна далека від завершення, велику битву проти тих, хто хотів приректи на загибель, було виграно.\n\nПрошу, прийми це в знак нашої щирої вдячності. Тепер знай, {Ім'я}, за твої великі вчинки тебе завжди вітатимуть тут як героя Кенарійського Кола. Дякую тобі.", ["en"] = "Shards of the Felvine", ["tasks"] = { ["Sealed Reliquary of Purity"] = "запечатаний релікварій чистоти", ["Sealed Reliquary of Purity (Provided)"] = "запечатаний релікварій чистоти (видано)" } },
    [5527] = { [1] = "Релікварій чистоти", [2] = "Перший крок — знайти ємність, здатну втримати надзвичайно споганену субстанцію та при цьому вберегти власника від її шкідливого впливу. Є лише один відомий мені прилад, що здатен вмістити щось настільки мерзенне, як Сквернолоза — релікварій чистоти.\n\nГлибоко в пустках Силітусу є руїни поселення нічних ельфів, відомого як селище Південний Вітер. Я знаю, що релікварій був там багато, багато років тому. Задля успіху наших планів, тобі потрібно обшукати ці руїни в надії віднайти його.", [3] = "Прямуйте до Силітуса та знайдіть релікварій чистоти в руїнах селища Південний Вітер. Якщо вам вдасться його знайти, повертайтеся з ним до Рабіна Сатурни в Нічну Гавань на Місячній галявині.", [4] = "Релікварій чистоти вже сам по собі є артефактом. Лише кілька таких було створено, і майже всі вони вважаються вважалися з часом.\n\nВизнаю, про той, що в Південному Вітрі, я знав уже деякий час. Якщо чесно, у зв'язку зі зростаючою метушнею в Силітусі я хотів би, щоб наші таємниці такими й залишалися — таємницями. Нишпорення та розпитування тільки посилять підозри наших ворогів.\n\nНа жаль, час для поступливості закінчується, особливо, з огляду на ситуацію в Ельдре'Таласі.", [5] = "А ти справді {стать:такий же винахідливий:така ж винахідлива}, як про тебе говорять. Кенарійському Колу справді пощастило, що ти працюєш на нас.\n\nЗ поверненням релікварію чистоти мені стало значно легше. Тепер я почуваюся спокійніше, коли прошу тебе не лише перемогти злісного демона, але й повернути небезпечний предмет.", ["en"] = "A Reliquary of Purity", ["tasks"] = { ["Reliquary of Purity"] = "релікварій чистоти", ["Reliquary of Purity (Provided)"] = "релікварій чистоти (видано)" } },
    [5528] = { [1] = "Найсмачніший напій Ґордока", [5] = "Ти тепер великий бос, тож можеш просто так скуштувати мої найкращі напої! Вони підбадьорять тебе і дадуть добряче кайфонути! Це хороші напої, шеф... Спробуй {стать:сам:сама}!", ["en"] = "The Gordok Taste Test" },
    [5529] = { [1] = "Зачумлені дитинчата дракона", [2] = "Нещодавно до Сріблястого Світанку дійшли чутки, що Скара створює своїх власних зачумлених драконів! Ми повинні зупинити їх — якщо Скара отримає силу драконів, вони безконтрольно літатимуть по всьому Азероту!\n\nЇхні некроманти розводять зачумлених драконів у Некроситеті, посеред озера Дарроумер.\n\nВирушай до Некроситету та вбий якомога більше дитинчат драконів, поки вони не виросли!", [3] = "Вбийте 20 зачумлених дитинчат дракона та поверніться до Бетіни Біґґльзінк у Каплицю Надії Світла.", [4] = "{ім'я}, вирушай до Некроситету. Знищ зачумлених дитинчат дракона до того, як вони виростуть!", [5] = "Молодець, {ім'я}! Їм знадобиться багато часу, щоб виростити нових драконів.\n\n...Принаймні, я на це сподіваюся!", ["en"] = "Plagued Hatchlings", ["tasks"] = { ["Plagued Hatchling"] = "зачумлене дитинча дракона", ["Plagued Hatchling slain"] = "зачумлене дитинча дракона: убито" } },
    [5531] = { [1] = "Бетіна Біґґльзінк", [2] = "Яйця, які ти {стать:приніс:принесла}, мали бути використані в експериментах Скари, для створення зачумлених драконів. Ці заморожені яйця чорних драконів, безсумнівно, прискорили б їхню роботу.\n\nНастав час покласти край їхнім дослідженням.\n\nВіднеси заморожені яйця до Бетіни Біґґльзінк. Вона добре розбирається в науці та алхімії й виготовила зброю, яку ми використовуємо проти Скари. З твоєю допомогою ми завдамо їм потужного удару.", [3] = "Віднесіть заморожені яйця до Бетіни Біґґльзінк.", [4] = "Привіт, {ім'я}! Я чула, що ти {стать:приніс:принесла} драконячі яйця? Що ж, погляньмо на них!", [5] = "Ось вони! І в такій хорошій коробці. Ідеального розміру!\n\nМи триматимемо ці яйця в безпечному місці, щоб потім вивчити, але зараз нам потрібна та штука, яку ти {стать:приніс:принесла}.\n\nЯ створила пристрій, який має дуже специфічне призначення: знищувати невмерлих вчених в Некроситеті. Вони вивчають драконів, намагаючись створити зачумлених драконів, ми повинні зупинити їх.\n\nЯ назвала пристрій Гамбіт Світанку, бо... Я не впевнена, що він працює!\n\nЗможеш перевірити його?", ["en"] = "Betina Bigglezink", ["tasks"] = { ["Frozen Eggs"] = "заморожені яйця", ["Frozen Eggs (Provided)"] = "заморожені яйця (видано)" } },
    [5532] = { [1] = "<NYI> <TXT> Кільце Світанку", ["en"] = "<NYI> <TXT> Ring of the Dawn", ["tasks"] = { ["Argent Dawn Valor Token"] = "знак доблесті Сріблястого Світанку", ["Required money: 20"] = "Необхідна сума: 20" } },
    [5533] = { [1] = "Некроситет", [2] = "На острові Тверджа Дарроу знаходиться Некроситет — мерзенна школа, що слугує центром некромантії та зла Скари. В її надрах наші вороги спокійно здійснюють невимовні акти жорстокості проти мимовільних жертв... принаймні, ми так думаємо. Двері загороджують нам шлях, і як ми не намагалися, без відповідного ключа їх не відчинити.\n\nАлхімік Арбінґтон багато знає про Некроситет, і у нього є ідея, як отримати цей ключ. Ти {стать:довів:довела}, що ти {стать:той:та}, хто завжди сумлінно виконує поставлені задачі, тож я довіряю це завдання тобі. Обговори подробиці з аптекарем.", [3] = "Поговоріть з алхіміком Арбінґтоном в проліску Студовій, що Західних Зачумлених землях.", [5] = "Радий зустрічі, {клас:к}. Я присвятив чимало часу дослідженню Некроситету, і мені здається, що я знаю, як отримати ключ... ключ, який дозволить тобі відчинити вхідні двері.\n\nЯ можу лише уявити, які жахливі речі можна там побачити, {ім'я}. Не знаю, як ви, \"герої\", це робите...", ["en"] = "Scholomance" },
    [5534] = { [1] = "\"Зникле\" спорядження Кім'джаєля", [2] = "Що?! Що?!\n\nТобі мало цього? Ти знаєш, яка вартість цієї вибухівки? Вона продається за... О, ну ладно. Добре, ти хочеш заробити реальні гроші? Так працює бізнес: ти доводиш свою цінність, і тоді тебе адекватно винагороджують, коли ти покажеш себе.\n\nЯкщо ти {стать:\"цінний\" працівник:\"цінна\" працівниця}, то вирушай до руїн Ельдарата та знайди для мене руну, яку шукали ці ельфи крові. Здається, нею володіють наги.", [3] = "Знайдіть у руїнах Ельдарата якусь руну, яку охороняють наги, і поверніть її Кім'джаєлю в Азшару.", [4] = "Ну, {ім'я}? Де руна? Ти {стать:хороший працівник:хороша працівниця}, так? Ти тут, щоб допомогти?\n\nНе змушуй мене думати двічі про те, щоб заплатити тобі те, про що ми домовилися. Про що? О, ми ні про що не домовлялися? Чудово... тоді не поспішай — просто знай, що я заплачу набагато менше, якщо будеш гаяти час.", [5] = "Ха-ха! Чудово!\n\nЯ обов'язково з'ясую, для чого вона, і чому чаклунка Рімторі — це корова, яка мене найняла — хотіла цю руну. Ха! Попалися, смердючі ельфи крові! Кім'джаєль! Ха! Я покажу їм, хто тут пацюк!\n\nТи молодець, {ім'я}. Спасибі тобі величезне. Ось, бери нагороду і йди, мені треба дещо з'ясувати.", ["en"] = "Kim'jael's \"Missing\" Equipment", ["tasks"] = { ["Some Rune"] = "якась руна", ["Some Rune (Provided)"] = "якась руна (видано)" } },
    [5535] = { [1] = "Духовний неспокій", [2] = "В давні часи, високородні були одними з найпотужніших учнів арканічної магії, які коли-небудь існували серед нічних ельфів. Скверна, яка супроводжує такі вчення, завдала багато шкоди нічним ельфам і сильно вплинула на весь Азерот... я думаю, ти це знаєш.\n\nЯ обіцяв стражам, що звільнятиму зустрінутих мною духів від їхніх смертних зв'язків. Якщо допоможеш мені в цьому, я нагороджу тебе.\n\nПримари знаходяться біля вівтаря Пісні Тіней на північний схід звідси.", [3] = "Знищіть 6 високородних примар і 6 високородних тіней, перш ніж повернутися до Ло'ату в Азшару.", [4] = "Як проходить пошук духів високородних, {клас:к}?\n\nБагато подій завдали страждань усім расам Азероту, але з якоїсь причини ці духи здаються чумою для всього народу. Можливо, справа в їхньому потягу до арканічної магії. Ти знаєш, це пішло від Палаючого Легіону... І ти знаєш, чим усе це може закінчитися.", [5] = "Молодець, {клас:к}. Дякую за допомогу. Духи умиротворені, і загроза, яка несе в собі їхнє прагнення до арканічної магії, зменшилася.\n\nДумаю, обидві сторони конфлікту, що роздирає нині Азерот, зрозуміють, що ти вищий за це.", ["en"] = "Spiritual Unrest", ["tasks"] = { ["Highborne Apparition"] = "високородна примара", ["Highborne Apparition slain"] = "високородна примара: убито", ["Highborne Lichling"] = "високородна тінь", ["Highborne Lichling slain"] = "високородна тінь: убито" } },
    [5536] = { [1] = "Земля, сповнена ненависті", [2] = "Сатири, спотворений, злий різновид нічних ельфів, тепер забруднюють священні землі, якими колись ходив Кенарій. Я не можу говорити за нічних ельфів про всі звірства, скоєні цими демонічними істотами, але я присягнувся Матері-Землі допомогти ельфам позбавити цю землю від такої напасті.\n\nЯ впевнений, що ти зможеш показати, на що {стать:здатен:здатна}, якщо допоможеш мені очистити цю землю від них.\n\nНа північний схід звідси живе клан Гальдаррів. Повертайся до мене, коли випробуєш свої сили проти їхньої міці.", [3] = "Вбийте 6 гальдаррсьских сатирів, 2 гальдаррсьских ошустів, 2 гальдаррсьских скверноклятів та поверніться до Ло'ату на кордоні Ясенедолу.", [4] = "Як тобі битва проти сатирів, {клас:к}?\n\nЧи вони настільки ж сильні, як ти {стать:уявляв:уявляла}? Чи сильніші? Чи може їхні сили були нікчемними у порівнянні з твоєю?", [5] = "Молодець, {клас:к}. Бачу, що ти не тільки {стать:вправний:вправна}, але й {стать:хитрий:хитра}. Перемога над цими створіннями — свідчення твоєї відданості Матері-Землі, навіть якщо ти й не визнаєш її своїм божеством. Вона — в усьому на цій планеті та поза нею. Її очі, одне темне, а друге світле, мандрують небом і завжди споглядають на нас.\n\nБудь ласка, візьми цю невеличку винагороду на знак вдячності за те, що ти {стать:зробив:зробила}.", ["en"] = "A Land Filled with Hatred", ["tasks"] = { ["Haldarr Felsworn"] = "гальдаррсьский скверноклят", ["Haldarr Felsworn slain"] = "гальдаррсьский скверноклят: убито", ["Haldarr Satyr"] = "гальдаррсьский сатир", ["Haldarr Satyr slain"] = "гальдаррсьский сатир: убито", ["Haldarr Trickster"] = "гальдаррсьский ошуст", ["Haldarr Trickster slain"] = "гальдаррсьский ошуст: убито" } },
    [5537] = { [1] = "Фрагменти скелетів", [2] = "Ключ до Некроситету називається Скелетним Ключем. Він кується із залишків скелетів — точніше, з декількох — та укріплюється одним з найміцніших металів у відповідній формі. Тільки сила створіння, що може відкрити портал до Некроситету, змусить ключ працювати.\n\nАле почнемо з найважливішого, {ім'я}. Нам знадобляться фрагменти скелетів, щоб викувати ключ. Скелети з Андорала чудово підійдуть, хоча й ті, що знаходяться за стіною, теж згодяться.", [3] = "Принесіть 15 фрагментів скелетів алхіміку Арбінґтону в пролісок Студовій, що в Західних Зачумлених землях.", [4] = "Якби це погано не звучало, але нам знадобиться чимала кількість фрагментів скелетів, щоб зробити зовнішню оболонку ключа. Його ж не дарма називають скелетним ключем.", [5] = "Так, вони підійдуть, {ім'я}! Тепер моя черга — я загартую фрагменти таким чином, щоб вони змогли витримати напружений процес кування, через який їм доведеться пройти.\n\nНаступний крок — знайти відповідну форму для відливання. Я знаю одного гобліна-коваля з Танаріса, який колись робив схожі форми. Він працює на того, на кого зазвичай і працюють гобліни — на того, хто більше платить.", ["en"] = "Skeletal Fragments", ["tasks"] = { ["Skeletal Fragments"] = "фрагменти скелетів", ["Skeletal Fragments (Provided)"] = "фрагменти скелетів (видано)" } },
    [5538] = { [1] = "Ціна форми", [2] = "Гобліна, з яким тобі потрібно поговорити, звати Крінкл Файносталь. Він працює в Пристроблясі, що в пустелі Танаріс. Йому під силу зробити потрібну нам форму, але це обійдеться недешево. Ми просимо тебе не скупитися та заплатити стільки, скільки він попросить.\n\nЯ алхімік, а не банкір. Якби в мене була купа золота, мене б тут не було.\n\nЗдається, я знову бовкнув щось зайве. Упс.\n\nПристроблях чекає на тебе! Удачі!", [3] = "Принесіть загартовані фрагменти скелетів та 15 золотих монет Крінклу Файносталі в Пристроблях.", [4] = "Так, я знаю хто ти {стать:такий:така}, і я знаю, чому ти тут. Арбінґтон надіслав мені звістку про тебе. Перейдімо до справи?\n\nУ мене є форма, яку ти можеш використати для відливання скелетного ключа, але це коштуватиме тобі 15 золотих. Гроші вперед і ніяких торгів. Я покладу у форму фрагменти скелетів і покажу, як відлити ключ без знань ковальства... і все це безплатно!\n\nХай не кажуть, що я за мідяк вдавлюсь.", [5] = "Арбінґтон казав, що ти принесеш усе необхідне, і так воно і є! Угода є угода, дай-но я складу фрагменти скелетів у форму.\n\nНевже Арбінґтон їх укріпив? Прекрасно... Інакше тобі довелося б повертатись назад, у пролісок Студовій.", ["en"] = "Mold Rhymes With...", ["tasks"] = { ["Imbued Skeletal Fragments"] = "загартовані фрагменти скелетів", ["Imbued Skeletal Fragments (Provided)"] = "загартовані фрагменти скелетів (видано)" } },
    [554] = { [1] = "Розшифрування Бурешпиля", [2] = "Розвідувач Бурешпиль — майстер шифру та розшифрування. Якщо принесете йому знайдений пергамент, то, якщо пощастить, він зможе щось у ньому зрозуміти. Зараз Бурешпиль навчається у штабі розвідувачів у Залізогарті.\n\nА коли зустрінете його, то скажіть, що говорили зі мною: останнім часом я посилав йому досить багато справ.", [3] = "Віднесіть зачаклований пергамент до розвідувача Бурешпиля в Залізогарт.", [4] = "Знову мене відривають від справ...\n\nОх, цей пергамент вкритий дуже складним, тонко закрученим закляттям. Звісно, я можу його розплутати, але це займе час. А час для мене дуже цінний...\n\nМоже, я просто викуплю його у тебе?", [5] = "Мудре рішення. Я не вірю, що є ще вчені, окрім мене, з навичками, достатніми для перекладу цього згортку. А якщо його вміст виявиться цікавим — не переживай, я пошлю по тебе.", ["en"] = "Stormpike's Deciphering", ["tasks"] = { ["Ensorcelled Parchment"] = "зачаклований пергамент", ["Ensorcelled Parchment (Provided)"] = "зачаклований пергамент (видано)" } },
    [5542] = { [1] = "Демонічні пси", [2] = "Якщо ти збираєшся залишатися тут, тобі доведеться відпрацювати за своє проживання. У нас є багато неприємностей, з якими варто розібратися.\n\nМожеш почати з чумних гончих.\n\nЯ не можу запропонувати велику нагороду, але гарантую тобі теплий обід та приємну бесіду.", [3] = "Вбийте 20 карликових чумних гончих, 5 чумних гончих та 5 навіжених чумних гончих. Поверніться до Тіріона Фордрінґа коли виконаєте завдання.", [4] = "Не жалій демонічних псів, {раса:к}. Вони справжні чудовиська!", [5] = "Молодець, {ім'я}. Проходь. Відпочинь. Давай-но поїмо та поговоримо про давно минулі дні.", ["en"] = "Demon Dogs", ["tasks"] = { ["Frenzied Plaguehound"] = "навіжена чумна гонча", ["Frenzied Plaguehound slain"] = "навіжена чумна гонча: убито", ["Plaguehound"] = "чумна гонча", ["Plaguehound Runt"] = "карликова чумна гонча", ["Plaguehound Runt slain"] = "карликова чумна гонча: убито", ["Plaguehound slain"] = "чумна гонча: убито" } },
    [5543] = { [1] = "Небо, забарвлене кров'ю", [2] = "Лихо тим, хто по дурості забрідає в Зачумлені землі. У цих краях водиться всіляка нечисть — від фанатичного Багряного Походу, що вбиває всіх, хто їм не прихильний, до кровожерливої Скари, що лиш прагне поповнити свої ряди ще більшою кількістю невмерлих.\n\nНавіть дикі тварини перетворилися на хижих чудовиськ, що пожирають людей. Я прошу тебе знищити тих, хто нападає з неба: чумних кажанів.", [3] = "Вбийте 30 чумних кажанів і поверніться до Тіріона Фордрінґа.", [4] = "Не варто недооцінювати крилатих шкідників, {раса:к}. Чума наділила їх надприродними здібностями.", [5] = "Ти взірець порядності, {раса:к}! Давно я не відчував геройської крові, що тече в моїх жилах. Твої хоробрі вчинки надихають!", ["en"] = "Blood Tinged Skies", ["tasks"] = { ["Plaguebat"] = "чумний кажан", ["Plaguebat slain"] = "чумний кажан: убито" } },
    [5544] = { [1] = "М'ясо трупожерів", [2] = "Мої запаси їжі закінчуються, {раса:к}. Мені соромно зізнатися, але у мене не вистачить їжі, щоб поділитися з тобою.\n\nЧи не {стать:міг би:могла б} ти допомогти старому з простим завданням? У цих краях єдиний вид тварин, якого не торкнулася чума — це трупні черв'яки. Хоча їхнє м'ясо досить бридке, його можна легко законсервувати на кілька місяців. Мені знадобиться біля сотні кілограм, щоб вистачило на зиму!", [3] = "Шукайте трупних личинок та пожирачів, вбивайте їх та збирайте їхнє м'ясо. Поверніться до Тіріона Фордрінґа, коли зберете 15 шматків м'яса трупних черв'яків.", [4] = "Ти звикнеш до цього смаку, {раса:к}.", [5] = "Нехай Світло благословить тебе, {стать:юначе:юначко}.", ["en"] = "Carrion Grubbage", ["tasks"] = { ["Slab of Carrion Worm Meat"] = "шматок м'яса трупного черв'яка", ["Slab of Carrion Worm Meat (Provided)"] = "шматок м'яса трупного черв'яка (видано)" } },
    [555] = { [1] = "Ніжний черепаховий суп", [2] = "Якщо ти щось і дізнаєшся про Південнобережжя, так це те, що у нас найкраща кухня на північ від Штормовію!\n\nВізьми, наприклад, мій секретний рецепт черепахового супу. Іноді до мене заходять із самого Темнолісся, щоб просто насолодитися ним. До речі, останнім часом мені я все ніяк не міг його приготувати. Раніше я сам ходив повз Даларан до озера Лордамер, щоб полювати на тріскощелепів, але зараз це надто небезпечно. Якщо ти принесеш мені трохи черепашачого м'яса і духмяні спеції, я приготую свій знаменитий суп!", [3] = "Принесіть 10 шматків черепашачого м'яса і духмяні спеції шеф-кухарю Джессену у Південнобережжя.", [4] = "Ну як, вдалося знайти інгредієнти? Так, скажу тобі, тут бували й спокійніші часи. Ах, якби ж не ці війни...", [5] = "Всі будуть у захваті — ніжний черепаховий суп від шеф-кухаря Джессена знову в меню!", ["en"] = "Soothing Turtle Bisque", ["tasks"] = { ["Soothing Spices"] = "духмяні спеції", ["Soothing Spices (Provided)"] = "духмяні спеції (видано)", ["Turtle Meat"] = "черепашаче м'ясо", ["Turtle Meat (Provided)"] = "черепашаче м'ясо (видано)" } },
    [5561] = { [1] = "Загін кодо", [2] = "Біблі думає, що він — єдиний гоблін в Спустошищі, який вміє заробляти гроші. Що ж, єдиний караван, який наважився мандрувати цими землями, повністю покладається на мене. Відтоді, як я навчився омолоджувати й контролювати старих і вмираючих кодо за допомогою свого комбобулятора, ми з караванниками Короком та Монтером стали партнерами.\n\nВізьми комбобулятор і використай на будь-якому древньому, старому або вмираючому кодо; він миттю перетворить звіра на прирученого кодо і змусить його слідувати за тобою. Коли приручиш кодо, приведи його до мене.", [3] = "Приведіть п'ять приручених кодо в табір Гвинтодряпа. Не забудьте повернути Сміду Гвинтодряпу комбобулятор кодо.", [4] = "Караван незабаром буде тут. Ти {стать:привів:привела} п'ять нових приручених кодо, як я просив?", [5] = "<Смід Гвинтодряп починає лічити.>\n\nТри, чотири та п'ять... чудово, я просив п'ять приручених кодо та отримав рівно стільки... Я стану багатим... так, дуже багатим! Я хочу побачити вираз зеленої пики Біблі, коли він почує про це!", ["en"] = "Kodo Roundup", ["tasks"] = { ["Kodo Kombobulator"] = "комбобулятор кодо", ["Kodo Kombobulator (Provided)"] = "комбобулятор кодо (видано)", ["Kodos Tamed"] = "Приручений Кодос", ["Kodos Tamed (Provided)"] = "Приручений Кодос (видано)", ["Kodos Tamed slain"] = "Приручений Кодос: убито" } },
    [558] = { [1] = "Автограф Джайни", [2] = "Кажуть, що леді Джайна Праудмур — одна з найвеличніших героїнь Альянсу, що коли-небудь існували. Коли я виросту, я теж хочу стати героєм Альянсу!\n\nТи знаєш Джайну, {ім'я}? Можеш мені допомогти, будь ласка? Зможеш взяти у неї автограф для мене? Я не знаю, як її попросити, і у неї, напевно, немає часу на таких, як я... Але ти {стать:шукач:шукачка} пригод, так само як і вона! Я впевнений, вона згодиться дати тобі автограф!", [3] = "Прямуйте в Терамор, щоб отримати для свого підопічного автограф леді Джайни Праудмур.", [4] = "Колись я хочу стати героєм, як Джайна... ну, хлопчиком-героєм.", [5] = "ВАУ! Тобі вдалося взяти автограф у леді Джайни! Дуже тобі дякую! І, ого... вона написала на ньому щось для мене! Я знав, вона крута, просто знав! Може, якось в майбутньому я подякую її особисто... коли сам стану героєм Альянсу!\n\nТи {стать:найкращий:найкраща}, {ім'я}. Я тобі дуже вдячний.", ["en"] = "Jaina's Autograph", ["tasks"] = { ["Jaina's Autograph"] = "автограф Джайни", ["Jaina's Autograph (Provided)"] = "автограф Джайни (видано)" } },
    [5582] = { [1] = "Здорова луска дракона", [2] = "Це луска, що випала під час вилуплення зачумленого дракончика. Але на відміну від інших гнилих та вкритих слизом лусок, ця на диво здорова і неушкоджена.\n\nБетіна Біґґльзінк захоче отримати цей зразок для дослідження.", [3] = "Принесіть здорову луску дракона Бетіні Біґґльзінк у Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "{ім'я}, ти маєш щось для мене?", [5] = "Чудово! Це неоціненний інгредієнт для мого подальшого вивчення зловісних задумів Скари. Дякую, {ім'я}, якщо ти ще знайдеш подібні лусочки, будь ласка, принеси їх мені!", ["en"] = "Healthy Dragon Scale", ["tasks"] = { ["Healthy Dragon Scale"] = "здорова луска дракона", ["Healthy Dragon Scale (Provided)"] = "здорова луска дракона (видано)" } },
    [559] = { [1] = "Доказ Фаррена", [2] = "Можеш у це повірити, {ім'я}? Редпата не влаштували всі вбиті нами мурлоки — о, не скромничай, ти теж {стать:доклав:доклала} до цього руку. Тепер він хоче, щоб я приніс докази їхньої смерті. Щоб я відрубав холодні, слизькі голови мурлоків і приніс йому на огляд.", [3] = "Зберіть 10 голів мурлоків на Західному узбережжі для лейтенанта Фаррена Орінелла в Південнобережжі.", [4] = "Ти {стать:приніс:принесла} голови, {ім'я}?", [5] = "О, заради Світла... з них щось капає.\n\nЯ до них не доторкнуся. Риба — це добре, але коли у неї відростають ноги й вона починає ходити... Я не їв риби вже кілька тижнів, скажу я тобі, а в Південнобережжі це означає життя обголодь.", ["en"] = "Farren's Proof", ["tasks"] = { ["Murloc Head"] = "голова мурлока", ["Murloc Head (Provided)"] = "голова мурлока (видано)" } },
    [560] = { [1] = "Доказ Фаррена", [2] = "Знаєте, {ім'я}, я б хотів торкатися до цих голів... Раз вже вони в тебе, може віднесеш їх Редпату від мого імені?", [3] = "Принесіть мішок голів мурлоків маршалу Редпату в Південнобережжя.", [4] = "Вітаю тебе. Ти хочеш запропонувати свою допомогу в підтримці безпеки Південнобережжя?", [5] = "То ти на побігеньках у Фаррена?\n\nЯкщо ти {стать:допоміг:допомогла} Фаррену дістати ці голови, то дякую тобі. Південнобережжю потрібні такі захисники.", ["en"] = "Farren's Proof", ["tasks"] = { ["Sack of Murloc Heads"] = "мішок голів мурлоків", ["Sack of Murloc Heads (Provided)"] = "мішок голів мурлоків (видано)" } },
    [5601] = { [1] = "Сестра Памела", [2] = "Я втекла з Лордерону під час великої війни, і мені пощастило врятуватися до того, як Скара пробралася до моєї батьківщини та перетворила її на зачумлені руїни! Та моїй сім'ї не так пощастило, як мені. Я боюся, що всі вони загинули під час битви при Дарроуширі.\n\nДарроушир — це село у Східних Королівствах, нині розташоване на південних пагорбах Східних Зачумлених земель. Ти зможеш відправитися туди та відшукати мою сім'ю? Я дуже сумую за ними, особливо за моєю сестричкою Памелою.\n\nПрошу, знайди її!", [3] = "Знайдіть Памелу Редпат у Дарроуширі.", [5] = "Де моя сестричка Джессіка? Вона пішла так давно, коли я була ще зовсім маленькою дівчинкою. Вона так плакала, коли йшла звідси. Не знаю, чому. Може вона впала та забилась.\n\nРаніше ми з Джессікою разом бавилися, танцювали та збирали квіти навколо будинку. А інколи ми ховалися і чекали, коли татко прийде додому, а потім вискакували та лякали його!\n\nЯ хочу, щоб вона повернулася! Може, якщо вона повернеться, то повернеться і тато, і ми знову будемо бавитися разом...", ["en"] = "Sister Pamela" },
    [561] = { [1] = "Доказ Фаррена", [2] = "Будь ласка, повідом лейтенанту Орінеллу, що я хочу, щоб він зайнявся нагами, що заполонили Східне узбережжя. Коли у нього будуть результати, скажи йому, щоб він доповів мені особисто.", [3] = "Поговоріть з лейтенантом Фарреном Орінеллом у Південнобережжі.", [5] = "Наги, так? Редпат, мабуть, щойно отримав ту ж інформацію, що і я... Ха! Він не отримає підвищення через мою працю. Дозволь мені пояснити.", ["en"] = "Farren's Proof" },
    [563] = { [1] = "Перепризначення", [2] = "З моїм звітом не повинно бути жодних проблем. Новий капітан вартових, майор Самуельсон, був моїм наставником, коли я служив у Штормовії. Йому не важко буде перевести мене назад у столицю. Але доведеться попросити тебе віднести йому мій звіт... Головне, щоб старий Редпат ні про що не дізнався.", [3] = "Передайте звіт Фаррена майору Самуельсону у фортецю Штормовія.", [4] = "Вітаю тебе. Чим Штормовійська варта може тобі допомогти?", [5] = "А це що таке? А... так мій уважний учень зайнявся проблемою наг на Південнобережжі. Дякую, що {стать:приніс:принесла} мені це, я обов'язково візьму це до уваги, коли буду переглядати призначення наступного місяця.", ["en"] = "Reassignment", ["tasks"] = { ["Farren's Report"] = "звіт Фаррена", ["Farren's Report (Provided)"] = "звіт Фаррена (видано)" } },
    [564] = { [1] = "Серйозна загроза", [2] = "Ніщо так не злить мене, як втрата цих прекрасних коней. І повір мені, ми втратили їх чимало через цих набридливих мерців, клятих бандитів Синдикату та інших негідників, що нишпорять у цих краях.\n\nАле я присягаюся могилою мого прадідуся, що немає більшої загрози для наших коней, ніж гірські леви з Альтерака. Постійно спускаються з пагорбів і псують мені життя!\n\nВважаєш себе {стать:героєм:героїнею}? Тоді йди та розберися з ними!", [3] = "Даррен Малвей з Південнобрежжя просить вас вбити 8 гірських левів і 10 масивних гірських левів.", [4] = "Гірські леви вбивають наших коней направо і наліво, а ти тут теревениш про якісь дурниці.\n\nТреба мені піти й знайти справжніх героїв. Більше вбивай і менше базікай.", [5] = "Хіба це не чудова новина! Треба було відразу ж знайти старих-добрих героїв війни, які б з першого дня розібралися з цими звірами. Твій татко пишався б тобою, {ім'я}.", ["en"] = "Costly Menace", ["tasks"] = { ["Hulking Mountain Lion"] = "масивний гірський лев", ["Hulking Mountain Lion slain"] = "масивний гірський лев: убито", ["Mountain Lion"] = "гірський лев", ["Mountain Lion slain"] = "гірський лев: убито" } },
    [5721] = { [1] = "Битва при Дарроуширі", [2] = "А тепер, {ім'я}, ти візьмеш участь в битві при Дарроуширі та врятуєш Джозефа Редпата.\n\nРозмісти цей набір реліквій на площі Дарроушира, і духи цього міста повстануть з могил. Приєднайся до їхньої битви та переконайся, щоб Дейвіл вижив в битві з Горґусом, а Редпат став оскверненим, а потім вбитим.\n\nПісля перемоги над оскверненим Редпатом його дух буде врятовано. Поговори з ним, а потім повернися до його доньки Памели.", [3] = "Розмістіть набір реліквій на площі Дарроушира.\n\nЗапобіжіть смерті Дейвілу Сяйносвіту від Горґуса.\n\nЗапобіжіть смерті капітана Редпата до появи Редпата Оскверненого.\n\nПереможіть Редпата Оскверненого.\n\nПоговоріть з духом Джозефа Редпата, коли він з'явиться на площі, а потім поговоріть з Памелою в її домі.", [4] = "Там зовні зібралися злі духи. Їх шепіт мене лякає...", [5] = "Битва завершена! Мій тато сказав мені це. Він розігнав всіх духів і тепер повертається додому! Я така щаслива!\n\nА ще він сказав, щоб я зустріла тебе як {стать:гостя:гостю}, тож я зробила чаю!\n\nСподіваюся, ти любиш багацько цукру!", ["en"] = "The Battle of Darrowshire", ["tasks"] = { ["Accept Redpath's Forgiveness"] = "Прийміть прощення Редпата", ["Accept Redpath's Forgiveness (Provided)"] = "Прийміть прощення Редпата (видано)", ["Accept Redpath's Forgiveness slain"] = "Прийміть прощення Редпата: убито" } },
    [5725] = { [1] = "Сила руйнувати...", [2] = "Тобі певно вже відомо, що в Легіоні прийнято всіляко обдаровувати ідейних послідовників. Деяким з цих дарів краще б опинитися в руках у Темної Леді, ніж у... простаків.\n\nЯскравий приклад — секта Ради Тіні, що ховається в печерах під Орґріммаром, відома також як \"Випалений Клинок\". Леді повідомила, що вони отримали дві могутні книги заклять — вона хотіла б \"позичити\" їх. І ти дістанеш їх для неї.", [3] = "Принесіть книги \"Закляття Темряви\" і \"Чаклунство з Підсвіття\" Варіматрасу в Підмістя.", [4] = "Мене чекає сотня інших справ, {клас:к}. Де книги?", [5] = "Молодець, {клас:к}. Ти добре {стать:послужив:послужила} Темній Леді. Її підданим знадобляться твої завзятість і честолюбство. Повертайся до мене в майбутньому. Можливо, я відправлю тебе на нові подвиги, які допоможуть Темній Леді здолати Короля-ліча і звільнити рабів Скари.", ["en"] = "The Power to Destroy...", ["tasks"] = { ["Incantations from the Nether"] = "Чаклунство з Підсвіття", ["Incantations from the Nether (Provided)"] = "Чаклунство з Підсвіття (видано)", ["Spells of Shadow"] = "Закляття Темряви", ["Spells of Shadow (Provided)"] = "Закляття Темряви (видано)" } },
    [5729] = { [1] = "Таємні вороги", [2] = "Гадаю, тепер тобі варто наблизитись ближче до Нііру. Якщо він справді настільки схвильований, як про це кажуть у звітах — ми вб'ємо відразу двох зайців. По-перше, ти зможеш дізнатись більше про Раду або, принаймні, про Палаюче Лезо, а по-друге, він, можливо, почне довіряти тобі настільки, що попросить йому допомагати. Він зараз у відчаї, тож цілком може довіритись тобі.\n\nПовертайся в Розколину і поговори з ним знову, але не будь занадто {стать:відвертим:відвертою}.", [3] = "Поговоріть з Нііру Вогняним Лезом в Орґріммарі.", [5] = "Що таке?! О, це ти, {клас:к}... прошу вибачення. Я злий, як скажений кодо... але, можливо, я сам у цьому винен. Відправляючи мандрівників у прірву Лютого Полум'я, я мав передбачити, що це може призвести до проблем. Здається, що Баззалана та Єргоша застали зненацька і вбили якісь кляті добродії Тралла. Дуже невчасно, але з цим вже нічого не поробиш.", ["en"] = "Hidden Enemies" },
    [5730] = { [1] = "Таємні вороги", [2] = "Ти {стать:один:одна} з моїх лейтенантів! Тож приготуйся, {клас:к}. Скоро я викличу тебе.\n\nПевно, я даремно витратив час на Випалений Клинок, але це не означає, що від цього мають постраждати інші плани Ради Тіні. Я зроблю все, що зможу, щоб мінімізувати наслідки у прірві Лютого Полум'я. А тим часом мої агенти в Степах та Ясенедолі почнуть працювати над нашим новим планом. Повертайся до мене пізніше.", [3] = "Поговоріть з Траллом в Орґріммарі та розкажіть йому про все, що дізналися.", [5] = "Ясенеділ? Хм, я не чув про присутність Ради або Палаючого Леза в Ясенедолі. Я доручу своїм шпигунам це перевірити, {ім'я}. Ти добре {стать:попрацював:попрацювала}.\n\nА поки відпочивай і займися іншими справами. Незабаром я покличу тебе знову.\n\nЛок'тар оґар!", ["en"] = "Hidden Enemies" },
    [5741] = { [1] = "Скіпетр світла", [2] = "Ходять чутки, що клан Палаючого Леза, який розташований на сході у фортеці Грозової Сокири відібрав скіпетр світла у наг. Якщо вірити легенді, скіпетр здатен відправити цілі міста на морське дно. Не можна допустити, щоб Палаюче Лезо опанувало таку силу.\n\nТи маєш повернути скіпетр! Зараз він у провидця Палаючого Леза, він вивчає скіпетр на вершині однієї з вартових фортець Грозової Сокири.", [3] = "Дістаньте скіпетр світла та поверніть його Азору Альдаморту у вежу в Етель Ретор.", [4] = "Ти {стать:дістав:дістала} скіпетр світла?", [5] = "Невловний скіпетр світла! Повернувши його, ти {стать:позбавив:позбавила} світ від серйозної загрози. Молодець, {клас:к}, молодець.", ["en"] = "Sceptre of Light", ["tasks"] = { ["Sceptre of Light"] = "скіпетр світла", ["Sceptre of Light (Provided)"] = "скіпетр світла (видано)" } },
    [5742] = { [1] = "Спокута", [2] = "Ти тяжко {стать:працював:працювала}, {стать:друже:подруго}. Відпочинь, а я поки розповім тобі свою історію.", [3] = "Вислухайте розповідь Тіріона Фордрінґа.", [4] = "Прошу, {стать:друже:подруго}. Сідай та послухай мою розповідь.", [5] = "Спокути мого сина буде нелегко досягнути. Ти {стать:готовий:готова}?", ["en"] = "Redemption", ["tasks"] = { ["Tirion's Tale"] = "Оповідь Тіріона" } },
    [575] = { [1] = "Попит і пропозиція", [2] = "\"Найкращий шкіряний майстер Південних морів та старих і нових світів\". Так мене називають. Мене! Мжичника! Найкращого шкіря... Кхе. От.\n\nМої шкіряні вироби відомі в усьому світі як найвишуканіші, на думку експертів!\n\nЯ щойно отримав замовлення від директора Шарадника зі Спілки штукарів на дюжину його улюблених чобіт з лінійки \"Переможець\". Насправді це наша найпопулярніша модель.\n\nДля початку роботи мені знадобляться шкури кроколісків, що живуть вздовж річки на півночі Тернистої долини.", [3] = "Принесіть 2 великі шкури річкового кроколіска Мжичнику в Грабіжну Бухту.", [4] = "Моє обладнання вже готове до роботи, {ім'я:к}, мені лише потрібні ці шкури. І маю сказати, що не варто змушувати Шарадника чекати.\n\nНікому не вигідно залишати головного винахідника Спілки штукарів незадоволеним.", [5] = "Ці шкури повинні підійти. Їхня якість не надто важлива, враховуючи, що вони призначені для внутрішнього шару черевиків, але все ж важливо, щоб вони були зручними.\n\nЯкщо вони будуть занадто жорсткими, я додам трохи тигрової крові, щоб пом'якшити їх. Хитрощі шкірництва, розумієш?", ["en"] = "Supply and Demand", ["tasks"] = { ["Large River Crocolisk Skin"] = "велика шкура річкового кроколіска", ["Large River Crocolisk Skin (Provided)"] = "велика шкура річкового кроколіска (видано)" } },
    [576] = { [1] = "Хоч одним оком", [2] = "Стій! Хто йде?\n\nАррр, я безпорадний без мого особливого зачарованого ока. Мало того, що я втратив зір в бою! Але завдяки щасливому збігу обставин, ми причалили до Менетілів і мандрівний чарівник зачарував мені спеціальне скляне око, яке знову дозволило мені бачити.\n\nМинулої ночі на мене по дорозі напали пірати Кривавого Вітрила. Вони забрали моє око! Схоже, ці хлопці почувають себе в Грабіжній Бухті як вдома.\n\nДопоможеш старому морському псу повернути його око?", [3] = "Запаморок Одноокий з Грабіжної Бухти хоче, щоб ви відвоювали його око у піратів Кривавого Вітрила.", [4] = "Егей, друже! Може, я тебе й не бачу, але чую твій запах з іншої сторони порту.\n\nМені б не завадило моє око. Капітан протягне мене по кільватеру, коли дізнається, що воно в руках брудних піратів Кривавого Вітрила.\n\nЯка користь від вартового, що не бачить? Ґав'яче гніздо було моїм домом... Без очей мені в кращому випадку поручать вичищати трюм.", [5] = "Якір мені в селезінку і селезінку мою на якір! Ти {стать:знайшов:знайшла} моє прекрасне око! Подивимося, чи підійде воно мені.\n\n{ім'я}, йо-хо! Чорт забирай, я бачу!!", ["en"] = "Keep An Eye Out", ["tasks"] = { ["Dizzy's Eye"] = "око Запаморока", ["Dizzy's Eye (Provided)"] = "око Запаморока (видано)" } },
    [5762] = { [1] = "Гемет Ернінґвей", [2] = "У мене є посилка для мого старого клієнта, дворфа, на ім'я Гемет Ернінґвей. Посилка йшла кілька тижнів, а до цього часу Гемет вже відправився у справах. Він сказав, що збирався відправитися на полювання до Тернистої долини. Але він залишив мені пару монет, щоб я надіслав йому його посилку.\n\nГемет багатий дворф, а з багатими варто підтримувати стосунки, еге ж? Тож... чи не хочеш доставити посилку за мене?\n\nЯ чув, що Гемет став табором у Тернистій долині, на північ від Ґром'ґола.", [3] = "Віднесіть ящик Крейвела Гемету Ернінґвею в Тернисту долину.", [4] = "Це що, пустельний пил у тебе на комірі?\n\nГм... якщо мій ніс мене не підводить, я б сказав, що це пустельна сіль! Ти {стать:був:була} на Мерехтливих рівнинах?", [5] = "Чудово, моя посилка від Вуглеборода! Дякую тобі, {ім'я}. Цей ящик містить в собі набої особливого калібру, які добре нам послужать в джунглях!\n\nОсь твоя плата, і скажи мені, як там поживає Крейвел? Напевно знову замислює щось пакосне...", ["en"] = "Hemet Nesingwary", ["tasks"] = { ["Kravel's Crate"] = "ящик Крейвела", ["Kravel's Crate (Provided)"] = "ящик Крейвела (видано)" } },
    [577] = { [1] = "Збір шкури", [2] = "Що ж, я розробив основу черевиків, і все йде добре, але шкур, які ти {стать:приніс:принесла}, не вистачить на внутрішні шари.\n\n\"Що ж нам робити, Мжичнику?\" Не сумніваюсь, це питання у тебе на вустах і тобі пощастило, що ти розмовляєш з Мжичником, адже він скаже, що нам робити!\n\nВнутрішні шари ніколи ніхто не побачить, тож для них ми просто візьмемо кілька товстих, дешевих шкур кроколісків з озера Назферіті.", [3] = "Принесіть 5 шкур кроколіска-тріскощелепа Мжичнику в Грабіжну Бухту.", [4] = "Шкіряні черевики \"Переможець\", найтоншої роботи, зі шкіри морського кроколіска найвищої якості від Мжичника. Кращих просто не існує!\n\nНеможливо встояти перед таким блискучим описом, чи не так?\n\nОтож, ти {стать:приніс:принесла} мені ці шкури?", [5] = "Мої чоботи... вони як сосиски, {ім'я}. На вигляд чудово і на смак чудово. Кажу тобі, вони наповнені лише найкращими інгредієнтами, ти їси їх і тобі це подобається.\n\nБуде приємніше, якщо просто довіритись мені та не розпитувати, чим насправді наповнені чоботи.", ["en"] = "Some Assembly Required", ["tasks"] = { ["Snapjaw Crocolisk Skin"] = "шкура кроколіска-тріскощелепа", ["Snapjaw Crocolisk Skin (Provided)"] = "шкура кроколіска-тріскощелепа (видано)" } },
    [5781] = { [1] = "Забуті спогади", [2] = "Щоб допомогти Телану, ти мусиш повернути речі з його минулого.\n\nОдна з цих речей — іграшка, яку я йому подарував йому на семиріччя. Він обожнював цей маленький бойовий молот. Власне, це була зменшена копія моєї власної зброї.\n\nКоли мене вигнали за мою зраду, його мати сказала йому, що я загинув. Його відвели до моєї порожньої могили біля Підцарини, де він і залишив молот та усі спогади про мене.\n\nТи маєш відправитися туди та повернути молот Телана.", [3] = "Відправляйтеся в Підцарину в південній частині Східних Зачумлених земель та дістаньте молот Телана. Поверніться до Тіріона Фордрінґа та віддайте йому молот.", [4] = "Ми маємо врятувати його.", [5] = "<Тіріон кліпає очима, щоб стримати сльози.>\n\nНас звела сама доля, {ім'я}. Ти {стать:благословив:благословила} мене своєю добротою.", ["en"] = "Of Forgotten Memories", ["tasks"] = { ["Taelan's Hammer"] = "молот Телана", ["Taelan's Hammer (Provided)"] = "молот Телана (видано)" } },
    [579] = { [1] = "Бібліотека Штормовію", [4] = "Король Андуїн приділив велику увагу освіті та всіляко піклувався про те, щоб городяни мали доступ до копій цінних книг. Все просто: принеси мені бібліотечний сувій, і я видам тобі копію будь-якої книги.", [5] = "Яка книга цікавить тебе, {ім'я}?", ["en"] = "Stormwind Library", ["tasks"] = { ["Library Scrip"] = "бібліотечний сувій", ["Library Scrip (Provided)"] = "бібліотечний сувій (видано)" } },
    [580] = { [1] = "Загублений грог Віскі Пронози", [2] = "Коли ми підходили до Оглядових круч, якраз в той момент, коли старі добрі Внутрішні землі з'явились вдалині, ми потрапили в страшенну бурю. Ми думали, що нас поглине море.\n\nСтарий Проноза знає все про рідку хоробрість! У капітана був ящик портвейну \"Пупеллівербос\", який ми захопили у корсара по дорозі до Штормовію.\n\nТож коли біля Внутрішніх земель почався шторм, я насів на грог. І тут вдарила велика хвиля і викинула пляшки за борт. Капітан покарає мене, якщо ти не допоможеш мені їх повернути!", [3] = "Віскі Проноза з Грабіжної Бухти хоче, щоб ви принесли йому втрачені пляшки портвейну \"Пупеллівербос\".", [4] = "Розрази мене грім! У мене майже закінчилася випивка! Капітан збирається кинути якір, і старий Проноза буде сухим, як пустеля Танаріс. А коли він дізнається, що його портвейн зник... Щоб я провалився!", [5] = "Якір мені в селезінку! Ти {стать:знайшов:знайшла} грог капітана!\n\nЯ твій боржник, {стать:друже:подруго}.\n\nЗдається, зовні назріває шторм. Може, я просто зігріюся однією з цих пляшок, поки ми чекаємо....", ["en"] = "Whiskey Slim's Lost Grog", ["tasks"] = { ["Pupellyverbos Port"] = "портвейн \"Пупеллівербос\"", ["Pupellyverbos Port (Provided)"] = "портвейн \"Пупеллівербос\" (видано)" } },
    [5801] = { [1] = "Кузня Вогнеперої скелі", [2] = "Тобі потрібні два злитки торію та потужне джерело тепла, щоб викувати основу ключа. Торій знайди самостійно, а з нагрівом я можу допомогти.\n\nНа заході, в кратері Ун'Ґоро, є Вогнепера скеля — киплячий вулкан. Лавове озеро нагорі достатньо гаряче, щоб сплавити торій з кістками. Твої гроші витрачені не дарма — цю форму можна просто занурити в вогняне озеро, а все інше зробить лава.\n\nЦе все, чим я можу тобі допомогти. Арбінґтон розкаже тобі, як завершити ключ.", [3] = "Віднесіть форму для скелетного ключа та 2 злитки торію на вершину Вогнеперої скелі в кратер Ун'Ґоро. Використовуйте форму для скелетного ключа біля озера лави, щоб викувати незавершений скелетний ключ.\n\nВіднесіть незавершений скелетний ключ алхіміку Арбінґтону у пролісок Студовій, що в Західних Зачумлених землях.", [4] = "Тобі вдалося зробити основу скелетного ключа? Мені шкода, що ти {стать:мусив:мусила} купувати форму за власні гроші, але кожен з нас має робити свій внесок у боротьбу зі Скарою. Якщо ти віддаси мені незавершений ключ, ти будеш {стать:готовий:готова} до останньої деталі, необхідної для його завершення.\n\nЦе важке завдання, але твоя підготовка до нападу на Андорал не пройде даремно. Ось побачиш.", [5] = "Недешево обійшлася тобі ця основа скелетного ключа, еге ж, {ім'я}? Проте він залишається незавершеним. Прийшов час останнього етапу, а він найскладніший. Для завершення ключа тобі доведеться зіткнутися з головним ворогом, що чекав на нас в Андоралі... з мерзенною істотою, що керує руїнами міста.\n\nЯ маю на увазі Аража-Закликача — ліча, одне з найпотужніших створінь Скари.", ["en"] = "Fire Plume Forged", ["tasks"] = { ["Unfinished Skeleton Key"] = "незавершений скелетний ключ", ["Unfinished Skeleton Key (Provided)"] = "незавершений скелетний ключ (видано)" } },
    [5803] = { [1] = "Скарабей Аража", [2] = "Араж-Закликач править Андоралом з серця зруйнованого міста. Ми знаємо, що він був лідером Некроситету, поки не захопив місто. Щоб завершити ключ, нам потрібен його перстень — він називається скарабеєм — це буде головка ключа.\n\nВідправляйся в саме серце Андорала та позбав його влади над містом. Як вб'єш його, витягни скарабея з його філактерії.\n\nКлюч до Некроситету чекає, {ім'я}!", [3] = "Вбийте Аража-Закликача та принесіть скарабея Аража алхіміку Арбінґтону в пролісок Студовій, що в Західних Зачумлених землях.", [4] = "Ти {стать:зайшов:зайшла} досить далеко, {ім'я}, але лиш знищення Аража-Закликача дозволить нам завершити ключ. Забери скарабея Аража, чого б тобі це не вартувало, та принеси його мені — я зроблю з нього головку ключа.", [5] = "Так, це він! Я... знову ж таки, вражений глибиною твого героїзму. Це просто вражає, на що ти {стать:здатен:здатна} піти, щоб досягти перемоги над силами темряви.\n\nТепер дозволь мені відіграти свою роль. Я приготував особливий розчин, який дозволить мені закріпити скарабея на ключі. Ця сила зможе відчинити двері в Некроситеті.\n\nЦе займе лиш мить...", ["en"] = "Araj's Scarab", ["tasks"] = { ["Araj's Scarab"] = "скарабей Аража", ["Araj's Scarab (Provided)"] = "скарабей Аража (видано)" } },
    [5821] = { [1] = "Найманий охоронець", [2] = "Зазвичай ми з Монтером провели б кодо повз Колкарів. Час від часу лунають бойові барабани кентавра і коли ми їх чуємо, ми зупиняємося, щоб перечекати небезпеку. Бути мертвим погано для бізнесу!\n\nОт, що я скажу тобі, {клас:к}, якщо ти захистиш та проведеш нас через поселення Колкарів, ми тобі за це добре заплатимо.\n\nТут невелика відстань, все, що тобі потрібно зробити, це зберегти караван неушкодженим і ти зможеш забрати свою винагороду у Сміда Гвинтодряпа — він живе трохи далі по дорозі. Ми з ним партнери по бізнесу.", [3] = "Проведіть караван Ґізельтона через поселення Колкарів. Поговоріть зі Смідом в таборі Гвинтодряпа, щоб отримати винагороду.", [4] = "Чому я чекаю на цей клятий караван?\n\n<Смід замислюється.>\n\nА, так, вони оплачують рахунки. {стать:Бачив:Бачила} цих типів?", [5] = "Знаєш, мені не сильно подобається платити таким, як ти за охорону каравану Ґізельтона. {Клас:к}, якби я був трохи вищим, я міг би взяти ще одну роботу: сидів би в сідлі на боці кодо з найбільшою рушницею, яку тільки можна тримати в руках... так, я б показав цим проклятим кентаврам, де раки зимують...", ["en"] = "Bodyguard for Hire", ["tasks"] = { ["Escort Gizelton Caravan past Kolkar Centaur Village"] = "Супровід каравану Gizelton повз село кентаврів Колкар" } },
    [583] = { [1] = "Ласкаво просимо до джунглів", [2] = "Ласкаво просимо до Тернистої долини!\n\nМожливо, ти не знаєш, але отой дворф — єдиний і неповторний Гемет Ернінґвей, славетний герой Альянсу і майстерний мисливець на велику дичину. Він не з тих, хто радий незнайомцям у своєму таборі, але ти виглядаєш так, ніби {стать:бачив:бачила} чимало за своє життя, {клас:к}.\n\nЯк ветеран багатьох битв, майстер Ернінґвей має слабкість до колег-героїв.\n\nІди та поговори з ним. Можливо, він дасть тобі кілька порад щодо полювання.", [3] = "Поговоріть з Геметом Ернінґвеєм.", [5] = "Дуже приємно познайомитися, {ім'я}. Давненько я не бачив {клас:з} у наших краях.\n\nЯ пішов в цю експедицію з однією метою: вполювати великого і невловного звіра. Враховуючи, що ти теж свого роду {стать:герой:героїня}, я дозволю тобі взяти участь у полюванні. Але спершу ти маєш показати себе.\n\nЯ навчу тебе, як вбивати раптора. Барвина навчить тебе вистежувати тигрів. А пан Имин — полювати на пантер.\n\nДоведи свою майстерність і я візьму тебе на велике полювання.", ["en"] = "Welcome to the Jungle" },
    [5845] = { [1] = "Втрачена честь", [2] = "Зі смертю Утера орден Сріблястої Десниці втратив бойовий дух.\n\nМій хлопчик тримався до останнього. Але, відступаючи до понівеченого війною Північнодолу, він прийняв остаточне рішення.\n\n\"Чи вижив хтось з ордену, — подумав він, — і чи це взагалі важливо?\"\n\nЗ цією думкою Телан кинув стяг ордену на землю та відрікся від усього, що колись цінував. Його честь лишилася в просякнутій кров'ю землі Північнодолу.\n\nТи маєш відправитися туди та повернути символ втраченої честі.", [3] = "Відправляйтеся до Північнодолу, на північний схід Східних Зачумлених земель, та поверніть символ втраченої честі. Поверніться до Тіріона Фордрінґа коли виконаєте завдання.", [4] = "Моя віра направить тебе, {ім'я}. У Світла немає меж.", [5] = "Навіть у такому стані воно таке ж прекрасне, як і того дня, коли я складав присягу на вірність.\n\nМожливо, разом з його спокутою прийде й моя...", ["en"] = "Of Lost Honor", ["tasks"] = { ["Symbol of Lost Honor"] = "символ втраченої честі", ["Symbol of Lost Honor (Provided)"] = "символ втраченої честі (видано)" } },
    [5846] = { [1] = "Сімейна любов", [2] = "Коли Телан був дитиною, ми часто відвідували острів Тверджа Дарроу. Під час нашого останнього візиту, художниця, на ім'я Ренфрі, намалювала наш портрет, як ми стоїмо на пляжі. Це мій найтепліший спогад про Таелана та Карандру. Бо саме тоді, стоячи поруч з дружиною та сином, я відчув глибоку сімейну любов... любов, яку я більше ніколи не відчую.\n\nЯкщо ця картина все ще існує, ти маєш знайти її.\n\nВідправляйся на острів Тверджа Дарроу та дізнайся, чи лишилася там картина, чи художниця.", [3] = "Відправляйтеся на острів Тверджа Дарроу, в південно-центральній частині Зачумлених земель, та знайдіть будь-які підказки щодо місцеперебування картини.", [5] = "Як я могла забути? Більшість духів цього острова приречені знову й знову переживати останні щасливі спогади перед своєю трагічною загибеллю.\n\nЯ занадто проклята, але не так, як вони — я та, хто пам'ятає все...\n\nМожливо, саме ця річ, яка тебе цікавить, тримає мене прикутою до цих руїн. Можливо, якщо я розповім тобі про цю річ, це дарує мені свободу.", ["en"] = "Of Love and Family" },
    [5848] = { [1] = "Сімейна любов", [2] = "Ця картина...Вона висіла на стіні моєї майстерні, всередині казарм ордену, роками.\n\nПісля суду над Тіріоном я зрозуміла, що не більше не можна тримати її на виду. Я сховала її там, де її ніколи не знайдуть.\n\nВирушай в Стратгольм і пройди углиб того, що зараз називається Багряним бастіоном. Знайди там картину двох місяців. Зніми зайву фарбу і побачиш мій шедевр - \"Сімейну любов\".\n\nНехай Світло направляє тебе.", [3] = "Вирушайте до Стратгольма в північну частину Зачумлених земель. Знайдіть в Багряному бастіоні картину \"Сімейна любов\", заховану за іншим полотном, що зображає місяці Азерота.\n\nПоверніться з картиною до Тіріона Фордрінґа.", [4] = "Картина, {ім'я}. Ти {стать:знайшов:знайшла} її?", [5] = "<Тіріон падає навколішки, коли бачить картину.>\n\n<Він починає плакати, не приховуючи сліз.>", ["en"] = "Of Love and Family", ["tasks"] = { ["Of Love and Family"] = "Сімейна любов", ["Of Love and Family (Provided)"] = "Сімейна любов (видано)" } },
    [5861] = { [1] = "Знайти Міранду", [2] = "{ім'я}, ти {стать:виконав:виконала} все, про що я тебе просив. Лишився всього один крок до спокути.\n\nТи маєш віднести всі зібрані тобою предмети Телану. На жаль, Телан та його лицарі Багряного Походу нападуть на тебе щойно побачать.\n\nЄ тільки один шлях доставити мого листа — обман.\n\nНа південь звідси ти знайдеш могилу Утера. Там проживає моя довірена особа, Міранда. Знайди її та покажи зібрані тобою предмети, і вона допоможе тобі.", [3] = "Відправтеся до могили Утера, що знаходиться на півдні Зачумлених земель. Покажіть відьмі Міранді подарунок Тіріона.", [4] = "Я знала, що цей день настане.", [5] = "Я була довіреною радницею Тіріона в той час, як він утримував посаду лорда Марденгольда. Я відкрито відреклася від вердикту ордену Сріблястої Десниці й мене вигнали за непокору.\n\nТіріон пройшов через великий біль та розчарування у своєму житті, {раса:к}. Чи {стать:готовий:готова} ти виправити біди Фордрінґів?", ["en"] = "Find Myranda", ["tasks"] = { ["Tirion's Gift"] = "подарунок Тіріона", ["Tirion's Gift (Provided)"] = "подарунок Тіріона (видано)" } },
    [5862] = { [1] = "Обман Багряного Походу", [2] = "Я, як мене кличуть, ілюзіоністка. Я можу створити ілюзію, яка дозволить тобі пройти до Вогнедолу, але будь {стать:обережним:обережною}, мої сили мають свої межі.\n\nЯкщо ти зайдеш надто далеко від цих земель, дія моєї ілюзії припиниться. Заклинання вимагає від мене великої концентрації та сили, і такий ефект я не зможу утримувати надто довго.\n\nПоговори зі мною, як будеш {стать:готовий:готова}.", [3] = "Поговоріть з Мірандою, щоб вона наклала на вас ілюзію Багряного Походу. Перебуваючи під дією ілюзії, відправляйтеся до Вогнедолу та передайте подарунок Тіріона верховному повелителю Телану Фордрінґу.\n\nВогнеділ знаходиться на півночі, Телан має бути всередині фортеці Марденгольд.", [4] = "Ти {стать:прибув:прибула} з підкріпленням з Десниці Тіра?", [5] = "Що це, солдате?\n\n<Телан відкриває коробку та починає розглядати вміст.>\n\nЦе... цього не може бути. Але... все, що ти {стать:показав:показала} мені...\n\n<Телан падає на коліно, його серцебиття прискорюється. Лють віків ось-ось вивільниться на це місто.>", ["en"] = "Scarlet Subterfuge", ["tasks"] = { ["Tirion's Gift"] = "подарунок Тіріона", ["Tirion's Gift (Provided)"] = "подарунок Тіріона (видано)" } },
    [5863] = { [1] = "Поселення Піщаного Молота", [2] = "Зовсім недавно в Танарісі з'явилась велика кочівна група огрів. Вони зайняли велику частину пустелі на південь звідси та створили поселення. Наразі пустелею блукає кілька менших груп, деякі з них захопили старі руїни тролів.\n\nПоселення Піщаного Молота повинно бути знищене! Ми не можемо дозволити ограм зібратися з силами.\n\nЛідер цієї банди — Ґор'марок-Руйнівник, і я вважаю, що кінець його правління стане початком кінця огрів.", [3] = "Анді Лінн з Пристробляху просить вас знищити поселення Піщаного Молота, вбивши 10 моцаків Піщаного Молота, 10 громил Піщаного Молота і Ґор'марока-Руйнівника.", [4] = "Я так хвилююся! Будь ласка, будь {стать:обережним:обережною}!", [5] = "Я дуже рада, що ти {стать:зміг:змогла} зробити це для мене, {ім'я}! Дякую за допомогу!", ["en"] = "The Dunemaul Compound", ["tasks"] = { ["Dunemaul Brute"] = "моцак Піщаного Молота", ["Dunemaul Brute slain"] = "моцак Піщаного Молота: убито", ["Dunemaul Enforcer"] = "громило Піщаного Молота", ["Dunemaul Enforcer slain"] = "громило Піщаного Молота: убито", ["Gor'marok the Ravager"] = "Ґор'марок-Руйнівник", ["Gor'marok the Ravager slain"] = "Ґор'марок-Руйнівник: убито" } },
    [587] = { [1] = "Нюхальний тютюн", [2] = "Ох, життя моряка. Не скажу, що це гарне життя, але це моє життя.\n\nКоли я швартуюсь в порту, люблю дістати собі пляшку хорошого грогу і якісного тютюну. Так, погані звички, але що за пірат без вад, чи не так?\n\nТож можеш собі уявити, як я розчарувався, коли дізнався, що місцевий травник розпродав усе своє зілля. Каже, що його вантаж викрали ті кляті розбійники з \"Кривавих вітрил\".\n\nБ'юся об заклад, що {стать:такий безстрашний:така безстрашна} {клас:н}, як ти, {стать:міг:могла} би переконати їх поділитися товаром, правда ж?", [3] = "Діґ з Грабіжної Бухти хоче, щоб ви принесли йому 15 понюшок тютюну.", [4] = "Вдалося знайти щось, {стать:приятелю:приятелько}?", [5] = "Гарна робота, {ім'я}! І якраз перед тим, як мені треба відпливати! Не знаю, як тобі віддячити, {стать:старий друже:стара подруго}.", ["en"] = "Up to Snuff", ["tasks"] = { ["Snuff"] = "понюшка тютюну", ["Snuff (Provided)"] = "понюшка тютюну (видано)" } },
    [5904] = { [1] = "Чуму на вас!", [2] = "Тепер, коли ми маємо вдосталь термітів, віднеси цю укріплену сталлю бочку до лісопильні Північного кряжу, що на півдні від Вогнедолу — ти знайдеш її на заході від дороги, що веде до цього містечка.\n\nЯк будеш там — постав бочку в центрі лісопильні, на щось високе, як ящик чи щось подібне. Терміти зроблять свою справу і Багряний Похід не зможе використовувати лісопильню.", [3] = "Знайдіть зручне місце в центрі лісопильні Північного кряжу в Західних Зачумлених землях, щоб розмістити там бочку з термітами Зачумлених земель.", [5] = "Терміти явно починають метушитись, коли ви ставите бочку на ящик.", ["en"] = "A Plague Upon Thee", ["tasks"] = { ["Barrel of Plagueland Termites"] = "бочка з термітами Зачумлених земель" } },
    [593] = { [1] = "Наповнення каменя душі", [4] = "Єнніку стоїть перед вами, він приголомшений, а його розум далеко звідси...", [5] = "Ви торкаєтесь каменем душі до його чола. Єнніку здригається, коли його душа всмоктується в камінь, залишаючи за собою лише тіло — бездушну оболонку.", ["en"] = "Filling the Soul Gem", ["tasks"] = { ["Soul Gem"] = "камінь душі", ["Soul Gem (Provided)"] = "камінь душі (видано)" } },
    [594] = { [1] = "Послання в пляшці", [2] = "Записка написана досить гарним почерком:\n\n\"Будь-кому, хто може мені допомогти...\n\nБудь ласка, мені дуже потрібна допомога. Великий небогрив тримає мене в полоні на острові в Південних морях.\n\nВночі я дивлюсь на чужі мені зорі, напівзакриті деревами джунглів, але в найясніші дні я бачу Бурхливий берег на північному заході, а на південному заході — великі кораблі з вітрилами.\n\nБлагаю тебе, мій майбутній рятівник, будь ласка, допоможи мені.", [3] = "Знайдіть автора послання в пляшці.", [5] = "Ти {стать:прийшов:прийшла} звільнити мене?", ["en"] = "Message in a Bottle" },
    [5941] = { [1] = "Повернення до Хромі", [2] = "Ти {стать:зібрав:зібрала} багато реліквій битви при Дарроуширі. Щоразу, коли ти {стать:повертався:поверталася} до мене з ними, моє серце тужило за моїм домом... прагнуло захистити його від долі.\n\nЯ знаю, що це неможливо, але Хромі, ця дивна гномка з Андорала, каже мені, що це цілком можливо. Вона каже, що ти можеш врятувати Дарроушир!\n\nХромі попросила мене зібрати реліквії та передати тобі. Вона чекатиме тебе в зруйнованій таверні Андорала.", [3] = "Принесіть набір реліквій до Хромі в Андорал.", [4] = "Я говорила з твоїм другом Карліном. Йому дуже боляче за долю свого селища, але він вірить, що ти можеш змінити долю Дарроушира.\n\nОх, я відходжу від теми... {ім'я}, ти {стать:приніс:принесла} реліквії, про які я просила?", [5] = "Так, ось і вони. Разом вони створять потужне заклинання, яке підніме дух Дарроушира.\n\nЗ цим заклинанням та крихтою удачі, ми зможемо врятувати Джозефа Редпата!", ["en"] = "Return to Chromie", ["tasks"] = { ["Bundle of Relics"] = "набір реліквій", ["Bundle of Relics (Provided)"] = "набір реліквій (видано)" } },
    [5942] = { [1] = "Сховані скарби", [2] = "Тато сказав передати тобі цей ключ. Він сказав, що ним можна відкрити скриню за будинком.\n\nА ще він просив подякувати тобі. Не знаю, щоправда, за що — може, він знає, що ти {стать:знайшов:знайшла} мою ляльку?\n\nНу що ж, ось ключ. І дякую, {ім'я}. Дякую! Ти дуже {стать:хороший:хороша}!", [3] = "Відкрийте скриню Джозефа його ключем.", [4] = "Ця скриня стара та вкрита брудом.", [5] = "Ключ підходить до замка, і скриня відчиняється...", ["en"] = "Hidden Treasures", ["tasks"] = { ["Joseph's Key"] = "ключ Джозефа", ["Joseph's Key (Provided)"] = "ключ Джозефа (видано)" } },
    [5943] = { [1] = "Караван Ґізельтона", [2] = "Ти виглядаєш {стать:здібним:здібною} {раса:о}. Можливо, ти хочеш заробити трохи грошей? Ми з Короком створили цей караван, щоб заробити купу грошей, щоправда, потім ми дізнались, наскільки це може бути небезпечно.\n\nПопереду руїни Маннорок... Зазвичай демони нас ігнорують, але цього разу щось неабияк налякало кодо. Я заплачу тобі за охорону каравану. Як тільки ми безпечно пройдемо руїни Маннорок, ти отримаєш свою винагороду від нашого ділового партнера Сміда в таборі Гвинтодряпа.", [3] = "Проведіть караван Ґізельтона через руїни Маннорок. Поговоріть зі Смідом у таборі Гвинтодряпа, щоб отримати нагороду.", [4] = "Знаєш, якщо з цим караваном що-небудь станеться, я розорюсь! Ти ж не {стать:приніс:принесла} погані новини про караван?\n\n<Смід витирає лоба.>\n\nХвала богині жадібності!", [5] = "Не впевнений, що за охорону каравану Ґізельтона варто платити такі гроші. Зрештою, Корок і Монтер заробляють лише по одному золотому на тиждень. Але поки вони платять за кодо, мені байдуже, як вони ведуть свої справи.", ["en"] = "Gizelton Caravan", ["tasks"] = { ["Escort Gizelton Caravan past Mannoroc Coven"] = "Проведіть Караван Гізелтона повз Маннорок Ковен" } },
    [5944] = { [1] = "Уві сні", [2] = "Я так довго був маріонеткою верховного лицаря. Який сенс битися проти того, на що перетворився Багряний Похід? Минули десятиліття, але спогади про мого батька, ці прекрасні спогади — це єдине, що тримає мене в живих.\n\nВін з'являється в моїх снах, {стать:незнайомцю:незнайомко}. В них мій батько зі мною. Він стоїть та з гордістю дивиться на те, як мене приймають до ордену. Ми пліч-о-пліч б'ємося проти цілого легіону Скари, приносячи славу Альянсу і Лордерону.\n\nЯ не хочу більше жити уві сні.\n\nВідведи мене до батька.", [3] = "Виведіть Телана Фордрінґа з Вогнедолу.", [4] = "<Тіріон заспокоюється.>", [5] = "Смерть мого сина не пройде цим чудовиськами даремно. Нехай нас втішить знання про те, що Орден відроджується.\n\nЯ займу місце верховного повелителя Ордену Сріблястої Десниці.\n\nЦі речі з мого минулого — це все, що я можу запропонувати за все, що ти {стать:зробив:зробила}. Будь ласка, візьми це як символ моєї вдячності. Всі ці речі служили мені протягом багатьох років.\n\nНехай ми зустрінемося знову, в кращі часи, та будемо згадувати давнє минуле... важкі битви... спокуту.", ["en"] = "In Dreams", ["tasks"] = { ["Redemption?"] = "Викуплення?" } },
    [595] = { [1] = "Пірати Кривавого Вітрила", [2] = "Схоже, ти дуже хочеш попрацювати, {стать:приятелю:приятелько}. Не знаю, чому {стать:якийсь сухопутний:якась сухопутна} {раса:н} пропонує допомогу рейдерам Чорноводдя, але я не буду тебе відмовляти.\n\nНаш корабель щойно пришвартувався тут, у Грабіжній Бухті й ходять чутки, що наших суперників — тих клятих, брудних піратів Кривавого Вітрила — зустрічають по всьому півдню Тернистої долини.\n\nВсі мої хлопці надто зайняті грогом та пошуком дівчат! А мені потрібен розвідник.\n\nПеревір затоку на північ від Грабіжної Бухти, вздовж Дикого узбережжя і розкажи мені про все, що там побачиш.", [3] = "Перший помічник Кразз хоче, щоб ви оглянули затоку на північ від Грабіжної Бухти.", [5] = "На бочці лежить мапа з нашвидкуруч написаним текстом і трохи монет.", ["en"] = "The Bloodsail Buccaneers" },
    [597] = { [1] = "Пірати Кривавого Вітрила", [2] = "На карті позначеня Грабіжна Бухта, а також червоний хрест, намальований саме в тому місці, де ви стоїте.\n\nНа карті написано:\n\n\"Отаборіться на цьому місці та сидіть тихо. Дочекайтесь сигналу з південного командного пункту, перш ніж атакувати. Якщо хтось наблизиться — вбивайте на місці\".", [3] = "Повідомте про свої знахідки першому помічнику Краззу в Грабіжній Бухті.", [5] = "Звісно я пам'ятаю тебе, {клас:к}. Бачу, ти вже {стать:повернувся:повернулася} з розвідки...", ["en"] = "The Bloodsail Buccaneers" },
    [599] = { [1] = "Пірати Кривавого Вітрила", [2] = "Якір мені в селезінку! Кажеш, Криваві Вітрила планують якийсь напад на Грабіжну Бухту? Що за нахабні мерзотники. Грабіжна Бухта завжди буде належати рейдерам Чорноводдя!\n\nСправи гірші, ніж я думав. Негайно повідом про все, що ти {стать:дізнався:дізналася} командувачу флоту Морському Рогу! Старий морський пес десь у місті.", [3] = "Повідомте про заплановану атаку Кривавого Вітрила командувачу флоту Морському Рогу.", [5] = "Криваві Вітрила атакують Грабіжну Бухту? З таким же успіхом вони могли б кинутися з Оглядових круч. Проте, повідомивши мені цю інформацію, ти {стать:зробив:зробила} велику послугу для мого флоту шибайголів. Рейдери Чорноводдя вдячні тобі.", ["en"] = "The Bloodsail Buccaneers" },
    [600] = { [1] = "Копальня ТзНБ \"Авантюра\"", [2] = "ТзНБ \"Авантюра\" проводить свої операції в Тернистій долині, які заважають працьовитим гоблінам, таким як я, чесно заробляти золото! Прошу тебе, ти {стать:повинен:повинна} мені допомогти!\n\nТзНБ \"Авантюра\" видобуває золото біля Кришталевої копальні на північ звідси. Вони не можуть потрапити в шахту через василіска, але вони все одно примудряються викопувати співочі кристали з навколишніх пагорбів.\n\nЗабери у них кристали й дай їм зрозуміти, що вони не можуть керувати джунглями.\n\nІ... кхм... як доказ, принеси мені ці кристали!", [3] = "Принесіть 10 співочих блакитних кристалів Вибрику Бульчуку в Грабіжну Бухту.", [4] = "Ти {стать:дістав:дістала} ті кристали? Вони мені потрібні!!!\n\nТобто... Мені потрібно знати, що клята ТзНБ \"Авантюра\" втрачає землі в Тернистій долині. Тому що нам, чесному народу, треба заробляти на життя!", [5] = "Чудово! Прекрасно! Я зароблю на них цілу купу!!\n\nТзНБ \"Авантюра\" вибрала не ті джунглі для копання, еге ж? Нам усім було б краще, якби вони забралися звідси.\n\nСпасибі тобі, {ім'я}. Ти сьогодні {стать:зробив:зробила} добру справу.", ["en"] = "Venture Company Mining", ["tasks"] = { ["Singing Blue Crystal"] = "співочий блакитний кристал", ["Singing Blue Crystal (Provided)"] = "співочий блакитний кристал (видано)" } },
    [6004] = { [1] = "Незавершена справа", [2] = "Мене відправили на розвідувальну місію для оцінки оборону Вогнедолу. Багато хто в Альянсі вважає, що це маленьке місто має більше, ніж історичне значення. Не моя справа ставити під це сумнів, але в будь-якому разі я зараз не в змозі продовжувати завдання, поки не відпочину.\n\nЯкщо хочеш, я добре заплачу за допомогу. Почни на південь звідси, біля табору Багряного Походу. Якщо ти виявишся досить {стать:сильним:сильною}, можливо, я зможу попросити тебе про допомогу з моїм головним завданням.", [3] = "Вбийте 2 медиків, 2 мисливців, 2 магів та 2 лицарів Багряного Ордену, після чого поверніться до Кірсти Чорнотіні в Західні Зачумлені землі.", [4] = "Як воно, {ім'я}? Вони виявилися сильнішими, ніж ти {стать:думав:думала}? Сподіваюся, що ні. Якщо я збираюсь довести справу до кінця, це завдання потребуватиме до біса більше сил, ніж я попросила в тебе.", [5] = "Молодець, {ім'я}. Я вражена, наскільки ти швидко {стать:впорався:впоралася} з ними. Дякую.\n\nЯ поки не зустріла нікого, хто б схвалював Багряний Похід та його методи. Я вірю у Світло, як і будь-хто інший в Штормовії, але Багряний Похід показали, що прагнуть лише вбивати всіх, хто не вірний їм... навіть невинних.", ["en"] = "Unfinished Business", ["tasks"] = { ["Scarlet Hunter"] = "мисливець Багряного Походу", ["Scarlet Hunter slain"] = "мисливець Багряного Походу: убито", ["Scarlet Knight"] = "лицар Багряного Походу", ["Scarlet Knight slain"] = "лицар Багряного Походу: убито", ["Scarlet Mage"] = "маг Багряного Походу", ["Scarlet Mage slain"] = "маг Багряного Походу: убито", ["Scarlet Medic"] = "медик Багряного Походу", ["Scarlet Medic slain"] = "медик Багряного Походу: убито" } },
    [602] = { [1] = "Магічний аналіз", [2] = "Я чув, що маги Даларану зараз зайняті відбудовою свого зруйнованого міста, але я впевнений, що ти зможеш знайти хоча б когось, хто зможе приділити тобі трохи часу і подивитись на браслети. Якщо я щось і знаю про магів, то це те, що вони не можуть встояти перед магічними загадками.\n\nВізьми мішок з браслетами водяних елементалів і дізнайся, чи зможуть вони пролити світло на прокляття каменя. Краще звернись до архімага Ансірема Рунописа. Я мав справу з ним раніше і його знання величезні.", [3] = "Принесіть браслети водяних елементалів архімагу Ансірему Рунопису в Даларан.", [4] = "Вибач, я зараз дуже зайнятий.", [5] = "Камінь припливів? Дуже цікаво. Ти будеш {стать:здивований:здивована}, дізнавшись, що кілька років тому я написав книгу, присвячену легендам імперії Ґурубаші. Я знаю досить багато про камінь.\n\nПринаймні на одному з цих браслетів, здається, є якісь залишки магії, які я можу проаналізувати.\n\nПодивимось, що я можу зробити...", ["en"] = "Magical Analysis", ["tasks"] = { ["Bag of Water Elemental Bracers"] = "мішок з браслетами водяних елементалів", ["Bag of Water Elemental Bracers (Provided)"] = "мішок з браслетами водяних елементалів (видано)" } },
    [6021] = { [1] = "Зельдарр-Вигнанець", [2] = "Хто б міг подумати, що після всіх проблем, через які ми пройшли в Зачумлених землях... ми іще маємо перейматися через крадіїв? І не звичайних крадіїв, а тролів-крадіїв.\n\nІ не нормальних тролів-крадіїв. А мертвих тролів-крадіїв!\n\nУ них є ватажок — величезний мертвий троль, на ім'я Зельдарр-Вигнанець. Вони приходять сюди вночі, крадуть тіла з ями та тягнуть їх у своє зловісне лігво — у Підцарину, що на заході.\n\nВідправляйся туди та вбий Зельдарра, {ім'я}. Я вже ситий по горло його витівками!", [3] = "Принесіть голову Зельдарра доглядачу Алену в Каплицю Надії Світла.", [4] = "Тобі вдалося знайти їхнє лігво, {ім'я}? Ти {стать:подбав:подбала} про Зельдарра?", [5] = "Чудово, ти {стать:вбив:вбила} його! І, сподіваюся, {стать:провчив:провчила} його банду!", ["en"] = "Zaeldarr the Outcast", ["tasks"] = { ["Zaeldarr's Head"] = "голова Зельдарра", ["Zaeldarr's Head (Provided)"] = "голова Зельдарра (видано)" } },
    [6023] = { [1] = "Незавершена справа", [2] = "Моє справжнє завдання — послабити сили Багряного Походу, а потім проникнути у Вогнеділ, щоб оцінити їхню чисельність. Я все ще не в тому стані, щоб зробити це самотужки, тому, можливо, я могла б знову попросити тебе про допомогу, {ім'я}? Судячи з інформації, яку мені вдалося зібрати, у Багряного Походу є двоє важливих членів, які є опорою їхніх сил за межами міста: мисливиця Радлі та кавалерист Дарґен. Вбий їх і справа зрушить з місця. Вони мають бути в перевалі, неподалік від міста.", [3] = "Вбийте мисливицю Радлі та кавалериста Дарґена, після чого поверніться до Кірсти Чорнотіні в Західні Зачумлені землі.", [4] = "Ти вже {стать:знайшов:знайшла} їх, {ім'я}? Якщо ти розберешся з ними, я зможу проникнути у Вогнеділ та краще оцінити їхні сили. Я не впораюся без твоєї допомоги. Будь ласка, знайди Радлі та Дарґена.", [5] = "Дякую, {ім'я}. Я і не розраховувала на таку велику поміч. Здається, саме повітря цих земель висмоктує з мене життєві сили. Я дуже втомлена, і що довше тут знаходжуся, то мені гірше.\n\nЯ не впевнена, яким чином я проберуся до Вогнедолу та звітую про сили Багряного Походу.\n\nАле це вже інша справа. Зачекай, візьми це... як плату за твою допомогу. Іще раз дякую.", ["en"] = "Unfinished Business", ["tasks"] = { ["Cavalier Durgen"] = "кавалерист Дарґен", ["Cavalier Durgen slain"] = "кавалерист Дарґен: убито", ["Huntsman Radley"] = "мисливиця Радлі", ["Huntsman Radley slain"] = "мисливиця Радлі: убито" } },
    [6024] = { [1] = "Прохання Гамеї", [2] = "Вбий мене. Поки не пізно.\n\nЯ Гамея. Подорожуючи Зул'Машаром, я з побратимами з'їла поганого м'яса... і ми змінилися. Тепер ми заражені.\n\nЯ чую шепіт ліча, як він змушує мене дістатися до Зул'Машара та поширити заразу серед моїх побратимів. Я не можу опиратися, тому написав цей сувій перед до того, як воля покине мене.\n\nЯ закопав скриню в землі поруч з возом за цим склепом, але лише мій ключ відчинить її. Ключ у мене. Якщо хочеш отримати мої скарби — вбий мене.\n\nВбий мене, поки не стало геть пізно.", [3] = "Вбийте шпигуна Гамею. Скористайтеся його ключем, щоб відкрити закопану за Підцариною скриню.", [4] = "Ця скриня надійно замкнена.", [5] = "Скриня Гамеї відчинена!", ["en"] = "Hameya's Plea", ["tasks"] = { ["Hameya's Key"] = "ключ Гамеї", ["Hameya's Key (Provided)"] = "ключ Гамеї (видано)" } },
    [6025] = { [1] = "Незавершена справа", [2] = "Що? Справді? Ти хочеш дізнатися більше? Але ти вже так багато для мене {стать:зробив:зробила}, {ім'я}. Я не можу просити тебе пробратися до Вогнедолу.\n\nТи {стать:впевнений:впевнена}, {ім'я}? Вогнеділ набагато небезпечніший за перевал. Я не зможу захистити тебе чи навіть сказати, що на тебе може чекати там.\n\nЩо ж, якщо ти так хочеш допомогти, проникни у місто та знайди височину, з якої буде гарно видно місто. Звідти ти зможеш оцінити сили Багряного Походу та розповісти про них мені. Але будь {стать:обережним:обережною}...", [3] = "Проникніть у Вогнеділ та знайдіть височину, з якої ви зможете побачити місто та оцінити сили Багряного Походу, після чого поверніться до Кірсти Чорнотіні в Західні Зачумлені землі.", [4] = "Це небезпечне завдання, {ім'я}. Я заздрю твоїй хоробрості.", [5] = "Ти {стать:зробив:зробила} це, {ім'я}! Дякую тобі!\n\nЯ повернуся до Еллінга... тобто до Штормовію, як тільки зможу. Ось, візьми ці моенти, це найменше, що я можу зробити для тебе. Ти гордість свого народу, {ім'я}. Дякую тобі та нехай щастить.", ["en"] = "Unfinished Business", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Overlook Hearthglen from a high vantage point"] = "Огляньте Хартглен з високої точки огляду" } },
    [6026] = { [1] = "Се багато, але се чесна праця", [2] = "Сріблястий Світанок доручив стариганю Димню невеличку демонтажну роботу. Матуся Димня не дурника виховала — грошики-то ніколи не зайві!\n\nЯ б хтів розділити обов'язки з тобоу, якщо ти хо' попрацювати ніжками. Я піду до Чумолісся та помічу всі будівлі, які потрібно знести, а ти поки добудеш вибухівку. Домовилися? Зустрінемоси тут, як збереш усе необхідне.", [3] = "Димень ЛаРу хоче, щоб ви принесли 2 злитки торію, 1 золотий жезл, 8 фугасних бомб та 8 нестабільних пускових пристроїв.\n\nДля виготовлення цих предметів вам доведеться знайти коваля та інженера.", [4] = "Довірся стариганю Димню, {раса:к}. Робота не май важка, а друзяки зі Сріблястого Світанку не скупі — платять файно.", [5] = "Я мо' заплатити тобі половину нині, а іншу — як кінчимо роботу.", ["en"] = "That's Asking A Lot", ["tasks"] = { ["Golden Rod"] = "золотий жезл", ["Golden Rod (Provided)"] = "золотий жезл (видано)", ["Hi-Explosive Bomb"] = "фугасна бомба", ["Hi-Explosive Bomb (Provided)"] = "фугасна бомба (видано)", ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)", ["Unstable Trigger"] = "нестабільний пусковий пристрій", ["Unstable Trigger (Provided)"] = "нестабільний пусковий пристрій (видано)" } },
    [6027] = { [1] = "Книга Древніх", [2] = "{ім'я}, я доручаю тобі самоцвіт змії. Поклади цей камінь на руку статуї змії на острові Раназжар, що на північний захід звідси. Коли зробиш це, з'явиться той, хто захищає книгу древніх. Ця книга містить таємниці наг, які зберігалися століттями. Принеси мені цю книгу, і ми дізнаємося багато про наших лускатих ворогів!", [3] = "Дістаньте книгу Древніх і поверніть її Азору Альдаморту у вежу Етель Ретор.", [4] = "О, {ім'я}! Радий бачити тебе знову. То що, ти {стать:дістав:дістала} книгу Древніх?", [5] = "Втрачена книга Древніх! Я прослідкую за тим, щоб її передали до вищої ради. Ти сьогодні добре {стать:впорався:впоралася}, і за це тобі треба подякувати... подякувати як {стать:герою:героїні}!", ["en"] = "Book of the Ancients", ["tasks"] = { ["Book of the Ancients"] = "книга Древніх", ["Book of the Ancients (Provided)"] = "книга Древніх (видано)", ["Gem of the Serpent"] = "самоцвіт змії", ["Gem of the Serpent (Provided)"] = "самоцвіт змії (видано)" } },
    [6028] = { [1] = "Доповідь з Завшегляду", [2] = "Я шукаю відповідального працівника, що допоможе мені у невеликій, але важливій справі. Я представляю інтереси Сріблястого Світанку в місцевому управлінні Завшегляда. Мені потрібно передати доповідь офіцерці Сріблястого Світанку Чистосердній в табір Студовій. Це далеко звідси, в Західних Зачумлених землях.\n\nЯкщо мені це вдасться, це буде чудова нагода представити тебе моїй начальниці й можливо, знайти для тебе трохи роботи!", [3] = "Передайте доповідь з Завшегляду офіцерці Сріблястого Світанку Чистосердній в табір Студовій, що в Західних Зачумлених землях.", [4] = "Вітаю, {клас:к}. Від імені Сріблястого Світанку я забезпечу тобі безпеку і притулок, поки ти тут, у таборі Студовій. Можливо, у мене також знайдеться для тебе робота...", [5] = "Грегор дійсно досить винахідливий. Він вже довгий час має справу з картелем Паровиманювання і став експертом у \"мистецтві\" переговорів з гоблінами. Хоч це й правда, що головні уподобання гоблінів лежать в руках тих, у кого найбільші гаманці, вони також знають і поважають цінність дипломатії. Якщо вона так чи інакше забезпечує їм постійних клієнтів...\n\nВ будь-якому випадку, Сріблястий Світанок визнає твої зусилля. Будь ласка, прийми це на знак нашої подяки.", ["en"] = "The Everlook Report", ["tasks"] = { ["Everlook Report"] = "доповідь з Завшегляду", ["Everlook Report (Provided)"] = "доповідь з Завшегляду (видано)" } },
    [6030] = { [1] = "Герцог Ніколас Зверенгоф", [2] = "Відлюдник-медіум, на ім'я Умбранс, що мешкає в цих краях, подарував Сріблястому Світанку справжній літературний шедевр... Це найбільше зібрання чуток і пліток, яке тільки коли-небудь бачив.\n\nОдин з найповажніших лідерів Світанку, герцог Ніколас Зверенгоф, є блискучим лінгвістом. Чи не {стать:міг би:могла б} ти передати йому це від мене — за винагороду, звісно? Каплиця Надії Світла — ось де він зараз перебуває, далеко на сході Східних Зачумлених земель.", [3] = "Передайте книгу \"Дослідження мови духів\" герцогу Ніколасу Зверенгофу в Каплиці Надії Світла, що в Східних Зачумлених землях.", [4] = "Нехай Світло веде тебе у ці тривожні часи, {клас:к}. Що привело тебе сюди, до цього маяка надії посеред темряви й відчаю?", [5] = "Це... це дуже особлива книга. Хотілося б сказати, що \"особлива\" в цьому випадку означає унікальна і, цілком можливо, просвітницька, але це ще треба з'ясувати.\n\n\"Уууууу?\" Хто в здоровому глузді до цього додумався?\n\nЩо ж, я чув про цього Умбранса, про якого говорив Грегор, тож це не безпідставно. Я зроблю все можливе, щоб розшифрувати це. Що ж до тебе... будь ласка, візьми це — люб'язність від Сріблястого Світанку. А поки ти тут, можливо, знайдуться ще якісь речі, з якими ти можеш нам допомогти.", ["en"] = "Duke Nicholas Zverenhoff", ["tasks"] = { ["Studies in Spirit Speaking"] = "Дослідження мови духів", ["Studies in Spirit Speaking (Provided)"] = "Дослідження мови духів (видано)" } },
    [6031] = { [1] = "Рунічне полотно", [2] = "Ми, Деревопузи, самодостатні. Ми не любимо чужинців. Це добре для нас, але погано для торгівлі.\n\nНедавно до нас прийшла нічна ельфа в рідкісному плащі з рунічного полотна. Рунічне полотно є рідкістю серед нас, але плащ був настільки чудовим, що мої родичі хочуть, щоб я зробив їм одяг з рунічної тканини.\n\nЧи зможеш ти принести мені рунічне полотно? Якщо ти принесеш мені достатньо, то я дам тобі щось.", [3] = "Принесіть 30 відрізів рунічного полотна Меілошу в оплот Деревопузих.", [4] = "В тебе є рунічне полотно? Мої родичі з нетерпінням чекають на одяг з нього!", [5] = "То ти {стать:приніс:принесла} полотно. Який чудовий матеріал!\n\nСпасибі тобі, {ім'я}. Ти справжній друг. Будь ласка, прийми це натомість.", ["en"] = "Runecloth", ["tasks"] = { ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [6032] = { [1] = "Священне полотно", [2] = "Хоча Деревопузим до вподоби рунічне полотно, воно для нас не священне. Але місячне полотно священне.\n\nПринеси мені трохи цього священного полотна, і я навчу тебе деяким кравецьким секретам.", [3] = "Принесіть 2 відрізи місячного полотна Меілошу в оплот Деревопузих.", [4] = "Ти {стать:приніс:принесла} місячне полотно, {ім'я}?", [5] = "Дуже добре. Це місячне полотно буде використане для одягу, священного для нашого народу. Спасибі, {ім'я}. Тепер я навчу тебе.", ["en"] = "Sacred Cloth", ["tasks"] = { ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)" } },
    [604] = { [1] = "Пірати Кривавого Вітрила", [2] = "Кразз високо цінує твою відданість рейдерам Чорноводдя. Я поручаю тобі надзвичайно важливе завдання для флоту.\n\nПроникни в так званий південний командний пункт Кривавого Вітрила, який вони встановили на Бурхливому березі. Напади на табір. Викради для мене їхні карти разом з записами наказів. Так ми дізнаємось, що задумали ці покидьки.", [3] = "Командувач флоту Морський Ріг з Грабіжної Бухти хоче, щоб ви вбили 10 шибайголів Кривавого Вітрила і принесли йому карти та накази Кривавого Вітрила.", [4] = "Агов, {ім'я}. Які новини ти {стать:приніс:принесла} з південного табору Кривавого Вітрила?", [5] = "Чудово, {ім'я}. Тепер, коли нам відомі їхні плани, це лише питання часу.\n\nПодумати тільки, що ці дурні кинули якір просто біля мису....", ["en"] = "The Bloodsail Buccaneers", ["tasks"] = { ["Bloodsail Charts"] = "карти Кривавого Вітрила", ["Bloodsail Charts (Provided)"] = "карти Кривавого Вітрила (видано)", ["Bloodsail Orders"] = "накази Кривавого Вітрила", ["Bloodsail Orders (Provided)"] = "накази Кривавого Вітрила (видано)", ["Bloodsail Swashbuckler"] = "шибайголова Кривавого Вітрила", ["Bloodsail Swashbuckler slain"] = "шибайголова Кривавого Вітрила: убито" } },
    [6041] = { [1] = "Шик і дим", [2] = "Поки ти {стать:збирав:збирала} матеріали, мої хлопці помітили будівлі Скари, які потрібно знести.\n\nПлан такий: я дам тобі десяток брусків моєї особливої суміші. Ти відправишси в Чумолісся і лишиш їх в будівлях Скари, що помічені особливим знаком.\n\n<Димень клацає пальцями.>\n\nБам! Ось так се просто.", [3] = "Відправляйтеся до Чумолісся, на північний захід від Каплиці Надії Світла. Знищте 8 будівель Скари використовуючи особливу суміш Димня на мітці детонації всередині кожної будівлі. Димень відмітив зикурати та бійні.\n\nКоли поставите бомбу, покиньте будівлю і милуйтеся своєю роботою.\n\nДо речі, особлива суміш Димня досить... нестабільна.", [4] = "У мене лишились матеріали, щоб зробити кілька брусків моєї особливої суміші. Просто дай знати, якщо знадобиться іще.", [5] = "Ти ніби трішки {стать:засмаг:засмагла} з нашої останньої зустрічі. Я завжди казав, що вибухівка корисна для шкіри.\n\n<Димень регоче.>\n\nНу, хай там як, ось твоя доля. Я дещо додав від себе, щоб полегшити біль від опіків.", ["en"] = "When Smokey Sings, I Get Violent", ["tasks"] = { ["Scourge Structures Destroyed"] = "Зруйновані споруди Бичі" } },
    [605] = { [1] = "Співочі блакитні осколки", [2] = "Співочі кристали можна знайти лише в Тернистій долині й деякі покупці їх дуже цінують. Я знаю кому продати ці кристали, але клята ТзНБ \"Авантюра\" заважає таким чесним підприємцям, як я, збирати їх!\n\nЯ хотів би найняти тебе.\n\nВасиліски Тернистої долини їдять ці кристали. Завдяки кристалам у них така тверда шкіра, з якої іноді можна добувати кристали непоганої якості.\n\nЇх можна добути з будь-якого василіска, але вздовж північних берегів, південніше від Зул'Кунди, вони не такі мерзенні.", [3] = "Принесіть 10 осколків співочих кристалів Вибрику Бульчуку.", [4] = "Ти вже {стать:добув:добула} осколки? Ти отримаєш непогану частку від прибутку!", [5] = "Ага! Ці підійдуть, {ім'я}. Так, дуже добре!\n\nОсь твоя частка... і було приємно мати з тобою справу.", ["en"] = "Singing Blue Shards", ["tasks"] = { ["Singing Crystal Shard"] = "осколок співочого кристала", ["Singing Crystal Shard (Provided)"] = "осколок співочого кристала (видано)" } },
    [606] = { [1] = "Наполохати полохуна", [2] = "Якщо я чогось і не терплю, то це людей, які не платять свої борги! А мені багато хто винен. Як гадаєш, зможеш допомогти мені вибити борги?\n\nПо-перше, в доках є \"Полохун\" Філіп. Він заборгував мені чимало після минулої гри і я хочу забрати своє! Але щоб отримати гроші, потрібно його налякати.\n\nВирушай за місто полювати на старих горил з Туманного долу. Назбирай гарних потрухів та віднеси їх Полохуну. Тільки так, щоб він не дізнався, що вони з тварин. Добряче наполохай його.", [3] = "Принесіть 5 потрухів туманодільної горили \"Полохуну\" Філіпу в Грабіжну Бухту.", [4] = "Гей! Мені не подобається, як ви на мене дивитеся, {стать:пане:панянко}.", [5] = "Ааа! Звідки вони в вас? Ні, не кажіть мені. Я не хочу знати!\n\nХто вас прислав? Морський вовк?", ["en"] = "Scaring Shaky", ["tasks"] = { ["Mistvale Giblets"] = "потрухи туманодільної горили", ["Mistvale Giblets (Provided)"] = "потрухи туманодільної горили (видано)" } },
    [607] = { [1] = "Повернення до Мак-Кінлі", [2] = "Ось, візьми цей мішечок і віддай його Морському вовку. І скажи йому, що я хотів йому заплатити! Клянуся!!\n\nЯ просто був трохи п'яний і заблукав по дорозі, ти знаєш, як це буває. Він зрозуміє, не потрібно насилля!", [3] = "Віднесіть борг Полохуна до \"Морського вовка\" Мак-Кінлі.", [4] = "Що ж, {ім'я}. Ти {стать:приніс:принесла} борг Полохуна?", [5] = "Хе-хе, молодець! Потрухи добряче наполохали Полохуна?\n\nХа! Він читається, як розкрита книга, коли я граю з ним у карти, я просто не можу не виграти!\n\nДякую за допомогу, {ім'я}. Тепер твоя черга отримувати гроші...", ["en"] = "Return to MacKinley", ["tasks"] = { ["Shaky's Payment"] = "борг Полохуна", ["Shaky's Payment (Provided)"] = "борг Полохуна (видано)" } },
    [608] = { [1] = "Пірати Кривавого Вітрила", [2] = "Ти тільки глянь на це нахабство Фіраллона! Він навіть не перепливе Кришталеве озеро на човні, не кажучи вже про те, щоб вести проти нас цілий флот.\n\nПірати Кривавого Вітрила заплатять за свою необачність. Тепер, коли ми знаємо їхній план нападу, ми можемо дати відсіч до того, як вони щось зрозуміють.\n\nАле навіщо посилати цілий флот, якщо для цієї роботи достатньо групи відважних шукачів пригод? {ім'я}, візьми кількох своїх найдосвідченіших товаришів на місце висадки Фіраллона і вбий усе керівництво Кривавого Вітрила. Після цього їхній флот піде на дно....", [3] = "Командувач флоту Морський Ріг з Грабіжної Бухти хоче, щоб ви вбили капітана Море-по-коліно, капітана Кілетяга і командувача флоту Фіраллона.", [4] = "В чому проблема, {ім'я}? Ми повинні атакувати раніше, ніж це зробить Криваве Вітрило!", [5] = "Ах, який чудовий день для рейдерів Чорноводдя! Потрійне ура тобі, {ім'я}!", ["en"] = "The Bloodsail Buccaneers", ["tasks"] = { ["Captain Keelhaul"] = "капітан Кілетяг", ["Captain Keelhaul slain"] = "капітан Кілетяг: убито", ["Captain Stillwater"] = "капітан Море-по-коліно", ["Captain Stillwater slain"] = "капітан Море-по-коліно: убито", ["Fleet Master Firallon"] = "командувач флоту Фіраллон", ["Fleet Master Firallon slain"] = "командувач флоту Фіраллон: убито" } },
    [6085] = { [1] = "Приборкання звіра", [2] = "Може, тобі більше сподобається звір, що має дещо більше, ніж грубу силу? Льодолапий ведмідь стане чудесним супутником для {стать:такого:такої} {клас:р}, як ти. Знайти його можна на схід від Хараноса. Ось жезл приборкання — спробуй цього звіра в бою і подивимось, чи тобі сподобається.\n\nЯк повернешся — я навчу тебе приборкання звірів, щоб ти {стать:міг:могла} обрати собі супутника, який допоможе тобі в боротьбі з загрозами та отримуватиме разом з тобою досвід в бою. Також я навчу тебе, як викликати та відпускати його по твоїй волі.", [3] = "Приборкайте льодолапого ведмедя за допомогою жезлу приборкання. Попрактикуйтесь, після чого поверніть жезл приборкання Ґріфу Дикосерду в Харанос.", [4] = "Ти вже {стать:приручив:приручила} льодолапого ведмедя?", [5] = "А ось і ти, {ім'я:к}. Тепер я навчу тебе приборкання звіра, а також як викликати та відпускати його по своїй волі.\n\nЗнайди собі вірного супутника і насолоджуйся шляхом {клас:р}!", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [60863] = { [1] = "[Ніколи не використовувався]", ["en"] = "[Never used]" },
    [60864] = { [1] = "[Ніколи не використовувався]", ["en"] = "[Never used]" },
    [60865] = { [1] = "[Ніколи не використовувався]", ["en"] = "[Never used]" },
    [60866] = { [1] = "[Ніколи не використовувався]", ["en"] = "[Never used]" },
    [60868] = { [1] = "[Ніколи не використовувався]", ["en"] = "[Never used]" },
    [609] = { [1] = "Боржники вуду", [2] = "Мій список зменшується, але боржників ще вдосталь.\n\nДалі у нас Морі \"Дерев'яна нога\" Вілкінс, Джон-Джон Ворон і Чакі \"Десять Пальців\".\n\nЦі підлі пси вже кілька місяців не сплачують борги, я думав, що вони втекли з міста, щоб не платити! Але потім я дізнався, що їх прокляли та зачарували й тепер вони блукають руїнами в джунглях. Але мені байдуже на їхню долю, я хочу те, що належить мені!\n\nВони в руїнах Абораз і Джубувал, на північний схід звідси. Знайди їх і забери мої речі.", [3] = "Принесіть дерев'яну ногу Морі, золоту підзорну трубу Джон-Джона та величезний перстень Чакі до \"Морського вовка\" Мак-Кінлі в Грабіжну Бухту.", [4] = "{ім'я}, ти {стать:знайшов:знайшла} тих трьох псів? Їхні речі в тебе?", [5] = "Чудово! Я можу отримати за них гарну ціну, особливо за те, що всередині ноги Морі! Дуже дякую, {ім'я}!\n\nСподіваюсь, ці троє засвоїли урок: не роби ставку тим, що не можеш дозволити собі втратити.\n\nМожливо, для них вже запізно це усвідомлювати, але треба було думати, з ким сідати грати в карти.", ["en"] = "Voodoo Dues", ["tasks"] = { ["Chucky's Huge Ring"] = "величезний перстень Чакі", ["Chucky's Huge Ring (Provided)"] = "величезний перстень Чакі (видано)", ["Jon-Jon's Golden Spyglass"] = "золота підзорна труба Джон-Джона", ["Jon-Jon's Golden Spyglass (Provided)"] = "золота підзорна труба Джон-Джона (видано)", ["Maury's Clubbed Foot"] = "дерев'яна нога Морі", ["Maury's Clubbed Foot (Provided)"] = "дерев'яна нога Морі (видано)" } },
    [6124] = { [1] = "Зцілення хворих", [2] = "Мені вдалось виготовити десять порцій мазі з інгредієнтів, які ти {стать:приніс:принесла} мені, {ім'я:к}. Поки я працюю тут, в селищі, намагаючись виготовити якомога більше цієї мазі, я хотіла б, щоб ти {стать:допоміг:допомогла} нам почати зцілення. По всьому Темнобережжі бродять хворі олені. Скористайся цією маззю для їх зцілення.\n\nЯ впевнена, Дендрит Зіркосяйво з Місячної галявини захоче поговорити з тобою, коли ти закінчиш. Будь ласка, передай подяку жителів Аубердіну Кенарійському Колу... і дозволь мені подякувати тобі особисто за допомогу!", [3] = "Нанесіть мазь для зцілення тварин на 10 хворих оленів, що проживають в Темнобережжі — це має їх зцілити. За чутками, ареал проживання хворих оленів — південніше Скельноджерельної річки, що на північ від Аубердіну, а далі — по всій території, аж до південних кордонів Темнобережжя, де починається Ясенеділ.", [4] = "Ти {стать:завершив:завершила} те, про що тебе просила Аланндаріан Нічна Пісня в Аубердіні? Твоє завдання ще не виконане.", [5] = "Ти добре {стать:зробив:зробила}, що {стать:потурбувався:потурбувалася} про хворих оленів Темнобережжя; це мимовільні жертви прокльону й осквернення, яке розповзається по всьому краю. В Дарнасі є ті, хто признає наявність загрози... і ті, хто вперто ігнорує ознаки її посилення. Я сподіваюсь, що ти, {ім'я:к}, — {стать:один:одна} з тих, хто не збирається відвертатися від фактів, які дивляться тобі просто у вічі.\n\nХай там що, ти {стать:довів:довела}, що ти — друг природи та Кола. Прийми це як відзнаку цієї твоєї якості.", ["en"] = "Curing the Sick", ["tasks"] = { ["Sickly Deer cured"] = "Хворий олень вилікуваний", ["Sickly Deer cured (Provided)"] = "Хворий олень вилікуваний (видано)", ["Sickly Deer cured slain"] = "Хворий олень вилікуваний: убито" } },
    [613] = { [1] = "Відкрити ногу Морі", [2] = "Прокляття! Той шмаркач Морі зачинив ногу на замок і я не можу її відкрити! Його скарби всередині ноги, і там якраз стільки, скільки він мені винен!\n\nТреба знайти ключ, щоб відкрити замок. Знаю, що Морі часто грав в азартні ігри з мош'оґґськими ограми в них на пагорбі, що на північному сході. І він розповідав мені, коли був ще живий, що після останнього походу на той пагорб, його вигнали звідти, бо він виграв занадто багато. Можливо, огри мають його ключ.\n\nАле якщо це правда, то, можливо, доведеться вбити цілу купу огрів, щоб відшукати його...", [3] = "Принесіть ключ Морі \"Морському вовку\" Мак-Кінлі в Грабіжну Бухту.", [4] = "Агов, {ім'я}! Ти вже {стать:знайшов:знайшла} ключ Морі?", [5] = "Ти {стать:знайшов:знайшла} його! Величезне тобі дякую, {ім'я}. Ти мені дуже {стать:допоміг:допомогла}!\n\nТримай — ти це {стать:заслужив:заслужила}!", ["en"] = "Cracking Maury's Foot", ["tasks"] = { ["Maury's Key"] = "ключ Морі", ["Maury's Key (Provided)"] = "ключ Морі (видано)" } },
    [6131] = { [1] = "Союзник Деревопузих", [2] = "Тільки плем'я Деревопузих змогло уникнути зараження. Проте багато інших рас вбивають хутропузів без причини, не намагаючись розрізнити друзів від ворогів. Тому Деревопузі хутропузи дуже мало кому довіряють.\n\nХочеш заслужити нашу довіру? Очисть Сквернолісся від зараженого племені Мертволісих і, можливо, ми визнаємо тебе {стать:нашим союзником:нашою союзницею}. Перше плем'я Мертволісих — воїни, слідопити та садівники — знаходиться на захід звідси.", [3] = "Ґразл хоче, щоб ви проявили себе, вбивши 5 мертволісих воїнів, 5 мертволісих слідопитів і 5 мертволісих садівників.", [4] = "Продовжуй, {ім'я}. Якщо хочеш заслужити нашу довіру — покажи, чого ти {стать:вартий:варта}.", [5] = "Ми сильно страждаємо від того, що трапилося в минулому. Дякую за все, що ти {стать:зробив:зробила} для захисту Деревопузих.", ["en"] = "Timbermaw Ally", ["tasks"] = { ["Deadwood Gardener slain"] = "мертволісий садівник: убито", ["Deadwood Pathfinder slain"] = "мертволісий слідопит: убито", ["Deadwood Warrior slain"] = "мертволісий воїн: убито" } },
    [6132] = { [1] = "Витягни мене звідси!", [2] = "Витягни мене звідси!\n\nЯ вирушила в долину Списів, щоб поговорити з Мародінами. Я думала, що зможу вести з ними справи... але вони не хочуть розмовляти! Здається, вони хочуть мене з'їсти!\n\nВитягни мене звідси, і мій брат Горнізз добре тобі заплатить! Він у нашому таборі на сході, поруч з кладовищем кодо.\n\nНам краще поквапитися, {ім'я}. Кілька хвилин тому я чула, як кентаври говорили про казан...", [3] = "Проведіть Меліззу Белькотало, а потім поговоріть з Горніззом Белькоталом на кладовищі кодо в Спустошищі.", [4] = "Ти не {стать:бачив:бачила} мою сестру Меліззу? Вона постійно потрапляє в неприємності.", [5] = "Моя сестра Мелізза сказала, що ти прийдеш. Дуже дякую, що {стать:витягнув:витягла} її з чергової халепи. Шкода, що вона вже, напевно, втрапила в ще одну!", ["en"] = "Get Me Out of Here!" },
    [6134] = { [1] = "Збір ектоплазми", [2] = "На південному сході є долина Кісток, в якій мешкають маґрамські привиди. Звучить страшно, чи не так? А уяви, як страшно Маґрамам! Якби нам вдалося зібрати енергію цих привидів, я впевнений, кентаври б добре заплатили за це.\n\nОсь, візьми цей ящик з примарними магнітами. Якщо покласти такий магніт в долині між двома великими скелетами — Мертвими Голіафами — то примари потягнуться до нього. Відійди подалі, знищ привидів і збери їхню ектоплазму — ми продамо її Маґрамам.", [3] = "Принесіть 8 одиниць ектоплазми і ящик примарних магнітів Горніззу Белькоталу в Спустошище.", [4] = "Де моя ектоплазма, {ім'я}?", [5] = "А ось і вона! Схоже, на тобі теж трохи залишилось. Слизька штука, ене ж?\n\nЩо ж, {ім'я}, велика подяка тобі за всі клопоти. Ця гидота коштуватиме немало... якщо, звісно, я переконаю кентаврів купити її!", ["en"] = "Ghost-o-plasm Round Up", ["tasks"] = { ["Crate of Ghost Magnets"] = "ящик примарних магнітів", ["Crate of Ghost Magnets (Provided)"] = "ящик примарних магнітів (видано)", ["Ghost-o-plasm"] = "ектоплазма", ["Ghost-o-plasm (Provided)"] = "ектоплазма (видано)" } },
    [614] = { [1] = "Скриня капітана", [2] = "Я ходив на кораблі звідси аж до Брашпиль, що в Калімдорі. Я був хорошим капітаном з бездоганною репутацією.\n\nДоки...\n\nЦі прокляті морські велетні не знищили мене! Вони розтрощили мій корабель, вбили мою команду і відправили мене на рятувальній шлюпці до Грабіжної Бухти. А один з велетнів, Ґорлаш, вкрав мою капітанську скриню. Сказав, що зробить з неї табакерку. От нахаба!\n\nЯ чув, що Ґорлаш блукає узбережжям на сході звідси. Знайди його і поверни мою скриню! Зробиш це й отримаєш капітанську подяку.", [3] = "Поверніть Гекельбері Смотсу в Грабіжну Бухту його скриню.", [4] = "Агов, {ім'я}! Ти {стать:знайшов:знайшла} Ґорлаша? Це була моя улюблена скриня, до того ж в ній був прихований відсік, де зберігалися мої найдорожчі скарби!", [5] = "Ти {стать:знайшов:знайшла} її! Який щасливий день! Дякую тобі, {ім'я}. Повернення скрині трохи заспокоїло мене.\n\nАле я ще не помстився...", ["en"] = "The Captain's Chest", ["tasks"] = { ["Smotts' Chest"] = "скриня Смоттса", ["Smotts' Chest (Provided)"] = "скриня Смоттса (видано)" } },
    [6145] = { [1] = "Кур'єр Багряного Походу", [2] = "Як тіло не може вижити без голови, так і голова не може вижити без тіла. Оборона сил Багряного Походу в Стратгольмі майже незламна. Тож ми маємо, навпаки, відрізати тіло від голови.\n\nМої Смертолови вже давно збирають дані про діяльність Багряного Походу за межами Стратгольму. Щодня вони надсилають звіт від командування до Десниці Тіра. Ми повинні перехопити його, {раса:к}! Знайди кур'єра Багряного Походу та забери цей звіт. Віддаси його Натаносу.", [3] = "Поверніться до Східних Зачумлених земель та вистежте кур'єра Багряного Походу. Вбийте його та заберіть наказ верховного лицаря.\n\nДля подальших вказівок зверніться до Натаноса Гнилоклича.", [4] = "Якщо ти впораєшся, то майже заслужиш мою повагу, {клас:к}.", [5] = "<Натанос сміється.>\n\nПрекрасно! Нарешті! У нас є можливість знищити Багряного Оракула!", ["en"] = "The Crimson Courier", ["tasks"] = { ["The Grand Crusader's Command"] = "наказ верховного лицаря", ["The Grand Crusader's Command (Provided)"] = "наказ верховного лицаря (видано)" } },
    [615] = { [1] = "Шабля капітана", [2] = "Після того, як я втратив свій перший корабель через цих велетнів, я купив інший. Я назвав корабель \"Помста Смоттса\", наповнив його припасами, набрав екіпаж і вирушив на пошуки цих лиходіїв. Я знайшов їх, але вони виявились сильнішими за мене. Вони розтрощили \"Помсту Смоттса\", вбили мою другу команду і знову посадили мене на рятувальну шлюпку.\n\nЦього разу інший велетень, Неґолаш, вкрав мою шаблю.\n\nЗнайди Неґолаша і принеси мені мою шаблю!\n\nПоговори з Салагою. Він був моїм коком на \"Помсті Смоттса\" і вижив в останній битві. Він допоможе тобі знайти велетня.", [3] = "Поговоріть з Салагою.", [5] = "Привіт, привіт, {ім'я}. Капітан сказав, що ти йдеш на Неґолаша, правильно?", ["en"] = "The Captain's Cutlass" },
    [6161] = { [1] = "Скарби Ракмора!", [2] = "Записи Ракмора говорять про те, як його корабель плив до фортеці Перомісяць, коли на нього напали морські істоти. Щоб його скарб не потрапив до рук ворога, він сховав скриню на острові Раназжар.\n\nЩоб відкрити скриню, потрібні два ключі — срібний і золотий. Вони були загублені, але якщо ключі та скриня знайдуться, хто знає, який скарб там може чекати!", [3] = "Знайдіть срібний та золотий ключі Ракмора, після чого відкрийте скриню Ракмора.", [4] = "Скриня надійно замкнена.", [5] = "Скриня відкривається. Це скарби Ракмора!", ["en"] = "Claim Rackmore's Treasure!", ["tasks"] = { ["Rackmore's Golden Key"] = "золотий ключ Ракмора", ["Rackmore's Golden Key (Provided)"] = "золотий ключ Ракмора (видано)", ["Rackmore's Silver Key"] = "срібний ключ Ракмора", ["Rackmore's Silver Key (Provided)"] = "срібний ключ Ракмора (видано)" } },
    [6164] = { [1] = "Чекова книжка Августа", [2] = "Я готовий до торгівлі! Що тобі потрібно?\n\nЗачекай... Я не можу відчинити крамницю без чекової книжки. Як я буду вести облік без неї?\n\nНапевно, я залишив її десь у місті. У мене була кімната у корчмі... книжка має бути там.\n\nБудь ласка, принеси мені мою чекову книжку. Принеси мені її, і побачиш, що мої ціни БОЖЕВІЛЬНІ!", [3] = "Поверніть Августу Зворушеному зі Страходолу його чекову книжку.", [4] = "Ти {стать:знайшов:знайшла} мою чекову книжку? Не можу дочекатися, щоб відчинити крамницю!", [5] = "А ось і вона! Йой, яке щастя!\n\nЦе славетний день, {ім'я}! Приголомшливий! Божевільно чудовий, я б сказав!", ["en"] = "Augustus' Receipt Book", ["tasks"] = { ["Augustus' Receipt Book"] = "чекова книжка Августа", ["Augustus' Receipt Book (Provided)"] = "чекова книжка Августа (видано)" } },
    [6165] = { [1] = "<NYI> <TXT> Останки Архімага Тімолайна", ["en"] = "<NYI> <TXT> Archmage Timolain's Remains" },
    [617] = { [1] = "Стеблини акіріса", [2] = "Шукаєш роботу, {ім'я}? Можу дещо запропонувати, якщо не боїшся труднощів.\n\nЄ в мене друзяка, на ім'я Ґрой, який озолотився, продаючи те, що наги називають акірісом. Якась цінна морська травичка. Не знаю, для чого вона потрібна, але він добре платить за її пучки.\n\nПринеси мені десять стеблин цього товару й ми укладемо хорошу угоду. Останній раз наг бачили на узбережжі на північ звідси.", [3] = "Принесіть 10 стеблин акіріса корсару Блодсу в Грабіжну Бухту.", [4] = "Якщо ти не по ділу, то йди геть звідси, {ім'я}.", [5] = "Молодець, {ім'я}. Не так вже й складно було дістати 10 стеблин акіріса, чи не так? Нічого не маю проти наг, але ж треба якось заробляти на життя.", ["en"] = "Akiris by the Bundle", ["tasks"] = { ["Akiris Reed"] = "стебло акіріса", ["Akiris Reed (Provided)"] = "стебло акіріса (видано)" } },
    [618] = { [1] = "Бій з Неґолашем", [2] = "Неґолаш — голодний велетень.\n\nКоли велетні знищили наш корабель, Неґолаш пішов прямо на мою кухню. Він не хотів їсти екіпаж, як інші велетні. Неґолаш хотів вина і моїх смажених крилець канюка. Це моя фірмова страва і за рецептом мені довелося їхати аж у Безплідні краї!\n\nЯкщо хочеш заманити велетня, то візьми вина і купу крилець канюка. Поклади їх у нашу стару рятувальну шлюпку, що пришвартована до берега на південний схід звідси. Коли Неґолаш відчує запах їжі, він обов'язково прийде!", [3] = "Принесіть 10 смажених крилець канюка та 5 пляшок вина з джунглів до рятувальної шлюпки капітана Смоттса.\n\nВбийте Неґолаша і поверніть капітану Смоттсу його шаблю.", [4] = "Ти {стать:дістав:дістала} мою шаблю, {ім'я}?", [5] = "Ти {стать:забрав:забрала} мою шаблю у Неґолаша! Очам своїм не вірю, {ім'я}! Після зустрічі з тобою, удача перейшла на мою сторону, кажу тобі!\n\nДякую! Якщо у мене коли-небудь з'явиться новий корабель і ти захочеш поплавати по морях, то я буду радий {стать:такому почесному гостю:такій почесній гості}.", ["en"] = "Facing Negolash", ["tasks"] = { ["Smotts' Cutlass"] = "шабля Смоттса", ["Smotts' Cutlass (Provided)"] = "шабля Смоттса (видано)" } },
    [6183] = { [1] = "Вшанування померлих", [2] = "П'ятьом моїм найкращим польовим агентам доручили справу Марріса. Один з них повернувся, але через три дні помер уві сні.\n\nІнформації від нього ми отримали небагато, та й та була незв'язною тарабарщиною. Ми розібрали лише два слова: «Натанос» і «Гнилоклич».\n\nЯ не маю вдосталь ресурсів, щоб продовжити це розслідування, а Рейвенхольдт не допоможе нам. Ми повинні дістатись до суті, щоб забезпечити спокій для сімей померлих. Ти допоможеш?", [3] = "Поговоріть з Матіасом Гичем ще раз, якщо хочете прийняти його завдання.", [5] = "<Матіас киває.>\n\nЯ знав, що Болвар пришле мені чоловіків і жінок честі — найвідданіших солдатів Альянсу.", ["en"] = "Honor the Dead" },
    [6184] = { [1] = "Флінт Тінехід", [2] = "Єдина інформація, яка нам відома, це те, що Натанос Марріс, можливо, був вбитий цим Гнилокличем. Ми припускаємо, що той самий Гнилоклич вбив і моїх агентів.\n\nФлінт Тінехід, іще одий член ШУР, знаходиться в таборі Альянсу в проліску Студовій, що в Західних Зачумлених землях. Знайди його, він розповість тобі про теперішню ситуацію з Чумою та дасть тобі завдання.\n\nЩасти тобі, {ім'я}.", [3] = "Відправтеся до табору Студовій в Західні Зачумлені землі та знайдіть Флінта Тінехода.", [5] = "Перше завдання буде простим, {ім'я}. Ти заходиш, ти виходиш. Розвідка...", ["en"] = "Flint Shadowmore" },
    [6185] = { [1] = "Чума на сході", [2] = "Як я вже казав, твоїм першим завданням буде розвідка. Нічого особливого, {ім'я}. Тобі потрібно буде відправитися до Східних Зачумлених земель та пошукати зачіпки, які могли б вивести нас на Гнилоклича.\n\nБудь {стать:уважним:уважною}, коли будеш шукати інформацію про наших зниклих агентів. Ми маємо припускати, що вони вже мертві, і якщо вони мертві, це означає, що їх труп повинен бути... десь там.\n\n<Флінт важко ковтає.>\n\nВсі агенти ШУР носять з собою такі жетони.\n\n<Флінт показує вам свій жетон ШУР.>\n\nПринеси мені всі, які тобі вдасться знайти.", [3] = "Пошукайте у Східних Зачумлених землях зачіпки про Гнилоклича та зниклих агентів ШУР. Якщо ви знайдете будь-які жетони ШУР, поверніть їх Флінту Тінеходу в табір Студовій.", [4] = "У-у... успішно??", [5] = "Рутґер. Фредо. Тур'єн. Всі... мертві...\n\n<Флінт міцно стискає в руках їхні жетони.>\n\nДе вони були? Тобі вдалося знайти якусь інформацію про цього покидька, Гнилоклича?", ["en"] = "The Eastern Plagues", ["tasks"] = { ["SI:7 Insignia (Fredo)"] = "жетон ШУР (Фредо)", ["SI:7 Insignia (Fredo) (Provided)"] = "жетон ШУР (Фредо) (видано)", ["SI:7 Insignia (Rutger)"] = "жетон ШУР (Рутґер)", ["SI:7 Insignia (Rutger) (Provided)"] = "жетон ШУР (Рутґер) (видано)", ["SI:7 Insignia (Turyen)"] = "жетон ШУР (Тур'єн)", ["SI:7 Insignia (Turyen) (Provided)"] = "жетон ШУР (Тур'єн) (видано)" } },
    [6186] = { [1] = "Пришестя Гнилоклича", [2] = "<Флінт зблід.>\n\nЦе зробив На... Натанос? Натанос Гнилоклич?\n\nЧому? Він був... таким благородним ватажком слідопитів. Єдина людина, яку погодились навчати вищі ельфи. І тепер він безжальний поплічник відречених?\n\nВибач, що я... маю попросити тебе про це, {ім'я}, але верховний лорд Фордраґон має якомога скоріше дізнатись про це. Прошу, повертайся до Штормовію та розкажи йому все.", [3] = "Поверніться до Штормовію та розкажіть верховному лорду Болвару Фордраґону про долю Натаноса Марріса.", [5] = "Ні. Це... НІ! Як? Поплічник відречених? ЗАХИСНИК Королеви-Банші???\n\n<Верховний лорд Болвар Фордраґон знесилено опускає руки.>", ["en"] = "The Blightcaller Cometh" },
    [6187] = { [1] = "Порядок має бути відновлено", [2] = "Чи ти знаєш, скільки ватажків слідопитів існує в цьому світі? А скільки існує людей-ватажків слідопитів?\n\nДосягнення Натаноса були безпрецедентними. Він був генієм тактики, він був відповідальним за перемоги Альянсу протягом кількох десятків років.\n\nА тепер він... чемпіон відречених.\n\nНі. Цього не може бути. Порядок має бути відновлено.\n\nЗбери військо, {ім'я}. Повернися з ним до Зачумлених земель та знищ Гнилоклича.\n\nЯ зичу тобі удачі, {ім'я}. Тобі вона справді знадобиться.", [3] = "Зберіть військо та вирушайте до Східних Зачумлених земель. Почніть повномасштабну атаку на Натаноса Гнилоклич та будь-яких воїнів Орди, які можуть спробувати захистити його.\n\nБудьте обережні, {ім'я}. Орда захищатиме колишнього ватажка слідопитів не дивлячись ні на що.", [4] = "<Лорд Болвар Фордрагон розгубився в думках.>", [5] = "Це трагедія. Я думаю... я впевнений, що наш рід проклятий, {ім'я}. Ми приречені втрачати наших найкращих воїнів... наших найблагородніших героїв... наших найобдарованіших учнів.\n\nМи всі в боргу перед тобою, {ім'я}. І де б зараз не був Натанос Марріс, він з посмішкою дивиться на тебе.", ["en"] = "Order Must Be Restored", ["tasks"] = { ["Nathanos Blightcaller"] = "Натанос Заклинач Гниття", ["Nathanos Blightcaller (Provided)"] = "Натанос Заклинач Гниття (видано)", ["Nathanos Blightcaller slain"] = "Натанос Заклинач Гниття: убито" } },
    [619] = { [1] = "Приманка для Неґолаша", [4] = "Перед вами покинута рятувальна шлюпка. На її борту, здертою, вицвілою фарбою видніються слова:\n\n\"Помста Смоттса\"", [5] = "Ви завантажуєте шлюпку їжею та випивкою...", ["en"] = "Enticing Negolash", ["tasks"] = { ["Barbecued Buzzard Wing"] = "смажене крильце канюка", ["Barbecued Buzzard Wing (Provided)"] = "смажене крильце канюка (видано)", ["Junglevine Wine"] = "вино з джунглів", ["Junglevine Wine (Provided)"] = "вино з джунглів (видано)" } },
    [620] = { [1] = "Пояс з монограмою", [2] = "На цьому вишуканому поясі вздовж канту вишиті літери \"ГС\".", [3] = "Поверніть пояс з монограмою власнику.", ["en"] = "The Monogrammed Sash", ["tasks"] = { ["Monogrammed Sash"] = "пояс з монограмою", ["Monogrammed Sash (Provided)"] = "пояс з монограмою (видано)" } },
    [6201] = { [1] = "<UNUSED> Спадщина Попелоносця", ["en"] = "<UNUSED> The Legacy of the Ashbringer", ["tasks"] = { ["Darnassian Bleu"] = "дарнаський блю", ["Refreshing Spring Water"] = "освіжаюча джерельна вода" } },
    [621] = { [1] = "Таємниця Занзіла", [2] = "Занзіл-Вигнанець живе зі своїми поплічниками в руїнах Джубувал та Абораз, на північний схід від Грабіжної Бухти. Його вигнали зі свого племені. Чому? Ну...\n\nЗанзіл володіє методами впливу на свідомість інших, і його бояться його власні вожді. Він використовує суміш із тропічних рослин на своїх послідовниках, щоб придушити їхню волю і зміцнити їхні тіла.\n\nЙого зілля було б дуже цінним для тих, хто хоче контролювати інших.\n\nПринеси мені зразки цієї суміші і я знайду їм застосування.", [3] = "Принесіть 12 зразків суміші Занзіла до Вибрика Бульчука у Грабіжну Бухту.", [4] = "Ти {стать:приніс:принесла} зразки суміші Занзіла?", [5] = "О, чудово! Ось твоя оплата.\n\nІ ще дещо зверху... за мовчання.", ["en"] = "Zanzil's Secret", ["tasks"] = { ["Zanzil's Mixture"] = "суміш Занзіла", ["Zanzil's Mixture (Provided)"] = "суміш Занзіла (видано)" } },
    [622] = { [1] = "Повернення до капрала Калеба", [2] = "Поки тебе не було, я полагодив горщик, який ти мені {стать:приніс:принесла}. Я навіть доробив додатковий паровий свисток, тільки поглянь! На дні є новий подрібнювач, який з легкістю розрубує найтовщі кістки!\n\nТак-так, горщик Кронжека — це 100% задоволення для кухаря! Я впевнений, що власник буде задоволений.", [3] = "Принесіть відремонтований горщик Кронжека капралу Калебу в табір Повстання.", [4] = "Привіт, {ім'я}. Ти {стать:дістався:дісталася} до Грабіжної Бухти? Гоблін Кронжек полагодив мій горщик?", [5] = "Він полагодив його! Чудово, тепер я можу починати готувати вечерю! Дуже тобі дякую, {ім'я}.\n\nСподіваюсь, з тобою нічого не сталося в Грабіжній Бухті. Там буває всяке. До мене навіть доходили чутки, що гобліни затягують п'яних моряків на свої човни, приковують їх і відвозять хтозна-куди, щоб робити хтозна-що...", ["en"] = "Return to Corporal Kaleb", ["tasks"] = { ["Krazek's Fixed Pot"] = "відремонтований горщик Кронжека", ["Krazek's Fixed Pot (Provided)"] = "відремонтований горщик Кронжека (видано)" } },
    [6221] = { [1] = "Мертволісі з півночі", [2] = "На південному заході звідси розташований табір хутропузів племені Мертволісих. Скверна проникає в табір і я хочу покласти кінець цьому, перш ніж вони стануть проблемою.\n\nПлем'я Мертволісих є злим, але це наслідок впливу скверни, що помутила їхній розум. Вони не ворожі від природи, але їм вже не допоможеш. Мені нестерпно важко боротися проти побратимів.\n\nБудь ласка, {ім'я}, зроби те, що потрібно зробити, і не згадуй подробиць. Вони дуже мене засмутять.", [3] = "Нафіен хоче, щоб ви вбили 5 мертволісих наглядачів лігва, 5 мертволісих месників і 5 мертволісих шаманів.", ["en"] = "Deadwood of the North" },
    [623] = { [1] = "Стеблини акіріса", [2] = "{ім'я}, оскільки ти вже тут, я отримав звістку від Ґроя, поки тебе не було. Він каже, що задоволений останньою партією, і в нього є замовник, який хоче ще і якнайшвидше.\n\nЯ буду в Тераморі не раніше ніж через тиждень, але якщо ти збираєшся туди, можеш прихопити й товар з собою.\n\nТо що, любиш пригоди? Ти ж знаєш, де розташована Бруднолипка трясовина? Але будь {стать:обережним:обережною}, в Тераморі може бути небезпечно, якщо зв'язатися не з тими людьми.", [3] = "Принесіть в'язку стеблин акіріса корсару Ґрою в Терамор.", [4] = "Так?", [5] = "Що?! У мене є набагато важливіші справи, ніж теревенити з такими, як ти, {клас:к}. Або кажи щось корисне, або забирайся геть з моїх очей.\n\nА? То тебе прислав Блодс? Ну, то ти маєш щось для мене?\n\n<Рядовий Ґрой уважно оглядає в'язку.>\n\nНепогано, навіть дуже непогано. Ще одна в'язка товару потішить мого замовника.\n\nГадаю, ти хочеш запитати про гроші, чи не так, {клас:к}? Звісно, що так!\n\nОсь твої гроші та порада на додачу: забирайся з моєї пристані.", ["en"] = "Akiris by the Bundle", ["tasks"] = { ["Bundle of Akiris Reeds"] = "в'язка стеблин акіріса", ["Bundle of Akiris Reeds (Provided)"] = "в'язка стеблин акіріса (видано)" } },
    [624] = { [1] = "Загадка Кортелло", [2] = "Підказка чекає на тебе поблизу мосту ошатного\nНа схід від мертвого вітру, південніше кряжу багряного\nШукай під мостом тим, не бий байдики\nЯкщо прагнеш скарб дорогий віднайти.\nЛежить вона там і не знає турбот\nЧекає свій час на болоті Скорбот.", [3] = "Розгадайте загадку!", [5] = "На промоклому пергаменті міститься наступна підказка...", ["en"] = "Cortello's Riddle" },
    [6241] = { [1] = "Активність Зимокрайових", [2] = "Деревопузі зазвичай залишаються відірваними від світу, {ім'я}. Хоча ми дозволяємо проходити через наш оплот тим, кому довіряємо, ми намагаємося уникати інших племен хутропузів.\n\nПлем'я Зимокрайових останнім часом стало все більш ворожим до нас. Вони, здається, перебувають у гніві, повністю поглинені своїм страхом і ненавистю до всього, що вони не розуміють.\n\nЯ прошу тебе скоротити їх чисельність, щоб зменшити загрозу для нас. Ти знайдеш їх в селищі Зимокрайових, далеко на сході звідси.", [3] = "Сальфа хоче, щоб ви вбили 6 зимокрайових тотемістів, 6 зимокрайових наглядачів лігва та 6 зимокрайових слідопитів.", [4] = "Ми дуже цінуємо те, що ти {стать:зробив:зробила} для Деревопузих, {ім'я}. Твої подальші зусилля, безсумнівно, забезпечать тобі довіру та повагу мого племені.", [5] = "Дякуємо за те, що ти {стать:зробив:зробила}. Будь ласка, продовжуй допомагати нам, {ім'я}. У нас дуже мало союзників, до яких ми можемо звернутися.", ["en"] = "Winterfall Activity" },
    [625] = { [1] = "Загадка Кортелло", [2] = "Далека земля в Калімдорі чекає\nНадії і долі ніхто там не знає\nНа схід від степів, де завжди негода\nТам, в трясовині, де морок й тривога\nЗнайде той підказку, хто прагне пригоди\nШукай у печері на південному сході", [3] = "Розгадайте загадку!", [5] = "Ви знаходите запліснявілий сувій.", ["en"] = "Cortello's Riddle" },
    [626] = { [1] = "Загадка Кортелло", [2] = "У Лордерон! Землю жалю й скорботи\nВ кістлявої там завжди є робота\nВздовж узбережжя внутрішніх земель рушай\nВ підніжжі водоспаду скарб шукай\nВже поклик його чуть з глибин води.\nКінець своїй пригоді там знайди.", [3] = "Розгадайте загадку!", [5] = "Ви відкриваєте скриню і знаходите...", ["en"] = "Cortello's Riddle" },
    [628] = { [1] = "Переможець", [2] = "Внутрішня частина готова, залишається лише зробити зовнішній шар. Для цього я використовую лише найкращі шкури старого кроколіска. Вони довговічніші та є найкращим полотном для візерунків та деталей, якими славиться лінійка \"Переможець\".\n\nОднак дуже важко знайти ідеальну шкіру і єдина, яка відповідає моїм вимогам — це шкіра старого морського кроколіска. Старі кроколіски виходять на берег тільки для того, щоб захистити молодших, тому, можливо, доведеться вбити трохи молодняку, щоб витягти одного з них.", [3] = "Принесіть шкуру старого кроколіска Мжичнику в Грабіжну Бухту.", [4] = "Я десь читав, що морські кроколіски повільно вимирають... не найкращі новини для мого бізнесу, правда ж?\n\nХай там як, я сподіваюсь, ти {стать:приніс:принесла} мені шкіру старого морського кроколіска!", [5] = "Чудово! Завдяки твоїй допомозі я виконаю це замовлення і відправлю товар директору Шараднику на найближчому човні до Підштольні. Навіть раніше запланованого терміну!\n\nЯ зробив кілька додаткових чобіт, тож візьми собі пару за твою важку працю. За рахунок Мжичника.\n\nІ пам'ятай, немає кращих черевиків, ніж черевики лінії \"Переможець\" від Мжичника!", ["en"] = "Excelsior", ["tasks"] = { ["Elder Crocolisk Skin"] = "шкура старого кроколіска", ["Elder Crocolisk Skin (Provided)"] = "шкура старого кроколіска (видано)" } },
    [63] = { [1] = "Поклик води", [2] = "Вздовж узбережжя Срібнохвою, на захід від Крипти, ти знайдеш вівтар поглинутий чумою. Духи там більше не розмовляють з нашим народом, тож тобі належить перемогти прояв і очистити водойму.\n\nВізьми наручі елементаля разом із залишками крапель води Бріни та поклади їх у жаровню. Цього ритуалу має бути достатньо, щоб викликати чистий дух, з яким буде можливо спілкуватися.\n\nПринеси мені докази виконання завдання, і я нагороджу тебе новим тотемом.", [3] = "Переможіть зіпсований прояв води та помістіть наручі зіпсованого прояву разом із залишками крапель найчистішої води у жаровню першоджерела в Срібнохвойному пралісі.", [4] = "Жаровня все ще відбиває навколишнє світло, і полум'я помалу тремтить, поки ви наближаєтеся.\n\nВплив чуми уздовж пагорбів, здається, тримається на відстані, і, окрім відсутніх компонентів, жаровня виглядає готовою до ритуалу виклику очищеного прояву води.", [5] = "Ви кладете наручі у жаровню, а потім виливаєте залишки крапель зілля Бріни у полум'я. Краплі тріщать, потрапляючи на полум'я, і ви починаєте вимовляти прості слова, яких навчила вас Іслен...", ["en"] = "Call of Water", ["tasks"] = { ["Corrupt Manifestation's Bracers"] = "наручі зіпсованого прояву", ["Corrupt Manifestation's Bracers (Provided)"] = "наручі зіпсованого прояву (видано)", ["Remaining Drops of Purest Water"] = "залишки крапель найчистішої води", ["Remaining Drops of Purest Water (Provided)"] = "залишки крапель найчистішої води (видано)" } },
    [630] = { [1] = "Послання в пляшці", [2] = "{ім'я}, я вірю в тебе і в тих, кого ти зможеш зібрати, щоб звільнити мене. Мене викрав великий король небогривів, Мукла. Йому поклоняються звірі цього острову і вони тримають мене в заручниках за допомогою цього ланцюга. Якщо ти вб'єш його і знайдеш ключ від кайданів, я буду тобі безмежно вдячною.\n\nЯ часто чую його з південно-східної частини острова, але будь {стать:обережним:обережною}, з ним не варто жартувати.", [3] = "Убийте короля Муклу, а потім поверніться з ключем до принцеси Пуби та звільніть її.", [4] = "Дяка предкам, хтось прийшов мені на допомогу. В тебе є ключ, який визволить мене?", [5] = "{ім'я}, ти {стать:врятував:врятувала} мене від великої ганьби. Якби в мене була така можливість, я б запропонувала тобі місце в моєму племені. Але зараз я можу запропонувати тобі лише це на знак подяки за твою мужність і благородство.", ["en"] = "Message in a Bottle", ["tasks"] = { ["Shackle Key"] = "ключ від кайданів", ["Shackle Key (Provided)"] = "ключ від кайданів (видано)" } },
    [631] = { [1] = "Віадук Тандола", [2] = "Здовецько то гахнуло, кажу тобі. Аж гори здригнулись!\n\nНа віадуці полягли найкращі наші солдати. Довгокос поклявся, що Темне Залізо ще заплатить за скоєне.\n\nТа ниньки ми в скрутному становищі, підмоги все нема. Довгокос відправив стариганя Іржегака на розвідку до східного мосту, щоб глянути чи мо' ми там закріпитись.\n\nТо було кілька днів тому. Ми не маємо кого відправити на пошуки, поки Дун-Модр під осадою.\n\nМо' ти пошукаєш його...", [3] = "Раґ Гармаш просить вас знайти стариганя Іржегака.", [5] = "Ви наштовхуєтесь на тіло дворфа. На його шоломі видніється гравіювання: Ебенезер Іржегак.", ["en"] = "The Thandol Span" },
    [632] = { [1] = "Віадук Тандола", [2] = "Схоже, що Іржегак потрапив в засідку Темного Заліза. Ви помічаєте пергамент біля його стиснутої руки.\n\nПовідомте сумну звістку Раґу Гармашу і покажіть йому знайдений пергамент.", [3] = "Відзвітуйте Раґу Гармашу і покажіть пергамент, знайдений біля тіла Іржегака.", [4] = "Є новини про стариганя Іржегака, {ім'я}?", [5] = "Який жах, страшна новина...", ["en"] = "The Thandol Span", ["tasks"] = { ["Deepfury's Orders"] = "накази Темнолюта", ["Deepfury's Orders (Provided)"] = "накази Темнолюта (видано)" } },
    [633] = { [1] = "Віадук Тандола", [2] = "О, небеса! Бідний Іржегак. Се просто трагедія.\n\nХай його смерть не буде марною. В цьому пергаменті сказано, що Кам Темнолют, організатор нападу на віадук, сховав запас вибухівки прямо за мостом, на височині Араті.\n\nЯкщо ця вибухівка дістанеться мосту, ми будемо відрізані від постачання з півночі! Ти маєш знищити цю вибухівку, {ім'я}. Як справишся - вертайся до мене.\n\nТи наша остання надія.", [3] = "Знищіть сховок з вибухівкою.", [4] = "Знищ вибухівку, доки не пізно!", [5] = "Міст врятовано! Ти добре {стать:послужив:послужила} королю Маґні та дворфам Каз-Модану.\n\nТепер залишилось дочекатися підкріплення...", ["en"] = "The Thandol Span", ["tasks"] = { ["Cache of Explosives Destroyed"] = "сховок з вибухівкою знищено" } },
    [634] = { [1] = "Благання до Альянсу", [2] = "Я попрошу тебе про ще одну послугу, {клас:к}. Ми чекаємо на резерви із Залізогарту. Однак, Роґґо каже про табір Альянсу на півночі у височині Араті, в Опорному пункті.\n\nХоди туди і знайди капітана Ніалс. Запитай капітана, чи може Альянс виділити нам групу солдат, щоб ми відбили Дун-Модр та віадук Тандола.", [3] = "Знайдіть капітана Ніалс в Опорному пункті.", [5] = "Мої співчуття Довгокосу та його хоробрим солдатам. Звістка про трагедію на віадуці Тандола та падіння Дун-Модру глибоко сколихнула всіх нас.\n\nАле Стромварт теж захоплено! Тому ми й тут, в Опорному пункті. Ми маємо намір битися за власне місто.\n\nЧесть і обов'язок вимагають нас не покидати нагір'я, допоки над Стромвартом не буде височіти славетний стяг короля. Я відправлю Довгобороду звістку про те, що йому доведеться триматись самотужки...", ["en"] = "Plea To The Alliance" },
    [635] = { [1] = "Кристал в горах", [2] = "Осколок пульсує в ваших руках...\n\nВам здається, що він молить про щось, ніби хтось, хто відчайдушно потребує допомоги, намагається зв'язатися з вами.\n\nВам являється видіння — у північних горах Араті із землі стирчить сяючий кристал.\n\nВи відчуваєте потяг до цього місця.", [3] = "Знайдіть кристал з видіння.", [5] = "Кристал пульсує, ніби в ньому ув'язнена якась жива сила.", ["en"] = "Crystal in the Mountains", ["tasks"] = { ["Pendant of Myzrael"] = "кулон Мізраель" } },
    [636] = { [1] = "Легенди Землі <NYI>", [2] = "Ця книга розповідає історію про принцесу-елементалу, Мізраель, та її ув'язнення глибоко під Араті-Нагір'ям.\n\nВона також розповідає про таємний виступ кристалів у нагір'ї. Ці кристали, Уламки Мізраель, є вікном до в'язниці принцеси.\n\nЯкби смілива душа знайшла Уламки Мізраель, можливо, <він/вона> змогла б поговорити з нею...", ["en"] = "Legends of the Earth <NYI>" },
    [63769] = { [1] = "[DNT] Трекер святкових квестів", ["en"] = "[DNT] Holiday Quests Tracker" },
    [6389] = { [1] = "Чуму на вас!", [2] = "Ви оглядаєте лісопильню в пошуках чогось, щоб відкрити бочку і знаходите лом, що цілком підходить для цієї мети.\n\nВи готуєтесь накивати п'ятами та молитесь, що встигнете вибратися з лісопильні до того, як до вас доберуться терміти.", [3] = "Випустіть термітів Зачумлених земель на лісопильні Північного кряжу, а потім поверніться з бочкою термітів Зачумлених земель до Натаніеля Дюми в табір Студовій, що в Західних Зачумлених землях.", [4] = "Ти {стать:зробив:зробила} це, {ім'я}? Ти {стать:випустив:випустила} термітів? Нехай Світло допоможе нам, щоб Багряний Похід не зміг утримувати лісопильню та Вогнеділ. Вони взагалі нічого не мають утримувати. Вони просто наживаються на жертвах війни й повинні бути знищені, як прокажені тварини!", [5] = "Ха-ха! Дякую, {ім'я}! Ти {стать:зробив:зробила} це! Дух мого батька може спочивати спокійно, і я можу жити в мирі.\n\nІще раз дякую тобі. Проси мене що хочеш, чим зможу — допоможу.", ["en"] = "A Plague Upon Thee", ["tasks"] = { ["Barrel of Plagueland Termites"] = "бочка з термітами Зачумлених земель", ["Barrel of Plagueland Termites (Provided)"] = "бочка з термітами Зачумлених земель (видано)" } },
    [6402] = { [1] = "Зустріч в Штормовії", [2] = "Ти маєш зустрітись з Віндзором біля воріт Штормовію.\n\nТе, що Віндзор збирається зробити, похитне все королівство!\n\nНавіть не намагайся йти наодинці, {ім'я}. Ти маєш зібрати армію! Поклич друзів! До зброї!", [3] = "Відправляйтесь до воріт Штормовію. Поговоріть зі сквайром Роу, щоб він повідомив маршала Віндзора про ваше прибуття.", [5] = "Перед тим, як ми почнемо, я попрошу тебе спочатку зібрати армію. Ми на дракона йдемо, як-не-як!", ["en"] = "Stormwind Rendezvous" },
    [6403] = { [1] = "Великий обман", [2] = "Це була ще та пригода, {стать:друже:подруго}. Я перед тобою у великому боргу. Можливо, коли з усім буде покінчено...\n\nЯк ти вже {стать:дізнався:дізналась}, леді Престор — це Оніксія, дочка Смертекрила, сестра-близнюк володаря Шпиля, Нефаріана.\n\nЗанадто довго вона плела інтриги в нашому королівстві. Навіть верховний лорд — лиш маріонетка в її руках. Та це все закінчиться сьогодні... Ми зруйнуємо ці чари.\n\nНе бійся — разом ми переможемо!\n\nТи {стать:готовий:готова}?", [3] = "Слідуйте за Реджинальдом Віндзором через Штормовій та захищайте його.", [4] = "Я... Я був... безсилий...", [5] = "<Болвар тримає в руках розколотий медальйон.>\n\nМи маємо відновити магію, яку він містив і налаштувати око дракона.\n\nЖертва Віндзора повернула свободу нашому королівству, але йому все ще загрожує Оніксія та їй подібні.\n\nЦей медальйон утримував в полоні моє тіло та розум. Але він також давав мені доступ до розуму Оніксії — до її таємниць. Хоча ці спогади затуманені, деякі речі я пам'ятаю.", ["en"] = "The Great Masquerade", ["tasks"] = { ["Reginald's March"] = "Марш Реджинальда" } },
    [642] = { [1] = "Ув'язнена принцеса", [2] = "Мене звати Мізраель. Я принцеса землі, і мої полонителі — велетні — ув'язнили мене глибоко під височиною Араті. Ці кришталеві осколки — єдиний спосіб зв'язку з поверхнею.\n\nПрошу, допоможи мені. Союзники велетнів — Суховусі кобольди — мають такий самий осколок в ущелині Суховусих, що на сході звідси. Щоб зарядити його, ти маєш дістати порошинки Мізраель у кобольдів.\n\nБлагаю тебе, {ім'я}, допоможи мені!", [3] = "Зберіть 12 порошинок Мізраель та принесіть їх до райдужник осколків в ущелину Суховусих.", [4] = "Це скупчення кристалів дуже схоже на осколки Мізраель. Але в них не пульсує таке ж відчуття безпеки.", [5] = "Тобі вдалося зарядити ці осколки! Я почуваюсь легше! Вільніше!\n\nАле до свободи ще далеко...", ["en"] = "The Princess Trapped", ["tasks"] = { ["Mote of Myzrael"] = "порошинка Мізраель", ["Mote of Myzrael (Provided)"] = "порошинка Мізраель (видано)" } },
    [647] = { [1] = "Самогон Мак-Кріла", [2] = "Пропустив трішки старого доброго самогончику минулої ночі! Довгокос зніс би мені довбешку якби дізнався що я знепритомнів під час вахти.\n\nМакітра кепсько болить. Здається ніби ціла штурмова бригада їздила мені по голові, настільки міцно гуде.\n\nОх, ти поглянь на час! Я ж давав слово броварю Білґеру з Південнобережжя що поверну свій борг, надіславши йому самогон.\n\nАле в мене лише 15 хвилин! Віднесеш йому цю партію, будь ласка? І поквапся!", [3] = "Віднесіть самогон Мак-Кріла до майстра-броваря Білґера у Південнобережжя.", [4] = "Що скажеш, {раса:н}?", [5] = "Ах, нема нічого, що може розпалити у жвавий день краще, ніж самогон Млистого Мак-Кріла! А я вже почав думати що той маленький негідник знову прострочить свої рахунки. Дякую, {стать:друже:подруго}! Красно дякую!", ["en"] = "MacKreel's Moonshine", ["tasks"] = { ["MacKreel's Moonshine"] = "самогон Мак-Кріла", ["MacKreel's Moonshine (Provided)"] = "самогон Мак-Кріла (видано)" } },
    [648] = { [1] = "Врятувати OOX-17/ТН!", [2] = "Голос гнома знову тріщить з робота:\n\n\"Мені потрібно перемістити OOX-17/TН на відкрите, безпечне місце, щоб він міг почати тривалу процедуру зльоту. Він має вбудовану систему маскування, але мені потрібен час, щоб зробити її знову працездатною. Мені потрібно, щоб ти {стать:супроводжував:супроводжувала} робота з його поточного місцеперебування до, скажімо, порту Паровиманювання! Це має бути ідеальне місце, достатньо просторе, щоб підготувати апарат до польоту!\"\n\n\"Проведи його до порту, а потім приходь поговорити зі мною в Грабіжну Бухту! Оґлторп Обриднус — кінець зв'язку!\"", [3] = "Проведіть OOX-17/TН до порту Паровиманювання, а потім звітуйте Оґлторпу Обриднусу в Грабіжній Бухті.", [5] = "О, ТИ — {стать:великий рятівник:велика рятівниця} OOX-17/ТН! У мене просто слів немає, настільки я вдячний за твою допомогу! Моя серія автономних роботів потребує вдосконалень, але завдяки тобі, я заощадив безліч часу на відновлення і купу золота на дорогі деталі!\n\nБудь ласка, обери будь-який з цих предметів. Ще раз дякую за твою щедру допомогу, мої роботи і я у тебе в боргу!", ["en"] = "Rescue OOX-17/TN!", ["tasks"] = { ["Escort OOX-17/TN to Steamwheedle Port"] = "Супровід OOX-17/TN до порту Стімвілдл" } },
    [6501] = { [1] = "Око Дракона", [2] = "Все, що я можу тобі запропонувати — цей розколотий медальйон.\n\nЗнайди іншого дракона, який зможе допомогти тобі зі створенням нового ключа. Щойно отримаєш його — прямуй до Змієдолу, що в Бруднолипкій трясовині. Там ти знайдеш її лігво, {ім'я}.\n\nДе знайти таких драконів? На жаль, я не знаю... Але вони точно існують. Деякі з них навіть живуть серед нас, замасковані під смертних. Нехай тобі щастить.", [3] = "Знайдіть в Азероті створіння, здатне відновити силу фрагмента ока дракона. Єдина інформація про цих створінь — вони існують.", [4] = "Я відчуваю зло від тебе, {клас:к}. Звідки воно походить?", [5] = "Я мала здогадатись — частина тіла матері чорних драконів, Оніксії... Яка гидота...", ["en"] = "The Dragon's Eye", ["tasks"] = { ["Fragment of the Dragon's Eye"] = "фрагмент Ока Дракона", ["Fragment of the Dragon's Eye (Provided)"] = "фрагмент Ока Дракона (видано)" } },
    [6502] = { [1] = "Амулет полум'я дракона", [2] = "Цей шматок дракона — це луска, зачарована та перетворена. Якби вона була ціла, вона могла б відкрити доступ до лігва дракона. А розбита на друзки, вона нічого не варта.\n\nЇЇ можна відновити, але для цього потрібна кров чемпіона чорних драконів. Я знаю одного такого... Його звати генерал Драккісат, правитель армії драконідів Нефаріана. Можливо, ти щось {стать:чув:чула} про нього?\n\nПовертайся з його кров'ю, {раса:к}, і я накладу на цей уламок чари, що дозволять тобі потрапити в лігво Оніксії.", [3] = "Вам потрібно добути кров чемпіона чорних драконів — генерала Драккісата. Його можна знайти на троні в залах Переродження, що в Чорноскельному шпилі.", [4] = "Плин часу не зупиняється і не сповільнюється, {раса:к}. Моє життя вічне, а твоє — ні. Не марнуй свій час...", [5] = "Цей амулет допоможе тобі досягти мети. Лігво Оніксії можна знайти в Бруднолипкій трясовині. Поки ти тримаєш амулет, її вартові не завадять тобі увійти.\n\nСинє крило бажає тобі удачі, {ім'я}.", ["en"] = "Drakefire Amulet", ["tasks"] = { ["Blood of the Black Dragon Champion"] = "кров чемпіона чорних драконів", ["Blood of the Black Dragon Champion (Provided)"] = "кров чемпіона чорних драконів (видано)" } },
    [651] = { [1] = "Камені Поневолення", [2] = "Чотири камені Поневолення розкидані по височині Араті. Ці камені тримають мене ув'язненою під землею.\n\nЩоб відкрити їх, треба спочатку відкрити найсильніший із них: камінь Внутрішнього Поневолення. А для цього треба зібрати ключі з інших трьох.\n\nЦі камені охороняються вартовими, але якщо в тебе вистачить винахідливості... чи удачі — ти зможеш перемогти їх.", [3] = "Зберіть палаючий, бурунистий та буревійний ключі з каменів Західного, Східного та Зовнішнього Поневолення.\n\nПринесіть їх до каменю Внутрішнього Поневолення.", [4] = "Перед вами камінь Внутрішнього Поневолення. Це найсильніший з каменів Поневолення і за його допомогою можна відкрити інші камені.", [5] = "<Голос Мізраель лунає з каменю.>\n\nТобі вдалося! Ти {стать:відкрив:відкрила} камені Поневолення! Я відчуваю як мої кайдани слабнуть, а моя свобода стає все ближчою.\n\nТи {стать:благородний:благородна} {клас}, {ім'я}. {стать:Мій рятівник!:Моя рятівниця!}", ["en"] = "Stones of Binding", ["tasks"] = { ["Burning Key"] = "палаючий ключ", ["Burning Key (Provided)"] = "палаючий ключ (видано)", ["Cresting Key"] = "бурунистий ключ", ["Cresting Key (Provided)"] = "бурунистий ключ (видано)", ["Thundering Key"] = "буревійний ключ", ["Thundering Key (Provided)"] = "буревійний ключ (видано)" } },
    [652] = { [1] = "Розбити ключ-камінь", [2] = "Відкриття каменів Поневолення ослабило мої кайдани, але дещо ще утримує мене. Це ключ-камінь, який ти бачиш серед інших каменів кола. І ключем від нього володіє Фозрук, один із моїх тюремників.\n\nТи маєш добути ключ, який кам'яні вартові називають скіпетром порядку, у Фозрука і використати його, щоб відкрити ключ-камінь.\n\n{ім'я}, ти так багато для мене {стать:зробив:зробила}. Ще трохи... і моя вдячність стрясе цю землю!", [3] = "Знайдіть і вбийте Фозрука. Принесіть скіпетр порядку до ключа-каменя на височину Араті.", [4] = "Ключ-камінь заряджений потужною силою геомантії...", [5] = "Ви поміщаєте скіпетр в ключ-камінь і відчуваєте, як земля під вами починає тремтіти...", ["en"] = "Breaking the Keystone", ["tasks"] = { ["Rod of Order"] = "скіпетр порядку", ["Rod of Order (Provided)"] = "скіпетр порядку (видано)" } },
    [654] = { [1] = "Польові дослідження в Танарісі", [2] = "Активація джерела енергії призводить до того, що тестовий набір починає світитися і вібрувати. Схоже, що все працює, як задумано.\n\nЗа словами головного інженера Трюмосвиста, у вас є дві години, щоб зібрати потрібні дані в пустелі Танаріс. Якщо ви не зможете зібрати їх протягом цього часу, то весь зібраний матеріал буде втрачено, і вам доведеться купити ще одне джерело енергії у Трюмосвиста.\n\nПоверніться до нього, коли завдання буде виконано.", [3] = "Отримайте 8 прийнятних зразків василісків, гієн і скорпідів. Принесіть набір для польових досліджень головному інженеру Трюмосвисту в Пристроблях до того, як джерело енергії виснажиться.", [4] = "Ну, {стать:зібрав:зібрала} все необхідне? Якщо ні, а джерело енергії виснажиться, то все, що ти {стать:зібрав:зібрала}, буде знищено, і тобі доведеться починати все спочатку.\n\nЕй, не шукай в мене співчуття; я думаю тільки про інтереси Пристробляхводоканалу, і якщо мені доведеться продавати тобі джерела енергії до тих пір, поки ми не зможемо дозволити собі імпортувати воду з крижаних джерел Дун-Морога, то хай буде так!", [5] = "Гаразд, мені знадобиться кілька секунд, щоб витягнути джерело енергії. Після цього ти можеш робити з ним все, що завгодно, не турбуючись про втрату даних.", ["en"] = "Tanaris Field Sampling", ["tasks"] = { ["Acceptable Basilisk Sample"] = "прийнятний зразок василіска", ["Acceptable Basilisk Sample (Provided)"] = "прийнятний зразок василіска (видано)", ["Acceptable Hyena Sample"] = "прийнятний зразок гієни", ["Acceptable Hyena Sample (Provided)"] = "прийнятний зразок гієни (видано)", ["Acceptable Scorpid Sample"] = "прийнятний зразок скорпіда", ["Acceptable Scorpid Sample (Provided)"] = "прийнятний зразок скорпіда (видано)", ["Field Testing Kit"] = "набір для польових досліджень", ["Field Testing Kit (Provided)"] = "набір для польових досліджень (видано)" } },
    [656] = { [1] = "Виклик принцеси", [2] = "Ти маєш перемогти Мізраель до того, як вона стане надто сильною. Якщо ти цього не зробиш, то вона кинеться на своїх поневолювачів щойно набереться сил. Дехто вважає, що зможе її контролювати, але якщо її можна контролювати, навіщо було гігантам від самого початку заковувати її в ланцюги?\n\nБожевільна логіка, еге ж?\n\nЩоб перемогти Мізраель, виклич її біля кристалів, де ти вперше {стать:розмовляв:розмовляла} з нею. Переможи її, забери в неї таємничі кайдани та прив'яжи їх до осколків Мізраель.\n\nЗроби це і вона знову буде поневолена.", [3] = "Вирушайте до осколків Мізраель, викличте її та переможіть.\n\nЗаберіть її таємничі кайдани та зв'яжіть їх з осколками Мізраель.", [4] = "Осколки Мізраель тепер незвично тихі.", [5] = "Щойно ви зв'язуєте таємничі кайдани з осколками, з підземних глибин залунало нелюдське виття, що перейшло у крик.\n\nОсколки Мізраель більше не випромінюють тепла і почуття безпеки, як це було раніше. Тепер вони пульсують загрозою... ніби істота під ними має злі наміри.", ["en"] = "Summoning the Princess", ["tasks"] = { ["Eldritch Shackles"] = "таємничі кайдани", ["Eldritch Shackles (Provided)"] = "таємничі кайдани (видано)" } },
    [6561] = { [1] = "Лиходійство Чорноводних глибин", [2] = "Сили покидають мене. Мені потрібна твоя допомога!\n\nКолись давно на цьому місці був храм Елуни. На жаль, його було знищено, коли порча Старих Богів просочилась з-під землі та зіпсувала священний місячний колодязь.\n\nАку'май, слуга Старих Богів, піднялася з глибин.\n\nКультисти Сутінкового Молота об'єднались з нагами, щоб захопити ці землі. На чолі з Келрісом вони приносять жертви, щоб Аку'май набрався сил.\n\n{ім'я}, благаю, вбий Келріса і принеси його голову Башані Рунний Тотем в Громовий Бескид.", [3] = "Принесіть Башані Рунному Тотему в Громовий Бескид голову сутінкового лорда Келріса.", [4] = "Хай береже тебе Матір-Земля, {ім'я}.\n\nГармонія з природою — наша головна мета. Все у світі відбувається по волі Матері-Землі, а наше завдання — втілювати її задуми.", [5] = "Келріс довгий час переховувався від Сріблястого Світанку.\n\nДеякий час вони вважали його мертвим.\n\nПокінчивши з ним, ти {стать:врятував:врятувала} багато невинних життів, {ім'я}.\n\nХай славиться Матір-Земля! Немає прощення тим, хто приносить жертви Старим Богам!\n\nТи {стать:зробив:зробила} велику справу. Келріс був породженням зла і намагався повернути нас світ до часів хаосу, коли ним правили Старі Боги. Дякую тобі, {ім'я}.", ["en"] = "Blackfathom Villainy", ["tasks"] = { ["Head of Kelris"] = "голова Келріса", ["Head of Kelris (Provided)"] = "голова Келріса (видано)" } },
    [6562] = { [1] = "Халепа в глибинах", [2] = "Дже'неу Санкрі потребує допомоги. Він знаходиться на форпості Зорам'ґар в Ясенедолі. Цей ліс нічних ельфів знаходиться на північ від Каміннопазуристих гір. Ти можеш дістатись до нього, пройшовши через Вітрокосі скелі або відправившись на північ через Степи. Зорамське узбережжя знаходиться на заході лісу. Будь {стать:обережний:обережна}, {ім'я}. Тамтешні сили можуть вороже сприйняти твою присутність.", [3] = "Поговоріть з Дже'неу Санкрі в Ясенедолі.", [5] = "Тебе прислав Цунамен? Чудово. Нам є що обговорити.", ["en"] = "Trouble in the Deeps" },
    [6564] = { [1] = "Відданість Старим Богам", [2] = "На зім'ятому шматі паперу нашрябано:\n\n\"Так, передайте всім жрицям, щоб принесли кристали мені. Душі водяних елементалів могутні, вони допоможуть нашим аквамантам в закляттях.\n\nЗ силою цих кристалів ми зможемо задовольнити Аку'Май. Одного дня ми матимемо достатньо сил, щоб викликати Аку'Май і повернути наш світ до найвеличнішої епохи! Епохи Старих Богів!\"", [3] = "Принесіть розмоклу записку Дже'неу Санкрі в Ясенеділ.", [4] = "Так, {ім'я}? Чого тобі треба? Мені належить ще багато дізнатись про ці кристали, що збирають наги.", [5] = "Що ж, це дійсно цікаво. Радий, що ти {стать:приніс:принесла} цю записку мені.\n\nТепер у нашої напасті є ім'я... Лорґус Джетт.", ["en"] = "Allegiance to the Old Gods", ["tasks"] = { ["Damp Note"] = "розмокла записка", ["Damp Note (Provided)"] = "розмокла записка (видано)" } },
    [6582] = { [1] = "Випробування черепів: Провидець", [2] = "Ми — діти Смертекрила, драконеня. Наша влада над меншими Аспектами має зміцнитися.\n\nЯкщо ти дійсно {стать:гідний:гідна} піднесення, то інші дракони повинні тремтіти від одного твого імені.\n\nЗнайди їхніх чемпіонів і знищуй в ім'я нашого Батька!\n\nПрямуй в Зимоключ та відшукай могутнього синього дракона — Провидця. Знищ його та будь-кого з синього крила, хто стане на твоєму шляху. Вирви його череп і принеси мені.", [3] = "Знайдіть чемпіона крила синіх драконів, Провидця, вбийте його і принесіть його череп Вуглечвару.\n\nВи знаєте, що Провидця можна знайти у Зимоключі.", [4] = "<Вуглечвар шипить>.", [5] = "Ще ззззз одним покінчено...", ["en"] = "The Test of Skulls, Scryer", ["tasks"] = { ["The Skull of Scryer"] = "череп Провидця", ["The Skull of Scryer (Provided)"] = "череп Провидця (видано)" } },
    [6583] = { [1] = "Випробування черепів: Сомнус", [2] = "Так само як наш батько розтрощив самих Аспектів, так само ми повинні сіяти хаос і страх серед їхніх нащадків.\n\nТобі маєш довести свою майстерність на сноходцях — дітях зеленого крила.\n\nЙди в болото Скорбот і знайди Сомнуса, дракона-чемпіона зеленого крила. Вивільни свою ненависть, розчави цього черв'яка... Повертайся до мене з його черепом...", [3] = "Знищте чемпіона зелених драконів, Сомнуса. Принесіть його череп Вуглечвару.", [4] = "Не повертайся, поки не скупаєшся в крові наших ворогів і не вип'єш їхніх страждань.", [5] = "Ще один готовий...", ["en"] = "The Test of Skulls, Somnus", ["tasks"] = { ["The Skull of Somnus"] = "череп Сомнуса", ["The Skull of Somnus (Provided)"] = "череп Сомнуса (видано)" } },
    [6584] = { [1] = "Випробування черепів: Хроналіс", [2] = "Часові наглядачі, діти Ноздорму — Владики Віків...\n\nТроє з них стережуть Печери Часу, але лише один цікавить чорне крило: змінювач часу, Хроналіс — улюбленець Ноздорму.\n\nНапади на цього чемпіона бронзового крила і завдай удару, щоб навіть пісок у його годиннику ридав від жаху. Повертайся до мене з його черепом.", [3] = "Печери Часу в пустелі Танаріс охороняє Хроналіс, дитя Ноздорму. Знищте його і принесіть його череп Вуглечвару.", [4] = "Іронічно, але час має велике значення.", [5] = "Залишився один — найненависссніший...", ["en"] = "The Test of Skulls, Chronalis", ["tasks"] = { ["The Skull of Chronalis"] = "череп Хроналіса", ["The Skull of Chronalis (Provided)"] = "череп Хроналіса (видано)" } },
    [6585] = { [1] = "Випробування черепів: Акстроз", [2] = "Це було над горами Ґрім-Батол, де наш Батько наш бився проти об'єднаних сил Аспектів. Але підступна зрада Алекстрази дала іншим Аспектам достатньо часу, щоб втекти від гніву Батька.\n\nТакий ганебний вчинок...\n\nЧервоне крило тепер охороняє Ґрім-Батол, і їх лейтенант, Акстроз, має бути знищений. Принеси мені його череп. За Батька, драконеня!", [3] = "Відправляйтеся в Ґрім-Батол і вистежте Акстроза, чемпіона крила червоних драконів. Знищте його та заберіть його череп. Принесіть череп Вуглечвару.", [4] = "Ззззміни... Я бачу, як вони відбуваються в тобі, драконеня. Пройди це випробування, і залишиться лише церемонія.", [5] = "Я сумнівався у твоїй відданості, драконеня. Ти {стать:вистояв:вистояла}, перемігши наших ворогів, принісши честь нашому крилу.\n\nТепер я маю підготувати черепи для твого вознесіння.", ["en"] = "The Test of Skulls, Axtroz", ["tasks"] = { ["The Skull of Axtroz"] = "череп Акстроза", ["The Skull of Axtroz (Provided)"] = "череп Акстроза (видано)" } },
    [6602] = { [1] = "Кров чемпіона чорних драконів", [2] = "Ти відправишся до генерала, але вже не як член крила чорних драконів.\n\nОт, що я тобі скажу, церемонія — це лише прикриття для проливання крові чорним крилом.\n\nВсе, чого не вистачає цьому амулету, це крові генерала. Досить простий захисний механізм.\n\nПовертайся до Чорноскельного шпиля і вбий Драккісата. Принеси його кров мені і я активую ключ до лігва Оніксії.", [3] = "Відправляйтеся на Чорноскельний шпиль та вбийте генерала Драккісата. Зберіть його кров і поверніться до Рексара.", [4] = "З Драккісатом краще не жартувати, {ім'я}. Він убив тисячі...", [5] = "<Рексар посміхається.>\n\nПро твої подвиги говоритимуть багато років, {ім'я}. Амулет полум'я дракона відкриє тобі шлях до лігва Оніксії. Збирай своїх союзників та бийся в ім'я Орди!", ["en"] = "Blood of the Black Dragon Champion", ["tasks"] = { ["Blood of the Black Dragon Champion"] = "кров чемпіона чорних драконів", ["Blood of the Black Dragon Champion (Provided)"] = "кров чемпіона чорних драконів (видано)" } },
    [6603] = { [1] = "Халепа в Зимоключі!", [2] = "Здається, у Зимоключі якась халепа.\n\nЯ проводжу багато часу на природі й знаю про такі речі... Я завжди пишаюся цим. Я вважаю, що години, проведені в горах — найцінніші. Це допомагає розвивати швидкість рефлексів, спокійний розум та гостре око...\n\nПотрібні розсудливість, розум і зрілість, щоб оцінити дику природу так, як це роблю я.\n\nА, так, халепа. Поговори з Доновою Снігосхов біля гарячих джерел, вона зможе детальніше розповісти тобі.", [3] = "Знайдіть Донову Снігосхов біля гарячих джерел в Зимоключі.", [5] = "Ну, привіт! То Меґґі розповіла тобі про халепу, яку я тут знайшла?", ["en"] = "Trouble in Winterspring!" },
    [6604] = { [1] = "Розлючені дикі совухи", [2] = "Ти {стать:помітив:помітила} покинутий табір на південь звідси? Схоже, що дикі совухи збожеволіли та знищили майже все, до чого могли дотягнутись!\n\nДо мене дійшли чутки, що один з тих, хто вижив після нападу, відпочиває в селищі Зорепад, на захід звідси. Мені було б цікаво що там трапилося... а тобі?", [3] = "Поговоріть з Жароном Каменотесом у селищі Зорепад.", [5] = "Еге, чим я можу тобі допомогти?", ["en"] = "Enraged Wildkin" },
    [6607] = { [1] = "Екстремальна риболовля Нета Пеґла", [2] = "Не можу сказати, що особливо люблю риболовлю. Думаю, я займаюся цим вже добрих 20 або 30 років.\n\nЛюди займаються своєю справою з різних причин.\n\nЯ не кажу, що тобі потрібно ловити рибу 30 років чи виловити всю рибу у морі, щоб стати майстром риболовлі. Я думаю, що тобі просто треба бути {стать:терплячим:терплячою} — настільки, щоб сидіти на березі годинами, нічого не роблячи.\n\nВлови мені кілька рідкісних рибин, і я навчу тебе дечого. Ось список:", [3] = "Нет Пеґл хоче, щоб ви зловили наступну рибу:\n\nМахі-махі з узбережжя Туманного Очерету на болоті Скорбот.\n\nСар'теріського мілинника з узбережжя Сар'теріс в Спустошищі.\n\nФералаську ахі з Буйної річки, що в Фераласі.\n\nСинього вітрильника з Дикого узбережжя в Тернистій долині.\n\nПоверніться до Нета Пеґла, коли зловите їх усіх!", [4] = "Ну як, щось клює?", [5] = "Ось це так улов!\n\nХоди сюди, я покажу тобі пару хитрощів.", ["en"] = "Nat Pagle, Angler Extreme", ["tasks"] = { ["Feralas Ahi"] = "фераласька ахі", ["Feralas Ahi (Provided)"] = "фераласька ахі (видано)", ["Misty Reed Mahi Mahi"] = "махі-махі Туманного Очерету", ["Misty Reed Mahi Mahi (Provided)"] = "махі-махі Туманного Очерету (видано)", ["Sar'theris Striker"] = "сар'теріський мілинник", ["Sar'theris Striker (Provided)"] = "сар'теріський мілинник (видано)", ["Savage Coast Blue Sailfin"] = "синій вітрильник Дикого узбережжя", ["Savage Coast Blue Sailfin (Provided)"] = "синій вітрильник Дикого узбережжя (видано)" } },
    [6610] = { [1] = "Омлюск-сюрприз", [2] = "Ти коли-небудь {стать:чув:чула} про омлюск? Звичайно, ти не {стать:чув:чула}! Це мій найновіший і найвеличніший кулінарний шедевр. О, {ім'я}, від однієї думки про омлюск в мене тече слина.\n\nНа жаль, у мене не вистачає продуктів, щоб приготувати його! А що, якщо ми укладемо угоду? Ти збереш продукти, які мені потрібні для приготування омлюска, а я навчу тебе дрібничок екзотичної кухні та навіть дам тобі кілька порцій! Згода??\n\nОсь, що мені потрібно:", [3] = "Могиль Хуткоріз просить вас знайти наступні інгредієнти:\n\n12 гігантських яєць. Ви знайдете їх у рухів Танарісу або будь-яких інших великих птахів.\n\n10 шматків пікантного м'яса молюсків. Його ви можете знайти, вочевидь, у молюсках!\n\n20 шматків альтерацького сиру. Йдіть до сирної крамниці!\n\nЗберіть всі інгредієнти й поверніться до Могиля.", [4] = "Моя тяга до їжі зведе мене в могилу! Поспішай, {ім'я} — бо мені доведеться лізти у власні запаси.", [5] = "На тебе чекає особлива насолода, {ім'я}. Дивись і вчись!", ["en"] = "Clamlette Surprise", ["tasks"] = { ["Alterac Swiss"] = "альтерацький сир", ["Alterac Swiss (Provided)"] = "альтерацький сир (видано)", ["Giant Egg"] = "гігантське яйце", ["Giant Egg (Provided)"] = "гігантське яйце (видано)", ["Zesty Clam Meat"] = "пікантне м'ясо молюска", ["Zesty Clam Meat (Provided)"] = "пікантне м'ясо молюска (видано)" } },
    [662] = { [1] = "Глибоководні пошуки", [2] = "О'Брін повів кораблі в бухту. Ми були впевнені, що знайдемо тут скарби. \"Провісник\" безпечно пришвартувався, але коли «Дівоча примха» та «Дух Срібнохвою» наблизилися до берега, вода почала швидко знижуватися. Я такого в житті не бачив!\n\nЦі два кораблі налетіли на щось... схоже на храм у рифі. Вони так швидко потонули, це була справжня трагедія.\n\nМи маємо повернути їхні бортові журнали та карти, перш ніж відчалити. Не можна залишити таку важливу інформацію для сторонніх очей!", [3] = "Перший помічник Нілзлікс просить вас дістати журнали та карти з «Дівочої примхи» та «Духу Срібнохвою».", [4] = "Як проходять пошуки, {ім'я}? Нам дуже потрібно повернути суднові журнали та карти з «Дівочої примхи» та «Духу Срібнохвою».\n\nЯкщо ця інформація попаде в чужі руки, командувач флоту Морський Ріг викине нас за борт.\n\nЦе якщо ми взагалі виберемося звідси...", [5] = "Звістка про те, що ця важлива інформація в безпеці, має трохи заспокоїти наше начальство в Грабіжній Бухті. Молодець, {ім'я}.", ["en"] = "Deep Sea Salvage", ["tasks"] = { ["Maiden's Folly Charts"] = "карта з \"Дівочої примхи\"", ["Maiden's Folly Charts (Provided)"] = "карта з \"Дівочої примхи\" (видано)", ["Maiden's Folly Log"] = "журнал \"Дівочої примхи\"", ["Maiden's Folly Log (Provided)"] = "журнал \"Дівочої примхи\" (видано)", ["Spirit of Silverpine Charts"] = "карта з \"Духу Срібнохвою\"", ["Spirit of Silverpine Charts (Provided)"] = "карта з \"Духу Срібнохвою\" (видано)", ["Spirit of Silverpine Log"] = "журнал \"Духу Срібнохвою\"", ["Spirit of Silverpine Log (Provided)"] = "журнал \"Духу Срібнохвою\" (видано)" } },
    [6626] = { [1] = "Сонм зла", [2] = "Відречені не намагаються перетворити всіх живих в... подібних собі... наскільки мені відомо. Та схоже, що цей дипломат радий перетворювати в невмерлих всіх охочих. Я підозрюю, що він служить Скарі.\n\nАле зараз мене більше турбують його послідовники, яких стає все більше. Вони щодня виповзають з тіней, прислужуючи йому в намаганні отримати більшу силу.\n\nЯ не зможу сама з ними впоратись, {ім'я}. Що скажеш? Допоможеш мені?", [3] = "Вбийте 8 бривоболотих боєстражів, 8 бривоболотих терноткачів та 8 мертвоголових культистів та поверніться до Міріам Місяцепісні в норах Бритвоболотих.", [4] = "Як проходить полювання, {ім'я}? Побачивши, що може зробити всього один посланець, я не сумніваюсь, що Скара — одна з найбільших загроз нашому світу.", [5] = "Дякую, {ім'я}! Це неоціненна допомога!\n\nЯ продовжу спостерігати за посланцем та тутешніми свинобразами. Якщо шукаєш пригод — візьми з собою друзів і прямуй до он тої печери, що схожа на пащу кнура. Впевнена, всередині ти знайдеш гідні випробування.", ["en"] = "A Host of Evil", ["tasks"] = { ["Death's Head Cultist"] = "мертвоголова культистка", ["Death's Head Cultist slain"] = "мертвоголова культистка: убито", ["Razorfen Battleguard"] = "бривоболотий боєстраж", ["Razorfen Battleguard slain"] = "бривоболотий боєстраж: убито", ["Razorfen Thornweaver"] = "бривоболотий терноткач", ["Razorfen Thornweaver slain"] = "бривоболотий терноткач: убито" } },
    [6628] = { [1] = "Випробування знань", [2] = "Ось ми й зустрілися знову. Ти {стать:показав:показала} неабияку завзятість, виконуючи моє завдання, і тепер мені залишилося тільки поставити тобі останнє запитання.\n\nЯкщо ти {стать:готовий:готова}, поговори зі мною знову. У тебе є час подумати, {ім'я}, можеш не квапитись, поспішати нам нікуди.", [3] = "Дайте правильну відповідь на питання Парквела Фінталласа, а потім знову поговоріть з ним. Він чекатиме в Підмісті, коли ви будете готові.", [4] = "Є тільки одне правило, якому би я хотів навчити тебе, щоб ти {стать:міг:могла} вижити в цьому світі: що більше знаєш, то більше бачиш.\n\nКоли ти вивчаєш, коли спостерігаєш — ти почнеш бачити те, чого ніхто інший не помічає.", [5] = "Молодець, {ім'я}. У мене були сумніви щодо того книги, яку я попросив тебе дістати, але ти {стать:відповів:відповіла} правильно.", ["en"] = "Test of Lore", ["tasks"] = { ["Answer Parqual Fintallas' question correctly"] = "Правильно дайте відповідь на запитання Паркуала Фінталласа" } },
    [66294] = { [1] = "Книга смертекаменів", [2] = "Ви відкриваєте старий, зношений фоліант та бачите текст, в якому детально описується некромантичний ритуал. Можливо, архімага Тарсіса зацікавить ця інформація.", [3] = "Віднесіть книгу смертекаменів архімагу Тарсісу Кір-Молдіру в Наксрамас.", ["en"] = "Book of Deathstones" },
    [663] = { [1] = "Земля!", [2] = "Лоло бачити крихітку-{раса:з}! Лоло завжди напоготові!\n\nВітаю в бухті Фалдіра! Капітан О'Брін сказав, що ми тут застрягати на кілька годин. Якраз достатньо, щоб зібрати скарби та повернутись до Грабіжної Бухти.\n\nАле Лоло думати, що ми тут застрягати надовго. Ми втратити два кораблі з нашої ескадри. Бідний «Дух Срібнохвою» і «Дівоча примха». Тепер вони спочивати на дні моря!\n\nЛоло радити тобі піти до капітана О'Бріна і поговорити з ним, якщо ти теж хочеш застрягати тут.", [3] = "Поговоріть з капітаном О'Бріном в бухті Фалдіра.", [5] = "О, здоров будь.\n\nЯке це все нещастя! Морський Ріг забере мій корабель, якщо дізнається, що тут сталося!\n\nОдна з цих хитрих професорських штуковин знайшла скарб біля бухти. Я повів «Провісника» до берега і подав сигнал «Духу Срібнохвою» і «Дівочій примсі», щоб вони приєдналися.\n\nТоді море зашуміло, вода відійшла від берега й обидва кораблі врізалися в риф.\n\nАле це був не просто риф, це було щось інше...\n\nДопоможи моїй команді, і отримаєш щедру винагороду.", ["en"] = "Land Ho!" },
    [664] = { [1] = "Затонулий смуток", [2] = "Ох, життя — жахлива штука! Я мав би зараз лежати на морському дні, а не сидіти тут, біля вогнища, дихаючи свіжим морським повітрям.\n\nМоя команда намагалася врятувати «Дівочу примху». Хай вони спочивають з миром...\n\nО'Брін спокійно дійшов до берега, а нам не пощастило. Море просто вирішило нас потопити, я клянусь.\n\nОсь ми пливемо — і ось наступна хвиля накриває нас з головою. А ці тварюки! Вони вбили всіх, хто вижив. Підле нагівське кодло. Але я якимось чином врятувався, і прийшов до тями вже тут, на березі.\n\nЯ хочу, щоб ці мерзотники здохли!", [3] = "Капітан Сталепуз з бухти Фалдіра просить вас убити 10 рейдерів та 3 чарівниць Клинкоспинів.", [4] = "Може, мені варто піти й вбити тих наг самотужки? Очевидно, що ти цього не зробиш.\n\nМоже, я знайду спиці, щоб ти {стать:міг:могла} себе чимось зайняти.", [5] = "Гарна робота, {ім'я}.\n\nЦі тварюки отримали по заслугах. Хоч це й не поверне ні мій корабель, ні команду, але смерть цих наг дає хоч якусь втіху.", ["en"] = "Drowned Sorrows", ["tasks"] = { ["Daggerspine Raider"] = "рейдер Клинкоспинів", ["Daggerspine Raider slain"] = "рейдер Клинкоспинів: убито", ["Daggerspine Sorceress"] = "чарівниця Клинкоспинів", ["Daggerspine Sorceress slain"] = "чарівниця Клинкоспинів: убито" } },
    [6642] = { [1] = "Прихильність братства, темнозалізна руда", [4] = "Темне залізо, попри те, що його досить багато в надрах, все ще є цінним товаром серед братства. Священна зброя та вбрання Раґнароса кується саме з цієї руди.\n\nЗа кожні пожертвувані тобою 10 шматків темнозалізної руда, ти отримаєш прихильність Торієвого братства.", [5] = "Твій дар прийнято. Ти {стать:заслужив:заслужила} нашу прихильність. Продовжуй у тому ж дусі, і тобі відкриється доступ до таємниць древніх ремесел.", ["en"] = "Favor Amongst the Brotherhood, Dark Iron Ore", ["tasks"] = { ["Dark Iron Ore"] = "руда темного заліза", ["Dark Iron Ore (Provided)"] = "руда темного заліза (видано)" } },
    [6643] = { [1] = "Прихильність братства, вогняне ядро", [4] = "Горе тим, хто спокушає долю всередині Палаючого Ядра. Смерть приходить швидко — покарання здійснюється без милосердя.\n\nБагато членів братства зникли у пошуках вогняних ядер.\n\nПожертвуй 1 вогняне ядро, і ти отримаєш прихильність Торієвого братства.", [5] = "Твій дар прийнято. Ти {стать:заслужив:заслужила} нашу прихильність. Продовжуй у тому ж дусі, і тобі відкриється доступ до таємниць древніх ремесел.", ["en"] = "Favor Amongst the Brotherhood, Fiery Core", ["tasks"] = { ["Fiery Core"] = "вогняне ядро", ["Fiery Core (Provided)"] = "вогняне ядро (видано)" } },
    [6644] = { [1] = "Прихильність братства, лавове ядро", [4] = "Торієве братство допомагає тим, хто заслужив нашу дружбу і повагу, {раса:к}. Власне тому Локтос уповноважений пропонувати ці угоди.\n\nПожертвуй 1 лавове ядро, і ти отримаєш прихильність Торієвого братства.", [5] = "Твій дар прийнято. Ти {стать:заслужив:заслужила} нашу прихильність. Продовжуй у тому ж дусі, і тобі відкриється доступ до таємниць древніх ремесел.", ["en"] = "Favor Amongst the Brotherhood, Lava Core", ["tasks"] = { ["Lava Core"] = "лавове ядро", ["Lava Core (Provided)"] = "лавове ядро (видано)" } },
    [6645] = { [1] = "Прихильність братства, шкіра надр", [4] = "Для багатьох виробів древнього ремесла потрібна шкіра з обраних улюбленців Раґнароса.\n\nПожертвуй 2 шкіри надр, знятої з тліючих трупів гончаків Палаючого Ядра, і ти отримаєш прихильність Торієвого братства.", [5] = "Твій дар прийнято. Ти {стать:заслужив:заслужила} нашу прихильність. Продовжуй у тому ж дусі, і тобі відкриються таємниці древніх ремесел.", ["en"] = "Favor Amongst the Brotherhood, Core Leather", ["tasks"] = { ["Core Leather"] = "шкіра ядра", ["Core Leather (Provided)"] = "шкіра ядра (видано)" } },
    [6646] = { [1] = "Прихильність братства, кров гори", [4] = "Сльози Повелителя вогню справді рідкісна знахідка.\n\nПожертвуй 1 кров гори, і ти отримаєш прихильність Торієвого братства.", [5] = "Твій дар прийнято. Ти {стать:заслужив:заслужила} нашу прихильність. Продовжуй у тому ж дусі, і тобі відкриються таємниці древніх ремесел.", ["en"] = "Favor Amongst the Brotherhood, Blood of the Mountain", ["tasks"] = { ["Blood of the Mountain"] = "кров гори", ["Blood of the Mountain (Provided)"] = "кров гори (видано)" } },
    [665] = { [1] = "Затонулий скарб", [2] = "Тепер, коли ми стали повноправними рейдерами Чорноводдя, ми повинні допомогти містеру О'Бріну знайти загублений ельфійський скарб.\n\nБез сторонньої допомоги знайти самоцвіти в морі майже неможливо. Доктор сконструював спеціальні окуляри, які мають нам допомогти. Йому потрібно зарядити ці окуляри енергією зачарованого каменю з печери, що знаходиться трохи вище по схилу пагорба.\n\nАле ця печера проклята! Коли ми наблизилися до неї, на нас напали! Захисти мене, і я зможу витягнути енергію з каменю і спрямувати її в окуляри.", [3] = "Проведіть професора Горлошипа до печери та назад.", [4] = "Ніколи базікати! Ми маємо зарядити окуляри енергією каменю!", [5] = "Окуляри працюють відмінно! Молодець, {ім'я}.", ["en"] = "Sunken Treasure", ["tasks"] = { ["Defend Professor Phizzlethorpe"] = "Захистіть професора Фізлторпа" } },
    [666] = { [1] = "Затонулий скарб", [2] = "Ці скарби лежали на морському дні так довго, що самоцвіти вкрилися вапняним нальотом і перетворились на каміння. Але сила цих окулярів дасть змогу легко їх знайти.\n\nІ все завдяки геніальності гномів!\n\nЯ позичу тобі ці окуляри, {ім'я}, і ти зможеш знайти втрачені скарби для капітана О'Бріна.\n\nЯ б і сам поплив туди, але... гм... ну, у мене є важливі наукові справи на безпечній, сухій землі.... от.", [3] = "Доктор Датчикокрут з бухти Фалдіра просить вас зібрати 10 ельфійських самоцвітів і повернутися з окулярами для пошуку самоцвітів.", [4] = "Ну що, окуляри працюють? Все функціонує як треба? Я можу їх підрегулювати, якщо треба.\n\nА, і поверни окуляри, як закінчиш. Я впевнений, що капітан О'Брін знайде їм ще багато застосувань.", [5] = "Неймовірно, {ім'я}! Капітан буде дуже задоволений! Почекай, ось ще звістку отримає командувач флоту Морський Ріг!", ["en"] = "Sunken Treasure", ["tasks"] = { ["Elven Gem"] = "ельфійський самоцвіт", ["Elven Gem (Provided)"] = "ельфійський самоцвіт (видано)", ["Goggles of Gem Hunting"] = "окуляри для пошуку самоцвітів", ["Goggles of Gem Hunting (Provided)"] = "окуляри для пошуку самоцвітів (видано)" } },
    [667] = { [1] = "Смерть з глибин", [2] = "Справи кепські. Схоже, Клинкоспини готуються до нападу.\n\nНаги відомі своєю безжальністю в бою. Вони не зупиняться, поки я не помру.\n\nНе те щоб я цінував своє життя вище, ніж життя членів команди, але ти маєш захистити мене. Екіпаж не зможе повернутися до Грабіжної Бухти без моїх знань моря.\n\nНаги прийдуть з моря. Залишайся тут зі мною і відбий їхню атаку. Берись за гармату і відтісни їх назад.\n\n{стать:Готовий:Готова}, {ім'я}?", [3] = "Захистіть Тряса О'Бріна під час нападу наг.", [4] = "До зброї!", [5] = "Ми відбили атаку!\n\nБез тебе ми б не впорались, {ім'я}.\n\nМи відпливемо, коли почнеться приплив. Якби ти не {стать:був:була} такою перспективною героїчною особистістю, я б запропонував тобі місце в команді. Але схоже, що на тебе чекає більша риба.\n\nХай навіть поки що ти лиш {стать:кволий:квола} {раса}...", ["en"] = "Death From Below", ["tasks"] = { ["Defend Shakes O'Breen"] = "Захистіть Шейкса О'Бріна" } },
    [668] = { [1] = "Затонулий скарб", [2] = "Не змушуй капітана О'Бріна чекати. Він захоче побачити ці коштовності на власні очі. Зрештою, ми тут саме для цього!\n\nПісля кількох тижнів співпраці з цими піратами ми з професором зрозуміли, що їхні скарби краще зайвий раз не тримати при собі.\n\nОсь, {ім'я}, віднеси це О'Бріну.", [3] = "Віднесіть ельфійські самоцвіти до капітана О'Бріна.", [4] = "Гей, {клас:к}. Що привело тебе на місток?", [5] = "Тож гноми врешті-решт виявилися корисними? Я знав, що ми не дарма взяли з собою цих коротунів!", ["en"] = "Sunken Treasure", ["tasks"] = { ["Elven Gems"] = "ельфійські самоцвіти", ["Elven Gems (Provided)"] = "ельфійські самоцвіти (видано)" } },
    [6681] = { [1] = "Маєток, Рейвенхольдт", [2] = "{ім'я},\n\nРейвенхольдт зацікавився тобою, {стать:юний крадію:юна крадійко}. Ми спостерігали за тобою. Тобі дещо бракує спритності, але ми зможемо це виправити.\n\nЯкщо ти {стать:готовий:готова} стати {стать:учнем:ученицею} майстра Рейвенхольдту та членом Ліги вбивць, ти маєш лише принести печатку Рейвенхольдта (прикладену до цього листа) до маєтку Рейвенхольдт.\n\nТвоє перше завдання — знайти маєток серед пагорбів Гіллзбраду та продемонструвати свої здібності.\n\nЗ повагою,\n\nФаград", [3] = "Віднесіть печатку Рейвенхольдта Фаграду в маєток Рейвенхольдт, що захований глибоко в горах Гіллзбраду.\n\nПошуки маєтку — перевірка ваших здібностей. Будьте напоготові.", [4] = "{стать:Бачив:Бачила} Мільтона?\n\n<Фаград сміється.>", [5] = "Чудово, {стать:юний крадію:юна крадійко}.\n\nВиглядаєш трохи {стать:побитим:побитою}, але не гірше, ніж раніше.\n\nНа тебе чекає довга подорож, довга та сповнена нагород. Ти {стать:готовий:готова} прийняти свою долю серед майстрів Рейвенхольдта?\n\nПоговори з вартовими назовні. Вони дадуть тобі перше завдання.", ["en"] = "The Manor, Ravenholdt", ["tasks"] = { ["Rite of Cunning"] = "Обряд хитрості", ["Rite of Cunning (Provided)"] = "Обряд хитрості (видано)", ["Rite of Cunning slain"] = "Обряд хитрості: убито", ["Seal of Ravenholdt"] = "печатка Рейвенхольдта", ["Seal of Ravenholdt (Provided)"] = "печатка Рейвенхольдта (видано)" } },
    [669] = { [1] = "Затонулий скарб", [2] = "Командувач флоту Морський Ріг захоче негайно почути про нашу знахідку.\n\nАле, як бачиш, ми поки що не в тому становищі, що вирушити звідси. Мало того, що за зараз відплив, так ще й ці тварюки не спускають з нас очей.\n\nТи можеш добряче нам допомогти, якщо скажеш командувачу флоту Морському Рогу в Грабіжній Бухті, що ми знайшли скарб і працюємо над тим, щоб дістати ще. Віднеси йому цей зразок як доказ.", [3] = "Віднесіть зразок ельфійського самоцвіту до командувача флоту Морського Рога в Грабіжну Бухту.", [4] = "Що привело тебе в Грабіжну Бухту, {клас:к}?", [5] = "А, старий Тряс О'Брін! Я знав, що вибрав правильного капітана для цього завдання.", ["en"] = "Sunken Treasure", ["tasks"] = { ["Sample Elven Gem"] = "зразок ельфійського самоцвіту", ["Sample Elven Gem (Provided)"] = "зразок ельфійського самоцвіту (видано)" } },
    [670] = { [1] = "Затонулий скарб", [2] = "Слухай, {ім'я}, ти, здається, любиш пригоди. Мій флот не зможе відплисти з Грабіжної Бухти, доки не поповнить припаси.\n\nВ цих землях назрівають темні речі, тож мені потрібно передати надсекретну кореспонденцію Трясу О'Бріну на узбережжя Араті.\n\nЧи можу я довірити тобі це важливе завдання?", [3] = "Віднесіть лист Морського Рога до капітана О'Бріна на височину Араті.", [4] = "Ну що, Морський Ріг задоволений? Б'юся об заклад, його посмішка була ширшою за його капелюх!", [5] = "Дякую тобі за цю довгу й небезпечну подорож. Ти добре {стать:послужив:послужила} рейдерам Чорноводдя.", ["en"] = "Sunken Treasure", ["tasks"] = { ["Seahorn's Sealed Letter"] = "запечатаний лист Морського Рога", ["Seahorn's Sealed Letter (Provided)"] = "запечатаний лист Морського Рога (видано)" } },
    [6701] = { [1] = "Емблеми Синдикату", [4] = "Ми роками ведемо боротьбу з Синдикатом. Нестачу навичок вони компенсують своєю чисельністю. Вона зростає швидше, ніж ми встигаємо їх вбивати!\n\nМи з'ясували, що найкращий спосіб впоратися з ними — викрасти їхні емблеми. Втративши емблему, зганьблений член Синдикату позбавляється і життя.\n\nОбчисть їхні кишені та принеси емблеми мені або іншим вартовим.\n\nПочинай з Дарнгольда, що на південь звідси.", [5] = "Гей, гарна робота! Продовжуй у тому ж дусі, і може інші пройдисвіти перестануть сміятися над тобою.", ["en"] = "Syndicate Emblems", ["tasks"] = { ["Syndicate Emblem"] = "емблема Синдикату", ["Syndicate Emblem (Provided)"] = "емблема Синдикату (видано)" } },
    [678] = { [1] = "Заклик до зброї", [2] = "Твоя сила вражає, {ім'я}. Тепер подивимося, як ти впораєшся зі справжнім ворогом.\n\nБрилорукі огри мають лігво на південний захід звідси, у напрямку мосту дворфів. Якщо не помиляюсь, тамтешні моцаки та чаклуни мають стати для тебе серйознішим випробуванням — принаймні такими вони були для нас.\n\nВбий стільки огрів, скільки зможеш, або повернись у формі духа після смерті. У будь-якому разі я віддам хвалу твоїй стійкості в бою.", [3] = "Вбийте 10 брилоруких моцаків та 4 брилоруких чаклунів, після чого поверніться до Драма Кепського в аванпост Молотобій.", [4] = "Ти сумніваєшся. Чому? Ти {стать:побив:побила} цих покидьків Зів'ялої Кори, {ім'я}. Не підведи мене зараз...", [5] = "Ти {стать:сильний:сильна}, як кодо, і твій героїзм в битві надихає наш народ.", ["en"] = "Call to Arms", ["tasks"] = { ["Boulderfist Brute"] = "брилорукий моцак", ["Boulderfist Brute slain"] = "брилорукий моцак: убито", ["Boulderfist Magus"] = "брилорукий чаклун", ["Boulderfist Magus slain"] = "брилорукий чаклун: убито" } },
    [6804] = { [1] = "Отруйна вода", [2] = "Ми відправили групу елементалів-розвідників в Східні Зачумлені землі Лордерона, і хвороба того місця спотворила і заразила їх. Водоповелителі не можуть допустити такої наруги над нашою чистотою!\n\nВізьміть цей флакон. В ній міститься аспект Нептулона. Якщо використати його на зачумлених елементалях, він поборе отруту в їх тілах і вилікує їх! Однак цей процес настільки болісний, що деякі з них можуть збожеволіти.\n\nПереможи ці збожеволілі сплески та принеси мені їхні браслети.", [3] = "Використайте аспект Нептулона на отруєних елементалях у Східних Зачумлених землях. Принесіть 12 браслетів збожеволілих сплесків і аспект Нептулона герцогу Гідраксісу в Азшару.", [4] = "Ти {стать:приніс:принесла} браслети?", [5] = "Ти добре {стать:попрацював:попрацювала}, {клас:к}. Заражені елементалі, яких ти {стать:вилікував:вилікувала}, були ганьбою для всього нашого племені. Наша сила в нашій чистоті, і якщо ми хочемо перемогти у війні, ми повинні залишатися сильними.", ["en"] = "Poisoned Water", ["tasks"] = { ["Aspect of Neptulon"] = "аспект Нептулона", ["Aspect of Neptulon (Provided)"] = "аспект Нептулона (видано)", ["Discordant Bracers"] = "браслет збожеволілого сплеска", ["Discordant Bracers (Provided)"] = "браслет збожеволілого сплеска (видано)" } },
    [6805] = { [1] = "Буревісники та гуркотуни", [2] = "Ми, елементалі води, ведемо війну з істотами менших елементів. Якщо ти дійсно {стать:наш союзник:наша союзниця} у цьому конфлікті, то покажи мені свою відданість!\n\nДалеко на півдні, в пустелі Силітус, у скелястому куточку, що зветься Кристальною Долиною, знаходяться слуги повітря та землі. Вони захищають приховані там предмети сили від примітивних істот, смертних. Мені немає ніякої справи до того, що вони там стережуть, я хочу, щоб ти їх {стать:вбив:вбила}.\n\nВирушай в Кристальну Долину в Силітусі та переможи наших ворогів, а потім повертайся до мене.", [3] = "Убийте 15 пустельних буревісників і 15 пустельних гуркотунів, а потім поверніться до герцога Гідраксіса в Азшару.", [4] = "Боягузтво — це не те що ми поважаємо, {клас:к}. Йди в Силітус і доведи свою хоробрість.", [5] = "Ти {стать:довів:довела} свою хоробрість і цінність для нас. Можливо, у мене будуть для тебе ще завдання, більш гідні для {стать:союзника:союзниці} Водоповелителів.", ["en"] = "Stormers and Rumblers", ["tasks"] = { ["Desert Rumbler"] = "пустельний гуркотун", ["Desert Rumbler slain"] = "пустельний гуркотун: убито", ["Dust Stormer"] = "пустельний буревісник", ["Dust Stormer slain"] = "пустельний буревісник: убито" } },
    [6821] = { [1] = "Око Вуглегляда", [2] = "Ти {стать:показав:показала} мені, що {стать:здатний:здатна} перемагати наших ворогів і виконувати завдання Водоповелителів. Але досі ти {стать:бився:билася} лише з менш потужними ворогами... Якщо ти зіткнешся з сильним противником, чи зможеш ти перемогти?\n\nЦе твоє нове завдання.\n\nВисоко в Чорноскельному шпилі знаходяться орки, які взяли в полон прислужника вогню — вогнестража Вуглегляда. Знайди місце його ув'язнення, знищ всіх полонителів, а потім вбий його самого. Принеси мені його око, і воно доведе мені твою силу.", [3] = "Принесіть око Вуглегляда герцогу Гідраксісу в Азшару.", [4] = "Око у тебе, {клас:к}? Чи є у тебе сила, щоб увійти у Чорноскельний шпиль?", [5] = "А, то ти маєш силу. А також хитрість, бо для того, щоб побувати в Чорноскельному шпилі, потрібно більше, ніж просто груба сила.\n\nДійсно, {ім'я}, ти ще можеш стати нам {стать:цінним союзником:цінною союзницею}...", ["en"] = "Eye of the Emberseer", ["tasks"] = { ["Eye of the Emberseer"] = "око Вуглегляда", ["Eye of the Emberseer (Provided)"] = "око Вуглегляда (видано)" } },
    [6822] = { [1] = "Палаюче Ядро", [2] = "{ім'я}, можливо, настав час для справжнього випробування. Ти {стать:готовий:готова}?\n\nНа дні Чорноскельних надр є прохід до Палаючого Ядра. Це фортеця наших ворогів, яка охороняється найпотужнішими слугами вогню на цьому світі.\n\nЙди до Палаючого Ядра, {ім'я}. Покажи мені, що ти маєш силу та волю, щоб перемогти все, що знайдеш там.\n\nА якщо ти маєш союзників серед свого народу, то збери їх разом. Ніщо, крім армії, не може пройти до Вогняних Надр та вижити.", [3] = "Вбийте 1 лорда вогню, 1 розплавленого велетня, 1 древнього гончака ядра та 1 лавового сплеска, а потім поверніться до герцога Гідраксіса в Азшару.", [4] = "Звершення у Палаючому Ядрі чекають на тебе, {ім'я}.", [5] = "Ти {стать:зробив:зробила} те, що більшість твого народу вважала б неможливим. Ти {стать:зіткнувся:зіткнулася} з істотами Палаючого Ядра і {стать:переміг:перемогла}!\n\nЯк на таку маленьку істоту, ти {стать:показав:показала} неабияку силу.\n\nКолись, можливо, ми зможемо досягти справжньої вірності між твоїм видом і Водоповелителями.", ["en"] = "The Molten Core", ["tasks"] = { ["Ancient Core Hound"] = "древній гончак ядра", ["Ancient Core Hound slain"] = "древній гончак ядра: убито", ["Firelord"] = "лорд вогню", ["Firelord slain"] = "лорд вогню: убито", ["Lava Surger"] = "лавовий сплеск", ["Lava Surger slain"] = "лавовий сплеск: убито", ["Molten Giant"] = "розплавлений велетень", ["Molten Giant slain"] = "розплавлений велетень: убито" } },
    [6823] = { [1] = "Агент Гідраксіса", [2] = "Якщо ти справді хочеш стати {стать:нашим союзником:нашою союзницею}, візьми участь у війні з нашими ворогами, прислужниками повітря, землі та вогню. Кожна їхня поразка, завдана тобою, послабить їхні позиції та доведе твою відданість нашій справі.\n\nЦя кампанія буде довгою, але наполегливість принесе тобі велику славу та честь.", [3] = "Досягніть почесності з фракцією Гідраксійських Водоповелителів, а потім поговоріть з герцогом Гідраксісом в Азшарі.", [4] = "Твою кампанію ще не завершено, {ім'я}. Йди та перемагай наших ворогів, прислужників повітря, землі та вогню, і одного дня ти, можливо, заслужиш місце в залах Водоповелителів.", [5] = "Твої подвиги в битві проти наших ворогів бринять в залах Водоповелителів, {ім'я}. Дехто вважав, що ти занадто {стать:малий:мала} та {стать:тендітний:тендітна} для того, аби битися в нашій війні, але ти {стать:досяг:досягла} величезних успіхів. Ти {стать:заслужив:заслужила} на нашу повагу — це неймовірне досягнення.", ["en"] = "Agent of Hydraxis", ["tasks"] = { ["9000 reputation with Hydraxian Waterlords"] = "9000 репутації у Гідраксійських Водоловів" } },
    [6824] = { [1] = "Руки ворога", [2] = "{ім'я}, твоя служба має для нас велику цінність, тому ми неохоче відсилаємо тебе на це останнє завдання, оскільки не хочемо втратити такого корисного агента.\n\nАле його успіх надзвичайно зміцнить наші воєнні зусилля і... було вирішено ризикувати тобою.\n\nМи хочемо знищити цих капітанів Палаючого Ядра: Люцифрона, Сульфурона, Геєнаса і Шаззраха. Вбий їх та принеси мені їхні руки!\n\nЦе завдання вимагатиме від тебе всіх можливих ресурсів, {ім'я}, але якщо ти зможеш це зробити, то володари вогню зазнають страшенного удару.", [3] = "Принесіть руки Люцифрона, Сульфурона, Геєнаса і Шаззраха до герцога Гідраксіса в Азшару.", [4] = "Чи {стать:переміг:перемогла} ти Люцифрона та інших, {ім'я}? Ти {стать:приніс:принесла} руки наших ворогів?", [5] = "Вони в тебе! Ти {стать:переміг:перемогла} капітанів вогню! Я б не подумав, що це можливо, якби не знав тебе та твої можливості.\n\n{ім'я}, твої подвиги незліченні, але цей останній викличе хвилю серед Водоповелителів. Твоє ім'я може стати для нас легендою.\n\nПоговори зі мною ще раз, {ім'я}. Можливо, у мене знайдеться ще одне завдання...", ["en"] = "Hands of the Enemy", ["tasks"] = { ["Hand of Gehennas"] = "рука Геєнаса", ["Hand of Gehennas (Provided)"] = "рука Геєнаса (видано)", ["Hand of Lucifron"] = "рука Люцифрона", ["Hand of Lucifron (Provided)"] = "рука Люцифрона (видано)", ["Hand of Shazzrah"] = "рука Шаззраха", ["Hand of Shazzrah (Provided)"] = "рука Шаззраха (видано)", ["Hand of Sulfuron"] = "рука Сульфурона", ["Hand of Sulfuron (Provided)"] = "рука Сульфурона (видано)" } },
    [683] = { [1] = "Прохання Сари Баллу", [2] = "{ім'я}, у мене є до тебе невелике прохання.\n\nВіднеси мою записку великому монарху Залізогарта, королю Маґні Бронзобородому. Це буде не складно для {стать:такого відважного героя:такої відважної героїні} Альянсу.\n\nМені в моєму горі зараз важко буде постати перед королем. Ти, звісно, розумієш мене.", [3] = "Віднесіть записку Сари Баллу королю Маґні Бронзобородому в Залізогарт.", [4] = "То ти {ім'я}-{клас}? Слава твоїх подвигів на службі Альянсу випереджає тебе.\n\nЩо тебе привело до мене сьогодні?", [5] = "Хвилинку, дай-но я прочитаю цього листа...", ["en"] = "Sara Balloo's Plea", ["tasks"] = { ["Sara Balloo's Plea"] = "прохання Сари Баллу", ["Sara Balloo's Plea (Provided)"] = "прохання Сари Баллу (видано)" } },
    [6841] = { [1] = "<UNUSED>", [2] = "х", ["en"] = "<UNUSED>" },
    [6842] = { [1] = "<UNUSED>", [2] = "х", ["en"] = "<UNUSED>" },
    [6843] = { [1] = "Да Фу", ["en"] = "Da Foo" },
    [6844] = { [1] = "Умбер, архіваріус", [2] = "Тут ще багато чого треба зробити, але я вважаю, що першим ділом потрібно віднести це до Кола для аналізу. Повір мені — тут буде ще купа роботи, навіть коли все буде зроблено. Якщо під цим хітином щоденник, то Коло нарешті зможе заглянути у минуле!\n\nВіднеси це архіваріусу Кола в Нічну Гавань. Його звуть Умбер і він справжній геній. З відхиленнями, звісно, але все одно геній! Умбер рятував фоліанти в набагато гіршому стані, ніж цей. Якщо ці записи можна врятувати, він це зробить.", [3] = "Віднесіть вкриту хітином річ Умберу — архіваріусу Кенарійського Кола, у селище Нічна Гавань, що на Місячній галявині.", [4] = "О, привіт! Хмм...\n\nБуду з тобою відвертим, {стать:друже:подруго}... Від тебе чимось тхне. Навіть можна сказати, смердить. Я не хочу тебе образити. Просто кажу... На майбутнє, прийшовши з бою, не забудь трохи освіжитись. Це покращить перші враження про тебе!\n\nНу, хай там як... Чим я можу тобі допомогти?", [5] = "Отакої, святі мавпячі жаби! Що це у тебе? Напевно, щось схоже на книжку... Спробую розбити оболонку.\n\nТебе прислав Лайо з Силітуса? Я чув лише сумнівні чутки — хоча, гадаю, не такі вже й сумнівні, якщо подумати — про жахіття, які там відбуваються. Враховуючи мою ненависть до всього комахоподібного, ти зрозумієш, чому я маю сидіти тут, з книжками!", ["en"] = "Umber, Archivist", ["tasks"] = { ["Encrusted Silithid Object"] = "вкрита хітином річ", ["Encrusted Silithid Object (Provided)"] = "вкрита хітином річ (видано)" } },
    [6845] = { [1] = "Розкриття таємниць минулого", [2] = "У будь-якому разі, тобі варто навідати мене відносно скоро... якщо, звичайно, ти хочеш знати, що тут, усередині. Щойно я про це дізнаюсь і якщо там дійсно книга — я залюбки поділюся з тобою цією інформацією.\n\nТим часом я зв'яжуся з матусею цього невеличкого ведмежого табору — Рабіном. Не сумніваюся, що він захоче дізнатися про твої божевільні витівки. Ніколи не змушуй матусю чекати, {Ім'я}... хіба що ти хочеш скупатися у меді.\n\nТаке траплялося, повір мені.", [3] = "Поговоріть з Рабіном Сатурною в селищі Нічна Гавань на Місячній галявині.", [5] = "А, {Ім'я}. Я сподівався, що ти завітаєш. Радий бачити, що у тебе все добре.\n\nМене повідомили, що ти прийдеш, і я хотів би особисто виразити подяку від Кенарійського Кола за досі надану тобою допомогу. Безсумнівно, в Силітусі є ще багато таємниць, які варто розкрити. Те, що ти {стать:доставив:доставила} Умберові, може виявитися однією з найцікавіших. Будь ласка, прийми це на знак нашої вдячності за твою підтримку.\n\nДякую, {стать:благородний:благородна} {клас:к}.", ["en"] = "Uncovering Past Secrets" },
    [6846] = { [1] = "В атаку!", [4] = "Мої бійці отримали все необхідне і готові до штурму. Залишилося отримати наказ від Нореґа Бурешпиля і можна відправляти їх у бій!", [5] = "А, накази! В них сказано, що я можу атакувати коли захочу, а хочу я... зараз!", ["en"] = "Begin the Attack!", ["tasks"] = { ["Stormpike Assault Orders"] = "наказ Бурешпиля про атаку", ["Stormpike Assault Orders (Provided)"] = "наказ Бурешпиля про атаку (видано)" } },
    [6847] = { [1] = "Всевидяче око майстра Райсона", [2] = "Синдикату все одно на війну, яка ведеться в самому серці Альтераку, {клас:к}. Ми робитимемо те, що робили завжди — зачекаємо, поки з попелу і руїн цього божевілля не з'явиться явний переможець, а потім завдамо удару.\n\nАле зараз нас тут цікавить дещо інше. Всевидяче око зникло — його забрали тролі з племені Зимної Сокири.\n\nПоверни око і ми завжди будемо до твоїх послуг, що б не сталося.\n\nПовертайся, коли знайдеш око, я перевірю тебе.\n\n<Майстер Райсон посміхається.>", [3] = "Знайдіть всевидяче око майстра Райсона в печерах Зимної Сокири та поверніть його майстру Райсону.\n\nБудьте обережні, кажуть, що на всевидяче око майстра Райсона накладено жахливе прокляття!", ["en"] = "Master Ryson's All Seeing Eye", ["tasks"] = { ["Master Ryson's All Seeing Eye Recovered"] = "Всевидюче око майстра Райсона знайдено" } },
    [6848] = { [1] = "Всевидяче око майстра Райсона", [2] = "Синдикату все одно на війну, яка ведеться в самому серці Альтераку, {клас:к}. Ми робитимемо те, що робили завжди — зачекаємо, поки з попелу і руїн цього божевілля не з'явиться явний переможець, а потім завдамо удару.\n\nАле зараз нас тут цікавить дещо інше. Всевидяче око зникло — його забрали тролі з племені Зимної Сокири.\n\nПоверни око і ми завжди будемо до твоїх послуг, що б не сталося.\n\nПовертайся, коли знайдеш око, я перевірю тебе.\n\n<Майстер Райсон посміхається.>", [3] = "Знайдіть всевидяче око майстра Райсона в печерах Зимної Сокири та поверніть його майстру Райсону.\n\nБудьте обережні, кажуть, що на всевидяче око майстра Райсона накладено жахливе прокляття!", ["en"] = "Master Ryson's All Seeing Eye", ["tasks"] = { ["Master Ryson's All Seeing Eye Recovered"] = "Всевидюче око майстра Райсона знайдено" } },
    [686] = { [1] = "Королівські почесті", [2] = "Я і не очікую, що такі добрі дворфи, як місіс Баллу, зрозуміють, що нам доводиться терпіти жахи війни заради блага нашого народу. Загибель її чоловіка, як і втрата кожного дворфа, що б'юєься в ім'я Альянсу, лежить тяжким тягарем на моїй душі.\n\nМені не під силу повернути її чоловіка з Підсвітньої Крутоверті, але я можу хоча б вшанувати його пам'ять.\n\nЯ маю намір замовити у головного каменяра Мармуренка пам'ятник Саллі Баллу.\n\nПередай йому мої слова, {клас:к}. Ти будеш {стать:посланцем:посланницею} моєї волі.", [3] = "Король Маґні Бронзобородий хоче, щоб ви поговорили з головним каменярем Мармуренком.", [5] = "То тебе прислав король Маґні Бронзобородий?\n\nЙой! Це певно щось важливе!", ["en"] = "A King's Tribute" },
    [6861] = { [1] = "Портативний подрібнювач Зінфіззлекса", [2] = "Мені, так само як і тобі, не терпиться випробувати мій портативний подрібнювач, {раса:к}, але перш ніж я зможу його виготовити, мені знадобляться матеріали — багато матеріалів!\n\nЯкщо точніше, мені знадобиться гора торію, мітрилу та заліза. Окрім того, потрібно по одній паровій пилці на кожен подрібнювач. Ти зможеш знайти їх на лісопильні.\n\nПрогулюючись по околицях (до того, як мене схопили), я помітив купу парових пилок у лісозаготівельному таборі Бурешпиля.", [3] = "Головний інженер Зінфіззлекс просить вас принести йому наступні матеріали:\n\n*30 злитків торію.\n\n*50 злитків мітрилу.\n\n*75 злитків заліза.\n\n*1 парову пилку.", ["en"] = "Zinfizzlex's Portable Shredder Unit", ["tasks"] = { ["Iron Bar"] = "злиток заліза", ["Iron Bar (Provided)"] = "злиток заліза (видано)", ["Mithril Bar"] = "злиток мітрилу", ["Mithril Bar (Provided)"] = "злиток мітрилу (видано)", ["Steamsaw"] = "парова пилка", ["Steamsaw (Provided)"] = "парова пилка (видано)", ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [6862] = { [1] = "Портативний подрібнювач Зінфіззлекса", [2] = "Мені, так само як і тобі, не терпиться випробувати мій портативний подрібнювач, {раса:к}, але перш ніж я зможу його виготовити, мені знадобляться матеріали — багато матеріалів!\n\nЯкщо точніше, мені знадобиться гора торію, мітрилу та заліза. Окрім того, потрібно по одній паровій пилці на кожен подрібнювач. Ти зможеш знайти їх на лісопильні.\n\nПрогулюючись по околицях (до того, як мене схопили), я помітив купу парових пилок у лісозаготівельному таборі Морозних Вовків.", [3] = "Головний інженер Зінфіззлекс просить вас принести йому наступні матеріали:\n\n*30 злитків торію.\n\n*50 злитків мітрилу.\n\n*75 злитків заліза.\n\n*1 парову пилку.", ["en"] = "Zinfizzlex's Portable Shredder Unit", ["tasks"] = { ["Iron Bar"] = "злиток заліза", ["Iron Bar (Provided)"] = "злиток заліза (видано)", ["Mithril Bar"] = "злиток мітрилу", ["Mithril Bar (Provided)"] = "злиток мітрилу (видано)", ["Steamsaw"] = "парова пилка", ["Steamsaw (Provided)"] = "парова пилка (видано)", ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [687] = { [1] = "Тельдурін Загублений", [2] = "Тельдурін Загублений був членом нашого ордену, Сутінкового Молота. Однак він збожеволів і відкинув наше вчення. Але перед втечею він викрав у нас сувій Мізраель! Ми не змогли зловити його, але ходять чутки, що він зовсім збожеволів і ховається в Безплідних краях.\n\nЩоб повернути до нас Пані, ми повинні знайти сувій. А для цього ти маєш знайти Тельдуріна.", [3] = "Знайдіть Тельдуріна Загубленого.", [5] = "Привіт. Привіт, привіт привіт привіт ПРИВІТ!!!\n\nВибач — ні, не вибач! Не груби мені!\n\nО, ні... це було божевілля.\n\nАле іноді божевілля — єдине спасіння.", ["en"] = "Theldurin the Lost" },
    [6901] = { [1] = "В атаку!", [4] = "Мої бійці отримали все необхідне і готові до штурму. Залишилося отримати наказ від квартирмейстера Морозних Вовків і можна відправляти їх у бій!", [5] = "Давно пора! Тепер ми можемо показати Альянсу, що дарма вони прийшли в Альтерацьку долину!", ["en"] = "Launch the Attack!", ["tasks"] = { ["Frostwolf Assault Orders"] = "наказ Морозних Вовків про атаку", ["Frostwolf Assault Orders (Provided)"] = "наказ Морозних Вовків про атаку (видано)" } },
    [692] = { [1] = "Утрачені фрагменти", [2] = "Сувій Мізраелі... сувій Мізраелі?! Ти цього не хочеш! Його магія може витягнути Мізраель на поверхню, і якщо ти це зробиш — буде біда!\n\nАбо... можливо, вже занадто пізно. Можливо, вона вже вільна. Можливо, вона просто збирає сили, перш ніж обрушитися на нас. Якщо це так, то тобі точно ПОТРІБЕН сувій!\n\n...шкода, що він знищений. Розлючені елементалі вкрали його і розірвали на шматки, а тепер б'ються за його фрагменти.\n\nАле якщо ти зможеш зібрати ці фрагменти, можливо, нам вдалося б відновити сувій...", [3] = "Принесіть рваний, м'ятий і обпалений фрагменти сувою Тельдуріну Загубленому.", [4] = "Ти {стать:знайшов:знайшла} ці фрагменти?!?! Тобі потрібен сувій Мізраелі, якщо ти хочеш знову її полонити, поки ще не стало занадто пізно!", [5] = "Ах, ти їх {стать:знайшов:знайшла}! Чудова робота, {ім'я}! Вони, можливо, наш єдиний шанс протистояти злу Мізраелі!\n\nДай-но мені знайти мій лом-храповик і побачимо, чи зможу я з'єднати ці фрагменти...", ["en"] = "The Lost Fragments", ["tasks"] = { ["Crumpled Scroll Fragment"] = "м'ятий фрагмент сувою", ["Crumpled Scroll Fragment (Provided)"] = "м'ятий фрагмент сувою (видано)", ["Singed Scroll Fragment"] = "обпалений фрагмент сувою", ["Singed Scroll Fragment (Provided)"] = "обпалений фрагмент сувою (видано)", ["Torn Scroll Fragment"] = "рваний фрагмент сувою", ["Torn Scroll Fragment (Provided)"] = "рваний фрагмент сувою (видано)" } },
    [695] = { [1] = "Чари учня", [2] = "Ось, {ім'я}. Самоцвіт потрібно розмістити на одному з п'єдесталів біля основи вежі, щоб активувати її захист. Використай його, коли будеш {стать:готовий:готова} зайти в вежу і знайти решту речей Трелейна.\n\nНехай щастить. Я чекатиму на твоє повернення тут, в таборі. А, і поговори зі Скуерто — він розповість тобі більше деталей.", [3] = "Поговоріть зі Скуерто.", [5] = "Добре, добре.\n\nЯкщо нас нічого більше не затримує, мо' почнем?", ["en"] = "An Apprentice's Enchantment", ["tasks"] = { ["Enchanted Agate"] = "зачарований агат" } },
    [696] = { [1] = "Атака на вежу", [2] = "Ось що ти маєш знайти: філактерію Трелейна, сферу Трелейна та червоний агат Трелейна.\n\nCі речі мають бути в скринях у вежі, тож знайти їх буде не важко, але стережиси огрів.\n\nЗахист вежі не впораєтьси з ними, тож тримай зброю напоготові. Якщо вони збагнуть, що ти там і намагаєшся обікрасти їх — ясна річ, вони вирішать дати тобі прочухана.\n\nБудь {стать:обережний:обережна} і нехай тобі щастить.", [3] = "Знайдіть філактерію, сферу та червоний агат Трелейна. Поверніться з ними до Скуерто в Опорний пункт.", [4] = "Як все зробиш — певен, Малін буде задоволений.", [5] = "Малін не зміг би знайти нікого кращого нам в поміч, {ім'я}. Приголомшлива робота!\n\nВін буде радий дізнатись про наші успіхи!", ["en"] = "Attack on the Tower", ["tasks"] = { ["Trelane's Ember Agate"] = "червоний агат Трелейна", ["Trelane's Ember Agate (Provided)"] = "червоний агат Трелейна (видано)", ["Trelane's Orb"] = "сфера Трелейна", ["Trelane's Orb (Provided)"] = "сфера Трелейна (видано)", ["Trelane's Phylactery"] = "філактерія Трелейна", ["Trelane's Phylactery (Provided)"] = "філактерія Трелейна (видано)" } },
    [697] = { [1] = "Прохання Маліна", [2] = "Віднеси цей лист в Штормовій і повідом Маліну, що ми з Крітеном скоро повернемоси. Він тебе файно винагородить за допомогу, {клас:к}, в цьому я не сумніваюсь.\n\nЩасливої дороги.", [3] = "Віднесіть запечатаний лист до архімага Маліна у квартал Магів Штормовію.", [4] = "Так? Твоє обличчя мені знайоме. Я перепрошую, але ми раніше не зустрічалися? Я настільки зайнятий, що починаю забувати.", [5] = "<Архімаг Малін відкриває лист і він широко відкриває очі.>\n\nХвала Світлу, тобі вдалося. Як це чудово. Трілейн буде задоволений. Я впевнений, що Крітейн та Скуерто так само раді, як і я, і можуть повернутися в Штормовій.\n\nЩе раз дякую, {ім'я}. Ось, візьми це. Сподіваюсь, воно стане тобі у пригоді.", ["en"] = "Malin's Request", ["tasks"] = { ["Sealed Letter to Archmage Malin"] = "запечатаний лист до архімага Маліна", ["Sealed Letter to Archmage Malin (Provided)"] = "запечатаний лист до архімага Маліна (видано)" } },
    [6981] = { [1] = "Сяючий уламок", [2] = "Уламок яскраво зелений і, не дивлячись на суцільність, під його поверхнею клубочиться щось схоже на дим. Ви не можете відірватись від кристала і водночас він викликає тривожність.\n\nМожливо, вам варто пошукати в Брашпилі когось, хто зможе розказати про цей кристал більше.", [3] = "Відправляйтесь до Брашпиля і знайдіть когось, хто може розказати більше про сяючий уламок.\n\nОпісля, віднесіть уламок туди, куди вас відправлять.", [4] = "Вітаю, {раса:к}. Чим я можу допомогти?", [5] = "Ох... ніколи не бачила нічого подібного...", ["en"] = "The Glowing Shard", ["tasks"] = { ["Glowing Shard"] = "сяючий уламок", ["Glowing Shard (Provided)"] = "сяючий уламок (видано)" } },
    [700] = { [1] = "Королівські почесті", [2] = "Ах, який в Лордероні гарний камінь. Як шкода, що ці землі лежать в руїні.\n\nАле пам'ятник вийшов доволі непоганий! Впевнений, король буде задоволений.\n\nА тепер, будь ласка, передай Його Величності, що його прохання виконано.", [3] = "Передайте звістку королю Маґні Бронзобородому.", [5] = "Граніт — така дрібниця в порівнянні з життям гідного дворфа. Та жоден дворф на цьому світі не вічний.\n\nСподіватимемося, що цей меморіал стане нагадуванням майбутнім поколінням Азерота. Ми ніколи не забудемо, що за них віддали життя відважні солдати. Такі, як Саллі Баллу.", ["en"] = "A King's Tribute" },
    [7003] = { [1] = "Зменшення велетнів", [2] = "Я маю зробити щось з цими велетнями, якщо хочу тут залишитись! Вони гублять весь бізнес!\n\nЯ працюю над аналогом гномського зменшувального променя, але з використанням унікальних ГОБЛІНСЬКИХ технологій! Щоб уникнути різних незручностей, по типу смерті, я доручаю його випробування тобі. Перевір його на будь-яких велетнях Фераласа. Після його роботи ти зможеш знайти на них залишки мініатюаризації — принеси їх мені!", [3] = "Використовуйте ультразменшувач Зорбіна, щоб зменшити будь-якого велетня Фераласа до менш небезпечної форми. Принесіть 15 залишків мініатюризації Зорбіну Блимоверту близ причалу Забутого узбережжя, що у Фераласі.", [4] = "Залишки мініатюризації — цінна штука для інженера! Їхня цінність полягає в тому, що вони дозволяють мені впевнитись, що у зменшувача не буде неочікуваних побічних ефектів, як от вибуху в руках користувача.\n\nО, це я про інші зменшувачі, не той який я тобі дав. Абсолютно точно!", [5] = "Пресуперово! Радий бачити, що ти {стать:повернувся:повернулася} не тільки з залишками, а й з усіма своїми кінцівками! Ні-ні, використання ультразменшувача було абсолютно безпечним!\n\nЯ ціную твої зусилля для мене, {ім'я}. Чесне слово, ти — друг для гоблінів у всьому світі. Прийми це на знак моєї вдячності!", ["en"] = "Zapped Giants", ["tasks"] = { ["Miniaturization Residue"] = "залишок мініатюризації", ["Miniaturization Residue (Provided)"] = "залишок мініатюризації (видано)" } },
    [7028] = { [1] = "Плетене зло", [2] = "На заході, в глибинах Мародона, розташовані кристальні печери Террамока... Це древнє місце з багатою історією. І я хочу здобути деякі речі звідти, {клас:к}. Реліквії Старих Богів заховані за величезними дверима.\n\nЯкщо ти наважишся кинути виклик злу, що таїться в Мародоні, я щедро тобі віддячу. Збери терадричні кришталеві орнаменти та принеси їх мені.\n\nКоли я отримаю орнаменти, я зможу їх... дослідити. Занадто довго ці сили лежали без діла...", [3] = "Зберіть 25 терадричних кришталевих орнаментів для Верби зі Спустошища.", [4] = "Жодних запитань!\n\nТи маєш виконати моє прохання.", [5] = "Ха-ха-ха! Я знала, що ти повернешся!\n\n<Верба щось бурмоче.>\n\n...так легко переконати.\n\n...що завгодно зробить за хорошу оплату. Хе-хе-хе...", ["en"] = "Twisted Evils", ["tasks"] = { ["Theradric Crystal Carving"] = "терадричний кришталевий орнамент", ["Theradric Crystal Carving (Provided)"] = "терадричний кришталевий орнамент (видано)" } },
    [7029] = { [1] = "Прокляття Злоязикого", [2] = "Сатир, на ім'я Злоязикий, прокляв печери Мародона, призупинивши ріст більшості рослин.\n\nВізьми цей флакон, {ім'я}. Наповни його з кришталевого помаранчевого озера в печерах. Покриття всередині флакона буде протидіяти токсинам, перетворюючи його на ліки.\n\nЗнайди у помаранчевих печерах злолози та полий їх цілющою рідиною. Псування покине рослини, але все одно залишиться під контролем Злоязикого. Тож він може використати його проти тебе...", [3] = "Наповніть лазуровий флакон з покриттям в кришталевому помаранчевому озері, що в Мародоні.\n\nПолийте злолозу з наповненого лазурового флакона, щоб вигнати породження Ноксіона.\n\nЗціліть 8 рослин, вбиваючи породження Ноксіона, після чого поверніться до Варка Битвошрама в селище Тінездобич.", [4] = "Якщо ти зможеш вилікувати рослину, вона знову почне рости. Ми повинні зробити все, що в наших силах, {ім'я}...", [5] = "Дякую, що {стать:приніс:принесла} його, {ім'я}. Я зможу продовжити вивчення цієї рідини завдяки цим залишкам.\n\nХоч і попереду ще багато роботи, ти {стать:допоміг:допомогла} зняти частину прокляття, яке Злоязикий поширював у Мародоні. Прошу, прийми це на знак моєї подяки.", ["en"] = "Vyletongue Corruption", ["tasks"] = { ["Filled Cerulean Vial"] = "наповнений лазуровий флакон", ["Filled Cerulean Vial (Provided)"] = "наповнений лазуровий флакон (видано)", ["Vylestem Vines healed"] = "Вилестемські лози зцілилися", ["Vylestem Vines healed (Provided)"] = "Вилестемські лози зцілилися (видано)", ["Vylestem Vines healed slain"] = "Вилестемські лози зцілилися: убито" } },
    [703] = { [1] = "Смажені крильця канюків", [2] = "О так, мої смажені крильця канюків просто обожнюють! Сповнений смаку соус і соковите м'ясце. А їхній аромат змусить голодних прибігти за милі звідси!\n\nУ мене є все, що потрібно, для приготування. Все... окрім крилець канюка!\n\nЯкщо хочеш їх спробувати, добудь мені такі крильця. Принесеш достатньо, і, може, я навіть поділюся рецептом з тобою!", [3] = "Принесіть 4 крила канюка Смиколяпу.", [4] = "Привіт, {ім'я}. {стать:Приніс:Принесла} мені мої крильця?", [5] = "О, я одразу почну їх готувати. Я вже майже відчуваю їхній смак!\n\nІ ось тобі рецепт, на випадок, якщо захочеш зробити ці крильця {стать:сам:сама}!", ["en"] = "Barbecued Buzzard Wings", ["tasks"] = { ["Buzzard Wing"] = "крило канюка", ["Buzzard Wing (Provided)"] = "крило канюка (видано)" } },
    [704] = { [1] = "Доля Аґмонда", [2] = "Останній звіт від Аґмонда занепокоює, тим паче, що тепер він мертвий! Він згадував, що його землекопи знайшли \"стародавні урни\" на розкопках біля Ульдамана. Я боюся що урни, які він знайшов на тому місці, вплинули на трогів так само як і ідоли, які я знайшов тут.\n\nМені потрібно, щоб ти {стать:дістав:дістала} ці урни для наших досліджень. Вирушай до Ульдаману, збери урни та повертайся до мене.", [3] = "Принесіть 4 різьблені кам'яні урни розвідувачеві Залізоплету у Лох-Модан.", [4] = "Ти {стать:знайшов:знайшла} урни, {ім'я}? Ми маємо знайти зв'язок між ними та трогами!", [5] = "Чудова робота! Зі старанністю та вдачею, ми знайдемо будь-який зв'язок між трогами та цими стародавніми артефактами.\n\nТи {стать:зробив:зробила} велику справу для розвідувачів, {ім'я}. Твої зусилля не будуть забуті. Як і Аґмонд.", ["en"] = "Agmond's Fate", ["tasks"] = { ["Carved Stone Urn"] = "різьблена кам'яна урна", ["Carved Stone Urn (Provided)"] = "різьблена кам'яна урна (видано)" } },
    [7041] = { [1] = "Прокляття Злоязикого", [2] = "Сатир, на ім'я Злоязикий, прокляв печери Мародона, призупинивши ріст більшості рослин.\n\nВізьми цей флакон, {ім'я}. Наповни його з зіпсованого помаранчевого озера в печерах. Покриття всередині флакона буде протидіяти токсинам, перетворюючи його на ліки.\n\nЗнайди у помаранчевих печерах злолози та полий їх цілющою рідиною. Псування покине рослини, але все одно залишиться під контролем Злоязикого. Тож він може використати його проти тебе...", [3] = "Наповніть лазуровий флакон з покриттям в кришталевому помаранчевому озері, що в Мародоні.\n\nПолийте злолозу з наповненого лазурового флакона, щоб вигнати породження Ноксіона.\n\nЗціліть 8 рослин, вбиваючи породження Ноксіона, після чого поверніться до Талендрії в оплот Найджела.", [4] = "Якщо ти зможеш вилікувати рослину, вона знову почне рости. Ми повинні зробити все, що в наших силах, {ім'я}...", [5] = "Дякую, що {стать:приніс:принесла} його, {ім'я}. Я зможу продовжити вивчення цієї рідини завдяки цим залишкам.\n\nХоч і попереду ще багато роботи, ти {стать:допоміг:допомогла} зняти частину прокляття, яке Злоязикий поширював у Мародоні. Прошу, прийми це на знак моєї подяки.", ["en"] = "Vyletongue Corruption", ["tasks"] = { ["Filled Cerulean Vial"] = "наповнений лазуровий флакон", ["Filled Cerulean Vial (Provided)"] = "наповнений лазуровий флакон (видано)", ["Vylestem Vines healed"] = "Вилестемські лози зцілилися", ["Vylestem Vines healed (Provided)"] = "Вилестемські лози зцілилися (видано)", ["Vylestem Vines healed slain"] = "Вилестемські лози зцілилися: убито" } },
    [7044] = { [1] = "Легенди Мародона", [2] = "Темний сатир, на ім'я лорд Злоязикий, сіє жахіття в цих покручених печерах, отруюючи розум усіх, хто опинився всередині. Він все ще живе за фіолетовими кристалами.\n\nКрім того, Злоязикий створив живий символ свого ж псування — Ноксіона, який живе за помаранчевими кристалами. Разом вони викрали дві частини скіпетра мого брата. Мій брат, Келебрас... Бездумно ходить по цих печерах, проклятий псуванням.\n\nДопоможи йому! Знайди частини скіпетра та постарайся якось поговорити з моїм братом...", [3] = "Поверніть дві частини скіпетра Келебраса: жезл Келебраса та діамант Келебраса.\n\nЗнайдіть спосіб поговорити з Келебрасом.", [4] = "Я прокинувся від нескінченного кошмару...", [5] = "Тепер, коли ти {стать:повернув:повернула} обидві частини мого скіпетра, сподіваюся, незабаром ми зможемо позбавити Мародон від псування.", ["en"] = "Legends of Maraudon", ["tasks"] = { ["Celebrian Diamond"] = "діамант Келебраса", ["Celebrian Diamond (Provided)"] = "діамант Келебраса (видано)", ["Celebrian Rod"] = "жезл Келебраса", ["Celebrian Rod (Provided)"] = "жезл Келебраса (видано)" } },
    [7046] = { [1] = "Скіпетр Келебраса", [2] = "Колись мій скіпетр був джерелом надії для мене. Його сила дозволяла мені стрімко пересуватися цими печерами. Я сподівався умиротворити душу мого дядька... Тепер це завдання я передаю тобі.\n\nМені потрібна твоя допомога, щоб провести ритуал для з'єднання двох частини скіпетра. Будь ласка, йди за мною та виконуй мої вказівки, поки я спрямовуватиму енергію для возз'єднання жезла з діамантом.\n\nРазом ми знову створимо скіпетр Келебраса!", [3] = "Допоможіть Келебрасу Спокутому створити скіпетр Келебраса.\n\nПоговоріть з ним після завершення ритуалу.", [4] = "Якщо ти хочеш почати ритуал спочатку, будь ласка, зупини його та поговори зі мною знову.", [5] = "Прошу тебе, прийми це і пам'ятай, що сила, яка міститься в ньому, має використовуватись лише для добрих цілей. Продовжуй вивчати печери і, сподіваюся, ти знайдеш рештки мого дядька. Тобі доведеться здолати багато загроз, {ім'я}.\n\nЗвертайся до мене знову, якщо буде потреба.", ["en"] = "The Scepter of Celebras", ["tasks"] = { ["Create the Scepter of Celebras"] = "Створіть Скіпетр Целебраса" } },
    [705] = { [1] = "Пірнання по перлини", [2] = "Безплідні краї — це суворе місце, наповнене злісними хижаками та зухвалими падальниками. Страшне місце, особливо для маленького гобліна. Щоб вижити, я мушу бути хитрим!\n\nМені відомий рецепт для виготовлення світлових бомб. Я використовую їх, щоб відлякувати диких тварин. Але у мене закінчується один з інгредієнтів: порошок з подрібнених синіх перлин. Добудь мені декілька, і я зроблю так, щоб твої зусилля були не марними.\n\nХа, і сподіваюся, на тобі міцні чоботи. Потрібні мені сині перлини можна знайти у молюсків на Підступному рифі.\n\nТак-так, той самий Підступний риф у Тернистій долині!", [3] = "Принесіть 9 синіх перлин Смиколяпу в Безплідні краї.", [4] = "Ти {стать:дістав:дістала} мої перлини? У мене майже закінчилися світлові бомби!", [5] = "Так, ці чудово підійдуть! Мені лише потрібно змолоти їх на порошок... Потім змішати їх з дрібкою цього і дрібкою того.\n\nНу стережіться, падальники! Приготуйтеся до вибухів!", ["en"] = "Pearl Diving", ["tasks"] = { ["Blue Pearl"] = "синя перлина", ["Blue Pearl (Provided)"] = "синя перлина (видано)" } },
    [706] = { [1] = "Зачарування вогняного спалаху", [2] = "Як учень Феранора Сталепалого, я перейняв від нього його особливу техніку наповнення зброї вогненними чарами. Коли я чув про нього востаннє, Феранор працював у кузні з мисливським загоном в Лордероні.\n\nЯ не можу розповісти тобі подробиці процесу, але можу сказати, що для нього потрібна кров з рідкісного серця чорного драконеняти, яке все ще б'ється. У мене небагато справ, поки я чекаю на звістку з Залізогарта. Якщо принесеш мені серце драконеняти з ущелини Летлор, то я продемонструю тобі свою майстерність!", [3] = "Роздобудьте серце чорного дракончика для Зіґрана Залізотеса.", [4] = "Як там полювання, {клас:к}?", [5] = "О так, воно чудово підійде. Це наділить твою зброю здатністю бити палючим жаром!", ["en"] = "Fiery Blaze Enchantments", ["tasks"] = { ["Black Drake's Heart"] = "серце чорного дракончика", ["Black Drake's Heart (Provided)"] = "серце чорного дракончика (видано)" } },
    [7064] = { [1] = "Понівечення землі та насіння", [2] = "В глибинах Мародона живе зле породження хаосу — принцеса Терадрас — елементаль землі, споріднена зі Старими Богами. Давним-давно між нею та Заєтаром, першим сином Кенарія, зав'язалися стосунки. Результатом їхнього кохання стали істоти, що звуться кентаврами. Вдячні кентаври вбили Заєтара і тепер зберігають його рештки у себе. Мені потрібно знайти того, кому вистачить сил вбити Терадрас і повернути рештки Заєтара в Каміннопазуристі гори.", [3] = "Вбийте принцесу Терадрас та поверніться до Селендри неподалік селища Тінездобич у Спустошищі.", [4] = "Я хотіла б битися в цій битві самотужки, але у нас не залишилося іншого вибору — нам потрібні найсильніші, а раси з Азероту довели, що можуть здолати подібне, коли працюють разом. Тому й ми просимо вас про допомогу.\n\nСподіваюся, цього буде достатньо.\n\nЗаєтар, брат Ремула, приніс багато болю в цей світ, а в результаті це стало причиною його смерті. Я сподіваюсь, що не спричиню ще більше смертей, просячи про допомогу.", [5] = "Це чудова новина, {ім'я}! Дякую тобі!\n\nЯ поговорю з Марандісом та попрошу в нього поради щодо подальшої долі Заєтара, але, принаймні, найскладніша частина завдання виконана.\n\nМені наказали, в разі успіху, нагородити тих, хто нам допомагав. Мені передали ці предмети для винагороди — можеш обрати один з них.", ["en"] = "Corruption of Earth and Seed", ["tasks"] = { ["Princess Theradras"] = "Принцеса Терадрас", ["Princess Theradras (Provided)"] = "Принцеса Терадрас (видано)", ["Princess Theradras slain"] = "Принцеса Терадрас: убито" } },
    [7065] = { [1] = "Понівечення землі та насіння", [2] = "В глибинах Мародона живе породження хаосу і зла, {ім'я}. Принцеса Терадрас — елементаль землі, споріднена зі Старими Богами. Дуже давно її відшукав Заєтар, перший син Кенарія та закохався в неї. Результатом їхнього кохання стали істоти, що звуться кентаврами. Вдячні кентаври вбили Заєтара і тепер Терадрас зберігає його рештки у себе. Мені потрібно знайти того, кому вистачить сил вбити Терадрас і повернути рештки Заєтара в Каміннопазуристі гори.", [3] = "Вбийте принцесу Терадрас та поверніться до хранителя Марандіса в оплот Найджела, що у Спустошищі.", [4] = "Я відчуваю провину за нав'язування своїх прохань смертним расам, але у нас не залишилося іншого вибору. Раси Азероту довели, що можуть здолати подібне, коли працюють разом, тому я й прошу їх допомогти.\n\nСподіваюся, цього буде достатньо.\n\nЗаєтар, брат Ремула, приніс багато болю в цей світ, а в результаті це стало причиною його смерті. Це урок для всіх нас, якщо ми достатньо мудрі, щоб його зрозуміти.", [5] = "Це чудова новина, {ім'я}! Дякую тобі!\n\nЯ занепокоєний тим, що ти не {стать:зміг:змогла} повернути рештки Заєтара... Хоча хто я такий, щоб ставити під сумнів волю первістка Кенарія? Можливо, кентаври зможуть подолати власну кровожерливість — залишається тільки сподіватися на краще.\n\nМені дали ці речі, щоб, в разі успіху, нагородити тих, хто нам допомагав. Ти можеш обрати одну з них на знак нашої подяки.", ["en"] = "Corruption of Earth and Seed", ["tasks"] = { ["Princess Theradras"] = "Принцеса Терадрас", ["Princess Theradras (Provided)"] = "Принцеса Терадрас (видано)", ["Princess Theradras slain"] = "Принцеса Терадрас: убито" } },
    [7066] = { [1] = "Насіння життя", [2] = "Бідні кентаври — мої сини та доньки, вони потребують свого батька.\n\nОзирнися — це місце сповнене надії й того, чого вчив мій батько, Кенарій. І всі вони пішли від мене! Я не можу відвернутись від них... Хоч вони й обернулися проти мене.\n\nМені потрібно заспокоїти свого брата і ти можеш мені в цьому допомогти. Ось, візьми це... Це перше насіння життя, народжене з моїх решток. Скажи йому, що я живий та мій дух перебуває тут. Я впевнений, він зрозуміє.", [3] = "Знайдіть Ремула на Місячній галявині та віддайте йому насіння життя.", [4] = "Від тебе тхне гниллю, {ім'я}... Як і від багатьох шукачів пригод у наш час. Але ти відрізняєшся від інших. Ти {стать:прийшов:прийшла} про щось поговорити зі мною? Я відчуваю щось знайоме, але не можу зрозуміти, що саме.\n\nПрошу тебе, скажи, чому ти {стать:хотів:хотіла} поговорити зі мною?", [5] = "То мій брат нарешті знайшов спокій? Я щасливий, що дожив до цього дня. Зважаючи на всю його гордість та злість, я справді думав, що ми втратили його назавжди, але... цей символ його жертви лише доводить, що він не загинув — він лише переродився. Він виконав обов'язок та зайняв своє місце в природі.\n\nДякую тобі, {ім'я}. Принісши це мені, ти {стать:подарував:подарувала} мені невелику надію, яку, здавалося, я давно втратив. Це насіння колись принесе свої плоди для народу цих зруйнованих війною земель... Я відчуваю це...", ["en"] = "Seed of Life", ["tasks"] = { ["Seed of Life"] = "насіння життя", ["Seed of Life (Provided)"] = "насіння життя (видано)" } },
    [7067] = { [1] = "Вказівки кентавра-парії", [2] = "Хоч мене і вигнали як єретика, моя віра все ще залишаються істинною — це єдине, що спонукає мене рухатись вперед. Але для того, щоб я виконав свій обов'язок, мені потрібна допомога чужинця, не з племені кентаврів.\n\nПотрібно, щоб хтось увійшов до священних залів Мародону — гробниці, що оберігає мій народ, в яку можна заходити лише найпобожнішим.\n\nЯкщо ти {стать:згоден:згодна} допомогти мені, тобі потрібно лише кивнути. Я дам тобі пергамент з моїми вказівками. Прочитай його й обміркуй мої слова.", [3] = "Прочитайте вказівки кентавра-парії. Потім добудьте амулет Єднання в Мародоні та поверніть його кентавру-парії на півдні Спустошища.", [4] = "Що ти {стать:вирішив:вирішила}, {ім'я}? Ти допоможеш мені? Чи ступиш ти на священну землю, щоб допомогти мені створити єдине велике плем'я кентаврів!?", [5] = "Саме так, {раса:к}! Це він! Тепер я можу приступити до великого об'єднання племен. Дякую.\n\nБудь ласка, візьми це за твої старання. Сподіваюся, наступного разу ми зустрінемось за інших обставин.", ["en"] = "The Pariah's Instructions", ["tasks"] = { ["Amulet of Union"] = "амулет Єднання", ["Amulet of Union (Provided)"] = "амулет Єднання (видано)" } },
    [7069] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [709] = { [1] = "Порятунок від загибелі", [2] = "О, небеса милосердні! Лихо! Наближається загибель. Згадай моє слово! Ми приречені!\n\nНі, я не можу більше нічого сказати... я не можу вимовляти їхні імена, вони можуть мене почути! Але якщо ми дізнаємося, так, якщо ми дізнаємося більше про них... тоді, можливо, ми зможемо протистояти їм!\n\nМожливо...\n\nІди в Ульдаман. Ні! Я вимовив це! Ти маєш знайти... знайти скрижаль... Р'юн'еха. Так, знайди її! І не змушуй мене вимовляти це ім'я знову!\n\nВона в глибині Ульдаману, в стародавній скрині, більш стародавній, ніж будь-які досі знайдені сліди дворфів.", [3] = "Принесіть скрижаль Р'юн'еха Тельдуріну Загубленому.", [4] = "Тобі вдалось знайти скрижаль? Вона має містити розгадку нашого спасіння!", [5] = "Ох, доля милосердна до нас! Дякую тобі! Можливо, ми ще зможемо врятуватися!", ["en"] = "Solution to Doom", ["tasks"] = { ["Tablet of Ryun'eh"] = "скрижаль Р'юн'еха", ["Tablet of Ryun'eh (Provided)"] = "скрижаль Р'юн'еха (видано)" } },
    [710] = { [1] = "Вивчення стихій: Камінь", [2] = "Тут, у Безплідних краях, я зупинився, щоб працювати над моїм останнім проєктом: мої кайдани зв'язування стихій.\n\nПісля завершення, вони дозволять магам викликати більш могутніх елементалей у більших кількостях. Щоб почати роботу над ними, мені необхідні маленькі кам'яні осколки, щоб перевірити деякі з моїх останніх атакуючих заклять, а також пару штуковин, що я зібрав докупи.\n\nОсколки можна легко дістати з менших кам'яних елементалей на захід звідси. Можеш принести декілька?", [3] = "Знайдіть 10 маленьких кам'яних осколків і принесіть їх Лотвілю Веріату в Безплідні краї.", [4] = "Це місце ідеальне для-- Тримай їх і не рухайся. Так, саме так, уздовж вектора нормалі. Тепер, про що я... Точно. Ідеальне для тестування мого останнього проєкту. Сировина, відкритий простір... Що ще треба розумному, справжньому професіоналу мистецтв?", [5] = "Ці добре підійдуть, {ім'я}. Дякую. Гмм, трохи більше піску, ніж я передбачав. Доведеться регулювати коефіцієнт тертя. Стоп, зажди. З крижаною олією він має бути незначним.", ["en"] = "Study of the Elements: Rock", ["tasks"] = { ["Small Stone Shard"] = "маленький кам'яний осколок", ["Small Stone Shard (Provided)"] = "маленький кам'яний осколок (видано)" } },
    [711] = { [1] = "Вивчення стихій: Камінь", [2] = "{Ім'я}, ти вже {стать:проявив себе здібнішим:проявила себе здібнішою}, ніж всі мої учні разом узяті.\n\nЩоб добути наступні необхідні мені частини, знадобиться трохи більше сили. Великі кам'яні брили можна знайти у кам'яних елементалів, якщо бути обережним. Їхні тіла більші та міцніші, тож з них можна відколоти шматки, зручні для моїх досліджень. Ти можеш знайти їх далі на захід звідси або на південному сході біля підніжжя гір.\n\nМожеш не поспішати; мені потрібен час, щоб перевірити ці маленькі шматки, які ти {стать:приніс:принесла}.", [3] = "Принесіть 3 великі кам'яні брили Лотвілю Веріату в Безплідні краї.", [4] = "Я дуже задоволений, {ім'я}. Мої закляття впливали на маленькі шматки саме так, як і очікувалося. Якщо цей експеримент вдасться, то елементалі, якими я зможу керувати, перевершать все, що до цього вдавалося викликати.", [5] = "{Ім'я}, це просто дивовижно! Я думав, що знадобиться пів дюжини тауренів, щоб донести мені все це.", ["en"] = "Study of the Elements: Rock", ["tasks"] = { ["Large Stone Slab"] = "велика кам'яна брила", ["Large Stone Slab (Provided)"] = "велика кам'яна брила (видано)" } },
    [712] = { [1] = "Вивчення стихій: Камінь", [2] = "{Ім'я}, є ще одна річ, яка мені потрібна від елементалей Безплідних країв: це поручі зв'язування каменю, які можна дістати з більших кам'яних елементалів. За моїми розрахунками, цих поручів повинно вистачити, щоб оцінити міць моїх власних кайданів.\n\nМої спроби спостереження за більшими кам'яними елементалями показали, що є невелика група на південний захід звідси, поблизу огрів, якщо не помиляюся.\n\nПринеси мені 5 поручів, хай будуть про запас. Серво непогано вміє плутати мої реагенти та результати досліджень.", [3] = "Принесіть 5 поручів зв'язування каменю Лотвілю Веріату в Безплідні краї.", [4] = "Кам'яні брили, які ти {стать:знайшов:знайшла}, були ідеальними, {ім'я}. Люсьєн відвезе зайві назад до Хараноса, коли ми завершимо тут. Зрештою, вони можуть ще знадобитись.\n\nНаприклад, вони були б гарною основою для затишного маленького укриття, коли я почну вивчати високопродуктивні вибухові речовини...", [5] = "{Ім'я}, а ти ніколи не {стать:замислювався:замислювалася} над тим, щоб стати {стать:науковим співробітником:науковою співробітницею}? Ні? Не знаю, що б я робив тут без твоїх здібностей. Інтелект, допитливість і сила — все в одному.", ["en"] = "Study of the Elements: Rock", ["tasks"] = { ["Bracers of Rock Binding"] = "поручі зв'язування каменю", ["Bracers of Rock Binding (Provided)"] = "поручі зв'язування каменю (видано)" } },
    [713] = { [1] = "Холодний розум — запорука успіху", [2] = "Дозволь розповісти тобі про крижану олію: ніщо так не вбереже двигун або шестерні від перегріву, як вона.\n\nЇї охолоджувальні властивості надзвичайні, а довговічність як мастила просто не має рівних. І це ще не все: вона також допомагає зберігати чари на магічних предметах.\n\nМені потрібен флакон цієї олії, щоб підсилити магічний потенціал моїх кайданів і зробити їх достатньо потужними, аби викликаний нами друг не прикінчив нас усіх.\n\nБро'кін, мій друг-гоблін, може навчити тебе, як виготовити цю олію. Він перебуває в Альтераці.", [3] = "Знайдіть крижану олію та принесіть її Лотвілю Веріату в Безплідні краї.", [4] = "Ти вже {стать:знайшов:знайшла} потрібну мені олію? Було б чудово, якби ти {стать:зміг:змогла} знайти хоч трохи.", [5] = "Приголомшливо! Вона послужить прекрасним охолоджувачем для моїх нових наручів. Якщо ці чари впадуть раніше, ніж через сто років, я відпишу все моє майно Серво.\n\nУсі маги Асамблеї будуть в такому захопленні, коли я закінчу цю роботу, {ім'я}. Лише зачекай, і ти побачиш.", ["en"] = "Coolant Heads Prevail", ["tasks"] = { ["Frost Oil"] = "крижана олія", ["Frost Oil (Provided)"] = "крижана олія (видано)" } },
    [714] = { [1] = "Гіро... що?", [2] = "{Ім'я}, ти {стать:впорався:впоралася} зі своїм завданням вище всяких похвал.\n\n<Лотвіль, очевидно, поглинутий своєю роботою.>\n\nЯкщо ми колись зустрінемось у Хараносі, не соромся подати заяву на роботу.\n\nУпс! Швидше, хапай... так, це. Дякую.\n\nТепер мені потрібна лише одна річ. Маленька штуковина, але, боюся, досить необхідна: гірохронатом.\n\nЯкби ти просто {стать:сходив:сходила} та {стать:приніс:принесла} мені один, то в мене буде все готово для завершення.", [3] = "Принесіть гірохронатом Лотвілю Веріату в Безплідні краї.", [4] = "Так, так, так. Секунду.\n\n<Лотвіль продовжує працювати над якимсь хитрим винаходом.>", [5] = "ХА!\n\n<Лотвіль вихоплює у вас гірохронатом.>\n\nВідмінно... майже готово. Ні, справді. Я тут МАЙЖЕ завершив. Це мій найпріоритетніший проєкт... наразі. Дай-но я засуну цю штуку в належне їй місце, і ти {стать:сам:сама} побачиш, зі створенням чого ти мені {стать:допоміг:допомогла}. Це займе лише кілька хвилин... мабуть... може, довше. Гаразд, мабуть, набагато довше. Побачимо...", ["en"] = "Gyro... What?", ["tasks"] = { ["Gyrochronatom"] = "гірохронатом", ["Gyrochronatom (Provided)"] = "гірохронатом (видано)" } },
    [715] = { [1] = "Рідкий камінь", [2] = "Я думаю, що ті речі, які ти {стать:роздобув:роздобула} для Лотвіля, будуть найменшою з наших турбот, {ім'я}. З іншого боку, ти {стать:виявився:виявилася} більш ніж {стать:умілим:умілою} в науках, які Лотвіль вважає священними, тож як щодо допомоги мені?\n\nМені необхідні зілля невидимості та зілля лікування; обидва можуть стати у пригоді дуже скоро, якщо йому це вдасться.\n\nНатомість я дам тобі рецепт зілля, яке я розробив, навчаючись у Лотвіля. Воно засноване на частині досліджень що він проводив тут, у Безплідних краях.", [3] = "Принесіть зілля лікування та зілля малої невидимості Люсьєну Ключожбуру в Безплідні краї.", [4] = "Він майже закінчив. А як твої успіхи?", [5] = "ТАК!\n\nТобто дякую, {ім'я}. Вони мені допоможуть під час подорожі Безплідними краями.", ["en"] = "Liquid Stone", ["tasks"] = { ["Healing Potion"] = "зілля лікування", ["Healing Potion (Provided)"] = "зілля лікування (видано)", ["Lesser Invisibility Potion"] = "зілля малої невидимості", ["Lesser Invisibility Potion (Provided)"] = "зілля малої невидимості (видано)" } },
    [716] = { [1] = "Камінь кращий за тканину", [2] = "Знаю, наскільки жадібним може бути Лотвіль, {ім'я}, тому дозволь мені дати тобі щось за всі твої клопоти. Можливо, це навіть допоможе захистити тебе від нового винаходу Лотвіля.\n\nЯ працював з усіма невикористаними каменями, які ти {стать:збирав:збирала} для нього, і можу зробити досить непогані поручі для тебе. Звісно, я їх зачарую.\n\nМені лише потрібні прикрашені візерунком бронзові поручі, викувані ковалем, і я завершу поручі для тебе.", [3] = "Принесіть візерунчасті бронзові поручі Люсьєну Ключожбуру у Безплідні краї.", [4] = "Я б не чекав занадто довго, щоб отримати ці поручі, {ім'я}.\n\nХто знає, що трапиться далі?", [5] = "Готово, {ім'я}. Приміряй.", ["en"] = "Stone Is Better than Cloth", ["tasks"] = { ["Patterned Bronze Bracers"] = "візерунчасті бронзові поручі", ["Patterned Bronze Bracers (Provided)"] = "візерунчасті бронзові поручі (видано)" } },
    [717] = { [1] = "Тремтіння землі", [2] = "Тепер ми вочевидь не можемо бути впевнені, що Чорнохлист та Гемат будуть залишатися ув'язненими у Летлорі. Те, що там влаштувалися чорні дракони, та те, що ограм вдалося заволодіти знаком Землі, означає, що потрібні куди більш серйозні заходи.\n\nВ'язниця драконів замкнена трьома рунічними каменями, які можна отримати лише за допомогою знака Землі. Ці рунічні камені потрібні, щоб зламати печатку, яка ув'язнює їх.\n\n{Ім'я}... переконайся в тому, щоб дракони упокоїлися навіки.", [3] = "Застосуйте знак Землі, щоб активувати діамантовий, опаловий і аметистовий стовпи, і витягнути рунічні камені.\n\nПомістіть рунні камені на печатку Землі, щоб звільнити драконів Чорнохлиста і Гемата.\n\nУбийте драконів і принесіть Ґареку наручники Чорнохлиста, ланцюги Гемата і знак Землі.", [4] = "Потужна магія тримала в'язницю драконів під замком досить довго, і все ж ми не можемо допустити жодного шансу, щоб Чорнохлист та Гемат вирвалися на свободу.", [5] = "Кірін-Тору більше немає потреби перейматися бранцями Летлора. Я повернуся, щоб відзвітувати про успіх моєму господарю. Крас, безсумнівно, буде задоволений.", ["en"] = "Tremors of the Earth", ["tasks"] = { ["Blacklash's Bindings"] = "наручники Чорнохлиста", ["Blacklash's Bindings (Provided)"] = "наручники Чорнохлиста (видано)", ["Chains of Hematus"] = "ланцюги Гемата", ["Chains of Hematus (Provided)"] = "ланцюги Гемата (видано)", ["Sign of the Earth"] = "знак Землі", ["Sign of the Earth (Provided)"] = "знак Землі (видано)" } },
    [718] = { [1] = "Марева", [2] = "У поспіху залишаючи розкопки Ульдамана ми були вимушені покинути багато візків та ящиків з припасами вздовж шляху. Місцеві огри з табору Кош накинулися на наше спорядження, як стерв'ятники на гнилий труп. Смердять вони теж не краще. За падаль, я маю на увазі.\n\nХай там як, вони взяли візок, у якому була вся наша зброя і тому подібне... Тож — ох, це трохи ніяково — ми не змогли роздобути жодної їжі.\n\nМи тут трохи у скруті, тож, може, ти б {стать:міг:могла} нас виручити?", [3] = "Поверніть ящик з припасами Зіґрану Залізотесу.", [4] = "Мушу я тобі сказати, {стать:друже:подруго}, що пустеля — не найкраще місце, щоб голодувати.\n\nГей... що це там...", [5] = "Величезне дякую, {ім'я}. Поки тебе не було, я... е... поїв трохи піску. Це...\n\nНу, досить про це, ми підемо та здобудемо якусь їжу сьогодні. Будемо бенкетувати, як королі!", ["en"] = "Mirages", ["tasks"] = { ["Supply Crate"] = "ящик з припасами", ["Supply Crate (Provided)"] = "ящик з припасами (видано)" } },
    [7181] = { [1] = "Легенда про Коррака", [2] = "Загарбники Бурешпиля — не єдина загроза, солдате. Війна в долині ведеться на два фронти. Тролі-канібали Зимної Сокири також змагаються за владу.\n\nЇх очолює Коррак Кроволютий — жорстокий і підступний звір.\n\nВбивство Коррака може стати нищівним ударом для клану Зимної Сокири. Вбий його та отримаєш нагороду!", [3] = "За легендою, ватажок могутніх тролів Зимної Сокири з'являється за власним бажанням, щоб сіяти хаос серед мешканців Альтерацької долини.\n\nЯкщо Коррак з'явиться, знищте його і поверніться до отамана Лаґґронда.", ["en"] = "The Legend of Korrak", ["tasks"] = { ["Korrak the Bloodrager"] = "Коррак Кроволютий", ["Korrak the Bloodrager slain"] = "Коррак Кроволютий: убито" } },
    [719] = { [1] = "Дворф і його інструменти", [2] = "Гей, {ім'я}. Бережи сі тутка. Повсюди шастають дворфи Темного Заліза — виглядали, як клан Тінегарту.\n\nВони щойно напали на місце розкопок, де я робив, і, вважай, майже всіх там вирізали, включаючи мого шефа Молотопалого. Я ледь сі душу забрав.\n\nРозкопки — прямо на північ звідси, і я ось прикидаю, як би забрати звідти частину наших припасів, особливо, моє щасливе кайло.\n\nДумаєш, {стать:міг би:могла б} мені троха посприяти? Хтось з того чортового Темного Заліза мусить мати моє кайло! Може бути будь-хто з них.", [3] = "Знайдіть щасливе кайло Житника та поверніть його розвідувачеві Житнику на півдні від розкопок Молотопалого.", [4] = "Не знаю, що тут шукав сі той Тінегарт, але у них точно була якась мета.", [5] = "Ти сі мене {стать:врятував:врятувала}, {клас:к}. Радий, що хтось зміг провчити тих Тінегартців. Вельми дякую за допомогу.", ["en"] = "A Dwarf and His Tools", ["tasks"] = { ["Ryedol's Lucky Pick"] = "щасливе кайло Житника", ["Ryedol's Lucky Pick (Provided)"] = "щасливе кайло Житника (видано)" } },
    [72] = { [1] = "Легенда про Сталвана", [2] = "Мій батько був доглядачем цих земель задовго до мене. Йому й довелося витирати кров після тієї різанини. Але це справи не стосується.\n\nОстанні кошти з фонду Кремнекряжів вичерпалися. Тепер останнє майно сім'ї направляється на аукціон. Винна в усьому скажена податкова. Гадаю, якщо тобі справді кортить дізнатися більше, можеш поритися в цьому мотлоху. Хто знає, що ти зможеш знайти.", [3] = "Пошукайте підказку в зібраних речах.", [5] = "Ви повільно зсуваєте кришку ящика...", ["en"] = "The Legend of Stalvan" },
    [7202] = { [1] = "Коррак Кроволютий", [2] = "Місцеві тролі Зимної Сокири — безжальні дикуни, які тільки й мріють про те, щоб прикрасити свій стіл стравами з м'яса наших солдатів.\n\nМи повинні показати їм нашу силу!\n\nМи знайшли в їхніх печерах фоліанти, в яких детально описана ієрархія їхніх правителів. Вони вказують на те, що їхнього лідера, Коррака Кроволютого, ретельно приховують, а з'явиться він, коли для цього буде потреба.\n\nСмерть Коррака означатиме і смерть клану Зимної Сокири! Вбий його і повертайся.", [3] = "За легендою, ватажок могутніх тролів Зимної Сокири з'являється за власним бажанням, щоб сіяти хаос серед мешканців Альтерацької долини.\n\nЯкщо Коррак з'явиться, знищте його і поверніться до лейтенанта Гаґґердіна в Альтерацькі гори.", ["en"] = "Korrak the Bloodrager", ["tasks"] = { ["Korrak the Bloodrager"] = "Коррак Кроволютий", ["Korrak the Bloodrager slain"] = "Коррак Кроволютий: убито" } },
    [721] = { [1] = "Провісник надії", [2] = "{ім'я}, ти можеш знайти його? Ти можеш відшукати Молотопалого в Ульдамані?\n\nЯкщо ті брудні тінегартці тримають його в заручниках, щоб з'ясувати, що він знає про розкопки титанів, тоді увесь Залізогарт може опинитись у великій біді.\n\nДворфи Темного Заліза вже давно шукають магію для створення ще потужніших големів. Звісно, Молотопалий займався тим самим, але тільки для того, щоб зупинити їх.\n\nЙмовірно вони триматимуть його живим, доки не дізнаються що йому відомо. Якщо ти хочеш врятувати його, тобі варто поквапитись!", [3] = "Знайдіть Молотопалого Ґреза в Ульдамані.", [5] = "Так? Вибач... <кашляє> Я так ослаб. Можеш підійти ближче, {клас:к}?\n\nТебе прислав Житник? Хвала Мурадіну, цей хлопець не таке вже й гальмо, як я думав.", ["en"] = "A Sign of Hope" },
    [722] = { [1] = "Амулет таємниць", [2] = "А ти {стать:хоробрий:хоробра}... <кашляє> ...раз {стать:прийшов:прийшла} в Ульдаман заради мене, {клас:к}.\n\nЯкщо ти справді хочеш допомогти старому Ґрезу, то... <кашляє> ...знайди мій амулет.\n\nВін у Чорноморока. Маґреґана Чорноморока. Він десь тут... в руїнах. Цей амулет приведе їх... <кашляє> ...прямо до сувоїв, якщо його не зупинити. Це у твоїх руках, {ім'я}. Будь ласка... поверни амулет.\n\nЯкщо сувої потраплять до їхніх рук, то Темне Залізо зможе створювати ще могутніших големів. Я знаю це. Я відчуваю це своїм нутром.", [3] = "Знайдіть амулет Молотопалого і поверніть його йому в Ульдаман.", [4] = "Клан Тінегарту... <кашляє> небезпечний. Будь {стать:обережний:обережна}. <кашляє> Ти маєш знайти амулет.", [5] = "Ха! <кхе-кхе>\n\nЯ знав, що ти знайдеш мій амулет, {ім'я}.\n\nМолодець, {ім'я}.", ["en"] = "Amulet of Secrets", ["tasks"] = { ["Hammertoe's Amulet"] = "амулет Молотопалого", ["Hammertoe's Amulet (Provided)"] = "амулет Молотопалого (видано)" } },
    [7221] = { [1] = "Розмова з розвідувачкою Камнетескою", [2] = "А, {ім'я:н}, ти {стать:прибув:прибула} на службу? Чудово, Бурешпилю потрібні всі, кого можливо зібрати!\n\nПоговори з розвідувачкою Камнетескою в Дун-Балдарі. Вона набирає людей для дуже важливого завдання на ворожій території. Ти знайдеш Камнетеску в самому низу гарнізону Дун-Балдару.\n\nІ будь {стать:уважним:уважною}, коли проходитимеш через Дун-Балдар. Тут завжди знайдеться робота для {стать:працьовитого:працьовитої} {клас:р}, {стать:який:яка} не боїться забруднити руки.", [3] = "Поговоріть з розвідувачкою Камнетескою в гарнізоні Дун-Балдару.", ["en"] = "Speak with Prospector Stonehewer" },
    [7222] = { [1] = "Розмова з Воґґою Смертехватом", [2] = "А, {клас}? Чудово! Ми раді бачити тебе в Альтераці, {ім'я:к}. Дворфи та їхні союзники вдерлися в нашу долину, тож Орда вітає кожного, хто приєднається до нас у праведному бою!\n\nПоговори з Воґґою Смертехватом. Він шукає агентів для важливого завдання в фортеці Альянсу, що в Альтерацькій долині!\n\nТи знайдеш Воґґа у форті Морозних Вовків.", [3] = "Поговоріть з Воґґою у форті Морозних Вовків.", ["en"] = "Speak with Voggah Deathgrip" },
    [723] = { [1] = "Іскра надії", [2] = "<Молотопалий стискає свої рани та кілька митей збирає свої сили, перш ніж знову заговорити.>\n\nЗнайди Житника, {ім'я}. Передай йому мій амулет... <кашляє> Він... <кашляє> зрозуміє, що робити. Він знає, що я шукав секрети походження нашого народу, і він... <кашляє>... знає, що моєю місією також було зупинити клан Тінегарту. Їм не можна дозволити знайти сувої... <кашляє>", [3] = "Принесіть амулет Молотопалого розвідувачеві Житнику в Безплідні краї.", [4] = "Я б сказав, що це був поганий день, але це — Безплідні краї: кожен день тут поганий.", [5] = "Амулет Молотопалого? Думаю, у мене був кращий настрій, коли я вважав його мертвим. Тепер біль лише сильніший. Цей амулет був справою його життя. Я не можу дозволити, щоб його смерть буда марною.", ["en"] = "Prospect of Faith", ["tasks"] = { ["Hammertoe's Amulet"] = "амулет Молотопалого", ["Hammertoe's Amulet (Provided)"] = "амулет Молотопалого (видано)" } },
    [724] = { [1] = "Іскра надії", [2] = "Так, так... Хто б знав, що робити?\n\nІсторик Карник! Звісно!\n\nВін у Залізогарті. Він зможе допомогти. Вони разом з Молотопалим працювали над пошуком втрачених артефактів в Ульдамані.\n\nГадаю, Тінегарт дізнався, що ці двоє знають більше, ніж удавали.\n\nРозкажи Карникові, що сталося з Молотопалим, і передай йому амулет — він скаже, що потрібно робити далі.", [3] = "Принесіть амулет Молотопалого історикові Карнику в Залізогарт.", [4] = "А, так. Ще один {стать:подорожній, якому:подорожня, якій} щось потрібно від дворфів.\n\n{Стать:Пане:Пані}, даруйте, але зараз у мене немає часу відповідати на безглузді запитання.", [5] = "О! Так це зовсім інша справа. Мабуть, ви ще не усвідомлюєте всю серйозність цієї справи, чи не так?\n\nМене дуже хвилює загибель Молотопалого, але якщо він послав вас сюди зі своїм амулетом, то він розумів, що стоїть на кону.\n\nМи оплачемо Молотопалого пізніше.\n\nДозвольте мені пояснити вам, чому цей амулет такий цінний.", ["en"] = "Prospect of Faith", ["tasks"] = { ["Hammertoe's Amulet"] = "амулет Молотопалого", ["Hammertoe's Amulet (Provided)"] = "амулет Молотопалого (видано)" } },
    [725] = { [1] = "Звістка про загрозу", [2] = "{Ім'я}, біжіть та якомога швидше знайдіть радника Белґрама. Розкажіть йому про все та запитайте, що нам робити далі. Ця записка має все йому пояснити.\n\nТим часом я поспілкуюся з духом Молотопалого. Можливо, він знає щось, що зможе допомогти нам зупинити цих кретинів з Тінегарту в Безплідних краях. Ми можемо лише молитися.", [3] = "Знайдіть радника Белґрама та віддайте йому записку.", [4] = "Гм-м? Так, {клас:к}.", [5] = "А, звісточка від історика Карника. Чудово.\n\nДля його справ у мене завжди знайдеться хвилинка.\n\n<Радник Белґрам розгортає записку та починає читати.>", ["en"] = "Passing Word of a Threat", ["tasks"] = { ["Sealed Note to Advisor Belgrum"] = "записка для радника Белґрама", ["Sealed Note to Advisor Belgrum (Provided)"] = "записка для радника Белґрама (видано)" } },
    [726] = { [1] = "Звістка про загрозу", [2] = "<Радник Белґрам дочитує записку до кінця, і його очі на мить розширюються.>\n\nОх, це погані новини.\n\n{Ім'я}, будь ласка, повернися до історика Карника та повідом йому від імені короля, щоб він швидко та рішуче зреагував на цю інформацію. Він повинен припинити діяльність Тінегарту в Безплідних краях.", [3] = "Поспілкуйтеся з істориком Карником.", [5] = "Ви дієте у цій справі з поспішністю, яку я б очікував від самого короля, {ім'я}.\n\nГаразд. Я знаю, що зупинить Тінегарт.\n\nЇхні сили в Ульдамані можна послабити, якщо ми завдамо удару по їхній базі операцій: фортеці Анґора.", ["en"] = "Passing Word of a Threat" },
    [727] = { [1] = "У Залізогарт за збірником Яґіна", [2] = "Ця табличка говорить багато про що. І все ж цього недостатньо! І близько недостатньо!\n\nІснує книга, збірник, яку Яґін писав століття тому. Ті... від кого я втік... вони зберігають цю книгу в багатьох місцях. І наймудріші з них вивчають її. Вона містить великі знання. Знання, що здатні захистити нас!\n\nВирушай до Ґерріґа Кісткохвата. Він у магазині в Залізогарті, у Закинутій Печері. Покажи йому цю сигілу, і він прийме тебе за свого. Попроси у нього збірник Яґіна... і принеси його мені!", [3] = "Віддайте сигілу молота Ґерріґу Кісткохвату в Закинуту Печеру, що в Залізогарті.", [4] = "Вітаю. Ласкаво прошу в мою крамницю, але дивись, чого торкаєшся.\n\nЗнання може бути смертельним.", [5] = "О. Вітаю, {стать:брате:сестро}.\n\nІ хвала мешканцям глибин.", ["en"] = "To Ironforge for Yagyin's Digest", ["tasks"] = { ["Sigil of the Hammer"] = "сигіла Молота", ["Sigil of the Hammer (Provided)"] = "сигіла Молота (видано)" } },
    [73] = { [1] = "<TXT> Без винагороди", ["en"] = "<TXT> No Reward" },
    [732] = { [1] = "Тремтіння землі", [2] = "Зіґран сказав, що ти {стать:надав:надала} йому неоціненну допомогу. Можливо, мені вона теж знадобиться. Мене прислав сюди мій господар, Крас з Кірін-Тора, щоб припинити безлади в ущелині Летлор.\n\nЯ не маю права розголошувати деталі моїх завдань, але можеш не сумніватися — вони надзвичайно важливі.\n\nЗграя бродячих огрів, яких іноді бачили біля табору Бофф, викрали один предмет, що зветься знаком Землі. Я маю повернути його. Принеси його мені і я розповім тобі більше.", [3] = "Принесіть знак Землі Ґареку.", [4] = "Зграя бродячих огрів кочує від табору до табору в Безплідних краях; спека, що підіймається від сухої землі та вируючі вітри ускладнюють відстеження їхнього шляху. Я чув, що іноді вони проходять через табір Бофф. Якщо ти {стать:загубився:загубилася}, спробуй пошукати там.", [5] = "Добра звістка, що ти {стать:приніс:принесла} знак, {ім'я}. Знак Землі був створений дворфами Темного Заліза із фортеці Анґора, щоб зв'язати двох безжальних лейтенантів Смертекрила, близнюків Чорнохлиста та Гемата.", ["en"] = "Tremors of the Earth", ["tasks"] = { ["Sign of the Earth"] = "знак Землі", ["Sign of the Earth (Provided)"] = "знак Землі (видано)" } },
    [733] = { [1] = "Виканючування", [2] = "Нам буде важко, якщо я не зможу роздобути матеріали, щоб побудувати укріплення та інші необхідні речі. Я помітив, що огри в цих землях маю багато брухту. Можливо, історії про облогові машини у Безплідних краях не така вже й вигадка...\n\nУ будь-якому разі, розвідувач турбується за стан нашого маленького табору, тож я хотів би взятися за роботу якомога швидше.\n\nГоловний табір огрів розташований у Пилорижному гроті, досить далеко на захід звідси.", [3] = "Принесіть 7 шматків брухту Зіґрану.", [4] = "Ну, я зробив, що міг, але... Цього не багато. Тобі вдалося роздобути більше припасів?", [5] = "Це початок, {ім'я}. Вистачить, поки не отримаємо розпорядження із Залізогарта чи від Ліги дослідників.\n\nТепер, якби я тільки міг знайти трохи солі для моєї загартованої рушниці...", ["en"] = "Scrounging", ["tasks"] = { ["Scrap Metal"] = "брухт", ["Scrap Metal (Provided)"] = "брухт (видано)" } },
    [734] = { [1] = "Це буде важко", [2] = "Чудово, чудово.\n\n<Лотвіль на мить дивиться на вас, перш ніж повернутися до своїх кайданів.>\n\nЗбігай-но до Люсьєна, {ім'я}. Мені потрібен зубець #5. Принеси його мені, добре?", [3] = "Поговоріть з Люсьєном Ключожбуром у Безплідних краях.", [5] = "Зубець #5, еге ж? Так, добром це не скінчиться.", ["en"] = "This Is Going to Be Hard" },
    [7341] = { [1] = "Чесний обмін", [4] = "Вітаю, {раса:к}. Я Коларк, мисливець за головами з Громового Бескиду. Я багато подорожував світом і бачив чимало.\n\nПодорожуючи Південними морями, я роздобув ці чудові стріли з торієвим вістрям. У мене безліч цих стріл, та, на жаль, у мене скінчилися торієві патрони. Жоден таурен, що поважає себе, ніколи не буде користуватися хлипким луком. Стріли мені ні до чого!!\n\nЯ пропоную обмін: я тобі — стріли, а ти мені — таку саму кількість торієвих патронів. Домовилися?", [5] = "Чудово! Я — таурен слова, {раса:к}. Ось твої стріли.", ["en"] = "A Fair Trade", ["tasks"] = { ["Thorium Shells"] = "торієві патрони", ["Thorium Shells (Provided)"] = "торієві патрони (видано)" } },
    [7342] = { [1] = "Стріли — для слабаків", [4] = "Ні, ну ти уявляєш? Вони запороли останню партію боєприпасів з Хараноса! Все, що нам залишається — стріляти цими хлипкими, ні до чого не придатними стрілами! Що мені в біса робити з 500 тисячами стріл з торієвим вістрям?\n\nОсь що, {стать:малий:мала}. Якщо принеси мені торієвих патронів — я виміняю їх на стріли з торієвим вістрям! Згода?", [5] = "Гарний обмін, якщо я щось в цьому тямлю. Стріли — твої.", ["en"] = "Arrows Are For Sissies", ["tasks"] = { ["Thorium Shells"] = "торієві патрони", ["Thorium Shells (Provided)"] = "торієві патрони (видано)" } },
    [735] = { [1] = "Зірка, рука та серце", [2] = "Збірник Яґіна, еге? Ти хочеш зібрати десь ще одну ватагу? Не зважай, не мені питати.\n\nЯ допоможу тобі, бо маю додаткову копію. Ми повинні допомагати один одному, чи не так? Тільки так ми досягнемо успіху.\n\nМені потрібні три предмети сили. Принеси їх мені та отримаєш збірник.\n\nЯ не називаю тобі ці предмети, бо нас можуть підслуховувати. Але ось, я їх записав.", [3] = "Поверніть предмети, перелічені в записці Кісткохвата, Ґерріґу Кісткохвату в Залізогарт.", [4] = "Ти {стать:приніс:принесла} реліквії, про які я просив?", [5] = "Ти {стать:винахідливий:винахідлива}, {клас:к}. Якщо тобі належить честь відкрити новий осередок нашого ордену, то я вірю, що в тебе все вийде.", ["en"] = "The Star, the Hand and the Heart", ["tasks"] = { ["Hand of Dagun"] = "рука Даґуна", ["Hand of Dagun (Provided)"] = "рука Даґуна (видано)", ["Star of Xil'yeh"] = "зірка Ксіл'єх", ["Star of Xil'yeh (Provided)"] = "зірка Ксіл'єх (видано)", ["The Legacy Heart"] = "серце спадку", ["The Legacy Heart (Provided)"] = "серце спадку (видано)" } },
    [736] = { [1] = "Зірка, рука та серце", [2] = "Тобі потрібен збірник Яґіна? Отже, ти хочеш зібрати ще одну ватагу? Звісно, що так... І, звісно, я тобі допоможу, {стать:брате:сестро}.\n\nАле ти також {стать:повинен:повинна} мені допомогти.\n\nМені потрібні три предмети сили. Принеси їх мені та отримаєш збірник.\n\nЯ не можу вимовити назви цих предметів, але запишу їх.\n\nДістань мені речі з цього списку. Якщо зможеш це зробити, тоді ти справді {стать:достойний:достойна} відкрити свій власний осередок нашого ордену.", [3] = "Принесіть предмети, перелічені в записці Бел'дуґура, хранителеві Бел'дуґуру в Підмістя.", [4] = "Як твої успіхи на завданні, {клас:к}?", [5] = "Я вражений! Ти або володієш великою вправністю, або великим фартом, якщо {стать:здобув:здобула} ці реліквії. У будь-якому разі, ти маєш велику цінність для нас.", ["en"] = "The Star, the Hand and the Heart", ["tasks"] = { ["Hand of Dagun"] = "рука Даґуна", ["Hand of Dagun (Provided)"] = "рука Даґуна (видано)", ["Star of Xil'yeh"] = "зірка Ксіл'єх", ["Star of Xil'yeh (Provided)"] = "зірка Ксіл'єх (видано)", ["The Legacy Heart"] = "серце спадку", ["The Legacy Heart (Provided)"] = "серце спадку (видано)" } },
    [7367] = { [1] = "Знешкодження загрози", [2] = "{Клас:к}, по всіх прифронтових територіях та базах Морозних Вовків розкладені пастки. Будь {стать:обережним:обережною} під час вилазки на ворожу територію.\n\nЯкщо ти хочеш завдати потужного удару по них, ти маєш знищити відповідального за ці пастки — я говорю про їхнього експерта з вибухівки. Якщо ти вб'єш його, то зможеш спокійно знешкодити міни. А якщо він буде мертвий, то й не буде кому розставляти ці міни знову.\n\nТи, ймовірно, знайдеш його у вежі біля гарнізону Крижаної Крові. Щасти тобі!", [3] = "Знайдіть експерта з вибухівки Морозних Вовків та вбийте його. Коли виконаєте завдання, поверніться до експерта з вибухівки Бурешпиля.", ["en"] = "Defusing the Threat", ["tasks"] = { ["Frostwolf Explosives Expert"] = "експерт з вибухівки Морозних Вовків", ["Frostwolf Explosives Expert slain"] = "експерт з вибухівки Морозних Вовків: убито" } },
    [7368] = { [1] = "Знешкодження загрози", [2] = "Я знаю все про міни. Зрештою, саме я встановлюю всі міни на лінії фронту.\n\nЯкщо ти хочеш знешкодити мінні поля Бурешпиля, все, що тобі потрібно зробити, це вбити їхнього експерта з вибухівки. Цей боягузливий дворф ховається в першій вежі на полі Чвар. Прибери його і ці міни не буде кому знову розставляти після того, як ми їх знешкодимо.\n\nЯкщо тобі вдасться його вбити, повернись сюди та дай мені знати. Жодна добра справа не повинна залишитися без винагороди.", [3] = "Знайдіть експерта з вибухівки Бурешпиля та вбийте його. Коли виконаєте завдання, поверніться до експерта з вибухівки Морозних Вовків.", ["en"] = "Defusing the Threat", ["tasks"] = { ["Stormpike Explosives Expert"] = "експерт з вибухівки Бурешпиля", ["Stormpike Explosives Expert slain"] = "експерт з вибухівки Бурешпиля: убито" } },
    [737] = { [1] = "Заборонене знання", [2] = "У мене є для тебе збірник, {ім'я}. Думаю, не варто говорити, що з ним потрібно поводитися дуже дбайливо. І неодмінно тримати подалі від ворожих рук.\n\nЦей збірник містить багато правди...\n\n...а правда може обпекти.", [3] = "Принесіть збірник Яґіна Тельдуріну.", [4] = "Гей! Тебе давно не було. {Стать:Дістав:Дістала} збірник?", [5] = "Ти {стать:дістав:дістала} його! О, надія жевріє!\n\nМожливо, твої зусилля ще врятують нас, {ім'я}. Варто поставити тобі пам'ятник! Спорудити святилище! Хай славиться ім'я твоє, доки у твоїх онуків не народяться їхні онуки!\n\nЯкщо тільки... якщо тільки ВОНИ ще не вирвалися та вийшли на поверхню. Якщо це трапиться, то можеш забути про дітей.\n\nЯкщо ВОНИ вирвалися на свободу — ми всі підемо на корм хробакам.", ["en"] = "Forbidden Knowledge", ["tasks"] = { ["Yagyin's Digest"] = "збірник Яґіна", ["Yagyin's Digest (Provided)"] = "збірник Яґіна (видано)" } },
    [741] = { [1] = "Розсіяний розвідувач", [2] = "Тож розвідувач хоче відправити цю таємничу скам'янілість Лізі дослідників у Дарнас? Мені не хотілося б залишати Темнобережжя без нього.\n\nОсь, {ім'я}, достав цю таємничу скам'янілість старшому археологу Сіровусу в Дарнас.", [3] = "Віднесіть таємничу скам'янілість старшому археологу Сіровусу в Дарнас.", [4] = "Чим я можу тобі допомогти, {раса:к}?", [5] = "Йой! Лише розвідувач Сноходень міг зробити таке відкриття!", ["en"] = "The Absent Minded Prospector", ["tasks"] = { ["Mysterious Fossil"] = "таємнича скам'янілість", ["Mysterious Fossil (Provided)"] = "таємнича скам'янілість (видано)" } },
    [7421] = { [1] = "Оборона Темного Списа", [4] = "Вони хочуть нас знищити? Це ми їх знищимо.", [5] = "{ім'я:к}, це лише одна з тисяч. Проте, робота виконана добре.", ["en"] = "Darkspear Defense", ["tasks"] = { ["Severed Night Elf Head"] = "відрубана голова нічного ельфа", ["Severed Night Elf Head (Provided)"] = "відрубана голова нічного ельфа (видано)" } },
    [7422] = { [1] = "Робота для цирульника", [4] = "Мені байдуже, звідки саме ти вирвеш волосся, {раса:к}.", [5] = "Так, це без сумніву гном. Ти добре {стать:попрацював:попрацювала}, {раса:к}, але попереду ще багато роботи.", ["en"] = "Tuft it Out", ["tasks"] = { ["Tuft of Gnome Hair"] = "пучок волосся гнома", ["Tuft of Gnome Hair (Provided)"] = "пучок волосся гнома (видано)" } },
    [7423] = { [1] = "Кістяна лихоманка", [4] = "Так, це правда. Мій брат — людина. Ганебно... Це пляма на моїй майже бездоганній репутації.", [5] = "Було б легше, якби вони просто прийняли свою хворобу і піддалися твоєму цілющому дотику. Хоча, мабуть, це було б не так весело. Не зупиняйся! Так чи інакше, ми їх вилікуємо.", ["en"] = "I've Got A Fever For More Bone Chips", ["tasks"] = { ["Human Bone Chip"] = "уламок людської кістки", ["Human Bone Chip (Provided)"] = "уламок людської кістки (видано)" } },
    [7424] = { [1] = "Які копита?", [4] = "Наваляй їм, {ім'я:к}. Вони повинні зрозуміти, що гноми не потерплять знущань!", [5] = "*Дірк кидає копито на купу позаду нього.*", ["en"] = "What the Hoof?", ["tasks"] = { ["Tauren Hoof"] = "копито таурена", ["Tauren Hoof (Provided)"] = "копито таурена (видано)" } },
    [7425] = { [1] = "Моджо для Оленерога", [4] = "Я все ще відчуваю запах смердючих тролів.", [5] = "Дякую, {ім'я:к}. Завдяки тобі повітря стало трохи чистішим.", ["en"] = "Staghelm's Mojo Jamboree", ["tasks"] = { ["Darkspear Troll Mojo"] = "моджо троля Темного Списа", ["Darkspear Troll Mojo (Provided)"] = "моджо троля Темного Списа (видано)" } },
    [7426] = { [1] = "Любов до ближнього", [4] = "Бенедикт! Я лише маленька цяточка в тіні його величі. Слава йому!", [5] = "Слава Бенедикту! Ще одна загублена душа незабаром буде врятована білим палким полум'ям світла!\n\nВперед, солдате! Ми маємо врятувати їх всіх!", ["en"] = "One Man's Love", ["tasks"] = { ["Forsaken Heart"] = "серце відреченого", ["Forsaken Heart (Provided)"] = "серце відреченого (видано)" } },
    [7427] = { [1] = "Розшукується: БІЛЬШЕ ДВОРФІВ!", [4] = "Я працюю з іронією, солдате.", [5] = "Тепер ти можеш знищувати дворфів десятками, {клас:к}!\n\n<Язра на мить вдивляється в далечінь.>\n\nТи ніколи не забудеш свого першого вбивства...", ["en"] = "Wanted: MORE DWARVES!", ["tasks"] = { ["Dwarf Spine"] = "хребет дворфа", ["Dwarf Spine (Provided)"] = "хребет дворфа (видано)" } },
    [7428] = { [1] = "Розшукується: БІЛЬШЕ ОРКІВ!", [4] = "Тобі потрібні затискачі, щоб виривати зуби?", [5] = "Добре, {ім'я:к}. Ці зуби їм вже не знадобляться.", ["en"] = "Wanted: MORE ORCS!", ["tasks"] = { ["Orc Tooth"] = "зуб орка", ["Orc Tooth (Provided)"] = "зуб орка (видано)" } },
    [7429] = { [1] = "Звільнення Вузла!", [4] = "Він називається ключем від кайданів Ґордока — принаймні, так його називають ці \"жартівники\". Гадаю, він може бути в будь-якого огра, але я не знаю в якого конкретно. Думаю, більше шансів знайти його в охоронців...\n\nТа про що я говорю, ключ вже в тебе, чи не так?! Так?!", [5] = "Дякую, що {стать:звільнив:звільнила} мене! Ти для мене на першому місці. Всі інші — після тебе.\n\nЯ знав, що моя доля стати чимось більшим, аніж закускою для якогось огра!", ["en"] = "Free Knot!", ["tasks"] = { ["Gordok Shackle Key"] = "ключ від кайданів Ґордока", ["Gordok Shackle Key (Provided)"] = "ключ від кайданів Ґордока (видано)" } },
    [7441] = { [1] = "Пузіллін і старійшина Аж'Тордін", [2] = "Уяви собі, {стать:незнайомцю:незнайомко}, я відвернувся лише на мить. Я виривався з рук занепалого принца і в цей момент мене пограбували. Найогидніший демон, біс Пузіллін, викрав мою книгу замовлянь та ключ від колись великих залів Ельдре'Таласу.\n\nКлюч мені більше не потрібен, бо я обміняв своє безсмертя на свободу, а от книга замовлянь мені дуже потрібна.\n\nЗнайди біса Пузілліна й забери мою книгу.\n\nШукай Пузілліна у кварталі Хибнодревів, що в Грізному Молоті.", [3] = "Відправляйтеся в Грізний Молот і знайдіть біса Пузілліна. Будь-якими способами переконайте Пузілліна віддати вам книгу замовлянь Аж'Тордіна.\n\nЯкщо зможете роздобути книгу замовлянь, поверніться до Аж'Тордіна в павільйон Ларісс, що у Фераласі.", [4] = "Я ні про що не шкодую, {стать:незнайомцю:незнайомко}. Королева вже давно померла. Твори Шен'дралар були зіпсовані божевіллям принца Тортельдріна. Мені потрібна лише свобода... Воля...", [5] = "Ти {стать:знайшов:знайшла} її! Нехай буде проклятий цей нікчемний біс. На жаль, мої матеріальні статки не такі великі. Ти можеш вибирати лиш з того, що я маю.", ["en"] = "Pusillin and the Elder Azj'Tordin", ["tasks"] = { ["Book of Incantations"] = "книга замовлянь", ["Book of Incantations (Provided)"] = "книга замовлянь (видано)" } },
    [7461] = { [1] = "Внутрішнє божевілля", [2] = "Ти {стать:почув:почула} достатньо? Сподіваюсь, ти тримаєш своє слово?\n\nЦе божевілля має скінчитися. Епоха безсмертних вже давно минула. Знищ охоронців, що оточують пілони, щоб прибрати силове поле. Коли зробиш це — вбий Безсмер'тера. Коли принц почне втрачати свою силу, атакуй і вбий його також. Умиротвори духів цього міста.", [3] = "Розправтеся з вартовими, які охороняють 5 пілонів, що живлять енергією в'язницю Безсмер'тера. Щойно пілони будуть знеструмлені, захисне поле, що оточує Безсмер'тера, розвіється.\n\nВвійдіть у в'язницю Безсмер'тера та знищте нечистого демона, що знаходиться всередині. Потім розправтеся з принцом Тортельдріном в Атенеумі.\n\nВиконавши це завдання, поверніться у внутрішній двір до старійшини Шен'дралар.", [4] = "Будь {стать:обережним:обережною}. Принц може ввести тебе в оману.", [5] = "Дякуємо тобі, {стать:герою:героїне}.", ["en"] = "The Madness Within", ["tasks"] = { ["Immol'thar"] = "Безсмер'тер", ["Immol'thar slain"] = "Безсмер'тер: убито", ["Prince Tortheldrin"] = "принц Тортельдрін", ["Prince Tortheldrin slain"] = "принц Тортельдрін: убито" } },
    [7462] = { [1] = "Скарб Шен'дралар", [2] = "В Атенеумі, під сходами, захована старовинна скриня — відшукай її. Візьми з неї те, що тобі сподобається.", [3] = "Поверніться в Атенеум і знайдіть скарб Шен'дралар. Отримайте свою нагороду!", [5] = "Ви відкриваєте скриню і знаходите...", ["en"] = "The Treasure of the Shen'dralar" },
    [7463] = { [1] = "Магічний напій", [2] = "А, {раса:н}, що {стать:присвятив:присвятила} своє життя магії! Як же дивовижно. Я не бачив таких, як ти, вже... ой, скільки ж? 500 років!\n\nЯ маю дещо, що втамує твою спрагу, але спочатку ти маєш виконати моє завдання.\n\n<Лідрос хихотить.>\n\nВ Ельдре'Таласі з'явилась аномалія. У східному крилі оселився водяний елементаль. Потрібно його занести в каталог!\n\nВідправляйся у квартал Хибнодревів і роздобудь частину стихійної сутності Гідроподоби. Принеси мені її, а я навчу тебе користуватись одним корисним закляттям.", [3] = "Відправляйтеся у квартал Хибнодревів, що знаходиться в Грізному Молоті та вбийте водяного елементаля — Гідроподобу. Поверніться в Атенеум до хранителя знань Лідроса і віддайте йому сутність Гідроподоби.", [4] = "Так? Ми знайомі?", [5] = "Чудесно! Нагадай, хто ти {стать:такий:така}? Хоча, це не має значення. Що я мав тобі дати? Хм... ну ти ж {клас:н}, можливо, тобі це знадобиться.", ["en"] = "Arcane Refreshment", ["tasks"] = { ["Hydrospawn Essence"] = "сутність Гідроподоби", ["Hydrospawn Essence (Provided)"] = "сутність Гідроподоби (видано)" } },
    [7483] = { [1] = "Манускрипт прудкості", [2] = "Майстер Снохочий втратив манускрипт прудкості у східному крилі. Цей манускрипт дозволить накласти на твоє спорядження невелике замовляння швидкості. Дитяча магія, насправді...\n\nПроте, якщо тобі це цікаво, принеси мені манускрипт та основні реагенти.\n\nХм... Здається, там ще потрібна кров героїв, чистий чорний діамант і великі блискучі осколки. Утім, я можу й помилятися!\n\n<Лідрос знизує плечима.>", [3] = "Віднесіть манускрипт прудкості, 1 чистий чорний діамант, 2 великі блискучі осколки та 2 крові героїв хранителю знань Лідросу в Грізний Молот, щоб отримати магічний камінь прудкості.", [4] = "Що таке? Я маю заповнювати каталог!", [5] = "<Лідрос позіхає.>\n\nЯк я й обіцяв, магічний камінь прудкості. Не витрачай все за один раз.\n\n<Лідрос хихотить.>", ["en"] = "Libram of Rapidity", ["tasks"] = { ["Blood of Heroes"] = "кров героїв", ["Blood of Heroes (Provided)"] = "кров героїв (видано)", ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)", ["Libram of Rapidity"] = "манускрипт прудкості", ["Libram of Rapidity (Provided)"] = "манускрипт прудкості (видано)", ["Pristine Black Diamond"] = "чистий чорний діамант", ["Pristine Black Diamond (Provided)"] = "чистий чорний діамант (видано)" } },
    [7484] = { [1] = "Манускрипт зосередження", [2] = "Цей манускрипт ледь не викликав інтерес в одного з фамільярів хранителя знань. Бідолаха, йому було лише кілька тижнів.\n\nТих, хто більше схильний до магії, може зацікавити цей предмет.\n\nМанускрипт зосередження зник десь в цьому крилі. Я можу лише припустити, що його міг знайти один з духів високородних.\n\nПринеси манускрипт разом з великими блискучими осколками, шкірою тіні та чистим чорним діамантом і я створю магічний камінь.", [3] = "Віднесіть манускрипт зосередження, 1 чистий чорний діамант, 4 великі блискучі осколки та 2 шкіри тіні хранителю знань Лідросу в Грізний Молот, щоб отримати магічний камінь зосередження.", [4] = "Знову ти? Чого тобі ще треба?", [5] = "Дивись не покалічся, коли користуватимешся чарами, {раса:к}.", ["en"] = "Libram of Focus", ["tasks"] = { ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)", ["Libram of Focus"] = "манускрипт зосередження", ["Libram of Focus (Provided)"] = "манускрипт зосередження (видано)", ["Pristine Black Diamond"] = "чистий чорний діамант", ["Pristine Black Diamond (Provided)"] = "чистий чорний діамант (видано)", ["Skin of Shadow"] = "шкіра тіні", ["Skin of Shadow (Provided)"] = "шкіра тіні (видано)" } },
    [7485] = { [1] = "Манускрипт захисту", [2] = "Він плакав, як немовля, коли втратив цей манускрипт. Зауважу, я сам плакав через тексти, бо немає більшої втрати, ніж втрата знань та історії — але плакати за цими безглуздими уривками заклинань? Дурість! Я навіть подумав, що принц робить йому послугу, здираючи плоть з його кісток.\n\nПринеси манускрипт разом з чистим чорним діамантом, великими блискучими осколками та зотлілим стібком потвори і я створю магічний камінь.\n\nО, і перевір північне крило.", [3] = "Віднесіть манускрипт захисту, 1 чистий чорний діамант, 2 великі блискучі осколки та 1 зотлілий стібок потвори хранителю знань Лідросу в Грізний Молот, щоб отримати магічний камінь захисту.", [4] = "Тобі пощастило, що я терплячий.", [5] = "Так, так... Заспокойся. Як і обіцяв, ось твій магічний камінь.", ["en"] = "Libram of Protection", ["tasks"] = { ["Frayed Abomination Stitching"] = "зотлілий стібок потвори", ["Frayed Abomination Stitching (Provided)"] = "зотлілий стібок потвори (видано)", ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)", ["Libram of Protection"] = "манускрипт захисту", ["Libram of Protection (Provided)"] = "манускрипт захисту (видано)", ["Pristine Black Diamond"] = "чистий чорний діамант", ["Pristine Black Diamond (Provided)"] = "чистий чорний діамант (видано)" } },
    [7486] = { [1] = "Нагорода для героя", [2] = "{ім'я}, твої заслуги перед Воєводами перевершили все, що ми могли очікувати від мешканців цього світу.\n\nМи не розуміємо ваших понять про вдячність чи винагороду за добрі справи, але в цьому випадку... можливо, я можу запропонувати нагороду.\n\nПід прибоєм в південній частині цього острова ти знайдеш скриню. В цій скрині твоя... нагорода.\n\nЙди, {ім'я}. Забери свою нагороду.", [3] = "Заберіть свою нагороду зі скрині Гідраксіса.", [5] = "Голос Гідраксіса лунає з поверхні води...\n\n\"Вибери те, що тобі годиться, {ім'я}. Нехай цей скарб захистить тебе від ворогів Водоповелителів\".", ["en"] = "A Hero's Reward" },
    [7487] = { [1] = "Спорідненість з ядром", [2] = "Розломи виникають, рвуться та руйнуються навколо нас, {раса:к}. Навіть за два кроки від того місця, де ти зараз стоїш, є розлом, який веде в надра Чорноскельної гори, до самої пащі Володара вогню.\n\n{стать:Здивований:Здивована}? Шкода... смертні не можуть збагнути того, чого вони не можуть побачити, торкнутися чи відчути.\n\nЗапевняю тебе, ти стоїш просто поруч із порталом і цілком можеш ним скористатися.\n\nБачу, я зацікавив тебе. Споріднення з порталом дуже просте. Вирушай в Чорноскельні надра та добудь фрагмент ядра. Принеси його мені і я зможу споріднити твою сутність з порталом.", [3] = "Відправляйтеся до Палаючого Ядра через портал в Чорноскельних надрах та добудьте фрагмент ядра. Поверніться з фрагментом ядра до Лотоса Побудника Розлому в Чорноскельну гору.", [4] = "Ти маєш споріднити свою душу з Палаючим Ядром, щоб отримати доступ до порталу.", [5] = "Тепер я можу перенести тебе до Палаючого Ядра. Ти лиш скажи коли.", ["en"] = "Attunement to the Core", ["tasks"] = { ["Core Fragment"] = "фрагмент ядра" } },
    [7488] = { [1] = "Тенета Лестендріс", [2] = "Чаклунка Лестендріс, злісна ельфа крові, чия жорстокість може зрівнятися лише з її збоченою пристрастю до магії, втекла в Грізного Молота. Вона створила пристрій, тенета для збору магічної енергії, і ми боїмося, що якщо її не зупинити, вона завдасть серйозної шкоди нашому світу!\n\nЗупини її, {ім'я}. Знайди Лестендріс та відбери в неї тенета. Скоріше за все, вона знаходиться біля сатирів у кварталі Хибнодревів, що в Грізному Молоті. Принеси мені тенета, щоб я випустив цю силу назад у дику природу...", [3] = "Принесіть тенета Лестендріс до Латроніка Місяцесписа в фортецю Перомісяць, що в Фераласі.", [4] = "Ти {стать:приніс:принесла} тенета, {ім'я}? Ми маємо розсіяти їхню сконцентровану магічну енергію!", [5] = "Ти {стать:повернув:повернула} тенета! Молодець, {ім'я}! Лестендріс, як і більшість ельфів її виду, не бачить небезпеку, яку зловживання магією може принести в наш світ. Ці ельфи думають, що вони є володарями магії, не усвідомлюючи, що вони раби своєї власної залежності. Її смерть засмучує мене, але це необхідно було зробити.\n\nДякую тобі, {ім'я}. Я вивільню енергію з тенет, а потім знищу їх, щоб не допустити таких витівок з магією у майбутньому.", ["en"] = "Lethtendris's Web", ["tasks"] = { ["Lethtendris's Web"] = "тенета Лестендріс", ["Lethtendris's Web (Provided)"] = "тенета Лестендріс (видано)" } },
    [7494] = { [1] = "Фортеця Перомісяць", [2] = "{ім'я}! У Фераласі потребують твоєї допомоги!\n\nЛестендріс — чаклунка-вигнанниця, втекла до руїн древнього ельфійського міста Ельдре'Таласа, яке тепер називається Грізний Молот. Ми припускаємо, що вона має при собі небезпечний магічний предмет, який необхідно повернути.\n\nЛатронік Місяцеспис шукає агентів, що проникнуть в Грізний Молот і заберуть у Лестендріс цей предмет.\n\nПослужи Альянсу! Знайди Латроніка у фортеці Перомісяць, що у Фераласі.", [3] = "Поговоріть з Латроніком Місяцесписом у фортеці Перомісяць, що в Фераласі.", [5] = "Вітаю, {ім'я}. Я радий бачити тебе, та шкода, що наша зустріч не відбувається в більш сприятливих умовах.\n\nСлухай уважно, я маю для тебе життєво важливе завдання...", ["en"] = "Feathermoon Stronghold" },
    [7498] = { [1] = "Ґарона: дослідження непомітності та зради", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Чудова робота, {раса:к}. Якщо ти знайдеш ще якісь фоліанти, не соромся повернути їх нам.\n\nМи стаємо кращими з часом і навіть додаємо нові винагороди за повернення зниклих фоліантів.", ["en"] = "Garona: A Study on Stealth and Treachery", ["tasks"] = { ["Garona: A Study on Stealth and Treachery"] = "Ґарона: дослідження непомітності та зради", ["Garona: A Study on Stealth and Treachery (Provided)"] = "Ґарона: дослідження непомітності та зради (видано)" } },
    [7499] = { [1] = "Кодекс захисту", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Чудова робота, {раса:к}. Якщо ти знайдеш ще якісь фоліанти, не соромся повернути їх нам.\n\nМи стаємо кращими з часом і навіть додаємо нові винагороди за повернення зниклих фоліантів.", ["en"] = "Codex of Defense", ["tasks"] = { ["Codex of Defense"] = "Кодекс захисту", ["Codex of Defense (Provided)"] = "Кодекс захисту (видано)" } },
    [75] = { [1] = "Легенда про Сталвана", [2] = "Коли я тільки-но переїхав сюди, в скрині на другому поверсі лежала ціла купа пергаментів. Якось я їх переглядав, але потім зір зіпсувався, і я махнув на них рукою.\n\nЗроби одну послугу майже сліпому старому, пошукай у скрині нагорі що-небудь, що може допомогти тобі дізнатися щось про цього Сталвана. Я впевнений, що там є вицвіла сторінка із щоденника, яка може тебе зацікавити. Принеси її мені, і я допоможу чим зможу.", [3] = "Маршал Знесилій просить вас пошукати вицвілу сторінку щоденника в скрині нагорі.", [4] = "Ти {стать:знайшов:знайшла} ту сторінку, про яку казав, {ім'я:к}?", [5] = "Ти {стать:знайшов:знайшла} її!", ["en"] = "The Legend of Stalvan", ["tasks"] = { ["A Faded Journal Page"] = "вицвіла сторінка щоденника", ["A Faded Journal Page (Provided)"] = "вицвіла сторінка щоденника (видано)" } },
    [7500] = { [1] = "Кулінарна книга арканіста", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Чудова робота, {раса:к}. Якщо ти знайдеш ще якісь фоліанти, не соромся повернути їх нам.\n\nМи стаємо кращими з часом і навіть додаємо нові винагороди за повернення зниклих фоліантів.", ["en"] = "The Arcanist's Cookbook", ["tasks"] = { ["The Arcanist's Cookbook"] = "Кулінарна книга арканіста", ["The Arcanist's Cookbook (Provided)"] = "Кулінарна книга арканіста (видано)" } },
    [7501] = { [1] = "Світло і як ним керувати", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Чудова робота, {раса:к}. Якщо ти знайдеш ще якісь фоліанти, не соромся повернути їх нам.\n\nМи стаємо кращими з часом і навіть додаємо нові винагороди за повернення зниклих фоліантів.", ["en"] = "The Light and How To Swing It", ["tasks"] = { ["The Light and How to Swing It"] = "Світло і як ним керувати", ["The Light and How to Swing It (Provided)"] = "Світло і як ним керувати (видано)" } },
    [7502] = { [1] = "Приборкання тіней", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Чудова робота, {раса:к}. Якщо ти знайдеш ще якісь фоліанти, не соромся повернути їх нам.\n\nМи стаємо кращими з часом і навіть додаємо нові винагороди за повернення зниклих фоліантів.", ["en"] = "Harnessing Shadows", ["tasks"] = { ["Harnessing Shadows"] = "Приборкання тіней", ["Harnessing Shadows (Provided)"] = "Приборкання тіней (видано)" } },
    [7503] = { [1] = "Найвеличніші змагання мисливців", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Чудова робота, {раса:к}. Якщо ти знайдеш ще якісь фоліанти, не соромся повернути їх нам.\n\nМи стаємо кращими з часом і навіть додаємо нові винагороди за повернення зниклих фоліантів.", ["en"] = "The Greatest Race of Hunters", ["tasks"] = { ["The Greatest Race of Hunters"] = "Найвеличніші змагання мисливців", ["The Greatest Race of Hunters (Provided)"] = "Найвеличніші змагання мисливців (видано)" } },
    [7504] = { [1] = "Святе лицемірство: про що мовчить світло", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Чудова робота, {раса:к}. Якщо ти знайдеш ще якісь фоліанти, не соромся повернути їх нам.\n\nМи стаємо кращими з часом і навіть додаємо нові винагороди за повернення зниклих фоліантів.", ["en"] = "Holy Bologna: What the Light Won't Tell You", ["tasks"] = { ["Holy Bologna: What the Light Won't Tell You"] = "Святе лицемірство: про що мовчить світло", ["Holy Bologna: What the Light Won't Tell You (Provided)"] = "Святе лицемірство: про що мовчить світло (видано)" } },
    [7505] = { [1] = "Крижаний шок і ви", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Чудова робота, {раса:к}. Якщо ти знайдеш ще якісь фоліанти, не соромся повернути їх нам.\n\nМи стаємо кращими з часом і навіть додаємо нові винагороди за повернення зниклих фоліантів.", ["en"] = "Frost Shock and You", ["tasks"] = { ["Frost Shock and You"] = "Крижаний шок і ви", ["Frost Shock and You (Provided)"] = "Крижаний шок і ви (видано)" } },
    [7506] = { [1] = "Смарагдовий Сон...", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Чудова робота, {раса:к}. Якщо ти знайдеш ще якісь фоліанти, не соромся повернути їх нам.\n\nМи стаємо кращими з часом і навіть додаємо нові винагороди за повернення зниклих фоліантів.", ["en"] = "The Emerald Dream...", ["tasks"] = { ["The Emerald Dream"] = "Смарагдовий Сон", ["The Emerald Dream (Provided)"] = "Смарагдовий Сон (видано)" } },
    [7507] = { [1] = "Довідник Ностро", [2] = "Ви знайшли дещо дуже важливе. Ця книга не схожа на жодну з тих, що ви бачили.\n\nЗдається, ніби хтось або щось змогло знищити печатку Атенеума. Текст всередині спотворений і ледве розбірливий для читання.", [3] = "Поверніть \"Довідник Ностро по винищенню драконів\" в Атенеум.", [4] = "А, одна з наших найкращих збірок. Вона була втрачена багато років тому.", [5] = "Ти {стать:міг би:могла б} отримати чимало золота за цю книгу на чорному ринку, {ім'я}. Тим паче захисна печатка зламана і секрети винищення драконів доступні кожному, кому вистачить розуму, щоб заволодіти знаннями, що містяться на цих священних сторінках.\n\nМожливо, ти заслуговуєш за це великої винагороди... Нагороди, для отримання якої потрібно прикласти чимало зусиль.", ["en"] = "Nostro's Compendium", ["tasks"] = { ["Foror's Compendium of Dragon Slaying"] = "Форорівський компендіум вбивства драконів", ["Foror's Compendium of Dragon Slaying (Provided)"] = "Форорівський компендіум вбивства драконів (видано)", ["Foror's Compendium of Dragon Slaying slain"] = "Форорівський компендіум вбивства драконів: убито" } },
    [7508] = { [1] = "Кування Квел'Серрара", [2] = "Якщо ти хочеш взяти на себе це завдання, подаруй Лідросу тупий клинок.", [3] = "Віддайте тупий і плаский ельфійський клинок хранителю знань Лідросу.", [4] = "Чудово, почнімо...", [5] = "Якщо тобі вдасться проникнути в лігво дракона, нагрій клинок під його вогняним диханням і загартуй в його власній крові. А я пов'яжу клинок з тобою, щоб ти {стать:міг:могла} вічно користуватися ним.", ["en"] = "The Forging of Quel'Serrar", ["tasks"] = { ["A Dull and Flat Elven Blade"] = "тупий і плаский ельфійський клинок", ["A Dull and Flat Elven Blade (Provided)"] = "тупий і плаский ельфійський клинок (видано)" } },
    [7509] = { [1] = "Кування Квел'Серрара", [2] = "Віднеси цей клинок до лігва Оніксії та вступи з нею в бій.\n\nЩоб нагріти клинок, слід застосувати деякі хитрощі. Під час бою вона неодмінно спробує спопелити тебе своїм вогняним подихом. Ти {стать:повинен:повинна} підставити клинок під вогонь і сподіватися, що подих нагріє його. Якщо ти виживеш після цього, схопи нагрітий клинок та добий драконицю.\n\nВстроми його в її тліюче тіло, щоб отримати загартований древній клинок.", [3] = "Змусьте Оніксію дихнути своїм вогняним вогнем на неопалений древній клинок. Після цього підніміть нагрітий древній клинок. Майте на увазі, що клинок лишається нагрітим ненадовго, не гайте час.\n\nОстаннім кроком буде вбивство звіра, після чого встроміть нагрітий древній клинок в її труп.\n\nЗробіть це — і Квел'Серрар буде вашим.", [4] = "Можливо, одного дня клинком володітиме інший.", [5] = "<Лідрос бурмоче щось незрозуміле.>\n\nЯк і обіцяв, {клас:к} — клинок Квел'Серрар.", ["en"] = "The Forging of Quel'Serrar", ["tasks"] = { ["Treated Ancient Blade"] = "загартований древній клинок", ["Treated Ancient Blade (Provided)"] = "загартований древній клинок (видано)" } },
    [7521] = { [1] = "Громаан Шукач Вітру", [2] = "Я розповів тобі все, що знаю, {ім'я}. Саме ти маєш знайти елементій. Саме ти маєш знищити тілесну форму Володара Вогню.\n\nЯкщо ти зробиш це, то отримаєш благословення Громаана.", [3] = "Щоб звільнити Громаана Шукача Вітру з його в'язниці, ви маєте віднести праву та ліву половини кайданів Шукача Вітру, 10 злитків елементію та сутність Володара Вогню верховному повелителю Демітріану.", [4] = "Постав цей світ на коліна, якщо доведеться!", [5] = "Навіть уві сні я не смів передбачити цей день.\n\nУзри, {стать:смертний:смертна}.\n\nУЗРИ ТОГО, ХТО СТАРШИЙ ЗА БУТТЯ!\n\nУЗРИ ТОГО, ХТО БИВСЯ З ТИТАНАМИ ТА БОГАМИ!\n\nПОВСТАНЬ, МІЙ ПОВЕЛИТЕЛЮ! ЗВІЛЬНИСЯ ВІД ВЛАСНИХ КАЙДАНІВ!", ["en"] = "Thunderaan the Windseeker" },
    [7562] = { [1] = "Мор'зул Кровопивця", [2] = "{ім'я}, твої пізнання темних мистецтв глибокі. Твоя майстерність у володінні істотами з інших світів стала настільки сильною... Можливо, ти {стать:готовий:готова} зв'язати з собою одного з жахожеребців.\n\nВикликати його в наш світ нелегко, це вимагає великої сили та ресурсів, але якщо ти бажаєш підкорити цього епічного коня, то звернись до Мор'зула Кровопивці. Він став табором біля Олтаря Бур в Палаючому степі.\n\nЙди, {ім'я}. Це завдання буде небезпечним, але чорнокнижники твого рівня не бояться небезпек!", [3] = "Поговоріть з Мор'зулом Кровопивцею в Палаючому степі.", [5] = "Вітаю, {ім'я}, і ласкаво прошу. Ти тут, щоб вчитися біля Олтаря Бурі, як і я, та, можливо, щоб використати його енергію для якихось таємних цілей...\n\nАбо... ти тут, щоб поговорити зі мною? Так, я гадаю, що саме так.\n\nТи хочеш опанувати жахожеребця? Це зовсім не проста справа. Це вимагає від тебе не мало крові, поту... і, звичайно ж, золота. Але Зоротський жахожеребець — це приз, вартий зусиль. Тому, якщо тобі цікаво, слухай далі...", ["en"] = "Mor'zul Bloodbringer" },
    [7563] = { [1] = "Кривава лють", [2] = "Жахожеребці мешкають в іншому світі, на палаючих рівнинах Зороту, і щоб підкорити одного з цих знаменитих звірів, необхідні могутні гліфи. Я можу накреслити ці гліфи на пергаменті, але для цього мені знадобиться особливе чорнило.\n\nУ далекому Зимоключі живе раса совоподібних істот. Колись ці істоти були чистими, але демонічний вплив ущелини Темного шепоту позбавив їх розуму, і вони блукають снігами в повному божевіллі.\n\nЇх кров потрібна мені для створення чорнила. Принеси її мені.", [3] = "Принесіть 30 пляшок крові лютого звіра Мор'зулу Кровопивці в Палаючий степ.", [4] = "Ти {стать:бачив:бачила} лютих совозвірів, {ім'я}? Магія цих створінь дуже потужна і концентрується в крові, що тече через їхні понівечені тіла.", [5] = "Ах, дуже добре. Я перегоню цю кров на чорнило і використаю його для пергаменту, який я тобі обіцяв. І, можливо, залишу трохи для себе, бо я чув, що у неї незвичайний смак...", ["en"] = "Rage of Blood", ["tasks"] = { ["Raging Beast's Blood"] = "кров лютого звіра", ["Raging Beast's Blood (Provided)"] = "кров лютого звіра (видано)" } },
    [7564] = { [1] = "Дикоокий", [2] = "Мій слуга, Ґорзікі, досить вмілий алхімік. Він може приготувати чорнило, яке мені знадобиться для твого пергаменту. Я вже підготував принесену тобою кров. Віднеси її Ґорзікі, щоб він міг почати свою роботу.", [3] = "Принесіть скриньку крові до Ґорзікі Дикоокого в Палаючий степ.", [4] = "У тебе є щось для мене? Це ж не великий, соковитий павук? Чи, може, тарган? Сподіваюся, він ще живий... Я так люблю їх жувати, коли вони ще живі...", [5] = "А, це кров. Мабуть, вона від майстра Мор'зула. Він так захоплюється нею і любить, коли вона проливається. А мені більше подобається, коли вона тече в жилах маленького гризуна. Так вона залишається теплою... до вживання.\n\nЦе потужна кров. Мор'зул, мабуть, збирається створити ще один пергамент для виклику жахожеребця! Як цікаво!\n\nЯкщо це правда, і ти збираєшся провести ритуал, то.. тобі знадобиться набагато більше, ніж кров, {стать:друже:подруго}.", ["en"] = "Wildeyes", ["tasks"] = { ["Case of Blood"] = "скриня з кров'ю", ["Case of Blood (Provided)"] = "скриня з кров'ю (видано)" } },
    [758] = { [1] = "Очищення Громового Рога", [2] = "Тотем готовий, {Ім'я}. І знову, твоє завдання - провести ритуал очищення.\n\nЙди до колодязя Громового Рога на північ від селища та використай очисний тотем Громового Рога у своєму ритуалі. Після того, як закінчиш, повертайся до мене.\n\nНехай тебе ведуть духи.", [3] = "Використайте очисний тотем Громового Рога біля колодязя Громового Рога, після чого поверніться до Мулла.", [4] = "Вода колодязя Громового Рога досі заражена, {Ім'я}. Будь ласка, ти мусиш провести ритуал!", [5] = "Духи клану Громового Рога говорили зі мною уві сні, вихваляючи тебе за твій вчинок для їхнього колодязя.\n\nЯк знак їхньої вдячності, вони хочуть дати тобі це...", ["en"] = "Thunderhorn Cleansing", ["tasks"] = { ["Cleanse the Thunderhorn Water Well"] = "Очистіть водяну криницю Громового рога" } },
    [7581] = { [1] = "Тюремні кайдани", [2] = "Тобі потрібно дістати кайдани для вартового приречення у менших демонів.\n\nКров диких сатирів, що живуть в Грsзному Молоті, повинна підійти. Згорнута кров з'єднає уламки Гедеріни та дасть силу кришталевій в'язниці.", [3] = "Вирушайте до Грізного Молота у Фераласі та зберіть 15 зразків крові шаленородних сатирів, що мешкають у кварталі Хибнодревів. Зробивши це, поверніться до Дайо в Проклятий Рубець.", [4] = "Підійде лише кров сатирів племені Шаленородних.", [5] = "Чудовий результат. Кров приглушить магічний захист вартового приречення.", ["en"] = "The Prison's Bindings", ["tasks"] = { ["Satyr Blood"] = "кров сатира", ["Satyr Blood (Provided)"] = "кров сатира (видано)" } },
    [7582] = { [1] = "Тюремна камера", [2] = "Демони Гедеріни, які поселились на схилах гори Гіджал, виділяють потужну отруту скверни, яка, якщо залишити її на довгий час, затвердіє, перетворюючись на щільний антимагічний кристал. Ці кристали отримали назву \"сльози Гедеріни\".\n\nНавіть неймовірна сила вартового приречення не зможе зруйнувати стіну в'язниці, збудованої з цього матеріалу.\n\nВирушай в ущелину Темного шепоту у Зимоключ та збери сльози Гедеріни.", [3] = "Вирушайте в ущелину Темного шепоту в Зимоключі та зберіть 5 сліз Гедеріни у демонів Гедеріни, які знаходяться в ущелині. Поверніться до Дайо в Проклятий Рубець, коли закінчите це завдання.", [4] = "Демони Гедеріни не віддадуть свої дорогоцінні камені без бою, {ім'я}.", [5] = "Мені лише потрібно поєднати кров Шаленородних з цими кристалами, і в'язниця буде готова до використання.", ["en"] = "The Prison's Casing", ["tasks"] = { ["Tears of the Hederine"] = "сльози Гедеріни", ["Tears of the Hederine (Provided)"] = "сльози Гедеріни (видано)" } },
    [7583] = { [1] = "Ув'язнення", [2] = "В'язниця готова. Тепер лишилась найважча частина завдання.\n\nТобі потрібно знайти та захопити командира вартових приречення в Проклятому Рубці, використовуючи цю кришталеву в'язницю.\n\nБудь {стать:обережний:обережна}! Вартовий приречення — це хитрий і смертельний суперник, який намагатиметься знищити тебе, коли ти почнеш ритуал ув'язнення. Він буде дико битися, намагаючись втекти від ув'язнення.\n\nВін зосередиться тільки на тобі, {ім'я}. Тому я раджу взяти з собою компаньйонів, здатних зберегти тобі життя!", [3] = "Вирушайте в Проклятий Рубець і знайдіть командира вартових приречення.\n\nВикористайте сяючий кристал ув'язнення на командирі вартових приречення. Будьте готові до відчайдушного опору, оскільки демон намагатиметься уникнути ув'язнення.\n\nЯкщо вам вдасться — поверніть ув'язненого вартового приречення до Дайо в Проклятий Рубець.", [4] = "Хм? Ну?", [5] = "Ти {стать:зробив:зробила} все так, як я просив. Ти {стать:готовий:готова} отримати знання про те, як викликати чудовиськ та контролювати їх.", ["en"] = "Suppression", ["tasks"] = { ["Glowing Crystal Prison"] = "сяючий кристал ув'язнення", ["Glowing Crystal Prison (Provided)"] = "сяючий кристал ув'язнення (видано)", ["Imprisoned Doomguard"] = "ув'язнений вартовий приречення", ["Imprisoned Doomguard (Provided)"] = "ув'язнений вартовий приречення (видано)" } },
    [760] = { [1] = "Очищення Дикої Гриви", [2] = "Про твоє очищення колодязів Зимового Копита та Громового Рога говорять духи, {стать:юний:юна} {Ім'я}. Тотем Дикої Гриви готовий, і твоє останнє завдання лежить попереду.\n\nКолодязь Дикої Гриви розташований на північ від Громового Бескиду. Проведи ритуал! Вилікуй землю від гоблінської отрути! Нехай знову ллється чиста вода!", [3] = "Використайте очисний тотем Дикої Гриви біля колодязя Дикої Гриви, після чого поверніться до Мулла Громового Рогу.", [4] = "Останній водяний коллодязь залишається сморідним і отруйним, {Ім'я}. Не барися!", [5] = "Ти {стать:впорався:впоралася}, ти {стать:очистив:очистила} колодязі та {стать:вилікував:вилікувала} наші землі. Селище Криваве Копито вдячне тобі, {Ім'я}.\n\nНехай вітер шепоче про твої вчинки сотні пір року, а води Мулґору залишаються чистими назавжди.", ["en"] = "Wildmane Cleansing", ["tasks"] = { ["Cleanse the Wildmane Well"] = "Очистіть криницю Дикої Гриви" } },
    [7601] = { [1] = "Як Нібі скаже", [2] = "Якщо хочеш навчитися в мене викликати пекельника-слугу, ти маєш знищити Крошія і добути з його палаючих останків ядро пекельника. Однак це не так просто, як здається. Крошій майже повністю згорів. Тобі доведеться знову розпалити його тіло та підняти його з попелу. Однак, для цього тобі доведеться добути деякі компоненти з інших демонічних сутностей.\n\nМій біс, на ім'я Бісик, допоможе тобі.", [3] = "Поговоріть з Бісиком в Скверноліссі.", [5] = "Йой, знову те саме...", ["en"] = "What Niby Commands" },
    [7602] = { [1] = "Бездоганна есенція скверни", [2] = "Якщо ти збираєшся відродити Крошія, тобі знадобиться вогонь скверни. Я можу розпалити вогонь скверни, але для цього мені потрібні деякі компоненти.\n\nТобі потрібно принести мені бездоганні есенції скверни з трьох різних місць.\n\nПершу есенцію можна отримати у сатирів Леґаші з Азшари, другу — в легіонерів Джеденару, а третю — у вартових скверни зі Спустошених земель.\n\nДістань у них по одній есенції, принеси мені і я розпалю вогонь скверни, що дозволить тобі відродити Крошія.", [3] = "Бісик зі Сквернолісся попросив вас принести йому три бездоганні есенції скверни з трьох різних місць.\n\nСатири Леґаші з Азшари мають першу бездоганну есенцію скверни. Легіонери Джеденару мають другу бездоганну есенцію скверни. Вартові скверни зі Спустошених земель мають третю бездоганну есенцію скверни.\n\nЗберіть всі бездоганні есенції скверни та поверніться до Бісика в Сквернолісся.", [4] = "Нікому не кажи, але Нібі — дурень.", [5] = "Дай мені хвилину, і я об'єднаю есенції у вогонь скверни.", ["en"] = "Flawless Fel Essence", ["tasks"] = { ["Flawless Fel Essence (Azshara)"] = "бездоганна есенція скверни (Азшара)", ["Flawless Fel Essence (Azshara) (Provided)"] = "бездоганна есенція скверни (Азшара) (видано)", ["Flawless Fel Essence (Dark Portal)"] = "бездоганна есенція скверни (Темний Портал)", ["Flawless Fel Essence (Dark Portal) (Provided)"] = "бездоганна есенція скверни (Темний Портал) (видано)", ["Flawless Fel Essence (Jaedenar)"] = "бездоганна есенція скверни (Джеденар)", ["Flawless Fel Essence (Jaedenar) (Provided)"] = "бездоганна есенція скверни (Джеденар) (видано)" } },
    [7603] = { [1] = "Ядро Крошія", [2] = "Крошій лежить у купі на північному сході, в долині Шматованих порубів. Візьми цей вогонь скверни та підпали залишки. Вогонь повинен оживити загиблого пекельника.\n\nНа цьому етапі, я впевнений, що він вб'є тебе та будь-яких друзів, яких ти, можливо, візьмеш з собою — а повір мені, тобі захочеться взяти з собою друзів.\n\nЯкщо якимось дивом тобі вдасться вбити Крошія, візьми його ядро пекельника та поверни його Нібі.", [3] = "Шукайте рештки Крошія в долині Шматованих порубів у Скверноліссі. Коли знайдете його залишки, скористайтеся вогнем скверни поряд з ним та очікуйте на повернення Крошія. Коли пекельник відродиться з попелу, знищте його та візьміть з його тіла ядро пекельника.\n\nПоверніть ядро Крошія Нібі Всемогутньому в Сквернолісся.", [4] = "Ти {стать:заблукав:заблукала}?", [5] = "Угода є угода! Швидко, візьми це та записуй. У мене немає часу! Моє найбільше творіння йде на нас!", ["en"] = "Kroshius' Infernal Core", ["tasks"] = { ["Kroshius"] = "Крошій", ["Kroshius slain"] = "Крошій: убито", ["Kroshius' Infernal Core"] = "ядро Крошія", ["Kroshius' Infernal Core (Provided)"] = "ядро Крошія (видано)" } },
    [7604] = { [1] = "Укладання договору", [2] = "{стать:Той:Та}, хто нижче {стать:підписався:підписалася}, заявляє, що злиток сульфурону, який {стать:він передав:вона передала} Торієвому братству (ТОВ \"ТБ\"), є справжнім, а не його факсимільною копією. {стать:Той:Та}, хто нижче {стать:підписався:підписалася}, також визнає, що ТОВ \"ТБ\" не несе відповідальність за будь-яку шкоду, яка може бути нанесена {стать:йому:їй}, як покарання за спробу побудувати, підробити, знайти, створити, продати або з'їсти Сульфурас.\n\nПідписуючи цей контракт, ви погоджуєтеся з усіма умовами, перерахованими в документі.\n\n_________________\n\nПідпис", [3] = "Укладіть договір з представником Торієвого братства, Локтосом Темнокрамом, якщо хочете отримати креслення сульфуронового молота.", [4] = "Ми домовились?", [5] = "Було приємно працювати з тобою, {ім'я}!\n\nВід імені ТОВ \"ТБ\" бажаю успіхів у пошуках Сульфураса!", ["en"] = "A Binding Contract", ["tasks"] = { ["Sulfuron Ingot"] = "злиток сульфурону", ["Sulfuron Ingot (Provided)"] = "злиток сульфурону (видано)", ["Thorium Brotherhood Contract"] = "договір Торієвого братства", ["Thorium Brotherhood Contract (Provided)"] = "договір Торієвого братства (видано)" } },
    [762] = { [1] = "Посол зла", [2] = "Посла Інферна прислав до фортеці Анґора сам Раґнарос, щоб наглядати за пошуками Тінегартом втрачених артефактів в Ульдамані.\n\nЦе вже означало великі жертви для наших людей, але, очевидно, все стало гірше. Я навіть боюся припустити, скільки артефактів вони зможуть знайти та використати проти Залізогарта.\n\nНаше завдання просте, {клас:к}. Повертайтеся до Безплідних країв і знищте посла Інферна. Як тільки загроза буде усунена, повертайтесь до радника Белґрама з доказом перемоги.\n\nТепер все у ваших руках.", [3] = "Убийте посла Інферна в фортеці Анґора і принесіть доказ його смерті радникові Белґраму в Залізогарт.", [4] = "Час — безцінний, {ім'я}. Раґнарос не чекатиме, поки ми підготуємося.", [5] = "{Ім'я}, твоя відданість Залізогарту та народові дворфів беззаперечна. Я дякую тобі за допомогу.\n\nЯ зв'яжуся з істориком Карником і повідомлю про твої успіхи, а також якомога швидше пошлю поміч до Безплідних країв, що допомогти відновити місце розкопок. Ще раз дякую тобі.\n\nПерш ніж ти підеш, у мене до тебе є ще одне прохання від імені короля Бронзобородого.", ["en"] = "An Ambassador of Evil", ["tasks"] = { ["Ambassador Infernus' Bracer"] = "браслет посла Інферна", ["Ambassador Infernus' Bracer (Provided)"] = "браслет посла Інферна (видано)" } },
    [7621] = { [1] = "Попередження", [5] = "{Клас:к}, на тебе чекають суворі випробування, що перевірять твої здібності.\n\nЯ пропоную тобі послухати, що я розповім.\n\nБудь напоготові, ти {стать:повинен:повинна} виконати це завдання самостійно. Нехай твої союзники відійдуть на безпечну відстань і не втручаються. Будь-яке втручання може спричинити найсуворішу кару.\n\nДоля привела тебе, ти тут {стать:один:одна}. Бийся з честю. Використовуй Світло.", ["en"] = "A Warning" },
    [7622] = { [1] = "Баланс Світла й Тіні", [2] = "Ти мусиш зробити те, чого я не змогла: врятувати селян, що загинули під час втечі зі Стратгольму.\n\nВони йтимуть до світла і ти маєш захистити їх. Якщо занадто багато з них загине — наше прокляте існування продовжиться.\n\nЦе справжнє випробування для всіх твоїх здібностей. Нехай Світло захистить тебе, {ім'я}.", [3] = "Врятуйте 50 селян перш ніж 15 з них загинуть. Поговоріть з Еридою Мирожарою коли виконаєте завдання.\n\nКількість вбитих селян можна дізнатися з пошти смерті.", [5] = "Твоя стійкість та хоробрість вражають, {ім'я}. Ти {стать:заслужив:заслужила} право володіти уламком Нордрассіля. Тобі залишилось лише знайти Око Тіні. Знайди його, навіть якщо тобі доведеться обшукати весь світ.", ["en"] = "The Balance of Light and Shadow", ["tasks"] = { ["The Balance of Light and Shadow"] = "Баланс світла і тіні" } },
    [7623] = { [1] = "Лорд Пустоклят", [2] = "Мор'зул каже, що ти хочеш відкрити портал до Зорота. Для цього тобі знадобиться зоротський зоряний пил. Його нелегко знайти в Азероті!\n\nЄ одна істота, яка може мати його: лорд Пустоклят в Джеденарі, резиденції ради Тіні! Поговори з ним, раптом він поділиться з тобою зоряним пилом.\n\nАле якщо ти збираєшся до Джеденару, тобі потрібно буде пройти {стать:непоміченим:непоміченою} радою Тіні. Для цього знадобляться мої тіньові зілля, а вони недешеві...", [3] = "Купіть тіньове зілля у Ґорзікі в Палаючому степі.\n\nВикористайте зілля, щоб пройти через Джеденар та поговоріть з лордом Пустоклятом.", [5] = "Моя терплячість охоплює тисячоліття, {клас:к}. Але не думай, що я приділю тобі більше, ніж мить мого часу...", ["en"] = "Lord Banehollow" },
    [7624] = { [1] = "Зрадник Улатек", [2] = "Хочеш заслужити мою милість? Тоді вбий для мене.\n\nМій слуга Улатек жалюгідно повзає переді мною, і в той самий час замислює зраду проти мене разом із лордом Хел'нуратом із Зорота. Хел'нурат планує скинути мене та узурпувати мою владу тут, а Улатек — його шпигун.\n\nДоведи, що ти служиш саме мені, а не моїм суперникам. Знайди Улатека в його покоях в оплоті Тіні на заході. Скажи йому, що я знаю його таємницю і побачиш, як його охопить страх. А потім принеси мені серце зрадника!", [3] = "Вбийте Улатека, а потім принесіть серце зрадника лорду Пустокляту в Джеденар.", [4] = "Я вже відчуваю смак серця Улатека на своїх губах. Така солодка плоть зрадника...", [5] = "Ах, як чудово! Після тижневого гниття це серце стане соковитим делікатесом! Можливо, я пошлю за головою Улатека і поставлю її перед собою, коли буду їсти...\n\nТи {стать:зробив:зробила} мені послугу, {клас:к}, і тому моє до тебе терпіння зросло. Трохи.", ["en"] = "Ulathek the Traitor", ["tasks"] = { ["The Traitor's Heart"] = "серце зрадника", ["The Traitor's Heart (Provided)"] = "серце зрадника (видано)" } },
    [7625] = { [1] = "Зоротський зоряний пил", [2] = "Тож ти {стать:прийшов:прийшла} до мене в пошуках зоротського зоряного пилу? Ти бажаєш відкрити портал до Зороту, володінь, що належить моєму супернику Хел'нурату? Можливо, ти плануєш викрасти у нього одного з його дорогоцінних жахожеребців?\n\nДобре. Мій слуга Ур'дан має запас зоротського зіркового пилу. Ти можеш отримати його від нього... якщо зможеш заплатити.", [3] = "Придбайте зоротський зоряний пил в Ур'дана. Віднесіть його до Ґорзікі Дикоокого в Палаючий степ.", [4] = "Ти {стать:був:була} у Джеденарі, {ім'я}? Ти {стать:отримав:отримала} зоряний пил від лорда Пустоклята?", [5] = "Ось він! Мені не віриться, що ти його {стать:дістав:дістала}! Мабуть, ти {стать:уклав:уклала} велику угоду з повелителем жаху або {стать:заплатив:заплатила} величезну суму, або те й інше!\n\nМор'зул скоро отримає чорнило і зробить тобі пергамент з рунами. А ти відкриєш портал у Зорот і викрадеш одного зі знаменитих жахожеребців!", ["en"] = "Xorothian Stardust", ["tasks"] = { ["Xorothian Stardust"] = "зоротський зоряний пил", ["Xorothian Stardust (Provided)"] = "зоротський зоряний пил (видано)" } },
    [7626] = { [1] = "Дзвін Детмури", [2] = "Дзвін Детмури, названий на честь покійної чорнокнижниці Детмури Темноокої, є одним з трьох предметів, необхідних для створення кола великого виклику. Коли вони правильно налаштовані з колесом та свічкою, ці предмети вміщують великі обсяги арканічної магії.\n\nМій слуга Ґорзікі може зробити такий дзвін, але для цього йому потрібна велика кількість еліксирів сили тіней. Добудь еліксири в алхіміка та принеси їх Ґорзікі.", [3] = "Принесіть 10 еліксірів сили тіней до Ґорзікі в Палаючий степ.", [4] = "Ти {стать:приніс:принесла} еліксири, {ім'я}? Мор'зул сказав мені, що тобі потрібен дзвін Детмури, а для його створення потрібно багато еліксирів!", [5] = "Дуже добре! Сподіваюся, що отримати ці еліксири було не надто складно. Іноді алхіміки можуть бути такими скупими на свої творіння...\n\nЯ зроблю дзвін та зберігатиму його, доки ти не будеш {стать:готовий:готова} до ритуалу.", ["en"] = "Bell of Dethmoora", ["tasks"] = { ["Elixir of Shadow Power"] = "еліксир сили тіні", ["Elixir of Shadow Power (Provided)"] = "еліксир сили тіні (видано)" } },
    [7627] = { [1] = "Колесо Чорного Походу", [2] = "Колесо Чорного Походу містить та направляє жорстоку енергію, необхідну для кола великого виклику. Щоб Ґорзікі зміг побудувати колесо, йому потрібні великі блискучі осколки, які можна знайти у чародіїв та руда темного заліза, яку можна купити у шахтаря-майстра.\n\nЗнайди ці компоненти та принеси їх моєму прислужнику.", [3] = "Принесіть 6 великих блискучих осколків та 25 шматків руди темного заліза до Ґорзікі в Палаючий степ.", [4] = "Колесо Чорного Походу не так легко зробити та воно потребує багато матеріалів. Ти вже {стать:зібрав:зібрала} їх?", [5] = "Отже, ось і вони! Я чув, що руда темного заліза знаходиться тільки у глибинах Чорнокамінної гори, і я впевнений, що ці осколки також було не легко знайти. Я часто дивуюся самовідданості чорнокнижників. Якби ви спрямували всю цю енергію, щоб ловити жуків, о... який би бенкет ви влаштували!\n\nВибач, відступив від теми. Я зроблю колесо і зберігатиму, доки ти не будеш {стать:готовий:готова} провести ритуал.", ["en"] = "Wheel of the Black March", ["tasks"] = { ["Dark Iron Ore"] = "руда темного заліза", ["Dark Iron Ore (Provided)"] = "руда темного заліза (видано)", ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)" } },
    [7628] = { [1] = "Свічка Судного дня", [2] = "Свічка Судного дня зберігає в собі вогонь, який обпалює всіх, хто хоче перервати твій ритуал. Під час створення кола великого виклику, якщо твоя свічка запалена, будь-які свавільні демони будуть спалені її полум'ям!\n\nСтримувати цей вогонь не так легко, і для цього потрібна есенція з лусок чорного дракона. Придбай ці луски у шкуродерів та принеси їх Ґорзікі Дикоокому.", [3] = "Принесіть 35 лусок чорного дракона до Ґорзікі Дикоокого в Палаючий степ.", [4] = "Ти {стать:приніс:принесла} луски чорних драконів, {ім'я}? Я не хочу починати роботу над свічкою, поки у мене їх немає... інакше я можу підірвати весь табір!", [5] = "А, дуже добре. Мені знадобляться ці луски, щоб контролювати вогонь свічки. Тепер я зроблю свічку і зберігатиму її доки ти не будеш {стать:готовий:готова} до ритуалу кола великого виклику.", ["en"] = "Doomsday Candle", ["tasks"] = { ["Black Dragonscale"] = "луска чорного дракона", ["Black Dragonscale (Provided)"] = "луска чорного дракона (видано)" } },
    [7629] = { [1] = "Доставка біса", [2] = "Є ще один процес, необхідний для пергаменту Мор'зула; мені потрібен папір, наповнений зоротським зоряним пилом. І... Боюся, я не зможу зробити його тут. У мене немає потрібного обладнання!\n\nАле є алхімічна лабораторія, де є все необхідне. Це в Некроситеті, на острові Тверджа Дарроу в Зачумлених землях.\n\nЯ не можу туди поїхати, але ось — візьми цю банку. У ній сидить дуже розумний біс. Випусти його в алхімічній лабораторії, і він наповнить пергамент.", [3] = "Принесіть біса в банці в алхімічну лабораторію Некроситету. Після того, як пергамент буде створено, поверніть банку Ґорзікі Дикоокому.", [4] = "Ти вже {стать:був:була} в Некроситеті, {ім'я}? Біс вже наповнив пергамент зоряним пилом?", [5] = "Ах, добре. Дж'іві створив пергамент. Тобі сподобалося в Некроситеті? Чарівно, не так? А комахи там... я чув, що вони дуже смачні!\n\nГарна робота, {ім'я}, і дякую за повернення моєї банки. Вона в мене вже довгий час... і вона не для продажу!", ["en"] = "Imp Delivery", ["tasks"] = { ["Imp in a Jar"] = "біс у банці", ["Imp in a Jar (Provided)"] = "біс у банці (видано)", ["Parchment Created"] = "Пергамент створено", ["Parchment Created (Provided)"] = "Пергамент створено (видано)", ["Parchment Created slain"] = "Пергамент створено: убито" } },
    [7630] = { [1] = "Арканіт", [2] = "Тепер, коли дзвін, колесо та свічка готові, я повинен зробити чорний магніт. Він знадобиться тобі, щоб підтримувати інші об'єкти ритуалу, якщо щось піде не так.\n\nДля виготовлення магніту, мені потрібен арканіт. У тебе його немає? Якщо ні, то... тоді тобі доведеться пошукати його в алхіміка.\n\nПовертайся до мене, коли матимеш арканіт, і я зможу створити чорний магніт.", [3] = "Принесіть 3 злитки арканіту до Ґорзікі в Палаючий степ.", [4] = "Ти {стать:приніс:принесла} арканіт, {ім'я}? Як тільки я отримаю його, я зможу зробити для тебе чорний магніт.", [5] = "Ти {стать:приніс:принесла} його! Гарна робота! Тепер я можу створити магніт. Коли ти нарешті будеш {стать:готовий:готова} до ритуалу створення кола великого виклику, тобі знадобиться чорний магніт, щоб бути {стать:впевненим:впевненою}, що ритуал не перерветься!", ["en"] = "Arcanite", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)" } },
    [7631] = { [1] = "Зоротський жахожеребець", [2] = "Усе готово. Тепер ти маєш провести ритуал для створення кола великого виклику, а потім використати пергамент, насичений зоротським зоряним пилом, щоб відкрити портал до Зороту.\n\nЯ записав інструкції для ритуалу на сувої. Вивчи його уважно, адже ти маєш чітко виконати кожен крок, якщо хочеш досягти успіху.\n\nЩасти тобі, {ім'я}. І нехай душі твоїх ворогів якнайшвидше потраплять у твій мішечок з уламками душ.", [3] = "Прочитайте вказівки Мор'зула. Викличте зоротського жахожеребця, переможіть його, а потім прив'яжіть його дух до себе.", [5] = "Дух зоротського жахожеребця зламаний. Попри те, що гнів б'ється в ньому, ви знаєте, що душа цього звіра належить вам...\n\nВін нашіптує темні слова та дарує знання про те, як викликати жахожеребця.", ["en"] = "Dreadsteed of Xoroth", ["tasks"] = { ["Xorothian Dreadsteed"] = "зоротський жахожеребець", ["Xorothian Dreadsteed slain"] = "зоротський жахожеребець: убито" } },
    [7632] = { [1] = "Древній листок", [2] = "Листок випромінює яскраво-зелене світіння. Його поверхня надзвичайно зморщена, на ній видно кілька борозен і оголених прожилок.\n\nСхоже, що він належав комусь древньому і могутньому.\n\nМожливо, вам варто знайти власника цього листка?", [3] = "Знайдіть власника древнього скам'янілого листка. Нехай щастить, {ім'я:к}, це великий світ.", [4] = "<Вартрій стогне.>", [5] = "Звісно я впізнаю свій листок. Тільки-но поглянь! Він в чудовому стані.\n\nЦе дуже благородно, {клас:к}.\n\nМожливо, ти міг би добре послужити нам, а ми — тобі.", ["en"] = "The Ancient Leaf", ["tasks"] = { ["Ancient Petrified Leaf"] = "древній скам'янілий листок", ["Ancient Petrified Leaf (Provided)"] = "древній скам'янілий листок (видано)" } },
    [7633] = { [1] = "Знайомство", [5] = "Твоя старанність та чесність не будуть забуті, {клас:к}.\n\nМи — древні, хранителі цього, колись величного, лісу. Наші фізичні тіла були знищені 10 000 літ тому, коли Архімонд і Палаючий Легіон пройшли Гіджалом. Однак, наші душі залишились неушкодженими.\n\nУ нас є завдання для тебе. Завдання, які відкриють тобі таємниці древніх.\n\nТож знай, якщо ти виконаєш ці завдання — просто повернись до цієї скелі, і ми відповімо на поклик.", ["en"] = "An Introduction" },
    [7634] = { [1] = "Перетягнутий жилою лист древнього", [2] = "Вітаю, {клас:к}. Я Гастат, древній знань. Я оберігаю знання, втрачені з давніх-давен.\n\nЗ вірною перев'яззю, один з моїх листків може служити як сагайдак, подібного якому уже не бачили у світі 10 000 років. Сагайдак, який разом з луком древніх, може надати тобі несказанну могутність.\n\nПовернись до мене з сухожиллям дорослого синього дракона і цей сагайдак буде твоїм.", [3] = "Гастат Древній попросив вас принести йому сухожилля дорослого синього дракона. Коли знайдете таке сухожилля — принесіть його Гастату в Сквернолісся.", [4] = "З поверненням, {стать:юний:юна} {клас:к}.", [5] = "Нехай мої листки убезпечать твої стріли від ушкоджень. Нехай твої стріли б'ють влучно. Нехай вороги нашого світу будуть розбиті.", ["en"] = "Ancient Sinew Wrapped Lamina", ["tasks"] = { ["Mature Blue Dragon Sinew"] = "сухожилля дорослого синього дракона", ["Mature Blue Dragon Sinew (Provided)"] = "сухожилля дорослого синього дракона (видано)" } },
    [7635] = { [1] = "Гідна тятива", [2] = "Вартрій може запропонувати тобі руків'я для створення лука Древніх, однак лише я можу зачарувати тятиву, щоб його завершити.\n\nЦе просте завдання, легесеньке. Вбий дорослого чорного дракона і відділи сухожилля від його кісток. Повернись з цим сухожиллям до мене і я накладу чари на нього так, що тятива з нього стане практично вічною.", [3] = "Стома Древній попросив вас принести йому сухожилля дорослого чорного дракона. Коли знайдете таке сухожилля — принесіть його Стомі у Сквернолісся.", [4] = "Я впевнений, що у тебе не виникне труднощів з тим, щоб знайти та убити чорного дракона, {ім'я:к}. Не марнуй мого часу марною балаканиною.", [5] = "Цей дракон був найбільш нечестивим. Сухожилля смердить злом.\n\nДай мені хвилю, щоб очистити мерзоту цієї плоті та накласти належні чари.", ["en"] = "A Proper String", ["tasks"] = { ["Mature Black Dragon Sinew"] = "сухожилля дорослого чорного дракона", ["Mature Black Dragon Sinew (Provided)"] = "сухожилля дорослого чорного дракона (видано)" } },
    [7636] = { [1] = "Руків'я древніх", [2] = "Слуги Палаючого Легіону все ще роблять свої темні справи в нашому світі, {клас:к}. Вони спотворюють все, до чого торкаються. Сама природа в'яне і стогне в їх присутності.\n\nТи маєш вистежити цих демонічних потвор і знищити їх, {ім'я:к}. Та попереджаю — ти маєш самостійно впоратись з ними, інакше вони втечуть. Поки ти наодинці, вони намагатимуться знищити тебе. Ти маєш вбити їх, обернувши їх самовпевненість проти них самих.\n\nЯ дарую тобі шматок моєї кори. Написи на ній допоможуть тобі знайти цих демонів. Принеси їх голови.", [3] = "Ви маєте знайти й знешкодити чотирьох демонічних розносників порчі:\n\nСимону Спокусницю.\n\nКлінфрана Схибленого.\n\nСоленора Душогуба.\n\nАрторія Губителя.\n\nЗнищіть цих створінь і поверніться з їх головами до Вартрія Древнього в Сквернолісся.\n\nПідказки по їх місцеперебуванню шукайте в скам'янілій корі, що у вас в рюкзаку.\n\nВи маєте виконати це завдання САМОСТІЙНО.", [4] = "Не дай їх маскуванню обманути тебе!", [5] = "Ти гарно {стать:послужив:послужила} нам, {ім'я:к}! Візьми це руків'я та об'єднай з тятивою, яку ти можеш отримати у Стоми. Разом вони утворять могутню зброю.", ["en"] = "Stave of the Ancients", ["tasks"] = { ["Artorius's Head"] = "голова Арторія", ["Artorius's Head (Provided)"] = "голова Арторія (видано)", ["Klinfran's Head"] = "голова Клінфрана", ["Klinfran's Head (Provided)"] = "голова Клінфрана (видано)", ["Simone's Head"] = "голова Симони", ["Simone's Head (Provided)"] = "голова Симони (видано)", ["Solenor's Head"] = "голова Соленора", ["Solenor's Head (Provided)"] = "голова Соленора (видано)" } },
    [7637] = { [1] = "В першу чергу — жертовність", [2] = "Щоб приготуватись до цього завдання, ти маєш проявити належну жертовність та готовність до правосуддя... В першу чергу — жертовність.\n\nДля цього маєш отримати кадильницю екзорцизму у верховного жерця Рогана. Хоч вона й буде використовуватись з благородною метою, за неї належить віддати гідну компенсацію.\n\nПрямуй до Залізогарту і поговори з верховним жерцем. Принесеш достатньо монет за його кадильницю — покажеш свою готовність до жертви.\n\nЙди, {ім'я:к}, не гай часу.", [3] = "Прямуйте до Залізогарту та отримайте кадильницю екзорцизму у верховного жреця Рогана. Вам доведеться внести пожертву в 150 золотих, щоб отримати її.", [4] = "Вітаю, {стать:благородний:благородна} {клас:к}! Я вже підготував кадильницю для тебе: наповнив найсвіжішим ладаном та тричі благословив. Твоя пожертва допоможе нам не тільки створити нову кадильницю, а й знайти більше їжі для нужденних Залізогарту.", [5] = "Благослови тебе Світло, {стать:любий:люба} {клас:к}! Твоя пожертва покриє всі наші потреби. Ми не тільки відновимо нашу втрату, а й допоможемо тим, хто найбільше цього потребує.\n\nА тепер дозволь мені перевірити, що кадильниця готова для твоїх потреб...", ["en"] = "Emphasis on Sacrifice", ["tasks"] = { ["Required money: 150"] = "Необхідна сума: 150" } },
    [7639] = { [1] = "Готовність до правосуддя", [2] = "Візьми цю кадильницю і прийми моє благословення. Я використовував її в кількох обрядах екзорцизму і вона гарно тобі послужить в майбутніх випробуваннях.\n\nТепер повертайся до лорда Сивенка Тінелома в Штормовій, {ім'я:к}. Він направить тебе далі.", [3] = "Принесіть кадильницю екзорцизму лорду Сивенку Тінелому в соборний район Штормовію.", [4] = "З поверненням, {ім'я:к}! Ти {стать:отримав:отримала} кадильницю?", [5] = "Так, це вона. Тобі доведеться ще не раз проявляти свою готовність до жертв під час цього завдання. І я радий бачити твою готовність до цього. Жертовність — ключова чеснота {клас:р}. Та я, певно, можу тобі про це не розказувати.\n\nА тепер, {ім'я:к}, тобі доведеться проявити правосуддя у своїх діяннях. А ця кадильниця послужить тобі інструментом правосуддя над замученими духами наших земель.", ["en"] = "To Show Due Judgment", ["tasks"] = { ["Rohan's Exorcism Censer"] = "кадильниця екзорцизму Рогана", ["Rohan's Exorcism Censer (Provided)"] = "кадильниця екзорцизму Рогана (видано)" } },
    [7640] = { [1] = "Екзорцизм Страходолу", [2] = "Я додав до кадильниці щіпку забрудненої землі Страходолу, що в Східних Зачумлених землях. Ти маєш використати цю кадильницю, щоб знайти місця, які несуть ознаки активності неспокійних духів. Шукай зелене світіння, що є ознакою прояву активності потойбічних сил в нашому світі, і використай кадильницю для виклику духів.\n\nТи будеш {стать:готовий:готова} продовжити, коли проведеш вдосталь правосуддя над духами.", [3] = "Використайте кадильницю екзорцизму для виклику духів, що мучать Страходіл. Вбийте 25 духів Страходолу і повертайтесь до лорда Сивенка Тінелома в соборний район Штормовію.", [4] = "Радий тебе знову бачити, {ім'я:к}. Ти {стать:виконав:виконала} завдання у Страходолі?", [5] = "Чудово, {ім'я:к}. Здійснення правосуддя Світлом над тими, хто живе в темряві — задача, над якою ми маємо працювати із завзяттям. Ти {стать:проявив:проявила} свою жертовність в Залізогарті та правосуддя над духами в Страходолі.\n\nТвоє наступне завдання знову потребуватиме від тебе жертовність і правосуддя, адже тобі доведеться повернути дух бойового коня, що зараз служить лицарю смерті, на ім'я Тінегубитель.", ["en"] = "Exorcising Terrordale", ["tasks"] = { ["Exorcism Censer"] = "кадильниця екзорцизму", ["Exorcism Censer (Provided)"] = "кадильниця екзорцизму (видано)", ["Terrordale Spirit"] = "дух Страходолу", ["Terrordale Spirit slain"] = "дух Страходолу: убито" } },
    [7641] = { [1] = "Робота Ґріманда Елмора", [2] = "Бойовий кінь паладина нічого не вартий без відповідного барду. Бард для твого коня не тільки має бути виготовлений з найкращих матеріалів, а й, враховуючи обставини, він має бути достатньо пов'язаний зі світом духів.\n\nАле все по черзі, {ім'я:к}, — почнемо з виготовлення барду. В дворфійському районі Штормовію живе один з найкращих сучасних майстрів — Ґріманд Елмор. За роботу він бере не мало, але вона того варта. Поговори з ним.", [3] = "Поговоріть з Ґрімандом Елмором у дворфійському районі Штормовію.", [5] = "Вітаю, {стать:юначе:юнко}, лорд Тінелом попередив мене, що ти прийдеш. Я з радістю займусь бардом, та це буде не легко, та й не дешево. Я про це кажу тобі відверто.\n\nАле повір мені, і Сивенко не дасть мені збрехати, кращого барду ти не знайдеш у всьому Азероті.", ["en"] = "The Work of Grimand Elmore" },
    [7642] = { [1] = "Збір необхідного", [2] = "Для барда тобі знадобиться чотири компоненти: рунічне полотно для підкладки, злитки арканіту для покриття, сльози Артаса для зв'язку з потойбіччям та свята вода Стратхольму для укріплення цього зв'язку. Насправді п'ять... якщо рахувати оплату моєї роботи. Ця плата — за сідло і стремена ручної роботи та за мою працю.\n\nЯк збереш все необхідне — я зроблю твій бард. А поки є кілька речей, якими я займусь, поки ти збираєш все необхідне.", [3] = "Принесіть 40 відрізів рунічного полотна, 6 злитків арканіту, 10 сліз Артаса, 5 флаконів зі святою водою Стратхольму та 150 золотих Ґріманду Елмору у дворфійський район Штормовію.", [4] = "О, {ім'я:н}. Я не зможу завершити бард без компонентів, про які я казав. Тобі вдалось все зібрати?", [5] = "Це... так, це те, що мені потрібно. Ти досить {стать:винахідливий:винахідлива} {клас}, чи не так?\n\nДобренько, пора завершити твій бард!", ["en"] = "Collection of Goods", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Arthas' Tears"] = "сльози Артаса", ["Arthas' Tears (Provided)"] = "сльози Артаса (видано)", ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)", ["Stratholme Holy Water"] = "стратгольмська свята вода", ["Stratholme Holy Water (Provided)"] = "стратгольмська свята вода (видано)" } },
    [7643] = { [1] = "Древній дух коня", [2] = "Твій бард потребує особливого благословіння, яке ти можеш отримати у відповідного духа. Такий дух живе у Грізному Молоті, це древній дух коня. Зараз його утримує Тендріс Хибнодрев. Проведи правосуддя над чим чудовиськом, {ім'я:к}.\n\nТа знай — однієї тільки свободи буде недостатньо. Щоб отримати благословення, ти маєш заспокоїти духа. Для цього тобі знадобиться спеціальний корм для коней. Тому спочатку прямуй до Південнобережжя і поговори з Мерідет Карлсон... і приготуйся до жертви.", [3] = "Придбайте корм для коней у Мерідет Карлсон в Південнобережжі.\n\nПрямуйте в Фералас до підземель Грізного Молота та вбийте Тендріса Хибнодрева. Це звільнить древнього духа коня. Нагодуйте його кормом, щоб заспокоїти, після чого попросіть його благословити арканітовий бард.", [4] = "Древній дух коня уважно дивиться на вас, очікуючи на щось.", [5] = "Древній дух коня приймає від вас збагачений маною корм для коней. Попоївши, він підставляє свою спину під бард...", ["en"] = "Ancient Equine Spirit", ["tasks"] = { ["Arcanite Barding"] = "арканітовий бард", ["Arcanite Barding (Provided)"] = "арканітовий бард (видано)", ["Manna-Enriched Horse Feed"] = "збагачений маною корм для коней", ["Manna-Enriched Horse Feed (Provided)"] = "збагачений маною корм для коней (видано)" } },
    [7644] = { [1] = "Благословенний арканітовий бард", [2] = "Опинившись на спині древнього духа коня, бард почав ледь помітно світитись. Повітря на мить важчає від сили, що переповнює його, після чого бард зникає зі спини духа коня та опиняється у вашому рюкзаку.\n\nСхоже, що на барді тепер лежить благословення. Тепер, як казав лорд Тінелом, ви маєте повернутись до нього в Штормовій.", [3] = "Проверніться з благословенним арканітовим бардом до лорда Сивенка Тінелома на соборну площу Штормовія.", [4] = "{ім'я:к}, ти {стать:повернувся:повернулась}! Ну як, {стать:впорався:впоралась} з Мерідет Карлсон та Тендрісом Хибнодревом? Чесно кажучи, навіть не знаю, хто з них небезпечніше...", [5] = "Тобі довелось чимало попрацювати, {стать:брате:сестро}. Твій бард готовий до останньої справи.\n\nВін знадобиться тобі, коли ти будеш сідлати свого бойового коня. Та спершу, тобі належить проявити себе у боротьбі проти зла та провести ритуал спокути. Твій час настав!\n\nТа спершу ти маєш зробити ще одну річ, {ім'я:к}. Сподіваюсь, ти ще не {стать:втратив:втратила} свого завзяття?", ["en"] = "Blessed Arcanite Barding", ["tasks"] = { ["Blessed Arcanite Barding"] = "благословенний арканітовий бард", ["Blessed Arcanite Barding (Provided)"] = "благословенний арканітовий бард (видано)" } },
    [7645] = { [1] = "Збагачений маною корм для коней", [2] = "Срібляста Десниця вважала мене БОЖЕВІЛЬНОЮ, коли я сказала їм, що можу робити корм, яким можна нагодувати духів коней. ВСІ думали що я несповна розуму! Що ж, настав час розплати!\n\nЯ зроблю те, що тобі потрібно, {КЛАС:к}... теж мені {стать:ЗАХИСНИК:ЗАХИСНИЦЯ}... та не задарма. Мені потрібні інгредієнти — збагачене маною печиво, що продається лише у Сріблястого Світанку. А ще я вимагаю... так, ВИМАГАЮ компенсацію за всі страждання. Золотом.\n\nПокажи мені цю вашу жертовність, про яку ви всі балакаєте, {КЛАС:к}.", [3] = "Принесіть 20 наповненого маною печива — ключового інгредієнта збагаченого маною корму для коней — Мерідет Карлсон в Південнобережжя, що в передгір'ях Гіллзбраду. Вони продаються лише у Сріблястого Світанку.\n\nТакож вам знадобиться 50 золотих, щоб заспокоїти її чутливе его.", [4] = "Ну що, розумієш тепер, як ви всі помилялись? А я ж казала! Я КАЗАЛА ПРАВДУ ВЕСЬ ЦЕЙ ЧАС!!!", [5] = "НУ ЩО, ХТО ТЕПЕР... Зажди, ти й золото {стать:приніс:принесла}? Ти не {стать:назвав:назвала} мене божевільною як інші (точніше, вони казали, що я хвора на голову)... Але все ж, ти хочеш загладити чужу провину?\n\nЯ... Я недооцінила тебе, {ім'я:к}. Якщо знадобиться більше корму — приходь до мене, я дам ще. Дякую тобі, {стать:благородний:благородна} {клас:к}.\n\nАле гроші я візьму — я не настільки божевільна, щоб відмовитися від такої суми.", ["en"] = "Manna-Enriched Horse Feed", ["tasks"] = { ["Enriched Manna Biscuit"] = "збагачене маною печиво", ["Enriched Manna Biscuit (Provided)"] = "збагачене маною печиво (видано)" } },
    [7646] = { [1] = "Кристал провидіння", [2] = "Тепер ми маємо зібрати кристал провидіння — він допоможе тобі провести ритуал спокути над лицарським конем і повернути його душу. Сам кристал майже готовий. Кадильниця екзорцизму, що ти {стать:використовував:використовувала} в Страходолі послужила для нього каталізатором. Залишилось лише зробити підхоже обрамлення.\n\nПотрібно лише два камені, що доповнять одне одного як блиском, так і призначенням — азеротський та чистий чорний діаманти. Вони стануть маяком, що розріже темряву перед тобою.", [3] = "Принесіть азеротський діамант та чистий чорний діамант лорду Сивенку Тінелому на соборну площу Штормовію.", [4] = "Ти {стать:зайшов:зайшла} так далеко, {клас:к}. Твій останній акт пожертви стане вінцем твоїх величних звершень. Я відчуваю це всім своїм єством!", [5] = "Це прекрасні екземпляри, {ім'я:к}. Нарешті, останні фрагменти на місці, твій час настав!\n\nВ глибинах великого склепу Некроситету лежать рештки багатьох створінь. Серед них — кістки благородного бойового коня. Спустошена душа цього коня тепер служить лицарю смерті на ім'я Тінегубитель. Ти зустрінешся з ним в бою і здійсниш правосуддя над ним і його скакуном. Тільки ти, {ім'я:к}, зможеш провести ритуал спокути над душею благородного лицарського коня і позбавити його страждань служіння темним силам.", ["en"] = "The Divination Scryer", ["tasks"] = { ["Azerothian Diamond"] = "азеротський діамант", ["Azerothian Diamond (Provided)"] = "азеротський діамант (видано)", ["Pristine Black Diamond"] = "чистий чорний діамант", ["Pristine Black Diamond (Provided)"] = "чистий чорний діамант (видано)" } },
    [7647] = { [1] = "Правосуддя і спокута", [2] = "Візьми цю сумку — в ній все необхідне для твого завдання.\n\nВикористай кристал провидіння в глибинах великого склепу, щоб викликати чотирьох духів, які потребують правосуддя. Використовуй своє правосуддя мудро — воно несе більшу силу, ніж здається на перший погляд. Після перемоги над духами з'явиться лицар смерті. Вбий його та врятуй загублену душу його коня. Тільки тоді, {ім'я:к}, ти зможеш спокутувати її гріхи та помістити свій бард на спину свого нового скакуна.\n\nНехай тобі щастить!", [3] = "Використайте кристал провидіння в глибинах підземель великого склепу Некроситету. Це викличе чотирьох духів, над якими ви маєте провести правосуддя. Перемога над цими духами викличе лицаря смерті Тінегубителя. Переможіть його та проведіть ритуал спокути над душею його коня.\n\nВіддайте спасенну душу коня та благословенний арканітовий бард коню Тінегубителя.", [4] = "Загублений дух скакуна дивиться на вас поглядом, повним скорботи. В його змертвілих очах давно погас останній промінь надії.", [5] = "Проблиск життя, давно втраченого благородним створінням, знову сяє в його очах, щойно ви повертаєте йому його спасенну душу. Щойно ви кладете бард на його спину, вас оточує шалена сила Світла. Кінь притискається до вашої руки в знак подяки за спасіння. Ви відчуваєте, що тепер у вас з'явився вірний друг, який з'явиться за першим вашим покликом.", ["en"] = "Judgment and Redemption", ["tasks"] = { ["Blessed Arcanite Barding"] = "благословенний арканітовий бард", ["Blessed Arcanite Barding (Provided)"] = "благословенний арканітовий бард (видано)", ["Charger's Redeemed Soul"] = "спасенна душа коня", ["Charger's Redeemed Soul (Provided)"] = "спасенна душа коня (видано)" } },
    [7648] = { [1] = "Найкраща робота Ґріманда", [2] = "<Ґріманд змахує піт з чола, сяючи від гордості.>\n\n Готово, {стать:друже мій:люба моя}. Це моя найкраща робота — не гірше за бард, що я робив для самого лорда Тінелома, коли він йшов за своїм конем. Дякую тобі за довіру, я старався.\n\nНе сумніваюсь, Сивенко захоже побачити це на власні очі. Віднеси бард йому і передай, що я щиро вдячний за цю благородну справу.", [3] = "Віднесіть арканітовий бард лорду Сивенку Тінелому в соборний район Штормовію на огляд.", [4] = "Ти непогано проявляєш себе, {ім'я:к}. Отримавши бард, ти можеш відправлятись за наступним завданням.", [5] = "Неймовірна робота. Схоже, що з часом майстерність Ґріманда тільки росте. Він був найкращим майстром ще за часів, коли він робив бард для мого коня.\n\nЦей бард був би неймовірним доповненням для звичайного коня, та ми маємо справу з незвичайним створінням. Тобі знадобиться особливе благословення, якщо хочеш, щоб він був гідний паладинського бойового коня.", ["en"] = "Grimand's Finest Work", ["tasks"] = { ["Arcanite Barding"] = "арканітовий бард", ["Arcanite Barding (Provided)"] = "арканітовий бард (видано)" } },
    [7649] = { [1] = "Зачаровані торієві обладунки: Том I", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Молодець, {стать:мій хлопчику:моя дівчинко}.\n\n<Хранитель знань Лідрос вириває сторінку з книги.>\n\nЯ впевнений, що ти зможеш скористатися цим кресленням.", ["en"] = "Enchanted Thorium Platemail: Volume I", ["tasks"] = { ["Enchanted Thorium Platemail"] = "Зачаровані торієві обладунки", ["Enchanted Thorium Platemail (Provided)"] = "Зачаровані торієві обладунки (видано)" } },
    [7650] = { [1] = "Зачаровані торієві обладунки: Том II", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Молодець, {стать:мій хлопчику:моя дівчинко}.\n\n<Хранитель знань Лідрос вириває сторінку з книги.>\n\nЯ впевнений, що ти зможеш скористатися цим кресленням.", ["en"] = "Enchanted Thorium Platemail: Volume II", ["tasks"] = { ["Enchanted Thorium Platemail"] = "Зачаровані торієві обладунки", ["Enchanted Thorium Platemail (Provided)"] = "Зачаровані торієві обладунки (видано)" } },
    [7651] = { [1] = "Зачаровані торієві обладунки: Том III", [2] = "Фоліант помічений печаткою Атенеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ти {стать:знайшов:знайшла} фоліант!", [5] = "Молодець, {стать:мій хлопчику:моя дівчинко}.\n\n<Хранитель знань Лідрос вириває сторінку з книги.>\n\nЯ впевнений, що ти зможеш скористатися цим кресленням.", ["en"] = "Enchanted Thorium Platemail: Volume III", ["tasks"] = { ["Enchanted Thorium Platemail"] = "Зачаровані торієві обладунки", ["Enchanted Thorium Platemail (Provided)"] = "Зачаровані торієві обладунки (видано)" } },
    [7652] = { [1] = "Вигідна угода", [5] = "Добре, {стать:пане:пані}, у мене є гаряча пропозиція для вас.\n\nЯ тут хочу продати кілька креслень імперських латних обладунків, і мені потрібен покупець. В обмін я хочу отримати злитки торію. Обговоримо деталі?", ["en"] = "A Blue Light Bargain" },
    [7653] = { [1] = "Імперський латний пояс", [4] = "За креслення ременя я прошу 20 злитків торію.", [5] = "Приємно мати з тобою справу.\n\nІ {ім'я}, зітри сей вираз огиди зі свого обличчя.", ["en"] = "Imperial Plate Belt", ["tasks"] = { ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [7654] = { [1] = "Імперські латні чоботи", [4] = "За креслення чоботів я прошу 40 злитків торію. Так, 40. Ти що, зара' заплачеш? Дати хустинку?\n\n<Деротайн сміється.>", [5] = "Приємно мати з тобою справу.\n\nІ {ім'я}, зітри сей вираз огиди зі свого обличчя.", ["en"] = "Imperial Plate Boots", ["tasks"] = { ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [7655] = { [1] = "Імперські латні браслети", [4] = "За креслення браслетів я хочу 20 злитків торію.\n\nВсе гаразд, {стать:хлопче:дівчинко}? Ти {стать:весь почервонів:вся почервоніла}.", [5] = "Приємно мати з тобою справу.\n\nІ {ім'я}, зітри сей вираз огиди зі свого обличчя.", ["en"] = "Imperial Plate Bracer", ["tasks"] = { ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [7656] = { [1] = "Імперська латна кіраса", [4] = "За креслення кіраси я хочу 60 злитків торію.\n\nЙой, знову ти за своє. Що, побіжиш до своїх божків питати, чому вони тебе покинули?! Тримайся, нюня! Ніхто ніколи не казав, що життя справедливе.", [5] = "Приємно мати з тобою справу.\n\nІ {ім'я}, зітри сей вираз огиди зі свого обличчя.", ["en"] = "Imperial Plate Chest", ["tasks"] = { ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [7657] = { [1] = "Імперський латний шолом", [4] = "Просто дай 50 злитків торію, і креслення шолома твоє.", [5] = "Приємно мати з тобою справу.\n\nІ {ім'я}, зітри сей вираз огиди зі свого обличчя.", ["en"] = "Imperial Plate Helm", ["tasks"] = { ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [7658] = { [1] = "Імперські латні штани", [4] = "Просто віддай 60 злитків торію, і креслення штанів твоє.\n\nЗнаю, я доведу тебе до банкрутства! Я се все вже чув, тож мо' приберегти свої сльозливі історії, {стать:слабак:слабачко}.", [5] = "Приємно мати з тобою справу.\n\nІ {ім'я}, зітри сей вираз огиди зі свого обличчя.", ["en"] = "Imperial Plate Leggings", ["tasks"] = { ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [7659] = { [1] = "Імперські латні наплічники", [4] = "За креслення наплічників я хочу 20 злитків торію.", [5] = "Приємно мати з тобою справу.\n\nІ {ім'я}, зітри сей вираз огиди зі свого обличчя.", ["en"] = "Imperial Plate Shoulders", ["tasks"] = { ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [7660] = { [1] = "Заміна арктичного вовка", [5] = "Якщо приведеш мені свого старого швидкого вовка — я обміняю його на одного з нової зграї. Новий вовк буде таким же швидким, як і твій попередній, але матиме інший вигляд. Ти можеш подивитися, як виглядають ці вовки, тут.", ["en"] = "Wolf Swapping - Arctic Wolf", ["tasks"] = { ["Horn of the Arctic Wolf"] = "ріг арктичного вовка", ["Horn of the Arctic Wolf (Provided)"] = "ріг арктичного вовка (видано)" } },
    [7661] = { [1] = "Заміна рудого вовка", [5] = "Якщо приведеш мені свого старого швидкого вовка — я обміняю його на одного з нової зграї. Новий вовк буде таким же швидким, як і твій попередній, але матиме інший вигляд. Ти можеш подивитися, як виглядають ці вовки, тут.", ["en"] = "Wolf Swapping - Red Wolf", ["tasks"] = { ["Horn of the Red Wolf"] = "ріг рудого вовка", ["Horn of the Red Wolf (Provided)"] = "ріг рудого вовка (видано)" } },
    [7662] = { [1] = "Заміна бірюзового кодо", [5] = "Якщо приведеш мені свого старого кодо — я обміняю його на одного з нового стада. Новий кодо буде таким же швидким, як і твій попередній, але матиме інший вигляд. Ти можеш подивитися, як виглядають ці великі кодо, тут, щоб знати, з чого обирати.", ["en"] = "New Kodo - Teal", ["tasks"] = { ["Teal Kodo"] = "бірюзовий кодо", ["Teal Kodo (Provided)"] = "бірюзовий кодо (видано)" } },
    [7663] = { [1] = "Заміна зеленого кодо", [5] = "Якщо приведеш мені свого старого кодо — я обміняю його на одного з нового стада. Новий кодо буде таким же швидким, як і твій попередній, але матиме інший вигляд. Ти можеш подивитися, як виглядають ці великі кодо, тут, щоб знати, з чого обирати.", ["en"] = "New Kodo - Green", ["tasks"] = { ["Green Kodo"] = "зелений кодо", ["Green Kodo (Provided)"] = "зелений кодо (видано)" } },
    [7664] = { [1] = "Заміна кремового раптора", [5] = "Якщо приведеш мені свого старого раптора - я обміняю його на нового з нагостреними пазурями. Новий раптор буде таким же швидким, як і твій попередній, але матиме новий вигляд. Ти можеш подивитися, як виглядають ці прудкі раптори, тут.", ["en"] = "Ivory Raptor Replacement", ["tasks"] = { ["Whistle of the Ivory Raptor"] = "свисток кремового раптора", ["Whistle of the Ivory Raptor (Provided)"] = "свисток кремового раптора (видано)" } },
    [7665] = { [1] = "Заміна червоного раптора", [5] = "Якщо приведеш мені свого старого раптора - я обміняю його на нового з нагостреними пазурями. Новий раптор буде таким же швидким, як і твій попередній, але матиме новий вигляд. Ти можеш подивитися, як виглядають ці прудкі раптори, тут.", ["en"] = "Red Raptor Replacement", ["tasks"] = { ["Whistle of the Mottled Red Raptor"] = "свисток строкатого червоного раптора", ["Whistle of the Mottled Red Raptor (Provided)"] = "свисток строкатого червоного раптора (видано)" } },
    [7666] = { [1] = "Повернення до великого склепу", [5] = "Ти знову йдеш до Некроситету, {ім'я:к}? Ти {стать:заплатив:заплатила} велику ціну за кристал провидіння, тож, може, ти хочеш взяти з собою ще один? З ним ти зможеш знову пройти випробування великого склепу.\n\nВ будь-якому разі, тримай. Ти його {стать:заслужив:заслужила}.", ["en"] = "Again Into the Great Ossuary" },
    [7667] = { [1] = "Матеріальна допомога", [2] = "{ім'я}, є нагальна справа, з якою, я сподіваюся, ти можеш мені допомогти... як матеріально, так і духовно. Дозволь мені пояснити.\n\nУ глибинах Некроситету в Лордероні є кімната, яку називають великим склепом. Мені потрібно завершити пристрій, який дозволить розвіяти зловісні тіні цього моторошного місця. Але для цього мені потрібні два діаманти: азеротський і чистий чорний. Я знаю, що знайти їх не просто, та сам я їх роздобути не зможу.\n\nЧи не {стать:міг би:могла б} ти роздобути ці діаманти для мене?", [3] = "Принесіть азеротський діамант і чистий чорний діамант Саґорну Хребтоступу в долину Мудрості, що в Орґріммарі.", [4] = "Мені незручно просити про матеріальну допомогу, але для кристала провидіння — пристрою, який я сподіваюся закінчити — потрібні обидва ці камені. Якщо ти не зможеш мені допомогти, я зрозумію...", [5] = "Твоя щедрість не знає меж, {ім'я:к}. Я дякую за твою доброту.\n\nТепер я зможу закінчити свій кристал провидіння, і навіть не один... можливо, тобі буде цікаво допомогти мені в його використанні? Запевняю тебе, це надзвичайно важлива справа... Якщо її не виконати, світу духів загрожує катастрофа!", ["en"] = "Material Assistance", ["tasks"] = { ["Azerothian Diamond"] = "азеротський діамант", ["Azerothian Diamond (Provided)"] = "азеротський діамант (видано)", ["Pristine Black Diamond"] = "чистий чорний діамант", ["Pristine Black Diamond (Provided)"] = "чистий чорний діамант (видано)" } },
    [7668] = { [1] = "Загроза Тінегубителя", [2] = "Лицар смерті Тінегубитель панує у великому склепі Некроситету. Він погрожує підкорити царство духів своїй волі, і його необхідно зупинити! Ось тут-то тобі й знадобиться кристал провидіння.\n\nПриведи його в дію у самому серці великого склепу, щоб викликати поплічників Тінегубителя. Коли ти здолаєш цих духів, з'явиться сам лицар смерті. Принеси мені його голову, {ім'я}! Тільки його смерть здатна виправити шкоду, завдану царству духів!", [3] = "Використайте кристал провидіння в глибинах підземель великого склепу Некроситету. Це викличе чотирьох духів, з якими ви маєте битись. Перемога над цими духами викличе лицаря смерті Тінегубителя. Переможіть його.\n\nВіднесіть голову Тінегубителя Саґорну Хребтоступу в долину Мудрості, що в Орґріммарі.", [4] = "Часу обмаль, {ім'я} — тобі вдалося зупинити лицаря смерті Тінегубителя?", [5] = "Це гідна перемога, {ім'я}! Загибель Тінегубителя має відновити тендітні кайдани, що тримають царство духів.\n\nТи значно {стать:перевершив:перевершила} те, чого від тебе вимагали, навіть коли ти не мав жодного уявлення про винагороду чи компенсацію. Ти справді {стать:гідний:гідна} {клас}.\n\nЯ знаю, що дії, спрямовані на збереження царства духів мають бути достатньою подякою, але, будь ласка — прийми цей простий подарунок на знак моєї вдячності.", ["en"] = "The Darkreaver Menace", ["tasks"] = { ["Darkreaver's Head"] = "голова Тінегубителя" } },
    [7669] = { [1] = "Повернення до великого склепу", [5] = "Ти знову йдеш до Некроситету, {ім'я}? Ти {стать:заплатив:заплатила} велику ціну за кристал провидіння, тож, може, ти хочеш взяти з собою ще один? З ним ти зможеш знову пройти випробування великого склепу.\n\nВ будь-якому разі, тримай. Ти його {стать:заслужив:заслужила}.", ["en"] = "Again Into the Great Ossuary" },
    [7670] = { [1] = "Лорд Сивенко Тінелом", [2] = "Прийшов твій час, {ім'я:к}, отримати те, чого ти певно давно {стать:чекав:чекала} — твого бойового коня.\n\nПоговори з лордом Сивенком Тінеломом в соборному районі Штормовію. Він допоможе тобі не тільки дізнатись більше про вірного паладинського скакуна, але й допоможе тобі його отримати.\n\nНехай тобі щастить в цьому випробуванні. Заради Світла, {стать:благородний брате:благородна сестро}!", [3] = "Поговоріть з лордом Сивенком Тінеломом на соборній площі Штормовію.", [5] = "Радий бачити тебе, {ім'я:к}. Знаю, ти давно {стать:хотів:хотіла} отримати бойового коня. І ось прийшов твій час.\n\nТебе звісно чекає безліч різноманітних випробувань, та найголовніше — твоя рішучість перед численними перешкодами. Це будуть не навчальні завдання — твоєму досвіду вони вже не личать. Тобі доведеться вирвати свого майбутнього компаньйона з лап того самого зла, боротьбі з яким ти {стать:присвятив:присвятила} своє життя.\n\nБережи себе, твій час настав.", ["en"] = "Lord Grayson Shadowbreaker" },
    [7671] = { [1] = "Заміна кригозуба", [5] = "Якщо приведеш мені свого старого кригозуба — я обміняю його на одного з нової зграї. Новий кригозуб буде таким же швидким, як і твій попередній, але матиме інший вигляд. Ти можеш подивитися, як виглядають ці прудкі кригозуби, тут.", ["en"] = "Frostsaber Replacement", ["tasks"] = { ["Reins of the Frostsaber"] = "поводи кригозуба", ["Reins of the Frostsaber (Provided)"] = "поводи кригозуба (видано)" } },
    [7672] = { [1] = "Заміна ночезуба", [5] = "Якщо приведеш мені свого старого ночезуба — я обміняю його на одного з нової зграї. Новий ночезуб буде таким же швидким, як і твій попередній, але матиме інший вигляд. Ти можеш подивитися, як виглядають ці прудкі ночезуби, тут.", ["en"] = "Nightsaber Replacement", ["tasks"] = { ["Reins of the Nightsaber"] = "поводи ночезуба", ["Reins of the Nightsaber (Provided)"] = "поводи ночезуба (видано)" } },
    [7673] = { [1] = "Заміна морозного барана", [5] = "Приведи мені свого старого барана, — і я обміняю його на іншого з нового стада! Новий баран буде так само швидкий, як і старий, але матиме новий вигляд. Можеш подивитися на стрімких баранів тут, аби знати, з чого обиратимеш.", ["en"] = "Frost Ram Exchange", ["tasks"] = { ["Frost Ram"] = "морозний баран", ["Frost Ram (Provided)"] = "морозний баран (видано)", ["Frost Ram slain"] = "морозний баран: убито" } },
    [7674] = { [1] = "Заміна чорного барана", [5] = "Приведи мені свого старого барана, — і я обміняю його на іншого з нового стада! Новий баран буде так само швидкий, як і старий, але матиме новий вигляд. Можеш подивитися на стрімких баранів тут, аби знати, з чого обиратимеш.", ["en"] = "Black Ram Exchange", ["tasks"] = { ["Black Ram"] = "чорний баран", ["Black Ram (Provided)"] = "чорний баран (видано)", ["Black Ram slain"] = "чорний баран: убито" } },
    [7675] = { [1] = "Заміна крижано-блакитного механобіга", [5] = "Якщо ти ще їздиш на тому старезному крижано-блакитному механобігу моделі A, то тобі неодмінно треба спробувати замінити його на нову модель. Твій новий стрімкий механобігу підтримує таку ж швидкість, що і старий, маючи абсолютно новий вигляд. Тут ти можеш переглянути стрімкі механобіги, щоб побачити, з чого доведеться обирати.", ["en"] = "Icy Blue Mechanostrider Replacement", ["tasks"] = { ["Icy Blue Mechanostrider Mod A"] = "крижано-блакитний механобіг, модель А", ["Icy Blue Mechanostrider Mod A (Provided)"] = "крижано-блакитний механобіг, модель А (видано)", ["Icy Blue Mechanostrider Mod A slain"] = "крижано-блакитний механобіг, модель А: убито" } },
    [7676] = { [1] = "Заміна білого механобіга", [5] = "Якщо ти ще їздиш на тому старезному білому механобігу моделі A, то тобі неодмінно треба спробувати замінити його на нову модель. Твій новий стрімкий механобігу підтримує таку ж швидкість, що і старий, маючи абсолютно новий вигляд. Тут ти можеш переглянути стрімкі механобіги, щоб побачити, з чого доведеться обирати.", ["en"] = "White Mechanostrider Replacement", ["tasks"] = { ["White Mechanostrider Mod A"] = "білий механобіг, модель А", ["White Mechanostrider Mod A (Provided)"] = "білий механобіг, модель А (видано)", ["White Mechanostrider Mod A slain"] = "білий механобіг, модель А: убито" } },
    [7677] = { [1] = "Обмін білого жеребця", [5] = "Якщо приведеш мені свого білого жеребця, то я обміняю його на одного з нового табуна. Новий кінь буде таким же швидким, як і твій попередній, але матиме інший вигляд. Ти можеш подивитися, як виглядають ці прудкі скакуни, тут.", ["en"] = "White Stallion Exchange", ["tasks"] = { ["White Stallion Bridle"] = "вузда білого жеребця", ["White Stallion Bridle (Provided)"] = "вузда білого жеребця (видано)" } },
    [7678] = { [1] = "Обмін солового коня", [5] = "Якщо приведеш мені свого солового коня, то я обміняю його на одного з нового табуна. Новий кінь буде таким же швидким, як і твій попередній, але матиме інший вигляд. Ти можеш подивитися, як виглядають ці прудкі скакуни, тут.", ["en"] = "Palomino Exchange", ["tasks"] = { ["Palomino Bridle"] = "вузда солового коня", ["Palomino Bridle (Provided)"] = "вузда солового коня (видано)" } },
    [7681] = { [1] = "Випробувальний квест мисливця", [2] = "Налийте корм для вашого улюбленця.", ["en"] = "Hunter test quest" },
    [7682] = { [1] = "Випробувальний квест Мисливця 2", [2] = "Налийте корм для вашого улюбленця.", ["en"] = "Hunter test quest2" },
    [7701] = { [1] = "РОЗШУКУЄТЬСЯ: розпорядник Мальторій", [2] = "З наказу його височенства розпорядника Слизькорука, розшукується пройдисвіт Торієвого братства та новопризначений командир бригади дворфів Темного Заліза в Котлі, розпорядник Мальторій. Його потрібно убити, а його голову принести як доказ.\n\nЗверніться до капітана дозорних Лоло Довгобоя за винагородою.", [3] = "У глибинах Шлакової Ями в Котлі знайдіть зрадника-дворфа Темного Заліза, на ім'я розпорядник Мальторій.\n\nВбийте розпорядника Мальторія і заберіть його голову. Принесіть її капітану дозорних Лоло Довгобою у Випалену ущелину, щоб отримати винагороду.", [4] = "Не бач, шо я занятий? Чого тобі *гик* треба? *гик*", [5] = "Не думав, шо знов побачу сю гидку пику!\n\nМушу визнати, виглядає він трохи краще, коли ти {стать:відрізав:відрізала} все зайве. *гик*\n\nОт твуя нагорода *гик*, {раса:к}.", ["en"] = "WANTED: Overseer Maltorius", ["tasks"] = { ["Head of Overseer Maltorius"] = "голова розпорядника Мальторія", ["Head of Overseer Maltorius (Provided)"] = "голова розпорядника Мальторія (видано)" } },
    [7702] = { [1] = "Фатальне кланове безсоння", [2] = "Щоб підірвати сили Темного Заліза, які працюють в Шлаковій Ямі, ми повинні вдарити по ним якнайболючіше.\n\nМало хто знає, але дворфи, зокрема Темного Заліза, відпочивають! Багато відпочивають!\n\nТому ось питання: як вони зможуть спати без подушок? Саме так, {ім'я}, ніяк. Тому тобі потрібно пробратися в Шлакову Яму та вкрасти їх подушки.", [3] = "У глибинах Шлакової Ями в Котлі ви знайдете спальні квартали дворфів Темного Заліза.\n\nВідправляйтеся туди й викрадіть 20 подушок Темного Заліза. Виконавши це завдання, поверніться до Евоніс Коптильниці у Випалену ущелину.", [4] = "Не дозволяй божевільним окулярам обдурити тебе, {ім'я}. Я тут найрозумніша.", [5] = "Чудово! Сонним дворфам Шлакової Ями доведетьсяповернуться до своїх домівок у надрах гори, щоб трохи відпочити, що значно сповільнить продуктивність Шлакової Ями.", ["en"] = "Kill 'Em With Sleep Deprivation" },
    [7703] = { [1] = "Незакінчена справа Ґордоків", [2] = "Тепер ти король, значить можливо ти зможеш відібрать цінний артефакт Ґордоків у того страшного ельфа, шо зове себе принцом! Прошлий король не справився з цим, як і всі інші, хто пробував його повернути, з тої давнини, як Тортельдрін, той страшний ельф, вкрав його в короля Ґордока!\n\nАртефакт зоветься рукавичкою могутності Ґордока. Старі легенди кажуть, шо повернуть її може тільки справжній король Ґордок. В старій легенді також говориться, шо цей страшний ельф все ще вештається десь поруч. Найди цей артефакт і матимеш могутню рукавичку, яку зможеш носить завжди!", [3] = "Знайдіть рукавичку могутності Ґордока і поверніть її капітану Дужохрусту в Грізний Молот.\n\nЗа словами Дужохруста, \"стара легенда\" свідчить, що Тортельдрін — \"страшний\" ельф, який називав себе принцом — вкрав її в одного з королів Ґордоків.", [4] = "Ха-ха, ну шо, бос, не {стать:знайшов:знайшла}? Може, стара легенда бреше... важко повірить, шо той страшний ельф міг шось вкрасти у короля Ґордока!", [5] = "Ого... ти {стать:справжній король:справжня королева}! Ніколи в житті не думав, шо побачу цю рукавичку! Схоже, в ній більше не залишилося сили... Може, цей страшний ельф намагався зіпсувать її. Ну, я скажу йому ГРР РРР!\n\nДивись — цей знак на рукавичці, старий-пристарий чарівний знак, старіший за всіх королів Ґордоків, як то кажуть. Нас, капітанів Гордоків, навчають, як оживить знак і вернуть силу рукавичці!\n\nЯ зроблю це для тебе, {стать:король:королева}! Ось, візьми рукавичку і керуй ЗАВЖДИ!", ["en"] = "Unfinished Gordok Business", ["tasks"] = { ["Gauntlet of Gordok Might"] = "рукавичка могутності Ґордока", ["Gauntlet of Gordok Might (Provided)"] = "рукавичка могутності Ґордока (видано)" } },
    [7704] = { [1] = "Тільки подивись-но на її розміри!", [2] = "Так, так, так... Ось так сюрприз. У головної покоївки була гігантська вишита подушка, і тепер вона ваша. Евоніс Коптильниця неодмінно захоче отримати її. Принесіть їй подушку, щоб подивитись, чи не запропонує вона за неї щось цікаве.", [3] = "Віднесіть подушку покоївки Ніжностиск до Евоніс Коптильниці у Випалену ущелину.", [4] = "Оце так подушка! Звідки вона в тебе?", [5] = "Це навіть краще, ніж я могла собі уявити! Чарівна подушка покоївки — моя! Повір, {ім'я}, ти отримаєш гарну винагороду за неї!", ["en"] = "Look at the Size of It!", ["tasks"] = { ["Chambermaid Pillaclencher's Pillow"] = "подушка покоївки Ніжностиск", ["Chambermaid Pillaclencher's Pillow (Provided)"] = "подушка покоївки Ніжностиск (видано)" } },
    [7721] = { [1] = "Паливо для зменшувача", [2] = "Якщо я вчиню всупереч моєму глузду і залишуся керувати інженерною майстернею на Забутому узбережжі, мені доведеться мати справу з цими надокучливими елементалями. Щоб їм провалитися, цим неприборканим стихіям!\n\nНа щастя для мене, а тепер і для тебе, {стать:мій надійний помічнику:моя надійна помічнице}, ці елементалі є ідеальним джерелом енергії для мого ультразменшувача! Тож всип їм, не соромся! Але ж тільки не забудь збирати для мене їхні ядра!", [3] = "Зберіть 10 ядер водяних елементалів з морських елементалів і морських бризків уздовж Забутого узбережжя Фераласа і принесіть їх Зорбіну Блимоверту, який знаходиться там біля причалу.", [4] = "Я не буду докучати технічними подробицями та поясненнями того, навіщо мені ці ядра. Я краще натякну, що, виконавши це важливе завдання, ти отримаєш чимало монет, і дещо корисне на додачу. Ну що, де мої ядра?", [5] = "Супердуперово! Так, цих ядер мені вистачить надовго... Ба більше: тепер на узбережжі стане менше цих елементалів і, можливо, я більше не плакатиму перед сном від думки про те, що я вибрав для своєї майстерні найгірше місце у світі!\n\nДякую, {ім'я}, за всі твої зусилля. Хоча це й дещо обтяжує мене фінансово, але дозволь мені висловити мою вдячність зрозумілим для тебе чином... здобиччю!", ["en"] = "Fuel for the Zapping", ["tasks"] = { ["Water Elemental Core"] = "ядро водяного елементаля", ["Water Elemental Core (Provided)"] = "ядро водяного елементаля (видано)" } },
    [7722] = { [1] = "Якого флюса?", [2] = "Коли цей негідник, Мальторій, покинув наш клан, він забрав з собою дещо цінніше за бездоганний арканічний кристал — наш рецепт вогненного флюса! Зуб даю, що він зробив це, щоб вислужитися у дворфів Темного Заліза.\n\nЯ хочу, щоб ти {стать:знайшов:знайшла} наш секретний рецепт, {ім'я}. Я впевнений, що Мальторій тримає його при собі, глибоко в Шлаковій Ямі.", [3] = "Знайдіть у Шлаковій Ямі, що в Котлі, розпорядника Мальторія, що вкрав секрет створення вогненного флюса. Знайдіть ці плани та поверніть їх ковалю-майстру Вогнероду в Випалену ущелину.", [4] = "Ти {стать:знайшов:знайшла} його?", [5] = "Сподіваюся, ти заодно {стать:вибив:вибила} йому зуби, {ім'я}. Він на це заслужив!\n\nТепер ми можемо повернутися до справ.", ["en"] = "What the Flux?", ["tasks"] = { ["Secret Plans: Fiery Flux"] = "секретний рецепт: вогненний флюс", ["Secret Plans: Fiery Flux (Provided)"] = "секретний рецепт: вогненний флюс (видано)" } },
    [7723] = { [1] = "Кляті набряклі пальці", [2] = "Шкода, та через проблеми з пальцями я не дужий бити си, як колис. Бач, через тутешній клімат і низький атмосферний тиск мої пальци набрякают. Нинька вони нагадуют гігантські сардельки...\n\nТож тобі доведет си попрацювати за мене.\n\nПерше діло в мому списку: поубивати бойових големів, їких мо' знайти в ущелині. Давай, вйо до роботи!", [3] = "Гензель Важкорукий просить вас вбити 20 важких бойових големів.\n\nВажкі бойові големи блукають околицями Котла у Випаленій ущелині. Коли вб'єте достатньо, поверніться до Гензеля.", [4] = "Ну, {стать:повбивав:повбивала} їх?", [5] = "Ти {стать:файний хлопак:файне дівча}. У мене є для тебе невеличкий дарунок.", ["en"] = "Curse These Fat Fingers", ["tasks"] = { ["Heavy War Golem"] = "важкий бойовий голем", ["Heavy War Golem slain"] = "важкий бойовий голем: убито" } },
    [7724] = { [1] = "Вогняна напасть!", [2] = "Уявляєш, кожен раз, їк старий Гензел хо' відпочити та подумати над життєм, на його долю випадає нове завдання.\n\nМені тре' подумати! Розумієш, що я кажу?\n\nОтож, ци великі лавові павуки додали проблеми. Слизькорук каже, що вони випускают вогонь зі своїх... емм, ну, взагалі-то, про таки речи не кажут дітям.\n\nМабут, нам доведетьси їх вбити. Точніше, тобі доведетьси їх вбити.", [3] = "Гензель Важкорук просить вас вбити 20 великих лавових павуків. Їх можна знайти на плато та в лавових басейнах Випаленої ущелини.\n\nПоверніться до Гензеля, коли вб'єте достатню кількість павуків.", [4] = "Ну що? Вони справді випускают вогонь прємо з дупи?", [5] = "<Гензель чхає.>\n\nЗдається, я застудив си. Клятий холод!", ["en"] = "Fiery Menace!", ["tasks"] = { ["Greater Lava Spider"] = "великий лавовий павук", ["Greater Lava Spider slain"] = "великий лавовий павук: убито" } },
    [7725] = { [1] = "І знову зменшення велетнів!", [2] = "Я знаю, що ти вже {стать:збирав:збтрала} залишки для мене... але якщо ти хочеш знову розважитися, то мені завжди потрібні нові залишки.\n\nТакої великої винагороди, як раніше, я звісно запропонувати не зможу, але зате я буду радий розповісти про твої вчинки усім моїм друзям-гоблінам.\n\nПовірте мені, {стать:сер:леді}, гобліни до моїх слів уважно прислухаються.", [3] = "Використовуйте ультразменшувач Зорбіна, щоб зменшити будь-якого велетня Фераласа до менш небезпечної форми. Принесіть 10 залишків мініатюризації Зорбіну Блимоверту близ причалу Забутого узбережжя, що у Фераласі.", [4] = "Ах, ось вони, плоди досліджень та розумної утилізації: мої солоденькі залишки! Ні-ні, ти тільки не подумай, ніби я куштував їх на смак!\n\nМайже не куштував.", [5] = "Суперфантастично, {ім'я}! Ти знову мені {стать:допоміг:допомогла}, і я дуже вдячний.\n\nДякую!\n\nХоча ця монета може здатися трохи меншою, ніж ти {стать:звик:звикла}, будь {стать:впевненим:впевненою}, що слова про твої великі подвиги на ниві гоблінства гучно пролунають в залах картелю Паровиманювання. Якщо тобі знадобиться якась допомога, то звертайся до мене без зайвих вагань!", ["en"] = "Again With the Zapped Giants", ["tasks"] = { ["Miniaturization Residue"] = "залишок мініатюризації", ["Miniaturization Residue (Provided)"] = "залишок мініатюризації (видано)" } },
    [7726] = { [1] = "Заправляння зменшувача", [2] = "Хочеш ще попрацювати? Невже героїчне збирання шматків слизу з тіл елементалей не вгамувало твоєї жаги до пригод? Ну, тоді ти, напевно, не засмутишся, якщо я знову дам тобі те саме доручення...\n\nДобре, жарти вбік. Мені дійсно потрібні нові ядра водяних елементалів. Я намагаюся облаштувати тут свою майстерню, тому нагорода не буде такою ж великою... але я обіцяю тобі, що розповім усім своїм знайомим про те, як ти мені {стать:допоміг:допомогла}! А в мене багато знайомих в картелі!", [3] = "Зберіть 6 ядер водяних елементалів з морських елементалів і морських бризків уздовж Забутого узбережжя Фераласа і принесіть їх Зорбіну Блимоверту, який знаходиться там біля причалу.", [4] = "Ти {стать:знайшов:знайшла} ядра водяних елементалів, про які я тебе просив?", [5] = "Першокласно, {ім'я}, першокласно! Хоча ця нагорода, напевно, й не найбільша з тих, що ти коли-небудь {стать:отримував:отримувала} за таку роботу, та будь {стать:певен:певна}, мої товариші з картелю Паровиманювання почують про твої діяння!\n\nЯкщо шукатимеш ще якусь роботу — дай мені знати. Мені завжди потрібні нові ядра елементалів і всіляке інше.", ["en"] = "Refuel for the Zapping", ["tasks"] = { ["Water Elemental Core"] = "ядро водяного елементаля", ["Water Elemental Core (Provided)"] = "ядро водяного елементаля (видано)" } },
    [7727] = { [1] = "Вогнезаври? Скоріше мертвозаври!", [2] = "Бурсит, {стать:хлопче:дівчинко}. У мене бурсит. Як я маю убивати з такими ногами? Ти мені поможеш.\n\nСкрендж та Вогнерод доручили мені знищити цих істот, щоб вони могли відправити дослідницькі команди до лавових басейнів Шлакової Ями. І якісь вогнезаври завдають нам проблем.\n\nТож рушай, {ім'я}, і не повертай си, поки популяція вогнезаврів не буде знищена.", [3] = "Гензель Важкорук хоче, щоб ви вбили 20 вогнезаврів.\n\nВи знайдете вогнезаврів у лавових басейнах всередині Шлакової Ями. Шлакова Яма знаходиться у Котлі в Випаленій ущелині.\n\nПоверніться до Гензеля Важкорука в Випалену ущелину, коли вб'єте достатню кількість вогнезаврів.", [4] = "<Ганзель зайнятий чесанням свого бурситу.>\n\nНе стій без діла, хапай пемзу та припарку і починай чесати сей бурсит.\n\nНемає припарки? Ну що ж! Може, настав час одправити тебе на її пошуки?\n\nГей, ти куди?", [5] = "Ох, як болять муї ноги.\n\nЯ се подумав, раз у тебе немає припарки...", ["en"] = "Incendosaurs? Whateverosaur is More Like It", ["tasks"] = { ["Incendosaur"] = "вогнезавр", ["Incendosaur slain"] = "вогнезавр: убито" } },
    [7728] = { [1] = "ВИКРАДЕНО: Ковальська фурма і підзорна труба спостерігача", [2] = "Були викрадені наступні речі:\n\n*Одна фурма Темного Заліза.\n\n*Одна підзорна труба спостерігача.\n\nПрохання повернути ці предмети за винагороду.\n\nТорієве братство впевнене, що ці речі були викрадені нечесними та заздрісними дворфами Темного Заліза, що мешкають у Випаленій ущелині.\n\nЗгадана підзорна труба була відмінним інструментом для спостерігачів, а фурма є незамінним інструментом ковалів.\n\nЯкщо ви знайдете зазначені речі — поверніть їх Скренджу.", [3] = "Знайдіть і поверніть ковальську фурму і підзорну трубу спостерігача орудару Скренджу в Випалену ущелину.\n\nЄдина інформація про ці предмети полягає в наступному: їх точно викрали дворфи Темного Заліза. Ковальська фурма — це інструмент, який використовується ковалями, а підзорна труба — неоціненний інструмент спостерігачів.", [4] = "Якщо ти {стать:прийшов:прийшла} за винагородою, тобі доведеться віддати мені вкрадені речі.", [5] = "Чудова робота! Ось твоя винагорода.", ["en"] = "STOLEN: Smithing Tuyere and Lookout's Spyglass", ["tasks"] = { ["Lookout's Spyglass"] = "підзорна труба спостерігача", ["Lookout's Spyglass (Provided)"] = "підзорна труба спостерігача (видано)", ["Smithing Tuyere"] = "ковальська фурма", ["Smithing Tuyere (Provided)"] = "ковальська фурма (видано)" } },
    [7729] = { [1] = "ВАКАНСІЯ: Приборкувач конкурентів", [2] = "Орудар Скрендж шукає кількох вправних кандидатів на посаду \"приборкувача конкурентів\" у Випаленій ущелині.\n\nЯкщо ви зацікавлені, вирушайте у Випалену ущелину та вбивайте кожних орударів і поневолювачів Темного Заліза, що трапляться на шляху.\n\nПоверніться до орударя Скренджа, коли ваш одяг просочиться кров'ю.\n\nВи самі зрозумієте, коли це станеться, тому зайвих питань не ставте.", [3] = "Вбийте 15 орударів Темного Заліза і 15 поневолювачів Темного Заліза. Після виконання цього завдання поверніться до орудара Скренджа у Випалену ущелину.", [4] = "Щоб переконатись, я маю зважити тебе в одязі та без нього.", [5] = "7.2 кілограма! Та це ж новий рекорд ваги крові та кишок на одязі! Вітаю, {клас:к}!", ["en"] = "JOB OPPORTUNITY: Culling the Competition", ["tasks"] = { ["Dark Iron Slaver"] = "поневолювач Темного Заліза", ["Dark Iron Slaver slain"] = "поневолювач Темного Заліза: убито", ["Dark Iron Taskmaster"] = "орудар Темного Заліза", ["Dark Iron Taskmaster slain"] = "орудар Темного Заліза: убито" } },
    [7733] = { [1] = "Найвища якість", [2] = "Я маю інформацію про ще КРАЩЕ джерело шкур, якщо в це взагалі можливо повірити! В північній частині Фераласа — глибоко в печері Лютошрамих — живе ще одна зграя єті. Вони міцніші за тих, з якими ти {стать:бився:билася} раніше, тому якщо ти {стать:готовий:готова} до виклику, тебе це має зацікавити!\n\nЯ щедро винагороджу тебе за десять шкур цих єті. Просто принеси мені їх.", [3] = "Принесіть 10 шкур лютошрамних єті Пратту Макґруббену в фортецю Перомісяць, що в Фераласі.", [4] = "Якщо ці шкури не поступаються шкурам лихошрамних єті, вони цілком можуть бути не менш міцними за торій!\n\nТільки уяви!", [5] = "Чудово, чудово! Вони вийдуть неймовірними — я вже бачу, що після належної обробки вони стануть набагато міцнішими.\n\nЩе раз дякую за допомогу, {ім'я}. Ось — будь ласка, візьми один з моїх останніх виробів.", ["en"] = "Improved Quality", ["tasks"] = { ["Rage Scar Yeti Hide"] = "шкура лютошрамного єті", ["Rage Scar Yeti Hide (Provided)"] = "шкура лютошрамного єті (видано)" } },
    [7735] = { [1] = "Бездоганна шкура єті", [2] = "Ви знайшли бездоганну шкуру єті, надзвичайно товсту та міцну — навіть міцнішу за шкури лютошрамних єті.\n\nВраховуючи, що Пратт Макґруббен з фортеці Перомісяць цікавиться шкурами єті, цю знахідку варто показати йому.", [3] = "Принесіть бездоганну шкуру єті Пратту Макґруббену в фортецю Перомісяць, що в Фераласі.", [4] = "Що це, {ім'я} — у тебе є щось особливе для мене?", [5] = "Неймовірно! Ти, можливо, {стать:знайшов:знайшла} шкуру дідуся всіх єті!\n\nПовір, я заплачу тобі за неї. Зазвичай я не плачу стільки за одну шкуру, але я впевнений, що зможу зробити з неї щось особливе. Дякую, що {стать:згадав:згадала} про мене, {ім'я}!", ["en"] = "Pristine Yeti Hide", ["tasks"] = { ["Pristine Yeti Hide"] = "бездоганна шкура єті", ["Pristine Yeti Hide (Provided)"] = "бездоганна шкура єті (видано)" } },
    [7736] = { [1] = "Відновлення запасів вогненного флюса за допомогою королекрові", [4] = "Не марнуй мій дорогоцінний час пустими балачками, {раса:к}. Час сконцентруватися на поповненні наших обмежених запасів вогненного флюса.\n\nМені від тебе потрібно наступне:\n\n*Луска вогнезавра.\n\n*Королекров.\n\n*Вугілля.\n\nЯ візьму все, що ти зможеш принести!\n\nІ поквапся, якщо хочеш заслужити довіру Братства.", [5] = "У нас завжди знайдеться місце для вогненного флюса, {стать:юначе:юначко}. Продовжуй... поки я тебе не зупиню.", ["en"] = "Restoring Fiery Flux Supplies via Kingsblood", ["tasks"] = { ["Coal"] = "вугілля", ["Coal (Provided)"] = "вугілля (видано)", ["Incendosaur Scale"] = "луска вогнезавра", ["Incendosaur Scale (Provided)"] = "луска вогнезавра (видано)", ["Kingsblood"] = "королекров", ["Kingsblood (Provided)"] = "королекров (видано)" } },
    [7737] = { [1] = "Отримати визнання", [4] = "Ти швидко заслуговуєш визнання братства, {раса:к}. Ми починаємо дивитися на тебе з повагою. Це чимале досягнення!\n\nТа якщо ти хочеш заслужити ще більше поваги, слухай уважно.\n\nМи можемо покращити вогненний флюс, додавши до суміші звичайну ожарину темного заліза. Її можна знайти у Чорноскельних надрах.\n\nПринеси мені всю ожарину, яку зможеш знайти!", [5] = "Продовжуй приносити ожарину!", ["en"] = "Gaining Acceptance", ["tasks"] = { ["Dark Iron Residue"] = "ожарина темного заліза", ["Dark Iron Residue (Provided)"] = "ожарина темного заліза (видано)" } },
    [774] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [776] = { [1] = "Обряди Матері-Землі", [2] = "Ти {стать:пройшов:пройшла} Обряд Матері-Землі та {стать:заслужив:заслужила} своє місце у Громовому Бескиді.\n\nАле щоб утримувати позицію, задля якої ти так важко {стать:працював:працювала}, ти {стать:повинен:повинна} продовжувати засвідчувати свою цінність своєму народу.\n\nМи - мисливці, {Ім'я}. У Мулґорі там унизу є могутній кодо на ім'я Арра'чі. Покажи мені свої навички вистежування та полювання - принеси мені ріг Арра'чі.", [3] = "Керн Криваве Копито з Громового Бескиду хоче, щоб ви принесли йому ріг Арра'чі.", [4] = "Ти вже {стать:вистежив:вистежила} Арра'чі?", [5] = "Молодець! Це була вартісна здобич.\n\nЯ відряджу групу збирачів, щоб забрати тушу на шкури та м'ясо.\n\nТи {стать:зробив:зробила} велику справу для свого народу, {Ім'я}.", ["en"] = "Rites of the Earthmother", ["tasks"] = { ["Horn of Arra'chea"] = "ріг Арра'чі", ["Horn of Arra'chea (Provided)"] = "ріг Арра'чі (видано)" } },
    [7761] = { [1] = "Наказ Чорнорука", [2] = "Дурень,\n\nМені не сильно віриться в те, що ти зможеш стримати чужинців та не дати їм зайти в лігво господаря. Якщо ти помреш, ця сфера має власний запобіжник, який не дозволить стороннім телепортуватися назад, в лігво Чорного крила.\n\nЛише ті, хто має мітку Драккісата на руці, можуть скористатися цією сферою. На щастя, Драккісат не такий дурний, як ти, квартирмейстре. Він сам охороняє клеймо!\n\n— Воєвождь Ренд Чорнорук\n\nP.S. Знищ цього листа, ідіоте.", [3] = "Що за дурний орк. Здається, вам потрібно знайти це клеймо та випалити знак Драккісата, щоб отримати доступ до сфери Командування.\n\nУ листі зазначено, що генерал Драккісат охороняє цей знак. Можливо, вам варто це перевірити.", [5] = "Ви навіть не здригаєтеся, коли розжарене клеймо випалює вашу плоть. Ви такі сильні та міцні духом!\n\nТепер ви маєте мітку Драккісата. Щасти вам в штурмі замку.", ["en"] = "Blackhand's Command" },
    [77690] = { [1] = "Невелике оновлення", [2] = "Вітаю, мій шановний {клас} знайомий! Мене звати Джон Трінкетман, я всесвітньо відомий мандрівник і розгадувач головоломок! Ніколи про мене не чули, чи не так? Неважливо! Я тут, у Залізогарті, шукаю два найпрестижніші ювелірні вироби, які коли-небудь бачив цей бік Азероту! Кажуть, що вони утворюють головоломку!\n\nНа жаль, ходять чутки, що вони обидва мешкають у небезпечній Чорній Скелі! Напевно, шукач пригод вашого калібру без проблем знайде ці вироби для мене?", ["en"] = "A Small Upgrade" },
    [777] = { [1] = "Це буде важко", [2] = "Добре, ось зубець #5.\n\nЯ буду тут... в укритті.\n\nМожеш приєднатися, якщо хочеш.", [3] = "Принесіть зубець #5 Лотвілю Веріату.", [4] = "<Не відриваючи погляд від кайданів, Лотвіль простягає руку і нетерпляче розмахує пальцями.>\n\nЗубець, {ім'я}, зубець!", [5] = "Ах, ідеально. Відійди-но в бік, поки я готуюсь вершити історію!\n\n<Лотвіль продовжує гарячково працювати.>", ["en"] = "This Is Going to Be Hard", ["tasks"] = { ["Cog #5"] = "зубець #5", ["Cog #5 (Provided)"] = "зубець #5 (видано)" } },
    [778] = { [1] = "Це буде важко", [2] = "Ха-ха! Готово! Кайдани готові!\n\nНастав час, Люсьєне. Пора, Серво!\n\nТи {стать:готовий:готова} стати свідком досконалої суміші алхімії, інженерії та таємниць, {ім'я}?\n\nЗараз я викличу могутнього елементаля. Це видатний день для всіх нас.", [3] = "Здобудьте перемогу над вартовим Фам'ретором і поверніть Лотвілю Веріату його кайдани зв'язування стихій.", [4] = "Не зовсім той результат, на який я розраховував. Можеш повернути мені мої кайдани?", [5] = "Дякую, {ім'я}. Це було досить важким випробуванням, чи не так?\n\nЯ не впевнений, що саме пішло не так. Добре, що за допомогою магії мені вдалося повернути істоту назад у її рідний вимір.\n\nМожливо, трохи вдячності за всю твою наполегливу працю...", ["en"] = "This Is Going to Be Hard", ["tasks"] = { ["Lotwil's Shackles of Elemental Binding"] = "кайдани зв'язування стихій Лотвіля", ["Lotwil's Shackles of Elemental Binding (Provided)"] = "кайдани зв'язування стихій Лотвіля (видано)" } },
    [7785] = { [1] = "Огляд посудини", [2] = "Оглянь посудину його відродження, {стать:смертний:смертна}. Саме з неї переродиться Шукач Вітру!", [3] = "Огляньте посудину відродження та поверніть її верховному повелителю Демітріану.", [4] = "Чи звільниш ти його з цієї вічної в'язниці?", [5] = "Хай тебе захистять у твоєму поході. Нехай Повелитель благословить твої зусилля.", ["en"] = "Examine the Vessel", ["tasks"] = { ["Vessel of Rebirth"] = "посудина відродження", ["Vessel of Rebirth (Provided)"] = "посудина відродження (видано)" } },
    [7786] = { [1] = "Громаан Шукач Вітру", [2] = "Я розповів тобі все, що знаю, {ім'я}. Саме ти маєш знайти елементій. Саме ти маєш знищити тілесну форму Володара Вогню.\n\nЯкщо ти зробиш це, то отримаєш благословення Громаана.", [3] = "Щоб звільнити Громаана Шукача Вітру з його в'язниці, ви маєте віднести праву та ліву половини кайданів Шукача Вітру, 10 злитків елементію та сутність Володара Вогню верховному повелителю Демітріану в Силітус.", [4] = "Постав цей світ на коліна, якщо доведеться!", [5] = "Навіть уві сні я не смів передбачити цей день.\n\nУзри, {стать:смертний:смертна}.\n\nУЗРИ ТОГО, ХТО СТАРШИЙ ЗА БУТТЯ!\n\nУЗРИ ТОГО, ХТО БИВСЯ З ТИТАНАМИ ТА БОГАМИ!\n\nПОВСТАНЬ, МІЙ ПОВЕЛИТЕЛЮ! ЗВІЛЬНИСЯ ВІД ВЛАСНИХ КАЙДАНІВ!", ["en"] = "Thunderaan the Windseeker", ["tasks"] = { ["Bindings of the Windseeker"] = "кайдани Шукача Вітру", ["Bindings of the Windseeker (Provided)"] = "кайдани Шукача Вітру (видано)", ["Elementium Bar"] = "злиток елементію", ["Elementium Bar (Provided)"] = "злиток елементію (видано)", ["Essence of the Firelord"] = "сутність Володара Вогню", ["Essence of the Firelord (Provided)"] = "сутність Володара Вогню (видано)" } },
    [7787] = { [1] = "Повстань, Громолють!", [2] = "Ви подолали Шукача Вітру. Візьміть цей сплячий клинок та віднесіть його цьому брехливому покидьку, Демітріану. Змусьте його скористатися наданими йому матеріалами, щоб пробудити Громолють.", [3] = "Віддайте сплячий поцілований вітром клинок верховному повелителю Демітріану.", [4] = "<Демітріан тремтить від страху.>", [5] = "Прошу, не кривдь мене! Візьми, що тобі потрібно! Візьми клинок! Дозволь Демітріану збирати уламки свого нікчемного життя!", ["en"] = "Rise, Thunderfury!", ["tasks"] = { ["Dormant Wind Kissed Blade"] = "сплячий поцілований вітром клинок", ["Dormant Wind Kissed Blade (Provided)"] = "сплячий поцілований вітром клинок (видано)" } },
    [7788] = { [1] = "Знищити загарбників!", [2] = "За цим тунелем ти знайдеш поле запеклих битв, {стать:юний:юна} {клас:к}. Орда продовжує нищити наш священний ліс, вирубуючи вічнозелені крони для живлення своїх військових машин.\n\nПрямуй в тіснину Пісні Війни та захисти фортецю Срібнокрилих. Відбий напади ординських загарбників!\n\nЗроби це — і отримаєш талісман заслуг. Принеси мені такий талісман, {ім'я:к}, і я винагороджу тебе.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Орду, отримайте відзнаку честі тіснини Пісні Війни та принесіть її стражниці Далепісні в Срібнокрилі хащі.", [4] = "Тобі вже вдалось захистити фортецю Срібнокрилих в тіснині Пісні Війни?", [5] = "Ти {стать:довів:довела} свою цінність для наших зусиль в тіснині Пісні Війни. Продовжуй допомагати та принеси мені більше талісманів заслуг. Зроби це, і заслужиш нашу довіру.", ["en"] = "Vanquish the Invaders!", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [7789] = { [1] = "Розгромити Срібнокрилих загарбників", [2] = "Хащі Ясенедолу підкоряться могутності Орди, {раса:к}. Що б не робили Срібнокрилі, їм не впоратися з нашим натиском. Калімдор належить Орді. Як вони сміють заважати нам збирати те, що належить нам по праву!\n\nНехай гордість наповнює твої груди, коли ти зломиш їхні жалюгідні спроби зупинити нас. Розгроми Срібнокрилих стражів і заслужи відзнаку честі тіснини Пісні Війни. Повертайся до мене з такою відзнакою, {ім'я:к}, і отримаєш винагороду.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Альянс, отримайте відзнаку честі тіснини Пісні Війни та принесіть її капітану Череподробу в табір Мор'шан.", [4] = "Кров наших ворогів — відзнака честі. Вже маєш таку?", [5] = "<Капітан Череподроб тріумфально ричить.>\n\nСкільки ще вони зможуть витримати? Скільки ще покидьків Альянсу має загинути від рук Орди, щоб вони відступили? Тільки час покаже, {раса:к}...", ["en"] = "Quell the Silverwing Usurpers", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [779] = { [1] = "Печатка Землі", [4] = "Перед вами печатка Землі з трьома заглибленнями для аметистового, опалового та діамантового рунічних каменів.", [5] = "Щойно рунічні камені опинилися у призначених для них заглибленнях, земля затремтіла і печатка зруйнувалася.", ["en"] = "Seal of the Earth", ["tasks"] = { ["Amethyst Runestone"] = "аметистовий рунічний камінь", ["Amethyst Runestone (Provided)"] = "аметистовий рунічний камінь (видано)", ["Diamond Runestone"] = "діамантовий рунічний камінь", ["Diamond Runestone (Provided)"] = "діамантовий рунічний камінь (видано)", ["Opal Runestone"] = "опаловий рунічний камінь", ["Opal Runestone (Provided)"] = "опаловий рунічний камінь (видано)" } },
    [7790] = { [1] = "ПОВТОРНЕ ВИКОРИСТАННЯ", [2] = "Переможи Млин Пісні Війни, а потім повернися до мене.", ["en"] = "REUSE", ["tasks"] = { ["Defeat Warsong Mill"] = "Перемогти Млин Пісні Війни" } },
    [7797] = { [1] = "Роздирач простору — Завшегляд", ["en"] = "Dimensional Ripper - Everlook" },
    [78] = { [1] = "Легенда про Сталвана", [2] = "Я знаю когось, хто, можливо, зможе тобі допомогти. Коли я був на чолі стражі Штормовія, ми часто відпочивали в таверні «Багряний Ворон» в Темнодолі. Тамтешній корчмар, Сміттс, був неабияким знавцем місцевої історії. Покажи йому цю сторінку і послухай, що він скаже.", [3] = "Віднесіть вицвілу сторінку щоденника господарю таверни Сміттсу.", [4] = "Тебе прислав маршал Знесилій? Що ж ти відразу не {стать:сказав:сказала}?\n\nЕх, старий Знесилій. Бідолаха скоро зовсім осліпне. Так чи інакше, показуй, що у тебе там.", [5] = "Присягаюсь Світлом! Ще б пак, я впізнаю цей почерк.", ["en"] = "The Legend of Stalvan", ["tasks"] = { ["A Faded Journal Page"] = "вицвіла сторінка щоденника", ["A Faded Journal Page (Provided)"] = "вицвіла сторінка щоденника (видано)" } },
    [781] = { [1] = "Напад на табір Нараче", [2] = "Після ретельного вивчення мапи, ви розумієте, що те, що ви знайшли — плани вождя Щетиношкурих щодо розширеної облоги табору Нараче.\n\nБезсумнівно, вождь Соколиний Вітер міг би скористатися цією інформацією!", [3] = "Принесіть плани нападу Щетиношкурих вождю Соколиному Вітру в табір Нараче.", [4] = "У тебе занепокоєний вигляд, {Ім'я}. Які новини ти {стать:приніс:принесла}?", [5] = "Це дійсно тривожна звістка! Але тепер ми можемо звернутися до наших братів з селища Криваве Копито по допомогу. Ти {стать:зберіг:зберегла} життя безлічі тауренів, {Ім'я}.", ["en"] = "Attack on Camp Narache", ["tasks"] = { ["Bristleback Attack Plans"] = "плани нападу Щетиношкурих", ["Bristleback Attack Plans (Provided)"] = "плани нападу Щетиношкурих (видано)" } },
    [7810] = { [1] = "Майстер арени", [2] = "Напевно, звання майстра арени не так легко здобути! Можливо, варто спитати у пірата, який керує ареною Ґурубаші.", [3] = "Поговоріть з Коротуном Джоном Мітрилом на арені Тернистої долини.", [5] = "Аррр, {стать:дорогенький:дорогенька}! Однієї дрібнички не вистачить, щоб стати майстром арени! Настав час по-справжньому перевірити свою силу.", ["en"] = "Arena Master", ["tasks"] = { ["Arena Master"] = "знак майстра арени" } },
    [78114] = { [1] = "Дика звірина суперечка", [2] = "Бачив, як літають ці Гордокрилі Виверни? Б'юся об заклад, люди заплатили б чималі гроші, щоб побачити, як я роблю сальто на одній з них!\n\nАле вони досить сварливі. Не можу приручити жодного достатньо, щоб їздити верхи, не кажучи вже про високі трюки.\n\nЯ чув, що можна зробити спеціальну паличку, щоб їх заспокоїти. Мабуть, міг би зробити це навіть сам. Все, що мені потрібно, це Гіпнотичний Кристал і Звужена Паличка Дикої Магії.\n\nТепер, я не зовсім впевнений, де їх взяти, але ми можемо обговорити деталі пізніше.", [3] = "Принесіть Гіпнотичний кристал та Звужений жезл Дикої Магії до Джіксо Мадрокет у Кігтевих горах.", [4] = "Пощастило з постачанням?", [5] = "Чудова робота! А тепер час для невеликого польового випробування.", ["en"] = "Wild Wyvern Wrangling" },
    [78121] = { [1] = "Змагання з диким виверном", [2] = "З чарівною паличкою залишилося лише одне. Я приручу собі виверну!\n\nТобі варто піти зі мною, {ім'я}. Ти будеш у першому ряду на моєму новому виступі!", [3] = "Слідкуйте за Джіксо Мадрокетом і спостерігайте, як він приборкує Виверну.", [5] = "Дозвольте сказати вам, {ім'я}, те падіння було боліснішим, ніж здавалося. Я буду в порядку, але не думаю, що старий Джіксо збирається боротися з Виверном.\n\nМожливо, мені варто просто дотримуватися хітів, розумієте? Трюки, як-от перестрибування через ряд із двадцяти гномів на вертольоті. Люди це їдять.\n\nВізьміть чарівну паличку. Вона мені більше не потрібна. І ось це також: маленький бонус за всі ці клопоти.", ["en"] = "Wrangling a Wild Wyvern" },
    [78124] = { [1] = "Альманах Нар'таласа", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Nar'thalas Almanac", ["tasks"] = { ["Nar'thalas Almanac, Vol. 74"] = "Альманах Нар'таласа, том 74" } },
    [78127] = { [1] = "Даларанський дайджест", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "The Dalaran Digest", ["tasks"] = { ["The Dalaran Digest, Vol. 23"] = "Даларанський дайджест, том 23" } },
    [78132] = { [1] = "Шолом Драконівбивці", [4] = "Шолом Драконівбивці колись належав великому полководцю, який загинув у бою. Кажуть, що його змучена душа досі переслідує місце його смерті.", [5] = "Чудова робота, {ім'я}! З цим я зробив ще один крок на шляху до слави.", ["en"] = "Dragonslayer's Helm", ["tasks"] = { ["Dragonslayer's Helm"] = "Шолом Драконівбивці" } },
    [78133] = { [1] = "Щит Драконівбивці", [4] = "Ходять чутки, що щит Драконівбивці належить оркському воєначальнику. Він викрав його під час нальоту на людське поселення.", [5] = "Чудова робота, {ім'я}! З цим я зробив ще один крок на шляху до слави.", ["en"] = "Dragonslayer's Shield", ["tasks"] = { ["Dragonslayer's Shield"] = "Щит Драконівбивці" } },
    [78134] = { [1] = "Спис Драконівбивці", [4] = "Спис Драконівбивці багато разів переходив з рук в руки. Час від часу поширюються чутки про те, що він з'являється на чорному ринку зброї. Можливо, нинішній сумнівний власник списа був би готовий розлучитися з ним; за певну ціну.", [5] = "Чудова робота, {ім'я}! З цим я зробив ще один крок на шляху до слави.", ["en"] = "Dragonslayer's Lance", ["tasks"] = { ["Dragonslayer's Lance"] = "Спис Драконівбивці" } },
    [78142] = { [1] = "Чари та чари", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Bewitchments and Glamours", ["tasks"] = { ["Bewitchments and Glamours"] = "Чари та чари" } },
    [78143] = { [1] = "Таємниці мрійників", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Secrets of the Dreamers", ["tasks"] = { ["Secrets of the Dreamers"] = "Таємниці мрійників" } },
    [78144] = { [1] = "Алонсо, вбивця драконів", [2] = "Час настав, {ім'я}. Я одягнений у обладунки, що личать справжньому Вбивці Драконів! Ви дуже допомогли.\n\nЯ прошу вас супроводжувати мене зараз, як мого почесного зброєносця, і спостерігати, як я раз і назавжди перемагаю великого дракона!", [3] = "Супроводжуйте Алонсо, щоб убити дракона.", [5] = "Я зробив це {ім'я}! Нарешті мій ворог переможений!\n\nО, зіткнення ікла та металу; луски та клинка. Яка небезпека, яке хвилювання! І крізь усе це я постаю чемпіоном.\n\nНе забуваймо також про твій скромний внесок! Без обладунків, які ти здобув, я б точно не переміг диявола.\n\nТи був чудовим зброєносцем, {ім'я}. Можливо, одного дня ти також пройдеш славним шляхом лицаря.", ["en"] = "Alonso the Dragonslayer" },
    [78145] = { [1] = "Посібник з арканічних систем", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Arcanic Systems Manual", ["tasks"] = { ["Arcanic Systems Manual"] = "Посібник з арканічних систем" } },
    [78146] = { [1] = "Сувої Гоаза", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Goaz Scrolls", ["tasks"] = { ["Goaz Scrolls"] = "Сувої Гоаза" } },
    [78147] = { [1] = "Злочини проти анатомії", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Crimes Against Anatomy", ["tasks"] = { ["Crimes Against Anatomy"] = "Злочини проти анатомії" } },
    [78148] = { [1] = "Руни Королів-Чаклунів", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Runes of the Sorceror-Kings", ["tasks"] = { ["Runes of the Sorcerer-Kings"] = "Руни Королів-Чаклунів" } },
    [78149] = { [1] = "Гнів Країни", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Fury of the Land", ["tasks"] = { ["Fury of the Land"] = "Гнів Країни" } },
    [78150] = { [1] = "Друг бібліотеки", [5] = "Завдяки вашим пожертвам бібліотека процвітає.\n\nБудь ласка, візьміть це.", ["en"] = "Friend of the Library" },
    [78229] = { [1] = "Суд над совами", [2] = "Дай мені подивитися на той символ, який ти носиш, {ім'я}.\n\nСхоже, ти розпочав випробування сов. Це знаменує собою ключовий момент у твоїй подорожі як друїда.\n\nЄ й інші подібні символи; розкидані по всьому Азероту. Щоб їх заробити, ти повинен здійснити великі подвиги як розуму, так і тіла.\n\nОдна сова сидить під великим деревом у Східних Королівствах. Інша знаходиться біля великого дерева тут, у Калімдорі. Ще одна знаходиться в морі; біля узбережжя Гіллсбрада.\n\nЗнайди цих сов, {ім'я}, і принеси мені їхні символи.", [3] = "Принесіть символи трьох сов до Логанаара в Мунглейді.", [4] = "Як проходить твій пробний період, {ім'я}?", [5] = "Я хотів би привітати тебе, {ім'я}. Те, чого ти досяг, – немалий подвиг.\n\nПройти випробування сов – це продемонструвати узгодженість з усіма аспектами твого друїдського покликання.\n\nВізьми цю руну як знак твого досягнення. Сподіваюся, вона добре послужить тобі як охоронцю Смарагдового Сну.", ["en"] = "Trial of The Owls" },
    [78261] = { [1] = "Ріг Кселтоса", [2] = "<Записка лежить у скрині>\n\nПривіт, {ім'я}.\n\nЯ бажаю знайти скарб, відомий як Ріг Кселтоса, який знаходиться десь у Твердині Тіньового Ікла.\n\nДля того, щоб потрапити всередину фортеці, зазвичай потрібне підкріплення. Однак для цієї роботи надзвичайно важливо залишатися непомітним.\n\nТи маєш йти сам.\n\nУ мене є контакт на ім'я Вінікс у Кігтевих Горах. Він має допомогти тобі пройти через ворота внутрішнього двору. Решта залежить від тебе.\n\nПоверни ріг сюди, і твій платіж буде надіслано невдовзі після цього.\n\n- C", [3] = "Знайдіть Ріг Кселтоса всередині Тіньової Тіні. Потім поверніть його до схованки C біля села Пірвуд. Ви повинні виконати завдання самостійно.", [4] = "<Скриня стоїть порожня.>", [5] = "<Ви кладете Ріг Кселтоса у скриню>", ["en"] = "The Horn of Xelthos", ["tasks"] = { ["Horn of Xelthos"] = "Ріг Кселтоса" } },
    [78265] = { [1] = "Риб'ячий жир", [4] = "Мені знадобиться риб'ячий жир — і багато його!", [5] = "Щиро дякую, {ім'я}. Я використовую це з користю.", ["en"] = "Fish Oil" },
    [78266] = { [1] = "Темний залізний ордонанс", [4] = "Мені знадобиться якийсь Постанова Темного Заліза. Де ти збираєшся знайти дворфів Темного Заліза? Це твоя проблема!", [5] = "Щиро дякую, {ім'я}. Я використовую це з користю.", ["en"] = "Dark Iron Ordinance" },
    [78267] = { [1] = "Турбокомпресори подрібнювача", [4] = "Мені знадобляться деякі турбокомпресори подрібнювача від ТзНБ \"Авантюра\". Вони щільно з'єднані з системами шредера, тому вам знадобиться спеціальне обладнання для їх ремонту.\n\nНі, у мене немає такого обладнання.", [5] = "Щиро дякую, {ім'я}. Я використовую це з користю.", ["en"] = "Shredder Turbochargers" },
    [78270] = { [1] = "Гоблінські відмички", [2] = "<Записка лежить у скрині>\n\nЗнову вітаю, {ім'я}.\n\nЯ прагну скарб, відомий як Ріг Кселтоса, який знаходиться десь у Твердині Тіньового Ікла.\n\nДля того, щоб потрапити всередину фортеці, зазвичай потрібне підкріплення. Однак для цієї роботи надзвичайно важливо залишатися непомітним.\n\nВи повинні йти самі.\n\nУ мене є контакт на ім'я Вінікс у Кігтевих Горах. Він має допомогти вам пройти через ворота внутрішнього двору. Решта залежить від вас.\n\nПоверніть ріг сюди, і ваш платіж буде надіслано невдовзі після цього.\n\n- C", [3] = "Знайдіть Ріг Кселтоса всередині Тіньової Тіні. Потім поверніть його до схованки C біля села Пірвуд.", [4] = "Ти казав, що вриваєшся в Тіньовий Ікло... сам? У тебе є сміливість!\n\nЯ можу забезпечити тебе вибухівкою, щоб пройти повз ворота, але мені знадобиться робоче замовлення, щоб це виглядало законно в книгах. Ймовірно, хтось із працівників тут має таке. Ймовірно, хтось, хто багато займається ремонтом або будівництвом.", [5] = "Чудова робота, {ім'я}. Гадаю, це було легко для людини у вашій сфері діяльності.\n\nЯк і обіцяно, ось результат.", ["en"] = "Goblin Lockpicks", ["tasks"] = { ["Venture Co. Work Order"] = "Замовлення на виконання робіт від ТзНБ \"Авантюра\"" } },
    [78307] = { [1] = "Ріг Кселтоса", [2] = "Опис", [3] = "Журнал", [5] = "<Записка лежить у скрині>\n\nЗа {ім'я}. Ще побачимося.\n\n- C", ["en"] = "The Horn of Xelthos" },
    [7838] = { [1] = "Гросмейстер арени", [4] = "Стій, салаго! Принеси-но мені 12 знаків майстра арени та отримай звання гросмейстера арени Ґурубаші! Арррр!", [5] = "Ти {стать:пролив:пролила} вдосталь крові на арені, тож я радий оголосити тебе гросмейстером арени!", ["en"] = "Arena Grandmaster", ["tasks"] = { ["Arena Master"] = "знак майстра арени", ["Arena Master (Provided)"] = "знак майстра арени (видано)" } },
    [7841] = { [1] = "Послання Дикому Молоту", [2] = "Дикий Молот водиться з нашими ворогами та укладає з ними союзи. Цього разу вони сплуталися з вищими ельфами.\n\n<Отон спльовує.>\n\nНам потрібно послати зрозуміле повідомлення Дикому Молоту — повідомлення з крові наших ворогів. Вбивай кожного високодільного вищого ельфа, якого зустрінеш — нехай їхні тіла будуть попередженням.\n\nЗ тролями не варто жартувати!", [3] = "Отон Моджі'ко з селища Сколотий Бивень у Внутрішніх землях хоче, щоб ви вбили 15 високодільних вістових, 15 високодільних розвідників, 15 високодільних стрільців і 15 високодільних слідопитів. Поверніться до нього, коли виконаєте завдання.\n\nВи можете знайти високодільних вищих ельфів в оселі Квел'Даніл на північному заході Внутрішніх земель.", [4] = "Ти надто {стать:чистий:чиста}. Ти маєш зануриться в бруд і кров ворогів.", [5] = "Схоже, що Сколотий Бивень теж укладає нові союзи! Ти молодець.", ["en"] = "Message to the Wildhammer", ["tasks"] = { ["Highvale Marksman"] = "високодільний стрілець", ["Highvale Marksman slain"] = "високодільний стрілець: убито", ["Highvale Outrunner"] = "високодільний вістовий", ["Highvale Outrunner slain"] = "високодільний вістовий: убито", ["Highvale Ranger"] = "високодільний слідопит", ["Highvale Ranger slain"] = "високодільний слідопит: убито", ["Highvale Scout"] = "високодільний розвідник", ["Highvale Scout slain"] = "високодільний розвідник: убито" } },
    [7848] = { [1] = "Спорідненість з ядром", [2] = "Розломи виникають, рвуться та руйнуються навколо нас, {раса:к}. Навіть за два кроки від того місця, де ти зараз стоїш, є розлом, який веде в надра Чорноскельної гори, до самої пащі Володара вогню.\n\n{стать:Здивований:Здивована}? Шкода... смертні не можуть збагнути того, чого вони не можуть побачити, торкнутися чи відчути.\n\nЗапевняю тебе, ти стоїш просто поруч із порталом і цілком можеш ним скористатися.\n\nБачу, я зацікавив тебе. Споріднення з порталом дуже просте. Вирушай в Чорноскельні надра та добудь фрагмент ядра. Принеси його мені і я зможу споріднити твою сутність з порталом.", [3] = "Відправляйтеся до Палаючого Ядра через портал в Чорноскельних надрах та добудьте фрагмент ядра. Поверніться з фрагментом ядра до Лотоса Побудника Розлому в Чорноскельну гору.", [4] = "Ти маєш споріднити свою душу з Палаючим Ядром, щоб отримати доступ до порталу.", [5] = "Тепер я можу перенести тебе до Палаючого Ядра. Ти лиш скажи коли.", ["en"] = "Attunement to the Core", ["tasks"] = { ["Core Fragment"] = "фрагмент ядра", ["Core Fragment (Provided)"] = "фрагмент ядра (видано)" } },
    [785] = { [1] = "Стратегічний альянс", [2] = "Тралл — наймудріший і найблагородніший лідер. Його наполегливість на полі бою зрівняється лише з його дипломатичним тактом.\n\nТролі Темного Списа виявилися безцінними союзниками орків. З вірності та честі ми уклали з ними пакт захисту.\n\nВождь надіслав наказ переконатися, що наші друзі Темного Списа в селі Сен'джін не перебувають під жодною прямою загрозою. Один з їхніх найдовіреніших розвідників, Лар Пролтуск, пильно стежить за їхнім західним флангом.\n\nЗнайдіть Лара та допоможіть йому за потреби.", ["en"] = "A Strategic Alliance" },
    [78611] = { [1] = "Заскочена партія", [5] = "У посилці бракує деяких предметів, але вона все одно буде корисною. Дякую, {ім'я}.", ["en"] = "A Waylaid Shipment" },
    [78612] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment", ["tasks"] = { ["Supply Shipment"] = "Відвантаження постачання" } },
    [78676] = { [1] = "Око Бхоски", [2] = "<Записка лежить у скрині>\n\nРадий твоєму поверненню, {ім'я}.\n\nНайновіший об'єкт мого бажання — артефакт, відомий як Око Бхоски. Мої джерела повідомляють, що око знаходиться десь у Багряному монастирі. Як і у випадку з Тінню Тіньової Ікло, ти повинен проникнути до монастиря сам.\n\nМожливо, тобі варто знайти маскування, перш ніж заходити всередину. Це трохи полегшить пересування. Я впевнений, що ти зможеш щось знайти на території монастиря.\n\nПоверни око сюди, і оплату буде доставлено, як і раніше.\n\n- C", [3] = "Знайдіть Око Бхоски всередині Багряного Монастиря. Потім поверніть його до схованки C біля села Пірвуд. Ви повинні виконати завдання самостійно.", [4] = "<Скриня стоїть порожня.>", [5] = "<Ви кладете Око Бхоски в скриню>", ["en"] = "The Eye of Bhossca" },
    [78680] = { [1] = "Чутки ширяють", [2] = "Шепіт у тінях говорить про зброю, що містить душу великої демонічної істоти. Менші демони, такі як Соран'рук, це одне, але набагато могутніші сутності, зв'язані як покарання за свої невдачі, пропонують неймовірну силу.\n\nЦя зброя була втрачена багато років тому, розбита під час Третьої війни.\n\nНещодавно ці чутки свідчили про те, що маги, які втручаються в темну магію поза їхнім розумінням, забрали фрагменти зброї, але вони не можуть розблокувати сили, не переробляючи її.", [3] = "Про місцезнаходження цих фрагментів розбитої зброї відомо небагато, окрім того, що обидва вони знаходяться у володінні колись великих магів, які утримуються у важливих вежах. Кажуть, що один знаходиться тут, на півночі Калімдора, а інший — у самому серці Східних Королівств.\n\nПеревірте, чи правдиві чутки... Знайдіть дві відсутні половинки цієї зброї та принесіть їх мені.", [4] = "Досі немає ознак фрагментів зброї? Мабуть, я відправив тебе з дурним дорученням.", [5] = "Ще багато чого потрібно зробити, перш ніж я зможу реформувати зброю такої сили. Ми почали цей шлях, і шляху назад немає.", ["en"] = "Rumors Abound" },
    [78681] = { [1] = "Закляття", [2] = "Здається, демон Дес'Алтек вирвався зі своєї в'язниці, але він все ще прив'язаний до неї, як в'язень до своєї камери. Ми повинні викликати демона, щоб знову захопити його душу.\n\nНа півночі, в Ясеневому Долині, де падали великі демони, на хребті є місце, яке колись використовувалося Легіоном для жертвоприношень. Земля назавжди понівечена звірствами, що тут відбувалися, але якщо ми зможемо зібрати Кров Легіону з демонів, які досі кишать цією землею... це ключ до успіху.", [3] = "Зберіть 10 Крові Легіону та виконайте ритуал, щоб викликати Дес'Альтека та знову захопити його душу в пастку.", [4] = "Зробіть жертву крові.", [5] = "Використай Темний Ритуальний Камінь, щоб розпочати Темний Ритуал. Тепер шляху назад немає...", ["en"] = "The Conjuring" },
    [78684] = { [1] = "Таємничий мандрівник", [2] = "Що? Де я? Як... як я сюди потрапив?\n\n<Чоловік перед вами хитається, ніби його захворіла морська хвороба. Його очі розширюються, руки тремтять, і ви дивитеся одне на одного в моменті спільного збентеження.>\n\nА... Бачу, товариш-чаклун. Можливо, ми обговоримо, що призвело до цієї серії подій, і, можливо, зможемо з'ясувати, що пішло не так?\n\n<Не знаючи, що робити далі, ви пропонуєте їм повернутися, щоб поговорити з Доаном Карханом.>", [3] = "Зустріньтеся з Доаном Карханом та Таємничим Мандрівником у Степах.", [5] = "Цікаво, справді... Я відправив тебе вбити демона; ніколи в найсміливішій уяві я б не подумав, що ти повернешся з другом.", ["en"] = "Mysterious Traveler" },
    [7869] = { [1] = "тестовий квест - не використовувати", ["en"] = "test quest - do not use" },
    [78699] = { [1] = "Око Бхоски", [2] = "Опис", [3] = "Журнал", [5] = "<Записка лежить у скрині>\n\nДля {ім'я}. Я буду стежити за тобою.\n\n- C", ["en"] = "The Eye of Bhossca" },
    [787] = { [1] = "Нова Орда", [2] = "Тром'ка, {клас:к}. Я Ейтріґ, призначений Траллом котролювати навчання рекрутів.\n\nОрда вже не така як була раніше. Був час, коли я покинув Орду, зневірений зростаючою могутністю і впливом Палаючого Легіону. Перебуваючи у вигнанні, група людей мене схопила. Але воєвождь врятував мене з полону. Я повернувся, почувши його бачення Орди, вільної від демонічного впливу під керівництвом шаманів.\n\nҐорнек має подальші інструкції для тебе.", [3] = "Відрапортуйте Ґорнеку в Лігві.", ["en"] = "The New Horde" },
    [7870] = { [1] = "тестовий квест2 - не використовувати", ["en"] = "test quest2 - do not use" },
    [78702] = { [1] = "Расель Андер", [5] = "Расель був другом... Тим, кого я думав, що втратив давно, з іншого часу... Ми були молодими учнями тоді... Багато що змінилося.\n\nРезультатом ритуалу могла бути невдача, але я вірю, що ми все ще можемо переробити зброю.\n\nНам з Раселем є що обговорити, разом ми розробимо план. Я дам звістку, як тільки дізнаємося, як рухатися далі.\n\nА тим часом візьми це. Здається, це те, що тебе може зацікавити.", ["en"] = "Raszel Ander" },
    [7871] = { [1] = "Знищити загарбників!", [2] = "За цим тунелем ти знайдеш поле запеклих битв, {стать:юний:юна} {клас:к}. Орда продовжує нищити наш священний ліс, вирубуючи вічнозелені крони для живлення своїх військових машин.\n\nПрямуй в тіснину Пісні Війни та захисти фортецю Срібнокрилих. Відбий напади ординських загарбників!\n\nЗроби це — і отримаєш талісман заслуг. Принеси мені такий талісман, {ім'я:к}, і я винагороджу тебе.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Орду, отримайте відзнаку честі тіснини Пісні Війни та принесіть її стражниці Далепісні в Срібнокрилі хащі.", [4] = "Тобі вже вдалось захистити фортецю Срібнокрилих в тіснині Пісні Війни?", [5] = "Ти {стать:довів:довела} свою цінність для наших зусиль в тіснині Пісні Війни. Продовжуй допомагати та принеси мені більше талісманів заслуг. Зроби це, і заслужиш нашу довіру.", ["en"] = "Vanquish the Invaders!", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [7872] = { [1] = "Знищити загарбників!", [2] = "За цим тунелем ти знайдеш поле запеклих битв, {стать:юний:юна} {клас:к}. Орда продовжує нищити наш священний ліс, вирубуючи вічнозелені крони для живлення своїх військових машин.\n\nПрямуй в тіснину Пісні Війни та захисти фортецю Срібнокрилих. Відбий напади ординських загарбників!\n\nЗроби це — і отримаєш талісман заслуг. Принеси мені такий талісман, {ім'я:к}, і я винагороджу тебе.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Орду, отримайте відзнаку честі тіснини Пісні Війни та принесіть її стражниці Далепісні в Срібнокрилі хащі.", [4] = "Тобі вже вдалось захистити фортецю Срібнокрилих в тіснині Пісні Війни?", [5] = "Ти {стать:довів:довела} свою цінність для наших зусиль в тіснині Пісні Війни. Продовжуй допомагати та принеси мені більше талісманів заслуг. Зроби це, і заслужиш нашу довіру.", ["en"] = "Vanquish the Invaders!", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [7873] = { [1] = "Знищити загарбників!", [2] = "За цим тунелем ти знайдеш поле запеклих битв, {стать:юний:юна} {клас:к}. Орда продовжує нищити наш священний ліс, вирубуючи вічнозелені крони для живлення своїх військових машин.\n\nПрямуй в тіснину Пісні Війни та захисти фортецю Срібнокрилих. Відбий напади ординських загарбників!\n\nЗроби це — і отримаєш талісман заслуг. Принеси мені такий талісман, {ім'я:к}, і я винагороджу тебе.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Орду, отримайте відзнаку честі тіснини Пісні Війни та принесіть її стражниці Далепісні в Срібнокрилі хащі.", [4] = "Тобі вже вдалось захистити фортецю Срібнокрилих в тіснині Пісні Війни?", [5] = "Ти {стать:довів:довела} свою цінність для наших зусиль в тіснині Пісні Війни. Продовжуй допомагати та принеси мені більше талісманів заслуг. Зроби це, і заслужиш нашу довіру.", ["en"] = "Vanquish the Invaders!", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [7874] = { [1] = "Розгромити Срібнокрилих загарбників", [2] = "Хащі Ясенедолу підкоряться могутності Орди, {раса:к}. Що б не робили Срібнокрилі, їм не впоратися з нашим натиском. Калімдор належить Орді. Як вони сміють заважати нам збирати те, що належить нам по праву!\n\nНехай гордість наповнює твої груди, коли ти зломиш їхні жалюгідні спроби зупинити нас. Розгроми Срібнокрилих стражів і заслужи відзнаку честі тіснини Пісні Війни. Повертайся до мене з такою відзнакою, {ім'я:к}, і отримаєш винагороду.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Альянс, отримайте відзнаку честі тіснини Пісні Війни та принесіть її капітану Череподробу в табір Мор'шан.", [4] = "Кров наших ворогів — відзнака честі. Вже маєш таку?", [5] = "<Капітан Череподроб тріумфально ричить.>\n\nСкільки ще вони зможуть витримати? Скільки ще покидьків Альянсу має загинути від рук Орди, щоб вони відступили? Тільки час покаже, {раса:к}.", ["en"] = "Quell the Silverwing Usurpers", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [7875] = { [1] = "Розгромити Срібнокрилих загарбників", [2] = "Хащі Ясенедолу підкоряться могутності Орди, {раса:к}. Що б не робили Срібнокрилі, їм не впоратися з нашим натиском. Калімдор належить Орді. Як вони сміють заважати нам збирати те, що належить нам по праву!\n\nНехай гордість наповнює твої груди, коли ти зломиш їхні жалюгідні спроби зупинити нас. Розгроми Срібнокрилих стражів і заслужи відзнаку честі тіснини Пісні Війни. Повертайся до мене з такою відзнакою, {ім'я:к}, і отримаєш винагороду.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Альянс, отримайте відзнаку честі тіснини Пісні Війни та принесіть її капітану Череподробу в табір Мор'шан.", [4] = "Кров наших ворогів — відзнака честі. Вже маєш таку?", [5] = "<Капітан Череподроб тріумфально ричить.>\n\nСкільки ще вони зможуть витримати? Скільки ще покидьків Альянсу має загинути від рук Орди, щоб вони відступили? Тільки час покаже, {раса:к}.", ["en"] = "Quell the Silverwing Usurpers", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [7876] = { [1] = "Розгромити Срібнокрилих загарбників", [2] = "Хащі Ясенедолу підкоряться могутності Орди, {раса:к}. Що б не робили Срібнокрилі, їм не впоратися з нашим натиском. Калімдор належить Орді. Як вони сміють заважати нам збирати те, що належить нам по праву!\n\nНехай гордість наповнює твої груди, коли ти зломиш їхні жалюгідні спроби зупинити нас. Розгроми Срібнокрилих стражів і заслужи відзнаку честі тіснини Пісні Війни. Повертайся до мене з такою відзнакою, {ім'я:к}, і отримаєш винагороду.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Альянс, отримайте відзнаку честі тіснини Пісні Війни та принесіть її капітану Череподробу в табір Мор'шан.", [4] = "Кров наших ворогів — відзнака честі. Вже маєш таку?", [5] = "<Капітан Череподроб тріумфально ричить.>\n\nСкільки ще вони зможуть витримати? Скільки ще покидьків Альянсу має загинути від рук Орди, щоб вони відступили? Тільки час покаже, {раса:к}.", ["en"] = "Quell the Silverwing Usurpers", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [7877] = { [1] = "Скарб Шен'дралар", [2] = "В Атенеумі, під сходами, захована старовинна скриня — відшукай її. Візьми з неї те, що тобі сподобається.", [3] = "Поверніться в Атенеум і знайдіть скарб Шен'дралар. Отримайте свою нагороду!", [5] = "Ви відкриваєте скриню і знаходите...", ["en"] = "The Treasure of the Shen'dralar" },
    [7881] = { [1] = "Карнавальні чоботи", [4] = "Ми на ярмарку Темного місяця багато ходимо. Від одного майданчика до іншого... насправді, ти ніколи не побачиш, як ми сидимо, тут купа роботи! Тож не дивно, що ми зношуємо досить багато взуття! Нам потрібні міцні та стильні черевики, і тиснені шкіряні чоботи чудово підходять.\n\nТи! Ти {стать:шкірник:шкірниця}, тож зроби мені тиснені шкіряні чоботи, а я дам тобі купон ярмарку Темного місяця за роботу.", [5] = "Спасибі, {ім'я}. Вони досить добре зроблені. Майстерність найвищого ґатунку! Ось купон ярмарку Темного місяця... Насолоджуйтесь, {стать:пане:пані}.", ["en"] = "Carnival Boots", ["tasks"] = { ["Embossed Leather Boots"] = "тиснені шкіряні чоботи", ["Embossed Leather Boots (Provided)"] = "тиснені шкіряні чоботи (видано)" } },
    [7882] = { [1] = "Карнавальні шкіряні куртки", [4] = "Наші працівники ярмарку роблять більше, ніж просто підмітають сміття та забивають колони! Вони також охороняють ярмарок у дорозі, і для цього їм завжди потрібні міцні шкіряні куртки.\n\nЯкщо ти зробиш укріплені шкіряні обладунки й принесеш їх мені, я подбаю про те, щоб вони потрапили до працівників. А ще я дам тобі кілька купонів ярмарку Темного місяця в обмін.", [5] = "А, ти {стать:приніс:принесла} куртки. Чудово. Дозволь запитати, шкіру якої тварини ти {стать:використовував:використовувала} для їх виготовлення? Шовна робота виконана дуже добре, а сама шкіра має вишукану текстуру. З впевненістю можу сказати, що ти — {стать:справжній майстер:справжня майстриня}!\n\nДякую, {ім'я}, і ось твої купони.", ["en"] = "Carnival Jerkins", ["tasks"] = { ["Toughened Leather Armor"] = "укріплений шкіряний обладунок", ["Toughened Leather Armor (Provided)"] = "укріплений шкіряний обладунок (видано)" } },
    [78823] = { [1] = "Жах пустельного неба", [2] = "Малюнок складений грубими, широкими штрихами та, здається, зображує великого хижого птаха. Незважаючи на просту композицію, художник явно дивився на цю істоту зі страхом і благоговінням. Експерт з великої дичини, ймовірно, міг би розповісти вам більше.", [3] = "Принесіть примітивний малюнок Хемету Несінґварі в Тернисту Долину.", [5] = "Ну що ж. Це, безумовно, цікаво...", ["en"] = "Terror of the Desert Skies" },
    [7883] = { [1] = "Найбільший у світі гном!", [4] = "Єбб Небіжило прагне додати більше талантів у своє шоу, і він шукає найбільших у світі гномів. Чи знаєш ти гномів значного розміру?\n\nДо того, як він знайде такого гнома, він хоче підготувати костюм. Я думаю, що варварська портупея була б гарною основою для костюма. Зможеш зробити кілька таких портупей і принести їх мені? Зробиш це, і я дам тобі багато купонів ярмарку Темного місяця...", [5] = "Ох, а вона справді велика!! Я не можу уявити, як гнома таких розмірів, але не хвилюйся — якщо гном, якого ми знайдемо, буде надто малим, я зможу трохи підшити костюм.\n\nДуже дякую, {ім'я}. Ось купони, які я тобі обіцяв.", ["en"] = "The World's Largest Gnome!", ["tasks"] = { ["Barbaric Harness"] = "варварська портупея", ["Barbaric Harness (Provided)"] = "варварська портупея (видано)" } },
    [78830] = { [1] = "Жах пустельного неба", [2] = "Цей малюнок нагадує мені історію, яку я чув під час іншої експедиції, не так давно. Мені розповідали про великого птаха, Гарріка, який панує над Безплідними Землями як головний хижак.\n\nВостаннє його бачили на північний схід від табору Кагг. Можливо, його гніздо десь неподалік?\n\nВам знадобиться жива наживка, щоб виманити її. Я позичу вам клітку, щоб виловити трохи. Дрібні дикі тварини рідко зустрічаються в Безплідних Землях, тому вам доведеться знайти наживку деінде.\n\nПеро з Гарріка було б чудовим призом. Ви точно стали б предметом розмов у таборі.", [3] = "Отримайте Багряне перо-трофей у Гарріка в Безплідних землях. Потім поверніться до Хемета Несінґварі в Тернистій Долині.\n\nНаданий предмет:", [4] = "Як полювання? Пташка тебе точно не перегнала!", [5] = "Ось тобі й почесний головний убір! Чудово зроблено, {ім'я}.\n\nМожеш трохи тут відпочити, якщо хочеш. Я впевнений, що твій похід пустелею був важким.", ["en"] = "Terror of the Desert Skies", ["tasks"] = { ["Empty Bait Cage"] = "Порожня клітка для приманки" } },
    [7884] = { [1] = "Хлопчик-кроколіск і бородатий мурлок", [4] = "Єбб працює над іншими атракціонами для свого зоопарку, в тому числі над болотистим вольєром для хлопчика, якого виростили кроколіски, і, можливо, для мурлока. Нам знадобляться гарні, водонепроникні поножі, щоб не промокнути під час встановлення та демонтажу атракціонів. Для цієї роботи, певно, підійдуть поножі з черепашачої луски.\n\n{ім'я}, ти можеш пошити такі поножі? Якщо зможеш, то товстий стос купонів ярмарку Темного місяця чекає на тебе...", [5] = "Чудово, ти їх {стать:зробив:зробила}! Вони чудово підійдуть... Сподіваюся, що не мені доведеться чистити клітку кроколісків, коли прийде час. Ці звірі досить жорстокі.\n\nОсь твої купони, {ім'я}. Насолоджуйся ними, і приємного перебування на ярмарку Темного місяця!", ["en"] = "Crocolisk Boy and the Bearded Murloc", ["tasks"] = { ["Turtle Scale Leggings"] = "поножі з черепашачої луски", ["Turtle Scale Leggings (Provided)"] = "поножі з черепашачої луски (видано)" } },
    [7885] = { [1] = "Накладки для обладунків", [4] = "Можливо, ти цього не усвідомлюєш, але утримувати мандрівний ярмарок дорого! Все зношується так швидко, що дивно, як нам вдається отримувати прибуток.\n\nЧерез усі ці витрати ми завжди шукаємо способи підтримувати наше обладнання якомога дешевше. Наші намети, наприклад, регулярно рвуться, але я помітив, що шкіряні накладки для обладунків чудово підходять і для латок. Можеш знайти й привезти мені кілька комплектів? Це заощадить нам купу грошей! Зроби це, і я дам тобі жменю купонів ярмарку Темного місяця...", [5] = "Чудово! Це має спрацювати! Я щойно помітив дірку в наметі, і одна з цих накладок — якраз те, що мені потрібно, щоб її залатати!\n\nДуже дякую, {ім'я}. Ці накладки допоможуть нам заощадити купу грошей на ремонті. Ось твої купони — ти на них заслуговуєш!", ["en"] = "Armor Kits", ["tasks"] = { ["Rugged Armor Kit"] = "накладки з міцної шкіри", ["Rugged Armor Kit (Provided)"] = "накладки з міцної шкіри (видано)" } },
    [7886] = { [1] = "Талісмани заслуг", [4] = "Ти {стать:отримав:отримала} талісман заслуги Срібнокрилих за виконання минулого завдання. Поговори зі мною знову, щоб отримати винагороду.", [5] = "Дякую, {ім'я:к}. Звістки про твої подвиги в тіснині Пісні Війни розійшлися по всьому Ясенедолу.", ["en"] = "Talismans of Merit", ["tasks"] = { ["Silverwing Talisman of Merit"] = "талісман заслуги Срібнокрилих", ["Silverwing Talisman of Merit (Provided)"] = "талісман заслуги Срібнокрилих (видано)" } },
    [7887] = { [1] = "Талісмани заслуг", [4] = "Ти {стать:отримав:отримала} талісман заслуги Срібнокрилих за виконання минулого завдання. Поговори зі мною знову, щоб отримати винагороду.", [5] = "Дякую, {ім'я:к}. Звістки про твої подвиги в тіснині Пісні Війни розійшлися по всьому Ясенедолу.", ["en"] = "Talismans of Merit", ["tasks"] = { ["Silverwing Talisman of Merit"] = "талісман заслуги Срібнокрилих", ["Silverwing Talisman of Merit (Provided)"] = "талісман заслуги Срібнокрилих (видано)" } },
    [78872] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment" },
    [7888] = { [1] = "Талісмани заслуг", [4] = "Ти {стать:отримав:отримала} талісман заслуги Срібнокрилих за виконання минулого завдання. Поговори зі мною знову, щоб отримати винагороду.", [5] = "Дякую, {ім'я:к}. Звістки про твої подвиги в тіснині Пісні Війни розійшлися по всьому Ясенедолу.", ["en"] = "Talismans of Merit", ["tasks"] = { ["Silverwing Talisman of Merit"] = "талісман заслуги Срібнокрилих", ["Silverwing Talisman of Merit (Provided)"] = "талісман заслуги Срібнокрилих (видано)" } },
    [7889] = { [1] = "Шорстке грузило", [4] = "Щоб бути найсильнішою жінкою на світі, потрібно багато працювати! Моя гиря стає занадто легкою, і якщо я хочу залишатися у формі, то мені знадобиться більше ваги!\n\nЯк думаєш, чи зможеш ти принести мені кілька грузил? Якщо принесеш, то я дам тобі купон ярмарку Темного місяця.", [5] = "Чудово! Вони чудово підійдуть! Вони не надто важкі, але й не надто легкі. Ідеально підходять для нарощування м'язової маси!\n\nДуже дякую, {ім'я}. Ось твій купон ярмарку Темного місяця!", ["en"] = "Coarse Weightstone", ["tasks"] = { ["Coarse Weightstone"] = "шорстке грузило", ["Coarse Weightstone (Provided)"] = "шорстке грузило (видано)" } },
    [7890] = { [1] = "Важкий шліфувальний камінь", [4] = "Щоб мої тренування були більш продуктивними, я прилаштовую до обох кінців палиці важкі шліфувальні камені, а потім підіймаю це все над головою. Це нелегко, але звання найсильнішої жінки у світі інакше не заслужити!\n\nМожеш мені допомогти? Мені потрібні точильні камені — принеси мені кілька, і я обміняю їх на купони ярмарку Темного місяця.", [5] = "Ти {стать:приніс:принесла} камені! І вони важкі! Я вже відчуваю, як ростуть мої м'язи. Спасибі, {ім'я}!\n\nОсь, візьми ці купони, і не їж багато солодкого на ярмарку. {стать:Такий великий і сильний:Такий велика і сильна} {клас}, як ти, {стать:повинен:повинна} підтримувати себе в формі!", ["en"] = "Heavy Grinding Stone", ["tasks"] = { ["Heavy Grinding Stone"] = "важкий шліфувальний камінь", ["Heavy Grinding Stone (Provided)"] = "важкий шліфувальний камінь (видано)" } },
    [78909] = { [1] = "Талісман Зміщення Шкали", [2] = "Мені знадобиться... номінальна кількість матеріалів для талісмана.\n\n<Н'ора сором'язливо тобі посміхається>", [3] = "Принесіть Н'орі Еніхарт такі матеріали разом із жменею мінливих лусочок, щоб завершити талісман: сумку Дивного пилу, п'ять Великої магічної сутності, 2 малих мерехтливих осколки та п'ять золотих монет.", [4] = "Зізнаюся, я не дуже гарний чарівник, але, гадаю, я досить добре розумію цей процес. Принаймні, в принципі.", [5] = "Бажаю тобі успіхів у твоїх пригодах і сподіваюся, що ти знову знайдеш дорогу до мене, якщо зіткнешся з такими ж дивовижними відкриттями!", ["en"] = "Shifting Scale Talisman" },
    [7891] = { [1] = "Зелені залізні браслети", [4] = "Я працюю над новим костюмом, щоб у мене був власний стенд як у найсильнішої жінки у світі! Зараз я шукаю браслети, що пасуватимуть до нього. Вони не мають сильно прикривати тіло, тому що народ має бачити мої м'язи, але я все одно хочу додати невеликий акцент, розумієш?\n\nЯк щодо зелених залізних браслетів, {ім'я}? Зможеш зробити їх для мене? Якщо можеш, то я маю для тебе цілу купу купонів ярмарку Темного місяця.", [5] = "Так! Це саме те, що мені потрібно! Такий чудовий колір, і вони все ще залишають мої руки оголеними так, щоб підкреслити їхню силу! Ідеально!\n\nТримай, {ім'я}. Ось твої купони — насолоджуйся ярмарком!", ["en"] = "Green Iron Bracers", ["tasks"] = { ["Green Iron Bracers"] = "зелені залізні браслети", ["Green Iron Bracers (Provided)"] = "зелені залізні браслети (видано)" } },
    [78914] = { [1] = "Посудина душі", [2] = "Інженери-гобліни намагалися створити синтетичний Камінь Душі, але їхні методи були, м'яко кажучи, грубими. Незважаючи на їхній недолік, вони на правильному шляху.\n\nЯ чув, що гобліни обманом змусили групу торговців купити права на рецепт. Навряд чи вони знають, що Посудина Душі сама по собі не має магічних властивостей. Напевно, хтось буде зацікавлений розлучитися зі зразком, якщо матиме достатньо грошей.", [3] = "Тепер, коли у нас є спосіб послабити демона, нам потрібна посудина, щоб зв'язати його всередині. Палаючий Клинок захопив стародавні ельфійські руїни в південній Пустощі, використовуючи їх як плацдарм для викликання демонів до Азероту.\n\nЯк тільки ви знайдете Посудину Душі, зустріньте нас у Пустощі, де ми завершимо ритуал.", [4] = "З Гілкою Тіней та Посудиною Душі ми будемо готові розпочати ритуал.", [5] = "А, так... так. Це саме те, що нам потрібно.", ["en"] = "Soul Vessel" },
    [7892] = { [1] = "Велика чорна булава", [4] = "Для мого виступу як найсильнішої жінки у світі, я планую приймати предмети від глядачів і розбивати їх великою чорною булавою!\n\nЧи можеш ти зробити велику чорну булаву для мене, {ім'я}?", [5] = "Чудово! Ця булава має велику, важку головку. Б'юся об заклад, я можу розбити нею все, що завгодно. Сподіваюся лиш, що вона не зламається.\n\nОсь твої купони, {ім'я}. Насолоджуйся ярмарком!", ["en"] = "Big Black Mace", ["tasks"] = { ["Big Black Mace"] = "велика чорна булава", ["Big Black Mace (Provided)"] = "велика чорна булава (видано)" } },
    [78924] = { [1] = "У пошуках Талріда", [2] = "Багато чуток ходить цими днями про союз Сутінкового Молота та наг у Чорнопровалних Безоднях на узбережжі Ясенеділу.\n\nМоя роль тут, разом зі Срібним Світанком, полягає в тому, щоб зібрати якомога більше інформації, щоб ми знали, коли і де потрібна допомога.\n\nМинули тижні відтоді, як я відправив розвідника перевірити активність у Чорнопровалних Безоднях. Срібний Вартовий Таельрід ще не доповів.\n\nМої інші розвідники зайняті невідкладними справами.\n\nЗнайди та допоможи Таельріду для мене, {ім'я}.", ["en"] = "In Search of Thaelrid" },
    [7893] = { [1] = "Ритуали сили", [4] = "{ім'я}, у своєму прагненні стати найсильнішою жінкою у світі, я подорожувала світом і вивчала секрети нарощування м'язів у далеких майстрів важкої атлетики, силових гуру та стародавніх книжок. Тепер я знаю заборонені вправи, які вб'ють слабких і покалічать непосвячених!\n\nЦі подвиги сили й загартування вимагають тренувань з наймасивнішим шліфувальним камінням. {ім'я}, чи можеш ти знайти або виготовити шліфувальні камені та принести їх мені? Я дам тобі купони, якщо ти це зробиш...", [5] = "Дякую тобі, {ім'я}. Я використаю ці камені в ритуалі набуття сили, про який дізналася зі стародавньої скрижалі в глибинах джунглів Тернистої долини.\n\nКажуть, що та, хто правильно виконає цей священний обряд, матиме силу і витривалість десяти тауренів!", ["en"] = "Rituals of Strength", ["tasks"] = { ["Dense Grinding Stone"] = "масивний шліфувальний камінь", ["Dense Grinding Stone (Provided)"] = "масивний шліфувальний камінь (видано)" } },
    [7894] = { [1] = "Мідний модулятор", [4] = "Єбб розробляє новий атракціон для Дивопарку, який зведе народ з розуму від здивування і захоплення! Але для цього знадобиться багато роботи й багато матеріалів...\n\nВ тому числі мідні модулятори. Нам потрібно багато модуляторів для механічних частин атракціону. Принеси мені мідні модулятори, і я обміняю їх на купони ярмарку Темного місяця.", [5] = "Ага! Модулятори! Чудово!\n\nЯ не можу сказати, що саме ми будуємо, але ці штуки дуже знадобляться для його будівництва. Я у тебе у боргу, {ім'я}, будь ласка, візьми цей купон ярмарку Темного місяця на знак моєї вдячності.", ["en"] = "Copper Modulator", ["tasks"] = { ["Copper Modulator"] = "мідний модулятор", ["Copper Modulator (Provided)"] = "мідний модулятор (видано)" } },
    [7895] = { [1] = "Бронзові тріщалки", [4] = "Моя нова кабінка радуватиме око, так-так, панове! А кому сильно пощастить, той зможе зайти всередину!\n\nЯ вже чую, як бронзові тріщалки співають свою несамовиту механічну пісню, а купи клієнтів біжать у кабінку і випробовують свою вправність!\n\nАх... якби я мав бронзові тріщалки... Благаю, {ім'я}, принеси мені їх, а я тобі дам купони ярмарку Темного місяця!", [5] = "Ти {стать:приніс:принесла} тріщалки! Чудово! Я навіть зараз чую їх тріск. Цілий хор тріщалок в моїй голові! Ох, коли ця кабінка буде готова, це буде чудо світу, я тобі кажу!\n\nОсь твої купони, {ім'я}. І, будь ласка, насолоджуйся ярмарком!", ["en"] = "Whirring Bronze Gizmo", ["tasks"] = { ["Whirring Bronze Gizmo"] = "бронзова тріщалка", ["Whirring Bronze Gizmo (Provided)"] = "бронзова тріщалка (видано)" } },
    [7896] = { [1] = "Зелені феєрверки", [4] = "Коли я нарешті запущу цю будку, я захочу її прорекламувати! А що може бути кращою рекламою, ніж феєрверк?\n\nНу, дехто може подумати, що запах казана, в якому киплять голови твоїх ворогів, краще привертає увагу натовпу, але... аудиторія різна буває. Тож феєрверк буде!\n\nПринеси мені зелені феєрверки, {ім'я}, і я дам тобі велику жменю купонів ярмарку Темного місяця.", [5] = "Ти {стать:приніс:принесла} феєрверки. Чудова робота, {ім'я}! Не можу дочекатися, щоб запалити їх і розповісти світові, що моя кабінка готова до роботи! Я мушу ще почекати... і боюся, що досить довго, але... Все буде готово, коли буде готово, гаразд?\n\nОсь купони, {ім'я}. Насолоджуйся ярмарком!", ["en"] = "Green Fireworks", ["tasks"] = { ["Green Firework"] = "зелений феєрверк", ["Green Firework (Provided)"] = "зелений феєрверк (видано)" } },
    [7897] = { [1] = "Механічний ремкомплект", [4] = "Головна причина того, чому я не можу відкрити свою кабінку, полягає в тому, що... все зламано! Мені потрібні механічні ремкомплекти, щоб все полагодити!\n\nМожеш принести мені ці ремкомплекти, {ім'я}? Я обміняю їх на... купони ярмарку Темного місяця. Що скажеш?", [5] = "Дякую! Тепер я можу починати ремонт.\n\nЗнадобиться багато ремкомплектів і багато ночей, щоб привести все в робочий стан. Іноді я думаю, що було б краще повернутися до свого минулого і відновити кар'єру мисливця за головами, але... Ярмарок мені теж подобається.\n\nВізьми ці купони, {ім'я}, і розважайся!", ["en"] = "Mechanical Repair Kits", ["tasks"] = { ["Mechanical Repair Kit"] = "механічний ремкомплект", ["Mechanical Repair Kit (Provided)"] = "механічний ремкомплект (видано)" } },
    [7898] = { [1] = "Торієвий пристрій", [4] = "Єбб Небіжило, як і я, працює над майбутнім атракціоном. Єбб каже, що цей атракціон буде настільки дивовижним, що приваблюватиме народ з усього світу... і зробить нас усіх дуже, дуже багатими!\n\nВін каже, що йому потрібні торієві пристрої для будівництва, і хоче, щоб я зібрав їх для нього. То що скажеш, {ім'я}? Чи знаєш ти, де можна дістати ці пристрої? Або якщо ти {стать:інженер:інженерка}, чи можеш ти їх зробити? Хочеш обміняти їх на купони ярмарку Темного місяця?", [5] = "О, дякую, {ім'я}! Єббу сподобаються ці пристрої. Я не знаю, що він запланував для них, але Єбб — розумний гном. Він розумний, і, можливо, трохи хитрий....\n\nЯкби йому подобався смак гуманоїдної плоті... з нього вийшов би чудовий троль!\n\nОсь, {ім'я}. Угода є угода, і ці купони твої.", ["en"] = "Thorium Widget", ["tasks"] = { ["Thorium Widget"] = "торієвий пристрій", ["Thorium Widget (Provided)"] = "торієвий пристрій (видано)" } },
    [7899] = { [1] = "Маленькі пухнасті лапки", [4] = "Знаєш, як привернути увагу натовпу? Урок перший: пообіцяй відвідувачам сотні призів та подарунків! Зможеш мені допомогти?\n\nМені потрібні маленькі пухнасті лапки для призів. Ти можеш знайти їх у котів в Степах, або на Темнобережжі....\n\nПринеси мені кілька лапок, і я обміняю їх на купон ярмарку Темного місяця.", [5] = "Чудово, ти їх {стать:знайшов:знайшла}! Ми можемо використати їх для виготовлення іграшок та всіляких дрібничок, які приваблять більше народу на ярмарок!\n\nОсь твій купон, {ім'я}. Ти його {стать:заслужив:заслужила}!", ["en"] = "Small Furry Paws", ["tasks"] = { ["Small Furry Paw"] = "маленька пухнаста лапка", ["Small Furry Paw (Provided)"] = "маленька пухнаста лапка (видано)" } },
    [78994] = { [1] = "Міцний фундамент", [2] = "Реформування зброї виявилося складним завданням, і досі незрозуміло, чому ритуал провалився, але я вважаю, що ми розробили альтернативне рішення.\n\nДля початку нам потрібна міцна основа: Гілка Тіней.\n\nЦі дерева — злоякісні нарости Смарагдового Кошмару, що просочується в наш світ. Кажуть, що вони послаблюють волю оточуючих. Ця магічна властивість стане основою, яку ми використаємо для створення цієї зброї.\n\nЩоб допомогти вам у пошуках, візьміть це зілля. Воно сховає вас від поплічників Смарагдових Драконів.", [3] = "Смарагдові Дракони захищають кілька порталів до Смарагдового Сну по всьому Азероту. В одному з цих місць точно є те, що нам потрібно.\n\nЯк тільки ви знайдете Гілку Тіней, повертайтеся якомога швидше.", [4] = "Ніхто не казав, що це буде легке завдання, але знову ж таки, більшість речей, які варто робити, такими не є.", [5] = "Ах так, ти знайшов його! Твій глузд, здається, досі не зник, поки що все добре.", ["en"] = "A Solid Foundation", ["tasks"] = { ["Invisibility Potion"] = "зілля невидимості" } },
    [7900] = { [1] = "Рвані ведмежі шкури", [4] = "Діти люблять іграшки! І незалежно від раси, я виявив, що всі діти люблять пухнасті, плюшеві іграшки, зроблені з рваних ведмежих шкур!\n\nТи можеш дістати ці шкури з ведмедів Ясенедолу або Гіллзбраду. Принеси їх мені і заробиш купу купонів ярмарку Темного місяця!", [5] = "Гарні шкури, {ім'я}! Я попрошу пошити з них плюшеві іграшки. З гарним наповнювачем і фарбою вони стануть предметом заздрості для дітей по всьому Азероту!\n\nКупони? Ах, так, твоя оплата! Ось вони!", ["en"] = "Torn Bear Pelts", ["tasks"] = { ["Torn Bear Pelt"] = "рвана ведмежа шкура", ["Torn Bear Pelt (Provided)"] = "рвана ведмежа шкура (видано)" } },
    [7901] = { [1] = "М'які пухнасті хвости", [4] = "Це неймовірно, що народ цінує! Візьми, наприклад, дерев'яну палицю з прикріпленим до неї м'яким пухнастим хвостом. Нам з тобою може здатися, що така річ не дуже цінна... але якщо ти даси цьому шматку мотлоху гарну назву, наприклад, \"хвіст пухнастої дикості\", і покладеш його в красиву коробку, то народ вважатиме його дуже цінним. Сміття стає скарбом!\n\nПринеси мені м'які пухнасті хвости вовків зі Спустошища або з Безплідних країв, і я дам тобі купони ярмарку Темного місяця.", [5] = "Молодець, {ім'я}! Ці хвости стануть чудовими призами для наших відвідувачів, а це означає, що наші відвідувачі будуть щасливими... і розкажуть про нас своїм друзям, тобто приведуть ще більше відвідувачів!\n\nОсь твої купони! Бажаю приємно провести час на ярмарку Темного місяця... і не забудь розповісти про нас друзям!", ["en"] = "Soft Bushy Tails", ["tasks"] = { ["Soft Bushy Tail"] = "м'який пухнастий хвіст", ["Soft Bushy Tail (Provided)"] = "м'який пухнастий хвіст (видано)" } },
    [7902] = { [1] = "Яскраве пір'я", [4] = "Уява — неймовірна річ. Вона може змусити найменший пагорб здаватися найбільшою горою. Найневинніша тінь може здатися відкинутою жахливим нічним кошмаром!\n\nМи на ярмарку Темного місяця дозволяємо уяві наших відвідувачів розквітати! Але щоб допомогти їхній уяві... іноді нам доводиться йти на хитрощі.\n\nМені потрібне яскраве пір'я для одного з моїх атракціонів. Ти можеш дістати його у птахів більш небезпечних районів Азерота. Принеси мені пір'я, і я дам тобі багато купонів!", [5] = "А, пір'я! Воно дивовижне, чи не так? Такими красенями можна було б легко розпалити уяву!\n\nТи робиш таку благородну справу, {ім'я}. Посмішки на обличчях наших відвідувачів, коли вони бачать шоу — це вже велика нагорода, але, будь ласка, візьми й ці купони.", ["en"] = "Vibrant Plumes", ["tasks"] = { ["Vibrant Plume"] = "яскраве перо", ["Vibrant Plume (Provided)"] = "яскраве перо (видано)" } },
    [7903] = { [1] = "Очі злих кажанів", [4] = "Ти коли-небудь {стать:блукав:блукала} в печері пізно вночі в пошуках пригод? Бувало? Справді? Тоді ти {стать:бачив:бачила} моторошні очі кажанів, які дивляться на тебе згори, чекаючи, коли ти втратиш пильність, щоб вони могли висмоктати твою кров!\n\nСтрашно, чи не так? Ще б пак! Без сумніву, очі кажанів страшні!\n\nПринесеш мені кілька очей злих кажанів, {ім'я}? Вони мені потрібні для... дечого, що я розробляю. Дечого страшного.\n\nТи можеш знайти ці очі у кажанів зі Східних Зачумлених земель.", [5] = "Чудово! Ти {стать:приніс:принесла} очі! Сподіваюся, полювання на кажанів було для тебе моторошним, бо якщо воно налякало {стать:такого хороброго:таку хоробру} {клас:з}, як ти, то ці очі неодмінно налякають відвідувачів нашого ярмарку.\n\nВізьми ці купони, {ім'я}, і дякую за твою допомогу.", ["en"] = "Evil Bat Eyes", ["tasks"] = { ["Evil Bat Eye"] = "око злого кажана", ["Evil Bat Eye (Provided)"] = "око злого кажана (видано)" } },
    [7904] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>", ["tasks"] = { ["Item #19182"] = "Товар №19182" } },
    [7906] = { [1] = "Карти Молодика - Звірі", ["en"] = "Darkmoon Cards - Beasts", ["tasks"] = { ["Beasts Deck"] = "колода звірів" } },
    [7907] = { [1] = "Колода Темного місяця: звірі", [2] = "Щойно ви збираєте разом всю колоду звірів, загадковим чином з'являється дев'ята карта з таким же зворотом, як і у перших восьми. На цій карті написано: \"Поверніть ці карти на ярмарок Темного місяця й отримаєте винагороду\". Ви чули, що цей ярмарок зупиняється в Мулґорі та Злотохресті кожні кілька місяців, тож вам доведеться почекати, поки він не приїде знову.", [3] = "Поверніть колоду звірів на ярмарок Темного місяця.", [4] = "Бачу, ти вже {стать:встиг:встигла} зібрати колоду звірів! Вітаю!", [5] = "Отже, ти {стать:зібрав:зібрала} колоду звірів. Відтепер між тобою та ярмарком встановиться міцний зв'язок, і пам'ять про нього збережеться надовго. Дозволь подарувати тобі одну з найвеличніших карт Темного місяця, як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Beast Deck", ["tasks"] = { ["Beasts Deck"] = "колода звірів", ["Beasts Deck (Provided)"] = "колода звірів (видано)" } },
    [7908] = { [1] = "Майстер арени", [2] = "Напевно, звання майстра арени не так легко здобути! Можливо, варто спитати у пірата, який керує ареною Ґурубаші.", [3] = "Поговоріть з Коротуном Джоном Мітрилом на арені Тернистої долини.", ["en"] = "Arena Master", ["tasks"] = { ["Arena Master"] = "знак майстра арени" } },
    [79092] = { [1] = "Дослідницький журнал архімага Теокрита", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Archmage Theocritus's Research Journal", ["tasks"] = { ["Archmage Theocritus' Research Journal"] = "Дослідницький журнал архімага Теокрита" } },
    [79093] = { [1] = "Румі з Гномреґану: Зібрання творів", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Rumi of Gnomeregan: The Collected Works", ["tasks"] = { ["Rumi of Gnomeregan: The Collected Works"] = "Румі з Гномреґану: Зібрання творів", ["Rumi of Gnomeregan: The Collected Works (Provided)"] = "Румі з Гномреґану: Зібрання творів (видано)", ["Rumi of Gnomeregan: The Collected Works slain"] = "Румі з Гномреґану: Зібрання творів: убито" } },
    [79095] = { [1] = "Метафізичний посібник аптекаря", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "The Apothecary's Metaphysical Primer", ["tasks"] = { ["The Apothecary's Metaphysical Primer"] = "Метафізичний посібник аптекаря" } },
    [79096] = { [1] = "Атерік: Про таємні курйози", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Ataeric: On Arcane Curiosities", ["tasks"] = { ["Ataeric: On Arcane Curiosities"] = "Атерік: Про таємні курйози" } },
    [79097] = { [1] = "Бакстан: Про руйнівну магію", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Baxtan: On Destructive Magics", ["tasks"] = { ["Baxtan: On Destructive Magics"] = "Бакстан: Про руйнівну магію" } },
    [79100] = { [1] = "Заскочена партія", [5] = "У посилці бракує деяких предметів, але вона все одно буде корисною. Дякую, {ім'я}.", ["en"] = "A Waylaid Shipment" },
    [79101] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment" },
    [79102] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment", ["tasks"] = { ["Supply Shipment"] = "Відвантаження постачання" } },
    [79103] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment" },
    [79192] = { [1] = "Сходинки", [2] = "Записка починається словами: «Місія сказала, що вони обидва здійснюють поставки для Нової Чуми. Мені здається, що це звичайні нещасні випадки в аптеці. Знайдіть моє затишне місце в горах між Степями та Пустощами, якщо хочете безпечне місце для розмови».", [3] = "Ти відриваєш записку від дошки та читаєш каракулі.", [5] = "Тут, безсумнівно, розбивають табір як шукачі пригод у глушині, так і найманці. Куточок записки, що майорить на вітрі, привертає вашу увагу, і ви тягнетеся до неї.", ["en"] = "Stepping Stones" },
    [7921] = { [1] = "Талісмани заслуг", [4] = "Ти {стать:отримав:отримала} талісман заслуги Срібнокрилих за виконання минулого завдання. Поговори зі мною знову, щоб отримати винагороду.", [5] = "Дякую, {ім'я:к}. Звістки про твої подвиги в тіснині Пісні Війни розійшлися по всьому Ясенедолу.", ["en"] = "Talismans of Merit", ["tasks"] = { ["Silverwing Talisman of Merit"] = "талісман заслуги Срібнокрилих", ["Silverwing Talisman of Merit (Provided)"] = "талісман заслуги Срібнокрилих (видано)" } },
    [7922] = { [1] = "Відзнака честі", [4] = "Ти {стать:заслужив:заслужила} довіру за виконання минулого завдання. Принеси мені більше відзнак честі й отримаєш винагороду.", [5] = "Нічні ельфи та їхні союзники мають тремтіти від однієї лиш згадки твого імені! За Орду!\n\nТи {стать:довів:довела} свою цінність для нашої справи в тіснині Пісні Війни. Виплесни всю свою лють на Срібнокрилих стражів! Принеси мені більше відзнак честі!", ["en"] = "Mark of Honor", ["tasks"] = { ["Warsong Mark of Honor"] = "відзнака честі Пісні Війни", ["Warsong Mark of Honor (Provided)"] = "відзнака честі Пісні Війни (видано)" } },
    [79229] = { [1] = "Пограбування на дорозі", [2] = "Табір перед вами — це жахлива картина. Судячи з останків, жертвами були двоє людей і карлик. Сліди на кістках вказують на жорстокий напад, але награбовані припаси говорять про те, що це було зроблено не твариною. Рани також не відповідають зброї кентаврів.\n\nМожливо, досвідчений збирач сміття з цих земель знав би, що з цим робити.", [3] = "Знайдіть у Дезоласі когось, хто знає про розграбований табір.", [5] = "А, тож ти знайшов ще одного...", ["en"] = "Highway Robbery" },
    [7923] = { [1] = "Відзнака честі", [4] = "Ти {стать:заслужив:заслужила} довіру за виконання минулого завдання. Принеси мені більше відзнак честі й отримаєш винагороду.", [5] = "Нічні ельфи та їхні союзники мають тремтіти від однієї лиш згадки твого імені! За Орду!\n\nТи {стать:довів:довела} свою цінність для нашої справи в тіснині Пісні Війни. Виплесни всю свою лють на Срібнокрилих стражів! Принеси мені більше відзнак честі!", ["en"] = "Mark of Honor", ["tasks"] = { ["Warsong Mark of Honor"] = "відзнака честі Пісні Війни", ["Warsong Mark of Honor (Provided)"] = "відзнака честі Пісні Війни (видано)" } },
    [79235] = { [1] = "У бігах", [2] = "Я знайшов кілька сцен, схожих на ті, що ви описуєте, {ім'я}. Завжди табори людей та гномів. Серед караванів ходять чутки, що це зробила група ординських мародерів. Здається ймовірним, враховуючи жертв та жорстокість нападів.\n\nСхоже, бандити втекли з Пустощів, як тільки маршал Альянсу пішов на їхній слід.\n\nЯкщо ви хочете вистежити одного з них, я б звернувся до портового міста. Там завжди з'являються та йдуть тіньові особи. Можливо, когось спіймають, коли він намагається дістатися човном кудись.", [3] = "Знайдіть одного з мародерів з Дезоласа.", [5] = "Тобі щось потрібно? Зроби це швидко.", ["en"] = "On the Lam" },
    [79236] = { [1] = "Вишня для ваших думок?", [2] = "Ти з маршалом? Ні, ти на нього не схожий.\n\nЧутки, які ти чув, правдиві лише наполовину. Так, ми грабували людські та гномські табори, але ми робили це не для Орди. Ми були приватними працівниками.\n\nЯ розповім тобі всю історію, якщо ти купиш мені трохи грогу.", [3] = "Принесіть вишневий грог Токал, що в Буті-Бей, щоб почути решту її історії.", [4] = "Як там з тим напоєм?", [5] = "А, ось і все. А на чому я зупинився?", ["en"] = "Cherry for Your Thoughts?" },
    [7924] = { [1] = "Відзнака честі", [4] = "Ти {стать:заслужив:заслужила} довіру за виконання минулого завдання. Принеси мені більше відзнак честі й отримаєш винагороду.", [5] = "Нічні ельфи та їхні союзники мають тремтіти від однієї лиш згадки твого імені! За Орду!\n\nТи {стать:довів:довела} свою цінність для нашої справи в тіснині Пісні Війни. Виплесни всю свою лють на Срібнокрилих стражів! Принеси мені більше відзнак честі!", ["en"] = "Mark of Honor", ["tasks"] = { ["Warsong Mark of Honor"] = "відзнака честі Пісні Війни", ["Warsong Mark of Honor (Provided)"] = "відзнака честі Пісні Війни (видано)" } },
    [79242] = { [1] = "Немає честі серед злодіїв", [2] = "Як я вже казав...\n\nНаша начальниця не була з Ордою. Це була нічна ельфійка на ім'я Ілларі Сутінкове Перо. Вона дала нам інформацію про табори і навіть дозволила нам залишити собі більшу частину здобичі. Вона залишила собі лише кілька рідкісних знахідок.\n\nОднак, коли Маршал почала слідувати за нами, вона залишила нас помирати. Я не знаю її мотивів, але думаю, що нас підставили як халепу.\n\nЯ не з тих, хто мститься, але я не заваджу комусь іншому полювати на неї. Якщо ви її шукаєте, вона колись згадувала про сховище десь поблизу Араті.", [3] = "Знайдіть Ілларі Сутінкове Перо поблизу Араті-Хайлендс та отримайте доступ до її схованки з викраденою здобиччю.", [4] = "<Використовуючи ключ Ілларі, ви розблоковуєте схованку.>", [5] = "<Усередині схованки ви знаходите невелику скриньку разом із монетами.>", ["en"] = "No Honor Among Thieves" },
    [7925] = { [1] = "Відзнака честі", [4] = "Ти {стать:заслужив:заслужила} довіру за виконання минулого завдання. Принеси мені більше відзнак честі й отримаєш винагороду.", [5] = "Нічні ельфи та їхні союзники мають тремтіти від однієї лиш згадки твого імені! За Орду!\n\nТи {стать:довів:довела} свою цінність для нашої справи в тіснині Пісні Війни. Виплесни всю свою лють на Срібнокрилих стражів! Принеси мені більше відзнак честі!", ["en"] = "Mark of Honor", ["tasks"] = { ["Warsong Mark of Honor"] = "відзнака честі Пісні Війни", ["Warsong Mark of Honor (Provided)"] = "відзнака честі Пісні Війни (видано)" } },
    [7927] = { [1] = "Колода Темного місяця: портали", [2] = "Щойно ви збираєте разом всю колоду порталів, загадковим чином з'являється дев'ята карта з таким же зворотом, як і у перших восьми. На цій карті написано: \"Поверніть ці карти на ярмарок Темного місяця й отримаєте винагороду\". Ви чули, що цей ярмарок зупиняється в Мулґорі та Злотохресті кожні кілька місяців, тож вам доведеться почекати, поки він не приїде знову.", [3] = "Поверніть колоду порталів на ярмарок Темного місяця.", [4] = "Бачу, ти вже {стать:встиг:встигла} зібрати колоду порталів! Вітаю!", [5] = "Отже, ти {стать:зібрав:зібрала} колоду порталів. Відтепер між тобою та ярмарком встановиться міцний зв'язок, і пам'ять про нього збережеться надовго. Дозволь подарувати тобі одну з найвеличніших карт Темного місяця, як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Portals Deck", ["tasks"] = { ["Portals Deck"] = "колода порталів", ["Portals Deck (Provided)"] = "колода порталів (видано)" } },
    [7928] = { [1] = "Колода Темного місяця: воєводи", [2] = "Щойно ви збираєте разом всю колоду воєвод, загадковим чином з'являється дев'ята карта з таким же зворотом, як і у перших восьми. На цій карті написано: \"Поверніть ці карти на ярмарок Темного місяця й отримаєте винагороду\". Ви чули, що цей ярмарок зупиняється в Мулґорі та Злотохресті кожні кілька місяців, тож вам доведеться почекати, поки він не приїде знову.", [3] = "Поверніть колоду воєвод на ярмарок Темного місяця.", [4] = "Бачу, ти вже {стать:встиг:встигла} зібрати колоду воєвод! Вітаю!", [5] = "Отже, ти {стать:зібрав:зібрала} колоду воєвод. Відтепер між тобою та ярмарком встановиться міцний зв'язок, і пам'ять про нього збережеться надовго. Дозволь подарувати тобі одну з найвеличніших карт Темного місяця, як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Warlords Deck", ["tasks"] = { ["Warlords Deck"] = "колода воєвод", ["Warlords Deck (Provided)"] = "колода воєвод (видано)" } },
    [7929] = { [1] = "Колода Темного місяця: елементалі", [2] = "Щойно ви збираєте разом всю колоду елементалів, загадковим чином з'являється дев'ята карта з таким же зворотом, як і у перших восьми. На цій карті написано: \"Поверніть ці карти на ярмарок Темного місяця й отримаєте винагороду\". Ви чули, що цей ярмарок зупиняється в Мулґорі та Злотохресті кожні кілька місяців, тож вам доведеться почекати, поки він не приїде знову.", [3] = "Поверніть колоду елементалів на ярмарок Темного місяця.", [4] = "Бачу, ти вже {стать:встиг:встигла} зібрати колоду елементалів! Вітаю!", [5] = "Отже, ти {стать:зібрав:зібрала} колоду елементалів. Відтепер між тобою та ярмарком встановиться міцний зв'язок, і пам'ять про нього збережеться надовго. Дозволь подарувати тобі одну з найвеличніших карт Темного місяця, як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Elementals Deck", ["tasks"] = { ["Elementals Deck"] = "колода елементалів", ["Elementals Deck (Provided)"] = "колода елементалів (видано)" } },
    [79298] = { [1] = "Спокуслива доля", [2] = "Ви бачите, що нечиста магія отруює воду, надаючи їй фіолетового відтінку. Палаючий Клинок переповнив цю область темною енергією.\n\nМи використаємо цей Жертвенний Альтер, який вони використовують під час ритуалів викликання. Ми можемо використати приховану темну енергію в цій області, щоб посилити наш ритуал.", [3] = "Допоможіть Раселю Андеру та Доану Кархану з ритуалом виклику та заманіть Дес'Альтека в пастку всередині посоху.", [5] = "Хоча Расель Андер був і не таким відомим, його командування не було однією з рис, які я знав. Як для {клас}, він завжди був покірним. У мене виникло відчуття, що щось не так, коли той самозванець повернувся під час твого ритуалу виклику, тому я послав за допомогою ще аколітів, але цього було недостатньо... Знову нам не вдалося спіймати нашу здобич.\n\nНа жаль, посох розбився під час твого бою, і все, що я міг зробити, це стояти безпорадно осторонь і спостерігати... але я знайшов це в руйнуванні.", ["en"] = "Tempting Fate" },
    [7930] = { [1] = "5 купонів — квітка Темного місяця", [4] = "Підходь, підходь! Якщо у тебе є купони ярмарку Темного місяця, які ти хочеш обміняти, просто скажи! Ти можеш обміняти різну кількість купонів на чудові та фантастичні призи. Не соромся, спробуй!", [5] = "Тримай, тримай! Приз, гідний {стать:короля:королеви}! Вітаю тебе, {стать:друже:подруго}!\n\nЯкщо у тебе є ще купони, які ти хочеш здати, будь ласка, дай мені знати! Я зможу обміняти твої купони лиш поки триває ярмарок Темного місяця.", ["en"] = "5 Tickets - Darkmoon Flower", ["tasks"] = { ["Darkmoon Faire Prize Ticket"] = "призовий купон ярмарку Темного місяця", ["Darkmoon Faire Prize Ticket (Provided)"] = "призовий купон ярмарку Темного місяця (видано)" } },
    [7931] = { [1] = "5 купонів — заохочувальний приз Темного місяця", [4] = "Підходь, підходь! Якщо у тебе є купони ярмарку Темного місяця, які ти хочеш обміняти, просто скажи! Ти можеш обміняти різну кількість купонів на чудові та фантастичні призи. Не соромся, спробуй!", [5] = "Тримай, тримай! Приз, гідний {стать:короля:королеви}! Вітаю тебе, {стать:друже:подруго}!\n\nЯкщо у тебе є ще купони, які ти хочеш здати, будь ласка, дай мені знати! Я зможу обміняти твої купони лиш поки триває ярмарок Темного місяця.", ["en"] = "5 Tickets - Minor Darkmoon Prize", ["tasks"] = { ["Darkmoon Faire Prize Ticket"] = "призовий купон ярмарку Темного місяця", ["Darkmoon Faire Prize Ticket (Provided)"] = "призовий купон ярмарку Темного місяця (видано)" } },
    [7932] = { [1] = "12 купонів — малий приз Темного місяця", [4] = "Підходь, підходь! Якщо у тебе є купони ярмарку Темного місяця, які ти хочеш обміняти, просто скажи! Ти можеш обміняти різну кількість купонів на чудові та фантастичні призи. Не соромся, спробуй!", [5] = "Тримай, тримай! Приз, гідний {стать:короля:королеви}! Вітаю тебе, {стать:друже:подруго}!\n\nЯкщо у тебе є ще купони, які ти хочеш здати, будь ласка, дай мені знати! Я зможу обміняти твої купони лиш поки триває ярмарок Темного місяця.", ["en"] = "12 Tickets - Lesser Darkmoon Prize", ["tasks"] = { ["Darkmoon Faire Prize Ticket"] = "призовий купон ярмарку Темного місяця", ["Darkmoon Faire Prize Ticket (Provided)"] = "призовий купон ярмарку Темного місяця (видано)" } },
    [7933] = { [1] = "40 купонів — великий приз Темного місяця", [4] = "Підходь, підходь! Якщо у тебе є купони ярмарку Темного місяця, які ти хочеш обміняти, просто скажи! Ти можеш обміняти різну кількість купонів на чудові та фантастичні призи. Не соромся, спробуй!", [5] = "Тримай, тримай! Приз, гідний {стать:короля:королеви}! Вітаю тебе, {стать:друже:подруго}!\n\nЯкщо у тебе є ще купони, які ти хочеш здати, будь ласка, дай мені знати! Я зможу обміняти твої купони лиш поки триває ярмарок Темного місяця.", ["en"] = "40 Tickets - Greater Darkmoon Prize", ["tasks"] = { ["Darkmoon Faire Prize Ticket"] = "призовий купон ярмарку Темного місяця", ["Darkmoon Faire Prize Ticket (Provided)"] = "призовий купон ярмарку Темного місяця (видано)" } },
    [7934] = { [1] = "50 купонів — скринька Темного місяця", [4] = "Підходь, підходь! Якщо у тебе є купони ярмарку Темного місяця, які ти хочеш обміняти, просто скажи! Ти можеш обміняти різну кількість купонів на чудові та фантастичні призи. Не соромся, спробуй!", [5] = "Тримай, тримай! Приз, гідний {стать:короля:королеви}! Вітаю тебе, {стать:друже:подруго}!\n\nЯкщо у тебе є ще купони, які ти хочеш здати, будь ласка, дай мені знати! Я зможу обміняти твої купони лиш поки триває ярмарок Темного місяця.", ["en"] = "50 Tickets - Darkmoon Storage Box", ["tasks"] = { ["Darkmoon Faire Prize Ticket"] = "призовий купон ярмарку Темного місяця", ["Darkmoon Faire Prize Ticket (Provided)"] = "призовий купон ярмарку Темного місяця (видано)" } },
    [79348] = { [1] = "Загублені стародавні", [2] = "Гниле насіння — це все, що залишається від мандрівного древнього. Його зовнішня оболонка крихка, а всередині виходить неприємний запах.\n\nВраховуючи його розмір, древній, з якого походить це насіння, мав бути досить молодим; принаймні за стародавніми стандартами. Цікаво, чому таку істоту знайшли, що блукає Трясовиною.\n\nЩоб знайти відповіді, вам слід віднести це насіння комусь, хто знає знання стародавніх.", [3] = "Знайдіть когось, хто може розповісти вам більше про гниле стародавнє насіння.", [5] = "Ах, ще один загублений юнак...", ["en"] = "The Lost Ancient" },
    [7935] = { [1] = "10 купонів — баранина місячної витримки", [4] = "Підходь, підходь! Якщо у тебе є купони ярмарку Темного місяця, які ти хочеш обміняти, просто скажи! Ти можеш обміняти різну кількість купонів на чудові та фантастичні призи. Не соромся, спробуй!", [5] = "Тримай, тримай! Приз, гідний {стать:короля:королеви}! Вітаю тебе, {стать:друже:подруго}!\n\nЯкщо у тебе є ще купони, які ти хочеш здати, будь ласка, дай мені знати! Я зможу обміняти твої купони лиш поки триває ярмарок Темного місяця.", ["en"] = "10 Tickets - Last Month's Mutton", ["tasks"] = { ["Darkmoon Faire Prize Ticket"] = "призовий купон ярмарку Темного місяця", ["Darkmoon Faire Prize Ticket (Provided)"] = "призовий купон ярмарку Темного місяця (видано)" } },
    [7936] = { [1] = "50 купонів — баранина річної витримки", [4] = "Підходь, підходь! Якщо у тебе є купони ярмарку Темного місяця, які ти хочеш обміняти, просто скажи! Ти можеш обміняти різну кількість купонів на чудові та фантастичні призи. Не соромся, спробуй!", [5] = "Тримай, тримай! Приз, гідний {стать:короля:королеви}! Вітаю тебе, {стать:друже:подруго}!\n\nЯкщо у тебе є ще купони, які ти хочеш здати, будь ласка, дай мені знати! Я зможу обміняти твої купони лиш поки триває ярмарок Темного місяця.", ["en"] = "50 Tickets - Last Year's Mutton", ["tasks"] = { ["Darkmoon Faire Prize Ticket"] = "призовий купон ярмарку Темного місяця", ["Darkmoon Faire Prize Ticket (Provided)"] = "призовий купон ярмарку Темного місяця (видано)" } },
    [7937] = { [1] = "Ваша доля чекає на вас...", [2] = "\"Ваша доля чекає на вас в Східнодолі.\"\n\nПророцтво, що вам передав Вщун, тепле на дотик. Стискаючи його, ви бачите видіння лісозаготівельного табору Східнодолу в Ельвиннському лісі. Сконцентрувавшись на видінні, ви бачите копицю сіна, що стоїть поруч зі стайнею.", [3] = "Прямуйте до лісозаготівельного табору Східнодолу в Ельвиннському лісі та відшукайте свою долю.", [4] = "Ця копиця сіна схожа на ту, що ви бачили у видінні.", [5] = "У копиці сіна ви знаходите невелику скриньку. Мабуть, в ній знаходиться ваша доля!", ["en"] = "Your Fortune Awaits You...", ["tasks"] = { ["Sayge's Fortune #23"] = "пророцтво Вщуна #23", ["Sayge's Fortune #23 (Provided)"] = "пророцтво Вщуна #23 (видано)" } },
    [79377] = { [1] = "Загублені саджанці", [2] = "У часи неспокою насіння може пустити коріння в гіркому ґрунті. Древні, народжені таким чином, схильні до зіпсуття. Вони блукають ворожими землями; ніколи не знаходячи спокою.\n\nЯ відчував чотири саджанці, яких може уникнути такої долі. Вони загублені серед Східних Королівств, з листям, подібним до листя кожної пори року.\n\nБудь ласка, віднесіть їм цю воду, щоб вони могли зцілитися.\n\nБудьте обережні, магія води делікатна. Телепортація знищить її. Її сила також з часом зникне.", [3] = "Знайдіть чотири загублені саджанці у Східних Королівствах та поділіться з ними Водою Елуне'ари. Після цього поверніться до Орокаю, що в Місячній Галявині.\n\nНаданий предмет:", [4] = "Поспішай, {ім'я}. Моїх родичів ще можна врятувати.", [5] = "Ваші справи зберегли століття життя, {ім'я}. Я безмежно вдячний. Нехай ви принесете ще більше зцілення на цю землю в прийдешні часи.", ["en"] = "The Lost Saplings", ["tasks"] = { ["Item #213036"] = "Артикул №213036" } },
    [7938] = { [1] = "Ваша доля чекає на вас...", [2] = "\"Ваша доля чекає на вас всередині Мертвих копалень.\"\n\nПророцтво, що вам передав Вщун, тепле на дотик. Стискаючи його, ви бачите видіння Мертвих копалень під зруйнованим містечком Місяцеграй, що в Західному краю. Сконцентрувавшись на видінні, ви проходите через довгі тунелі до мерехтливого порталу, що веде в глибини копалень. Пройшовши через нього, ви натрапляєте на дивну скриню, що з'явилась нібито нізвідки.", [3] = "Прямуйте до Мертвих копалень в Західному краї та відшукайте свою долю.", [4] = "Ця скриня схожа на ту, що ви бачили у видінні...", [5] = "У скрині ви знаходите невелику скриньку. Мабуть, в ній знаходиться ваша доля!", ["en"] = "Your Fortune Awaits You...", ["tasks"] = { ["Sayge's Fortune #24"] = "пророцтво Вщуна #24", ["Sayge's Fortune #24 (Provided)"] = "пророцтво Вщуна #24 (видано)" } },
    [7939] = { [1] = "Більше масивних шліфувальних каменів", [4] = "{ім'я}, дякую за всю допомогу, яку ти мені {стать:надав:надала}. Я справді не зможу вдосталь віддячити!\n\nХоча моя потреба вже не така велика... якщо ти принесеш мені більше масивних шліфувальних каменів, у мене все ще знайдуться для тебе купони ярмарку Темного місяця.", [5] = "Ще раз дякую тобі, {ім'я}. Будь ласка, насолоджуйся цими купонами й розкажи про ярмарок Темного місяця своїм друзям!", ["en"] = "More Dense Grinding Stones", ["tasks"] = { ["Dense Grinding Stone"] = "масивний шліфувальний камінь", ["Dense Grinding Stone (Provided)"] = "масивний шліфувальний камінь (видано)" } },
    [7940] = { [1] = "1200 купонів — сфера Темного місяця", [4] = "Підходь, підходь! Якщо у тебе є купони ярмарку Темного місяця, які ти хочеш обміняти, просто скажи! Ти можеш обміняти різну кількість купонів на чудові та фантастичні призи. Не соромся, спробуй!", [5] = "Тримай, тримай! Приз, гідний {стать:короля:королеви}! Вітаю тебе, {стать:друже:подруго}!\n\nЯкщо у тебе є ще купони, які ти хочеш здати, будь ласка, дай мені знати! Я зможу обміняти твої купони лиш поки триває ярмарок Темного місяця.", ["en"] = "1200 Tickets - Orb of the Darkmoon", ["tasks"] = { ["Darkmoon Faire Prize Ticket"] = "призовий купон ярмарку Темного місяця", ["Darkmoon Faire Prize Ticket (Provided)"] = "призовий купон ярмарку Темного місяця (видано)" } },
    [7941] = { [1] = "Більше накладок для обладунків", [4] = "{ім'я}, я маю подякувати тобі за всю твою допомогу. Я маю багато припасів завдяки неабияким зусиллям з твого боку, але якщо ти бажаєш принести мені більше накладок для обладунків, то я з радістю обміняю їх на купони ярмарку Темного місяця.", [5] = "Ось твої купони, {ім'я}. Чесний обмін. Насолоджуйся.", ["en"] = "More Armor Kits", ["tasks"] = { ["Rugged Armor Kit"] = "накладки з міцної шкіри", ["Rugged Armor Kit (Provided)"] = "накладки з міцної шкіри (видано)" } },
    [7942] = { [1] = "Більше торієвих пристроїв", [4] = "{ім'я}, ти дуже {стать:допоміг:допомогла} нам, невтомно привозячи всі ці речі. Я тобі безмежно вдячний!\n\nХоча наша потреба у торієвих пристроях вже не така велика, як раніше, ти все одно можеш приносити їх мені, і я з радістю обміняю їх на купони ярмарку Темного місяця.", [5] = "Ось, будь ласка, {ім'я}. Твої купони ярмарку Темного місяця. Та не варто витрачати їх всі й одразу!", ["en"] = "More Thorium Widgets", ["tasks"] = { ["Thorium Widget"] = "торієвий пристрій", ["Thorium Widget (Provided)"] = "торієвий пристрій (видано)" } },
    [7943] = { [1] = "Більше очей кажанів", [4] = "{ім'я}, атракціон, який я розробляю, стане найстрашнішою подією з часів захоплення Гномреґана! І це значною мірою завдяки тобі й всім тим дрібничкам, які ти мені {стать:приніс:принесла}. Величезне, величезне тобі спасибі!\n\nМені більше нічого не потрібно, але... якщо ти принесеш мені більше очей злих кажанів зі Східних Зачумлених земель... можливо, у мене знайдуться для тебе купони ярмарку Темного місяця.", [5] = "Ще раз спасибі, {ім'я}. Ось твої купони!", ["en"] = "More Bat Eyes", ["tasks"] = { ["Evil Bat Eye"] = "око злого кажана", ["Evil Bat Eye (Provided)"] = "око злого кажана (видано)" } },
    [7944] = { [1] = "Ваша доля чекає на вас...", [2] = "\"Ваша доля чекає на вас всередині Плачучих печер.\"\n\nПророцтво, що вам передав Вщун, тепле на дотик. Стискаючи його, ви бачите видіння печери на південний захід від Перехрестя в Степах. Сконцентрувавшись на видінні, ви проходите через довгі тунелі до мерехтливого порталу, що веде в глибини печер. Пройшовши через нього, ви натрапляєте на дивну скриню, що з'явилась нібито нізвідки.", [3] = "Прямуйте до Плачущих печер в Степах та відшукайте свою долю.", [4] = "Ця скриня схожа на ту, що ви бачили у видінні...", [5] = "У скрині ви знаходите невелику скриньку. Мабуть, в ній знаходиться ваша доля!", ["en"] = "Your Fortune Awaits You...", ["tasks"] = { ["Sayge's Fortune #25"] = "пророцтво Вщуна #25", ["Sayge's Fortune #25 (Provided)"] = "пророцтво Вщуна #25 (видано)" } },
    [7945] = { [1] = "Ваша доля чекає на вас...", [2] = "\"Ваша доля чекає на вас біля скелі Бляклогривів.\"\n\nПророцтво, що вам передав Вщун, тепле на дотик. Стискаючи його, ви бачите видіння скелі Бляклогривів в Мулґорі. Сконцентрувавшись на видінні, ви бачите пеньок, що знаходиться неподалік входу в печеру.", [3] = "Прямуйте до скелі Бляклогривів в Мулґорі та відшукайте свою долю.", [4] = "Цей пеньок схожий той, що ви бачили у видінні.", [5] = "В пеньку ви знаходите невелику скриньку. Мабуть, в ній знаходиться ваша доля!", ["en"] = "Your Fortune Awaits You...", ["tasks"] = { ["Sayge's Fortune #27"] = "пророцтво Вщуна #27", ["Sayge's Fortune #27 (Provided)"] = "пророцтво Вщуна #27 (видано)" } },
    [7946] = { [1] = "Потомство Жабжаб", [4] = "Я так рада, що Жабжаб знайшлась. Вона так любить ель Темного Заліза, що коли він закінчився... вона втекла, щоб знайти ще!\n\nТепер, коли Жабжаб повернулася, мені потрібно стільки елю, скільки можна дістати! Я не хочу, щоб вона знову втекла!\n\nУ тебе є ель Темного Заліза? Якщо є, то я обміняю одне яйце Жабжаб на кухоль...", [5] = "Спасибі, {ім'я}. Ось твоє яйце! Воно не вилупиться ще деякий час, але коли це станеться, у тебе з'явиться чудовий улюбленець!", ["en"] = "Spawn of Jubjub", ["tasks"] = { ["Dark Iron Ale Mug"] = "кухоль елю Темного Заліза", ["Dark Iron Ale Mug (Provided)"] = "кухоль елю Темного Заліза (видано)" } },
    [795] = { [1] = "Печатка Землі", [4] = "Перед вами печатка Землі з трьома заглибленнями для аметистового, опалового та діамантового рунічних каменів.", [5] = "Щойно рунічні камені опинилися у призначених для них заглибленнях, земля затремтіла і печатка зруйнувалася.", ["en"] = "Seal of the Earth", ["tasks"] = { ["Amethyst Runestone"] = "аметистовий рунічний камінь", ["Amethyst Runestone (Provided)"] = "аметистовий рунічний камінь (видано)", ["Diamond Runestone"] = "діамантовий рунічний камінь", ["Diamond Runestone (Provided)"] = "діамантовий рунічний камінь (видано)", ["Opal Runestone"] = "опаловий рунічний камінь", ["Opal Runestone (Provided)"] = "опаловий рунічний камінь (видано)" } },
    [79535] = { [1] = "Василіски: чи варто боятися скам'яніння?", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Basilisks: Should Petrification be Feared?", ["tasks"] = { ["Basilisks: Should Petrification be Feared?"] = "Василіски: чи варто боятися скам'яніння?" } },
    [79536] = { [1] = "Великий друг бібліотеки", [5] = "Завдяки вашим пожертвам бібліотека процвітає.\n\nБудь ласка, візьміть це.", ["en"] = "Greater Friend of the Library" },
    [79588] = { [1] = "Маленькі пухнасті лапки", [4] = "Перший урок зі створення натовпу: заманюйте їх за допомогою дрібничок та гаджетів! Чи можете ви мені допомогти?\n\nМені потрібні маленькі пухнасті лапи, щоб використовувати їх як призи. Ви можете знайти їх на котах Степу або Темного Берега...\n\nПринесіть мені кілька лап, і я обміняю вам квиток на Ярмарок Молодика.", [5] = "Чудово, ви їх отримали! Ми можемо використати їх для виготовлення іграшок та кульок, і це привабить більше людей на ярмарок!\n\nОсь ваш квиток, {ім'я}. Ви його заслужили!", ["en"] = "Small Furry Paws" },
    [79589] = { [1] = "Рвані ведмежі шкури", [4] = "Діти люблять іграшки! І незалежно від раси, я помітив, що всі діти люблять пухнасті, плюшеві іграшки, зроблені з розірваних ведмежих шкур!\n\nВи можете отримати ці шкури у ведмедів з Ясенеділу або Гіллсбрада. Принесіть мені купу їх і заробіть собі купу квитків на Ярмарок Новомісяця!", [5] = "Гарні шкурки, {ім'я}! Я попрошу когось зшити з них купу плюшевих іграшок. З невеликою кількістю набивки та фарби, гадаю, вони будуть предметом заздрості дітей по всьому Азероту!\n\nКвитки? Ах так, ваша оплата! Ось вони!", ["en"] = "Torn Bear Pelts" },
    [79590] = { [1] = "Важкий шліфувальний камінь", [4] = "Щоб покращити свої тренування, я люблю вставляти посох між важкими жорнами, а потім піднімати посох над головою. Це нелегко, але бути найсильнішою жінкою у світі, якою я є, не можна заслужити сидячи!\n\nЧи можете ви мені допомогти? Мені потрібно більше жорна — принесіть мені трохи, і я обміняю на них квитки на ярмарок Новомісяччя.", [5] = "Ти приніс каміння! І воно важке! Я вже відчуваю, як мої м'язи стають більшими. Дякую {ім'я}!\n\nОсь, візьми ці квитки і не їж забагато солодощів, поки будеш на ярмарку. Такому великому, сильному {клас}, як ти, потрібно підтримувати себе у бойовій формі!", ["en"] = "Heavy Grinding Stone" },
    [79591] = { [1] = "Бронзові тріщалки", [4] = "Мій новий стенд буде видовищем, так, сер! Видовищем, яке варто побачити, і... для кількох щасливчиків, яке варто помацати!\n\nЯ вже чую, як бронзові штучки співають свою пісню механічного захоплення, коли відвідувачі підходять до мого стенда та випробовують свою майстерність!\n\nАх... тепер мені потрібні самі штучки, щоб наблизити мою мрію до здійснення. Будь ласка, {ім'я}, принесіть мені бронзові штучки, що дзижчать... і квитки на Ярмарок Новомісяця будуть вашими!", [5] = "Ви принесли ці штуковини! Чудово! Навіть зараз я чую їхнє гудіння, свистячий хор у своїй голові! О, коли цей стенд буде готовий, це буде диво світу, запам'ятайте!\n\nОсь ваші квитки, {ім'я}. І, будь ласка, насолоджуйтесь перебуванням на ярмарку!", ["en"] = "Whirring Bronze Gizmo" },
    [79592] = { [1] = "Карнавальні шкіряні куртки", [4] = "Наші працівники ярмарку не просто збирають сміття та забивають цвяхи! Вони також допомагають охороняти карнавал під час його подорожі, і для цього їм завжди потрібні міцні обладунки.\n\nЯкщо ви зробите міцні шкіряні обладунки та принесете їх мені, я подбаю про те, щоб вони потрапили до потрібних людей. Я також роздобуду вам кілька квитків на ярмарок Новомісяччя в обмін.", [5] = "А, ви принесли куртки. Чудово. Шкуру якої тварини ви використали для їх виготовлення, якщо можна запитати? Вишивка дуже добре виконана, а текстура шкіри має суворий стиль. Я бачу, що ви майстер мистецтва!\n\nДякую, {ім'я}, а ось ваші квитки.", ["en"] = "Carnival Jerkins" },
    [79593] = { [1] = "Шорстке грузило", [4] = "Потрібно багато працювати, щоб бути найсильнішою жінкою на світі! Моя вага стає занадто легкою, і якщо я буду занадто підтримувати форму, мені знадобляться додаткові гирі!\n\nЯкщо ти принесеш мені кілька вагових каменів, то я подарую тобі квиток на ярмарок Новомісяччя.", [5] = "Чудово! Вони чудово підійдуть! Вони не надто важкі, але й не надто легкі. Вони ідеально підходять для нарощування м'язової маси!\n\nЩиро дякую, {ім'я}. Ось ваш квиток на ярмарок Новомісяччя!", ["en"] = "Coarse Weightstone" },
    [79594] = { [1] = "Мідний модулятор", [4] = "Єбб розробляє новий атракціон для дивовижного звіринця, який зведе людей з розуму від захоплення та захоплення! Але це вимагатиме багато роботи та багато матеріалів...\n\nСюди входять мідні модулятори. Нам потрібно багато модуляторів для механічних частин атракціону. Принесіть мені мідні модулятори, і я обміняю їх на квиток на ярмарок Новомісяччя.", [5] = "Ага! Модулятори! Чудово!\n\nЯ не можу точно сказати, що ми будуємо, але вони будуть безцінними для його будівництва. Я ваш боржник, {ім'я}, але, будь ласка, прийміть цей квиток на Ярмарок Новомісяччя як знак моєї вдячності.", ["en"] = "Copper Modulator" },
    [79595] = { [1] = "Карнавальні чоботи", [4] = "Ми на Ярмарку Новомісяччя багато ходимо пішки. Ми ходимо від одного ярмарку до іншого... насправді, ви ніколи не побачите нас сидячими на роботі! Тож не дивно, що ми зношуємо чимало чобіт! Нам потрібні чоботи, які є одночасно міцними та стильними, і чоботи з тисненням та шкіри чудово підходять для цього.\n\nТи! Ти шкіряник; зроби мені чоботи з тисненням та шкіри, і я дам тобі квиток на Ярмарок Новомісяччя за роботу.", [5] = "Дякую, {ім'я}. Вони досить добре зроблені. Майстерність на найвищому рівні! Ось квиток на ярмарок Новомісяччя... насолоджуйтесь, сер.", ["en"] = "Carnival Boots" },
    [796] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [7961] = { [1] = "Васкілі Ваббітс!", [2] = "Ці кролики неконтрольовано розмножуються. Треба щось робити!\n\nДопоможіть нам {ім'я}, ви наша єдина надія.", [3] = "Убийте 5 кроликів і поверніться до Джона ЛеКрафта біля кузні на Острові Дизайнерів.", ["en"] = "Waskily Wabbits!", ["tasks"] = { ["Polymorph Clone slain"] = "поліморфний клон: убито", ["The Good Rabbit slain"] = "Добрий кролик: убито", ["Zap a Polymorphed Chicken"] = "Збийте поліморфну курку" } },
    [7962] = { [1] = "Шкури вебітів", [2] = "Я хочу шкурки кролика від ЛеКрафті. Принесіть мені трохи від кроликів ЛеКрафті.\n\nЦе важливо!", ["en"] = "Wabbit Pelts", ["tasks"] = { ["LeCraft Rabbit Pelt"] = "кроляча шкурка ЛеКрафта" } },
    [79624] = { [1] = "Готувати може кожен", [2] = "Схоже, рецепт якоїсь м’ясної страви. Він написаний мовою, яку ви не розумієте. Огр – це ваша найкраща здогадка, враховуючи джерело та тему.\n\nОгри зазвичай не є кулінарними фанатами, але якщо ви знаєте когось із таким нахилом, він міг би перекласти рецепт для вас.", [3] = "Знайдіть людожера, який може прочитати Нерозбірливий рецепт.", [5] = "У тебе є рецепт? Сконк слухає.", ["en"] = "Anyone Can Cook" },
    [79626] = { [1] = "Рятувальний 9000!", [2] = "Здається, цей пристрій отримує живлення, але ледве-ледве. На невеликій табличці написано \"Утилізатор 9000\", а далі — текст, який неможливо розібрати через товстий шар засохлого бруду. Машина має дуже великий приймальний отвір, а також щілину для монет.", [3] = "Вставте забруднений брудом бітум деталі у Утилізатор 9000 та переконайтеся, що у вас є тридцять срібних монет, щоб запустити машину.", [4] = "Машина виглядає вкрай занедбаною. Схоже, до неї ще можна вставити вкриті брудом деталі, але ви не певні, що після цього станеться.", [5] = "Ви вставляєте Забруднений брудом утиль та тридцять срібних монет у Утилізатор 9000. Машина ненадовго засвітлюється, починає трястися та гриміти, а потім випльовує ваш все ще брудний утиль, перш ніж замовкнути. Здається, він зламаний.", ["en"] = "The Salvagematic 9000!" },
    [79637] = { [1] = "Подарунок, що цокає", ["en"] = "A Ticking Present" },
    [79677] = { [1] = "Швидкий похід за продуктами", [2] = "Інші огри сміються зі Сконка, бо Сконк менший за них. Вони кажуть, що маленький огр слабкий, тому Сконк вчиться готувати, а не битися. Це викликає лише ще більше дражнилок, тому Сконк тікає, щоб слідувати за мрією.\n\nСконк може готувати страви, але потрібні інгредієнти. Не знаю, де їх знайти. Сконк більше зосереджений на ремеслі; не дуже розбирається в логістиці.", [3] = "Зберіть інгредієнти для страви Сконка, а потім принесіть їх йому в Араті-Хайлендс.", [4] = "Ви вже знайшли інгредієнти? Майже час вечері.", [5] = "Гарна робота, друже {раса}. Тепер ми справді готуємо!", ["en"] = "A Quick Grocery Run" },
    [79678] = { [1] = "Тестування смаку", [2] = "Добре, друже {раса}, час для улюбленої страви Сконка. Сконк розігрів вогонь і хоче поділитися новою стравою з новим другом. Ти робиш таку велику послугу для Сконка; тобі також варто взяти трохи!\n\nПовідом Сконку, коли будеш готовий скуштувати.", [3] = "Спробуйте рецепт на смак за допомогою Сконку.", [5] = "Ммм, рецепт чудовий!\n\nСконк трохи загубився в пристрасті моменту, але ти був гарним помічником!\n\nОсь твоя частка. Сконк навіть додав трохи додаткового за твою працю.", ["en"] = "Taste Testing" },
    [797] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [79704] = { [1] = "Рятувальний 9000!", [2] = "Вставте свій утиль у машину та отримайте казкові призи! Можливо. Можливо.", [3] = "Вставте забруднену брудом монету Утилізатор 9000 та переконайтеся, що у вас є три срібні монети, щоб запустити машину.", [4] = "Машина здригається та трясеться, перш ніж вивергнути купу утилізованої продукції.", ["en"] = "The Salvagematic 9000!" },
    [79705] = { [1] = "Врятувати рятівне", [2] = "Гадаю, ця штука вже майже помирає, друже. Можливо, я зможу її полагодити, але це буде нелегко... чи дешево. Знаєш що, принеси мені 10 міфрилових злитків, 5 гран містичної есенції, 3 картриджні запобіжники GG12-082 та процесор чистий G-7 C.O.R.E., і я, мабуть, зможу її тобі полагодити. Картриджних запобіжників має бути вдосталь тут, у Гномреґані, але ядро процесора — досить рідкісний предмет, і його не так легко знайти. Але ти виглядаєш досить винахідливим, тому я впевнений, що ти розберешся! Удачі!", [3] = "Принеси Зірі \"Гайковий ключ\" 10 міфрилових злитків, 5 Великої містичної сутності, 3 картриджні запобіжники GG12-082 та чистий процесор G-7 C.O.R.E., і вона зможе змусити Утилізатор 9000! працювати на тебе. Ймовірно. Можливо.", [4] = "Ого, ти справді притягнув сюди весь цей мотлох? Я просто жартував з тобою, але ж я гном свого слова і не з тих, хто витрачає якісні матеріали. Дай мені трохи, і я заведу цю крихітку в робоче русло!", [5] = "Один Утилізатор 9000 готовий до роботи, як і обіцяв. Якщо раптом знайдеш щось корисне, приходь до мене. Можливо, я зможу тебе чогось навчити, за певну плату, звісно!\n\n<Зірі широко посміхається і засовує щось у задню кишеню>", ["en"] = "Salvaging the Salvagematic" },
    [79731] = { [1] = "Трольський сувій", [2] = "<Стародавні гліфи перетворюються на слова прямо перед вашими очима.>\n\nКоли фонтан Зул'Кунди наповнюється водами святого джерела, боги дарують своє благословення.", [3] = "Розгадайте загадку сувою. Як тільки ви це зробите, Гемет Несінґварі, можливо, захоче почути історію.", [5] = "Чарівний фонтан, захований у джунглях? Що за історія, {ім'я}!\n\nЦе дає мені ідею для ще одного розділу в моїй книзі! Подивимося, куди я подів той рукопис...", ["en"] = "The Troll Scroll", ["tasks"] = { ["Learn: Solve the riddle"] = "Навчіться: Розгадайте загадку" } },
    [798] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [7981] = { [1] = "1200 купонів — амулет Темного місяця", [4] = "Підходь, підходь! Якщо у тебе є купони ярмарку Темного місяця, які ти хочеш обміняти, просто скажи! Ти можеш обміняти різну кількість купонів на чудові та фантастичні призи. Не соромся, спробуй!", [5] = "Тримай, тримай! Приз, гідний {стать:короля:королеви}! Вітаю тебе, {стать:друже:подруго}!\n\nЯкщо у тебе є ще купони, які ти хочеш здати, будь ласка, дай мені знати! Я зможу обміняти твої купони лиш поки триває ярмарок Темного місяця.", ["en"] = "1200 Tickets - Amulet of the Darkmoon", ["tasks"] = { ["Darkmoon Faire Prize Ticket"] = "призовий купон ярмарку Темного місяця", ["Darkmoon Faire Prize Ticket (Provided)"] = "призовий купон ярмарку Темного місяця (видано)" } },
    [799] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [79947] = { [1] = "Геомантія: Холодна правда", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Geomancy: The Stone-Cold Truth", ["tasks"] = { ["Geomancy: The Stone-Cold Truth"] = "Геомантія: Холодна правда" } },
    [79948] = { [1] = "Захисна магія 101", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Defensive Magics 101", ["tasks"] = { ["Defensive Magics 101"] = "Захисна магія 101" } },
    [79949] = { [1] = "Павутиння брехні: розвінчування міфів та легенд", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "A Web of Lies: Debunking Myths and Legends", ["tasks"] = { ["A Web of Lies: Debunking Myths and Legends"] = "Павутиння брехні: розвінчування міфів та легенд" } },
    [79950] = { [1] = "Демони та ти", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Demons and You", ["tasks"] = { ["Demons and You"] = "Демони та ти" } },
    [79951] = { [1] = "Мумії: Путівник по неприємним немертвим", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Mummies: A Guide to the Unsavory Undead", ["tasks"] = { ["Mummies: A Guide to the Unsavory Undead"] = "Мумії: Путівник по неприємним немертвим" } },
    [79952] = { [1] = "РвлРвлРвлРвл!", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "RwlRwlRwlRwl!", ["tasks"] = { ["RwlRwlRwlRwl!"] = "РвлРвлРвлРвл!" } },
    [79953] = { [1] = "Посібник лудита з догляду за вашим демонічним домашнім улюбленцем", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "A Ludite's Guide to Caring for Your Demonic Pet", ["tasks"] = { ["A Luddite's Guide to Caring for Your Demonic Pet"] = "Посібник луддита з догляду за вашим демонічним домашнім улюбленцем" } },
    [79974] = { [1] = "Мокра робота", [2] = "Завжди люблю тримати запасний запас під рукою на випадок, якщо доведеться терміново тікати.\n\nВигляд цього гірського схилу такий прекрасний, що можна сказати, що його висікли водоспади часу.\nЦе орлине гніздо, саме це ви шукаєте.", [3] = "Обтрушуючи пил із сумки, що виринає з землі, ви знаходите пергамент, захований серед припасів.", [5] = "Гномська інженерія завжди дивувала.", ["en"] = "Wet Job" },
    [79975] = { [1] = "Кулак Орла", [2] = "Ви знаходите ретельно складеного листа всередині скриньки з інструментами. Уявляючи собі голос, що говорить, ви читаєте: «Звідси, з правильними інструментами, ви керуватимете. Чудове місце для запуску парашутного планера.\n\nМоя вірність Орлу та Кулаку вимагає дистанції, щоб служити їм якнайкраще. Ця барикада мала кращі часи, як і Старі Королівства, які вона колись захищала, але я ніколи її не покину».", [3] = "Водяні бризки зволожують повітря, краєвид неймовірний.", [5] = "Багаття щойно підживили дровами, але ознаки швидкого відходу очевидні.", ["en"] = "Eagle's Fist" },
    [79976] = { [1] = "Це має бути те місце", [2] = "«Отже, я вирішив повернути свою роботу під землю. Щоб вона не потрапила в чужі руки».\n\nПапір порваний якраз достатньо, щоб вмістилося повідомлення. Ви не впевнені, чи це останні слова, які прочитаєте від автора, чи це підказка до наступного сховища. Недостатньо закріплений спальний мішок розгортається вам на ноги...", [3] = "Хто б тут не був, ти його щойно розминувся.", [5] = "Важкий брезент намотують на різноманітне спорядження. Ви беретеся за рюкзак.", ["en"] = "This Must Be The Place" },
    [79980] = { [1] = "Скрембл", [2] = "Не так вже й погано, еге ж? Оскільки ти це читаєш, це означає, що мій запас все ще там. Зроби сто кроків на північ і не зламай щиколотки, спускаючись крутим схилом. Тут має бути достатньо, щоб тобі вистачило.", [3] = "Знайди те, що тебе чекає.", [5] = "Ти витягуєш із землі сумку-посиденьку. Усередині, разом з припасами, лежить брудний пергамент.", ["en"] = "Scramble" },
    [79981] = { [1] = "Кородоване ядро", [2] = "Цей пристрій C.O.R.E. точно відповідає опису, який вам дав Зірі, але він сильно пошкоджений і вкритий брудом. Ви ледве можете розгледіти вицвілу наклейку з тим, що схоже на контактну інформацію для якоїсь гарантії. Видно лише кілька літер.\n\n«Обмеження... гарантія... претензії... контакт.... З..... нде...ар»", [3] = "Знайдіть когось, хто може відремонтувати пошкоджений кородією процесор G-7 C.O.R.E.", [4] = "Коли хтось будує вежу та майстерню на вершині велетенського шпиля посеред ніде, це майже як несподівані гості. Хто б міг подумати?", [5] = "<Збільшувальні окуляри Вірдала видають тихий механічний звук дзижчання, коли фокусуються на кородованому процесорі G-7 C.O.R.E. у вашій руці> Дійсно, це один з моїх.\n\nЯ наполегливо раджу вам викинути цю штуку в океан і більше ніколи про неї не думати.", ["en"] = "The Corroded Core", ["tasks"] = { ["Corroded G-7 C.O.R.E. Processor"] = "Кородований процесор G-7 C.O.R.E." } },
    [79982] = { [1] = "Гарантійна претензія", [2] = "Я можу полагодити цей процесор для вас, але мені потрібен дещо важкодоступний предмет: Заряджене Порожнече Ядро. Відомо, що заклинателі-нага носять їх із собою, і хоча я не можу бути впевненим, звідки наги їх беруть або як їх виготовляють, вони зазвичай діють як потужні осередки для певних видів магічних ритуалів. Вони є ключовим компонентом мого процесора G-7 C.O.R.E. Вони не поширені, тому вам може бути важко його знайти.", [3] = "Принесіть Вірдалу Чудо-ґеар Заряджене Порожнече.", [4] = "Мене лякає думка про те, скількох Наг тобі довелося перебити, щоб отримати цю штуку.", [5] = "Ну, тут нічого.\n\nЯ зобов'язаний зробити вам застереження, що я не несу відповідальності за будь-які електричні пожежі, спалахи електромагнітних імпульсів, демонічні прояви чи міжвимірні вихори, які можуть виникнути внаслідок встановлення та використання цього процесора.", ["en"] = "Warranty Claim" },
    [79984] = { [1] = "Квадрангуляція", [2] = "Вірдал? Так, я його знаю. Він гном, але я не буду мати на нього за це претензій як такий самий ентузіаст трансполіпорцій, як і я. Він вилетів звідси кілька місяців тому кудись у Калімдор, але час від часу заїжджає, щоб купити припаси. Я, мабуть, міг би трансполіпортувати тебе до нього, але тобі знадобляться його координати, або я, мабуть, просто телепортую тебе в гору чи кудись кудись. Якщо ти зможеш знайти його чотирикутні маяки в Калімдорі та налаштуватися на них, це спрацює!", [3] = "Знайдіть чотирикутні маяки Вірдала Чудо-гіра та налаштуйтеся на них. Їх чотири, і вони розташовані десь у Калімдорі.", [4] = "Ви знайшли маяки?", [5] = "Ого, ви їх знайшли. Дайте мені секунду, щоб ввести координати та відкалібрувати транспондер...\n\n... і ось почалося! Думаю, це має спрацювати.", ["en"] = "Quadrangulation" },
    [79985] = { [1] = "Халепа", [2] = "<Кернобі стогне.> Що.. Що сталося?\n\nОстаннє, що я пам'ятаю, це те, як мене захопила група темних залізних гномів, побила майже до смерті, а потім кинула сюди з цими брудними троґами.\n\nВитягніть мене звідси, {ім'я}!\n\nОсь план: проведіть мене до виходу; якщо ми виберемося живими, вирушайте до Бухти Здобичі та повідомте Скуті, що я пішов до Ретчета, щоб попередити Тінкервіза про причетність темного заліза до створення цієї супер-вишки.\n\nХодімо!", [3] = "Супроводьте Кернобі до виходу з Механічного переходу, а потім з'явіться до Скуті в Грабіжній Бухті.", [5] = "Гадаю, тебе слід винагородити за те, що ти повернув нам Кернобі цілим і неушкодженим, {ім'я}. Якщо ти повернешся до Гномреґану, це може дати тобі перевагу, необхідну для перемоги над тим нікчемним підступником, Мекгініром Термоштепселем.", ["en"] = "A Fine Mess", ["tasks"] = { ["Kernobee Rescue"] = "Рятувальний майданчик Кернобі" } },
    [79986] = { [1] = "Вкритий брудом перстень", [2] = "Ви знайшли щось схоже на перстень з трупа одного з дворфів Темного Заліза. Однак важко сказати, що це за перстень; бруд і затверділі залишки повністю покривають предмет, що робить його неможливим для носіння. Вам здається, що ви можете розгледіти легкий блиск дорогоцінного металу і, можливо, навіть відблиск дорогоцінного каміння під залишками.\n\nЯкщо ви збираєтеся використовувати цей перстень, вам потрібно буде знайти щось, щоб видалити з нього затверділі залишки.", [3] = "Знайдіть спосіб видалити бруд з кільця, покритого брудом.", [4] = "Гномський пристрій перед вами має табличку з назвою «Блискочист 5200». Суть машини, судячи з інструкцій під табличкою, полягає у видаленні бруду, який може бути на предметі. Машина має слот для монет, який приймає три срібні монети для початку процесу після того, як предмет поміщено всередину.\n\nЗдається, що кільце з забрудненим брудом, яке ви знайшли раніше, саме те, що варто спробувати в цій машині!", [5] = "Ви поміщаєте кільце всередину Блискочист 5200 та вставляєте срібну монету в отвір.\n\nЗ машини лунають болісні скрегітливі звуки, коли вона починає сильно смикатися. Можна лише здогадуватися, що відбувається з кільцем всередині машини...\n\nМашина раптово зупиняється, трубячи про своє припинення простим «Дзінь!». Відсік для предметів відкривається, показуючи маленьку коробочку, акуратно загорнуту червоним бантом. Схоже, що Блискочист 5200 також пакує подарунки!", ["en"] = "Grime-Encrusted Ring", ["tasks"] = { ["Item #216661"] = "Товар №216661" } },
    [800] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [80001] = { [1] = "Відродити", [4] = "Згашене вогнище. Деревина навіть достатньо суха, щоб спалахнути.", [5] = "Ви застосовуєте свої скаутські навички.", ["en"] = "Rekindle", ["tasks"] = { ["Flint and Tinder"] = "кремінь і трут", ["Simple Wood"] = "проста деревина" } },
    [80098] = { [1] = "Цікава реліквія Даларана", [4] = "Ви знайшли одну з викрадених реліквій?", [5] = "Дякую, {ім'я}. Я подбаю про те, щоб це безпечно повернули до міста.", ["en"] = "Curious Dalaran Relic" },
    [801] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [80120] = { [1] = "Служба Даларану", [5] = "Ви зробили велику послугу для Даларана та для Азероту.\n\nНаші закони забороняють мені ділитися секретами Даларана зі сторонніми, але я думаю, що можу трохи посилити правила, щоб винагородити вас за ваші зусилля. Будь ласка, візьміть це.", ["en"] = "A Service to Dalaran" },
    [80142] = { [1] = "Завдання Трубоплава", [2] = "Майстер-механік Кастпайп з Залізогарта потребує шукачів пригод! Він організовує групи для повернення до Гномреґану з місією з пошуку даних найвищої безпеки та важливості.\n\nКастпайп може й не є членом Освіченої Асамблеї Арканології, Алхімії та Інженерних Наук, як я, але він все ще розумний гном, тому якщо він вважає це важливим, то, за моїми розрахунками, існує вісімдесят чотиривідсоткова ймовірність того, що це справді важливо!\n\nЦе непогані шанси!", ["en"] = "Castpipe's Task" },
    [80147] = { [1] = "Цікава реліквія Даларана", [4] = "Ви знайшли одну з викрадених реліквій?", [5] = "Дякую, {ім'я}. Я подбаю про те, щоб це безпечно повернули до міста.", ["en"] = "Curious Dalaran Relic" },
    [80148] = { [1] = "Цікава реліквія Даларана", [4] = "Ви знайшли одну з викрадених реліквій?", [5] = "Дякую, {ім'я}. Я подбаю про те, щоб це безпечно повернули до міста.", ["en"] = "Curious Dalaran Relic" },
    [80149] = { [1] = "Цікава реліквія Даларана", [4] = "Ви знайшли одну з викрадених реліквій?", [5] = "Дякую, {ім'я}. Я подбаю про те, щоб це безпечно повернули до міста.", ["en"] = "Curious Dalaran Relic" },
    [80150] = { [1] = "Цікава реліквія Даларана", [4] = "Ви знайшли одну з викрадених реліквій?", [5] = "Дякую, {ім'я}. Я подбаю про те, щоб це безпечно повернули до міста.", ["en"] = "Curious Dalaran Relic" },
    [80151] = { [1] = "Цікава реліквія Даларана", [4] = "Ви знайшли одну з викрадених реліквій?", [5] = "Дякую, {ім'я}. Я подбаю про те, щоб це безпечно повернули до міста.", ["en"] = "Curious Dalaran Relic" },
    [80152] = { [1] = "Цікава реліквія Даларана", [4] = "Ви знайшли одну з викрадених реліквій?", [5] = "Дякую, {ім'я}. Я подбаю про те, щоб це безпечно повернули до міста.", ["en"] = "Curious Dalaran Relic" },
    [80153] = { [1] = "Блискочист 5200!", [2] = "Цей пристрій виділяється серед гномів, які протистоять божевіллю зовні кімнати. Невелика табличка на пристрої говорить «Блискочист 5200», а потім текст:\n\n«Бруд та залишки псують ваші блискітки? Блискочист 5200 повертає блиск! Вставте предмет, який ви хочете почистити, та покладіть три срібні монети у отвір для монет. Дайте Блискочист 5200 хвилинку, щоб він спрацював, і вуаля! Ваші цінності вийдуть чистими та блискучими!»", [3] = "Вставте предмет із забрудненням брудом у Блискочист 5200 та переконайтеся, що у вас є три срібні монети, щоб запустити пристрій.", [4] = "Здається, що для очищення пристрою потрібен якийсь предмет, покритий засохлим брудом, і три срібні монети, щоб запустити його. Якщо обидва є, Блискочист 5200 має працювати...", [5] = "Ви вставляєте забруднений брудом предмет і три срібні монети в Блискочист 5200. Машина оживає в шаленій спробі очистити невідомий предмет від бруду. Гучні, сильні звуки бурчання вириваються з серця машини. Металевий каркас звіра скрипить і стогне, коли він хитається з боку в бік...", ["en"] = "The Sparklematic 5200!" },
    [80155] = { [1] = "Блискочист знову в дії", [4] = "Блискочист 5200 порожній, чекає на предмет, забруднений брудом, для очищення та три срібні монети для початку роботи!", [5] = "Блискочист 5200 оживає, хитаючись туди-сюди. Усередині безпорадний бруд, що вкрив предмет, поміщений у нього, подрібнюється гномським засобом для чищення машини.\n\nБлискочист 5200 зупиняється, сповіщаючи про це знайомим \"дзинь!\". Відсік для предметів машини спірально відкривається, показуючи акуратно загорнуту коробку.", ["en"] = "More Sparklematic Action" },
    [80156] = { [1] = "Блискочист 5200!", [2] = "Цей пристрій виділяється серед гномів, які протистоять божевіллю зовні кімнати. Невелика табличка на пристрої говорить «Блискочист 5200», а потім текст:\n\n«Бруд та залишки псують ваші блискітки? Блискочист 5200 повертає блиск! Вставте предмет, який ви хочете почистити, і покладіть три срібні монети у отвір для монет. Дайте Блискочист 5200 хвилинку, щоб він попрацював, і вуаля! Ваші цінності вийдуть чистими та блискучими!»", ["en"] = "The Sparklematic 5200!" },
    [80157] = { [1] = "Блискочист 5200!", [5] = "Так само швидко, як і запустився, Блискочист 5200 різко зупинився. З машини чути просте «дзвін», і рот машини спіралеподібно піднімається вгору. Усередині Блискочист 5200 знаходиться невелика коробка, загорнута в маленький бант. Здається, що машина загортає предмет після видалення його забрудненого стану. Навіть якщо машина не працювала, принаймні предмет тепер загорнутий у гарну коробку.\n\nЩо ж, є один спосіб дізнатися, чи очистила вона предмет чи ні...", ["en"] = "The Sparklematic 5200!" },
    [80158] = { [1] = "Блискочист 5200!", [2] = "Цей пристрій виділяється серед гномів, які протистоять божевіллю зовні кімнати. Невелика табличка на пристрої говорить «Блискочист 5200», а потім текст:\n\n«Бруд та залишки псують ваші блискітки? Блискочист 5200 повертає блиск! Вставте предмет, який ви хочете почистити, та покладіть три срібні монети у отвір для монет. Дайте Блискочист 5200 хвилинку, щоб він спрацював, і вуаля! Ваші цінності вийдуть чистими та блискучими!»", [3] = "Вставте предмет із забрудненням брудом у Блискочист 5200 та переконайтеся, що у вас є три срібні монети, щоб запустити пристрій.", [4] = "Здається, що для очищення пристрою потрібен якийсь предмет, покритий засохлим брудом, і три срібні монети, щоб запустити його. Якщо обидва є, Блискочист 5200 має працювати...", [5] = "Ви вставляєте забруднений брудом предмет і три срібні монети в Блискочист 5200. Машина оживає в майже шаленій спробі очистити невідомий предмет від бруду. Гучні, сильні звуки бурчання вириваються з серця машини. Металевий каркас звіра скрипить і стогне, коли він хитається з боку в бік...", ["en"] = "The Sparklematic 5200!" },
    [80160] = { [1] = "Блискочист знову в дії", [4] = "Блискочист 5200 порожній, чекає на предмет, забруднений брудом, для очищення та три срібні монети для початку роботи!", [5] = "Блискочист 5200 оживає, хитаючись туди-сюди. Усередині безпорадний бруд, що вкрив предмет, поміщений у нього, подрібнюється гномським засобом для чищення машини.\n\nБлискочист 5200 зупиняється, сповіщаючи про це знайомим \"дзинь!\". Відсік для предметів машини спірально відкривається, показуючи акуратно загорнуту коробку.", ["en"] = "More Sparklematic Action" },
    [80161] = { [1] = "Блискочист 5200!", [5] = "Так само швидко, як і запустився, Блискочист 5200 різко зупинився. З машини чути просте «дзвін», і рот машини спіралеподібно піднімається вгору. Усередині Блискочист 5200 знаходиться невелика коробка, загорнута в маленький бант. Здається, що машина загортає предмет після видалення його забрудненого стану. Навіть якщо машина не працювала, принаймні предмет тепер загорнутий у гарну коробку.\n\nЩо ж, є один спосіб дізнатися, чи очистила вона предмет чи ні...", ["en"] = "The Sparklematic 5200!" },
    [80167] = { [1] = "Великі ракети", [4] = "Великі Фестивальні ракети яскраво освітлюють небо — лише кластерні ракети можуть зрівнятися з їхньою пишнотою!\n\nПринесіть мені монети предків, {ім'я}, і я поділюся знаннями про їхнє створення.", [5] = "Добре — я приймаю ці монети походження. Ось твої рецепти, {ім'я}. Нехай ти використовуєш їх для поширення слави Елуни!", ["en"] = "Large Rockets" },
    [80168] = { [1] = "Пускова установка для феєрверків", [4] = "Хоча ракети — чудовий спосіб святкувати, щоб побачити їхню славу... їх потрібно запускати з пускової установки.\n\nПринесіть мені монети предків, і я можу запропонувати вам знання для створення ракетних установок, подібних до тих, що ви бачите в Мунґлейді.", [5] = "Ось тобі, {ім'я}. Ось схема створення установки для запуску феєрверків. Розмістіть установки там, де ви хочете святкувати, а потім запросіть своїх друзів приєднатися до вас!", ["en"] = "Firework Launcher" },
    [80169] = { [1] = "Пускова установка для залпів феєрверків", [4] = "Найрозкішніші феєрверки мають включати касетні ракети, і ці касетні ракети мають бути запущені з касетних пускових установок! Хіба ж не логічно, що ви навчитеся секретів виготовлення касетних пускових установок? Принесіть мені монети походження, і я передам вам ці знання.", [5] = "Ось ваша схема. Уважно вивчіть її та дізнайтеся...\n\nУдачі, {ім'я}. Нехай ваші свята зрівняються зі святкуванням самого Місячного фестивалю!", ["en"] = "Cluster Launcher" },
    [80170] = { [1] = "Святкові викройки", [4] = "Сукні та брючні костюми, які ви бачите, – це традиційний одяг з багатьох минулих років. Його носять на честь старих звичаїв та померлих близьких.\n\nЯкщо ви принесете мені монети предків, {ім'я}, то я дам вам викрійку для створення традиційних червоних суконь або костюмів.", [5] = "Ось ці патерни, {ім'я}. Я впевнений, що ви знайдете результат цих знань досить гарним.", ["en"] = "Festive Recipes" },
    [802] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [8021] = { [1] = "Активуйте призовий ваучер iCoke", ["en"] = "Redeem iCoke Prize Voucher", ["tasks"] = { ["iCoke Prize Voucher"] = "Призовий ваучер iCoke" } },
    [8022] = { [1] = "Активуйте призовий ваучер iCoke", ["en"] = "Redeem iCoke Prize Voucher", ["tasks"] = { ["iCoke Prize Voucher"] = "Призовий ваучер iCoke" } },
    [8023] = { [1] = "Активуйте призовий ваучер iCoke", ["en"] = "Redeem iCoke Prize Voucher", ["tasks"] = { ["iCoke Prize Voucher"] = "Призовий ваучер iCoke" } },
    [8024] = { [1] = "Активуйте призовий ваучер iCoke", ["en"] = "Redeem iCoke Prize Voucher", ["tasks"] = { ["iCoke Prize Voucher"] = "Призовий ваучер iCoke" } },
    [8025] = { [1] = "Активуйте призовий ваучер iCoke", ["en"] = "Redeem iCoke Prize Voucher", ["tasks"] = { ["iCoke Prize Voucher"] = "Призовий ваучер iCoke" } },
    [8026] = { [1] = "Активуйте призовий ваучер iCoke", ["en"] = "Redeem iCoke Prize Voucher", ["tasks"] = { ["iCoke Prize Voucher"] = "Призовий ваучер iCoke" } },
    [803] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [80307] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment" },
    [80308] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment" },
    [80309] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment" },
    [8041] = { [1] = "Сила гори Муґамба", [5] = "Вітаю, {клас:к}. Я Джін'рох Руйнівник, троль з Муґамби. Ми, з племені Зандалар, визнаємо твої досягнення. Ми вітаємо твою завзятість і силу волі.\n\nНоси цей талісман на шиї, {клас:к}. Нехай сила гори Муґамба пронизує твоє єство. Будь {стать:сильним:сильною}, коли будеш нищити наших ворогів!", ["en"] = "Strength of Mount Mugamba" },
    [80411] = { [1] = "Талісман Каздора", [2] = "З останнього перехопленого нами листа випливає, що останнім артефактом, який бажає Кай, є Талісман Каздора. У листі йдеться, що цей талісман знаходиться десь у Зул'Фарраку.\n\nЯ хочу, щоб ти виконав завдання згідно з інструкціями Кая, щоб не викликати його підозр. Це означає, що тобі доведеться піти до Зул'Фарраку самому, як завжди.\n\nОднак, перш ніж доставити Талісман, принеси його сюди. Ми дамо Каюсу трохи більше, ніж він просив.", [3] = "Знайдіть Талісман Каздора всередині Зул'Фаррака. Потім принесіть його Фаграду в маєток Рейвенгольдт. Ви повинні виконати завдання самостійно.", [4] = "Іди зараз, час має вирішальне значення.", [5] = "Справді непогана крадіжка, {ім'я}. А тепер час для кроку другого.", ["en"] = "The Talisman of Kazdor" },
    [80417] = { [1] = "М'які пухнасті хвости", [4] = "Дивовижно, що цінують люди! Візьмемо, наприклад, дерев'яну палицю з м'яким пухнастим хвостом, прикріпленим до неї. Ми з вами можемо подумати, що щось таке не таке вже й цінне... але якщо ви дасте цьому шматку мотлоху гарне ім'я, наприклад, «Дикий Пухнастий Хвіст», і покладете його в гарну коробку, тоді люди вважатимуть його цінним. Сміття стає скарбом!\n\nПринесіть мені м'які пухнасті хвости від вовків Спустошення та Безпліддя, і я подарую вам квитки на Ярмарок Новомісяччя.", [5] = "Молодець, {ім'я}! Ці хвости стануть чудовими призами для наших відвідувачів, а це означає щасливих відвідувачів... які спілкуються зі своїми друзями та приводять ще більше відвідувачів!\n\nОсь ваші квитки! Гарно проведіть час на Ярмарку Молодика... і не забудьте розповісти про нас своїм друзям!", ["en"] = "Soft Bushy Tails" },
    [8042] = { [1] = "Сила гори Муґамба", [4] = "Радий бачити тебе в доброму здоров'ї, {ім'я}. Славні битви, в яких ти {стать:брав:брала} участь, впливають на життя всього світу. Гаккар не повинен залишати межі Зул'Ґуруба, інакше він поглине весь світ.\n\nДай мені свій талісман, і я наповню його силою. Використовуй силу Муґамби, щоб покарати наших ворогів!", [5] = "Наші шляхи ще перетнуться, {клас:к}.", ["en"] = "Strength of Mount Mugamba", ["tasks"] = { ["Strength of Mugamba"] = "сила Муґамби", ["Strength of Mugamba (Provided)"] = "сила Муґамби (видано)" } },
    [80421] = { [1] = "Зелені залізні браслети", [4] = "Я працюю над новим костюмом, на той час, коли в мене буде власний стенд найсильнішої жінки на світі! Зараз я шукаю наручі, які можна носити. Вони не можуть багато приховати, бо люди хочуть бачити мої м'язи, але я все одно хочу трохи блиснути кольором, розумієте?\n\nЯк щодо зелених залізних наручів, {ім'я}? Чи можете ви зробити мені зелені залізні наручі? Якщо можете, то в мене є ціла купа квитків на ярмарок Новомісяця для вас.", [5] = "Так! Це саме те, що мені потрібно! Такий гарний колір, і вони все одно залишають мої руки оголеними, тож ви можете бачити, які вони міцні! Ідеально!\n\nОсь вам, {ім'я}. Ось ваші квитки — насолоджуйтесь!", ["en"] = "Green Iron Bracers" },
    [80422] = { [1] = "Зелені феєрверки", [4] = "Коли я нарешті запущу цей стенд, я захочу розмістити рекламу! А що може бути кращим способом реклами, ніж феєрверки?\n\nНу, дехто може подумати, що запах казана, в якому киплять голови твоїх ворогів, краще приваблює натовпи, але... ми в неоднозначній компанії. Тож доведеться влаштувати феєрверк!\n\nПринеси мені зелений феєрверк, {ім'я}, і в мене є для тебе велика жменя квитків на ярмарок Новомісяця.", [5] = "Ви принесли феєрверки. Чудова робота, {ім'я}! Не можу дочекатися, щоб запалити їх і розповісти світові, що мій стенд готовий! Мені ще доведеться чекати, боюся, досить довго, але... Я буду готовий, коли буду готовий, так?\n\nОсь квитки, {ім'я}. Насолоджуйтесь!", ["en"] = "Green Fireworks" },
    [80423] = { [1] = "Найбільший у світі гном!", [4] = "Єбб Небблгір прагне додати більше акторів до свого шоу та шукає найбільшого гнома у світі. Чи знаєте ви якихось гномів значних розмірів?\n\nЗадовго до того, як він знайде гнома, він хоче підготувати його костюм. Я думаю, що варварська збруя була б гарною основою для костюма; чи можете ви зробити кілька збруй та принести їх мені? Зробіть це, і в мене буде для вас ціла купа квитків на ярмарок Новомісяччя...", [5] = "Ой, вони досить великі!! Не можу уявити собі гнома, який би щільно в них помістився, але не хвилюйтеся — якщо знайдений нами гном недостатньо великий, я можу внести корективи в його костюм.\n\nЩиро дякую, {ім'я}. Ось квитки, які я вам обіцяв.", ["en"] = "The World's Largest Gnome!" },
    [8043] = { [1] = "Сила гори Муґамба", [4] = "{стать:Майстре:Майстрине} {ім'я}, ти {стать:повернувся:повернулася}! Молтор повідомив королю про твої подвиги. Твоє ім'я відоме навіть у Південних морях. Можливо, одного дня ти станеш {стать:легендарним:легендарною} {клас:о} — і на віки залишиш слід в історії.\n\nДай мені свій талісман, щоб я міг знову наповнити його силою.", [5] = "Використовуй свою нову силу, щоб знищити Ґурубаші!", ["en"] = "Strength of Mount Mugamba", ["tasks"] = { ["Strength of Mugamba"] = "сила Муґамби", ["Strength of Mugamba (Provided)"] = "сила Муґамби (видано)" } },
    [8044] = { [1] = "Лють Муґамби", [4] = "Король Растахан передає тобі вітання, {стать:майстре:майстрине} {ім'я}. Такої честі ніколи не надавали нікому, хто не належить до племені Зандалар.\n\n<Джін'рох вклоняється.>\n\nДай мені свій талісман, щоб я міг ще раз його посилити. Знай, що лють Муґамби тепер нерозривно пов'язана з твоєю душею.", [5] = "Зул'джин позаздрив би тобі, {клас:к}. Вперед до завоювань!", ["en"] = "The Rage of Mugamba", ["tasks"] = { ["Strength of Mugamba"] = "сила Муґамби", ["Strength of Mugamba (Provided)"] = "сила Муґамби (видано)" } },
    [8045] = { [1] = "Тавро язичника", [5] = "Знай, {стать:язичнику:язичнице}: нас змусила об'єднатися катастрофа. Твої язичницькі звичаї не розуміють і не цінують в Зандаларі, але ми справедливий народ. Носи це тавро на шиї. Воно буде попередженням для наших ворогів і символом твоєї дружби з Зандаларами.\n\nПродовжуй служити нашому народу, і я збільшу силу цього тавра.", ["en"] = "The Heathen's Brand" },
    [80453] = { [1] = "Найкраще продумані плани", [2] = "Віднесіть талісман до Зана Шівспрокета, у підвал. Я попросив його оснастити артефакт механізмом, який виявить будь-яку спробу спрямувати магічну енергію в нього або з нього.\n\nМеханізм майже невидимий неозброєним оком і детонує при спрацьовуванні. Якщо пощастить, Кай загине під час вибуху. Як мінімум, його плани щодо талісмана будуть зірвані.", [3] = "Принесіть Талісман Каздора Зану Шівспрокету в підвалі маєтку Рейвенгольдт.", [4] = "Так, {клас}? Вам щось від мене потрібно?", [5] = "Тож ти працюєш у Фахрада, га? Добре. Дай мені талісман, і я візьмуся за роботу.", ["en"] = "Best Laid Plans", ["tasks"] = { ["Talisman of Kazdor"] = "Талісман Каздора" } },
    [80454] = { [1] = "Остання крапля", [2] = "Приманка готова, тепер треба поставити пастку. Я модифікував талісман згідно з інструкціями Фаграда. Залишилося лише доставити його, як ви вже донесли інші артефакти.\n\nІдіть до хатини біля села Пірвуд і покладіть цей модифікований талісман у схованку Кая.\n\nЩо буде далі, поки що нам не вирішувати.", [3] = "Віднесіть Модифікований Талісман до схованки Кая біля села Пайрвуд.", [4] = "<Скриня стоїть порожня.>", [5] = "<Ви кладете Модифікований Талісман у скриню.>", ["en"] = "One Last Drop", ["tasks"] = { ["Modified Talisman"] = "Модифікований Талісман" } },
    [80455] = { [1] = "Вичікуючи свого часу", [2] = "Роботу зроблено. Краще повернися до Рейвенгольдта та повідоми Фаррада.", [3] = "Доповісти Фаграду в садибі Равенгольдт.", [5] = "Здається, все пішло за планом. Гарна робота.\n\nТепер нам залишається лише чекати на наступний крок Кая. Я повідомлю тебе, коли настане цей час. Твої зобов'язання перед маєтком ще не повністю виконані.\n\nОднак поки що можеш бути спокійним.", ["en"] = "Biding Our Time" },
    [8046] = { [1] = "Тавро язичника", [4] = "Можливо, я був надто поспішним у своїх судженнях, {клас:к}. Здається, що твоя сліпа віра в це Світло все ж таки має якусь цінність.\n\nВіддай мені своє тавро, і я збільшу його силу.", [5] = "Роби те, що маєш, щоб перемогти наших ворогів, {клас:к}. Навіть якщо це означає використовувати Світло.\n\n<Джін'рох здригається.>", ["en"] = "The Heathen's Brand", ["tasks"] = { ["Heathen's Brand"] = "тавро язичника", ["Heathen's Brand (Provided)"] = "тавро язичника (видано)" } },
    [8047] = { [1] = "Тавро язичника", [4] = "Мушу зізнатися, я не думав, що у тебе вистачить рішучості довести цю справу до кінця, {клас}. Зандалари тепер вважають тебе {стать:важливим союзником:важливою союзницею}.\n\nВіддай мені своє тавро, і я ще раз збільшу його силу.", [5] = "Наші вірування різняться, але наша справа праведна. Знищимо наших ворогів, {стать:благородний:благородна} {клас:к}.", ["en"] = "The Heathen's Brand", ["tasks"] = { ["Heathen's Brand"] = "тавро язичника", ["Heathen's Brand (Provided)"] = "тавро язичника (видано)" } },
    [8048] = { [1] = "Тавро героя", [4] = "Король визнав тебе, {клас:к}. Ти {стать:перший:перша} у своєму роді, кого Растахан прийняв як {стать:справжнього союзника:справжню союзницю} Зандаларів.\n\nТи будеш щедро {стать:винагороджений:винагороджена} за свої зусилля. Дай своє тавро, і я застосую останнє посилення.", [5] = "Пильність, честь, вірність, хоробрість... Твоє тавро втілюватиме ці риси так само, як їх втілюєш ти.", ["en"] = "The Hero's Brand", ["tasks"] = { ["Heathen's Brand"] = "тавро язичника", ["Heathen's Brand (Provided)"] = "тавро язичника (видано)" } },
    [8049] = { [1] = "Око Зулдазара", [5] = "Прийми цей талісман на знак нашої вдячності, {клас:к}.\n\nОко Зулдазара зростатиме в силі в міру того, як зміцнюватиметься твій зв'язок з тролями Зандалара. Періодично навідуйся до мене, і я буду посилювати його.", ["en"] = "The Eye of Zuldazar" },
    [8050] = { [1] = "Око Зулдазара", [4] = "Вітаю, {клас:к}. Око Зулдазара пульсує енергією. Ти {стать:готовий:готова} до наступного кроку. Дай мені талісман, і я наповню його чарами.", [5] = "Продовжуй битися проти Здирача Душ і його послідовників, {ім'я}. Не можна дозволити йому покинути межі Зул'Ґуруба.", ["en"] = "The Eye of Zuldazar", ["tasks"] = { ["The Eye of Zuldazar"] = "око Зулдазара", ["The Eye of Zuldazar (Provided)"] = "око Зулдазара (видано)" } },
    [8051] = { [1] = "Око Зулдазара", [4] = "Розповіді про твої битви з Ґурубаші розносяться вітрами, {клас:к}. Про твої подвиги починають говорити навіть королівські особи. Подейкують, що навіть сам король Растахан згадував твоє ім'я.\n\nПередай мені Око — прийшов час наповнити Око чарами.", [5] = "Будь {стать:рішучим:рішучою} у своїх починаннях, {ім'я}. Здирач Душ намагатиметься висмоктати з тебе всю волю до життя.", ["en"] = "The Eye of Zuldazar", ["tasks"] = { ["The Eye of Zuldazar"] = "око Зулдазара", ["The Eye of Zuldazar (Provided)"] = "око Зулдазара (видано)" } },
    [8052] = { [1] = "Всевидюще око Зулдазара", [4] = "Якби ж у нас було ще десять тисяч таких, як ти, {ім'я}. Ми б вмить розгромили армії Гаккара.\n\n<Ал'табім зітхає.>\n\nЩо ж, Око готове реалізувати весь свій потенціал. Віддай його мені.", [5] = "Покарай їх усіх, і нехай вони з Гаккаром відправляться в безодню...", ["en"] = "The All-Seeing Eye of Zuldazar", ["tasks"] = { ["The Eye of Zuldazar"] = "око Зулдазара", ["The Eye of Zuldazar (Provided)"] = "око Зулдазара (видано)" } },
    [80526] = { [1] = "Обдури мене двічі", [2] = "Не зарано, {ім'я}\n\nМаєток стежить за цим персонажем \"C\", з яким ви маєте справу.\n\nСправжня особистість C — Кай Блеквуд; могутній маг, який працює з Синдикатом. Наші джерела кажуть, що він збирав артефакти з невідомою метою. Лише нещодавно ми дізналися, що *ви* були тим, хто їх постачав.\n\nКая потрібно зупинити, і я вважаю, що тягар цього лягає на вас. На щастя, я розробив план. Приходьте поговорити зі мною, коли будете готові очистити своє ім'я.", [3] = "Поговоріть з Фаградом, коли будете готові почути його план.", [5] = "Гаразд тоді, давайте перейдемо до справи.", ["en"] = "Fool Me Twice" },
    [8053] = { [1] = "Взірці могутності: нарукавники вільнодумця", [2] = "Ти {стать:язичник:язичниця}. Язичники мають своє місце в племені. Язичники — це вільнодумці Зандалара. Вільнодумці не бояться пригнічення. Вільнодумці готові померти за свої переконання. Ми знаємо, що ти {стать:готовий:готова} померти за те, у що віриш. Це заслуговує нашого визнання. Це дає тобі можливість показати себе.\n\nНам потрібні взірці могутності. Вирушай в Зул'Ґуруб. Знищ прибічників Гаккара. Повертайся, коли в тебе буде те, що я шукаю. Ти отримаєш перше бойове спорядження зандаларських вільнодумців.\n\nЙди.", [3] = "Принесіть Джін'роху Руйнівнику первісні браслети Гаккарі. Ви також повинні мати репутацію не нижче дружньої з племенем Зандалар.\n\nДжін'рох Руйнівник знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Ти {стать:повернувся:повернулася}? Взірці могутності в тебе? Чи ти марнуєш мій час?\n\nСподіваюся, що ні, {стать:язичнику:язичнице}.", [5] = "Ти багато {стать:зробив:зробила} для нас. Твої руки обагрені кров'ю поплічників Гаккара. Ти {стать:друг:подруга} нашого племені.\n\nОдягни ці браслети. Це нарукавники вільнодумця. Ось що я маю на увазі під справжньою силою.", ["en"] = "Paragons of Power: The Freethinker's Armguards", ["tasks"] = { ["3000 reputation with Zandalar Tribe"] = "3000 репутації у племені Зандалар", ["Primal Hakkari Bindings"] = "первісні браслети Гаккарі", ["Primal Hakkari Bindings (Provided)"] = "первісні браслети Гаккарі (видано)" } },
    [8054] = { [1] = "Взірці могутності: пояс вільнодумця", [2] = "Твої вірування нам чужі, {стать:язичнику:язичнице}. Давні Зандалари колись були визнані єретиками. Це сталося в ті часи, коли імперія Ґурубаші була сильною. Язичники осмілювалися кинути виклик жерцю Гаккара. Язичників переслідували та вбивали, як шкідників. Ці язичники ніколи не зраджували у своїй боротьбі проти Бога крові. Ми шануємо ціну, яку вони заплатили. Вони є вільнодумцями.\n\nЗнищ прибічників Гаккара у Зул'Ґурубі. Принесіть мені взірці могутності, які я шукаю. Успіх буде щедро винагороджений.\n\nЙди.", [3] = "Принесіть Джін'роху Руйнівнику первісну шаль Гаккарі. Ви також повинні мати репутацію не нижче почесної з племенем Зандалар.\n\nДжін'рох Руйнівник знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Твоя присутність означає перемогу? Взірці могутності в тебе? Чи вкриті твої обладунки рештками ворогів?", [5] = "Твоя честь шанується в племені. Ти {стать:забрав:забрала} багато життів у Зул'Ґурубі. Вороги падають перед твоїми переконаннями. Вороги падають перед твоєю силою.\n\nЦе пояс вільнодумця. Це символ честі. Це потужне моджо. Тепер він твій.", ["en"] = "Paragons of Power: The Freethinker's Belt", ["tasks"] = { ["9000 reputation with Zandalar Tribe"] = "9000 репутації у племені Зандалар", ["Primal Hakkari Shawl"] = "первісна шаль Гаккарі", ["Primal Hakkari Shawl (Provided)"] = "первісна шаль Гаккарі (видано)" } },
    [8055] = { [1] = "Взірці могутності: кіраса вільнодумця", [2] = "Бойове спорядження надає тобі силу в племені. Вільнодумці шануються таким чином. Вони фанатики. Вони наповнюють свої кіраси потужним моджо. Їхня віра може похитнутись в бою з ворогом, та не їхня кіраса.\n\nЩоб мати можливість володіти такою кірасою, тебе мають шанувати в нашому племені. Йди в Зул'Ґуруб. Збери взірці могутності. Забери їх у дурнів, що сидять всередині. Принеси їх мені. Доведи раз і назавжди, що ти {стать:гідний бути одним:гідна бути одною} з вільнодумців.", [3] = "Принесіть Джін'роху Руйнівнику первісну накидку Гаккарі. Ви також повинні мати репутацію не нижче шанованої з племенем Зандалар.\n\nДжін'рох Руйнівник знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Взірці у тебе? В них велике моджо. Ми мусимо їх отримати. Ти нам допоможеш.", [5] = "Ти {стать:зробив:зробила} те, що мало кому вдавалося. Ти {стать:поставив:поставила} прибічників Гаккара на коліна. Ти {стать:показав:показала} їм, що може зробити {стать:вільнодумець:вільнодумниця}. Ти {стать:показав:показала} нам, як {стать:єретик:єретичка} може бути {стать:шанованим:шанованою} в племені. Ти не просто маєш силу. Ти і є сила.\n\nПрийми цю кірасу, {стать:вільнодумцю:вільнодумнице}. Розбий своїх ворогів.", ["en"] = "Paragons of Power: The Freethinker's Breastplate", ["tasks"] = { ["21000 reputation with Zandalar Tribe"] = "21000 репутації у племені Зандалар", ["Primal Hakkari Tabard"] = "первісна накидка Гаккарі", ["Primal Hakkari Tabard (Provided)"] = "первісна накидка Гаккарі (видано)" } },
    [8056] = { [1] = "Взірці могутності: браслети авгура", [2] = "Авгури нашого племені шануються за їхній дар духовного бачення, {стать:друже:подруго}. Вони не знахарі — вони проводять свій час, кидаючи кістки або досліджуючи природу, щоб отримать прозріння, а не проклинать всіх. Як {клас}, ти вже знаєш шось про силу авгурів. Ми, Зандалари, цінуєм мудрість, яку вони приносять племені.\n\nПринеси мені взірці могутності з Зул'Ґуруба та доведи свою цінність для нас. Зроби це, і я дам тобі браслети, що ціняться нашими авгурами!", [3] = "Принесіть Майвікі Зулдазарській первісний наруч Гаккарі. Ви також повинні мати репутацію не нижче дружньої з племенем Зандалар.\n\nМайвікі Зулдазарська знаходиться на острові Йоджамба в Тернистій долині.", [4] = "{стать:Приніс:Принесла} мені взірці могутності з Зул'Ґуруба? Ці браслети варті будь-яких зусиль, які тобі доведеться докласти!", [5] = "Здається, що в тобі є шось спільне з авгурами Зандаларів. Ми знаєм про речі, які ти {стать:робив:робила} в Зул'Ґурубі заради нас, {стать:друже:подруго}. Ці взірці могутності дуже поможуть племені Зандалар — племені, до якого, до речі, ти можеш звертаться як до друзів. Візьми ці браслети, {ім'я}, ти {стать:заслужив:заслужила} їх і ще дещо!", ["en"] = "Paragons of Power: The Augur's Bracers", ["tasks"] = { ["3000 reputation with Zandalar Tribe"] = "3000 репутації у племені Зандалар", ["Primal Hakkari Armsplint"] = "первісний наруч Гаккарі", ["Primal Hakkari Armsplint (Provided)"] = "первісний наруч Гаккарі (видано)" } },
    [8057] = { [1] = "Взірці могутності: браслети гаруспіка", [2] = "Гаруспіки є важливими членами нашого племені, і мудро буде дослухатися до їхніх передбачень. Вони спілкуються з тваринами та приносять їх у жертву духам, щоб дізнатися волю Богів. У минулому мудрість і проникливість гаруспіків допомогли нам у війні з розрізненими племенами імперії Ґурубаши.\n\nПринеси мені взірці могутності з Зул'Ґуруба, і доведи свою цінність. Якщо ти це зробиш, я дам тобі браслети, від яких не відмовилися б жодні гаруспіки Зандаларів.", [3] = "Принесіть Майвікі Зулдазарській первісний поруч Гаккарі. Ви також повинні мати репутацію не нижче дружньої з племенем Зандалар.\n\nМайвікі Зулдазарська знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Ти {стать:добув:добула} взірці могутності з Зул'Ґуруба? Ці браслети варті зусиль, {ім'я}. Повір мені, {стать:друже:подруго}!", [5] = "Ах, я відчуваю силу, що йде від цих взірців могутності, {ім'я}. Ти {стать:довів:довела}, що гідна дружби з племенем. Угода є угода, {ім'я}... ось браслети гаруспіка!", ["en"] = "Paragons of Power: The Haruspex's Bracers", ["tasks"] = { ["3000 reputation with Zandalar Tribe"] = "3000 репутації у племені Зандалар", ["Primal Hakkari Stanchion"] = "первісний поруч Гаккарі", ["Primal Hakkari Stanchion (Provided)"] = "первісний поруч Гаккарі (видано)" } },
    [8058] = { [1] = "Взірці могутності: нарукавники поборника", [2] = "Помста — це сила. Саме вона рухає поборниками Зандаларів. У племені багато ворогів, і поборники несуть їм розплату. Жоден злочин проти нас не залишиться безкарним, і поборники виносять вироки. Наші вороги бояться нашої помсти. Так було раніше і так буде завжди\n\nСтань {стать:одним з наших поборників:однією з наших поборниць} правосуддя. Знайди взірці могутності у Зул'Ґурубі. Вразь прислужників Гаккара і помстись за плем'я. Я тебе винагороджу.", [3] = "Принесіть Джін'роху Руйнівнику первісний наруч Гаккарі. Ви також повинні мати репутацію не нижче дружньої з племенем Зандалар.\n\nДжін'рох Руйнівник знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Взірці могутності у тебе? Чи {стать:помстився:помстилася} ти за Зандаларів?", [5] = "Сьогодні було багато помсти. Ти {стать:прийняв:прийняла} подобу {стать:поборника:поборниці}. Ти {стать:поставив:поставила} поплічників Бога крові на коліна.\n\nВізьми це. Це підживить твою помсту в майбутньому. Тепер ти {стать:друг:подруга} Зандаларів.", ["en"] = "Paragons of Power: The Vindicator's Armguards", ["tasks"] = { ["3000 reputation with Zandalar Tribe"] = "3000 репутації у племені Зандалар", ["Primal Hakkari Armsplint"] = "первісний наруч Гаккарі", ["Primal Hakkari Armsplint (Provided)"] = "первісний наруч Гаккарі (видано)" } },
    [8059] = { [1] = "Взірці могутності: обмотки одержимого", [2] = "Чорнокнижники ступають на небезпечний шлях, маючи справу з демонами, але наші одержимі зайшли ще далі. Завдяки давньому та загадковому ритуалу вони дозволяють демонові увійти у своє єство. Замість того, щоб дозволити йому володіти ними, вони підкорюють демона зсередини, поглинаючи силу демона, щоб керувати нею на свій розсуд. Цей подвиг вдалося здійснити одиницям.\n\nЩоб дізнатись про силу одержимих, ти маєш принести мені взірці могутності з Зул'Ґурубу. Йди туди та добудь те, що ми шукаємо.", [3] = "Принесіть Ал'табіму Всевидющому первісний поруч Гаккарі. Ви також повинні мати репутацію не нижче дружньої з племенем Зандалар.\n\nАл'табім Всевидющий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Ти {стать:повернувся:повернулася} з взірцями могутності? Перемігши диявольських поплічників Гаккара, ти проявиш не тільки себе, але й свою готовність пізнати шляхи одержимих.", [5] = "Чудово... без сумніву, ти {стать:отримав:отримала} ці взірці могутності у поплічників Гаккара ціною їхніх жахливих мук. Ось, прийми ці обмотки одержимого. Вони містять потужне моджо полонених демонів і будуть могутнім інструментом на твоєму шляху.", ["en"] = "Paragons of Power: The Demoniac's Wraps", ["tasks"] = { ["3000 reputation with Zandalar Tribe"] = "3000 репутації у племені Зандалар", ["Primal Hakkari Stanchion"] = "первісний поруч Гаккарі", ["Primal Hakkari Stanchion (Provided)"] = "первісний поруч Гаккарі (видано)" } },
    [8060] = { [1] = "Взірці могутності: обмотки ілюзіоніста", [2] = "Магів в нашому племені називають ілюзіоністами. Вони використовують потужні чари, щоб збивати з пантелику та заплутувати ворогів племені!\n\n<Ал'табім злісно сміється.>\n\nТи маєш побачити могутнього ілюзіоніста в дії, вороги якого власноруч знищують себе, дедалі більше занурюючись у безумство.\n\nЩоб пізнати шлях наших ілюзіоністів, йди в Зул'Ґуруб та принеси мені взірці могутності. За це я дам тобі обмотки для рук, якими користуються наші ілюзіоністи, щоб плести свої закляття.", [3] = "Принесіть Ал'табіму Всевидющому первісні браслети Гаккарі. Ви також повинні мати репутацію не нижче дружньої з племенем Зандалар.\n\nАл'табім Всевидющий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "{ім'я}! Ти вже {стать:повернувся:повернулася}? Ти {стать:зміг:змогла} дістати взірці могутності?", [5] = "Дивовижно... ти {стать:відчував:відчувала}, як чари протікають через них? Взірці могутності колись використовувалися як свого роду валюта, коли імперія Ґурубаші правила цими землями. Тепер ми, Зандалари, використовуватимемо чари, які містяться в них, щоб протистояти Богу крові Гаккару!\n\nТи добре {стать:впорався:впоралася} сьогодні — вважай, що у тебе є друзі серед Зандаларів. Ось обмотки ілюзіоніста, які я обіцяв тобі!", ["en"] = "Paragons of Power: The Illusionist's Wraps", ["tasks"] = { ["3000 reputation with Zandalar Tribe"] = "3000 репутації у племені Зандалар", ["Primal Hakkari Bindings"] = "первісні браслети Гаккарі", ["Primal Hakkari Bindings (Provided)"] = "первісні браслети Гаккарі (видано)" } },
    [8061] = { [1] = "Взірці могутності: обмотки сповідника", [2] = "Ми, Зандалари, надаємо владу тим, хто говорить з Богами. Наші жерці — це не просто лікарі, вони є нашими сповідниками. Зло приходить як ззовні, так і зсередини племені. Наші сповідники виступають як судді серед нас, зберігаючи нас від того ж зла, що пожирає Ґурубаші зсередини.\n\nЙди в Зул'Ґуруб та принеси звідти взірці могутності Ґурубаші. Дізнайся, що означає бути сповідником та охороняй нас від зла.", [3] = "Принесіть Ал'табіму Всевидющому первісний поруч Гаккарі. Ви також повинні мати репутацію не нижче дружньої з племенем Зандалар.\n\nАл'табім Всевидющий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Ти {стать:повернувся:повернулася} з Зул'Ґуруба, так? Тобі вдалося здобути взірці могутності з поплічників Гаккара?", [5] = "Чудово, {ім'я}! Це був неабиякий подвиг — принести їх мені. Без сумніву, сьогодні ти {стать:проявив:проявила} себе як {стать:сповідник:сповідниця} нашого племені, захистивши нас від загрози Гаккара. Ці обмотки гідні таких друзів племені, як ти!", ["en"] = "Paragons of Power: The Confessor's Wraps", ["tasks"] = { ["3000 reputation with Zandalar Tribe"] = "3000 репутації у племені Зандалар", ["Primal Hakkari Stanchion"] = "первісний поруч Гаккарі", ["Primal Hakkari Stanchion (Provided)"] = "первісний поруч Гаккарі (видано)" } },
    [8062] = { [1] = "Взірці могутності: браслети хижака", [2] = "У темні часи, що настали після падіння імперії Ґурубаші, хижаки Зандаларів використовували свою вправність, щоб забезпечувати плем'я їжею. Мисливці твердять, що вони схожі на хижаків нашого племені — шукати здобич означає уособлювати суть хижака, так воно і є. Однак твоє полювання в Зул'Ґурубі покаже, чи справді ти можеш посісти місце серед наших найкращих хижаків.\n\nПринеси мені взірці могутності з Зул'Ґуруба. Зроби це, і ти ще на один крок наблизишся до того, щоб стати хижаком.", [3] = "Принесіть Фалтіру Незрячому первісні браслети Гаккарі. Ви також повинні мати репутацію не нижче дружньої з племенем Зандалар.\n\nФалтір Незрячий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Полюй у Зул'Ґурубі на тих, хто володіє взірцями могутності, {ім'я}. Вони — твоя здобич. Вони володіють тим, що ми хочемо мати.", [5] = "Так... Мені не потрібне видіння, щоб відчувати присутність взірців могутності. Твій успіх у Зул'Ґурубі вразив багатьох у племені. Ми не тільки називаємо тебе {стать:другом:подругою} Зандаларів, але й вважаємо, що ти {стать:гідний:гідна} володіти браслетами хижака — могутніми предметами та символом того, що означає бути хижаком. Молодець, {ім'я}.", ["en"] = "Paragons of Power: The Predator's Bracers", ["tasks"] = { ["3000 reputation with Zandalar Tribe"] = "3000 репутації у племені Зандалар", ["Primal Hakkari Bindings"] = "первісні браслети Гаккарі", ["Primal Hakkari Bindings (Provided)"] = "первісні браслети Гаккарі (видано)" } },
    [8063] = { [1] = "Взірці могутності: браслети зірвиголови", [2] = "Зірвиголови Зандаларів схожі на підступних пройдисвітів, але передусім вони втілюють безлад... хаос... непередбачуваність буття. Вони творили жах на полі бою, сіючи збентеження та хаос серед наших ворогів у дикі часи після розколу племен. Ми не були б тут сьогодні без них.\n\nПринеси мені взірці могутності з Зул'Ґуруба, які я шукаю, і я дам тобі одне зі споряджень зірвиголів. Поринь в божевілля!", [3] = "Принесіть Фалтіру Незрячому первісний наруч Гаккарі. Ви також повинні мати репутацію не нижче дружньої з племенем Зандалар.\n\nФалтір Незрячий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Шукай божевілля всередині Зул'Ґуруба і затьмар його своїм власним, {ім'я}! Це означатиме успіх, а успіх означає нагороду! Не дозволь Богу крові знову запанувати!", [5] = "Молодець, {ім'я}... твої досягнення в Зул'Ґурубі заслужили тобі право називати плем'я Зандалар своїми друзями. Я подбаю про ці взірці могутності. Прийми цю нагороду за твої зусилля!", ["en"] = "Paragons of Power: The Madcap's Bracers", ["tasks"] = { ["3000 reputation with Zandalar Tribe"] = "3000 репутації у племені Зандалар", ["Primal Hakkari Armsplint"] = "первісний наруч Гаккарі", ["Primal Hakkari Armsplint (Provided)"] = "первісний наруч Гаккарі (видано)" } },
    [8064] = { [1] = "Взірці могутності: пояс гаруспіка", [2] = "Ми, Зандалари, не знаємо про шляхи друїдів. Природа має бути упорядкована за нашими потребами, а не навпаки. Проте, гаруспік — це той, хто найбільше зв'язаний з природою, і це зрозуміло. Щоб зрозуміти звірів, треба бути одним з них. Ось справжня сила природи.\n\nПринеси мені взірці могутності з Зул'Ґуруба, щоб довести свою відданість нам. Зробиш це, і я дам тобі потужний предмет — пояс, яким користуються гаруспіки Зандаларів.\n\nСильне моджо, {стать:друже:подруго}!", [3] = "Принесіть Майвікі Зулдазарській первісний пояс Гаккарі. Ви також повинні мати репутацію не нижче почесної з племенем Зандалар.", [4] = "Ти {стать:приніс:принесла} взірці могутності з Зул'Ґуруба? Якщо так, то пояс гаруспіка буде твоїм.", [5] = "Я дякую тобі. Прихована сила, що міститься в цих взірцях — це великий скарб, можеш не сумніватися. Ти не тільки {стать:зробив:зробила} те, про що я тебе просила, але й {стать:довів:довела}, що ти {стать:почесний союзник:почесна союзниця} нашого племені. Як я й обіцяла — ось твоя нагорода!", ["en"] = "Paragons of Power: The Haruspex's Belt", ["tasks"] = { ["9000 reputation with Zandalar Tribe"] = "9000 репутації у племені Зандалар", ["Primal Hakkari Sash"] = "первісний пояс Гаккарі", ["Primal Hakkari Sash (Provided)"] = "первісний пояс Гаккарі (видано)" } },
    [8065] = { [1] = "Взірці могутності: мундир гаруспіка", [2] = "Головним символом сили гаруспіків є їхній одяг, {ім'я}. Мундир символізує зв'язок між ними та божественною мудрістю, яку вони шукають. Часто в мундир вплітають частини тварин, принесених у жертву. Це нагадує гаруспіками про зв'язок, який вони мають зі своїми дарами.\n\nПринеси мені взірці могутності з Зул'Ґуруба і доведи нам свою цінність. Зроби це, і мундир, просякнутий справжньою силою гаруспеків, буде твоїм.", [3] = "Принесіть Майвікі Зулдазарській первісну накидку Гаккарі. Ви також повинні мати репутацію не нижче шанованої з племенем Зандалар.", [4] = "{стать:Приніс:Принесла} мені взірці могутності з Зул'Ґуруба? Мундир гаруспіка вартий будь-яких твоїх зусиль.", [5] = "Неймовірно... ти успішно {стать:зібрав:зібрала} необхідні взірці могутності, {ім'я}. Про твої досягнення в Зул'Ґурубі ходять легенди. Відтепер ти будеш {стать:шанованим:шанованою} серед племені. Ось твій мундир, {стать:могутній:могутня} {клас:к}!", ["en"] = "Paragons of Power: The Haruspex's Tunic", ["tasks"] = { ["21000 reputation with Zandalar Tribe"] = "21000 репутації у племені Зандалар", ["Primal Hakkari Tabard"] = "первісна накидка Гаккарі", ["Primal Hakkari Tabard (Provided)"] = "первісна накидка Гаккарі (видано)" } },
    [8066] = { [1] = "Взірці могутності: пояс хижака", [2] = "Будь-який хижак знає, як підкрадатися до здобичі, але лиш найвправніший вміє вибирати найкращий момент для удару. Тобі необхідно опанувати обидві навички, щоб мати хоча б невеликий шанс на успіх у Зул'Ґурубі... і можливість бути схожим на хижаків Зандаларів.\n\nПринеси мені взірці могутності з Зул'Ґуруба. Моєю нагородою буде сила, яку вони несуть, а твоєю буде пояс хижака — обладунок, вартий такої угоди.", [3] = "Принесіть Фалтіру Незрячому первісну шаль Гаккарі. Ви також повинні мати репутацію не нижче почесної з племенем Зандалар.\n\nФалтір Незрячий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Завдай удару божевільним поплічникам Гаккара в Зул'Ґурубі — саме вони володіють взірцями могутності, {ім'я}. Доведи їм, і племені, свою гідність як {стать:претендента:претендентки} на хижака.", [5] = "Я відчув твоє прибуття за мить до цього, {ім'я}, але це було непросто. Те, що відкрилося мені — це взірці могутності, які ти {стать:приніс:принесла}. Я можу відчувати силу без необхідності бачити її. їх приховане моджо — магія, якщо хочеш — продовжуватиме підживлювати наші зусилля для перемоги над диявольськими планами Бога крові Гаккара.\n\nТи заслуговуєш на похвалу і винагороду за твій успіх. Ти {стать:почесний союзник:почесна союзниця} племені, і ти {стать:гідний:гідна} носити пояс хижака.", ["en"] = "Paragons of Power: The Predator's Belt", ["tasks"] = { ["9000 reputation with Zandalar Tribe"] = "9000 репутації у племені Зандалар", ["Primal Hakkari Shawl"] = "первісна шаль Гаккарі", ["Primal Hakkari Shawl (Provided)"] = "первісна шаль Гаккарі (видано)" } },
    [8067] = { [1] = "Взірці могутності: наплічники хижака", [2] = "Ми, Зандалари, цінуємо те, що носимо, як символ досягнень. Тобі не потрібно бачити, щоб відчути силу, яку випромінює цей одяг. Одяг хижака Зандаларів саме такий, і найціннішими є наплічники, які вони носять. Вони допомагають їм ховатись від чужих поглядів... і давати знати про свою присутність, коли самі хижаки цього бажають.\n\nВзірці могутності чекають на тебе в Зул'Ґурубі. Принеси мені їх і наплічники хижака стануть твоїми.", [3] = "Принесіть Фалтіру Незрячому первісну егіду Гаккарі. Ви також повинні мати репутацію не нижче шанованої з племенем Зандалар.\n\nФалтір Незрячий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Чи був твій напад на Зул'Ґуруб успішним, {ім'я}? Тільки тоді, коли ти принесеш мені те, що я шукаю, і повністю доведеш свою цінність для племені, ти отримаєш неперевершені наплічники зандаларського хижака.", [5] = "Тобі вдалося... Ти будеш {стать:шанованим:шанованою} серед племені, {ім'я}. Було нелегко здобути взірці могутності, необхідні для наплічників, але ти {стать:впорався:впоралася} з цим завданням, як {стать:найсмертоносніший:найсмертоносніша} з наших хижаків. Ти {стать:заслужив:заслужила} своє місце серед них і, безумовно, {стать:заслужив:заслужила} право носити їхні наплічники.", ["en"] = "Paragons of Power: The Predator's Mantle", ["tasks"] = { ["21000 reputation with Zandalar Tribe"] = "21000 репутації у племені Зандалар", ["Primal Hakkari Aegis"] = "первісна егіда Гаккарі", ["Primal Hakkari Aegis (Provided)"] = "первісна егіда Гаккарі (видано)" } },
    [8068] = { [1] = "Взірці могутності: наплічники ілюзіоніста", [2] = "Магія — це чиста, первісна сила, яку можуть використовувати лише ті, хто має достатньо сили. Моджо — це наше продовження цієї сили. Однією з таких потужних маніпуляцій з нею є створення ілюзій. Як можна перемогти супротивника, якого насправді немає? Ми, Зандалари, знаємо цю силу, і саме тому ілюзіоністи займають почесне місце в нашому племені.\n\nЗбери взірці могутності в Зул'Ґурубі — за це отримаєш повагу нашого племені та потужні наплічники, якими користуються наші найкращі ілюзіоністи!", [3] = "Принесіть Ал'табіму Всевидющому первісну шаль Гаккарі. Ви також повинні мати репутацію не нижче почесної з племенем Зандалар.\n\nАл'табім Всевидющий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Як пройшов твій похід в Зул'Ґуруб? Ти {стать:звів:звела} своїх ворогів з розуму силою ілюзії? Ілюзія чи ні, але їхня смерть, і відібрані у них взірці могутності, допоможуть зупинити повернення Гаккара.", [5] = "Молодець! Ти справді {стать:почесний союзник:почесна союзниця} нашого племені! Зул'Ґуруб відчув на собі міць Зандаларів завдяки тобі, {ім'я}.\n\nЗ благословення племені, прийми ці наплічники зандаларського ілюзіоніста. Нехай вони гідно служать тобі.", ["en"] = "Paragons of Power: The Illusionist's Mantle", ["tasks"] = { ["9000 reputation with Zandalar Tribe"] = "9000 репутації у племені Зандалар", ["Primal Hakkari Shawl"] = "первісна шаль Гаккарі", ["Primal Hakkari Shawl (Provided)"] = "первісна шаль Гаккарі (видано)" } },
    [8069] = { [1] = "Взірці могутності: мантія ілюзіоніста", [2] = "У нашому племені одяг — це символ статусу та влади. Наші одежі виготовлені з найкращих матеріалів та пронизані потужним моджо. Ілюзіоністи не є винятком. Їхні мантії втілюють у собі саму сутність ілюзій. Легенди свідчать, що стародавній одяг ілюзіоністів постійно змінював свій вигляд.\n\nЯ дам тобі мантію ілюзіоніста, {ім'я}... але спочатку тобі потрібно заслужити шану племені! Принеси мені взірці могутності з Зул'Ґуруба!", [3] = "Принесіть Ал'табіму Всевидющому первісний каптан Гаккарі. Ви також повинні мати репутацію не нижче шанованої з племенем Зандалар.\n\nАл'табім Всевидющий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Ти {стать:повернувся:повернулася} з взірцями могутності? Я знаю, що це нелегко... але я давно передбачав, що на допомогу нам у боротьбі з Гаккаром прийде {стать:чужинець:чужинка}. Нехай це будеш ти!", [5] = "Нарешті хтось, {стать:гідний:гідна} носити мантію ілюзіоніста! Твій успіх у Зул'Ґурубі забезпечив тобі пошану серед племені на довгі віки. Носи її з гордістю, {ім'я}!", ["en"] = "Paragons of Power: The Illusionist's Robes", ["tasks"] = { ["21000 reputation with Zandalar Tribe"] = "21000 репутації у племені Зандалар", ["Primal Hakkari Kossack"] = "первісний каптан Гаккарі", ["Primal Hakkari Kossack (Provided)"] = "первісний каптан Гаккарі (видано)" } },
    [807] = { [1] = "<UNUSED>", [2] = "Мої розвідники повідомляють, що деякі представники дикої природи Дуротара заразилися демонічною скверною. Їх бачили на півночі та заході.\n\nВони блукають серед своїх побратимів, як звичайні звірі, але крізь них пронизують злі сили, і всередині кожного з них горить серце, випалене чорною магією.\n\nЦих звірів потрібно знищити!\n\nЯкщо ви знайдете таку тварину під час дослідження Дуротара, убийте її та заберіть її Випалене Серце. Принесіть серця мені, і я накажу їх вивчити, а потім знищити.", ["en"] = "<UNUSED>" },
    [8070] = { [1] = "Взірці могутності: пояс сповідника", [2] = "Невдовзі після падіння Ґурубаші, ми, Зандалари, майже зазнали остаточної поразки від зла всередині нашого племені. Тоді серед нас з'явилися сповідники, що зберегли плем'я, вигнавши тих, хто хотів знищити свій рід. Вони не тільки підтримують нас у гармонії з духами, але й зберігають плоть.\n\nЙди в Зул'Ґуруб і поглянь власними очима на порочність Гаккара та Ґурубаші. Вирви в них взірці могутності, які ми шукаємо, і отримаєш винагороду!", [3] = "Принесіть Ал'табіму Всевидющому первісний пояс Гаккарі. Ви також повинні мати репутацію не нижче почесної з племенем Зандалар.\n\nАл'табім Всевидющий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Взірці могутності... вони в тебе? Тільки коли ми матимемо їх, ми зможемо використати їхню приховану силу. Буде добре, якщо ми вб'ємо всіх поплічників Бога крові...", [5] = "Тобі вдалося! Ці взірці допоможуть нам зміцнити наші сили проти Гаккара. З твоєю допомогою ми зробили значний крок до того, щоб Бог крові не знищив нас усіх.\n\nСьогодні ти {стать:заслужив:заслужила} пошану нашого племені, {ім'я}. Візьми цей пояс сповідника як символ нашої вдячності.", ["en"] = "Paragons of Power: The Confessor's Bindings", ["tasks"] = { ["9000 reputation with Zandalar Tribe"] = "9000 репутації у племені Зандалар", ["Primal Hakkari Sash"] = "первісний пояс Гаккарі", ["Primal Hakkari Sash (Provided)"] = "первісний пояс Гаккарі (видано)" } },
    [8071] = { [1] = "Взірці могутності: наплічники сповідника", [2] = "Сповідники Зандаларів носять особливі наплічники, що вирізняє їх як хранителів племені. Ці наплічники сплетені з потужним моджо, що допомагає їм судити тих, хто загрожує нашому племені. Як {клас}, ти також проводиш час, вирішуючи, хто достойний, а хто ні; такі наплічники безсумнівно стануть благословенням для тебе.\n\nУ обмін на боротьбу з прислужниками Гаккара в Зул'Ґурубі та взірці могутності я дам тобі наплічники, варті наших найкращих сповідників.", [3] = "Принесіть Ал'табіму Всевидющому первісний пояс Гаккарі. Ви також повинні мати репутацію не нижче шанованої з племенем Зандалар.\n\nАл'табім Всевидющий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Ти {стать:приніс:принесла} взірці могутності з Зул'Ґуруба?", [5] = "Добре, {ім'я:к} — прислужники Гаккара відчули помсту Зандаларів завдяки тобі. Твої дії дарували тобі повагу нашого племені. Прошу, прийми ці наплічники сповідника з нашим благословенням.", ["en"] = "Paragons of Power: The Confessor's Mantle", ["tasks"] = { ["21000 reputation with Zandalar Tribe"] = "21000 репутації у племені Зандалар", ["Primal Hakkari Aegis"] = "первісна егіда Гаккарі", ["Primal Hakkari Aegis (Provided)"] = "первісна егіда Гаккарі (видано)" } },
    [8072] = { [1] = "Взірці могутності: наплічники зірвиголови", [2] = "Одним з легендарних зірвиголів Зандалару був Хар'ваксал Шалений. Легенди свідчать, що у боях із ворогами він застосовував свої наплічники зі спеціальним \"плетінням божевілля\". Він був сильним не тільки завдяки наплічникам, але й завдяки неймовірній швидкості його подвійних кинджалів. Сучасні зірвиголови цінують свої наплічники як символ свого місця в племені.\n\nПринеси мені взірці могутності, і наплічники стануть твоїми, щоб ти {стать:міг:могла} плести божевілля серед ворогів.", [3] = "Принесіть Фалтіру Незрячому первісний пасок Гаккарі. Ви також повинні мати репутацію не нижче почесної з племенем Зандалар.\n\nФалтір Незрячий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Ти {стать:повернувся:повернулася} — взірці могутності в тебе?\n\nЛегенда про Хар'ваксала Шаленого слугує нам нагадуванням про те, що жодного ворога, якою б великою загрозою він не був, можна здолати. Хаос поставить всіх на коліна... і це одна з небагатьох його закономірностей.", [5] = "Сьогодні ми перемогли завдяки божевіллю, яке ти {стать:посіяв:посіяла} серед наших спільних ворогів! Ти будеш {стать:почесним союзником:почесною союзницею} Зандаларів, і немає кращого способу висловити вдячність за твої діяння, ніж запропонувати тобі наплічники зірвиголови!", ["en"] = "Paragons of Power: The Madcap's Mantle", ["tasks"] = { ["9000 reputation with Zandalar Tribe"] = "9000 репутації у племені Зандалар", ["Primal Hakkari Girdle"] = "первісний пасок Гаккарі", ["Primal Hakkari Girdle (Provided)"] = "первісний пасок Гаккарі (видано)" } },
    [8073] = { [1] = "Взірці могутності: мундир зірвиголови", [2] = "Мої очі вже давно не служать мені, але це не важливо. Навіть у нашому племені, де одяг відображає статус і призначення, найпотужніші речі випромінюють силу, яку прості очі не можуть бачити. Мундир, що носять зірвиголови Зандаларів не є винятком — він випромінює силу хаосу та безладу, яку вони можуть контролювати.\n\nВзірці могутності, які мені потрібні, знаходяться в Зул'Ґурубі. Принеси мені те, що я шукаю, і я нагороджу тебе власним легендарним мундиром... що личить ткачу божевілля.", [3] = "Принесіть Фалтіру Незрячому первісну егіду Гаккарі. Ви також повинні мати репутацію не нижче шанованої з племенем Зандалар.\n\nФалтір Незрячий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Вітаю на острові, {ім'я}... чи {стать:повернувся:повернулася} ти з тріумфом та взірцями могутності?", [5] = "Дивовижно... ти {стать:зробив:зробила} сьогодні те, що мало хто вважав можливим. Твоя шана в племені забезпечена на все життя, {ім'я}. Ти {стать:заслужив:заслужила} право одягнути мундир зірвиголови — зроби це з нашого благословення.", ["en"] = "Paragons of Power: The Madcap's Tunic", ["tasks"] = { ["21000 reputation with Zandalar Tribe"] = "21000 репутації у племені Зандалар", ["Primal Hakkari Aegis"] = "первісна егіда Гаккарі", ["Primal Hakkari Aegis (Provided)"] = "первісна егіда Гаккарі (видано)" } },
    [8074] = { [1] = "Взірці могутності: пояс авгура", [2] = "Авгури багато знають про стихії, {стать:друже:подруго}. І використовують свої знання на славу нашого племені. У темні дні після розколу імперії Ґурубаші, наші авгури вели нас до безпечного прихистку в Південних морях. Вони привели нас сюди, в долину, прямо до серця зла, що вирує у Зул'Ґурубі.\n\nПринеси мені взірці могутності з Зул'Ґуруба та доведи свою цінність для нас. Зроби це, і я дам тобі пояс, який використовують наші авгури — той, що має потужну магію всередині!", [3] = "Принесіть Майвікі Зулдазарській первісний пасок Гаккарі. Ви також повинні мати репутацію не нижче почесної з племенем Зандалар.\n\nМайвікі Зулдазарська знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Мені потрібні взірці могутності, {стать:друже:подруго} — ми будемо черпати з них силу для боротьби проти зла Зул'Ґуруба. Ти маєш їх?", [5] = "Я відчуваю запах переможеного зла на тобі, {ім'я}. Це солодкий запах, {стать:друже:подруго}... який, я впевнена, тобі добре знайомий.\n\nЯ розумію, що було непросто принести мені взірці могутності, необхідні для пояса. Твої вчинки не тільки прославили плем'я, але й прославили тебе серед мого племені. Ось, тримай пояс авгура і носи його як свій власний!", ["en"] = "Paragons of Power: The Augur's Belt", ["tasks"] = { ["9000 reputation with Zandalar Tribe"] = "9000 репутації у племені Зандалар", ["Primal Hakkari Girdle"] = "первісний пасок Гаккарі", ["Primal Hakkari Girdle (Provided)"] = "первісний пасок Гаккарі (видано)" } },
    [8075] = { [1] = "Взірці могутності: гауберк авгура", [2] = "Авгури Зандаларів носять особливий нагрудник, який називається гауберком. Він виготовлений з найкращих шовків та тканин, переплетених міцними ланцюгами. Це символ не лише їхньої божественності, але й влади, {стать:друже:подруго}. Ніколи не варто перечити тому, хто присвятив своє життя спілкуванню з духами...\n\nПринеси мені взірці могутності з Зул'Ґуруба та доведи свою цінність для нас. Зроби це, і я дам тобі один з найкращих гауберків, про які коли-небудь мріяли наші авгури!", [3] = "Принесіть Майвікі Зулдазарській первісну накидку Гаккарі. Ви також повинні мати репутацію не нижче шанованої з племенем Зандалар.\n\nМайвікі Зулдазарська знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Взірці могутності — ключове джерело магічної сили, тієї самої сили, що використовується для виготовлення гауберка для авгурів. Принеси мені їх і я дам тобі найкращий гауберк, який будь-який зандаларський авгур хотів би мати.", [5] = "Я знаю, через що тобі довелося пройти, щоб принести мені взірці могутності, {ім'я}. Це було нелегко — перемогти зло, що просочується з Зул'Ґуруба, немов зловіщий слиз — але тепер, коли все вже зроблено, можу з впевненістю сказати, що ти будеш {стать:шанованим:шанованою} серед Зандаларів на довгі віки!\n\nВізьми гауберк авгура і носи його з гордістю!", ["en"] = "Paragons of Power: The Augur's Hauberk", ["tasks"] = { ["21000 reputation with Zandalar Tribe"] = "21000 репутації у племені Зандалар", ["Primal Hakkari Tabard"] = "первісна накидка Гаккарі", ["Primal Hakkari Tabard (Provided)"] = "первісна накидка Гаккарі (видано)" } },
    [8076] = { [1] = "Взірці могутності: наплічники одержимого", [2] = "Одержимі прагнуть злитися з силою, а не просто володіти нею. Багато з наших одержимих програли битву зі своїм демоном. А такими ворогами — особливо як в Зул'Ґурубі — сила, яку біснуватий може випустити на них, варта жертви. Наше виживання залежить від того, чи зуміємо ми розгромити тих, хто хоче нас знищити — цього нас навчило падіння імперії Ґурубаші.\n\nЙди в Зул'Ґуруб та добудь необхідні нам взірці могутності. Зроби це, і цінна річ одержимого стане буде нагородою.", [3] = "Принесіть Ал'табіму Всевидющому первісний пояс Гаккарі. Ви також повинні мати репутацію не нижче почесної з племенем Зандалар.\n\nАл'табім Всевидющий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "{стать:Забрав:Забрала} взірці могутності з Зул'Ґуруба? Ми витягнемо приховану силу з цих предметів, зробимо її нашою власною, і дамо тобі гідну нагороду, якщо ти впораєшся...", [5] = "Чудово, {ім'я}. Взірці могутності з Зул'Ґуруба будуть нагадуванням про марнування сили. Ґурубаші були могутніми у своїй піднесеності, але дозволили собі бути жертвою своєї могутності. Одержимі знають, що їхній шлях дуже схожий, але здобута ними сила необхідна для виживання племені.\n\nВізьми ці наплічники, {стать:почесний союзнику:почесна союзнице} Зандаларів... нехай вони добре послужать тобі.", ["en"] = "Paragons of Power: The Demoniac's Mantle", ["tasks"] = { ["9000 reputation with Zandalar Tribe"] = "9000 репутації у племені Зандалар", ["Primal Hakkari Sash"] = "первісний пояс Гаккарі", ["Primal Hakkari Sash (Provided)"] = "первісний пояс Гаккарі (видано)" } },
    [8077] = { [1] = "Взірці могутності: мантія одержимого", [2] = "Найважливішим символом сили серед племені є одяг, який ми носимо у бою. Мантії одержимих поєднують у собі витончену рунічну тканину і надзвичайно потужне моджо. Кажуть, що вигляд цієї мантії вселяє страх у свідомість всіх, хто її бачить... особливо демонів, яких одержимий врешті-решт підкорить.\n\nТобі необхідно принести мені взірці могутності з Зул'Ґуруба. Це буде важко... але твій успіх винагородить тебе цією мантією.", [3] = "Принесіть Ал'табіму Всевидющому первісний каптан Гаккарі. Ви також повинні мати репутацію не нижче шанованої з племенем Зандалар.\n\nАл'табім Всевидющий знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Взірці могутності... ти {стать:повернувся:повернулася} з ними? Тільки коли вони будуть у нас, {ім'я}, ми поділимося з тобою головним символом сили одержимих.", [5] = "Дивовижно. Твої успіхи в Зул'Ґурубі запевнили нас — ні, весь світ — що Гаккар не переможе. Можливо, настане час, коли ти зустрінешся з Богом крові віч-на-віч... і якщо це станеться, знай, що тебе шанують в племені Зандалар.\n\nО, і думаю, що ця звичайна мантія також допоможе тобі.\n\n<Ал'табім підморгує вам.>", ["en"] = "Paragons of Power: The Demoniac's Robes", ["tasks"] = { ["21000 reputation with Zandalar Tribe"] = "21000 репутації у племені Зандалар", ["Primal Hakkari Kossack"] = "первісний каптан Гаккарі", ["Primal Hakkari Kossack (Provided)"] = "первісний каптан Гаккарі (видано)" } },
    [8078] = { [1] = "Взірці могутності: пояс поборника", [2] = "Помста чекає в Зул'Ґурубі. Гаккар не повинен повстати знову. Він знищив імперію Ґурубаші зсередини. Ніякої жертви не вистачить, щоб спокутувати провину. Тролі стали лиш тінню минулої слави. І я знаю, що це через Гаккара.\n\nСтань {стать:поборником, яким ти покликаний:поборницею, якою ти покликана} бути. Принеси прислужникам зла помсту Зандаларів. І повернись з доказами — взірцями могутності. Ти отримаєш пояс покровителя. Ти отримаєш справжню міць.\n\nЙди.", [3] = "Принесіть Джін'роху Руйнівнику первісний пасок Гаккарі. Ви також повинні мати репутацію не нижче почесної з племенем Зандалар.\n\nДжін'рох Руйнівник знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Чи {стать:приніс:принесла} ти взірці могутності? Чи {стать:вразив:вразила} ти ворогів племені? Гаккар повинен пізнати гнів поборника!", [5] = "Шлях поборників тепер відомий тобі. Ти {стать:приніс:принесла} честь племені. Ти {стать:приніс:принесла} честь собі. Ти {стать:приніс:принесла} біль нашим ворогам.\n\nПояс поборника твій. Ти, безсумнівно, пізнаєш шляхи поборників.", ["en"] = "Paragons of Power: The Vindicator's Belt", ["tasks"] = { ["9000 reputation with Zandalar Tribe"] = "9000 репутації у племені Зандалар", ["Primal Hakkari Girdle"] = "первісний пасок Гаккарі", ["Primal Hakkari Girdle (Provided)"] = "первісний пасок Гаккарі (видано)" } },
    [8079] = { [1] = "Знаки Сили: кіраса поборника", [2] = "Символом сили поборників є кіраса. Вона кована за допомогою могутнього моджо. І ми довіряємо її лише тим, кого шануємо. Це символ помсти Зандаларів.\n\nСтати {стать:поборником:поборницею} — значить стати помстою. Забери взірці могутності з Зул'Ґуруба. Принеси їх нам. Ми повернемо моджо, що було вкрадене у нас. Ми примусимо прислужників Гаккара заплатити. Ми винагородимо тебе кірасою поборника.\n\nЙди. Будь нашою помстою, {ім'я}.", [3] = "Принесіть Джін'роху Руйнівнику первісний каптан Гаккарі. Ви також повинні мати репутацію не нижче шанованої з племенем Зандалар.\n\nДжін'рох Руйнівник знаходиться на острові Йоджамба в Тернистій долині.", [4] = "Твоя присутність означає перемогу? Чи є у тебе взірці могутності? Розкажи мені про помсту, яку ти {стать:здійснив:здійснила} сьогодні!", [5] = "Тебе шанують за твої вчинки. Плем'я винагороджує своїх героїв. Зул'Ґуруб відчув смак помсти Зандаларів, як ніколи раніше.\n\nТвої вчинки стануть передвісниками вчинків інших. Вони дивитимуться на тебе як на знак справжньої сили. Вони дивитимуться на тебе як на уособлення помсти!", ["en"] = "Paragons of Power: The Vindicator's Breastplate", ["tasks"] = { ["21000 reputation with Zandalar Tribe"] = "21000 репутації у племені Зандалар", ["Primal Hakkari Kossack"] = "первісний каптан Гаккарі", ["Primal Hakkari Kossack (Provided)"] = "первісний каптан Гаккарі (видано)" } },
    [8080] = { [1] = "Ресурси низини Араті", [2] = "Війну виграють солдати — це тобі скаже будь-який солдат. Він також скаже, що битва, яка ведеться з поганим спорядженням або на порожній шлунок, програна ще до її початку!\n\nОсь чому низина Араті така важлива. У цій низині є ключові райони, в яких містяться важливі ресурси. Метал, зброя, їжа, деревина — все це нам потрібно і все це можна отримати там.\n\nОсь, що я хочу від тебе, {ім'я:к}. Іди в низину Араті, виграй битву, утримавши більше баз, ніж ворог і принеси мені ящик з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його сержанту Очистій в Опорний пункт.", [4] = "Ти {стать:приніс:принесла} ящик з ресурсами, {ім'я:к}? Без них Ліга Аратора багато не навоює...", [5] = "Ти {стать:приніс:принесла} ресурси! Чудова робота! Я відправлю ці ресурси нашим квартирмейстерам, щоб вони якомога швидше роздали їх військам.\n\nДякую тобі, {ім'я:к}. Саме завдяки сумлінному виконанню таких завдань й виграються війни.", ["en"] = "Arathi Basin Resources!", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8081] = { [1] = "Більше ящиків з ресурсами", [2] = "Війну виграють солдати — це тобі скаже будь-який солдат. Він також скаже, що битва, яка ведеться з поганим спорядженням або на порожній шлунок, програна ще до її початку!\n\nОсь чому низина Араті така важлива. У цій низині є ключові райони, в яких містяться важливі ресурси. Метал, зброя, їжа, деревина — все це нам потрібно і все це можна отримати там.\n\nОсь, що я хочу від тебе, {ім'я:к}. Іди в низину Араті, виграй битву, утримавши більше баз, ніж ворог і принеси мені ящик з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його сержанту Очистій в Опорний пункт.", [4] = "{ім'я:к}, твоє завдання лишається незмінним — повертайся в низину Араті, добудь більше ящиків з ресурсами та принеси їх мені.", [5] = "Чудово. Я негайно передам ці ресурси нашим квартирмейстерам, а начальству — подяку за твої дії.\n\nЩе раз дякую тобі, {ім'я:к}. Твій внесок у нашу боротьбу помітили як піхотинці, так і фельдмаршали.", ["en"] = "More Resource Crates", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [810] = { [1] = "<UNUSED>", [2] = "Тобі варто дізнатися, наскільки небезпечною може бути ця земля, {клас}.\n\nДика природа тут може навчити нас цьому... якщо ми будемо мудрими та спостережливими.\n\nСкорпіди – ідеальний приклад виживання в Дуротарі. Якщо ти хочеш вижити, було б мудро перейняти деякі з їхніх рис. Їхні загартовані панцири можуть захистити тебе від палючого сонця або навіть стати смертельною зброєю.\n\nПринеси мені 6 малих панцирів скорпідів від Клацаючих Скорпідів, {ім'я}, і я подбаю про те, щоб справедливо винагородити тебе.", ["en"] = "<UNUSED>" },
    [8101] = { [1] = "Камінчик Каджаро", [5] = "{Раса:к}, цей талісман містить у собі камінчик з гори Каджаро в Південних морях. Гора Каджаро знаменита своєю нестабільністю — там постійно відбуваються потужні та часто магічні виверження.\n\nУ міру зміцнення твого зв'язку з тролями Зандалара, зростатиме і сила цього каменю. Використовуй його силу, щоб нищити наших ворогів. Будь {стать:подібним:подібною} до гори: {стать:швидким:швидкою}, {стать:вибуховим:вибуховою}, {стать:смертоносним:смертоносною}...", ["en"] = "The Pebble of Kajaro" },
    [8102] = { [1] = "Камінчик Каджаро", [4] = "З поверненням, {клас:к}. Я бачу, що камінчик знайшов собі застосування. Багато наших ворогів піддалися твоїм потойбічним здібностям. Їхні страждання були великими. Настав час збільшити силу камінця. Віддай його мені.", [5] = "Будь {стать:нестримним:нестримною}, як лава Каджаро.", ["en"] = "The Pebble of Kajaro", ["tasks"] = { ["Pebble of Kajaro"] = "камінчик Каджаро", ["Pebble of Kajaro (Provided)"] = "камінчик Каджаро (видано)" } },
    [8103] = { [1] = "Камінчик Каджаро", [4] = "Гаккарі бояться тебе, {ім'я}. Вони говорять про жахіття, які, на їхню думку, міг вчинити лише їхній безликий Бог. Ти {стать:спалив:спалила} їх силою Каджаро. Тепер вони пізнали новий страх.\n\nНастав час ще більше посилити камінчик. Дай мені його.", [5] = "Продовжуй знищувати тролів Зул'Ґуруба. Гаккар повинен побачити, що світ не прогнеться перед його волею.", ["en"] = "The Pebble of Kajaro", ["tasks"] = { ["Pebble of Kajaro"] = "камінчик Каджаро", ["Pebble of Kajaro (Provided)"] = "камінчик Каджаро (видано)" } },
    [8104] = { [1] = "Самоцвіт Каджаро", [4] = "Дай мені талісман, {ім'я:к}. Я маю дещо тобі показати.", [5] = "<Ал'табім розбиває камінчик потужною невидимою силою.>\n\nБачиш? Камінчик — це те, що ми називаємо жеодою. Усередині камінця знаходяться потужний кристал, який ввібрав в себе приховану енергію нашого світу. Розбивши камінчик, я нарешті дозволив реалізувати весь його потенціал. Використовуй його, щоб нищити наших ворогів.", ["en"] = "The Jewel of Kajaro", ["tasks"] = { ["Pebble of Kajaro"] = "камінчик Каджаро", ["Pebble of Kajaro (Provided)"] = "камінчик Каджаро (видано)" } },
    [8106] = { [1] = "Пошесть Кезана", [5] = "Прийми цей талісман, {клас:к}. Прийми його і використовуй його силу, щоб послабити наших спільних ворогів.\n\nЗнай, що на своїй шиї ти носиш частинку історії. Колись Кезан був величною територією Зандаларської імперії. На жаль, пошесть гоблінських торгових принців витіснила моїх гордих братів і сестер.\n\nТепер у Кезані розташована столиця гоблінів — Підштольня. Але знай, що раніше, до цієї пошесті, він славився своєю величчю. Кезан досі є священною землею для мого народу.", ["en"] = "Kezan's Taint" },
    [8107] = { [1] = "Пошесть Кезана", [4] = "Честь серед зандаларських тролів треба заслужити, {ім'я}. Та з нею приходить нагорода — дружба, союз...\n\nПередай мені талісман, щоб я міг збільшити його силу.", [5] = "Злийся з темрявою, {клас:к}. Прийми світ тіней. Дозволь пошесті Кезана наситити твою темну жагу.", ["en"] = "Kezan's Taint", ["tasks"] = { ["Kezan's Taint"] = "пошесть Кезана", ["Kezan's Taint (Provided)"] = "пошесть Кезана (видано)" } },
    [8108] = { [1] = "Пошесть Кезана", [4] = "Я чекав на тебе, {клас:к}. Я ще раз посилю твій талісман. Я лише прошу, щоб ти {стать:продовжував:продовжувала} знищувати Гаккара та його поплічників.\n\nДай мені талісман.", [5] = "Лише спільними зусиллями ми зупинимо Здирача Душ.", ["en"] = "Kezan's Taint", ["tasks"] = { ["Kezan's Taint"] = "пошесть Кезана", ["Kezan's Taint (Provided)"] = "пошесть Кезана (видано)" } },
    [8109] = { [1] = "Нестримна пошесть Кезана", [4] = "Виклич своїх демонів, {клас:к}. Нехай енергія пошесті Кезана наситить їх. Командуй ним на полі бою і знищ ворогів!\n\nТак... Настав час додати останнє посилення до твого талісмана. Дай мені його.", [5] = "Здирай плоть з їхніх тіл. Дивись, як тіні поглинають Гаккарі. Черпай силу з їхнього страху, {клас:к}. І нехай пошесть Кезана збільшить цю силу...", ["en"] = "Kezan's Unstoppable Taint", ["tasks"] = { ["Kezan's Taint"] = "пошесть Кезана", ["Kezan's Taint (Provided)"] = "пошесть Кезана (видано)" } },
    [8110] = { [1] = "Зачаровані водорості Південних морів", [5] = "Бач ці водорості? Вони з Південних морів. Ми лиш додали трохи моджо й трохи магії, щоб вони краще служили своєму власнику.\n\nТи {клас}, тож це буде просто. Просто оберни їх навколо шиї та подумай про природу чи білочок, чи шо там ви любите.", ["en"] = "Enchanted South Seas Kelp" },
    [8111] = { [1] = "Зачаровані водорості Південних морів", [4] = "Гей, {стать:друже:подруго}! Рада тебе знову бачить. Плем'я говорить про те, як ти вбиваєш Гаккарі й все таке. Молтор сказав, шоб я додала більше моджо для твого талісмана. Просто дай його мені й Майвікі все зробить.", [5] = "Дивись, не викури його, {стать:друже:подруго}! Ти маєш використовувать його, шоб бороться зі злом.", ["en"] = "Enchanted South Seas Kelp", ["tasks"] = { ["Enchanted South Seas Kelp"] = "зачаровані водорості Південних морів", ["Enchanted South Seas Kelp (Provided)"] = "зачаровані водорості Південних морів (видано)" } },
    [8112] = { [1] = "Зачаровані водорості Південних морів", [4] = "Як тобі цей талісман, {стать:друже:подруго}? Схоже, настав час додать трохи більше магії та моджо до його листя. Йому треба трохи розквітнуть. Дай його сюди, і Майвікі все виправить.", [5] = "Тепер ти покажеш злим тролям в Зул'Ґурубі, на шо здатна сила природи, {стать:друже:подруго}!", ["en"] = "Enchanted South Seas Kelp", ["tasks"] = { ["Enchanted South Seas Kelp"] = "зачаровані водорості Південних морів", ["Enchanted South Seas Kelp (Provided)"] = "зачаровані водорості Південних морів (видано)" } },
    [8113] = { [1] = "Бездоганні зачаровані водорості Південних морів", [4] = "{ім'я}! Давно я тебе не бачила. Чи знаєш ти, шо сам король Растахан наказав додати останній штрих моджо до твого талісмана? Це правда, {стать:друже:подруго}! Я б сама не повірила, якби не почула це власними вухами. Давай сюди талісман.", [5] = "{ім'я}, це була гарна подорож. Продовжуй переслідувать й винищувать Гаккара і його поплічників.", ["en"] = "Pristine Enchanted South Seas Kelp", ["tasks"] = { ["Enchanted South Seas Kelp"] = "зачаровані водорості Південних морів", ["Enchanted South Seas Kelp (Provided)"] = "зачаровані водорості Південних морів (видано)" } },
    [8116] = { [1] = "Видіння Вудрії", [5] = "У тебе з Майвікі є дещо спільне, {стать:друже:подруго}. Я теж {клас}! Хоча Майвікі скоріш містик, а ти робиш більш брудну роботу. Проте, ми обоє знаєм, шо можуть дарувать великі духи.\n\nЯ дарую тобі цю сферу, яку ти будеш носить на шиї. Зазирни всередину і побачиш селище Вудрія у Південних морях! Нехай вона зміцнить твій дух!", ["en"] = "Vision of Voodress" },
    [8117] = { [1] = "Видіння Вудрії", [4] = "Майвікі придумала жарт... Шо-ман!\n\n<Майвікі сміється.>\n\nОтже, ти {стать:використовував:використовувала} духів і стихії проти наших ворогів в Зул'Ґурубі, ге? Хвала духам!\n\nМайвікі покращить твою сферу. Дай-но її сюди, {ім'я}.", [5] = "Поглянь-но, {ім'я}. Вудрію тепер видно ще ясніше, еге? Нехай первісна сила тече через тебе, {стать:друже:подруго}.", ["en"] = "Vision of Voodress", ["tasks"] = { ["Vision of Voodress"] = "видіння Вудрії", ["Vision of Voodress (Provided)"] = "видіння Вудрії (видано)" } },
    [8118] = { [1] = "Видіння Вудрії", [4] = "Хороші новини, {ім'я}. Молтор останнім часом співає тобі дифірамби. Він каже, що ти стаєш {стать:справжнім героєм:справжньою героїнею} Зандаларів.\n\nВін також сказав, шоб Майвікі ще трохи покращила твою сферу! Дай-но її сюди, шоб Майвікі могла прояснити видіння.", [5] = "Остерігайся злих духів Гаккарі, {стать:друже:подруго}. Чесно кажучи, вони лячні.", ["en"] = "Vision of Voodress", ["tasks"] = { ["Vision of Voodress"] = "видіння Вудрії", ["Vision of Voodress (Provided)"] = "видіння Вудрії (видано)" } },
    [8119] = { [1] = "Ясне видіння Вудрії", [4] = "<Майвікі вказує на ваш талісман>.\n\nПоглянь на нього, {ім'я}! Він ожив. Духи танцюють навколо сфери.\n\nВіддай його Майвікі, щоб вона могла зробити останнє посилення.", [5] = "Одного дня, {ім'я}, ти зможеш використовувати цю сферу, щоб спілкуватися зі мною. Коли битва з Гаккаром закінчиться і Майвікі повернеться додому. Покличмо духів і попросімо їх, щоб цей день настав якнайшвидше.", ["en"] = "The Unmarred Vision of Voodress", ["tasks"] = { ["Vision of Voodress"] = "видіння Вудрії", ["Vision of Voodress (Provided)"] = "видіння Вудрії (видано)" } },
    [8123] = { [1] = "Перерізати лінії постачання Аратора", [2] = "Ліга Аратора не шкодує сил на відвоювання низини Араті. Вони, разом зі всіма расами Альянсу, зараз прямують в цей віддалений регіон, маючи намір розширити свої володіння за межі Опорного пункту. Ми повинні зупинити їх, і найкращий спосіб для цього — захопити їхні припаси.\n\n{ім'я:к}, ти можеш нам допомогти. Вирушай в низину Араті, яка відома своїми родючими копальнями, багатими землями та професійними майстрами. Візьми під контроль усі бази, які зможеш, виграй битву і повернись до мене з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його смертолову Мортісу в Молотобій.", [4] = "Що таке, {раса:к}? Ти {стать:приніс:принесла} ящик з ресурсами? Повернись в низину Араті, вбий паразитів з Альянсу та захопи їхні ресурси для Темної Леді!", [5] = "<Смертолов Мортіс посміхається>\n\nТи {стать:завдав:завдала} ще одного потужного удару нашим ворогам, {ім'я:к}. Завдяки тобі, низина Араті скоро буде захоплена Труїтелями.", ["en"] = "Cut Arathor Supply Lines", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8124] = { [1] = "Більше ящиків з ресурсами", [2] = "Ліга Аратора не шкодує сил на відвоювання низини Араті. Вони, разом зі всіма расами Альянсу, зараз прямують в цей віддалений регіон, маючи намір розширити свої володіння за межі Опорного пункту. Ми повинні зупинити їх, і найкращий спосіб для цього — захопити їхні припаси.\n\n{ім'я:к}, ти можеш нам допомогти. Вирушай в низину Араті, яка відома своїми родючими копальнями, багатими землями та професійними майстрами. Візьми під контроль усі бази, які зможеш, виграй битву і повернись до мене з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його смертолову Мортісу в Молотобій.", [4] = "{ім'я:к}, твоє завдання лишається незмінним — повертайся в низину Араті, добудь більше ящиків з ресурсами та принеси їх мені.", [5] = "Чудово. Я негайно передам ці ресурси нашим квартирмейстерам, а начальству — подяку за твої дії.\n\nЩе раз дякую тобі, {ім'я:к}. Твій внесок у нашу боротьбу помітили як бугаї, так і воєводи.", ["en"] = "More Resource Crates", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [814] = { [1] = "<UNUSED>", [2] = "Готувати та прибирати – це все, що я роблю!\n\nХочеш їсти – принеси мені ще м’яса! У мене немає цілого дня, щоб полювати та готувати їжу для всіх цих вошей. Тобі треба навчитися тягнути тут свою вагу, якщо хочеш, щоб до тебе ставилися рівно.\n\nПринеси мені шматки кабанячого м’яса, якщо хочеш бути корисним... або не хочеш померти з голоду.", ["en"] = "<UNUSED>" },
    [8141] = { [1] = "Зандаларський талісман тіні", [5] = "Ти швидко ростеш, {стать:юний:юна} {клас:к}. Можливо, настав час посвятити тебе в Шера Алі'х — нашою мовою це означає \"Рука смерті\". Тисячоліттями ми виконували роль вбивць для імперії Зандалар. Занадто довго ми сиділи склавши руки, дозволяючи Гаккарі нарощувати силу. Ми знову зіткнулися з Гаккаром, але цього разу без підтримки об'єднаних сил тролів. Саме ти та твої союзники повинні допомогти нам перемогти Бога крові та його поплічників!\n\nНоси цей талісман, і нехай він допомагає у твоїх мандрах.", ["en"] = "Zandalarian Shadow Talisman" },
    [8142] = { [1] = "Зандаларський талісман тіні", [4] = "Я відчуваю, що ти {стать:вбив:вбила} незліченну кількість Гаккарі, {ім'я}. Від тебе тхне їхнім моджо.\n\nЯ припускаю, що талісман тіні допоміг тобі? Віддай його мені та дозволь мені збільшити його силу.", [5] = "Вбивці твого рівня повинні мати широку свободу дій. Твої вороги повинні навчитися поваги! Ти отримаєш це, коли ворог побачить блиск руки смерті — але буде занадто пізно...", ["en"] = "Zandalarian Shadow Talisman", ["tasks"] = { ["Zandalarian Shadow Talisman"] = "зандаларський талісман тіні", ["Zandalarian Shadow Talisman (Provided)"] = "зандаларський талісман тіні (видано)" } },
    [8143] = { [1] = "Зандаларський талісман тіні", [4] = "Дивовижно, {ім'я}. Ти маєш дар вбивати, якого я не відчував в інших вже багато років. Навіть Молтор знає про те, що ти {стать:зробив:зробила} для Зандалара. Настав час посилити твій талісман. Віддай його мені.", [5] = "Залишилося лише одне покращення, яке я можу застосувати до цього талісмана, {клас:к}. І коли прийде час, я застосую його.", ["en"] = "Zandalarian Shadow Talisman", ["tasks"] = { ["Zandalarian Shadow Talisman"] = "зандаларський талісман тіні", ["Zandalarian Shadow Talisman (Provided)"] = "зандаларський талісман тіні (видано)" } },
    [8144] = { [1] = "Зандаларський талісман майстра тіні", [4] = "Він прагне посилення, {ім'я}. Талісман ввібрав у себе все, що ти {стать:зробив:зробила}. Тисячі трупів тролів, що заполонили Зул'Ґуруб, підживлюють його силу. Віддай його мені, і я накладу останні чари.", [5] = "Це останній раз, коли ми говоримо під егідою Шера Алі'х. Ти знаєш все, що маєш знати. Візьми талісман і продовжуй вбивати. Гаккару не можна дозволити покинути Зул'Ґуруб.", ["en"] = "Zandalarian Shadow Mastery Talisman", ["tasks"] = { ["Zandalarian Shadow Talisman"] = "зандаларський талісман тіні", ["Zandalarian Shadow Talisman (Provided)"] = "зандаларський талісман тіні (видано)" } },
    [8145] = { [1] = "Вус Водоверті", [5] = "Серед зандаларців професія {клас:р} високо шанована. Наші найвідданіші мисливці подорожують до Водоверті, щоб довести свою рішучість.\n\nЗ самого серця моря вони добувають водорості, відомі як \"вус Водоверті\". З них плетуть талісмани, що збільшують силу та влучність.\n\nЯ дам тобі такий талісман. Коли твій зв'язок з Зандаларами буде зміцнюватись, я вплітатиму більше сили у цей талісман.", ["en"] = "The Maelstrom's Tendril" },
    [8146] = { [1] = "Вус Водоверті", [4] = "Ах, {ім'я}, як приємно знову відчути твій запах.\n\n<Фалтір посміхається.>\n\nВибач за моє почуття гумору. Часом воно буває дуже непристойним.\n\nЯ відчуваю, що ти {стать:завдав:завдала} великих страждань нашим ворогам. Сили Гаккара вигукують твоє ім'я в гніві. Це надзвичайно.\n\nТи {стать:заслужив:заслужила} на ще одне посилення свого талісмана. Дай мені його.", [5] = "Нехай вони знайдуть спокуту на кінці твоїх стріл.", ["en"] = "The Maelstrom's Tendril", ["tasks"] = { ["Maelstrom's Tendril"] = "вус Водоверті", ["Maelstrom's Tendril (Provided)"] = "вус Водоверті (видано)" } },
    [8147] = { [1] = "Вус Водоверті", [4] = "Навіть звідси я чув звуки твоїх пострілів, що вбивають наших ворогів. Їхні крики повні агонії.\n\nТи {стать:заслужив:заслужила} собі ім'я серед тролів Зандалару, {ім'я}. Ми вдячні тобі за все, що ти {стать:зробив:зробила}.\n\nДай мені свій талісман, щоб я міг додати ще одне плетиво.", [5] = "Я зможу додати ще лиш одне плетиво до твого талісмана, {клас:к}.", ["en"] = "The Maelstrom's Tendril", ["tasks"] = { ["Maelstrom's Tendril"] = "вус Водоверті", ["Maelstrom's Tendril (Provided)"] = "вус Водоверті (видано)" } },
    [8148] = { [1] = "Гнів Водоверті", [4] = "Молтор передає вістку від короля Растахана, {ім'я}. Королівський двір дуже вражений тим, як ти {стать:знищив:знищила} сили Гаккарі. Я хочу нагородити тебе останнім плетивом для твого талісмана. Дай його мені.", [5] = "Твоя подорож тільки починається, {стать:юний:юна} {клас:к}. Можливо, одного дня ти відвідаєш Водоверть і зазирнеш у серце світу.\n\nЯ бажаю тобі сили та стійкості!", ["en"] = "Maelstrom's Wrath", ["tasks"] = { ["Maelstrom's Tendril"] = "вус Водоверті", ["Maelstrom's Tendril (Provided)"] = "вус Водоверті (видано)" } },
    [8151] = { [1] = "Амулет мисливця", [2] = "Оґтінк з Азшари шукає таких досвідчених мисливців, як ти. Він — хутропуз-мисливець, що покинув своє плем'я задля допомоги Кенарійському Колу. Його вчення покликано наставити його товаришів по ремеслу на шлях гармонії з природою. Тобі варто з ним поговорити.\n\nОґтінка можна знайти на вершинах скель в Азшарі, на північний схід від руїн Ельдарата.", [3] = "Поговоріть з Оґтінком в Азшарі.", [5] = "Я більше не займаюсь полюванням, {клас:к}. Моя доля направила мене займатись навчанням подібних тобі.\n\nЯ допоможу тобі створити амулет мисливця з частин вбитої тобою здобичі. Він буде нагадувати тобі про твої минулі випробовування і досягненнях. Я залишу його собі, а тобі дам дещо інше.", ["en"] = "The Hunter's Charm" },
    [8153] = { [1] = "Роги самця оленя", [2] = "Самець оленя носить наймогутніші роги, які тільки можна знайти у відомих нам звірів. Такі роги вони використовують для захисту, проштрикуючи ворога наскрізь. Ідеальні природні роги є ознакою духу тварини із найвищою впевненістю.\n\nЗдобуття таких рогів нагородить такою ж впевненістю тебе.\n\nВполюй мохового оленя, віднайди ідеальні роги та принеси їх до мене.", [3] = "Принесіть пару ідеальних рогів самця оленя Оґтінку в Азшарі. Огтінк проживає на схилах пагорбів на північний схід від руїн Ельдарата.", [4] = "Ти {стать:віднайшов:віднайшла} роги?", [5] = "Мабуть, ти володієш пильним оком та великою терплячістю, якщо {стать:здобув:здобула} їх. Чудова робота!", ["en"] = "Courser Antlers", ["tasks"] = { ["Perfect Courser Antler"] = "ідеальні роги самця оленя", ["Perfect Courser Antler (Provided)"] = "ідеальні роги самця оленя (видано)" } },
    [8154] = { [1] = "Ресурси низини Араті", [2] = "Війну виграють солдати — це тобі скаже будь-який солдат. Він також скаже, що битва, яка ведеться з поганим спорядженням або на порожній шлунок, програна ще до її початку!\n\nОсь чому низина Араті така важлива. У цій низині є ключові райони, в яких містяться важливі ресурси. Метал, зброя, їжа, деревина — все це нам потрібно і все це можна отримати там.\n\nОсь, що я хочу від тебе, {ім'я:к}. Іди в низину Араті, виграй битву, утримавши більше баз, ніж ворог і принеси мені ящик з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його сержанту Очистій в Опорний пункт.", [4] = "Ти {стать:приніс:принесла} ящик з ресурсами, {ім'я:к}? Без них Ліга Аратора багато не навоює...", [5] = "Ти {стать:приніс:принесла} ресурси! Чудова робота! Я відправлю ці ресурси нашим квартирмейстерам, щоб вони якомога швидше роздали їх військам.\n\nДякую тобі, {ім'я:к}. Саме завдяки сумлінному виконанню таких завдань й виграються війни.", ["en"] = "Arathi Basin Resources!", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8155] = { [1] = "Ресурси низини Араті", [2] = "Війну виграють солдати — це тобі скаже будь-який солдат. Він також скаже, що битва, яка ведеться з поганим спорядженням або на порожній шлунок, програна ще до її початку!\n\nОсь чому низина Араті така важлива. У цій низині є ключові райони, в яких містяться важливі ресурси. Метал, зброя, їжа, деревина — все це нам потрібно і все це можна отримати там.\n\nОсь, що я хочу від тебе, {ім'я:к}. Іди в низину Араті, виграй битву, утримавши більше баз, ніж ворог і принеси мені ящик з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його сержанту Очистій в Опорний пункт.", [4] = "Ти {стать:приніс:принесла} ящик з ресурсами, {ім'я:к}? Без них Ліга Аратора багато не навоює...", [5] = "Ти {стать:приніс:принесла} ресурси! Чудова робота! Я відправлю ці ресурси нашим квартирмейстерам, щоб вони якомога швидше роздали їх військам.\n\nДякую тобі, {ім'я:к}. Саме завдяки сумлінному виконанню таких завдань й виграються війни.", ["en"] = "Arathi Basin Resources!", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8156] = { [1] = "Ресурси низини Араті", [2] = "Війну виграють солдати — це тобі скаже будь-який солдат. Він також скаже, що битва, яка ведеться з поганим спорядженням або на порожній шлунок, програна ще до її початку!\n\nОсь чому низина Араті така важлива. У цій низині є ключові райони, в яких містяться важливі ресурси. Метал, зброя, їжа, деревина — все це нам потрібно і все це можна отримати там.\n\nОсь, що я хочу від тебе, {ім'я:к}. Іди в низину Араті, виграй битву, утримавши більше баз, ніж ворог і принеси мені ящик з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його сержанту Очистій в Опорний пункт.", [4] = "Ти {стать:приніс:принесла} ящик з ресурсами, {ім'я:к}? Без них Ліга Аратора багато не навоює...", [5] = "Ти {стать:приніс:принесла} ресурси! Чудова робота! Я відправлю ці ресурси нашим квартирмейстерам, щоб вони якомога швидше роздали їх військам.\n\nДякую тобі, {ім'я:к}. Саме завдяки сумлінному виконанню таких завдань й виграються війни.", ["en"] = "Arathi Basin Resources!", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8157] = { [1] = "Більше ящиків з ресурсами", [2] = "Війну виграють солдати — це тобі скаже будь-який солдат. Він також скаже, що битва, яка ведеться з поганим спорядженням або на порожній шлунок, програна ще до її початку!\n\nОсь чому низина Араті така важлива. У цій низині є ключові райони, в яких містяться важливі ресурси. Метал, зброя, їжа, деревина — все це нам потрібно і все це можна отримати там.\n\nОсь, що я хочу від тебе, {ім'я:к}. Іди в низину Араті, виграй битву, утримавши більше баз, ніж ворог і принеси мені ящик з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його сержанту Очистій в Опорний пункт.", [4] = "{ім'я:к}, твоє завдання лишається незмінним — повертайся в низину Араті, добудь більше ящиків з ресурсами та принеси їх мені.", [5] = "Чудово. Я негайно передам ці ресурси нашим квартирмейстерам, а начальству — подяку за твої дії.\n\nЩе раз дякую тобі, {ім'я:к}. Твій внесок у нашу боротьбу помітили як піхотинці, так і фельдмаршали.", ["en"] = "More Resource Crates", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [81570] = { [1] = "Ярлу потрібне лезо", [2] = "Мені потрібно різати. Не можу сказати, що я збираюся різати, але... мені потрібен клинок. Певний клинок...\n\nДехто називає його мечем з місячної сталі. Я ж називаю його розмахувальним клинком.\n\nДопоможеш мені? Можливо, знайдеш його в місті, можливо, поговориш з ковалем, і він зробить його особливим.\n\nАле не забувай про це. Те, що я ріжу, не збережеться вічно...", [3] = "Принесіть Ярлу в Пилові болота палаш із місячної сталі.", [4] = "У тебе є мій клинок??", [5] = "Це гарне лезо. У нього гарний замах. Це гарне лезо для замаху. Дякую. Дякую, дякую, дякую!!! Тепер я хочу спробувати...\n\nПізніше. Я спробую пізніше. Але, як я вже казав... дякую.", ["en"] = "Jarl Needs a Blade" },
    [8158] = { [1] = "Більше ящиків з ресурсами", [2] = "Війну виграють солдати — це тобі скаже будь-який солдат. Він також скаже, що битва, яка ведеться з поганим спорядженням або на порожній шлунок, програна ще до її початку!\n\nОсь чому низина Араті така важлива. У цій низині є ключові райони, в яких містяться важливі ресурси. Метал, зброя, їжа, деревина — все це нам потрібно і все це можна отримати там.\n\nОсь, що я хочу від тебе, {ім'я:к}. Іди в низину Араті, виграй битву, утримавши більше баз, ніж ворог і принеси мені ящик з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його сержанту Очистій в Опорний пункт.", [4] = "{ім'я:к}, твоє завдання лишається незмінним — повертайся в низину Араті, добудь більше ящиків з ресурсами та принеси їх мені.", [5] = "Чудово. Я негайно передам ці ресурси нашим квартирмейстерам, а начальству — подяку за твої дії.\n\nЩе раз дякую тобі, {ім'я:к}. Твій внесок у нашу боротьбу помітили як піхотинці, так і фельдмаршали.", ["en"] = "More Resource Crates", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [8159] = { [1] = "Більше ящиків з ресурсами", [2] = "Війну виграють солдати — це тобі скаже будь-який солдат. Він також скаже, що битва, яка ведеться з поганим спорядженням або на порожній шлунок, програна ще до її початку!\n\nОсь чому низина Араті така важлива. У цій низині є ключові райони, в яких містяться важливі ресурси. Метал, зброя, їжа, деревина — все це нам потрібно і все це можна отримати там.\n\nОсь, що я хочу від тебе, {ім'я:к}. Іди в низину Араті, виграй битву, утримавши більше баз, ніж ворог і принеси мені ящик з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його сержанту Очистій в Опорний пункт.", [4] = "{ім'я:к}, твоє завдання лишається незмінним — повертайся в низину Араті, добудь більше ящиків з ресурсами та принеси їх мені.", [5] = "Чудово. Я негайно передам ці ресурси нашим квартирмейстерам, а начальству — подяку за твої дії.\n\nЩе раз дякую тобі, {ім'я:к}. Твій внесок у нашу боротьбу помітили як піхотинці, так і фельдмаршали.", ["en"] = "More Resource Crates", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [8160] = { [1] = "Перерізати лінії постачання Аратора", [2] = "Ліга Аратора не шкодує сил на відвоювання низини Араті. Вони, разом зі всіма расами Альянсу, зараз прямують в цей віддалений регіон, маючи намір розширити свої володіння за межі Опорного пункту. Ми повинні зупинити їх, і найкращий спосіб для цього — захопити їхні припаси.\n\n{ім'я:к}, ти можеш нам допомогти. Вирушай в низину Араті, яка відома своїми родючими копальнями, багатими землями та професійними майстрами. Візьми під контроль усі бази, які зможеш, виграй битву і повернись до мене з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його смертолову Мортісу в Молотобій.", [4] = "Що таке, {раса:к}? Ти {стать:приніс:принесла} ящик з ресурсами? Повернись в низину Араті, вбий паразитів з Альянсу та захопи їхні ресурси для Темної Леді!", [5] = "<Смертолов Мортіс посміхається>\n\nТи {стать:завдав:завдала} ще одного потужного удару нашим ворогам, {ім'я:к}. Завдяки тобі, низина Араті скоро буде захоплена Труїтелями.", ["en"] = "Cut Arathor Supply Lines", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8161] = { [1] = "Перерізати лінії постачання Аратора", [2] = "Ліга Аратора не шкодує сил на відвоювання низини Араті. Вони, разом зі всіма расами Альянсу, зараз прямують в цей віддалений регіон, маючи намір розширити свої володіння за межі Опорного пункту. Ми повинні зупинити їх, і найкращий спосіб для цього — захопити їхні припаси.\n\n{ім'я:к}, ти можеш нам допомогти. Вирушай в низину Араті, яка відома своїми родючими копальнями, багатими землями та професійними майстрами. Візьми під контроль усі бази, які зможеш, виграй битву і повернись до мене з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його смертолову Мортісу в Молотобій.", [4] = "Що таке, {раса:к}? Ти {стать:приніс:принесла} ящик з ресурсами? Повернись в низину Араті, вбий паразитів з Альянсу та захопи їхні ресурси для Темної Леді!", [5] = "<Смертолов Мортіс посміхається>\n\nТи {стать:завдав:завдала} ще одного потужного удару нашим ворогам, {ім'я:к}. Завдяки тобі, низина Араті скоро буде захоплена Труїтелями.", ["en"] = "Cut Arathor Supply Lines", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8162] = { [1] = "Перерізати лінії постачання Аратора", [2] = "Ліга Аратора не шкодує сил на відвоювання низини Араті. Вони, разом зі всіма расами Альянсу, зараз прямують в цей віддалений регіон, маючи намір розширити свої володіння за межі Опорного пункту. Ми повинні зупинити їх, і найкращий спосіб для цього — захопити їхні припаси.\n\n{ім'я:к}, ти можеш нам допомогти. Вирушай в низину Араті, яка відома своїми родючими копальнями, багатими землями та професійними майстрами. Візьми під контроль усі бази, які зможеш, виграй битву і повернись до мене з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його смертолову Мортісу в Молотобій.", [4] = "Що таке, {раса:к}? Ти {стать:приніс:принесла} ящик з ресурсами? Повернись в низину Араті, вбий паразитів з Альянсу та захопи їхні ресурси для Темної Леді!", [5] = "<Смертолов Мортіс посміхається>\n\nТи {стать:завдав:завдала} ще одного потужного удару нашим ворогам, {ім'я:к}. Завдяки тобі, низина Араті скоро буде захоплена Труїтелями.", ["en"] = "Cut Arathor Supply Lines", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8163] = { [1] = "Більше ящиків з ресурсами", [2] = "Ліга Аратора не шкодує сил на відвоювання низини Араті. Вони, разом зі всіма расами Альянсу, зараз прямують в цей віддалений регіон, маючи намір розширити свої володіння за межі Опорного пункту. Ми повинні зупинити їх, і найкращий спосіб для цього — захопити їхні припаси.\n\n{ім'я:к}, ти можеш нам допомогти. Вирушай в низину Араті, яка відома своїми родючими копальнями, багатими землями та професійними майстрами. Візьми під контроль усі бази, які зможеш, виграй битву і повернись до мене з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його смертолову Мортісу в Молотобій.", [4] = "{ім'я:к}, твоє завдання лишається незмінним — повертайся в низину Араті, добудь більше ящиків з ресурсами та принеси їх мені.", [5] = "Чудово. Я негайно передам ці ресурси нашим квартирмейстерам, а начальству — подяку за твої дії.\n\nЩе раз дякую тобі, {ім'я:к}. Твій внесок у нашу боротьбу помітили як бугаї, так і воєводи.", ["en"] = "More Resource Crates", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [8164] = { [1] = "Більше ящиків з ресурсами", [2] = "Ліга Аратора не шкодує сил на відвоювання низини Араті. Вони, разом зі всіма расами Альянсу, зараз прямують в цей віддалений регіон, маючи намір розширити свої володіння за межі Опорного пункту. Ми повинні зупинити їх, і найкращий спосіб для цього — захопити їхні припаси.\n\n{ім'я:к}, ти можеш нам допомогти. Вирушай в низину Араті, яка відома своїми родючими копальнями, багатими землями та професійними майстрами. Візьми під контроль усі бази, які зможеш, виграй битву і повернись до мене з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його смертолову Мортісу в Молотобій.", [4] = "{ім'я:к}, твоє завдання лишається незмінним — повертайся в низину Араті, добудь більше ящиків з ресурсами та принеси їх мені.", [5] = "Чудово. Я негайно передам ці ресурси нашим квартирмейстерам, а начальству — подяку за твої дії.\n\nЩе раз дякую тобі, {ім'я:к}. Твій внесок у нашу боротьбу помітили як бугаї, так і воєводи.", ["en"] = "More Resource Crates", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [8165] = { [1] = "Більше ящиків з ресурсами", [2] = "Ліга Аратора не шкодує сил на відвоювання низини Араті. Вони, разом зі всіма расами Альянсу, зараз прямують в цей віддалений регіон, маючи намір розширити свої володіння за межі Опорного пункту. Ми повинні зупинити їх, і найкращий спосіб для цього — захопити їхні припаси.\n\n{ім'я:к}, ти можеш нам допомогти. Вирушай в низину Араті, яка відома своїми родючими копальнями, багатими землями та професійними майстрами. Візьми під контроль усі бази, які зможеш, виграй битву і повернись до мене з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його смертолову Мортісу в Молотобій.", [4] = "{ім'я:к}, твоє завдання лишається незмінним — повертайся в низину Араті, добудь більше ящиків з ресурсами та принеси їх мені.", [5] = "Чудово. Я негайно передам ці ресурси нашим квартирмейстерам, а начальству — подяку за твої дії.\n\nЩе раз дякую тобі, {ім'я:к}. Твій внесок у нашу боротьбу помітили як бугаї, так і воєводи.", ["en"] = "More Resource Crates", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [81682] = { [1] = "Старий чемпіон", [2] = "Ця арена може й не виглядає чимось особливим, але скажу вам, що колись це місце було досить привабливим. Бійці, шукачі пригод, навіть кілька членів картелю, всі виходили на ринг заради шансу на гроші та славу.\n\nМіж азартними іграми та поступками я заробляв неймовірні гроші!\n\nВтім, справи почали стихати після того, як старий чемпіон Каджинд пішов на пенсію. Він був дуже серйозною людиною; одного дня він пішов до Азшари, не сказавши ні слова. Якби ви його знайшли, ми могли б знову відновити роботу арени.", [3] = "Знайдіть Каджинда десь в Азшарі.", [5] = "<На обличчі Каджинда на мить з’являється сумний вираз>\n\nСправді, я той самий «чемпіон», якого ви шукаєте.", ["en"] = "The Old Champ" },
    [81697] = { [1] = "Знешкоджений", [2] = "Битва — це все, що я знаю, {ім'я}. Під час третьої війни незліченна кількість впала перед моїм клинком. Коли війна закінчилася, я проклав собі шлях як бійець-приз. Саме тоді я потрапив на арену Гаджетзана.\n\nМої дні там були славними, але я швидко втомився бути чемпіоном. Я прибув до Азшари в пошуках більшого виклику: синього дракона, який блукає на південний схід звідси. На жаль, істота взяла наді мною гору. Я втік живим, але мій клинок забрали як його скарб.\n\nЯкщо ти повернеш мій клинок, я повернуся з тобою до Гаджетзана.", [3] = "Заберіть клинок Каджинда у синього дракона, що блукає на південний схід від Загубленого хребта в Азшарі.", [4] = "Я не звинувачую твої вагання, {раса}. Дракон — грізний ворог.", [5] = "Там, де я колись зазнав невдачі, ти досяг успіху. Маєш мою найглибшу повагу та вдячність, {ім'я}. Можливо, ти перевершиш мене і на арені.", ["en"] = "Defanged" },
    [81730] = { [1] = "Місія I у Сутінковому лісі: Перемога над воргенами", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів у Гниючий Сад. Переможіть там воргенів і поверніться до мене.", [3] = "Перемогти 10 Бігунів Кошмарів та 10 Ткачів Кошмарів під час Вторгнення Кошмарів у Сутінковий Ліс у Гнилому Саду та повернутися до Польового Капітана Паландара.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission I: Defeat Worgen" },
    [81731] = { [1] = "Місія II у Сутінковому лісі: Перемога над ограми", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів на Кургані Огрів Вул'гол. Переможіть там огрів і поверніться до мене.", [3] = "Перемогти 3 божевільних огрів та 3 божевільних ткачів вогню під час вторгнення Кошмарів Смерколісся на курган огрів Вул'гол та повернутися до польового капітана Паландара.", [4] = "Ти мав справу з огами?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission II: Defeat Ogres" },
    [81732] = { [1] = "Місія Смерколісся III: Перемога над Драконячим Кіном", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів у Садибі Йоргенів. Переможіть там драконів та поверніться до мене.", [3] = "Перемогти 3 Змієподібних Жахливих Ходяків та 10 Драконів Нічного Жаху під час Вторгнення Жахів у Сутінковий Ліс на ферму Йоргенів та повернутися до польового капітана Паландара.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission III: Defeat Dragonkin" },
    [81733] = { [1] = "Місія Смерколісся IV: Розвідка Огрів", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів на Кургані Огрів Вул'гол. Там отримайте розвідувальний звіт від Вартового Сну Талінара та поверніться до мене.", [3] = "Зберіть розвідувальну інформацію від Вартового Снів Талінара під час Вторгнення Кошмарів у Сутінковий Ліс глибоко всередині Кургану Огрів Вул'гол і поверніться до польового капітана Паландара.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission IV: Ogre Intelligence" },
    [81734] = { [1] = "Місія V у Сутінковому лісі: Розвідка воргенів", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів у Гниючий Сад. Там отримайте розвідувальний звіт від Вартового Сну Дорілара та поверніться до мене.", [3] = "Зберіть розвідувальні дані від Вартового Снів Дорілара під час Вторгнення Кошмарів Смерколісся в сараї Гниючого Саду та поверніться до польового капітана Паландара.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission V: Worgen Intelligence" },
    [81735] = { [1] = "Місія VI Смерколісся: Розвідка Дракона", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів на ферму Йоргенів. Там отримайте розвідувальний звіт від Вартової Снів Амалії та поверніться до мене.", [3] = "Зберіть розвідувальну інформацію від Вартової Снів Амалії під час Вторгнення Кошмарів у Сутінковий Ліс у фермерському будинку на фермі Йоргенів та поверніться до польового капітана Паландара.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission VI: Dragon Intelligence" },
    [81736] = { [1] = "Смерколісся, місія VII: Відновлення Тіньової Коси", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів у Гниючий Сад. Знайдіть потужний артефакт, відомий як Тіньова Коса, та доставте його мені.", [3] = "Знайдіть Тіньову Косу під час Вторгнення Кошмарів у Сутінковий Ліс нагорі у фермерському будинку в Гнилому Саду та поверніться до польового капітана Паландара.", [4] = "У тебе є Тіньова Коса?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission VII: Recover Shadowscythe" },
    [81737] = { [1] = "Смерколісся, місія VIII: Відновлення тексту магів-огрів", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів на Кургані Огрів Вул'гол. Знайдіть Текст Огрського Мага та доставте його мені.", [3] = "Знайдіть Текст Мага-огра під час Вторгнення Кошмарів у Сутінковий Ліс у Кургані Огрів Вул'гол та поверніться до польового капітана Паландара.", [4] = "У тебе є текст?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission VIII: Recover Ogre Magi text" },
    [81738] = { [1] = "Місія IX у Сутінковому лісі: Віднайти яйце дракона", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів на ферму Йоргенів. Знайдіть невилуплене яйце Зеленого Дракона та доставте його мені.", [3] = "Під час вторгнення Кошмарів у Сутінковий Ліс знайдіть невилуплене яйце Зеленого Дракона на фермі Йоргенів біля великого пня в полі та поверніться до польового капітана Паландара.", [4] = "У тебе є яйце?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission IX: Recover Dragon Egg" },
    [81739] = { [1] = "Місія X у Сутінковому лісі: Кошмарний мох", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та зберіть Кошмарний Мох з-під Кошмарних Вторгнень. Ми можемо використати його магію, щоб усунути завдану шкоду. Тобі знадобиться допомога травника.", [3] = "Зберіть 10 Кошмарного моху під час Кошмарних вторгнень у Смерколісся та поверніться до польового капітана Паландара.", [4] = "У вас є Кошмарний Мох?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission X: Nightmare Moss" },
    [81740] = { [1] = "Смерколісся, місія XI: Холодна залізна руда", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та зберіть Холодну Залізну Руду з-під Набігів Кошмарів. Ми можемо використати її магію, щоб повернути назад шкоду. Тобі знадобиться допомога шахтаря.", [3] = "Зберіть 10 одиниць холодної залізної руди під час набігів Кошмарів у Сутінковому лісі та поверніться до польового капітана Паландара.", [4] = "У вас є Холодна Залізна Руда?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission XI: Cold Iron Ore" },
    [81741] = { [1] = "Смерколісся, місія XII: Драконяча луска, доторкнута мріями", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та зберіть Доторкнуту Сном Драконячу Луску у драконів у межах Вторгнення Кошмарів. Ми можемо використати її магію, щоб повернути назад шкоду. Тобі знадобиться допомога шкуродера.", [3] = "Зберіть 10 Драконячих Лусок, Доторкнутих Сном, під час Набігів Кошмарів Смерколісся та поверніться до Польового Капітана Паландара.", [4] = "У тебе є Луска Дракона?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission XII: Dream-Touched Dragonscale" },
    [81742] = { [1] = "Місія XIII Смерколісся: Перемога над Ілантріусом", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів у Садибу Йоргенів. Переможіть там дракона Ілантріуса та поверніться до мене.", [3] = "Переможіть Ілантріуса під час вторгнення Кошмарів у Сутінковий Ліс на полі ферми Йорген та поверніться до польового капітана Паландара.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission XIII: Defeat Ylanthrius" },
    [81743] = { [1] = "Місія XIV у Сутінковому лісі: Перемога над Вварц'зулом", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів на Кургані Огрів Вул'гол. Переможіть там воєначальника огрів Вварц'зула та поверніться до мене.", [3] = "Переможіть Вварц'зула під час Вторгнення Кошмарів у Сутінковий Ліс глибоко в Кургані Огрів Вул'гол і поверніться до польового капітана Паландара.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission XIV: Defeat Vvarc'zul" },
    [81744] = { [1] = "Місія XV у Сутінковому лісі: Перемога над Амокароком", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів у Гниючий Сад. Переможіть там лідера воргенів Амокарока та поверніться до мене.", [3] = "Переможіть Амокарока під час Вторгнення Кошмарів у Сутінковий Ліс на кемпінгу біля сараю в Гнилому Саду та поверніться до польового капітана Паландара.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission XV: Defeat Amokarok" },
    [81745] = { [1] = "Місія XVI у Сутінковому лісі: Порятунок Кролла Гірської Тіні", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів у Гниючий Сад. Знайдіть там сплячого Друїда Кігтячого Кролла Гірської Тіні та супроводьте його у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Кролла Гірської Тіні від вторгнення Кошмарів Смерколісся в гостьовому будинку в Гнилому Саду та поверніться до польового капітана Паландара.", [4] = "Ти врятував Кролла?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission XVI: Rescue Kroll Mountainshade" },
    [81746] = { [1] = "Місія XVII Смерколісся: Порятунок Алари Гроувмендер", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів у Йорген Дармстед. Знайдіть там сплячу Друїдку Кігтя Алару, Засновницю Гаю, та супроводьте її у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Алару Гроувмендер під час вторгнення Кошмарів у Сутінковий Ліс у стайні на фермі Йоргенів та поверніться до польового капітана Паландара.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission XVII: Rescue Alara Grovemender" },
    [81747] = { [1] = "Місія «Смерколісся» XVIII: Порятунок Еленори Маршволкер", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів на Кургані Людожерів Вул'гол. Знайдіть там сплячу Друїдку Кігтя Еленору Болотянку та супроводьте її у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Еленору Болотяну Уокер під час Вторгнення Кошмарів Смерколісся в руїнах фермерського будинку поблизу кургану Вул'гол Огр і поверніться до польового капітана Паландара.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Duskwood Mission XVIII: Rescue Elenora Marshwalker" },
    [81768] = { [1] = "Місія I в Ясенедолі: Перемога над сатирами", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Сатирнаар. Переможіть там сатирів і поверніться до мене.", [3] = "Перемогти 10 Зрадників Снівного Вогню та 10 Заклиначів Пекла Снівного Вогню під час Вторгнення Кошмарів Попелястого Долини в Сатирнаарі та повернутися до польового капітана Ханнали.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission I: Defeat Satyrs" },
    [81769] = { [1] = "Місія II в Ясенедолі: Перемога над ентами", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісопиломному Таборі Пісні Війни. Переможіть там ентів та поверніться до мене.", [3] = "Перемогти 7 мстивих Древніх під час вторгнення Кошмарів Ясенеділу в Лісопиловий табір Пісні Війни та повернутися до польового капітана Ханнали.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission II: Defeat Treants" },
    [81770] = { [1] = "Місія III у Ясенедолі: Перемога над Драконяком", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісовій Пісні. Переможіть там драконів і поверніться до мене.", [3] = "Перемогти 3 нічних мисливців-зміїв та 10 драконів жаху під час вторгнення кошмарів у Ясенеділ у Лісовій пісні та повернутися до польового капітана Ханнали.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission III: Defeat Dragonkin" },
    [81771] = { [1] = "Місія IV у Ясенедолі: Розвідка Дракона", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісовій Пісні. Отримайте там розвідувальний звіт від Вартового Сну Еллодара та поверніться до мене.", [3] = "Зберіть розвідувальну інформацію від Вартового Снів Еллодара під час Вторгнення Кошмарів у Ясеневий Ліс у Лісовій Пісні на мосту до стародавньої вежі та поверніться до польового капітана Ханнали.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission IV: Dragon Intelligence" },
    [81772] = { [1] = "Місія V у Ясенедолі: Розвідка Сатирів", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Сатирнаар. Там отримайте розвідувальний звіт від Вартового Сну Мандорана та поверніться до мене.", [3] = "Зберіть розвідувальні дані від Вартового Снів Мандорана під час Вторгнення Кошмарів Ясенеділу в ритуальному колі в Сатирнаарі та поверніться до польового капітана Ханнали.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission V: Satyr Intelligence" },
    [81773] = { [1] = "Місія в Ясенедолі VI: Розвіддані деревантів", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісопиломний Табір Пісні Війни. Отримайте там розвідувальний звіт від Вартової Снів Ланарії та поверніться до мене.", [3] = "Зберіть розвідувальну інформацію від Вартової Снів Ланарії під час вторгнення Кошмарів Ясенеділу в фортецю Каргатія в Лісопиломному таборі Пісні Війни та поверніться до польового капітана Ханнали.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission VI: Treant Intelligence" },
    [81774] = { [1] = "Місія в Ясенедолі VII: Повернення сновидвигуна", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісопиломному Таборі Пісні Війни. Знайдіть потужний артефакт, відомий як Двигун Снів, та доставте його мені.", [3] = "Під час вторгнення Кошмарів у Ясеневий Ліс знайдіть Двигун Снів у кузні Лісопиломного Табору Пісні Війни та поверніть його польовому капітану Ханналі.", [4] = "У тебе є сновидвигун?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission VII: Recover Dreamengine" },
    [81775] = { [1] = "Місія VIII у Ясенедолі: Відновлення пророцтва Азшари", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Сатирнаар. Знайдіть загублений сувій, відомий як Пророцтво Азшари, та доставте його мені.", [3] = "Знайдіть Азшаранське пророцтво під час Вторгнення Кошмарів у Ясеневий Ліс з невеликого намету в Сатирнаарі та поверніться до польового капітана Ханнали.", [4] = "У тебе є Пророцтво Азшари?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission VIII: Recover Azsharan Prophecy" },
    [81776] = { [1] = "Місія IX у Ясенедолі: Віднайти Драконяче Яйце, Доторкнуте Сном", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісовій Пісні. Знайдіть Доторкнуте Сном Драконяче Яйце та доставте його мені.", [3] = "Знайдіть Доторкнуте сном Драконяче Яйце під час Вторгнення Кошмарів Ясенеділу з центральних руїн у Лісовій Пісні та поверніть його до польового капітана Ханнали.", [4] = "У тебе є яйце?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission IX: Recover Dream-Touched Dragonegg", ["tasks"] = { ["Dream-Touched Dragon Egg"] = "Яйце Дракона, Доторкнутого Сном" } },
    [81777] = { [1] = "Місія X у Ясенедолі: Корінь Снів", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та зберіть Корінь Сну з-поміж Вторгнень Кошмарів. Ми можемо використати його магію, щоб повернути назад шкоду. Тобі знадобиться допомога травника.", [3] = "Зберіть 10 Коренів Сновидінь у Вторгненнях Кошмарів Есенвейлу та поверніться до польового капітана Ганнали.", [4] = "У тебе є Дрімкорінь?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission X: Dreamroot" },
    [81778] = { [1] = "Місія XI в Ясенедолі: Золотий пил дурнів", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та зберіть Золотий Пил Дурня з-під Набігів Кошмарів. Ми можемо використати його магію, щоб усунути завдану шкоду. Тобі знадобиться допомога шахтаря.", [3] = "Зберіть 10 Золотого пилу дурнів під час Набігів Кошмарів Ясенеділу та поверніться до польового капітана Ханнали.", [4] = "У тебе є Золотий Пилок Дурня?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission XI: Fool's Gold Dust" },
    [81779] = { [1] = "Місія XII у Ясенедолі: Сповнена мрій луска дракона", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та зберіть Наповнену Сном Драконячу Луску у драконів під час Вторгнень Кошмарів. Ми можемо використати її магію, щоб повернути назад шкоду. Тобі знадобиться допомога шкуродера.", [3] = "Зберіть 10 сповнених мрій драконячої луски під час вторгнень Кошмарів Ясенеділу та поверніться до польового капітана Ханнали.", [4] = "У тебе є Сповнена Мріями Драконяча Луска?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission XII: Dream-Infused Dragonscale" },
    [81780] = { [1] = "Місія XIII у Ясенедолі: Перемога над Ларсерою", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісовій Пісні. Переможіть там дракона Ларсеру та поверніться до мене.", [3] = "Переможіть Ларсеру під час Вторгнення Кошмарів Ясенеділу біля центральних руїн у Лісовій Пісні та поверніться до польового капітана Ханнали.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission XIII: Defeat Larsera" },
    [81781] = { [1] = "Місія XIV у Ясенедолі: Перемога над Заліусом", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісовій Пісні. Переможіть там сатира Заліуса та поверніться до мене.", [3] = "Переможіть Заліуса під час вторгнення Кошмарів Ясенеділу біля основи зиккурату в Сатирнаарі та поверніться до польового капітана Ханнали.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission XIV: Defeat Zalius" },
    [81782] = { [1] = "Місія XV у Ясенедолі: Перемогти Шреддера 9000", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісопиломному Таборі Пісні Війни. Переможіть там Шреддера 9000 та поверніться до мене.", [3] = "Перемогти Шреддера 9000 під час вторгнення Кошмарів у Ясеневий Ліс біля лісорубних кранів у Лісопиломному таборі Пісні Війни та повернутися до польового капітана Ханнали.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission XV: Defeat Shredder 9000" },
    [81783] = { [1] = "Місія XVI у Ясенедолі: Порятунок Алісіанської Заклинальниці Вітрів", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісопиломному Таборі Пісні Війни. Знайдіть там сплячу Друїдку Кігтя Аліссианку Заклинательку Вітрів та супроводьте її у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Алісіан Вітрокалер від вторгнення Кошмарів Ясенеділу біля підніжжя сторожової вежі в Лісопиломному таборі Пісні Війни та поверніть її до польового капітана Ханнали.", [4] = "Ти врятував Алісіан?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission XVI: Rescue Alyssian Windcaller" },
    [81784] = { [1] = "Місія в Ясенедолі XVII: Порятунок Дорана Дрімбау", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісовій Пісні. Знайдіть там сплячого Друїда Кігтя Дорана Снового Гілки та супроводьте його у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Дорана Снового Гілля від вторгнення Кошмарів Ясеневого Долу в альтанці, освітленій місячним світлом, у Лісовій Пісні, та поверніться до польового капітана Ханнали.", [4] = "Ти врятував Дорана?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission XVII: Rescue Doran Dreambough" },
    [81785] = { [1] = "Місія в Ясенедолі XVIII: Порятунок Масеари Осіннього Місяця", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Сатирнаар. Знайдіть там сплячу Друїдку Кігтя Масеару Осінній Місяць та супроводьте її у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Масеару Осінній Місяць від вторгнення Кошмарів Ясенеділу у південно-східному скупченні наметів у Сатирнаарі та поверніться до польового капітана Ханнали.", [4] = "Ти врятував Масеару?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Ashenvale Mission XVIII: Rescue Maseara Autumnmoon" },
    [81786] = { [1] = "Місія у Внутрішніх землях I: Перемога над місяцезвірами", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів на Скелі Скльк. Переможіть там місячних родичів та поверніться до мене.", [3] = "Перемогти 20 загиблих місячних під час вторгнення Кошмарів у Внутрішні землі на Скалк Рок та повернутися до польового капітана Корліана.", [4] = "Ти мав справу з місячною людиною?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission I: Defeat Moonkin" },
    [81787] = { [1] = "Місія у Внутрішніх землях II: Перемога над велетенськими черепахами", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів у Шаол'вату. Переможіть там гігантських черепах і поверніться до мене.", [3] = "Перемогти 20 Візеджоу Снів Води під час Вторгнення Кошмарів у Внутрішні Землі на Шаол'ваті та повернутися до польового капітана Корліана.", [4] = "Ви мали справу з черепахами?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission II: Defeat Giant Turtles" },
    [81788] = { [1] = "Місія у Внутрішніх землях III: Перемога над драконідами", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів в Агол'вату. Переможіть там драконів та поверніться до мене.", [3] = "Перемогти 10 Драконів Гніву та 3 Зоряних Мисливців-Зміїв під час Вторгнення Кошмарів у Внутрішні Землі на Агол'ваті та повернутися до польового капітана Корліана.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission III: Defeat Dragonkin" },
    [81789] = { [1] = "Місія у Внутрішніх землях IV: Розвіддані про драконів", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів в Агол'ват. Там отримайте розвідувальний звіт від Вартового Сну Ланінара та поверніться до мене.", [3] = "Зберіть розвідувальні дані від Вартового Снів Ланінара під час Вторгнення Кошмарів у Внутрішні Землі біля арки в Агол'ваті та поверніться до польового капітана Корліана.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission IV: Dragon Intelligence" },
    [81801] = { [1] = "Повернення на арену", [2] = "Я — орк, який дав слово. Ти помстився за мене, і я відплатжу тобі тим самим. Іди до Ґаджетзана та скажи Фізбузу, що він повернув свого чемпіона.\n\nСподіваюся побачити тебе на рингу.", [3] = "Поверніться до Фізбуза Міфрилу в Гаджетзані, Танаріс.", [5] = "Видовищно! Усі збожеволіють, коли почують, що старий Каджинд повернувся до міста.\n\nА ти казав, що вбив дракона заради цього хлопця!? Звучить так, ніби ти сам будеш неабияким приманкою.\n\nЯ вже це відчуваю, {ім'я}. Зараз тут буде справжній гуркіт!", ["en"] = "Return to the Arena" },
    [8181] = { [1] = "Протистояння Є'кіньї", [2] = "Мої дослідження скрижалей Мош'ару приносять похмурі новини, {ім'я}. Справжня форма Гаккара, самого бога, може бути відроджена через саме яйце, у яке ти його {стать:ув'язнив:ув'язнила}. Є'кінья говорив тобі, що воно має утримувати його сутність, але насправді воно потрібне для його відродження! Троль тебе надурив!\n\nЙди до Є'кіньї та вимагай повернути. Молись, щоб не було надто пізно зупинити повернення Гаккара!", [3] = "Поговоріть з Є'кіньєю.", [5] = "Отже, ти {стать:говорив:говорила} зі старим дворфом Залізочоботом і {стать:знайшов:знайшла} загублені скрижалі Мош'ару, так? Настирливий розвідувач...\n\nНеважливо. Занадто пізно рятувати цей світ. Гаккар відродився, і прямо зараз набирається сил... глибоко в стародавньому королівстві тролів Зул'Ґурубі! Він прийшов! І він буде правити кров'ю і терором!\n\nДякую, {ім'я}. Твоя допомога прискорила повернення Здирача Душ!", ["en"] = "Confront Yeh'kinya" },
    [81817] = { [1] = "Місія V для Внутрішніх земель: Розвідка черепах", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів у Шаол'ват. Там отримайте розвідувальний звіт від Вартової Снів Санатель та поверніться до мене.", [3] = "Зберіть розвідувальну інформацію від Вартової Снів Санатель під час Вторгнення Кошмарів у Внутрішні Землі за барабаном у Шаол'ваті та поверніться до польового капітана Корліана.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission V: Turtle Intelligence" },
    [8182] = { [1] = "Рука Растахана", [2] = "{ім'я}, наші найгірші страхи збулися. Легенда розповідає про Здирача Душ, який правив стародавнім світом тролів за допомогою зла і терору, і його влада була абсолютною. Якщо його не зупинити зараз, то його нова влада може поширитися на весь Азерот!\n\nТролі Зандалара можуть допомогти нам стримати це зло. Вони знаходяться на острові Йоджамба, на узбережжі Тернистої долини, на заході від руїн Зул'Кунди. Поговори з їхнім лідером, Молтором, і молись, щоб він знав, як перемогти Гаккара.", [3] = "Поговоріть з Молтором у Тернистій долині.", [5] = "Тебе прислав розвідувач Залізочобіт? Його вид мудрий, а він ще мудріший, якщо прислав тебе до мене, бо зандаларські тролі можуть знати спосіб перемогти Здирача Душ.\n\nПоговори з тролями цього острова, слухай їх і готуйся, {ім'я}, бо завдання, яке стоїть перед тобою просочене кров'ю.", ["en"] = "The Hand of Rastakhan" },
    [81820] = { [1] = "Місія VI для Внутрішніх земель: Розвідка Місячної Сфери", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів у Скелі Скльк. Там отримайте розвідувальний звіт від Вартової Снів Валорі та поверніться до мене.", [3] = "Зберіть розвідувальну інформацію від Вартової Снів Валорі під час Вторгнення Кошмарів у Внутрішні Землі біля підземного озера в Скалк-Рок та поверніться до польового капітана Корліана.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission VI: Moonkin Intelligence" },
    [81826] = { [1] = "Місія VII у глибинних землях: Повернення Драконячого Яйця, Доторкнутого Зорями", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів в Агол'вату. Знайдіть Зоряно-Доторкнуте Драконяче Яйце та доставте його мені.", [3] = "Під час Вторгнення Кошмарів у Внутрішні Землі знайдіть Зоряне Драконяче Яйце з центральної хатини в Агол'ваті та поверніть його польовому капітану Корліану.", [4] = "У тебе є яйце?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission VII: Recover Star-Touched Dragonegg" },
    [8183] = { [1] = "Серце Гаккара", [2] = "Серце Гаккара палає зсередини. Хоча Здирач Душ переможений, джерело його сили все ще залишається в цьому проклятому серці.", [3] = "Принесіть серце Гаккара до Молтора на острів Йоджамба.", [4] = "{ім'я}, тебе оточує сморід злої душі. Тебе прокляв Здирач Душ?", [5] = "А, серце Гаккара. Отже, Здирач Душ мертвий! Наш світ врятовано!\n\n{ім'я}, твої подвиги неможливо переоцінити. Ти воістину {стать:герой:героїня} цього світу!", ["en"] = "The Heart of Hakkar", ["tasks"] = { ["Heart of Hakkar"] = "серце Гаккара", ["Heart of Hakkar (Provided)"] = "серце Гаккара (видано)" } },
    [81830] = { [1] = "Місія VIII у Внутрішніх землях: Відновлення реліквії Елунару", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів у Скелі Скльк. Знайдіть реліквію Елунару, яку там заховали місячні, та доставте її мені.", [3] = "Під час Вторгнення Кошмарів у Внутрішні Землі знайдіть реліквію Елунара з високого виступу всередині Скелі Скалк і поверніться до польового капітана Корліана.", [4] = "У тебе є реліквія?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission VIII: Recover Elunar Relic" },
    [81832] = { [1] = "Місія IX у Внутрішніх землях: Відновлення Перлини Сну", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів у Шаол'вату. Знайдіть Перлину Сну, яку там заховали черепахи, та доставте її мені.", [3] = "Під час Вторгнення Кошмарів у Внутрішні Землі знайдіть Перлину Снів у фонтані змії в Шаол'ваті та поверніть її до польового капітана Корліана.", [4] = "У тебе є перлина?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission IX: Recover Dreampearl" },
    [81833] = { [1] = "Місія X для Внутрішніх земель: Зоряний Лотос", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та зберіть Зоряний Лотос з-поміж Набігів Кошмарів. Ми можемо використати його магію, щоб повернути назад шкоду. Тобі знадобиться допомога травника.", [3] = "Зберіть 10 Зоряних Лотосів під час Вторгнень Кошмарів у Внутрішні землі та поверніться до польового капітана Корліана.", [4] = "У тебе є Зоряний Лотос?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission X: Star Lotus" },
    [81834] = { [1] = "Місія XI в глибинці: Руда Зоряного срібла", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та зберіть руду Зоряного Срібла з-під Навал Кошмарів. Ми можемо використати її магію, щоб повернути назад шкоду. Тобі знадобиться допомога шахтаря.", [3] = "Зберіть 10 руди Зоряного срібла під час Вторгнень Кошмарів у Внутрішні землі та поверніться до польового капітана Корліана.", [4] = "У тебе є руда Зоряного срібла?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission XI: Starsilver Ore" },
    [81835] = { [1] = "Місія у Внутрішніх землях XII: Зоряні снаряди", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та зберіть Шаршели у гігантських черепах під час Набігів Кошмарів. Ми можемо використати їхню магію, щоб повернути назад шкоду. Тобі знадобиться допомога шкуродера.", [3] = "Зберіть 10 шаршнів під час Кошмарних вторгнень у Внутрішні землі та поверніться до польового капітана Корліана.", [4] = "У тебе є Зоряні мушлі?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission XII: Starshells" },
    [81837] = { [1] = "Місія XIII у глибинних землях: Перемога над Флоріусом", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів в Агол'ваті. Переможіть там дракона Флоріуса та поверніться до мене.", [3] = "Переможіть Флоріуса під час Вторгнення Кошмарів у Внутрішні землі на головному подвір'ї в Агол'ваті та поверніться до польового капітана Корліана.", [4] = "Ти мав справу з Флоріусом?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission XIII: Defeat Florius" },
    [81838] = { [1] = "Місія у Внутрішніх землях XIV: Перемога над згубниками", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів у Скелі Скльк. Переможіть там велетня-місячника, відомого як Думкін, та поверніться до мене.", [3] = "Переможіть Думкіна під час Вторгнення Кошмарів у Внутрішні Землі на глибокому виступі всередині Скелі Скалк і поверніться до польового капітана Корліана.", [4] = "Ти мав справу з Думкіном?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission XIV: Defeat Doomkin" },
    [81839] = { [1] = "Місія XV у глибинних землях: Перемога над Гаму-Раджею", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів у Шаол'вату. Переможіть там \"короля\" черепах, відомого як Гаму-Раджа, та поверніться до мене.", [3] = "Переможіть Гаму-Раджу під час Вторгнення Кошмарів у Внутрішні землі у дворі Шаол'вати та поверніться до польового капітана Корліана.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission XV: Defeat Ghamoo-Raja" },
    [8184] = { [1] = "Явлення могутності", [4] = "Занза може створити стародавні чари тролів з правильними компонентами.\n\nПерший — це первісний ідол Гаккарі, який треба взяти у наймогутніших лейтенантів Гаккарі: Джин'до та Мандокіра, повелителя крові.\n\nДругий — це проколота лялька вуду. Їх можна знайти в купах сміття, якими завалене це мерзотне місце. Поглянь в купах зачарованих худу.\n\nПринеси мені їх, і я створю для тебе потужні чари!", [5] = "Використовуй їх з розумом, {клас:к}. Не щади Гаккарі!", ["en"] = "Presence of Might", ["tasks"] = { ["Primal Hakkari Idol"] = "первісний ідол Гаккарі", ["Primal Hakkari Idol (Provided)"] = "первісний ідол Гаккарі (видано)", ["Punctured Voodoo Doll"] = "проколота лялька вуду", ["Punctured Voodoo Doll (Provided)"] = "проколота лялька вуду (видано)" } },
    [8185] = { [1] = "Сигіла синкретиста", [4] = "Занза може створити стародавні чари тролів з правильними компонентами.\n\nПерший — це первісний ідол Гаккарі, який треба взяти у наймогутніших лейтенантів Гаккарі: Джин'до та Мандокіра, повелителя крові.\n\nДругий — це проколота лялька вуду. Їх можна знайти в купах сміття, якими завалене це мерзотне місце. Поглянь в купах зачарованих худу.\n\nПринеси мені їх, і я створю для тебе потужні чари!", [5] = "Використовуй їх з розумом, {клас:к}. Не щади Гаккарі!", ["en"] = "Syncretist's Sigil", ["tasks"] = { ["Primal Hakkari Idol"] = "первісний ідол Гаккарі", ["Primal Hakkari Idol (Provided)"] = "первісний ідол Гаккарі (видано)", ["Punctured Voodoo Doll"] = "проколота лялька вуду", ["Punctured Voodoo Doll (Provided)"] = "проколота лялька вуду (видано)" } },
    [81850] = { [1] = "Місія XVI у глибинних землях: Порятунок Еліанара Тіньопивки", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів в Агол'вату. Знайдіть там сплячого Друїда Кігтя Еліанара Тіньопивцю та супроводьте його у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Еліанар Тіньопиючу від вторгнення Кошмарів Внутрішніх Земель у трольському укріпленні поблизу Агол'вати та поверніться до польового капітана Корліана.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission XVI: Rescue Elianar Shadowdrinker" },
    [81851] = { [1] = "Місія XVII у Внутрішніх землях: Порятунок Серліни Старбрайт", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів у Шол'вату. Знайдіть там сплячу Друїдку Кігтя Серліну Старбрайт та супроводьте її у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Серліну Старбрайт від вторгнення Кошмарів Внутрішніх Земель у найближчому до Шол'вати трольському укріпленні та поверніться до польового капітана Корліана.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission XVII: Rescue Serlina Starbright" },
    [81852] = { [1] = "Місія XVIII у глибинних землях: Порятунок Веанни Хмарносплячої", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Серадані та вирушайте до Вторгнення Кошмарів на Скелі Скльк. Знайдіть там сплячого Друїда Кігтя Веанни Хмарної Сплячої та супроводьте її у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Веанну Хмаросплячу від Вторгнення Кошмарів Гінтерленду в гамаку над Скелею Скалк і поверніться до польового капітана Корліана.", [4] = "Ти врятував Веанну?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Hinterlands Mission XVIII: Rescue Veanna Cloudsleeper" },
    [81855] = { [1] = "Місія Фералас I: Перемогти дітей Кенарія", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів у Подвійних Колосалах. Переможіть там божевільних синів і дочок Кенарія та поверніться до мене.", [3] = "Перемогти 10 Загублених Дочок та 10 Мстивих Синів під час Вторгнення Кошмарів Фералас у Подвійних Колосалів та повернутися до Польового Капітана Аруннела.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission I: Defeat Children of Cenarius" },
    [81856] = { [1] = "Місія Фералас II: перемогти Гарпій", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів у Руїни Рейвенвінда. Переможіть там гарпій і поверніться до мене.", [3] = "Перемогти 10 Розбійників-Перят з Мрій та 10 Буревісників з Мрій під час Вторгнення Кошмарів Фералас у Руїни Рейвенвінда та повернутися до польового капітана Аруннела.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission II: Defeat Harpies" },
    [81857] = { [1] = "Місія Фералас III: Перемогти Драконяка", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів в Онейрос. Переможіть там драконів і поверніться до мене.", [3] = "Перемогти 10 шалених дракончиків та 3 змієподібних берсеркерів під час вторгнення кошмарів Фералас в Онейрос та повернутися до польового капітана Аруннела.", [4] = "Ти мав справу з драконом?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission III: Defeat Dragonkin" },
    [81858] = { [1] = "Місія Фералас IV: Розвідка Дракона", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів в Онейрос. Там отримайте розвідувальний звіт від Вартового Снів Шелдріна та поверніться до мене.", [3] = "Зберіть розвідувальні дані від Вартового Снів Шелдрін під час Вторгнення Кошмарів Фералас у найпівденніші руїни Онейроса та поверніться до польового капітана Аруннела.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission IV: Dragon Intelligence" },
    [81859] = { [1] = "Місія Фералас V: Розвідка Кенаріона", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів у Подвійних Колосалах. Там отримайте розвідувальний звіт від Вартового Снів Горласа та поверніться до мене.", [3] = "Зберіть розвідувальні дані від Вартового Снів Горласа під час Вторгнення Кошмарів Фераласу біля водоспаду у Подвійних Колосалах та поверніться до польового капітана Аруннела.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission V: Cenarion Intelligence" },
    [8186] = { [1] = "Обійми смерті", [4] = "Занза може створити стародавні чари тролів з правильними компонентами.\n\nПерший — це первісний ідол Гаккарі, який треба взяти у наймогутніших лейтенантів Гаккарі: Джин'до та Мандокіра, повелителя крові.\n\nДругий — це проколота лялька вуду. Їх можна знайти в купах сміття, якими завалене це мерзотне місце. Поглянь в купах зачарованих худу.\n\nПринеси мені їх, і я створю для тебе потужні чари!", [5] = "Використовуй їх з розумом, {клас:к}. Не щади Гаккарі!", ["en"] = "Death's Embrace", ["tasks"] = { ["Primal Hakkari Idol"] = "первісний ідол Гаккарі", ["Primal Hakkari Idol (Provided)"] = "первісний ідол Гаккарі (видано)", ["Punctured Voodoo Doll"] = "проколота лялька вуду", ["Punctured Voodoo Doll (Provided)"] = "проколота лялька вуду (видано)" } },
    [81860] = { [1] = "Місія VI Фералас: Розвідка гарпій", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів у Руїни Рейвенвінда. Отримайте там розвідувальний звіт від Вартової Снів Анадель і поверніться до мене.", [3] = "Зберіть розвідувальні дані від Вартової Снів Анадель під час Вторгнення Кошмарів Фералас у зруйнованій альтанці в Руїнах Рейвенвінда та поверніться до польового капітана Аруннела.", [4] = "У вас є звіт?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission VI: Harpy Intelligence" },
    [81861] = { [1] = "Місія у Фераласі VII: Повернення яйця місяцесвітлого дракона", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів в Онейрос. Знайдіть Драконяче Яйце Місячного Сяйва та доставте його мені.", [3] = "Під час вторгнення Кошмарів Фералас під час пошуків Яйце дракона Місячного Сяйва з альтанки в Онейросі поверніться до польового капітана Аруннела.", [4] = "У тебе є яйце?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission VII: Recover Moonglow Dragonegg" },
    [81863] = { [1] = "Місія Фералас VIII: Віднайти нотатки хранителя", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів у Подвійних Колосалах. Заберіть Записки Божевільного Хранителя та доставте їх мені.", [3] = "Знайдіть Нотатки Божевільного Хранителя під час Вторгнення Кошмарів Фералас на східному схилі західного колосалу біля Подвійних Колосалів і поверніться до польового капітана Аруннела.", [4] = "У тебе є нотатки?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission VIII: Recover Keeper's Notes" },
    [81864] = { [1] = "Місія Фералас IX: Відновлення ґрунту Гарпії", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів у Руїни Рейвенвінда. Знайдіть Скрид гарпії та доставте його мені.", [3] = "Під час вторгнення Кошмарів Фералас під час пошуків Гарпійного скріда з південно-західної альтанки в Руїнах Рейвенвінда під час пошуків Рейвенвінда під час бойових дій, знайдіть його та поверніться до польового капітана Аруннела.", [4] = "У вас є стяжка?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission IX: Recover Harpy Screed" },
    [81865] = { [1] = "Місія Фералас X: Місячний корінь", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і зберіть Місячний Корінь з-під Набігів Кошмарів. Ми можемо використати його магію, щоб повернути назад шкоду. Тобі знадобиться допомога травника.", [3] = "Зберіть 10 Місячних коренів під час Набігів Кошмарів Фералас та поверніться до польового капітана Аруннела.", [4] = "У тебе є Місячний корінь?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission X: Moonroot" },
    [81866] = { [1] = "Місія Фералас XI: Великий Місячний камінь", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і зберіть Великий Місячний Камінь з-під Навал Кошмарів. Ми можемо використати його магію, щоб повернути назад шкоду. Тобі знадобиться допомога шахтаря.", [3] = "Зберіть 10 Великих Місячних Каменів під час Набігів Кошмарів Фераласу та поверніться до Польового Капітана Аруннела.", [4] = "У тебе є Великий Місячний Камінь?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission XI: Greater Moonstone" },
    [81867] = { [1] = "Місія Фералас XII: Луска Великого Місячного Дракона", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і зберіть Луску Місячного Дракона у драконів під час Вторгнення Кошмарів. Ми можемо використати його магію, щоб повернути назад шкоду. Тобі знадобиться допомога шкуродера.", [3] = "Зберіть 10 лусочок місячного дракона в Кошмарних вторгненнях Фераласа та поверніться до польового капітана Аруннела.", [4] = "У тебе є луска дракона?", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission XII: Greater Moondragon Scales" },
    [81868] = { [1] = "Місія Фералас XIII: перемогти Тираника", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів в Онейросі. Переможіть там дракона Тіраннікуса і поверніться до мене.", [3] = "Переможіть Тіраннікуса під час вторгнення Кошмарів Фералас у зруйнований храм в Онейросі та поверніться до польового капітана Аруннела.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission XIII: Defeat Tyrannikus" },
    [8187] = { [1] = "Поклик сокола", [4] = "Занза може створити стародавні чари тролів з правильними компонентами.\n\nПерший — це первісний ідол Гаккарі, який треба взяти у наймогутніших лейтенантів Гаккарі: Джин'до та Мандокіра, повелителя крові.\n\nДругий — це проколота лялька вуду. Їх можна знайти в купах сміття, якими завалене це мерзотне місце. Поглянь в купах зачарованих худу.\n\nПринеси мені їх, і я створю для тебе потужні чари!", [5] = "Використовуй їх з розумом, {клас:к}. Не щади Гаккарі!", ["en"] = "Falcon's Call", ["tasks"] = { ["Primal Hakkari Idol"] = "первісний ідол Гаккарі", ["Primal Hakkari Idol (Provided)"] = "первісний ідол Гаккарі (видано)", ["Punctured Voodoo Doll"] = "проколота лялька вуду", ["Punctured Voodoo Doll (Provided)"] = "проколота лялька вуду (видано)" } },
    [81870] = { [1] = "Місія Фералас XIV: перемогти Алондриуса", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів у Подвійних Колосалах. Переможіть там хранителя гаю Алондрія та поверніться до мене.", [3] = "Переможіть Алондріуса під час вторгнення Кошмарів Фералас, патрулюючи дорогу біля Подвійних Колосалів, та поверніться до польового капітана Аруннела.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission XIV: Defeat Alondrius" },
    [81871] = { [1] = "Місія Фералас XV: перемогти Слірену", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів у Руїни Рейвенвінда. Переможіть там гарпію-«королеву» Слірену та поверніться до мене.", [3] = "Переможіть Слірену під час вторгнення Кошмарів Фералас біля зиккурату в Руїнах Рейвенвінда та поверніться до польового капітана Аруннела.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission XV: Defeat Slirena" },
    [81872] = { [1] = "Місія Фералас XVI: Врятуйте Мелліаса, землянку", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів в Онейрос. Знайдіть там сплячого Друїда Кігтя Мелліаса Землеборця та супроводьте його у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Мелліаса Землянина від вторгнення Кошмарів Фералас біля сходів біля озера Джадемір в Онейросі та поверніться до польового капітана Аруннела.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission XVI: Rescue Mellias Earthtender" },
    [81873] = { [1] = "Місія Фералас XVII: Врятувати Нерен Бруксінгер", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів у Подвійних Колосалах. Знайдіть там сплячу Друїдку Кігтя Нерену Бруксінгер і супроводьте її у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Нерен Бруксінгер від вторгнення Кошмарів Фералас біля багаття у Подвійних Колосалах та поверніться до польового капітана Аруннела.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission XVII: Rescue Nerene Brooksinger" },
    [81874] = { [1] = "Місія у Фераласі XVIII: Порятунок Джамнісса Дереволіка", [2] = "Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Гілці Снів і вирушайте до Вторгнення Кошмарів у Руїни Рейвенвінда. Знайдіть там сплячого Друїда Кігтя Джемніс, Лікаря Дерев, і супроводьте її у безпечне місце. Потім поверніться до мене.", [3] = "Врятуйте Джемніс Лісоголову від вторгнення Фераласських Кошмарів на північному краю Руїн Рейвенвінда та поверніть його до польового капітана Аруннела.", [5] = "Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?", ["en"] = "Feralas Mission XVIII: Rescue Jamniss Treemender" },
    [81877] = { [1] = "Ніч бою", [2] = "Все готово до грандіозного відкриття Арени Гаджетзан!\n\nПравила прості: у вас буде три бої, кожен з яких завершиться перемогою чемпіона. Між боями буде коротка перерва, але ви не зможете покинути арену в будь-який момент. Якщо ви це зробите, ви програєте.\n\nКоли ви будете готові, бій розпочнеться!", [3] = "Здобути перемогу на Арені Гаджетзана.", [4] = "Як справи, {ім'я}? Тільки не кажи, що тобі досить!", [5] = "Ти справді влаштував там шоу. Я ж на межі сидіння був, кажу тобі! Прибутки теж були не такі вже й погані.\n\nЯк чемпіон, ти отримаєш свою частку, плюс дещо додаткове просто за те, що зробив усе це можливим. Переможцю дістається здобич, як то кажуть.", ["en"] = "Fight Night" },
    [8188] = { [1] = "Палкі обійми вуду", [4] = "Занза може створити стародавні чари тролів з правильними компонентами.\n\nПерший — це первісний ідол Гаккарі, який треба взяти у наймогутніших лейтенантів Гаккарі: Джин'до та Мандокіра, повелителя крові.\n\nДругий — це проколота лялька вуду. Їх можна знайти в купах сміття, якими завалене це мерзотне місце. Поглянь в купах зачарованих худу.\n\nПринеси мені їх, і я створю для тебе потужні чари!", [5] = "Використовуй їх з розумом, {клас:к}. Не щади Гаккарі!", ["en"] = "Vodouisant's Vigilant Embrace", ["tasks"] = { ["Primal Hakkari Idol"] = "первісний ідол Гаккарі", ["Primal Hakkari Idol (Provided)"] = "первісний ідол Гаккарі (видано)", ["Punctured Voodoo Doll"] = "проколота лялька вуду", ["Punctured Voodoo Doll (Provided)"] = "проколота лялька вуду (видано)" } },
    [8189] = { [1] = "Явлення прозріння", [4] = "Занза може створити стародавні чари тролів з правильними компонентами.\n\nПерший — це первісний ідол Гаккарі, який треба взяти у наймогутніших лейтенантів Гаккарі: Джин'до та Мандокіра, повелителя крові.\n\nДругий — це проколота лялька вуду. Їх можна знайти в купах сміття, якими завалене це мерзотне місце. Поглянь в купах зачарованих худу.\n\nПринеси мені їх, і я створю для тебе потужні чари!", [5] = "Використовуй їх з розумом, {клас:к}. Не щади Гаккарі!", ["en"] = "Presence of Sight", ["tasks"] = { ["Primal Hakkari Idol"] = "первісний ідол Гаккарі", ["Primal Hakkari Idol (Provided)"] = "первісний ідол Гаккарі (видано)", ["Punctured Voodoo Doll"] = "проколота лялька вуду", ["Punctured Voodoo Doll (Provided)"] = "проколота лялька вуду (видано)" } },
    [8190] = { [1] = "Чари худу", [4] = "Занза може створити стародавні чари тролів з правильними компонентами.\n\nПерший — це первісний ідол Гаккарі, який треба взяти у наймогутніших лейтенантів Гаккарі: Джин'до та Мандокіра, повелителя крові.\n\nДругий — це проколота лялька вуду. Їх можна знайти в купах сміття, якими завалене це мерзотне місце. Поглянь в купах зачарованих худу.\n\nПринеси мені їх, і я створю для тебе потужні чари!", [5] = "Використовуй їх з розумом, {клас:к}. Не щади Гаккарі!", ["en"] = "Hoodoo Hex", ["tasks"] = { ["Primal Hakkari Idol"] = "первісний ідол Гаккарі", ["Primal Hakkari Idol (Provided)"] = "первісний ідол Гаккарі (видано)", ["Punctured Voodoo Doll"] = "проколота лялька вуду", ["Punctured Voodoo Doll (Provided)"] = "проколота лялька вуду (видано)" } },
    [81900] = { [1] = "Палаючий Звір", [2] = "Різьблена фігурка перед вами зображує двоголового звіра, що виходить з Темного Порталу. З його пащі вивергається вогонь Скверни. Під зображенням на табличці написано: «Калефактус Визволений».\n\nІнтуїція підказує вам, що культисти Сутінків можуть мати плани використати руйнівну силу цієї істоти для власних цілей.\n\nВи міркуєте, що наступним кроком у вашому полюванні є шлях до Вивержених Земель. Хтось там може знати більше про цього пекельного звіра.", [3] = "Знайдіть експерта з тварин Вибухнутих Земель.", [5] = "Розкажи мені більше про цього звіра, {раса}. Наші інтереси можуть збігатися.", ["en"] = "The Burning Beast" },
    [8191] = { [1] = "Віщунська аура", [4] = "Занза може створити стародавні чари тролів з правильними компонентами.\n\nПерший — це первісний ідол Гаккарі, який треба взяти у наймогутніших лейтенантів Гаккарі: Джин'до та Мандокіра, повелителя крові.\n\nДругий — це проколота лялька вуду. Їх можна знайти в купах сміття, якими завалене це мерзотне місце. Поглянь в купах зачарованих худу.\n\nПринеси мені їх, і я створю для тебе потужні чари!", [5] = "Використовуй їх з розумом, {клас:к}. Не щади Гаккарі!", ["en"] = "Prophetic Aura", ["tasks"] = { ["Primal Hakkari Idol"] = "первісний ідол Гаккарі", ["Primal Hakkari Idol (Provided)"] = "первісний ідол Гаккарі (видано)", ["Punctured Voodoo Doll"] = "проколота лялька вуду", ["Punctured Voodoo Doll (Provided)"] = "проколота лялька вуду (видано)" } },
    [81917] = { [1] = "Ланцюги, що зв'язують", [2] = "Я багато разів бачив цю істоту, яку ви називаєте \"Калефактус\", під час своїх польових досліджень. За всіма даними, це майже невразливий гончий ядро, створений з енергії Скверни.\n\nОднак, якщо те, що ви кажете, правда, і Молот Сутінків планував поневолити його, то, можливо, є спосіб підкорити звіра.\n\nТіньоприсягнуті, що на південному сході, відомі тим, що виконують темні ритуали, включаючи поневолення істот Скверни. Можливо, члени їхнього ордену мають ключ до послаблення Калефактуса?", [3] = "Принесіть 5 ланок інфернального ланцюга магові крові Ліннору у Вивержених землях.", [4] = "Ви знайшли інструмент для послаблення Калефактуса, {раса}?", [5] = "Цікаво... так, я можу з цим працювати.", ["en"] = "Chains That Bind" },
    [81919] = { [1] = "Доведений до п'яти", [2] = "Я створив інструмент з ланок ланцюга, які ви знайшли. Ті, хто має вашу професію, могли б назвати його своєрідним «ласо».\n\nЕнергія всередині цього ланцюга найкраще підходить для зв'язування демонів, але враховуючи, що Калефактус може бути з-за темного порталу, я підозрюю, що вона подіє і на нього.\n\nЯкщо ви його знищите, принесіть мені зразок його крові скверни. Така аномальна істота заслуговує на подальше вивчення.\n\nПоточне місцезнаходження Калефактуса серед цих пусток невідоме, але я сподіваюся, що ви його знайдете, {клас}.", [3] = "Принесіть кров скверни Калефактуса Визволеного Кровомагу Ліннору у Вивержених Землях", [4] = "Знайди швидко того основного пса, {ім'я}. Перш ніж Молот Сутінків знайде його першим.", [5] = "Такий вишуканий зразок! Хто знає, які таємниці криються в сутності звіра з-за порталу?\n\nНа знак подяки, можете залишити собі ласо. Сумніваюся, що мені колись знадобиться така річ.", ["en"] = "Brought to Heel", ["tasks"] = { ["Infernal Lasso"] = "Пекельне ласо" } },
    [8192] = { [1] = "Ласка аніміста", [4] = "Занза може створити стародавні чари тролів з правильними компонентами.\n\nПерший — це первісний ідол Гаккарі, який треба взяти у наймогутніших лейтенантів Гаккарі: Джин'до та Мандокіра, повелителя крові.\n\nДругий — це проколота лялька вуду. Їх можна знайти в купах сміття, якими завалене це мерзотне місце. Поглянь в купах зачарованих худу.\n\nПринеси мені їх, і я створю для тебе потужні чари!", [5] = "Використовуй їх з розумом, {клас:к}. Не щади Гаккарі!", ["en"] = "Animist's Caress", ["tasks"] = { ["Primal Hakkari Idol"] = "первісний ідол Гаккарі", ["Primal Hakkari Idol (Provided)"] = "первісний ідол Гаккарі (видано)", ["Punctured Voodoo Doll"] = "проколота лялька вуду", ["Punctured Voodoo Doll (Provided)"] = "проколота лялька вуду (видано)" } },
    [81924] = { [1] = "Мудрість Хранителів", [2] = "Які б знання Калдорей ви не шукали, їх не знайдете серед цих руїн, {клас}. Більше ні.\n\nОднак, поки фізичне лежить у руїнах, духовне залишається.\n\nШукайте духів-охоронців Азшари, Тирових земель та Фералас. Ви впізнаєте їх за їхніми святилищами. Доведіть свою гідність перед ними та слухайте їхніх слів. Їхня мудрість буде передана вам, щоб вона не була втрачена часом, як це було тут.", [3] = "Доведіть свою спроможність перед духами-охоронцями Фераласа, Азшари та Внутрішніх земель, а потім поверніться до Тирісія у Фералас.", [4] = "Чи духи передали вам свою мудрість?", [5] = "Ви виявилися відданим учнем, {ім'я}. Робота зі збереження давніх знань часто буває важкою, але ви чудово впоралися з цим обов'язком.\n\nУ цьому світі є ще багато таємниць, які вам належить розкрити. Сподіваюся, ці інструменти допоможуть вам у цій подорожі.", ["en"] = "Wisdom of the Guardians" },
    [8193] = { [1] = "Рибалка-майстер", [4] = "Сьогодні між 14:00 та 16:00 ми проведемо змагання, щоб визначити найкращого рибалку! Просто будь {стать:ПЕРШИМ:ПЕРШОЮ}, хто принесе мені 40 смачнориб, спійманих вздовж узбережжя Тернистої долини й отримаєш звання рибалки-майстра!\n\nЯкщо ж не встигнеш принести мені 40 рибин, ти зможеш отримати грошову винагороду у моєї помічниці за кожні 5 смачнориб.\n\nО, і раджу не зволікати, смачнориба швидко псується!", [5] = "Поквапся, якщо хочеш заслужити звання рибалки-майстра! Я стирчу тут вже кілька годин без їжі! Давай сюди смачнорибу!", ["en"] = "Master Angler", ["tasks"] = { ["Speckled Tastyfish"] = "плямиста смачнориба", ["Speckled Tastyfish (Provided)"] = "плямиста смачнориба (видано)" } },
    [8194] = { [1] = "Рибалка-учень", [4] = "Попри те, що у нас вже є переможець змагань, я все одно куплю у тебе смачнорибу за розумною ціною. Що скажеш?", [5] = "Це взаємовигідна угода!", ["en"] = "Apprentice Angler", ["tasks"] = { ["Speckled Tastyfish"] = "плямиста смачнориба", ["Speckled Tastyfish (Provided)"] = "плямиста смачнориба (видано)" } },
    [81947] = { [1] = "Сангвінічне чаклунство", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Sanguine Sorcery", ["tasks"] = { ["Sanguine Sorcery"] = "Сангвінічне чаклунство" } },
    [81949] = { [1] = "Легенди про мудреців припливів", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Legends of the Tidesages", ["tasks"] = { ["Legends of the Tidesages"] = "Легенди про мудреців припливів" } },
    [8195] = { [1] = "Монети Зуліан, Раззаші та Гаккарі", [4] = "Я шукаю знаки влади, відомі як монети племен. Це валюта, якою користуються різні племена Зул'Ґуруба, і кожна з них наповнена непомітною, але потужною магією.\n\nІснує дев'ять видів таких монет. Якщо у тебе будуть зайві — я готовий обміняти три монети на знак пошани. Ці знаки ти зможеш використати у Рін'вошо-Торговця — він пропонує нашим героям особливі предмети в обмін на них.", [5] = "Чудово — ці монети чудово доповнять нашу колекцію... яку ми використаємо для захисту племені від бога крові. Ти {стать:заслужив:заслужила} цей знак пошани, {ім'я}, разом з подякою нашого племені!", ["en"] = "Zulian, Razzashi, and Hakkari Coins", ["tasks"] = { ["Hakkari Coin"] = "монета Гаккарі", ["Hakkari Coin (Provided)"] = "монета Гаккарі (видано)", ["Razzashi Coin"] = "монета Раззаші", ["Razzashi Coin (Provided)"] = "монета Раззаші (видано)", ["Zulian Coin"] = "монета Зуліан", ["Zulian Coin (Provided)"] = "монета Зуліан (видано)" } },
    [81951] = { [1] = "Лімінальний та Арканний", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "The Liminal and the Arcane", ["tasks"] = { ["The Liminal and the Arcane"] = "Лімінальний та Арканний" } },
    [81952] = { [1] = "Повсякденний етикет", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Everyday Etiquette", ["tasks"] = { ["Everyday Etiquette"] = "Повсякденний етикет" } },
    [81953] = { [1] = "Дизайн з каменю", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Stonewrought Design", ["tasks"] = { ["Stonewrought Design"] = "Дизайн з каменю" } },
    [81954] = { [1] = "Отруйні подорожі", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Venomous Journeys", ["tasks"] = { ["Venomous Journeys"] = "Отруйні подорожі" } },
    [81955] = { [1] = "Металевий розум", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "A Mind of Metal", ["tasks"] = { ["A Mind of Metal"] = "Металевий розум" } },
    [81956] = { [1] = "Кодекс фокусника", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Conjurer's Codex", ["tasks"] = { ["Conjurer's Codex"] = "Кодекс фокусника" } },
    [8196] = { [1] = "Сутні манго", [4] = "Надзвичайно потужні сутні манго ростуть на багатьох островах Південних морів. Одне таке манго освіжає того, хто його з'їсть, як фізично, так і духовно. Якщо ти ніколи не {стать:куштував:куштувала} манго, то ти багато чого {стать:втратив:втратила}!\n\nУ нас є достатні запаси манго, і ми охоче обміняємо їх на знак пошани Зандаларів. Якщо ти не знаєш, де дістати знаки — поговори з Вінчаксою.", [5] = "Це чесний обмін, {стать:мій друже:моя подруго} — прошу, насолоджуйся соковитими плодами Південного моря з благословенням племені.", ["en"] = "Essence Mangoes", ["tasks"] = { ["9000 reputation with Zandalar Tribe"] = "9000 репутації у племені Зандалар", ["Zandalar Honor Token"] = "знак пошани Зандаларів", ["Zandalar Honor Token (Provided)"] = "знак пошани Зандаларів (видано)" } },
    [81967] = { [1] = "Потойбічне скарб", ["en"] = "Otherworldly Treasure" },
    [81974] = { [1] = "Більше сміття для Зірі", [2] = "Ви знайшли ще один процесор G-7 C.O.R.E. Цей пристрій виглядає у гіршому стані, ніж попередній, і з нього витікає дуже їдка чорнильно-чорна рідина. Ймовірно, зараз це вже мотлох, але Зірі може знайти для нього застосування.", [3] = "Поговоріть із Зірі «Гайковим ключем» Літтлшпрокетом у Гномреґані.", [4] = "Що це у тебе там є, {ім'я}?", [5] = "Ого! Процесор G-7 C.O.R.E. Не думаю, що я коли-небудь бачив такий наживо. Мабуть, тобі варто просто викинути його. Я чув, що вони справді небезпечні.", ["en"] = "More Junk for Ziri", ["tasks"] = { ["Item #220526"] = "Товар №220526" } },
    [81975] = { [1] = "Тривожний обмін", [2] = "Зачекай, що? Ти вдарився головою? Навіщо мені просити тебе принести одну з цих штук, щоб допомогти полагодити це відро з болтами? Все, що потрібно було Утилізатор, це кілька картриджних запобіжників, міфрилові стійки та шматочки чарівної есенції. Якби я встановив у цю штуку повноцінний блок G-7... ну, я не знаю, що б сталося. Нічого хорошого, це точно. Вибухи, вогонь, міжвимірні монстри. Найімовірніше, справжнє шоу жахів.", [3] = "Поговоріть із Зірі.", [5] = "Уяви собі, подумати, що я спробую помістити підрозділ G-7 у Утилізатор! У мене немає бажання померти, друже.\n\n<Зірі сміється сама собі та повертається до роботи>", ["en"] = "A Troubling Exchange" },
    [81977] = { [1] = "ДНТ", [2] = "Ви знаходите маленький гладенький фіолетовий камінь. Він має багато нерівних граней, найбільша з яких, здається, містить каламутне мінеральне утворення, яке, як ви помічаєте, мерехтить і злегка кружляє у світлі. Однак, чим більше ви зосереджуєтеся на цьому русі, тим більше відчуваєте наростаюче відчуття неспокою.\n\nВи вже збираєтеся викинути його, коли вас охоплює раптове відчуття, майже бажання поки що залишити його при собі.", ["en"] = "DNT", ["tasks"] = { ["Item #220531"] = "Товар №220531" } },
    [81979] = { [1] = "ДНТ", [2] = "Значна частина цього світу перебуває під загрозою неминучого знищення. Я знаю, це звучить дуже драматично, але зупинити це не повинно бути проблемою для такої винахідливої людини, як ти. Зустрінемося на протилежному боці мосту, що веде до Серадана, у північній частині Внутрішніх земель. Ми поговоримо там більше.", ["en"] = "DNT" },
    [81980] = { [1] = "ДНТ", [2] = "Позаду мене ви знайдете досить великий портал, що веде до Смарагдового Сну. На жаль, зараз це скоріше \"нічний кошмар\" з іншого боку, і це для мене зараз недоступно. Ніби прояву кошмару було недостатньо, там щось є, кошмарна суміш жахливих снів та пророчих видінь загибелі.\n\nТож, звісно, мені потрібно, щоб ви зайшли туди та знайшли для мене його лігво. Оцініть цю істоту, щоб ми могли вирішити, що робити далі.", ["en"] = "DNT" },
    [81982] = { [1] = "ДНТ", [2] = "Та темрява, в яку ти потрапив... саме там вона й мешкає. Як ти, безсумнівно, здогадався, твій розум, не кажучи вже про твій плотський смертний м'ясний костюм, не може витримати аури жаху, що оточує цього монстра. На щастя, моя неперевершена передбачливість і здатність розвивати позитивні робочі стосунки з широким колом талановитих людей означають, що в мене є рішення, яке дозволить тобі підійти достатньо близько до цього звіра, щоб убити його.", ["en"] = "DNT" },
    [81983] = { [1] = "ДНТ", [2] = "Зачекай, що? Тіньова жінка? Пристрій на порожнечі? Про що ти говориш?", ["en"] = "DNT" },
    [81986] = { [1] = "Пробудження кошмару", [2] = "Тепер, коли у вас є гаджет Зірі, у вас має бути все необхідне, щоб протистояти Об'єднанню Кошмарів. Зберіть якомога більше союзників і поверніться в Кошмар через портал Тіні Гілки в Ясенедолі. Знайдіть і знищіть Об'єднання Кошмарів у його лігві.\n\nО, і ще одне... звір володіє певним предметом, який мене дуже цікавить. Принесіть мені все, що знайдете на його трупі, і ви будете щедро винагороджені.", [3] = "Знищте Об'єднання Кошмарів та принесіть Тіньовій Фігурі будь-яку знайдену здобич.", [4] = "Як проходить полювання?", [5] = "Фантастична робота, {ім'я}. А тепер ваша винагорода!\n\nБачите, все, що мені було потрібно, це маленький фрагмент мрії, захований під цією мантією, але оболонка — це скарб сам по собі, і ця частина ваша. Я думаю, ви виявите, що вона має певні унікальні властивості, і якщо у вас є відповідні навички, поговоріть зі мною ще раз, і я впевнений, що зможу допомогти вам зрозуміти, як правильно її використовувати.", ["en"] = "Waking the Nightmare" },
    [81987] = { [1] = "Рішення для гоблінів", [2] = "Гей, ти, йди сюди, дай мені на тебе подивитися. Так, я так і думав, я можу впізнати послідовника мистецтва гоблінів за милю. Плями від сажі на кісточках пальців, у нас усіх є. Слухай, мені потрібна допомога.\n\nМені доручили консультувати моїх товаришів-гоблінів, щоб дати їм тут перевагу. Але ці гноми також запросили експерта і поступово починають просуватися вперед. У мене є кілька ідей, але тим часом, скажімо, ти принесеш мені кілька гоблінських мін! Ти ж можеш їх зробити, га?", [3] = "Принесіть 5 гоблінських мін Максиміліану «Бріольцю» в Мерехтливій квартирі", [4] = "Як мама завжди казала: «Якщо не можеш виграти чесний бій, то не бийся чесним бієм». Тож ми вирішимо цю проблему, як це робили мої предки. Накриємо це місце високочутливими вибуховими пристроями!", [5] = "Подумати тільки, що їх використовували для захисту гори Гіджал від Палаючого Легіону. Це здається таким же гарним варіантом використання.", ["en"] = "Goblin Solutions" },
    [82] = { [1] = "Дослідження Отруйного кубла", [2] = "Добре, тепер щодо цих повідомлень про комах... Ми знаємо, що вони осушують водойми в Отруйному кублі. А НЕ ЗНАЄМО ми... все інше!\n\nДавай спочатку з'ясуємо, з чим ми маємо справу! Я хочу, щоб ти {стать:вирушив:вирушила} в Отруйне кубло і {стать:зібрав:зібрала} зразки тамтешніх комах. Збери п'ять частин тіл комах Сентіпаар та принеси їх алхіміку Товкачеру, щоб він міг їх дослідити. З його допомогою ми точно з'ясуємо, з чим ми маємо справу!", [3] = "Принесіть п'ять частин тіл комах Сентіпаар з Отруйного кубла алхіміку Товкачеру в Пристроблях.", [4] = "Ти {стать:молодший землемір:молодша землемірка} {ім'я}, так? Швидше, у нас тут жахлива ситуація! Ти {стать:приніс:принесла} частини тіл комах, про які казав Шипохідник?!", [5] = "Гарна робота, я розпочну дослідження цих частин прямо зараз! Але я можу тобі відразу сказати... таких комах я ще не бачив. Таке враження, ніби ними керує якась зовнішня сила.\n\nТобі потрібно негайно поговорити з Шипохідником. Ситуація виникла серйозна, і ти маєш допомогти нам вирішити її якомога швидше! Я не впевнений, але, скоріш за все це знову пов'язано з цими комахами в пустелі Танаріс!", ["en"] = "Noxious Lair Investigation", ["tasks"] = { ["Centipaar Insect Parts"] = "частини тіл комах Сентіпаар", ["Centipaar Insect Parts (Provided)"] = "частини тіл комах Сентіпаар (видано)" } },
    [820] = { [1] = "<UNUSED>", [2] = "Воістину, у твоєму тілі живе дух сили, а може, це була просто удача, так?\n\nОсь на що покладаються молоді в наші дні: на удачу... і на щедрість тих, хто сильніший за них. Небагато хто знаходить час, щоб знайти свій власний шлях. Це завжди благання про допомогу... завжди винагорода, а ніколи пошуки. Я впевнений, що ти будеш таким самим.\n\nАле є надія. Мені потрібна ще одна річ для мого зілля, {ім'я}: 8 трав мерехтливого рілля. Їх можна знайти в Громовому Хребті на північний захід від Рейзор-Гілл.", ["en"] = "<UNUSED>" },
    [82001] = { [1] = "Вимагати гномських проблем", [2] = "Гаразд, погані новини. Цей гномський консультант, якого вони знайшли, на крок попереду мене. Виявляється, їхній гонщик навіть не буде на землі!\n\nВони вистилають гоночну трасу цією штукою під назвою «магніти», і вони плануватимуть трохи вище землі, а це означає, що вибуху не буде! Якщо вони не наступлять на міну, то ми просто підемо та принесемо їм міну!\n\nЯ думаю, що якщо у нас буде достатньо великий електричний заряд, це має вирішити нашу проблему. Іди на південний захід Ун'горо та принеси мені ріг стегодона Громового Тупоту!", [3] = "Принесіть ріг стегодона Громового Тупота Максиміліану \"Бриолетнику\".", [4] = "Я не буду вдаватися в подробиці про те, як працюють магніти, бо, чесно кажучи, не думаю, що хтось знає.", [5] = "Так, це має стати в нагоді! Ідеальний природний канал, який нам потрібен! Стружка від цього стане ідеальним спусковим гачком для вибуху мін.", ["en"] = "Require Gnomish Problems" },
    [82002] = { [1] = "Що таке червоний колір і як пахне фарба?", [2] = "Ці нові міни працюють чудово, але ми не можемо просто грати в диверсантів. Нам потрібно буде кілька покращень наших власних атракціонів, щоб вони не визнавали це нечесною грою.\n\nТож нам потрібно зробити найочевидніше покращення – гарне фарбування. І вам навіть не потрібно питати, який колір ми використовуємо! Червоний, як у Хотрода! Найшвидший колір!\n\nХто знає, у кого ідеальний червоний відтінок? Ці джаброні з Червоного Хрестового Походу. Чому б тобі не пробратися в Долину Гарт і не знайти мені трохи того гарного червоного барвника.", [3] = "Вирушайте до Хартглена та знайдіть коробку з червоною фарбою.", [4] = "Це має бути червоний колір, як у Багряного Хрестового Походу. Не криваво-червоний, не червоний, як у вогняної кулі, не червоний, як у демонічних Орків. Червоний, як у Багряного Хрестового Походу, або ж просто красень!", [5] = "Вишуканий відтінок, ідеальний градієнт червоного. Навіть натяку на рожевий чи помаранчевий. Тільки чиста червона насолода. О так, я вже відчуваю, як ми рухаємося швидше, друже.", ["en"] = "Whats Red and Smells like Paint?" },
    [82003] = { [1] = "Коло перемоги для гоблінів!", [2] = "Ха! Я зробив це! Е-е, тобто... ми зробили це!\n\nТой консультант-аматор-гном здається! Він платить нам, щоб ми втекли з міста! Чому б тобі не зробити цю честь, га? Ти це заслужив, хлопче.", [3] = "Поговоріть з Фіззбізз Міднокрут щодо отримання виплати.", [5] = "У мене є пропозиція, яка, я вважаю, буде в інтересах нас обох.", ["en"] = "Victory Lap For the Goblins!" },
    [82004] = { [1] = "Тиші гроші", [2] = "Я не можу дозволити собі втрати репутації чи фінансових збитків, які ви та ваш друг-гоблін мені завдаєте. Тож ось у чому угода: я дам тобі інсайдерську інформацію про те, як Гномські Інженери працюють. В обмін на це зникни! Я більше не хочу тебе тут бачити!", [3] = "Прийміть хабар від Фіззбізз Міднокрут", [5] = "Це все, що ти отримуєш зараз! Повертайся через тиждень, і в мене буде для тебе ще.", ["en"] = "Hush Money" },
    [82008] = { [1] = "Гномські рішення", [2] = "Вітаю, шановний колего! Одразу видно, що ви інтелектуал найвищого ґатунку. Мені потрібен хтось із вашими навичками. Але спершу найважливіше: вздовж гоночної траси постійно щось вибухає! Підозріло, чи не так? Безпека наших водіїв — понад усе. Принесіть мені кілька гномських поясів запобігання травмам! Сподіваюся, це принаймні тимчасово розв'яже проблему.", [3] = "Принесіть пояси для запобігання пошкодженню гномів Фіззбізз Міднокрут 2", [4] = "У тебе є пояси? Скоро відбудуться перегони, і вони нам потрібні НЕГАЙНО!", [5] = "Дуже добре! Сподіваємося, що наш гонщик добереться до фінішу цілим і неушкодженим. А тепер перейдемо до більш серйозних проблем.", ["en"] = "Gnomish Solutions" },
    [82009] = { [1] = "Вимагати проблем з гоблінами", [2] = "Чуєш вибухи на гоночній трасі? Ні, серйозно, чуєш? У мене майже повністю пропав слух. У будь-якому разі...\n\nМагніти! Ретельно розмістивши магніти вздовж всієї гоночної траси та додавши зворотну полярність до днища нашого транспортного засобу, ми просто будемо ширяти над шахтами! Візьміть собі цих гоблінів!\n\nОстанній елемент пазла — нам потрібно щось, що може утримувати електричний заряд, щоб впоратися зі складною електричною панеллю.\n\nВирушай на південний захід Ун'горо та принеси мені ріг стегодона Громового Тупоту!", [3] = "Принесіть Фіззбізз Міднокрут ріг громотупого стегодона.", [4] = "Ріг стегодона «Громовий тупіт» – ідеальна органічна сполука для керування електричними полями, необхідними для роботи цих магнітів. Принаймні, я на це сподіваюся, бо не зовсім впевнений, як вони працюють.", [5] = "Це чудово підійде! Воно досі сповнене енергії! Якби в мене залишилося хоч якесь волосся, воно б стріляло в усі боки!", ["en"] = "Require Goblin Problems" },
    [8201] = { [1] = "Колекція голів", [2] = "Це правда. Гаккар тепер перебуває у Зул'Ґурубі, купаючись в силі наших богів. Поневолені ним верховні жерці тепер направляють енергію наших найсвященніших божеств в Здирача Душ, який незабаром стане ссильнішим за будь-яку істоту Азерота. Його треба зупинити!\n\nВізьми цю священну мотузку та протягни через неї голови жерців, відповідальних за викрадення сили наших богів.\n\nКоли зробиш це — повертайся до мене.", [3] = "Зберіть 5 голів верховних жерців, а потім принесіть колекцію голів Ґурубаші до Ексжала на острів Йоджамба.", [4] = "Ти {стать:зібрав:зібрала} колекцію голів, {ім'я}? Ми повинні зупинити Гаккара, поки він не отримав більше сили!", [5] = "Ти {стать:здобув:здобула} голови! Ти {стать:зупинив:зупинила} розкрадання сили наших богів і {стать:послабив:послабила} Гаккара!\n\nТвої дії воістину героїчні, {ім'я}. Нехай голови цих тролів благають тебе про милість ще довго після того, як їхня кров охолоне.", ["en"] = "A Collection of Heads", ["tasks"] = { ["Gurubashi Head Collection"] = "колекція голів Ґурубаші", ["Gurubashi Head Collection (Provided)"] = "колекція голів Ґурубаші (видано)" } },
    [82010] = { [1] = "Послаблення конкуренції", [2] = "Час оборони закінчився! Ми не переможемо, якщо не саботуємо змагання! Їхнє паливо! Подивимося. Вогняний цвіт і ром? ЦЕ ЧОМУ ПРОГРАЄ ГНОМСЬКА ВИНАХІДЛИВІСТЬ? НАСИТОМУ АЛКОГОЛЮ?\n\nНам потрібно знайти спосіб саботувати вороже паливо, щоб вони цього не помітили. Є квітка неймовірно червоного кольору, сполуки пелюсток якої нестабільні навіть при найменшому нагріванні.\n\nЧервоний хрестовий похід використовує цю квітку у своїх барвниках. Іди до Долини Підгір'я та знайди мені трохи.", [3] = "Іди до Хартглена та знайди Коробку з червоною фарбою.", [4] = "Тільки «Червоний хрестовий похід» знає про місцезнаходження квітів! Ці сполуки достатньо сильні, щоб їх барвники були достатньо концентрованими.", [5] = "Ви знайшли це! Так, просто підкинути це у ворожий бензобак має викликати справжнє видовище! Вибух? Нічого гіршого! Вони працюватимуть лише з потужністю 76% c! І вони навіть не здогадуватимуться про це!", ["en"] = "Watering Down the Competition" },
    [82011] = { [1] = "Коло перемоги для гномів!", [2] = "Ми зробили це, друже! Гобліни здаються. Насправді, консультант, якого найняли гобліни, хоче поговорити з тобою особисто! Постарайся зараз не випендрюватися, не хотів би ж вони підстрелити сапера!", [3] = "Поговоріть з Максиміліаном \"Масляником\"", [5] = "Я достатньо дорослий, щоб знати, коли я переможений. Або принаймні, коли більше не варто боротися.", ["en"] = "Victory Lap for the Gnomes!" },
    [82013] = { [1] = "Тиші гроші", [2] = "Дозволь мені розповісти тобі, як це все піде. Я більше не можу дозволити тобі бути тут, тому ось що ми зробимо. Ти збираєшся піти просто зараз. Однак в обмін на твою щедру за часом поїздку звідси, ти зможеш повертатися раз на тиждень.\n\nКоли ти це зробиш, ти можеш заскочити сюди і побачити щось на землі, що тобі, можливо, дуже захочеться підібрати. І я був би такий вдячний за цей акт послуги, що не міг не відчути бажання якось тебе винагородити.", [3] = "Прийміть хабар від Максиміліана \"Масляника\"", [5] = "Побачимося наступного тижня, боже.", ["en"] = "Hush Money" },
    [82016] = { [1] = "Міцні напої Атал'ай", [4] = "Я пропоную тобі непогану угоду, друже! Принеси мені чарівність, яку можна знайти лише у народу Атал'ай, і я зроблю тобі пропозицію: силу, яка перевершує твою найсміливішу уяву. Будь обережний, друже, цю силу можна використовувати лише в болотах, де вона знайдена. Кажуть, що Атал'ай практикують заборонене чаклунство, і я можу трохи про них знати.\n\nЗвучить добре? Хочеш обмінятися?", [5] = "Гей, ти не пошкодуєш про цей обмін, друже!", ["en"] = "Atal'ai Potent Potables" },
    [82017] = { [1] = "Поєднання кошмарів", [2] = "Жахлива аура, яку ти відчув, виходить не з якогось місця, а від істоти. Особливо смертоносна істота темряви, спотворене тіньове відображення найгірших аспектів нашого світу, що злилося в суміш чистого кошмару. Я не можу пояснити, звідки я це знаю, але мені... це наснилося. А точніше, це було показано мені. Це важко пояснити. Будь ласка, йди до Місячної Галявини та поговори з друїдом Логанааром. Можливо, ще є час зупинити її, перш ніж вона стане ще потужнішою.", [3] = "Шукайте Логанаара в Місячній поляні", [4] = "Так, {клас}?", [5] = "Це найжахливіша новина. Якщо це так, як сказала Ханнала, то нинішня криза уві сні ось-ось стане набагато гіршою.", ["en"] = "An Amalagamation of Nightmares" },
    [82018] = { [1] = "Ітарій", [2] = "Ви знайомі з Храмом Атал'Хаккара? Він має багату історію, яку я не буду тут переповідати, але зараз він перебуває під опікою сонця могутніх зелених драконів. Головним охоронцем храму є великий дракон на ім'я Еранікус, і він відомий своєю особливою налаштованістю на сон. Я сподіваюся, що він зможе нам допомогти. Вирушайте до Болота Скорботи та зустріньтесь там із рейнджером, відомим як Ітаріус. Можливо, він знає, як зв'язатися з Еранікусом, щоб попросити його про допомогу.", [3] = "Знайдіть Ітаріуса десь у Болоті Скорботи.", [4] = "Вітання, {раса}.", [5] = "Ти прийшов шукати Еранікуса? Твій прихід, можливо, невчасний, {клас}. Боюся, щось не так у Храмі Атал'Хаккара. Ходімо, поговоримо далі.", ["en"] = "Itharius" },
    [82019] = { [1] = "Занурення", [2] = "У свій час так званий Затонулий Храм був домівкою для секти тролів, присвячених воскресінню свого давнього кривавого божества, Хаккара, Пожирача Душ. Перш ніж Атал'ай встигли реалізувати свої похмурі амбіції, гнів Ізери перетворив храм на болото, і вона залишила дракона Еранікуса та його військо його охоронцями. Останнім часом я чув багато чуток про те, що тролі знову активні там, і боюся, що могло статися з драконами.\n\nБудь ласка, зайдіть всередину храму та подивіться, що ви можете дізнатися.", [3] = "Дізнайтеся більше про те, що відбувається в Храмі Атал'Хаккара.", [4] = "Які новини ти приніс про Еранікуса?", [5] = "Сцена, яку ви описали, дуже жахлива. Це набагато гірше, ніж я боявся. Я можу лише сподіватися, що деякі дракони там ще живі та їх можна буде зібрати на ноги.", ["en"] = "Going Under" },
    [82020] = { [1] = "Повернення до Мунґлейд", [2] = "Повернися до Логанаара та повідом йому про те, що ми дізналися. Я спробую сам розвідати храм, сподіваючись зв'язатися з драконами або хоча б зібрати більше інформації.", [3] = "Поверніться до Логанаара в Місячній поляні.", [5] = "<Логанар важко зітхає>\n\nЩе погані новини. Добре, дякую тобі за те, що ти ризикнув своїм життям, щоб увійти до храму та дізнатися, що ти накоїв, і за те, що ти доніс мені звістку. Я маю повідомити інших друїдів, щоб ми могли вирішити, що робити далі.\n\nДякую тобі поки що. Можливо, я знову звернуся до тебе в майбутньому.", ["en"] = "Return to Moonglade" },
    [82021] = { [1] = "Випадковий поворот подій", [2] = "Що ж, привіт, {ім'я}! Я просто стояв тут, милуючись краєвидами, і не міг не почути твою скрутну ситуацію. На щастя, я думаю, що можу надати саме те, що тобі потрібно, щоб допомогти тобі з твоєю маленькою проблемою \"злого пожираючого монстра-кошмару\".", [3] = "Послухайте, що каже Тіньова Постать.", [4] = "Мушу сказати, що все склалося б якнайкраще, якби я все спланував. Здається, доля тобі посміхається, друже.\n\n<У тебе чітко складається враження, що тіньова постать перед тобою самодостатньо посміхається>", [5] = "Хіба не приємно мати поруч когось на кшталт мене, хто має саме те, що тобі потрібно, саме тоді, коли тобі це потрібно?", ["en"] = "A Fortuitous Turn of Events" },
    [82022] = { [1] = "Погані новини...", [2] = "Отже, гарна новина полягає в тому, що рішення існує. Погана новина полягає в тому, що отримання того, що потрібно для переживання жаху, вимагатиме певних зусиль. Я знаю, як прикро, що так важко отримати хорошу допомогу в наші дні. Якби цей шукач пригод зумів зробити одну просту річ, про яку я його попросив, ви б зараз насолоджувалися гарячою їжею та холодним пивом десь у готелі, нічого про це не підозрюючи.", [3] = "Знайдіть шукача пригод, якого описала Тіньова Постава, та поверніть Браслети з Порожнечею.", [4] = "Як проходять пошуки?", [5] = "А, схоже, що вони знесилені. Прикро, але це легко виправити. Щоб їх перезарядити, вам потрібно знайти густе скупчення чарівників-нага та масово їх знищити. Рідко вони можуть носити щось під назвою «Ядро Порожнечі», тому переберіть тіла, принесіть мені одне і... Ха! Жартую! Якби ви могли бачити вираз вашого обличчя...\n\nДайте мені хвилинку, і я зможу наповнити їх силою... і ось ми тут! Ви готові вбити Кошмар.", ["en"] = "The Bad News..." },
    [82023] = { [1] = "Загублені наручі", [2] = "Бачите, я лицар з деяким визнанням, і нещодавно я взявся за те, щоб позбавити землю особливо жахливого зла, яке оселилося на сусідньому острові на сході. Коли я знайшов цю мерзенну істоту, розпочалася справді епічна битва. Ми, мабуть, билися годинами, поки нарешті я не відправив звіра у повний відступ, безсумнівно, він побіг і піддався ранам. Я ледве зміг повернутися до міста, перш ніж знепритомнів. Наручі, мабуть, злетіли з моєї руки під час битви.", [3] = "Знайдіть лігво \"Звіра\", про якого говорив поранений гном, і поверніть Браслети з Порожнечею.", [4] = "<Молодий мурлок дивиться на тебе та видає милий булькаючий звук.>\n\nТи помічаєш, що поруч із мурлоком є невелика купка землі. Можливо, якась нора. Можливо, тобі варто перевірити її на наявність наручів?", [5] = "Ви знайшли маленьку нору, що належить чарівному та, здавалося б, доброзичливому молодому мурлоку. Напевно, це не та істота, про яку говорив гном?\n\n<Крихітний мурлок видає тихий булькаючий звук і починає відригувати пару покритих слизом наручів до ваших ніг>", ["en"] = "The Lost Vambraces" },
    [82043] = { [1] = "Дикі боги", [2] = "Щось не так з лоа з Гіджалу. Наймогутніші духи природи спостерігають за горою тисячі років, але вони починають зникати, один за одним.\n\nАгамагган, найвеличніший з давніх лоа, помер давно. Але тролі Амані мають способи розмовляти з мертвими. Знайдіть вуду, яке вони використовують, і віднесіть його до Остроголового. Поговоріть з Агамагганом і запитайте його, що відбувається з його родичами.", [3] = "Зберіть Напій Дикого Шепіту у Джінта'алора у Внутрішніх Землях, а потім використовуйте його на вершині Остролистих Пагорбів, щоб поговорити з Духом Агамаггана.", [5] = "Навіть за завісою смерті я відчував тінь, що падає на Хіджал та моїх родичів.\n\nВізьми це, смертний. Воно тобі знадобиться в майбутньому.", ["en"] = "The Wild Gods" },
    [82044] = { [1] = "Дикі боги", [2] = "Темрява вкоренилася в Смарагдовому Сні, і вона огортає стародавніх духів Хіджалу сум'ям і страхом.\n\nЗнайди цих маревних духів, смертний, і використай мій рев, щоб залучити їх до бою.\n\nКоли ти вб'єш їхні зіпсовані форми, їхні духи очищаться, і вони відродяться заново.", [3] = "Доставте Дикі Підношення Посланцю Тіньового Зуба у Фехтвуді. Використайте Рев Агамаггана на Мареному Древньому та переможіть його, щоб отримати Дикі Підношення.", [4] = "Я відчуваю зміни на горі, {ім'я}. Що ти мені несеш?", [5] = "Ти зробиш де лоа велику послугу, {ім'я}. Я використаю твої пожертви, щоб провести їх назад до Хіджалу.\n\nПринеси мені ще пожертв, і я, можливо, розлучуся з деякими скарбами мого клану.", ["en"] = "The Wild Gods" },
    [82055] = { [1] = "Колода «Дюни Молодика»", [2] = "Тепер, коли ви зібрали всі карти Дюни в колоду, таємничим чином з'являється дев'ята карта з такою ж рубрикою, як і перші вісім. На цій карті написано: «Поверніть ці карти на Ярмарок Молодика та отримайте винагороду». Ви чули, що цей ярмарок по черзі зупиняється в Мулгорі та Голдширі кожні кілька тижнів, тому вам доведеться почекати, поки вони тут з'являться наступного разу.", [3] = "Поверніть колоду Дюн на Ярмарок Молодика, коли вона прибуде до міста.", [4] = "Бачу, що вам вдалося завершити колоду з дюн! Вітаю!", [5] = "Отже, ви зібрали колоду Дюн. Ваш жест повернення її нам створить зв'язок між вами та Темнолунням, який нескоро буде забутий. Дозвольте мені подарувати вам одну з найбільших карт Темнолуння як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Dunes Deck", ["tasks"] = { ["Dunes Deck"] = "Палуба Дюн" } },
    [82056] = { [1] = "Колода Кошмарів Новолуння", [2] = "Тепер, коли ви зібрали всі карти Кошмару в колоду, таємничим чином з'являється дев'ята карта з такою ж рубрикою, як і перші вісім. На цій карті написано: «Поверніть ці карти на Ярмарок Молодика та отримайте винагороду». Ви чули, що цей ярмарок по черзі зупиняється в Мулгорі та Голдширі кожні кілька тижнів, тому вам доведеться почекати, поки вони тут з'являться наступного разу.", [3] = "Поверніть колоду Кошмарів на Ярмарок Молодика, коли він прийде до міста.", [4] = "Бачу, що тобі вдалося зібрати колоду кошмарів! Вітаю!", [5] = "Отже, ви зібрали колоду Кошмарів. Ваш жест повернення її нам створить зв'язок між вами та Темнолунням, який нескоро буде забутий. Дозвольте мені подарувати вам одну з найбільших карт Темнолуння як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Nightmares Deck", ["tasks"] = { ["Nightmares Deck"] = "Колода кошмарів" } },
    [82057] = { [1] = "Колода Чуми Новомісяччя", [2] = "Тепер, коли ви зібрали всі карти Чуми в колоду, таємничим чином з'являється дев'ята карта з такою ж рубрикою, як і перші вісім. На цій карті написано: «Поверніть ці карти на Ярмарок Молодика та отримайте винагороду». Ви чули, що цей ярмарок по черзі зупиняється в Мулгорі та Золотоширі кожні кілька тижнів, тому вам доведеться почекати, поки вони тут з'являться наступного разу.", [3] = "Поверніть колоду Чуми на Ярмарок Молодика, коли вона прийде до міста.", [4] = "Бачу, що тобі вдалося зібрати колоду пошестей! Вітаю!", [5] = "Отже, ви зібрали колоду Чум. Ваш жест повернення її нам створить зв'язок між вами та Темнолунням, який нескоро буде забутий. Дозвольте мені подарувати вам одну з найбільших карт Темнолуння як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Plagues Deck", ["tasks"] = { ["Plagues Deck"] = "Колода «Чума»" } },
    [82058] = { [1] = "Колода «Диких земель Новомісяччя»", [2] = "Тепер, коли ви зібрали всі Дикі карти в колоду, таємничим чином з'являється дев'ята карта з такою ж підкладкою, як і перші вісім. На цій карті написано: «Поверніть ці карти на Ярмарок Молодика та отримайте винагороду». Ви чули, що цей ярмарок по черзі зупиняється в Мулгорі та Голдширі кожні кілька тижнів, тому вам доведеться почекати, поки вони тут з'являться наступного разу.", [3] = "Поверніть колоду дикої природи на Ярмарок Молодика, коли вона прийде до міста.", [4] = "Бачу, що тобі вдалося зібрати колоду диких символів! Вітаю!", [5] = "Отже, ви зібрали колоду Диких Карт. Ваш жест повернення її нам створить зв'язок між вами та Темномісяцем, який нескоро буде забутий. Дозвольте мені подарувати вам одну з найбільших карт Темномісяця як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Wilds Deck" },
    [82062] = { [1] = "Назавжди після", [2] = "Ми мусили бути впевнені, що можемо тобі довіряти. Таких друзів важко знайти.\n\nВ Азероті зростає зло, третя фракція. І Орда, і Альянс мимоволі працюють над досягненням власних цілей. Уповільнення їхнього просування та формування інформаційних мереж – це все, для чого ми маємо ресурси.\n\nВізьми це, підніми собі настрій і повернися до кращих днів. Незабаром настане час, коли нам знадобляться наші посилені сили для демонстрації сили.", [5] = "<Вам вручають невеликий пакунок, зверху якого акуратно складена сорочка.>", ["en"] = "Ever After" },
    [82068] = { [1] = "Боріться з вторгненнями кошмарів", [2] = "Виконайте місію «Кошмарне вторгнення» у Фераласі або Гінтерленді сьогодні та отримаєте додаткову нагороду.", [3] = "Виконайте місію «Вторгнення Кошмарів» у Фераласі або Внутрішніх землях, а потім доповідіть польовому капітану Корліану або польовому капітану Аруннелу.", [4] = "Ви вже виконали місію?", [5] = "Молодець, {ім'я}!", ["en"] = "Fight the Nightmare Incursions" },
    [82084] = { [1] = "Урок грамотності", [4] = "Твій прогрес у таємних мистецтвах був зразковим, {ім'я}. Гадаю, ти готовий створити власну книгу заклинань.\n\nПодивимося... перо Совиних Звірів з Внутрішніх Земель та чорнило, отримане з силітідної смоли... так, цього буде достатньо. А для сторінок — найкращий папірус Фарракі!", [5] = "Ваша книга заклинань готова, {ім'я}. Нехай ваші сторінки будуть наповнені таємницями, які зможуть зрівнятися з давніми бібліотеками Елун'дріса та Зулдазара.", ["en"] = "A Lesson in Literacy" },
    [82086] = { [1] = "Урок грамотності", ["en"] = "A Lesson in Literacy" },
    [82089] = { [1] = "Майстер трансмутації", [2] = "Трансмутація — це унікальна навичка, до якої мають доступ усі талановиті алхіміки, але лише ті, хто найбільше відданий цьому мистецтву, можуть навчитися справді стати майстрами. Можливо, у вас є все необхідне, але вам потрібно буде довести мені свою щирість, щоб піти цим шляхом до глибших знань і розуміння.\n\nПринесіть мені три злитки арканіту як знак вашої відданості цьому мистецтву.", [3] = "Принесіть Краймеон Лезолаб три злитки арканіту", [4] = "Невже три мізерні злитки арканіту — ніщо в порівнянні з цими знаннями?", [5] = "Дуже добре, я бачу твою відданість.\n\n<Краймон поспішно запихає бруски в рюкзак>\n\nТак? О, трансмутація. Звичайно. Тримайся нерухомо, мені потрібна вся моя концентрація для цього.\n\n<Краймон драматично махає руками, і з його правого вказівного пальця вилітає крихітна іскра>\n\nНу, е-е, так. Мабуть, цього достатньо.", ["en"] = "Master of Transmutation" },
    [82090] = { [1] = "Міксологія для розваги та прибутку", [2] = "Будь-який алхімік, який поважає себе, скаже вам, що мистецтво полягає в максимізації прибутку. Йдеться про те, щоб дешево добувати матеріали, виготовляти їх оптом і продавати за неймовірні гроші. Що, якби я сказав вам, що є спосіб зробити так, щоб ваші матеріали йшли набагато, набагато далі? Що ж, як самопроголошений «Майстер міксології», я маю саме те, що вам потрібно, якщо ви хочете підвищити рівень своєї гри в еліксири та зілля. Принесіть мені 10 зілля невидимості, 10 еліксирів знищення демонів і 5 еліксирів мудреців, і я покажу вам, як це зробити.", [3] = "Принесіть Міксмайстру Бліксу 10 зілля невидимості, 10 еліксиру знищення демонів та 5 еліксиру мудреців.", [4] = "Слухай, у мене багато потенційних студентів, які чекають, щоб повчитися у мене. У тебе є те, що я просив? Якщо ні, то йди геть.", [5] = "Ого, ти справді це приніс? Ну гаразд тоді. Давай приготуємо твою локшину і зробимо з тебе справжнього міксолога.", ["en"] = "Mixology For Fun and Profit" },
    [82093] = { [1] = "Дуріан у джунглях", [4] = "Цей насичений та гострий фрукт підніме вам настрій, поки ви будете мандрувати через Болото Скорботи та досліджувати Храм Атал'Хаккара. Нехай цей запах не обманює вас, друже, це цінний фрукт мого народу!\n\nЯкщо ви принесете мені щось привабливе зі своїх пригод, я зроблю це вартим ваших зусиль, друже. В'язку нашого найкращого дуріана за ваші клопоти! Може, укладемо угоду?", [5] = "Таз'дінго! Насолоджуйтесь смачним, солодким дуріаном, але пам'ятайте, понеділок... повернення коштів не здійснюється.", ["en"] = "Jungle Durian" },
    [82094] = { [1] = "Печатки Загубленого Храму", [4] = "Для наймогутнішого шукача пригод я пропоную найпотужніші обміни. У мене є дещо, що посилює ваші наплечники, сила від самих Атал'ай! {ім'я}, якщо у вас є магія, знайдена найсильнішим з Атал'ай у храмі, я зроблю це вартим ваших зусиль.\n\nНе поспішаймо, я пропоную найсправедливіші угоди...", [5] = "Іди вже, друже. Якщо тобі потрібно ще цих товарів, ти знаєш, де мене знайти, {ім'я}!", ["en"] = "Signets of the Lost Temple" },
    [82095] = { [1] = "Бог Гаккар", [2] = "Тепер час захопити сутність аватара Хаккара.\n\nВіднесіть яйце Хаккара до Святилища Павшего Бога в Затонулому Храмі в Азероті. Закликайте силу яйця, щоб розбудити мертвого бога.\n\nБудьте обережні, навіть у цій новонародженій формі він володітиме неймовірною силою і чинитиме опір вам кожною краплею своєї люті.\n\nПереможете його та помістіть його сутність у яйце Хаккара.", [3] = "Принесіть начинене яйце Хаккара до Єх'кінії в Танарісі.\n\nНаданий предмет:", [4] = "Ти переміг аватара Хаккара, {ім'я}? Чи його сутність вже підсилила яйце, яке я тобі дав?", [5] = "Суть Хаккара зібрано! Навіть зараз Яйце ворушиться життям! Чи можуть міфи про Хаккара бути правдою?\n\nЦе не повинно бути правдою, бо саме тоді я боюся того, що може зробити Хаккар, якщо народиться знову. Я збережу це яйце в безпеці та переконаюся, що воно не потрапить у злі руки.\n\nТвоя праця зі мною закінчена, {ім'я}. Ти торкнувся легенди, і твої дії можуть одного дня змінити обличчя нашого світу.", ["en"] = "The God Hakkar", ["tasks"] = { ["Egg of Hakkar"] = "яйце Гаккара" } },
    [82096] = { [1] = "В глибинах", [2] = "Усередині храму я знайшов круглу кімнату з шістьма балконами, кожен з яких мав статую змії на краю. Зацікавлений, я штовхнув один з них, щоб побачити, що станеться, і це виявилася пасткою! Я мало не впав на смерть від вибуху. Лежачи на виступі, я подивився вниз і помітив, що біля основи кімнати була ще одна статуя; щось на зразок вівтаря... Хаккар, здається, так його називали.\n\nЯ думаю, що цей вівтар і є таємницею -- ти повинен принести цей жетон до вівтаря в Затонулому Храмі.", [3] = "Знайдіть Вівтар Хаккара у Затонулому Храмі на Болоті Скорботи.", [4] = "Оглянувши статую, ви помічаєте заглиблення на її боці, розміром з жетон, який вам дав Марвон...", [5] = "Ви вставляєте кам'яне коло в отвір і чуєте, як воно замикається.\n\nТепер, коли камінь на місці, ви можете продовжувати... але що робити далі?\n\nМожливо, вам варто детальніше дослідити цей вівтар...", ["en"] = "Into the Depths", ["tasks"] = { ["Atal'ai Stone Circle"] = "круглий камінь Атал'ай" } },
    [82097] = { [1] = "Таємниця кола", [2] = "Мої спогади туманні, але я розповім тобі, що можу. Коло статуй у Затонулому Храмі, хоча й небезпечне, я вірю, що вони зберігають таємницю, яка відкриває ще більший скарб.\n\nЗ головного вівтаря мені вдалося активувати серію вогнів. Я думаю, що якщо ти зможеш розкрити значення цих вогнів, то зможеш розкрити будь-які таємниці, що приховані в цій кімнаті.\n\nОднак попереджаю тебе, {ім'я}. Велике зло лежить у храмі. Цілком ймовірно, що все цінне буде ретельно охоронятися...", [3] = "Подорожуйте до Затонулого храму та відкрийте таємницю, приховану в колі статуй.", [5] = "Око ідола яскраво блищить на вершині купи руїн. Його прозорість показує щось блискуче позаду нього. Ви зрушуєте кілька великих шматків уламків і вам вдається витягнути те, що лежить під ними.\n\nСкарб Атал'ай тепер ваш.", ["en"] = "Secret of the Circle" },
    [82102] = { [1] = "Сутність Ераніка", [2] = "Коли ви торкаєтеся самоцвіту, глибокий голос резонує у вашій свідомості.\n\n«Смертний, почуй це благання. Я Еранікус із Зеленого Драконячого Року, хранитель цього проклятого храму. Моє доручення забезпечити, щоб тролі більше ніколи не повертали свою гидоту бога, поки що закінчилося невдачею. Коли я наповнюю цей самоцвіт частиною своєї сутності, я відчуваю, як моя хватка над Сном перетворюється на хаос. Будь ласка, помістіть цей самоцвіт у джерело сутності в моєму лігві, і нехай наша магія очистить мою психіку від скверни, щоб я міг відпочити».", [3] = "Помістіть Сутність Еранікуса в Купелю Сутності, розташовану в цьому лігві в Затонулому Храмі.", [4] = "Коли ти наближаєшся до джерела сутності, про яке тобі розповідав Еранікус, його голос знову торкається твого розуму.\n\n«Так, смертний, це джерело сутності викупить той незаплямований елемент моєї психіки, що залишився в цьому самоцвіті. Помістіть самоцвіт всередину джерела, і дозвольте магії Зеленого Драконячого Польоту очистити мою істоту від зіпсованості та скверни. Тільки тоді я знайду справжнє звільнення, і тільки тоді Драконячий Політ зможе відновити своє керівництво над Атал'ай».", [5] = "Ви поміщаєте камінь всередину шрифту сутності.\n\n«Дякую тобі, смертний, що ти... ні... цього не може бути! Ні! Зіпсуття цього проклятого бога навіть оскверняє святість шрифту сутності Зеленого Дракона! Ні, будь ласка, я відчуваю, як моя сутність виривається з мене! БІЛЬ! Я відчуваю, як мене охоплює вічний кошмар...»\n\n«Смертний, благаю тебе! Знайди одного з Зеленого Дракона, щоб зупинити це... допоможи мені... Я закутий у темряву... навіки в агонії... будь ласка, не катуйте...»", ["en"] = "The Essence of Eranikus", ["tasks"] = { ["Item #221475"] = "Товар №221475" } },
    [82104] = { [1] = "Джаммал'ан-Пророк", [2] = "Мої супутники з Візербарків не люблять чужинців у своєму домі.\n\nА я? У мене більше немає дому. Мене вигнали з мого народу, великого племені Атал'ай з Болота Скорботи.\n\nУ нашого духовного лідера, Джаммал'ана, було те, що він назвав пророцтвом. Він вірить, що виклик бога Хаккара принесе Атал'ай безсмертя.\n\nАле я закликав до обережності. Що, якби пророцтво було не більше ніж маніпуляцією?\n\nЯ хочу помститися за своє вигнання. Принесіть мені голову Джаммал'ана. Можливо, тоді мій народ буде вільним.", [3] = "Вигнанець Атал'ай у Внутрішніх Землях хоче отримати Голову Джаммал'ана.", [4] = "Як тільки Джаммалаана буде усунено, у мене є шанс повернутися до свого народу.\n\nЗ Джаммаланом як їхнім духовним лідером, Атал'аї зіткнуться з неминучою загибеллю.", [5] = "Безрозсудна довіра Джаммалана до хибних видінь привела мій народ до вічної загибелі.\n\nЯ дякую тобі, {клас}, за помсту за моє вигнання. Я сумую за своїм народом. Мені немає дому, куди повернутися.", ["en"] = "Jammal'an the Prophet" },
    [82107] = { [1] = "Пір'я вуду", [2] = "Ваша честь принесла мені трохи спокою. Це єдине справедливе рішення, що я пропоную вам щось натомість.\n\nМоя зброя та обладунки були чудовими за життя, але зараз вони мені не потрібні. Вони були б кориснішими у вашому розпорядженні.\n\nВирушайте до затонулого храму та знищіть тролів-охоронців Гашера, Міджана, Золо, Хукку, Зул'лора та Лоро. Вони носять магічне пір'я, яке може перетворювати моє фізичне тіло на достатній час, щоб ви отримали винагороду.", [3] = "Принесіть Пір'я Вуду від тролів у Затонулому Храмі Полеглому Герою Орди.", [4] = "Ти так швидко повернувся? Час для мене вже не той, можливо, це справді була для тебе довга подорож...", [5] = "Нарешті я знову відчуваю холодний дотик сталі, хоча б на мить.", ["en"] = "Voodoo Feathers" },
    [82108] = { [1] = "Зелений дракон", [2] = "А тепер я відправляю тебе на небезпечне полювання, щоб ти вбив зеленого дракона Морфаза та приніс мені його зуб. Морфаз мешкає глибоко в Храмі Атал'Хаккара, вхід до якого знаходиться в Болоті Скорбот.\n\nЯкщо ти хочеш перемогти його, ти не повинен йти сам. Цей дракон — ворог багатьох — шукай інших, хто хоче його знищити.\n\nЗуб дракона символізує силу, яку мисливець знайде в компанії інших. Принеси його мені, і ти багато чого навчишся.", [3] = "Принесіть Зуб Морфаза Огтінку в Азшарі. Огтінк мешкає на вершинах скель на північний схід від Руїн Елдарату.", [4] = "Я бачу мудрість у твоїх очах, {ім'я}. Твоє полювання закінчилося?", [5] = "Ти вивчив старі методи, {ім'я}, і за це я пропоную тобі подарунок з моїх днів як {клас}.", ["en"] = "The Green Drake" },
    [82110] = { [1] = "Лазурний ключ", [2] = "Знадобиться деякий час, щоб розшифрувати фрагменти та зняти чари. Коли я закінчу, я особисто передам сумку лорду Рейвенгольдту.\n\nЗалишилося ще питання ключа, який, як кажуть, зберігає зелений дракон, відомий як Морфаз. Дракон оселився глибоко в Храмі Атал'Хаккара, вхід до якого знаходиться в Болоті Скорботи.\n\nЗберіть своїх друзів і вирушайте до його лігва. Лорд Рейвенгольдт чекатиме на ваше повернення з ключем.", [3] = "Поверніть Лазурний ключ лорду Джораху Рейвенгольдту.", [4] = "Сумка вже прибула від Архімага Ксилема, ти знайшов ключ?", [5] = "Ключ! Я думав, що він втрачений назавжди. Будь ласка, візьміть зачарований одяг з моїх крамниць — вони призначені для шахраїв з винятковою майстерністю та відданістю. Слід знати, що з {ім'я} не можна жартувати!", ["en"] = "The Azure Key" },
    [82111] = { [1] = "Кров Морфаза", [2] = "Тепер остання частина, другі ліки.\n\nЗелений дракон Морфаз відомий своєю стійкістю до всіх форм отрути та хвороб — багато друїдів загинули, щоб донести нам цю інформацію. Немає сумнівів, що його кров має велику силу для наших потреб.\n\nКур'єр з Кола Кенаріона забере частини, які ви вже зібрали, поки ви збиратимете останні. Покличте своїх союзників і знайдіть лігво дракона в затонулому храмі Атал'Хаккара. Принесіть його кров Греті Мохшуф у Фехтвуд.", [3] = "Убийте Морфаза у затонулому храмі Атал'Хаккара та поверніть його кров Греті Моххоф у Фехтвуді. Вхід до затонулого храму можна знайти у Болоті Скорботи.", [4] = "У тебе є кров Морфаза?", [5] = "Ти вбив Морфаза і приніс нам його кров... Мені важко повірити в цю добру новину!\n\nМи негайно змішаємо інгредієнти та почнемо зцілювати дерева та істот Фелдвуду. Знадобиться ціле життя, щоб скасувати те, що тут сталося, але ти дав нам засоби для цього.", ["en"] = "Blood of Morphaz" },
    [82112] = { [1] = "Кращий інгредієнт", [2] = "Як я й боявся — токсин просто занадто слабкий для такої могутньої істоти.\n\nЯкщо ми хочемо створити токсин достатньої сили, ти повинен спуститися на дно Храму Атал'Хаккара, розкрити таємниці вівтаря та забрати гнилу лозу у охоронця. Храм небезпечний, і тобі варто було б привести друзів.\n\nПовернися до мене, коли це буде зроблено.", [3] = "Заберіть Гнилу Лозу у охоронця на дні Затонулого Храму та поверніться до Слідопита Торви.", [4] = "Ви відновили виноградну лозу?", [5] = "Нарешті, токсин може бути створений повністю. Я не смію вимагати від вас знову застосовувати його до істоти, оскільки я вже забагато просив.\n\nДякую вам і маю повагу. Хай вам щастить у ваших подорожах, {ім'я}.", ["en"] = "A Better Ingredient" },
    [82114] = { [1] = "Знищити Морфаза", [2] = "Глибоко в затонулому храмі Атал'Хаккара живе зелений дракон на ім'я Морфаз.\n\nРоки тому він здійснив зухвалу засідку, влаштувавши мені халепу та поглинувши мого учня. Хоча втрата учня мені відома, саме цей ніс таємничий осколок неперевершеного розміру та якості.\n\nТи повинен зібрати могутніх союзників та заглибитися в храм. Знищити Морфаза та дістати таємничий осколок з його вічного шлунка.", [3] = "Заберіть Арканний Осколок у Морфаза та поверніть його до Архімага Ксилема.", [4] = "Ти вбив мого давнього ворога?", [5] = "Неймовірно. Осколок виріс, поглинаючи енергію дракона протягом довгих років.\n\nЯ більше нічого не можу від тебе просити. Моя повна здатність кувати аркан повернулася з цим осколком. Моє перше творіння твоє, {ім'я}, і тобі залишається лише вибрати...", ["en"] = "Destroy Morphaz" },
    [82115] = { [1] = "Тролі пера", [2] = "Мій улюбленець майже готовий. Тепер мені просто потрібно чимось його набити.\n\nПідійдуть лише пір'я вуду від тролів із затонулого храму. Їх звуть Гашер, Міджан, Золо, Хукку, Зул'лор та Лоро. Вбийте їх. Вбийте їх усіх.\n\nЦе нелегке завдання, {ім'я}, тому я зроблю його вартим ваших зусиль, давши вам щось від Нібі — йому це, мабуть, і не потрібно.", [3] = "Принесіть загалом 6 пір'я Вуду від тролів у затонулому храмі.", [4] = "Ти приніс пір'я? Цю ляльку треба набити!", [5] = "Чудово, тепер мій улюбленець готовий!\n\n<Імпсі швидко набиває ляльку та демонічно обіймає її.>\n\nО, який дивний побічний ефект мають ці вуду-пір'я...", ["en"] = "Trolls of a Feather" },
    [82208] = { [1] = "Великий друг бібліотеки", [5] = "Завдяки вашим пожертвам бібліотека процвітає.\n\nБудь ласка, візьміть це.", ["en"] = "Greater Friend of the Library" },
    [82209] = { [1] = "Винагорода за бурдюки з водою", [4] = "Знову повернувся, {ім'я}? Якщо у тебе є ще п'ять мішечків з водою з Пустелебродів, то в мене є пакет з твоїм ім'ям!", [5] = "Чудово — чим більше мішків з водою ми зможемо повернути, тим далі ми всі будемо від катастрофи! Продовжуйте, і я обов'язково винагороджу вас за кожні п'ять мішків з водою, які ви мені принесете.", ["en"] = "Water Pouch Bounty" },
    [8221] = { [1] = "Рідкісна риба — риба-ангел Кіфера", [4] = "*ЖЖЖ* *Клац*\n\nЯ розшукую рідкісну рибу за дорученням рибалки Синьожаброго. Якщо ви принесете мені рибу-ангела Кіфера, то отримаєте цю чудову винагороду.\n\n*Клац* *ЖЖЖ*", [5] = "*ЖЖЖ*\n\nІдентифікація риби-ангела Кіфера завершена.\n\nВи можете отримати винагороду.\n\n*Клац-клац* *Бзззз*", ["en"] = "Rare Fish - Keefer's Angelfish", ["tasks"] = { ["Keefer's Angelfish"] = "риба-ангел Кіфера", ["Keefer's Angelfish (Provided)"] = "риба-ангел Кіфера (видано)" } },
    [8222] = { [1] = "Сяюча кров скорпіда", [4] = "За весь час роботи на ярмарку я дізнався багато нового про клієнтів. Ось одна з таких мудростей: покупці люблять речі, які світяться! Неважливо, що це — ти можеш взяти зламану ніжку стільця і зробити так, щоб вона світилася, і кожна дитина прийде за версту, щоб отримати таку!\n\nОтже, {ім'я}, мені потрібна сяюча кров скорпіда. Ти можеш знайти її у скорпідів Силітуса, або Спустошених земель, або Палаючих степів.", [5] = "Чудова робота, {ім'я}! Дуже дякую! З цієї крові я зроблю фарбу і перетворю всілякий дешевий мотлох на скарб, що сяє!\n\nОсь твої купони, і ще раз дякую!", ["en"] = "Glowing Scorpid Blood", ["tasks"] = { ["Glowing Scorpid Blood"] = "сяюча кров скорпіда", ["Glowing Scorpid Blood (Provided)"] = "сяюча кров скорпіда (видано)" } },
    [8223] = { [1] = "Більше сяючої крові скорпіда", [4] = "Ця кров скорпіда чудово працює, {ім'я}! Дивовижно, як трохи блиску і сяйва можуть створити цінну дрібничку з мотлоху. Меценати люблять ці речі, а любов — це те, заради чого все це робиться, чи не так...\n\nТи мені дуже {стать:допоміг:допомогла}, {ім'я}, і хоча я не маю великої потреби в сяючій крові скорпіда, якщо ти принесеш мені ще — я обміняю її на кілька купонів.", [5] = "Ще раз спасибі, {ім'я}. Ось твої купони!", ["en"] = "More Glowing Scorpid Blood", ["tasks"] = { ["Glowing Scorpid Blood"] = "сяюча кров скорпіда", ["Glowing Scorpid Blood (Provided)"] = "сяюча кров скорпіда (видано)" } },
    [8224] = { [1] = "Рідкісна риба — дезійська ставрида", [4] = "*ЖЖЖ* *Клац*\n\nЯ розшукую рідкісну рибу за дорученням рибалки Синьожаброго. Якщо ви принесете мені дезійську ставриду, то отримаєте цю чудову винагороду.\n\n*Клац* *ЖЖЖ*", [5] = "*ЖЖЖ*\n\nІдентифікація дезійської ставриди завершена.\n\nВи можете отримати винагороду.\n\n*Клац-клац* *Бзззз*", ["en"] = "Rare Fish - Dezian Queenfish", ["tasks"] = { ["Dezian Queenfish"] = "дезійська ставрида", ["Dezian Queenfish (Provided)"] = "дезійська ставрида (видано)" } },
    [8225] = { [1] = "Рідкісна риба — синій смугастик Браунелла", [4] = "*ЖЖЖ* *Клац*\n\nЯ розшукую рідкісну рибу за дорученням рибалки Синьожаброго. Якщо ви принесете мені синього смугастика Браунелла, то отримаєте цю чудову винагороду.\n\n*Клац* *ЖЖЖ*", [5] = "*ЖЖЖ*\n\nІдентифікація смугастика Браунелла завершена.\n\nВи можете отримати винагороду.\n\n*Клац-клац* *Бзззз*", ["en"] = "Rare Fish - Brownell's Blue Striped Racer", ["tasks"] = { ["Brownell's Blue Striped Racer"] = "синій смугастик Браунелла", ["Brownell's Blue Striped Racer (Provided)"] = "синій смугастик Браунелла (видано)" } },
    [8227] = { [1] = "Вимірювальна стрічка Нета", [2] = "Серед розтрощених рибальських приманок і снастей лежить згорнута шовкова мірна стрічка. До стрічки прикріплена етикетка з написом:\n\n\"Нет Пеґл, Бруднолипка трясовина\".", [3] = "Поверніть вимірювальну стрічку Нету Пеґлу в Бруднолипку трясовину.", [4] = "Привіт, {стать:хлопче:дівчино}. Ти тут, щоб порибалити?", [5] = "Ти {стать:знайшов:знайшла} мою улюблену вимірювальну стрічку! Це моя улюблена! Я виміряв нею найбільшу рибу, яку коли-небудь зловив...\n\nАле я загубив її в Зул'Ґурубі... Ти {стать:був:була} у Зул'Ґурубі? {стать:Бачив:Бачила} легендарного Ґаз'ранку?\n\nНу... хочеш його зловити?", ["en"] = "Nat's Measuring Tape", ["tasks"] = { ["Nat's Measuring Tape"] = "вимірювальна стрічка Нета", ["Nat's Measuring Tape (Provided)"] = "вимірювальна стрічка Нета (видано)" } },
    [82271] = { [1] = "Більше сяючої крові скорпіда", [4] = "Ця кров скорпіда чудово працює, {ім'я}! Дивовижно, як трохи блиску та сяйва може створити цінну дрібничку з будь-якого мотлоху. Відвідувачам подобається ця річ, і головне — це любов, чи не так...\n\nТи дуже мені допоміг, {ім'я}, і хоча мені не дуже потрібна ще сяюча кров скорпіда, якщо ти принесеш мені більше, я все одно обміняю тобі кілька квитків.", [5] = "Ще раз дякую, {ім'я}. Ось ваші квитки!", ["en"] = "More Glowing Scorpid Blood" },
    [82272] = { [1] = "Сяюча кров скорпіда", [4] = "За весь час роботи на Ярмарку я багато чого навчився про клієнтів. Ось один із цих важливих моментів: клієнти люблять речі, що світяться! Неважливо, що це — ви можете взяти зламану ніжку стільця та зробити так, щоб вона світилася, і кожна дитина приїде з багатьох кілометрів навколо, щоб отримати таку!\n\nОтже, {ім'я}, мені потрібна світна кров скорпіда. Ви можете знайти її у скорпідів Сіллітуса, або Вибухнутих Земель, або Палаючих Степів.", [5] = "Чудова робота, {ім'я}! Щиро дякую! Я збираюся зробити фарбу з цієї крові та перетворити всіляке дешеве барахло на сяючі скарби!\n\nОсь ваші квитки, і ще раз дякую!", ["en"] = "Glowing Scorpid Blood" },
    [82273] = { [1] = "Більше очей кажанів", [4] = "{ім'я}, атракціон, який я проєктую, стане найстрашнішою подією з часів захоплення Гномреґану! І це значною мірою завдяки тобі та всім дрібничкам, які ти мені приніс. Велике-велике спасибі!\n\nМені більше багато не потрібно, але... якщо ти принесеш мені більше злих кажанячих очей зі Східних Чумних Земель... у мене може бути більше квитків на Ярмарок Новомісяччя для тебе.", [5] = "Ще раз дякую, {ім'я}. Ось ваші квитки!", ["en"] = "More Bat Eyes" },
    [82274] = { [1] = "Очі злих кажанів", [4] = "Чи траплялося вам коли-небудь блукати печерою пізно вночі в пошуках пригод? Так? Справді? Ну, тоді ви бачили моторошні очі кажанів, що дивляться на вас з висоти, чекаючи, поки ви ослабите пильність, щоб вони могли висмоктати вашу кров!\n\nСтрашна думка, чи не так? Звичайно! Безсумнівно, очі кажана страшні!\n\nПринесете мені кілька злих очей кажана, {ім'я}? Вони мені потрібні для... чогось, що я розробляю. Щось страшне.\n\nВи можете отримати їх від кажанів Східних Чумних Земель.", [5] = "Чудово! У тебе є очі! Сподіваюся, полювання на цих кажанів було для тебе страшним, бо якщо воно налякало такого хороброго {клас}, як ти, то ці очі точно налякають відвідувачів нашого ярмарку.\n\nВізьми ці квитки, {ім'я}, і дякую за твою послугу.", ["en"] = "Evil Bat Eyes" },
    [82275] = { [1] = "Велика чорна булава", [4] = "За мій виступ найсильнішої жінки на світі, я планую приймати предмети від глядачів і розбивати їх великою чорною булавою!\n\nЧи можеш ти зробити мені велику чорну булаву, {ім'я}?", [5] = "О, чудово! Ця булава має велику, важку головку. Б'юся об заклад, я можу розбити нею майже все. Сподіваюся, що не розіб'ю її разом з тим, об що я її вдарю!\n\nОсь ваші квитки, {ім'я}. Бажаю вам гарного перебування на ярмарку!", ["en"] = "Big Black Mace" },
    [82276] = { [1] = "Ритуали сили", [4] = "{ім'я}, у своєму прагненні стати найсильнішою жінкою на світі, я подорожувала світом і дізнавалася секрети нарощування м'язів від далеких майстрів ваг, гуру сили та стародавніх посібників. Тепер я знаю заборонені вправи, які вбивають слабких і калічать непосвячених!\n\nЦі подвиги сили та фізичної підготовки вимагають тренувань з найщільнішим шліфувальним камінням. {ім'я}, чи можеш ти знайти або зробити шліфувальне каміння та принести його мені? Я дам тобі квитки, якщо ти це зробиш...", [5] = "Дякую, {ім'я}. Я використаю це каміння в ритуалі зміцнення, який я вивчив зі стародавньої таблички в найглибших джунглях Тернистої Долини.\n\nКажуть, що та, хто правильно виконає цей священний обряд, матиме силу та витривалість десяти Тауренів!", ["en"] = "Rituals of Strength" },
    [82277] = { [1] = "Більше масивних шліфувальних каменів", [4] = "{ім'я}, дякую тобі за всю допомогу, яку ти мені надав. Я справді не можу тобі достатньо подякувати!\n\nХоча моя потреба вже не така велика... якщо ти принесеш мені більше щільних шліфувальних каменів, у мене все одно збереться для тебе більше квитків на Ярмарок Новомісяччя.", [5] = "Ще раз дякую {ім'я}. Будь ласка, насолоджуйтесь цими квитками та розкажіть своїм друзям про Ярмарок Молодика!", ["en"] = "More Dense Grinding Stones" },
    [82278] = { [1] = "Більше торієвих пристроїв", [4] = "{ім'я}, ти був такий добрий до нас, приносив мені товари без втоми. За це тобі моя вічна подяка!\n\nХоча наша потреба у віджетах Торію вже не така велика, як була, ти все одно можеш принести їх мені, і я з радістю обміняю їх на квитки на Ярмарок Новомісяччя.", [5] = "Ось вам, {ім'я}. Ось квитки на Ярмарок Новомісяця для вашої насолоди. Не витрачайте їх, як то кажуть, усі в одному місці!", ["en"] = "More Thorium Widgets" },
    [82279] = { [1] = "Торієвий пристрій", [4] = "Єбб Небблгір, як і я, працює над майбутнім атракціоном. Цей атракціон настільки дивовижний, каже Небб, що він привабить людей з усього світу... і зробить нас усіх дуже-дуже багатими!\n\nВін каже, що йому потрібні торієві віджети для його будівництва, і хоче, щоб я їх для нього зібрав. То що ти скажеш, {ім'я}? Чи знаєш ти, де можна взяти торієві віджети? Якщо ти інженер, чи можеш ти їх зробити? Чи хочеш обміняти їх на квитки на ярмарок Новомісяччя?", [5] = "А, дякую, {ім'я}! Єббу сподобаються ці віджети. Я не знаю, що він для них запланував, але Єбб — розумний маленький гном. Він розумний і, можливо, трохи хитрий...\n\nЯкби йому тільки подобався смак людиноподібної плоті... з нього вийшов би чудовий троль!\n\nОсь, {ім'я}. Угода є угода, і ці квитки ваші.", ["en"] = "Thorium Widget" },
    [82280] = { [1] = "Механічний ремкомплект", [4] = "Найбільша причина, чому я не можу відкрити свій стенд, полягає в тому, що... все зламано! Мені потрібні комплекти для механічного ремонту, щоб полагодити все це!\n\nЧи можеш ти принести мені ці комплекти, {ім'я}? Я обміняю тобі... комплекти на квитки на ярмарок Новомісяця. Що ти скажеш?", [5] = "Дякую! Тепер я можу взятися за ремонт.\n\nЗнадобиться багато ремонтних комплектів і багато пізніх ночей, щоб все запрацювало. Іноді я думаю, що було б краще повернутися до коріння та перезапустити свою кар'єру хедхантера, але... ярмарок був до мене добрим.\n\nВізьміть ці квитки, {ім'я}, і розважайтеся!", ["en"] = "Mechanical Repair Kits" },
    [82281] = { [1] = "Більше накладок для обладунків", [4] = "{ім'я}, мушу подякувати тобі за всю твою допомогу. У мене є достатньо припасів, завдяки немалим зусиллям з твого боку, але якщо ти хочеш принести мені більше комплектів броні, то я з радістю обміняю їх на квитки на Ярмарок Новомісяччя.", [5] = "Ось так, {ім'я}. Чесна угода. Насолоджуйтесь.", ["en"] = "More Armor Kits" },
    [82282] = { [1] = "Накладки для обладунків", [4] = "Можливо, ви цього не усвідомлюєте, але проведення пересувного карнавалу – це дорого! Все зношується так швидко, що дивно, як ми можемо отримувати прибуток.\n\nЧерез усі ці приховані витрати ми завжди шукаємо способи якомога дешевше обслуговувати наше спорядження. Наприклад, наші намети регулярно рвуться, але я виявив, що комплекти шкіряної броні чудово підходять для латок. Чи можете ви знайти та принести мені кілька комплектів броні? Це заощадить нам купу грошей! Зробіть це, і в мене є для вас жменя квитків на ярмарок Новомісяця...", [5] = "Чудово! Це чудово спрацює! Я щойно помітив дірку в наметі он там, і один із цих комплектів броні саме те, що мені потрібно, щоб її залатати!\n\nЩиро дякую, {ім'я}. Ці комплекти броні заощадять нам купу коштів на ремонті. Ось ваші квитки — ви їх заслуговуєте!", ["en"] = "Armor Kits" },
    [82283] = { [1] = "Хлопчик-кроколіск і бородатий мурлок", [4] = "Єбб працює над іншими атракціонами для свого зоопарку, зокрема над вологими, болотистими оселями для хлопчика, якого виховують кроколіски, і, можливо, для мурлока. Нам знадобляться гарні, водонепроникні легінси, щоб ми не промокли під час встановлення та демонтажу реквізиту. Думаю, для цієї роботи підійдуть легінси з черепашачої луски.\n\n{ім'я}, чи можеш ти зробити ці легінси? Якщо зробиш, то твоєю нагородою буде величезна купа квитків на ярмарок Новомісяця...", [5] = "Чудово, ти їх зробив! Ці чудово підійдуть... Сподіваюся, що не мені доведеться чистити клітку з кроколіском, коли прийде час. Ці звірі можуть бути досить скаженими, чи не так?\n\nОсь твої квитки, {ім'я}. Насолоджуйся ними та насолоджуйся перебуванням на Ярмарку Молодика!", ["en"] = "Crocolisk Boy and the Bearded Murloc" },
    [8230] = { [1] = "Випробувальний квест Колліна", ["en"] = "Collin's Test Quest" },
    [82301] = { [1] = "Потойбічне скарб", ["en"] = "Otherworldly Treasure" },
    [82302] = { [1] = "Потойбічне скарб", ["en"] = "Otherworldly Treasure" },
    [82303] = { [1] = "Потойбічне скарб", ["en"] = "Otherworldly Treasure" },
    [82307] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment" },
    [82308] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment" },
    [82309] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment" },
    [8231] = { [1] = "Хвилеломи", [2] = "Хвилеломи — ендемічні амфібії Азшари. Вони могутні та витривалі.\n\nЇх міцна, блискуча луска зображає майстерність мисливця.\n\nВистеж і вбий хвилеломів на узбережжі Азшари та принеси мені їх луску.", [3] = "Принесіть 6 лусок хвилеломів Оґтінку в Азшару. Огтінк проживає на схилах пагорбів на північний схід від руїн Ельдарата.", [4] = "Як успіхи?", [5] = "Хвилеломів не легко здолати, тим більше в їх рідній стихії.\n\nТи {стать:довів:довела}, що можеш впоратися і з більш смертоносною здобиччю.", ["en"] = "Wavethrashing", ["tasks"] = { ["Wavethrasher Scales"] = "луска хвилешльопа", ["Wavethrasher Scales (Provided)"] = "луска хвилешльопа (видано)" } },
    [82316] = { [1] = "Сім очей я шукаю...", [4] = "Сім прихованих очей я шукаю... приведи їх до мене, і ти теж побачиш.", [5] = "Тебе видно...", ["en"] = "Seven Eyes I Seek..." },
    [8232] = { [1] = "Зелений дракон", [2] = "Тепер ти відправишся на небезпечне полювання на зеленого дракона, Морфаза, і принесеш мені його зуб. Знайдеш ти його глибоко в храмі Атал'Гаккара, що на болоті Скорбот.\n\nЯкщо хочеш перемогти його — не йди {стать:один:одна}. Дракона багато хто хоче вбити, тож ти з легкістю знайдеш союзників.\n\nЗуб дракона буде символізувати могутність мисливця на амулеті. Принеси мені його та отримаєш гідну винагороду.", [3] = "Принесіть Оґтінку з Азшари зуб Морфаза. Огтінк проживає на схилах пагорбів на північний схід від руїн Ельдарата.", [4] = "Я бачу мудрість у твоїх очах, {ім'я:к}. Та {стать:завершив:завершила} полювання?", [5] = "Ти проявив свою відданість традиціям мисливців, {ім'я:к}, і за це прийми цей дарунок, що залишився з тих часів, коли я й сам йшов шляхом мисливця.", ["en"] = "The Green Drake", ["tasks"] = { ["Tooth of Morphaz"] = "зуб Морфаза", ["Tooth of Morphaz (Provided)"] = "зуб Морфаза (видано)" } },
    [82323] = { [1] = "Яскраве пір'я", [4] = "Уява людини – неймовірна річ. Вона може перетворити найменший пагорб на найбільшу гору. Вона може зробити найнешкідливішу тінь жахливим кошмаром!\n\nМи на Ярмарку Молодика дозволяємо уяві наших відвідувачів розквітнути! Але щоб допомогти їм розширити свої горизонти... іноді нам доводиться хитрувати.\n\nМені потрібні яскраві пір'я для однієї з моїх атракціонів. Ви можете отримати їх від птахів з найнебезпечніших районів Азероту. Принесіть мені пір'я, і багато квитків будуть вашими!", [5] = "Ах, ці пір'я! Вони неймовірні, чи не так! Такою красою легко розпалити чиюсь уяву!\n\nВи робите таку благодійну роботу, {ім'я}. Посмішки на обличчях наших відвідувачів, коли вони дивляться шоу, – це справді велика винагорода, але, будь ласка, візьміть і ці квитки.", ["en"] = "Vibrant Plumes" },
    [8233] = { [1] = "Просте прохання", [2] = "Лорд Джорах Рейвехольдт просить твоєї присутності. Справа таємна, я не можу розповісти деталі.\n\nМаєток Рейвенхольдт знаходиться на передгір'ї Гіллзбраду — шукай стежку в горах на північний захід від фортеці Дарнгольд.", [3] = "Поговоріть з лордом Джорахом Рейвехольдтом у маєтку Рейвенхольдт.", [5] = "Вітаю, вітаю, вітаю! Прошу, {ім'я}, сідай, обговоримо одну простеньку справу.\n\nРозумієш, {ім'я}, я, нещодавно втратив дещо дуже цінне, і, відверто прямо, я хочу повернути його за будь-яку ціну. Є дещо і для тебе, не переймайся. Ти отримаєш дещо справді корисне.\n\nЩо скажеш, {ім'я}... ти не проти пригод?", ["en"] = "A Simple Request" },
    [8234] = { [1] = "Запечатана лазурна сумка", [2] = "Почнемо з початку. Я втратив маленьку синю сумку, а в ній були мої особисті речі.\n\nНе намагайся шукати крадіїв, вони вже мертві. Мені відомо лише, що ці дурні не змогли відкрити сумку, тому продали її якомусь деревопузому шаману в Азшарі, як священну реліквію. Розумно.\n\nМені потрібно, щоб ти {стать:відправився:відправилася} до Азшари та {стать:забрав:забрала} її у шамана за допомогою хитрості... чи сили. Певно, перший варіант буде більш доречним. Коли отримаєш сумку, віднеси її архімагу Зілему.", [3] = "Добудьте запечатану лазурну сумку в деревопузого шамана в Азшарі. Потім принесіть сумку архімагу Зілему, який також знаходиться в Азшарі.", [4] = "Я тебе знаю?", [5] = "Я бачу у тебе є сумка лорда Рейвенхольдта. Чому ж ти одразу не {стать:сказав, хлопче:сказала, дівчинко}?", ["en"] = "Sealed Azure Bag", ["tasks"] = { ["Sealed Azure Bag"] = "запечатана лазурна сумка", ["Sealed Azure Bag (Provided)"] = "запечатана лазурна сумка (видано)" } },
    [8235] = { [1] = "Зашифровані фрагменти", [2] = "Лорд Рейвенхольдт попросив нас обох про допомогу. Він хоче зняти чари з цієї сумки.\n\nНа жаль, всі мої книги зі зняття чар нещодавно забрали та знищили дикуни. Рештки цих книжок все ще цінні для мене.\n\nЯкщо ти принесеш мені достатню кількість зашифрованих фрагментів, я зможу зібрати їх докупи. Найкращий шлях отримати фрагменти — вбити лісних слизнів. Вони дуже люблять підбирати все, що погано лежить. Ти знайдеш їх на північному сході Азшари.", [3] = "Принесіть 10 зашифрованих фрагментів архімагу Зілему в Азшару.", [4] = "Ти {стать:знайшов:знайшла} достатньо фрагментів, щоб я зміг продовжити роботу?", [5] = "Схоже, що ти {стать:підібрав:підібрала} одні з кращих фрагментів. Можливо, ти не {стать:такий:така} вже й {стать:безнадійний:безнадійна}.", ["en"] = "Encoded Fragments", ["tasks"] = { ["Encoded Fragment"] = "зашифрований фрагмент", ["Encoded Fragment (Provided)"] = "зашифрований фрагмент (видано)" } },
    [8236] = { [1] = "Лазурний ключ", [2] = "Мені знадобиться трохи часу, щоб розшифрувати ці фрагменти та зняти чари. Коли я закінчу, я особисто віддам сумку лорду Рейвенхольдту.\n\nНам все ще потрібен ключ. Кажуть, його привласнив зелений дракон на ім'я Морфаз. Він оселився в глибині храму Атал'Гаккар, вхід до якого знаходиться на болоті Скорбот.\n\nВізьми своїх друзів та вирушай до його лігва. Лорд Рейвенхольдт чекатиме, поки ти принесеш йому ключ.", [3] = "Поверніть лазурний ключ лорду Джораху Рейвехольдту.", [4] = "Сумка від архімага Зілема вже прибула, ти {стать:знайшов:знайшла} ключ?", [5] = "Ключ! Я вже думав, що він втрачений навіки. Будь ласка, візьми одну з цих зачарованих речей. Вони призначені для пройдисвітів з винятковими здібностями та відданістю. Нехай усі знають, що з тобою не варто жартувати!\n\n<Джорах розкриває сумку, і з неї виривається золоте сяйво. Він зачаровано дивиться всередину...>", ["en"] = "The Azure Key", ["tasks"] = { ["Azure Key"] = "лазурний ключ", ["Azure Key (Provided)"] = "лазурний ключ (видано)" } },
    [8237] = { [1] = "ПОВТОРНЕ ВИКОРИСТАННЯ", ["en"] = "REUSE" },
    [8238] = { [1] = "Монети Ґурубаші, Миршавого Гілля та Зів'ялої Кори", [4] = "Я шукаю знаки влади, відомі як монети племен. Це валюта, якою користуються різні племена Зул'Ґуруба, і кожна з них наповнена непомітною, але потужною магією.\n\nІснує дев'ять видів таких монет. Якщо у тебе будуть зайві — я готовий обміняти три монети на знак пошани. Ці знаки ти зможеш використати у Рін'вошо-Торговця — він пропонує нашим героям особливі предмети в обмін на них.", [5] = "Чудово — ці монети чудово доповнять нашу колекцію... яку ми використаємо для захисту племені від бога крові. Ти {стать:заслужив:заслужила} цей знак пошани, {ім'я}, разом з подякою нашого племені!", ["en"] = "Gurubashi, Vilebranch, and Witherbark Coins", ["tasks"] = { ["Gurubashi Coin"] = "монета Ґурубаші", ["Gurubashi Coin (Provided)"] = "монета Ґурубаші (видано)", ["Vilebranch Coin"] = "монета Миршавого Гілля", ["Vilebranch Coin (Provided)"] = "монета Миршавого Гілля (видано)", ["Witherbark Coin"] = "монета Зів'ялої Кори", ["Witherbark Coin (Provided)"] = "монета Зів'ялої Кори (видано)" } },
    [8239] = { [1] = "Монети Піщанолютих, Черепотрощителів та Кровоскальпих", [4] = "Я шукаю знаки влади, відомі як монети племен. Це валюта, якою користуються різні племена Зул'Ґуруба, і кожна з них наповнена непомітною, але потужною магією.\n\nІснує дев'ять видів таких монет. Якщо у тебе будуть зайві — я готовий обміняти три монети на знак пошани. Ці знаки ти зможеш використати у Рін'вошо-Торговця — він пропонує нашим героям особливі предмети в обмін на них.", [5] = "Чудово — ці монети чудово доповнять нашу колекцію... яку ми використаємо для захисту племені від бога крові. Ти {стать:заслужив:заслужила} цей знак пошани, {ім'я}, разом з подякою нашого племені!", ["en"] = "Sandfury, Skullsplitter, and Bloodscalp Coins", ["tasks"] = { ["Bloodscalp Coin"] = "монета Кровоскальпих", ["Bloodscalp Coin (Provided)"] = "монета Кровоскальпих (видано)", ["Sandfury Coin"] = "монета Піщанолютих", ["Sandfury Coin (Provided)"] = "монета Піщанолютих (видано)", ["Skullsplitter Coin"] = "монета Черепотрощителів", ["Skullsplitter Coin (Provided)"] = "монета Черепотрощителів (видано)" } },
    [8240] = { [1] = "Прикраси для Занзи", [2] = "Знищення прикрас Гаккарі має для нас величезне значення. Це наша внутрішня справа, але вона настільки важлива, що ми просимо про допомогу і чужинців!\n\nВіднеси будь-які знайдені прикраси з Зул'Ґуруба до вівтаря Занзи та знищ їх. Якщо ти впораєшся із цим завданням, я дам тобі знак пошани нашого племені. Знай, що у нас цими знаками не розкидаються!\n\nІди, і нехай Занза благословить тебе!", [3] = "Знищте прикраси Гаккарі, знайдені в Зул'Ґурубі, біля вівтаря Занзи на острові Йоджамба. Як закінчите, поговоріть з Вінчаксою неподалік.", [4] = "Ти {стать:знищив:знищила} прикраси на вівтарі Занзи? Зроби це й отримаєш подвійне благословення від Занзи!", [5] = "Відмінно... кожна прикраса, яку ми відібрали у послідовників бога крові, наближає нас усіх на крок ближче до остаточної перемоги над ними раз і назавжди. Своїми благородними ти {стать:надав:надала} честь як зандаларам, так і собі.\n\nПам'ятай, {ім'я}, ти завжди можеш знищувати прикраси, які знайдеш у Зул'Ґурубі на вівтарі. За кожну знищену прикрасу ти отримаєш наше визнання та знак пошани! Лиш не забудь, що у тебе має бути вільне місце в сумках, якщо ти ще не маєш такого знака.", ["en"] = "A Bijou for Zanza" },
    [8241] = { [1] = "Відновлення запасів вогненного флюса за допомогою заліза", [4] = "Не марнуй мій дорогоцінний час пустими балачками, {раса:к}. Час сконцентруватися на поповненні наших обмежених запасів вогненного флюса.\n\nМені від тебе потрібно наступне:\n\n*Луска вогнезавра.\n\n*Злитки заліза.\n\n*Вугілля.\n\nЯ візьму все, що ти зможеш принести!\n\nІ поквапся, якщо хочеш заслужити довіру Братства.", [5] = "У нас завжди знайдеться місце для вогненного флюса, {стать:юначе:юначко}. Продовжуй... поки я тебе не зупиню.", ["en"] = "Restoring Fiery Flux Supplies via Iron", ["tasks"] = { ["Coal"] = "вугілля", ["Coal (Provided)"] = "вугілля (видано)", ["Incendosaur Scale"] = "луска вогнезавра", ["Incendosaur Scale (Provided)"] = "луска вогнезавра (видано)", ["Iron Bar"] = "злиток заліза", ["Iron Bar (Provided)"] = "злиток заліза (видано)" } },
    [8242] = { [1] = "Відновлення запасів вогненного флюса за допомогою важкої шкіри", [4] = "Не марнуй мій дорогоцінний час пустими балачками, {раса:к}. Час сконцентруватися на поповненні наших обмежених запасів вогненного флюса.\n\nМені від тебе потрібно наступне:\n\n*Луска вогнезавра.\n\n*Важка шкіра.\n\n*Вугілля.\n\nЯ візьму все, що ти зможеш принести!\n\nІ поквапся, якщо хочеш заслужити довіру Братства.", [5] = "У нас завжди знайдеться місце для вогненного флюса, {стать:юначе:юначко}. Продовжуй... поки я тебе не зупиню.", ["en"] = "Restoring Fiery Flux Supplies via Heavy Leather", ["tasks"] = { ["Coal"] = "вугілля", ["Coal (Provided)"] = "вугілля (видано)", ["Heavy Leather"] = "важка шкіра", ["Heavy Leather (Provided)"] = "важка шкіра (видано)", ["Incendosaur Scale"] = "луска вогнезавра", ["Incendosaur Scale (Provided)"] = "луска вогнезавра (видано)" } },
    [8243] = { [1] = "Потужні напої Занзи", [4] = "Тепер, коли наше плем'я шанує тебе, ти можеш користуватися нашими найпотужнішими напоями. Поглянь... вони містять в собі могутню силу — благословення Занзи, і придатні для шукачів пригод з усіх верств суспільства!\n\nЯ дозволю тобі обрати один з трьох запропонованих мною напоїв. В обмін на нього я попрошу знак пошани Зандаларів. Зауваж, що одночасно ти можеш перебувати під дією лише одного з цих напоїв.", [5] = "Це чесний обмін, {стать:мій друже:моя подруго} — прошу, насолоджуйся благословеннями Занзи!", ["en"] = "Zanza's Potent Potables", ["tasks"] = { ["21000 reputation with Zandalar Tribe"] = "21000 репутації у племені Зандалар", ["Zandalar Honor Token"] = "знак пошани Зандаларів", ["Zandalar Honor Token (Provided)"] = "знак пошани Зандаларів (видано)" } },
    [8246] = { [1] = "Печатки Зандаларів", [4] = "{ім'я}, для тих, кого возвеличують серед Зандаларів, у мене є дещо особливе. Прямо з нашого дому у Південних морях... Печатки Зандаларів! Ці печатки використовуються для посилення наплічників. Якщо ти шукаєш могутності, моджо чи спокою — у мене є те, що тобі потрібно!\n\nВ обмін на одну печатку я прошу п'ятнадцять знаків пошани Зандаларів. Якщо у тебе вже є знаки, то я готовий до обміну!", [5] = "Це чесний обмін, {стать:мій друже:моя подруго} — прийми свою печатку з благословенням племені!", ["en"] = "Signets of the Zandalar", ["tasks"] = { ["42000 reputation with Zandalar Tribe"] = "42000 репутації у племені Зандалар", ["Zandalar Honor Token"] = "знак пошани Зандаларів", ["Zandalar Honor Token (Provided)"] = "знак пошани Зандаларів (видано)" } },
    [8247] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [8248] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [8249] = { [1] = "Збір скриньок", [4] = "Мої пройдисвіти мають відточувати навички зламування, тож мені потрібні достатньо складні замки. Мотлох, який робить Зан годиться хіба що зовсім новачкам.\n\nОсь що, якщо принесеш 5 важких скриньок, я забезпечу тебе найкращими метальними ножами, які тільки бувають у пройдисвітів.\n\nТи можеш відмикати ящики та брати з них речі, але залиш там хоча б кілька монет... навіть учням-пройдисвітам потрібна мотивація.", [5] = "Нехай для цих ножів знайдеться місце в чиємусь серці.\n\nБуквально.", ["en"] = "Junkboxes Needed", ["tasks"] = { ["Heavy Junkbox"] = "важка скринька", ["Heavy Junkbox (Provided)"] = "важка скринька (видано)" } },
    [8250] = { [1] = "Мистецтво магії", [2] = "Архімаг Зілем останнім часом шукає когось... з твоїм досвідом.\n\nЯкщо бажаєш зустрітися з ним, ти знайдеш його в Азшарі. Його вежа знаходиться на високо на вершині скелі, і єдиний шлях нагору — це заклинання телепорту, відоме його зарозумілому слузі, Санату Лім-йо.\n\nСанат живе в таборі під вежею свого майстра. Щоб знайти його, вирушай до місця, де головна дорога Азшари розгалужується біля входу до руїн Ельдарата. Звідти рушай прямо на північ до скель.", [3] = "Знайдіть Саната Лім-йо та отримайте дозвіл на прохід до архімага Зілема.", [5] = "<Санат дивиться на вас з презирством.>\n\nАрхімаг Зілем чекає на тебе.", ["en"] = "Magecraft" },
    [8251] = { [1] = "Чарівний пил", [2] = "Ельфи крові Азшари розробили спосіб подрібнення магічних предметів. Блискучий пил, який вони отримують, відрізняється від компонентів, які зазвичай отримують за допомогою розпорошення.\n\nЯ відправив свого учня купити цей пил, але ельфи безжально вбили його. Вони мають заплатити за це.\n\nЧас для розмов закінчився, {ім'я:к}. Знайди ельфів крові вздовж скель Азшари та використай більш... переконливі методи, щоб отримати їхній блискучий пил.", [3] = "Принесіть 10 жмень блискучого пилу архімагу Зілему.", [4] = "Ти {стать:приніс:принесла} пил?", [5] = "Молодець, {ім'я:к}! Ніколи не перестаю дивуватися, наскільки переконливим може бути залп арканічних снарядів.", ["en"] = "Magic Dust", ["tasks"] = { ["Glittering Dust"] = "блискучий пил", ["Glittering Dust (Provided)"] = "блискучий пил (видано)" } },
    [8252] = { [1] = "Корали сирен", [2] = "Озирнись навколо. Руїни та пляжі переповнені Огидохльостими. Нещодавно ці жалюгідні створіння навчилися розпізнавати рідкісні компоненти, що зустрічаються тільки в Азшарі.\n\nЯ маю на увазі зачаровані корали — з невідомих мені причин вони притягують Огидохльостих. В затоці залишилось мало коралів, а вони життєво необхідні для моїх досліджень. Прошу тебе, відбери кілька коралів у огидохльостих сирен і принеси їх мені.", [3] = "Зберіть 6 зачарованих коралів та принесіть їх архімагу Зілему.", [4] = "Огидохльості сирени напрочуд вправні в магії. Сподіваюся, не такі вправні, як ти?", [5] = "Це чудові зразки, {ім'я:к}. Твої навички безсумнівно точні та смертоносні.\n\nНе думай, що твої зусилля непомічені. Можливо, ти {стать:вартий:варта} справжнього випробування своїх навичок...", ["en"] = "The Siren's Coral", ["tasks"] = { ["Enchanted Coral"] = "зачарований корал", ["Enchanted Coral (Provided)"] = "зачарований корал (видано)" } },
    [8253] = { [1] = "Знищити Морфаза", [2] = "У глибинах храму Атал'Гаккара живе зелений дракон, на ім'я Морфаз.\n\nБагато років тому він напав на мене із засідки та проковтнув цілком мого учня. Хоча втрата учня не є чимось новим для мене, саме цей учень носив з собою арканічний уламок неперевершеного розміру та потужності.\n\nТи маєш зібрати могутніх союзників та відправитися в храм. Знищ Морфаза та дістань арканічний уламок з його утроби.", [3] = "Заберіть у Морфаза арканічний уламок і поверніться до архімага Зілема.", [4] = "Ти {стать:вбив:вбила} мого старого ворога?", [5] = "Неймовірно. Уламок виріс, поглинаючи енергію дракона протягом довгих років.\n\nТепер я більше нічого не можу просити у тебе. Моя здібність кувати магічні артефакти повернулася з цим уламком. Моє перше творіння — твоє, {ім'я:к}. Тобі залишається тільки вибрати...", ["en"] = "Destroy Morphaz", ["tasks"] = { ["Arcane Shard"] = "арканічний уламок", ["Arcane Shard (Provided)"] = "арканічний уламок (видано)" } },
    [8254] = { [1] = "Допомога Кенарію", [2] = "Це божественний шлях — допомагати нужденним. Як саме — неважливо, важливо лише — чому.\n\nКенарійському Колу пторібна така допомога. І якщо ти хочеш допомогти їм — поговори з Оґтінком. Він проживає на вершинах скель на північний схід від руїн Ельдарта в Азшарі.", [3] = "Знайдіть Оґтінка в Азшарі.", [5] = "Від твого прибуття у мене немов спав камінь з пліч. На нас чекає багато справ.", ["en"] = "Cenarion Aid" },
    [8255] = { [1] = "Від полювачів, що нам відомі", [2] = "Мохоногі олень Азшари — прекрасні створіння, що колись населяли Сквернолісся. У них є природний імунітет до хвороб та отрут, тому псування не вплинуло на них. Ці мудрі створіння вирішили просто не жити на хворих землях.\n\nНа превеликий жаль, я мушу попросити тебе пополювати на цих могутніх звірів. Збери для мене 4 залози цих оленів — це перший інгредієнт відновлювальної мазі, яка буде використовуватися для зцілення Сквернолісся.", [3] = "Добудьте 4 залози здорового мохоногого оленя та принесіть їх Оґтінку в Азшару. Оґтінк проживає на схилах пагорбів на північний схід від руїн Ельдарата.", [4] = "Ти {стать:повернувся:повернулася}. Як твої успіхи?", [5] = "Добре, що божественний шлях привів тебе до нас, {ім'я}. Твої вірування не заважають виконанню завдань для створення цієї мазі.\n\nРозумієш, олені — священні для Кенарійського Кола, і вбивство цих тварин послаблює їх дух.", ["en"] = "Of Coursers We Know", ["tasks"] = { ["Healthy Courser Gland"] = "залоза здорового оленя", ["Healthy Courser Gland (Provided)"] = "залоза здорового оленя (видано)" } },
    [8256] = { [1] = "Пасока невмерлих", [2] = "У цієї цілющої мазі буде проста формула: одна частина отрути та дві частини цілющих компонентів. Один цілющий компонент ти вже {стать:приніс:принесла}, тепер потрібно знайти отруту.\n\nМогутні невмерлі, такі як невпокоєні високородні, що тиняються руїнами Ельдарата, настільки вражені псуванням, що воно матеріалізується у формі зеленого слизу. Серед живих ця субстанція відома як пасока невмерлих.\n\nЦе дуже потужна отрута, тож мені достатньо одного зразку.", [3] = "Принесіть Оґтінку з Азшари пасоку невмерлих. Оґтінк проживає на схилах пагорбів на північний схід від руїн Ельдарата.", [4] = "Нам треба скоріш дістати пасоку. Тобі вдалося добути її?", [5] = "Не можу сказати, що мені приємно отримати цю мерзенну субстанцію, але це необхідне зло. Дякую, {ім'я}.", ["en"] = "The Ichor of Undeath", ["tasks"] = { ["Ichor of Undeath"] = "пасока невмерлих", ["Ichor of Undeath (Provided)"] = "пасока невмерлих (видано)" } },
    [8257] = { [1] = "Кров Морфаза", [2] = "Тепер нам потрібен останній цілющий компонент.\n\nЯк нам відомо, зелений дракон Морфаз наділений імунітетом до усіх форм отрути та хвороб. Багато друїдів загинуло, щоб передати нам цю інформацію. Упевнений, що його кров чудово підійде для наших потреб.\n\nКур'єр з Кенарійського Кола забере компоненти, які ти вже {стать:зібрав:зібрала}, поки ти будеш добувати останній. Збери союзників та лігво зеленого дракона у затонулому храмі Атал'Гаккар. Принеси його кров Ґреті Моховому Копиту у Сквернолісся.", [3] = "Вбийте Морфаза у затонулому храмі Атал'Гаккар, та принесіть його кров Ґреті Моховому Копиту. Вхід до храму знаходиться на болоті Скорбот.", [4] = "Ти {стать:приніс:принесла} кров Морфаза?", [5] = "Ти {стать:подолав:подолала} Морфаза та {стать:приніс:принесла} нам його кров... Я не можу повірити в цю добру новину!\n\nМи поєднаємо інгредієнти та почнемо зцілювати дерева та створінь Сквернолісся. Зцілення може зайняти не один вік, але ти {стать:надав:надала} нам вдосталь засобів для цього.", ["en"] = "Blood of Morphaz", ["tasks"] = { ["Blood of Morphaz"] = "кров Морфаза", ["Blood of Morphaz (Provided)"] = "кров Морфаза (видано)" } },
    [8258] = { [1] = "Загроза Тінегубителя", [2] = "Лицар смерті Тінегубитель панує у великому склепі Некроситету. Він погрожує підкорити царство духів своїй волі, і його необхідно зупинити! Ось тут-то тобі й знадобиться кристал провидіння.\n\nПриведи його в дію у самому серці великого склепу, щоб викликати поплічників Тінегубителя. Коли ти здолаєш цих духів, з'явиться сам лицар смерті. Принеси мені його голову, {ім'я}! Тільки його смерть здатна виправити шкоду, завдану царству духів!", [3] = "Використайте кристал провидіння в глибинах підземель великого склепу Некроситету. Це викличе чотирьох духів, з якими ви маєте битись. Перемога над цими духами викличе лицаря смерті Тінегубителя. Переможіть його.\n\nВіднесіть голову Тінегубителя Саґорну Хребтоступу в долину Мудрості, що в Орґріммарі.", [4] = "Часу обмаль, {ім'я} — тобі вдалося зупинити лицаря смерті Тінегубителя?", [5] = "Це гідна перемога, {ім'я}! Загибель Тінегубителя має відновити тендітні кайдани, що тримають царство духів.\n\nТи значно {стать:перевершив:перевершила} те, чого від тебе вимагали, навіть коли ти не мав жодного уявлення про винагороду чи компенсацію. Ти справді {стать:гідний:гідна} {клас}.\n\nЯ знаю, що дії, спрямовані на збереження царства духів мають бути достатньою подякою, але, будь ласка — прийми цей простий подарунок на знак моєї вдячності.", ["en"] = "The Darkreaver Menace", ["tasks"] = { ["Darkreaver's Head"] = "голова Тінегубителя", ["Darkreaver's Head (Provided)"] = "голова Тінегубителя (видано)" } },
    [8260] = { [1] = "Базовий набір припасів Ліги Аратора", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я:к}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в низині Араті.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в низині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть дружніми, а бинти — коли почесними.", ["en"] = "Arathor Basic Care Package", ["tasks"] = { ["The League of Arathor"] = "Ліга Аратора" } },
    [8263] = { [1] = "Базовий набір припасів Труїтелів", [5] = "Ти {стать:почав:почала} справляти непогане враження, {ім'я:к}. Прийми цей пакунок як нагороду! У ньому є пайки та бинти, які можна використовувати лише в низині Араті.\n\nЯкщо ти й надалі проявлятимеш свої бойові здібності в низині, то отримаєш можливість придбати ці речі. Пайки стануть доступними коли наші відносини стануть почесними, а бинти — коли шанованими.", ["en"] = "Defiler's Basic Care Package", ["tasks"] = { ["The Defilers"] = "Осквернителі" } },
    [8266] = { [1] = "Жертовні стрічки", [2] = "Я розумію, що іноді буває важко здобути перемогу в тіснині Пісні Війни. Проте, участь в бою від нашого імені — навіть якщо перемога не досягнута — є важливою.\n\nЯкщо ти відправишся в тіснину Пісні Війни, але не здобудеш перемогу — ти все одно отримаєш жертовні стрічки. Принеси їх мені, щоб авангард Пісні Війни винагородив тебе за твої зусилля... навіть якщо вони не привели до перемоги.", [3] = "Принесіть жертовні стрічки капітану Череподробу, щоб отримати винагороду за допомогу авангарду Пісні Війни.", [4] = "Я розумію, що іноді буває важко здобути перемогу в тіснині Пісні Війни. Проте, участь в бою від нашого імені — навіть якщо перемога не досягнута — є важливою.\n\nЯкщо ти відправишся в тіснину Пісні Війни, але не здобудеш перемогу — ти все одно отримаєш жертовні стрічки. Принеси їх мені, щоб авангард Пісні Війни винагородив тебе за твої зусилля... навіть якщо вони не привели до перемоги.", [5] = "Що ж, ти не {стать:опустив:опустила} руки перед обличчям поразки. Ти {стать:стояв:стояла} до останнього, {ім'я:к}, і саме це є справжнім героїзмом. Наступного разу ти обов'язково переможеш... але ми все одно дякуємо за твої зусилля.", ["en"] = "Ribbons of Sacrifice", ["tasks"] = { ["Warsong Gulch Ribbon of Sacrifice"] = "жертовна стрічка Пісні Війни", ["Warsong Gulch Ribbon of Sacrifice (Provided)"] = "жертовна стрічка Пісні Війни (видано)" } },
    [8267] = { [1] = "Жертовні стрічки", [2] = "Я розумію, що іноді буває важко здобути перемогу в тіснині Пісні Війни. Проте, участь в бою від нашого імені — навіть якщо перемога не досягнута — є важливою.\n\nЯкщо ти відправишся в тіснину Пісні Війни, але не здобудеш перемогу — ти все одно отримаєш жертовні стрічки. Принеси їх мені, щоб авангард Пісні Війни винагородив тебе за твої зусилля... навіть якщо вони не привели до перемоги.", [3] = "Принесіть жертовні стрічки капітану Череподробу, щоб отримати винагороду за допомогу авангарду Пісні Війни.", [4] = "Я розумію, що іноді буває важко здобути перемогу в тіснині Пісні Війни. Проте, участь в бою від нашого імені — навіть якщо перемога не досягнута — є важливою.\n\nЯкщо ти відправишся в тіснину Пісні Війни, але не здобудеш перемогу — ти все одно отримаєш жертовні стрічки. Принеси їх мені, щоб авангард Пісні Війни винагородив тебе за твої зусилля... навіть якщо вони не привели до перемоги.", [5] = "Що ж, ти не {стать:опустив:опустила} руки перед обличчям поразки. Ти {стать:стояв:стояла} до останнього, {ім'я:к}, і саме це є справжнім героїзмом. Наступного разу ти обов'язково переможеш... але ми все одно дякуємо за твої зусилля.", ["en"] = "Ribbons of Sacrifice", ["tasks"] = { ["Warsong Gulch Ribbon of Sacrifice"] = "жертовна стрічка Пісні Війни", ["Warsong Gulch Ribbon of Sacrifice (Provided)"] = "жертовна стрічка Пісні Війни (видано)" } },
    [8268] = { [1] = "Жертовні стрічки", [2] = "Я розумію, що іноді буває важко здобути перемогу в тіснині Пісні Війни. Проте, участь в бою від нашого імені — навіть якщо перемога не досягнута — є важливою.\n\nЯкщо ти відправишся в тіснину Пісні Війни, але не здобудеш перемогу — ти все одно отримаєш жертовні стрічки. Принеси їх мені, щоб Срібнокрилі стражі винагородили тебе за твої зусилля... навіть якщо вони не привели до перемоги.", [3] = "Принесіть жертовні стрічки стражниці Далепісні, щоб отримати винагороду за допомогу Срібнокрилим стражам.", [4] = "Я розумію, що іноді буває важко здобути перемогу в тіснині Пісні Війни. Проте, участь в бою від нашого імені — навіть якщо перемога не досягнута — є важливою.\n\nЯкщо ти відправишся в тіснину Пісні Війни, але не здобудеш перемогу — ти все одно отримаєш жертовні стрічки. Принеси їх мені, щоб Срібнокрилі стражі винагородили тебе за твої зусилля... навіть якщо вони не привели до перемоги.", [5] = "Що ж, ти не {стать:опустив:опустила} руки перед обличчям поразки. Ти {стать:стояв:стояла} до останнього, {ім'я:к}, і саме це є справжнім героїзмом. Наступного разу ти обов'язково переможеш... але ми все одно дякуємо за твої зусилля.", ["en"] = "Ribbons of Sacrifice", ["tasks"] = { ["Warsong Gulch Ribbon of Sacrifice"] = "жертовна стрічка Пісні Війни", ["Warsong Gulch Ribbon of Sacrifice (Provided)"] = "жертовна стрічка Пісні Війни (видано)" } },
    [8269] = { [1] = "Жертовні стрічки", [2] = "Я розумію, що іноді буває важко здобути перемогу в тіснині Пісні Війни. Проте, участь в бою від нашого імені — навіть якщо перемога не досягнута — є важливою.\n\nЯкщо ти відправишся в тіснину Пісні Війни, але не здобудеш перемогу — ти все одно отримаєш жертовні стрічки. Принеси їх мені, щоб Срібнокрилі стражі винагородили тебе за твої зусилля... навіть якщо вони не привели до перемоги.", [3] = "Принесіть жертовні стрічки стражниці Далепісні, щоб отримати винагороду за допомогу Срібнокрилим стражам.", [4] = "Я розумію, що іноді буває важко здобути перемогу в тіснині Пісні Війни. Проте, участь в бою від нашого імені — навіть якщо перемога не досягнута — є важливою.\n\nЯкщо ти відправишся в тіснину Пісні Війни, але не здобудеш перемогу — ти все одно отримаєш жертовні стрічки. Принеси їх мені, щоб Срібнокрилі стражі винагородили тебе за твої зусилля... навіть якщо вони не привели до перемоги.", [5] = "Що ж, ти не {стать:опустив:опустила} руки перед обличчям поразки. Ти {стать:стояв:стояла} до останнього, {ім'я:к}, і саме це є справжнім героїзмом. Наступного разу ти обов'язково переможеш... але ми все одно дякуємо за твої зусилля.", ["en"] = "Ribbons of Sacrifice", ["tasks"] = { ["Warsong Gulch Ribbon of Sacrifice"] = "жертовна стрічка Пісні Війни", ["Warsong Gulch Ribbon of Sacrifice (Provided)"] = "жертовна стрічка Пісні Війни (видано)" } },
    [8270] = { [1] = "тестовий копіювальний квест", ["en"] = "test copy quest" },
    [8274] = { [1] = "Квест на випробування вбивства", [2] = "Маєш трохи вільного часу? Вбий мені кілька мурлоків, і я дам тобі щось блискуче!", [3] = "Убийте 5 мурлоків та поверніться до тестового персонажа.", ["en"] = "Test Kill Quest", ["tasks"] = { ["Murloc Coastrunner slain"] = "мурлок-берегобігун: убито" } },
    [8277] = { [1] = "Смертельна отрута пустелі", [2] = "Бітікс Хиткожвав до ваших послуг! Мій кузен Ноґґл заробляє на життя, збираючи рідкісні трави для алхіміків Кенарійської цитаделі. Принаймні, заробляв. Він повернувся з останньої вилазки, вражений сильною отрутою.\n\nМені вдалося сповільнити дію отрути, але щоб повністю нейтралізувати її, мені потрібні зразки отрути тих істот, що його вкусили.\n\nНоґґл прийшов з півночі, тож я б'юся об заклад, що це зробили камнехвості скорпіди або піщані швидколапи. Принеси мені кілька жал та ікл і я спробую зробити протиотруту.", [3] = "Бітікс Хиткожвав з Кенарійської цитаделі, що в Силітусі, хоче, щоб ви зібрали 8 жал камнехвостих скорпідів і 8 ікл піщаних швидколапів. Поверніться до неї, коли виконаєте завдання.", [4] = "Ти {стать:зібрав:зібрала} зразки? Ми можемо втратити Ноґґла в будь-яку хвилину!", [5] = "Схрестимо пальці, {стать:друже:подруго}! Сподіваюся, нам вдасться врятувати Ноґґла!", ["en"] = "Deadly Desert Venom", ["tasks"] = { ["Sand Skitterer Fang"] = "ікло піщаного швидколапа", ["Sand Skitterer Fang (Provided)"] = "ікло піщаного швидколапа (видано)", ["Stonelash Scorpid Stinger"] = "жало камнехвостого скорпіда", ["Stonelash Scorpid Stinger (Provided)"] = "жало камнехвостого скорпіда (видано)" } },
    [8278] = { [1] = "Остання надія Ноґґла", [2] = "Прокляття! Протиотрута не спрацювала. Мабуть, Ноґґла вкусила одна з сильніших істот на далекому півдні.\n\nЯ хочу, щоб ти {стать:пішов туди та приніс:пішла туди та принесла} мені ще кілька зразків, {ім'я}. Гарна новина полягає в тому, що оскільки їхня отрута сильніша, мені знадобиться не так багато зразків. Погана новина — на півдні більше видів отруйних істот, тому тобі доведеться зібрати зразки з них всіх.", [3] = "Бітікс Хиткожвав з Кенарійської цитаделі, що в Силітусі, хоче, щоб ви принесли 3 жала камнехвостих щипачів, 3 жала камнехвостих потрошителів і 3 ікла скельних ловців.", [4] = "Це наш останній шанс врятувати Ноґґла! Поквапся!", [5] = "Так! Здається, спрацювало, Ноґґл приходить до тями. Ми перед тобою у великому боргу!", ["en"] = "Noggle's Last Hope", ["tasks"] = { ["Rock Stalker Fang"] = "ікло скельного ловця", ["Rock Stalker Fang (Provided)"] = "ікло скельного ловця (видано)", ["Stonelash Flayer Stinger"] = "жало камнехвостого потрошителя", ["Stonelash Flayer Stinger (Provided)"] = "жало камнехвостого потрошителя (видано)", ["Stonelash Pincer Stinger"] = "жало камнехвостого щипача", ["Stonelash Pincer Stinger (Provided)"] = "жало камнехвостого щипача (видано)" } },
    [8279] = { [1] = "Сутінковий словник", [2] = "Сутінковий Молот ненавидить тих, хто покидає їхні лави. Вони полюють на мене й до сьогодні, ніби я якийсь звір! Що тут говорити, їхній ворог — мій друг!\n\nЩоб розшифрувати цю скрижаль, мені потрібна книга, яку використовують їхні писарі для кодування таємних послань — Сутінковий словник. Це настільки важливий інструмент, що вони зберігають три його розділи в різних місцях! Розділи словника охороняють офіцери, відомі як сутінкові хранителі. Шукай їх у таборах Сутінкового Молота.", [3] = "Принесіть три розділи Сутінкового словника відлюднику Ортеллу в Силітус.", [4] = "Хто там ходить? А, це ти! Ти вже {стать:знайшов:знайшла} усі розділи словника?", [5] = "Так! Це вони! Розпочнімо, {ім'я}.\n\nЗамінити кожне третє слово словами з другого розділу... Потім замінити кожне друге слово словами з першого розділу... Чи навпаки...", ["en"] = "The Twilight Lexicon", ["tasks"] = { ["Twilight Lexicon - Chapter 1"] = "Сутінковий словник - розділ 1", ["Twilight Lexicon - Chapter 1 (Provided)"] = "Сутінковий словник - розділ 1 (видано)", ["Twilight Lexicon - Chapter 2"] = "Сутінковий словник - розділ 2", ["Twilight Lexicon - Chapter 2 (Provided)"] = "Сутінковий словник - розділ 2 (видано)", ["Twilight Lexicon - Chapter 3"] = "Сутінковий словник - розділ 3", ["Twilight Lexicon - Chapter 3 (Provided)"] = "Сутінковий словник - розділ 3 (видано)" } },
    [8280] = { [1] = "Захист шляхів постачання", [2] = "Кенарійська цитадель має надзвичайно важливе стратегічне значення. Я впевнений, що поки ми утримуємо її, наша перемога над силітидами гарантована. За умови, що ми зможемо регулярно отримувати припаси.\n\nПустельні черв'яки виявилися навіть більшою загрозою для наших постачань, ніж самі силітиди. Наприклад, сьогодні група землечерпів розграбувала великий караван зі світанковим зерном. Я хочу, щоб ти {стать:зменшив:зменшила} популяцію цих істот, щоб забезпечити безпеку для наших вантажів.", [3] = "Вітрозов Гордий Ріг з Кенарійської цитаделі в Силітусі хоче, щоб ви вбили 15 землечерпів.", [4] = "Землечерпи становлять серйозну загрозу, тому з ними потрібно якнайшвидше розібратися!", [5] = "Щиро дякую тобі. Ти {стать:продемонстрував:продемонструвала} неабияку хоробрість, допомагаючи Кенарійській цитаделі.", ["en"] = "Securing the Supply Lines", ["tasks"] = { ["Dredge Striker"] = "землечерп", ["Dredge Striker slain"] = "землечерп: убито" } },
    [8281] = { [1] = "Посилення безпеки", [2] = "Ти {стать:продемонстрував:продемонструвала} зразкову роботу, {ім'я}. Проте захист наших шляхів постачання все ще недостатній. Землечерпів вже немає, але їхні південні родичі неодмінно займуть місце на півночі.\n\nТобі доведеться вбити чимало землечерпів-дробарів, щоби запобігти цьому, але ми не можемо наражати на небезпеку наші шляхи постачання.", [3] = "Вітрозов Гордий Ріг з Кенарійської цитаделі в Силітусі хоче, щоб ви вбили 20 землечерпів-дробарів.", [4] = "Землечерпи-дробарі становлять серйозну загрозу, тож треба негайно з ними розібратися!", [5] = "Чудова робота! Ти {стать:виявився цінним союзником:виявилася цінною союзницею} у підготовці до війни проти силітидів.", ["en"] = "Stepping Up Security", ["tasks"] = { ["Dredge Crusher"] = "землечерп-дробар", ["Dredge Crusher slain"] = "землечерп-дробар: убито" } },
    [8282] = { [1] = "Загублений рюкзак Ноґґла", [2] = "Де я? Де мій рюкзак? *зітхає* Мабуть, я загубив його, коли тікав від Смертехвата, велетенського скорпіда. Втікаючи, я зайшов прямо в гніздо камнехвостих потрошителів.\n\nУ рюкзаку, який я мав, були всілякі рідкісні реагенти. Без них ми з Бітікс не зможемо виготовити зілля для Кенарійської цитаделі. Зараз я занадто слабкий, щоб піднятися, але зможу добряче заплатити, якщо ти повернеш мої реагенти.\n\nЯ натрапив на Смертехвата у південних горах, за табором Бронзобородих.", [3] = "Знайдіть рюкзак Ноґґла в горах на півдні Силітуса і принесіть його йому в Кенарійську цитадель.", [4] = "Все ще не {стать:знайшов:знайшла} мій рюкзак? Що ж, мені пощастило — принаймні моє тіло повністю очистилось від отрути.", [5] = "Так! Ти {стать:приніс:принесла} мій рюкзак. І всі мої рідкісні реагенти в ньому! Я твій боржник на довгі роки.", ["en"] = "Noggle's Lost Satchel", ["tasks"] = { ["Noggle's Satchel"] = "рюкзак Ноґґла", ["Noggle's Satchel (Provided)"] = "рюкзак Ноґґла (видано)" } },
    [8283] = { [1] = "Розшукується: Смертехват, жахіття пустелі", [2] = "Згідно з останніми відомостями, через активність силітидів, жахливий скорпід, Смертехват, відступив до піденних гір. Ця істота становить велику загрозу для патрулів та експедицій у південних регіонах. Ті, хто посприяють її знищенню, отримають щедру винагороду. За винагородою звертайтесь до капітана Віша Козуса, на вершині сторожової вежі Кенарійської цитаделі.", [3] = "Принесіть клешню Смертехвата Вішу Козусу, капітану вартових.", [4] = "Мені потрібна клешня тієї істоти, як доказ твого подвигу. Немає клешні — немає винагороди.", [5] = "Чудово! Тепер ми можемо використовувати південні гори як стратегічний шлях, щоб обійти вулики силітидів. Ми високо цінуємо твою роботу.", ["en"] = "Wanted - Deathclasp, Terror of the Sands", ["tasks"] = { ["Deathclasp's Pincer"] = "клешня Смертехвата", ["Deathclasp's Pincer (Provided)"] = "клешня Смертехвата (видано)" } },
    [8284] = { [1] = "Сутінкова таємниця", [2] = "На північному заході звідси колись розташовувався табір культистів Сутінкового Молота. Якби ти {стать:наважився:наважилася} піти туди зараз, то {стать:побачив би:побачила б}, що вся територія кишить елементалями, а на місці табору немає нічого, окрім розкиданих шматків дерева та полотна, що лише нагадують про табір.\n\nЯ знайшла кілька фрагментів глиняної скрижалі звідти, але їх замало, щоб дізнатися щось корисне. Спробуй знайти решту фрагментів скрижалі, щоб ми могли дізнатись, що робить Сутінковий Молот у Силітусі.", [3] = "Геолог Жартолам з Кенарійської цитаделі, що в Силітусі, хоче, щоб ви зібрали 8 фрагментів сутінкової скрижалі.", [4] = "Зруйнований табір знаходиться на північному заході. Повертайся, коли збереш всі фрагменти.", [5] = "Як я і думав. Я можу розшифрувати окремі слова на скрижалях, але, здається, в них немає ніякої логіки та сенсу. Сутінковий Молот часто використовує шифр, щоб приховати сенс своїх текстів, тож нам доведеться звернутися до когось, хто краще розбирається в таких речах.", ["en"] = "The Twilight Mystery", ["tasks"] = { ["Twilight Tablet Fragment"] = "фрагмент сутінкової скрижалі", ["Twilight Tablet Fragment (Provided)"] = "фрагмент сутінкової скрижалі (видано)" } },
    [8285] = { [1] = "Дезертир", [2] = "Ходять чутки, що член Сутінкового Молота, на ім'я Ортелл, вийшов з рядів секти. Подейкують, що він сховався в горах на південь від селища Південний Вітер, в повній самотності. Можливо, тобі вдасться отримати його допомогу в розшифровці скрижалі.\n\nВізьми відновлену скрижаль з собою і вирушай на пошуки Ортелла.", [3] = "Віднесіть відновлену скрижаль відлюднику Ортеллу в Силітус.", [4] = "Ти! Як ти мене {стать:знайшов:знайшла}? Хто ти? За тобою не стежили? Говори!", [5] = "Бачу, ти {стать:знайомий:знайома} з моєю старою організацією. Ти, мабуть, з Кенарійської цитаделі.\n\nТобі потрібна інформація, щоб використати її проти Сутінкового Молота? Підійди ближче, можливо, ми зможемо допомогти одне одному.", ["en"] = "The Deserter", ["tasks"] = { ["Restored Twilight Tablet"] = "відновлена сутінкова скрижаль", ["Restored Twilight Tablet (Provided)"] = "відновлена сутінкова скрижаль (видано)" } },
    [82850] = { [1] = "Риб'ячий жир", [4] = "Риб'ячий жир змушує обертатися всі шестерні війни! Якщо в тебе є трохи для мене, друже, я зроблю все, щоб це було варте твоїх зусиль.", [5] = "Щиро дякую, {ім'я}. Я використовую це з користю.", ["en"] = "Fish Oil" },
    [82851] = { [1] = "Темний залізний ордонанс", [4] = "Чи знаєш ти, що за традицією Темного Заліза Сенат пише законопроекти про вибухові снаряди? Якщо Імператору не подобається закон... бум!\n\nЧому ти так на мене дивишся? Ти що, не довіряєш своєму старому приятелю Гріззбі?", [5] = "Щиро дякую, {ім'я}. Я використовую це з користю.", ["en"] = "Dark Iron Ordinance" },
    [82853] = { [1] = "Турбокомпресори подрібнювача", [4] = "Невдача, що судноплавні шляхи до Кезана зараз такі ненадійні. Удома можна купити турбокомпресори десятками за кілька мідяків. Вони зникають з полиць у кожній механічній майстерні. Позбутися їх ніяк не вдається.\n\nУ будь-якому разі, якщо у вас є кілька турбокомпресорів, з якими ви не знаєте, що з ними робити, я буду радий їх у вас забрати!", [5] = "Щиро дякую, {ім'я}. Я використовую це з користю.", ["en"] = "Shredder Turbochargers" },
    [8286] = { [1] = "Що день прийдешній нам готує", [2] = "Я вже був за крок до обіймів зі смертю, але потім він втрутився. Він лише раз дихнув на моє понівечене тіло, а потім терпляче чекав, поки піски часу очистять мої рани.\n\n\"Ти залишишся тут назавжди, якщо захочеш\" — сказав він і зробив мене наглядачем.\n\nПоглянь тепер на пустелю. Друга війна наближається. Ти {стать:повинен:повинна} знайти місце спочинку бронзових драконів. Відправляйся в Печери Часу і дізнайся, чи повернувся господар. Я повинен знати це, перш ніж діяти.", [3] = "Відвідайте Печери Часу в Танарісі та знайдіть Анахроноса з Роду Ноздорму.", [4] = "Анахронос повернувся?", [5] = "Все так, як і має бути — володар повстав. Моя варта добігає кінця...", ["en"] = "What Tomorrow Brings", ["tasks"] = { ["Discover the Brood of Nozdormu."] = "Відкрийте для себе Виводок Ноздорму.", ["Explore Zone"] = "Дослідіть місцевість" } },
    [8287] = { [1] = "Жахлива ціль", [2] = "Так, ну добре... досить цінна інформація, мушу сказати! Я бачив, як війська Кенарійського Кола прибули в Силітус. Вони планують вигнати Сутінковий Молот звідси, чи не так? Це може допомогти втілити їхні плани.\n\nВіднеси цей пергамент їхньому лідеру, командиру Мар'аліту. Скоро ми переможемо Сутінковий Молот і вони ніколи не доберуться до мене!", [3] = "Віднесіть розшифрований текст скрижалі командиру Мар'аліту.", [4] = "Що це ти {стать:приніс:принесла} мені, {ім'я}?", [5] = "Це дійсно дуже цікава інформація, {ім'я}. Це пояснює, що Сутінковий Молот робить у Силітусі й, безсумнівно, допоможе у боротьбі з ними. Твоя робота буде щедро оплачена, {клас:к}.", ["en"] = "A Terrible Purpose", ["tasks"] = { ["Decoded Tablet Transcription"] = "розшифрований текст скрижалі", ["Decoded Tablet Transcription (Provided)"] = "розшифрований текст скрижалі (видано)" } },
    [8288] = { [1] = "Лиш одного буде обрано", [2] = "Не можна гаяти час! Ми маємо знайти чемпіона! Завдання, яке я доручу тобі, потребує цілої армії, але лиш один зможе взяти на себе тягар і відповідальність союзника Роду.\n\nУ лігві повелителя Чорнокаменю живе найжорстокіший звір. Володар роду Хлист Бича охороняє Зали Боротьби, перекриваючи шлях до внутрішнього святилища Нефаріана. Вбий покидька та принеси мені його голову. Зробиш це і, можливо, зможеш розпочати наступний етап своєї подорожі.", [3] = "Принесіть голову володаря роду Хлиста Бича до Барістольта Мінливих Пісків в Кенарійську цитадель, що в Силітусі.", [4] = "Ти {стать:повинен:повинна} заслужити прихильність Роду Ноздорму.", [5] = "Чи можеш ти стати {стать:першим:першою}, хто заслужить прихильність Бронзового крила за тисячу років?", ["en"] = "Only One May Rise", ["tasks"] = { ["Head of the Broodlord Lashlayer"] = "голова володаря роду Хлиста Бича", ["Head of the Broodlord Lashlayer (Provided)"] = "голова володаря роду Хлиста Бича (видано)" } },
    [8289] = { [1] = "Талісмани заслуг", ["en"] = "Talismans of Merit", ["tasks"] = { ["Silverwing Talisman of Merit"] = "талісман заслуги Срібнокрилих", ["Silverwing Talisman of Merit (Provided)"] = "талісман заслуги Срібнокрилих (видано)" } },
    [8290] = { [1] = "Знищити загарбників", [2] = "За цим тунелем ти знайдеш поле запеклих битв, {стать:юний:юна} {клас:к}. Орда продовжує нищити наш священний ліс, вирубуючи вічнозелені крони для живлення своїх військових машин.\n\nПрямуй в тіснину Пісні Війни та захисти фортецю Срібнокрилих. Відбий напади ординських загарбників!\n\nЗроби це — і отримаєш талісман заслуг. Принеси мені такий талісман, {ім'я:к}, і я винагороджу тебе.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Орду, отримайте відзнаку честі тіснини Пісні Війни та принесіть її стражниці Далепісні в Срібнокрилі хащі.", ["en"] = "Vanquish the Invaders", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8291] = { [1] = "Знищити загарбників!", [2] = "За цим тунелем ти знайдеш поле запеклих битв, {стать:юний:юна} {клас:к}. Орда продовжує нищити наш священний ліс, вирубуючи вічнозелені крони для живлення своїх військових машин.\n\nПрямуй в тіснину Пісні Війни та захисти фортецю Срібнокрилих. Відбий напади ординських загарбників!\n\nЗроби це — і отримаєш талісман заслуг. Принеси мені такий талісман, {ім'я:к}, і я винагороджу тебе.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Орду, отримайте відзнаку честі тіснини Пісні Війни та принесіть її стражниці Далепісні в Срібнокрилі хащі.", [4] = "Тобі вже вдалось захистити фортецю Срібнокрилих в тіснині Пісні Війни?", [5] = "Ти {стать:довів:довела} свою цінність для наших зусиль в тіснині Пісні Війни. Продовжуй допомагати та принеси мені більше талісманів заслуг. Зроби це, і заслужиш нашу довіру.", ["en"] = "Vanquish the Invaders!", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8292] = { [1] = "Талісмани заслуг", [4] = "Ти {стать:отримав:отримала} талісман заслуги Срібнокрилих за виконання минулого завдання. Поговори зі мною знову, щоб отримати винагороду.", [5] = "Дякую, {ім'я:к}. Звістки про твої подвиги в тіснині Пісні Війни розійшлися по всьому Ясенедолу.", ["en"] = "Talismans of Merit", ["tasks"] = { ["Silverwing Talisman of Merit"] = "талісман заслуги Срібнокрилих", ["Silverwing Talisman of Merit (Provided)"] = "талісман заслуги Срібнокрилих (видано)" } },
    [8293] = { [1] = "Відзнака честі", [4] = "Ти {стать:заслужив:заслужила} довіру за виконання минулого завдання. Принеси мені більше відзнак честі й отримаєш винагороду.", [5] = "Нічні ельфи та їхні союзники мають тремтіти від однієї лиш згадки твого імені! За Орду!\n\nТи {стать:довів:довела} свою цінність для нашої справи в тіснині Пісні Війни. Виплесни всю свою лють на Срібнокрилих стражів! Принеси мені більше відзнак честі!", ["en"] = "Mark of Honor", ["tasks"] = { ["Warsong Mark of Honor"] = "відзнака честі Пісні Війни", ["Warsong Mark of Honor (Provided)"] = "відзнака честі Пісні Війни (видано)" } },
    [8294] = { [1] = "Розгромити Срібнокрилих загарбників", [2] = "Хащі Ясенедолу підкоряться могутності Орди, {раса:к}. Що б не робили Срібнокрилі, їм не впоратися з нашим натиском. Калімдор належить Орді. Як вони сміють заважати нам збирати те, що належить нам по праву!\n\nНехай гордість наповнює твої груди, коли ти зломиш їхні жалюгідні спроби зупинити нас. Розгроми Срібнокрилих стражів і заслужи відзнаку честі тіснини Пісні Війни. Повертайся до мене з такою відзнакою, {ім'я:к}, і отримаєш винагороду.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Альянс, отримайте відзнаку честі тіснини Пісні Війни та принесіть її капітану Череподробу в табір Мор'шан.", [4] = "Кров наших ворогів — відзнака честі. Вже маєш таку?", [5] = "<Капітан Череподроб тріумфально ричить.>\n\nСкільки ще вони зможуть витримати? Скільки ще покидьків Альянсу має загинути від рук Орди, щоб вони відступили? Тільки час покаже, {раса:к}.", ["en"] = "Quell the Silverwing Usurpers", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8295] = { [1] = "Розгромити Срібнокрилих загарбників", [2] = "Хащі Ясенедолу підкоряться могутності Орди, {раса:к}. Що б не робили Срібнокрилі, їм не впоратися з нашим натиском. Калімдор належить Орді. Як вони сміють заважати нам збирати те, що належить нам по праву!\n\nНехай гордість наповнює твої груди, коли ти зломиш їхні жалюгідні спроби зупинити нас. Розгроми Срібнокрилих стражів і заслужи відзнаку честі тіснини Пісні Війни. Повертайся до мене з такою відзнакою, {ім'я:к}, і отримаєш винагороду.", [3] = "Увійдіть в тіснину Пісні Війни та переможіть Альянс, отримайте відзнаку честі тіснини Пісні Війни та принесіть її капітану Череподробу в табір Мор'шан.", ["en"] = "Quell the Silverwing Usurpers", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8296] = { [1] = "Знак пошани", ["en"] = "Mark of Honor", ["tasks"] = { ["Warsong Mark of Honor"] = "відзнака честі Пісні Війни", ["Warsong Mark of Honor (Provided)"] = "відзнака честі Пісні Війни (видано)" } },
    [8297] = { [1] = "Ресурси низини Араті", [2] = "Війну виграють солдати — це тобі скаже будь-який солдат. Він також скаже, що битва, яка ведеться з поганим спорядженням або на порожній шлунок, програна ще до її початку!\n\nОсь чому низина Араті така важлива. У цій низині є ключові райони, в яких містяться важливі ресурси. Метал, зброя, їжа, деревина — все це нам потрібно і все це можна отримати там.\n\nОсь, що я хочу від тебе, {ім'я:к}. Іди в низину Араті, виграй битву, утримавши більше баз, ніж ворог і принеси мені ящик з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його сержанту Очистій в Опорний пункт.", [4] = "Ти {стать:приніс:принесла} ящик з ресурсами, {ім'я:к}? Без них Ліга Аратора багато не навоює...", [5] = "Ти {стать:приніс:принесла} ресурси! Чудова робота! Я відправлю ці ресурси нашим квартирмейстерам, щоб вони якомога швидше роздали їх військам.\n\nДякую тобі, {ім'я:к}. Саме завдяки сумлінному виконанню таких завдань й виграються війни.", ["en"] = "Arathi Basin Resources!", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8298] = { [1] = "Більше ящиків з ресурсами", [2] = "Війну виграють солдати — це тобі скаже будь-який солдат. Він також скаже, що битва, яка ведеться з поганим спорядженням або на порожній шлунок, програна ще до її початку!\n\nОсь чому низина Араті така важлива. У цій низині є ключові райони, в яких містяться важливі ресурси. Метал, зброя, їжа, деревина — все це нам потрібно і все це можна отримати там.\n\nОсь, що я хочу від тебе, {ім'я:к}. Іди в низину Араті, виграй битву, утримавши більше баз, ніж ворог і принеси мені ящик з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його сержанту Очистій в Опорний пункт.", [4] = "{ім'я:к}, твоє завдання лишається незмінним — повертайся в низину Араті, добудь більше ящиків з ресурсами та принеси їх мені.", [5] = "Чудово. Я негайно передам ці ресурси нашим квартирмейстерам, а начальству — подяку за твої дії.\n\nЩе раз дякую тобі, {ім'я:к}. Твій внесок у нашу боротьбу помітили як піхотинці, так і фельдмаршали.", ["en"] = "More Resource Crates", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [8299] = { [1] = "Перерізати лінії постачання Аратора", [2] = "Ліга Аратора не шкодує сил на відвоювання низини Араті. Вони, разом зі всіма расами Альянсу, зараз прямують в цей віддалений регіон, маючи намір розширити свої володіння за межі Опорного пункту. Ми повинні зупинити їх, і найкращий спосіб для цього — захопити їхні припаси.\n\n{ім'я:к}, ти можеш нам допомогти. Вирушай в низину Араті, яка відома своїми родючими копальнями, багатими землями та професійними майстрами. Візьми під контроль усі бази, які зможеш, виграй битву і повернись до мене з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його смертолову Мортісу в Молотобій.", [4] = "Що таке, {раса:к}? Ти {стать:приніс:принесла} ящик з ресурсами? Повернись в низину Араті, вбий паразитів з Альянсу та захопи їхні ресурси для Темної Леді!", [5] = "<Смертолов Мортіс посміхається>\n\nТи {стать:завдав:завдала} ще одного потужного удару нашим ворогам, {ім'я:к}. Завдяки тобі, низина Араті скоро буде захоплена Труїтелями.", ["en"] = "Cut Arathor Supply Lines", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8300] = { [1] = "Більше ящиків з ресурсами", [2] = "Ліга Аратора не шкодує сил на відвоювання низини Араті. Вони, разом зі всіма расами Альянсу, зараз прямують в цей віддалений регіон, маючи намір розширити свої володіння за межі Опорного пункту. Ми повинні зупинити їх, і найкращий спосіб для цього — захопити їхні припаси.\n\n{ім'я:к}, ти можеш нам допомогти. Вирушай в низину Араті, яка відома своїми родючими копальнями, багатими землями та професійними майстрами. Візьми під контроль усі бази, які зможеш, виграй битву і повернись до мене з ресурсами.", [3] = "Виграйте битву за низину Араті, отримайте ящик з ресурсами Араті та віднесіть його смертолову Мортісу в Молотобій.", [4] = "{ім'я:к}, твоє завдання лишається незмінним — повертайся в низину Араті, добудь більше ящиків з ресурсами та принеси їх мені.", [5] = "Чудово. Я негайно передам ці ресурси нашим квартирмейстерам, а начальству — подяку за твої дії.\n\nЩе раз дякую тобі, {ім'я:к}. Твій внесок у нашу боротьбу помітили як бугаї, так і воєводи.", ["en"] = "More Resource Crates", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [8301] = { [1] = "Шлях праведника", [2] = "Рід Ноздорму природно не довіряє нижчим расам. Хоч ти й {стать:зміг:змогла} довести мені, що маєш задатки {стать:героя:героїні}, прийшов час довести це моєму господарю.\n\nВул'Аші, Вул'Зора і Вул'Регаль кишать силітидами й становлять загрозу нашому існуванню. Вбий якомога більше силітидів з цих вуликів й принеси мені фрагменти їхніх панцирів. Коли ти збереш стільки панцирів, що не зможеш нести, повертайся до мене і я зміцню твою рішучість.", [3] = "Зберіть 200 фрагментів панцирів силітидів і віднесіть їх Барістольту.", [4] = "Їхня недовіра до смертних рас тягнеться з далекого минулого. Однак краще нехай вони самі розкажуть її тобі, коли прийде час.", [5] = "Ти не {стать:один, герою:одна, героїне}. Я дарую тобі можливість призначити інших, хто допоможе тобі подолати випробування. Якщо ти хочеш бути {стать:захисником:захисницею} свого народу, тобі знадобиться допомога.", ["en"] = "The Path of the Righteous", ["tasks"] = { ["Silithid Carapace Fragment"] = "фрагмент панцира силітида", ["Silithid Carapace Fragment (Provided)"] = "фрагмент панцира силітида (видано)" } },
    [8302] = { [1] = "Рука праведника", [2] = "Обирай собі заступників з розумом, {стать:смертний:смертна}. Кожного разу, коли ти успішно виконуєш завдання, ти можеш обрати собі нового заступника.\n\nВраховуючи це, скажу, що мені потрібно більше фрагментів панцирів. Не марнуй часу!", [3] = "Зберіть 200 фрагментів панцирів силітидів і віднесіть їх Барістольту.", [4] = "Можливо, одного дня ти керуватимеш Кенарійською цитаделлю.", [5] = "Молодець, {стать:герою:героїне}. Тепер ти маєш можливість призначити ще одного агента Ноздорму.", ["en"] = "The Hand of the Righteous", ["tasks"] = { ["Silithid Carapace Fragment"] = "фрагмент панцира силітида", ["Silithid Carapace Fragment (Provided)"] = "фрагмент панцира силітида (видано)" } },
    [8303] = { [1] = "Анахронос", [2] = "Час прийшов, {ім'я}.\n\nЯ маю попросити вибачення за те, що так довго тримав це в таємниці. Ворогів безліч, вони прямо у нас під носом. Прошу тебе, візьми цей фоліант, читай його і вчися. Прийми знання, які я дарую тобі та відшукай нашого господаря.", [3] = "Прямуйте в Танаріс та знайдіть Анахроноса в Печерах Часу.", [5] = "Ти — надія Калімдору, {ім'я}.", ["en"] = "Anachronos", ["tasks"] = { ["The War of the Shifting Sands"] = "Війна Мінливих Пісків" } },
    [8304] = { [1] = "Люба Наталія", [2] = "Моя люба Наталія зникла безвісти.\n\nЧесно кажучи, вона поводилася досить дивно останні тижні перед зникненням. Я неодноразово бачив, як вона розмовляла сама з собою, коли нікого не було поруч. Вона запевняла, що все гаразд і що необхідно продовжувати дослідження.\n\nВостаннє її бачили, коли вона прямувала в табір Бронзобородих на півдні.\n\nВ мене занадто мало солдат, {ім'я}. Я хочу, щоб ти {стать:пішов:пішла} в табір Бронзобородих й {стать:розпитав:розпитала} тих дворфів.", [3] = "Командир Мар'аліт з Кенарійської цитаделі, що в Силітус просить вас розпитати мешканців табору Бронзобородого, що на південь від Кенарійської цитаделі.\n\nЗібравши необхідну інформацію, поверніться до командира Мар'аліта.", [4] = "Не трать час марно, {ім'я}!", [5] = "<Командир Мар'аліт опускає голову в роздумах.>\n\nЖива вона чи мертва, я маю вчинити правильно. Її треба знайти. На жаль, я не маю права покинути заставу. Ти допоможеш мені ще раз, {ім'я}?", ["en"] = "Dearest Natalia", ["tasks"] = { ["Frankal Questioned"] = "Франкала допитали", ["Frankal Questioned (Provided)"] = "Франкала допитали (видано)", ["Frankal Questioned slain"] = "Франкала допитали: убито", ["Rutgar Questioned"] = "Рутгара допитали", ["Rutgar Questioned (Provided)"] = "Рутгара допитали (видано)", ["Rutgar Questioned slain"] = "Рутгара допитали: убито" } },
    [8305] = { [1] = "Давно забуті спогади", [2] = "У пустелі, на півдні Силітуса, біля священного бар'єру, є одна кришталева сльоза. Ця сльоза є символом великих втрат, яких ми зазнали під час Війни Мінливих Пісків. Знайди цю сльозу і зазирни у її глибини, щоб досягти просвітлення.", [3] = "Знайдіть кришталеву сльозу в Силітусі та зазирніть у її глибини.", [5] = "Ви відчуваєте сильний смуток, яким сповнений цей кристал. Сила його настільки потужна, що вам здається, ніби ви можете впасти й померти від горя.", ["en"] = "Long Forgotten Memories" },
    [8306] = { [1] = "В пащу божевілля", [2] = "Я хочу, щоб ти {стать:пішов:пішла} в Вул'Регаль і {стать:з'ясував:з'ясувала}, що сталося з моєю дорогою Наталією, {ім'я}. Це буде нелегке завдання, тож краще візьми з собою друзів. Перш ніж пірнути з головою в пащу божевілля, обов'язково поговори з дворфами. Можливо, вони зможуть дати тобі кілька порад щодо силітидів, що живуть в цьому вулику.\n\nІ ще дещо, {ім'я}, якщо вона справді втратила розум, як говорять... роби те, що {стать:повинен:повинна}.\n\n<Командир Мар'аліт відвертається від вас.>", [3] = "Командир Мар'аліт з Кенарійської цитаделв в Силітусі хоче, щоб ви знайшли його кохану Наталію. Зібрана вами інформація вказує на те, що пані Наталію Мар'аліт можна знайти на півдні, у Вул'Регалі.\n\nЗавітайте до дворфів у табір Бронзобородих, перш ніж вирушити до вулика. Можливо, у них знайдеться для вас додаткова робота чи порада.\n\nІ пам'ятай слова командира: \"Роби те, що {стать:повинен:повинна}...\"", [4] = "Наталія?", [5] = "<Командир Мар'аліт хапається за груди.>\n\nК'Тун? ЩО все це означає? Що за К'Тун? Як цей демон міг перетворити мою любу Наталію на монстра, якого ти {стать:описав:описала}?", ["en"] = "Into The Maw of Madness", ["tasks"] = { ["The Fate of Mistress Natalia Mar'alith"] = "Доля пані Наталії Мар'аліт", ["The Fate of Mistress Natalia Mar'alith (Provided)"] = "Доля пані Наталії Мар'аліт (видано)", ["The Fate of Mistress Natalia Mar'alith slain"] = "Доля пані Наталії Мар'аліт: убито" } },
    [8307] = { [1] = "Пустельна кулінарія", [2] = "Адаптуватися до життя в пустелі було, м'яко кажучи, непросто. Я сумую не лише за птахами та зеленню Аубердіна, але й за нормальною їжею. В цій пустці наш вибір їжі сильно обмежений. Я намагаюся вивчити пустельні трави, але їх мало.\n\nЯ бачила, як група Сутінкового Молота з табору на заході звідси полює на піщаних черв'яків. Але їхнє м'ясо таке гірке, що не уявляю, як вони роблять його смачним. Будь {стать:уважний:уважна}, як підеш до їхнього табору, і дай знати, якщо дізнаєшся щось.", [3] = "Знайдіть інформацію про приготування м'яса піщаного черв'яка в таборі Сутінкового Молота на захід від Кенарійської цитаделі.", [5] = "У цій книзі міститься кілька звичайних рецептів і кілька досить незвичних. Погортавши її, ви знаходите рецепт, у якому згадується м'ясо піщаного черв'яка.", ["en"] = "Desert Recipe" },
    [8308] = { [1] = "Загублений лист Бранна Бронзобородого", [2] = "Для тих, кому це може бути цікаво:\n\nЯкщо ви це читаєте, то я або мертвий, або скоро помру. Важко сказати. Більшість членів команди вже загинули.\n\nЯ знайшов інформацію про титана. Велика битва між ним і Старим Богом. Так, справжнім Старим Богом. Знайшов древній тунель, що веде в Ан'Кіраж. Йду по ньому.\n\nВіднесіть цей лист в мій старий табір. Переконайтеся, що моя мавпочка отримує достатньо їжі, води та обіймів.\n\n— Бранн Бронзобородий, дослідник екстремал\n\nP.S. Остерігайтеся божевільних нічних ельфів, що поклоняються Старому Богу.", [3] = "Віднесіть лист Бранна Бронзобородого в табір Бронзобородого, в південній частині Силітусу.", [4] = "Ой, леле.", [5] = "Що ж, це багато чого пояснює. Якщо ти коли-небудь знайдеш дорогу в Ан'Кіраж, подивись чи немає там старого Бранна. Боюся, він буде безсилий без своєї мавпи.", ["en"] = "Brann Bronzebeard's Lost Letter", ["tasks"] = { ["Brann Bronzebeard's Lost Letter"] = "загублений лист Бранна Бронзобородого", ["Brann Bronzebeard's Lost Letter (Provided)"] = "загублений лист Бранна Бронзобородого (видано)" } },
    [8309] = { [1] = "Гонитва за гліфами", [2] = "Після нашої першої вилазки до вуликів та божевілля майстрині Мар'аліт, з трьох вуликів почали лізти жуки! Мені здається, що їхня активність може бути пов'язана з гліфами, що вкривають ці дивні кристали.\n\nЯкщо ми отримаємо відтиски гліфів з цих кристалів, ми зможемо розібратися в цьому божевіллі.\n\nВізьми цей копіювальний набір та кількох приятелів і вирушай до тих вуликів, {ім'я:к}. Не повертайся, поки не отримаєш відтиски з кожного вулика.", [3] = "Рутґар Гліфотвор з табору Бронзобородого, що в Силітусі, хоче, щоб ви вирушили до Вул'Аші, Вул'Зори та Вул'Регаля і знайшли вкриті гліфами кристали у кожному з них.\n\nВикористовуйте копіювальний набір геолога, щоб зробити відтиски гліфів і поверніться з ними до Рутґара Гліфотвора.", [4] = "Якщо ти знайдеш у вулику божевільну нічну ельфійку, не забудь дати їй копняка під зад.", [5] = "Я не можу розібратися з цими символами. Ніколи не бачив нічого подібного! Сподіваюся, що дослідження Френкела допоможе розібратись в цьому.", ["en"] = "Glyph Chasing", ["tasks"] = { ["Geologist's Transcription Kit"] = "копіювальний набір геолога", ["Geologist's Transcription Kit (Provided)"] = "копіювальний набір геолога (видано)", ["Hive'Ashi Rubbing"] = "відтиск кристала Вул'Аші", ["Hive'Ashi Rubbing (Provided)"] = "відтиск кристала Вул'Аші (видано)", ["Hive'Regal Rubbing"] = "відтиск кристала Вул'Регаля", ["Hive'Regal Rubbing (Provided)"] = "відтиск кристала Вул'Регаля (видано)", ["Hive'Zora Rubbing"] = "відтиск кристала Вул'Зори", ["Hive'Zora Rubbing (Provided)"] = "відтиск кристала Вул'Зори (видано)" } },
    [8310] = { [1] = "Розшифровка", [2] = "Здається, я можу розробити еліксир, який дозволить нам розшифрувати записи мовою силітидів і кіражів! Що для цього потрібно? Радий, що ти {стать:запитав:запитала}! Мені потрібні мізки! Точніше, мені потрібні мізки кожного виду силітидів, що мешкають у вуликах. Принеси мені мізки і робота Рутґара не буде марною.", [3] = "Френкел Каменеміст з табору Бронзобородого, що в Силітусі, хоче, щоб ви знайшли мозок силітида Вул'Зори, мозок силітида Вул'Аші та мозок силітида Вул'Регаля. Поверніться до Френкела коли виконаєте завдання.", [4] = "Іди пограйся з мавпочкою, {стать:малий:мала}. В мене немає на це часу.", [5] = "Чудово! Не йди далеко, {стать:хлопче:дівча}. Нам може знадобитися твоя допомога з ще кількома завданнями.", ["en"] = "Breaking the Code", ["tasks"] = { ["Hive'Ashi Silithid Brain"] = "мозок силітида Вул'Аші", ["Hive'Ashi Silithid Brain (Provided)"] = "мозок силітида Вул'Аші (видано)", ["Hive'Regal Silithid Brain"] = "мозок силітида Вул'Регаля", ["Hive'Regal Silithid Brain (Provided)"] = "мозок силітида Вул'Регаля (видано)", ["Hive'Zora Silithid Brain"] = "мозок силітида Вул'Зори", ["Hive'Zora Silithid Brain (Provided)"] = "мозок силітида Вул'Зори (видано)" } },
    [8313] = { [1] = "Поділитись знанням", [2] = "Хоча рецепт приготування м'яса піщаних черв'яків цілком зрозумілий, у ньому згадуються трави та спеції, про які ви ніколи не чули. Можливо, Каландрат знає щось про рослини пустелі й зможе допомогти вам.", [3] = "Принесіть вирвану сторінку з рецептом до Каландрат в таверну у Кенарійській цитаделі.", [4] = "Ти {стать:знайшов:знайшла} рецепт? Сподіваюся, ти ним поділишся!", [5] = "Погляньмо...\n\nЗдається, все досить просто. Деякі трави називаються інакше, але не складно здогадатися. Давай-но я тобі покажу!", ["en"] = "Sharing the Knowledge", ["tasks"] = { ["Torn Recipe Page"] = "вирвана сторінка з рецептом", ["Torn Recipe Page (Provided)"] = "вирвана сторінка з рецептом (видано)" } },
    [8314] = { [1] = "Розгадка таємниці", [2] = "Ми на порозі прориву, {ім'я}! Знайдені тобою відтиски дозволили нам відтворити гліфи на цій кристалічній призмі. Очевидно, що за допомогою них кіражі та інші невідомі істоти передають повідомлення силітидам.\n\nНа жаль, це все, що ми змогли дізнатися з цих символів. Нам потрібно знайти спосіб розшифровки послань, схованих всередині кристалів.\n\nВіднеси цю вкриту гліфами кристалічну призму геологу Жартоламу в Кенарійську цитадель. Можливо, вона зможе допомогти.", [3] = "Рутґар Гліфотвор з табору Бронзобородого просить вас віднести вкриту гліфами кристалічну призму геологу Жартоламу в Кенарійську цитадель, що в Силітусі.", [4] = "Ой, лишенько! Що це у тебе, {ім'я}?", [5] = "Причина, через яку дворфи не змогли розшифрувати символи, полягає в тому, що тут немає чого розшифровувати. Щоб передати послання, зовнішній, рухомий шар призми, потрібно правильно вирівняти з внутрішніми позначками. Розумно...\n\nХоч ми й можемо перекласти ці дані, спершу потрібно зрозуміти код. На поверхні призми є лише одна підказка, і якщо відтиски були правильно зроблені — в мене погані новини.", ["en"] = "Unraveling the Mystery", ["tasks"] = { ["Glyphed Crystal Prism"] = "вкрита гліфами кристалічна призма", ["Glyphed Crystal Prism (Provided)"] = "вкрита гліфами кристалічна призма (видано)" } },
    [8315] = { [1] = "Поклик", [2] = "На гліфах проілюстровано зустріч кіразького емісара з трьома силітидами біля кісток великого дракона. Над ілюстрацією знаходиться, напевно, якийсь код. Цей код цілком може бути ключем для виклику емісара.\n\nЯ зроблю копію гліфів з послання, а тобі потрібно намалювати їх на піску біля кісток Ґраккаронда. Якщо я все правильно зрозуміла, властителі прийдуть, думаючи, що нові дані готові до передачі. Вбий їх і вступи в бій з емісаром. Ключ до кристалів у нього...", [3] = "Геолог Жартолам з Кенарійської цитаделі в Силітусі хоче, щоб ви добули механізм відкривання кристалів у кіразького емісара.\n\nВам потрібно віднести гліфи поклику до кісток Ґраккаронда, південніше від Кенарійської цитаделі й намалювати їх на піску. Якщо з'явиться кіразький емісар, вбийте його і заберіть механізм відкривання кристалів. Якщо впораєтесь — поверніться до геолога Жартолама.\n\nЗберіть армію для виконання цього завдання, {ім'я}!", [4] = "Ти маєш вибрати вдалий момент та завдати удару!", [5] = "{ім'я}, я тримаю в руках 20 000 років історії!", ["en"] = "The Calling", ["tasks"] = { ["Crystal Unlocking Mechanism"] = "механізм відкривання кристалів", ["Crystal Unlocking Mechanism (Provided)"] = "механізм відкривання кристалів (видано)" } },
    [8316] = { [1] = "Військові обладунки", [5] = "Наближається війна, {ім'я}, а разом з нею прийдуть й невимовні жахіття. Ти {стать:зробив:зробила} все, що {стать:міг:могла} і за це отримаєш нагороду.\n\nЯкщо це... пророцтво коли-небудь здійсниться...\n\n<Геолог Жартолам блідніє.>\n\nМи можемо забути про майбутнє.\n\nЦі обладунки можуть знадобитися тобі в прийдешній війні.", ["en"] = "Armaments of War" },
    [8317] = { [1] = "Допомога на кухні", [2] = "Цей рецепт точно стане в пригоді. Мені пора братися за роботу, щоб приготувати на сьогодні копчені пустельні пельмені. Мені б не завадила твоя допомога на кухні, це буде варте твого часу.", [3] = "Каландрат з Кенарійської цитаделі просить вас принести їй 10 копчених пустельних пельменів.", [4] = "Є успіх з пельменями?", [5] = "Чудово! Ти мене {стать:врятував:врятувала}. Ці пельмені дуже смачні. Не очікувала такої смакоти від Сутінкового Молота.", ["en"] = "Kitchen Assistance", ["tasks"] = { ["Smoked Desert Dumplings"] = "копчені пустельні пельмені", ["Smoked Desert Dumplings (Provided)"] = "копчені пустельні пельмені (видано)" } },
    [8318] = { [1] = "Таємне спілкування", [2] = "Деякі прихильники Сутінкового Молота носять з собою папірці з написаною на них тарабарщиною. Принеси мені пачку таких папірців, {клас:к}.\n\nЯ не можу зрозуміти, що означають ці тексти, але справа не в цьому! Ці папірці — це спосіб таємного спілкування між членами секти. Чим більше текстів ми вилучаємо з обігу, тим менше в них залишається можливостей спілкування!", [3] = "Принесіть 10 зашифрованих текстів Сутінкового Молота Бору Дикій Гриві в Кенарійську цитадель.", [4] = "Ти {стать:приніс:принесла} мені тексти?", [5] = "Чудово! Я сховаю їх якомога далі, можливо, вони знадобляться пізніше.", ["en"] = "Secret Communication", ["tasks"] = { ["Encrypted Twilight Text"] = "зашифрований текст Сутінкового Молота", ["Encrypted Twilight Text (Provided)"] = "зашифрований текст Сутінкового Молота (видано)" } },
    [83188] = { [1] = "Потойбічне скарб", ["en"] = "Otherworldly Treasure" },
    [83189] = { [1] = "Потойбічне скарб", ["en"] = "Otherworldly Treasure" },
    [8319] = { [1] = "Зашифровані тексти Сутінкового Молота", [4] = "Продовжуй приносити мені тексти. Незабаром ми витіснимо Сутінковий Молот з Силітусу.", [5] = "Відмінна робота! Я замовлю за тебе слівце.", ["en"] = "Encrypted Twilight Texts", ["tasks"] = { ["Encrypted Twilight Text"] = "зашифрований текст Сутінкового Молота", ["Encrypted Twilight Text (Provided)"] = "зашифрований текст Сутінкового Молота (видано)" } },
    [83190] = { [1] = "Потойбічне скарб", ["en"] = "Otherworldly Treasure" },
    [83191] = { [1] = "Потойбічне скарб", ["en"] = "Otherworldly Treasure" },
    [83192] = { [1] = "Потойбічне скарб", ["en"] = "Otherworldly Treasure" },
    [832] = { [1] = "Палаючі тіні", [2] = "<Слова плавно перетікають з підвіски у вашу свідомість>\n\nҐазз'уз?\n\nҐазз'уз… відповідай!\n\nПро те, що ти знайшов у Скелі Черепа вже відомо. Готуйся до нападу!\n\nҐазз'уз, я вимагаю, щоб ти відгукнувся! Відповідай, або я повідомлю про все Нііру Вогняному Лезу, а він-то вже тебе точно не пожаліє.\n\nЗ ним тобі краще не гратися...\n\n…Ґазз'уз, ти там…?", [3] = "Принесіть це око Нііру Вогняному Лезу.", [4] = "Ти маєш розповісти про щось життєво важливе. Я відчуваю це у твоєму погляді.", [5] = "<Розглядає око палаючої тіні>\n\nЦікаво. Почутий голос назвав моє ім'я? Я давно завоював репутацію мисливця на ворогів нашого воєвождя, але… дивно, що мене так визначили. Ще дивніше те, що у когось з послідовників культу Палаючого Леза ім'я, настільки подібне до мого.\n\nЯ маю вивчити цю підвіску. Вивчити та обміркувати значення цього послання.\n\nДякую тобі за знахідку, {Ім'я}. Ти {стать:зробив:зробила} велику послугу своєму народові.", ["en"] = "Burning Shadows", ["tasks"] = { ["Eye of Burning Shadow"] = "око палаючої тіні", ["Eye of Burning Shadow (Provided)"] = "око палаючої тіні (видано)" } },
    [8320] = { [1] = "Сутінкові геолорди", [2] = "Сутінковий Молот, божевільна секта, яка руйнує все на своєму шляху, встановила табори в Силітусі й проводить ритуали вдень і вночі. Поки що невідомо, що вони задумали, але ми вважаємо, що вони якось пов'язані з розкиданими по пустелі червоними пульсуючими кристалами.\n\nХоча, можливо, одного дня ми розгадаємо їхню таємницю, спочатку ми повинні розібратися з загрозою, яку несе безпосередньо Сутінковий Молот. Вирушай до їхнього табору на захід й знайди сутінкових геолордів. Вони командують цими гадюками, тому потрібно завдавати удару по них!", [3] = "Вбийте 10 сутінкових геолордів та поверніться до Гуума Дикої Гриви в Кенарійську цитадель.", [4] = "Іди в пустелю і відшукай сутінкових геолордів, {ім'я}. Повертайся тільки тоді, коли вб'єш їх.", [5] = "Ти добре {стать:виконав:виконала} завдання, {ім'я}. Завдяки вбивству сутінкових геолордів, ми завдали потужного удару по культу. Будемо сподіватися, що ми затримали їхні плани...", ["en"] = "Twilight Geolords", ["tasks"] = { ["Twilight Geolord"] = "сутінковий геолорд", ["Twilight Geolord slain"] = "сутінковий геолорд: убито" } },
    [8321] = { [1] = "Вірал Негідний", [2] = "Ми виявили ще одну базу Сутінкового Молота. Вона називається печерою Сутінків, і захована в північно-східній частині Силітуса. У цій печері мешкає їхній лідер, Вірал Негідний — він наступний, кого ти маєш перемогти. Коли зробиш це, принеси мені його перстень-печатку.\n\nЩасти тобі, {ім'я}. Печера Сутінків справді жахлива.", [3] = "Принесіть перстень-печатку Вірала до Гуума Дикої Гриви в Кенарійську цитадель.", [4] = "{ім'я}, ти {стать:переміг:перемогла} Вірала Негідного? Ти {стать:приніс:принесла} його перстень-печатку?", [5] = "Ти {стать:зробив:зробила} це! Вірал мертвий! Це означає, що Сутінковий Молот не зможе здійснити свої задуми в Силітусі. Їх там ще багато залишилось, але завдяки удару, який ти {стать:завдав:завдала} сьогодні, вони ще довго не зможуть оговтатись.", ["en"] = "Vyral the Vile", ["tasks"] = { ["Vyral's Signet Ring"] = "перстень-печатка Вірала", ["Vyral's Signet Ring (Provided)"] = "перстень-печатка Вірала (видано)" } },
    [8322] = { [1] = "Зіпсовані яйця", [2] = "Люди Південнобережжя обожнюють свій ель, особливо той, що подають в таверні Південнобережжя. Зараз, коли настав хаос Повечір'я святих, ми можемо використати це, щоб зіпсувати їхню останню партію напою на довгі тижні, а може й місяці!\n\nВізьми ці зіпсовані яйця і кинь їх у головну бочку з елем в таверні Південнобережжя. Твоя присутність сама по собі спричинить гармидер, тому будь {стать:готовим:готовою} захищатись!\n\nПісля того, як ти допоможеш Південнобережжю відчути смак, який вони не скоро забудуть, повертайся до мене на свято!", [3] = "Киньте зіпсовані яйця у головну бочку з елем у таверні Південнобережжя.", [4] = "Бочка наповнена елем.", [5] = "Пробившись у таверну, ви опускаєте зіпсовані яйця в бочку. Повітря сповнюється огидним смородом.", ["en"] = "Rotten Eggs", ["tasks"] = { ["Rotten Eggs"] = "зіпсовані яйця", ["Rotten Eggs (Provided)"] = "зіпсовані яйця (видано)" } },
    [8323] = { [1] = "Правовірні", [2] = "Тепер, коли у мене є Сутінковий словник, я хочу попросити тебе про невелику послугу.\n\nМоя колишня організація щомісяця випускає ретельно зашифровані публікації.\n\nЯкщо вони досягнуть якогось прогресу в моїх пошуках або якщо вони припинять мене шукати, це буде опубліковано в \"Правовірному\".\n\nХоча ця інформація, безумовно, цінна для мене, публікації містять й іншу корисну інформацію, якою я зможу поділитися з тобою. Принеси мені будь-які зашифровані тексти, які зможеш знайти у членів Сутінкового Молота.", [3] = "Відлюдник Ортелл хоче, щоб ви принесли йому 10 зашифрованих текстів Сутінкового Молота.", [4] = "Ти {стать:знайшов:знайшла} якісь зашифровані тексти? Я дуже хочу прочитати свіжий випуск \"Правовірного\".", [5] = "Чудово! Я почну розшифровку прямо зараз. Якщо знайду щось цікаве — я дам тобі знати.", ["en"] = "True Believers", ["tasks"] = { ["Encrypted Twilight Text"] = "зашифрований текст Сутінкового Молота", ["Encrypted Twilight Text (Provided)"] = "зашифрований текст Сутінкового Молота (видано)" } },
    [8324] = { [1] = "Не втрачаючи віри", [4] = "{стать:Знайшов:Знайшла} нові зашифровані тексти? Принеси мені цілу купу, розшифровка займає багато часу.", [5] = "Ідеально! Не можу дочекатися, щоб прочитати їх. Будь ласка, принось сюди нові зашифровані тексти, якщо знаходитимеш їх.", ["en"] = "Still Believing", ["tasks"] = { ["Encrypted Twilight Text"] = "зашифрований текст Сутінкового Молота", ["Encrypted Twilight Text (Provided)"] = "зашифрований текст Сутінкового Молота (видано)" } },
    [8331] = { [1] = "Аврель Золотолиста", [2] = "{ім'я}, ми сподівалися, що Сутінковий Молот призупинить свою діяльність у Силітусі... але, на жаль, ми помилялися. Продовжуючи набіги на табори сектантів, ми дізналися, що Молот контролює ще темніша сила — Рада Безодні. Для цього вони використовують таємничі вітрові камені, розкидані по таборах Сутінкового Молота. Твоє наступне завдання, {ім'я} — піти проти Ради Безодні.\n\nПоговори з майстринею Аврель Золотолистою у східній частині Кенарійської цитаделі. Її вміння знадобляться для нашого наступного кроку.", [3] = "Поговоріть з Аврель Золотолистою в Кенарійській цитаделі.", [5] = "Доброго дня, {ім'я}. Мені сказали, що ти будеш протистояти Раді Безодні? Якщо це правда, тоді слухай уважно...", ["en"] = "Aurel Goldleaf" },
    [8332] = { [1] = "Герцоги Ради", [2] = "Ми вважаємо, що можна використати вітровий камінь, щоб влаштувати засідку на герцога Ради Безодні. Однак, для цього необхідно зв'язатися через нього з Радою і переконати їх, що ти {стать:лідер:лідерка} середнього рангу Сутінкового Молота.\n\nДля цієї справи потрібна копія сутінкового медальйона служіння. Я можу створити медальйон, але мені потрібен великий блискучий осколок і талісмани, що носять храмовники Безодні.\n\nПринеси мені їх, а я зроблю все інше.", [3] = "Принесіть 1 великий блискучий осколок і 3 талісмани безодні та віддайте їх Аврель Золотолистій в Кенарійській цитаделі.", [4] = "Ти {стать:приніс:принесла} осколок і талісмани, {ім'я}? Вони мені знадобляться, щоб створити сутінковий медальйон служіння.", [5] = "Дуже добре. Я якраз працюю над медальйоном — завдяки цим останнім інгредієнтам я закінчу за кілька хвилин...\n\nОсь і все. Тримай медальйон, {ім'я}.\n\nТи {стать:повинен:повинна} надягнути його, коли активуєш один з вітрових каменів Сутінкового Молота. Одягни його разом з рештою сутінкових атрибутів, і рада Безодні вважатиме тебе {стать:одним:одною} зі своїх підлеглих.", ["en"] = "Dukes of the Council", ["tasks"] = { ["Abyssal Crest"] = "талісман безодні", ["Abyssal Crest (Provided)"] = "талісман безодні (видано)", ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)" } },
    [8333] = { [1] = "Медальйон служіння", [4] = "Якщо тобі потрібен ще один сутінковий медальйон служіння, я буду радий допомогти. Однак мені потрібен ще один блискучий осколок і кілька талісманів безодні...", [5] = "Ось, тримай, {ім'я}. Ще один сутінковий медальйон служіння. Користуйся на здоров'я і щасти тобі в боротьбі з Радою Безодні!", ["en"] = "Medallion of Station", ["tasks"] = { ["Abyssal Crest"] = "талісман безодні", ["Abyssal Crest (Provided)"] = "талісман безодні (видано)", ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)" } },
    [834] = { [1] = "Вітри у пустелі", [2] = "Я Резлак, представник компанії Ґазлоу. Бос послав мене сюди, у Дуротар, допомогти оркам. І все начебто йде нормально, але каравани... Я не можу забезпечити їх належний захист! А це дуже ускладнює мою роботу, уловлюєш?\n\nОстаннє відвантаження — а мені обіцяли, що воно прийде без проблем! — було викрадене пиловійними гарпіями з… як там його… каньйону Бритвовітру?\n\nМені потрібні ці припаси, бо я так ніколи нічого не дороблю до кінця! Йди вздовж великого каньону на південь і знайдеш ущелину, що йде із заходу на схід...", [3] = "Добудьте 5 мішків з припасами і поверніть їх Резлаку, що знаходиться біля Орґріммара.", [4] = "Не зрозумій мене неправильно, я незрівнянний у тому, що роблю, але це вже смішно! Мені що, піщані замки будувати?", [5] = "Гей, а це вже щось! Ти {стать:повернув:повернула} нам наші припаси. Чудово. Повернусь до роботи одразу як знайду когось, хто дотягне ці мішки за мене.", ["en"] = "Winds in the Desert", ["tasks"] = { ["Sack of Supplies"] = "мішок з припасами", ["Sack of Supplies (Provided)"] = "мішок з припасами (видано)" } },
    [8341] = { [1] = "Лорди Ради", [2] = "Викликати лордів Ради Безодні можна лише за допомогою великих вітрових каменів і лише високопоставлені члени Сутінкової Ради можуть говорити з ними. Але... Я знайшов спосіб поліпшити твоє маскування й обдурити лордів Безодні!\n\nДля маскування потрібен перстень влади, який носять лише найвищі члени культу. Я зроблю його для тебе, якщо ти принесеш мені великі блискучі осколки та персні безодні.", [3] = "Принесіть 5 великих блискучих осколків і 3 персні безодні до Аврель Золотолистої в Кенарійську цитадель.", [4] = "Ти {стать:приніс:принесла} осколки та персні, {ім'я}? Вони потрібні мені, щоб створити перстень влади.", [5] = "Дякую. Зачекай хвилинку і я зроблю перстень для тебе...\n\nОсь він. Тепер ти {стать:готовий:готова}.\n\nОбов'язково одягни цей перстень разом з медальйоном служіння та рештою сутінкових атрибутів, коли активуєш великий вітровий камінь. Якщо зробиш все це, Рада Безодні вважатиме тебе {стать:одним:однією} зі своїх слуг. Тоді, можливо, тобі вдасться заманити їх в пастку!", ["en"] = "Lords of the Council", ["tasks"] = { ["Abyssal Signet"] = "перстень безодні", ["Abyssal Signet (Provided)"] = "перстень безодні (видано)", ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)" } },
    [8342] = { [1] = "Сутінковий перстень влади", [4] = "{ім'я}, якщо ти плануєш знову вступити в бій проти Вищої Ради Безодні, тобі знадобиться ще один сутінковий перстень влади. Принеси мені більше осколків та перснів, і я зроблю його для тебе.", [5] = "О, бачу, ти впевнено стоїш на своєму. Мало хто вистоїть проти цієї диявольської ради!\n\nОсь твій перстень, {ім'я}. Нехай буде воля твоя тверда і хай супроводжує тебе удача.", ["en"] = "Twilight Ring of Lordship", ["tasks"] = { ["Abyssal Signet"] = "перстень безодні", ["Abyssal Signet (Provided)"] = "перстень безодні (видано)", ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)" } },
    [8343] = { [1] = "Відкриття Золотолистої", [2] = "{ім'я}, Аврель Золотолиста вважає, що знайшла спосіб викликати й перемогти правителя ради Безодні! Це завдання небезпечне, але ти {стать:заслужив:заслужила} велику шану всього Кенарійського Кола. Ми впевнені, що якщо хтось і може це зробити, то тільки ти.\n\nНехай щастить, {ім'я}. Поговори з Аврель, коли будеш {стать:готовий:готова} виконати це завдання.", [3] = "Поговоріть з Аврель Золотолистою в Кенарійській цитаделі.", [5] = "Те, що сказав Гуум — правда. Здається, я знаю, як викликати лорда Ради Безодні! Слухай уважно...", ["en"] = "Goldleaf's Discovery" },
    [8348] = { [1] = "Персні герцогів", [2] = "Гуум каже, що ти {стать:з'ясував:з'ясувала}, як викликати герцогів Безодні! Це велике досягнення.\n\nА знаєш, що ще було б неабияким досягненням? Добряче розгромити одного з них. Це б справило незабутнє враження на їхніх підлеглих. Принесіть перстень герцога, як доказ про виконане завдання.", [3] = "Принесіть перстень безодні Бору Дикій Гриві в Кенарійську цитадель.", [4] = "Як все пройшло з герцогом Безодні? Було важко?", [5] = "Я зрозумів, що ти {стать:міцний:міцна} {клас:н} в ту ж хвилину, коли ти {стать:зайшов:зайшла} в Кенарійську цитадель. Так тримати!", ["en"] = "Signet of the Dukes", ["tasks"] = { ["Abyssal Signet"] = "перстень безодні", ["Abyssal Signet (Provided)"] = "перстень безодні (видано)" } },
    [8349] = { [1] = "Бор Дика Грива", [2] = "Тепер, коли ти маєш медальйон і можеш викликати герцога Безодні, поговори з Бором Дикою Гривою. Він дасть тобі завдання для боротьби з радою Безодні.\n\nЩасти тобі, {ім'я}. І якщо тобі ще коли-небудь знадобляться медальйони, повертайся до мене.", [3] = "Поговоріть з Бором Дикою Гривою в Кенарійській цитаделі.", [5] = "Радий знову тебе бачити, {клас:к}! То ти {стать:дістав:дістала} медальйон? Добре, він знадобиться тобі для наступного завдання...", ["en"] = "Bor Wildmane" },
    [835] = { [1] = "Захист маршрутів", [2] = "Ґазлоу якось мені сказав: \"Резлак. Є дещо, що ти маєш знати у своєму житті - якщо ти хочеш, щоб щось було зроблено добре, зроби це сам.\"\n\nЯ не можу змиритись з втратою усіх наших караванів, тому вирішив взяти справу у свої руки. Сухощільний яр лежить у східній частині каньйону Бритвовітру. Якщо ми переб'ємо там усіх гарпій, то зможемо захистити маршрут.\n\nЗвичайно, є ще дещо, що мені казав Ґазлоу: \"Для кожної роботи можна знайти підходящу людину та відповідну ціну\". Це я до чого... Допоможеш мені, {Ім'я}?", [3] = "Убийте 12 пиловійних дикунок і 8 пиловійних штормовідьом біля Сухощільного яру за дорученням Резлака.", [4] = "Важко повірити, але мій бос Ґазлоу завжди знає всьому ціну. \"Ніколи не бійся робити перший крок. І роби то з розмахом\", - казав він.\n\nГарпії не припинять надокучати нам і знову нападатимуть на каравани, допоки ми щось не зробимо, егеж?", [5] = "Що ж, я можу зітхнути з полегшенням, знаючи, що гарпії більше не докучатимуть нашим караванам з вантажами. І це дуже вчасно. Я чув, що із наступною доставкою мені надішлють кілька веселих іграшок!\n\nТи досить непогано знаєшся на своїй справі, {Ім'я}, тобі слід навідатись до мого боса у Брашпилі. Впевнений, він підбере для тебе цікаву робітку.\n\nОу, і не хвилюйся, я не забув про оплату твоїх послуг.", ["en"] = "Securing the Lines", ["tasks"] = { ["Dustwind Savage"] = "пиловійна дикунка", ["Dustwind Savage slain"] = "пиловійна дикунка: убито", ["Dustwind Storm Witch"] = "пиловійна штормовідьма", ["Dustwind Storm Witch slain"] = "пиловійна штормовідьма: убито" } },
    [8351] = { [1] = "Бор хоче поговорити", [2] = "Тепер, коли ти можеш замаскуватися в керівного члена Сутінкової Ради, я впевнена, що Бор Дика Грива захоче поговорити з тобою. Іди до нього й приготуйся до дуже складної місії...", [3] = "Поговоріть з Бором Дикою Гривою в Кенарійській цитаделі.", [5] = "Так, саме так, {ім'я}. Я маю дуже важке завдання...", ["en"] = "Bor Wishes to Speak" },
    [8352] = { [1] = "Скіпетр Ради", [2] = "Ми з Гуумом щойно говорили про тебе. Він сказав, що ти майже {стать:готовий:готова} показати свої сили в битві з лордом Безодні!\n\nМаю попередити, що це дуже небезпечно. Тобі краще взяти з собою підмогу. І я не говорю про одного чи двох друзів, я маю на увазі першокласний, боєздатний бойовий загін. Якщо твої друзі такі ж здібні, як і ти, у тебе є шанс перемогти його!\n\nЯкщо ти це зробиш — а мені, як завжди, потрібні будуть докази — я дам тобі справді вартісну нагороду.", [3] = "Принесіть скіпетр безодні Бору Дикій Гриві в Кенарійську цитадель.", [4] = "То як все пройшло? Я б зробив що завгодно, аби покинути свій пост і самому поборотися з цим лордом!", [5] = "Ти... ти {стать:зробив:зробила} це! Ти {стать:впорався:впоралась}, {ім'я}! На! Візьми це. Це найбільша скриня, яка у нас була і я наповнив її найкращими предметами, які зміг знайти.", ["en"] = "Scepter of the Council", ["tasks"] = { ["Abyssal Scepter"] = "скіпетр безодні", ["Abyssal Scepter (Provided)"] = "скіпетр безодні (видано)" } },
    [836] = { [1] = "Врятувати OOX-09/ВЗ!", [2] = "Голос гнома знову тріщить з робота:\n\n\"Мені потрібно перемістити OOX-09/ВЗ на відкрите, безпечне місце, щоб він міг почати тривалу процедуру зльоту. Він має вбудовану систему маскування, але мені потрібен час, щоб зробити її знову працездатною. Мені потрібно, щоб ти {стать:супроводжував:супроводжувала} робота з його поточного місцеперебування до, скажімо, узбережжя за Оглядовими кручами! Це має бути ідеальне місце, достатньо просторе, щоб підготувати апарат до польоту!\"\n\n\"Проведи його до узбережжя, а потім приходь поговорити зі мною в Грабіжну Бухту! Оґлторп Обриднус — кінець зв'язку!\"", [3] = "Проведіть OOX-09/ВЗ на узбережжя за Оглядовими кручами, а потім звітуйте Оґлторпу Обриднусу в Грабіжній Бухті.", [5] = "О, ТИ - {стать:великий рятівник:велика рятівниця} OOX-09/ВЗ! У мене просто слів немає, настільки я вдячний за твою допомогу! Моя серія автономних роботів потребує вдосконалень, але завдяки тобі, я заощадив безліч часу на відновлення і купу золота на дорогі деталі!\n\nБудь ласка, обери будь-який з цих предметів. Ще раз дякую за твою щедру допомогу, мої роботи і я у тебе в боргу!", ["en"] = "Rescue OOX-09/HL!", ["tasks"] = { ["Escort OOX-09/HL to the shoreline beyond Overlook Cliff"] = "Супровід OOX-09/HL до берегової лінії за скелею Оверлук" } },
    [8361] = { [1] = "Зв'язок з Безодньою", [2] = "Ми бачили, як сектанти з Сутінкового Молота проводять ритуали для виклику могутніх елементалів. Ми не знаємо, чи це ті істоти, яким поклоняються сектанти, чи вони виступають посередниками перед ще більш могутніми силами. Одне можна сказати точно: вони отримують накази від цих елементалів.\n\nЯ хочу, щоб ти {стать:зв'язався:зв'язалася} з храмовником Безодні й {стать:дав:дала} йому добрячого прочухана! Ніщо так не дезорганізує військо, як порушення субординації. Принеси докази виконаного завдання.", [3] = "Бор Дика Грива з Кенарійської цитаделі в Силітусі хоче, щоб ви знищили храмовника Безодні й принесли йому талісман безодні в доказ про виконання завдання.", [4] = "Ти {стать:виконав:виконала} моє завдання?", [5] = "Ха! Ти {стать:зробив:зробила} це, {ім'я}! Сутінковий Молот скоро буде знищено!", ["en"] = "Abyssal Contacts", ["tasks"] = { ["Abyssal Crest"] = "талісман безодні", ["Abyssal Crest (Provided)"] = "талісман безодні (видано)" } },
    [8362] = { [1] = "Талісмани безодні", [4] = "Ти {стать:довів:довела}, що можеш постояти за себе в бою, {ім'я}. Не можна ослабляти тиск на Сутінковий Молот. Бийся з іншими храмовниками Безодні, за це ти отримаєш речі, які ми з Гуумом зібрали в бою.", [5] = "Ти молодець! Тепер храмовників стало менше, а відповідно у нас менше турбот.\n\nТримай, {ім'я}. Сподіваюся, ти знайдеш щось корисне для себе.", ["en"] = "Abyssal Crests", ["tasks"] = { ["Abyssal Crest"] = "талісман безодні", ["Abyssal Crest (Provided)"] = "талісман безодні (видано)" } },
    [8363] = { [1] = "Персні безодні", [4] = "Ти {стать:довів:довела}, що в тебе вдосталь сили, щоб знищити герцога Безодні, {ім'я}. Я завжди готовий гарно заплатити за хороші наміри. Принеси мені більше перснів і отримаєш винагороду.", [5] = "Чудово, {ім'я}! Здобувши перемогу над цими герцогами, ти зупиниш Сутінковий Молот на деякий час. Як я й обіцяв, ось твоя нагорода. Це найкраще, що ми з Гуумом знайшли.", ["en"] = "Abyssal Signets", ["tasks"] = { ["Abyssal Signet"] = "перстень безодні", ["Abyssal Signet (Provided)"] = "перстень безодні (видано)" } },
    [8364] = { [1] = "Скіпетри безодні", [4] = "Ти справді {стать:перевершив:перевершила} усі мої очікування, {ім'я}. Ти можеш перемогти таких супротивників, перед боєм з якими, ми б з Гуумом сто раз подумали.\n\nЄдине, що я можу робити зараз, це винагороджувати тебе за успіхи в боротьбі проти Сутінкового Молота та їхніх властителів.\n\nПринеси мені більше скіпетрів безодні і я постараюсь гідно тобі віддячити.", [5] = "Я знав, що ти впораєшся, {ім'я}! Тримай свою нагороду.", ["en"] = "Abyssal Scepters", ["tasks"] = { ["Abyssal Scepter"] = "скіпетр безодні", ["Abyssal Scepter (Provided)"] = "скіпетр безодні (видано)" } },
    [8365] = { [1] = "Піратські капелюхи", [2] = "То це тебе прислав картель? Думаю, ти мені підійдеш. Слухай уважно, {клас:к}. Я ти звісно знаєш, я постачаю модний одяг для еліти Азероту. Королям та королевам, вождям та... ну, як там Орда називає своїх королев? Одним словом, усі носять те, що я вибираю, і це стильно. І, що найприємніше, вони платять за це шалені гроші.\n\nОтож, ось що я хочу зробити. Вирушай до бухти Загубленого Вітрила і роздобудь якнайбільше піратських капелюхів. Як думаєш, зможеш впоратися з цим завданням?", [3] = "Гордовита Модистка просить вас зібрати 20 капелюхів піратів Південних морів і принести їх їй у порт Паровиманювання в Танарісі.", [4] = "Ти {стать:приніс:принесла} усі 20 капелюхів? Я тобі не вірю, покажи. І всі вони мають бути в бездоганному стані!", [5] = "О, ти просто чудо, хоча тобі знадобилося більше часу, ніж я думала. Ця партія повинна мені принести чимало грошей, залишається лише почистити їх та прикрасити. Я завжди вважала, що за хорошу роботу має бути гідна винагорода. Ось, візьми. І раджу тобі витратити частину на гарну ванну, {стать:солоденький:солоденька}.", ["en"] = "Pirate Hats Ahoy!", ["tasks"] = { ["Southsea Pirate Hat"] = "капелюх пірата Південних морів", ["Southsea Pirate Hat (Provided)"] = "капелюх пірата Південних морів (видано)" } },
    [8366] = { [1] = "Погром піратів Південних морів", [2] = "Аррр! Вони вимагають від мене неможливого!\n\nКартель Паровиманювання хоче, щоб я провчив піратів Південних морів. Мені що, розірватися?! Я повинен підтримувати тут порядок.\n\nСхоже, що пірати забули, що картель платить їм за захист. Тож я хочу доручити тобі піти туди та показати їм, де раки зимують.\n\nТи знайдеш їх в бухті Загубленого Вітрила, яка знаходиться неподалік звідси, на півдні. Дякую, {ім'я}, я твій боржник!", [3] = "Начальник служби безпеки Трюмосвист з порту Паровиманювання в Танарісі просить вас вбити 10 піратів Південних морів, 10 флібустьєрів Південних морів, 10 портових робітників Південних морів і 10 шибайголів Південних морів.", [4] = "Так швидко {стать:повернувся:повернулася}? Сподіваюсь, ти добряче {стать:провчив:провчила} цих громил.", [5] = "{ім'я}! Ти просто {стать:герой:героїня}!!!\n\nТепер, коли ти {стать:розправився:розправилась} з цими покидьками з Південних морів, картель відчепиться від мене. Добре, що я можу дати тобі в нагороду? Як щодо кількох монет, та одної з цих речей на твій вибір?", ["en"] = "Southsea Shakedown", ["tasks"] = { ["Southsea Dock Worker"] = "портовий робітник Південних морів", ["Southsea Dock Worker slain"] = "портовий робітник Південних морів: убито", ["Southsea Freebooter"] = "флібустьєр Південних морів", ["Southsea Freebooter slain"] = "флібустьєр Південних морів: убито", ["Southsea Pirate"] = "пірат Південних морів", ["Southsea Pirate slain"] = "пірат Південних морів: убито", ["Southsea Swashbuckler"] = "шибайголова Південних морів", ["Southsea Swashbuckler slain"] = "шибайголова Південних морів: убито" } },
    [8368] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Є новини з тіснини Пісні Війни, {ім'я:к}?", [5] = "Чудово! Ти {стать:довів:довела} свою гідність, захищаючи наші інтереси в тіснині Пісні Війни! Нехай звістки про твою честь рознесуться по всіх наших землях.", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8369] = { [1] = "Загарбники Альтерацької долини", [2] = "Слухай сюди, {ім'я:к}. Що б тобі не говорили про битву, що точиться в Альтерацькій долині, є лише одна правда — експедиція Бурешпиля вдерлася на землі Морозних Вовків. Якщо ми дозволимо Альянсу безкарно вдиратися на землі Орди, я повішу сокиру і проживу решту життя в ганьбі. Іди та вижени загарбників!", [3] = "Принесіть 3 відзнаки честі Альтерацької долини війноносцю Орди поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} якісь новини із земель Морозних Вовків? Як просувається битва за Альтерацьку долину?", [5] = "Ти {стать:проявив:проявила} надзвичайну хоробрість, захищаючи наші землі в Альтерацькій долині! Я доповім своєму начальству про твої подвиги.", ["en"] = "Invaders of Alterac Valley", ["tasks"] = { ["Alterac Valley Mark of Honor"] = "відзнака честі Альтерацької долини", ["Alterac Valley Mark of Honor (Provided)"] = "відзнака честі Альтерацької долини (видано)" } },
    [8370] = { [1] = "Завоювання низини Араті", [2] = "Наш конфлікт з Альянсом переріс у справжню війну. На цьому етапі жодна зі сторін більше не надає і не очікує приводів для вступу в бій.\n\nБитва за низину Араті — це битва за ресурси, все просто і зрозуміло. Або Альянс отримає ресурси й використає їх проти нас, або ми отримаємо їх і спорядимо наші війська. Допоможи Труїтелям завоювати ресурси, які нам потрібні, {ім'я:к}!", [3] = "Принесіть 3 відзнаки честі низини Араті війноносцю Орди поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з Араті, {клас:к}?", [5] = "Захоплення ресурсів в низині Араті — це дуже важливо! Молодець, ти чудово {стать:впорався:впоралась}, {ім'я:к}.", ["en"] = "Conquering Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8372] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з фронту, {ім'я:к}?", [5] = "Молодець, {ім'я:к}! Ти добре {стать:послужив:послужила} Альянсу.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8373] = { [1] = "Сила сосни", [2] = "Те, що мені найбільше не подобається на Повечір'я святих, це смердючі бомби, які відречені скидають на Південнобережжя. Хто знав, що святкування визволення повинно супроводжуватися такими смердючими неприємностями?\n\nПід час Повечір'я святих використовуй цей очищувач, щоб видалити будь-які смердючі бомби, які Орда може скинути на нас. Він використовує силу соснового запаху, щоб боротися зі смородом.\n\nЗроби свій внесок у збереження чистоти Південнобережжя, і я дам тобі кілька ласощів Повечір'я святих, від яких ти, без сумніву, будеш в захваті. Згода?", [3] = "Використовуйте очищувач смердючих бомб, щоб прибрати всі смердючі бомби, які були скинуті на Південнобережжя. Поверніться до сержанта Гартмана в Південнобережжя, коли закінчите.", [4] = "Ці кляті відречені... мало того, що вони невмерлі, так вони ще й показилися і почали спричиняти проблеми в МОЄМУ селищі!", [5] = "Ух, тут вже майже нічим не пахне. Майже.\n\nЗавдяки тобі, {ім'я}, Південнобережжя зможе пережити ще одне Повечір'я святих. Ось твої ласощі та моя щира подяка! Якщо у тебе закінчаться цукерки, в Залізогарті є гномка, на ім'я Катріна Блискозірка — вона може продати тобі ще. Здається, вона продає їх лише під час Повечір'я святих.", ["en"] = "The Power of Pine", ["tasks"] = { ["Clean up a stink bomb that's been dropped on Southshore!"] = "Приберіть смердючу бомбу, яку скинули на Саутберег!" } },
    [8374] = { [1] = "Відвоювання низини Араті", [2] = "Перемога у війні — це дещо більше, ніж просто перехитрити свого супротивника та виграти битву. Перемога часто зводиться до того, щоб просто виробляти більше ресурсів, ніж твій ворог.\n\nА ресурсів у низині Араті — хоч відбавляй. Головне для нас — це захопити їх першими.\n\nЯкщо Альянс переможе, це означатиме, що наші війська отримають більше мечів і списів. Якщо ж переможе Орда, ці мечі та списи все одно будуть виготовлені, але вони вже будуть спрямовані на нас! Настав час допомогти Альянсу в низині Араті, {ім'я:к}.", [3] = "Принесіть 3 відзнаки честі низини Араті бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Розказуй, які новини з фронту?", [5] = "Молодець, солдате! Продовжуй у тому ж дусі, і ми змусимо Орду тікати аж до самого Орґріммару.", ["en"] = "Claiming Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8375] = { [1] = "Пам'ятайте Альтерацьку долину!", [2] = "Не вводь себе в оману, {ім'я:к}. Орда таки права, кажучи, що Альтерацька долина - це територія Морозних Вовків.\n\nРозумієш, експедиція Ураганного верхогір'я прибула як мирні відвідувачі цієї місцевості, щоб шукати руди та реліквії. Реакція Морозних Вовків була найвищим актом жорстокості та варварства, якого зазнавав Альянс.\n\nНе забуваймо ж ніколи сміливих дворфів, які загинули через цю підло неоголошену атаку. Тепер іди, {клас:к}, зіграй свою роль у битві за Альтерацьку долину. За Альянс!", [3] = "Принесіть 3 відзнаки честі Альтерацької долини бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Які новини ти {стать:приніс:принесла}, {ім'я:к}?", [5] = "Ти {стать:зробив:зробила} свою справу, {ім'я:к}. Альянс не може дозволити варварствам Орди залишатися безкарними!", ["en"] = "Remember Alterac Valley!", ["tasks"] = { ["Alterac Valley Mark of Honor"] = "відзнака честі Альтерацької долини", ["Alterac Valley Mark of Honor (Provided)"] = "відзнака честі Альтерацької долини (видано)" } },
    [8376] = { [1] = "Військові обладунки", [5] = "Наближається війна, {ім'я}, а разом з нею прийдуть й невимовні жахіття. Ти {стать:зробив:зробила} все, що {стать:міг:могла} і за це отримаєш нагороду.\n\nЯкщо це... пророцтво коли-небудь здійсниться...\n\n<Геолог Жартолам блідніє.>\n\nМи можемо забути про майбутнє.\n\nЦі обладунки можуть знадобитися тобі в прийдешній війні.", ["en"] = "Armaments of War" },
    [8377] = { [1] = "Військові обладунки", [5] = "Наближається війна, {ім'я}, а разом з нею прийдуть й невимовні жахіття. Ти {стать:зробив:зробила} все, що {стать:міг:могла} і за це отримаєш нагороду.\n\nЯкщо це... пророцтво коли-небудь здійсниться...\n\n<Геолог Жартолам блідніє.>\n\nМи можемо забути про майбутнє.\n\nЦі обладунки можуть знадобитися тобі в прийдешній війні.", ["en"] = "Armaments of War" },
    [8378] = { [1] = "Військові обладунки", [5] = "Наближається війна, {ім'я}, а разом з нею прийдуть й невимовні жахіття. Ти {стать:зробив:зробила} все, що {стать:міг:могла} і за це отримаєш нагороду.\n\nЯкщо це... пророцтво коли-небудь здійсниться...\n\n<Геолог Жартолам блідніє.>\n\nМи можемо забути про майбутнє.\n\nЦі обладунки можуть знадобитися тобі в прийдешній війні.", ["en"] = "Armaments of War" },
    [8379] = { [1] = "Військові обладунки", [5] = "Наближається війна, {ім'я}, а разом з нею прийдуть й невимовні жахіття. Ти {стать:зробив:зробила} все, що {стать:міг:могла} і за це отримаєш нагороду.\n\nЯкщо це... пророцтво коли-небудь здійсниться...\n\n<Геолог Жартолам блідніє.>\n\nМи можемо забути про майбутнє.\n\nЦі обладунки можуть знадобитися тобі в прийдешній війні.", ["en"] = "Armaments of War" },
    [8380] = { [1] = "Військові обладунки", [5] = "Наближається війна, {ім'я}, а разом з нею прийдуть й невимовні жахіття. Ти {стать:зробив:зробила} все, що {стать:міг:могла} і за це отримаєш нагороду.\n\nЯкщо це... пророцтво коли-небудь здійсниться...\n\n<Геолог Жартолам блідніє.>\n\nМи можемо забути про майбутнє.\n\nЦі обладунки можуть знадобитися тобі в прийдешній війні.", ["en"] = "Armaments of War" },
    [8381] = { [1] = "Військові обладунки", [5] = "Наближається війна, {ім'я}, а разом з нею прийдуть й невимовні жахіття. Ти {стать:зробив:зробила} все, що {стать:міг:могла} і за це отримаєш нагороду.\n\nЯкщо це... пророцтво коли-небудь здійсниться...\n\n<Геолог Жартолам блідніє.>\n\nМи можемо забути про майбутнє.\n\nЦі обладунки можуть знадобитися тобі в прийдешній війні.", ["en"] = "Armaments of War" },
    [8382] = { [1] = "Військові обладунки", [5] = "Наближається війна, {ім'я}, а разом з нею прийдуть й невимовні жахіття. Ти {стать:зробив:зробила} все, що {стать:міг:могла} і за це отримаєш нагороду.\n\nЯкщо це... пророцтво коли-небудь здійсниться...\n\n<Геолог Жартолам блідніє.>\n\nМи можемо забути про майбутнє.\n\nЦі обладунки можуть знадобитися тобі в прийдешній війні.", ["en"] = "Armaments of War" },
    [8383] = { [1] = "Пам'ятайте Альтерацьку долину!", [2] = "Битва за Альтерак у розпалі, {клас:к}! Чи {стать:зробив:зробила} ти свій внесок в перемогу, {ім'я:к}?", [3] = "Принесіть 3 відзнаки честі Альтерацької долини бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Битва за Альтерак у розпалі, {клас:к}! Чи {стать:зробив:зробила} ти свій внесок в перемогу, {ім'я:к}?", [5] = "Ти продовжуєш приносити честь Альянсові, {ім'я:к}. Орда буде скоро розгромлена, якщо ми й надалі докладатимемо таких зусиль.", ["en"] = "Remember Alterac Valley!", ["tasks"] = { ["Alterac Valley Mark of Honor"] = "відзнака честі Альтерацької долини", ["Alterac Valley Mark of Honor (Provided)"] = "відзнака честі Альтерацької долини (видано)" } },
    [8384] = { [1] = "Відвоювання низини Араті", [4] = "{ім'я:к}, через війну з Ордою в нас швидко закінчуються припаси. Дуже важливо зберегти контроль над низиною Араті, щоб потік ресурсів не припинявся! Ти вже {стать:зробив:зробила} свій внесок у боротьбу за неї?", [5] = "Відмінна робота, {клас:к}! Завдяки тобі Альянс отримає потрібні ресурси.", ["en"] = "Claiming Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8386] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Не забувай, що боротьба за тіснину Пісні Війни — це більше, ніж просто захист дерев. Йдеться про збереження бар'єра між Ясенедолом та Степами. Є новини з поля бою, {ім'я:к}?", [5] = "Чудова робота, {ім'я:к}. Завдяки тобі наш захист Ясенедолу протримається ще деякий час.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8387] = { [1] = "Загарбники Альтерацької долини", [2] = "Битва за Альтерак у розпалі! Ти мусиш повернутися в Альтерацьку долину та ще раз вигнати загарбників із території Морозних Вовків, {ім'я:к}!", [3] = "Принесіть 3 відзнаки честі Альтерацької долини війноносцю Орди поряд з входом на поле бою.", [4] = "Битва за Альтерак у розпалі! Ти мусиш повернутися в Альтерацьку долину та ще раз вигнати загарбників із території Морозних Вовків, {ім'я:к}!", [5] = "Гарна робота, {ім'я:к}! Тобі варто собою пишатися. Загарбники Альянсу повинні бути вигнані з Альтераку!", ["en"] = "Invaders of Alterac Valley", ["tasks"] = { ["Alterac Valley Mark of Honor"] = "відзнака честі Альтерацької долини", ["Alterac Valley Mark of Honor (Provided)"] = "відзнака честі Альтерацької долини (видано)" } },
    [8389] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Битва в тіснині Пісні Війни триває, {ім'я:к}. Зроби свій внесок, допоможи вигнати Срібнокрилих стражів з наших земель!", [5] = "Молодчина, {клас:к}! Завдяки таким, як ти, Орда утримає тіснину Пісні Війни!", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [839] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [8390] = { [1] = "Завоювання низини Араті", [4] = "Війна проти покидьків з Альянсу потребує ресурсів, {ім'я:к}! Ми не можемо допустити, щоб наші запаси вичерпалися посеред битви. Зроби все можливе, щоб низина Араті залишилася в наших руках!", [5] = "Відмінна робота, {ім'я:к}! Поки низина Араті залишається під нашим контролем, в нас буде вдосталь припасів для підтримки війська.", ["en"] = "Conquering Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8391] = { [1] = "Відвоювання низини Араті", [4] = "{ім'я:к}, через війну з Ордою в нас швидко закінчуються припаси. Дуже важливо зберегти контроль над низиною Араті, щоб потік ресурсів не припинявся! Ти вже {стать:зробив:зробила} свій внесок у боротьбу за неї?", [5] = "Відмінна робота, {клас:к}! Завдяки тобі Альянс отримає потрібні ресурси.", ["en"] = "Claiming Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8392] = { [1] = "Відвоювання низини Араті", [2] = "Перемога у війні — це дещо більше, ніж просто перехитрити свого супротивника та виграти битву. Перемога часто зводиться до того, щоб просто виробляти більше ресурсів, ніж твій ворог.\n\nА ресурсів у низині Араті — хоч відбавляй. Головне для нас — це захопити їх першими.\n\nЯкщо Альянс переможе, це означатиме, що наші війська отримають більше мечів і списів. Якщо ж переможе Орда, ці мечі та списи все одно будуть виготовлені, але вони вже будуть спрямовані на нас! Настав час допомогти Альянсу в низині Араті, {ім'я:к}.", [3] = "Принесіть 3 відзнаки честі низини Араті бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "{ім'я:к}, через війну з Ордою в нас швидко закінчуються припаси. Дуже важливо зберегти контроль над низиною Араті, щоб потік ресурсів не припинявся! Ти вже {стать:зробив:зробила} свій внесок у боротьбу за неї?", [5] = "Відмінна робота, {клас:к}! Завдяки тобі Альянс отримає потрібні ресурси.", ["en"] = "Claiming Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8393] = { [1] = "Відвоювання низини Араті", [2] = "Перемога у війні — це дещо більше, ніж просто перехитрити свого супротивника та виграти битву. Перемога часто зводиться до того, щоб просто виробляти більше ресурсів, ніж твій ворог.\n\nА ресурсів у низині Араті — хоч відбавляй. Головне для нас — це захопити їх першими.\n\nЯкщо Альянс переможе, це означатиме, що наші війська отримають більше мечів і списів. Якщо ж переможе Орда, ці мечі та списи все одно будуть виготовлені, але вони вже будуть спрямовані на нас! Настав час допомогти Альянсу в низині Араті, {ім'я:к}.", [3] = "Принесіть 3 відзнаки честі низини Араті бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Розказуй, які новини з фронту?", [5] = "Молодець, солдате! Продовжуй у тому ж дусі, і ми змусимо Орду тікати аж до самого Орґріммару.", ["en"] = "Claiming Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [83934] = { [1] = "Покажи мені гроші!", [2] = "Гей! Ти схожий на \"винахідливого шукача пригод\", тож, можливо, ти зможеш мені допомогти. Бачиш, ми з братами приїхали із Загублених Островів, щоб розпочати новий бізнес, але зіткнулися з піратами, які вкрали наші стартові гроші. Люди, які фінансують нашу операцію вдома, я б не назвав розуміючими, тому ми зробимо це вартим твоїх зусиль, якщо зможемо знайти хоча б одну монету та повернути її. Це не звичайне золото, але ти маєш знати це, коли побачиш.", [3] = "Принесіть Заплямовану Підкопну Реальну до Пікс Ксізікс у Буті-Бей.", [4] = "Що ти мені приніс, {раса}?", [5] = "Гей! Чудово!\n\nЯкщо знайдеш ще наші монети, приходь до мене. У нас великий вибір товарів, і ми будемо раді обміняти їх!", ["en"] = "Show Me The Money!" },
    [8394] = { [1] = "Відвоювання низини Араті", [2] = "Перемога у війні — це дещо більше, ніж просто перехитрити свого супротивника та виграти битву. Перемога часто зводиться до того, щоб просто виробляти більше ресурсів, ніж твій ворог.\n\nА ресурсів у низині Араті — хоч відбавляй. Головне для нас — це захопити їх першими.\n\nЯкщо Альянс переможе, це означатиме, що наші війська отримають більше мечів і списів. Якщо ж переможе Орда, ці мечі та списи все одно будуть виготовлені, але вони вже будуть спрямовані на нас! Настав час допомогти Альянсу в низині Араті, {ім'я:к}.", [3] = "Принесіть 3 відзнаки честі низини Араті бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Розказуй, які новини з фронту?", [5] = "Молодець, солдате! Продовжуй у тому ж дусі, і ми змусимо Орду тікати аж до самого Орґріммару.", ["en"] = "Claiming Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8395] = { [1] = "Відвоювання низини Араті", [2] = "Перемога у війні — це дещо більше, ніж просто перехитрити свого супротивника та виграти битву. Перемога часто зводиться до того, щоб просто виробляти більше ресурсів, ніж твій ворог.\n\nА ресурсів у низині Араті — хоч відбавляй. Головне для нас — це захопити їх першими.\n\nЯкщо Альянс переможе, це означатиме, що наші війська отримають більше мечів і списів. Якщо ж переможе Орда, ці мечі та списи все одно будуть виготовлені, але вони вже будуть спрямовані на нас! Настав час допомогти Альянсу в низині Араті, {ім'я:к}.", [3] = "Принесіть 3 відзнаки честі низини Араті бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Розказуй, які новини з фронту?", [5] = "Молодець, солдате! Продовжуй у тому ж дусі, і ми змусимо Орду тікати аж до самого Орґріммару.", ["en"] = "Claiming Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8396] = { [1] = "Відвоювання низини Араті", [2] = "Перемога у війні — це дещо більше, ніж просто перехитрити свого супротивника та виграти битву. Перемога часто зводиться до того, щоб просто виробляти більше ресурсів, ніж твій ворог.\n\nА ресурсів у низині Араті — хоч відбавляй. Головне для нас — це захопити їх першими.\n\nЯкщо Альянс переможе, це означатиме, що наші війська отримають більше мечів і списів. Якщо ж переможе Орда, ці мечі та списи все одно будуть виготовлені, але вони вже будуть спрямовані на нас! Настав час допомогти Альянсу в низині Араті, {ім'я:к}.", [3] = "Принесіть 3 відзнаки честі низини Араті бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Розказуй, які новини з фронту?", [5] = "Молодець, солдате! Продовжуй у тому ж дусі, і ми змусимо Орду тікати аж до самого Орґріммару.", ["en"] = "Claiming Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8397] = { [1] = "Відвоювання низини Араті", [4] = "{ім'я:к}, через війну з Ордою в нас швидко закінчуються припаси. Дуже важливо зберегти контроль над низиною Араті, щоб потік ресурсів не припинявся! Ти вже {стать:зробив:зробила} свій внесок у боротьбу за неї?", [5] = "Відмінна робота, {клас:к}! Завдяки тобі Альянс отримає потрібні ресурси.", ["en"] = "Claiming Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8398] = { [1] = "Відвоювання низини Араті", [2] = "Перемога у війні — це дещо більше, ніж просто перехитрити свого супротивника та виграти битву. Перемога часто зводиться до того, щоб просто виробляти більше ресурсів, ніж твій ворог.\n\nА ресурсів у низині Араті — хоч відбавляй. Головне для нас — це захопити їх першими.\n\nЯкщо Альянс переможе, це означатиме, що наші війська отримають більше мечів і списів. Якщо ж переможе Орда, ці мечі та списи все одно будуть виготовлені, але вони вже будуть спрямовані на нас! Настав час допомогти Альянсу в низині Араті, {ім'я:к}.", [3] = "Принесіть 3 відзнаки честі низини Араті бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "{ім'я:к}, через війну з Ордою в нас швидко закінчуються припаси. Дуже важливо зберегти контроль над низиною Араті, щоб потік ресурсів не припинявся! Ти вже {стать:зробив:зробила} свій внесок у боротьбу за неї?", [5] = "Відмінна робота, {клас:к}! Завдяки тобі Альянс отримає потрібні ресурси.", ["en"] = "Claiming Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8399] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з фронту, {ім'я:к}?", [5] = "Чудова робота, {ім'я:к}. Завдяки тобі наш захист Ясенедолу протримається ще деякий час.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8400] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з фронту, {ім'я:к}?", [5] = "Молодець, {ім'я:к}! Ти добре {стать:послужив:послужила} Альянсу.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8401] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов Срібнокрилих до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою. Зроби свій внесок у боротьбу з авангардом Пісні Війни! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з фронту, {ім'я:к}?", [5] = "Молодець, {ім'я:к}! Ти добре {стать:послужив:послужила} Альянсу.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [84011] = { [1] = "Більше Зоряного Лотоса", [2] = "Нам все ще потрібно більше Зоряного Лотоса, щоб відвернути Нашестя Кошмарів. Пройдіть через Смарагдовий Портал у Серадані та принесіть мені трохи.", [3] = "Зберіть 10 Зоряних Лотосів під час Вторгнень Кошмарів у Внутрішні землі та поверніться до польового капітана Корліана.", [4] = "У тебе є Зоряний Лотос?", [5] = "Чудово! Дякую. Ваші послуги запам'ятаються.", ["en"] = "More Star Lotus" },
    [84012] = { [1] = "Ще зоресрібної руди", [2] = "Нам все ще потрібно більше руди Зоряного срібла, щоб відвернути Нашестя Кошмарів. Пройдіть через Смарагдовий Портал у Серадані та принесіть мені трохи.", [3] = "Зберіть 10 руди Зоряного срібла під час Вторгнень Кошмарів у Внутрішні землі та поверніться до польового капітана Корліана.", [4] = "У тебе є руда Зоряного срібла?", [5] = "Чудово! Дякую. Ваші послуги запам'ятаються.", ["en"] = "More Starsilver Ore" },
    [84013] = { [1] = "Більше зоряних мушель", [2] = "Нам все ще потрібно більше Зоряних Панцирів, щоб відвернути Нашестя Кошмарів. Пройдіть через Смарагдовий Портал у Серадані та принесіть мені трохи.", [3] = "Зберіть 10 Зоряних панцирів під час Вторгнень Кошмарів у Внутрішні землі та поверніться до польового капітана Корліана.", [4] = "У тебе є Зоряні мушлі?", [5] = "Чудово! Дякую. Ваші послуги запам'ятаються.", ["en"] = "More Starshells" },
    [84014] = { [1] = "Більше місячного кореня", [2] = "Нам все ще потрібно більше Місячного Коріння, щоб відвернути Нашестя Кошмарів. Пройдіть через Смарагдовий Портал у Гілці Снів і принесіть мені трохи.", [3] = "Зберіть 10 Місячних коренів під час Набігів Кошмарів Фералас та поверніться до польового капітана Аруннела.", [4] = "У тебе є Місячний корінь?", [5] = "Чудово! Дякую. Ваші послуги запам'ятаються.", ["en"] = "More Moonroot" },
    [84015] = { [1] = "Більше великих місячних каменів", [2] = "Нам все ще потрібно більше Великих Місячних Каменів, щоб відвернути Нашестя Кошмарів. Пройдіть через Смарагдовий Портал у Гілці Снів і принесіть мені трохи.", [3] = "Зберіть 10 Великих Місячних Каменів під час Набігів Кошмарів Фераласу та поверніться до Польового Капітана Аруннела.", [4] = "У вас є Великі Місячні Камені?", [5] = "Чудово! Дякую. Ваші послуги запам'ятаються.", ["en"] = "More Greater Moonstones" },
    [84016] = { [1] = "Більше луски Місячного Дракона", [2] = "Нам все ще потрібно більше Луски Місячного Дракона, щоб відвернути Нашестя Кошмарів. Пройдіть через Смарагдовий Портал у Гілці Снів і принесіть мені трохи.", [3] = "Зберіть 10 лусочок місячного дракона в Кошмарних вторгненнях Фераласа та поверніться до польового капітана Аруннела.", [4] = "У тебе є Луска Місячного Дракона?", [5] = "Чудово! Дякую. Ваші послуги запам'ятаються.", ["en"] = "More Moondragon Scales" },
    [8402] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з фронту, {ім'я:к}?", [5] = "Молодець, {ім'я:к}! Ти добре {стать:послужив:послужила} Альянсу.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8403] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з фронту, {ім'я:к}?", [5] = "Молодець, {ім'я:к}! Ти добре {стать:послужив:послужила} Альянсу.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8407] = { [1] = "Бій за тіснину Пісні Війни", [2] = "Срібнокрилі стражі воюють з кланом Пісні Війни через руйнування, які орки завдають лісу. Утім, ми захищаємо ліс не лише через любов до природи.\n\nЦей ліс є стратегічним рубежем, захищеним від широкомасштабного наступу. Без нього Астранаар не протримався б і дня, і наші землі були б захоплені Ордою.\n\nЗроби свій внесок у боротьбу з авангардом Пісні Війни, {ім'я:к}! За Альянс!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни бригадному генералові Альянсу поряд з входом на поле бою.", [4] = "Не забувай, що боротьба за тіснину Пісні Війни — це більше, ніж просто захист дерев. Йдеться про збереження бар'єра між Ясенедолом та Степами. Є новини з поля бою, {ім'я:к}?", [5] = "Чудова робота, {ім'я:к}. Завдяки тобі наш захист Ясенедолу протримається ще деякий час.", ["en"] = "Fight for Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8409] = { [1] = "Зіпсовані бочки", [2] = "Яйця успішно поміщені в бочку. Майбутні партії елю з таверни Південнобережжя будуть зіпсовані!\n\nТепер вам слід повернутися до Янки Темноклич на фестиваль Плетеного чоловічка в Тірісфальське перелісся та повідомити про ваш успіх.", [3] = "Поверніться до Янки Темноклич на фестиваль Плетеного чоловічка в Тірісфальському переліссі.", [5] = "Ах, тобі вдалось! Ти {стать:проявив:проявила} справжній дух Повечір'я святих — дух ВІДРЕЧЕНИХ!\n\n<Янка сміється й потирає руки.>\n\nЯ насолоджуюся тим, що Південнобережжя тепер має ласувати зіпсованим елем або обійтися без нього! Що ж до тебе — бери ці ласощі. Впевнена, ти знайдеш їм гарне застосування!", ["en"] = "Ruined Kegs" },
    [841] = { [1] = "Ще одне джерело енергії?", [2] = "Дай-но я вгадаю — ти не {стать:встиг:встигла} завершити свій страшний задум, згубний для всесвіту. Ні, ще краще... ти випадково {стать:впустив:впустила} його в пісок! У будь-якому разі я можу продати тобі ще одне джерело енергії. Проте, цього разу, це коштуватиме тобі десять, так, ДЕСЯТЬ бурдюків з водою Пустелебродів.\n\nЧаси зараз важкі, {ім'я}, і джерела енергії не ростуть на деревах! Хм, а що, якби росли? Можливо, ми могли б ЗРОБИТИ дерево джерел енергії...", [3] = "Принесіть 10 бурдюків з водою Пустелебродів головному інженеру Трюмосвисту в Пристроблях, щоб отримати ще одне джерело енергії.", [4] = "Ну що, ти {стать:дістав:дістала} десять бурдюків з водою?", [5] = "Добре, ось ще одне джерело енергії. Я наполегливо рекомендую тобі цього разу використати його належним чином, якщо тільки ти не хочеш збирати ще десять бурдюків з водою.", ["en"] = "Another Power Source?", ["tasks"] = { ["Wastewander Water Pouch"] = "бурдюк з водою Пустелебродів", ["Wastewander Water Pouch (Provided)"] = "бурдюк з водою Пустелебродів (видано)" } },
    [8410] = { [1] = "Опанування стихій", [2] = "Бат'рах Вітрогляд шукає шаманів на кшталт тебе. Принеси йому зразок кожної зі стихій, щоб довести свою майстерність.\n\nЩоб знайти Бат'раха, вирушай до річки на схід від Тарренського Млину. Йди вздовж річки на північ, поки не натрапиш на руїни, в яких мешкає Бат'рах.", [3] = "Принесіть первородні повітря, вогонь, землю та воду Бат'раху Вітрогляду.", [4] = "Що це в тебе, {клас:к}?", [5] = "Чудово, {стать:друже:подруго}. Тепер поговорим.", ["en"] = "Elemental Mastery", ["tasks"] = { ["Elemental Air"] = "первородне повітря", ["Elemental Air (Provided)"] = "первородне повітря (видано)", ["Elemental Earth"] = "первородна земля", ["Elemental Earth (Provided)"] = "первородна земля (видано)", ["Elemental Fire"] = "первородний вогонь", ["Elemental Fire (Provided)"] = "первородний вогонь (видано)", ["Elemental Water"] = "первородна вода", ["Elemental Water (Provided)"] = "первородна вода (видано)" } },
    [8412] = { [1] = "Тотем духів", [2] = "Тутешні духи стихій мене не люблять.\n\nТи знаєш про тотеми більше, чим хто-небудь інший, і мені треба тотем духів, який би мене захищав. У нас вже є стихії, тепер нам треба шось ближче до природи. Більш первісне.\n\nВ Західних Зачумлених землях можна вбити добути кігті ведмедів і очі пауків. Стерв'ятники їдять й тих, і других, тож можеш пошукать в їхніх шлунках.", [3] = "Принесіть частини тотема духів до Бат'раха Вітрогляда.", [4] = "Духи знають, шо роблять, і вони хочуть вбити мене! Надіюсь, ти {стать:приніс:принесла} частини тотему.", [5] = "Чудово, {стать:друже:подруго}! Спробуєм....", ["en"] = "Spirit Totem", ["tasks"] = { ["Bloodshot Spider Eye"] = "налите кров'ю павуче око", ["Bloodshot Spider Eye (Provided)"] = "налите кров'ю павуче око (видано)", ["Thick Black Claw"] = "товстий чорний кіготь", ["Thick Black Claw (Provided)"] = "товстий чорний кіготь (видано)" } },
    [84124] = { [1] = "Спадщина доблесті", [2] = "Примарний чемпіон поступається і рухається до вівтаря.", [3] = "Повернення до Вівтаря Шанування", [5] = "На вівтарі, який ти вшанував, велична дворучна сокира із золота та чорного кольорів лежить поруч із томом легенд про поле бою.", ["en"] = "Legacy of Valor" },
    [8413] = { [1] = "Вуду", [2] = "Тотема духів недостатньо. Нам треба магія вуду, шоб змусить його працювать як треба.\n\nТролі в Затонулому храмі мають пір'я, насичене магією вуду. Йди туди і вбий Ґешера, Міджана, Золо, Гукку, Зул'Лора та Лоро. Тоді нам хватить магії для справжнього тотема духів.", [3] = "Принесіть пір'я вуду до Бат'раха Вітрогляда.", [4] = "І де пір'я, {стать:друже:подруго}?", [5] = "Пора цьому тролю гарно відпочить! Тотем духів нагляне за мною.\n\nТи довго {стать:збирав:збирала} всякі речі. Може, хочеш шось за всі свої клопоти?", ["en"] = "Da Voodoo", ["tasks"] = { ["Amber Voodoo Feather"] = "бурштинове пір'я вуду", ["Amber Voodoo Feather (Provided)"] = "бурштинове пір'я вуду (видано)", ["Blue Voodoo Feather"] = "блакитне пір'я вуду", ["Blue Voodoo Feather (Provided)"] = "блакитне пір'я вуду (видано)", ["Green Voodoo Feather"] = "зелене пір'я вуду", ["Green Voodoo Feather (Provided)"] = "зелене пір'я вуду (видано)" } },
    [84135] = { [1] = "Пляжний бот", [2] = "На березі, напівзагублений у післяобідніх бризках, лежить дивний металевий пристрій. Він схожий на якийсь робот, але ви ніколи раніше не бачили нічого подібного. Ви помічаєте на його боці етикетку з написом «Власність D.E.L.T.A.: Альянс глибоководних досліджень та технологій зрідження». Ви також помічаєте невеликий відсік, який, можливо, зможете відкрити.", [3] = "Використайте камінь або щось подібне, щоб змістити частини механізму.", [5] = "Використовуючи свою зброю та польові навички, ви звільняєте відсік, відкриваючи всередині ампулу зі світною рідиною.", ["en"] = "Beach Bot" },
    [84136] = { [1] = "Володар Звірів Місячної Поляни", [2] = "Поки я стежу за Ван Амбургом, ти міг би відвідати мою стару подругу. Бантеазо зараз у Мунґлейді, де вона вивчає поведінку тварин разом з друїдами, щоб удосконалити дресирування для компаньйонів. Вона також раніше билася з Ван Амбургом і, можливо, має деякі підказки. Передай їй привіт від мене!\n\nЯк тільки ти закінчиш, ми знову зустрінемося у Зимоключі, де я планую прослідкувати деякі сліди. У мене є старий табір на північних пагорбах, де ми можемо поговорити приватно.", [3] = "Вирушайте до села Найтхейвен у Мунґлейді, на Калімдорі. Знайдіть троля Бантеазо, мисливця, і попросіть її розповісти про володіння звірами.", [5] = "Ти кажеш, що Естеленн привіталася? Дивно, я не бачив цього альянсового флітержука з того часу, як ми востаннє обмінювалися стрілами в Тернистій Долині... ну, як би там не було, це нейтральна територія. Якщо вона тебе до мене послала, то ти ж тут, щоб поговорити про тварин, га?", ["en"] = "The Beast Master of Moonglade" },
    [84137] = { [1] = "Механічний роман", [2] = "Ви задаєтеся питанням, чому цей робот розбився тут, і для чого потрібна ця рідина. Можливо, ви зможете використати її, щоб дістатися до сусідніх островів і нафтової платформи, які, здається, пов'язані з цією таємничою організацією. Якщо є щось, що ви знаєте напевно, так це те, що чарівні зілля мають досить хороший смак.", [3] = "Знайдіть застосування для прискорювача керованої плавучості\n\nНаданий предмет:", [5] = "Дійшовши до нафтової платформи, ви помічаєте чоловіка в лабораторному халаті, який бавиться з роботами. Він помічає вас і кричить, все ще бавлячись з елементами керування: «Фантастика! Ви якраз вчасно. Я вас чекав. Це випили моє чудове зілля, чи не так? Я доктор Юргенс, і в мене для вас пропозиція».", ["en"] = "Mechanical Romance", ["tasks"] = { ["Guided Buoyancy Accelerant"] = "Прискорювач плавучості, що керується" } },
    [84138] = { [1] = "Морозні подарунки", [2] = "Я головний інженер, засновник і головний технік Альянсу глибоководних досліджень і зрідження. Я майже завершив свій останній експеримент і мені потрібна ваша допомога! Я працюю над спеціальним пристроєм для геолокації вимірів, багатих на ресурси. Щоб завершити мою конструкцію, мені потрібно дещо повернути: книгу таємничих формул, яку я позичив своїй старій колезі Нумі, яка продовжує свою роботу у Зимоключа. Принеси мені книгу, і я щедро тебе винагороджу!", [3] = "Поясніть ситуацію з книгою колезі доктора Юргенса, Нумі, у Зимоключа.", [5] = "Себастьяну це потрібно? Він справжній хлопець. Ти даремно гаєш час, просячи про книгу. Я поки що не відмовляюся від неї і не скажу тобі, де вона знаходиться. Але, можливо, ми зможемо домовитися.", ["en"] = "Frosty Favors" },
    [8414] = { [1] = "Боротьба зі злом", [2] = "Вітаю, {клас:к}. Таким лицарям, як ви, завжди раді в цих спустошених краях.\n\nТвоя священна сила знадобиться нам в боротьбі з тутешніми невмерлими. Ти маєш зібрати якомога більше каменів Скари та принести їх верховному жерцю Тель'данісу. Ти знайдеш його на варті могили Утера на пагорбі Скорботи, неподалік звідси.\n\nТи не зможеш збирати камені Скари без жетона Сріблястого Світанку, тож поговори з офіцеркою Чистосердною, якщо в тебе його ще немає.", [3] = "Зберіть 20 каменів послідовників Скари та принесіть їх верховному жрецю Тель'данісу в Західні Зачумлені землі.", [4] = "З яким злом ти {стать:прийшов:прийшла} до мене?", [5] = "Очищати камені Скари небезпечно — це приверне увагу невмерлих з усіх околиць. Але твоя віра у Світло сильна, {ім'я:к}, тож, поки ти поруч, ми можемо не боятись.", ["en"] = "Dispelling Evil", ["tasks"] = { ["Minion's Scourgestone"] = "камінь посіпаки Скари", ["Minion's Scourgestone (Provided)"] = "камінь посіпаки Скари (видано)" } },
    [84146] = { [1] = "Червона сумка Блюз", [2] = "Те, що тобі потрібно, надійно заховано, і я можу лише сподіватися, що те саме можна сказати і про те, що шукаю я. У мене була червона сумка з деякими цінними екзотичними речовинами, які я використовую для електрооптики. Але я загубив її в аварії дирижабля над Палаючими Степами! Сумка все ще може бути там, але через орків, огрів та браконьєрів мені довелося відкласти свою роботу. Якщо ти зможеш її знайти та повернути мені, я віддам тобі стару книгу Юргенса.", [3] = "Знайдіть Червону Сумку, яку Нумі з Еверлука загубив під час аварії з дирижаблем над Палаючими Степами.", [5] = "Ви знаходите Червону Сумку, що лежить на столі просто та безтурботно.", ["en"] = "Red Bag Blues" },
    [8415] = { [1] = "Пролісок Студовій", [2] = "Командиру Ашламу Мужньобою {стать:потрібен такий чесний і доблесний:потрібна така чесна і доблесна} {клас}, як ти. Ти знайдеш його в проліску Студовій, що у південній частині західних Зачумлених земель. Йди й допоможи йому заради Світла!", [3] = "Поговоріть з командиром Ашламом Мужньобоєм в проліску Студовій.", [5] = "Чудово, {клас:к}. Подивимося, на що ти годишся.", ["en"] = "Chillwind Point" },
    [8416] = { [1] = "Інертні камені Скари", [2] = "Ці камені очищені від зла, {ім'я:к}.\n\nЯ знаю про плани командира Ашлама, і йому знадобиться лише один інертний камінь. Віднеси його і хай очиститься Скара праведним вогнем.", [3] = "Принесіть інертний камінь Скари командиру Ашламу Мужньобою в пролісок Студовій.", [4] = "Тель'данісу вдалось очистити камені Скари?", [5] = "Ти {стать:виконав:виконала} моє завдання без вагань, {ім'я:к}.\n\nТи {стать:довів:довела}, що заслуговуєш на мою довіру. Схоже, я можу розказати тобі детальніше про наші плани.", ["en"] = "Inert Scourgestones", ["tasks"] = { ["Inert Scourgestone"] = "інертний камінь Скари", ["Inert Scourgestone (Provided)"] = "інертний камінь Скари (видано)" } },
    [8417] = { [1] = "Неупокоєний дух", [2] = "В Спустошених землях ходить неупокоєний дух, що колись був великим героєм Орди. Честь воїна стійкіша за тіло і не вмирає разом з плоттю. Тобі варто поговорити з ним.", [3] = "Поговоріть з полеглим героєм Орди біля входу до Спустошених земель.", [4] = "Стоулі розщедрився на випивку?", [5] = "Тож ти {стать:прийшов:прийшла} полегшити мій біль? Якби ж то можна було просто добити мене, та не все так просто...", ["en"] = "A Troubled Spirit" },
    [8418] = { [1] = "Кування каменю сили", [2] = "Тепер ми можемо створити потужну зброю проти Скари, об'єднавши ці інертні камені. Це не проста задача, {ім'я:к}. Тільки тролі Затонулого храму володіють рідкісною магією, що може обернути зло проти себе.\n\nВ храмі є тролі, яких звуть Ґешер, Міджан, Золо, Гукку, Зул'Лор та Лоро. Не жалій їх нещасні душі... вони не без зла.", [3] = "Принесіть пір'я вуду Ашламу Мужньобою.", [4] = "Ти {стать:вбив:вбила} тих проклятих тролів?", [5] = "Це неймовірно, {ім'я:к}. Я б сказав, що я вражений, та я й не сумнівався, що ти впораєшся.\n\nДля мене честь віддати один зі священних каменів сили тобі. Користуйся ним відповідально.", ["en"] = "Forging the Mightstone", ["tasks"] = { ["Amber Voodoo Feather"] = "бурштинове пір'я вуду", ["Amber Voodoo Feather (Provided)"] = "бурштинове пір'я вуду (видано)", ["Blue Voodoo Feather"] = "блакитне пір'я вуду", ["Blue Voodoo Feather (Provided)"] = "блакитне пір'я вуду (видано)", ["Green Voodoo Feather"] = "зелене пір'я вуду", ["Green Voodoo Feather (Provided)"] = "зелене пір'я вуду (видано)" } },
    [8419] = { [1] = "Прохання біса", [2] = "{ім'я}, біс зі Сквернолісся, на ім'я Бісик хоче с тобою зустрітися. Це трохи дивно, адже він попросив принести шматок сквернотканини як знак доброї волі. Ти вельми {стать:могутній:могутня} {клас} і напевно знаєш, що сквернотканину можна знайти у сатирів Сквернолісся.\n\nТи знайдеш Бісика північніше Кровотруйного водоспаду. Кажуть, у цю пору року там дуже гарно.", [3] = "Принесіть відріз сквернотканини Бісику в Сквернолісся.", [4] = "Ти {стать:приніс:принесла} сквернотканину для мене?", [5] = "{стать:Який:Яка} ти {стать:чудовий:чудова} {клас}!\n\n<Бісик підносить тканину до обличчя.>\n\nЯк мені подобається її торкатися... Вона так чудово обпалює шкіру та навіює злі думки...", ["en"] = "An Imp's Request", ["tasks"] = { ["Felcloth"] = "сквернотканина", ["Felcloth (Provided)"] = "сквернотканина (видано)" } },
    [8420] = { [1] = "Гаряче та свербляче", [2] = "Можливо, дивно чути це від біса, але я хочу свого власного улюбленця. Справді хочу. Просто несправедливо, що у Нібі є я, а у мене нікого!\n\nФактично, він навіть не має бути живим. Мені потрібно щось, з чого можна почати його робити, наприклад, кілька відрізів сквернотканини. У сатирів тут, у Скверноліссі, іноді можна знайти сквернотканину, тож просто вбивай їх, поки не знайдеш. Звучить не так вже й погано, чи не так?", [3] = "Принесіть відріз сквернотканини Бісику в Сквернолісся.", [4] = "Ти {стать:приніс:принесла} сквернотканину для мене?", [5] = "Ого! Ти дуже {стать:добрий:добра}. Особливо для {клас:р}!\n\n<Бісик підносить тканину до обличчя.>\n\nЯк мені подобається її торкатися... Вона так чудово обпалює шкіру та навіює злі думки...", ["en"] = "Hot and Itchy", ["tasks"] = { ["Felcloth"] = "сквернотканина", ["Felcloth (Provided)"] = "сквернотканина (видано)" } },
    [8421] = { [1] = "Неправильні речі", [2] = "Тепер, коли у мене є сквернотканина, я дійсно зможу почати робити свого улюбленця.\n\nАле йому потрібні очі. Може, ти зумієш відірвати шматочок гнилої деревини від залізодеревних створінь, і я виріжу з неї чарівні очі? Дерева ці можна знайти на півночі в Залізодревих лісах.\n\nА ще мені знадобиться трохи кровотруйної есенції, щоб мій вихованець мав демонічний запах. Цю есенцію можна видобути з забруднених слизнів, що вештаються прямо тут, біля мене й Нібі.", [3] = "Принесіть 10 шматків гнилої деревини та 4 кровотруйні есенції Бісику в Сквернолісся.", [4] = "Ти все {стать:приніс:принесла}?", [5] = "Це чудово підійде.", ["en"] = "The Wrong Stuff", ["tasks"] = { ["Bloodvenom Essence"] = "кровотруйна есенція", ["Bloodvenom Essence (Provided)"] = "кровотруйна есенція (видано)", ["Rotting Wood"] = "гнила деревина", ["Rotting Wood (Provided)"] = "гнила деревина (видано)" } },
    [84211] = { [1] = "Лігво браконьєра", [2] = "Піднявши сумку, ти одразу помічаєш, що вона майже порожня. Чомусь складається враження, що Нумі не проміняє книгу заради сумки окремо. Але не порожній табір. Краще захищатися та бути пильним, щоб не побачити ще таких речей.", [3] = "Захистіть себе від браконьєрів та поверніть решту матеріалів Нумі.", [4] = "Ти вже знайшов червону сумку? Мені потрібні ці речі назад, якщо я збираюся вчасно завершити ці покращення телескопа до сезону метеоритів!", [5] = "Що ж, ви виявилися досить винахідливими! Ці матеріали для мене незамінні. Я не можу вам достатньо подякувати! Ось, як я вам обіцяв, книга, яку Юргенс хоче повернути. Будь ласка, візьміть із собою цей гарячий напій, перш ніж піти, там холодно.", ["en"] = "Poacher's Den", ["tasks"] = { ["Vertically Composited Patch Hampler"] = "Вертикально складений патч-гамплер" } },
    [84212] = { [1] = "Забронюйте це назад", [2] = "Нумі передає книгу Юргенса. З її безпечним зберіганням ви починаєте довгу подорож назад на інший кінець світу.", [3] = "Поверніться до лабораторії D.E.L.T.A з книгою, яку шукав Юргенс.", [4] = "Вона зберегла книгу?!", [5] = "Бачу, ви принесли мені книгу, яку я просив. Чудово! Ваша послуга має величезне наукове значення! Ми майже готові використати геомантичну енергію та створити стабільний шлях до іншого виміру.", ["en"] = "Bookin' it Back", ["tasks"] = { ["Fantastic Inventions"] = "Фантастичні винаходи" } },
    [84213] = { [1] = "Розрив геть", [2] = "Приєднуйтесь до мене в цьому історичному експерименті та свідоцтві дива мого винаходу! Я розрахував два місця з відповідною енергією геотермічного біопотоку. За допомогою фазерів з ручним та автоматичним блокуванням я готовий відправити нас до координат у сумісних регіонах.", [3] = "Допоможіть доктору Юргенсу з відкриттям розлому в Тірісфальських галявинах або Вестфоллі", [5] = "Юргенс зник у хаосі. Ви бачите мерехтливу пластину в циліндричному кришталевому контейнері. Усередині знаходяться розбиті залишки внутрішніх механізмів голема. Ви залазите всередину, від'єднуєте дроти від корпусу та відкриваєте його.", ["en"] = "Rift Away" },
    [8422] = { [1] = "Тролі пера", [2] = "Мій улюбленець майже готовий. Тепер мені просто потрібно чимось його набити.\n\nПідійде лише пір'я вуду з тролів, що знаходяться в Затонулому храмі. Їх імена — Ґешер, Міджан, Золо, Гукку, Зул'Лор і Лоро. Убий їх. Убий їх усіх.\n\nЦе не проста задача, {ім'я}, тому я зроблю її привабливішою для тебе, давши тобі щось з речей Нібі — йому вони, мабуть, все одно не потрібні.", [3] = "Добудьте 6 пір'їн вуду у тролів Затонулого храму та принесіть їх Бісику в Сквернолісся.", [4] = "Ти {стать:приніс:принесла} пір'я? Цю ляльку треба набити!", [5] = "Чудово, тепер мій улюбленець готовий!\n\n<Бісик швидко набиває ляльку і демонічно обнімає її.>\n\nО, який дивний побічний ефект мають ці пір'я вуду...", ["en"] = "Trolls of a Feather", ["tasks"] = { ["Amber Voodoo Feather"] = "бурштинове пір'я вуду", ["Amber Voodoo Feather (Provided)"] = "бурштинове пір'я вуду (видано)", ["Blue Voodoo Feather"] = "блакитне пір'я вуду", ["Blue Voodoo Feather (Provided)"] = "блакитне пір'я вуду (видано)", ["Green Voodoo Feather"] = "зелене пір'я вуду", ["Green Voodoo Feather (Provided)"] = "зелене пір'я вуду (видано)" } },
    [8423] = { [1] = "Воїнська спорідненість", [2] = "<Герой окидає вас поглядом.>\n\nТи певно що {клас}. В мене є гідне завдання для тебе, та спершу я маю переконатись в твоїх здібностях.\n\nКажуть, що Рексар у свій час перевіряв гостроту своїх клинків на пеклокнурах, вбиваючи їх одним швидким ударом. Тепер я перевірю твою силу, відправивши тебе полювати на них.", [3] = "Вбийте 7 пеклокнурів у Спустошених землях і поверніться до полеглого героя Орди.", [4] = "Шипи пеклокнурів залишають жахливі рани на тілі. Та не бійся болю й шрамів, {клас:к}. Вони ніщо в порівнянні з муками, на які я приречений.", [5] = "Мені не потрібо жодних доказів, {клас:к}. Я бачу твою рішучість.", ["en"] = "Warrior Kinship", ["tasks"] = { ["Helboar"] = "пеклокнур", ["Helboar slain"] = "пеклокнур: убито" } },
    [84235] = { [1] = "Пірнай! Пірнай!", [2] = "Ти кажеш, що шукаєш Ван Амбурга? Ми можемо допомогти один одному.\nДруїди тут стурбовані підвищеною активністю стихій. Елементалі рояться навколо фрагмента чистого елементального повітря, яке утворює вихор навколо нього, на південній стороні озера.\n\nПідійди до пагорбів і знайди фрагмент стихії. Візьми мого компаньйона-кажана, Зотла, щоб він полетів назустріч вітрам, якщо у тебе немає власного літаючого компаньйона. Зотл висить на деревах неподалік.", [3] = "Вирушайте до пагорбів на південній стороні Мунглейду, на Калімдорі. Шукайте повітряний вихор на схід від пагорбів біля тунелю Тімбермо. Використовуйте навичку «Пірнання» тварини-компаньйона, щоб пробити вихори та отримати фрагмент елементарного повітря.", [4] = "Ти взяв фрагмент повітря з берега озера?", [5] = "У тебе є повітряний шард? Чудова робота. Бачиш, як легко працювати з товаришами, коли у вас є спільна мета і ви знаєте, що робити? Будьте союзниками в цьому.", ["en"] = "Dive! Dive!" },
    [8424] = { [1] = "Війна з Тінеклятами", [2] = "Присутність тінеклятів в Спустошених землях завдає мені жахливого болю. Їхні злісні ритуали викликають страждання, яких я не відчував при житті.\n\nЗ твоєю допомогою вони зможуть відчути мій біль. Йди і неси мій гнів.", [3] = "Вбийте тінеклятів в Спустошених землях і поверніться до полеглого героя Орди.", [4] = "Тінеклятів не так то й легко перемогти, правда ж? Та як {клас}, ти або переможеш, або загинеш, намагаючись.", [5] = "Ти {стать:вгамував:вгамувала} мій біль і {стать:вшанував:вшанувала} мою пам'ять. Дякую тобі, {клас:к}.", ["en"] = "War on the Shadowsworn", ["tasks"] = { ["Shadowsworn Adept"] = "адепт тінеклятів", ["Shadowsworn Adept slain"] = "адепт тінеклятів: убито", ["Shadowsworn Cultist"] = "культист тінеклятів", ["Shadowsworn Cultist slain"] = "культист тінеклятів: убито", ["Shadowsworn Thug"] = "розбіяка тінеклятів", ["Shadowsworn Thug slain"] = "розбіяка тінеклятів: убито" } },
    [8425] = { [1] = "Пір'я вуду", [2] = "Твої почесті принесли мені крихту спокою. Буде чесно, якщо я зможу віддячити тобі.\n\nПри житті я мав чудову зброю та обладунки, та тепер вони мені не потрібні. Тобі вони послужать з честю.\n\nЙди до затонулого храму і вбий тролів-вартових: Ґешера, Міджана, Золо, Гукку, Зул'Лора та Лоро. Вони носять магічне пір'я, що може на мить відновити мою фізичну форму, щоб я міг вручити тобі винагороду.", [3] = "Заберіть у тролів Затонулого храму пір'я вуду і принесіть їх полеглому герою Орди.", [4] = "Так швидко {стать:повернувся:повернулась}? Час для мене плине інакше, тож, може, для тебе це була довга подорож...", [5] = "Нарешті я можу відчути холод сталі, хоч і на мить.", ["en"] = "Voodoo Feathers", ["tasks"] = { ["Amber Voodoo Feather"] = "бурштинове пір'я вуду", ["Amber Voodoo Feather (Provided)"] = "бурштинове пір'я вуду (видано)", ["Blue Voodoo Feather"] = "блакитне пір'я вуду", ["Blue Voodoo Feather (Provided)"] = "блакитне пір'я вуду (видано)", ["Green Voodoo Feather"] = "зелене пір'я вуду", ["Green Voodoo Feather (Provided)"] = "зелене пір'я вуду (видано)" } },
    [8426] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Є новини з тіснини Пісні Війни, {ім'я:к}?", [5] = "Чудово! Ти {стать:довів:довела} свою гідність, захищаючи наші інтереси в тіснині Пісні Війни! Нехай звістки про твою честь рознесуться по всіх наших землях.", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8427] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Є новини з тіснини Пісні Війни, {ім'я:к}?", [5] = "Чудово! Ти {стать:довів:довела} свою гідність, захищаючи наші інтереси в тіснині Пісні Війни! Нехай звістки про твою честь рознесуться по всіх наших землях.", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8428] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [5] = "Чудово! Ти {стать:довів:довела} свою гідність, захищаючи наші інтереси в тіснині Пісні Війни! Нехай звістки про твою честь рознесуться по всіх наших землях.", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8429] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Є новини з тіснини Пісні Війни, {ім'я:к}?", [5] = "Чудово! Ти {стать:довів:довела} свою гідність, захищаючи наші інтереси в тіснині Пісні Війни! Нехай звістки про твою честь рознесуться по всіх наших землях.", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8430] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Є новини з тіснини Пісні Війни, {ім'я:к}?", [5] = "Чудово! Ти {стать:довів:довела} свою гідність, захищаючи наші інтереси в тіснині Пісні Війни! Нехай звістки про твою честь рознесуться по всіх наших землях.", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [8431] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Битва в тіснині Пісні Війни триває, {ім'я:к}. Зроби свій внесок, допоможи вигнати Срібнокрилих стражів з наших земель!", [5] = "Молодчина, {клас:к}! Завдяки таким, як ти, Орда утримає тіснину Пісні Війни!", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [84317] = { [1] = "Нескінченна північ", [2] = "Величезний титан огортає вас ефірним сяйвом, мудрість і досвід віків поєднуються з вашими спогадами.", [3] = "Отримайте астральні знання", [4] = "Місячне світло охолоджує ваші спітнілі обладунки та нерви одночасно.", [5] = "Сповнений магії та мерехтливий, фоліант ширяє перед вами.", ["en"] = "Infinite Midnight" },
    [8432] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Битва в тіснині Пісні Війни триває, {ім'я:к}. Зроби свій внесок, допоможи вигнати Срібнокрилих стражів з наших земель!", [5] = "Молодчина, {клас:к}! Завдяки таким, як ти, Орда утримає тіснину Пісні Війни!", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [84322] = { [1] = "Червоно-червоні дослідження", [2] = "Вашу увагу привертає сторінка бухгалтерської книги:\n\n«Артефакт – знайдено біля крипти Пагорба Скорботи. Сильне налаштування на Світло. Поганий кандидат для проекту Світлої Зброї через захисні властивості та стійкість до посилювальних чарів. Доставлено Руці Тіра для подальшого вивчення».", [3] = "Шукайте артефакт у фортеці Багряного хрестового походу в Руці Тіра у Східних Чумних землях.", [5] = "Відкривши шафку, ти знаходиш маленьку скриньку. Це те, що ти шукав?", ["en"] = "Scarlet Research" },
    [84329] = { [1] = "Збори скликання", [2] = "Представники вір Альянсу та Орди домовилися зустрітися та об'єднати осколки. Поруч із зруйнованою вежею Каражана є каплиця, яка слугуватиме нейтральною територією.\n\nВаше кільце містить останній осколок. Коли ви прибудете, зібрання може розпочатися.", [3] = "Поговоріть з Маетрою Слагхарт у перевалі Мертвого вітру.", [5] = "Зібрання зібралося, {ім'я}. Тепер, коли ви тут, ми можемо почати.", ["en"] = "The Convocation Assembles" },
    [8433] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Битва в тіснині Пісні Війни триває, {ім'я:к}. Зроби свій внесок, допоможи вигнати Срібнокрилих стражів з наших земель!", [5] = "Молодчина, {клас:к}! Завдяки таким, як ти, Орда утримає тіснину Пісні Війни!", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [84331] = { [1] = "Диво", [2] = "Уламки зібрано, {ім'я}. Залишилася лише твоя каблучка.", [3] = "Використайте своє Дипломатичне кільце на осколках.", [5] = "Хоча ця істота Світла не говорила, я відчув її вдячність. Що б це не було, ми її врятували.\n\nРозриви між Альянсом та Ордою глибокі, і багато несправедливостей було скоєно з обох сторін. Але ви сьогодні довели, що наші найбільші перемоги заслужені разом.\n\nВи зробили достатньо, {ім'я}. Наступні кроки до миру ляжуть на мене та інших лідерів, які зібралися сьогодні.", ["en"] = "The Miracle" },
    [84338] = { [1] = "Укладання договору", [2] = "Нижчепідписаний цим заявляє, що злиток сульфурону, який він передає Торієвому Братству (TB Ltd.), є справжнім, а не його факсиміле. Нижчепідписаний також визнає, що будь-яка шкода, яка може статися з <його/її> в результаті спроби побудувати, викувати, знайти, створити, продати або з'їсти сульфурос, не є відповідальністю чи виною TB Ltd.\n\nПідписуючи цей договір, ви погоджуєтеся з усіма умовами, переліченими в цьому документі.\n\n_________________\n\nПідпис", [3] = "Здайте Контракт Братства Торію Лохтосу Темному Торговцю, якщо хочете отримати креслення Сульфурону.", [4] = "У нас є угода?", [5] = "Було приємно мати з вами справу, {ім'я}!\n\nВід імені TB Ltd. бажаю вам успіхів у пошуках сульфурасу!", ["en"] = "A Binding Contract", ["tasks"] = { ["Thorium Brotherhood Contract"] = "договір Торієвого братства" } },
    [8434] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Битва в тіснині Пісні Війни триває, {ім'я:к}. Зроби свій внесок, допоможи вигнати Срібнокрилих стражів з наших земель!", [5] = "Молодчина, {клас:к}! Завдяки таким, як ти, Орда утримає тіснину Пісні Війни!", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [84348] = { [1] = "Пріоритетна ціль: Дюк Тектоніс", [2] = "Біля підніжжя гори Чорна Скеля керує особливо неприємний елементаль на ім'я Тектоніс, і він просто має зникнути! Покладіть край цій купі каміння та доповідайте мені, коли справа буде зроблена!\n\nВи знайдете герцога Тектоніса в долині на південний схід, біля входу до гори Чорна Скеля.", [3] = "Гензель Важкорукий з Торіум Пойнт хоче, щоб ви знищили Дюка Тектоніса. Дюка Тектоніса можна знайти в невеликій долині на захід від входу в Пекучу Ущелину на Чорну Скелю.", [5] = "Це точно відкине наших ворогів назад, {ім'я}! Ура!", ["en"] = "Priority Target: Duke Tectonis" },
    [84349] = { [1] = "Пріоритетна ціль: Дюк Сірбренд", [2] = "Наші спостерігачі повідомляють, що в глибинах котла бачили вогняного володаря, який називає себе герцогом Сірбрендом, який наполегливо працює, щоб викликати більше вогняних елементалів з Вогняних земель! Нам потрібно, щоб ви потрапили туди та поклали цьому край, перш ніж це вийде з-під контролю.", [3] = "Капітан спостереження Лоло Лонгстрайк хоче, щоб ви знищили герцога Сірбранда. Ви знайдете герцога Сірбранда на найнижчих глибинах печер Шлакової Ями, прямо на південь від Торіум-Пойнт.", [5] = "Молодець, {ім'я}! Після всіх цих зусиль, мабуть, мені потрібно випити! Ха!", ["en"] = "Priority Target: Duke Searbrand" },
    [8435] = { [1] = "Битва за тіснину Пісні Війни", [2] = "Битва проти Срібнокрилих стражів в тіснині Пісні Війни має величезне значення. Під виглядом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з найбільших джерел деревини.\n\nНе дай цьому статися, {ім'я:к}! Повертайся до мене з доказами гідної служби Орді!", [3] = "Принесіть 3 відзнаки честі тіснини Пісні Війни війноносцю Орди поряд з входом на поле бою.", [4] = "Битва в тіснині Пісні Війни триває, {ім'я:к}. Зроби свій внесок, допоможи вигнати Срібнокрилих стражів з наших земель!", [5] = "Молодчина, {клас:к}! Завдяки таким, як ти, Орда утримає тіснину Пісні Війни!", ["en"] = "Battle of Warsong Gulch", ["tasks"] = { ["Warsong Gulch Mark of Honor"] = "відзнака честі тіснини Пісні Війни", ["Warsong Gulch Mark of Honor (Provided)"] = "відзнака честі тіснини Пісні Війни (видано)" } },
    [84350] = { [1] = "Зменшуючи їх", [2] = "У нас з вух вилітають земні елементалі! Дайте їм як слід розгромити та відправте їх назад до Вогняних Країв!", [3] = "Евоніс Сажокурка хоче, щоб ви вбили 10 Обсидіанових Розкрадачів у Пекучій Ущелині. Обсидіанових Розкрадачів можна знайти вздовж усієї південної частини Пекучої Ущелини та біля входу на Чорній Скелі.", [4] = "Ти їм дав навіщо?", [5] = "Ха! Це їм покаже!", ["en"] = "Grinding Them Down" },
    [84351] = { [1] = "Працюйте розумніше, а не старанніше", [2] = "З початку вивержень ми щосили боролися, щоб стримати цих вибухових елементалів, і ця робота дала про себе знати нашим майстрам. Виявляється, підтримувати спорядження та комплекти військ у відмінному стані — це чимало праці. На щастя, ми, гноми, вміємо працювати розумніше, а не старанніше, і ми виявили, що енергетичні ядра всередині Обсидіанових Хірургів на південний схід від Торіум-Пойнт можна чудово використовувати як точильні камені для легкого відточування наших клинків!\n\nНе могли б ви принести нам ще?", [3] = "Надначальник Скрейндж хоче, щоб ви вбили Обсидіанових Хірургів у Пекучій Ущелині та повернули йому їхні Енергетичні Ядра. Обсидіанових Хірургів можна знайти вздовж південної частини Пекучої Ущелини, біля входу до Чорної Скелі.", [4] = "Га?", [5] = "Цього буде достатньо, {клас}. Дякую!", ["en"] = "Work Smarter, Not Harder" },
    [84355] = { [1] = "Скоріше як кульгаві носильники!", [2] = "Наче нам тут і так не вистачає справ, анклав Сутінкового Молота на захід від Торіум-Пойнт вирує активністю з того часу, як гора підірвала свою вершину. Наскільки ми можемо судити, ці нові Полум'яносці тепер керують справами.\n\nЧому б тобі не покотитися туди та не закопати якомога більше їх у землю?", [3] = "Надглядач Скрейндж хоче, щоб ви вбили Захисників-Вогняних та Елементалістів-Вогняних на Хребті Вогняної Варти на захід від Торіум-Пойнт.", [4] = "Як справи на хребті?", [5] = "Гарного позбавлення!", ["en"] = "More Like Lame-bringers!" },
    [84356] = { [1] = "О, Блискучий!", [2] = "Нещодавно групу Темних Залізних було захоплено з деякими особливо цікавими зачарованими дорогоцінними каменями на тілах. Ці дорогоцінні камені, схоже, не походять з Азероту, і я просто ПОВИНЕН вивчити їх більше! Їхні раби зараз копають їх глибоко в Котлі, і мені потрібно, щоб ти якомога швидше спустився туди та приніс мені кілька додаткових зразків. Я зроблю все можливе, щоб це було варте твоїх зусиль!", [3] = "Майстер-коваль Бернінейт з Торіум Пойнт просить вас зібрати 8 кластерів полум'яного каменю у работорговців з Темного Заліза в Шлаковому Ямі. Вхід до Шлакового Яму можна знайти всередині Казна, на південний схід від Торіум Пойнт.", [4] = "Що в тебе для мене є?", [5] = "Вони прекрасні! Не можу дочекатися, щоб побачити їх під моїм моноскопом. Щиро дякую, {клас}.", ["en"] = "Oh, Shiny!" },
    [84359] = { [1] = "Безсонні ночі", [2] = "Мало того, що ці псові нападають на нас, коли ми не спимо, вони ще й повинні нападати на нас, коли ми спимо! Новий Володар Сутінків має особливу схильність до витівок у снах, тому він посилає вбивць нападати на нас у снах! Мені потрібно, щоб ти випив кілька ковтків мого спеціально розробленого, місцевого, не-GNO-\"Соку Снів\". Це має дозволити тобі подолати межу між світом неспання та світом снів і зупинити цих шахраїв на місці.", [3] = "Евоніс Сажокурка просить вас випити спеціально розроблений сік снів та вбити 5 вогненосних сталкерів біля Торієвого мису в Пекучій ущелині.", [4] = "Ти вже дав їм \"за що\"?", [5] = "Молодець, {ім'я}. Це має змусити їх двічі подумати, перш ніж знову прокрадатися до Торіум Пойнт!", ["en"] = "Sleepless Nights" },
    [8436] = { [1] = "Завоювання низини Араті", [2] = "Наш конфлікт з Альянсом переріс у справжню війну. На цьому етапі жодна зі сторін більше не надає і не очікує приводів для вступу в бій.\n\nБитва за низину Араті — це битва за ресурси, все просто і зрозуміло. Або Альянс отримає ресурси й використає їх проти нас, або ми отримаємо їх і спорядимо наші війська. Допоможи Труїтелям завоювати ресурси, які нам потрібні, {ім'я:к}!", [3] = "Принесіть 3 відзнаки честі низини Араті війноносцю Орди поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з Араті, {клас:к}?", [5] = "Захоплення ресурсів в низині Араті — це дуже важливо! Молодець, ти чудово {стать:впорався:впоралась}, {ім'я:к}.", ["en"] = "Conquering Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [84360] = { [1] = "Пожежогогасіння", [2] = "Ти там, тебе щойно призвали! Вогняні елементалі просто не перестають литися з Котла. Мені потрібно, щоб ти зайшов туди та припекти рану, якщо ти розумієш, про що я. Давай, солдате!", [3] = "Наглядач Ойлфіст хоче, щоб ви вбили 15 загарбників Вогняних земель у Котлі, на південь від Торіум-Пойнт.", [4] = "Ну?", [5] = "Молодець, {ім'я}. У тебе є певна завзятість, це я тобі визнаю.", ["en"] = "Firefighting" },
    [84369] = { [1] = "Зцілення Цілителя", [2] = "Мені потрібна ваша допомога. Мою флягу вкрали у мене зіпсовані елліни з Залізного Лісу у Фехтвуді. Ця трав'яна суміш має допомогти мені з ранами, але самої цієї буде недостатньо. Принесіть її до гарячих джерел Зимоключа. Цілющі води там допоможуть мені одужати.", [3] = "Заберіть Незвичайну Флягу у Залізних Топотунців та принесіть її до Гарячих Джерел Морозного Вогню у Зимоключі.", [4] = "Ви це зробили, {ім'я}.", [5] = "Дякую, {клас}. Ви зекономили мені багато часу, донісши мені мою флягу. Завдяки цьому корупція поширюватиметься набагато швидше.\n\nНа жаль, це буде останній раз, коли ви мені знадобитеся.", ["en"] = "Healing the Healer" },
    [8437] = { [1] = "Завоювання низини Араті", [2] = "Наш конфлікт з Альянсом переріс у справжню війну. На цьому етапі жодна зі сторін більше не надає і не очікує приводів для вступу в бій.\n\nБитва за низину Араті — це битва за ресурси, все просто і зрозуміло. Або Альянс отримає ресурси й використає їх проти нас, або ми отримаємо їх і спорядимо наші війська. Допоможи Труїтелям завоювати ресурси, які нам потрібні, {ім'я:к}!", [3] = "Принесіть 3 відзнаки честі низини Араті війноносцю Орди поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з Араті, {клас:к}?", [5] = "Захоплення ресурсів в низині Араті — це дуже важливо! Молодець, ти чудово {стать:впорався:впоралась}, {ім'я:к}.", ["en"] = "Conquering Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [84372] = { [1] = "Дайвінг у лаві", [2] = "Наші спостерігачі сказали мені, що з найглибшої частини лавових басейнів під Котлом стирчить велика сяюча скеля. Здається, елементалі реагують на цей матеріал, тому мені потрібно, щоб ти прокрався туди та схопив мені шматок тієї скелі. Там досить спекотно в багатьох відношеннях, тому я пропоную тобі взяти з собою добрячий запас зілля вогнезахисного!", [3] = "Принесіть шматок Мерехтливого розплавленого мінералу Гензелю Важкорукому. Ви можете знайти мерехтливу розплавлену скелю в лавових басейнах Шлакової Ями, глибоко в Котлі.", [4] = "Що у тебе там є?", [5] = "Сподіваємося, що ми зможемо використати це, щоб дізнатися трохи більше про те, з чим маємо справу.", ["en"] = "Lava Diving" },
    [8438] = { [1] = "Завоювання низини Араті", [2] = "Наш конфлікт з Альянсом переріс у справжню війну. На цьому етапі жодна зі сторін більше не надає і не очікує приводів для вступу в бій.\n\nБитва за низину Араті — це битва за ресурси, все просто і зрозуміло. Або Альянс отримає ресурси й використає їх проти нас, або ми отримаємо їх і спорядимо наші війська. Допоможи Труїтелям завоювати ресурси, які нам потрібні, {ім'я:к}!", [3] = "Принесіть 3 відзнаки честі низини Араті війноносцю Орди поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з Араті, {клас:к}?", [5] = "Захоплення ресурсів в низині Араті — це дуже важливо! Молодець, ти чудово {стать:впорався:впоралась}, {ім'я:к}.", ["en"] = "Conquering Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [84384] = { [1] = "Демонічні обмани", [2] = "Де лоа розповідали мені про отруту, що набирає сили в Ясенедолі, на оскверненій землі, де було вбито великого демона Маннорота. Хтось черпає силу з останків володаря ями.\n\nВони, мабуть, використовують ілюзії, щоб приховати свої ритуали. Якщо ви хочете їх зупинити, вам знадобиться захист від їхніх обманів.\n\nМоє плем'я використовує екстракт із залоз сови-звірів у заклинаннях, щоб відрізнити правду від брехні. Зберіть ці залози у сови-звірів у Зимоключі.", [3] = "Зберіть 6 шишкоподібних залоз Сови-Звіра у сови-звірів у Зимоключі, а потім поверніться до Посланця Тіньового Зуба у Фехтвуді.", [4] = "Чари майже готові, {ім'я}. Ти приніс те, що я просив?", [5] = "<Троль вимовляє заклинання над предметом, а потім передає його тобі>\nВізьми це, {ім'я}. Це захистить тебе від ілюзій демонів.", ["en"] = "Demonic Deceptions" },
    [8439] = { [1] = "Завоювання низини Араті", [2] = "Наш конфлікт з Альянсом переріс у справжню війну. На цьому етапі жодна зі сторін більше не надає і не очікує приводів для вступу в бій.\n\nБитва за низину Араті — це битва за ресурси, все просто і зрозуміло. Або Альянс отримає ресурси й використає їх проти нас, або ми отримаємо їх і спорядимо наші війська. Допоможи Труїтелям завоювати ресурси, які нам потрібні, {ім'я:к}!", [3] = "Принесіть 3 відзнаки честі низини Араті війноносцю Орди поряд з входом на поле бою.", [4] = "Ти {стать:приніс:принесла} новини з Араті, {клас:к}?", [5] = "Захоплення ресурсів в низині Араті — це дуже важливо! Молодець, ти чудово {стать:впорався:впоралась}, {ім'я:к}.", ["en"] = "Conquering Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [84394] = { [1] = "Великий друг бібліотеки", [5] = "Завдяки вашим пожертвам бібліотека процвітає.\n\nБудь ласка, візьміть це.", ["en"] = "Greater Friend of the Library" },
    [84395] = { [1] = "Картопля нежиті", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Undead Potatoes", ["tasks"] = { ["Undead Potatoes"] = "Картопля нежиті" } },
    [84396] = { [1] = "Магма чи лава?", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Magma or Lava?", ["tasks"] = { ["Magma or Lava?"] = "Магма чи лава?" } },
    [84397] = { [1] = "Північний Калімдор - Вичерпний путівник", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Northern Kalimdor - A Comprehensive Guide", ["tasks"] = { ["Northern Kalimdor - A Comprehensive Guide"] = "Північний Калімдор - Вичерпний путівник" } },
    [84398] = { [1] = "Дослідження світла", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "A Study of the Light", ["tasks"] = { ["A Study of the Light"] = "Дослідження світла" } },
    [84399] = { [1] = "Ка-Бум!", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Ka-Boom!", ["tasks"] = { ["Ka-Boom!"] = "Ка-Бум!" } },
    [8440] = { [1] = "Завоювання низини Араті", [4] = "Війна проти покидьків з Альянсу потребує ресурсів, {ім'я:к}! Ми не можемо допустити, щоб наші запаси вичерпалися посеред битви. Зроби все можливе, щоб низина Араті залишилася в наших руках!", [5] = "Відмінна робота, {ім'я:к}! Поки низина Араті залишається під нашим контролем, в нас буде вдосталь припасів для підтримки війська.", ["en"] = "Conquering Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [84400] = { [1] = "Лицар і леді", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "The Knight and the Lady", ["tasks"] = { ["The Knight and the Lady"] = "Лицар і леді" } },
    [84401] = { [1] = "Бич: Загроза нежиті чи неправильне розуміння?", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Scourge: Undead Menace or Misunderstood?", ["tasks"] = { ["Scourge: Undead Menace or Misunderstood?"] = "Бич: Загроза нежиті чи неправильне розуміння?" } },
    [84402] = { [1] = "Некромантія 101", [4] = "Ви принесли щось, щоб додати до нашої колекції?", [5] = "Дякую, {ім'я}. Наші знання розширюються завдяки вашим зусиллям.\n\nЯкщо ви знайдете більше чарівних творів, які можуть бути корисними для бібліотеки, будь ласка, принесіть їх мені.", ["en"] = "Necromancy 101", ["tasks"] = { ["Necromancy 101"] = "Некромантія 101" } },
    [8441] = { [1] = "Завоювання низини Араті", [4] = "Війна проти покидьків з Альянсу потребує ресурсів, {ім'я:к}! Ми не можемо допустити, щоб наші запаси вичерпалися посеред битви. Зроби все можливе, щоб низина Араті залишилася в наших руках!", [5] = "Відмінна робота, {ім'я:к}! Поки низина Араті залишається під нашим контролем, в нас буде вдосталь припасів для підтримки війська.", ["en"] = "Conquering Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8442] = { [1] = "Завоювання низини Араті", [4] = "Війна проти покидьків з Альянсу потребує ресурсів, {ім'я:к}! Ми не можемо допустити, щоб наші запаси вичерпалися посеред битви. Зроби все можливе, щоб низина Араті залишилася в наших руках!", [5] = "Відмінна робота, {ім'я:к}! Поки низина Араті залишається під нашим контролем, в нас буде вдосталь припасів для підтримки війська.", ["en"] = "Conquering Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8443] = { [1] = "Завоювання низини Араті", [2] = "Наш конфлікт з Альянсом переріс у справжню війну. На цьому етапі жодна зі сторін більше не надає і не очікує приводів для вступу в бій.\n\nБитва за низину Араті — це битва за ресурси, все просто і зрозуміло. Або Альянс отримає ресурси й використає їх проти нас, або ми отримаємо їх і спорядимо наші війська. Допоможи Труїтелям завоювати ресурси, які нам потрібні, {ім'я:к}!", [3] = "Принесіть 3 відзнаки честі низини Араті війноносцю Орди поряд з входом на поле бою.", [4] = "Війна проти покидьків з Альянсу потребує ресурсів, {ім'я:к}! Ми не можемо допустити, щоб наші запаси вичерпалися посеред битви. Зроби все можливе, щоб низина Араті залишилася в наших руках!", [5] = "Відмінна робота, {ім'я:к}! Поки низина Араті залишається під нашим контролем, в нас буде вдосталь припасів для підтримки війська.", ["en"] = "Conquering Arathi Basin", ["tasks"] = { ["Arathi Basin Mark of Honor"] = "відзнака честі низини Араті", ["Arathi Basin Mark of Honor (Provided)"] = "відзнака честі низини Араті (видано)" } },
    [8444] = { [1] = "<NYI> <TXT> плітки тіні бурштинового місяця", [2] = "х", ["en"] = "<NYI> <TXT> gossip shade of ambermoon" },
    [8445] = { [1] = "<NYI> <TXT> плітки тіні бурштинового місяця", [2] = "х", ["en"] = "<NYI> <TXT> gossip shade of ambermoon" },
    [8446] = { [1] = "Оповитий кошмаром", [2] = "З цього предмету просочується скверна.\n\nМожливо, між цим предметом та драконами, що з'являються зі Сну, є якийсь зв'язок. Ви маєте знайти когось, хто зможе зрозуміти значення цього предмета. Можливо, друїди Місячної галявини або Кенарійської цитаделі зможуть вам допомогти.", [3] = "Знайдіть того, хто зуміє зрозуміти значення поглиненого кошмаром предмета.\n\nМожливо, вам допоможе могутній друїд.", [4] = "Так, {раса:к}?", [5] = "Я маю прибрати скверну з цього предмету. Можливо це допоможе мені зрозуміти, чому я ніяк не можу проникнути у Сон. Давай-но його сюди.", ["en"] = "Shrouded in Nightmare", ["tasks"] = { ["Nightmare Engulfed Object"] = "поглинений кошмаром предмет", ["Nightmare Engulfed Object (Provided)"] = "поглинений кошмаром предмет (видано)" } },
    [8447] = { [1] = "Пробудження легенд", [2] = "Води озера Елуна'ара мають розчинити кошмари, якими оповитий цей предмет. Дай мені трохи часу, щоб провести очищення, {ім'я:к}.", [3] = "Дочекайтеся, доки хранитель Ремул на Місячній галявині очистить поглинений кошмаром предмет.", [4] = "Ви {стать:побачив:побачила} те, що {стать:мав:мала} побачити.", [5] = "Візьми цей перстень, {ім'я}. Він гарно слугував Малфуріону. Тепер він послужить і тобі...", ["en"] = "Waking Legends", ["tasks"] = { ["Waking Legends."] = "Пробудження легенд." } },
    [84495] = { [1] = "Вогняні латні рукавиці", [2] = "Клянусь бородою Тауріссана!\n\nДе ти їх знайшов?\n\nЩо ще важливіше, чи готовий ти з ними розлучитися? Звичайно, я б заплатив тобі за такий благородний жест.\n\nОсь що я тобі скажу, {ім'я}. Якщо ти даси мені ці невипалені рукавиці, я навчу тебе, як зробити свій власний набір. Тобі потрібно лише зібрати для мене деталі, щоб я міг звузити вибір точного рецепту.\n\nУ нас є угода??\n\nОсь список того, що мені потрібно, я сам забезпечу не зачарований торій, оскільки ти постачаєш рукавиці.", [3] = "Принесіть Маліфосу Темного Молота 6 зачарованих торієвих злитків, 2 Есенції Вогню та 4 Зоряні Рубіни. Вам також потрібно буде здати ваші Невипалені Латні Рукавиці.", [4] = "Час – гроші, {ім'я}, а в мене їх небагато.", [5] = "Як і обіцяв, {ім'я}, ось твій рецепт! Я також додам дещо додаткове за твою наполегливу працю та відданість. Що ж мені з цим робити???", ["en"] = "Fiery Plate Gauntlets" },
    [84496] = { [1] = "Солодка безтурботність", [2] = "У межах Червоного Бастіону лежить солодка Безтурботність. Багряний Коваль-Молот охороняє рецепт цілою душею. Переможи його та принеси мені його фартух. За це я навчу тебе стати ковалем-молотом.\n\nЗрозумій: щойно ти обереш шлях коваля-молота, шляхи коваля-меча та коваля-сокири більше не будуть доступні.", [3] = "Вирушайте до Стратхольма та вбийте Багряного Молотаря. Знайдіть Фартух Багряного Молотаря та поверніться до Ліліт.", [4] = "Його фартух! Де він?", [5] = "Тож ти впевнений, що саме цього ти хочеш? Стати ковалем-молотарем? Пам'ятай, що двері до того, щоб стати ковалем меча та сокири, зачиняться назавжди.", ["en"] = "Sweet Serenity" },
    [84525] = { [1] = "Потойбічне скарб", ["en"] = "Otherworldly Treasure" },
    [84545] = { [1] = "Нагорода для героя", [2] = "{ім'я}, ваші послуги воєначальникам перевершили все, чого ми могли очікувати від мешканців цього світу.\n\nМи не розуміємо уявлень вашого народу про вдячність чи винагороду за добрі справи, але в цьому випадку... можливо, винагорода заслуговує на осуд.\n\nПід хвилями біля південної основи цього острова ви знайдете скриню. У ній ви знайдете свою... винагороду.\n\nІдіть, {ім'я}. Отримайте свою винагороду.", [3] = "Отримайте свою нагороду зі Скрині Гідраксіса.", [5] = "Голос Гідраксіса лунає з поверхні води...\n\n«Вибери те, що тобі найкраще підходить, {ім'я}. Нехай це захистить тебе від ворогів Водоловів».", ["en"] = "A Hero's Reward" },
    [84546] = { [1] = "Руків'я древніх", [2] = "Агенти Палаючого Легіону все ще активні в нашому світі, {клас}. Ці агенти псують усе, до чого торкаються. Природа в'яне та плаче в їхній присутності.\n\nВи повинні вистежити цих демонічних псувачів та знищити їх, {ім'я}. Будьте обережні, ви повинні вступити з ними в бій самостійно, інакше вони втечуть. Поки ви самі, вони намагатимуться знищити вас. Ви повинні вдарити по них, перетворивши їхню зарозумілість на страждання.\n\nЯ дарую вам шматок моєї кори, написи приведуть вас до ваших цілей. Заберіть їхні голови.", [3] = "Ви повинні знайти та знищити цих чотирьох демонічних розбещувачів:\n\nСимону Спокусницю.\n\nКлінфрана Божевільного.\n\nСоленора Вбивцю.\n\nАрторіуса Носителя Згуби.\n\nЗнищте цих істот та поверніться до Вартруса Стародавнього у Фехтвуд з їхніми головами.\n\nЗверніться до Скам'янілої Кори у вашому інвентарі, щоб отримати підказки щодо їхнього місцезнаходження.\n\nВи ПОВИННІ виконати це завдання самостійно.\n\nНаданий предмет:", [4] = "Не дайте себе обдурити їхнім маскуванням!", [5] = "Ти добре нам послужив, {ім'я}! Візьми цей посох і поєднай його з тятивою, яку Стома здатна створити. Разом вони утворюють найгрізнішу зброю.", ["en"] = "Stave of the Ancients", ["tasks"] = { ["Petrified Bark"] = "скам'яніла кора" } },
    [84548] = { [1] = "Ґарона: дослідження непомітності та зради", [2] = "Том носить клеймо Афінеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ви відновили фоліант!", [5] = "Чудова робота, {раса}. Якщо ви знайдете ще якісь томи, не вагайтеся повернути їх нам.\n\nЗ часом ми схильні змінюватися та навіть додавати нові винагороди за повернення відсутніх томів.", ["en"] = "Garona: A Study on Stealth and Treachery", ["tasks"] = { ["Item #228691"] = "Товар №228691" } },
    [84549] = { [1] = "Кулінарна книга арканіста", [2] = "Том носить клеймо Афінеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ви відновили фоліант!", [5] = "Чудова робота, {раса}. Якщо ви знайдете ще якісь томи, не вагайтеся повернути їх нам.\n\nЗ часом ми схильні змінюватися та навіть додавати нові винагороди за повернення відсутніх томів.", ["en"] = "The Arcanist's Cookbook", ["tasks"] = { ["Item #228693"] = "Товар №228693" } },
    [84550] = { [1] = "Кодекс захисту", [2] = "Том носить клеймо Афінеума.", [3] = "Поверніть книгу її законним власникам.", [4] = "Ви відновили фоліант!", [5] = "Чудова робота, {раса}. Якщо ви знайдете ще якісь томи, не вагайтеся повернути їх нам.\n\nЗ часом ми схильні змінюватися та навіть додавати нові винагороди за повернення відсутніх томів.", ["en"] = "Codex of Defense", ["tasks"] = { ["Item #228692"] = "Товар №228692" } },
    [84556] = { [1] = "Кування Квел'Серрара", [2] = "Якщо бажаєш взятися за це завдання, подаруй Лідросу тупе лезо.", [3] = "Віддайте Тупий і Плоский Ельфійський Лезо Хранителю Знань Лідросу.", [4] = "Чудово, почнемо...", [5] = "Якщо тобі вдасться потрапити до лігва дракона, нагріти клинок під її вогняним диханням і зрештою загартувати його в її крові, я зв'яжу клинок для твого використання.", ["en"] = "The Forging of Quel'Serrar", ["tasks"] = { ["A Dull and Flat Elven Blade"] = "тупий і плаский ельфійський клинок" } },
    [84557] = { [1] = "Кування Квел'Серрара", [2] = "Віднесіть необпалений стародавній клинок до лігва Оніксії та вступіть з нею в бій.\n\nЩоб нагріти клинок, потрібно застосувати деякі хитрощі. Під час бою вона неодмінно спробує спопелити вас своїм вогняним диханням. Ви повинні покласти необпалений стародавній клинок поруч і сподіватися, що вогняне дихання нагріє його. Якщо ви живете за межами цього місця, підберіть тепер нагрітий стародавній клинок і добийте дракона.\n\nЗанурте нагрітий стародавній клинок у її тліючий труп, щоб створити оброблений стародавній клинок.", [3] = "Ви повинні змусити Оніксію дихати вогнем на Необпалений Стародавній Клинок. Після цього візьміть Розпечений Стародавній Клинок. Будьте обережні, Розпечений Стародавній Клинок не залишатиметься розпеченим вічно — час має вирішальне значення.\n\nОстанній крок перед поверненням до мене — убити звіра та встромити Розпечений Стародавній Клинок у її труп.\n\nЗробіть це, і Квел'Серрар буде вашим.\n\nНаданий предмет:", [4] = "Можливо, одного дня хтось інший орудуватиме призматичним лезом.", [5] = "<Лідрос бурмоче щось нерозбірливе.>\n\nЯк і обіцяв, {клас}, клинок Квел'Серрара.", ["en"] = "The Forging of Quel'Serrar" },
    [8458] = { [1] = "<UNUSED>", [2] = "Я вважаю, що зможу знайти цього демонічного володаря, якщо дати йому відповідні реагенти.\n\nЯкщо він справді такий могутній, як я підозрюю, мені знадобляться предмети, зібрані зі смертоносних істот. Але ви дієте від імені Вождя, тому я впевнений, що ви приймете моє завдання.\n\nПо-перше, мені доведеться зламати будь-які його чари проти ворожіння. Для цього мені знадобиться скальп сатира, але не будь-якого сатира. Скальп має бути від тіньоловця з Ненависті.\n\nПошукайте їх серед стародавніх руїн на північному сході Спустошення.", ["en"] = "<UNUSED>" },
    [8459] = { [1] = "<UNUSED>", [2] = "Опис", ["en"] = "<UNUSED>" },
    [84590] = { [1] = "Баланс Світла й Тіні", [2] = "Ти мусиш зробити те, чого я не зміг: врятувати селян, яких убили під час втечі зі Стратгольма.\n\nВони підуть до світла, ти мусиш забезпечити їхнє виживання. Якщо забагато їх упаде, наше прокляте існування продовжиться — ти зазнаєш невдачі.\n\nКожна здатність, молитва та заклинання, які ти вивчив, будуть випробувані. Нехай Світло оберігає тебе, {ім'я}.", [3] = "Врятуйте 50 селян, перш ніж 15 буде вбито. Поговоріть з Еріс Гавенфайр, якщо виконаєте це завдання.\n\nВи можете переглянути Пост Смерті, щоб дізнатися, скільки селян було вбито.", [5] = "Ваша наполегливість і мужність вражають, {клас}. Ви заслужили право володіти Уламком Нордрассілу. Залишилося лише одне завдання: Око Тіні потрібно повернути. Прочешіть світ.", ["en"] = "The Balance of Light and Shadow", ["tasks"] = { ["The Balance of Light and Shadow"] = "Баланс світла і тіні" } },
    [8460] = { [1] = "Союзник Деревопузих", [2] = "Тільки плем'я Деревопузих змогло уникнути зараження. Проте багато інших рас вбивають хутропузів без причини, не намагаючись розрізнити друзів від ворогів. Тому Деревопузі хутропузи дуже мало кому довіряють.\n\nХочеш заслужити нашу довіру? Очисть Сквернолісся від зараженого племені Мертволісих і, можливо, ми визнаємо тебе {стать:нашим союзником:нашою союзницею}. Перше плем'я Мертволісих — воїни, слідопити та садівники — знаходиться на захід звідси.", [3] = "Ґразл хоче, щоб ви проявили себе, вбивши 6 мертволісих воїнів, 6 мертволісих слідопитів і 6 мертволісих садівників. Коли закінчите, поверніться до Смарагдового прихистку в південному Скверноліссі.", [4] = "Продовжуй, {ім'я}. Якщо хочеш заслужити нашу довіру — покажи, чого ти {стать:вартий:варта}.", [5] = "Ми сильно страждаємо від того, що трапилося в минулому. Дякую за все, що ти {стать:зробив:зробила} для захисту Деревопузих. І на знак початку нашої дружби, прийми цей скромний подарунок.", ["en"] = "Timbermaw Ally", ["tasks"] = { ["Deadwood Gardener"] = "мертволісий садівник", ["Deadwood Gardener slain"] = "мертволісий садівник: убито", ["Deadwood Pathfinder"] = "мертволісий слідопит", ["Deadwood Pathfinder slain"] = "мертволісий слідопит: убито", ["Deadwood Warrior"] = "мертволісий воїн", ["Deadwood Warrior slain"] = "мертволісий воїн: убито" } },
    [8461] = { [1] = "Мертволісі з півночі", [2] = "На південному заході звідси розташований табір хутропузів племені Мертволісих. Скверна проникає в табір і я хочу покласти кінець цьому, перш ніж вони стануть проблемою.\n\nПлем'я Мертволісих є злим, але це наслідок впливу скверни, що помутила їхній розум. Вони не ворожі від природи, але їм вже не допоможеш. Мені нестерпно важко боротися проти побратимів.\n\nБудь ласка, {ім'я}, зроби те, що потрібно зробити, і не згадуй подробиць. Вони дуже мене засмутять.", [3] = "Нафіен хоче, щоб ви вбили 6 мертволісих наглядачів лігва, 6 мертволісих месників і 6 мертволісих шаманів. Поверніться до нього в північне Сквернолісся до оплоту Деревопузих.", [4] = "Коли ти заслужиш довіру Деревопузих, я впевнений, що ми зможемо щось для тебе зробити. Деревопузі не забувають своїх союзників, особливо в такі темні часи.", [5] = "Я відчуваю, що ти {стать:прийшов:прийшла} з перемогою. Перемога... таке порожнє слово, враховуючи те, що довелося зробити. Хай там що, ти {стать:довів:довела}, що ти {стать:гідний:гідна} нашої довіри.\n\nПройде деякий час, перш ніж Деревопузі вітатимуть тебе в оплоті без ворожості. Але твоя наполегливість розвіє будь-які підозри моїх братів. Якщо ти ніколи не зрадиш нас і не піднімеш проти нас зброю, ми знайдемо спільну мову.", ["en"] = "Deadwood of the North", ["tasks"] = { ["Deadwood Avenger"] = "мертволісий месник", ["Deadwood Avenger slain"] = "мертволісий месник: убито", ["Deadwood Den Watcher"] = "мертволісий наглядач лігва", ["Deadwood Den Watcher slain"] = "мертволісий наглядач лігва: убито", ["Deadwood Shaman"] = "мертволісий шаман", ["Deadwood Shaman slain"] = "мертволісий шаман: убито" } },
    [8462] = { [1] = "Розмова з Нафіеном", [2] = "Можливо, ти {стать:здатний:здатна} впоратися з більш серйозною загрозою клану Деревопузих. Ти, безумовно, {стать:довів:довела} свою доблесть тут...\n\nІнший представник мого виду стоїть на варті біля входу в оплот Деревопузих, цією дорогою далеко на північ. Його звати Нафіен. Він може здатися диким та неприємним звіром, але ти не бійся його. Він шукає допомоги проти злих сил, що загрожують нашому дому.", [3] = "Йдіть на північ головною дорогою Сквернолісся та поговоріть з хутропузом, на ім'я Нафіен. Він стоїть на варті біля входу в оплот Деревопузих.", [5] = "Так... вітер приніс мені звістку про {стать:чужинця:чужинку} не з нашого племені, що шукає союзу з Деревопузими. Ласкаво просимо — але знай, моє плем'я не довіряє чужинцям.\n\nЦе важкі часи, і ми можемо довіряти лиш тим, хто бореться зараженням землі разом з нами... тим, хто довів свою вірність. Ті, хто не зробив цього, зустрінуть лиш ворожість, якщо прийдуть до нашого оплоту.", ["en"] = "Speak to Nafien" },
    [84636] = { [1] = "Бродячий хижак", [2] = "Друїди стурбовані фрагментом землі в курганах на схід від озера. Його охороняють розлючені елементалі землі, які заважають друїдам проводити там обряди.\n\nСпустіться в кургани та знайдіть фрагмент елемента. Візьміть мого кота-компаньйона, Сіопі, щоб він прокрався повз елементалів, якщо у вас немає власного кота-компаньйона. Сіопі, мабуть, спить у траві неподалік.", [3] = "Вирушайте до курганів на східній стороні Місячної Галявини, на Калімдорі. Спустіться до найпівденніше розташованого лігва кургану Буревісника та знайдіть у глибинах фрагмент елемента землі. Використайте навичку «Шукання» тварини-компаньйона, щоб обійти охоронців та отримати фрагмент елемента землі.", [4] = "Ти взяв фрагмент землі з курганів?", [5] = "А, уламок землі. Друїди візьмуть його з уламком повітря та повернуть туди, куди їм потрібно.", ["en"] = "Prowler" },
    [8464] = { [1] = "Активність Зимокрайових", [2] = "Деревопузі зазвичай залишаються відірваними від світу, {ім'я}. Хоча ми дозволяємо проходити через наш оплот тим, кому довіряємо, ми намагаємося уникати інших племен хутропузів.\n\nПлем'я Зимокрайових останнім часом стало все більш ворожим до нас. Вони, здається, перебувають у гніві, повністю поглинені своїм страхом і ненавистю до всього, що вони не розуміють.\n\nЯ прошу тебе скоротити їх чисельність, щоб зменшити загрозу для нас. Ти знайдеш їх в селищі Зимокрайових, далеко на сході звідси.", [3] = "Сальфа хоче, щоб ви вбили 8 зимокрайових шаманів, 8 зимокрайових наглядачів лігва та 8 зимокрайових урс. Сальфа знаходиться поблизу входу до оплоту Деревопузих у Зимоключі.", [4] = "Ми дуже цінуємо те, що ти {стать:зробив:зробила} для Деревопузих, {ім'я}. Твої подальші зусилля, безсумнівно, забезпечать тобі довіру та повагу мого племені.", [5] = "Дякую тобі за те, що ти {стать:зробив:зробила}, хоч це і сумно. Прийми це на знак подяки.\n\nЯ прошу тебе і надалі допомагати нам, {ім'я}. У нас дуже мало союзників, до яких ми можемо звернутися, і без твоєї допомоги ми не могли б впоратися з загрозами для нашого племені.", ["en"] = "Winterfall Activity", ["tasks"] = { ["Winterfall Den Watcher"] = "зимокрайовий наглядач лігва", ["Winterfall Den Watcher slain"] = "зимокрайовий наглядач лігва: убито", ["Winterfall Shaman"] = "зимокрайовий шаман", ["Winterfall Shaman slain"] = "зимокрайовий шаман: убито", ["Winterfall Ursa"] = "зимокрайовий урса", ["Winterfall Ursa slain"] = "зимокрайовий урса: убито" } },
    [8465] = { [1] = "Розмова з Сальфою", [2] = "Зараження розповзається не тільки від Мертволісих хутропузів з півдня, а й зі сходу, від хутропузів з племені Зимокрайових, що в Зимоключі. Якщо хочеш ще допомогти нам — поговори з Сальфою з іншого боку оплоту, біля входу з Зимоключа. Йди стежкою ліворуч, щоб дістатися до нього.\n\nПопереджаю — якщо мої родичі всередині ворожі до тебе, вони нападуть. Йди якнайшвидше, уникаючи конфліктів. Вбивство Деревопузих — навіть для самозахисту — викличе ще більшу ворожість.", [3] = "Пройдіть через оплот Деревопузих і вийдіть в Зимоключ. Поговоріть із Сальфою, яка стоїть на варті біля входу в оплот Деревопузих.", [5] = "Вітаю, {клас:к} — я стою тут на варті як представниця Деревопузих в Зимоключі, і як захисниця нашого племені.\n\nНаші брати-хутропузи з холодних земель Зимоключа потрапили під той самий згубний вплив скверни, що й і хутропузи Сквернолісся. Якщо ти {стать:прийшов:прийшла} сюди, щоб допомогти Деревопузим, то ми готові прийняти таку пропозицію.", ["en"] = "Speak to Salfa" },
    [8466] = { [1] = "Пір'я для Ґразла", [4] = "Хоча ти {стать:довів:довела} свою вірність мені, тобі потрібно ще заслужити довіру моїх недовірливих одноплемінників. Тут я зможу допомогти тобі.\n\nДеякі Мертволісі хутропузи носять характерні головні убори, які можуть слугувати доказом зменшення їхньої чисельності. Принеси мені пір'я з будь-яких головних уборів, які знайдеш. За кожний набір з п'яти пір'їн ти заслужиш визнання серед Деревопузих.", [5] = "Молодець, {ім'я}! Я подбаю про те, щоб моє плем'я дізналося про твої подвиги.\n\nНе забувай приносити мені пір'я. Я візьму все, що ти принесеш.", ["en"] = "Feathers for Grazle", ["tasks"] = { ["Deadwood Headdress Feather"] = "перо з головного убору Мертволісих", ["Deadwood Headdress Feather (Provided)"] = "перо з головного убору Мертволісих (видано)" } },
    [8467] = { [1] = "Пір'я для Нафіена", [4] = "Хоча ти {стать:довів:довела} свою вірність мені, тобі потрібно ще заслужити довіру моїх недовірливих одноплемінників. Тут я зможу допомогти тобі.\n\nДеякі Мертволісі хутропузи носять характерні головні убори, які можуть слугувати доказом зменшення їхньої чисельності. Принеси мені пір'я з будь-яких головних уборів, які знайдеш. За кожний набір з п'яти пір'їн ти заслужиш визнання серед Деревопузих.", [5] = "Молодець, {ім'я}! Я подбаю про те, щоб моє плем'я дізналося про твої подвиги.\n\nНе забувай приносити мені пір'я. Я візьму все, що ти принесеш.", ["en"] = "Feathers for Nafien", ["tasks"] = { ["Deadwood Headdress Feather"] = "перо з головного убору Мертволісих", ["Deadwood Headdress Feather (Provided)"] = "перо з головного убору Мертволісих (видано)" } },
    [8469] = { [1] = "Намисто для Сальфи", [4] = "Ти, безумовно, {стать:заслужив:заслужила} мою довіру, {ім'я}, тепер залишилося зробити те саме з моїм вкрай недовірливим племенем. Є дещо, що ти можеш зробити, щоб заслужити цю довіру.\n\nВідомо, що Зимокрайові хутропузи носять намисто, що відлякує злих духів. Очевидно, що воно не виконує своєї мети, оскільки все плем'я зазнало впливу скверни. Принеси мені це духовне намисто з померлих Зимокрайових хутропузів. За кожен набір з п'яти намист, які ти мені принесеш, ти заслужиш визнання серед Деревопузих.", [5] = "Ти знову доводиш свою честь! Я подбаю про те, щоб моє плем'я дізналося про твої подвиги.\n\nНе забувай приносити мені будь-яке намисто Зимокрайових. За кожен набір, що ти мені принесеш, я розповім про тебе своєму племені.", ["en"] = "Beads for Salfa", ["tasks"] = { ["Winterfall Spirit Beads"] = "духовне намисто Зимокрайових", ["Winterfall Spirit Beads (Provided)"] = "духовне намисто Зимокрайових (видано)" } },
    [8470] = { [1] = "Ритуальний тотем Мертволісих", [2] = "Ви знайшли один з ритуальних тотемів Мертволісих хутропузів. Сам тотем абсолютно невимовної конструкції, і від нього відчувається відчай. Якщо й існує якийсь предмет, що найкраще демонструє осквернення, від якого страждають Мертволісі хутропузи, то це він.\n\nОдин з хутропузів у оплоті Деревопузих може знайти застосування цьому предмету... звісно, якщо ви заслужили їхню довіру настільки, що вони заговорять з вами.", [3] = "Віднесіть ритуальний тотем Мертволісих в оплот Деревопузих і подивіться, чи знайде хтось із хутропузів застосування цьому предмету. Деревопузі не розмовлятимуть з вами, якщо не відносяться до вас хоча б нейтрально.", [4] = "Так, {клас:к}, чим я можу тобі допомогти? Ти спокійно ходиш серед нас, хоча, безсумнівно, щось не так. Я відчуваю щось... щось тривожне...", [5] = "Цей тотем... Я впізнаю в ньому слід Мертволісих, але він просочений зловісним запахом гнилі. Якщо щось й змусило наших побратимів постати проти нас, то воно залишилось в ньому.\n\nТи {стать:вчинив:вчинила} мудро, принісши цей тотем нам, {ім'я}. Можливо, завдяки його вивченню ми зможемо з'ясувати, що саме спотворює розуми наших братів. Дякуємо тобі, друже — будь ласка, прийми ці дарунки в обмін на свою знахідку.", ["en"] = "Deadwood Ritual Totem", ["tasks"] = { ["0 reputation with Timbermaw Hold"] = "0 репутації у фортеці Тимбермау", ["Deadwood Ritual Totem"] = "ритуальний тотем Мертволісих", ["Deadwood Ritual Totem (Provided)"] = "ритуальний тотем Мертволісих (видано)" } },
    [8471] = { [1] = "Ритуальний тотем Зимокрайових", [2] = "Ви знайшли один з ритуальних тотемів хутропузів з племені Зимокрайових. Сам тотем абсолютно невимовної конструкції, але здається, що він випромінює почуття відчаю. Якщо є якийсь предмет, який найкраще демонструє занепад, від якого страждають Зимокрайові хутропузи, то це саме він.\n\nОдин з хутропузів у оплоті Деревопузих може знайти застосування такому предмету... якщо ви заслужили їхню довіру настільки, що вони заговорять з вами.", [3] = "Віднесіть ритуальний тотем Зимокрайових в оплот Деревопузих і подивіться, чи знайде хтось із хутропузів застосування цьому предмету. Деревопузі не розмовлятимуть з вами, якщо ви не маєте нейтральної репутації або вище.", [4] = "{Клас:к}, ти {стать:прийшов:прийшла} до нас з миром, але я відчуваю, що ти тут у справах серйозних і важких... як для хутропузів, так і для {раса:р} в рівній мірі. Що ти хочеш сказати нам?", [5] = "Ця річ... вона має форму ритуального тотема Зимокрайових, але його вигини спотворені силами, які я не можу зрозуміти. Те саме прокляття, яке змусило Зимокрайових нападати на нас, безумовно присутнє в цьому предметі.\n\nБожественна мудрість привела цей предмет та тебе до нас, {ім'я}. Ми ретельно дослідимо його. Можливо, колись Зимокрайові перестануть нападати на нас.\n\nДякую, {стать:друже:подруго} — будь ласка, прийми ці подарунки в обмін на твою доброту.", ["en"] = "Winterfall Ritual Totem", ["tasks"] = { ["0 reputation with Timbermaw Hold"] = "0 репутації у фортеці Тимбермау", ["Winterfall Ritual Totem"] = "ритуальний тотем Зимокрайових", ["Winterfall Ritual Totem (Provided)"] = "ритуальний тотем Зимокрайових (видано)" } },
    [84777] = { [1] = "Пір'я для Нафіена", [4] = "Хоча ти й зарекомендував себе переді мною, тобі, можливо, доведеться продовжувати працювати над тим, щоб зарекомендувати себе перед підозрілими братами мого племені. З цією метою я, можливо, зможу продовжувати допомагати тобі.\n\nДеякі фурболги Мертвого Лісу носять особливий головний убір, який можна використовувати як доказ для зменшення їхньої кількості. Принеси мені перо з будь-якого головного убору, який ти придбаєш; за кожен комплект з п'яти, який ти мені принесеш, ти заслужиш визнання серед Лісогубів.", [5] = "Молодець, {ім'я}! Я подбаю про те, щоб твої діяння стали відомими серед мого роду.\n\nНе забудь принести мені будь-яке пір'я, яке знайдеш. Я прийматиму його стільки, скільки буде потрібно.", ["en"] = "Feathers for Nafien" },
    [8481] = { [1] = "Корінь зла", [2] = "{ім'я}, дякую тобі за те, що {стать:знайшов:знайшла} спосіб вирвати корінь зла з душ племені Зимокрайових — знищити демона, який заволодів ними!\n\nВіднеси цей факел до входу до печери верховного вождя Зимокрая і постав його там. Це змусить демона з'явитися. Ось тоді ти зі своїми союзниками нападеш на нього! Тільки сутність загиблого демона допоможе почати довгий процес зцілення племені Зимокрайових... і порятунку оплоту Деревопузих.", [3] = "Встановіть факел виклику демона біля входу до печери верховного вождя Зимокрая в селищі Зимокрайових хутропузів. Здолайте демона та отримайте сутність Зандівія для Ґорна Одноокого з оплоту Деревопузих.", [4] = "Ти {стать:повернувся:повернулася} до нас, {ім'я}... чи означає це, що демона вбито?", [5] = "Ти... ти нас {стать:врятував:врятувала}! Твоя перемога над демоном Зандівієм забезпечила безпеку оплоту Деревопузих на багато років вперед. Ти дійсно {стать:герой:героїня} серед нашого народу.\n\nБудь ласка, прийми це з нашим благословенням. Хоча процес зцілення хутропузів буде повільним, а конфлікт все ще триватиме, ти {стать:дав:дала} Зимокрайовим щось, чого вони не мали до цього дня.\n\nУ них є шанс на виживання.", ["en"] = "The Root of All Evil", ["tasks"] = { ["42000 reputation with Timbermaw Hold"] = "42000 репутації у фортеці Тимбермау", ["Demon Summoning Torch"] = "факел виклику демона", ["Demon Summoning Torch (Provided)"] = "факел виклику демона (видано)", ["Essence of Xandivious"] = "сутність Зандівія", ["Essence of Xandivious (Provided)"] = "сутність Зандівія (видано)" } },
    [84853] = { [1] = "Сліди на снігу", [2] = "Ти зробив гарну послугу, тож тепер я тобі допоможу. Минулого разу, коли я бачив Ван Амбурга, у нього був звіринець із трьох тварин: величезний кіт, хижак і жахливий комаха. Він тримає їх у клітках, б'є батогом, доводить до злості. Жорстокість і голод — його знаряддя для дресирування. Бився з ним у Фераласі деякий час тому, не знаю, де він зараз.\n\nТобі варто зустрітися з Естеленн і дізнатися, чи потребує вона тебе. І обов'язково передай їй від мене привіт.", [3] = "Вирушайте до пагорбів у Зимоключі на півночі Калімдору, на північ від Еверлука, щоб зустрітися з Естеленн та дізнатися, що їй ще потрібно.", [5] = "Залишки старого табору Естеленн холодні. Можливо, вам доведеться трохи почекати на її повернення. Краще влаштовуйтесь зручніше.", ["en"] = "Tracks in the Snow" },
    [84870] = { [1] = "Темний скарб", [2] = "Цей документ — звіт від одного з підлеглих Разоргора. Ходять чутки, що якісь орки з Чорної Скелі ховають у сховищі незаконні магічні артефакти. Незрозуміло, чи це проста контрабанда, чи щось глибше.\n\nУ будь-якому разі, це схоже на прибуткову справу. Краще йти одному, щоб уникнути викриття. Також немає потреби ділити здобич.", [3] = "Вдеріться до комори Шпиля Чорної Скелі та вкрадіть усі цінності, що знаходяться всередині. Ви повинні виконати завдання самостійно.", [5] = "Тепер я бачу, що ти не один з них. Перепрошую.", ["en"] = "The Dark Hoard" },
    [84880] = { [1] = "Ворог мого ворога", [2] = "Мене послали сюди разом із магом, щоб викрасти Клинок Пожирання для Синдикату. Однак, щойно я відчинив замки, він напав на мене. Він забрав клинок собі, а мене залишив помирати.\n\nМага звали Кай. Він приєднався до нас нещодавно; пообіцявши поділитися своїми знаннями про потужний ритуал в обмін на допомогу у викраденні його останнього реагенту.\n\nЦього зрадницького змія та його ритуал потрібно зупинити. Йому це не зійде з рук!", [3] = "У Синдикату назріває жахлива загроза. Хтось у Рейвенгольдті може знати, що робити.", [5] = "Я розумію, чому ви принесли мені це, {клас}. Справді тривожні новини. Ми повинні ретельно обміркувати наш наступний крок. Залиште мене на хвилинку, щоб я міг подумати.", ["en"] = "The Enemy of my Enemy" },
    [84881] = { [1] = "У Тіло Тіней", [2] = "Зрада Кая — це тривожна ознака. Вона вказує на іншу, небезпечнішу організацію.\n\nНаші розвідувальні дані свідчать, що це може бути Тіньова Рада.\n\nОпераційною базою ради є Тіньова Твердість у Фелвуді. Якщо наша інформація правильна, ритуал Кая, ймовірно, буде проведено там. Ви повинні проникнути до Тіньової Твердості, знайти Кая та зупинити його.\n\nВкрай важливо залишатися непоміченим. Якщо Кай дізнається про вашу присутність, він, ймовірно, втече або вас уб'є.", [3] = "Знайдіть Кая в Тіньовій фортеці, що у Фехтвуді, та зупиніть його ритуал. Крім того, принесіть доказ його смерті Фаграду в маєток Рейвенгольдт. Ви повинні йти самі та залишатися непоміченими, поки не знайдете Кая.", [4] = "Ти вже знайшов Кая?", [5] = "Отже, Кай справді був союзником Тіньової Ради. Наслідки такої змови можуть бути величезними.\n\nУспіх вашої місії надав цінні розвідувальні дані та запобіг великій небезпеці для всього Азероту. Чудова робота, {ім'я}.\n\nЩодо цього «Пожирача снів», якого ви повернули: мені страшно подумати, яким би він міг бути, якби Кай завершив свій ритуал. Володійте ним з витонченістю та мудро вибирайте цілі.", ["en"] = "Into the Hold of Shadows" },
    [8492] = { [1] = "Альянсу потрібні злитки міді!", [2] = "Агов, {клас:к}, ти чудово підійдеш для того, щоб взяти участь у підготовці у війні! Нам знадобиться будь-яка допомога, щоб зібрати всі потрібні ресурси для війни в Ан'Кіражі. І сьогодні твій щасливий день!\n\nЯ збираю злитки міді по двадцять штук. Це для гідної справи. Ну що, зможеш допомогти Альянсу?", [3] = "Принесіть 20 злитків міді сержанту Камнеброву у Військову палату Залізогарта.", [4] = "Тобі вдалося зібрати двадцять злитків міді, солдате?", [5] = "Тобі вдалося, {стать:малий:мала}! Зараз ми покладемо ці злитки у купу, а потім використаємо у війні. Саме такі, як ти, змушують мене пишатися службою Альянсу. Молодець, солдате!\n\nЯкщо тобі трапляться ще мідні злитки — обов'язково передай їх мені.", ["en"] = "The Alliance Needs Copper Bars!", ["tasks"] = { ["Copper Bar"] = "злиток міді", ["Copper Bar (Provided)"] = "злиток міді (видано)" } },
    [8493] = { [1] = "Альянсу потрібно більше злитків міді!", [2] = "Знову ти, {клас:к}? Неймовірно! Нам все ще потрібні злитки міді для війни в Ан'Кіражі. Допоможеш нам?", [3] = "Принесіть 20 злитків міді сержанту Камнеброву у Військову палату Залізогарта.", [4] = "Знову ти, {клас:к}? Неймовірно! Злитки, які ти {стать:надав:надала} раніше, підуть на створення різних речей для війни. Я знаю, наприклад, що мідь знадобиться для частин парових танків, а також для невеликого флоту гірокоптерів та іншої техніки.\n\nНе дай цим стосам обманути тебе, нам все ще потрібні злитки міді для війни в Ан'Кіражі. Допоможеш нам?", [5] = "Прекрасна робота! Напевно копатися у шахтах задля міді, а потім ще й переплавляти її — це ще та пригода. Хіба що ти {стать:придбав:придбала} їх на аукціоні. В будь-якому разі, мене все влаштовує. Тебе слід похвалити за твій внесок у війну, {клас:к}. Будь ласка, якщо знайдеш більше злитків міді — не вагайся і неси їх до мене.", ["en"] = "The Alliance Needs More Copper Bars!", ["tasks"] = { ["Copper Bar"] = "злиток міді", ["Copper Bar (Provided)"] = "злиток міді (видано)" } },
    [8494] = { [1] = "Альянсу потрібні злитки заліза!", [2] = "Вітаннячка, {стать:пане:пані} \"гроза мурлоків\", моя ти радість. Поки ти {стать:блукав:блукала} світом в пошуках \"пригод\", ти {стать:міг:могла} і не почути, що Альянс готується до війни в Ан'Кіражі, і йому потрібні злитки заліза... ціла купа злитків. Можеш приносити їх мені по двадцять штук. Ми ж можемо на тебе розраховувати, {клас:к}?", [3] = "Принесіть 20 злитків заліза капралу Карнсу у Військову палату Залізогарта.", [4] = "Якщо у тебе є з собою двадцять злитків заліза, я навіть не хочу знати, куди ти їх {стать:заховав:заховала}.", [5] = "Так-так-так, невже це {ім'я}? Та ще й зі злитками. Можливо, варто до тебе пригледітись. Мені боляче це казати, але дякую тобі за допомогу. Альянс не забуде цього... і я теж. Ну, чого стоїш? Йди допоможи ще кому-небудь зі збором матеріалів.", ["en"] = "The Alliance Needs Iron Bars!", ["tasks"] = { ["Iron Bar"] = "злиток заліза", ["Iron Bar (Provided)"] = "злиток заліза (видано)" } },
    [8495] = { [1] = "Альянсу потрібно більше злитків заліза!", [2] = "Так швидко {стать:повернувся:повернулася}? Не хочеться цього визнавати, {клас:к}, але ти, схоже, все ж чогось та й {стать:вартий:варта}. Як бачиш, нам все ще не вистачає злитків заліза на зброю, броню, парові танки й інші речі для полювання на жуків. Думаю, ти зможеш принести ще з двадцять злитків заліза в перерві між цими своїми походеньками в Зул'Ґуруб, чи де там ви, молодь, зараз зависаєте?", [3] = "Принесіть 20 злитків заліза капралу Карнсу у Військову палату Залізогарта.", [4] = "Так швидко {стать:повернувся:повернулася}? Не хочеться цього визнавати, {клас:к}, але ти, схоже, все ж чогось та й {стать:вартий:варта}. Як бачиш, нам все ще не вистачає злитків заліза на зброю, броню, парові танки й інші речі для полювання на жуків. Думаю, ти зможеш принести ще з двадцять злитків заліза в перерві між цими своїми походеньками в Зул'Ґуруб, чи де там ви, молодь, зараз зависаєте?", [5] = "Певно щось в Смерколіссі здохло. Погляньте-но сюди, це ж {ім'я}, і не з порожніми руками. Невже це двадцять злитків заліза? Це саме те, що мені треба!\n\nЯкщо серйозно, то дякую тобі, {ім'я}. Можеш пишатися собою. А тепер йди звідси та принеси ще більше ресурсів для війни!", ["en"] = "The Alliance Needs More Iron Bars!", ["tasks"] = { ["Iron Bar"] = "злиток заліза", ["Iron Bar (Provided)"] = "злиток заліза (видано)" } },
    [84950] = { [1] = "На холоді", [2] = "У старому таборі є кілька корисних шматків дерева та вражаючий кремінь. Щоб знайти більше слідів Естеленн або дочекатися її повернення, вам потрібно зібрати матеріали для будівництва власного табору, щоб ви могли пережити майбутню снігову бурю.\n\nХоча ви можете уникнути бурі, вирушивши з пагорбів, вам доведеться повернутися, щоб знайти потрібні підказки.", [3] = "Використайте свої запаси для виживання, щоб встановити фундамент для кемпінгу та простий намет.\n\nЯкщо ви втратите фундамент, зробіть новий зі своїх запасів для виживання та принесіть матеріали туди.\n\nНаданий предмет:", [5] = "Намет допоможе захистити вас від негоди, тож ви зможете почекати тут трохи довше, не замерзнувши до смерті.", ["en"] = "Out in the Cold", ["tasks"] = { ["Survival Supplies"] = "Приладдя для виживання" } },
    [8496] = { [1] = "Запаси бинтів", [2] = "Нещодавно ми зазнали серйозних втрат на полі бою, тому наші запаси бинтів закінчуються. Дістань партію засобів першої допомоги й віднеси їх вітрозову Гордому Рогу в Кенарійську цитадель.", [3] = "Принесіть 30 щільних рунічних бинтів, 30 щільних шовкових бинтів і 30 щільних маготканих бинтів вітрозову Гордому Рогу в Кенарійську цитадель, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання X.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "Якраз вчасно. Ці припаси врятують життя. Ми дуже вдячні тобі. Ось твоє наступне завдання.", ["en"] = "Bandages for the Field", ["tasks"] = { ["Heavy Mageweave Bandage"] = "щільний маготканий бинт", ["Heavy Mageweave Bandage (Provided)"] = "щільний маготканий бинт (видано)", ["Heavy Runecloth Bandage"] = "щільний рунічний бинт", ["Heavy Runecloth Bandage (Provided)"] = "щільний рунічний бинт (видано)", ["Heavy Silk Bandage"] = "щільний шовковий бинт", ["Heavy Silk Bandage (Provided)"] = "щільний шовковий бинт (видано)", ["Logistics Task Briefing X"] = "план логістичного завдання X", ["Logistics Task Briefing X (Provided)"] = "план логістичного завдання X (видано)" } },
    [8497] = { [1] = "Набори виживання в пустелі", [2] = "З приходом новобранців в Кенарійську цитадель, постає проблема їхнього виживання в пустелі. Зневоднення, а також численні отруйні істоти становлять серйозну загрозу для недосвідчених добровольців. Збери припаси, необхідні для набору виживання в пустелі й принеси їх до Каландрат в Кенарійську цитадель.", [3] = "Дістаньте 4 сфери води, 4 потужні протиотрути та 4 порції копчених пустельних пельменів та віднесіть їх до Каландрат, в таверну Кенарійської цитаделі, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання I.", [4] = "Маєш щось для мене?", [5] = "Чудова робота, {ім'я}. Нам дуже потрібні ці припаси.", ["en"] = "Desert Survival Kits", ["tasks"] = { ["Globe of Water"] = "куля води", ["Globe of Water (Provided)"] = "куля води (видано)", ["Logistics Task Briefing I"] = "план логістичного завдання I", ["Logistics Task Briefing I (Provided)"] = "план логістичного завдання I (видано)", ["Powerful Anti-Venom"] = "потужна протиотрута", ["Powerful Anti-Venom (Provided)"] = "потужна протиотрута (видано)", ["Smoked Desert Dumplings"] = "копчені пустельні пельмені", ["Smoked Desert Dumplings (Provided)"] = "копчені пустельні пельмені (видано)" } },
    [8498] = { [1] = "Бойові накази Сутінкового Молота", [2] = "Наші розвідники доповіли, що ватажки Сутінкового Молота віддають нові бойові накази. Їх розповсюджують пророки під посиленою охороною. Перехопи накази й віднеси їх командиру Мар'аліту.", [3] = "Отримайте бойові накази Сутінкового Молота та віднесіть їх командиру Мар'аліту з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план тактичного завдання X.", [4] = "Ти {стать:приніс:принесла} щось мені?", [5] = "Чудово. Важливо знати наступний крок ворога. Ця інформація дозволить нам передбачити атаки Сутінкового Молота.", ["en"] = "Twilight Battle Orders", ["tasks"] = { ["Tactical Task Briefing X"] = "план тактичного завдання X", ["Tactical Task Briefing X (Provided)"] = "план тактичного завдання X (видано)", ["Twilight Battle Orders"] = "бойові накази Сутінкового Молота", ["Twilight Battle Orders (Provided)"] = "бойові накази Сутінкового Молота (видано)" } },
    [8499] = { [1] = "Альянсу потрібні злитки торію!", [2] = "Це вкрай люб'язно з твого боку, так перейматися потребами Альянсу. Приготування до війни йдуть повним ходом, і, крім усього іншого, нам потрібно багато злитків торію, за збір яких я й відповідаю. Торій нам знадобиться на створення багатьох речей для майбутньої війни, а особливо парових танків, які будуть переправлені повітрям в Силітус одразу після завершення будівництва. Допоможеш нам з цим, {клас:к}?", [3] = "Принесіть 20 злитків торію мадам Двокосій у Військову палату Залізогарта.", [4] = "Сподіваюся, тобі вже вдалося зібрати необхідну кількість злитків торію?", [5] = "Ох, дякую тобі, {клас:к}! Щиро дякую! Чергові двадцять злитків є, залишилося зібрати ще незліченну кількість. Альянс вдячний тобі, і твої зусилля не залишаться без винагороди. Якщо знайдеш більше злитків торію — принось їх до мене.", ["en"] = "The Alliance Needs Thorium Bars!", ["tasks"] = { ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [8500] = { [1] = "Альянсу потрібно більше злитків торію!", [2] = "Рада знову бачити тебе, {ім'я}. Сподіваюся, у тебе все добре. Так, нам дійсно все ще потрібні злитки торію. Можливо, ти теж хочеш долучитися до збору припасів для війни в Ан'Кіражі?", [3] = "Принесіть 20 злитків торію мадам Двокосій у Військову палату Залізогарта.", [4] = "Рада знову бачити тебе, {ім'я}. Сподіваюся, у тебе все добре. Так, нам дійсно все ще потрібні злитки торію. Можливо, ти теж хочеш долучитися до збору припасів для війни в Ан'Кіражі?", [5] = "Прекрасно, {клас:к}! Гарна робота. Я прослідкую за тим, щоб ці злитки гарно запакували та доставили в руки ковалям та інженерам, що створять озброєння для нашої армії. Дякую ще раз, і якщо будеш проходити повз зі злитками торію — не забудь про мене.", ["en"] = "The Alliance Needs More Thorium Bars!", ["tasks"] = { ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [8501] = { [1] = "Ціль: жалоносці Вул'Аші", [2] = "У міру розростання конфлікту, силітиди в цьому районі становлять дедалі більшу загрозу для наших операцій. Тебе обрали для участі у штурмі Вул'Аші, а твоєю головною ціллю будуть летючі жалоносці Вул'Аші.", [3] = "Вбийте 30 жалоносців Вул'Аші та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання XII.", [4] = "Ти хочеш щось мені сказати, {ім'я}?", [5] = "Чудова робота, {ім'я}. Ми врахуємо твою участь у нападі на Вул'Аші.", ["en"] = "Target: Hive'Ashi Stingers", ["tasks"] = { ["Combat Task Briefing XII"] = "план бойового завдання XII", ["Combat Task Briefing XII (Provided)"] = "план бойового завдання XII (видано)", ["Hive'Ashi Stinger"] = "жалоносець Вул'Аші", ["Hive'Ashi Stinger slain"] = "жалоносець Вул'Аші: убито" } },
    [8502] = { [1] = "Ціль: робітники Вул'Аші", [2] = "У міру розростання конфлікту, силітиди в цьому районі становлять дедалі більшу загрозу для наших операцій. Тебе обрали для участі у штурмі Вул'Аші, а твоєю головною ціллю будуть робітники Вул'Аші.\n\nПро виконання завдання прозвітуй командиру Мар'аліту.", [3] = "Вбийте 30 робітників Вул'Аші та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання III.", [4] = "Ти маєш, про що мені доповісти, {клас:к}?", [5] = "Чудова робота, {ім'я}. Без своїх робітників силітидам буде важко усунути шкоду, завдану їхньому вулику.", ["en"] = "Target: Hive'Ashi Workers", ["tasks"] = { ["Combat Task Briefing III"] = "план бойового завдання III", ["Combat Task Briefing III (Provided)"] = "план бойового завдання III (видано)", ["Hive'Ashi Worker"] = "робітник Вул'Аші", ["Hive'Ashi Worker slain"] = "робітник Вул'Аші: убито" } },
    [8503] = { [1] = "Альянсу потрібна душирість!", [2] = "Тож, {клас:к}, чи казав я тобі, наскільки корисною може бути душирість? Казав? А, ну добре... в будь-якому разі, нам потрібно багато запасів цієї рослини, і коли я кажу багато, я маю на увазі ДУЖЕ БАГАТО! Як гадаєш, ти зможеш нам допомогти з цим? Я розумію, що тобі доведеться лишитися без усіх цих чудових речей, які можна зробити з душирості, але це для доброї справи!", [3] = "Принесіть 20 душиростей рядовому Драксельміру у Військову палату Залізогарта.", [4] = "Брехня! Я ніколи не брав душирість зі стосів. Хоча це неабияка спокуса, враховуючи те, наскільки вона може бути корисною. *Кхм* Ти часом не {стать:приніс:принесла} душирість, про яку я казав раніше?", [5] = "Ура! Іще двадцять штук. Ти просто {стать:найкращий:найкраща}. Гадаю, мені варто упакувати ці рослини, доки вони не зав'янули. Так багато душирості, і так мало часу!\n\nІще раз дякую, {клас:к}!", ["en"] = "The Alliance Needs Stranglekelp!", ["tasks"] = { ["Stranglekelp"] = "душирість", ["Stranglekelp (Provided)"] = "душирість (видано)" } },
    [8504] = { [1] = "Альянсу потрібно більше душирості!", [2] = "І знову привітики... про що це я... А, точно, {ім'я}! Ти {стать:прийшов:прийшла}, щоб дізнатися, чи потрібна мені ще душирість? Що ж, сьогодні твій щасливий день, бо відповідь на це важливе питання дуже чітке — ТАК! Ну як, збереш ще двадцять штук?", [3] = "Принесіть 20 душиростей рядовому Драксельміру у Військову палату Залізогарта.", [4] = "І знову привітики... про що це я... А, точно, {ім'я}! Ти {стать:прийшов:прийшла}, щоб дізнатися, чи потрібна мені ще душирість? Що ж, сьогодні твій щасливий день, бо відповідь на це важливе питання дуже чітке — ТАК! Ну як, збереш ще двадцять штук?", [5] = "Йой, тут ціла купа душирості. Давай-но швиденько покладемо її в коробку, щоб вона не зів'яла. Ти {стать:зробив:зробила} мені... тобто нам, Альянсу, величезну послугу. Я подбаю про те, щоб усі знали, що саме {стать:великий:велика} {ім'я} {стать:зробив:зробила} неоціненний внесок у підготовку до війни в Ан'Кіражі, пожертвувавши стільки душирості!", ["en"] = "The Alliance Needs More Stranglekelp!", ["tasks"] = { ["Stranglekelp"] = "душирість", ["Stranglekelp (Provided)"] = "душирість (видано)" } },
    [8505] = { [1] = "Альянсу потрібен пурпуровий лотос!", [2] = "{Клас:к}, у пурпурового лотоса є безліч застосувань. На прохання Альянсу я відповідаю за заготівлю зібраних трав. І також я маю переконатися, що ми зберемо достатню кількість пурпурового лотоса для задоволення всіх військових потреб.\n\nЯ хочу, щоб ти {стать:зібрав:зібрала} ці квіти для мене. Впораєшся з цим завданням?", [3] = "Принесіть 20 пурпурових лотосів майстру Нічній Пісні у Військову палату Залізогарта.", [4] = "Ти {стать:зібрав:зібрала} пурпуровий лотос, про який я просив?", [5] = "Твій внесок дуже цінний, {клас:к}. Лише завдяки спільним зусиллям ми зможемо відбити армію силітидів та будь-яку силу, що їх направляє. Навіть Орда збирає власні запаси пурпурового лотоса. Тож якщо знайдеш більше цих квітів — повертайся до мене.", ["en"] = "The Alliance Needs Purple Lotus!", ["tasks"] = { ["Purple Lotus"] = "пурпуровий лотос", ["Purple Lotus (Provided)"] = "пурпуровий лотос (видано)" } },
    [8506] = { [1] = "Альянсу потрібно більше пурпурового лотоса!", [2] = "З поверненням, {клас:к}. Наш збір добре просувається, але нам все ще потрібен пурпуровий лотос. Якщо ти ще маєш бажання зібрати трави — принеси їх мені якнайшвидше.", [3] = "Принесіть 20 пурпурових лотосів майстру Нічній Пісні у Військову палату Залізогарта.", [4] = "З поверненням, {клас:к}. Наш збір добре просувається, але нам все ще потрібен пурпуровий лотос. Якщо ти ще маєш бажання зібрати трави — принеси їх мені якнайшвидше.", [5] = "Я з радістю приймаю твій внесок. Твої внески неоціненні й завдяки тобі наші війська отримають додаткові зілля та олії. Дякую тобі, і якщо знайдеш більше пурпурових лотосів — принось їх мені.", ["en"] = "The Alliance Needs More Purple Lotus!", ["tasks"] = { ["Purple Lotus"] = "пурпуровий лотос", ["Purple Lotus (Provided)"] = "пурпуровий лотос (видано)" } },
    [85061] = { [1] = "Полювання на комах", [2] = "Я йшов твоїми слідами і радий бачити, що ти живий! Здається, твої навички виживання такі ж хороші, як я й підозрював. Перепрошую, що змусив тебе чекати.\n\nЯ знайшов більше ознак нашої здобичі. Ван Амбург десь на південному заході Калімдора. Я збираюся вирушити в тому напрямку і продовжувати шукати сліди. Тим часом, можливо, тобі варто потренуватися у стрільбі.\n\nВирушай до Силітуса. Ти можеш допомогти друїдам у фортеці Кенаріона, одночасно відточуючи свої трюкові постріли.", [3] = "Вирушайте до фортеці Кенаріона в Силітусі, на Калімдорі, та поговоріть з друїдами про силітідів, що розвиваються. Допомагайте їм за їхнім проханням, одночасно практикуючи свої навички стрільби.", [5] = "Ласкаво просимо до фортеці Кенаріон. Виглядаєш як здібний {клас}, і чесно кажучи, нам завжди потрібна додаткова допомога.", ["en"] = "Bug Hunt" },
    [8509] = { [1] = "Альянсу потрібні сльози Артаса!", [2] = "Одразу до справи, {клас:к}. Альянсу необхідно зібрати величезну кількість сліз Артаса для війни в Ан'Кіражі. Не питай мене навіщо, я просто виконую наказ. Збери якомога більше цих трав і принеси мені. Ну що, візьмешся за це завдання?", [3] = "Принесіть 20 сліз Артаса сержант-майорці Жермейн у Військову палату Залізогарта.", [4] = "Що таке? Кажи, {клас:к}! Тобі вдалося зібрати сльози Артаса?", [5] = "Чудова робота, {клас:к}. Мушу сказати, що я приємно здивована. Ти не повіриш, скільки народу приходить сюди, обіцяючи допомогти, і більше ніколи не повертається. Дозволь мені скласти ці трави в ящик та перерахувати наявні запаси, і тоді ми будемо знати, чи знадобиться мені ще допомога.", ["en"] = "The Alliance Needs Arthas' Tears!", ["tasks"] = { ["Arthas' Tears"] = "сльози Артаса", ["Arthas' Tears (Provided)"] = "сльози Артаса (видано)" } },
    [85093] = { [1] = "НЕВИКОРИСТАНИЙ", [2] = "Я хотів би поговорити з тобою востаннє, перш ніж піду. Будь ласка, зустрінь мене ще раз біля мосту до Андоралу на Пагорбі Скорботи. Ми поміркуємо про те, що сталося, і про жертву Еонаса, яка здобула нам цю перемогу.", ["en"] = "UNUSED" },
    [8510] = { [1] = "Альянсу потрібно більше сліз Артаса!", [2] = "Добре, схоже мені ще знадобляться сльози Артаса. Гадаю, вони ростуть там же, де ти {стать:збирав:збирала} їх минулого разу. Що швидше ми зберемо ці трави, то швидше зможемо почати наступ на Ан'Кіраж.\n\nДопоможеш нам знову, {клас:к}?", [3] = "Принесіть 20 сліз Артаса сержант-майорці Жермейн у Військову палату Залізогарта.", [4] = "Добре, схоже мені ще знадобляться сльози Артаса, {клас:к}. Гадаю, вони ростуть там же, де ти {стать:збирав:збирала} їх минулого разу. Що швидше ми зберемо ці трави, то швидше зможемо почати наступ на Ан'Кіраж.\n\nДопоможеш нам знову, {ім'я}?", [5] = "Просто неймовірно, {ім'я}! Альянс перед тобою в боргу. Я подбаю про те, щоб ці трави зберігалися належним чином, поки хтось не зробить з них щось корисне. Не соромся приходити в будь-який час, особливо, якщо принесеш більше сліз Артаса.", ["en"] = "The Alliance Needs More Arthas' Tears!", ["tasks"] = { ["Arthas' Tears"] = "сльози Артаса", ["Arthas' Tears (Provided)"] = "сльози Артаса (видано)" } },
    [8511] = { [1] = "Альянсу потрібна легка шкіра!", [2] = "У нас, Камнедерів, довга історія шкуродерства, {клас:r}. Ось чому Альянс попросив мою сім'ю допомогти зі збором легкої шкіри для війни в Ан'Кіражі. Я слідкую за тим, щоб шкіра була правильно видублена, для чого вона б там не знадобилася, але нам потрібна твоя допомога.\n\nОскільки я тут слідкую за всім, я попрошу тебе зібрати шкіру та принести її мені. Що на це скажеш, {стать:хлопче:дівчинко}, спробуєш?", [3] = "Принесіть 10 легких шкір Бонні Камнедерці у Військову палату Залізогарта.", [4] = "{Клас:к}, я сподіваюся, ти {стать:приніс:принесла} легку шкіру.", [5] = "Посмію сказати, що Альянс буде дуже задоволений цією шкірою, {клас:к}. Я переконаюся, щоб жодна шкіра не пропала даремно. Дякую тобі, і обов'язково повертайся до мене знову — раптом нам знадобиться більше шкіри.", ["en"] = "The Alliance Needs Light Leather!", ["tasks"] = { ["Light Leather"] = "легка шкіра", ["Light Leather (Provided)"] = "легка шкіра (видано)" } },
    [85112] = { [1] = "Виснажена коса", [2] = "Коса скручена та випромінює дивну демонічну ауру. Незважаючи на це, вона крихка на дотик, і ви хвилюєтеся, що зламається під час використання. Вона висмоктує вашу енергію, ніби випробовуючи вас. Ненажерливий голод чатує десь у вашій свідомості, коли ви думаєте про косу. Можливо, хтось, хто знає про демонічні артефакти, знає більше.", [3] = "Принесіть посох Доану Кархану в Степи.", [5] = "Це справді цікавий артефакт, який ви знайшли, {ім'я}. Я вважаю, що цей посох можна врятувати... хоча це вимагатиме певних зусиль.\n\nХм, він навіть може бути чудовим кандидатом для завершення деяких незавершених справ, які ми маємо.", ["en"] = "The Depleted Scythe" },
    [8512] = { [1] = "Альянсу потрібно більше легкої шкіри!", [2] = "Рада знову тебе бачити, {ім'я}. Виявляється, що нам потрібно більше легкої шкіри на створення різних речей для війни. Якщо ти зможеш принести мені ще десяток — це буде просто чудово.", [3] = "Принесіть 10 легких шкір Бонні Камнедерці у Військову палату Залізогарта.", [4] = "Рада знову тебе бачити, {ім'я}. Виявляється, що нам потрібно більше легкої шкіри на створення різних речей для війни. Якщо ти зможеш принести мені ще десяток — це буде просто чудово.", [5] = "Дякую тобі за твій щедрий внесок, {ім'я}. Зараз я складу їх до купи, і зовсім скоро ця шкіра піде на створення якихось чудових обладунків, шкіряних латок, чи ще чогось корисного для війни. І схоже, що нам потрібно більше легкої шкіри. Тож повертайся до мене з нею якнайшвидше.", ["en"] = "The Alliance Needs More Light Leather!", ["tasks"] = { ["Light Leather"] = "легка шкіра", ["Light Leather (Provided)"] = "легка шкіра (видано)" } },
    [8513] = { [1] = "Альянсу потрібна середня шкіра!", [2] = "Саме так, {стать:пане:пані}, я відповідаю за збір середньої шкіри, яка знадобиться нам у війні. Якщо зможете зібрати середню шкіру, неважливо звідки, принесіть її мені. Я буду вдячним за будь-яку допомогу в цій справі, якщо у вас знайдеться час.", [3] = "Принесіть 10 середніх шкір рядовому Портеру у Військову палату Залізогарта.", [4] = "Так, {стать:пане:пані}, я пам'ятаю вас. Ви принесли середню шкіру?", [5] = "Ого! Схоже, що ви справді хочете допомогти. Красно вам дякую за такий внесок. Зараз я запакую та порахую цю шкіру. А ви знаєте, як скрасити день звичайному рядовому.", ["en"] = "The Alliance Needs Medium Leather!", ["tasks"] = { ["Medium Leather"] = "середня шкіра", ["Medium Leather (Provided)"] = "середня шкіра (видано)" } },
    [8514] = { [1] = "Альянсу потрібно більше середньої шкіри!", [2] = "Так, {стать:пане:пані}, схоже що ми зібрали багато шматків середньої шкіри, але нам потрібно більше. Я запевняю вас, що вона піде на добру справу, і жоден шматочок не буде змарновано. Я знаю, що багато прошу, але чи не могли б ви допомогти мені зі збором?", [3] = "Принесіть 10 середніх шкір рядовому Портеру у Військову палату Залізогарта.", [4] = "Так, {стать:пане:пані}, схоже що ми зібрали багато шматків середньої шкіри, але нам потрібно більше. Я запевняю вас, що вона піде на добру справу, і жоден шматочок не буде змарновано. Я знаю, що багато прошу, але чи не могли б ви допомогти мені зі збором?", [5] = "Боже правий, ви принесли мені купу середньої шкіри, {стать:пане:пані}! Я простежу, щоб ця шкіра пішла на добру справу. З вашою допомогою ми виконаємо наш план зі збору середньої шкіри раніше строку!\n\nКрасно дякую, {ім'я}!", ["en"] = "The Alliance Needs More Medium Leather!", ["tasks"] = { ["Medium Leather"] = "середня шкіра", ["Medium Leather (Provided)"] = "середня шкіра (видано)" } },
    [8515] = { [1] = "Альянсу потрібна товста шкіра!", [2] = "Ой леле, це буде чудово! {Клас:к}, підготовка до війни в Ан'Кіражі у повному розпалі, і мене назначили відповідальною за всю товсту шкіру, що прибуває сюди. Ми робимо тисячі речей з неї, але спершу нам потрібна ціла тонна товстої шкіри. Це в прямому сенсі!\n\nНу що, зможеш принести мені файний, товстезний стос товстої шкіри? Зможеш, зможеш?!", [3] = "Принесіть 10 товстих шкір Марті Гострошпильці у Військову палату Залізогарта.", [4] = "Невже це товста шкіра у твоєму рюкзаку, {клас:к}? Це вона? Скоріше, давай її сюди! Всі будуть задоволені нами, правда ж?", [5] = "Ох, я знала, що ти впораєшся, {клас:к}, я просто знала це! Я передам шкіру у правильні руки якомога скоріше. А тепер, давай-но подивимося. Хмм, схоже, що наш збір йде досить добре. Поговори зі мною знову коли я закінчу підрахунок, можливо нам знадобиться більше шкіри. І якщо це так, то я хочу, щоб саме ти {стать:добув:добула} її для мене!", ["en"] = "The Alliance Needs Thick Leather!", ["tasks"] = { ["Thick Leather"] = "товста шкіра", ["Thick Leather (Provided)"] = "товста шкіра (видано)" } },
    [85150] = { [1] = "Єдиний хороший жук — це мертвий жук", [2] = "Силітіди постійно змінюються, і наступні покоління набувають нових рис, щоб покращити свою придатність до виживання. Ми помітили новий вид силітідних літунів на північ звідси, поблизу Хайве'Аші. Вони літають, як і деякі інші силітідові оси, але менші, швидші та мають блакитний екзоскелет.\n\nЯ хочу знати, чого очікувати від цих дротиків. Візьміть кількох і повідомте, які вони витривалі.", [3] = "Знайдіть та переможете чотирьох силітідів-дротиків. Це швидкі, маленькі силітідові оси з блакитним екзоскелетом.", [5] = "Тепер ми знаємо, що їх можна вбити. Не такі витривалі, як інші силітіди, кажете ви? Можливо, якась нова розвідувальна форма. Корисна інформація, дякую.", ["en"] = "The Only Good Bug is a Dead Bug" },
    [8516] = { [1] = "Альянсу потрібно більше товстої шкіри!", [2] = "Так, стоси не такі вже і високі, {ім'я}, ми все іще не досягли своєї мети зі збору товстої шкіри... Просто подумай, що ми могли б зробити з усією цією шкірою! Ми могли б зробити всі види обладунків та зброї, речі для парових танків, приціли для рушниць, а також інженерні окуляри! І якщо у нас залишиться зайва шкіра — ми можемо віддати її Орді для їхніх дирижаблів!\n\nТи принесеш мені ще товстої шкіри?", [3] = "Принесіть 10 товстих шкір Марті Гострошпильці у Військову палату Залізогарта.", [4] = "Так, стоси не такі вже і високі, {ім'я}, ми все іще не досягли своєї мети зі збору товстої шкіри... Просто подумай, що ми могли б зробити з усією цією шкірою! Ми могли б зробити всі види обладунків та зброї, речі для парових танків, приціли для рушниць, а також інженерні окуляри! Без окулярів життя не те!\n\nТи принесеш мені ще товстої шкіри?", [5] = "Ти знову {стать:зробив:зробила} це! Це неймовірно, як ти ідеш туди, збираєш всі ці речі, а потім приносиш їх сюди та віддаєш їх мені. Я тобі кажу, коли всі дізнаються, скільки разів ти {стать:допомагав:допомагала} нам, ти й кроку спокійно не зможеш зробити без натовпу, що буде просити у тебе автографи!\n\nДякую іще раз за твій щедрий внесок товстої шкіри, {ім'я}.", ["en"] = "The Alliance Needs More Thick Leather!", ["tasks"] = { ["Thick Leather"] = "товста шкіра", ["Thick Leather (Provided)"] = "товста шкіра (видано)" } },
    [8517] = { [1] = "Альянсу потрібні лляні бинти!", [2] = "Війна в Ан'Кіраджі буде довгою та кривавою. Альянс вчинив дуже мудро, залучившись допомогою таких, як ти, щоб зібрати потрібну кількість припасів перед тим, як зануритися з головою у конфлікт.\n\nМені доручили збирати лляні бинти, і я сподіваюся, що ти допоможеш мені. Це не так легко, але принаймні, лляні бинти не так вже й важко робити. Допоможеш, {клас:к}?", [3] = "Принесіть 20 лляних бинтів стражниці Срібнонебесній у Військову палату Залізогарта.", [4] = "У тебе є двадцять лляних бинтів, {клас:к}?", [5] = "Багатьом солдатам знадобляться твої сьогоднішні внески, {клас:к}, і вони у тебе в боргу. Я особисто простежу, щоб Альянс дізнався про твої зусилля. Дозволь мені належним чином упакувати ці бинти та внести їх в журнал, а потім поговори зі мною знову, раптом мені знадобиться ще.\n\nНехай світло Елуни сяє над тобою, {раса:к}!", ["en"] = "The Alliance Needs Linen Bandages!", ["tasks"] = { ["Linen Bandage"] = "лляний бинт", ["Linen Bandage (Provided)"] = "лляний бинт (видано)" } },
    [8518] = { [1] = "Альянсу потрібно більше лляних бинтів!", [2] = "Мене завжди приголомшує самовідданість, адже зазвичай всі більше схильні до егоїзму. {Клас:к}, мені все ще потрібно зібрати деяку кількість лляних бинтів, щоб виконати свою норму. Чи не допоможеш мені ще раз?", [3] = "Принесіть 20 лляних бинтів стражниці Срібнонебесній у Військову палату Залізогарта.", [4] = "Мене завжди приголомшує самовідданість, адже зазвичай всі більше схильні до егоїзму. {Клас:к}, мені все ще потрібно зібрати деяку кількість лляних бинтів, щоб виконати свою норму. Чи не допоможеш мені ще раз?", [5] = "Ти заслуговуєш на похвалу, {ім'я:к}. Поки дехто намагається нажитися на підготовці до війни, ти вже вкотре доводиш свою вірність Альянсу та й всьому Азероту.\n\nНехай благословення Елуни завжди буде з тобою!", ["en"] = "The Alliance Needs More Linen Bandages!", ["tasks"] = { ["Linen Bandage"] = "лляний бинт", ["Linen Bandage (Provided)"] = "лляний бинт (видано)" } },
    [8519] = { [1] = "Пішак на дошці вічності", [2] = "Заспокоївшись та сфокусувавши свій погляд на кристалі, ви помічаєте, що в ньому щось рухається. Підійшовши ближче, ви розумієте, що дивитеся у минуле... спогади... давно забуті.", [3] = "Дізнайтеся все, що зможете про минуле, а потім прямуйте в Танаріс й поговоріть з Анахроносом у Печерах Часу.", [5] = "Після зради Оленерога я зібрав розбиті частини скіпетра Мінливих Пісків та повернувся сюди. Я хотів захистити скіпетр від тих, хто намагався заволодіти ним, щоб нашкодити нашому світу — так були створені роди драконів.\n\nТі, хто свідомо хоче творити хаос, не зможуть відновити скіпетр, розділений між чотирма могутніми Аспектами... принаймні, я так думав. Яким же я дурнем був. Мене й дотепер переслідують ці прокляті дракони.", ["en"] = "A Pawn on the Eternal Board", ["tasks"] = { ["The War of the Shifting Sands"] = "Війна Мінливих Пісків" } },
    [8520] = { [1] = "Альянсу потрібні шовкові бинти!", [2] = "З наближенням війни в Ан'Кіражі, ми маємо зробити все можливе, щоб переконатися, що наші солдати мають все необхідне. І саме це ми тут й робимо. Мене назначили відповідальною за збір шовкових бинтів.\n\nЯк гадаєш, {клас:к}, зможеш допомогти мені?", [3] = "Принесіть 20 шовкових бинтів медсестрі Кам'янопільській у Військову палату Залізогарта.", [4] = "Привіт, {клас:к}, ти {стать:приніс:принесла} двадцять шовкових бинтів?", [5] = "<Клас>, ти молодець! Завдяки тобі ми ще на крок наблизилися до нашої мети зі збору запасів бинтів. Дай-но я віднесу їх на зберігання, і ми зможемо поговорити ще.", ["en"] = "The Alliance Needs Silk Bandages!", ["tasks"] = { ["Silk Bandage"] = "шовковий бинт", ["Silk Bandage (Provided)"] = "шовковий бинт (видано)" } },
    [8521] = { [1] = "Альянсу потрібно більше шовкових бинтів!", [2] = "Це дуже мило з твого боку, знову запропонувати мені допомогу, {клас:к}. Схоже, що нам ще не вдалося зібрати необхідну кількість шовкових бинтів, тож ми з радістю приймемо ще.", [3] = "Принесіть 20 шовкових бинтів медсестрі Кам'янопільській у Військову палату Залізогарта.", [4] = "Це дуже мило з твого боку, знову запропонувати мені допомогу, {клас:к}. Схоже, що нам ще не вдалося зібрати необхідну кількість шовкових бинтів, тож ми з радістю приймемо ще. {ім'я}, у тебе вийде дістати ще двадцяти штук та принести їх мені? Я була б вдячна тобі від імені всього Альянсу.", [5] = "Ти {стать:такий самовідданий:така самовіддана}, {ім'я}. Красно дякую тобі за твої внески у підготовку до війни. Саме від таких, як ти, і залежить, переможемо ми чи програємо в Ан'Кіражі. Я сподіваюся, що всього цього буде достатньо.\n\nЩе раз дякую, {ім'я}.", ["en"] = "The Alliance Needs More Silk Bandages!", ["tasks"] = { ["Silk Bandage"] = "шовковий бинт", ["Silk Bandage (Provided)"] = "шовковий бинт (видано)" } },
    [8522] = { [1] = "Альянсу потрібні рунічні бинти!", [2] = "Ми можемо сперечатися про доцільність війни скільки завгодно, {клас:к}, але вона вже розпочалася. Озирнися навколо, поглянь на своїх рідних і близьких, а потім запитай себе, що ти можеш зробити, щоб переконатися, що всі вони будуть у безпеці та зможуть пережити цю війну?\n\nСаме тому я збираю рунічні бинти, звідки б їх не приносили. Бажаєш зробити внесок?", [3] = "Принесіть 20 рунічних бинтів хранителю Місячній Тіні у Військову палату Залізогарта.", [4] = "Дні минають один за одним, а ми продовжуємо готуватися. {Клас:к}, ти {стать:приніс:принесла} рунічні бинти?", [5] = "Твоя наполегливість заслуговує на похвалу, {клас:к}. Тепер я маю скласти ці бинти, а потім ми зможемо поговорити знову. Можливо тобі доведеться дістати більше рунічних бинтів.", ["en"] = "The Alliance Needs Runecloth Bandages!", ["tasks"] = { ["Runecloth Bandage"] = "рунічний бинт", ["Runecloth Bandage (Provided)"] = "рунічний бинт (видано)" } },
    [8523] = { [1] = "Альянсу потрібно більше рунічних бинтів!", [2] = "Отже, ми знову змушені говорити про нагальні питання, {клас:к}. Хочу ще раз подякувати тобі за минулі внески, мало хто демонструє таку самовідданість. Але в нас є ще багато роботи.\n\n{ім'я}, чи зможеш ти знову принести мені рунічні бинти?", [3] = "Принесіть 20 рунічних бинтів хранителю Місячній Тіні у Військову палату Залізогарта.", [4] = "Отже, ми знову змушені говорити про нагальні питання, {клас:к}. Хочу ще раз подякувати тобі за минулі внески, мало хто демонструє таку самовідданість. Але в нас є ще багато роботи.\n\n{ім'я}, чи зможеш ти знову принести мені рунічні бинти?", [5] = "Я радий, що ми разом опинилися на цьому шляху, {ім'я}. З тобою приємно працювати. Ще раз дякую тобі за твої зусилля від імені всього Альянсу. Приходь поговорити зі мною знову, як матимеш нагоду.", ["en"] = "The Alliance Needs More Runecloth Bandages!", ["tasks"] = { ["Runecloth Bandage"] = "рунічний бинт", ["Runecloth Bandage (Provided)"] = "рунічний бинт (видано)" } },
    [8524] = { [1] = "Альянсу потрібен веселковий тунець!", [2] = "Здоров, {стать:друже:подруго}! Якби я запитав у тебе: \"Як ти думаєш, чи потрібно солдатам харчуватися їжею як всім іншим?\", ти б, звісно, {стать:відповів:відповіла}: \"Так\". І я згоден з тобою на всі 110%! Я радий, що ми порозумілися. Все, що мені потрібно від тебе — вирушити на риболовлю та виловити цілу купу веселкових тунців, а потім приготувати їх та принести мені. Ммм, я вже відчуваю цей неперевершений смак.", [3] = "Принесіть 20 веселкових тунців Слизькому Гастрогному у Військову палату Залізогарта.", [4] = "Готовий посперечатися, що ти {стать:повернувся:повернулася} з усім необхідним веселковим тунцем, про якого ми говорили раніше. Чи не так, {клас:к}?", [5] = "Два для Альянсу, один для мене, два для Альянсу, один для мене. Агов, рибалко, прекрасна робота! Я вже бачу, що ти принесеш клубу користь. Здається, нам знадобиться більше тунця. Чому б тобі не піти та не зловити ще трохи? Я вже чую, як у мене в животі бурчить.", ["en"] = "The Alliance Needs Rainbow Fin Albacore!", ["tasks"] = { ["Rainbow Fin Albacore"] = "веселковий тунець", ["Rainbow Fin Albacore (Provided)"] = "веселковий тунець (видано)" } },
    [85248] = { [1] = "Всім відомо, що комахи не вміють літати", [2] = "З ваших звітів випливає, що ці дротики безумовно швидші, але нам потрібно дізнатися про них більше. Якщо ми зможемо вивчити одну з них, можливо, ми зможемо з'ясувати, як її ефективніше нейтралізувати.\n\nЗавдяки вашим мисливським навичкам, ви зможете знешкодити одну з дротиків і повернути її сюди, щоб ми могли дізнатися про неї більше. Відстежте одну, пораніть її, зв'яжіть мотузкою та поверніть сюди, до клітки, яку ми встановили для дослідження.", [3] = "Бийся з силітідським дротиком, доки не ослабиш його, потім скористайся навичкою «Струсний постріл», щоб уповільнити його. Коли він впаде в шаленство, скористайся «Заспокійливим пострілом», щоб знепритомніти. Зв'яжи його, перетягни назад до фортеці Кенаріона та прикріпи до стовпа навпроти бойової кімнати командира Мар'аліт для подальшого вивчення.\n\nПовернися до командира Мар'аліт у фортеці Кенаріона, коли закінчиш.\n\nВи можете вивчити «Заспокійливий постріл» під час рейду на Розплавлене Ядро.", [4] = "Пам'ятайте, спочатку послабте дартера, а потім спробуйте вивести його з ладу за допомогою струсу мозку та транквілізаторів.", [5] = "Стерлінгова робота. Ваші навички вже показали нам один спосіб їх нейтралізувати, і ми зможемо дізнатися більше про дартерів, спостерігаючи за цим полоненим.", ["en"] = "Everyone Knows That Bugs Can't Fly" },
    [8525] = { [1] = "Альянсу потрібно більше веселкового тунця!", [2] = "Що? Знову ти? А най його, будь я вуйком мавпи... хоча я гном. Слизький Гастрогном, якщо бути точним! То що, ти {стать:прийшов:прийшла}, щоб знову допомогти, га? Ну, не можу сказати, що я цим незадоволений. Хіба ти не любиш запах всієї цієї їжі? <облизується>\n\nГаразд, годі базікати! Йди звідси та принеси мені більше веселкових тунців!", [3] = "Принесіть 20 веселкових тунців Слизькому Гастрогному у Військову палату Залізогарта.", [4] = "Що? Знову ти? А най його, будь я вуйком мавпи... хоча я гном. Слизький Гастрогном, якщо бути точним! То що, ти {стать:прийшов:прийшла}, щоб знову допомогти, га? Ну, не можу сказати, що я цим незадоволений. Хіба ти не любиш запах всієї цієї їжі? <облизується>\n\nГаразд, годі базікати! Йди звідси та принеси мені більше веселкових тунців!", [5] = "Я знав, що у тобі щось є, {стать:малий:мала}. Ти вочевидь завжди знаєш, чого хочеш. Зокрема, ти хочеш догоджати мені та сильним світу цього.\n\nХа-ха, добре, я зараз піду складу цю рибку, а потім ми поглянемо, чи тобі доведеться приготувати ще двадцять рибин.", ["en"] = "The Alliance Needs More Rainbow Fin Albacore!", ["tasks"] = { ["Rainbow Fin Albacore"] = "веселковий тунець", ["Rainbow Fin Albacore (Provided)"] = "веселковий тунець (видано)" } },
    [85250] = { [1] = "Зустріч зі звіринцем", [2] = "Поки тебе не було, нас відвідав вогник, який шукав тебе. Вогник вказав, що ти потрібен у кратері Ун'Горо. Вогник сказав, що твій супутник виявив місцезнаходження ворога, якого ти вже деякий час відстежуєш.\n\nЩе раз дякуємо за твою допомогу. Здається, тобі час рухатися далі.", [3] = "Вирушайте до кратера Ун'Горо, що на півдні Калімдора, та знайдіть докази існування Ван Амбурга.", [5] = "Ти впорався! Я так радий тебе бачити.", ["en"] = "Meeting the Menagerie" },
    [85251] = { [1] = "Розбірка в кратері Ун'Горо", [2] = "Нарешті час. Мене вичерпало всі сили, щоб знайти табір Ван Амбурга тут, і мене поранила одна з його пасток. Його звірі з ним. Ти готовий закінчити це?", [3] = "Вирушайте до табору Ван Амбурга в кратері Ун'Горо, на півдні Калімдора, та переможіть гнома та його звіринець.", [5] = "Готово. Ван Амбург більше не вчинить жодних звірств.", ["en"] = "Showdown at Un'Goro Crater" },
    [8526] = { [1] = "Альянсу потрібні смажені раптори!", [2] = "Йой, як ся маєш, {клас:к}? Я бачу, що ти {стать:зацікавлений:зацікавлена} у зборі їжі для прийдешньої війни в Ан'Кіражі. Чомусь мій тато вирішив, що для мене це буде корисно волонтерити та допомагати тут. Це було великою помилкою. Я навіть запах м'яса не виношу.\n\nХай там як, якщо хочеш — можеш принести мені багато смажених рапторів. Мабуть, це те, чого хочуть їсти всі солдати.", [3] = "Принесіть 20 смажених рапторів Сарі Сумносвист у Військову палату Залізогарта.", [4] = "Ти {стать:приніс:принесла} смажених рапторів?", [5] = "Йой, це чудово. Дякую, що {стать:приніс:принесла} мені цю палену тваринну плоть, {клас:к}. Я просто кину його в цю купку. Впевнена, що хтось попіклується про це м'ясо. Якщо у тебе знайдеться трохи часу, можливо ти захочеш принести мені ще м'яса?", ["en"] = "The Alliance Needs Roast Raptor!", ["tasks"] = { ["Roast Raptor"] = "смажений раптор", ["Roast Raptor (Provided)"] = "смажений раптор (видано)" } },
    [8527] = { [1] = "Альянсу потрібно більше смажених рапторів!", [2] = "І знову привіт, {клас:к}. Я бачу, ти в захваті від всього цього. Тож гадаю, що ти бажаєш принести мені ще двадцять смажених рапторів. Чудово. Так і роби. Побачимося.", [3] = "Принесіть 20 смажених рапторів Сарі Сумносвист у Військову палату Залізогарта.", [4] = "І знову привіт, {клас:к}. Я бачу, ти в захваті від всього цього. Тож гадаю, що ти бажаєш принести мені ще двадцять смажених рапторів. Чудово. Так і роби. Побачимося.", [5] = "Ого, оце так завзяття. Я вже втомлююся, дивлячись на тебе. Хай там як, дякую тобі від Альянсу і все таке. Я простежу, щоб усю цю дохлятину куди-небудь прибрали. Гадаю, ти можеш зайти до мене пізніше, щоб дізнатися, чи не потрібно нам ще. Хоча, як на мене, тут вже починає смердіти.", ["en"] = "The Alliance Needs More Roast Raptor!", ["tasks"] = { ["Roast Raptor"] = "смажений раптор", ["Roast Raptor (Provided)"] = "смажений раптор (видано)" } },
    [8528] = { [1] = "Альянсу потрібен плямистий жовтохвіст!", [2] = "Мабуть, збирання риби може здатися не дуже героїчним, але не варто недооцінювати підготовку, {стать:юний:юна} {клас:к}. Солдатам потрібно харчуватися так само як й іншим, і ми тут для того, щоб переконатися, що наші солдати матимуть при собі все необхідне, коли почнеться війна в Ан'Кіражі.\n\nВідповідно, я збираю плямистих жовтохвостів, універсальний харчовий ресурс, який гарно зберігається та може використовуватися у багатьох стравах. Крім того, ця риба не має запаху притаманного морській рибі. Чи бажаєш ти допомогти мені в цій справі?", [3] = "Принесіть 20 плямистих жовтохвостів мисливиці Стрімкоріці у Військову палату Залізогарта.", [4] = "Ти вже {стать:повернувся:повернулась} з плямистим жовтохвостом, про якого ми говорили?", [5] = "Дякую тобі за цей дар, {клас:к}, і за таку швидкість. Нашим солдатам точно буде що поїсти. Дозволь мені скласти цю рибу належним чином, а потім ми зможемо обговорити наступний внесок, якщо бажаєш.", ["en"] = "The Alliance Needs Spotted Yellowtail!", ["tasks"] = { ["Spotted Yellowtail"] = "плямистий жовтохвіст", ["Spotted Yellowtail (Provided)"] = "плямистий жовтохвіст (видано)" } },
    [8529] = { [1] = "Альянсу потрібно більше плямистих жовтохвостів!", [2] = "Якщо у тебе все ще є бажання допомагати нам, то нам все ще потрібен плямистий жовтохвіст, {ім'я}. Я тільки можу собі уявити, наскільки швидше і легше тобі буде збирати його цього разу — з таким то досвідом! Ну що, допоможеш?", [3] = "Принесіть 20 плямистих жовтохвостів мисливиці Стрімкоріці у Військову палату Залізогарта.", [4] = "Якщо у тебе все ще є бажання допомагати нам, то нам все ще потрібен плямистий жовтохвіст, {ім'я}. Я тільки можу собі уявити, наскільки швидше і легше тобі буде збирати його цього разу — з таким то досвідом! Ну що, допоможеш?", [5] = "Ти дбаєш про потреби Альянсу, як про свої власні, {ім'я}. Твої зусилля не залишаться непоміченими. І дякую тобі за приготування рибини. Я прослідкую, щоб її гарно запакували, і тоді я оновлю свій підрахунок. Кожна рибина все ближче наближає нас до нашої мети.", ["en"] = "The Alliance Needs More Spotted Yellowtail!", ["tasks"] = { ["Spotted Yellowtail"] = "плямистий жовтохвіст", ["Spotted Yellowtail (Provided)"] = "плямистий жовтохвіст (видано)" } },
    [8530] = { [1] = "Альянсу потрібні обпалені вулканічні камені!", [2] = "{Клас:к}, мені потрібна твоя допомога. У Вогняних Надрах є камені — обпалені вулканічні камені, якщо бути точним. Нам потрібно зібрати їх для війни в Ан'Кіражі. Мені сказали, що наші ковалі та інженери можуть зробити з них гарні речі. Мені потрібно, щоб ти {стать:відправився:відправилася} до Палаючого Ядра та {стать:зібрав:зібрала} стільки каменів, скільки зможеш. Звичайно, ти захочеш поговорити зі своїми тридцятьма дев'ятьма друзями, щоб вони пішли з тобою.", [3] = "Принесіть 50 обпалених вулканічних каменів командиру Дужомолоту у Військову палату Залізогарта.", ["en"] = "The Alliance Needs Singed Corestones!", ["tasks"] = { ["Singed Corestone"] = "обпалений вулканічний камінь" } },
    [85304] = { [1] = "Сутність вогню", [2] = "Цей сувій випромінює вогняну енергію, на відміну від інших сувоїв, які ви знайшли. Поблизу Драко'дара в Палаючих Степах є Магічний Камінь, який може допомогти розкрити його призначення. Перекладіть сувій і дізнайтеся його призначення, перш ніж принести свої знахідки бібліотекарям Штормовія або Підмістя.", [3] = "З'ясуйте, для чого потрібен цей незвичайний сувій, і повідомте про свої знахідки бібліотекареві у Штормовії або Підмісті.", [4] = "Ви знайшли щось цікаве?", [5] = "Ви знайшли щось справді цікаве, {ім'я}.", ["en"] = "Essence of Fire" },
    [8531] = { [1] = "Альянсу потрібно більше обпалених вулканічних каменів!", [2] = "Дякую, що {стать:повернувся:повернулася}, {ім'я}. Якщо твої друзі все іще з тобою, я попрошу вас повернутися до Палаючого Ядра та продовжувати збирати обпалені вулканічні камені. Що скажеш?", [3] = "Принесіть 50 обпалених вулканічних каменів командиру Дужомолоту у Військову палату Залізогарта.", ["en"] = "The Alliance Needs More Singed Corestones!" },
    [8532] = { [1] = "Орді потрібні злитки міді!", [2] = "Я такий радий, що ти {стать:вирішив:вирішила} допомогти мені. Не кожен би погодився, тому я маю переконатися, щоб ти {стать:зрозумів:зрозуміла}, що конкретно мені потрібно. Мідні злитки, не мідна руда. У нас немає ані часу, ані людей, щоб займатися переплавкою самостійно, тому, будь {стать:ласкавим:ласкавою}, займися цією справою. Твої зусилля не залишаться непоміченими. Ну що, впораєшся з цим завданням, {клас:к}?", [3] = "Принесіть 20 злитків міді шахтарю Кромвелю в долину Духів в Орґріммарі.", [4] = "Сподіваюся, ти {стать:приніс:принесла} злитки міді, {клас:к}.", [5] = "Так, ці злитки підійдуть. Дякую, що не {стать:полірував:полірувала} їх. Адже немає сенсу робити злитки красивими, якщо вони все одно підуть на військове озброєння. Я попіклуюся про те, щоб вони пішли на користь. Поговори зі мною знову, якщо захочеш віддати мені ще двадцять злитків.", ["en"] = "The Horde Needs Copper Bars!", ["tasks"] = { ["Copper Bar"] = "злиток міді", ["Copper Bar (Provided)"] = "злиток міді (видано)" } },
    [8533] = { [1] = "Орді потрібно більше злитків міді!", [2] = "Вже {стать:повернувся:повернулася}? Ти {стать:був би непоганим шахтарем:була б непоганою шахтаркою}, {клас:к}. Ну, ти вже що робити: мені потрібно, щоб ти {стать:пішов:пішла} та {стать:добув:добула} мідну руду, {стать:переплавив:переплавила} її у злитки, а потім {стать:приніс:принесла} мені. Я знаю, що ти на це {стать:здатен:здатна}, питання лиш в тому, чи хочеш ти?", [3] = "Принесіть 20 злитків міді шахтарю Кромвелю в долину Духів в Орґріммарі.", [4] = "Вже {стать:повернувся:повернулася}? Ти {стать:був би непоганим шахтарем:була б непоганою шахтаркою}, {клас:к}. Ну, ти вже що робити: мені потрібно, щоб ти {стать:пішов:пішла} та {стать:добув:добула} мідну руду, {стать:переплавив:переплавила} її у злитки, а потім {стать:приніс:принесла} мені. Я знаю, що ти на це {стать:здатен:здатна}, питання лиш в тому, чи хочеш ти?", [5] = "Ти знову {стать:довів, чого вартий:довела, чого варта}, {клас:к}. Я прослідкую, щоб цю мідь використали за призначенням. А зараз мені потрібно скласти ці злитки та перерахувати їх. Якщо у тебе ще є натхнення — можеш принести ще більше злитків міді.", ["en"] = "The Horde Needs More Copper Bars!", ["tasks"] = { ["Copper Bar"] = "злиток міді", ["Copper Bar (Provided)"] = "злиток міді (видано)" } },
    [8534] = { [1] = "Звіт розвідника Вул'Зори", [2] = "Ми відправили наших найкращих розвідників всередину вуликів силітидів, щоб зібрати дані. Розвідниця Азенель вже кілька днів спостерігає за пересуванням силітидів у Вул'Зорі. Знайди її й забери письмовий звіт. {ім'я}, ми маємо якнайшвидше отримати ці дані, щоб почати діяти.", [3] = "Зв'яжіться з кенарійською розвідницею Азенель у Вул'Зорі та принесіть звіт розвідниці Вул'Зори вітрозову Гордому Рогу в Кенарійську цитадель. Щоб виконати це завдання, потрібно мати з собою план тактичного завдання VI.", [4] = "Ти знайдеш розвідницю Азенель всередині Вул'Зори. Поспіши, {ім'я}! Немає часу на зволікання.", [5] = "Ми дуже цінуємо твої зусилля, {ім'я}. Я прочитаю ці звіти прямо зараз, можеш переходити до наступного завдання.", ["en"] = "Hive'Zora Scout Report", ["tasks"] = { ["Hive'Zora Scout Report"] = "звіт розвідниці Вул'Зори", ["Hive'Zora Scout Report (Provided)"] = "звіт розвідниці Вул'Зори (видано)", ["Tactical Task Briefing VI"] = "план тактичного завдання VI", ["Tactical Task Briefing VI (Provided)"] = "план тактичного завдання VI (видано)" } },
    [8535] = { [1] = "Сивий храмовник", [2] = "Сутінковий Молот і елементалі, яким вони поклоняються, становлять величезну загрозу для нашої діяльності у Силітусі. Враховуючи, що у нас з'явилися нові вороги всередині Ан'Кіражу, ми не можемо дозволити собі послабити пильність до ворогів ззовні.\n\nЗнайди спосіб викликати та знищити сивого храмовника і повідом про виконання завдання Бора Дику Гриву.", [3] = "Викличте та вбийте сивого храмовника і повідомте про виконання завдання Бора Дику Гриву в Кенарійській цитаделі. Щоб виконати це завдання, потрібно мати з собою план тактичного завдання IV.", [4] = "Ти вже {стать:виконав:виконала} завдання, {ім'я}?", [5] = "Гарна робота, {ім'я}. Ось твоє наступне завдання.", ["en"] = "Hoary Templar", ["tasks"] = { ["Hoary Templar"] = "сивий храмовник", ["Hoary Templar slain"] = "сивий храмовник: убито", ["Tactical Task Briefing IV"] = "план тактичного завдання IV", ["Tactical Task Briefing IV (Provided)"] = "план тактичного завдання IV (видано)" } },
    [8536] = { [1] = "Земляний храмовник", [2] = "Сутінковий Молот і елементалі, яким вони поклоняються, становлять величезну загрозу для нашої діяльності у Силітусі. Враховуючи, що у нас з'явилися нові вороги всередині Ан'Кіражу, ми не можемо дозволити собі послабити пильність до ворогів ззовні.\n\nЗнайди спосіб викликати та знищити земляного храмовника і повідом про виконання завдання Бора Дику Гриву.", [3] = "Викличте та вбийте земляного храмовника і повідомте про виконання завдання Бора Дику Гриву в Кенарійській цитаделі. Щоб виконати це завдання, потрібно мати з собою план тактичного завдання III.", [4] = "Ти вже {стать:виконав:виконала} завдання, {ім'я}?", [5] = "Гарна робота, {ім'я}. Ось твоє наступне завдання.", ["en"] = "Earthen Templar", ["tasks"] = { ["Earthen Templar"] = "земляний храмовник", ["Earthen Templar slain"] = "земляний храмовник: убито", ["Tactical Task Briefing III"] = "план тактичного завдання III", ["Tactical Task Briefing III (Provided)"] = "план тактичного завдання III (видано)" } },
    [8537] = { [1] = "Багряний храмовник", [2] = "Сутінковий Молот і елементалі, яким вони поклоняються, становлять величезну загрозу для нашої діяльності у Силітусі. Враховуючи, що у нас з'явилися нові вороги всередині Ан'Кіражу, ми не можемо дозволити собі послабити пильність до ворогів ззовні.\n\nЗнайди спосіб викликати та знищити багряного храмовника і повідом про виконання завдання Бора Дику Гриву.", [3] = "Викличте та вбийте багряного храмовника і повідомте про виконання завдання Бора Дику Гриву в Кенарійській цитаделі. Щоб виконати це завдання, потрібно мати з собою план тактичного завдання II.", [4] = "Ти вже {стать:виконав:виконала} завдання, {ім'я}?", [5] = "Гарна робота, {ім'я}. Ось твоє наступне завдання.", ["en"] = "Crimson Templar", ["tasks"] = { ["Crimson Templar"] = "багряний храмовник", ["Crimson Templar slain"] = "багряний храмовник: убито", ["Tactical Task Briefing II"] = "план тактичного завдання II", ["Tactical Task Briefing II (Provided)"] = "план тактичного завдання II (видано)" } },
    [8538] = { [1] = "Чотири герцоги", [2] = "Зв'язок між Сутінковим Молотом і Радою Безодні виявився важливішим, ніж ми очікували.\n\nМи вважаємо, що елементалі-володарі, відомі як герцоги Безодні, одні з найвпливовіших лідерів сектантів з Сутінкового Молота. Знайди спосіб заманити чотирьох герцогів Безодні в наш світ і знищити їх!\n\nТвоя відданість та відвага під час виконання минулих завдань наштовхнули нас ще раз обрати тебе для нового завдання. Ми впевнені, що ти успішно виконаєш цю справу.", [3] = "Знайдіть спосіб викликати та вбити герцога попелу, герцога глибин, герцога вітрів і герцога осколків та повідомте про виконання командира Мар'аліта в Кенарійській цитаделі. Щоб виконати це завдання, потрібно мати з собою план тактичного завдання V.", [4] = "Ти вже {стать:виконав:виконала} завдання, {ім'я}?", [5] = "Сьогодні ти {стать:досяг:досягла} великого успіху для нашої справи, {ім'я}. Ти {стать:переміг:перемогла} кількох наших найсильніших ворогів. За це прийми нашу велику подяку.", ["en"] = "The Four Dukes", ["tasks"] = { ["Tactical Task Briefing V"] = "план тактичного завдання V", ["Tactical Task Briefing V (Provided)"] = "план тактичного завдання V (видано)", ["The Duke of Cynders"] = "герцог попелу", ["The Duke of Cynders slain"] = "герцог попелу: убито", ["The Duke of Fathoms"] = "герцог глибин", ["The Duke of Fathoms slain"] = "герцог глибин: убито", ["The Duke of Shards"] = "герцог осколків", ["The Duke of Shards slain"] = "герцог осколків: убито", ["The Duke of Zephyrs"] = "герцог вітрів", ["The Duke of Zephyrs slain"] = "герцог вітрів: убито" } },
    [85385] = { [1] = "Учень бібліотекаря", [2] = "Ваше відкриття Сутності Вогню значно розширило наші знання про аркани. Я чув чутки про подібну силу у Зимоключі, хоча вона має морозну природу. Мій колега в Еверлуці матиме більше інформації щодо подробиць.", [3] = "Поговоріть з Валксом Креклквілом в Еверлуку, щоб дізнатися про чутки.", [5] = "То тебе прислали ті старі йолопи з бібліотеки, га? Вони мене дуже не люблять, кажуть, що «порох і магія несумісні». Тьху.\n\nТак, я дещо знаю про те, про що ти питаєш. На щастя для тебе, я надто зайнятий, щоб сам цим займатися.", ["en"] = "The Librarian's Apprentice" },
    [85386] = { [1] = "Сутність Морозу", [2] = "Колись давно я чув про дивні події в Ущелині Морозного Шепоту. Схоже, ці крижані велетні знайшли якусь давню силу. Я б сам пішов розслідувати, але я тут надто зайнятий. Привези мені щось цікаве, добре? Якщо виживеш, звісно.", [3] = "Дослідіть Ущелину Морозного Шепоту на наявність таємничої крижаної сили.", [4] = "Ти ще не помер? Цікаво.", [5] = "Що це? Там справді щось було?! Я здивований, що ці крижані велетні не перетворили тебе на бурульку, {ім'я}. Молодець.", ["en"] = "Essence of Frost" },
    [85388] = { [1] = "Порушення правил гри", [2] = "Поки тебе не було, я чув, що в Мазторілі відбувається щось дуже неприємне. Здається, це щось у твоєму роді, тож йди подивися, що ти можеш зробити, щоб це вирішити. Ці сині дракони багато знають про аркан, можливо, вони дадуть тобі щось натомість.", [3] = "Зупиніть корупцію в Мазторілі.", [4] = "Ти ще не помер? Цікаво.", [5] = "Ви дуже мені допомогли, {ім'я}. Хоча я боюся, що це ніщо порівняно з героїчними вчинками, які ви для нас здійснили, я хочу, щоб ви це мали. Цей посох неповний, але, можливо, його можна відновити.", ["en"] = "A Foul Interference" },
    [8539] = { [1] = "Ціль: сестри рою Вул'Зори", [2] = "Ми викликали підкріплення для штурму Вул'Зори. Твоє завдання — вбити якомога більше сестер рою Вул'Зори. Коли виконаєш завдання, прозвітуй про це командиру Мар'аліту.", [3] = "Вбийте 30 сестер рою Вул'Зори та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання V.", [4] = "Ти маєш, про що мені доповісти, {клас:к}?", [5] = "Чудова робота, {ім'я}. Ти {стать:гідний союзник:гідна союзниця}.", ["en"] = "Target: Hive'Zora Hive Sisters", ["tasks"] = { ["Combat Task Briefing V"] = "план бойового завдання V", ["Combat Task Briefing V (Provided)"] = "план бойового завдання V (видано)", ["Hive'Zora Hive Sister"] = "сестра рою Вул'Зори", ["Hive'Zora Hive Sister slain"] = "сестра рою Вул'Зори: убито" } },
    [8540] = { [1] = "Чоботи для вартових", [2] = "Кінному підрозділу варти Кенарійської цитаделі не вистачає вишуканих мітрилових чобіт. Дістань нам партію і негайно віднеси її капітану Вішу Козусу в Кенарійську цитадель.", [3] = "Принесіть 3 пари вишуканих мітрилових чобіт Вішу Козусу, капітану вартових Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання II.", [4] = "У тебе є щось для мене?", [5] = "Чудова робота, {ім'я}. Нам саме таких і не вистачало.", ["en"] = "Boots for the Guard", ["tasks"] = { ["Logistics Task Briefing II"] = "план логістичного завдання II", ["Logistics Task Briefing II (Provided)"] = "план логістичного завдання II (видано)", ["Ornate Mithril Boots"] = "вишукані мітрилові чоботи", ["Ornate Mithril Boots (Provided)"] = "вишукані мітрилові чоботи (видано)" } },
    [85401] = { [1] = "Холодний курган", [2] = "Так само, як життя виникає з розпаду, так само неприродне може служити природному.\n\nСерце можна перетворити на посох змінної форми, але мені знадобиться посудина, достатньо міцна, щоб стримати його силу.\n\nПоблизу села Зоряний Пад, у Зимоключі, є курган-лігво. Справжній вхід відкриється лише тоді, коли ви будете самі.\n\nУсередині є хранитель, який давно заблукав; Нандієб. Його посох буде посудиною серця. Мені боляче це припускати, але він більше не той великий хранитель, якого я колись знав.", [3] = "Знайдіть Нандієба в кургані біля села Зорепад у Зимоключі та поверніть його посох. Це потрібно зробити самотужки.", [4] = "Ви знайшли клеймо?", [5] = "Хроматичне серце та посох Нандієба: Разом вони утворять рухомі посох Гла'сіра та Рае'лара. Два об'єкти злоби та руйнування, перетворені на служіння творінню та життю.\n\nЯ дарую цю силу тобі, {ім'я}, у надії, що ти й надалі будеш благородним розпорядником усього життя в Азероті.", ["en"] = "The Frigid Barrow" },
    [8541] = { [1] = "Шліфувальні камені для вартових", [2] = "Вартовим Кенарійської цитаделі не вистачає шліфувальних каменів. Добудь партію каменів й негайно віднеси їх капітану Вішу Козусу в Кенарійську цитадель.", [3] = "Принесіть 10 масивних шліфувальних каменів, 10 твердих шліфувальних каменів і 10 важких шліфувальних каменів Вішу Козусу, капітану вартових Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання III.", [4] = "У тебе є щось для мене?", [5] = "Чудова робота, {ім'я}. Нам саме таких і не вистачало.", ["en"] = "Grinding Stones for the Guard", ["tasks"] = { ["Dense Grinding Stone"] = "масивний шліфувальний камінь", ["Dense Grinding Stone (Provided)"] = "масивний шліфувальний камінь (видано)", ["Heavy Grinding Stone"] = "важкий шліфувальний камінь", ["Heavy Grinding Stone (Provided)"] = "важкий шліфувальний камінь (видано)", ["Logistics Task Briefing III"] = "план логістичного завдання III", ["Logistics Task Briefing III (Provided)"] = "план логістичного завдання III (видано)", ["Solid Grinding Stone"] = "твердий шліфувальний камінь", ["Solid Grinding Stone (Provided)"] = "твердий шліфувальний камінь (видано)" } },
    [8542] = { [1] = "Орді потрібні злитки олова!", [2] = "Лок'тар, {раса:к}, ти певно вже знаєш, що ми ідемо на війну з жуками в Ан'Кіражі. Але воєвождь вирішив, що нам спершу потрібно підготуватися. Хоча я радше б гостив зброю та укріпляв броню, я пишаюся тим, що мене назначили відповідальним за збір злитків олова. Але я не впораюся без твоєї допомоги.\n\nМені потрібно, щоб ти {стать:дістав:дістала} злитки олова і {стать:приніс:принесла} їх мені. Здається, мені знадобиться більше злитків, ніж я можу злічити.", [3] = "Принесіть 20 злитків олова бугаю Мауґу в долину Духів в Орґріммарі.", [4] = "Ну, скільки там в тебе злитків олова, {клас:к}? Думаю, після війни мені варто б навчитися рахувати...", [5] = "Хм, тут ніби стільки, скільки треба. Тільки не намагайся мене обдурити, {клас:к}! У мене від лічби голова болить. Зараз я піду складу ці злитки, а ти йди й принеси мені ще стільки ж.", ["en"] = "The Horde Needs Tin Bars!", ["tasks"] = { ["Tin Bar"] = "злиток олова", ["Tin Bar (Provided)"] = "злиток олова (видано)" } },
    [85423] = { [1] = "Сутність Морозу", ["en"] = "Essence of Frost" },
    [8543] = { [1] = "Орді потрібно більше злитків олова!", [2] = "Дуже добре, бачу, ти серйозно ставишся до війни. Я трохи нервую, чекаючи на її початок, і тому краще не дражни мене своєю неквапливістю й неси злитки. Хм, може, трохи потренуватися на тобі, щоб зняти стрес?\n\nГарр! Ні, напевно не буду. Хто ж мені тоді приноситиме злитки олова?", [3] = "Принесіть 20 злитків олова бугаю Мауґу в долину Духів в Орґріммарі.", [4] = "Дуже добре, бачу, ти серйозно ставишся до війни. Я трохи нервую, чекаючи на її початок, й ти, певно, розумієш мене, {клас:к}. Це буде славно. Орда переможно пронесеться пустелею Силітусу і розгромить цих комах! Ми здобудемо велику славу!\n\nГарр! Але спершу нам потрібно зібрати злитки олова. Цікаво, як така велика війна не може початись без таких маленьких речей.", [5] = "Тром'ка, {ім'я}. Цими злитками олова, ти вшановуєш і мене, і Орду. Я покладу їх до купи, а потім з них зроблять чудові речі. А коли ми закінчимо з цим, ми підемо на війну та покажемо жалюгідному Альянсу як битися з жуками.\n\nА тепер принеси мені ще олов'яних злитків!", ["en"] = "The Horde Needs More Tin Bars!", ["tasks"] = { ["Tin Bar"] = "злиток олова", ["Tin Bar (Provided)"] = "злиток олова (видано)" } },
    [85435] = { [1] = "Порушення правил гри", [2] = "Поки тебе не було, я чув, що в Мазторілі відбувається щось дуже неприємне. Здається, це щось для тебе, тож йди подивися, що ти можеш зробити, щоб це вирішити. Ці сині дракони багато знають про аркани, можливо, вони дадуть тобі щось натомість.\n\nЯ чув, що ти дуже старанно збираєш езотеричні знання. Я знайшов ці сувої, вони можуть стати в нагоді.", [3] = "Зупиніть корупцію в Мазторілі.", ["en"] = "A Foul Interference" },
    [8544] = { [1] = "Наплічники завойовника", [2] = "Як у нас в народі кажуть, що прикрашені наплічні обладунки, які носять смертні, були створені для імітації драконячих крил.\n\nПринеси мені наручі вищих кіразьких лідерів, і я зроблю з них наплічники, страхітливіші за крила самого Нефаріана!", [3] = "Принесіть кіразькі наручі командування, 2 ідоли ночі, 5 кам'яних та 5 глиняних скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} компоненти, які я просила?", [5] = "З матеріалів, які ти {стать:приніс:принесла}, і з луски наших полеглих ворогів, я зроблю для тебе ці напліччя, {стать:смертний:смертна}. Нехай вони нададуть тобі потрібний захист. Нехай їхній вигляд вселяє страх в наших ворогів.", ["en"] = "Conqueror's Spaulders", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Idol of Night"] = "ідол ночі", ["Idol of Night (Provided)"] = "ідол ночі (видано)", ["Qiraji Bindings of Command"] = "кіразькі наручі командування", ["Qiraji Bindings of Command (Provided)"] = "кіразькі наручі командування (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [85441] = { [1] = "Громаан Шукач Вітру", [2] = "Я розповів тобі, що знаю, {ім'я}. Саме ти маєш знайти елементій. Саме ти маєш знищити тілесну форму Володаря Вогню.\n\nЗроби це та отримай благословення Громовержця.", [3] = "Щоб скористатися силою Шукача Вітру, ви повинні подарувати Верховному лорду Демітріану в Кришталевій Долині праву та ліву половини Путів Шукача Вітру, 10 злитків Елементію та Сутність Володаря Вогню.", [4] = "Якщо треба, постав світ на коліна!", [5] = "Навіть у снах я не смів передбачати цей день.\n\nІди, смертний. Звернися до мене знову, коли будеш готовий і захочеш кинути виклик Шукачеві Вітру.", ["en"] = "Thunderaan the Windseeker" },
    [85442] = { [1] = "Огляд посудини", [2] = "Огляньте посудину, яку використовували для вивільнення швидкоплинної бурі. Саме з неї відродився Шукач Вітру, і тепер він черпає нову силу з Кришталевої Долини.", [4] = "Чи скористаєшся ти силою, що міститься в в'язниці Шукачів Вітру?", [5] = "Нехай вас оберігає ваш хрестовий похід. Нехай Господь благословить ваші зусилля.", ["en"] = "Examine the Vessel", ["tasks"] = { ["Vessel of Rebirth"] = "посудина відродження" } },
    [85443] = { [1] = "Повстань, Громолють!", [2] = "Ви перемогли Шукача Вітру. Візьміть сплячий клинок і змусьте поклонника, Демітріана, використати надані вами матеріали, щоб розбудити Громову Лють.", [4] = "<Димитріан благоговіє перед твоєю присутністю.", [5] = "Твоя міць вічно нестиметься вітрами Азероту. Візьми клинок і заспівай про свою бурю.", ["en"] = "Rise, Thunderfury!", ["tasks"] = { ["Item #232018"] = "Товар №232018" } },
    [85445] = { [1] = "Золотий диск", [2] = "Ти не маєш уявлення, що це може бути за предмет, але це явно артефакт значної сили. Тобі слід знайти когось, хто зможе розповісти тобі більше про цей артефакт та його справжнє призначення.", [3] = "Знайдіть когось, хто може розповісти вам більше про Мерехтливий Золотий Диск.", [4] = "Будь ласка, поспішайте, {ім'я}.", [5] = "Зачекай, що це у тебе? Виглядає так, ніби... ні, не може бути. Я бачив це лише в книгах, але... воно було знищене. Напевно, це не...\n\n<Фіксація Гарека на предметі на твоєму поясі на мить порушується, і його очі зустрічаються з твоїми.>\n\nЗвідки у тебе цей предмет, {клас}? Будь ласка, ти повинен надати мені всі подробиці!", ["en"] = "The Golden Disk" },
    [85446] = { [1] = "Луска Володаря Дракона", [2] = "<Ріосус слухає, як ти розповідаєш свою історію>\n\nТак, Гарек мав рацію, це не справжня Душа Дракона... і дякую за це титанам. Я б не почувався комфортніше з таким нерозумним смертним, як ти, який володіє артефактом, настільки потужним, як я, сам Лорд Чорної Скелі. Незважаючи на це, це все ще небезпечно, і нам слід подбати про його утилізацію. Первісну Душу Дракона було нелегко знищити. Давай поговоримо про варіанти утилізації цього меншого симулякра.", [3] = "Поговоріть з Ріосусом і складіть план, як позбутися Симулякра Душі Дракона.", [4] = "...", [5] = "Гарна робота, {клас}. Ну, для смертного, у будь-якому разі. А тепер дай мені луску дракона. З нею у нас є інструменти, необхідні для розкриття таємниць симулякра, і, якщо він знову обернеться проти нас, знищити його.\n\nО, ти виглядаєш здивованим. Ти думав, що ми поспішимо знищити цей дар, не до кінця зрозумівши, на що він здатний, або як його можна використати проти наших ворогів? Дурень.", ["en"] = "Scale of the Dragon Lord" },
    [85447] = { [1] = "Грім Батол", [2] = "Нефаріан давно проводить експерименти, пов'язані з п'ятьма зграями драконів, і, схоже, цей \"симулякр\" Душі Дракона був одним із таких експериментів. Мене здригає думка про те, що могло б вийти з його успішного наслідування навіть частки сили справжньої Душі Дракона. Будь ласка, знайдіть агентів червоних драконів поблизу руїн Грім Батола.\n\nЯ зачарую симулякр, який ви носите, щоб позначити вас як друга червоної зграї.", [3] = "Принесіть Симулякр Душі Дракона ватажку драконячого війська біля входу до фортеці Грім Батол.", [4] = "Хто ти і чому ти смієш постати переді мною, смертний?", [5] = "Ти носиш позначку агента Коріалстраза, але як чужинець, у мене все ще немає іншого вибору, окрім як не довіряти тобі, смертний. Позначка чи ні, я раджу тобі бути обережним, інакше я дозволю моїм драконам спопелити та поглинути тебе.", ["en"] = "Grim Batol", ["tasks"] = { ["Item #231385"] = "Товар №231385" } },
    [8545] = { [1] = "Орді потрібні злитки мітрилу!", [2] = "{Клас:к}, війна наближається і єдине, шо ми можемо зараз зробить — підготуваться до неї. Ми з тобою можем помогти одне одному, {стать:друзяко:подруго}. Як бач, мене назначили відповідальною за збір злитків мітрилу, шо потрібні нам для виготовлення купи речей для війни.\n\nСподіваюсь, ти зможеш добути мітрил і переплавити його в злитки для нас, еге ж?", [3] = "Принесіть 20 злитків мітрилу старшій сержантці Т'келі в долину Духів в Орґріммарі.", [4] = "Звісно, було б непогано зібрать всі злитки мітрилу для війни в Ан'Кіражі. Тому ж ти й тут, друзяко? {стать:Приніс:Принесла} злитки?", [5] = "Непоганий початок, {клас:к}. І от ще двадцять злитків мітрилу, які я покладу в стос та впишу журнал. Все це піде на виготовлення військового спорядження.\n\nОбов'язково повертайся до мене знов, бо нам знадобиться ще більше мітрилу.", ["en"] = "The Horde Needs Mithril Bars!", ["tasks"] = { ["Mithril Bar"] = "злиток мітрилу", ["Mithril Bar (Provided)"] = "злиток мітрилу (видано)" } },
    [85453] = { [1] = "Жоден добрий вчинок не залишається безкарним", [2] = "З огляду на це, боюся, ти вже вичерпав себе. Але не хвилюйся, я й не подумаю залишити твою службу без винагороди, тому я збираюся дарувати тобі честь бути поглинутим мною в моїй справжній формі. Це справді велика честь, {клас}.", [3] = "Захищайся від Ріосустраза!", [5] = "Будь ласка, {клас}. Прийміть мої вибачення за це жорстоке поводження. Ви зробили нам велику послугу. Ви не лише завдали нищівного удару по чорному драконовому роду, але й знайшли небезпечну зброю, яку можна було б використати для перемоги над усім драконячим родом.\n\nЗапевняю вас, на відміну від мого норовливого брата, я сплачую борги перед своїм родом.", ["en"] = "No Good Deed Goes Unpunished" },
    [85454] = { [1] = "Справедлива винагорода", [2] = "Ти багато зробив для захисту нашого виводку, {клас}. Здається доречним, що ми віддячимо тобі даром, який ти зможеш використати, щоб продовжувати захищати інших. Поговори зі мною, коли будеш готовий, і ми разом знищимо цю фальшиву Душу Дракона. Я вірю, що можу використати частину енергії, що вивільняється, коли магія симулякра розсіюється, разом з частинкою власної магії, щоб створити для тебе щось особливе.", [3] = "Поговоріть з Красусом, щоб знищити Симулякрум Душі Дракона та отримати свою нагороду.", [5] = "Не можу сказати, що я коли-небудь використовував магію для створення щита, але результати досить вражаючі, якщо я міг би бути таким пихатим, щоб сам так сказати.\n\nНа цьому наша справа завершена, і я маю вирушати. Використовуй це добре для захисту тих, хто найбільше потребує твого захисту.\n\nПрощавай, смертний.", ["en"] = "A Just Reward" },
    [8546] = { [1] = "Орді потрібно більше злитків мітрилу!", [4] = "Йо, рада, шо ти тут, друзяко. Ти вже раз {стать:поміг:помогла} мені, і я хочу, шоб ти знов це {стать:зробив:зробила}. Нам все ще потрібні злитки мітрилу для підготовки до війни. З них вийде хороша броня, зброя та інші штуки, що розквасять цих бісових жуків в Ан'Кіражі.\n\nЯкшо ти {стать:справжній друг:справжня подруга} — принеси злитки мітрилу. Я візьму все, шо в тебе є, поки не виконаю норму. Ти ж зможеш дістать ше?", [5] = "Хороша робота, {ім'я}! Ми ближче до мети ше на двадцять злитків, і ми зможемо зробить більше військового спорядження. Я простежу, щоб їх зпакували. І якщо найдеш ше стос злитків — обов'язково принось їх мені.", ["en"] = "The Horde Needs More Mithril Bars!", ["tasks"] = { ["Mithril Bar"] = "злиток мітрилу", ["Mithril Bar (Provided)"] = "злиток мітрилу (видано)" } },
    [85468] = { [1] = "Душа пустощів", [2] = "Дивлячись на цю цікаву косу, яку ви принесли, я вважаю, що нам потрібно дати їй душі, щоб відновити її. Почнемо з бісів. У мене є помічник у Східних Чумних Землях поблизу Нортдейла, який може вам допомогти. Назвіть моє ім'я, і він буде більш поступливим. Зустрінемося в каплиці Надії Світла, коли ви закінчите.", [3] = "Переконайте Ксірата поблизу Норддейла у Східних Чумних землях, щоб він допоміг вам отримати Душу Шалості та використати її на Виснаженій Косі Хаосу.", [4] = "Все йде добре?", [5] = "Чудова робота, {ім'я}, схоже, коса повертає собі силу. О, Ксірат? Шкода, що він зрештою нас обдурив. Доведеться знайти нового спільника. Наступного разу спробуємо збільшити силу душі.", ["en"] = "Soul of Mischief" },
    [8548] = { [1] = "Спорядження добровольців", [2] = "Відзнаки, які ти отримуєш, виконуючи бойові, логістичні та тактичні завдання для Кенарійської цитаделі, — це не просто прикраси, {ім'я:к}.\n\nНе загуби їх. Довівши свою відданість нашій організації, ти зможеш отримати частину спорядження, яке ми зберігаємо для наших найближчих союзників, в обмін на ці відзнаки.", [3] = "Принесіть 5 бойових, 3 логістичні й 7 тактичних кенарійських відзнак Варґусу в Кенарійську цитадель, що в Силітусі. Вам також потрібно заслужити дружні відносини з Кенарійським Колом, щоб завершити це завдання.", [4] = "Ми зацікавлені в тому, щоб наші союзники були добре споряджені, {ім'я}.", [5] = "Чудова робота, {ім'я:к}. Будь ласка, прийми це від імені Кенарійського Кола. Це, безперечно, заслужена винагорода, {стать:друже:подруго}!", ["en"] = "Volunteer's Battlegear", ["tasks"] = { ["3000 reputation with Cenarion Circle"] = "3000 репутації у Колі Кенаріона", ["Cenarion Combat Badge"] = "кенарійська бойова відзнака", ["Cenarion Combat Badge (Provided)"] = "кенарійська бойова відзнака (видано)", ["Cenarion Logistics Badge"] = "кенарійська логістична відзнака", ["Cenarion Logistics Badge (Provided)"] = "кенарійська логістична відзнака (видано)", ["Cenarion Tactical Badge"] = "кенарійська тактична відзнака", ["Cenarion Tactical Badge (Provided)"] = "кенарійська тактична відзнака (видано)" } },
    [85480] = { [1] = "Вдячність Прокрастимонда", ["en"] = "Procrastimond's Gratitude" },
    [85485] = { [1] = "Душа Порожнечі", [2] = "Коса добре розвивається. Наступна душа, яку вам варто спробувати додати, це душа мандрівника Безодні. Я знаю одну особливо могутню душу, яка залишається, незважаючи на те, що її господар помер поруч. Вона має стати гарним доповненням.", [3] = "Знайдіть Блукача Порожнечі поблизу Перехрестя Коріна у Східних Чумних Землях та додайте його душу до коси.", [4] = "Все йде добре?", [5] = "Чудово, {ім'я}. Ви готові до наступного етапу реставрації цієї коси?", ["en"] = "Soul of the Void" },
    [85486] = { [1] = "Душа Захоплюючої", [2] = "Ваше наступне завдання набагато складніше, воно пов'язане з тими порталами Скверни, що з'являються навколо. Я чув, що коли маги використовують спеціальні сувої, вони викликають могутніх Чужих Чум. Схоже, що бич у Чумному Лісі задумав щось подібне. Використайте демона, якого вони намагаються викликати, таким самим чином для наступного осколка душі.", [3] = "Використайте сяючий сувій просторового виправлення на великому розломі Скверни, щоб викликати порушника Скверни та отримати його душу.", [4] = "Все йде добре?", [5] = "Ти справді перевершив усі очікування, {ім'я}. Ще одна душа, і коса буде готова до останнього випробування.", ["en"] = "Soul of Enthralling" },
    [8549] = { [1] = "Орді потрібен мироквіт!", [2] = "Кажуть, що кожне покоління має пройти випробування вогнем. Боюся, що війна в Ан'Кіражі стане для нас цим випробуванням. Та ми підготуємося та покажемо, з чого ми зроблені.\n\nЯ допомагаю Орді збирати мироквіт, який піде на створення зілля для війни. Сподіваюся, ти {стать:прийшов:прийшла}, щоб допомогти мені. Якщо так, то мені потрібно якомога більше мироквіту. Збереш його для мене, {клас:к}?", [3] = "Принесіть 20 мироквітів травниці Гордому Перу в долину Духів в Орґріммарі.", [4] = "Ти вже {стать:повернувся:повернулась} з мироквітом, {клас:к}?", [5] = "Ця підготовка наближає нас до війни. Дякую за допомогу зі збором мироквіту, {клас:к}. Запевняю тебе, він піде на добру справу, і твій внесок не залишиться непоміченим. Якщо матимеш змогу — будь ласка, принось більше мироквіту. А до того часу нехай Матір-Земля береже тебе.", ["en"] = "The Horde Needs Peacebloom!", ["tasks"] = { ["Peacebloom"] = "мироквіт", ["Peacebloom (Provided)"] = "мироквіт (видано)" } },
    [8550] = { [1] = "Орді потрібно більше мироквіту!", [4] = "І знову привіт, {ім'я}. Я рада, що ти {стать:захотів:захотіла} знову допомогти нам у цьому нескінченному зборі мироквіту. Підготовка до війни продовжується, а отже продовжується й виробництво зілля та еліксирів, що допоможуть нашим військам в майбутніх битвах.\n\nТи допоможеш нам знову, {клас:к}? Мені знову потрібна та ж кількість мироквітів що й раніше. Тож якщо ти зможеш назбирати його для мене, я буду надзвичайно вдячна.", [5] = "Дякую, що продовжуєш допомагати нам, {ім'я}. Своєю самовідданістю ти приносиш велику честь собі та своїм пращурам і вкотре демонструєш істинний дух Орди. Я складу ці трави, щоб вони залишалися свіжими, поки не знадобляться.", ["en"] = "The Horde Needs More Peacebloom!", ["tasks"] = { ["Peacebloom"] = "мироквіт", ["Peacebloom (Provided)"] = "мироквіт (видано)" } },
    [85501] = { [1] = "Серце Хромаггуса", [2] = "Серце колись грізного Хромаггуса спочиває у ваших руках. Його калейдоскопічні кольори такі ж вишукані, як і гротескні. Ви відчуваєте величезну силу в серці; щось поза вашим розумінням. Щоб дізнатися більше, знадобиться допомога когось набагато могутнішого та давнішого, ніж ви самі.", [3] = "Знайдіть когось, хто може зрозуміти силу Хроматичного Серця.", [4] = "Що ти мені приніс, малий?", [5] = "Це серце — жахлива, аномальна річ. Однак, його силу, можливо, можна було б переробити, щоб вона служила кращим цілям.", ["en"] = "The Heart of Chromaggus" },
    [85505] = { [1] = "Душа Пожирання", [2] = "Ця душа має бути цікавою. Поки тебе не було, я чув, що зрадницький хорт полював на якихось магів поблизу озера Блеквуд. Візьми цей особливий уламок душі — він має посилити дію таємної магії, накладеної на тебе. Той хорт не зможе йому протистояти.", [3] = "Знайдіть магів біля озера Блеквуд і нехай вони накладають на вас заклинання, поки не з'явиться хорт Скверни.", [4] = "Все йде добре?", [5] = "Коса нарешті готова. Ще одна спроба, {ім'я}.", ["en"] = "Soul of Devouring" },
    [85506] = { [1] = "Фінальне випробування", [2] = "Я маю розкрити своє справжнє призначення зараз, {ім'я}. Я вірю, що ця коса може допомогти раз і назавжди зупинити Дес'Алтека. Зустрінемося в каньйоні Демонічного Фоллу в Ясенедолі, щоб ми могли використати його як останню душу, необхідну для повного відновлення сили коси.", [3] = "Отримайте душу Дес'Алтека з каньйону Демон-Фолл та використовуйте її, щоб завершити відновлення коси.", [4] = "Все йде добре?", [5] = "Дякую за допомогу, {ім'я}. Ви добре попрацювали. Будь ласка, збережіть косу як знак моєї вдячності.", ["en"] = "The Final Test" },
    [8551] = { [1] = "Скриня капітана", [2] = "Я ходив на кораблі звідси аж до Брашпиль, що в Калімдорі. Я був хорошим капітаном з бездоганною репутацією.\n\nДоки...\n\nЦі прокляті морські велетні не знищили мене! Вони розтрощили мій корабель, вбили мою команду і відправили мене на рятувальній шлюпці до Грабіжної Бухти. А один з велетнів, Ґорлаш, вкрав мою капітанську скриню. Сказав, що зробить з неї табакерку. От нахаба!\n\nЯ чув, що Ґорлаш блукає узбережжям на сході звідси. Знайди його і поверни мою скриню! Зробиш це й отримаєш капітанську подяку.", [3] = "Поверніть Гекельбері Смотсу в Грабіжну Бухту його скриню.", [4] = "Агов, {ім'я}! Ти {стать:знайшов:знайшла} Ґорлаша? Це була моя улюблена скриня, до того ж в ній був прихований відсік, де зберігалися мої найдорожчі скарби!", [5] = "Ти {стать:знайшов:знайшла} її! Який щасливий день! Дякую тобі, {ім'я}. Повернення скрині трохи заспокоїло мене.\n\nАле я ще не помстився...", ["en"] = "The Captain's Chest", ["tasks"] = { ["Smotts' Chest"] = "скриня Смоттса", ["Smotts' Chest (Provided)"] = "скриня Смоттса (видано)" } },
    [8552] = { [1] = "Пояс з монограмою", [2] = "На цьому вишуканому поясі вздовж канту вишиті літери \"ГС\".", [3] = "Поверніть пояс з монограмою власнику.", [4] = "Привіт. Маєш якусь справу до мене?", [5] = "Ти вдалося повернути мій пояс? В такому випадку ти, мабуть, {стать:убив:убила} морського велетня Мок'раша! Ура!\n\nЯ радий, що цей підлий лиходій мертвий — Мок'раш був одним з трьох морських велетнів, які розтрощили мої кораблі та вбили мій екіпаж.\n\nТричі.\n\nТи {стать:гідний:гідна} {клас:н}, {ім'я}.", ["en"] = "The Monogrammed Sash", ["tasks"] = { ["Monogrammed Sash"] = "пояс з монограмою", ["Monogrammed Sash (Provided)"] = "пояс з монограмою (видано)" } },
    [85521] = { [1] = "Відстеження ловця", [2] = "Знайдена вами записка, схоже, є квитанцією на придбання пасток для придушення, що оточують лігво Виводка-Бішоломника. У записці зазначено, що якщо Виводку потрібно більше пасток для придушення, він може придбати їх у таборі продавця, поблизу західного боку Палаючих Степів, трохи південніше дороги до Вівтаря Бур. У записці також зазначено, що продавець може скоро переїхати, тому Виводку слід поспішити, якщо йому потрібно більше пасток.", [3] = "Знайдіть покинутий табір на західній стороні Палаючих Степів, на південь від дороги до Вівтаря Бур, та дослідіть місцевість.", [4] = "Покинутий табір має дати деякі підказки.", [5] = "Можливо, ми зможемо працювати разом. Я все ще слідкую за іншими слідами, але ми можемо поділитися підказками, щоб вистежити цього порушника природи та зупинити його від заподіяння ще більшої шкоди.", ["en"] = "Tracking the Trapper" },
    [85525] = { [1] = "Одна ніч у Зимоключа", [2] = "Простого намету буде недостатньо, щоб пережити ніч під час зимової весняної бурі. Вам знадобляться їжа, хутро та вогонь, щоб зігрітися, інакше ви замерзнете на смерть, поки чекатимете. На щастя, природа забезпечує вас усім необхідним, і ви можете знайти все це прямо тут.", [3] = "Зберіть ведмеже м'ясо, тепле хутро та суху деревину. Принесіть матеріали до вашого табору, щоб побудувати укриття, аби пережити шторм.\n\nЯкщо ви втратите фундамент, зробіть новий зі своїх запасів для виживання та принесіть туди матеріали.\n\nНаданий предмет:", [4] = "Вам знадобиться достатньо їжі, хутра та вогню, щоб пережити ніч і не замерзнути.", [5] = "З додатковими запасами можна буде розбити табір під час шторму.", ["en"] = "One Night in Winterspring", ["tasks"] = { ["Survival Supplies"] = "Приладдя для виживання" } },
    [8553] = { [1] = "Шабля капітана", [2] = "Після того, як я втратив свій перший корабель через цих велетнів, я купив інший. Я назвав корабель \"Помста Смоттса\", наповнив його припасами, набрав екіпаж і вирушив на пошуки цих лиходіїв. Я знайшов їх, але вони виявились сильнішими за мене. Вони розтрощили \"Помсту Смоттса\", вбили мою другу команду і знову посадили мене на рятувальну шлюпку.\n\nЦього разу інший велетень, Неґолаш, вкрав мою шаблю.\n\nЗнайди Неґолаша і принеси мені мою шаблю!\n\nПоговори з Салагою. Він був моїм коком на \"Помсті Смоттса\" і вижив в останній битві. Він допоможе тобі знайти велетня.", [3] = "Поговоріть з Салагою.", [5] = "Привіт, привіт, {ім'я}. Капітан сказав, що ти йдеш на Неґолаша, правильно?", ["en"] = "The Captain's Cutlass" },
    [8554] = { [1] = "Бій з Неґолашем", [2] = "Неґолаш — голодний велетень.\n\nКоли велетні знищили наш корабель, Неґолаш пішов прямо на мою кухню. Він не хотів їсти екіпаж, як інші велетні. Неґолаш хотів вина і моїх смажених крилець канюка. Це моя фірмова страва і за рецептом мені довелося їхати аж у Безплідні краї!\n\nЯкщо хочеш заманити велетня, то візьми вина і купу крилець канюка. Поклади їх у нашу стару рятувальну шлюпку, що пришвартована до берега на південний схід звідси. Коли Неґолаш відчує запах їжі, він обов'язково прийде!", [3] = "Принесіть 10 смажених крилець канюка та 5 пляшок вина з джунглів до рятувальної шлюпки капітана Смоттса.\n\nВбийте Неґолаша і поверніть капітану Смоттсу його шаблю.", [4] = "Ти {стать:дістав:дістала} мою шаблю, {ім'я}?", [5] = "Ти {стать:забрав:забрала} мою шаблю у Неґолаша! Очам своїм не вірю, {ім'я}! Після зустрічі з тобою, удача перейшла на мою сторону, кажу тобі!\n\nДякую! Якщо у мене коли-небудь з'явиться новий корабель і ти захочеш поплавати по морях, то я буду радий {стать:такому почесному гостю:такій почесній гості}.", ["en"] = "Facing Negolash", ["tasks"] = { ["Smotts' Cutlass"] = "шабля Смоттса", ["Smotts' Cutlass (Provided)"] = "шабля Смоттса (видано)" } },
    [8555] = { [1] = "Тягар драконів", [5] = "Еранік, Велестраз та Азуреґос... Не сумніваюся, тобі доводилося чути про цих драконів, {стать:смертний:смертна}. І це не випадково, бо вони відіграли дуже важливу роль наглядачів за нашим світом.\n\nНа жаль (і в цьому частково винна моя власна наївність), чи то через слуг Старих Богів, чи то через зраду тих, хто називав їх друзями, всі вони зазнали трагедії. Це лише посилило мою недовіру до твого виду.\n\nЗнайди їх... І, {раса:к}, готуйся до найгіршого.", ["en"] = "The Charge of the Dragonflights" },
    [85557] = { [1] = "Ефективність – пріоритет один", [2] = "Власне, мені щойно спала на думку ідея. Бачите, найбільша проблема при роботі з елементієм — це підтримувати кузню достатньою температурою. Якби в мене було щось, що я міг би використовувати, щоб довше підтримувати вогонь на повну потужність, мені б не довелося витрачати стільки часу, скільки на його розпалювання.\n\nЯкщо ви знайдете мені чарівний засіб, щоб підтримувати мою кузню гарячою, я міг би звільнити трохи свого часу для підробітків, як ваше маленьке прохання. А тепер ідіть, забирайтеся. Подивіться, що ви зможете для мене знайти.", [3] = "Знайдіть відповідне джерело живлення, щоб кузня елементію Майстра-формувальника стихій Крікс працювала ефективніше.", [4] = "Що ти зі мною говориш? Геть.", [5] = "Вау! Це ідеально!\n\nМожна було б подумати, що Вік, будучи сином Смертокрила, міг би використати трохи своєї магії, щоб вирішити цю проблему для мене. Але між нами, у нього є ця енергія \"самовдоволеного менеджменту другого покоління\". Марна.\n\nУ будь-якому разі... давайте візьмемося за справу.", ["en"] = "Efficiency Is Priority One" },
    [85558] = { [1] = "Прагніть якості", [2] = "Я думав, що б зробити з цим шматком металу, і здається, що в мене є ідеальний спосіб для цього. Дайте мені лише кілька хвилин, і я зроблю його для вас.", [3] = "Спостерігайте, як Майстер-формувальник стихій Крікс створює ваш предмет.", [5] = "Ось вона. Хіба вона не красуня? Нехай вас не обманює те, скільки часу мені знадобилося, щоб зібрати цю погану дівчинку. Я лише зробила так, щоб вона ВИГЛЯДАЛА легко. Запевняю вас, це шедевр.\n\nЯ навіть вважаю, що це моя найкраща робота. Звичайно, все, що я створюю, — це моя найкраща робота. Що ж, це була весела розвага, але мені треба повернутися до роботи. Побачимося.", ["en"] = "Commit to Quality" },
    [85559] = { [1] = "Ніч падає", [2] = "Якщо ти підеш зі мною, я маю тобі ще дещо показати.", [3] = "Прогуляйтеся з Естеленн і подивіться, що вона вам покаже.", [4] = "Обіцяю, це не займе багато часу.", [5] = "Нарешті все скінчено. Нарешті я можу відпочити.\n\nБачите, Ван Амбург убив мене деякий час тому. Але я не міг піти, поки він завдавав таких страждань своїм тваринним поплічникам. Я мав знайти когось, хто розумів би тварин, як я, хто жив би, як я, і я знайшов тебе.\n\nЯ мушу піти, але перш ніж я це зроблю, у мене є для тебе останнє слово. Мене поховали тут, і я хочу, щоб ти взяв мої мечі, останнє, що я залишив після себе.\n\nІди із зеленим.", ["en"] = "Night Falls" },
    [8556] = { [1] = "Перстень-печатка непохитної сили", [2] = "Подейкують, що персні, які носять лейтенанти кіражів, наділяють їх надзвичайними здібностями. Але, якщо замінити осквернені самоцвіти, які вставлені в оправу, на чисті, сила перснів зросте.\n\nСамоцвіти, що прикрашають кіразьких ідолів, чудово підійдуть, оскільки їхня якість відмінна.\n\nПринеси мені перстень одного з лейтенантів та ідоли, і я зроблю для тебе потужний перстень, {клас:к}.", [3] = "Принесіть кіразький магістерський перстень, 2 сяйнистих ідоли, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки вітрозову Єссендрі в Силітус. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені перстень та матеріали, {ім'я}?", [5] = "Я заміню самоцвіти на цьому персні. Ти побачиш, що ефект буде набагато... приємнішим.", ["en"] = "Signet of Unyielding Strength", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Lambent Idol"] = "сяйнистий ідол", ["Lambent Idol (Provided)"] = "сяйнистий ідол (видано)", ["Qiraji Magisterial Ring"] = "кіразький магістерський перстень", ["Qiraji Magisterial Ring (Provided)"] = "кіразький магістерський перстень (видано)" } },
    [8557] = { [1] = "Пелерина непохитної сили", [2] = "Я радий чути, що ти допомагаєш нам у нападі на Ан'Кіраж, {ім'я}. На знак подяки я можу зробити для тебе річ, що захищатиме тебе в битві проти наших ворогів, {клас}.\n\nМені знадобиться кіразька пелерина, яку я підшию під твій розмір, звичайно. Також мені знадобляться ідоли та скарабеї, з яких я зроблю застібку.\n\nОбіцяю, ця річ тебе не розчарує.", [3] = "Принесіть кіразьку бойову пелерину, 2 оніксових ідоли, 5 срібних та 5 кістяних скарабеїв Кейлу Прудкопазуру в Силітус. Для виконання цього завдання вам потрібно мати принаймні шановану репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} матеріали для пелерини, {ім'я}?", [5] = "О так... вона бездоганна.\n\nВізьми цю пелерину, {ім'я}. Нехай вона захистить тебе від нечистої магії кіражів.", ["en"] = "Drape of Unyielding Strength", ["tasks"] = { ["21000 reputation with Cenarion Circle"] = "21000 репутації у Колі Кенаріона", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Onyx Idol"] = "оніксовий ідол", ["Onyx Idol (Provided)"] = "оніксовий ідол (видано)", ["Qiraji Martial Drape"] = "кіразька бойова пелерина", ["Qiraji Martial Drape (Provided)"] = "кіразька бойова пелерина (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)" } },
    [8558] = { [1] = "Серп непохитної сили", [2] = "Кіражі та їхні прислужники володіють предметами, виготовленими з найрідкісніших та найдосконаліших матеріалів: кісток велетенських та древніх створінь, самоцвітів з глибин землі, чистих та сильних металів.\n\nЛише один погляд на кіразькі артефакти сповнює мене бажанням практикувати своє ремесло з розбитими та розплавленими шматками їхніх артефактів. Доведи свою вірність Колу, {ім'я}, і я зроблю тобі могутню зброю з найкращих матеріалів кіражів.", [3] = "Принесіть кіразьке шиповане руків'я, 2 алебастрових ідоли, 5 кришталевих та 5 кам'яних скарабеїв вартовому Гаро в Силітус. Для виконання цього завдання вам потрібно мати возвеличену репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася} {клас:к}. Це руків'я майстерної роботи... ідеально збалансоване.\n\nВізьми свою зброю, {ім'я}. Використовуй її впевнено та розчави наших ворогів!", ["en"] = "Sickle of Unyielding Strength", ["tasks"] = { ["42000 reputation with Cenarion Circle"] = "42000 репутації у Колі Кенаріона", ["Alabaster Idol"] = "алебастровий ідол", ["Alabaster Idol (Provided)"] = "алебастровий ідол (видано)", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Qiraji Spiked Hilt"] = "кіразьке шиповане руків'я", ["Qiraji Spiked Hilt (Provided)"] = "кіразьке шиповане руків'я (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8559] = { [1] = "Наголінники завойовника", [2] = "Магія кіражів дуже сильна та древня. Наймогутніші кіражі володіють предметами такої могутності, що вони могли б зупинити навіть дракона.\n\nПринеси мені кіразькі наручі командування та інші другорядні компоненти, і я створю для тебе могутні чоботи.\n\nВони знадобляться тобі в битві проти наших ворогів.", [3] = "Принесіть кіразькі наручі командування, 2 ідоли війни, 5 скарабеїв зі слонової кістки та 5 золотих скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} предмети, які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Ти {стать:довів:довела}, що ти не {стать:звичайний смертний:звичайна смертна}.\n\nЯ впевнений, що вони допоможуть тобі трощити нікчемних кіражів.", ["en"] = "Conqueror's Greaves", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Idol of War"] = "ідол війни", ["Idol of War (Provided)"] = "ідол війни (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Qiraji Bindings of Command"] = "кіразькі наручі командування", ["Qiraji Bindings of Command (Provided)"] = "кіразькі наручі командування (видано)" } },
    [85595] = { [1] = "Явлення могутності", [4] = "Занза може створювати стародавні чари тролів за допомогою правильних компонентів.\n\nПерше — це первісний ідол Хаккарі, якого потрібно взяти у наймогутніших лейтенантів Хаккарі: Джін'до та Кривавого Володаря.\n\nДруге — це проколота лялька вуду. Її можна знайти в купах сміття, що засмічують це гидке місце. Зазирни всередину куп проклятих вуду.\n\nПринеси мені ці речі, і я створю для тебе потужні чари!", [5] = "Використовуй це добре, {клас}. Не проявляй милосердя до Хаккарі!", ["en"] = "Presence of Might" },
    [85596] = { [1] = "Обійми смерті", [4] = "Занза може створювати стародавні чари тролів за допомогою правильних компонентів.\n\nПерше — це первісний ідол Хаккарі, якого потрібно взяти у наймогутніших лейтенантів Хаккарі: Джін'до та Кривавого Володаря.\n\nДруге — це проколота лялька вуду. Її можна знайти в купах сміття, що засмічують це гидке місце. Зазирни всередину куп проклятих вуду.\n\nПринеси мені ці речі, і я створю для тебе потужні чари!", [5] = "Використовуй це добре, {клас}. Не проявляй милосердя до Хаккарі!", ["en"] = "Death's Embrace" },
    [85597] = { [1] = "Поклик сокола", [4] = "Занза може створювати стародавні чари тролів за допомогою правильних компонентів.\n\nПерше — це первісний ідол Хаккарі, якого потрібно взяти у наймогутніших лейтенантів Хаккарі: Джін'до та Кривавого Володаря.\n\nДруге — це проколота лялька вуду. Її можна знайти в купах сміття, що засмічують це гидке місце. Зазирни всередину куп проклятих вуду.\n\nПринеси мені ці речі, і я створю для тебе потужні чари!", [5] = "Використовуй це добре, {клас}. Не проявляй милосердя до Хаккарі!", ["en"] = "Falcon's Call" },
    [85598] = { [1] = "Віщунська аура", [4] = "Занза може створювати стародавні чари тролів за допомогою правильних компонентів.\n\nПерше — це первісний ідол Хаккарі, якого потрібно взяти у наймогутніших лейтенантів Хаккарі: Джін'до та Кривавого Володаря.\n\nДруге — це проколота лялька вуду. Її можна знайти в купах сміття, що засмічують це гидке місце. Зазирни всередину куп проклятих вуду.\n\nПринеси мені ці речі, і я створю для тебе потужні чари!", [5] = "Використовуй це добре, {клас}. Не проявляй милосердя до Хаккарі!", ["en"] = "Prophetic Aura" },
    [85599] = { [1] = "Чари худу", [4] = "Занза може створювати стародавні чари тролів за допомогою правильних компонентів.\n\nПерше — це первісний ідол Хаккарі, якого потрібно взяти у наймогутніших лейтенантів Хаккарі: Джін'до та Кривавого Володаря.\n\nДруге — це проколота лялька вуду. Її можна знайти в купах сміття, що засмічують це гидке місце. Зазирни всередину куп проклятих вуду.\n\nПринеси мені ці речі, і я створю для тебе потужні чари!", [5] = "Використовуй це добре, {клас}. Не проявляй милосердя до Хаккарі!", ["en"] = "Hoodoo Hex" },
    [8560] = { [1] = "Поножі завойовника", [2] = "Прагнеш довести свою цінність моєму роду, {стать:смертний:смертна}? Дуже добре, можливо, ми зможемо допомогти одне одному.\n\nДревній піщаний черв'як Оуро — істота легендарної сили. Подейкують, що його створив сам Старий Бог як наругу над життям.\n\nЙого шкіра неприродна... товста, майже неприступна, але при цьому така гнучка, що дозволяє йому швидко рухатися з грацією дрібної істоти.\n\nПринеси мені зразок його шкіри з іншими другорядними компонентами, і я зроблю для тебе поножі великої сили.", [3] = "Принесіть неушкоджену шкуру Оуро, 2 ідоли смерті, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просив, {ім'я}?", [5] = "Так... зі шкіри черв'яка можна зробити чудовий захисний шар. У поєднанні з найсильнішими частинами кіражів, яких ми знищили на нашому шляху сюди, ми створимо міцний обладунок. Нехай це допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!", ["en"] = "Conqueror's Legguards", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Idol of Death"] = "ідол смерті", ["Idol of Death (Provided)"] = "ідол смерті (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Ouro's Intact Hide"] = "неушкоджена шкура Оуро", ["Ouro's Intact Hide (Provided)"] = "неушкоджена шкура Оуро (видано)" } },
    [85600] = { [1] = "Явлення прозріння", [4] = "Занза може створювати стародавні чари тролів за допомогою правильних компонентів.\n\nПерше — це первісний ідол Хаккарі, якого потрібно взяти у наймогутніших лейтенантів Хаккарі: Джін'до та Кривавого Володаря.\n\nДруге — це проколота лялька вуду. Її можна знайти в купах сміття, що засмічують це гидке місце. Зазирни всередину куп проклятих вуду.\n\nПринеси мені ці речі, і я створю для тебе потужні чари!", [5] = "Використовуй це добре, {клас}. Не проявляй милосердя до Хаккарі!", ["en"] = "Presence of Sight" },
    [85602] = { [1] = "Ласка аніміста", [4] = "Занза може створювати стародавні чари тролів за допомогою правильних компонентів.\n\nПерше — це первісний ідол Хаккарі, якого потрібно взяти у наймогутніших лейтенантів Хаккарі: Джін'до та Кривавого Володаря.\n\nДруге — це проколота лялька вуду. Її можна знайти в купах сміття, що засмічують це гидке місце. Зазирни всередину куп проклятих вуду.\n\nПринеси мені ці речі, і я створю для тебе потужні чари!", [5] = "Використовуй це добре, {клас}. Не проявляй милосердя до Хаккарі!", ["en"] = "Animist's Caress" },
    [85608] = { [1] = "Бездоганні зачаровані водорості Південних морів", [4] = "{ім'я}! Давно я тебе не бачив. Ти знав, що сам король Растахан наказує мені додати останню частинку чарів та магії до твого талісмана? Це правда, друже! Я б не повірив, якби не бачив цього на власні очі. Дай це сюди.", [5] = "{ім'я} пн, це була гарна подорож. Продовжуй у вбивстві та придушенні Хаккара та його поплічників.", ["en"] = "Pristine Enchanted South Seas Kelp" },
    [85609] = { [1] = "Взірці могутності: браслети гаруспіка", [2] = "Гаруспік — ключовий член нашого племені; тобі буде мудро прислухатися до їхніх ознак. Спілкуючись з тваринами та віддаючи їх духам, коли це потрібно, вони дають нам божественне керівництво. У минулому проникливість і мудрість гаруспіка давали нам перевагу у війнах проти розколотих племен Гурубаші.\n\nПринеси мені жертву Взірців Сили з Зул'Ґуруба і доведи нам свою цінність. Зроби це, і я дам тобі наручі, які забажає будь-який гаруспік Зандалару.", [3] = "Принесіть Мейвікі Зулдазара Первісний Хаккарі-Стіч. Ви також повинні мати репутацію, рівну або вищу, ніж Дружні з Плем'ям Зандалар.\n\nМейвікі Зулдазара розташована на острові Йоджамба, Терниста Долина.", [4] = "Ти отримав Взірці Сили від Зул'Ґуруба? Ці наручі варті зусиль, {ім'я}. Повір мені, друже!", [5] = "Ах, я відчуваю силу, що виходить від цих Взірців Сили, {ім'я}. Ти довів, що ми в племені можемо назвати тебе \"другом\". Угода є угода, {ім'я}... ось сила наручів гаруспика!", ["en"] = "Paragons of Power: The Haruspex's Bracers" },
    [8561] = { [1] = "Корона завойовника", [2] = "Імператори-близнюки... Їхній невпинний шепіт потроху зводить мене з розуму. Вони знущаються з мене, знаючи, що я не можу ступити ні кроку в їхні володіння, щоб врятувати свого брата Ариґоса.\n\nУ своїх видіннях я бачу їхні жахливі голови, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці кіразькі символи сили на те, що більше відповідатиме нашим потребам.\n\nПринеси мені необхідні компоненти, {ім'я}, і я дам тобі головний убір незрівнянної сили.", [3] = "Принесіть вінець Век'нілаша, 2 ідоли сонця, 5 кам'яних та 5 кришталевих скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просила, {ім'я}?", [5] = "Тобі вдалося! Шепіт імператорів-близнюків припинився.\n\nПрийми це як нагороду. Один лише вид цієї речі вселятиме страх у серця кіражів... це нагадуватиме їм про їхніх полеглих лідерів і {стать:смертного:смертну}, {стать:який їх вбив:яка їх вбила}.", ["en"] = "Conqueror's Crown", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Idol of the Sun"] = "ідол сонця", ["Idol of the Sun (Provided)"] = "ідол сонця (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)", ["Vek'nilash's Circlet"] = "вінець Век'нілаша", ["Vek'nilash's Circlet (Provided)"] = "вінець Век'нілаша (видано)" } },
    [85610] = { [1] = "Взірці могутності: пояс гаруспіка", [2] = "Ми, Зандалар, не знаємо друїдських звичаїв; природа має формуватися нашими потребами, а не навпаки. Однак, гаруспік — це той з нас, хто найбільше налаштований на природу, і це справедливо. Відмовитися від привида звіра — означає знати, що таке бути одним із них. Це справжня сила природи.\n\nПринеси мені жертву Взірців Сили зсередини Зул'Ґуруба, довівши нам свою спроможність. Зроби це, і я дам тобі потужний предмет — пояс, який використовують багато гаруспік Зандаларів.\n\nМіцна магія, друже!", [3] = "Принесіть Майвікі із Зулдазара первісний пояс Хаккарі.  Мейвікі з Зулдазару знаходиться на острові Йоджамба в Тернистій долині. Ви також повинні бути відзначені Зандаларом.", [4] = "Отримав у Зул'Ґуруба потрібні мені Взірці Сили? Пояс гаруспека буде твоїм, якщо вони у тебе є.", [5] = "Дякую тобі — прихована сила цих предметів буде скарбом сама по собі, можеш бути певен. Ти не лише зробив те, що я просив тебе, але й довів, що ти шануєш нас тут, у племені. Як і обіцяв, ось твоя нагорода!", ["en"] = "Paragons of Power: The Haruspex's Belt" },
    [85611] = { [1] = "Взірці могутності: мундир гаруспіка", [2] = "Найвищим символом сили гаруспика є те, що він носить, {ім'я}. З них туніка символізує зв'язок між ним та божественною мудрістю, яку він прагне. Часто в туніку вплітають частини тіла тварин, яких він приносить у жертву; це нагадує йому про зв'язок зі своїми дарами.\n\nПринесіть мені жертву Взірців Сили зсередини Зул'Ґуруба та доведіть нам свою цінність. Зробіть це, і туніка, що просочується справжньою силою гаруспика, буде вашою.", [3] = "Принесіть Майвікі із Зулдазара гербову накидку Первісного Хаккарі.  Мейвікі з Зулдазару знаходиться на острові Йоджамба в Тернистій долині. Ви також повинні бути шанованими разом із Зандаларом.", [4] = "Отримав необхідні Взірці Сили від Зул'Ґуруба? Туніка гаруспека варта будь-яких зусиль, які тобі доведеться докласти.", [5] = "Вражаюче... ви успішно зібрали необхідні Взірці Сили, {ім'я}. Ваші досягнення в Зул'Ґурубі для Зандаларів легендарні; відтепер вас шануватимуть серед племені. Ось ваша туніка, могутній {клас}!", ["en"] = "Paragons of Power: The Haruspex's Tunic" },
    [85612] = { [1] = "Лють Муґамби", [4] = "Король Растахан передає свої вітання, Майстре {ім'я}. Такої честі ніколи не було надано комусь поза межами племені Зандалар.\n\nВіддай мені свій талісман, щоб я міг його ще раз посилити. Знай, що Гнів Мугамби тепер нерозривно пов'язаний з твоєю душею.", [5] = "Зул'джин би позаздрив, {клас}. Вперед і перемагай!", ["en"] = "The Rage of Mugamba" },
    [85613] = { [1] = "Взірці могутності: нарукавники поборника", [2] = "Помста — це сила. Зандаларський захисник — це така сила. У племені багато ворогів. Він карає їх. Жоден злочин проти нас не залишається безкарним. Він виконує це покарання. Наші вороги бояться нашої помсти. Вони повинні. Вони будуть боятися завжди.\n\nСтаньте одним із наших захисників. Шукайте Взірців Сили в Зул'Ґурубі. Знищуйте поплічників Хаккара та помстіться в ім'я племені. Ви будете винагороджені.", [3] = "Принесіть Джін'року Руйнівнику Первісну Хаккарську Наручну Шину. Ви також повинні мати репутацію, рівну або вищу за Дружні стосунки з Плем'ям Зандалар.\n\nДжін'рок Руйнівник знаходиться на острові Йоджамба, Терниста Долина.", [4] = "Ти привів Взірців Могутності? Чи помста вже заявлена в ім'я Зандаларів?", [5] = "Ти сьогодні багато помстився. Ти прийняв образ мстителя. Ти поставив на коліна поплічників Кривавого Бога.\n\nВізьми це. Це підживить твою жагу до помсти в майбутньому. Тепер ти друг Зандаларів.", ["en"] = "Paragons of Power: The Vindicator's Armguards" },
    [85614] = { [1] = "Взірці могутності: пояс поборника", [2] = "Остаточна помста чекає всередині Зул'Ґуруба. Хаккар не повинен знову повстати. Хаккар знищив Імперію Гурубаші зсередини. Жодної жертви не було достатньо. Тролі — це тінь колишньої слави. Я знаю, що це через Хаккара.\n\nСтань тим захисником, яким тобі судилося бути. Знищи поплічників зла. Зул'Ґуруб має скуштувати помсту Зандалара. Принеси мені доказ у Взірцях Сили. Ти отримаєш пояс захисника. Ти отримаєш справжню силу.\n\nІди.", [3] = "Принесіть Джін'року Руйнівнику Первісний Пояс Хаккарі. Ви також повинні мати репутацію, що дорівнює або вища за «Шановний у Племені Зандалар».\n\nДжін'рок Руйнівник знаходиться на острові Йоджамба, Терниста Долина.", [4] = "Ти привів Взірців Сили? Ти переміг ворогів племені? Хаккар мусить знати гнів мстителя!", [5] = "Шлях захисника тепер тобі відомий. Ти приніс честь племені. Ти приніс честь собі. Ти приніс біль нашим ворогам.\n\nПояс захисника твій. Ти неодмінно стаєш єдиним цілим зі шляхом захисника.", ["en"] = "Paragons of Power: The Vindicator's Belt" },
    [85615] = { [1] = "Знаки Сили: кіраса поборника", [2] = "Символом влади захисника є нагрудник. Він викуваний з потужного чарівного скло. Його довіряють лише тим, кого ми шануємо. Це зандаларський символ помсти.\n\nСтати захисником — означає стати помстою. Заберіть у Зул'Ґуруба Взірці Сили, які нам потрібні. Принесіть їх нам. Ми заберемо вкрадене у нас чарівне скло. Ми змусимо поплічників Хаккара заплатити. Ми винагородимо вас нагрудником захисника.\n\nІди. Будь нашою помстою, {ім'я}.", [3] = "Принесіть Джін'року Руйнівнику Первісного Хаккарі Коссака. Ви також повинні мати репутацію, рівну або вищу за Шанований у Племені Зандалар.\n\nДжін'рок Руйнівник знаходиться на острові Йоджамба, Терниста Долина.", [4] = "Твоя присутність означає перемогу? Чи маєш ти Взірці Сили? Розкажи мені про помсту, яку ти сьогодні здійснив!", [5] = "Тебе слід шанувати за твої вчинки. Плем'я винагороджує своїх героїв. Зул'Ґуруб скуштував помсти Зандалару, як ніколи раніше.\n\nТвої вчинки сповіщатимуть про вчинки інших майбутніх. Вони вважатимуть тебе ознакою справжньої сили. Вони вважатимуть тебе втіленням помсти!", ["en"] = "Paragons of Power: The Vindicator's Breastplate" },
    [85616] = { [1] = "Всевидюще око Зулдазара", [4] = "Якби ж у нас було ще десять тисяч таких, як ти, {ім'я}. Армії Хаккара розвіялися б на вітер вмить.\n\nНа жаль, Око готове реалізувати свій повний потенціал. Віддай його мені.", [5] = "Урази їх усіх і нехай Хаккар з ними розбереться...", ["en"] = "The All-Seeing Eye of Zuldazar" },
    [8562] = { [1] = "Кіраса завойовника", [2] = "Старий Бог, ім'я якого ми не згадуємо, повільно прокидається від свого сну під Ан'Кіражем. Жахлива доля може спіткати Азерот за кілька днів або років. Час не має значення для істот його сили.\n\nЗійдуться зірки — і його страшний гнів кинеться на все живе. Ти маєш знайти його раніше та покласти край його існуванню.\n\nЗроби це та принеси мені шматок його оболонки. Натомість я дам тобі обладунок, яким не володів ще ніхто зі смертних... обладунок, гідний вбивці бога!", [3] = "Принесіть панцир Старого Бога, 2 ідоли війни, 5 срібних та 5 кістяних скарабеїв Ветзері в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Роду Ноздорму.", [4] = "У своїй оселі в Ан'Кіражі, жихливий К'Тун спить і чекає, коли прийде його час.", [5] = "Я не очікувала, що ти повернешся, {ім'я}.\n\nТи {стать:здійснив:здійснила} подвиг величніший, ніж більшість безсмертних істот.\n\nВбивши К'Туна, ти не тільки {стать:врятував:врятувала} весь Азерот, але й {стать:перехилив:перехилила} терези космічних сил, про які ти навіть і не {стать:знав:знала}.\n\nПрийми цю кірасу як символ слави та тягаря, що буде наслідком твоїх дій.\n\nНехай її сила допоможе тобі у випробуваннях, які чекають на тебе, вбивце богів!", ["en"] = "Conqueror's Breastplate", ["tasks"] = { ["9000 reputation with Brood of Nozdormu"] = "9000 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Carapace of the Old God"] = "панцир Старого Бога", ["Carapace of the Old God (Provided)"] = "панцир Старого Бога (видано)", ["Idol of War"] = "ідол війни", ["Idol of War (Provided)"] = "ідол війни (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)" } },
    [85622] = { [1] = "Взірці могутності: обмотки сповідника", [2] = "Ми, Зандалар, наділяємо силою тих, хто говорить з авторитетом божественності. Наші жерці — це більше, ніж просто цілителі, вони наші сповідники. Зло походить як від зовнішніх загроз, таких як Хаккар, так і зсередини племені. Наші сповідники діють як судді серед нас, оберігаючи нас від того ж зла, яке поглинуло Гурубаші зсередини.\n\nІдіть до Зул'Ґуруба та поверніть Взірці Сили від Гурубаші. Дізнайтеся, що означає бути сповідником, і збережіть нас від зла.", [3] = "Принесіть Аль'табіму Всевидючому Первісний Хаккарі-Стіч. Ви також повинні мати репутацію, рівну або вищу за Дружній до Плем'я Зандалар.\n\nАль'табім Всевидючий знаходиться на острові Йоджамба, Терниста Долина.", [4] = "Ти повернувся із Зул'Ґуруба? Тобі вдалося повернути Взірці Сили у поплічників Хаккара?", [5] = "Чудово, {ім'я}! Це був немалий подвиг – принести це мені. Безсумнівно, ти сьогодні виступив сповідником нашого племені, захистивши нас від загрози Хаккара. Ці накидки личать такому другу племені, як ти!", ["en"] = "Paragons of Power: The Confessor's Wraps" },
    [85623] = { [1] = "Взірці могутності: пояс сповідника", [2] = "Невдовзі після падіння Гурубаші ми, Зандалар, ледь не зазнали остаточної поразки від зла всередині нашого племені. Саме тоді серед нас з'явилися сповідники, які зберегли плем'я, вигнавши тих, хто знищував би їхній рід. Вони не лише підтримують нас у гармонії з духами, але й зберігають плоть.\n\nВирушайте до Зул'Ґуруба та на власні очі переконайтеся у розбещеності Хаккара та Гурубаші. Вирвіть у них Взірці Сили, яких ми шукаємо; успіх буде винагороджений!", [3] = "Принесіть Аль'табіму Всевидючому Первісний Хаккарі-Пояс. Ви також повинні мати репутацію, що дорівнює або вища за «Шановний у племені Зандалар».\n\nАль'табім Всевидючий знаходиться на острові Йоджамба, в Тернистій Долині.", [4] = "Взірці Сили... чи є вони у вас? Тільки коли вони у нас є, ми зможемо використовувати приховану силу, що зберігається в них. Буде добре змінити ситуацію проти поплічників Кривавого Бога...", [5] = "Успіх! Це значною мірою допоможе нам зміцнити нашу силу проти піднесення Хаккара. З вашою допомогою ми зробили значний крок уперед, щоб Бог Криви не знищив нас усіх.\n\nСьогодні ви заслужили честь племені, {ім'я}. Візьміть це — пути сповідника — як символ нашої подяки.", ["en"] = "Paragons of Power: The Confessor's Bindings" },
    [85624] = { [1] = "Взірці могутності: наплічники сповідника", [2] = "Сповідники Зандаларів носять особливу мантію, що позначає їх як охоронців племені. Ці мантії виткані з потужного міфу, що допомагає їм судити тих, хто загрожує нашому племені. Як священик, ти також повинен витрачати свій час на судження тих, хто гідний, і тих, хто ні; така мантія безумовно буде для тебе благословенням.\n\nВ обмін на боротьбу з поплічниками Хаккара в Зул'Ґурубі та принесення мені Взірців Сили, яких я шукаю, я дам тобі мантію, гідну наших найкращих сповідників.", [3] = "Принесіть Аль'табіму Всевидючому Первісну Егіду Хаккарі. Ви також повинні мати репутацію, рівну або вищу за Шанований у Племені Зандалар.\n\nАль'табім Всевидючий розташований на острові Йоджамба, Терниста Долина.", [4] = "У тебе є Взірці Сили від Зул'Ґуруба?", [5] = "Молодець, {ім'я} — завдяки тобі, поплічники Хаккара сьогодні точно відчули на собі покарання Зандаларів. Твої дії забезпечили тобі постійне шанобливе місце в племені. З нашим благословенням, будь ласка, прийми цей сповідницький сан як свій!", ["en"] = "Paragons of Power: The Confessor's Mantle" },
    [85625] = { [1] = "Нестримна пошесть Кезана", [4] = "Поклич своїх демонів, {клас}. Нехай вони погріються в енергії Порчі Кезана. Командуй ними на полі бою! Знищи ворога!\n\nТак... Настав час застосувати останнє посилення до Порчі Кезана. Дай мені талісман.", [5] = "Здирай плоть з їхніх трупів. Спостерігай, як тіні поглинають Хаккарі. Черпай силу з їхнього страху, {клас}. Нехай Скверна Кезана посилює цю силу...", ["en"] = "Kezan's Unstoppable Taint" },
    [85626] = { [1] = "Взірці могутності: обмотки одержимого", [2] = "Чаклуни ступають на небезпечний шлях у спілкуванні з демонами, але наші демонічні вороги йдуть ще далі. За допомогою давнього та таємничого ритуалу вони дозволяють демону увійти в свою істоту. Однак, замість того, щоб дозволити йому оволодіти ними, вони поневолюють демона зсередини, поглинаючи силу звіра для власного розпорядження. Це подвиг, який мало хто може опанувати.\n\nЩоб ти дізнався про силу демонічного ворога, мені потрібні Взірці Сили від Зул'Ґуруба. Іди туди та поверни те, що ми шукаємо.", [3] = "Принесіть Аль'табіму Всевидючому Первісний Хаккарі-Стіч. Ви також повинні мати репутацію, рівну або вищу за Дружній до Плем'я Зандалар.\n\nАль'табім Всевидючий знаходиться на острові Йоджамба, Терниста Долина.", [4] = "Ти повернувся з Взірцями Сили? Перемогши диявольських поплічників Хаккара, ти не лише доведеш нам себе, але й свою готовність вивчити шляхи демонічного.", [5] = "Молодець... безсумнівно, їм довелося заплатити жахливими способами, перш ніж вони відмовилися від Взірців Сили. Візьміть це — обгортки демонічного. Виготовлені з потужної магії, що використовується для викликання здобичі демонічного, це потужний інструмент для здобуття сили.", ["en"] = "Paragons of Power: The Demoniac's Wraps" },
    [85627] = { [1] = "Взірці могутності: наплічники одержимого", [2] = "Демонічний дух прагне втілити силу безпосередньо, а не просто володіти нею. Не один з наших демонічних духів програв битву з демоном; з нашими ворогами, які загрожують нам — особливо в Зул'Ґурубі — сила, яку демонічний дух здатний вивільнити на наших ворогів, варта жертви. Наше виживання залежить від знищення тих, хто хоче нас знищити; падіння Імперії Гурубаші навчило нас цьому.\n\nПодорожуйте до Зул'Ґуруба та отримайте потрібні нам Взірці Сили. Зробіть це, і цінний демонічний предмет стане вашим.", [3] = "Принесіть Аль'табіму Всевидючому Первісний Хаккарі-Пояс. Ви також повинні мати репутацію, що дорівнює або вища за «Шановний у племені Зандалар».\n\nАль'табім Всевидючий знаходиться на острові Йоджамба, в Тернистій Долині.", [4] = "Отримали Взірці Сили від Зул'Ґуруба? Хоча ми візьмемо приховану силу з цих предметів і зробимо їх своїми, ми дамо вам вашу власну винагороду у вигляді сили, якщо ви досягнете успіху...", [5] = "Молодець, {ім'я}. Взірці Сили від Зул'Ґуруба мають нагадувати про витрачену силу. Гурубаші були сильними на своєму піку, але вони дозволили їй поглинути себе. Демонічний божевільний знає, що гра, в яку вони грають, дуже схожа, але сила, яку вивільняють, часто є саме тим, що потрібно для виживання.\n\nВикористовуйте цю мантію як шановний союзник Зандаларів... вона добре вам послужить.", ["en"] = "Paragons of Power: The Demoniac's Mantle" },
    [85628] = { [1] = "Взірці могутності: мантія одержимого", [2] = "Найвищим символом влади серед племені є одяг, який ми носимо в бою. Мантії демонічного ворога поєднали в одне ціле тонку рунічну тканину та нищівно потужну магію. Кажуть, що вигляд мантії вселяє страх у всіх, хто її бачить... особливо у демонів, яких демонічний ворог зрештою підкорить.\n\nІз Зул'Ґуруба ти повинен принести мені дуже специфічний набір Взірців Сили. Це буде важко... але твій успіх гарантує тобі придбання мантії для себе.", [3] = "Приведіть Аль'табіма Всевидючого Первісного Хаккарі Коссака. Ви також повинні мати репутацію, рівну або вищу за Шанований у Племені Зандалар.\n\nАль'табім Всевидючого знаходиться на острові Йоджамба, Терниста Долина.", [4] = "Взірці Сили... ви повернулися з ними? Тільки-но ми їх отримаємо, ми поділимося з вами найвищим символом демонічної сили, {ім'я}.", [5] = "Вражаюче — ваша перемога в Зул'Ґурубі запевнила нас — ні, весь світ — що Хаккар не переможе. Можливо, настане час, коли ви зустрінетеся безпосередньо з Кривавим Богом... і якщо це станеться, знайте, що ваша шана гарантована серед племені Зандалар.\n\nО, і цей простий халат також, я думаю, має допомогти.\n\n<Аль'табім багатозначно підморгує вам.>", ["en"] = "Paragons of Power: The Demoniac's Robes" },
    [85629] = { [1] = "Самоцвіт Каджаро", [4] = "Дай мені талісман, {ім'я}. Я маю тобі дещо показати.", [5] = "<Аль'табім розбиває камінь потужною невидимою силою.>\n\nБачите? Цей камінь — це те, що ми називаємо жеодою. Усередині камінця знаходяться потужні кристали, які вбирали приховану енергію нашого світу. Розрізавши камінь навпіл, я нарешті дозволив йому повністю розкрити свій потенціал. Використайте його, щоб спустошити наших ворогів.", ["en"] = "The Jewel of Kajaro" },
    [85630] = { [1] = "Взірці могутності: обмотки ілюзіоніста", [2] = "Маги нашого племені відомі як ілюзіоністи. Вони використовують потужну магію у своїх заклинаннях, часто бентежачи та заплутуючи ворогів племені!\n\n<Аль'табім злобно сміється.>\n\nЦе ж видовище — бачити, як могутній ілюзіоніст працює, збиваючи наших ворогів з власного божевілля!\n\nЩоб ти знав шлях наших ілюзіоністів, йди до Зул'Ґуруба та принеси мені вибраних Взірців Сили. За це я дам тобі нарукавні пов'язки, які наші ілюзіоністи використовують для плетіння своїх заклинань.", [3] = "Принесіть Аль'табіму Всевидючі Первісні Хаккарські Путці. Ви також повинні мати репутацію, рівну або вищу за Дружні стосунки з Плем'ям Зандалар.\n\nАль'табім Всевидючий знаходиться на острові Йоджамба, Терниста Долина.", [4] = "{ім'я} - ти вже повернувся? Чи зміг ти отримати потрібні мені Взірці Сили?", [5] = "Вражаюче... чи відчували ви, як крізь них тече магія? Взірці Сили використовувалися як своєрідна валюта, коли Імперія Гурубаші правила цими землями. Тепер ми, Зандаларці, використаємо приховану магію всередині них, щоб боротися з другим піднесенням Бога Криви Хаккара!\n\nВи добре попрацювали сьогодні — вважайте, що у вас є друг у Зандаларі. За це ось вам обіцяні обгортки ілюзіоніста!", ["en"] = "Paragons of Power: The Illusionist's Wraps" },
    [85631] = { [1] = "Взірці могутності: наплічники ілюзіоніста", [2] = "Магія — це сира, первісна сила, яку можуть формувати ті, хто достатньо сильний для цього. Моджо — наше продовження цієї сили; одна з таких потужних маніпуляцій з нею — ілюзія. Як можна по-справжньому сподіватися перемогти ворога, якого насправді навіть немає? Ми, Зандалар, знаємо силу цього, і тому ілюзіоністи займають почесне місце в племені.\n\nВізьміть необхідні Взірці Сили від Зул'Ґуруба — за це ви отримаєте шану від племені та могутню мантію, яку використовують наші найкращі ілюзіоністи!", [3] = "Принесіть Аль'табіму Всевидючому Первісну Хаккарі-шаль. Ви також повинні мати репутацію, що дорівнює або вища за «Шановний у племені Зандалар».\n\nАль'табім Всевидючий знаходиться на острові Йоджамба, в Тернистій долині.", [4] = "Як пройшов твій вторгнення в Зул'Ґуруб? Чи зводив ти своїх ворогів з розуму силою ілюзії? Ілюзія чи ні, їхня смерть – і забрані у них Взірці Сили – допоможуть перешкодити піднесенню Хаккара.", [5] = "Успіху! Відтепер тебе шануватимуть у племені! Зул'Ґуруб сьогодні точно відчув могутність Зандаларів завдяки тобі {ім'я}.\n\nЗ благословення племені прийми мантію ілюзіоніста Зандаларів. Нехай вона тобі служить добре.", ["en"] = "Paragons of Power: The Illusionist's Mantle" },
    [85632] = { [1] = "Взірці могутності: мантія ілюзіоніста", [2] = "Плем'я визнає своє становище та владу через те, що ми носимо. Наш одяг виготовлений з найкращих матеріалів та переплетений з нашою магією, яка робить нас сильними. Ілюзіоністи не є винятком; кажуть, що їхні шати втілюють суть ілюзії у своєму образі. Легенда свідчить, що їхні стародавні шати ніколи не виглядали однаково двічі.\n\nЯ дам тобі мантію ілюзіоніста, {ім'я}... але спочатку заслужи своє шанобливе місце серед племені! Принеси мені Взірці Сили від Зул'Ґуруба!", [3] = "Приведіть Аль'табіма Всевидючого Первісного Хаккарі Коссака. Ви також повинні мати репутацію, рівну або вищу за Шанований у Племені Зандалар.\n\nАль'табім Всевидючого знаходиться на острові Йоджамба, Терниста Долина.", [4] = "Ти повернувся з потрібними нам Взірцями Сили? Я знаю, що це буде нелегко... але я давно передбачав, що хтось іззовні прийде допомогти нам у нашій боротьбі проти Хаккара. Хай це буде ти, кажу я!", [5] = "Нарешті хтось гідний носити мантію ілюзіоніста! Ваш успіх у Зул'Ґурубі забезпечив вам шану серед племені на віки вперед. Носіть її з гордістю, {ім'я}!", ["en"] = "Paragons of Power: The Illusionist's Robes" },
    [85633] = { [1] = "Зандаларський талісман майстра тіні", [4] = "Він прагне рости, {ім'я}. Талісман увібрав у себе все, що ти зробив. Тисячі трупів тролів, що розкидані по Зул'Ґурубу, підживили його силу. Дай його мені, і я зроблю останнє покращення.", [5] = "Це останній раз, коли ми розмовляємо під заступництвом Шери Алі'х. Ти знаєш усе, що повинен. Візьми талісман і продовжуй свої вбивства. Хаккару ніколи не можна дозволити покинути Зул'Ґуруб.", ["en"] = "Zandalarian Shadow Mastery Talisman" },
    [85634] = { [1] = "Взірці могутності: браслети зірвиголови", [2] = "Божевільні Зандалару схожі на розбійників, але понад усе вони охоплюють божевілля... хаос... непередбачуваність існування. Жах на полі бою, вони посіяли зерна плутанини та хаосу серед наших ворогів у дикі часи після розколу племен. Нас би тут сьогодні не було без них.\n\nПринесіть мені Взірці Сили Зул'Ґуруба, яких я шукаю, і я дам вам перші цінні обладунки божевільного. Прийміть божевілля!", [3] = "Принесіть Фалтіру Незрячому Первісну Хаккарську Наручну Шину. Ви також повинні мати репутацію, рівну або вищу за Дружню з Плем'ям Зандалар.\n\nФалтір Незрячий знаходиться на острові Йоджамба, Терниста Долина.", [4] = "Шукай божевілля всередині Зул'Ґуруба та затьмарюй його своїм власним, {ім'я}! Зробити це означає успіх, а успіх означає винагороду! Нехай Бог Криви знову не запанує!", [5] = "Молодець, {ім'я}... твої досягнення в Зул'Ґурубі заслужили тобі право називати плем'я Зандалар другом. Я подбаю про те, щоб розпорядилися Ідеалами; за твої зусилля, будь ласка, прийми цю нагороду!", ["en"] = "Paragons of Power: The Madcap's Bracers" },
    [85635] = { [1] = "Взірці могутності: наплічники зірвиголови", [2] = "Одним із легендарних божевільних Зандалара був Хар'ваксал Тріснутий. Легенда свідчить, що, вперше зіткнувшись з ворогами племені, Кар'ксаван використав свою мантію, спеціально виткану з «переплетення божевілля». Його тіло було оповите не лише мантією, а й сліпучою швидкістю його двох кинджалів. Сьогодні божевільні плекають свою мантію як знак свого місця в племені.\n\nПринесіть мені Взірці Сили, яких я шукаю, і така мантія буде вашою, щоб виткати божевілля своїм ворогам.", [3] = "Принесіть Фалтіру Незрячому Первісний Пояс Хаккарі. Ви також повинні мати репутацію, що дорівнює або вища за «Шановний у Племені Зандалар».\n\nФалтір Незрячий розташований на острові Йоджамба, Терниста Долина.", [4] = "Ти повернувся — чи маєш ти Взірці Сили, які мені потрібні?\n\nЛегенда про Хар'ваксала Тріснутого служить нам сьогодні нагадуванням про те, що жодного ворога — якою б великою загрозою він не був — неможливо подолати. Хаос поставить усіх на коліна, це точно... і, можливо, найнехаотичніші елементи хаосу.", [5] = "Перемога за нами сьогодні, завдяки божевіллю, яке ви посіяли серед наших спільних ворогів! Ви заслуговуєте на повагу серед Зандаларів, і немає кращого способу висловити вдячність за ваші вчинки, ніж запропонувати вам мантію божевільного!", ["en"] = "Paragons of Power: The Madcap's Mantle" },
    [85636] = { [1] = "Взірці могутності: мундир зірвиголови", [2] = "Мої очі давно мене підвели, але я не сумую за ними. Навіть у такому племені, як наше, де одяг відображає становище та призначення, найпотужніший одяг випромінює силу, яку не можуть побачити прості очі. Цінна туніка зандаларського божевільного не є винятком, випромінюючи грубу силу хаосу та божевілля, яку вони здатні направляти.\n\nВзірці Сили, які мені потрібні, лежать у Зул'Ґурубі; принеси мені те, що я шукаю, і я винагороджу тебе твоєю власною легендарною тунікою... такою, що личить ткачеві божевілля.", [3] = "Принесіть Фалтіру Незрячому Первісну Егіду Хаккарі. Ви також повинні мати репутацію, рівну або вищу за Шанований у Племені Зандалар.\n\nФалтхір Незрячий розташований на острові Йоджамба, Терниста Долина.", [4] = "Ласкаво просимо назад на Острів, {ім'я}... ви тріумфально повернулися з Взірцями Сили на буксирі?", [5] = "Вражаюче... ви сьогодні досягли того, що мало хто вважав можливим. Ваша шана в племені гарантована на все життя, {ім'я}. Ви заслужили право одягнути туніку божевільного — зробіть це з нашого благословення.", ["en"] = "Paragons of Power: The Madcap's Tunic" },
    [85637] = { [1] = "Гнів Водоверті", [4] = "Молтор передає звістку від короля Растахана, {ім'я}. Королівський двір надзвичайно вражений вашим знищенням військ Хаккарі. Я маю нагородити вас останнім виплетенням вашого талісмана. Передайте його мені.", [5] = "Твоя подорож тільки почалася, юний {клас}. Можливо, одного дня ти відвідаєш Вир і зазирнеш у серце світу.\n\nБажаю тобі сили та стійкості!", ["en"] = "Maelstrom's Wrath" },
    [85638] = { [1] = "Взірці могутності: браслети хижака", [2] = "У темні часи після падіння Імперії Гурубаші, хижаки Зандалару використовували свою майстерність, щоб забезпечити плем'я їжею. Мисливці стверджують, що вони дуже схожі на хижаків нашого племені – так, шукати полювання – це втілювати сутність хижака. Однак ваше полювання в Зул'Ґурубі покаже нам, яке ви справжнє місце серед наших найкращих хижаків.\n\nПринесіть мені зразки Взірців Сили з Зул'Ґуруба. Зробіть це, і ви зробите перші кроки до того, щоб стати передостаннім хижаком.", [3] = "Принесіть наступні Взірці Сили з Зул'Ґуруба Фалтіру Незрячому: Первісні Хаккарські Путці. Ви також повинні мати репутацію, рівну або вищу за Дружні стосунки з Плем'ям Зандалар.\n\nФалтхір Незрячий розташований на острові Йоджамба, Терниста Долина.", [4] = "Полюй у Зул'Ґурубі на тих, хто бажає володіти Взірцями Сили, {ім'я}. Вони — твоя здобич; вони володіють тим, що мусимо мати ми обидва.", [5] = "Так... Мені не потрібне бачення, щоб відчути присутність Взірців Сили. Ваш успіх у Зул'Ґурубі вразив багатьох у племені. Ми вважаємо вас не лише другом Зандаларів, але й достатньо гідним, щоб володіти наручами хижака — могутніми предметами та символом того, що означає бути хижаком. Молодець, {ім'я}.", ["en"] = "Paragons of Power: The Predator's Bracers", ["tasks"] = { ["Primal Hakkari Bindings"] = "первісні браслети Гаккарі", ["Zandalar Tribe"] = "Плем'я Зандалар" } },
    [85639] = { [1] = "Взірці могутності: пояс хижака", [2] = "Хижак знає, як вистежувати свою здобич, але успішний хижак знає, як атакувати, коли вони зімкнуть ряди. Ти повинен опанувати і те, й інше, щоб мати хоч якийсь шанс на успіх у Зул'Ґурубі... і хоч якийсь шанс стати схожим на зандаларських хижаків.\n\nПринеси мені добірні частини Взірців Сили з Зул'Ґуруба. Моєю нагородою буде сила, яку дають ці дрібнички, а твоєю буде пояс зандаларського хижака — спорядження, варте обміну.", [3] = "Принесіть наступні Взірці Сили з Зул'Ґуруба Фалтіру Незрячому: Первісну Шаль Хаккарі. Ви також повинні мати репутацію, що дорівнює або вища за «Шановний у Племені Зандалар».\n\nФалтхір Незрячий розташований на острові Йоджамба, Терниста Долина.", [4] = "Удар по божевільних поплічниках Хаккара в Зул'Ґурубі — саме вони володіють Взірцями Сили, {ім'я}. Доведи їм — і племені — свій успіх як претендент на хижака.", [5] = "Я відчув твій прихід за мить до цього, {ім'я}, але не надто легко. Мені відкрили тебе Взірці Сили, яких ти приніс. Я можу відчути цю силу, навіть не бачачи дрібничок; їхнє приховане мохо – чиста магія, якщо хочете – продовжуватиме підживлювати наші зусилля щодо перемоги над диявольськими планами Бога Криви Хаккара.\n\nТи заслуговуєш на похвалу – і винагороду – за твій успіх. Ти шанована серед племені, і ти гідна носити пояс хижака.", ["en"] = "Paragons of Power: The Predator's Belt" },
    [85640] = { [1] = "Взірці могутності: наплічники хижака", [2] = "Ми, зандаларці, цінуємо те, що носимо, як символ досягнення. Не потрібно бачити, що носить людина, щоб відчути, що з цього виходить – сила виходить за межі зору. Одяг зандаларського хижака такий, і найбільше вони цінують свою мантію. Вона допомагає приховати їх від очей... і дати зрозуміти про свою присутність, коли вони цього забажають.\n\nВзірці Сили чекають на вас у Зул'Ґурубі. Принесіть мені те, що я шукаю, і мантія хижака буде вашою.", [3] = "Принесіть наступні Взірці Сили з Зул'Ґуруба до Фалтіра Незрячого: Первісну Егіду Хаккарі. Ви також повинні мати репутацію, що дорівнює або вища за Шанований у Племені Зандалар.\n\nФалтхір Незрячий розташований на острові Йоджамба, Терниста Долина.", [4] = "Чи твої атаки на Зул'Ґуруб увінчалися успіхом, {ім'я}? Тільки коли ти принесеш мені те, що я шукаю, — і повністю доведеш свою спроможність племені, — ти заслужиш неперевершене звання серед Зандаларів.", [5] = "Успіх... тебе слід шанувати серед племені, {ім'я}. Це був нелегкий подвиг — отримати Взірці Сили, необхідні для мантії, але ти впорався з цим як найсмертоносніший з наших хижаків. Ти заслужив своє місце серед них і, безумовно, заслужив право носити їхню мантію.", ["en"] = "Paragons of Power: The Predator's Mantle" },
    [8565] = { [1] = "Минулі перемоги в Араті", [5] = "О, так! Звичайно, ми не забули про твої минулі досягнення в низині Араті.", ["en"] = "Past Victories in Arathi", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [8566] = { [1] = "Минулі перемоги в Араті", [5] = "О, так! Звичайно, ми не забули про твої минулі досягнення в низині Араті.", ["en"] = "Past Victories in Arathi", ["tasks"] = { ["Arathi Resource Crate"] = "ящик з ресурсами Араті", ["Arathi Resource Crate (Provided)"] = "ящик з ресурсами Араті (видано)" } },
    [85660] = { [1] = "Серце Гаккара", [2] = "Серце Хаккара горить зсередини. Хоча Душевловлювач переможений, зерно його сили все ще залишається в цьому проклятому органі.", [3] = "Принесіть Серце Хаккара до Молтора на острові Йоджамба.", [5] = "Ах, Серце Хаккара. Отже, Душевловлювач убитий! Наш світ врятовано!\n\n{ім'я}, ваші послуги нам неможливо переоцінити. Ви справжній герой цього королівства!", ["en"] = "The Heart of Hakkar" },
    [8567] = { [1] = "Минулі перемоги в тіснині Пісні Війни", [5] = "О, так! Звичайно, ми не забули про твої минулі досягнення в тіснині Пісні Війни.", ["en"] = "Past Victories in Warsong Gulch", ["tasks"] = { ["Silverwing Talisman of Merit"] = "талісман заслуги Срібнокрилих", ["Silverwing Talisman of Merit (Provided)"] = "талісман заслуги Срібнокрилих (видано)" } },
    [8568] = { [1] = "Минулі перемоги в тіснині Пісні Війни", [5] = "О, так! Звичайно, ми не забули про твої минулі досягнення в тіснині Пісні Війни.", ["en"] = "Past Victories in Warsong Gulch", ["tasks"] = { ["Warsong Mark of Honor"] = "відзнака честі Пісні Війни", ["Warsong Mark of Honor (Provided)"] = "відзнака честі Пісні Війни (видано)" } },
    [8569] = { [1] = "Минулі заслуги в тіснині Пісні Війни", [5] = "О, так! Звичайно, ми не забули про твої минулі досягнення в тіснині Пісні Війни.", ["en"] = "Past Efforts in Warsong Gulch", ["tasks"] = { ["Warsong Gulch Ribbon of Sacrifice"] = "жертовна стрічка Пісні Війни", ["Warsong Gulch Ribbon of Sacrifice (Provided)"] = "жертовна стрічка Пісні Війни (видано)" } },
    [85699] = { [1] = "Змієкамінь темної мисливиці", [2] = "Нехай її краса тебе не обдурить, {клас}. Тіньова мисливиця, Вош'ґаджин, смертельна та божевільна.\n\n<Кілрам вказує на шрам на обличчі.>\n\nТак, вона дала мені це — любовний удар, вона це назвала.\n\nНарешті настав час помсти.\n\nТи можеш знайти Вош'ґаджин у Шпилі Чорної Скелі. Убий її та повернися до мене з її зміїним каменем. Зроби це, і я навчу тебе шляхів коваля-сокиря.", [3] = "Вирушайте до Шпиля Чорної Скелі та вбийте Тіньового Мисливця Вош'ґаджина. Відшукайте Зміїний Камінь Вош'ґаджина та поверніться до Кілрама.", [4] = "Легенда свідчить, що одне використання зміїного каменю Вош'ґаджіна збереже сокиру гострою як бритва протягом 1000 років!", [5] = "Тож ти впевнений, що саме цього ти хочеш? Стати ковалем-сокирою? Пам'ятай, що двері до того, щоб стати ковалем-мечарем та ковалем-молотом, зачиняться назавжди.", ["en"] = "Snakestone of the Shadow Huntress" },
    [8570] = { [1] = "Минулі заслуги в тіснині Пісні Війни", [5] = "О, так! Звичайно, ми не забули про твої минулі досягнення в тіснині Пісні Війни.", ["en"] = "Past Efforts in Warsong Gulch", ["tasks"] = { ["Warsong Gulch Ribbon of Sacrifice"] = "жертовна стрічка Пісні Війни", ["Warsong Gulch Ribbon of Sacrifice (Provided)"] = "жертовна стрічка Пісні Війни (видано)" } },
    [85700] = { [1] = "Порча", [2] = "Якщо я з тобою й говорю коротко, то на це є причина. Плани створення великого клинка, Псування, були викрадені Чорною Гвардією: Елітними скелетними підрозділами Барона Рівендара.\n\nТак, Бароне Рівендаре зі Стратгольма.\n\nМечовий коваль Чорної Гвардії тепер охороняє ці плани своєю... нежитью.\n\nУбий його та поверни доказ цього вчинку, і я навчу тебе шляхів мечника.", [3] = "Знайдіть у Стратгольмі коваля-мечника Чорної Гвардії та знищіть його. Поверніть знаки розрізнення Чорної Гвардії та поверніться до Серіла Скорджбейна.", [4] = "Ти забув, яке тобі завдання доручили, {ім'я}?", [5] = "Тож ти впевнений, що саме цього ти хочеш? Стати ковалем-мечарем? Пам'ятай, що двері до того, щоб стати ковалем-молотом та сокирою, зачиняться назавжди.", ["en"] = "Corruption" },
    [8572] = { [1] = "Спорядження ветеранів", [2] = "Відзнаки, які ти отримуєш, виконуючи бойові, логістичні та тактичні завдання для Кенарійської цитаделі, — це не просто прикраси, {ім'я:к}.\n\nНе загуби їх. Довівши свою відданість нашій організації, ти зможеш отримати частину спорядження, яке ми зберігаємо для наших найближчих союзників, в обмін на ці відзнаки.", [3] = "Принесіть 7 бойових, 4 логістичні й 4 тактичні кенарійські відзнаки Варґусу в Кенарійську цитадель, що в Силітусі. Вам також потрібно досягти почесної репутації з Кенарійським Колом, щоб завершити це завдання.", [4] = "Ми зацікавлені в тому, щоб наші союзники були добре споряджені, {ім'я:к}.", [5] = "Чудова робота, {ім'я:к}. Будь ласка, прийми це від імені Кенарійського Кола. Це, безперечно, заслужена винагорода, {стать:друже:подруго}!", ["en"] = "Veteran's Battlegear", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Cenarion Combat Badge"] = "кенарійська бойова відзнака", ["Cenarion Combat Badge (Provided)"] = "кенарійська бойова відзнака (видано)", ["Cenarion Logistics Badge"] = "кенарійська логістична відзнака", ["Cenarion Logistics Badge (Provided)"] = "кенарійська логістична відзнака (видано)", ["Cenarion Tactical Badge"] = "кенарійська тактична відзнака", ["Cenarion Tactical Badge (Provided)"] = "кенарійська тактична відзнака (видано)" } },
    [8573] = { [1] = "Спорядження чемпіона", [2] = "Відзнаки, які ти отримуєш, виконуючи бойові, логістичні та тактичні завдання для Кенарійської цитаделі, — це не просто прикраси, {ім'я:к}.\n\nНе загуби їх. Довівши свою відданість нашій організації, ти зможеш отримати частину спорядження, яке ми зберігаємо для наших найближчих союзників, в обмін на ці відзнаки.", [3] = "Принесіть 15 бойових, 20 логістичних й 20 тактичних кенарійських відзнак та 1 знак Кенарія Варґусу в Кенарійську цитадель, що в Силітусі. Вам також потрібно заслужити возвеличення Кенарійського Кола, щоб завершити це завдання.", [4] = "Ми зацікавлені в тому, щоб наші союзники були добре споряджені, {ім'я}.", [5] = "Чудова робота, {ім'я:к}. Будь ласка, прийми це від імені Кенарійського Кола. Це, безперечно, заслужена винагорода, {стать:друже:подруго}!", ["en"] = "Champion's Battlegear", ["tasks"] = { ["42000 reputation with Cenarion Circle"] = "42000 репутації у Колі Кенаріона", ["Cenarion Combat Badge"] = "кенарійська бойова відзнака", ["Cenarion Combat Badge (Provided)"] = "кенарійська бойова відзнака (видано)", ["Cenarion Logistics Badge"] = "кенарійська логістична відзнака", ["Cenarion Logistics Badge (Provided)"] = "кенарійська логістична відзнака (видано)", ["Cenarion Tactical Badge"] = "кенарійська тактична відзнака", ["Cenarion Tactical Badge (Provided)"] = "кенарійська тактична відзнака (видано)", ["Mark of Cenarius"] = "знак Кенарія", ["Mark of Cenarius (Provided)"] = "знак Кенарія (видано)" } },
    [8574] = { [1] = "Спорядження незламних", [2] = "Відзнаки, які ти отримуєш, виконуючи бойові, логістичні та тактичні завдання для вітрозова Гордого Рога, — це не просто прикраси, {ім'я:к}.\n\nНе загуби їх. Довівши свою відданість нашій організації, ти зможеш отримати частину спорядження, яке ми зберігаємо для наших найближчих союзників, в обмін на ці відзнаки.", [3] = "Принесіть 15 бойових, 20 логістичних й 17 тактичних кенарійських відзнак та 1 знак Ремула Варґусу в Кенарійську цитадель, що в Силітусі. Вам також потрібно заслужити повагу Кенарійського Кола, щоб завершити це завдання.", [4] = "Ми зацікавлені в тому, щоб наші союзники були добре споряджені, {ім'я}.", [5] = "Чудова робота, {ім'я:к}. Будь ласка, прийми це від імені Кенарійського Кола. Це, безперечно, заслужена винагорода, {стать:друже:подруго}!", ["en"] = "Stalwart's Battlegear", ["tasks"] = { ["21000 reputation with Cenarion Circle"] = "21000 репутації у Колі Кенаріона", ["Cenarion Combat Badge"] = "кенарійська бойова відзнака", ["Cenarion Combat Badge (Provided)"] = "кенарійська бойова відзнака (видано)", ["Cenarion Logistics Badge"] = "кенарійська логістична відзнака", ["Cenarion Logistics Badge (Provided)"] = "кенарійська логістична відзнака (видано)", ["Cenarion Tactical Badge"] = "кенарійська тактична відзнака", ["Cenarion Tactical Badge (Provided)"] = "кенарійська тактична відзнака (видано)", ["Mark of Remulos"] = "знак Ремула", ["Mark of Remulos (Provided)"] = "знак Ремула (видано)" } },
    [8575] = { [1] = "Магічне писання Азуреґоса", [2] = "Ви не можете зрозуміти жодного слова в цьому писанні. Ви навіть не знаєте, що це за мова!", [3] = "Принесіть магічне писання Азуреґоса Нараіну Тихомрію у Танаріс.", [4] = "Оооо! Ця штуковина пульсує магією! Це мені?", [5] = "<Нараін жадібно розглядає писання.>\n\nЧудово, {раса:к}! Що це? Я не знаю мови драконів.", ["en"] = "Azuregos's Magical Ledger", ["tasks"] = { ["Magical Ledger"] = "магічне писання", ["Magical Ledger (Provided)"] = "магічне писання (видано)" } },
    [8576] = { [1] = "Переклад писання", [5] = "Перш за все, {ім'я}, нам потрібно розібратися з тим, що тут написав Азуреґос.\n\nКажеш, він сказав тобі створити арканітовий буй, а це його схема? Дивно, що він написав це драконячою мовою. Цей старий козел знає, що я не зможу прочитати цю дурню.\n\nЯкщо це спрацює, мені знадобляться мої окуляри провидіння, 500-фунтова курка та другий том \"Мови драконів для початківців\". Не обов'язково в такому порядку.", ["en"] = "Translating the Ledger" },
    [8577] = { [1] = "Тушевул, ККД.", [2] = "Якщо я хочу хоч щось перекласти, мені знадобляться мої окуляри провидіння. На жаль, їх давно вкрав мій колишній кращий друг, Тушевул. Він розбив мені серце, а потім залишив мене тут гнити.\n\nЗа допомогою моєї вірної кришталевої кулі я знайшов його приблизне місцеперебування: або біля стіни Сивогрива в Срібнохвої, або в якомусь світі за порталом Позамежжя, нині захопленого Палаючим Легіоном. Тобі доведеться відшукати його та повернути мої окуляри, {ім'я}!", [3] = "Нараін Тихомрій хоче, щоб ви знайшли його колишнього кращого друга (ККД), Тушевула, і повернули окуляри спостереження, які Тушевул у нього вкрав.", [5] = "Не можу повірити, що він знайшов мене. Я був впевнений, що замів сліди, коли був в Позамежжі. Я не повернуся до нього, {раса:к}! Нізащо! Я більше не хочу бути його напівдругом-напіврабом.", ["en"] = "Stewvul, Ex-B.F.F." },
    [8578] = { [1] = "Окуляри провидіння? Без проблем!", [2] = "<Ви чуєте, як Тушевол зітхає з полегшенням.>\n\nТобі просто потрібні його окуляри провидіння? Чудово! Це не проблема... Просто дай мені хвильку, щоб... Гей! А де... а най його!\n\nЩо ж, у мене є погана новина та іще гірша новина. Погана новина — я загубив окуляри. Іще гірша новина — я загубив їх, коли нишпорив у Палаючому Ядрі минулого місяця. Так, Палаюче Ядро... Я так розумію, що наші справи на цьому завершені! Бувай!", [3] = "Знайдіть окуляри провидіння Нараіна та поверніть їх Нараіну Тихомрію в Танаріс.", [4] = "Палаюче Ядро, ге? Сподіваюся, мої окуляри все ще цілі!", [5] = "Неперевершено! Куди я поклав 500-фунтову курку та другий том \"Мови драконів для початківців\"??! А, так, ось нагорода за твою старанну роботу!", ["en"] = "Scrying Goggles? No Problem!", ["tasks"] = { ["Narain's Scrying Goggles"] = "окуляри провидіння Нараіна", ["Narain's Scrying Goggles (Provided)"] = "окуляри провидіння Нараіна (видано)" } },
    [8579] = { [1] = "Смертні чемпіони", [4] = "Ми відчуваємо присутність наших поневолених побратимів у глибині Ан'Кіража, але навіть армії драконів не вистачило б, щоб врятувати їх, {раса:к}.\n\nТе закляття, що ув'язнило їх, захопить й нас під контроль К'Туна, якщо ми наблизимося до нього надто близько.\n\nСтарий Бог передбачив наше прибуття. Вся надія втрачена. Що може змінити така смертна істота, як ти?", [5] = "Я бачу, що ти не {стать:звичайний смертний:звичайна смертна}, {ім'я:к}. Твої шанси проти Старого Бога все іще малі, але явно більше ніж у нас всіх. Тим більше він очікуватиме саме драконів, він не буде готовий до {стать:такого:такої} як ти.\n\nЯк Анахронос та Оленеріг перемогли кіражі тисячу років тому завдяки союзу між смертними та драконами, ми маємо зробити такий самий союз. Заслужи довіру бронзових драконів, і ти отримаєш й нашу довіру. Тільки тоді ми зробимо з тебе {стать:справжнього чемпіона:справжню чемпіонку}.", ["en"] = "Mortal Champions", ["tasks"] = { ["Qiraji Lord's Insignia"] = "відзнака кіразького володаря", ["Qiraji Lord's Insignia (Provided)"] = "відзнака кіразького володаря (видано)" } },
    [858] = { [1] = "Запалювання", [2] = "Тебе часом не Гуркоклапан прислав? Я тут у безвиході... Застрибнув сюди, не усвідомлюючи, що без ключа подрібнювач не заведеться. Мій колега запитав мене, чи все в порядку, а я запанікував! І замість того, щоб сказати йому, що в мене немає ключа, я відповів, що виникла якась несправність.\n\nТреба якнайшвидше драпати звідси! Піднімись в диспетчерську кімнату, що на вершині вишки, там у бригадира має бути ключ від цього подрібнювача.\n\nВиручи мене, благаю!", [3] = "Дістаньте ключ запалювання і принесіть його Кривошип-су.", [4] = "Мерщій, ми повинні щезнути звідси, перш ніж хтось щось запідозрить!", [5] = "Так, виглядає як той самий ключ. Дай-но переконатися, як все це працює...\n\nХм... контроль обертання... регулює швидкість і стабільність... чутливий контроль руху руки. Ти диви! Мені не віриться, що ТзНБ \"Авантюра\" змогли розробити щось краще, ніж в нас. Я негайно маю показати це у Брашпилі!", ["en"] = "Ignition", ["tasks"] = { ["Ignition Key"] = "ключ запалювання", ["Ignition Key (Provided)"] = "ключ запалювання (видано)" } },
    [8580] = { [1] = "Орді потрібен вогнеквіт!", [2] = "Агов, {клас:к}. Так, ти, друзяко! У нас тут такий гармидер. Орді треба вогнеквіт для війни в Ан'Кіражі. Може вони його запхнуть у якусь вибухівку? Чи оддадуть Альянсу на паливо для парових танків? Хто зна? Точно не Пеле'кейкі!\n\nАле дещо Пеле'кейкі точно знає... він знає, шо ти поможеш йому зібрати купу вогнеквітів, так, друзяко?", [3] = "Принесіть 20 вогнеквітів вершнику на кажані Пеле'кейкі в долину Духів в Орґріммарі.", [4] = "Ти ж не хочеш розсердить Пеле'кейкі. Ти зробиш Пеле'кейкі щасливим, якшо принесеш йому купу вогнецвіту.", [5] = "{Клас:к}! Пеле'кейкі просто щасливий. Пеле'кейкі забере весь цей вогнеквіт і складе в коробку, шоб він залишався свіжим. Пеле'кейкі прослідкує, шоб з цього зробили хороші штуки для війни. А якшо найдеш більше вогнеквіту — одразу ж принось його до Пеле'кейкі.", ["en"] = "The Horde Needs Firebloom!", ["tasks"] = { ["Firebloom"] = "вогнеквіт", ["Firebloom (Provided)"] = "вогнеквіт (видано)" } },
    [8581] = { [1] = "Орді потрібно більше вогнеквітів!", [4] = "Пеле'кейкі знає, шо ти хочеш помогти. Принести багато вогнеквітів та зробити його дуже щасливим! Пеле'кейкі може зробити великі бомби з вогнеквіту. Як настане війна, він скине їх на жуків Ан'Кіража зі свого кажана. Але Пеле'кейкі потрібно більше вогнеквітів, {клас:к}!\n\nТож принось Пеле'кейкі вогнеквіти, і хутчіш! Принось стільки ж, скільки й минулого разу, і Пеле'кейкі буде задоволений.", [5] = "Це не жарт, {клас:н}? Ти так швидко {стать:приніс:принесла} Пеле'кейкі вогнеквіти? Пеле'кейкі зараз же їх порахує, друзяко! Ти робиш Пеле'кейкі таким щасливим, він розкаже всім, шо {ім'я} — {стать:найкращий збирач:найкраща збирачка} вогнеквітів! Пеле'кейкі не може дочекатися початку війни. Ми покажемо нашу крутість в Силітусі, еге ж, друзяко?!", ["en"] = "The Horde Needs More Firebloom!", ["tasks"] = { ["Firebloom"] = "вогнеквіт", ["Firebloom (Provided)"] = "вогнеквіт (видано)" } },
    [8582] = { [1] = "Орді потрібен пурпуровий лотос!", [2] = "Пурпуровий лотос, {клас:к} — це реагент для багатьох гарних зіллів, еліксирів та олій, що знадобляться нам в Ан'Кіражі. Тож ми маємо зібрати чималі запаси, перш ніж починати війну. І я збираюся експериментувати над лотосом, щоб знайти для нього більше застосувань. Але щоб зробити це, мені знадобиться велика кількість квітів.\n\nІ це буде твоє завдання — зібрати якомога більше пурпурового лотоса. Бажаєш нам допомогти?", [3] = "Принесіть 20 пурпурових лотосів аптекарці Жезель в долину Духів в Орґріммарі.", [4] = "Ти вже {стать:повернувся:повернулась} з пурпуровим лотосом, {клас:к}? Дуже важливо, щоб ти {стать:приніс:принесла} його якомога швидше, інакше все, що я намагаюся тут зробити, буде дарма.", [5] = "Твої зусилля заслуговують на винагороду, {клас:к}. Я виміряю ці зразки та відзначу твій внесок. Потім пурпуровий лотос потрібно буде належним чином зберігати, поки в мене не дійдуть до нього руки. Схоже, що мені знадобиться більше цих квітів, тож далеко не йди.", ["en"] = "The Horde Needs Purple Lotus!", ["tasks"] = { ["Purple Lotus"] = "пурпуровий лотос", ["Purple Lotus (Provided)"] = "пурпуровий лотос (видано)" } },
    [8583] = { [1] = "Орді потрібно більше пурпурового лотоса!", [4] = "Схоже, що нам потрібно ще більше пурпурового лотоса, {клас:к}. Мої дослідження мають на меті знайти нові способи застосування цієї рослини, і я розробляю вірні методики.\n\nМені потрібно, щоб ти знову {стать:зібрав:зібрала} принаймні двадцять зразків пурпурового лотоса і {стать:приніс:принесла} їх мені.", [5] = "Прекрасна і точна робота, {ім'я}. Твоя старанність варта похвали, як і твоя швидкість. Я особисто простежу, щоб жоден з лотосів не пропав даремно.\n\nЩе раз дякую, і якщо збереш ще більше пурпурового лотоса — одразу принось його мені.", ["en"] = "The Horde Needs More Purple Lotus!", ["tasks"] = { ["Purple Lotus"] = "пурпуровий лотос", ["Purple Lotus (Provided)"] = "пурпуровий лотос (видано)" } },
    [8584] = { [1] = "Ніколи не розпитуй мене про мої справи", [2] = "Про мене тобі слід знати лиш одне: НІКОЛИ не розпитуй мене про мої справи! Я працюю з речами, які ти просто не зможеш зрозуміти. Наприклад, ти знаєш, що таке психотронний намордник? Звісно, що ні! Тому ми залишаємо планування мені, а дії — тобі.\n\nЯк я вже казав раніше, якщо ми хочемо, щоб у нас усе вийшло, нам знадобиться 500-фунтова курка.\n\nРушай до Пристобляху і поговори з Могилем Хуткорізом — він допоможе тобі знайти відповідний екземпляр.", [3] = "Нараін Тихомрій з Танаріса хоче, щоб ви поговорили з Могилем Хуткорізом з Пристобляху.", [5] = "<Могиль чеше голову.>\n\n500-фунтова курка? Таких не буває! Принаймні, більше не існує. Я знав таку курку... Чорну курку смерті...\n\n<Голос Могиля тремтить.>\n\nАле так, ніхто ніколи не бачив ту курку. Принаймні, не дожив до того, щоб розповісти про це. Однак, у мене є ідея, яка може бути корисною для нас обох, {стать:хлопче:дівча}.", ["en"] = "Never Ask Me About My Business" },
    [8585] = { [1] = "Острів Страховищ!", [2] = "Ходять легенди, що у химерин острова Страховищ, що у Фераласі, найсмачніше та найніжніше м'ясо у світі! А тепер у цих химерин є татусь, який при правильному приготуванні може виглядати, як 500-фунтова курка. Або може і не виглядати.\n\nВирушай на острів Страховищ, вбий лорда Лакмерана і принеси мені його свіжу тушу. Це повинно задовольнити гнома. А щоб задовольнити мене, тобі потрібно буде дістати вирізки химерин.\n\nЗроби це — і отримаєш свою 500-фунтову курку та дещо зверху.", [3] = "Принесіть тушу Лакмерана та 20 вирізок химерин Могилю Хуткорізу в Танаріс.", [4] = "Ммммм... Химеринятинка...", [5] = "Подивись на мармурові прожилки цих вирізок! Фантастика!\n\nТепер щодо курки... Хм, дай подумати. Мені потрібно кілька хвилин, щоб розробити рецепт.", ["en"] = "The Isle of Dread!", ["tasks"] = { ["Chimaerok Tenderloin"] = "вирізка химерини", ["Chimaerok Tenderloin (Provided)"] = "вирізка химерини (видано)", ["Lakmaeran's Carcass"] = "туша Лакмеран", ["Lakmaeran's Carcass (Provided)"] = "туша Лакмеран (видано)" } },
    [8586] = { [1] = "Кайфові відбивні Могиля з химерин", [2] = "Мій рецепт готовий! Зараз мені потрібно від тебе ракетне паливо та глибокоскельна сіль. Спеції я візьму на себе, а м'ясо, яке ти мені {стать:дістав:дістала}, покриє решту.\n\nПісля того, як ти принесеш мені все, що я просив, курка буде готова і ти зможеш віднести її до Нараіна.", [3] = "Могиль Хуткоріз з Пристобляху хоче, щоб ви принесли йому 20 порцій гоблінського ракетного палива і 20 порцій глибокоскельної солі.", [4] = "Поквапся, {стать:хлопче:дівча}. Ми не хочемо, щоб м'ясо зіпсувалося.", [5] = "Все готово! Представляю тобі моє найкраще творіння: кайфові відбивні Могиля з химерин!", ["en"] = "Dirge's Kickin' Chimaerok Chops", ["tasks"] = { ["Deeprock Salt"] = "глибокоскельна сіль", ["Deeprock Salt (Provided)"] = "глибокоскельна сіль (видано)", ["Goblin Rocket Fuel"] = "гоблінське ракетне паливо", ["Goblin Rocket Fuel (Provided)"] = "гоблінське ракетне паливо (видано)" } },
    [8587] = { [1] = "Повернення до Нараіна", [2] = "Я гоблін свого слова, {стать:хлопче:дівча}. Ось твоя 500-фунтова курка.\n\nЩо хоче зробити гном з 500-фунтовою куркою, я ніколи не зрозумію...\n\n<Могиль щось бурмоче під ніс.>\n\nМожливо, щоб спати в ньому... Брудні гноми...", [3] = "Доставте 500-фунтову курку Нараіну Тихомрію в Танаріс.", [4] = "Що це за чудовий запах?", [5] = "<Нараін обома руками рве величезну курку, зариваючись носом у смачну страву Могиля.>\n\nМмм... Це неймовірно! Найкраща курка, яку я коли-небудь їв!", ["en"] = "Return to Narain", ["tasks"] = { ["500 Pound Chicken"] = "500-фунтова курка", ["500 Pound Chicken (Provided)"] = "500-фунтова курка (видано)" } },
    [8588] = { [1] = "Орді потрібна важка шкіра!", [2] = "Раз ми вже готуємся до війни, буде краще, якшо ми підготуємся як слід, як думаєш, {стать:друже:подруго}? Одним з основних матеріалів для військового спорядження є важка шкіра. Ми використовуєм її скрізь. Від укріплення броні до старих добрих пасток.\n\nАле спершу нам треба дістать якомога більше шкіри. Це твоя робота, {клас:к}. Нагостри ножа та принеси мені цілий стіс шкіри. Тоді ми й поговорим.", [3] = "Принесіть 10 важких шкір шкірниці Джамані в долину Духів в Орґріммарі.", [4] = "Якщо ти {стать:прийшов:прийшла} сюди потеревенить, то у мене нема часу на балачки, {клас:к}. Нам ше треба зібрать купу стосів важкої шкіри. Повертайся до мене, як найдеш хоча б 10 штук.", [5] = "О, то ти {стать:приніс:принесла} важку шкіру. У тебе справді гострий ніж, {клас:к}, це гарні шкіри! Тепер, коли ми з тобою порозумілись, я подбаю про те, шоб твій внесок використали з користю. І якщо знайдеш більше важкої шкіри — неси її мені.", ["en"] = "The Horde Needs Heavy Leather!", ["tasks"] = { ["Heavy Leather"] = "важка шкіра", ["Heavy Leather (Provided)"] = "важка шкіра (видано)" } },
    [8589] = { [1] = "Орді потрібно більше важкої шкіри!", [4] = "Це правда, {клас:к}, мені все ще потрібна важка шкіра. Запити від генералів та квартирмейстерів здаються нескінченними. Але це ще ніщо в порівнянні з тим, що просять провідники цепелінів!\n\nМені доведеться, мабуть, виконати подвійну норму. {ім'я}, принеси мені більше важкої шкіри, і якнайшвидше!", [5] = "А най його! Красно дякую тобі за важку шкіру. Кожен маленький етап наближає нас до нашої цілі. Я покладу ці шкіри у купу, щоб інші шкірники почали з ними працювать.\n\nІще раз дякую, {ім'я}, якшо раптом знайдеш більше стосів важкої шкіри — ти знаєш, де мене знайти.", ["en"] = "The Horde Needs More Heavy Leather!", ["tasks"] = { ["Heavy Leather"] = "важка шкіра", ["Heavy Leather (Provided)"] = "важка шкіра (видано)" } },
    [859] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [8590] = { [1] = "Орді потрібна товста шкіра!", [2] = "Я рада, що ти {стать:вирішив:вирішила} поговорити зі мною, {клас:к}. Схоже, що підготовка Орди до прийдешньої війни у повному розпалі. Але нам з тобою все ще потрібно виконати свою частину завдання.\n\nМене попросили зібрати велику кількість товстої шкіри на створення військового спорядження, і мені потрібно, щоб ти {стать:допоміг:допомогла} зібрати її. Якщо ти нам допоможеш, Орда буде вдячна тобі.", [3] = "Принесіть 10 товстих шкір сержантці Умалі в долину Духів в Орґріммарі.", [4] = "{Клас:к}, ти {стать:повернувся:повернулася} з товстою шкірою, про яку ми говорили?", [5] = "Хороша робота, {клас:к}. Я впевнена, що ця товста шкіра піде на цепеліни та на створення різних видів обладунків та зброї. Я та вся Орда вдячні тобі. Повертайся до мене, якщо знайдеш більше товстої шкіри.", ["en"] = "The Horde Needs Thick Leather!", ["tasks"] = { ["Thick Leather"] = "товста шкіра", ["Thick Leather (Provided)"] = "товста шкіра (видано)" } },
    [8591] = { [1] = "Орді потрібно більше товстої шкіри!", [4] = "{Клас:к}, як ти можеш бачити, я все ще продовжую збирати товсту шкіру. І я знову попрошу тебе про допомогу. Обіцяю, Орда не забуде докладених тобою зусиль.\n\nУ нас обмаль часу! Повертайся до мене з товстою шкірою, щоб ми могли скоріше закінчити підготовку і вирушити на війну, {стать:герою:героїне}!", [5] = "Ти {стать:зробив:зробила} це, я знала, що ти впораєшся! Ще раз дякую тобі від імені всієї Орди. Твої внески не залишаться непоміченими. І якщо тобі вдасться знайти більше товстої шкіри, яку ти захочеш пожертвувати — принось її до мене.\n\nЛок'тар оґар, {клас:к}!", ["en"] = "The Horde Needs More Thick Leather!", ["tasks"] = { ["Thick Leather"] = "товста шкіра", ["Thick Leather (Provided)"] = "товста шкіра (видано)" } },
    [8592] = { [1] = "Тіара оракула", [2] = "Імператори-близнюки... Їхній невпинний шепіт потроху зводить мене з розуму. Вони знущаються з мене, знаючи, що я не можу ступити ні кроку в їхні володіння, щоб врятувати свого брата Ариґоса.\n\nУ своїх видіннях я бачу їхні жахливі голови, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці кіразькі символи сили на те, що більше відповідатиме нашим потребам.\n\nПринеси мені необхідні компоненти, {ім'я}, і я дам тобі головний убір незрівнянної сили.", [3] = "Принесіть вінець Век'нілаша, 2 ідоли мудреця, 5 срібних та 5 кістяних скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просила, {ім'я}?", [5] = "Тобі вдалося! Шепіт імператорів-близнюків припинився.\n\nПрийми це як нагороду. Один лише вид цієї речі вселятиме страх у серця кіражів... це нагадуватиме їм про їхніх полеглих лідерів і {стать:смертного:смертну}, {стать:який їх вбив:яка їх вбила}.", ["en"] = "Tiara of the Oracle", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Idol of the Sage"] = "ідол мудреця", ["Idol of the Sage (Provided)"] = "ідол мудреця (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)", ["Vek'nilash's Circlet"] = "вінець Век'нілаша", ["Vek'nilash's Circlet (Provided)"] = "вінець Век'нілаша (видано)" } },
    [8593] = { [1] = "Штани оракула", [2] = "Прагнеш довести свою цінність моєму роду, {стать:смертний:смертна}? Дуже добре, можливо, ми зможемо допомогти одне одному.\n\nДревній піщаний черв'як Оуро — істота легендарної сили. Подейкують, що його створив сам Старий Бог як наругу над життям.\n\nЙого шкіра неприродна... товста, майже неприступна, але при цьому така гнучка, що дозволяє йому швидко рухатися з грацією дрібної істоти.\n\nПринеси мені зразок його шкіри з іншими другорядними компонентами, і я зроблю для тебе поножі великої сили.", [3] = "Принесіть неушкоджену шкуру Оуро, 2 ідоли життя, 5 золотих та 5 глиняних скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просив, {ім'я}?", [5] = "Так... зі шкіри черв'яка можна зробити чудовий захисний шар. У поєднанні з найсильнішими частинами кіражів, яких ми знищили на нашому шляху сюди, ми створимо міцний обладунок. Нехай це допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!", ["en"] = "Trousers of the Oracle", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Idol of Life"] = "ідол життя", ["Idol of Life (Provided)"] = "ідол життя (видано)", ["Ouro's Intact Hide"] = "неушкоджена шкура Оуро", ["Ouro's Intact Hide (Provided)"] = "неушкоджена шкура Оуро (видано)" } },
    [8594] = { [1] = "Наплічники оракула", [2] = "Як у нас в народі кажуть, що ошатні наплічні обладунки, які носять смертні, були створені для імітації драконячих крил.\n\nПринеси мені наручники, які належать кіразьким лідерам, і я зроблю з них наплічники іще страхітливіші, ніж крила самого Нефаріана!", [3] = "Принесіть кіразькі наручі командування, 2 ідоли відродження, 5 срібних скарабеїв та 5 скарабеїв зі слонової кістки до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} компоненти, які я просила?", [5] = "З матеріалів, які ти {стать:приніс:принесла}, і з луски наших полеглих ворогів, я зроблю для тебе ці наплічники, {стать:смертний:смертна}. Нехай вони нададуть тобі потрібний захист. Нехай їхній вигляд вселяє страх в наших ворогів.", ["en"] = "Mantle of the Oracle", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Idol of Rebirth"] = "ідол відродження", ["Idol of Rebirth (Provided)"] = "ідол відродження (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Qiraji Bindings of Command"] = "кіразькі наручі командування", ["Qiraji Bindings of Command (Provided)"] = "кіразькі наручі командування (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)" } },
    [8595] = { [1] = "Смертні чемпіони", [4] = "Вбивство одно лорда кіражі — це велике досягнення для {стать:смертного:смертної}, {ім'я:к}. Однак їх все ще багато, і вони могутні. Продовжуй вбивати їх, щоб довести, що ти все ще {стать:гідний:гідна} бути {стать:нашим чемпіоном:нашою чемпіонкою}.", [5] = "Ти продовжуєш добре служити нам, {ім'я}. Наш союз залишається в силі.", ["en"] = "Mortal Champions", ["tasks"] = { ["Qiraji Lord's Insignia"] = "відзнака кіразького володаря", ["Qiraji Lord's Insignia (Provided)"] = "відзнака кіразького володаря (видано)" } },
    [8596] = { [1] = "Ножні обмотки оракула", [2] = "Магія кіражів дуже сильна та древня. Наймогутніші кіражі володіють предметами такої могутності, що вони могли б зупинити навіть дракона.\n\nПринеси мені кіразькі наручі командування та інші другорядні компоненти, і я створю для тебе могутні чоботи.\n\nВони знадобляться тобі в битві проти наших ворогів.", [3] = "Принесіть кіразькі наручі командування, 2 ідоли смерті, 5 бронзових та 5 золотих скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} предмети, які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Ти {стать:довів:довела}, що ти не {стать:звичайний смертний:звичайна смертна}.\n\nЯ впевнений, що вони допоможуть тобі трощити нікчемних кіражів.", ["en"] = "Footwraps of the Oracle", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Idol of Death"] = "ідол смерті", ["Idol of Death (Provided)"] = "ідол смерті (видано)", ["Qiraji Bindings of Command"] = "кіразькі наручі командування", ["Qiraji Bindings of Command (Provided)"] = "кіразькі наручі командування (видано)" } },
    [8597] = { [1] = "Мова драконів для початківців", [2] = "Я знав, що та книга колись згодиться! На щастя, мені вистачило розуму і передбачливості сховати її в безпечному місці.\n\nНе хвилюйся, вона там, де її ніхто ніколи не знайде! Щоб туди потрапити, мені знадобився гірокоптер. На жаль, я розбив його на пляжі, коли повертався. Саме завдяки тій аварії я отримав ці супер-гномські екстрасенсорні здібності!\n\nШукай мій розбитий гірокоптер десь на узбережжі на Краю землі та пливи на південь від нього! Ти впізнаєш місце, коли побачиш його!", [3] = "Знайдіть книгу Нараіна Тихомрія, закопану на острові в Південних морях.", [5] = "Книга зникла! На купі землі лежить записка.", ["en"] = "Draconic for Dummies" },
    [8598] = { [1] = "вИКуП", [2] = "<Текст на цій записці складається з різних шрифтів, вклеєних на поверхню пергаменту.>\n\nТвоя дорогоцінна книга у нас, гноме. Якщо ти хочеш її повернути, ти повинен зробити все, що ми скажемо.\n\n<На трьох сторінках перелічені детальні вказівки.>\n\nПриходь сам та з грошима!", [3] = "Поверніть лист з вимогою викупу Нараіну Тихомрію в Танаріс.", [4] = "Кажи, в чому справа?", [5] = "<Обличчя Нараіна багряніє.>\n\nМою... книгу... вкрали?! Книгокради! Я покажу їм, що значить зв'язуватися з гномом-екстрасенсом!", ["en"] = "rAnS0m", ["tasks"] = { ["Ransom Letter"] = "лист з вимогою викупу", ["Ransom Letter (Provided)"] = "лист з вимогою викупу (видано)" } },
    [8599] = { [1] = "Любовна пісня для Нараіна", [2] = "До мене нечасто навідуються гості. Власне кажучи, востаннє у мене був відвідувач, коли я врятувала того милого гнома з-під уламків летючого апарату.\n\n<Меридіт дивиться у нікуди, занурившись в спогади.>\n\nТи знаєш його? Нараіна? Нараіна Тихомрія? О, це б так багато значило для мене, якби хтось передав йому мого листа. Я повинна сказати йому, що я відчуваю! Я знаю, це кохання! Я просто знаю!\n\nМожливо, ти {стать:міг би:могла б} передати листа Нараіну? Я була б у вічному боргу перед тобою!", [3] = "Принесіть любовний лист Меридіт до Нараіна Тихомрія в Танаріс.", [4] = "Від тебе смердить рибою!", [5] = "Що?!\n\n<Нараін починає метушитися.>\n\nНу... Що ти хочеш, щоб я зробив? Вона риба! РИБА, кажу тобі! А я гном. Нічого не вийде.", ["en"] = "Love Song for Narain", ["tasks"] = { ["Meridith's Love Letter"] = "любовний лист Меридіт", ["Meridith's Love Letter (Provided)"] = "любовний лист Меридіт (видано)" } },
    [860] = { [1] = "Серґра Темношип", [2] = "Якщо бажаєш стати на шлях мисливця - тобі пряма дорога до Степів. Тамтешні звірі - вольові та люті. Ти багато чого навчишся, полюючи там, а твій дух зміцніє.\n\nПоговори з Серґрою Темношип. Вона стане твоєю першою наставницею у Степах.\n\nСерґра мешкає на Перехресті. Щоб дістатися до неї, йди на схід від селища Криваве Копито прямісінько в Степи, потім повертай на північ, як дійдеш до роздоріжжя. І будь {стать:обережним:обережною}: Степи таять велику небезпеку для непідготовлених і необачних.", [3] = "Поговоріть із Серґрою Темношип на Перехресті.", [5] = "Прагнеш полювати в Степах?\n\nОчі твої нетерплячі, молоді. Вони ще не зіщулені від постійного переслідування здобичі по висохлих рівнинах цієї землі.\n\nАле турбуватися не варто. Ми загартуємо твоє тіло та розум. І ти пізнаєш, що мисливство - це більше, ніж знайти та вбити здобич.\n\nПриготуйся. Твоя подорож починається. Прямо зараз.", ["en"] = "Sergra Darkthorn" },
    [8600] = { [1] = "Орді потрібна міцна шкіра!", [2] = "Я зрозумів, що посадка ножа в долоні важлива навіть більше, ніж його гострота. Навіть найтупіший клинок здатен порізати, якщо докласти потрібне зусилля, чи не так, {клас:к}? Але у нас з тобою не буде таких проблем, адже наші ножі завжди заточені, так?\n\nЩо ж, це не важливо, я маю для тебе завдання. Дістань мені якомога більше міцної шкіри — для Орди та для нашої підготовки до війни в Ан'Кіражі. Впораєшся з цим?", [3] = "Принесіть 10 міцних шкір доктору Серратусу в долину Духів в Орґріммарі.", [4] = "Не може бути, щоб зрізка десятка міцних шкір зайняла у тебе так багато часу! Можливо, тобі варто загострити свого ножа для шкірництва? Чи я помиляюся, і шкіра вже у тебе в рюкзаку?", [5] = "Чудово, схоже, що ти добре {стать:впорався:впоралася} з цим завданням, хоча у деяких шкір краї не дуже рівно обрізані. Але це не важливо, завдання виконане, і ти отримаєш свою винагороду. Якщо раптом знайдеш більше міцної шкіри — принось її до мене.", ["en"] = "The Horde Needs Rugged Leather!", ["tasks"] = { ["Rugged Leather"] = "міцна шкіра", ["Rugged Leather (Provided)"] = "міцна шкіра (видано)" } },
    [8601] = { [1] = "Орді потрібно більше міцної шкіри!", [4] = "Підготовка до неминучої війни в Ан'Кіражі продовжується, {клас:к}. Проте, щоб впевнитися, що ніхто не помре, принаймні не через мене, я хочу, щоб ти {стать:приніс:принесла} ще один стіс міцної шкіри. Я буду дуже вдячним тобі, {ім'я}.", [5] = "Практика, практика, практика. З гарно відточеним ножем та навичками, ти далеко підеш, {клас:к}. Схоже, що краї шкіри обрізані краще, ніж минулого разу. Ти {стать:придбав:придбала} нового ножа?\n\nУ будь-якому разі, ми дякуємо тобі за твої зусилля. Твоя пожертва піде на добру справу та не залишиться непоміченою, запевняю тебе. Якщо знайдеш ще міцної шкіри — обов'язково принось, вона точно мені знадобиться.", ["en"] = "The Horde Needs More Rugged Leather!", ["tasks"] = { ["Rugged Leather"] = "міцна шкіра", ["Rugged Leather (Provided)"] = "міцна шкіра (видано)" } },
    [8602] = { [1] = "Напліччя бурезова", [2] = "Як у нас в народі кажуть, що прикрашені наплічні обладунки, які носять смертні, були створені для імітації драконячих крил.\n\nПринеси мені наручі вищих кіразьких лідерів, і я зроблю з них наплічники, страхітливіші за крила самого Нефаріана!", [3] = "Принесіть кіразькі наручі домінування, 2 ідоли життя, 5 золотих та 5 кришталевих скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} компоненти, які я просила?", [5] = "З матеріалів, які ти {стать:приніс:принесла}, і з луски наших полеглих ворогів, я зроблю для тебе ці напліччя, {стать:смертний:смертна}. Нехай вони нададуть тобі потрібний захист. Нехай їхній вигляд вселяє страх в наших ворогів.", ["en"] = "Stormcaller's Pauldrons", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Idol of Life"] = "ідол життя", ["Idol of Life (Provided)"] = "ідол життя (видано)", ["Qiraji Bindings of Dominance"] = "кіразькі наручі домінування", ["Qiraji Bindings of Dominance (Provided)"] = "кіразькі наручі домінування (видано)" } },
    [8603] = { [1] = "Вбрання оракула", [2] = "Старий Бог, ім'я якого ми не згадуємо, повільно прокидається від свого сну під Ан'Кіражем. Жахлива доля може спіткати Азерот за кілька днів або років. Час не має значення для істот його сили.\n\nЗійдуться зірки — і його страшний гнів кинеться на все живе. Ти маєш знайти його раніше та покласти край його існуванню.\n\nЗроби це та принеси мені шматок його оболонки. Натомість я дам тобі обладунок, яким не володів ще ніхто зі смертних... обладунок, гідний вбивці бога!", [3] = "Принесіть оболонку Старого Бога, 2 ідоли смерті, 5 кам'яних та 5 кришталевих скарабеїв Ветзері в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Роду Ноздорму.", [4] = "У своїй оселі в Ан'Кіражі, жихливий К'Тун спить і чекає, коли прийде його час.", [5] = "Я не очікувала, що ти повернешся, {ім'я}.\n\nТи {стать:здійснив:здійснила} подвиг величніший, ніж більшість безсмертних істот.\n\nВбивши К'Туна, ти не тільки {стать:врятував:врятувала} весь Азерот, але й {стать:перехилив:перехилила} терези космічних сил, про які ти навіть і не {стать:знав:знала}.\n\nПрийми ці вбрання як символ слави та тягаря, що буде наслідком твоїх дій.\n\nНехай їхня сила допоможе тобі у випробуваннях, які чекають на тебе, вбивце богів!", ["en"] = "Vestments of the Oracle", ["tasks"] = { ["9000 reputation with Brood of Nozdormu"] = "9000 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Husk of the Old God"] = "оболонка Старого Бога", ["Husk of the Old God (Provided)"] = "оболонка Старого Бога (видано)", ["Idol of Death"] = "ідол смерті", ["Idol of Death (Provided)"] = "ідол смерті (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8604] = { [1] = "Орді потрібні вовняні бинти!", [2] = "Вітаю, {клас:к}. Мені доручено збирати вовняні бинти для підготовки до війни в Ан'Кіражі. На жаль, на полі бою солдати не зможуть повною мірою покладатися на цілителів. Повір мені, я знаю це з власного досвіду. Тому ми збираємо для них все необхідне в аптечки.\n\nЯкщо у тебе є час, допоможи мені зібрати вовняні бинти. Принесіть їх мені, і я подбаю про те, щоб тебе належним чином винагородили.", [3] = "Принесіть 20 вовняних бинтів цілителю Довгобігу в долину Духів в Орґріммарі.", [4] = "А, {клас}, вже так швидко {стать:повернувся:повернулася} з вовняними бинтами?", [5] = "Прийми мою подяку, {клас:к}, а разом з нею і подяку всієї Орди. Якщо тобі ще трапляться вовняні бинти — принось їх мені, якщо бажаєш зробити внесок у підготовку до війни. А поки що — хай бережуть тебе предки!", ["en"] = "The Horde Needs Wool Bandages!", ["tasks"] = { ["Wool Bandage"] = "вовняний бинт", ["Wool Bandage (Provided)"] = "вовняний бинт (видано)" } },
    [8605] = { [1] = "Орді потрібно більше вовняних бинтів!", [4] = "Радий знову бачити тебе, {клас:к}. Ми все ще працюємо над підготовкою до війни, і я буду вкрай вдячний за будь-яку допомогу з вовняними бинтами. Я лише сподіваюся, що наших зусиль буде достатньо. У минулих битвах через нестачу першої допомоги загинуло надто багато хороших солдатів. І я маю зробити все, що в моїх силах, щоб цього не повторилося.", [5] = "Ти дійсно {стать:благородний:благородна} {клас:н}, {ім'я}! Я переконаюся, щоб ці бинти потрапили в потрібні руки. Прийми мою вдячність та вдячність Орди.\n\nЙди з миром і обов'язково повертайся, якщо знайдеш ще більше вовняних бинтів. Нам тут знадобиться будь-яка допомога.", ["en"] = "The Horde Needs More Wool Bandages!", ["tasks"] = { ["Wool Bandage"] = "вовняний бинт", ["Wool Bandage (Provided)"] = "вовняний бинт (видано)" } },
    [8606] = { [1] = "Приманка!", [2] = "У мене є ідея! Ось що ми зробимо. Я наберу мішок каменів, а ти підеш на обмін. Я знаю, що обмінмаю здійснити я, і я збираюся — типу того.\n\n<Нараін оглядає вас з голови до ніг.>\n\nТак, ти підійдеш. Візьми цей тюрбан, цю мантію і мішок з каменями та вирушай до місця обміну в Зимоключ.\n\nЯ додав у цей спеціальний набір все, що тобі потрібно. Коли вони з'являться, щоб забрати товар, вбий їх! Це навчить їх не зв'язуватися з Нараіном!", [3] = "Нараін Тихомрій з Танарісу хоче, щоб ви вирушили в Зимоключ і залишили мішок золота у вказаній книгокрадами точці.", [5] = "Я думаю, що ми недооцінили цих книгокрадів.", ["en"] = "Decoy!", ["tasks"] = { ["Who Does Number Two Work For?"] = "Для кого працює Номер Два?", ["Who Does Number Two Work For? (Provided)"] = "Для кого працює Номер Два? (видано)", ["Who Does Number Two Work For? slain"] = "Для кого працює Номер Два?: убито" } },
    [8607] = { [1] = "Орді потрібні маготкані бинти!", [2] = "Сподіваюся, що ти говориш зі мною, бо хочеш допомогти зі збором матеріалів, який мені назначили? Чудово! Мені потрібно, щоб ти {стать:зібрав:зібрала} якомога більше маготканих бинтів. Бажано, щоб вони були свіжими, але це необов'язково. Принеси їх мені, {клас:к}, і я особисто прослідкую, щоб тебе винагородили належним чином.", [3] = "Принесіть 20 маготканих бинтів леді Келлоу в долину Духів в Орґріммарі.", [4] = "Не підведи мене, {клас:к}! Повертайся якомога швидше з маготканими бинтами.", [5] = "Дивно, але прийнятно. Можливо, я недооцінила твої \"здібності\", {клас:к}. Можливо. Ти {стать:виконав:виконала} дуже просте завдання, але за це ти отримаєш чималу нагороду. Утім, не бери в голову. Якщо справді хочеш довести, чого {стать:вартий:варта} — принеси мені більше маготканих бинтів.", ["en"] = "The Horde Needs Mageweave Bandages!", ["tasks"] = { ["Mageweave Bandage"] = "маготканий бинт", ["Mageweave Bandage (Provided)"] = "маготканий бинт (видано)" } },
    [8608] = { [1] = "Орді потрібно більше маготканих бинтів!", [4] = "Ти {стать:повернувся:повернулася}? Цікаво. Я ти можеш бачити, я все ще збираю ресурси для війни в Ан'Кіражі. А це означає, що мені знову потрібно, щоб ти {стать:зібрав:зібрала} стос маготканих бинтів. Я чекатиму твого повернення, {клас:к}.", [5] = "Дивовижно, {клас:к}, ти знову це {стать:зробив:зробила}! Недарма кажуть, що у мене гарний смак у виборі прислужників. Дуже добре, твій внесок не залишиться непоміченим і ти неодмінно отримаєш винагороду відповідно до своїх заслуг. Але я гадаю, що тобі слід зібрати ще один набір маготканих бинтів, якщо ти справді хочеш довести, чого {стать:вартий:варта}.", ["en"] = "The Horde Needs More Mageweave Bandages!", ["tasks"] = { ["Mageweave Bandage"] = "маготканий бинт", ["Mageweave Bandage (Provided)"] = "маготканий бинт (видано)" } },
    [8609] = { [1] = "Орді потрібні рунічні бинти!", [2] = "Альянс та Орда готуються до невідворотної війни в Ан'Кіражі. Дивно, але вони збираються воювати не одне з одним, а проти сілітидів та сил, які їх контролюють. Не менш дивно, що обидві сторони роблять все можливе, щоб зібрати необхідні ресурси для війни.\n\nЯ відповідаю за збір рунічних бинтів, щоб роздати їх солдатам, але одна я точно не впораюся. Можливо, ти зможеш мені допомогти, {клас:к}?", [3] = "Принесіть 20 рунічних бинтів кам'яній вартовій Глиняному Копиту в долину Духів в Орґріммарі.", [4] = "Я думаю, що війна почнеться зовсім скоро, {клас:к}. Дякую, що {стать:знайшов:знайшла} час на допомогу в зборі ресурсів. Тобі вже вдалося дістати рунічні бинти?", [5] = "Ти — гордість Орди, {клас:к}. Дякую за твої зусилля, вони будуть гідно винагороджені! Я маю скласти ці бинти та ще раз порахувати, як далеко ми наблизилися до нашої мети. Якщо хочеш — можеш зібрати більше рунічних бинтів та принести їх мені.", ["en"] = "The Horde Needs Runecloth Bandages!", ["tasks"] = { ["Runecloth Bandage"] = "рунічний бинт", ["Runecloth Bandage (Provided)"] = "рунічний бинт (видано)" } },
    [8610] = { [1] = "Орді потрібно більше рунічних бинтів!", [4] = "Наближається час, коли ми стрімголов кинемося до бою та пройдемо вогнем та мечем по Ан'Кіражу, {клас:к}. Але спершу ми маємо зібратися з силами та підготуватися, щоб витримати натиск комах та їхніх господарів.\n\nЯкщо ти знову тут, то, напевно, бажаєш внести чергову пожертву рунічних бинтів на потреби наших військ. Прошу, зроби це якнайшвидше і повертайся до мене знову.", [5] = "Це дуже безкорисливий вчинок, {ім'я}. Можливо, він врятує життя багатьом нашим бійцям в Ан'Кіражі. Дякую, і знай, що Орда вдячна тобі за твою пожертву. Якщо ти зробиш або знайдеш нові рунічні бинти — принось їх мені.", ["en"] = "The Horde Needs More Runecloth Bandages!", ["tasks"] = { ["Runecloth Bandage"] = "рунічний бинт", ["Runecloth Bandage (Provided)"] = "рунічний бинт (видано)" } },
    [8611] = { [1] = "Орді потрібні пісні вовчі стейки!", [2] = "Я стою тут не задля красивої засмаги, {клас:к}. Треба готуватися до війни. Якщо ми збираємося розтрощити цих жуків в Ан'Кіражі, ми повинні бути готовими, і я кажу про їжу теж!\n\nМені доручили збирати та засолювати пісні вовчі стейки для прийдешньої війни. Але оскільки я стою тут та слідкую за всім, мені потрібно, щоб ти {стать:вбив:вбила} кількох вовків та {стать:приготував:приготувала} з них пісні вовчі стейки. А потім ти маєш принести їх сюди. Все зрозуміло?", [3] = "Принесіть 20 пісних вовчих стейків кривавій вартовій Сиромаз в долину Духів в Орґріммарі.", [4] = "Вже {стать:повернувся:повернулася} з пісними вовчими стейками, {клас:к}? Мені байдуже, якщо вони пересмажені чи недосмажені, головне, щоб їх можна було жувати та щоб вони опинилися в мене якнайшвидше!", [5] = "Гаразд, це м'ясо має непоганий вигляд. Я засолю його, а потім приберу на зберігання. Сподіваюся, воно буде достатньо їстівним, коли прийде час.\n\nДякую за твій внесок, {клас:к}. Як щодо того, щоб принести мені ще порцію стейків?", ["en"] = "The Horde Needs Lean Wolf Steaks!", ["tasks"] = { ["Lean Wolf Steak"] = "пісний вовчий стейк", ["Lean Wolf Steak (Provided)"] = "пісний вовчий стейк (видано)" } },
    [8612] = { [1] = "Орді потрібно більше пісних вовчих стейків!", [4] = "Як бачиш, {клас:к}, нам все ще потрібно багато їжі для наших солдатів. Я не знаю, чи {стать:був:була} ти коли-небудь на війні, але як тільки ти переживеш початковий шок, ти зголоднієш. Ти гарно {стать:впорався:впоралася} минулого разу, тож я очікую від тебе не гіршого результату з пісними вовчими стейками.", [5] = "Пахне так, ніби хтось тут добре готує, {ім'я}. Від цих вовчих стейків у мене аж слина тече. Гадаю, ніхто не помітить зникнення кількох з них. У будь-якому випадку, гарна робота. Я простежу, щоб їх правильно запакували, щоб вони не зіпсувалися.\n\nЯкщо знайдеш ще — ти знаєш, де мене шукати.", ["en"] = "The Horde Needs More Lean Wolf Steaks!", ["tasks"] = { ["Lean Wolf Steak"] = "пісний вовчий стейк", ["Lean Wolf Steak (Provided)"] = "пісний вовчий стейк (видано)" } },
    [8613] = { [1] = "Орді потрібен плямистий жовтохвіст!", [2] = "Який чудовий день для риболовлі, чи не так, друзяко? Це добре, адже мені понадобиться багацько риби. Орда назначила мене за главного у зборі тонни плямистих жовтохвостів. Вони сказали, шо вони потрібні, шоб підготуваться до війни в Ан'Кіражі. Я їм сказав, шо зроблю все можливе. Отже, мені треба допомога. Ти мені поможеш, {клас:к}?", [3] = "Принесіть 20 плямистих жовтохвостів рибалці Лін'до в долину Духів в Орґріммарі.", [4] = "Ти вже {стать:вернувся:вернулась} з плямистим жовтохвостом, {клас:к}? Ти не {стать:забув:забула} її гарненько приготувать? Ми ж не дамо сиру рибу солдатам під гарячим сонцем пустелі.", [5] = "О, так, це хороша риба. Я зараз її гарно запакую, шоб не зіпсувалась. Дякую, шо {стать:виручив:виручила} мене. Думаю, ти будеш {стать:найкращим:найкращою} рибалкою на плямистого жовтохвоста. Якщо вийде наловить та приготувать ше — принось його мені. Я подбаю про те, шоб всі знали, шо ти це {стать:зробив:зробила}!", ["en"] = "The Horde Needs Spotted Yellowtail!", ["tasks"] = { ["Spotted Yellowtail"] = "плямистий жовтохвіст", ["Spotted Yellowtail (Provided)"] = "плямистий жовтохвіст (видано)" } },
    [8614] = { [1] = "Орді потрібно більше плямистих жовтохвостів!", [4] = "Як бач, нам потрібно ше чимало риби. Бійцям прийдешньої війни в Ан'Кіражі треба буде багато їсти, тож я маю назбирать стільки плямистих жовтохвостів, скільки зможу. Налови їх побільше, приготуй і неси мені, а я буду тобі вдячним, як і вся Орда.", [5] = "Це найкращий улов, {ім'я}! Добра чесна робота. І ніяких кісток! Дякую тобі за плямистих жовтохвостів, {стать:друже:подруго}. Приходь коли ти приготуєш ше!", ["en"] = "The Horde Needs More Spotted Yellowtail!", ["tasks"] = { ["Spotted Yellowtail"] = "плямистий жовтохвіст", ["Spotted Yellowtail (Provided)"] = "плямистий жовтохвіст (видано)" } },
    [8615] = { [1] = "Орді потрібен запечений лосось!", [2] = "Підготовка до війни в Ан'Кіражі — це величезна робота, {клас:к}. Всі матеріали, що збираються тут, чи то метал для зброї, чи їжа для вживання, не менш важливі за інші. Адже якщо ти не поїси кілька днів, то й не матимеш достатньо сили, щоб просто підняти сокиру.\n\nОсь ми й збираємо їжу, яку тільки можемо. Я збираю запечених лососів — страву, яку обрали за її поживність та здатність добре зберігатися. Ти зможеш допомогти мені з цим завданням, {клас:к}?", [3] = "Принесіть 20 запечених лососів вождю Гострому Кігтю в долину Духів в Орґріммарі.", [4] = "Ти вже {стать:повернувся:повернулася} з запеченим лососем, {клас:к}? Пам'ятай, що він має бути приготований. На жаль, я не можу приймати сиру рибу.", [5] = "Дякую за допомогу зі збором припасів для війни, {клас:к}. Багатьом немає ніякого діла до війни, їх цікавить лише прибуток. Але вони не мають вдячності Орди, на відміну від тебе. Нехай твоє серце сповниться гордості за свої безкорисливі діяння.\n\nЩе раз дякую тобі. Якщо ти знайдеш час, щоб допомогти нам ще — я чекатиму тут.", ["en"] = "The Horde Needs Baked Salmon!", ["tasks"] = { ["Baked Salmon"] = "запечений лосось", ["Baked Salmon (Provided)"] = "запечений лосось (видано)" } },
    [8616] = { [1] = "Орді потрібно більше запеченого лосося!", [4] = "Остання партія запеченого лосося, яку ти {стать:пожертвував:пожертвувала} для підготовки до війни, виглядала дуже смачно, {клас:к}. Мушу визнати, що я ледь не спокусився взяти трошки собі. Як ти можеш здогадатися, ми ще не досягли нашої мети. Я сподіваюся, ти {стать:повернувся:повернулася}, бо у тебе є ще ціла купа запеченого лосося?", [5] = "Твоя пожертва часу та сил для підготовки до війни не пропаде даремно, {ім'я}. Прийми мою подяку і подяку всієї Орди. Повертайся, коли приготуєш нову партію риби.", ["en"] = "The Horde Needs More Baked Salmon!", ["tasks"] = { ["Baked Salmon"] = "запечений лосось", ["Baked Salmon (Provided)"] = "запечений лосось (видано)" } },
    [8617] = { [1] = "Орді потрібні обпалені вулканічні камені!", [2] = "Настав час тобі внести свій внесок у підготовку до війни в Ан'Кіражі, {клас:к}. Пройшли ті безтурботні дні, коли ти {стать:витрачав:витрачала} час на дозвілля. Тепер настав час служити мені та Орді, і я запевняю тебе, що я не такий поблажливий, як воєвождь.\n\nТи збереш свої сили, гільдію, якщо вона в тебе є, і ви підете у Палаюче Ядро. Всередині ви побачите, що мешканці цього місця мають обпалені вулканічні камені. Принеси їх мені, і якомога більше.", [3] = "Принесіть 50 обпалених вулканічних каменів генералу Зоґу в Дуротар.", ["en"] = "The Horde Needs Singed Corestones!", ["tasks"] = { ["Singed Corestone"] = "обпалений вулканічний камінь" } },
    [8619] = { [1] = "Предок Світанник", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Morndeep the Elder" },
    [862] = { [1] = "Рагу з печерних щурів", [2] = "{стать:Такий:Така} {клас}, як ти, певно, любить добре попоїсти. Я от постійно хочу їсти.\n\nЯ приготую тобі смачний гуляш. Тільки мені потрібні печерні щури.\n\nІ схоже, що у брудних дворфів в Бель-Модані водиться купа цих смаколиків. Тож йди на південь до Бель-Модана і принеси мені кількох печерних щурів.\n\nТи не станеш {стать:досвідченим пригодником:досвідченою пригодницею}, доки не наб'єш руку на щурах! Ха!", [3] = "Принесіть 8 печерних щурів Бубону на сході від Перехрестя.", [4] = "Ти вже {стать:набив:набила} вдосталь щурів, {ім'я}?", [5] = "Зазвичай я не їм цих гризунів, коли вони такі... такі... свіжі. Їм треба полежати кілька тижнів, щоб вони розкрили сіій смак. Але ти виглядаєш {стать:таким голодним:такою голодною}.\n\nДавай-но я зварю для тебе рагу. Ось.\n\nСкуштуй!", ["en"] = "Dig Rat Stew", ["tasks"] = { ["Dig Rat"] = "печерний щур", ["Dig Rat (Provided)"] = "печерний щур (видано)", ["Dig Rat slain"] = "печерний щур: убито" } },
    [8620] = { [1] = "Єдиний спосіб", [2] = "Я мав би здогадатися. Мій заклятий ворог, доктор Жло, взявся за старе! А тепер, через твою поразку в Зимоключі, доктор Жло знищив мою книгу! Як ти тепер збираєшся рятувати світ, {стать:герою:героїне}?\n\nУ записці, яку я отримав, йдеться, що єдина копія \"Мови драконів для початківців: Том II\" була розірвана на 8 частин і розкидана за вітром! Якщо ти якимось чином знайдеш ці втрачені розділи, скористайся цією магічною палітуркою, щоб зібрати їх до купи, і повертайся до мене.", [3] = "Знайдіть 8 втрачених розділів \"Мови драконів для початківців\", об'єднайте їх чарівною палітуркою і поверніть завершену книгу \"Мова драконів для початківців: Том II\" Нараіну Тихомрію в Танаріс.", [4] = "Я вдягаю штани, так само як і ти — по одній холоші за раз. Тільки коли мої штани на мені, я створюю арканітові буї. Арканітові буї, крихітко!", [5] = "Чудово! Не можу повірити, що ти таки {стать:впорався:впоралася} з цим завданням! Ти що, якась машина? Я от, напевно, не заморочувався б і дав світові вибухнути.\n\nЗнімаю перед вами свій тюрбан, {стать:пане:пані}. І жоден добрий вчинок не має залишатися без винагороди.", ["en"] = "The Only Prescription", ["tasks"] = { ["Draconic For Dummies: Volume II"] = "Мова драконів для початківців: Том ІІ", ["Draconic For Dummies: Volume II (Provided)"] = "Мова драконів для початківців: Том ІІ (видано)" } },
    [8621] = { [1] = "Чоботи бурезова", [2] = "Магія кіражів дуже сильна та древня. Наймогутніші кіражі володіють предметами такої могутності, що вони могли б зупинити навіть дракона.\n\nПринеси мені кіразькі наручі домінування та інші другорядні компоненти, і я створю для тебе могутні чоботи.\n\nВони знадобляться тобі в битві проти наших ворогів.", [3] = "Принесіть кіразькі наручі домінування, 2 ідоли мудреця, 5 бронзових та 5 глиняних скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} предмети, які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Ти {стать:довів:довела}, що ти не {стать:звичайний смертний:звичайна смертна}.\n\nЯ впевнений, що вони допоможуть тобі трощити нікчемних кіражів.", ["en"] = "Stormcaller's Footguards", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Idol of the Sage"] = "ідол мудреця", ["Idol of the Sage (Provided)"] = "ідол мудреця (видано)", ["Qiraji Bindings of Dominance"] = "кіразькі наручі домінування", ["Qiraji Bindings of Dominance (Provided)"] = "кіразькі наручі домінування (видано)" } },
    [8622] = { [1] = "Гауберк бурезова", [2] = "Старий Бог, ім'я якого ми не згадуємо, повільно прокидається від свого сну під Ан'Кіражем. Жахлива доля може спіткати Азерот за кілька днів або років. Час не має значення для істот його сили.\n\nЗійдуться зірки — і його страшний гнів кинеться на все живе. Ти маєш знайти його раніше та покласти край його існуванню.\n\nЗроби це та принеси мені шматок його оболонки. Натомість я дам тобі обладунок, яким не володів ще ніхто зі смертних... обладунок, гідний вбивці бога!", [3] = "Принесіть панцир Старого Бога, 2 ідоли мудреця, 5 срібних та 5 кістяних скарабеїв Ветзері в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Роду Ноздорму.", [4] = "У своїй оселі в Ан'Кіражі, жихливий К'Тун спить і чекає, коли прийде його час.", [5] = "Я не очікувала, що ти повернешся, {ім'я}.\n\nТи {стать:здійснив:здійснила} подвиг величніший, ніж більшість безсмертних істот.\n\nВбивши К'Туна, ти не тільки {стать:врятував:врятувала} весь Азерот, але й {стать:перехилив:перехилила} терези космічних сил, про які ти навіть і не {стать:знав:знала}.\n\nПрийми цей гауберк як символ слави та тягаря, що буде наслідком твоїх дій.\n\nНехай його сила допоможе тобі у випробуваннях, які чекають на тебе, вбивце богів!", ["en"] = "Stormcaller's Hauberk", ["tasks"] = { ["9000 reputation with Brood of Nozdormu"] = "9000 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Carapace of the Old God"] = "панцир Старого Бога", ["Carapace of the Old God (Provided)"] = "панцир Старого Бога (видано)", ["Idol of the Sage"] = "ідол мудреця", ["Idol of the Sage (Provided)"] = "ідол мудреця (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)" } },
    [8623] = { [1] = "Діадема бурезова", [2] = "Імператори-близнюки... Їхній невпинний шепіт потроху зводить мене з розуму. Вони знущаються з мене, знаючи, що я не можу ступити ні кроку в їхні володіння, щоб врятувати свого брата Ариґоса.\n\nУ своїх видіннях я бачу їхні жахливі голови, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці кіразькі символи сили на те, що більше відповідатиме нашим потребам.\n\nПринеси мені необхідні компоненти, {ім'я}, і я дам тобі головний убір незрівнянної сили.", [3] = "Принесіть діадему Век'лора, 2 ідоли відродження, 5 кам'яних та 5 кришталевих скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просила, {ім'я}?", [5] = "Тобі вдалося! Шепіт імператорів-близнюків припинився.\n\nПрийми це як нагороду. Один лише вид цієї речі вселятиме страх у серця кіражів... це нагадуватиме їм про їхніх полеглих лідерів і {стать:смертного:смертну}, {стать:який їх вбив:яка їх вбила}.", ["en"] = "Stormcaller's Diadem", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Idol of Rebirth"] = "ідол відродження", ["Idol of Rebirth (Provided)"] = "ідол відродження (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)", ["Vek'lor's Diadem"] = "діадема Век'лора", ["Vek'lor's Diadem (Provided)"] = "діадема Век'лора (видано)" } },
    [8624] = { [1] = "Поножі бурезова", [2] = "Прагнеш довести свою цінність моєму роду, {стать:смертний:смертна}? Дуже добре, можливо, ми зможемо допомогти одне одному.\n\nДревній піщаний черв'як Оуро — істота легендарної сили. Подейкують, що його створив сам Старий Бог як наругу над життям.\n\nЙого шкіра неприродна... товста, майже неприступна, але при цьому така гнучка, що дозволяє йому швидко рухатися з грацією дрібної істоти.\n\nПринеси мені зразок його шкіри з іншими другорядними компонентами, і я зроблю для тебе поножі великої сили.", [3] = "Принесіть шкуру гігантського піщаного черв'яка, 2 ідоли боротьби, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просив, {ім'я}?", [5] = "Так... зі шкіри черв'яка можна зробити чудовий захисний шар. У поєднанні з найсильнішими частинами кіражів, яких ми знищили на нашому шляху сюди, ми створимо міцний обладунок. Нехай це допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!", ["en"] = "Stormcaller's Leggings", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Idol of Strife"] = "ідол боротьби", ["Idol of Strife (Provided)"] = "ідол боротьби (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Skin of the Great Sandworm"] = "шкіра гігантського піщаного черв'яка", ["Skin of the Great Sandworm (Provided)"] = "шкіра гігантського піщаного черв'яка (видано)" } },
    [8625] = { [1] = "Наплічники таїнства", [2] = "Як у нас в народі кажуть, що прикрашені наплічні обладунки, які носять смертні, були створені для імітації драконячих крил.\n\nПринеси мені наручі вищих кіразьких лідерів, і я зроблю з них наплічники, страхітливіші за крила самого Нефаріана!", [3] = "Принесіть кіразькі наручі домінування, 2 ідоли смерті, 5 кам'яних та 5 бронзових скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} компоненти, які я просила?", [5] = "З матеріалів, які ти {стать:приніс:принесла}, і з луски наших полеглих ворогів, я зроблю для тебе ці наплічники, {стать:смертний:смертна}. Нехай вони нададуть тобі потрібний захист. Нехай їхній вигляд вселяє страх в наших ворогів.", ["en"] = "Enigma Shoulderpads", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Idol of Death"] = "ідол смерті", ["Idol of Death (Provided)"] = "ідол смерті (видано)", ["Qiraji Bindings of Dominance"] = "кіразькі наручі домінування", ["Qiraji Bindings of Dominance (Provided)"] = "кіразькі наручі домінування (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8626] = { [1] = "Чоботи нападника", [2] = "Магія кіражів дуже сильна та древня. Наймогутніші кіражі володіють предметами такої могутності, що вони могли б зупинити навіть дракона.\n\nПринеси мені кіразькі наручі командування та інші другорядні компоненти, і я створю для тебе могутні чоботи.\n\nВони знадобляться тобі в битві проти наших ворогів.", [3] = "Принесіть кіразькі наручі командування, 2 ідоли життя, 5 кам'яних та 5 кістяних скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} предмети, які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Ти {стать:довів:довела}, що ти не {стать:звичайний смертний:звичайна смертна}.\n\nЯ впевнений, що вони допоможуть тобі трощити нікчемних кіражів.", ["en"] = "Striker's Footguards", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Idol of Life"] = "ідол життя", ["Idol of Life (Provided)"] = "ідол життя (видано)", ["Qiraji Bindings of Command"] = "кіразькі наручі командування", ["Qiraji Bindings of Command (Provided)"] = "кіразькі наручі командування (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8627] = { [1] = "Кіраса месника", [2] = "Старий Бог, ім'я якого ми не згадуємо, повільно прокидається від свого сну під Ан'Кіражем. Жахлива доля може спіткати Азерот за кілька днів або років. Час не має значення для істот його сили.\n\nЗійдуться зірки — і його страшний гнів кинеться на все живе. Ти маєш знайти його раніше та покласти край його існуванню.\n\nЗроби це та принеси мені шматок його оболонки. Натомість я дам тобі обладунок, яким не володів ще ніхто зі смертних... обладунок, гідний вбивці бога!", [3] = "Принесіть панцир Старого Бога, 2 ідоли мудреця, 5 срібних та 5 кістяних скарабеїв Ветзері в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Роду Ноздорму.", [4] = "У своїй оселі в Ан'Кіражі, жихливий К'Тун спить і чекає, коли прийде його час.", [5] = "Я не очікувала, що ти повернешся, {ім'я}.\n\nТи {стать:здійснив:здійснила} подвиг величніший, ніж більшість безсмертних істот.\n\nВбивши К'Туна, ти не тільки {стать:врятував:врятувала} весь Азерот, але й {стать:перехилив:перехилила} терези космічних сил, про які ти навіть і не {стать:знав:знала}.\n\nПрийми цю кірасу як символ слави та тягаря, що буде наслідком твоїх дій.\n\nНехай її сила допоможе тобі у випробуваннях, які чекають на тебе, вбивце богів!", ["en"] = "Avenger's Breastplate", ["tasks"] = { ["9000 reputation with Brood of Nozdormu"] = "9000 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Carapace of the Old God"] = "панцир Старого Бога", ["Carapace of the Old God (Provided)"] = "панцир Старого Бога (видано)", ["Idol of the Sage"] = "ідол мудреця", ["Idol of the Sage (Provided)"] = "ідол мудреця (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)" } },
    [8628] = { [1] = "Корона месника", [2] = "Імператори-близнюки... Їхній невпинний шепіт потроху зводить мене з розуму. Вони знущаються з мене, знаючи, що я не можу ступити ні кроку в їхні володіння, щоб врятувати свого брата Ариґоса.\n\nУ своїх видіннях я бачу їхні жахливі голови, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці кіразькі символи сили на те, що більше відповідатиме нашим потребам.\n\nПринеси мені необхідні компоненти, {ім'я}, і я дам тобі головний убір незрівнянної сили.", [3] = "Принесіть діадему Век'лора, 2 ідоли відродження, 5 кам'яних та 5 кришталевих скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просила, {ім'я}?", [5] = "Тобі вдалося! Шепіт імператорів-близнюків припинився.\n\nПрийми це як нагороду. Один лише вид цієї речі вселятиме страх у серця кіражів... це нагадуватиме їм про їхніх полеглих лідерів і {стать:смертного:смертну}, {стать:який їх вбив:яка їх вбила}.", ["en"] = "Avenger's Crown", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Idol of Rebirth"] = "ідол відродження", ["Idol of Rebirth (Provided)"] = "ідол відродження (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)", ["Vek'lor's Diadem"] = "діадема Век'лора", ["Vek'lor's Diadem (Provided)"] = "діадема Век'лора (видано)" } },
    [8629] = { [1] = "Поножі месника", [2] = "Прагнеш довести свою цінність моєму роду, {стать:смертний:смертна}? Дуже добре, можливо, ми зможемо допомогти одне одному.\n\nДревній піщаний черв'як Оуро — істота легендарної сили. Подейкують, що його створив сам Старий Бог як наругу над життям.\n\nЙого шкіра неприродна... товста, майже неприступна, але при цьому така гнучка, що дозволяє йому швидко рухатися з грацією дрібної істоти.\n\nПринеси мені зразок його шкіри з іншими другорядними компонентами, і я зроблю для тебе поножі великої сили.", [3] = "Принесіть шкуру гігантського піщаного черв'яка, 2 ідоли боротьби, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просив, {ім'я}?", [5] = "Так... зі шкіри черв'яка можна зробити чудовий захисний шар. У поєднанні з найсильнішими частинами кіражів, яких ми знищили на нашому шляху сюди, ми створимо міцний обладунок. Нехай це допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!", ["en"] = "Avenger's Legguards", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Idol of Strife"] = "ідол боротьби", ["Idol of Strife (Provided)"] = "ідол боротьби (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Skin of the Great Sandworm"] = "шкіра гігантського піщаного черв'яка", ["Skin of the Great Sandworm (Provided)"] = "шкіра гігантського піщаного черв'яка (видано)" } },
    [863] = { [1] = "Втеча", [2] = "Гадаю, я розберусь по дорозі... Нічого складного! Тут просто кілька кнопок, і важіль чи два... Ну, ти {стать:готовий:готова} вирушати?", [3] = "Охороняйте Кривошип-са і викрадений гоблінський подрібнювач по дорозі до Гуркоклапана в Брашпиль.", [4] = "Чим можу бути корисним?", [5] = "Сподіваюсь, нам вдасться отримати щось цінне з цього зруйнованого прототипу подрібнювача... мій час спливає! Я негайно відправлю рятувальну команду на допомогу Кривошип-су.\n\nО, і дозволь віддячити тобі за клопоти.", ["en"] = "The Escape", ["tasks"] = { ["Escort Wizzlecrank out of the Venture Co. drill site"] = "Супроводжуйте Візлкранка з бурового майданчика ТзНБ \"Авантюра\"" } },
    [8630] = { [1] = "Напліччя месника", [2] = "Як у нас в народі кажуть, що прикрашені наплічні обладунки, які носять смертні, були створені для імітації драконячих крил.\n\nПринеси мені наручі вищих кіразьких лідерів, і я зроблю з них наплічники, страхітливіші за крила самого Нефаріана!", [3] = "Принесіть кіразькі наручі домінування, 2 ідоли життя, 5 кришталевих та 5 золотих скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} компоненти, які я просила?", [5] = "З матеріалів, які ти {стать:приніс:принесла}, і з луски наших полеглих ворогів, я зроблю для тебе ці напліччя, {стать:смертний:смертна}. Нехай вони нададуть тобі потрібний захист. Нехай їхній вигляд вселяє страх в наших ворогів.", ["en"] = "Avenger's Pauldrons", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Idol of Life"] = "ідол життя", ["Idol of Life (Provided)"] = "ідол життя (видано)", ["Qiraji Bindings of Dominance"] = "кіразькі наручі домінування", ["Qiraji Bindings of Dominance (Provided)"] = "кіразькі наручі домінування (видано)" } },
    [8631] = { [1] = "Поножі таїнства", [2] = "Прагнеш довести свою цінність моєму роду, {стать:смертний:смертна}? Дуже добре, можливо, ми зможемо допомогти одне одному.\n\nДревній піщаний черв'як Оуро — істота легендарної сили. Подейкують, що його створив сам Старий Бог як наругу над життям.\n\nЙого шкіра неприродна... товста, майже неприступна, але при цьому така гнучка, що дозволяє йому швидко рухатися з грацією дрібної істоти.\n\nПринеси мені зразок його шкіри з іншими другорядними компонентами, і я зроблю для тебе поножі великої сили.", [3] = "Принесіть неушкоджену шкуру Оуро, 2 ідоли мудреця, 5 срібних та 5 кістяних скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просив, {ім'я}?", [5] = "Так... зі шкіри черв'яка можна зробити чудовий захисний шар. У поєднанні з найсильнішими частинами кіражів, яких ми знищили на нашому шляху сюди, ми створимо міцний обладунок. Нехай це допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!", ["en"] = "Enigma Leggings", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Idol of the Sage"] = "ідол мудреця", ["Idol of the Sage (Provided)"] = "ідол мудреця (видано)", ["Ouro's Intact Hide"] = "неушкоджена шкура Оуро", ["Ouro's Intact Hide (Provided)"] = "неушкоджена шкура Оуро (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)" } },
    [8632] = { [1] = "Вінець таїнства", [2] = "Імператори-близнюки... Їхній невпинний шепіт потроху зводить мене з розуму. Вони знущаються з мене, знаючи, що я не можу ступити ні кроку в їхні володіння, щоб врятувати свого брата Ариґоса.\n\nУ своїх видіннях я бачу їхні жахливі голови, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці кіразькі символи сили на те, що більше відповідатиме нашим потребам.\n\nПринеси мені необхідні компоненти, {ім'я}, і я дам тобі головний убір незрівнянної сили.", [3] = "Принесіть вінець Век'нілаша, 2 ідоли ночі, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просила, {ім'я}?", [5] = "Тобі вдалося! Шепіт імператорів-близнюків припинився.\n\nПрийми це як нагороду. Один лише вид цієї речі вселятиме страх у серця кіражів... це нагадуватиме їм про їхніх полеглих лідерів і {стать:смертного:смертну}, {стать:який їх вбив:яка їх вбила}.", ["en"] = "Enigma Circlet", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Idol of Night"] = "ідол ночі", ["Idol of Night (Provided)"] = "ідол ночі (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Vek'nilash's Circlet"] = "вінець Век'нілаша", ["Vek'nilash's Circlet (Provided)"] = "вінець Век'нілаша (видано)" } },
    [86326] = { [1] = "Сила пустелі", [2] = "Глибокі та темні тунелі до стародавніх місць світу погано підходять для вашої подорожі.", [3] = "Поговоріть із Селестразою, щоб отримати свій резонансний кристал Кіраджі.", [5] = "Твоя міць не залишилася непоміченою, смертний. Нехай цей приборканий силітид пришвидшить твої подорожі до стародавньої імперії Кіраджі.", ["en"] = "Desert Power" },
    [8633] = { [1] = "Мантія таїнства", [2] = "Старий Бог, ім'я якого ми не згадуємо, повільно прокидається від свого сну під Ан'Кіражем. Жахлива доля може спіткати Азерот за кілька днів або років. Час не має значення для істот його сили.\n\nЗійдуться зірки — і його страшний гнів кинеться на все живе. Ти маєш знайти його раніше та покласти край його існуванню.\n\nЗроби це та принеси мені шматок його оболонки. Натомість я дам тобі обладунок, яким не володів ще ніхто зі смертних... обладунок, гідний вбивці бога!", [3] = "Принесіть оболонку Старого Бога, 2 ідоли сонця, 5 золотих та 5 глиняних скарабеїв Ветзері в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Роду Ноздорму.", [4] = "У своїй оселі в Ан'Кіражі, жихливий К'Тун спить і чекає, коли прийде його час.", [5] = "Я не очікувала, що ти повернешся, {ім'я}.\n\nТи {стать:здійснив:здійснила} подвиг величніший, ніж більшість безсмертних істот.\n\nВбивши К'Туна, ти не тільки {стать:врятував:врятувала} весь Азерот, але й {стать:перехилив:перехилила} терези космічних сил, про які ти навіть і не {стать:знав:знала}.\n\nПрийми цю мантію як символ слави та тягаря, що буде наслідком твоїх дій.\n\nНехай її сила допоможе тобі у випробуваннях, які чекають на тебе, вбивце богів!", ["en"] = "Enigma Robes", ["tasks"] = { ["9000 reputation with Brood of Nozdormu"] = "9000 репутації у Виводка Ноздорму", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Husk of the Old God"] = "оболонка Старого Бога", ["Husk of the Old God (Provided)"] = "оболонка Старого Бога (видано)", ["Idol of the Sun"] = "ідол сонця", ["Idol of the Sun (Provided)"] = "ідол сонця (видано)" } },
    [8634] = { [1] = "Чоботи таїнства", [2] = "Магія кіражів дуже сильна та древня. Наймогутніші кіражі володіють предметами такої могутності, що вони могли б зупинити навіть дракона.\n\nПринеси мені кіразькі наручі домінування та інші другорядні компоненти, і я створю для тебе могутні чоботи.\n\nВони знадобляться тобі в битві проти наших ворогів.", [3] = "Принесіть кіразькі наручі домінування, 2 ідоли сонця, 5 срібних та 5 кришталевих скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} предмети, які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Ти {стать:довів:довела}, що ти не {стать:звичайний смертний:звичайна смертна}.\n\nЯ впевнений, що вони допоможуть тобі трощити нікчемних кіражів.", ["en"] = "Enigma Boots", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Idol of the Sun"] = "ідол сонця", ["Idol of the Sun (Provided)"] = "ідол сонця (видано)", ["Qiraji Bindings of Dominance"] = "кіразькі наручі домінування", ["Qiraji Bindings of Dominance (Provided)"] = "кіразькі наручі домінування (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)" } },
    [8635] = { [1] = "Предок Камнекол", [5] = "Битви минулих століть — це насіння, з якого виростають легенди. Твій час — час героїв, {стать:юначе:юначко}. Нехай твоя легенда пустить коріння і процвітає.\n\nЯ бажаю тобі всього найкращого, {ім'я}, і пропоную тобі це...", ["en"] = "Splitrock the Elder" },
    [8636] = { [1] = "Предок Гуркокамінь", [5] = "Жива матерія приречена на смерть і повернення в землю, але дух живе вічно. Бажаю тобі всього найкращого, {ім'я}, і пропоную тобі це...", ["en"] = "Rumblerock the Elder" },
    [8637] = { [1] = "Чоботи смертоносця", [2] = "Магія кіражів дуже сильна та древня. Наймогутніші кіражі володіють предметами такої могутності, що вони могли б зупинити навіть дракона.\n\nПринеси мені кіразькі наручі командування та інші другорядні компоненти, і я створю для тебе могутні чоботи.\n\nВони знадобляться тобі в битві проти наших ворогів.", [3] = "Принесіть кіразькі наручі командування, 2 ідоли боротьби, 5 кришталевих та 5 кістяних скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} предмети, які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Ти {стать:довів:довела}, що ти не {стать:звичайний смертний:звичайна смертна}.\n\nЯ впевнений, що вони допоможуть тобі трощити нікчемних кіражів.", ["en"] = "Deathdealer's Boots", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Idol of Strife"] = "ідол боротьби", ["Idol of Strife (Provided)"] = "ідол боротьби (видано)", ["Qiraji Bindings of Command"] = "кіразькі наручі командування", ["Qiraji Bindings of Command (Provided)"] = "кіразькі наручі командування (видано)" } },
    [8638] = { [1] = "Жилет смертоносця", [2] = "Старий Бог, ім'я якого ми не згадуємо, повільно прокидається від свого сну під Ан'Кіражем. Жахлива доля може спіткати Азерот за кілька днів або років. Час не має значення для істот його сили.\n\nЗійдуться зірки — і його страшний гнів кинеться на все живе. Ти маєш знайти його раніше та покласти край його існуванню.\n\nЗроби це та принеси мені шматок його оболонки. Натомість я дам тобі обладунок, яким не володів ще ніхто зі смертних... обладунок, гідний вбивці бога!", [3] = "Принесіть панцир Старого Бога, 2 ідоли боротьби, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки Ветзері в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Роду Ноздорму.", [4] = "У своїй оселі в Ан'Кіражі, жихливий К'Тун спить і чекає, коли прийде його час.", [5] = "Я не очікувала, що ти повернешся, {ім'я}.\n\nТи {стать:здійснив:здійснила} подвиг величніший, ніж більшість безсмертних істот.\n\nВбивши К'Туна, ти не тільки {стать:врятував:врятувала} весь Азерот, але й {стать:перехилив:перехилила} терези космічних сил, про які ти навіть і не {стать:знав:знала}.\n\nПрийми цей жилет як символ слави та тягаря, що буде наслідком твоїх дій.\n\nНехай його сила допоможе тобі у випробуваннях, які чекають на тебе, вбивце богів!", ["en"] = "Deathdealer's Vest", ["tasks"] = { ["9000 reputation with Brood of Nozdormu"] = "9000 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Carapace of the Old God"] = "панцир Старого Бога", ["Carapace of the Old God (Provided)"] = "панцир Старого Бога (видано)", ["Idol of Strife"] = "ідол боротьби", ["Idol of Strife (Provided)"] = "ідол боротьби (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)" } },
    [8639] = { [1] = "Шолом смертоносця", [2] = "Імператори-близнюки... Їхній невпинний шепіт потроху зводить мене з розуму. Вони знущаються з мене, знаючи, що я не можу ступити ні кроку в їхні володіння, щоб врятувати свого брата Ариґоса.\n\nУ своїх видіннях я бачу їхні жахливі голови, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці кіразькі символи сили на те, що більше відповідатиме нашим потребам.\n\nПринеси мені необхідні компоненти, {ім'я}, і я дам тобі головний убір незрівнянної сили.", [3] = "Принесіть діадему Век'лора, 2 ідоли війни, 5 золотих та 5 глиняних скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просила, {ім'я}?", [5] = "Тобі вдалося! Шепіт імператорів-близнюків припинився.\n\nПрийми це як нагороду. Один лише вид цієї речі вселятиме страх у серця кіражів... це нагадуватиме їм про їхніх полеглих лідерів і {стать:смертного:смертну}, {стать:який їх вбив:яка їх вбила}.", ["en"] = "Deathdealer's Helm", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Idol of War"] = "ідол війни", ["Idol of War (Provided)"] = "ідол війни (видано)", ["Vek'lor's Diadem"] = "діадема Век'лора", ["Vek'lor's Diadem (Provided)"] = "діадема Век'лора (видано)" } },
    [8640] = { [1] = "Поножі смертоносця", [2] = "Прагнеш довести свою цінність моєму роду, {стать:смертний:смертна}? Дуже добре, можливо, ми зможемо допомогти одне одному.\n\nДревній піщаний черв'як Оуро — істота легендарної сили. Подейкують, що його створив сам Старий Бог як наругу над життям.\n\nЙого шкіра неприродна... товста, майже неприступна, але при цьому така гнучка, що дозволяє йому швидко рухатися з грацією дрібної істоти.\n\nПринеси мені зразок його шкіри з іншими другорядними компонентами, і я зроблю для тебе поножі великої сили.", [3] = "Принесіть неушкоджену шкуру Оуро, 2 ідоли ночі, 5 кам'яних та 5 кришталевих скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просив, {ім'я}?", [5] = "Так... зі шкіри черв'яка можна зробити чудовий захисний шар. У поєднанні з найсильнішими частинами кіражів, яких ми знищили на нашому шляху сюди, ми створимо міцний обладунок. Нехай це допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!", ["en"] = "Deathdealer's Leggings", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Idol of Night"] = "ідол ночі", ["Idol of Night (Provided)"] = "ідол ночі (видано)", ["Ouro's Intact Hide"] = "неушкоджена шкура Оуро", ["Ouro's Intact Hide (Provided)"] = "неушкоджена шкура Оуро (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8641] = { [1] = "Наплічники смертоносця", [2] = "Як у нас в народі кажуть, що прикрашені наплічні обладунки, які носять смертні, були створені для імітації драконячих крил.\n\nПринеси мені наручі вищих кіразьких лідерів, і я зроблю з них наплічники, страхітливіші за крила самого Нефаріана!", [3] = "Принесіть кіразькі наручі командування, 2 ідоли сонця, 5 срібних та 5 глиняних скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} компоненти, які я просила?", [5] = "З матеріалів, які ти {стать:приніс:принесла}, і з луски наших полеглих ворогів, я зроблю для тебе ці наплічники, {стать:смертний:смертна}. Нехай вони нададуть тобі потрібний захист. Нехай їхній вигляд вселяє страх в наших ворогів.", ["en"] = "Deathdealer's Spaulders", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Idol of the Sun"] = "ідол сонця", ["Idol of the Sun (Provided)"] = "ідол сонця (видано)", ["Qiraji Bindings of Command"] = "кіразькі наручі командування", ["Qiraji Bindings of Command (Provided)"] = "кіразькі наручі командування (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)" } },
    [8642] = { [1] = "Предок Срібножил", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Silvervein the Elder" },
    [8643] = { [1] = "Предок Височина", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Highpeak the Elder" },
    [8644] = { [1] = "Предок Камнефорт", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Stonefort the Elder" },
    [86443] = { [1] = "Втілення Кошмару", [2] = "Ми повинні проявити стриманість проти Еранікуса. Ми маємо викупити його, а не знищити.\n\nТіранда вже в дорозі, щоб допомогти нам у цьому завданні. Ми повинні витримати удари дракона та врятувати Найтхейвен від неминучого знищення.\n\nБудьте напоготові! Ви та ваші союзники — наша єдина надія.", [3] = "Захистіть Нічну Гавань від Еранікуса. Не дозвольте Хранителю Ремулосу загинути. Не вбийте Еранікуса. Захистіть себе. Чекайте на Тиранду.", [5] = "Він викуплений, {ім'я}. Тепер він повертається до Сну, щоб виправити те, що він сам зробив неправильно. Еранікус буде могутнім союзником Малфуріона та мого батька.\n\nЦя зброя для тебе, {ім'я}; дана мені самою Ізерою. Тобі варто використати її у своїх битвах проти кіраджі.", ["en"] = "The Nightmare Manifests", ["tasks"] = { ["The Redemption of Eranikus"] = "Викуплення Еранікуса" } },
    [86444] = { [1] = "Єдиний спосіб", [2] = "Я мав здогадатися. Мій заклятий ворог, Доктор Вівіл, повернувся до своїх старих трюків! А тепер, завдяки твоїй невдачі у Зимоключа, Доктор Вівіл знищив мою книгу! Як ти тепер збираєшся врятувати світ, герою?\n\nУ записці, яку я отримав, йшлося про те, що єдиний відомий примірник «Драконів для чайників: Том II» був розірваний на 8 частин і розвіяний на вітер! Якщо тобі якимось чином вдасться знайти ці відсутні розділи, скористайся цією магічною палітуркою, щоб зібрати їх назад, і поверни мені.", [3] = "Відновіть 8 втрачених розділів книги «Драконічна книга для чайників» та поєднайте їх з Чарівною палітуркою книги, щоб повернути завершену книгу «Драконічна книга для чайників: Том II» Нараїн Соутфансі в Танарісі.\n\nНаданий предмет:", [4] = "Я одягаю штани так само, як і ти — по одній нозі за раз. Тільки коли я одягаю штани, я роблю арканітові буї. Арканітові буї, крихітко!", [5] = "Фантастично! Не можу повірити, що ти пройшов через ці клопоти! Ти що, якась машина? Якби це було на моєму місці, я б, мабуть, просто дозволив світу вибухнути.\n\nЯ схиляю перед тобою свій тюрбан, сер. І жодна добра справа не повинна залишитися без винагороди.", ["en"] = "The Only Prescription" },
    [86449] = { [1] = "Скарб Позачасового", [5] = "Вітаю, чемпіоне. Я Джонатан, хранитель священного гонгу та вічний спостерігач Бронзового Польоту.\n\nСам Вічний уповноважив мене дарувати тобі предмет на твій вибір з його вічної скарбниці. Нехай це допоможе тобі в твоїх битвах проти К'Туна.", ["en"] = "Treasure of the Timeless One" },
    [8645] = { [1] = "Предок Обсидіан", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Obsidian the Elder" },
    [8646] = { [1] = "Предок Молотоклич", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Hammershout the Elder" },
    [8647] = { [1] = "Предок Гнівояр", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Bellowrage the Elder" },
    [8648] = { [1] = "Предок Чорносерд", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Darkcore the Elder" },
    [8649] = { [1] = "Предок Штормобров", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Stormbrow the Elder" },
    [865] = { [1] = "Роги рапторів", [2] = "Раптори Степів розумніші, ніж раптори з інших країв. І мені здається, що весь їх розум — в рогах! Отож, ці роги можна стерти в порошок і використати для приготування \"напоїв розумності\". Я б на них розбагатів!\n\nА ти мені можеш допомогти. Збери неушкоджені роги рапторів з сонцелуских серпопазурів. Вони бродять на півдні Степів і на півночі, біля кордону з Ясенедолом.", [3] = "Зберіть 5 неушкоджених рогів рапторів з сонцелуских серпопазурів і принесіть їх Мебокові Міцріксу в Брашпиль.", [4] = "Ти {стать:зібрав:зібрала} роги, {ім'я}? Вони зроблять мене багатим!", [5] = "Прекрасно, вони в тебе! Залишилось стерти їх в порошок, змішати з вином і...", ["en"] = "Raptor Horns", ["tasks"] = { ["Intact Raptor Horn"] = "неушкоджений ріг раптора", ["Intact Raptor Horn (Provided)"] = "неушкоджений ріг раптора (видано)" } },
    [8650] = { [1] = "Предок Сніговий Вінець", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Snowcrown the Elder" },
    [8651] = { [1] = "Предок Залізоплет", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Ironband the Elder" },
    [8652] = { [1] = "Предок Могилородний", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Graveborn the Elder" },
    [8653] = { [1] = "Предок Золотий Колодязь", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Goldwell the Elder" },
    [8654] = { [1] = "Предок Першокамінь", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Primestone the Elder" },
    [8655] = { [1] = "Наголінники месника", [2] = "Магія кіражів дуже сильна та древня. Наймогутніші кіражі володіють предметами такої могутності, що вони могли б зупинити навіть дракона.\n\nПринеси мені кіразькі наручі домінування та інші другорядні компоненти, і я створю для тебе могутні чоботи.\n\nВони знадобляться тобі в битві проти наших ворогів.", [3] = "Принесіть кіразькі наручі домінування, 2 ідоли мудреця, 5 бронзових та 5 глиняних скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} предмети, які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Ти {стать:довів:довела}, що ти не {стать:звичайний смертний:звичайна смертна}.\n\nЯ впевнений, що вони допоможуть тобі трощити нікчемних кіражів.", ["en"] = "Avenger's Greaves", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Idol of the Sage"] = "ідол мудреця", ["Idol of the Sage (Provided)"] = "ідол мудреця (видано)", ["Qiraji Bindings of Dominance"] = "кіразькі наручі домінування", ["Qiraji Bindings of Dominance (Provided)"] = "кіразькі наручі домінування (видано)" } },
    [8656] = { [1] = "Гауберк нападника", [2] = "Старий Бог, ім'я якого ми не згадуємо, повільно прокидається від свого сну під Ан'Кіражем. Жахлива доля може спіткати Азерот за кілька днів або років. Час не має значення для істот його сили.\n\nЗійдуться зірки — і його страшний гнів кинеться на все живе. Ти маєш знайти його раніше та покласти край його існуванню.\n\nЗроби це та принеси мені шматок його оболонки. Натомість я дам тобі обладунок, яким не володів ще ніхто зі смертних... обладунок, гідний вбивці бога!", [3] = "Принесіть панцир Старого Бога, 2 ідоли життя, 5 золотих та 5 глиняних скарабеїв Ветзері в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Роду Ноздорму.", [4] = "У своїй оселі в Ан'Кіражі, жихливий К'Тун спить і чекає, коли прийде його час.", [5] = "Я не очікувала, що ти повернешся, {ім'я}.\n\nТи {стать:здійснив:здійснила} подвиг величніший, ніж більшість безсмертних істот.\n\nВбивши К'Туна, ти не тільки {стать:врятував:врятувала} весь Азерот, але й {стать:перехилив:перехилила} терези космічних сил, про які ти навіть і не {стать:знав:знала}.\n\nПрийми цей гауберк як символ слави та тягаря, що буде наслідком твоїх дій.\n\nНехай його сила допоможе тобі у випробуваннях, які чекають на тебе, вбивце богів!", ["en"] = "Striker's Hauberk", ["tasks"] = { ["9000 reputation with Brood of Nozdormu"] = "9000 репутації у Виводка Ноздорму", ["Carapace of the Old God"] = "панцир Старого Бога", ["Carapace of the Old God (Provided)"] = "панцир Старого Бога (видано)", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Idol of Life"] = "ідол життя", ["Idol of Life (Provided)"] = "ідол життя (видано)" } },
    [8657] = { [1] = "Діадема нападника", [2] = "Імператори-близнюки... Їхній невпинний шепіт потроху зводить мене з розуму. Вони знущаються з мене, знаючи, що я не можу ступити ні кроку в їхні володіння, щоб врятувати свого брата Ариґоса.\n\nУ своїх видіннях я бачу їхні жахливі голови, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці кіразькі символи сили на те, що більше відповідатиме нашим потребам.\n\nПринеси мені необхідні компоненти, {ім'я}, і я зроблю для тебе головний убір незрівнянної сили.", [3] = "Принесіть діадему Век'лора, 2 ідоли боротьби, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просила, {ім'я}?", [5] = "Тобі вдалося! Шепіт імператорів-близнюків припинився.\n\nПрийми це як нагороду. Один лише вид цієї речі вселятиме страх у серця кіражів... це нагадуватиме їм про їхніх полеглих лідерів і {стать:смертного:смертну}, {стать:який їх вбив:яка їх вбила}.", ["en"] = "Striker's Diadem", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Idol of Strife"] = "ідол боротьби", ["Idol of Strife (Provided)"] = "ідол боротьби (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Vek'lor's Diadem"] = "діадема Век'лора", ["Vek'lor's Diadem (Provided)"] = "діадема Век'лора (видано)" } },
    [8658] = { [1] = "Поножі нападника", [2] = "Прагнеш довести свою цінність моєму роду, {стать:смертний:смертна}? Дуже добре, можливо, ми зможемо допомогти одне одному.\n\nДревній піщаний черв'як Оуро — істота легендарної сили. Подейкують, що його створив сам Старий Бог як наругу над життям.\n\nЙого шкіра неприродна... товста, майже неприступна, але при цьому така гнучка, що дозволяє йому швидко рухатися з грацією дрібної істоти.\n\nПринеси мені зразок його шкіри з іншими другорядними компонентами, і я зроблю для тебе поножі великої сили.", [3] = "Принесіть шкуру гігантського піщаного черв'яка, 2 ідоли сонця, 5 срібних та 5 кістяних скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просив, {ім'я}?", [5] = "Так... зі шкіри черв'яка можна зробити чудовий захисний шар. У поєднанні з найсильнішими частинами кіражів, яких ми знищили на нашому шляху сюди, ми створимо міцний обладунок. Нехай це допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!", ["en"] = "Striker's Leggings", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Idol of the Sun"] = "ідол сонця", ["Idol of the Sun (Provided)"] = "ідол сонця (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)", ["Skin of the Great Sandworm"] = "шкіра гігантського піщаного черв'яка", ["Skin of the Great Sandworm (Provided)"] = "шкіра гігантського піщаного черв'яка (видано)" } },
    [8659] = { [1] = "Напліччя нападника", [2] = "Як у нас в народі кажуть, що прикрашені наплічні обладунки, які носять смертні, були створені для імітації драконячих крил.\n\nПринеси мені наручі вищих кіразьких лідерів, і я зроблю з них напліччя, страхітливіші за крила самого Нефаріана!", [3] = "Принесіть кіразькі наручі командування, 2 ідоли війни, 5 кришталевих скарабеїв та 5 скарабеїв зі слонової кістки до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} компоненти, які я просила?", [5] = "З матеріалів, які ти {стать:приніс:принесла}, і з луски наших полеглих ворогів, я зроблю для тебе ці напліччя, {стать:смертний:смертна}. Нехай вони нададуть тобі потрібний захист. Нехай їхній вигляд вселяє страх в наших ворогів.", ["en"] = "Striker's Pauldrons", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Idol of War"] = "ідол війни", ["Idol of War (Provided)"] = "ідол війни (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Qiraji Bindings of Command"] = "кіразькі наручі командування", ["Qiraji Bindings of Command (Provided)"] = "кіразькі наручі командування (видано)" } },
    [866] = { [1] = "Зразки коренів", [2] = "Трави Степів не такі ж, як в інших землях. Їхні властивості здебільшого ті ж самі, але вода оазисів змінює їх, тож вони трохи відрізняються.\n\nЯ хочу дослідити ці відмінності... і чи можна ними скористатися!\n\nЯкщо ти володієш навичками травництва, збери зразки коренів з трав, які знайдеш у Степах. Принеси їх мені, щоб я міг порівняти їх з травами з інших регіонів.", [3] = "Принесіть 8 зразків коренів Мебоку Міцріксу в Брашпиль.", [4] = "Привіт, {ім'я}. Ти {стать:приніс:принесла} зразки коренів?", [5] = "Так, так, дуже гарні зразки! Я вирощу з цих коренів трави й зможу вивчити їх. Сподіваюся знайти в них нові властивості. Приховані, цінні властивості...\n\nІ не хвилюйся — якщо я їх знайду, ти будеш {стать:першим:першою}, хто про це дізнається. Тому що в такому разі мені знадобиться більше коренів!", ["en"] = "Root Samples", ["tasks"] = { ["Root Sample"] = "зразок кореня", ["Root Sample (Provided)"] = "зразок кореня (видано)" } },
    [8660] = { [1] = "Ножні обмотки згубоклича", [2] = "Магія кіражів дуже сильна та древня. Наймогутніші кіражі володіють предметами такої могутності, що вони могли б зупинити навіть дракона.\n\nПринеси мені кіразькі наручі домінування та інші другорядні компоненти, і я створю для тебе могутні чоботи.\n\nВони знадобляться тобі в битві проти наших ворогів.", [3] = "Принесіть кіразькі наручі домінування, 2 ідоли ночі, 5 глиняних скарабеїв та 5 скарабеїв зі слонової кістки Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} предмети, які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Ти {стать:довів:довела}, що ти не {стать:звичайний смертний:звичайна смертна}.\n\nЯ впевнений, що вони допоможуть тобі трощити нікчемних кіражів.", ["en"] = "Doomcaller's Footwraps", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Idol of Night"] = "ідол ночі", ["Idol of Night (Provided)"] = "ідол ночі (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Qiraji Bindings of Dominance"] = "кіразькі наручі домінування", ["Qiraji Bindings of Dominance (Provided)"] = "кіразькі наручі домінування (видано)" } },
    [8661] = { [1] = "Мантія згубоклича", [2] = "Старий Бог, ім'я якого ми не згадуємо, повільно прокидається від свого сну під Ан'Кіражем. Жахлива доля може спіткати Азерот за кілька днів або років. Час не має значення для істот його сили.\n\nЗійдуться зірки — і його страшний гнів кинеться на все живе. Ти маєш знайти його раніше та покласти край його існуванню.\n\nЗроби це та принеси мені шматок його оболонки. Натомість я дам тобі обладунок, яким не володів ще ніхто зі смертних... обладунок, гідний вбивці бога!", [3] = "Принесіть оболонку Старого Бога, 2 ідоли ночі, 5 кам'яних та 5 кришталевих скарабеїв Ветзері в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Роду Ноздорму.", [4] = "У своїй оселі в Ан'Кіражі, жихливий К'Тун спить і чекає, коли прийде його час.", [5] = "Я не очікувала, що ти повернешся, {ім'я}.\n\nТи {стать:здійснив:здійснила} подвиг величніший, ніж більшість безсмертних істот.\n\nВбивши К'Туна, ти не тільки {стать:врятував:врятувала} весь Азерот, але й {стать:перехилив:перехилила} терези космічних сил, про які ти навіть і не {стать:знав:знала}.\n\nПрийми цю мантію як символ слави та тягаря, що буде наслідком твоїх дій.\n\nНехай її сила допоможе тобі у випробуваннях, які чекають на тебе, вбивце богів!", ["en"] = "Doomcaller's Robes", ["tasks"] = { ["9000 reputation with Brood of Nozdormu"] = "9000 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Husk of the Old God"] = "оболонка Старого Бога", ["Husk of the Old God (Provided)"] = "оболонка Старого Бога (видано)", ["Idol of Night"] = "ідол ночі", ["Idol of Night (Provided)"] = "ідол ночі (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8662] = { [1] = "Вінець згубоклича", [2] = "Імператори-близнюки... Їхній невпинний шепіт потроху зводить мене з розуму. Вони знущаються з мене, знаючи, що я не можу ступити ні кроку в їхні володіння, щоб врятувати свого брата Ариґоса.\n\nУ своїх видіннях я бачу їхні жахливі голови, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці кіразькі символи сили на те, що більше відповідатиме нашим потребам.\n\nПринеси мені необхідні компоненти, {ім'я}, і я дам тобі головний убір незрівнянної сили.", [3] = "Принесіть вінець Век'нілаша, 2 ідоли смерті, 5 срібних та 5 кістяних скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просила, {ім'я}?", [5] = "Тобі вдалося! Шепіт імператорів-близнюків припинився.\n\nПрийми це як нагороду. Один лише вид цієї речі вселятиме страх у серця кіражів... це нагадуватиме їм про їхніх полеглих лідерів і {стать:смертного:смертну}, {стать:який їх вбив:яка їх вбила}.", ["en"] = "Doomcaller's Circlet", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Idol of Death"] = "ідол смерті", ["Idol of Death (Provided)"] = "ідол смерті (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)", ["Vek'nilash's Circlet"] = "вінець Век'нілаша", ["Vek'nilash's Circlet (Provided)"] = "вінець Век'нілаша (видано)" } },
    [8663] = { [1] = "Штани згубоклича", [2] = "Прагнеш довести свою цінність моєму роду, {стать:смертний:смертна}? Дуже добре, можливо, ми зможемо допомогти одне одному.\n\nДревній піщаний черв'як Оуро — істота легендарної сили. Подейкують, що його створив сам Старий Бог як наругу над життям.\n\nЙого шкіра неприродна... товста, майже неприступна, але при цьому така гнучка, що дозволяє йому швидко рухатися з грацією дрібної істоти.\n\nПринеси мені зразок його шкіри з іншими другорядними компонентами, і я зроблю для тебе поножі великої сили.", [3] = "Принесіть шкуру гігантського піщаного черв'яка, 2 ідоли відродження, 5 золотих та 5 глиняних скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просив, {ім'я}?", [5] = "Так... зі шкіри черв'яка можна зробити чудовий захисний шар. У поєднанні з найсильнішими частинами кіражів, яких ми знищили на нашому шляху сюди, ми створимо міцний обладунок. Нехай це допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!", ["en"] = "Doomcaller's Trousers", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Idol of Rebirth"] = "ідол відродження", ["Idol of Rebirth (Provided)"] = "ідол відродження (видано)", ["Skin of the Great Sandworm"] = "шкіра гігантського піщаного черв'яка", ["Skin of the Great Sandworm (Provided)"] = "шкіра гігантського піщаного черв'яка (видано)" } },
    [8664] = { [1] = "Наплічники згубоклича", [2] = "Як у нас в народі кажуть, що прикрашені наплічні обладунки, які носять смертні, були створені для імітації драконячих крил.\n\nПринеси мені наручі вищих кіразьких лідерів, і я зроблю з них наплічники, страхітливіші за крила самого Нефаріана!", [3] = "Принесіть кіразькі наручі домінування, 2 ідоли мудреця, 5 бронзових та 5 кістяних скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} компоненти, які я просила?", [5] = "З матеріалів, які ти {стать:приніс:принесла}, і з луски наших полеглих ворогів, я зроблю для тебе ці наплічники, {стать:смертний:смертна}. Нехай вони нададуть тобі потрібний захист. Нехай їхній вигляд вселяє страх в наших ворогів.", ["en"] = "Doomcaller's Mantle", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Idol of the Sage"] = "ідол мудреця", ["Idol of the Sage (Provided)"] = "ідол мудреця (видано)", ["Qiraji Bindings of Dominance"] = "кіразькі наручі домінування", ["Qiraji Bindings of Dominance (Provided)"] = "кіразькі наручі домінування (видано)" } },
    [8665] = { [1] = "Чоботи буття", [2] = "Магія кіражів дуже сильна та древня. Наймогутніші кіражі володіють предметами такої могутності, що вони могли б зупинити навіть дракона.\n\nПринеси мені кіразькі наручі домінування та інші другорядні компоненти, і я створю для тебе могутні чоботи.\n\nВони знадобляться тобі в битві проти наших ворогів.", [3] = "Принесіть кіразькі наручі домінування, 2 ідоли відродження, 5 кам'яних та 5 срібних скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} предмети, які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я}. Ти {стать:довів:довела}, що ти не {стать:звичайний смертний:звичайна смертна}.\n\nЯ впевнений, що вони допоможуть тобі трощити нікчемних кіражів.", ["en"] = "Genesis Boots", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Idol of Rebirth"] = "ідол відродження", ["Idol of Rebirth (Provided)"] = "ідол відродження (видано)", ["Qiraji Bindings of Dominance"] = "кіразькі наручі домінування", ["Qiraji Bindings of Dominance (Provided)"] = "кіразькі наручі домінування (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8666] = { [1] = "Жилет буття", [2] = "Старий Бог, ім'я якого ми не згадуємо, повільно прокидається від свого сну під Ан'Кіражем. Жахлива доля може спіткати Азерот за кілька днів або років. Час не має значення для істот його сили.\n\nЗійдуться зірки — і його страшний гнів кинеться на все живе. Ти маєш знайти його раніше та покласти край його існуванню.\n\nЗроби це та принеси мені шматок його оболонки. Натомість я дам тобі обладунок, яким не володів ще ніхто зі смертних... обладунок, гідний вбивці бога!", [3] = "Принесіть оболонку Старого Бога, 2 ідоли відродження, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки Ветзері в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Роду Ноздорму.", [4] = "У своїй оселі в Ан'Кіражі, жихливий К'Тун спить і чекає, коли прийде його час.", [5] = "Я не очікувала, що ти повернешся, {ім'я}.\n\nТи {стать:здійснив:здійснила} подвиг величніший, ніж більшість безсмертних істот.\n\nВбивши К'Туна, ти не тільки {стать:врятував:врятувала} весь Азерот, але й {стать:перехилив:перехилила} терези космічних сил, про які ти навіть і не {стать:знав:знала}.\n\nПрийми цей жилет як символ слави та тягаря, що буде наслідком твоїх дій.\n\nНехай його сила допоможе тобі у випробуваннях, які чекають на тебе, вбивце богів!", ["en"] = "Genesis Vest", ["tasks"] = { ["9000 reputation with Brood of Nozdormu"] = "9000 репутації у Виводка Ноздорму", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Husk of the Old God"] = "оболонка Старого Бога", ["Husk of the Old God (Provided)"] = "оболонка Старого Бога (видано)", ["Idol of Rebirth"] = "ідол відродження", ["Idol of Rebirth (Provided)"] = "ідол відродження (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)" } },
    [8667] = { [1] = "Шолом буття", [2] = "Імператори-близнюки... Їхній невпинний шепіт потроху зводить мене з розуму. Вони знущаються з мене, знаючи, що я не можу ступити ні кроку в їхні володіння, щоб врятувати свого брата Ариґоса.\n\nУ своїх видіннях я бачу їхні жахливі голови, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці кіразькі символи сили на те, що більше відповідатиме нашим потребам.\n\nПринеси мені необхідні компоненти, {ім'я}, і я дам тобі головний убір незрівнянної сили.", [3] = "Принесіть діадему Век'лора, 2 ідоли життя, 5 золотих та 5 глиняних скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просила, {ім'я}?", [5] = "Тобі вдалося! Шепіт імператорів-близнюків припинився.\n\nПрийми це як нагороду. Один лише вид цієї речі вселятиме страх у серця кіражів... це нагадуватиме їм про їхніх полеглих лідерів і {стать:смертного:смертну}, {стать:який їх вбив:яка їх вбила}.", ["en"] = "Genesis Helm", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Idol of Life"] = "ідол життя", ["Idol of Life (Provided)"] = "ідол життя (видано)", ["Vek'lor's Diadem"] = "діадема Век'лора", ["Vek'lor's Diadem (Provided)"] = "діадема Век'лора (видано)" } },
    [86671] = { [1] = "Кіразькі імператорські регалії", [2] = "Арігос теоретизує, що стихія, що народжується внаслідок конфліктів між Стародавніми Богами та їхніми поплічниками, також надзвичайно смертельна для них за певних умов. Я говорю про Елементій, смертний.\n\nЗнайди та принеси мені Імперські Кіраджі Регалії та токсичний елемент, і я наповню їх зброєю великої сили.", [3] = "Мерітра Сну в Храмі Ан'Кіраджа створить для вас Наповнену Елементієм Зброю, якщо ви принесете їй Імперські Кіражські Регалії та 3 Елементієві Руди.", [4] = "Ти їх знищиш і звільниш нас від цих кайданів.", [5] = "Використовуй предмет добре, {ім'я}. Нехай вони відчують біль, який вони так палко хочуть завдати іншим.", ["en"] = "Imperial Qiraji Regalia" },
    [86672] = { [1] = "Кіразька імператорська зброя", [2] = "Ми не сиділи склавши руки протягом тисячоліття, {ім'я}.\n\nМи спостерігали, як ці звірі бенкетують самі по собі, коли вичерпують свою корисність. Ми слухали, як вони замишляли та планували знищити наш світ. І ми дізналися про їхню власну внутрішню зраду.\n\nСлабкості існують, і ми знаємо, як використати ці слабкості на свою користь.\n\nЗнайдіть і принесіть мені їхнє церемоніальне озброєння: у поєднанні з елементом, створеним з мінливості їхнього власного Бога, вони стануть силою розплати.", [3] = "Арігос у Храмі Ан'Кіраджа створить для вас Зброю, Наповнену Елементієм, якщо ви принесете йому Імперську Зброю Кіражів та 3 Елементієві Руди.", [4] = "Шукай те, чого я просив. Ти станеш більшим, ніж сума твоїх частин, чемпіоне.", [5] = "Наповнена елементієм, ця зброя з неймовірною легкістю розсіче кіраджі та їхнього Бога.", ["en"] = "Imperial Qiraji Armaments" },
    [86673] = { [1] = "Падіння Оссіріана", [2] = "Жахливу загрозу покладено нанівець. Жорстокого Оссіріана переможено.\n\nМешканці Калімдору з полегшенням дізнаються про цю перемогу. Візьміть голову Оссіріана та подаруйте її командувачу Мар'аліту з форту Кенаріон.", [3] = "Доставте голову Оссіріана Непошкодженого командиру Мар'аліту в фортецю Кенаріона в Силітусі.", [4] = "А, {ім'я}, ти повернувся! І цілим, додам я. Які новини ти приніс з Ан'Кіраджа?", [5] = "Висловлюю вам свою найвищу похвалу та ваш вибір предмета сили, {ім'я}. Ви зробили велику послугу народу Калімдора.", ["en"] = "The Fall of Ossirian" },
    [86674] = { [1] = "Ідеальна отрута", [2] = "Ми з братом керуємо операціями з отруєння з маєтку Рейвенгольдт.\n\nЛорд Рейвенгольдт доручив мені знайти нову та надзвичайно ефективну отруйну суміш, яку можна виготовити з отруйних мішечків мешканців Зул'Ґуруба та Руїн Ан'Кіраджа.\n\nУ цих вируйнованих руїнах живуть дві особливо отруйні істоти, які володіють тим, що ми можемо шукати, {клас}. Принесіть мені отруйний мішечок від істот Куріннакса та Веноксиса, і ми будемо вічно вдячні.", [3] = "Дірк Громовуд з Кенаріонської фортеці хоче, щоб ви принесли йому Отруйний мішок Веноксіса та Отруйний мішок Куріннакса.", [4] = "Це не робота на розбиття та захоплення, {ім'я}. Тобі потрібно буде привести друзів.", [5] = "Рейвенгольдт, дякую тобі, герою! Обери свій!", ["en"] = "The Perfect Poison" },
    [86675] = { [1] = "Спорядження добровольців", [2] = "Значки, які ви отримуєте за виконання бойових, логістичних та тактичних завдань для форту Кенаріон, — це більше, ніж просто для показухи, {ім'я}.\n\nБуло б мудро зберегти їх. Коли ви доведете свою відданість нашій організації, я можу запропонувати вам частину спорядження, яке ми резервуємо для наших найближчих союзників, в обмін на ці значки.", [3] = "Принесіть 5 бойових значків Кенаріона, 3 значки логістики Кенаріона та 7 тактичних значків Кенаріона Варгусу в фортеці Кенаріона в Силітусі. Ви також повинні отримати репутацію дружби у Колі Кенаріона, щоб мати змогу виконати це завдання.", [4] = "У наших інтересах тримати наших найвірніших союзників у належному стані, {ім'я}.", [5] = "Чудова робота, {ім'я}. Будь ласка, прийміть це від імені Кола Кенаріона. Ви точно це заслужили, друже!", ["en"] = "Volunteer's Battlegear" },
    [86676] = { [1] = "Спорядження ветеранів", [2] = "Значки, які ви отримуєте за виконання бойових, логістичних та тактичних завдань для форту Кенаріон, — це більше, ніж просто для показухи, {ім'я}.\n\nБуло б мудро зберегти їх. Коли ви доведете свою відданість нашій організації, я можу запропонувати вам частину спорядження, яке ми резервуємо для наших найближчих союзників, в обмін на ці значки.", [3] = "Принесіть 7 бойових значків Кенаріона, 4 значки логістики Кенаріона та 4 тактичні значки Кенаріона Варгусу в фортеці Кенаріона в Силітусі. Ви також повинні досягти Пошанованої репутації в Колі Кенаріона, щоб мати змогу виконати це завдання.", [4] = "У наших інтересах тримати наших найвірніших союзників у належному стані, {ім'я}.", [5] = "Чудова робота, {ім'я}. Будь ласка, прийміть це від імені Кола Кенаріона. Ви точно це заслужили, друже!", ["en"] = "Veteran's Battlegear" },
    [86677] = { [1] = "Спорядження незламних", [2] = "Значки, які ви отримуєте за виконання бойових, логістичних та тактичних завдань для Вітрошукача Гордого, — це більше, ніж просто для показухи, {ім'я}.\n\nБуло б мудро зберегти їх. Коли ви доведете свою відданість нашій організації, я можу запропонувати вам частину спорядження, яке ми резервуємо для наших найближчих союзників, в обмін на ці значки.", [3] = "Принесіть 15 бойових значків Кенаріона, 20 значків логістики Кенаріона, 17 тактичних значків Кенаріона та 1 знак Ремулоса Варгусу в фортеці Кенаріона в Силітусі. Ви також повинні досягти репутації Шанування у Колі Кенаріона, щоб мати змогу виконати це завдання.", [4] = "У наших інтересах тримати наших найвірніших союзників у належному стані, {ім'я}.", [5] = "Чудова робота, {ім'я}. Будь ласка, прийміть це від імені Кола Кенаріона. Ви точно це заслужили, друже!", ["en"] = "Stalwart's Battlegear" },
    [86678] = { [1] = "Спорядження чемпіона", [2] = "Значки, які ви отримуєте за виконання бойових, логістичних та тактичних завдань для форту Кенаріон, — це більше, ніж просто для показухи, {ім'я}.\n\nБуло б мудро зберегти їх. Коли ви доведете свою відданість нашій організації, я можу запропонувати вам частину спорядження, яке ми резервуємо для наших найближчих союзників, в обмін на ці значки.", [3] = "Принесіть 15 бойових значків Кенаріона, 20 значків логістики Кенаріона, 20 тактичних значків Кенаріона та 1 знак Кенарія Варгусу до фортеці Кенаріона в Силітусі. Ви також повинні досягти Піднесеної репутації у Колі Кенаріона, щоб мати змогу виконати це завдання.", [4] = "У наших інтересах тримати наших найвірніших союзників у належному стані, {ім'я}.", [5] = "Чудова робота, {ім'я}. Будь ласка, прийміть це від імені Кола Кенаріона. Ви точно це заслужили, друже!", ["en"] = "Champion's Battlegear" },
    [86679] = { [1] = "Оповитий кошмаром", [2] = "З цього предмета просочується псування.\n\nМожливо, існує зв'язок між цим предметом і драконами, що виходять зі Сну. Ви повинні знайти когось, хто може розшифрувати значення цього предмета. Можливо, друїди Місячної Галявини або Твердині Кенаріона могли б вам допомогти.", [3] = "Знайдіть когось, хто зможе розшифрувати значення Об'єкта, Поглинутого Кошмаром.\n\nМожливо, вам допоможе друїд великої сили.", [4] = "Так, {раса}?", [5] = "Я мушу позбутися скверни з цього предмета. Це може пролити світло на мої нещодавні невдачі в дослідженні Сну. Дай мені це.", ["en"] = "Shrouded in Nightmare", ["tasks"] = { ["Item #235049"] = "Товар №235049" } },
    [8668] = { [1] = "Штани буття", [2] = "Прагнеш довести свою цінність моєму роду, {стать:смертний:смертна}? Дуже добре, можливо, ми зможемо допомогти одне одному.\n\nДревній піщаний черв'як Оуро — істота легендарної сили. Подейкують, що його створив сам Старий Бог як наругу над життям.\n\nЙого шкіра неприродна... товста, майже неприступна, але при цьому така гнучка, що дозволяє йому швидко рухатися з грацією дрібної істоти.\n\nПринеси мені зразок його шкіри з іншими другорядними компонентами, і я зроблю для тебе штани великої сили.", [3] = "Принесіть шкуру гігантського піщаного черв'яка, 2 ідоли війни, 5 кам'яних та 5 кришталевих скарабеїв Кандростразу в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні дружню репутацію у Роду Ноздорму.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просив, {ім'я}?", [5] = "Так... зі шкіри черв'яка можна зробити чудовий захисний шар. У поєднанні з найсильнішими частинами кіражів, яких ми знищили на нашому шляху сюди, ми створимо міцний обладунок. Нехай це допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!", ["en"] = "Genesis Trousers", ["tasks"] = { ["3000 reputation with Brood of Nozdormu"] = "3000 репутації у Виводка Ноздорму", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Idol of War"] = "ідол війни", ["Idol of War (Provided)"] = "ідол війни (видано)", ["Skin of the Great Sandworm"] = "шкіра гігантського піщаного черв'яка", ["Skin of the Great Sandworm (Provided)"] = "шкіра гігантського піщаного черв'яка (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [86680] = { [1] = "Пробудження легенд", [2] = "Води озера Елуне'ара повинні розчинити кошмари, що поглинають цей об'єкт. Дайте мені хвилинку, щоб провести очищення, {ім'я}.", [3] = "Зачекайте, поки Хранитель Ремулос на Місячній Галявині очистить Об'єкт, Поглинутий Кошмаром.", [4] = "Ви побачили те, що повинні були побачити.", [5] = "Візьми його перстень, {ім'я}. Він виконав своє призначення для Малфуріона. Тепер він служитиме новому призначенню для тебе...", ["en"] = "Waking Legends" },
    [8669] = { [1] = "Наплічники буття", [2] = "Як у нас в народі кажуть, що прикрашені наплічні обладунки, які носять смертні, були створені для імітації драконячих крил.\n\nПринеси мені наручі вищих кіразьких лідерів, і я зроблю з них наплічники, страхітливіші за крила самого Нефаріана!", [3] = "Принесіть кіразькі наручі домінування, 2 ідоли боротьби, 5 золотих та 5 кістяних скарабеїв до Андорґос в Ан'Кіраж. Для виконання цього завдання вам потрібно мати принаймні нейтральну репутацію у Роду Ноздорму.", [4] = "Ти {стать:зібрав:зібрала} компоненти, які я просила?", [5] = "З матеріалів, які ти {стать:приніс:принесла}, і з луски наших полеглих ворогів, я зроблю для тебе ці наплічники, {стать:смертний:смертна}. Нехай вони нададуть тобі потрібний захист. Нехай їхній вигляд вселяє страх в наших ворогів.", ["en"] = "Genesis Shoulderpads", ["tasks"] = { ["0 reputation with Brood of Nozdormu"] = "0 репутації у Виводка Ноздорму", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Idol of Strife"] = "ідол боротьби", ["Idol of Strife (Provided)"] = "ідол боротьби (видано)", ["Qiraji Bindings of Dominance"] = "кіразькі наручі домінування", ["Qiraji Bindings of Dominance (Provided)"] = "кіразькі наручі домінування (видано)" } },
    [8670] = { [1] = "Предок Рунний Тотем", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Runetotem the Elder" },
    [8671] = { [1] = "Предок Тотем Люті", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Ragetotem the Elder" },
    [8672] = { [1] = "Предок Кам'яний Шпиль", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Stonespire the Elder" },
    [8673] = { [1] = "Предок Криваве Копито", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Bloodhoof the Elder" },
    [8674] = { [1] = "Предок Зимове Копито", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Winterhoof the Elder" },
    [8675] = { [1] = "Предок Небесна Мисливиця", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Skychaser the Elder" },
    [8676] = { [1] = "Предок Дика Грива", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Wildmane the Elder" },
    [86760] = { [1] = "Колода Темного місяця: звірі", [2] = "Тепер, коли ви зібрали всі карти Звірів разом у колоду, таємничим чином з'являється дев'ята карта з такою ж рубрикою, як і перші вісім. На цій карті написано: «Поверніть ці карти на Ярмарок Молодика та отримайте винагороду». Ви чули, що цей ярмарок по черзі зупиняється то в Мулгорі, то в Золотоширі кожні кілька місяців, тому вам доведеться почекати, поки вони тут з'являться наступного разу.", [3] = "Поверніть колоду Звіра на Ярмарок Молодика, коли вона прийде до міста.", [4] = "Бачу, що тобі вдалося зібрати колоду звірів! Вітаю!", [5] = "Отже, ви зібрали колоду Звірів. Ваш жест повернення її нам створить зв'язок між вами та Темномісяцем, який нескоро буде забутий. Дозвольте мені подарувати вам одну з найбільших карт Темномісяця як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Beast Deck", ["tasks"] = { ["Beasts Deck"] = "колода звірів" } },
    [86761] = { [1] = "Колода Темного місяця: воєводи", [2] = "Тепер, коли ви зібрали всі карти Воєначальника в колоду, таємничим чином з'являється дев'ята карта з такою ж підкладкою, як і перші вісім. На цій карті написано: «Поверніть ці карти на Ярмарок Молодика та отримайте винагороду». Ви чули, що цей ярмарок по черзі зупиняється в Мулгорі та Золотоширі кожні кілька місяців, тому вам доведеться почекати, поки вони тут з'являться наступного разу.", [3] = "Поверніть колоду Воєначальників на Ярмарок Молодика, коли вона прийде до міста.", [4] = "Бачу, що тобі вдалося зібрати колоду воєначальників! Вітаю!", [5] = "Отже, ви зібрали колоду Воєначальників. Ваш жест повернення її нам створить зв'язок між вами та Темнолунням, який нескоро буде забутий. Дозвольте мені подарувати вам одну з найбільших карт Темнолуння як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Warlords Deck", ["tasks"] = { ["Warlords Deck"] = "колода воєвод" } },
    [86763] = { [1] = "Колода Темного місяця: портали", [2] = "Тепер, коли ви зібрали всі карти Порталу в колоду, таємничим чином з'являється дев'ята карта з такою ж підкладкою, як і перші вісім. На цій карті написано: «Поверніть ці карти на Ярмарок Молодика та отримайте винагороду». Ви чули, що цей ярмарок по черзі зупиняється то в Мулгорі, то в Золотоширі кожні кілька місяців, тому вам доведеться почекати, поки вони тут з'являться наступного разу.", [3] = "Поверніть колоду Порталів на Ярмарок Молодика, коли вона прийде до міста.", [4] = "Бачу, що тобі вдалося зібрати колоду порталів! Вітаю!", [5] = "Отже, ви зібрали колоду Порталів. Ваш жест повернення її нам створить зв'язок між вами та Темнолунням, який нескоро буде забутий. Дозвольте мені подарувати вам одну з найбільших карт Темнолуння як невеликий знак нашої вдячності.", ["en"] = "Darkmoon Portals Deck" },
    [8677] = { [1] = "Предок Чорний Ріг", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Darkhorn the Elder" },
    [8678] = { [1] = "Предок Гордий Ріг", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Proudhorn the Elder" },
    [8679] = { [1] = "Предок Зловісний Тотем", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Grimtotem the Elder" },
    [8680] = { [1] = "Предок Тотем Вітру", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Windtotem the Elder" },
    [8681] = { [1] = "Предок Громовий Ріг", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Thunderhorn the Elder" },
    [8682] = { [1] = "Предок Небесний Провидець", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Skyseer the Elder" },
    [8683] = { [1] = "Предок Світанкова Мандрівниця", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Dawnstrider the Elder" },
    [8684] = { [1] = "Предок Провидець Снів", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Dreamseer the Elder" },
    [8685] = { [1] = "Предок Серпанкова Мандрівниця", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "Mistwalker the Elder" },
    [8686] = { [1] = "Предок Висока Гора", [5] = "Твій дух горить життям, {стать:юний:юна} {клас:к}. Я приймаю твою шану і натомість пропоную це...", ["en"] = "High Mountain the Elder" },
    [8687] = { [1] = "Ціль: прохідники Вул'Зори", [2] = "Ми викликали підкріплення для штурму Вул'Зори. Твоє завдання — вбити якомога більше прохідників Вул'Зори. Коли виконаєш завдання, прозвітуй про це командиру Мар'аліту.", [3] = "Вбийте 30 прохідників Вул'Зори та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання VII.", [4] = "Ти маєш, про що мені доповісти, {клас:к}?", [5] = "Чудова робота, {ім'я}. Без своїх прохідників силітидам буде важко усунути шкоду, завдану їхньому вулику. Гадаю, ти бажаєш отримати нове завдання.", ["en"] = "Target: Hive'Zora Tunnelers", ["tasks"] = { ["Combat Task Briefing VII"] = "план бойового завдання VII", ["Combat Task Briefing VII (Provided)"] = "план бойового завдання VII (видано)", ["Hive'Zora Tunneler"] = "прохідник Вул'Зори", ["Hive'Zora Tunneler slain"] = "прохідник Вул'Зори: убито" } },
    [8688] = { [1] = "Предок Вітробіг", [5] = "Небеса у своїх незліченних зірках зберігають відповіді на земні таємниці, {ім'я}. Тож чи можуть мудрі та щасливі поглянути туди й знайти істину?", ["en"] = "Windrun the Elder" },
    [8689] = { [1] = "Накидка нескінченної мудрості", [2] = "Я радий чути, що ти допомагаєш нам у нападі на Ан'Кіраж, {ім'я}. На знак подяки я можу зробити для тебе річ, що захищатиме тебе в битві проти наших ворогів, {клас}.\n\nМені знадобиться кіразька пелерина, яку я підшию під твій розмір, звичайно. Також мені знадобляться ідоли та скарабеї, з яких я зроблю застібку.\n\nОбіцяю, ця річ тебе не розчарує.", [3] = "Принесіть кіразьку бойову пелерину, 2 яшмових ідоли, 5 золотих та 5 глиняних скарабеїв Кейлу Прудкопазуру в Силітус. Для виконання цього завдання вам потрібно мати принаймні шановану репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} матеріали для накидки, {ім'я}?", [5] = "О так... ця пелерина бездоганна.\n\nВізьми цю накидку, {ім'я}. Нехай вона захистить тебе від нечистої магії кіражів.", ["en"] = "Shroud of Infinite Wisdom", ["tasks"] = { ["21000 reputation with Cenarion Circle"] = "21000 репутації у Колі Кенаріона", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Jasper Idol"] = "яшмовий ідол", ["Jasper Idol (Provided)"] = "яшмовий ідол (видано)", ["Qiraji Martial Drape"] = "кіразька бойова пелерина", ["Qiraji Martial Drape (Provided)"] = "кіразька бойова пелерина (видано)" } },
    [8690] = { [1] = "Плащ прийдешньої бурі", [2] = "Я радий чути, що ти допомагаєш нам у нападі на Ан'Кіраж, {ім'я}. На знак подяки я можу зробити для тебе річ, що захищатиме тебе в битві проти наших ворогів, {клас}.\n\nМені знадобиться кіразька пелерина, яку я підшию під твій розмір, звичайно. Також мені знадобляться ідоли та скарабеї, з яких я зроблю застібку.\n\nОбіцяю, ця річ тебе не розчарує.", [3] = "Принесіть кіразьку королівську пелерину, 2 обсидіанових ідоли, 5 глиняних та 5 золотих скарабеїв Кейлу Прудкопазуру в Силітус. Для виконання цього завдання вам потрібно мати принаймні шановану репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} матеріали для плаща, {ім'я}?", [5] = "О так... ця пелерина бездоганна.\n\nВізьми цей плащ, {ім'я}. Нехай він захистить тебе від нечистої магії кіражів.", ["en"] = "Cloak of the Gathering Storm", ["tasks"] = { ["21000 reputation with Cenarion Circle"] = "21000 репутації у Колі Кенаріона", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Obsidian Idol"] = "обсидіановий ідол", ["Obsidian Idol (Provided)"] = "обсидіановий ідол (видано)", ["Qiraji Regal Drape"] = "кіразька королівська пелерина", ["Qiraji Regal Drape (Provided)"] = "кіразька королівська пелерина (видано)" } },
    [8691] = { [1] = "Пелерина похованих таємниць", [2] = "Я радий чути, що ти допомагаєш нам у нападі на Ан'Кіраж, {ім'я}. На знак подяки я можу зробити для тебе річ, що захищатиме тебе в битві проти наших ворогів, {клас}.\n\nМені знадобиться кіразька пелерина, яку я підшию під твій розмір, звичайно. Також мені знадобляться ідоли та скарабеї, з яких я зроблю застібку.\n\nОбіцяю, ця річ тебе не розчарує.", [3] = "Принесіть кіразьку бойову пелерину, 2 алебастрових ідоли, 5 кам'яних та 5 кришталевих скарабеїв Кейлу Прудкопазуру в Силітус. Для виконання цього завдання вам потрібно мати принаймні шановану репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} матеріали для пелерини, {ім'я}?", [5] = "О так... вона бездоганна.\n\nВізьми цю пелерину, {ім'я}. Нехай вона захистить тебе від нечистої магії кіражів.", ["en"] = "Drape of Vaulted Secrets", ["tasks"] = { ["21000 reputation with Cenarion Circle"] = "21000 репутації у Колі Кенаріона", ["Alabaster Idol"] = "алебастровий ідол", ["Alabaster Idol (Provided)"] = "алебастровий ідол (видано)", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Qiraji Martial Drape"] = "кіразька бойова пелерина", ["Qiraji Martial Drape (Provided)"] = "кіразька бойова пелерина (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8692] = { [1] = "Плащ нескінченного життя", [2] = "Я радий чути, що ти допомагаєш нам у нападі на Ан'Кіраж, {ім'я}. На знак подяки я можу зробити для тебе річ, що захищатиме тебе в битві проти наших ворогів, {клас}.\n\nМені знадобиться кіразька пелерина, яку я підшию під твій розмір, звичайно. Також мені знадобляться ідоли та скарабеї, з яких я зроблю застібку.\n\nОбіцяю, ця річ тебе не розчарує.", [3] = "Принесіть кіразьку королівську пелерину, 2 багряних ідоли, 5 срібних та 5 кістяних скарабеїв Кейлу Прудкопазуру в Силітус. Для виконання цього завдання вам потрібно мати принаймні шановану репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} матеріали для плаща, {ім'я}?", [5] = "О так... ця пелерина бездоганна.\n\nВізьми цей плащ, {ім'я}. Нехай він захистить тебе від нечистої магії кіражів.", ["en"] = "Cloak of Unending Life", ["tasks"] = { ["21000 reputation with Cenarion Circle"] = "21000 репутації у Колі Кенаріона", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Qiraji Regal Drape"] = "кіразька королівська пелерина", ["Qiraji Regal Drape (Provided)"] = "кіразька королівська пелерина (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)", ["Vermillion Idol"] = "багряний ідол", ["Vermillion Idol (Provided)"] = "багряний ідол (видано)" } },
    [8693] = { [1] = "Плащ прихованих тіней", [2] = "Я радий чути, що ти допомагаєш нам у нападі на Ан'Кіраж, {ім'я}. На знак подяки я можу зробити для тебе річ, що захищатиме тебе в битві проти наших ворогів, {клас}.\n\nМені знадобиться кіразька пелерина, яку я підшию під твій розмір, звичайно. Також мені знадобляться ідоли та скарабеї, з яких я зроблю застібку.\n\nОбіцяю, ця річ тебе не розчарує.", [3] = "Принесіть кіразьку бойову пелерину, 2 лазурових ідоли, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки Кейлу Прудкопазуру в Силітус. Для виконання цього завдання вам потрібно мати принаймні шановану репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} матеріали для плаща, {ім'я}?", [5] = "О так... ця пелерина бездоганна.\n\nВізьми цей плащ, {ім'я}. Нехай він захистить тебе від нечистої магії кіражів.", ["en"] = "Cloak of Veiled Shadows", ["tasks"] = { ["21000 reputation with Cenarion Circle"] = "21000 репутації у Колі Кенаріона", ["Azure Idol"] = "лазуровий ідол", ["Azure Idol (Provided)"] = "лазуровий ідол (видано)", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Qiraji Martial Drape"] = "кіразька бойова пелерина", ["Qiraji Martial Drape (Provided)"] = "кіразька бойова пелерина (видано)" } },
    [8694] = { [1] = "Накидка невимовних імен", [2] = "Я радий чути, що ти допомагаєш нам у нападі на Ан'Кіраж, {ім'я}. На знак подяки я можу зробити для тебе річ, що захищатиме тебе в битві проти наших ворогів, {клас}.\n\nМені знадобиться кіразька пелерина, яку я підшию під твій розмір, звичайно. Також мені знадобляться ідоли та скарабеї, з яких я зроблю застібку.\n\nОбіцяю, ця річ тебе не розчарує.", [3] = "Принесіть кіразьку королівську пелерину, 2 бурштинових ідоли, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки Кейлу Прудкопазуру в Силітус. Для виконання цього завдання вам потрібно мати принаймні шановану репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} матеріали для накидки, {ім'я}?", [5] = "О так... ця пелерина бездоганна.\n\nВізьми цю накидку, {ім'я}. Нехай вона захистить тебе від нечистої магії кіражів.", ["en"] = "Shroud of Unspoken Names", ["tasks"] = { ["21000 reputation with Cenarion Circle"] = "21000 репутації у Колі Кенаріона", ["Amber Idol"] = "бурштиновий ідол", ["Amber Idol (Provided)"] = "бурштиновий ідол (видано)", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Qiraji Regal Drape"] = "кіразька королівська пелерина", ["Qiraji Regal Drape (Provided)"] = "кіразька королівська пелерина (видано)" } },
    [8695] = { [1] = "Накидка вічної справедливості", [2] = "Я радий чути, що ти допомагаєш нам у нападі на Ан'Кіраж, {ім'я}. На знак подяки я можу зробити для тебе річ, що захищатиме тебе в битві проти наших ворогів, {клас}.\n\nМені знадобиться кіразька пелерина, яку я підшию під твій розмір, звичайно. Також мені знадобляться ідоли та скарабеї, з яких я зроблю застібку.\n\nОбіцяю, ця річ тебе не розчарує.", [3] = "Принесіть кіразьку королівську пелерину, 2 обсидіанових ідоли, 5 золотих та 5 глиняних скарабеїв Кейлу Прудкопазуру в Силітус. Для виконання цього завдання вам потрібно мати принаймні шановану репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} матеріали для накидки, {ім'я}?", [5] = "О так... ця пелерина бездоганна.\n\nВізьми цю накидку, {ім'я}. Нехай вона захистить тебе від нечистої магії кіражів.", ["en"] = "Cape of Eternal Justice", ["tasks"] = { ["21000 reputation with Cenarion Circle"] = "21000 репутації у Колі Кенаріона", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Obsidian Idol"] = "обсидіановий ідол", ["Obsidian Idol (Provided)"] = "обсидіановий ідол (видано)", ["Qiraji Regal Drape"] = "кіразька королівська пелерина", ["Qiraji Regal Drape (Provided)"] = "кіразька королівська пелерина (видано)" } },
    [8696] = { [1] = "Плащ Незримого Шляху", [2] = "Я радий чути, що ти допомагаєш нам у нападі на Ан'Кіраж, {ім'я}. На знак подяки я можу зробити для тебе річ, що захищатиме тебе в битві проти наших ворогів, {клас}.\n\nМені знадобиться кіразька пелерина, яку я підшию під твій розмір, звичайно. Також мені знадобляться ідоли та скарабеї, з яких я зроблю застібку.\n\nОбіцяю, ця річ тебе не розчарує.", [3] = "Принесіть кіразьку королівську пелерину, 2 сяйнистих ідоли, 5 кам'яних та 5 кришталевих скарабеїв Кейлу Прудкопазуру в Силітус. Для виконання цього завдання вам потрібно мати принаймні шановану репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} матеріали для плаща, {ім'я}?", [5] = "О так... ця пелерина бездоганна.\n\nВізьми цей плащ, {ім'я}. Нехай він захистить тебе від нечистої магії кіражів.", ["en"] = "Cloak of the Unseen Path", ["tasks"] = { ["21000 reputation with Cenarion Circle"] = "21000 репутації у Колі Кенаріона", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Lambent Idol"] = "сяйнистий ідол", ["Lambent Idol (Provided)"] = "сяйнистий ідол (видано)", ["Qiraji Regal Drape"] = "кіразька королівська пелерина", ["Qiraji Regal Drape (Provided)"] = "кіразька королівська пелерина (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [86964] = { [1] = "За золото та славу!", [2] = "Закликаємо всіх шукачів пригод та скарбів! Повідомляємо, що Кірін Тор дозволив виплатити значні кошти будь-яким особам, які зможуть спуститися в крипти під Каражаном та знайти певний магічний артефакт. Будь-які інші знайдені скарби, курйози чи монети не мають значення для ордена та можуть бути утримані як додаткова компенсація. Зацікавлені сторони повинні повідомити про це...\n\n<Нижня частина записки відірвана, а решта деталей відсутня.>", [3] = "Схоже, хтось хотів найняти шукачів пригод, щоб вони витягли щось цінне з крипт Каражана в перевалі Мертвого Вітру. Ви не можете бути впевнені, хто розмістив цей листівку або де їх знайти, але ідея значної винагороди від добре відомої та заможної організації, такої як Кірін Тор, а також схованки зі скарбами, які можна взяти, є, безумовно, цікавою перспективою.\n\nПодорожуйте до перевалу Мертвого Вітру та дослідіть крипти за вежею Каражана.", [5] = "Людина, що лежить перед вами, справді мертва. Здається, у неї немає жодних очевидних ран чи травм. Єдина дивна річ на тілі — це вираз сильного жаху на її обличчі. Здається, ніби ця жінка померла від страху...", ["en"] = "For Gold and Glory!" },
    [86965] = { [1] = "Незвичайні тіні", [2] = "Раптом, коли ви стаєте на коліна, на вас починає падати гнітюча темрява. Ви помічаєте, що все світло навколо темніє та зникає, коли темрява ніби тягнеться до вас. Це не природні тіні.\n\nШвидкий погляд на вхід до сусідньої крипти безсумнівно говорить вам, що ця зловісна темрява виходить із самої крипти, чорними, як чорнило, вусиками, що шукають більше світла, щоб загасити. Ви здригаєтеся, коли волосся на потилиці стає дибки.", [3] = "Морок, що просочується з входу до крипти, здається, суперечить будь-якій нормальній логіці та розуму. Жодне світло не проникає в темряву і не розганяє її, і жодне світло всередині, здається, не може її уникнути. Ви маєте сильну підозру, що якщо ви зараз зайдете в крипту, це може бути вашим кінцем.\n\nВам потрібно буде якось знайти спосіб подолати цю темряву, якщо ви хочете продовжити. Ви, здається, пам'ятаєте, що в таборі на півночі є агент Даларана. Можливо, вона знає більше про мертвого шукача пригод і цю дивну темряву?", [5] = "<Агент Кіанна дивиться на вас і злегка хмуриться.>\n\nПослухайте, я сказала останній групі, яка приходила сюди і питала про крипти, що в мене немає жодної інформації про винагороду, яку мій орден призначив за той проклятий скарб, що лежить під тією старою вежею. Моя сфера компетенції лежить в іншому, і я не уповноважена робити великі витрати від імені ордену.\n\nЯкщо більше нічого немає, я хотіла б повернутися до своїх досліджень.", ["en"] = "No Ordinary Shadows" },
    [86966] = { [1] = "Шукаємо тих, хто вижив", [2] = "О, розумію. Так, тіло, яке ви стверджуєте, що знайшли, справді збігається з моїми спогадами про одного з шукачів пригод, які нещодавно проходили тут. Наскільки я пам'ятаю, їх було п'ятеро. Я закликав їх не йти далі, але їх не вдалося відмовити. Здається, мої попередження були обґрунтованими, оскільки я не бачив, щоб хтось із них проходив повз. Я боявся найгіршого, і, ну...\n\nВи кажете, що вона була єдиним тілом, яке ви знайшли? Якщо це правда, можливо, десь у перевалі є інші вижили?", [3] = "Розшукайте будь-яких тих, хто вижив у невдалій групі шукачів пригод, і спробуйте дізнатися все, що можете, про те, що сталося в крипті.", [5] = "Чоловік ледь помітно ворушиться, коли ви наближаєтесь, майже непомітно відкриваючи одну повіку, щоб подивитися на вас. Спочатку він здавався серйозно пораненим, але тепер ви не зовсім впевнені...", ["en"] = "Seeking Survivors" },
    [86967] = { [1] = "На допомогу", [2] = "<Єдине відкрите око чоловіка зустрічається з твоїм.>\n\nПссс, ей ти. Так, ти! Думаєш, ти зможеш мене звідси витягнути? Я лежу тут годинами, вдаючи мертвого, але це лише питання часу, коли ці кляті людожери згадають, що я тут, і прийдуть мене з'їсти, або ще гірше!\n\nЦя клітка досить щільно замкнена, але один із цих негідників має мати ключ. Подивись, чи зможеш ти знайти його, і випусти мене. Я точно буду тобі в боргу.\n\nЯ збираюся продовжувати вдавати мертвого, поки ти візьмешся за роботу. А тепер іди... тихо!", [3] = "Знайдіть ключ від клітки в печері огрів Мертвого вітру та звільніть пораненого шукача пригод усередині.", [5] = "Як це я повернувся сюди раніше за тебе — весь у крові та зі струсом мозку?\n\n<Гаррісон Джонс хитає головою.>\n\nТи точно до цього готовий, малий?", ["en"] = "To the Rescue" },
    [86968] = { [1] = "Ви боїтеся темряви?", [2] = "Справді, безмежно вдячний тобі за допомогу. Ти справді врятував мене.\n\nЯ розмовляв з цією милою молодою жінкою, поки чекав на тебе, і думаю, що в неї можуть бути якісь ідеї, як допомогти тобі потрапити до того покинутого склепу, якщо ти справді наполягаєш на випробуванні долі.\n\nЯ, однак, забігаю наперед. Гадаю, я винен тобі деяку інформацію.", [3] = "Послухайте Гаррісона Джонса, коли він розповідає вам, що сталося в криптах Каражана.", [5] = "Отже, схоже, що група Джонса успішно проникла до крипти та натрапила на значний сховок зі скарбами. Темрява, яку описали ви і він, безумовно, має магічну природу. Очевидно, їхнє незграбне мародерство викликало реакцію чогось зловісного.\n\nЯ переглянув свої книги заклинань і думаю, що маю потенційне рішення, яке допоможе вам пройти крізь цю темряву, якщо ви все ще почуватиметеся достатньо сміливими, щоб продовжити. Ходімо, давайте поговоримо про це далі.", ["en"] = "Are You Afraid of the Dark?" },
    [86969] = { [1] = "Гіпотеза", [2] = "Гадаю, я можу створити щось на зразок магічного тотема, який дозволить тобі пробитися крізь цю зловісну темряву і хоча б дослідити крипти. Однак у мене з собою немає всіх компонентів. Дещо з цього може бути нелегко знайти, але, судячи з того, що я бачив від тебе досі, я вірю, що ти достатньо винахідливий, щоб отримати необхідне.", [3] = "Перегляньте список необхідних матеріалів та надайте агенту Кіанні запитувані компоненти.\n\nНаданий предмет:", [4] = "Вам вдалося відновити необхідні мені компоненти?", [5] = "Чудово. Це зв'язування досить просте, дозвольте мені просто... Ось! Гадаю, цього має вистачити.\n\nЦей чарівний смолоскип має дозволити вам пробити зловісну темряву достатньо, щоб хоча б побачити та дослідити Крипту. Однак майте на увазі, що вогник, який володіє цим предметом, має власну волю. Хоча я прив'язав його до цього об'єкта та до цієї конкретної мети, я не можу бути повністю впевненим, як він... поведе себе, коли ви досягнете Крипту.\n\nБудьте напоготові, коли прибудете. Ми не можемо повністю передбачити, що станеться.", ["en"] = "The Hypothesis", ["tasks"] = { ["List of Components"] = "Список компонентів" } },
    [8697] = { [1] = "Перстень нескінченної мудрості", [2] = "Подейкують, що персні, які носять лейтенанти кіражів, наділяють їх надзвичайними здібностями. Але, якщо замінити осквернені самоцвіти, які вставлені в оправу, на чисті, сила перснів зросте.\n\nСамоцвіти, що прикрашають кіразьких ідолів, чудово підійдуть, оскільки їхня якість відмінна.\n\nПринеси мені перстень одного з лейтенантів та ідоли, і я зроблю для тебе потужний перстень, {клас:к}.", [3] = "Принесіть кіразький церемоніальний перстень, 2 обсидіанових ідоли, 5 срібних та 5 кістяних скарабеїв вітрозову Єссендрі в Силітус. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені перстень та матеріали, {ім'я}?", [5] = "Я заміню самоцвіти на цьому персні. Ти побачиш, що ефект буде набагато... приємнішим.", ["en"] = "Ring of Infinite Wisdom", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Obsidian Idol"] = "обсидіановий ідол", ["Obsidian Idol (Provided)"] = "обсидіановий ідол (видано)", ["Qiraji Ceremonial Ring"] = "кіразький церемоніальний перстень", ["Qiraji Ceremonial Ring (Provided)"] = "кіразький церемоніальний перстень (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)" } },
    [86970] = { [1] = "Перевірка нашої гіпотези", [2] = "Я вважаю, що буде розумно випробувати цей пристрій, перш ніж ти повністю зануришся в темряву Крипт. Віднеси смолоскип до краю магічної темряви та активуй його. Подивись, чи він виконує свою функцію та забезпечує освітлення, а що ще важливіше, зрозумій, як він поводиться під впливом цієї магії.\n\nЦей тотем був пов'язаний з певною метою і мав би бути зобов'язаний дотримуватися цієї мети, але нічого конкретного не можна сказати, поки ми туди не потрапимо та не перевіримо цю гіпотезу.", [3] = "Йдіть до входу до крипт Каражана, використовуйте смолоскип Зачарованого Вогняного Голова та подивіться, що станеться. Поверніться до агента Кіани після завершення випробування.", [4] = "Що показав наш тест?", [5] = "Це гарна новина. Смолоскип не лише успішно розвіяв меншу темряву зовні крипти, але й зв'язування змусило його без прохання кинутися всередину, щоб продовжити виконувати своє призначення.\n\nТепер, коли зловісна темрява зовні крипти зникла, я підозрюю, що ви зможете безпечно увійти. Судячи з розповіді цього чоловіка, невідомо, що ви знайдете всередині, тому будьте обережні.\n\nУдачі.", ["en"] = "Testing Our Hypothesis", ["tasks"] = { ["Enchanted Firebrand"] = "Зачарований Вогняний Головоріз" } },
    [86971] = { [1] = "Цікаві Каражанські курйози!", [2] = "Тепер, коли ви знайшли спосіб потрапити до крипти, я хотів би попросити вас про послугу. Якщо це не було очевидно, я археолог, який працює в Королівській бібліотеці Штормовія. Я збираю артефакти та реліквії з усього світу для академічних досліджень та вивчення, і мене дуже цікавлять будь-які подібні курйози, які ви можете знайти в глибинах крипти. Приносьте мені будь-які, які, на вашу думку, можуть бути цікавими, і я зроблю все, що вам потрібно.", [3] = "Принесіть сувенір Каражана Гаррісону Джонсу в перевалі Мертвого вітру.", [4] = "Що в тебе для мене є, {ім'я}?", [5] = "Це чудова знахідка! Якщо ви знайдете ще такі артефакти, принесіть їх мені сюди, і я подбаю про те, щоб ви отримали належну винагороду за ваші зусилля.", ["en"] = "Curious Karazhan Curios!" },
    [86972] = { [1] = "Цікаві Каражанські курйози!", [2] = "Тепер, коли ви знайшли спосіб потрапити до крипти, я хотів би попросити вас про послугу. Якщо це не було очевидно, я археолог, який працює в Королівській бібліотеці Штормовія. Я збираю артефакти та реліквії з усього світу для академічних досліджень та вивчення, і мене дуже цікавлять будь-які подібні курйози, які ви можете знайти в глибинах крипти. Приносьте мені будь-які, які, на вашу думку, можуть бути цікавими, і я зроблю все, що вам потрібно.", [3] = "Принесіть сувенір Каражана Гаррісону Джонсу в перевалі Мертвого вітру.", [4] = "Пам’ятай, я шукаю будь-який артефакт чи скарб, який ти можеш знайти. У тій крипті є незліченні скарби, тож пильнуй!", [5] = "Це чудова знахідка! Якщо ви знайдете ще такі артефакти, принесіть їх мені сюди, і я подбаю про те, щоб ви отримали належну винагороду за ваші зусилля.", ["en"] = "Curious Karazhan Curios!" },
    [8698] = { [1] = "Перстень прийдешньої бурі", [2] = "Подейкують, що персні, які носять лейтенанти кіражів, наділяють їх надзвичайними здібностями. Але, якщо замінити осквернені самоцвіти, які вставлені в оправу, на чисті, сила перснів зросте.\n\nСамоцвіти, що прикрашають кіразьких ідолів, чудово підійдуть, оскільки їхня якість відмінна.\n\nПринеси мені перстень одного з лейтенантів та ідоли, і я зроблю для тебе потужний перстень, {клас:к}.", [3] = "Принесіть кіразький магістерський перстень, 2 багряних ідоли, 5 срібних та 5 кістяних скарабеїв вітрозову Єссендрі в Силітус. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені перстень та матеріали, {ім'я}?", [5] = "Я заміню самоцвіти на цьому персні. Ти побачиш, що ефект буде набагато... приємнішим.", ["en"] = "Ring of the Gathering Storm", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Qiraji Magisterial Ring"] = "кіразький магістерський перстень", ["Qiraji Magisterial Ring (Provided)"] = "кіразький магістерський перстень (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)", ["Vermillion Idol"] = "багряний ідол", ["Vermillion Idol (Provided)"] = "багряний ідол (видано)" } },
    [8699] = { [1] = "Перстень похованих таємниць", [2] = "Подейкують, що персні, які носять лейтенанти кіражів, наділяють їх надзвичайними здібностями. Але, якщо замінити осквернені самоцвіти, які вставлені в оправу, на чисті, сила перснів зросте.\n\nСамоцвіти, що прикрашають кіразьких ідолів, чудово підійдуть, оскільки їхня якість відмінна.\n\nПринеси мені перстень одного з лейтенантів та ідоли, і я зроблю для тебе потужний перстень, {клас:к}.", [3] = "Принесіть кіразький магістерський перстень, 2 лазурових ідоли, 5 золотих та 5 глиняних скарабеїв вітрозову Єссендрі в Силітус. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені перстень та матеріали, {ім'я}?", [5] = "Я заміню самоцвіти на цьому персні. Ти побачиш, що ефект буде набагато... приємнішим.", ["en"] = "Band of Vaulted Secrets", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Azure Idol"] = "лазуровий ідол", ["Azure Idol (Provided)"] = "лазуровий ідол (видано)", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Qiraji Magisterial Ring"] = "кіразький магістерський перстень", ["Qiraji Magisterial Ring (Provided)"] = "кіразький магістерський перстень (видано)" } },
    [8700] = { [1] = "Перстень нескінченного життя", [2] = "Подейкують, що персні, які носять лейтенанти кіражів, наділяють їх надзвичайними здібностями. Але, якщо замінити осквернені самоцвіти, які вставлені в оправу, на чисті, сила перснів зросте.\n\nСамоцвіти, що прикрашають кіразьких ідолів, чудово підійдуть, оскільки їхня якість відмінна.\n\nПринеси мені перстень одного з лейтенантів та ідоли, і я зроблю для тебе потужний перстень, {стать:брате:сестро} {клас:к}.", [3] = "Принесіть кіразький магістерський перстень, 2 алебастрових ідоли, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки вітрозову Єссендрі в Силітус. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені перстень та матеріали, {ім'я}?", [5] = "Я заміню самоцвіти на цьому персні. Ти побачиш, що готове творіння буде набагато... приємнішим.", ["en"] = "Band of Unending Life", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Alabaster Idol"] = "алебастровий ідол", ["Alabaster Idol (Provided)"] = "алебастровий ідол (видано)", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Qiraji Magisterial Ring"] = "кіразький магістерський перстень", ["Qiraji Magisterial Ring (Provided)"] = "кіразький магістерський перстень (видано)" } },
    [8701] = { [1] = "Перстень прихованих тіней", [2] = "Подейкують, що персні, які носять лейтенанти кіражів, наділяють їх надзвичайними здібностями. Але, якщо замінити осквернені самоцвіти, які вставлені в оправу, на чисті, сила перснів зросте.\n\nСамоцвіти, що прикрашають кіразьких ідолів, чудово підійдуть, оскільки їхня якість відмінна.\n\nПринеси мені перстень одного з лейтенантів та ідоли, і я зроблю для тебе потужний перстень, {клас:к}.", [3] = "Принесіть кіразький церемоніальний перстень, 2 оніксових ідоли, 5 кам'яних та 5 кришталевих скарабеїв вітрозову Єссендрі в Силітус. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені перстень та матеріали, {ім'я}?", [5] = "Я заміню самоцвіти на цьому персні. Ти побачиш, що ефект буде набагато... приємнішим.", ["en"] = "Band of Veiled Shadows", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Onyx Idol"] = "оніксовий ідол", ["Onyx Idol (Provided)"] = "оніксовий ідол (видано)", ["Qiraji Ceremonial Ring"] = "кіразький церемоніальний перстень", ["Qiraji Ceremonial Ring (Provided)"] = "кіразький церемоніальний перстень (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8702] = { [1] = "Перстень невимовних імен", [2] = "Подейкують, що персні, які носять лейтенанти кіражів, наділяють їх надзвичайними здібностями. Але, якщо замінити осквернені самоцвіти, які вставлені в оправу, на чисті, сила перснів зросте.\n\nСамоцвіти, що прикрашають кіразьких ідолів, чудово підійдуть, оскільки їхня якість відмінна.\n\nПринеси мені перстень одного з лейтенантів та ідоли, і я зроблю для тебе потужний перстень, {клас:к}.", [3] = "Принесіть кіразький церемоніальний перстень, 2 яшмових ідоли, 5 кам'яних та 5 кришталевих скарабеїв вітрозову Єссендрі в Силітус. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені перстень та матеріали, {ім'я}?", [5] = "Я заміню самоцвіти на цьому персні. Ти побачиш, що ефект буде набагато... приємнішим.", ["en"] = "Ring of Unspoken Names", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Jasper Idol"] = "яшмовий ідол", ["Jasper Idol (Provided)"] = "яшмовий ідол (видано)", ["Qiraji Ceremonial Ring"] = "кіразький церемоніальний перстень", ["Qiraji Ceremonial Ring (Provided)"] = "кіразький церемоніальний перстень (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8703] = { [1] = "Перстень вічної справедливості", [2] = "Подейкують, що персні, які носять лейтенанти кіражів, наділяють їх надзвичайними здібностями. Але, якщо замінити осквернені самоцвіти, які вставлені в оправу, на чисті, сила перснів зросте.\n\nСамоцвіти, що прикрашають кіразьких ідолів, чудово підійдуть, оскільки їхня якість відмінна.\n\nПринеси мені перстень одного з лейтенантів та ідоли, і я зроблю для тебе потужний перстень, {клас:к}.", [3] = "Принесіть кіразький магістерський перстень, 2 багряних ідоли, 5 срібних та 5 кістяних скарабеїв вітрозову Єссендрі в Силітус. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені перстень та матеріали, {ім'я}?", [5] = "Я заміню самоцвіти на цьому персні. Ти побачиш, що ефект буде набагато... приємнішим.", ["en"] = "Ring of Eternal Justice", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Qiraji Magisterial Ring"] = "кіразький магістерський перстень", ["Qiraji Magisterial Ring (Provided)"] = "кіразький магістерський перстень (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)", ["Vermillion Idol"] = "багряний ідол", ["Vermillion Idol (Provided)"] = "багряний ідол (видано)" } },
    [8704] = { [1] = "Перстень-печатка Незримого Шляху", [2] = "Подейкують, що персні, які носять лейтенанти кіражів, наділяють їх надзвичайними здібностями. Але, якщо замінити осквернені самоцвіти, які вставлені в оправу, на чисті, сила перснів зросте.\n\nСамоцвіти, що прикрашають кіразьких ідолів, чудово підійдуть, оскільки їхня якість відмінна.\n\nПринеси мені перстень одного з лейтенантів та ідоли, і я зроблю для тебе потужний перстень, {клас:к}.", [3] = "Принесіть кіразький церемоніальний перстень, 2 бурштинових ідоли, 5 золотих та 5 глиняних скарабеїв вітрозову Єссендрі в Силітус. Для виконання цього завдання вам потрібно мати принаймні почесну репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені перстень та матеріали, {ім'я}?", [5] = "Я заміню самоцвіти на цьому персні. Ти побачиш, що ефект буде набагато... приємнішим.", ["en"] = "Signet of the Unseen Path", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Amber Idol"] = "бурштиновий ідол", ["Amber Idol (Provided)"] = "бурштиновий ідол (видано)", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Qiraji Ceremonial Ring"] = "кіразький церемоніальний перстень", ["Qiraji Ceremonial Ring (Provided)"] = "кіразький церемоніальний перстень (видано)" } },
    [8705] = { [1] = "Молоток нескінченної мудрості", [2] = "Кіражі та їхні прислужники володіють предметами, виготовленими з найрідкісніших та найдосконаліших матеріалів: кісток велетенських та древніх створінь, самоцвітів з глибин землі, чистих та сильних металів.\n\nЛише один погляд на кіразькі артефакти сповнює мене бажанням практикувати своє ремесло з розбитими та розплавленими шматками їхніх артефактів. Доведи свою вірність Колу, {ім'я}, і я зроблю тобі могутню зброю з найкращих матеріалів кіражів.", [3] = "Принесіть кіразьке вишукане руків'я, 2 сяйнистих ідоли, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки вартовому Гаро в Силітус. Для виконання цього завдання вам потрібно мати возвеличену репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася} {клас:к}. Це руків'я майстерної роботи... ідеально збалансоване.\n\nВізьми свою зброю, {ім'я}. Використовуй її впевнено та розчави наших ворогів!", ["en"] = "Gavel of Infinite Wisdom", ["tasks"] = { ["42000 reputation with Cenarion Circle"] = "42000 репутації у Колі Кенаріона", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Lambent Idol"] = "сяйнистий ідол", ["Lambent Idol (Provided)"] = "сяйнистий ідол (видано)", ["Qiraji Ornate Hilt"] = "кіразьке вишукане руків'я", ["Qiraji Ornate Hilt (Provided)"] = "кіразьке вишукане руків'я (видано)" } },
    [8706] = { [1] = "Молот прийдешньої бурі", [2] = "Кіражі та їхні прислужники володіють предметами, виготовленими з найрідкісніших та найдосконаліших матеріалів: кісток велетенських та древніх створінь, самоцвітів з глибин землі, чистих та сильних металів.\n\nЛише один погляд на кіразькі артефакти сповнює мене бажанням практикувати своє ремесло з розбитими та розплавленими шматками їхніх артефактів. Доведи свою вірність Колу, {ім'я}, і я зроблю тобі могутню зброю з найкращих матеріалів кіражів.", [3] = "Принесіть кіразьке шиповане руків'я, 2 бурштинових ідоли, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки вартовому Гаро в Силітус. Для виконання цього завдання вам потрібно мати возвеличену репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася} {клас:к}. Це руків'я майстерної роботи... ідеально збалансоване.\n\nВізьми свою зброю, {ім'я}. Використовуй її впевнено та розчави наших ворогів!", ["en"] = "Hammer of the Gathering Storm", ["tasks"] = { ["42000 reputation with Cenarion Circle"] = "42000 репутації у Колі Кенаріона", ["Amber Idol"] = "бурштиновий ідол", ["Amber Idol (Provided)"] = "бурштиновий ідол (видано)", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Qiraji Spiked Hilt"] = "кіразьке шиповане руків'я", ["Qiraji Spiked Hilt (Provided)"] = "кіразьке шиповане руків'я (видано)" } },
