    [8709] = { [1] = "Кинджал прихованих тіней", [2] = "Кіражі та їхні прислужники володіють предметами, виготовленими з найрідкісніших та найдосконаліших матеріалів: кісток велетенських та древніх створінь, самоцвітів з глибин землі, чистих та сильних металів.\n\nЛише один погляд на кіразькі артефакти сповнює мене бажанням практикувати своє ремесло з розбитими та розплавленими шматками їхніх артефактів. Доведи свою вірність Колу, {ім'я}, і я зроблю тобі могутню зброю з найкращих матеріалів кіражів.", [3] = "Принесіть кіразьке вишукане руків'я, 2 багряних ідоли, 5 золотих та 5 глиняних скарабеїв вартовому Гаро в Силітус. Для виконання цього завдання вам потрібно мати возвеличену репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася} {клас:к}. Це руків'я майстерної роботи... ідеально збалансоване.\n\nВізьми свою зброю, {ім'я}. Використовуй її впевнено та розчави наших ворогів!", ["en"] = "Dagger of Veiled Shadows", ["tasks"] = { ["42000 reputation with Cenarion Circle"] = "42000 репутації у Колі Кенаріона", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Qiraji Spiked Hilt"] = "кіразьке шиповане руків'я", ["Qiraji Spiked Hilt (Provided)"] = "кіразьке шиповане руків'я (видано)", ["Vermillion Idol"] = "багряний ідол", ["Vermillion Idol (Provided)"] = "багряний ідол (видано)" } },
    [8710] = { [1] = "Кріс невимовних імен", [2] = "Кіражі та їхні прислужники володіють предметами, виготовленими з найрідкісніших та найдосконаліших матеріалів: кісток велетенських та древніх створінь, самоцвітів з глибин землі, чистих та сильних металів.\n\nЛише один погляд на кіразькі артефакти сповнює мене бажанням практикувати своє ремесло з розбитими та розплавленими шматками їхніх артефактів. Доведи свою вірність Колу, {ім'я}, і я зроблю тобі могутню зброю з найкращих матеріалів кіражів.", [3] = "Принесіть кіразьке вишукане руків'я, 2 оніксові ідоли, 5 золотих та 5 глиняних скарабеїв вартовому Гаро в Силітус. Для виконання цього завдання вам потрібно мати возвеличену репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася} {клас:к}. Це руків'я майстерної роботи... ідеально збалансоване.\n\nВізьми свою зброю, {ім'я}. Використовуй її впевнено та розчави наших ворогів!", ["en"] = "Kris of Unspoken Names", ["tasks"] = { ["42000 reputation with Cenarion Circle"] = "42000 репутації у Колі Кенаріона", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Onyx Idol"] = "оніксовий ідол", ["Onyx Idol (Provided)"] = "оніксовий ідол (видано)", ["Qiraji Ornate Hilt"] = "кіразьке вишукане руків'я", ["Qiraji Ornate Hilt (Provided)"] = "кіразьке вишукане руків'я (видано)" } },
    [8711] = { [1] = "Клинок вічної справедливості", [2] = "Кіражі та їхні прислужники володіють предметами, виготовленими з найрідкісніших та найдосконаліших матеріалів: кісток велетенських та древніх створінь, самоцвітів з глибин землі, чистих та сильних металів.\n\nЛише один погляд на кіразькі артефакти сповнює мене бажанням практикувати своє ремесло з розбитими та розплавленими шматками їхніх артефактів. Доведи свою вірність Колу, {ім'я}, і я зроблю тобі могутню зброю з найкращих матеріалів кіражів.", [3] = "Принесіть кіразьке шиповане руків'я, 2 бурштинових ідоли, 5 бронзових скарабеїв та 5 скарабеїв зі слонової кістки вартовому Гаро в Силітус. Для виконання цього завдання вам потрібно мати возвеличену репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я тебе просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {клас:к}. Це руків'я майстерної роботи... ідеально збалансоване.\n\nВізьми свою зброю, {ім'я}. Використовуй її впевнено та розчави наших ворогів!", ["en"] = "Blade of Eternal Justice", ["tasks"] = { ["42000 reputation with Cenarion Circle"] = "42000 репутації у Колі Кенаріона", ["Amber Idol"] = "бурштиновий ідол", ["Amber Idol (Provided)"] = "бурштиновий ідол (видано)", ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Qiraji Spiked Hilt"] = "кіразьке шиповане руків'я", ["Qiraji Spiked Hilt (Provided)"] = "кіразьке шиповане руків'я (видано)" } },
    [8712] = { [1] = "Коса Незримого Шляху", [2] = "Кіражі та їхні прислужники володіють предметами, виготовленими з найрідкісніших та найдосконаліших матеріалів: кісток велетенських та древніх створінь, самоцвітів з глибин землі, чистих та сильних металів.\n\nЛише один погляд на кіразькі артефакти сповнює мене бажанням практикувати своє ремесло з розбитими та розплавленими шматками їхніх артефактів. Доведи свою вірність Колу, {ім'я}, і я зроблю тобі могутню зброю з найкращих матеріалів кіражів.", [3] = "Принесіть кіразьке шиповане руків'я, 2 лазурових ідоли, 5 срібних та 5 кістяних скарабеїв вартовому Гаро в Силітус. Для виконання цього завдання вам потрібно мати возвеличену репутацію у Кенарійського Кола.", [4] = "Ти {стать:приніс:принесла} мені компоненти, про які я просив, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася} {клас:к}. Це руків'я майстерної роботи... ідеально збалансоване.\n\nВізьми свою зброю, {ім'я}. Використовуй її впевнено та розчави наших ворогів!", ["en"] = "Scythe of the Unseen Path", ["tasks"] = { ["42000 reputation with Cenarion Circle"] = "42000 репутації у Колі Кенаріона", ["Azure Idol"] = "лазуровий ідол", ["Azure Idol (Provided)"] = "лазуровий ідол (видано)", ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Qiraji Spiked Hilt"] = "кіразьке шиповане руків'я", ["Qiraji Spiked Hilt (Provided)"] = "кіразьке шиповане руків'я (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)" } },
