    [8719] = { [1] = "Предок Клинкоспів", [5] = "Небеса у своїх незліченних зірках зберігають відповіді на земні таємниці, {ім'я}. Тож чи можуть мудрі та щасливі поглянути туди й знайти істину?", ["en"] = "Bladesing the Elder" },
    [8720] = { [1] = "Предок Небоблиск", [5] = "Небеса у своїх незліченних зірках зберігають відповіді на земні таємниці, {ім'я}. Тож чи можуть мудрі та щасливі поглянути туди й знайти істину?", ["en"] = "Skygleam the Elder" },
    [8721] = { [1] = "Предок Зореткач", [5] = "Небеса у своїх незліченних зірках зберігають відповіді на земні таємниці, {ім'я}. Тож чи можуть мудрі та щасливі поглянути туди й знайти істину?", ["en"] = "Starweave the Elder" },
    [8722] = { [1] = "Предок Лугобіг", [5] = "Небеса у своїх незліченних зірках зберігають відповіді на земні таємниці, {ім'я}. Тож чи можуть мудрі та щасливі поглянути туди й знайти істину?", ["en"] = "Meadowrun the Elder" },
    [8723] = { [1] = "Предок Ночевітер", [5] = "Небеса у своїх незліченних зірках зберігають відповіді на земні таємниці, {ім'я}. Тож чи можуть мудрі та щасливі поглянути туди й знайти істину?", ["en"] = "Nightwind the Elder" },
    [8724] = { [1] = "Предок Вранішня Роса", [5] = "Небеса у своїх незліченних зірках зберігають відповіді на земні таємниці, {ім'я}. Тож чи можуть мудрі та щасливі поглянути туди й знайти істину?", ["en"] = "Morningdew the Elder" },
    [8725] = { [1] = "Предок Пісня Струмка", [5] = "Небеса у своїх незліченних зірках зберігають відповіді на земні таємниці, {ім'я}. Тож чи можуть мудрі та щасливі поглянути туди й знайти істину?", ["en"] = "Riversong the Elder" },
    [8726] = { [1] = "Предок Ясноспис", [5] = "Небеса у своїх незліченних зірках зберігають відповіді на земні таємниці, {ім'я}. Тож чи можуть мудрі та щасливі поглянути туди й знайти істину?", ["en"] = "Brightspear the Elder" },
    [8727] = { [1] = "Предок Далешепіт", [5] = "Небеса у своїх незліченних зірках зберігають відповіді на земні таємниці, {ім'я}. Тож чи можуть мудрі та щасливі поглянути туди й знайти істину?", ["en"] = "Farwhisper the Elder" },
    [8728] = { [1] = "Хороші та погані новини", [2] = "Це зайняло трохи більше часу, ніж я очікував. Тепер подивимось, що тут написано.\n\n<Нараін мовчки читає книгу, періодично бурчачи під ніс.>\n\nДобра новина в тому, що я на 99% впевнений, що здатен створити арканітовий буй, який буде функціонувати відповідно до твоїх вимог. Звісно, це повністю залежить від поганої новини.\n\nПогана новина в тому, що мені знадобиться купа арканіту, елементієвої руди та рідкісних дорогоцінних каменів.\n\nПринеси мені все, що потрібно, і я зроблю буй.", [3] = "Нараін Тихомрій з Танарісу хоче, щоб ви принесли йому 20 арканітових злитків, 10 одиниць елементієвої руди, 10 азеротських діамантів і 10 синіх сапфірів.", [4] = "Арканітові буї самі себе не зроблять, {ім'я}. І НІ, в борг не дам.", [5] = "Угода є угода. Я сподіваюсь, що ти знаєш, у що {стать:вляпався:вляпалася}, {ім'я} Це надто багато труднощів для того, щоб просто половити рибу.", ["en"] = "The Good News and The Bad News", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Azerothian Diamond"] = "азеротський діамант", ["Azerothian Diamond (Provided)"] = "азеротський діамант (видано)", ["Blue Sapphire"] = "синій сапфір", ["Blue Sapphire (Provided)"] = "синій сапфір (видано)", ["Elementium Ore"] = "елементієва руда", ["Elementium Ore (Provided)"] = "елементієва руда (видано)" } },
    [87283] = { [1] = "Фіолетовий саквояж", [2] = "Ви знайшли маленьку фіолетову сумку, яка, схоже, має знак Кірін-Тора. Однак, попри всі ваші зусилля, ви, здається, не можете знайти способу підняти клапан і побачити, що всередині. Записка на тілі шукача пригод, де ви її знайшли, свідчить про те, що вона може бути власністю Архімага Кір-Молдіра з Даларана. Можливо, вам варто знайти Архімага та повернути його майно... і отримати обіцяну винагороду.", [3] = "Знайдіть Архімага Тарсіса Кір-Молдіра та поверніть йому Фіолетову Сумку.", [4] = "Здається, Архімаг тебе не чує...", [5] = "Що це у тебе? Чи це... чи це можливо?\n\n<Архімаг швидко вихоплює у тебе сумку. Він шепоче заклинання і висипає вміст собі в руки, відкриваючи два маленькі червоні дорогоцінні камені.>\n\nОчі! Так, очі! Вони в мене є! Дякую. Будь ласка, залиш мене зараз... Іди! Іди, поки я не змушений тебе знищити!\n\n<Суворий погляд у його очах говорить про те, що він налаштований досить серйозно. Коли ти починаєш відступати, Архімаг відвертається, згинаючись і міцно притискаючи дорогоцінні камені до грудей.>", ["en"] = "The Violet Satchel", ["tasks"] = { ["Violet Satchel"] = "Вайолет Сатчел" } },
    [8729] = { [1] = "Гнів Нептулона", [2] = "Я вже розповідав тобі погану новину? Її ім'я — Пащі, це 30 метрів смерті й руйнування. Здається, я забув про цей маленький нюанс.\n\nМоє ясновидіння говорить мені, тищо найкраще закинути буй біля берегів Азшари, в затоці Штормів.\n\nШукай закручений вир, ймовірно, захаращений уламками.\n\nДо речі, я сподіваюсь, у тебе є друзі.\n\nЯкщо ти якимось дивом успішно впораєшся з цим завданням, віднеси уламок скіпетра до Анахроноса.", [3] = "Використайте арканітовий буй у закрученому вирі в затоці Штормів, що в Азшарі.", [4] = "Час спливає, {стать:чемпіоне:чемпіонко}.", [5] = "Молодець, {ім'я:к}. Незабаром я зможу відтворити скіпетр Мінливих Пісків.", ["en"] = "The Wrath of Neptulon", ["tasks"] = { ["Blue Scepter Shard"] = "синій уламок скіпетра", ["Blue Scepter Shard (Provided)"] = "синій уламок скіпетра (видано)" } },
    [8730] = { [1] = "Пошесть Нефарія", [2] = "То це ти {стать:чемпіон:чемпіонка}? Тисячоліття минуло з тої пори, як мені довірили цей уламок, і в цей найтемніший час ти маєш звільнити мене від цієї ноші.. Але яка ж трагедія без жорстокості?\n\n<Велестраз безсило кашляє.>\n\nУ... уламок скіпетра тепер у Нефарія.\n\nЧас не чекає. Нефарій планує знищити уламок. Ти маєш поспішати!", [3] = "Вбийте Нефаріана та заволодійте червоним уламком скіпетра. Поверніть уламок Анахроносу в Печери Часу, що в Танарісі. У вас є 5 годин, щоб виконати це завдання.", [4] = "Іще один з наших героїв зазнав поразки від породження Смертекрила. Ми будемо прокляті на вічні страждання...", [5] = "Душа Велестраза спокійна, {стать:чемпіоне:чемпіонко}. Аспекти уважно спостерігають за твоїми успіхами. Знай, що в тебе є могутні союзники.\n\nМені наказали дещо передати тобі, воно допоможе на твоєму шляху. Користуйся цим з розумом.", ["en"] = "Nefarius's Corruption", ["tasks"] = { ["Red Scepter Shard"] = "червоний уламок скіпетра", ["Red Scepter Shard (Provided)"] = "червоний уламок скіпетра (видано)" } },
    [87318] = { [1] = "Серця загублених", [2] = "Відколи дворфи Темного Заліза підірвали міст, віадук Тандола став небезпечним місцем, але я не очікувала зустріти їх там!\n\nМені вдалося втекти, та я загубила з виду свою супутницю Ессену. Я всюди шукала її, але не знайшла жодного сліду. Її схопили дворфи Темного Заліза? Вона впала в річку внизу? Чи змогла повернутися на інший берег? Не знаю! Я навіть не знаю, чи вона жива!\n\nБудь ласка, якщо знайдеш хоч якийсь її слід, повідом мені!", [3] = "Знайдіть супутницю Корми — Ессену.", ["en"] = "Hearts of the Lost" },
    [8733] = { [1] = "Еранік, тиран сну", [2] = "Це шлях спокути, {стать:герою:героїне}. Якщо мене сьогодні вб'ють, я помру за справедливу й праведну справу. Ти маєш повернути зелений уламок скіпетра. Очисть Ераніка від прокляття, накладеного Старими Богами.\n\nВирушай в Дарнас. Одразу за містом ти знайдеш одного з моїх підлеглих. Він розпочне справу та попередить Тіранду про наші плани так, щоб Оленеріг ні про що не дізнався.\n\n<Малфуріон зітхає.>\n\nВтратити благодать тисячоліть...", [3] = "Вирушайте на Тельдрассіль та знайдіть підлеглого Малфуріона біля стін Дарнаса.", [5] = "Світлик мовчить та іноді тихенько гудить. Як не дивно, він може говорити з вами подумки.", ["en"] = "Eranikus, Tyrant of the Dream" },
    [8734] = { [1] = "Тіранда та Ремул", [2] = "Я сповіщу Тіранду, {стать:смертний:смертна}. Шан'до Шаленство Бурі готував мене до цієї надзвичайної ситуації.\n\nТепер ти {стать:повинен:повинна} вирушати на Місячну галявину та поговорити з Ремулом. Він надасть подальші інструкції щодо виклику Ераніка.\n\nМи всі бажаємо тобі удачі.", [3] = "Вирушайте на Місячну галявину та поговоріть з хранителем Ремулом.", [5] = "Витягнути Ераніка зі Смарагдового Сну буде неможливо, якщо він сам цього не забажає. Однак його наміри потребують входження у наш світ. Він прагне знищити живий прояв Малфуріона. Якщо в нього це вийде, то ми втратимо одного з наймогутніших союзників Смарагдового Сну. Жах повністю поглине все, що лишиться, якщо Малфуріона не стане...", ["en"] = "Tyrande and Remulos" },
    [8735] = { [1] = "Зараження Жаху", [2] = "Ти {стать:повинен:повинна} піти до чотирьох порталів сну на Азероті. З кожного з них тобі потрібно добути фрагмент зараження Жаху. Драконіди, що мешкають там, мають такі фрагменти. Повертайся до мене, коли збереш їх усі.", [3] = "Прямуйте до чотирьох порталів Смарагдового Сну в Азероті та зберіть по фрагменту зараження Жаху з кожного з них. Повертайтеся до хранителя Ремула в Місячну галявину, коли виконаєте це завдання.", [4] = "<Ремул глибоко занурений у власні думки.>", [5] = "Ти {стать:готовий:готова}? Чи готовий світ до того, що ми збираємось викликати? Я не знаю… Я прикутий обов'язком перед Малфуріоном. Обов'язком і честю...", ["en"] = "The Nightmare's Corruption", ["tasks"] = { ["Fragment of the Nightmare's Corruption"] = "фрагмент зараження Жаху", ["Fragment of the Nightmare's Corruption (Provided)"] = "фрагмент зараження Жаху (видано)" } },
    [8736] = { [1] = "Втілення Кошмару", [2] = "Ми маємо протриматися проти Ераніка. Нам потрібно врятувати його, а не знищити.\n\nТіранда вже йде нам на допомогу. Ми повинні відбивати удари дракона та врятувати Нічну Гавань від неминучого знищення.\n\nБудь напоготові! Ти й твої союзники — наша єдина надія.", [3] = "Захистіть Нічну Гавань від Ераніка. Не дайте хранителеві Ремулу загинути. Не вбивайте Ераніка. Захищайте себе. Дочекайтеся Тіранди.", [5] = "Його прощено, {ім'я:к}, і тепер він повертається в Сон, щоб виправити власні помилки. Еранік буде могутнім союзником Малфуріона та мого батька.\n\nЦе спорядження, дароване мені самою Ізерою — для тебе, {ім'я:к}. Тобі варто скористатися ним у твоїх битвах з кіражами.", ["en"] = "The Nightmare Manifests", ["tasks"] = { ["The Redemption of Eranikus"] = "Викуплення Еранікуса" } },
    [87360] = { [1] = "Падіння Кел'Тузада", [2] = "Філактерій — це все, що залишилося від господаря Наксрамаса. Ваш здоровий глузд підказує вам знищити філактерій, щоб запобігти переродженню ліча. На щастя, ви рідко прислухаєтеся до цього внутрішнього голосу розуму.\n\nХтось у Світлій Надії заплатить вам величезні гроші за цей артефакт. Кого хвилює, що Кел'Тузад регенерується до повної сили?", [3] = "Віднесіть Філакторій Кел'Тузада до каплиці Надії Світла у Східних Чумних землях.", [4] = "БЛАГОСЛОВЕННЕ СВІТЛО! Яку мерзоту ти тримаєш, хлопче?", [5] = "За всі свої дні я б ніколи не очікував побачити таке...\n\n<Здається, у отця Монтоя слинки течуть.>\n\nО так, ти будеш винагороджений, любий хлопчику. Ти будеш щедро винагороджений. Дай це сюди. Зараз!", ["en"] = "The Fall of Kel'Thuzad" },
    [87361] = { [1] = "Похований", [2] = "Вирване з Тіні Долі, серце ледь чутно пульсує та вібрує.\n\nВи намагаєтеся покласти його в сумку, але вас охоплює непереборне почуття гніву, страху, жаху, а потім... смутку.\n\nКоли ці почуття вщухають, ви відчуваєте, ніби щойно прожили інше життя.\n\nМожливо, хтось у каплиці Світлої Надії зможе пролити світло на те, що ви щойно відчули.", [3] = "Подивіться, чи може хтось допомогти вам у каплиці Світлої Надії у Східних Чумних землях.", [4] = "Тобі не потрібно пояснювати, {ім'я}.\n\nТвоя присутність тут і ця сфера говорять мені все, що мені потрібно знати.\n\nТемрява випробувала тебе, {ім'я}.\n\nТобі пощастило. З бичем та його прокляттями не варто гратися.\n\nСвітло слідує за тобою.", [5] = "Майже ніхто з тих, хто торкається цих проклятих предметів, досі не притомний.\n\n<Хоча вираз його обличчя не змінився, сльози починають котитися по його обличчю, коли ти передаєш йому серце>\n\nАх... цей не хоче йти. Вони були {клас}... як і ти...\n\n{ім'я}, якщо ти готовий нести цей тягар, я можу тобі допомогти. Я можу вигравіювати цю неспокійну душу на твоїх обладунках...\n\nЯ виявив, що, як і тягар світу, найкраще місце для носіння душі — це твої плечі.", ["en"] = "Laid to Rest", ["tasks"] = { ["Item #236750"] = "Товар №236750" } },
    [87362] = { [1] = "Надія починається в темряві", [2] = "Наксрамас становить загрозу, з якою ви ще не стикалися. Це осередок могутності Кел'Тузада, де зберігаються жахи, невідомі навіть найпошрамованішим у битвах серед Срібного Світанку.\n\nВізьми цю печатку.\n\nКоли ти наважуєшся ступити в некрополь, ти несеш тягар наших надій, {ім'я}. Цілком справедливо, що ти також несеш нашу силу.", [3] = "Отримайте Печатку Світанку.", [5] = "Ця печатка посилить спорядження, яке ви знайдете всередині Наксрамаса.\n\nТримайте її поруч і використовуйте з розумом.", ["en"] = "Hope Begins in the Dark" },
    [87364] = { [1] = "Запечатати угоду", [3] = "Зберіть Залишки Доблесті в Наксрамасі.", [4] = "Чесно кажучи, {ім'я}, можливо, є спосіб покращити силу твоєї печатки.\n\nКоли ми очищаємо останки могутніх лейтенантів Бичі, невелика кількість святої енергії не тільки зберігається, але й загартовується. Цю енергію можна перетворити на силу.\n\nЗанурся глибше в Наксрамас, герою, і поверни для мене останки цих лейтенантів Бичі. У свою чергу, я можу посилити твою печатку.", [5] = "Ти добре впорався, що приніс мені це, {ім'я}.\n\nЦікаво, скільки з них походить від наших загиблих братів? Чи вони десь там ще були? Я маю вірити, що вони хотіли б, щоб ми запобігли тому, щоб інші стали такими, як вони. Можливо, це невелика втіха.\n\nДозволь мені посилити твою печатку.", ["en"] = "Seal the Deal" },
    [87365] = { [1] = "Доблесть зростає завдяки сміливості", [3] = "Зберіть Залишки Доблесті в Наксрамасі.", [4] = "Твоя печатка має пройти довгий шлях, якщо ти хочеш побачити її повною мірою. Принеси мені більше Залишків Доблесті, і я продовжуватиму забезпечувати тебе силою захищати наш світ.\n\nПам'ятай, герою, що мертві не можуть вимагати справедливості. Обов'язок живих — робити це за них.", [5] = "Чудово. Як і раніше, це займе лише мить.", ["en"] = "Valor Grows by Daring" },
    [87366] = { [1] = "Лицарський час", [3] = "Зберіть Залишки Доблесті в Наксрамасі.", [4] = "Кожен убитий поплічник Батога — це звільнена душа, {ім'я}. Ніколи не забувай добро, яке ти робиш, навіть... ні, особливо коли битва здається безнадійною. Поки ми протистоїмо йому, армії Короля-Ліча не зможуть нас зупинити.\n\nПідозраю, ти вже знаєш, як це працює. Дай мені більше залишків, і я продовжуватиму посилювати твою печатку.", [5] = "Правосуддя не прагне винагороди, {ім'я}.\n\nАле я знаю, що ти прагнеш. Візьми це.", ["en"] = "Knight Time" },
    [87367] = { [1] = "Нове світло", [3] = "Отримайте Печатку Світанку.", [4] = "Щоразу, коли ми посилюємо твою печатку, ми робимо крок до припинення вторгнення Кел'Тузада.\n\nБудьте сильними, і ми звільнимо Азерот від Короля-Ліча та його лейтенантів в найкоротші терміни.", [5] = "Ти справжній герой, {ім'я}. Сам Попелоносець був би вражений.", ["en"] = "A New Light" },
    [87368] = { [1] = "Продукт віри", [3] = "Отримайте Печатку Світанку.", [4] = "Мене аж тремтить від думки про жахіття, з якими тобі довелося зіткнутися, щоб дійти так далеко. Ти натхнення для Срібного Світанку, і я можу лише молитися, щоб ти продовжував допомагати нам у такий спосіб.\n\nПринеси мені більше Залишків Доблесті, і я посилю твою печатку. Я вірю, що є ще довгий шлях, перш ніж ти реалізуєш свій потенціал.", [5] = "Молодець, {ім'я}. Очистити занепалих було б гідним заняттям саме по собі, навіть якби не обіцяли жодної винагороди.\n\nЗвісно, це не твій випадок! Візьми свою щойно наділену силою печатку.", ["en"] = "A Product of Faith" },
    [87369] = { [1] = "Плідкування віри", [3] = "Отримайте Печатку Світанку.", [4] = "Я ніколи не уявляв, що Багряний Хрестовий Похід та Срібний Світанок зможуть відкинути свої розбіжності та боротися за спільне благо, але ось ми тут.\n\nЗнову і знову ти доводив, що наша авантюра окупилася. Поверни більше Залишків Доблесті, чемпіоне. Я відчуваю, що ми близькі до того, щоб завдати останнього удару Кел'Тузадові та йому подібним.", [5] = "Ще раз дякую вам, і ще раз доведу свою вдячність, надавши силу вашій печатці.", ["en"] = "Cultivating Faith" },
    [8737] = { [1] = "Лазурний храмовник", [2] = "Сутінковий Молот і елементалі, яким вони поклоняються, становлять величезну загрозу для нашої діяльності у Силітусі. Враховуючи, що у нас з'явилися нові вороги всередині Ан'Кіражу, ми не можемо дозволити собі послабити пильність до ворогів ззовні.\n\nЗнайди спосіб викликати та знищити лазурного храмовника і повідом про виконання завдання Бора Дику Гриву.", [3] = "Викличте та вбийте лазурного храмовника і повідомте про виконання завдання Бора Дику Гриву в Кенарійській цитаделі. Щоб виконати це завдання, потрібно мати з собою план тактичного завдання I.", [4] = "Ти вже {стать:виконав:виконала} завдання, {ім'я}?", [5] = "Гарна робота, {ім'я}. Ось твоє наступне завдання.", ["en"] = "Azure Templar", ["tasks"] = { ["Azure Templar"] = "лазурний храмовник", ["Azure Templar slain"] = "лазурний храмовник: убито", ["Tactical Task Briefing I"] = "план тактичного завдання I", ["Tactical Task Briefing I (Provided)"] = "план тактичного завдання I (видано)" } },
    [87377] = { [1] = "Ніколи не відпочиває", [2] = "Приводьте мені будь-які приречені душі, які перетинаються на вашому шляху, {ім'я}.\n\nДозвольте мені перефразувати це – ви ПОВИННІ привести їх до мене.\nМій обов'язок – залишатися та направляти душі загиблих. Ваш обов'язок – привести їх до мене.\n\nПорада: ніколи не беріть більше однієї душі одночасно. Повірте мені, ваша душа може витримати лише певну кількість, а ваш розум... ну... він може витримати ще менше.\n\nЦей тягар тепер ваш. Тому що ви можете, ви повинні.\n\nВважайте це моральним обов'язком.", [3] = "Принесіть ще одне Серце Долі Брату Луктусу в Каплицю Надії Світла у Східних Чумних землях.", [4] = "Лихо ніколи не відпочиває, тому ми ніколи не повинні відпочивати, {ім'я}.", [5] = "{ім'я}, з кожним поверненим серцем я стою в покорі. Деякі з душ належать могутнім воїнам. Деякі здавалися незламними... і все ж... вони впали.\n\nБич охопив їх, корупція проникла в їхні розуми, або, в деяких випадках, вони добровільно скорилися.\n\nТака величезна сила була знищена.\n\nІ тепер, завдяки вам, вони зберігають свою останню крихту доблесті.\n\nБез вас жахи їхньої смерті переважили б героїзм їхнього життя.", ["en"] = "Never at Rest" },
    [8738] = { [1] = "Звіт розвідника Вул'Регаля", [2] = "Ми відправили наших найкращих розвідників всередину вуликів силітидів, щоб зібрати дані. Розвідник Лендіон вже кілька днів спостерігає за пересуванням силітидів у Вул'Регалі. Знайди його й забери письмовий звіт. {ім'я}, ми маємо якнайшвидше отримати ці дані, щоб почати діяти.", [3] = "Зв'яжіться з кенарійським розвідником Лендіоном у Вул'Регалі та принесіть звіт розвідника Вул'Регаля вітрозову Гордому Рогу в Кенарійську цитадель. Щоб виконати це завдання, потрібно мати з собою план тактичного завдання VII.", [4] = "Ти знайдеш розвідника Лендіона всередині Вул'Регаля. Поспіши, {ім'я}! Немає часу на зволікання.", [5] = "Ми дуже цінуємо твої зусилля, {ім'я}. Я прочитаю ці звіти прямо зараз, можеш переходити до наступного завдання.", ["en"] = "Hive'Regal Scout Report", ["tasks"] = { ["Hive'Regal Scout Report"] = "звіт розвідника Вул'Регаля", ["Hive'Regal Scout Report (Provided)"] = "звіт розвідника Вул'Регаля (видано)", ["Tactical Task Briefing VII"] = "план тактичного завдання VII", ["Tactical Task Briefing VII (Provided)"] = "план тактичного завдання VII (видано)" } },
    [8739] = { [1] = "Звіт розвідниці Вул'Аші", [2] = "Ми відправили наших найкращих розвідників всередину вуликів силітидів, щоб зібрати дані. Розвідниця Жалія вже кілька днів спостерігає за пересуванням силітидів у Вул'Аші. Знайди її й забери письмовий звіт. {ім'я}, ми маємо якнайшвидше отримати ці дані, щоб почати діяти.", [3] = "Зв'яжіться з кенарійською розвідницею Жалією у Вул'Аші та принесіть звіт розвідниці Вул'Аші вітрозову Гордому Рогу в Кенарійську цитадель. Щоб виконати це завдання, потрібно мати з собою план тактичного завдання VIII.", [4] = "Ти знайдеш розвідницю Жалію всередині Вул'Аші. Поспіши, {ім'я}! Немає часу на зволікання.", [5] = "Ми дуже цінуємо твої зусилля, {ім'я}. Я прочитаю ці звіти прямо зараз, можеш переходити до наступного завдання.", ["en"] = "Hive'Ashi Scout Report", ["tasks"] = { ["Hive'Ashi Scout Report"] = "звіт розвідниці Вул'Аші", ["Hive'Ashi Scout Report (Provided)"] = "звіт розвідниці Вул'Аші (видано)", ["Tactical Task Briefing VIII"] = "план тактичного завдання VIII", ["Tactical Task Briefing VIII (Provided)"] = "план тактичного завдання VIII (видано)" } },
    [8740] = { [1] = "Сутінкові мародери", [2] = "Останнім часом ми почали помічати, що верхові загони прихильників Сутінкового Молота переслідують наші патрулі та каравани за межами Кенарійської цитаделі.\n\nЗнайди й вбий сутінкових мародерів разом з їхнім ватажком — жахливою воїтелькою, на ім'я Морна. Про виконання завдання прозвітуй вітрозову Гордому Рогу.", [3] = "Вбийте сутінкового мародера Морну та 5 сутінкових мародерів. Коли виконаєте завдання, прозвітуйте вітрозову Гордому Рогу. Щоб виконати це завдання, потрібно мати з собою план тактичного завдання IX.", [4] = "Ти вже {стать:виконав:виконала} завдання, {ім'я}?", [5] = "Молодець, {ім'я}. Сутінкові мародери завдавали неприпустимо великої кількості втрат нашим патрулям. Ось твоє наступне завдання.", ["en"] = "Twilight Marauders", ["tasks"] = { ["Tactical Task Briefing IX"] = "план тактичного завдання IX", ["Tactical Task Briefing IX (Provided)"] = "план тактичного завдання IX (видано)", ["Twilight Marauder"] = "сутінковий мародер", ["Twilight Marauder Morna"] = "сутінковий мародер Морна", ["Twilight Marauder Morna slain"] = "сутінковий мародер Морна: убито", ["Twilight Marauder slain"] = "сутінковий мародер: убито" } },
    [8741] = { [1] = "Повернення чемпіона", [2] = "Хранитель чекає на твоє повернення, {Ім'я}. Віднеси зелений уламок скіпетра Анахроносу в Печери Часу.", [3] = "Віднесіть зелений уламок скіпетра Анахроносу в Печери Часу, що в Танарісі.", [4] = "<Анахронос киває.>", [5] = "Твої вчинки будуть відомі всім, {стать:чемпіоне:чемпіонко}. Тебе вихвалятимуть у піснях від Орґріммара до далей Південних морів. Усім буде відомо про {стать:чемпіона:чемпіонку} бронзових драконів, {ім'я:з}.", ["en"] = "The Champion Returns", ["tasks"] = { ["Green Scepter Shard"] = "зелений уламок скіпетра", ["Green Scepter Shard (Provided)"] = "зелений уламок скіпетра (видано)" } },
    [8742] = { [1] = "Сила Калімдора", [4] = "Скіпетр Мінливих Пісків знову цілий, {ім'я}.\n\nТільки ти можеш скористатися цим скіпетром. Тільки ти можеш принести нову еру своєму народові.\n\nТобі треба почекати, поки армії Орди та Альянсу прибудуть до Силітусу перш ніж ти удариш в гонг Скарабея.", [5] = "Минула тисяча років і, як було передбачено, переді мною стоїть {стать:обраний:обрана}. {стать:Той:Та}, хто проведе свій народ у нову еру.\n\nСтарий Бог тремтить, {ім'я}. Так, він боїться твоєї віри. Розбий пророцтво К'Туна.\n\nВін знає, що ти прийдеш, {стать:чемпіоне:чемпіонко} — і з тобою прийде сила Калімдора. Ти лише маєш сказати мені, коли будеш {стать:готовий:готова}, і я дам тобі скіпетр Мінливих Пісків.", ["en"] = "The Might of Kalimdor" },
    [8743] = { [1] = "Бий в гонг!", [4] = "Гонг Скарабея зловісно звисає перед вами. Зберіться, {ім'я}, коли пролунає гонг Скарабея, ворота Ан'Кіражу відкриються.\n\nРоззявлена паща звіра може принести лише хаос і руйнування. Захистіть свій народ!", [5] = "Біля гонга із землі стирчить особливий кристал. Можливо, це подарунок від роду Ноздорму.", ["en"] = "Bang a Gong!", ["tasks"] = { ["The Scepter of the Shifting Sands"] = "скіпетр Мінливих Пісків", ["The Scepter of the Shifting Sands (Provided)"] = "скіпетр Мінливих Пісків (видано)" } },
    [8744] = { [1] = "Дбайливо упакований подарунок", [5] = "На записці, прикріпленій до цього подарунку написано:\n\n\"Для {ім'я},\n\nБажаю тобі щасливого свята Зимової Покрови!\"", ["en"] = "A Carefully Wrapped Present" },
    [87441] = { [1] = "Атієш, великий посох Вартівника", [2] = "Це останнє завдання буде найскладнішим з усіх, {ім'я}. Ти зустрівся та переміг як Старого Бога, так і Генерала Короля-Ліча, але тепер тобі доведеться зіткнутися з рукою Саргераса.\n\nВіднеси посох до Стратхольма. Саме там ти знайдеш шматок освяченої землі: землю, де були вбиті найвидатніші лицарі Лордерона. Поклади осквернений посох на святу землю та приготуйся до того, що сутність величезної сили вирветься зсередини... Переможи демонічну істоту, яка контролює посох, і повернися до мене.", [3] = "Анахронос з Печер Часу в Танарісі хоче, щоб ви віднесли Атієша, Великий посох Хранителя, до Стратхольма та використали його на Освяченій Землі. Переможіть сутність, яку вигнано з посоха, та поверніться до нього.", [4] = "Я не повинен втручатися, {раса}.", [5] = "Не можна недооцінювати масштаб цього досягнення, {ім'я}. Ви зробили те, що більшість вважала б неможливим. На жаль, це було призначено долею. Персонал зробив свій вибір...", ["en"] = "Atiesh, Greatstaff of the Guardian", ["tasks"] = { ["Atiesh, Greatstaff of the Guardian"] = "Атієш, великий посох Вартівника" } },
    [8745] = { [1] = "Скарб Позачасового", [5] = "Вітаю, {стать:чемпіоне:чемпіонко}. Я Джонатан, хранитель священного гонга і вічний вартовий бронзових драконів.\n\nСам Позачасовий уповноважив мене подарувати тобі один предмет на твій вибір з його вічної скарбниці. Нехай він допоможе тобі у битві з К'Туном.", ["en"] = "Treasure of the Timeless One" },
    [87459] = { [1] = "Червоні активності", [2] = "Хоча ми чемно поводимося з Червоно-червоними хрестоносцями тут, вони продовжують підозріло поводитися в інших місцях. Деякі з моїх контактів у Тірісфалі розповідають мені про зухвале вторгнення Червоно-червоного хрестоносця в саме серце Підмістя, і ми отримали повідомлення від наших розвідників про великі каравани, що перевозять припаси через Чумні землі. Загін елітних червоно-червоних сил помітили поблизу форпосту хрестоносців у Тірісфальських галявинах, між фермою Балнір та Долиною Отрути. Якщо хочете, сходіть і подивіться, що там можна знайти.", [3] = "Вирушайте до району поблизу форпосту хрестоносців на північний захід від Бастіона в Тірісфальських галявинах та досліджуйте його на наявність ознак нещодавньої активності Червоного хрестового походу. Будь-яку отриману інформацію поверніть Леоніду Варфаломію Шановному.", [4] = "Як проходить твоя місія, {ім'я}?", [5] = "Зрозуміло. Отже, схоже, Хрестовий похід викрав когось із міста, до того ж когось важливого. Це дуже непокоїть. Дякую, {ім'я}. Поки що нічого не робіть і нікому про це не кажіть. Наш союз з Багряним Хрестовим Походом нестійкий, але нам потрібна вся можлива допомога, щоб впоратися із загрозою Наксрамаса на даний момент.\n\nЯ самостійно розгляну це питання. Можливо, в майбутньому я звернуся до вас за додатковою допомогою. А поки що йдіть зі світлом.", ["en"] = "Scarlet Activities" },
    [8747] = { [1] = "Шлях захисника", [4] = "Вражає, маля. Ти {стать:доклав:доклала} багато зусиль, щоб здобути прихильність Бронзового крила. Ми не забудемо твою відданість.\n\nПерстень-печатка захисника забезпечить тобі надійний захист від сил зла.\n\nАле пам'ятай, що, обравши свій шлях, ти не зможеш змінити його.", [5] = "Вражає, маля. Ти {стать:доклав:доклала} багато зусиль, щоб здобути прихильність Бронзового крила. Ми не забудемо твою відданість.\n\nПерстень-печатка захисника забезпечить тобі надійний захист від сил зла.\n\nАле пам'ятай, що, обравши свій шлях, ти не зможеш змінити його.", ["en"] = "The Path of the Protector" },
    [8748] = { [1] = "Шлях захисника", [4] = "За постійний захист дітей Калімдору ти заслуговуєш на визнання. Віддай мені свій перстень-печатку, щоб я міг посилити його.", [5] = "Твої успіхи перед Родом Ноздорму вражають, {ім'я}. Бажаю тобі ніколи не звертати зі шляху захисника!", ["en"] = "The Path of the Protector", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [8749] = { [1] = "Шлях захисника", [4] = "Ти {стать:вшанував:вшанувала} мій рід, {ім'я}. Знищуй ворогів Калімдору! Покажи їм, що значить паплюжити землю вічного зоряного сяйва.\n\nТи {стать:заслужив:заслужила} ще одне покращення. Віддай мені свій перстень-печатку, щоб я міг посилити його.", [5] = "Твої успіхи перед Родом Ноздорму вражають, {ім'я}. Бажаю тобі ніколи не звертати зі шляху захисника!", ["en"] = "The Path of the Protector", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [87493] = { [1] = "Заворушення від руки Тіра", [2] = "Цікавий розвиток подій, {ім'я}. Схоже, що хоча основна увага Багряного Хрестового Походу була зосереджена на Накшрамасі, у лавах Руки Тіра виникли певні заворушення. Поки що деталі нечіткі, але, наскільки нам відомо, серед хрестоносців відбуваються деякі внутрішні чвари.\n\nЯ хотів би відправити вас до табору на захід від Руки Тіра, щоб ви оцінили ситуацію. Повідомте нам про свої знахідки якомога швидше.", [3] = "Розвідайте Базовий табір Червоного кольору на захід від Руки Тіра у Східних Чумних землях та спробуйте з'ясувати, що там відбувається з силами Червоного Хрестового Походу.", [5] = "Вітаю, {ім'я}. Радий знову тебе бачити. Однак, хотілося б, щоб обставини були кращими.", ["en"] = "Unrest at Tyr's Hand" },
    [87497] = { [1] = "Розкол", [2] = "Я одразу перейду до суті: анклав Рука Тіра більше не під нашим контролем. Поки ми були в Наксрамасі, з міста Стратгольм прибули ворожі хрестоносці та захопили фортецю. Нам заборонили в'їзд, і жодні посланці, яких ми відправляємо, не повертаються.\n\nМені не хочеться просити про зовнішню допомогу, але щось дуже не так, і я не знаю, чи зможемо ми повернути анклав самотужки.", [3] = "Поговоріть з Беатрікс, щоб дізнатися більше про ситуацію в Багряному Анклаві в Руці Тіра, і доповістіть Леоніду Варфаломію Шанованому в Каплиці Надії Світла, як тільки дізнаєтеся більше про те, що відбувається.", [4] = "Чого ви навчилися?", [5] = "Події в Руці Тіра... безперечно цікаві. Аббендіс, ймовірно, мертвий, Бальназзар повернувся. Хоча частина мене воліла б сидіти склавши руки та спостерігати, як Багряний Хрестовий Похід пожинає те, що посіяв, я відчуваю, що незалежно від результату, Срібний Світанок, ймовірно, буде втягнутий у конфлікт. Ослаблені після кампанії в Наксрамасі, лорд Тіросус волів би, щоб наша участь відбувалася на наших умовах, а не була примусовою.\n\nТакож... ви казали, що там був інквізитор Калдоран?", ["en"] = "The Schism" },
    [87498] = { [1] = "Багряне Відродження", [2] = "<Вираз обличчя Леоніда похмурнішає, коли ви підтверджуєте присутність Калдорана в Базовому таборі Багряного. За мить він знову опанував себе.>\n\nДякую... дякую, {ім'я}. Поки що продовжуйте допомагати Беатрікс, якщо хочете. Я порадитися з лордом Тіросусом і розроблю непередбачувані заходи, якщо Срібному Світанку доведеться безпосередньо втрутитися. Молюся, щоб ситуація не була такою жахливою, як нас змусили вважати, але якщо нам доведеться втрутитися та покласти цьому край, ми будемо готові.", [3] = "Поверніться до командир Беатрікс у Базовий табір Багряного кольору на захід від Руки Тіра.", [5] = "Тож ви нам допоможете? Зізнаюся, я відчуваю полегшення. Я особисто бачив ваші можливості та можливості ваших союзників і радий, що ви на нашому боці. Я сподівався, що Срібний Світанок надасть свою допомогу безпосередньо, але я все ж вдячний за вашу підтримку.\n\nПоговоріть з інквізитором Калдораном на сусідньому пагорбі. Він може допомогти вам розпочати.", ["en"] = "The Scarlet Reclamation" },
    [8750] = { [1] = "Шлях захисника", [4] = "Така відданість є рідкістю. Ти {стать:показав:показала}, що твоя воля непохитна, {ім'я}. Ти будеш {стать:винагороджений:винагороджена} за свій відважну охорону нашого світу.\n\nВіддай мені свій перстень-печатку, щоб я міг посилити його чари.", [5] = "Твої успіхи перед Родом Ноздорму вражають, {ім'я}. Бажаю тобі ніколи не звертати зі шляху захисника!", ["en"] = "The Path of the Protector", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [87502] = { [1] = "Збір розвідувальних даних", [2] = "Мені не приємно звертатися до вас за допомогою. Ви спілкуєтеся з єретиками та нечистими, і це нижче моїх гідностей та рівня нашого священного ордену приймати вашу присутність тут. Однак... ви здається досить здібним і станете корисним інструментом тут для наших потреб.\n\nІдіть до Руки Тіра та розвідайте тамтешній собор, перш ніж рухатися глибше в Новий Авалон, щоб розвідати задню фортецю та вежу магів. Повертайтеся сюди без зволікання та повідомляйте про те, що ви знайдете. Нам потрібно знати, з чим ми маємо справу.", [3] = "Увійдіть до Руки Тіра у Східних Чумних Землях та розвідайте центральний собор, а також вежу магів, і тримайтеся всередині Нового Авалону, перш ніж повернутися до Калдорана в Базовий Табір Багряного.\n\nПряме вторгнення можливе, але може бути небезпечним. Поговоріть з інквізитором Джосіфіною в Базовому Таборі Багряного, якщо ви віддаєте перевагу більш тонкому підходу.", [4] = "Ти виконав свою місію? Якщо ні, то чому ти стоїш тут і бездіяльно розмовляєш зі мною?", [5] = "<Калдоран різко бурчить на тебе, коли ти закінчуєш звітувати.>\n\nНарощування сил у Новому Авалоні викликає занепокоєння, але їхня кількість не є нездоланною.\n\nТакож здається, що Датрохан – або, мабуть, Балназар – зміцнює свою владу в центральному соборі, і його використання нечистої магії для закриття входу підтверджує, що він щось там задумав. Цей монстр оскверняє нашу святу землю, і я побачу його мертвим від власної руки. Клянусь своїм життям.", ["en"] = "Gathering Intelligence" },
    [87506] = { [1] = "Ослаблення захисту", [2] = "Поки тебе не було, ми завершили розробку наших планів атаки на Руку Тіра. Ми здійснимо фронтальну атаку, а також фланговий удар, який я особисто очолю. Перш ніж ми повністю розпочнемо атаку, нам потрібно буде послабити передову оборону. Я відправляю тебе назад до Руки Тіра, щоб ти знищив якомога більше ворожих командирів облоги, оскільки вони є ключовими організаторами оборони анклаву.\n\nЯ йду, щоб приєднатися до своїх сил на нашій позиції. Ти доповіш командиру Беатрікс, коли повернешся.\n\nНе зазнай невдачі.", [3] = "Увійдіть до Руки Тіра у Східних Чумних Землях, убийте трьох Командирів Багряної Облоги.", [4] = "Чи успішно ви виконали свою місію?", [5] = "Калдоран та його охорона надіслали сигнал про те, що вони на позиції та готові підтримати пряму атаку.\n\nПоки вас не було, посланець Срібного Світанку прибув, щоб доставити повідомлення, а потім швидко відійшов. Схоже, що в Каплиці Надії Світла виникли проблеми, і ви терміново потрібні туди. Я не можу просити вас ні про що більше, оскільки ви вже були безцінними в цій справі. Дякую за вашу допомогу, {ім'я}. Ми готові як ніколи.", ["en"] = "Weakening The Defenses" },
    [87508] = { [1] = "Звіт лорду Тиросусу", [2] = "Будь ласка, {ім'я}, щойно прибув посланець. Ви повинні якомога швидше повернутися до каплиці Світлої Надії! На нас напали, і лорд Максвелл Тіросус негайно запросив вашу присутність.", [3] = "Поговоріть з лордом Максвеллом Тіросусом у каплиці Надії Світла у Східних Чумних землях.", [5] = "На нас напали! Якась драконоподібна... гидота швидко прилетіла з боку Багряного Анклаву та сильно вдарила нас. Я бачив драконів раніше, але ніколи не бачив нічого подібного.\n\nНайдивніше те, що дракон просто... зник. Він вдарив нас одним жахливим пострілом, а потім просто полетів. Це, безперечно, благословення, але це дуже тривожно. Нас застали абсолютно несподіваними. Він міг завдати величезної шкоди, але, здається, вирішив цього не робити.", ["en"] = "Report to Lord Tyrosus" },
    [87509] = { [1] = "Гнів світанку", [2] = "Незалежно від причини, чому цей звір відступив назад до анклаву, ми не дамо йому ще одного шансу знищити нас. Здається, ми змушені, і тепер ми повинні присвятити всю лють Срібного Світанку справі подолання загрози з боку Багряного Анклаву.\n\nПоверніться до Базового Табору Багряного та зустріньтесь із Беатрікс. Дайте їй знати, що вона має нашу підтримку... поки що.", [3] = "Зверніться до командир Беатрікс у Базовий табір Багряного кольору у Східних Чумних землях та приготуйтеся повернути Багряний Анклав.", [4] = "Я бачив дим, що піднімався з боку Світлої Надії, що сталося?", [5] = "Якийсь звір напав на Надію Світла? Це сміливо з боку Бальназара. Занадто сміливо, адже тепер Срібний Світанок присвятив себе нашій справі. Не буду вам брехати і скажу, що я не відчуваю полегшення від їхньої допомоги. Не думаю, що ми можемо захопити анклав силами, які маємо зараз у нашому розпорядженні.\n\nМи зараз у ендшпілі, {клас}. Підготуйте свої сили.", ["en"] = "The Wrath of the Dawn" },
    [8751] = { [1] = "Захисник Калімдору", [4] = "Ніколи ще я не бачив такої наполегливості! Бронзове крило надає тобі останні чари. Сам Позачасовий так велів!\n\nВіддай мені свій перстень-печатку, щоб я міг внести необхідні доповнення.", [5] = "Хвала тобі, {стать:Великий Захиснику:Велика Захиснице}! Велика тобі хвала!", ["en"] = "The Protector of Kalimdor", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [87516] = { [1] = "Страйк обезголовлення", [2] = "Наші сили зібрані, і ми займемо позиції для початку наступу, поки ваші сили прокрадуться до тилу собору гірською стежкою.\n\nЯк тільки ви потрапите всередину, проберіться до абатства та подзвоніть у дзвін, щоб сповістити про атаку.\n\nВи будете в найгучнішому бою, поки ми не прийдемо на заміну, тож будьте обережні.", [3] = "Увійдіть до Багряного Анклаву гірською стежкою та вступіть у бій із захисниками Руки Тіра. Подзвоніть у дзвін всередині абатства, щоб створити плутанину та дати сигнал силам Беатрікс до атаки.\n\nЯк тільки продзвенить дзвін, протистояйте Бальназару та знищіть його.", [4] = "Це була майже повна катастрофа...", [5] = "Нас зрадили! Після падіння Бальназара, Беатрікс взяла під контроль захисників без лідера та негайно повернула проти нас свої щойно посилені сили! Втрати були важкими, але ми завдали сильного удару та змогли відступити й перегрупуватися. Ми боялися найгіршого для ваших сил, поки наші розвідники не повідомили про вашу присутність.\n\nЯ не знаю, що задумали Беатрікс і Калдоран, але на даний момент я готовий придушити будь-кого, кого побачу в червоному, і залишити світло розбиратися з ними.", ["en"] = "Decapitation Strike" },
    [87517] = { [1] = "Червоний = Мертвий", [2] = "Схоже, що звір, який напав на Надію Світла, є улюбленцем Калдорана, а напад на Надію Світла був лише хитрощами, щоб виманити наші сили та залучити нас до цієї атаки. Калдоран і Беатрікс прагнули використати нас, щоб відвернути увагу та усунути суперника в особі Балназара, а потім, після того, як вони відновлять контроль, звернутися проти нас і усунути нашу присутність у Чумних землях.\n\nУ нас немає всіх відповідей, і ситуація виглядає похмуро, але ми знищимо цих собак за цю зраду.", [4] = "Що ж, заради всього святого, робив Багряний Хрестовий Похід за цими стінами?", [5] = "Те, що ми тут відкрили, виходить за межі дозволеного. Нова чума? Світлоподібний дракон? Висмоктування душ благочестивих, щоб живити їхню світлову зброю? Таке зловживання світлом викликає нудоту, і мені страшно подумати, яку ще силу може мати Калдоран у своєму розпорядженні. Те, як він знищив Бальназара, говорить мені, що він щось задумав. Така сильна сила перевершує навіть найсильніших паладинів.\n\nУсе одно, це закінчується. Пощади не буде. Ці звірства не спокутувати.", ["en"] = "Red = Dead" },
    [87518] = { [1] = "Падіння Великого хрестоносця", [2] = "Шлях уперед простий і жорстокий. Прорвіться у святилище Багряного Анклаву та протистояти новому самопроголошеному «Великому хрестоносцю» Баеліну Калдорану. Притягніть його до відповідальності за його злочини. Ми залишимося тут і забезпечимо цю позицію, щоб жодні залишки сил не переслідували вас ззаду.\n\nПритягніть цього монстра до відповідальності.", [5] = "Калдорану більше немає, але перемога гірко-солодка. Це був кривавий день. З розпорошеними залишками сил Червоного Хрестового Походу та полум'ям Червоного Анклаву, ми зробили тут велику справу. У Чумних Землях ще багато роботи, але принаймні у нас зараз на одного супротивника менше, про якого треба турбуватися. Як на мене, це привід для святкування.\n\nЗа Світло! За Лордерон! За Світанок!", ["en"] = "Fall of the Grand Crusader" },
    [8752] = { [1] = "Шлях завойовника", [4] = "Вражає, маля. Ти {стать:доклав:доклала} багато зусиль, щоб здобути прихильність Бронзового крила. Ми не забудемо твою відданість.\n\nПерстень-печатка завойовника значно посилить твої удари.\n\nАле пам'ятай, що, обравши свій шлях, ти не зможеш змінити його.", [5] = "Вражає, маля. Ти {стать:доклав:доклала} багато зусиль, щоб здобути прихильність Бронзового крила. Ми не забудемо твою відданість.\n\nПерстень-печатка завойовника значно посилить твої удари.\n\nАле пам'ятай, що, обравши свій шлях, ти не зможеш змінити його.", ["en"] = "The Path of the Conqueror" },
    [87520] = { [1] = "Антитеза Світла", [2] = "Гладкий чорний артефакт перед вами зловісно пульсує. Здається, що цей об'єкт ніби втягує та поглинає все світло навколо. Ваша інтуїція підказує, що цей об'єкт небезпечний, і що торкатися його голими руками було б нерозумно.\n\nВи загортаєте предмет у тканину та ховаєте його в рюкзак. Лорд Максвелл Тіросус з каплиці Надії Світла може бути зацікавлений у цьому.", ["en"] = "Antithesis of the Light" },
    [8753] = { [1] = "Шлях завойовника", [4] = "За постійний захист дітей Калімдору ти заслуговуєш на визнання. Віддай мені свій перстень-печатку, щоб я міг посилити його.", [5] = "Твої успіхи перед Родом Ноздорму вражають, {ім'я}. Бажаю тобі ніколи не звертати зі шляху завойовника!", ["en"] = "The Path of the Conqueror", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [8754] = { [1] = "Шлях завойовника", [4] = "Ти {стать:вшанував:вшанувала} мій рід, {ім'я}. Знищуй ворогів Калімдору! Покажи їм, що значить паплюжити землю вічного зоряного сяйва.\n\nТи {стать:заслужив:заслужила} ще одне покращення. Віддай мені свій перстень-печатку, щоб я міг посилити його.", [5] = "Твої успіхи перед Родом Ноздорму вражають, {ім'я}. Бажаю тобі ніколи не звертати зі шляху завойовника!", ["en"] = "The Path of the Conqueror", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [8755] = { [1] = "Шлях завойовника", [4] = "Така відданість є рідкістю. Ти {стать:показав:показала}, що твоя воля непохитна, {ім'я}. Ти будеш {стать:винагороджений:винагороджена} за свій відважну охорону нашого світу.\n\nВіддай мені свій перстень-печатку, щоб я міг посилити його чари.", [5] = "Твої успіхи перед Родом Ноздорму вражають, {ім'я}. Бажаю тобі ніколи не звертати зі шляху завойовника!", ["en"] = "The Path of the Conqueror", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [8756] = { [1] = "Завойовник кіражі", [4] = "Ніколи ще я не бачив такої наполегливості! Бронзове крило надає тобі останні чари. Сам Позачасовий так велів!\n\nВіддай мені свій перстень-печатку, щоб я міг внести необхідні доповнення.", [5] = "Хвала тобі, {стать:Завойовнику:Завойовнице} кіражі! Велика тобі хвала!", ["en"] = "The Qiraji Conqueror", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [8757] = { [1] = "Шлях заклинателя", [4] = "Вражає, маля. Ти {стать:доклав:доклала} багато зусиль, щоб здобути прихильність Бронзового крила. Ми не забудемо твою відданість.\n\nПерстень-печатка заклинателя значно посилить твої магічні та природні здібності.\n\nАле пам'ятай, що, обравши свій шлях, ти не зможеш змінити його.", [5] = "Вражає, маля. Ти {стать:доклав:доклала} багато зусиль, щоб здобути прихильність Бронзового крила. Ми не забудемо твою відданість.\n\nПерстень-печатка заклинателя значно посилить твої магічні та природні здібності.\n\nАле пам'ятай, що, обравши свій шлях, ти не зможеш змінити його.", ["en"] = "The Path of the Invoker" },
    [8758] = { [1] = "Шлях заклинателя", [4] = "За постійний захист дітей Калімдору ти заслуговуєш на визнання. Віддай мені свій перстень-печатку, щоб я міг посилити його.", [5] = "Твої успіхи перед Родом Ноздорму вражають, {ім'я}. Бажаю тобі ніколи не звертати зі шляху заклинателя!", ["en"] = "The Path of the Invoker", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [8759] = { [1] = "Шлях заклинателя", [4] = "Ти {стать:вшанував:вшанувала} мій рід, {ім'я}. Знищуй ворогів Калімдору! Покажи їм, що значить паплюжити землю вічного зоряного сяйва.\n\nТи {стать:заслужив:заслужила} ще одне покращення. Віддай мені свій перстень-печатку, щоб я міг посилити його.", [5] = "Твої успіхи перед Родом Ноздорму вражають, {ім'я}. Бажаю тобі ніколи не звертати зі шляху заклинателя!", ["en"] = "The Path of the Invoker", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [8760] = { [1] = "Шлях заклинателя", [4] = "Така відданість є рідкістю. Ти {стать:показав:показала}, що твоя воля непохитна, {ім'я}. Ти будеш {стать:винагороджений:винагороджена} за свій відважну охорону нашого світу.\n\nВіддай мені свій перстень-печатку, щоб я міг посилити його чари.", [5] = "Твої успіхи перед Родом Ноздорму вражають, {ім'я}. Бажаю тобі ніколи не звертати зі шляху заклинателя!", ["en"] = "The Path of the Invoker", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [8761] = { [1] = "Великий заклинатель", [4] = "Ніколи ще я не бачив такої наполегливості! Бронзове крило надає тобі останні чари. Сам Позачасовий так велів!\n\nВіддай мені свій перстень-печатку, щоб я міг внести необхідні доповнення.", [5] = "Хвала тобі, {стать:Великий Заклинателю:Велика Заклинателько}! Велика тобі хвала!", ["en"] = "The Grand Invoker", ["tasks"] = { ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [8764] = { [1] = "Зміна шляху — більше не захисник", [4] = "{стать:Чемпіоне:Чемпіонко}, якщо ти {стать:вирішив:вирішила} обрати інший шлях, віддай мені свій перстень-печатку та купу жуків-скарабеїв наших ворогів з Ан'Кіражу.", [5] = "Бувай, {ім'я}. Якщо ти передумаєш, я буду тут, щоб допомогти тобі.", ["en"] = "The Changing of Paths - Protector No More", ["tasks"] = { ["Gold Scarab"] = "золотий скарабей", ["Gold Scarab (Provided)"] = "золотий скарабей (видано)", ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)", ["Silver Scarab"] = "срібний скарабей", ["Silver Scarab (Provided)"] = "срібний скарабей (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8765] = { [1] = "Зміна шляху — більше не заклинатель", [4] = "{стать:Чемпіоне:Чемпіонко}, якщо ти {стать:вирішив:вирішила} обрати інший шлях, віддай мені свій перстень-печатку та купу жуків-скарабеїв наших ворогів з Ан'Кіражу.", [5] = "Бувай, {ім'я}. Якщо ти передумаєш, я буду тут, щоб допомогти тобі.", ["en"] = "The Changing of Paths - Invoker No More", ["tasks"] = { ["Bronze Scarab"] = "бронзовий скарабей", ["Bronze Scarab (Provided)"] = "бронзовий скарабей (видано)", ["Clay Scarab"] = "глиняний скарабей", ["Clay Scarab (Provided)"] = "глиняний скарабей (видано)", ["Crystal Scarab"] = "кришталевий скарабей", ["Crystal Scarab (Provided)"] = "кришталевий скарабей (видано)", ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)" } },
    [8766] = { [1] = "Зміна шляху — більше не завойовник", [4] = "{стать:Чемпіоне:Чемпіонко}, якщо ти {стать:вирішив:вирішила} обрати інший шлях, віддай мені свій перстень-печатку та купу жуків-скарабеїв наших ворогів з Ан'Кіражу.", [5] = "Бувай, {ім'я}. Якщо ти передумаєш, я буду тут, щоб допомогти тобі.", ["en"] = "The Changing of Paths - Conqueror No More", ["tasks"] = { ["Bone Scarab"] = "кістяний скарабей", ["Bone Scarab (Provided)"] = "кістяний скарабей (видано)", ["Ivory Scarab"] = "скарабей зі слонової кістки", ["Ivory Scarab (Provided)"] = "скарабей зі слонової кістки (видано)", ["Signet Ring of the Bronze Dragonflight"] = "перстень-печатка бронзових драконів", ["Signet Ring of the Bronze Dragonflight (Provided)"] = "перстень-печатка бронзових драконів (видано)", ["Stone Scarab"] = "кам'яний скарабей", ["Stone Scarab (Provided)"] = "кам'яний скарабей (видано)" } },
    [8767] = { [1] = "Злегка розтрушений подарунок", [5] = "Цей подарунок виглядає так, ніби його кілька разів потрясли. У записці сказано:\n\n{стать:Особливому:Особливій} {раса:д}-{клас:д}.", ["en"] = "A Gently Shaken Gift" },
    [8768] = { [1] = "Подарунок в яскравій обгортці", [5] = "На цьому святково загорнутому подарунку вказано ваше ім'я.\n\nЗачекайте, він щойно ворухнувся?", ["en"] = "A Gaily Wrapped Present" },
    [8769] = { [1] = "Подарунок, що цокає", [5] = "Привітання зі святом Зимової Покрови від ваших друзів з Пасовищ Димного Лісу.", ["en"] = "A Ticking Present" },
    [8770] = { [1] = "Ціль: захисники Вул'Аші", [2] = "У міру розростання конфлікту, силітиди в цьому районі становлять дедалі більшу загрозу для наших операцій. Тебе обрали для участі у штурмі Вул'Аші, а твоєю головною ціллю будуть захисники Вул'Аші.\n\nПро виконання завдання прозвітуй командиру Мар'аліту.", [3] = "Вбийте 30 захисників Вул'Аші та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання I.", [4] = "Ти маєш, про що мені доповісти, {клас:к}?", [5] = "Відмінна робота, {ім'я}. Твоя старанність, як завжди, заслуговує на подяку.", ["en"] = "Target: Hive'Ashi Defenders", ["tasks"] = { ["Combat Task Briefing I"] = "план бойового завдання I", ["Combat Task Briefing I (Provided)"] = "план бойового завдання I (видано)", ["Hive'Ashi Defender"] = "захисник Вул'Аші", ["Hive'Ashi Defender slain"] = "захисник Вул'Аші: убито" } },
    [8771] = { [1] = "Ціль: піщані ловці Вул'Аші", [2] = "У міру розростання конфлікту, силітиди в цьому районі становлять дедалі більшу загрозу для наших операцій. Тебе обрали для участі у штурмі Вул'Аші, а твоєю головною ціллю будуть піщані ловці Вул'Аші.\n\nПро виконання завдання прозвітуй командиру Мар'аліту.", [3] = "Вбийте 30 піщаних ловців Вул'Аші та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання II.", [4] = "Ти маєш, про що мені доповісти, {клас:к}?", [5] = "Чудова робота, {ім'я}. Ми врахуємо твою участь у нападі на Вул'Аші.", ["en"] = "Target: Hive'Ashi Sandstalkers", ["tasks"] = { ["Combat Task Briefing II"] = "план бойового завдання II", ["Combat Task Briefing II (Provided)"] = "план бойового завдання II (видано)", ["Hive'Ashi Sandstalker"] = "піщаний ловець Вул'Аші", ["Hive'Ashi Sandstalker slain"] = "піщаний ловець Вул'Аші: убито" } },
    [8772] = { [1] = "Ціль: шляхостражі Вул'Зори", [2] = "Ми викликали підкріплення для штурму Вул'Зори. Твоє завдання — вбити якомога більше шляхостражів Вул'Зори. Коли виконаєш завдання, прозвітуй про це командиру Мар'аліту.", [3] = "Вбийте 30 шляхостражів Вул'Зори та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання VI.", [4] = "Ти маєш, про що мені доповісти, {клас:к}?", [5] = "Чудова робота, {ім'я}. Ми врахуємо твою участь у нападі на Вул'Зору.", ["en"] = "Target: Hive'Zora Waywatchers", ["tasks"] = { ["Combat Task Briefing VI"] = "план бойового завдання VI", ["Combat Task Briefing VI (Provided)"] = "план бойового завдання VI (видано)", ["Hive'Zora Waywatcher"] = "шляхостраж Вул'Зори", ["Hive'Zora Waywatcher slain"] = "шляхостраж Вул'Зори: убито" } },
    [8773] = { [1] = "Ціль: розорителі Вул'Зори", [2] = "Ми викликали підкріплення для штурму Вул'Зори. Твоє завдання — вбити якомога більше розорителів Вул'Зори. Коли виконаєш завдання, прозвітуй про це командиру Мар'аліту.", [3] = "Вбийте 30 розорителів Вул'Зори та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання IV.", [4] = "Ти маєш, про що мені доповісти, {клас:к}?", [5] = "Я чув багато хорошого про твою участь у нападі на Вул'Зору. Продовжуй в тому ж дусі й незабаром ми переможемо.", ["en"] = "Target: Hive'Zora Reavers", ["tasks"] = { ["Combat Task Briefing IV"] = "план бойового завдання IV", ["Combat Task Briefing IV (Provided)"] = "план бойового завдання IV (видано)", ["Hive'Zora Reaver"] = "розоритель Вул'Зори", ["Hive'Zora Reaver slain"] = "розоритель Вул'Зори: убито" } },
    [8774] = { [1] = "Ціль: душителі Вул'Регаля", [2] = "У міру розростання конфлікту, силітиди в цьому районі становлять дедалі більшу загрозу для наших операцій. Тебе обрали для участі у штурмі Вул'Регаля, а твоєю головною ціллю будуть душителі Вул'Регаля.\n\nПро виконання завдання прозвітуй командиру Мар'аліту.", [3] = "Вбийте 30 душителів Вул'Регаля та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання VIII.", [4] = "Ти хочеш щось мені сказати, {ім'я}?", [5] = "Чудова робота, {ім'я}. Ми врахуємо твою участь у нападі на Вул'Регаль.", ["en"] = "Target: Hive'Regal Ambushers", ["tasks"] = { ["Combat Task Briefing VIII"] = "план бойового завдання VIII", ["Combat Task Briefing VIII (Provided)"] = "план бойового завдання VIII (видано)", ["Hive'Regal Ambusher"] = "душитель Вул'Регаля", ["Hive'Regal Ambusher slain"] = "душитель Вул'Регаля: убито" } },
    [8775] = { [1] = "Ціль: вогнеплюї Вул'Регаля", [2] = "У міру розростання конфлікту, силітиди в цьому районі становлять дедалі більшу загрозу для наших операцій. Тебе обрали для участі у штурмі Вул'Регаля, а твоєю головною ціллю будуть летючі вогнеплюї Вул'Регаля.\n\nПро виконання завдання прозвітуй командиру Мар'аліту.", [3] = "Вбийте 30 вогнеплюїв Вул'Регаля та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання IX.", [4] = "Ти хочеш щось мені сказати, {ім'я}?", [5] = "Чудова робота, {ім'я}. Ми врахуємо твій вклад в напад на Вул'Регаль.", ["en"] = "Target: Hive'Regal Spitfires", ["tasks"] = { ["Combat Task Briefing IX"] = "план бойового завдання IX", ["Combat Task Briefing IX (Provided)"] = "план бойового завдання IX (видано)", ["Hive'Regal Spitfire"] = "вогнеплюй Вул'Регаля", ["Hive'Regal Spitfire slain"] = "вогнеплюй Вул'Регаля: убито" } },
    [8776] = { [1] = "Ціль: поневолювачі Вул'Регаля", [2] = "У міру розростання конфлікту, силітиди в цьому районі становлять дедалі більшу загрозу для наших операцій. Тебе обрали для участі у штурмі Вул'Регаля, а твоєю головною ціллю будуть поневолювачі Вул'Регаля.\n\nПро виконання завдання прозвітуй командиру Мар'аліту.", [3] = "Вбийте 30 поневолювачів Вул'Регаля та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання X.", [4] = "Ти щось хочеш мені сказати, {ім'я}?", [5] = "Чудова робота, {ім'я}. Ми врахуємо твій вклад в напад на Вул'Регаль.", ["en"] = "Target: Hive'Regal Slavemakers", ["tasks"] = { ["Combat Task Briefing X"] = "план бойового завдання X", ["Combat Task Briefing X (Provided)"] = "план бойового завдання X (видано)", ["Hive'Regal Slavemaker"] = "поневолювач Вул'Регаля", ["Hive'Regal Slavemaker slain"] = "поневолювач Вул'Регаля: убито" } },
    [87760] = { [1] = "Святий Дайвер", [2] = "Я отримав звістку з Дарнасу, {ім'я}!\n\nЗі зразків тварин ми дізналися, що наги домінували над цими морськими істотами, щоб використовувати їх як неохочих верхових тварин та в'ючних тварин. Тих, хто був надто впертим, надто старим або важко пораненим, вони виганяли заради розваги. Жах!\n\nЦе наш священний обов'язок покласти цьому край!\n\nНаги мають сили в Руїнах Матістри, і вони, мабуть, захоплюють молотарки з берега. Знайдіть їхню господиню-звірів, убийте її та поверніть її знаряддя панування!", [3] = "Знайдіть Володарку Звірів Штормової Луски, убийте її та поверніть її Жезл Глибокого Панування.", ["en"] = "Holy Diver", ["tasks"] = { ["Rod of Deep Dominion"] = "Жезл Глибокого Панування" } },
    [8777] = { [1] = "Ціль: землериї Вул'Регаля", [2] = "У міру розростання конфлікту, силітиди в цьому районі становлять дедалі більшу загрозу для наших операцій. Тебе обрали для участі у штурмі Вул'Регаля, а твоєю головною ціллю будуть землекопи Вул'Регаля.\n\nПро виконання завдання прозвітуй командиру Мар'аліту.", [3] = "Вбийте 30 землекопів Вул'Регаля та повідомте про це командира Мар'аліта з Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план бойового завдання XI.", [4] = "Ти хочеш щось мені сказати, {ім'я}?", [5] = "Чудова робота, {ім'я}. Ми врахуємо твій вклад в напад на Вул'Регаль.", ["en"] = "Target: Hive'Regal Burrowers", ["tasks"] = { ["Combat Task Briefing XI"] = "план бойового завдання XI", ["Combat Task Briefing XI (Provided)"] = "план бойового завдання XI (видано)", ["Hive'Regal Burrower"] = "землерий Вул'Регаля", ["Hive'Regal Burrower slain"] = "землерий Вул'Регаля: убито" } },
    [8778] = { [1] = "Бригаді Залізогарта потрібна вибухівка!", [2] = "Бригада Залізогарта подала незвичайний запит на дуже... нестабільні... компоненти. Збери їх і принеси пану Форсунопружу з бригади Залізогарта.", [3] = "Принесіть 6 пляшок олії жертвоприношення, 5 бочок гоблінського ракетного палива та 10 порцій масивного вибухового порошку арканісту Форсунопружу біля Вул'Зори, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання IV.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "О, так! Ці штуки нам знадобляться! Дуже дякую, {ім'я}!", ["en"] = "The Ironforge Brigade Needs Explosives!", ["tasks"] = { ["Dense Blasting Powder"] = "масивний вибуховий порошок", ["Dense Blasting Powder (Provided)"] = "масивний вибуховий порошок (видано)", ["Goblin Rocket Fuel"] = "гоблінське ракетне паливо", ["Goblin Rocket Fuel (Provided)"] = "гоблінське ракетне паливо (видано)", ["Logistics Task Briefing IV"] = "план логістичного завдання IV", ["Logistics Task Briefing IV (Provided)"] = "план логістичного завдання IV (видано)", ["Oil of Immolation"] = "олія жертвоприношення", ["Oil of Immolation (Provided)"] = "олія жертвоприношення (видано)" } },
    [8784] = { [1] = "Секрети кіражів", [2] = "Ви знайшли древній кіразький артефакт! Можливо, один з драконів, що стоять біля входу до храму, зможе знайти застосування цій реліквії.", [3] = "Віднесіть древній кіразький артефакт драконам, які ховаються біля входу до храму.", [4] = "Ти сяєш! Я знаю, що це значить...", [5] = "Виняткова знахідка, {ім'я}. Просто чудова! Це, безумовно, дозволить нам трохи зрозуміти схиблений розум наших ворогів.", ["en"] = "Secrets of the Qiraji", ["tasks"] = { ["Ancient Qiraji Artifact"] = "древній кіразький артефакт", ["Ancient Qiraji Artifact (Provided)"] = "древній кіразький артефакт (видано)" } },
    [8786] = { [1] = "Бойова зброя", [2] = "Орґріммарський легіон подав запит на додаткову зброю, яку ми наразі не можемо надати. Дістань зброю, про яку вони просили й віднеси її Мероку Широкому Кроку, він знаходиться неподалік Вул'Регаля.", [3] = "Принесіть 3 масивні залізні сокири Мероку Широкому Кроку, що знаходиться неподалік Вул'Регаля. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання VI.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "Чудова робота, {ім'я}. Нам саме таких і не вистачало.", ["en"] = "Arms for the Field", ["tasks"] = { ["Logistics Task Briefing VI"] = "план логістичного завдання VI", ["Logistics Task Briefing VI (Provided)"] = "план логістичного завдання VI (видано)", ["Massive Iron Axe"] = "масивна залізна сокира", ["Massive Iron Axe (Provided)"] = "масивна залізна сокира (видано)" } },
    [8787] = { [1] = "Накладки для броні", [2] = "Відважні добровольці з Орґріммарського легіону прибули в Силітус, щоб допомогти нам. Вони загубили свої запаси накладок для броні по дорозі. Добудь партію накладок та віднеси їх Мероку Широкому Кроку в табір Орґріммарського легіону.", [3] = "Принесіть 8 накладок з міцної шкіри та 8 накладок з важкої шкіри Мероку Широкому Кроку, що знаходиться неподалік Вул'Регаля. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання VII.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "О, так... Я роздам це військовим, {ім'я}. Орґріммарський легіон дякує тобі!", ["en"] = "Armor Kits for the Field", ["tasks"] = { ["Heavy Armor Kit"] = "накладки з важкої шкіри", ["Heavy Armor Kit (Provided)"] = "накладки з важкої шкіри (видано)", ["Logistics Task Briefing VII"] = "план логістичного завдання VII", ["Logistics Task Briefing VII (Provided)"] = "план логістичного завдання VII (видано)", ["Rugged Armor Kit"] = "накладки з міцної шкіри", ["Rugged Armor Kit (Provided)"] = "накладки з міцної шкіри (видано)" } },
    [8788] = { [1] = "Злегка розтрушений подарунок", [5] = "Цей подарунок виглядає так, ніби його кілька разів потрясли. У записці сказано:\n\n{стать:Особливому:Особливій} {раса:д}-{клас:д}.", ["en"] = "A Gently Shaken Gift" },
    [8789] = { [1] = "Кіразька імператорська зброя", [2] = "Ми не сиділи склавши руки протягом тисячоліття, {ім'я:к}.\n\nМи спостерігали, як ці звірі пожирали одне одного та виснажували власні ресурси. Ми слухали їхні плани знищення нашого світу. І ми дізналися про зрадників у їхніх лавах.\n\nУ них є слабкості, і ми знаємо як використати їх на свою користь.\n\nЗнайди та принеси мені їхню церемоніальну зброю. У поєднанні з елементом, створеним мінливістю їхнього власного бога, вона стане силою нашої розплати.", [3] = "Ариґос у храмі Ан'Кіражу зробить для вас посилену елементієм зброю, якщо ви принесете йому кіразьку імператорську зброю та 3 шматки елементієвої руди.", [4] = "Знайди те, що мені потрібно, і ти станеш чимось більшим за {стать:звичайного:звичайну} {раса:з}, {стать:чемпіоне:чемпіонко}.", [5] = "Ця посилена елементієм зброя легко розріже навпіл як звичайних кіражів, так і їхнього бога.", ["en"] = "Imperial Qiraji Armaments", ["tasks"] = { ["Elementium Ore"] = "елементієва руда", ["Elementium Ore (Provided)"] = "елементієва руда (видано)", ["Imperial Qiraji Armaments"] = "кіразька імператорська зброя", ["Imperial Qiraji Armaments (Provided)"] = "кіразька імператорська зброя (видано)" } },
    [8790] = { [1] = "Кіразькі імператорські регалії", [2] = "Ариґос припускає, що елемент, народжений унаслідок конфліктів між Старими Богами та їхніми прислужниками, за певних умов також є надзвичайно смертельним для них самих. Я кажу про елементій, {стать:смертний:смертна}.\n\nЗнайди та принеси мені кіразькі імператорські регалії та цей отруйний елемент, і я створю зброю великої сили.", [3] = "Мерітра зі Сну в храмі Ан'Кіражу зробить для вас посилену елементієм зброю, якщо ви принесете їй кіразькі імператорські регалії та 3 шматки елементієвої руди.", [4] = "Ти знищиш їх та звільниш нас від кайданів.", [5] = "Користуйся цим з розумом, {ім'я}. Нехай вони відчують біль, який вони так прагнуть заподіяти іншим.", ["en"] = "Imperial Qiraji Regalia", ["tasks"] = { ["Elementium Ore"] = "елементієва руда", ["Elementium Ore (Provided)"] = "елементієва руда (видано)", ["Imperial Qiraji Regalia"] = "кіразькі імператорські регалії", ["Imperial Qiraji Regalia (Provided)"] = "кіразькі імператорські регалії (видано)" } },
    [8791] = { [1] = "Падіння Оссіріана", [2] = "Зі страшною загрозою покінчено. Жорстокий Оссіріан переможений.\n\nМешканці Калімдору зрадіють, дізнавшись про цю перемогу. Візьміть голову Оссіріана та віддайте її командиру Мар'аліту з Кенарійської цитаделі.", [3] = "Віднесіть голову Оссіріана Невразливого до командира Мар'аліта в Кенарійську цитадель, що в Силітусі.", [4] = "О, {ім'я}, ти {стать:повернувся:повернулася}! І не по частинах, маю сказати. Яку звістку ти {стать:приніс:принесла} з Ан'кіража?", [5] = "Я висловлюю тобі мою найвищу похвалу, {ім'я}, а також пропоную обрати у винагороду могутній предмет. Ти {стать:зробив:зробила} жителям Калімдору велику послугу.", ["en"] = "The Fall of Ossirian", ["tasks"] = { ["Head of Ossirian the Unscarred"] = "голова Оссіріана Невразливого", ["Head of Ossirian the Unscarred (Provided)"] = "голова Оссіріана Невразливого (видано)" } },
    [8795] = { [1] = "Альянсу потрібна твоя допомога!", [2] = "Привіт, я радий, що ти {стать:вирішив:вирішила} мене вислухати. Альянсу потрібна допомога, щоб підготуватися до війни в Ан'Кіражі, і це означає, що нам {стать:потрібен:потрібна} ти! Навіть зараз, поки ми з тобою базікаємо, наші інтенданти збирають всі ресурси, які знадобляться для майбутньої війни. Але ми не зможемо досягти мети без твоєї допомоги, {ім'я}!\n\nТи маєш піти поговорити з нашим керівником — фельдмаршалом Снігопадом. Що скажеш, {клас:к}? Допоможеш нам з підготовкою?", [3] = "Поговоріть з фельдмаршалом Снігопадом у Військовій палаті Залізогарта.", [5] = "Вітаю тебе, {стать:хлопче:дівчино}! Радий бачити, що стільки народу з Альянсу, як ти, {ім'я}, приходять сюди, щоб допомогти у підготовці до війни в Ан'Кіражі. Докладені зусилля гарантуватимуть нашу перемогу у війні проти силітидів та їхніх злих господарів, що сховалися в глибинах Ан'Кіража.\n\nОскільки ти вже тут, то обов'язково поговори з різними збирачами ресурсів та запропонуй їм допомогу.", ["en"] = "The Alliance Needs Your Help!" },
    [8796] = { [1] = "Альянсу потрібна твоя допомога!", [2] = "Привіт, я рада, що ти {стать:вирішив:вирішила} мене вислухати. Альянсу потрібна допомога, щоб підготуватися до війни в Ан'Кіражі, і це означає, що нам {стать:потрібен:потрібна} ти! Навіть зараз, поки ми з тобою базікаємо, наші інтенданти збирають всі ресурси, які знадобляться для майбутньої війни. Але ми не зможемо досягти мети без твоєї допомоги, {ім'я}!\n\nТи маєш піти поговорити з нашим керівником — фельдмаршалом Снігопадом. Що скажеш, {клас:к}? Допоможеш нам з підготовкою?", [3] = "Поговоріть з фельдмаршалом Снігопадом у Військовій палаті Залізогарта.", [5] = "Вітаю тебе, {стать:хлопче:дівчино}! Радий бачити, що стільки народу з Альянсу, як ти, {ім'я}, приходять сюди, щоб допомогти у підготовці до війни в Ан'Кіражі. Докладені зусилля гарантуватимуть нашу перемогу у війні проти силітидів та їхніх злих господарів, що сховалися в глибинах Ан'Кіража.\n\nОскільки ти вже тут, то обов'язково поговори з різними збирачами ресурсів та запропонуй їм допомогу.", ["en"] = "The Alliance Needs Your Help!" },
    [8798] = { [1] = "Твій власний єті", [5] = "Слухай! Знаєш, що?! Ти ж теж {стать:інженер:інженерка}! Тож, оскільки ти {стать:допоміг:допомогла} мені провчити моїх друзів, я навчу тебе, як зробити власного механічного єті! Тепер веселощі можуть тривати нескінченно, і ти зможеш лякати кого завгодно! За умови, що ти зможеш зібрати необхідні для нього компоненти.\n\nЩо скажеш, {ім'я}? Хочеш дізнатися секрет виготовлення механічного єті?", ["en"] = "A Yeti of Your Own" },
    [8800] = { [1] = "Кенарійське спорядження", [2] = "Коли ти виконаєш усі свої завдання, поговори з ковалем Варґусом. Покажи йому всі зароблені на відзнаки. Він забезпечить тебе спорядженням, що відповідатиме твоєму рівню відданості нашій справі.", [3] = "Поговоріть з Варґусом у Кенарійській цитаделі, що в Силітусі.", [5] = "Тебе Калдон прислав? Дуже добре, подивимося, що можна зробити для тебе.", ["en"] = "Cenarion Battlegear" },
    [8801] = { [1] = "Спадщина К'Туна", [2] = "Стіни Ан'Кіража тремтять. Сила зла, старша за цей світ, знищена.\n\nДивлячись на залишки гидоти, ваше серце ледь не завмирає. Навіть після смерті К'Туна ви можете відчути спадщину його зла навколо себе.\n\nВи зробили те, що вважалося неможливим.\n\nВи берете око та обережно кладете його у свою сумку.\n\nВіднесіть око К'Туна драконам у сусідній кімнаті.", [3] = "Віднесіть око К'Туна Келестразу в храм Ан'Кіражу.", [4] = "<Келестраз стає перед вами на коліна.>\n\n{стать:Пане:Пані} {ім'я}, ви звільнили нас від його влади.", [5] = "Ми самі покинемо це місце, {стать:пане:пані} {ім'я}, щойно впевнимося, що зло було повністю знищено. Ваша легендарна подорож добігає кінця.", ["en"] = "C'Thun's Legacy", ["tasks"] = { ["Eye of C'Thun"] = "око К'Туна", ["Eye of C'Thun (Provided)"] = "око К'Туна (видано)" } },
    [8802] = { [1] = "Рятівник Калімдора", [2] = "До Печер Часу лежить ваш шлях, {стать:пане:пані} {ім'я}. Анахронос чекає на ваше повернення. Віддайте йому око К'Туна, він неодмінно захоче додати його до колекції свого господаря.", [3] = "Віднесіть око К'Туна до Анахроноса в Печери Часу.", [4] = "{ім'я}! Це скінчилося...", [5] = "Господар залишив це для тебе, {стать:чемпіоне:чемпіонко}. Колекція артефактів позачасового сховку, що охоплює тисячі років — вибір за тобою.", ["en"] = "The Savior of Kalimdor", ["tasks"] = { ["Eye of C'Thun"] = "око К'Туна", ["Eye of C'Thun (Provided)"] = "око К'Туна (видано)" } },
    [8803] = { [1] = "Святковий подарунок", [5] = "Напис на цьому подарунку свідчить:\n\n\"Для {ім'я},\n\nСподіваюсь, що це допоможе тобі поширювати тепло та святковий настрій по всьому Азероту.\n\nВід Дідуся Зими\"", ["en"] = "A Festive Gift" },
    [8804] = { [1] = "Набори виживання в пустелі", [2] = "З приходом новобранців в Кенарійську цитадель, постає проблема їхнього виживання в пустелі. Зневоднення, а також численні отруйні істоти становлять серйозну загрозу для недосвідчених добровольців. Збери припаси, необхідні для набору виживання в пустелі й принеси їх до Каландрат в Кенарійську цитадель.", [3] = "Дістаньте 4 сфери води, 4 потужні протиотрути та 4 порції копчених пустельних пельменів та віднесіть їх до Каландрат, в таверну Кенарійської цитаделі, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання I.", [4] = "У тебе є щось для мене?", [5] = "Чудова робота, {ім'я}. Нам дуже потрібні ці припаси.", ["en"] = "Desert Survival Kits", ["tasks"] = { ["Globe of Water"] = "куля води", ["Globe of Water (Provided)"] = "куля води (видано)", ["Logistics Task Briefing I"] = "план логістичного завдання I", ["Logistics Task Briefing I (Provided)"] = "план логістичного завдання I (видано)", ["Powerful Anti-Venom"] = "потужна протиотрута", ["Powerful Anti-Venom (Provided)"] = "потужна протиотрута (видано)", ["Smoked Desert Dumplings"] = "копчені пустельні пельмені", ["Smoked Desert Dumplings (Provided)"] = "копчені пустельні пельмені (видано)" } },
    [8805] = { [1] = "Чоботи для варти", [2] = "Кінному підрозділу варти Кенарійської цитаделі не вистачає вишуканих мітрилових чобіт. Дістань нам партію і негайно віднеси її капітану Вішу Козусу в Кенарійську цитадель.", [3] = "Принесіть 3 пари вишуканих мітрилових чобіт Вішу Козусу, капітану вартових Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання II.", [4] = "У тебе є щось для мене?", [5] = "Чудова робота, {ім'я}. Нам саме таких і не вистачало.", ["en"] = "Boots for the Guard", ["tasks"] = { ["Logistics Task Briefing II"] = "план логістичного завдання II", ["Logistics Task Briefing II (Provided)"] = "план логістичного завдання II (видано)", ["Ornate Mithril Boots"] = "вишукані мітрилові чоботи", ["Ornate Mithril Boots (Provided)"] = "вишукані мітрилові чоботи (видано)" } },
    [8806] = { [1] = "Шліфувальні камені для вартових", [2] = "Вартовим Кенарійської цитаделі не вистачає шліфувальних каменів. Добудь партію каменів й негайно віднеси їх капітану Вішу Козусу в Кенарійську цитадель.", [3] = "Принесіть 10 масивних шліфувальних каменів, 10 твердих шліфувальних каменів і 10 важких шліфувальних каменів Вішу Козусу, капітану вартових Кенарійської цитаделі в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання III.", [4] = "У тебе є щось для мене?", [5] = "Чудова робота, {ім'я}. Нам саме таких і не вистачало.", ["en"] = "Grinding Stones for the Guard", ["tasks"] = { ["Dense Grinding Stone"] = "масивний шліфувальний камінь", ["Dense Grinding Stone (Provided)"] = "масивний шліфувальний камінь (видано)", ["Heavy Grinding Stone"] = "важкий шліфувальний камінь", ["Heavy Grinding Stone (Provided)"] = "важкий шліфувальний камінь (видано)", ["Logistics Task Briefing III"] = "план логістичного завдання III", ["Logistics Task Briefing III (Provided)"] = "план логістичного завдання III (видано)", ["Solid Grinding Stone"] = "твердий шліфувальний камінь", ["Solid Grinding Stone (Provided)"] = "твердий шліфувальний камінь (видано)" } },
    [8807] = { [1] = "Матеріали для провидінь", [2] = "Дослідження геолога Жартолама виявилися надзвичайно цінними для нашої діяльності в Силітусі. Нещодавно вона звернулася до нас з проханням надати їй матеріали для провидінь, щоб використати їх у своїх дослідженнях.\n\nБудь ласка, збери ці матеріали й віднеси їй, щоб вона продовжила дослідження.", [3] = "Принесіть 1 великий блискучий осколок, 1 великий променистий осколок і 1 величезний смарагд геологу Жартоламу в Кенарійську цитадель, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання V.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "Так, так... Ти мені дуже {стать:допоміг:допомогла}! Дістати ці матеріали в пустелі неймовірно складно, {ім'я}. Дякую.", ["en"] = "Scrying Materials", ["tasks"] = { ["Huge Emerald"] = "величезний смарагд", ["Huge Emerald (Provided)"] = "величезний смарагд (видано)", ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)", ["Large Radiant Shard"] = "великий променистий осколок", ["Large Radiant Shard (Provided)"] = "великий променистий осколок (видано)", ["Logistics Task Briefing V"] = "план логістичного завдання V", ["Logistics Task Briefing V (Provided)"] = "план логістичного завдання V (видано)" } },
    [8808] = { [1] = "Постачання форми", [2] = "Велика кількість добровольців спричинила нестачу форми. Роздобудь матеріали для форми та віддай їх вітрозову Гордому Рогу.", [3] = "Принесіть 1 місячне полотно, 2 рулони рунічної тканини й 1 залізошовкову павутину вітрозову Гордому Рогу в Кенарійській цитаделі, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання VIII.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "Ми дуже вдячні тобі, {ім'я}. Нам саме цього і не вистачало.", ["en"] = "Uniform Supplies", ["tasks"] = { ["Bolt of Runecloth"] = "рулон рунічної тканини", ["Bolt of Runecloth (Provided)"] = "рулон рунічної тканини (видано)", ["Ironweb Spider Silk"] = "залізошовкова павутина", ["Ironweb Spider Silk (Provided)"] = "залізошовкова павутина (видано)", ["Logistics Task Briefing VIII"] = "план логістичного завдання VIII", ["Logistics Task Briefing VIII (Provided)"] = "план логістичного завдання VIII (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)" } },
    [8809] = { [1] = "Незвичайні матеріали", [2] = "Варґус, коваль Кенарійської цитаделі, попросив зачаровані матеріали для виготовлення потужної зброї для нашого війська. Дістань матеріали та віднеси Варґусу, щоб війська Кенарійської цитаделі й надалі були добре озброєні.", [3] = "Принесіть 2 зачаровані злитки торію та 2 зачаровані шкіри Варґусу в Кенарійську цитадель, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання IX.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "О, так. Ці матеріали відмінної якості. Дякую, {ім'я}.", ["en"] = "Extraordinary Materials", ["tasks"] = { ["Enchanted Leather"] = "зачарована шкіра", ["Enchanted Leather (Provided)"] = "зачарована шкіра (видано)", ["Enchanted Thorium Bar"] = "зачарований злиток торію", ["Enchanted Thorium Bar (Provided)"] = "зачарований злиток торію (видано)", ["Logistics Task Briefing IX"] = "план логістичного завдання IX", ["Logistics Task Briefing IX (Provided)"] = "план логістичного завдання IX (видано)" } },
    [8810] = { [1] = "Запаси бинтів", [2] = "Нещодавно ми зазнали серйозних втрат на полі бою, тому наші запаси бинтів закінчуються. Дістань партію засобів першої допомоги й віднеси їх вітрозову Гордому Рогу в Кенарійську цитадель.", [3] = "Принесіть 30 щільних рунічних бинтів, 30 щільних шовкових бинтів і 30 щільних маготканих бинтів вітрозову Гордому Рогу в Кенарійську цитадель, що в Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання X.", [4] = "У тебе є щось для мене, {ім'я}?", [5] = "Якраз вчасно. Ці припаси врятують життя. Ми дуже вдячні тобі. Ось твоє наступне завдання.", ["en"] = "Bandages for the Field", ["tasks"] = { ["Heavy Mageweave Bandage"] = "щільний маготканий бинт", ["Heavy Mageweave Bandage (Provided)"] = "щільний маготканий бинт (видано)", ["Heavy Runecloth Bandage"] = "щільний рунічний бинт", ["Heavy Runecloth Bandage (Provided)"] = "щільний рунічний бинт (видано)", ["Heavy Silk Bandage"] = "щільний шовковий бинт", ["Heavy Silk Bandage (Provided)"] = "щільний шовковий бинт (видано)", ["Logistics Task Briefing X"] = "план логістичного завдання X", ["Logistics Task Briefing X (Provided)"] = "план логістичного завдання X (видано)" } },
    [8811] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Дарнаса.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8812] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання вигнанців Гномреґана.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8813] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Залізогарта.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8814] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Штормовію.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8815] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Орґріммара.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8816] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання племені Темного Списа.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8817] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Підмістя.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8818] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Громового Бескиду.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8819] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення Дарнаса до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8820] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення вигнанців Гномреґана до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
