    [8823] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення Орґріммара до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8824] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення племені Темного Списа до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8825] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення Громового Бескиду до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8826] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення Підмістя до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8829] = { [1] = "Останній обман", [2] = "Сутінковий Молот діє шляхом обману та підступу. Хоча їхні дії відбуваються в нашому світі, свої плани вони розробляють за його межами, куди ми ще не змогли потрапити.\n\nМи вважаємо, що камені, які Сутінковий Молот використовує для виклику своїх повелителів, можуть переправляти в обидві сторони. Щоб спробувати використати їх таким чином, нам потрібно виготовити точну копію мантії сутінкового емісара.\n\n{ім'я}, збери необхідні матеріали й віднеси їх Аврель Золотолистій.", [3] = "Принесіть шкіру тіні, 3 зотлілі стібки потвори та 1 сутінкову мантію культиста Аврель Золотолистій в Кенарійську цитадель, що у Силітусі. Щоб виконати це завдання, потрібно мати з собою план логістичного завдання XI.", [4] = "У тебе є щось для мене?", [5] = "Так, гадаю, цього буде достатньо. Я зроблю мантію у кольорах, які носять послідовники Сутінкового Молота. Я молюся Елуні, щоб моя майстерність знову обдурила наших ворогів.\n\nАле не турбуйся про це, ти {стать:зробив:зробила} свою справу і за це будеш належно {стать:винагороджений:винагороджена}. Ти {стать:вірний і гідний союзник:вірна і гідна союзниця}, {ім'я}.", ["en"] = "The Ultimate Deception", ["tasks"] = { ["Frayed Abomination Stitching"] = "зотлілий стібок потвори", ["Frayed Abomination Stitching (Provided)"] = "зотлілий стібок потвори (видано)", ["Logistics Task Briefing XI"] = "план логістичного завдання XI", ["Logistics Task Briefing XI (Provided)"] = "план логістичного завдання XI (видано)", ["Skin of Shadow"] = "шкіра тіні", ["Skin of Shadow (Provided)"] = "шкіра тіні (видано)", ["Twilight Cultist Robe"] = "сутінкова мантія культиста", ["Twilight Cultist Robe (Provided)"] = "сутінкова мантія культиста (видано)" } },
    [8832] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Підмістя.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8833] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення Підмістя до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8834] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Залізогарта.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8835] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення Залізогарта до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8836] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Штормовію.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
