    [8838] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання вигнанців Гномреґана.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8839] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення вигнанців Гномреґана до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8840] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Орґріммара.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8841] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення Орґріммара до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8842] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання Громового Бескиду.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8843] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення Громового Бескиду до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8844] = { [1] = "Одна відзнака подяки", [4] = "Якщо у тебе є одна відзнака подяки, я можу обміняти її на невелику кількість визнання племені Темного Списа.\n\nОднак, май на увазі, що краще здавати одразу десять відзнак, адже так ти отримаєш більше визнання за свої зусилля. Якщо ж в тебе немає змоги віддати одразу десять відзнак — ми також приймаємо їх по одній.\n\nАле я з радістю допоможу тобі, якщо ти все ж бажаєш віддати мені лише одну відзнаку.", [5] = "Дуже добре, твої подвиги будуть відзначені належним чином. Продовжуй в тому ж дусі, {клас:к}.\n\nЯкщо захочеш здати більше відзнак — я з радістю їх прийму.", ["en"] = "One Commendation Signet", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8845] = { [1] = "Десять відзнак подяки", [4] = "Я приймаю від шукачів пригод відзнаки подяки, отримані за виконання службових обов'язків. За кожні десять відзнак ставлення племені Темного Списа до тебе покращиться. Я також приймаю по одній відзнаці, але так ти отримаєш менше визнання. Ми особливо цінуємо великі діяння, проте жодне не залишиться поза увагою.\n\nОтож, я з радістю допоможу тобі, якщо ти бажаєш віддати мені десяток відзнак.", [5] = "Прекрасно! Ти {стать:зробив:зробила} чимало пожертв, щоб отримати таку кількість відзнак, і ти отримаєш відповідне визнання за свою службу. Такі шукачі пригод як ти, {ім'я:к}, дійсно здатні змінити цей світ.\n\nДай мені знати, якщо у тебе з'являться нові відзнаки — я з радістю прийму їх.", ["en"] = "Ten Commendation Signets", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8846] = { [1] = "П'ять відзнак в обмін на припаси", [4] = "О, то ти хочеш отримати припаси? Що ж, я розумію твою потребу в додаткових припасах... просто поглянь навколо.\n\nЯ видам тобі додаткові припаси, але в обмін на них попрошу відповідну кількість відзнак подяки. Таким чином ти не отримаєш додаткового визнання від нас, але зможеш знайти щось корисне, що допоможе тобі в подальших боях та може навіть врятує твоє життя.", [5] = "Ну що ж, домовилися. Ось твої припаси, {клас:к}. Якщо захочеш отримати ще — тільки скажи мені.\n\nПродовжуй у тому ж дусі, {ім'я}. Якщо ми збираємося перемогти, ми маємо зібрати стільки ресурсів, скільки зможемо. І якщо кожен зробить свій внесок, перемога буде не за горами!", ["en"] = "Five Signets for War Supplies", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8847] = { [1] = "Десять відзнак в обмін на припаси", [4] = "О, то ти хочеш отримати припаси? Що ж, я розумію твою потребу в додаткових припасах... просто поглянь навколо.\n\nЯ видам тобі додаткові припаси, але в обмін на них попрошу відповідну кількість відзнак подяки. Таким чином ти не отримаєш додаткового визнання від нас, але зможеш знайти щось корисне, що допоможе тобі в подальших боях та може навіть врятує твоє життя.", [5] = "Ну що ж, домовилися. Ось твої припаси, {клас:к}. Якщо захочеш отримати ще — тільки скажи мені.\n\nПродовжуй у тому ж дусі, {ім'я}. Якщо ми збираємося перемогти, ми маємо зібрати стільки ресурсів, скільки зможемо. І якщо кожен зробить свій внесок, перемога буде не за горами!", ["en"] = "Ten Signets for War Supplies", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
    [8848] = { [1] = "П'ятнадцять відзнак в обмін на припаси", [4] = "О, то ти хочеш отримати припаси? Що ж, я розумію твою потребу в додаткових припасах... просто поглянь навколо.\n\nЯ видам тобі додаткові припаси, але в обмін на них попрошу відповідну кількість відзнак подяки. Таким чином ти не отримаєш додаткового визнання від нас, але зможеш знайти щось корисне, що допоможе тобі в подальших боях та може навіть врятує твоє життя.", [5] = "Ну що ж, домовилися. Ось твої припаси, {клас:к}. Якщо захочеш отримати ще — тільки скажи мені.\n\nПродовжуй у тому ж дусі, {ім'я}. Якщо ми збираємося перемогти, ми маємо зібрати стільки ресурсів, скільки зможемо. І якщо кожен зробить свій внесок, перемога буде не за горами!", ["en"] = "Fifteen Signets for War Supplies", ["tasks"] = { ["Alliance Commendation Signet"] = "відзнака подяки Альянсу", ["Alliance Commendation Signet (Provided)"] = "відзнака подяки Альянсу (видано)" } },
