    [8852] = { [1] = "Десять відзнак в обмін на припаси", [4] = "О, то ти хочеш отримати припаси? Що ж, я розумію твою потребу в додаткових припасах... просто поглянь навколо.\n\nЯ видам тобі додаткові припаси, але в обмін на них попрошу відповідну кількість відзнак подяки. Таким чином ти не отримаєш додаткового визнання від нас, але зможеш знайти щось корисне, що допоможе тобі в подальших боях та може навіть врятує твоє життя.", [5] = "Ну що ж, домовилися. Ось твої припаси, {клас:к}. Якщо захочеш отримати ще — тільки скажи мені.\n\nПродовжуй у тому ж дусі, {ім'я}. Якщо ми збираємося перемогти, ми маємо зібрати стільки ресурсів, скільки зможемо. І якщо кожен зробить свій внесок, перемога буде не за горами!", ["en"] = "Ten Signets for War Supplies", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8853] = { [1] = "П'ятнадцять відзнак в обмін на припаси", [4] = "О, то ти хочеш отримати припаси? Що ж, я розумію твою потребу в додаткових припасах... просто поглянь навколо.\n\nЯ видам тобі додаткові припаси, але в обмін на них попрошу відповідну кількість відзнак подяки. Таким чином ти не отримаєш додаткового визнання від нас, але зможеш знайти щось корисне, що допоможе тобі в подальших боях та може навіть врятує твоє життя.", [5] = "Ну що ж, домовилися. Ось твої припаси, {клас:к}. Якщо захочеш отримати ще — тільки скажи мені.\n\nПродовжуй у тому ж дусі, {ім'я}. Якщо ми збираємося перемогти, ми маємо зібрати стільки ресурсів, скільки зможемо. І якщо кожен зробить свій внесок, перемога буде не за горами!", ["en"] = "Fifteen Signets for War Supplies", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8854] = { [1] = "Двадцять відзнак в обмін на припаси", [4] = "О, то ти хочеш отримати припаси? Що ж, я розумію твою потребу в додаткових припасах... просто поглянь навколо.\n\nЯ видам тобі додаткові припаси, але в обмін на них попрошу відповідну кількість відзнак подяки. Таким чином ти не отримаєш додаткового визнання від нас, але зможеш знайти щось корисне, що допоможе тобі в подальших боях та може навіть врятує твоє життя.", [5] = "Ну що ж, домовилися. Ось твої припаси, {клас:к}. Якщо захочеш отримати ще — тільки скажи мені.\n\nПродовжуй у тому ж дусі, {ім'я}. Якщо ми збираємося перемогти, ми маємо зібрати стільки ресурсів, скільки зможемо. І якщо кожен зробить свій внесок, перемога буде не за горами!", ["en"] = "Twenty Signets for War Supplies", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8855] = { [1] = "Тридцять відзнак в обмін на припаси", [4] = "О, то ти хочеш отримати припаси? Що ж, я розумію твою потребу в додаткових припасах... просто поглянь навколо.\n\nЯ видам тобі додаткові припаси, але в обмін на них попрошу відповідну кількість відзнак подяки. Таким чином ти не отримаєш додаткового визнання від нас, але зможеш знайти щось корисне, що допоможе тобі в подальших боях та може навіть врятує твоє життя.", [5] = "Ну що ж, домовилися. Ось твої припаси, {клас:к}. Якщо захочеш отримати ще — тільки скажи мені.\n\nПродовжуй у тому ж дусі, {ім'я}. Якщо ми збираємося перемогти, ми маємо зібрати стільки ресурсів, скільки зможемо. І якщо кожен зробить свій внесок, перемога буде не за горами!", ["en"] = "Thirty Signets for War Supplies", ["tasks"] = { ["Horde Commendation Signet"] = "відзнака подяки Орди", ["Horde Commendation Signet (Provided)"] = "відзнака подяки Орди (видано)" } },
    [8856] = { [1] = "Набори виживання в пустелі", [2] = "З приходом новобранців в Кенарійську цитадель, постає проблема їхнього виживання в пустелі. Зневоднення, а також численні отруйні істоти становлять серйозну загрозу для недосвідчених добровольців. Збери припаси, необхідні для набору виживання в пустелі й принеси їх до Каландрат в Кенарійську цитадель.", [3] = "Дістаньте 4 сфери води, 4 потужні протиотрути та 4 порції запеченого лосося та віднесіть їх до Каландрат, в таверну Кенарійської цитаделі, що в Силітусі.", ["en"] = "Desert Survival Kits", ["tasks"] = { ["Globe of Water"] = "куля води", ["Globe of Water (Provided)"] = "куля води (видано)", ["Logistics Task Briefing I"] = "план логістичного завдання I", ["Logistics Task Briefing I (Provided)"] = "план логістичного завдання I (видано)", ["Powerful Anti-Venom"] = "потужна протиотрута", ["Powerful Anti-Venom (Provided)"] = "потужна протиотрута (видано)", ["Smoked Desert Dumplings"] = "копчені пустельні пельмені", ["Smoked Desert Dumplings (Provided)"] = "копчені пустельні пельмені (видано)" } },
    [8857] = { [1] = "Таємниці колоса — Аші", [2] = "Я шукаю загартованих у боях шукачів пригод, які захочуть принести свіжий зразок полеглого колоса Аші Оґлторпу в Грабіжну Бухту. Ні, ні, я не хочу, щоб ти {стать:наближався:наближалася} до тіла цієї істоти. Такі зразки йому не знадобляться, вони гнилі! Просто візьми один з моїх зразків і поквапся.", [3] = "Віднесіть зразок панцира колоса Аші Оґлторпу Обриднусу в Грабіжну Бухту.", [4] = "Так? Що там у тебе?", [5] = "Ох, скільки ж я зроблю курчат з цього чудесного панцира! Молодець, {стать:мій хлопчику:моя дівчинко}!", ["en"] = "Secrets of the Colossus - Ashi", ["tasks"] = { ["Colossus of Ashi's Husk"] = "зразок панцира колоса Аші", ["Colossus of Ashi's Husk (Provided)"] = "зразок панцира колоса Аші (видано)" } },
    [8858] = { [1] = "Таємниці колоса — Регаль", [2] = "Понад усе, я хочу запхати зразок панцира цього жука в... жирну пику Слизькорука. Але я застряг тут, збираючи зразки з цього таргана-переростка. Я сидітиму тут до самого ранку, враховуючи його розміри.\n\nВіднеси цей зразок Слизькоруку якнайшвидше, {клас:r}. Він добре заплатить!\n\nТобі в Торієвий табір — це у Випаленій ущелині.", [3] = "Віднесіть зразок панцира колоса Регаля розпоряднику Слизькоруку у Випалену ущелину.", [4] = "Хмм...", [5] = "Чудово. З цього хітину можна створити неймовірно міцні обладунки. Ось багатства, які тобі обіцяли.", ["en"] = "Secrets of the Colossus - Regal", ["tasks"] = { ["Colossus of Regal's Husk"] = "зразок панцира колоса Регаля", ["Colossus of Regal's Husk (Provided)"] = "зразок панцира колоса Регаля (видано)" } },
    [8859] = { [1] = "Таємниці колоса — Зора", [2] = "Мої слуги ледь не загинули, намагаючись здобути цей зразок. Ти маєш поспішати! Лорд Максвелл Тірос з нетерпінням чекає на новий зразок панцира. Він вірить, що таємниці цього колоса допоможуть нам у війні зі Скарою!\n\nЧому ти ще тут?! Вперед, до Надії Світла! Тобі щедро заплатять за твої зусилля...", [3] = "Віднесіть зразок панцира колоса Зори лорду Максвеллу Тіросу в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Ти ледве переставляєш ноги, {стать:друже:подруго}.", [5] = "Відмінно та вчасно! Так тримати, {стать:хлопче:дівчино}.", ["en"] = "Secrets of the Colossus - Zora", ["tasks"] = { ["Colossus of Zora's Husk"] = "зразок панцира колоса Зори", ["Colossus of Zora's Husk (Provided)"] = "зразок панцира колоса Зори (видано)" } },
    [886] = { [1] = "Оазиси Степів", [2] = "Друїди Громового Бескиду відчувають дивну силу, що просочується у Степи, що на схід від Мулґору.\n\nТонґу Рунного Тотема спорядили розвідати джерело цієї сили, але ми боїмося, що йому може знадобитись допомога.\n\nПрямуй до Степів і поговори з Тонґою. Ти знайдеш його на Перехресті. Рухайся дорогою на схід, від селища Криваве Копито, щоб туди дістатися. Як зайдеш у Степи, то на роздоріжжі тримайся півночі. Йди у тому ж напрямку й опинишся на Перехресті.\n\nІ не звертай з дороги, {ім'я}: Степи - сувора земля.", [3] = "Поговоріть з Тонґою Рунним Тотемом на Перехресті.", [5] = "Мої побратими з Громового Бескиду мудро вчинили, приславши тебе, {стать:юний:юна} {клас:к}. Бо самотужки таємницю Степів я не розплутаю.\n\nЗ твоєю допомогою, сподіваюся, ми знайдемо відповіді на наші запитання.", ["en"] = "The Barrens Oases" },
    [8862] = { [1] = "Свічка Елуни", [4] = "Свічка Елуни — це артефакт великої пошани для послідовників Місячного фестивалю. Усередині свічки зберігається справжнє місячне сяйво, готове вирватися назовні!\n\nЦе сяйво нешкідливе для більшості істот, але ти побачиш, що Омена і його поплічників свічка обпікає і засліплює.", [5] = "Дуже добре — я приймаю ці монети предків. Забирай свічку Елуни з моїм благословенням. Також, прошу, насолоджуйся цими феєрверками.\n\nНехай твій Місячний фестиваль буде радісним і наповненим веселощами, {ім'я}.\n\nІ якщо ти вирішиш зустрітися з Оменом та його поплічниками, свічка Елуни допоможе тобі...", ["en"] = "Elune's Candle", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [8863] = { [1] = "Фестивальні вареники", [4] = "Якщо ти {стать:голодний:голодна}, то ти {стать:прийшов:прийшла} куди треба, {стать:друже:подруго}!\n\nВареники — це традиційна страва Місячного фестивалю. Вони подаються з часів першого Місячного фестивалю, і я радий мати можливість пропонувати їх на цьому святі. За всього одну монету предків я поділюся з тобою однією з найсмачніших страв, яку ти коли-небудь {стать:їв:їла}!", [5] = "Чудово — будь ласка, насолоджуйся цими варениками з моїми компліментами. Хоча вони лише маленький символ вдячності за твої заслуги, я думаю, що тобі все одно сподобається.\n\nЯкщо у тебе є ще монети предків, я готовий запропонувати тобі широкий асортимент товарів у обмін на них.", ["en"] = "Festival Dumplings", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [8864] = { [1] = "Святкові місячні сукні", [4] = "У мене є декілька суконь, які можуть тебе зацікавити. Такі сукні носили в минулі часи під час Місячного фестивалю, і асортимент, який я маю сьогодні, можливо, найкращий, який я коли-небудь бачив. Кожна сукня ручної роботи з використанням тільки найкращих та найм'якших компонентів.\n\nВ обмін на кілька монет предків я дозволю тобі вибрати одну з цих трьох суконь. Чи приймаєш ти цю пропозицію?", [5] = "Згода, я приймаю ці монети предків. Забирай свою сукню з моїм благословенням. Також, прошу, насолоджуйся цими феєрверками.\n\nТи {стать:вшанував:вшанувала} предків, і твоя присутність викликає в мене велику повагу. Дякую тобі, і нехай твій Місячний фестиваль буде радісним.", ["en"] = "Festive Lunar Dresses", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [8865] = { [1] = "Святкові місячні костюми", [4] = "Я радий повідомити тебе, що у мене є чудовий вибір святкових костюмів, які ти можеш отримати... але лише в обмін на монети предків. Я впевнений, що ти не знайдеш такі костюми ніде інде.\n\nВ обмін на монети предків, я дозволю тобі вибрати один з трьох костюмів, який ти зможеш носити. Чи приймаєш ти цю пропозицію?", [5] = "Згода, я приймаю ці монети предків. Забирай свій костюм з моїм благословенням. Також, прошу, насолоджуйся цими феєрверками.\n\nЯкщо матимеш ще монети предків, приходь до мене знову. В обмін на них я пропонуватиму різні предмети протягом усього Місячного фестивалю.", ["en"] = "Festive Lunar Pant Suits", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [88654] = { [1] = "Повна відправка", [4] = "У тебе є щось для мене?", [5] = "Все враховано! Дякую, {ім'я}. Ці припаси критично важливі для передової.", ["en"] = "A Full Shipment" },
    [8866] = { [1] = "Предок Бронзобородий", [5] = "Приємно знати, що народ цієї землі все ще віддає шану давнім расам. Я бажаю тобі всього найкращого, {ім'я}, і прийми цю річ...", ["en"] = "Bronzebeard the Elder" },
    [8867] = { [1] = "Місячні феєрверки", [2] = "Кожного року друїди Місячної галявини проводять святкування величного тріумфу нашого міста над давнім злом.\n\nМи вшановуємо мудрість наших предків, насолоджуємося величезним святкуванням і звичайно ж... запускаємо феєрверки!\n\nЗа невелику пожертву ти можеш придбати кольорові ракети у нашого торговця. Спробуй скористатися пусковими установками, що знаходяться неподалік.", [3] = "Запустіть 8 феєрверків і 2 залпи феєрверків та поверніться до провісниці Місячного фестивалю в будь-якій столиці.", [4] = "Ти {стать:знайшов:знайшла} пускові установки, {ім'я}?", [5] = "Молодець, {ім'я}.\n\nТепер, коли ти {стать:відчув:відчула} дух свята, чому б тобі не скористатися запрошенням на фестиваль в Місячній галявині.\n\nТи зможеш непогано повеселитися, якщо у тебе є вільний час. Там повно їжі, напоїв, чудових історій і звичайно ж... феєрверків!\n\nВідкрий запрошення, стоячи всередині кола великого місячного сяйва, і ти потрапиш на Місячну галявину.", ["en"] = "Lunar Fireworks", ["tasks"] = { ["Lunar Fireworks Cluster Fired"] = "Місячний феєрверк у скупченні запущено", ["Lunar Fireworks Cluster Fired (Provided)"] = "Місячний феєрверк у скупченні запущено (видано)", ["Lunar Fireworks Cluster Fired slain"] = "Місячний феєрверк у скупченні запущено: убито", ["Lunar Fireworks Fired"] = "Місячний феєрверк запущено", ["Lunar Fireworks Fired (Provided)"] = "Місячний феєрверк запущено (видано)", ["Lunar Fireworks Fired slain"] = "Місячний феєрверк запущено: убито" } },
    [8868] = { [1] = "Благословення Елуни", [2] = "Цей звір, Омен, колись був героєм цього світу. Вовк великої сили та удачі, Омен бився пліч-о-пліч з героями Війни Древніх, поки не потрапив під вплив демонічної магії. Він обернувся проти власних союзників та в люті блукав Азеротом, сіючи навколо себе смерть та жах.\n\nНарешті, переможений тут, в Місячній галявині, Омен зараз спить серед мулу озера Елуна'ара. Але кожного року, під час фестивалю, він прокидається...\n\nЗбирай союзників, {ім'я}, виклич та переможи звіра Омена. Отримай благословення Елуни!", [3] = "Викличте Омена, переможіть його та отримайте благословення Елуни. Поверніться до Валадара Зорепісні в Нічну Гавань.", [4] = "Омен все ще рухається під мулом озера Елуна'ара, {ім'я}...", [5] = "Дуже добре, {ім'я}. Перемога над Оменом відправила його дух назад до вод Елуна'ара. Хоча сам звір був благословенним Елуною та не може померти, його гнів заспокоїться іще на один рік.\n\nТвоя перемога — це свято, {ім'я}. Свято могутності Омена, тебе та твоїх союзників, і миру, який ти {стать:подарував:подарувала} цьому трагічному герою нашого минулого.", ["en"] = "Elune's Blessing", ["tasks"] = { ["Receive Elune's Blessing."] = "Отримайте благословення Елуни." } },
    [8869] = { [1] = "Солодка безтурботність", [2] = "Всередині Багряного оплоту приховується солодка Безтурботність. Багряний коваль молотів стереже її креслення як зіницю ока. Вбий його і принеси мені його фартух. За це я відкрию тобі секрети кування молотів.\n\nТа пам'ятай, що коли обереш шлях коваля молотів, ти вже не зможеш стати ковалем мечів чи сокир.", [3] = "Відправляйтеся до Стратгольму і вбийте багряного коваля молотів. Заберіть фартух багряного коваля молотів та поверніться до Ліліт.", ["en"] = "Sweet Serenity", ["tasks"] = { ["Crimson Hammersmith's Apron"] = "фартух багряного коваля молотів", ["Crimson Hammersmith's Apron (Provided)"] = "фартух багряного коваля молотів (видано)" } },
    [887] = { [1] = "Флібустьєри Південних морів", [2] = "Хотілось би, щоб віцеадмірал Ґрецлік краще охороняв море для наших торгових кораблів. У торговий флот вкладено стільки золота, що я просто звірію, коли пірати так безкарно нападають на мої кораблі та крадуть мої товари!\n\nЯ чув, що флібустьєри Південних морів отаборилися на південь звідси. Вони стали справжньою проблемою, тож якщо Ґрецлік не хоче про них подбати, то, можливо, ти допоможеш мені їх позбутися.", [3] = "Вбийте 12 грабіжників Південних морів та 6 канонірів Південних морів для Ґазлоу з Брашпиля.", [4] = "Я навіть думати не хочу про збитки, які мені завдали ці кляті пірати, а тепер вони ще й табір у мене під носом розбили? Це вже нахабство, Підштольня має щось з цим зробити.", [5] = "Ти молодець, {стать:малий:мала}. Ще трохи такої роботи, і у мене стане однією проблемою менше. Сподіваюся, вони додумаються забратись якомога далі разом зі своїм табором.\n\nА поки що залишилася маленька справа — повернути викрадені товари!", ["en"] = "Southsea Freebooters", ["tasks"] = { ["Southsea Brigand"] = "грабіжник Південних морів", ["Southsea Brigand slain"] = "грабіжник Південних морів: убито", ["Southsea Cannoneer"] = "канонір Південних морів", ["Southsea Cannoneer slain"] = "канонір Південних морів: убито" } },
    [88713] = { [1] = "Ніколи не відпочиває", [2] = "Приводьте мені будь-які приречені душі, які перетинаються на вашому шляху, {ім'я}.\n\nДозвольте мені перефразувати це – ви ПОВИННІ привести їх до мене.\nМій обов'язок – залишатися та направляти душі загиблих. Ваш обов'язок – привести їх до мене.\n\nПорада: ніколи не беріть більше однієї душі одночасно. Повірте мені, ваша душа може витримати лише певну кількість, а ваш розум... ну... він може витримати ще менше.\n\nЦей тягар тепер ваш. Тому що ви можете, ви повинні.\n\nВважайте це моральним обов'язком.", [3] = "Принесіть ще одне Серце Долі Брату Луктусу в Каплицю Надії Світла у Східних Чумних землях.", [4] = "Лихо ніколи не відпочиває, тому ми ніколи не повинні відпочивати, {ім'я}.", [5] = "{ім'я}, з кожним поверненим серцем я стою в покорі. Деякі з душ належать могутнім воїнам. Деякі здавалися незламними... і все ж... вони впали.\n\nБич охопив їх, корупція проникла в їхні розуми, або, в деяких випадках, вони добровільно скорилися.\n\nТака величезна сила була знищена.\n\nІ тепер, завдяки вам, вони зберігають свою останню крихту доблесті.\n\nБез вас жахи їхньої смерті переважили б героїзм їхнього життя.", ["en"] = "Never at Rest" },
    [88714] = { [1] = "Ніколи не відпочиває", [2] = "Приводьте мені будь-які приречені душі, які перетинаються на вашому шляху, {ім'я}.\n\nДозвольте мені перефразувати це – ви ПОВИННІ привести їх до мене.\nМій обов'язок – залишатися та направляти душі загиблих. Ваш обов'язок – привести їх до мене.\n\nПорада: ніколи не беріть більше однієї душі одночасно. Повірте мені, ваша душа може витримати лише певну кількість, а ваш розум... ну... він може витримати ще менше.\n\nЦей тягар тепер ваш. Тому що ви можете, ви повинні.\n\nВважайте це моральним обов'язком.", [3] = "Принесіть ще одне Серце Долі Брату Луктусу в Каплицю Надії Світла у Східних Чумних землях.", [4] = "Лихо ніколи не відпочиває, тому ми ніколи не повинні відпочивати, {ім'я}.", [5] = "{ім'я}, з кожним поверненим серцем я стою в покорі. Деякі з душ належать могутнім воїнам. Деякі здавалися незламними... і все ж... вони впали.\n\nБич охопив їх, корупція проникла в їхні розуми, або, в деяких випадках, вони добровільно скорилися.\n\nТака величезна сила була знищена.\n\nІ тепер, завдяки вам, вони зберігають свою останню крихту доблесті.\n\nБез вас жахи їхньої смерті переважили б героїзм їхнього життя.", ["en"] = "Never at Rest" },
    [88715] = { [1] = "Ніколи не відпочиває", [2] = "Приводьте мені будь-які приречені душі, які перетинаються на вашому шляху, {ім'я}.\n\nДозвольте мені перефразувати це – ви ПОВИННІ привести їх до мене.\nМій обов'язок – залишатися та направляти душі загиблих. Ваш обов'язок – привести їх до мене.\n\nПорада: ніколи не беріть більше однієї душі одночасно. Повірте мені, ваша душа може витримати лише певну кількість, а ваш розум... ну... він може витримати ще менше.\n\nЦей тягар тепер ваш. Тому що ви можете, ви повинні.\n\nВважайте це моральним обов'язком.", [3] = "Принесіть ще одне Серце Долі Брату Луктусу в Каплицю Надії Світла у Східних Чумних землях.", [4] = "Лихо ніколи не відпочиває, тому ми ніколи не повинні відпочивати, {ім'я}.", [5] = "{ім'я}, з кожним поверненим серцем я стою в покорі. Деякі з душ належать могутнім воїнам. Деякі здавалися незламними... і все ж... вони впали.\n\nБич охопив їх, корупція проникла в їхні розуми, або, в деяких випадках, вони добровільно скорилися.\n\nТака величезна сила була знищена.\n\nІ тепер, завдяки вам, вони зберігають свою останню крихту доблесті.\n\nБез вас жахи їхньої смерті переважили б героїзм їхнього життя.", ["en"] = "Never at Rest" },
    [88716] = { [1] = "Ніколи не відпочиває", [2] = "Приводьте мені будь-які приречені душі, які перетинаються на вашому шляху, {ім'я}.\n\nДозвольте мені перефразувати це – ви ПОВИННІ привести їх до мене.\nМій обов'язок – залишатися та направляти душі загиблих. Ваш обов'язок – привести їх до мене.\n\nПорада: ніколи не беріть більше однієї душі одночасно. Повірте мені, ваша душа може витримати лише певну кількість, а ваш розум... ну... він може витримати ще менше.\n\nЦей тягар тепер ваш. Тому що ви можете, ви повинні.\n\nВважайте це моральним обов'язком.", [3] = "Принесіть ще одне Серце Долі Брату Луктусу в Каплицю Надії Світла у Східних Чумних землях.", [4] = "Лихо ніколи не відпочиває, тому ми ніколи не повинні відпочивати, {ім'я}.", [5] = "{ім'я}, з кожним поверненим серцем я стою в покорі. Деякі з душ належать могутнім воїнам. Деякі здавалися незламними... і все ж... вони впали.\n\nБич охопив їх, корупція проникла в їхні розуми, або, в деяких випадках, вони добровільно скорилися.\n\nТака величезна сила була знищена.\n\nІ тепер, завдяки вам, вони зберігають свою останню крихту доблесті.\n\nБез вас жахи їхньої смерті переважили б героїзм їхнього життя.", ["en"] = "Never at Rest" },
    [88717] = { [1] = "Ніколи не відпочиває", [2] = "Приводьте мені будь-які приречені душі, які перетинаються на вашому шляху, {ім'я}.\n\nДозвольте мені перефразувати це – ви ПОВИННІ привести їх до мене.\nМій обов'язок – залишатися та направляти душі загиблих. Ваш обов'язок – привести їх до мене.\n\nПорада: ніколи не беріть більше однієї душі одночасно. Повірте мені, ваша душа може витримати лише певну кількість, а ваш розум... ну... він може витримати ще менше.\n\nЦей тягар тепер ваш. Тому що ви можете, ви повинні.\n\nВважайте це моральним обов'язком.", [3] = "Принесіть ще одне Серце Долі Брату Луктусу в Каплицю Надії Світла у Східних Чумних землях.", [4] = "Лихо ніколи не відпочиває, тому ми ніколи не повинні відпочивати, {ім'я}.", [5] = "{ім'я}, з кожним поверненим серцем я стою в покорі. Деякі з душ належать могутнім воїнам. Деякі здавалися незламними... і все ж... вони впали.\n\nБич охопив їх, корупція проникла в їхні розуми, або, в деяких випадках, вони добровільно скорилися.\n\nТака величезна сила була знищена.\n\nІ тепер, завдяки вам, вони зберігають свою останню крихту доблесті.\n\nБез вас жахи їхньої смерті переважили б героїзм їхнього життя.", ["en"] = "Never at Rest" },
    [88721] = { [1] = "Чудове бойове спорядження — дружба Світанку", [2] = "Вітаю, друже. Чи маєш ти знаки розрізнення Світанку чи Хрестового походу, які хотів би обміняти на предмети сили?\n\nМушу тебе попередити: покупки, зроблені у дружніх стосунках зі Світанком, мають значну доплату. Я б порадив тобі покращити свою репутацію у Світанку, перш ніж продовжувати свої плани.", [3] = "За 30 знаків розрізнення Світанку та 30 знаків розрізнення Хрестового походу ви можете вибрати предмет зі скарбниці Срібного Світанку.", [4] = "Вибирайте ретельно. Повернення коштів не передбачено.", [5] = "Доброго дня, {ім'я}. Було приємно мати з вами справу.", ["en"] = "Superior Armaments of Battle - Friend of the Dawn" },
    [88722] = { [1] = "Чудове бойове спорядження — почесть Світанку", [2] = "Вітаю, друже. Чи маєш ти знаки розрізнення Світанку чи Хрестового походу, які хотів би обміняти на предмети сили?\n\nМушу тебе попередити: покупки, зроблені з шанованою репутацією у Світанку, мають досить високу додаткову плату. Я б порадив тобі покращити репутацію у Світанку, перш ніж продовжувати свої плани.", [3] = "За 20 знаків розрізнення Світанку та 20 знаків розрізнення Хрестового походу ви можете вибрати предмет зі скарбниці Срібного Світанку.", [4] = "Вибирайте ретельно. Повернення коштів не передбачено.", [5] = "Доброго дня, {ім'я}. Було приємно мати з вами справу.", ["en"] = "Superior Armaments of Battle - Honored Amongst the Dawn" },
    [88723] = { [1] = "Чудове бойове спорядження — шанованість Світанку", [2] = "Вітаю, друже. Чи маєш ти знаки розрізнення Світанку чи Хрестового походу, які хотів би обміняти на предмети сили?\n\nПредмети, що пропонуються шанованим серед Світанку, мають цілком помірну ціну. Закликаю тебе зробити покупку!", [3] = "За 7 знаків розрізнення Світанку та 7 знаків розрізнення Хрестового походу ви можете вибрати предмет зі скарбниці Срібного Світанку.", [4] = "Вибирайте ретельно. Повернення коштів не передбачено.", [5] = "Доброго дня, {ім'я}. Було приємно мати з вами справу.", ["en"] = "Superior Armaments of Battle - Revered Amongst the Dawn" },
    [88724] = { [1] = "Чудове бойове спорядження — возвеличення Світанку", [2] = "Вітаю, друже. Чи маєш ти знаки розрізнення Світанку чи Хрестового походу, які хотів би обміняти на предмети сили?\n\nПредмети, що пропонуються тим, хто піднесений серед Світанку, зі знижкою. Закликаю тебе зробити покупку!", [3] = "За 6 знаків розрізнення Світанку та 6 знаків розрізнення Хрестового походу ви можете вибрати предмет зі скарбниці Срібного Світанку.", [4] = "Вибирайте ретельно. Повернення коштів не передбачено.", [5] = "Доброго дня, {ім'я}. Було приємно мати з вами справу.", ["en"] = "Superior Armaments of Battle - Exalted Amongst the Dawn" },
    [88725] = { [1] = "Епічне бойове спорядження — дружба Світанку", [2] = "Вітаю, друже. Чи маєш ти знаки розрізнення Світанку чи Хрестового походу, які хотів би обміняти на предмети великої сили?\n\nМушу тебе попередити: покупки, зроблені у дружніх стосунків зі Світанком, мають надзвичайно велику доплату. Я б порадив тобі покращити свою репутацію у Світанку, перш ніж продовжувати свої плани.", [3] = "За 110 знаків розрізнення Світанку та 110 знаків розрізнення Хрестового походу ви можете вибрати предмет зі скарбниці Срібного Світанку.", ["en"] = "Epic Armaments of Battle - Friend of the Dawn" },
    [88726] = { [1] = "Епічне бойове спорядження — почесть Світанку", [2] = "Вітаю, друже. Чи маєш ти знаки розрізнення Світанку чи Хрестового походу, які хотів би обміняти на предмети великої сили?\n\nМушу тебе попередити: покупки, зроблені за шанованою репутацією у Світанку, мають надзвичайно велику доплату. Я б порадив тобі покращити репутацію у Світанку, перш ніж продовжувати свої плани.", [3] = "За 75 знаків розрізнення Світанку та 75 знаків розрізнення Хрестового походу ви можете вибрати предмет зі скарбниці Срібного Світанку.", ["en"] = "Epic Armaments of Battle - Honored Amongst the Dawn" },
    [88727] = { [1] = "Епічне бойове спорядження — шанованість Світанку", [2] = "Вітаю, друже. Чи маєш ти знаки розрізнення Світанку чи Хрестового походу, які хотів би обміняти на предмети великої сили?\n\nМушу тебе попередити: епічні покупки, зроблені за шановану репутацію у Світанку, все ще досить дорогі. Я б порадив тобі здобути кращу репутацію у Світанку, перш ніж продовжувати свої плани.", [3] = "За 45 знаків розрізнення Світанку та 45 знаків розрізнення Хрестового походу ви можете вибрати предмет зі скарбниці Срібного Світанку.", [4] = "Вибирайте ретельно. Повернення коштів не передбачено.", [5] = "Доброго дня, {ім'я}. Було приємно мати з вами справу.", ["en"] = "Epic Armaments of Battle - Revered Amongst the Dawn" },
    [88728] = { [1] = "Епічне бойове спорядження — возвеличення Світанку", [2] = "Вітаю, друже. Чи маєш ти знаки розрізнення Світанку чи Хрестового походу, які хотів би обміняти на предмети великої сили?\n\nТі, хто підноситься серед Світанку, отримують наші найбільші знижки! Закликаю тебе зробити покупку.", [3] = "За 27 знаків розрізнення Світанку та 27 знаків розрізнення Хрестового походу ви можете вибрати предмет зі скарбниці Срібного Світанку.", [4] = "Вибирайте ретельно. Повернення коштів не передбачено.", [5] = "Доброго дня, {ім'я}. Було приємно мати з вами справу.", ["en"] = "Epic Armaments of Battle - Exalted Amongst the Dawn" },
    [88729] = { [1] = "Крижана хватка Рамаладні", [2] = "Полагодити цю обручку може виявитися досить складно, {ім'я}. Бачите, вона була зроблена з тих самих рун, що утворюються всередині структур Бичі — таких як Наксрамас. Також потрібні додаткові матеріали, але вашою головною турботою має бути отримання цих заморожених рун. Принесіть мені те, що мені потрібно, і я поверну обручці колишню славу.", [3] = "Корфакс з Каплиці Надії Світла у Східних Чумних землях хоче, щоб ви принесли йому 1 Замерзлу Руну, 1 Синій Сапфір та 1 Арканітовий злиток.", [4] = "Замерзлі руни, ймовірно, можна знайти всередині Наксрамаса.", [5] = "Сам Рамаладні не міг би зробити краще! Ось перстень, як і обіцяв.", ["en"] = "Ramaladni's Icy Grasp" },
    [88730] = { [1] = "Це все, що я можу...", [2] = "Ти вважаєш себе героєм Світанку, га? Я бачив, як наших найкращих солдатів валили на землю плебеї Кел'Тузада! Як добре може хтось такий безпорадний почуватися в Наксрамасі?\n\n<Вільгельм зітхає.>\n\nБа, який у мене вибір? Ти найкращий, кого я можу зробити; я можу тобі допомогти.\n\nОмаріон залишив мені один рецепт. Це єдина пісня, яку я знаю... Я можу зробити кілька варіацій цих штанів; тобі просто потрібно надати матеріали.", [3] = "Ремісник Вільгельм з каплиці Надії Світла у Східних Чумних землях хоче, щоб ви принесли йому 2 Замерзлі Руни, 2 Есенції Води, 2 Сині Сапфіри та 30 золотих монет.", [4] = "Ти ж не зустрічав Омаріона, чи не так?", [5] = "<Вільгельм витирає піт з чола.>\n\nОсь важка робота! Насолоджуйся штанами, {клас}. Принаймні, тепер ти помреш у чистих штанях.", ["en"] = "The Only Song I Know..." },
    [88744] = { [1] = "Під тінню", [2] = "Плаваючі некрополі Бичі вражають землі Орди та Альянсу. Танаріс, Вивержені Землі, Зимоключ та Палаючі Степи вкриті тінями літаючих фортець.\n\nЛише завдяки нашим спільним зусиллям їх буде відвернуто.\n\nНекрополі підтримуються магічними колами в різних точках захоплених територій. Ми вирішили, що знищення бездумних орд, які оточують ці кола, зруйнує їхню оборону.", [3] = "Перевірте свою карту, щоб знайти область під атакою Бичі. Ідіть туди та пошкодьте некрополь, перемігши Бич навколо нього. Поверніть 10 їхніх Некротичних Рун Командувачу Томасу Хеллерану в Каплиці Надії Світла у Східних Чумних Землях.", [4] = "Знадобиться час, щоб подолати цю загрозу. Як вам справи, {ім'я}?", [5] = "Ти добре впорався, {ім'я}. Завдяки цим поступовим поразкам ми переможемо цю нову загрозу Бичі.\n\nВідпочинь та одужай, але потім ти мусиш знову вирушити на фронт, інакше ми втратимо позиції, які здобули сьогодні.\n\nЩоб допомогти тобі в подальших битвах, ми надамо тобі деякі з наших спеціальних предметів в обмін на більше некротичних рун.", ["en"] = "Under the Shadow" },
    [88745] = { [1] = "Тіні приречення", [2] = "Після того, як ви зруйнуєте захист кіл виклику Бича, що з'явилися в зонах атаки, ви зможете протистояти аколітам, які їх захищають.\n\nНасправді, це не люди. Це тіні, одні з найстрашніших істот Короля-ліча. Їх можна виявити за допомогою некротичних рун, які вони несуть, а потім знищити магією або силою зброї.", [3] = "Ідіть до кола викликання та вбийте Тінь Долі, потім поверніться до Командира Томаса Хеллерана в Каплицю Надії Світла у Східних Чумних землях.", [4] = "Тобі пощастило, {ім'я}?", [5] = "Чудова робота, {ім'я}. Зі знищенням тіней, це лише питання часу, коли Король-ліч вирішить відкликати свої некрополі та залишити нас у спокої.", ["en"] = "Shadows of Doom" },
    [8876] = { [1] = "Маленькі ракети", [4] = "Я володію секретами створення ракет Місячного фестивалю і з радістю поділюся своїми знаннями з достойними.\n\nВ обмін на монети предків я можу запропонувати тобі креслення маленьких ракет...", [5] = "Чудово. Ось твої креслення, {ім'я}, і хай благословить тебе Елуна.", ["en"] = "Small Rockets", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [8877] = { [1] = "Пускова установка для феєрверків", [4] = "Хоча ракети — чудовий спосіб святкувати, щоб побачити їх в повній красі... їх треба запустити з пускової установки.\n\nПринеси мені монети предків, і я зможу запропонувати тобі знання для створення ракетних установок, подібних до тих, що ти {стать:бачив:бачила} на Місячній галявині.", [5] = "Ось, тримай, {ім'я}. Це креслення пускової установки для феєрверків. Розмісти пускові установки там, де ти хочеш святкувати, а потім запроси друзів приєднатися!", ["en"] = "Firework Launcher", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [8878] = { [1] = "Святкові викройки", [4] = "Сукні та костюми, які ти бачиш тут, є традиційним одягом багатьох років. Їх носять на честь старих звичаїв і померлих близьких.\n\nЯкщо ти принесеш мені монети предків, {ім'я}, то я дам тобі викрійку для створення традиційних червоних суконь або костюмів.", [5] = "Ось викрійки, {ім'я}. Я впевнена, що тобі сподобаються речі, які ти створиш з ними.", ["en"] = "Festive Recipes", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [8879] = { [1] = "Великі ракети", [4] = "Великі фестивальні ракети яскраво освітлюють небо — з їхньою красою можуть позмагатися лише залпи ракет!\n\nПринеси мені монети предків, {ім'я}, і я поділюся знаннями про їх створення.", [5] = "Дуже добре — я приймаю ці монети предків. Ось твої креслення, {ім'я}. Нехай вони допоможуть тобі ширити славу Елуни!", ["en"] = "Large Rockets", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [888] = { [1] = "Вкрадене добро", [2] = "Хотів би я повернути всі свої речі, але це, напевно, неможливо. Але є кілька речей, які мені дуже потрібні!\n\nЯк бачиш, моя обсерваторія майже готова, але їй не вистачає одної з лінз. Перша з них прибула караваном з Дуротару, але другу везли на кораблі та вона так і не прибула. Крім того, я так і не отримав черевики від Мжичника з Грабіжної Бухти!\n\nРушай до піратського табору і пошукай їх.", [3] = "Поверніть Ґазлоу у Брашпиль посилку з чобітьми та лінзу від телескопа.", [4] = "Тобі вдалось знайти мої речі, {ім'я}?", [5] = "Як я радий повернути своє добро. Дякую тобі за допомогу, {ім'я}. Знаєш, мені б не завадили такі помічники, як ти. Якщо знадобиться робота, не забувай, що Ґазлоу непогано платить!", ["en"] = "Stolen Booty", ["tasks"] = { ["Shipment of Boots"] = "партія черевиків", ["Shipment of Boots (Provided)"] = "партія черевиків (видано)", ["Telescopic Lens"] = "лінза для телескопа", ["Telescopic Lens (Provided)"] = "лінза для телескопа (видано)" } },
    [8880] = { [1] = "Залпи ракет", [4] = "Залпи ракет — це набори з окремих ракет, і їхня краса вражає! Принесіть мені монети предків, і я поділюся з тобою знаннями про їх створення...", [5] = "Ось, тримай, {ім'я}. Візьми ці креслення та дізнайся їх секрети. Я бажаю тобі удачі та з нетерпінням чекаю на твої чудові творіння.", ["en"] = "Cluster Rockets", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [8881] = { [1] = "Залпи великих ракет", [4] = "Для створення залпів великих ракет потрібно багато ресурсів та неабиякі навички, але їхній блиск і краса варті цих зусиль! Принеси мені монети предків, і я поділюся з тобою знаннями про їх створення.", [5] = "Дякую, {ім'я}. Ось креслення залпів великих ракет. Нехай твої вироби приносять радість і удачу всім, хто на них дивиться.", ["en"] = "Large Cluster Rockets", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [8882] = { [1] = "Пускова установка для залпів феєрверків", [4] = "Щоб влаштувати найкращий феєрверк, потрібно використовувати залпи ракет, а випускати їх треба з відповідних пускових установок! Хіба не логічно буде тобі дізнатися секрети виготовлення пускової установки для залпів феєрверків? Принеси мені монети предків, і я поділюсь з тобою цими знаннями.", [5] = "Ось твої креслення. Вивчи їх уважно і навчись...\n\nЩасти тобі, {ім'я}. Нехай твої святкування не поступаються за розмахом самому Місячному фестивалю!", ["en"] = "Cluster Launcher", ["tasks"] = { ["Coin of Ancestry"] = "монета предків", ["Coin of Ancestry (Provided)"] = "монета предків (видано)" } },
    [8883] = { [1] = "Валадар Зорепісня", [2] = "Тепер, коли у тебе є запрошення на Місячний фестиваль, ти можеш вирушити на Місячну галявину! Там ти зустрінеш багатьох гуляк, а в поселенні Нічна Гавань Валадар Зорепісня та його сестра Фаріель чекають на тих, хто бажає приєднатися до святкування.\n\nПрямуй на Місячну галявину через яскраве місячне сяйво і поговори з Валадаром Зорепіснею. Дізнайся в нього, які призи ти можеш отримати під час фестивалю!", [3] = "Скористайтесь своїм запрошенням на Місячний фестиваль в місячному сяйві, щоб потрапити на Місячну галявину. Поговоріть з Валадаром Зорепіснею у Нічній Гавані, коли прибудете.", [5] = "{ім'я}, ласкаво просимо до Нічної Гавані, місця проведення Місячного фестивалю! Хоча наше поселення зазвичай ізольоване від інших народів Азероту, в цей святковий час ми відкриваємо наші двері та серця для всіх.\n\nПриємного святкування, {ім'я}, і звертайся до мене або до моєї сестри, коли будеш {стать:готовий:готова}.", ["en"] = "Valadar Starsong" },
    [8893] = { [1] = "Супер Яйц-Е-Мат", [4] = "Супер Яйц-Е-Мат — останній винахід Бульки Хисткоплиг. Ця машина вражає.\n\nСупер Яйц-Е-Мат несамовито шумить, коли ви наближаєтесь до панелі управління.", [5] = "Ви поміщаєте яйце гіпогрифа в машину. Після цього лунає кілька звукових сигналів і дивні механічні звуки.\n\nЦе означає, що яйцемір зважив, виміряв і запакував ваше яйце. Ось це швидке обслуговування!", ["en"] = "The Super Egg-O-Matic", ["tasks"] = { ["Hippogryph Egg"] = "яйце гіпогрифа", ["Hippogryph Egg (Provided)"] = "яйце гіпогрифа (видано)" } },
    [8897] = { [1] = "Люба Коларо,", [2] = "Я маю стояти тут та наглядати за воротами, але я завжди переймаюся через свою милу Колару. Я можу побачитися з нею лише на кілька годин, але це тільки якщо мені пощастить, але просто подивися на мене. Я отримую крихітну зарплату офіцера, і мене можуть забрати на фронт у будь-який день.\n\nЧи не забуде вона мене? В місті є багато чоловіків. Багато заможних чоловіків.\n\nУ будь-якому разі, я нашкрябав пару слів... нічого особливого, але якщо ти зможеш передати їй цю записку, це було б чудово.", [3] = "Доставте ретельно продуману записку лейтенанта Гелдріка до Колари Дін за банком Штормовію.", [4] = "Привітики, {стать:красеню:красуне}. Чим я можу тобі допомогти?", [5] = "Оу, це так мило! Це вперше, коли він мені прислав щось! Як гадаєш, він серйозно налаштований?\n\nКолара Гелдрік? Думаю, мені скоро знадобиться обручка! Ой, щось я надто кваплю події. Дякую тобі.", ["en"] = "Dearest Colara,", ["tasks"] = { ["Carefully Penned Note"] = "ретельно продумана записка", ["Carefully Penned Note (Provided)"] = "ретельно продумана записка (видано)" } },
    [8898] = { [1] = "Люба Коларо,", [2] = "Я зустрів дівчинку у Штормовії, коли я останній раз там був по банківським справам. Вона полонила моє серце. А тепер я не можу припинити думати про неї! Я хотів би послати їй листа. Я переписав його дванадцять разів!\n\nПошта зараз переповнена, а я хочу, щоб цей лист точно дійшов до неї.\n\nЯкщо ти ідеш у той бік, ти не {стать:міг:могла} би мені допомогти?", [3] = "Доставте пом'ятого листа Коларі Дін за банком Штормовію.", [4] = "Привітики, {стать:красеню:красуне}. Чим я можу тобі допомогти?", [5] = "Тормек? О, так, я пам'ятаю його. У нього була класна борода та красива посмішка.\n\nОх, не можу повірити, що він мене запам'ятав!", ["en"] = "Dearest Colara,", ["tasks"] = { ["Creased Letter"] = "пом'ятий лист", ["Creased Letter (Provided)"] = "пом'ятий лист (видано)" } },
    [890] = { [1] = "Зниклий вантаж", [2] = "Я вже цілу вічність чекаю на своє останнє замовлення з Грабіжної Бухти! Напевно його вкрали флібустьєри, але щоб знати напевно — сходи, будь ласка, в док і запитай Запаморока, чи не відправили мої товари на склад без мого відома?\n\nОсь, віднеси мій гросбух Запамороку, хай він звірить зі своїми записами.", [3] = "Принесіть гросбух Ґазлоу завідувачеві причалу Запамороку.", [4] = "Хочеш відправити товар на наступному кораблі, {ім'я}?", [5] = "А, то тебе прислав Ґазлоу, ге? Хвилинку, дай-но я зазирну у свої записи, треба переконатися, що я не відправив його товар не туди, куди треба.\n\nМабуть, він чекає на ті чоботи від Мжичника...", ["en"] = "The Missing Shipment", ["tasks"] = { ["Gazlowe's Ledger"] = "гросбух Ґазлоу", ["Gazlowe's Ledger (Provided)"] = "гросбух Ґазлоу (видано)" } },
    [8903] = { [1] = "Небезпечне кохання", [2] = "Є щось неприродне в цій епідемії кохання. Це якось неправильно, це щось потворне, ба більше, це може стати загрозою для безпеки самого Альянсу.\n\nПросто подумай: що, якщо вартові підкоряться цій дивній закоханості? Нам потрібно щось з цим робити.\n\nІди до одного з вартових Штормовію та подивися, чи не вплинула на нього ця лихоманка.", [3] = "Візьміть листівку вартового Штормовію та віддайте її Арістану Моттару у Штормовії.", [4] = "Чи мав я рацію? Вартових вже вразила ця любовна лихоманка?", [5] = "Тож це правда. Не можу в це повірити. Як це могло статися? Дай мені хвильку подумати. Цьому всьому має бути якась причина.", ["en"] = "Dangerous Love", ["tasks"] = { ["Stormwind Guard's Card"] = "листівка вартового Штормовію", ["Stormwind Guard's Card (Provided)"] = "листівка вартового Штормовію (видано)" } },
    [8904] = { [1] = "Небезпечне кохання", [2] = "Є щось неприродне в цій епідемії кохання. Це якось неправильно, це щось потворне, ба більше, це може стати загрозою для нашої безпеки.\n\nМало того, що купа жителів втягнуті в це божевілля. Але я думаю, що воно поширилось навіть на вартових, які повинні мати імунітет до таких речей.\n\nІди до одного з наших вартових та поглянь, чи не вплинула на нього ця лихоманка.", [3] = "Візьміть запліснявілу листівку вартового та віднесіть її Фенстаду Арґайлу в Підмістя.", [4] = "Чи мав я рацію? Наших дурнів-вартових вже вразила ця хвороба?", [5] = "Тож це правда. Не можу в це повірити. Як це могло статися? Дай мені хвильку подумати. Цьому всьому має бути якась причина.", ["en"] = "Dangerous Love", ["tasks"] = { ["Guardian's Moldy Card"] = "запліснявіла листівка вартового", ["Guardian's Moldy Card (Provided)"] = "запліснявіла листівка вартового (видано)" } },
    [8908] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}. Я маю дещо, що може тебе зацікавити.\n\nВ мене є набір обладунків, схожих на ті, що зазвичай носять представники твого ремесла, але значно вищої якості. Я б охоче віддала тобі їх в обмін на невеличку послугу.\n\nКров кригозубів та ведмедів, що населяють Зимоключ, має властивості, які мені зараз дуже необхідні. Принеси мені вдосталь зразків крові разом з поручами та невеликою кількістю золота. Побачиш — воно того варте.", [3] = "Зберіть 15 зразків крові із Зимоключа та 20 золотих і принесіть їх разом зі світлокованими браслетами Деліані в Залізогарт.", [4] = "Ти {стать:приніс:принесла} мені все необхідне, {ім'я}?", [5] = "Прекрасно! Тоді міняємось. Шкода віддавати такі чудові обладунки, та певно вони мені й не знадобляться.\n\nЯкщо погодишся виконати ще кілька доручень, я з радістю віддам тобі інші частини обладунку.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Lightforge Bracers"] = "світлоковані браслети", ["Lightforge Bracers (Provided)"] = "світлоковані браслети (видано)", ["Winterspring Blood Sample"] = "зразок крові із Зимоключа", ["Winterspring Blood Sample (Provided)"] = "зразок крові із Зимоключа (видано)" } },
    [8914] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}! По тобі видно, що тобі чимало довелося побачити і зробити в цьому світі. Але б'юся об заклад, що таких обладунків, як ці, ти ще не {стать:бачив:бачила}!\n\nЗроби мені невелику послугу, і я віддам їх тобі в обмін на звичайний набір браслетів.\n\nМені потрібен зразок отрути павуків і скорпіонів, що мешкають у Силітусі. Принеси його мені разом з кількома золотими монетами, і браслети твої.", [3] = "Зберіть 15 зразків отрути з Силітуса та 20 золотих і принесіть їх разом з браслетами ловця звірів Моквару в Орґріммар.", [4] = "Ти {стать:зібрав:зібрала} все необхідне, {ім'я}?", [5] = "О, так. Мукс буде в захваті.\n\nЦі браслети — частина більшого набору обладунків. Якщо ти погодишся допомагати мені й далі, я готовий розглянути можливість віддати тобі й решту.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Beaststalker's Bindings"] = "браслети ловця звірів", ["Beaststalker's Bindings (Provided)"] = "браслети ловця звірів (видано)", ["Silithus Venom Sample"] = "зразок отрути з Силітуса", ["Silithus Venom Sample (Provided)"] = "зразок отрути з Силітуса (видано)" } },
    [8916] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}! По тобі видно, що тобі чимало довелося побачити і зробити в цьому світі. Але б'юся об заклад, що таких обладунків, як ці, ти ще не {стать:бачив:бачила}!\n\nЗроби мені невелику послугу, і я віддам їх тобі в обмін на звичайний набір поручів.\n\nМені потрібен зразок отрути павуків і скорпіонів, що мешкають у Силітусі. Принеси його мені разом з кількома золотими монетами, і поручі твої.", [3] = "Зберіть 15 зразків отрути з Силітуса та 20 золотих і принесіть їх разом з браслетами відданості Моквару в Орґріммар.", [4] = "Ти {стать:зібрав:зібрала} все необхідне, {ім'я}?", [5] = "О, так. Мукс буде в захваті.\n\nЦі поручі — частина більшого набору обладунків. Якщо ти погодишся допомагати мені й далі, я готовий розглянути можливість віддати тобі й решту.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Devout Bracers"] = "браслети відданості", ["Devout Bracers (Provided)"] = "браслети відданості (видано)", ["Silithus Venom Sample"] = "зразок отрути з Силітуса", ["Silithus Venom Sample (Provided)"] = "зразок отрути з Силітуса (видано)" } },
    [8918] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}! По тобі видно, що тобі чимало довелося побачити і зробити в цьому світі. Але б'юся об заклад, що таких обладунків, як ці, ти ще не {стать:бачив:бачила}!\n\nЗроби мені невелику послугу, і я віддам їх тобі в обмін на звичайний набір браслетів.\n\nМені потрібен зразок отрути павуків і скорпіонів, що мешкають у Силітусі. Принеси його мені разом з кількома золотими монетами, і браслети твої.", [3] = "Зберіть 15 зразків отрути з Силітуса та 20 золотих і принесіть їх разом з браслетами стихій Моквару в Орґріммар.", [4] = "Ти {стать:зібрав:зібрала} все необхідне, {ім'я}?", [5] = "О, так. Цей старий гоблін буде в захваті.\n\nЦі браслети — частина більшого набору обладунків. Якщо ти погодишся допомагати мені й далі, я готовий розглянути можливість віддати тобі й решту.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Bindings of Elements"] = "браслети стихій", ["Bindings of Elements (Provided)"] = "браслети стихій (видано)", ["Silithus Venom Sample"] = "зразок отрути з Силітуса", ["Silithus Venom Sample (Provided)"] = "зразок отрути з Силітуса (видано)" } },
    [8919] = { [1] = "Серйозна пропозиція", [2] = "Вітаю, {клас:к}! По тобі видно, що тобі чимало довелося побачити і зробити в цьому світі. Але б'юся об заклад, що таких обладунків, як ці, ти ще не {стать:бачив:бачила}!\n\nЗроби мені невелику послугу, і я віддам їх тобі в обмін на звичайний набір поручів.\n\nМені потрібен зразок отрути павуків і скорпіонів, що мешкають у Силітусі. Принеси його мені разом з кількома золотими монетами, і поручі твої.", [3] = "Зберіть 15 зразків отрути з Силітуса та 20 золотих і принесіть їх разом з браслетами імли жаху Моквару в Орґріммар.", [4] = "Ти {стать:зібрав:зібрала} все необхідне, {ім'я}?", [5] = "О, так. Мукс буде в захваті.\n\nЦі поручі — частина більшого набору обладунків. Якщо ти погодишся допомагати мені й далі, я готовий розглянути можливість віддати тобі й решту.", ["en"] = "An Earnest Proposition", ["tasks"] = { ["Dreadmist Bracers"] = "браслети імли жаху", ["Dreadmist Bracers (Provided)"] = "браслети імли жаху (видано)", ["Silithus Venom Sample"] = "зразок отрути з Силітуса", ["Silithus Venom Sample (Provided)"] = "зразок отрути з Силітуса (видано)" } },
    [892] = { [1] = "Зниклий вантаж", [2] = "У мене в записах усе гаразд, {ім'я}. Йди до Ґазлоу і скажи, що йому не пощастило. Не здивуюся, якщо його товари прибрали до рук пірати.\n\nЯ більше нічим не можу йому допомогти. Хоча... Скажи, що в мене є для нього дещо з Підштольні, хай приходить і забирає.", [3] = "Поверніть Ґазлоу в Брашпиль його гросбух.", [4] = "Ну, що сказав Запаморок?", [5] = "Не пощастило, ге? Мабуть, це були флібустьєри... Запамороку я вірю, він би мене так не обдурив. Зрештою, він на зарплаті.\n\nЗдається, мені доведеться дещо повернути, {ім'я}. Що скажеш?", ["en"] = "The Missing Shipment", ["tasks"] = { ["Gazlowe's Ledger"] = "гросбух Ґазлоу", ["Gazlowe's Ledger (Provided)"] = "гросбух Ґазлоу (видано)" } },
    [8921] = { [1] = "Ектоплазматичний дистилятор", [2] = "А, тобі потрібен мій останній проєкт... міжвимірний шукач привидів! На жаль, мені не вистачає ресурсів та робочої сили.\n\nХочеш допомогти? Чудово! Перш за все, ми маємо побудувати пристрій, який збиратиме саму сутність смерті! Створення ектоплазматичного дистилятора буде непростою справою, {ім'я}.\n\nМені потрібно, щоб ти {стать:приніс:принесла} мені чутливий арканітовий перетворювач, кілька великих вічних субстанцій, та олію камнелуского вугра. Також для фільтра мені знадобиться вулканічний попіл зі ставів лави, що в Палаючому степі.", [3] = "Принесіть Муксу Маношкрябу в Пристроблях 1 чутливий арканітовий перетворювач, 4 великі вічні субстанції, 10 порцій олії камнелуского вугра, 25 пригорщ вулканічного попелу та 40 золотих.", [4] = "Я розумію, що матеріали дещо дорогі... але я чесно кажу тобі, вони всі необхідні!", [5] = "Це саме те, що мені потрібно. І ти вчасно, {ім'я}!\n\nЗа кілька хвилин дистилятор буде готовий до роботи! А поки візьми це як винагороду за участь у моєму проєкті.", ["en"] = "The Ectoplasmic Distiller", ["tasks"] = { ["Delicate Arcanite Converter"] = "чутливий арканітовий перетворювач", ["Delicate Arcanite Converter (Provided)"] = "чутливий арканітовий перетворювач (видано)", ["Greater Eternal Essence"] = "велика вічна субстанція", ["Greater Eternal Essence (Provided)"] = "велика вічна субстанція (видано)", ["Stonescale Oil"] = "олія камнелуского вугра", ["Stonescale Oil (Provided)"] = "олія камнелуского вугра (видано)", ["Volcanic Ash"] = "вулканічний попіл", ["Volcanic Ash (Provided)"] = "вулканічний попіл (видано)" } },
    [89224] = { [1] = "Дефіцит продовольства", [2] = "<Шеф-кухар починає говорити, перш ніж ви встигаєте вимовити просте привітання.>\n\nСлава світлу, допомога нарешті прибула! Ні плита, ні комора не можуть впоратися з раптовим напливом замовлень. Щось сталося, що перервало наші звичайні лінії постачання, і я припускаю, що всі крики зовні якось пов'язані з цим.\n\nЯкою б не була причина, мені потрібна допомога. Негайно. Принесіть мені щось, що виглядає хоч трохи їстівним, звідкись у місті, і ми почнемо звідти.", [3] = "Зберіть неапетитні залишки їжі по всьому Новому Авалону та поверніть їх шеф-кухарю. Якщо у вас виникають проблеми з їх пошуком, можливо, вам краще вдасться вирішити цю нестачу за допомогою насильства.", [4] = "Будь ласка, залиште мене в спокої, поки ви не зберете деякі інгредієнти.", [5] = "О. О... Я очікувала вчорашнього хліба, перестиглих фруктів і, можливо, тарілку недоїденого печива чи щось таке.\n\nЯ справді не маю жодного уявлення, що колись було з цих страв, а я їх готувала! А цей... запах... Ви намагаєтеся саботувати мою кухню?\n\nГлибокий вдих, Керрі...\n<Шеф-кухарка заплющує очі та повільно вдихає через ніздрі, через мить тихо видихаючи.>\n\nСпробуємо ще раз.", ["en"] = "Food Shortage" },
    [89229] = { [1] = "Правильний шлях", [2] = "Тепер ти знаєш усю історію. Переживати все це знову було боляче, але я надто довго відкладав це. Як не дивно, я почуваюся... краще. Я так довго молився про справедливість, але її здійснення — не мій тягар. Я обрав свій власний шлях, і якщо помста затягне мене назад у темряву, це не принесе мені миру, ані не виконає бажань мого сина.\n\nЯ повертаюся, щоб передати свій звіт лорду Тиросусу. Побачимося в «Надії Світла». У мене там є щось для тебе.", [3] = "Поговоріть з Леонідом Варфаломієм Шановним у каплиці Світлої Надії, щоб отримати свою нагороду.", [5] = "Розплата Калдорана врешті-решт прийде, оскільки його зло зрештою саморуйнівне. Я вірю в це, так само як вірю в мрію свого сина.\n\nБудь ласка, візьміть це. Це мені дала Ліліана, коли мене прийняли до Срібної Руки, і це добре послужило мені нагадуванням про мої клятви родині та країні протягом років служби. Сподіваюся, це послужить нагадуванням про те, що найтемніше перед світанком, але світанок завжди настане.", ["en"] = "The Right Path" },
    [89232] = { [1] = "Перший крок", [2] = "У своїй гордині Калдоран думав, що зможе змусити клинок підкоритися його волі. Він вкрав життя своїх найпалкіших послідовників, щоб підживити свою спробу підкорити клинок. Він не усвідомлював, що цю силу не можна завоювати силою; її очищення потрібно заслужити.\n\nПоговоріть зі мною далі, якщо хочете побачити повернений клинок. Якщо ви достатньо сильні, можливо, вам це вдасться.", [4] = "<Спектральний контур Волі Попелоносця змінюється та тремтить тривожним чином.>", [5] = "Тож тепер розумієш? Ти мусиш довести це до кінця, а цей кінець далеко не певний. Якщо ти хочеш побачити це завдання завершеним, то ти повинен мати мужність навіть перед обличчям цієї невизначеності.\n\nЧи маєш ти таку мужність?", ["en"] = "The First Step" },
    [89234] = { [1] = "Особиста справа", [2] = "Те, про що ми говорили в «Надії світла» та моя історія з Калдораном... Все почалося саме тут, у Стратголмі. Ви ж знайомі з «винищенням» Стратголма, яке відбулося на початку Третьої війни, так?\n\nНу, я був тут, і Калдоран також. Саме тут починається наша історія. Якщо ви не заперечуєте, зустріньте мене біля службового входу Стратголма на сході.", [3] = "Зустріньте Леоніда Варфаломія Преподобного одразу за вхідною брамою для служби на схід від головних воріт Стратгольма.", [5] = "Я радий, що ти прийшов. Не знаю, чи зміг би я сам зробити те, що буде далі.", ["en"] = "A Personal Matter" },
    [89235] = { [1] = "Вибракування", [2] = "Місто позаду нас – це місце з привидами. Я провів тут роки після своєї першої смерті, будучи рабом Короля-Ліча, але навіть у своєму рабстві я зберігав певну свідомість. Незліченну кількість разів я хитався повз тіло своєї дружини, назавжди застиглий у страху, який вона відчувала, коли настав кінець.\n\nБудь ласка, пройдіть через ворота, що ведуть до району, відомого зараз як Площа Бійні. Я зустрінуся з вами там, коли знайду свою рішучість. Для цього вам знадобляться союзники.", [3] = "Увійдіть до Стратголма та пройдіть через ворота, що ведуть на площу Слотер, де знайдете Леоніда Варфаломія Шановного.", [5] = "Тож тепер ти розумієш, чому я зневажаю Калдорана. Він людина ненависного фанатика. Він був таким тоді, і він є зараз. Калдоран не супроводжував експедицію Артаса до Нортренда, але я дуже бажаю, щоб він знайшов там свій кінець, і це був кінець нашої спільної історії.", ["en"] = "The Culling" },
    [89236] = { [1] = "Сварливі яблука", [2] = "Якщо мене питаєте, свіжі фрукти – це родзинка будь-якої трапези. Яблука – мої улюблені, і, до речі, на південь від нас є квітучий сад.\n\nЯкщо припустити, що він ще не загорівся – що цілком можливо – б'юся об заклад, що вже час збирати врожай!\n\nЗазвичай фермери готові зробити мені знижку, але я все одно винен їм пиріг. Купити їх дешево – неможливе, але схоже, що ти можеш собі їх дозволити.", [3] = "Знайдіть яблуневий сад у південній частині Нового Авалона, щоб принести яблук. Після досягнення успіху поверніться до Керрі Хартфайр у корчмі Нового Авалона. Якщо яблука вам здаються занадто дорогими, подумайте про альтернативний спосіб їх придбання.", [4] = "Незважаючи на те, що я живу за крок від фруктового саду, іноді буває напрочуд важко дістати яблука.", [5] = "<Керрі ретельно оглядає кожне яблуко на наявність недоліків. Тим часом мовчання довге та незручне.>\n\nУ тебе є око на якість, коли ти не риєшся у смітті. Це найсвіжіші яблука, які я бачила з часів своєї молодості в монастирі!\n\nМушу зізнатися, я була готова скасувати твоє членство після першої ж поставки. Продовжуй у тому ж дусі, і мені, можливо, доведеться запропонувати тобі постійну посаду.", ["en"] = "Wrangling Apples" },
    [89237] = { [1] = "Це може дорого обійтися...", [2] = "Щоб створити цей сплав, нам знадобиться багато матеріалів для експериментів. Я підготував список і, ну, я ж казав тобі, що це може бути дорого.\n\n<Омаріон передає тобі список, який майже такий же довгий, як твоє передпліччя.>", [3] = "Принесіть майстру-реміснику Омаріону 20 злитків арканіту, 20 злитків торію, настояних на обсидіані, 120 злитків справжнього срібла, 10 величезних смарагдів та 20 сфер праведності.", [4] = "Послухайте, створення металургійних чудес не відбувається просто так. Вам потрібен час, терпіння та хтось із глибокими гаманцями.", [5] = "Від думки про ціну всього цього в мене трохи сльозяться очі. Ну що ж, нічого не ризикнув, нічого не отримав.", ["en"] = "This Could Get Expensive..." },
    [8924] = { [1] = "Полювання на ектоплазму", [2] = "Чудова інженерна робота, скажу я! Боюся, тобі доведеться трохи помандрувати, щоб знайти потрібних нам безтілесних невмерлих.\n\nРозумієш, різні клімати по-різному впливають на спектральну сутність мертвих. Замучені нічні ельфи Силітуса, духи високородних із Зимоключа і привиди та банші Східних Зачумлених земель дадуть нам різні види ектоплазми, які нам і потрібні. Обов'язково розмісти дистилятор неподалік, перш ніж почати збір!", [3] = "Використайте ектоплазматичний дистилятор біля безтілесних невмерлих, щоб зібрати 12 обпаленої ектоплазми у Силітусі, 12 замороженої ектоплазми у Зимоключі та 12 стабільної ектоплазми у Східних Зачумлених землях. Принесіть їх разом з ектоплазматичним дистилятором Муксу Маношкрябу в Пристроблях.", [4] = "Ти вже {стать:зібрав:зібрала} ектоплазму, {раса:к}?", [5] = "Так, чудові зразки!\n\nВикористовуючи потойбічну енергію, що міститься в цих речовинах, ми зможемо зв'язатись з душами, які ще не покинули цей світ!", ["en"] = "Hunting for Ectoplasm", ["tasks"] = { ["Ectoplasmic Distiller"] = "ектоплазматичний дистилятор", ["Ectoplasmic Distiller (Provided)"] = "ектоплазматичний дистилятор (видано)", ["Frozen Ectoplasm"] = "заморожена ектоплазма", ["Frozen Ectoplasm (Provided)"] = "заморожена ектоплазма (видано)", ["Scorched Ectoplasm"] = "обпалена ектоплазма", ["Scorched Ectoplasm (Provided)"] = "обпалена ектоплазма (видано)", ["Stable Ectoplasm"] = "стабільна ектоплазма", ["Stable Ectoplasm (Provided)"] = "стабільна ектоплазма (видано)" } },
    [89245] = { [1] = "Риба в бочці", [2] = "Я деякий час служив у Хартглені, і не можу передати словами, наскільки жахливо було покладатися на поставки з Чумних земель, щоб забезпечити себе їжею. Стабільний ланцюг постачання моря для Нового Авалону був благословенням, принаймні донедавна.\n\nУ черговому випадку «Керрі намагається нагодувати армію, маючи кухню, забезпечену для сім'ї», мені потрібна риба. Перевірте док на півдні, щоб дізнатися, чи прибуло моє замовлення.", [3] = "Дослідіть човен, що пришвартувався на південь від Нового Авалона для перевезення риби, і поверніть улов Керрі.", [4] = "Я вже згадував, що ненавиджу запах риби? Можливо, варто попросити тебе взяти прищіпку, поки ти будеш удома.", [5] = "Я не впізнаю деяких із них, але риба є риба, мабуть. У будь-якому разі, я вже з нетерпінням чекаю, коли все це буде зі моєї кухні.\n\nДякую за вашу допомогу, навіть якщо це було завдання, на яке я насправді сподівався, що ви повернетеся з порожніми руками.", ["en"] = "Fish in a Barrel" },
    [8925] = { [1] = "Портативне джерело енергії", [2] = "Тепер нам потрібно знайти стабільне та портативне джерело енергії, щоб підтримувати активність ектоплазми. Я чув про могутнього елементаля, на ім'я Бокк, серцем якого є потужне магматичне ядро — нескінченне джерело жару!\n\nКажуть, що його можна знайти в Палаючому степі, що на південь від Чорноскельної гори. Принеси мені магматичне ядро, і ми матимемо вдосталь енергії для живлення міжвимірного шукача привидів!", [3] = "Знайдіть повелителя магми Бокка в Палаючому Степі, добудьте його магматичне ядро та принесіть його Муксу Маношкрябу в Пристроблях.", [4] = "Ти {стать:знайшов:знайшла} повелителя магми, {ім'я}?", [5] = "Тобі вдалось! Тепер у нас буде достатньо енергії, щоб активувати міжвимірний шукач привидів!", ["en"] = "A Portable Power Source", ["tasks"] = { ["Magma Core"] = "магматичне ядро", ["Magma Core (Provided)"] = "магматичне ядро (видано)" } },
    [89253] = { [1] = "Основна страва", [2] = "Жодна трапеза не обходиться без зірки страви — м’яса! Як ви, мабуть, можете собі уявити, полювання на безпечне для споживання м’ясо в Чумних землях — це неперевершене випробування.\n\nЩо ще гірше, наші гончі їдять тільки м’ясо! Я впевнений, що ви розумієте, до чого це призводить, і я впевнений, що тепер ви розумієте, чому я постійно відстаю.\n\nНу що ж? Чого ви чекаєте?", [3] = "Здобувайте м'ясо, безпечне для споживання людиною. Якщо вам важко знайти його в Новому Авалоні, ви можете (зрештою) зібрати достатньо, вбиваючи звірів у Східних Чумних Землях.", [4] = "Вже повернувся? Це ж не може бути добре.", [5] = "Ваша оперативність викликає похвалу, але викликає підозру; майже таку ж підозру, як і колір цих шматків м'яса. На щастя, за час перебування тут ми всі зміцніли шлунки.\n\nКілька шматочків тут, дрібка спецій там, і ніхто нічого не помітить.\n\nСподіваюся, цього буде достатньо. Дякую.", ["en"] = "Main Course" },
    [89255] = { [1] = "Доведіть свою цінність: головний убір", [2] = "Підтримка високого стандарту якості має вирішальне значення для підтримки високого стандарту якості. Наші солдати довіряють своє життя неназваним майстрам, а мені — за забезпечення якості кожного обладунку.\n\nМоє завдання для вас просте. Якщо ви добре володієте кравецькою, шкіряною або ковальською справою, тоді створіть головний убір виключно для власної вигоди. Ви можете залишити результат собі.\n\nЯкщо вам бракує навичок, замовте та пожертвуйте будь-який елемент уніформи хрестового походу.", [3] = "Зробіть предмет Червоного Головного Убору з будь-якої професії з виготовлення броні або пожертвуйте будь-який предмет виготовленого спорядження Червоної Уніформи.\n\nЯкщо ви вирішите зробити пожертву, ви можете знайти ящик біля квартирмейстера всередині казарми. Доставте предмет у ящику назад до Брайона Сталевого Клинка, щоб отримати кредит.\n\nНаданий предмет:", [4] = "Створюйте ремесло чи робіть свій внесок; вибір за вами. Наша зброя добре оснащена для будь-яких випробувань, але важливо забезпечити нашим майстрам достатньо можливостей для практики та вдосконалення своєї техніки.", [5] = "Чудово зроблено.\n\nМи почали складати конфіскований мотлох у ці старі скрині, і в мене вже закінчується місце для його зберігання, але ви, здається, з тих, хто цінує дрібниці. Я вважаю, що це гідна винагорода за один внесок.\n\nО, і я додав цінний сюрприз до кількох із них. Можливо, саме ви будете одним із щасливчиків?", ["en"] = "Prove Your Worth: Headgear" },
    [89256] = { [1] = "Доведіть свою цінність: наплічники", [2] = "Підтримка високого стандарту якості має вирішальне значення для підтримки високого стандарту якості. Наші солдати довіряють своє життя неназваним майстрам, а мені — за забезпечення якості кожного обладунку.\n\nМоє завдання для вас просте. Якщо ви добре володієте кравецькою, шкіряною або ковальською справою, тоді зробіть пару наплічників виключно для власної вигоди. Ви можете залишити результат собі.\n\nЯкщо вам бракує навичок, замовте та пожертвуйте будь-який елемент уніформи хрестового походу.", [3] = "Зробіть фрагмент Червоних Наплечників з будь-якої професії з виготовлення обладунків або пожертвуйте будь-який фрагмент виготовленого спорядження Червоної Уніформи.\n\nЯкщо ви вирішите зробити пожертву, ви можете знайти ящик біля квартирмейстера всередині казарми. Доставте предмет у ящику назад до Брайона Сталевого Клинка, щоб отримати кредит.\n\nНаданий предмет:", [4] = "Створюйте ремесло чи робіть свій внесок; вибір за вами. Наша зброя добре оснащена для будь-яких випробувань, але важливо забезпечити нашим майстрам достатньо можливостей для практики та вдосконалення своєї техніки.", [5] = "Чудово зроблено.\n\nМи почали складати конфіскований мотлох у ці старі скрині, і в мене вже закінчується місце для його зберігання, але ви, здається, з тих, хто цінує дрібниці. Я вважаю, що це гідна винагорода за один внесок.\n\nО, і я додав цінний сюрприз до кількох із них. Можливо, саме ви будете одним із щасливчиків?", ["en"] = "Prove Your Worth: Shoulderpads", ["tasks"] = { ["Quartermaster's Crate"] = "Ящик квартирмейстера" } },
    [89257] = { [1] = "Доведіть свою цінність: нагрудник", [2] = "Підтримка високого стандарту якості має вирішальне значення для підтримки високого стандарту якості. Наші солдати довіряють своє життя неназваним майстрам, а мені — за забезпечення якості кожного обладунку.\n\nМоє завдання для вас просте. Якщо ви добре володієте кравецькою, шкіряною або ковальською справою, тоді виготовте нагрудник виключно для власної вигоди. Ви можете залишити результат собі.\n\nЯкщо вам бракує навичок, замовте та пожертвуйте будь-який елемент уніформи хрестового походу.", [3] = "Створіть Червоний нагрудник з будь-якої професії з виготовлення обладунків або пожертвуйте будь-який предмет виготовленого спорядження Червоної уніформи.\n\nЯкщо ви вирішите зробити пожертву, ви можете знайти ящик біля квартирмейстера всередині казарми. Доставте предмет у ящику назад до Брайона Сталевого Клинка, щоб отримати кредит.\n\nНаданий предмет:", [4] = "Створюйте ремесло чи робіть свій внесок; вибір за вами. Наша зброя добре оснащена для будь-яких випробувань, але важливо забезпечити нашим майстрам достатньо можливостей для практики та вдосконалення своєї техніки.", [5] = "Чудово зроблено.\n\nМи почали складати конфіскований мотлох у ці старі скрині, і в мене вже закінчується місце для його зберігання, але ви, здається, з тих, хто цінує дрібниці. Я вважаю, що це гідна винагорода за один внесок.\n\nО, і я додав цінний сюрприз до кількох із них. Можливо, саме ви будете одним із щасливчиків?", ["en"] = "Prove Your Worth: Chestpiece" },
    [89258] = { [1] = "Доведіть свою цінність: наручники", [2] = "Підтримка високого стандарту якості має вирішальне значення для підтримки високого стандарту якості. Наші солдати довіряють своє життя неназваним майстрам, а мені — за забезпечення якості кожного обладунку.\n\nМоє завдання для вас просте. Якщо ви добре володієте кравецькою, шкіряною або ковальською справою, тоді виготовте пару наручів виключно для власної вигоди. Ви можете залишити результат собі.\n\nЯкщо вам бракує навичок, замовте та пожертвуйте будь-який елемент уніформи хрестового походу.", [3] = "Зробіть пару Червоних Наручів з будь-якої професії з виготовлення обладунків або пожертвуйте будь-який предмет виготовленого спорядження Червоної Уніформи.\n\nЯкщо ви вирішите зробити пожертву, ви можете знайти ящик біля квартирмейстера всередині казарми. Доставте предмет у ящику назад до Брайона Сталевого Клинка, щоб отримати кредит.\n\nНаданий предмет:", [4] = "Створюйте ремесло чи робіть свій внесок; вибір за вами. Наша зброя добре оснащена для будь-яких випробувань, але важливо забезпечити нашим майстрам достатньо можливостей для практики та вдосконалення своєї техніки.", [5] = "Чудово зроблено.\n\nМи почали складати конфіскований мотлох у ці старі скрині, і в мене вже закінчується місце для його зберігання, але ви, здається, з тих, хто цінує дрібниці. Я вважаю, що це гідна винагорода за один внесок.\n\nО, і я додав цінний сюрприз до кількох із них. Можливо, саме ви будете одним із щасливчиків?", ["en"] = "Prove Your Worth: Wristguards" },
    [89259] = { [1] = "Доведіть свою цінність: рукавички", [2] = "Підтримка високого стандарту якості має вирішальне значення для підтримки високого стандарту якості. Наші солдати довіряють своє життя неназваним майстрам, а мені — за забезпечення якості кожного обладунку.\n\nМоє завдання для вас просте. Якщо ви добре володієте кравецькою, шкіряною або ковальською справою, тоді зробіть пару рукавичок виключно для власної вигоди. Ви можете залишити результат собі.\n\nЯкщо вам бракує навичок, замовте та пожертвуйте будь-який елемент уніформи хрестового походу.", [3] = "Зробіть пару Червоних Рукавиць з будь-якої професії з виготовлення обладунків або пожертвуйте будь-який предмет виготовленого спорядження Червоної Уніформи.\n\nЯкщо ви вирішите зробити пожертву, ви можете знайти ящик біля квартирмейстера всередині казарми. Доставте предмет у ящику назад до Брайона Сталевого Клинка, щоб отримати кредит.\n\nНаданий предмет:", [4] = "Створюйте ремесло чи робіть свій внесок; вибір за вами. Наша зброя добре оснащена для будь-яких випробувань, але важливо забезпечити нашим майстрам достатньо можливостей для практики та вдосконалення своєї техніки.", [5] = "Чудово зроблено.\n\nМи почали складати конфіскований мотлох у ці старі скрині, і в мене вже закінчується місце для його зберігання, але ви, здається, з тих, хто цінує дрібниці. Я вважаю, що це гідна винагорода за один внесок.\n\nО, і я додав цінний сюрприз до кількох із них. Можливо, саме ви будете одним із щасливчиків?", ["en"] = "Prove Your Worth: Gloves" },
    [89260] = { [1] = "Доведіть свою цінність: пояс", [2] = "Підтримка високого стандарту якості має вирішальне значення для підтримки високого стандарту якості. Наші солдати довіряють своє життя неназваним майстрам, а мені — за забезпечення якості кожного обладунку.\n\nМоє завдання для вас просте. Якщо ви добре володієте кравецькою, шкіряною або ковальською справою, тоді виготовте пояс виключно для власної вигоди. Ви можете залишити результат собі.\n\nЯкщо вам бракує навичок, замовте та пожертвуйте будь-який елемент уніформи хрестового походу.", [3] = "Створіть Червоний Пояс з будь-якої професії, пов'язаної з виготовленням обладунків, або пожертвуйте будь-який предмет виготовленого спорядження Червоної Уніформи.\n\nЯкщо ви вирішите зробити пожертву, ви можете знайти ящик біля квартирмейстера всередині казарми. Доставте предмет у ящику назад до Брайона Сталевого Клинка, щоб отримати кредит.\n\nНаданий предмет:", [4] = "Створюйте ремесло чи робіть свій внесок; вибір за вами. Наша зброя добре оснащена для будь-яких випробувань, але важливо забезпечити нашим майстрам достатньо можливостей для практики та вдосконалення своєї техніки.", [5] = "Чудово зроблено.\n\nМи почали складати конфіскований мотлох у ці старі скрині, і в мене вже закінчується місце для його зберігання, але ви, здається, з тих, хто цінує дрібниці. Я вважаю, що це гідна винагорода за один внесок.\n\nО, і я додав цінний сюрприз до кількох із них. Можливо, саме ви будете одним із щасливчиків?", ["en"] = "Prove Your Worth: Belt" },
    [89261] = { [1] = "Доведіть свою цінність: набедреники", [2] = "Підтримка високого стандарту якості має вирішальне значення для підтримки високого стандарту якості. Наші солдати довіряють своє життя неназваним майстрам, а мені — за забезпечення якості кожного обладунку.\n\nМоє завдання для вас просте. Якщо ви добре володієте кравецькою, шкіряною або ковальською справою, тоді зробіть пару штанів виключно для власної вигоди. Ви можете залишити собі результат.\n\nЯкщо вам бракує навичок, замовте та пожертвуйте будь-який предмет уніформи хрестового походу.", [3] = "Створіть пару Червоних Штанів з будь-якої професії з виготовлення броні або пожертвуйте будь-який предмет виготовленого спорядження Червоної Уніформи.\n\nЯкщо ви вирішите зробити пожертву, ви можете знайти ящик біля квартирмейстера всередині казарми. Доставте предмет у ящику назад до Брайона Сталевого Клинка, щоб отримати кредит.\n\nНаданий предмет:", [4] = "Створюйте ремесло чи робіть свій внесок; вибір за вами. Наша зброя добре оснащена для будь-яких випробувань, але важливо забезпечити нашим майстрам достатньо можливостей для практики та вдосконалення своєї техніки.", [5] = "Чудово зроблено.\n\nМи почали складати конфіскований мотлох у ці старі скрині, і в мене вже закінчується місце для його зберігання, але ви, здається, з тих, хто цінує дрібниці. Я вважаю, що це гідна винагорода за один внесок.\n\nО, і я додав цінний сюрприз до кількох із них. Можливо, саме ви будете одним із щасливчиків?", ["en"] = "Prove Your Worth: Legguards" },
    [89262] = { [1] = "Доведіть свою цінність: Чоботи", [2] = "Підтримка високого стандарту якості має вирішальне значення для підтримки високого стандарту якості. Наші солдати довіряють своє життя неназваним майстрам, а мені — за забезпечення якості кожного обладунку.\n\nМоє завдання для вас просте. Якщо ви добре володієте кравецькою, шкіряною або ковальською справою, тоді зробіть пару взуття виключно для власної вигоди. Ви можете залишити результат собі.\n\nЯкщо вам бракує навичок, замовте та пожертвуйте будь-який предмет уніформи хрестового походу.", [3] = "Зробіть пару Червоних Чоботи з будь-якої професії з виготовлення обладунків або пожертвуйте будь-який предмет виготовленого спорядження Червоної Уніформи.\n\nЯкщо ви вирішите зробити пожертву, ви можете знайти ящик біля квартирмейстера всередині казарми. Доставте предмет у ящику назад до Брайона Сталевого Клинка, щоб отримати кредит.\n\nНаданий предмет:", [4] = "Створюйте ремесло чи робіть свій внесок; вибір за вами. Наша зброя добре оснащена для будь-яких випробувань, але важливо забезпечити нашим майстрам достатньо можливостей для практики та вдосконалення своєї техніки.", [5] = "Чудово зроблено.\n\nМи почали складати конфіскований мотлох у ці старі скрині, і в мене вже закінчується місце для його зберігання, але ви, здається, з тих, хто цінує дрібниці. Я вважаю, що це гідна винагорода за один внесок.\n\nО, і я додав цінний сюрприз до кількох із них. Можливо, саме ви будете одним із щасливчиків?", ["en"] = "Prove Your Worth: Boots" },
    [8928] = { [1] = "Верткий торговець", [2] = "Ядро забезпечить нас достатньою кількістю енергії для живлення пристрою. Залишається знайти стрижень, який направлятиме її та при цьому не розплавиться.\n\nЯ зустрів у Зимоключі біса, який продавав усілякі екзотичні товари. У нього був стихійний стрижень, який нам має підійти. Ех, шкода, що я не купив його тоді.\n\nВін живе в печері біля входу в ущелину Темного шепоту. Проберись туди та спробуй знайти його.\n\nІ не давай йому більш як сорок золотих — це ціна, яку він назвав мені!", [3] = "Знайдіть біса в печері біля входу до ущелини Темного шепоту на півдні Зимоключа, купіть скверно-стихійний стрижень та поверніться до Мукса Маношкряба в Пристроблях.", [4] = "Ну як, вдалося знайти біса в ущелині Темного шепоту?", [5] = "Ти {стать:впорався:впоралась}! Цей жезл ідеально підійде. Тепер залишилось зібрати це все докупи...", ["en"] = "A Shifty Merchant", ["tasks"] = { ["Fel Elemental Rod"] = "скверно-стихійний стрижень", ["Fel Elemental Rod (Provided)"] = "скверно-стихійний стрижень (видано)" } },
    [8929] = { [1] = "У пошуках Антіона", [2] = "Що ж, нам нічого не лишається, окрім як випробувати гоблінський винахід. Кажуть, Антіон загинув під натиском легіонів Стратгольма, коли намагався увійти до його воріт.\n\nСпробуй скористатися цим винаходом там і дізнайся все, що знав Антіон.", [3] = "Скористайтесь міжвимірним шукачем привидів біля входу до Стратгольма і поговоріть з привидом Антіона Гармона.", [5] = "Тебе прислала Деліана? Я зроблю все можливе, щоб допомогти тобі, та спершу маю попросити про послугу.", ["en"] = "In Search of Anthion", ["tasks"] = { ["Extra-Dimensional Ghost Revealer"] = "міжвимірний шукач привидів" } },
    [89300] = { [1] = "Попелоносець", [2] = "Твоя рука тремтить, коли вона стискає рукоять розбитого клинка. Ти тримаєш залишки справді легендарної зброї — Попелоносця. Тримаючи те, що залишилося від меча, ти відчуваєш крижаний жах, і можеш поклястися, що чуєш голоси у своїй свідомості. Один голос, зокрема, лунає найгучніше.\n\n<Якщо ти хочеш побачити його відновленим, візьми зламаний клинок. Ця дорога може призвести лише до прокляття, але я покажу тобі шлях.>", [5] = "Добре, ви зробили перший крок.\n\nЯ відлуння первісного власника Попелоносця. Щось на кшталт... свідка дурості тих, хто думає, що просто володіння легендарною зброєю зробить їх легендарними. Калдоран потрапив у цю пастку, і забуття стало його нагородою.\n\nЩо ж до вас, можливо, ви могли б бути іншим? Ви могли б досягти кращих результатів. Або ви могли б зазнати невдачі, як багато інших, і прагнути влади над принципами в тих самих пихатих прагненнях.", ["en"] = "The Ashbringer", ["tasks"] = { ["Item #239010"] = "Артикул №239010" } },
    [89301] = { [1] = "Важкий шлях", [2] = "Біля основи Світового Дерева, високо на вершині гори Хіджал, знаходиться джерело великої сили. Це місце давньої та багатогранної історії; нещодавно воно було центром останньої сутички між захисниками Азероту та Палаючим Легіоном. Тепер це місце з привидами, просякнуте силою світла і тіні... життя і смерті.\n\nЦя сила відображає подвійність клинка, і ми побачимо, як там гартується зброя. Однак досягнення вершини гори буде нелегким подвигом.", [4] = "Оригінальний клинок був загартований у крові нації, що падає у полум'я, війну та темряву. У таких речах є давня та моторошна магія.", [5] = "Друїди ревно охороняють таємниці Гіджалу з кінця Третьої війни. Однак вони не єдина перешкода для вас. Залишки Багачу, боги диких територій, демони... навіть дракони нишпорять по схилах гори. Якщо пощастить, з'явиться можливість, яка дозволить вам обійти ці небезпеки.\n\nЗалишається лише сподіватися, що фортуна посміхнеться вам.", ["en"] = "A Difficult Path", ["tasks"] = { ["Item #240936"] = "Товар №240936" } },
    [89303] = { [1] = "На стежці долі", [2] = "Калдоран використав поєднання святої магії, майстерності та амбіцій, щоб «очистити» клинок. Попелоносець зрештою відкинув Калдорана, але деякі з його методів можуть мати певну цінність як відправну точку.\n\nСвітло та темрява — це сума того, ким є Попелоносець зараз, а світлокована зброя, якою володіють хрестоносці в Анклаві, може бути нам корисною.", [4] = "Що ти відкрив, {клас}?", [5] = "Методи Багряного Хрестового Походу настільки ж перекручені, наскільки й помилкові. Зброя та обладунки хрестоносців сяють променистим світлом, але також відображають притаманну Багряному Хрестовому Походу темряву. Вроджена подвійність цього легкокованого металу робить його добре придатним для перекування клинка.\n\nЗалишився лише один компонент.", ["en"] = "On Fate's Path" },
    [89304] = { [1] = "Ідеальний метал", [2] = "Тепер, коли у нас є матеріали, мені потрібен трохи часу, щоб спробувати кілька різних комбінацій та перевірити свої результати. Це делікатна робота, і я не хотів би витрачати жодного з матеріалів, які ви так люб'язно мені надали, надто поспішно тестуючи.", [5] = "Я тут сам впораюся. Тим часом почни думати, яку зброю ти хочеш зробити. Якщо раптом відчуєш натхнення, сміливо повертайся сюди і дай мені знати.\n\nО, і дякую, {ім'я}. Як би мені не хотілося цього визнавати, але мати щось подібне для дослідження дуже допомогло мені. Я досі не впевнений, чи колись знову приєднаюся до Срібного Світанку, але принаймні я більше не нишпорю в тій клітці.\n\nО, і візьми це. Це небагато, але це знак моєї вдячності.", ["en"] = "The Perfect Metal" },
    [89310] = { [1] = "Терордейл", [2] = "Мені знадобилося багато років, щоб оговтатися від почуття провини, як тільки мій розум звільнився від Короля-Ліча. Звільнившись Сільваною, я відхилив пропозицію Темної Леді та пішов сам у Чумні Країни. Я безцільно блукав місяцями. Не знаю, чому я це зробив, але зрештою я знайшов дорогу назад до дому моєї родини, і те, що я там знайшов, було... несподіваним.\n\nПодорожуйте до села з привидами, яке тепер відоме як Терордейл, знайдіть найпівнічніший будинок і зустріньтеся зі мною там. Ви дізнаєтесь решту.", [3] = "Вирушайте до Террордейлу та знайдіть Леоніда Варфаломія Шановного в одному з будинків.", [5] = "Мені неприємно бачити, що сталося з моїм будинком.", ["en"] = "Terrordale" },
    [89328] = { [1] = "Втрата", [2] = "Коли мої блукання привели мене сюди, ви можете уявити моє здивування, коли я знайшла свого сина живим і здоровим. Він не відкинув мене, як інші живі, він прийняв мене. Він став цілителем і вивчав нежить. Він був переконаний, що може знайти ліки, щоб не лише запобігти нежиті, а й повернути її назад.\n\nНедовго ми були разом і щасливі. Я допомагала синові з його дослідженнями, і він дав мені надію, якої я потребувала.\n\nТак було доти, доки Баелін Калдоран не повернувся в наше життя.", [3] = "Послухайте заключну частину розповіді Леоніда.", [5] = "На мій сором, я вижив. Невдовзі після цього лорд Тиросус знайшов мене та залатав.\n\nНе один, а двічі Баелін Калдоран був відповідальним за смерть дорогої мені людини. Його зарозумілий фанатизм — це саме серце корупції, яка мучить Багряний Хрестовий Похід.\n\nХоча я ніколи не оговтаюся від болю, я все ж шаную свого сина, ділячись його надією та баченням майбутнього, де прокляття нежиті можна вилікувати. Я маю сподіватися, що колись хтось зможе завершити роботу мого сина.", ["en"] = "Loss" },
    [89329] = { [1] = "Викорінення зараження", [2] = "Огидно. Це місце кишить гниючими нерубіанськими дронами. Я б бачив їх знищення.", [3] = "Убийте 5 склепників та 8 склепних демонів, а потім поверніться до Леоніда Варфаломія Шановного до його колишнього будинку в Террордейлі.", [5] = "Це, швидше за все, безглуздий жест, але мені хоч трохи легше.", ["en"] = "Stomping Out The Infestation", ["tasks"] = { ["Crypt Fiend slain"] = "склепний марник: убито", ["Crypt Walker slain"] = "склепний блукач: убито" } },
    [89340] = { [1] = "Абсурдно продумана поштова відправка", [2] = "До шановного шеф-кухаря Нового Авалону: Керрі Хартфайр,\n\nСподіваюся, цей лист застав вас у гарному настрої! Ваш від'їзд з Хартглена залишив дірку в наших серцях і шлунках. Не минає й дня без скарг на ранкову кашу, що прагне наступної смачної трапези.\n\nЗ цією метою ми плануємо бенкет, на якому ми маємо намір подавати лише найкращі страви Лордерону: ваші.\n\nЗа два тижні прибуде караван у супроводі. Вам і вашим стравам краще бути готовими.", [3] = "Завершіть доставку.", [5] = "<Керрі зрештою бере листа після твого наполягання та переглядає його вміст. Її очі широко розширюються.>\n\nЯк я маю зібрати інгредієнти та приготувати їжу для цілої секти Червоного Хрестового Походу... менш ніж за два тижні? Справді жахливий час.\n\nХоч би як, громадяни Нового Авалону понад усе. А тим часом я маю сподіватися на допомогу, мабуть.\n\n<Вона робить паузу.>\n\nЗачекайте хвилинку, чому це вже було відкрито?", ["en"] = "Preposterously Prosed Postage" },
    [89341] = { [1] = "Велике свято", [2] = "Ваша допомога була неоціненною. Громадяни та солдати Нового Авалону можуть розраховувати на гарячу їжу цієї ночі та протягом багатьох наступних вечорів. Щиро вам вдячна.\n\nОднак, як ви, мабуть, самі зрозуміли, мені потрібно виконати ще одне завдання, перш ніж я нарешті зможу розпочати. З більшою частиною цього я можу впоратися сам, але якщо ви готові зробити мені ще одну послугу, я навчу вас своїм найвідомішим рецептам.\n\nВи будете їсти як справжній Верховний Лорд щовечора.", [3] = "Допоможіть Керрі Хартфаєр у Новому Авалоні востаннє, зібравши такі інгредієнти:", [4] = "Ах, чудово знову тебе бачити. Ти приніс мені останню партію інгредієнтів, які мені потрібні?", [5] = "Швидка та надійна, як завжди, не можу повірити, що колись сумнівалася в тобі. Дозволь мені взяти це з тебе.\n\nТвої мотиви мені досі незрозумілі, але очевидно, що у тебе добре серце. Як і обіцяла, ось моя кулінарна книга. Вона мені більше не потрібна, я давно запам'ятала всі свої рецепти.\n\nЩе раз дякую, і не будь чужою.\n\n<Керрі щиро, розслаблено посміхається, перш ніж відновити свою роботу.>", ["en"] = "The Great Feast" },
    [89342] = { [1] = "Членство в елітному клубі", [2] = "Гей, ти!\n\nТи схожий на ту людину, про яку нещодавно говорила Керрі. Вона багато хорошого про тебе сказала. Ну, спочатку не дуже, але швидко змінила тон.\n\nУ будь-якому разі, друзі шеф-кухаря – це мої друзі. Я хотів би надати тобі постійне членство, і тобі не потрібно буде постійно носити цю картку з собою.\n\nВсе, що я прошу натомість, це омлет «Схід сонця» та стейк «Проулер». Звичайно, обидва приготовані твоїми руками.", [3] = "Особисто приготуйте та доставте омлет «Схід сонця» та стейк «Проулер» до Девонського лісу перед готелем «Новий Авалон».", [4] = "Повернувся з моєю їжею?", [5] = "<Не зупиняючись, він відкушує шматочок від обох страв.>\n\nОго, у Керрі є конкурентка. Мабуть, вона навчила тебе всім своїм технікам. Я здивований, мені ніколи не вдавалося переконати її навчити мене чомусь.\n\nДякую. Я вже зареєстрував твоє ім'я як постійного VIP-члена нашого закладу. Ти можеш вільно приходити та йти без цієї картки члена клубу, якщо тільки ти не зробиш нічого, що могло б відлякати наших гостей.", ["en"] = "VIP Haute Club Membership" },
    [8935] = { [1] = "Гідна винагорода", [2] = "Ти {стать:дотримав:дотримала} слова і {стать:приніс:принесла} пристрій Мукса. І якщо я хочу, щоб ти знову {стать:виручив:виручила} мене — винагорода має бути відповідною. Принеси мені пояс і рукавички, які хочеш оновити. Обіцяю, ті, які я дам тобі натомість, будуть набагато кращими.", [3] = "Принесіть пояс тіньового ремесла та рукавички тіньового ремесла Деліані в Залізогарт.", [4] = "{стать:Готовий:Готова} обмінятись?", [5] = "Ти {стать:виконав:виконала} свою частину угоди, а я виконаю свою.\n\nТа пам'ятай, що найкращі частини обладунку все ще в мене, і я віддам їх, коли твоя робота буде закінчена.", ["en"] = "Just Compensation", ["tasks"] = { ["Shadowcraft Belt"] = "пояс тіньового ремесла", ["Shadowcraft Belt (Provided)"] = "пояс тіньового ремесла (видано)", ["Shadowcraft Gloves"] = "рукавиці тіньового ремесла", ["Shadowcraft Gloves (Provided)"] = "рукавиці тіньового ремесла (видано)" } },
    [89381] = { [1] = "Подушка для шпильок", [2] = "Ого! Неймовірна сміливість — тупотіти стрільбищем під час нашого тренування. Ти практично благаєш про снаряд у коліно, або, можливо, в зад, враховуючи те, як ти пересуваєшся.\n\nАле ж твоя безпека — це твоя прерогатива. Оскільки ти, здається, справді ризикуєш, чому б не допомогти нам? Збирання наших стріл після кожного раунду пострілів забирає дорогоцінний час стрільби.\n\nЯк щодо того, щоб ти приніс мені кілька, га?", [3] = "Зберіть стріли на полігоні для стрільби з лука на південь від міської площі Нового Авалона. Ви також можете отримати стріли, борючись з рейнджерами.", [4] = "Ці стріли самі не принесуть. Чого ти чекаєш?", [5] = "Бачу, ти ще живий! Спостерігати за тим, як ти мчав по тиру, викликало в мене кілька сміху. Зізнаюся, я очікував, що ти втечеш, коли вони почнуть стріляти прямо в тебе.\n\nДякую, що дав моїм лучникам рухому мішень для тренувань. Я не думав, що ти будеш настільки дурним, щоб спробувати, тому не мав на увазі винагороди.\n\nХм. Як щодо того, щоб я навчив тебе, як зробити сагайдак? Це полегшить тобі роботу наступного разу.", ["en"] = "Pin Cushion" },
    [894] = { [1] = "Самофланж", [2] = "ТзНБ \"Авантюра\" створила невеликий дослідницький центр далеко на північ звідси, на південний захід від Драговини шламу. Я не дуже добре знаю про те, чим вони займаються, але мені вдалося дізнатися, що проводять експерименти з чимось, що називається \"самофланж\".\n\nЩо це в біса таке — самофланж? Що б це не було, я хочу його дослідити, тож мені потрібен хтось, хто може його дістати.\n\nЯ дістав копію інструкції з експлуатації їхньої системи управління — там має бути написано, як від'єднати від неї самофланж.", [3] = "Отримайте доступ до панелі управління на дослідницькому майданчику ТзНБ \"Авантюра\".", [5] = "Різноманітні кнопки, важелі та миготливі лампочки хаотично розкидані на лицьовій стороні панелі управління. Невеликий індикатор показує, що апарат наразі працює в оптимальному режимі, а регулювальні клапани з першого по третій наразі відкриті. У нижній правій частині панелі управління є невелика замкова щілина.", ["en"] = "Samophlange", ["tasks"] = { ["Control Console Operating Manual"] = "інструкція з експлуатації панелі управління" } },
    [8941] = { [1] = "Гідна винагорода", [2] = "Ти {стать:довів:довела}, що на тебе можна покластися, {ім'я}. Оскільки я вірю, що ти допоможеш мені виплутатися з цих неприємностей, було б мудро з мого боку винагородити тебе за твої старання.\n\nТепер я обміняю твій пояс і рукавички. Якщо ми доведемо справу до кінця, я віддам тобі й решту речей.", [3] = "Принесіть пояс тіньового ремесла та рукавички тіньового ремесла Моквару в Орґріммар.", [4] = "{стать:Готовий:Готова} до обміну?", [5] = "Наша угода залишається в силі. Тільки пам'ятай, що це лише дещиця того, що на тебе чекає. Звільни мене від цього прокляття, і я щедро винагороджу тебе гарними речами.", ["en"] = "Just Compensation", ["tasks"] = { ["Shadowcraft Belt"] = "пояс тіньового ремесла", ["Shadowcraft Belt (Provided)"] = "пояс тіньового ремесла (видано)", ["Shadowcraft Gloves"] = "рукавиці тіньового ремесла", ["Shadowcraft Gloves (Provided)"] = "рукавиці тіньового ремесла (видано)" } },
    [89421] = { [1] = "Куля Рай", [2] = "Ви можете подумати: «А що, якби я хотів натомість підсумок для набоїв?» і «Якщо я щось скажу, чи змусить вона мене теж стати перед кулями?» Я не можу читати ваші думки, але хороший рейнджер чудово вміє робити прогнози.\n\nПравда в тому, що ми тут не використовуємо кулі, попри те, що я за це виступаю. Якби, скажімо, купа куль приземлилася мені до ніг, мабуть, у мене не було б іншого вибору, окрім як розробити відповідний підсумок для них.\n\nЯкби тільки.", [3] = "Зробіть або придбайте торієві панцири у гравця з професією інженера та принесіть їх Кіндрі Свіфтарроу біля стрільбища з лука Нового Авалона.", [4] = "Хо-хо! Якби тільки хтось доставив нам запас куль! Це було б чудово.", [5] = "А, ти повернувся, і в тебе ще й достатній запас куль. Ти чудово ухиляєшся від снарядів ТА розумієш натяки! Я пишаюся тобою.\n\nОскільки ти був готовий ризикувати своїм життям, щоб підібрати кілька неякісних тренувальних стріл, я подумав, що ти повернешся після того, як тобі дадуть незначне завдання. Я вже витратив час на розробку належного підсумка.\n\nМені ще треба переконати свого командира інвестувати в зброю, але принаймні тепер у мене є трохи боєприпасів.", ["en"] = "Bullet Heaven" },
    [89442] = { [1] = "Емблема Темряви", [2] = "Залишилася ще одна частина: Емблема Попелоносця. Певним чином, емблема є серцем клинка. Верховний лорд Александрос сам використав всю свою волю та рішучість, щоб перетворити сферу чистої порожнечі на посудину самого Світла.\n\nЕмблема вистояла, коли Калдоран упав, а клинок розбився. Шукачі пригод відібрали її та передали під опіку лорда Максвелла Тіросуса.\n\nЗаберіть емблему, і ми матимемо все необхідне для наступного кроку.", [3] = "Поговоріть з лордом Максвеллом Тіросусом у каплиці Світлої Надії про Емблему Попелоносця.\n\nНаданий предмет:", [5] = "<Очі лорда Максвелла Тіросуса розширюються, коли ви розповідаєте йому про Заповіт Попелоносця.>\n\nЦе неймовірна історія, {ім'я}. Частина мене радіє перспективі повернення клинка та спостереження за тим, як мій старий друг нарешті знаходить спокій, який у нього вкрали. Однак є відчуття, якого я просто не можу позбутися. Я боюся, що цей шлях не приведе вас до того кінця, на який ми сподіваємося.\n\nУ будь-якому разі, якщо ви впевнені, що це шлях, то я довірю емблему вашій опіці та помолюся за обнадійливий результат.", ["en"] = "Emblem of Darkness", ["tasks"] = { ["Item #239197"] = "Товар №239197" } },
    [89443] = { [1] = "Падіння на свої місця", [2] = "Ось емблема. Попереджаю вас, не торкайтеся її голими руками. Від неї випромінюється мерзенна некромантична аура, яка може завдати великої шкоди.\n\nБажаю вам успіхів у цій справі, {ім'я}. Я наважуся сподіватися на ваш успіх, але підготуюся до менш сприятливого результату.", [3] = "Поєднайте Перекований клинок Попелоносця, Емблему Попелоносця та Руків'я Попелоносця, а потім поговоріть з Волею Попелоносця, щоб визначити свої наступні кроки.\n\nНаданий предмет:", [4] = "Ми вже близько, {клас}.", [5] = "Шматочки стають на свої місця. Зброя зараз повністю інертна, але залишився ще один останній крок, щоб відновити втрачену силу клинка. Наступна частина не вимагатиме сили рук, але все одно може виявитися складною.\n\nСкажи мені, {клас}, що ти знаєш про Нордрассіл, Світове Дерево?", ["en"] = "Falling Into Place", ["tasks"] = { ["Item #239219"] = "Товар №239219" } },
    [89444] = { [1] = "Зіпсована емблема", [2] = "<Розшукуючи руїни битви з Баеліном Калдораном, ви знаходите емблему з розбитого клинка Попелоносця. Тримаючи в руці значок у формі черепа, можете поклястися, що чуєте тихий, бурмочучий шепіт. Ви озираєтеся навколо, шукаючи джерело голосу, але не бачите жодного очевидного джерела звуку. Ви хитаєте головою та ховаєте емблему в рюкзак.>\n\nЗнайди лорда Максвелла Тіросуса, як тільки повернешся до каплиці Надії Світла. Він зацікавиться цим артефактом.", [3] = "Віднесіть Зіпсовану Емблему лорду Максвеллу Тіросусу в каплиці Надії Світла у Східних Чумних Землях.", [4] = "Лорд Максвелл Тіросус напружується, коли ви показуєте йому емблему, яку знайшли.", [5] = "Коли Александрос вирушив кувати Попелоносця, він зробив це з серцем, сповненим надії та бажанням захистити свою батьківщину.\n\nЗрештою, клинок був поглинутий темрявою, як і його власник. Хоча Калдоран прагнув очистити його через панування та огидне зловживання світлом, він абсолютно не зміг зрозуміти природу самого викуплення. Викуплення належить серцю і має бути заслужене, а не примусове.\n\nЯ збережу це поки що в безпеці. Дякую, {клас}. А тепер ми святкуємо нашу перемогу.", ["en"] = "The Corrupted Emblem", ["tasks"] = { ["Item #239215"] = "Товар №239215" } },
    [89445] = { [1] = "Леза світла", [2] = "Навіть зруйнований та зламаний, властивості клинка, який ви тримаєте в руках, вражають. Якби ви могли краще зрозуміти матеріал, з якого виготовлений цей клинок, можливо, вдалося б створити з нього справді виняткову зброю. Спочатку вам потрібно знайти коваля, достатньо вправного, щоб визначити його властивості, та знайти спосіб обробки матеріалу.", [3] = "Знайдіть коваля, який може розповісти вам більше про Зруйнований світлокований клинок.", [4] = "Га? Не можу виділити хвилинку, щоб помахати тобі щелепами! Ці нагрудники самі себе не розіб'ють!", [5] = "Ооо! Якщо це не вражаючий клинок, то це ж у тебе!\n\nКажеш, шукаєш когось, хто спробує обробити цей матеріал? Хм, ну, з жалем мушу сказати, що розкриття секретів цього металу, мабуть, мені не під силу. Якби ж то Омаріон був тут. Він був тут головним майстром-ремісником і справді чудовим експертом з екзотичних матеріалів і сплавів. Він ідеально підійшов би для такого. Проблема лише в тому, що він зник!\n\nЯкщо він десь живий, то він твій найкращий вибір!", ["en"] = "Blades of Light", ["tasks"] = { ["Item #239196"] = "Товар №239196" } },
    [89446] = { [1] = "Загублений ремісник", [2] = "<Здається, що майстер Вільгельм не може вам допомогти, але він припустив, що його колишній господар, чоловік на ім'я Омаріон, міг би. Якщо ви знайдете його, він може знати більше про цей матеріал.>", [3] = "Знайдіть майстра-ремісника Омаріона.", [4] = "<Омаріон дивиться повз тебе порожнім поглядом.>", [5] = "Я розумію, як це. Ніхто не прийде мене шукати, хіба що їм щось знадобиться. Все гаразд, все гаразд. Мені все одно не потрібно рятувати. Я задоволений просто померти тут, у цьому забутому світлом місці. Будь ласка, просто залиште мене самого.", ["en"] = "The Lost Craftsman", ["tasks"] = { ["Item #243230"] = "Товар №243230" } },
    [89447] = { [1] = "Екстравагантні смаки", [2] = "Отже, у тебе там дуже вишуканий шматок металу. Кого це хвилює?\n\nО, хочеш, щоб я тобі про це розповів більше? Ну, це меч, і він зламаний. Ми вже закінчили?\n\n<Омаріон пильно дивиться на тебе, а потім важко зітхає, коли стає очевидно, що ти не збираєшся йти.>\n\nДобре. Залиш лезо мені, і я на нього подивлюся. Поки я тут, мені б не завадило трохи перекусити. Я колись знав цього гобліна, Дірджа Швидкоруба. Він готує найкращі відбивні з хімероків. Принеси мені трохи.", [3] = "Принесіть десять порцій відбивних «Пікаючих хімерок» від Могиля майстру-реміснику Омаріону в Наксрамас.", [4] = "Виявляється, коли твої викрадачі нежить, годувати тебе не є їхнім головним пріоритетом. Не те щоб мене це хвилювало; я був задоволений голодною смертю тут. Але оскільки ти не перестаєш мене чіпляти, гадаю, ти міг би хоча б принести мені гарну останню страву.", [5] = "Це влучно, {клас}.\n\nЩодо цього леза. Воно... насправді досить дивовижне. Воно випромінює тепло; і лезо майже надприродно добре тримає лезо. Здається, воно також відлякує нежить, про що свідчить той факт, що з тих пір, як ви залишили його тут, жодного зомбі не пройшов повз мене і не спробував мене з'їсти.\n\nШкода, справді. Зомбі — не дуже цікава розмова, але в такому місці береш те, що можеш знайти.", ["en"] = "Extravagant Tastes" },
    [89448] = { [1] = "Збирання світла", [2] = "<Омаріон виглядає значно жвавішим, ніж коли ти вперше з ним зустрівся.>\n\nГаразд, {клас}, ти привернув мою увагу. Цей метал надзвичайно унікальний, і я хотів би ще трохи поекспериментувати з ним. Однак мені знадобляться додаткові зразки сировини. Принесіть мені ще з десяток злитків цього «легковки». Також спробуй дізнатися більше про те, де створюється ця зброя. Зрештою, коваль настільки хороший, наскільки хороші його інструменти та простір для крафтингу.", [3] = "Принесіть 12 злитків світлокованого заліза майстру-реміснику Омаріону в Наксрамас і дізнайтеся, де Багряний хрестовий похід кує цю нову зброю.", [4] = "Шкода, що до цих відбивних у мене немає трохи Кая-коли. О, ви ніколи не чули про Кая-Колу? Що ж, якщо у вас колись буде можливість спробувати, це змінить ваше життя.", [5] = "Вони мають чудово підійти. Чого ще ви навчилися під час своєї подорожі?\n\n<Ви розповіли Омаріону про Сяючу Кузню, яку знайшли в Багряному Анклаві.>\n\nДуже цікаво. Тож у Багряному Анклаві є ковадло, що працює на світловому паливі, і саме там вони виготовляють цю зброю?\n\nНу, нічого страшного. Мені потрібно побачити це на власні очі. Мабуть, я відкладу смерть на самоті в цьому жахливому місці.", ["en"] = "Gathering Light" },
    [89449] = { [1] = "Сяюча кузня", [2] = "Отже, схоже, що в Руці Тіра трохи безладно. Це прикро, але суть у тому, що мені потрібно добре оглянути майстерню, де вони виготовляли цю зброю. Інакше в мене не буде жодної надії розкрити секрети цього металу.\n\nПросто позначте місцезнаходження цієї майстерні на моїй карті, і я вирушаю туди, як тільки берег буде чистим.", [3] = "Увійдіть до Багряного Анклаву та зустріньтеся з Майстром-ремісником Омаріоном у Сяючій кузні.", [5] = "Я вивчаю цей робочий простір і, здається, маю чітке розуміння того, чим тут займається Хрестовий похід. Ми повинні мати змогу використовувати цей матеріал для виготовлення клинка неперевершеної якості.\n\nОднак, це легке коване залізо саме по собі має фатальний недолік, який значно знижує його довговічність. Було б ідеально, якби ми могли використовувати його як частину сплаву.\n\nПросто щоб підготувати вас, це може бути дорого.", ["en"] = "The Radiant Forge" },
    [8945] = { [1] = "Прохання мерця", [2] = "Я відповім на всі твої запитання, {ім'я}. Але спершу виконай моє прохання.\n\nМою кохану дружину взяли в полон мертві покидьки Рівендера.\n\nЯ так не хотів, щоб вона йшла в цей безглуздий похід зі Сріблястим Світанком, але це вже не має значення. Прошу тебе, зроби те, що мені не вдалося — врятуй Ісіду з лап барона!", [3] = "Відправляйтесь в Стратгольм і врятуйте Ісіду Гармон від барона Рівендера.", [4] = "Скажи мені, Ісіда жива?", [5] = "Дякую за мій порятунок.... Я вже не вірила, що виживу. Прийми це в знак моєї вдячності.\n\nАнтіон... ні... не може бути....", ["en"] = "Dead Man's Plea", ["tasks"] = { ["Ysida Freed"] = "Ісіда Фрід", ["Ysida Freed (Provided)"] = "Ісіда Фрід (видано)", ["Ysida Freed slain"] = "Ісіда Фрід: убито" } },
    [89451] = { [1] = "Подорож до Місячної галявини", [2] = "Я пропоную вам почати з Мунґлейду, фортеці Кенарійського Кола. Саме Архідруїд Малфуріон Буревісник наказав закрити шлях, але не всі друїди з цим погоджуються. Деякі можуть захотіти вам допомогти.\n\nВи винахідливі, і я впевнений, що ви зможете подолати цю перешкоду. Отримайте доступ до вершини та знову поговоріть зі мною.", [3] = "Знайдіть спосіб дістатися до вершини гори Хіджал.", [5] = "Ти хочеш подорожувати до світового дерева? Моя мати нещодавно мала там справи... доки не зникла. Ось чому я тут і хочу аудієнції з керівництвом Кенарійського Кола. Однак це моя турбота, а не твоя.\n\nЗахисні чари, що перекривають Гіджал, вже не ті, що були раніше. Ти не можеш пройти крізь них, можливо, ти зможеш. Я знаю когось, хто може бути готовий допомогти тобі.", ["en"] = "Journey To Moonglade" },
    [8946] = { [1] = "Доказ життя", [2] = "Немає гіршої долі, ніж коли близькі гинуть, намагаючись врятувати тебе. Однак, ти стверджуєш, що можеш розмовляти з ним.\n\nВіднеси Антіону цей медальйон як доказ того, що я жива. Він не мусить триматись за цей світ, моє серце цього не витримає.\n\nПрощай, {ім'я}. Я завжди буду перед тобою в боргу.", [3] = "Принесіть медальйон Ісіди Антіону Гармону в Східні Зачумлені землі.", [4] = "Ісіда... вона жива?", [5] = "Цей медальйон... ти {стать:знайшов:знайшла} її! Тепер я можу спочивати з миром.\n\nЯ відповім на всі твої запитання, {ім'я}. Але поспіши, мій час у цьому світі обмежений.", ["en"] = "Proof of Life", ["tasks"] = { ["Ysida's Locket"] = "медальйон Ісіди", ["Ysida's Locket (Provided)"] = "медальйон Ісіди (видано)" } },
    [89462] = { [1] = "Друїд Кігтя", [2] = "Я маю випадкове знайомство з друїдом Кігтя, який, можливо, захоче допомогти вам. Святилище Авіани знаходиться на схилах гори Гіджал і є священним для її ордену, тому вони все ще мають обмежений доступ до гори.\n\nЇї звати Тісалі Кроу. Я вважаю, що вона регулярно відвідує Еверлук у Зимоключі, щоб обміняти припаси. Вона вперта та дуже імпульсивна, що може бути саме тим, що вам потрібно для вашого квесту.\n\nУдачі, {клас}.", [3] = "Поговоріть з Тісалі Кроу біля Еверлука у Зимоключа.", [5] = "<Тісалі уважно слухає, як ти розповідаєш їй свою історію.>\n\nОтже, дозволь мені прояснити: ти хочеш дістатися до самої вершини Хіджалу та використати силу Криниці Вічності, щоб загартувати зламаний, проклятий, легендарний меч? Ти хочеш зробити це, щоб зняти це прокляття та звільнити його колишнього власника від нежить? Це... насправді звучить досить приголомшливо.\n\nЯ думаю, що можу допомогти, але в мене також є кілька власних проблем, які потребують вирішення — якщо ти не проти.", ["en"] = "The Druid of the Talon" },
    [89463] = { [1] = "Аргумент щодо нерозголошення", [2] = "Я не з тих гоблінів, які діляться своїми секретами з якимось випадковим шукачем пригод, але я з тих, хто ділиться секретами гнома! Я випадково роздобув кілька схем дорогою сюди і працюю над виправленням недоліків у їхніх конструкціях. Вони досі використовують запобіжники! Можете повірити? ЗАПОМІЖНІ ЗАПОБІГНИКИ!!\n\nУ будь-якому разі, я прагну поділитися своїм прогресом, але мені потрібне перо, якщо я збираюся викреслити все це мотлох. І мені не завадить затишне місце, щоб я міг трохи подумати. Що ви скажете?", [3] = "Фізлфуз з Нового Авалона попросив перо та щось, щоб зробити своє сховище комфортнішим. Класне перо можна знайти в ратуші Нового Авалона, а реквізит для дому — десь поблизу Некросистоти або в криптах Каражана.", [4] = "Гей, це ти! Не можу дочекатися, щоб побачити, що ти мені приніс.", [5] = "Знаєш, я не впевнений, чого я очікував, але це було не... це. Гадаю, це пасує до дерев. Мені не варто скаржитися, здебільшого тому, що я б почав кричати, якби закінчив, а жоден з нас цього не хоче.\n\nЩо ще важливіше, перо! Забув згадати, що в мене закінчилося чорнило, але моторна олива має допомогти.\n\n<Fizzlefuse перевіряє зручність використання пера за допомогою хаотично намальованої схеми.>\n\nОсь, друже.", ["en"] = "Nondisclosure Arguement" },
    [8947] = { [1] = "Дивне прохання Антіона", [2] = "Ми не усвідомлювали важливість медальйона Вальталака, тому розділили його разом із рештою здобичі. Перший шматок забрав дворф, на ім'я Телдрен. Я намагався відібрати у нього цей фрагмент, але він побив мене до півсмерті. Тож тобі доведеться відібрати його силою.\n\nЯ чув, що він став гладіатором у дворфів Темного Заліза. Однак викликати його на битву буде непросто.\n\nЗбери для мене деякі матеріали. Вони тобі знадобляться.", [3] = "Принесіть 3 злитки темного заліза, 20 зачарованих шкір, 3 місячні полотна та 4 оброблені міцні шкури Антіону Гармону в Східні Зачумлені землі.", [4] = "Ти {стать:дістав:дістала} матеріали, які я просив, {ім'я}?", [5] = "Чудово. Я перетворю їх на щось більш корисне для наших потреб.", ["en"] = "Anthion's Strange Request", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Dark Iron Bar"] = "злиток темного заліза", ["Dark Iron Bar (Provided)"] = "злиток темного заліза (видано)", ["Enchanted Leather"] = "зачарована шкіра", ["Enchanted Leather (Provided)"] = "зачарована шкіра (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)" } },
    [89471] = { [1] = "Гоблін Ладіння", [2] = "Гадаю, можна сміливо сказати, що наші ділові стосунки вже міцно встановлені. Я — мозок, ти — сила. Це чудово, бо приблизно тридцять секунд тому я зрозумів, що мені бракує деяких критично важливих компонентів!\n\nОсь список речей, які мені потрібні, виходячи з цих схем, виключаючи все це гномське сміття. Тим часом я виправлю ці креслення. Коли ти повернешся, ми зможемо одразу взятися до роботи.", [4] = "Тобі знадобилося трохи часу, я вже починав думати, що ці Багряні Хрестоносці нарешті тебе покінчили. Ти отримав усе, що я просив?", [5] = "Я мав здогадатися, що ти зручно проігноруєш список покупок. Як гоблін тут може щось перекусити? Ну хай там як.\n\nТобі буде приємно дізнатися, що я закінчив схему свого найновішого винаходу: Дзвіночка! Цей пристрій сам по собі нешкідливий, але в цьому й вся суть! Все, що тобі потрібно зробити, це втиснути кілька ретельно відкаліброваних деталей у задню панель, а потім, коли будеш готовий, натиснути велику червону кнопку!\n\nЩо станеться? Саме це ти зараз дізнаєшся!", ["en"] = "Goblin Tinkering", ["tasks"] = { ["Fizzlefuse's Shopping List"] = "Список покупок Fizzlefuse" } },
    [89473] = { [1] = "Криниця Вічності", [2] = "Ми вже близько. Катастрофічне руйнування, яке давні духи Калдорей завдали демону-лорду Архімонду, жахливо вразило дерево. Вибух розкидав безліч уламків по всій території.\n\nЗберіть фрагменти Нордрасілу з-під гілок дерева. Ми використаємо їх, щоб створити спеціальний вогонь, у якому нагріємо клинок, а потім загасимо його у водах самої криниці. Магія загартує та зв'яже клинок, відновлюючи магію, яка залишилася на ньому, коли він був розбитий.", [4] = "Багаття перед вами виглядає як ідеальне місце, щоб нагріти лезо.", [5] = "Гілки Нордрасілу, які ви зібрали, тепер акуратно розкладені на залишках багаття. Залишилося лише підпалити його.", ["en"] = "The Well of Eternity" },
    [89474] = { [1] = "Прощення", [2] = "Александроса Могрейна вбив власний син, і тягар цієї зради скує його душу. Попелоносець був такою ж людиною, як і меч, і клинок не знайде спокою, доки дух самого Александроса не знайде спокою. Віднесіть зброю до собору Багряного монастиря в Тірісфальських галявинах. Там зустріньтесь із сином Могрейна, Багряним Командувачем.\n\nМогрейн повинен знайти в собі волю пробачити, щоб це справді закінчилося.", [3] = "Подорожуйте до Багряного монастиря в Тірісфальських галявинах. Увійдіть до монастирського собору, тримаючи в руках Зіпсованого Попелоносця, і станьте свідком того, що там відбувається.", [5] = "<Дух не говорить і, здається, навіть не помічає твоєї присутності.>\n\n<Твоє серце стискається від наслідків того, що щойно сталося. Що тепер буде з Александросом? А як щодо викуплення Попелоносця? У тебе так багато запитань і ще менше відповідей.>\n\n<Спроби закликати Волю Попелоносця за допомогою клинка тепер зустрічаються лише мовчанням.>", ["en"] = "Forgiveness" },
    [89475] = { [1] = "Самотній шлях проклятих", [2] = "<Дух, що стоїть перед вами, не виявляє жодної уваги до вашої присутності. За мить ви розумієте, що лорд Максвелл Тіросус захоче знати, що тут сталося. Вам слід повернутися до каплиці Світлої Надії та поговорити з ним.>\n\n<Ви підозрюєте, що Срібні Хрестоносці можуть не бути надто раді бачити вас з Попелоносцем у його нинішньому, спотвореному вигляді. Можливо, вам варто тримати клинок подалі від очей, коли ви наближатиметеся.>", [3] = "Поговоріть з лордом Максвеллом Тіросусом у каплиці Світлої Надії.\n\nВам слід сховати Зіпсованого Попелоносця у свої сумки, інакше члени Срібного Світанку можуть вороже відреагувати, побачивши зіпсовану зброю.", [5] = "<Максвелл Тіросус важко зітхає, коли ти закінчуєш свою розповідь про події в монастирі.>\n\nСхоже, Александрос ще не був готовий знайти спокій, тому клинок залишається заплямованим.\n\nНайбільше, що розбиває мені серце, це те, що щойно ти підійшов, у мене виникло... відчуття. Ніби мій старий друг знову тут зі мною, таким, яким я його пам'ятаю. Знаю, нерозумно сподіватися на таке після всього, що сталося.\n\nІди. Забери клинок звідси. Я не потерплю його присутності.", ["en"] = "The Lonely Path of the Damned" },
    [8948] = { [1] = "Давній приятель Антіона", [2] = "Телдрен не з тих, хто охоче вступає у чесний поєдинок. Я виготовив цей стяг, на якому зображені його родові кольори.\n\nТрохи додаткових чар і Телдрен перед ним точно не встоїть.\n\nМій давній приятель, на ім'я Фалрін знає, як накласти такі чари. Він непогано розбирається в... грі на нервах. Ти знайдеш його у бібліотеці Грізного Молота.", [3] = "Віднесіть незавершений стяг виклику Фалріну Деревотворцю в бібліотеку Грізного Молота.", [4] = "Говори вже, {стать:незнайомцю:незнайомко}. Ти не бачиш, що я зайнятий?", [5] = "Кажеш, тебе Антіон прислав? Я думав, що він мертвий. Що ж, мені доводилось чути й дивніші речі.\n\nОтож. Що ти хочеш, щоб я зробив з цим стягом?", ["en"] = "Anthion's Old Friend", ["tasks"] = { ["Incomplete Banner of Provocation"] = "незавершений стяг виклику", ["Incomplete Banner of Provocation (Provided)"] = "незавершений стяг виклику (видано)" } },
    [89485] = { [1] = "Химерні жахи", [2] = "Хоча мені й подобається думка про те, що ти будеш піддослідним для всіх моїх винаходів, цей мене трохи бентежить. Він має просто деформувати тебе на кілька ярдів вперед, але коли я ткнув перший прототип палицею, він повністю зник, забравши палицю з собою!\n\nВідтоді я зробив кілька налаштувань на різних пристроях. Я бачив, як ти раніше спілкувався з місцевими жителями, спробуй, чи зможеш ти змусити їх спробувати. Тоді, можливо, якщо почуваєшся сміливим, спробуй сам.", [4] = "Як проходять випробування? Хоч мені й байдуже до цих червоних типів, я б дуже хотів дізнатися, що мій пристрій спричиняє болісні смерті, не пов'язані з горінням.", [5] = "Мені... вибачте?! Не могли б ви повторити?\n\n<Очі Фізлф'юза заскленіли, не від жаху, а просто від нудьги.>\n\nОтже, ви кажете, що пристрій працює, просто йому здається, що виникають якісь перешкоди? Чому я не подумав про це вперше? Це цілком логічно. Я не маю уявлення, як це полагодити, але це має сенс.\n\nОсь схема, не соромтеся погратися з нею. Я впевнений, що він на межі того, щоб стати найкращим транспортним засобом для ближнього сполучення з усіх коли-небудь створених.", ["en"] = "Whimsical Horrors", ["tasks"] = { ["Pile of Portiporters"] = "Купа портипортерів" } },
    [89486] = { [1] = "Щіпка пороху", [2] = "Я просто знаю, що ти дуже радий почути про те, що я запланував щодо пороху.\n\nТи колись чув про нітробусти? Не про нітрочоботи; про бусти. Якщо чув, то ти брехун, бо їх ще не винайшли. Досі!\n\nЯ хочу, щоб ти мав честь їх випробувати. Все, що тобі потрібно зробити, це додати дрібку пороху прямо тут і натиснути кнопку. Якщо хочеш їхати ще швидше, додай трохи більше!\n\nОбов'язково подолай різноманітну місцевість, перш ніж повертатися.", [4] = "Я вже запустив годинник, чому ти ще тут?", [5] = "Чудово! Ви повернулися цілими та неушкодженими, з мінімальними опіками. Думаю, ми обидва можемо погодитися, що цей пробний запуск був успішним, насправді, я думаю, що ми можемо покращити його, додавши ще більше пороху!\n\nДякую за всі дані, я знав, що ви не розчаруєте. Ось схема ваших власних нітропідсилювачів. Я наполягаю, щоб ви використовували порох якомога менше, інакше у мене буде конкуренція.", ["en"] = "A Pinch of Gunpowder" },
    [89487] = { [1] = "Багато галасу навколо магнітів", [2] = "Навіть з тими припасами, які ти зібрав, я можу зробити лише певну кількість речей без своєї майстерні. Я придумав план, до того ж геніальний, щоб нарешті зрозуміти, як працюють ці дивні магнітні поля. Підозрюю, що з достатньо точною гоблінською інженерією я зможу створити спосіб постійно тримати відстань між двома людьми на мінімумі! Ніхто більше ніколи не втече від мене без покупки.\n\nЩоб перевірити мою теорію, візьми цей прототип і помахай ним у Новому Авалоні. Якщо пощастить, ти можеш щось знайти!", [4] = "Знаєш, це ж так приємно працювати над чимось, що не має значних шансів перетворити мене на купу попелу. Можливо, гноми все ж таки натрапили на щось цікаве.", [5] = "Спрацювало!? Тобто, спрацювало! Звичайно, спрацювало... фу, мені варто навчитися завжди довіряти своїй інтуїції.\n\nЯ почав підозрювати, що моя теорія була помилкою. Замість того, щоб налаштовувати пристрій на використання протилежних полярностей, він створений для вивільнення сплеску енергії з такою ж полярністю. В результаті, я гадаю, він відштовхуватиме речі, а не притягуватиме їх.\n\nНу що ж, повернемося до креслярської дошки. Ось схема, якщо відштовхування людей відповідає вашій бізнес-стратегії.", ["en"] = "Much Ado About Magnets" },
    [89488] = { [1] = "Різновид миру", [2] = "Я витрачаю більшу частину своїх сил, що згасають, щоб з'явитися перед тобою.\n\nЄ одна швидкоплинна надія. Можливо, ти не зможеш врятувати чоловіка, але ти все ж можеш принести йому певний спокій, обмеживши шкоду, яку він може завдати. Могрейн повернувся до Наксрамаса, щоб відновити та воскресити вершників. Коли це буде зроблено, його лють буде жахливою.\n\nНеправильно вимагати цього від тебе після всього, що ти зробив... але, будь ласка, протистояй Духу Могрейна. Зроби все можливе, щоб зупинити його, хоча б зараз. Я можу допомогти тобі дістатися до нього.", [3] = "Воля Попелоносця використовує останні сили, щоб створити зв'язок з Александросом Могрейном у Наксрамасі. Скористайтеся порталом і протистоятимете Духу Могрейна.\n\nЯкщо ви загинете в бою, поверніться до порталу в Каплиці Надії Світла, щоб знову потрапити до Наксрамаса.", [4] = "<Дух до того мерехтить, з'являється і зникає. У нього залишилося небагато часу.>", [5] = "Це... зроблено... поки що. Я відчуваю, як ця форма... починає згасати. Дякую--{клас}. Лезо... залишається пошкодженим, але... можливо... є хтось інший, хто може...\n\nТим часом... тримай його в безпеці.\n\nПерш ніж я... повністю зникну--один маленький проблиск світла залишився... який я можу дати...", ["en"] = "A Kind of Peace" },
    [89489] = { [1] = "Збільшений шанс випадання", [2] = "Тепер, коли ми знаємо, що мої винаходи працюють як окремі пристрої, наступним логічним кроком в інноваціях є покращення багаторазового використання та якості життя! Не думаю, що хтось із нас хоче викидати повну жменю золота щоразу, коли хоче перелізти через калюжу.\n\nЯк завжди, у мене є ідея.\n\nРемені – це жалюгідно недооцінений предмет спорядження, до якого зручно дістатися. Має сенс покращити їх багаторазовими гаджетами, але мені потрібно кілька, щоб потренуватися. Піди та вкради кілька.", [4] = "Я готовий почати лагодити, щойно ти принесеш мені кілька ременів.\n\nЩо? Ні, я не збираюся використовувати свої власні!", [5] = "Поки тебе не було, мені вдалося закінчити ВСІ ТРИ схеми для майстрів з ременів! Це водночас дуже вражає мене і досить сумно для тебе.\n\nЯ також зрозумів, що нам дуже пощастило, що наш хаос не привернув до нас більше уваги з боку цих надокучливих людей. Тому я не думаю, що мені взагалі потрібні ці ремені, зараз я зосереджуся на плануванні втечі. Я все одно візьму їх, щоб розпочати колекцію; не хотів би потрапити зі спущеними штанами.", ["en"] = "Increased Drop Rate" },
    [8949] = { [1] = "Вендета Фалріна", [2] = "Так, {клас:к}, це правда, мені відомі чари, які тобі потрібні. Та я не з тих, хто допомагає задарма, навіть якщо тебе прислав мій старий друг.\n\nЯ не відчуваю нічого, крім ненависті та презирства до тутешніх огрів. І не тільки їх, я ненавиджу послідовників Омокка не менше за тих, хто служить королю Ґордоку.\n\nВбий їх, що більше, то краще! Принеси мені намисто, яке вони носять на шиї, як доказ виконаної роботи. Зробиш це, і ми обговоримо твоє прохання.", [3] = "Зберіть 25 бойових намист огрів в Грізному Молоті чи Чорноскельному шпилі та поверніться до Фалріна Деревотворця в Атенеум Грізного Молота.", [4] = "Ти {стать:виконав:виконала} те, про що я просив тебе, {ім'я}?", [5] = "Хмм... як не дивно, мені не стало легше від помсти за смерть мого брата від рук цих виродків.\n\nЩо ж, ти {стать:виконав:виконала} свою частину угоди. Погляньмо, що я можу для тебе зробити.", ["en"] = "Falrin's Vendetta", ["tasks"] = { ["Ogre Warbeads"] = "бойове намисто огрів", ["Ogre Warbeads (Provided)"] = "бойове намисто огрів (видано)" } },
    [89491] = { [1] = "Складний план втечі", [2] = "Що ж, було весело, але, здається, ми затрималися надто довго. Я думав використати свої нові гаджети, щоб вибратися звідти в крайньому випадку, але я не можу перенести всі свої нові речі за одну поїздку!\n\nКоли я прибув сюди, мені вдалося встановити транспортний майданчик, як ви бачили. Все, що йому потрібно, це деяке калібрування.\n\nВізьміть цей пристрій і використовуйте його біля воріт, на подвір'ї для стрільби з лука та всередині таверни. Тоді, і тільки тоді, станьте на мій телепорт і скористайтеся своїм телепортом \"Ґаджетзан\" або \"Еверлук\", щоб запустити його.", [4] = "Вже зібрав більшість своїх речей. Як тільки ви завершите калібрування, я звідси піду!", [5] = "Ти повернувся цілим і неушкодженим, а телепорт муркоче, як орк! Гоблінська винахідливість у своєму найкращому прояві.\n\nПривіт, е-е, я був так радий розпочати, що забув передати схему для легкого зворотного шляху, коли ти будеш виходити. Без образ, правда?\n\nУ будь-якому разі, все готово для зворотних поїздок, як тільки ти збереш свій модуль. Що стосується мене, то я збираюся закінчити пакування та повернуся. Тим часом можеш звертатися до мене за запчастинами.\n\nДякую за всю допомогу!", ["en"] = "A Complicated Escape Plan", ["tasks"] = { ["Triangulation Samophlange"] = "Тріангуляція Самофланж" } },
    [895] = { [1] = "РОЗШУКУЄТЬСЯ: барон Довгоберег", [2] = "РОЗШУКУЄТЬСЯ!\n\nБарон Довгоберег, капітан \"Безтурботної\"\n\nКапітан Довгоберег з Ґілнеасу керує кораблями флібустьєрів Південних морів, і розшукується за звинуваченням у піратстві. Рештки мають бути придатні для впізнання!\n\n-- Ґазлоу", [3] = "Принесіть голову барона Довгоберега до Ґазлоу в Брашпиль.", [4] = "Що сталося? Чим я можу допомогти? Хочеш відправити вантаж чи, може, інженер потрібен?", [5] = "А! Так от чому ти тут. Знаєш, я бачив якось \"Безтурботну\" у відкритому морі. Вражаючий корабель, чи то човен... ці моряки так чіпляються до слів!\n\nЗагалом, вона так ковзала по воді, що аж дух захоплювало. Я радий, що її клятий капітан більше не турбуватиме мої кораблі.", ["en"] = "WANTED: Baron Longshore", ["tasks"] = { ["Baron Longshore's Head"] = "голова барона Довгоберега", ["Baron Longshore's Head (Provided)"] = "голова барона Довгоберега (видано)" } },
    [8950] = { [1] = "Чари підбурювача", [2] = "Я легко можу накласти на стяг чари, які тобі потрібні, {ім'я}. Однак, на жаль, у мене немає необхідних матеріалів — про такі заклинання рідко хто питає.\n\nМені знадобиться сутність одного з привидів Елдрету, що мешкають у цих залах, кілька темних рун з Некроситету та кілька великих блискучих осколків. Принеси мені все це і я накладу потрібні тобі чари.", [3] = "Принесіть Фалріну Деревотворцю в Грізний Молот: 1 сутність глузливого привида, 4 темні руни та 8 великих блискучих осколків.", [4] = "Ти {стать:приніс:принесла} необхідні матеріали, {ім'я}?", [5] = "Так, це саме те, що потрібно. Коли я закінчу, жодна сила у світі не зупинить твою ціль від прийняття виклику.", ["en"] = "The Instigator's Enchantment", ["tasks"] = { ["Dark Rune"] = "темна руна", ["Dark Rune (Provided)"] = "темна руна (видано)", ["Jeering Spectre's Essence"] = "сутність глузливого привида", ["Jeering Spectre's Essence (Provided)"] = "сутність глузливого привида (видано)", ["Large Brilliant Shard"] = "великий блискучий осколок", ["Large Brilliant Shard (Provided)"] = "великий блискучий осколок (видано)" } },
    [8953] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Деліани та скажи їй, що Бодлі — її єдиний шанс знайти інші частини. Поговори з нею і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Деліани в Залізогарт з чоботами магістра, поножами магістра та напліччям магістра.", [4] = "Ти {стать:повернувся:повернулась}, {ім'я}. Розказуй все, про що {стать:дізнався:дізналась}. Та спершу поговорімо про твою винагороду.", [5] = "Я не можу повірити, що всі наші життя в небезпеці через якийсь дурний медальйон! І ти {стать:впевнений:впевнена}, що Антіон згадав Бодлі?\n\nЩо ж, ти свою справу {стать:зробив:зробила}, тому давай розберемось з твоєю винагородою.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Magister's Boots"] = "чоботи магістра", ["Magister's Boots (Provided)"] = "чоботи магістра (видано)", ["Magister's Leggings"] = "поножі магістра", ["Magister's Leggings (Provided)"] = "поножі магістра (видано)", ["Magister's Mantle"] = "напліччя магістра", ["Magister's Mantle (Provided)"] = "напліччя магістра (видано)" } },
    [89562] = { [1] = "Мій давній ворог", [2] = "Я чув, що Калдоран був присутній у Наксрамасі, і боявся, що якщо битва зміниться, мені доведеться опинитися на передовій разом з ним.\n\nХоча Срібний Світанок підтримує вас у наданні допомоги силам Багряного Відродження, я мушу попередити вас найрішучіше: остерігайтеся Баеліна Калдорана. Мої руки тремтять від люті, навіть думаючи про цю людину та звірства, які він чинив над невинними. Йому НЕ можна довіряти. Будь ласка, благаю вас, послухайте моїх слів.", [3] = "Дізнайтеся більше про Баелін Калдоран від Леоніда Варфаломія Шановного.", [4] = "Калдорану ніколи не можна довіряти.", [5] = "Це все, що я скажу з цього приводу наразі. Мені знадобилися роки, щоб вилізти з темряви в моїй душі після того, що той чоловік зробив зі мною.\n\nМожливо, зараз ми невпевнені союзники, але я побачу, як Калдоран розплачується за свої злочини... колись. Моя клятва в цьому справі залишається в силі. Тим часом будьте надзвичайно обережні у своїх стосунках з ним.", ["en"] = "My Old Enemy" },
    [89563] = { [1] = "Тягар Леоніда", [2] = "Я не міг не підслухати вашу розмову з Леонідом про інквізитора Калдорана. Мізерні подробиці, які вам надав Леонід, — це лише крихітна частинка їхньої спільної історії та страждань, яких Калдоран йому завдав. Я був поруч, коли Леонід був у найгіршій точці свого життя, і допоміг йому знайти в собі сили знову піднятися.\n\nЯ боюся, що наша подальша співпраця з Багряним хрестовим походом зробить з Леонідом, особливо якщо це зблизить його з цією людиною.", [3] = "Отримайте інструкції від лорда Максвелла Тіросуса.", [5] = "Я пильно стежитиму за ситуацією тут, а ти пильно стеж за Калдораном, поки працюватимеш з силами рекультивації. Я не довіряю жодному з наших «союзників», а йому найменше довіряю.\n\nПоговори з Леонідом ще раз. У мене є місія, яку я доручив йому виконати, і я хотів би, щоб ти супроводжував його. Думаю, йому було б добре відволіктися від цього місця.", ["en"] = "Leonid's Burden" },
    [89567] = { [1] = "Розбитий караван", [2] = "Лорд Тіросус попросив мене дослідити залишки каравану Багряного хрестового походу в Чумному лісі вздовж дороги до Стратгольма.\n\nНещодавні повідомлення розповідають про масштабні переміщення хрестових походів по всіх Чумних землях, що призвели до розколу в Руці Тіра, і цей караван може дати нам деякі вказівки щодо їхньої мети.\n\nЯ зустрінуся з тобою там, і ми разом розслідуємо це.", [3] = "Дослідіть залишки червоного каравану в Чумному лісі, вздовж дороги до Стратгольма, і поговоріть там з Леонідом Варфаломієм Шановним, коли дізнаєтесь більше.", [4] = "У всьому цьому точно є щось дивне. Ви знайшли щось цікаве?", [5] = "Отже, цей караван містив... зразки чуми, взяті з Наксрамаса? Але чому? З якою метою? Чи намагався Багряний Хрестовий Похід вивчити чуму, щоб боротися з нею?", ["en"] = "The Wrecked Caravan" },
    [89568] = { [1] = "Щось нове", [2] = "Я думаю, нам потрібно дізнатися більше про цю нову чуму. Здається, вона спрямована на... вбивство нежиті та живих? Нежить має природний імунітет до чуми нежиті, будучи, по суті, саме від цієї чуми. Якщо те, що я підозрюю, правда, це може бути щось нове та жахливе.\n\nМені не хочеться піддавати нежить тут ще більшим мукам, але ми повинні дізнатися більше, перш ніж повернемося до Надії Світла.", [3] = "Використайте Нові Зразки Чуми на ослаблених Людожерних Гулях, Зшитих Жахах, Проклятих Магах, Солдатах Бичі та Вартових Бичі, яких можна знайти по всьому Чумному Лісу, та спостерігайте за наслідками.", [4] = "Мене непокоїть те, що я так близько до Стратголма...\n\n<Леонід Варфаломій Вельмишановний робить паузу, дивлячись у бік Стратголма, і ви помічаєте, що його рука починає трохи тремтіти.>\n\n...не звертайте уваги, це нічого.\n\nДавайте швидко завершимо нашу справу, {ім'я}.", [5] = "Вплив цих пошестей на нежить глибокий і жахливий. Якщо їх обернути проти покинутих у руїнах Лордерона, це може бути катастрофічним.\n\nЄ ще одне випробування, яке нам потрібно провести.", ["en"] = "Something New" },
    [89574] = { [1] = "Слуги смерті", [2] = "Для мене немає нічого гіршого за живих агентів короля-ліча. Я зневажаю та відкидаю тих, хто має вільну волю розрізняти добре від поганого, але водночас добровільно служить смерті. Візьміть зразки чуми ще раз та перевірте їх на живих членах Культу Проклятих поблизу.\n\nНе жалійте цих монстрів і не виявляйте до них милосердя. Вони приєдналися до проклятих, тож прокляті вони будуть.", [3] = "Використайте Нові Зразки Чуми на Темних Прикликачах та Некромантах, яких можна знайти по всій Східній Чумній Землі, та спостерігайте за наслідками.", [4] = "Я вивчаю ці дослідницькі нотатки, і те, що я бачу, жахливо.\n\nЦю чуму спричинив Червоний Хрестовий Похід.", [5] = "Це саме те, що я й очікував, ця чума має однаковий вплив як на живих, так і на мертвих. Боюся, що це віщує лихо для всіх.\n\nУ мене питання: як Червоні Хрестоносці змогли розробити таку чуму? Це вимагало б глибокого розуміння первісної чуми нежиті, а дослідження таких чум є... складним завданням для живих. Це дуже тривожно.\n\nЯ підозрюю, що ми вже дізналися все, що могли. Однак, перш ніж ми повернемося... чи можу я попросити вас про послугу?", ["en"] = "Servants of Death" },
    [896] = { [1] = "Талан шахтаря", [2] = "Перебуваючи завідувачем причалу у такому жвавому порту, як Брашпиль, доводиться тримати руку на пульсі всіх справ. Я знаю все про обмін товарами та грошима між Грабіжною бухтою і Брашпилем.\n\nОстанні новини, що я чув, - були про шахту Валун Вапняку ТзНБ \"Авантюри\" на північний схід від Драговини шламу. Один із шахтарів виявив смарагд розміром з кулак. Я знаю кількох покупців, яким було б цікаво прикупити собі щось подібне. Я навіть не проти розділити виторг від продажу 50 на 50.", [3] = "Добудьте смарагд «Котяче око» у одного з розпорядників або громил ТзНБ \"Авантюра\" і принесіть його завідувачеві причалу Запамороку в Брашпиль.", [4] = "Якби ж ми тільки знали, який саме шахтар знайшов той смарагд, то це було б як з гірки скотитись...", [5] = "Лише глянь який здоровезний, {ім'я}! Ми точно розбагатіємо! Такс, згідно з розцінками на дорогоцінні камені, що я бачив у Підштольні, зможу розрахувати твою частку - п'ятдесят відсотків, не хвилюйся!\n\nТож подивімось... Цього більш-менш буде достатньо. Приємно вести з тобою справи, {ім'я}!", ["en"] = "Miner's Fortune", ["tasks"] = { ["Cats Eye Emerald"] = "смарагд «Котяче око»", ["Cats Eye Emerald (Provided)"] = "смарагд «Котяче око» (видано)" } },
    [8960] = { [1] = "Нещасна доля Бодлі", [2] = "Отже, нам потрібно відновити медальйон? Знайти Бодлі буде непросто. Він вирушив до Чорноскельної гори, щоб спробувати знову увійти до Чорноскельного шпилю, але так і не повернувся.\n\nПро всяк випадок візьми з собою гоблінський пристрій для виявлення привидів, бо боюся, що могло статись найгірше.", [3] = "Відправляйтесь до Чорноскельної гори та скористайтесь міжвимірним шукачем привидів, щоб знайти Бодлі в Чорноскельному шпилі.", [5] = "Ти навіть не уявляєш, як я радий, що ти можеш мене бачити. Нарешті мені є з ким поговорити!\n\nТи допоможеш нам, {ім'я}? Ми не знали, що творили, і вчинили велике зло, а тепер маємо все виправити. Якщо в тебе дійсно вже є верхня частина амулета лорда Вальталака, я можу підказати, де ти зможеш знайти інші частини, щоб об'єднати їх та покласти всьому цьому край.\n\nТак, до речі, мене звуть Бодлі. Приємно познайомитись!", ["en"] = "Bodley's Unfortunate Fate" },
    [8961] = { [1] = "Три повелителі полум'я", [2] = "Для виклику лорда Вальталака потрібно зібрати інші дві частини амулета. Для цього нам знадобиться жаровня і деяке спеціальне вугілля, яке ми в ній запалимо.\n\nЄ три повелителі вогню: лорд Спалахій у Чорноскельних надрах, вогнестраж Вуглегляд у Чорноскельному шпилі та герцог попелу в Силітусі, у яких є те, що нам потрібно. Збери останки їх тіл та повертайся до мене з освяченою жаровнею, яку можна придбати у Сріблястого Світанку, якщо вони шанують тебе.", [3] = "Зберіть спалахіт Спалахія, вуглинку Вуглегляда та попіл герцога попелу разом з освяченою жаровнею та принесіть їх Бодлі в Чорноскельну гору.", [4] = "Це була наша величезна помилка... ми стали приречені, щойно погодились на те останнє замовлення. Якби тільки ми не викрали дух лорда Вальталака, який містився в амулеті. Якби тільки ми не були такі жадібні та не розділили його між собою. Я був би живий сьогодні, пив би пиво чи грався зі своїми дітьми.\n\n{ім'я}, не дозволь нашій скупості стати й твоєю загибеллю.", [5] = "Я вражений, {клас:к}, але не можна втрачати час. У мене є ще одне завдання для тебе — тобі доведеться добути ще кілька важливих компонентів, перш ніж ми продовжимо.\n\nПоговори зі мною знову, коли будеш {стать:готовий:готова} до наступного виклику.", ["en"] = "Three Kings of Flame", ["tasks"] = { ["Cinder of Cynders"] = "попіл герцога попелу", ["Cinder of Cynders (Provided)"] = "попіл герцога попелу (видано)", ["Ember of Emberseer"] = "вуглинка Вуглегляда", ["Ember of Emberseer (Provided)"] = "вуглинка Вуглегляда (видано)", ["Hallowed Brazier"] = "освячена жаровня", ["Hallowed Brazier (Provided)"] = "освячена жаровня (видано)", ["Incendicite of Incendius"] = "спалахіт Спалахія", ["Incendicite of Incendius (Provided)"] = "спалахіт Спалахія (видано)" } },
    [8962] = { [1] = "Важливі компоненти", [2] = "{Клас:к}, слухай уважно. Тепер, коли у нас є жаровня та джерело вогню, нам залишилось знайти компоненти для її наповнення. Щось, що зосередить вдосталь сили, щоб викликати дух мого загиблого товариша.\n\nМор Сиве Копито, наш найвидатніший друїд, мав багато друзів у Кенарійському Колі. Деякі з них загинули від силітідів. Мені потрібно, щоб ти {стать:забрав:забрала} друїдські останки у силітідів, які населяють околиці Вул'Регаля на південному сході Силітуса.", [3] = "Знайдіть друїдські останки та поверніться з ними до Бодлі в Чорноскельну гору.", [4] = "Ти вже {стать:повернувся:повернулась}, {клас:к}? Вдалось щось знайти?", [5] = "Гарна робота, {ім'я}. Я наповню жаровню сутністю цих останків.\n\nТепер ти маєш піти в нижню частину Чорноскельного шпиля, до кімнати у Тазз'Алорі, де мешкає воєначальник Вун, і використати жаровню, щоб викликати змучений дух мого колишнього товариша, Мора Сивого Копита. Він не може спочити з миром, доки у нього є частина амулета.", ["en"] = "Components of Importance", ["tasks"] = { ["Druidical Remains"] = "друїдські останки", ["Druidical Remains (Provided)"] = "друїдські останки (видано)" } },
    [8963] = { [1] = "Важливі компоненти", [2] = "{Клас:к}, слухай уважно. Тепер, коли у нас є жаровня та джерело вогню, нам залишилось знайти компоненти для її наповнення. Щось, що зосередить вдосталь сили, щоб викликати дух мого загиблого товариша.\n\nІзалієн, наша жриця, виросла в Зимоключі, в селищі Зоряний бриз. Мені потрібно, щоб ти {стать:забрав:забрала} реліквію Зоряного Бризу у велетнів-кригобоїв з ущелини Морозного шепоту на півдні Зимоключа, які час від часу здійснюють набіги на північ.", [3] = "Знайдіть реліквію Зоряного Бризу та поверніться з нею до Бодлі в Чорноскельну гору.", [4] = "Ти вже {стать:повернувся:повернулась}, {клас:к}? Вдалось щось знайти?", [5] = "Гарна робота, {ім'я}. Я наповню жаровню сутністю цієї реліквії.\n\nТепер ти маєш піти до каплиці Ельдретарра, що в східному крилі Грізного Молоту, і використати жаровню, щоб викликати дух Ізалієн, жриці з моєї колишньої банди. Її змучений дух знаходиться у полоні частини амулета Вальталака.", ["en"] = "Components of Importance", ["tasks"] = { ["Starbreeze Village Relic"] = "реліквія Зоряного Бризу", ["Starbreeze Village Relic (Provided)"] = "реліквія Зоряного Бризу (видано)" } },
    [8964] = { [1] = "Важливі компоненти", [2] = "{Клас:к}, слухай уважно. Тепер, коли у нас є жаровня та джерело вогню, нам залишилось знайти компоненти для її наповнення. Щось, що зосередить вдосталь сили, щоб викликати дух моїх загиблих товаришів.\n\nЯрієн та Сотос залишили нас і приєднались до Багряного Походу, повіривши в їх мету. Вони понад усе прагнули вступити до цих мерзотників. Вирушай до Десниці Тіра у Східних Чумних землях і забери блискучий меч фанатизму у тамтешніх преторів.", [3] = "Знайдіть блискучий меч фанатизму та поверніться з ним до Бодлі в Чорноскельну гору.", [4] = "Ти вже {стать:повернувся:повернулась}, {клас:к}? Вдалось щось знайти?", [5] = "Гарна робота, {ім'я}. Я наповню жаровню сутністю цього меча.\n\nТепер ти маєш піти до багряного трону, що в Багряному бастіоні Стратгольму, і використати жаровню, щоб викликати дух моїх колишніх побратимів, Ярієн та Сотоса. Їх душі ще більше викривила частина амулета Вальталака.", ["en"] = "Components of Importance", ["tasks"] = { ["Brilliant Sword of Zealotry"] = "блискучий меч фанатизму", ["Brilliant Sword of Zealotry (Provided)"] = "блискучий меч фанатизму (видано)" } },
    [8965] = { [1] = "Важливі компоненти", [2] = "{Клас:к}, слухай уважно. Тепер, коли у нас є жаровня та джерело вогню, нам залишилось знайти компоненти для її наповнення. Щось, що зосередить вдосталь сили, щоб викликати дух мого загиблого товариша.\n\nОгр-некромант, який подорожував з нами, Кормок, викликав душі мертвих вигнанців з острова Позбавлення, що неподалік південного узбережжя передгір'я Гіллзбраду. Йди туди та дістань трохи попелу душі з останків вигнанців.", [3] = "Знайдіть попіл душі вигнанця та поверніться з ним до Бодлі в Чорноскельну гору.", [4] = "Ти вже {стать:повернувся:повернулась}, {клас:к}? Вдалось щось знайти?", [5] = "Гарна робота, {ім'я}. Я наповню жаровню сутністю цього попелу.\n\nТепер ти маєш піти до Некроситету, в кімнату Раса Кригошепта, і використати жаровню, щоб викликати дух мого колишнього товариша, Кормока. Їх душі ще більше викривила частина амулета Вальталака. Частина амулета Вальталака ще більше спотворила його дух. Він не зможе спочивати з миром, доки частина амулета у нього.", ["en"] = "Components of Importance", ["tasks"] = { ["Soul Ashes of the Banished"] = "попіл душі вигнанця", ["Soul Ashes of the Banished (Provided)"] = "попіл душі вигнанця (видано)" } },
    [8966] = { [1] = "Ліва частина амулета лорда Вальталака", [2] = "Мій друг, Мор Сиве Копито, був першим, хто постраждав від володіння амулетом лорда Вальталака та фрагмента його духу, що міститься всередині. Викравши книгу заклинань і амулет Вальталака, ми втекли з верхньої частини Чорноскельного шпиля, рятуючи свої життя. Та дорогою Мор не втримався та впав вниз.\n\nПізніше ми дізналися, що насправді він не розбився, а його схопив і катував воєначальник Вун. А потім кілька примарних убивць прокралися і вбили його прямо на очах Вуна.", [3] = "Скористайтесь жаровнею поклику, щоб викликати дух Мора Сивого Копита та вбийте його. Поверніться до Бодлі в Чорноскельну гору з лівою частиною амулета лорда Вальталака та жаровнею поклику.", [4] = "Справу зроблено? Ти {стать:дістав:дістала} ліву частину амулета лорда Вальталака й нарешті {стать:впокоїв:впокоїла} дух мого старого друга, Мора Сивого Копита?", [5] = "Ти {стать:зробив:зробила} велику справу, {ім'я}. Один дух спочиває з миром, але ще чимало потрібно зробити, щоб покінчити з цим.\n\nНа жаль, я не знаю, де знаходиться права частина амулета. Але не хвилюйся, я практикувався в мистецтві ворожіння, коли був живий. Тож у мене для тебе є ще одне завдання, яке дозволить нам відшукати останню частину.", ["en"] = "The Left Piece of Lord Valthalak's Amulet", ["tasks"] = { ["Brazier of Beckoning"] = "жаровня поклику", ["Brazier of Beckoning (Provided)"] = "жаровня поклику (видано)", ["Left Piece of Lord Valthalak's Amulet"] = "ліва частина амулета лорда Вальталака", ["Left Piece of Lord Valthalak's Amulet (Provided)"] = "ліва частина амулета лорда Вальталака (видано)", ["Mor Grayhoof"] = "Мор Сиве Копито", ["Mor Grayhoof slain"] = "Мор Сиве Копито: убито" } },
    [8967] = { [1] = "Ліва частина амулета лорда Вальталака", [2] = "Після того, як ми зробили все можливе, щоб вижити, нам стало відомо, що Ізалієн, жриця нічних ельфів з нашої компанії, відправилась до стародавнього міста нічних ельфів, зараз відомого як Грізний Молот. Як ми пізніше дізналися, вона поїхала туди з особистих причин, а також щоб розкрити таємниці частини амулета, яка їй дісталась.\n\nАле їй не вдалось здійснити задумане. До нас дійшли чутки, що Альззін-Диковертень разом зі своїми прибічниками вбили її біля каплиці Ельдретарра.", [3] = "Скористайтесь жаровнею поклику, щоб викликати дух Ізалієн та вбийте його. Поверніться до Бодлі в Чорноскельну гору з лівою частиною амулета лорда Вальталака та жаровнею поклику.", [4] = "Я так розумію, ти ще не {стать:викликав:викликала} дух Ізалієн, щоб повернути ліву частину амулета лорда Вальталака, {ім'я}?", [5] = "Дякую за те, що {стать:умиротворив:умиротворила} дух Ізалієн, {ім'я}. Сподіваюсь, вона знайшла спокій разом зі своєю богинею. Але попереду ще багато справ, якщо ми хочемо покінчити з цим.\n\nНа жаль, я не знаю, де знаходиться права частина амулета. Але не хвилюйся, я практикувався в мистецтві ворожіння, коли був живий. Тож у мене для тебе є ще одне завдання, яке дозволить нам відшукати останню частину.", ["en"] = "The Left Piece of Lord Valthalak's Amulet", ["tasks"] = { ["Brazier of Beckoning"] = "жаровня поклику", ["Brazier of Beckoning (Provided)"] = "жаровня поклику (видано)", ["Isalien"] = "Ізалієн", ["Isalien slain"] = "Ізалієн: убито", ["Left Piece of Lord Valthalak's Amulet"] = "ліва частина амулета лорда Вальталака", ["Left Piece of Lord Valthalak's Amulet (Provided)"] = "ліва частина амулета лорда Вальталака (видано)" } },
    [8968] = { [1] = "Ліва частина амулета лорда Вальталака", [2] = "Ярієн та Сотос залишили вирішили приєднались до Багряного Походу, коли наша компанія розпалась. Вони забрали з собою ліву частину амулета Лорда Вальталака. Ну і грець з нею, сказав би я, але нам потрібно її повернути.\n\nНаскільки ми знаємо, вони не пройшли випробування на ритуалі посвяти і їх вбив сам верховний лицар Датроган у Багряному бастіоні.\n\nХай там як, нам... тобто тобі, доведеться забрати цю частину амулета.", [3] = "Скористайтесь жаровнею поклику, щоб викликати духів Ярієн та Сотоса та вбийте їх. Поверніться до Бодлі в Чорноскельну гору з лівою частиною амулета лорда Вальталака та жаровнею поклику.", [4] = "Ти вже {стать:впокоїв:впокоїла} душі Ярієн та Сотоса і {стать:забрав:забрала} їхню частину амулета лорда Вальталака, {клас:к}?", [5] = "Думаю, це на краще, що їх душі нарешті упокоїлися. Хай вони мені й не подобались при житті. У будь-якому випадку ми отримали те, чого хотіли, і це чудово!\n\nНа жаль, я не знаю, де знаходиться права частина амулета. Та нічого, при житті я практикував мистецтво ворожіння. Тож у мене для тебе є ще одне завдання, яке дозволить нам відшукати останню частину.", ["en"] = "The Left Piece of Lord Valthalak's Amulet", ["tasks"] = { ["Brazier of Beckoning"] = "жаровня поклику", ["Brazier of Beckoning (Provided)"] = "жаровня поклику (видано)", ["Jarien"] = "Ярієн", ["Jarien slain"] = "Ярієн: убито", ["Left Piece of Lord Valthalak's Amulet"] = "ліва частина амулета лорда Вальталака", ["Left Piece of Lord Valthalak's Amulet (Provided)"] = "ліва частина амулета лорда Вальталака (видано)", ["Sothos"] = "Сотос", ["Sothos slain"] = "Сотос: убито" } },
    [8969] = { [1] = "Ліва частина амулета лорда Вальталака", [2] = "У нас є все необхідне, тож настав час обговорити, кого ти будеш викликати.\n\nКормок був цілком нормальним, як для огра, поки він не зайнявся некромантією. Після цього його боялись навіть в нашій банді. Ніхто не здивувався, коли він забрав частину амулета і повернувся до свого нового дому, Некроситету.\n\nАле навіть там він не зміг сховатися від примарних вбивць. Вони вбили його прямо на очах у господаря, Раса Кригошепта.", [3] = "Скористайтесь жаровнею поклику, щоб викликати дух Кормока та вбийте його. Поверніться до Бодлі в Чорноскельну гору з лівою частиною амулета лорда Вальталака та жаровнею поклику.", [4] = "Я радий вітати тебе, {ім'я}, якщо ти {стать:повернувся:повернулась} з лівою частиною амулета. Якщо ж ні, будь ласка, подбай про це, у нас обмаль часу!", [5] = "Гарна робота, {ім'я}! Кормок був не таким вже й поганим, як для огра, принаймні, поки був живий. Тому я сподіваюсь, що він отримає спокій, на який заслуговує. Але попереду у нас ще багато роботи.\n\nНа жаль, я не знаю, де знаходиться права частина амулета. Але не хвилюйся, я практикував мистецтво ворожіння, коли був живий. Тож я маю для тебе ще одне завдання, яке дозволить нам відшукати останню частину.", ["en"] = "The Left Piece of Lord Valthalak's Amulet", ["tasks"] = { ["Brazier of Beckoning"] = "жаровня поклику", ["Brazier of Beckoning (Provided)"] = "жаровня поклику (видано)", ["Kormok"] = "Кормок", ["Kormok slain"] = "Кормок: убито", ["Left Piece of Lord Valthalak's Amulet"] = "ліва частина амулета лорда Вальталака", ["Left Piece of Lord Valthalak's Amulet (Provided)"] = "ліва частина амулета лорда Вальталака (видано)" } },
    [8970] = { [1] = "Я бачу острів Альказ...", [2] = "Як я вже казав, {клас:к}, при житті я думав стати віщуном. Здивую тебе, це не така й прибуткова справа. Здебільшого тому, що це небезпечно, а реагенти рідкісні та надзвичайно дорогі. Однак, моїх навичок вистачить на пошук останньої частини амулета, а разом з нею — і духу когось з моїх колишніх побратимів.\n\nАле мені знадобиться твоя допомога, {ім'я}. Вирушай на острів Альказ біля узбережжя Бруднолипкої трясовини та збери кров'яницю у наг Страшаз, що там мешкають.", [3] = "Зберіть 20 кров'яниць у наг Страшаз та поверніться до Бодлі в Чорноскельну гору.", [4] = "Кров'яниця, {ім'я}, для мого ворожіння потрібна велика купа кров'яниці. Певно, тобі доведеться взяти кількох друзів на поміч... Страшаз — небезпечні супротивники!", [5] = "Чесно кажучи, {ім'я}, я здивований, що ти {стать:повернувся живим:повернулась живою}. Та що ж, думаю, острів Альказ не найбільша проблема для тебе.\n\nДобре, дай мені хвилинку... ворожіння — це не просто клацнути пальцями й отримати відповідь.", ["en"] = "I See Alcaz Island In Your Future...", ["tasks"] = { ["Bloodkelp"] = "кров'яниця", ["Bloodkelp (Provided)"] = "кров'яниця (видано)" } },
    [8971] = { [1] = "ПОВТОРНЕ ВИКОРИСТАННЯ", ["en"] = "REUSE", ["tasks"] = { ["Homemade Bread"] = "домашній хліб", ["Pledge of Loyalty: Stormwind"] = "обітниця вірності зі Штормовію", ["Stormwind Guard's Card"] = "листівка вартового Штормовію" } },
    [8972] = { [1] = "ПОВТОРНЕ ВИКОРИСТАННЯ", ["en"] = "REUSE", ["tasks"] = { ["Freshly Baked Pie"] = "свіжовипечений пиріг", ["Grunt's Card"] = "листівка бугая", ["Pledge of Loyalty: Orgrimmar"] = "обітниця вірності з Орґріммара" } },
    [8973] = { [1] = "ПОВТОРНЕ ВИКОРИСТАННЯ", ["en"] = "REUSE", ["tasks"] = { ["Handmade Woodcraft"] = "дерев'яний виріб ручної роботи", ["Pledge of Loyalty: Darnassus"] = "обітниця вірності з Дарнаса", ["Sentinel's Card"] = "листівка стражниці" } },
    [8974] = { [1] = "ПОВТОРНЕ ВИКОРИСТАННЯ", ["en"] = "REUSE", ["tasks"] = { ["Guardian's Moldy Card"] = "запліснявіла листівка вартового", ["Pledge of Loyalty: Undercity"] = "обітниця вірності з Підмістя", ["Romantic Poem"] = "романтичний вірш" } },
    [8975] = { [1] = "ПОВТОРНЕ ВИКОРИСТАННЯ", ["en"] = "REUSE", ["tasks"] = { ["Bluffwatcher's Card"] = "листівка вартового бескиду", ["Freshly Picked Flowers"] = "свіжозібрані квіти", ["Pledge of Loyalty: Thunder Bluff"] = "обітниця вірності з Громового Бескиду" } },
    [8976] = { [1] = "ПОВТОРНЕ ВИКОРИСТАННЯ", ["en"] = "REUSE", ["tasks"] = { ["Dwarven Homebrew"] = "дворфійське домашнє пиво", ["Ironforge Guard's Card"] = "листівка вартового Залізогарта", ["Pledge of Loyalty: Ironforge"] = "обітниця вірності з Залізогарта" } },
    [8979] = { [1] = "Здогадка Фенстада", [2] = "Здається, я зрозумів причину такої поведінки. Ти відчуваєш новий запах у повітрі, що перебиває сморід каналів? Запах новомодних парфумів та одеколонів?\n\nНаші думки затьмарені якоюсь мерзенною алхімією.\n\nЄ тільки один спосіб це перевірити — принеси флакон одеколону та парфуму моїй подрузі, аптекарці Зінґе. Королівське товариство аптекарів дізнається всю правду.\n\nЯ відшкодую твої витрати коли ти повернешся.", [3] = "Принесіть 1 флакон одеколону та 1 флакон парфуму аптекарці Зінґе в Апотекарій Підмістя.", [4] = "Чим можу тобі допомогти?", [5] = "Ага, іще одна одержимість Фенстада. Він що, вважає, що Королівському товариству аптекарів немає чим зайнятися, окрім як допомагати його дрібним розслідуванням?\n\nНу добре, я потішу його душу.", ["en"] = "Fenstad's Hunch", ["tasks"] = { ["Cologne Bottle"] = "флакон одеколону", ["Cologne Bottle (Provided)"] = "флакон одеколону (видано)", ["Perfume Bottle"] = "флакон парфуму", ["Perfume Bottle (Provided)"] = "флакон парфуму (видано)" } },
    [8980] = { [1] = "Оцінка Зінґе", [2] = "Це цікаво. Схоже, що Фенстад все ж напав на якийсь слід. Я знайшов сліди речовин, що використовуються в сумішах, що контролюють розум.\n\nЦе й так відомо, що у цих парфумах є такі речовини, але деякі інгредієнти, які я знайшла... Це серйозна алхімія, навіть для члена Королівського товариства аптекарів.", [3] = "Поверніться до Фенстада Арґайла за банком Підмістя.", [5] = "Тож я мав рацію. Не варто марнувати час. Ми маємо визначити джерело цих порочних ароматів.\n\nОсь відшкодування за куплені тобою парфуми та одеколон.", ["en"] = "Zinge's Assessment" },
    [8981] = { [1] = "Підношення дарів", [4] = "Ти тут для того, щоб піднести дар кохання та обожнювання своєму улюбленому лідеру?", [5] = "Чудово! Чудово! Я покладу це до купи інших подарунків.\n\nЯ не очікував, що їх буде настільки багато! Мабуть, ви справді любите своїх лідерів.\n\nА тепер, дозволь мені додати іще один подарунок до рахунку...", ["en"] = "Gift Giving", ["tasks"] = { ["Horde Gift Collection"] = "колекція дарів Орди", ["Horde Gift Collection (Provided)"] = "колекція дарів Орди (видано)" } },
    [8982] = { [1] = "Пошук джерела", [2] = "Ми маємо дізнатися, хто є постачальником. Я помітив у аптекарки Катріни флакон парфумів. Вона сказала, що купила їх у Нормана, корчмаря.", [3] = "Поговоріть з корчмарем Норманом в Підмісті.", [5] = "А, так, я нещодавно отримав партію парфумів та одеколонів. Не знаю, наскільки довго вони протримаються на полицях — схоже, що ці аромати всім подобаються.\n\nЯкщо хочеш запитати мою думку, то я не розумію, що в цьому такого.", ["en"] = "Tracing the Source" },
    [8983] = { [1] = "Пошук джерела", [2] = "Щось не так з моїм товаром? Що ж, я ніколи не бачив, щоб стільки народу так активно купували один і той самий товар.\n\nЯ купив всю партію у торговки, на ім'я Мара Реннік. Вона в місті недавно.\n\nВона згадувала, що у неї є ще є товар, який вона має доставити кравцю у квартал Магії.", [3] = "Поговоріть з Марою Реннік у крамниці кравців у кварталі Магії Підмістя.", [5] = "Боюся, що я продала всі свої запаси парфумів та одеколонів Норману, корчмарю. Якщо хочеш придбати кілька флаконів, тобі варто поговорити з ним, якщо вони в нього ще лишилися.\n\nНе гай часу. Думаю, ти теж не встоїш перед цим одеколоном.", ["en"] = "Tracing the Source" },
    [8984] = { [1] = "Джерело знайдено", [2] = "Послухай, дії якогось пройдисвіта-аптекаря — не моя турбота. Якщо він намагається зашкодити нам, тоді дозволь мені бути першою, хто вкаже тобі правильний шлях.\n\nЯкщо він невинний, тоді йому немає чого приховувати, правильно?\n\nЯ придбала товари в аптекаря Стаффрона Лерента. Він працює у затишному куточку за маєтком Рейвенхольдт у передгір'ях Гіллзбрада. Чесно кажучи, він здався мені дещо дивним.", [3] = "Знайдіть аптекаря Стаффрона Лерента в передгір'ї Гіллзбраду за маєтком Рейвенхольдт.", [5] = "Так, це я зробив ті аромати. Прекрасний запах, чи не так? Неперевершений.\n\nКоли воїни Альянсу та Орди будуть охоплені почуттям кохання, вони не зможуть зупинити повернення Тіньової Ради.\n\nВони будуть ослаблені й непідготовлені. Поки вони будуть перейматися за своїх коханих, вони втратять пильність.\n\nРішення було таким простим. Чому мені знадобилося стільки часу, щоб знайти його? Слабке місце будь-кого — серце. І тобі вже не зупинити неминучого.", ["en"] = "The Source Revealed" },
    [8985] = { [1] = "Більше важливих компонентів", [2] = "{Клас:к}, слухай уважно. Тепер, коли ми знаємо, де знаходиться остання частина амулета, нам знадобиться ще один компонент для наповнення жаровні. Щось, що зосередить вдосталь сили, щоб викликати дух мого загиблого товариша.\n\nІзалієн, наша жриця, виросла в Зимоключі, в селищі Зоряний бриз. Мені потрібно, щоб ти {стать:забрав:забрала} реліквію Зоряного Бризу у велетнів-кригобоїв з ущелини Морозного шепоту на півдні Зимоключа, які час від часу здійснюють набіги на північ.", [3] = "Знайдіть реліквію Зоряного Бризу та поверніться з нею до Бодлі в Чорноскельну гору.", [4] = "Ти вже {стать:повернувся:повернулась}, {клас:к}? Вдалось щось знайти?", [5] = "Гарна робота, {ім'я}. Я наповню жаровню сутністю цієї реліквії.\n\nТепер ти маєш піти до каплиці Ельдретарру, що в східному крилі Грізного Молоту, і використати жаровню, щоб викликати дух Ізалієн, жриці з моєї колишньої банди. Її змучений дух знаходиться у полоні частини амулета Вальталака.\n\nО, до речі, у мене залишилося трохи кров'яниці після твоєї подорожі на острів Альказ, тож я зробив трохи зілля. Вибирай собі!", ["en"] = "More Components of Importance", ["tasks"] = { ["Starbreeze Village Relic"] = "реліквія Зоряного Бризу", ["Starbreeze Village Relic (Provided)"] = "реліквія Зоряного Бризу (видано)" } },
    [8986] = { [1] = "Більше важливих компонентів", [2] = "{Клас:к}, слухай уважно. Тепер, коли ми знаємо, де знаходиться остання частина амулета, нам знадобиться ще один компонент для наповнення жаровні. Щось, що зосередить вдосталь сили, щоб викликати дух мого загиблого товариша.\n\nМор Сиве Копито, наш найвидатніший друїд, мав багато друзів у Кенарійському Колі. Деякі з них загинули від силітідів. Мені потрібно, щоб ти {стать:забрав:забрала} друїдські останки у силітідів, які населяють околиці Вул'Регаля на південному сході Силітуса.", [3] = "Знайдіть друїдські останки та поверніться з ними до Бодлі в Чорноскельну гору.", [4] = "Ти вже {стать:повернувся:повернулась}, {клас:к}? Вдалось щось знайти?", [5] = "Гарна робота, {ім'я}. Я наповню жаровню сутністю цих останків.\n\nТепер ти маєш піти в нижню частину Чорноскельного шпиля, до кімнати у Тазз'Алорі, де мешкає воєначальник Вун, і використати жаровню, щоб викликати змучений дух мого колишнього товариша, Мора Сивого Копита. Він не може спочити з миром, доки у нього є частина амулета.\n\nО, до речі, у мене залишилося трохи кров'яниці після твоєї подорожі на острів Альказ, тож я зробив трохи зілля. Вибирай собі!", ["en"] = "More Components of Importance", ["tasks"] = { ["Druidical Remains"] = "друїдські останки", ["Druidical Remains (Provided)"] = "друїдські останки (видано)" } },
    [8987] = { [1] = "Більше важливих компонентів", [2] = "{Клас:к}, слухай уважно. Тепер, коли ми знаємо, де знаходиться остання частина амулета, нам знадобиться ще один компонент для наповнення жаровні. Щось, що зосередить вдосталь сили, щоб викликати дух мого загиблого товариша.\n\nЯрієн та Сотос залишили нас і приєднались до Багряного Походу, повіривши в їх мету. Вони понад усе прагнули вступити до цих мерзотників. Вирушай до Десниці Тіра у Східних Чумних землях і забери блискучий меч фанатизму у тамтешніх преторів.", [3] = "Знайдіть блискучий меч фанатизму та поверніться з ним до Бодлі в Чорноскельну гору.", [4] = "Ти вже {стать:повернувся:повернулась}, {клас:к}? Вдалось щось знайти?", [5] = "Гарна робота, {ім'я}. Я наповню жаровню сутністю цього меча.\n\nТепер ти маєш піти до багряного трону, що в Багряному бастіоні Стратгольму, і використати жаровню, щоб викликати дух моїх колишніх побратимів, Ярієн та Сотоса. Їх душі ще більше викривила частина амулета Вальталака.\n\nО, до речі, у мене залишилося трохи кров'яниці після твоєї подорожі на острів Альказ, тож я зробив трохи зілля. Вибирай собі!", ["en"] = "More Components of Importance", ["tasks"] = { ["Brilliant Sword of Zealotry"] = "блискучий меч фанатизму", ["Brilliant Sword of Zealotry (Provided)"] = "блискучий меч фанатизму (видано)" } },
    [8988] = { [1] = "Більше важливих компонентів", [2] = "{Клас:к}, слухай уважно. Тепер, коли ми знаємо, де знаходиться остання частина амулета, нам знадобиться ще один компонент для наповнення жаровні. Щось, що зосередить вдосталь сили, щоб викликати дух мого загиблого товариша.\n\nОгр-некромант, який подорожував з нами, Кормок, викликав душі мертвих вигнанців з острова Позбавлення, що неподалік південного узбережжя передгір'я Гіллзбраду. Йди туди та дістань трохи попелу душі з останків вигнанців.", [3] = "Знайдіть попіл душі вигнанця та поверніться з ним до Бодлі в Чорноскельну гору.", [4] = "Ти вже {стать:повернувся:повернулась}, {клас:к}? Вдалось щось знайти?", [5] = "Гарна робота, {ім'я}. Я наповню жаровню сутністю цього попелу.\n\nТепер ти маєш піти до Некроситету, в кімнату Раса Кригошепта, і використати жаровню, щоб викликати дух мого колишнього товариша, Кормока. Їх душі ще більше викривила частина амулета Вальталака. Частина амулета Вальталака ще більше спотворила його дух. Він не зможе спочивати з миром, доки частина амулета у нього.\n\nО, до речі, у мене залишилося трохи кров'яниці після твоєї подорожі на острів Альказ, тож я зробив трохи зілля. Вибирай собі!", ["en"] = "More Components of Importance", ["tasks"] = { ["Soul Ashes of the Banished"] = "попіл душі вигнанця", ["Soul Ashes of the Banished (Provided)"] = "попіл душі вигнанця (видано)" } },
    [8989] = { [1] = "Права частина амулета лорда Вальталака", [2] = "Мій друг, Мор Сиве Копито, був першим, хто постраждав від володіння амулетом лорда Вальталака та фрагмента його духу, що міститься всередині. Викравши книгу заклинань і амулет Вальталака, ми втекли з верхньої частини Чорноскельного шпиля, рятуючи свої життя. Та дорогою Мор не втримався та впав вниз.\n\nПізніше ми дізналися, що насправді він не розбився, а його схопив і катував воєначальник Вун. А потім кілька примарних убивць прокралися і вбили його прямо на очах Вуна.", [3] = "Скористайтеся жаровнею поклику, щоб викликати дух Мора Сивого Копита та вбийте його. Поверніться до Бодлі в Чорноскельну гору з зібраним амулетом лорда Вальталака та жаровнею поклику.", [4] = "Справу зроблено? Ти {стать:дістав:дістала} праву частину амулета лорда Вальталака, {стать:зібрав:зібрала} його і нарешті {стать:впокоїв:впокоїла} дух мого старого друга, Мора Сивого Копита?", [5] = "Дякую за допомогу Мору Сивому Копиту, {ім'я}. Ще один дух спочиває з миром, а нам нарешті вдалось зібрати амулет! Але, найважче, випробування ще попереду.\n\nДля того, щоб жаровня була здатна викликати лорда Вальталака, тобі доведеться зібрати ще кілька предметів і принести мені.", ["en"] = "The Right Piece of Lord Valthalak's Amulet", ["tasks"] = { ["Brazier of Beckoning"] = "жаровня поклику", ["Brazier of Beckoning (Provided)"] = "жаровня поклику (видано)", ["Lord Valthalak's Amulet"] = "амулет лорда Вальталака", ["Lord Valthalak's Amulet (Provided)"] = "амулет лорда Вальталака (видано)", ["Mor Grayhoof"] = "Мор Сиве Копито", ["Mor Grayhoof slain"] = "Мор Сиве Копито: убито" } },
    [8990] = { [1] = "Права частина амулета лорда Вальталака", [2] = "Пізніше, коли ми робили все можливе, щоб вижити, нам стало відомо, що Ізалієн, жриця нічних ельфів з нашої компанії, відправилась до стародавнього міста нічних ельфів, тепер відомого як Грізний Молот. Наскільки нам вдалося дізнатися, вона поїхала туди з особистих причин, а також щоб розкрити таємниці частини амулета, яка їй дісталась.\n\nАле їй не вдалось здійснити задумане. До нас дійшли чутки, що Альззін-Диковертень і його прибічники вбили її біля каплиці Ельдретарра.", [3] = "Скористайтесь жаровнею поклику, щоб викликати дух Ізалієн та вбийте його. Поверніться до Бодлі в Чорноскельну гору з зібраним амулетом лорда Вальталака та жаровнею поклику.", [4] = "Я так розумію, ти ще не {стать:викликав:викликала} дух Ізалієн, щоб повернути праву частину амулета лорда Вальталака, {ім'я}? Не забудь з'єднати обидві частини амулета перед тим, як віддати його мені.", [5] = "Дякую за те, що {стать:умиротворив:умиротворила} дух Ізалієн, {ім'я}. Сподіваюсь, вона знайшла спокій разом зі своєю богинею. А нам, нарешті, вдалось зібрати амулет! Але найважче випробування ще попереду.\n\nДля того, щоб жаровня була здатна викликати лорда Вальталака, тобі доведеться зібрати ще кілька предметів і принести їх мені.", ["en"] = "The Right Piece of Lord Valthalak's Amulet", ["tasks"] = { ["Brazier of Beckoning"] = "жаровня поклику", ["Brazier of Beckoning (Provided)"] = "жаровня поклику (видано)", ["Isalien"] = "Ізалієн", ["Isalien slain"] = "Ізалієн: убито", ["Lord Valthalak's Amulet"] = "амулет лорда Вальталака", ["Lord Valthalak's Amulet (Provided)"] = "амулет лорда Вальталака (видано)" } },
    [8991] = { [1] = "Права частина амулета лорда Вальталака", [2] = "Ярієн та Сотос залишили вирішили приєднались до Багряного Походу, коли наша компанія розпалась. Вони забрали з собою праву частину амулета Лорда Вальталака. Ну і грець з нею, сказав би я, але нам потрібно її повернути.\n\nНаскільки ми знаємо, вони не пройшли випробування на ритуалі посвяти і їх вбив сам верховний лицар Датроган у Багряному бастіоні.\n\nХай там як, нам... тобто тобі, доведеться забрати цю частину амулета.", [3] = "Скористайтесь жаровнею поклику, щоб викликати духів Ярієн та Сотоса та вбийте їх. Поверніться до Бодлі в Чорноскельну гору з зібраним амулетом лорда Вальталака та жаровнею поклику.", [4] = "Ти вже {стать:впокоїв:впокоїла} душі Ярієн та Сотоса і {стать:зібрав:зібрала} докупи амулет лорда Вальталака, {клас:к}?", [5] = "Думаю, це на краще, що їх душі нарешті упокоїлися. Хай вони мені й не подобались при житті. У будь-якому випадку ми отримали те, чого хотіли, і нарешті амулет зібрано! Але найважче випробування ще попереду.\n\nДля того, щоб жаровня була здатна викликати лорда Вальталака, тобі доведеться зібрати ще кілька предметів і принести їх мені.", ["en"] = "The Right Piece of Lord Valthalak's Amulet", ["tasks"] = { ["Brazier of Beckoning"] = "жаровня поклику", ["Brazier of Beckoning (Provided)"] = "жаровня поклику (видано)", ["Jarien"] = "Ярієн", ["Jarien slain"] = "Ярієн: убито", ["Lord Valthalak's Amulet"] = "амулет лорда Вальталака", ["Lord Valthalak's Amulet (Provided)"] = "амулет лорда Вальталака (видано)", ["Sothos"] = "Сотос", ["Sothos slain"] = "Сотос: убито" } },
    [8992] = { [1] = "Права частина амулета лорда Вальталака", [2] = "У нас є все необхідне, тож настав час обговорити, кого ти будеш викликати.\n\nКормок був цілком нормальним, як для огра, поки він не зайнявся некромантією. Після цього його боялись навіть в нашій банді. Ніхто не здивувався, коли він забрав частину амулета і повернувся до свого нового дому, Некроситету.\n\nАле навіть там він не зміг сховатися від примарних вбивць. Вони вбили його прямо на очах у господаря, Раса Кригошепта.", [3] = "Скористайтесь жаровнею поклику, щоб викликати дух Кормока та вбийте його. Поверніться до Бодлі в Чорноскельну гору з зібраним амулетом лорда Вальталака та жаровнею поклику.", [4] = "Я радий вітати тебе, {ім'я}, якщо ти {стать:повернувся:повернулась} з зібраним амулетом. Якщо ж ні, будь ласка, подбай про це, у нас обмаль часу!", [5] = "Гарна робота, {ім'я}! Кормок був не таким вже й поганим, як для огра, принаймні, поки був живий. Тому я сподіваюсь, що він отримає спокій, на який заслуговує. Тепер ми маємо зібраний амулет, але попереду ще багато роботи.\n\nДля того, щоб жаровня була здатна викликати лорда Вальталака, тобі доведеться зібрати ще кілька предметів і принести їх мені.", ["en"] = "The Right Piece of Lord Valthalak's Amulet", ["tasks"] = { ["Brazier of Beckoning"] = "жаровня поклику", ["Brazier of Beckoning (Provided)"] = "жаровня поклику (видано)", ["Kormok"] = "Кормок", ["Kormok slain"] = "Кормок: убито", ["Lord Valthalak's Amulet"] = "амулет лорда Вальталака", ["Lord Valthalak's Amulet (Provided)"] = "амулет лорда Вальталака (видано)" } },
    [8994] = { [1] = "Останні приготування", [2] = "Ми майже завершили, {клас:к}. Залишилося знайти ще кілька компонентів, щоб я міг налаштувати жаровню на виклик лорда Вальталака.\n\nДля початку я попрошу тебе вирушити до Чорноскельного шпиля і вбити тамтешніх орків. Вони носять поручі з особливого сплаву, який містить необхідний мені метал. Тож мені знадобиться їх якнайбільше, щоб добути необхідну кількість металу. А ще, щоб завершити підготовку жаровні, мені знадобиться настій великої сили.\n\nНехай щастить, {ім'я}!", [3] = "Зберіть 40 поручів Чорнокаменю та добудьте настій великої сили. Поверніться з ними до Бодлі в Чорноскельну гору.", [4] = "Ми пройшли довгий шлях, {ім'я}. Я просто хотів сказати, що б не сталося, дякую тобі! Ти {стать:наражав:наражала} себе на смертельну небезпеку, намагаючись допомогти вцілілим членам нашої ватаги найманців, Примарного Клинка, і, як на мене, ти тепер {стать:один:одна} із нас.", [5] = "Ось і все. Я добуду метал з поручів і наповню жаровню цими останніми компонентами. Тоді все буде готове до виклику лорда Вальталака і ми, нарешті, зможемо повернути йому амулет.\n\nТи {стать:пройшов:пройшла} чималий шлях, {ім'я}, тож не вагайся, кінець вже близько!", ["en"] = "Final Preparations", ["tasks"] = { ["Blackrock Bracer"] = "поручі Чорнокаменю", ["Blackrock Bracer (Provided)"] = "поручі Чорнокаменю (видано)", ["Flask of Supreme Power"] = "настій великої сили", ["Flask of Supreme Power (Provided)"] = "настій великої сили (видано)" } },
    [8995] = { [1] = "Моя провина, лорде Вальталак", [2] = "Тепер все готово, {ім'я}.\n\nЗа життя лорд Вальталак проживав в місці, що зараз зветься кімнатою Звіра. Йди туди та скористайся жаровнею для виклику лорда Вальталака. Це відновить його тіло, тому тобі доведеться вбити його знову. Та спершу подбай про Звіра та обов'язково візьми з собою вдосталь друзів, щоб вижити у верхній частині Чорноскельного шпиля.\n\nКоли вб'єш Вальталака, використай амулет на його трупі. Після возз'єднання з душею він, ймовірно, також захоче повернути свій амулет.\n\nНехай щастить!", [3] = "Скористайтесь жаровнею для виклику лорда Вальталака. Вбийте його та використайте амулет на його мертвому тілі, після цього віддайте амулет духу лорда Вальталака.", [4] = "{Клас:к}, як ти смієш порушувати мій спокій?!", [5] = "Тобі пощастило, що я знаю, що тебе не було серед тих покидьків, які викрали мій амулет.\n\nТепер я заберу те, що є моїм по праву, {стать:смертний:смертна}! Віддай мені амулет!", ["en"] = "Mea Culpa, Lord Valthalak", ["tasks"] = { ["Lord Valthalak"] = "Лорд Валталак", ["Lord Valthalak (Provided)"] = "Лорд Валталак (видано)", ["Lord Valthalak slain"] = "Лорд Валталак: убито", ["Lord Valthalak's Amulet"] = "амулет лорда Вальталака", ["Lord Valthalak's Amulet (Provided)"] = "амулет лорда Вальталака (видано)" } },
    [8996] = { [1] = "Повернення до Бодлі", [2] = "Цього разу я прощаю тобі твою зухвалість, {клас:к}, тому що сьогодні ти {стать:здійснив:здійснила} благородний вчинок, повернувши мені решту моєї викраденої душі. Попри твою очевидну слабкість, {раса:к}, ти {стать:проявив:проявила} сміливість та міць духу, на відміну від тих, хто вкрав мою душу!\n\nПовертайся до них, поки я не передумав і не прикінчив тебе на місці. Іди до них і скажи, що їм нічого не загрожує... поки що.", [3] = "Поверніться до Бодлі в Чорноскельну гору та віддайте йому жаровню поклику.", [4] = "{ім'я}, ти {стать:повернувся:повернулась} і все ще {стать:живим:живою}! Ну, хоч комусь з нас це вдалось.\n\nТобі доведеться про все мені розповісти!", [5] = "Він справді все це сказав? Я не можу повірити, що він відкличе своїх примарних вбивць, хоч він і натякнув на те, що завдасть моїм живим товаришам шкоди в майбутньому.\n\nЦе великий день, {ім'я}! Ти {стать:зробив:зробила} те, що мало кому вдалось, і {стать:звільнив:звільнила} нас від нашої провини, принаймні частково.\n\nДякую! На знак вдячності я хотів би віддати тобі цю жаровню. Ти можеш використовувати її, щоб викликати духів у тих самих місцях, де ти вже {стать:викликав:викликала} їх. І навіть в кількох інших.", ["en"] = "Return to Bodley", ["tasks"] = { ["Brazier of Beckoning"] = "жаровня поклику", ["Brazier of Beckoning (Provided)"] = "жаровня поклику (видано)" } },
    [900] = { [1] = "Самофланж", [2] = "Три регулювальні клапани наразі відкриті. Судячи з написів на панелі управління, їх треба закрити, перш ніж вимикати пристрій.", [3] = "Закрийте паливний регулювальний клапан, регуляторний клапан і головний регулювальний клапан, а потім знову скористайтесь панеллю управління.", [4] = "Миготливі лампочки на консолі управління вказують на те, що головні регулювальні клапани не перекриті.", [5] = "Лампочки, що вказують на три регулювальні клапани, повільно згасають. Зелений вогник змінюється жовтим, а перемикач, що керує пристроєм, тепер активний, і при закритих клапанах панель можна вимкнути.", ["en"] = "Samophlange", ["tasks"] = { ["Shut off Fuel Control Valve"] = "Вимкніть клапан регулювання палива", ["Shut off Fuel Control Valve (Provided)"] = "Вимкніть клапан регулювання палива (видано)", ["Shut off Fuel Control Valve slain"] = "Вимкніть клапан регулювання палива: убито", ["Shut off Main Control Valve"] = "Закрийте головний регулювальний клапан", ["Shut off Main Control Valve (Provided)"] = "Закрийте головний регулювальний клапан (видано)", ["Shut off Main Control Valve slain"] = "Закрийте головний регулювальний клапан: убито", ["Shut off Regulator Valve"] = "Запірний регуляторний клапан", ["Shut off Regulator Valve (Provided)"] = "Запірний регуляторний клапан (видано)", ["Shut off Regulator Valve slain"] = "Запірний регуляторний клапан: убито" } },
    [901] = { [1] = "Самофланж", [2] = "Тепер, коли пристрій вимкнено, панель управління можна відкрити та вийняти з неї самофланж. Залишається лише здобути ключ для розблокування панелі.", [3] = "Отримайте ключ від панелі у штукаря Вугрелова та скористайтесь ним на панелі управління.", [4] = "Лампочки на панелі згасли, стрілки всіх приладів стоять на нульовій позначці, пристрій працює на холостому ходу.", [5] = "Ви повертаєте ключ у замку і панель управління відкривається. Червоний індикатор у верхній частині панелі вимикається, і тепер пристрій повністю знеструмлений.", ["en"] = "Samophlange", ["tasks"] = { ["Console Key"] = "ключ від панелі", ["Console Key (Provided)"] = "ключ від панелі (видано)" } },
    [90107] = { [1] = "Реформований клинок", [2] = "Гадаю, я довела сплав до такого рівня, що зможемо надійно використовувати його для виготовлення заготовки клинка. На щастя, у нас також є багато сировини, враховуючи все, що ви вже для мене зібрали.\n\nВідійдіть, будь ласка. Робота в кузні може бути... драматичною.", [5] = "Готово. Хоча мій світлокований сплав є продуктом святої магії, цей клинок у його нинішньому вигляді саме такий: простий клинок. Збирати решту частин докупи залежить від тебе та твого друга-примари.\n\nЯ давно не відчував, що досягнув успіху, але мушу зізнатися, що в мене погане передчуття щодо всього цього. Цікаво, чи не було б краще залишити Попелоносця зламаним. Це здається неправильним, ніби цього не мало статися.", ["en"] = "The Blade Reformed" },
    [90116] = { [1] = "Святі Нитки", [2] = "Цей ткацький верстат особливий. Чи знаєте ви це? Усі наші майстри отримали благословення від наших первосвящеників.\n\nЗокрема, ткацький верстат приваблює тканини та нитки, що розлітаються, призначені для використання в найсвятішому з наших церемоніальних облачень. З часом у нас збереться достатньо, щоб створити новий одяг, і ці дні є приводом для святкування, принаймні для мене.\n\nЯкщо вам цікаво, як працює цей процес, протягніть кілька болтів біля ткацького верстата та спостерігайте за роботою Світла.", [3] = "Здобувайте Тканини Світанку, сплітаючи тканину в рулони, перебуваючи поблизу Ткацького верстата Хрестоносця. Поверніться до Тейлора, коли у вас буде достатньо.", [4] = "Зазвичай, щоб накопичити достатньо тканини для світанку, потрібно кілька більших проектів, таких як сорочки чи штани, але для вашої демонстрації, я вважаю, плетіння рулонів буде досить простим завданням.", [5] = "Чудово! Звичайно, це лише невелика частина ризи, гідна абата Червоного кольору, але я гадаю, що тепер ви глибше цінуєте власну майстерність.\n\nЯ заберу це у вас і сховатиму. Викрійка священних риз є суворо охоронюваною таємницею, але я хотів би, щоб ви мали цю. Глибокі та міцні рюкзаки — це розкіш у наші дні, але вони варті інвестицій. Хто знає, можливо, ви зможете розпочати бізнес з продажу сумок?", ["en"] = "Holy Threads" },
    [90120] = { [1] = "Червоний не мертвий", [2] = "Гм, до речі про секрети, я працюю над новим проектом: розкішні рюкзаки для наших найвищих солдатів. Вони мають бути великими, виготовленими з найкращого шовку, і, найголовніше, червоними, як герб Багряного Хрестового Походу.\n\nМатеріал – це найлегша частина, я маю намір використати для цього ваші нитки, виткані світанком. Однак знайти ідеальний барвник далеко за межами моїх можливостей. Обшукайте світ у пошуках ідеального червоного відтінку, і я вважатиму вас партнером у цій справі, поділившись з вами своїм остаточним дизайном.", [3] = "Здобувайте різноманітні матеріали, які можна використовувати як яскраво-червоний барвник. Червоний барвник та Червону Троянду можна знайти у торговців. Вогняний цвіт можна придбати у Травників. Кров Героїв можна знайти в Чумних землях. Багряне Листя для видобутку барвника можна знайти поблизу озера Меннар в Азшарі.", [4] = "Не поспішайте, справді. Це не що інше, як моя пристрасть. Мене набагато більше цікавить пошук найкращого червоного барвника, який ми можемо знайти, ніж зберігання цих речей на полицях, і я б волів, щоб ви так само старанно працювали, ніж поспішали заради мене.\n\nЯ буду тут.", [5] = "У тебе природне чуття до краси! Не те щоб я колись сумнівалася в тобі, але я не очікувала одразу знайти відтінок червоного, який так сильно мене вразить. Проте ти принесла мені кілька!\n\n<Тейлор захоплюється кандидатами на барвники один за одним, не збентежена думкою, що один флакон повний крові.>\n\nТі, що мають написи «Кров Героїв» та «Багряний Листопад» – мої улюблені, і це складний вибір. Думаю, для нас двох має сенс використовувати різні барвники, тому я візьму Листопад.", ["en"] = "Red is Not Dead" },
    [9015] = { [1] = "Виклик", [2] = "Послухай, {ім'я}. Щоб стяг спрацював належним чином, тобі потрібно буде увійти в Кільце Закону, що розташоване в Чорноскельних надрах. Коли верховний суддя Хмурокамінь винесе тобі вирок, встроми стяг у землю на знак непокори.\n\nТелдрен не зможе стриматись і прийме виклик, сповнений бажанням битися з тобою. Щойно отримаєш те, що шукаєш — повертайся до Антіона.", [3] = "Увійдіть в Кільце Закону, що в Чорноскельних надрах, вислухайте вирок верховного судді Хмурокаменя та встроміть стяг виклику в центр кола. Вбийте Телдрена та його гладіаторів, після чого поверніться до Антіона Гармона у Східні Зачумлені землі з першою частиною амулета лорда Вальталака.", [4] = "Ти {стать:повернувся:повернулась}, {ім'я}!", [5] = "Ти {стать:знайшов:знайшла} частину амулета, {ім'я}?", ["en"] = "The Challenge", ["tasks"] = { ["Theldren's Team Defeated"] = "Команда Телдрена зазнала поразки", ["Top Piece of Lord Valthalak's Amulet"] = "верхня частина амулету лорда Вальталака", ["Top Piece of Lord Valthalak's Amulet (Provided)"] = "верхня частина амулету лорда Вальталака (видано)" } },
    [9019] = { [1] = "Прощальні слова Антіона", [2] = "У цьому амулеті зберігалася душа Вальталака. Через нашу жадібність ми безглуздо розділили його на три частини, не розуміючи, яке прокляття на нас чекає.\n\nЄдиний спосіб зупинити закляття Вальталака — зібрати медальйон докупи. Повертайся до Моквара та скажи йому, що Бодлі — його єдиний шанс знайти інші частини. Поговори з ним і про обумовлену нагороду.\n\nА я, нарешті, буду спочивати з миром. Бажаю удачі — вона тобі знадобиться!", [3] = "Поверніться до Моквара в Орґріммар із сандалями відданості, спідницею відданості та напліччям відданості.", [4] = "Ти {стать:повернувся:повернулась}, і я бачу по твоїх очах, що ти хочеш мені багато чого розповісти, {ім'я}. Та спершу подбаймо про твою винагороду.", [5] = "На нас наклали це прокляття за один лише медальйон. Лорд Вальталак, безумовно, вміє затаїти образу.\n\nМи постараємося знайти решту частин — сподіваюся, до того, як я загину. Але спершу давай обговоримо твою винагороду.", ["en"] = "Anthion's Parting Words", ["tasks"] = { ["Devout Mantle"] = "напліччя відданості", ["Devout Mantle (Provided)"] = "напліччя відданості (видано)", ["Devout Sandals"] = "сандалі відданості", ["Devout Sandals (Provided)"] = "сандалі відданості (видано)", ["Devout Skirt"] = "спідниця відданості", ["Devout Skirt (Provided)"] = "спідниця відданості (видано)" } },
    [902] = { [1] = "Самофланж", [2] = "Відкривши лицьову частину панелі управління, ви знаходите густе переплетення дротів, трубок та інших дивних механічних об'єктів, більшість з яких, схоже, не мають жодного практичного призначення. Відсунувши їх убік, ви знаходите самофланж і з легкістю висмикуєте його з заглибини.", [3] = "Принесіть самофланж Гуркоклапанові в Брашпиль.", [4] = "О, ти {стать:повернувся:повернулась}, {ім'я:к}! Самофланж {стать:приніс:принесла}?", [5] = "Це... е-е-е... цікаво... так. Я відправлю його в штаб-квартиру Спілки штукарів в Підштольню. Не сумніваюся, коли цю штуку розберуть та ретельно вивчать, вони зможуть зрозуміти її призначення.\n\nАле, можливо, спочатку я сам трохи огляну його...", ["en"] = "Samophlange", ["tasks"] = { ["Samophlange"] = "самофланж", ["Samophlange (Provided)"] = "самофланж (видано)" } },
    [9023] = { [1] = "Ідеальна отрута", [2] = "Ми з братом займаємося виготовленням отрут для маєтку Рейвенхольдт.\n\nЛорд Рейвенхольдт доручив мені знайти нову надзвичайно ефективну отруту, яку можна виготовити з отруйних залоз мешканців Зул'Ґуруба та руїн Ан'Кіражу.\n\nУ цих проклятих руїнах мешкають дві особливо отруйні істоти, які, можливо, мають те, що нам потрібно, {клас:к}. Принеси мені отруйні залози Куріннакса і Веноксіса, і ми будемо тобі безмежно вдячні.", [3] = "Принесіть Дірку Громолісу з Кенарійської цитаделі отруйні залози Веноксіса та Куріннакса.", [4] = "Це не якийсь там маленький наліт, {ім'я:к}. Тобі знадобиться допомога друзів.", [5] = "Рейвенхольдт вдячний тобі, {стать:герою:героїне}! Обирай свою нагороду!", ["en"] = "The Perfect Poison", ["tasks"] = { ["Kurinnaxx's Venom Sac"] = "отруйна залоза Куріннакса", ["Kurinnaxx's Venom Sac (Provided)"] = "отруйна залоза Куріннакса (видано)", ["Venoxis's Venom Sac"] = "отруйна залоза Веноксіса", ["Venoxis's Venom Sac (Provided)"] = "отруйна залоза Веноксіса (видано)" } },
    [9024] = { [1] = "Здогадка Арістана", [2] = "Я зрозумів! Ти відчуваєш новий запах у повітрі? Запах новомодних парфумів та одеколонів? Наші вартові не стали б просто так нехтувати своїми службовими обов'язками.\n\nЯкщо тільки їхній розум не затьмарила якась мерзенна алхімія.\n\nЄ тільки один спосіб це перевірити — принеси флакон одеколону та парфуму Моргану Товкачу і розкажи йому про мої підозри. Я відшкодую твої витрати коли ти повернешся.", [3] = "Принесіть 1 флакон одеколону та 1 флакон парфуму Моргану Товкачу в Торговий район Штормовію.", [4] = "Я можу тобі чимось допомогти?", [5] = "Я розумію стурбованість Арістана, але я вважаю, що він дещо перебільшує. Нехай юні чоловіки та жінки роблять, що робили. Я думаю, що Арістан просто забув що значить бути молодим та закоханим.\n\nАле краще йому цього не говорити.", ["en"] = "Aristan's Hunch", ["tasks"] = { ["Cologne Bottle"] = "флакон одеколону", ["Cologne Bottle (Provided)"] = "флакон одеколону (видано)", ["Perfume Bottle"] = "флакон парфуму", ["Perfume Bottle (Provided)"] = "флакон парфуму (видано)" } },
    [9025] = { [1] = "Відкриття Моргана", [2] = "Схоже, що Арістан все ж напав на якийсь слід. Я знайшов сліди речовин, які використовувалися у любовних зіллях та сумішах, що змінюють свідомість.\n\nЦе й так відомо, що у цих парфумах є такі речовини, але деякі інгредієнти, які я знайшов... Пахне цікаво.", [3] = "Поверніться до Арістана Моттара за банком у Торговому районі Штормовію.", [5] = "Хоча я знав, що так воно і буде, але від того, що мої підозри підтвердилися, легше не стало. Ми повинні ретельно продумати наш наступний крок.\n\nОсь, компенсація за придбані тобою одеколон та парфуми.", ["en"] = "Morgan's Discovery" },
    [9026] = { [1] = "Пошук джерела", [2] = "Ми маємо знайти джерело. Я бачив багатьох, у тому числі й вартових, що заходили до \"Позолоченої Троянди\". Поговори з Еллісон. Якщо вона їх продає, вона зможе розповісти, звідки вона їх взяла.", [3] = "Поговоріть з корчмаркою Еллісон в \"Позолоченій троянді\" в торговому районі Штормовію.", [5] = "О, так, я нещодавно отримала партію одеколонів та парфумів. Вони так гарно продаються, навіть не знаю, наскільки довго вони протримаються на полицях.\n\nЯкщо хочеш запитати мою думку, то це якось нудно. Я маю на увазі, що всі тепер пахнуть однаково. Так, запах хороший, але все ж...", ["en"] = "Tracing the Source" },
    [9027] = { [1] = "Пошук джерела", [2] = "Щось дивне в одеколоні? Можливо. Я ніколи не бачила, щоб стільки народу так активно купували один і той самий товар.\n\nПослухай, якщо з ними щось не так, я також хочу знати про це. Я купила всю партію у торговця, на ім'я Еверт Сорісам. Він у місті недавно.\n\nВін сказав, що у нього є ще товари, які він збирався доставити в \"Найтоншу пряжу\".", [3] = "Поговоріть з Евертом Сорісамом в \"Найтоншій пряжі\" вздовж каналів.", [5] = "Так, звісно. Ці аромати — хіт сезону! Ти, мабуть, {стать:п'ятий чи шостий:п'ята чи шоста} за цю годину, хто запитує про них.\n\nТа боюся, що всі мої запаси розпродані. Якщо ти бажаєш придбати кілька флаконів, тобі варто поговорити з Еллісон, корчмаркою \"Позолоченої троянди\".\n\nНе гай часу. Думаю, ти теж не встоїш перед цим одеколоном.", ["en"] = "Tracing the Source" },
    [9028] = { [1] = "Джерело знайдено", [2] = "Що? Зрада? Ні, ні, запевняю тебе, мої наміри були абсолютно невинними.\n\nЩо поганого у тому, щоб допомогти тим, хто бажає полегшити болючий ритуал залицяння? Слухай, це не злочин.\n\nІ щоб довести, що я не бажав нічого поганого, я навіть назву джерело цих ароматів.\n\nЇх постачав мені Стаффрон Лерент, свого роду аптекар. Я ніколи з ним не бачився.\n\nНаш гоблін-посередник сказав, що цей аптекар працює десь у передгір'ях Гіллзбрада, за тим загадковим маєтком Рейвенхольдт. Зичу тобі удачі в його пошуках.", [3] = "Знайдіть аптекаря Стаффрона Лерента в передгір'ї Гіллзбраду за маєтком Рейвенхольдт.", [5] = "Так, це я зробив ті аромати. Прекрасний запах, чи не так? Неперевершений.\n\nКоли воїни Альянсу та Орди будуть охоплені почуттям кохання, вони не зможуть зупинити повернення Тіньової Ради.\n\nВони будуть ослаблені й непідготовлені. Поки вони будуть перейматися за своїх коханих, вони втратять пильність.\n\nРішення було таким простим. Чому мені знадобилося стільки часу, щоб знайти його? Слабке місце будь-кого — серце. І тобі вже не зупинити неминучого.", ["en"] = "The Source Revealed" },
    [9029] = { [1] = "Киплячий казан", [5] = "З казана доноситься приємний запах.", ["en"] = "A Bubbling Cauldron" },
    [9033] = { [1] = "Відлуння війни", [2] = "З останньої війни минуло п'ять років...\n\nДесятки тисяч життів було втрачено і заради чого? Нам так і не вдалося позбутися загрози.\n\nІ Король-ліч повернувся... Його права рука, Кел'Тузад, готується до нового нападу на наші землі.\n\nМи цього не дозволимо! Доведи свою відданість. Доведи, що ти {стать:готовий:готова} ризикнути життям, щоб зупинити це божевілля. А об'єднані сили Сріблястого Світанку та Багряного Походу допоможуть тобі.\n\nЗайди у Наксрамас та знищ Скару...", [3] = "Командир Еліґор Світанковий з Каплиці Надії Світла, що в Східних Зачумлених землях хоче, щоб ви вбили 5 ходячих чудовиськ, 5 каменешкірих гаргуйлів, 8 капітанів лицарів смерті та 3 отруйних ловців.", [4] = "Обов'язок, честь, відданість... Що ці слова для тебе означають?", [5] = "Чудова робота! Ти отримаєш нагороду за вірну службу мешканцям Каплиці Надії Світла.", ["en"] = "Echoes of War", ["tasks"] = { ["Deathknight Captain"] = "капітан лицарів смерті", ["Deathknight Captain slain"] = "капітан лицарів смерті: убито", ["Living Monstrosity"] = "ходяче чудовисько", ["Living Monstrosity slain"] = "ходяче чудовисько: убито", ["Stoneskin Gargoyle"] = "каменешкірий гаргуйль", ["Stoneskin Gargoyle slain"] = "каменешкірий гаргуйль: убито", ["Venom Stalker"] = "отруйний ловець", ["Venom Stalker slain"] = "отруйний ловець: убито" } },
    [9034] = { [1] = "Нагрудник безстрашності", [2] = "Якщо під час твоїх битв зі Скарою у Наксрамасі ти натрапиш на оскверненні обладунки або на їх обрізки — принеси мені їх, і я зроблю тобі обладунок, гідний великих героїв.", [3] = "Корфакс з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить нагрудник безстрашності, якщо ви принесете йому наступні предмети: осквернену кірасу, 25 понівечених обрізків лат, 4 злитки арканіту та 2 кристали сплетіння.", [4] = "В Наксрамасі утримується древнє зло, {ім'я}.", [5] = "Нехай вони знову пізнають страх, {клас:к}. І нехай ніколи не пізнають твого милосердя.", ["en"] = "Dreadnaught Breastplate", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Breastplate"] = "осквернена кіраса", ["Desecrated Breastplate (Provided)"] = "осквернена кіраса (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9036] = { [1] = "Ножні лати безстрашності", [2] = "Якщо під час твоїх битв зі Скарою у Наксрамасі ти натрапиш на оскверненні обладунки або на їх обрізки — принеси мені їх, і я зроблю тобі обладунок, гідний великих героїв.", [3] = "Корфакс з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить ножні лати безстрашності, якщо ви принесете йому наступні предмети: осквернені ножні лати, 20 понівечених обрізків лат, 4 злитки арканіту та 3 оброблені міцні шкури.", [4] = "Пам'ятай про тих, хто впав перед тобою, {ім'я}.", [5] = "Розчави їх своїми ногами.", ["en"] = "Dreadnaught Legplates", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Legplates"] = "осквернені ножні лати", ["Desecrated Legplates (Provided)"] = "осквернені ножні лати (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9037] = { [1] = "Шолом безстрашності", [2] = "Якщо під час твоїх битв зі Скарою у Наксрамасі ти натрапиш на оскверненні обладунки або на їх обрізки — принеси мені їх, і я зроблю тобі обладунок, гідний великих героїв.", [3] = "Корфакс з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить шолом безстрашності, якщо ви принесете йому наступні предмети: осквернений шолом, 15 понівечених обрізків лат, 5 злитків арканіту та кристал сплетіння.", [4] = "Голова — найчутливіша частина тіла у більшості істот.", [5] = "Пам'ятай, ти ще не зовсім {стать:мертвий:мертва}, якщо у твоїй голові ще є мозок. Завжди тримай цю штуку на голові...", ["en"] = "Dreadnaught Helmet", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Helmet"] = "осквернений шолом", ["Desecrated Helmet (Provided)"] = "осквернений шолом (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9038] = { [1] = "Напліччя безстрашності", [2] = "Якщо під час твоїх битв зі Скарою у Наксрамасі ти натрапиш на оскверненні обладунки або на їх обрізки — принеси мені їх, і я зроблю тобі обладунок, гідний великих героїв.", [3] = "Корфакс з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить напліччя безстрашності, якщо ви принесете йому наступні предмети: осквернене напліччя, 12 понівечених обрізків лат, 2 злитки арканіту та 3 оброблені міцні шкури.", [4] = "Секрет — в кріпленні.", [5] = "Я завжди вважав, що напліччя — це найбільш виразна частина обладунків. Впевнений, ти з цим погодишся.", ["en"] = "Dreadnaught Pauldrons", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Pauldrons"] = "осквернене напліччя", ["Desecrated Pauldrons (Provided)"] = "осквернене напліччя (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9039] = { [1] = "Сабатони безстрашності", [2] = "Якщо під час твоїх битв зі Скарою у Наксрамасі ти натрапиш на оскверненні обладунки або на їх обрізки — принеси мені їх, і я зроблю тобі обладунок, гідний великих героїв.", [3] = "Корфакс з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить сабатони безстрашності, якщо ви принесете йому наступні предмети: осквернені сабатони, 12 понівечених обрізків лат, 2 злитки арканіту та 3 оброблені міцні шкури.", [4] = "Ніколи не варто недооцінювати хорошу пару чоботів. Особливо, коли вони зроблені Корфаксом!", [5] = "Під час останньої війни я бачив, як Моґрейн розбивав цими самими черевиками смердючі черепи живих мерців.", ["en"] = "Dreadnaught Sabatons", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Sabatons"] = "осквернені сабатони", ["Desecrated Sabatons (Provided)"] = "осквернені сабатони (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9040] = { [1] = "Рукавиці безстрашності", [2] = "Якщо під час твоїх битв зі Скарою у Наксрамасі ти натрапиш на оскверненні обладунки або на їх обрізки — принеси мені їх, і я зроблю тобі обладунок, гідний великих героїв.", [3] = "Корфакс з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить рукавиці безстрашності, якщо ви принесете йому наступні предмети: осквернені рукавиці, 8 понівечених обрізків лат, злиток арканіту та 5 оброблених міцних шкур.", [4] = "Ці рукавиці створені для того, щоб тримати в них могутню зброю.", [5] = "Нехай твоя хватка міцно стиснеться навколо шиї Кел'Тузада.\n\n<Корфакс душить руками повітря.>", ["en"] = "Dreadnaught Gauntlets", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Gauntlets"] = "осквернені рукавиці", ["Desecrated Gauntlets (Provided)"] = "осквернені рукавиці (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9041] = { [1] = "Ремінь безстрашності", [2] = "Якщо під час твоїх битв зі Скарою у Наксрамасі ти натрапиш на оскверненні обладунки або на їх обрізки — принеси мені їх, і я зроблю тобі обладунок, гідний великих героїв.", [3] = "Корфакс з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить ремінь безстрашності, якщо ви принесете йому наступні предмети: осквернений ремінь, 8 понівечених обрізків лат, злиток арканіту та 5 оброблених міцних шкур.", [4] = "Пояс — це водночас і модний аксесуар, і потужний елемент захисту.", [5] = "Можеш використовувати його як зашморг для ворогів. А ще вдягати його в гоблінський клюб. Про тебе буде говорити все місто!", ["en"] = "Dreadnaught Waistguard", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Waistguard"] = "осквернений ремінь", ["Desecrated Waistguard (Provided)"] = "осквернений ремінь (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9042] = { [1] = "Браслети безстрашності", [2] = "Якщо під час твоїх битв зі Скарою у Наксрамасі ти натрапиш на оскверненні обладунки або на їх обрізки — принеси мені їх, і я зроблю тобі обладунок, гідний великих героїв.", [3] = "Корфакс з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить браслети безстрашності, якщо ви принесете йому наступні предмети: осквернені поручі, 6 понівечених обрізків лат, злиток арканіту та кристал сплетіння.", [4] = "Зап'ястя — друге найвразливіше місце на тілі... Чи четверте?", [5] = "Пам'ятай, зап'ястя — п'яте найвразливіше місце на тілі! Це захистить твої зап'ястя і можливо навіть лікті.", ["en"] = "Dreadnaught Bracers", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Bracers"] = "осквернені поручі", ["Desecrated Bracers (Provided)"] = "осквернені поручі (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9043] = { [1] = "Мундир спокути", [2] = "Ти знайдеш рештки обладунків наших загиблих героїв на трупах володарів Наксрамаса. Принеси мені ці осквернені реліквії разом з понівеченими обрізками лат та матеріалами, здатними оживити осквернені обладунки. Тоді я зроблю для тебе чудовий обладунок.", [3] = "Командир Еліґор Світанковий з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить мундир спокути, якщо ви принесете йому наступні предмети: осквернений мундир, 25 понівечених обрізків лат, 4 злитки арканіту та 3 оброблені міцні шкури.", [4] = "Я отримую накази згори, {ім'я}.", [5] = "Носи на здоров'я, {клас:к}.", ["en"] = "Redemption Tunic", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Tunic"] = "осквернений мундир", ["Desecrated Tunic (Provided)"] = "осквернений мундир (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9044] = { [1] = "Набедреники спокути", [2] = "Ти знайдеш рештки обладунків наших загиблих героїв на трупах володарів Наксрамаса. Принеси мені ці осквернені реліквії разом з понівеченими обрізками лат та матеріалами, здатними оживити осквернені обладунки. Тоді я зроблю для тебе чудовий обладунок.", [3] = "Командир Еліґор Світанковий з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить набедреники спокути, якщо ви принесете йому наступні предмети: осквернені поножі, 20 понівечених обрізків лат, 4 злитки арканіту та 2 кристали сплетіння.", [4] = "Ти не знайдеш кращих ножних лат для поборника світла.", [5] = "Баланс між ближнім боєм і магією чітко контролюється за допомогою цих ножних лат.", ["en"] = "Redemption Legguards", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Legguards"] = "осквернені поножі", ["Desecrated Legguards (Provided)"] = "осквернені поножі (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9045] = { [1] = "Головний убір спокути", [2] = "Ти знайдеш рештки обладунків наших загиблих героїв на трупах володарів Наксрамаса. Принеси мені ці осквернені реліквії разом з понівеченими обрізками лат та матеріалами, здатними оживити осквернені обладунки. Тоді я зроблю для тебе чудовий обладунок.", [3] = "Командир Еліґор Світанковий з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить головний убір спокути, якщо ви принесете йому наступні предмети: осквернений головний убір, 15 понівечених обрізків лат, 5 злитків арканіту та 2 оброблені міцні шкури.", [4] = "<Еліґор підіймає на вас погляд, а потім повертається до своєї розмови.>", [5] = "<Еліґор вказує на свою голову.>\n\nБережи її, {клас:к}.", ["en"] = "Redemption Headpiece", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Headpiece"] = "осквернений головний убір", ["Desecrated Headpiece (Provided)"] = "осквернений головний убір (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9046] = { [1] = "Напліччя спокути", [2] = "Ти знайдеш рештки обладунків наших загиблих героїв на трупах володарів Наксрамаса. Принеси мені ці осквернені реліквії разом з понівеченими обрізками лат та матеріалами, здатними оживити осквернені обладунки. Тоді я зроблю для тебе чудовий обладунок.", [3] = "Командир Еліґор Світанковий з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить напліччя спокути, якщо ви принесете йому наступні предмети: осквернені наплечі, 12 понівечених обрізків лат, 2 злитки арканіту та 2 кристали сплетіння.", [4] = "Хіба ти не бачиш, що я зайнятий, {ім'я}?", [5] = "Будь-які паладини скажуть тобі, що основний тягар їхньої сили припадає на плечі. Чим більше, тим краще...", ["en"] = "Redemption Spaulders", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Spaulders"] = "осквернені наплечі", ["Desecrated Spaulders (Provided)"] = "осквернені наплечі (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9047] = { [1] = "Чоботи спокути", [2] = "Ти знайдеш рештки обладунків наших загиблих героїв на трупах володарів Наксрамаса. Принеси мені ці осквернені реліквії разом з понівеченими обрізками лат та матеріалами, здатними оживити осквернені обладунки. Тоді я зроблю для тебе чудовий обладунок.", [3] = "Командир Еліґор Світанковий з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить чоботи спокути, якщо ви принесете йому наступні предмети: осквернені чоботи, 12 понівечених обрізків лат, 2 злитки арканіту та 3 оброблені міцні шкури.", [4] = "Ти маєш принести мені все, що я просив, щоб я міг почати роботу.", [5] = "Ці чоботи захистять твої ноги від карликових посіпак Скари.", ["en"] = "Redemption Boots", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Boots"] = "осквернені чоботи", ["Desecrated Boots (Provided)"] = "осквернені чоботи (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9048] = { [1] = "Бойові рукавиці спокути", [2] = "Ти знайдеш рештки обладунків наших загиблих героїв на трупах володарів Наксрамаса. Принеси мені ці осквернені реліквії разом з понівеченими обрізками лат та матеріалами, здатними оживити осквернені обладунки. Тоді я зроблю для тебе чудовий обладунок.", [3] = "Командир Еліґор Світанковий з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить бойові рукавиці спокути, якщо ви принесете йому наступні предмети: осквернені бойові рукавиці, 8 понівечених обрізків лат, злиток арканіту та 5 оброблених міцних шкур.", [4] = "Ти маєш принести мені все, що я просив, щоб я міг почати роботу.", [5] = "Направляй Світло крізь ці рукавиці та знищуй своїх ворогів!", ["en"] = "Redemption Handguards", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Handguards"] = "осквернені бойові рукавиці", ["Desecrated Handguards (Provided)"] = "осквернені бойові рукавиці (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9049] = { [1] = "Ремінь спокути", [2] = "Ти знайдеш рештки обладунків наших загиблих героїв на трупах володарів Наксрамаса. Принеси мені ці осквернені реліквії разом з понівеченими обрізками лат та матеріалами, здатними оживити осквернені обладунки. Тоді я зроблю для тебе чудовий обладунок.", [3] = "Командир Еліґор Світанковий з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить ремінь спокути, якщо ви принесете йому наступні предмети: осквернений пасок, 8 понівечених обрізків лат, злиток арканіту та 3 кристали сплетіння.", [4] = "Ти маєш принести мені все, що я просив, щоб я міг почати роботу.", [5] = "Цей пояс виконуватиме дві функції: 1) Він захистить тебе від Скари, і 2) Ти виглядатимеш на кілька кілограмів легше.", ["en"] = "Redemption Girdle", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Girdle"] = "осквернений пасок", ["Desecrated Girdle (Provided)"] = "осквернений пасок (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [9050] = { [1] = "Поручі спокути", [2] = "Ти знайдеш рештки обладунків наших загиблих героїв на трупах володарів Наксрамаса. Принеси мені ці осквернені реліквії разом з понівеченими обрізками лат та матеріалами, здатними оживити осквернені обладунки. Тоді я зроблю для тебе чудовий обладунок.", [3] = "Командир Еліґор Світанковий з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить поручі спокути, якщо ви принесете йому наступні предмети: осквернені наручі, 6 понівечених обрізків лат, злиток арканіту та 2 оброблені міцні шкури.", [4] = "Ти маєш принести мені все, що я просив, щоб я міг почати роботу.", [5] = "Вони надзвичайно вигідні у виготовленні, але май на увазі, що вони можуть покритися іржею, якщо будеш в них надто багато плавати.", ["en"] = "Redemption Wristguards", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Wristguards"] = "осквернені наручі", ["Desecrated Wristguards (Provided)"] = "осквернені наручі (видано)", ["Wartorn Plate Scrap"] = "понівечений обрізок лат", ["Wartorn Plate Scrap (Provided)"] = "понівечений обрізок лат (видано)" } },
    [90506] = { [1] = "Захоплює подих", [2] = "Я працюю з Еві Вірлбрю, щоб забезпечити важливі припаси, але вона веде жорстку угоду і відмовляється поступатися. Вона наполягає, що обміняє на них лише Нівіфацієнтні залози від синіх драконів. Ця залоза дозволяє синім драконам використовувати своє крижане дихання, і вона має різноманітні особливі алхімічні властивості.\n\nУ Мазторілі на півдні є популяція дуже ворожих синіх драконів, і мені дуже потрібна допомога в отриманні деяких із цих залоз, щоб задовольнити цього негідника.", [3] = "Отримайте 10 залоз Нівіфаціента від синього драконячого породження в Мазторілі, що на південь від Еверлука.", [4] = "Я б збрехав, якби сказав, що мені цілком комфортно витягувати органи з живих, дихаючих істот, навіть якщо вони дуже й дуже ворожі. Однак, у будь-якому разі, нам потрібні ці матеріали, і друїд повинен робити; те, що друїд повинен робити.", [5] = "Гадаю, що чим менше кривавих подробиць я знатиму про те, як їх видобували, тим краще для мене буде. Блюз не зовсім прощає.\n\nУ будь-якому разі, я дуже ціную це! Я впевнений, що зараз зможу отримати ці припаси від Еві. Хіба що, звісно, вона знову вирішить змінити угоду зі мною!", ["en"] = "Take Their Breath Away" },
    [90507] = { [1] = "Логістичні виклики", [2] = "У мене давня домовленість з Аззлбі про перевезення припасів через гірські перевали на його в'ючних тваринах. Останнім часом його каравани почали нападати на Зимові осінні фурболги, і вони вкрали наші речі!\n\nОбшукайте табори Зимоключа тут, у Зимоключа, у пошуках наших зниклих припасів.", [3] = "Зберіть 15 ящиків із припасами Місячної Галявини у таборах та селах Фурболгів Зимоключа у Зимоключі.", [4] = "Підозрюю, що фурболги Зимоключа вважають, що це гарна розвага — запастися вогняною водою та розграбувати наші фургони заради розваги.\n\nНа мою думку, це просто грубо.", [5] = "Щиро дякую {ім'я}. Це величезне полегшення знову отримати ці матеріали!", ["en"] = "Logistics Challenges" },
    [90508] = { [1] = "Як ворона летить", [2] = "Мені справді варто поговорити з майстром Омнуроном з цього приводу. Однак, ви так допомогли Друїдам Кігтя, що я ризикну. Я впевнений, що він зрозуміє.\n\nКраще благати прощення, ніж просити дозволу!\n\nМи підемо зараз. Ви не бачите маршруту, яким ми йдемо, щоб обійти обереги, тому мені доведеться затулити вам зір. Це вже й так безвідповідально, і я точно не можу розкрити таємниці Друїдів Кігтя.", [3] = "Безпечний транспорт до вершини гори Хіджал.", [5] = "Ну, ось ми й тут.\n\nПопереджаю вас, не залишайте безпосередню територію вершини. Це не буде для вас добре. Друїди, які охороняють Нордрассіл, не завжди, на мою думку, дружелюбні. Тут також ціла гора, повна інших жахів, які б із задоволенням поласували таким соковитим {клас}, як ви.\n\nРаджу вам якомога швидше закінчити тут і знову поговорити зі мною, коли будете готові повернутися до Еверлука.\n\nУдачі!", ["en"] = "As The Crow Flies" },
    [9051] = { [1] = "Випробування отрути", [2] = "Отрута, яку я створив з твоєю допомогою, потрібна для важливої мети. Гігантські дияволозаври, що мешкають в кратері, заважають мені полювати та загрожують моєму життю. Навіть якби мені вистачило сил вбити одного з них, це б лише звільнило територію для іншого.\n\nВізьми цю дияволозаврову колючку, змащену отрутою і встроми в дияволозавра. Ця отрута має втихомирити звіра... Хоча, я не знаю, як швидко...", [3] = "Вколіть дияволозавра дияволозавровою колючкою, після чого поверніться до Торви Слідопита в кратер Ун'Ґоро.", [4] = "Тобі вдалось втихомирити звіра?", [5] = "Дякую, {ім'я:к}. Ти маєш вдосталь сміливості й мудрості.\n\nНу, розказуй, як дияволозавр відреагував на отруту?", ["en"] = "Toxic Test", ["tasks"] = { ["Devilsaur stabbed with barb"] = "Дияволзавра вдарили колючою головкою" } },
    [90510] = { [1] = "Новий Авалон", [2] = "Як ви бачили, Новий Авалон може похвалитися значною військовою присутністю, але він також пропонує безпеку та захист цивільному населенню.\n\nЯкщо ви зможете створити більш постійну маскування, подумайте про те, щоб запропонувати руку допомоги. Підлещування до місцевих жителів може бути корисним для наших зусиль щодо повернення анклаву, не кажучи вже про те, щоб дати вам змогу «привласнити» частину матеріалів та ресурсів там, збагативши себе та позбавивши їхню військову машину життєво важливих поставок.", [3] = "Використайте Червоний знак розрізнення, як тільки ви отримаєте достатньо частин маскування, щоб обдурити Червоних хрестоносців у Новому Авалоні, та знову поговоріть з інквізитором Джосіфіною. Гравці з професіями виготовлення обладунків можуть використовувати рецепти та креслення частин червоного обладунків, отриманих від ворожих хрестоносців у Руці Тіра та Новому Авалоні.\n\nНаданий предмет:", [4] = "Якщо у вас виникають проблеми з придбанням потрібних виробів шляхом їх самостійного виготовлення, можливо, ви можете звернутися до інших людей, які мають відповідні навички та доступ до відповідних дизайнів та візерунків.", [5] = "Досить переконливо, мабуть.\n\nНовий Авалон втратив деяких своїх майстрів-ремісників під час каравану, що прямував до Хартглена кілька років тому, але я бачу, що деякі з їхніх проектів не були втрачені.\n\nЯкщо ви ще не дуже відточили власні ремісничі навички, вам може бути важче просунутися в Новому Авалоні. Однак, незалежно від того, чи знаєте ви, як поводитися з молотком чи голкою, я підозрюю, що ви можете хоча б відвідати квартирмейстера в казармах. Ви також можете поритися в їхній коморі.", ["en"] = "New Avalon", ["tasks"] = { ["Item #237020"] = "Артикул №237020" } },
    [90518] = { [1] = "Яблуко на день тримає нежить на відстані", [2] = "Радий знову тебе бачити. У мене не було проблем із тим, щоб тримати кухню заповненою, відколи тебе не було, але сьогодні вранці я помітила, що мені якраз достатньо соромно спекти яблук, щоб спекти пиріг. Я подумала, що час зробити собі невеликий ласощ.\n\nЯкщо у тебе є кілька хвилин, чи не міг би ти заскочити до саду та взяти трохи? На жаль, я ще не спекла пиріг Джонні, але я не можу спекти пиріг без яблук, і я не витрачу яблука на пиріг Джонні!\n\nЗвісно, я поділюся з тобою шматочком.", [3] = "Знайдіть яблуневий сад у південній частині Нового Авалона, щоб принести яблук. Після досягнення успіху поверніться до Керрі Хартфайр у корчмі Нового Авалона. Якщо яблука вам здаються занадто дорогими, подумайте про альтернативний спосіб їх придбання.", [4] = "Пам’ятайте, що Джонні може захотіти стягувати додаткову плату за свої найкращі яблука, але я впевнений, що ви можете знайти креативне рішення, якщо не хочете наповнювати його кишені.", [5] = "Чудово, я негайно почну! Ці яблука виглядають навіть краще, ніж попередня партія, яку ви доставили, це майже як намагання стати на мою користь...\n\n<Коли Керрі починає облаштовувати своє місце для приготування пирога, вона робить перебільшений жест, який явно демонструє її обручку.>\n\nДякую, що завітали та покращили нашу вечерю. Ми з Маркусом сподіваємося побачити вас знову незабаром!", ["en"] = "An Apple a Day Keeps the Undead at Bay" },
    [90519] = { [1] = "Риба на замовлення", [2] = "Я ненавиджу рибу. Терпіти не можу її запах. Вона неймовірно моторошна. Справді найгірша.\n\nОскільки це моя кухня, я можу скористатися і використовую свою владу, щоб сказати НІ імпорту риби, але іноді наші солдати вбивають собі в голову, що їм потрібне рибальське свято.\n\nЗдається, сьогодні ввечері одна з таких ночей. Мені потрібна риба, і то подвійно!", [3] = "Дослідіть човен, що пришвартувався на південь від Нового Авалона для перевезення риби, і поверніть улов Керрі.", [4] = "Будь ласка, не доставляйте неповне замовлення. Я хочу негайно все розібратися.\n\nЯкщо ви не можете знайти достатньо риби на вечір, можливо, ви можете знову піти пошукати залишки. Чесно кажучи, я думаю, що це було б краще.", [5] = "Ах, я сподівався, що в тебе сьогодні ввечері будуть цікавіші справи, але, гадаю, ти вдав із себе цілком надійного, відколи ми познайомилися.\n\nНу, мені краще починати.", ["en"] = "Fish On Demand" },
    [9052] = { [1] = "Отрута з паростків кровоцвіту", [2] = "Мені потрібна твоя поміч у створенні отрути, за допомогою якої я збираюсь втихомирювати величезних звірів, які населяють кратер. Не бійся, отрута не смертельна. Крім того, кмітливі очі {клас:р} будуть сильною перевагою при зборі складників.\n\nТи знайдеш гриби-кровошляпи під паростками кровоцвіту, що ростуть по всьому кратеру. Жала Ґоріші - це жала комах, які водяться в районі Слизького шраму, розташованому в південній частині кратера.", [3] = "Зберіть 8 кровошляпів і 8 жал Ґоріші, після чого поверніться до Торви Слідопита в кратер Ун'Ґоро.", [4] = "Як успіхи?", [5] = "Нарешті!\n\nЯ тепер змішаю ці інгредієнти з ґрунтом Ун'Горо і приготую отруту...", ["en"] = "Bloodpetal Poison", ["tasks"] = { ["Bloodcap"] = "кровошляп", ["Bloodcap (Provided)"] = "кровошляп (видано)", ["Gorishi Sting"] = "жало Ґоріші", ["Gorishi Sting (Provided)"] = "жало Ґоріші (видано)" } },
    [90520] = { [1] = "Безпека харчових продуктів", [2] = "Здається, я пам'ятаю, що одним із інгредієнтів, за яким я тебе послав, коли ми вперше зустрілися, було м'ясо. Також я пам'ятаю багато скарг того вечора на те, що їхня їжа знудила? Це було дуже дивно.\n\nУ будь-якому разі, у коморі знову закінчується м'ясо, і було б добре знати, що в мене є хтось надійний, хто допоможе його поповнити. Останнє, що мені потрібно, це очікувати доставку, а потім дізнатися про це лише через тиждень після смерті кур'єра!", [3] = "Здобувайте м'ясо, безпечне для споживання людиною. Якщо вам важко знайти його в Новому Авалоні, ви можете (зрештою) зібрати достатньо, вбиваючи звірів у Східних Чумних Землях.", [4] = "З такими темпами вечеря трохи затримається.", [5] = "Твоя відданість послідовності неймовірна, друже. Ці порції майстерно нарізані та мають той самий колір і текстуру, що й твоя попередня партія. Якщо я колись опинюся в ситуації, коли мені потрібно буде самостійно шукати їжу, сподіваюся, ти будеш поруч.\n\nІ, звісно, Маркус.\n\nЯ заберу це від тебе і почну. У Нью-Авалоні сьогодні ввечері буде смачно!", ["en"] = "Food Safety" },
    [9053] = { [1] = "Кращий інгредієнт", [2] = "Як я і боявся — ця отрута занадто слабка для такого сильного створіння.\n\nЩоб створити сильнішу отруту, мені знадобляться потужніші інгредієнти. Відправляйся на дно храму Атал'Гаккар, розкрий таємниці вівтаря та отримай гнилу лозу від тамтешнього вартового. Храм небезпечний, краще візьми з собою друзів.\n\nПовертайся до мене, коли закінчиш завдання.", [3] = "Отримайте гнилу лозу від вартового на дні Затонулого храму і поверніться до Торви Слідопита.", [4] = "Ти {стать:роздобув:роздобула} лозу?", [5] = "Нарешті я можу приготувати достатньо сильну отруту. Я не смію вимагати, щоб ти {стать:застосував:застосувала} його проти цих звірів знову, адже я і без того вже забагато в тебе просив.\n\nПрийми мою дяку і повагу. Нехай щастить у твоїх подорожах, {ім'я:к}.", ["en"] = "A Better Ingredient", ["tasks"] = { ["Putrid Vine"] = "гнила лоза", ["Putrid Vine (Provided)"] = "гнила лоза (видано)" } },
    [9054] = { [1] = "Мундир склепного ловця", [2] = "Я знайшов застосування панцирам склепних марників. Я можу виготовити надзвичайно легкий, але дуже смертоносний обладунок, поєднавши фрагменти разом з оскверненими магічними обладунками, втраченими в Наксрамасі.\n\nПринеси мені всі потрібні предмети, і я створю для тебе обладунки, подібних яким ще не бачив світ!", [3] = "Мисливець Леопольд з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить мундир склепного ловця, якщо ви принесете йому наступні предмети: осквернений мундир, 25 понівечених обрізків кольчуги, 4 злитки арканіту та 3 оброблені міцні шкури.", [4] = "Ти {стать:приніс:принесла} предмети, які я просив, {клас:к}?", [5] = "Вони боятимуться тебе, {ім'я}.", ["en"] = "Cryptstalker Tunic", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Tunic"] = "осквернений мундир", ["Desecrated Tunic (Provided)"] = "осквернений мундир (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9055] = { [1] = "Набедреник склепного ловця", [2] = "Я знайшов застосування панцирам склепних марників. Я можу виготовити надзвичайно легкий, але дуже смертоносний обладунок, поєднавши фрагменти разом з оскверненими магічними обладунками, втраченими в Наксрамасі.\n\nПринеси мені всі потрібні предмети, і я створю для тебе обладунки, подібних яким ще не бачив світ!", [3] = "Мисливець Леопольд з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить набедреник склепного ловця, якщо ви принесете йому наступні предмети: осквернені поножі, 20 понівечених обрізків кольчуги, 3 злитки арканіту та 5 оброблених міцних шкур.", [4] = "Ти {стать:приніс:принесла} предмети, які я просив, {клас:к}?", [5] = "Чим більше частин цих обладунків ти одягаєш, тим більше змінюється твоя особистість. Ти отримаєш надприродні здібності до вбивства. Можливо, у тебе навіть з'явиться жага крові.\n\nСкажімо так, я не несу відповідальності за весь той хаос, який ти можеш утнути...", ["en"] = "Cryptstalker Legguards", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Legguards"] = "осквернені поножі", ["Desecrated Legguards (Provided)"] = "осквернені поножі (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [90559] = { [1] = "Загартування", [2] = "<Гілки Нордрассілу створюють вогонь, якого ви ще не бачили. Здається, що він має власну волю та інтелект. Ви не можете бути впевнені, але можете поклястися, що полум'я, здається, певною мірою усвідомлює вашу присутність і дивиться на вас з певною цікавістю.>\n\n<Як би це не було тривожно, залишається лише нагріти лезо та занурити його у води Криниці Вічності.>", [4] = "Готово. Лезо відновлено, хоча на ньому все ще є сліди тління.", [5] = "Ти так багато зробив, але я мушу попросити тебе донести меч до одного кінцевого пункту призначення.\n\nОдного разу там, нам залишається лише сподіватися, що душа Александроса Могрейна матиме сміливість зробити останній крок.", ["en"] = "The Tempering", ["tasks"] = { ["Item #241654"] = "Товар №241654" } },
    [9056] = { [1] = "Головний убір склепного ловця", [2] = "Я знайшов застосування панцирам склепних марників. Я можу виготовити надзвичайно легкий, але дуже смертоносний обладунок, поєднавши фрагменти разом з оскверненими магічними обладунками, втраченими в Наксрамасі.\n\nПринеси мені всі потрібні предмети, і я створю для тебе обладунки, подібних яким ще не бачив світ!", [3] = "Мисливець Леопольд з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить головний убір склепного ловця, якщо ви принесете йому наступні предмети: осквернений головний убір, 15 понівечених обрізків кольчуги, 4 злитки арканіту та 2 кристали сплетіння.", [4] = "Ти {стать:приніс:принесла} предмети, які я просив, {клас:к}?", [5] = "Ти перетворюєшся на страшне створіння, {ім'я}.", ["en"] = "Cryptstalker Headpiece", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Headpiece"] = "осквернений головний убір", ["Desecrated Headpiece (Provided)"] = "осквернений головний убір (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9057] = { [1] = "Наплечі склепного ловця", [2] = "Я знайшов застосування панцирам склепних марників. Я можу виготовити надзвичайно легкий, але дуже смертоносний обладунок, поєднавши фрагменти разом з оскверненими магічними обладунками, втраченими в Наксрамасі.\n\nПринеси мені всі потрібні предмети, і я створю для тебе обладунки, подібних яким ще не бачив світ!", [3] = "Мисливець Леопольд з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить наплечі склепного ловця, якщо ви принесете йому наступні предмети: осквернені наплечі, 12 понівечених обрізків кольчуги, 2 злитки арканіту та 3 оброблені міцні шкури.", [4] = "Ти {стать:приніс:принесла} предмети, які я просив, {клас:к}?", [5] = "Я особливо подбав про те, щоб зробити ці наплечі якомога більшими та виразнішими. Повір мені на слово, вони тобі сподобаються...", ["en"] = "Cryptstalker Spaulders", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Spaulders"] = "осквернені наплечі", ["Desecrated Spaulders (Provided)"] = "осквернені наплечі (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9058] = { [1] = "Чоботи склепного ловця", [2] = "Я знайшов застосування панцирам склепних марників. Я можу виготовити надзвичайно легкий, але дуже смертоносний обладунок, поєднавши фрагменти разом з оскверненими магічними обладунками, втраченими в Наксрамасі.\n\nПринеси мені всі потрібні предмети, і я створю для тебе обладунки, подібних яким ще не бачив світ!", [3] = "Мисливець Леопольд з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить чоботи склепного ловця, якщо ви принесете йому наступні предмети: осквернені чоботи, 12 понівечених обрізків кольчуги, злиток арканіту та 3 кристали сплетіння.", [4] = "Ти {стать:приніс:принесла} предмети, які я просив, {клас:к}?", [5] = "Чоботи готові, {ім'я}! Носи їх із задоволенням.", ["en"] = "Cryptstalker Boots", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Boots"] = "осквернені чоботи", ["Desecrated Boots (Provided)"] = "осквернені чоботи (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9059] = { [1] = "Бойові рукавиці склепного ловця", [2] = "Я знайшов застосування панцирам склепних марників. Я можу виготовити надзвичайно легкий, але дуже смертоносний обладунок, поєднавши фрагменти разом з оскверненими магічними обладунками, втраченими в Наксрамасі.\n\nПринеси мені всі потрібні предмети, і я створю для тебе обладунки, подібних яким ще не бачив світ!", [3] = "Мисливець Леопольд з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить бойові рукавиці склепного ловця, якщо ви принесете йому наступні предмети: осквернені бойові рукавиці, 8 понівечених обрізків кольчуги, злиток арканіту та 5 оброблених міцних шкур.", [4] = "Ти {стать:приніс:принесла} предмети, які я просив, {клас:к}?", [5] = "Нехай лють склепного марника направляє твою руку, {ім'я}.", ["en"] = "Cryptstalker Handguards", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Handguards"] = "осквернені бойові рукавиці", ["Desecrated Handguards (Provided)"] = "осквернені бойові рукавиці (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9060] = { [1] = "Пасок склепного ловця", [2] = "Я знайшов застосування панцирам склепних марників. Я можу виготовити надзвичайно легкий, але дуже смертоносний обладунок, поєднавши фрагменти разом з оскверненими магічними обладунками, втраченими в Наксрамасі.\n\nПринеси мені всі потрібні предмети, і я створю для тебе обладунки, подібних яким ще не бачив світ!", [3] = "Мисливець Леопольд з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить пасок склепного ловця, якщо ви принесете йому наступні предмети: осквернений пасок, 8 понівечених обрізків кольчуги, злиток арканіту та 3 кристали сплетіння.", [4] = "Ти {стать:приніс:принесла} предмети, які я просив, {клас:к}?", [5] = "Пасок, гідний королів! Він готовий, {ім'я}.", ["en"] = "Cryptstalker Girdle", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Girdle"] = "осквернений пасок", ["Desecrated Girdle (Provided)"] = "осквернений пасок (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9061] = { [1] = "Наручі склепного ловця", [2] = "Я знайшов застосування панцирам склепних марників. Я можу виготовити надзвичайно легкий, але дуже смертоносний обладунок, поєднавши фрагменти разом з оскверненими магічними обладунками, втраченими в Наксрамасі.\n\nПринеси мені всі потрібні предмети, і я створю для тебе обладунки, подібних яким ще не бачив світ!", [3] = "Мисливець Леопольд з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить наручі склепного ловця, якщо ви принесете йому наступні предмети: осквернені наручі, 6 понівечених обрізків кольчуги, злиток арканіту та 2 оброблені міцні шкури.", [4] = "Ти {стать:приніс:принесла} предмети, які я просив, {клас:к}?", [5] = "Наручі готові. Насолоджуйся!", ["en"] = "Cryptstalker Wristguards", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Wristguards"] = "осквернені наручі", ["Desecrated Wristguards (Provided)"] = "осквернені наручі (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [90625] = { [1] = "На жахливих крилах", [2] = "Роздерте крило Жахливого Володаря Балназара — це все, що залишилося від поваленого Натрезіма.\n\nХтось у Світлій Надії може бути зацікавлений у цьому.", [3] = "Відвідайте Крило Бальназара до каплиці Надії Світла у Східних Чумних землях.", [4] = "Що привело тебе до Грок'ло?", [5] = "Так само любитель трофеїв!? Грок'ло сам має велику колекцію.\n\nНіщо так не об'єднує лігво Грок'ло, як череп його ворога.\n\n<Грок'ло сміється>\n\nЩо у тебе є? Гігантське крило кажана? Мок'ло вже бачив. Вже не вражає. Краще як лук або проданий за монети, ніж як трофей.\n\nЯкщо хочеш, принеси Грок'ло тятиву, і Грок'ло домовиться про зустріч зі своїм особливим майстром.", ["en"] = "On Dreaded Wings", ["tasks"] = { ["Item #242365"] = "Товар №242365" } },
    [90626] = { [1] = "Сухожилля Світла", [2] = "Грок'ло домовиться про зустріч зі спеціальним майстром, як тільки ви знайдете підходящу мотузку, яка пасуватиме до цього гігантського крила кажана.\n\nГрок'ло рекомендує знайти найкращу мотузку.\n\n<Грок'ло посміхається під шоломом>\n\nДраконяче сухожилля – безумовно найкраща мотузка.", [3] = "Переможіть Солістразу та отримайте Зріле Сухожилля Світлого Дракона, а потім принесіть його Грок'ло до Каплиці Надії Світла у Східних Чумних Землях.\n\nНаданий предмет:", [4] = "Ви знайшли мотузку, яка пасуватиме до вашого крила кажана?", [5] = "Ось це ж мотузка! Грок'ло любить яскраві речі!\n\n<Грок'ло киває>\n\nАх, Грок'ло, безсумнівно, думає, що за це ти отримаєш багато золота, коли зробиш з цього лук.", ["en"] = "Sinew of Light" },
    [90627] = { [1] = "Хитрий майстер", [2] = "Гаразд, ім'я мого майстра — Мізл Хитрий.\n\nЦе так очевидно, що навіть Грок'ло це бачить! Усі думають, що його звуть, бо він розумний. НІ! Він Огр, він не розумний! Це тому, що він добре справляється з майстерністю!\n\n<Грок'ло киває>\n\nІдіть до Північного Запеклого Молу та зустріньтеся з ним. Переконайтеся, що він нічим іншим не відволікається, коли ви зустрінетеся.\n\nІдіть один.", [3] = "Зустріньтеся з Мізлом Хитрим у Північному Дайр-Молі.\n\nВи захочете спіймати його без відволікаючих факторів, тому не вбивайте жодного з важливих огрів по дорозі до нього, інакше йому доведеться витратити час на їх заміну, і він не зможе вам допомогти.\n\nІдіть самі.", [4] = "Вас послав пан Мок'ло? Якщо ви великий бос, то він другий великий бос, І найкращий клієнт.\n\nСкриня з данинами завжди наповнена здобиччю та золотом від крафту для Грок'ло. Ми не питаємо, звідки він все це бере, але тепер це належить Гордоку!\n\nО, і тепер, коли ви новий король, а мені нема чого лагодити, я можу допомогти вам зібрати все, що вам потрібно!", [5] = "О НІ! Мізл з'єднала крило кажана та цю гарну нитку разом!\n\nСильно його розтрощила, але йому потрібно щось інше, чого я не можу зробити.\n\nДух Огра сказав мені, що це світло та темрява цих двох речей. Вони не ладнають. Дух Огра каже, що йому потрібна крапля Долі, якої не можна уникнути. Але я не знаю, що це таке.", ["en"] = "Crafty the Crafter", ["tasks"] = { ["Item #242364"] = "Товар №242364" } },
    [9063] = { [1] = "Торва Слідопит", [2] = "Мисливець на ім'я Торва Слідопит попросив допомоги друїдів. Він сказав, що лише ми маємо необхідні навички та належну повагу до природи, щоб допомогти йому.\n\nДо кратера Ун'Ґоро веде дорога з пустелі Танаріс. Торва стоїть біля входу до кратера.", [3] = "Поговоріть з Торвою Слідопитом в кратері Ун'Ґоро.", [5] = "Ти {стать:подолав:подолала} довгий шлях, {клас:к}. І ти дуже вчасно.", ["en"] = "Torwa Pathfinder" },
    [9065] = { [1] = "Квест «Чоу» (123)aa", [2] = "$Tpunk;! Убийте Кобольдів-Шкодників, 2 з них.", ["en"] = "The \"Chow\" Quest (123)aa" },
    [9068] = { [1] = "Мундир Землетрощителя", [2] = "Прошу тебе, зроби мені честь і поверни обладунки тих, хто поліг, захищаючи ці землі.\n\nЦі обладунки були осквернені та, безсумнівно, використовуються у злих цілях, але за допомогою обрізків та деяких інших матеріалів їх можна відновити та знову вдягнути на битву.\n\nПринеси мені обладунки полеглих разом з матеріалами для їх очищення, і обладунки Землетрощителя будуть твоїми.\n\nШукай їх в Наксрамасі.", [3] = "Рімблат Землетрощитель з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить мундир Землетрощителя, якщо ви принесете йому наступні предмети: осквернений мундир, 25 понівечених обрізків кольчуги, 4 злитки арканіту та 3 оброблені міцні шкури.", [4] = "<Рімблат фиркає на вас.>", [5] = "Без сумніву, найпотужніший і найстрашніший елемент обладунку Землетрощителя. Мої предки усміхаються тобі, {ім'я}.", ["en"] = "Earthshatter Tunic", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Tunic"] = "осквернений мундир", ["Desecrated Tunic (Provided)"] = "осквернений мундир (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9069] = { [1] = "Набедреники Землетрощителя", [2] = "Прошу тебе, зроби мені честь і поверни обладунки тих, хто поліг, захищаючи ці землі.\n\nЦі обладунки були осквернені та, безсумнівно, використовуються у злих цілях, але за допомогою обрізків та деяких інших матеріалів їх можна відновити та знову вдягнути на битву.\n\nПринеси мені обладунки полеглих разом з матеріалами для їх очищення, і обладунки Землетрощителя будуть твоїми.\n\nШукай їх в Наксрамасі.", [3] = "Рімблат Землетрощитель з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить набедреники Землетрощителя, якщо ви принесете йому наступні предмети: осквернені поножі, 20 понівечених обрізків кольчуги, 3 злитки арканіту та 5 оброблених міцних шкур.", [4] = "Якщо вже на те пішло, то землю треба рятувати.", [5] = "Сподіваюся, що тебе не спіткає доля тих, хто приходив до тебе, {ім'я}.", ["en"] = "Earthshatter Legguards", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Legguards"] = "осквернені поножі", ["Desecrated Legguards (Provided)"] = "осквернені поножі (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9070] = { [1] = "Головний убір Землетрощителя", [2] = "Прошу тебе, зроби мені честь і поверни обладунки тих, хто поліг, захищаючи ці землі.\n\nЦі обладунки були осквернені та, безсумнівно, використовуються у злих цілях, але за допомогою обрізків та деяких інших матеріалів їх можна відновити та знову вдягнути на битву.\n\nПринеси мені обладунки полеглих разом з матеріалами для їх очищення, і обладунки Землетрощителя будуть твоїми.\n\nШукай їх в Наксрамасі.", [3] = "Рімблат Землетрощитель з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить головний убір Землетрощителя, якщо ви принесете йому наступні предмети: осквернений головний убір, 15 понівечених обрізків кольчуги, 4 злитки арканіту та 2 кристали сплетіння.", [4] = "Ти {стать:приніс:принесла} мені все необхідне?", [5] = "Представляю тобі головний елемент обладунків Землетрощителя: шолом Землетрощителя...", ["en"] = "Earthshatter Headpiece", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Headpiece"] = "осквернений головний убір", ["Desecrated Headpiece (Provided)"] = "осквернений головний убір (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9071] = { [1] = "Наплечі Землетрощителя", [2] = "Прошу тебе, зроби мені честь і поверни обладунки тих, хто поліг, захищаючи ці землі.\n\nЦі обладунки були осквернені та, безсумнівно, використовуються у злих цілях, але за допомогою обрізків та деяких інших матеріалів їх можна відновити та знову вдягнути на битву.\n\nПринеси мені обладунки полеглих разом з матеріалами для їх очищення, і обладунки Землетрощителя будуть твоїми.\n\nШукай їх в Наксрамасі.", [3] = "Рімблат Землетрощитель з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить наплечі Землетрощителя, якщо ви принесете йому наступні предмети: осквернені наплечі, 12 понівечених обрізків кольчуги, 2 злитки арканіту та 2 місячні полотна.", [4] = "Ти {стать:приніс:принесла} мені все необхідне?", [5] = "Наплечі допомагають тримати рівновагу.", ["en"] = "Earthshatter Spaulders", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Spaulders"] = "осквернені наплечі", ["Desecrated Spaulders (Provided)"] = "осквернені наплечі (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9072] = { [1] = "Чоботи Землетрощителя", [2] = "Прошу тебе, зроби мені честь і поверни обладунки тих, хто поліг, захищаючи ці землі.\n\nЦі обладунки були осквернені та, безсумнівно, використовуються у злих цілях, але за допомогою обрізків та деяких інших матеріалів їх можна відновити та знову вдягнути на битву.\n\nПринеси мені обладунки полеглих разом з матеріалами для їх очищення, і обладунки Землетрощителя будуть твоїми.\n\nШукай їх в Наксрамасі.", [3] = "Рімблат Землетрощитель з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить чоботи Землетрощителя, якщо ви принесете йому наступні предмети: осквернені чоботи, 12 понівечених обрізків кольчуги, злиток арканіту та 3 кристали сплетіння.", [4] = "Ти {стать:приніс:принесла} мені все необхідне?", [5] = "Ці чоботи наповнені силою моїх предків! Ступай з розумом...", ["en"] = "Earthshatter Boots", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Boots"] = "осквернені чоботи", ["Desecrated Boots (Provided)"] = "осквернені чоботи (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9073] = { [1] = "Бойові рукавиці Землетрощителя", [2] = "Прошу тебе, зроби мені честь і поверни обладунки тих, хто поліг, захищаючи ці землі.\n\nЦі обладунки були осквернені та, безсумнівно, використовуються у злих цілях, але за допомогою обрізків та деяких інших матеріалів їх можна відновити та знову вдягнути на битву.\n\nПринеси мені обладунки полеглих разом з матеріалами для їх очищення, і обладунки Землетрощителя будуть твоїми.\n\nШукай їх в Наксрамасі.", [3] = "Рімблат Землетрощитель з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить бойові рукавиці Землетрощителя, якщо ви принесете йому наступні предмети: осквернені бойові рукавиці, 8 понівечених обрізків кольчуги, злиток арканіту та 5 оброблених міцних шкур.", [4] = "Ти {стать:приніс:принесла} мені все необхідне?", [5] = "Ці рукавиці направлятимуть силу стихій!", ["en"] = "Earthshatter Handguards", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Handguards"] = "осквернені бойові рукавиці", ["Desecrated Handguards (Provided)"] = "осквернені бойові рукавиці (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9074] = { [1] = "Пасок Землетрощителя", [2] = "Прошу тебе, зроби мені честь і поверни обладунки тих, хто поліг, захищаючи ці землі.\n\nЦі обладунки були осквернені та, безсумнівно, використовуються у злих цілях, але за допомогою обрізків та деяких інших матеріалів їх можна відновити та знову вдягнути на битву.\n\nПринеси мені обладунки полеглих разом з матеріалами для їх очищення, і обладунки Землетрощителя будуть твоїми.\n\nШукай їх в Наксрамасі.", [3] = "Рімблат Землетрощитель з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить пасок Землетрощителя, якщо ви принесете йому наступні предмети: осквернений пасок, 8 понівечених обрізків кольчуги, злиток арканіту та 3 кристали сплетіння.", [4] = "Ти {стать:приніс:принесла} мені все необхідне?", [5] = "Пасок готовий, {ім'я}.", ["en"] = "Earthshatter Girdle", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Desecrated Girdle"] = "осквернений пасок", ["Desecrated Girdle (Provided)"] = "осквернений пасок (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9075] = { [1] = "Наручі Землетрощителя", [2] = "Прошу тебе, зроби мені честь і поверни обладунки тих, хто поліг, захищаючи ці землі.\n\nЦі обладунки були осквернені та, безсумнівно, використовуються у злих цілях, але за допомогою обрізків та деяких інших матеріалів їх можна відновити та знову вдягнути на битву.\n\nПринеси мені обладунки полеглих разом з матеріалами для їх очищення, і обладунки Землетрощителя будуть твоїми.\n\nШукай їх в Наксрамасі.", [3] = "Рімблат Землетрощитель з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить наручі Землетрощителя, якщо ви принесете йому наступні предмети: осквернені наручі, 6 понівечених обрізків кольчуги, злиток арканіту та 2 оброблені міцні шкури.", [4] = "Ти {стать:приніс:принесла} мені все необхідне?", [5] = "Наручі готові, {ім'я}.", ["en"] = "Earthshatter Wristguards", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Wristguards"] = "осквернені наручі", ["Desecrated Wristguards (Provided)"] = "осквернені наручі (видано)", ["Wartorn Chain Scrap"] = "понівечений обрізок кольчуги", ["Wartorn Chain Scrap (Provided)"] = "понівечений обрізок кольчуги (видано)" } },
    [9077] = { [1] = "Мундир кістяної коси", [2] = "Якщо ти хочеш обладунки кістяної коси, тобі доведеться принеси мені матеріали.\n\nВирушай в Наксрамас, величезне летюче місто смерті он там в небі, знайди осквернені обладунки та понівечені обрізки. Принеси мені їх разом з усіма іншими матеріалами і отримаєш обладунки кістяної коси. О, так, і тобі доведеться заплатити за мої послуги... Я знайду кістки.", [3] = "Роган-Душогуб з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить мундир кістяної коси, якщо ви принесете йому наступні предмети: осквернену кірасу, 25 понівечених обрізків шкіри, 2 злитки арканіту та 6 оброблених міцних шкур.", [4] = "<Роган показує вам свої рухи.>\n\nЩо таке, {ім'я}? Я маю ідеально влучити в цю ціль, щоб потім брати участь у змаганнях.", [5] = "Ось, будь ласка, {раса:к}. Як і обіцяв, мундир кістяної коси. Сподіваюся, поліції моди тут немає. Тебе б кинули до в'язниці за те, що ти це носиш!", ["en"] = "Bonescythe Breastplate", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Breastplate"] = "осквернена кіраса", ["Desecrated Breastplate (Provided)"] = "осквернена кіраса (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [9078] = { [1] = "Поножі кістяної коси", [2] = "Якщо ти хочеш обладунки кістяної коси, тобі доведеться принеси мені матеріали.\n\nВирушай в Наксрамас, величезне летюче місто смерті он там в небі, знайди осквернені обладунки та понівечені обрізки. Принеси мені їх разом з усіма іншими матеріалами і отримаєш обладунки кістяної коси. О, так, і тобі доведеться заплатити за мої послуги... Я знайду кістки.", [3] = "Роган-Душогуб з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить поножі кістяної коси, якщо ви принесете йому наступні предмети: осквернені ножні лати, 20 понівечених обрізків шкіри, злиток арканіту, 8 оброблених міцних шкур та 100 золотих.", [4] = "<Роган сміється.>\n\nЯ просто усвідомив всю іронічність ситуації.", [5] = "Будь обережніше з цим. Ти можеш порізатися.", ["en"] = "Bonescythe Legplates", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Legplates"] = "осквернені ножні лати", ["Desecrated Legplates (Provided)"] = "осквернені ножні лати (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [9079] = { [1] = "Головний убір кістяної коси", [2] = "Якщо ти хочеш обладунки кістяної коси, тобі доведеться принеси мені матеріали.\n\nВирушай в Наксрамас, величезне летюче місто смерті он там в небі, знайди осквернені обладунки та понівечені обрізки. Принеси мені їх разом з усіма іншими матеріалами і отримаєш обладунки кістяної коси. О, так, і тобі доведеться заплатити за мої послуги... Я знайду кістки.", [3] = "Роган-Душогуб з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить головний убір кістяної коси, якщо ви принесете йому наступні предмети: осквернений шолом, 15 понівечених обрізків шкіри, 8 оброблених міцних шкур, кристал сплетіння та 75 золотих.", [4] = "Ти даєш мені гроші.\n\n<Роган сміється.>\n\nЦе все ще смішить мене.", [5] = "Що відрізняє мою модель головного убору кістяної коси від моделі Дона Хуліо, так це стиль, {ім'я}. Стиль...", ["en"] = "Bonescythe Helmet", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Helmet"] = "осквернений шолом", ["Desecrated Helmet (Provided)"] = "осквернений шолом (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [908] = { [1] = "Серед руїн", [2] = "Сутінковий Молот проник до руїн місячної святині в Чорноводних глибинах. Їхня присутність націлена на те, щоб обернути стихії проти нас. Якщо ми не будемо діяти, вони захоплять ці місця.\n\n{ім'я}, йди до Чорноводних глибин і знайди в руїнах камінь глибин. Він має бути десь неподалік під водою. В ньому заховано ядро глибин — пристрій, що дозволить нам зчитати дані про всю активність стихій. Якщо принесеш його мені — ми зі Служителями Землі зможемо зупинити їх!", [3] = "Принесіть ядро глибин Дже'неу Санкрі на форпост Зорам'ґар, що в Ясенедолі.", [4] = "Чи вдалося тобі знайти ядро глибин? Без нього ми ніколи не дізнаємось, що замислив Сутінковий Молот.", [5] = "Це те, що мені потрібно! Ядро глибин — невичерпне джерело інформації, яку ми можемо звідти добути. Що б там не замислив Сутінковий Молот — а повір мені, нічого хорошого — ми з моїми побратимами дізнаємось про це.\n\nТи сьогодні добре {стать:потрудився:потрудилася} і Служителі Землі неймовірно вдячні тобі за це. Це також і допомога Орді, тож можеш пишатися собою.", ["en"] = "Amongst the Ruins", ["tasks"] = { ["Fathom Core"] = "ядро глибин" } },
    [9080] = { [1] = "Наплечі кістяної коси", [2] = "Якщо ти хочеш обладунки кістяної коси, тобі доведеться принеси мені матеріали.\n\nВирушай в Наксрамас, величезне летюче місто смерті он там в небі, знайди осквернені обладунки та понівечені обрізки. Принеси мені їх разом з усіма іншими матеріалами і отримаєш обладунки кістяної коси. О, так, і тобі доведеться заплатити за мої послуги... Я знайду кістки.", [3] = "Роган-Душогуб з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить наплечі кістяної коси, якщо ви принесете йому наступні предмети: осквернене напліччя, 12 понівечених обрізків шкіри, 5 оброблених міцних шкур, кристал сплетіння та 50 золотих.", [4] = "<Роган дивиться на вас з підозрою.>\n\n{стать:Був:Була} нещодавно в Десниці Тіра?", [5] = "<Роган протирає чоло від поту.>\n\nНад цими наплечами довелося попотіти! Не дозволь вбити себе, як невдаху, {ім'я}.", ["en"] = "Bonescythe Pauldrons", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Pauldrons"] = "осквернене напліччя", ["Desecrated Pauldrons (Provided)"] = "осквернене напліччя (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [9081] = { [1] = "Сабатони кістяної коси", [2] = "Якщо ти хочеш обладунки кістяної коси, тобі доведеться принеси мені матеріали.\n\nВирушай в Наксрамас, величезне летюче місто смерті он там в небі, знайди осквернені обладунки та понівечені обрізки. Принеси мені їх разом з усіма іншими матеріалами й отримаєш обладунки кістяної коси. О, так, і тобі доведеться заплатити за мої послуги... Я знайду кістки.", [3] = "Роган-Душогуб з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить сабатони кістяної коси, якщо ви принесете йому наступні предмети: осквернені сабатони, 12 понівечених обрізків шкіри, 3 оброблені міцні шкури, 2 кристали сплетіння та 25 золотих.", [4] = "Просто принеси мені матеріали та припини гаяти мій час, {клас:к}.", [5] = "Вони як раз твого розміру. Ти ж не {стать:ходив:ходила} знову до Десниці Тіра?", ["en"] = "Bonescythe Sabatons", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Sabatons"] = "осквернені сабатони", ["Desecrated Sabatons (Provided)"] = "осквернені сабатони (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [9082] = { [1] = "Бойові рукавиці кістяної коси", [2] = "Якщо ти хочеш обладунки кістяної коси, тобі доведеться принеси мені матеріали.\n\nВирушай в Наксрамас, величезне летюче місто смерті он там в небі, знайди осквернені обладунки та понівечені обрізки. Принеси мені їх разом з усіма іншими матеріалами і отримаєш обладунки кістяної коси. О, так, і тобі доведеться заплатити за мої послуги... Я знайду кістки.", [3] = "Роган-Душогуб з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить бойові рукавиці кістяної коси, якщо ви принесете йому наступні предмети: осквернені рукавиці, 8 понівечених обрізків шкіри, злиток арканіту та 5 оброблених міцних шкур.", [4] = "Ну і як ти хочеш, щоб я розпочав роботу без потрібних мені предметів?", [5] = "Ці рукавиці, ймовірно, могли б замінити зброю за крайньої потреби. Носи їх з гордістю!", ["en"] = "Bonescythe Gauntlets", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Gauntlets"] = "осквернені рукавиці", ["Desecrated Gauntlets (Provided)"] = "осквернені рукавиці (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [9083] = { [1] = "Пасок кістяної коси", [2] = "Якщо ти хочеш обладунки кістяної коси, тобі доведеться принеси мені матеріали.\n\nВирушай в Наксрамас, величезне летюче місто смерті он там в небі, знайди осквернені обладунки та понівечені обрізки. Принеси мені їх разом з усіма іншими матеріалами й отримаєш обладунки кістяної коси. О, так, і тобі доведеться заплатити за мої послуги... Я знайду кістки.", [3] = "Роган-Душогуб з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить пасок кістяної коси, якщо ви принесете йому наступні предмети: осквернений ремінь, 8 понівечених обрізків шкіри, 5 оброблених міцних шкур, кристал сплетіння та 15 золотих.", [4] = "Ну і як ти хочеш, щоб я розпочав роботу без потрібних мені предметів?", [5] = "Пасок готовий, {ім'я}. Чи {стать:бачив:бачила} ти колись таку якісну річ за таку низьку ціну?", ["en"] = "Bonescythe Waistguard", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Waistguard"] = "осквернений ремінь", ["Desecrated Waistguard (Provided)"] = "осквернений ремінь (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [9084] = { [1] = "Браслети кістяної коси", [2] = "Якщо ти хочеш обладунки кістяної коси, тобі доведеться принеси мені матеріали.\n\nВирушай в Наксрамас, величезне летюче місто смерті он там в небі, знайди осквернені обладунки та понівечені обрізки. Принеси мені їх разом з усіма іншими матеріалами і отримаєш обладунки кістяної коси. О, так, і тобі доведеться заплатити за мої послуги... Я знайду кістки.", [3] = "Роган-Душогуб з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить браслети кістяної коси, якщо ви принесете йому наступні предмети: осквернені поручі, 6 понівечених обрізків шкіри, злиток арканіту, 2 оброблені міцні шкури та 10 золотих.", [4] = "Ну і як ти хочеш, щоб я розпочав роботу без потрібних мені предметів?", [5] = "Браслети готові, {ім'я}.", ["en"] = "Bonescythe Bracers", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Bracers"] = "осквернені поручі", ["Desecrated Bracers (Provided)"] = "осквернені поручі (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [9085] = { [1] = "Тіні приречення", [2] = "Після того, як ти {стать:знищив:знищила} захист кругів виклику Скари, які з'являються у тих місцях, де відбувається напад, тобі доведеться битися з прислужниками Скари, які охороняють ці круги.\n\nПравду кажучи, це не живі істоти. Це тіні, одні з найстрашніших створінь Короля-ліча. Їх можна виявити за допомогою некротичних рун, які вони носять при собі, а потім їх можна знищити магією або силою зброї.", [3] = "Ідіть до кола виклику та вбийте тінь приречення, після чого повертайтеся до командира Томаса Гелерана у Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Ну як, є якісь успіхи, {ім'я}?", [5] = "Чудова робота, {ім'я}. Тепер, коли тіні знищено, це лише питання часу, коли Король-ліч відкличе свої некрополі та дасть нам спокій.", ["en"] = "Shadows of Doom", ["tasks"] = { ["Shadow of Doom"] = "тінь приречення", ["Shadow of Doom slain"] = "тінь приречення: убито" } },
    [9086] = { [1] = "Мундир сноходця", [2] = "Багато героїв загинуло в минулій війні, і багато хто досі продовжує гинути в руках Скари. З трупів загиблих здирають обладунки та приносять їх у Наксрамас для невідомих цілей.\n\nПоверни осквернену броню, понівечені обрізки та інші необхідні матеріали, і я зроблю обладунки сноходця.", [3] = "Рейн з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить мундир сноходця, якщо ви принесете їй наступні предмети: осквернений мундир, 25 понівечених обрізків шкіри, 6 оброблених міцних шкур та 2 кристали сплетіння.", [4] = "Вартість матеріалів висока, але ти про неї швидко забудеш.", [5] = "Твій мундир сноходця готовий, {ім'я}.", ["en"] = "Dreamwalker Tunic", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Tunic"] = "осквернений мундир", ["Desecrated Tunic (Provided)"] = "осквернений мундир (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [9087] = { [1] = "Набедреники сноходця", [2] = "Багато героїв загинуло в минулій війні, і багато хто досі продовжує гинути в руках Скари. З трупів загиблих здирають обладунки та приносять їх у Наксрамас для невідомих цілей.\n\nПоверни осквернену броню, понівечені обрізки та інші необхідні матеріали, і я зроблю обладунки сноходця.", [3] = "Рейн з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить набедреники сноходця, якщо ви принесете їй наступні предмети: осквернені поножі, 20 понівечених обрізків шкіри, 8 оброблених міцних шкур та кристал сплетіння.", [4] = "Вартість матеріалів висока, але ти про неї швидко забудеш.", [5] = "Як і обіцяла, набедреники сноходця.\n\n<Рейн передає вам обладунок.>", ["en"] = "Dreamwalker Legguards", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Legguards"] = "осквернені поножі", ["Desecrated Legguards (Provided)"] = "осквернені поножі (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [9088] = { [1] = "Головний убір сноходця", [2] = "Багато героїв загинуло в минулій війні, і багато хто досі продовжує гинути в руках Скари. З трупів загиблих здирають обладунки та приносять їх у Наксрамас для невідомих цілей.\n\nПоверни осквернену броню, понівечені обрізки та інші необхідні матеріали, і я зроблю обладунки сноходця.", [3] = "Рейн з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить головний убір сноходця, якщо ви принесете їй наступні предмети: осквернений головний убір, 15 понівечених обрізків шкіри, 6 оброблених міцних шкур та 2 кристали сплетіння.", [4] = "Вартість матеріалів висока, але ти про неї швидко забудеш.", [5] = "Твій головний убір сноходця готовий, {ім'я}.", ["en"] = "Dreamwalker Headpiece", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Headpiece"] = "осквернений головний убір", ["Desecrated Headpiece (Provided)"] = "осквернений головний убір (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
    [9089] = { [1] = "Наплечі сноходця", [2] = "Багато героїв загинуло в минулій війні, і багато хто досі продовжує гинути в руках Скари. З трупів загиблих здирають обладунки та приносять їх у Наксрамас для невідомих цілей.\n\nПоверни осквернену броню, понівечені обрізки та інші необхідні матеріали, і я зроблю обладунки сноходця.", [3] = "Рейн з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить наплечі сноходця, якщо ви принесете їй наступні предмети: осквернені наплечі, 12 понівечених обрізків шкіри, 5 оброблених міцних шкур та кристал сплетіння.", [4] = "Вартість матеріалів висока, але ти про неї швидко забудеш.", [5] = "Твої наплечі сноходця готові, {ім'я}.", ["en"] = "Dreamwalker Spaulders", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Spaulders"] = "осквернені наплечі", ["Desecrated Spaulders (Provided)"] = "осквернені наплечі (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Leather Scrap"] = "понівечений обрізок шкіри", ["Wartorn Leather Scrap (Provided)"] = "понівечений обрізок шкіри (видано)" } },
