    [9095] = { [1] = "Мантія крижаного вогню", [2] = "Як вартова, я мала доступ до особистих речей Медіва. Серед них мене найбільше цікавили фоліанти. Хоча здебільшого в книгах була суцільна маячня, серед них були й перлини. В одному з фоліантів описується створення обладунку, гідного архімагів: обладунку крижаного вогню.\n\n<Анжела вказує на свою голову.>\n\nВсі знання тепер тут, і я хочу поділитися плодами цих знань з тобою, якщо ти забезпечиш мене необхідними матеріалами.", [3] = "Архімагиня Анжела Досантос з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить мантію крижаного вогню, якщо ви принесете їй наступні предмети: осквернену мантію, 25 понівечених обрізків тканини, 4 місячні полотна та 2 кристали сплетіння.", [4] = "З відповідними матеріалами та реагентами я можу створити обладунок крижаного вогню.", [5] = "Не забувай, що неконтрольована сила така ж руйнівна, як і сила, яку не використовують, {клас:к}. Будь {стать:обережним:обережною}, одягаючи обладунок крижаного вогню.", ["en"] = "Frostfire Robe", ["tasks"] = { ["Desecrated Robe"] = "осквернена мантія", ["Desecrated Robe (Provided)"] = "осквернена мантія (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
