    [9098] = { [1] = "Наплічники крижаного вогню", [2] = "Як вартова, я мала доступ до особистих речей Медіва. Серед них мене найбільше цікавили фоліанти. Хоча здебільшого в книгах була суцільна маячня, серед них були й перлини. В одному з фоліантів описується створення обладунку, гідного архімагів: обладунку крижаного вогню.\n\n<Анжела вказує на свою голову.>\n\nВсі знання тепер тут, і я хочу поділитися плодами цих знань з тобою, якщо ти забезпечиш мене необхідними матеріалами.", [3] = "Архімагиня Анжела Досантос з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить наплічники крижаного вогню, якщо ви принесете їй наступні предмети: осквернені наплічники, 12 понівечених обрізків тканини, 2 місячні полотна та 3 оброблені міцні шкури.", [4] = "З відповідними матеріалами та реагентами я можу створити обладунок крижаного вогню.", [5] = "Не забувай, що неконтрольована сила така ж руйнівна, як і сила, яку не використовують, {клас:к}. Будь {стать:обережним:обережною}, одягаючи обладунок крижаного вогню.", ["en"] = "Frostfire Shoulderpads", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Shoulderpads"] = "осквернені наплічники", ["Desecrated Shoulderpads (Provided)"] = "осквернені наплічники (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9099] = { [1] = "Сандалі крижаного вогню", [2] = "Як вартова, я мала доступ до особистих речей Медіва. Серед них мене найбільше цікавили фоліанти. Хоча здебільшого в книгах була суцільна маячня, серед них були й перлини. В одному з фоліантів описується створення обладунку, гідного архімагів: обладунку крижаного вогню.\n\n<Анжела вказує на свою голову.>\n\nВсі знання тепер тут, і я хочу поділитися плодами цих знань з тобою, якщо ти забезпечиш мене необхідними матеріалами.", [3] = "Архімагиня Анжела Досантос з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить сандалі крижаного вогню, якщо ви принесете їй наступні предмети: осквернені сандалі, 12 понівечених обрізків тканини, 2 місячні полотна та 3 оброблені міцні шкури.", [4] = "З відповідними матеріалами та реагентами я зможу створити обладунок крижаного вогню.", [5] = "Не забувай, що неконтрольована сила така ж руйнівна, як і сила, яку не використовують, {клас:к}. Будь {стать:обережним:обережною}, одягаючи обладунок крижаного вогню.", ["en"] = "Frostfire Sandals", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Sandals"] = "осквернені сандалі", ["Desecrated Sandals (Provided)"] = "осквернені сандалі (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [910] = { [1] = "У доки", [2] = "Я чув оповіді про могутні кораблі, які плавають між Брашпилем і Грабіжною Бухтою! Це було б так круто плавати по океану і брати участь у великих морських битвах. Можливо, коли я виросту, я стану могутнім моряком Орди! Так!\n\nПокажеш мені доки Брашпиля, будь ласка? Обіцяю, що не полізу в воду і не створю ніяких проблем — я просто хочу побачити великі кораблі й відчути запах солоної морської води! Так!", [3] = "Відведіть свого підопічного до доків Брашпиля в Степи.", [4] = "Ми вже прийшли?", [5] = "Ого, океан ВЕЛИЧЕЗНИЙ! Там було багато морських чайок і всього іншого — він такий же галасливий і метушливий, як я і думав. А ще поруч є пірати — це так круто!\n\nДякую, що {стать:взяв:взяла} мене до Брашпиля, {ім'я}. Це було так класно!", ["en"] = "Down at the Docks", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Go to the docks of Ratchet in the Barrens."] = "Ідіть до доків Ретчета в Степах." } },
    [9100] = { [1] = "Рукавиці крижаного вогню", [2] = "Як вартова, я мала доступ до особистих речей Медіва. Серед них мене найбільше цікавили фоліанти. Хоча здебільшого в книгах була суцільна маячня, серед них були й перлини. В одному з фоліантів описується створення обладунку, гідного архімагів: обладунку крижаного вогню.\n\n<Анжела вказує на свою голову.>\n\nВсі знання тепер тут, і я хочу поділитися плодами цих знань з тобою, якщо ти забезпечиш мене необхідними матеріалами.", [3] = "Архімагиня Анжела Досантос з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить рукавиці крижаного вогню, якщо ви принесете їй наступні предмети: осквернені рукавички, 8 понівечених обрізків тканини та 4 місячні полотна.", [4] = "З відповідними матеріалами та реагентами я можу створити обладунок крижаного вогню.", [5] = "Не забувай, що неконтрольована сила така ж руйнівна, як і сила, яку не використовують, {клас:к}. Будь {стать:обережним:обережною}, одягаючи обладунок крижаного вогню.", ["en"] = "Frostfire Gloves", ["tasks"] = { ["Desecrated Gloves"] = "осквернені рукавички", ["Desecrated Gloves (Provided)"] = "осквернені рукавички (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9101] = { [1] = "Пояс крижаного вогню", [2] = "Як вартова, я мала доступ до особистих речей Медіва. Серед них мене найбільше цікавили фоліанти. Хоча здебільшого в книгах була суцільна маячня, серед них були й перлини. В одному з фоліантів описується створення обладунку, гідного архімагів: обладунку крижаного вогню.\n\n<Анжела вказує на свою голову.>\n\nВсі знання тепер тут, і я хочу поділитися плодами цих знань з тобою, якщо ти забезпечиш мене необхідними матеріалами.", [3] = "Архімагиня Анжела Досантос з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить пояс крижаного вогню, якщо ви принесете їй наступні предмети: осквернений пояс, 8 понівечених обрізків тканини, 2 арканічних кристали та 2 місячні полотна.", [4] = "З відповідними матеріалами та реагентами я можу створити обладунок крижаного вогню.", [5] = "Не забувай, що неконтрольована сила така ж руйнівна, як і сила, яку не використовують, {клас:к}. Будь {стать:обережним:обережною}, одягаючи обладунок крижаного вогню.", ["en"] = "Frostfire Belt", ["tasks"] = { ["Arcane Crystal"] = "арканічний кристал", ["Arcane Crystal (Provided)"] = "арканічний кристал (видано)", ["Desecrated Belt"] = "осквернений пояс", ["Desecrated Belt (Provided)"] = "осквернений пояс (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9102] = { [1] = "Браслети крижаного вогню", [2] = "Як вартова, я мала доступ до особистих речей Медіва. Серед них мене найбільше цікавили фоліанти. Хоча здебільшого в книгах була суцільна маячня, серед них були й перлини. В одному з фоліантів описується створення обладунку, гідного архімагів: обладунку крижаного вогню.\n\n<Анжела вказує на свою голову.>\n\nВсі знання тепер тут, і я хочу поділитися плодами цих знань з тобою, якщо ти забезпечиш мене необхідними матеріалами.", [3] = "Архімагиня Анжела Досантос з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить браслети крижаного вогню, якщо ви принесете їй наступні предмети: осквернені браслети, 6 понівечених обрізків тканини, арканічний кристал та кристал сплетіння.", [4] = "З відповідними матеріалами та реагентами я можу створити обладунок крижаного вогню.", [5] = "Не забувай, що неконтрольована сила така ж руйнівна, як і сила, яку не використовують, {клас:к}. Будь {стать:обережним:обережною}, одягаючи обладунок крижаного вогню.", ["en"] = "Frostfire Bindings", ["tasks"] = { ["Arcane Crystal"] = "арканічний кристал", ["Arcane Crystal (Provided)"] = "арканічний кристал (видано)", ["Desecrated Bindings"] = "осквернені браслети", ["Desecrated Bindings (Provided)"] = "осквернені браслети (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9103] = { [1] = "Мантія чумного серця", [2] = "Не буду брехати, слимаче. Темрява, яку містять в собі предмети чумного серця може знищити нас обох. Ось чому ціна така висока. Якщо я помру, то я помру багатим.\n\nМені начхати як помреш ти, роби те, що я тобі кажу. Принось мені все, що мені потрібно, і ми обоє матимемо користь... або помремо. Але я вже пояснював це...", [3] = "Матаус Гнівоклят з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить мантію чумного серця, якщо ви принесете йому наступні предмети: осквернену мантію, 25 понівечених обрізків тканини, 4 місячні полотна та 2 кристали сплетіння.", [4] = "{стать:Блудний гризун повернувся!:Блудна куниця повернулася!} У тебе є те, що мені потрібно?", [5] = "Бачиш? Тепер ти розумієш силу? Очищення... Що за дурні...\n\n<Матаус несхвально хитає головою.>\n\nА тепер забирай це і геть з моїх очей.", ["en"] = "Plagueheart Robe", ["tasks"] = { ["Desecrated Robe"] = "осквернена мантія", ["Desecrated Robe (Provided)"] = "осквернена мантія (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9104] = { [1] = "Поножі чумного серця", [2] = "Не буду брехати, слимаче. Темрява, яку містять в собі предмети чумного серця може знищити нас обох. Ось чому ціна така висока. Якщо я помру, то я помру багатим.\n\nМені начхати як помреш ти, роби те, що я тобі кажу. Принось мені все, що мені потрібно, і ми обоє матимемо користь... або помремо. Але я вже пояснював це...", [3] = "Матаус Гнівоклят з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить поножі чумного серця, якщо ви принесете йому наступні предмети: осквернені штани, 20 понівечених обрізків тканини, 4 місячні полотна та 2 кристали сплетіння.", [4] = "{стать:Блудний гризун повернувся!:Блудна куниця повернулася!} У тебе є те, що мені потрібно?", [5] = "Бачиш? Тепер ти розумієш силу? Очищення... Що за дурні...\n\n<Матаус несхвально хитає головою.>\n\nА тепер забирай це і геть з моїх очей.", ["en"] = "Plagueheart Leggings", ["tasks"] = { ["Desecrated Leggings"] = "осквернені штани", ["Desecrated Leggings (Provided)"] = "осквернені штани (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9105] = { [1] = "Вінець чумного серця", [2] = "Не буду брехати, слимаче. Темрява, яку містять в собі предмети чумного серця може знищити нас обох. Ось чому ціна така висока. Якщо я помру, то я помру багатим.\n\nМені начхати як помреш ти, роби те, що я тобі кажу. Принось мені все, що мені потрібно, і ми обоє матимемо користь... або помремо. Але я вже пояснював це...", [3] = "Матаус Гнівоклят з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить вінець чумного серця, якщо ви принесете йому наступні предмети: осквернений вінець, 15 понівечених обрізків тканини, 3 місячні полотна та 3 кристали сплетіння.", [4] = "{стать:Блудний гризун повернувся!:Блудна куниця повернулася!} У тебе є те, що мені потрібно?", [5] = "Бачиш? Тепер ти розумієш силу? Очищення... Що за дурні...\n\n<Матаус несхвально хитає головою.>\n\nА тепер забирай це і геть з моїх очей.", ["en"] = "Plagueheart Circlet", ["tasks"] = { ["Desecrated Circlet"] = "осквернений вінець", ["Desecrated Circlet (Provided)"] = "осквернений вінець (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9106] = { [1] = "Наплічники чумного серця", [2] = "Не буду брехати, слимаче. Темрява, яку містять в собі предмети чумного серця може знищити нас обох. Ось чому ціна така висока. Якщо я помру, то я помру багатим.\n\nМені начхати як помреш ти, роби те, що я тобі кажу. Принось мені все, що мені потрібно, і ми обоє матимемо користь... або помремо. Але я вже пояснював це...", [3] = "Матаус Гнівоклят з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить наплічники чумного серця, якщо ви принесете йому наступні предмети: осквернені наплічники, 12 понівечених обрізків тканини, 2 місячні полотна та 3 оброблені міцні шкури.", [4] = "{стать:Блудний гризун повернувся!:Блудна куниця повернулася!} У тебе є те, що мені потрібно?", [5] = "Бачиш? Тепер ти розумієш силу? Очищення... Що за дурні...\n\n<Матаус несхвально хитає головою.>\n\nА тепер забирай це і геть з моїх очей.", ["en"] = "Plagueheart Shoulderpads", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Shoulderpads"] = "осквернені наплічники", ["Desecrated Shoulderpads (Provided)"] = "осквернені наплічники (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9107] = { [1] = "Сандалі чумного серця", [2] = "Не буду брехати, слимаче. Темрява, яку містять в собі предмети чумного серця може знищити нас обох. Ось чому ціна така висока. Якщо я помру, то я помру багатим.\n\nМені начхати як помреш ти, роби те, що я тобі кажу. Принось мені все, що мені потрібно, і ми обоє матимемо користь... або помремо. Але я вже пояснював це...", [3] = "Матаус Гнівоклят з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить сандалі чумного серця, якщо ви принесете йому наступні предмети: осквернені сандалі, 12 понівечених обрізків тканини, 2 місячні полотна та 3 оброблені міцні шкури.", [4] = "{стать:Блудний гризун повернувся!:Блудна куниця повернулася!} У тебе є те, що мені потрібно?", [5] = "Бачиш? Тепер ти розумієш силу? Очищення... Що за дурні...\n\n<Матаус несхвально хитає головою.>\n\nА тепер забирай це і геть з моїх очей.", ["en"] = "Plagueheart Sandals", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Sandals"] = "осквернені сандалі", ["Desecrated Sandals (Provided)"] = "осквернені сандалі (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9108] = { [1] = "Рукавички чумного серця", [2] = "Не буду брехати, слимаче. Темрява, яку містять в собі предмети чумного серця може знищити нас обох. Ось чому ціна така висока. Якщо я помру, то я помру багатим.\n\nМені начхати як помреш ти, роби те, що я тобі кажу. Принось мені все, що мені потрібно, і ми обоє матимемо користь... або помремо. Але я вже пояснював це...", [3] = "Матаус Гнівоклят з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить рукавички чумного серця, якщо ви принесете йому наступні предмети: осквернені рукавички, 8 понівечених обрізків тканини та 4 місячні полотна.", [4] = "{стать:Блудний гризун повернувся!:Блудна куниця повернулася!} У тебе є те, що мені потрібно?", [5] = "Бачиш? Тепер ти розумієш силу? Очищення... Що за дурні...\n\n<Матаус несхвально хитає головою.>\n\nА тепер забирай це і геть з моїх очей.", ["en"] = "Plagueheart Gloves", ["tasks"] = { ["Desecrated Gloves"] = "осквернені рукавички", ["Desecrated Gloves (Provided)"] = "осквернені рукавички (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9109] = { [1] = "Пояс чумного серця", [2] = "Не буду брехати, слимаче. Темрява, яку містять в собі предмети чумного серця може знищити нас обох. Ось чому ціна така висока. Якщо я помру, то я помру багатим.\n\nМені начхати як помреш ти, роби те, що я тобі кажу. Принось мені все, що мені потрібно, і ми обоє матимемо користь... або помремо. Але я вже пояснював це...", [3] = "Матаус Гнівоклят з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить пояс чумного серця, якщо ви принесете йому наступні предмети: осквернений пояс, 8 понівечених обрізків тканини, 2 арканічні кристали та 2 місячні полотна.", [4] = "{стать:Блудний гризун повернувся!:Блудна куниця повернулася!} У тебе є те, що мені потрібно?", [5] = "Бачиш? Тепер ти розумієш силу? Очищення... Що за дурні...\n\n<Матаус несхвально хитає головою.>\n\nА тепер забирай це і геть з моїх очей.", ["en"] = "Plagueheart Belt", ["tasks"] = { ["Arcane Crystal"] = "арканічний кристал", ["Arcane Crystal (Provided)"] = "арканічний кристал (видано)", ["Desecrated Belt"] = "осквернений пояс", ["Desecrated Belt (Provided)"] = "осквернений пояс (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [911] = { [1] = "Ворота до прикордоння", [2] = "Кажуть, що Ясенеділ — це нове прикордоння, а оплот Мор'шан у Степах — ворота до нього. Це було б так круто бути першопроходцем і забирати все необхідне з первозданного лісу! Кажуть, що саме там в майбутньому гримітимуть найбільші битви між Ордою та Альянсом. Я хочу потрапити туди, {ім'я}!\n\nВідведеш мене до оплоту Мор'шан, щоб я міг подивитися на нове прикордоння? Я хочу побачити, як Орда виганяє звідти смердючих нічних ельфів!", [3] = "Відведіть свого підопічного до оплоту Мор'шан в північній частині Степів, прямо перед входом в Ясенеділ.", [4] = "Ми вже прийшли?", [5] = "Вау, Ясенеділ — це місце справжніх пригод! Ти коли-небудь {стать:бився:билася} в Ясенедолі, {ім'я}? Коли я виросту і стану героєм, я хочу приїхати в Ясенеділ і битися за славу Орди!\n\nДякую, що {стать:взяв:взяла} мене сюди, {ім'я}. Ти {стать:найкращий:найкраща}!", ["en"] = "Gateway to the Frontier", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Go to the Mor'shan Rampart in the Barrens."] = "Ідіть до валу Мор'шана в Степах." } },
    [9110] = { [1] = "Браслети чумного серця", [2] = "Не буду брехати, слимаче. Темрява, яку містять в собі предмети чумного серця може знищити нас обох. Ось чому ціна така висока. Якщо я помру, то я помру багатим.\n\nМені начхати як помреш ти, роби те, що я тобі кажу. Принось мені все, що мені потрібно, і ми обоє матимемо користь... або помремо. Але я вже пояснював це...", [3] = "Матаус Гнівоклят з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить браслети чумного серця, якщо ви принесете йому наступні предмети: осквернені браслети, 6 понівечених обрізків тканини, арканічний кристал та кристал сплетіння.", [4] = "{стать:Блудний гризун повернувся!:Блудна куниця повернулася!} У тебе є те, що мені потрібно?", [5] = "Бачиш? Тепер ти розумієш силу? Очищення... Що за дурні...\n\n<Матаус несхвально хитає головою.>\n\nА тепер забирай це і геть з моїх очей.", ["en"] = "Plagueheart Bindings", ["tasks"] = { ["Arcane Crystal"] = "арканічний кристал", ["Arcane Crystal (Provided)"] = "арканічний кристал (видано)", ["Desecrated Bindings"] = "осквернені браслети", ["Desecrated Bindings (Provided)"] = "осквернені браслети (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9111] = { [1] = "Мантія віри", [2] = "<Отець Монтой робить дивні жести в повітрі перед вами.>\n\n{стать:Благословенний хлопче:Благословенна дівчино}, чи вдалося тобі знайти вбрання загиблих? Бідні душі, що втратили життя на полі битви — у них забрали все, навіть гідність.\n\nПринеси мені осквернені обладунки померлих разом з реагентами для їхнього очищення, і ти пізнаєш віру.", [3] = "Отець Ініґо Монтой з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить мантію віри, якщо ви принесете йому наступні предмети: осквернену мантію, 25 понівечених обрізків тканини, 4 місячні полотна та 2 кристали сплетіння.", [4] = "Ти {стать:приніс:принесла} мені реагенти, дитя?", [5] = "Твоє вбрання готове, {ім'я}. Покарай тих, хто бажає зашкодити нашому світу, своїм праведним вогнем.", ["en"] = "Robe of Faith", ["tasks"] = { ["Desecrated Robe"] = "осквернена мантія", ["Desecrated Robe (Provided)"] = "осквернена мантія (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9112] = { [1] = "Поножі віри", [2] = "<Отець Монтой робить дивні жести в повітрі перед вами.>\n\n{стать:Благословенний хлопче:Благословенна дівчино}, чи вдалося тобі знайти вбрання загиблих? Бідні душі, що втратили життя на полі битви — у них забрали все, навіть гідність.\n\nПринеси мені осквернені обладунки померлих разом з реагентами для їхнього очищення, і ти пізнаєш віру.", [3] = "Отець Ініґо Монтой з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить поножі віри, якщо ви принесете йому наступні предмети: осквернені штани, 20 понівечених обрізків тканини, 4 місячні полотна та 2 кристали сплетіння.", [4] = "Ти {стать:приніс:принесла} мені реагенти, дитя?", [5] = "Твоє вбрання готове, {ім'я}. Покарай тих, хто бажає зашкодити нашому світу, своїм праведним вогнем.", ["en"] = "Leggings of Faith", ["tasks"] = { ["Desecrated Leggings"] = "осквернені штани", ["Desecrated Leggings (Provided)"] = "осквернені штани (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9113] = { [1] = "Вінець віри", [2] = "<Отець Монтой робить дивні жести в повітрі перед вами.>\n\n{стать:Благословенний хлопче:Благословенна дівчино}, чи вдалося тобі знайти вбрання загиблих? Бідні душі, що втратили життя на полі битви — у них забрали все, навіть гідність.\n\nПринеси мені осквернені обладунки померлих разом з реагентами для їхнього очищення, і ти пізнаєш віру.", [3] = "Отець Ініґо Монтой з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить вінець віри, якщо ви принесете йому наступні предмети: осквернений вінець, 15 понівечених обрізків тканини, 3 місячні полотна та 3 кристали сплетіння.", [4] = "Ти {стать:приніс:принесла} мені реагенти, дитя?", [5] = "Твоє вбрання готове, {ім'я}. Покарай тих, хто бажає зашкодити нашому світу, своїм праведним вогнем.", ["en"] = "Circlet of Faith", ["tasks"] = { ["Desecrated Circlet"] = "осквернений вінець", ["Desecrated Circlet (Provided)"] = "осквернений вінець (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9114] = { [1] = "Наплічники віри", [2] = "<Отець Монтой робить дивні жести в повітрі перед вами.>\n\n{стать:Благословенний хлопче:Благословенна дівчино}, чи вдалося тобі знайти вбрання загиблих? Бідні душі, що втратили життя на полі битви — у них забрали все, навіть гідність.\n\nПринеси мені осквернені обладунки померлих разом з реагентами для їхнього очищення, і ти пізнаєш віру.", [3] = "Отець Ініґо Монтой з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить наплічники віри, якщо ви принесете йому наступні предмети: осквернені наплічники, 12 понівечених обрізків тканини, 2 місячні полотна та 3 оброблені міцні шкури.", [4] = "Ти {стать:приніс:принесла} мені реагенти, дитя?", [5] = "Твоє вбрання готове, {ім'я}. Покарай тих, хто бажає зашкодити нашому світу, своїм праведним вогнем.", ["en"] = "Shoulderpads of Faith", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Shoulderpads"] = "осквернені наплічники", ["Desecrated Shoulderpads (Provided)"] = "осквернені наплічники (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9115] = { [1] = "Сандалі віри", [2] = "<Отець Монтой робить дивні жести в повітрі перед вами.>\n\n{стать:Благословенний хлопче:Благословенна дівчино}, чи вдалося тобі знайти вбрання загиблих? Бідні душі, що втратили життя на полі битви — у них забрали все, навіть гідність.\n\nПринеси мені осквернені обладунки померлих разом з реагентами для їхнього очищення, і ти пізнаєш віру.", [3] = "Отець Ініґо Монтой з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить сандалі віри, якщо ви принесете йому наступні предмети: осквернені сандалі, 12 понівечених обрізків тканини, 2 місячні полотна та 3 оброблені міцні шкури.", [4] = "Ти {стать:приніс:принесла} мені реагенти, дитя?", [5] = "Твоє вбрання готове, {ім'я}. Покарай тих, хто бажає зашкодити нашому світу, своїм праведним вогнем.", ["en"] = "Sandals of Faith", ["tasks"] = { ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Desecrated Sandals"] = "осквернені сандалі", ["Desecrated Sandals (Provided)"] = "осквернені сандалі (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9116] = { [1] = "Рукавички віри", [2] = "<Отець Монтой робить дивні жести в повітрі перед вами.>\n\n{стать:Благословенний хлопче:Благословенна дівчино}, чи вдалося тобі знайти вбрання загиблих? Бідні душі, що втратили життя на полі битви — у них забрали все, навіть гідність.\n\nПринеси мені осквернені обладунки померлих разом з реагентами для їхнього очищення, і ти пізнаєш віру.", [3] = "Отець Ініґо Монтой з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить рукавички віри, якщо ви принесете йому наступні предмети: осквернені рукавички, 8 понівечених обрізків тканини та 4 місячні полотна.", [4] = "Ти {стать:приніс:принесла} мені реагенти, дитя?", [5] = "Твоє вбрання готове, {ім'я}. Покарай тих, хто бажає зашкодити нашому світу, своїм праведним вогнем.", ["en"] = "Gloves of Faith", ["tasks"] = { ["Desecrated Gloves"] = "осквернені рукавички", ["Desecrated Gloves (Provided)"] = "осквернені рукавички (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9117] = { [1] = "Пояс віри", [2] = "<Отець Монтой робить дивні жести в повітрі перед вами.>\n\n{стать:Благословенний хлопче:Благословенна дівчино}, чи вдалося тобі знайти вбрання загиблих? Бідні душі, що втратили життя на полі битви — у них забрали все, навіть гідність.\n\nПринеси мені осквернені обладунки померлих разом з реагентами для їхнього очищення, і ти пізнаєш віру.", [3] = "Отець Ініґо Монтой з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить пояс віри, якщо ви принесете йому наступні предмети: осквернений пояс, 8 понівечених обрізків тканини, 2 арканічні кристали та 3 місячні полотна.", [4] = "Ти {стать:приніс:принесла} мені реагенти, дитя?", [5] = "Твоє вбрання готове, {ім'я}. Покарай тих, хто бажає зашкодити нашому світу, своїм праведним вогнем.", ["en"] = "Belt of Faith", ["tasks"] = { ["Arcane Crystal"] = "арканічний кристал", ["Arcane Crystal (Provided)"] = "арканічний кристал (видано)", ["Desecrated Belt"] = "осквернений пояс", ["Desecrated Belt (Provided)"] = "осквернений пояс (видано)", ["Mooncloth"] = "місячне полотно", ["Mooncloth (Provided)"] = "місячне полотно (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [9118] = { [1] = "Браслети віри", [2] = "<Отець Монтой робить дивні жести в повітрі перед вами.>\n\n{стать:Благословенний хлопче:Благословенна дівчино}, чи вдалося тобі знайти вбрання загиблих? Бідні душі, що втратили життя на полі битви — у них забрали все, навіть гідність.\n\nПринеси мені осквернені обладунки померлих разом з реагентами для їхнього очищення, і ти пізнаєш віру.", [3] = "Отець Ініґо Монтой з Каплиці Надії Світла, що в Східних Зачумлених землях, зробить браслети віри, якщо ви принесете йому наступні предмети: осквернені браслети, 6 понівечених обрізків тканини, арканічний кристал та кристал сплетіння.", [4] = "Ти {стать:приніс:принесла} мені реагенти, дитя?", [5] = "Твоє вбрання готове, {ім'я}. Покарай тих, хто бажає зашкодити нашому світу, своїм праведним вогнем.", ["en"] = "Bindings of Faith", ["tasks"] = { ["Arcane Crystal"] = "арканічний кристал", ["Arcane Crystal (Provided)"] = "арканічний кристал (видано)", ["Desecrated Bindings"] = "осквернені браслети", ["Desecrated Bindings (Provided)"] = "осквернені браслети (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Wartorn Cloth Scrap"] = "понівечений обрізок тканини", ["Wartorn Cloth Scrap (Provided)"] = "понівечений обрізок тканини (видано)" } },
    [912] = { [1] = "Маскування Трогга-Каменяного Уламка", ["en"] = "Stonesplinter Trogg Disguise" },
    [9120] = { [1] = "Падіння Кел'Тузада", [2] = "Від повелителя Наксрамаса залишилася лише ця філактерія. Ваш внутрішній голос підказує вам, що її варто б знищити, щоб не дати лічу відродитися. На щастя, ви рідко прислухаєтеся до свого внутрішнього голосу.\n\nХтось у Каплиці Надії Світла добряче вам заплатить вам за цей артефакт. Кому є діло до того, що Кел'Тузад зможе відродитися?", [3] = "Віднесіть філактерію Кел'Тузада до Каплиці Надії Світла, що в Східних Зачумлених землях.", [4] = "БЛАГОСЛОВЕННЕ СВІТЛО! Що це за гидота у тебе в руках, {стать:хлопче:дівчино}?!", [5] = "Я й подумати не міг, що доживу до такого...\n\n<Отець Монтой бризкає слиною.>\n\nО так, ти отримаєш винагороду, {стать:хлопче:дівчино}. Велику винагороду. Давай цю річ сюди!", ["en"] = "The Fall of Kel'Thuzad", ["tasks"] = { ["The Phylactery of Kel'Thuzad"] = "філактерія Кел'Тузада", ["The Phylactery of Kel'Thuzad (Provided)"] = "філактерія Кел'Тузада (видано)" } },
    [9121] = { [1] = "Цитадель жаху — Наксрамас", [2] = "У гущавині Чумолісся лежить вхід до цитаделі жаху — Наксрамаса. Раніше всі спроби увійти до неї блокувалися магічними чарами, накладеними на рунічний портал. Так було цього часу.\n\nМи знайшли спосіб проникнути всередину завдяки арканічному покриву — старому закляттю Кірін-Тора, яке я дещо модифікувала. Оскільки твоєї відданості Світанку дещо бракує, за чари доведеться чимало заплатити. Ти можеш повернутися, коли тебе шануватимуть чи звеличуватимуть, щоб отримати знижку.", [3] = "Архімагиня Анжела Досантос з Каплиці Надії Світла, що в Східних Зачумлених землях, просить вас принести їй 5 арканічних кристалів, 2 кристали сплетіння, 1 сферу праведності та 60 золотих. Також, ви маєте бути {стать:почесним:почесною} серед Сріблястого Світанку.", [4] = "З Наксрамасу ще ніхто не повертався живим.", [5] = "Ти відчуєш легке поколювання, {ім'я:к}. Це означатиме, що чари спрацювали. Після цього ти зможеш потрапити до Наксрамаса, ступивши на рунічний портал в Чумоліссі.", ["en"] = "The Dread Citadel - Naxxramas", ["tasks"] = { ["9000 reputation with Argent Dawn"] = "9000 репутації у Сріблястого Світанку", ["Arcane Crystal"] = "арканічний кристал", ["Arcane Crystal (Provided)"] = "арканічний кристал (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)", ["Righteous Orb"] = "сфера праведності", ["Righteous Orb (Provided)"] = "сфера праведності (видано)" } },
    [9122] = { [1] = "Цитадель жаху — Наксрамас", [2] = "У гущавині Чумолісся лежить вхід до цитаделі жаху — Наксрамаса. Раніше всі спроби увійти до неї блокувалися магічними чарами, накладеними на рунічний портал. Так було цього часу.\n\nМи знайшли спосіб проникнути всередину завдяки постійному арканічному покриву — старому закляттю Кірін-Тора, яке я дещо модифікувала. Ці чари досить дорогі, однак за твою відданість Світанку частину витрат ми візьмемо на себе.", [3] = "Архімагиня Анжела Досантос з Каплиці Надії Світла, що в Східних Зачумлених землях, просить вас принести їй 2 арканічні кристали, 1 кристал сплетіння та 30 золотих. Також, ви маєте бути {стать:шанованим:шанованою} серед Сріблястого Світанку.", [4] = "З Наксрамасу ще ніхто не повертався живим.", [5] = "Ти відчуєш легке поколювання, {ім'я:к}. Це означатиме, що чари спрацювали. Після цього ти зможеш потрапити до Наксрамаса, ступивши на рунічний портал в Чумоліссі.", ["en"] = "The Dread Citadel - Naxxramas", ["tasks"] = { ["21000 reputation with Argent Dawn"] = "21000 репутації у Сріблястого Світанку", ["Arcane Crystal"] = "арканічний кристал", ["Arcane Crystal (Provided)"] = "арканічний кристал (видано)", ["Nexus Crystal"] = "кристал сплетіння", ["Nexus Crystal (Provided)"] = "кристал сплетіння (видано)" } },
    [9123] = { [1] = "Цитадель жаху — Наксрамас", [2] = "У гущавині Чумоліссі лежить вхід до цитаделі жаху — Наксрамаса. Раніше всі спроби увійти до неї блокувалися магічними чарами, накладеними на рунічний портал. Так було цього часу.\n\nМи знайшли спосіб проникнути всередину завдяки постійному арканічному покриву — старому закляттю Кірін-Тора, яке я дещо модифікувала. Ці чари досить дорогі, однак за твою непохитну відданість Світанку ми візьмемо всі витрати на себе.", [3] = "Архімагиня Анжела Досантос з Каплиці Надії Світла, що в Східних Зачумлених землях накладе на вас чари арканічного покриву безплатно. Для цього вас мають возвеличувати серед Сріблястого Світанку.", [4] = "З Наксрамасу ще ніхто не повертався живим.", [5] = "Ти відчуєш легке поколювання, {ім'я:к}. Це означатиме, що чари спрацювали. Після цього ти зможеш потрапити до Наксрамаса, ступивши на рунічний портал в Чумоліссі.", ["en"] = "The Dread Citadel - Naxxramas", ["tasks"] = { ["42000 reputation with Argent Dawn"] = "42000 репутації у Сріблястого Світанку" } },
    [9124] = { [1] = "Обладунки склепного ловця самі себе не зроблять...", [2] = "Хочеш отримати цю блискучу штучку?\n\n<Леопольд тримає в руках відзнаку Багряного Походу.>\n\nУ мене є невелика проблемка, з якою ти можеш мені допомогти, {ім'я}. Розумієш, я виготовляю обладунки склепного ловця для тих дурнів, що вештаються в Наксрамасі. Вони постачають мені основні матеріали, але мені завжди бракує частин тіл склепної нечисті. Принеси мені купку таких частин, і я заплачу тобі відзнакою, яку можна обміняти у квартирмейстерів.", [3] = "Мисливець Леопольд з каплиці Надії Світла, що у Східних Зачумлених землях, просить вас принести йому 30 частин тіл склепної нечисті.", [4] = "Як проходить полювання?", [5] = "О, цього буде достатньо, {ім'я}. Пам'ятай, що вони постійно мені потрібні. Тому за кожен набір частин тіл, я буду платити тобі відзнакою.", ["en"] = "Cryptstalker Armor Doesn't Make Itself...", ["tasks"] = { ["Crypt Fiend Parts"] = "частини тіл склепної нечисті", ["Crypt Fiend Parts (Provided)"] = "частини тіл склепної нечисті (видано)" } },
    [9125] = { [1] = "Частини тіл склепної нечисті", [4] = "Ти відмінно {стать:впорався:впоралася} з першим завданням, {ім'я}. Якщо у тебе є ще частини тіл, я з радістю заберу їх. За кожен набір я буду платити тобі відзнакою.", [5] = "Прекрасно, {ім'я}! Вони точно мені знадобляться.", ["en"] = "Crypt Fiend Parts", ["tasks"] = { ["Crypt Fiend Parts"] = "частини тіл склепної нечисті", ["Crypt Fiend Parts (Provided)"] = "частини тіл склепної нечисті (видано)" } },
    [9126] = { [1] = "Обладунки кістяної коси", [2] = "Для виготовлення обладунків кістяної коси, винайдених доном Хуліо, потрібні фрагменти кісток. Багато фрагментів кісток. І хоча ті сміливці, що наважуються піти в Наксрамас, приносять вдосталь матеріалів для виготовлення обладунків, фрагменти кісток Скари мені завжди потрібні.\n\nНу, що думаєш? Хочеш допомогти мені та водночас знищити трохи Скари?", [3] = "Рохан-Душогуб з каплиці Надії Світла, що у Східних Зачумлених землях, просить вас принести йому 30 фрагментів кісток.", [4] = "Я можу направити тебе до місць, що кишать скелетами, {клас:к}.", [5] = "Швидко ти працюєш, {ім'я}. Швидко, як лисиця... Скажи, а я тобі не розповідав, як грав у квартеті?\n\nНагадай мені якось розповісти тобі цю історію.", ["en"] = "Bonescythe Digs", ["tasks"] = { ["Bone Fragments"] = "фрагменти кісток", ["Bone Fragments (Provided)"] = "фрагменти кісток (видано)" } },
    [9127] = { [1] = "Фрагменти кісток", [4] = "У моєму ремеслі фрагменти кісток ніколи не бувають зайвими, {ім'я}. Як матимеш зайві — принеси їх мені, і я нагороджу тебе новою відзнакою.", [5] = "Скоро я здійсню свою мрію і влаштуюся танцюристом в клуб Пристробляху! Продовжуй в тому ж дусі, {ім'я}.", ["en"] = "Bone Fragments", ["tasks"] = { ["Bone Fragments"] = "фрагменти кісток", ["Bone Fragments (Provided)"] = "фрагменти кісток (видано)" } },
    [9128] = { [1] = "Задача зі стихіями", [2] = "Вітаю, {стать:мандрівнику:мандрівнице}! Тебе цікавить робота? Я плачу тим відзнаками. Їх можна обміняти у квартирмейстерів, щоб купити корисні речі.\n\nВсе що мені потрібно від тебе — це принести мені якомога більше ядер стихій. Чим більше, тим краще!\n\nТи зможеш знайти ядра стихій в елементалів усіх видів та розмірів.", [3] = "Архімаг Анжела Досантос з каплиці Надії Світла, що в Східних Зачумлених землях, просить вас принести їй 30 ядер стихій.", [4] = "Я можу лиш направити тебе на правильний шлях, {ім'я}.", [5] = "Чудова робота, {ім'я}! Як я й обіцяла — відзнака твоя. Лиш пам'ятай, що є ще багато способів отримати їх...", ["en"] = "The Elemental Equation", ["tasks"] = { ["Core of Elements"] = "ядро стихій", ["Core of Elements (Provided)"] = "ядро стихій (видано)" } },
    [9129] = { [1] = "Ядро стихій", [4] = "По правді кажучи, я використовую ядра для створення обладунків крижаного полум'я. Ці обладунки використовують маги, що б'ються в Наксрамасі. Без таких, як ти ми б точно програли цю битву.\n\nТому принеси мені якомога більше ядер, і отримаєш за них відзнаки.", [5] = "Твою допомогу неможливо переоцінити, {ім'я}. Молодець!", ["en"] = "Core of Elements", ["tasks"] = { ["Core of Elements"] = "ядро стихій", ["Core of Elements (Provided)"] = "ядро стихій (видано)" } },
    [9131] = { [1] = "Обладунки безстрашності", [2] = "Чи доводилося тобі бачити обладунки безстрашності, {клас:к}? Ні, звісно ж ні, ти ще зовсім {стать:юний:юна}. Так ось, вона неймовірна.\n\nТи, напевно, запитаєш, яке це має відношення до тебе? Я тобі ось що скажу, недотепо. Принеси мені брухт темного заліза, і я добряче заплачу за нього.\n\nМені потрібен брухт, щоб зібрати обладунки безстрашності для наших славетних героїв.", [3] = "Корфакс з каплиці Надії Світла, що у Східних Зачумлених землях, просить вас принести йому 30 брухтів темного заліза.", [4] = "<Корфакс сердито дивиться на вас.>\n\nЧого тобі ще треба? Напрям? Це я можу дати...", [5] = "Поки що вистачить. Якщо знайдеш ще — ти знаєш де мене шукати.", ["en"] = "Binding the Dreadnaught", ["tasks"] = { ["Dark Iron Scraps"] = "брухт темного заліза", ["Dark Iron Scraps (Provided)"] = "брухт темного заліза (видано)" } },
    [9132] = { [1] = "Брухт темного заліза", [4] = "За кожну купку брухту я даватиму тобі відзнаку. Чим більше, тим краще. А тепер забирайся з моїх очей, доки я не розрубав тебе навпіл!", [5] = "І це все, що ти мені {стать:приніс:принесла}? Можливо ти недочуваєш... Мені потрібно БІЛЬШЕ!", ["en"] = "Dark Iron Scraps", ["tasks"] = { ["Dark Iron Scraps"] = "брухт темного заліза", ["Dark Iron Scraps (Provided)"] = "брухт темного заліза (видано)" } },
    [9136] = { [1] = "Дика флора", [2] = "Я виготовляю особливі обладунки для хоробрих героїв, що ходять до Наксрамасу — вони називаються вбранням сноходця. Зазвичай герої забезпечують мене більшістю необхідних матеріалів, але мені завжди потрібні дикі пагони.\n\nТи можеш подумати, що ця робота не варта твоїх зусиль, але без пагонів створення цих обладунків неможливе.\n\nЯ заплачу за пагони відзнакою Світанку чи Багряного Походу — на твій вибір.", [3] = "Рейн з каплиці Надії Світла, що у Східних Зачумлених землях, просить вас принести їй 30 диких пагонів.", [4] = "Я добре знаю флору нашого світу. Тобі вказати правильний шлях?", [5] = "Я щиро вдячна тобі, {ім'я}.\n\n<Рейн кланяється.>\n\nІ пам'ятай, що я завжди готова прийняти більше пагонів.", ["en"] = "Savage Flora", ["tasks"] = { ["Savage Frond"] = "дикий пагін", ["Savage Frond (Provided)"] = "дикий пагін (видано)" } },
    [9137] = { [1] = "Дикі пагони", [4] = "За кожен набір пагонів я буду платити відзнаками Світанку чи Багряного Походу, на твій вибір.\n\nВідзнаки можна обміняти у квартирмейстерів на різні винагороди.", [5] = "Дякую тобі, {ім'я}. Твоя робота життєво важлива для нашої боротьби проти Скари.", ["en"] = "Savage Fronds", ["tasks"] = { ["Savage Frond"] = "дикий пагін", ["Savage Frond (Provided)"] = "дикий пагін (видано)" } },
    [9141] = { [1] = "Не так все просто", [2] = "Хочеш отримати замовлення? Що? Ти хочеш, щоб я доручив тобі важливе замовлення просто тому, що ти тут {стать:з'явився:з'явилася}? Не так все просто, {стать:голодранцю:голодранко}. Майстри зі всього світу шукають роботу на фронті!\n\nЯкщо хочеш отримати замовлення, тобі доведеться показати мені, що ти {стать:готовий:готова} пролити кров. Принеси мені знак доблесті, тоді й поговоримо.\n\nЩоб отримати такий знак, тобі доведеться вбивати.", [3] = "Командир зв'язку Метц з Каплиці Надії Світла, що в Східних Зачумлених землях, хоче, щоб ви принесли йому знак доблесті Сріблястого Світанку.", [4] = "<Командир Метц жує свою сигару.>\n\nЩо таке? Я зайнятий.", [5] = "Гаразд, ось як це працює: за кожен такий знак доблесті я даватиму тобі замовлення. Ти виконуєш його, приносиш його в'юннику Камнелупу. Дійшло? А тепер забирайся звідси.", ["en"] = "They Call Me \"The Rooster\"", ["tasks"] = { ["Argent Dawn Valor Token"] = "знак доблесті Сріблястого Світанку", ["Argent Dawn Valor Token (Provided)"] = "знак доблесті Сріблястого Світанку (видано)" } },
    [9142] = { [1] = "Замовлення майстра", [4] = "Ти знаєш правила, дитя. За один знак доблесті ти отримаєш замовлення майстра.", [5] = "Ти отримуєш, на що заслуговуєш. А тепер не жалійся на свої накази. Або виконуй їх, або знищ.", ["en"] = "Craftsman's Writ", ["tasks"] = { ["Argent Dawn Valor Token"] = "знак доблесті Сріблястого Світанку", ["Argent Dawn Valor Token (Provided)"] = "знак доблесті Сріблястого Світанку (видано)" } },
    [915] = { [1] = "Морозиво...", [2] = "МОРОЗИВО! О, будь ласка, будь ласка, можеш купити мені морозиво?! Якщо і є у світі щось краще за полуничне морозиво Тіґуля, то я такого не знаю! Це моє улюблене морозиво на цілому світі!\n\nЯ колись дуже давно спробував його на трасі Мерехтливих рівнин, але я чув, що його можуть продавати у місті! Будь ласка! Будь ласочка!", [3] = "Купіть полуничне морозиво для свого підопічного. Хлопець, схоже, віддає перевагу морозиву Тіґуля.", [4] = "Хотілося б, щоб вони робили більше смаків морозива, окрім полуничного, але, мабуть, мені пощастило, що полуничне — моє улюблене!", [5] = "Ммммммммм! Я обожнюю це полуничне морозиво! Якщо Тіґуль щось і вміє, так це робити морозиво!\n\nДуже дякую, {ім'я}, — це найкращий смаколик у світі!", ["en"] = "You Scream, I Scream...", ["tasks"] = { ["Tigule and Foror's Strawberry Ice Cream"] = "Полуничне морозиво від Тігуле та Форора", ["Tigule and Foror's Strawberry Ice Cream (Provided)"] = "Полуничне морозиво від Тігуле та Форора (видано)", ["Tigule and Foror's Strawberry Ice Cream slain"] = "Полуничне морозиво від Тігуле та Форора: убито" } },
    [9153] = { [1] = "Під тінню", [2] = "Летючі некрополі Скари заполонили землі як Орди, так і Альянсу. Тінь летючих фортець впала на Танаріс, Спустошені землі, Зимоключ та Палаючий степ.\n\nЛише спільними зусиллями ми зможемо протистояти їм.\n\nНекрополі підтримуються магічними колами, що розміщені в різних точках захоплених територій. Ми дізналися, що якщо знищити купу бездумних невмерлих, що оточують ці кола, захист їх буде послаблено.", [3] = "Перевірте свою карту, щоб знайти місця, які знаходяться під нападом Скари. Відправляйтеся туди та відбийте атаку, розгромившии війська Скари. Віддайте 10 некротичних рун командиру Томасу Гелерану у Каплиці Надії Світла, що в Східних Зачумлених землях.", [4] = "Знадобиться деякий час, щоб перемогти цю загрозу. Як твої успіхи, {ім'я}?", [5] = "Ти добре {стать:впорався:впоралася}, {ім'я:к}. Завдяки таким невеликим перемогам ми знищимо нову загрозу Скари.\n\nВідпочинь та віднови свої сили, але потім ти маєш знову вирушити на фронт, щоб ми не втратили те, що захистили сьогодні.\n\nЩоб допомогти у твоїх подальших битвах, ми надамо тобі доступ до наших особливих предметів, які ти зможеш придбати за некротичні руни.", ["en"] = "Under the Shadow", ["tasks"] = { ["Necrotic Rune"] = "некротична руна", ["Necrotic Rune (Provided)"] = "некротична руна (видано)" } },
    [9154] = { [1] = "Каплиця Надії Світла", [2] = "Скара повернулася, і тепер її набагато більше, ніж будь-коли раніше. Сріблястий Світанок збирає всіх, хто може і бажає взятися за зброю для захисту наших земель.\n\nЯкщо ти бажаєш долучитися — віднеси цей документ Архіваріусу у Каплицю Надії Світла, що в Східних Зачумлених землях.", [3] = "Віднесіть оголошення про заклик до зброї Архіваріусу в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Ти тут, щоб приєднатися до нашого ордену, чи не так?", [5] = "Сріблястий Світанок звернувся з закликом про допомогу, і ти — серед тих, хто відгукнувся на цей заклик. У нас немає часу, щоб займатися тренуваннями. Ми віримо у твої здібності та в те, що ти допоможеш нам відбити загрозу Скари.", ["en"] = "Light's Hope Chapel", ["tasks"] = { ["Call to Arms Announcement"] = "оголошення про заклик до зброї", ["Call to Arms Announcement (Provided)"] = "оголошення про заклик до зброї (видано)" } },
    [9165] = { [1] = "Подяка за супровід", [2] = "Без допомоги мандрівників, мій караван ніколи б не дістався сюди. Скара вилазить звідусіль, щоб завадити нам дістатися сюди.\n\n<Вартовий Дідьє витирає чоло.>\n\nТепер нам треба дочекатися фельдмаршала Чамберса. Він підпише тобі подяку за супровід, яку ти маєш віднести до командира Метца в Каплицю Надії Світла.\n\nІ ще, {ім'я}, слідкуй за тим, що говориш Чамберсу. Він з тих, хто може й голову тобі відірвати... За винятком того, що він дійсно може це зробити...", [3] = "Доставте підписану подяку за супровід до командира зв'язку Метца в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Ім'я, звання, порядковий номер!", [5] = "<Командир зв'язку Метц бере подяку та підписує її.>\n\nПрекрасна робота, {ім'я}. Навіть неперевершена! Візьми це на знак нашої дяки.", ["en"] = "Writ of Safe Passage", ["tasks"] = { ["Writ of Safe Passage"] = "подяка за супровід", ["Writ of Safe Passage (Provided)"] = "подяка за супровід (видано)", ["Writ of Safe Passage Signed"] = "Підписано ордер на безпечний прохід", ["Writ of Safe Passage Signed (Provided)"] = "Підписано ордер на безпечний прохід (видано)", ["Writ of Safe Passage Signed slain"] = "Підписано ордер на безпечний прохід: убито" } },
    [917] = { [1] = "Яйце павутиннолісих", [2] = "Оскільки в мене вже є отрута павуків, я б хотів повивчати живі зразки. На жаль, виловлення живого величезного павука понад те, що я можу в тебе попросити, {стать:юний:юна} {клас:к}. Тим більше, величезний павук також понад те, з чим я міг би самотужки справитися!\n\nАле якщо ти зможеш знайти для мене невилуплене яйце, то процес вирощення зразків значно спроститься, і я потім зможу втримувати невилуплених павуків.\n\nОдне з гнізд повинне бути глибоко в печері Тіненитки. Будь ласка, пошукай там яйце та повертайся з ним до мене.", [3] = "Принесіть яйце павутиннолісих до Ґілшалана в Альдрассіль.", [4] = "Ти вже {стать:був:була} всередині печери Тіненитки, {Ім'я}? {стать:Знайшов:Знайшла} павучине яйце?", [5] = "О, чудово. Я передам це яйце й отруту до Дарнаса, і повернуся туди сам після завершення моїх досліджень тут. Я сподіваюся дізнатися багато нового з цих зразків, {Ім'я}. Ти мені дуже {стать:допоміг:допомогла}.", ["en"] = "Webwood Egg", ["tasks"] = { ["Webwood Egg"] = "яйце павутиннолісих", ["Webwood Egg (Provided)"] = "яйце павутиннолісих (видано)" } },
    [91723] = { [1] = "Делікатні інструменти", [2] = "Хай йому й кінець! Щоразу, коли я намагаюся відкалібрувати ці чутливі таємничі інструменти, їх знову збиває з пантелику сплеск енергії.\nЗдається, сплески йдуть з півночі, де ці первісні кобольди практикували свою грубу магію. Чи не могли б ви позбутися деяких із них, щоб я міг продовжити свою роботу?", [3] = "Убийте 8 кобольдів-геомантів у шахті Ясперлоуд, а потім поверніться до Геміша Бергворта у Вежу Азори.", ["en"] = "Delicate Instruments", ["tasks"] = { ["Kobold Geomancer"] = "кобольд-геомант", ["Kobold Geomancer slain"] = "кобольд-геомант: убито" } },
    [91724] = { [1] = "Делікатні інструменти", [2] = "Майже на місці, і... Присягаюся Нижнім світом! Щось досі руйнує роботу моїх інструментів.\nЦе дуже дратує, {ім'я}. Я чув чутки, що місцеві бандити практикують заклинання біля озера Кам'яна Керн. Можливо, якщо ви їх зупините, ці перешкоди нарешті припиняться, і я зможу трохи попрацювати?", [3] = "Убийте 6 чарівників-розбійників з родини Дефіас на озері Кам'яна піраміда, а потім поверніться до Геміша Бергворта у Вежу Азори.", ["en"] = "Delicate Instruments", ["tasks"] = { ["Defias Rogue Wizard"] = "чарівник-пройдисвіт Непокірних", ["Defias Rogue Wizard slain"] = "чарівник-пройдисвіт Непокірних: убито" } },
    [91725] = { [1] = "Вкрадені приналежності для зачарування", [2] = "Мене послав майстер Теокрит, щоб забрати деякі чарівні припаси з торгового посту, але на зворотному шляху мене влаштувала зграя гнолів!\n\nЯ впустив пакунок і втік, але якщо я повернуся без нього, то мені доведеться тижнями прибирати після експериментів з поліморфами як покарання! Як думаєш, ти зможеш знайти для мене припаси?", [3] = "Зберіть 5 викрадених припасів для зачарування з таборів гнолів навколо озера Кам'яна Керн, а потім поверніться до Бліксі Фіцвінк біля Вежі Азори.", ["en"] = "Stolen Enchanting Supplies", ["tasks"] = { ["Stolen Enchanting Supplies"] = "Вкрадені приналежності для зачарування", ["Stolen Enchanting Supplies (Provided)"] = "Вкрадені приналежності для зачарування (видано)", ["Stolen Enchanting Supplies slain"] = "Вкрадені приналежності для зачарування: убито" } },
    [91732] = { [1] = "Хороша сталь", [2] = "Після війни хорошої сталі не вистачає, і наші інструменти від цього постраждали. Шахтарі Джасперлоуда використовували майстерно виготовлені кирки, і я гадаю, що деякі з них досі знаходяться в глибинах шахти. Чи не могли б ви дістати для мене трохи, і я подивлюся, чи можу я використати цю сталь для іншого використання?", [3] = "Зберіть 4 гірничодобувні інструменти з шахти Джасперлоуд, а потім поверніться до Хагар Лоу в лісорубному таборі Іствейл.", ["en"] = "Good Steel", ["tasks"] = { ["Mining Tools"] = "Інструменти для видобутку корисних копалин", ["Mining Tools (Provided)"] = "Інструменти для видобутку корисних копалин (видано)", ["Mining Tools slain"] = "Інструменти для видобутку корисних копалин: убито" } },
    [91733] = { [1] = "Нижче за течією", [2] = "Я віз партію припасів з торгового посту, але мій фургон перекинувся, і припаси впали в річку! Перш ніж я встиг їх спіймати, їх уже змило вниз за течією.\nМіж мурлоками та вовками там, унизу, у мене немає жодного шансу дістати припаси самостійно. Ти здаєшся витривалим типом — як думаєш, зміг би їх для мене знайти?", [3] = "Зберіть заболочену сокиру, заболочену пилку та заболочену скриньку з інструментами, які змило вниз за течією від лісорубного табору Іствейл, а потім поверніться до Орміна Пелфорда.", ["en"] = "Downstream", ["tasks"] = { ["Waterlogged Axe"] = "Замокла сокира", ["Waterlogged Axe (Provided)"] = "Замокла сокира (видано)", ["Waterlogged Axe slain"] = "Замокла сокира: убито", ["Waterlogged Saw"] = "Заболочена пила", ["Waterlogged Saw (Provided)"] = "Заболочена пила (видано)", ["Waterlogged Saw slain"] = "Заболочена пила: убито", ["Waterlogged Toolbox"] = "Заболочений інструментарій", ["Waterlogged Toolbox (Provided)"] = "Заболочений інструментарій (видано)", ["Waterlogged Toolbox slain"] = "Заболочений інструментарій: убито" } },
    [91736] = { [1] = "Епплджек Стілл", ["en"] = "Applejack Still", ["tasks"] = { ["Shiny Red Apple"] = "соковите червоне яблуко" } },
    [91738] = { [1] = "Яблучне частування", ["en"] = "An Apple Treat", ["tasks"] = { ["Thunder Applejack"] = "Громовий яблуневий джек" } },
    [91741] = { [1] = "Обгризена книга", [2] = "<Один із кобольдів упустив цю книгу. Схоже, кобольд намагався її з'їсти.\n\nБрат Пакстон усередині абатства має невелику бібліотеку, яку він підтримує. Книга, мабуть, звідти походить.>", [3] = "Поверніть книгу брату Пакстону.", ["en"] = "Nibbled-On Book", ["tasks"] = { ["Nibbled-On Book"] = "Обгризена книга", ["Nibbled-On Book (Provided)"] = "Обгризена книга (видано)", ["Nibbled-On Book slain"] = "Обгризена книга: убито" } },
    [91743] = { [1] = "Шалені гризуни", [2] = "Ці жахливі кобольди їдять мої книги! Ти маєш їх повернути, перш ніж вони з'їдять усю мою бібліотеку.", [3] = "Заберіть 8 викрадених книг у кобольдів у долині Нортшир та поверніть їх брату Пакстону.", ["en"] = "Rascally Rodents", ["tasks"] = { ["Stolen Book"] = "Вкрадена книга", ["Stolen Book (Provided)"] = "Вкрадена книга (видано)", ["Stolen Book slain"] = "Вкрадена книга: убито" } },
    [91745] = { [1] = "Консультант з гірничої справи", [2] = "Поговоріть з новою ученицею шахтаря, Келсі Фарго. Вона працює прямо біля шахти і, мабуть, бачила, чим займаються кобольди. Можливо, вона зможе навчити вас чогось про гірничодобувну справу, поки ви там працюєте.", [3] = "Поговоріть з Келсі Фарго біля шахти Ехо-Рідж у долині Нортшир.", ["en"] = "Mining Consultant" },
    [91751] = { [1] = "Шорсткі вовчі шкури", [2] = "Шукаєте можливість потренуватися у знятті шкури? Мій чоловік зазвичай допомагає полювати на вовків, але він зайнятий біля абатства. Мені б не завадила допомога зі збором шкурок, щоб завершити замовлення, над якими я працюю.", [3] = "Зніміть шкуру з вовків навколо Елвіннського лісу, щоб отримати 7 грубих вовчих шкур, а потім доставте їх Гелені Пелцкіннер поблизу Голдширу.", ["en"] = "Rough Wolf Pelts", ["tasks"] = { ["Rough Wolf Pelt"] = "Шорстка вовча шкура", ["Rough Wolf Pelt (Provided)"] = "Шорстка вовча шкура (видано)", ["Rough Wolf Pelt slain"] = "Шорстка вовча шкура: убито" } },
    [91752] = { [1] = "Загальна картина", [2] = "Час від часу з'являється кобольд і кричить: «Фото для Нарфа!». Я не знаю, хто такий Нарф. Можливо, один із головних кобольдів у глибині шахти? Б'юся об заклад, у нього вже цілий мішок книг.\n\nІди візьми ці книги та віднеси їх до місцевих правоохоронних органів, маршале Макбрайде. Тобі варто знайти друга, щоб допомогти. Ті кобольди в шахті набагато підліші.", [3] = "Знайдіть мішок книжок з картинками у Блискучого шукача Нарфа. Віднесіть мішок маршалу Макбрайду, що знаходиться всередині абатства Нортшир.", ["en"] = "The Big Picture", ["tasks"] = { ["Sack of \"Picture\" Books"] = "Мішок книжок з картинками", ["Sack of \"Picture\" Books (Provided)"] = "Мішок книжок з картинками (видано)", ["Sack of \"Picture\" Books slain"] = "Мішок книжок з картинками: убито" } },
    [91753] = { [1] = "Чарівний урок", [2] = "Академічна ретельність, звичайно, є важливою для ремесла чарівника, але практична основа може окупитися. Розглянемо, наприклад, скромних кобольдів. Не маючи формальної освіти, вони, тим не менш, демонструють певну вроджену схильність до простих заклинань та чарів.\n\nЗберіть деякі з їхніх воскових фігурок та розберіть чари, пов'язані з ними. Можливо, ви знайдете це зрозумілим.", [3] = "Кітта Вогняний Вітер у Вежі Азори просить вас зібрати 3 Світлих Залишку.\n\nСвітлий Залишок можна отримати, розчарувавши опудала з сирого воску, що випадають з кобольдів-геомантів.", ["en"] = "An Enchanting Lesson", ["tasks"] = { ["Luminous Residue"] = "Світловий залишок" } },
    [91758] = { [1] = "Слідкуй за тим кобольдом!", [2] = "Ти ще не закінчив з цими кобольдами. Ми щойно отримали звістку від Келсі, що кобольд покинув шахту, несучи великий мішок книг. Мені потрібно, щоб ти вистежив цього кобольда, щоб ми могли забрати книги для брата Пакстона.\n\nПоговори з Тордріном Стернблейд. Він новий тренер мисливців, який щойно прибув з Залізогарта. Ти можеш знайти його за абатством, біля стайні. Він може допомогти тобі вистежити цього злодія кобольдів.", [3] = "Поговоріть із Тордріном Стернблейд біля стайні за абатством Нортширу.", ["en"] = "Follow That Kobold!" },
    [91772] = { [1] = "Тссс! Ми полюємо на кобольдів", [2] = "Добре. Візьми цей набір для відстеження кобольдів. Він дозволить тобі відстежити кобольда, про якого турбується маршал Макбрайд.\n\nІди слідами та принеси знайдене маршалу Дугану в Голдшир.\n\nУ мене таке відчуття, що ці шкідники щось задумали за межами Нортширу. Тож тобі знадобиться допомога Дугана.", [3] = "Ідіть слідами кобольдів та повідомте маршалу Дугану в Голдширі про свої знахідки та набір для відстеження кобольдів.", ["en"] = "Shhh! We're Hunting Kobolds", ["tasks"] = { ["Followed Kobold Tracks"] = "Слідував слідами кобольдів", ["Followed Kobold Tracks (Provided)"] = "Слідував слідами кобольдів (видано)", ["Followed Kobold Tracks slain"] = "Слідував слідами кобольдів: убито", ["Kobold Tracking Kit"] = "Комплект для відстеження Kobold", ["Kobold Tracking Kit (Provided)"] = "Комплект для відстеження Kobold (видано)", ["Kobold Tracking Kit slain"] = "Комплект для відстеження Kobold: убито" } },
    [91775] = { [1] = "Повернення книги", [2] = "Поки ви досліджуєте шахту Фаргодіп, спробуйте знайти якусь із книг брата Пакстона, яку можна було б повернути. Зокрема, Пакстона дуже непокоїть книга під назвою «Розваги з елементалями». Він вважає, що навіть кобольд міг би використати її, щоб викликати слугу-елементаля. Будьте обережні, глибини шахти досить небезпечні. Вам слід взяти з собою друзів.\n\nВізьміть цю сумку для книг, щоб захистити книги, коли ви їх знайдете!", [3] = "Знайдіть 6 Загублених книг та «Розваги з елементалями» та поверніть їх маршалу Дугану.\n\nНаданий предмет:", ["en"] = "Book Return", ["tasks"] = { ["Lost Book"] = "Загублена книга", ["Lost Book (Provided)"] = "Загублена книга (видано)", ["Lost Book slain"] = "Загублена книга: убито", ["Picture Book: Fun with Elementals"] = "Книжка з картинками: Розваги з елементалями", ["Picture Book: Fun with Elementals (Provided)"] = "Книжка з картинками: Розваги з елементалями (видано)", ["Picture Book: Fun with Elementals slain"] = "Книжка з картинками: Розваги з елементалями: убито" } },
    [91777] = { [1] = "Рідкісні книги", [2] = "У списку брата Пакстона бракує лише двох книг: «Геомантія для допитливих юних чарівників» та «Пояснення таємниць: магічні речі простими словами».\n\nКобольди, мабуть, віднесли їх до шахти «Джасперлоуд». Будь ласка, знайдіть ці дві книги та поверніть їх брату Пакстону.\n\nАле боюся, що це буде досить небезпечно. Якщо кобольд-«учень» викликав елементаля, хто знає, що може зробити майстер. На вашому місці я б взяв із собою кількох друзів.", [3] = "Знайдіть книги «Геомантія для допитливих юних чарівників» та «Пояснення таємниць: магічні речі простими словами» та поверніть їх братові Пакстону в абатстві Нортшира.", ["en"] = "Rare Books", ["tasks"] = { ["Arcane Explainer: Magical Stuff in Simple Words"] = "Пояснювач таємниць: магічні речі простими словами", ["Arcane Explainer: Magical Stuff in Simple Words (Provided)"] = "Пояснювач таємниць: магічні речі простими словами (видано)", ["Arcane Explainer: Magical Stuff in Simple Words slain"] = "Пояснювач таємниць: магічні речі простими словами: убито", ["Geomancy for Curious Young Wizards"] = "Геомантія для допитливих юних чарівників", ["Geomancy for Curious Young Wizards (Provided)"] = "Геомантія для допитливих юних чарівників (видано)", ["Geomancy for Curious Young Wizards slain"] = "Геомантія для допитливих юних чарівників: убито" } },
    [9178] = { [1] = "Замовлення майстра — масивне грузило", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення КВ-091:\n\n120 масивних грузил.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 120 масивних грузил та замовлення майстра — масивне грузило до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Так, це знадобиться для дробильної зброї піхоти.", ["en"] = "Craftsman's Writ - Dense Weightstone", ["tasks"] = { ["Craftsman's Writ - Dense Weightstone"] = "замовлення майстра — масивне грузило", ["Craftsman's Writ - Dense Weightstone (Provided)"] = "замовлення майстра — масивне грузило (видано)", ["Dense Weightstone"] = "масивне грузило", ["Dense Weightstone (Provided)"] = "масивне грузило (видано)" } },
    [9179] = { [1] = "Замовлення майстра — імперська латна кіраса", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення КВ-428:\n\n3 імперські латні кіраси.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 3 імперські латні кіраси та замовлення майстра — імперська латна кіраса до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Більше броні для військ! Прекрасно, {ім'я}!", ["en"] = "Craftsman's Writ - Imperial Plate Chest", ["tasks"] = { ["Craftsman's Writ - Imperial Plate Chest"] = "замовлення майстра — імперська латна кіраса", ["Craftsman's Writ - Imperial Plate Chest (Provided)"] = "замовлення майстра — імперська латна кіраса (видано)", ["Imperial Plate Chest"] = "імперська латна кіраса", ["Imperial Plate Chest (Provided)"] = "імперська латна кіраса (видано)" } },
    [9181] = { [1] = "Замовлення майстра — вулканічний молот", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення КВ-697:\n\n3 вулканічні молоти.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 3 вулканічні молоти та замовлення майстра — вулканічний молот до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Вони мають добре поєднуватися з цими масивними грузилами, які ми теж збираємо.", ["en"] = "Craftsman's Writ - Volcanic Hammer", ["tasks"] = { ["Craftsman's Writ - Volcanic Hammer"] = "замовлення майстра — вулканічний молот", ["Craftsman's Writ - Volcanic Hammer (Provided)"] = "замовлення майстра — вулканічний молот (видано)", ["Volcanic Hammer"] = "вулканічний молот", ["Volcanic Hammer (Provided)"] = "вулканічний молот (видано)" } },
    [9182] = { [1] = "Замовлення майстра — величезна торієва бойова сокира", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення КВ-6020:\n\n3 величезні торієві бойові сокири.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 3 величезні торієві бойові сокири та замовлення майстра — величезна торієва бойова сокира до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Вони не такі величезні, як я очікував. Ну, хай там як, та угода є угода.", ["en"] = "Craftsman's Writ - Huge Thorium Battleaxe", ["tasks"] = { ["Craftsman's Writ - Huge Thorium Battleaxe"] = "замовлення майстра — величезна торієва бойова сокира", ["Craftsman's Writ - Huge Thorium Battleaxe (Provided)"] = "замовлення майстра — величезна торієва бойова сокира (видано)", ["Huge Thorium Battleaxe"] = "величезна торієва бойова сокира", ["Huge Thorium Battleaxe (Provided)"] = "величезна торієва бойова сокира (видано)" } },
    [9183] = { [1] = "Замовлення майстра — променистий вінець", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення КВ-80:\n\n3 променистих вінця.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 3 променистих вінця та замовлення майстра — променистий вінець до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Я досі не можу повірити, що Метц думає, що наші солдати будуть носити цей мотлох, щоб захиститись від крижаних атак Скари.", ["en"] = "Craftsman's Writ - Radiant Circlet", ["tasks"] = { ["Craftsman's Writ - Radiant Circlet"] = "замовлення майстра — променистий вінець", ["Craftsman's Writ - Radiant Circlet (Provided)"] = "замовлення майстра — променистий вінець (видано)", ["Radiant Circlet"] = "променистий вінець", ["Radiant Circlet (Provided)"] = "променистий вінець (видано)" } },
    [9184] = { [1] = "Замовлення майстра — лиха шкіряна бандана", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ШК-971:\n\n10 лихих шкіряних бандан.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 10 лихих шкіряних бандан та замовлення майстра — лиха шкіряна бандана до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Вони... лихі.", ["en"] = "Craftsman's Writ - Wicked Leather Headband", ["tasks"] = { ["Craftsman's Writ - Wicked Leather Headband"] = "замовлення майстра — лиха шкіряна бандана", ["Craftsman's Writ - Wicked Leather Headband (Provided)"] = "замовлення майстра — лиха шкіряна бандана (видано)", ["Wicked Leather Headband"] = "лиха шкіряна бандана", ["Wicked Leather Headband (Provided)"] = "лиха шкіряна бандана (видано)" } },
    [9185] = { [1] = "Замовлення майстра — накладки з міцної шкіри", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ШК-448:\n\n25 накладок з міцної шкіри.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 25 накладок з міцної шкіри та замовлення майстра — накладки з міцної шкіри до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Накладки з міцної шкіри мають багато застосувань, {ім'я}. Вони призначені НЕ ЛИШЕ для того, щоб укріпляти ними обладунки. Я от використаю їх як підставку для чайника.", ["en"] = "Craftsman's Writ - Rugged Armor Kit", ["tasks"] = { ["Craftsman's Writ - Rugged Armor Kit"] = "замовлення майстра — накладки з міцної шкіри", ["Craftsman's Writ - Rugged Armor Kit (Provided)"] = "замовлення майстра — накладки з міцної шкіри (видано)", ["Rugged Armor Kit"] = "накладки з міцної шкіри", ["Rugged Armor Kit (Provided)"] = "накладки з міцної шкіри (видано)" } },
    [9186] = { [1] = "Замовлення майстра — лихий шкіряний пояс", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ШК-736:\n\n9 лихих шкіряних поясів.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 9 лихих шкіряних поясів та замовлення майстра — лихий шкіряний пояс до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Насправді ці пояси більш лихі, ніж бандани. Знаю, в це важко повірити.", ["en"] = "Craftsman's Writ - Wicked Leather Belt", ["tasks"] = { ["Craftsman's Writ - Wicked Leather Belt"] = "замовлення майстра — лихий шкіряний пояс", ["Craftsman's Writ - Wicked Leather Belt (Provided)"] = "замовлення майстра — лихий шкіряний пояс (видано)", ["Wicked Leather Belt"] = "лихий шкіряний пояс", ["Wicked Leather Belt (Provided)"] = "лихий шкіряний пояс (видано)" } },
    [9187] = { [1] = "Замовлення майстра — рунічні шкіряні штани", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ШК-8485:\n\n4 пари рунічних шкіряних штанів.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 4 пари рунічних шкіряних штанів та замовлення майстра — рунічні шкіряні штани до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Друїди, безумовно, оцінять майстерність, з якою були зроблені ці штани. Вельми вдячний тобі, {клас:к}.", ["en"] = "Craftsman's Writ - Runic Leather Pants", ["tasks"] = { ["Craftsman's Writ - Runic Leather Pants"] = "замовлення майстра — рунічні шкіряні штани", ["Craftsman's Writ - Runic Leather Pants (Provided)"] = "замовлення майстра — рунічні шкіряні штани (видано)", ["Runic Leather Pants"] = "рунічні шкіряні штани", ["Runic Leather Pants (Provided)"] = "рунічні шкіряні штани (видано)" } },
    [9188] = { [1] = "Замовлення майстра — сяйнополотняні штани", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ШВ-95:\n\n6 сяйнополотняних штанів.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 6 сяйнополотняних штанів та замовлення майстра — сяйнополотняні штани до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Нічого собі — та я майже бачу в них своє відображення!", ["en"] = "Craftsman's Writ - Brightcloth Pants", ["tasks"] = { ["Brightcloth Pants"] = "сяйнополотняні штани", ["Brightcloth Pants (Provided)"] = "сяйнополотняні штани (видано)", ["Craftsman's Writ - Brightcloth Pants"] = "замовлення майстра — сяйнополотняні штани", ["Craftsman's Writ - Brightcloth Pants (Provided)"] = "замовлення майстра — сяйнополотняні штани (видано)" } },
