    [9190] = { [1] = "Замовлення майстра — чоботи з рунічного полотна", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ШВ-635:\n\n8 пар чобіт з рунічного полотна.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 8 пар чобіт з рунічного полотна та замовлення майстра — чоботи з рунічного полотна до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "В ім'я бороди Бронзобороди! Ти справді {стать:приніс:принесла} чоботи з рунічного полотна... Схоже, що я програв парі.", ["en"] = "Craftsman's Writ - Runecloth Boots", ["tasks"] = { ["Craftsman's Writ - Runecloth Boots"] = "замовлення майстра — сумка з рунічного полотна", ["Craftsman's Writ - Runecloth Boots (Provided)"] = "замовлення майстра — сумка з рунічного полотна (видано)", ["Runecloth Boots"] = "чоботи з рунічного полотна", ["Runecloth Boots (Provided)"] = "чоботи з рунічного полотна (видано)" } },
    [91900] = { [1] = "Запечатаний ящик", ["en"] = "A Sealed Crate", ["tasks"] = { ["Sealed Journeyman Crate"] = "Запечатаний ящик підмайстра" } },
