    [9191] = { [1] = "Замовлення майстра — сумка з рунічного полотна", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ШВ-9999:\n\n8 сумок з рунічного полотна.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 8 сумок з рунічного полотна та замовлення майстра — сумка з рунічного полотна до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Святий чобіток! Це те, що я думаю? Солдати постійно скаржаться на брак місця для зберігання всього необхідного в польових умовах. Один з них навіть намалював мені діаграму — такий зануда...\n\nЦі сумки мають зменшити ниття солдат.", ["en"] = "Craftsman's Writ - Runecloth Bag", ["tasks"] = { ["Craftsman's Writ - Runecloth Bag"] = "замовлення майстра — сумка з рунічного полотна", ["Craftsman's Writ - Runecloth Bag (Provided)"] = "замовлення майстра — сумка з рунічного полотна (видано)", ["Runecloth Bag"] = "сумка з рунічного полотна", ["Runecloth Bag (Provided)"] = "сумка з рунічного полотна (видано)" } },
    [91920] = { [1] = "Дикі очі", [2] = "Я б не наважився сумніватися в ефективності формул аптекаря Ренферрела, проте я б збрехав, якби сказав, що зілля мало якусь помітну різницю.\n\nВздовж берега озера Лордамер мешкає рій мурлоків, і, що цікаво, у мурлоків є очі. Підозрюю, що готовність аптекаря пробувати щось нове пригнічується його нещодавньою одержимістю серцями. Принесіть йому кілька.\n\nЯкщо мій вибір — неминуче померти другою смертю або Ренферрел уб'є мене за сумнів у його методах, я оберу останнє.", [3] = "Зберіть 3 ока мурлоків і віднесіть їх аптекарю Ренферрелу в Гробниці.", ["en"] = "Wild Eyes", ["tasks"] = { ["Murloc Eye"] = "око мурлока" } },
    [91921] = { [1] = "Повернення до Квінн (Знову)", [2] = "Ось нове зілля, яке допоможе Квінну одужати, приготоване з любов'ю, витягнутою з шести цілих сердець.\n\nА тепер, будь ласка, вибачте мене, бо ваша присутність вимагатиме ще більше паперової роботи.", [3] = "Принесіть зілля Квінна Квінну Йоріку в Іварську ділянку, на північ від Гробниці.", ["en"] = "Return to Quinn (Again)", ["tasks"] = { ["Quinn's Potion"] = "Квіннове зілля", ["Quinn's Potion (Provided)"] = "Квіннове зілля (видано)" } },
    [9194] = { [1] = "Замовлення майстра — вбрання з рунічного полотна", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ШВ-7229:\n\n8 вбрань з рунічного полотна.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 8 вбрань з рунічного полотна та замовлення майстра — вбрання з рунічного полотна до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Ой, не варто було! Ні, справді, не варто. Не знаю, що там Метц собі думає, але ніхто не збирається одягати ці вбрання до Наксрамасу.\n\n<В'юнник Камнелуп позіхає.>\n\nЕх, іще одна купа сміття, яку мені доведеться перти на передову та знову слухати докори від Чамберса.", ["en"] = "Craftsman's Writ - Runecloth Robe", ["tasks"] = { ["Craftsman's Writ - Runecloth Robe"] = "замовлення майстра — вбрання з рунічного полотна", ["Craftsman's Writ - Runecloth Robe (Provided)"] = "замовлення майстра — вбрання з рунічного полотна (видано)", ["Runecloth Robe"] = "вбрання з рунічного полотна", ["Runecloth Robe (Provided)"] = "вбрання з рунічного полотна (видано)" } },
    [9195] = { [1] = "Замовлення майстра — гоблінський саперний заряд", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ІН-11:\n\n20 гоблінських саперних зарядів.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 20 гоблінських саперних зарядів та замовлення майстра — гоблінський саперний заряд до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Отакі речі мені подобаються, {клас:к}. Речі, які роблять БУМ!", ["en"] = "Craftsman's Writ - Goblin Sapper Charge", ["tasks"] = { ["Craftsman's Writ - Goblin Sapper Charge"] = "замовлення майстра — гоблінський саперний заряд", ["Craftsman's Writ - Goblin Sapper Charge (Provided)"] = "замовлення майстра — гоблінський саперний заряд (видано)", ["Goblin Sapper Charge"] = "гоблінський саперний заряд", ["Goblin Sapper Charge (Provided)"] = "гоблінський саперний заряд (видано)" } },
    [9196] = { [1] = "Замовлення майстра — торієва граната", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ІН-7:\n\n20 торієвих гранат.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 20 торієвих гранат та замовлення майстра — торієва граната до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "На ці гранати, певно, пішла купа міді. Я правий, чи да, {ім'я}?", ["en"] = "Craftsman's Writ - Thorium Grenade", ["tasks"] = { ["Craftsman's Writ - Thorium Grenade"] = "замовлення майстра — торієва граната", ["Craftsman's Writ - Thorium Grenade (Provided)"] = "замовлення майстра — торієва граната (видано)", ["Thorium Grenade"] = "торієва граната", ["Thorium Grenade (Provided)"] = "торієва граната (видано)" } },
    [9197] = { [1] = "Замовлення майстра — гномське бойове курча", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ІН-0:\n\n4 гномських бойових курчат.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 4 гномських бойових курчат та замовлення майстра — гномське бойове курча до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Чого ти посміхаєшся? Що тут кумедного? Послухайте-но {стать:пане:пані}, гномські бойові курчата — це дуже важлива річ для нас, а іще їх ДУЖЕ важко знайти. Ми відправляємо цих курчат до сильно заражених зон, де вони знищують всіх зачумлених комах та личинок. Всі знають, що роботи стійкі до чуми.\n\nБ'юся об заклад, тепер ти не відчуваєш себе {стать:таким розумником:такою розумницею}? Дурило...", ["en"] = "Craftsman's Writ - Gnomish Battle Chicken", ["tasks"] = { ["Craftsman's Writ - Gnomish Battle Chicken"] = "замовлення майстра — гномське бойове курча", ["Craftsman's Writ - Gnomish Battle Chicken (Provided)"] = "замовлення майстра — гномське бойове курча (видано)", ["Gnomish Battle Chicken"] = "гномське бойове курча", ["Gnomish Battle Chicken (Provided)"] = "гномське бойове курча (видано)" } },
    [9198] = { [1] = "Замовлення майстра — торієва трубка", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення ІН-558:\n\n14 торієвих трубок.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 14 торієвих трубок та замовлення майстра — торієва трубка до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Торієві трубки? Йой, дякую.\n\n<В'юнник Камнелуп кидає трубки до величезної купи мотлоху.>", ["en"] = "Craftsman's Writ - Thorium Tube", ["tasks"] = { ["Craftsman's Writ - Thorium Tube"] = "замовлення майстра — торієва трубка", ["Craftsman's Writ - Thorium Tube (Provided)"] = "замовлення майстра — торієва трубка (видано)", ["Thorium Tube"] = "торієва трубка", ["Thorium Tube (Provided)"] = "торієва трубка (видано)" } },
    [920] = { [1] = "Поклик Тенарона", [2] = "{Ім'я}, чи не так? Я чув, що Тенарон питався про тебе. Ти знайдеш його у найвищій кімнаті на вершині Альдрассіля.\n\nУ нас, може, й довгі життя, але краще не змушуй його чекати на тебе надто довго.", [3] = "Поговоріть з Тенароном Штормохапом на вершині Альдрассіля у Тінистій долині.", [5] = "А-а, {Ім'я}. Я сподівався, що ти швидко відреагуєш на мій поклик. У мене є для тебе важливе завдання, і я хотів би, щоб ти його {стать:виконав:виконала}.", ["en"] = "Tenaron's Summons" },
    [9200] = { [1] = "Замовлення майстра — величезне зілля мани", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення АЛ-473:\n\n10 величезних зіллів мани.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 10 величезних зіллів мани та замовлення майстра — величезне зілля мани до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Думаю, немає сенсу казати, наскільки вони корисні.", ["en"] = "Craftsman's Writ - Major Mana Potion", ["tasks"] = { ["Craftsman's Writ - Major Mana Potion"] = "замовлення майстра — величезне зілля мани", ["Craftsman's Writ - Major Mana Potion (Provided)"] = "замовлення майстра — величезне зілля мани (видано)", ["Major Mana Potion"] = "величезне зілля мани", ["Major Mana Potion (Provided)"] = "величезне зілля мани (видано)" } },
    [9201] = { [1] = "Замовлення майстра — велике зілля арканічного захисту", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення АЛ-1420:\n\n15 великих зіллів арканічного захисту.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 15 великих зіллів арканічного захисту та замовлення майстра — велике зілля арканічного захисту до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "<В'юнник Камнелуп відкриває одне зілля та робить ковток.>\n\nУХ! Як же воно бадьорить! БРРР! Бадьорить!", ["en"] = "Craftsman's Writ - Greater Arcane Protection Potion", ["tasks"] = { ["Craftsman's Writ - Greater Arcane Protection Potion"] = "замовлення майстра — велике зілля арканічного захисту", ["Craftsman's Writ - Greater Arcane Protection Potion (Provided)"] = "замовлення майстра — велике зілля арканічного захисту (видано)", ["Greater Arcane Protection Potion"] = "велике зілля арканічного захисту", ["Greater Arcane Protection Potion (Provided)"] = "велике зілля арканічного захисту (видано)" } },
    [9202] = { [1] = "Замовлення майстра — величезне зілля лікування", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення АЛ-169110:\n\n20 величезних зіллів лікування.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 20 величезних зіллів лікування та замовлення майстра — величезне зілля лікування до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Знаєш як наші солдати називають це? Жрець у пляшці...\n\n<В'юнник Камнелуп співає.>\n\n\"Я твій жрець у пляшечці, крихітко... Їж мене, пий мене, шаленій...\"\n\nЩо таке, {стать:малий:мала}? Це дуже популярна пісня тут.", ["en"] = "Craftsman's Writ - Major Healing Potion", ["tasks"] = { ["Craftsman's Writ - Major Healing Potion"] = "замовлення майстра — величезне зілля лікування", ["Craftsman's Writ - Major Healing Potion (Provided)"] = "замовлення майстра — величезне зілля лікування (видано)", ["Major Healing Potion"] = "величезне зілля лікування", ["Major Healing Potion (Provided)"] = "величезне зілля лікування (видано)" } },
    [9203] = { [1] = "Замовлення майстра — настій скам'яніння", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення АЛ-90:\n\n1 настій скам'яніння.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 1 настій скам'яніння та замовлення майстра — настій скам'яніння до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Без коментарів.\n\n<В'юнник Камнелуп витріщився на вас.>\n\nЯ сказав — без коментарів! А тепер геть з очей моїх!", ["en"] = "Craftsman's Writ - Flask of Petrification", ["tasks"] = { ["Craftsman's Writ - Flask of Petrification"] = "замовлення майстра — настій скам'яніння", ["Craftsman's Writ - Flask of Petrification (Provided)"] = "замовлення майстра — настій скам'яніння (видано)", ["Flask of Petrification"] = "настій скам'яніння", ["Flask of Petrification (Provided)"] = "настій скам'яніння (видано)" } },
    [9204] = { [1] = "Замовлення майстра — камнелуский вугор", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення РЛ-5:\n\n40 камнелуских вугрів.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 40 камнелуских вугрів та замовлення майстра — камнелуский вугор до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Ти {стать:міг:могла} використати їх для чогось іншого, але ти цього не {стать:зробив:зробила}, ге? Та вже пізно шкодувати, {ім'я}.", ["en"] = "Craftsman's Writ - Stonescale Eel", ["tasks"] = { ["Craftsman's Writ - Stonescale Eel"] = "замовлення майстра — камнелуский вугор", ["Craftsman's Writ - Stonescale Eel (Provided)"] = "замовлення майстра — камнелуский вугор (видано)", ["Stonescale Eel"] = "камнелуский вугор", ["Stonescale Eel (Provided)"] = "камнелуский вугор (видано)" } },
    [9205] = { [1] = "Замовлення майстра — риба-броненосець", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення РЛ-12:\n\n30 риб-броненосців.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 30 риб-броненосців та замовлення майстра — риба-броненосець до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "Ти дійсно не знаєш, для чого вона знадобиться?\n\n<В'юнник Камнелуп регоче.>\n\nДзуськи я тобі скажу!", ["en"] = "Craftsman's Writ - Plated Armorfish", ["tasks"] = { ["Craftsman's Writ - Plated Armorfish"] = "замовлення майстра — риба-броненосець", ["Craftsman's Writ - Plated Armorfish (Provided)"] = "замовлення майстра — риба-броненосець (видано)", ["Plated Armorfish"] = "риба-броненосець", ["Plated Armorfish (Provided)"] = "риба-броненосець (видано)" } },
    [9206] = { [1] = "Замовлення майстра — блискавковий вугор", [2] = "Пред'явник цього замовлення має право на отримання оплати у вигляді відзнаки за власним вибором після виконання роботи.\n\nЗамовлення РЛ-9:\n\n30 блискавкових вугрів.\n\nВиконане замовлення має бути доставлене в'юннику Камнелупу в каплицю Надії Світла, що в Східних Зачумлених землях.\n\nЗамовлення недійсне, якщо його підроблено або пошкоджено.\n\n-Командир зв'язку Метц, Сріблястий Світанок", [3] = "Доставте 30 блискавкових вугрів та замовлення майстра — блискавковий вугор до в'юнника Камнелупа в каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Хочеш здати виконане замовлення, {клас:к}?", [5] = "З цих вугрів виходять найкращі роли у світі. Так-так, У СВІТІ.", ["en"] = "Craftsman's Writ - Lightning Eel", ["tasks"] = { ["Craftsman's Writ - Lightning Eel"] = "замовлення майстра — блискавковий вугор", ["Craftsman's Writ - Lightning Eel (Provided)"] = "замовлення майстра — блискавковий вугор (видано)", ["Lightning Eel"] = "блискавковий вугор", ["Lightning Eel (Provided)"] = "блискавковий вугор (видано)" } },
    [9208] = { [1] = "Захист джунглів — магічний камінь захисту", [2] = "Занза може створити багато стародавніх чарів тролів з відповідними компонентами! Чи ти коли-небудь {стать:чув:чула} про захист джунглів? Ні, звичайно ж, ні. Твій розум затьмарений жалюгідною ельфійською магією.\n\nПринеси мені магічний камінь ельфійської роботи. Тоді я дам тобі захист джунглів, і ти побачиш, що таке справжня магія!", [3] = "Занза Неупокоєний з Зул'Ґуруба хоче отримати магічний камінь захисту.", [4] = "Ти {стать:приніс:принесла} магічний камінь?", [5] = "Нікчемна магія в цих чарах підживлює мою злість. А моя злість дає мені силу.\n\nПринеси мені ще, і отримаєш новий захист джунглів.", ["en"] = "The Savage Guard - Arcanum of Protection", ["tasks"] = { ["Arcanum of Protection"] = "магічний камінь захисту", ["Arcanum of Protection (Provided)"] = "магічний камінь захисту (видано)" } },
    [9209] = { [1] = "Захист джунглів — магічний камінь прудкості", [2] = "Занза може створити багато стародавніх чарів тролів з відповідними компонентами! Чи ти коли-небудь {стать:чув:чула} про захист джунглів? Ні, звичайно ж, ні. Твій розум затьмарений жалюгідною ельфійською магією.\n\nПринеси мені магічний камінь ельфійської роботи. Тоді я дам тобі захист джунглів, і ти побачиш, що таке справжня магія!", [3] = "Занза Неупокоєний з Зул'Ґуруба хоче отримати магічний камінь прудкості.", [4] = "Ти {стать:приніс:принесла} магічний камінь?", [5] = "Нікчемна магія в цих чарах підживлює мою злість. А моя злість дає мені силу.\n\nПринеси мені ще, і отримаєш новий захист джунглів.", ["en"] = "The Savage Guard - Arcanum of Rapidity", ["tasks"] = { ["Arcanum of Rapidity"] = "магічний камінь прудкості", ["Arcanum of Rapidity (Provided)"] = "магічний камінь прудкості (видано)" } },
    [9210] = { [1] = "Захист джунглів — магічний камінь зосередження", [2] = "Занза може створити багато стародавніх чарів тролів з відповідними компонентами! Чи ти коли-небудь {стать:чув:чула} про захист джунглів? Ні, звичайно ж, ні. Твій розум затьмарений жалюгідною ельфійською магією.\n\nПринеси мені магічний камінь ельфійської роботи. Тоді я дам тобі захист джунглів, і ти побачиш, що таке справжня магія!", [3] = "Занза Неупокоєний з Зул'Ґуруба хоче отримати магічний камінь зосередження.", [4] = "Ти {стать:приніс:принесла} магічний камінь?", [5] = "Нікчемна магія в цих чарах підживлює мою злість. А моя злість дає мені силу.\n\nПринеси мені ще, і отримаєш новий захист джунглів.", ["en"] = "The Savage Guard - Arcanum of Focus", ["tasks"] = { ["Arcanum of Focus"] = "магічний камінь зосередження", ["Arcanum of Focus (Provided)"] = "магічний камінь зосередження (видано)" } },
    [9211] = { [1] = "Крижаний захист", [2] = "Крижаний захист — це тоненький шар захисної магії, що накладається на певні частини спорядження. Завдяки цьому посилюється захист від атак крижаних створінь.\n\nОднак все, що створює Гнівоклят, має свою ціну — ціну, яку я не знижу, скільки б ти не {стать:скиглив:скиглила}. Ну що, цікавить?", [3] = "Матаус Гнівоклят з Каплиці Надії Світла, що в Східних Зачумлених землях, просить вас принести йому 10 відзнак Багряного Походу та 30 золотих.", [4] = "Якби не Сріблястий Світанок, від тебе й мокрого місця не залишилося б.", [5] = "<Матаус ховає золото.>\n\nНасолоджуйся витратами на ремонт, {раса:к}. В Наксрамасі не люблять чужинців.", ["en"] = "The Ice Guard", ["tasks"] = { ["Insignia of the Crusade"] = "відзнака Багряного Походу", ["Insignia of the Crusade (Provided)"] = "відзнака Багряного Походу (видано)" } },
    [92124] = { [1] = "Інвентаризація книг", [2] = "Нам потрібно підрахувати, скільки книг зникло!\n\nПоговоріть з моїм нікчемним помічником, Даніелем. Він може швидко провести інвентаризацію та повідомити нам, наскільки серйозна проблема.\n\nВін одержимий різними торговими професіями в Елвіннському лісі. Хлопець постійно зосереджується на них, замість того, щоб займатися своєю важливою роботою – допомагати мені.\n\nНе дозволяйте йому базікати про торгові навички, і дізнайтеся, що сталося з моїми книгами!", [3] = "Поговоріть з Даніелем, помічником брата Пакстона в бібліотеці.", ["en"] = "Book Inventory" },
    [9213] = { [1] = "Тіньовий захист", [2] = "Геніальний витвір! Так само як і крижаний захист, тіньовий захист накладає тоненький шар захисної магії на певні частини спорядження. І так само як і крижаний захист, він буде коштувати тобі багацько грошей.\n\n<Матаус простягає руку й потирає пальці.>\n\n{стать:Зацікавлений:Зацікавлена}?", [3] = "Матаус Гнівоклят з Каплиці Надії Світла, що в Східних Зачумлених землях, просить вас принести йому 10 відзнак Багряного Походу та 30 золотих.", [4] = "<Матаус позіхає.>\n\nЧухай звідси, комахо, як нічого не купуєш.", [5] = "<Матаус ховає золото під мантію.>\n\nЧого ти тут стоїш, {раса:к}? Моя справа зроблена.", ["en"] = "The Shadow Guard", ["tasks"] = { ["Insignia of the Crusade"] = "відзнака Багряного Походу", ["Insignia of the Crusade (Provided)"] = "відзнака Багряного Походу (видано)" } },
    [9221] = { [1] = "Чудове бойове спорядження — дружба Світанку", [2] = "Вітаю, {стать:друже:подруго}. Бажаєш обміняти свої відзнаки Багряного Походу або Світанку на бойове спорядження?\n\nЯ мушу попередити тебе — навіть друзям Світанку доведеться заплатити за них чималу ціну. Тож раджу тобі заслужити кращу репутацію серед Сріблястого Світанку.", [3] = "За 30 відзнак Світанку та 30 відзнак Багряного Походу ви зможете обрати собі предмет зі скарбниці Сріблястого Світанку.", [4] = "Обирай з розумом. Товар поверненню не підлягає.", [5] = "Вдалого дня, {ім'я}! Приємно мати з тобою справу.", ["en"] = "Superior Armaments of Battle - Friend of the Dawn", ["tasks"] = { ["Insignia of the Crusade"] = "відзнака Багряного Походу", ["Insignia of the Crusade (Provided)"] = "відзнака Багряного Походу (видано)", ["Insignia of the Dawn"] = "відзнака Світанку", ["Insignia of the Dawn (Provided)"] = "відзнака Світанку (видано)" } },
    [9222] = { [1] = "Епічне бойове спорядження — дружба Світанку", [2] = "Вітаю, {стать:друже:подруго}. Бажаєш обміняти свої відзнаки Багряного Походу або Світанку на потужне бойове спорядження?\n\nЯ мушу попередити тебе — навіть друзям Світанку доведеться заплатити за них чималу ціну. Тож раджу тобі заслужити кращу репутацію серед Сріблястого Світанку.", [3] = "За 110 відзнак Світанку та 110 відзнак Багряного Походу ви зможете обрати собі предмет зі скарбниці Сріблястого Світанку.", [4] = "Обирай з розумом. Товар поверненню не підлягає.", [5] = "Вдалого дня, {ім'я}! Приємно мати з тобою справу.", ["en"] = "Epic Armaments of Battle - Friend of the Dawn", ["tasks"] = { ["Insignia of the Crusade"] = "відзнака Багряного Походу", ["Insignia of the Crusade (Provided)"] = "відзнака Багряного Походу (видано)", ["Insignia of the Dawn"] = "відзнака Світанку", ["Insignia of the Dawn (Provided)"] = "відзнака Світанку (видано)" } },
    [9223] = { [1] = "Чудове бойове спорядження — почесть Світанку", [2] = "Вітаю, {стать:друже:подруго}. Бажаєш обміняти свої відзнаки Багряного Походу або Світанку на бойове спорядження?\n\nЯ мушу попередити тебе — навіть за почесної репутації серед Світанку тобі доведеться заплатити за них чималу ціну. Тож раджу тобі заслужити кращу репутацію Сріблястого Світанку.", [3] = "За 20 відзнак Світанку та 20 відзнак Багряного Походу ви зможете обрати собі предмет зі скарбниці Сріблястого Світанку.", [4] = "Обирай з розумом. Товар поверненню не підлягає.", [5] = "Вдалого дня, {ім'я}! Приємно мати з тобою справу.", ["en"] = "Superior Armaments of Battle - Honored Amongst the Dawn", ["tasks"] = { ["Insignia of the Crusade"] = "відзнака Багряного Походу", ["Insignia of the Crusade (Provided)"] = "відзнака Багряного Походу (видано)", ["Insignia of the Dawn"] = "відзнака Світанку", ["Insignia of the Dawn (Provided)"] = "відзнака Світанку (видано)" } },
    [9224] = { [1] = "Епічне бойове спорядження — почесть Світанку", [2] = "Вітаю, {стать:друже:подруго}. Бажаєш обміняти свої відзнаки Багряного Походу або Світанку на потужне бойове спорядження?\n\nЯ мушу попередити тебе — навіть за почесної репутації серед Світанку тобі доведеться заплатити за них чималу ціну. Тож раджу тобі заслужити кращу репутацію Сріблястого Світанку.", [3] = "За 75 відзнак Світанку та 75 відзнак Багряного Походу ви зможете обрати собі предмет зі скарбниці Сріблястого Світанку.", [4] = "Обирай з розумом. Товар поверненню не підлягає.", [5] = "Вдалого дня, {ім'я}! Приємно мати з тобою справу.", ["en"] = "Epic Armaments of Battle - Honored Amongst the Dawn", ["tasks"] = { ["Insignia of the Crusade"] = "відзнака Багряного Походу", ["Insignia of the Crusade (Provided)"] = "відзнака Багряного Походу (видано)", ["Insignia of the Dawn"] = "відзнака Світанку", ["Insignia of the Dawn (Provided)"] = "відзнака Світанку (видано)" } },
    [9225] = { [1] = "Епічне бойове спорядження — шанованість Світанку", [2] = "Вітаю, {стать:друже:подруго}. Бажаєш обміняти свої відзнаки Багряного Походу або Світанку на потужне бойове спорядження?\n\nЯ мушу попередити тебе — навіть за шанованості серед Світанку тобі доведеться заплатити за них чималу ціну. Тож раджу тобі заслужити кращу репутацію Сріблястого Світанку.", [3] = "За 45 відзнак Світанку та 45 відзнак Багряного Походу ви зможете обрати собі предмет зі скарбниці Сріблястого Світанку.", [4] = "Обирай з розумом. Товар поверненню не підлягає.", [5] = "Вдалого дня, {ім'я}! Приємно мати з тобою справу.", ["en"] = "Epic Armaments of Battle - Revered Amongst the Dawn", ["tasks"] = { ["Insignia of the Crusade"] = "відзнака Багряного Походу", ["Insignia of the Crusade (Provided)"] = "відзнака Багряного Походу (видано)", ["Insignia of the Dawn"] = "відзнака Світанку", ["Insignia of the Dawn (Provided)"] = "відзнака Світанку (видано)" } },
    [9226] = { [1] = "Чудове бойове спорядження — шанованість Світанку", [2] = "Вітаю, {стать:друже:подруго}. Бажаєш обміняти свої відзнаки Багряного Походу або Світанку на бойове спорядження?\n\nТі, кого шанують у Срібному Світанку, отримують непогані знижки. Прошу, обирай.", [3] = "За 7 відзнак Світанку та 7 відзнак Багряного Походу ви зможете обрати собі предмет зі скарбниці Сріблястого Світанку.", [4] = "Обирай з розумом. Товар поверненню не підлягає.", [5] = "Вдалого дня, {ім'я}! Приємно мати з тобою справу.", ["en"] = "Superior Armaments of Battle - Revered Amongst the Dawn", ["tasks"] = { ["Insignia of the Crusade"] = "відзнака Багряного Походу", ["Insignia of the Crusade (Provided)"] = "відзнака Багряного Походу (видано)", ["Insignia of the Dawn"] = "відзнака Світанку", ["Insignia of the Dawn (Provided)"] = "відзнака Світанку (видано)" } },
    [9227] = { [1] = "Чудове бойове спорядження — возвеличення Світанку", [2] = "Вітаю, {стать:друже:подруго}. Бажаєш обміняти свої відзнаки Багряного Походу або Світанку на бойове спорядження?\n\nТі, кого звеличують у Срібному Світанку, отримують найбільші знижки! Прошу, обирай.", [3] = "За 6 відзнак Світанку та 6 відзнак Багряного Походу ви зможете обрати собі предмет зі скарбниці Сріблястого Світанку.", [4] = "Обирай з розумом. Товар поверненню не підлягає.", [5] = "Вдалого дня, {ім'я}! Приємно мати з тобою справу.", ["en"] = "Superior Armaments of Battle - Exalted Amongst the Dawn", ["tasks"] = { ["Insignia of the Crusade"] = "відзнака Багряного Походу", ["Insignia of the Crusade (Provided)"] = "відзнака Багряного Походу (видано)", ["Insignia of the Dawn"] = "відзнака Світанку", ["Insignia of the Dawn (Provided)"] = "відзнака Світанку (видано)" } },
    [9228] = { [1] = "Епічне бойове спорядження — возвеличення Світанку", [2] = "Вітаю, {стать:друже:подруго}. Бажаєш обміняти свої відзнаки Багряного Походу або Світанку на потужне бойове спорядження?\n\nТі, кого звеличують у Срібному Світанку, отримують найбільші знижки! Прошу, обирай.", [3] = "За 27 відзнак Світанку та 27 відзнак Багряного Походу ви зможете обрати собі предмет зі скарбниці Сріблястого Світанку.", [4] = "Обирай з розумом. Товар поверненню не підлягає.", [5] = "Вдалого дня, {ім'я}! Приємно мати з тобою справу.", ["en"] = "Epic Armaments of Battle - Exalted Amongst the Dawn", ["tasks"] = { ["Insignia of the Crusade"] = "відзнака Багряного Походу", ["Insignia of the Crusade (Provided)"] = "відзнака Багряного Походу (видано)", ["Insignia of the Dawn"] = "відзнака Світанку", ["Insignia of the Dawn (Provided)"] = "відзнака Світанку (видано)" } },
    [9229] = { [1] = "Доля Рамаладні", [2] = "Рамаладні був воїном нашого братства та учнем лорда Могрейна ще до заснування Світанку! Коли він дізнався про смерть Могрейна, гнів та ненависть оповили його.\n\nЗрозумій, {ім'я}, коли гнів та жага помсти беруть вверх, людина перестає бути людиною. Людина уособлює емоції, які нею керують. І тому Рамаладні, дух відплати, пішов в Наксрамас, щоб помститися... але він не повернувся.\n\nЙди до Наксрамасу та знайти те, що колись раніше було Рамаладні.", [3] = "Увійдіть у Наксрамас та дізнайтеся долю Рамаладні.", [4] = "Є якісь новини про Рамаладні?", [5] = "Це його перстень! Але він зламаний. Ти не {стать:знайшов:знайшла} інших слідів Рамаладні?\n\n<Корфакс морщиться.>\n\nНе найкраща звістка про його долю. А перстень... можливо, його вдасться відновити.", ["en"] = "The Fate of Ramaladni", ["tasks"] = { ["Fate of Ramaladni"] = "доля Рамаладні", ["Fate of Ramaladni (Provided)"] = "доля Рамаладні (видано)" } },
    [9230] = { [1] = "Крижана хватка Рамаладні", [2] = "Відновити цей перстень буде ще тою задачею, {ім'я}. Розумієш, воно він створений з тих самих рун, які можна знайти в спорудах Скари. Наприклад, в Наксрамасі. Також знадобляться деякі додаткові матеріали, але твоєю головною метою є збір морозних рун. Принеси мені все, що мені потрібно, і я поверну персню його колишню славу.", [3] = "Корфакс з Каплиці Надії Світла, що в Східних Зачумлених землях, просить вас принести йому морозну руну, синій сапфір та злиток арканіту.", [4] = "Морозні руни можна знайти в Наксрамасі.", [5] = "Сам Рамаладні не зміг би зробити краще! Ось перстень, як я й обіцяв.", ["en"] = "Ramaladni's Icy Grasp", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Blue Sapphire"] = "синій сапфір", ["Blue Sapphire (Provided)"] = "синій сапфір (видано)", ["Frozen Rune"] = "морозна руна", ["Frozen Rune (Provided)"] = "морозна руна (видано)" } },
    [9232] = { [1] = "Це все, що я можу...", [2] = "Вважаєш себе {стать:героєм:героїнею} Сріблястого Світанку, ге? Я бачив, як летіли голови наших найкращих солдатів під тиском Кел'Тузадських покидьків! Я не розумію, як така нездара, як ти, може ходити в Наксрамас?\n\n<Вільгельм зітхає.>\n\nА хіба у мене є вибір? Все ж я можу тобі допомогти.\n\nОмаріон лишив мені всього одне креслення. Це все, що я можу... Ось кілька варіантів поножів на вибір — ти тільки принеси матеріали.", [3] = "Ремісник Вільгельм з Каплиці Надії Світла, що в Східних Зачумлених землях, просить вас принести йому 2 морозні руни, 2 сутності води, 2 синіх сапфіри та 30 золотих.", [4] = "Ти не {стать:натрапив:натрапила} на Омаріона?", [5] = "<Вільгельм протирає чоло від поту.>\n\nЦе важка робота! Насолоджуйся штанцями, {клас:к}. Принаймні, ти помреш у нових поножах.", ["en"] = "The Only Song I Know...", ["tasks"] = { ["Blue Sapphire"] = "синій сапфір", ["Blue Sapphire (Provided)"] = "синій сапфір (видано)", ["Essence of Water"] = "сутність води", ["Essence of Water (Provided)"] = "сутність води (видано)", ["Frozen Rune"] = "морозна руна", ["Frozen Rune (Provided)"] = "морозна руна (видано)" } },
    [9233] = { [1] = "Довідник Омаріона", [2] = "Вільгельм,\n\nЯкщо ти це читаєш — я нарешті загинув. Я хочу, щоб ти знав, що перед смертю я думав лиш про те, що ти найбездарніший ремісник. На жаль, ті, хто принесуть тобі цей довідник, цілком можуть відібрати в тебе це звання.\n\nЩо стосується цієї книги — тут решта моїх рецептів. Зроби для тих, хто принесе її, все, чого вони попросять. І я впевнений, що ти візьмеш велику плату за свої послуги, адже ти, зрештою, справжня скотиняка.\n\nЗі щирим презирством,\n\nОмаріон", [3] = "Віднесіть довідник Омаріона реміснику Вільгельму в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Це те, про що я думаю?\n\n<У Вільгельма тече слина.>", [5] = "Схоже, що він був не у сво'му розумі, коли писав це! Ми з Омаріоном були друзі нерозлийвода!\n\nХай там як, {ім'я}, ця книга відкриває переді мною нові можливості. Тепер я можу створювати нові речі — за матеріали та невеличку плату.", ["en"] = "Omarion's Handbook", ["tasks"] = { ["Omarion's Handbook"] = "довідник Омаріона", ["Omarion's Handbook (Provided)"] = "довідник Омаріона (видано)" } },
    [9234] = { [1] = "Рукавиці крижаної гибелі", [2] = "Дякуючи тобі та Омаріону, царство йому небесне, я тепер зможу створити рукавиці крижаної гибелі. Все, що тобі потрібно буде зробити, це принести мені матеріали та заплатити невеличкий гонорар за виготовлення.", [3] = "Ремісник Вільгельм з Каплиці Надії Світла, що в Східних Зачумлених землях, просить вас принести 5 морозних рун, 12 злитків торію, 2 злитки арканіту, 2 сутності води та 200 золотих.", [4] = "Ти {стать:приніс:принесла} матеріали?", [5] = "Ось твоє замовлення, {ім'я}. Виконане, як і обіцяно!", ["en"] = "Icebane Gauntlets", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Essence of Water"] = "сутність води", ["Essence of Water (Provided)"] = "сутність води (видано)", ["Frozen Rune"] = "морозна руна", ["Frozen Rune (Provided)"] = "морозна руна (видано)", ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
    [9235] = { [1] = "Браслети крижаної гибелі", [2] = "Дякуючи тобі та Омаріону, царство йому небесне, я тепер зможу створити браслети крижаної гибелі. Все, що тобі потрібно буде зробити, це принести мені матеріали та заплатити невеличкий гонорар за виготовлення.", [3] = "Ремісник Вільгельм з Каплиці Надії Світла, що в Східних Зачумлених землях, просить вас принести 4 морозні руни, 12 злитків торію, 2 злитки арканіту, 2 сутності води та 200 золотих.", [4] = "Ти {стать:приніс:принесла} матеріали?", [5] = "Ось твоє замовлення, {ім'я}. Виконане, як і обіцяно!", ["en"] = "Icebane Bracers", ["tasks"] = { ["Arcanite Bar"] = "злиток арканіту", ["Arcanite Bar (Provided)"] = "злиток арканіту (видано)", ["Essence of Water"] = "сутність води", ["Essence of Water (Provided)"] = "сутність води (видано)", ["Frozen Rune"] = "морозна руна", ["Frozen Rune (Provided)"] = "морозна руна (видано)", ["Thorium Bar"] = "злиток торію", ["Thorium Bar (Provided)"] = "злиток торію (видано)" } },
