    [92422] = { [1] = "Гнів Рат'маеля", [2] = "З оглядового майданчика Лордамір, що знаходиться глибоко в руїнах Лордерона, надійшли повідомлення. Нечестивий туман огорнув вулиці та цвинтар, надаючи лиху там певну непомітність.\n\nНаші розвідники повідомляють, що їх викликає нова сила в їхніх лавах, некромант, відомий як Рат'маель. Ми не можемо дозволити собі чекати, {ім'я}.\n\nЯкщо у вас є союзники, покличте їх та принесіть на допомогу Відреклим. Виженіть цю істоту з наших земель.", [3] = "Убийте Рат'маеля в руїнах Лордерона для отримання смертного варта Крістофа в Бріллі.", ["en"] = "The Wrath of Rath'mael", ["tasks"] = { ["Rath'mael slain"] = "Рат'маель: убито" } },
