    [92454] = { [1] = "Ласкаво просимо!", [2] = "Ласкаво просимо до World of Warcraft!\n\nНа знак особливої подяки за придбання колекційного видання World of Warcraft, передайте цей подарунковий сертифікат Далії Віндбріз у Тендал Гай. Після цього ви отримаєте подарунок: маленького компаньйона, який супроводжуватиме вас у ваших пошуках пригод та слави.\n\nЩе раз дякуємо та бажаємо приємного перебування у World of Warcraft!", ["en"] = "Welcome!", ["tasks"] = { ["Thendal Grove Gift Voucher"] = "Подарунковий сертифікат Thendal Grove", ["Thendal Grove Gift Voucher (Provided)"] = "Подарунковий сертифікат Thendal Grove (видано)" } },
    [9246] = { [1] = "Кіраса з крижаної луски", [2] = "Дякуючи тобі та Омаріону, царство йому небесне, я тепер зможу створити кірасу з крижаної луски. Все, що тобі потрібно буде зробити, це принести мені матеріали та заплатити невеличкий гонорар за виготовлення.", [3] = "Ремісник Вільгельм з Каплиці Надії Світла, що в Східних Зачумлених землях, просить вас принести 8 морозних рун, 24 важкі луски скорпідів, 7 сутностей води, 5 оброблених міцних шкур та 300 золотих. Також для виконання завдання вас мають возвеличувати в Сріблястому Світанку.", [4] = "Ти {стать:приніс:принесла} матеріали?", [5] = "Ось твоє замовлення, {ім'я}. Виконане, як і обіцяно!", ["en"] = "Icy Scale Breastplate", ["tasks"] = { ["42000 reputation with Argent Dawn"] = "42000 репутації у Сріблястого Світанку", ["Cured Rugged Hide"] = "оброблена міцна шкура", ["Cured Rugged Hide (Provided)"] = "оброблена міцна шкура (видано)", ["Essence of Water"] = "сутність води", ["Essence of Water (Provided)"] = "сутність води (видано)", ["Frozen Rune"] = "морозна руна", ["Frozen Rune (Provided)"] = "морозна руна (видано)", ["Heavy Scorpid Scale"] = "важка луска скорпіда", ["Heavy Scorpid Scale (Provided)"] = "важка луска скорпіда (видано)" } },
    [92460] = { [1] = "Досягнення повноліття", [2] = "Подивися на себе, сяючі очі та готові до пригод! Ми чекали на твій приїзд і сподівалися на твою таку необхідну допомогу тут, у селі Тендал. Гадаю, ти переповнена нервами та хвилюванням перед тим, що має статися. Зрештою, дорослішання буває лише раз у житті.\n\n<Ейлі доброзичливо посміхається.>\n\nІди, знайди нашого вождя села Роріана, Шукача Дня, біля входу до дерева-прадіда на захід звідси. Він допоможе тобі розпочати твою подорож.", [3] = "Поговоріть з Роріаном, Шукачем Дня, у Гаю Тендал.", [5] = "Вітряного привіту, {ім'я:к}. Для мене честь сьогодні вручити тобі реліквію повноліття на знак визнання потенціалу, який ти несеш шен'дорай. Наш народ за свою складну історію пережив великі труднощі й переслідування.\r\n\r\nСьогодні тобі даровано цю реліквію — одну з багатьох, що належали тим, хто був до тебе. Колись, коли твій попіл розвіють за вітром, вона перейде до іншого, щоб наша традиція тривала.\r\n\r\nБеручи цю реліквію із собою, знай: вітри рідного дому будуть із тобою, куди б ти не вирушив.", ["en"] = "Coming of Age" },
    [92461] = { [1] = "Гармонія в балансі", [2] = "Ми живемо в часи великої невизначеності для нашого народу. Ми стикаємося з безпрецедентними викликами, які можуть вимагати сміливих рішень, але ми також повинні боротися зі звичайними та буденними речами тут, у Тендал-Гроув. Візьмемо, наприклад, нещодавнє нестійке зростання популяції вульденів.\n\nВульдени є життєво важливою частиною нашої екосистеми. Однак, дисбаланс необхідно виправити, щоб зберегти тонку гармонію, яку поділяють усі істоти в Тендал-Гроув.\n\nВирушайте на схід і знищіть деяких вульденів там.", [3] = "Убийте 8 молодих вульдренів у гаю Тендал.", [5] = "Дякую за службу Зефрасу, юний {клас:к}.\r\n\r\nЗазвичай вулдрени доволі сумирні, але тварини, для яких Зефрас є домом, відчувають, коли магія вітрів виходить із рівноваги. Якщо це не виправити, їхня поведінка може стати небезпечною й непередбачуваною.", ["en"] = "Harmony in Balance", ["tasks"] = { ["Juvenile Vuldren"] = "Ювенільний Вульдрен", ["Juvenile Vuldren (Provided)"] = "Ювенільний Вульдрен (видано)", ["Juvenile Vuldren slain"] = "Ювенільний Вульдрен: убито" } },
    [92462] = { [1] = "Розслідування зараження", [2] = "Один з наших рейнджерів нещодавно повідомив про нашестя перистих мух тут, у Тендал-Гроув.\n\nПеристі мухи можуть бути небезпечними, якщо дозволити рою розростатися надто великим, тому, будь ласка, вирушайте до східного кінця Гаю та знищіть якомога більше перистих мух.", [3] = "Убийте 8 надокучливих перистих мух у гаю Тендал.", [5] = "Судячи з кількості нутрощів комах на тобі, ця навала й справді серйозна.", ["en"] = "Infestation Investigation", ["tasks"] = { ["Pesky Cirrusfly"] = "Набридлива периста муха", ["Pesky Cirrusfly (Provided)"] = "Набридлива периста муха (видано)", ["Pesky Cirrusfly slain"] = "Набридлива периста муха: убито" } },
    [92463] = { [1] = "Королева перистих мух", [2] = "Якщо ліс так густо кишить цими комахами, як здається, простого вбивства робочих комах буде недостатньо.\n\nЗайдіть глибше в ліс і знайдіть королеву. Вона буде поруч із вуликом і оточена більшими та агресивнішими солдатами, тому будьте обережні.\n\nВідпустіть її та поверніться сюди, коли це закінчиться. Це буде на одну проблему менше, про яку доведеться думати тут.", [3] = "Знищити королеву перистих мух у гаю Тендал.", [5] = "Чудова робота, {ім'я:к}. З тебе вийшов би добрий слідопит, якщо вся ця справа з «шукачем пригод» раптом не складеться.", ["en"] = "The Cirrusfly Queen", ["tasks"] = { ["Cirrusfly Queen"] = "Королева перистих мух", ["Cirrusfly Queen (Provided)"] = "Королева перистих мух (видано)", ["Cirrusfly Queen slain"] = "Королева перистих мух: убито" } },
    [92464] = { [1] = "Стихійний неспокій", [2] = "Відколи наші стихійні благодійники покинули нас, здається, що ми просто переходимо від одного неспокою до іншого. Проблема, з якою ми зараз стикаємося, полягає в тому, що прояви вітрів поблизу каменів, що стоять на північному сході, неспокійні.\n\nНе маючи справжньої самосвідомості, як розумні духи вітру, які колись жили тут, ці прості спрайти реагують відповідно на сили, емоції та наміри істот навколо них.\n\nМоя учениця Яла, Спостерігачка за Вітром, пішла спостерігати за ними. Знайдіть її та дізнайтеся, чого вона навчилася.", [3] = "Поговоріть з Яльським Спостерігачем за вітром у Тендальському гаю.", [5] = "Тебе послав Роріан? Добре. Мені не завадить твоя допомога.", ["en"] = "Elemental Unrest", ["tasks"] = { ["Learn more about the agitated winds."] = "Дізнайтеся більше про бурхливі вітри." } },
    [92465] = { [1] = "Агітатори", [2] = "Культ Ал'Акет — це лихо для цього острова. Ці культисти, безсумнівно, відповідальні за те, що збурюють простих духів вітру, які тут мешкають, і перетворюють їх на агресивних.\n\nНа жаль, нам потрібно розвіяти ці бурхливі вітри, перш ніж вони завдадуть комусь шкоди. Нам також потрібно чітко дати культу зрозуміти, що вони не бажані в гаю.\n\nЧи не допоможеш мені, {клас}?", [3] = "Убийте 6 Бурхливих Вітрів та 7 Навернених Ал'Акета в Гаю Тендал.", [5] = "Мені боляче проливати кров шен'дорай тут, у гаю, але ми робимо те, що мусимо.", ["en"] = "Agitators", ["tasks"] = { ["Al'Aketh Convert"] = "Аль-Акет Конвертувати", ["Al'Aketh Convert (Provided)"] = "Аль-Акет Конвертувати (видано)", ["Al'Aketh Convert slain"] = "Аль-Акет Конвертувати: убито", ["Roiling Winds destroyed"] = "Зруйновані бурхливі вітри" } },
    [92466] = { [1] = "Поклик землі", [2] = "Хоча ми значною мірою завдячуємо своїм процвітанням стихії вітру, шлях, яким ми йдемо, вимагає, щоб ми підкорилися заклику всіх чотирьох первинних стихій і пройшли випробування для кожної з них. Однак, перш ніж ви почнете своє перше серйозне випробування, ви повинні довести силу своєї рішучості.\n\nВирушайте до стоячих каменів на сході. Там помітили загін новонавернених Ал'Акет, і їх потрібно прогнати. Зустріньтеся з культистами там і принесіть мені один з їхніх печаток як доказ ваших діянь.", [3] = "Принесіть печатку Акіра до Вітротворця Боро.", ["en"] = "Call of Earth", ["tasks"] = { ["Signet of Akir"] = "Печатка Акіра", ["Signet of Akir (Provided)"] = "Печатка Акіра (видано)", ["Signet of Akir slain"] = "Печатка Акіра: убито" } },
    [92469] = { [1] = "Повернення до Роріана", [2] = "Ти вже достатньо тут зробив, {клас}. Я залишуся і приберу всіх відсталих там, внизу.\n\nПовернися до Села та розкажи Роріану про присутність культу. Він буде незадоволений.", [3] = "Принеси звістку про Ал'Акет Роріану, Шукачеві Дня, у Гай Тендал.", [5] = "Це дуже тривожно, хоча, на жаль, і не дивно. Ми вже деякий час знаємо про рухи культу, але задовольнялися спостереженням здалеку. Те, що вони збурюють духів вітру біля стоячих каменів, — явна ескалація з їхнього боку.\r\n\r\nТи виконав важку, але необхідну службу для гаю Тендала, {ім'я:к}. Дякую.", ["en"] = "Return to Rorian" },
    [9247] = { [1] = "Поклик Архіваріуса", [2] = "{ім'я},\n\nВ минулому тобі доводилося служити інтересам Сріблястого Світанку, і ти завжди ідеально {стать:виконував:виконувала} наші доручення. Але в цей час великої потреби, ми знову посилаємо тобі поклик.\n\n{ім'я}, будь ласка, з'явися до Архіваріуса у Каплицю Надії Світла, що в Східних Зачумлених землях, якщо ти бажаєш знову допомогти нам.", [3] = "Віднесіть лист Архіваріусу в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "А, {ім'я}, я радий тебе бачити.", [5] = "Вже за те, що ти {стать:з'явився:з'явилася} на поклик, {ім'я}, ми в боргу перед тобою. Сріблястий Світанок впевнений, що твій блискучий приклад покаже всім іншим, як відбити цю навалу Скари!", ["en"] = "The Keeper's Call", ["tasks"] = { ["A Letter from the Keeper of the Rolls"] = "лист від Архіваріуса", ["A Letter from the Keeper of the Rolls (Provided)"] = "лист від Архіваріуса (видано)" } },
    [92470] = { [1] = "Фоул Матріарх", [2] = "Роріан повідомив тобі, що я спостерігав за тобою. Зараз я пропоную тобі випробування рішучості. Однак будь обережний — це наражає тебе на велику небезпеку.\n\nІди до печер на півдні. Зменш там кількість урсер і знайди їхню матріарха, яку рейнджери називають «Урс'ана». Знищи її та принеси мені доказ її смерті. Як тільки ти це зробиш, ти зробиш важливий крок на своєму шляху.", [3] = "Убийте 8 Урсера-Суперників та візьміть голову матері-лігва, Урс'ани, у Тендальському гаю.", [4] = "Те, про що я тебе прошу, нелегке. Але тобі треба готуватися до значно серйозніших випробувань, якщо хочеш прожити достатньо довго, щоб служити острову Зефрас.", [5] = "Дуже добре. Ти повалив звірів і здолав непроханих культистів. Ти показав великий потенціал, але невдовзі твій шлях поведе тебе за межі відносної безпеки селища Тендал.", ["en"] = "Foul Matriarch", ["tasks"] = { ["Head of Urs'anah"] = "Голова Урсани", ["Head of Urs'anah (Provided)"] = "Голова Урсани (видано)", ["Head of Urs'anah slain"] = "Голова Урсани: убито", ["Ursera Scavenger"] = "Ведмедиця-сміттярка", ["Ursera Scavenger (Provided)"] = "Ведмедиця-сміттярка (видано)", ["Ursera Scavenger slain"] = "Ведмедиця-сміттярка: убито" } },
    [92471] = { [1] = "Етін з Гейлз", [2] = "Можливо, ти цього не усвідомлюєш, але все, що ти зробив, було своєрідним випробуванням. Випробуванням на те, що тебе чекає. Там великий острів, і Зефрасу потрібні такі жваві молоді шукачі пригод, як ти, якщо ми хочемо пережити випробування, з якими стикається наш народ.\n\nТа, що називається Етін з Гейлз, є однією з лідерів нашого народу тут, на острові Зефра, і вона спостерігає за тобою. У неї є завдання, яке ти повинен виконати. Поговори з нею, щоб дізнатися більше.", [3] = "Поговоріть з Етін з роду Штормів у Гаю Тендал.", [5] = "Роріан багато мені про тебе розповідав. Ти, мабуть, мене не знаєш, але я член Ради Старійшин тут, на острові Зефрас. Я прийшов сюди, до гаю Тендала, щоб прочитати течію вітрів. А ще — оцінити молодих шен'дорай, таких як ти, що вступають у доросле життя.\r\n\r\nТо скажи, ти готовий зробити наступний крок? Готовий служити острову Зефрас?", ["en"] = "Aetheen of the Gales" },
    [92472] = { [1] = "Наступний крок", [2] = "Однією з найпоширеніших загроз на острові Зефрас є культ Ал'Акет. Це релігійні фанатики, віддані поклонінню передбачуваному стихійному правителю Небесної стіни, Ал'Акіру Володарю Вітрів. Вони жорстокі, цілеспрямовані, а їхня сила та амбіції з кожним днем стають все смертоноснішими.\n\nВаш шлях незабаром приведе вас до села Шен'дар на півдні. З'явіться до констебля Аонди, коли прибудете. Культ загрожує Шен'дару, і їм потрібна допомога. Скажіть Аонді, що це я вас послав.", [3] = "Зверніться до констебля Аонди в селі Шен'дар.", [5] = "Тебе послала Етін? Зізнаюся, на вигляд ти не надто вражаєш, але селище Шен'дар не відмовиться від добровільної допомоги — тим паче якщо її надіслала сама старійшина Етін.", ["en"] = "The Next Step" },
    [92473] = { [1] = "Агресивне посягання", [2] = "Лігво ведмедиці на південному заході швидко стає проблемою. Лише минулого тижня рейнджерам довелося вбити підлітка-ведмедицю, яка забрів занадто близько до села та намагалася напасти на хлопчика, що грався біля основи бузини в центрі села.\n\nНам пощастило, що хлопчик врятувався. Голод і відчай роблять цих звірів занадто небезпечними, щоб залишати їх без нагляду. Ідіть на південь і знищіть найхудіших серед ведмедиць. Принесіть мені їхні кігті як доказ, коли це буде зроблено.", [3] = "Зберіть 6 кігтів Худорлявої Ведмедиці у Худорлявої Ведмедиці в Гаю Тендал.", [4] = "Останнім часом урсери стали значно агресивнішими. Цікаво, що змінилося й спричинило таку поведінку?", [5] = "Добре зроблено, {клас:к}. Слідопити гаю перед тобою в боргу.", ["en"] = "Aggressive Encroachment", ["tasks"] = { ["Scrawny Ursera Claw"] = "Кіготь худорлявої ведмедиці", ["Scrawny Ursera Claw (Provided)"] = "Кіготь худорлявої ведмедиці (видано)", ["Scrawny Ursera Claw slain"] = "Кіготь худорлявої ведмедиці: убито" } },
    [92474] = { [1] = "Падіння зі стилем", [2] = "Привіт, {ім'я}! Хочеш пограти?\n\nВсе, що тобі потрібно зробити, це стати на той виступ... а потім стрибнути! Використай свою вроджену здатність ходити по повітрі, щоб уповільнити падіння та подивитися, як далеко вперед ти зможеш злетіти.\n\nПравила вигадані, і очки не мають значення, але ти отримаєш бонусні очки, якщо зможеш приземлитися прямо перед Роріаном, Шукачем Дня, і налякати його! Йому це не сподобається, але я точно добре посміюся, якщо тобі вдасться його розсміяти! Ха!", [3] = "Стрибніть з вершини сторожової вежі в Тендал-Гроув і скористайтеся своєю здатністю «Ходити по повітрю», щоб уповільнити падіння.", [5] = "Скільки разів мені ще казати Міріаал, щоб вона не заохочувала інших бездумно користуватися нашими небородними дарами!\r\n\r\nУтім, гадаю, трохи практики у відносній безпеці селища... допустимо.\r\n\r\nНадалі раджу користуватися цією здібністю розважливо. Не варто бездумно виснажувати свою магію, а потім не мати змоги скористатися нею, коли вона справді буде потрібна.", ["en"] = "Falling With Style", ["tasks"] = { ["Use Walk on Air"] = "Використовуйте функцію «Прогулянка в прямому ефірі»" } },
    [9248] = { [1] = "Скромна пропозиція", [2] = "Ішну-ала, {раса:к}. Покажи мені докази, що лорд Ради Безодні мертвий і ти отримаєш в нагороду предмет, який допоможе тобі в бою проти кіражів.", [3] = "Аврель Золотолиста з Кенарійської цитаделі, що в Силітусі, хоче, щоб ви принесли їй один скіпетр безодні. Вам також потрібно заслужити повагу зі сторони Кенарійського Кола.", [4] = "Фенду-дат-белоре? Ой, вибач, {ім'я}. Я не впізнала тебе. Ти {стать:дістав:дістала} скіпетр?", [5] = "Анде'торас-етіл. Це означає \"Нехай зменшаться твої проблеми\" на моїй рідній мові.\n\nНоси перстень з гордістю та на здоров'я, {ім'я}.", ["en"] = "A Humble Offering", ["tasks"] = { ["9000 reputation with Cenarion Circle"] = "9000 репутації у Колі Кенаріона", ["Abyssal Scepter"] = "скіпетр безодні", ["Abyssal Scepter (Provided)"] = "скіпетр безодні (видано)" } },
    [92480] = { [1] = "СТАРИЙ НЕВИКОРИСТАНИЙ Засідка культу", [2] = "Культист, якого ви щойно вбили, передав, схоже, наказ від верховної жриці Культу Ал'Акіра. У ньому згадується шпигун у селі Шен'дар та операції культу в місці під назвою село Фалаат. Влада села Шен'дар захоче про це дізнатися.", ["en"] = "zzOLD UNUSED Cult Ambush", ["tasks"] = { ["Item #251942"] = "Товар №251942", ["Item #251942 (Provided)"] = "Товар №251942 (видано)" } },
    [92481] = { [1] = "Учень Аркану", [2] = "Поки ти вирішував нашу проблему з вульдренами, наш постійний тренер магів — Дорії Яскравий Шепіт — залишила тобі цей кристал відкликання. Він містить якесь послання для тебе, тож подивися на нього. Після цього ти зможеш знайти Дорії в будівлі одразу за мною.", [3] = "Огляньте Кристал Сяючого Відкликання, потім поговоріть з Дорією Яскравим Шепітом у Гаю Тендал.", ["en"] = "A Student of the Arcane", ["tasks"] = { ["Glowing Recall Crystal"] = "Сяючий кристал відкликання", ["Glowing Recall Crystal (Provided)"] = "Сяючий кристал відкликання (видано)", ["Glowing Recall Crystal slain"] = "Сяючий кристал відкликання: убито" } },
    [92482] = { [1] = "Шлях мисливця", [2] = "Поки ти вирішував нашу проблему з вудренами, наша місцева тренерка мисливців — Тай'рі Фарсайт — залишила тобі цю записку. Ти можеш знайти її трохи ближче до центру села. Прочитай записку, а потім знайди її.", [3] = "Прочитайте Написану Записку, а потім поговоріть з Тай'рі Далекоглядною в Гаю Тендал.", ["en"] = "The Way of the Hunter", ["tasks"] = { ["Scribbled Note"] = "Накреслена нотатка", ["Scribbled Note (Provided)"] = "Накреслена нотатка (видано)", ["Scribbled Note slain"] = "Накреслена нотатка: убито" } },
    [92483] = { [1] = "Вдома в тіні", [2] = "Поки ти вирішував нашу проблему з вульдренами, наш місцевий тренер-шахрай — Акері Даскблейд — попросив поговорити з тобою. Він залишив цю записку, тож спочатку прочитай її, а потім розшукай його всередині сторожової вежі, тут, у селі.\n\nВін підозрілий хлопець, але, з іншого боку, ти теж. Думаю, у вас все вийде.", [3] = "Прочитайте Просту Записку, а потім поговоріть з Акері Сутінковим Клинком у сторожовій вежі в Гаю Тендал.", ["en"] = "At Home in the Shadows", ["tasks"] = { ["Simple Note"] = "проста записка", ["Simple Note (Provided)"] = "проста записка (видано)" } },
    [92484] = { [1] = "Приймаючи стихії", [2] = "Поки ти вирішував нашу проблему з вудренами, наш місцевий тренер шаманів — Вітротворець Боро — залишив тобі цей кристал відкликання. Будь ласка, оглянь його, а потім поговори з Боро трохи далі, біля центру села.", [3] = "Огляньте Кристал Гудіння, а потім поговоріть з Творцем Вітру Боро в Гаю Тендал.", ["en"] = "Embracing the Elements", ["tasks"] = { ["Humming Recall Crystal"] = "Гудіння нагадування про кристал", ["Humming Recall Crystal (Provided)"] = "Гудіння нагадування про кристал (видано)" } },
    [92485] = { [1] = "Дослідник природи", [2] = "Поки ти вирішував нашу проблему з вульденами, наш тренер-друїд, Ксітон Срібний Вінд, залишив тобі цю записку. Прочитай її якомога швидше, а потім знайди Срібного Віндвера на першому поверсі цього великого дерева одразу за мною.\n\nПрислухайся до його слів і порад, він може багато чому тебе навчити.", [3] = "Прочитайте Складений Пергамент, а потім поговоріть із Ксітоном Срібним Вітром у Гаю Тендал.", [4] = "Вітаю. Я Ксайтон Срібновій, хранитель друїдських знань.", [5] = "Флора й фауна острова Зефрас — це багатий гобелен яскравого життя. Екосистема потребує постійної рівноваги, щоб зберігати гармонію природи, а ми, друїди, — хранителі цієї рівноваги. Я бачу в тобі великий потенціал, але цей шлях нелегкий, і тобі знадобиться настанова, доки ти набиратимешся сили як учень ікла, кігтя, пера й гілки. \r\n\r\nПоговори зі мною ще раз, якщо хочеш зробити наступні кроки.", ["en"] = "A Student of Nature", ["tasks"] = { ["Folded Parchment"] = "Складений пергамент", ["Folded Parchment (Provided)"] = "Складений пергамент (видано)" } },
    [9249] = { [1] = "40 квитків - Схема: Контролер парового танка", ["en"] = "40 Tickets - Schematic: Steam Tonk Controller", ["tasks"] = { ["Item #19182"] = "Товар №19182" } },
    [925] = { [1] = "Відбиток копита Керна", [2] = "Кажуть, що Керн Криваве Копито — один з найвеличніших героїв Орди, що коли-небудь існували. Коли я виросту, я теж хочу стати героєм Орди!\n\nТи знаєш Керна, {ім'я}? Можеш мені допомогти, будь ласка? Зможеш взяти у нього відбиток копита для мене? Я не знаю, як його попросити, і у нього, напевно, немає часу на таких, як я... Але ти {стать:шукач:шукачка} пригод, так само як і він! Я впевнений, він згодиться дати тобі його!", [3] = "Прямуйте до Громового Бескиду, щоб отримати для свого підопічного відбиток копита Керна Кривавого Копита.", [4] = "Коли орки були самі та без друзів, таурени зустріли їх у чужих землях та допомогли їм, не вимагаючи нічого натомість. Це велика честь, {ім'я}.", [5] = "ВАУ! Тобі вдалося взяти відбиток копита Керна! Дуже тобі дякую! І, ого... він написав на ньому щось для мене! Я знав, що він крутий, просто знав! Може, якось в майбутньому я подякую йому особисто... коли сам стану героєм Орди!\n\nТи {стать:найкращий:найкраща}, {ім'я}. Я тобі дуже вдячний.", ["en"] = "Cairne's Hoofprint", ["tasks"] = { ["Cairne's Hoofprint"] = "відбиток копита Керна", ["Cairne's Hoofprint (Provided)"] = "відбиток копита Керна (видано)" } },
    [9250] = { [1] = "Каркас Атієша", [2] = "Каркас готовий, Атієш майже зібраний. Не вистачає лише верхів'я та основи. Іще лишилася одна проблема — посох досі служить вмістилищем зла Сарґераса.\n\nЗнайдіть того, хто зможе допомогти вам знайти останні частини та вигнати злого духа з посоха.", [3] = "Знайдіть того, хто допоможе вам знайти останні дві частини посоха та очистити його від зла.", [4] = "От і настав цей час, {стать:смертний:смертна}.", [5] = "Архімаги померли.\n\nНе оплакуй їх смерть, {ім'я}. Так і мало статися. Так само як тобі судилося отримати цей посох Вартівника...", ["en"] = "Frame of Atiesh", ["tasks"] = { ["Frame of Atiesh"] = "каркас Атієша", ["Frame of Atiesh (Provided)"] = "каркас Атієша (видано)" } },
    [9251] = { [1] = "Атієш, осквернений великий посох", [2] = "Ти питаєшся, чому ти все іще {стать:живий:жива}. Зрештою, ти володієш предметом великого зла. Відповідь не така чітка, {ім'я}. Я роблю лише те, що повинен.\n\nКел'Тузад сидить на своєму троні в Наксрамасі, він щось планує... Він шукає те, що ти тримаєш та тримає те, що шукаєш ти.\n\nЩодо основи посоха. Дворф Бранн Бронзобородий мав його при собі, коли заходив до Ан'Кіражу. Попри те, що він його покинув, основа Атієша все іще там.\n\nКоли отримаєш всі частини — повертайся до мене.", [3] = "Анахроносу з Печер Часу, що в Танарісі, потрібні навершя та основа Атієша.", [4] = "В його теперішній формі, цей посох надто небезпечний, щоб бути у руках смертного.", [5] = "Всередині є істота... істота не з цього світу.", ["en"] = "Atiesh, the Befouled Greatstaff", ["tasks"] = { ["Base of Atiesh"] = "основа Атієша", ["Base of Atiesh (Provided)"] = "основа Атієша (видано)", ["Staff Head of Atiesh"] = "верхів'я Атієша", ["Staff Head of Atiesh (Provided)"] = "верхів'я Атієша (видано)" } },
    [92515] = { [1] = "Проблема з Прайдклоузами", [2] = "Наче бандитів та божевільних культистів було недостатньо, пагорби зараз також густо кишать гордими кігтями. Вони починають зазіхати на межі села та стають дедалі сміливішими з кожним днем. Це лише питання часу, коли чиюсь домашню тварину чи дитину заберуть. Було б милосердям з нашого боку скоротити їхню кількість зараз, а не після якоїсь трагедії.\n\nПринесіть мені приблизно десяток їхніх шкур. Я можу перетворити їх на всілякі товари, які стануть у пригоді селу.", [3] = "Зберіть 10 шкур Гордих Кігтів у Гордих Кігтів у Шен'дарському нагір'ї.", [4] = "Як на мене, Гордокігті насправді навіть трохи милі. З безпечної відстані... і коли стоїш за спиною когось із мечем, звісно.", [5] = "Я ж не казав, що робота буде чистенькою, правда?", ["en"] = "The Problem With Prideclaws", ["tasks"] = { ["Prideclaw Pelt"] = "Шкура Гордого Кігтя", ["Prideclaw Pelt (Provided)"] = "Шкура Гордого Кігтя (видано)", ["Prideclaw Pelt slain"] = "Шкура Гордого Кігтя: убито" } },
    [92516] = { [1] = "Переслідування гіпогрифів", [2] = "Зграя гіпогрифів нещодавно влаштувала гніздування на південний схід від села Шен'дар і сіє хаос серед мандрівників на дорозі. Мені потрібен хтось, хто поїде туди і прорідить їх для нас.", [3] = "Убийте 8 юнаків-гіпогрифів, 6 захисників-гіпогрифів та матріарха-гіпогрифа у Шен'дарському нагір'ї.", ["en"] = "Hippogryph Harrassment", ["tasks"] = { ["Hippogryph Matriarch"] = "Гіпогриф-матріарх", ["Hippogryph Matriarch (Provided)"] = "Гіпогриф-матріарх (видано)", ["Hippogryph Matriarch slain"] = "Гіпогриф-матріарх: убито", ["Hippogryph Protector"] = "Гіпогриф-захисник", ["Hippogryph Protector (Provided)"] = "Гіпогриф-захисник (видано)", ["Hippogryph Protector slain"] = "Гіпогриф-захисник: убито", ["Hippogryph Youth"] = "Гіпогриф Юність", ["Hippogryph Youth (Provided)"] = "Гіпогриф Юність (видано)", ["Hippogryph Youth slain"] = "Гіпогриф Юність: убито" } },
    [92517] = { [1] = "Злочинний елемент", [2] = "Неподалік на півночі є печера, захована за водоспадом. Мені добре відомо, що з цієї печери діє група бандитів. Вони були для нас проблемою до приходу культу, але тепер вони справжній жах. На жаль, я не можу виділити людей, щоб піти та вичистити їх.\n\nМені потрібно, щоб ти пішов туди та подбав про них для мене. Вбий якомога більше, і, якщо можливо, знищ їхнього лідера, того, кого вони називають \"Злий Вітер\" Беннік. Ця печера небезпечна, тому будь обережний.", [3] = "Убийте 10 бандитів з нагір'я та їхнього лідера, \"Злого вітру\" Бенніка, у нагір'ї Шен'дар.", ["en"] = "The Criminal Element", ["tasks"] = { ["\"Badwind\" Bennic"] = "«Поганий вітер» Беннік", ["\"Badwind\" Bennic (Provided)"] = "«Поганий вітер» Беннік (видано)", ["\"Badwind\" Bennic slain"] = "«Поганий вітер» Беннік: убито", ["Highlands Bandit"] = "Хайлендський бандит", ["Highlands Bandit (Provided)"] = "Хайлендський бандит (видано)", ["Highlands Bandit slain"] = "Хайлендський бандит: убито" } },
    [92528] = { [1] = "Серед вірних", [2] = "Вірні Аль'Акіра стають дедалі сильнішими з кожним таким завзятим новобранцем, як ви. Як бачите, наша сила надає форми самій бурі!\n\nЗазвичай я б одразу відправив вас до Небесного жерця Аандерса для оцінки, але зараз він зайнятий прийомом гостя в корчмі на північній стороні міста. Будь ласка, уникайте цього місця поки що. Неголений новобранець, як ви, у присутності такого гостя був би недоречним.\n\nПоки що просто не заважайте нікому.", [3] = "Огляньте село Фалаат, щоб дізнатися про наміри культу в Шен'дарському нагір'ї.", ["en"] = "Among the Faithful", ["tasks"] = { ["Learn about the cultists' plans"] = "Дізнайтеся про плани культистів" } },
    [92529] = { [1] = "Село Фалаат", [2] = "Мене тішить те, що ти хочеш служити Аль'Акіру. Наші нинішні випробування як народу походять від нашої власної самовдоволеності. Ми стали гордими та сприймали щедрість вітрів як належне. Застій, що настав, є причиною того, що духи вітру покинули нас.\n\nТільки через акти каяття ми можемо знову відчути ласку вітру. Якщо ти прагнеш товариства однодумців шен'дорей, вирушай до села Фалаат і знайди там місіонера Джасаана. Я позначу тебе, щоб вірні знали тебе як новобранця.", [3] = "Зверніться до місіонерки Джасаан біля входу до села Фалаат.\n\nЯкщо ви втратите свій Знак Акіра, поговоріть із Санією Сільверстрім у селі Шен'дар, щоб відновити його ефект.", ["en"] = "Falaath Village", ["tasks"] = { ["Speak with Missionary Jasaan at the entrance to Falaath Village"] = "Поговоріть з місіонером Джасааном біля входу до села Фалаат" } },
    [92532] = { [1] = "Шлях Воїна", [2] = "Поки тебе не було, наш тренер воїнів, Майстер Клинків Рен, попросив нас відправити тебе до них, коли ти повернешся. Вона також залишила тобі цю записку.\n\nПрочитай її, а потім знайди Майстра Клинків Рена всередині сільської сторожової вежі.", [3] = "Прочитайте зім'яту записку, яку вам дали, а потім знайдіть майстра клинка Рена всередині сторожової вежі села Тендал.", ["en"] = "The Warrior's Path", ["tasks"] = { ["Crumpled Note"] = "зім'ята записка", ["Crumpled Note (Provided)"] = "зім'ята записка (видано)" } },
    [92534] = { [1] = "jktestquest1a", ["en"] = "jktestquest1a" },
    [92544] = { [1] = "Аль'Акетські бандити", [2] = "Група розбійників культу Ал'Акет оселилася поблизу руїн храму, трохи південно-західніше звідси, на чолі зі справжнім монстром на ім'я Малдуко Хмарний Краш. Цю юрбу, безсумнівно, відправила сюди Верховна Жриця Лортуна зі Святилища Акіра, щоб напасти на подорожніх і примусити наших людей приєднатися до культу.\n\nМені потрібно залишитися тут, на своєму посту, щоб попередити подорожніх, які залишають гай, про небезпеку, але я був би вдячний, якби ви могли щось зробити для мене з цими культистами та їхнім лідером.", [3] = "Убийте 6 Ал'Акетських Брутів, 4 Ал'Акетських Неофітів та Малдуко Хмарного Розтрощення в Тендальському Гаю.", [5] = "Мені ледве вдалося втриматися, щоб не кинути свою позицію й не приєднатися до тебе. Можу лише сподіватися, що ці йолопи зрозуміли натяк і скоро заберуться звідси. \r\n\r\nДякую, {клас:к}. Тобі вдячні слідопити гаю Тендала.", ["en"] = "Al'Aketh Thugs", ["tasks"] = { ["Al'Aketh Brute"] = "Аль'Акет Брут", ["Al'Aketh Brute (Provided)"] = "Аль'Акет Брут (видано)", ["Al'Aketh Brute slain"] = "Аль'Акет Брут: убито", ["Al'Aketh Neophyte"] = "Аль'Акет Неофіт", ["Al'Aketh Neophyte (Provided)"] = "Аль'Акет Неофіт (видано)", ["Al'Aketh Neophyte slain"] = "Аль'Акет Неофіт: убито", ["Malduko Cloudcrush"] = "Мальдуко Хмарний Краш", ["Malduko Cloudcrush (Provided)"] = "Мальдуко Хмарний Краш (видано)", ["Malduko Cloudcrush slain"] = "Мальдуко Хмарний Краш: убито" } },
    [92550] = { [1] = "Хаос у Високогір'ї", [2] = "Нашим найкращим захистом тут може бути сильний напад. Наша перевага полягає в тому, що ми очікуємо наближення атаки. Чого вони не очікуватимуть, так це того, що ми вдаримо по них першими.\n\nЯ вже багато просив вас, але, будь ласка, поверніться до села Фалаат. Вбийте якомога більше культистів, і якщо зможете підійти досить близько, убийте командира та принесіть мені його голову. Я залишуся тут і організую громадян та наших кількох миротворців, щоб підготувати оборону... на випадок, якщо ви не повернетеся.", [3] = "Вирушайте до руїн села Фалаат та знищіть 6 Буревісників Ал'Акета, 4 Живих Блискавок і візьміть голову Командира Цикласа.", ["en"] = "Havoc in the Highlands", ["tasks"] = { ["Al'Aketh Stormcaller"] = "Ал'Акет, Заклинатель Бурі", ["Al'Aketh Stormcaller (Provided)"] = "Ал'Акет, Заклинатель Бурі (видано)", ["Al'Aketh Stormcaller slain"] = "Ал'Акет, Заклинатель Бурі: убито", ["Commander Cyclas's Head"] = "Голова командира Сайкласа", ["Commander Cyclas's Head (Provided)"] = "Голова командира Сайкласа (видано)", ["Commander Cyclas's Head slain"] = "Голова командира Сайкласа: убито", ["Living Lightning"] = "Жива блискавка", ["Living Lightning (Provided)"] = "Жива блискавка (видано)", ["Living Lightning slain"] = "Жива блискавка: убито" } },
    [92551] = { [1] = "Крадені припаси", [2] = "Я підчув, що ти, можливо, їдеш до села Фалаат? Поки ти там, будь ласка, стеж за нашими викраденими схованками з припасами.\n\nАль'Акет вже кілька місяців грабує наші каравани з припасами, перевозячи різні товари, такі як їжа та вітряне каміння, до низин і назад. Звичайно, вони звинувачують бандитів, але ми всі знаємо, що все це опиняється в одному місці. Якщо щось із цього залишилося у Фалааті, було б дуже корисно, якби ти зміг це повернути.", [3] = "Зберіть 10 упаковок викрадених припасів Шен'дар у селі Фалаат у нагір'ї Шен'дар.", ["en"] = "Stolen Supplies", ["tasks"] = { ["Stolen Shen'dar Supplies"] = "Викрадені припаси Шен'дара", ["Stolen Shen'dar Supplies (Provided)"] = "Викрадені припаси Шен'дара (видано)", ["Stolen Shen'dar Supplies slain"] = "Викрадені припаси Шен'дара: убито" } },
    [92553] = { [1] = "Поповнення комор", [2] = "Готовий трохи попрацювати? Мені б не завадила допомога такого сильного шукача пригод, як ти. З огляду на те, як тут відбувається небезпека, останнім часом ні в кого не було багато часу на полювання чи пошук їжі, і мені потрібен хтось, хто б дістав мені свіжі яйця та м'ясо мандрівника, щоб прогодувати це село.\n\nЯ б із задоволенням навчив тебе одному зі своїх відомих рецептів, якщо ти зможеш принести мені те, що мені потрібно. Що скажеш?", [3] = "Зберіть 3 маленьких яйця та 8 м'яса м'яса щурака у істот, що зустрічаються по всьому Шен'дарському нагір'ю.", ["en"] = "Restocking the Larders", ["tasks"] = { ["Small Egg"] = "маленьке яйце", ["Small Egg (Provided)"] = "маленьке яйце (видано)", ["Strider Meat"] = "м'ясо бігуна", ["Strider Meat (Provided)"] = "м'ясо бігуна (видано)" } },
    [9257] = { [1] = "Атієш, великий посох Вартівника", [2] = "Останнє завдання буде найскладнішим, {ім'я}. Ти вже {стать:здолав:здолала} Старого Бога і генерала Короля-Ліча, але тепер тобі доведеться зустрітися з рукою Сарґераса.\n\nВізьми посох і вирушай до Стратгольма. Там ти знайдеш клаптик освяченої землі: землі, де полягли найкращі лицарі Лордерона. Поклади осквернений посох на святу землю і приготуйся до бою з надзвичайно могутньою істотою, що вирветься зсередини... Переможи демона, що контролює посох, і повертайся до мене.", [3] = "Анахронос з Печер Часу, що в Танарісі, просить вас віднести Атієш, великий посох Вартівника, до Стратгольма і використати його на освяченій землі. Здолайте сутність, що з'явиться з посоха, і поверніться до Анахроноса.", [4] = "Я не повинен втручатися, {раса:к}.", [5] = "Велич цього досягнення не можна применшувати, {ім'я:к}. Ти {стать:зробив:зробила} те, що інші вважали б неможливим. Однак, такою була доля. Посох зробив свій вибір...", ["en"] = "Atiesh, Greatstaff of the Guardian", ["tasks"] = { ["Atiesh Cleansed"] = "Атієш Очищений", ["Atiesh Cleansed (Provided)"] = "Атієш Очищений (видано)", ["Atiesh Cleansed slain"] = "Атієш Очищений: убито", ["Atiesh, Greatstaff of the Guardian"] = "Атієш, великий посох Вартівника", ["Atiesh, Greatstaff of the Guardian (Provided)"] = "Атієш, великий посох Вартівника (видано)" } },
    [9259] = { [1] = "Зрадник Кривавого Вітрила", [4] = "Цей мерзенний пес, Ревілґаз, запропонував помилувати всіх колишніх піратів Кривавого вітрила, які здадуть свого капітана! Цей трюмний шмаркач попросив мене піти й прирізати моїх старих товаришів і в доказ принести їхні бандани.\n\nЯ не збираюся цього робити та тебе не проситиму. Принеси мені шовкове полотно і червоний барвник, і я зроблю копії бандан. Я скажу барону, що ти {стать:перейшов:перейшла} на бік ворога, але попереджаю, Кривавому Вітрилу це не сподобається!", [5] = "Вшануймо хвилиною мовчання пам'ять наших загиблих побратимів, {ім'я}.\n\n<Зрадник Кривавого Вітрила посміхається вам і підморгує.>\n\nБути зрадником, це діло одне, але вбивати своїх — це було б зовсім підло, ага!", ["en"] = "Traitor to the Bloodsail", ["tasks"] = { ["Red Dye"] = "червоний барвник", ["Red Dye (Provided)"] = "червоний барвник (видано)", ["Silk Cloth"] = "шовкове полотно", ["Silk Cloth (Provided)"] = "шовкове полотно (видано)" } },
    [926] = { [1] = "Тріснутий камінь сили", [5] = "Ці камені наповнені магічною енергією, але навмисно пошкоджені. Вони дуже нестабільні. Піднявши їх зі столу, ви бачите, як вони швидко починають пожирати самі себе.", ["en"] = "Flawed Power Stone" },
    [9260] = { [1] = "Розвідка Скари в Штормовії", [2] = "Скара розташувала свій табір прямо біля нашого порогу. Ми не можемо сидіти склавши руки! Чи встанеш ти на захист Штормовію від цих проклятих загарбників?\n\nЗзовні ми побачили дивні рунічні кола, що світяться тією ж енергією, що оточує невмерлих та Некрополь там, нагорі. Я впевнений, що вони мають якесь призначення, і я хочу, щоб ти {стать:дізнався:дізналася}, яке саме. Поки ти цим займаєшся, зменш кількість цих потвор і принеси мені докази їхньої смерті разом з результатами свого розслідування, і я тебе винагороджу. Іди!", [3] = "Зберіть три тьмяні некротичні камені зі Скари поблизу Штормовію та дослідіть сяйливі рунічні кола поруч з їхнім табором.", [4] = "Ти вже {стать:завершив:завершила} дослідження кіл Скари? Немає часу для балачок!", [5] = "Хмм... Судячи з того, що ти мені {стать:розповів:розповіла}, ці голоси всередині рунічних кіл... схоже, що їх використовують для комунікації. Я здригаюся від самої думки про те, з якими жахливими почварами можна зв'язатися за допомогою такої магії. Проте тобі вдалося залишитися {стать:цілим та неушкодженим:цілою та неушкодженою}. Сріблястий Світанок цінує твою службу.", ["en"] = "Investigate the Scourge of Stormwind", ["tasks"] = { ["Dim Necrotic Stone"] = "тьмяний некротичний камінь", ["Dim Necrotic Stone (Provided)"] = "тьмяний некротичний камінь (видано)" } },
    [9261] = { [1] = "Розвідка Скари в Залізогарті", [2] = "Скара розташувала свій табір прямо біля нашого порогу. Ми не можемо сидіти склавши руки! Чи встанеш ти на захист Залізогарта від цих проклятих загарбників?\n\nЗзовні ми побачили дивні рунічні кола, що світяться тією ж енергією, що оточує невмерлих та Некрополь там, нагорі. Я впевнений, що вони мають якесь призначення, і я хочу, щоб ти {стать:дізнався:дізналася}, яке саме. Поки ти цим займаєшся, зменш кількість цих потвор і принеси мені докази їхньої смерті разом з результатами свого розслідування, і я тебе винагороджу. Іди!", [3] = "Зберіть три тьмяні некротичні камені зі Скари поблизу Залізогарта та дослідіть сяйливі рунічні кола поруч з їхнім табором.", [4] = "Ти вже {стать:завершив:завершила} дослідження кіл Скари? Немає часу для балачок!", [5] = "Хмм... Судячи з того, що ти мені {стать:розповів:розповіла}, ці голоси всередині рунічних кіл... схоже, що їх використовують для комунікації. Я здригаюся від самої думки про те, з якими жахливими почварами можна зв'язатися за допомогою такої магії. Проте тобі вдалося залишитися {стать:цілим та неушкодженим:цілою та неушкодженою}. Сріблястий Світанок цінує твою службу.", ["en"] = "Investigate the Scourge of Ironforge", ["tasks"] = { ["Dim Necrotic Stone"] = "тьмяний некротичний камінь", ["Dim Necrotic Stone (Provided)"] = "тьмяний некротичний камінь (видано)" } },
    [9263] = { [1] = "Розвідка Скари в Орґріммарі", [2] = "Скара розташувала свій табір прямо біля нашого порогу. Ми не можемо сидіти склавши руки! Чи встанеш ти на захист Орґріммара від цих проклятих загарбників?\n\nЗзовні ми побачили дивні рунічні кола, що світяться тією ж енергією, що оточує невмерлих та Некрополь там, нагорі. Я впевнений, що вони мають якесь призначення, і я хочу, щоб ти {стать:дізнався:дізналася}, яке саме. Поки ти цим займаєшся, зменш кількість цих потвор і принеси мені докази їхньої смерті разом з результатами свого розслідування, і я тебе винагороджу. Іди!", [3] = "Зберіть три тьмяні некротичні камені зі Скари поблизу Орґріммара та дослідіть сяйливі рунічні кола поруч з їхнім табором.", [4] = "Ти вже {стать:завершив:завершила} дослідження кіл Скари? Немає часу для балачок!", [5] = "Хмм... Судячи з того, що ти мені {стать:розповів:розповіла}, ці голоси всередині рунічних кіл... схоже, що їх використовують для комунікації. Я здригаюся від самої думки про те, з якими жахливими почварами можна зв'язатися за допомогою такої магії. Проте тобі вдалося залишитися {стать:цілим та неушкодженим:цілою та неушкодженою}. Сріблястий Світанок цінує твою службу.", ["en"] = "Investigate the Scourge of Orgrimmar", ["tasks"] = { ["Dim Necrotic Stone"] = "тьмяний некротичний камінь", ["Dim Necrotic Stone (Provided)"] = "тьмяний некротичний камінь (видано)" } },
    [9264] = { [1] = "Розвідка Скари в Громовому Бескиді", [2] = "Скара розташувала свій табір прямо біля нашого порогу. Ми не можемо сидіти склавши руки! Чи встанеш ти на захист Громового Бескиду від цих проклятих загарбників?\n\nЗзовні ми побачили дивні рунічні кола, що світяться тією ж енергією, що оточує невмерлих та Некрополь там, нагорі. Я впевнений, що вони мають якесь призначення, і я хочу, щоб ти {стать:дізнався:дізналася}, яке саме. Поки ти цим займаєшся, зменш кількість цих потвор і принеси мені докази їхньої смерті разом з результатами свого розслідування, і я тебе винагороджу. Іди!", [3] = "Зберіть три тьмяні некротичні камені зі Скари поблизу Громового Бескиду та дослідіть сяйливі рунічні кола поруч з їхнім табором.", [4] = "Ти вже {стать:завершив:завершила} дослідження кіл Скари? Немає часу для балачок!", [5] = "Хмм... Судячи з того, що ти мені {стать:розповів:розповіла}, ці голоси всередині рунічних кіл... схоже, що їх використовують для комунікації. Я здригаюся від самої думки про те, з якими жахливими почварами можна зв'язатися за допомогою такої магії. Проте тобі вдалося залишитися {стать:цілим та неушкодженим:цілою та неушкодженою}. Сріблястий Світанок цінує твою службу.", ["en"] = "Investigate the Scourge of Thunder Bluff", ["tasks"] = { ["Dim Necrotic Stone"] = "тьмяний некротичний камінь", ["Dim Necrotic Stone (Provided)"] = "тьмяний некротичний камінь (видано)" } },
    [92640] = { [1] = "Відчайдушні часи", [2] = "Оскільки відкрита боротьба з культом неможлива, наш найкращий шанс — використати цю можливість для нападу на саму святиню. Ми можемо викреслити саму Лортуну з поля, перш ніж вона встигне завершити свою частину цього плану.\n\nТак виявилося, що Валеннія вже деякий час готує стратегію потенційного нападу на Святиню. Єдина проблема полягає в тому, що нам знадобиться допомога.\n\nПоговоріть з Валеннією, щоб дізнатися деталі.", [3] = "Поговоріть з Валенією Буревісник у Валанаарі та дотримуйтесь її інструкцій.", ["en"] = "Desperate Times", ["tasks"] = { ["Recruit the High Order"] = "Завербуйте вищий орден", ["Recruit the High Order (Provided)"] = "Завербуйте вищий орден (видано)", ["Recruit the High Order slain"] = "Завербуйте вищий орден: убито", ["Recruit the Windshapers"] = "Завербуйте вітроутворювачів", ["Recruit the Windshapers (Provided)"] = "Завербуйте вітроутворювачів (видано)", ["Recruit the Windshapers slain"] = "Завербуйте вітроутворювачів: убито", ["Speak with Valennia Stormfist"] = "Поговоріть з Валенією Буревісник" } },
    [92642] = { [1] = "Зміна логістики", [2] = "Валеннія відправила лише одну людину, щоб допомогти відбити повномасштабний напад... вітрами.\n\nВиглядаєш не дуже сильно, але я візьму те, що зможу. Нам потрібно завдати якомога більше шкоди, щоб скоро це зупинити. Мої люди більше не зможуть триматися.\n\nСпустіться з пагорба та поруште їхню логістику. Їхні цілителі не дадуть нападникам наступати, якщо ми їх знищимо, то зможемо зібратися та відкинути їх. Будь-які інші культисти, яких ви вб'єте, поки будете там, також допоможуть.", [3] = "Убийте 4 цілителів Ал'Акета та 8 бійців Ал'Акета в низовині Гастберрі.", ["en"] = "Disrupting Logistics", ["tasks"] = { ["Al'Aketh Brawler"] = "Аль'Акетський бешкетник", ["Al'Aketh Brawler (Provided)"] = "Аль'Акетський бешкетник (видано)", ["Al'Aketh Brawler slain"] = "Аль'Акетський бешкетник: убито", ["Al'Aketh Healer"] = "Цілитель Аль'Акет", ["Al'Aketh Healer (Provided)"] = "Цілитель Аль'Акет (видано)", ["Al'Aketh Healer slain"] = "Цілитель Аль'Акет: убито" } },
    [92643] = { [1] = "Перебіжчик", [2] = "Серед Ал'Акетів є перебіжчик. Вони стверджують, що знають справжні наміри культу щодо острова та хочуть прийти, але зроблять це лише за умови гарантій захисту.\n\nЦей перебіжчик ховається у відокремленому будинку на північний захід від Валанаару у високогір'ї. Мені потрібен хтось, хто може непомітно потрапити туди, знайти зрадника та супроводити його назад до нас. Це може бути пасткою, але якщо ця інформація така важлива, як стверджує цей зрадник, вона варта певного ризику.", [3] = "Знайдіть перебіжчика-культиста в будинку одразу в гірській місцевості на північний захід від Валанаару.", ["en"] = "The Turncoat", ["tasks"] = { ["Find the Al'Aketh Turncoat"] = "Знайдіть перебіжчика Ал'Акета", ["Find the secluded house in Shen'dar Highlands"] = "Знайдіть відокремлений будинок у Шен'дарському нагір'ї" } },
    [92644] = { [1] = "Невтішні новини", [2] = "<Ви засовуєте руку під ще тепле тіло культиста-перебіжчика та знаходить маленький, сяючий блакитний кристал. Він здається пошкодженим, але все ще може бути важливим. Верховний Старійшина Тіньопісні може бути цим зацікавлений.>", [3] = "Доставте сяючий кристал Таланаанісу Шодосонгу у Валанаар.", ["en"] = "Unfortunate News", ["tasks"] = { ["Glowing Crystal"] = "Сяючий кристал", ["Glowing Crystal (Provided)"] = "Сяючий кристал (видано)", ["Glowing Crystal slain"] = "Сяючий кристал: убито" } },
    [92645] = { [1] = "Зламати вимикач", [2] = "Цю атаку буде важко відбити, якщо ми не зможемо знищити командира культу. Її називають Белгілос «Руйнівниця», і вона справжнє жахливе явище. Вона була миротворцем, перш ніж культ вийшов з-під контролю, і навіть тоді вона була... не в собі. Як культист, я можу лише уявити, наскільки гіршою вона може бути зараз.\n\nМожливо, я просто відправляю тебе на смерть, але хтось має знищити Белгілос, якщо ми хочемо вижити тут. Ти можеш знайти її на віллі біля підніжжя пагорба. Удачі, {клас}.", [3] = "Убийте командира Белгілоса в низовині Гастберрі.", ["en"] = "Breaking the Breaker", ["tasks"] = { ["Commander Belguilos"] = "Командир Белгілос", ["Commander Belguilos (Provided)"] = "Командир Белгілос (видано)", ["Commander Belguilos slain"] = "Командир Белгілос: убито" } },
    [9265] = { [1] = "Розвідка Скари в Підмісті", [2] = "Скара розташувала свій табір прямо біля нашого порогу. Ми не можемо сидіти склавши руки! Чи встанеш ти на захист Підмістя від цих проклятих загарбників?\n\nЗзовні ми побачили дивні рунічні кола, що світяться тією ж енергією, що оточує невмерлих та Некрополь там, нагорі. Я впевнений, що вони мають якесь призначення, і я хочу, щоб ти {стать:дізнався:дізналася}, яке саме. Поки ти цим займаєшся, зменш кількість цих потвор і принеси мені докази їхньої смерті разом з результатами свого розслідування, і я тебе винагороджу. Іди!", [3] = "Зберіть три тьмяні некротичні камені зі Скари поблизу Підмістя та дослідіть сяйливі рунічні кола поруч з їхнім табором.", [4] = "Ти вже {стать:завершив:завершила} дослідження кіл Скари? Немає часу для балачок!", [5] = "Хмм... Судячи з того, що ти мені {стать:розповів:розповіла}, ці голоси всередині рунічних кіл... схоже, що їх використовують для комунікації. Я здригаюся від самої думки про те, з якими жахливими почварами можна зв'язатися за допомогою такої магії. Проте тобі вдалося залишитися {стать:цілим та неушкодженим:цілою та неушкодженою}. Сріблястий Світанок цінує твою службу.", ["en"] = "Investigate the Scourge of the Undercity", ["tasks"] = { ["Dim Necrotic Stone"] = "тьмяний некротичний камінь", ["Dim Necrotic Stone (Provided)"] = "тьмяний некротичний камінь (видано)" } },
    [9266] = { [1] = "Відшкодування збитків", [4] = "Ти, мабуть, {стать:зробив:зробила} щось дуже погане нам або нашим друзям, {ім'я}. В будь-якому випадку, я тут, щоб запропонувати тобі спосіб відновити нашу прихильність.\n\nНа скільки ти знаєш, в Зимоключі досить холодно. Оскільки багато гоблінів приїжджає з інших міст, нам не завадить щось, що може зігріти. Принеси мені рунічне полотно і вугілля, і я замовлю за тебе слівце. Але попереджаю, наші вороги не зрадіють тому, що ти зробиш.", [5] = "Дякую тобі, {ім'я}. Якщо так піде і далі, то ти швидко спокутуєш свою провину перед нашим чесним містом.", ["en"] = "Making Amends", ["tasks"] = { ["Coal"] = "вугілля", ["Coal (Provided)"] = "вугілля (видано)", ["Runecloth"] = "рунічне полотно", ["Runecloth (Provided)"] = "рунічне полотно (видано)" } },
    [9267] = { [1] = "Виправлення старих помилок", [4] = "Подумай двічі, перш ніж ступити на землю Брашпиля, {ім'я}! Слава про твої брудні діяння випереджає тебе.\n\nТобі пощастило, корабель щойно причалив із багатьма пораненими від сутички із піратами Кривавого Вітрила. Це шанс довести, що ти не справжня свинота. Допоможи нам, роздобувши льняної тканини для пов'язок і порожніх фіалів для зілля.", [5] = "Я рада, що ти {стать:побачив:побачила} помилку свого світосприйняття, {ім'я}. Не припиняй постачання; від нас так легко не відкараскаєшся, {стать:пане:панночко}!", ["en"] = "Mending Old Wounds", ["tasks"] = { ["Empty Vial"] = "порожній фіал", ["Empty Vial (Provided)"] = "порожній фіал (видано)", ["Linen Cloth"] = "лляна тканина", ["Linen Cloth (Provided)"] = "лляна тканина (видано)" } },
    [92679] = { [1] = "Кривава десятина", [2] = "В... Привіт, незнайомцю. Ти виглядаєш здібним шукачем пригод. Я...\n\n<Небеснородний здригається, явно відчуваючи жахливий біль>\n\n...Мені було цікаво, чи шукаєш ти роботу? Я приїхав сюди до Валанаару, щоб завербувати бійців, які допоможуть врятувати мою ферму. Якщо ти зацікавлений, будь ласка, знайди мою дружину Аамелію Віндфілд у нашому саду на захід від Валанаару, у низовині.", [3] = "Послухайте, що каже Альваріон Віндфілд, і знайдіть Амелію Віндфілд у Віндфілдському саду.", ["en"] = "Blood Tithe", ["tasks"] = { ["Find Aamelia Windfield"] = "Знайдіть Амелію Віндфілд", ["Listen to Alvarion Windfield's Story"] = "Послухайте історію Алваріона Віндфілда" } },
    [9268] = { [1] = "Морський бій", [4] = "Ти хочеш знову подружитися з гоблінами Танарісу, {ім'я}? Нам потрібні матеріали для вітрил і зброя, щоб битися з нашими старими ворогами, піратами Кривавого Вітрила. Принеси мені маготкане полотно і сильний флюс, і ми будемо на шляху до прощення твоїх гріхів.", [5] = "Не зупиняйся, {ім'я}. Ми, гобліни, так просто не забуваємо образи!", ["en"] = "War at Sea", ["tasks"] = { ["Mageweave Cloth"] = "маготкане полотно", ["Mageweave Cloth (Provided)"] = "маготкане полотно (видано)", ["Strong Flux"] = "сильний флюс", ["Strong Flux (Provided)"] = "сильний флюс (видано)" } },
    [92682] = { [1] = "Зробіть себе корисним", [2] = "О, тож у тебе більше сміливості, ніж розуму? Гаразд, я не буду сперечатися.\n\nФерауу та його бандити ще не збираються збирати свій урожай, тому я змусю тебе працювати за їжу, поки вони не прибудуть.\n\nВиходь надвір і збирай для мене сьогоднішню партію яблук. О, а бандити, що чатують навколо яблук... Вони думають, що вони підступні. Але це не так. Убий їх для мене.\n\nПодивимося, на що ти здатний у бою.", [3] = "Зберіть 10 стиглих штормових яблук та вбийте 5 голодних бандитів у саду Віндфілд.", ["en"] = "Make Yourself Useful", ["tasks"] = { ["Hungry Bandit"] = "Голодний бандит", ["Hungry Bandit (Provided)"] = "Голодний бандит (видано)", ["Hungry Bandit slain"] = "Голодний бандит: убито", ["Ripe Stormapple"] = "Стиглий штормовий яблуко", ["Ripe Stormapple (Provided)"] = "Стиглий штормовий яблуко (видано)", ["Ripe Stormapple slain"] = "Стиглий штормовий яблуко: убито" } },
    [92683] = { [1] = "Пил від пурхаючої мухи", [2] = "Я впевнений, що ви помічали гігантських пурхачів на полях біля саду? На них приємно дивитися, але вони також мають інші переваги, а саме: пил з крил. Він може бути безладним, але якщо ви зможете зібрати його у великій кількості, він має корисне застосування в побуті.\n\nВізьміть цю мухобойку та добре пришлепайте великих комах від мене. Зазвичай вони просто лякаються та тікають, але іноді ображаються. У будь-якому разі, вони струсять свої зади та розкидають купу пилу.", [3] = "Зберіть 5 одиниць пилу з пурхаючих мух навколо низин Гостроягод.", ["en"] = "Flutterfly Dust", ["tasks"] = { ["Flutterfly Dust"] = "Пил від пурхаючої мухи", ["Flutterfly Dust (Provided)"] = "Пил від пурхаючої мухи (видано)", ["Flutterfly Dust slain"] = "Пил від пурхаючої мухи: убито", ["Flutterfly Swatter"] = "Мухобойка для пурхатих мух", ["Flutterfly Swatter (Provided)"] = "Мухобойка для пурхатих мух (видано)", ["Flutterfly Swatter slain"] = "Мухобойка для пурхатих мух: убито" } },
    [92684] = { [1] = "Зухвалий Зухвалий Буреносці", [2] = "Ніби цього року врожаю було недостатньо, вершники з околиць забираються в сад і крадуть мої шквальні яблука. Думаєш, можеш піти на поле і зібрати їх для мене?\n\nБудь обережний, незнайомцю, ці низинні вершники більші та зліші, ніж гірські. Бережи себе. Вчасного стусана достатньо, щоб остаточно тебе збити з ніг, якщо ти не будеш уважним.\n\nПринеси мені трохи їхнього м'яса, і я також можу приготувати нам гарячу страву.", [3] = "Зберіть 7 вирізок низинного галестрідера з зловмисних галестрідерів, яких можна знайти по всій низовині Гастберрі.", ["en"] = "Ornery Ornery Galestriders", ["tasks"] = { ["Lowlands Galestrider Tenderloin"] = "Вирізка низинного в'юнного в'юнка", ["Lowlands Galestrider Tenderloin (Provided)"] = "Вирізка низинного в'юнного в'юнка (видано)", ["Lowlands Galestrider Tenderloin slain"] = "Вирізка низинного в'юнного в'юнка: убито" } },
    [92685] = { [1] = "Пагорби мають очі", [2] = "У бандитів табори повсюди, і є невеликий у пагорбах трохи північніше звідси. Підніміться туди та почніть розбивати черепи. Якщо ми зможемо заскочити їх зненацька та знищити, перш ніж вони прийдуть за нами, ми можемо зрівняти шанси.\n\nПринесіть мені їхні маски. Чим кривавіші, тим краще.", [3] = "Здобичіть 7 закривавлених масок бандитів у розбійників-розбійників у низовині Гастберрі.", ["en"] = "The Hills Have Eyes", ["tasks"] = { ["Blood-Stained Bandit Mask"] = "Маска бандита, заплямована кров'ю", ["Blood-Stained Bandit Mask (Provided)"] = "Маска бандита, заплямована кров'ю (видано)", ["Blood-Stained Bandit Mask slain"] = "Маска бандита, заплямована кров'ю: убито" } },
    [9269] = { [1] = "Атієш, великий посох Вартівника", [2] = "Останнє завдання буде найскладнішим, {ім'я}. Ти вже {стать:здолав:здолала} Старого Бога і генерала Короля-Ліча, але тепер тобі доведеться зустрітися з рукою Сарґераса.\n\nВізьми посох і вирушай до Стратгольма. Там ти знайдеш клаптик освяченої землі: землі, де полягли найкращі лицарі Лордерона. Поклади осквернений посох на святу землю і приготуйся до бою з надзвичайно могутньою істотою, що вирветься зсередини... Переможи демона, що контролює посох, і повертайся до мене.", [3] = "Анахронос з Печер Часу, що в Танарісі, просить вас віднести Атієш, великий посох Вартівника, до Стратгольма і використати його на освяченій землі. Здолайте сутність, що з'явиться з посоха, і поверніться до Анахроноса.", [4] = "Я не повинен втручатися, {раса:к}.", [5] = "Велич цього досягнення не можна применшувати, {ім'я:к}. Ти {стать:зробив:зробила} те, що інші вважали б неможливим. Однак, такою була доля. Посох зробив свій вибір...", ["en"] = "Atiesh, Greatstaff of the Guardian", ["tasks"] = { ["Atiesh Cleansed"] = "Атієш Очищений", ["Atiesh Cleansed (Provided)"] = "Атієш Очищений (видано)", ["Atiesh Cleansed slain"] = "Атієш Очищений: убито", ["Atiesh, Greatstaff of the Guardian"] = "Атієш, великий посох Вартівника", ["Atiesh, Greatstaff of the Guardian (Provided)"] = "Атієш, великий посох Вартівника (видано)" } },
    [92693] = { [1] = "Стоячи на своєму", [2] = "Ти багато зробив, щоб дати нам шанс на перемогу. Навіть якщо ми помремо сьогодні, ми принаймні знатимемо, що зробили все можливе.\n\nЦе твій останній шанс, незнайомцю. Якщо ти хочеш повернутися до Валанаару та прожити ще один день, я б тебе не звинувачував.\n\nЗ іншого боку, якщо ти справді любиш програні справи, просто дай мені знати, коли будеш готовий. Ми вийдемо туди з високо піднятою головою, і що станеться, те станеться.", [3] = "Поговоріть з Амелією Віндфілд, коли будете готові протистояти ватажку бандитів.", ["en"] = "Standing Our Ground", ["tasks"] = { ["Follow Aamelia and make your final stand"] = "Слідкуйте за Аамелією та зробіть свій останній крок", ["Speak with Aamelia Windfield"] = "Поговоріть з Амелією Віндфілд" } },
    [92698] = { [1] = "Яка моя мета?", [2] = "<Ви нахиляєтеся ближче, щоб спробувати почути слова, що доносяться з-під броньованих пластин гігантської конструкції.>\n\n...Помилка функції...\n\n...Запитання...\n\n...Що таке....\n\n...Функція...\n\n<Ці фрагментарні слова та фрази, здається, просто повторюються. Можливо, хтось поруч знає більше про цю конструкцію?>", [3] = "Поговоріть з Амелією Віндфілд про несправну конструкцію «Циклон».", ["en"] = "What Is My Purpose?" },
    [9270] = { [1] = "Атієш, великий посох Вартівника", [2] = "Останнє завдання буде найскладнішим, {ім'я}. Ти вже {стать:здолав:здолала} Старого Бога і генерала Короля-Ліча, але тепер тобі доведеться зустрітися з рукою Сарґераса.\n\nВізьми посох і вирушай до Стратгольма. Там ти знайдеш клаптик освяченої землі: землі, де полягли найкращі лицарі Лордерона. Поклади осквернений посох на святу землю і приготуйся до бою з надзвичайно могутньою істотою, що вирветься зсередини... Переможи демона, що контролює посох, і повертайся до мене.", [3] = "Анахронос з Печер Часу, що в Танарісі, просить вас віднести Атієш, великий посох Вартівника, до Стратгольма і використати його на освяченій землі. Здолайте сутність, що з'явиться з посоха, і поверніться до Анахроноса.", [4] = "Я не повинен втручатися, {раса:к}.", [5] = "Велич цього досягнення не можна применшувати, {ім'я:к}. Ти {стать:зробив:зробила} те, що інші вважали б неможливим. Однак, такою була доля. Посох зробив свій вибір...", ["en"] = "Atiesh, Greatstaff of the Guardian", ["tasks"] = { ["Atiesh Cleansed"] = "Атієш Очищений", ["Atiesh Cleansed (Provided)"] = "Атієш Очищений (видано)", ["Atiesh Cleansed slain"] = "Атієш Очищений: убито", ["Atiesh, Greatstaff of the Guardian"] = "Атієш, великий посох Вартівника", ["Atiesh, Greatstaff of the Guardian (Provided)"] = "Атієш, великий посох Вартівника (видано)" } },
    [92703] = { [1] = "Доносити новини", [2] = "Гадаю, мені здається неправильним продовжувати називати тебе незнайомцем після всього цього, тому... дякую, {ім'я}.\n\nЯкщо ти не проти і повернешся тим шляхом, будь ласка, повідом Альваріону, що тут сталося. Також скажи йому, що як тільки він встане на ноги, йому потрібно принести сюди вітроутворювач, щоб він оглянув цю конструкцію, аби переконатися, що вона безпечна для нашої... нашої родини.\n\n<Амелія ніжно торкається свого живота.>\n\nВін не знає про це. Давай поки що залишимо це між нами.", [3] = "Поговоріть з Алваріоном Віндфілдом у Валанаарі.", ["en"] = "Deliver the News" },
    [92706] = { [1] = "РОЗШУКУЄТЬСЯ: Брууз", [2] = "Заклик до всіх рибалок!\n\nГігантська акула кружляє над водами біля судноплавного доку, нападаючи на моряків та невеликі човни. Докери дали їй прізвисько «Брууз». Тому, хто принесе мені її плавник, буде надана щедра винагорода!\n\n-- Газлоу", [3] = "Принесіть спинний плавець Брууза Газлоу в Ретчет.", ["en"] = "WANTED: Bruuz", ["tasks"] = { ["Bruuz's Dorsal Fin"] = "Спинний плавець Брууза" } },
    [9271] = { [1] = "Атієш, великий посох Вартівника", [2] = "Останнє завдання буде найскладнішим, {ім'я}. Ти вже {стать:здолав:здолала} Старого Бога і генерала Короля-Ліча, але тепер тобі доведеться зустрітися з рукою Сарґераса.\n\nВізьми посох і вирушай до Стратгольма. Там ти знайдеш клаптик освяченої землі: землі, де полягли найкращі лицарі Лордерона. Поклади осквернений посох на святу землю і приготуйся до бою з надзвичайно могутньою істотою, що вирветься зсередини... Переможи демона, що контролює посох, і повертайся до мене.", [3] = "Анахронос з Печер Часу, що в Танарісі, просить вас віднести Атієш, великий посох Вартівника, до Стратгольма і використати його на освяченій землі. Здолайте сутність, що з'явиться з посоха, і поверніться до Анахроноса.", [4] = "Я не повинен втручатися, {раса:к}.", [5] = "Велич цього досягнення не можна применшувати, {ім'я:к}. Ти {стать:зробив:зробила} те, що інші вважали б неможливим. Однак, такою була доля. Посох зробив свій вибір...", ["en"] = "Atiesh, Greatstaff of the Guardian", ["tasks"] = { ["Atiesh Cleansed"] = "Атієш Очищений", ["Atiesh Cleansed (Provided)"] = "Атієш Очищений (видано)", ["Atiesh Cleansed slain"] = "Атієш Очищений: убито", ["Atiesh, Greatstaff of the Guardian"] = "Атієш, великий посох Вартівника", ["Atiesh, Greatstaff of the Guardian (Provided)"] = "Атієш, великий посох Вартівника (видано)" } },
    [9272] = { [1] = "Перевдягання", [5] = "Аррр... Якщо тобі подобається компанія досвідчених морських псів, тобі краще припинити вдягатися, як розбишака! Ось, вдягни щось пристойне, поки я не здер з тебе шкуру.\n\nЦе тобі пасуватиме краще, ніж тому старому псові, Червоноокому Бену. Ми втратили його в морському штормі.\n\nНоси це з гордістю, {стать:друже:подруго}!", ["en"] = "Dressing the Part" },
    [9273] = { [1] = "Активуйте призовий ваучер iCoke", ["en"] = "Redeem iCoke Prize Voucher", ["tasks"] = { ["iCoke Prize Voucher"] = "Призовий ваучер iCoke" } },
    [928] = { [1] = "Вінець Землі", [2] = "Хоча я й можу далі говорити про місячні колодязі та Тельдрассіль, я все ж змушений направити тебе далі. Корітрас Місяцелють очікуватиме на тебе. Я вилив воду, принесену тобою, в цю посудину, щоб передати йому.\n\nВідшукай Корітраса. Ти знайдеш його біля місячного колодязя у Доланаарі. Слідуй дорогою на південь від Альдрассіля до Тінистої долини, а далі поверни по бруківці на захід.\n\nОднак стеж, щоб ти {стать:залишався:залишалася} на дорозі, {ім'я}. У лісах віднедавна бродять багато небезпечних створінь.", [3] = "Принесіть частково наповнену ємність Корітрасу Місяцелюті в Доланаарі.", [4] = "Вітаю, {клас:к}. Чим я заслужив на радість нашої зустрічі?", [5] = "А-а, я розумію. Тебе прислав Тенарон. Що ж, схоже, у нас є багато про що поговорити, багато що зробити та мало часу на це все.\n\nМабуть, нам варто починати вже.", ["en"] = "Crown of the Earth", ["tasks"] = { ["Partially Filled Vessel"] = "частково наповнена ємність", ["Partially Filled Vessel (Provided)"] = "частково наповнена ємність (видано)" } },
    [92812] = { [1] = "Економічна війна", ["en"] = "Economic Warfare", ["tasks"] = { ["Carved Centaur Totem"] = "Різьблений тотем кентавра" } },
    [92880] = { [1] = "Повернення до Валанаару", [2] = "Підозрюю, що нам знадобиться трохи часу, щоб знищити залишки нападників, але зараз наші шанси набагато кращі. Повертайтеся до Валанаару та повідомте їм, що наша ситуація тут стабільна.\n\nЯ не можу висловити вам достатньо подяки за вашу допомогу. Без вас нам було б набагато гірше. Я попросив підкріплення, а натомість, схоже, отримав героя, що розквітає. Я це прийму.\n\nХай благословить вас світ, {клас}.", [3] = "Віднесіть звіт Йорни до Валеннії Буревісник у Валанаар.", ["en"] = "Return to Valanaar" },
    [92881] = { [1] = "Прохання Верховного Старійшини", [2] = "Напад на західну та східну сторожові вежі не є випадковістю. Виходячи з того, що ви розповіли нам про те, що сталося на західній сторожовій вежі з тим небесним жерцем, ми гадаємо, що культ намагається щось зробити з опорними пілонами.\n\nБудь ласка, поговоріть з Верховним Старійшиною Тіньопіснею. Він розповість вам про зачіпку, яка може виявитися багатообіцяючою.", [3] = "Поговоріть із Талаанісом Шодосонг у Валанаарі.", ["en"] = "The High Elder's Request" },
    [9292] = { [1] = "Тріснутий некротичний кристал", [2] = "Ну трупі мертвої потвори ви бачите тріснутий кристал, що повільно пульсує некротичною енергією.", [3] = "Принесіть тріснутий некротичний камінь лейтенанту Орріну біля воріт Штормовію.", [4] = "Тобі щось потрібно?", [5] = "Хм, ти {стать:взяв:взяла} це з трупа одного із загарбників?\n\nМи отримали повідомлення про табори з некрополями, які викликає Скара. Підозрюю, що вони хотіли створити такий в самому Штормовії. Дуже добре, що їм це не вдалося.", ["en"] = "Cracked Necrotic Crystal", ["tasks"] = { ["Cracked Necrotic Crystal"] = "тріснутий некротичний кристал", ["Cracked Necrotic Crystal (Provided)"] = "тріснутий некротичний кристал (видано)" } },
    [92947] = { [1] = "Робимо наш крок", [2] = "Всі тут, добре. Я щойно відправив кількох своїх найкращих бійців через передню частину святилища, щоб створити трохи проблем і відволікти увагу, поки я веду Вітротворців та Вищий Орден з флангу.\n\nЯкщо все піде добре, ми зможемо швидко пробитися та знищити Верховну Жрицю. А ти заходь туди та починай розбивати черепи. Зустрінь мою помічницю, Х'юсу Швидкий Бриз, біля сходів до святилища після того, як створиш трохи проблем.\n\nВітри тобі на руку, {клас}.", [3] = "Убийте 8 Вартових Ал'Акета, 6 Заклиначів Духів Ал'Акета та 6 Майстрів Клинків Ал'Акета, а потім зверніться до Х'юсаї Швидкий Бриз у Святилище Акіра.", ["en"] = "Making Our Move", ["tasks"] = { ["Al'Aketh Blademaster"] = "Майстер клинка Ал'Акет", ["Al'Aketh Blademaster (Provided)"] = "Майстер клинка Ал'Акет (видано)", ["Al'Aketh Blademaster slain"] = "Майстер клинка Ал'Акет: убито", ["Al'Aketh Guardian"] = "Аль'Акет Гардіан", ["Al'Aketh Guardian (Provided)"] = "Аль'Акет Гардіан (видано)", ["Al'Aketh Guardian slain"] = "Аль'Акет Гардіан: убито", ["Al'Aketh Spiritcaller"] = "Ал'Акет, заклинатель духів", ["Al'Aketh Spiritcaller (Provided)"] = "Ал'Акет, заклинатель духів (видано)", ["Al'Aketh Spiritcaller slain"] = "Ал'Акет, заклинатель духів: убито", ["Report to Hyusaa Quickbreeze"] = "Звітувати до Х'юсаа Квікбріз" } },
    [9295] = { [1] = "Лист з фронту", [2] = "Ви знайшли цей лист в одного з вбитих посіпак Скари. Судячи з вигляду та запаху, він був у невмерлого довгий час. Можливо, комусь в Каплиці Надії Світла буде цікаво поглянути...", [3] = "Віднесіть порваного листа Архіваріусу в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Так? Що у тебе там?", [5] = "Яка трагедія. Ці слова, явно призначені для когось, кого солдат любив, так і не дійшли до адресата. Описані події відбулися багато років тому. Я не впевнений, чи ще жива та, кому вони адресовані.\n\nОднак надія ще є. З цими іменами та інформацією з листа я, можливо, зможу знайти родину! Це потребуватиме деяких досліджень, але бібліотекар у Штормовії винен мені послугу...\n\nДякую, що {стать:приніс:принесла} це мені. Можливо, це допоможе комусь знайти хоч трохи душевного спокою.", ["en"] = "Letter from the Front", ["tasks"] = { ["A Torn Letter"] = "порваний лист", ["A Torn Letter (Provided)"] = "порваний лист (видано)" } },
    [9296] = { [1] = "повторне використання", [2] = "Цей камінь випромінює темну енергію. Тобі слід доставити його КОМУСЬ.", ["en"] = "reuse", ["tasks"] = { ["Cracked Necrotic Crystal"] = "тріснутий некротичний кристал", ["Cracked Necrotic Crystal (Provided)"] = "тріснутий некротичний кристал (видано)" } },
    [9297] = { [1] = "повторне використання", [2] = "Цей камінь випромінює темну енергію. Тобі слід доставити його КОМУСЬ.", ["en"] = "reuse", ["tasks"] = { ["Cracked Necrotic Crystal"] = "тріснутий некротичний кристал", ["Cracked Necrotic Crystal (Provided)"] = "тріснутий некротичний кристал (видано)" } },
    [9298] = { [1] = "повторне використання", [2] = "Цей камінь випромінює темну енергію. Тобі слід доставити його КОМУСЬ.", ["en"] = "reuse", ["tasks"] = { ["Cracked Necrotic Crystal"] = "тріснутий некротичний кристал", ["Cracked Necrotic Crystal (Provided)"] = "тріснутий некротичний кристал (видано)" } },
    [9299] = { [1] = "Записка з фронту", [2] = "Ви знайшли цю записку в одного з вбитих посіпак Скари. Судячи з вигляду та запаху, вона була у невмерлого довгий час. Можливо, комусь в Каплиці Надії Світла буде цікаво поглянути...", [3] = "Віднесіть потерту записку Архіваріусу в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Так? Що у тебе там?", [5] = "Яка трагедія. Ці слова, явно призначені для когось, кого солдат любив, так і не дійшли до адресата. Описані події відбулися багато років тому. Я не впевнений, чи ще жива та, кому вони адресовані.\n\nОднак надія ще є. З цими іменами та інформацією з листа я, можливо, зможу знайти родину! Це потребуватиме деяких досліджень, але бібліотекар у Штормовії винен мені послугу...\n\nДякую, що {стать:приніс:принесла} це мені. Можливо, це допоможе комусь знайти хоч трохи душевного спокою.", ["en"] = "Note from the Front", ["tasks"] = { ["A Careworn Note"] = "потерта записка", ["A Careworn Note (Provided)"] = "потерта записка (видано)" } },
    [9300] = { [1] = "Сторінка з фронту", [2] = "Ви знайшли цю сторінку в одного з вбитих посіпак Скари. Судячи з вигляду та запаху, вона була у невмерлого довгий час. Можливо, комусь в Каплиці Надії Світла буде цікаво поглянути...", [3] = "Віднесіть пошарпану сторінку Архіваріусу в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Так? Що у тебе там?", [5] = "Яка трагедія. Ці слова, явно призначені для когось, кого солдат любив, так і не дійшли до адресата. Описані події відбулися багато років тому. Я не впевнений, чи ще жива та, кому вони адресовані.\n\nОднак надія ще є. З цими іменами та інформацією з листа я, можливо, зможу знайти родину! Це потребуватиме деяких досліджень, але бібліотекар у Штормовії винен мені послугу...\n\nДякую, що {стать:приніс:принесла} це мені. Можливо, це допоможе комусь знайти хоч трохи душевного спокою.", ["en"] = "Page from the Front", ["tasks"] = { ["A Ragged Page"] = "пошарпана сторінка", ["A Ragged Page (Provided)"] = "пошарпана сторінка (видано)" } },
    [9301] = { [1] = "Конверт з фронту", [2] = "Ви знайшли цей конверт в одного з вбитих посіпак Скари. Судячи з вигляду та запаху, він був у невмерлого довгий час. Можливо, комусь в Каплиці Надії Світла буде цікаво поглянути...", [3] = "Віднесіть закривавлений конверт Архіваріусу в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Так? Що у тебе там?", [5] = "Яка трагедія. Ці слова, явно призначені для когось, кого солдат любив, так і не дійшли до адресата. Описані події відбулися багато років тому. Я не впевнений, чи ще жива та, кому вони адресовані.\n\nОднак надія ще є. З цими іменами та інформацією з листа я, можливо, зможу знайти родину! Це потребуватиме деяких досліджень, але бібліотекар у Штормовії винен мені послугу...\n\nДякую, що {стать:приніс:принесла} це мені. Можливо, це допоможе комусь знайти хоч трохи душевного спокою.", ["en"] = "Envelope from the Front", ["tasks"] = { ["A Bloodstained Envelope"] = "закривавлений конверт", ["A Bloodstained Envelope (Provided)"] = "закривавлений конверт (видано)" } },
    [9302] = { [1] = "Послання з фронту", [2] = "Ви знайшли це послання в одного з вбитих посіпак Скари. Судячи з вигляду та запаху, воно було у невмерлого довгий час. Можливо, комусь в Каплиці Надії Світла буде цікаво поглянути...", [3] = "Віднесіть зім'яте послання Архіваріусу в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Так? Що у тебе там?", [5] = "Яка трагедія. Ці слова, явно призначені для когось, кого солдат любив, так і не дійшли до адресата. Описані події відбулися багато років тому. Я не впевнений, чи ще жива та, кому вони адресовані.\n\nОднак надія ще є. З цими іменами та інформацією з листа я, можливо, зможу знайти родину! Це потребуватиме деяких досліджень, але бібліотекар у Штормовії винен мені послугу...\n\nДякую, що {стать:приніс:принесла} це мені. Можливо, це допоможе комусь знайти хоч трохи душевного спокою.", ["en"] = "Missive from the Front", ["tasks"] = { ["A Crumpled Missive"] = "зім'яте послання", ["A Crumpled Missive (Provided)"] = "зім'яте послання (видано)" } },
    [93036] = { [1] = "Проникнення в культ", [2] = "Можливо, ви знаєте про це, а можливо, й ні, але Санія Сільверстрім — «місіонерка» для Аль'Акет. Вони люблять грати в звичайний релігійний орден і надсилають безпечних посланців для вербування. Досі ми терпіли Санію, щоб уникнути прямого конфлікту з культом, але очевидно, що ілюзія миру триватиме недовго.\n\nВи тут новачок і невідомий більшості, тому я хотів би побачити, чи зможете ви використати Санію, щоб наблизитися до культу та дізнатися, які їхні плани щодо села.", [3] = "Поговоріть із Санією Сільверстрім у селі Шен'дар.", ["en"] = "Infiltrating the Cult" },
    [9304] = { [1] = "Документ з фронту", [2] = "Ви знайшли цей лист в одного з вбитих посіпак Скари. Судячи з вигляду та запаху, він був у невмерлого довгий час. Можливо, комусь в Каплиці Надії Світла буде цікаво поглянути...", [3] = "Віднесіть вкритий брудом документ Архіваріусу в Каплицю Надії Світла, що в Східних Зачумлених землях.", [4] = "Так? Що у тебе там?", [5] = "Яка трагедія. Ці слова, явно призначені для когось, кого солдат любив, так і не дійшли до адресата. Описані події відбулися багато років тому. Я не впевнений, чи ще жива та, кому вони адресовані.\n\nОднак надія ще є. З цими іменами та інформацією з листа я, можливо, зможу знайти родину! Це потребуватиме деяких досліджень, але бібліотекар у Штормовії винен мені послугу...\n\nДякую, що {стать:приніс:принесла} це мені. Можливо, це допоможе комусь знайти хоч трохи душевного спокою.", ["en"] = "Document from the Front", ["tasks"] = { ["A Smudged Document"] = "вкритий брудом документ", ["A Smudged Document (Provided)"] = "вкритий брудом документ (видано)" } },
    [93065] = { [1] = "Підготуйтеся до битви", [2] = "Миротворці мобілізуються, і ми всі готуємося вирушити в дорогу. Зробіть усе необхідне та зустріньте нас на східній дорозі, що веде на північ з міста. Ми проведемо останню зустріч з усіма, перш ніж вирушити.", [3] = "Поговоріть з Валенією Буревісник у Низині Гастберрі.", ["en"] = "Prepare for Battle", ["tasks"] = { ["Find Valennia on the Road"] = "Знайдіть Валенію на дорозі" } },
    [93066] = { [1] = "Відступ Щетиношкурих", [2] = "На іншому боці долини ми закріпилися на невеликому плацдармі, готуючись вирушити в сусідній ліс. Перш ніж іти туди, розберися зі Щетиношкурими, які нещодавно вторглися на ці землі. Здається, вони прибули майже одночасно з нами, але встигли заволодіти артефактом із сусіднього храму, який не дає нам наблизитися.\n\nЗавдання просте. Шукай терни та свиней. Убий якнайбільше, не розбираючи. Потім доповіси Гаґіаку в таборі, про який я говорив.", ["en"] = "Bristleback Retreat", ["tasks"] = { ["Bristleback Nomad"] = "Щетиношкурий кочівник", ["Bristleback Nomad slain"] = "Щетиношкурий кочівник: убито", ["Bristleback Skullcrusher"] = "Щетиношкурий черепотрощ", ["Bristleback Skullcrusher slain"] = "Щетиношкурий черепотрощ: убито", ["Bristleback Thornweaver"] = "Щетиношкурий терноткач", ["Bristleback Thornweaver slain"] = "Щетиношкурий терноткач: убито", ["Magram Clan Centaur"] = "Кентавр клану Маґрамів" } },
    [93072] = { [1] = "Довготривалі рішення", [2] = "На південному заході є ще одне поселення кентаврів. Воно належить Ґелкісам. Очікуєш, що я пошлю тебе туди пролити трохи крові? Добре. Саме це й має спадати тобі на думку насамперед, інакше я засумнівався б у твоїй вірності Маґрамам!\n\nЧого чекаєш? Уперед! Убивай!", [3] = "Зберігайте репутацію з кланом Маґрамів, убийте 2 розвідників-вигнанців, 6 мародерів-вигнанців і 8 некромантів-вигнанців, а потім поверніться до Гаґіака на фронт Маґрамів.", ["en"] = "Long-Term Solutions", ["tasks"] = { ["Outcast Marauder"] = "Мародер-вигнанець", ["Outcast Marauder slain"] = "Мародер-вигнанець: убито", ["Outcast Necromancer"] = "Некромант-вигнанець", ["Outcast Necromancer slain"] = "Некромант-вигнанець: убито", ["Outcast Scout"] = "Розвідник-вигнанець", ["Outcast Scout slain"] = "Розвідник-вигнанець: убито" } },
    [9310] = { [1] = "Тьмяний некротичний кристал", [2] = "На трупі мертвої потвори ви бачите кристал, який ледь-ледь випромінює некротичну енергію.", [3] = "Принесіть тьмяний некротичний кристал лейтенанту Рукаґу у внутрішній двір Підмістя.", [4] = "Чим я можу тобі допомогти?", [5] = "Хм, ти {стать:взяв:взяла} це з трупа одного із загарбників?\n\nМи отримали повідомлення про табори з некрополями, які викликає Скара. Підозрюю, що вони намагались створити такий в самому Підмісті. Ми повинні бути пильними.", ["en"] = "Faint Necrotic Crystal", ["tasks"] = { ["Faint Necrotic Crystal"] = "тьмяний некротичний кристал", ["Faint Necrotic Crystal (Provided)"] = "тьмяний некротичний кристал (видано)", ["Faint Necrotic Crystal slain"] = "тьмяний некротичний кристал: убито" } },
    [93129] = { [1] = "Загроза голоду", [2] = "Оскільки ти так палко прагнеш допомогти нашому клану, певен, ти охоче дістанеш трохи припасів, поки будеш у сховку вигнанців.\n\nДля Маґрама вбивство наших ворогів саме по собі — достатній стимул, але не бачу причин не отримати з цього ще й користь.\n\nКоли розберемося з вигнанцями, зможемо закріпити це місце за Маґрамами й зібрати військо, яке поставить інші клани на коліна!", ["en"] = "Threat of Starvation", ["tasks"] = { ["Magram Clan Centaur"] = "Кентавр клану Маґрамів", ["Stolen Supplies"] = "Вкрадені припаси" } },
    [93159] = { [1] = "Дивний відлюдник", [2] = "Е-е, гм... привіт, я маю на увазі привіт! Навіть вітання! Вибачте... гм, так давно я востаннє ні з ким не розмовляв. Боюся, я трохи не вправний у цьому.\n\n<Дивна постать у капюшоні незручно ворушиться перед вами.>\n\nОтже, гм... як проходить ваш день?", [3] = "Поговоріть із Дивним Відлюдником у Лісі Тіней та дізнайтеся про нього більше.", ["en"] = "The Strange Hermit", ["tasks"] = { ["Learn more about the Strange Hermit"] = "Дізнайтеся більше про Дивного Відлюдника" } },
    [93160] = { [1] = "Лісові щедрості", [2] = "Я дуже вдячний вам за те, що ви завітали поговорити зі мною! Я-якщо ви хочете допомогти, мені потрібна ваша допомога зі збиранням жолудів з лісової підстилки. Я зібрав більшість жолудів поблизу, але в лісі точно багато хижих птахів. Там небезпечно, і я б не хотів стати обідом для велетенського птаха!\n\nТож, якщо хочете, можете зібрати їх для мене? Я приготую нам щось смачненьке, якщо ви це зробите!", [3] = "Зберіть 8 жолудів Тіньогейлу в Тіньогейльському лісі.", ["en"] = "The Forest's Bounty", ["tasks"] = { ["Zephyrseed"] = "Зефірне насіння" } },
    [93165] = { [1] = "Милосердя не чують", [2] = "Ал'Акет завдали великої трагедії нашому анклаву, і за кров треба відплатити кров'ю.\n\nУ мене є пропозиція для тебе, незнайомцю. Якщо ти зіткнешся з цими проклятими культистами, принеси мені вуха тих, кого вб'єш. Я винагороджу тебе за кожну, яку ти повернеш, як грошима, так і, з часом, доступом до таємниць Нічного Кігтя, якщо ти доведеш, що ти справжній друг.", [3] = "Зберіть 10 вух культиста Ал'Акета у культистів Ал'Акета в Тіньоголовому лісі, Сяйві Акіра або Низині Густберрі.", ["en"] = "Mercy Falls on Deaf Ears", ["tasks"] = { ["Al'Alketh Cultist's Ear"] = "Вухо культиста Ал'Алкета", ["Al'Alketh Cultist's Ear (Provided)"] = "Вухо культиста Ал'Алкета (видано)", ["Al'Alketh Cultist's Ear slain"] = "Вухо культиста Ал'Алкета: убито" } },
    [93172] = { [1] = "Звільніть Порожняків", [2] = "Більшість ельфів на цьому острові, здається, вважають, що в цьому лісі живуть привиди, і вони не помиляються.\n\nУ старих руїнах на північному сході збираються дивні духи, схожі на привидів. Інколи ночами можна майже почути, як вони «співають». Це не схоже на жодну пісню, яку я чув раніше, але це точно пісня, і вона... просто така сумна.\n\nЯ не впевнений чому, але мені здається, що там у якийсь момент сталося щось жахливе, і духи якось там застрягли. Якщо ви відчуваєте сміливість, можливо, ви можете допомогти їм звільнитися?", [3] = "Знищити 10 Вітряних Ущелин у Тіньовій Лісі.", ["en"] = "Free the Hollows", ["tasks"] = { ["Wind Hollow freed"] = "Звільнена Вітряна Долина" } },
    [93173] = { [1] = "(UNUSED) Іржавий пристрій", [2] = "<Коли бурхливі потоки, що утримують Вітряну западину, починають розсіюватися, до ваших ніг падає невеликий металевий пристрій. Здається, це якась механічна штуковина. Дивний відлюдник казав, що йому досі бракує деякого обладнання. Можливо, це його зацікавить.>", ["en"] = "(UNUSED) The Rusty Gadget", ["tasks"] = { ["Rusty Gadget (Provided)"] = "Іржавий пристрій (видано)" } },
    [93176] = { [1] = "Мої маленькі друзі", [2] = "Милуєшся моїм маленьким звіринцем? Це справа всього мого нежиття. Я витратив незліченні години, вивчаючи їхню будову, харчування й навіть суспільні звичаї.\n\nХочеш долучитися до мого захоплення? Ось, візьми цей пакунок. Нотатки й матеріали всередині допоможуть тобі почати. Якщо загубиш його, доведеться купити в мене ще один за невелику плату.", ["en"] = "My Little Friends", ["tasks"] = { ["Arbor Tarantula Specimen"] = "зразок деревного тарантула", ["Flesh Picker Specimen"] = "зразок плотокуса", ["Hay Weevil Specimen"] = "зразок сінного довгоносика" } },
    [9319] = { [1] = "Світло у темних місцях", [2] = "Ми не єдині, хто святкує це свято, {ім'я}. Усі створіння, усі культури осяяні полум'ям. Навіть у найтемніших місцях запалюються вогні.\n\nЯкщо ти бажаєш побачити їх особисто, йди в глибини. Знайди вогні, що горять у Стратгольмі, Некроситеті, серед огрів Грізного Молота та у залах Чорноскельного шпиля. Я чекатиму на твоє повернення.", [3] = "Знайдіть і доторкніться до вогнищ, розташованих у Чорноскельному шпилі, Грізному Молоті, Некроситеті та Стратгольмі, а потім поверніться до хранителя полум'я фестивалю.", [4] = "Чи {стать:знайшов:знайшла} ти шлях крізь темряву?", [5] = "Твоя сутність співає енергією знайденого тобою полум'я, {ім'я}. Вогонь, з яким тобі довелося зіткнутися, потужний, і з правильним знанням його силу можна використати...\n\n<Хранитель полум'я бурмоче заклинання дивною, таємничою мовою, а потім витягує пляшку, що світиться.>\n\nА! Ось. Нехай це осяє твій шлях, куди б ти не {стать:йшов:йшла}.", ["en"] = "A Light in Dark Places", ["tasks"] = { ["Flame of Blackrock Spire"] = "Полум'я Шпиля Чорної Скелі", ["Flame of Blackrock Spire (Provided)"] = "Полум'я Шпиля Чорної Скелі (видано)", ["Flame of Blackrock Spire slain"] = "Полум'я Шпиля Чорної Скелі: убито", ["Flame of Dire Maul"] = "Полум'я Запеклого Молота", ["Flame of Dire Maul (Provided)"] = "Полум'я Запеклого Молота (видано)", ["Flame of Dire Maul slain"] = "Полум'я Запеклого Молота: убито", ["Flame of Stratholme"] = "Полум'я Стратгольма", ["Flame of Stratholme (Provided)"] = "Полум'я Стратгольма (видано)", ["Flame of Stratholme slain"] = "Полум'я Стратгольма: убито", ["Flame of the Scholomance"] = "Полум'я Несхольності", ["Flame of the Scholomance (Provided)"] = "Полум'я Несхольності (видано)", ["Flame of the Scholomance slain"] = "Полум'я Несхольності: убито" } },
    [9322] = { [1] = "Дикі вогні Калімдору", [2] = "Святкування вогняного фестивалю сонцестояння охоплює кожний куточок Азероту, і землі Калімдору не є винятком. Ти виглядаєш {стать:готовим:готовою} до подорожі — і, можливо, час відправлятися.\n\nПо справжньому насолодитися сонцестоянням можна, побачивши далекі блакитні вогні. Святкувальники запалили вогні на заході Зимоключа, на північному сході Азшари, біля Спочину Доблесті у пустелях Силітусу і біля входу в кратер Ун'Ґоро. Повертайся, коли закінчиш свою подорож.", [3] = "Відвідайте табори сонцестояння, розташовані в Азшарі, Силітусі, кратері Ун'Ґоро та Зимоключі, а потім поверніться до хранителя полум'я фестивалю.", [4] = "Чи яскраво горить полум'я Калімдору?", [5] = "Твій дух світиться теплом вогнів Калімдору, {стать:друже:подруго}. Хіба цей жар не підбадьорює?\n\nКоли сили покинуть тебе, можливо, ці речі допоможуть тобі розпалити це відчуття.", ["en"] = "Wild Fires in Kalimdor", ["tasks"] = { ["Flame of Azshara"] = "Полум'я Азшари", ["Flame of Azshara (Provided)"] = "Полум'я Азшари (видано)", ["Flame of Azshara slain"] = "Полум'я Азшари: убито", ["Flame of Silithus"] = "Полум'я Силітуса", ["Flame of Silithus (Provided)"] = "Полум'я Силітуса (видано)", ["Flame of Silithus slain"] = "Полум'я Силітуса: убито", ["Flame of Un'Goro"] = "Полум'я Ун'Горо", ["Flame of Un'Goro (Provided)"] = "Полум'я Ун'Горо (видано)", ["Flame of Un'Goro slain"] = "Полум'я Ун'Горо: убито", ["Flame of Winterspring"] = "Полум'я Зимоключа", ["Flame of Winterspring (Provided)"] = "Полум'я Зимоключа (видано)", ["Flame of Winterspring slain"] = "Полум'я Зимоключа: убито" } },
    [93227] = { [1] = "Купівля дружби: Ґелкіси", [2] = "На перший погляд, я б сказав, що Ґелкісам сутужно. Їх значно менше, ніж Маґрамів, та й наші розвідники рідко повідомляють про їхні походи.\n\nІ все ж вони — один із панівних кланів Спустошища й досі виживають. Значить, щось вони роблять правильно.\n\nЯкщо хочеш помиритися з Ґелкісами, візьми цю торбу тотемів і рушай до їхнього поселення далеко на південному заході. Хоч які вони примітивні, якийсь скарбник у них, напевно, знайдеться.", ["en"] = "Buying Friendship: Gelkis", ["tasks"] = { ["Totem Tote (Provided)"] = "Торба для тотемів (видано)" } },
    [9323] = { [1] = "Дикі вогні Східних Королівств", [2] = "Наше свято полум'я розповсюджується по всій землі, {клас:к}. Немає жодного місця, яке б не отримало тепло цього свята, а найсильніші вогнища горять яскравим блакитним полум'ям. Знайди їх.\n\nОдне з них знаходиться північніше Чорноскельного шпилю. Інші розташовані вглиб Східних Зачумлених земель біля покинутого міста, вздовж дороги до скель у Внутрішніх землях, і на шляху до Темного Порталу у Спустошених землях.\n\nПовертайся, коли завершиш свою подорож.", [3] = "Відвідайте табори сонцестояння, розташовані у Спустошених землях, Східних Зачумлених землях, Внутрішніх землях та Випаленій ущелині, а потім поговоріть з хранителем полум'я фестивалю.", [4] = "Чи яскраво горить полум'я Східних Королівств?", [5] = "А, ось і ти. Трохи {стать:втомлений:втомлена}, трохи {стать:запилений:запилена}, але {стать:просвітлений:просвітлена}! Тепло обіймає та об'єднує всіх нас цієї пори. Саме твоє єство світиться силою вогню, якого ти {стать:доторкнувся:доторкнулася}.\n\nАле, якось так сталося, що просвітлення зараз вважається не надто цінною винагородою за виконане завдання. Тож нехай ці дари заспокоять тебе. Насолоджуйся святкуванням.", ["en"] = "Wild Fires in the Eastern Kingdoms", ["tasks"] = { ["Flame of Searing Gorge"] = "Полум'я Палаючої Ущелини", ["Flame of Searing Gorge (Provided)"] = "Полум'я Палаючої Ущелини (видано)", ["Flame of Searing Gorge slain"] = "Полум'я Палаючої Ущелини: убито", ["Flame of the Blasted Lands"] = "Полум'я вируйнованої землі", ["Flame of the Blasted Lands (Provided)"] = "Полум'я вируйнованої землі (видано)", ["Flame of the Blasted Lands slain"] = "Полум'я вируйнованої землі: убито", ["Flame of the Hinterlands"] = "Полум'я глибинок", ["Flame of the Hinterlands (Provided)"] = "Полум'я глибинок (видано)", ["Flame of the Hinterlands slain"] = "Полум'я глибинок: убито", ["Flame of the Plaguelands"] = "Полум'я Чумних земель", ["Flame of the Plaguelands (Provided)"] = "Полум'я Чумних земель (видано)", ["Flame of the Plaguelands slain"] = "Полум'я Чумних земель: убито" } },
    [93317] = { [1] = "Сезон крабів", [2] = "Ви знайомі з повзунами Вітряної Пісні? Бачите, ці краби мешкають лише на озері Вітряної Пісні тут, на Зефрасі, і їх можна виловлювати лише кілька тижнів на рік.\n\nЧерез всю цю культову активність останнім часом я не зміг потрапити на озеро, щоб виловити їх, і наш час швидко закривається. Буду вдячний, якщо ви зможете піти та зібрати трохи для мене. Зазвичай їх можна знайти вздовж берегової лінії навколо озера та в річках.\n\nАле будьте обережні, вони підступніші, ніж здаються!", [3] = "Зберіть 6 шматків м'яса повзуна Вітропісні.", ["en"] = "Crab Season", ["tasks"] = { ["Windsong Crawler Meat"] = "М'ясо повзуна Вітропісні", ["Windsong Crawler Meat (Provided)"] = "М'ясо повзуна Вітропісні (видано)", ["Windsong Crawler Meat slain"] = "М'ясо повзуна Вітропісні: убито" } },
    [93318] = { [1] = "РОЗШУКУЄТЬСЯ: Вульгара Ненаситна", [2] = "За наказом констебля Аонди з Миротворців, цим призначається винагорода за бича високогір'я, Вульгару Ненаситну. Востаннє помічений на вершині пагорба трохи південно-захід від села Шен'дар, крилатий жах вульдренів є дуже небезпечним і до нього слід підходити з обережністю.\n\nДоставте голову звіра Данарії Беллоувейл, щоб отримати свою винагороду.", [3] = "Убийте Вулгару Ненаситну у Шен'дарському нагір'ї та принесіть її голову Данарії Беллоувейл.", ["en"] = "WANTED: Vulgara the Insatiable", ["tasks"] = { ["Vulgara's Head"] = "Голова Вульгари", ["Vulgara's Head (Provided)"] = "Голова Вульгари (видано)", ["Vulgara's Head slain"] = "Голова Вульгари: убито" } },
    [93319] = { [1] = "Вкрадені вітряні камені", [2] = "Ми дедалі більше покладаємося на вітряні камені для повсякденного життя тут, на Зефрасі, тому намагаємося тримати їх у запасі на випадок надзвичайних ситуацій. Останнім часом я помітив, що деякі з них зникають з наших запасів.\n\nМи знайшли вітряні камені на бандитах, яких нещодавно спіймали, і я підозрюю, що вони є причиною нашої нестачі.\n\nЯкщо ви опинитеся біля печери бандитів на півночі, чи не могли б ви зіткнутися кількома головами та повернути мені деякі з наших вкрадених вітряних каменів?", [3] = "Зберіть 10 вкрадених вітряних каменів у бандитів нагір'я у нагір'ї Шен'дар.", ["en"] = "Pilfered Windstones", ["tasks"] = { ["Pilfered Windstone"] = "Вкрадений вітряний камінь", ["Pilfered Windstone (Provided)"] = "Вкрадений вітряний камінь (видано)", ["Pilfered Windstone slain"] = "Вкрадений вітряний камінь: убито" } },
    [93320] = { [1] = "Захист вежі", [2] = "Я щойно отримав звістку, що культ атакує сторожову вежу-пілон одразу за містом! Я відправив кількох додаткових миротворців, які в нас є, щоб спробувати прорватися крізь ворожу лінію тилу та допомогти захисникам, але будь-яка додаткова допомога може вирішити, чи наші люди там виживуть, чи помруть.\n\nБудь ласка, негайно вирушайте до східної сторожової вежі та надайте будь-яку допомогу, яку можете.\n\nМоя лейтенантка Йорана Віндірід очолила сили допомоги. Якщо вона ще жива, вона зможе підказати вам, як найкраще допомогти.", [3] = "Зверніться до Йорани Віндірід на східній сторожовій вежі в низовині Гастберрі.", ["en"] = "Tower Defense" },
    [9338] = { [1] = "Вірність Кенарійському Колу", [4] = "Навіть якщо тобі не потрібні нагороди, які ми даємо, ці відзнаки свідчать про нашу взаємну довіру та дружбу.\n\nПринеси їх мені. Я пам'ятатиму про твою службу, навіть якщо наша співпраця вийде за рамки службового обов'язку.", [5] = "Велика честь для нас, працювати з тобою, {ім'я}. Завдяки твоїм зусиллям, нас не зупинять жодні перешкоди.", ["en"] = "Allegiance to Cenarion Circle", ["tasks"] = { ["Cenarion Combat Badge"] = "кенарійська бойова відзнака", ["Cenarion Combat Badge (Provided)"] = "кенарійська бойова відзнака (видано)", ["Cenarion Logistics Badge"] = "кенарійська логістична відзнака", ["Cenarion Logistics Badge (Provided)"] = "кенарійська логістична відзнака (видано)", ["Cenarion Tactical Badge"] = "кенарійська тактична відзнака", ["Cenarion Tactical Badge (Provided)"] = "кенарійська тактична відзнака (видано)" } },
    [934] = { [1] = "Вінець Землі", [2] = "Утім, з Тельдрассілем усе було не так добре, як того хотілося. Оленеріг склав ретельні плани, оскільки нове Дерево Життя виросло саме таким, як він мріяв. Але була одна невелика проблема — проблема, яка й стала причиною багатьох неприємностей на Тельдрассілі.\n\nОднак про це мені ще рано говорити. Ти {стать:повинен:повинна} відвідати останній місячний колодязь, розташований на північному заході, на Поляні Оракула. Під гіллям Дерева-оракула ти знайдеш перше, найпотужніше з наших джерел. Наповни фіал його водою та повертайся до мене.", [3] = "Наповніть аметистовий фіал і поверніть його Корітрасу Місяцелюті в Доланаарі.", [4] = "Друїди, Дерево-оракул та Верховний друїд пліч-о-пліч уважно спостерігали за ростом Тельдрассіля. І хоча тепер в нас є новий дім, безсмертне життя ми так і не змогли повернути.", [5] = "Перебувати у присутності Дерева-оракула... це так, неначе сама мудрість набула форми живого створіння. Але на чому я зупинився...\n\nТельдрассіль виріс, і Верховний друїд звернувся до драконів по їхні благословення, якими свого часу вони освятили Нордрассіль. Але Ноздорму, Володар Часу, відмовився дати своє благословення, докірливо звинувативши Фендрала в його нахабності. На підтриму Ноздорму Алекстраза також відмовила Оленерогові, і без її благословення подальший ріст Тельдрассіля був приреченим стати недосконалим та непередбачуваним.", ["en"] = "Crown of the Earth", ["tasks"] = { ["Vial of Blessed Water"] = "флакон з благословенною водою", ["Vial of Blessed Water (Provided)"] = "флакон з благословенною водою (видано)" } },
    [93459] = { [1] = "Більше вух Аль'Акет", [2] = "Культ Ал'Акет зазвичай обходить цей ліс стороною, боячись чуток про те, що в ньому населяють привиди... чуток, які ми раді підтримувати. Друїди мого ордену хочуть лише жити тихим, мирним життям тут, у Тіньовій Ґейлі, і вони погрожують цьому.\n\nБагато хто з нас боїться.\n\nЯ приходжу з пропозицією. Бийтеся з культистами за нас і принесіть нам вуха тих, кого ви вб'єте. Ми винагородимо вас за кожну, з якою ви повернетеся, як грошима, так і, з часом, доступом до наших таємниць, якщо ви доведете, що є справжнім другом.", [3] = "Зберіть 10 вух культиста Ал'Акета з Ал'Акета в Тіньоголовому лісі, Сяйві Акіра або Низині Густберрі та поверніть їх Вейн Місячний Кігть у Тіньоголовому лісі.", ["en"] = "More Al'Aketh Ears", ["tasks"] = { ["Al'Alketh Cultist's Ear"] = "Вухо культиста Ал'Алкета", ["Al'Alketh Cultist's Ear (Provided)"] = "Вухо культиста Ал'Алкета (видано)", ["Al'Alketh Cultist's Ear slain"] = "Вухо культиста Ал'Алкета: убито" } },
    [9353] = { [1] = "Обміняйте ваучер на подарункову коробку iCoke", ["en"] = "Redeem iCoke Gift Box Voucher", ["tasks"] = { ["iCoke Gift Box Voucher"] = "Подарунковий ваучер iCole" } },
    [93552] = { [1] = "Збір вітряних каменів", [2] = "Вітряні камені є критично важливим ресурсом на острові Зефрас, оскільки вони містять сиру, концентровану енергію самих вітрів. Вітряні елементалі, які колись жили тут, на Зефрасі, зникли кілька століть тому, і відтоді магія, яка підтримує цей острів, поступово згасає. Не без обмежень, Вітряні камені все ще є надійним джерелом енергії та неймовірно цінні для нас.\n\nВи знайдете необроблені Вітряні камені, розкидані по гаю, чи можете ви допомогти мені їх зібрати?", [3] = "Зберіть 15 скупчень вітряного каменю з необроблених вітряних каменів у гаю Тендал.", [4] = "Вітаю, {клас:к}.", [5] = "Щиро дякую за це. Як ельфи, ми всі маємо глибокий зв'язок із магією, і ці вітрокамені стають дедалі ціннішими, адже магія, вкладена в острів великими якірними пілонами, продовжує згасати. \r\n\r\nВітрокамені — не єдине корисне, що можна зібрати на землі. Прошу, візьми один із цих посібників.", ["en"] = "Harvesting Windstones", ["tasks"] = { ["Windstone Cluster"] = "Скупчення Вітряного каменю", ["Windstone Cluster (Provided)"] = "Скупчення Вітряного каменю (видано)", ["Windstone Cluster slain"] = "Скупчення Вітряного каменю: убито" } },
    [9362] = { [1] = "Воєвода Крелліан", [2] = "У нас обмаль часу, {ім'я:к}! Мої закляття виявили потужне джерело магії. Я не можу залишити вежу і прошу тебе вбити нікчемну істоту, що володіє цим артефактом.\n\nЦей жалюгідний покидьок, воєвода Крелліан, ховається за своїми охоронцями у храмі Зін-Малор. Спопели його і забери призматичну мушлю, яку він так сильно цінує.", [3] = "Знайдіть призматичну мушлю для архімага Зілема, що мешкає у вежі на вершині скель Азшари.", [4] = "Не можна гаяти час! Ти {стать:приніс:принесла} мушлю?", [5] = "Мушу сказати, що у цієї призматичної мушлі дивна аура. Здається, цілком доречно, що частиною твоєї нагороди буде можливість дослідити її магічні властивості...", ["en"] = "Warlord Krellian", ["tasks"] = { ["Prismatic Shell"] = "призматична мушля", ["Prismatic Shell (Provided)"] = "призматична мушля (видано)" } },
    [9364] = { [1] = "Фрагменти магії", [2] = "Мої дослідження виявили унікальне призначення призматичної оболонки.\n\nВізьми мушлю та наклади заклинання поліморфії на Огидохльостів в Азшарі. Якщо почекати декілька секунд, хаотична аура мушлі змусить їх розділитися на кількох менших клонів на кілька секунд. Вбий цих клонів якомога швидше, і мушля збере їхню сутність.\n\nКоли мушля наповниться, поверни її мені.", [3] = "Накладіть поліморфію на Огидохльостів в Азшарі та вбийте клонів, що з'являться через кілька секунд. Коли знищите 50 поліморфних клонів, поверніться до архімага Зілема в Азшару.", [4] = "Ти вже {стать:зібрав:зібрала} їхню сутність?", [5] = "Чудово! Чудово!\n\nТепер ми можемо використати зібрану магічну силу для створення нового закляття!", ["en"] = "Fragmented Magic", ["tasks"] = { ["Polymorph Clone"] = "поліморфний клон", ["Polymorph Clone slain"] = "поліморфний клон: убито", ["Prismatic Shell"] = "призматична мушля", ["Prismatic Shell (Provided)"] = "призматична мушля (видано)" } },
    [9367] = { [1] = "Фестиваль вогню", [2] = "Знов настає свято сонцестояння!\n\nЩороку, за традицією, ми обираємо хранителів полум'я, які зобов'язані наглядати за багаттями, запаленими в наших столицях. По всьому Азероту запалюються вогні, але важливо, щоб наші горіли спекотніше і яскравіше за всіх, щоб належним чином вшанувати пору року.\n\nНасправді я маю для тебе завдання, якщо ти не проти. Мені поки що невідомо, чи належним чином горять багаття у всіх столицях. Вирушай туди, погрійся біля цих вогнищ і переконайся, що вони достатньо гарячі!", [3] = "Доторкніться до вогнищ у Штормовії, Залізогарті та Дарнасі, а потім поговоріть з фестивальним знавцем в одній зі столиць.", [5] = "Чудово! Схоже, цього року ми обрали відповідальних хранителів полум'я, якщо вогнища так добре доглянуті. Дякую, що {стать:перевірив:перевірила} їх для мене. Ось, візьми це на знак моєї вдячності.", ["en"] = "The Festival of Fire", ["tasks"] = { ["Flame of Darnassus"] = "полум'я Дарнаса", ["Flame of Darnassus (Provided)"] = "полум'я Дарнаса (видано)", ["Flame of Ironforge"] = "полум'я Залізогарта", ["Flame of Ironforge (Provided)"] = "полум'я Залізогарта (видано)", ["Flame of Stormwind"] = "полум'я Штормовію", ["Flame of Stormwind (Provided)"] = "полум'я Штормовію (видано)" } },
    [9368] = { [1] = "Фестиваль вогню", [2] = "Знов настає свято сонцестояння!\n\nЩороку, за традицією, ми обираємо хранителів полум'я, які зобов'язані наглядати за багаттями, запаленими в наших столицях. По всьому Азероту запалюються вогні, але важливо, щоб наші горіли спекотніше і яскравіше за всіх, щоб належним чином вшанувати пору року.\n\nНасправді я маю для тебе завдання, якщо ти не проти. Мені поки що невідомо, чи належним чином горять багаття у всіх столицях. Вирушай туди, погрійся біля цих вогнищ і переконайся, що вони достатньо гарячі!", [3] = "Доторкніться до вогнищ в Орґріммарі, Громовому Бескиді та Підмісті, а потім поговоріть з фестивальним оповідником в одній зі столиць.", [4] = "Чи горять вогнища?", [5] = "Чудово! Схоже, цього року ми обрали відповідальних хранителів полум'я, якщо вогнища так добре доглянуті. Дякую, що {стать:перевірив:перевірила} їх для мене. Ось, візьми це на знак моєї вдячності.", ["en"] = "The Festival of Fire", ["tasks"] = { ["Flame of Orgrimmar"] = "полум'я Орґріммара", ["Flame of Orgrimmar (Provided)"] = "полум'я Орґріммара (видано)", ["Flame of Thunder Bluff"] = "полум'я Громового Бескиду", ["Flame of Thunder Bluff (Provided)"] = "полум'я Громового Бескиду (видано)", ["Flame of the Undercity"] = "полум'я Підмістя", ["Flame of the Undercity (Provided)"] = "полум'я Підмістя (видано)" } },
    [9378] = { [1] = "ПРАПОР DND Цитадель жаху – Наксрамас", [2] = "У гущі Чумного Лісу знаходиться вхід до жахливої цитаделі Наксрамаса. Раніше всі спроби увійти туди гальмувалися магічними оберегами, накладеними на рунічний портал. Тобто, досі.\n\nМи розробили спосіб проникнення за допомогою постійного таємного маскування – старого заклинання Кірін-Тора з деякими моїми власними модифікаціями. З огляду на це, маскування коштує дорого; проте ваша відданість справі Світанку непохитна! Ми відмовимося від усіх зобов'язань щодо витрат.", [3] = "Архімаг Анджела Досантос у каплиці Світлої Надії у Східних Чумних Землях безкоштовно надасть вам Арканне Маскування. Ви повинні бути Піднесені Срібним Світанком.", ["en"] = "DND FLAG The Dread Citadel - Naxxramas", ["tasks"] = { ["42000 reputation with Argent Dawn"] = "42000 репутації у Сріблястого Світанку" } },
    [9386] = { [1] = "Світло у темних місцях", [2] = "Не терпиться, чи не так? Якщо ти {стать:готовий:готова} ще раз зазирнути в глибини, я з радістю винагороджу тебе.\n\nШукай вогнища, що горять у Стратгольмі, Некроситеті, Грізному Молоті та залах самого Чорноскельного шпиля. Я з нетерпінням чекатиму на твоє повернення, {ім'я}.", [3] = "Знайдіть і доторкніться до вогнищ, розташованих у Чорноскельному шпилі, Грізному Молоті, Некроситеті та Стратгольмі, а потім поговоріть з хранителем полум'я фестивалю.", ["en"] = "A Light in Dark Places", ["tasks"] = { ["Flame of Blackrock Spire"] = "Полум'я Шпиля Чорної Скелі", ["Flame of Blackrock Spire (Provided)"] = "Полум'я Шпиля Чорної Скелі (видано)", ["Flame of Blackrock Spire slain"] = "Полум'я Шпиля Чорної Скелі: убито", ["Flame of Dire Maul"] = "Полум'я Запеклого Молота", ["Flame of Dire Maul (Provided)"] = "Полум'я Запеклого Молота (видано)", ["Flame of Dire Maul slain"] = "Полум'я Запеклого Молота: убито", ["Flame of Stratholme"] = "Полум'я Стратгольма", ["Flame of Stratholme (Provided)"] = "Полум'я Стратгольма (видано)", ["Flame of Stratholme slain"] = "Полум'я Стратгольма: убито", ["Flame of the Scholomance"] = "Полум'я Несхольності", ["Flame of the Scholomance (Provided)"] = "Полум'я Несхольності (видано)", ["Flame of the Scholomance slain"] = "Полум'я Несхольності: убито" } },
    [93862] = { [1] = "Повернення ящика", ["en"] = "Crate Return", ["tasks"] = { ["Notarized Shipping Container"] = "Нотаріально засвідчений вантажний контейнер" } },
    [9388] = { [1] = "Мерехтливе полум'я Калімдору", [2] = "Сьогодні по всьому світу горить безліч вогнів, {ім'я}. Найважче наглядати за тими вогнями, що палають зеленим. Вони не горітимуть довго без нагляду. Переконайся, що смарагдові вогні все ще горять у Калімдорі для наших хранителів полум'я, добре?\n\nТи знайдеш їх поблизу Брашпиля в Степах, біля Глефи властителя в Темнобережжі, у лісі Ясенедолу поблизу мосту біля Срібнокрилої застави та біля дороги до Вітрокосих скель вздовж головної дороги в Каміннопазуристих горах.", [3] = "Відвідайте вогнища в Ясенедолі, Степах, Темнобережжі та Каміннопазуристих горах, а потім поговоріть з хранителем полум'я фестивалю.", [4] = "Вогні не мають згаснути, поки триває фестиваль!", [5] = "Ох, то вони досі горять? Це тішить, бо не хотілося б, щоб ці вогнища згасли передчасно. Ти добре {стать:попрацював:попрацювала}, {ім'я}. Прийми це з моїм благословенням.", ["en"] = "Flickering Flames in Kalimdor", ["tasks"] = { ["Flame of Ashenvale"] = "Полум'я Ясенеділу", ["Flame of Ashenvale (Provided)"] = "Полум'я Ясенеділу (видано)", ["Flame of Ashenvale slain"] = "Полум'я Ясенеділу: убито", ["Flame of Darkshore"] = "Полум'я Темних берегів", ["Flame of Darkshore (Provided)"] = "Полум'я Темних берегів (видано)", ["Flame of Darkshore slain"] = "Полум'я Темних берегів: убито", ["Flame of Stonetalon"] = "Полум'я Кам'яного Кігтя", ["Flame of Stonetalon (Provided)"] = "Полум'я Кам'яного Кігтя (видано)", ["Flame of Stonetalon slain"] = "Полум'я Кам'яного Кігтя: убито", ["Flame of the Barrens"] = "Полум'я пустелі", ["Flame of the Barrens (Provided)"] = "Полум'я пустелі (видано)", ["Flame of the Barrens slain"] = "Полум'я пустелі: убито" } },
    [9389] = { [1] = "Мерехтливе полум'я Східних Королівств", [2] = "Вогняний фестиваль сонцестояння традиційно осяює землю міріадами вогнів. Дехто стверджує, що зелені вогні — найкращі, адже їх найважче підтримувати, і вони мають такий характерний відтінок.\n\nПереконайся, що вони все ще горять у Східних Королівствах для наших хранителів полум'я. Вогні знаходяться біля Дун-Модра в Заболотті, поблизу села Поховальні Вогнища в Срібнохвойному пралісі, на скелях неподалік маяка в Західному краї та біля зруйнованої вежі в передгір'ях Гіллзбраду.", [3] = "Відвідайте вогнища у передгір'ях Гіллзбраду, Срібнохвойному пралісі, Західному краю та Заболотті, а потім поговоріть з хранителем полум'я фестивалю.", [4] = "Ти вже {стать:оглянув:оглянула} вогнища?", [5] = "Отже, ти {стать:повернувся:повернулася}, побачивши смарагдові полум'я у різних куточках континенту. Що скажеш? Безперечно, це рідкісне і прекрасне видовище. Однак я розумію, що матеріальна винагорода цінується більше... тож, прошу, прийми це за твої клопоти.", ["en"] = "Flickering Flames in the Eastern Kingdoms", ["tasks"] = { ["Flame of Hillsbrad"] = "Полум'я Гіллсбрада", ["Flame of Hillsbrad (Provided)"] = "Полум'я Гіллсбрада (видано)", ["Flame of Hillsbrad slain"] = "Полум'я Гіллсбрада: убито", ["Flame of Silverpine"] = "Полум'я срібної сосни", ["Flame of Silverpine (Provided)"] = "Полум'я срібної сосни (видано)", ["Flame of Silverpine slain"] = "Полум'я срібної сосни: убито", ["Flame of Westfall"] = "Полум'я Вестфоллу", ["Flame of Westfall (Provided)"] = "Полум'я Вестфоллу (видано)", ["Flame of Westfall slain"] = "Полум'я Вестфоллу: убито", ["Flame of the Wetlands"] = "Полум'я водно-болотних угідь", ["Flame of the Wetlands (Provided)"] = "Полум'я водно-болотних угідь (видано)", ["Flame of the Wetlands slain"] = "Полум'я водно-болотних угідь: убито" } },
    [93926] = { [1] = "Західна варта", [2] = "Якою б не була причина нападу культу на вежу, він не вартий втрат наших людей через це.\n\nЯ б хотів, щоб ти вирушив на південний захід і перевірив ту сторожову вежу для нас. Знайди там миротворців і скажи їм повернутися до села. Утримання цієї вежі не варте життів, які це коштуватиме, і я б волів зосередити тут захисників, які в нас є, щоб захистити наших громадян.\n\nМиротворець Вааніель головний, повідом йому, щоб він повернувся сюди якомога швидше. Швидше!", [3] = "Знайдіть миротворця Вааніеля на західній сторожовій вежі.", ["en"] = "The Western Watch", ["tasks"] = { ["Check in on the Western Watchtower in the Shen'dar Highlands"] = "Завітайте до Західної сторожової вежі у Шен'дарському нагір'ї" } },
    [93927] = { [1] = "Останнє прохання", [2] = "<Коли ви оглядаєте тіло загиблого миротворця, з його рук випадає кривава записка. Якщо ви її піднімете та прочитаєте, це може дати вам підказку, як діяти далі.>", [3] = "Зберіть записку, яку ви знайшли біля мертвого миротворця, і прочитайте її, щоб визначити свої наступні кроки.", ["en"] = "A Last Request", ["tasks"] = { ["Collect and read the note"] = "Зберіть та прочитайте записку", ["Raani's Favorite Feather"] = "Улюблене перо Раані", ["Raani's Favorite Feather (Provided)"] = "Улюблене перо Раані (видано)", ["Raani's Favorite Feather slain"] = "Улюблене перо Раані: убито", ["Shadowsong Family Signet"] = "Сімейна печатка Тіньопісні", ["Shadowsong Family Signet (Provided)"] = "Сімейна печатка Тіньопісні (видано)", ["Shadowsong Family Signet slain"] = "Сімейна печатка Тіньопісні: убито", ["Skypriest Aanders"] = "Небесний жрець Аандерс", ["Skypriest Aanders (Provided)"] = "Небесний жрець Аандерс (видано)", ["Skypriest Aanders slain"] = "Небесний жрець Аандерс: убито" } },
    [93928] = { [1] = "Про мишей та молоко", [2] = "Мені потрібне печиво, розумієш?\n\nНі!", [3] = "Принеси мишці печиво.", ["en"] = "Of Mice and Milk" },
    [93948] = { [1] = "Доставити печатку", [2] = "Оскільки ти все одно їдеш до Валанаару, будь ласка, достав перстень-печатку, який ти знайшов у вежі, Талаанісу Тіньовій Пісні у Валанаарі.\n\nВін захоче його повернути, і, що ще важливіше, він захоче дізнатися про долю свого племінника. Талааніс — Верховний Старійшина острова Зефрас, і, що ще важливіше, він хороша людина, яку люблять люди, незважаючи на наші нинішні труднощі. Мені боляче думати про те, як він відреагує на цю новину. Будь ласка, вислови мої співчуття з приводу його втрати.", [3] = "Доставте родинну печатку Тіньопісні Талаанісу Тіньопісні у Валанаар.", ["en"] = "Deliver the Signet", ["tasks"] = { ["Shadowsong Family Signet"] = "Сімейна печатка Тіньопісні", ["Shadowsong Family Signet (Provided)"] = "Сімейна печатка Тіньопісні (видано)", ["Shadowsong Family Signet slain"] = "Сімейна печатка Тіньопісні: убито" } },
    [93949] = { [1] = "Прослуховування", [2] = "Нас прослуховують.\n\nУ низовинах сезон скайгоперів, а це означає, що шкідники всюди. Один із магів Високого Ордену повідомив, що на одну з комах, яких вони вбили, накладено якісь чари. Коли ми уважно оглянули її, то виявили, що це якесь заклинання підслуховування.\n\nМи підозрюємо, що культ використовує цих зачарованих комах як шпигунів. Ідіть і знищіть їх для нас. Ви не зможете сказати, які з них зачаровані, дивлячись на них, тому вам просто доведеться вбити їх усіх.", [3] = "Вбивайте Небесних Стрибунців у Валанаарі, доки не знищите 8 зачарованих Небесних Стрибунців.", ["en"] = "Bugged", ["tasks"] = { ["Enchanted Skyhopper Exterminated"] = "Зачарований Скайхопер знищений" } },
    [93951] = { [1] = "Маленька красуня", [2] = "Гіпогрифи, що оселилися на південний захід від села, можуть бути неприємністю, але вони також надають досить унікальну можливість отримати їхнє пір'я. Багато небеснородних люблять прикрашати своє волосся яскравим пір'ям, а пух гіпогрифа надзвичайно яскравий і, що ще важливіше, шовковисто-м'який.\n\nЯкщо ви прямуєте в цьому напрямку, спробуйте зібрати якомога більше опалого пір'я з місць їх гніздування та навколо них. Будьте обережні, оскільки дикі гіпогрифи не терплять гостей.", [3] = "Зберіть 8 пухових пір'їн гіпогрифа у Шен'дарському нагір'ї.", ["en"] = "A Little Beauty", ["tasks"] = { ["Hippogryph Down"] = "Гіпогриф вниз", ["Hippogryph Down (Provided)"] = "Гіпогриф вниз (видано)", ["Hippogryph Down slain"] = "Гіпогриф вниз: убито" } },
    [93958] = { [1] = "Внутрішнє святилище", [2] = "Війська Валеннії щойно прорвали внутрішнє святилище. Спочатку там були запеклі бої, але тепер вони стали... тривожно тихими. Іди туди та зроби все можливе, щоб з'єднатися з Валеннією та її силами... якщо якісь із них залишилися.\n\nЯ залишуся тут і прикрию тобі спину.", [3] = "Поговоріть з Валенією Буревісник у внутрішньому святилищі Святилища Акіра.", ["en"] = "The Inner Sanctum" },
    [940] = { [1] = "Тельдрассіль", [2] = "Ліс шепоче про твої подвиги, {Ім'я}. Коли я відчула, як гарпій витурили з їхніх гнізд, заспокійливе відчуття наповнило весь ліс, і його істоти знову почуваються в безпеці. Я боялася направляти Верховному друїду ще одного посланника, але знаю, що ти впораєшся з цією роботою.\n\nПередай йому це та знай, що ліс безпечно проведе тебе своїми стежинами до кам'яних садів.", [3] = "Передайте доповідь Дерева-оракула верховному друїду Фендралові Оленерогу в Дарнасі.", [4] = "Гм... У тобі відчувається потужний дух лісу, {клас:к}. Що привело тебе до верховного друїда калдорай?", [5] = "Мені було цікаво, чому Дерево-оракул так довго не спілкувалося зі мною... Схоже, що поки одні проблеми стають меншими, інші продовжують рости.\n\nЯ боюся, що моя робота над Тельдрассілем ніколи не буде завершена, і ми не повернемо собі безсмертя.\n\nУ будь-якому разі, ти добре {стать:виконав:виконала} завдання Дерева-оракула та {стать:повинен:повинна} отримати нагороду за свою старанність.", ["en"] = "Teldrassil", ["tasks"] = { ["Inscribed Bark"] = "вкрита написами кора", ["Inscribed Bark (Provided)"] = "вкрита написами кора (видано)" } },
    [94003] = { [1] = "Бастіон «Небесний розбивач»", [2] = "Я — все, що залишилося від роду Небесних Руйнівників тут, на острові Зефрас. Решту вбили Ал'Акет.\n\nЄдине, що переважує мій смуток, — це мій сором. Родовий щит моєї родини — Оплот Небесних Руйнівників — тепер у руках культиста на ім'я Заал Штормовий Щит. Сімейні перекази стверджують, що гідному власнику цього щита не може статися нічого поганого.\n\nЗаал негідний, я в цьому впевнений. Знайдіть цього чоловіка у Святилищі Акіра та заберіть у нього мій щит. Зробіть це, і я навчу вас Захисту Небесних Руйнівників.", [3] = "Поверніть Оплот Небесного Руйнівника у Заала Штормового Щита у Святилищі Акіра.", ["en"] = "The Skybreaker Bulwark", ["tasks"] = { ["Skybreaker Bulwark"] = "Оплот «Скайбрейкер»" } },
    [94004] = { [1] = "Письмо ремісника: Еліксир сили огра", [2] = "<Написана вицвілим чорнилом записка вимагає $2oa Еліксир Сили Людожера, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер можна передати.>", ["en"] = "Craftsman's Writ: Elixir of Ogre's Strength", ["tasks"] = { ["Craftsman's Writ: Elixir of Ogre's Strength"] = "Письмо ремісника: Еліксир сили огра", ["Elixir of Ogre Strength"] = "Еліксир сили огра" } },
    [94006] = { [1] = "Великий Дух Урсери", [2] = "Вітання, {ім'я}. Ви просунулися у своїх друїдських дослідженнях достатньо далеко, щоб, на мою думку, вам познайомитися з одним із великих духів, які мешкають тут, на Зефрасі. Урс'ендріс — мудрий і благородний дух, який поколіннями навчав друїдів приймати форму урсери. На жаль, його володіння почали в'янути та падати в небо, як і багато інших областей Зефраса.\n\nЩоб знайти його, прямуйте на північний схід біля водоспаду в тіні Святилища Акіра. Він має змогу навчити вас далі.", [3] = "Поговоріть з Урс'ендрісом біля водоспадів на північний схід від Валанаару.", ["en"] = "The Great Ursera Spirit" },
    [94007] = { [1] = "Приборкання звіра", [2] = "Тепер, коли ви звикли до дикої природи високогір'я, я вважаю, що вам час знайти собі власного тваринного компаньйона.\n\nВирушайте до порту Валанаар на південному сході та поговоріть там з Квел'аною Квікґейлом. Він навчить вас мистецтву приборкання звірів.", [3] = "Звітувати до Квелани Квікгейл у Валанаарі.", ["en"] = "Taming the Beast" },
    [94013] = { [1] = "Приборкання звіра", [2] = "Ви повернулися з тріумфом, приборкавши двох звірів, тож настав час для вашого останнього випробування. Вітри Зефраса шепочуть про більші випробування попереду.\n\nВізьміть цей жезл для приборкання та вирушайте до низин Гастберрі. Там приборкайте Альфу Вульдрен та доведіть свою майстерність.\n\nЗавершіть цей урок, і ви будете готові вивчити глибші шляхи мисливця.", [3] = "Використайте Жезл Приборкання, щоб приборкати Альфу Вульдрен у Низині Гастберрі. Потренуйте свої навички, а потім поверніть Жезл Приборкання Квел'ані Квікгейл у Валанаар.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [94050] = { [1] = "Тренування звіра", [2] = "Тепер ти маєш силу приручити домашнього улюбленця, але ти також повинен здобути навички його дресирування. Для цього немає нікого кращого за мою сестру, Квел'дору. Вона дасть тобі здатність дресирувати твого нового улюбленця.\n\nПлинь за вітром, юний {клас}.", [3] = "Поговоріть з Квел'дорою Квікгейл у Валанаарі.", ["en"] = "Training the Beast" },
    [9411] = { [1] = "<UNUSED>Інфузійні бинти", ["en"] = "<UNUSED>Infused Bandages", ["tasks"] = { ["[PH] Silithus PvP Dust [DEP]"] = "[PH] PvP-пил Силітуса [DEP]" } },
    [9412] = { [1] = "<UNUSED>Кришталеві пастилки для горла з лускатиною", ["en"] = "<UNUSED>Crystal Flake Throat Lozenge", ["tasks"] = { ["[PH] Silithus PvP Dust [DEP]"] = "[PH] PvP-пил Силітуса [DEP]" } },
