    [94299] = { [1] = "Письмо майстра: Плечі нічного пейзажу", [2] = "<Написана вицвілим чорнилом записка вимагає $2oa Плечі «Нічний пейзаж», а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Nightscape Shoulders", ["tasks"] = { ["Craftsman's Writ: Nightscape Shoulders"] = "Письмо майстра: Плечі нічного пейзажу", ["Nightscape Shoulders"] = "наплечі нічного краєвиду" } },
    [943] = { [1] = "Розгублений розвідувач", [2] = "Розвідувач Вельґар зберігає скам'янілість у себе на розкопках у Заболотті. Коли я знайшов камінь Релу, то був упевнений, що це ключ до таємниці скам'янілості.\n\nКоли я йшов до Вельґара, на мене напали раптори і я втратив реліквію. Я не знаю, хто з цих строкатих звірів проковтнув її, але якщо тобі вдасться її повернути, я зможу розкрити силу цих артефактів.\n\nПринеси мені камінь Релу і скам'янілість, що зберігається у Вельґара.", [3] = "Принесіть археологу Флягопузу в гавань Менетілів камінь Релу та скам'янілість Флягопуза.", [4] = "За допомогою каменя Релу я зможу розкрити таємниці моєї скам'янілості, а також скам'янілості Сноходня з Темнобережжя, {ім'я}.", [5] = "Чудово, {ім'я}!\n\nТепер подивимося, чи зможу я розкрити силу скам'янілостей за допомогою цього каменя.", ["en"] = "The Absent Minded Prospector", ["tasks"] = { ["Flagongut's Fossil"] = "скам'янілість Флягопуза", ["Flagongut's Fossil (Provided)"] = "скам'янілість Флягопуза (видано)", ["Stone of Relu"] = "камінь Релу", ["Stone of Relu (Provided)"] = "камінь Релу (видано)" } },
    [94300] = { [1] = "Письмо майстра: Велика маска вуду", [2] = "<Написана вицвілим чорнилом записка вимагає $2oa Великої маски Вуду, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Big Voodoo Mask", ["tasks"] = { ["Big Voodoo Mask"] = "маска потужного вуду", ["Craftsman's Writ: Big Voodoo Mask"] = "Письмо майстра: Велика маска вуду" } },
