    [94338] = { [1] = "Замовлення майстра: гоблінські кабелі запуску XL", [2] = "<У записці, написаній вицвілим чорнилом, запитується $2oa Кабелі для перемикання гоблінський XL, а також інформація про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Goblin Jumper Cables XL", ["tasks"] = { ["Craftsman's Writ: Goblin Jumper Cables XL"] = "Письмо майстра: Кабелі для перемички гоблінський XL", ["Goblin Jumper Cables XL"] = "гоблінський кабельний дефібрилятор Макс-Про" } },
    [94339] = { [1] = "Напис майстра: Польовий ремонтний бот 74A", [2] = "<Написана вицвілим чорнилом записка містить запит на $2oa Польовий ремонтний робот 74A, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Field Repair Bot 74A", ["tasks"] = { ["Craftsman's Writ: Field Repair Bot 74A"] = "Напис майстра: Польовий ремонтний бот 74A", ["Field Repair Bot 74A"] = "польовий ремонтний робот 74A" } },
