    [94353] = { [1] = "Письмо ремісника: Сумка з рунічної тканини", [2] = "<Написана вицвілим чорнилом записка вимагає $2oa Мішок з рунної тканини, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Runecloth Bag", ["tasks"] = { ["Craftsman's Writ: Runecloth Bag"] = "Письмо ремісника: Сумка з рунічної тканини", ["Runecloth Bag"] = "сумка з рунічного полотна" } },
    [94354] = { [1] = "Письмо ремісника: Чоботи з рунічної тканини", [2] = "<Написана вицвілим чорнилом записка вимагає $2oa Чоботи з рунічної тканини, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Runecloth Boots", ["tasks"] = { ["Craftsman's Writ: Runecloth Boots"] = "Письмо ремісника: Чоботи з рунічної тканини", ["Runecloth Boots"] = "чоботи з рунічного полотна" } },
    [94355] = { [1] = "Письмо майстра: Смокінг-піджак", [2] = "<Написана вицвілим чорнилом записка містить запит на $2oa піджак для смокінгу, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Tuxedo Jacket", ["tasks"] = { ["Craftsman's Writ: Tuxedo Jacket"] = "Письмо майстра: Смокінг-піджак", ["Tuxedo Jacket"] = "вишуканий жакет" } },
    [94356] = { [1] = "Письмо ремісника: Чоботи з тканини Скверни", [2] = "<Написана вицвілим чорнилом записка вимагає $2oa Чоботи з тканини Скверни, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Felcloth Boots", ["tasks"] = { ["Craftsman's Writ: Felcloth Boots"] = "Письмо ремісника: Чоботи з тканини Скверни", ["Felcloth Boots"] = "сквернополотняні черевики" } },
    [94357] = { [1] = "Письмо ремісника: Мішечок з травами Кенаріона", [2] = "<Написана вицвілим чорнилом записка вимагає $2oa мішечок з травами Кенаріона, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Cenarion Herb Bag", ["tasks"] = { ["Cenarion Herb Bag"] = "кенарійська сумка для трав", ["Craftsman's Writ: Cenarion Herb Bag"] = "Письмо ремісника: Мішечок з травами Кенаріона" } },
    [94358] = { [1] = "Письмо ремісника: Маска Тіньової Шерсті", [2] = "<Написана вицвілим чорнилом записка вимагає $2oa Маску Тіньової Шерсті, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Shadoweave Mask", ["tasks"] = { ["Craftsman's Writ: Shadoweave Mask"] = "Письмо ремісника: Маска Тіньової Шерсті", ["Shadoweave Mask"] = "тінеткана маска" } },
    [94359] = { [1] = "Письмо ремісника: Жилет з привидового ткацтва", [2] = "<Написана вицвілим чорнилом записка вимагає $2oa Жилет з привидової тканини, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Ghostweave Vest", ["tasks"] = { ["Craftsman's Writ: Ghostweave Vest"] = "Письмо ремісника: Жилет з привидового ткацтва", ["Ghostweave Vest"] = "жилет з примарного полотна" } },
    [94360] = { [1] = "Письмо ремісника: Мішечок душі", [2] = "<Написана вицвілим чорнилом записка вимагає $2oa Мішечок душі, а також інформацію про місце доставки та оплату. Внизу написано, що цей ордер може бути переданий.>", ["en"] = "Craftsman's Writ: Soul Pouch", ["tasks"] = { ["Craftsman's Writ: Soul Pouch"] = "Письмо ремісника: Мішечок душі", ["Soul Pouch"] = "мішечок душ" } },
    [94373] = { [1] = "Поклик землі", [2] = "Так, час настав, юний шамане. Ти став міцним і сильним, як камінь під нашими чоботами. Ставши шаманським шляхом, ти показуєш, що маєш мудрість гори, ще до того, як доведеш свою спроможність... Ти маєш твердість каменю, щоб пройти земним шляхом.\n\nАле щоб заслужити її прихильність, ти повинен зустріти її як слід. На південь звідси, у печері живуть тролі Морозногриві.\n\nПринеси мені два їхні намиста, які вони носять, — виготовлені з ведмедів Крижаних Кігтів. Тоді ми поговоримо більше про твоє майбутнє.", [3] = "Принесіть 2 кулони Ведмедя Морозної Гриви Тео Молотшторму в Анвілмарі.", ["en"] = "Call of Earth", ["tasks"] = { ["Iceclaw Bear Pendant"] = "Кулон «Ведмідь Крижаний Кіготь»", ["Iceclaw Bear Pendant (Provided)"] = "Кулон «Ведмідь Крижаний Кіготь» (видано)", ["Iceclaw Bear Pendant slain"] = "Кулон «Ведмідь Крижаний Кіготь»: убито" } },
    [94374] = { [1] = "Поклик землі", [2] = "Так, сапта — це напій, викуваний магією, що зв'язує наш дух зі стихіями. Лише кілька шаманів знають рецепт, і це не для слабохарактерних. Випий його, і ти побачиш те, чого інші не можуть. Правда — його потрібно пити лише у священному місці.\n\nВирушай на північ до Каменя Духів, що захований у кінці прихованої стежки вгору по горі. Випий його там... подивися, що тобі покаже земля.", [3] = "Знайдіть Камінь Духа та випийте Сапту Землі.\n\nНаданий предмет:", ["en"] = "Call of Earth", ["tasks"] = { ["Earth Sapta"] = "сапта землі" } },
    [94414] = { [1] = "Якорі Зефраса", [2] = "Вітаю, юний {ім'я}. Я часто приходжу сюди, щоб подивитися на стародавній пілон-якір. Дари духів вітрів, вони зв'язують і підтримують наш острів. Однак останнім часом їхня магія стала нестабільною та непослідовною.\n\nЯ не бачу, щоб вони страждали. Їхня велич не змінилася.\n\nЯкщо хочеш, я можу позичити тобі свій дар, щоб ти сам на них подивився.", [3] = "Поговоріть з Халааном Соколиним Оком і позичте його дар, щоб побачити опорний пілон вдалині.", [5] = "Дякую, що знайшов хвилину й поділився цим зі мною. Я й надалі пильнуватиму гай і розмірковуватиму про стан нашої батьківщини.", ["en"] = "The Anchors of Zephras", ["tasks"] = { ["View the Anchor Pylon"] = "Переглянути анкерний пілон" } },
    [94466] = { [1] = "Поклик вогню", [2] = "Ба, ти ж не заради історій пройшов весь цей шлях, чи не так, {ім'я}? Ти шукаєш Вічний вогонь і тотем вогню.\n\nПо-перше, тобі знадобиться сапта, щоб зв'язати твій дух з полум'ям.\n\nЯ її виготовлю, але мені знадобляться дві речі: вогняна смола від геомантів-тунельних щурів у печерах кобольдів на півночі та мішечок з реагентом від провидця-каменяруба, що ховається на південних пагорбах. Небезпечна робота, але гідна полум'я.", [3] = "Принесіть 1 вогняний дьоготь та 1 мішечок з реагентами Бралдіру Попелястому Мантлу в Лох-Модан.", ["en"] = "Call of Fire", ["tasks"] = { ["Fire Tar"] = "вогняна смола", ["Reagent Pouch"] = "мішечок з реагентами" } },
    [94472] = { [1] = "Сапта землі", [3] = "Поговоріть з Тео Хамерстормом, щоб отримати ще одну Земну Сапту.", ["en"] = "Earth Sapta" },
    [94473] = { [1] = "Сапта вогню", [3] = "Поговоріть з Бралдіром Попелястим Мантлом, щоб отримати ще одну Вогняну Сапту.", ["en"] = "Fire Sapta" },
    [94484] = { [1] = "Тривожна тиша", [2] = "Хвилинку, якщо дозволите {ім'я}. Ви прямуєте до Тіньоголового лісу? Там, у печері на північному сході, є конклав друїдів. Я чекаю на звістку від них, але їхнє листування давно затрималося.\n\nЗ огляду на руїни Бана'еталла та всі останні неспокою, я хвилююся, що могло статися щось жахливе. Будь ласка, якщо ви можете, йдіть, знайдіть Елегаеля Тернпоу та заспокойте мене.", [3] = "Знайдіть і поговоріть з Елегаелем Тернпо у північно-східній частині лісу Тіньогейл.", ["en"] = "Unnerving Silence" },
    [94485] = { [1] = "Сльози леді", [2] = "Якщо ми хочемо врятувати моїх товаришів у Лігві Нічних Кігтів, мені знадобляться деякі інгредієнти для припарки. Перший і найважливіший – це тонкий мох під назвою Ледіна Сльоза. Він зазвичай росте біля основи дерев тут, у Тіньовій Галі.\n\nЦей мох виділяє липку речовину, яка діє як антисептик і ідеально підходить для перев'язування відкритих ран. Я зібрав те небагато, що зміг дістати, але знаю, що в цьому лісі є більше.\n\nІдіть і будьте швидкими. Нам знадобиться багато, якщо поранені, яких я залишив, ще живі.", [3] = "Зберіть 8 мохів леді-сльози.", ["en"] = "Tears of the Lady", ["tasks"] = { ["Lady's Tear Moss"] = "Ледінська сльоза", ["Lady's Tear Moss (Provided)"] = "Ледінська сльоза (видано)", ["Lady's Tear Moss slain"] = "Ледінська сльоза: убито" } },
    [94486] = { [1] = "Пір'я для обв'язування", [2] = "Інший інгредієнт, який мені потрібен для припарки, – це пір'я крикунів Тіньової Гали, що бродять цим лісом. У молодому віці крикуни мають ізолююче пір'я, яке ідеально підійде для того, щоб покласти поверх моху. Це пір'я запобіжить висиханню антисептичного соку та забезпечить хоча б певний захист від негоди.\n\nБудьте обережні, крикуни зазвичай слухняні, але останнім часом вони стали неймовірно ворожими. Їхні великі кігті можуть легко випатрати вас, якщо ви не будете обережні.", [3] = "Зберіть 20 пір'їн у Верескунів Тіньогейл у Тіньогейлському лісі.", ["en"] = "Feathers for Binding", ["tasks"] = { ["Pristine Shriekling Feathers"] = "Незаймане верещаче пір'я", ["Pristine Shriekling Feathers (Provided)"] = "Незаймане верещаче пір'я (видано)", ["Pristine Shriekling Feathers slain"] = "Незаймане верещаче пір'я: убито" } },
    [94487] = { [1] = "Небажаний і негідний", [2] = "Культисти Алакета влаштували нам засідку без попередження, хоча їхні мотиви залишаються для мене загадкою. Я знав, що в цих культистів хмари між вухами, але ніколи не думав, що вони порушать крихку рівновагу тут, на Зефрасі, з такою жорстокістю. Ідіть, убийте стільки, скільки зможете, і заберіть їхні реліквії, якщо вони їх носять.\n\n<Елегаель плюється.>\n\nЦі прокляті штормом культисти не заслуговують називатися шен'дорей. Лісові звірі можуть отримати їхні тіла. Їхній прах не заслуговує на вітри.", [3] = "Зберіть 10 закривавлених сімейних реліквій у піхотинців Ал'Акета та мисливців за бурею Ал'Акета в лісі Тіньової брами.", ["en"] = "Unwanted and Unworthy", ["tasks"] = { ["Bloody Heirloom"] = "Кривава реліквія", ["Bloody Heirloom (Provided)"] = "Кривава реліквія (видано)", ["Bloody Heirloom slain"] = "Кривава реліквія: убито" } },
    [94488] = { [1] = "Узи, що зв'язують", [2] = "Причина присутності культистів тут досі мене бентежить, але я відчуваю знайомий запах крізь кровопролиття.\n\nОдин з наших друїдів кола, Хааліен, зник кілька місяців тому. Схоже, він кинув свою жалюгідну шкуру разом із культистами.\n\nПокажіть йому, що станеться, коли він проллє кров своїх родичів! Візьміть його голову та поверніть її мені.", [3] = "Убийте командира Хааліена та принесіть його голову Елегаелю Тернпоу в лісі Тіньовій брами.", ["en"] = "The Ties That Bind", ["tasks"] = { ["Commander Haalien's Severed Head"] = "Відрубана голова командира Хааліена", ["Commander Haalien's Severed Head (Provided)"] = "Відрубана голова командира Хааліена (видано)", ["Commander Haalien's Severed Head slain"] = "Відрубана голова командира Хааліена: убито" } },
    [94489] = { [1] = "Рани зради", [2] = "Я закінчив з припарками. Швидко, віднеси їх друїдам у печері, на північ, через галявину. Я знаю, що мої побратими в набагато гіршому стані, ніж я. Вони, мабуть, занадто поранені, щоб загоїти власні рани. Нас, шен'дорейських друїдів, так мало, що кожне життя цінне.\n\nПерш ніж ти підеш, у мене егоїстичне прохання. Мій приятель, Джорел Вітроспівець, був у жалюгідному стані, коли я пішов. Будь ласка, подбай про його рани, якщо він ще живий.", [3] = "Увійдіть до Лігва Нічного Ікла та вилікуйте 7 друїдів, а також знайдіть Джорела Вітроспівака в Лісі Тіней.", ["en"] = "The Wounds of Betrayal", ["tasks"] = { ["Baeo Sharpstrike"] = "Гострий удар Бео", ["Baeo Sharpstrike (Provided)"] = "Гострий удар Бео (видано)", ["Baeo Sharpstrike slain"] = "Гострий удар Бео: убито", ["Bryaes Galechaser"] = "Бріас Гейлчейзер", ["Bryaes Galechaser (Provided)"] = "Бріас Гейлчейзер (видано)", ["Bryaes Galechaser slain"] = "Бріас Гейлчейзер: убито", ["Find Jorel Windsinger"] = "Знайдіть Джорела Віндсінгера", ["Injured Druids healed"] = "Поранені друїди зцілені", ["Injured Druids healed (Provided)"] = "Поранені друїди зцілені (видано)", ["Injured Druids healed slain"] = "Поранені друїди зцілені: убито", ["Mithraless Sterngale"] = "Мітралес Стернгейл", ["Mithraless Sterngale (Provided)"] = "Мітралес Стернгейл (видано)", ["Mithraless Sterngale slain"] = "Мітралес Стернгейл: убито", ["Naaleos Leafwhisper"] = "Наалеос Листяний Шепіт", ["Naaleos Leafwhisper (Provided)"] = "Наалеос Листяний Шепіт (видано)", ["Naaleos Leafwhisper slain"] = "Наалеос Листяний Шепіт: убито", ["Nayeela Snarlfang"] = "Найїла Снарлфанг", ["Nayeela Snarlfang (Provided)"] = "Найїла Снарлфанг (видано)", ["Nayeela Snarlfang slain"] = "Найїла Снарлфанг: убито", ["Neyasteel Mossmender"] = "Неястил Моссмендер", ["Neyasteel Mossmender (Provided)"] = "Неястил Моссмендер (видано)", ["Neyasteel Mossmender slain"] = "Неястил Моссмендер: убито", ["Telenos \nLeafwhisper × 1"] = "Теленос \nШепіт листя × 1", ["Telenos \nLeafwhisper × 1 (Provided)"] = "Теленос \nШепіт листя × 1 (видано)", ["Telenos \nLeafwhisper × 1 slain"] = "Теленос \nШепіт листя × 1: убито" } },
    [94490] = { [1] = "Розірваний лист", [2] = "<За одним із наручів Хааліена захована записка, трохи порвана та заплямована кров’ю у вашому бою. Схоже, вона містить корисну інформацію про мотиви культистів для нападу на лігво друїдів. Елегаель був би зацікавлений у цій інформації.>", [3] = "Принесіть Розірваного послання Елегаелю Тернпоу в лісі Тіньоголовий.\n\nНаданий предмет:", ["en"] = "Ripped Missive", ["tasks"] = { ["Ripped Missive"] = "Розірваний лист" } },
    [94491] = { [1] = "Доля лігва", [2] = "Схоже, десь у Валанаарі ховається кореспондент, який постачає інформацію культу. Я явно не в змозі вирушити в цю подорож, але Лотелуум має знати, що тут сталося.\n\nВін також повинен знати долю тих, кого вже немає з нами. Завдяки вашій допомозі, я думаю, ми зможемо впоратися з рештою ситуації звідси, хоча шкода вже завдана.\n\nБудь ласка, йдіть швидше, {ім'я}. Сподіваюся, наші шляхи колись знову перетнуться. А поки що мені потрібно вбити культистів.", [3] = "Віддайте послання Лотелууму у Валаннарі та розкажіть йому, що сталося.\n\nНаданий предмет:", ["en"] = "The Fate of the Den", ["tasks"] = { ["Mysterious Orders"] = "Таємничі ордени" } },
    [94493] = { [1] = "Марна жертва", [2] = "Слава Богу, наше повідомлення дійшло до Лотелууму. Зачекайте, а де решта підкріплення? Напевно, не тільки тебе послали?\n\n<Елегаель блідне, коли ти пояснюєш.>\n\nОтже, повідомлення не дійшло до Валанаару. Ми справді у скрутному становищі.\n\n<Елегаель глибоко зітхає, а потім виглядає рішучим.>\n\nТоді ми повинні впоратися з цим самостійно. Час має вирішальне значення.", [3] = "Поговоріть з Елегаелем Тернпо у північно-східній частині лісу Тіньогейл.", ["en"] = "A Sacrifice in Vain" },
    [94559] = { [1] = "НЕВИКОРИСТАНИЙ", [2] = "Серед Ал'Акетів є перебіжчик. Вони стверджують, що знають справжні наміри культу щодо острова та хочуть прийти, але зроблять це лише за умови гарантій захисту.\n\nЦей перебіжчик ховається в будинку на північний захід від Валанаару, одразу в гірській місцевості. Мені потрібен хтось, хто може непомітно потрапити туди, знайти зрадника, дізнатися про нього та супроводити його назад до нас. Це може бути пасткою, але якщо ця інформація така важлива, як стверджує цей зрадник, вона варта певного ризику.", ["en"] = "UNUSED", ["tasks"] = { ["Find the Al'Aketh Turncoat"] = "Знайдіть перебіжчика Ал'Акета" } },
    [94568] = { [1] = "Справжні плани Культу", [2] = "Цей перебіжчик явно боявся задумів культу, настільки, що перебіг на бік і звернувся до нас за допомогою. Дуже прикро, що він мертвий і забрав свої таємниці з собою в могилу.\n\nНам потрібно обговорити це далі, щоб визначити наші наступні кроки.", [3] = "Поговоріть з Талаанісом Тіньоспівом та спостерігайте за розмовою.", ["en"] = "The Cult's True Plans", ["tasks"] = { ["Learn what you can from the crystal"] = "Дізнайтеся, що ви можете, з кристала" } },
    [9458] = { [1] = "<UNUSED>Зілля посилених почуттів", ["en"] = "<UNUSED>Potion of Heightened Senses", ["tasks"] = { ["[PH] Silithus PvP Dust [DEP]"] = "[PH] PvP-пил Силітуса [DEP]" } },
    [9459] = { [1] = "<UNUSED>Зілля проти критичних ударів", ["en"] = "<UNUSED>Anti-crit Potion", ["tasks"] = { ["[PH] Silithus PvP Dust [DEP]"] = "[PH] PvP-пил Силітуса [DEP]" } },
    [946] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [94616] = { [1] = "Сапта води", ["en"] = "Water Sapta" },
    [94638] = { [1] = "Сила і милосердя", [2] = "Ти прийшов до мене в надії навчитися приймати силу. У мене є для тебе завдання, хоча воно важко лежить на моєму серці.\n\nМоя подруга, Ур'ендра, збожеволіла і почала нападати на своїх родичів. Без вітрів багато істот почали губити себе, і з величезною могутністю Ур'ендри вона становить страшну загрозу для крихкої рівноваги. Вона блукає по Шен'дарському нагір'ю на північний захід звідси.\n\nПокажи мені, що в тебе є сила духу покласти край її стражданням, і я дам тобі своє благословення.", [3] = "Знайдіть та вбийте Ур'ендру у Шен'дарському нагір'ї.", ["en"] = "Strength and Mercy", ["tasks"] = { ["Ur'endra slain"] = "Ур'ендра: убито" } },
    [9477] = { [1] = "<UNUSED>Зілля природних обладунків", ["en"] = "<UNUSED>Potion of Nature's Armor", ["tasks"] = { ["[PH] Silithus PvP Dust [DEP]"] = "[PH] PvP-пил Силітуса [DEP]" } },
    [9478] = { [1] = "<UNUSED>Портативний шрифт для зцілення", ["en"] = "<UNUSED>Portable Healing Font", ["tasks"] = { ["[PH] Silithus PvP Dust [DEP]"] = "[PH] PvP-пил Силітуса [DEP]" } },
    [9479] = { [1] = "<UNUSED>Славний штандарт Альянсу", ["en"] = "<UNUSED>Glorious Standard of the Alliance", ["tasks"] = { ["[PH] Silithus PvP Dust [DEP]"] = "[PH] PvP-пил Силітуса [DEP]" } },
    [948] = { [1] = "Ону", [2] = "Ону, древній знань з діброви Древніх, знає про твою подорож до Скельноджерельного водоспаду і хоче поговорити з тобою. Діброва знаходиться на півдні, біля гір.\n\nДревні — мудрі та дуже терплячі, {ім'я}. Та якщо Ону хоче поговорити з тобою щодо того, що ти {стать:бачив:бачила} біля водоспаду, то, боюся, це терміново.", [3] = "Поговоріть з Ону в діброві Древніх.", [5] = "{ім'я}. Ти тут.\n\nДобре.\n\nМи маємо дещо... обговорити. Ти і я.", ["en"] = "Onu" },
    [9480] = { [1] = "<UNUSED>Банер негативних наслідків", ["en"] = "<UNUSED>Debuff Banner", ["tasks"] = { ["[PH] Silithus PvP Dust [DEP]"] = "[PH] PvP-пил Силітуса [DEP]" } },
    [9481] = { [1] = "<UNUSED>Легкий витратний матеріал", ["en"] = "<UNUSED>Light Consumable", ["tasks"] = { ["[PH] Silithus PvP Dust [DEP]"] = "[PH] PvP-пил Силітуса [DEP]" } },
    [9482] = { [1] = "<UNUSED>Зілля опору природі", ["en"] = "<UNUSED>Nature Resist Potion", ["tasks"] = { ["[PH] Silithus PvP Dust [DEP]"] = "[PH] PvP-пил Силітуса [DEP]" } },
    [94872] = { [1] = "Купівля дружби: Маґрами", [2] = "Люті Маґрами зараз безсумнівно перемагають у війні за території. Хоча всі ми раді, що сутички в пустелі трапляються не надто часто, щодня їхнє поселення на схід звідси стає більшим, а воїни — сміливішими.\n\nМене дуже непокоять наслідки безконтрольного посилення клану Маґрамів, але не можу заперечувати: з них міг би вийти добрий союзник.\n\nЯкщо хочеш заслужити їхню довіру, віддай цю торбу тотемів їхньому інтендантові. Але будь обережним.", ["en"] = "Buying Friendship: Magram", ["tasks"] = { ["Totem Tote (Provided)"] = "Торба для тотемів (видано)" } },
    [94873] = { [1] = "Купівля дружби: Ґелкіси", [2] = "Будь-який із двох панівних кланів кентаврів міг би стати добрим союзником, але щодо Ґелкісів я мушу тебе застерегти.\n\nЗа надійними відомостями, у протистоянні Маґрамів і Ґелкісів саме останні явно програють. Це може зіграти нам на руку: відчай здатен змусити ізольований клан прийняти допомогу ззовні.\n\nЯ приготував торбу тотемів. Віднеси її до інтенданта Ґелкісів у їхньому поселенні, якщо такий у них є. Це може бути нам на користь.", ["en"] = "Buying Friendship: Gelkis", ["tasks"] = { ["Totem Tote (Provided)"] = "Торба для тотемів (видано)" } },
    [94896] = { [1] = "Допомога біженцям", [2] = "Ти виглядаєш як здібний шукач пригод. Ти випадково не прямуєш до лісу Тіньогейл? Ба'аеталь лежить глибоко в лісі; звідти ми всі родом.\n\n<Еалане жестом вказує на інших біженців.>\n\nНещодавно нам довелося евакуюватися з Ба'аеталю, оскільки він почав падати в небо. Це сталося раптово і посеред ночі. Якщо ти прямуєш у цьому напрямку, будь ласка, пошукай будь-які залишені речі? Ліс і село надто небезпечні для нас, щоб повертатися туди зараз.", [3] = "Зберіть 8 покинутих речей з руїн Банаеталя.", ["en"] = "Aid For The Refugees", ["tasks"] = { ["Abandoned Belongings"] = "Покинуті речі", ["Abandoned Belongings (Provided)"] = "Покинуті речі (видано)", ["Abandoned Belongings slain"] = "Покинуті речі: убито" } },
    [94897] = { [1] = "Доля коханої людини", [2] = "Якщо ви подорожуєте до Банаеталу, у мене егоїстичне прохання. Мій коханий, Ресаан... Я вважаю, що він більше не є частиною цього світу. Він намагався повернутися, щоб купити припаси, хоча я благав його залишитися. Минув уже більше тижня, і я боюся найгіршого.\n\nБудь ласка, якщо ви знайдете його, поверніть його додому. Якщо він загинув, то я благаю вас, будь ласка, поверніть мені його сімейну реліквію.", [3] = "Знайдіть Ресаана в руїнах Банаеталя.", ["en"] = "The Fate of a Loved One", ["tasks"] = { ["Resaan's Heirloom"] = "Реліквія Ресаана", ["Resaan's Heirloom (Provided)"] = "Реліквія Ресаана (видано)", ["Resaan's Heirloom slain"] = "Реліквія Ресаана: убито" } },
    [94898] = { [1] = "Сильні вітри (температура вимкнена)", [2] = "Коли тієї фатальної ночі наш будинок почав падати в небо, ніби сама стихія чекала, щоб поглинути нас. Поки ми тікали, почали з'являтися духи вітру, і, на наш жах, вони почали нападати на тих, хто вижив.\n\nМи втратили багатьох жителів села через небо, але ще більше через невпинний гнів цих духів вітру. Не знаю, чи це наше село впало в небо, але вони надзвичайно небезпечні.\n\nЯкщо можете, будь ласка, покладіть їх на спокій.", [3] = "Убийте 10 Вітряних Ущелин.", ["en"] = "Violent Winds (Temp Disabled)", ["tasks"] = { ["Wind Hollow slain"] = "Вітрова западина: убито" } },
    [94901] = { [1] = "Помічники зі стрибків", [2] = "[PH] Збирайте жаб", ["en"] = "Hopping Helpers" },
    [94902] = { [1] = "Вінтажі Валанаара", [2] = "[PH] Збирати виноград з виноградника", ["en"] = "Valanaar Vintages" },
    [94978] = { [1] = "Приборкання звіра", [2] = "Кожен мисливець починає з пізнання зв'язку між звіром і господарем. Це ваше перше випробування. З часом ви приручите істот з усіх куточків світу, але поки що почніть з наших річок та озер на Зефрасі.\n\nВізьміть цей жезл для приборкання та знайдіть Пташиного Півня Вітру.\n\nПокажіть, що ви можете заслужити його довіру, і розпочніть свій шлях до справжньої майстерності.", [3] = "Використайте Жезл Приборкання, щоб приборкати Повзуна Пісні Вітру, якого можна знайти біля водойм.\nПотренуйте свої навички, а потім поверніть Жезл Приборкання Квел'ані Квікгейл у Валанаарі.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [94979] = { [1] = "Приборкання звіра", [2] = "Ви довели, що можете приборкати річкового повзуна, а тепер час випробувати свої навички на відкритій місцевості. Рівнини Зефраса лунають криками Буревісника, гордого крилатого мисливця, що бігає, як вітер.\n\nВізьміть цей жезл Приборкання та знайдіть одного з них. Подорожуйте низинами та заслужіть його довіру.\n\nПокажіть, що ви готові до випробувань, які ще попереду.", [3] = "Використайте Жезл Приборкання, щоб приборкати Злого Буреносця в Низині Гастберрі.\nПотренуйтеся у своїх навичках, а потім поверніть Жезл Приборкання Квел'ані Квікгейл у Валанаар.", ["en"] = "Taming the Beast", ["tasks"] = { ["Taming Rod"] = "жезл приборкання", ["Taming Rod (Provided)"] = "жезл приборкання (видано)" } },
    [95041] = { [1] = "Зберігачі даних", [2] = "Перш ніж ми втекли з Гномреґану, я зробив друковану копію архівів моєї родини. Арканотехнічні польові рівняння, проекти корпусів підводних човнів часів Другої війни, рецепт чилі бабусі Квіксвіч... наші найбільші досягнення знаходяться в цих файлах.\n\nТільки коли ми дісталися до Залізогарта, я знайшов дірку в своєму рюкзаку! Кілька перфокарт зникли, і без них дані занадто перемішані, щоб їх відновити.\n\nКартки, мабуть, закопані в снігу, десь за межами Гномреґану. Чи могли б ви їх знайти? Я знаю, що це малоймовірно...", [3] = "Зберіть 7 карток архівних даних Гномерегану з усього Гномерегану, а потім доставте їх Джеммі Квіксвіч у Залізогарті.", [4] = "Як просувається відновлення даних?", [5] = "Ці картки трохи відсиріли... але я з ними впораюся! Дякую, {ім'я:к}!", ["en"] = "Data Hoarders", ["tasks"] = { ["Gnomeregan Archival Data"] = "Архівні дані Гномерегану", ["Gnomeregan Archival Data (Provided)"] = "Архівні дані Гномерегану (видано)", ["Gnomeregan Archival Data slain"] = "Архівні дані Гномерегану: убито" } },
    [951] = { [1] = "Реліквії Матистри", [2] = "Пергамент, який ти {стать:знайшов:знайшла} біля Глефи властителя - це сторінка зі стародавнього тексту... написаного ельфами! Він сповнений прокляттями та порчею Сутінкового Молота, але схоже, що культ використовує стародавню ельфійську магію, щоб повернути своїх старих повелителів у наш світ.\n\nВідправляйся до руїн Матистри на північний схід та пошукай серед трави й розбитого каміння стародавні реліквії. Вивчивши їх, ми зможемо з'ясувати, яким чином Сутінковий Молот збирається використовувати магію ельфів.", [3] = "Принесіть 6 реліквій Матистри до Ону в діброву Древніх.", [4] = "{ім'я}. Чи були плідними твої пошуки в руїнах Матистри?", [5] = "Дякую тобі. Ці реліквії походять з часів розквіту Матистри. Цей колись великий бастіон ельфів давно зруйнований, але залишки магії все ще лежать в його руїнах. Будемо сподіватися, що ми зможемо розкрити таємниці цього місця до того, як це зроблять наші вороги...\n\nБудь насторожі, {ім'я}.", ["en"] = "Mathystra Relics", ["tasks"] = { ["Mathystra Relic"] = "реліквія Матистри", ["Mathystra Relic (Provided)"] = "реліквія Матистри (видано)" } },
    [95161] = { [1] = "Пам'ятай, що я тебе кохаю", [2] = "Якщо ви шукаєте Джеремі Хартвівера, найкраще поговорити з його нещодавно усиновленою матір'ю, Аветт Феллвуд, у Сутінковому лісі. Мила жінка. Ймовірно, їй потрібна ще одна пара рук для роботи, але це краще, ніж залишатися в дитячому будинку.\n\nЯкщо побачите маленького Джеремі, обов'язково скажіть йому, що ми всі думаємо про нього, добре?", [3] = "Доставте Закривавленого Листа Аветті Феллвуд у Сутінковий Ліс.", ["en"] = "Remember That I Love You", ["tasks"] = { ["Blood-Stained Letter"] = "Лист, заплямований кров’ю", ["Blood-Stained Letter (Provided)"] = "Лист, заплямований кров’ю (видано)" } },
    [95204] = { [1] = "Герб Лордерона", [2] = "<Вивітрений герб із зображенням знака Лордерона. З огляду на те, що після падіння королівства залишилося так мало реліквій, хтось у Підмісті дуже хотів би його роздобути.>", [3] = "Принесіть Герб Лордерона Орану Снейкрайту в Підмісті.", ["en"] = "Crest of Lordaeron", ["tasks"] = { ["Crest of Lordaeron"] = "Герб Лордерона", ["Crest of Lordaeron (Provided)"] = "Герб Лордерона (видано)" } },
    [95212] = { [1] = "Ніколи не обтяжуйте себе якістю", [2] = "Ми готуємося відправити команду баранів на підкріплення експедиції Альтераку, але в нас закінчився матеріал для виготовлення їхніх сідел.\n\nЗберіть шкури найбільших, найлютіших леопардів на сході та принесіть їх мені. Там пронизливо холодно, і наші війська заслуговують лише на найкращі шкури, щоб зігрітися!", [3] = "Зберіть 6 незайманих леопардових шкурок і доставте їх на ранчо Амберстілл.", ["en"] = "Never Saddle on Quality", ["tasks"] = { ["Pristine Leopard Pelt"] = "Незаймана леопардова шкура", ["Pristine Leopard Pelt (Provided)"] = "Незаймана леопардова шкура (видано)", ["Pristine Leopard Pelt slain"] = "Незаймана леопардова шкура: убито" } },
    [95213] = { [1] = "Вкрадений вибуховий порошок", [2] = "На бочці стоїть штамп:\n\nВИБУХОВИЙ ПОРОХ - НЕБЕЗПЕКА - НЕ ВИКОРИСТОВУВАТИ - НЕБЕЗПЕКА - ТІЛЬКИ ЗА ДОЗВОЛОМ МАЙСТРА КАР'ЄРУ - НЕБЕЗПЕКА\n\nВиникає неприємне відчуття, що троґґи не повинні цього мати. Краще повідомити про це в кар'єр якомога швидше.", [3] = "Віднесіть порожню порохову бочку начальнику каменоломні Тестену в каменоломні Гол'Болар.", [4] = "Що це в тебе?", [5] = "<Дворф блідне, побачивши порожню бочку.>\n\n...Де ти її знайшов?", ["en"] = "Stolen Blasting Powder", ["tasks"] = { ["Empty Powder Keg"] = "Порожня порохова бочка" } },
    [95214] = { [1] = "Вкрадений вибуховий порошок", [2] = "У цій бочці було достатньо пороху, щоб перетворити тронну залу короля Магні на внутрішній двір просто неба. Нам потрібно повернути його у троггів, перш ніж вони з'ясують, як його підпалити.", [3] = "Знайдіть 16 вкраденого вибухового пороху у трогів на схід від кар'єру Гол'Болар, а потім поверніться до майстра каменоломні Тестена.", [4] = "Сподіваюся, у тебе добрі новини?", [5] = "Це має бути весь викрадений порох. Дякую, воїне.\n\nВізьми цю нагороду і... буду вдячний, якщо ти нікому не розповідатимеш про цей невеличкий випадок.", ["en"] = "Stolen Blasting Powder", ["tasks"] = { ["Stolen Blasting Powder"] = "Вкрадений вибуховий порошок" } },
    [95217] = { [1] = "Коваль кар'єру", [2] = "Отже, ти хочеш навчитися ковальській справі? Можливо, ми зможемо допомогти один одному.\n\nПоставка припасів затримується, і мені потрібні матеріали для ремонту в таборі. Якщо ти принесеш мені те, що мені потрібно, я навчу тебе деяким своїм прийомам. Звучить справедливо?", [3] = "Зберіть 12 мідних злитків та 4 загартовані кабанячі шкури та доставте їх Фрасту Докнеру.", [4] = "Не байдикуй, {ім'я:к}. Ковальство — не для ледачих!", [5] = "Ти винахідливий, {ім'я:к}.\n\nА тепер слухай уважно — я не повторюватиму!", ["en"] = "The Quarry's Smith", ["tasks"] = { ["Copper Bar"] = "злиток міді", ["Toughened Boar Hide"] = "Загартована кабаняча шкура" } },
    [95314] = { [1] = "Той зелений еліксир Тіньодолини", [2] = "До вторгнення Скочу, відлюднене село Тіньова Долина було відоме своїм Шепітливим Еліксиром. Виготовлений з трав, що зустрічаються лише у Падінні Тіра, еліксир шукали аптекарі, містики та отруйники навіть після того, як його заборонили в місті.\n\nЯ отримав запити від багатьох покупців, які прагнули роздобути еліксир. Вирушайте до руїн Тіньової Долини глибоко в Шепітливому Лісі на заході. Я готовий запропонувати значну компенсацію, якщо ви зможете знайти для мене кілька пляшок.", [3] = "Зберіть 8 пляшок Шепочучого Еліксиру в Тіньовій Долині, а потім поверніться до Керолаї Аніс у Брілл.", ["en"] = "That Shadowvale Green Elixir", ["tasks"] = { ["Bottle of Whispering Elixir"] = "Пляшка еліксиру шепоту" } },
    [954] = { [1] = "Башал'Аран", [2] = "Руїни Башал'Арану на сході переповнені демонічним злом. Духи та сатири, що оселилися тут, живляться магічною енергією Башал'Арану, і з часом їхня сила зростає все більше.\n\nПроте я помітив, що є одна святиня, до якої вони не наближаються. На західній стороні руїн, на вершині невеликої скелі, видніється дивне блакитне світіння... Певно там і знаходиться пояснення того, чому демони оминають це місце.\n\nЯ хочу, щоб ти {стать:дослідив:дослідила} його.", [3] = "Знайдіть джерело загадкового синього світіння в руїнах Башал'Арану.", [5] = "Ахх... Чим я можу завдячувати компанії {стать:такого люб'язного:такої люб'язної} {раса:р}, як ви? Воістину, це багато говорить про моїх нинішніх компаньйонів — без образи моїх господарів, благородних грелів і сатирів — що ваша присутність може бути розцінена як поліпшення.\n\nАле, будь ласка, нехай мій нечемний язик не змушує вас піти звідси. Минуло багато років, а то й десятиліть, відколи я мав пристойну компанію.", ["en"] = "Bashal'Aran" },
    [955] = { [1] = "Башал'Аран", [2] = "Я міг би розказати історію свого життя, та, боюсь, це перевершить межі вашого терпіння. Скажімо так, моє життя було довгим і сповненим страждань, а існування в цій примарній формі — чи не найстрашніша мука з усіх.\n\nМене утримують тут за допомогою магії. Хоча мої слова можуть здатися нещирими, запевняю вас, я був би невимовно вдячний, якби ви допомогли мені знайти те, що тримає мене тут. Мене сковує якась печатка, і, дослідивши сережки грелів, я, можливо, зможу знайти її слід.", [3] = "Зберіть 8 сережок грелів для Астеріона в Башал'Арані.", [4] = "Щойно я отримаю сережки, я застосую закляття, щоб знайти місцеперебування печатки, яка мене зв'язує. Століттями я думав про свободу, яку принесе мені знищення печатки... Можливо, ці століття так вплинули на мій розум, що я вже ніколи не зможу прийти до тями...", [5] = "Звісно... Грели Башал'Арану не мають того, що я шукаю... але нещодавно вони вступили з цим у контакт. Нещодавно... Я маю на увазі, за твоїм часом, а не за моїм. Для мене \"нещодавно\" простягається глибоко в минуле, майже в іншу епоху...", ["en"] = "Bashal'Aran", ["tasks"] = { ["Grell Earring"] = "сережка грела", ["Grell Earring (Provided)"] = "сережка грела (видано)" } },
    [95534] = { [1] = "Таємниця Странбрада", [2] = "<Записка подекуди обгоріла, але її ще можна прочитати.>\n\nКажуть, ті старі ковальські міхи живуть власним життям і оживають, коли ніхто не дивиться. Байдуже, чи це байка про привидів: розберися з усім до мого повернення.\n\nУ Странбраді прихована велика сила, я це знаю.\n\n<Решта записки обгоріла й розірвана, наче її спалила магія вогню.>", [3] = "Розгадайте таємницю Странбрада й повідомте про свої знахідки в містечку Гіллзбрад.", ["en"] = "Strahnbrad Mystery", ["tasks"] = { ["Discover the fiery mystery of Strahnbrad"] = "Розгадати вогняну таємницю Странбрада", ["Singed Note"] = "обпалена записка" } },
    [9556] = { [1] = "За перемогу...", [2] = "Ти, без сумніву, довго і важко {стать:бився:билася} за вежі, {раса:к}. Ми хочемо віддячити тобі за захист цих земель, але спершу ти маєш довести, що розумієш всю глибину тутешніх трагедій.\n\nПройдись вулицями Стратгольма і знайди пляшку стратгольмської святої води. Віднеси її у квартал Магів у Штормовій чи Підмістя... Там ти знайдеш моїх колег, якщо твоя фракція перемагатиме в цих землях.", [3] = "Знайдіть пляшку стратгольмської святої води та передайте її в лордеронському магу у квартал Магів Штормовія або Підмістя, коли ваша фракція контролюватиме вежі у Східних Зачумлених землях.", ["en"] = "To The Victor...", ["tasks"] = { ["Stratholme Holy Water"] = "стратгольмська свята вода" } },
    [956] = { [1] = "Башал'Аран", [2] = "Якщо грели входили в тісний контакт з печаткою, що скріплює мою в'язницю, мені здається, я знаю, де її шукати. Без сумніву, печаткою володіє один з сатирів, що керують ними.\n\nЯ відчуваю, що це дійсно так, {ім'я}. Один із сатирів має володіти печаткою. Якщо вам вдасться дістати її, то ви нарешті наблизите мене до свободи, якої я так довго прагну...", [3] = "Дістаньте древню печатку місячного каменю та принесіть її Астеріону в Башал'Аран.", [4] = "Колони цієї святині для мене — тюремні ґрати, {ім'я}. У мене немає сил, щоб зламати їх, і я не знаю жодної магії, що могла б їх знищити...\n\nБільше тисячі років я дивлюся на них, гадаючи, чи буду я нарешті вільний, коли переживу цей камінь? Чи мене триматимуть невидимі ґрати...", [5] = "Мені... мені важко повірити, що те, що я тримаю зараз, утримувало мене так довго. Не гаймо часу, {ім'я}. Коли ми знищимо цю печатку, я зможу знову вільно ходити лісами.", ["en"] = "Bashal'Aran", ["tasks"] = { ["Ancient Moonstone Seal"] = "древня печатка місячного каменю", ["Ancient Moonstone Seal (Provided)"] = "древня печатка місячного каменю (видано)" } },
    [95663] = { [1] = "Чутки про Драконову Пащу", [2] = "Драконова Паща — грізний клан.\n\nВони славляться магією поневолення, достатньо сильною, щоб примушувати драконів служити. Подейкують, у Заболотті вони готуються продемонструвати її. Правда це чи хвальба — Смертолови не можуть діяти на підставі самих лише чуток. Вітри титанів донесли до мене лише це.\n\nНашій агентці потрібна допомога на пагорбах над табором Драконової Пащі. Зустрінься з нею там. Вона пояснить, що робити далі.", [3] = "Вирушайте в Заболоття й зустріньтеся з агенткою Смертоловів на пагорбах над табором Драконової Пащі.", ["en"] = "Dragonmaw Rumors" },
    [95682] = { [1] = "Розкрити Пащу", [2] = "Драконова Паща. <Вона сухо, з насмішкою пирхає.>\n\nЗалишки клану приборкувачів драконів гадають, що знайшли щось, здатне повернути їм колишню могутність. У чиїх очах... їхнього самозваного вождя?\n\nЗнищ їхній жалюгідний загін на розкопках, щоб наші Смертолови могли непомітно проникнути туди.\n\nЯкщо знайдеш у Драконової Пащі щось варте уваги, принеси мені. Ці відомості мають залишитися між нами та нашим королівським командуванням.", [3] = "Убийте бійців Драконової Пащі на розкопках і поверніться до агентки Смертоловів з усім, що знайдете.", ["en"] = "Open the Maw", ["tasks"] = { ["Dragonmaw Dispatch"] = "Депеша Драконової Пащі", ["Dragonmaw Saboteur"] = "Диверсант Драконової Пащі", ["Dragonmaw Saboteur slain"] = "Диверсант Драконової Пащі: убито", ["Dragonmaw Warder"] = "Вартовий Драконової Пащі", ["Dragonmaw Warder slain"] = "Вартовий Драконової Пащі: убито" } },
    [95737] = { [1] = "У пошуках Кейтлін", [2] = "Час від часу я листуюся з іншими знавцями свого ремесла — травниками та диваками, що вивчають рідкісні рослини й місцеві дива. Ми обмінюємося відкриттями, а іноді й застереженнями про те, що чекає попереду.\n\nОдна алхімікиня із Заболоття писала про експедицію, до якої входив її чоловік. Вони знайшли сліди давно зниклої первісної трави... але вона так і не повідомила, наскільки ця рослина поширена й доступна.\n\nЯкщо можеш, навідай Кейтлін Трав'яну в гавані Менетілів.", [3] = "Поговоріть із Кейтлін Трав'яною в гавані Менетілів.", ["en"] = "Seeking Caitlin" },
    [95771] = { [1] = "Смак темряви", ["en"] = "A Taste of Darkness", ["tasks"] = { ["Scout through the Fargodeep Mine"] = "Дослідіть Бездонну копальню" } },
    [95772] = { [1] = "У пошуках Лезоспіва", [2] = "Мій брат намагався потягти мене в Заболоття з якоюсь експедицією з Лох-Модану. Казав, вони збираються на розкопки серед пагорбів, де ще не ступала нога дворфа.\n\nАвжеж, я пішов би, якби не мав стільки поясів, які треба переробити.\n\nЗазвичай Дейвін пише, щойно вирушить. А цього разу жодної звістки, і це якось дивно.\n\nЯкщо йтимеш туди, чи не міг би ти навідати мого брата?", [3] = "Знайдіть Дейвіна, брата Доріна Лезоспіва, на розкопках Вельґара.", ["en"] = "Songblade Search" },
    [958] = { [1] = "Інструменти високородних", [2] = "{Клас:к}. В мене є для тебе завдання.\n\nЧи траплялось тобі бачити руїни Амет'Арана? Якщо ні — ти знайдеш їх на схід від головної дороги, трохи на південь звідси. Колись Амет'Аран був домом для багатьох могутніх високородних, а тепер це пам'ятник руйнуванням, до яких призвела їхня недалекоглядність.\n\nСтражі сказали мені, що духи високородних все ще мешкають там, і що вони орудують своїми древніми магічними знаряддями. Ти маєш забрати ці реліквії, щоб ми могли їх знищити.", [3] = "Принесіть 7 реліквій високородних Тандрісу Вітроткачу в Аубердін.", [4] = "Якби ж їхні інструменти могли бути знищені під час катаклізму, що зруйнував наш світ... Проте, ми повинні зробити все можливе, щоб жахи нашого минулого не повторилися в майбутньому.", [5] = "Хоча це, звичайно, лише плід моєї уяви, але мені здається, що я відчуваю в цих реліквіях рештки брудної магії високородних. Я знищу їх, щоб їхнє дрімуче зло більше ніколи не вирвалося на волю.", ["en"] = "Tools of the Highborne", ["tasks"] = { ["Highborne Relic"] = "реліквія високородних", ["Highborne Relic (Provided)"] = "реліквія високородних (видано)" } },
    [95816] = { [1] = "Зареєструй мене!", [2] = "Вітання, досвідчений майстре!\n\nЗаповнення цієї форми надасть вам невиключний, відкличний та юридично обмежений дозвіл на розміщення рекламних вивісок для ваших ремесел по всьому Азероту!\n\nПісля заповнення, будь ласка, віднесіть її до координатора контрактів вашого місцевого відділення Торгового управління Азероту для початку обробки.\n\nЩасливого рукоділля!", ["en"] = "Sign Me Up!", ["tasks"] = { ["Advertising License Application"] = "Заява на ліцензію на рекламу", ["Massive Pile of Completed Forms"] = "Величезна купа заповнених форм" } },
    [95819] = { [1] = "Зареєструй мене!", [2] = "Вітання, досвідчений майстре!\n\nЗаповнення цієї форми надасть вам невиключний, відкличний та юридично обмежений дозвіл розміщувати рекламні вивіски для вашої(их) майстерності(й) по всьому Азероту!\n\nПісля заповнення, будь ласка, передайте її вашому місцевому координатору контрактів з постачання та логістики в Дуротарі для початку обробки.\n\nЩасливого рукоділля!", ["en"] = "Sign Me Up!", ["tasks"] = { ["Advertising License Application"] = "Заява на ліцензію на рекламу", ["Massive Pile of Completed Forms"] = "Величезна купа заповнених форм" } },
    [95883] = { [1] = "Закатована душа", [2] = "<На вівтарі безцеремонно збираються всі необхідні матеріали для поспіхом організованого ритуалу. Згідно з уривком записки, все вже зібрано. Бракує лише жертви крові та Закатованої Душі.\n\nНежить навколо вас виглядає досить закатованою. Можливо, у них є те, що ви шукаєте.>", [3] = "Зберіть Закатовану душу у сусідньої нежиті в Небезпеці Берена у Сріблястому лісі.", ["en"] = "The Tortured Soul", ["tasks"] = { ["Tortured Soul"] = "Закатована душа" } },
    [95884] = { [1] = "Камінь жертвопринесення", [2] = "<Уривок записки здебільшого нерозбірливий. Однак, те, що все ще можна прочитати, це нотатки про підготовку до жертвопринесення.\n\nЗгадується камінь для жертвопринесення, а також ритуал.\n\nМожливо, ви зможете знайти цей камінь для жертвопринесення поблизу.>", [3] = "Знайдіть Камінь підношень у Небезпеці Берена у Сріблястому лісі.", ["en"] = "The Offering Stone", ["tasks"] = { ["Note Scrap"] = "Записка" } },
    [95885] = { [1] = "Жертва крові", [2] = "<Залишилося лише принесення крові.\n\nУ клаптику записки згадувалося про «добровільну жертву».\n\nВас охоплює сильне відчуття жаху.>", [3] = "Використайте Закатовану Душу, щоб принести жертву крові біля Каменя Жертв у Небезпеці Берена.\n\nНаданий предмет:", ["en"] = "The Offering of Blood", ["tasks"] = { ["Release Tortured Soul"] = "Звільніть змучену душу", ["Tortured Soul slain"] = "закатована душа: убито", ["Willingly offer blood"] = "Охоче пропонувати кров" } },
    [959] = { [1] = "Халепа в доках", [2] = "Ой!\n\nЯк бачиш, у нас тут невеличка проблемка. Вранці до нас прийшов вантаж з Грабіжної Бухти. Здоровенний, скажу тобі. Ніколи не бачив стільки ящиків. Я хотів швиденько закінчити, тож брав більше ящиків, ніж міг втримати. От воно все й посипалось!\n\nНе встиг я отямитись, як цей негідник, Божевільний Маґґліш, втік з пляшкою 99-річного портвейну. Я біг за ним аж до Плачучих печер. Але всередину я ні за що не піду.\n\nМоже, тобі вистачить сміливості пошукати його там?", [3] = "Кранівник Біґґльфуз з Брашпиля просить вас відібрати пляшку 99-річного портвейну у Божевільного Маґґліша, що ховається в Плачучих печерах.", [4] = "Начальник доку не дає мені спокою з того часу, як Божевільний Маґґліш втік з 99-річним портвейном. Схоже, що ця пляшка була подарунком для Ґазлоу від самого барона Ревілґаза.\n\nЯкщо тобі вистачить сміливості й терпіння, щоб знайти Божевільного Маґґліша і повернути портвейн — я тобі щедро віддячу.", [5] = "Неймовірно! А мене ледь не звільнили! Я зараз-но віднесу це Ґазлоу.\n\nДякую, {ім'я}. Чудова робота!", ["en"] = "Trouble at the Docks", ["tasks"] = { ["99-Year-Old Port"] = "99-річний портвейн", ["99-Year-Old Port (Provided)"] = "99-річний портвейн (видано)" } },
    [96] = { [1] = "Поклик води", [2] = "Візьми осколок. Візьми осколок і даруй життя.\n\nДаруй життя і розумій. Розумій, що вода — це життя... псування зупиняє життя.\n\nТи захищаєш і даруєш життя силою води.", [3] = "Принесіть осколок води до Іслен Морської Провидиці у Степи.", [4] = "Ти {стать:повернувся:повернулась}. Чудово!\n\nЯк пройшла твоя подорож до Срібнохвою? Це зайняло багато часу?\n\nМені важко сказати, чи все пройшло в тебе добре, оскільки надто багато землі було зіпсовано. Цей сморід перекриває будь-яке благо, яке ти {стать:міг би:могла б} зробити. Але маленькі успіхи інколи такі ж важливі, як і великі. Очищення води там було корисним і для тебе, і для всіх інших шаманів.", [5] = "Це доказ, якого я просила. Ти добре {стать:впорався:впоралась}, {ім'я}.\n\nМені приємно бути першою, хто привітає тебе і подарувати тобі цей... твій тотем води.\n\nВикористовуй його з розумом і хай тобі щастить.\n\nТебе чекає ще одне випробування через деякий час, тож добре підготуйся. Чиста вода не тільки повертає життя пораненим, але й вміє й багато інших речей. Я рекомендую тобі пошукати тренерів шаманів, коли буде час. Можливо, у них є нові заклинання, які ти можеш вивчити.", ["en"] = "Call of Water", ["tasks"] = { ["Shard of Water"] = "осколок води", ["Shard of Water (Provided)"] = "осколок води (видано)" } },
    [960] = { [1] = "Міркування Ону", [5] = "Я розмірковую над твоїм завданням, {ім'я}. Розмірковую над причинами присутності Сутінкового Молота і наг.\n\nКоли ти будеш {стать:готовий:готова} - скористайся фіалом провидіння, щоб створити чашу провидіння. Потім зв'яжися зі мною за її допомогою.\n\nЯкщо ти {стать:загубив:загубила} свій фіал — візьми цей.", ["en"] = "Onu is meditating" },
    [961] = { [1] = "Міркування Ону", [5] = "Присутність сектантів Сутінкового Молота викликає занепокоєння. Я маю поміркувати про їхні наміри...\n\nКоли матимеш більше інформації — поговори зі мною за допомогою чаші провидіння. Якщо для створення чаші тобі не вистачає фіалу провидіння, то... ось, тримай ще один.", ["en"] = "Onu is meditating" },
    [96101] = { [1] = "На свіжому повітрі", [2] = "Вітаю, {клас}. Бачу, що у вас вигляд шукача пригод. Це добре. Світу потрібно більше нас, неспокійних душ, які прагнуть багатства та слави.\n\nТобі потрібно навчитися процвітати в дикій природі, щоб досягти успіху в цій сфері. Не впевнений, як у тебе справи з навичками активного відпочинку на природі, але я, мабуть, можу тебе дечому навчити, якщо ти схильний до навчання.\n\nСядьте біля вогню та влаштуйтеся зручніше. Я тобі все розповім.", [3] = "Сядьте біля Базового Багаття Раана, набравши /sit у вікні чату, та зачекайте, поки отримаєте баф «Посилений відпочинок».", [4] = "Навички, потрібні для виживання просто неба, вкрай важливі. Добре відпочилий і добре підготовлений шукач пригод має значно більше шансів вижити за такого способу життя.", [5] = "Тепер, коли ми опанували основи, чому б тобі не піти й не вивчити ремесло у наставників у сусідньому селищі? Вони також навчать тебе створювати табірний об'єкт, що відповідає твоїй новій професії.", ["en"] = "The Great Outdoors", ["tasks"] = { ["Gain the Boosted Rest buff"] = "Отримайте бафф «Посилений відпочинок»", ["Use the /sit emote near the campfire"] = "Використайте емодзі /сидіти біля багаття" } },
    [963] = { [1] = "Заради вічного кохання", [2] = "Після битв за Колодязь Вічності я дізнався, що Амет'Аран було зруйновано, а його жителі загинули — зокрема й моя кохана Анайя.\n\nЯ б ніколи не подумав, що й через тисячі років спогади про Анайю все ще переслідуватимуть мене. Блукаючи уві сні лісами Темнобережжя, я опинився в руїнах Амет'Арана... де побачив неупокоєний дух моєї коханої.\n\nЇї треба звільнити, але я не можу цього зробити. Потрібно знищити її дух.", [3] = "Звільніть дух Анайї Зорегін і поверніть її кулон Цереліану Білопазуру в Аубердін.", [4] = "З великою скорботою в серці я пішов за Шан'до Шаленством Бурі в сплячку і занурився у свої сни, проспавши тисячі років.", [5] = "Дякую тобі, {ім'я}. Можливо, було б краще... якби я зробив це сам. Але навіть через ці тисячі років я не зміг би підняти руку на свою кохану.\n\nПрошу, залиш мене наодинці з моїм горем...", ["en"] = "For Love Eternal", ["tasks"] = { ["Anaya's Pendant"] = "кулон Анайї", ["Anaya's Pendant (Provided)"] = "кулон Анайї (видано)" } },
    [96390] = { [1] = "Придушити їх у зародку", [2] = "Шпигуни Темного Заліза проникли в Дун Морог. З якою метою, я не знаю, але це проблема, яку нам потрібно придушити в зародку, перш ніж вона розростеться.\n\nВирушайте на схід до комплексу Залізної Зв'язки та вбивайте шпигунів Темного Заліза, яких там знайдете.", [3] = "Убийте 10 шпигунів з темного заліза в Дун Морог.", [5] = "Ці гноми Темного Заліза, може, й наші родичі, та ріднею їх не назвеш. Я не проллю сльози, якщо когось із них спіткає лихо, коли він забреде надто далеко від своєї проклятої гори.\n\nСподіваюся, цього вистачить, щоб відбити в них бажання знову вдиратися в наші землі.", ["en"] = "Nip 'Em in the Bud", ["tasks"] = { ["Dark Iron Spy"] = "шпигун Темного Заліза", ["Dark Iron Spy slain"] = "шпигун Темного Заліза: убито" } },
    [96391] = { [1] = "Підземна карта", [2] = "<Карта, яку ви тримаєте в руках, здається, показує складну серію підземних тунелів та автомагістралей, які, здається, сходяться в одній точці під самою Залізогарт.\n\nВи не можете бути впевнені, що говорять руни, оскільки вони написані потворною зубчастою рунічною мовою гномів Темного Заліза, але ви можете здогадатися про призначення цих тунелів. Коли ви читаєте карту, вас охоплює порив вітру, і ви ледь чуєте гномський голос, що лунає по ньому. Землепровидець Фарсен повинен це побачити.>", [3] = "Доставте карту Темного Заліза землепровидцю Фарсену в Дун Морог.", [4] = "О, а це що таке?", [5] = "Судячи з цієї карти, гноми Темного Заліза планують проникнути до сховищ під Залізогартом. Та банда, яку ти розгромив на сході, мабуть, була розвідниками.\n\nДякую, що приніс її. Якщо поквапимося, то, можливо, випередимо їх і першими дістанемося до їхньої мети.", ["en"] = "Underground Map", ["tasks"] = { ["Dark Iron Map"] = "Карта Темного Заліза", ["Dark Iron Map (Provided)"] = "Карта Темного Заліза (видано)", ["Dark Iron Map slain"] = "Карта Темного Заліза: убито", ["Deliver the Dark Iron Map to Earthseer Farsen in Dun Morogh."] = "Доставте карту Темного Заліза землепровидцю Фарсену в Дун Морог." } },
    [96392] = { [1] = "Дозор Фарсена", [2] = "Вітаю тебе, друже. Мене звати Землепровидець Фарсен, і я відвідую Дун Морог з Піку Ері. Під час подорожі я не міг не помітити, що у нас є, ну... невелика проблема з Темними Залізними Гномами.\n\nЯкщо у тебе є хвилинка, я можу тобі показати, що я маю на увазі. У мене є трохи магії, яка має допомогти.", [3] = "Поговоріть із землевіком Фарсеном і попросіть його позичити вам свій далекозір, щоб ви могли спостерігати за загрозою Темного Заліза.", [4] = "Далекоглядність може показати тобі багато чого, навіть те, чого ти волів би не бачити.", [5] = "Тепер бачиш, воїне? Їх тут як тарганів, і це лише ті, кого ми можемо розгледіти з неба.\n\nБачу, сили тобі не бракує. Як щодо трохи повоювати?", ["en"] = "Farsen's Watch", ["tasks"] = { ["Use Farsen's Farsight"] = "Використайте далекоглядність Фарсена" } },
    [96393] = { [1] = "Вторгнення до Старого Залізогарта", [2] = "Зберіть союзників і спустіться в печери під Старою Залізогартом. Увійдіть до Зали Танів і пройдіть до нижніх сховищ.\n\nМоє Темне Залізо трохи іржаве, але я можу розібрати ім'я — хтось Дурген Жалобний Молот. Цілком ймовірно, що він командир. Візьміть його голову та доставте її королю Магні Бронзобородому.\n\nО, і коли це зробите, передайте йому, що його старий друг Фарсен передає йому вітання!", [3] = "Увійдіть до Зали Танів під Старою Залізогартом та заберіть Голову Дургена Жалобного Молота.", [4] = "Що тобі потрібно, громадянине?", [5] = "Вторгнення Темного Заліза — просто в нас під ногами? Що ж, я радий чути, що командира Темного Заліза знищено.\n\nВарта спуститься туди й зачистить решту покидьків. Ми запечатаємо проломи й укріпимо нижні рівні, щоб більше жодних вторгнень не сталося.\n\nДякую за службу Залізогарту, {стать:воїне:воїтелько}. Прийми це як невеликий знак моєї вдячності. І якщо знову побачиш того старого каменеобіймача з клану Дикого Молота, Фарсена, скажи йому нарешті завітати до мене як слід.", ["en"] = "Old Ironforge Incursion", ["tasks"] = { ["Durgen Dirgehammer's Head"] = "Голова Дургена Діргехаммера", ["Durgen Dirgehammer's Head (Provided)"] = "Голова Дургена Діргехаммера (видано)", ["Durgen Dirgehammer's Head slain"] = "Голова Дургена Діргехаммера: убито" } },
    [96395] = { [1] = "Давня образа", [2] = "Тан... мій могутній... Тан... йому... потрібен... відпочинок.\n\nБудь ласка... допоможіть йому... допоможіть йому... відпочинок...\n\nПоглинутий... давньою... образою... Без... відпочинку...", [3] = "Упокойте дух Фалдріма Анвілмара, а потім поверніться до примарного служителя в Залі танів.", [5] = "Мій... тан... він... спочиває... так... спочинок.\n\nДякую... тобі...\n\nЯ... спочину...", ["en"] = "An Ancient Grudge", ["tasks"] = { ["Faldrim Anvilmar slain"] = "Фалдрім Анвілмар: убито" } },
    [96403] = { [1] = "Важливі сімейні реліквії", [2] = "Ти там, шукачу пригод... Мені дуже потрібна твоя допомога.\n\nЯ прокрадався... е-е... «патрулював» у сховищах, коли з глибин на машинах-кротах виринув загін дворфів Темного Заліза! Я не знаю, для чого вони тут, але там безцінна здобич... е-е, чи, радше... я маю на увазі, «важливі культурні реліквії»! Будь ласка, знайдіть будь-які такі реліквії, які побачите, і поверніть їх сюди.\n\nЗапевняю вас, що все, що ви знайдете, буде каталогізовано та повернуто на належне почесне місце.", [3] = "Зберіть 8 гномьих реліквій з Чертога Танів.", [4] = "<Том, дивлячись на вас, неуважно потирає руки.>", [5] = "Який ти {стать:хоробрий:хоробра} та {стать:підприємливий:підприємлива}! Я гном слова, тож ти чесно {стать:заслужив:заслужила} свою нагороду!\n\nА тепер дай-но поглянути на здобич... е-е, тобто на врятовані реліквії. Треба якнайшвидше взятися до їхньої оцінки... перепрошую, «каталогізації», щоб повернути все на належні місця.", ["en"] = "Important Heirlooms", ["tasks"] = { ["Dwarven Heirloom"] = "Гномська реліквія", ["Dwarven Heirloom (Provided)"] = "Гномська реліквія (видано)", ["Dwarven Heirloom slain"] = "Гномська реліквія: убито" } },
    [965] = { [1] = "Вежа Алталакса", [2] = "Вітаю тебе, {стать:юний:юна} {раса:к}. Я Елісса Зоребриз, і мій обов'язок — захищати Аубердін від шкоди.\n\nЗ цією метою я відправила Балтула Тіневдара спостерігати за дивними явищами, що відбуваються поблизу вежі Алталакса на північний схід звідси.\n\nАле він давно вже мав би повернутися. Я боюся, що він зіткнувся з якоюсь непередбачуваною небезпекою. Я була б тобі дуже вдячна, якби ти {стать:знайшов:знайшла} його і {стать:переконався:переконалась}, що з ним все гаразд.", [3] = "Знайдіть Балтула Тіневдара біля вежі Алталакса на Темнобережжі.", [5] = "Тебе прислала Елісса? Це добре. Я мав повідомити їй тривожну звістку, але не міг передати її.", ["en"] = "The Tower of Althalaxx" },
    [966] = { [1] = "Вежа Алталакса", [2] = "Група чорнокнижників оселилася навколо і всередині вежі. Я хотів повернутися до Аубердіну, щоб доповісти Еліссі, але боявся, що можу щось пропустити.\n\nДельґрен підозрював, що подібна компанія може збиратися у вежі, але не знав, навіщо.\n\nМені вдалось дістати кілька клаптиків пергаменту, які носять з собою чорнокнижники, але мені потрібно більше, щоб розгадати їх задуми. Однак, попереджаю тебе, не намагайся заходити до вежі — чорнокнижники, що засіли там, набагато сильніші!", [3] = "Принесіть 4 потертих пергаменти Балтулу Тіневдару біля вежі Альталакса.", [4] = "Тобі вдалось знайти більше їхніх сувоїв? Я зможу скласти краще уявлення про культ, якщо ти зможеш їх знайти.", [5] = "Дуже дякую, {ім'я}. Це має пролити світло на те, чим займається це збіговисько чорнокнижників...\n\nХм... культ Темного Пасма... Я ніколи раніше не чув про цю групу. Не знаючи їхньої історії, практично неможливо сказати точно, які у них плани.\n\nМи більше не можемо зволікати. Потрібно негайно попередити Дельґрена.", ["en"] = "The Tower of Althalaxx", ["tasks"] = { ["Worn Parchment"] = "потертий пергамент", ["Worn Parchment (Provided)"] = "потертий пергамент (видано)" } },
    [96638] = { [1] = "Шукач пригод", [2] = "Все більше шукачів пригод, таких як ви, шукають слави та багатства за межами безпеки Тендал-Гроув. Є один такий шукач пригод, який розбив табір за межами села Шен'дар, вздовж дороги, що веде на південний захід з Тендал-Гроув.\n\nЗнайдіть його та подивіться, чого ви можете навчитися у нього, що може допомогти вам у ваших власних подорожах.", [3] = "Поговоріть з Рааном Диким Вітром біля села Шен'дар.", [5] = "Радий зустрічі!", ["en"] = "The Adventurer" },
    [9664] = { [1] = "Встановлення нових аванпостів", [2] = "Ласкаво прошу до Зачумлених земель, {ім'я}. Як ти знаєш, відречені та їх союзники утримують землі на захід звідси, не дивлячись на всі наші зусилля. Командири Альянсу вирішили, що ми маємо встановити нові аванпости у Східних Зачумлених землях, щоб укріпити наші позиції на кордонах наших ворогів.\n\nВежі, що були закинуті за часів руїни Лордерона, потрібно захопити та відновити. Ці краї надто небезпечні, тож нам знадобиться твоя допомога.", [3] = "Захопіть вежу Королівської варти, Східну вежу, вежу Північного ходу, і вежу Чумолісся у Східних Зачумлених землях, а потім поверніться до емісара Білоборода, близ Каплиці Надії Світла.", [4] = "Коли вежі будуть під нашим контролем, ми зможемо оточити відречених. Тоді наша перемога над ними буде лиш питанням часу.", [5] = "Чудово, {ім'я}. Дуже важливо утримувати ці вежі, тож нам знадобиться твоя допомога, доки не прибудуть наші війська.", ["en"] = "Establishing New Outposts", ["tasks"] = { ["Capture Crown Guard Tower"] = "Захоплення вежі Коронної варти", ["Capture Crown Guard Tower (Provided)"] = "Захоплення вежі Коронної варти (видано)", ["Capture Crown Guard Tower slain"] = "Захоплення вежі Коронної варти: убито", ["Capture Eastwall Tower"] = "Захоплення вежі Істволл", ["Capture Eastwall Tower (Provided)"] = "Захоплення вежі Істволл (видано)", ["Capture Eastwall Tower slain"] = "Захоплення вежі Істволл: убито", ["Capture Northpass Tower"] = "Захоплення вежі Нортпасс", ["Capture Northpass Tower (Provided)"] = "Захоплення вежі Нортпасс (видано)", ["Capture Northpass Tower slain"] = "Захоплення вежі Нортпасс: убито", ["Capture Plaguewood Tower"] = "Захоплення вежі Чумного лісу", ["Capture Plaguewood Tower (Provided)"] = "Захоплення вежі Чумного лісу (видано)", ["Capture Plaguewood Tower slain"] = "Захоплення вежі Чумного лісу: убито" } },
    [96646] = { [1] = "Основи таборування: куховарство", [2] = "Отже, ви хочете дізнатися більше про кемпінг, га? Молодець, {клас}. Перший крок, який має зробити будь-який шукач пригод, — це стати кухарем і навчитися розводити багаття.\n\nКулінарія — це не просто приготування смачної їжі. Це також основа вашого табору.", [3] = "Поговоріть із Зерріл М'який Бриз у селі Шен'дар, щоб навчитися бути кухарем.", ["en"] = "Camping 101: Cooking", ["tasks"] = { ["Learn cooking from Zerril Softbreeze in Shen'dar Village"] = "Навчіться готувати у Зерріл Софтбріз у селі Шен'дар" } },
    [96735] = { [1] = "Тост!?", ["en"] = "Toast!?" },
    [96779] = { [1] = "Саботаж Синдикату", [2] = "Іноді, {раса:к}, одного удару в потрібне місце досить, щоб ворог упав мертвим. З організаціями часто так само.\n\nНаші агенти визначили важливу ціль серед членів Синдикату — людину на ім'я лорд Томас.\n\nВін відіграє ключову роль у справах фортеці Дарнгольд у передгір'ї Гіллзбраду. Якщо хочеш послужити Воронгольдту, вирушай у Дарнгольд і усунь його. Що швидше й тихіше, то краще.", [3] = "Знайдіть і вбийте лорда Томаса у фортеці Дарнгольд у передгір'ї Гіллзбраду. Потім поверніться до Мірокоса Тихоступа.", ["en"] = "Syndicate Sabotage", ["tasks"] = { ["Lord Tomas"] = "Лорд Томас", ["Lord Tomas slain"] = "Лорд Томас: убито" } },
    [96781] = { [1] = "Що вони задумали?", [2] = "Ми помітили розвідувальний загін Синдикату, який нишпорить серед руїн Альтераку під проводом чоловіка на ім'я Бартон.\n\nВони явно щось шукають, але я не дізнаюся що саме, доки не прочитаю його розвідувальні звіти.\n\nПрошу тебе викрасти звіт у нього з кишені, а не вбивати його. Смерть Бартона дасть Синдикату зрозуміти, що ми їх викрили, і вони неодмінно вживуть заходів, щоб замести сліди.\n\nШукати його найкраще серед членів Синдикату в Странбраді.", ["en"] = "What's the Big Idea?", ["tasks"] = { ["Barton's Scouting Report"] = "Розвідувальний звіт Бартона" } },
    [96782] = { [1] = "Таємне вилучення", [2] = "Схоже, наш приятель Бартон неабияк спростив нам справу. Він шукає серед руїн Альтераку дві родинні реліквії Перенольдів: меч — клинок дому Перенольдів, і щит — королівську егіду Перенольдів.\n\nЗі звіту випливає, що ця зброя зберігається у двох вежах серед руїн. Краще здобути її раніше за Синдикат.\n\nОгри, що оселилися в руїнах, люті, але я впевнений: ти зможеш непомітно пройти повз них, навіть не закривавивши свого клинка.", ["en"] = "Covert Extraction", ["tasks"] = { ["Blade of House Perenolde"] = "Клинок дому Перенольдів", ["Royal Aegis of Perenolde"] = "Королівська егіда Перенольдів" } },
    [96783] = { [1] = "Шлях усередину", [2] = "Фортеця Стромварт — один із найбільших оплотів Синдикату. За її стінами відбувається чимало найважливіших справ цієї організації.\n\nДо мене дійшла звістка про якусь оборудку між членами Синдикату десь у нагір'ї Араті. Певен, її подробиці можна знайти в Стромварті.\n\nЩоб проникнути у фортецю без підозр, тобі потрібне маскування. Спробуй знайти його в членів Синдикату поза фортецею, у садибі Північного поля.", ["en"] = "A Way In" },
    [96784] = { [1] = "Майстер маскування", [2] = "<Ви пригадуєте доручення Мірокоса: дізнатися про важливу оборудку Синдикату у фортеці Стромварт. Завдяки маскуванню ви зможете досить вільно розмовляти з членами Синдикату. Напевно, хтось із них щось знає.>", ["en"] = "Master of Disguise", ["tasks"] = { ["Syndicate Uniform"] = "Уніформа Синдикату" } },
    [96785] = { [1] = "Нічого не скажу", [2] = "Ким ти себе уявляєш? Приходиш сюди й пхаєш носа в службові справи.\n\nЯ не розповідатиму якомусь новачкові про справи керівництва без поважної причини. Якщо не маєш для мене чогось важливого або цінного, мені нема чого тобі сказати.", ["en"] = "Ain't No Telling", ["tasks"] = { ["Stolen Funds"] = "Вкрадені кошти" } },
    [96786] = { [1] = "Перехоплення Синдикату", [2] = "Соколохресний послав кількох хлопців забрати вантаж біля південної частини стіни Торадіна. Не знаю, що вони забирають. Мабуть, щось цінне, бо всі причетні тримають це в цілковитій таємниці. Думаю, навіть ті, хто його забирає, не знають, що це.\n\nЦе все, що мені відомо. Не змушуй мене шкодувати, що розповів тобі.", ["en"] = "The Syndicate Sting", ["tasks"] = { ["Intercepted Shipment"] = "Перехоплений вантаж", ["Syndicate Uniform"] = "Уніформа Синдикату" } },
    [969] = { [1] = "Хай буде з тобою удача!", [2] = "А, бачу, шо ти хоч собі талісман на вдачу. Мав'арі завжди всьо знає!\n\nНа південь отсюда находиться каньйон, де є велетні з твердого льоду, у яких єсть уламки. Їх можна найти у велетнів, але ти можеш собрать уламки в каньйоні. Ці уламки мають отмєнні відбивні властивості.\n\nПринеси мені 10 уламків кригобоїв, і дам тобі талісман удачі.", [3] = "Зберіть 10 уламків кригобоїв для знахарки Мав'арі з Завшегляду.", [4] = "Принеси уламки, і я розкажу тобі більше!", [5] = "О, так... Я зараз зроблю тобі талісман. Пожди!", ["en"] = "Luck Be With You", ["tasks"] = { ["Frostmaul Shards"] = "уламки кригобоїв", ["Frostmaul Shards (Provided)"] = "уламки кригобоїв (видано)" } },
    [970] = { [1] = "Вежа Алталакса", [2] = "Лист Балтула тривожить мене. Цей культ Темного Пасма — велика проблема, від якої треба позбутися. Мені доводилося мати справу з мерзотниками Темного Пасма на північний схід звідси, в Орділ'Арані. Один з них має камінь душі, який, як я вважаю, містить секрет сили культу.\n\nПринеси його мені, і я зможу розгадати його таємницю.", [3] = "Принесіть сяючий камінь душі Дельґрену Очистителю на заставу Маєстри.", [4] = "Тобі вдалось дістати цей камінь душі?", [5] = "Хм, цей камінь душі містить якусь темну магію. Давай-но подивимося, що в ньому всередині...", ["en"] = "The Tower of Althalaxx", ["tasks"] = { ["Glowing Soul Gem"] = "сяючий камінь душі", ["Glowing Soul Gem (Provided)"] = "сяючий камінь душі (видано)" } },
    [97065] = { [1] = "Схилити чашу терезів - рибка-ангел Кіфера", ["en"] = "Tip the Scales - Keefer's Angelfish", ["tasks"] = { ["Keefer's Angelfish"] = "риба-ангел Кіфера" } },
    [97066] = { [1] = "Схиліть терези - блакитно-смугастий скакун Браунелла", ["en"] = "Tip the Scales - Brownell's Blue Striped Racer", ["tasks"] = { ["Brownell's Blue Striped Racer"] = "синій смугастик Браунелла" } },
    [97067] = { [1] = "Схилити терези - Дезіанська королева", ["en"] = "Tip the Scales - Dezian Queenfish", ["tasks"] = { ["Dezian Queenfish"] = "дезійська ставрида" } },
    [971] = { [1] = "Знання в глибинах", [2] = "Як ти певно знаєш, я збираю знання. Старі знання. Могутні знання. Знання, що відкривають нові світи й знання, що можуть розбудити Тих, Що Сплять.\n\nШиряться чутки про старезні знання — манускрипт Лорґаліса, що лежить на дні Чорноводних глибин в Ясенедолі. Колись давно там жили ельфи, що оберігали могутні знання. Та всі вони тепер мертві, а їх обитель лежить в руїнах.\n\nЙди до Чорноводних глибин і знайди цей манускрипт. Зробиш це — і я ніколи цього не забуду. Навіть після... кінця часів.", [3] = "Принесіть манускрипт Лорґаліса до Ґерріґа Кісткохвата в Закинуту Печеру Залізогарту.", [4] = "Дорога до Ясенедолу довга, а завдання твоє непросте. Але якщо знайдеш манускрипт, {ім'я}... твоя нагорода буде гідною.", [5] = "Манускрипт у тебе! Що за чудовий день! Ми зробимо й розповсюдимо його копії, тож древні знання Лорґаліса стануть доступними моїм братам і сестрам!\n\nТи навіть не уявляєш, наскільки це велика справа, {ім'я}. Сподіваюсь, цей дар гідно продемонструє нашу вдячність.", ["en"] = "Knowledge in the Deeps", ["tasks"] = { ["Lorgalis Manuscript"] = "манускрипт Лорґаліса", ["Lorgalis Manuscript (Provided)"] = "манускрипт Лорґаліса (видано)" } },
    [972] = { [1] = "Сапта води", [5] = "{ім'я}, візьми сапту води та знайди зіпсовану водойму у Срібнохвої. Я покладаю великі надії на твої здібності.", ["en"] = "Water Sapta" },
    [97220] = { [1] = "Послуга Філмора", [2] = "Щодня цього тижня нам не вистачало докерів.\n\nХочете полегшити наш графік вантажних перевезень?\n\nВіднесіть цю посилку до входу до складу сторожки. Ви знайдете її в сирній крамниці Тріаса на другому поверсі. Господиня, Елейн, добре знайома з доставкою. До сторожки часто надходять посилки з більшою дискретністю, щоб мати змогу влаштувати урочисті сюрпризи від імені офіцерів варти.", [3] = "Принесіть вантаж з прохідної до входу на склад, розташований у сирній крамниці Тріаса в Торговому районі.", ["en"] = "Philmor's Favor", ["tasks"] = { ["Gatehouse Shipment"] = "Відвантаження на сторожку", ["Gatehouse Shipment (Provided)"] = "Відвантаження на сторожку (видано)" } },
    [97222] = { [1] = "Товари для сторожки", [2] = "Так, це лише сходовий проліт, але якщо це таке невелике прохання, то для вас не повинно бути проблемою самостійно завершити доставку!\n\nСир Тріас не входить до складу воріт чи їхнього інвентарю, але наші будівлі мають один поверх.\n\nПоставте ящик біля дверей їхнього складу — охоронець надішле когось за звичайною посилкою. Вони побачать прибуття посилки та занесуть її всередину, коли повернуться на склад.", [3] = "Віднесіть вантаж з сторожки нагору сходами в магазині Тріаса та залиште його за дверима.\n\nНаданий предмет:", ["en"] = "Gatehouse Goods", ["tasks"] = { ["Gatehouse Shipment delivered"] = "Доставка на сторожку" } },
    [97223] = { [1] = "Матріарх Кривавого Кігтя", [2] = "Усіх хижаків, яких ви бачите перед собою, я сам дресирував. Вони походять з усього Калімдору, але деякі з найкращих походять від хижаків Кривавих Кігтів з островів біля нашого узбережжя.\n\nОдин хижак серед них, Матріарх Кривавих Кігтів, особливо лютий і вбив багатьох мешканців нашого села, і став надто небезпечним, щоб залишати його на наших кордонах. Якщо ви зможете її знищити, поверніться з її яйцями, щоб ми могли виростити дитинчат як союзників, а не ворогів.", [3] = "Принесіть Яйця Матріарха Кривавого Кігтя Ксар'Ті в селі Сен'джін.", ["en"] = "Bloodtalon Matriarch", ["tasks"] = { ["Bloodtalon Martriarch Eggs"] = "Яйця Кров'яного Кігтя-Жертволомця" } },
    [97225] = { [1] = "Забуті ідоли Лоа", [2] = "Коли ми втікали з островів, які зараз населяють Залазан та йому подібні, ми залишили після себе багато дорогоцінних ідолів, які допомагають нам спілкуватися з духами, яким ми поклоняємося: нашими лоа. Вони мають величезне значення для нашого племені.\n\nПослідовники Залазана не виявляють жодної шани до наших лоа та розкидали цих ідолів по найбільшому з островів.\n\nЦей вчинок не залишиться непоміченим, якщо ми не зможемо зібрати цих ідолів, а образити лоа — це серйозна справа.\n\nІди, знайди якомога більше ідолів лоа та поверни їх мені.", [3] = "Зберіть 8 Забутих Ідолів Лоа з Островів Відлуння. Принесіть їх Майстру Гадріну в село Сен'джін.", ["en"] = "Forgotten Loa Idols", ["tasks"] = { ["Forgotten Loa Idol"] = "Забутий ідол Лоа" } },
    [97234] = { [1] = "Читальний зал", [2] = "Ви тут, щоб обговорити глибші значення наших легендарних творів? Ні?\n\nДобре, після того, як ви закінчите оглядати, чи можете ви віднести це до бібліотеки для мене? Ми обмінюємо деякі з наших менш популярних творів на більш сучасні. У мене є список томів, які, я впевнений, бібліотекар зможе нам дістати в рамках нашої існуючої домовленості.\n\nБезкоштовні клубні напої від нас, якщо ви нам допоможете.", [3] = "Принесіть загорнуті матеріали для читання до бібліотеки Штормовія.", ["en"] = "Reading Room", ["tasks"] = { ["Wrapped Reading Material"] = "Матеріали для читання в упаковці", ["Wrapped Reading Material (Provided)"] = "Матеріали для читання в упаковці (видано)" } },
    [97236] = { [1] = "Ікло Гітісса", [2] = "Свіжий екземпляр звіра такого розміру – справжня знахідка. Можливо, хтось в Альдрассілі, знайомий з вивченням павуків, зацікавиться іклом.", [3] = "Доставте Ікло Гітісса комусь, хто цікавиться вивченням павуків в Альдрассілі.", ["en"] = "Fang of Githyiss" },
    [97237] = { [1] = "Зібрано з полиці", [2] = "Я перевірив наш інвентар, і всі перелічені містером Льюеллсом вибрані матеріали зараз доступні.\n\nОднак вам потрібно буде самостійно придбати їх з полиць. Частиною наших обов'язків бібліотекаря є пильність, і для цього я відновлю ведення бухгалтерського обліку.\n\nПовернення матеріалів Рою від його імені не означає, що ви несете відповідальність за їх повернення; оскільки за його запискою ви виконуєте обов'язки офіційного кур'єра книжкового клубу. Їхня установа несе цей тягар.\n\nДоброго дня, {ім'я}.", [3] = "Знайдіть кожен з матеріалів для читання десь у бібліотеці, а потім поверніться до Роя Льюеллса в парку Штормовія.", ["en"] = "Shelf Picked", ["tasks"] = { ["Cycles of Morality"] = "Цикли моралі", ["Field Accounts of Horde Razings"] = "Польові звіти про розгром Орди", ["The Forsaken Ally"] = "Покинутий союзник", ["Trollbane Conquests"] = "Завоювання Тролльбейна" } },
    [97253] = { [1] = "Деталі та частини", [2] = "Гей, маєш секунду?\n\nОтже, очевидно, ніхто з тих, кого я відправляв для вирішення нещодавньої проблеми з піратами, не повернувся живим. Після п'яти чи шести спроб я подумав: \"А що, якби я замість цього відправив машину?\" Виявляється, що ятагани в крайньому випадку можуть слугувати викрутками, і перш ніж я встиг перенаправити її додому, вона вже була розбита на шматки та розкидана по їхньому табору!\n\nМені потрібно повернути ці частини, і оскільки це швидка місія з повернення, я б посперечався, що твої шанси на виживання НАБАГАТО вищі, ніж у інших. Що скажеш?", [3] = "Зберіть 5 жмень складних деталей у верхньому піратському таборі на південь від Ретчета, а потім поверніться до Ренікса Нещасного в Ретчет.", ["en"] = "Parts and Pieces", ["tasks"] = { ["Handful of Complicated Parts"] = "Кілька складних деталей" } },
    [97279] = { [1] = "Норовлива зброя", [2] = "З напливом нових рекрутів, таких як ви, важко забезпечити нас зброєю. Нашому зброяру, Кзану, не вистачає навчальної зброї, і я хотів би побачити, якими навичками ви володієте, щоб отримати уявлення про те, з чим мені доведеться працювати. На щастя для вас, у мене є рішення для обох проблем.\n\nПоки ви гоните зуби на кабанів, врятуйте шість покинутих навчальних видів зброї. Наші невдалі рекрути залишили їх лежати на землі. Як тільки ви це зробите, поверніть їх нашому зброяру Кзану позаду мене в Лігві.", [3] = "Зберіть 6 покинутих навчальних зброї, потім поверніться до Кзана Торнслаша в Лігво.", ["en"] = "Wayward Weapons", ["tasks"] = { ["Abandoned Training Weapon"] = "Покинута навчальна зброя", ["Abandoned Training Weapon (Provided)"] = "Покинута навчальна зброя (видано)", ["Abandoned Training Weapon slain"] = "Покинута навчальна зброя: убито" } },
    [97281] = { [1] = "Шторм, що назріває", [2] = "<Перед вами дивна куля з матовою поверхнею. Якщо її підняти, здається, що всередині вібрує слабкий електричний струм. При ближчому розгляді виглядає так, ніби всередині клубиться темний туман, і час від часу можна побачити невелику електричну іскру.\n\nЗрозуміло, що гарпія використовувала її для якоїсь мети. Можливо, Резлак зацікавиться цим об'єктом?>", [3] = "Принесіть Тупу Бурхливу Сферу Резлаку біля Ущелини Драйгалч.", ["en"] = "A Simmering Storm" },
    [97282] = { [1] = "Бурхливий потенціал", [2] = "«Резлак, коли з'явиться можливість, будь готовий її використати». Це ще одна перлина, якій мене навчив Газлоу, і саме це я маю намір зробити.\n\nЦя сфера не виглядає пошкодженою, вона просто виглядає так, ніби в ній вичерпався заряд, але в мене є ідея зарядити її до повної сили!\n\nВ ущелині на захід звідси є купа громових ящірок. У них є органи, що утримують сильний електричний заряд, який ідеально підійде для цього.\n\nІди, збери трохи і принеси їх мені!", [3] = "Принесіть 5 заряджених органів громової ящірки Резлаку біля ущелини Драйгалч.", ["en"] = "Stormy Potential", ["tasks"] = { ["Charged Thunder Lizard Organ"] = "Орган зарядженої грімової ящірки" } },
    [97286] = { [1] = "Доступ до досліджень", ["en"] = "Research Access" },
    [973] = { [1] = "Вежа Алталакса", [2] = "Ілкруд Маґтрулл. Так, я знаю про нього. Це могутній орк-чорнокнижник, який оселився біля вівтаря Вогняного Шраму, місці великого зла на південному заході Ясенедолу.\n\nДосі він нам особливо не заважав, тому я й не чіпав його, але, здається, час настав.", [3] = "Принесіть Дельґренові Очистителю на заставу Маєстри фоліант Ілкруда Маґтрулла.", [4] = "Ти наче трохи {стать:схвильований:схвильована}, {ім'я}. Все гаразд?", [5] = "Сьогодні ти {стать:зробив:зробила} велику справу, {ім'я}. Ти можеш пишатися собою за те, що {стать:зумів:зуміла} протистояти такому могутньому чорнокнижнику.\n\nА тепер погляньмо, що ми зможемо знайти в записах Ілкруда.", ["en"] = "The Tower of Althalaxx", ["tasks"] = { ["Ilkrud Magthrull's Tome"] = "фоліант Ілкруда Маґтрулла", ["Ilkrud Magthrull's Tome (Provided)"] = "фоліант Ілкруда Маґтрулла (видано)" } },
    [97328] = { [1] = "Усе, що має цінність", [2] = "<Перебираючи уламки дирижабля, який зазнав жахливої аварії просто над цим місцем, ви знаходите сліди великої партії припасів, давно розграбованої до останньої цінної речі. Навіть транспортні наліпки розірвані на шматки. Лише на одній ледь читаються слова «Грабіжна Бухта».\n\nНезліченні двопалі сліди й кілька ділянок поритої землі ведуть до руїн на північному заході.>", ["en"] = "Anything of Value", ["tasks"] = { ["Stolen Shipment"] = "Вкрадений вантаж" } },
    [974] = { [1] = "У пошуках джерела", [2] = "Тутешні гарячі джерела — загадка для мене. Звідки йде це тепло?\n\nВраховуючи те, наскільки близько вони розташовані до Вогнеперої скелі, мені стало цікаво, чи може вулкан бути причетним до цього. Я створив термометр, щоб виміряти температури на вулкані, і хотів би знайти його найгарячішу частину. Він показує виміри по шкалі Кракленгейта!\n\nОсь, візьми його та виміряй температури на кожній гарячій точці!", [3] = "Кракл з кратера Ун'Ґоро хоче, щоб ви знайшли найгарячішу ділянку Вогнеперої скелі.\n\nКоли ви знайдете гарячу точку, скористайтесь термометром, щоб перевірити температуру. Продовжуйте шукати, поки не знайдете найгарячішу ділянку.", [4] = "Я б і сам туди пішов, але... Я трохи боюся тамтешніх вогняних елементалів!", [5] = "Так, я точно бачу зв'язок між температурою вулкана і гарячими джерелами. Мені доведеться перевірити точність моїх формул, але, здається, що відстань і швидкість передачі тепла... Хм...", ["en"] = "Finding the Source", ["tasks"] = { ["Find the hottest area of Fire Plume Ridge"] = "Знайдіть найгарячіший район Фаєр-Плюм-Рідж", ["Krakle's Thermometer"] = "термометр Кракла", ["Krakle's Thermometer (Provided)"] = "термометр Кракла (видано)" } },
    [975] = { [1] = "Скарб Мав'арі", [2] = "Тепер, перш ніж я дам тобі цей талісман, я поясню, як ним користуваться.\n\nЯкшо ти будеш носить його з собою, то побачиш, шо з істот, з якими ти б'єшся, падатимуть певні предмети. Якщо не матимеш його з собою, то не найдеш їх. Понятно?\n\nТи узнаєш ці особливі предмети за назвою — вони називаються е'ко. Якщо ти найдеш якийсь з цих предметів, просто принеси їх старій Мав'арі, і вона тобі поможе.\n\nПожди тут, поки я полагоджу твій талісман.", [3] = "Поговоріть зі знахаркою Мав'арі ще раз, щоб отримати талісман удачі.", [5] = "Ось, {ім'я}. Пам'ятай, ти {стать:повинен:повинна} носить його з собою. Чого б тобі не повернуться за стіни і не подивиться, шо ти там найдеш?", ["en"] = "Cache of Mau'ari" },
    [97558] = { [1] = "Шкури для покинутих", [2] = "Одна частина життя нежить, про яку ніхто не згадує, це те, що відбувається, коли ми отримуємо поранення. Як шкіра нежиті загоюється сама?\n\nНу, це не так.\n\nНаше життя прокляте, {ім'я}. Ми повинні брати у живих, щоб продовжувати своє існування.\n\nКоли ми отримуємо поранення, ми повинні замінити свою шкіру, що зазвичай означає використання тваринних шкур. Оскільки різна товщина шкіри краще підходить для різних частин нашого тіла, різноманітність є ключовою!\n\nПринесіть мені перетинки крил сутінкового кажана, шкури темного гончака та шкіру мурлока Мерзкого Фіна.", [3] = "Принесіть Шелін Робарт 8 мембран крил Сутінкового Кажана, 6 шкур Темного Гончака та 3 шкіри Мертвого Плавника Мурлока.", ["en"] = "Hides for the Forsaken", ["tasks"] = { ["Darkhound Hide"] = "Шкура Темного Пса", ["Duskbat Wing Membrane"] = "Мембрана крила Сутінкового Кажана", ["Vile Fin Murloc Skin"] = "Скін Мерзенного Плавця Мурлока" } },
    [976] = { [1] = "Поставки в Аубердін", [2] = "Дельґрен попросив мене передати повідомлення та припаси стражниці Зоребриз в Аубердін, але мені дуже не хочеться вирушати туди на самоті. В лісі повно небезпечних ворогів, і я не хочу, аби важлива інформація та припаси потрапили не в ті руки.\n\nЯкщо ти погодишся супроводжувати мене на цьому шляху, я можу вирушати просто зараз. З твоїм захистом ми успішно доставимо припаси в Аубердін.", [3] = "Поговоріть з Дельґреном Очистителем на заставі Маєстри після того, як проведете Фіро через Ясенедільський ліс до безпечного місця.", [4] = "Стражам дуже потрібні припаси аби укріпити свої позиції в Темнобережжі.", [5] = "Ти добре {стать:попрацював:попрацювала} сьогодні, {клас:к}. Товари, які ми надіслали в Аубердін, допоможуть вистояти проти небезпеки, що причаїлася в лісі.\n\nВізьми це, разом із моєю сердечною подякою.", ["en"] = "Supplies to Auberdine", ["tasks"] = { ["Protect Feero Ironhand"] = "Захистіть Фіеро Залізну Руку" } },
    [977] = { [1] = "Механічні єті!", [2] = "Тепер, коли я маю все необхідне для покриття механічних рухомих частин, мені потрібна лише одна річ. Точніше, дві. Два роги!\n\nЛьодореп'яхові патріархи та матріархи мають найбільші роги, тож, звісно, саме вони мені й потрібні. Цей вид єті мешкає в печері на південному сході. Їх там багато, знайти їх буде не важко.\n\nПам'ятай, мені потрібні тільки найкрасивіші — ніяких побитих або зламаних рогів, будь ласка!", [3] = "Принесіть 2 бездоганних роги єті Умі Румпельшніцель в Завшегляд.", [4] = "Я майже закінчила з хутром, {ім'я}. Будь ласка, поквапся з рогами!", [5] = "Не можу дочекатися, щоб показати це друзям! Зачекай хвилинку, я прикріплю це...\n\nІдеально!", ["en"] = "Are We There, Yeti?", ["tasks"] = { ["Pristine Yeti Horn"] = "бездоганний ріг єті", ["Pristine Yeti Horn (Provided)"] = "бездоганний ріг єті (видано)" } },
    [978] = { [1] = "Осяяні місяцем дикі совухи", [2] = "Схоже, що пір'я диких совухів з Внутрішніх земель містить сліди магії. Ці сили... не схоже, що ці створіння здатні їх контролювати, скоріше, ця магія просто є частиною їхньої сутності.\n\nПід час моїх досліджень я дізнався, що велика популяція диких совухів населяє засніжені землі Зимоключа. Чи можуть ці істоти володіти тими ж силами? Прошу, {ім'я}, допоможи мені дізнатись це. Йди до Зимоключа, збери пір'я совухів та повертайся до мене.", [3] = "Зберіть 15 осяяних місяцем пір'їн у Зимоключі та поверніться з ними до Ереласа Бурштинонебого в селище Рут'Теран.", [4] = "Звідки взялись ці сили? Думаю, ми на правильному шляху до істини, {ім'я}.", [5] = "Тепер я зможу порівняти пір'я... Що ж, поглянемо...", ["en"] = "Moontouched Wildkin", ["tasks"] = { ["Moontouched Feather"] = "осяяне місяцем перо", ["Moontouched Feather (Provided)"] = "осяяне місяцем перо (видано)" } },
    [979] = { [1] = "Пошуки Раншалли", [2] = "Так, так, це пір'я, здається, містить ті самі магічні сили, які я помітив раніше... Хоч я й не зовсім впевнений, що саме ми знайшли, я прошу тебе продовжувати пошуки відповідей, {ім'я}.\n\nМоя колега нещодавно вирушила до Зимоключа вивчати тамтешніх диких совухів у їхньому природному середовищі. Чому б тобі не наздогнати її та не запитати, що їй вдалося дізнатись?", [3] = "Знайдіть Раншаллу на сході Зимоключа.", [5] = "Привіт! Тебе прислав Ерелас? Чудово, я якраз збиралась відправитись до печер і була б не проти компанії.", ["en"] = "Find Ranshalla" },
    [97963] = { [1] = "Кемпінг 101: Алхімія", [2] = "Отже, ти вирішив варити зілля та напої як Алхімік. Я впевнений, що це стане тобі в пригоді в подорожах.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити Колодязь Мани для твого табору. Збудуй один з них, і всі цілителі та чарівники збігатимуться, щоб насолодитися освіжаючим смаком.", [3] = "Поговоріть з Ньяссою ШвидкоїЗтяжки в селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Alchemy", ["tasks"] = { ["Raise your alchemy skill to 20"] = "Підвищте свою навичку алхімії до 20" } },
    [97964] = { [1] = "Кемпінг 101: Ковальська справа", [2] = "Отже, ви стали ковалем. Це чудовий вибір, якщо ви хочете бути впевнені, що ваші клинки ніколи не затупляться.\n\nГадаю, я знаю когось, хто може допомогти вам у цьому, навчивши вас, як виготовити точильне колесо. Принесіть одне з них у свій табір, і всі воїни та розбійники в окрузі вишикуються в чергу, щоб відточити свою зброю.", [3] = "Поговоріть з Тричі перекованим Аеді в селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Blacksmithing", ["tasks"] = { ["Raise your blacksmithing skill to 20"] = "Підвищіть навичку ковальства до 20" } },
    [97965] = { [1] = "Кемпінг 101: Перша допомога", [2] = "Отже, ви почали навчатися наданню першої допомоги? Це почесне... і прагматичне прагнення як {клас}.\n\nГадаю, я знаю когось, хто може навчити вас, як створити аптечку першої допомоги для вашого табору. Травми — це реальність у світі пригод, і пропонування так необхідного лікування у вашому таборі може навіть врятувати життя.", [3] = "Поговоріть з Налією Таттерменд у селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: First Aid", ["tasks"] = { ["Raise your first aid skill to 20"] = "Підвищіть навичку першої допомоги до 20" } },
    [97967] = { [1] = "Кемпінг 101: Риболовля", [2] = "Можливо, ви так не думаєте, але ваші навички рибалки можуть стати в нагоді в таборі.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити акваріум для вашого табору. Ви можете використовувати цей інструмент, щоб подарувати трохи радості собі та своїм товаришам-шукачам пригод. Щасливий шукач пригод – це сильний шукач пригод, і я впевнений, що ваші бойові здібності це відображатимуть.", [3] = "Поговоріть з Фенн Фейрвезер у селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Fishing", ["tasks"] = { ["Raise your fishing skill to 20"] = "Підвищте свій рівень риболовлі до 20" } },
    [97968] = { [1] = "Кемпінг 101: Трав'ярство", [2] = "Мені здається, ти набув певних навичок у травництві. Збирання квітів — це не просто для розваг, знаєш. Це може бути корисним... і прибутковим.\n\nГадаю, я знаю когось, хто може навчити тебе, як створити ароматичну свічку для твого табору. Піднесений дух — ключовий компонент для підтримки цілителів та заклинателів у бою, а ароматична свічка може дати підкріплення, яке маги точно оцінять.", [3] = "Поговоріть із Сіріель Найтрейн у Валанаарі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Herbalism", ["tasks"] = { ["Raise your herbalism skill to 20"] = "Підвищте свій рівень навичок травництва до 20" } },
    [97969] = { [1] = "Кемпінг 101: Шкіряна справа", [2] = "Ти став шкіряником. Молодець, {клас}. Гадаю, я знаю когось, хто може навчити тебе, як зробити собі намет, у якому буде прохолодно в спекотні дні та сухо в дощові.\n\nЗ гарним наметом над головою ти гарантовано отримаєш весь необхідний відпочинок, щоб залишатися бадьорим під час подорожей.", [3] = "Поговоріть з Індарі Сансім у селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Leatherworking", ["tasks"] = { ["Raise your leatherworking skill to 20"] = "Підвищте свою майстерність обробки шкіри до 20" } },
    [97970] = { [1] = "Основи таборування: гірництво", [2] = "Гірничодобувна справа — не найгламурніше, але це гарна чесна робота та чудова професія, яку варто досліджувати.\n\nГадаю, я знаю когось, хто може навчити тебе виготовляти магніт для твого табору. Збудуй один з них, і кожен, хто хоче розмахувати мечем, захоче зібратися навколо твого вогнища та насолодитися його додатковою «силою», щоб підвищити свою бойову майстерність.", [3] = "Поговоріть з Мессаною Крествінд у селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Mining", ["tasks"] = { ["Raise your mining skill to 20"] = "Підвищте свій рівень майнінгу до 20" } },
    [97971] = { [1] = "Кемпінг 101: Зняття шкури", [2] = "Вміння вміло збирати шкури та шкури полеглих звірів – одна з найцінніших навичок, якими може володіти шукач пригод.\n\nГадаю, я знаю когось, хто може навчити вас, як зробити похідне крісло для вашого табору. Іноді важливо просто розслабитися, і ви можете використати деякі з цих зібраних шкур, щоб зробити зручне крісло. Трохи відпочинку може допомогти вам бути у найкращій формі та вдарити там, де це потрібно, наступного разу, коли ви опинитеся в запиленій хаосі.", [3] = "Поговоріть з Мендаласом Таттермендом у селі Шен'дар, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Skinning", ["tasks"] = { ["Raise your skinning skill to 20"] = "Підвищте свою навичку зняття шкури до 20" } },
    [97977] = { [1] = "Поклик природи", [2] = "Фурболги Гнарлпайна не так легко б звернулися проти своїх давніх союзників. Ми повинні дізнатися більше про їхнє скрутне становище.\n\nОбшукайте їхні покинуті будинки в пошуках тотемів. Якщо хтось пережив хаос їхнього відходу, їхні гравюри можуть розповісти нам більше про те, що тут сталося.\n\nВи знайдете їхні табори вздовж західного краю ущелини, хоча грелли та грелкіни, можливо, розсіяли їх далі.", [3] = "Зберіть 4 тотеми гнарлпіни та принесіть їх Таріндреллі.", ["en"] = "Nature's Call", ["tasks"] = { ["Gnarlpine Totem"] = "Тотем Гнарлсосни" } },
    [980] = { [1] = "Нові джерела", [2] = "Я також чув про інші гарячі джерела в місці під назвою Зимоключ, що далеко на півночі звідси. Дивно, що поруч з ними немає жодних вулканів. Так, це цікаво, я знаю.\n\nЯкщо ти хочеш дізнатися більше, то тобі варто вирушити в Зимоключ і поговорити з моєю знайомою. Її звуть Донова Снігосхов, і вона має бути біля гарячих джерел.\n\nЩе раз дякую тобі за допомогу з термометром! Здибаємось!", [3] = "Прямуйте в Зимоключ і поговоріть з Доновою Снігосхов.", [5] = "Привіт, {ім'я}. Так, те, що тобі сказав Кракл правда...", ["en"] = "The New Springs" },
    [98013] = { [1] = "Сили набухання", [2] = "Приготуйся до перебування в руїнах, юний... тобі не дадуть вільного проходу туди.\n\nДесятки проклятих Високонароджених, тепер відомих як наги, блукають колись великим містом. Мандруйте на північний схід і викиньте їх з цієї землі.\n\nТим, ким вони колись були... більше немає. Якщо вони допоможуть Сутінковому Молоту, вони можуть принести лише ще більше болю лісам, які колись давали їм притулок.\n\nВійна — це те, чого вони прагнуть, {клас}. Війна... це те, що ми принесемо.", [3] = "Знищити 12 мірмідонів Бурелуски, 8 чаклунок Бурелуски та 6 воїнів Бурелуски для Арбала в Гаю Стародавніх.", ["en"] = "Swelling Forces", ["tasks"] = { ["Stormscale Myrmidon slain"] = "штормолуский мірмідон: убито", ["Stormscale Sorceress slain"] = "штормолуска чаклунка: убито", ["Stormscale Warrior slain"] = "штормолуский воїн: убито" } },
    [98042] = { [1] = "Це все веселощі та ігри, поки...", [2] = "<Коли ти відриваєш єдину сторінку від Сутінкового Тома, твій розум непрохано заливає лихий голос.>\n\nВони зазнали невдачі.\n\nТебе забудуть.\n\nВони втратять око, яке здобули.", [3] = "Отримайте Незрівнянне Око у Сутінкового Учня або Головоріза в Глефі Майстра на Темному Березі та знайдіть когось в Обердіні, хто готовий його взяти.", ["en"] = "It's All Fun and Games Until...", ["tasks"] = { ["Peerless Eye"] = "Незрівнянне Око" } },
    [98046] = { [1] = "Вінець Землі", [2] = "<Погляд Архідруїда Фандрала Оленячого Шолом'я звужується.>\n\nТи все ще тут?\n\nЗабери фіалу та зникни з моїх очей, {клас}. Зрозуміло, що мої відповіді не лежать у воді, як і раніше.\n\nМожливо, одна з жриць у Храмі Місяця на півдні позбудеться її.\n\n<Фандрал відводить погляд, більше не розмовляючи з тобою.>\n\nЯкщо це хоче спрацювати, я маю шукати деінде...", [3] = "Принесіть Висушену посудину Ларії в Храмі Місяця в Дарнасі.", ["en"] = "Crown of the Earth", ["tasks"] = { ["Drained Vessel"] = "Осушене судно", ["Drained Vessel (Provided)"] = "Осушене судно (видано)" } },
    [98065] = { [1] = "Вінець Землі", [2] = "Ти мусиш негайно віднести це Тіранді! Я перекладу це для тебе в більш церемоніальну ємність.\n\nНе бійся. Верховна Жриця Елуни тверда, але добра. Вона захищає всіх, хто входить до Дарнасу, і несе світло нашої богині всім.\n\nВона буде рада отримати цю священну воду. Ти знайдеш її прямо над нами.", [3] = "Принесіть Залишки Місячної Колодязі Тіранді Шепіт Вітер у Храм Місяця в Дарнасі.", ["en"] = "Crown of the Earth", ["tasks"] = { ["Moonwell Remnants"] = "Залишки Місячної Колодязі", ["Moonwell Remnants (Provided)"] = "Залишки Місячної Колодязі (видано)" } },
    [98072] = { [1] = "Крокси неба", [2] = "Ти справді завзятий! У мене є ще одна прохання, якщо ти готовий до чогось трохи небезпечнішого.\n\nТоргівля кроколісками — це стабільний заробіток, але це дрібна риба порівняно з тим, що може принести луска цуценят. Люди заплатять чималі гроші за мішок таких.\n\nЯ їх називаю кроколісками неба! Мій учень ніяк не зміг би їх дістати, але, здається, це саме те, що тобі потрібно!\n\nТи знайдеш цуценят далеко на сході, вздовж Зеленого Поясу. Але будь обережний, у тих пагорбах є гидкі орки!", [3] = "Зберіть 10 Незайманих Багряних Лусок та принесіть їх Джеймсу Халлорану в Гавань Менетіл.", ["en"] = "Crocs of the Sky", ["tasks"] = { ["Pristine Crimson Scale"] = "Незаймана багряна луска" } },
    [981] = { [1] = "Вежа Алталакса", [2] = "За всю виконану роботу ти заслуговуєш на гідну винагороду. Повертайся до Дельґрена і скажи йому, що Атрік Нарассін поліг від твоєї руки, а культ Темного Пасма розтрощений і знищений.", [3] = "Поговоріть з Дельґреном Очистителем на заставі Маєстри.", [5] = "Я знав, що ти впораєшся із завданням, {ім'я}.\n\nЯ відчуваю, що на тебе чекають великі справи, і що ти виправиш багато зла, заподіяного нашим землям. Прийми моє благословення, {ім'я}, а також цей дар.", ["en"] = "The Tower of Althalaxx" },
    [982] = { [1] = "Глибокий океан, безмежне море", [2] = "Біля узбережжя Темнобережжя на північ від нас лежать два розбиті кораблі - \"Срібляста Зоря\" і \"Туманний Серпанок\". Колись давно вони зазнали нападу мурлоків, коли пливли по безмежному морю до Аубердіну. Тепер вони лежать на дні океану, ставши здобиччю мурлоків.\n\nОбидва капітани загинули тієї ночі, а їхні журнали та інші цінні речі досі лежать у скриньках. Я хотів би, щоб ти {стать:повернув:повернула} їх нам. Це багато значило б для членів команди, які живуть у цих краях.", [3] = "Добудьте скриньку \"Сріблястої Зорі\" та скриньку \"Туманного Серпанку\" для Ґорбольда Сталерука. Обидва предмети можна знайти на борту затонулих кораблів на північ від Аубердіна.", [4] = "Капітани цих кораблів були славними нічними ельфами, і вони заслуговували на кращу долю. Можливо, догляд за їхніми особистими речами буде найкращим способом заспокоїти їхні нещасні душі.", [5] = "Ти {стать:зробив:зробиkf} нам в Аубердіні велику послугу, {стать:юначе:юначко}. Ми подбаємо про те, щоб за їхніми речами доглядали належним чином.\n\nЩо ж до тебе, прошу, візьми це. Це найменше, чим я можу віддячити за твою сміливість.", ["en"] = "Deep Ocean, Vast Sea", ["tasks"] = { ["Mist Veil's Lockbox"] = "скринька \"Туманного Серпанку\"", ["Mist Veil's Lockbox (Provided)"] = "скринька \"Туманного Серпанку\" (видано)", ["Silver Dawning's Lockbox"] = "скринька \"Сріблястої Зорі\"", ["Silver Dawning's Lockbox (Provided)"] = "скринька \"Сріблястої Зорі\" (видано)" } },
    [98208] = { [1] = "Цвітіння небес", [2] = "Я прибув до гавані Менетіл з Обердіна, з великого дерева Тельдрассіл, щоб забрати квітку, що має велике значення для мого народу.\n\nКорабель мого народу «Летюча Скопа» зазнав аварії тут багато місяців тому, приєднавшись до Третього флоту Кул-Тірану. Серед його вантажу була квітка, відома як Норд'ел — «Цвіт Небес» вашою мовою — що розквітла під повним місяцем на вершині гори Хіджал, нашого колишнього дому.\n\nБудь ласка, допоможіть мені забрати її! Уламки знаходяться трохи південніше від міста, але там мешкають люті мурлоки-рейдери!", [3] = "Поверніть Норд'ел Сілессі Сутінкошепіт у гавані Менетілів.", [4] = "Ти вже був на місці аварії? Вельми сумне видовище.", [5] = "Він уцілів! О, хвала Елуні!\r\n\r\nТисяча подяк, <name>. Якщо ти не проти, я маю попросити ще про одну послугу...", ["en"] = "Bloom of the Heavens", ["tasks"] = { ["Nord'el"] = "Норд'ел" } },
    [98209] = { [1] = "Цвітіння небес", [2] = "Чи не віднесеш Норд'ел старійшині Тандрісу Вітроткачу в Аубердін?\n\nКорабель звідси швидко доправить тебе туди.\n\nПробач за це прохання, щиро прошу. Я досі виснажена подорожжю сюди та втечею від тих клятих мурлоків, коли вперше спробувала дістати священну квітку!", [3] = "Віднесіть Норд'ел Тандрісу Вітроткачу в Аубердін у Темнобережжі.\n\nВи пригадуєте слова Сілесси: корабель із гавані Менетілів доправить вас туди.", [4] = "Вітаю тебе в Аубердіні, <class>. Чим ми можемо допомогти тобі в мандрах?", [5] = "Норд'ел уцілів? Не може бути... після стількох років!\r\n\r\nНаша богиня воістину дивовижна!\r\n\r\nДякую, що доставив його сюди. Це рідкісний промінь світла в темні часи, які нам випали останнім часом, і символ не лише милості Елуни, а й незламної волі нашого народу вистояти без безсмертя.\r\n\r\nЯ подбаю, щоб його безпечно доправили до Дарнаса, де його зможуть належно вирощувати.", ["en"] = "Bloom of the Heavens", ["tasks"] = { ["Nord'el (Provided)"] = "Норд'ел (видано)" } },
    [98283] = { [1] = "Кривава різанина", [2] = "Природний лад цих земель руйнується. Колись гостропащі раптори стримували надмірне розростання рослин. Тепер вони живуть у страху перед своїм ватажком, названим лише за криваві сліди, які він залишає.\n\nБоюся, хвороба, якої ми ще не позбулися остаточно, звела звіра з розуму.\n\nЙого привабить заражене м'ясо хворих ведмедів під хребтом Рапторів на північному сході. Залиш їхні нутрощі в його печерному лігві.\n\nРізанина прийде. Принеси мені його голову.", [3] = "Принесіть голову Різанини Ретілю Вартовому Природи в Зеленому Поясі.", ["en"] = "Carnage", ["tasks"] = { ["Carnage's Head"] = "Голова Різанини", ["Malignant Rotclaw Flesh"] = "Злоякісна плоть Гнилокігтя" } },
    [98285] = { [1] = "Кемпінг 101: Інженерія", [2] = "Інженер завжди винахідливий, і якщо ви самі в дикій природі, завжди добре мати можливість застосувати свою майстерність. Жоден хороший табір не обходиться без кількох корисних конструкцій!\n\nТак, повертайтеся до мене, коли отримаєте трохи досвіду як інженер, і я зможу показати вам, як створити щось особливе!", [3] = "Поговоріть із Дивним Відлюдником у Тіньовому Лісі, щоб навчитися створювати предмет для кемпінгу для вашої професії, як тільки ви продемонструєте майстерність у своїй навичці.", ["en"] = "Camping 101: Engineering", ["tasks"] = { ["Raise your engineering skill to 20"] = "Підвищте свій інженерний рівень до 20" } },
    [98298] = { [1] = "Дурість Аруґала", [2] = "Ах, все стало так бентежно очевидно! Аругал майже не мав жодної магії, не кажучи вже про те, щоб створити воргена. «Прокляття Аругала». Тьху! Ледве достатньо потужне, щоб протриматися кілька секунд.\n\nЦі кайдани доводять, що він може зв'язувати звірів, а не створювати їх. Воргени явно поширювали своє прокляття іншим способом. Я б знав як.\n\nІдіть до Стіни Сірогривої на південь. Здається, воргени поширюються на людей поблизу. Розірвіть звірів на частини та принесіть мені все, що знайдете. Це вимагає більш прямого підходу.", [3] = "Принесіть 6 шматочків Воргена Далару Світанковому Ткачу в Гробниці.", ["en"] = "Arugal's Folly", ["tasks"] = { ["Worgen Bits"] = "Біти Воргена" } },
    [98299] = { [1] = "Зупинити поширення", [2] = "Якщо ми щось і знаємо напевно, то це те, що Аругал відповідальний за воргенів у Срібній Пайні — чи то його власні махінації, чи щось інше. Ми не знаємо, як воно поширюється.\n\nПоки я досліджую спосіб зупинити прокляття, нашим першим пріоритетом є його стримування. Здається, ця хвороба не може заразити відреклих, але велика група людей зібралася біля Стіни Сірогривої.\n\nІдіть до стіни та знищіть цих біженців, перш ніж вони матимуть шанс стати слугами Аругала. І постарайтеся не бути укушеними, {раса}.", [3] = "Убийте 5 хворих біженців та 5 знесилених біженців для Далар Світанку в Гробниці.", ["en"] = "Stop the Spread", ["tasks"] = { ["Haggard Refugee slain"] = "змучений біженець: убито", ["Sickly Refugee slain"] = "кволий біженець: убито" } },
    [983] = { [1] = "Дзижчатор 827", [2] = "Гей! Допоможи мені з моїм останнім винаходом, дзижчатором. З його допомогою можна спілкуватись на відстані!\n\nМожливо, ти вже {стать:зустрічав:зустрічала} їх — це такі коробки з важелями. Єдина проблема в тому, що вони потребують постійного обслуговування.\n\nКожен з них страждає від різних проблем, але я прийняв дуже розумне рішення. Я розмістив їх біля істот, які мають необхідні деталі для ремонту. Зараз Дзижчатор 827 вийшов з ладу. Він розташований на південь від Аубердіна, зовсім неподалік. Щоб його полагодити, потрібно 6 ніг повзунів. Я заплачу...", [3] = "Зберіть 6 ніг повзунів та помістіть їх у Дзижчатор 827.", [4] = "Дзижчатор 827 не видає жодного звуку. Єдиний мерехтливий індикатор вказує на те, що в приймач потрібно покласти 6 ніг повзунів.", [5] = "Щойно ноги повзунів опинилися в машині, ви чуєте, як шестерні починають їх перемелювати. Судячи зі стукоту, що доноситься з Дзижчатора, ноги повзунів знайшли своє місце. Незабаром машина починає дзижчати, і ви чуєте тоненький голосок, який ледь доноситься зсередини.\n\n\"Агов? Е-е... Привіт! Ти {стать:полагодив:полагодила} її! До речі, це Бацбах! Дуже дякую... Слухай, а ти не хочеш полагодити ще один?\"", ["en"] = "Buzzbox 827", ["tasks"] = { ["Crawler Leg"] = "нога повзуна", ["Crawler Leg (Provided)"] = "нога повзуна (видано)" } },
    [98313] = { [1] = "Для подальшого вивчення", [2] = "Що б усе це не означало, {ім'я}, справа справді грандіозна.\n\nЯ гарно запакую все для тебе. Віднеси це історику Карнику в Залу дослідників у Залізогарті. Зазвичай його можна знайти в глибині бібліотеки, зануреним у якийсь фоліант.\n\nЩоб розгадати цю загадку, знадобиться ціле військо дослідників. Але якщо судити з того, що ми вже бачили, воно того варте!", [3] = "Віднесіть пакунок реліквій Вельґара історику Карнику в Залізогарт.", ["en"] = "For Further Study", ["tasks"] = { ["Whelgar Relic Package (Provided)"] = "Пакунок реліквій Велґара (видано)" } },
    [98326] = { [1] = "Морозне виття", [2] = "Чи знаєте ви, як важко ловити рибу на замерзлому озері? Мій бідний чоловік, Пакстон, вже кілька днів просидів посеред нього, і в нас ледве залишилося жодного мішка, щоб показати його.\n\nНу, у нас ДІЙСНО був мішок, щоб показати його. Поки тричі проклятий вендіго не напав на мене і не втік з нашим уловом. Нам знадобляться тижні, щоб виловити його назад! Якщо цей крикливий Морозний Виття не налякав їх усіх, у будь-якому разі.\n\nЗробіть нам послугу і поверніть його, гаразд? Слинявий звір ховається десь глибоко в Сивому Лігві на південному сході.", [3] = "Убийте Морозного Виття та зберіть Мішок Риби для Гретти Гантер у селі Брюналл.", ["en"] = "Frosthowl", ["tasks"] = { ["Sack of Fish"] = "Мішок риби", ["Sack of Fish (Provided)"] = "Мішок риби (видано)", ["Sack of Fish slain"] = "Мішок риби: убито" } },
    [98341] = { [1] = "Великий Вітряний Котячий Дух", [2] = "Нещодавно тут з'явився дух вашої батьківщини і попросив мене провести вас туди. Цей дух кішки, що переноситься вітром, прийшов навчати вас і наставляти, щоб ви могли прийняти котячу форму духа Зефраса.\n\nУсі друїди зрештою прагнуть цієї мудрості, хоча, схоже, ваша батьківщина має дещо іншу форму, ніж наша традиційна. Якщо ви бажаєте прийняти котячу форму цього духа, вам потрібно буде пройти наше випробування.\n\nЙого можна знайти в південній частині Місячної Галявини, на південь від мостів-близнюків.", [3] = "Знайдіть Аватара Сейлінан у південній частині Мунглейду та дізнайтеся, що він може вам розповісти про природу вітряного кота.", ["en"] = "The Great Windborne Cat Spirit" },
    [98372] = { [1] = "Нещасливий кінець", [5] = "Мертвий вартовий Нічної Варти перед вами вкритий глибокими ранами й порізами. Вочевидь, його розшматував якийсь великий звір.\n\nВи помічаєте в руці трупа незапалений смолоскип. Нахиляєтеся й вивільняєте його із закляклих пальців. Він може стати в пригоді під час мандрів Смерколіссям та іншими землями, освітлюючи те, що ховається в темряві.", ["en"] = "An Unfortunate End" },
    [98386] = { [1] = "Лісопильня Альтера", [2] = "Орки, гноли, мурлоки. Здається, все завадило мені вчасно побудувати цей міст. Тепер нам з'явилася інформація, що на нашій лісопилці нашестя тарантулів!\n\nЯкщо хочеш заробити трохи більше грошей, чи не міг би ти піти до Альтерс-Мілл на сході та вирішити там проблему з павуками? Це місце для мене практично ні на що не здатне, якщо я не можу безпечно відправити робітників збирати вантажі.\n\nО, і якщо побачиш старого Альтера, скажи йому, що він винен мені за те, що я прибрав свій безлад.", [3] = "Убийте 12 великих тарантулів та знищіть 6 яєць тарантула на млині Альтера для бригадира Ослоу в Редріджі.\n\n(1)\n\nЯйце тарантула знищено (6)", ["en"] = "Alther's Mill", ["tasks"] = { ["Greater Tarantula"] = "Великий тарантул", ["Greater Tarantula slain (12) Greater Tarantula"] = "Вбито великого тарантула (12) Великий тарантул" } },
    [98387] = { [1] = "Блокада Чорної Скелі", [2] = "Орки Чорної Скелі не розуміють, що це війна на виснаження. Їхній зухвалий наступ на територію Альянсу залишив їх вразливими та без постачання, вони покладаються на навколишні гори для збору ресурсів.\n\nАрмія не може бігти на порожні шлунки, {ім'я}. Ідіть до їхніх таборів на південь від фортеці Кам'яна Варта на сході та позбавте їх їжі та зброї. Подивимося на бойовий дух орків, коли вони голодні та беззахисні.", [3] = "Принесіть 10 бойових сокир маршалу Маррісу в Лейкшир.", [4] = "Більшість того, що ти знайдеш, вони все одно награбували в Приозер’ї. Приємно знати, що наші люди процвітатимуть, поки орки хирітимуть.", [5] = "Чудова робота, {ім'я:к}. Відрізані від союзників у Палаючому степу, орки Чорної гори не матимуть жодного шансу втримати тут свої позиції без належного постачання.", ["en"] = "Blackrock Blockade", ["tasks"] = { ["10/10 Blackrock Supplies"] = "10/10 припасів Чорної гори", ["Stolen Supplies"] = "Крадені припаси", ["Stolen Weapon"] = "Викрадена зброя" } },
    [984] = { [1] = "Наскільки велика загроза?", [2] = "Деякі з моїх побратимів врятувались від осквернених хутропузів на Тельдрассілі і я поклявся припинити ці звірства, перш ніж ще більше наших побратимів постраждає.\n\nЯ вже бачив сліди присутності порчі на Темнобережжі, але ще не знайшов якихось масштабних ознак. Гадаю, варто продовжити дослідження хутропузів. Чи не {стать:міг би:могла б} ти знайти один з їхніх таборів і повідомити мені, якщо побачиш сліди порчі?", [3] = "Знайдіть осквернений табір хутропузів на Темнобережжі та поверніться до Терентіса в Аубердін.", [4] = "Як просуваються твої пошуки, {ім'я}?", [5] = "Це дійсно жахливі новини, {ім'я}.\n\nХутропузи знаходяться занадто близько до Аубердіна, тож нам доведеться підготуватися до неминучого.\n\nДякую тобі, {ім'я}.", ["en"] = "How Big a Threat?", ["tasks"] = { ["Explore Zone"] = "Дослідіть місцевість", ["Find a corrupt furbolg camp"] = "Знайдіть корумпований табір фурболгів" } },
    [98403] = { [1] = "Викривлена ненависть", [2] = "Лорд Меленас діяв не один; він діяв за наказом іншого. Той, кого ви шукаєте, — це Ксеторр Злий. Схоже, він спотворив павуків, які називають Тельдрассіл своїм домом, використовуючи їхню отруту для якогось підступного плану.\n\nВін оселився глибоко в лісі, в місцевості на північний захід від цього місця, відомій як Розколина. Будьте обережні та беріть із собою союзників, бо Ксеторр — не той супротивник, з яким можна жартувати.\n\nВідправте його виводок і принесіть мені все, що може розповісти нам більше про роботу сатира тут.", [3] = "Убийте 8 осквернених Павутинників та принесіть зрілий Скверновий Мох Ксетхорра Злого до Таллонкаї Швидкокореневої в Доланаарі.", ["en"] = "Twisted Hatred", ["tasks"] = { ["Befouled Webwood slain"] = "Забруднений Павутин: убито", ["Mature Fel Moss"] = "Зрілий мох Скверни" } },
    [98404] = { [1] = "Великий Вітряний Котячий Дух", [2] = "Щоб залучити мій дух, тобі потрібно буде пройти стежкою. Щоб зрозуміти та поважати мою форму, ти повинен довести, що можеш втілювати хитрість, скритність, а якщо тебе заганять у кут, то й лютість.\n\nУ Курганних Лігвах, на схід від цього місця, ти повинен здобути три реліквії. Їх охороняють могутні розлючені духи, які нападуть на тебе одразу. Статуя біля входу благословить тебе тимчасовою скритністю, щоб ти міг пройти повз них.\n\nПоверни мені ці реліквії, щоб пройти випробування друїдів у цих землях.", [3] = "Знайдіть Реліквію Ікла, Реліквію Кігтя та Реліквію Мовчазної Тіні з Кургану Буревісника та поверніть їх Аватарові Сейлінан.", ["en"] = "The Great Windborne Cat Spirit", ["tasks"] = { ["Relic of the Claw"] = "Реліквія Кігтя", ["Relic of the Fang"] = "Реліквія Ікла", ["Relic of the Silent Shadow"] = "Реліквія Мовчазної Тіні" } },
    [98407] = { [1] = "Демонстрація сили", [2] = "Якщо гноли стають настільки сміливими, що готові розбити табір так близько до людей, невідомо, як далеко вони зайдуть. Нам потрібно їх стримувати.\n\nЦі звірі навряд чи організовані, але, здається, вони понад усе поважають силу. Якщо ми зможемо вбити найгірших з них, можливо, забрати деякі з їхніх трофеїв, ми зможемо нагадати цим гнолам, чому вони повинні залишатися в пагорбах, де їм і місце.\n\nЯкщо ви побачите когось із їхніх лихоманок, принесіть мені їхні нашийники. Це має повернути їм страх перед Альянсом.", [3] = "Зберіть 5 шипастих нашийників із багрянокряжових молотильників для заступника Фелдона біля Приозер'я.", [4] = "Повна оцінка загрози ґнолів неможлива без сутички з найгіршими з них. Поклади край цим громилам!", [5] = "Оце ж ти їх набрав.\r\n\r\nХоч це й не розв'язує нашої проблеми повністю, тепер я можу спати спокійніше, знаючи, що ми відбили в них бажання просуватися далі. Чудова робота, Darrin.", ["en"] = "Show of Force", ["tasks"] = { ["Spiked Collar"] = "шипастий нашийник" } },
    [98447] = { [1] = "Родина Валор", [2] = "Незважаючи на те, що ви знищили привидів родини Валор, повідомлення про напади не припиняються. Це була гарна авантюра, але, можливо, ми все ж таки не впоралися з їхніми незакінченими справами.\n\nЗ мого дослідження випливає, що вся ця родина зникла одночасно. Яка б травма не спричинила приковування їхніх душ до цього царства, це мало статися одночасно.\n\nНаша єдина підказка — де ви знайшли книгу. Поверніться до Рейвен-Гілл і подивіться, що ви зможете знайти. Можливо, якщо ви принесете їхню зброю, це щось дасть.", [3] = "Знайдіть причину появи привидів родини Валор на Рейвен-Гілл для Сірри Вон'Інді в Темноширі.", ["en"] = "The Valor Family", ["tasks"] = { ["Raven Hill investigated"] = "Рейвен Гілл розслідував" } },
    [985] = { [1] = "Наскільки велика загроза?", [2] = "Ти вже {стать:показав:показала} свої здібності в розвідці, {ім'я}. Але чи зможеш ти ще й битись з ворогами?\n\nНе всі шукачі пригод обирають прямий бій, натомість віддаючи перевагу мистецтву спритності й непомітності.\n\nЯкщо ти вважаєш, що впораєшся з цим завданням, то табір хутропузів, що на південь від Аубердіна наразі несе найбільшу загрозу для нас. Там ти знайдеш представників племені Чорнолісних. Вбий 8 слідопитів та 5 вітробаїв і повертайся до мене.", [3] = "Вбийте 8 чорнолісних слідопитів та 5 чорнолісних вітробаїв і поверніться до Терентіса в Аубердін.", [4] = "Не утримуйся від того, що має бути зроблено, дитя. Я знаю, наскільки неприємно вбивати лісових створінь, але в цьому випадку це необхідно. Ми ще не маємо ліків проти порчі, що охопила ліс, тож ми повинні зробити все можливе, щоб зупинити її, доки їх не знайдуть.", [5] = "Змий кров зі своїх обладунків, {ім'я}, і не сумуй через скоєне. Натомість подякуй долі. Ти {стать:стримав:стримала} загрозу нашому народу тут, в Аубердіні, навіть якщо Темнобережжя все ще в небезпеці через вплив моху скверни.", ["en"] = "How Big a Threat?", ["tasks"] = { ["Blackwood Pathfinder"] = "чорнолісний слідопит", ["Blackwood Pathfinder slain"] = "чорнолісний слідопит: убито", ["Blackwood Windtalker"] = "чорнолісний вітробай", ["Blackwood Windtalker slain"] = "чорнолісний вітробай: убито" } },
    [98512] = { [1] = "Вбивці Аль'Акета", [2] = "Ти там, незнайомцю. Тихо та спокійно. Ми тут не самі.\n\nЯ патрулював біля кордону і помітив, що навколо будинку, трохи вище за пагорб, на півночі, ховається кілька Аль'Акетів. Я не знаю, що вони тут роблять, але це не може бути добре.\n\nЯкщо хочеш бути корисним, заходь туди та знищ їх. Я чекатиму тут і прикриватиму тебе.", [3] = "Убийте 10 асасинів Ал'Акет у Шен'дарському нагір'ї.", ["en"] = "Al'Aketh Assassins", ["tasks"] = { ["Al'Aketh Assassin"] = "Асасин Аль'Акет", ["Al'Aketh Assassin (Provided)"] = "Асасин Аль'Акет (видано)", ["Al'Aketh Assassin slain"] = "Асасин Аль'Акет: убито" } },
    [986] = { [1] = "Зниклий господар", [2] = "{ім'я}, твоя майстерність неймовірно виручила мене. Чи можу я попросити тебе про допомогу Хмуропазуру та його господареві Волкору? Я можу виготовити для тебе магічний плащ, який дозволить тобі безперешкодно пересуватися по Темнобережжю, поки ти шукатимеш Волкора.\n\nДля створення плаща мені знадобляться п'ять чудових шкур місяцескрадів, знятих з дорослих осіб або матріархів. Цих кішок можна знайти біля Дикогнутої ріки на півдні, або ще далі, біля Ясенедолу.", [3] = "Принесіть 5 чудових шкур місяцескрадів Терентісу в Аубердін.", [4] = "Я в жодному разі не можу дозволити тобі шукати Волкора, поки не зроблю для тебе плащ.", [5] = "Так, вони чудово підійдуть, {ім'я}. Я негайно візьмуся за пошиття плаща.\n\nДай мені кілька хвилин, а потім повертайся.\n\nІ ще дещо: після того, як скористаєшся чарами плаща, ти будеш {стать:обмежений:обмежена} у взаємодії з іншими. Якщо можеш — не розмовляй ні з ким, це може розвіяти ілюзію.", ["en"] = "A Lost Master", ["tasks"] = { ["Fine Moonstalker Pelt"] = "чудова шкура місяцескрада", ["Fine Moonstalker Pelt (Provided)"] = "чудова шкура місяцескрада (видано)" } },
    [987] = { [1] = "<UNUSED>", ["en"] = "<UNUSED>" },
    [98738] = { [1] = "Благословення Великого Вітряного Котячого Духа", [2] = "Тепер, коли ти отримав моє благословення, повертайся до Дендріта. Він навчить тебе далі.\n\nНа жаль, мені поки що мало що залишилося, щоб навчити тебе. Я дуже сподіваюся, що ти колись знову приїдеш до мене в Зефрасі. Я відчуваю в тобі багатообіцяючість, юний шен'дорей.\n\nНехай тіні назавжди приховують тебе, твої вороги легко стають жертвами твоїх кігтів, а вітри скеровують твої кроки.", ["en"] = "Blessings of the Great Windborne Cat Spirit" },
    [98815] = { [1] = "Шкури нагір'я", [2] = "У нагір'ї є якісь руїни, таємниці яких зараз досліджує експедиція. Знаю лише, що в тих гірських болотах водяться особливі дикі звірі. Як щодо вилазки туди з кількома добре спорядженими друзями? А ми влаштуємо обмін.\n\nБайдуже, де вони ховаються, — мені потрібні їхні шкури! Принеси шкури чотирьох хащових рапторів, а я підберу для тебе щось варте зусиль.", [3] = "Принесіть 4 шкури хащових рапторів шкіряному майстру Джеймсу Галлорану в гавань Менетілів.", ["en"] = "Highland Hides", ["tasks"] = { ["Thicket Raptor Hide"] = "Шкура хащового раптора" } },
    [98901] = { [1] = "Битва за острови Темного Списа", [2] = "Боротьба проти рейдерів Темного Списа загострюється. Без негайної допомоги ми втратимо острови Темного Списа.\n\nТвій обов'язок як гордого представника Альянсу — не допустити цього. Принеси докази своїх звершень на передовій, і тебе шануватимуть як героя Альянсу!", ["en"] = "Darkspear Islands Clash", ["tasks"] = { ["Darkspear Islands Mark of Honor"] = "Знак честі Островів Темносписа" } },
    [98977] = { [1] = "Мосхарт Старший", ["en"] = "Mossheart the Elder" },
    [98983] = { [1] = "Морозний Лист Старший", ["en"] = "Frostleaf the Elder" },
    [990] = { [1] = "Подорож до Ясенедолу", [2] = "{ім'я}, моя господиня, Рене Вовкогін, чекає на тебе у місті Астранаар, що в Ясенедолі. Можливо, з твоєю допомогою ми зможемо зупинити спотворення, яке там вкоренилося.\n\nЗвідси прямуй на південь і тримайся ближче до дороги. Тоді ти легко знайдеш шлях до міста.", [3] = "Знайдіть Рене Вовкогін в Ясенедолі.", [5] = "А, {клас} з Темнобережжя. Добре, що Селарін відправила тебе сюди так швидко, {ім'я}. Шкода, що твоя подорож сюди — жахлива необхідність. Можливо, з твоєю допомогою ми зможемо покращити наші справи.\n\nДля початку, поговори з іншими жителями Астранаару. Комусь з них потрібна твоя допомога.", ["en"] = "Trek to Ashenvale" },
    [991] = { [1] = "Очищення Рене", [2] = "{ім'я}, мій давній друг також допомагає стражам тут, в Ясенедолі, але він ще не повернувся.\n\nУ нього були зачіпки щодо місця знаходження однієї речі. На його думку, вона може сповільнити напади хутропузів. Ця річ — жезл, створений нині мертвим злим чарівником.\n\nПеред тим, як піти, він згадував, що шукає самоцвіт для жезла.\n\nВін казав, що цей камінь може бути захований у святилищі на озері Фалатім біля підніжжя гори на заході. Самоцвіт зберігався там до захоплення місцини.\n\nЗнайди мого друга, {ім'я}.", [3] = "Знайдіть Тероніса в Ясенедолі.", [5] = "Понівечене тіло Тероніса лежить на острові. Мурлоки чомусь не стали чіпати мертвого.\n\nГлибокі рани на тілі було нанесено зброєю та пазурами мурлоків.", ["en"] = "Raene's Cleansing" },
    [99145] = { [1] = "Подарунок Зимового Покрову", ["en"] = "A Winter Veil Gift" },
    [992] = { [1] = "Дослідження Пристробляхводоканалу", [2] = "У нас, у Пристробляхводоканалі, є відкрита вакансія молодшого землеміра. Якщо тобі цікаво.\n\nЗараз, коли кочівники захопили всі наші свердловини, нам потрібно знайти інші джерела води! У пустелі є вода, треба тільки її відшукати першими.\n\nВізьми цей пристрій для пошуку води та принеси мені пробу з водойми поблизу Варти Зажурених Пісків. Це прямо під носом у тролів. Поверни прилад, коли закінчиш!", [3] = "Використовуйте пристрій для пошуку води у водоймі біля Варти Зажурених Пісків. Після того, як ви зберете зразок, поверніть використаний пристрій для пошуку води старшому землеміру Шипохіднику в Пристроблях.", [4] = "С поверненням, {стать:молодший землеміре:молодша землемірко} {ім'я}! Ти вже {стать:виконав:виконала} своє завдання?", [5] = "Що таке? На тебе напали якісь мерзенні повзкі тварюки? Це поганий знак для Пристробляхводоканалу, дуже поганий...\n\nМожливо, я мав попередити щодо божевільних комах, які, здається, висмоктують всю воду в пустелі. Спочатку я думав, що це просто вигадки. Нам вистачає проблем з кочівниками, і я подумав, що це просто їхні витівки. Ну, тепер ми, принаймні, знаємо, що це правда!", ["en"] = "Gadgetzan Water Survey", ["tasks"] = { ["Tapped Dowsing Widget"] = "використаний пристрій для пошуку води", ["Tapped Dowsing Widget (Provided)"] = "використаний пристрій для пошуку води (видано)" } },
    [993] = { [1] = "Зниклий господар", [2] = "Плащ готовий, {ім'я}. Настав час знайти Волкора. Сподіваюся, ми встигнемо.\n\nМагія плаща після використання діятиме недовго, приблизно п'ять хвилин. {стать:Сам:Сама} вирішуй, коли його використати, та я б порадив зачекати, доки не знайдеш Хмуропазура.\n\nЯкщо те, що він сказав мені, правда, то ти знайдеш його господаря в печері на південь звідси. Хмуропазур чекатиме на тебе біля дороги. Помахай йому, щоб привернути його увагу, і він покаже тобі шлях до свого господаря.", [3] = "Знайдіть Волкора на Темнобережжі та віддайте йому зачарований плащ місяцескрада.", [5] = "Чудово! Терентіс знайшов того, хто мені допоможе.\n\nІ поглянь-но, плащ місяцескрада...<кашляє> Ох... боляче. Дякую, {ім'я}.\n\nХутропузи поранили мене, перш ніж я зумів від них втекти. Дай мені ще хвилинку, і я зможу говорити далі.", ["en"] = "A Lost Master", ["tasks"] = { ["Enchanted Moonstalker Cloak"] = "зачарований плащ місяцескрада", ["Enchanted Moonstalker Cloak (Provided)"] = "зачарований плащ місяцескрада (видано)" } },
    [994] = { [1] = "Втеча з боєм", [2] = "Гаразд, {ім'я}, ми прорвемось з боєм. Виходимо, коли ти будеш {стать:готовий:готова}. Доберемось до дороги — Хмуропазур все ще має бути там. Там і розійдемося.\n\nТерентіс захоче поговорити з тобою, тож вирушай до Аубердіна, щойно ми виберемося звідси.", [3] = "Захищайте Волкора, поки не дійдете до дороги, після чого поговоріть з Терентісом в Аубердіні.", [5] = "{ім'я}! Радий, що ти успішно {стать:повернувся:повернулась}. Твоя допомога Волкору укріпила мою віру в те, що ми зможемо подолати всі труднощі — як на Темнобережжі, так і за його межами.", ["en"] = "Escape Through Force", ["tasks"] = { ["Help Volcor to the road"] = "Допоможіть Волкору в дорогу" } },
    [995] = { [1] = "Непомітна втеча", [2] = "Гаразд... якщо ти {стать:впевнений:впевнена}, ми спробуємо непомітно вислизнути звідси. Виходимо, коли ти будеш {стать:готовий:готова}.\n\nНе забудь після втечі зустрітись з Терентісом в Аубердіні. Я піду туди самотужки, бо, мабуть, буду рухатися швидше.", [3] = "Втечіть з печери хутропузів та зустріньтесь з Терентісом в Аубердіні.", [4] = "Так, {ім'я}?", [5] = "{ім'я}! Радий, що ти успішно {стать:повернувся:повернулась}. Твоя допомога Волкору укріпила мою віру в те, що ми зможемо подолати всі труднощі — як на Темнобережжі, так і за його межами.", ["en"] = "Escape Through Stealth", ["tasks"] = { ["Help Volcor escape the cave"] = "Допоможіть Волкору вибратися з печери" } },
    [996] = { [1] = "Осквернений вітроцвіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на вітроцвіт. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите дві порції кенарійського бальзаму зцілення рослин на вітроцвіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Windblossom", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [998] = { [1] = "Осквернений вітроцвіт", [4] = "Ви знайшли хвору, осквернену рослину, схожу на вітроцвіт. Ягоди, що висять на ній, тхнуть гниллю. Ця рослина відчайдушно потребує догляду, щоб повернутися до нормального стану.", [5] = "Ви наносите дві порції кенарійського бальзаму зцілення рослин на вітроцвіт. Він миттєво починає змінювати свій вигляд, перетворюючись на живу і здорову рослину.", ["en"] = "Corrupted Windblossom", ["tasks"] = { ["Cenarion Plant Salve"] = "кенарійський бальзам зцілення рослин", ["Cenarion Plant Salve (Provided)"] = "кенарійський бальзам зцілення рослин (видано)" } },
    [999] = { [1] = "Коли сни перетворюються на кошмари", ["en"] = "When Dreams Turn to Nightmares" },
}
addonTable.quest_both = quest_both

